INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, '起初, 神 创造 天 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, '地 是 空虚 混沌,渊面 黑暗; 神 的灵 运行 在 水 面上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, '神 说:「要有 光」,就有了 光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, '神 看 光 是好的, 就把 光 暗 分开 了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, '神 称 光为「昼」,称 暗为「夜」。有 晚上,有 早晨,这是头一 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, '神 说:「诸水 之间 要有 空气,将 水 分为上下。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, '神 就造出 空气,将 空气 以下 的水、空气 以上 的水 分开 了。事就这样 成了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, '神 称 空气为「天」。有 晚上,有 早晨,是第二 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, '神 说:「天 下 的水 要聚 在 一 处,使旱地 露出来。」事就这样 成了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, '神 称 旱地为「地」,称 水 的聚处为「海」。 神 看著 是好的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, '神 说:「地 要发生 青草 和结 种子 的菜蔬,并结 果子 的树木,各从其类,果子 都包著核。」 事就这样 成了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, '于 是地 发生了 青草 和结 种子 的菜蔬,各从其类;并结 果子 的树木,各从其类;果子 都包著核。 神 看著 是好的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, '有 晚上,有 早晨,是第三 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, '神 说:「天上 要有 光体,可以分 昼 夜, 作记号,定节令、日子、年岁, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, '并要 发光 在天 空,普照 在 地上。」事就这样 成了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, '于 是 神 造了 两个 大 光, 大的 管 昼, 小的 管 夜,又造 众星, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, ' 就把这些光 摆列 在天 空,普照 在 地上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, '管理 昼 夜,分别 明 暗。 神 看著 是好的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, '有 晚上,有 早晨,是第四 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, '神 说:「水 要多多滋生 有生命 的物;要有雀鸟 飞 在 地面以上,天 空 之中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, '神 就造出 大 鱼 和 水 中所 滋生 各样 有生命 的动 物,各从其类;又造出 各样 飞 鸟,各从其类。 神 看著 是好的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, '神 就赐福给这一切,说:「滋生 繁多,充满 海中 的水;雀鸟 也要多生 在地上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, '有 晚上,有 早晨,是第五 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, '神 说:「地 要生出 活 物来,各从其类;牲畜、昆虫、野兽,各从其类。」事就这样 成了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, '于 是 神 造出 野兽,各从其类; 牲畜,各从其类; 地上 一切 昆虫,各从其类。 神 看著 是好的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, '神 说:「我们要照著我们的形像、按著我们的样式 造 人,使他们管理 海 里的鱼、空 中的鸟、地上的牲畜,和全 地,并地上 所爬的 一切 昆虫。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, '神 就照著自己的形像 造 人,乃是照著他 的形像 造 男 造 女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, '神 就赐福 给他们, 又对他们 说:「要生养 众多,遍满 地面,治理这地,也要管理 海 里的鱼、空 中的鸟,和地上 各样 行动的 活物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, '神 说:「看哪,我将 遍 地 上 一切 结 种子 的菜蔬 和 一切 树 上 所 结 有核 的果子 全赐 给你们 作 食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, '至于  地上 的走兽和 空中 的飞鸟,并各样 爬 在 地上有 生命 的物,我将 青 草 赐给牠们作食物。」事就这样 成了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, '神 看著 一切 所 造的 都甚 好。有 晚上,有 早晨,是第六 日。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, '天 地 万物 都 造齐了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, '到第七 日, 神 造物 的工 已经完毕,就在第七 日 歇了他一切 的工,安息了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, '神 赐福 给 第七 日,定为圣日;因为 在这日, 神 歇了他一切 创 造 的工,就安息了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, '创造 天 地 的来历,在耶和华 神 造 天 地 的日子,乃是这样, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, '野地 还没 有 草木,田间的 菜蔬 还没有 长起来;因为 耶和华 神 还没有 降雨 在 地上,也没有 人 耕 地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, '但有雾气 从 地 上腾,滋润 遍 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, '耶和华 神 用 地上 的尘土 造 人,将生 气 吹 在他鼻孔里,他就成了 有灵的 活人,名叫亚当。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, '耶和华 神 在东方的 伊甸 立了 一个园子,把 所 造 的人 安置 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, '耶和华 神 使 各样 的树 从 地里 长出来,可以悦人 的眼目,其上的果子好 作食物。园子 当中 又有生命 树 和分别 善 恶 的树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, '有河 从伊甸 流出来,滋润 那园子,从那里 分 为 四 道: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, '第一 道名叫 比逊,就是 环绕 哈腓拉 全 地的。 在那里 有金子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, '并且那 地 的金子 是好的;在那里 又有珍珠 和红玛瑙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, '第二 道河 名 叫基训,就是 环绕 古实 全 地的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, '第三 道河 名叫 底格里斯, 流 在亚述 的东边。第四 道河 就是 幼发拉底河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, '耶和华 神 将 那人 安置 在伊甸 园,使他修理,看守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, '耶和华 神 吩咐 他 说:「园中 各样 树上的果子,你可以随意 吃, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, '只是分别 善 恶 树上的果子,你不可 吃,因为 你吃 的日子 必定 死!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, '耶和华 神 说:「那人 独居 不 好,我要为他 造 一个配偶 帮助他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, '耶和华 神 用 土 所造成的 野地 各样 走兽 和 空中 各样 飞鸟 都带 到 那人面前,看 他叫 什么。那人 怎样 叫 各样的 活 物,那就是 牠的名字。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, '那人 便给一切 牲畜 和空中 飞鸟、野地 走兽 都 起了 名;只是那人 没有 遇见 配偶 帮助他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, '耶和华 神 使 他 沉睡,他就睡了;于 是取下 他的一 条肋骨,又把肉 合起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, '耶和华 神 就用 那人 身上所 取的 肋骨 造成 一个女人,领她 到 那人跟前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, '那人 说:这是 我骨中 的骨,肉中 的肉,可以称 她为「女人」,因为 她是从「男人」身上取出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, '因此,人 要离开  父 母,与妻子 连合,二人成为 一 体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, '当时 夫 妻 二人 赤身露体,并不 羞耻。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, '耶和华 神 所 造的,惟有 蛇 比田野 一切的 活物 更狡猾。蛇对 女人 说:「 神 岂是 真 说 不许 你们吃 园中 所有 树上的果子吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, '女人 对 蛇 说:「园中 树上 的果子,我们可以吃, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, '惟有 园 当中 那棵树 上的果子, 神 曾说:『你们不可 吃,也不可 摸,免得 你们死。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, '蛇 对 女人 说:「你们不 一定 死; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, '因为 神 知道, 你们吃 的日子 眼睛 就明亮了,你们便如 神 能知道 善 恶。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, '于 是女人 见 那棵树 的果子好 作食物, 也 悦人 的眼目,且 是可喜爱的,能使人有智慧,就摘下 果子 来吃了,又 给 她丈夫,她丈夫也 吃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, '他们二人 的眼睛 就明亮了,才知道 自己是 赤身露体,便拿无花果树 的叶子 为自己 编 做 裙子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, '天 起了凉风,耶和华 神 在园中 行走。那人 和他妻子 听见 神 的声音,就藏 在园里 的树木中,躲避耶和华 神 的面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, '耶和华 神 呼唤 那人,对他 说:「你在哪里?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, '他说:「我在园中 听见 你的声音,我就害怕;因为 我 赤身露体,我便藏了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, '耶和华说:「谁 告诉 你 赤身露体呢?莫非你吃了 我吩咐你 不可 吃的那 树上的果子吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, '那人 说:「你所 赐给我、与我 同居的女人,她 把那树上的果子 给 我,我就吃了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, '耶和华 神 对女人 说:「你做的 是什么 事呢?」女人 说:「那蛇 引诱我,我就吃了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, '耶和华 神 对 蛇 说:你 既 做了 这事,就必受咒诅,比一切的 牲畜 野 兽更甚;你必用 肚子 行走,终 身 吃 土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, '我又要叫 你 和女人 彼此 为仇;你的后裔和 女人的后裔 也彼此为仇。女人的后裔要 伤 你的头;你要 伤 他的脚跟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, '又对 女人 说:我必多多 加增 你怀胎 的苦楚;你生产 儿女 必多受苦楚。你必恋慕 你丈夫;你丈夫必 管辖 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, '又对亚当 说:你既 听从 妻子 的话,吃了 我所 吩咐你 不可 吃的 那树上的果子,地 必为你的缘故 受咒诅;你必终 身 劳苦 才能从地里得吃的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, '地必给你 长出 荆棘 和蒺藜来;你也要吃 田间 的菜蔬。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, '你必汗流 满面 才得糊口,直到 你归了 土,因为 你是从 土而出的。你 本是 尘土,仍要归 于  尘土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, '亚当 给他妻子 起 名 叫夏娃,因为 她 是 众 生 之母。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, '耶和华 神 为亚当 和他妻子 用皮子 做 衣服 给他们穿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, '耶和华 神 说:「 那人 已经 与我们 相似,能知道 善 恶;现在 恐怕 他伸 手 又 摘 生命 树的果子 吃,就永远 活著。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, '耶和华 神 便打发 他出伊甸 园去,耕种 他所 自出 之土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, '于 是把 他 赶出去了;又在伊甸 园的 东边 安设 基路伯 和 四面转动 发火焰 的剑,要把守 生命 树 的道路。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, '有一日,那人 和 他妻子 夏娃 同房,夏娃就怀孕,生了 该隐(就是得的意思),便说:「 耶和华 使我得了 一个男子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, '又 生了 该隐的兄弟 亚伯。亚伯 是 牧 羊的;该隐 是 种 地的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, '有 一日,该隐 拿 地 里的出产 为供物 献给耶和华; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, '亚伯 也 将他 羊群 中头生的 和羊的脂油 献上。耶和华 看中了 亚伯和 他的供物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, '只是看 不中 该隐和 他的供物。该隐 就大大地 发怒,变了 脸色。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, '耶和华 对 该隐 说:「你 为什么 发怒呢?你为什么 变了 脸色呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, '你若 行得好,岂不 蒙悦纳?你若 行得不 好,罪 就伏 在 门前。它必恋慕你,你 却要制伏 它。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, '该隐 与 他兄弟 亚伯 说话; 二人正 在田间。该隐 起来 打 他兄弟 亚伯,把他杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, '耶和华 对 该隐 说:「你兄弟 亚伯 在哪里?」他说:「我不 知道!我 岂是看守 我兄弟的吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, '耶和华说:「你做了 什么事呢?你兄弟 的血 有声音 从 地 里向我 哀告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, '地 开 了 口,从你手里 接受 你兄弟 的血。现在 你必 从 这地 受咒诅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, ' 你种 地,地不 再 给 你 效力;你必 流离 飘荡 在地上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, '该隐 对 耶和华 说:「我的刑罚 太重,过于 我所能当的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, ' 你如今 赶逐 我 离开  这地,以致不见 你面;我必 流离 飘荡 在地上,凡 遇见我的 必 杀我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, '耶和华 对他 说:「 凡 杀 该隐的,必遭报 七倍。」耶和华 就给该隐 立 一个记号,免得 人 遇见他 就杀 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, '于 是该隐 离开  耶和华 的面,去住 在伊甸 东边 挪得 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, '该隐 与 妻子 同房,他妻子就怀孕,生了 以诺。 该隐建造了 一座城,就按著他儿子 的名 将那城 叫做 以诺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, '以诺 生 以拿;以拿 生 米户雅利;米户雅利 生 玛土撒利;玛土撒利 生 拉麦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, '拉麦 娶了 两个 妻:一个 名叫 亚大,一个 名叫 洗拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, '亚大 生 雅八;雅八 就是 住 帐棚、牧养牲畜 之人的祖师。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, '雅八的兄弟 名叫 犹八;他 是 一切 弹 琴 吹箫 之人的祖师。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, '洗拉 又 生了土八‧该隐;他是打造 各样 铜 铁 利器的(或译:是铜匠铁匠的祖师)。土八‧该隐 的妹子 是拿玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, '拉麦 对他两个妻子 说:亚大、洗拉,听 我的声音;拉麦 的妻子,细听 我的话语: 壮年人 伤我,我把他杀了;少年人 损我,我把他害了(或译:我杀壮士却伤自己,我害幼童却损本身)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, '若 杀该隐,遭报 七倍,杀拉麦,必遭报七十 七倍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, '亚当 又 与 妻子 同房,她就生了 一个儿子,起 名 叫塞特,意思说:「 神 另 给我 立了 一个儿子 代替 亚伯,因为 该隐 杀了他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, '塞特 也 生了 一个儿子,起 名 叫以挪士。那时候,人才 求告 耶和华 的名。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, '亚当 的后代 记在 下面。(当 神 造 人 的日子,是照著 自己的 样式 造的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, '并且造 男 造女。在他们被造 的日子, 神赐福 给他们,称 他们为「人」。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, '亚当 活到 一百 三十 岁,生了一个儿子,形像 样式和自己相似,就给他起 名 叫塞特。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, '亚当 生 塞特 之后,又在 世 八 百 年,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, ' 亚当 共 活了 九 百 三十 岁 就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, '塞特 活到 一百 零五 岁,生了 以挪士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, '塞特 生 以挪士 之后,又活了 八 百 零七 年,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, ' 塞特 共 活了九 百 一十二 岁 就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, '以挪士 活到 九十 岁,生了 该南。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, '以挪士 生 该南 之后,又活了 八 百 一十五 年,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, ' 以挪士 共 活了九 百 零五 岁 就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, '该南 活到 七十 岁,生了 玛勒列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, '该南 生 玛勒列 之后,又活了 八 百 四十 年,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, ' 该南 共 活了九 百 一十 岁 就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, '玛勒列 活到 六十 五 岁,生了 雅列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, '玛勒列 生 雅列 之后,又活了 八 百 三十 年,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, ' 玛勒列 共 活了八 百 九十 五 岁 就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, '雅列 活到 一百 六十 二 岁,生了 以诺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, '雅列 生 以诺 之后,又活了 八 百 年,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, ' 雅列 共 活了九 百 六十 二 岁 就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, '以诺 活到 六十 五 岁,生了 玛土撒拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, '以诺 生 玛土撒拉 之后,与 神 同行 三 百 年,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, ' 以诺 共 活了三 百 六十 五 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, '以诺 与 神 同行, 神 将他 取去,他就不在世了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, '玛土撒拉 活到 一百 八十 七 岁,生了 拉麦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, '玛土撒拉 生 拉麦 之后,又活了 七 百 八十 二 年,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, ' 玛土撒拉 共 活了九 百 六十 九 岁 就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, '拉麦 活到 一百 八十 二 岁,生了 一个儿子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, '给他起 名 叫挪亚,说:「这个 儿子必为我们的操作 和手中 的劳苦 安慰我们;这操作劳苦是因为 耶和华 咒诅 地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, '拉麦 生 挪亚 之后,又活了 五 百 九十 五 年,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, ' 拉麦 共 活了七 百 七十 七 岁 就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, ' 挪亚 五 百 岁 生了 闪、 含、 雅弗。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, ' 当 人 在 世上 多起来、又生 女儿的时候, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, '神 的儿子们 看见 人 的女子 美貌,就随意 挑选,娶来 为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, '耶和华 说:「人 既 属乎血气,我的灵 就不 永远 住 在他里面;然而他的日子 还可到 一百 二十 年。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, '那 时候 有 伟人 在地上, 后来 神 的儿子们 和 人 的女子们 交合 生子;那 就是 上古 英武 有名的 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, '耶和华 见 人 在地上 罪恶 很大,终 日 所思 想的 尽 都 是恶, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, '耶和华 就后悔 造 人 在地上,心中 忧伤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, '耶和华 说:「我要将 所 造的 人 和 走兽,并 昆虫,以及 空中的 飞鸟,都从 地上 除灭,因为 我造他们 后悔了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, '惟有挪亚 在耶和华 眼前 蒙 恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, '挪亚的后代 记在下面。挪亚 是 个义 人,在当时的世代 是个完全人。挪亚 与 神 同行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, '挪亚 生了 三个 儿子,就是 闪、 含、 雅弗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, '世界在 神 面前 败坏,地上 满了 强暴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, '神 观看 世界,见 是败坏了; 凡 有血气的 人在 地上 都败坏了 行为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, '神 就对挪亚 说:「凡 有血气的人,他的尽头 已经来到 我面前;因为 地上 满了 他们的 强暴,我 要把他们和 地 一并毁灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, '你 要用歌斐 木 造 一只方舟,分一间一间 地造,里 外 抹上 松香。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, '方舟的 造法 乃是 这样:要长 三 百 肘,宽 五十 肘,高 三十 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, '方舟 上边 要留 透光处,高 一肘。方舟的 门 要开  在旁边。方舟要分 上、中、下三层。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, '看哪,我 要使 洪水 泛滥在 地上,毁灭 天 下;凡 地上 有血肉、 有气息的 活物,无一不死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, '我却要与你 立 约;你 同 你的妻,与儿子 儿 妇,都要进 入 方舟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, '凡 有血肉的 活物,每样 两个, 一公 一母,你要带进 方舟,好在你 那里保全生命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, '飞鸟 各从其类,牲畜 各从其类,地上的 昆虫 各从其类,每样 两个,要到 你那里,好保全生命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, '你 要拿 各样 食物 积蓄起来,好作 你 和牠们 的食物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, '挪亚 就这样行。凡 神 所 吩咐的,他都照样 行了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, '耶和华 对挪亚 说:「你 和你的全 家 都要进 入 方舟;因为 在这 世代中,我见 你 在我面前 是义人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, '凡 洁净的 畜类,你要带 七 公 七 母; 不 洁净的 畜类,你要带一 公 一母; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, '空中 的飞鸟 也 要带七 公 七 母,可以留种,活 在 全 地 上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, '因为 再过 七 天,我要 降雨 在 地上 四十 昼 夜,把 我所 造的 各种 活物 都从 地 上 除灭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, '挪亚 就遵著 耶和华 所 吩咐的 行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, '当 洪 水 泛滥在 地上的时候,挪亚 整六 百 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, '挪亚 就同 他的妻 和儿子 儿妇 都进 入 方舟,躲避 洪水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, '洁净的 畜类和 不 洁净的 畜类,飞鸟 并地上 一切的 昆虫, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, '都是一对 一对地,有公 有母,到 挪亚 那里进 入 方舟,正如 神 所吩咐 挪亚的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, '过了 那七 天,洪水泛滥 在 地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, '当 挪亚 六 百 岁,二 月 十七 日 那 一天,大 渊 的泉源 都 裂开 了,天上的 窗户 也敞开 了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, ' 四十 昼 夜 降大雨 在 地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, '正当 那 日,挪亚 和 他 三个儿子 闪、含、雅弗,并挪亚 的妻子 和三个 儿 妇,都进 入 方舟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, '他们 和百 兽,各从其类,一切 牲畜,各从其类,爬 在 地上的 昆虫,各从其类,一切 禽 鸟,各从其类,都进入方舟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, '凡 有血肉、有气息的 活物,都一对 一对地 到 挪亚那里,进 入 方舟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, '凡 有血肉 进入方舟的,都是 有公 有母,正如 神 所吩咐挪亚的。耶和华 就把他关在 方舟里头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, ' 洪水 泛滥在 地上 四十 天,水 往上长,把 方舟 从 地上 漂 起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, '水势 浩大,在 地上 大大地 往上长,方舟 在 水 面上 漂来漂去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, '水势 在 地上 极其 浩大, 天 下 的 高 山 都 淹没了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, '水 势比 山高过 十五 肘,山岭 都淹没了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, '凡 在 地上 有血肉的 动物,就是飞鸟、牲畜、走兽,和 爬 在 地上的 昆虫,以及所有的 人,都死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, '凡 在旱地上、鼻孔 有气息 的 生灵 都死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, '凡 地 上 各类的 活物,连人 带 牲畜、 昆虫,以及 空中的 飞鸟,都从 地上 除灭了,只 留下 挪亚 和那些 与他 同在方舟里的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, '水 势浩大,在 地上 共一百 五十 天。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, '神 记念 挪亚 和 挪亚 方舟 里的 一切 走兽 牲畜。 神 叫 风 吹 地,水 势渐落。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, '渊 源 和天上的 窗户 都闭塞了,天上的 大雨 也止住了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, '水 从 地上 渐 退。过了 一百 五十 天,水 就渐消。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, '七 月 十 七 日,方舟 停 在 亚拉腊 山上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, '水又 渐 消,到 十 月 初一日,山 顶 都现出来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, ' 过了 四十 天,挪亚 开 了 方舟 的窗户, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, '放出 一只乌鸦去;那乌鸦飞来 飞去,直到 地 上 的水 都干了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, '他又放出 一只鸽子去,要看看 水 从 地 上 退了没有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, '但 遍 地 上 都是水,鸽子 找 不著 落脚 之地,就回 到 方舟 挪亚那里,挪亚伸 手 把鸽子 接 进 方舟来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, '他又 等了 七 天,再 把 鸽子 从 方舟 放出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, '到了晚上,鸽子 回到 他那里, 嘴里 叼著一个新拧下来的 橄榄 叶子,挪亚 就知道 地上 的水 退了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, '他又 等了 七 天,放出 鸽子去,鸽子 就不 再 回来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, '到 挪亚六 百 零一 岁,正 月 初一日,地上的 水 都干了。挪亚 撤去 方舟 的盖 观看,便见 地 面上 干了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, '到了二 月 二十 七 日,地 就都干了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, '神 对 挪亚 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, '「你 和你 的妻子、儿子、儿 妇 都可以出 方舟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, '在你那里 凡 有血肉的活物,就是飞鸟、牲畜,和一切 爬 在 地上 的昆虫,都要带出来,叫牠在地上 多多滋生,大大 兴旺。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, '于 是挪亚 和他 的妻子、儿子、儿 妇 都出来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, '一切 走兽、 昆虫、 飞鸟,和地上 所有的 动物,各从其类,也都出了 方舟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, '挪亚 为耶和华 筑了 一座坛,拿 各类 洁净的 牲畜、 飞鸟 献 在坛上 为燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, '耶和华 闻 那馨香 之气, 就心里 说:「我不 再 因人的 缘故 咒诅 地( 人 从小时 心里 怀著恶 念),也不 再 按著 我才行 的灭 各种的 活物了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, '地 还 存留的时候,稼 穑、寒 暑、冬 夏、昼 夜 就永不 停息了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, '神 赐福 给 挪亚和 他的儿子,对他们 说:「你们要生养 众多,遍满了 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, '凡 地 上 的走兽和 空中 的飞鸟 都必 惊恐,惧怕你们,连地上 一切的 昆虫 并海 里一切的 鱼 都交付 你们的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, '凡 活著 的动物 都可以作 你们的 食物。这 一切 我都赐 给你们,如同菜蔬一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, '惟独 肉 带著血,那就是牠的生命,你们不可 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, ' 流你们血、害你们命的,无论是 兽是 人,我必 讨他的罪,就是 向各人的 弟兄 也是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, '凡流 人 血的,他的血 也必被人 所流,因为 神造 人 是照自己 的形像造的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, '你们 要生养 众多,在地上 昌盛 繁茂。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, '神 晓谕 挪亚和 他的儿子 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, '「 我 与你们 和 你们的 后裔 立 约, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, '并与 你们这里 的 一切 活 物─就是飞鸟、牲畜、 走兽, 凡从 方舟 里出来的 活物─立约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, '我与你们 立 约,凡 有血肉的,不 再 被洪 水 灭绝,也不 再 有 洪水 毁坏 地了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, '神 说:「我 与你们并 你们这里 的 各样 活 物 所 立 的永 约是 有记号的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, '我把 虹 放 在云彩中,这就可作我 与 地 立约 的记号了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, '我使 云彩 盖地的时候,必有 虹 现 在云彩中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, '我便记念 我 与你们和 各样 有血肉的 活 物 所 立的约,水就 再 不 泛滥、毁坏 一切 有血肉的物了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, '虹 必 现在云彩中,我看见,就要记念 我 与地上 各样 有血肉的 活 物 所立的永 约。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, '神 对 挪亚 说:「这就是 我 与 地上 一切 有血肉之物 立 约 的记号了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, '出 方舟 挪亚 的儿子 就是 闪、含、雅弗。含 是 迦南 的父亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, '这是 挪亚 的三 个儿子,他们的后裔 分散 在全 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, '挪亚 作起 农 夫来,栽了 一个葡萄园。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, '他喝了 园中的酒 便醉了,在帐棚 里 赤著身子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, '迦南 的父亲 含 看见 他父亲 赤身,就到外边 告诉 他两个 弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, '于 是闪 和雅弗 拿件 衣服 搭 在 肩上,倒退著 进去,给 他父亲 盖上;他们背著 脸 就看不 见 父亲的 赤身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, '挪亚 醒了 酒,知道 小 儿子 向他 所 做的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, '就说:迦南 当受咒诅,必 给他弟兄 作奴仆 的奴仆; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, '又说:耶和华─闪的 神 是应当称颂的!愿  迦南作闪的 奴仆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, '愿  神 使雅弗 扩张,使他住 在闪 的帐棚里;又愿  迦南 作他的 奴仆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, '洪水 以后,挪亚 又活了 三 百 五十 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, ' 挪亚 共 活了 九 百 五十 岁 就死了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, '挪亚 的儿子 闪、含、雅弗 的后代 记在下面。洪水 以后,他们 都生了 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, '雅弗 的儿子 是歌篾、玛各、玛代、雅完、土巴、米设、提拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, '歌篾 的儿子 是亚实基拿、利法、陀迦玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, '雅完 的儿子 是以利沙、他施、基提、多单。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, '这些人的后裔 将各国 的地土、海岛 分开 居住,各 随各的方言、宗族 立国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, '含 的儿子 是古实、麦西、弗、迦南。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, '古实 的儿子 是西巴、哈腓拉、撒弗他、拉玛、撒弗提迦。拉玛 的儿子 是示巴、底但。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, '古实 又生 宁录,他 为 世上 英雄 之首。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, '他 在耶和华 面前 是 个英勇的 猎户,所以 俗语说:「像宁录 在耶和华 面前 是个英勇的 猎户。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, '他国 的起头 是 巴别、以力、亚甲、甲尼,都在示拿 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, '他从 那 地 出来 往亚述去,建造 尼尼微、 利河伯、 迦拉, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, '和 尼尼微、迦拉 中间的 利鲜,这就是 那大 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, '麦西 生 路低人、 亚拿米人、 利哈比人、 拿弗土希人、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, ' 帕斯鲁细人、 迦斯路希人、 迦斐托 讬人;从 迦斐托 讬 出来 的 有非利士人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, '迦南 生 长子 西顿,又生 赫 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, '和 耶布斯人、 亚摩利人、 革迦撒人、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, ' 希未人、 亚基人、 西尼人、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, ' 亚瓦底人、 洗玛利人、 哈马人,后来 迦南 的诸族 分散了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, '迦南 的境界 是 从西顿 向 基拉耳的路上,直到 迦萨,又向 所多玛、蛾摩拉、押玛、洗扁的路上,直到 拉沙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, '这就是 含 的后裔,各随他们的宗族、方言,所住的地土、邦国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, '雅弗 的哥哥 闪,是 希伯 子孙 之祖,他 也 生了儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, '闪 的儿子 是以拦、亚述、亚法撒、路德、亚兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, '亚兰 的儿子 是乌斯、户勒、基帖、玛施。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, '亚法撒 生 沙拉;沙拉 生 希伯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, '希伯 生了 两个 儿子,一个 名 叫法勒(就是分的意思),因为 那时 人就分 地居住;法勒的兄弟 名 叫约坍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, '约坍 生 亚摩答、 沙列、 哈萨玛非、 耶拉、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, ' 哈多兰、 乌萨、 德拉、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, ' 俄巴路、 亚比玛利、 示巴、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, ' 阿斐、 哈腓拉、 约巴,这 都 是约坍 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, '他们所住的地方 是 从米沙 直到 西发 东边的 山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, '这就是 闪 的子孙,各随他们的宗族、方言,所住的地土、邦国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, '这些 都是挪亚 三个儿子 的宗族,各随他们的支派 立国。 洪水 以后,他们在地上 分为 邦国。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, '那时,天下 人的口音、言语 都是一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, ' 他们往东边 迁移的时候,在示拿 地 遇见 一片平原,就住 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, '他们彼此 商量说:「来吧!我们要做 砖,把砖烧 透了。」他们就拿 砖 当石头,又拿 石漆 当 灰泥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, '他们说:「来吧!我们 要建造 一座城 和一座塔,塔顶 通天,为要传扬 我们的 名,免得 我们分散 在 全 地 上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, '耶和华 降临,要看看 世人 所 建造的 城和 塔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, '耶和华 说:「看哪,他们成为一样的 人民,都是 一样的 言语,如今既做 起 这事来,以后 他们 所 要 做 的事就没有不 成就的了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, '我们下 去,在那里 变乱 他们的口音,使 他们的言语 彼此 不 通。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, '于 是耶和华 使他们 从那里 分散 在 全 地 上;他们就停工,不造 那城了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, '因为 耶和华 在那里 变乱 天下 人的言语, 使众人分散 在 全 地 上,所以 那城名 叫 巴别。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, '闪 的后代 记在下面。洪水 以后 二年,闪 一百 岁 生了 亚法撒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, '闪 生 亚法撒 之后 又活了 五 百 年,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, '亚法撒 活到 三十 五 岁,生了 沙拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, '亚法撒 生 沙拉 之后 又活 了四 百 零三 年,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, '沙拉 活到 三十 岁,生了 希伯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, '沙拉 生 希伯 之后 又活 了四 百 零三 年,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, '希伯 活 到三十 四 岁,生了 法勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, '希伯 生 法勒 之后 又活了 四 百 三十 年,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, '法勒 活 到三十 岁,生了 拉吴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, '法勒 生 拉吴 之后 又活了 二百 零九 年,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, '拉吴 活 到三十 二 岁,生了 西鹿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, '拉吴 生 西鹿 之后 又活了 二百 零七 年,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, '西鹿 活 到三十 岁,生了 拿鹤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, '西鹿 生 拿鹤 之后 又活了 二百 年,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, '拿鹤 活 到二十 九 岁,生了 他拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, '拿鹤 生 他拉 之后 又活了 一百 一十九 年,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, '他拉 活 到七十 岁,生了 亚伯兰、 拿鹤、 哈兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, '他拉 的后代 记在下面。他拉 生 亚伯兰、 拿鹤、 哈兰;哈兰 生 罗得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, '哈兰 死 在他的本 地 迦勒底 的吾珥,在他父亲 他拉 之先。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, '亚伯兰、拿鹤 各 娶了 妻:亚伯兰 的妻子 名 叫撒莱;拿鹤 的妻子 名 叫密迦,是哈兰 的女儿;哈兰 是密迦 和亦迦 的父亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, ' 撒莱 不生育,没有 孩子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, '他拉 带著 他儿子 亚伯兰 和他孙子 哈兰 的儿子 罗得,并他儿妇 亚伯兰 的妻子 撒莱, 出了 迦勒底 的吾珥,要往 迦南 地去;他们走 到 哈兰,就住 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, ' 他拉 共活了 二百 零五 岁,就死 在哈兰。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, '耶和华 对 亚伯兰 说:「你 要离开  本地、本族、父 家,往 我所 要指示你 的地去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, '我必叫你成为 大 国。我必赐福给你,叫 你的名 为大;你也要 叫别人得福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, '为你祝福的,我必赐福与他;那咒诅你的,我必咒诅他。地上 的万 族 都要因你 得福。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, '亚伯兰 就照著 耶和华 的吩咐 去了;罗得 也和他 同去。亚伯兰 出 哈兰 的时候年 七十 五 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, '亚伯兰 将 他妻子 撒莱和 姪儿 罗得,连 他们在哈兰 所 积蓄的 财物、 所 得 的人口,都带 往 迦南 地 去。他们就到了 迦南 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, '亚伯兰 经过 那地,到了 示剑 地方、 摩利 橡树那里。那时 迦南人 住在那地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, '耶和华 向 亚伯兰 显现,说:「我要把 这 地 赐 给你的后裔。」亚伯兰 就在那里 为向他 显现的 耶和华 筑了 一座坛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, '从那里 他又迁 到伯特利 东边 的山,支搭 帐棚;西边 是伯特利,东边 是艾。他在那里 又为耶和华 筑了 一座坛,求告 耶和华 的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, '后来亚伯兰 又渐渐 迁 往 南地去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, '那地 遭遇 饥荒。因 饥荒 甚大,亚伯兰 就下 埃及去,要在那里 暂居。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, ' 将近 埃及,就对 他妻子 撒莱 说:「 我知道 你是 容貌 俊美 的妇人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, ' 埃及人 看见 你 必说:『这是 他的妻子』,他们就要杀 我,却叫你 存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, '求你 说,你是 我的妹子,使 我 因你 得平安,我的命 也因你 存活。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, '及至 亚伯兰 到了 埃及,埃及人 看见 那妇人 极其 美貌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, '法老 的臣宰 看见了 她,就在法老 面前 夸奖 她。那妇人 就被带 进法老 的宫去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, '法老因 这妇人就厚待 亚伯兰,亚伯兰 得了许多牛、羊、骆驼、公驴、母驴、仆 婢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, '耶和华 因 亚伯兰 妻子 撒莱 的缘故,降 大 灾 与 法老 和 他的全家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, '法老 就召了 亚伯兰来,说:「你这 向我 做 的是什么事呢?为什么 没有 告诉 我 她是 你的妻子? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, '为什么 说 她是 你的妹子,以致我把她 取来 要作我的 妻子?现在 你的妻子 在这里,可以带她 走吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, '于 是法老 吩咐 人 将亚伯兰 和 他妻子,并 他 所有的 都 送走了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, '亚伯兰 带著 他的妻子 与罗得,并一切 所有的,都从埃及 上 南地去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, '亚伯兰 的金、银、牲畜 极 多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, '他从 南地渐渐 往 伯特利 去,到了 伯特利 和 艾 的中间,就 是 从前 支搭帐棚 的地方, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, '也是 他起先 筑 坛 的地方;他 又在那里 求告 耶和华 的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, '与 亚伯兰 同行 的罗得 也 有 牛群、羊群、帐棚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, '那地 容 不 下他们;因为 他们的财物 甚多,使他们不 能 同 居。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, '当时,迦南人 与比利洗人 在那地 居住。 亚伯兰 的牧人 和 罗得 的牧人 相争。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, '亚伯兰 就对 罗得 说:「 你我 不可 相争, 你的牧人 和 我的牧人 也不可相争,因为 我们是 骨肉(原文是弟兄)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, '遍 地 不 都在你眼前吗?请 你离开  我: 你向左,我就向右; 你向右,我就向左。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, '罗得 举 目 看见 约旦河 的全 平原,直到 琐珥,都是 滋润的,那地在耶和华 未灭 所多玛、 蛾摩拉 以先 如同耶和华 的园子,也像埃及 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, '于 是罗得 选择 约旦 河的全 平原, 往东 迁移;他们就彼此 分离了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, '亚伯兰 住 在迦南 地,罗得 住 在平原 的城邑,渐渐挪移帐棚,直到 所多玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, '所多玛 人 在耶和华 面前罪 大恶 极。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, '罗得 离别亚伯兰 以后,耶和华 对 亚伯兰 说:「从 你 所 在的 地方,你 举 目 向东 西 南 北 观看; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, '凡 你 所 看见 的 一切 地,我都要赐 给你 和你的后裔,直到 永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, '我也要使 你的后裔 如同地 上的尘沙那样多, 人 若 能 数算 地 上的尘沙 才能 数算 你的后裔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, '你起来,纵 横 走 遍这地,因为 我必把这地赐 给你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, '亚伯兰 就搬了帐棚,来 到希伯仑  幔利 的橡树 那里 居住,在那里 为耶和华 筑 了一座坛。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, ' 当暗拉非 作示拿 王,亚略 作以拉撒 王,基大老玛 作以拦 王,提达 作戈印 王 的时候, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, '他们都攻打 所多玛 王 比拉、 蛾摩拉 王 比沙、押玛 王 示纳、洗扁 王 善以别,和比拉 王;比拉 就是 琐珥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, '这 五王都 在 西订 谷 会合;西订谷就是 盐 海。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, '他们已经事奉 基大老玛 十二 年,到十三 年 就背叛了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, '十四 年,基大老玛和 同盟的王 都来在亚特律‧加宁,杀败了 利乏音人,在哈麦杀败了 苏西人,在沙微‧基列亭杀败了 以米人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, '在何利人 的西珥 山杀败了何利人,一直 杀到靠近 旷野 的伊勒‧巴兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, '他们回 到安‧密巴,就是 加低斯,杀败了 亚玛力 全 地的人,以及 住在哈洗逊‧他玛 的 亚摩利人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, '于 是所多玛 王、蛾摩拉 王、押玛 王、洗扁 王,和比拉 王(比拉 就是 琐珥)都出来,在西订 谷 摆阵,与他们 交战 , ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, '就是与 以拦 王 基大老玛、戈印 王 提达、示拿 王 暗拉非、以拉撒 王 亚略交战 ;乃是四 王 与 五 王交战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, '西订 谷 有许多 石漆 坑。所多玛 王 和蛾摩拉 王 逃跑,有掉在坑里的,其余 馀 的人都往山 上逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, '四王就把 所多玛 和蛾摩拉 所有的 财物,并 一切的 粮食 都掳掠 去了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, '又把 亚伯兰 的姪儿 罗得和 罗得 的财物 掳掠 去了。当时罗得 正住 在所多玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, '有一个逃 出来 的人告诉 希伯来人 亚伯兰;亚伯兰 正住 在亚摩利人 幔利 的橡树那里。幔利和以实各 并亚乃 都是弟兄,曾与 亚伯兰 联盟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, '亚伯兰 听见他姪儿被掳去,就率领 他家 里生 养的精练 壮丁三 百 一十 八人,直追 到 但, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, '便在夜间,自己 同仆人 分队 杀败 敌人,又追 到 大马士革 北边 的 何把, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, '将 被掳掠的一切 财物 夺回来,连 他姪儿 罗得 和他的财物,以及 妇女、 人民也都夺回来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, ' 亚伯兰杀败 基大老玛 和 与他 同盟的 王 回来的时候,所多玛 王 出来,在 沙微 谷 迎接他;沙微谷就是 王 谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, '又有撒冷 王 麦基洗德 带著 饼 和酒出来迎接;他是 至高 神的 祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, '他为亚伯兰祝福,说:「愿 天 地 的主、至高的 神 赐福 与亚伯兰! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, '至高的 神 把敌人 交 在你手里,是应当称颂的!」亚伯兰就把所得的 拿出十分之一来,给 麦基洗德。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, '所多玛 王 对 亚伯兰 说:「你把人口 给 我,财物 你自己 拿去吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, '亚伯兰 对 所多玛 王 说:「我已经向 天 地 的主─至高的 神 耶和华 起誓: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, '凡是 你的 东西,就是 一根线 缐、 一根鞋 带,我都不 拿,免得 你说:『我 使 亚伯兰 富足!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, '只有 仆人 所 吃的,并与我 同行 的 亚乃、以实各、幔利 所应得的分,可以任凭他们 拿 去。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, '这 事 以后,耶和华 在异象 中有 话 对 亚伯兰 说:「亚伯兰,你不要 惧怕!我是 你的 盾牌,必大 大 地赏赐你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, '亚伯兰 说:「主 耶和华啊,我 既 无子,你还赐 我 什么呢?并且要承受 我家 业的 是 大马士革人 以利以谢。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, '亚伯兰 又说:「 你没有 给 我 儿子; 那生在我家 中的人 就是我的 后嗣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, ' 耶和华 又有话 对他 说:「这人 必不 成为你的后嗣;你本身 所 生 的才 成为 你的后嗣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, '于 是领他 走 到外边,说:「 你向天 观看,数算 众星, 能 数得过来吗?」又对他 说:「你的后裔 将要 如此。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, '亚伯兰信 耶和华,耶和华就以此为 他的 义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, '耶和华又对他 说:「我是 耶和华, 曾领你 出了迦勒底 的吾珥,为要将 这地 赐 你 为业。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, '亚伯兰说:「主 耶和华啊,我怎能 知道 必 得这地为业呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, '他说:「你为我 取 一只三年的 母牛,一只三年的 母山羊,一只三年的 公绵羊,一只斑鸠,一只雏鸽。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, '亚伯兰 就取了 这些来,每样 劈开 ,分成两半,一 半 对著 一半 地摆列,只有 鸟 没有 劈开 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, '有鸷鸟 下来,落在 那死畜的肉上,亚伯兰 就把牠 吓飞了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, ' 日头 正落的时候, 亚伯兰 沉沉地睡了;忽然 有惊人 的大 黑暗 落 在他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, '耶和华对亚伯兰 说:「你要的确 知道, 你的后裔 必 寄居 别人的 地,又服事那地的人;那地的人要苦待 他们 四 百 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, '并且 他们所 要服事 的 那国,我要 惩罚,后来 他们必带著许多 财物 从那里出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, '但你 要享大 寿数,平平安安地 归 到 你列祖那里,被人埋葬。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, '到了第四 代,他们必回 到此地,因为 亚摩利人 的罪孽 还 没有 满盈。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, ' 日 落天 黑,不料 有冒烟 的炉 并烧 著的火把 从那些 肉块 中 经过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, '当那 日,耶和华 与 亚伯兰 立 约,说:「我已赐 给你的后裔, 从埃及 河 直到 幼发拉底 大 河 之 地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, '就是 基尼人、 基尼洗人、 甲摩尼人、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, ' 赫人、 比利洗人、 利乏音人、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, ' 亚摩利人、 迦南人、 革迦撒人、 耶布斯人之地。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, '亚伯兰 的妻子 撒莱 不 给他 生儿女。撒莱有一个使女,名 叫夏甲,是埃及人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, '撒莱 对 亚伯兰 说:「 耶和华 使我不能 生育。求 你和 我的使女 同房,或者 我可以因她 得孩子(得孩子:原文是被建立)」。亚伯兰 听从 了撒莱 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, '于 是亚伯兰 的妻子 撒莱 将 使女 埃及人 夏甲 给 了丈夫 为妾;那时亚伯兰 在 迦南 已经 住了 十 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, '亚伯兰与 夏甲 同房,夏甲就怀了孕;她见 自己有孕,就小看 她的主母。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, '撒莱 对 亚伯兰 说:「我因你 受屈。我将我的使女 放 在你怀中,她见 自己有了孕,就小看我。愿 耶和华 在你我中间 判断。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, '亚伯兰 对 撒莱 说:「 使女 在你手下,你可以随意 待 她。」撒莱 苦待她,她就从撒莱面 前逃走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, '耶和华 的使者 在旷野 书珥 路 上 的水 泉 旁遇见她, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, '对她说:「撒莱 的使女 夏甲,你从哪里 来?要往哪里 去?」夏甲说:「我 从我的主母 撒莱 面前 逃出来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, '耶和华 的使者 对她 说:「你回 到 你主母那里,服 在她手 下」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, ' 又说:「我必使 你的后裔 极其 繁多,甚至不可 胜 数」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, ' 并说:「 你如今怀孕 要生 一个儿子,可以给他起名 叫 以实玛利(就是神听见的意思),因为 耶和华 听见了 你的苦情。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, '他 为 人 必像野驴。他的手 要攻打人,人 的手 也要攻打他;他必住 在 众 弟兄 的东边。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, '夏甲就称 那对她 说话 的耶和华为「 看顾人的 神」。因而 说:「在这里 我也 看见 那看顾 我的吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, '所以 这井 名叫庇耳‧拉海‧莱。 这井正在加低斯和 巴列 中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, '后来夏甲 给亚伯兰 生了 一个儿子;亚伯兰 给他 起名 叫 以实玛利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, '夏甲 给亚伯兰 生 以实玛利的时候,亚伯兰 年 八十 六 岁。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, ' 亚伯兰 年 九十 九 岁的时候,耶和华 向 他 显现,对他 说:「我是 全能的 神。你当 在我面前 作 完全人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, '我就与你 立 约,使你 的后裔极 其繁多。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, '亚伯兰 俯伏 在 地; 神 又 对他 说:「 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, '我 与你 立约:你要作 多 国 的父。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, '从此以后, 你的名 不 再 叫 亚伯兰,要 叫 亚伯拉罕,因为 我已立 你作多 国 的父。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, '我必使你 的后裔极其 繁多;国度 从你而立,君王 从你 而出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, '我要与你并 你 世世代代 的后裔 坚立 我的约,作永远 的约,是要作 你 和你 后裔的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, '我要将 你现在寄居 的地,就是 迦南 全 地,赐 给你 和你 的后裔 永远 为业,我也必作 他们的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, '神 又对 亚伯拉罕 说:「你 和你 的后裔 必世世代代 遵守 我的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, '你们 所有的 男子 都要受割礼;这就是我 与你并 你 的后裔 所立的约,是你们所 当遵守的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, '你们都要受割礼;这是 我与你们 立约 的证据。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, '你们 世世代代的 男子,无论是家里 生的,是 在你后裔 之外 用银子 从 外人 买 的,生下来第八 日,都要受割礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, '你家里 生的 和你用银子 买 的,都必须 受割礼。这样,我的约 就立在你们肉体上 作 永远 的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, '但不受割礼的 男子 必 从民中 剪除,因他背了 我的约。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, '神 又对 亚伯拉罕 说:「你的妻子 撒莱 不可 再叫 撒莱, 她的名 要叫撒拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, '我必赐福 给她,也 要使你 从她 得 一个儿子。我要赐福给她,她也要作 多国之母;必有 百姓 的君王 从她而出。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, '亚伯拉罕 就俯伏 在 地 喜笑,心里 说:「一百 岁的人还能 得孩子吗?撒拉 已经九十 岁了,还能 生养吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, '亚伯拉罕 对 神 说:「但愿  以实玛利 活 在你面前。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, '神 说:「不然,你妻子 撒拉 要给你 生 一个儿子,你要给他 起名 叫 以撒。我要与他 坚定所立的 约,作他 后裔 永远 的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, '至于 以实玛利,我也应允你: 我必赐福 给他,使他 昌盛,极其 繁多。他必生 十二 个族长;我也要使他 成为大 国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, '到明 年 这 时节,撒拉必 给你 生 以撒,我要与他 坚定所立的 约。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, '神 和 亚伯拉罕 说 完了话,就离开  他上升去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, '正当 那 日,亚伯拉罕 遵著 神的 命,给 他的儿子 以实玛利和 家里 的一切 男子, 无论 是在家里 生的,是 用银子 买 的,都行了割礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, '亚伯拉罕 受割礼的时候 年 九十 九 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, '他儿子 以实玛利 受割礼的时候 年 十三 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, '正当 那 日,亚伯拉罕 和他儿子 以实玛利 一同受了割礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, '家 里所有的 人,无论是在家 里生的,是用银子 从 外人 买 的,也都一同 受了割礼。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, '耶和华 在幔利 橡树 那里向 亚伯拉罕显现出来。那时 正热,亚伯拉罕 坐在 帐棚 门口, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, '举 目 观看,见 有三 个人 在对面 站著。他一见,就从帐棚 门口 跑 去迎接他们,俯伏 在地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, '说:「我主, 我若 在你眼前 蒙 恩,求你不要 离开  仆人 往前去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, '容我 拿 点 水来,你们洗洗 脚,在树 下 歇息歇息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, '我再拿 一点 饼来,你们可以加添 心力,然后 往前去。你们既 到 仆人这里来,理当如此。」他们说:「就 照 你说的 行吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, '亚伯拉罕 急忙 进帐棚 见 撒拉,说:「你速速 拿三 细亚 细 面 麺 调和 做 饼。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, '亚伯拉罕 又跑 到 牛群里,牵 了一只又嫩 又好 的牛犊来,交 给 仆人,仆人急忙 预备好了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, '亚伯拉罕又取 了奶油 和奶,并 预备 好的牛犊来,摆 在他们面前,自己 在树 下 站 在旁边,他们就吃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, '他们问亚伯拉罕 说:「你妻子 撒拉 在哪里?」他说:「 在帐棚里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, '三人中有一位说:「到明年 这时候,我必要 回到 你这里; 你的妻子 撒拉 必生一个儿子。」撒拉 在那人 后边 的帐棚 门口 也听见了这话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, '亚伯拉罕 和撒拉 年纪 老迈,撒拉的 月经 已断 绝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, '撒拉 心里 暗笑,说:「我既已 衰败,我主 也老迈, 岂能有 这喜事呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, '耶和华 对 亚伯拉罕 说:「撒拉 为什么 暗笑,说:『我 既已年老,果真 能生养吗?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, '耶和华 岂有难成 的事吗?到了日期,明年这时候,我必回到 你这里,撒拉 必生一个儿子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, '撒拉 就 害怕,不承认,说:「我没有 笑。」那位说:「不然,你实在 笑了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, '三人 就从那里 起行,向 所多玛 观看,亚伯拉罕 也与他们 同行,要送他们一程。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, '耶和华 说:「我 所 要做的事 岂可瞒著 亚伯拉罕呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, '亚伯拉罕 必 要成为 强 大 的国;地上 的万 国 都必因他 得福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, ' 我眷顾他, 为要 叫他吩咐 他的众子 和 他的眷属 遵守 我 的道,秉公 行 义,使 我 所 应许 亚伯拉罕 的话 都成就了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, '耶和华 说:「所多玛 和蛾摩拉 的罪恶 甚 重,声 闻于 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, '我现在 要下去,察看 他们所行的,果然尽像 那达 到我 耳中的声音 一样吗?若是 不然,我也必知道。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, '二人 转身 离开 那里,向所多玛 去;但亚伯拉罕 仍旧 站 在耶和华 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, '亚伯拉罕 近前来,说:「无论善 恶,你都要 剿灭吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, '假若 那城 里 有 五十 个义人,你还 剿灭那地方吗?不 为 城 里 这五十 个义人 饶恕 其中的人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, ' 将义人 与 恶人 同杀,将义人 与恶人 一样看待,这断不是 你 所行的。审判 全 地 的主岂不 行 公义吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, '耶和华 说:「我若 在所多玛 城 里 见 有五十 个义人,我就为他们的缘故 饶恕 那地方 的众人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, '亚伯拉罕 说:「 我 虽然是灰 尘,还 敢 对 主 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, '假若 这五十 个义人 短 了五个,你就因为短了五 个毁灭 全 城吗?」他说:「我在那里 若 见 有四十 五个,也不 毁灭那城。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, '亚伯拉罕又 对他 说:「假若 在那里 见 有四十个怎么样呢?」他说:「为这四十 个的缘故,我也不 做这事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, '亚伯拉罕说:「求 主 不要 动怒,容我说,假若 在那里 见 有三十个怎么样呢?」他说:「我在那里 若 见 有三十个,我也不 做这事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, '亚伯拉罕说:「 我还 敢 对 主 说话,假若 在那里 见 有二十个怎么样呢?」他说:「为这二十 个的缘故,我也不 毁灭那城。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, '亚伯拉罕说:「求 主 不要 动怒,我再 说 这一次,假若 在那里 见 有十个呢?」他说:「为这十 个的缘故,我也不 毁灭那城。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, '耶和华 与 亚伯拉罕 说 完 了话就 走了;亚伯拉罕 也回到 自己的地方去了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, '那两 个天使 晚上 到了 所多玛;罗得 正坐 在所多玛 城门口, 看见他们,就起来 迎接,脸 伏于 地 下拜, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, '说:「 我主啊,请 你们到 仆人 家 里洗洗 脚,住一夜,清早起来 再走。」他们说:「不!我们要 在街上 过夜。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, '罗得切切地 请 他们,他们这才进去,到 他屋里。罗得为他们 预备 筵席,烤 无酵饼,他们就吃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, '他们还没 有躺下,所多玛 城 里各处 的人,连 老 带少,都 来围住 那房子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, '呼叫 罗得 说:「 今日晚上 到 你这里 来的人 在哪里呢?把他们 带出来,任我们所为。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, '罗得 出来,把 门 关上,到众人那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, '说:「众弟兄,请 你们不要 做这恶事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, ' 我 有两 个女儿, 还是处女,容 我领出来,任凭你们的心愿  而行;只是 这 两个人 既然 到 我舍 下,不要 向他们做 什么。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, '众人说:「退去吧!」又说:「这个人 来 寄居,还想要 作官哪!现在 我们要害 你 比害他们更甚。」众人就向前拥挤 罗得,要 攻破 房门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, '只是那二人 伸出 手来,将 罗得 拉进 屋 去,把 门 关上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, '并且使 门外的 人,无论 老 少,眼都昏迷;他们摸来摸去,总寻 不著房门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, '二人 对 罗得 说:「你 这里 还有 什么人吗?无论是女婿 是儿 女,和这城中 一切 属你的 人,你都要将他们从 这地方 带出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, ' 我们 要毁灭 这 地方;因为 城内罪恶的声音 在耶和华 面 前 甚大,耶和华 差我们来,要毁灭这地方。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, '罗得 就出去,告诉 娶了(或译:将要娶)他女儿 的女婿 们说:「你们起来 离开  这 地方,因为 耶和华 要毁灭 这城。」他女婿 们却以为 他说的是 戏言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, ' 天明了,天使 催逼 罗得 说:「起来!带著 你的妻子 和 你在这里的两 个女儿 出去,免得 你因这城 里的罪恶 同被剿灭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, '但罗得迟延不走。二人 因为耶和华 怜恤 罗得,就拉 著他的手 和他妻子 的手,并他两 个女儿 的手,把他们领出来,安置 在城 外; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, ' 领 他们 出来以后,就说:「逃 命吧!不可 回头 看,也不可 在 平原 站住。要往山上 逃跑,免得 你被剿灭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, '罗得 对他们 说:「我主啊, 不要如此! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, ' 你仆人 已经在你眼前 蒙 恩;你又向我 显出 莫大 的慈爱,救 我的性命。我 不 能 逃 到山上去,恐怕 这灾祸 临到我,我便死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, '看哪,这 座城 又小 又 近,容易逃到,这 不是 一个小的吗?求 你容我逃 到那里,我的性命 就得存活。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, '天使对他 说:「 这 事 我也 应允 你;我不 倾覆 复 你所 说的 这城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, '你要速速 地逃 到那城;因为 你还没有 到 那里,我不 能 做 什么。」因 此 那城 名 叫 琐珥(就是小的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, '罗得 到了 琐珥,日头 已经出来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, '当时,耶和华 将硫磺 与火 从 天上 耶和华 那里 降 与 所多玛和 蛾摩拉, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, '把 那些 城 和 全 平原,并 城 里所有的 居民,连地 上生长的,都毁灭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, '罗得的妻子 在后边 回头一看,就变成了 一根盐 柱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, '亚伯拉罕 清早 起来,到了他从前 站 在 耶和华 面前的 地方, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, '向 所多玛 和蛾摩拉与 平原 的全 地 观 看,不料,那地方 烟气 上腾,如同 烧窑一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, '当 神 毁灭 平原 诸城的时候,他 记念 亚伯拉罕,正在倾覆 复 罗得 所 住 之城的时候,就打发 罗得 从倾覆 复 之中出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, '罗得 因为 怕 住 在琐珥,就同他 两 个女儿 从琐珥 上去,住 在山里;他 和两 个女儿 住 在一个洞里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, '大女儿 对 小女儿 说:「我们的父亲 老了,地上 又无 人 按著 世上 的常规 进到 我们这里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, '来!我们可以叫 父亲 喝 酒,与他 同寝。这样,我们好从他 存留 后裔。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, '于 是,那 夜 她们叫 父亲 喝 酒,大女儿 就进去 和 她父亲 同寝;她几时躺下,几时起来,父亲都不 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, ' 第二天,大女儿 对 小女儿 说:「 我昨夜 与 父亲 同寝。今夜 我们再 叫他喝 酒,你可以进去 与他 同寝。这样,我们好从父亲 存留 后裔。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, '于 是,那 夜 她们又 叫 父亲 喝 酒,小女儿 起来 与她 父亲同寝;她几时躺下,几时起来,父亲都不 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, '这样,罗得 的两 个女儿 都从她父亲 怀了孕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, '大女儿 生了 儿子,给他起名 叫 摩押,就是 现今 摩押人 的始祖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, '小女儿 也 生了 儿子,给他起名 叫便‧亚米,就是 现今 亚扪 人 的始祖。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, '亚伯拉罕 从那里 向南 地 迁去,寄居 在 加低斯 和书珥 中间 的基拉耳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, '亚伯拉罕 称 他的妻 撒拉 为 妹子,基拉耳 王 亚比米勒 差 人把 撒拉 取了去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, '但夜间, 神 来,在梦中 对 亚比米勒 说:「 你是个死人哪!因为 你取 了那 女人来;她 原是别人 的妻子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, '亚比米勒 却还没有 亲近 撒拉;他说:「主啊,连有义 的国,你也要 毁灭吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, '那人 岂不是 自己对我 说『她 是我的妹子』吗?就是女人 也 自己 说:『他 是我的哥哥。』我做 这 事是心 正 手 洁的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, '神 在梦中 对他 说:「 我 知道 你做 这 事是心中 正直;我 也 拦阻了 你,免得你得罪 我,所以 我不 容 你沾著 她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, '现在 你把这人 的妻子 归还他;因为 他是 先知,他要为你 祷告,使你存活。你若 不 归还他,你当知道, 你 和你 所有的 人 都必要 死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, '亚比米勒 清早 起来,召了 众 臣仆来,将 这些 事 都 说 给他们听,他们 都甚 惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, '亚比米勒 召了 亚伯拉罕来,对他 说:「你怎么 向我 这样行呢?我在什么 事上得罪 了你,你竟 使 我 和我 国 里的人陷在大 罪里? 你向我 行 不 当行 的事了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, '亚比米勒 又对 亚伯拉罕 说:「你见 了什么 才 做 这 事呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, '亚伯拉罕 说:「 我以为 这 地方 的人总 不 惧怕 神,必为我妻子 的缘故 杀我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, '况且 她也实在 是我的妹子;她 与我是同父 异母,后来作了 我的 妻子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, '当 神 叫我 离开 父 家、飘流 在外的时候,我对她 说:『我们无论 走 到 什么 地方,你可以对人说:他是 我的哥哥;这 就是 你待 我 的恩典了。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, '亚比米勒 把 牛、羊、仆 婢 赐给 亚伯拉罕,又把 他的妻子 撒拉 归还 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, '亚比米勒 又说:「看哪,我的地 都在你面前,你可以随意 居住」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, '又对撒拉 说:「 我给 你哥哥 一千 银子, 作为 你 在合 家人 面前遮羞的(羞:原文是眼),你就在 众人面前 没有不是了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, '亚伯拉罕 祷告 神, 神 就医好了 亚比米勒 和 他的妻子,并他的众女仆,她们便能生育。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, '因 耶和华 为 亚伯拉罕 的妻子 撒拉 的缘故,已经使亚比米勒 家中的 妇人 不能 生育。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, '耶和华 按著 先前的话 眷顾 撒拉,便照他 所 说 的给撒拉 成就。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, '当亚伯拉罕年老的时候,撒拉 怀了孕;到 神 所 说 的日期,就给亚伯拉罕 生 了一个儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, '亚伯拉罕 给 撒拉 所 生的 儿子 起名 叫 以撒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, '以撒生下来第八 日,亚伯拉罕 照著 神 所 吩咐的,给 以撒 行了割礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, ' 他儿子 以撒 生的时候,亚伯拉罕 年一百 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, '撒拉 说:「 神 使 我 喜笑,凡 听见 的必与我 一同喜笑」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, '又说:「谁 能预先对亚伯拉罕 说『撒拉 要乳养 婴孩』呢?因为 在他年老的时候,我给他生 了一个儿子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, '孩子 渐长,就断了奶。 以撒 断奶 的日子,亚伯拉罕 设摆 丰盛 的筵席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, '当时,撒拉 看见 埃及人 夏甲 给亚伯拉罕 所 生 的儿子 戏笑, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, '就对亚伯拉罕 说:「你把这 使女 和 她儿子 赶出去!因为 这 使女 的儿子 不可 与 我的儿子 以撒 一同 承受产业。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, '亚伯拉罕 因 他儿子 的缘故 很 忧愁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, '神 对 亚伯拉罕 说:「你 不必 为 这童子 和 你的使女 忧愁。凡 撒拉 对你 说的话,你都该听从;因为 从以撒生的,才要称为 你的 后裔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, '至于  使女 的儿子,我也必 使 他的后裔 成立一国,因为 他是你所生的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, '亚伯拉罕 清早 起来,拿 饼 和一皮袋 水,给了 夏甲,搭 在 她的肩上,又把 孩子交给她,打发她走。夏甲就走了,在别是巴 的旷野 走迷了路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, ' 皮袋 的水 用尽了,夏甲就把 孩子 撇 在 小树 底下, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, '自己走开  约有一 箭 之远,相对 而坐, 说:「我不 忍见 孩子 死」,就相对 而坐,放 声 大哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, '神 听见 童子的 声音; 神 的使者 从 天上 呼叫 夏甲 说:「夏甲,你 为何这样呢?不要 害怕, 神 已经听见 童子的 声音了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, '起来!把 童子 抱 在 怀中(怀:原文是手), 我必使 他的后裔成为大 国。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, '神 使 夏甲的眼睛 明亮,她就看见 一口水 井,便去 将 皮袋 盛满 了水,给 童子 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, '神保佑 童子,他就渐长,住 在旷野,成了 弓箭手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, '他住 在巴兰 的旷野;他母亲 从埃及 地 给他 娶 了一个妻子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, ' 当那 时候,亚比米勒 同他军长 非各 对 亚伯拉罕 说:「凡 你 所 行的事都有 神 的保佑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, '我愿 你如今 在这里指著 神 对我 起誓,不要 欺负 我 与我的儿子,并我的子孙。我怎样 厚 待 了你,你也要照样厚待 我 与 你所 寄居 这地的民。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, '亚伯拉罕 说:「我 情愿 起誓。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, '从前,亚比米勒 的仆人 霸占了 一口水 井,亚伯拉罕 为 这事 指责 亚比米勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, '亚比米勒 说:「谁 做 这 事,我不 知道,你 也 没有 告诉 我, 今日 我 才 听见了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, '亚伯拉罕 把 羊 和牛 给 了亚比米勒,二人 就彼此立 约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, '亚伯拉罕 把 七 只母 羊羔 另放 在一处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, '亚比米勒 问 亚伯拉罕 说:「你把 这 七 只母羊羔 另放 在一处, 是什么意思呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, '他说:「 你要从我手 里受 这七 只母羊羔, 作 我 挖 这 口井 的证据。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, '所以 他给那 地方 起名叫 别是巴(就是盟誓的井的意思),因为 他们 二人在那里 起了誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, '他们在别是巴 立 了约,亚比米勒 就同他军长 非各 起身 回 非利士 地去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, '亚伯拉罕在别是巴 栽 上一棵垂丝柳树,又在那里 求告 耶和华─永生 神 的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, '亚伯拉罕 在非利士人 的地 寄居 了多 日。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, ' 这些 事 以后, 神 要试验 亚伯拉罕,就呼叫他 说:「亚伯拉罕!」他说:「我在这里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, '神说:「你带著 你的儿子,就是 你独生的儿子,你所 爱 的 以撒,往 摩利亚 地 去,在 我所 要指示 你 的 山上, 把他献 为燔祭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, '亚伯拉罕 清早 起来,备上 驴,带著 两 个仆人 和 他儿子 以撒,也劈 好了燔祭 的柴,就起身 往 神 所 指示 他 的地方 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, '到了第三 日,亚伯拉罕 举 目 远远地 看见那 地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, '亚伯拉罕 对 他的仆人 说:「你们 和 驴 在此 等候,我 与童子 往那里 去 拜一拜,就回到 你们这里来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, '亚伯拉罕 把 燔祭 的柴 放 在 他儿子 以撒身上,自己手里 拿著 火 与 刀;于 是二人 同 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, '以撒 对 他父亲 亚伯拉罕 说:「父亲哪!」亚伯拉罕说:「我儿,我在这里。」以撒说:「请看,火 与柴都有了,但燔祭 的羊羔 在哪里呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, '亚伯拉罕 说:「我儿, 神 必自己 预备 作燔祭 的羊羔。」于 是二人 同 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, '他们到了 神 所 指示的 地方,亚伯拉罕 在那里 筑 坛,把 柴 摆好,捆绑 他的儿子 以撒,放 在 坛 的柴 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, '亚伯拉罕 就伸 手 拿 刀,要杀 他的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, '耶和华 的使者 从 天上 呼叫 他 说:「亚伯拉罕!亚伯拉罕!」他说:「我在这里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, '天使说:「你不可 在 这童子 身上下 手。一点 不可 害 他! 现在 我知道 你是 敬畏 神的了;因为你没有 将 你的儿子,就是 你独生的儿子,留下 不给我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, '亚伯拉罕 举 目 观看,不料, 有一只公羊,两角 扣 在稠密的小树中。亚伯拉罕 就 取了 那只公羊来,献 为燔祭,代替 他的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, '亚伯拉罕 给那 地方 起名 叫「耶和华以勒」(就是耶和华必预备的意思),直到今日 人还说:「在 耶和华 的山 上必有预备。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, '耶和华 的使者 第二次 从 天上 呼叫 亚伯拉罕说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, '「耶和华 说:『你既 行了 这 事,不 留下 你的儿子,就是 你独生的儿子,我便指著自己 起誓 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, '论 福,我必赐大福给你;论子孙,我必叫 你的子孙 多起来,如同 天上 的星, 海 边 的沙。你子孙 必得著 仇敌 的城门, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, '并且地 上万 国 都必因你的后裔 得福,因为 你听从 了我的话。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, '于 是亚伯拉罕 回 到 他仆人那里,他们一同 起身 往 别是巴 去,亚伯拉罕 就住 在别是巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, ' 这 事 以后,有人告诉 亚伯拉罕 说:「 密迦给 你兄弟 拿鹤 生 了几个儿子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, '长子是 乌斯,他的兄弟是 布斯和 亚兰 的父亲 基母利, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, '并 基薛、 哈琐、 必达、 益拉、 彼土利(彼土利 生 利百加)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, '这 八 个人都是密迦 给亚伯拉罕 的兄弟 拿鹤 生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, '拿鹤的妾 名 叫流玛, 生了 提八、 迦含、 他辖,和 玛迦。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, '撒拉 享寿一百 二十 七 岁,这是 撒拉 一生 的岁数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, '撒拉 死 在迦南 地的基列‧亚巴,就是 希伯仑 。亚伯拉罕 为她 哀恸 哭号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, '后来亚伯拉罕 从 死人 面前 起来, 对 赫 人 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, '「我 在你们中间 是外人,是寄居的。求你们在这里 给 我 一块地,我好埋葬 我的死人,使她不在我眼前。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, '赫 人 回答 亚伯拉罕 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, '「我主 请听。你 在我们中间 是一位尊大 的王子,只管在我们最好的 坟地 里埋葬 你的死人;我们没有 一人 不 容 你 在他的坟地 里埋葬 你的死人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, '亚伯拉罕 就起来,向那地的 赫 人 下拜, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, ' 对他们 说:「你们若 有 意 叫我埋葬 我的死人,使她不在我眼前,就请听我的话,为我 求 琐辖 的儿子 以弗仑 , ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, '把 田 头 上那 麦比拉 洞 给 我,他可以按著足 价 卖 给我,作我在你们中间 的坟 地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, '当时以弗仑  正坐 在赫 人 中间。于 是,赫人 以弗仑  在城 门 出入的 赫 人 面前 对 亚伯拉罕 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, '「不然,我主 请听。我送 给你 这块田,连 田间 的洞 也送 给你,在我同族 的人 面前 都给 你,可以埋葬 你的死人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, '亚伯拉罕 就在那地 的人民 面前 下拜, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, '在他们 面前 对 以弗仑  说:「 你 若应允,请 听我的话。我要把田 价 给你,求你收下,我就在那里 埋葬 我的死人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, '以弗仑  回答 亚伯拉罕 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, '「我主 请听。值四 百 舍客勒 银子 的一块田,在你 我中间 还算什么 呢?只管埋葬 你的死人吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, '亚伯拉罕 听从了 以弗仑 ,照著他 在赫 人 面前 所 说的话,把 买 卖 通用 的银子 平 了四 百 舍客勒 给以弗仑 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, '于 是,麦比拉、幔利 前、以弗仑  的那块田 和其 中 的洞,并田 间 四 围的 树木, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, '都定准 归与亚伯拉罕,乃是他在赫 人 面前 并 城 门 出入 的人面前买 妥的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, '此后,亚伯拉罕 把 他妻子 撒拉 埋葬 在 迦南 地 幔利 前 的麦比拉 田 间的洞里。(幔利就是 希伯仑 )。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, '从此,那块田 和 田间 的洞 就藉 借著 赫 人 定准 归与亚伯拉罕 作坟 地。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, '亚伯拉罕 年纪 老迈,向来在一切事上 耶和华 都赐福 给 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, '亚伯拉罕 对 管理 他 全业 最老 的仆人 说:「请你 把手 放 在我大腿 底下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, '我要叫你指著耶和华─天 地 的主 起誓, 不要 为我儿子 娶 这 迦南地 中 的女子 为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, '你要 往 我本地 本族 去,为我的儿子 以撒 娶 一个妻子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, '仆人 对他 说:「倘若 女子 不 肯 跟我 到 这 地方 来,我必须将 你的儿子 带回 你原出 之地吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, '亚伯拉罕 对他 说:「你 要谨慎,不要 带 我的儿子 回 那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, '耶和华─天上 的主 曾带领我 离开 父 家 和本族 的地, 对我 说话, 向我 起誓 说:『我要将 这 地 赐 给你的后裔。』他 必差遣 使者 在你面前,你就可以从那里 为我儿子 娶 一个妻子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, '倘若 女子 不 肯 跟你 来,我使你起的 誓 就与你无干了,只是 不可 带 我的儿子 回 那里去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, '仆人 就把 手 放 在他主人 亚伯拉罕 的大腿 底下,为 这 事 向他 起誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, '那仆人 从他主人 的骆驼 里取 了十 匹骆驼,并带 些他主人 各样的 财物,起身 往 美索不达米亚 去,到了 拿鹤 的城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, '天 将晚,众女子出来 打水 的时候,他便叫 骆驼 跪 在 城 外 的水 井那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, '他说:「耶和华─我主人 亚伯拉罕的 神啊,求 你施 恩 给 我主人 亚伯拉罕,使我 今日 遇见好机会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, '我 现今 站 在 井旁,城 内居民 的女子们 正出来 打 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, '我向 那一个 女子 说:『请 你拿下 水瓶来,给我水喝。』她若说:『请喝!我也 给 你的骆驼 喝。』愿 那女子 就作 你所预定 给你仆人 以撒的妻。这样,我便知道 你施 恩 给 我主人了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, ' 话还没有 说 完,不料,利百加 肩头 上 扛著水瓶 出来。利百加 是彼土利 所生的;彼土利是亚伯拉罕 兄弟 拿鹤 妻子 密迦 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, '那女子 容貌 极其 俊美,还是处女,也未 曾有人 亲近她。她下到 井旁,打满 了瓶,又上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, '仆人 跑上前 去迎著她,说:「求 你将瓶 里的水 给我一点 喝。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, '女子说:「我主 请喝!」就急忙 拿下 瓶来,托在 手 上给他喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, '女子给他喝 了,就说:「我再 为你的骆驼 打水,叫 骆驼也 喝 足。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, '她就急忙 把瓶 里的水倒 在 槽里,又 跑 到 井 旁打水,就为所有 的骆驼 打上水来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, '那人 定睛看 她,一句话也不说,要晓得 耶和华 赐他通达 的道路 没有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, ' 骆驼 喝 足了,那人 就拿 一个金 环,重 半舍客勒,两 个金 镯,重 十舍客勒,给了 那女子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, '说:「请 告诉 我,你 是谁的 女儿?你父亲 家 里有 我们 住宿 的地方没有?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, '女子说:「我是 密迦与 拿鹤之 子 彼土利 的女儿」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, '又说:「我们家里 足 有 粮 草,也 有住宿 的地方。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, '那人 就低头 向耶和华 下拜, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, '说:「耶和华─我主人 亚伯拉罕的 神 是应当称颂的,因他 不 断 地以慈爱 诚实 待 我主人。至于 我,耶和华 在路 上引领我,直走到我主人 的兄弟 家里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, '女子 跑回去,照著这些 话 告诉 她母亲 和她家里的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, '利百加 有一个哥哥,名 叫拉班, 看见 金环,又 看见金镯 在 他妹子 的手上,并听见 他妹子 利百加 的 话,说 那人 对我 如此如此 说。拉班 就跑 出来 往 井旁去,到 那人跟前,见 他仍站 在 骆驼 旁边的井 旁那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, '并入上节 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, '便对他说:「你这蒙耶和华 赐福的,请进来,为什么 站 在外边?我 已经收拾 了房屋,也为骆驼 预备了地方。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, '那人 就进了 拉班的家。拉班卸了 骆驼,用 草料 喂 𫗭上,拿水 给那人 和跟随的人 洗 脚; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, '把饭摆 在他面前,叫他吃,他却说:「我不 吃,等 我说明白 我的事情再吃。」拉班说:「请说。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, '他说:「我是 亚伯拉罕 的仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, '耶和华 大大地 赐福 给 我主人,使他昌大,又赐 给他 羊群、牛群、金 银、仆 婢、骆驼,和驴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, '我主人 的妻子 撒拉 年老 的时候 给我主人 生了 一个儿子;我主人也将 一切 所有的 都给了 这个儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, '我主人 叫我起誓 说:『你不要 为我儿子 娶 迦南 地 的女子 为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, ' 你要往 我父 家、 我本族 那里去,为我的儿子 娶 一个妻子。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, '我对 我主人 说:『恐怕 女子 不肯 跟 我来。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, '他就说:『我所 事奉 的耶和华 必要差遣 他的使者 与你同去,叫你的道路 通达,你就得以在我父 家、我本族那里,给我的儿子 娶 一个妻子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, '只要 你到了 我本族那里,我使你起的誓 就 与你无干。他们若 不 把女子交 给你,我使你起的誓 也与你 无干。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, '「我今日 到了 井旁,便说:『耶和华─我主人 亚伯拉罕的 神啊, 愿  你叫 我 所 行 的 道路 通达。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, ' 我 如今站 在 井旁, 对 哪一个出来 打 水的女子 说:请 你把你瓶 里的水 给 我一点 喝; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, '她若说:你 只管 喝,我也 为你的骆驼 打水;愿 那女子 就作耶和华 给我主人 儿子 所 预定 的妻。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, '我 心 里的话还没有 说 完, 利百加 就出来,肩头 上 扛著水瓶,下到 井 旁打水。我便对她 说:『请 你给我水喝。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, '她就急忙 从肩头上 拿下 瓶来,说:『请喝!我也 给你的骆驼 喝。』我便喝了;她又 给 我的骆驼 喝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, '我问 她 说:『你 是谁 的女儿?』她说:『我是密迦 与拿鹤之 子 彼土利 的女儿。』我就把环子 戴 在 她鼻子上,把镯子 戴在 她两手上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, '随后我低头 向耶和华 下拜,称颂 耶和华─我主人 亚伯拉罕的 神;因为他 引导我 走合适 的道路,使我得著 我主人 兄弟 的孙女,给我主人的儿子为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, '现在 你们若 愿  以慈爱 诚实 待 我主人,就告诉 我;若 不然,也告诉 我,使我可以或向 左,或 向 右。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, '拉班 和彼土利 回答 说:「这事 乃出 于 耶和华,我们不 能 向你 说 好 说歹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, '看哪,利百加 在你面前,可以将她带 去,照著 耶和华 所说的,给你主人 的儿子 为 妻。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, ' 亚伯拉罕 的仆人 听见 他们这话,就向耶和华 俯伏 在地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, '当下仆人 拿出 金 器、银 器,和衣服 送 给利百加,又将宝物 送 给她哥哥 和她母亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, '仆人 和跟从他 的人 吃了 喝了,住了一夜。早晨 起来,仆人就说:「请打发我 回我主人那里去吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, '利百加的哥哥 和她母亲 说:「让女子 同我们 再住 几天,至少 十天,然后 她可以去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, '仆人 说:「耶和华 既赐给我通达 的道路,你们不要 耽误 我,请打发我 走,回我主人那里去吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, '他们说:「我们把女子 叫来 问问 她」, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, '就叫了 利百加来,问她 说:「你和 这 人 同去吗?」利百加说:「我去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, '于 是他们打发 妹子 利百加 和 她的乳母,同 亚伯拉罕 的仆人,并 跟从仆人的,都走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, '他们就给 利百加 祝福 说:我们的妹子啊,愿 你 作 千 万人的母!愿 你的后裔 得著 仇敌 的城门! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, '利百加 和她的使女们 起来,骑 上 骆驼,跟 著 那仆人,仆人 就带 著 利百加 走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, '那时,以撒 住 在南 地,刚从庇耳‧拉海‧莱 回来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, '天将 晚,以撒 出来 在田间 默想,举 目 一看,见 来了 些骆驼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, '利百加 举 目 看见 以撒,就急忙下 了 骆驼, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, '问 那仆人 说:「这 田间 走来 迎接我们 的 是谁?」仆人 说:「是 我的主人。」利百加就拿 帕子 蒙上脸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, '仆人 就将 所 办 的一切 事 都告诉 以撒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, '以撒 便领 利百加进了他母亲 撒拉 的帐棚,娶 了 她 为 妻,并且爱她。以撒 自从 他母亲不在了,这才得了安慰。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, '亚伯拉罕 又 娶了 一妻,名 叫基土拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, '基土拉给他 生了 心兰、 约珊、 米但、 米甸、 伊施巴,和 书亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, '约珊 生了 示巴 和 底但。底但 的子孙 是 亚书利族、利都是族,和利乌米族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, '米甸 的儿子 是以法、以弗、哈诺、亚比大,和以勒大。这 都 是基土拉 的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, '亚伯拉罕 将 一切 所 有的 都给了 以撒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, '亚伯拉罕 把财物 分给 他 庶出的 众子,趁著自己还 在世 的时候打发他们 离开  他的儿子 以撒,往 东 方去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, ' 亚伯拉罕 一生 的年 日 是 一百 七十 五 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, '亚伯拉罕 寿 高 年 迈,气绝 而死,归 到他列祖(原文是本民)那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, '他两个儿子 以撒、以实玛利 把他 埋葬 在 麦比拉 洞里。这洞 在 幔利 前、赫人 琐辖 的儿子 以弗仑  的田中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, '就是 亚伯拉罕 向 赫 人 买  的那块田。亚伯拉罕 和他妻子 撒拉 都葬 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, ' 亚伯拉罕 死 了以后, 神 赐福 给 他的儿子 以撒。以撒 靠近庇耳‧拉海‧莱 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, '撒拉 的使女 埃及人 夏甲 给亚伯拉罕 所 生 的儿子 是 以实玛利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, '以实玛利 儿子们 的名字,按著他们的家谱 记在下面。以实玛利 的长子 是尼拜约,又有基达、亚德别、米比衫、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, '米施玛、度玛、玛撒、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, '哈大、提玛、伊突、拿非施、基底玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, '这 是 以实玛利 众子的 名字,照著他们的村庄、营寨,作了十二 族 的族长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, ' 以实玛利 享寿 一百 三十 七 岁,气绝 而死,归 到他列祖(原文是本民)那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, '他子孙的住处 在 他众 弟兄 东边,从哈腓拉 直到 埃及 前 的 书珥,正在 亚述 的道上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, '亚伯拉罕 的儿子 以撒 的后代 记在下面。亚伯拉罕 生 以撒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, ' 以撒 娶 利百加 为 妻 的时候正四十 岁。利百加是巴旦‧亚兰地的 亚兰人 彼土利 的女儿,是亚兰人 拉班 的妹子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, '以撒 因 他妻子 不生育,就为 她 祈求 耶和华;耶和华 应允他 的祈求,他的妻子 利百加 就怀了孕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, '孩子们 在她腹中 彼此相争,她就说:「若是 这样,我 为什么活著呢(或译:我为什么如此呢)?」她就去 求问 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, '耶和华 对她 说:两 国 在你腹内;两 族 要从你身上 出来。这族 必强于  那族;将来大的 要服事 小的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, '生产 的日子 到了,腹中 果然 是双子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, '先 产 的身体发红,浑身有毛,如同皮 衣,他们就给他起 名 叫以扫(就是有毛的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, '随后 又 生了 以扫的兄弟,手 抓住 以扫 的脚跟,因此给他起名 叫 雅各(就是抓住的意思)。利百加生下 两个儿子的时候,以撒 年正六十 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, '两个孩子 渐渐长大,以扫 善于  打猎, 常在田野;雅各 为人 安静,常住 在帐棚里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, '以撒 爱 以扫,因为 常吃 他的野味;利百加 却爱 雅各。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, '有一天,雅各 熬 汤,以扫 从 田野 回来 累昏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, '以扫 对 雅各 说:「 我 累昏了,求 你把 这 红 汤给我喝。」因此 以扫 又叫 以东(就是红的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, '雅各 说:「你今日 把 长子的名分 卖 给我吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, '以扫 说:「 我 将要 死,这 长子的名分 于 我 有什么益处呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, '雅各 说:「你今日 对我 起誓吧。」以扫就对他 起了誓,把 长子的名分 卖 给雅各。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, '于 是雅各 将饼 和红豆 汤 给了 以扫,以扫吃了 喝了,便起来 走了。这就是以扫 轻看了 他长子的名分。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, '在 亚伯拉罕 的日子,那地 有 一次 饥荒;这时又有 饥荒,以撒 就往 基拉耳 去,到非利士人 的王 亚比米勒那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, '耶和华 向以撒 显现,说:「你不要 下 埃及去,要住 在我所 指示 你 的地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, '你寄居 在这 地,我必与你 同在,赐福给你,因为 我要将 这些 地 都 赐 给你 和你的后裔。我必坚定 我向你父 亚伯拉罕 所 起 的誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, '我要加增 你的后裔,像天上 的星那样多,又要将 这些 地 都 赐 给你的后裔。并且地 上万 国 必因你的后裔 得福- ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, '都因 亚伯拉罕 听从 我的话,遵守 我的吩咐 和我的命令、律例、法度。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, '以撒 就住 在基拉耳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, '那地方 的人 问 到他的妻子,他便说:「那是 我的妹子。」原来 他怕 说:「是我的妻子」;他心里想:「恐怕 这地方 的人 为 利百加 的缘故杀我」,因为 她 容貌 俊美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, ' 他 在那里 住了许久。有一天,非利士人 的王 亚比米勒 从 窗户 里往外观看, 见 以撒 和 他的妻子 利百加 戏玩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, '亚比米勒 召了 以撒来,对他说:「 她 实在 是你的妻子,你怎么 说 她是 你的妹子?」以撒 说:「 我心里想,恐怕 我因她 而死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, '亚比米勒 说:「你向我们 做 的是什么事呢?民 中险些 有人 和 你的妻 同寝,把我们 陷在 罪里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, '于 是亚比米勒 晓谕 众 民 说:「凡沾 著这个 人,或是他妻子的,定要 把他治死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, '以撒 在那 地 耕种,那一 年 有百 倍 的收成。耶和华 赐福给他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, '他 就昌大,日增月盛, 成了大富户。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, '他 有 羊群 牛群,又有许多 仆人,非利士人 就嫉妒 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, '当他父亲 亚伯拉罕 在世的日子,他父亲 的仆人 所 挖 的井,非利士人 全都 塞住,填满 了土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, '亚比米勒 对 以撒 说:「你离开 我们 去吧。因为 你比我们 强盛 得多。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, '以撒 就离开  那里,在基拉耳 谷 支搭帐棚,住 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, '当他父亲 亚伯拉罕 在世之日 所 挖 的水 井 因非利士人 在亚伯拉罕 死 后 塞住了,以撒 就重新 挖出来,仍照 他父亲 所 叫 的 叫 那些井 的名字。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, '以撒 的仆人 在谷中 挖井, 便得了 一口活 水 井。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, '基拉耳 的牧人 与 以撒 的牧人 争竞,说:「这水 是我们的。」以撒就给那井 起名 叫 埃色(就是相敌的意思),因为 他们和他 相争。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, '以撒的仆人又挖 了一 口井,他们又 为这井 争竞,因此以撒给这井起名 叫 西提拿(就是为敌的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, '以撒离开  那里,又挖了 一 口井,他们不 为这井 争竞了,他就给那井起名 叫 利河伯(就是宽阔的意思)。他说:「 耶和华 现在 给我们 宽阔之地,我们必在这地 昌盛。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, '以撒从那里 上 别是巴去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, '当 夜 耶和华 向他 显现,说:「我是 你父亲 亚伯拉罕的 神,不要 惧怕!因为 我与你同在,要赐福给你,并要为我仆人 亚伯拉罕 的缘故,使 你的后裔 繁多。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, '以撒 就在那里 筑了 一座坛,求告 耶和华 的名,并且支搭 帐棚;他 的仆人 便在那里 挖 了一口井。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, '亚比米勒,同他的朋友 亚户撒 和他的军 长 非各,从基拉耳 来 见以撒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, '以撒 对他们 说:「你们 既然恨 我,打发我走了,为什么 到 我这里来呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, '他们说:「我们明明地 看见 耶和华 与你 同在,便说,不如 我们 两下 彼此 起誓,彼此 立 约, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, '使你不 害 我们,正如 我们未 曾害你, 一味地 厚待 你,并且打发你 平平安安地走。 你是 蒙耶和华 赐福的了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, '以撒就为他们 设摆 筵席,他们便吃了 喝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, '他们清早 起来 彼此 起誓。以撒 打发他们走,他们就平平安安地 离开  他走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, ' 那一 天,以撒 的仆人 来,将 挖 井 的事 告诉 他 说:「我们得了 水了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, '他就给那井 起名 叫 示巴;因此 那城 叫做别是巴,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, ' 以扫 四十 岁 的时候 娶了 赫人 比利 的女儿 犹滴,与 赫人 以伦 的女儿 巴实抹 为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, '她们常使 以撒 和利百加 心 里愁烦。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, ' 以撒 年老,眼睛 昏花,不能看见,就叫了 他大 儿子 以扫来,说:「我儿。」以扫说:「我在这里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, '他说:「 我如今 老了,不 知道 那一天 死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, '现在 拿 你的器械,就是箭囊 和弓,往田野 去 为我 打 猎, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, '照 我所爱 的做成 美味,拿来 给我 吃,使 我 在未死 之先 给你祝福。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, '以撒 对 他儿子 以扫 说话,利百加 也听见了。以扫 往田野 去 打猎,要得野味 带来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, '利百加 就对 她儿子 雅各 说:「 我听见 你父亲 对 你哥哥 以扫 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, '『你去把野兽 带来,做成 美味 给我 吃,我好在未死 之先,在耶和华 面前 给你祝福。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, '现在,我儿,你要照著我 所 吩咐 你的,听从 我的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, ' 你到 羊群 里 去,给我 拿 两 只肥 山羊 羔来,我便照 你父亲 所爱 的给他 做成 美味。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, '你拿到 你父亲 那里给他吃,使他 在未死 之先 给你祝福。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, '雅各 对 他母亲 利百加 说:「 我哥哥 以扫 浑身是有毛的,我 身上是光滑的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, '倘若 我父亲 摸著我,必以 我为 欺哄人的,我 就招 咒诅,不 得祝福。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, '他母亲 对他 说:「我儿,你招的咒诅 归到我身上;你只管 听 我的话,去 把羊羔给我 拿来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, '他便去 拿来,交给 他母亲;他母亲 就照 他父亲 所爱 的做成 美味。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, '利百加 又 把 家里 所 存 大 儿子 以扫 上好的 衣服 给 她小 儿子 雅各 穿上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, '又用 山羊 羔 皮 包 在 雅各的手 上和 颈项 的光滑处, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, '就把所 做 的 美味 和 饼 交 在她儿子 雅各 的手里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, '雅各到 他父亲 那里说:「我父亲!」他说:「我在这里。我儿,你 是谁?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, '雅各 对 他父亲 说:「我是 你的长子 以扫;我已照 你所吩咐 我 的行了。请 起来 坐著,吃 我的野味, 好 给我祝福。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, '以撒 对 他儿子 说:「我儿,你如何 找得 这么 快呢?」他说:「因为 耶和华─你的 神 使我 遇见好机会得著的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, '以撒 对 雅各 说:「我儿, 你近前来,我摸摸你,知道你 真是 我的儿子 以扫 不是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, '雅各 就挨近 他父亲 以撒。以撒摸著他,说:「声音 是雅各 的声音,手 却是以扫 的手。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, '以撒就辨 不出他来;因为 他手 上有 毛,像他哥哥 以扫 的手一样,就给他祝福; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, '又说:「你 真是 我儿子 以扫吗?」他说:「我是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, '以撒说:「你递 给我,我好吃 我儿子 的野味, 给你祝福。」雅各就递 给他,他便吃了,又拿 酒 给他,他也喝 了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, '他父亲 以撒 对他 说:「我儿, 你上前来 与我 亲嘴。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, '他就上前 与父亲 亲嘴。他父亲一闻 他衣服 上的香气,就给他祝福,说: 我儿 的香气 如同耶和华 赐福 之田地 的香气一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, '愿  神 赐 你 天上 的甘露,地 上的肥土,并许多 五谷 新酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, '愿 多民 事奉你,多国 跪拜 你。愿 你作 你弟兄 的主;你母亲 的儿子 向你 跪拜。凡咒诅你的,愿 他受咒诅;为你祝福的,愿 他蒙福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, ' 以撒 为 雅各 祝福 已毕, 雅各 从 他父亲 那里 才 出来,他哥哥 以扫 正打猎 回来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, '也 做了 美味,拿来 给他父亲,说:「请父亲 起来,吃 你儿子 的野味, 好 给我祝福。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, '他父亲 以撒 对他 说:「你 是谁?」他说:「我 是你的长子 以扫。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, '以撒 就大大地 战 兢,说:「你未来 之先,是谁 得了 野味 拿来 给我呢?我已经吃 了,为他祝福;他将来也 必 蒙福。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, '以扫 听了 他父亲 的话,就放声 痛 哭,说:「我父啊,求你也 为我 祝福!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, '以撒说:「你兄弟 已经用诡计 来 将你的福分 夺去了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, '以扫说:「他名 雅各,岂不是正对吗?因为他欺骗 了我 两次:他从前夺了 我长子的名分,你看,他现在 又夺了 我的福分。」以扫又说:「你没有 留下 为我 可祝的福吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, '以撒 回答 以扫 说:「 我已立他 为你 的主,使 他的弟兄 都 给 他 作仆人,并赐他 五谷 新酒可以养生。我儿,现在 我还能为你 做 什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, '以扫 对 他父亲 说:「父啊,你 只有 一 样可祝的福吗?我父啊,求你也 为我 祝福!」以扫 就放 声 而哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, '他父亲 以撒 说: 地 上的肥土 必为 你所住;天 上 的甘露必为你所得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, '你必倚靠 刀剑 度日,又必事奉 你的兄弟;到 你强盛 的时候,必从 你颈项 上挣开  他的轭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, '以扫 因 他父亲 给雅各祝 的 福,就怨恨 雅各, 心里 说:「为我父亲 居丧 的日子 近了,到那时候,我要杀 我的兄弟 雅各。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, '有人把 利百加大 儿子 以扫 的话 告诉 利百加,她就打发人去,叫了 她小 儿子 雅各来,对他 说:「 你哥哥 以扫 想要杀 你,报仇雪恨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, '现在,我儿,你要听 我的话:起来, 逃 往 哈兰、我哥哥 拉班那里去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, '同他 住 些 日子,直等 你哥哥 的怒气 消了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, ' 你哥哥 向你 消了 怒气,忘了 你向他 所 做的事,我便打发 人去把你从那里 带回来。为什么 一 日 丧 你们二人呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, '利百加 对 以撒 说:「我因 这赫人 的女子 连性命 都厌烦了;倘若 雅各 也娶 赫人 的女子 为妻,像这些 一样,我 活著 还有什么益处呢?」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, '以撒 叫 了 雅各来,给他 祝福,并嘱咐他 说:「你不要 娶 迦南 的女子 为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, '你起身往巴旦‧亚兰 去,到你外 祖 彼土利 家里,在你母 舅 拉班 的女儿中 娶 一女为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, '愿 全能的 神 赐福 给你,使你生养 众多,成为 多 族, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, '将 应许亚伯拉罕 的福 赐 给你 和 你的后裔,使你承受 你所寄居 的地为业,就是 神 赐 给亚伯拉罕的地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, '以撒 打发 雅各走了,他就往巴旦‧亚兰 去,到 亚兰人 彼土利 的儿子 拉班那里。拉班是雅各、以扫 的母 舅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, '以扫 见 以撒 已经给 雅各 祝福,而且打发 他往巴旦‧亚兰去,在那里 娶 妻,并见祝福 的时候嘱咐 他 说:「不要 娶 迦南 的女子 为妻」, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, '又见雅各 听从 父 母的话往巴旦‧亚兰 去了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, '以扫 就晓得 他父亲 以撒 看不中 迦南 的女子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, ' 便往 以实玛利 那里去,在他 二妻 之外 又娶了 玛哈拉 为妻。她是亚伯拉罕 儿子 以实玛利 的女儿,尼拜约 的妹子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, '雅各 出了 别是巴,向哈兰 走去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, '到了 一个地方,因为 太阳 落了,就在那里 住宿,便拾起 那地方 的一块石头 枕 在头下,在那里 躺卧睡了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, '梦见 一个梯子 立 在地上,梯子的头 顶著 天,有 神 的使者 在梯子上,上去 下来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, ' 耶和华 站在梯子以上(或译:站在他旁边),说:「我 是耶和华─你祖 亚伯拉罕的 神,也是以撒的 神;我要将你 现在所 躺卧 之地 赐 给你 和你的后裔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, '你的后裔 必 像地 上的尘沙那样多,必向东 西 南 北 开 展;地上 万 族 必因你 和你的后裔 得福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, ' 我 也与你同在。你无论 往哪里 去,我必保佑你,领你归 回 这 地, 总不 离弃你,直到 我成全了 向你 所 应许的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, '雅各 睡醒了,说:「耶和华 真 在 这 里,我 竟不 知道!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, '就惧怕,说:「这 地方 何等 可畏!这 不是别的,乃是 神 的殿,也是 天 的门。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, '雅各 清早 起来,把 所 枕的 石头 立作 柱子,浇 油 在 上面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, '他就给 那 地方 起名 叫 伯特利(就是 神殿的意思);但 那地方 起先 名 叫路斯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, '雅各 许 愿  说:「 神 若 与我 同在,在我 所 行 的 路上 保佑我,又给 我 食物 吃,衣服 穿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, '使我平平安安地 回 到 我父亲 的家,我就必以耶和华 为 我的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, '我所 立 为柱子 的 石头 也必作 神 的殿;凡 你所 赐 给我的,我必 将十分之一 献给你。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, '雅各 起 行,到了 东方 人 之地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, '看见 田间 有一口井, 有三 群 羊 卧 在井旁;因为 人饮 羊群 都是用 那 井里的水。井 口 上 的石头 是大的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, '常有羊群 在那里 聚集,牧人把 石头 转 离 井 口 饮 羊,随后又把 石头 放 在 井 口 的原处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, '雅各 对牧人 说:「弟兄们,你们 是哪里来的?」他们说:「我们是 哈兰来的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, '他问他们 说:「 拿鹤 的孙子 拉班,你们认识吗?」他们说:「我们认识。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, '雅各说:「他 平安吗?」他们说:「平安。看哪,他女儿 拉结 领著 羊 来了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, '雅各说:「 日头 还 高,不是 羊群 聚集 的时候,你们不如饮 羊,再去 放一放。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, '他们说:「我们不 能,必等 羊群 聚齐,人把 石头 转 离 井 口 才可饮 羊。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, '雅各正 和他们 说话的时候,拉结 领著 她父亲的 羊 来了,因为 那些羊 是她 牧放的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, ' 雅各 看见 母 舅 拉班 的女儿 拉结 和 母 舅 拉班 的羊群,就上前 把 石头 转 离 井 口,饮 他母 舅 拉班 的羊群。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, '雅各 与拉结 亲嘴,就放 声 而哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, '雅各 告诉 拉结, 自己是 她父亲 的外甥, 是 利百加 的儿子,拉结就跑去 告诉 她父亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, ' 拉班 听见 外甥 雅各 的信息,就跑 去迎接,抱 著他,与他 亲嘴,领他 到 自己的家。雅各将 一切的 情由 告诉 拉班。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, '拉班 对他 说:「你 实在 是我的骨 肉。」雅各就和他 同住了 一个月。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, '拉班 对雅各 说:「你 虽是我的骨肉(原文是弟兄),岂可白白地 服事我?请告诉 我,你要什么 为工价?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, '拉班 有两 个女儿,大的 名 叫利亚,小的 名 叫拉结。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, '利亚 的眼睛 没有神气,拉结 却生得 美 貌 俊秀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, '雅各 爱 拉结,就说:「我愿 为你小 女儿 拉结 服事你 七 年。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, '拉班 说:「我把她 给 你,胜似 给 别 人,你与我 同住吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, '雅各 就为拉结 服事 了七 年;他因为深爱 拉结,就看 这七年如同 几 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, '雅各 对 拉班 说:「 日期 已经满了,求你把 我的妻子 给我,我好与她 同房。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, '拉班 就摆设 筵席,请齐了 那地方 的众 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, '到 晚上,拉班 将 女儿 利亚 送来 给雅各,雅各就与她 同房。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, '拉班 又 将 婢女 悉帕 给女儿 利亚 作使女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, '到了 早晨,雅各一看 是 利亚,就对 拉班 说:「你向我 做 的是什么事呢?我服事 你,不是 为拉结吗?你为什么 欺哄我呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, '拉班 说:「大女儿还没有给人,先 把小女儿 给人,在我们这地方 没有 这 规矩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, '你为这个 满了 七日,我就把 那个 也 给 你, 你再 为她服事 我 七 年。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, '雅各 就如此 行。满了 利亚的 七日,拉班便 将 女儿 拉结 给雅各 为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, '拉班 又将 婢女 辟拉 给 女儿 拉结 作使女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, '雅各也 与 拉结 同房,并且 爱 拉结 胜似爱利亚,于 是又 服事 了拉班 七 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, '耶和华 见 利亚失宠(原文是被恨;下同),就使 她生育,拉结 却不生育。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, '利亚 怀孕 生 子,就给他起名 叫 流便(就是有儿子的意思),因而 说:「 耶和华 看见 我的苦情,如今 我的丈夫 必爱我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, '她又 怀孕 生 子,就说:「耶和华 因为 听见 我失宠,所以又 赐 给我 这个儿子」,于 是给他起名 叫 西缅(就是听见的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, '她又 怀孕 生 子, 起名 叫 利未(就是联合的意思),说:「 我给丈夫 生了 三个 儿子, 他 必与我 联合。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, '她又 怀孕 生 子,说:「这回 我要赞美 耶和华」,因此 给他起名 叫 犹大(就是赞美的意思)。这才停了 生育。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, '拉结 见 自己不 给雅各 生子, 就嫉妒 她姊姊,对 雅各 说:「你给 我 孩子,不然 我 就死了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, '雅各 向拉结 生 气,说:「叫你 不 生育的是 神,我 岂能代替 他作主呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, '拉结说:「 有我的使女 辟拉在这里,你可以与她 同房,使她生 子在 我膝下,我 便因她 也得孩子(原文是被建立)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, '拉结就把 她的使女 辟拉 给 丈夫 为妾;雅各 便与她 同房, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, '辟拉 就怀孕,给雅各 生了 一个儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, '拉结 说:「 神 伸了我的冤,也 听了 我的声音,赐 我 一个儿子」,因此 给他起名 叫 但(就是伸冤的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, '拉结 的使女 辟拉 又 怀孕,给雅各 生了 第二个 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, '拉结 说:「我与 我姊姊 大大 相争,并且 得胜」,于 是给他起名 叫 拿弗他利(就是相争的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, '利亚 见 自己停了 生育,就 把 使女 悉帕 给 雅各 为妾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, '利亚 的使女 悉帕 给雅各 生 了一个儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, '利亚 说:「万幸!」于 是给他 起名 叫 迦得(就是万幸的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, '利亚 的使女 悉帕 又给雅各 生了 第二个 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, '利亚 说:「我有福啊, 众女子 都要称我是有福的」,于 是给 他起名 叫 亚设(就是有福的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, '割 麦子 的时候,流便 往田里 去,寻见 风茄,拿 来 给 他母亲 利亚。拉结 对 利亚 说:「请 你把你儿子 的风茄 给 我些。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, '利亚说:「你夺了 我的丈夫 还算小事吗?你又 要夺 我儿子 的风茄吗?」拉结 说:「 为 你儿子 的风茄,今夜 他可以与你 同寝。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, '到了晚上,雅各 从 田 里回来,利亚 出来 迎接他,说:「你要与我 同寝,因为 我实在 用我儿子 的风茄 把你雇下了。」那 一夜,雅各就与她 同寝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, '神 应允 了 利亚,她就怀孕,给雅各 生了 第五个 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, '利亚 说:「 神 给了 我价值,因为 我把 使女 给了我丈夫」,于 是给他起名 叫 以萨迦(就是价值的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, '利亚 又 怀孕,给雅各 生了 第六个 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, '利亚 说:「 神 赐 我 厚 赏; 我丈夫 必与我同住,因 我给他 生了 六个 儿子」,于 是给 他起 名 西布伦(就是同住的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, '后来 又生 了一个女儿,给 她起名 叫 底拿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, '神 顾念 拉结, 应允了 她,使 她 能生育。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, '拉结怀孕 生 子,说:「 神 除去 了 我的羞耻」, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, '就给 他起名 叫 约瑟(就是增添的意思),意思说:「愿 耶和华 再增添 我 一个 儿子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, ' 拉结 生 约瑟之后,雅各 对 拉班 说:「请打发我走,叫我回 到 我本乡 本土去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, '请你把我服事 你 所得 的 妻子 和 儿女 给我,让我走; 我怎样 服事你,你 都知道。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, '拉班 对他 说:「我若 在你眼前 蒙 恩,请你仍与我同住,因为我已算定,耶和华 赐福与我 是为你的缘故」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, '又说:「请你定 你的工价,我就给你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, '雅各对他 说:「 我怎样 服事你, 你的牲畜 在 我手里 怎样,是你 知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, ' 我未来之先,你所 有 的很少,现今却发大 众多,耶和华 随我的脚步 赐福 与你。如今,我 什么时候 才 为自己兴家 立业呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, '拉班说:「我当给 你 什么呢?」雅各 说:「什么 你也不必 给 我,只有一件 事,你若 应承,我便仍旧 牧 放 你的羊群。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, '今天 我要走 遍 你的羊群,把绵羊中 凡 有点的、有斑的,和黑色的,并山羊中 凡 有斑的、有点的,都挑出来;将来这一等的就算 我的工价。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, '以后 你 来 查看 我的工价,凡 在我手里 的 山羊 不是 有点 有斑的,绵羊 不是黑色的,那就算是 我偷的;这样便可证出 我的 公义来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, '拉班 说:「好啊!我情愿  照著你的话行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, '当 日,拉班把 有纹的、有斑的 公山羊,有 点的、 有斑的、有 杂白纹的 母山羊,并 黑色的 绵羊,都挑出来,交 在他儿子们 的手下, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, '又使 自己 和 雅各 相离三 天 的路程。雅各 就牧养 拉班 其余 馀 的羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, '雅各 拿 杨树、杏树、枫树 的嫩 枝,将 皮剥成 白 纹,使 枝子 露出 白的来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, '将 剥了皮 的 枝子,对著 羊群,插在 饮 羊的水沟里 和水 槽里,羊 来 喝 的时候,牝牡配合。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, '羊 对著 枝子 配合,就生下 有纹的、有点的、有斑的来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, '雅各 把羊羔 分出来,使拉班 的羊 与 这有纹 和 黑色的 羊 相 对,把自己的 羊 另放 一处,不 叫他和 拉班 的羊 混杂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, '到 羊群 肥壮 配合 的时候,雅各 就把 枝子 插 在水沟里,使羊 对著 枝子 配合。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, '只是到羊 瘦弱 配合的时候就不 插枝子。这样,瘦弱的 就归拉班,肥壮的 就归雅各。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, '于 是雅各 极其 发大,得了 许多 的羊群、仆 婢、骆驼,和驴。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, '雅各听见 拉班 的儿子们 有 话 说:「雅各 把 我们父亲 所有的 都 夺了去,并藉 借著 我们父亲的,得了 这 一切的 荣耀(或译:财)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, '雅各 见 拉班 的气色 向他 不如 从前了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, '耶和华 对 雅各 说:「你要回你祖、你父 之地,到你亲族那里去,我必 与你同在。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, '雅各 就打发人,叫 拉结 和利亚 到 田野 羊群那里来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, '对她们 说:「我 看 你们父亲 的气色 向我 不 如从前了;但我父亲的 神 向来与我 同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, '你们 也知道, 我尽了 我的力量 服事 你们的父亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, '你们的父亲 欺哄 我,十 次 改了 我的工价;然而 神 不 容他 害 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, '他若 说:『有点的 归你作 工价』,羊群 所生 的都 有点;他若 说:『有纹的 归你作 工价』,羊群 所生 的都 有纹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, '这样, 神 把 你们父亲 的牲畜 夺来 赐 给我了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, ' 羊 配合 的时候,我梦中 举 目 一看,见 跳 母羊 的公羊 都是有纹的、有点的、有花斑的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, '神 的使者 在那梦中 呼叫我 说:『雅各。』我说:『我在这里。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, '他说:『 你举 目 观看,跳 母羊 的公羊 都 是有纹的、有点的、有花斑的; 凡 拉班 向你 所 做的,我都 看见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, '我是 伯特利的 神; 你在那里 用油浇过 柱子, 向我 许过 愿 。现今 你起来,离开  这 地,回 你本 地去吧!』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, '拉结 和利亚 回答 雅各 说:「在我们父亲 的家里 还有 我们 可得的分吗?还有我们的产业吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, '我们不是 被他 当作 外人吗?因为 他卖了我们,吞了 我们的价值。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, ' 神 从我们父亲 所 夺出来 的一切 财物,那就是 我们 和我们孩子们的。现今 凡 神 所 吩咐 你的,你只管去行吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, '雅各 起来,使 他的儿子 和 妻子 都骑 上 骆驼, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, '又带著他在巴旦‧亚兰 所 得 的一切 牲畜 和 财物,往 迦南 地、他父亲 以撒 那里去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, '当时拉班 剪 羊 毛去了,拉结 偷了 他父亲 家中的 神像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, '雅各 背著 亚兰人 拉班 偷走了,并不 告诉 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, '就带著 所有的 逃跑。他 起身 过 大河,面向 基列 山行去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, '到第三 日,有人告诉 拉班, 雅各 逃跑了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, '拉班带领 他的众弟兄 去追赶,追了七 日,在基列 山 就追上了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, '夜间, 神 到 亚兰人 拉班那里,在梦中 对他 说:「你 要小心,不可 与 雅各 说 好 说 歹。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, '拉班 追上 雅各。雅各 在山上 支搭 帐棚;拉班 和 他的众弟兄 也在基列 山上 支搭帐棚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, '拉班 对雅各 说:「你做的 是什么事呢?你背著我 偷走了,又把 我的女儿们 带了去,如同用刀剑 掳去的一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, '你为什么 暗暗地 逃跑,偷著走,并不 告诉 我,叫我可以欢乐、唱歌、击鼓、弹琴地 送你回去? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, '又不 容我 与外孙 和女儿 亲嘴?你所行的 真是 愚昧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, '我手 中原有 能力 害 你,只是你父亲的 神 昨夜 对我 说:『你 要小心,不可与 雅各 说 好 说 歹。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, '现在 你虽然 想 你父 家,不得不 去,为什么 又偷了 我的神像呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, '雅各 回答 拉班 说:「 恐怕 你把 你的女儿 从我 夺去,所以我逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, '至于  你的神像,你在谁那里 搜出来,就不 容谁存活。当著 我们的众弟兄,你 认一认,在我这里有 什么东西 是你的,就拿去。」原来雅各 不 知道 拉结 偷了那些神像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, '拉班 进了 雅各、利亚,并两个 使女 的帐棚,都没有 搜出来,就从利亚 的帐棚 出来,进了 拉结 的帐棚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, '拉结 已经 把 神像 藏在 骆驼 的驮篓里,便坐 在上头。拉班 摸 遍 了那帐棚,并没有 摸著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, '拉结对 她父亲 说:「现在 我 身上不便,不 能 在你面前 起来,求我主 不要 生气。」这样,拉班搜寻 神像,竟没有 搜出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, '雅各 就发怒 斥责 拉班 说:「我有什么 过犯,有什么 罪恶,你竟这样 火速地追 我? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, ' 你摸 遍了我一切的 家具,你搜出 什么来呢?可以放 在 你 我弟兄 面前,叫他们在你我 中间 辨别辨别。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, '我 在你 家这 二十 年,你的母绵羊、母山羊 没有 掉过胎。你群 中的公羊,我没有 吃过; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, '被野兽撕裂的,我没有 带 来给你,是我自己 赔上。无论是白日,是黑夜,被偷去的,你都向我 索要。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, '我白日 受尽 干热,黑夜 受尽寒霜,不得 合眼 睡著,我常是这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, '我 这 二十 年 在你家里,为你的两 个女儿 服事你 十四 年,为你的羊群 服事你六 年,你又十 次 改了 我的工价。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, '若不是 我父亲 以撒 所敬畏的 神,就是亚伯拉罕的 神 与我 同在,你如今 必定 打发我 空手而去。 神 看见 我的苦情 和 我的劳碌,就在昨夜 责备你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, '拉班 回答 雅各 说:「这女儿 是我的女儿,这些孩子 是我的孩子,这些羊群 也是我的羊群;凡 在你 眼前 的都是 我的。我的女儿 并 她们所 生 的孩子,我今日 能向他们 做 什么呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, ' 来吧!你 我 二人可以立 约,作 你 我中间 的证据。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, '雅各 就拿 一块石头 立 作柱子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, ' 又对众弟兄 说:「你们堆聚 石头。」他们就拿 石头 来堆 成一堆,大家便在 旁边 吃喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, '拉班 称 那石堆为伊迦尔‧撒哈杜他,雅各 却称 那石堆 为迦累得(都是以石堆为证的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, '拉班 说:「今日 这 石堆 作你 我中间 的证据。」因此 这地方名 叫 迦累得, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, '又叫米斯巴,意思 说:「 我们彼此 离别以后,愿 耶和华 在你 我中间 鉴察。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, '你若 苦待 我的女儿,又 在我的女儿 以外 另娶 妻,虽没有 人 知道,却有 神 在你 我中间 作见证。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, '拉班 又说:「你看 我在你 我中间 所 立 的这 石堆 和 柱子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, '这 石堆 作证据,这柱子 也作证据。 我 必不 过 这 石堆 去害你; 你 也不可 过 这 石堆 和 柱子 来害 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, '但愿 亚伯拉罕的 神 和拿鹤的 神,就是他们父亲的 神,在你我中间 判断。」雅各 就指著他父亲 以撒 所敬畏的 神起誓, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, ' 又在山上 献 祭,请 众弟兄 来吃 饭。他们吃了 饭,便在山上 住宿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, '拉班 清早 起来,与他外孙 和女儿 亲嘴,给他们 祝福, 回 往自己的地方 去了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, '雅各 仍旧行 路, 神 的使者 遇见 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, ' 雅各 看见他们 就说:「这是 神 的军兵」,于 是给那 地方 起名 叫 玛哈念(就是二军兵的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, '雅各 打发 人 先 往 西珥 地去,就是以东 地,见他哥哥 以扫, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, '吩咐 他们 说:「你们对我主 以扫 说:『你的仆人 雅各 这样说:我在 拉班 那里寄居, 直到 如今。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, '我 有 牛、驴、羊群、仆 婢,现在打发 人来报告 我主,为要在你眼前 蒙 恩。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, '所打发的人 回 到 雅各那里,说:「我们到了 你哥哥 以扫那里,他带著 四百 人,正 迎著你 来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, '雅各 就甚 惧怕,而且愁烦,便把 那 与他 同在的人口 和 羊群、 牛群、骆驼 分做 两 队, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, '说:「以扫 若 来 击杀 这一 队,剩下的 那一队 还可以 逃避。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, '雅各 说:「耶和华─我祖 亚伯拉罕的 神,我父亲 以撒的 神啊,你曾对我 说:『回 你本地 本族去,我要厚待 你。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, '你向 仆人 所 施 的一切 慈爱 和诚实,我一点也 不配得; 我先前只拿著我的杖 过 这 约旦河,如今 我却成了 两 队了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, '求 你救我 脱离 我哥哥 以扫 的手;因为 我 怕 他 来 杀我,连妻子 带 儿女一同杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, '你 曾说:『我必定 厚待 你,使 你的后裔 如同海 边的沙, 多得 不 可胜数。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, '当 夜,雅各在那里 住宿,就从 他所有 的物中拿 礼物 要送 给他哥哥 以扫: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, '母山羊 二百只,公山羊 二十只,母绵羊 二百只,公绵羊 二十只, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, '奶崽子的 骆驼 三十只─各带著崽子,母牛 四十只,公牛 十只,母驴 二十匹,驴驹 十匹; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, '每样各分一群,交 在仆人 手下,就对 仆人 说:「你们要在我前头 过去,使群 群 相离,有空闲 的地方」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, '又吩咐 尽 侭先走的 说:「我哥哥 以扫 遇见你 的时候,问你 说:『你是 哪家的人?要往哪里 去?你前头 这些 是谁的?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, '你就说:『是你仆人 雅各的,是 送 给我主 以扫 的礼物; 他自己 也 在我们后边。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, '又 吩咐 第二、 第三, 和一切 赶 群畜 的人说:「你们遇见 以扫 的时候也要这样 对 他 说; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, '并且 你们要说:『 你仆人 雅各 在我们后边。』」因 雅各心里说:「我藉 借著在我前头 去 的礼物 解 他的恨,然后 再见 他的面,或者 他容纳 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, '于 是礼物 先 过去了;那 夜,雅各 在队中 住宿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, '他 夜间 起来,带 著 两个 妻子, 两个 使女,并 十一个 儿子,都过 了 雅博 渡口, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, '先打发 他们过 河,又打发 所有的都过去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, '只剩下 雅各 一人。有一个人 来和他 摔跤,直到 黎明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, '那人见 自己胜 不 过他,就将他的大腿 窝 摸了一把,雅各 的大腿 窝正在 摔跤 的时候就扭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, '那人说:「 天 黎明了,容我去吧!」雅各说:「 你不 给我祝福,我就不 容你去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, '那人说:「你名 叫什么?」他说:「我名叫雅各。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, '那人说:「你的名 不要 再 叫 雅各,要叫 以色列;因为 你与 神 与 人 较力,都得了胜。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, '雅各 问 他说:「请 将你的名 告诉我。」那人说:「何必 问 我的名?」于 是在那里 给雅各 祝福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, '雅各 便给那地方 起名 叫 毘努伊勒(就是 神之面的意思),意思说:「我面 对 面 见了 神,我的性命 仍得保全。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, '日头 刚出来的时候,雅各 经过 毘努伊勒,他 的 大腿 就瘸了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, '故此,以色列 人 不 吃 大腿 窝的 筋,直到 今 日,因为 那人摸了 雅各 大腿 窝 的筋。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, '雅各 举 目 观看,见 以扫 来了,后头跟著 四 百 人,他就把 孩子们 分开  交给 利亚、 拉结,和 两 个使女, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, '并且叫 两个使女 和 她们的孩子 在前头, 利亚 和她的孩子 在后头, 拉结 和 约瑟 在尽 侭后头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, '他自己 在他们前头 过去,一连七 次 俯伏 在地 才 就近 他哥哥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, '以扫 跑来 迎接他,将他抱住,又搂著 他的颈项,与他亲嘴,两个人就哭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, '以扫举 目 看见 妇人 孩子,就说:「这些 和你 同行的是谁呢?」雅各说:「这些孩子 是 神 施恩 给 你的仆人的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, '于 是两个使女 和她们 的孩子 前来 下拜; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, '利亚 和她的孩子 也 前来 下拜;随后 约瑟 和拉结 也前来 下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, '以扫说:「我所 遇见 的这 些群 畜 是什么意思呢?」雅各说:「是要在我主 面前 蒙 恩的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, '以扫 说:「兄弟啊,我的 已经够了,你的 仍归 你吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, '雅各 说:「不然,我若 在你眼前 蒙 恩,就求你从我手里 收下 这礼物;因为 我见了 你的面,如同见了 神 的面,并且你容纳了我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, '求你 收下我 带来 给你 的礼物;因为 神 恩待我, 使 我 充足。」雅各再三地求 他,他才收下了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, '以扫说:「我们可以起身 前往,我在你前头 走。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, '雅各对他 说:「我主 知道 孩子们 年幼娇嫩,牛 羊 也正在乳养的时候,若是催赶 一 天,群畜 都 必死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, '求 我主 在仆人 前头 走,我 要量著 在我面前 群畜 和孩子 的力量 慢慢地 前行,直 走 到 西珥 我主那里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, '以扫 说:「容 我把 跟随我 的人 留 几个 在你这里。」雅各说:「何必呢?只要在我主 眼前 蒙 恩就是了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, '于 是,以扫 当 日 起行,回 往西珥去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, '雅各 就往疏割 去,在那里为自己 盖造 房屋,又为牲畜 搭 棚;因此 那地方 名 叫 疏割(就是棚的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, '雅各从巴旦‧亚兰 回来的时候,平平安安地 到了 迦南 地 的示剑 城,在 城 东 支搭帐棚, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, '就用一百 块银子 向 示剑 的父亲、哈抹 的子孙 买 了 支 帐棚 的 那块 地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, '在那里 筑了 一座坛,起名 叫伊利‧伊罗伊‧以色列(就是 神、以色列 神的意思)。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, '利亚 给雅各 所 生 的女儿 底拿 出去,要见 那地 的女子们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, '那地 的主─希未人、哈抹 的儿子 示剑 看见 她,就拉住 她,与她 行淫,玷辱她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, '示剑的心 系恋 雅各 的女儿 底拿,喜爱 这女子,甜言蜜语 地安慰她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, '示剑 对 他父亲 哈抹 说:「求你为我 聘 这 女子 为妻。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, '雅各 听见 示剑玷污了 他的女儿 底拿。那时他的儿子们 正 和 群畜 在田野,雅各 就闭口不言,等 他们回来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, '示剑 的父亲 哈抹 出来 见 雅各,要和他 商议。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, '雅各 的儿子们 听见这事,就从 田野 回来,人人 忿恨, 十分 恼怒;因 示剑在以色列 家做了 丑事,与 雅各 的女儿 行淫,这本是 不 该做的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, '哈抹 和他们 商议 说:「我儿子 示剑 的心 恋慕 这女子,求 你们将她 给 我的儿子 为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, '你们与我们 彼此结亲;你们可以把女儿 给 我们,也可以娶 我们的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, '你们与我们 同住吧!这地 都在 你们面前,只管在此居住,做买 卖,置产业。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, '示剑 对 女儿的父亲 和 弟兄们 说:「但愿 我在你们眼前 蒙 恩,你们向我 要 什么,我必给你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, '任凭向我 要 多重的 聘金 和礼物,我必照 你们所说的 给你们;只要把 女子 给 我 为妻。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, '雅各 的儿子们 因为 示剑玷污了 他们的妹子 底拿,就用诡诈 的话回答 示剑 和 他父亲 哈抹, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, '对他们 说:「我们不 能 把 我们的妹子 给 没有受割礼的 人为妻,因为 那是 我们的 羞辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, '惟有 一件 才可以应允:若 你们 所有的 男丁 都受割礼, 和我们一样, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, '我们就把 女儿 给 你们,也娶 你们的女儿;我们便与你们 同住,两下成为 一样的 人民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, '倘若 你们不 听从 我们 受割礼,我们就带 著 妹子 走了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, '哈抹 和他 的儿子 示剑 喜欢 这话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, '那少年人 做 这事 并不 迟延,因为 他喜爱 雅各 的女儿;他 在 他父亲 家 中也是人最尊重的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, '哈抹 和他儿子 示剑 到 本城 的门口,对 本城 的人 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, '「这些 人 与我们 和睦,不如许他们在这地 居住,做买 卖; 这地 也宽阔,足可 容下他们。我们 可以娶 他们的女儿 为妻,也可以把 我们的女儿 嫁 给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, '惟有 一件事我们必须做,他们 才肯应允 和我们 同住,成为 一样 的人民:就是我们中间 所有的 男丁 都要受割礼,和他们 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, '他们的群畜、货财,和一切的 牲口 岂不 都归 我们吗?只要 依从 他们,他们就与我们 同住。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, '凡 从城 门 出入 的人就都听从 哈抹 和 他儿子 示剑的话;于 是凡 从城 门 出入 的男丁 都 受了割礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, '到 第三 天,众人正在 疼痛的时候,雅各 的两 个儿子,就是底拿 的哥哥 西缅 和利未,各 拿 刀剑,趁著众人想不到的时候 来 到 城中,把一切 男丁 都杀了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, '又用 刀 杀了 哈抹 和 他儿子 示剑,把 底拿 从示剑 家里 带出来 就走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, '雅各 的儿子们 因为 他们的妹子 受了玷污,就来 到 被杀的人那里,掳掠 那城, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, '夺了 他们的羊群、 牛群,和 驴,并 城里 田间 所有的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, '又把 他们一切 货财、 孩子、 妇女,并 各房中 所有的,都掳 掠去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, '雅各 对 西缅 和 利未 说:「你们连累 我,使我在这地 的居民中,就是在迦南人 和比利洗人中,有了臭名。我 的人丁 既然稀少,他们必聚集 来击杀 我,我 和全家 的人都必灭绝。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, '他们说:「他岂可待 我们的妹子 如同妓女吗?」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, '神 对 雅各 说:「起来!上 伯特利去,住 在那里;要在那里 筑 一座坛给 神,就是你逃避 你哥哥 以扫 的时候向你 显现的那位。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, '雅各 就对 他家中的人 并 一切 与他同在 的人 说:「你们要除掉 你们中间 的 外邦 神,也要自洁,更换 衣裳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, '我们要起来,上 伯特利去,在那里 我要筑 一座坛给 神,就是在我遭难 的日子 应允 我的祷告、在我行 的 路上 保佑我的那位。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, '他们就把 外邦人 的神像 和 他们耳朵上 的 环子 交 给 雅各;雅各 都藏 在 示剑 那里 的橡树 底下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, '他们便起行前往。 神 使 那 周围 城邑 的人都甚 惊惧,就不 追赶 雅各 的众子了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, '于 是雅各 和一切 与他 同在的人 到 了迦南 地 的 路斯,就是 伯特利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, '他在那里 筑了 一座坛,就给那地方 起名叫伊勒‧伯特利(就是伯特利之 神的意思);因为 他逃避 他哥哥的时候, 神 在那里 向他 显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, '利百加 的奶母 底波拉 死了,就葬 在伯特利 下边 橡树 底下;那棵树名 叫亚伦‧巴古。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, '雅各从巴旦‧亚兰 回来, 神 又 向 他显现,赐福 与他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, ' 且对他 说:「你的名 原是雅各,从今以后 不要 再 叫 雅各, 要 叫 以色列。」这样,他就改 名 叫 以色列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, '神 又对他 说:「我是 全能的 神;你要生养 众多,将来有一族 和多国 的民 从你 而生,又有君王从你 而出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, '我所 赐 给亚伯拉罕 和以撒 的 地,我要赐 给你 与你的后裔。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, '神 就从 那 与雅各 说话 的地方 升上去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, '雅各 便在那里 立了 一根石 柱,在柱子 上 奠 酒,浇 油。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, '雅各 就给那 地方起 名 叫 伯特利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, '他们从伯特利 起行,离 以法他 还 有 一段 路程,拉结 临产 甚是艰难。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, '正在 艰难的时候,收生婆 对她 说:「不要 怕, 你 又要 得一个 儿子了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, ' 她将近于  死,灵魂 要走的时候,就给她儿子起名 叫便‧俄尼;他父亲 却给他 起名叫 便雅悯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, '拉结 死了,葬 在以法他 的路旁;以法他就是 伯利恒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, '雅各 在 她的坟 上 立了 一统碑,就是 拉结 的墓 碑,到 今日还在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, '以色列 起行前往,在 以得 台 那边支搭 帐棚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, ' 以色列 住 在那 地的时候,流便 去 与 他父亲 的妾 辟拉 同寝,以色列 也听见了。雅各 共有 十 二 个儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, '利亚 所生的 是雅各 的长子 流便,还有西缅、利未、犹大、以萨迦、西布伦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, '拉结 所生的 是约瑟、便雅悯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, '拉结 的使女 辟拉 所生的 是但、拿弗他利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, '利亚 的使女 悉帕 所生的 是迦得、亚设。这是 雅各在巴旦‧亚兰 所 生 的 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, '雅各 来 到 他父亲 以撒那里,到了基列‧亚巴 的幔利,乃是 亚伯拉罕 和以撒 寄居 的地方;基列‧亚巴就是 希伯仑 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, '以撒 共活了 一百 八十 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, '以撒 年纪老迈,日子 满足,气绝 而死,归 到他列祖(原文是本民)那里。他两个儿子 以扫、雅各 把他 埋葬了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, '以扫 就是 以东,他的后代 记在下面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, '以扫 娶 迦南 的女子 为 妻,就是 赫人 以伦 的女儿 亚大 和 希未人 祭便 的孙女、亚拿 的女儿 阿何利巴玛, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, '又 娶了以实玛利 的女儿、尼拜约 的妹子 巴实抹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, '亚大 给以扫 生了 以利法;巴实抹 生了 流珥; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, '阿何利巴玛 生了 耶乌施、 雅兰、 可拉。这都是 以扫 的儿子, 是在迦南 地 生 的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, '以扫 带著 他的妻子、 儿 女,与 家中 一切的 人口,并 他的牛羊、 牲畜,和一切 货财,就是他在迦南 地 所 得的,往 别处 去,离了 他兄弟 雅各。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, '因为 二人的财物 群畜 甚多,寄居 的地方 容 不下 他们,所以不能同 居。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, '于 是以扫 住 在西珥 山里;以扫 就是 以东。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, '以扫 是西珥 山里 以东人 的始祖,他的后代 记在下面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, '以扫 众子 的名字 如下。以扫 的妻子 亚大 生 以利法;以扫 的妻子 巴实抹 生 流珥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, '以利法 的儿子 是 提幔、阿抹、洗玻、迦坦、基纳斯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, '亭纳 是 以扫 儿子 以利法的 妾;她给以利法 生了 亚玛力。这是 以扫 的妻子 亚大 的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, '流珥 的儿子 是 拿哈、谢拉、沙玛、米撒。这 是 以扫 妻子 巴实抹 的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, '以扫 的妻子 阿何利巴玛 是祭便 的孙女,亚拿 的女儿; 她给以扫 生了 耶乌施、 雅兰、 可拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, '以扫 子孙 中作族长 的记在下面。以扫 的长子 以利法 的子孙中,有提幔 族长、阿抹 族长、洗玻 族长、基纳斯 族长、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, '可拉 族长、迦坦 族长、亚玛力 族长。这是 在以东 地 从以利法 所出的族长,都是 亚大 的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, '以扫 的儿子 流珥 的子孙中,有 拿哈 族长、谢拉 族长、沙玛 族长、米撒 族长。这是 在以东 地 从流珥 所出的族长,都是 以扫 妻子 巴实抹 的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, '以扫 的妻子 阿何利巴玛 的子孙中,有 耶乌施 族长、雅兰 族长、可拉 族长。这是 从以扫 妻子,亚拿 的女儿,阿何利巴玛 子孙中所出的族长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, '以上的 族长 都是 以扫 的子孙;以扫就是 以东。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, '那地 原有的居民─何利人 西珥 的子孙 记在下面:就是罗坍、朔巴、祭便、亚拿、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, '底顺、以察、底珊。这是 从以东 地 的何利人 西珥 子孙 中所出的族长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, '罗坍 的儿子 是 何利、希幔;罗坍 的妹子 是亭纳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, '朔巴 的儿子 是 亚勒文、玛拿辖、以巴录、示玻、阿南。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, '祭便 的儿子 是 亚雅、亚拿(当时在旷野 放 他父亲 祭便的 驴,遇著 温泉 的,就是这 亚拿)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, '亚拿 的儿子 是 底顺;亚拿 的女儿 是阿何利巴玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, '底顺 的儿子 是 欣但、伊是班、益兰、基兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, '以察 的儿子 是 辟罕、撒番、亚干。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, '底珊 的儿子 是 乌斯、亚兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, '从何利人 所出的族长 记在下面:就是罗坍 族长、朔巴 族长、祭便 族长、亚拿 族长、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, '底顺 族长、以察 族长、底珊 族长。这是 从何利人 所出的族长,都在西珥 地,按著宗族作族长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, '以色列 人 未有君王 治理 以先,在以东 地 作 王 的 记在下面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, '比珥 的儿子 比拉 在以东 作王,他的京城 名 叫亭哈巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, '比拉 死了,波斯拉人 谢拉 的儿子 约巴 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, '约巴 死了,提幔 地的 人户珊 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, '户珊 死了,比达 的儿子 哈达 接续他 作王;这哈达就是在摩押 地 杀败 米甸人的,他的京城 名 叫亚未得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, '哈达 死了,玛士利加人 桑拉 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, '桑拉 死了,大河 边的利河伯人 扫罗 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, '扫罗 死了,亚革波 的儿子巴勒‧哈南 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, '亚革波 的儿子巴勒‧哈南 死了,哈达 接续他 作王,他的京城 名 叫巴乌;他的妻子 名 叫米希她别,是米‧萨合 的孙女,玛特列 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, '从以扫 所出的族长,按著他们的宗族、住处、名字 记在下面:就是亭纳 族长、亚勒瓦 族长、耶帖 族长、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, '阿何利巴玛 族长、以拉 族长、比嫩 族长、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, '基纳斯 族长、提幔 族长、米比萨 族长、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, '玛基叠 族长、以兰 族长。这是 以东 人 在所得为业 的地上,按著他们的住处。〈所有的族长都是 以东人 的始祖 以扫的后代。〉   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, '雅各 住在 迦南 地,就是他父亲 寄居 的地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, '雅各 的记略 如下。约瑟 十 七 岁 与 他哥哥们一同 牧 羊。他是 个童子,与 他父亲 的妾 辟拉、悉帕 的儿子们 常在一处。约瑟 将 他哥哥们的恶 行 报 给 他们的父亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, '以色列 原来爱 约瑟 过于 爱他的众 子,因为 约瑟是 他 年老 生的;他给约瑟 做了 一件彩 衣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, '约瑟的哥哥们 见 父亲 爱 约瑟 过于  爱他们,就恨 约瑟,不 与他说 和睦的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, '约瑟 做了 一梦,告诉 他哥哥们,他们就越 发 恨 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, '约瑟对他们 说:「请 听 我所 做 的 梦: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, ' 我们 在 田 里捆 禾稼, 我的捆 起来 站著, 你们的捆 来围著 我的捆 下拜。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, '他的哥哥们回答 说:「难道你真要 作我们 的王吗?难道 你真要 管辖 我们吗?」他们就因为 他的梦 和 他的话 越 发 恨 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, '后来他又 做了 一 梦,也告诉 他的哥哥们 说:「看哪,我又 做了 一梦,梦见 太阳、月亮,与十一 个星 向我 下拜。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, '约瑟将这梦告诉 他父亲 和 他哥哥们,他父亲 就责备 他 说:「你做 的 这是 什么 梦!难道我 和你母亲、你弟兄 果然 要来 俯伏在地,向你 下拜吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, '他哥哥们 都嫉妒 他,他父亲 却把 这话 存在心里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, '约瑟的哥哥们 往示剑 去 放 他们父亲 的羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, '以色列 对 约瑟 说:「你哥哥们 不是 在示剑 放羊吗?你来,我要打发你 往他们那里去。」约瑟说:「我在这里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, '以色列 说:「 你去 看看 你哥哥们 平安不平安, 群羊 平安不平安,就回来报 信 给我。」于 是打发他 出希伯仑  谷,他就往示剑 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, '有人 遇见他 在田野 走迷了路, 就问他 说:「你找 什么?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, '他说:「我 找 我的哥哥们,求你 告诉 我,他们 在何处 放羊。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, '那人 说:「他们已经走了, 我听见 他们说 要往多坍 去。」约瑟 就去追 赶 他哥哥们,遇见他们 在多坍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, '他们远远地 看见 他,趁 他还没有走到 跟前,大家就同谋 要害死 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, '彼此 说:「你看!那 做梦的 来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, ' 来吧!我们将他杀了,丢 在一个 坑里,就说 有恶 兽 把他吃了。我们且看 他的梦 将来 怎么样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, '流便 听见了,要救 他脱离他们的手,说:「我们不可 害 他的性命」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, ' 又说:「不可 流 他的血,可以把他 丢 在 这 野地 的 坑里,不可 下 手 害他。」流便的意思是 要救 他 脱离他们的手,把他归 还 他的父亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, ' 约瑟 到 了 他哥哥们那里,他们就剥了 他的外衣, 就是 他穿的 那件彩 衣, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, '把 他 丢 在坑里;那坑 是空的,里头 没有 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, '他们坐下 吃 饭,举 目 观看,见 有一伙 夥 米甸的以实玛利人 从基列 来,用骆驼 驮著 香料、乳香、没药,要带下 埃及 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, '犹大 对 众弟兄 说:「 我们杀 我们的兄弟,藏了 他的血 有什么 益处呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, ' 我们不如将他卖 给以实玛利人,不可 下 手 害他;因为 他是 我们的兄弟,我们的骨肉。」众弟兄 就听从了他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, '有些米甸的 商 人 从那里经过,哥哥们就把 约瑟 从 坑 里拉上来,讲定二十 舍客勒银子,把 约瑟 卖 给以实玛利人。他们就把 约瑟 带到 埃及去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, '流便 回 到 坑边,见 约瑟 不在 坑里,就撕裂 衣服, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, '回 到 兄弟们那里,说:「童子 没有了。我 往哪里 去才好呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, '他们宰了 一只公 山羊, 把 约瑟 的那件 彩衣 染了 血, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, '打发 人送 到 他们的父亲那里,说:「我们捡了 这个;请 认一认 是 你儿子 的外衣 不是?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, '他认得,就说:「这是我儿子 的外衣。有恶 兽 把他吃了,约瑟 被撕碎了!撕碎了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, '雅各 便撕裂 衣服,腰间 围上 麻布,为 他儿子 悲哀了 多 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, '他的 儿 女 都起来 安慰他,他却不肯 受安慰,说:「我必 悲哀著 下 阴间,到 我儿子那里。」约瑟的父亲 就为他 哀哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, '米甸人 带约瑟到埃及,把他 卖 给 法老 的内臣─护卫 长 波提乏。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, ' 那 时,犹大 离开  他弟兄 下去,到 一个 亚杜兰人 名 叫希拉的家里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, '犹大 在那里 看见 一个 迦南人 名 叫书亚 的女儿,就娶她为妻,与她 同房, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, '她就怀孕 生了 儿子,犹大给他起 名 叫 珥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, '她又 怀孕 生了 儿子,母亲给他起 名 叫 俄南。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, '她复 又 生了 儿子,给他起 名 叫 示拉。她生 示拉的时候,犹大正在 基悉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, '犹大 为长子 珥 娶 妻,名 叫她玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, '犹大 的长子 珥 在耶和华 眼中 看为 恶,耶和华 就叫他死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, '犹大 对俄南 说:「你当与 你哥哥 的妻子 同房,向她 尽你为弟的本分,为你哥哥 生子立 后。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, '俄南 知道 生子 不 归自己,所以 同房的时候 便遗 在地,免得 给他哥哥 留 后。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, '俄南所 做 的在耶和华 眼中 看为恶,耶和华也就 叫他 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, '犹大 心里说:「 恐怕 示拉 也 死,像他两个哥哥一样」,就对他儿妇 她玛 说:「你去,在你父亲 家 里守 寡,等 我儿子 示拉 长大。」她玛 就回去,住 在她父亲 家里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, '过了许久,犹大 的妻子 书亚 的女儿 死了。犹大 得了安慰,就 和他朋友 亚杜兰人 希拉 上 亭拿 去,到他剪羊毛的人那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, '有人告诉 她玛 说:「 你的公公 上 亭拿 剪 羊毛去了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, ' 她玛见 示拉 已经长大, 还没有 娶 她 为妻,就脱了 她 作寡妇 的衣裳,用帕子 蒙著脸,又遮住身体,坐 在 亭拿 路 上的 伊拿印 城门口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, '犹大 看见她,以为 是妓女,因为 她蒙著 脸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, '犹大就转 到她 那里去,说:「来吧! 让我与你 同寝。」他原 不 知道 是 他的儿妇。她玛说:「你要 与我 同寝,把什么 给 我呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, '犹大说:「我 从 羊群 里取一只山羊羔,打发人送来给你。」她玛说:「在未 送以先,你愿 意 给 我一个当头吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, '他说:「 我给 你 什么 当头呢?」她玛说:「你的印、你的带子,和你手里 的 杖。」犹大就给了 她,与她 同寝,她就从犹大 怀了孕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, '她玛起来 走了,除去 帕子,仍旧穿上 作寡妇 的衣裳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, '犹大 托 讬 他朋友 亚杜兰人 送 一只山羊羔去,要从那女人 手里 取回 当头来,却找 不著她, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, '就问 那地方 的人 说:「伊拿印 路 旁 的妓女 在 哪里?」他们说:「这里 并没 有 妓女。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, '他回去 见 犹大 说:「我没有 找著她,并且 那地方 的人 说:『这里 没 有 妓女。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, '犹大 说:「 我把这 山羊羔 送去了,你 竟找 不著她。任凭她 拿去吧,免得 我们被 羞辱。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, ' 约过了三 个月,有人告诉 犹大 说:「你的儿妇 她玛 作了妓女,且 因行淫 有了身孕。」犹大 说:「拉出她来,把她烧了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, '她玛 被拉出来的时候 便打发 人去见 她公公,对他说:「这些 东西 是谁的,我 就是从谁 怀的孕。 请你 认一认,这 印 和带子 并杖 都是谁的?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, '犹大 承认 说:「她比我更 有义,因 为 我没有 将她给 我的儿子 示拉。」从此犹大不 再 与她同寝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, '她玛将要 生产,不料 她腹里 是一对双生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, '到 生产的时候,一个孩子伸出 一只手来;收生婆 拿 红线 缐 拴 在 他手上,说:「这是 头 生的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, '随后 这孩子把手 收回去, 他哥哥 生出来了;收生婆说:「你 为什么 抢著来呢?」因此给他起名 叫 法勒斯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, '后来,他兄弟 那 手 上 有红线 缐 的也生出来,就给他起名 叫 谢拉。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, '约瑟 被带下 埃及去。有一个埃及 人,是法老 的内臣─护卫 长 波提乏,从那些 带下他 来 的 以实玛利人 手下 买 了他去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, '约瑟 住在 他主人 埃及人 的家中,耶和华 与 他同在,他 就 百事顺利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, '他主人 见 耶和华 与他同在,又见耶和华 使他 手里 所 办的 尽都 顺利, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, '约瑟 就在主人眼前 蒙 恩,伺候 他主人,并且主人派他管理 家务,把一切 所有的 都交在 他手里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, ' 自从 主人派 约瑟 管理家务 和 他 一切 所 有的,耶和华 就因 约瑟 的缘故赐福 与 那埃及人 的家;凡 家里 和田间一切 所 有的 都蒙 耶和华 赐福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, '波提乏将一切 所 有的 都交 在约瑟 的手中,除了 自己 所 吃的 饭,别的事 一概 不 知。约瑟 原来 秀雅 俊美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, ' 这 事 以后,约瑟主人 的妻 以 目 送情 给 约瑟,说:「你与我 同寝吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, '约瑟不从,对 他主人 的妻 说:「看哪,一切 家务,我主人 都不 知道;他把 所 有的 都 交 在我手里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, '在这 家里 没有 比我 大的;并且他没有 留下 一样 不交给我,只 留下了你,因为 你 是他的妻子。我怎能 作 这 大 恶,得罪 神呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, '后来 她天 天 和 约瑟 说,约瑟却不 听从 她,不与她同 寝,也不和她 在一处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, '有 一天,约瑟进 屋里 去办 事,家中 人 没有 一个 在那 屋里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, '妇人就拉住 他的衣裳,说:「你与我 同寝吧!」约瑟把衣裳 丢 在妇人手里,跑到 外边 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, ' 妇人看见 约瑟把衣裳 丢 在她手里 跑 出去了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, '就叫了 家 里的人来, 对他们 说:「你们看!他带了 一个希伯来 人 进入我们家里,要戏弄 我们。他到 我这里来,要与我 同寝,我就大 声 喊叫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, ' 他听见 我放 声 喊起来,就把衣裳 丢 在我这里,跑到 外边 去了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, '妇人把约瑟的衣裳 放 在自己那里,等著 他主人 回 家, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, ' 就对他 如此如此 说:「你所 带 到我们 这里的那希伯来 仆人 进来 要戏弄 我, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, ' 我放 声 喊起来,他就把衣裳 丢在 我这里,跑 出去了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, ' 约瑟的主人 听见 他妻子 对他 所 说 的 话,说「你的仆人 如此如此 待 我」,他就生 气, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, ' 把 约瑟 下 在 监里,就是 王 的囚犯 被囚 的地方。于 是约瑟 在 那里 坐监。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, '但耶和华 与 约瑟 同在,向他 施 恩,使他在司 狱 的眼前 蒙 恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, '司 狱就把 监里 所有 的囚犯 都交 在约瑟的 手下; 他们在那里 所 办的事 都 是 经他 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, ' 凡 在约瑟手下 的事,司 狱 一概不 察,因为 耶和华 与约瑟同在;耶和华 使他 所 做的 尽都顺利。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, ' 这 事 以后,埃及 王 的酒政 和膳长 得罪了 他们的主─埃及 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, '法老 就恼怒 酒 政 和 膳 长 这二 臣, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, '把 他们 下 在 护卫 长 府 内的监里,就是 约瑟 被囚 的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, '护卫 长 把他们 交 给 约瑟,约瑟便伺候 他们;他们有 些日子 在监里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, ' 被囚 在监 之 埃及 王的 酒政 和膳长 二人 同 夜 各 做 一梦,各 梦 都有讲解。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, '到了早晨,约瑟 进 到他们那里,见 他们 有愁闷 的样子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, '他便问 法老 的二臣,就是 与他 同囚在 他主人 府里的,说:「你们今日 为什么 面带 愁容呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, '他们对他 说:「我们各人做了 一梦,没有人 能解。」约瑟 说:「解梦 不是出于  神吗?请 你们将梦告诉 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, '酒 政 便将 他的梦 告诉 约瑟 说:「我梦 见 在我面前 有一棵葡萄树, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, '树上 有三 根枝子, 好像发了芽,开 了 花,上头 的葡萄 都成熟了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, '法老 的杯 在我手中,我就拿 葡萄 挤 在 法老 的杯里,将 杯 递 在 他 手中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, '约瑟 对他 说:「你所做的梦是这样 解:三 根枝子 就是 三 天; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, '三 天 之内,法老 必提 你出监,叫你官复 原职,你仍要递 杯 在法老 的手中,和 先前 作 他的酒政 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, '但 你 得好处 的时候,求你记念我, 施 恩 与我,在 法老 面前提说我,救我 出 这 监牢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, '我实在 是从希伯来人 之地 被拐来的;我在这里 也 没有 做过 什么, 叫他们把我 下 在监里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, '膳 长 见 梦解 得好,就对 约瑟 说:「 我 在梦中 见 我头 上 顶著三 筐 白饼; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, '极上的 筐子里 有为法老 烤 的 各样 食物,有飞鸟 来吃 我头 上 筐子里 的食物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, '约瑟 说:「你的梦是这样 解:三 个筐子 就是 三 天; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, '三 天 之内,法老 必斩断 你的头,把你 挂 在 木头上,必有飞鸟 来吃 你身上 的肉。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, '到了 第三 天,是 法老 的生日,他为众 臣仆 设摆 筵席,把 酒 政 和 膳 长 提出监来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, '使 酒 政 官复 原职,他仍旧递 杯 在 法老 手中; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, '但把 膳 长 挂起来,正如 约瑟 向他们 所解的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, '酒 政 却不 记念 约瑟,竟忘了他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, ' 过了 两 年,法老 做梦,梦见 自己站 在 河边, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, ' 有七 只母牛 从 河 里上来,又美好 又肥壮,在芦荻中 吃草。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, ' 随后 又有 七 只母牛 从 河 里上来,又丑陋 又干瘦,与 那七只母牛 一同站 在 河 边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, '这又丑陋 又干瘦 的七只母牛 吃尽了 那 又美好 又肥壮 的七 只母牛。法老 就醒了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, '他又睡著,第二回 做梦,梦见 一 棵麦子 长了 七 个穗子,又肥大 又佳美, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, ' 随后 又长了 七 个穗子,又细弱 又被东风 吹焦了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, '这细弱 的穗子 吞了 那 七 个又肥大 又饱满 的穗子。法老 醒了,不料 是个梦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, '到了 早晨,法老心里 不安,就差人 召了 埃及 所有的 术士 和 博士来;法老 就把 所做的梦 告诉 他们,却没有人 能给法老 圆解。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, '那时酒 政 对 法老 说:「我 今日 想起 我的罪来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, '从前法老 恼怒 臣仆,把我 和 膳 长 下在 护卫 长 府 内的监里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, '我们 二人同 夜 各做 一梦,各 梦 都有讲解。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, '在那里 同著我们 有一个希伯来 的少年人,是护卫 长的 仆人,我们告诉 他,他就把 我们的梦 圆解,是按著各人 的梦 圆解的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, '后来 正如 他给我们 圆解 的成就了:我 官复 原职,膳长 被挂起来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, '法老 遂即差 人去召 约瑟,他们便急忙带他 出 监,他就剃头,刮脸,换 衣裳,进 到 法老面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, '法老 对 约瑟 说:「我做了 一梦,没有人 能解;我 听见 人说,你听了 梦 就能解。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, '约瑟 回答 法老 说:「这不在乎我, 神必将 平安 的话回答 法老。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, '法老 对 约瑟 说:「我梦 见 我站 在 河 边, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, ' 有七 只母牛 从 河 里上来,又肥壮 又美好,在芦荻中 吃草。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, ' 随后 又有 七 只母牛 上来,又软弱 又丑陋 又干瘦,在埃及 遍 地,我没有 见过 这样 不好的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, '这又干瘦 又丑陋 的母牛 吃尽了 那 以先的 七 只肥 母牛, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, '吃了 以后 却看不出 是 吃了,那丑陋 的样子仍旧 和先前 一样。我就醒了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, '我又梦 见 一 棵麦子, 长了 七 个穗子,又饱满 又佳美, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, ' 随后 又长了 七 个穗子,枯槁 细弱,被东风 吹焦了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, '这些细弱 的穗子 吞了 那 七 个佳美 的穗子。我将这梦告诉了 术士,却没有人 能给我 解说。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, '约瑟 对 法老 说:「法老 的梦 乃是一个。 神 已将 所 要做 的事指示 法老了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, '七 只好 母牛 是 七 年,七 个好 穗子 也是 七 年;这梦 乃是 一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, '那随后 上来 的七 只又干瘦 又丑陋的 母牛 是 七 年,那七 个虚空、被东风 吹焦的 穗子也是七年,都是 七 个荒 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, '这 就是 我对 法老 所 说, 神 已将所 要做 的事显明 给 法老了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, ' 埃及 遍 地 必来 七 个大 丰 年, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, '随后 又要来 七 个荒 年,甚至在埃及 地 都 忘了 先前的丰收, 全地 必被饥荒 所灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, '因 那 以后的 饥荒 甚 大, 便不 觉得 先前的丰收了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, '至于  法老 两回 做 梦,是 因 神 命定 这事,而且 必速速 成就。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, '所以,法老 当拣选 一个有聪明 有智慧 的人,派他 治理 埃及 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, '法老 当这样行,又派 官员 管理 这地。当七 个丰 年的时候,征收 埃及 地 的五分之一, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, '叫他们把 将来 丰 年 一切的 粮食 聚敛起来,积蓄 五谷,收存 在各城里 做食物,归于 法老 的手 下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, ' 所积蓄 的粮食 可以防备埃及 地 将来 的 七 个荒 年,免得 这地 被饥荒 所灭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, '法老 和他一切 臣仆 都以这事 为妙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, '法老 对 臣仆 说:「像这样 的人,有 神 的灵 在他 里头,我们岂能找得著呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, '法老 对 约瑟 说:「 神 既 将 这 事都 指示 你,可见没有人 像你这样有聪明 有智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, '你 可以 掌管 我的家;我的民 都 必听从 你的话。惟独 在宝座 上我比你 大。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, '法老 又对 约瑟 说:「 我派 你 治理 埃及 全 地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, '法老 就摘下 手 上 打印的 戒指,戴 在 约瑟 的手上,给他 穿上 细麻 衣,把金 炼 链 𫔀 戴 在 他的颈项上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, '又叫约瑟 坐 他的 副 车,喝道的在前 呼叫说:「跪下。」这样,法老派 他 治理 埃及 全 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, '法老 对 约瑟 说:「我是 法老,在埃及 全 地,若没有你的命令,不许 人擅自办事(原文是动 手动 脚)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, '法老 赐名 给约瑟,叫撒发那忒‧巴内亚,又将 安城 的祭司 波提非拉 的女儿 亚西纳 给 他 为妻。约瑟 就出去 巡行 埃及 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, '约瑟 见 埃及 王 法老 的时候年 三十 岁。他 从法老 面前 出去,遍行 埃及 全 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, '七 个丰 年之内,地 的出产极丰极盛(原文是一把一把的), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, '约瑟聚敛 埃及 地 七 个丰年 一切 的粮食,把 粮食 积存 在各城里; 各城 周围 田地 的粮食 都积存 在本城里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, '约瑟 积蓄 五谷 甚 多,如同海边 的沙, 无法 计算,因为 谷不可 胜数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, '荒 年 未到 以前, 安城 的祭司 波提非拉 的女儿 亚西纳 给 约瑟 生了 两个 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, '约瑟 给 长子 起名 叫 玛拿西(就是使之忘了的意思),因为他说:「 神 使我忘了 一切 的 困苦 和 我父 的全 家。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, '他给 次子 起名 叫 以法莲(就是使之昌盛的意思),因为他说:「 神 使我在受苦 的地方 昌盛。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, ' 埃及 地 的七 个丰 年 一完, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, '七 个荒 年 就 来了。正如 约瑟 所说的,各 地 都有 饥荒;惟独埃及 全 地 有 粮食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, '及至埃及 全 地 有了饥荒,众民 向 法老 哀求 粮食,法老 对他们 说:「你们往 约瑟 那里去,凡他所 说的,你们都要做。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, '当时 饥荒 遍 满 天下,约瑟 开 了 各处的仓,粜粮 给埃及人;在埃及 地 饥荒 甚大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, '各地的人 都往 埃及去,到 约瑟 那里籴粮,因为 天下 的饥荒 甚大。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, '雅各 见 埃及 有 粮, 就对儿子们 说:「你们为什么 彼此观望呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, ' 我听见 埃及 有 粮,你们可以下去,从那里 为我们 籴些来,使我们可以存活,不至于  死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, '于 是,约瑟 的十个 哥哥 都下 埃及 籴 粮去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, '但 约瑟 的兄弟 便雅悯,雅各 没有 打发 他和 哥哥们同去,因为 雅各说:「恐怕 他遭 害。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, '来 籴粮 的人中 有以色列 的儿子们,因为 迦南 地 也有 饥荒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, '当时治理 埃及地 的是 约瑟;粜粮 给那地 众 民 的就是他。约瑟 的哥哥们 来了,脸 伏于 地,向他 下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, '约瑟 看见 他哥哥们,就认得他们,却装作生人,向他们 说 些严厉话,问他们 说:「你们从哪里 来?」他们说:「我们从迦南 地 来籴 粮。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, '约瑟 认得 他哥哥们,他们 却不 认得他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, '约瑟 想起 从前所 做 的 那两个梦,就对他们 说:「你们 是奸细,来 窥探 这地 的虚实。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, '他们对他 说:「我主啊,不是的。仆人们 是籴 粮 来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, '我们 都是 一个 人 的儿子,是 诚实人;仆人们 并不 是 奸细。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, '约瑟说:「不然,你们必是 窥探 这地 的虚实 来的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, '他们说:「仆人们 本是 弟兄 十二人,是迦南 地 一个 人 的儿子, 顶小的 现今 在 我们的父亲那里,有一个 没有了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, '约瑟 说:「我才说 你们 是奸细,这话实在不错。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, '我指著法老 的性命起誓,若是 你们的小 兄弟 不到 这里来,你们就不得 出 这地方,从此 就可以把你们证验出来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, '须要打发 你们中间 一个人去,把 你们的兄弟 带来。至于 你们,都要囚在这里,好证验 你们的话 真不真,若 不真,我指著法老 的性命起誓,你们 一定 是奸细。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, '于 是约瑟把他们 都下 在 监里 三 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, '到第三 天,约瑟 对他们 说:「我 是敬畏 神的;你们照我的话 行 就可以存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, '你们 如果 是诚实人,可以留你们中间 的一个人 囚 在监里,但你们 可以带著 粮食 回去,救你们家 里的饥荒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, '把 你们的小 兄弟 带 到我这里来,如此,你们的话 便有证据,你们也不至于  死。」他们就照样 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, '他们彼此 说:「我们 在 兄弟 身上实在 有罪。他 哀求 我们的时候,我们见 他心里 的愁苦,却不肯 听,所以 这场 苦难 临到 我们身上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, '流便 说:「我岂不是 对你们 说过,不可 伤害 那孩子吗?只是你们不肯 听,所以 流他血的罪 向我们追讨。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, '他们 不 知道 约瑟 听得出来,因为 在他们中间 用通事传话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, '约瑟转身 退去,哭了一场,又回来 对他们 说话,就从他们中间 挑出 西缅来,在他们眼前 把他 捆绑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, '约瑟 吩咐 人把粮食 装满 他们的器具,把各人 的银子 归还 在 各人的口袋里,又给 他们 路上 用的食物,人就照 他的话办了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, '他们就把 粮食 驮 在 驴上,离开  那里去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, '到了住宿的地方,他们中间有一个人 打开  口袋,要拿料 喂 𫗭 驴,才看见 自己的银子仍在 口 袋里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, '就对 弟兄们 说:「我的银子 归还了,看哪,仍 在我口袋里!」他们就提心吊胆,战 战 兢兢地 彼此 说:「这是 神 向我们 做 什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, '他们来 到 迦南 地、他们的父亲 雅各那里,将 所遭遇的事 都 告诉 他,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, '「 那地 的主 对我们 说 严厉的话,把我们 当作窥探 那地 的奸细。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, '我们对他 说:『我们是 诚实人,并不 是 奸细。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, '我们 本是弟兄 十二人,都是一个父亲 的儿子,有一个 没有了,顶小的 如今 同 我们的父亲 在迦南 地。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, ' 那地 的主 对我们 说:『若要 我知道 你们是 诚实人,可以留下 你们 中间的一个人 在我这里,你们可以带著 粮食回去,救 你们家里 的饥荒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, '把 你们的小 兄弟 带 到我这里来,我便知道 你们 不是 奸细,乃是 诚实人。这样,我就把你们的弟兄 交 给你们,你们也可以在 这地 做买 卖。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, '后来 他们 倒 口袋,不料,各人 的银 包 都在口袋里;他们 和父亲 看见 银 包 就都害怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, '他们的父亲 雅各 对他们 说:「你们使我 丧失我的儿子:「约瑟 没有了,西缅 也没有了,你们又要将 便雅悯 带去;这些事都 归 到我身上了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, '流便 对 他父亲 说:「我若 不 带他 回来交给你,你可以杀 我的两个 儿子。只管把他 交 在 我手里,我 必带他回来 交给你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, '雅各说:「我的儿子 不可 与你们一同 下去; 他哥哥 死了,只 剩下 他,他若在你们 所 行的 路上 遭 害,那便是你们使 我白发苍苍、悲悲惨惨地 下 阴间去了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, '那地 的饥荒 甚大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, ' 他们从埃及 带来 的 粮食 吃 尽了,他们的父亲 就对他们 说:「你们再去 给我 籴 些 粮来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, '犹大 对他 说:「那人 谆谆地 告诫 我们 说:『你们的兄弟 若不 与你们同来,你们就不 得见 我的面。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, '你若 打发 我们的兄弟 与我们同去,我们就下去 给你 籴 粮; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, '你若 不 打发他去,我们就不 下去,因为 那人 对我们 说:『你们的兄弟 若不 与你们同来,你们就不得 见 我的面。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, '以色列 说:「你们为什么 这样害 我,告诉 那人 你们 还有 兄弟呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, '他们回答说:「那人 详细 问到 我们 和我们的亲属,说:『你们的父亲 还 在吗?你们 还有 兄弟吗?』我们就按著 他所问的 告诉 他,焉能 知道 他要说『必须把 你们的兄弟 带下来』呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, '犹大 又对 他父亲 以色列 说:「你打发 童子 与我同去,我们就起身 下去,好叫 我们 和 你,并 我们的妇人孩子,都得存活,不 至于 死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, '我 为他作保;你可以从我手中 追讨,我若 不 带 他回来交 在你 面前,我情愿 永远 担罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, '我们若 没有 耽搁, 如今 第 二次 都回来了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, '他们的父亲 以色列说:「若 必须如此,你们就 当这样 行:可以将这地 土产中最好的 乳香、 蜂蜜、香料、没药、榧子、杏仁 都取一点,收 在器具里,带下去 送给那人 作礼物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, '又要手里 加倍地 带 银子,并将 归还 在你们口 袋 内的银子 仍带 在手里;那 或者 是错了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, '也带 著 你们的兄弟,起身 去 见 那人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, '但愿 全能的 神 使你们 在那人 面前 蒙 怜悯,释放 你们的 那 弟兄 和 便雅悯回来。我 若 丧了儿子,就丧了吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, '于 是,他们 拿 著 那 礼物,又手里 加倍地 带 银子,并且带著 便雅悯,起身 下到 埃及,站 在约瑟 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, '约瑟 见 便雅悯 和他们同来,就对 家 宰 说:「将 这些人 领 到屋里。要宰杀牲畜,预备筵席,因为 晌午 这些人 同我 吃饭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, '家宰 就遵著 约瑟 的命 去行, 领 他们 进约瑟 的屋里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, '他们 因为 被领 到约瑟 的屋里,就害怕,说:「领我们到这里来,必是因为 头次 归还 在我们口袋里 的银子,找我们的错缝,下手害 我们,强取 我们 为奴仆,抢夺 我们的驴。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, '他们就挨近 约瑟的 家 宰,在屋 门口 和他 说话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, '说:「我主 啊,我们头次 下来 实在 是要籴 粮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, '后来 到了 住宿的地方,我们打开  口袋,不料,各人 的银子, 分量足数,仍在各人的口 袋内,现在我们手里 又带回来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, '另外 又带下 银子 来籴 粮。不 知道 先前谁 把银子 放 在我们的口袋里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, '家宰说:「你们 可以放心,不要 害怕,是你们的 神 和你们父亲的 神 赐 给你们 财宝 在你们的口袋里;你们的银子,我 早已收了。」他就把 西缅 带出来,交给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, '家宰 就领 他们 进约瑟 的屋里,给 他们水 洗 脚,又给 他们草料 喂 𫗭驴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, '他们就预备 那 礼物,等候 约瑟 晌午 来,因为 他们听见 要在那里 吃 饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, '约瑟 来到 家里,他们就把 手中 的 礼物 拿 进屋 去给他,又俯伏在地,向他 下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, '约瑟问 他们 好,又问:「你们的父亲─就是你们所 说的 那老人家 平安吗?他还 在吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, '他们回答说:「你仆人─我们的父亲 平安;他还 在。」于 是他们低头 下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, '约瑟举 目 看见 他同母 的兄弟 便雅悯,就说:「你们向我 所 说 那顶小的 兄弟 就是这位吗?」又说:「小儿啊,愿  神 赐恩给你!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, '约瑟 爱 弟 之情 发动,就急忙 寻找 可哭之地,进入 自己的屋里,哭了一场。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, '他洗了 脸 出来,勉强隐忍,吩咐 人摆 饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, '他们就为约瑟 单 摆了一席,为那些人 又摆了一席,也为和约瑟同 吃饭 的埃及人 另摆了一席,因为 埃及人 不 可 和 希伯来人 一同吃 饭;那 原是 埃及人 所厌恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, '约瑟使众弟兄在他面前 排列坐席,都按著长 幼 的次序,众弟兄 就彼此 诧异。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, '约瑟把 他面前 的食物 分出来,送给他们;但便雅悯 所得的 比 别人 多五 倍。他们就饮酒,和约瑟 一同宴乐。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, '约瑟吩咐 家 宰 说:「把粮食 装满 这些人 的 口袋,尽 侭著 他们的驴所能 驮的,又把各人 的银子 放 在各人的口 袋里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, '并将 我的 银 杯 和 那少年人 籴粮 的银子 一同装 在他的口 袋里。」家宰就照约瑟 所 说 的话 行了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, '天 一亮 就打发 那些人 带著驴走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, '他们 出 城 走了不 远,约瑟对 家 宰 说:「起来,追 那些人去,追上了 就对他们 说:『你们为什么 以 恶 报 善呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, '这 不是 我主人 饮酒 的杯吗?岂不是他 占卜 用的吗?你们这样 行 是作恶了。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, '家宰追上他们,将 这些 话 对他们 说了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, '他们回答 说:「我主 为什么 说 这样 的话呢?你仆人 断不能 做 这样 的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, '你看,我们从前在口 袋 里所 见的 银子,尚且从迦南 地 带来还 你,我们怎能 从你主人 家 里偷窃 金 银呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, '你仆人中 无论 在谁那里 搜出来,就叫他死,我们 也 作 我主 的奴仆。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, '家宰说:「现在 就 照你们的话 行吧!在谁 那里 搜出来,谁就作 我的 奴仆;其余 馀的 都没有罪。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, '于 是他们各人 急忙 把 口袋 卸 在地下,各人 打开  口袋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, '家宰就搜查,从年长的 起 到年幼的 为止,那杯 竟在便雅悯 的口袋 里搜出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, '他们就撕裂 衣服,各人 把驮子抬 在 驴上,回 城去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, '犹大 和他弟兄们 来 到约瑟 的屋中,约瑟 还在 那里,他们就在他面前 俯伏 于 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, '约瑟 对他们 说:「你们做的 是什么 事呢?你们岂不 知 像我 这样的 人 必 能占卜吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, '犹大 说:「我们对我主 说 什么呢?还有什么 话可说呢?我们怎能 自己表白出来呢? 神 已经查出 仆人 的罪孽了。 我们 与 那 在他手中 搜出杯来的都 是我主的 奴仆。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, '约瑟说:「我 断不能 这样 行!在谁 的 手中 搜出 杯来,谁 就作 我的 奴仆;至于 你们,可以平平安安地 上 你们父亲 那里去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, '犹大 挨近 他,说:「我主 啊,求你 容仆人 说 一句话 给我主 听,不要 向仆人 发 烈怒,因为 你如同 法老一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, '我主 曾问 仆人们 说:『你们有 父亲 有 兄弟没有?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, '我们对 我主 说:『我们 有 父亲,已经年老,还有他老年 所生的 一个小孩子。他哥哥 死了,他母亲 只撇下 他 一人,他父亲 疼爱他。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, '你对 仆人 说:『把他带到 我这里来,叫 我亲眼 看看他。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, '我们对 我主 说:『童子 不 能 离开  他父亲,若是离开 , 他父亲 必死。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, '你对 仆人 说:『你们的小 兄弟 若 不 与你们一同 下来,你们就不 得再 见 我的面。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, ' 我们上 到 你仆人─我们父亲那里,就把 我主 的话 告诉了 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, '我们的父亲 说:『你们再去 给我 籴 些 粮来。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, '我们就说:『我们不 能 下去。我们的小 兄弟 若 和我们 同往,我们就可以下去。因为,小 兄弟 若不 与我们同往,我们必不 得 见 那人 的面。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, '你仆人─我父亲 对我们 说:『你们 知道 我的妻子 给我 生了 两个儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, '一个 离开 我 出去了;我说 他必 是 被撕碎了,直到 如今 我也没有 见他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, '现在你们又 要把 这个 带去 离开  我,倘若他遭 害,那便是你们使我 白发苍苍、悲悲惨惨地 下 阴间去了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, '我父亲的命 与这童子的命 相连。如今 我回 到 你仆人─我父亲那里,若没有 童子 与我们同在, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, ' 我们的父亲见 没有 童子,他就必死。这便是我们 使 你仆人─我们的父亲 白发苍苍、悲悲惨惨地 下 阴间去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, '因为 仆人 曾向 我父亲 为 这童子 作保,说:『我若 不 带他 回来交给父亲,我便在父亲 面前永远 担罪。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, '现在 求你 容仆人 住下,替 这童子 作我主的 奴仆,叫童子 和 他哥哥们 一同上去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, '若 童子 不 和我同去,我怎能 上去 见 我父亲呢?恐怕 我看见 灾祸 临到 我父亲身上。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, '约瑟 在左右 站著的人 面前 情不 自禁,吩咐一声说:「人 都 要离开 我 出去!」约瑟 和 弟兄们 相认 的时候并没有 一人 站 在他面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, '他就放 声 大哭;埃及人 和法老 家中 的人都听见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, '约瑟 对 他弟兄们 说:「我是 约瑟。我的父亲 还 在吗?」他弟兄 不 能 回答,因为 在他面前 都惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, '约瑟 又对 他弟兄们 说:「请 你们近前 来。」他们就近前来。他说:「我是 你们的兄弟 约瑟,就是你们所 卖 到埃及的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, '现在,不要 因为 把我 卖 到这里 自忧 自 恨。这是 神 差我 在你们以先来,为要保全生命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, '现在 这 地 的饥荒 已经 二年了,还有 五 年 不能 耕种,不能收成。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, '神 差我 在你们以先来,为要给你们 存留 余 馀种 在世上,又要大 施拯救,保全你们的 生命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, '这样看来,差 我 到这里 来的不是 你们,乃是 神。他又使我 如法老 的父,作他全 家 的主,并埃及 全 地 的宰相。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, '你们要赶紧 上 到 我父亲那里,对他 说:『你儿子 约瑟 这样 说: 神 使我作 全 埃及 的主,请你下 到我这里来,不要 耽延。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, '你 和你的儿子 孙子,连牛群 羊群,并一切 所有的,都可以住 在歌珊 地,与我 相 近。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, '我要在那里 奉养 你;因为 还有 五 年 的饥荒,免得 你 和你的眷属,并一切 所有的,都败落了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, '况且 你们的眼 和我兄弟 便雅悯 的眼 都看见 是我亲口 对你们 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, '你们也要将 我在埃及 一切的 荣耀 和 你们所 看见的事 都 告诉 我父亲,又要赶紧地 将 我父亲 搬 到我这里来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, '于 是约瑟伏 在 他兄弟 便雅悯 的颈项 上哭,便雅悯 也在 他的颈项 上哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, '他又与众 弟兄 亲嘴,抱著他们 哭,随后 他弟兄们 就和他 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, '这风声 传到 法老 的宫里,说:「约瑟 的弟兄们 来了。」 法老和 他的臣仆 都很喜欢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, '法老 对 约瑟 说:「你吩咐 你的弟兄们 说:『你们要这样 行:把驮子抬 在 牲口上,起身 往迦南 地 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, '将 你们的父亲 和 你们的眷属 都搬 到我这里 来,我要把 埃及 地 的美物 赐 给你们,你们也要吃 这地 肥美的出产。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, '现在我吩咐 你们 要这样 行:从埃及 地 带著 车辆去,把你们的孩子 和妻子,并 你们的父亲 都搬 来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, '你们眼中 不要 爱惜 你们的家具,因为 埃及 全 地 的美物 都是 你们的。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, '以色列 的儿子们 就如 此行。约瑟 照著 法老 的吩咐 给 他们 车辆 和 路上 用的食物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, '又给 他们 各人 一套 衣服,惟独给 便雅悯 三 百 银子,五 套 衣服; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, '送 给他父亲 公驴 十匹,驮著 埃及 的美物,母驴 十匹,驮著 粮食 与饼 和菜,为他父亲 路上用。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, '于 是约瑟打发 他弟兄们 回去,又对他们 说:「你们不要 在路上 相争。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, '他们从埃及 上去,来 到迦南 地、 他们的父亲 雅各那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, '告诉 他 说:「约瑟 还 在,并且 作 埃及 全 地 的宰相。」雅各心里 冰凉,因为 不 信 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, '他们便将 约瑟 对他们 说 的一切 话 都告诉了 他。他们父亲 雅各 又看见 约瑟 打发 来接 他 的车辆,心 就苏醒了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, '以色列 说:「罢了!罢了!我的儿子 约瑟 还 在,趁我未死 以先,我要去 见他一面。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, '以色列 带著一切 所有的,起身 来 到别是巴,就献 祭 给他父亲 以撒的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, '夜间, 神 在异象中 对以色列 说:「雅各!雅各!」他说:「我在这里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, '神说:「我是 神,就是你父亲的 神。你下 埃及 去不要 害怕,因为 我必使你 在那里 成为大 族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, '我要 和你 同下 埃及去, 也 必定 带你上来;约瑟必给你送终。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, '雅各 就从别是巴 起行。以色列 的儿子们 使 他们的父亲 雅各 和 他们的妻子、 儿女都坐在 法老 为雅各 送来 的车上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, '他们又带著 迦南 地 所 得的 牲畜、 货财 来 到埃及。雅各 和他 的一切 子孙都一同来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, '雅各 把他的儿子、孙子、女儿、孙女,并 他的子子孙孙,一同 带 到埃及。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, '来 到埃及 的以色列 人 名字 记在下面。雅各 和他的儿孙:雅各 的长子 是流便。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, '流便 的儿子 是哈诺、法路、希斯伦、迦米。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, '西缅 的儿子 是耶母利、雅悯、阿辖、雅斤、琐辖,还有迦南女子 所生的 扫罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, '利未 的儿子 是革顺、哥辖、米拉利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, '犹大 的儿子 是珥、俄南、示拉、法勒斯、谢拉;惟有珥 与俄南 死 在迦南 地。法勒斯 的儿子 是 希斯伦、哈母勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, '以萨迦 的儿子 是陀拉、普瓦、约伯、伸仑 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, '西布伦 的儿子 是西烈、以伦、雅利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, '这是 利亚在巴旦‧亚兰 给雅各 所 生 的儿子,还有 女儿 底拿。儿 孙 共 三十 三 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, '迦得 的儿子 是洗非芸、哈基、书尼、以斯本、以利、亚罗底、亚列利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, '亚设 的儿子 是音拿、亦施瓦、亦施韦、比利亚,还有他们的妹子 西拉。比利亚 的儿子 是希别、玛结。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, '这是 拉班 给 他女儿 利亚的 婢女悉帕 从雅各 所生 的 儿孙,共有 十 六 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, '雅各 之妻 拉结 的儿子 是约瑟 和便雅悯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, '约瑟 在埃及 地 生了 玛拿西 和 以法莲,就是 安城 的祭司 波提非拉 的女儿 亚西纳 给约瑟 生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, '便雅悯 的儿子 是比拉、比结、亚实别、基拉、乃幔、以希、罗实、母平、户平、亚勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, '这是 拉结 给雅各 所 生 的儿孙,共有 十 四 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, '但 的儿子 是户伸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, '拿弗他利 的儿子 是雅薛、沽尼、耶色、示冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, '这是 拉班 给 他女儿 拉结 的婢女辟拉 从雅各 所生 的 儿孙,共 有 七 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, ' 那与雅各 同到 埃及的,除了 他 儿 妇之外,凡从他 所生的,共有 六十 六 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, '还有约瑟 在埃及 所 生的 两个 儿子。雅各 家 来 到埃及 的共有 七十 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, '雅各打发 犹大 先 去见 约瑟,请派人引 路 往歌珊去;于 是他们来 到歌珊 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, '约瑟 套 车 往歌珊 去,迎接 他父亲 以色列,及至见 了面,就伏 在 父亲的颈项上,哭了 许久。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, '以色列 对 约瑟 说:「我既 得见 你的面,知道 你还 在,就是 死我也甘心。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, '约瑟 对 他的弟兄 和 他父 的全家 说:「我要上去 告诉 法老,对他 说:『我的弟兄 和我父 的全家 从前在迦南 地,现今都到我这里 来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, '他们本是牧 羊 的人, 以养 牲畜 为业;他们把羊群 牛群 和一切 所 有的 都带来了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, '等 法老 召 你们的时候,问你们说:『你们以何 事为业?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, '你们要说:『你的仆人,从幼年 直到 如今,都以养牲畜 为 业,连 我们 的祖宗 也都以此为业。』这样,你们可以住 在歌珊 地,因为 凡 牧 羊 的都被埃及人 所厌恶。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, '约瑟 进去 告诉 法老 说:「我的父亲 和我的弟兄 带著羊群 牛群,并一切 所 有的,从迦南 地 来了,如今 在歌珊 地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, '约瑟从他弟兄 中 挑出 五 个人来,引他们去 见 法老。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, '法老 问 约瑟的弟兄 说:「你们以何 事为业?」他们对 法老 说:「你仆人 是牧 羊的,连 我们 的祖宗 也是牧羊的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, '他们又对 法老 说:「 迦南 地 的饥荒 甚大, 仆人 的 羊群 没有 草吃,所以我们来到 这地 寄居。现在 求你 容仆人 住在 歌珊 地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, '法老 对 约瑟 说:「你父亲 和你弟兄 到你这里 来了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, '埃及 地 都在 你面前,只管叫 你父亲 和 你弟兄 住在 国中最好的 地;他们可以住在 歌珊 地。你若 知道 他们中间 有 什么能 人,就派他们 看管我的 牲畜。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, '约瑟 领 他父亲 雅各 进到 法老 面前,雅各 就给 法老 祝福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, '法老 问 雅各 说:「你平生 的年 日 是多少呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, '雅各 对 法老 说:「我寄居 在世的年 日 是一百 三十 岁,我平生 的年 日 又 少 又苦,不 及 我列祖 在世 寄居 的 年 日。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, '雅各 又给 法老 祝福,就从法老 面前 出去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, '约瑟 遵著 法老 的命,把埃及 国 最好的 地,就是兰塞 境内的地,给 他父亲 和 弟兄 居住,作为 产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, '约瑟 用粮食 奉养 他父亲 和 他弟兄,并 他父亲 全 家的眷属,都是照各家 的人口奉养他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, ' 饥荒 甚 大,全 地 都绝了 粮,甚至埃及 地 和迦南 地 的人因 那饥荒 的缘故都饿昏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, '约瑟 收聚了 埃及 地 和迦南 地 所有的 银子,就是 众人 籴 粮的银子,约瑟 就把 那银子 带 到法老 的宫里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, '埃及 地 和迦南 地 的银子 都花尽了,埃及 众人 都来 见 约瑟,说:「 我们的银子 都用尽了,求你给 我们 粮食,我们为什么 死 在你面前呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, '约瑟 说:「若 是银子 用尽了,可以把你们的牲畜 给我,我就为你们的牲畜 给 你们粮食。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, '于 是他们把 牲畜 赶 到 约瑟那里,约瑟 就拿 粮食 换了他们的牛、羊、驴、马;那 一年 因换他们一切的 牲畜,就用粮食 养活他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, '那 一年 过去,第二 年 他们又来 见约瑟,说:「我们不 瞒 我主, 我们的银子 都花尽了,牲畜 也都归了 我主。我们在我主 眼前,除了 我们的身体 和田地之外,一无 所剩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, '你何 忍见 我们人 死 地荒呢?求你用粮食 买  我们 和 我们的地,我们 和我们的地 就要 给法老 效力。又求你给 我们种子,使我们得以存活,不致 死亡,地土 也不致 荒凉。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, '于 是,约瑟 为法老 买 了 埃及 所有的 地, 埃及人 因 被饥荒 所迫,各 都卖了 自己的田地;那地 就都归了 法老。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, '至于  百姓,约瑟叫他们,从埃及 这边 直到 埃及那边,都各归 各城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, '惟有 祭司 的地,约瑟没有 买 ,因为 祭司 有从 法老 所得的常俸。他们吃 法老 所 给 的 常俸,所以 他们不 卖 自己的地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, '约瑟 对 百姓 说:「 我今日 为法老 买 了 你们 和 你们的地,看哪,这里有种子 给你们,你们可以种 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, '后来 打粮食的时候,你们要把五分之一 纳给 法老,四 分 可以归 你们 做地 里的种子,也做 你们和 你们家口 孩童的食物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, '他们说:「你救了我们的性命。但愿 我们在我主 眼前 蒙 恩,我们就作 法老的 仆人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, '于 是约瑟 为 埃及 地 定下 常例,直到 今日:法老 必得五分之一,惟 独 祭司 的地 不 归 法老。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, '以色列人 住在 埃及 的歌珊 地。他们在那里 置了产业,并且生育 甚 多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, '雅各 住 在埃及 地 十 七 年,雅各 平生 的年 日 是 一百 四十 七 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, '以色列 的死 期 临近了,他就叫了 他儿子 约瑟来,说:「我若 在你眼前 蒙 恩,请 你把手 放 在我大腿 底下,用慈爱 和诚实 待 我,请 你不要 将我葬 在埃及。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, '我与 我祖我父 同睡的时候,你要将我带出 埃及,葬 在他们所葬的地方。」约瑟说:「我必 遵著你的命 而行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, '雅各说:「你要向我 起誓。」约瑟就向他 起了誓,于 是以色列 在 床 头上敬拜 神。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, ' 这 事 以后,有人告诉 约瑟说:「 你的父亲 病了。」他就带 著 两 个儿子 玛拿西 和 以法莲 同去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, '有人告诉 雅各 说:「请看,你儿子 约瑟 到你这里 来了。」以色列 就勉强 在 床 上坐起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, '雅各 对 约瑟 说:「全能的 神 曾在迦南 地 的路斯 向我 显现,赐福 与我, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, '对我 说:『 我必使你生养 众多,成为 多 民,又要把 这 地 赐 给你的后裔,永远 为业。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, ' 我未到 埃及 见你 之先,你 在埃及 地 所生 的以法莲 和玛拿西 这两 个儿子 是 我的,正如流便 和西缅 是 我的一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, ' 你在他们以后 所 生 的就是 你的,他们可以归 于  他们弟兄 的名 下得产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, '至于 我,我从巴旦 来的时候,拉结 死 在我眼前,在迦南 地 的路上,离 以法他 还有 一段 路程,我就把她葬 在以法他 的路上〈以法他就是 伯利恒〉。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, '以色列 看见 约瑟 的两个儿子,就说:「这 是谁?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, '约瑟 对 他父亲 说:「这是 神 在这里 赐 给我 的 儿子。」以色列说:「请 你领他们 到我跟前,我要给他们祝福。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, '以色列 年纪老迈,眼睛 昏花,不 能 看见。约瑟领他们 到他跟前,他就和他们 亲嘴,抱著 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, '以色列 对 约瑟 说:「我想 不到 得见 你的面,不料, 神 又 使我 得见 你的儿子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, '约瑟 把两个儿子 从 以色列两膝 中领出来,自己就脸 伏于  地下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, '随后,约瑟 又拉 著 他们两个, 以法莲 在他的右手里,对著以色列 的左手, 玛拿西 在他的左手里,对著以色列 的右手,领 他们到以色列的跟前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, '以色列 伸出 右手来,按 在 以法莲 的头上〈以法莲乃是 次子〉,又剪搭过 左手来,按在 玛拿西 的头上〈玛拿西 原是 长子〉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, '他就给 约瑟 祝福 说:「愿 我祖 亚伯拉罕 和我父以撒 所 事奉的 神,就是一生 牧养 我 直到 今 日的 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, '救赎 我 脱离一切 患难 的那使者,赐福 与 这两个童子。愿 他们 归在 我的名 下和我祖 亚伯拉罕、我父以撒 的名下。又愿 他们在世界 中 生养 众多。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, '约瑟 见 他父亲 把右 手 按 在 以法莲 的头上,就不喜悦,便提起 他父亲 的手,要从 以法莲 头 上挪 到 玛拿西的 头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, '约瑟 对 他父亲 说:「我父,不是 这样。这 本是 长子,求你把右手 按 在 他的头上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, '他父亲 不从,说:「我知道,我儿,我知道。他 也必 成为 一族, 也 必昌大。只是 他的兄弟 将来比他 还大;他兄弟的后裔 要成为 多 族。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, '当 日 就给他们祝福 说:「以色列人 要指著你们 祝福 说:『愿  神 使 你如以法莲、玛拿西一样。』」于 是立 以法莲 在玛拿西 以上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, '以色列 又对 约瑟 说:「 我要 死了,但 神 必 与你们同在,领 你们 回到 你们列祖 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, '并且我从前用弓 用刀 从亚摩利人 手下 夺 的那块地,我 都赐 给你,使你比 众弟兄 多得一 分。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, '雅各 叫 了 他的儿子们来,说:「你们都来聚集,我好把 你们 日 后 必遇 的事 告诉 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, '雅各 的儿子们,你们要聚集 而听,要听 你们父亲 以色列的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, '流便哪,你是 我的长子,是我力量 强壮 的时候生的,本当大有 尊荣,权力 超众。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, '但你放纵情欲,滚沸如水,必不得 居首位;因为 你上了 你父亲 的床, 污秽了 我的榻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, '西缅 和利未 是弟兄;他们的刀剑 是残忍 的器具。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, '我的灵啊,不要 与他们同 谋;我的心哪,不要 与他们联络;因为 他们趁怒 杀害 人命,任意 砍断 牛腿大筋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, '他们的怒气 暴烈 可咒;他们的忿恨 残忍可诅。我要使他们分居 在雅各家里,散 住在以色列地中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, '犹大啊,你弟兄们 必赞美 你;你手 必掐住仇敌 的颈项;你父亲 的儿子们 必向你 下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, '犹大 是个小 狮子;我儿啊,你抓了食 便上去。你屈下身去,卧 如公狮,蹲如母狮,谁 敢惹你? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, '圭 必不 离 犹大,杖 必不离他两脚 之间,直 等 细罗来到, 万民 都必归顺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, '犹大把小驴 拴 在葡萄树上,把驴 驹 拴在美好的葡萄树上。他在葡萄酒 中洗了 衣服,在葡萄 汁中 洗了袍褂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, '他的眼睛 必因酒 红润;他的牙齿 必因奶 白亮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, '西布伦 必住在 海 口,必成为 停船 的海口;他的境界 必延到 西顿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, '以萨迦 是个强壮 的驴,卧在 羊圈 之中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, '他以 安静 为 佳,以 肥地 为 美,便低 肩 背重,成为 服苦 的仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, '但 必判断 他的民,作以色列 支派 之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, '但 必作 道 上 的蛇,路 中 的虺,咬伤 马 蹄,使骑马的 坠落 于 后。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, '耶和华啊,我向来等候 你的救恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, '迦得 必被敌军 追逼,他却要 追逼 他们的脚跟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, '亚设之 地必出肥美 的粮食,且 出 君王 的美味。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, '拿弗他利 是被释放 的母鹿;他出 嘉美 的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, '约瑟 是多结果子 的树枝,是泉 旁 多结果 的枝子;他的枝条 探 出 墙外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, '弓箭 手 将他苦害,向他射箭,逼迫他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, '但他的弓 仍旧 坚硬;他的手 健壮敏捷。这是因 以色列的牧者,以色列 的磐石─就是 雅各 的大能者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, '你父亲的 神 必帮助你;那 全能者 必将天 上 所有的福,地里 所藏 的福,以及生产 乳养 的福,都赐给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, '你父亲 所祝的福 胜 过 我祖先 所祝的福 如永世 的山岭,至极的边界;这些福必降在 约瑟 的头上,临到那与弟兄 迥别之人 的顶上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, '便雅悯 是个撕掠 的狼,早晨 要吃 他所抓的,晚上 要分 他所夺的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, '这 一切 是以色列 的十 二 支派;这 也是他们的父亲 对他们 所 说的话,为他们 所 祝的福,都是按著各人 的福分 为他们 祝福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, '他又嘱咐 他们 说:「我 将要归 到我列祖那里,你们要将我 葬 在 赫人 以弗仑  田间 的 洞里,与我祖我父在一处, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, '就是 在 迦南 地 幔利 前、麦比拉 田间 的洞;那洞和田 是 亚伯拉罕 向 赫人 以弗仑  买 来 为业,作坟地的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, '他们在那里 葬了 亚伯拉罕 和 他妻 撒拉,又在那里 葬了 以撒 和 他的妻子 利百加;我也在那里 葬了 利亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, '那块田和田间 的洞 原是向 赫 人 买 的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, '雅各 嘱咐 众子 已毕,就把脚 收 在 床上,气绝而死,归他列祖那里去了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, '约瑟 伏 在 他父亲 的面上 哀哭,与他 亲嘴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, '约瑟 吩咐 伺候他的 医生 用香料薰 他父亲,医生 就用香料薰 了 以色列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, ' 薰 尸的常例是四十天;那四十 天 满了,埃及人 为他 哀哭了 七十 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, '为他哀哭 的日子 过了,约瑟 对 法老 家 中的人说:「我若 在你们眼前 蒙 恩,请 你们报告 法老 说:『 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, '我父亲 要死 的时候叫我起誓 说:你要将我葬 在迦南 地, 在我为自己 所 掘 的坟墓里。』现在 求 你让我上去 葬 我父亲,以后我必回来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, '法老 说:「你可以上去,照著 你父亲 叫你起的誓,将 他葬埋。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, '于 是约瑟 上去 葬 他父亲。与他 一同上去的,有法老的 臣仆 和法老家 中的长老,并 埃及 国 的长老, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, '还有约瑟 的全 家 和他的弟兄们,并他父亲 的眷属;只有 他们的妇人孩子,和羊群 牛群,都留 在歌珊 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, '又有 车辆 马兵,和他 一同上去;那一帮人 甚 多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, '他们到 了 约旦 河外、 亚达 的禾场,就在那里 大大 地 号咷 痛 哭。约瑟为他父亲 哀哭 了七 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, '迦南 的居民 见 亚达 禾场上 的 哀哭,就说:「这是 埃及人 一场极大的 哀哭。」因此 那地方名 叫亚伯‧麦西,是 在约旦河 东。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, '雅各的儿子们 就遵 著 他父亲所吩咐 的办了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, ' 把他 搬到 迦南 地,葬 在 幔利 前、麦比拉 田间 的洞里;那洞和 田 是 亚伯拉罕 向 赫人 以弗仑  买 来 为业,作坟地的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, '约瑟 葬了 他父亲 以后,就 和众弟兄,并一切 同他 上去 葬 他父亲的人,都回 埃及去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, '约瑟 的哥哥们 见 父亲 死了,就说:「或者 约瑟 怀恨我们,照著 我们从前待 他 一切的 恶 足足地 报复 我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, '他们就打发人 去见 约瑟,说:「你父亲 未死 以先 吩咐 说:『 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, '你们要对约瑟 这样 说: 从前你哥哥们 恶 待你,求 你 饶恕 他们的过犯 和罪恶。』如今 求你 饶恕 你父亲 神 之仆人 的过犯。」他们对约瑟 说这话,约瑟 就哭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, '他的哥哥 们又 来 俯伏 在他面前,说:「 我们是你的 仆人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, '约瑟 对他们 说:「不要 害怕,我 岂 能代替 神呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, '从前你们 的意思 是要害 我,但 神 的意思 原是好的,要 保全 许多 人 的性命,成就 今 日的光景。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, '现在 你们不要 害怕,我必 养活 你们 和 你们的妇人孩子。」于 是约瑟用 亲爱 的话 安慰 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, '约瑟 和他父亲 的眷属 都住 在埃及。约瑟 活了 一百 一十 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, '约瑟 得见 以法莲 第三 代的子孙。玛拿西 的孙子、玛吉 的儿子 也 养 在 约瑟 的膝上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, '约瑟 对 他弟兄们 说:「我 要死了,但 神 必定 看顾 你们,领 你们 从 这 地上去,到 他起誓 所 应许给亚伯拉罕、以撒、雅各 之地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, '约瑟 叫 以色列 的子孙 起誓 说:「 神 必定 看顾 你们;你们要把 我的骸骨 从这里 搬上去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, '约瑟 死了,正 一百 一十 岁。人用香料将他 薰了,把他收殓 在棺材里,停在埃及。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, '以色列 的众子,各 带 家眷,和 雅各 一同来到 埃及。他们的名字 记在下面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, '有流便、西缅、利未、犹大、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, '以萨迦、西布伦、便雅悯、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, '但、拿弗他利、迦得、亚设。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, '凡 从雅各 而生的,共有 七十 人。约瑟 已经 在埃及。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, '约瑟 和他的弟兄,并 那 一代的人,都 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, '以色列 人 生养 众多,并且繁茂,极 其 强盛,满了 那地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, '有 不 认识 约瑟 的新 王 起来,治理 埃及, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, '对 他的百姓 说:「看哪,这以色列 民 比我们 还多,又比我们强盛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, '来吧,我们不如用巧计 待他们,恐怕 他们多起来, 日后若 遇 什么争战 的事, 就 连合 我们的仇敌 攻击 我们,离开  这地 去了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, '于 是埃及人派 督 工 的辖制他们,加重担 苦害他们。他们为法老 建造 两座积货 城,就是 比东 和 兰塞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, '只是越发 苦害 他们,他们越发 多起来,越发 蔓延;埃及人就因 以色列 人 愁烦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, '埃及人 严严地 使 以色列 人 做工, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, '使 他们因做苦 工觉得 命 苦;无论是和泥,是做砖,是做田间 各样的 工,在 一切的 工 上都严严地 待他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, '有希伯来 的 两个收生婆,一 名 施弗拉,一 名 普阿;埃及 王 对她们说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, '「你们为 希伯来妇人 收生,看 她们临 盆的时候,若 是 男孩,就把他 杀了;若 是 女孩,就留她存活。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, '但是收生婆 敬畏 神,不 照 埃及 王 的吩咐 行,竟存留 男孩 的性命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, '埃及 王 召了 收生婆来,说:「你们为什么 做 这 事,存留 男孩 的性命呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, '收生婆 对 法老 说:「因为 希伯来妇人 与埃及 妇人 不同;希伯来妇人 本是健壮的(原文是活泼的),收生婆 还没有 到,她们已经生产了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, '神 厚待 收生婆。以色列人 多起来,极其 强盛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, ' 收生婆 因为 敬畏 神, 神便叫她们 成立 家室。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, '法老 吩咐 他的众 民 说:「以色列人所生的 男孩,你们都要丢 在河里;一切的 女孩,你们要存留她的性命。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, ' 有一个利未 家 的人 娶了 一个利未 女子为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, '那女人 怀孕,生 一个儿子,见 他 俊美,就藏了他 三 个月, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, '后来不 能 再 藏,就取了 一个蒲草 箱,抹 上石漆 和石油,将 孩子 放 在里头,把箱子搁 在 河 边 的芦荻中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, '孩子的姊姊 远远 站著,要知道 他 究竟怎么 样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, '法老 的女儿 来 到 河 边洗澡,她的使女们 在河 边 行走。她看见 箱子 在 芦荻 中,就打发 一个婢女 拿来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, '她打开 箱子,看见 那孩子。 孩子 哭了,她就可怜 他,说:「这是 希伯来人 的一个孩子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, '孩子的姊姊 对 法老 的女儿 说:「我去 在 希伯来 妇人 中叫 一个奶妈来,为你 奶 这孩子,可以不可以?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, '法老 的女儿 说:「可以。」童女 就去 叫了 孩子 的母亲来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, '法老 的女儿 对她 说:「你把 这 孩子 抱去,为我 奶他,我必 给你 工价。」妇人 就抱了 孩子 去奶他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, '孩子 渐长,妇人把他带 到法老 的女儿那里,就作了 她的 儿子。她给孩子起名 叫 摩西,意思说:「因 我把他从 水 里拉出来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, ' 后来,摩西 长大,他出去 到 他弟兄那里,看 他们的重担,见 一个 埃及人 打 希伯来人 的一个弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, '他左 右 观看,见 没有 人,就把 埃及人 打死了,藏 在沙土里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, '第二 天 他出去,见 有两 个希伯来 人 争斗,就对那欺负人的 说:「你为什么 打 你同族的人呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, '那人说:「谁 立你作 我们的 首领 和审判官呢?难道你 要 杀我,像 杀 那 埃及人吗?」摩西 便惧怕,说:「这事 必是 被人知道了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, '法老 听见 这 事,就想 杀 摩西,但摩西 躲避 法老,逃往米甸 地 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, '一日,他在 井 旁坐下。米甸 的祭司 有七 个女儿;她们来 打水,打满了 槽,要饮 父亲 的群羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, '有牧羊的人 来,把她们赶走了,摩西 却起来 帮助她们,又饮了 她们的群羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, '她们来 到 父亲 流珥那里;他说:「今日 你们为何 来 得这么快呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, '她们说:「有一个 埃及人 救我们 脱离牧羊人 的手,并且 为我们 打 水 饮了 群羊。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, '他对 女儿们 说:「那个 人在哪里?你们为什么 撇下 他呢?你们去请 他 来吃 饭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, '摩西 甘心 和 那人 同住;那人把 他的女儿 西坡拉 给 摩西为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, '西坡拉生了 一个儿子,摩西给他 起名 叫 革舜,意思说:「因 我在 外邦 作了 寄居的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, '过了 多 年,埃及 王 死了。以色列 人 因 做苦工,就叹息 哀求,他们的哀声 达 于  神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, '神 听见 他们的哀声, 就记念 他与 亚伯拉罕、 以撒、 雅各 所立的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, '神 看顾 以色列 人, 也知道他们的苦情。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, ' 摩西 牧养 他岳父 米甸 祭司 叶忒罗 的羊群;一日领 羊群 往野 外去,到了 神 的山,就是何烈山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, '耶和华 的使者 从荆棘 里 火 焰中 向 摩西显现。摩西观看,不料,荆棘 被火 烧著, 却没有 烧毁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, '摩西 说:「我要 过去 看 这 大 异象,这荆棘 为何 没有 烧坏呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, '耶和华 神见 他过去 要看, 就从荆棘 里 呼叫 说:「摩西!摩西!」他说:「我在这里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, '神说:「不要 近 前来。当把 你脚 上的鞋 脱下来,因为 你 所 站 之地 是 圣 地」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, '又说:「我 是你父亲的 神,是亚伯拉罕的 神,以撒的 神,雅各的 神。」摩西 蒙上 脸,因为 怕 看 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, '耶和华 说:「 我的百姓 在埃及 所 受的困苦,我实在 看见了; 他们因 受督工 的辖制所发的哀声,我也听见了。我原 知道 他们的痛苦, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, '我下来 是要救他们 脱离埃及人 的手,领他们 出了 那 地,到 美好、 宽阔、流 奶 与蜜 之地,就是到 迦南人、赫人、亚摩利人、比利洗人、希未人、耶布斯人 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, '现在 以色列 人 的哀声 达 到我耳中,我也 看见 埃及人 怎样 欺压 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, '故此,我要打发你 去 见 法老,使你可以将 我的百姓 以色列 人 从埃及 领出来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, '摩西 对 神 说:「我 是什么人,竟 能去 见 法老, 将 以色列 人 从埃及 领出来呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, '神说:「 我必 与你同在。你将 百姓 从埃及 领出来之后,你们必在 这 山 上 事奉 我;这 就是 我 打发你去 的证据。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, '摩西 对 神 说:「 我 到 以色列 人那里,对他们 说:『你们祖宗的 神 打发我 到你们这里来。』他们若问我 说:『他叫什么 名字?』我要对他们 说 什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, '神 对 摩西 说:「我是 自有永有的」;又说:「你要对以色列 人 这样 说:『那自有的 打发我 到你们这里来。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, '神 又 对 摩西 说:「你要对 以色列 人 这样 说:『耶和华─你们祖宗的 神,就是亚伯拉罕的 神,以撒的 神,雅各的 神,打发我 到你们 这里来。』耶和华是我的名,直到永远;这 也是我的纪念,直到万 代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, '你去 招聚 以色列 的长老,对他们 说:『耶和华-你们祖宗的 神,就是亚伯拉罕的 神,以撒的 神,雅各的 神,向我 显现,说:我实在 眷顾了 你们,我也看见埃及 人怎样 待 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, '我也说:要将你们 从埃及 的困苦 中领出来,往 迦南人、赫人、亚摩利人、比利洗人、希未人、耶布斯人 的地去,就是到 流 奶 与蜜 之地。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, '他们必听 你的话。你 和以色列 的长老 要去 见 埃及 王,对他 说:『耶和华─希伯来人的 神 遇见了 我们,现在 求 你容我们往旷野 去,走三 天 的路程,为要祭祀 耶和华─我们的 神。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, '我 知道 虽 用大能 的手,埃及 王 也不 容 你们 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, '我必伸 手 在埃及 中间 施行 我一切的 奇事,攻击那地,然后 他才容你们 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, '我必叫 你们 在埃及人 眼 前蒙 恩, 你们去 的时候 就不至于  空手 而去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, '但各妇女 必向她的邻舍,并居住 在她家里的女人,要 金 器 银 器 和衣裳,好给 你们的儿 女 穿戴。这样你们就把 埃及人 的财物夺去了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, '摩西 回答 说:「他们 必不 信 我,也不 听 我的话,必 说:『耶和华 并没有 向你 显现。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, '耶和华 对 摩西说:「你手 里是什么?」他说:「是杖。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, '耶和华说:「丢 在地上。」他一丢 下去,就变作 蛇;摩西 便跑开 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, '耶和华 对 摩西 说:「伸出 手来,拿 住牠的尾巴, 牠必在你手 中仍变为 杖; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, '如此好叫 他们信 耶和华─他们祖宗的 神,就是亚伯拉罕的 神,以撒的 神,雅各的 神,是向你 显现了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, '耶和华 又 对他 说:「 把手 放 在怀里。」他就把手 放 在怀里,及至抽出来,不料,手 长了大痲疯,有雪那样白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, '耶和华说:「再 把手 放 在 怀里。」他就再把手 放 在 怀里,及至从怀 里抽出来,不料,手已经复原,与周身的肉一样; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, '又说:「倘或 他们不 听 你的话,也不 信 头一 个神迹,他们必信 第二 个神迹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, ' 这 两 个神迹 若 都 不 信,也不 听 你的话,你就从河 里取 些水,倒 在旱地上, 你从 河 里取 的水 必在旱地 上变作 血。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, '摩西 对 耶和华 说:「主 啊,我 素日 不是 能言 的人,就是 从 你对 仆人 说话 以后,也是这样。我 本是 拙 口 笨 舌的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, '耶和华 对他 说:「谁 造 人的 口呢? 谁 使 人口哑、 耳聋、 目明、 眼瞎呢?岂不是 我─耶和华吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, '现在 去吧,我 必 赐 你口才,指教你 所 当说的话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, '摩西说:「主 啊,你愿 意 打发谁,就打发谁去吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, '耶和华 向摩西 发 怒 说:「不是 有你的哥哥 利未人 亚伦吗?我知道 他 是能 言的; 现在 他 出来 迎接你,他一见你,心 里就欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, '你要将 当说 的话 传 给他;我 也要 赐 你 和 他口才,又要指教 你们 所 当行的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, '他 要替你 对 百姓 说话;你要 以他 当作 口,他要以你 当作 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, '你手里 要拿 这 杖, 好行 神迹。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, '于 是,摩西 回 到 他岳父 叶忒罗那里,对他 说:「求 你容我回 去 见 我在埃及 的弟兄,看 他们还 在不在。」叶忒罗 对摩西 说:「你可以平平安安地 去吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, '耶和华 在米甸 对 摩西 说:「你要回 埃及 去,因为 寻索 你命 的人 都 死了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, '摩西 就带著 妻子 和 两个儿子,叫他们骑 上 驴,回 埃及 地去。摩西 手里 拿著 神 的杖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, '耶和华 对 摩西 说:「你回 到 埃及的时候,要留意将 我指示你 的一切 奇事 行 在法老 面前。但我 要使(或译:任凭;下同)他的心 刚硬,他必不 容 百姓 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, '你要对 法老 说:『耶和华 这样 说:以色列 是我的儿子,我的长子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, '我对你 说过:容 我的儿子 去,好事奉我。你还是不肯 容他去。看哪,我 要杀 你的长子。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, ' 摩西在路 上住宿的地方,耶和华 遇见他,想要 杀他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, '西坡拉 就拿 一块火石,割下 他儿子 的阳皮,丢 在摩西脚前,说:「你 真是 我的 血 郎了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, '这样,耶和华才放了 他。西坡拉说:「你因割礼 就是血 郎了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, '耶和华 对 亚伦 说:「你往旷野 去 迎接 摩西。」他就去,在 神 的山 遇见摩西,和他 亲嘴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, '摩西 将 耶和华 打发 他所说的 言语 和 嘱咐 他所行的 神迹 都 告诉了 亚伦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, '摩西、亚伦 就去 招聚 以色列 的众 长老。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, '亚伦 将 耶和华 对 摩西 所 说 的一切 话 述说了一遍,又在百姓 眼前 行了 那些神迹, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, '百姓 就信了。以色列 人 听见 耶和华 眷顾 他们, 鉴察 他们的困苦,就低头 下拜。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, '后来 摩西、亚伦 去 对 法老 说:「耶和华─以色列的 神 这样 说:『容 我的百姓 去,在旷野 向我 守节。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, '法老 说:「耶和华 是谁, 使我听 他的话,容 以色列人 去呢?我不 认识 耶和华,也 不 容 以色列人 去!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, '他们说:「希伯来人的 神 遇见了 我们。求 你容我们往旷野 去,走三 天 的路程,祭祀 耶和华─我们的 神,免得 他用瘟疫、 刀兵 攻击我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, '埃及 王 对他们 说:「摩西、亚伦!你们为什么 叫 百姓 旷 工呢?你们去 担你们的担子吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, ' 又说:「看哪,这地 的以色列人 如今 众多,你们竟叫他们 歇下 担子!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, '当 天,法老 吩咐 督工的 和 官长 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, '「你们不可 照 常 把草 给 百姓 做 砖,叫他们 自己 去 捡 草。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, ' 他们 素常 做 砖 的数目,你们仍旧向他们 要,一点 不可 减少;因为 他们 是懒惰的,所以 呼求 说:『容我们去 祭祀我们的 神。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, '你们要把更重的 工夫 加在 这些人 身上,叫他们劳碌,不 听 虚谎 的言语。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, '督工 的和官长 出来 对 百姓 说:「法老 这样 说:『我不 给 你们 草。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, '你们 自己 在哪里能找 草,就往那里 去 找吧!但 你们的工 一点 不可 减少。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, '于 是百姓 散 在埃及 遍 地,捡 碎秸 当作草。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, '督工的 催著 说:「你们一天 当完 一天的 工,与先前 有 草一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, '法老 督工的,责打 他所 派 以色列 人 的官长,说:「你们 昨天 今天 为什么 没有 照向来 的数目做砖、完 你们的工作呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, '以色列 人 的官长 就来 哀求 法老 说:「为什么 这样 待 你的仆人? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, '督工的不 把草 给 仆人,并且对我们 说:『做 砖吧!』看哪,你仆人 挨了打,其实是你百姓 的错。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, '但法老说:「你们 是懒惰的!你们是懒惰的!所以 说:『容我们去 祭祀 耶和华。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, '现在 你们去 做工吧!草 是不 给 你们的,砖 却要如数 交纳。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, '以色列 人 的官长 听说「你们每天 做砖 的工作 一点不可 减少」,就知道是 遭遇祸患了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, '他们离了 法老 出来,正遇见 摩西、 亚伦 站 在对面, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, '就向他们 说:「愿 耶和华 鉴察 你们,施行判断;因 你们使我们 在 法老 和他臣仆 面前 有了臭 名,把刀 递 在他们手 中杀我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, '摩西 回 到 耶和华那里,说:「主啊,你为什么 苦待 这 百姓呢?为什么 打发我去呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, '自从 我去 见 法老,奉你的名 说话,他就苦待 这 百姓,你一点也 没有 拯救 他们。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, '耶和华 对 摩西 说:「现在 你必看见 我向法老 所 行的事,使他因 我大能 的手 容以色列人去, 且把他们赶出 他的地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, '神 晓谕 摩西 说:「我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, '我从前向 亚伯拉罕、 以撒、 雅各 显现 为全能的 神;至于 我名 耶和华,他们 未曾 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, ' 我与他们 坚定所立的 约,要把 他们寄居的 迦南 地 赐 给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, '我 也 听见 以色列 人 被埃及人 苦待 的哀声,我也记念 我的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, '所以 你要对以色列 人 说:『我 是耶和华;我要用伸出来 的膀臂 重重地 刑罚 埃及人,救赎 你们 脱离 他们的重担, 不做他们的苦工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, '我要以 你们 为我的 百姓,我也要作 你们的 神。你们要知道 我 是耶和华─你们的 神,是救 你们 脱离 埃及人 之重担的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, ' 我起 誓 应许给 亚伯拉罕、以撒、雅各 的那地,我要把你们 领 进去,将 那地赐 给你们 为业。我 是耶和华。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, '摩西 将这话 告诉 以色列 人,只是他们因苦 工 愁烦,不肯 听 他的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, '「你进去 对 埃及 王 法老 说,要容 以色列 人 出 他的地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, '摩西 在耶和华 面前 说:「 以色列 人 尚且不 听 我的话,法老 怎肯 听我 这拙口笨舌的人呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, '耶和华 吩咐 摩西、 亚伦 往 以色列 人 和 埃及 王 法老那里去,把 以色列 人 从埃及 地 领出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, '以色列人家长 的名字记在下面。以色列 长子 流便 的儿子 是哈诺、法路、希斯仑 、迦米;这是 流便 的各家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, '西缅 的儿子 是耶母利、雅悯、阿辖、雅斤、琐辖,和迦南女子 的儿子 扫罗;这是 西缅 的各家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, '利未 众子 的名字 按著他们的后代 记在下面:就是革顺、哥辖、米拉利。利未 一生 的岁数 是一百 三十 七 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, '革顺 的儿子 按著家室 是立尼、示每。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, '哥辖 的儿子 是暗兰、以斯哈、希伯伦、乌薛。哥辖 一生 的岁数 是一百 三十 三 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, '米拉利 的儿子 是抹利 和母示;这是 利未的 家,都按著他们的后代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, '暗兰 娶了 他父亲的妹妹 约基别 为妻,她给他 生了 亚伦 和 摩西。暗兰 一生 的岁数 是一百 三十 七 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, '以斯哈 的儿子 是可拉、尼斐、细基利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, '乌薛 的儿子 是米沙利、以利撒反、西提利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, '亚伦 娶了 亚米拿达 的女儿,拿顺 的妹妹,以利沙巴 为妻,她给他 生了 拿答、 亚比户、 以利亚撒、 以他玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, '可拉 的儿子 是亚惜、以利加拿、亚比亚撒;这是 可拉 的各家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, '亚伦 的儿子 以利亚撒 娶了 普铁 的一个女儿 为妻,她给他 生了 非尼哈。这是 利未人 的家长,都按著他们的家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, '耶和华 说:「将 以色列 人 按著 他们的军队 从埃及 地 领出来。」这 是对那 亚伦、摩西说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, ' 对 埃及 王 法老 说 要将 以色列 人 从埃及 领出来的,就是这 摩西、亚伦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, '当 耶和华 在埃及 地 对 摩西 说话 的日子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, '他 向 摩西 说:「我 是耶和华;我 对你 说的 一切话,你都要告诉 埃及 王 法老。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, '摩西 在耶和华 面前 说:「看哪,我 是拙口笨舌的人,法老 怎肯 听 我呢?」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, '耶和华 对 摩西 说:「 我使你 在法老面前代替 神,你的哥哥 亚伦 是 替你说话的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, ' 凡 我所 吩咐你的,你 都要说。你的哥哥 亚伦 要对 法老 说,容 以色列 人 出 他的地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, '我 要使 法老 的心 刚硬,也要在埃及 地 多行 神迹 奇事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, '但法老 必不 听 你们;我要伸 手 重重地 刑罚 埃及,将 我的军队 以色列 民 从埃及 地 领出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, '我伸 手 攻击 埃及,将 以色列 人 从他们中间 领出来的时候,埃及人 就要知道 我 是耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, '摩西、亚伦 这样行;耶和华 怎样 吩咐 他们,他们就照样 行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, '摩西、亚伦 与 法老 说话的时候,摩西八十 岁,亚伦八十 三 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, '耶和华 晓谕 摩西、 亚伦 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, '「法老 若 对你们 说:『你们行 件奇事吧!』你就吩咐 亚伦 说:『 把 杖 丢 在法老 面前,使杖变作 蛇。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, '摩西、亚伦 进去 见 法老,就照 耶和华 所 吩咐 的行。亚伦 把 杖 丢 在法老 和臣仆 面前,杖就变作 蛇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, '于 是法老 召 了博士 和术士来;他们 是埃及 行法术的,也 用邪术 照样 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, '他们各人 丢下 自己的杖,杖就变作 蛇;但亚伦 的杖 吞了 他们的杖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, '法老 心 里刚硬,不肯 听从摩西、亚伦,正如耶和华 所 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, '耶和华 对 摩西 说:「法老 心 里固执,不肯 容百姓 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, ' 明日早晨, 他出来 往水边去,你要 往 河 边 迎接他,手里 要拿著 那 变过 蛇 的杖, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, '对他 说:『耶和华─希伯来人的 神 打发我 来见你,说:容 我的百姓 去,好在旷野 事奉我。 到 如今 你还是不 听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, '耶和华 这样 说: 我 要用我手里 的 杖 击打 河中 的 水,水就变作 血;因此,你必知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, '河里 的 鱼 必死,河 也要腥臭,埃及人 就要厌恶 吃 这河 里的水。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, '耶和华 晓谕 摩西说:「你对 亚伦 说:『把 你 的杖 伸 在 埃及 所有 的水以上,就是在 他们的江、 河、 池、 塘以上,叫水 都 变作 血。在埃及 遍 地,无论在木器中,石器中,都必有 血。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, '摩西、亚伦 就照 耶和华 所 吩咐 的行。亚伦在法老 和臣仆 眼前 举 杖 击打 河里 的 水,河里 的 水 都 变作 血了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, '河里 的 鱼 死了,河 也腥臭了,埃及人 就不 能 吃 这河 里的水;埃及 遍 地 都有了 血。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, '埃及 行法术的,也用邪术 照样 而行。法老 心 里刚硬,不肯 听摩西、亚伦,正如耶和华 所 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, '法老 转身 进 宫,也 不 把这事 放 在心上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, '埃及人 都 在河 的两边 挖地,要得水 喝,因为 他们不 能 喝 这河 里的水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, '耶和华 击打 河 以后 满了 七 天。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, '耶和华 吩咐 摩西 说:「你进去 见 法老,对他 说:『耶和华 这样 说:容 我的百姓 去,好事奉我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, '你 若 不肯 容他们去, 我 必使青蛙 糟蹋 你的四 境。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, '河 里要滋生 青蛙;这青蛙要上来 进 你的宫殿 和你的卧房,上 你的床榻,进你臣仆 的房屋,上你百姓的身上,进你的炉灶 和你的抟面 麺盆, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, ' 又要上 你 和你百姓 并你众 臣仆的身上。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, '耶和华晓谕 摩西 说:「你对 亚伦 说:『把 你 的杖 伸 在 江、 河、 池以上,使 青蛙 到 埃及 地 上来。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, '亚伦 便伸 杖 在 埃及 的诸水以上,青蛙 就上来,遮满了 埃及 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, '行法术的 也用他们的邪术 照样 而行,叫 青蛙 上了 埃及 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, '法老 召了 摩西、亚伦来,说:「请你们求 耶和华 使这青蛙 离开  我 和我的民,我就容 百姓 去 祭祀 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, '摩西 对法老 说:「任凭你吧, 我要何时 为你 和你的臣仆 并你的百姓 祈求,除灭 青蛙 离开 你 和你的宫殿 只 留 在河里呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, '他说:「明天。」摩西说:「可以照你的话吧,好叫 你知道 没有 像耶和华─我们 神的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, '青蛙 要离开  你 和你的宫殿,并你的臣仆 与你的百姓,只 留 在河里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, '于 是摩西、亚伦 离开  法老 出去。摩西 为 扰害 法老 的青蛙 呼求 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, '耶和华 就照摩西 的话 行。凡在 房里、 院中、 田 间的青蛙 都死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, '众人把青蛙 聚拢 成堆,遍地 就都腥臭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, '但法老 见 灾祸松缓,就硬著 心,不肯 听 他们,正如耶和华 所 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, '耶和华 吩咐 摩西 说:「你对 亚伦 说:『伸出 你的杖 击打 地上 的尘土,使尘土在 埃及 遍地 变作 虱子(或译:虼蚤;下同)。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, '他们就这样 行。亚伦 伸 杖 击打 地上 的尘土,就在人 身上和牲畜 身上有了 虱子;埃及 遍 地 的尘土 都 变成 虱子了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, '行法术的 也 用邪术 要生出 虱子来,却是不 能。于 是在人 身上和牲畜 身上都有了 虱子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, '行法术的 就对 法老 说:「这是 神 的手段。」法老 心里 刚硬,不肯 听摩西、亚伦,正如耶和华 所 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, '耶和华 对 摩西 说:「你清早 起来, 法老 来到 水边,你站 在他面前,对他 说:『耶和华 这样 说:容我的百姓 去,好事奉我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, ' 你若 不 容 我的百姓 去,我 要 叫 成群的苍蝇 到你 和你臣仆 并你百姓的身上,进你的房屋,并且 埃及人 的房屋 和他们 所住的 地 都要满了 成群的苍蝇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, '当那 日,我必分别 我百姓 所 住的 歌珊 地,使那里 没 有 成群的苍蝇,好叫 你知道 我 是天下 的耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, '我要将 我的百姓 和 你的百姓 分别 出来。明天 必有 这 神迹。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, '耶和华 就这样 行。苍蝇 成了大群,进入 法老 的宫殿,和他臣仆 的房屋;埃及 遍 地 就因 这成群的苍蝇 败坏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, '法老 召了 摩西、亚伦来,说:「你们去,在这地 祭祀你们的 神吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, '摩西 说:「这样 行 本不 相宜,因为 我们要把埃及人 所厌恶的 祭祀 耶和华─我们的 神;若 把 埃及人 所厌恶的 在他们眼前 献为祭,他们岂不 拿石头打死我们吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, '我们要往旷野 去,走三 天 的路程,照著耶和华─我们 神 所 要吩咐 我们 的祭祀他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, '法老 说:「我 容你们 去,在旷野 祭祀 耶和华─你们的 神;只是 不要 走 得很 远。求你们为我 祈祷。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, '摩西 说:「 我 要出去 求 耶和华,使成群的苍蝇 明天 离开  法老 和法老的臣仆 并法老的百姓;法老 却 不可 再 行诡诈,不容 百姓 去 祭祀 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, '于 是摩西 离开  法老 去求 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, '耶和华 就照摩西 的话 行,叫成群的苍蝇 离开  法老 和他的臣仆 并他的百姓,一 个也没有 留下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, '这 一次 法老 又 硬著 心,不 容 百姓 去。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, '耶和华 吩咐 摩西 说:「你进去 见 法老,对他 说:『耶和华─希伯来人的 神 这样 说:容 我的百姓 去,好事奉我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, ' 你 若 不肯 容他们去,仍旧 强留 他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, ' 耶和华 的手 加在 你田间 的牲畜上,就是 在马、驴、骆驼、牛群、羊群上,必有重重的 瘟疫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, '耶和华 要分别 以色列 的牲畜 和 埃及 的牲畜,凡 属以色列 人的,一样 都不 死。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, '耶和华 就定了 时候,说:「明天 耶和华 必在此地 行 这 事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, '第二天,耶和华 就行 这 事。埃及 的牲畜 几乎都 死了,只是以色列 人 的牲畜,一个 都没有 死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, '法老 打发人去看,谁知 以色列人 的牲畜 连一个 都 没有 死。法老 的心 却是固执,不 容 百姓 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, '耶和华 吩咐 摩西、 亚伦 说:「你们取 几捧 炉 灰,摩西 要在法老 面前 向天 扬起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, '这灰要在 埃及 全 地 变作 尘土,在 人 身上和 牲畜 身上成了 起 泡 的疮。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, '摩西、亚伦取了 炉 灰,站 在法老 面前。摩西 向天 扬起来,就在人 身上和牲畜 身上成了 起 泡 的疮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, '行法术的 在摩西 面前 站立 不 住, 因为 在他们 身上和一切 埃及人 身上都有 这疮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, '耶和华 使 法老 的心 刚硬,不 听 他们,正如耶和华 对 摩西 所 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, '耶和华 对 摩西 说:「你清早 起来,站 在法老 面前,对他 说:『耶和华─希伯来人的 神 这样 说:容 我的百姓 去,好事奉我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, '因为 这 一次 我 要 叫 一切 的灾殃 临到 你 和你臣仆 并你百姓的身上,叫 你知道 在普 天下 没有 像我的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, '我若 伸 手 用瘟疫 攻击 你 和 你的百姓,你早就从 地 上除灭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, '其实,我叫 你存立,是特要 向你显 我的大能,并要 使我的名 传 遍 天下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, '你还 向我的百姓 自高,不 容他们去吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, '到明天 约在这时候,我 必叫重大 的冰雹 降下, 自从 埃及 开 国以来,没 有 这样的冰雹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, '现在 你要打发 人把 你的牲畜 和 你田间 一切所有的 催进来;凡 在田 间 不 收回 家的,无论 是人 是牲畜,冰雹 必降 在他们身上,他们就必死。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, '法老 的臣仆中,惧怕 耶和华 这话的,便叫 他的奴仆 和 牲畜 跑 进 家来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, '但那 不 把 耶和华 这话 放 在心上的,就将 他的奴仆 和 牲畜 留 在田里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, '耶和华 对 摩西 说:「你向 天 伸 杖,使埃及 遍 地 的人 身上 和牲畜 身上,并田 间各样 菜蔬 上,都有 冰雹。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, '摩西 向 天 伸 杖,耶和华 就打 雷 下雹,有火 闪 到地上;耶和华 下 雹 在 埃及 地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, '那时, 雹 与火 搀 杂,甚是 厉害, 自从 埃及 成 国以来,遍 地 没 有 这样的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, '在埃及 遍 地,雹 击打了 田间 所有 的人 和 牲畜, 并 一切的 菜蔬,又打坏 田 间一切 的树木。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, '惟独 以色列 人 所 住的歌珊 地 没 有 冰雹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, '法老 打发 人召 摩西、亚伦来,对他们 说:「这一次 我犯了罪了。耶和华 是公义的;我 和我的百姓 是邪恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, '这 雷轰 和冰雹 已经 够了。请你们求 耶和华,我就容你们 去,不 再 留住你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, '摩西 对他 说:「我一出 城,就要向 耶和华 举 手祷告;雷 必止住,也不 再 有 冰雹,叫 你知道 全地 都是属耶和华的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, '至于 你 和你的臣仆,我知道 你们还是不 惧怕 耶和华 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, '(那时,麻 和大麦 被雹击打;因为 大麦 已经吐穗,麻 也开 了花。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, '只是小麦 和粗麦 没有 被击打,因为 还没有长成。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, '摩西 离了 法老 出 城,向 耶和华 举 手祷告;雷 和雹 就止住,雨 也不再 浇 在地上了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, '法老 见 雨 和雹 与雷 止住,就越发 犯罪;他 和他的臣仆 都硬著 心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, '法老 的心 刚硬,不 容 以色列 人 去,正如耶和华 藉 借著 摩西 所 说的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, '耶和华 对 摩西 说:「你进去 见 法老。 我 使 他 和 他臣仆 的心 刚硬,为要 在他们中间 显 我这些 神迹, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, '并要叫 你将 我向埃及 人所 做的事,和 在他们中间 所 行 的神迹,传 于 你儿子 和你孙子 的耳中,好叫你们知道 我 是耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, '摩西、亚伦 就进去 见 法老,对他 说:「耶和华─希伯来人的 神 这样 说:『你在我面前 不肯 自卑 要到 几时呢?容我的百姓 去,好事奉我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, ' 你 若 不肯 容 我的百姓 去,明天 我 要使蝗虫 进 入你的境内, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, '遮满 地 面,甚至看 不见 地,并且吃 那 冰雹 所剩的 和 田 间 所长 的一切 树木。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, '你的宫殿 和你众 臣仆 的房屋,并一切 埃及人 的房屋,都要被蝗虫占满了; 自从 你祖宗 和你祖宗 的祖宗 在 世以来,直到 今日,没有 见过 这样的灾。』」摩西就转身 离开  法老 出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, '法老 的臣仆 对 法老说:「这 人为 我们的 网罗 要到 几时呢?容 这些人 去 事奉 耶和华─他们的 神吧! 埃及 已经败坏了,你还不 知道吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, '于 是 摩西、 亚伦 被召回来 见 法老;法老对他们 说:「你们去 事奉 耶和华─你们的 神;但那要去 的是 谁呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, '摩西 说:「我们要和我们老的 少的、儿子 女儿 同去,且把羊群 牛群 一同带去,因为 我们 务要向耶和华 守节。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, '法老对他们 说:「我容你们 和 你们妇人孩子 去 的时候,耶和华 与你们 同在吧!你们要谨慎;因为 有祸 在 你们眼前(或译:你们存著恶意), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, '不可 都去!你们这壮年人 去事奉 耶和华吧,因为 这是 你们 所求的。」于 是把他们 从 法老 面前 撵出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, '耶和华 对 摩西 说:「你向 埃及 地 伸 杖,使蝗虫 到 埃及 地 上来,吃 地 上一切 的菜蔬, 就是冰雹 所 剩的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, '摩西 就向 埃及 地 伸 杖,那 一 昼 一 夜,耶和华 使 东 风 刮在埃及地上;到了 早晨,东 风 把 蝗虫 刮了来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, '蝗虫 上来,落 在埃及 的四 境,甚是 厉害;以前 没 有 这样的,以后 也必没 有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, '因为这蝗虫遮 满 地 面,甚至地 都黑暗了,又吃 地 上一切 的菜蔬 和 冰雹 所 剩 树上 的果子。埃及 遍 地,无论是树木,是田间 的菜蔬,连一点 青的 也没有 留下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, '于 是法老 急忙 召了 摩西、亚伦来,说:「我得罪 耶和华─你们的 神,又得罪了你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, '现在 求你,只 这一次,饶恕 我的罪,求 耶和华─你们的 神 使我 脱离 这 一 次的死亡。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, '摩西就离开  法老 去求 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, '耶和华 转了 极 大 的西 风,把 蝗虫 刮起,吹入 红 海;在埃及 的四 境 连一 个 也没有 留下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, '但耶和华 使 法老 的心 刚硬,不 容 以色列 人 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, '耶和华 对 摩西 说:「你向 天 伸 杖,使 埃及 地 黑暗;这黑暗 似乎摸得著。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, '摩西 向 天 伸 杖,埃及 遍 地 就 乌黑 了三 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, '三 天之久,人不能 相 见,谁 也不敢 起来 离开 本处;惟有以色列 人 家 中都 有 亮光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, '法老 就召 摩西来,说:「你们去 事奉 耶和华;只是 你们的羊群 牛群 要留下;你们的妇人孩子 可以 和你们 同去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, '摩西 说:「你 总要 把祭物 和燔祭牲 交 给我们,使我们可以祭祀 耶和华─我们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, '我们的牲畜 也 要带去,连一蹄 也不 留下;因为 我们要从其中 取出来,事奉 耶和华─我们的 神。我们 未 到 那里,还不 知道 用什么 事奉 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, '但耶和华 使 法老 的心 刚硬,不 肯 容他们去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, '法老 对摩西 说:「你离开 我 去吧,你要小心,不要 再 见 我的面!因为 你见 我面 的那日 你就必死!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, '摩西 说:「你说 得好!我必不 再 见 你的面了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, '耶和华 对 摩西 说:「我再 使一样 的灾殃 临 到 法老 和 埃及,然后 他必容你们 离开  这地。他容你们 去的时候,总要 催逼 你们 都 从这地出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, '你要 传 于 百姓 的耳中,叫他们男 女 各人向 邻舍 要 金 器 银 器。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, '耶和华 叫百姓 在埃及人 眼前 蒙 恩,并且 摩西 在埃及 地、法老 臣仆,和百姓 的眼中 看为极 大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, '摩西 说:「耶和华 这样 说:『约到半 夜,我 必出去 巡行埃及 遍地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, '凡在埃及 地,从坐 宝座 的法老 直到 磨子 后 的 婢女 所有的 长子,以及一切 头生 的牲畜,都必死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, '埃及 遍 地 必有 大 哀号;从前 没 有 这样的,后来 也必 没有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, '至于  以色列中,无论是人 是 牲畜,连狗 也不 敢向他们摇 舌,好叫 你们知道 耶和华是将 埃及人 和 以色列人 分别出来。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, '你这 一切 臣仆 都要俯伏 来 见我,说:『求你 和 跟从你 的 百姓 都出去』,然后 我要出去。」于 是,摩西气忿忿地 离开  法老,出去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, '耶和华 对 摩西 说:「法老 必不 听 你们,使 我的奇事 在埃及 地 多起来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, '摩西、亚伦 在法老 面前 行了 这 一切 奇事;耶和华 使 法老的 心 刚硬,不 容 以色列 人 出离 他的地。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, '耶和华 在埃及 地 晓谕 摩西、 亚伦 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, '「你们要以本 月 为 正月,为 一年 之首。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, '你们吩咐 以色列 全 会众 说:本 月 初十日,各人 要按著父 家 取 羊羔,一家 一只。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, '若是 一家的人 太少,吃不了 一只羊羔,本人 就要和 他隔壁 的邻舍 共取一只。你们预备 羊羔,要按著人 数和 饭量 计算。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, '要 无残疾、一 岁 的公 羊羔,你们或从 绵羊 里取,或从 山羊里取,都可以。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, '要 留 到 本 月 十 四 日,在 黄昏的时候,以色列 全 会众 把羊羔 宰了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, '各家要取 点 血,涂 在 吃 羊羔 的 房屋 左右 的门框 上和 门楣上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, '当 夜 要吃 羊羔的肉;用火 烤了,与无酵饼 和 苦菜 同吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, '不可 吃 生的,断不可吃水 煮的,要 带著头、 腿、 五脏,用火 烤了吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, '不可 剩下 一点 留到 早晨;若留 到 早晨,要用火 烧了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, ' 你们吃 羊羔 当腰间 束带,脚上 穿鞋,手中 拿杖,赶紧地 吃;这是 耶和华的 逾越节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, '因为那 夜 我要巡行 埃及 地,把埃及 地 一切 头生的,无论是人 是 牲畜,都击杀了,又要败坏 埃及 一切 的神。我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, '这血 要在 你们 所 住的房屋 上 作 记号;我一见 这 血,就越过 你们去。我击杀 埃及 地头生的时候,灾殃 必不 临 到你们 身上灭你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, '「 你们 要记念 这 日,守 为耶和华的 节, 作为你们世世代代 永远 的定例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, '你们要吃 无酵饼 七 日。 头一 日 要把酵 从你们各家 中除去;因为 从头一 日起,到 第七 日为止,凡 吃 有酵之饼的, 必 从以色列 中剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, '头一 日 你们当有圣 会,第七 日 也当有 圣 会。这两日之内,除了 预备 各 人 所 要吃 的以外,无论何 工 都不可 做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, '你们要守 无酵节,因为 我正当 这 日 把 你们的军队 从埃及 地 领出来。所以,你们要守 这 日,作为世世代代 永远 的定例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, '从正 月 十 四 日 晚上,直到 二十 一 日 晚上,你们要吃 无酵饼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, '在你们各家中,七 日 之内不可 有 酵;因为 凡 吃 有酵之物的,无论是寄居的,是本 地的, 必 从以色列 的会 中剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, '有酵的物,你们都 不可 吃;在你们一切 住处 要吃 无酵饼。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, '于 是,摩西 召了 以色列 的众 长老来,对他们 说:「你们要按著家口 取 出 羊羔,把这逾越节的羊羔 宰了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, '拿 一把 牛膝草,蘸 盆里 的 血,打 在 门楣 上和 左右的 门框上。你们 谁 也不可 出 自己的房 门,直到 早晨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, '因为耶和华 要巡行 击杀 埃及人,他看见 血 在 门楣 上和 左右的 门框上, 就必越 过 那门,不 容 灭命的 进 你们的房屋,击杀你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, '这 例,你们要守 著,作为你们 和你们子孙 永远 的定例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, '日后,你们到了 耶和华 按著 所 应许 赐 给你们 的那地,就要守 这 礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, ' 你们的儿女 问你们 说:『行这 礼 是什么意思?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, '你们就说:『这是 献给耶和华 逾越节 的祭。 当以色列人在埃及的时候,他击杀 埃及人,越 过 以色列 人 的房屋,救了 我们各家。』」于 是百姓 低头 下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, '耶和华 怎样 吩咐 摩西、亚伦,以色列 人 就怎样 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, '到了 半 夜,耶和华 把埃及 地 所有的 长子,就是从坐 宝座 的法老,直到 被掳 囚在监里 之人的长子,以及一切 头生的 牲畜,尽都杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, '法老 和一切 臣仆,并埃及众 人,夜间 都起来了。在埃及 有 大 哀号, 无 一家 不 死一个人的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, '夜间,法老召了 摩西、亚伦来,说:「起来!连 你们 带 以色列 人,从我民 中 出去,依你们所说的,去 事奉 耶和华吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, '也依你们所 说的,连 羊群 牛群 带著 走吧!并要 为我 祝福。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, '埃及人 催促 百姓,打发他们 快快 出离 那地,因为 埃及人说:「我们都 要死了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, '百姓 就拿著 没有 酵 的生面 麺,把抟面 麺盆 包 在衣服中,扛在 肩头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, '以色列 人 照著摩西 的话 行,向埃及人 要 金 器、银 器,和衣裳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, '耶和华 叫百姓 在埃及人 眼前 蒙 恩,以致埃及人给他们所要的。他们就把 埃及人 的财物夺去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, '以色列 人 从兰塞 起行,往疏割去;除了 妇人孩子,步行的 男人 约有六 十万。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, '又有 许多 闲 杂人,并有羊群 牛群,和他们 一同上去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, '他们用 埃及 带出来 的 生面 麺 烤成 无酵 饼。这生面 麺原 没有 发起;因为 他们被催逼 离开 埃及,不 能 耽延,也 没有 为自己 预备 什么食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, ' 以色列 人 住 在埃及 共有 四 百 三十 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, ' 正满了 四 百 三十 年 的那 一 天, 耶和华 的军队 都 从埃及 地 出来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, '这 夜 是 耶和华的 夜;因耶和华领他们 出了埃及 地,所以当向耶和华 谨守, 是以色列 众 人 世世代代 该谨守的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, '耶和华 对 摩西、亚伦 说:「逾越节 的例 是这样:外邦 人 都 不可 吃 这羊羔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, '但各 人 用银子 买  的奴仆,既受了割礼 就 可以吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, '寄居的 和雇工人 都不可 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, '应当在一 个房子里 吃;不可 把一点 肉 从 房子 里带 到外头去。羊羔的骨头 一根也不可 折断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, '以色列 全 会众 都要守 这礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, '若 有外人 寄居 在你们中间,愿 向耶和华 守 逾越节,他 所有的 男子 务要受割礼,然后 才容他前来 遵守,他也就 像本 地人一样;但未受割礼的,都 不可 吃 这羊羔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, '本地人 和寄居 在你们中间 的外人 同归 一 例。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, '耶和华 怎样 吩咐 摩西、 亚伦,以色列 众 人 就怎样 行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, ' 正当 那 日,耶和华 将 以色列 人 按著 他们的军队,从埃及 地 领出来。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, '「以色列 中 凡 头生的,无论是人 是牲畜,都 是 我的,要分别为圣 归我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, '摩西 对 百姓 说:「你们要记念 从埃及 为奴 之家 出来 的 这 日,因为 耶和华 用大能 的手 将你们 从这地方 领出来。有酵的饼 都不可 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, '亚笔 月 间的这日是你们 出来 的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, '将来 耶和华 领 你进 迦南人、赫人、亚摩利人、希未人、耶布斯人 之地,就是 他向你的祖宗 起誓 应许给 你 那流 奶 与蜜 之地,那时你要在这 月 间守 这 礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, '你要吃 无酵饼 七 日,到第七 日 要向耶和华 守节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, '这 七 日之久,要吃 无酵饼;在你 四 境 之内不可 见 有酵的饼,也不可 见 发酵的物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, '当那 日,你要告诉 你的儿子 说:『这是 因 耶和华 在我出 埃及 的时候为我 所行的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, '这要 在 你手 上作记号,在 你额 上作纪念,使 耶和华 的律法 常 在你口中,因为 耶和华 曾用大能 的手 将你从埃及 领出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, '所以你每 年 要按著日期 守 这 例。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, '「将来,耶和华 照他向你 和你祖宗 所 起 的誓将你领 进 迦南人 之地,把这地赐 给你, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, '那时你要将一切 头生的,并 牲畜 中头生的,归 给耶和华; 公的 都要 属耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, '凡 头生的 驴,你要用羊羔 代赎;若 不 代赎,就要打折牠的颈项。凡你 儿子 中头生 的都 要赎出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, '日后, 你的儿子 问你 说:『这是 什么意思?』你就说:『耶和华 用大能 的手 将我们从埃及 为奴 之家 领出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, ' 那时 法老 几乎不容 我们去,耶和华 就把埃及 地 所有 头生的,无论是 人是 牲畜,都杀了。因此,我 把一切 头生 的公 牲畜献 给耶和华为祭,但将头生的 儿子 都 赎出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, '这要 在 你手 上作记号,在 你额 上作经文,因为 耶和华 用大能 的手 将我们从埃及 领出来。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, ' 法老 容 百姓 去的时候,非利士 地 的道路 虽 近, 神 却不 领他们从那里走;因为 神 说:「恐怕 百姓 遇见 打仗 后悔,就回 埃及去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, '所以 神 领 百姓 绕道而行,走红 海 旷野 的路。以色列 人 出埃及 地,都带著兵器 上去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, '摩西 把 约瑟 的骸骨 一同 带去;因为 约瑟曾叫 以色列 人 严严地 起誓,对他们说:「 神 必 眷顾 你们,你们要把 我的骸骨 从这里 一同 带上去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, '他们从疏割 起行,在旷野 边 的以倘 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, '日间,耶和华 在云 柱中 领 他们的 路;夜间,在火 柱中 光照 他们,使他们日 夜 都可以行走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, '日间 云 柱,夜间 火 柱,总不 离开  百姓 的面前。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, '「你吩咐 以色列 人 转回,安营 在比‧哈希录 前,密夺 和海 的中间,对著巴力‧洗分,靠近 海 边 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, '法老 必说:『以色列 人 在地中 绕迷了,旷野 把他们 困住了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, '我要使 法老 的心 刚硬,他要追赶 他们,我便在法老 和他全 军 身上得荣耀;埃及人 就知道 我 是耶和华。」于 是以色列人这样 行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, '有人告诉 埃及 王说:「百姓 逃跑。」法老 和他的臣仆 就向 百姓 变 心,说:「 我们容 以色列 人去,不再服事我们,这 做 的是什么事呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, '法老就预备 他的车辆,带领 军兵 同去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, '并带著 六 百 辆特选的 车 和埃及 所有的 车,每辆 都有 车兵长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, '耶和华 使 埃及 王 法老 的心 刚硬,他就追赶 以色列 人,因为以色列 人 是昂然无惧 地出埃及。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, '埃及人 追赶 他们,法老 一切的 马匹、车辆、马兵,与军兵 就在 海边上,靠近比‧哈希录,对著巴力‧洗分,在他们安营 的地方追上了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, '法老 临近的时候,以色列 人 举 目 看见 埃及人 赶来,就甚 惧怕, 向 耶和华 哀求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, '他们对 摩西 说:「难道 在埃及 没有 坟地,你把我们带 来死 在旷野吗?你为什么 这样 待 我们,将我们从埃及 领出来呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, '我们在埃及 岂没有 对你 说过, 不要 搅扰我们,容我们服事 埃及人吗?因为 服事 埃及人 比死 在旷野 还好。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, '摩西 对 百姓 说:「不要 惧怕,只管站住!看 耶和华 今天 向你们 所 要施行 的救恩。因为,你们今天 所 看见 的埃及人必 永远 不 再 看见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, '耶和华 必为你们 争战 ;你们 只管静默,不要作声。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, '耶和华 对 摩西 说:「你为什么 向我 哀求呢?你吩咐 以色列 人 往前走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, '你 举 手 向 海 伸 杖,把水分开 。以色列 人 要下海 中 走 干地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, '我 要使 埃及人 的心 刚硬,他们就跟著 下去。我要在法老 和他的全 军、车辆、马兵 上得荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, '我在法老 和他的车辆、马兵 上得荣耀的时候,埃及人 就知道 我 是耶和华了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, '在以色列 营 前 行走 神 的使者,转 到 他们后边去;云 柱 也从他们前边 转到 他们后边 立住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, ' 在 埃及 营 和以色列 营 中间 有 云柱,一边黑暗,一边发光,终 夜 两下 不得 相近。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, '摩西 向 海 伸 杖,耶和华 便用大 东 风,使 海 水一 夜 退去,水 便分开 , 海 就成了 干地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, '以色列 人 下海 中 走 干地,水 在他们 的左 右 作了墙垣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, '埃及人 追赶他们,法老 一切 的马匹、车辆,和马兵 都跟著 下 到 海 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, '到了 晨 更的时候,耶和华 从云 火 柱 中向 埃及 的军兵 观看,使 埃及 的军兵 混乱了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, '又使 他们的车 轮 脱落,难以 行走,以致埃及人 说:「我们从以色列人 面前 逃跑吧!因 耶和华 为他们 攻击我们了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, '耶和华 对 摩西 说:「你向 海 伸 杖,叫水 仍合 在 埃及人 并 他们的车辆、 马兵身上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, '摩西 就向 海 伸 杖,到了天 一亮,海 水仍旧复 原。埃及人 避 水逃跑的时候,耶和华 把 他们 推翻 在海 中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, '水 就回流,淹没了 车辆 和 马兵。那些跟著 以色列人下 海 法老 的全 军,连 一个 也没有 剩下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, '以色列 人 却在海 中 走 干地;水 在他们的 左 右 作了墙垣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, '当 日,耶和华 这样拯救 以色列 人脱离埃及人 的手,以色列 人看见 埃及人 的死尸 都在 海 边了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, '以色列 人看见 耶和华 向埃及人 所 行 的大 事, 就敬畏 耶和华,又信服他 和他的仆人 摩西。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, '那时,摩西 和以色列 人 向耶和华 唱 歌 说:我要向耶和华 歌唱,因 他大大 战 胜,将马 和骑马的 投 在海中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, '耶和华 是我的力量,我的诗歌,也成了 我的 拯救。这是我的 神,我要赞美他,是我父亲的 神,我要尊崇他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, '耶和华 是战  士;他的名 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, '法老 的车辆、军兵,耶和华已抛 在海中;他特选 的军长 都沉 于 红 海。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, '深水 淹没他们;他们如同 石头 坠 到深处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, '耶和华啊,你的右手 施展能力,显出荣耀;耶和华啊,你的右手 摔碎 仇敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, '你大发 威严,推翻 那些起来攻击你的;你发出 烈怒如火,烧灭他们 像烧碎秸一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, '你发鼻中 的气,水 便聚起成堆,大水 直立 如 垒,海 中 的深水 凝结。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, '仇敌 说:我要追赶,我要追上;我要分 掳物,我要在他们身上称 我的心愿 。我要拔出 刀来,亲手 杀灭他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, '你叫风 一吹,海 就把他们淹没;他们如铅 沉 在大 水之中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, '耶和华啊,众神之中,谁 能像你?谁 能像你─至圣 至荣,可颂 可畏,施行 奇事? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, '你伸出 右手,地 便吞灭他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, '你凭慈爱 领了 你所 赎 的百姓;你凭能力 引他们 到了 你的圣 所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, '外邦人 听见 就发颤;疼痛 抓住 非利士 的居民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, '那时,以东 的族长 惊惶,摩押 的英雄 被战 兢 抓住,迦南 的居民 心都 消化了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, '惊骇 恐惧 临 到他们。耶和华啊,因你膀臂 的大能,他们如石头 寂然不动,等候 你的百姓 过去,等候 你所 赎 的百姓 过去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, '你要将他们领进去,栽 于 你产业 的山上─耶和华啊,就是你为自己所造 的住 处;主啊,就是你手 所建立 的圣所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, '耶和华 必作王,直到永永远远! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, ' 法老 的马匹、车辆,和马兵 下到 海中,耶和华 使 海 水 回流,淹没他们;惟有以色列 人 在海 中 走 干地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, '亚伦 的姊姊,女先知 米利暗,手里 拿著 鼓;众 妇女 也跟她 出去 拿鼓 跳舞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, '米利暗 应声说:你们要歌颂 耶和华,因 他大大 战 胜,将马 和骑马的 投 在海中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, '摩西 领 以色列人 从红 海 往前行,到了 书珥 的旷野,在旷野 走了 三 天,找 不 著水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, '到了 玛拉,不 能 喝 那里 的水;因为 水苦,所以 那地名 叫 玛拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, '百姓 就向 摩西 发怨言,说:「我们喝 什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, '摩西呼求 耶和华,耶和华 指示他 一棵树。他把树丢 在 水里,水 就变甜了。耶和华在那里 为他们 定了 律例、典章,在那里 试验他们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, '又说:「你若 留意 听 耶和华─你 神 的话,又行 我眼中 看为正的事,留心听 我的诫命,守 我一切 的律例,我就不 将所 加与 埃及人的 疾病 加在 你身上,因为 我─耶和华 是医治你的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, '他们到了 以琳,在那里 有十 二 股水 泉,七十 棵棕树;他们就在 那里 的水 边安营。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, '以色列 全 会众 从以琳 起行,在出 埃及 后第二个 月 十 五 日 到了 以琳 和西奈 中间、汛 的 旷野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, '以色列 全 会众 在旷野 向 摩西、 亚伦 发怨言, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, ' 说:「巴不 得 我们早死 在埃及 地、耶和华 的手下;那时我们坐 在 肉 锅旁边,吃 得饱足。 你们将我们 领出来,到 这 旷野,是要叫 这 全 会众 都饿 死啊!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, '耶和华 对 摩西 说:「我 要将粮食 从 天 降 给你们。百姓 可以出去,每天 收 每天 的分,我好 试验他们 遵 不遵 我的法度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, '到 第六 天,他们要把 所 收进来的 预备好了,比 每天 所 收的多 一倍。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, '摩西、亚伦 对 以色列 众 人 说:「到了晚上,你们要知道 是耶和华 将你们 从埃及 地 领出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, '早晨,你们要看见 耶和华 的荣耀,因为耶和华听见 你们向 他 所发的怨言了。我们 算什么,你们竟 向我们 发怨言呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, '摩西 又说:「耶和华 晚上 必给 你们 肉 吃,早晨 必给你们食物 得饱;因为你们 向 耶和华 发 的 怨言,他都听见了。我们 算什么,你们的怨言 不是 向我们发的,乃是 向 耶和华发的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, '摩西 对 亚伦 说:「你告诉 以色列 全 会众 说:『你们就近 耶和华 面前,因为 他已经听见 你们的怨言了。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, ' 亚伦 正对 以色列 全 会众 说话的时候,他们向 旷野 观看,不料,耶和华 的荣光 在云中 显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, '「我已经听见 以色列 人 的怨言。你告诉 他们 说:『到 黄昏的时候,你们要吃 肉,早晨 必有食物 得饱,你们就知道 我 是耶和华─你们的 神。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, '到了 晚上,有鹌鹑 飞来,遮满了 营;早晨 在营 四围 的地上有 露水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, '露水 上升之后,不料,野地 面 上 有 如白霜 的小 圆物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, '以色列 人 看见,不 知道 是 什么,就彼此 对问说:「这 是 什么呢?」摩西 对他们 说:「这 就是 耶和华 给 你们 吃的 食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, '耶和华 所 吩咐的 是这样:你们要按著 各人 的饭量, 为帐棚里 的人,按著人 数 收起来,各 拿 一俄梅珥。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, '以色列 人 就这样 行;有多 收的,有少收的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, '及至用俄梅珥 量一量,多收的 也没有 余 馀,少收的 也没有 缺;各人 按著 自己的饭量 收取。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, '摩西 对他们 说:「所收的,不许 什么人 留 到 早晨。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, '然而他们不 听 摩西的话,内中有 留 到 早晨的,就生 虫 变臭了;摩西 便向他们 发怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, '他们每日 早晨,按著 各人 的饭量 收取,日头 一发热,就消化了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, '到 第六 天,他们收了 双倍 的食物,每人 两 俄梅珥。会众的 官长 来 告诉 摩西; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, '摩西对他们 说:「耶和华 这样 说:『明天 是圣 安息日,是向耶和华 守的圣安息日。 你们要烤 的 就烤了, 要煮 的 就煮了, 所 剩下的 都留 到 早晨。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, '他们就照 摩西 的吩咐 留 到 早晨,也不 臭,里头 也没 有 虫子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, '摩西 说:「你们今天 吃这个吧!因为 今天 是向耶和华 守的安息日; 你们在田野 必找 不著了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, '六 天 可以收取,第七 天 乃是安息日,那一天 必没 有了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, ' 第七 天, 百姓 中有人出去 收,什么也找 不著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, '耶和华 对 摩西 说:「你们不肯 守 我的诫命 和律法,要到 几时呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, '你们看!耶和华 既 将安息日 赐 给你们,所以 第六 天 他 赐 给你们 两天 的食物,第七 天 各人 要住 在自己的地方,不许 什么人 出去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, '于 是百姓 第七 天 安息了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, '这食物,以色列 家 叫 吗哪; 样子像芫荽 子,颜色是白的,滋味 如同搀蜜 的薄饼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, '摩西 说:「耶和华 所 吩咐 的是这样:『要将一满 俄梅珥 吗哪 留 到世世代代,使 后人可以看见 我当日将你们 领 出埃及 地,在旷野 所 给你们 吃的 食物。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, '摩西 对 亚伦 说:「你拿 一个 罐子,盛 一满 俄梅珥 吗哪,存 在耶和华 面前,要留 到世世代代。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, '耶和华 怎么 吩咐 摩西,亚伦就怎么行,把吗哪放 在法柜 前 存留。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, '以色列 人 吃 吗哪 共四十 年,直到 进了 有人居住 之地, 就是 迦南 的境界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, '(俄梅珥 就是 伊法 十分之一。)   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, '以色列 全 会众 都遵 耶和华 的吩咐,按著站口 从汛 的旷野 往前行,在利非订 安营。百姓 没有 水 喝, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, '所以 与 摩西 争闹,说:「给 我们 水 喝吧!」摩西 对他们 说:「你们为什么 与我 争闹?为什么 试探 耶和华呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, '百姓 在那里 甚渴,要喝水, 就向 摩西 发怨言,说:「你为什么 将我们从埃及 领出来,使我们 和 我们的儿女 并 牲畜 都渴 死呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, '摩西 就呼求 耶和华 说:「我向这 百姓 怎样 行呢?他们几乎 要拿石头打死我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, '耶和华 对 摩西 说:「你手里 拿著 你先前击打 河水 的杖,带领 以色列 的几个长老,从百姓 面前 走 过去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, '我 必在 何烈 的磐石 那里,站 在你面前。你要击打 磐石,从磐石里 必有水 流出来,使百姓 可以喝。」摩西 就在以色列 的长老 眼前 这样 行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, '他给那地方 起名 叫 玛撒(就是试探的意思),又叫米利巴(就是争闹的意思);因 以色列 人 争闹,又因 他们试探 耶和华,说:「耶和华 是在 我们中间 不是?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, '那时,亚玛力人 来 在利非订,和 以色列人 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, '摩西 对 约书亚 说:「你为我们 选出 人来,出去 和亚玛力人 争战 。明天 我 手里要拿著 神 的杖,站 在 山 顶上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, '于 是约书亚 照著摩西 对他 所 说的 话行,和亚玛力人 争战 。摩西、亚伦,与户珥 都上了 山 顶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, ' 摩西 何时 举 手,以色列人 就得胜,何时 垂 手,亚玛力人 就得胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, '但摩西 的手 发沉,他们就搬 石头来,放 在他以下,他就坐 在上面。亚伦 与户珥 扶著 他的手,一个 在这边,一个 在那边,他的手 就 稳住,直到 日 落的时候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, '约书亚 用 刀 杀了 亚玛力 王和 他的百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, '耶和华 对 摩西 说:「 我要将 亚玛力 的名号 从天 下 全然 涂抹了;你要将这 话写 在书上 作纪念,又念 给约书亚听。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, '摩西 筑了 一座坛,起名 叫「耶和华尼西」(就是耶和华是我旌旗的意思), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, '又说:「 耶和华 已经起了 誓, 必世世 代代 和亚玛力人 争战 。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, '摩西 的岳父,米甸 祭司 叶忒罗,听见 神 为摩西和 神的百姓 以色列 所 行 的一切事,就是 耶和华 将 以色列 从埃及 领出来的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, ' 便带著 摩西 的妻子 西坡拉,就是摩西从前 打发回去的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, '又 带著西坡拉的两个 儿子, 一个 名 叫革舜,因为 摩西说:「我在 外邦 作了 寄居的」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, '一个 名 叫以利以谢,因为他说:「我父亲的 神 帮助了我,救我 脱离法老 的刀。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, '摩西 的岳父 叶忒罗 带著摩西 的妻子 和两个儿子 来 到 神的 山,就是 摩西 在 旷野 安营 的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, '他对 摩西 说:「我 是你岳父 叶忒罗,带著你的妻子 和 两个 儿子 来 到你这里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, '摩西 迎接 他的岳父,向他下拜,与他 亲嘴,彼此 问 安,都进了 帐棚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, '摩西 将 耶和华 为 以色列的 缘故 向法老 和埃及人 所 行的 一切事,以及 路上 所 遭遇的 一切 艰难,并耶和华 怎样搭救他们,都述说 与他岳父听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, '叶忒罗 因 耶和华 待 以色列 的 一切 好处,就是 拯救他们 脱离埃及人 的手,便甚欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, '叶忒罗 说:「耶和华 是应当称颂的;他 救了 你们 脱离埃及人 和法老 的手, 将 这百姓 从埃及人 的手 下 救出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, '我现今在 埃及人向这百姓 发狂傲 的 事上 得知, 耶和华 比万 神 都大。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, '摩西 的岳父 叶忒罗 把 燔祭 和平安祭献给 神。亚伦 和以色列 的众 长老 都来了,与 摩西 的岳父在 神 面前 吃 饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, ' 第二天,摩西 坐著 审判 百姓,百姓 从 早 到 晚 都站 在 摩西的左右。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, '摩西 的岳父 看见 他 向百姓 所 做的 一切事,就说:「你 向百姓 做 的 是什么 事呢?你 为什么 独自 坐著,众 百姓 从 早 到 晚 都站 在你的左右呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, '摩西 对岳父 说:「这是因 百姓 到我这里 来 求问 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, '他们 有 事 的时候 就到我这里 来,我便在两造 之间 施行审判;我又叫他们知道 神 的律例 和 法度。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, '摩西 的岳父 说:「你 这 做的 不 好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, ' 你 和 这些 百姓 必 都疲惫;因为 这事 太重,你独自 一人办理 不 了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, '现在 你要听 我的话。我为你出个主意,愿  神 与你同在。你 要 替百姓到 神 面前, 将 案件 奏告 神; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, '又要将 律例 和 法度 教训 他们,指示 他们 当行的 道, 当做 的 事; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, ' 并要从 百姓 中拣选 有才能 的人,就是敬畏 神、诚实无妄、恨 不义之财 的人,派他们 作千夫 长、百夫 长、五十夫 长、十夫 长,管理百姓, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, '叫他们随 时 审判 百姓,大 事 都 要 呈 到你这里, 小 事 他们 自己可以审判。这样,你 就轻省些,他们也可以同 当此任。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, '你若 这样 行, 神 也这样吩咐你,你就能 受得住,这 百姓 也 都 平平安安 归 回 他们的住处。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, '于 是,摩西 听从 他岳父 的话,按著他 所 说的 去行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, '摩西 从 以色列人 中拣选了 有才能 的人,立 他们 为 百姓 的首领,作千夫 长、百夫 长、五十夫 长、十夫 长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, '他们随 时 审判 百姓,有难断的 案件 就呈 到 摩西那里,但各样 小 事 他们 自己审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, '此后,摩西 让 他的岳父 去,他就往 本地 去了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, '以色列 人 出 埃及 地以后,满了三个 月 的那 一天,就来到 西奈 的旷野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, '他们离了 利非订,来到 西奈 的旷野, 就在那里 的山 下 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, '摩西 到 神那里,耶和华 从 山上 呼唤 他 说:「你要这样 告诉 雅各 家,晓谕 以色列 人说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, '『我向埃及人 所 行的事,你们 都看见了,且看见我如鹰 将你们 背 在 翅膀上,带 来 归我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, '如今 你们若 实在 听从 我的话,遵守 我的约,就要在万 民 中作 属我的 子民,因为 全 地 都是我的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, '你们 要归我 作 祭司 的国度,为圣洁 的国民。』这些 话 你要告诉 以色列 人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, '摩西 去 召了 民间的 长老来,将 耶和华 所 吩咐他的 话 都 在他们面前 陈明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, '百姓 都 同声 回答 说:「凡 耶和华 所 说的,我们都要遵行。」摩西 就将 百姓的 话 回复 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, '耶和华 对 摩西 说:「 我 要在密 云中 临 到你那里,叫 百姓 在我与你 说话 的时候可以听见,也 可以永远 信 你了。」于 是,摩西 将 百姓 的话 奏告 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, '耶和华 又对 摩西 说:「你往 百姓 那里去,叫他们今天 明天 自洁,又叫他们洗 衣服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, '到第三 天 要 预备好了,因为 第三 天 耶和华 要在众 百姓 眼前 降临 在 西奈 山上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, '你要在山的四围 给 百姓 定界限,说:『你们 当谨慎,不可上 山去,也不可摸 山的边界;凡 摸 这山的,必 要治死他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, '不可 用手 摸 他, 必 用石头打死,或 用箭射 透;无论是 人 是 牲畜,都不得 活。到角声 拖长的时候,他们 才可到 山根来。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, '摩西 下 山 往 百姓那里去,叫 他们 自洁,他们就洗 衣服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, '他对 百姓 说:「到第三 天 要 预备好了。不可 亲近 女人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, '到了 第三 天 早晨,在 山 上有 雷轰、闪电,和密 云,并且角 声 甚 大, 营中 的百姓 尽都 发颤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, '摩西 率领 百姓 出 营 迎接 神,都站 在山 下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, '西奈 全 山 冒烟,因为 耶和华 在火中 降 于 山上。山的烟气 上腾,如烧窑 一般,遍 山 大大地 震动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, ' 角 声 渐渐地 高 而又高,摩西 就说话, 神 有声音 答应他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, '耶和华 降临 在 西奈 山 顶 上,耶和华 召 摩西 上 山 顶,摩西 就上去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, '耶和华 对 摩西 说:「你下去 嘱咐 百姓,不可闯过来 到 我 面前观看,恐怕 他们有 多人 死亡; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, '又 叫亲近 我 的祭司 自洁,恐怕 我 忽然出来击杀 他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, '摩西 对 耶和华 说:「百姓 不 能 上 西奈 山,因为 你 已经嘱咐 我们 说:『要在山的四围定界限,叫 山 成圣。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, '耶和华 对他 说:「下 去吧,你 要和亚伦 一同 上来;只是祭司 和百姓 不可 闯过来 上 到 我面前,恐怕 我忽然出来击杀 他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, '于 是摩西 下 到 百姓 那里告诉 他们。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, '神 吩咐 这 一切的 话 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, '「我 是耶和华─你的 神, 曾将你从埃及 地 为奴 之家 领出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, '「除了我以外,你 不可 有 别的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, '「不可 为自己 雕刻 偶像,也不可做什么 形像 仿佛 上 天、 下 地,和 地 底下、水中的百物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, '不可 跪拜 那些像,也不可 事奉它,因为 我 耶和华─你的 神 是忌邪的 神。恨我的,我必追讨 他的罪,自父 及 子,直到 三 四代; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, '爱我、守我 诫命的,我必向他们发 慈爱,直到千代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, '「不可 妄 称 耶和华─你 神 的名;因为 妄 称 耶和华名的,耶和华 必不 以 他 为无罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, '「当记念 安息 日,守为圣日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, '六 日 要劳碌 做 你一切的 工, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, '但第七 日 是向耶和华─你 神 当守的安息日。这一日你 和你的儿 女、仆 婢、牲畜,并 你城里 寄居的客旅,无论 何工 都不可 做; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, '因为 六 日之内,耶和华 造 天、 地、 海,和 其 中的 万物,第七 日 便安息,所以 耶和华 赐福 与 安息 日,定为圣日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, '「当孝敬 父 母,使 你的日子 在 耶和华─你 神 所 赐 你 的地 上得以长久。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, '「不可 杀人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, '「不可 奸淫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, '「不可 偷盗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, '「不可 作 假 见证 陷害人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, '「不可 贪恋 人 的房屋;也不可 贪恋 人 的妻子、仆 婢、牛 驴,并他 一切 所有的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, '众 百姓 见 雷轰、 闪电、 角 声、 山上 冒烟, 就都发颤,远远地 站立, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, '对 摩西 说:「求你 和我们 说话,我们必听;不要 神 和我们 说话,恐怕 我们死亡。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, '摩西 对 百姓 说:「不要 惧怕;因为 神 降临 是要 试验 你们,叫你们 时常 敬畏他,不致 犯罪。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, '于 是百姓 远远地 站立;摩西 就挨近 神 所在的 幽暗之中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, '耶和华 对 摩西 说:「你要向 以色列 人 这样 说:『你们 自己看见 我从 天上 和你们 说话了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, '你们不可 做 什么神 像与我相配,不可 为自己 做 金 银 的神像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, '你要为我 筑 土 坛,在上面 以 牛 羊 献 为 燔祭 和 平安祭。凡 记下 我名 的地方,我必到 那里 赐福给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, '你若 为我 筑 一座石 坛,不可 用凿成的石头,因 你在上头 一动 家具,就把坛污秽了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, '你上 我的坛,不可 用台阶,免得 露出 你的下体来。』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, '「你在百姓面前 所 要立 的典章 是这样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, '你若 买  希伯来人 作奴仆,他必服事 你六 年;第七 年他可以自由,白白地 出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, '他若 孤身 来 就可以孤身 去;他 若 有 妻,他的妻 就可以同他 出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, '他主人 若 给 他 妻子,妻子给他 生了 儿子 或 女儿,妻子 和儿女 要 归主人,他 要独自 出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, '倘或 奴仆 明 说:『我爱 我的主人 和 我的妻子 儿女,不 愿 意自由 出去。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, '他的主人 就要带他 到 审判官(或译: 神;下同)那里,又要带他 到 门前, 靠近 门框, 用锥子 穿 他的耳朵,他就永远 服事主人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, '「人 若 卖 女儿 作婢女,婢女不可 像男仆 那样 出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, '主人 选定她归自己, 若 不喜欢她,就要许她赎身;主人既然用诡诈 待她,就没有 权柄 卖 给外邦 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, '主人若 选定 她给自己的儿子,就当待 她 如同 女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, '若 另 娶一个,那女子的吃食、衣服,并好合的事,仍不可 减少。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, '若 不 向她 行 这 三样,她就可以不用 钱赎,白白地 出去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, '「打 人 以致打死的,必要 把他治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, ' 人若不是 埋伏著杀人,乃是 神 交 在他手中,我就设下 一个地方, 他可以往那里 逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, '人 若 任意 用诡计 杀了 他的邻舍,就是逃到 我的坛那里,也当捉去 把他治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, '「打 父 母的,必要 把他治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, '「拐带 人口,或是把人卖了,或是留 在他手下,必要 把他治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, '「咒骂 父 母的,必要 把他治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, '「人 若 彼此相争,这个 用石头 或 是拳头 打 那个,尚且不至于  死,不过躺卧 在床, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, '若 再能起来 扶 杖 而出,那打他的 可算无罪;但 要将他耽误的工夫 用钱赔补,并要将他全然 医好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, '「人 若 用棍子 打 奴仆 或 婢女,立时死 在他的手 下,他必要 受刑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, ' 若 过 一 两天才死,就可以不 受刑,因为 是 用钱买 的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, '「人 若 彼此争斗,伤害 有孕 的妇人,甚至坠 胎,随后却无 别害,那伤害她的,总要 按妇人 的丈夫 所 要的,照审判官 所断的,受罚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, '若 有 别害,就要以 命 偿 命, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, '以眼 还 眼,以牙 还 牙,以手 还 手,以脚 还 脚, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, '以烙 还 烙,以伤 还 伤,以打 还 打。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, '「人 若 打 坏了 他奴仆 或是 婢女 的一只眼,就要因 他的眼 放他去 得以自由。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, '若 打 掉了他奴仆 或是 婢女 的一个牙,就要因 他的牙 放他去 得以自由。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, '「牛 若 触 死 男人 或是 女人,总要 用石头打死 那牛,却不可 吃 牠的肉;牛 的主人 可算无罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, '倘若 那 牛 素来 是触人的,有人报告了 牛主,他竟不 把牛拴著,以致把男人 或是 女人 触死,就要用石头打死 那牛,牛主 也 必治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, '若 罚 他 赎命的价银,他必照 所罚的 赎 他的 命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, '牛无论 触了 人的儿子 或是 女儿,必照这 例 办理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, '牛 若 触了 奴仆 或是 婢女,必将银子 三十 舍客勒 给 他们的主人,也要用石头把牛 打死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, '「人 若 敞著 井口,或 挖 井 不 遮盖,有牛 或 驴 掉 在里头, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, '井 主 要拿 钱 赔还 本主人,死 牲畜要 归自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, '「这人 的牛 若 伤了 那人的 牛,以至于 死,他们要卖了 活 牛,平分 价值,也要 平分 死牛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, '人若 知道 这牛 素来 是 触人的,主人 竟不 把牛拴著,他必要 以 牛 还 牛,死 牛要 归自己。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, '「人 若 偷 牛 或 羊,无论 是宰了,是卖了,他就要以 五 牛 赔 一牛,四 羊 赔 一羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, '人若 遇见 贼 挖窟窿,把贼打了,以至于 死,就不能 为他 有流血的罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, '若 太阳 已经出来,就为他 有流血的罪。贼若被拿,总要 赔还。若 他 一无所有,就要被卖,顶他所偷的物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, '若 他所偷的,或牛,或 驴,或 羊,仍 在他手下 存活,他就要加倍 赔还。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, '「人 若 在田 间或 在葡萄园 里放牲畜,任凭 牲畜 上别人 的田里 去吃,就必拿自己田 间上好的 和葡萄园 上好的 赔还。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, '「若 点 火 焚烧 荆棘,以致将别人堆积的禾捆, 站著的禾稼,或是 田园,都烧尽了,那点 火 的必要 赔还。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, '「人 若 将银钱 或 家具 交 付 邻舍 看守,这物从那人 的家 被偷去,若 把贼 找到了,贼要加倍 赔还; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, '若 找 不到 贼,那家 主 必就近 审判官,要看看他 拿了 原主 的物件 没有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, '「两个人 的案件,无论 是为什么 过犯,或是为 牛,为 驴,为 羊,为 衣裳,或是为 什么 失掉之物,有一人 说:『 这 是我的』,两造就要 将案件 禀告 审判官,审判官 定 谁有罪,谁就要加倍 赔还。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, '「人 若 将驴,或 牛,或 羊,或 别的 牲畜,交 付 邻舍 看守,牲畜或死,或 受伤,或 被赶去,无人 看见, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, '那看守的人要 凭著耶和华 起誓,手 里未曾 拿 邻舍 的物,本主 就要罢休,看守的人不必 赔还。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, '牲畜若 从看守的那里 被 偷去,他就要赔还 本主; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, '若 被野兽 撕碎,看守的要带来 当作证据,所撕的 不必 赔还。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, '「人 若 向 邻舍 借什么,所借的或受伤,或 死,本主 没有 同在一处,借的人总要 赔还; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, '若 本主 同在一处,他就不必 赔还;若 是 雇的,也不必赔还,本是为雇价 来的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, '「人 若 引诱 没有 受聘 的处女,与她 行淫,他总要交出 聘礼,娶她 为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, '若 女子的父亲 决 不肯 将女子给 他,他就要按处女 的聘礼,交出 钱来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, '「行邪术的女人,不可 容她存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, '「凡 与 兽 淫合的,总要 把他治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, '「祭祀 别神,不 单单 祭祀耶和华的,那人必要灭绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, '「不可 亏负 寄居的,也不可 欺压他,因为 你们在埃及 地 也作过 寄居的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, '不可 苦待 寡妇 和孤儿; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, '若是 苦待 他们 一点, 他们向我 一哀求,我总要 听 他们的哀声, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, '并要发 烈怒,用刀 杀 你们,使你们的妻子 为 寡妇,儿女 为孤儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, '「 我民 中有贫穷人 与你同住,你若 借 钱 给他,不 可 如放债的 向他 取 利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, '你即 或 拿 邻舍 的衣服 作当头,必在日 落 以先 归还 他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, '因 他 只有 这一件当盖头,是 他盖身 的衣服,若是没有,他拿什么 睡觉呢? 他哀求 我,我就应允,因为 我 是有恩惠的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, '「不可 毁谤 神;也不可 毁谤 你百姓 的官长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, '「你要从你庄稼中的谷 和酒醡中滴出来的酒拿来献上,不可 迟延。「你要将头生的 儿子 归 给我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, '你牛 羊头生的,也要 这样;七 天 当 跟著 母,第八 天 要归 给我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, '「你们要在我 面前为 圣洁 的人。因此,田间 被野兽 撕裂牲畜的肉,你们不可 吃,要丢 给狗吃。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, '「不可 随伙 夥布散 谣 言;不可 与 恶人 连 手 妄 作 见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, '不可 随 众 行恶;不可 在 争讼的事 上随 众 偏行,作见证 屈枉正直; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, '也不可 在争讼的事 上偏护 穷人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, '「若 遇见 你仇敌 的牛 或 驴 失迷了路,总要 牵回来 交给他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, '若 看见 恨你人的 驴 压卧 在重驮 之下,不可 走开 ,务要 和驴主一同 抬开 重驮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, '「不可 在穷人 争讼的事 上屈枉 正直。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, '当远离 虚假 的事。不可 杀 无辜 和有义的人,因 我必不 以恶人 为义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, '不可 受 贿赂;因为 贿赂 能叫明眼人 变瞎了,又能颠倒 义人 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, '「不可 欺压 寄居的;因为 你们 在埃及 地 作过 寄居的,知道 寄居的 心。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, '「六 年 你要耕种 田地,收藏 土产, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, '只是第七 年要叫地歇息,不耕不种,使你民中的 穷人 有吃的;他们所剩下的, 野兽 可以吃。你的葡萄园 和橄榄园 也要照样 办理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, '「六 日 你要做 工,第七 日 要安息,使 牛、驴 可以歇息,并使你婢女 的儿子 和寄居的 都可以舒畅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, '「凡 我对你们 说的话,你们要谨守。别 神 的名,你不可 提,也不可从 你口 中 传说。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, '「一年 三 次,你要向我 守节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, '你要守 除酵 节,照我所 吩咐你的,在亚笔 月 内所定的日期,吃 无酵饼 七 天。谁也不可 空手 朝见 我,因为 你是这月 出了 埃及。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, '又要守收割 节,所收的是你田间 所 种、劳碌 得来初熟之物。并在年 底 收藏,要守收藏 节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, '一切 的男丁 要一年 三 次 朝见 主 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, '「不可 将我祭牲 的血 和 有酵的饼 一同献上;也不可 将我节上祭牲 的脂油 留 到 早晨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, '「地里 首先 初熟之物 要送 到耶和华─你 神 的殿。「不可 用山羊羔母 的奶 煮 山羊羔。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, '「看哪,我 差遣 使者 在你前面,在路上 保护你,领你 到 我所 预备的 地方去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, '他是 奉 我名来的;你们要在他面前 谨慎,听从 他的话,不可 惹(或译:违背)他,因为 他必不 赦免 你们的过犯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, '「你若 实在 听从 他的话,照著我一切 所 说的 去行,我就向 你的仇敌 作仇敌,向 你的敌人 作敌人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, '「 我的使者 要在你前面 行,领你 到 亚摩利人、赫人、比利洗人、迦南人、希未人、耶布斯人那里去,我必将他们剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, '你不可 跪拜 他们的神,不可 事奉他,也不可 效法 他们的行为,却要 把神像尽行 拆毁,打 碎 他们的柱像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, '你们要事奉 耶和华─你们的 神,他必赐福 与 你的粮 与 你的水,也必从你们中间 除去 疾病。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, '你境内 必没 有 坠胎的,不生产的。我要使你满了 你年日的 数目。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, '凡你所到的地方,我要 使 那里的众 民 在你面前 惊骇,扰乱,又要 使 你一切 仇敌 转背逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, '我要打发 黄蜂 飞在你前面,把 希未人、 迦南人、 赫人 撵出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, '我不 在一 年 之内将他们从你面前 撵出去,恐怕 地 成为 荒凉,野地 的兽 多起来 害你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, '我要渐 渐地 将他们从你面前 撵出去,等到 你的人数加多,承受 那地为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, '我要定 你的境界,从红 海 直到 非利士 海,又从旷野 直到 大河。 我要将 那地 的居民 交 在你手中,你要将他们从你面前 撵出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, '不可 和他们 并他们的神 立 约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, '他们不可 住 在你的地上,恐怕 他们使你 得罪 我。你若 事奉 他们的神,这必 成为 你的 网罗。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, '耶和华对 摩西 说:「你 和亚伦、拿答、亚比户,并以色列 长老 中的七十人,都要上 到 我这里来,远远地 下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, '惟独 你 可以亲近 耶和华;他们 却不可 亲近;百姓 也不可 和你 一同上来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, '摩西 下山,将 耶和华的 命令 典章 都 述说 与百姓听。众 百姓 齐 声 说:「耶和华 所 吩咐的,我们都 必遵行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, '摩西 将 耶和华 的命令 都 写上。清早 起来,在山 下 筑 一座坛,按以色列 十 二 支派 立十 二 根柱子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, '又打发 以色列 人 中的少年人 去献 燔祭,又向耶和华 献 牛 为平安 祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, '摩西 将 血 一半 盛 在盆中,一半 洒 在 坛上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, '又将 约 书 念 给百姓 听。他们说:「耶和华 所 吩咐的,我们都 必遵行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, '摩西 将 血 洒 在 百姓身上,说:「你看!这是立约的 血,是 耶和华 按 这 一切 话 与你们 立约的凭据。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, '摩西、亚伦、拿答、亚比户,并以色列 长老 中的七十人,都上了山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, '他们看见 以色列的 神,他脚 下 仿佛 有平铺的 蓝宝石,如同 天 色明净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, '他的手 不 加害 在 以色列 的尊者身上。他们观看 神;他们又吃 又喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, '耶和华 对 摩西 说:「你上 山 到我这里来,住在 这里,我要将 石 版 并我所 写的 律法 和诫命 赐 给你,使你可以教训百姓。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, '摩西 和他的帮手 约书亚 起来, 上了 神 的山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, '摩西对 长老 说:「你们在这里 等著,等到 我们再回来, 有亚伦、户珥 与你们同在。凡 有争讼的,都可以就近 他们去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, '摩西 上 山,有云彩 把 山 遮盖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, '耶和华 的荣耀 停 于  西奈 山;云彩 遮盖山 六 天,第七 天 他从云 中 召 摩西。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, '耶和华 的荣耀 在山 顶上,在以色列 人 眼前,形状 如烈 火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, '摩西 进入 云 中 上 山, 在 山上 四十 昼 夜。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, '「你告诉 以色列 人 当为我 送 礼物来; 凡 甘心 乐意的,你们就可以收下归我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, '所 要收的 礼物:就是 金、银、铜, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, '蓝色、紫色、朱红色线 缐,细麻,山羊毛, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, '染红的 公羊 皮,海狗 皮,皂荚 木, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, '点灯的 油 并做膏 油 和香 的香料, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, '红玛瑙 与别样的宝石,可以镶嵌 在以弗得 和胸牌上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, '又当为我 造 圣所,使我可以住在 他们中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, ' 制造 帐幕 和 其中的一切 器具 都 要照我 所 指示 你 的样式。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, '「要用皂荚 木 做 一柜,长 二肘 半,宽 一肘 半,高 一肘 半。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, '要 里 外 包上 精 金,四围 镶 上 金 牙边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, '也要铸 四个 金 环,安 在 柜的四 脚上; 这 边 两 环, 那 边 两 环。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, '要用皂荚 木 做 两根杠,用金 包裹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, '要把 杠 穿 在 柜 旁 的环内,以便抬 柜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, '这杠 要常在 柜 的环内,不可 抽出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, '必将 我所 要赐 给你 的法版 放 在 柜里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, '要用精 金 做 施恩座(施恩:或译蔽罪;下同),长 二肘 半,宽 一肘 半。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, '要 用金子 锤出 两个 基路伯来,安 在施恩座 的两 头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, '这 头 做 一个 基路伯,那 头 做一 个基路伯, 二基路伯 要接连一块,在 施恩座 的 两 头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, '二基路伯 要 高 张 翅膀, 遮掩 施恩座。基路伯 要 脸 对 脸, 朝著 施恩座。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, '要将 施恩座 安 在 柜 的上边,又将我所 要赐 给你的 法版 放 在 柜里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, '我要在那里 与你 相会,又要从 法 柜 施恩座 上 二 基路伯 中间,和你 说 我所 要吩咐 你 传给 以色列 人 的一切事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, '「要用皂荚 木 做 一张桌子,长 二肘,宽 一肘,高 一肘 半。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, '要包上 精 金,四围 镶上 金 牙边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, '桌子的四围 各做 一掌宽 的横梁,横梁 上 镶著 金 牙边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, '要做 四个 金 环, 安 在 桌子的四 角上,就是 桌子四脚 上的四角。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, '安环子 的地方 要 挨近 横梁,可以穿杠 抬 桌子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, '要用皂荚 木 做 两根杠,用金 包裹,以便抬 桌子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, '要做 桌子上的盘子、调羹,并 奠酒的 爵 和瓶;这都要用精 金 制作。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, '又要在 桌子上,在我面前,常 摆 陈设 饼。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, '「要用精 金 做 一个灯台。 灯台 的座 和干 与杯、球、花,都要 接连一块 锤出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, '灯台 两旁 要杈出 六个 枝子:这 旁 三个, 那 旁 三个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, '这 旁每枝上 有三个 杯,形状像杏花,有球,有花;那 旁每枝上 也有三个 杯,形状像杏花,有球,有花。从 灯台 杈出来的 六个 枝子 都是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, '灯台上 有四个 杯,形状像杏花,有球,有花。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, '灯台每两个 枝子 以下 有球 与枝子接连一块。 灯台 出的 六 个枝子都是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, '球 和枝子 要 接连一块,都 是一块 精 金 锤出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, '要做 灯台的七个 灯盏。祭司要点 这灯,使 灯光对 照。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, '灯台的蜡剪 和蜡花盘 也是要精 金的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, '做 灯台 和 这 一切 的器具 要用精 金 一他连得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, '要谨慎 做这些物件,都要照著 在山上 指示 你 的样式。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, '「你要用十幅 幔子 做 帐幕。这些幔子 要用撚的 细麻 和蓝色、紫色、朱红色线 缐制造,并用巧匠的 手工 绣上 基路伯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, '每幅 幔子 要长 二十 八 肘, 宽 四 肘,幔子 都要 一样 的尺寸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, '这五幅 幔子 要 幅 幅 相 连;那五幅 幔子 也要幅 幅 相 连。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, '在这 相连 的幔子 末幅 边 上 要做 蓝色 的钮扣;在那 相连 的幔子 末幅 边 上也要照样 做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, '要在这 相连的幔子 上做 五十个 钮扣;在那 相连 的幔子 上也做 五十个 钮扣, 都要两 两 相 对。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, '又要做 五十个 金 钩,用钩 使 幔子 相 连,这才成了 一个 帐幕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, '「你要用山羊毛 织 十一 幅幔子,作 为帐幕 以上的 罩棚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, '每幅 幔子 要长 三十 肘, 宽 四 肘;十 一幅 幔子 都要一样 的尺寸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, '要把 五幅 幔子 连成 一幅,又把 六幅 幔子 连成一幅,这 第六幅 幔子 要在 罩棚 的前 面 折上去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, '在这 相连 的幔子 末幅 边 上 要做 五十个 钮扣;在那 相连 的幔子 末幅边 上 也做五十个 钮扣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, '又要做 五十个 铜 钩, 钩 在钮扣中,使 罩棚 连 成 一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, '罩棚 的幔子 所余 馀 那垂下来的 半幅 幔子,要垂 在 帐幕 的后头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, '罩棚 的幔子 所余 馀 长的,这边 一肘,那边 一肘,要 垂 在 帐幕 的两旁,遮盖帐幕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, '又要用染红的 公羊 皮 做 罩棚的 盖;再用海狗 皮 做一层罩棚上 的顶盖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, '「你要用皂荚 木 做 帐幕的 竖 板。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, '每 块 要长 十 肘, 宽 一肘 半; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, '每 块 必有两 榫 相 对。帐幕 一切的 板 都要这样 做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, '帐幕的 南 面 要做 板 二十 块。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, '在这二十块 板 底下 要做 四十个 带卯 的银座,两 卯 接这 块板 上 的两 榫,两 卯 接那 块板 上 的两 榫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, '帐幕 第二 面,就是北 面,也要做板 二十块 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, '和带卯 的银 座四十个;这 板 底下 有两 卯,那 板 底下 也有两 卯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, '帐幕 的后面,就是西面,要做 板 六块。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, '帐幕 后面 的拐角 要做 板 两块。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, '板的下半截 要 双的, 上半截 要 整的,直顶到 第一 个环子;两块 都要 这样 做 两个 拐角。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, '必有 八块 板 和十 六个 带卯 的银 座;这 板 底下 有两 卯,那 板 底下 也有两 卯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, '「你要用皂荚 木 做 闩:为帐幕 这 面 的板 做五闩, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, '为帐幕 那 面 的板 做五 闩,又为帐幕 后 面 的板 做五 闩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, '板 腰 间的中 闩 要从 这一头 通 到 那一头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, ' 板 要用金子 包裹,又要做 板上的金 环 套 闩; 闩 也要用金子 包裹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, '要照著 在山上 指示 你的样式 立起 帐幕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, '「你要用蓝色、紫色、朱红色线 缐,和撚的 细麻 织 幔子,以巧匠的 手工 绣上 基路伯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, '要把幔子 挂 在 四根 包 金 的皂荚木 柱子上,柱子上当有金 钩,柱子安在 四个 带卯的银 座上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, '要使 幔子 垂 在钩子 下,把 法 柜 抬进 幔子 内;这幔子 要将 圣所 和 至圣所 隔开 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, '又要把 施恩座 安 在 至圣所 内的法 柜上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, '把 桌子 安 在 幔子 外 帐幕 的北 面;把 灯台 安 在 帐幕的南 面,彼此相对。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, '「你要拿蓝色、紫色、朱红色线 缐,和撚的 细麻,用绣花的 手工 织 帐幕 的门 帘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, '要用皂荚 木为帘子 做 五根 柱子,用金子 包裹。柱子上当有金 钩;又要为柱子 用铜 铸造 五 个带卯的座。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, '「你要用皂荚 木 做 坛。这坛 要 四方的,长 五 肘,宽 五 肘,高 三 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, '要在 坛的四 拐角 上做 四个角, 与坛接连一块,用铜 把坛 包裹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, '要做 盆,收去坛上的灰,又做铲子、盘子、肉锸子、火鼎;坛上一切的 器具 都用铜 做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, '要为坛 做 一个 铜 网,在 网 的四 角 上 做 四个 铜 环, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, '把网 安 在坛 四面的围腰板 以下,使 网 从下 达到 坛 的半腰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, '又要用皂荚 木 为坛 做 杠,用铜 包裹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, '这 杠 要 穿 在 坛 两 旁 的环子内, 用以抬 坛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, '要用板 做坛,坛是空的,都照著 在山上 指示 你的样式 做。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, '「你要做 帐幕 的院子。院子的 南 面 要用撚的 细麻 做帷子,长 一百 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, '帷子的柱子 要二十根,带卯 的铜 座二十个。柱子 上的钩子 和杆子 都要用银子做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, '北 面 也当有 帷子,长 一百肘,帷子的柱子 二十根,带卯 的铜 座二十个。柱子 上的钩子 和杆子 都要用银子做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, '院子 的西 面 当有帷子,宽 五十 肘,帷子的柱子 十根,带卯的座 十个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, '院子 的东 面 要宽 五十 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, '门这边 的帷子 要十五 肘,帷子的柱子 三根,带卯的座 三个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, '门那 边 的帷子 也要十五肘,帷子的柱子 三根,带卯的座 三个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, '院子 的门 当有帘子,长二十 肘,要拿蓝色、紫色、朱红色线 缐,和撚的 细麻,用绣花 的手工织成,柱子 四根,带卯的座 四个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, '院子 四围 一切的 柱子 都要用银 杆连络,柱子上的钩子 要用银做,带卯的座 要用铜做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, '院子 要长 一百 肘,宽 五十肘,高 五 肘,帷子要用撚的 细麻做,带卯的座 要用铜做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, '帐幕 各样 用处的 器具,并帐幕一切的 橛子,和院子 里一切的 橛子,都要用铜做。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, '「你 要吩咐 以色列 人,把那为点灯 捣成 的清 橄榄 油 拿来 给你,使灯 常常 点著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, '在 会 幕中 法柜 前的幔 外,亚伦 和他的儿子,从晚上 到 早晨,要在耶和华 面前 经理 这灯。这要作 以色列 人 世世代代 永远 的定例。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, '「你 要从以色列 人 中,使 你的哥哥 亚伦 和 他的儿子 拿答、亚比户、以利亚撒、以他玛 一同 就近 你,给我 供祭司的职分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, '你要给你哥哥 亚伦 做 圣 衣 为荣耀,为华美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, '又 要吩咐 一切 心中 有智慧的,就是 我用智慧 的灵 所充满的,给 亚伦 做 衣服,使他分别为圣,可以给我 供祭司的职分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, '所 要做 的 就是 胸牌、以弗得、外袍、杂色 的内袍、冠冕、腰带,使 你哥哥 亚伦 和他儿子 穿这圣 服,可以给我 供祭司的职分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, ' 要 用 金 线 缐和 蓝色、 紫色、 朱红色线 缐,并 细麻去做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, '「他们要拿金 线 缐和蓝色、紫色、朱红色线 缐,并撚的 细麻,用巧匠 的手工 做 以弗得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, '以弗得 当有 两条 肩带,接 上 两 头,使它相连。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, '其 上 巧工织的带子,要 和以弗得 一样的做法,用以束上,与以弗得接连一块,要用金 线 缐和蓝色、紫色、朱红色线 缐,并撚的 细麻做成。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, '要取 两块 红玛瑙,在上面 刻 以色列 儿子 的名字: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, '六个 名字 在 这块 宝石上, 六个 名字 在 那块 宝石上,都照他们生来的次序。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, '要用刻 宝石 的手工,仿佛刻 图书,按著 以色列 儿子 的名字,刻 这两块 宝石,要 镶 在金 槽上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, '要将 这两块 宝石 安 在 以弗得 的两条肩带上,为以色列 人 做纪念 石。亚伦 要在 两 肩 上担 他们的名字,在耶和华 面前 作为纪念。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, '要用金子 做 二槽, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, '又拿精 金,用拧 工 仿佛拧绳子,做 两条 链子,把 这拧成的 链子 搭 在 二 槽上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, '「你要用巧匠 的手工 做 一个决断 的胸牌。要和以弗得 一样的做法: 用金 线 缐和蓝色、紫色、朱红色线 缐,并撚的 细麻 做成。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, '这胸牌要 四方的,叠为两层,长 一虎口,宽 一虎口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, '要 在上面 镶 宝石 四 行:第一 行是 红宝石、红璧玺、红玉; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, '第二 行 是绿宝石、蓝宝石、金钢石; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, '第三 行 是紫玛瑙、白玛瑙、紫晶; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, '第四 行 是水苍玉、红玛瑙、碧玉。这都要 镶 在金 槽中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, '这些宝石 都要 按著 以色列 十 二个 儿子 的名字,仿佛刻 图书, 刻 十 二个 支派的 名字。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, '要 在 胸牌 上用精 金 拧成 如绳 的链子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, '在 胸牌 上也要做 两个 金 环, 安 在 胸牌 的两 头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, '要把 那两条 拧成的金 链子,穿 过 胸牌 两 头 的环子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, '又要把 链子 的那两 头 接 在 两 槽上,安 在 以弗得 前 面 肩带 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, '要做 两个 金 环,安 在 胸牌 的两 头, 在 以弗得 里 面 的边 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, '又要做 两个 金 环,安 在 以弗得 前 面 两条 肩带 的下边,挨近 相接之处,在以弗得 巧工织的带子 以上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, '要用蓝 细带子 把 胸牌 的环子 与 以弗得 的环子 系住,使 胸牌 贴在 以弗得 巧工织的带子上,不可 与 以弗得 离缝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, '亚伦 进 圣所的时候,要将决断 胸牌,就是刻著以色列 儿子 名字的,带 在 胸前,在耶和华 面前 常 作纪念。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, '又要将 乌陵 和 土明 放 在 决断 的胸牌里;亚伦 进 到耶和华 面前的时候, 要 带在 胸前,在耶和华 面前 常 将 以色列 人 的决断 牌带 在 胸前。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, '「你要做 以弗得 的外袍,颜色全是 蓝的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, '袍上 要 为头 留一领口,口的 周围 织出 领边来,仿佛铠甲 的领口,免得 破裂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, '袍子周围 底边 上 要用蓝色、紫色、朱红色线 缐 做 石榴。在袍子周围 的石榴中间 要有金 铃铛: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, '一个金 铃铛 一个石榴,一个金 铃铛 一个石榴,在 袍子 周围 的底边上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, '亚伦 供职 的时候 要 穿这袍子。他进 圣所 到 耶和华 面前,以及出来的时候,袍上的响声 必被听见,使他不 至于 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, '「你要用精 金 做 一面牌,在上面 按刻 图书 之法刻著『归耶和华 为圣』。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, '要用 一条蓝 细带子 将牌 系 在 冠冕的 前 面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, '这牌必 在 亚伦 的额上,亚伦 要担当 干犯圣物 条例的罪孽;这圣物 是以色列 人 在一切的 圣 礼物 上所分别为圣的。这牌要 常 在 他的额上,使他们 可以在耶和华 面前 蒙悦纳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, '要用杂色细麻线 缐 织 内袍,用细麻布 做 冠冕,又用绣花 的手工 做 腰带。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, '「你要为亚伦 的儿子 做 内袍、 腰带、裹头巾, 为荣耀,为华美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, '要把这些 给 你的哥哥 亚伦 和 他的儿子 穿戴,又要膏 他们, 将他们 分别为圣,好给我 供祭司的职分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, '要给他们 做 细麻布 裤子,遮掩 下体;裤子当 从腰 达到 大腿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, ' 亚伦 和 他儿子 进 入 会 幕,或 就近 坛,在圣所 供职 的时候必穿上,免得 担 罪 而死。这要为亚伦 和他的 后裔 作永远的 定例。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, '「你使亚伦和他儿子 成圣,给我 供祭司的职分,要如此 行:取 一只 公 牛 犊,两只 无残疾的 公绵羊, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, '无酵 饼 和调 油 的无酵 饼,与抹 油 的无酵 薄饼;这都要用细麦 面 麺 做成。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, '这饼 要装 在 一个 筐子里,连筐子 带来,又把 公牛 和 两只 公绵羊牵来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, '要使 亚伦 和 他儿子 到 会 幕 门口 来,用水 洗 身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, '要 给 亚伦 穿 上 内袍 和 以弗得 的外袍,并 以弗得,又 带上胸牌,束 上 以弗得 巧工织的带子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, '把冠冕 戴 在 他头上,将 圣 冠 加 在 冠冕上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, '就 把 膏 油 倒 在 他头 上膏 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, '要叫 他的儿子 来,给他们穿上 内袍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, '给亚伦 和他儿子 束 上 腰带,包 上 裹头巾,他们 就凭永远的 定例 得了 祭司的职任。又要将 亚伦 和 他儿子 分别为圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, '「你要把 公牛 牵 到会 幕 前,亚伦 和他儿子 要按 手 在 公牛 的头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, '你要在耶和华 面前,在会 幕 门口,宰 这 公牛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, '要取 些公牛 的血,用指头 抹 在 坛 的四角上,把 血 都 倒 在 坛 脚那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, '要 把 一切 盖 脏 的脂油 与 肝 上 的网子,并 两个 腰子 和 腰子 上 的脂油,都烧在 坛上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, '只是公牛的 皮、 肉、 粪 都要用火 烧 在营 外。这牛是 赎罪祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, '「你要牵 一只 公绵羊来,亚伦 和他儿子 要按 手 在 这羊 的头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, '要宰 这 羊, 把 血 洒 在 坛 的周围。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, '要把 羊 切 成块子,洗净 五脏 和腿,连 块子 带 头,都放在一处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, '要把 全 羊 烧 在坛上,是 给耶和华 献的燔祭,是 献给耶和华 为馨香 的火祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, '「你要将 那 一只公绵羊 牵来,亚伦 和他儿子 要按 手 在 羊 的头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, '你要宰 这 羊,取 点血 抹 在 亚伦 的右耳 垂 上和 他儿子 的右 耳 垂上,又 抹在他们右 手 的大拇指 上和 右 脚 的大拇指上;并要把 血 洒 在 坛 的四围。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, '你要取 点膏 油和 坛 上的 血,弹 在 亚伦 和 他的衣服上,并 他儿子 和 他儿子 的衣服上, 他们 和他们 的衣服 就一同 成圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, '「你要取 这羊 的脂油 和 肥尾巴,并 盖 脏 的脂油 与 肝 上的网子,两个 腰子 和 腰子上的 脂油 并 右 腿( 这是 承接圣职 所献的羊)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, '再从 耶和华 面前 装无酵饼 的筐子 中取一 个 饼,一个 调油的 饼 和一个 薄饼, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, '都 放 在 亚伦 的手 上和 他儿子 的手上,作为摇祭,在耶和华 面前 摇一摇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, '要从他们手中 接过来,烧 在耶和华 面前 坛 上的燔祭 上,是 献给耶和华 为馨香 的火祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, '「你要取 亚伦 承接圣职 所 献公羊的 胸,作为摇祭,在耶和华 面前 摇一摇,这就可以作 你的 分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, '那 摇祭 的胸 和 举祭 的腿,就是 承接圣职 所 摇的、所 举的,是 归亚伦 和 他儿子的。这些你都要成为圣, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, '作 亚伦 和他子孙 从 以色列 人 中永远 所得的分,因为 是 举祭。这 要从 以色列 人 的平安 祭中,作为 献给耶和华 的举祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, '「 亚伦的 圣 衣 要 留给他的 子孙,可以穿著 受膏,又穿著 承接圣职。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, '他的子孙 接续他 当祭司的,每逢 进 会 幕 在圣所 供职的时候,要穿 七 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, '「你要 将 承接圣职 所献公羊的 肉 煮 在圣 处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, '亚伦 和他儿子 要在会 幕 门口 吃 这 羊 的肉 和 筐内 的饼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, '他们吃 那些 赎罪之物,好承接圣职,使他们 成圣;只是外人 不可 吃,因为 这是 圣物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, '那承接圣职 所献的肉 或 饼,若 有一点留 到 早晨,就要用火 烧了,不可 吃这物,因为 是 圣物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, '「你要这样 照我一切 所 吩咐的,向亚伦 和他儿子 行 承接圣职的礼 七 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, '每天 要献 公牛 一只为 赎罪 祭。你洁净 坛的时候,坛 就洁净了;且要用膏抹 坛,使坛成圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, '要洁净 坛 七 天,使坛 成圣,坛 就成为 至圣。凡 挨著 坛 的都成为圣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, '「你每 天 所要献 在 坛 上的就是 两只 一 岁 的羊羔; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, '早晨 要献 这一只,黄昏 的时候 要献 那一只。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, '和这一只 羊羔同献的,要用细面 麺 伊法十分之一 与捣成的 油 一欣 四分之一 调和,又用酒 一欣 四分之一 作为奠祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, ' 那 一只羊羔 要在黄昏 的时候 献上,照著早晨 的素祭 和奠祭 的礼办理,作为献给耶和华 馨香 的火祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, '这要在耶和华 面前、会 幕 门口,作你们世世代代 常 献的燔祭。 我要在那里 与你们 相会,和你们 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, '我要在那里 与以色列 人 相会,会幕就要因我的荣耀 成为圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, '我要使 会 幕 和 坛 成圣,也要使 亚伦 和 他的儿子 成圣,给我 供祭司的职分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, '我要住 在以色列 人 中间,作 他们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, '他们必知道 我 是耶和华─他们的 神,是 将他们 从埃及 地 领出来的,为要住 在他们中间。我 是耶和华─他们的 神。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, '「你要用皂荚 木 做 一座烧 香 的坛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, '这坛要 四方的,长 一肘,宽 一肘,高 二肘;坛的四角 要与坛接连一块。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, '要用精 金 把 坛的上面 与 坛的四围,并 坛的四角,包裹;又要在坛的四围 镶 上 金 牙边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, '要做 两个 金 环 安 在 牙子边 以下,在 坛的两 旁, 两根 横撑上,作为 穿杠 的用处,以便抬 坛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, '要用皂荚 木 做 杠,用金 包裹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, '要把坛 放 在 法 柜 前 的幔子外, 对著 法 柜上的施恩座,就是 我要与你 相会 的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, '亚伦 在坛上 要烧 馨香料 做的香;每 早晨 他收拾 灯的时候,要烧这香。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, ' 黄昏 点 灯的时候,他要在耶和华 面前 烧这香,作为世世代代 常 烧的香。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, '在这坛上 不可 奉上 异样的 香,不可献燔祭、素祭,也不可 浇 上 奠祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, '亚伦 一年 一次 要在 坛的角 上行赎罪之礼。他一年 一次 要用赎罪 祭牲 的血 在坛上 行赎罪之礼,作为世世代代的定例。这坛 在耶和华 面前为至圣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, '「 你要按以色列 人 被数的,计算 总数,你数的时候,他们各人 要为自己的生命 把赎价 奉 给耶和华,免得 数的时候 在他们中间 有 灾殃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, '凡 过去 归 那些被数之人的,每人要按圣所 的平,拿银子半 舍客勒;这 半 舍客勒 是奉给 耶和华 的礼物(一舍客勒 是二十 季拉)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, '凡 过去 归 那些被数的人,从二十 岁 以外的,要将这礼物 奉给 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, '他们为赎 生命 将 礼物 奉给 耶和华,富足的 不可 多出,贫穷的 也不可 少出,各人要出半 舍客勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, '你要从 以色列 人 收 这赎罪 银, 作为 会 幕 的使用,可以在耶和华 面前 为以色列 人 作 纪念,赎 生命。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, '「你要用铜 做 洗濯盆 和盆座,以便洗濯。要将盆 放 在 会 幕 和坛 的中间,在盆里 盛 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, '亚伦 和他的儿子 要在这盆里 洗 手洗 脚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, '他们进 会 幕,或是 就近 坛 前供职 给耶和华 献 火祭的时候,必用水 洗濯,免得 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, '他们洗 手 洗脚 就免得 死亡。这要作 亚伦 和他后裔 世世代代 永远 的定例。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, '「你 要取 上品的 香料,就是流质的 没药 五 百舍客勒,香 肉桂 一半,就是二百 五十舍客勒,菖蒲 二百 五十舍客勒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, '桂皮 五 百舍客勒,都按著圣所 的平,又取橄榄 油 一欣, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, '按做香 之法 调和 做成 圣 膏 油。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, '要用这膏油 抹 会 幕 和 法 柜, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, ' 桌子 与 桌子的一切 器具, 灯台 和 灯台的器具,并 香 坛、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, ' 燔祭 坛,和 坛的一切 器具, 洗濯盆 和 盆座。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, '要使这些物 成为圣,好成为 至圣;凡 挨著的 都成为圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, '要膏 亚伦 和 他的儿子,使他们 成为圣,可以给我 供祭司的职分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, '你要对 以色列 人 说:『这油,我 要世世代代 以为 圣 膏 油。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, '不可 倒 在 别人 的身上,也不可 按这调和之法 做 与此相似的。这膏油是 圣的,你们 也要以为 圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, '凡 调和 与此相似的,或 将这膏 膏 在 别人身上的,这人要从民中 剪除。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, '耶和华 吩咐 摩西 说:「你要取 馨香的香料,就是拿他弗、施喜列、喜利比拿;这馨香的香料 和净 乳香 各样 要 一般大的分量。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, '你要用这些加上盐,按做 香 之法 做成 清净 圣洁 的香。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, '这香要取点 捣得 极细,放 在会 幕内、法柜 前, 我要在那里 与你 相会。你们 要以这香为 至圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, '你们不可 按这调和之法 为自己 做 香; 要以这香为 圣,归耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, '凡 做 香和这香一样,为要闻 香味的,这人要从民 中剪除。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, '「看哪,犹大 支派中,户珥 的孙子、乌利 的儿子 比撒列,我已经题他的名 召他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, '我也以我 的灵 充满了 他,使他有智慧,有聪明,有知识,能做各样 的工, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, '能想出 巧工,用金、银、铜 制造各物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, '又能刻 宝石,可以镶嵌,能雕刻 木头,能做 各样 的工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, ' 我 分派 但 支派中、亚希撒抹 的儿子 亚何利亚伯 与他同工。凡 心里 有智慧的,我更使 他们有智慧,能做 我一切 所 吩咐的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, '就是 会 幕 和 法 柜,并 其 上 的施恩座,与 会幕 中一切 的器具, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, ' 桌子 和 桌子的器具, 精金 的灯台 和 灯台的一切 器具 并 香 坛, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, ' 燔祭 坛 和 坛的一切 器具,并 洗濯盆 与 盆座, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, ' 精工做 的礼服,和 祭司 亚伦 并 他儿子 用以供祭司职分 的圣 衣, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, ' 膏 油 和 为圣所 用馨香 的香料。他们都要照我一切 所 吩咐 的去做。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, '「你 要吩咐 以色列 人 说:『你们务要 守 我的安息日;因为 这是 你 我之间 世世代代 的证据,使你们知道 我─耶和华 是叫你们成为圣的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, '所以你们要守 安息日, 以为 圣日。凡干犯这日的,必 要把他治死; 凡 在这日 做 工的, 必从民 中 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, '六 日 要做 工,但第七 日 是安息 圣日,是向耶和华 守为圣的。凡 在安息 日 做 工的,必 要把他治死。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, '故此,以色列 人 要世世代代 守 安息日 为永远 的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, '这是 我 和 以色列 人 永远 的证据;因为 六 日 之内耶和华 造 天 地,第七 日 便安息 舒畅。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, '耶和华在西奈 山 和 摩西 说 完了话,就把两 块法 版 交 给他,是 神 用指头 写 的石 版。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, '百姓 见 摩西 迟延 不下 山,就大家 聚集 到 亚伦那里,对他 说:「起来!为我们 做 神像, 可以在我们前面 引路;因为 领我们 出埃及 地 的那个 摩西,我们不 知道 他 遭了 什么事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, '亚伦 对他们 说:「你们去摘下 你们妻子、儿 女 耳 上的 金 环,拿来 给我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, '百姓 就都 摘下 他们耳 上的 金 环,拿来 给 亚伦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, '亚伦从他们手里 接过来,铸了 一只牛犊,用雕刻的器具 做成。他们就说:「以色列啊, 这是 领你 出埃及 地的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, '亚伦 看见,就在牛犊面前 筑 坛, 且宣告 说:「明日 要向耶和华 守节。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, '次日清早,百姓 起来 献 燔祭 和 平安祭,就坐下 吃 喝,起来 玩耍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, '耶和华 吩咐 摩西 说:「下 去吧,因为 你的百姓,就是 你从埃及 地 领出来的,已经败坏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, '他们快快 偏离了 我所 吩咐的 道,为自己 铸了 一只牛犊,向它 下拜 献祭,说:『以色列啊,这 就是 领你出 埃及 地 的神。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, '耶和华 对 摩西 说:「我看 这 百姓 真是 硬著颈项的 百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, ' 你且由著 我,我要向他们 发烈 怒,将他们灭绝,使你的后裔 成为 大 国。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, '摩西 便恳求 耶和华─他的 神 说:「耶和华啊,你为什么 向你的百姓 发烈 怒呢?这百姓 是你用大 力 和大能的 手 从埃及 地 领出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, '为什么 使埃及人 议论 说『他领他们出去,是要降祸与他们,把他们 杀 在山中,将他们从 地 上 除灭』?求你转意,不发 你的烈怒,后悔,不降 祸 与你的百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, '求你记念 你的仆人 亚伯拉罕、以撒、以色列。 你曾指著自己 起誓 说:『我必使 你们的后裔 像天上 的星 那样多,并且我所 应许 的这 全 地,必给 你们的后裔,他们要永远 承受为业。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, '于 是耶和华 后悔,不把 所 说 的祸 降 与他的百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, '摩西 转身 下 山,手里 拿著两 块法 版。这版 是两 面 写的,这面 那面 都有 字, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, '是 神 的工作,字 是 神 写的, 刻 在 版上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, '约书亚 一听见 百姓 呼喊 的声音,就对 摩西 说:「在营 里有争战  的声音。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, '摩西说:「这不是 人打胜仗 的声音,也不是 人打败仗 的声音,我 所听见 的乃是人歌唱 的声音。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, ' 摩西 挨近 营 前就看见 牛犊,又看见人跳舞,便发烈 怒,把 两块版 扔 在山 下 摔碎了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, '又 将 他们所 铸 的牛犊 用火 焚烧,磨 得 粉碎,撒 在 水 面上,叫 以色列 人 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, '摩西 对 亚伦 说:「这 百姓 向你 做了 什么?你竟 使他们 陷在 大 罪里!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, '亚伦 说:「求我主 不要 发烈 怒。 这 百姓 专 于 作恶,是你 知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, '他们对我 说:『你为我们 做 神像,可以 在我们前面 引路;因为 领我们 出埃及 地 的那个 摩西,我们不 知道 他 遭了 什么事。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, '我对他们 说:『凡 有金 环的可以摘下来』,他们就给了 我。我把金环扔 在火中,这 牛犊 便出来了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, '摩西 见 百姓 放肆( 亚伦 纵容他们,使他们在仇敌 中间被讥刺), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, ' 就站 在营 门中,说:「凡 属耶和华的,都要到我这里来!」于 是利未 的子孙 都 到他 那里聚集。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, '他对他们 说:「耶和华─以色列的 神 这样 说:『你们各人 把刀 跨 在 腰间,在营 中往 来,从这门 到那门,各人 杀 他的弟兄 与 同伴 并 邻舍。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, '利未 的子孙 照摩西 的话 行了。那 一天 百姓 中被杀 的约有三 千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, '摩西 说:「今天 你们要自 洁,归耶和华为圣, 各人 攻击他的儿子 和弟兄,使耶和华 赐 福 与你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, '到了 第二天,摩西 对 百姓 说:「你们 犯了 大 罪。我如今 要上 耶和华那里去,或者 可以为 你们赎 罪。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, '摩西 回 到 耶和华那里,说:「唉!这 百姓 犯了 大 罪,为自己 做了 金 像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, ' 倘或 你肯赦免 他们的罪......不然,求 你从你所 写 的册 上涂抹我的名。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, '耶和华 对 摩西 说:「谁 得罪 我,我就从我的册 上涂抹谁的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, '现在 你去 领 这百姓,往 我所 告诉 你的地方去, 我的使者 必在你前面 引路;只是到我追讨 的日子,我必追讨 他们 的罪。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, '耶和华 杀 百姓 的缘故是因 他们同亚伦 做了 牛犊。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, '耶和华 吩咐 摩西 说:「我曾起誓 应许亚伯拉罕、以撒、雅各 说:『要将迦南地 赐 给你的后裔。』现在你 和你从埃及 地 所 领出来 的百姓,要从这里 往 那地 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, '我要差遣 使者 在你前面,撵出 迦南人、亚摩利人、赫人、比利洗人、希未人、耶布斯人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, '领你到 那流 奶 与蜜 之地。 我自己不同 你们上去;因为 你们 是硬著颈项 的百姓,恐怕 我在路上 把你们灭绝。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, '百姓 听见 这 凶 信 就悲哀,也没有 人 佩戴 妆饰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, '耶和华 对 摩西 说:「你告诉 以色列 人说:『耶和华说:你们 是硬著 颈项 的百姓,我若一 霎时 临到 你们中间,必灭绝你们。现在 你们要把身上 的妆饰 摘下来,使我可以知道 怎样 待 你们。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, '以色列 人 从住何烈 山以后,就把 身上的妆饰 摘得干净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, '摩西 素常 将 帐棚 支搭 在营 外,离 营 却远,他称 这帐棚 为会 幕。 凡 求问 耶和华的,就到 营 外 的会 幕 那里 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, '当 摩西 出 营到 会幕去的时候,百姓 就都 起来,各人 站 在自己帐棚 的门口,望著 摩西,直等到 他进了 会幕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, ' 摩西 进 会幕的时候,云 柱 降下来,立在 会幕 的门前,耶和华便与 摩西 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, '众 百姓 看见 云 柱 立 在会幕 门前, 就都 起来,各人 在自己帐棚 的门口 下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, '耶和华 与 摩西 面 对 面 说话,好像 人 与 朋友 说话一般。摩西转 到 营里去,惟有他的帮手─一个少年人 嫩 的儿子 约书亚 不 离开  会幕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, '摩西 对 耶和华 说:「 你 吩咐我 说:『将 这 百姓 领上去』, 却没有 叫我知道 你要打发 谁 与我同去, 只说:『我按你的名 认识你,你在我眼前 也 蒙了 恩。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, '我如今 若 在你眼前 蒙 恩,求 你将 你的道 指示我,使我可以认识你,好 在你眼前 蒙 恩。求你想 到 这 民 是你的民。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, '耶和华说:「我必亲自 和你同去,使你 得安息。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, '摩西说:「你若 不 亲自 和我同去,就不要 把我们从这里 领上去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, '人在何事上 得以 知道 我 和你的百姓 在你眼前 蒙 恩呢?岂不是 因你与我们 同去、使我 和你的百姓 与地 上 的 万 民 有分别吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, '耶和华 对 摩西 说:「 你这 所 求 的 我也 要行;因为 你在我眼前 蒙了 恩,并且我按你的名 认识你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, '摩西说:「求你 显出 你的荣耀给我看。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, '耶和华说:「我 要显我一切 的恩慈,在 你面前 经过,宣告 我 的名。我要恩待 谁 就恩待谁;要怜悯 谁 就怜悯谁」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, '又说:「你不 能 看见 我的面,因为 人 见我 的面不能 存活。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, '耶和华 说:「看哪,在我 这里有地方,你要站 在 磐石上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, ' 我的荣耀 经过的时候,我必将你放 在磐石 穴中,用我的手 遮掩 你,等 我过去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, '然后我要将 我的手 收回,你就得见 我的背,却不得 见 我的面。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, '耶和华 吩咐 摩西 说:「你要凿出 两 块石 版,和先前 你摔碎 的 那 版一样; 其 上的 字 我要写 在 这版上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, '明日早晨,你要 预备好了, 上 西奈 山,在 山 顶 上站在 我面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, '谁 也不可 和你 一同上去,遍 山 都 不可 有 人,在 山 根 也 不可 叫羊群 牛群 吃草。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, '摩西 就凿出 两 块石 版,和先前的一样。清晨 起来,照 耶和华 所吩咐 的上 西奈 山去,手里 拿著 两 块石 版。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, '耶和华 在云中 降临,和摩西一同 站 在那里,宣告 耶和华 的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, '耶和华 在 他面前 宣告说:「耶和华,耶和华,是有怜悯 有恩典的 神,不轻易发怒,并有丰盛 的慈爱 和诚实, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, '为千万 人存留 慈爱,赦免 罪孽、过犯,和罪恶,万不 以 有罪的为无罪,必追讨 他的罪,自父 及 子, 直到 三、 四代。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, '摩西 急忙 伏 地 下拜, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, '说:「主啊,我若 在你眼前 蒙 恩, 求你 在我们中间 同行,因为 这是 硬著 颈项的 百姓。又求你赦免 我们的罪孽 和罪恶,以我们为你的产业。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, '耶和华说:「 我 要立 约,要在 百姓 面前 行 奇妙的事,是在遍 地 万 国 中所 未曾 行的。在你 四 围的 外邦人 就要看见 耶和华 的作为,因 我 向你 所 行的 是 可畏惧的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, '「 我 今天 所 吩咐你的,你要谨守。我 要从你面前 撵出 亚摩利人、迦南人、赫人、比利洗人、希未人、耶布斯人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, '你要谨慎,不可 与你 所 去 那地 的居民 立 约,恐怕 成为 你们 中间 的网罗; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, '却要 拆毁 他们的祭坛,打碎 他们的柱像,砍下 他们的木偶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, ' 不可 敬拜 别 神;因为 耶和华 是忌邪的 神,名 为 忌邪者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, '只怕 你与那地 的居民 立 约,百姓随从他们的 神,就行邪淫,祭祀 他们的神,有人叫 你,你便吃 他的祭物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, '又为你的儿子 娶 他们的女儿为妻,他们的女儿 随从 他们的神,就行邪淫,使 你的儿子 也随从 她们的神 行邪淫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, '「不可 为自己 铸造 神 像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, '「你要守 除酵 节,照我所 吩咐你的,在亚笔 月 内所定的日期 吃 无酵饼 七 天,因为 你是这亚笔 月 内出了 埃及。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, '凡 头生的都是我的;一切 牲畜 头生的,无论是牛 是羊,公的 都是我的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, '头生的 驴 要用羊羔 代赎,若 不 代赎 就要打折牠的颈项。凡 头生的 儿子 都要赎出来。谁也不可 空手 朝见 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, '「你六 日 要做工,第七 日 要安息,虽在耕种 收割 的时候也要安息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, '在收割 初熟 麦子 的时候要守 七七 节;又在年 底 要守收藏 节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, '你们一切 男丁 要一年 三 次 朝见 主 耶和华─以色列的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, '我要 从你面前 赶出 外邦人,扩张 你的境界。你一年 三 次 上去 朝见 耶和华─你 神的时候,必没 有人 贪慕 你的地土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, '「你不可 将我祭物 的血 和 有酵 的饼一同 献上。逾越 节 的祭物 也不可 留 到早晨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, '地 里首先 初熟之物 要送 到耶和华─你 神 的殿。不可 用山羊羔母 的奶 煮 山羊羔。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, '耶和华 吩咐 摩西 说:「你要将 这些 话 写上,因为 我是按 这 话 与你 和 以色列 人立 约。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, ' 摩西在 耶和华 那里 四十 昼 夜,也不 吃 饭 也不 喝 水。耶和华将 这约 的话,就是十 条诫,写 在 两块版上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, ' 摩西 手里 拿著两 块法 版 下 西奈 山的时候, 不 知道 自己 的面 皮 因耶和华和他 说话 就发了光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, '亚伦 和以色列 众 人 看见 摩西 的面 皮 发光 就怕 挨近 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, '摩西 叫 他们来;于 是亚伦 和会众 的官长 都 到 他那里去,摩西 就与他们 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, '随后 以色列 众 人 都近前来,他就把 耶和华 在西奈 山 与他 所 说 的一切 话都吩咐他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, '摩西 与他们 说 完了 话就用帕子 蒙 上 脸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, '但摩西 进到 耶和华 面前 与他 说话 就揭去 帕子,及至 出来 的时候 便将 耶和华所 吩咐 的告诉 以色列 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, '以色列 人 看见 摩西 的面 皮 发光。摩西 又用 帕子 蒙 上 脸,等到 他进去 与耶和华 说话就揭去帕子。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, '摩西 招聚 以色列 全 会众,对他们 说:「这是 耶和华 所 吩咐的 话,叫你们照著 行: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, '六 日 要做 工,第七 日 乃为 圣日,当向耶和华 守为安息 圣日。凡 这日之内 做 工的,必把他治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, '当安息 日,不可 在你们一切 的住处 生 火。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, '摩西 对 以色列 全 会众 说:「耶和华 所 吩咐 的 是这 样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, '你们中间 要拿 礼物 献给耶和华,凡 乐意 献的可以拿 耶和华 的礼物来,就是金、银、铜, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, '蓝色、紫色、朱红色线 缐,细麻,山羊毛, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, '染红 的公羊 皮,海狗 皮,皂荚 木, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, '点灯 的油,并做膏 油 和香 的香 料, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, '红玛瑙 与别样的宝石,可以镶嵌 在以弗得 和胸牌上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, '「你们中间 凡 心里 有智慧 的都要来 做 耶和华 一切 所 吩咐的: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, '就是 帐幕 和 帐幕的罩棚,并 帐幕的盖、 钩子、 板、 闩、 柱子、 带卯的座, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, ' 柜 和 柜的杠, 施恩座 和 遮掩 柜的幔子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, ' 桌子 和 桌子的杠 与 桌子的一切 器具,并 陈设饼, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, ' 灯 台 和 灯台的器具, 灯盏 并 点灯 的油, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, ' 香 坛 和 坛的杠, 膏 油 和 馨 香的香料,并 帐幕 门 口的 帘子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, ' 燔祭 坛 和 坛的 铜 网, 坛的杠 并 坛的一切 器具, 洗濯盆 和 盆座, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, ' 院子 的帷子 和 帷子的柱子, 带卯的座 和 院子 的门 帘, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, ' 帐幕 的橛子 并 院子 的橛子,和 这两处的绳子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, ' 精工做的礼 服 和 祭司 亚伦 并 他儿子 在圣所 用以供 祭司职分 的圣 衣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, '以色列 全 会众 从摩西 面前 退去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, '凡 心里 受感和 甘心乐意 的都 拿 耶和华 的礼物 来,用以做 会 幕 和其中一切 的使用,又用以做圣 衣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, '凡 心里 乐意献礼物的,连男 带 女,各将 金 器,就是胸前针、耳环(或译:鼻环)、打印的戒指,和手钏 带来 献给 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, '凡 有 蓝色、紫色、朱红色线 缐,细麻,山羊毛,染红 的公羊 皮,海狗 皮的,都拿了来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, '凡 献 银子 和铜 给耶和华 为 礼物 的都拿了来;凡 有 皂荚 木 可做 什么 使用的 也拿了来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, '凡 心中 有智慧 的妇女 亲手 纺线 缐,把 所纺的 蓝色、 紫色、 朱红色线 缐,和 细麻 都拿了来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, '凡 有智慧、心里 受感 的妇女 就纺 山羊毛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, '众官长 把 红玛瑙 和 别样的宝石,可以镶嵌 在以弗得 与胸牌上的,都拿了来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, '又 拿香料 做香,拿 油 点灯,做膏 油。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, '以色列 人,无论 男 女,凡 甘心 乐意 献 礼物 给耶和华的,都将礼物拿来,做 耶和华 藉 借 摩西 所 吩咐的 一切 工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, '摩西 对 以色列 人 说:「 犹大 支派中,户珥 的孙子、乌利 的儿子 比撒列,耶和华 已经题他的名 召他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, '又以 神 的灵 充满了 他,使他有智慧、聪明、知识,能做各样 的工, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, '能想出 巧工,用金、银、铜 制造各物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, '又能刻 宝石,可以镶嵌,能雕刻 木头,能做 各样 的巧 工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, '耶和华又使 他,和但 支派 中亚希撒抹 的儿子 亚何利亚伯,心里灵明,能教导人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, '耶和华使他们 的心 满有 智慧,能做 各样 的工,无论是雕刻的工,巧匠的工,用蓝色、紫色、朱红色线 缐,和细麻、绣花的工,并机匠的工,他们都 能做,也能想出 奇巧的 工。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, '「比撒列 和亚何利亚伯,并一切 心里 有智慧的,就是 蒙耶和华 赐 智慧 聪明、叫他知道 做 圣所 各样 使用 之工的,都要照 耶和华 所 吩咐的 做工。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, '凡 耶和华 赐 他心里 有智慧、而且 受感 前来 做 这工的,摩西 把他们 和 比撒列 并 亚何利亚伯 一同召来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, '这些人就从 摩西 收了 以色列 人 为做 圣所并圣 所使用 之工 所 拿来的 礼物。百姓 每 早晨 还 把甘心献的礼物 拿来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, '凡 做 圣所 一切 工 的智慧人 各 都 离开  他 所 做 的工, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, '来 对 摩西 说:「百姓 为耶和华 吩咐 使用 之工 所 拿来的,富富 有余 馀。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, '摩西 传命,他们就在全营 中宣告 说:「无论男 女,不必 再 为圣所 拿 什么礼物来。」这样才拦住 百姓 不再拿礼物来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, '因为他们所有的材料 够 做 一切 当做的物,而且有余 馀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, '他们中间,凡 心里 有智慧 做 工的,用十幅 幔子 做 帐幕。这幔子 是比撒列用撚的 细麻 和蓝色、紫色、朱红色线 缐制造的,并用巧匠的 手工 绣上 基路伯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, '每幅 幔子 长 二十 八 肘, 宽 四 肘, 都是 一样 的尺寸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, '他使 这五幅 幔子 幅 幅 相连,又使那五幅 幔子 幅 幅 相连; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, '在 这 相连 的幔子 末幅 边 上做 蓝色 的钮扣,在那 相连的 幔子 末幅 边上 也照样 做; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, '在这 相连的幔子 上做 五十个 钮扣, 在那 相连的 幔子上 也做 五十个 钮扣, 都是两两 相对; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, '又做 五十个 金 钩,使 幔子 相连。这才成了 一个 帐幕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, '他用 山羊毛 织 十 一 幅幔子,作为帐幕 以上 的罩棚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, '每幅 幔子 长 三十 肘, 宽 四 肘;十 一 幅幔子 都是一样 的尺寸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, '他把 五幅 幔子 连成 一幅,又把 六幅 幔子 连成一幅; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, '在 这相连 的幔子 末 幅边 上做 五十个 钮扣,在 那 相连 的幔子 末幅边 上也做 五十个 钮扣; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, '又做 五十个 铜 钩,使 罩棚 连 成 一个; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, '并用染红的 公羊 皮 做 罩棚的 盖,再用海狗 皮 做一层罩棚上 的顶盖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, '他用皂荚 木 做 帐幕的 竖 板。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, '每 块 长 十 肘, 宽 一肘 半; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, '每 块 有两 榫 相对。帐幕 一切 的板 都是这样 做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, '帐幕的 南 面 做 板 二十 块。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, '在这二十块 板 底下 又做 四十个 带卯 的银座:两 卯 接这块 板 上 的两 榫,两 卯 接那块 板 上 的两 榫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, '帐幕 的第二 面,就是北 面,也做 板 二十块 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, '和带卯 的银 座四十个:这 板 底下 有两 卯,那 板 底下 也有两 卯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, '帐幕 的后面,就是西面,做 板 六块。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, '帐幕 后面 的拐角 做 板 两块。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, '板的下半截 是 双的,上半截 是 整的,直到 第一个 环子;在帐幕的两个 拐角 上都是 这样 做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, '有 八块 板 和十 六 个 带卯 的银座,每块 板 底下 有两 卯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, '他用皂荚 木 做 闩:为帐幕 这 面 的板 做五闩, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, '为帐幕 那 面 的板 做五 闩,又为帐幕 后 面 的板 做五 闩, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, ' 使 板 腰间 的中 闩 从 这一头 通 到 那一头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, '用金子 将 板 包裹,又做 板上的金 环 套 闩; 闩 也用金子 包裹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, '他用蓝色、紫色、朱红色线 缐,和撚的 细麻 织 幔子,以巧匠 的手工 绣 上 基路伯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, '为幔子 做 四根 皂荚 木柱子,用金 包裹,柱子上有金 钩,又为柱子 铸了 四个 带卯 的银座。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, '拿蓝色、紫色、朱红色线 缐,和撚的 细麻,用绣花 的手工 织 帐幕 的门 帘; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, '又 为帘子做五根 柱子 和 柱子上的钩子,用金子 把柱顶 和柱子上的杆子 包裹。柱子有五个 带卯的座,是铜的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, '比撒列 用皂荚 木 做 柜,长 二肘 半,宽 一肘 半,高 一肘 半。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, '里 外 包 上 精 金,四围 镶上 金 牙边, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, '又铸 四个 金 环,安在 柜的四 脚上: 这 边 两 环, 那 边 两 环。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, '用皂荚 木 做 两根杠,用金 包裹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, '把 杠 穿 在 柜 旁 的环内,以便抬 柜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, '用精 金 做 施恩座,长 二肘 半,宽 一肘 半。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, ' 用金子 锤出 两个 基路伯来,安 在施恩座 的两 头, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, '这 头 做一个 基路伯,那 头 做一个 基路伯, 二基路伯 接连一块,在施恩座 的两 头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, '二基路伯 高 张 翅膀, 遮掩 施恩座;基路伯 是 脸 对 脸,朝著 施恩座。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, '他用皂荚 木 做 一张桌子,长 二肘,宽 一肘,高 一肘 半, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, '又包 上 精 金,四围 镶 上 金 牙边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, '桌子 的四围 各做 一掌宽 的横梁,横梁 上 镶著 金 牙边, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, '又铸了 四个 金 环,安 在 桌子 四 脚 的四 角上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, '安环子 的地方是 挨近 横梁,可以穿 杠 抬 桌子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, '他用皂荚 木 做 两根杠,用金 包裹,以便抬 桌子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, '又用精 金 做 桌子 上 的器皿,就是 盘子、 调羹,并 奠酒 的 瓶 和 爵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, '他用精 金 做 一个灯台; 这 灯台 的座 和干,与杯、球、花,都是 接连一块 锤出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, '灯台两旁 杈出 六个 枝子:这 旁 三个,那 旁 三 个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, '这旁每 枝 上有三个 杯,形状像杏花,有球 有花;那旁每 枝 上也有三个 杯,形状像杏花,有球 有花。从 灯台 杈出来的 六个 枝子 都是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, '灯台 上有四个 杯,形状像杏花,有球 有花。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, '灯台每两个 枝子 以下 有球, 与枝子接连一块;灯台杈出的 六个 枝子都是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, '球 和枝子 是 接连一块,都 是一块 精 金 锤出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, '用精 金 做 灯台的七个 灯盏,并灯台的蜡剪 和蜡花盘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, '他用精 金 一他连得 做 灯台 和 灯台的一切 器具。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, '他用皂荚 木 做 香 坛,是四方的,长 一肘,宽 一肘,高 二肘,坛的四角 与坛接连一块; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, '又用精 金 把 坛的上面 与 坛的四面 并 坛的四角 包裹,又在坛的四围 镶 上 金 牙边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, '做 两个 金 环,安在牙子 边以下,在 坛的两 旁、两根 横撑 上,作为穿 杠的用处,以便抬 坛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, '用皂荚 木 做 杠,用金 包裹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, '又按做香 之法 做 圣 膏 油 和 馨香料 的净 香。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, '他用皂荚 木 做 燔祭 坛,是四方的,长 五 肘,宽 五 肘,高 三 肘, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, '在 坛的四 拐角 上做 四个角,与坛接连一块,用铜 把坛 包裹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, '他做 坛上的 盆、 铲子、 盘子、 肉锸子、 火鼎;这一切 器具 都是用铜 做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, '又为坛 做 一个铜 网,安在坛四面 的围腰板以下,从下 达到 坛的半腰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, '为铜 网 的四 角 铸 四个 环子,作为穿 杠的用处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, '用皂荚 木 做 杠,用铜 包裹, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, '把 杠 穿 在 坛 两旁 的环子内,用以 抬 坛,并用板 做 坛;坛是空的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, '他用铜 做 洗濯盆 和 盆座,是用会 幕 门前 伺候的妇人 之镜子 做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, '他做 帐幕的院子。院子 的南 面 用撚的 细麻 做帷子,宽一百 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, '帷子的柱子 二十根,带卯 的铜 座二十个;柱子 上的钩子 和杆子 都是用银子做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, '北 面也有帷子,宽一百 肘。帷子的柱子 二十根,带卯的铜 座 二十个;柱子 上的钩子 和杆子 都是用银子做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, '院子的西 面 有帷子,宽五十 肘。帷子的柱子 十根,带卯的座 十个;柱子 的钩子 和杆子 都是用银子做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, '院子的东 面,宽五十 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, ' 门这边 的帷子 十五 肘,那 边也是一样。帷子的柱子 三根,带卯的座 三个。在门 的左 右 各有帷子 十 五 肘,帷子的柱子 三根,带卯的座 三个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, '院子 四面的 帷子 都是 用撚的 细麻做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, '柱子 带卯的座 是铜的,柱子 上的钩子 和杆子 是银的,柱顶 是用银子 包的。院子 一切的 柱子 都是 用银杆 连络的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, '院子 的门 帘 是以绣花的 手工,用蓝色、紫色、朱红色线 缐,和撚的 细麻织的,宽 二十 肘,高 五 肘,与院子 的帷子 相配。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, '帷子的柱子 四根,带卯 的铜 座四个;柱子上的钩子 和杆子 是银的;柱顶 是用银子 包的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, '帐幕 一切的 橛子 和院子 四围的 橛子都是铜的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, '这 是法柜 的帐幕 中利未人 所 用 物件的总数,是照 摩西 的吩咐,经祭司 亚伦 的儿子 以他玛 的手 数点的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, '凡 耶和华 所 吩咐 摩西 的都是犹大 支派 户珥 的孙子、乌利 的儿子 比撒列 做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, '与他 同工的有但 支派 中亚希撒抹 的儿子 亚何利亚伯;他是雕刻匠,又是巧匠,又能用蓝色、紫色、朱红色线 缐,和细麻 绣花。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, ' 为圣所 一切 工作 使用 所献的 金子,按圣所 的平,有 二十 九 他连得 并七 百 三十 舍客勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, '会 中被数的 人所出的银子,按圣所 的平,有一百 他连得 并一千 七 百 七十 五 舍客勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, '凡 过去 归 那些被数之人的,从 二十 岁 以外,有六十 万 零三 千 五 百 五十人。按圣所 的平,每人 出银半 舍客勒,就是一比加。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, '用 那一百 他连得 银子 铸造 圣所 带卯的座 和 幔子 柱子带卯的座;一百 他连得 共一百 带卯的座,每带卯的座 用一他连得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, '用 那一千 七 百 七十 五 舍客勒银子做 柱子上的 钩子,包裹 柱顶 并柱子上的杆子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, '所献的 铜 有七十 他连得 并二千 四 百 舍客勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, '用这铜 做 会 幕 门 带卯的座 和 铜 坛,并坛上 的铜 网 和 坛 的一切 器具, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, '并 院子 四围 带卯的座 和 院 门 带卯的座,与 帐幕 一切的 橛子 和 院子 四围 所有的 橛子。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, '比撒列用 蓝色、紫色、朱红色线 缐 做 精致 的衣服,在圣所 用以供职, 又为亚伦 做 圣 衣,是照 耶和华 所吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, '他用金线 缐 和蓝色、紫色、朱红色线 缐,并撚的 细麻 做 以弗得; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, '把金子 锤 成 薄片,剪出 线 缐来,与 蓝色、 紫色、 朱红色线 缐,用巧匠的 手工 一同绣上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, '又为以弗得 做 两条相连的 肩带,接连 在 以弗得的两 头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, '其 上 巧工织的带子 和以弗得 一样的 做法,用以束上,与以弗得接连一块,是用金线 缐 和蓝色、紫色、朱红色线 缐,并撚的 细麻做的,是照 耶和华 所吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, '又琢出 两块红玛瑙,镶在 金 槽上,仿佛刻 图书,按著 以色列 儿子 的名字 雕刻; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, '将 这两块宝石安 在 以弗得 的两条肩带上,为以色列 人 做纪念 石,是照 耶和华 所吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, '他用巧匠的 手工 做 胸牌,和以弗得 一样的做法,用金线 缐 与蓝色、紫色、朱红色线 缐,并撚的 细麻做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, ' 胸牌 是 四方的,叠为两层;这两层 长 一虎口,宽 一虎口, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, '上面 镶著 宝石 四 行:第一 行 是红宝石、 红璧玺、红玉; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, '第二 行 是绿宝石、蓝宝石、金钢石; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, '第三 行 是紫玛瑙、白玛瑙、紫晶; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, '第四 行 是水苍玉、红玛瑙、碧玉。这都镶在 金 槽 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, '这些宝石 都是按著 以色列 十 二个 儿子 的名字, 仿佛刻 图书, 刻十 二 个支派 的名字。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, '在 胸牌上,用精 金 拧 成 如绳子 的链子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, '又做 两个 金 槽 和两个 金 环,安 在 胸牌 的两 头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, '把那两条 拧成的金 链子 穿 过 胸牌 两 头的 环子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, '又把 链子 的那两 头 接 在 两 槽上,安 在 以弗得 前 面 肩带 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, '做 两个 金 环,安 在 胸牌 的两 头,在 以弗得 里 面 的 边 上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, '又做 两个 金 环,安 在 以弗得 前 面 两条 肩带 的下边,挨近 相接之处,在以弗得 巧工织的带子 以上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, '用一条蓝 细带子 把 胸牌 的环子 和 以弗得 的环子 系住,使 胸牌 贴在 以弗得 巧工织的带子上,不可 与 以弗得 离缝,是照 耶和华 所吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, '他用织 工 做 以弗得 的外袍,颜色全是 蓝的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, '袍 上 留一领口,口的 周围 织出领边来,仿佛铠甲 的领口,免得 破裂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, '在 袍子 底边上,用蓝色、紫色、朱红色线 缐,并撚的 细麻做 石榴, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, '又用精 金 做 铃铛,把 铃铛 钉 在 袍子 周围 底边 上的石榴 中间: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, '一个铃铛 一个石榴,一个铃铛 一个石榴,在 袍子 周围 底边 上用以供职,是照 耶和华 所吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, '他用织 成的 细麻布 为亚伦 和他的儿子 做 内袍, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, '并用细麻布做 冠冕 和 华美的 裹头巾,用撚的 细麻布做 裤子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, '又用蓝色、紫色、朱红色线 缐,并撚的 细麻,以绣花的 手工做 腰带,是照 耶和华 所吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, '他用精 金 做 圣 冠 上的牌,在上面 按刻 图书 之法,刻著「归耶和华 为圣」。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, '又用 一条蓝 细带子 将牌系 在 冠冕 上,是照 耶和华 所吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, '帐幕,就是会 幕,一切的 工 就这样做 完了。凡 耶和华 所 吩咐 摩西的,以色列 人 都照样 做了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, '他们 送 到 摩西那里。 帐幕 和 帐幕的一切 器具,就是钩子、板、闩、柱子、带卯的座, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, ' 染红 公羊 皮 的盖、 海狗 皮 的顶盖,和 遮掩 柜的幔子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, ' 法 柜 和 柜的杠 并 施恩座, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, ' 桌子 和 桌子的一切 器具 并 陈设 饼, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, ' 精金的 灯 台 和 摆列的 灯盏,与 灯台 的一切 器具,并 点灯 的油, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, ' 金 坛、 膏 油、 馨香 的香料、 会幕 的门 帘, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, ' 铜 坛 和 坛 上 的铜 网, 坛的杠 并 坛的一切 器具, 洗濯盆 和 盆座, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, ' 院子 的帷子 和 柱子,并 带卯的座, 院子 的门 帘、 绳子、橛子,并帐幕 和 会 幕 中一切 使用 的器具, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, ' 精工做的 礼服,和 祭司 亚伦 并 他儿子 在圣所 用以供祭司职分 的圣 衣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, '这 一切 工作 都是以色列 人照 耶和华 所 吩咐 摩西 做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, '耶和华 怎样 吩咐的, 他们就怎样 做了。摩西 看见 一切的 工 都做成了, 就给他们 祝福。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, '「正 月 初 一 日,你要立起 帐幕, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, '把 法 柜 安放 在里面,用 幔子 将 柜 遮掩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, '把 桌子 搬进去,摆设 上面的物。把 灯台 搬进去,点 其上的灯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, '把 烧香 的金 坛 安 在法 柜 前,挂上 帐幕的 门 帘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, '把 燔祭 坛 安 在帐幕 门 前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, '把 洗濯盆 安 在 会 幕 和坛 的中间,在盆里 盛 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, '又在四围 立 院帷,把 院子 的门 帘 挂上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, '用 膏 油 把 帐幕 和 其 中 所有的都 抹上,使 帐幕和一切 器具 成圣,就都成 圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, '又要抹 燔祭 坛 和 一切 器具,使 坛 成圣, 就都成为 至 圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, '要抹 洗濯盆 和 盆座,使盆 成圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, '要使 亚伦 和 他儿子 到 会 幕 门口来,用水 洗 身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, '要给 亚伦 穿上 圣 衣,又膏 他,使他 成圣,可以给我 供祭司的职分; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, '又要 使 他儿子来,给他们 穿上 内袍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, '怎样 膏 他们的父亲,也要照样膏 他们,使 他们 给我供 祭司的职分。他们世世代代 凡受膏的,就永远 当祭司的职任。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, '摩西 这样 行,都是照 耶和华 所 吩咐 他的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, ' 第二 年 正 月 初 一日,帐幕 就立起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, '摩西 立起 帐幕,安上 带卯的座,立上 板,穿上 闩,立起 柱子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, '在帐幕 以上 搭 罩棚,把 罩棚 的顶盖 盖 在 其上,是照 耶和华 所吩咐 他的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, '又 把 法版 放 在 柜 里,把 杠 穿 在 柜的两旁,把 施恩座 安 在 柜 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, '把 柜 抬 进 帐幕,挂上 遮掩 柜的幔子,把 法 柜 遮掩了,是照 耶和华 所吩咐 他的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, '又把 桌子 安 在会 幕内,在 帐幕 北 边,在幔子 外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, '在桌子上 将 饼 陈设 在耶和华 面前,是照 耶和华 所吩咐 他的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, '又把 灯台 安 在会 幕内,在 帐幕 南 边,与桌子 相对, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, '在耶和华 面前 点 灯,是照 耶和华 所吩咐 他的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, '把 金 坛 安 在会 幕内 的幔子 前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, '在坛上 烧了 馨香料 做的香,是照 耶和华 所吩咐 他的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, '又挂上 帐幕的 门 帘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, '在会 幕 的帐幕 门前,安设 燔祭 坛,把 燔祭 和 素祭 献 在其上,是照 耶和华 所吩咐 他的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, '把 洗濯盆 安 在 会 幕 和坛 的中间,盆中 盛 水,以便洗濯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, '摩西 和亚伦 并亚伦的儿子 在这盆里 洗 手洗 脚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, '他们进 会 幕 或就近 坛的时候,便都洗濯,是照 耶和华 所吩咐 他的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, '在帐幕 和坛 的四围 立了 院帷,把 院子 的门 帘 挂上。这样,摩西 就完了 工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, '当时,云彩 遮盖 会 幕,耶和华 的荣光 就充满了 帐幕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, '摩西 不 能 进 会 幕;因为 云彩 停 在其上,并且耶和华 的荣光 充满了 帐幕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, '每逢云彩 从 帐幕 收上去,以色列 人 就起程前往; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, '云彩 若 不 收上去,他们就不 起程,直等到 云彩收上去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, ' 日间,耶和华 的云彩 是在 帐幕以上;夜间,云中 有 火,在以色列 全 家 的眼前。在他们所行的路上 都是这样。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, '耶和华 从会 幕 中呼叫 摩西,对他 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, '「你晓谕 以色列 人 说:你们中间 若 有人 献 供物 给耶和华,要从 牛群 羊群 中献牲畜 为 供物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, '「他的供物 若 以 牛 为燔祭,就要在 会 幕 门口 献 一只没有残疾的 公牛, 可以在耶和华 面前 蒙悦纳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, '他要按 手 在 燔祭 牲的头上,燔祭便蒙悦纳,为他 赎罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, '他要在耶和华 面前 宰 公牛;亚伦 子孙 作祭司的,要奉上 血,把 血 洒 在 会 幕 门口、 坛 的周围。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, '那人要剥去 燔祭牲的皮,把燔祭牲 切 成块子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, '祭司 亚伦 的子孙 要把火 放 在 坛上,把柴 摆 在 火上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, '亚伦 子孙 作祭司的,要把 肉块 和 头 并 脂油 摆在 坛 上 火 的柴 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, '但燔祭的脏腑 与腿 要用水 洗。祭司 就要把 一切全 烧 在坛上,当作燔祭,献与耶和华 为馨 香 的火祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, '「人的供物 若 以 绵羊 或 山羊 为燔祭,就要献上 没有残疾的 公羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, '要把羊 宰 于  坛 的北 边,在耶和华 面前;亚伦 子孙 作祭司的,要把 羊血 洒 在 坛 的周围。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, '要把燔祭牲 切 成块子,连 头 和 脂油,祭司 就要摆 在 坛 上 火的 柴 上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, '但脏腑 与腿 要用水 洗,祭司就要 全然 奉献,烧 在坛上。这是 燔祭,是献与耶和华 为馨 香 的火祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, '「人奉给耶和华 的供物,若 以 鸟 为燔祭,就要献 斑鸠 或是 雏 鸽 为 供物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, '祭司 要把鸟拿 到 坛前,揪下 头来,把鸟烧 在坛上;鸟的血 要流 在 坛 的旁边; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, '又要把 鸟的嗉子和脏物(脏物:或译翎毛)除掉,丢 在 坛 的东 边 倒灰 的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, '要拿著鸟的两个翅膀,把鸟 撕开 ,只是不可 撕断;祭司 要在 坛上、 在 火 的柴 上焚烧。这是 燔祭,是献与耶和华 为馨 香 的火祭。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, '「若 有人 献 素 祭 为供物 给耶和华,要 用细面 麺 浇 上 油,加 上 乳香, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, '带 到 亚伦 子孙 作祭司的那里;祭司就要从细面 麺 中取 出 一把来,并取些油 和 所有的 乳香,然后 要把 所取的这些作为纪念,烧 在坛上,是献与耶和华 为馨 香 的火祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, '素祭 所剩的 要归给亚伦 和他的子孙;这是献与耶和华 的火祭 中为至 圣的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, '「若 用 炉 中烤的物 为素 祭,就要用调 油 的无酵 细面 麺 饼,或是抹 油 的无酵 薄饼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, '若 用铁鏊 上 做的物 为素祭,就要用 调 油 的无酵 细面 麺, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, '分成 块子,浇 上 油;这是 素祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, '若 用煎盘 做的物 为素祭,就要用油 与细面 麺 做成。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, '要把 这些东西 做的 素祭 带 到耶和华面前,并奉 给 祭司,带 到 坛前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, '祭司 要从 素祭 中取出 作为纪念的,烧 在坛上,是献与耶和华 为馨 香 的火祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, ' 素祭 所剩的 要归给亚伦 和他的子孙。这是献与耶和华 的火祭 中为至 圣的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, '「凡 献 给耶和华的 素祭 都不可 有 酵;因为 你们不可 烧 一点 酵、一点 蜜当作 火祭 献给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, '这些物 要献 给耶和华 作为初熟的 供物,只是不可 在 坛 上献 为馨香的祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, '凡 献为素祭 的供物 都要用盐 调和,在 素祭 上不可 缺了你 神 立约 的盐。 一切 的供物 都要配盐 而献。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, '若 向耶和华 献 初熟之物 为素祭,要献上 烘了 的禾穗子,就是轧了 的新穗子,当作 初熟之物 的素祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, '并要抹 上 油,加 上 乳香;这是 素祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, '祭司 要把 其中作为纪念的,就是一些轧了的禾穗子 和一些油,并 所有的 乳香,都焚烧,是向耶和华 献的火祭。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, '「 人 献供物 为平安 祭(平安:或译酬恩;下同),若 是从 牛群 中献,无论 是公的 是 母的,必用没有残疾的 献 在耶和华 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, '他要按 手 在 供物 的头上,宰 于 会 幕 门口。亚伦 子孙 作祭司的,要把 血 洒 在 坛 的周围。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, '从平安 祭中,将火祭 献 给耶和华,也要把 盖 脏 的脂油 和 脏 上 所有的 脂油, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, '并 两个 腰子 和 腰子上的 脂油,就是 靠 腰两旁的脂油,与 肝 上 的网子 和 腰子,一概取下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, '亚伦 的子孙 要把这些 烧 在 坛 的燔祭上,就是 在 火 的 柴 上,是献与耶和华 为馨 香 的火祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, '「人向耶和华 献供物 为平安 祭,若 是从 羊群 中献,无论是公的 是 母的,必用没有残疾的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, ' 若 献 一只羊羔 为 供物,必在耶和华 面前 献上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, '并要按 手 在 供物 的头上,宰 于 会 幕 前。亚伦 的子孙 要把 血 洒 在 坛 的周围。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, '从平安 祭中,将火祭 献 给耶和华,其中的脂油 和整 肥尾巴 都要在靠近 脊骨 处取下,并要把 盖 脏 的脂油 和 脏 上 所有的 脂油, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, ' 两个 腰子 和 腰子 上 的脂油,就是 靠 腰两旁的脂油,并 肝 上 的网子和 腰子,一概取下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, '祭司 要在坛上 焚烧,是献给耶和华 为食物 的火祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, '「人的供物 若 是山羊,必在耶和华 面前 献上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, '要按 手 在 山羊头上,宰 于 会 幕 前。亚伦 的子孙 要把 血 洒 在 坛 的周围, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, '又把 盖 脏 的脂油 和 脏 上 所有的 脂油, 两个 腰子 和 腰子上 的脂油,就是 靠 腰两旁的脂油,并 肝 上 的网子和 腰子,一概取下,献 给耶和华 为火祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, '并入上节 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, '祭司 要在坛 上焚烧,作为馨 香 火祭 的食物。脂油 都是 耶和华的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, '在你们一切的 住处, 脂油 和 血 都不可 吃;这要成为你们世世代代 永远的 定例。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, '「你晓谕 以色列 人 说:若 有人 在耶和华 所 吩咐 不可 行 的什么事上 误 犯了 一件, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, '或 是受膏的 祭司 犯罪,使百姓 陷在罪里,就当为 他所 犯 的罪 把没有残疾的 公牛 犊 献 给耶和华 为赎罪祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, '他要牵 公牛 到 会 幕 门口,在耶和华 面前 按 手 在 牛 的头上,把 牛 宰 于 耶和华 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, '受膏的 祭司 要取 些公牛 的血 带 到 会 幕, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, ' 把 指头 蘸 于 血中,在耶和华 面前 对著 圣所 的幔子 弹 血 七 次, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, ' 又要把些 血 抹 在 会 幕内、 耶和华 面前 香 坛 的四角上,再把 公牛 所有的 血 倒 在 会 幕 门口、 燔祭 坛 的脚那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, '要 把 赎罪祭 公牛 所有的 脂油,乃是盖 脏的 脂油和 脏 上 所有的 脂油, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, '并 两个 腰子 和 腰子 上 的脂油,就是 靠 腰两旁的脂油,与 肝 上 的网子和 腰子,一概取下, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, '与平安 祭 公牛 上所取 的一样;祭司 要把这些烧 在 燔祭 的坛上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, ' 公牛 的皮 和 所有的 肉,并 头、 腿、脏、腑、粪, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, '就是 全 公牛,要搬 到 营 外 洁净 之地、 倒 灰之所,用火 烧 在 柴上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, '「以色列 全 会众 若 行了 耶和华 所 吩咐 不可 行 的什么事,误犯了 罪, 是隐而未现、会众 看不出来的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, '会众 一知道 所 犯 的罪 就要献 一只公牛 犊 为赎罪祭,牵 到会 幕 前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, '会 中的长老 就要在耶和华 面前 按 手 在 牛 的头上,将 牛 在耶和华 面前 宰了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, '受膏的 祭司 要取 些公牛 的血 带到 会 幕, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, ' 把指头 蘸 于 血中,在耶和华 面前 对著 幔子 弹血 七 次, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, '又要把些 血 抹 在 会 幕内、 耶和华 面前 坛的 四角上,再把 所有的 血 倒 在 会 幕 门口、 燔祭 坛 的脚那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, '把 牛 所有的 脂油 都取下,烧 在坛上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, '收拾 这牛,与 那赎罪祭 的牛一样。祭司 要为他们 赎罪,他们 必蒙赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, '他要把 牛 搬 到 营 外 烧了,像 烧 头一个 牛一样;这是 会众 的赎罪祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, '「官长 若 行了 耶和华─他 神 所 吩咐 不可 行 的什么事,误 犯了 罪, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, ' 所 犯 的 罪 自己 知道了,就要牵 一只 没有残疾的 公 山羊 为 供物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, '按 手 在 羊 的头上,宰 于 耶和华 面前、 宰 燔祭牲 的地方;这是 赎罪祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, '祭司 要用指头 蘸 些赎罪祭 牲的血,抹 在 燔祭 坛 的四角上,把 血 倒 在 燔祭 坛 的脚那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, ' 所有的 脂油,祭司都要烧 在坛上,正如平安 祭 的脂油一样。至于 他的罪,祭司 要为他 赎了,他 必蒙赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, '「民中 若 有人 行了 耶和华 所 吩咐 不可 行 的什么事,误 犯了 罪, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, '所 犯 的罪 自己 知道了,就要为 所 犯 的罪 牵 一只没有残疾的 母 山羊 为供物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, '按 手 在 赎罪祭 牲的头上,在那宰燔祭 牲的地方 宰了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, '祭司 要用指头 蘸 些羊的血,抹 在 燔祭 坛 的四角上, 所有的 血 都要倒 在 坛 的脚那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, '又要把 羊所有的 脂油 都取下,正如 取 平安 祭 牲的脂油一样。祭司 要在坛上 焚烧,在耶和华 面前作为馨 香的祭, 为他 赎罪,他 必蒙赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, '「人若 牵 一只绵羊羔 为赎罪祭 的供物,必要牵 一只没有残疾 的母羊, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, '按 手 在 赎罪祭 牲的头上,在那 宰 燔祭 牲的地方 宰了 作赎罪祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, '祭司 要用指头 蘸 些赎罪祭 牲的血,抹 在 燔祭 坛 的四角上, 所有的 血 都要倒 在 坛 的脚那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, '又要把 所有的 脂油 都取下,正如 取 平安 祭 羊羔 的脂油一样。祭司 要按 献给耶和华 火祭的条例,烧 在坛上。至于 所 犯的 罪,祭司 要为他 赎了,他 必蒙赦免。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, '「若有人 听见 发誓 的声音(或译:若有人听见叫人发誓的声音),他 本是见证,却 不 把 所看见的、 所知道的 说出来,这就是 罪;他要担当 他的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, '或是 有人 摸了 不洁 的物,无论是 不洁 的死 兽,是 不洁 的死 畜,是 不洁 的死 虫,他 却不知道,因此 成了 不洁,就有了罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, '或是 他摸了 别人 的污秽,无论是 染了 什么 污秽,他 却不知道,一 知道了 就有了罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, '或是 有人 嘴里 冒失 发誓,要行恶, 要行善,无论人 在什么 事上 冒失 发誓,他 却不知道,一 知道了 就要在这其中 的一件 上有了罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, ' 他有了 罪的时候,就要承认 所 犯 的罪, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, '并要因 所 犯 的罪,把 他的赎愆祭牲─就是羊群 中 的母羊,或是 一只羊羔,或是 一只山羊─牵到 耶和华 面前为赎罪祭。至于 他的罪,祭司 要为他 赎了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, '「他的力量 若 不 够 献 一只羊羔,就要因所 犯的罪,把两只 斑鸠 或是 两只 雏 鸽 带 到耶和华 面前为 赎愆祭:一只 作赎罪祭,一只 作燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, '把这些 带 到 祭司那里,祭司就要先 把 那 赎罪祭 献上,从 鸟的颈项 上揪下 头来,只是不可 把鸟撕断, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, '也把些赎罪祭 牲的血 弹 在 坛 的旁边,剩下的 血 要流 在 坛 的脚那里;这是 赎罪祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, '他要照例 献 第二只 为燔祭。至于 他所 犯 的罪,祭司 要为他 赎了,他 必蒙赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, '「他的力量 若 不 够 献两只 斑鸠 或是 两只 雏 鸽,就要因所 犯的罪 带 供物来,就是细面 麺 伊法 十分之一 为赎罪祭;不可 加 上 油,也不可 加 上 乳香,因为 是 赎罪祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, '他要把供物带 到 祭司那里,祭司 要取 出 自己的一 把 来作为 纪念,按 献给耶和华 火祭 的条例烧 在坛上;这是 赎罪祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, '至于  他在这几件 事中 所 犯 的罪,祭司 要为他 赎了,他 必蒙赦免。剩下的面 麺都归 与祭司,和素祭一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, '「人 若 在耶和华 的圣物 上误 犯 了罪,有了过犯,就要照你所估的,按圣所 的舍客勒 拿银子,将 赎愆祭牲─就是羊群 中 一只没有残疾 的公绵羊─牵 到耶和华 面前为赎愆祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, '并且 他因 在 圣物 上的差错 要偿还,另外 加 五分之一,都给 祭司。祭司 要用赎愆祭 的公绵羊 为他 赎罪,他 必蒙赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, '「若 有人 犯罪,行了 耶和华 所 吩咐 不可 行 的什么事,他虽然不 知道,还是有了罪,就要担当 他的罪孽; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, '也要照你所估定的价,从 羊群 中牵 一只没有残疾 的公绵羊来,给 祭司 作赎愆祭。至于  他误 行 的那 错事, 祭司 要为他 赎罪,他 必蒙赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, '这是 赎愆祭,因他在耶和华 面前实在 有了罪。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, '「若 有人 犯罪,干犯 耶和华,在邻舍 交付他的物上,或是 在交易 上行了诡诈,或是 抢夺人的财物,或是 欺压 邻舍, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, '或是 在捡了 遗失的物 上 行了诡诈,说谎 起誓,在 这 一切的 事 上 犯了 什么 罪; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, '他既 犯了罪,有了 过犯,就要归还 他所 抢夺 的,或是 因欺压 所 得的,或 是 人 交付 他 的,或 是 人遗失他所 捡 的物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, '或是 他因 什么 物 起了假 誓,就要 如数 归还,另外加 上 五分之一,在查出他有罪 的日子 要交 还 本主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, '也要照你所估定的价,把 赎愆祭牲─就是羊群 中 一只没有残疾的 公绵羊─牵 到耶和华面前,给 祭司 为赎愆祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, '祭司 要在耶和华 面前 为他 赎罪;他无论 行了 什么 事,使他 有了罪,都必蒙赦免。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, '「你要吩咐 亚伦 和 他的子孙 说,燔祭 的条例 乃是 这样:燔祭 要放在 坛 的柴 上,从 晚上 到 天亮,坛 上的火 要常常烧著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, '祭司 要穿上 细麻布 衣服,又要把细麻布 裤子 穿 在 身上,把 坛 上 所 烧的 燔祭 灰 收起来,倒在 坛 的旁边; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, '随后要脱去 这衣服,穿上 别的 衣服,把 灰 拿 到 营 外 洁净 之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, '坛 上 的火 要在其上 常常烧著,不可 熄灭。祭司 要每日 早晨 在上面 烧 柴,并要把燔祭 摆 在坛上,在其上 烧 平安祭牲 的脂油。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, '在 坛上 必有常常 烧著 的火,不可 熄灭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, '「素祭 的条例 乃是这样:亚伦 的子孙 要在 坛 前 把这祭 献在 耶和华 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, '祭司要从其中─就是从素祭 的细面 麺中─取出 自己的一把,又要取些油 和 素祭 上 所有的 乳香,烧 在坛上,奉给耶和华 为馨 香 素祭的纪念。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, '所 剩下的,亚伦 和他子孙 要吃,必在圣 处 不带酵 而吃,要在会 幕 的院子里 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, '烤 的时候不可 搀酵。这是从所献给我的火祭 中赐 给他们 的分,是 至 圣的,和赎罪祭 并赎愆祭一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, '凡献给耶和华 的火祭,亚伦 子孙 中的男丁 都 要吃这一分,直到万代,作他们永 得的分。摸 这些祭物 的,都 要成为圣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, '「当亚伦 受膏 的日子,他和他子孙 所 要献 给耶和华 的供物,就是 细面 麺 伊法 十分之一,为常献的 素祭:早晨 一半,晚上 一半。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, '要在 铁鏊 上用油 调和做成,调匀了,你就拿进来;烤好了 分成块子,献 给耶和华 为馨 香 的素祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, '亚伦的子孙中,接续他 为受膏 的祭司,要把这素祭 献上,要全 烧 给耶和华。这是永远 的定例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, ' 祭司 的素祭 都 要烧了,却不可 吃。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, '「你对 亚伦 和 他的子孙 说,赎罪祭 的条例 乃是这样: 要在耶和华 面前、宰 燔祭牲 的地方 宰 赎罪祭牲;这是 至 圣的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, '为赎罪 献这祭 的祭司 要吃,要在圣 处,就是在会 幕 的院子里 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, '凡 摸 这祭肉 的要成为圣;这祭牲的血 若 弹 在 什么衣服上,所 弹 的那一件 要在圣 处 洗净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, '惟有煮祭物的 瓦 器 要打碎;若 是煮 在铜 器里,这铜器要擦磨,在水中 涮净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, '凡 祭司中 的男丁 都可以吃;这是 至 圣的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, '凡 赎罪祭,若 将血 带 进 会 幕 在圣所 赎罪,那肉都不可 吃,必用火 焚烧。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, '「赎愆祭 的条例 乃是如此:这祭是 至 圣的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, '人在那里 宰 燔祭牲,也要在那里 宰 赎愆祭牲; 其血,祭司要洒 在 坛 的周围。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, '又 要 将 肥尾巴 和 盖 脏 的脂油, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, ' 两 个腰子 和 腰子上 的 脂油,就是 靠 腰两旁的脂油,并 肝 上 的网子 和 腰子,一概取下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, '祭司 要在坛 上焚烧,为献给耶和华 的火祭,是 赎愆祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, '祭司中 的男丁 都 可以吃这祭物;要在圣 处 吃,是 至 圣的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, '赎罪祭怎样,赎愆祭也是怎样,两个祭 是一个 条例。献赎愆祭赎罪 的 祭司 要得 这祭物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, '献 燔祭 的祭司,无论为 谁奉献,要亲自 得 他 所 献 那燔祭牲 的皮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, '凡 在炉中 烤 的素祭和 煎盘中做的,并 铁鏊 上做的,都要 归那献祭 的祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, '凡 素祭,无论是油 调和的 是干的,都要 归 亚伦 的子孙,大家均分。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, '「人 献 与耶和华 平安 祭 的条例 乃是这样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, '他若 为 感谢 献上,就要用调 油 的无酵 饼 和抹 油 的无酵 薄饼,并用油 调 匀 细面 麺 做的饼,与 感谢 祭 一同献上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, '要用 有酵 的饼 和为 感谢 献的平安祭,与供物 一同献上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, '从各样的 供物中,他要把一个 饼 献 给耶和华 为举祭,是 要归给 洒 平安祭牲 血 的祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, '为感谢 献平安 祭牲 的肉,要在献的 日子 吃,一点 不可 留 到 早晨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, '若 所献的 是为还愿 ,或是 甘心 献的,必在献 祭 的日子 吃,所剩下的 第二天 也可以吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, '但所剩下的 祭 肉,到第三 天 要用火 焚烧; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, '第三 天 若 吃了 平安 祭 的肉,这祭必不 蒙悦纳,人所献的 也不 算为祭,反为 可憎嫌的,吃这祭肉 的,就必担当 他的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, '「挨了 污秽 物的肉 就不可 吃,要用火 焚烧。至于 平安祭的肉,凡 洁净的人 都要吃; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, '只是 献与耶和华 平安 祭 的肉, 人 若不洁净 而吃了,这 人 必从民中 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, ' 有人 摸了 什么 不洁净的物,或是人 的不洁净,或是 不洁净 的牲畜,或是 不洁 可憎之物,吃了献 与耶和华 平安 祭 的肉,这 人 必从民中 剪除。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, '「你晓谕 以色列 人 说:牛 的脂油、绵羊的脂油、山羊的脂油,你们都 不可 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, '自死的 和被野兽 撕裂的,那脂油 可以做别的 使用,只是你们万 不可 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, ' 无论何人 吃了 献 给耶和华 当 火祭 牲畜 的脂油,那人 必从民中 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, '在你们一切的 住处,无论是雀鸟的 血是野兽的 血,你们都 不可 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, '无论 是谁 吃血,那 人 必从民中 剪除。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, '「你晓谕 以色列 人 说:献 平安 祭 给耶和华的,要从平安 祭中取些 来 奉给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, '他亲手 献 给 耶和华 的火祭,就是 脂油 和 胸,要带来,好把 胸 在耶和华 面前 作摇祭,摇一摇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, '祭司 要把 脂油 在坛 上焚烧,但胸 要 归亚伦 和他的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, '你们要从平安 祭中 把 右 腿 作举祭,奉 给祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, '亚伦 子孙中,献 平安祭牲 血 和 脂油的,要得 这右 腿 为分; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, '因为 我从 以色列 人 的平安 祭中,取了 这摇的 胸 和 举的 腿 给 祭司 亚伦 和他子孙,作他们从 以色列 人 中所永 得的分。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, '这是 从耶和华 火祭中,作亚伦 受膏 的分和他子孙 受膏的分,正在摩西(原文是他)叫他们 前来 给耶和华 供祭司职分 的日子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, '就是在摩西(原文是他)膏 他们 的日子,耶和华 吩咐 以色列 人 给 他们的。这是他们世世代代 永 得的分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, '这就是 燔祭、素祭、赎罪祭、赎愆祭,和平安 祭 的条例,并承接圣职的礼, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, '都是耶和华 在西奈 山 所 吩咐 摩西的,就是他在西奈 旷野 吩咐 以色列 人 献 供物 给耶和华 之日所说的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, '「你将 亚伦 和 他儿子 一同 带来,并将 圣衣、 膏 油,与 赎罪祭 的一只公牛、 两 只公绵羊、 一筐 无酵饼都带来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, '又 招聚 会众 到 会 幕 门口。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, '摩西 就照 耶和华 所吩咐的 行了;于 是会众 聚集 在 会 幕 门口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, '摩西 告诉 会众 说:「这就是 耶和华 所 吩咐 当行 的事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, '摩西 带了 亚伦 和 他儿子来,用水 洗了 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, '给亚伦 穿上 内袍,束上 腰带,穿上 外袍,又加 上 以弗得, 用其上巧工织的带子 把 以弗得 系 在他 身上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, '又给他 戴上 胸牌,把 乌陵 和 土明 放 在 胸牌内, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, '把 冠冕 戴 在 他头上,在 冠冕 的前面 钉上 金 牌,就是圣 冠,都是照 耶和华 所吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, '摩西 用 膏 油 抹 帐幕 和 其 中 所有的,使它 成圣; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, '又用膏油 在 坛 上弹了 七 次,又抹了 坛 和 坛的一切 器皿,并 洗濯盆 和 盆座,使它成圣; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, '又把膏 油 倒 在 亚伦 的头 上膏 他,使他成圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, '摩西 带了 亚伦 的儿子来,给他们 穿上 内袍,束上 腰带,包上 裹头巾,都是照 耶和华 所吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, '他牵了 赎罪祭 的公牛来,亚伦 和他儿子 按 手 在 赎罪祭 公牛 的头上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, '就宰了公牛。摩西 用指头 蘸 血,抹 在 坛 上四角 的周围,使 坛 洁净,把 血 倒 在 坛 的脚那里,使坛成圣,坛就洁净了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, '又取 脏 上 所有 的 脂油 和 肝 上的网子,并 两 个腰子 与 腰子上的脂油, 都烧 在坛上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, '惟有 公牛,连 皮 带 肉 并 粪,用火 烧 在营 外,都是照 耶和华 所吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, '他奉上 燔祭 的公绵羊;亚伦 和他儿子 按 手 在 羊 的头上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, '就宰了公羊。摩西 把 血 洒 在 坛 的周围, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, '把 羊 切 成块子, 把 头 和 肉块 并 脂油 都烧了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, '用水 洗了 脏腑 和 腿, 就把 全 羊 烧 在坛上 为 馨 香 的燔祭,是 献给耶和华 的火祭,都是照 耶和华 所吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, '他又奉上 第二 只公绵羊,就是承接圣职之礼 的羊;亚伦 和他儿子 按 手 在 羊 的头上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, '就宰了羊。摩西 把 些血 抹 在 亚伦 的右 耳 垂 上和 右 手 的大拇指上,并 右 脚 的大拇指上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, '又带了 亚伦 的儿子来, 把 些 血 抹在 他们的右 耳 垂 上和 右 手 的大拇指上,并 右 脚 的大拇指上, 又把 血 洒 在 坛 的周围。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, '取 脂油 和 肥尾巴,并 脏 上 一切 的 脂油 与 肝 上的网子, 两 个腰子 和 腰子上的脂油,并 右 腿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, '再从 耶和华 面前、盛无酵饼 的筐子 里取出 一个 无酵 饼,一个 油 饼,一个 薄饼,都放 在 脂油 和 右 腿上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, '把 这一切 放 在 亚伦 的手 上和 他儿子 的手 上作摇祭,在耶和华 面前 摇一摇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, '摩西 从 他们的手 上拿下来,烧 在 坛 上的燔祭上,都是 为承接圣职 献给耶和华 馨 香 的火祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, '摩西 拿 羊 的胸 作为摇祭,在耶和华 面前 摇一摇,是承接圣职之礼, 归摩西 的分,都是照 耶和华 所吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, '摩西 取 点膏 油和 坛 上的 血,弹 在 亚伦 和 他的衣服上,并 他儿子 和 他儿子 的衣服上,使 他和 他们 的 衣服 一同成圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, '摩西 对 亚伦 和 他儿子 说:「把 肉 煮 在会 幕 门口,在那里 吃,又 吃承接圣职 筐子里 的饼,按我所 吩咐 的说(或译:按所吩咐我的说):『这是亚伦 和他儿子 要吃的。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, '剩下 的肉 和饼,你们要用火 焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, '你们七 天 不可 出 会 幕 的门,等到 你们承接圣职 的日子 满了,因为 主叫 你们 七 天 承接圣职。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, '像今 天 所 行 的都是耶和华 吩咐 行的,为你们 赎罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, '七 天 你们要昼 夜 住在 会 幕 门口,遵守 耶和华 的吩咐,免得 你们死亡,因为 所吩咐 我的就是这样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, '于 是亚伦 和他儿子 行了 耶和华藉 借著 摩西 所 吩咐 的一切 事。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, '到了 第八 天,摩西 召了 亚伦 和他儿子,并以色列 的众长老来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, '对 亚伦 说:「你当取 牛群中的 一只公牛犊 作赎罪祭,一只公绵羊 作燔祭,都要没有残疾的,献 在耶和华 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, '你也要 对 以色列 人 说:『你们当取 一只公山羊 作赎罪祭,又取一只牛犊 和一只绵羊羔,都要一岁、没有残疾的,作燔祭, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, '又取一只公牛,一只公绵羊 作平安祭,献 在耶和华 面前,并取调 油 的素祭,因为 今天 耶和华 要向你们 显现。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, '于 是他们把 摩西 所 吩咐的,带 到 会 幕 前;全 会众 都近前来,站 在耶和华 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, '摩西 说:「这是 耶和华 吩咐 你们所 当行 的;耶和华 的荣光 就要向你们 显现。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, '摩西 对 亚伦 说:「你就近 坛前,献 你的赎罪祭 和 燔祭,为自己 与 百姓 赎罪,又献上 百姓的 供物,为他们 赎罪,都照 耶和华 所吩咐的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, '于 是,亚伦 就近 坛前,宰了 为自己 作 赎罪祭 的牛犊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, '亚伦 的儿子 把 血 奉 给他,他就把指头 蘸 在血中,抹 在 坛 的四角上,又把 血 倒 在 坛 脚那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, '惟有 赎罪祭的 脂油 和 腰子,并 肝上取的 网子,都烧 在坛上,是照 耶和华 所吩咐 摩西的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, '又用火 将 肉 和 皮 烧 在营 外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, '亚伦 宰了 燔祭牲,他儿子 把 血 递 给他,他就洒 在 坛 的周围, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, '又把 燔祭 一块一块地、连 头 递 给他,他都烧 在 坛上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, '又洗了 脏腑 和 腿,烧 在 坛 上的燔祭上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, '他奉上 百姓 的供物, 把 那 给百姓 作赎罪祭 的公山羊 宰了,为罪献上,和先献的一样; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, '也奉上 燔祭,照例 而献。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, '他又奉上 素祭,从其中 取一满 把,烧 在 坛上;这是在早晨 的燔祭 以外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, '亚伦 宰了 那 给百姓 作平安 祭的 公牛 和 公绵羊。他儿子 把 血 递 给他,他就洒 在 坛 的周围; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, '又把 公牛 和公绵羊 的脂油、肥尾巴,并盖 脏的脂油与腰子,和肝 上的网子,都递给他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, '把 脂油 放 在 胸上,他就把脂油 烧 在坛上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, ' 胸 和 右 腿,亚伦 当作摇祭,在耶和华 面前 摇一摇,都是照 摩西 所吩咐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, '亚伦 向 百姓 举 手,为他们祝福。他献了 赎罪祭、燔祭、平安祭 就下来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, '摩西、亚伦 进入 会 幕,又出来 为 百姓 祝福,耶和华 的荣光 就向 众 民 显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, '有火 从耶和华 面前 出来,在 坛 上烧尽 燔祭 和 脂油;众 民 一见,就都欢呼,俯伏 在 地。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, '亚伦 的儿子 拿答、亚比户 各 拿 自己的香炉,盛 上 火,加 上 香,在耶和华 面前 献上 凡 火,是 耶和华没有 吩咐 他们的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, '就有火 从耶和华 面前 出来,把他们 烧灭,他们就死 在耶和华 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, '于 是摩西 对 亚伦 说:「这就是 耶和华 所 说:『我在亲近我的人中 要显为圣;在 众 民 面前,我要得荣耀。』」亚伦 就默默不言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, '摩西 召了 亚伦 叔父 乌薛 的儿子 米沙利、 以利撒反来,对他们 说:「上前来,把 你们的亲属 从 圣所 前 抬 到 营 外。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, '于 是二人上前来,把他们穿著袍子 抬 到 营 外,是照 摩西 所吩咐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, '摩西 对 亚伦 和他儿子 以利亚撒、以他玛 说:「不可 蓬头 散发,也不可 撕裂 衣裳,免得 你们死亡,又免得耶和华向 会众 发怒;只要你们的弟兄 以色列 全 家 为 耶和华 所 发的 火 哀哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, '你们也不可 出 会 幕 的门,恐怕 你们死亡,因为 耶和华 的膏 油 在你们的身上。」他们就照摩西 的话 行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, '耶和华 晓谕 亚伦 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, '「你 和 你儿子 进 会 幕的时候,清酒、浓酒 都不可 喝,免得 你们死亡;这要作你们世世代代 永远的 定例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, '使你们可以将 圣的、 俗的, 洁净的、 不洁净的,分别出来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, '又使你们可以将 耶和华 藉 借 摩西 晓谕 以色列 人 的 一切 律例 教训 他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, '摩西 对 亚伦 和他剩下的 儿子 以利亚撒、 以他玛 说:「你们献 给 耶和华 火祭中 所剩的 素祭,要在坛 旁 不带酵 而吃,因为 是 至 圣的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, '你们要在圣 处 吃;因为 在献给耶和华 的火祭中,这是 你的分 和你儿子 的分;所吩咐我的 本是 这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, '所 摇 的胸,所 举 的腿,你们要在洁净 地方 吃。你 和你的儿 女 都要同吃;因为 这些是从以色列 人 平安 祭 中给你,当你的分 和你儿子 的分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, '所举 的腿,所摇 的胸,他们要与火祭 的脂油 一同 带来 当摇祭,在耶和华 面前 摇一摇;这要 归你 和你儿子,当作永 得的分,都是照 耶和华 所吩咐的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, '当下摩西 急切地 寻找 作赎罪祭 的公山羊,谁知 已经焚烧了,便向 亚伦 剩下的 儿子 以利亚撒、 以他玛 发怒,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, '「这 赎罪祭 既 是 至 圣的, 主又给了 你们,为要你们担当 会众 的罪孽,在耶和华 面前 为他们 赎罪,你们为何 没有 在圣 所 吃呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, '看哪,这 祭牲的血 并没有 拿 到 圣 所里去,你们本当 照我所 吩咐的,在圣所里 吃 这祭肉。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, '亚伦 对 摩西 说:「 今天 他们在耶和华 面前 献上 赎罪祭 和 燔祭,我 又遇见 这样的灾,若今天 吃了 赎罪祭,耶和华 岂能看 为美呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, '摩西 听见这话,便以为 美。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, '耶和华 对 摩西、 亚伦 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, '「你们晓谕 以色列 人 说,在 地上 一切 走兽 中 可吃的 乃是这些: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, '凡 蹄 分 两 瓣、倒 嚼的 走兽,你们都可以吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, '但 那 倒 嚼 或分 蹄 之中不可 吃 的乃是:骆驼─因为 倒 嚼 不 分 蹄,就 与你们 不洁净; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, ' 沙番─因为 倒 嚼 不 分 蹄,就 与你们 不洁净; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, ' 兔子─因为 倒 嚼 不 分 蹄,就 与你们 不洁净; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, ' 猪─因为 蹄 分 两 瓣,却 不 倒 嚼,就 与你们 不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, '这些兽的肉,你们不可 吃;死的,你们不可 摸,都 与你们 不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, '「 水中 可吃 的 乃是 这些:凡 在水里、海里、河里、 有翅 有鳞 的,都可以吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, '凡 在海里、河里,并一切 水里 游动的 活 物, 无 翅 无鳞的,你们都当以为 可憎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, '这些无翅无鳞、以为 可憎的,你们不可 吃 牠的肉; 死的 也当以为可憎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, '凡 水里 无 翅 无鳞的,你们 都当以为 可憎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, '「雀鸟 中你们当以为 可憎、不可 吃的 乃是: 雕 𫛲、 狗头雕 𫛲、 红头雕 𫛲、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, ' 鹞鹰、 小鹰 与其类; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, ' 乌鸦 与其类; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, ' 鸵鸟、 夜鹰、 鱼鹰、 鹰 与其类; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, ' 鸮鸟、 鸬鹚、 猫头鹰、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, ' 角鸱、 鹈鹕、 秃雕 𫛲、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, ' 鹳、鹭鸶 与其类; 戴鵀 与 蝙蝠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, '「凡 有翅膀 用 四 足爬行 的物,你们 都当以为 可憎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, '只是 有翅膀 用 四 足爬行 的物 中, 有足 有腿,在 地上 蹦跳的,你们还可以吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, '其中有 蝗虫、 蚂蚱、 蟋蟀 与其类; 蚱蜢 与其类;这些 你们都可以吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, '但是有 翅膀有 四 足 的 爬物,你们 都当以为 可憎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, '「这些 都能使你们不洁净。凡 摸了 死的,必不洁净 到 晚上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, '凡 拿了 死的,必不洁净 到 晚上,并要洗 衣服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, '凡 走兽 分 蹄 不 成两 瓣、也不 倒 嚼 的,是 与你们 不洁净;凡 摸了的 就不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, '凡 四 足 的走兽, 用 掌 行走的,是 与你们 不洁净; 摸 其尸的,必不洁净 到 晚上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, '拿 其尸的,必不洁净 到 晚上,并要洗 衣服。这些是 与你们 不洁净的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, '「地 上 爬 物 与你们 不洁净的 乃是这些:鼬鼠、鼫鼠、蜥蜴 与其类; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, '壁虎、龙子、守宫、蛇医、蝘蜓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, '这些 爬物 都是 与你们 不洁净的。在牠死了以后,凡 摸了的,必不洁净 到 晚上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, '其中 死了的,掉 在 什么 东西上,这东西就不洁净,无论 是木 器、 衣服、 皮子、 口袋,不拘 是做 什么 工 用 的器皿,须要放 在水中,必不洁净 到 晚上,到晚上才洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, '若有死了 掉 在 瓦 器 里的,其 中 不拘 有什么,就不洁净,你们要把这瓦器 打破了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, '其中一切 可吃 的 食物,沾 水 的 就不洁净,并且那样器皿 中一切 可喝 的,也必不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, '其中已死的,若有一点掉 在 什么 物件上,那物件就不洁净,不拘是炉子,是锅台,就要打碎,都 不洁净,也必 与你们 不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, '但是 泉源 或是聚 水 的池子 仍是 洁净;惟挨了 那死的,就不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, '若是 死的,有一点掉 在 要种 的 子 粒上,子粒 仍是洁净; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, '若 水 已经浇 在 子粒上,那死的有一点 掉 在上头,这子粒 就与你们 不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, '「 你们 可吃的 走兽 若 是死了,有人摸 牠,必不洁净 到 晚上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, '有人吃 那死了的走兽,必不洁净 到 晚上,并要洗 衣服;拿了 死走兽的,必不洁净 到 晚上,并要洗 衣服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, '「凡 地上 的爬 物 是 可憎的,都不可 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, '凡 用 肚子 行走 的和 用 四 足行走的,或是 有许多 足的,就是一切 爬 在 地上 的,你们都不可 吃,因为 是 可憎的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, '你们不可 因什么 爬 物 使 自己 成为可憎的,也不可 因这些 使自己不洁净,以致染了污秽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, ' 我 是耶和华─你们的 神;所以你们要 成为圣洁,因为 我是 圣洁的。你们也不可 在 地上的 爬 物 污秽 自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, ' 我是 把你们 从埃及 地 领出来 的耶和华,要作 你们的 神;所以你们要 圣洁,因为 我是 圣洁的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, '这是 走兽、飞鸟,和 水中 游动的 活 物,并 地 上 爬 物 的条例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, '要把 洁净 的和 不洁净的, 可吃的 与 不可 吃的 活物,都分别出来。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, '「你晓谕 以色列 人 说:若 有妇人 怀孕 生 男孩,她就不洁净 七 天,像在月经 污秽的 日子 不洁净一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, '第八 天,要给婴孩 行割礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, '妇人在产血 不洁之中,要家居 三十 三 天。她洁净的 日子 未 满,不可 摸 圣物,也不可 进 入 圣所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, '她若 生 女孩,就不洁净 两个七天,像污秽的时候一样,要在 产血 不洁之中,家居 六十 六 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, '「满了 洁净的 日子,无论是为男孩 是 为女孩,她要把一 岁 的羊羔 为燔祭,一只雏 鸽 或是 一只斑鸠 为赎罪祭,带 到 会 幕 门口 交给 祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, '祭司要献 在耶和华 面前,为她 赎罪,她的血 源 就洁净了。这 条例 是为生育的妇人,无论是生男 生女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, ' 她的力量 若不 够 献 一只羊羔,她就要取 两只 斑鸠 或是 两只 雏 鸽,一只 为燔祭,一只 为赎罪祭。祭司 要为她 赎罪,她就洁净了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, '耶和华 晓谕 摩西、 亚伦 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, '「人 的肉 皮上 若 长了 疖子,或 长了癣,或 长了火斑,在他肉 皮上 成了 大痲疯 的灾病,就要将他带 到 祭司 亚伦 或 亚伦 作祭司 的一个 子孙面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, '祭司 要察看 肉 皮上 的灾病,若灾病处 的毛 已经变 白,灾病 的现象 深于  肉上 的皮,这便是 大痲疯 的灾病。祭司 要察看他,定他 为不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, '若 火斑 在他肉 皮上 是 白的,现象 不 深 于  皮,其上的毛 也没有 变 白,祭司 就要将 有灾病 的人关锁 七 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, '第七 天,祭司 要察看他,若 看 灾病 止住了, 没有 在皮上 发散,祭司 还 要将他关锁 七 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, '第七 天,祭司 要再 察看 他,若 灾病 发暗,而且 没有 在皮上 发散,祭司 要定他为洁净,原来是 癣;那人就要洗 衣服,得为洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, '但他为得洁净,将身体给 祭司 察看 以后,癣 若 在皮上 发散 开 了,他要再 将身体给 祭司 察看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, '祭司 要察看, 癣 若在皮上 发散, 就要定他为不洁净,是 大痲疯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, '「 人 有了 大痲疯 的灾病,就要将他带 到 祭司面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, '祭司 要察看, 皮上 若长了白 疖, 使毛 变 白,在长白疖 之处有了红 瘀 肉, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, '这是 肉 皮上 的旧 大痲疯,祭司 要定他为不洁净,不用 将他关锁,因为 他是 不洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, '大痲疯 若 在皮上 四外 发散, 长满了 患灾病 人的皮,据祭司 察看,从头 到 脚 无处不有, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, '祭司 就要察看, 全身的 肉 若长满了 大痲疯,就要定那 患灾病 的为洁净;全身 都变为 白,他乃 洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, '但红 肉 几时 显 在他的身上 就几时不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, '祭司 一看 那 红 肉 就定他为不洁净。红 肉 本是 不洁净,是 大痲疯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, '红 肉 若 复原,又变 白了,他就要来 见 祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, '祭司 要察看, 灾病处 若变 白了,祭司 就要定那 患灾病 的为洁净,他乃 洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, '「人若 在皮 肉 上 长 疮,却治好了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, '在长疮 之处 又起了 白 疖,或是 白 中带红 的火斑,就要给 祭司 察看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, '祭司 要察看, 若现象 洼 于  皮,其上的毛 也变 白了, 就要定他为不洁净,是 大痲疯 的灾病 发 在疮中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, '祭司 若 察看, 其上 没有 白 毛,也没有 洼 于  皮,乃是 发暗, 就要将他关锁 七 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, '若 在皮上 发散 开 了,祭司 就要定他 为不洁净,是 灾病。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, '火斑 若 在原处 止住,没有 发散,便是 疮 的痕迹,祭司 就要定他为洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, '「人的皮 肉上 若 起了 火 毒,火毒的瘀 肉 成了 火斑,或是 白 中带红的,或是 全白的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, '祭司 就要察看, 火斑中 的毛 若变 白了,现象 又深 于  皮,是 大痲疯 在火毒中 发出, 就要定他 为不洁净,是 大痲疯 的灾病。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, '但是 祭司 察看, 在火斑中 若没有 白 毛,也没有 洼 于  皮,乃是 发暗, 就要将他关锁 七 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, '到第七 天,祭司 要察看他,火斑若 在皮上 发散 开 了, 就要定他 为不洁净,是 大痲疯 的灾病。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, '火斑 若 在原处 止住,没有 在皮上 发散,乃是 发暗,是 起的火 毒,祭司 要定他为洁净,不过 是 火毒 的痕迹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, '「无论 男 女,若在头上 有 灾病,或是 男人胡须上有灾病, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, '祭司 就要察看;这 灾病 现象 若深 于  皮,其间 有细 黄 毛, 就要定他 为不洁净,这是 头疥,是头上 或 是 胡须上 的大痲疯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, '祭司 若 察看 头疥 的灾病, 现象 不 深 于  皮,其间 也没有 黑 毛, 就要将 长头疥 灾病 的关锁 七 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, '第七 天,祭司 要察看 灾病, 若头疥 没有 发散,其间 也没 有 黄 毛,头疥 的现象 不 深 于  皮, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, '那人就要剃去须发,但他不可 剃 头疥之处。祭司 要将 那长头疥的,再 关锁 七 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, '第七 天,祭司 要察看 头疥, 头疥 若没有 在皮上 发散,现象 也不 深 于  皮, 就要定他 为洁净,他要洗 衣服,便成为洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, '但他得洁净 以后,头疥 若 在皮上 发散 开 了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, '祭司 就要察看他。 头疥 若在皮上 发散, 就不必 找 那黄 毛,他是 不洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, '祭司若 看 头疥 已经止住,其间 也长了 黑 毛,头疥 已然痊愈,那人是 洁净了, 就要定他为洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, '「无论男 女,皮 肉上 若 起了 火斑,就是白 火斑, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, '祭司 就要察看, 他们肉 皮上 的火斑 若白 中带黑,这是 皮上 发出 的白癣,那人是 洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, '「人 头上 的发若 掉了,他不过是 头秃,还是 洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, '他顶 前 若 掉了头发,他不过是 顶门秃,还是 洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, '头秃处 或是 顶门秃处 若 有 白中 带红 的灾病,这就是 大痲疯 发 在他头秃处 或是 顶门秃处, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, '祭司 就要察看, 他起的 那灾病 若在头秃处 或是 顶门秃处 有白中 带红的,像肉 皮上 大痲疯 的现象, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, '那人 就是 长大痲疯, 不洁净的,祭司 总要 定他为不洁净,他的灾病 是在头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, '「身上 有长大痲疯 灾病 的,他的衣服 要 撕裂,也要 蓬头 散发,蒙著 上唇,喊叫说:『不洁净了!不洁净了!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, '灾病 在他身上 的 日子,他便是不洁净;他既是 不洁净,就要独 居 营 外。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, '「染了 大痲疯 灾病 的衣服,无论 是 羊毛 衣服、是 麻布 衣服, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, '无论是 在经上、 在纬上,是麻布的、是羊毛的,是 在皮子上,或 在皮子 做的 什么物件上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, '或在衣服上、 皮子上, 经上、 纬上,或 在皮子 做的什么 物件上,这灾病 若是 发绿,或是 发红,是 大痲疯 的灾病,要给 祭司 察看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, '祭司 就要察看 那 灾病,把 染了灾病 的物件关锁 七 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, '第七 天,他要察看 那 灾病,灾病 或 在衣服上, 经上、 纬上, 皮子上,若发散,这皮子 无论 当作 何 用,这灾病 是蚕食的 大痲疯,都是 不洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, '那 染了 灾病 的 衣服,或是 经上、 纬上,羊毛上, 麻衣上,或是 皮子 做的什么 物件上,他都要焚烧;因为 这是 蚕食的 大痲疯,必在火中 焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, '「祭司 要察看, 若 灾病 在衣服上, 经上、 纬上,或是 皮子 做的什么 物件上,没有 发散, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, '祭司 就要吩咐他们,把 染了 灾病 的 物件洗了,再 关锁 七 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, '洗过 以后,祭司 要察看, 那 物件 若没有 变 色,灾病 也没有 消散,那物件就 不洁净,是 透重的灾病,无论 正面 反面,都要在火中 焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, '洗过 以后,祭司 要察看,若 见 那灾病 发暗,他就要把那灾病 从 衣服上、 皮子上、 经上、 纬上,都撕去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, '若 仍 现 在衣服上,或是 经上、 纬上、 皮子 做的什么 物件上,这就是 灾病又发了、必用火 焚烧 那 染灾病 的 物件。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, '所 洗的 衣服,或是 经,或是 纬,或是 皮子 做的什么 物件,若灾病 离开 了,要再 洗,就洁净了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, '这就是 大痲疯 灾病 的条例,无论是在羊毛 衣服上, 麻布衣服上, 经上、 纬上,和 皮子 做的什么 物件上,可以定为洁净 或是 不洁净。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, '「长大痲疯 得洁净 的日子,其例 乃是 这样:要带他 去见 祭司; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, '祭司 要出 到 营 外 察看, 若见 他的 大痲疯 痊愈了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, ' 就要吩咐人 为那求洁净的 拿 两只 洁净的 活 鸟 和香柏 木、朱红色线 缐,并牛膝草来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, '祭司 要吩咐 用 瓦 器 盛活 水,把 一只 鸟 宰 在上面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, '至于 那只 活 鸟,祭司要把 牠 和 香柏 木、 朱红色线 缐 并 牛膝草 一同 蘸 于  宰 在 活 水 上的鸟 血中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, '用以在 那长大痲疯 求洁净的 人身上洒 七 次,就定他为洁净,又把 活 鸟 放 在 田野 里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, '求洁净的人 当洗 衣服,剃去 毛发,用水 洗澡,就洁净了;然后 可以进 营,只是要在自己的帐棚 外 居住 七 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, ' 第七 天, 再把 头上 所有的 头发 与 胡须、 眉毛,并 全身 的毛,都剃了;又要洗 衣服,用水 洗 身,就洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, '「第八 天,他要取 两只 没有残疾 的公羊羔 和一只 没有残疾、一 岁 的母羊羔,又要把调 油 的细面 麺 伊法十分 之三 为素祭,并油 一 罗革,一同取来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, '行洁净 之礼的祭司 要将 那求洁净 的人 和这些东西 安置 在会 幕 门口、耶和华 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, '祭司 要取 一只 公羊羔 献 为赎愆祭,和那 一罗革 油 一同作 摇祭,在耶和华 面前 摇一摇; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, '把 公羊羔 宰 于 圣 地,就是 宰 赎罪祭牲 和 燔祭牲 之地。 赎愆祭 要 归祭司,与赎罪祭一样,是 至 圣的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, '祭司 要取 些赎愆祭牲 的血, 抹 在 求洁净人 的右 耳 垂上 和 右 手 的大拇指上,并 右 脚 的大拇指上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, '祭司 要从那一罗革 油 中取 些倒 在 自己 的左手 掌里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, ' 把 右手 的一个指头 蘸 在 左 手 的 油里,在耶和华 面前 用指头 弹 七 次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, ' 将手里 所 剩的 油 抹 在 那求洁净人 的右 耳 垂 上和 右 手 的大拇指上,并 右 脚 的大拇指上,就是抹在 赎愆祭牲 的血上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, '祭司 手里 所 剩的 油 要抹 在 那求洁净人 的头上, 在耶和华 面前 为他 赎罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, '祭司 要献 赎罪祭,为 那本不洁净、求洁净的人 赎罪;然后 要宰 燔祭牲, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, ' 把 燔祭 和 素祭 献 在坛上, 为他 赎罪,他就洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, '「他 若 贫穷 不 能预备 够数,就要取 一只 公羊羔 作赎愆祭,可以摇一摇,为他 赎罪;也要把调 油 的细面 麺 伊法十分 之一 为素祭,和油 一罗革一同取来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, '又照 他的力量 取 两只 斑鸠 或是 两只 雏 鸽,一只 作 赎罪祭,一只 作燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, '第八 天,要为洁净,把这些 带 到 会 幕 门口、耶和华 面前,交给 祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, '祭司 要 把 赎愆祭 的羊羔 和那 一罗革 油 一同作摇祭, 在耶和华 面前 摇一摇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, '要宰了 赎愆祭 的羊羔, 取 些赎愆祭牲 的血,抹 在 那求洁净人 的右 耳 垂上 和 右 手 的大拇指上,并 右 脚 的大拇指上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, '祭司 要把些油 倒 在 自己的 左手 掌里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, '把 左 手 里的 油,在耶和华 面前,用右手 的一个指头 弹 七 次, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, ' 又把手里 的 油 抹 些 在 那求洁净人 的右 耳 垂 上和 右 手 的大拇指上,并 右 脚 的大拇指上,就是 抹赎愆祭 之血 的原处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, '祭司 手里 所 剩的 油 要抹 在 那求洁净人 的头上,在耶和华 面前 为他 赎罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, '那人又要照 他的力量 献上 一只 斑鸠 或是一只 雏 鸽, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, '就是 他 所 能办的, 一只 为赎罪祭, 一只 为燔祭,与素祭 一同献上;祭司 要在耶和华 面前 为他 赎罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, '这是 那 有 大痲疯 灾病 的人、不能 将关乎得洁净之物 预备够数 的条例。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, '耶和华 晓谕 摩西、 亚伦 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, '「 你们到了 我 赐 给你们 为业 的 迦南 地,我若使 你们所得为业 之地 的房屋中 有大痲疯 的灾病, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, '房 主 就要去 告诉 祭司 说:『据我 看,房屋中 似乎有灾病。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, '祭司 还没有进去 察看 灾病 以前, 就要吩咐 人把 房子 腾空,免得 房子里 所有的 都成了不洁净;然后 祭司 要进去 察看 房子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, '他要察看 那 灾病, 灾病 若在房子 的墙上 有发绿 或 发红 的凹斑纹,现象 洼 于  墙, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, '祭司 就要出 到 房 门外,把 房子 封锁 七 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, '第七 天,祭司 要再去 察看, 灾病 若在房子 的墙上 发散, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, ' 就要吩咐人 把 那 有灾病 的石头 挖出来,扔 在 城 外 不洁净 之处; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, '也要叫人刮 房内 的四围, 所 刮掉 的灰泥 要倒 在 城 外 不洁净 之处; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, '又要用 别的 石头 代替 那挖出来 的石头,要另 用 灰泥 墁 房子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, '「他挖出 石头,刮了 房子,墁了 以后,灾病 若 在房子里 又 发现, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, '祭司 就要进去 察看, 灾病 若在房子里 发散,这就是 房内 蚕食的 大痲疯,是 不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, '他就要拆毁 房子,把 石头、 木头、 灰泥 都 搬 到 城 外 不洁净 之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, '在房子 封锁 的时候,进去的人 必不洁净 到 晚上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, '在房子里 躺著的 必洗 衣服;在房子里 吃饭的 也必洗 衣服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, '「 房子 墁了 以后,祭司 若 进 去 察看,见 灾病 在房内 没有 发散,就要定 房子 为洁净,因为 灾病 已经消除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, '要为洁净 房子 取 两只 鸟 和香柏 木、朱红色线 缐 并牛膝草, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, '用 瓦 器 盛活 水,把 一只 鸟 宰 在上面, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, ' 把 香柏 木、 牛膝草、 朱红色线 缐,并 那活 鸟,都 蘸 在被宰的 鸟 血中 与活 水中,用以洒 房子 七 次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, '要用鸟 血、活 水、活 鸟、香柏 木、牛膝草,并朱红色线 缐,洁净 那 房子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, '但要把 活 鸟 放 在 城 外 田野 里。这样洁净房子(原文是为 房子 赎罪),房子就洁净了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, '这是 为各类 大痲疯 的灾病 和头疥, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, '并衣服 与房子 的大痲疯, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, '以及疖子、癣、火斑 所立的条例, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, '指明 何时 为洁净,何时 为不洁净。这是 大痲疯 的条例。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, '耶和华 对 摩西、亚伦 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, '「你们晓谕 以色列 人 说: 人 若 身 患 漏症,他 因这漏症 就不洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, '他 患漏症,无论是 下流的, 是 止住的,都 是 不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, '他 所 躺的 床 都 为不洁净,所 坐的 物 也为 不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, '凡 摸 那床 的,必不洁净 到 晚上,并要洗 衣服,用水 洗澡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, '那坐 患漏症人 所 坐之 物的,必不洁净 到 晚上,并要洗 衣服,用水 洗澡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, '那摸 患漏症人 身体的,必不洁净 到 晚上,并要洗 衣服,用水 洗澡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, '若 患漏症人 吐 在洁净的人身上,那人必不洁净 到 晚上,并要洗 衣服,用水 洗澡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, '患漏症人 所 骑的 鞍子 也为不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, '凡 摸了 他身下之物的,必不洁净 到 晚上;拿了 那物的,必不洁净 到 晚上,并要洗 衣服,用水 洗澡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, '患漏症的 人没有 用水 涮 手,无论 摸了 谁,谁 必不洁净 到 晚上,并要洗 衣服,用水 洗澡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, '患漏症人 所 摸的 瓦 器 就必打破;所摸的一切 木 器 也必用水 涮洗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, '「 患漏症的 人痊愈了,就要为洁净 自己 计算 七 天,也必洗 衣服,用活 水 洗 身,就洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, '第八 天,要取 两只 斑鸠 或是 两只 雏 鸽,来 到 会 幕 门口、耶和华 面前,把鸟交 给 祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, '祭司 要献上 一只 为赎罪祭,一只 为燔祭;因那人患的漏症,祭司 要在耶和华 面前 为他 赎罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, '「人 若 梦遗,他必不洁净 到 晚上,并要用水 洗 全 身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, '无论 是衣服是 皮子,被 精 所 染,必不洁净 到 晚上,并要用水 洗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, '若男 女 交合,两个人 必不洁净 到 晚上,并要用水 洗澡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, '「女人行经,必 污秽 七 天;凡 摸 她的,必不洁净 到 晚上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, '女人在污秽之中,凡 她所 躺的物件 都为不洁净, 所 坐的物件 也都不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, '凡 摸 她床的,必不洁净 到 晚上,并要洗 衣服,用水 洗澡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, '凡 摸 她所 坐 什么 物件的,必不洁净 到 晚上,并要洗 衣服,用水 洗澡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, '在 女人 的床上,或 在 她 坐 的 物 上,若有别的物件,人一摸了,必不洁净 到 晚上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, '男人 若 与那女人 同房,染了 她的污秽,就要七 天 不洁净; 所 躺 的 床 也为不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, '「女人 若 在经 期 以外 患 多 日 的血 漏,或 是 经期过长,有了漏症,她就 因这漏症 不洁净,与她 在经 期 不洁净一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, '她在患漏症的 日子 所 躺 的 床、 所 坐 的 物 都要看为 不洁净,与她 月经的时候一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, '凡 摸 这些物件的,就为不洁净,必不洁净 到 晚上,并要洗 衣服,用水 洗澡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, '女人的漏症 若 好了,就要计算 七 天,然后 才为洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, '第八 天,要取 两只 斑鸠 或是 两只 雏 鸽,带 到 会 幕 门口 给 祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, '祭司 要献 一只 为赎罪祭, 一只 为燔祭;因那人血漏 不洁,祭司 要在耶和华 面前 为她 赎罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, '「你们要这样使 以色列 人 与他们的污秽 隔绝,免得 他们玷污我的 帐幕,就因自己的污秽 死亡。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, '这是 患漏症和 梦遗 而不洁净的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, '并有月经 病 的和患 漏症的,无论男 女,并人 与 不洁净 女人同房 的条例。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, '亚伦 的两个 儿子 近到 耶和华 面前 死了。死了 之后,耶和华 晓谕 摩西说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, '「要告诉 你哥哥 亚伦,不可 随 时 进 圣所 的幔子 内、到 柜上 的 施恩座 前,免得 他死亡,因为 我要从云中 显现 在 施恩座上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, ' 亚伦 进 圣所,要带一只公牛 犊 为赎罪祭,一只公绵羊 为燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, '要穿上 细麻布 圣 内袍,把细麻布 裤子穿 在 身上,腰束 细麻布 带子,头戴 细麻布 冠冕;这都是 圣 服。他要用水 洗 身,然后穿戴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, '要从 以色列 会众 取 两只 公 山羊 为赎罪祭,一只 公绵羊 为燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, '「亚伦 要把 赎罪祭 的 公牛 奉上,为自己 和 本家 赎罪; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, '也要 把 两只 公山羊 安置 在会 幕 门口、耶和华 面前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, ' 为 那两只 羊 拈 阄,一 阄 归与耶和华,一 阄 归与阿撒泻勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, '亚伦 要 把 那 拈 阄 归 与耶和华 的羊 献 为赎罪祭, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, '但那 拈 阄 归 与阿撒泻勒 的羊 要活著 安置 在耶和华 面前,用以 赎罪,打发人送 到旷野去,归与阿撒泻勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, '「亚伦 要把 赎罪祭 的 公牛 牵来 宰了,为自己 和 本家 赎罪; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, '拿 香炉, 从耶和华 面前 的坛 上 盛满 火 炭,又拿一 捧 捣细的 香料,都带入 幔子 内, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, '在耶和华 面前,把 香 放 在 火上,使香 的烟云 遮掩 法柜 上 的 施恩座,免得 他死亡; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, '也要取 些公牛 的血,用指头 弹 在 施恩座 的东 面,又在施恩座 的前面 弹 血 七 次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, '「随后他要宰 那 为百姓 作赎罪祭 的公山羊,把 羊的血 带 入 幔子 内,弹 在 施恩座 的上面和 前面, 好像 弹 公牛 的血一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, '他因以色列 人 诸般的污秽、过犯,就是他们一切的 罪愆,当这样在 圣所 行赎罪之礼,并因会 幕 在 他们 污秽 之中,也要照样 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, '他进 圣所 赎罪的时候,会 幕里 不可 有人,直等到 他为自己 和 本家 并 以色列 全 会众 赎了罪 出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, '他出来,要到 耶和华 面前 的 坛那里,在 坛上行赎罪之礼,又要取些 公牛 的血 和公山羊 的血,抹 在 坛上 四角 的周围; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, '也要用指头 把血 弹 在 坛上七 次,洁净了坛,从坛上除掉以色列 人 诸般的污秽,使坛成圣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, '「亚伦为 圣所 和 会 幕 并 坛 献完了 赎罪祭,就要把 那只活著的 公山羊 奉上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, ' 两 手 按 在 羊 头上,承认 以色列 人 诸般的 罪孽 过犯,就是他们一切的 罪愆,把这罪 都归 在 羊 的头上,藉 借著所派 之人 的手,送到 旷野去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, '要把 这羊 放 在旷野, 这羊 要担当 他们一切的 罪孽,带到 无人 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, '「亚伦 要进 会 幕,把 他进 圣所 时所 穿的 细麻布 衣服 脱下,放 在那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, '又要在圣 处 用水 洗 身,穿上 衣服,出来,把 自己的燔祭 和 百姓的 燔祭 献上,为自己 和 百姓 赎罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, ' 赎罪祭 牲的脂油 要在坛上 焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, '那放 羊 归与阿撒泻勒 的人要洗 衣服,用水 洗 身,然后 进 营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, '作 赎罪祭 的公牛 和 公山羊 的 血 既带入 圣所 赎罪,这牛羊就要搬 到 营 外,将 皮、 肉、 粪 用火 焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, '焚烧的 人要洗 衣服,用水 洗 身,然后 进 营。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, '「每逢七 月 初 十日,你们要刻苦 己心,无论是本地人,是寄居 在你们中间 的外人,什么 工 都不可 做;这要作 你们 永远 的定例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, '因 在这 日 要为你们 赎罪,使你们 洁净。你们要在耶和华 面前 得以洁净,脱尽一切的 罪愆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, '这日 你们 要守为圣安息 日,要刻苦 己心;这为永远 的定例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, '那 受膏、 接续 他父亲 承接 圣职 的 祭司 要穿上 细麻布 的圣 衣,行赎罪之礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, '他要在 至圣 所和 会 幕与 坛 行赎罪之礼,并要为 众祭司 和 会众 的百姓 赎罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, '这 要作 你们 永远 的定例─就是因 以色列 人 一切的 罪,要一年 一次 为他们赎罪。」于 是,亚伦照 耶和华 所吩咐 摩西 的行了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, '「你晓谕 亚伦和 他儿子 并 以色列 众 人 说,耶和华 所 吩咐 的乃是这样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, '凡 以色列 家中的 人 宰 公牛,或是 绵羊羔,或是 山羊,不拘 宰 于 营内 营 外, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, '若未 曾牵 到 会 幕 门口、耶和华 的帐幕 前 献 给耶和华 为供物,流血 的罪必归 到那 人身上。他流了 血, 要 从民 中 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, '这是 为要 使以色列 人 把 他们 在 田野 里 所 献 的祭 带 到 会 幕 门口、耶和华面前,交给 祭司,献 与耶和华 为平安 祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, '祭司 要把 血 洒 在 会 幕 门口、耶和华 的坛上,把脂油 焚烧,献给耶和华 为馨 香的祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, '他们不可 再 献 祭 给他们 行邪淫 所 随从 的鬼魔(原文是公山羊);这 要作 他们 世世代代 永远 的定例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, '「你要晓谕 他们说:凡 以色列 家中 的人,或是寄居 在他们中间 的 外人, 献 燔祭 或是 平安祭, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, '若不 带 到 会 幕 门口 献 给耶和华,那人 必 从民中 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, '「凡 以色列 家中 的人,或是寄居 在他们中间 的外人,若 吃 什么 血,我必向那吃 血 的人 变 脸,把他 从民 中 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, '因为 活物 的生命 是 在血中。我 把这血赐 给你们,可以在 坛上 为 你们的生命 赎罪;因 血 里有 生命,所以能赎罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, '因此,我对以色列 人 说:你们 都 不可 吃 血;寄居 在你们中间 的外人 也不可 吃 血。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, '凡 以色列 人,或是寄居 在他们中间 的外人,若 打猎 得了 可吃 的 禽 兽,必放出 牠的血来,用土 掩盖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, '「论到 一切 活 物 的生命,就在 血中。所以我对以色列 人 说:无论什么 活物 的血,你们都不可 吃,因为 一切 活物 的血 就是 他的生命。凡 吃了血的,必被剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, '凡 吃 自死的,或是被野兽撕裂的,无论是本地人,是寄居的,必不洁净 到 晚上,都要洗 衣服,用水 洗身,到了晚上才为洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, '但他若 不 洗衣服,也不 洗 身,就必担当 他的罪孽。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, '「你晓谕 以色列 人 说:我是 耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, '你们从前住 的 埃及 地,那里人的行为,你们不可 效法,我要 领 你们 到的 迦南 地,那里 人的行为 也不可 效法,也不可 照他们的恶俗 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, '你们要遵 我的典章,守 我的律例,按此 而行。我是 耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, '所以,你们要守 我的律例 典章;人 若 遵行,就必因此 活著。我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, '「你们 都 不可 露 骨肉 之亲 的下体,亲近他们。我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, '不可 露 你母亲 的下体,羞辱 了你父亲。她是 你的母亲,不可 露 她的下体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, '不可 露 你继母 的下体;这本是 你父亲 的下体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, '你的姊妹,不拘是异母同父 的,是 异父同母 的,无论 是生 在家 生 在外的,都不可 露 她们的下体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, '不可 露 你孙 女 或是 外孙 女 的下体,露了她们 的下体 就是 露了自己的下体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, '你继母 从你父亲 生 的女儿 本是 你的妹妹,不可 露 她的下体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, '不可 露 你姑母 的下体;她是 你父亲 的骨肉之亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, '不可 露 你姨母 的下体; 她是 你母亲 的骨肉之亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, '不可 亲近 你伯叔之妻, 羞辱了 你伯叔;她是 你的伯叔母。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, '不可 露 你儿妇 的下体;她是 你儿子 的妻,不可 露 她的下体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, '不可 露 你弟兄 妻子 的下体;这本是 你弟兄 的下体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, '不可 露了 妇人 的下体,又露 她女儿 的下体,也不可 娶 她孙女 或是 外孙女,露 她们的下体;她们是 骨肉之亲,这本是 大恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, '你妻 还在的时候,不可 另娶 她的姊妹 作对头,露 她的下体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, '「女人 行经 不洁净的时候,不可 露 她的下体,与她 亲近。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, '不可 与 邻舍 的妻 行 淫,玷污自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, '不可 使 你的儿女 经火 归与摩洛,也不可 亵渎你 神 的名。我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, '不可 与 男人 苟合,像与 女人一样;这本是 可憎恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, '不可 与 兽 淫合,玷污 自己。女人 也不可 站在 兽 前,与牠淫合;这本是 逆性的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, '「在这 一切的事上,你们都不可 玷污自己;因为 我 在你们面前 所 逐出 的列邦,在这 一切的事上 玷污了自己; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, '连地 也玷污了,所以我追讨 那地的罪孽,那地 也吐出 它的居民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, '故此,你们 要守 我的律例 典章。这 一切 可憎恶的事,无论是本地人,是寄居 在你们中间 的外人,都不可 行, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, '( 在你们以先 居住那地 的 人 行了 这 一切 可憎恶的事,地 就玷污了,) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, '免得 你们玷污 那地的时候,地 就把你们 吐出,像 吐出 在你们以先 的 国民一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, ' 无论 什么 人,行了 其中 可憎的 一件事,必从民 中 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, '所以,你们要守 我所吩咐的,免得 你们随从 那些可憎 的恶俗,就是 在你们以先 的人所常行的,以致 玷污了自己。我是 耶和华─你们的 神。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, '「你晓谕 以色列 全 会众 说:你们要 圣洁,因为 我 耶和华─你们的 神 是圣洁的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, '你们各人 都当孝敬 父 母,也要守 我的安息日。我是 耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, '你们不可 偏 向 虚无的神,也不可 为自己 铸造 神 像。我是 耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, '「 你们献 平安 祭 给耶和华的时候,要献得 可蒙悦纳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, '这祭物要在献的 那一天 和第二天 吃,若有剩 到 第三 天的,就必用火 焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, '第三 天 若 再吃,这就为 可憎恶的,必不 蒙悦纳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, '凡吃的人 必担当 他的罪孽;因为 他亵渎了 耶和华 的圣物,那 人 必从民中 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, '「在你们的地 收割 庄稼,不可 割 尽 田 角,也不可 拾取 所遗落的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, '不可 摘尽 葡萄园的果子,也不可 拾取 葡萄园 所掉的果子;要留 给穷人 和寄居的。我是 耶和华你─们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, '「你们不可 偷盗,不可 欺骗,也不可 彼此 说谎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, '不可 指著我的名 起 假誓,亵渎你 神 的名。我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, '「不可 欺压 你的邻舍,也不可 抢夺他的物。雇工人的 工价,不可 在你那里 过夜,留到 早晨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, '不可 咒骂 聋子,也不可 将绊脚石 放在 瞎子 面前,只要敬畏你的 神。我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, '「你们施行审判,不可 行 不义;不可 偏护 穷人,也不可 重看 有势力的人,只要按著公义 审判 你的邻舍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, '不可 在民中 往来 搬弄是非,也不可 与邻舍 为敌,置之于 死(原文是流他的血)。我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, '「不可 心里 恨 你的弟兄;总要 指摘 你的邻舍,免得 因他 担 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, '不可 报仇,也不可 埋怨 你本国的 子民,却要爱 人 如己。我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, '「你们要守 我的律例。不可 叫你的牲畜 与异类 配合;不可 用两样搀杂的种 种 你的地,也不可 用两样搀杂的 料 做衣服 穿 在身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, '「 婢女 许配了 丈夫,还没有 被 赎、 得 释放,人 若 与 她 行 淫,二人要 受刑罚,却不 把他们治死,因为 婢女还没有 得自由。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, '那人要把 赎愆祭,就是 一只公绵羊 牵 到 会 幕 门口、耶和华面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, '祭司 要用赎愆祭 的羊 在耶和华 面前 赎 他 所 犯的 罪,他 的 罪 就必蒙赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, '「 你们到了 迦南地,栽种 各样 结果子的 树木,就要以 所结的 果子 如未受割礼的一样。三 年之久,你们要 以这些果子,如未受割礼的,是不可 吃的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, '但第四 年 所结的果子 全 要成为 圣,用以赞美 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, '第五 年,你们要吃 那 树上的果子,好叫树给你们 结 果子更多。我是 耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, '「你们不可 吃 带 血的物;不可 用法术,也不可 观兆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, '头的 周围(或译:两鬓)不可 剃, 胡须的 周围 也不可 损坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, '不可 为死人 用刀划 㓰 身,也不可 在身上 刺 花 纹。我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, '「不可 辱没 你的女儿,使她为娼妓,恐怕 地上 的人专向淫乱,地 就满了 大恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, '你们要守 我的安息日,敬 我的圣所。我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, '「不可 偏 向 那些交鬼的 和 行巫术的;不可 求问他们,以致被他们 玷污了。我是 耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, '「在白发的 人面前,你要站起来;也要尊敬 老人,又要敬畏你的 神。我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, '「若有 外人 在你们国中 和你 同居,就不可 欺负 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, '和你们 同居的 外人,你们 要 看他如本地人一样,并要爱 他 如己,因为 你们在埃及 地 也作 过寄居的。我是 耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, '「你们施行审判,不可 行 不义;在尺、秤、升、斗上也是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, '要 用公道 天平、公道 法码、公道 升斗、公道 秤。我是 耶和华─你们的 神,曾把你们 从埃及 地 领出来 的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, '你们要谨守 遵行 我一切的 律例 典章。我是 耶和华。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, '「你还要晓谕 以色列 人 说:凡 以色列 人,或是在以色列中 寄居的 外人, 把自己的儿女 献 给摩洛的,总要 治死他;本地 人 要用石头 把他打死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, '我 也要 向那 人 变脸,把他 从民 中 剪除;因为 他把儿女 献 给摩洛, 玷污 我的圣所,亵渎 我的圣 名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, '那 人 把儿女 献 给摩洛,本地 人 若 佯为 不见,不 把他 治死, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, '我 就要 向这 人 和他的家 变 脸,把他 和 一切 随他 与 摩洛 行邪淫的 人都从民 中 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, '「人 偏 向 交鬼的和 行巫术的,随他们 行邪淫,我要 向那 人 变 脸,把他 从民 中 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, '所以你们要自洁 成 圣,因为 我是 耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, '你们要谨守 遵行 我的律例;我是 叫你们成圣的 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, ' 凡 咒骂 父 母 的,总要 治死他;他咒骂了 父 母,他的罪(原文是血;本章同)要归到他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, '「 与 邻舍 之妻 行淫的,奸夫 淫妇 都必 治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, ' 与 继母 行淫 的,就是羞辱了 他父亲,总要 把他们二人 治死,罪 要归到他们身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, ' 与 儿妇 同房 的,总要把 他们二人 治死;他们行了 逆伦的事,罪 要归到他们身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, '人 若 与 男人 苟合,像与女人 一样,他们二人 行了 可憎的事,总要 把他们治死,罪 要归到他们身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, '人 若 娶 妻,并娶 其母,便是 大恶,要把这三人 用火 焚烧,使 你们中间 免去 大恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, '人 若 与兽 淫合,总要 治死他,也要杀 那 兽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, '女人 若 与 兽 亲近,与牠 淫合,你要杀 那女人 和 那兽,总要 把他们治死,罪 要归到他们身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, '「人 若 娶 他的姊妹,无论是异母同父 的,是 异父同母 的,彼此见了 下体, 这是 可耻的事;他们必在本民 的眼前 被剪除。他露了 姊妹 的下体,必担当 自己的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, '妇人 有月经, 若 与她 同房,露了 她的下体,就是露了 妇人的血源,妇人 也露了 自己的血 源,二人 必从民 中 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, '不可 露 姨母 或是姑母 的下体,这是 露了 骨肉之亲的下体;二人必担当 自己的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, '人 若 与 伯叔之妻 同房,就羞辱了 他的伯叔;二人要担当 自己的罪,必无子女 而死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, '人 若 娶 弟兄 之妻,这本是 污秽的事,羞辱了 他的弟兄; 二人必无子女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, '「所以,你们要谨守 遵行 我一切的 律例 典章,免得 我 领 你们 去住 的那 地 把你们 吐出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, '我 在你们面前 所 逐出 的国民,你们不可 随从 他们的风俗;因为 他们行了 这 一切的事,所以我厌恶 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, '但我对你们 说过,你们要 承受 他们的地,就是我要 赐 给你们 为业、流 奶 与蜜 之地。我是 耶和华─你们的 神, 使你们 与万民 有分别的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, '所以,你们要把洁净 和 不洁净 的禽 兽 分别出来;不可因我 给你们 分为 不洁净的 禽 兽,或是 滋生 在地上的活物,使 自己 成为可憎恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, '你们要 归我 为圣,因为 我─耶和华 是圣的,并叫你们 与 万民 有分别,使你们作 我的民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, '「无论 男 女, 是 交鬼的 或 行巫术的,总要 治死他们。人必用石头 把他们 打死,罪 要归到他们身上。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, '耶和华 对 摩西 说:「你告诉 亚伦 子孙 作祭司 的说:祭司不可 为民中 的死人 沾染自己, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, '除非 为他 骨肉 之亲 的父 母、儿 女、弟兄, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, '和未 曾 出嫁、作处女 的 姊妹,才可以沾染 自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, '祭司既在民中 为首,就不可 从俗 沾染自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, '不可 使 头 光秃;不可 剃除 胡须 的周围,也不可 用刀划 㓰 身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, '要归 神 为圣,不可 亵渎 神 的名;因为 耶和华 的火祭,就是 神 的食物,是他们 献的,所以他们要成为 圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, '不可 娶 妓女 或被污 的女人为妻,也不可 娶被 休的 妇人为妻,因为 祭司是归 神 为圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, '所以你要使他成圣,因为 他 奉献你 神 的食物;你 要以他为 圣,因为 我─使你们成圣的 耶和华─是圣的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, '祭司 的 女儿 若 行淫 辱没自己,就 辱没了 父亲,必用火 将她焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, '「在弟兄中 作大 祭司、 头 上 倒了 膏 油、又承接圣职,穿了 圣衣的,不可 蓬 头散发,也不可 撕裂 衣服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, '不可 挨 近 死 尸,也不可 为父 母 沾染自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, '不可 出 圣所,也不可 亵渎 神 的圣所,因为 神 膏 油 的冠冕 在他头上。我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, '他 要娶 处女 为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, '寡妇 或是被休的妇人,或是被污 为妓的女人, 都 不可 娶;只可 娶 本民中 的处女 为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, '不可 在民中 辱没 他的儿女,因为 我是 叫他成圣的 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, '「你告诉 亚伦 说:你世世代代 的后裔,凡 有 残疾的,都不可 近前 来献他 神 的食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, '因为 凡 有残疾的,无论是瞎眼的、 瘸腿的、 塌鼻子的、 肢体有余 馀的、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, ' 折 脚 折 手的、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, ' 驼背的、 矮矬的、 眼睛 有毛病的、 长癣的、 长疥的,或是 损坏 肾子的,都不可近前来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, '祭司 亚伦 的后裔,凡 有残疾的,都不可 近前来,将 火祭 献 给耶和华。他 有残疾,不可 近前来 献 神 的食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, '神 的食物,无论是圣的,至 圣的,他都可以吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, '但 不可 进 到 幔子前,也不可 就近 坛前;因为 他 有残疾,免得 亵渎 我的圣所。 我是 叫他成圣的 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, '于 是,摩西 晓谕 亚伦 和 亚伦的子孙,并 以色列 众 人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, '「你吩咐 亚伦 和 他子孙说:要远离 以色列 人 所 分别为圣、归 给我 的圣物,免得 亵渎 我的圣 名。我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, '你要对他们 说:你们世世代代的 后裔,凡 身上 有污秽、亲近 以色列 人 所 分别为圣、归耶和华 圣物 的,那 人 必在我面前 剪除。我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, '亚伦 的后裔,凡 长 大痲疯的,或是 有漏症的,不可 吃 圣物,直等 他 洁净了。无论谁 摸 那因死尸 不洁净的物(或译:人),或是 遗 精 的 人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, '或是 摸 什么 使他 不洁净 的 爬物,或是 摸那 使他 不洁净 的人(不拘那人有什么 不洁净), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, ' 摸了这些人、物 的,必不洁净 到 晚上;若不 用水 洗 身,就不可 吃 圣物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, '日 落的时候,他就洁净了,然后 可以吃 圣物,因为 这是 他的食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, '自死的 或是被野兽撕裂的,他不可 吃,因此 污秽自己。我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, '所以他们要守 我所吩咐的,免得 轻忽了,因此 担 罪 而死。我是 叫他们成圣的 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, '「凡 外人 不可 吃 圣物;寄居 在祭司家的,或是雇工人,都不可 吃 圣物; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, '倘若 祭司 买  人,是他的钱 买 的,那人 就可以吃 圣物;生 在他家的人也 可以吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, '祭司 的女儿 若 嫁 外 人, 就不可 吃 举祭的 圣物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, '但祭司 的女儿 若 是 寡妇,或是被休的,没有 孩子,又归 回 父 家,与她青年一样,就可以吃 她父亲的 食物;只是 外人 不可 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, '若 有人 误 吃了 圣物,要照 圣物 的原数加 上 五分之一 交 给祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, '祭司不可 亵渎 以色列 人 所 献 给耶和华的 圣物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, '免得他们 在吃 圣物 上自取 罪 孽,因为 我是 叫他们成圣的 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, '「你晓谕 亚伦 和 他子孙,并 以色列 众 人 说:以色列 家中 的人,或在以色列中 寄居的,凡 献 供物,无论 是所许的愿 , 是甘心献的,就是 献 给耶和华 作燔祭的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, '要将没有残疾 的公 牛,或是绵羊,或是山羊献上,如此方蒙悦纳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, '凡 有残疾 的,你们不可 献上,因为 这 不 蒙悦纳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, '凡 从牛群 或是 羊群中,将平安 祭 献 给耶和华,为要还 特许的愿 ,或是 作甘心献的,所献的必 纯全 无 残疾的 才蒙悦纳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, '瞎眼的、 折伤的、 残废的、 有瘤子的、 长癣的、 长疥的 都 不可 献 给耶和华,也不可 在 坛上 作为 火祭 献给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, '无论是公牛 是绵羊羔,若肢体有余 馀的,或是缺少的,只可作甘心祭 献上;用以还愿 ,却不 蒙悦纳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, '肾子损伤的,或是压碎的,或是破裂的,或是骟了的,不可 献 给耶和华,在你们的地上 也不可 这样行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, '这类的物,你们从外 人 的手,一样 也 不可 接受作你们 神 的食物 献上;因为 这些 都有损坏,有残疾,不 蒙悦纳。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, '「才 生的 公牛,或是 绵羊 或是 山羊,七 天 当 跟著 母;从第八 天 以后,可以当供物 蒙悦纳,作为耶和华的 火祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, '无论是母牛 是 母羊,不可 同 日 宰 母和 子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, ' 你们献 感谢 祭 给耶和华,要献得 可蒙悦纳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, '要当 天 吃,一点 不可 留 到 早晨。我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, '「你们要谨守 遵行 我的诫命。我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, '你们不可 亵渎 我的圣 名;我在以色列 人 中,却要被尊为圣。我是 叫你们成圣的 耶和华, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, '把你们 从埃及 地 领出来,作 你们的 神。我是 耶和华。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, '「你晓谕 以色列 人 说:耶和华 的节期, 你们要宣告 为 圣 会 的节期。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, '六 日 要做 工,第七 日 是圣安息 日,当有圣 会;你们什么 工 都不可 做。这是 在你们一切的 住处 向耶和华 守的安息日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, '耶和华 的节期,就是 你们到了日期 要宣告 为圣 会的,乃是这些。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, '「正 月 十 四日,黄昏的时候,是耶和华的 逾越节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, '这 月 十 五 日 是向耶和华 守的无酵 节;你们要吃 无酵饼 七 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, '第一 日 当有 圣 会,什么 劳碌的 工 都不可 做; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, '要将火祭 献 给耶和华 七 日。第七 日 是圣 会,什么 劳碌的 工 都不可 做。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, '「你晓谕 以色列 人 说: 你们到了 我 赐 给你们 的 地,收割 庄稼的时候,要将 初熟的 庄稼 一捆 带 给 祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, '他要把 这一捆 在耶和华 面前 摇一摇,使你们得蒙悦纳。祭司 要在安息日 的次日 把这捆摇一摇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, '摇 这 捆 的日子,你们要把一 岁、没有残疾 的公绵羊羔 献 给耶和华 为燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, '同献的素祭,就是调 油 的细面 麺 伊法十分 之二,作为馨 香 的火祭,献给耶和华。同献的奠祭,要酒 一欣 四分之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, '无论是饼,是烘的子粒,是新穗子,你们都不可 吃,直等到把你们献给 神 的供物 带来 的那 一 天才可以吃。这在你们一切的 住处 作为世世代代 永远 的定例。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, '「你们 要从安息日 的次日,献 禾捆 为摇祭 的那日 算起,要 满了 七个 安息日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, '到 第七个 安息日 的次日,共计 五十 天,又要将新 素祭 献 给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, '要从你们的住处 取出 细面 麺 伊法十分 之二, 加酵,烤成 两个 摇祭 的饼,当作初熟之物 献给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, '又要将一 岁、没有残疾 的羊羔 七只、公 牛 犊 一只、公绵羊 两只,和饼 一同 奉上。这些与同献的素祭 和奠祭 要作为 燔祭 献给耶和华,就是作馨 香 的火祭 献给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, '你们要献 一只 公山羊 为赎罪祭,两只 一 岁 的公绵羊羔 为平安 祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, '祭司 要把这些 和 初熟 麦子做的饼 一同作摇祭,在耶和华 面前 摇一摇;这是 献与耶和华 为圣物 归给祭司的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, '当这 日,你们要宣告 圣 会;什么 劳碌的 工 都不可 做。这在你们一切的 住处 作为世世代代 永远的 定例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, '「在你们的地 收割 庄稼,不可 割尽 田 角,也不可 拾取 所 遗落的;要留 给穷人 和寄居的。我是 耶和华─你们的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, '「你晓谕 以色列 人 说:七 月 初一, 你们 要守为圣安息日,要吹 角作纪念,当有圣 会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, '什么 劳碌的 工 都不可 做;要将火祭 献 给耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, '「 七 月 初十 是 赎罪 日; 你们 要守为圣 会,并要刻苦 己心,也要将火祭 献 给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, '当这 日,什么 工 都不可 做;因为 是 赎罪 日,要在耶和华─你们的 神 面前 赎罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, '当这 日, 凡 不 刻苦 己心 的,必从民中 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, '凡 这 日 做 什么 工 的,我必将 他 从民 中 除灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, '你们什么 工 都不可 做。这在你们一切的 住处 作为世世代代 永远 的定例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, '你们 要守这 日为圣安息 日,并要刻苦 己心。从这月 初九 日晚上 到 次日晚上,要守为 安息日。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, '「你晓谕 以色列 人 说:这 七 月 十 五 日 是住棚 节,要在耶和华面前 守这节七 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, '第一 日 当有圣 会,什么 劳碌的 工 都不可 做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, '七 日 内要将火祭 献 给耶和华。第八 日 当 守圣 会,要将火祭 献 给耶和华。这是 严肃会,什么 劳碌的 工 都不可 做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, '「这是 耶和华 的节期,就是 你们要宣告 为 圣 会的节期;要将火祭、燔祭、素祭、祭物,并奠祭,各 归各日,献 给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, '这是在耶和华 的安息日 以外,又在你们的供物 和 所 许的愿 ,并 甘心 献 给耶和华 的以外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, '「你们收藏了 地 的出产,就 从七 月 十 五 日起,要守 耶和华 的节 七 日。第一 日 为圣安息;第八 日 也为圣安息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, '第一 日要 拿 美好 树 上的果子 和棕树 上的枝子,与茂密 树 的枝条 并河 旁的柳枝,在耶和华─你们的 神 面前 欢乐 七 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, '每年 七 月间,要向耶和华 守 这 节 七 日。这为你们世世代代 永远 的定例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, '你们要住 在棚里 七 日;凡 以色列家 的人 都要住 在棚里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, '好叫 你们世世代代 知道, 我领 以色列 人 出埃及 地 的时候曾使他们 住 在棚里。我是 耶和华─你们的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, '于 是,摩西 将 耶和华 的节期 传 给 以色列 人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, '「要吩咐 以色列 人,把那为点灯 捣成的 清 橄榄 油 拿来 给你,使灯 常常 点著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, '在会 幕 中法 柜的幔子 外,亚伦 从晚上 到 早晨 必在耶和华 面前 经理 这灯。这要作你们世世代代 永远 的定例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, '他要在耶和华 面前 常 收拾 精金 灯台 上的 灯。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, '「你要取 细面 麺,烤成 十 二 个饼,每 饼 用 面 麺伊法十分 之二。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, '要把饼 摆列 两 行(或译:摞;下同),每行 六个,在 耶和华 面前 精金 的桌子上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, '又要把净 乳香 放 在 每行 饼上,作 为纪念,就是作为火祭 献给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, '每安息日 要常 摆 在耶和华 面前;这为 以色列 人 作永远 的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, '这饼是要 给亚伦 和他子孙的;他们要在圣 处 吃,为永远的 定例,因为 在献给耶和华 的火祭中 是 至 圣的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, '有一个以色列 妇人 的儿子,他 父亲 是埃及人,一日闲 游 在以色列 人 中。这以色列 妇人的儿子 和一个以色列 人 在营里 争斗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, '这以色列 妇人 的儿子 亵渎了 圣名,并且咒诅,就有人把他 送 到 摩西那里。(他母亲 名 叫示罗密,是但 支派 底伯利 的女儿。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, '他们把那人收 在监里,要得 耶和华 所指示 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, '「把那 咒诅圣名的人 带 到 营 外。叫 听见的人 都放 手 在 他头上;全 会 众就要用石头打死 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, '你要晓谕 以色列 人 说:凡 咒诅 神的,必担当 他的罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, '那亵渎 耶和华 名的,必 被治死;全 会众 总要 用石头打死 他。不管是寄居的 是本地人,他亵渎 耶和华名的时候,必被治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, ' 打死 人的,必 被治死; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, '打死 牲畜的,必赔上牲畜,以命 偿 命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, '人 若 使 他邻舍 的身体有残疾,他怎样 行,也要照样 向他 行: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, '以伤 还 伤,以眼 还 眼,以牙 还 牙。他怎样 叫 人 的身体有残疾,也要照样 向他 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, '打死 牲畜的,必赔上牲畜;打死 人的,必被治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, '不管是 寄居的 是本地人,同归 一 例。 我是 耶和华─你们的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, '于 是,摩西 晓谕 以色列 人,他们就把 那咒诅圣名的人 带 到 营 外,用石头 打死。以色列 人 就照 耶和华 所吩咐 摩西 的行了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, '耶和华 在西奈 山 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, '「你晓谕 以色列 人 说: 你们到了 我 所 赐 你们 那地的时候,地 就要向耶和华 守 安息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, '六 年 要耕种 田地, 也要修理 葡萄园,收藏 地的出产。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, '第七 年,地 要 守圣安息,就是向耶和华 守的安息,不可 耕种 田地,也不可 修理 葡萄园。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, ' 遗落自长的 庄稼 不可 收割; 没有修理的 葡萄树 也不可 摘取葡萄。这年,地 要 守圣安息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, '地 在安息年所出的,要给你 和你的仆人、婢女、雇工 人,并 寄居的 外人 当 食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, '这年的土产 也要 给你的牲畜 和你地上 的 走兽 当食物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, '「你 要计算 七个 安息 年,就是七 七 年。这 便为你 成了 七个 安息 年,共是四十 九 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, '当年七 月 初十日,你要大发 角 声;这日就是赎罪 日,要在遍 地 发出 角声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, '第五十 年,你们要当作圣年,在遍地 给一切的 居民 宣告 自由。这年 必为 你们的 禧年,各人 要归 自己的产业,各 归 本家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, '第 五十 年 要作为 你们的 禧年。这 年不可 耕种; 地中自长的,不可 收割; 没有修理的葡萄树 也不可 摘取葡萄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, '因为 这是 禧年,你们 要当作 圣年,吃 地中自出的 土产。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, '「这 禧 年,你们各人 要归 自己的地业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, '你若 卖 什么 给邻舍,或是 从邻舍 的手中 买 什么,彼此 不可 亏负。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, '你要按禧年 以后 的年 数 向 邻舍 买 ;他也要按年 数 的收成 卖 给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, '年岁 若多,要照数 加添 价值;年岁 若少,要照数 减去 价值,因为 他 照收成 的数目 卖 给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, '你们彼此 不可 亏负,只要敬畏你们的 神,因为 我是 耶和华─你们的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, '「 我的律例,你们要遵行, 我的典章,你们要谨守,就可以在 那地上 安然 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, '地 必出 土产,你们就要吃 饱,在那地上 安然 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, '你们若 说:『 这第七 年 我们不 耕种,也不 收藏 土产,吃 什么呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, '我必在第六 年 将 我所命的 福 赐给你们,地便生 三 年 的土产。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, ' 第八 年,你们要耕种,也要吃 陈 粮,等到 第九 年 出产 收来 的时候,你们还吃 陈粮。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, '「地 不可 永 卖,因为 地 是我的; 你们 在我面前 是客旅,是寄居的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, '在你们所得为业 的全 地,也要准人 将地 赎回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, '你的弟兄(弟兄是指本国人说;下同)若 渐渐穷乏,卖了 几分地业,他至近的 亲属 就要来 把 弟兄 所卖的 赎回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, '若 没 有 能给他 赎回 的,他自己 渐渐富足,能 够 赎回, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, '就要算出 卖地的 年数,把 余 馀剩 年数的价值还 那 买  主,自己便归回 自己的地业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, '倘若 不 能 为自己 得 回 所卖的,仍要存 在买 主 的手里 直到 禧 年;到了禧年,地业要出买 主的手,自己便归回 自己的地业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, '「人 若 卖 城 内 的住 宅,卖了以后,一年 之内可以 赎回;在 一整 年,必有 赎回的权柄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, '若 在 一 整 年 之内不 赎回,这 城 内 的房屋 就定准 永 归买 主,世世代代为业;在禧年 也不 得出买 主的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, '但房屋 在无 城 墙 的 村庄里,要看如 乡下 的田地一样,可以 赎回;到了禧年,都要出买 主的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, '然而利未人 所得为业 的城邑,其中 的房屋,利未人 可以 随时 赎回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, '若是一个 利未人 不将所卖 的房屋 赎回,是在所得为业 的城内,到了禧年 就要出买 主的手,因为 利未人 城邑 的房屋 是 他们在以色列 人 中 的产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, '只是他们各城 郊野 之地 不可 卖,因为 是 他们 永远 的产业。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, '「你的弟兄 在你那里 若 渐渐贫穷,手中 缺乏,你就要帮补 他,使他与你 同住,像外人 和寄居的一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, '不可 向他 取 利,也不可向他多要;只要敬畏你的 神,使你的弟兄 与你 同住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, '你借 钱 给他,不可 向他取利;借 粮给他,也不可 向他多要。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, '我是 耶和华─你们的 神, 曾领 你们 从埃及 地出来,为要把 迦南 地 赐 给你们,要作 你们的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, '「你的弟兄 若 在你那里 渐渐穷乏,将自己卖 给你,不可 叫他 像奴仆 服事你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, '他要 在你那里 像雇工人 和寄居的一样,要服事 你 直到 禧 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, '到了禧年,他 和他儿女 要离开  你,一同 出去归 回 本家,到 他祖宗 的地业 那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, '因为 他们是 我的仆人,是 我从埃及 地 领出来 的,不可 卖 为 奴仆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, '不可 严严地 辖管 他,只要敬畏你的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, '至于  你的奴仆、婢女,可以 从 你四围 的 国中 买 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, '并且 那寄居 在你们中间 的外 人和 他们的家属,在你们地上 所 生的,你们也可以从其中 买 人;他们要作 你们的 产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, '你们要将他们 遗留 给你们的子孙 为 产业,要永远 从他们中间 拣出奴仆;只是你们的弟兄 以色列 人,你们不可 严严地 辖管。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, '「住在你那里 的外人,或是寄居的,若 渐渐富足,你的弟兄 却渐渐穷乏,将自己卖 给那外人,或是寄居的,或是 外人 的宗 族, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, '卖了 以后,可以 将他 赎回。无论 是他的弟兄, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, '或 伯叔、 伯叔 的儿子, 本家 的近 支,都可以赎他。 他自己 若渐渐富足,也可以自赎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, '他要和 买 主 计算,从卖 自己 的那年起,算到 禧 年;所卖的 价值 照著年 数多少,好像工人 每年的工价。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, '若 缺少的年 数多,就要按著 年数从买  价中 偿还 他的赎价。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, '若 到 禧 年 只缺少 几 年,就要按著 年数 和买 主 计算,偿还 他的赎价。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, '他和买 主同住,要像每年 雇的工人,买 主不可 严严地 辖管他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, '他若 不 这样 被赎,到了禧 年,要 和他的儿女 一同 出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, '因为 以色列 人 都是 我的 仆人,是 我从埃及 地 领出来 的。我是 耶和华─你们的 神。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, '「你们不可 做 什么虚无的神像,不可 立 雕刻的偶像 或是柱像,也不可 在你们的地上 安 什么錾成的 石像,向它 跪拜,因为 我是 耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, '你们要守 我的安息日,敬 我的圣所。我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, '「你们若 遵行 我的律例,谨守 我的诫命, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, '我就给 你们降下时 雨,叫地 生出 土产,田野 的树木 结 果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, '你们 打粮食 要打 到 摘葡萄的时候,摘葡萄 要摘 到 撒种的时候;并且要吃 得饱足,在你们的地上 安然 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, '我要赐 平安 在你们的地上;你们躺卧,无人 惊吓。我要叫恶 兽 从 你们的地上 息灭;刀剑 也必不 经过 你们的地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, '你们要追赶 仇敌,他们必倒 在你们 刀下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, '你们 五 个人要追赶 一百人, 一百 人要追赶 一万人;仇敌 必倒 在你们 刀下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, '我要眷顾 你们,使你们 生养 众多,也要与你们 坚定 所立的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, '你们要吃 陈 粮,又因 新粮 挪开  陈粮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, '我要在你们中间 立 我的帐幕;我的心 也不 厌恶 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, '我要在你们中间 行走;我要作 你们的 神,你们 要作 我的 子民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, '我是 耶和华─你们的 神, 曾将你们 从埃及 地 领出来,使你们 不作 埃及人的 奴仆;我也折断 你们所负 的轭,叫你们 挺身 而走。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, '「你们若 不 听从 我,不 遵行 我的诫命, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, ' 厌弃 我的律例, 厌恶 我的典章,不 遵行我一切的 诫命,背弃 我的约, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, ' 我 待 你们 就要这样:我必命定 惊惶,叫眼目 干瘪、精神 消耗的 痨病 热病 辖制你们。你们也要白白地 撒 种,因为仇敌 要吃你们所种的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, '我要向你们 变 脸,你们就要败 在仇敌 面前。恨恶你们的,必辖管 你们;无人 追赶,你们却要逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, '你们因这些事 若 还 不 听从 我,我就要为 你们的罪 加 七倍 惩罚 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, '我必断绝 你们因势力 而有的骄傲,又要使 覆 复你们的天 如铁, 载你们的地 如铜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, '你们要白白地 劳 力;因为你们的地 不 出 土产,其上 的树木 也不 结 果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, '「你们行事 若 与我 反对,不 肯 听从 我,我就要按你们的罪 加 七倍 降灾 与你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, '我也要打发 野地 的走兽 到你们中间,抢吃 你们的儿女,吞灭 你们的牲畜,使你们 的人数减少,道路 荒凉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, '「你们因这些事 若 仍不 改正 归我,行事 与我 反对, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, '我 就要 行事 与你们 反对,因 你们的罪 击打 你们 七次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, '我又要使 刀剑 临到你们,报复 你们背约 的仇;聚集你们 在 各城内,降 瘟疫 在你们中间,也必将你们交在 仇敌 的手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, '我要折断 你们的 杖,就是断绝你们的粮。那时,必有十个 女人 在一个 炉子 给你们烤 饼,按分量 秤给你们;你们要吃,也吃不 饱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, '「你们因这一切 的事若 不 听从 我,却行事 与我 反对, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, '我就要发烈怒,行事 与你们 反对, 又 因 你们的罪 惩罚 你们 七次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, '并且你们要吃 儿子 的肉,也要吃 女儿 的肉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, '我又要毁坏 你们的邱坛,砍下 你们的日像,把 你们的尸首 扔 在 你们偶像 的身上;我的心 也必厌恶 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, '我要使 你们的城邑 变为荒凉,使 你们的众圣所 成为荒场;我也不 闻 你们馨香 的香气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, '我 要使 地 成为荒场,住 在其上 的仇敌 就因此 诧异。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, '我要把你们 散 在列邦中;我也要拔 刀 追赶你们。你们的地 要成为 荒场;你们的城邑 要变为 荒凉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, '「你们 在仇敌 之地 居住的时候,你们的地 荒凉,要享受 众 安息;正在 那时候,地 要歇息,享受 安息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, '地多 时 为荒场,就要多时歇息; 地这样歇息,是你们住 在其上 的安息年 所不能 得的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, '至于 你们 剩下的人,我要使 他们 在仇敌 之地 心 惊胆怯。叶子 被风吹 的响声,要追赶他们;他们要逃避,像人逃避 刀剑,无人 追赶,却要跌倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, '无人 追赶,他们要彼此 撞跌,像在刀剑 之前。你们 在仇敌 面前 也必 站立 不住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, '你们要在列邦 中灭亡;仇敌 之地 要吞吃 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, '你们 剩下的人 必因自己的罪孽 和 祖宗 的罪孽 在仇敌 之地 消灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, '「他们要承认 自己的罪 和 他们祖宗 的罪,就是 干犯 我 的那罪,并且 承认自己行事 与我 反对, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, '我 所以 行事 与他们 反对,把他们 带 到仇敌 之地。那时,他们未受割礼 的心 若 谦卑了, 他们也服了 罪孽的刑罚, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, '我就要记念 我与雅各 所立的约, 与以撒 所立的约, 与亚伯拉罕 所立的约,并要记念 这地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, '他们 离开  这地,地在荒废 无人 的时候就要享受 安息。并且他们 要服 罪孽的刑罚;因为 他们厌弃了 我的典章,心中 厌恶了 我的律例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, '虽 是 这样,他们在 仇敌 之地,我却不 厌弃他们,也不 厌恶他们,将他们尽行灭绝,也不背弃 我与他们 所立的约,因为 我是 耶和华─他们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, '我却要为他们 的缘故记念 我与他们先祖 所立的约。 他们的先祖 是我在列邦人 眼前、从埃及 地 领出来的,为要作 他们的 神。我是 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, '这些 律例、典章,和法度 是 耶和华 与 以色列 人 在西奈 山 藉 借著 摩西 立的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, '「你晓谕 以色列 人 说: 人 还特许 的愿 ,被许的人 要按你所估的价值 归给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, ' 你估定的,从 二十 岁 到 六十 岁 的男人,要 按圣所 的平,估定价 银 五十 舍客勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, '若 是 女人,你要 估定 三十 舍客勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, '若 是从 五 岁 到 二十 岁,男子 你要 估定 二十 舍客勒,女子 估定十 舍客勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, '若 是从 一月 到 五 岁,男子 你要 估定 五 舍客勒,女子 估定 三 舍客勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, '若 是从 六十 岁 以上, 男人 你要 估定 十五 舍客勒,女人 估定十 舍客勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, '他 若 贫穷,不能照你所估定的价,就要把他带到 祭司 面前,祭司 要按 许愿  人 的力量 估定 他的价。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, '「所许的若 是牲畜,就是 人 献 给耶和华 为供物的,凡 这一类 献 给耶和华的,都要 成为圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, '人不可 改换,也不可 更换,或是好的 换坏的,或是 坏的 换好的。若 以 牲畜 更换 牲畜,所许的 与所换的 都要 成为圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, '若 牲畜 不洁净,是 不可 献 给耶和华 为供物的,就要把 牲畜 安置 在祭司 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, '祭司 就要估定价值;牲畜是 好 是 坏,祭司 怎样估定,就要以怎样 为是。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, '他若 一定要 赎回,就要在 你所估定的价值 以外加上 五分之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, '「 人 将 房屋 分别 为圣,归给耶和华,祭司 就要估定价值。房屋是 好 是 坏,祭司 怎样 估定,就要以怎样 为定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, '将 房屋分别为圣的人,若 要赎回 房屋,就必在 你所估定 的价值 以外加上 五分之一,房屋仍旧 归他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, '「人 若 将承受为业 的几分地 分别为圣,归给耶和华,你要 按 这地撒种 多少估定价值,若撒大麦 一贺梅珥,要估价 五十 舍客勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, '他若 从禧 年 将地 分别为圣,就要以你所估定的价 为定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, '倘若 他在禧年 以后 将地 分别为圣,祭司 就要按著 未到 禧 年 所剩 的年数 推算 价值,也要从你所估的 减去价值。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, '将地 分别为圣 的人若 定要 把 地 赎回,他便要在 你所估 的价值 以外加上 五分之一,地就准定 归他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, '他若 不 赎回 那地,或 是将 地 卖 给别 人,就再 不能 赎了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, '但到了禧年,那地 从买 主手下出来的时候,就要 归耶和华 为圣,和永献 的地一样,要 归祭司 为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, '他若 将 所买  的一块地, 不是 承受为业的,分别为圣 归给耶和华, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, '祭司 就要将 你所估 的价值 给他 推算 到 禧 年。当 日,他要以 你所估的价银 为圣,归 给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, '到了禧 年,那地 要归 卖主,就是那 承受 为业的原主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, '凡 你所估定的价银 都要 按著圣所 的平:二十 季拉 为 一舍客勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, '「惟独 牲畜中 头生的,无论是 牛 是 羊,既归耶和华,谁 也不可 再分别为圣,因为这是 耶和华的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, '若 是不洁净 的牲畜生的,就要按你所估定的价值 加 上 五分之一 赎回;若 不 赎回,就要按你所估定的价值 卖了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, '「但 一切 永献的,就是 人 从他所有 永献 给耶和华的,无论是人,是牲畜,是他承受为业 的地,都不可 卖,也不可 赎。凡 永献的 是 归给耶和华 为至 圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, '凡 从 人 中 当灭的 都不可 赎,必 被治死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, '「地上 所有的,无论是地上 的种子 是树上 的果子,十分之一 是 耶和华的,是归给耶和华 为圣的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, '人 若 要 赎 这十分之一的什么物,就要加 上 五分之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, '凡 牛群 羊群中,一切 从杖 下 经过的,每第十只 要 归给耶和华 为圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, '不可 问 是 好 是坏,也不可 更换;若 定要 更换, 所更换的 与本来的牲畜 都要 成为圣,不可 赎回。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, '这就是 耶和华 在西奈 山 为 以色列 人 所 吩咐 摩西 的命令。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, '以色列人出 埃及 地后,第二 年 二 月 初一日,耶和华 在西奈 的旷野、会 幕中 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, '「你要按以色列 全 会众 的家室、宗族、人名 的数目 计算 所有的 男丁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, '凡 以色列中,从 二十 岁 以外,能出去 打仗的,你 和亚伦 要照他们的军队 数点。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, '每 支派中 必有 一人 作本 支派的 族 长, 帮助你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, ' 他们 的名字:属流便的,有示丢珥 的儿子 以利蓿; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, '属西缅的,有苏利沙代 的儿子 示路蔑; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, '属犹大的,有亚米拿达 的儿子 拿顺; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, '属以萨迦的,有苏押 的儿子 拿坦业; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, '属西布伦的,有希伦 的儿子 以利押; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, '约瑟 子孙、属以法莲的,有亚米忽 的儿子 以利沙玛;属玛拿西的,有比大蓿 的儿子 迦玛列; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, '属便雅悯的,有基多尼 的儿子 亚比但; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, '属但的,有亚米沙代 的儿子 亚希以谢; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, '属亚设的,有俄兰 的儿子 帕结; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, '属迦得的,有丢珥 的儿子 以利雅萨; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, '属拿弗他利的,有以南 的儿子 亚希拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, '这 都是从会 中选召的,各作本 支派 的首领,都是 以色列 军中 的统领。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, '于 是,摩西、亚伦 带著 这些 按名 指定 的人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, '当二 月 初一 日招聚 全 会众。会众就照 他们的家室、宗 族、人名 的数目,从 二十 岁 以外的,都述说自己的家谱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, '耶和华 怎样 吩咐 摩西,他就怎样在西奈 的旷野 数点他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, ' 以色列 的长子,流便 子孙 的后代,照著家室、宗 族、人名 的数目, 从 二十 岁 以外,凡 能出去 打仗、被数 的男丁, 共有四万六千 五 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, '西缅 子孙 的后代,照著家室、宗 族、 人名 的数目,从 二十 岁 以外,凡 能出去 打仗、被数的 男丁, 共有五万九千 三 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, '迦得 子孙 的后代,照著家室、宗 族、人名 的数目,从 二十 岁 以外,凡 能出去 打仗、被数的, 共有四万五千 六 百 五十名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, '犹大 子孙 的后代,照著家室、宗 族、人名 的数目,从 二十 岁 以外,凡 能出去 打仗、被数的, 共有七万四千 六 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, '以萨迦 子孙 的后代,照著家室、宗 族、人名 的数目,从 二十 岁 以外,凡 能出去 打仗、被数的, 共有五万四千 四 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, '西布伦 子孙 的后代,照著家室、宗 族、人名 的数目,从 二十 岁 以外,凡 能出去 打仗、被数的, 共有五万七千 四 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, '约瑟 子孙 属以法莲 子孙 的后代,照著家室、宗 族、人名 的数目,从 二十 岁 以外,凡 能出去 打仗、被数的, 共有四万 零五 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, '玛拿西 子孙 的后代,照著家室、宗 族、人名 的数目,从 二十 岁 以外,凡 能出去 打仗、被数的, 共有三万二千 二百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, '便雅悯 子孙 的后代,照著家室、宗 族、人名 的数目,从 二十 岁 以外,凡 能出去 打仗、被数的, 共有三万五千 四 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, '但 子孙 的后代,照著家室、宗 族、人名 的数目,从 二十 岁 以外,凡 能出去 打仗、被数的, 共有六万二千 七 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, '亚设 子孙 的后代,照著家室、宗 族、人名 的数目,从 二十 岁 以外,凡 能出去 打仗、被数的, 共有四万一千 五 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, '拿弗他利 子孙 的后代,照著家室、宗 族、人名 的数目,从 二十 岁 以外,凡 能出去 打仗、被数的, 共有五万三千 四 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, '这些 就是被数点的,是 摩西、亚伦,和以色列中 十二个首领 所数点的;这十 二 个人 各 作 各宗 族的代表。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, '这样,凡 以色列 人中 被数的,照著宗 族,从 二十 岁 以外, 能出去 打仗、被数的,共有 六十万 零三 千 五 百 五十名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, '利未人 却没有 按著支派 数 在其中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, '因为耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, '「惟独 利未 支派 你不可 数点,也 不可 在以色列 人 中 计算 他们的总数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, ' 只要派 利未人 管 法柜 的帐幕 和其中的 器具,并 属乎 帐幕的;他们 要抬(或译:搬运)帐幕 和其中的 器具,并 要办理帐幕的事,在帐幕 的四围 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, '帐幕 将往前行的时候,利未人 要拆卸; 将支搭的时候,利未人 要竖起。近前来 的外人 必被治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, '以色列 人 支搭帐棚,要照他们的军队,各 归 本营,各 归 本纛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, '但利未人 要在法柜 帐幕 的四围 安营,免得 忿怒 临 到 以色列 会众;利未人 并要谨守 法柜 的帐幕。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, '以色列 人 就这样行。凡 耶和华 所 吩咐 摩西的,他们就照样 行了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, '耶和华 晓谕 摩西、 亚伦 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, '「以色列 人 要 各 归 自己的纛下,在本 族 的旗号那里,对著 会 幕 的四围 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, '在东边,向日出之地,照著军队 安营 的是犹大 营 的纛。有亚米拿达 的儿子 拿顺 作犹大 人的 首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, '他军队 被数的,共有七万四千 六 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, '挨著他 安营的 是以萨迦 支派。有苏押 的儿子 拿坦业 作以萨迦 人的 首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, '他军队 被数的,共有五万四千 四 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, '又有西布伦 支派。希伦 的儿子 以利押 作西布伦 人的 首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, '他军队 被数的,共有五万七千 四 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, '凡 属犹大 营、按著军队 被数的,共有十八万六千 四 百名,要作第一队 往前行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, '「在南边,按著军队 是流便 营 的纛。有示丢珥 的儿子 以利蓿 作流便 人的 首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, '他军队 被数的,共有四万六千 五 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, '挨著他 安营的 是西缅 支派。苏利沙代 的儿子 示路蔑 作西缅 人的 首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, '他军队 被数的,共有五万九千 三 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, '又有迦得 支派。丢珥 的儿子 以利雅萨 作迦得 人的 首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, '他军队 被数的,共有四万五千 六 百 五十名, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, '凡 属流便 营、按著军队 被数的,共有十五万一千 四 百 五十名,要作第二队 往前行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, '「随后,会 幕 要往前行,有利未 营 在诸营 中间。他们怎样 安营 就怎样 往前行,各 按 本位,各归本纛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, '「在西边,按著军队 是以法莲 营 的纛。亚米忽 的儿子 以利沙玛 作以法莲 人的 首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, '他军队 被数的,共有四万 零五 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, '挨著他 的是玛拿西 支派。比大蓿 的儿子 迦玛列 作玛拿西 人的 首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, '他军队 被数的,共有三万二千 二百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, '又有便雅悯 支派。基多尼 的儿子 亚比但 作便雅悯 人的 首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, '他军队 被数的,共有三万五千 四 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, '凡 属以法莲 营、按著军队 被数的,共有十万 零八 千 一百名,要作第三 队往前行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, '「在北边,按著军队 是但 营 的纛。亚米沙代 的儿子 亚希以谢 作但 人的 首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, '他军队 被数的,共有六万二千 七 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, '挨著他 安营 的是亚设 支派。俄兰 的儿子 帕结 作亚设 人的 首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, '他军队 被数的,共有四万一千 五 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, '又有拿弗他利 支派。以南 的儿子 亚希拉 作拿弗他利 人的 首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, '他军队 被数的,共有五万三千 四 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, '凡 但 营 被数的,共有十五万七千 六 百名,要归本纛 作末 队往前行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, '这些 以色列 人,照他们的宗 族,按他们的军队,在诸营中 被数的,共有六十万 零三 千 五 百 五十名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, '惟独利未人 没有 数 在以色列 人 中,是照 耶和华 所吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, '以色列 人 就这样 行,各人 照他们的家室、 宗 族 归于 本纛,安营 起行,都是照 耶和华 所 吩咐 摩西的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, '耶和华 在西奈 山 晓谕 摩西 的日子,亚伦 和摩西 的后代 如下: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, ' 亚伦 的儿子,长子 名 叫拿答,还有亚比户、以利亚撒、以他玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, '这是 亚伦 儿子 的名字,都是受膏 的祭司, 是摩西叫他们 承接圣职 供祭司职分的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, '拿答、亚比户 在西奈 的旷野 向 耶和华 献 凡 火 的时候就死 在耶和华 面前了。他们 也没 有 儿子。以利亚撒、以他玛 在 他们的父亲 亚伦 面前 供祭司的职分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, '「你使 利未 支派 近前来, 站 在祭司 亚伦 面前 好服事 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, '替 他和 会众 在会 幕 前 守 所吩咐的,办理 帐幕 的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, '又要看守 会 幕的 器具,并 守所吩咐 以色列 人的,办理 帐幕 的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, '你要将 利未人 给 亚伦 和他的儿子,因为他们是 从 以色列 人 中选出来给 他的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, '你要嘱咐 亚伦 和 他的儿子 谨守 自己祭司的职任。近前来 的外人 必被治死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, '「 我 从以色列 人 中 拣选了 利未人,代替 以色列 人 一切 头生的;利未人 要 归我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, '因为 凡 头生的 是我的;我在埃及 地 击杀 一切 头生的 那日 就把以色列中 一切 头生的,连人 带 牲畜 都分别为圣 归我;他们定要 属我。我是 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, '耶和华 在西奈 的旷野 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, '「你要照利未 人 的宗 族、家室 数点 他们。凡 一个月 以外 的男子 都要数点。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, '于 是摩西 照 耶和华 所 吩咐 的数点 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, '利未 众子 的名字 是 革顺、哥辖、米拉利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, '革顺 的儿子,按著家室,是立尼、示每。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, '哥辖 的儿子,按著家室,是暗兰、以斯哈、希伯伦、乌薛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, '米拉利 的儿子,按著家室,是抹利、母示。这些 按著宗 族 是 利未人 的家室。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, '属革顺的,有立尼 族、示每 族。这 是 革顺 的二族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, '其中被数、从 一个月 以外 所有的 男子 共有七 千 五 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, '这革顺 的二族 要在帐幕 后 西边 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, '拉伊勒 的儿子 以利雅萨 作革顺人 宗 族 的首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, '革顺 的子孙 在会 幕 中所要看守的,就是帐幕 和罩棚,并罩棚的盖 与会 幕 的门 帘, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, ' 院子 的帷子 和 门 帘(院子 是围 帐幕 和 坛的),并 一切 使用 的绳子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, '属哥辖的,有暗兰 族、以斯哈 族、希伯伦 族、乌薛 族。这 是 哥辖 的诸族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, '按所有 男子 的数目,从 一个月 以外 看守 圣所的,共有八 千 六 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, '哥辖 儿子 的诸族 要在 帐幕 的南 边 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, '乌薛 的儿子 以利撒反 作哥辖 宗 族 家室 的首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, '他们所要看守 的是约柜、桌子、灯台、两座坛 与圣所 内使用 的 器皿,并帘子 和一切 使用之物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, '祭司 亚伦 的儿子 以利亚撒 作利未人 众首领 的领袖,要监察 那些看守 圣所的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, '属米拉利的,有抹利 族、母示 族。这 是 米拉利 的二族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, '他们被数的,按所有 男子 的数目,从 一个月 以外的,共有六 千 二百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, '亚比亥 的儿子 苏列 作米拉利 二宗 族 的首领。他们要在 帐幕 的北 边 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, '米拉利 子孙 的职分 是看守 帐幕 的板、闩、柱子、带卯的座,和帐幕一切 所使用的 器具, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, '院子 四围 的柱子、带卯的座、橛子,和绳子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, '在帐幕 前 东边, 向日出之地 安营 的是摩西、亚伦,和亚伦的儿子。他们看守 圣所,替以色列 人 守耶和华所吩咐的。近前来 的外人 必被治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, '凡 被数 的利未人,就是 摩西、亚伦 照 耶和华 吩咐 所数的,按著家室,从 一个月 以外的 男子,共有二万二千名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, '耶和华 对 摩西 说:「你要从以色列 人 中数点 一个月 以外、凡 头生 的男子,把 他们的名字 记下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, '我是 耶和华。你要拣选 利未人 归我,代替 以色列 人 所有 头生的,也取 利未人 的牲畜 代替 以色列 所有 头生 的牲畜。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, '摩西 就照 耶和华 所吩咐的 把 以色列 人 头生 的都 数点了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, ' 按人名 的数目,从 一个月 以外、凡 头生 的男子, 共有二万二千 二百 七十 三名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, '「你拣选 利未人 代替 以色列 人 所有 头生的,也取 利未人 的牲畜 代替 以色列人的牲畜。利未人 要 归我;我是 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, '以色列 人 中头生 的男子比 利未人 多 二百 七十 三个,必当将 他们赎出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, '你要 按人丁,照圣所 的平,每人 取 赎银五 舍客勒(一舍客勒 是二十 季拉), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, '把那多余 馀之人 的赎 银 交 给亚伦 和他的儿子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, '于 是摩西 从 那被利未人 所 赎 以外 的人取了 赎 银。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, '从 以色列 人 头生 的所取 之 银,按圣所 的平,有一千 三 百 六十 五舍客勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, '摩西 照耶和华 的话 把 这赎 银 给 亚伦 和他的儿子,正如 耶和华 所 吩咐的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, '耶和华 晓谕 摩西、 亚伦 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, '「你从利未 人 中,将 哥辖 子孙 的总数,照他们的家室、宗 族, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, '从 三十 岁 直到 五十 岁,凡 前来 任职、在会 幕 里办 事的,全都计算。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, '哥辖 子孙 在会 幕 搬运至圣 之物,所办的事 乃是这样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, '起 营的时候,亚伦 和他儿子 要进去 摘下 遮掩 柜 的幔子,用以蒙盖 法 柜, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, '又用海狗 皮 盖 在上头,再蒙 上 纯 蓝色 的毯子,把杠 穿上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, '又用蓝色 毯子 铺 在 陈设饼 的桌子上,将 盘子、 调羹、 奠酒 的爵,和 杯 摆 在上头。桌子上 也必有 常设 的饼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, '在其上 又要蒙 朱红色 的毯子,再蒙上 海狗 皮,把 杠 穿上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, '要拿 蓝色 毯子,把 灯 台 和 灯台 上所 用 的灯盏、 剪子、 蜡花盘,并 一切 盛油 的器皿,全都遮盖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, '又要 把 灯台和灯台的一切 器具 包 在 海狗 皮里,放 在 抬架上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, '在 金 坛 上要铺 蓝色 毯子,蒙上 海狗 皮,把 杠 穿上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, '又要 把 圣所 用 的一切 器具 包 在 蓝色 毯子里,用 海狗 皮 蒙上,放 在 抬架上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, '要收去 坛上的灰,把紫色 毯子 铺 在坛上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, '又要把 所 用 的一切 器具,就是 火鼎、 肉锸子、 铲子、 盘子,一切 属坛 的器具 都摆 在坛上,又蒙 上 海狗 皮,把杠 穿上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, '将要起 营的时候,亚伦 和他儿子 把 圣所 和 圣所 的一切 器具 遮盖 完了, 哥辖 的子孙 就要来 抬,只是不可 摸 圣物,免得他们死亡。会 幕 里这些 物件是哥辖 子孙 所当抬的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, '「祭司 亚伦 的儿子 以利亚撒 所要看守 的是点灯 的油 与香 料,并当献的 素祭 和膏油,也要看守 全 帐幕 与其 中 所有的,并圣所 和圣所的器具。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, '耶和华 晓谕 摩西、 亚伦 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, '「你们不可 将 哥辖 人 的支派 从利未人 中 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, '他们挨近 至圣 物的时候,亚伦 和他儿子 要进去 派 他们 各 人 所当 办的,所当 抬的。这样 待 他们,好使他们活著,不致 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, '只是他们连片时 不可 进去 观看 圣所,免得他们死亡。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, '「你要 将 革顺 子孙 的总数, 照著宗 族、家室, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, '从 三十 岁 直到 五十 岁,凡 前来 任 职、在会 幕 里办 事的,全都数点。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, '革顺人 各族 所办 的事、所抬的 物乃是这样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, '他们要抬 帐幕 的幔子 和 会 幕,并会幕的盖 与其 上 的 海狗皮,和 会 幕 的门 帘, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, ' 院子 的帷子 和 门 帘(院子 是 围 帐幕 和 坛的)、 绳子,并 所用的 器具, 不论 是 做 什么用的,他们都要经理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, '革顺 的子孙 在一切 抬物 办事 之上都 要 凭 亚伦 和他儿子 的吩咐;他们所当 抬的,要派 他们 看守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, '这是 革顺 子孙 的各族 在会 幕 里所办的事;他们所看守的,必在祭司 亚伦 儿子 以他玛 的手下。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, '「至于 米拉利 的子孙,你要照著家室、宗 族 把他们 数点。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, '从 三十 岁 直到 五十 岁,凡 前来 任职、在会 幕 里办 事的,你都要数点。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, '他们办理 会 幕的 事,就是 抬帐幕 的板、闩、柱子,和带卯的座, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, '院子 四围 的柱子 和其上带卯的座、橛子、绳子,并一切 使用的 器具。他们所抬 的器具,你们要按名 指定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, '这是 米拉利 子孙 各族 在会 幕 里所办的 事,都在祭司 亚伦 儿子 以他玛 的手下。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, '摩西、亚伦 与会众 的诸首领 将 哥辖 的子孙,照著家室、宗 族, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, '从 三十 岁 直到 五十 岁,凡 前来 任职、在会 幕 里办事的,都数点了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, '被数的 共有 二千 七 百 五十名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, '这是 哥辖 各族 中被数的,是在会 幕里 办事的,就是 摩西、亚伦 照 耶和华 藉 借 摩西 所吩咐 数点的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, '革顺 子孙 被数的,照著家室、宗 族, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, '从 三十 岁 直到 五十 岁,凡 前来 任职、在会 幕 里办事的, 共有 二千 六 百 三十名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, '这是 革顺 子孙 各族 中被数的,是在会 幕里 办事的,就是 摩西、亚伦 照 耶和华 藉 借摩西所吩咐 数点的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, '米拉利 子孙 中各族 被数的,照著家室、宗 族, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, '从 三十 岁 直到 五十 岁,凡 前来 任职、在会 幕 里办事的, 共有 三 千 二百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, '这是 米拉利 子孙 各族 中被数的,就是 摩西、亚伦 照 耶和华 藉 借 摩西 所吩咐 数点的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, '凡 被数的 利未人,就是 摩西、亚伦 并以色列 众首领,照著家室、宗 族 所数点的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, '从 三十 岁 直到 五十 岁,凡 前来 任 职、在会 幕 里做抬物 之工的, 共有 八 千 五 百 八十名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, '摩西 按 他们 所办的事、 所抬的物,凭 耶和华 的吩咐 数点 他们;他们这样被 摩西 数点,正如耶和华 所 吩咐 他的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, '「你吩咐 以色列 人,使一切 长大痲疯的, 患漏症的,并 因死尸 不洁净的,都出 营外去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, '无论男 女 都要使他们出 到 营 外,免得 污秽 他们的营;这营 是我 所 住的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, '以色列 人 就这样 行,使他们 出 到 营 外。耶和华 怎样 吩咐 摩西,以色列 人 就怎样 行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, '「你晓谕 以色列 人说:无论男 女,若 犯 了人 所常 犯的罪,以致干 犯 耶和华,那 人 就有了罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, '他要承认 所 犯 的罪,将 所亏负人的,如数 赔还,另外加 上 五分之一,也归 与所 亏负的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, '那人 若 没有 亲属 可受 所赔还的,那所赔还的 就要归 与服事耶和华 的祭司;至于 那 为他 赎罪的 公羊 是在外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, '以色列 人 一切的 圣物中,所 奉 给祭司 的举祭 都 要归 与祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, '各人 所 分别为圣的物,无论是 什么,都要归 给祭司。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, '「你晓谕 以色列 人 说:人 的妻 若 有邪行,得 罪 她丈夫, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, '有人 与她 行淫,事情严密,瞒过 她丈夫,而且她 被玷污,没有 作见证的人,当她 行淫的时候也没有 被捉住, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, '她丈夫 生了 疑恨 的心,疑恨 她,她是 被玷污,或是 她丈夫 生了 疑恨 的心,疑恨 她,她 并没有 被玷污, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, '这人 就要将 妻 送 到 祭司那里,又为她 带著 大麦 面 麺 伊法 十分之一 作 供物,不可 浇 上 油,也不可 加 上 乳香;因为 这是 疑恨 的素祭,是思念 的素祭,使人思念 罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, '「祭司 要使那妇人 近前来,站 在耶和华 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, '祭司 要把圣 水 盛 在瓦 器里, 又从帐幕的 地上 取 点 尘土,放 在 水中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, '祭司 要叫 那妇人 蓬 头 散发,站 在耶和华 面前,把 思念 的素祭,就是 疑恨 的素祭,放 在 她手中。祭司 手 里拿著 致咒诅 的苦 水, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, ' 要叫妇人 起誓,对 她 说:『若 没有 人 与你 行淫,也 未曾 背 著 丈夫 做污秽的事,你就免受 这 致咒诅 苦 水的灾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, '你 若 背 著 丈夫 行了污秽的事,在你丈夫 以外 有人 与你 行 淫, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, '(祭司叫 妇人 发咒 起誓), 愿 耶和华 叫你 大腿 消瘦, 肚腹 发胀, 使 你 在你民 中 被人咒诅,成了誓语; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, '并且这 致咒诅 的水 入 你的肠中,要叫你的肚腹 发胀,大腿 消瘦。』妇人 要回答说:『阿们,阿们。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, '「祭司 要写 这 咒诅 的话,将所写的字抹 在 苦 水里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, '又叫 妇人 喝 这致咒诅 的苦 水;这水 要进入 她里面 变苦了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, '祭司 要从妇人 的手 中取 那疑恨 的素祭,在耶和华 面前 摇一摇,拿 到 坛前; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, ' 又要从素祭 中取出一把,作为 这事的纪念,烧 在坛上,然后 叫 妇人 喝 这水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, '叫她喝了以后, 她若 被玷污,得罪 了丈夫,这致咒诅 的水 必进入 她里面 变苦了,她的肚腹 就要发胀,大腿 就要消瘦,那妇人 便要 在他民 中 被人咒诅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, '若 妇人 没有 被玷污,却是 清洁的,就要免受这灾,且要怀孕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, '「妻子 背 著 丈夫 行了污秽的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, '或是 人 生了 疑恨 的心,疑恨 他的妻,就有这 疑恨 的条例。那时他要叫 妇人 站 在耶和华 面前,祭司 要在她身上 照 这 条例 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, '男人 就为无 罪, 妇人 必担当 自己的罪孽。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, '「你晓谕 以色列 人 说:无论男 女 许了 特别的愿 ,就是拿细耳人 的愿 (拿细耳就是归主的意思;下同),要离俗 归耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, '他就要远离 清酒 浓酒,也不可 喝 什么清酒 浓酒 做的醋;不可 喝 什么 葡萄 汁,也不可 吃 鲜 葡萄 和干葡萄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, '在一切 离俗 的日子,凡 葡萄 树 上结的,自核 至 皮所做的物,都 不可 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, '「在他一切 许愿  离俗 的日子,不可 用剃头刀 剃 头, 要由发 绺 长长了。他要 圣洁,直到 离俗 归耶和华 的日子 满了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, '在他离俗 归耶和华 的一切 日子,不可 挨 近 死 尸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, '他的父 母 或是弟兄 姊妹 死了的时候,他不可 因他们 使自己不洁净,因为 那离俗归 神 的凭据是在 他头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, '在他一切 离俗 的日子 是 归耶和华 为圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, '「若 在他旁边 忽然 有人 死了,以致沾染 了他离俗 的头,他要在第七 日,得洁净 的时候,剃 头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, '第八 日,他要把两 只斑鸠 或 两 只雏 鸽 带 到 会 幕 门口,交给 祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, '祭司 要献 一 只作赎罪祭,一 只作燔祭,为他 赎 那 因 死尸 而有的罪,并要当 日 使 他的头 成为圣洁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, '他要另选 离俗 归耶和华 的日子,又要牵 一只一 岁 的公羊羔 来作赎愆祭;但先前 的日子 要归徒然,因为 他在离俗 之间被玷污了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, '「拿细耳人 满 了离俗 的日子 乃有这 条例:人要领 他 到 会 幕 门口, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, '他要将 供物 奉 给耶和华,就是一 只没有残疾、一 岁 的公羊羔 作燔祭,一 只没有残疾、一 岁 的母羊羔 作赎罪祭,和一 只没有残疾 的公绵羊 作平安祭, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, '并一筐子 无酵 调 油 的细 面 麺饼,与抹 油 的无酵 薄饼,并同献的素祭 和奠祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, '祭司 要 在耶和华 面前 献 那人的赎罪祭 和 燔祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, '也要把 那只公羊 和 那筐 无酵饼 献 给耶和华 作平安祭, 又要将 同献的素祭 和 奠祭 献上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, '拿细耳人 要在会 幕 门口 剃 离俗 的头, 把 离俗 头 上的发 放 在 平安 祭 下 的 火上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, '他剃了 以后,祭司 就要取 那已煮的公羊 一条前腿,又从 筐子 里取一 个无酵 饼 和一 个无酵 薄饼,都放 在 他 手上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, '祭司 要拿这些 作为摇祭,在耶和华 面前 摇一摇;这与 所摇 的胸、 所举 的腿 同为 圣物,归给祭司。然后 拿细耳人 可以喝 酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, '「许愿  的 拿细耳人 为 离俗 所献的供物,和他 以外 所 能得 的献给耶和华,就有这 条例。他怎样 许 愿  就当照 离俗 的条例 行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, '「你告诉 亚伦 和 他儿子 说:你们要这样 为 以色列 人 祝福,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, '『愿 耶和华 赐福给你,保护你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, '愿 耶和华 使他的脸 光 照你,赐恩给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, '愿 耶和华 向你 仰 脸,赐 你 平安。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, '他们要如此奉 我的名 为 以色列 人祝福;我 也要赐福给他们。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, ' 摩西 立 完了 帐幕,就把帐幕 用膏抹了,使它 成圣,又把其中的 器具 和 坛,并坛上的 器具,都抹了,使它 成圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, '当天,以色列 的众首领,就是各族 的族长,都来奉献。他们是 各支派 的首领, 管理 那些被数的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, '他们把 自己的供物 送 到耶和华 面前,就是六 辆篷子 车 和十 二 只公牛。 每两 个首领 奉献一辆车,每 首领奉献一只牛。他们把这些 都奉 到帐幕 前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, '「你要收下 这些,好 作 会 幕 的使用,都要照 利未 人 所办的事 交 给 他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, '于 是摩西 收了 车 和 牛,交 给 利未人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, '把 两 辆车, 四 只牛,照 革顺 子孙 所办的事 交给他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, '又把 四 辆车, 八 只牛,照 米拉利 子孙 所办的事 交给他们;他们都在祭司 亚伦 的儿子 以他玛 手下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, '但车与牛都没有 交 给哥辖 子孙;因为 他们 办的是圣所 的事,在肩头 上抬圣物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, '用膏抹 坛 的日子,首领 都来行 奉献坛 的礼,众首领 就在坛 前 献 供物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, '耶和华 对 摩西 说:「众首领为行奉献坛 的礼,要每天 一 个首领 来献 供物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, '头一 日 献 供物 的是 犹大 支派的 亚米拿达 的儿子 拿顺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, '他的供物是:一 个银 盘子,重 一百 三十舍客勒,一 个银 碗,重七十 舍客勒,都是按圣所 的平, 也都盛满 了调 油 的细面 麺 作素祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, '一 个金 盂,重十舍客勒,盛满 了香; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, '一 只公 牛 犊,一 只公绵羊,一 只一 岁 的公羊羔 作燔祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, '一 只公 山羊 作赎罪祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, '两 只公牛,五 只公绵羊,五 只公山羊,五 只一 岁 的公羊羔 作平安 祭。这是 亚米拿达 儿子 拿顺 的供物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, '第二 日 来献 的是以萨迦 子孙的首领、苏押 的儿子 拿坦业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, '他献 为 供物的是:一 个银 盘子,重 一百 三十舍客勒,一 个银 碗,重七十 舍客勒,都是按圣所 的平, 也都盛满 了调 油 的细面 麺 作素祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, '一 个金 盂,重十舍客勒,盛满 了香; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, '一 只公 牛 犊,一 只公绵羊,一 只一 岁 的公羊羔 作燔祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, '一 只公 山羊 作赎罪祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, '两 只公牛,五 只公绵羊,五 只公山羊,五 只一 岁 的公羊羔 作平安 祭。这是 苏押 儿子 拿坦业 的供物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, '第三 日 来献的是西布伦 子孙的 首领、希伦 的儿子 以利押。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, '他的供物是:一 个银 盘子,重 一百 三十舍客勒,一 个银 碗,重七十 舍客勒,都是按圣所 的平, 也都盛满 了调 油 的细面 麺 作素祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, '一 个金 盂,重十舍客勒,盛满 了香; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, '一 只公 牛 犊,一 只公绵羊,一 只一 岁 的公羊羔 作燔祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, '一 只公 山羊 作赎罪祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, '两 只公牛,五 只公绵羊,五 只公山羊,五 只一 岁 的公羊羔 作平安 祭。这是 希伦 儿子 以利押 的供物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, '第四 日 来献的是流便 子孙的 首领、示丢珥 的儿子 以利蓿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, '他的供物是:一 个银 盘子,重 一百 三十舍客勒,一 个银 碗,重七十 舍客勒,都是按圣所 的平, 也都盛满 了调 油 的细面 麺 作素祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, '一 个金 盂,重十舍客勒,盛满 了香; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, '一 只公 牛 犊,一 只公绵羊,一 只一 岁 的公羊羔 作燔祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, '一 只公 山羊 作赎罪祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, '两 只公牛,五 只公绵羊,五 只公山羊,五 只一 岁 的公羊羔 作平安 祭。这是 示丢珥 的儿子 以利蓿 的供物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, '第五 日 来献的是西缅 子孙的 首领、苏利沙代 的儿子 示路蔑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, '他的供物是:一 个银 盘子,重 一百 三十舍客勒,一 个银 碗,重七十 舍客勒,都是按圣所 的平, 也都盛满 了调 油 的细面 麺 作素祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 38, '一 个金 盂,重十舍客勒,盛满 了香; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 39, '一 只公 牛 犊,一 只公绵羊,一 只一 岁 的公羊羔 作燔祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 40, '一 只公 山羊 作赎罪祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, '两 只公牛,五 只公绵羊,五 只公山羊,五 只一 岁 的公羊羔 作平安 祭。这是 苏利沙代 儿子 示路蔑 的供物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, '第六 日 来献的是迦得 子孙的 首领、丢珥 的儿子 以利雅萨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, '他的供物是:一个 银 盘子,重 一百 三十舍客勒,一个 银 碗,重七十 舍客勒,都是按圣所 的平, 也都盛满 了调 油 的细面 麺 作素祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 44, '一 个金 盂,重十舍客勒,盛满 了香; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 45, '一 只公 牛 犊,一 只公绵羊,一 只一 岁 的公羊羔 作燔祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 46, '一 只公山羊 作赎罪祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 47, '两 只公牛,五 只公绵羊,五 只公山羊,五 只一 岁 的公羊羔 作平安 祭。这是 丢珥 的儿子 以利雅萨 的供物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, '第七 日 来献的是以法莲 子孙的 首领、亚米忽 的儿子 以利沙玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, '他的供物是:一 个银 盘子,重 一百 三十舍客勒,一 个银 碗,重七十 舍客勒,都是按圣所 的平, 也都盛满 了调 油 的细面 麺 作素祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 50, '一 个金 盂,重十舍客勒,盛满 了香; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 51, '一 只公 牛 犊,一 只公绵羊,一 只一 岁 的公羊羔 作燔祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 52, '一 只公山羊 作赎罪祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 53, '两 只公牛,五 只公绵羊,五 只公山羊,五 只一 岁 的公羊羔 作平安 祭。这是 亚米忽 儿子 以利沙玛 的供物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, '第八 日 来献的是玛拿西 子孙的 首领、比大蓿 的儿子 迦玛列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, '他的供物是:一 个银 盘子,重 一百 三十舍客勒,一 个银 碗,重七十 舍客勒,都是按圣所 的平, 也都盛满 了调 油 的细面 麺 作素祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 56, '一 个金 盂,重十舍客勒,盛满 了香; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, '一 只公 牛 犊,一 只公绵羊,一 只一 岁 的公羊羔 作燔祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 58, '一 只公 山羊 作赎罪祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, '两 只公牛,五 只公绵羊,五 只公山羊,五 只一 岁 的公羊羔 作平安 祭。这是 比大蓿 儿子 迦玛列 的供物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, '第九 日 来献的是便雅悯 子孙的 首领、基多尼 的儿子 亚比但。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, '他的供物是:一 个银 盘子,重 一百 三十舍客勒,一 个银 碗,重七十 舍客勒,都是按圣所 的平, 也都盛满 了调 油 的细面 麺 作素祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 62, '一 个金 盂,重十舍客勒,盛满 了香; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, '一 只公 牛 犊,一 只公绵羊,一 只一 岁 的公羊羔 作燔祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, '一 只公 山羊 作赎罪祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, '两 只公牛,五 只公绵羊,五 只公山羊,五 只一 岁 的公羊羔 作平安 祭。这是 基多尼 儿子 亚比但 的供物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, '第十 日 来献的是但 子孙的 首领、亚米沙代 的儿子 亚希以谢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, '他的供物是:一 个银 盘子,重 一百 三十舍客勒,一 个银 碗,重七十 舍客勒,都是按圣所 的平, 也都盛满 了调 油 的细面 麺 作素祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, '一 个金 盂,重十舍客勒,盛满 了香; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, '一 只公 牛 犊,一 只公绵羊,一 只一 岁 的公羊羔 作燔祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, '一 只公 山羊 作赎罪祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, '两 只公牛,五 只公绵羊,五 只公山羊,五 只一 岁 的公羊羔 作平安 祭。这是 亚米沙代 儿子 亚希以谢 的供物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, ' 第十 一 日 来献的是亚设 子孙的 首领、俄兰 的儿子 帕结。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, '他的供物是:一 个银 盘子,重 一百 三十舍客勒,一 个银 碗,重七十 舍客勒,都是按圣所 的平, 也都盛满 了调 油 的细面 麺 作素祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, '一 个金 盂,重十舍客勒,盛满 了香; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, '一 只公 牛 犊,一 只公绵羊,一 只一 岁 的公羊羔 作燔祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, '一 只公 山羊 作赎罪祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, '两 只公牛,五 只公绵羊,五 只公山羊,五 只一 岁 的公羊羔 作平安 祭。这是 俄兰 儿子 帕结 的供物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, ' 第十 二 日 来献的是拿弗他利 子孙的 首领、以南 儿子 亚希拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, '他的供物是:一 个银 盘子,重 一百 三十舍客勒,一 个银 碗,重七十 舍客勒,都是按圣所 的平, 也都盛满 了调 油 的细面 麺 作素祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, '一 个金 盂,重十舍客勒,盛满 了香; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, '一 只公 牛 犊,一 只公绵羊,一 只一 岁 的公羊羔 作燔祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, '一 只公 山羊 作赎罪祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, '两 只公牛,五 只公绵羊,五 只公山羊,五 只一 岁 的公羊羔 作平安 祭。这是 以南 儿子 亚希拉 的供物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, '用膏抹 坛 的日子,以色列 的 众首领 为行献坛 之礼 所献的是:银 盘子 十 二个,银 碗 十 二个,金 盂 十 二个; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, '每 盘子 重一百 三十舍客勒,每 碗 重七十舍客勒。一切 器皿 的银子,按圣所 的平,共有二千 四 百舍客勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, '十 二 个金 盂 盛满 了香,按圣所 的平,每盂 重 十舍客勒,所有的 金子 共一百 二十舍客勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, ' 作燔祭的,共有公牛 十二只,公羊 十二只,一 岁 的公羊羔 十 二只,并同献的素祭 作赎罪祭 的公山羊 十 二只; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, ' 作平安 祭的,共有公牛 二十 四只,公绵羊 六十只,公山羊 六十只,一 岁 的公羊羔 六十只。这就是 用膏抹 坛 之后,为行奉献坛 之礼所献的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, '摩西 进 会 幕 要与耶和华 说话的时候,听见 法 柜 的施恩座 以上、二 基路伯 中间 有与他 说话 的声音,就是 耶和华与他 说话。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, '「你告诉 亚伦 说:点 灯的时候,七 盏灯 都要向 灯台 前 面 发光。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, '亚伦 便这样 行。他点 灯台 上的灯,使灯向 前发光,是照耶和华 所 吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, '这 灯台 的做法 是用金子 锤出来的,连 座 带 花 都是 锤出来的。摩西 制造 灯台,是照 耶和华 所 指示 的样式。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, '「你从以色列 人 中 选出 利未人来,洁净 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, '洁净 他们 当这样 行:用除罪 水 弹 在他们身上,又叫他们用 剃头刀 刮 全 身,洗 衣服,洁净自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, '然后叫他们取 一只公牛 犊,并同献的素祭,就是调 油 的细面 麺;你要另取 一 只公牛 犊 作赎罪祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, '将 利未人 奉 到会 幕 前,招聚 以色列 全 会众。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, '将 利未人 奉 到耶和华 面前,以色列 人 要按 手 在 他们头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, '亚伦 也将 他们 奉 到耶和华 面前,为 以色列 人 当作摇祭,使他们 好办 耶和华 的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, '利未人 要按 手 在 那两只牛 的头上;你要将 一 只作赎罪祭, 一 只作燔祭,献 给耶和华,为 利未人 赎罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, '你也要使 利未人 站 在亚伦 和他儿子 面前,将他们 当作摇祭 奉 给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, '「这样,你从以色列 人 中 将 利未人 分别出来,利未人 便要 归我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, '此 后 利未人 要进去 办 会 幕的事,你要洁净 他们,将他们 当作摇祭 奉上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, '因为 他们 是从以色列 人 中 全然 给 我的,我拣选 他们 归我,是代替 以色列 人中 一切 头生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, ' 以色列 人中 一切 头生的,连人 带牲畜,都是我的。我在埃及 地 击杀 一切 头生的 那天,将他们 分别为圣 归我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, '我拣选 利未人 代替 以色列 人中 一切 头生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, '我从以色列 人 中 将 利未人 当作赏赐 给 亚伦 和他的儿子,在会 幕 中办 以色列 人 的事,又为 以色列 人 赎罪,免得 他们 挨近 圣所,有灾殃 临 到他们 中间。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, '摩西、亚伦,并以色列 全 会众 便向利未人 如此行。凡 耶和华 指著利未人 所 吩咐 摩西的,以色列 人 就向他们 这样 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, '于 是利未人 洁净自己,除了罪,洗了 衣服;亚伦 将他们 当作摇祭 奉 到耶和华 面前, 又为他们 赎罪,洁净他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, '然 后 利未人 进去,在 亚伦 和他儿子 面前,在会 幕 中办 事。耶和华 指著 利未人 怎样 吩咐 摩西,以色列人就怎样 向他们 行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, '「利未人 是这样:从 二十 五 岁 以外,他们要前来 任 职,办会 幕 的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, '到了 五十 岁 要停工 退任,不 再 办 事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, '只要在会 幕里,和 他们的弟兄 一同伺候,谨守 所吩咐的,不再 办 事了。至于 所吩咐 利未人的,你要这样 向他们行。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, '以色列人出 埃及 地以后,第二 年 正 月,耶和华 在西奈 的旷野 吩咐 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, '「以色列 人 应当在所定的日期 守 逾越节, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, '就是本 月 十 四 日 黄昏 的时候,你们要在所定的日期 守 这节,要按这节的 律例 典章 而守。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, '于 是摩西 吩咐 以色列 人 守 逾越节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, '他们就在西奈 的旷野,正 月 十 四 日 黄昏 的时候,守 逾越节。凡 耶和华 所 吩咐 摩西的,以色列 人 都照样 行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, '有 几个人 因 死尸 而 不洁净,不 能 在那 日 守 逾越节。当 日 他们到 摩西、亚伦 面前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, ' 说:「我们 虽因死尸 而不洁净,为何 被阻止、不得 同 以色列 人 在所定的日期 献 耶和华 的供物呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, '摩西 对他们 说:「你们暂且等候,我可以去听 耶和华 指著你们 是怎样 吩咐的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, '「你晓谕 以色列 人 说:你们 和 你们后代中,若 有人 因死尸 而 不洁净,或 在远方 行路,还要向耶和华 守 逾越节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, '他们要在二 月 十 四 日 黄昏 的时候,守 逾越节。要用 无酵饼 与苦菜,和逾越节的羊羔同吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, '一点 不可 留 到 早晨;羊羔的骨头 一根也不可 折断。他们要照逾越节 的一切 律例 而守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, ' 那 洁净 而 不 行路 的人 若推辞 不守 逾越节,那 人 要从民 中剪除;因为 他 在所定的日期 不 献 耶和华 的供物, 应该担当 他的罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, '若 有外人 寄居 在你们中间,愿 意向耶和华 守 逾越节,他要照逾越节 的律例 典章 行,不管是寄居的 是本地 人, 同归 一 例。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, '立起 帐幕 的那日,有云彩 遮盖 帐幕,就是法柜 的帐幕;从晚上 到 早晨, 云彩在 其上,形状如 火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, '常 是 这样,云彩 遮盖帐幕,夜间 形状 如火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, '云彩 几时 从 帐幕 收上去, 以色列 人 就几时起行;云彩 在哪里 停住,以色列 人 就在那里 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, '以色列 人 遵 耶和华 的吩咐 起行,也遵 耶和华 的吩咐 安营。云彩 在 帐幕 上停住 几时,他们就住营 几时。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, '云彩 在 帐幕 上停留 许多 日子,以色列 人 就守 耶和华 所吩咐的 不 起行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, '有时 云彩 在 帐幕 上几 天,他们就照 耶和华 的吩咐 住营,也照 耶和华 的吩咐 起行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, '有时 从晚上 到 早晨,有这云彩在帐幕上;早晨 云彩 收上去,他们就起行。有时 昼 夜 云彩停在帐幕上,收上去的时候,他们就起行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, '云彩 停留 在 帐幕上,无论是 两天,是 一月,是 一年,以色列 人 就住营 不 起行;但云彩收上去,他们就起行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, '他们遵 耶和华 的吩咐 安营,也遵 耶和华 的吩咐 起行。他们守 耶和华 所吩咐的,都是凭 耶和华 吩咐 摩西的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, '「你要用银子 做 两 枝号,都要 锤出来的,用以 招聚 会众,并叫 众营 起行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, '吹 这号的时候,全 会众 要到你那里,聚集 在 会 幕 门口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, '若 单吹 一枝,众首领,就是以色列 军中 的统领,要聚集 到你那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, '吹出 大声的时候,东边 安 的营 都要起行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, '二次 吹出 大声的时候,南边 安 的营 都要起行。他们将起行,必吹出 大声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, '但招聚 会众的时候,你们要吹号,却不要 吹出大声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, '亚伦 子孙 作祭司 的要吹 这号;这要作 你们 世世代代 永远 的定例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, ' 你们在自己的地,与 欺压 你们 的敌人 打 仗,就要用号 吹出大声,便在耶和华─你们的 神 面前 得蒙纪念,也蒙拯救 脱离仇敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, '在你们快乐 的日子 和节期,并月 朔, 献燔祭 和 平安 祭,也要吹 号,这都要在你们的 神 面前 作为纪念。我 是耶和华─你们的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, ' 第二 年 二 月 二十日,云彩 从 法柜 的帐幕 收上去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, '以色列 人 就按站 往前行,离开 西奈 的旷野,云彩 停住 在巴兰 的旷野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, '这是他们照 耶和华 藉 借 摩西 所吩咐的,初次 往前行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, '按著军队 首先 往前行 的是犹大 营 的纛。统领 军队 的是亚米拿达 的儿子 拿顺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, '统领 以萨迦 支派 军队 的是苏押 的儿子 拿坦业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, '统领 西布伦 支派 军队 的是希伦 的儿子 以利押。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, '帐幕 拆卸,革顺 的子孙 和米拉利 的子孙 就抬著 帐幕 先往前行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, '按著军队 往前行 的是流便 营 的纛。统领 军队 的是示丢珥 的儿子 以利蓿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, '统领 西缅 支派 军队 的是苏利沙代 的儿子 示路蔑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, '统领 迦得 支派 军队 的是丢珥 的儿子 以利雅萨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, '哥辖人 抬著 圣物 先往前行。他们未 到以前,抬帐幕的已经把 帐幕 支好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, '按著军队 往前行 的是以法莲 营 的纛,统领 军队 的是亚米忽 的儿子 以利沙玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, '统领 玛拿西 支派 军队 的是比大蓿 的儿子 迦玛列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, '统领 便雅悯 支派 军队 的是基多尼 的儿子 亚比但。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, '在诸 营 末后 的是但 营 的纛,按著军队 往前行。统领 军队 的是亚米沙代 的儿子 亚希以谢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, '统领 亚设 支派 军队 的是俄兰 的儿子 帕结。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, '统领 拿弗他利 支派 军队 的是以南 的儿子 亚希拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, '以色列 人 按著军队 往前 行,就是这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, '摩西 对他 岳父(或译:内兄)─米甸人 流珥 的儿子 何巴─说:「我们 要行路,往 耶和华 所 应许 之地去;他曾说:『我要将这地 赐 给你们。』现在求你和我们 同去,我们必厚待 你,因为 耶和华 指著 以色列人 已经应许 给好处。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, '何巴回答说:「我不 去; 我要回 本地 本族那里去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, '摩西说:「求你 不要 离开  我们;因为 你知道 我们要在旷野 安营,你可以当作 我们的 眼目。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, '你 若 和我们 同去,将来耶和华 有 什么 好处 待 我们,我们也必以什么 好处待 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, '以色列人离开  耶和华 的山,往前行了三 天 的路程;耶和华 的约 柜 在前头 行了 三 天 的路程,为他们 寻找 安歇的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, '他们拔 营 往前行,日间 有耶和华 的云彩 在他们以上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, ' 约柜 往前行的时候,摩西 就说:「耶和华啊,求你兴起!愿 你的仇敌 四散!愿 恨 你的人从你面前 逃跑!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, '约柜停住的时候,他就说:「耶和华啊,求你回到 以色列 的千 万人中!」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, ' 众百姓 发怨言,他们的恶语 达到耶和华 的耳中。耶和华 听见了 就怒气 发作, 使火 在他们中间 焚烧,直烧 到营 的边界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, '百姓 向 摩西 哀求,摩西 祈求 耶和华,火 就熄了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, '那 地方 便叫做 他备拉,因为 耶和华 的火 烧 在他们中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, ' 他们中间 的闲 杂人 大起 贪欲的心;以色列 人 又 哭号 说:「谁 给我们肉 吃呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, '我们记得,在埃及 的时候不花钱 就 吃 鱼,也记得有 黄瓜、 西瓜、 韭菜、 葱、 蒜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, '现在 我们的心血 枯竭了,除 这吗哪以外,在我们眼前 并没有 别的东西。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, '(这吗哪 仿佛芫荽 子,又 好像 珍珠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, '百姓 周围行走,把吗哪收起来,或用磨 推,或 用臼 捣,煮 在锅中,又做成 饼,滋味 好像 新 油。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, '夜间 露水 降 在 营中,吗哪 也随著 降下。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, '摩西 听见 百姓 各 在各家 的帐棚 门口 哭号。耶和华 的怒气 便大 发作,摩西 就不喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, '摩西 对 耶和华 说:「你为何 苦待 仆人?我为何 不 在你眼前 蒙 恩,竟把 这管理 百姓 的重任 加 在我身上呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, ' 这 百姓 岂是我 怀的胎,岂是 我 生下来的呢?你竟 对我 说:『把他们抱 在怀里,如 养育之父 抱 吃奶的孩子,直抱到你 起誓应许 给他们祖宗 的地去。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, '我 从哪里 得肉 给 这 百姓吃呢? 他们都向我 哭号 说:『你给 我们 肉 吃吧!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, ' 管理 这 百姓 的责任太重了,我 独自 担当 不 起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, ' 你 这样 待 我,我若 在你眼前 蒙 恩,求你 立时 将我杀了,不 叫我见 自己的苦情。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, '耶和华 对 摩西 说:「你从以色列 的长老中 招聚 七十个 人,就是 你所知道 作 百姓 的长老 和官长的,到我这里来,领 他们 到 会 幕前,使他们和你 一同站立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, '我要在那里 降临,与你 说话,也要 把 降于 你身上的 灵 分赐 他们,他们就和你 同当 这管百姓 的重任,免得 你 独自 担当。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, '又要对 百姓 说:『你们应当自洁,预备明天 吃 肉,因为 你们哭号 说:谁 给我们肉 吃! 我们 在埃及 很好。这声音达到了耶和华 的耳中,所以他 必给 你们 肉 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, '你们不止 吃 一 天、 两天、 五 天、 十 天、 二十 天, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, ' 要吃一个整 月,甚至 肉 从你们鼻孔 里喷出来,使 你们 厌恶了,因为 你们厌弃 住在你们中间 的 耶和华,在他面前 哭号 说:我们为何 出了 埃及呢!』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, '摩西 对耶和华说:「这 与我 同住的 百姓、步行的男人 有六 十万,你 还说:『我要把肉 给 他们,使他们可以吃 一个整 月。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, '难道给他们 宰了 羊群 牛群,或是 把 海中 所有的 鱼 都聚了来,就够 他们吃吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, '耶和华 对 摩西 说:「耶和华 的膀臂 岂是缩短了吗?现在 要看 我的话 向你应验 不应验。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, '摩西 出去,将 耶和华 的话 告诉 百姓,又招聚 百姓 的长老中 七十个 人来,使他们 站 在会幕 的四围。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, '耶和华 在云中 降临,对摩西 说话, 把 降与他身上的 灵 分赐 那七十个 长老。 灵 停 在他们身上的时候,他们就受感说话,以后却没有 再说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, '但有两个 人 仍 在营里,一个 名 叫伊利达,一个 名 叫米达。他们 本是在那些被录的人中,却没有 到 会幕那里去。灵 停 在他们身上,他们就在营里 说预言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, '有个少年人 跑来 告诉 摩西 说:「伊利达、米达 在营里 说预言。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, '摩西 的帮手,嫩 的儿子 约书亚,就是摩西所拣选的一个人, 说:「请我主 摩西 禁止他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, '摩西 对他 说:「你 为我的缘故 嫉妒人吗?惟愿  耶和华 的百姓 都 受感说话! 愿 耶和华 把 他的灵 降 在他们身上!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, '于 是,摩西 和以色列 的长老 都回 到 营里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, '有风 从 耶和华 那里刮起,把鹌鹑 由 海 面刮来,飞散 在 营 边和营 的四围;这边 约有一天 的路程,那边 约有一天 的路程,离 地 面 约有二肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, '百姓 起来,终 日 终 夜,并次 日一整 天,捕取 鹌鹑;至少的 也取了 十 贺梅珥,为自己 摆 列 在营 的四围。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, '肉 在他们牙齿 之间 尚未 嚼烂,耶和华 的怒气 就向他们 发作, 用最 重 的灾殃 击杀了 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, '那 地方 便叫做基博罗‧哈他瓦(就是贪欲之人的坟墓),因为 他们在那里 葬埋 那起贪欲 之心的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, '百姓从基博罗‧哈他瓦 走 到哈洗录,就住 在哈洗录。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, ' 摩西娶了 古实 女子为妻。米利暗 和亚伦 因 他所 娶的 古实 女子 就毁谤 他,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, '「难道 耶和华 单 与摩西 说话,不 也 与我们 说话吗?」这话耶和华 听见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, '(摩西 为人 极其 谦和,胜过 世 上 的众 人。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, '耶和华 忽然 对 摩西、 亚伦、 米利暗 说:「你们三个人 都出来,到 会 幕这里。」他们三个人 就出来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, '耶和华 在云 柱中 降临,站 在会幕 门口,召 亚伦 和米利暗,二人 就出来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, '耶和华说:「你们且 听 我的话:你们中间若 有 先知,我─耶和华 必在异象 中向他 显现,在梦中 与他 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, '我的仆人 摩西 不是 这样;他是 在我全 家 尽忠的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, '我要与他 面 对 面 说话,乃是明说,不 用谜语,并且他必见 我 的形像。你们毁谤 我的仆人 摩西,为何 不 惧怕呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, '耶和华 就向他们 二人发 怒 而去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, '云彩 从 会幕 上挪开 了,不料,米利暗 长了大痲疯, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, '有雪那样白。亚伦 一看 米利暗 长了大痲疯, 就对 摩西 说:「 我主啊,求 你不要 因 我们愚昧 犯罪,便将这罪 加 在我们身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, '求 你不要 使她 像那 出 母 腹、肉 已半 烂 的死胎。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, '于 是摩西 哀求 耶和华 说:「 神啊,求 你医治 她!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, '耶和华 对 摩西 说:「她父亲 若吐 唾沫 在她脸上,她岂不 蒙羞 七 天吗?现在要把她在营 外 关锁 七 天,然后 才可以领她进来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, '于 是米利暗 关锁 在营 外 七 天。百姓 没有 行路,直等到 把米利暗 领进来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, '以后 百姓 从哈洗录 起行,在巴兰 的旷野 安营。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, '「你打发 人 去窥探 我 所 赐 给以色列 人 的迦南 地,他们每 支派 中 要打发 一个 人,都 要作首领的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, '摩西 就照 耶和华 的吩咐 从巴兰 的旷野 打发 他们去;他们 都 是以色列 人 的族长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, ' 他们的名字:属流便 支派的 有撒刻 的儿子 沙母亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, '属西缅 支派的 有何利 的儿子 沙法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, '属犹大 支派的 有耶孚尼 的儿子 迦勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, '属以萨迦 支派的 有约色 的儿子 以迦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, '属以法莲 支派的 有嫩 的儿子 何希阿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, '属便雅悯 支派的 有拉孚 的儿子 帕提。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, '属西布伦 支派的 有梭底 的儿子 迦叠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, '约瑟 的子孙,属玛拿西 支派的 有稣西 的儿子 迦底。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, '属但 支派的 有基玛利 的儿子 亚米利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, '属亚设 支派的 有米迦勒 的儿子 西帖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, '属拿弗他利 支派的 有缚西 的儿子 拿比。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, '属迦得 支派的 有玛基 的儿子 臼利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, '这就是 摩西 所 打发、窥探 那 地 之人 的名字。摩西 就称 嫩 的儿子 何希阿 为约书亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, '摩西 打发 他们 去窥探 迦南 地,说:「你们从 南地 上 山地去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, '看 那地 如何,其中 所住的 民 是 强 是弱,是 多 是 少, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, ' 所 住 之处 是 好 是 歹, 所 住 之处 是营盘 是 坚城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, '又看 那地土 是 肥美 是 瘠薄,其中 有 树木 没有。你们要放开 胆量,把那地 的果子 带些来。」(那时 正是葡萄 初熟 的时候。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, '他们上去 窥探 那地,从寻 的旷野 到 利合,直到哈马 口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, '他们从南地 上去,到了 希伯仑 ;在那里 有亚衲 族人 亚希幔、示筛、挞买 。(原来希伯仑 城 被建造 比埃及 的锁安城 早 七 年。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, '他们到了 以实各 谷,从那里 砍了 葡萄树的一枝,上头有一 挂 葡萄,两个人 用杠 抬著,又带了些 石榴 和 无花果来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, '(因 为 以色列 人 从那里 砍 来的那 挂葡萄,所以那 地方 叫做 以实各 谷。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, '过了 四十 天,他们窥探 那地 才回来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, '到了 巴兰 旷野 的加低斯, 见 摩西、 亚伦,并 以色列 的全 会众,回 报摩西、亚伦,并 全 会众,又把 那地 的果子 给他们看; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, '又告诉 摩西 说:「我们到了 你所 打发我们去 的那地,果然 是 流 奶 与蜜之地;这就是 那地的果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, '然而 住 那地 的民 强壮,城邑 也坚固 宽 大,并且 我们在那里 看见 了亚衲 族的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, '亚玛力人 住 在南 地;赫人、耶布斯人、亚摩利人 住 在山地;迦南人 住 在 海边 并 约旦河 旁。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, '迦勒 在 摩西 面前安抚 百姓,说:「我们立刻 上去 得 那地吧! 我们足能 得胜。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, '但那些 和他同 去 的人 说:「我们不 能 上去 攻击 那民,因为 他们 比我们 强壮。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, '探子中有人论到所 窥探 之地,向 以色列 人 报 恶信,说:「我们所 窥探、经过 之地 是 吞吃 居民 之地,我们在那里 所 看见 的人民 都 身量高大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, '我们在那里 看见 亚衲族 人,就是 伟人;他们是伟人 的后裔。据我们看,自己就 如蚱蜢一样;据他们看,我们也是 如此。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, '当下,全 会众大 声 喧嚷;那 夜 百姓 都哭号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, '以色列 众 人 向 摩西、 亚伦 发怨言;全 会众 对他们 说:「巴不得 我们早死 在埃及 地,或 是 死 在这 旷野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, '耶和华 为什么 把我们 领 到 那 地,使我们倒 在刀下呢?我们的妻子 和孩子 必 被掳掠。我们 回 埃及 去岂不 好吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, '众人彼此 说:「我们不如立 一个首领 回 埃及去吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, '摩西、亚伦 就俯伏 在 以色列 全 会 众 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, '窥探 地 的人中,嫩 的儿子 约书亚 和耶孚尼 的儿子 迦勒 撕裂 衣服, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, ' 对 以色列 全 会众 说:「我们所 窥探、经过 之地 是极 美 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, '耶和华 若 喜悦 我们,就必将我们 领 进 那 地,把地赐 给我们;那地 原 是 流 奶 与蜜之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, '但 你们 不可 背叛 耶和华,也不要 怕 那地 的居民;因为 他们 是我们的食物,并且荫庇 他们的已经离开  他们。有耶和华 与我们同在,不要 怕他们!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, '但全 会众 说:「拿石头 打死 他们二人。」忽然,耶和华 的荣光 在会 幕 中向 以色列 众 人 显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, '耶和华 对 摩西 说:「这 百姓 藐视我 要到 几时呢?我在他们中间 行了 这 一切 神迹,他们还不 信 我 要到 几时呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, '我要用瘟疫 击杀他们,使他们不得承受那地,叫 你 的后裔成为大 国,比他们 强胜。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, '摩西 对 耶和华 说:「埃及人 必听见这事;因为 你曾施展大能,将 这 百姓 从他们中间 领上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, '埃及人要将这事传 给 迦南 地 的居民;那民已经听见 你─耶和华 是在这 百姓 中间;因为 你 面 对面 被人看见,有你的云彩 停 在他们以上。你 日间 在云 柱中,夜间 在火 柱中,在他们前面 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, '如今你若把 这 百姓 杀了,如杀一 人,那些 听见 你名声 的列邦 必议论 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, '『耶和华 因为不 能 把 这 百姓 领 进 他向他们 起誓 应许之 地,所以在旷野 把他们杀了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, '现在 求 主 大显 能力,照你所 说过 的话说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, '『耶和华 不轻易 发怒,并有丰盛 的慈爱,赦免 罪孽 和过犯;万 不 以有罪的为无罪,必追讨 他的罪,自父 及 子,直到 三、 四代。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, '求 你照你的大 慈爱 赦免 这 百姓 的罪孽,好像 你从埃及 到 如今 常赦免 他们一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, '耶和华 说:「我照著你的话 赦免了他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, '然 我指著我 的永生起誓, 遍 地 要被我 的荣耀 充满。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, '这些 人 虽看 见 我的荣耀 和我在埃及 与旷野 所 行 的神迹,仍然试探 我 这 十 次,不 听从 我的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, '他们断不得 看见 我向他们的祖宗 所 起誓 应许之地。凡 藐视我的,一个也不 得看见; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, '惟独我的仆人 迦勒,因 他另 有 一个心志,专一 跟从我,我就把他领 进 他所 去过 的那地;他的后裔 也必得那地为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, '亚玛力人 和迦南人 住 在谷中,明天 你们要转回,从红 海 的路 往旷野 去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, '耶和华 对 摩西、 亚伦 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, '「这 恶 会众 向我 发怨言,我忍耐他们要到 几时呢?以色列 人 向我 所 发的 怨言,我都听见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, '你们告诉 他们,耶和华 说:『我 指著我的永生起誓,我必要 照 你们达到我耳中 的话 待 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, '你们的尸首 必倒 在这 旷野,并且 你们中间 凡 被数点、从 二十 岁 以外、 向我 发怨言的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, '必不 得进 我起 誓 应许叫你们 住 的 那地;惟有 耶孚尼 的儿子 迦勒 和嫩 的儿子 约书亚才能进去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, '但你们的妇人孩子,就是 你们所说、要 被掳掠的,我必把他们 领进去,他们就得知 你们所 厌弃 的那地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, '至于 你们,你们的尸首 必倒 在这 旷野; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, '你们的儿女 必 在旷野 飘流 四十 年,担当 你们淫行的罪,直到 你们的尸首 在旷野 消灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, '按 你们窥探 那地 的四十 日, 一年 顶一日,你们要担当 罪孽 四十 年,就知道 我与你们疏远了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, '我─耶和华 说过,我总要 这样 待 这 一切 聚集 敌我 的恶 会众;他们必在这 旷野 消灭,在这里 死亡。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, '摩西 所 打发、窥探 那地 的人 回来,报 那地 的恶信,叫 全 会众 向摩西 发怨言, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, '这些 报 恶 信 的人 都遭瘟疫,死 在耶和华 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, '其中 惟有嫩 的儿子 约书亚 和耶孚尼 的儿子 迦勒 仍然存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, '摩西 将 这些 话 告诉 以色列 众 人,他们 就甚 悲哀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, '清早 起来,上 山 顶 去,说:「我们在这里, 我们有罪了;情愿 上 耶和华 所 应许 的地方 去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, '摩西 说:「你们 为何 违背 耶和华 的命令呢?这事 不能 顺利了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, '不要 上去;因为 耶和华 不 在你们中间,恐怕 你们被仇敌 杀败了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, ' 亚玛力人 和迦南人都在 你们面前,你们必倒 在刀下;因 你们退回 不跟从 耶和华,所以他 必 不 与你们同在。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, '他们却擅敢 上 山 顶 去,然而耶和华 的约 柜 和摩西 没有 出 营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, '于 是亚玛力人 和住 在那 山上 的迦南人 都下来 击打他们,把他们杀退了,直到 何珥玛。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, '「你晓谕 以色列 人 说: 你们到了 我 所 赐 给你们 居住 的地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, '若愿 意从 牛群 羊群 中取牛羊作火祭,献 给耶和华,无论是燔祭 是 平安祭,为要还特许的 愿 ,或是 作甘心祭,或是 逢你们节期献的,都要奉 给耶和华 为馨 香之祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, '那献 供物 的就要将细面 麺 伊法十分之一,并油 一欣 四分之一,调和 作素祭,献 给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, '无论是燔祭 是 平安祭,你要为每只 绵羊羔,一同 预备 奠祭 的酒 一欣 四分之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, ' 为公绵羊 预备 细面 麺 伊法十分 之二,并油 一欣 三分之一,调和 作素祭, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, '又用酒 一欣 三分之一 作奠祭,献 给耶和华 为馨 香之祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, ' 你预备 公牛 作燔祭,或是 作平安祭,为要还特许的 愿 ,或是 作平安祭,献给耶和华, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, '就要把细面 麺 伊法十分 之三,并油 半 欣,调和 作素祭,和公牛 一同 献上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, '又用酒 半 欣 作奠祭,献 给耶和华 为馨 香 的火祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, '「献公牛、 公绵羊、 绵羊 羔、 山羊羔,每只都要这样 办理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, '照你们所 预备 的数目,按著只 数 都要这样 办理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, '凡 本地人 将馨 香 的火祭 献 给耶和华,都要这样 办理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, '若有 外人 和你们 同居,或 有人 世世代代 住在你们中间,愿 意将馨 香 的火祭 献 给耶和华,你们怎样 办理,他也要照样 办理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, '至于 会众,你们 和同居 的外人 都归一 例,作为你们世世代代 永远 的定例,在耶和华 面前,你们怎样,寄居的 也要怎样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, '你们 并与你们 同居 的外人 当有 一样 的条例,一样 的典章。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, '「你晓谕 以色列 人 说:你们到了 我 所 领 你们 进去 的那地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, '吃 那地 的粮食,就要 把举祭 献 给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, '你们要用初熟 的麦子磨面 麺,做饼 当举祭 奉献;你们举上,好像 举禾场 的举祭一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, '你们世世代代 要用初熟 的麦子磨面 麺,当举祭献 给 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, '「 你们有错误的时候,不 守 耶和华 所 晓谕 摩西 的这 一切 命令, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, '就是耶和华 藉 借 摩西 一切 所 吩咐 你们的,自 那 日 以至 你们的世世代代, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, '若 有 误 行,是会众 所不知道的,后来全 会众 就要将一只 公牛 犊 作燔祭,并照典章 把素祭 和奠祭 一同献 给耶和华 为馨 香之祭,又献一只 公山羊 作赎罪祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, '祭司 要为 以色列 全 会众 赎罪,他们 就必蒙赦免,因为 这 是错误。他们 又因 自己的错误,把 供物,就是 向耶和华 献的火祭 和赎罪祭,一并奉 到耶和华 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, '以色列 全 会众 和寄居 在他们中间 的外人 就必蒙赦免,因为这罪是 百姓 误犯的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, '「若 有一个 人 误 犯了罪,他就要献 一 岁 的母山羊 作赎罪祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, '那误行的人 犯罪的时候,祭司 要在耶和华 面前 为 他 赎罪, 他 就必蒙赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, '以色列 中 的本地人 和寄居 在他们中间 的外人,若误 行了什么事,必归 一样 的条例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, '但 那 擅敢 行事的,无论 是本地人 是 寄居的,他 亵渎了 耶和华, 必从民 中 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, '因 他藐视 耶和华 的言语,违背 耶和华的命令,那 人 总要 剪除;他的罪孽 要归到他身上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, ' 以色列 人 在旷野的时候,遇见 一个人 在安息 日 捡 柴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, '遇见 他 捡 柴的人,就把他 带 到 摩西、 亚伦 并 全 会众那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, '将他 收 在监内;因为 当怎样 办 他,还没有 指明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, '耶和华 吩咐 摩西 说:「总要 把 那人 治死;全 会众 要在营 外 用石头 把他打死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, '于 是全 会众 将他 带 到 营 外,用石头 打死 他,是照耶和华 所 吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, '「你吩咐 以色列 人,叫 他们 世世代代 在 衣服 边 上做 䍁子,又在 底边 的䍁子 上钉 一根蓝 细带子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, '你们 佩带 这䍁子,好叫你们看见 就记念 遵行 耶和华 一切 的命令,不 随 从 自己的心意、 眼目 行邪淫,像 你们 素常一样; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, '使 你们记念 遵行 我一切 的命令,成为 圣洁,归与你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, '「我 是耶和华─你们的 神, 曾把你们 从埃及 地 领出来,要作 你们的 神。我 是耶和华─你们的 神。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, '利未 的曾孙、哥辖 的孙子、以斯哈 的儿子 可拉,和流便 子孙 中以利押 的儿子 大坍、亚比兰,与比勒 的儿子 安, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, '并 以色列 会 中的二百 五十个 首领,就是有名望 选入 会中 的人,在摩西 面前 一同起来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, '聚集 攻击 摩西、 亚伦,说:「你们 擅自专权! 全 会众 个个 既是圣洁,耶和华 也在他们中间,你们为什么 自高,超过 耶和华 的会众呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, '摩西 听见 这话就俯伏 在 地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, ' 对 可拉 和 他一 党 的人说:「到了早晨,耶和华 必指示 谁 是属他的, 谁是圣洁的,就叫谁亲近 他; 他所 拣选的 是谁,必叫谁亲近 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, '可拉啊,你们要这样 行,你和你的一 党 要拿 香炉来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, '明日,在耶和华 面前,把火 盛 在炉中,把香 放 在其上。耶和华 拣选 谁,谁 就 为 圣洁。你们 这利未 的子孙 擅自专权了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, '摩西 又对 可拉 说:「利未 的子孙哪, 你们听我说! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, ' 以色列的 神 从以色列 会中 将你们 分别出来,使你们 亲近 他,办 耶和华 帐幕 的事,并站 在会众 面前 替他们当差。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, '耶和华又使你 和 你一切 弟兄─利未 的子孙─一同 亲近他,这岂为小事?你们还 要求 祭司的职任吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, ' 你 和你一 党 的人聚集 是要攻击 耶和华。亚伦 算什么,你们竟 向他 发怨言呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, '摩西 打发 人去召 以利押 的儿子 大坍、亚比兰。他们说:「我们不 上去! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, ' 你将我们从流 奶 与蜜 之地 领上来,要在旷野 杀我们,这岂为 小事? 你还要 自立 为王 辖管我们吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, '并且 你没有 将我们领 到 流 奶 与蜜 之地,也没有把田地 和葡萄园 给 我们 为业。难道你要剜 这些 人 的眼睛吗?我们不 上去!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, '摩西 就甚 发怒,对 耶和华 说:「求你不要 享受 他们 的供物。我并没有 夺过 他们一匹 驴,也没有 害过 他们 一个人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, '摩西 对 可拉 说:「明天,你 和你一 党的人, 并亚伦,都要 站在耶和华 面前; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, '各人 要拿 一个香炉, 共二百 五十 个,把香 放 在上面,到 耶和华 面前。你 和亚伦 也各 拿自己的香炉。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, '于 是他们各人 拿 一个香炉,盛 上 火,加 上 香,同摩西、亚伦 站 在会 幕 门前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, '可拉 招聚 全 会众 到 会 幕 门前,要攻击摩西、亚伦;耶和华 的荣光 就向 全 会众 显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, '耶和华 晓谕 摩西、 亚伦 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, '「你们离开  这 会众,我好在转眼之间 把他们 灭绝。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, '摩西、亚伦就俯伏 在 地,说:「 神,万 人 之灵的 神啊,一 人 犯罪,你就要向 全 会众 发怒吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, '「你吩咐 会众 说:『你们离开  可拉、大坍、亚比兰 帐棚 的四围。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, '摩西 起来,往 大坍、亚比兰 那里去;以色列 的长老 也随著他 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, '他吩咐 会众 说:「 你们离开  这 恶 人 的帐棚吧,他们 的物件,什么都 不可 摸,恐怕 你们陷在 他们的罪中,与他们一同消灭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, '于 是众人离开  可拉、大坍、亚比兰 帐棚 的四围。大坍、亚比兰 带著妻子、儿女、小孩子,都出来,站 在自己的帐棚 门口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, '摩西 说:「我行的 这 一切 事 本 不是 凭我自己心意行的,乃是 耶和华 打发我行的,必有证据使 你们知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, '这些人 死 若 与世 人 无异,或是他们所遭的 与世 人 相同,就不是 耶和华 打发我来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, '倘若 耶和华 创作 一件新事,使地 开  口,把他们 和 一切 属他们的 都吞下去,叫他们活活地 坠落 阴间,你们就明白 这些 人 是藐视 耶和华了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, '摩西刚 说 完了 这 一切 话,他们脚下 的 地 就开 了口, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, ' 把他们 和 他们的家眷,并 一切 属可拉 的人丁、 财物,都 吞下去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, '这样,他们 和一切 属他们的,都活活地 坠落 阴间;地 口在他们上头 照旧合闭,他们就从会 中 灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, ' 在他们四围 的以色列 众人 听他们呼号,就都逃跑, 说:「恐怕 地 也把我们吞下去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, '又有火 从 耶和华 那里出来,烧灭了 那献 香 的二百 五十 个人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, '「你吩咐 祭司 亚伦 的儿子 以利亚撒 从火 中 捡起 那些香炉来,把 火 撒 在别处,因为 那些香炉是圣的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, '把 那些 犯罪、自害己命 之人的香炉,叫人锤 成 片子,用以包 坛。那些香炉本是 他们在耶和华 面前 献过的,所以是圣的,并且可以给以色列 人 作 记号。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, '于 是祭司 以利亚撒 将 被烧之人 所 献 的铜 香炉 拿来,人就锤出来,用以包 坛, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, '给以色列 人 作纪念,使 亚伦 后裔 之外 的人 不得 近前来 在耶和华 面前 烧 香,免得 他遭可拉 和他一党所遭的。这乃是照 耶和华 藉 借著 摩西 所吩咐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, '第二天,以色列 全 会众 都向 摩西、 亚伦 发怨言 说:「你们 杀了 耶和华 的百姓了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, ' 会众 聚集 攻击 摩西、 亚伦的时候,向 会 幕 观看,不料,有云彩 遮盖了,耶和华 的荣光 显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, '摩西、亚伦 就来 到 会 幕 前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, '耶和华 吩咐 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, '「你们离开  这 会众,我好在转眼之间 把他们 灭绝。」他们二人就俯伏 于  地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, '摩西 对 亚伦 说:「拿 你的香炉,把坛 上 的火 盛 在其中,又加上 香,快快 带 到 会众那里,为他们 赎罪;因为 有忿怒 从 耶和华 那里出来,瘟疫 已经发作了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, '亚伦 照著 摩西 所说的 拿来,跑 到 会 中,不料,瘟疫 在百姓 中已经发作了。他就加 上 香,为 百姓 赎罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, '他站 在 活人 死人 中间,瘟疫 就止住了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, '除了 因 可拉 事情 死的以外,遭瘟疫 死的,共有 一万四 千 七 百人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, '亚伦 回 到 会 幕 门口,到 摩西那里,瘟疫 已经止住了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, '耶和华 对 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, '「你晓谕 以色列 人,从他们 手下取 杖,每支派 一根;从他们 所有的 首领,按著支派,共取十二 根。你要将 各人 的名字 写 在 各人的杖上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, '并要将 亚伦 的名字 写 在 利未 的杖上,因为 各族 长 必有一根 杖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, '你要把这些杖存 在会 幕 内法柜 前,就是 我与你们 相会 之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, '后来 我所 拣选的 那人,他的杖 必发芽。这样,我必使以色列 人 向你们 所 发的 怨言 止息,不再达到我耳中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, '于 是摩西 晓谕 以色列 人,他们的 首领 就把杖 交 给他,按著支派,每 首领 一根, 共有十 二 根;亚伦 的杖 也在其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, '摩西 就把 杖 存 在法柜 的帐幕内,在耶和华 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, ' 第二天,摩西 进 法柜 的帐幕 去。谁知 利未 族 亚伦 的杖 已经发了芽,生了 花苞,开 了 花,结了 熟杏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, '摩西 就把 所有的 杖 从耶和华 面前 拿出来,给 以色列 众 人看;他们看见了,各首领 就把自己的杖 拿去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, '耶和华 吩咐 摩西说:「把 亚伦 的杖 还放 在法柜 前,给这些背叛 之子 留 作记号。这样,你就使他们向我 发的怨言 止息,免得 他们死亡。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, '摩西 就这样行。耶和华 怎样 吩咐 他,他就怎样 行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, '以色列 人 对 摩西 说:「 我们死啦!我们灭亡啦!都 灭亡啦! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, '凡 挨 近 耶和华 帐幕 的是必死的。 我们都要 死亡吗?」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, '耶和华 对 亚伦 说:「你 和你的儿子,并你本 族的人,要一同 担当干犯 圣所 的罪孽。你 和你的儿子 也要一同 担当干犯 祭司职任 的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, '你要带 你弟兄 利未 人,就是 你祖宗 支派 的人前来,使他们与你 联合,服事你,只是你 和你的儿子,要一同 在法柜 的帐幕 前供职。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, '他们要守 所吩咐你的,并守 全 帐幕,只是 不可 挨近 圣所 的器具 和 坛,免得 他们 和 你们 都 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, '他们要与你 联合,也要看 守 会 幕,办理帐幕 一切 的事,只是外人 不可 挨近 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, '你们要看 守 圣所 和 坛,免得 忿怒 再 临到 以色列 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, ' 我 已将 你们的弟兄 利未人 从以色列 人 中 拣选 出来归耶和华,是给 你们 为赏赐的,为要办理 会 幕 的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, '你 和你的儿子 要为一切 属坛 和幔子 内 的事 一同 守 祭司的职任。你们要这样供职;我将 祭司的职任 给 你们当作赏赐 事奉我。凡挨近 的外人 必被治死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, '耶和华 晓谕 亚伦说:「 我 已将 归我的举祭,就是以色列 人 一切 分别为圣的物,交 给你 经管;因你受过膏,把这些都赐 给你 和你的子孙,当作永得的 分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, ' 以色列人归 给我 至 圣的 供物,就是 一切的 素祭、 赎罪祭、 赎愆祭,其中所有存留不经 火的,都为至 圣之物,要归 给你 和你的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, '你要拿这些当至 圣物 吃;凡 男丁 都可以吃。你 当以此物为 圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, '以色列 人 所献的 举祭并 摇祭 都是 你的;我已赐 给你 和你的儿 女,当作永 得的分;凡 在你家中 的洁净人 都可以吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, '凡 油 中、 新酒中、五谷 中至好的,就是 以色列人所献 给耶和华 初熟之物,我都赐 给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, '凡 从他们地上 所 带来 给耶和华 初熟之物 也都要归 与你。你家中 的洁净人 都 可以吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, '以色列中 一切 永献的 都必归 与你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, '他们所有 奉 给耶和华的,连人 带牲畜,凡 头 生的,都要归 给你;只是 人 头生的,总要 赎出来; 不洁净 牲畜 头生的,也要赎出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, '其中在一月 之外 所当赎的,要照你所估定的价,按圣所 的平,用银子 五 舍客勒 赎出来(一舍客勒是 二十 季拉)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, '只是 头生 的牛,或是 头生 的绵羊 和 山羊,必不可 赎,都是 圣的,要把 牠的血 洒 在 坛上,把 牠的脂油 焚烧,当作馨 香 的火祭 献给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, '牠的肉 必归 你,像被摇 的胸、被举的右 腿 归 你一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, '凡 以色列 人 所 献 给耶和华 圣物 中的举祭,我都赐 给你 和你的儿 女,当作永 得的分。这是 给你 和你的后裔、在耶和华 面前 作为永远 的盐 约(盐就是不废坏的意思)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, '耶和华 对 亚伦 说:「你在以色列 人 的境 内 不可 有产业,在他们中间 也不可 有 分。我就是 你的分,是你的产业。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, '「 凡 以色列中 出产的十分之一,我已赐 给利未 的子孙 为业;因他们 所 办的 是会 幕 的事,所以赐给他们为酬 他们的劳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, '从今以后,以色列 人 不可 挨近 会 幕,免得他们担 罪 而死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, '惟独 利未人 要办 会 幕 的事, 担当 罪孽;这要作你们世世代代 永远 的定例。他们在以色列 人 中 不可 有 产业; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, '因为 以色列 人 中出产的十分之一,就是 献 给耶和华 为举祭的,我已赐 给利未人 为业。所以 我对他们 说:『在以色列 人 中 不可 有 产业。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, '耶和华 吩咐 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, '「你晓谕 利未人 说: 你们从 以色列 人 中所取的 十分之一,就是 我给 你们 为业的,要再从 那十分之一 中取 十分之一 作为举祭 献给 耶和华, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, '这举祭 要算 为你们 场上 的谷,又如满 酒醡的酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, '这样,你们 从 以色列 人 中所 得的 十分之一 也要 作举祭 献给 耶和华,从这十分之一中,将 所献给耶和华 的举祭 归给 祭司 亚伦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, '奉给你们的一切 礼物,要从其中 将 至好的,就是 分别为圣的,献给 耶和华为 举祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, '所以你要对利未人 说:你们从其中 将 至好的 举起,这就算为 你们 场上 的粮,又如酒醡 的酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, '你们 和你们家属 随 处 可以吃;这原 是 你们的 赏赐,是酬 你们在会 幕 里办事的劳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, '你们从其中 将 至好的 举起,就不致 因 这物担 罪。你们不可 亵渎 以色列 人 的圣物,免得 死亡。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, '耶和华 晓谕 摩西、 亚伦 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, '「耶和华 命定 律法 中的一条律例 乃是 这样 说:你要吩咐 以色列 人,把一只 没有 残疾、 未曾 负 轭、纯 红 的母牛 牵 到你这里来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, '交 给 祭司 以利亚撒;他必牵 到 营 外,人就把牛 宰 在他面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, '祭司 以利亚撒 要用指头 蘸 这牛的血,向 会 幕 前面 弹 七 次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, '人要在他眼前 把 这母牛 焚烧; 牛的皮、 肉、 血、 粪 都要焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, '祭司 要 把 香柏 木、牛膝草、朱红色 线 缐 都丢 在 烧 牛 的火中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, '祭司 必不洁净 到 晚上, 要洗 衣服,用水 洗 身,然后 可以进 营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, '烧 牛 的人必不洁净 到 晚上,也要 洗 衣服,用水 洗 身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, '必有一个洁净 的人 收起 母牛 的灰,存 在营 外 洁净 的地方, 为以色列 会众 调做 除污秽 的水。这本是 除罪的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, '收起 母牛 灰 的人必不洁净 到 晚上,要洗 衣服。这要 给以色列 人 和寄居 在他们中间 的外人 作为永远 的定例。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, '「摸了 人 死 尸的,就必七 天 不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, '那人 到第三 天 要用这除污秽的水洁净 自己,第七 天 就洁净了。他若 在第三 天 不 洁净自己,第七 天 就不 洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, '凡 摸了 人 死 尸、不 洁净自己的,就玷污了 耶和华 的帐幕,这 人 必从以色列 中剪除;因为 那除污秽 的水 没有 洒 在他身上,他就为 不洁净,污秽 还 在他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, '「 人 死 在帐棚 里的条例 乃是这样:凡 进 那帐棚的,和一切 在帐棚里的,都必七 天 不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, '凡 敞口 的器皿,就是 没有 扎 上 盖的,也是 不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, '无论 何人 在 田野 里 摸了 被刀 杀的,或是 尸首,或是 人 的骨头,或是 坟墓,就要七 天 不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, '要为这不洁净的人 拿 些烧成的 除罪 灰 放 在 器皿里,倒上 活 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, '必当有一个洁净 的人 拿 牛膝草 蘸 在这水中,把水洒 在 帐棚上,和 一切 器皿 并 帐棚内 的众人身上,又洒在 摸了 骨头,或 摸了被杀的,或 摸了自死的,或 摸了坟墓的那人身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, '第三 天 和第七 天,洁净的人 要洒 水在 不洁净的人身上,第七 天 就使他成为洁净。那人要洗 衣服,用水 洗澡,到晚上 就洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, '「 但那 污秽 而不 洁净自己的,要将他 从会 中 剪除,因为 他玷污了 耶和华 的圣所。除污秽 的水 没有 洒 在他身上,他是 不洁净的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, '这要给你们 作为 永远 的定例。并且那洒 除污秽 水 的人要洗 衣服。凡摸 除污秽 水的,必不洁净 到 晚上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, '不洁净人 所 摸 的一切物 就不洁净;摸了 这物的人 必不洁净 到 晚上。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, '正 月间,以色列 全 会众 到了 寻 的旷野, 就住 在加低斯。米利暗 死 在那里,就葬 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, '会众 没 有 水喝,就聚集 攻击 摩西、 亚伦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, '百姓 向 摩西 争闹 说:「我们的弟兄 曾死 在耶和华 面前,我们恨不得 与他们同死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, '你们为何 把 耶和华 的会众 领 到 这 旷野、使我们 和牲畜 都死 在这里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, '你们为何 逼著我们出 埃及、领 我们 到 这 坏 地方呢?这地方 不好 撒种,也没有无花果树、葡萄树、石榴树,又没有 水 喝。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, '摩西、亚伦 离开  会众,到 会 幕 门口,俯伏 在 地;耶和华 的荣光 向他们 显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, '「你 拿著 杖去,和你的哥哥 亚伦 招聚 会众,在他们眼前 吩咐 磐石 发出 水来,水 就从 磐石 流出,给 会众 和 他们的牲畜 喝。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, '于 是摩西 照 耶和华 所吩咐的,从耶和华面前 取了 杖去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, '摩西、亚伦 就招聚 会众 到 磐石 前。摩西说:「你们这些背叛的人 听我说:我为你们 使水 从 这 磐石 中流出来吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, '摩西 举 手,用杖 击打 磐石 两下,就有许多 水 流出来,会众 和他们的牲畜 都喝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, '耶和华 对 摩西、 亚伦 说:「因为 你们不 信 我,不在以色列 人 眼前 尊我为圣,所以 你们必不得 领 这 会众 进 我所 赐 给他们 的地去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, '这 水名叫米利巴 水(米利巴就是争闹的意思),是因 以色列 人 向 耶和华 争闹,耶和华就在他们 面前显为圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, '摩西 从加低斯 差遣 使者 去见 以东 王,说:「你的弟兄 以色列 人这样 说:『我们所 遭遇的 一切 艰难, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, '就是我们的列祖 下到 埃及,我们在埃及 久 住;埃及人 恶待 我们的列祖 和我们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, '我们哀求 耶和华的时候,他听了 我们的声音,差遣 使者 把我们从埃及 领出来。这事你 都知道。如今,我们 在你边 界 上的城 加低斯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, '求 你容我们从你的地 经过。我们不 走 田间 和葡萄园,也不 喝 井 里的水,只走大道(原文是王 道),不 偏 左 右,直到 过了 你的境界。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, '以东 王说:「你不可 从我的地 经过,免得 我带刀 出去 攻击你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, '以色列 人 说:「我们要走大道 上去;我们 和牲畜 若 喝 你的水,必给 你价值。不 求别的,只求 你容我们步 行过去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, '以东 王说:「你们不可 经过!」就率领许多 人 出来,要用强硬 的手 攻击以色列人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, '这样,以东 王不肯 容 以色列人 从他的境界 过去。于 是他们 转去,离开 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, '以色列 全 会众 从加低斯 起行,到了 何珥 山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, '耶和华 在 附近以东 边界 的何珥 山 上晓谕 摩西、 亚伦 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, '「亚伦 要归 到他列祖(原文是本民)那里。他必 不得 入 我所 赐 给以色列 人 的地;因 为 在米利巴 水,你们违背了 我的命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, '你带 亚伦 和 他的儿子 以利亚撒 上 何珥 山, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, '把 亚伦的 圣衣 脱下来,给 他的儿子 以利亚撒 穿上;亚伦 必死 在那里,归他列祖。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, '摩西 就照 耶和华 所吩咐的 行。三人当著 会众 的眼前 上了 何珥 山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, '摩西 把 亚伦的 圣衣 脱下来,给 他的儿子 以利亚撒 穿上,亚伦 就死 在山 顶 那里。于 是摩西 和以利亚撒 下了 山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, '全 会众,就是以色列 全 家,见 亚伦 已经死了,便都为 亚伦 哀哭了 三十 天。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, '住 南地 的迦南人 亚拉得 王,听说 以色列人 从亚他林 路 来,就和以色列人 争战 ,掳了 他们几个 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, '以色列人 向耶和华 发 愿  说:「你若 将 这 民 交 付 我手,我就把 他们的城邑 尽行毁灭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, '耶和华 应允了 以色列人,把 迦南人 交付他们,他们就把迦南人 和 迦南人的城邑 尽行毁灭。那地方 的名 便叫 何珥玛(就是毁灭的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, '他们从何珥 山 起行,往红 海 那条路走,要绕过 以东 地。百姓 因这路难行,心 中甚是烦躁, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, ' 就怨讟 神 和摩西说:「你们为什么 把我们从埃及 领出来、使我们死 在旷野呢? 这里没有 粮,没有 水,我们的心 厌恶 这淡薄 的食物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, '于 是耶和华 使 火 蛇 进入 百姓中间,蛇就咬 他们。以色列人中 死了 许多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, '百姓 到 摩西那里,说:「 我们怨讟 耶和华 和你,有罪了。求你祷告 耶和华,叫 这些蛇 离开  我们。」于 是摩西 为 百姓 祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, '耶和华 对 摩西 说:「你制造 一条火蛇,挂 在 杆子上; 凡 被咬的,一望 这蛇,就必得活。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, '摩西 便制造 一条铜 蛇,挂 在 杆子上;凡 被蛇 咬的,一望 这铜 蛇 就活了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, '以色列 人 起行,安营 在阿伯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, '又从阿伯 起行,安营在以耶‧亚巴琳, 与 摩押 相对 的旷野,向日 出之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, '从那里 起行,安营 在撒烈 谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, '从那里 起行,安营 在亚嫩河 那边。这 亚嫩河是在旷野,从亚摩利 的境界 流出来的;原来 亚嫩河 是摩押 的边界,在 摩押 和 亚摩利人搭界的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, '所以 耶和华 的战  记 上说:「苏法的 哇哈伯 与 亚嫩河 的谷, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, '并 向亚珥 城 众谷 的下坡,是靠近 摩押 的境界。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, '以色列人从那里起行,到了比珥(就是井的意思)。从前 耶和华 吩咐摩西 说:「招聚 百姓,我好给 他们 水喝」,说的就是 这井。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, '当时,以色列人 唱 歌说:井啊,涌上水来!你们要向这井 歌唱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, '这井 是首领 和民中 的尊贵人 用圭 用杖 所挖 所掘的。以色列人从旷野 往玛他拿去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, '从玛他拿 到拿哈列,从拿哈列 到巴末, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, '从巴末 到摩押 地 的谷,又到那 下 望 旷野 之毘斯迦 的山顶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, '以色列人 差遣 使者 去见 亚摩利人 的王 西宏,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, '「求你容我们从你的地 经过;我们不 偏 入田间 和葡萄园,也不 喝 井里 的水,只走大道(原文是王 道),直到 过了 你的境界。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, '西宏 不 容 以色列人 从他的境界 经过, 就招聚 他的众 民 出 到旷野,要攻击 以色列人,到了 雅杂 与以色列人 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, '以色列人 用 刀 杀了他,得了 他的地,从亚嫩河 到 雅博河,直到 亚扪 人的境界,因为 亚扪 人 的境界 多有坚垒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, '以色列人 夺取 这 一切 的城邑, 也住 亚摩利人的 城邑,就是希实本 与希实本的一切 乡村。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, ' 这希实本 是 亚摩利 王 西宏 的京城;西宏 曾与摩押 的先 王 争战 ,从他手 中夺取了 全 地,直到 亚嫩河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, '所以 那些作诗歌的 说:你们来到 希实本;愿 西宏 的城 被修造,被建立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, '因为 有火 从希实本 发出,有火焰 出于 西宏 的城,烧尽 摩押 的亚珥 和亚嫩河邱坛的祭司(祭司原文是主)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, '摩押 啊,你 有祸了!基抹 的民哪,你们灭亡了!基抹的男子 逃奔,女子 被掳,交付 亚摩利 的王 西宏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, '我们射了他们;希实本 直到 底本 尽皆毁灭。我们使地变成荒场,直到 挪法;这挪法 直延到 米底巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, '这样,以色列人 就住 在亚摩利人 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, '摩西 打发 人去窥探 雅谢,以色列人就占了 雅谢的镇市,赶出 那里 的 亚摩利人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, '以色列人转回,向 巴珊 去。巴珊 王 噩 和他的众 民 都出来,在以得来 与他们交战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, '耶和华 对 摩西 说:「不要 怕 他!因 我已将他 和 他的众 民,并 他的地,都交 在你手中;你要待 他 像 从前待 住 希实本 的亚摩利 王 西宏一般。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, '于 是他们杀了 他 和 他的众子,并 他的众 民, 没有 留下 一个,就得了 他的地。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, '以色列 人 起行,在摩押 平原、约旦河 东,对著耶利哥 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, ' 以色列人 向亚摩利人 所 行的 一切事,西拨 的儿子 巴勒 都看见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, '摩押人 因 以色列民 甚多,就大大 惧怕, 心内忧急, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, ' 对 米甸 的长老 说:「现在 这众人 要把 我们四围 所有的 一概餂尽,就如牛 餂尽 田间 的草一般。」那 时 西拨 的儿子 巴勒 作摩押 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, '他差遣 使者 往 大河 边的 毘夺去,到 比珥 的儿子 巴兰 本 乡那里,召 巴兰来,说:「 有一宗民 从埃及 出来, 遮满 地 面, 与我对 居。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, ' 这 民 比我 强盛,现在 求 你来 为我 咒诅 他们,或者 我能得胜,攻打 他们,赶 出 此地。因为 我知道,你为 谁 祝福,谁就得福;你咒诅 谁,谁就受咒诅。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, ' 摩押 的长老 和米甸 的长老 手里 拿著卦金,到了 巴兰那里,将巴勒 的话 都告诉了 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, '巴兰说:「你们今夜 在这里 住宿,我必照 耶和华 所晓谕 我 的回 报 你们。」摩押 的使臣 就在 巴兰 那里住下了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, '神 临 到 巴兰那里,说:「在你这里的 人 都是谁?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, '巴兰 回答 说:「是摩押 王 西拨 的儿子 巴勒 打发 人到我这里来,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, '『 从埃及 出来 的民 遮满 地 面, 你来 为我 咒诅 他们,或者 我能 与他们 争战 ,把他们赶出去。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, '神 对 巴兰 说:「你不可 同他们 去,也不可 咒诅 那民,因为 那民 是蒙福的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, '巴兰 早晨 起来,对 巴勒 的使臣 说:「你们回 本地 去吧,因为 耶和华 不 容我 和你们同 去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, '摩押 的使臣 就起来,回 巴勒 那里去,说:「巴兰 不肯 和我们同 来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, '巴勒 又 差遣 使臣,比先前的 又多 又尊贵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, '他们到了 巴兰那里,对他 说:「西拨 的儿子 巴勒 这样 说:『求 你不容 什么事拦阻 你不到我 这里来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, '因为 我必使你得 极大 的尊荣。你向我 要 什么,我就给你什么;只求 你来 为我 咒诅 这 民。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, '巴兰 回答 巴勒 的臣仆 说:「巴勒 就是 将他满 屋 的金 银 给 我,我行 大事 小事 也不 得 越过 耶和华─我 神 的命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, '现在 我请 你们 今夜 在这里 住宿,等我得知 耶和华 还要 对我 说 什么。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, '当夜, 神 临 到 巴兰那里,说:「这些人 若 来 召 你,你就起来 同他们 去,你只要 遵行 我对你 所 说的 话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, '巴兰 早晨 起来,备上 驴,和 摩押 的使臣 一同去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, '神 因 他 去 就发了 怒;耶和华 的使者 站 在路上 敌挡 他。他 骑著 驴,有两个 仆人 跟随他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, '驴 看见 耶和华 的使者 站 在路上,手里 有拔出来 的刀, 就 从 路上 跨 进田间,巴兰 便打 驴,要叫牠回转 上路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, '耶和华 的使者 就站 在葡萄园 的窄路上;这边 有墙,那边 也有墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, '驴 看见 耶和华 的使者,就贴 靠 墙,将 巴兰 的脚 挤 伤了;巴兰又 打驴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, '耶和华 的使者 又 往前去,站 在狭窄 之处, 左 右 都没有 转折 的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, '驴 看见 耶和华 的使者,就卧 在巴兰 底下,巴兰 发 怒,用杖 打 驴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, '耶和华 叫 驴 开  口,对巴兰 说:「我向你 行了 什么,你竟 打我 这 三 次呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, '巴兰 对驴 说:「因为 你戏弄 我,我恨不能 手中 有 刀, 把你杀了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, '驴 对 巴兰 说:「我 不是 你从小时 直到 今 日 所 骑的 驴吗?我素常 向你 这样 行过吗?」巴兰说:「没有。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, '当时,耶和华 使 巴兰 的眼目 明亮,他就看见 耶和华 的使者 站 在路上,手里 有拔出来 的刀,巴兰便低头 俯伏在地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, '耶和华 的使者 对他 说:「你为 何 这 三 次 打 你的驴呢? 我 出来 敌挡你,因 你所行的,在我面前 偏僻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, '驴 看见我就 三 次 从我面前 偏过去;驴若没有 偏过去, 我早 把你 杀了,留牠 存活。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, '巴兰 对 耶和华 的使者 说:「我有罪了。 我不 知道 你 站 在路上 阻挡我; 你若 不喜欢我去,我 就转回。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, '耶和华 的使者 对 巴兰 说:「你同 这些人 去吧!你只 要说 我对你 说的 话。」于 是巴兰 同著 巴勒 的使臣 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, '巴勒 听见 巴兰 来了,就往 摩押 京城 去 迎接他;这城 是在 边 界上, 在亚嫩 河 旁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, '巴勒 对 巴兰 说:「我不是 急急地 打发 人到你 那里去召 你吗?你为何 不 到我这里 来呢?我岂 不 能 使你得尊荣吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, '巴兰 说:「 我已经到你这里 来了!现在 我岂能 擅自 说 什么呢? 神 将什么 话 传 给我,我就说 什么。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, '巴兰 和巴勒 同 行,来到基列‧胡琐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, '巴勒宰了(原文是献)牛 羊,送 给巴兰 和陪伴 的 使臣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, '到了 早晨,巴勒 领 巴兰 到 巴力 的高处;巴兰从那里 观看 以色列 营的边界。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, '巴兰 对 巴勒 说:「你在这里 给我 筑 七 座坛,为我 预备 七 只公牛,七 只公羊。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, '巴勒 照 巴兰 的话 行了。巴勒 和巴兰 在每座坛上 献 一只公牛,一只公羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, '巴兰 对巴勒 说:「你站 在 你的燔祭旁边,我且往前去,或者 耶和华 来 迎见我。他指示我 什么,我必告诉 你。」于 是巴兰上 一净光的高处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, '神 迎见 巴兰;巴兰说:「我预备了 七 座坛,在每座坛上 献了 一只公牛,一只公羊。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, '耶和华 将话 传给 巴兰,又说:「你回 到 巴勒那里,要如此如此 说。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, '他就回 到巴勒那里,见 他 同摩押 的使臣 都 站 在 燔祭旁边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, '巴兰便题起 诗歌 说:巴勒 引 我出 亚兰,摩押 王 引我出东 山,说:来啊,为我 咒诅 雅各;来啊,怒骂 以色列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, '神 没有 咒诅的,我焉能 咒诅?耶和华 没有 怒骂的,我焉能 怒骂? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, ' 我从高 峰 看他,从小山 望他; 这是独 居 的民,不 列 在万民中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, '谁 能数点 雅各 的尘土?谁能计算 以色列 的四分之一?我 愿 如义人 之死 而死;我愿  如义人之 终而终。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, '巴勒 对 巴兰 说:「你向我 做的 是什么事呢?我领你 来咒诅 我的仇敌,不料,你竟为他们祝福。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, '他回答 说:「耶和华 传 给我的话, 我能不 谨慎 传说吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, '巴勒 说:「求 你同我 往 别 处 去, 在那里 可以看见他们;你不能 全 看见,只能 看见 他们边界上的人。在那里 要为我 咒诅他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, '于 是领 巴兰到了琐腓 田,上了 毘斯迦 山顶,筑了 七 座坛;每座坛上 献 一只公牛,一只公羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, '巴兰对 巴勒 说:「你站 在 这 燔祭旁边,等我 往那边 去迎见耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, '耶和华 临 到 巴兰那里,将话 传 给他;又说:「你回 到 巴勒那里,要如此如此 说。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, '他就回 到巴勒那里,见他 站 在 燔祭旁边;摩押 的使臣 也和他在一处。巴勒 问他 说:「耶和华 说了 什么话呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, '巴兰就题 诗歌 说:巴勒,你起来 听;西拨 的儿子,你听 我言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, '神 非 人,必不致说谎,也非人 子,必不致后悔。他 说话 岂不 照著行呢?他发言 岂不 要成就呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, ' 我奉命 祝福; 神也曾赐福,此事我不能 翻转。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, '他未 见 雅各 中有罪孽,也未 见 以色列 中有奸恶。耶和华─他的 神 和他同在;有欢呼 王 的声音在他们中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, '神 领他们 出埃及;他们 似乎有野牛 之力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, '断 没有 法术 可以害雅各,也没有 占卜 可以害以色列。现在 必有人论及雅各,就是论及以色列 说: 神 为他行了 何等的大事! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, ' 这民 起来,仿佛母狮,挺身,好像公狮,未曾 吃 野食,未曾喝 被伤者 之血,决不 躺卧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, '巴勒 对 巴兰 说:「你一点 不要 咒诅他们,也 不要 为他们祝福。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, '巴兰 回答 巴勒 说:「我岂不是 告诉 你 说『凡 耶和华 所 说的, 我必须遵行』吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, '巴勒 对 巴兰 说:「 来吧,我领你 往 别 处去,或者 神 喜欢 你在那里 为我 咒诅他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, '巴勒 就领 巴兰 到 那下 望 旷野 的毘珥 山顶上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, '巴兰 对 巴勒 说:「你在这里 为我 筑 七 座坛,又在这里 为我 预备 七 只公牛,七 只公羊。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, '巴勒 就照 巴兰 的话 行,在每座坛上 献 一只公牛,一只公羊。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, '巴兰 见 耶和华 喜欢 赐福 与 以色列,就不 像 前两次 去 求 法术,却 面 向 旷野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, '巴兰 举 目,看见 以色列人 照著支派 居住。 神 的灵 就临 到他身上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, '他便题起 诗歌 说:比珥 的儿子 巴兰 说,眼目 闭住(或译:睁开 )的人 说, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, '得听 神 的言语,得见 全能者 的异象,眼目 睁开  而仆倒 的人 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, '雅各啊,你的帐棚 何等 华美!以色列啊,你的帐幕何其华丽! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, '如接连 的山谷,如河 旁 的园子,如耶和华 所栽 的沉香树,如水 边 的香柏木。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, '水 要从他的桶里 流出;种子 要撒在多 水之处。他的王 必超 过亚甲;他的国 必要振兴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, '神 领他出 埃及;他 似乎有野牛 之力。他要吞吃 敌 国,折断 他们的骨头,用箭 射透他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, '他蹲 如公狮,卧 如母狮,谁 敢惹他?凡给你祝福的,愿 他蒙福;凡咒诅你的,愿 他受咒诅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, '巴勒 向 巴兰 生 气,就拍起 手来, 对 巴兰 说:「我召你 来为我咒诅 仇敌,不料,你这 三 次 竟为他们 祝福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, '如今 你 快回 本地 去吧!我想 使你得 大尊荣, 耶和华 却阻止你 不得尊荣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, '巴兰 对 巴勒 说:「我岂 不是 对 你所 差遣 到我 那里的使者 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, '『巴勒 就是 将他满 屋 的金 银 给 我,我也不 得 越过 耶和华 的命,凭自己的心意 行 好行 歹。耶和华 说 什么,我就要说 什么』?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, '「现在 我要回 本族去。你来,我告诉你 这 民 日 后 要怎样 待 你的民。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, '他就题起 诗歌 说:比珥 的儿子 巴兰 说:眼目 闭住(或译:睁开 )的人 说, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, '得听 神 的言语,明白 至高者 的意旨,看见 全能者 的异象,眼目 睁开  而仆倒 的人说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, '我看他 却不 在现时;我望他 却不 在近日。有星 要出 于 雅各,有杖 要兴 于 以色列,必打破 摩押 的四角,毁坏 扰乱之 子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, '他必得以东 为 基业,又得仇敌 之地西珥 为 产业;以色列 必行事 勇敢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, '有一位出于 雅各的,必掌大权;他要除灭 城中 的余 馀民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, '巴兰观看 亚玛力,就题起 诗歌 说:亚玛力 原为诸国 之首,但他终 必 沉沦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, '巴兰观看 基尼人,就题起 诗歌 说:你的住处 本是坚固;你的窝巢 做 在岩穴中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, '然而 基尼 必 至衰微,直到 亚述 把你掳去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, '巴兰又题起 诗歌 说:哀哉! 神 行这事,谁 能得活? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, '必有人乘船 从基提 界而来,苦害 亚述,苦害 希伯;他 也 必至 沉沦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, '于 是巴兰 起来,回 他本地 去;巴勒 也 回去了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, '以色列 人住 在什亭,百姓 与 摩押 女子 行起 淫乱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, '因为这女子叫 百姓来,一同给她们的神 献祭,百姓 就吃她们的祭物,跪拜 她们的神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, '以色列人与巴力‧毘珥 连合,耶和华 的怒气 就向以色列人 发作。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, '耶和华 吩咐 摩西 说:「 将 百姓 中所有的 族长 在我 面前对著 日头 悬挂,使我 向以色列人 所发 的怒气 可以消了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, '于 是摩西 吩咐 以色列 的审判官 说:「凡 属你们的人,有与巴力‧毘珥 连合的,你们各人 要把他们杀了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, '摩西 和以色列 全 会众 正在会 幕 门 前哭泣的时候,谁知,有以色列 中的一个人,当他们 眼前,带著 一个米甸女人 到 他弟兄 那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, '祭司 亚伦的孙子,以利亚撒 的儿子 非尼哈 看见了,就从会 中 起来,手 里拿 著枪, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, '跟随 那以色列 人 进 亭子 里去,便将 以色列 人 和 那女人 由 腹 中刺透。这样,在 以色列 人 中瘟疫 就止息了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, '那时遭瘟疫 死的,有 二万 四 千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, '「祭司 亚伦 的孙子,以利亚撒 的儿子 非尼哈,使 我向 以色列 人 所发的怒 消了;因他在他们中间,以 我的忌邪 为心,使我不 在忌邪 中把 他们 除灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, '因此,你要说:『 我将 我平安 的约 赐 给他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, '这约要 给他 和他的后裔,作为永远 当祭司职任 的约;因 他为 神 有忌邪的心,为 以色列 人 赎罪。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, '那 与 米甸女人 一同被杀 的以色列 人,名 叫心利,是撒路 的儿子,是西缅 一个宗 族 的首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, '那被杀 的米甸 女人,名 叫哥斯比,是苏珥 的女儿;这苏珥是 米甸 一个宗 族 的首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, '「你要扰害 米甸人,击杀 他们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, '因为 他们 用诡计 扰害 你们,在 毘珥 的事 上和 他们的姊妹、米甸 首领 的女儿 哥斯比 的事上,用这诡计 诱惑 了你们;这哥斯比,当瘟疫 流行的日子,因 毘珥 的事 被杀了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, ' 瘟疫 之后,耶和华 晓谕 摩西 和 祭司 亚伦 的儿子 以利亚撒 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, '「你们要将 以色列 全 会众,按他们的宗 族,凡以色列中 从 二十 岁 以外、 能出去 打仗的,计算 总数。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, '摩西 和祭司 以利亚撒 在摩押 平原 与耶利哥 相对 的约旦河 边向以色列人 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, '「将你们中间从 二十 岁 以外的计算总数」;是照 耶和华 吩咐 出 埃及 地 的摩西 和以色列 人 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, '以色列 的长子 是流便。流便 的众子:属哈诺的,有哈诺 族;属法路的,有法路 族; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, '属希斯伦的,有希斯伦 族;属迦米的,有迦米 族; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, '这就是 流便 的各族;其中被数的,共有 四万 三 千 七 百 三十名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, '法路 的儿子 是以利押。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, '以利押 的众子 是尼母利、大坍、亚比兰。这 大坍、亚比兰,就是 从会 中选召的,与可拉 一党 同向 耶和华 争闹 的时候也向 摩西、 亚伦 争闹; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, '地 便开  口 吞了 他们,和 可拉、可拉的党类 一同死亡。那时火 烧灭了 二百 五十 个人;他们就作了 警戒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, '然而可拉 的众子 没有 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, '按著家族,西缅 的众子:属尼母利的,有尼母利 族;属雅悯的,有雅悯 族;属雅斤的,有雅斤 族; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, '属谢拉的,有谢拉 族;属扫罗的,有扫罗 族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, '这就是 西缅 的各族,共有二万 二 千 二百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, '按著家族,迦得 的众子:属洗分的,有洗分 族;属哈基的,有哈基 族;属书尼的,有书尼 族; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, '属阿斯尼的,有阿斯尼 族;属以利的,有以利 族; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, '属亚律的,有亚律 族;属亚列利的,有亚列利 族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, '这就是 迦得 子孙 的各族,照他们中间被数的,共有四 万 零五 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, '犹大 的儿子 是珥 和俄南。这珥 和俄南 死 在迦南 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, '按著家族, 犹大 其余 馀的众子:属示拉的,有示拉 族;属法勒斯的,有法勒斯 族;属谢拉的,有谢拉 族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, ' 法勒斯 的儿子:属希斯伦的,有希斯伦 族;属哈母勒的,有哈母勒 族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, '这就是 犹大 的各族,照他们中间被数的,共有七 万六 千 五 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, '按著家族,以萨迦 的众子:属陀拉的,有陀拉 族;属普瓦的,有普瓦 族; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, '属雅述的,有雅述 族;属伸仑 的,有伸仑  族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, '这就是 以萨迦 的各族,照他们中间被数的,共有六 万四 千 三 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, '按著家族,西布伦 的众子:属西烈的,有西烈 族;属以伦的,有以伦 族;属雅利的,有雅利 族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, '这就是 西布伦 的各族,照他们中间被数的,共有六 万 零五 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, '按著家族,约瑟 的儿子 有玛拿西、以法莲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, '玛拿西 的众子:属玛吉的,有玛吉族;玛吉 生 基列;属基列的,有基列 族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, ' 基列 的众子:属伊以谢的,有伊以谢 族;属希勒的,有希勒 族; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, '属亚斯烈的,有亚斯烈 族;属示剑的,有示剑 族; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, '属示米大的,有示米大 族;属希弗的,有希弗 族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, '希弗 的儿子:西罗非哈 没 儿子,只有 女儿。西罗非哈 女儿 的名字 就是玛拉、挪阿、曷拉、密迦、得撒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, '这就是 玛拿西 的各族;他们中间被数的,共有五 万二 千 七 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, '按著家族, 以法莲 的众子:属书提拉的,有书提拉 族;属比结的,有比结 族;属他罕的,有他罕 族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, ' 书提拉 的众子:属以兰的,有以兰 族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, '这就是 以法莲 子孙 的各族,照他们中间被数的,共有三 万二 千 五 百名。按著家族,这都是 约瑟 的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, '按著家族,便雅悯 的众子:属比拉的,有比拉 族;属亚实别的,有亚实别 族;属亚希兰的,有亚希兰 族; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, '属书反的,有书反 族;属户反的,有户反 族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, '比拉 的众子 是 亚勒、乃幔。属亚勒的,有亚勒 族;属乃幔的,有乃幔 族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, '按著家族,这就是 便雅悯 的子孙,其中被数的,共有四 万五 千 六 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, '按著家族, 但 的众子:属书含的,有书含 族。按著家族,这就是 但 的各族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, '照其中被数的,书含 所有的各 族,共有六 万四 千 四 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, '按著家族,亚设 的众子:属音拿的,有音拿 族;属亦施韦的,有亦施韦 族;属比利亚的,有比利亚 族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, '比利亚 的众子:属希别的,有希别 族;属玛结的,有玛结 族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, '亚设 的女儿 名叫 西拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, '这就是 亚设 子孙 的各族,照他们中间被数的,共有五 万三 千 四 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, '按著家族,拿弗他利 的众子:属雅薛的,有雅薛 族;属沽尼的,有沽尼 族; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, '属耶色的,有耶色 族;属示冷的,有示冷 族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, '按著家族,这就是 拿弗他利 的各族;他们中间被数的,共有四 万五 千 四 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, '以色列 人 中被数的,共有 六 十万 零一千 七 百 三十名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, '「你要按著人名 的数目 将地 分 给这些人 为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, '人多的,你要把产业 多分给他们;人少的,你要把产业 少分给他们;要照 被数的人数,把产业 分给 各人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, '虽是这样,还要 拈阄 分 地。他们要按著祖宗 各支派 的名字 承受为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, '要按著 所拈的阄, 看人数多,人数少,把产业 分给他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, ' 利未人,按著他们的各族 被数的:属革顺的,有革顺 族;属哥辖的,有哥辖 族;属米拉利的,有米拉利 族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, ' 利未 的各族 有立尼 族、希伯伦 族、玛利 族、母示 族、可拉 族。哥辖 生 暗兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, '暗兰的 妻 名 叫约基别,是 利未 女子,生 在埃及。她给暗兰 生了 亚伦、 摩西,并 他们的姊姊 米利暗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, '亚伦 生 拿答、 亚比户、 以利亚撒、 以他玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, '拿答、亚比户 在耶和华 面前 献 凡 火 的时候就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, '利未人中,凡 一个月 以外、被数 的男丁,共有 二 万三 千。他们本来 没有 数 在以色列 人 中;因为 在以色列 人 中,没有 分给 他们 产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, '这些就是 被摩西 和祭司 以利亚撒 所 数的;他们在摩押 平原 与耶利哥 相对 的约旦河 边数点 以色列 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, '但被数 的人中,没 有 一个 是摩西 和祭司 亚伦 从前在西奈 的旷野 所 数的 以色列 人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, '因为 耶和华 论到他们 说:「他们必要 死 在旷野。」所以,除了 耶孚尼 的儿子 迦勒 和嫩 的儿子 约书亚以外,连 一个人 也没有 存留。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, '属约瑟 的儿子 玛拿西 的各族,有玛拿西 的玄孙,玛吉 的曾孙,基列 的孙子,希弗 的儿子 西罗非哈 的女儿, 名叫 玛拉、挪阿、曷拉、密迦、得撒。她们前来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, '站 在会 幕 门口,在摩西 和祭司 以利亚撒,并众首领 与全 会众 面前,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, '「我们的父亲 死 在旷野。他 不与 可拉 同党 聚集 攻击 耶和华,是 在自己罪 中死的;他 也没 有 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, '为什么 因 我们的父亲 没有 儿子 就把他的名 从他族 中 除掉呢?求你们在我们父亲 的弟兄 中 分 给我们 产业。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, '于 是,摩西 将 她们的案件 呈到 耶和华 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, '「西罗非哈 的女儿 说 得有理。你定要 在她们父亲 的弟兄 中,把地 分 给她们 为业;要将 她们父亲的 产业 归给 她们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, '你也要晓谕 以色列 人 说:『人 若 死了 没有 儿子,就要把 他的产业 归给 他的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, '他若 没有 女儿,就要把 他的产业 给 他的弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, '他若 没有 弟兄,就要把 他的产业 给 他父亲 的弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, '他父亲 若 没有 弟兄,就要把 他的产业 给 他 族中 最近 的亲属,他便要得 为业。』这要作 以色列 人 的律例 典章,是照 耶和华 吩咐 摩西的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, '耶和华 对 摩西 说:「你上 这 亚巴琳 山,观看 我所 赐 给以色列 人 的地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, '看了以后,你 也 必归 到你列祖(原文是本民)那里,像 你哥哥 亚伦 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, '因为 你们在寻 的旷野,当会众 争闹的时候,违背 了我的命,没有在涌水之地、会众眼前 尊我为圣。」(这 水就是寻 的旷野 加低斯 米利巴 水。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, '摩西 对 耶和华 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, '「愿 耶和华 万 人 之灵的 神,立 一个人 治理 会众, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, '可以在他们面前 出 入,也可以 引 导他们,免得 耶和华 的会众如同 没有 牧人 的羊群一般。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, '耶和华 对 摩西 说:「嫩 的儿子 约书亚 是 心中 有圣灵 的;你将他 领来,按 手 在他头上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, '使他 站 在祭司 以利亚撒 和全 会众 面前,嘱咐 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, '又将你的尊荣 给 他几分,使 以色列 全 会众 都听从他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, '他要站 在祭司 以利亚撒 面前;以利亚撒要凭乌陵 的判断,在耶和华 面前 为他 求问。他 和 以色列 全 会众 都 要遵 以利亚撒 的命 出 入。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, '于 是摩西 照 耶和华 所吩咐 的将 约书亚 领来,使他站 在祭司 以利亚撒 和全 会众 面前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, '按 手 在他头上,嘱咐他,是照 耶和华 藉 借 摩西 所说的话。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, '「你要吩咐 以色列 人 说:『 献给我的供物,就是献给我作馨 香 火 祭的食物,你们要按 日期 献 给我』; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, '又要对他们 说: 你们要献 给耶和华 的火祭,就是 没有残疾、一岁 的公羊羔,每日 两只,作为常 献的燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, '早晨 要献 一 只,黄昏 的时候 要献 一 只; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, '又用细面 麺 伊法 十分之一,并捣成的 油 一欣 四分之一,调和 作为素祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, '这是西奈 山 所命定 为常 献的燔祭,是献给耶和华 为馨 香 的火祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, '为这一 只羊羔,要同献奠祭 的酒一欣 四分之一。在圣所中,你要将醇酒 奉 给耶和华 为奠祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, '晚上,你要献 那一只 羊羔,必照早晨 的素祭 和同献的奠祭献上,作为馨 香 的火祭,献 给耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, '「当安息 日,要献两 只没有残疾、一 岁 的公羊羔,并用调 油 的细面 麺 伊法十分 之二 为素祭,又将同献的奠祭献上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, '这是每 安息日 献的燔祭;那常 献的燔祭 和同献的奠祭 在外。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, '「每月 朔,你们要将两只 公牛 犊,一 只公绵羊,七 只没有残疾、一岁 的公羊羔,献 给耶和华 为燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, '每只 公牛 要用调 油 的细面 麺 伊法十分 之三 作为素祭;那只 公羊 也用调 油 的细面 麺 伊法十分 之二 作为素祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, '每只 羊羔 要用调 油 的细面 麺 伊法十分之一 作为素祭 和馨香 的燔祭,是献给耶和华 的火祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, '一只公牛 要 奠酒 半 欣,一只公羊 要奠酒 一欣 三分之一,一只羊羔 也奠酒一欣 四分之一。这是 每 月 的燔祭,一年 之中要月月如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, '又要将一 只公山羊 为赎罪祭,献给耶和华;要献 在常 献的燔祭 和同献的奠祭 以外。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, '「正 月 十 四 日 是耶和华的 逾越节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, '这 月 十 五 日 是节期,要吃 无酵饼 七 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, '第一 日 当有圣 会;什么 劳碌 的工 都不可 做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, '当将公牛 犊 两只,公绵羊 一只,一 岁 的公羊羔 七只,都要 没有残疾的,用火 献 给耶和华 为燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, '同献的素祭 用调 油 的细面 麺;为一只公牛 要献 伊法十分 之三;为一只公羊 要献伊法十分 之二; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, '为那七 只羊羔,每 只 要献 伊法十分之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, '并献一 只公山羊 作赎罪祭,为你们 赎罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, '你们献 这些,要在早晨 常 献的燔祭 以外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, '一连七 日,每日 要照这例 把馨 香 火祭 的食物 献 给耶和华,是在常 献 的燔祭 和同献的奠祭 以外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, '第七 日 当有 圣 会,什么 劳碌 的工 都不可 做。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, '「七七节 庄稼初熟,你们献 新 素祭 给耶和华 的日子,当有 圣 会;什么 劳碌 的工 都不可 做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, '只要将公牛 犊 两只,公绵羊 一只,一岁 的公羊羔 七只,作为馨 香 的燔祭 献 给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, '同献的素祭 用调 油 的细面 麺;为每只 公牛 要献伊法十分 之三;为一 只公羊 要献伊法十分 之二; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, '为那七 只羊羔,每 只 要献伊法十分之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, '并献一 只公 山羊 为你们 赎罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, '这些,你们要献 在常 献的燔祭 和同献的素祭 并同献的奠祭 以外,都要 没有残疾的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, '「七 月 初 一日,你们 当有 圣 会;什么 劳碌 的工 都不可 做,是你们 当守为 吹 角的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, '你们要将公 牛 犊 一只,公绵羊 一只,没有残疾、一 岁 的公羊羔 七只,作为馨 香 的燔祭 献 给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, '同献的素祭 用调 油 的细面 麺;为一只公牛 要献伊法十分 之三;为一只公羊 要献伊法十分 之二; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, '为那七只 羊羔,每只 要献伊法十分 之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, '又献一只 公 山羊 作赎罪祭,为你们 赎罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, '这些是在月 朔的燔祭 和同献的素祭,并常 献的燔祭 与同献的素祭,以及照例 同献的奠祭 以外,都作为馨 香 的火祭 献给耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, '「 七 月 初十日,你们 当有 圣 会;要刻苦 己心,什么 工 都不可 做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, '只要将公 牛 犊 一只,公绵羊 一只,一 岁 的公羊羔 七只,都要 没有残疾的,作为馨香 的燔祭 献 给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, '同献的素祭 用调 油 的细面 麺:为一只公牛 要献伊法十分 之三;为一 只公羊 要献伊法十分 之二; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, '为那七 只羊羔,每只 要献伊法十分 之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, '又献一 只公 山羊 为赎罪祭。这是在赎罪祭 和常 献的燔祭,与同献的素祭 并同献的奠祭 以外。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, '「七 月 十 五 日,你们 当有 圣 会;什么 劳碌 的工 都不可 做,要向耶和华 守 节 七 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, '又要将公 牛 犊 十 三只,公绵羊 两只,一 岁 的公羊羔 十 四只,都要 没有残疾的,用火 献 给耶和华 为馨香 的燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, '同献的素祭 用调 油 的细面 麺;为那十 三 只公牛,每只 要献伊法十分 之三;为那两 只公羊,每只 要献伊法十分 之二; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, '为那十 四 只羊羔,每只 要献伊法十分 之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, '并献一 只公 山羊 为赎罪祭,这是在常 献的燔祭 和同献的素祭 并同献的奠祭 以外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, '「第二 日 要献公 牛 犊 十 二只,公绵羊 两只,没有残疾、一 岁 的公羊羔 十 四只; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, '并为公牛、公羊,和羊羔,按数 照例,献同献的素祭 和同献的奠祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, '又要献一 只公 山羊 为赎罪祭。这是在常 献的燔祭 和同献的素祭 并同献的奠祭 以外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, '「第三 日 要献公牛 十 一只,公羊 两只,没有残疾、一 岁 的公羊羔 十 四只; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, '并为公牛、公羊,和羊羔,按数 照例,献同献的素祭 和同献的奠祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, '又要献一 只公山羊 为赎罪祭。这是在常 献的燔祭 和同献的素祭 并同献的奠祭 以外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, '「第四 日 要献公牛 十只,公羊 两只,没有残疾、一 岁 的公羊羔 十 四只; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, '并为公牛、公羊,和羊羔,按数 照例,献同献的素祭 和同献的奠祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, '又要献一 只公 山羊 为赎罪祭。这是在常 献的燔祭 和同献的素祭 并同献的奠祭 以外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, '「第五 日 要献公牛 九只,公羊 两只,没有残疾、一 岁 的公羊羔 十 四只; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, '并为公牛、公羊,和羊羔,按数 照例,献同献的素祭 和同献的奠祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, '又要献一 只公山羊 为赎罪祭。这是在常 献的燔祭 和同献的素祭 并同献的奠祭 以外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, '「第六 日 要献公牛 八只,公羊 两只,没有残疾、一 岁 的公羊羔 十 四只; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, '并为公牛、公羊,和羊羔,按数 照例,献同献的素祭 和同献的奠祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, '又要献一 只公山羊 为赎罪祭。这是在常 献的燔祭 和同献的素祭 并同献的奠祭 以外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, '「第七 日 要献公牛 七只,公羊 两只,没有残疾、一 岁 的公羊羔 十 四只; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, '并为公牛、公羊,和羊羔,按数 照例,献同献的素祭 和同献的奠祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, '又要献一 只公山羊 为赎罪祭。这是在常 献的燔祭 和同献的素祭 并同献的奠祭 以外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, '「第八 日 你们 当有 严肃会;什么 劳碌 的工 都不可 做; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, '只要将公牛 一只,公羊 一只,没有残疾、一 岁 的公羊羔 七 只作火祭,献 给耶和华 为馨香 的燔祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, '并为公牛、公羊,和羊羔,按数 照例,献同献的素祭 和同献的奠祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, '又要献一 只公山羊 为赎罪祭。这是在常 献的燔祭 和同献的素祭 并同献的奠祭 以外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, '「这些 祭要在你们的节期 献 给耶和华,都在所许的愿  并甘心所献的 以外,作为你们的燔祭、素祭、奠祭,和平安祭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, '于 是,摩西 照耶和华 所 吩咐 他 的一切 话告诉 以色列 人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, '摩西 晓谕 以色列 各支派 的首领 说:「耶和华 所 吩咐 的 乃是这样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, '人 若 向耶和华 许 愿  或 起 誓,要约 束 自己,就不可 食 言,必要按口中 所出的 一切 话行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, '女子 年幼、还在父 家的时候,若 向耶和华 许 愿 ,要约 束自己, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, '她父亲 也听见 她所 许的愿  并约束 自己 的话, 却向她 默默不言,她所 许的愿 并 约束 自己 的话 就都 要为定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, '但她父亲 听见 的日子 若 不应承 她 所许的愿 和 约束 自己 的话,就都 不得 为定;耶和华 也必赦免 她,因为 她父亲 不应承。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, '她若 出了 嫁,有愿  在身,或是 口中出了 约束 自己 的冒失话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, '她丈夫 听见 的日子,却向她 默默不言,她所许 的愿 并 约束 自己 的话 就都要为定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, '但她丈夫 听见 的日子,若 不应承,就算废了 她所 许 的愿  和 她出口 约束 自己 的冒失话;耶和华 也必赦免 她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, '寡妇 或是被休 的妇人所许的愿 ,就是 她约束 自己的话,都要为定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, '她若 在丈夫 家里 许了愿  或 起了誓,约 束 自己, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, '丈夫 听见,却向她 默默不言,也没有 不应承,她所许的 愿 并 约束 自己 的话 就都 要为定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, '丈夫 听见 的日子,若 把 这两样全 废了,妇人口中 所许 的愿  或是约束自己 的话 就都 不得 为定,因她丈夫 已经把这两样废了;耶和华 也必赦免 她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, '凡 她所许的愿  和 刻苦 约束 自己 所起的誓,她丈夫 可以坚定, 也可以废去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, '倘若 她丈夫 天 天 向她 默默 不言,就算是坚定 她所许的愿  和 约束 自己的话;因 丈夫听见 的日子 向她 默默不言,就使 这两样坚定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, '但她丈夫听见 以后,若 使 这两样全 废了,就要担当 妇人的罪孽。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, '这是 丈夫 待 妻子,父亲 待 女儿,女儿年幼、还在父 家,耶和华 所 吩咐 摩西 的律例。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, '耶和华 吩咐 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, '「你要在 米甸人 身上报 以色列 人 的仇,后来 要归 到你列祖(原文是本民)那里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, '摩西 吩咐 百姓 说:「要从你们中间 叫人 带兵器 出去攻击 米甸,好在米甸人 身上为耶和华 报 仇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, '从以色列 众 支派中,每支派 要打发 一千人 去打仗。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, '于 是从以色列 千万人中,每支派 交出 一千人,共一 万二 千人,带著兵器 预备打仗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, '摩西 就打发 每支派 的一千人 去打仗,并打发 祭司 以利亚撒 的儿子 非尼哈同去;非尼哈手 里拿著圣所的 器皿 和吹大声 的号筒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, '他们就照 耶和华 所吩咐 摩西的,与 米甸人 打仗,杀了 所有的 男丁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, '在 所杀的人中,杀了 米甸 的五 王,就是 以未、 利金、 苏珥、 户珥、 利巴,又用刀 杀了 比珥 的儿子 巴兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, '以色列 人 掳了 米甸人的 妇女 孩子,并将他们的 牲畜、 羊群,和 所有的 财物 都夺了来,当作掳物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, '又用火 焚烧 他们所住 的城邑 和 所有的 营寨, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, '把 一切 所夺的、 所掳的,连人 带牲畜 都带了去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, '将 所掳的人, 所夺的牲畜、 财物,都带 到 摩押 平原, 在 约旦河 边与耶利哥 相对的 营盘,交给 摩西 和 祭司 以利亚撒,并 以色列 的会众。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, '摩西 和祭司 以利亚撒,并会众 一切的 首领,都出 到 营 外 迎接他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, '摩西 向 打 仗 回来 的军 长,就是千 夫长、百 夫长,发怒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, ' 对他们 说:「你们要存留 这一切 妇女 的活命吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, ' 这些妇女 因巴兰 的计谋,叫 以色列 人 在 毘珥 的事上 得 罪 耶和华,以致耶和华 的会众 遭遇 瘟疫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, '所以,你们要 把一切 的男 孩 和所有 已嫁 的女子 都杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, '但 女 孩子中,凡 没有 出嫁的,你们 都可以存留她的活命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, '你们 要在营 外 驻扎 七 日;凡 杀了 人的,和一切 摸了 被杀的, 并你们所掳来的人口,第三 日,第七 日,都要洁净自己, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, '也要因一切的 衣服、 皮 物、 山羊 毛织的物,和各样的 木 器,洁净自己。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, '祭司 以利亚撒 对 打仗 回来 的兵 丁 说:「耶和华 所 吩咐 摩西 律法 中的条例 乃是这样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, ' 金、 银、 铜、 铁、 锡、 铅, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, '凡 能见 火的,你们要叫它经 火 就为洁净,然而 还要用除污秽的 水 洁净它;凡 不能 见 火的,你们要叫它过 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, '第七 日,你们要洗 衣服,就为洁净,然后 可以进 营。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, '「你 和祭司 以利亚撒,并会众 的各族 长,要计算 所掳来 的人口 和牲畜 的总数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, '把 所掳来的 分作两半:一半 归与出去 打仗 的精 兵,一半 归与全 会众。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, '又要从 出去 打仗所得的 人口、 牛、 驴、 羊群中,每五 百 取一,作为贡物 奉 给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, '从他们一半之中,要取出来 交 给祭司 以利亚撒,作为耶和华 的举祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, '从以色列 人 的一半之中,就是从 人口、 牛、 驴、 羊群、各样 牲畜中,每 五十 取 一,交 给看守 耶和华 帐幕 的利未人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, '于 是摩西 和祭司 以利亚撒 照 耶和华 所吩咐 摩西 的行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, '除了兵 丁 所 夺的 财物 以外,所掳来的: 羊 六 十 七 万 五 千只; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, '牛 七 万二 千只; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, '驴 六 万一 千匹; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, ' 女人 共 三 万二 千 口,都是 没有 出嫁的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, '出去 打仗 之人的分,就是 他们所得的那一半,共计 羊 三 十 三 万 七 千 五 百只, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, '从其中归耶和华 为贡物的,有 六 百 七十 五只; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, '牛 三 万六 千只,从其中归耶和华 为贡物的,有七十 二只; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, '驴 三 万 零五 百匹,从其中归耶和华 为贡物的,有六十 一匹; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, '人 一万 六 千 口,从其中归耶和华 的,有三十 二 口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, '摩西 把 贡物,就是归与耶和华 的举祭,交 给祭司 以利亚撒,是照 耶和华 所吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, '以色列 人 所得的那一半,就是 摩西 从 打仗 的人 取来分给他们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, '(会众 的那一半 有: 羊 三 十 三 万 七 千 五 百只; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, '牛 三万 六 千只; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, '驴 三 万 零五 百匹; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, '人 一万 六 千 口。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, '无论是 人口是 牲畜, 摩西 每 五十 取 一,交 给看 守 耶和华 帐幕 的利未人,是照 耶和华 所吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, '带领千 军 的各军长,就是 千 夫长、百 夫长,都近前来 见 摩西, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, '对 他 说:「 仆人 权下 的兵 已经计算 总数,并不 短少 一人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, '如今我们将 各人 所 得的 金器,就是脚链子、镯子、打印的戒指、耳环、手钏,都送来 为耶和华 的供物,好在耶和华 面前 为 我们的生命 赎罪。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, '摩西 和祭司 以利亚撒 就收了 他们的 金子,都是 打成的 器皿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, ' 千 夫长、 百 夫长 所 献 给耶和华 为举祭的 金子 共有 一万 六 千 七 百 五十 舍客勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, '各 兵 丁 都为自己 夺了财物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, '摩西 和祭司 以利亚撒 收了 千 夫长、百夫长的 金子,就带 进 会 幕,在耶和华 面前 作为以色列 人 的纪念。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, '流便 子孙 和迦得 子孙 的牲畜 极其 众多;他们看见 雅谢 地 和 基列 地 是可牧放牲畜 之地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, ' 就来 见 摩西 和 祭司 以利亚撒,并 会众 的首领,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, '「亚大录、底本、雅谢、宁拉、希实本、以利亚利、示班、尼波、比稳, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, '就是 耶和华 在以色列 会众 前面 所攻取 之地,是 可牧放牲畜 之地,你仆人 也有牲畜」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, '又说:「我们若 在你眼前 蒙 恩,求你把 这 地 给 我们 为业,不要 领我们过 约旦河。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, '摩西 对迦得 子孙 和流便 子孙 说:「难道你们的弟兄 去 打仗,你们 竟坐 在这里吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, '你们为何 使 以色列 人 灰 心丧胆、不过去 进入 耶和华 所 赐 给他们 的那地呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, '我先前从加低斯‧巴尼亚 打发 你们先祖 去窥探 那地,他们也是这样 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, '他们上 以实各 谷,去窥探 那地回来的时候,使 以色列 人 灰 心丧胆,不 进 入 耶和华 所 赐 给他们 的地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, '当 日,耶和华 的怒气 发作,就起誓 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, '『凡从埃及 上来、 二十 岁 以外 的人 断不得 看见 我对亚伯拉罕、以撒、雅各 起誓 应许之地,因为 他们没有 专心 跟从我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, '惟有 基尼洗族 耶孚尼 的儿子 迦勒 和嫩 的儿子 约书亚可以看见,因为 他们专心 跟从 我。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, '耶和华 的怒气 向以色列人 发作,使他们在旷野 飘流 四十 年,等到 在耶和华 眼 前行 恶 的那一代人 都 消灭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, '谁知,你们起来 接续 先祖,增添 罪 人的数目, 使耶和华 向 以色列 大发 烈 怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, '你们若 退后 不跟从他,他还 要 把以色列人撇 在旷野,便是你们使这 众 民 灭亡。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, '两支派的人挨近 摩西,说:「我们要在这里 为牲畜 垒 圈,为妇人孩子 造城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, '我们自己 要 带兵器 行在以色列 人 的前头,好 把他们领 到 他们的地方;但我们的妇人孩子,因 这地 居民的缘故,要住 在坚固的 城内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, '我们不 回 家,直等到 以色列 人 各 承受 自己的产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, ' 我们不 和他们 在约旦河 那边 一带 之地同受产业,因为 我们的产业 是坐落 在 约旦河 东边 这里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, '摩西 对他们 说:「你们若 这 样 行,在耶和华 面前 带著兵器 出去打仗, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, ' 所有 带兵器 的人都要在耶和华 面前 过 约旦河,等 他赶出 他的仇敌, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, '那地被 耶和华 制伏了,然后 你们可以回来,向耶和华 和以色列 才为 无罪,这 地 也必在耶和华 面前 归你们 为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, '倘若 你们不 这样 行, 就得罪 耶和华,要知道 你们的罪 必追上 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, '如今你们口中 所出的,只管去行,为你们的妇人孩子 造 城,为你们的羊群 垒圈。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, '迦得 子孙 和流便 子孙 对 摩西 说:「仆人 要照 我主 所吩咐 的去行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, '我们的妻子、孩子、羊群,和所有的 牲畜 都要留 在基列 的各城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, '但你的仆人,凡 带 兵器的,都要照 我主 所说的话,在耶和华 面前 过去 打仗。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, '于 是,摩西 为他们 嘱咐 祭司 以利亚撒 和 嫩 的儿子 约书亚,并 以色列 众支派 的族 长,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, '「迦得 子孙 和流便 子孙,凡 带兵器 在耶和华 面前 去打仗的,若 与你们 一同过 约旦河,那地 被你们 制伏了,你们就要把 基列 地 给 他们 为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, '倘若 他们不 带兵器 和你们 一同过去,就要在迦南 地 你们中间 得产业。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, '迦得 子孙 和流便 子孙 回答 说:「耶和华 怎样 吩咐 仆人,仆人就怎样 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, '我们 要带兵器,在耶和华 面前 过去,进入迦南 地,只是约旦河 这边、我们所得为业 之地 仍归我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, '摩西 将 亚摩利 王 西宏 的国 和 巴珊 王 噩 的国,连那地 和周围的 城邑,都给了 迦得 子孙 和流便 子孙,并约瑟 的儿子 玛拿西 半个 支派。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, '迦得 子孙 建造 底本、 亚他录、 亚罗珥、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, '亚他录‧朔反、 雅谢、约比哈、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, '伯‧宁拉、伯‧哈兰,都是坚固 城。他们又垒羊 圈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, '流便 子孙 建造 希实本、 以利亚利、 基列亭、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, ' 尼波、巴力‧免、 西比玛(尼波、巴力‧免,名字 是改了的),又给 他们所 建造的 城 另起 别名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, '玛拿西 的儿子 玛吉,他的子孙 往基列 去,占了那地,赶出 那里 的亚摩利人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, '摩西 将 基列 赐 给玛拿西 的儿子 玛吉,他子孙就住 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, '玛拿西 的子孙 睚珥 去 占了 基列的村庄,就称 这些村庄为哈倭特‧睚珥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, '挪巴 去 占了 基纳 和 基纳的乡村,就按自己的名 称 基纳 为挪巴。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, ' 以色列 人 按著军队,在摩西、亚伦 的手下 出 埃及 地 所行的路程(或译:站口;下同)记在下面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, '摩西 遵著 耶和华 的吩咐 记载 他们所行 的路程,其路程 乃是这样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, '正 月 十 五 日,就是逾越节 的次日,以色列 人 从兰塞 起行,在一切 埃及人 眼前 昂 然 无惧地出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, '那时,埃及人 正葬埋他们的 长子,就是 耶和华 在他们中间 所击杀的;耶和华 也败坏 他们的神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, '以色列 人 从兰塞 起行,安营 在疏割。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, '从疏割 起行,安营 在旷野 边 的 以倘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, '从以倘 起行,转 到比‧哈希录,是 在巴力‧洗分 对面,就在 密夺 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, '从比‧哈希录 对面 起行,经过 海 中 到了书珥旷野,又在伊坦 的旷野 走了 三 天 的路程,就安营 在玛拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, '从玛拉 起行,来 到以琳(以琳 有十 二 股水泉,七十棵 棕树),就在那里 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, '从以琳 起行,安营 在 红 海边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, '从红 海 边起行,安营 在汛 的旷野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, '从汛 的旷野 起行,安营 在脱加。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, '从脱加 起行,安营 在亚录。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, '从亚录 起行,安营 在利非订;在那里,百姓 没 有 水 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, '从利非订 起行,安营 在西奈 的旷野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, '从西奈 的旷野 起行,安营在基博罗‧哈他瓦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, '从基博罗‧哈他瓦 起行,安营 在哈洗录。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, '从哈洗录 起行,安营 在利提玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, '从利提玛 起行,安营 在临门帕烈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, '从临门帕烈 起行,安营 在立拿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, '从立拿 起行,安营 在勒撒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, '从勒撒 起行,安营 在基希拉他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, '从基希拉他 起行,安营 在沙斐 山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, '从沙斐 山 起行,安营 在哈拉大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, '从哈拉大 起行,安营 在玛吉希录。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, '从玛吉希录 起行,安营 在他哈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, '从他哈 起行,安营 在他拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, '从他拉 起行,安营 在密加。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, '从密加 起行,安营 在哈摩拿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, '从哈摩拿 起行,安营 在摩西录。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, '从摩西录 起行,安营在比尼‧亚干。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, '从比尼‧亚干 起行,安营在曷‧哈及甲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, '从曷‧哈及甲 起行,安营 在约巴他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, '从约巴他 起行,安营 在阿博拿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, '从阿博拿 起行,安营在以旬‧迦别。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, '从以旬‧迦别 起行,安营 在寻 的旷野,就是 加低斯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, '从加低斯 起行,安营 在何珥 山,以东 地 的边界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, '以色列 人 出了 埃及 地 后四十 年,五 月 初 一日,祭司 亚伦 遵著 耶和华 的吩咐 上 何珥 山,就死 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, '亚伦 死 在何珥 山 的时候年 一百 二十 三 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, ' 住 在迦南 南 地 的迦南人 亚拉得 王 听说 以色列 人 来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, '以色列人从何珥 山 起行,安营 在撒摩拿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, '从撒摩拿 起行,安营 在普嫩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, '从普嫩 起行,安营 在阿伯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, '从阿伯 起行,安营在以耶‧亚巴琳,摩押 的边界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, '从以耶‧亚巴琳 起行,安营在底本‧迦得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, '从底本‧迦得 起行,安营在亚门‧低比拉太音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, '从亚门‧低比拉太音 起行,安营 在尼波 对面 的亚巴琳 山里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, '从亚巴琳 山 起行,安营 在摩押 平原─约旦河边、耶利哥 对面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, '他们在摩押 平原 沿 约旦河 边安营,从伯‧耶施末 直到亚伯‧什亭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, '耶和华 在摩押 平原─约旦河边、耶利哥 对面 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, '你吩咐 以色列 人 说: 你们 过 约旦河 进 迦南 地的时候, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, '就要从你们面前 赶出 那里 所有的 居民,毁灭 他们一切 錾成的石像 和 他们一切 铸成 的偶像,又拆毁 他们一切的 邱坛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, '你们要夺 那地,住 在其中,因 我把 那地 赐 给你们 为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, '你们要按家室 拈阄,承受 那地;人多的,要把 产业 多分给他们;人少的,要把 产业 少分给他们。 拈出 何地 给 何人,就要归 何人。你们要按宗族 的支派 承受。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, '倘若 你们不 赶出 那地 的居民,所 容留 的居民 就必作 你们眼 中的刺,肋 下的荆棘,也必在 你们 所 住 的 地 上扰害 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, '而且我素常有 意 怎样 待 他们,也必照样待 你们。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, '「你吩咐 以色列 人 说: 你们 到了 迦南 地, 就是 归 你们 为业 的迦南 四境 之地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, ' 南 角 要从寻 的旷野,贴著 以东 的边界; 南 界 要从盐 海 东 头起, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, ' 绕 到亚克拉滨 坡 的南 边,接连 到寻,直通 到加低斯‧巴尼亚 的南边,又通到哈萨‧亚达,接连 到押们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, '从押们 转 到埃及 小河, 直通 到 海为止。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, '「 西 边 要以大 海 为界;这 就是 你们的 西 界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, '「 北 界 要从 大 海起,划 㓰到 何珥 山, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, '从何珥 山 划 㓰到 哈马 口, 通 到 西达达, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, ' 又通 到西斐仑 ,直 到哈萨‧以难。这 要作 你们的 北 界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, '「你们要从哈萨‧以难 划 㓰到 示番 为东 界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, '这界 要从示番 下 到亚延 东边 的利比拉, 又要达 到 基尼烈 湖 的东 边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, '这界 要下 到约旦河,通 到 盐 海为止。这 四围 的边界以内,要作 你们的 地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, '摩西 吩咐 以色列 人 说:「这 地 就是 耶和华 吩咐 拈阄 给 九个 半 支派 承受为业的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, '因为 流便 支派 和迦得 支派 按著宗 族 受了产业,玛拿西 半 个支派 也受了 产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, '这两 个 半 支派 已经在耶利哥 对面、约旦河 东、向日出 之地受了 产业。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, '「 要给你们 分 地 为业之人 的名字 是 祭司 以利亚撒 和嫩 的儿子 约书亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, '又要从每支派 中选 一个 首领帮助他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, '这些 人 的名字:犹大 支派 有耶孚尼 的儿子 迦勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, '西缅 支派 有亚米忽 的儿子 示母利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, '便雅悯 支派 有基斯伦 的儿子 以利达。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, '但 支派 有一个首领,约利 的儿子 布基。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, '约瑟 的子孙 玛拿西 支派 有一个首领,以弗 的儿子 汉聂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, '以法莲 支派 有一个首领,拾弗但 的儿子 基母利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, '西布伦 支派 有一个首领,帕纳 的儿子 以利撒番。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, '以萨迦 支派 有一个首领,阿散 的儿子 帕铁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, '亚设 支派 有一个首领,示罗米 的儿子 亚希忽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, '拿弗他利 支派 有一个首领,亚米忽 的儿子 比大黑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, '这些人 就是 耶和华 所吩咐、在迦南 地 把产业分 给 以色列 人的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, '耶和华 在摩押 平原─约旦河边、耶利哥 对面 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, '「你吩咐 以色列 人,要从所得为业 的地 中把些城 给 利未人 居住,也要把这城 四围 的郊野 给 利未人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, '这城邑 要归 他们 居住,城邑的郊野 可以 牧养他们的牛羊 和各样的 牲畜,又可以安置他们的财物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, '你们给 利未人 的郊野, 要从城 根起,四围 往外 量一千 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, '另外 东 量 二千 肘, 南 量二千 肘, 西 量二千 肘, 北 量二千 肘,为边界,城 在当中;这 要归 他们 作城邑 的郊野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, ' 你们给 利未人 的 城邑,其中 当有六 座逃 城, 使 误杀人的 可以逃 到那里。此外还要 给 他们四十 二 座城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, '你们要给 利未人的 城,共有四十 八 座,连城 带 郊野都要给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, '以色列 人 所 得的地业 从中 要把些城邑 给利未人;人多 的就多给, 人少 的就少给;各 支派要按 所 承受 为业之地 把城邑 给 利未人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, '耶和华 晓谕 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, '「你吩咐 以色列 人 说: 你们 过 约旦河,进了迦南 地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, '就要分出 几座城,为你们 作 逃 城,使误 杀 人 的 可以逃 到那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, '这些城可以作 逃避 报仇人 的城,使误杀人的 不至于  死,等 他站 在会众 面前 听审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, '你们所 分出来 的城,要作 六座 逃 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, '在约旦河 东 要分出 三座 城,在迦南 地 也要分出 三座 城,都作 逃 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, '这 六座 城 要给以色列 人 和他们中间 的外人,并寄居的,作为 逃城,使误 杀 人 的都 可以逃 到那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, '「倘若 人用铁 器 打人,以致打死,他就是 故杀人的;故杀人的 必 被治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, '若 用 可以打死 人的石头 打 死了人,他就是 故杀人的;故杀人的 必 被治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, '若 用 可以打死 人的木 器 打 死了人,他就是 故杀人的;故杀人的 必 被治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, '报血 仇的 必亲自 杀 那故杀人的,一遇见 就 杀他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, '人若 因怨恨 把人推倒,或是 埋伏 往人身上 扔物,以致于 死, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, '或是 因仇恨 用手 打人,以致于 死,那打人的 必 被治死。他是 故杀人的;报血 仇的 一遇见 就杀 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, '「倘若 人没有 仇恨,忽然 将人推倒,或是 没有 埋伏把 物 扔 在人身上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, '或是 没有 看见 的时候用可以打死人的 石头 扔 在人身上,以致于 死,本来 与他 无 仇,也无 意 害他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, '会众 就要照 典章,在 打死人的 和报血 仇的 中间 审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, '会众 要救 这误杀人的 脱离报血 仇人 的手, 也要使他 归 入 逃 城。他要住 在其中,直等到 受 圣 膏 的大 祭司 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, '但 误杀人的,无论什么时候,若 出了 逃 城 的境外, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, '报血 仇的 在逃 城 境 外 遇见 他,将 他 杀了,报血 仇的 就没有 流血之罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, '因为 误杀人的该住 在逃 城里,等到 大 祭司 死了。大 祭司 死了 以后,误杀人的 才可以回 到 他所得为业 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, '这 在你们一切的 住处,要作 你们 世世代代 的律例 典章。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, '「无论谁 故杀 人,要凭几个见证人 的口 把 那故杀人的 杀了,只是不可 凭一个 见证 的口 叫人 死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, '故杀人、 犯死 罪的,你们不可 收 赎价 代替他的命; 他必 被治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, '那逃 到 逃 城的人,你们不可 为他收 赎价,使他在 大祭司 未死 以先再 来住 在本地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, '这样,你们 就不 污秽 所住 之地,因为 血 是 污秽 地的; 若 有在地上 流 人血的,非流 那 杀人者的血,那地 就不 得洁净(原文是赎)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, '你们 不可 玷污 所 住之 地,就是 我 住 在其中之地,因为 我─耶和华 住 在以色列 人 中间。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, '约瑟 的后裔,玛拿西 的孙子,玛吉 的儿子 基列,他子孙中 的诸族 长 来 到摩西 和作首领 的以色列 人 族 长 面前,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, '「耶和华 曾吩咐 我主 拈阄 分 地 给以色列 人 为业,我主 也受了耶和华 的吩咐 将 我们兄弟 西罗非哈 的产业 分 给他的众女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, '她们若嫁 以色列 别 支派 的人,就必 将我们祖宗 所遗留的产业 加 在 她们丈夫支派 的产业中。这样,我们拈阄 所得的产业 就要减少了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, ' 到了 以色列 人 的禧年,这女儿的产业 就必加 在 她们丈夫支派 的产业上。这样,我们祖宗 支派 的产业 就减少了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, '摩西 照 耶和华 的话 吩咐 以色列 人 说:「约瑟 支派 的人 说得 有理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, '论到 西罗非哈 的众女儿,耶和华 这 样 吩咐 说:她们可以随 意 嫁人,只是 要嫁 同宗 支派的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, '这样,以色列 人 的产业 就不 从这支派 归 到 那支派,因为 以色列 人 要各 守 各祖宗 支派 的产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, '凡 在以色列 支派 中得了 产业 的女子 必作 同 宗 支派 人的妻,好叫 以色列 人 各自 承受 他祖宗 的产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, '这样,他们的产业 就不 从这支派 归 到那 支派,因为 以色列 支派 的人 要各 守 各的产业。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, '耶和华 怎样 吩咐 摩西,西罗非哈 的众女儿 就怎样 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, '西罗非哈 的女儿 玛拉、得撒、曷拉、密迦、挪阿 都嫁了 他们伯叔 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, '她们嫁 入约瑟 儿子、玛拿西 子孙 的族中;她们的产业 仍留 在 同宗 支派中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, '这是 耶和华 在摩押 平原─约旦河边、耶利哥 对面─藉 借著 摩西 所 吩咐 以色列 人 的命令 典章。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, '以下所记的是 摩西 在约旦河 东 的旷野、疏弗 对面 的亚拉巴─就是 巴兰、陀弗、拉班、哈洗录、底撒哈 中间─向 以色列 众人 所 说 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, '(从何烈山 经过西珥 山 到加低斯‧巴尼亚 有十 一 天 的路程。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, ' 出埃及第四十 年 十 一 月 初 一日,摩西 照 耶和华 藉 借著他 所 吩咐 以色列 人 的话都晓谕 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, '那时,他已经击杀了 住 希实本 的 亚摩利 王 西宏 和 住 以得来、亚斯他录 的 巴珊 王 噩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, '摩西 在约旦河 东 的摩押 地 讲 律法 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, '「耶和华─我们的 神 在何烈山 晓谕 我们 说:你们 在这 山 上住 的日子够了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, '要起行 转 到 亚摩利人 的山地 和 靠近 这山地的各处,就是亚拉巴、山地、高原、南地,沿海 一带 迦南人 的地,并黎巴嫩山 又到 幼发拉底 大 河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, '如今 我将 这地 摆 在你们面前;你们要进去 得 这地,就是 耶和华 向你们列祖 亚伯拉罕、以撒、雅各 起誓 应许赐 给他们 和他们 后裔为业之地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, '「那 时,我 对你们 说:『管理你们的重任,我独自 担当 不 起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, '耶和华─你们的 神 使你们 多起来。看哪,你们今日 像天上 的星 那样多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, '惟愿 耶和华─你们列祖的 神 使你们 比如今 更多 千 倍,照他所 应许 你们 的话赐福 与你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, '但你们的麻烦,和管理你们的重任,并你们的争讼,我独自一人 怎能 担当得起呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, '你们要按著各支派 选举 有智慧、有见识、为众人所认识 的,我立他们 为你们的首领。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, '你们回答 我 说:『照你所 说 的 行了 为妙。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, '我便 将 你们各支派 的首领,有智慧、为众人所认识 的,照你们的支派,立 他们 为官长、千 夫长、百 夫长、五十 夫长、十 夫长,管理 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, '「当 时,我嘱咐 你们的审判官 说:『你们听讼,无论是 弟兄 彼此争讼,是与 同居的外人争讼,都要按公义 判断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, '审判的时候,不可 看 人的外貌;听 讼不可分贵 贱,不可 惧怕 人,因为 审判 是属乎 神的。若有难断 的 案件,可以呈 到我这里,我就判断。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, '那 时,我将 你们所 当行 的事 都 吩咐 你们了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, '「我们照著 耶和华─我们 神 所吩咐的 从何烈山 起行,经过 你们所 看见 那 大 而可怕 的旷野,往 亚摩利人 的山地 去,到了加低斯‧巴尼亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, '我对你们 说:『你们已经到 了 耶和华─我们 神 所 赐 给我们 的亚摩利人 之山地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, '看哪,耶和华─你的 神 已将 那地 摆 在你面前,你要照 耶和华─你列祖的 神 所说的 上去 得那地为业;不要 惧怕,也不要 惊惶。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, '你们都 就近我 来 说:『我们要先 打发 人去,为我们 窥探 那地,将我们上去该 走 何 道,必 进 何 城,都回 报 我们。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, '这话 我 以为美,就从你们中间 选了 十二个 人,每支派 一 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, '于 是他们起身 上 山地去,到 以实各 谷,窥探 那地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, '他们手里 拿著 那地 的果子 下来,到我们那里,回 报 说:『耶和华─我们的 神 所 赐 给我们的 是美 地。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, '「你们却不 肯 上去,竟违背了 耶和华─你们 神 的命令, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, '在帐棚内 发怨言 说:『耶和华 因为恨 我们,所以将我们从埃及 地 领出来,要交 在亚摩利人 手中,除灭我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, '我们 上 哪里去呢?我们的弟兄 使 我们的心 消化,说 那地的民 比我们 又大 又高,城邑 又广大 又坚固,高得顶天,并且 我们在那里 看见 亚衲族 的人。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, '我就对你们 说:『不要 惊恐,也不要 怕 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, '在你们前面 行的 耶和华─你们的 神必 为你们 争战 ,正如 他在埃及和旷野,在你们眼前 所 行的一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, '你们在旷野 所 行的 路上, 也曾见 耶和华─你们的 神 抚养你们,如同 人 抚养 儿子一般,直等 你们来 到 这 地方。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, '你们在这 事上 却不 信 耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, '他在路上,在你们前面 行,为你们 找 安营 的地方;夜间 在火柱里,日间 在云柱里,指示你们 所 当行 的路。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, '「耶和华 听见 你们 这话,就发怒,起誓 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, '『这 恶 世代的 人,连一个 也不 得见 我起誓应许 赐 给你们列祖的 美 地; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, '惟有 耶孚尼 的儿子 迦勒必 得看见,并且我要将他所 踏过的 地 赐 给他 和他的子孙,因为 他专心 跟从 我。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, '耶和华 为你们的缘故 也 向我 发怒,说:『你 必 不得 进入 那地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, '伺候 你、嫩 的儿子 约书亚,他 必得进入 那地;你要勉励 他,因为 他 要使 以色列人 承受那地为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, '并且你们的妇人孩子,就是 你们所说、必 被掳掠的, 和今日 不 知 善 恶 的儿女,必 进入 那地。我要将那地赐 给他们,他们 必得为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, '至于 你们,要转回,从红 海 的路 往旷野 去。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, '「那时,你们回答 我 说:『我们得罪了 耶和华, 情愿 照耶和华─我们 神 一切 所 吩咐的 上去 争战 。』于 是你们各人 带著 兵 器,争先 上 山地去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, '耶和华 吩咐我 说:『你对他们 说:不要 上去,也不要 争战 ;因 我不 在你们中间,恐怕你们被 仇敌 杀败了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, '我就告诉了 你们,你们却不 听从,竟违背 耶和华 的命令,擅自 上 山地 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, '住 那 山地 的亚摩利人 就出来 攻击你们,追赶 你们,如 蜂 拥一般,在西珥 杀退 你们,直到 何珥玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, '你们便回来,在耶和华 面前 哭号;耶和华 却不 听 你们的声音,也不 向你们 侧耳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, '于 是你们在加低斯 住了 许多 日子。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, '「此后,我们转回,从红 海 的路 往旷野 去,是照 耶和华 所吩咐 我的。我们在 西珥 山 绕行了 许多 日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, '耶和华 对我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, '『你们 绕行 这 山 的日子够了,要转向 北去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, '你吩咐 百姓 说:你们弟兄 以扫 的子孙 住 在西珥,你们 要经过 他们的境界。他们必惧怕 你们,所以你们要分外 谨慎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, '不可 与他们 争战 ; 他们的地,连 脚 掌 可踏之处,我都不 给 你们,因 我已将 西珥 山 赐 给以扫 为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, '你们要用钱 向他们 买  粮 吃,也 要用钱 向他们 买  水 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, '因为 耶和华─你的 神 在你手 里所办的一切 事 上已赐福与你。你走 这 大 旷野,他都知道了。这 四十 年,耶和华─你的 神 常与你同在,故此你一 无 所缺。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, '「于 是,我们离了 我们弟兄 以扫 子孙 所住 的西珥,从亚拉巴 的路,经过 以拉他、以旬‧迦别,转向 摩押 旷野 的路去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, '耶和华 吩咐我 说:『不可 扰害 摩押人,也不可 与他们 争 战 。 他们的地,我不 赐 给你 为业,因 我已将 亚珥 赐 给 罗得 的子孙 为业。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, '(先前,有以米人 住 在那里,民 数众多,身体高 大,像亚衲人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, '这以米人 像亚衲人;也 算为 利乏音人;摩押人 称 他们 为以米人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, '先前,何利人 也住 在西珥,但以扫 的子孙 将他们除灭,得了他们的地,接著 居住,就如 以色列在 耶和华 赐 给他 为业 之地 所行的一样。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, '现在,起来 过 撒烈 溪!于 是我们过了 撒烈 溪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, '自从 离开 加低斯‧巴尼亚,到 过了 撒烈 溪 的时候,共有三十 八 年,等 那世代 的兵 丁 都 从营 中 灭尽,正如 耶和华 向他们 所起的誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, '耶和华 的手 也攻击 他们,将他们从营 中 除灭,直到 灭尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, '「 兵 丁 从民 中 都 灭尽 死亡以后, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, '耶和华 吩咐 我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, '『你 今天 要从 摩押 的境界 亚珥 经过, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, '走近 亚扪 人之地,不可 扰害他们,也不可 与他们 争战 。 亚扪 人 的地,我不 赐 给你们 为业,因 我已将那地赐 给罗得 的子孙 为业。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '(那地 也 算为 利乏音人 之地,先前 利乏音人 住 在那里,亚扪人 称 他们 为散送冥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, '那民 众多,身体高 大,像亚衲人一样,但耶和华 从亚扪人面前 除灭他们,亚扪人就得了他们的地,接著 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, '正如 耶和华 从前为 住 西珥 的以扫 子孙 将 何利人 从他们面前 除灭、他们得了何利人的地、接著 居住一样,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, '从迦斐托 讬 出来 的迦斐托 讬人 将先前住 在乡村 直到 迦萨 的亚卫人 除灭,接著 居住。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, '你们起来 前往,过 亚嫩 谷; 我已将 亚摩利人 希实本 王 西宏 和 他的地 交 在你手中,你要 与他 争 战 ,得他的地为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, '从今 日 起,我要使 天 下 万民 听见 你的名声 都 惊恐 惧怕,且因你 发颤 伤恸。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, '「我从基底莫 的旷野 差遣 使者 去见 希实本 王 西宏,用和睦 的话 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, '『求你容我从你的地 经过,只走 大道,不 偏 左 右。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, '你可以 卖 粮 给我吃,也可以 卖 水 给我 喝,只要 容我步行 过去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, '就如 住 西珥 的以扫 子孙 和住 亚珥 的摩押人 待 我一样,等 我过了约旦河,好进入 耶和华─我们 神 所 赐 给我们 的地。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, '但希实本 王 西宏 不 容 我们从他那里 经过;因为 耶和华─你的 神使 他心中 刚硬, 性情 顽梗,为要 将他交 在你手中,像今 日一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, '耶和华 对我 说:『 从此起首,我要将 西宏 和 他的地 交 给你;你要 得 他的地 为业。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, '那时,西宏 和他的众 民 出来 攻击我们,在雅杂 与我们交战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, '耶和华─我们的 神 将他交 给我们,我们就把他 和 他的儿子,并 他的众 民,都击杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, '我们夺了 他的一切 城邑,将 有人烟 的各 城,连女人 带孩子,尽都毁灭,没有 留下 一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, '惟有 牲畜 和所 夺 的各城,并其中的财物,都取为自己 的掠物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, '从亚嫩 谷 边 的亚罗珥 和谷中的 城,直到 基列,耶和华─我们的 神 都 交 给我们了,没 有 一座城 高得 使我们不能攻取的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, '惟有 亚扪 人 之地,凡 靠近 雅博 河的地,并山地 的城邑,与耶和华─我们 神 所 禁止我们去的地方,都 没有 挨近。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, '「以后,我们转回,向 巴珊 去。巴珊 王 噩 和他的众民 都 出来,在以得来 与我们交 战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, '耶和华 对我 说:『不要 怕 他!因 我已将他 和 他的众民,并 他的地,都 交 在你手中;你要待 他 像 从前待 住 希实本 的 亚摩利 王 西宏一样。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, '于 是耶和华─我们的 神 也 将 巴珊 王 噩 和 他的众民 都 交 在我们手中;我们杀了他们, 没有 留下 一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, '那 时,我们夺了 他所有的 城,共有六十 座,没 有 一座城 不 被我们所 夺。这为亚珥歌伯 的全 境,就是巴珊地 噩 王的国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, '这些 城 都 有坚固的 高 墙,有门 有闩。此外 还有许 多 无城墙 的乡村。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, '我们将这些 都毁灭了,像 从前待 希实本 王 西宏一样,把有人烟 的各 城,连女人 带孩子,尽都毁灭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, '惟有一切 牲畜 和城 中的财物 都取为自己的 掠物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, '那 时,我们从约旦河 东 两个 亚摩利 王 的手 将 亚嫩 谷 直到 黑门 山之 地 夺过来 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(这黑门山,西顿人 称为 西连,亚摩利人 称为 示尼珥), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, '就是夺了平原 的各 城、基列 全地、巴珊 全地,直到 撒迦 和以得来,都是巴珊 王噩 国 内的城邑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, '(利乏音人 所剩下的 只有 巴珊 王 噩。 他的床 是铁 的,长 九 肘,宽 四 肘,都是以人 肘为度。现今岂 不 是在亚扪 人 的拉巴吗?)」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, '「那 时,我们得了 这 地。从亚嫩 谷 边 的 亚罗珥起,我将基列 山地 的一半,并其中的城邑,都给了 流便人 和迦得人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, '其余 馀的 基列 地和巴珊 全地,就是噩 王的国,我给了 玛拿西 半 支派。亚珥歌伯 全 地 乃是巴珊 全地;这 叫做 利乏音人 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, '玛拿西 的子孙 睚珥 占了 亚珥歌伯 全 境,直到 基述人 和玛迦人 的交界,就按 自己的 名 称 这 巴珊地为哈倭特‧睚珥,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, '我又将 基列 给了 玛吉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, '从 基列 到 亚嫩 谷,以谷 中 为界,直到 亚扪 人 交界 的雅博 河,我给了 流便人 和迦得人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, '又将亚拉巴 和靠近 约旦河之地,从基尼烈 直到 亚拉巴 海,就是盐 海,并毘斯迦 山 根 东边之地,都给了他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, '「那 时,我吩咐 你们 说:『耶和华─你们的 神 已将 这 地 赐 给你们 为业;你们所有的 勇 士 都要带著兵器,在你们的弟兄 以色列 人 前面 过去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, '但 你们的妻子、孩子、牲畜(我知道 你们有 许多的 牲畜)可以住 在我所 赐 给你们 的各城里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, '等到 你们弟兄 在约旦河 那边,也 得 耶和华─你们 神 所 赐 给他们的 地, 又使他们得享平安,与你们一样,你们 才可以回 到我所 赐 给你们 为业之地。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, '那 时 我吩咐 约书亚 说:『你亲眼 看见了 耶和华─你 神 向这 二 王所 行的;耶和华 也必向你 所 要去的 各 国 照样 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, '你不要 怕他们,因 那为你 争战  的是 耶和华─你的 神。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, '「那 时,我恳求 耶和华 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, '『主 耶和华啊,你 已 将 你的大力 大能 显 给 仆人看。在天上,在地下,有 什么 神 能像你行事、像你有大能 的作为呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, '求你 容我过去,看 约旦河 那边 的美 地,就是 那 佳美的 山地 和黎巴嫩。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, '但耶和华 因你们的缘故 向我 发怒,不 应允 我, 对我 说:『罢了!你不要 向我 再 提 这 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, '你且上 毘斯迦 山顶去,向东、西、南、北 举 目 观 望,因为 你必不能 过 这 约旦河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, '你却要嘱咐 约书亚,勉励他,使他胆壮;因为 他必 在这 百姓 前面 过去, 使他们 承受 你所 要观看之 地。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, '于 是我们住在伯‧毘珥 对面 的谷中。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, '「以色列人哪,现在 我 所 教训 你们的 律例 典章,你们要听从 遵行,好叫 你们存活,得以进入 耶和华─你们列祖之 神 所 赐 给你们的 地,承受为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, ' 所 吩咐 你们 的话,你们不可 加添,也不可 删减,好叫你们遵守 我 所 吩咐的,就是耶和华─你们 神 的命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, '耶和华因巴力‧毘珥 的事所 行的,你们亲眼 看见了。 凡 随 从巴力‧毘珥 的人,耶和华─你们的 神 都 从你们中间 除灭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, '惟有你们 专靠 耶和华─你们 神的人,今日 全都 存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, ' 我照著 耶和华─我 神 所 吩咐的 将律例 典章 教训 你们,使你们 在所 要进去 得为业 的地 上 遵 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, '所以 你们要谨守 遵行; 这就是 你们在万民 眼前 的智慧、聪明。他们 听见 这 一切 律例,必说:『这 大 国 的人 真是 有智慧,有聪明!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, ' 哪 一大 国的人有 神 与他们 相近,像耶和华─我们的 神、在 我们求告 他的时候与我们相近呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, '又哪 一大 国 有这样 公义的 律例 典章、像 我 今日 在你们面前 所 陈明的 这 一切律法呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, '「你 只要 谨慎,殷勤 保守 你的心灵,免得 忘记 你亲眼 所 看见 的事,又免得 你一 生、这事离开  你的心;总要传 给你的子 子孙 孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, '你在何烈山 站 在耶和华─你 神 面前 的那 日,耶和华 对我 说:『你为我 招聚 百姓,我要叫他们听见 我的话,使 他们 存活 在 世的 日子,可以 学习 敬畏 我,又可以教训 儿女这样行。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, '那时你们近前来,站 在山 下;山 上有火焰 冲 天,并有昏黑、密云、幽暗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, '耶和华 从火焰 中 对你们 说话,你们 只听见 声音,却没有 看见 形像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, '他将 所 吩咐 你们 当守 的约 指示 你们,就是十 条诫,并将这诫写 在 两 块石 版上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, '那 时 耶和华 又吩咐 我 将律例 典章 教训 你们,使你们 在所 要过去 得为业 的地上 遵行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, '「所以,你们要 分外 谨慎;因为 耶和华 在何烈山、从火 中 对你们 说话 的那日,你们没有 看见 什么 形像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, '惟恐 你们败坏自己,雕刻 偶像,仿佛 什么 男 像 女像, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, '或 地上 走兽 的像,或空中 飞 鸟的 像, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, '或地上 爬 物的像,或地 底下 水中 鱼 的像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, '又恐怕 你向天 举 目观看,见 耶和华─你的 神为 天 下 万 民 所 摆列的 日 月 星,就是天上 的万 象,自己便被勾引 敬拜 事奉 它。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, '耶和华 将你们 从埃及 领出来, 脱离 铁 炉,要特作 自己 产业 的子民,像今 日一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, '耶和华 又因 你们的缘故 向我 发怒,起誓 必不容我 过 约旦河,也不容我 进 入 耶和华─你 神 所 赐 你 为业 的那美 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, '我 只得 死 在这 地,不能 过 约旦河;但你们 必过去 得 那 美 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, '你们要谨慎,免得 忘记 耶和华─你们 神 与你们 所 立 的约,为自己 雕刻 偶像,就是 耶和华─你 神 所禁止 你做的 偶像; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, '因为 耶和华─你的 神 乃是烈 火,是 忌邪的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, '「 你们在那地 住久了,生 子 生孙,就雕刻 偶像,仿佛什么 形像,败坏自己,行 耶和华─你 神 眼 中看为恶的事,惹他发怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, '我今日呼 天唤 地 向你们 作见证, 你们 必在 过 约旦河 得为业 的地上 速速 灭 尽!你们不能 在那地上 长久,必 尽行 除灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, '耶和华 必使你们 分散 在万民中;在他 所 领 你们 到的万国里,你们剩下 的人数 稀少。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, '在那里,你们必事奉 人 手 所造 的神,就是用木 石造成、 不能 看、不能 听、不能 吃、不能 闻的神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, '但你们在那里 必寻求 耶和华─你的 神。 你尽 心 尽 性 寻求他的时候,就必寻见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, '日 后 你 遭遇 一切 患难的时候,你必归回 耶和华─你的 神,听从 他的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, '耶和华─你 神 原是 有怜悯的 神;他总不 撇下你,不 灭绝你,也不 忘记 他起誓 与你列祖 所 立的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, '「你且 考察 在你以前 的世代,自 神 造 人 在 世以来,从天 这边 到 天 那边,曾有何民 听见 神 在火 中 说话 的声音,像 你 听见 还能存活呢?这样 的大 事 何曾有、何 曾听见呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, '神 何 曾 从别的国 中 将 一国 的人民领出来,用试验、神迹、奇事、争战 、大能 的手,和伸 出来的膀臂,并大 可畏的事,像耶和华─你们的 神 在埃及,在你们眼前 为你们 所 行 的一切事呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, '这是显 给你看,要使你知道,惟有 耶和华─他是 神,除他以外,再 无别神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, '他从 天上 使你听见 他的声音,为要教训你,又在 地 上使你看见 他的烈 火,并且听见 他从火 中 所说的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, '因 他爱 你的列祖,所以拣选 他们的 后裔,用大 能 亲自 领你出了 埃及, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, '要将比你 强 大 的国民 从你面前 赶出,领你进去,将 他们的地 赐 你 为业,像今 日一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, '所以,今日 你要知道,也要记 在 心上,天 上 地 下 惟有 耶和华 他是 神,除他以外,再 无别神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, '我 今日 将 他的律例 诫命 晓谕你,你要遵守,使 你 和你的子孙 可以得福,并使 你的日子 在 耶和华─你 神 所 赐 的地 上 得以长久。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, '「那时,摩西 在约旦河 东,向日出之地,分定 三 座城, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, ' 使那 素 无 仇恨、无 心 杀了 人的,可以逃 到 这 三城 之中 的一座城,就得存活: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, '为流便人 分定旷野 平原的 比悉;为迦得人 分定基列的 拉末;为玛拿西人 分定巴珊的 哥兰。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, ' 摩西 在以色列 人 面前 所 陈明 的律法─ ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, '就是 摩西 在以色列 人 出 埃及 后所 传 给 他们的法度、律例、典章; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, '在约旦河 东伯‧毘珥 对面 的谷中,在住 希实本、亚摩利 王 西宏 之 地;这西宏 是摩西 和以色列 人 出 埃及 后所击杀的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, '他们得了 他的地,又得了 巴珊 王 噩 的地,就是 两 个亚摩利 王,在约旦河 东 向日出之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, '从亚嫩 谷 边 的 亚罗珥,直到 西云 山,就是 黑门山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, '还有约旦河 东 的全 亚拉巴,直到 亚拉巴 海,靠近毘斯迦 山 根。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, '摩西 将 以色列 众人 召了来,对他们 说:「以色列人哪,我 今日 晓谕 你们 的 律例 典章,你们要听,可以学习,谨守 遵行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, '耶和华─我们的 神 在何烈山 与我们 立 约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, ' 这 约 不是 与 我们列祖 立的,乃是 与 我们 今日 在这里 存活之人立的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, '耶和华 在山上,从火 中,面 对面 与你们 说话─ ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, '那 时 我 站 在 耶和华 和你们中间,要将 耶和华 的话 传 给你们;因为 你们惧怕 那火,没有 上 山─说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, '「『我是 耶和华─你的 神, 曾将你从埃及 地 为奴 之家 领出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, '「『除了 我以外,你 不可 有 别 的神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, '「『不可 为自己 雕刻 偶像,也不可做什么 形像, 仿佛上 天、 下 地 和 地 底下、水中的百物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, '不可 跪拜 那些像,也不可 事奉它,因为 我 耶和华─你的 神 是忌邪的 神。恨我的,我必追讨 他的罪,自父 及 子,直到 三、 四代; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, '爱我、守我 诫命的,我必向他们发 慈爱,直到千代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, '「『不可 妄 称 耶和华─你 神 的名;因为 妄 称 耶和华名的,耶和华 必不 以他 为无罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, '「『当照 耶和华─你 神 所吩咐 的守 安息日 为圣日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, '六 日 要劳碌 做 你一切的 工, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, '但第七 日 是向耶和华─你 神 当守的安息日。这一日,你 和你的儿 女、仆 婢、牛、驴、 牲畜,并在你城 里寄居的 客旅,无论何工 都 不可 做,使 你的仆 婢 可以和你一样 安息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, '你也要记念 你在埃及 地 作过 奴仆;耶和华─你 神 用大能 的手 和伸出来 的膀臂 将你从那里 领出来。因 此,耶和华─你的 神 吩咐你 守 安息 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, '「『当照 耶和华─你 神 所吩咐 的孝敬 父 母,使 你 得福,并使 你的日子 在 耶和华─你 神 所 赐 你 的地 上得以长久。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, '「『不可 杀人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, '「『不可 奸淫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, '「『不可 偷盗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, '「『不可 作 假 见证 陷害人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, '「『不可 贪恋 人 的妻子;也不可 贪图 人 的房屋、田地、仆 婢、牛、驴,并他 一切 所有的。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, '「 这些 话 是耶和华 在山上,从火 中、云中、幽暗中,大 声 晓谕 你们全 会众的;此外并没有 添别的话。他就把这话写 在 两 块石 版上,交 给我了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, '「那时,火焰 烧 山,你们听见 从黑暗 中出来的 声音;你们支派 中所有的 首领 和长老 都来就近 我, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, '说:『看哪,耶和华─我们 神 将 他的荣光 和 他的大能 显给我们看,我们又听见 他的声音 从火 中出来。今 日 我们得见 神 与 人 说话,人还存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, '现在 这 大 火 将要烧灭我们,我们何必 冒死呢? 若 再 听见 耶和华─我们 神 的声音 就必死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, '凡 属血气的, 曾有何人 听见 永生 神 的声音 从火 中 出来,像我们 听见还能存活呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, '求你 近前去,听 耶和华─我们 神 所 要说 的一切话,将 他 对你 说的话 都 传 给我们,我们就听从 遵行。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, '「你们对我 说 的话,耶和华 都听见了。耶和华 对我 说:『这 百姓 的话,我听见了;他们所 说 的都 是。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, '惟愿  他们 存 这样 的心 敬畏 我,常 遵守 我的一切 诫命,使 他们 和他们的子孙 永远 得福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, '你去 对他们 说:你们 回 帐棚去吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, '至于 你,可以站 在我 这里,我要将 一切 诫命、律例、典章 传 给你; 你要教训他们,使他们在我 赐 他们 为业 的 地 上遵行。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, '所以,你们要照 耶和华─你们 神 所吩咐的 谨守 遵行,不可 偏离 左 右。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, '耶和华─你们 神 所 吩咐 你们 行的,你们都 要去行,使 你们 可以存活 得福,并使你们的日子 在所 要承受 的地 上得以长久。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, '「这是 耶和华─你们 神 所 吩咐 教训 你们 的诫命、律例、典章,使你们 在所 要过去 得为业 的地 上遵行, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, '好叫 你 和你子子 孙孙 一 生 敬畏 耶和华─你的 神,谨守 他的一切 律例 诫命,就是我 所 吩咐你的,使 你的日子 得以长久。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, '以色列啊,你要听,要谨守 遵行,使 你 可以在那流 奶 与蜜 之地 得以享福, 人数极其 增多,正如 耶和华─你列祖的 神 所应许 你的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, '「以色列啊,你要听!耶和华─我们 神 是独一 的主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, '你要尽 心、尽 性、尽 力 爱 耶和华─你的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, '我 今日 所 吩咐你的 话 都要 记在 心上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, '也要殷勤教训 你的儿女。无论你坐 在家里,行 在路上,躺下,起来,都要谈论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, '也要系 在 手 上为记号,戴在 额上 为 经文; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, '又要写 在 你房屋 的门框上,并你的城门上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, '「 耶和华─你的 神 领你 进 他向你列祖 亚伯拉罕、以撒、雅各 起誓 应许给 你 的 地。那里有城邑,又大 又美,非 你所 建造的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, '有房屋,装满 各样 美物,非 你所 装满的;有凿 成的水井,非 你所 凿成的;还有葡萄园、橄榄园,非 你所 栽种的;你吃了 而且饱足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, '那时你要谨慎,免得 你忘记 将你从埃及 地、为奴 之家 领出来 的耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, '你要敬畏 耶和华─你的 神,事奉 他,指著他的名 起誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, '不可 随 从 别 神,就是 你们四围 国民 的神; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, '因为 在你们中间 的耶和华─你 神 是忌邪的 神,惟恐 耶和华─你 神 的怒气 向你 发作,就把你从 地 上 除灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, '「你们不可 试探 耶和华─你们的 神,像 你们在玛撒 那样试探他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, '要留意 遵守 耶和华─你们 神 所 吩咐 的诫命、法度、律例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, '耶和华 眼 中看为正、看为善的,你都要遵行,使 你 可以享福,并可以进去 得 耶和华 向你列祖 起誓 应许的 那美 地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, '照 耶和华 所说的,从你面前 撵出 你的一切 仇敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, '「 日后,你的儿子 问你 说:『耶和华─我们 神 吩咐 你们 的这些 法度、律例、典章 是什么意思呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, '你就告诉你的儿子 说:『我们在埃及 作过 法老的 奴仆;耶和华 用大能 的手 将我们从埃及 领出来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, '在我们眼前, 将重大 可怕 的神迹 奇事 施行 在埃及地 和法老 并他全 家的身上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, '将我们 从那里 领出来,要 领 我们 进入他向我们列祖 起誓 应许之 地,把 这地赐 给我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, '耶和华 又吩咐我们 遵行 这 一切 律例,要敬畏 耶和华─我们的 神,使我们 常 得好处,蒙他保全我们的生命,像今 日一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, '我们若 照 耶和华─我们 神 所吩咐 的 一切 诫命 谨守 遵行,这就是 我们的 义了。』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, '「 耶和华─你 神 领你 进入 要得为业 之地,从你面前 赶出 许多 国民,就是赫人、革迦撒人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人,共七 国的民,都比你 强 大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, '耶和华─你 神 将他们交 给你 击杀,那时你要把他们 灭绝 净尽,不可 与他们 立 约,也不可 怜恤他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, '不可 与他们 结亲。不可 将你的女儿 嫁 他们的儿子,也不可 叫你的儿子 娶 他们的女儿; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, '因为 他必使 你儿子 转离 不跟从主,去事奉 别 神,以致耶和华 的怒气 向你们 发作,就速速地 将你们灭绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, '你们却要 这样 待 他们:拆毁 他们的祭坛,打碎 他们的柱像,砍下 他们的木偶,用火 焚烧 他们雕刻的偶像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, '因为 你 归耶和华─你 神 为圣洁 的民;耶和华─你 神 从 地 上 的 万民 中拣选 你,特 作 自己的 子民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, '「耶和华 专爱 你们,拣选 你们,并非 因你们的人数多于  别民,原来 你们 的人数在万 民 中是最少的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, '只因 耶和华 爱 你们,又因要守 他向你们列祖 所 起的 誓, 就用大能 的手 领 你们出来,从为奴 之家 救赎你们 脱离埃及 王 法老 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, '所以,你要知道 耶和华─你的 神,他是 神,是信实的 神;向爱他、守 他诫命 的人守 约,施慈爱,直到千 代; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, '向恨他的 人当 面 报应他们,将他们灭绝。凡恨他的人必 报应 他们,决不 迟延。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, '所以,你要谨守 遵行 我 今日 所 吩咐你的 诫命、 律例、 典章。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, '「你们果然 听从 这些 典章,谨守 遵行,耶和华─你 神 就必照他向你列祖 所 起 的誓守 约,施 慈爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, '他必爱你,赐福与你,使你人数增多,也必在 他向你列祖 起誓 应许给 你 的 地 上赐福 与你身 所生的,地 所产的,并你的五谷、新酒,和油,以及牛 犊、羊 羔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, '你必 蒙福 胜过万 民;你们的 男 女没 有 不能生养的,牲畜也没有不能生育的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, '耶和华 必使一切的 病症 离开  你;你所 知道 埃及 各样的 恶 疾,他不 加 在你身上,只加 在一切 恨你的人身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, '耶和华─你 神 所 要交 给你 的一切 人民,你要将 他们除灭;你眼 不可 顾惜 他们。你也不可 事奉他们的 神,因 这必 成为你的 网罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, '「你若 心 里说,这些 国的民 比我 更多,我怎 能 赶出他们呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, '你不要 惧怕 他们,要牢牢 记念 耶和华─你 神 向法老 和埃及 全 地所 行的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, '就是你亲眼 所 看见 的大 试验、神迹、奇事,和大能 的手,并伸出来 的膀臂,都是 耶和华─你 神 领你出来所用的。耶和华─你 神 必照样 待 你 所 惧怕 的一切 人民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, '并且 耶和华─你 神 必打发 黄蜂 飞到他们中间,直到 那剩下 而藏躲的人 从你面前 灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, '你不要 因他们 惊恐,因为 耶和华─你 神 在你们中间 是大 而可畏的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, '耶和华─你 神 必将 这些 国的民 从你面前 渐 渐 赶出;你不 可 把他们速速 灭尽,恐怕 野地 的兽 多起来 害你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, '耶和华─你 神 必将他们交 给你,大 大地 扰乱他们,直到 他们灭绝了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, '又要将他们的君王 交 在你手中,你就使 他们的名 从天 下 消灭。必无 一人 能在你面前 站立得住,直到 你将他们 灭绝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, '他们雕刻的神 像,你们要用火 焚烧;其上 的金 银,你不可 贪图,也不可收取,免得 你因此 陷入网罗;这 原是 耶和华─你 神 所憎恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, '可憎的物,你不可 带 进 家去;不然,你就成了 当毁灭的,与那物一样。你要十分 厌恶,十分 憎嫌,因为 这是 当毁灭的物。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, '「我 今日 所 吩咐 的一切 诫命,你们要谨守 遵行,好叫 你们存活,人数增多,且进去 得 耶和华 向你们列祖 起誓 应许的 那地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, '你也要记念 耶和华─你的 神 在旷野 引导你 这 四十 年,是要 苦炼你,试验你,要知道 你心内 如何,肯守 他的诫命 不肯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, '他苦炼你,任你饥饿,将你 和你列祖 所 不 认识 的吗哪 赐给你吃,使 你知道, 人 活著 不是 单 靠 食物,乃是 靠 耶和华 口 里所出 的一切 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, '这 四十 年,你的衣服 没有 穿破,你的脚 也没有 肿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, '你当 心 里思想, 耶和华─你 神 管教你,好像 人 管教 儿子一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, '你要谨守 耶和华─你 神 的诫命,遵行 他的道,敬畏 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, '因为 耶和华─你 神 领你 进入 美 地,那地 有河,有泉,有源,从山 谷 中流出 水来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, '那地 有小麦、大麦、葡萄树、无花果树、石榴树、 橄榄树,和蜜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, '你在那 地 不 缺 食物,一 无 所缺。那 地 的石头 是铁,山 内可以挖 铜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, '你吃 得饱足,就要称颂 耶和华─你的 神,因 他将那 美 地 赐 给你了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, '「你要谨慎,免得 忘记 耶和华─你的 神,不 守 他的诫命、典章、律例,就是 我 今日 所吩咐你的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, '恐怕 你吃 得饱足,建造 美好 的房屋 居住, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, '你的牛 羊 加多,你的金 银 增添,并你 所有的 全都 加增, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, '你就心 高气傲,忘记 耶和华─你的 神,就是将你从埃及 地 为奴 之家 领出来的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, '引你 经过那大 而可怕 的旷野,那里有火蛇、蝎子、干旱 无 水 之地。他曾为你 使水 从坚硬 的磐石 中流出来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, '又在旷野 将你列祖 所 不 认识 的吗哪 赐给你吃,是要 苦炼你, 试验你,叫你终久 享福; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, '恐怕你心 里说:『 这 货财 是我力量、我能力 得来的。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, '你要记念 耶和华─你的 神,因为 得 货财 的力量 是他 给 你的,为要 坚定 他向你列祖 起誓 所立的 约,像今 日一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, ' 你若 忘记 耶和华─你的 神,随 从 别 神,事奉 敬拜,你们必定 灭亡;这是我今日 警戒 你们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, '耶和华 在你们面前 怎样 使列国的民 灭亡,你们也必照样 灭亡,因为 你们不 听从 耶和华─你们 神 的话。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, '「以色列啊,你当听!你 今日 要过 约旦河,进去 赶出比你 强 大 的国民,得著 广大 坚固、高得顶天 的城邑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, '那民 是亚衲族 的人,又大 又高,是你 所 知道的; 也曾听见有人指著他们说:『谁 能在亚衲族 人 面前 站立得住呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, '你今日 当知道, 耶和华─你的 神 在你前面 过去,如同烈 火, 要灭绝他们, 将他们制伏 在你面前。这样,你就要照 耶和华 所说 的赶出他们,使他们速速 灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, '「耶和华─你的 神 将这些国民 从你面前 撵出以后,你心 里不可 说:『耶和华 将我领进来 得 这 地 是因我的义。』其实,耶和华 将他们从你面前 赶出去 是因他们的恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, '你 进去 得 他们的地,并不是 因你的义,也不是因你心 里正直,乃是因 这些 国民 的恶,耶和华─你的 神 将他们从你面前 赶出去,又因 耶和华 要坚定 他向你列祖 亚伯拉罕、以撒、雅各 起誓 所应许的 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, '「你当知道, 耶和华─你 神 将 这 美 地 赐 你 为业,并不是 因你的义;你 本是 硬著 颈项 的百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, '你当记念 不 忘, 你在旷野 怎样 惹 耶和华─你 神 发怒。自从 你出了 埃及 地 的那日,直到 你们来到 这 地方,你们时常 悖逆 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, '你们在何烈山 又惹 耶和华 发怒;他 恼怒 你们,要灭绝 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, '我上了 山,要领受 两块石 版,就是 耶和华 与你们 立 约 的版。那时我在山 上住了 四十 昼 夜,没有 吃 饭,也没有 喝 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, '耶和华 把 那两 块石 版 交 给我,是 神 用指头 写的。版上 所写的是照耶和华 在大会 的日子、在山上、从火 中 对你们 所 说 的一切 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, '过了 四十 昼 夜,耶和华 把 那两 块石 版,就是约 版,交 给我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, ' 对我 说:『你起来, 赶快 下去!因为 你从埃及 领出来 的 百姓 已经败坏了自己;他们快快地 偏离了 我所 吩咐 的道,为自己 铸成 了偶像。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, '「耶和华 又 对我 说:『我看 这 百姓 是 硬著 颈项 的百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, '你且由著 我,我要灭绝他们,将 他们的名 从天 下 涂抹,使你 的后裔比他们 成为 更大 更强 的国。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, '于 是我转身 下 山,山 被火 烧著,两 块约 版 在 我两 手之中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, '我一看见 你们得罪 了耶和华─你们的 神,铸成了 牛犊,快快地 偏离了 耶和华 所 吩咐 你们 的道, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, '我就把 那两 块版 从 我 手 中扔下去,在你们眼前 摔碎了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, '因 你们所 犯 的一切 罪,行了 耶和华 眼 中看为恶的事,惹他发怒,我就像从前 俯伏 在耶和华 面前 四十 昼 夜,没有 吃 饭,也没有 喝 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, '我因 耶和华 向你们 大发 烈 怒,要灭绝 你们,就甚害怕;但那 次 耶和华 又 应允 了我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, '耶和华 也向亚伦 甚是 发怒,要灭绝他;那 时 我又 为 亚伦 祈祷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, '我把 那叫你们犯罪 所 铸的 牛犊 用火 焚烧,又捣碎 磨 得很细,以致 细 如灰尘,我就把 这灰尘 撒 在 从 山 上流下来 的溪水中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, '「你们在他备拉、玛撒、基博罗‧哈他瓦又 惹 耶和华 发怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, '耶和华 打发 你们离开 加低斯‧巴尼亚,说:『你们上去 得 我所 赐 给你们 的地。』那时你们违背了 耶和华─你们 神 的命令,不 信服 他,不 听从 他的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, '自从 我认识 你们以来,你们常常 悖逆 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, '「我因 耶和华 说 要灭绝 你们,就在耶和华 面前 照 旧 俯伏 四十 昼 夜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, '我祈祷 耶和华 说:『主 耶和华啊,求你不要 灭绝 你的百姓。他们是你的产业,是 你用大力 救赎的,用 大能 从埃及 领出来 的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, '求你记念 你的仆人 亚伯拉罕、以撒、雅各,不要 想念 这 百姓的 顽梗、 邪恶、 罪过, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, '免得 你领我们出来 的那地 之人 说,耶和华 因为不 能 将这百姓领 进 他所 应许 之地,又因恨 他们,所以领他们出去,要在旷野 杀他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, '其实他们 是你的百姓,你的产业,是 你用大 能 和伸出来 的膀臂 领出来的。』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, '「那 时,耶和华 吩咐我 说:『你要凿出 两 块石 版,和先前的一样,上 山 到我这里来,又要做 一木 柜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, '你先前 摔碎 的 那版,其 上的 字 我要写 在 这版上;你要将这版放 在柜中。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, '于 是我用皂荚 木 做了 一柜,又凿出 两 块石 版,和先前的一样,手 里拿这两 块版 上 山去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, '耶和华 将那大会 之日、在山 上从火 中 所 传 与你们的 十 条诫,照先前 所写的,写 在 这版上, 将版交 给我了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, '我转身 下 山,将 这版 放 在我所 做 的柜中,现今还在 那里,正如 耶和华 所吩咐我的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, '(以色列 人从比罗比尼‧亚干(或译:亚干井)起行,到了摩西拉。亚伦 死 在那里,就葬 在那里。他儿子 以利亚撒 接续他 供祭司的职分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, '他们从那里 起行,到了谷歌大,又从 谷歌大 到了有溪 水 之地 的约巴他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, '那 时,耶和华 将 利未 支派 分别出来,抬 耶和华 的约 柜,又侍立 在耶和华 面前 事奉他,奉他的名 祝福,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, '所 以 利未人 在 他弟兄 中无 分 无业,耶和华 是 他的产业,正如 耶和华─你 神 所应许 他的。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, '「我 又像 从前 在山 上住了 四十 昼 夜。那 次 耶和华 也 应允 我, 不 忍 将你灭绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, '耶和华 吩咐我 说:『你起来 引导 这百姓,使他们进去 得 我向他们列祖 起誓 应许所 赐 之地。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, '「以色列啊,现在 耶和华─你 神 向你 所要 的是什么呢?只要 你敬畏 耶和华─你的 神,遵行 他的道,爱 他,尽 心 尽 性 事奉 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, '遵守 他 的诫命 律例,就是 我 今日 所吩咐你的,为要叫你 得福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, '看哪,天 和天上 的天,地 和地上 所有的,都 属耶和华─你的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, '耶和华 但 喜悦 你的列祖,爱 他们,从万 民 中拣选 他们的后裔,就是你们,像今 日一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, '所以你们要将 心 里的污秽 除掉,不可 再 硬著 颈项。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, '因为 耶和华─你们的 神─他是 万神 之神,万主 之主,至大的 神,大有能力,大而可畏, 不 以貌 取人,也不 受 贿赂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, '他为孤儿 寡妇 伸 冤,又怜爱 寄居的,赐 给他 衣 食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, '所以你们要怜爱 寄居的,因为 你们在埃及 地 也作过 寄居的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, '你要敬畏 耶和华─你的 神,事奉 他,专靠 他,也要指著他的名 起誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, '他是 你所赞美的,是你的 神, 为你 做了 那 大而 可畏的事,是你亲眼 所 看见的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, '你的列祖 七十 人 下 埃及;现在 耶和华─你的 神 使你 如同天上 的星 那样多。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, '「你要爱 耶和华─你的 神,常 守 他的吩咐、律例、典章、诫命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, '你们今日 当知道, 我本不是 和 你们的儿女说话;因为他们 不 知道,也 没有 看见 耶和华─你们 神 的管教、 威严、 大能 的手,和伸出来 的膀臂, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, '并他在埃及 中 向埃及 王 法老 和其全 地 所 行的 神迹 奇事; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, '也没有看见他怎样 待 埃及 的军兵、车 马,他们追 赶你们的时候,耶和华 怎样 使 红 海 的水 淹没 他们,将他们灭绝,直到 今 日, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, '并他在旷野 怎样 待 你们,以致 你们来 到 这 地方; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, '也没有看见他怎样 待 流便 子孙 以利押 的儿子 大坍、亚比兰,地 怎样在 以色列人 中间 开  口,吞了他们 和 他们的家眷,并 帐棚 与 跟他们 的一切 活物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, '惟有 你们亲眼 看见 耶和华 所 做 的一切 大 事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, '「所以,你们要守 我 今日 所 吩咐 的一切 诫命,使 你们胆壮,能以进去,得 你们 所 要 得 的那地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, '并使 你们的日子 在 耶和华 向你们列祖 起誓、应许 给 他们 和他们后裔 的地 上得以长久;那是流 奶 与蜜 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, ' 你要 进去 得为业 的那地, 本 不 像你出来 的埃及 地。你在那里 撒 种,用脚 浇灌,像浇灌菜 园一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, '你们要 过去 得为业 的那地 乃是有山 有谷、雨水 滋润 之地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, '是耶和华─你 神 所 眷顾的;从岁 首 到 年 终,耶和华─你 神 的眼目 时常看顾 那地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, '「 你们若 留意 听从 我 今日 所 吩咐 的诫命,爱 耶和华─你们的 神,尽 心 尽 性 事奉他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, '他(原文是我)必按时 降 秋雨 春雨 在你们的地上,使你们可以收藏 五谷、新酒,和油, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, '也必使你吃 得饱足,并使田野 为你的牲畜 长 草。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, '你们要谨慎,免得 心 中受迷惑,就偏离正路,去事奉 敬拜 别 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, '耶和华 的怒气 向你们 发作,就使 天 闭塞 不 下 雨,地 也不 出产,使你们在 耶和华 所 赐 给你们 的美 地 上速速 灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, '「你们要将我这 话 存 在 心内,留在 意中,系 在 手 上为记号,戴在 额 上为 经文; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, ' 也要教训 你们的儿女,无论坐 在家里,行 在路上,躺下,起来,都要谈论; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, '又要写 在 房屋 的门框上,并城门上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, '使 你们 和你们子孙 的日子 在耶和华 向你们列祖 起誓、应许 给 他们 的地 上 得以增多,如天 覆 复 地 的日子那样多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, ' 你们若 留意 谨守 遵行 我 所 吩咐 这 一切 的诫命,爱 耶和华─你们的 神,行 他的道,专靠 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, '他 必从你们面前 赶出 这 一切 国民,就是比你们 更大 更强 的国民,你们也要得他们的地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, '凡 你们脚 掌 所 踏 之地 都必 归你们;从 旷野 和黎巴嫩,并 幼发拉底大 河,直到 西 海,都要作 你们的境界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, '必无 一人 能在你们面前 站立得住;耶和华─你们的 神 必照他所 说的,使 惧怕 惊恐 临到 你们所 踏 之地的居民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, '「看哪,我 今日 将祝福 与咒诅 的话都陈明 在你们面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, '你们若 听从 耶和华─你们 神 的诫命,就是 我 今日 所吩咐 你们的,就必 蒙福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, '你们若 不 听从 耶和华─你们 神 的诫命,偏离 我 今日 所 吩咐 你们的 道,去 事奉 你们素来所 不 认识 的别 神,就必受祸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, '及 至 耶和华─你的 神 领你进 入要 去 得为业 的 那地,你就要将 祝福 的话陈明 在 基利心 山上,将 咒诅 的话陈明在 以巴路 山上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, '这二山 岂不是 在约旦河 那边,日 落 之处,在住 亚拉巴 的迦南人 之地 与吉甲 相对,靠近 摩利 橡树吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, ' 你们 要过 约旦河,进去 得 耶和华─你们 神 所 赐 你们 为业之地, 在那地 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, '你们要谨守 遵行 我 今日 在你们面前 所 陈明 的一切 律例 典章。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, '「 你们 存活 于  世的 日子,在耶和华─你们列祖的 神 所 赐 你们 为业 的地上,要谨守 遵行 的律例 典章 乃是 这些: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, '你们 要将 所 赶出的 国民 事奉 神 的各 地方,无论是在 高 山,在 小山,在各 青翠 树 下,都毁坏了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, '也要拆毁 他们的祭坛,打碎 他们的柱像,用火 焚烧 他们的木偶,砍下 他们雕刻的神 像,并将 其名 从 那 地方 除灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, '你们不可 照他们那样 事奉 耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, '但 耶和华─你们的 神 从你们各 支派 中选择 何处 为立 他名 的居所,你们就当往 那里 去 求问, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, '将你们的燔祭、平安祭、 十分取一之物,和 手 中的举祭,并还愿 祭、甘心祭,以及牛群 羊群 中头生的,都奉到 那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, '在那里,耶和华─你们 神 的面前,你们 和你们的家属 都可以吃,并且因你手 所办的一切 事 蒙耶和华─你的 神 赐福,就都欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, '我们 今日 在这里 所 行 的是各人 行自己眼 中看为正的事,你们将来不可 这样 行; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, '因为 你们还 没有 到 耶和华─你 神 所 赐 你的 安息地,所给你的 产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, '但你们过了 约旦河,得以住 在耶和华─你们 神 使你们 承受为业 之 地,又使你们 太平,不被四围 的一切 仇敌扰乱,安然 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, '那时 要将 我 所 吩咐 你们 的燔祭、平安祭、十分取一之物,和手 中的举祭,并 向耶和华 许愿  献的一切 美 祭,都奉到 耶和华─你们 神 所 选择 要立为他 名 的居所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, '你们 和儿 女、仆 婢,并 住在你们 城 里 无 分 无业 的利未人,都要在耶和华─你们的 神 面前 欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, '你要谨慎,不可 在你所 看 中的各 处 献 燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, '惟独 耶和华 从你那一 支派 中所 选择 的地方,你就要在那里 献 燔祭, 行 我 一切 所 吩咐你的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, '「然而,在你各 城 里都 可以照耶和华─你 神 所 赐 你 的福分,随心所欲 宰 牲吃 肉;无论洁净 人不洁净 人都可以吃,就如吃羚羊 与鹿一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, '只是 不可 吃 血,要倒 在 地上,如同倒水一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, '你的五谷、新酒,和油 的十分之一,或是牛群 羊群 中头生的,或是 你许 愿  献的,甘心献的,或是手 中的举祭,都不 可 在你城 里吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, '但要 在耶和华─你的 神 面前 吃,在耶和华─你 神 所 要选择 的地方,你 和儿 女、仆 婢,并 住在你城 里的利未人,都可以吃;也要因 你手 所办的,在耶和华─你 神 面前 欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, '你要谨慎,在 你所住的地方 永 不可 丢弃 利未人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, '「 耶和华─你的 神 照他所 应许 扩张 你境界的时候, 你心 里想要 吃 肉,说:『我要吃 肉』,就可以随 心 所欲 地吃 肉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, '耶和华─你 神 所 选择 要立 他名 的地方 若 离你 太远,就可以照我所 吩咐的,将 耶和华 赐 给你 的牛 羊 取些宰了,可以随 心 所欲 在你城 里吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, ' 你吃那肉,要像 吃 羚羊 与 鹿 一般;无论洁净 人不洁净 人都 可以吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, '只是 你要心意坚定,不可 吃 血,因为 血 是 生命;不可将血(原文是生命)与 肉 同吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, '不可 吃血,要倒 在 地上,如同倒水一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, '不可 吃血。这样,你行 耶和华 眼 中看为正的事,你 和你的子孙 就可以 得福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, '只是 你分别为圣的物 和你的还愿  祭要奉 到 耶和华 所 选择 的地方 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, '你的燔祭,连肉 带血,都要献 在 耶和华─你 神 的坛上。平安祭 的血 要倒 在 耶和华─你 神 的坛上;平安祭的肉,你自己可以吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, '你要谨守 听从 我 所 吩咐 的一切 话, 行 耶和华─你 神 眼 中看为善,看为正的事。这样,你 和你的子孙 就可以永远 享福。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, '「 耶和华─你 神 将 你要去 赶出 的国民 从你面前 剪除,你 得了 他们 的地 居住, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, '那时就要谨慎,不可 在他们除灭 之后 随从他们的恶俗,陷入网罗,也不可 访问 他们的神 说:『这些 国民 怎样 事奉 他们的神,我 也要 照样 行。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, '你不可 向耶和华─你的 神 这样 行,因为 他们向他们的神 行了 耶和华 所 憎嫌 所恨恶的一切 事,甚至 将 自己的儿 女 用火 焚烧,献与他们的神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, ' 凡 我 所 吩咐的, 你们都要谨守 遵行,不可 加添,也不可 删减。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, '「你们中间 若 有先知 或是 做 梦 的起来,向你 显 个神迹 奇事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, ' 对你 说:『我们去 随从 你素来所 不 认识 的别 神,事奉它吧。』他所显的神迹 奇事 虽有应验, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, '你也不可 听 那 先知 或是 那 做 梦 之人的话;因为 这是耶和华─你们的 神 试验 你们,要知道 你们是 尽 心 尽 性 爱 耶和华─你们的 神不是。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, '你们要顺从 耶和华─你们的 神,敬畏 他,谨守 他的诫命,听从 他的话,事奉 他,专靠 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, '那 先知 或是 那 做 梦 的既 用言语 叛逆 那领你们出 埃及 地、救赎你 脱离为奴 之家 的耶和华─你们的 神,要勾引你 离开  耶和华─你 神 所 吩咐你 行 的道,你便要将他治死。这样,就把那恶 从你们中间 除掉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, '「 你的同 胞 弟兄,或是 你的儿 女,或是 你怀 中的妻,或是 如同你性命 的 朋友,若暗中 引诱你,说:『我们不如去 事奉 你 和你列祖 素来所 不 认识 的别 神─ ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, '是 你四围 列国 的神。』无论是离你 近, 离你 远,从地 这边 到 地 那边的神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, '你不可 依从 他,也不可 听从 他,眼 不可 顾惜 他。你不可 怜恤他,也不可 遮庇 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, ' 总要 杀他;你先 下 手,然后 众 民 也下手,将他治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, '要用石头 打 死他,因为 他想要 勾引你 离开  那领你 出埃及 地 为奴 之家 的耶和华─你的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, '以色列 众人 都要听见 害怕,就不 敢在你们中间 再 行 这 样的 恶了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, '「在耶和华─你 神 所 赐 你 居住的 各 城中,你若 听 人说,有些 匪 类 从你们中间 的一座城出来 勾引 本城 的居民,说:『我们不如去 事奉 你们素来所 不 认识 的别 神』; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, '你就要探听,查究,细细地 访问,果然 是真,准有 这 可憎恶 的事 行 在你们中间, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, '你必要 用 刀 杀 那 城 里的居民,把 城里 所有的,连 牲畜,都 用 刀 杀尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, ' 你从那城里所夺的财物 都 要堆积 在 街市 上,用火 将 城 和 其内所夺的财物 都 在耶和华─你 神 面前烧尽;那城就永 为 荒堆,不可 再 建造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, '那当毁灭的物 连 一点 都不可 粘 你的手。你要 听从 耶和华─你 神 的话,遵守 我 今日 所 吩咐你 的一切 诫命,行 耶和华─你 神 眼 中看为正的事,耶和华 就 必转意,不发烈 怒,恩 待 你,怜恤你,照 他向你列祖 所起的誓 使你人数增多。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'a   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, '「你们是 耶和华─你们 神 的儿女。不可 为死人 用刀划 㓰身,也不可 将额上 剃光; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, '因为 你 归耶和华─你 神 为圣洁 的民,耶和华 从地 上 的 万 民 中拣选 你 特 作 自己的 子民。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, '「凡 可憎的物 都不可 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, ' 可吃 的牲畜 就是 牛、绵羊、山羊、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, '鹿、羚羊、麃子、野山羊、麋鹿、黄羊、青羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, '凡 分 蹄 成为两 瓣 又倒嚼 的走兽,你们都可以吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, '但 那些 倒嚼 或是分 蹄 之中不可 吃 的乃是 骆驼、 兔子、 沙番─因为 是 倒嚼 不 分 蹄, 就与你们 不洁净; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, ' 猪─因为 是 分 蹄 却不 倒嚼, 就与你们 不洁净。这些兽的肉,你们不可 吃,死的 也不可 摸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, '「 水 中可吃 的乃是 这些:凡 有翅 有鳞 的都 可以吃; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, '凡 无 翅 无鳞 的都 不可 吃,是 与你们 不洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, '「凡 洁净 的鸟,你们都可以吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, ' 不可 吃的 乃是 雕 𫛲、狗头雕 𫛲、红头雕 𫛲、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, '鹯、 小鹰、鹞鹰 与其类, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, ' 乌鸦 与其类, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, ' 鸵鸟、 夜鹰、 鱼鹰、 鹰 与其类, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, ' 鸮鸟、 猫头鹰、角鸱、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, '鹈鹕、 秃雕 𫛲、 鸬鹚、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, '鹳、鹭鸶 与其类,戴鵀 与蝙蝠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, '凡 有翅膀 爬行的物 是 与你们 不洁净,都不可 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, '凡 洁净 的鸟,你们都可以吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, '「凡 自死的,你们都不可 吃,可以给 你城里 寄居的 吃,或 卖 与外人吃,因为 你是 归耶和华─你 神 为圣洁 的民。「不可 用山羊羔母 的奶 煮 山羊羔。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, '「你要把 你撒种 所产的,就是你田地 每 年 所出的,十分 取一分; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, '又要把你的五谷、新酒、和油 的十分之一,并牛群 羊群 中头生的,吃 在耶和华─你 神 面前,就是他所 选择 要立 为他名的 居所。这样,你可以学习 时常 敬畏 耶和华─你的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, '当 耶和华─你 神 赐福与你的时候,耶和华─你 神 所 选择 要立 为他名的 地方 若 离你 太远,那路 也太长, 使你不 能 把这物带到那里去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, '你就可以换成 银子,将银子 包起来,拿在手中,往 耶和华─你 神 所 要选择 的地方 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, '你用 这银子,随 心 所 欲,或买 牛 羊,或买 清酒 浓酒,凡 你心 所 想的都可以买 ;你 和你的家属 在耶和华─你 神 的面前 吃 喝快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, '「住在你城 里的 利未人,你不可 丢弃他,因为 他 在你们中间 无 分 无业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, '每逢三 年 的末一年,你要将 本 年 的土产 十分之一 都 取出来,积存 在你的城中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, ' 在你 城里无 分 无业 的利未人,和 你城 里寄居的,并孤儿 寡妇,都可以来,吃 得饱足。这样,耶和华─你的 神 必在你手 里所 办 的一切 事 上赐福与你。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, '「每逢七 年 末一年,你要施行 豁免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, '豁免 的定例 乃是这样:凡 债主 要把所 借 给邻舍 的豁免了;不可 向 邻舍 和 弟兄 追讨,因为 耶和华的 豁免 年已经宣告了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, '若借给 外邦人,你可以向他追讨;但借给 你弟兄,无论是 什么,你要松手 豁免了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, ' 你若 留意 听从 耶和华─你 神 的话,谨守 遵行 我 今日 所 吩咐你 这 一切的 命令,就必 在你们中间 没 有 穷人了(在耶和华─你 神 所 赐 你 为 业 的地上,耶和华 必 大大 赐福与你。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, '因为 耶和华─你的 神 必照他所 应许 你 的赐福与你。你 必借 给许多 国民,却不致 向他们借贷;你必管辖 许多 国民,他们却不能 管辖 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, '「在耶和华─你 神 所 赐 你 的地上,无论哪一 座城里,你弟兄 中若 有 一个 穷人,你不可 忍著 心、 揝著 手 不帮补你穷乏 的弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, ' 总要 向他 松开  手,照 他 所缺乏 的借 给他,补 他的不足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, '你要谨慎,不可 心 里 起 恶 念,说:『第七 年 的豁免 年 快到了』,你便恶 眼 看你穷乏 的弟兄,什么都不 给 他,以致他因你 求告 耶和华,罪 便归 于 你了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, '你总要 给 他,给 他 的时候心 里不可 愁烦; 因 耶和华─你的 神 必在你这 一切所行的,并 你手里所办的 事上,赐福与你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, '原来 那地 上 的穷人 永不 断绝;所 以 我 吩咐你 说:『总要 向你地 上困苦 穷乏 的弟兄 松开  手。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, '「你弟兄中,若 有一个希伯来男人 或 希伯来女人 被卖 给你,服事你 六 年,到第七 年 就要任他自由 出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, ' 你任 他自由的时候,不可 使他 空手而去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, '要从你羊群、禾场、酒醡 之中多多地 给 他;耶和华─你的 神 怎样 赐福与你,你也要照样给 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, '要记念 你在埃及 地 作过 奴仆,耶和华─你的 神 将你救赎;因 此,我 今日 吩咐你 这 件事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, ' 他若 对你 说:『我不 愿 意离开  你』,是因 他爱你 和 你的家,且因 在你 那里很好, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, '你就要拿 锥子 将他的耳朵 在门 上刺透,他便永 为 你的 奴仆了。你待 婢女 也要 这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, '你任 他 自由的时候,不可 以为 难事,因 他服事你 六 年,较比雇工 的工价 多加一倍了。耶和华─你的 神 就必在你所 做 的一切 事上赐福与你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, '「你牛群 羊群中 头生的,凡是 公的,都要分别为圣,归耶和华─你的 神。牛群 中头生的,不可 用牠耕地;羊群 中头生的,不可 剪毛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, '这头生的,你 和你的家属,每 年 要在耶和华 所 选择 的地方,在耶和华─你 神 面前 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, '这头生的若 有 什么残疾,就如瘸腿的、 瞎眼的,无论有什么 恶 残疾,都不可 献 给耶和华─你的 神; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, '可以在你城 里吃;洁净 人与不洁净 人都可以吃,就如吃羚羊 与鹿一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, '只是 不可 吃 牠的血;要倒 在 地上,如同倒水一样。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, '「你要注意 亚笔 月,向耶和华─你的 神 守 逾越节,因为 耶和华─你的 神 在亚笔 月 夜间 领你出 埃及。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, '你当在耶和华 所 选择 要立 为他名的 居所,从牛群 羊群中,将逾越节 的祭牲献 给耶和华─你的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, '你吃这祭牲,不可 吃 有酵的饼;七 日 之内要吃 无酵饼,就是困苦 饼─你本是 急忙 出了 埃及 地─要叫 你一生 一世 记念 你从埃及 地 出来 的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, '在你四 境之内,七 日 不可 见 面 麺酵,头一 日 晚上 所 献 的肉,一点 不可 留 到早晨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, '在耶和华─你 神 所 赐 的各 城中,你不 可 献 逾越节的祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, '只 当在 耶和华─你 神 所 选择 要立 为他名的 居所,晚上 日 落的时候,乃是你出 埃及 的时候,献 逾越节的祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, '当在耶和华─你 神 所 选择的 地方 把肉烤了吃(烤:或译煮),次日早晨 就回到 你的帐棚 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, '你要吃 无酵饼 六 日,第七 日 要向耶和华─你的 神 守严肃会,不可 做 工。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, '「你要计算 七七日:从你开  镰 收割禾稼 时算 起,共计七 七日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, '你要照 耶和华─你 神 所赐你的福,手 里拿著 甘心祭, 献 在耶和华─你的 神面前,守 七七 节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, '你 和你儿 女、仆 婢,并 住在你城 里的利未人,以及 在你们中间 寄居的 与孤儿 寡妇,都要在耶和华─你 神 所 选择 立 为他名的 居所,在耶和华─你的 神 面前 欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, '你也要记念 你在埃及 作过 奴仆。你要谨守 遵行 这些 律例。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, '「你把禾场的谷、酒醡的酒 收藏以后,就要守 住棚 节 七 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, '守节的时候,你 和你儿 女、仆 婢,并 住在你城 里的利未人,以及寄居的 与孤儿 寡妇,都要欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, '在耶和华 所 选择 的地方,你当向耶和华─你的 神 守节 七 日;因为 耶和华─你 神 在你一切 的土产 上和 你手 里所办的事 上要赐福与你,你就 非常地 欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, '你一切的 男丁 要在除酵 节、七七 节、住棚 节,一年 三 次,在耶和华─你 神 所 选择 的地方 朝见 他,却不可 空手 朝见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, '各人 要按自己的 力量,照耶和华─你 神 所 赐 的福分,奉献礼物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, '「你要在耶和华─你 神 所 赐 的各 城里,按著各支派 设立 审判官 和官长。他们必按公义 的审判 判断 百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, '不可 屈枉 正直;不可 看 人的外貌。也不可 受 贿赂;因为 贿赂 能叫智慧人 的眼 变瞎了,又能颠倒 义人 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, '你要追求 至公 至义,好叫 你存活,承受 耶和华─你 神 所 赐 你 的地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, '「你为耶和华─你的 神 筑坛, 不可 在坛 旁 栽 什么 树木 作为木偶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, '也不可 为自己 设立 柱像;这是 耶和华─你 神 所恨恶的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, '「凡 有 残疾,或有什么 恶 病 的牛 羊,你都不可 献 给耶和华─你的 神,因为 这是 耶和华─你 神 所憎恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, '「在你们中间,在耶和华─你 神 所 赐 你 的诸城中,无论哪座城里,若 有人,或男 或 女, 行 耶和华─你 神 眼 中看为恶的事,违背 了他的约, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, '去 事奉 敬拜 别 神,或拜日头,或 拜月亮,或 拜天 象,是 主不 曾吩咐的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, '有人告诉 你,你也听见了,就要细细地 探听,果然 是真,准 有这 可憎恶 的事 行 在以色列中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, '你就要将 行 这 恶 事的 男人 或 女人 拉 到 城门外,用石头将他 打 死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, '要凭 两 三 个人 的口 作见证 将那当死的人 治死;不可 凭 一 个人 的口 作见证将他治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, '见证人 要 先 下手,然后 众 民 也下手 将他治死。这样,就把那恶 从你们中间 除掉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, '「你城 中若 起了争讼 的事,或因 流血,或因 争竞,或因 殴打,是你 难 断 的案件,你就当起来, 往 耶和华─你 神 所 选择的 地方 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, '去 见 祭司 利未人,并 当 时 的 审判官,求问他们,他们必将 判 语 指示 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, '他们在 耶和华 所 选择 的地方 指示 你的 判语,你必 照著 他们所 指教你 的一切 话谨守 遵行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, '要按 他们所 指教你 的律法,照 他们所 断 定 的去行;他们所 指示 你的 判语,你不可 偏离 左 右。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, '若有人 擅敢 不 听从 那侍 立 在 耶和华─你 神 面前 的祭司,或 不听从 审判官,那 人 就必治死;这样,便将那恶 从以色列 中除掉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, '众 百姓 都要听见 害怕,不 再 擅敢行事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, '「 到了 耶和华─你 神 所 赐 你 的地,得了 那地 居住的时候,若说:『我要立 王 治理我, 像四 围 的国一样。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, '你总要 立 耶和华─你 神 所 拣选 的人 为 王。必从你弟兄 中 立一人;不 可 立 你弟兄 以外 的人 为王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, '只是 王不可 为自己 加添 马匹,也不可 使 百姓 回 埃及去,为要 加添 他的马匹,因耶和华 曾吩咐你们 说:『不可 再 回 那 条路去。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, '他也不可 为自己 多立 妃嫔,恐怕 他的心 偏邪;也不可 为自己 多 积 金 银。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, ' 他登了 国 位,就要将 祭司 利未人 面前 的这 律法 书,为自己 抄录 一本, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, '存 在他那里,要平 生 诵读,好 学习 敬畏 耶和华─他的 神,谨守 遵行 这 律法 书上的一切 言语 和这些 律例, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, '免得 他向弟兄 心 高气傲,偏左 偏右, 离了 这诫命。这样,他 和他的子孙 便可在以色列 中,在 国位 上年长 日久。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, '「祭司 利未人 和利未 全 支派 必在 以色列 中无 分 无业;他们所吃 用的就是献给耶和华 的火祭 和一切所捐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, '他们在弟兄 中 必没 有 产业;耶和华 是 他们的产业,正如耶和华所 应许 他们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, '祭司 从 百姓 所当得的分 乃是 这样:凡 献 牛 或 羊 为祭的,要把前腿 和两腮 并脾胃 给 祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, '初 收的五谷、新酒 和油,并初 剪的羊 毛,也要给 他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, '因为 耶和华─你的 神 从你各 支派 中将他 拣选出来,使他 和他子孙 永远 奉耶和华 的名 侍立,事奉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, '「利未人 无论 寄居 在 以色列 中的哪一 座城,若 从那里 出来,一 心 愿 意 到 耶和华 所 选择 的地方, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, '就要奉耶和华─他 神 的名 事奉,像他众 弟兄 利未人 侍立 在耶和华 面前事奉一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, '除了 他卖 祖父 产业所得的以外,还要得一分 祭物与他们同吃。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, '「 你 到了 耶和华─你 神 所 赐 之地,那些 国民 所行可憎恶的事,你不可 学 著行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, '你们中间 不可 有人使儿 女 经 火,也不可有占 卜的、观兆的、用法术的、行邪术的、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, '用迷 术的、交 鬼的、行巫术的、过 阴的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, ' 凡 行 这些 事的都为耶和华 所憎恶;因 那些国民行这 可憎恶的事,所以耶和华─你的 神 将他们 从你面前 赶出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, '你要在 耶和华─你的 神 面前作 完全人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, '「因 你 所 要赶出的 那些 国民 都听信 观兆的 和 占卜的,至于 你,耶和华─你的 神 从来不 许 你 这样行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, '耶和华─你的 神 要从你们弟兄 中间 给你 兴起 一位先知,像我,你们要听从 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, '正如 你在何烈山 大会 的日子 求 耶和华─你 神 一切的话,说:『求你不 再 叫我听见 耶和华─我 神 的声音,也不 再 叫我看见 这 大 火,免得 我死亡。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, '耶和华 就对我 说:『他们所 说 的是。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, '我必在他们弟兄 中间 给他们 兴起 一位先知,像你。我要将当说的话 传给他;他要将 我一切 所 吩咐 的都传 给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, ' 谁 不 听 他奉我名 所 说 的话,我必 讨 谁的罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, '若有 先知 擅敢 托 讬我的名 说 我所 未 曾吩咐他 说 的话,或是 奉别 神 的名 说话,那 先知 就必治死。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, '你心 里若 说:『耶和华 所 未 曾吩咐的 话,我们怎能 知道呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, '先知 托 讬耶和华 的名 说话,所说的 若不 成就,也无 效验,这就是 耶和华 所 未 曾吩咐 的,是那先知 擅自 说的,你不要 怕 他。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, '「 耶和华─你 神 将 列国之民 剪除的时候,耶和华─你 神 也将 他们的 地 赐 给你,你接著 住 他们的城邑 并他们的房屋, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, '就要在耶和华─你 神 所 赐 你 为业 的地 上 分定 三 座城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, '要将 耶和华─你 神 使你承受为业 的 地 分为三段;又要预备 道路,使误杀人的,都 可以 逃 到那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, '「误杀人的 逃 到那里 可以存活,定例 乃是这样:凡 素 无 仇恨,无 心 杀了 人的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, '就如人 与 邻舍 同入 树林 砍伐 树木,手 拿斧子 一砍,本想砍下 树木,不料,斧头 脱了 把,飞落 在 邻舍身上,以致于 死,这人 逃 到 那些 城 的一座城,就可以存活, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, '免得 报 血仇的,心 中火热 追 赶 他,因 路 远 就追上,将他 杀死;其实他 不 该 死,因为 他 与被杀的 素 无 仇恨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, '所 以 我 吩咐你 说,要分定 三 座城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, '耶和华─你 神 若 照 他向你列祖 所起的誓 扩张 你的境界,将 所 应许 赐 你列祖 的地 全然 给 你, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, '你若 谨守 遵行 我 今日 所 吩咐 的这 一切 诫命,爱 耶和华─你的 神,常常 遵行 他的道,就要在 这 三座城之外,再 添 三 座城, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, '免得 无辜 之人的血 流 在耶和华─你 神 所 赐 你 为业 的地 上,流血 的罪就归 于 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, '「若 有 人 恨 他的邻舍,埋伏著 起来 击杀 他,以致于 死,便逃 到 这些 城 的一座城, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, '本城 的长老 就要打发人去,从那里 带出 他来,交 在报 血 仇的手中,将他治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, '你眼 不可 顾惜 他,却要从以色列 中除掉 流无辜 血的罪,使你 可以得福。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, '「在耶和华─你 神 所 赐 你 承受 为业 之地,不可 挪移 你邻舍 的地界,那是 先人 所定的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, '「人 无论 犯 什么 罪,作什么 恶,不可 凭一 个人的口作见证,总要凭 两 三 个人的口 作见证 才可定 案。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, '若 有凶恶 的见证人 起来,见证 某人 作恶, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, '这两个 争讼 的人 就要站 在耶和华 面前,和 当 时 的祭司,并审判官 面前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, '审判官 要细细地 查究,若见证人 果然 是作假 见证的,以假 见证 陷害弟兄, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, '你们就要待 他 如同 他想要 待 的弟兄。这样,就把那恶 从你们中间 除掉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, '别人 听见 都要害怕,就不 敢 在你们中间 再 行 这 样 的恶了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, '你眼 不可 顾惜,要以命 偿命,以眼 还眼,以牙 还牙,以手 还手,以脚 还脚。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, '「 你出去 与 仇敌 争战 的时候,看见 马匹、车辆,并有比你 多 的人民,不要 怕 他们,因为 领你 出埃及 地 的耶和华─你 神 与你同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, ' 你们将要上 阵的时候,祭司 要到 百姓 面前宣告 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, '说:『以色列人哪,你们当听,你们 今日 将要 与 仇敌 争战 , 不要 胆怯,不要 惧怕 战 兢,也不要 因他们 惊恐; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, '因为 耶和华─你们的 神 与你们 同去,要为你们 与 仇敌 争战 ,拯救 你们。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, '官长 也要对 百姓 宣告 说:『谁 建造 房屋,尚未 奉献,他可以回 家 去,恐怕 他阵 亡,别 人 去奉献。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, '谁 种 葡萄园,尚未 用所结的果子,他可以回 家 去,恐怕 他阵 亡,别 人 去用。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, '谁 聘定了 妻,尚未 迎娶,他可以回 家 去,恐怕 他阵 亡,别 人 去娶。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, '官长 又 要对 百姓 宣告 说:『谁 惧怕 胆怯,他可以回 家 去,恐怕 他弟兄 的心 消化,和他一样。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, ' 官长 对 百姓 宣告 完了,就当派 军 长 率领 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, '「 你临 近 一座城、要攻打的时候,先要对 城里的民宣告 和睦的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, ' 他们若 以和睦 的话回答你,给你 开 了城, 城里 所有的 人 都要 给你 效劳,服事你; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, '若 不肯 与你 和好,反要与你 打 仗,你就要围困 那城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, '耶和华─你的 神 把城交付 你手,你就要用 刀 杀 尽 这城的男丁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, '惟有 妇女、孩子、牲畜,和 城内 一切 的财物,你可以取为自己的 掠物。耶和华─你 神 把 你仇敌 的 财物 赐 给你,你可以吃用。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, '离你 甚 远的 各 城, 不是 这些 国民 的 城,你都要这样 待他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, '但 这些 国民 的城,耶和华─你 神 既 赐 你 为业,其中凡 有气息的,一个不可 存留; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, '只要 照 耶和华─你 神 所吩咐的 将这赫人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人 都灭绝 净尽, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, '免得 他们教导 你们 学习 一切 可憎恶的事,就是 他们向自己神 所行的,以致 你们得罪 耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, '「你若 许久 围困、攻打 所要取的 一座城,就不可 举斧子 砍 坏 树木;因为 你可以吃 那树上的果子,不可 砍伐。田间 的树木 岂是 人,叫 你糟蹋吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, '惟独 你所 知道 不 是 结果子 的树木 可以毁坏、砍伐,用以修筑 营垒,攻击 那 与你 打 仗 的城,直到 攻塌了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, '「在耶和华─你 神 所 赐 你 为业 的地上,若 遇见 被杀的人 倒 在田野,不 知道 是谁 杀的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, '长老 和审判官 就要出去,从被杀的人 那里量起,直量到 四围 的 城邑, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, ' 看哪城 离 被杀的人 最近,那 城 的长老 就要从牛群中取一只 未 曾耕地、 未 曾负 轭 的母牛犊, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, ' 把 母牛犊 牵 到 流水、 未 曾耕 种 的山谷去,在谷中 打折 母牛犊 的颈项。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, '祭司 利未 的子孙 要近前来;因为 耶和华─你的 神 拣选了 他们 事奉他,奉耶和华 的名 祝福,所有 争讼 殴打 的事都 要 凭 他们判断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, '那 城 的众 长老,就是离 被杀的人 最近的,要在那山谷中,在 所打折颈项 的母牛犊 以上洗 手, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, '祷告(原文是回答)说:『我们的手 未 曾流 这人 的血;我们的眼 也未 曾看见这事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, '耶和华啊,求你赦免 你所 救赎 的以色列 民,不要 使流无辜 血 的罪归 在你的百姓 以色列 中间。』这样,流血的罪 必得赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, ' 你行 耶和华 眼中 看为正的事, 就可以从你们中间 除掉 流无辜 血的罪。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, '「 你出去 与 仇敌 争战 的时候,耶和华─你的 神 将他们交 在你手中,你就掳了他们去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, '若在被掳的人 中见有 美貌 的女子,恋慕 她,要娶 她为妻, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, '就可以领她 到 你家 里去;她便要剃 头发,修 指甲, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, '脱去 被掳时 所穿的衣服,住 在你家里 哀哭 父 母 一个整 月,然后 可以与她 同房。你作她的丈夫,她作 你的 妻子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, '后来 你若 不 喜悦 她,就要由她随意 出去,决 不可 为钱 卖她,也不可 当婢女 待她,因为 你玷污了她。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, '「人 若 有 二 妻,一 为所爱,一 为所恶,所爱的、所恶的 都给他 生了 儿子,但长 子 是 所恶之妻生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, '到了 把产业 分给 儿子 承受 的时候,不 可 将 所爱 之妻生的儿子 立为长子,在 所恶之妻 生的儿子 以上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, '却要 认 所恶之妻 生的儿子 为 长子,将 产业 多加 一分 给 他;因 这 儿子是他力量 强壮的时候生的,长子 的名分 本当归他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, '「人 若 有 顽梗 悖逆 的儿子,不 听从 父 母 的话,他们虽惩治 他,他仍不 听从, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, '父 母 就要抓住 他,将他 带 到 本地 的城门、 本城 的长老那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, '对 长老 说:『我们这 儿子 顽梗 悖逆,不 听从 我们的话,是贪食 好酒的人。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, '本城 的众 人 就要用石头 将他打 死。这样,就把那恶 从你们中间 除掉,以色列 众人 都要听见 害怕。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, '「人 若犯 该 死 的罪,被治死了,你将他 挂 在 木头上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, '他的尸首 不可 留在 木头 上过夜, 必 要 当 日 将他葬埋,免得 玷污了 耶和华─你 神 所 赐 你 为业 之地。因为 被挂的人是在 神 面前受咒诅的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, '「你若看见 弟兄 的牛 或 羊 失迷了路,不可 佯为不见,总要 把牠牵回来 交给你的弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, '你弟兄 若 离你 远,或是你不 认识他,就要牵 到 你家 去,留 在你那里,等 你弟兄 来寻找 就还给 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, ' 你的弟兄 无论 失落什么,或是驴, 或是衣服,你若遇见,都要这样 行,不 可 佯为不见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, '你若看见 弟兄 的牛 或 驴 跌倒 在路上,不可 佯为不见,总要 帮助他 拉起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, '「妇女 不 可 穿戴 男子 所穿戴的,男子 也不可 穿 妇女 的衣服,因为 这样 行 都是 耶和华─你 神 所憎恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, '「你若 路上 遇见 鸟 窝,或在 树上 或 在 地上,里头有雏 或有 蛋,母鸟 伏 在 雏上 或 在 蛋上,你不可 连母 带 雏 一并取去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, '总要 放 母,只可取 雏;这样 你 就可以享福,日子 得以长久。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, '「你若 建造 房屋,要在房上的 四围安 栏杆,免得 有人 从房上 掉下来,流血 的罪就归 于 你家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, '「不可 把两样种子 种 在你的葡萄园里,免得 你撒 种 所 结的 和葡萄园 的果子 都要充公。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, '不可 并用 牛、驴 耕地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, '不可 穿 羊毛、细麻 两样 搀杂料做的衣服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, '「你要在 所 披的 外衣 上四 围 做 䍁子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, '「人 若 娶 妻,与她 同房 之后恨恶她, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, '信 口 说 她,将丑 名 加 在她身上,说:『我娶了 这 女子,与她 同房,见 她 没有 贞洁的凭据』; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, '女子 的父 母 就要把 女子 贞洁的凭据 拿出来,带 到 本城 门 长老那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, '女子 的父亲 要对 长老 说:『我将 我的女儿 给 这 人 为妻,他恨恶她, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, ' 信 口 说她,说:我见 你的女儿 没有 贞洁的凭据;其实这就是 我女儿 贞洁的凭据。』父母就把那布 铺 在本城 的长老 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, '本 城 的长老 要拿住 那人,惩治 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, '并要罚 他 一百 舍客勒银子,给 女子 的父亲,因为 他将丑 名 加 在 以色列 的一个处女身上。女子仍作 他的 妻,终 身 不 可 休她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, '但这 事 若 是 真的,女子 没有 贞洁的凭据, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, '就要将 女子 带 到 她父 家 的门口,本城 的人 要用石头 将她打 死;因为 她在父 家 行了淫乱,在以色列 中做了 丑事。这样,就把那恶 从你们中间 除掉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, '「若 遇见 人 与 有 丈夫 的妇人 行淫,就要将奸 夫 淫妇 一 并 治死。这样,就把那恶 从以色列 中除掉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, '「若 有 处 女 已经许配 丈夫,有人 在城里 遇见她,与她 行淫, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, '你们就要把 这二人 带 到 本 城 门,用石头 打 死─ 女子 是因 为 虽在城里 却没有 喊叫; 男子 是因 为 玷污 别人 的妻。这样,就把那恶 从你们中间 除掉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, '「若有 男子 在田野 遇见 已经许配人 的女子, 强 与她 行淫,只要 将那 男子 治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, '但不 可 办 女子;她 本没有 该死 的罪, 这 事 就类乎 人 起来 攻击 邻舍,将他 杀了 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, '因为 男子是在田野 遇见 那已经许配人 的女子,女子喊叫,并无人 救 她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, '「若有 男子 遇见 没有 许配人 的 处 女,抓住她,与她 行淫,被人看见, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, '这 男子 就要拿五十 舍客勒银子 给 女子 的父亲;因 他玷污了这女子,就要 娶她为妻,终 身 不 可 休她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, '「人 不可 娶 继母为妻;不可 掀开  他父亲 的衣襟。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, '「凡外肾 受伤的,或被阉 割的,不可 入 耶和华 的会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, '「私生子 不可 入 耶和华 的会;他的子孙,直到 十 代,也不可 入 耶和华 的会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, '「亚扪人 或是摩押人 不可 入 耶和华 的会;他们的子孙,虽 过十 代,也永 不可 入 耶和华 的会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, '因 为 你们出 埃及的时候,他们没有 拿食物 和水 在路上 迎接 你们,又因 他们雇了 美索不达米亚 的毘夺人 比珥 的儿子 巴兰 来咒诅你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, '然而耶和华─你的 神 不 肯 听 从 巴兰,却 使 那咒诅的言语 变为 祝福的话,因为 耶和华─你的 神 爱你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, '你一 生一世 永 不可 求 他们的平安 和他们的利益。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, '「不可 憎恶 以东人,因为 他是 你的弟兄。不可 憎恶 埃及人,因为 你在他的地上 作过 寄居的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, '他们 第三 代 子 孙 可以 入 耶和华 的会。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, '「 你出 兵 攻打 仇敌,就要远避 诸 恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, '「你们中间,若 有 人 夜间 偶然梦遗, 不 洁净,就要出 到 营 外,不可 入 营; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, '到 傍晚的时候,他要用水 洗澡,及至日 落了 才可以入 营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, '「你在营 外 也该 定出 一个地方 作为 便所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, '在 你器械 之中当预备 一把锹, 你出营外 便溺 以后,用以 铲土,转身 掩盖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, '因为 耶和华─你的 神 常在你营 中 行走,要救护你,将仇敌 交 给你,所以你的营 理当 圣洁,免得 他见 你那里 有污秽,就离开  你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, '「若有 奴仆 脱了 主人的手,逃到你那里,你不可 将他交 付 他的主人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, '他必在你那里 与你 同住,在你的城邑 中,要由他 选择 一个 所 喜悦 的地方居住;你不可 欺负他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, '「以色列 的女子 中不可 有 妓女;以色列 的男子 中不可 有 娈童。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, '娼妓 所得的钱,或娈童(原文是狗)所得的价,你不可 带入 耶和华─你 神 的殿还 愿 ,因为 这两样 都是 耶和华─你 神 所憎恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, '「你借给你弟兄的,或是钱财 或是粮食,无论什么 可生 利 的物,都 不可 取利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, '借给外邦人 可以取利,只是借给你弟兄 不可 取利。这样,耶和华─你 神 必在 你 所 去 得为业 的地上 和你手里 所办的 一切事上 赐福与你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, '「 你向耶和华─你的 神 许 愿 ,偿还 不可 迟延;因为 耶和华─你的 神 必定 向你 追讨,你 不偿还就有 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, '你若 不 许愿 ,倒 无 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, '你嘴里 所出的,就是 你口中 应许 甘心所献的,要照 你向耶和华─你 神 所许的愿  谨守 遵行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, '「 你进了 邻舍 的葡萄园,可以随意 吃 饱了 葡萄,只是不可 装 在 器皿中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, ' 你进了 邻舍 站著的禾稼,可以用手 摘 穗子,只是不可 用镰刀 割取 禾稼。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, '「人 若 娶 妻 以后, 见 她 有什么不合理的 事, 不 喜悦她,就可以写 休 书 交 在她手中,打发她 离开 夫家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, '妇人离开  夫家以后,可以去 嫁 别 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, '后 夫 若恨恶她,写 休 书 交 在她手中,打发她 离开 夫家,或是 娶 她 为妻 的 后 夫 死了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, '打发她 去的 前 夫 不 可 在妇人 玷污 之后 再 娶她 为 妻,因为 这是 耶和华 所憎恶的;不可 使 耶和华─你 神 所 赐 为业 之地 被玷污了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, '「 新 娶 妻 之人 不可 从军 出征,也不可 托 讬 他 办理什么 公事,可以 在家 清闲  一 年,使他所 娶的 妻 快活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, '「不可 拿人 的全盘磨石 或是上磨石 作当头,因为 这是 拿人的命 作当头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, '「若 遇见 人 拐带 以色列 中的一个 弟兄,当奴才 待他,或是卖了他,那 拐带人的 就必治死。这样,便将那恶 从你们中间 除掉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, '「在大痲疯 的灾病上,你们要谨慎,照祭司 利未人 一切 所 指教 你们 的留意 遵行。我怎样 吩咐他们,你们要怎样 遵行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, '当记念 出 埃及后,在路上,耶和华─你 神 向米利暗 所 行的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, '「 你借 给邻舍,不拘 是什么,不可 进 他家 拿 他的当头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, '要站 在外面,等那 向你 借贷 的人 把 当头 拿 出来 交给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, '他 若 是 穷人,你不可 留他的当头 过夜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, '日 落的时候,总要 把 当头 还 他,使他用那件衣服 盖著睡觉,他就为你祝福;这在耶和华─你 神 面前 就是 你的 义了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, '「困苦 穷乏 的雇工,无论是你的弟兄 或是在你 城里 寄居的,你不可 欺负他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, '要当日 给 他工价,不可 等到 日 落─因为 他 穷苦, 把 心 放 在工价上─恐怕 他因你 求告 耶和华,罪 便归 你了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, '「不可 因 子 杀 父,也不可 因 父 杀 子;凡 被杀 的都为本身的罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, '「你不可 向寄居的 和孤儿 屈枉 正直,也不可 拿 寡妇 的衣裳 作当头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, '要记念 你在埃及 作过 奴仆。耶和华─你的 神 从那里 将你救赎,所以 我 吩咐你 这 样 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, '「 你在田间 收割 庄稼,若忘下 一捆,不可 回去 再取,要留 给寄居的 与孤儿 寡妇。这样,耶和华─你 神 必在你手里 所办的一切 事上 赐福与你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, ' 你打 橄榄树,枝上剩下的,不可 再打;要留 给寄居的 与孤儿 寡妇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, ' 你摘 葡萄园的葡萄,所剩下的,不可 再摘;要留 给寄居的 与孤儿 寡妇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, '你也要记念 你在埃及 地 作过 奴仆,所以 我 吩咐你 这 样 行。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, '「 人 若 有 争讼,来 听 审判,审判官就要定 义人 有理,定 恶人 有罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, '恶人 若 该 受 责打,审判官 就要叫他当面 伏在地上,按著 他的罪 照数 责打。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, '只可打 他四十下,不可 过数;若 过数,便是轻 贱 你的弟兄了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, '「牛 在场上踹谷的时候,不可 笼住牠的嘴。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, '「 弟兄 同 居,若死了 一个,没有 儿子,死人 的妻 不可 出 嫁 外 人,她丈夫的兄弟 当尽弟兄的本分,娶她 为妻,与她 同房。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, '妇人 生的 长子 必 归 死 兄 的名下,免得 他的名 在以色列 中涂抹了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, '那人 若 不 愿 意 娶 他哥哥的妻,他哥哥的妻 就要到 城门 长老那里,说:『我丈夫的兄弟 不肯 在以色列 中兴起 他哥哥的 名字,不 给我尽 弟兄的本分。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, '本城 的长老 就要召 那人 来问 他,他若执意 说:『我不 愿 意 娶她』, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, '他哥哥的妻 就要当著 长老 到 那人的跟前,脱了 他的鞋,吐唾沫 在他脸上, 说:『凡 不 为 哥哥 建立 家室 的都要这样 待 他。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, '在以色列中,他的名 必称为 脱 鞋 之家。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, '「若 有二人 争斗,这人 的妻 近前来,要救 她丈夫 脱离那打 她丈夫之人的手, 抓住 那人的下体, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, '就要砍断 妇人的手,眼 不可 顾惜她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, '「你囊中 不可 有 一大 一小 两样的 法码。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, '你家里 不可 有 一大 一小 两样的 升斗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, '当用 对准 公平 的法码, 公平 的升斗。这样,在 耶和华─你 神 所 赐 你 的地上,你的日子 就可以长久。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, '因为 行 非义之事 的人都是 耶和华─你 神 所憎恶的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, '「你要记念 你们出 埃及的时候,亚玛力人 在路上 怎样 待 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, '他们 在路上 遇见你,趁你 疲乏 困倦 击杀 你 尽 侭后边 软弱的人,并不 敬畏 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, '所以耶和华─你 神 使你 不被四围 一切的 仇敌扰乱,在耶和华─你 神 赐 你 为 业 的地上 得享平安。那时,你要将 亚玛力 的名号 从天 下 涂抹了,不可 忘记。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, '「 你进去 得了耶和华─你 神 所 赐 你 为 业 之地 居住, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, '就要从耶和华─你 神 赐 你 的 地上 将所 收 的各种 初熟 的土 产 取些来,盛 在筐子里,往 耶和华─你 神 所 选择 要立为 他名 的居所 去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, ' 见 当 时 作 祭司 的,对他 说:『我今日 向耶和华─你 神 明认, 我已来 到 耶和华 向我们列祖 起誓 应许 赐 给我们 的地。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, '祭司 就从你手里 取过 筐子来,放 在耶和华─你 神 的坛 前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, '你要 在耶和华─你 神 面前 说:『我祖 原是一个将亡 的亚兰人,下到 埃及 寄居。他人口 稀少,在那里 却成了 又大 又强、人数很多 的国民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, '埃及人 恶待 我们,苦害我们,将苦 工 加 在我们身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, '于 是我们哀求 耶和华─我们列祖的 神,耶和华 听见 我们的声音,看见 我们所受的困苦、 劳碌、 欺压, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, '他 就用大能 的手 和伸出来 的膀臂,并大 可畏 的事与神迹 奇事,领我们 出了埃及, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, '将我们领 进 这 地方,把 这 流 奶 与蜜 之地 赐 给我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, '耶和华啊, 现在 我把 你所 赐 给我 地上 初熟 的土产 奉了来。』随后你要把筐子放 在耶和华─你 神 面前,向 耶和华─你的 神 下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, '你 和利未人,并 在你们中间 寄居的,要因耶和华─你 神 所 赐 你 和你家 的一切 福分 欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, '「 每逢三 年,就是十分取一 之年,你取 完了 一切 土产 的十分之一,要分给 利未人 和寄居的,与孤儿 寡妇,使他们在你城中 可以吃 得饱足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, '你又要在耶和华─你 神 面前 说:『我已将圣物 从 我家 里拿出来, 给了 利未人 和寄居的,与孤儿 寡妇,是照你所 吩咐我 的一切 命令。你的命令 我都没有 违背,也没有 忘记。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, '我守丧的时候,没有 吃这圣物;不洁净的时候,也没有 拿出来,又没有 为死人 送去。我听从了 耶和华─我 神 的话,都照 你所 吩咐 的行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, '求你从 天上、你的圣 所 垂看,赐福 给 你的百姓 以色列 与 你所 赐 给我们 的地,就是 你向我们列祖 起誓 赐我们流 奶 与蜜 之地。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, '「耶和华─你的 神 今 日 吩咐你 行 这些 律例 典章,所以你要尽 心 尽 性 谨守 遵行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, '你今日 认 耶和华 为 你的 神,应许遵行 他的道,谨守 他的律例、诫命、典章,听从 他的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, '耶和华 今日 照他所 应许 你的,也认你 为 他的 子民,使你谨守 他的一切 诫命, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, '又使你得 称赞、美名、尊荣,超乎 他所 造的 万 民 之上,并照他所 应许的 使你归耶和华─你 神 为 圣洁的 民。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, '摩西 和以色列 的众长老 吩咐 百姓 说:「你们要遵守 我 今日 所 吩咐 的一切 诫命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, ' 你们过 约旦河,到了 耶和华─你 神 所 赐 给你 的地,当 天 要立起 几块大 石头,墁上 石灰, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, '把 这 律法 的一切 话 写 在石头上。你过了河,可以 进入 耶和华─你 神 所 赐 你 流 奶 与蜜 之地,正如 耶和华─你列祖之 神 所应许 你的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, '你们过了 约旦河,就要 在以巴路 山上 照我 今日 所 吩咐的,将 这些 石头 立起来,墁上 石灰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, '在那里 要为耶和华─你的 神 筑 一座石 坛;在 石头上不可 动 铁器。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, '要用没有凿过 的石头 筑 耶和华─你 神 的坛,在坛上 要将燔祭 献 给耶和华─你的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, '又要献 平安祭,且在那里 吃,在耶和华─你的 神 面前 欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, '你要将 这 律法 的一切 话 明明地 写 在 石头上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, '摩西 和祭司 利未人 晓谕 以色列 众人 说:「以色列啊,要默默静 听。你今 日 成为 耶和华─你 神 的百姓了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, '所以要听从 耶和华─你 神 的话,遵行 他的诫命 律例,就是 我 今日 所吩咐你的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, '当 日,摩西 嘱咐 百姓 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, '「你们过了 约旦河,西缅、利未、犹大、以萨迦、约瑟、便雅悯 六个支派的人都要 站 在 基利心 山上 为 百姓 祝福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, '流便、迦得、亚设、西布伦、但、拿弗他利 六个支派的人都要 站 在以巴路 山上 宣布 咒诅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, '利未人 要 向 以色列 众 人 高 声 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, '「『有人 制造 耶和华 所憎恶的偶像,或雕刻,或铸造,就是工匠 手 所做的,在暗中 设立,那人 必受咒诅!』百姓 都 要答应 说:『阿们!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, '「『轻慢 父 母的,必受咒诅!』百姓 都 要说:『阿们!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, '「『挪移 邻舍 地界的,必受咒诅!』百姓 都 要说:『阿们!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, '「『使瞎子 走差 路的,必受咒诅!』百姓 都 要说:『阿们!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, '「『向寄居的 和孤儿 寡妇 屈枉 正直的,必受咒诅!』百姓 都 要说:『阿们!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, '「『与 继母 行淫的,必受咒诅!因为 掀开  他父亲 的衣襟。』百姓 都 要说:『阿们!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, '「『与 兽 淫合的,必受咒诅!』百姓 都 要说:『阿们!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, '「『与 异母同父,或 异父同母 的姊妹 行淫的,必受咒诅!』百姓 都 要说:『阿们!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, '「『与 岳母 行淫的,必受咒诅!』百姓 都 要说:『阿们!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, '「『暗中 杀 人的,必受咒诅!』百姓 都 要说:『阿们!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, '「『受 贿赂 害死 无辜 之人的,必受咒诅!』百姓 都 要说:『阿们!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, '「『 不 坚守 遵行 这 律法 言语的,必受咒诅!』百姓 都 要说:『阿们!』   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, '「 你若 留意 听从 耶和华─你 神 的话,谨守 遵行 他的一切 诫命,就是 我 今日 所吩咐你的,他 必使 你超乎 天下 万 民 之上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, '你若 听从 耶和华─你 神 的话,这 以下的 福 必追随你,临 到你身上: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, '你 在城里 必蒙福, 在田间 也必蒙福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, '你身 所生的,地 所产的,牲畜 所下的,以及牛 犊、羊 羔,都必蒙福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, '你的筐子 和你的抟面 麺盆 都必蒙福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, '你 出 也蒙福, 入 也蒙福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, '「仇敌 起来 攻击你,耶和华 必使 他们 在你面前 被你杀败;他们从一条 路 来 攻击你,必从七条 路 逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, '在你仓房里,并你手 所办的 一切事上,耶和华 所命的 福 必临到你。耶和华─你 神 也要在所 给 你 的地上 赐福与你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, '你若 谨守 耶和华─你 神 的诫命,遵行 他的道,他 必照著向你 所 起的誓 立你 作为自己的 圣 民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, '天下 万 民 见 你归 在 耶和华 的名下,就要惧怕 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, '你在 耶和华 向你列祖 起誓 应许赐 你 的地上, 他 必使你 身 所生的,牲畜 所下的,地 所产的,都绰绰有余 馀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, '耶和华 必为你 开  天上的 府库,按时 降 雨 在你的地上。在 你手里 所办的一切 事 上赐福与你。你 必借 给许多 国民,却不致 向他们借贷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, '你若 听 从 耶和华─你 神 的诫命,就是 我 今日 所吩咐你的,谨守 遵行,不 偏 左 右,也不随 从 事奉 别 神,耶和华 就必使你 作首 不 作尾,但 居 上 不 居 下。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, '「 你若 不 听从 耶和华─你 神 的话,不谨守 遵行 他的一切 诫命 律例,就是 我 今日 所吩咐你的,这 以下的 咒诅 都必追随你,临 到你身上: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, '你 在城里 必受咒诅, 在田间 也必受咒诅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, '你的筐子 和你的抟面 麺盆 都必受咒诅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, '你身 所生的,地 所产的,以及牛 犊、羊 羔,都必受咒诅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, '你 出 也受咒诅, 入 也受咒诅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, '耶和华 因 你行 恶 离弃他,必在你手里 所 办的 一切 事上,使 咒诅、 扰乱、 责罚 临到你,直到 你被毁灭, 速速地 灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, '耶和华 必使 瘟疫 贴 在你身上,直到 他将你 从 所 进去 得为业 的地上 灭绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, '耶和华 要用痨病、热病、火症、疟疾、刀剑、旱风(或译:干旱)、霉烂 攻击你。这都要追赶你,直到 你灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, '你 头 上 的天 要变为 铜, 脚下 的地 要变为铁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, '耶和华 要 使 那降在你地上 的雨 变为尘 沙,从 天 临 在你身上,直到 你灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, '「耶和华 必使你 败 在仇敌 面前,你从一条 路 去 攻击 他们,必从 七条 路 逃跑。你必 在天下 万 国 中抛来抛去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, '你的尸首 必给空中的 飞鸟 和地上 的走兽 作 食物,并无人 哄赶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, '耶和华 必用埃及人 的疮 并痔疮、牛皮癣 与疥 攻击你,使 你不 能 医治。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, '耶和华 必用癫狂、眼瞎、心 惊 攻击你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, '你必 在午间 摸索,好像 瞎子 在暗中 摸索一样。 你所行的 必不 亨通,时常 遭遇 欺压、抢夺,无人 搭救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, '你聘定了 妻,别 人 必与她同房;你建造 房屋,不得 住 在其内;你栽种 葡萄园,也不得 用其中的果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, '你的牛 在你眼前 宰了,你必不得 吃 牠的肉;你的驴 在你眼前 被抢夺,不得 归还;你的羊 归了 仇敌,无人 搭救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, '你的儿 女 必归 与别 国的民;你的眼目 终 日 切望,甚至失明,你手中 无 力拯救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, '你的土 产 和 你劳碌得来的,必被你所 不 认识 的国民 吃尽。你时常 被欺负,受压制, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, '甚至你因眼中 所 看见 的,必致 疯狂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, '耶和华 必攻击你,使你膝 上 腿 上,从脚 掌 到 头顶,长毒 疮 无 法 医治。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, '「耶和华 必将你 和你 所 立 的王 领 到 你 和你列祖 素不 认识 的国去;在那里 你必事奉 木头 石头 的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, '你在耶和华 领 你到的 各 国中,要 令人惊骇、笑谈、讥诮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, '你带 到田间 的种子 虽多,收进来的 却少,因为 被蝗虫 吃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, '你栽种、修理 葡萄园,却不得 收葡萄,也不得 喝 葡萄酒,因为 被虫子 吃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, '你 全 境 有 橄榄树,却不得 其油 抹身,因为 树上的橄榄 不熟自落了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, '你生 儿 养女,却不 算是 你的,因为 必被掳 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, '你所有的 树木 和你地里 的出产 必被蝗虫 所吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, ' 在你中间 寄居的,必渐渐上升,比你 高 而又高;你 必渐渐下降,低 而又低。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, '他 必借给你,你 却不能 借给他;他 必作 首,你 必作 尾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, '这 一切 咒诅 必 追随你,赶上你,直到 你灭亡;因为 你不 听从 耶和华─你 神 的话,不遵守 他所 吩咐 的诫命 律例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, '这些咒诅必在你 和你后裔 的身上成为 异迹 奇事,直到 永远! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, '「因为 你富有的时候,不 欢 心 乐意地 事奉 耶和华─你的 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, '所以你必在饥饿、干渴、赤露、缺乏 之中事奉 耶和华 所 打发来 攻击你 的仇敌。他必把铁 轭 加 在 你的颈项上,直到 将你 灭绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, '「耶和华 要从远方、地 极 带 一国的民,如 鹰 飞来 攻击你。这 民 的言语,你不 懂得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, '这民 的面貌 凶恶, 不 顾恤 年老的,也不 恩待 年少的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, '他们必吃 你牲畜 所下的 和你地土 所产的,直到 你灭亡。你的五谷、新酒,和油,以及牛犊、羊羔, 都不 给你 留下,直到 将你 灭绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, '他们必将你 困 在你各 城里,直到 你 所 倚靠、高大 坚固的 城墙 都被攻塌。他们必将你 困 在耶和华─你 神 所 赐 你 遍 地 的各 城里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, '你在 仇敌 围困 窘迫之中,必吃 你本身 所生的,就是 耶和华─你 神 所赐 给你 的儿 女 之肉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, '你们中间,柔 弱 娇嫩 的人 必恶 眼 看他弟兄 和他怀中 的妻,并他 余 馀剩 的儿女; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, '甚至在你 受 仇敌 围困 窘迫的 城中,他要吃 儿女 的 肉,不肯分一点 给 他的亲人,因为 他一 无 所剩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, '你们中间,柔弱 娇嫩的妇人,是 因娇嫩 柔弱 不 肯 把 脚 踏 地的,必恶 眼 看她怀中 的丈夫 和她的儿 女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, '她两腿 中间 出来 的婴孩 与她所 要生 的儿女,她因缺乏 一切 就要 在你 受 仇敌 围困 窘迫 的城中 将他们暗暗地 吃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, '「这 书上 所写 律法 的一切 话 是叫你敬畏 耶和华─你 神 可荣 可畏 的名。你若 不 谨守 遵行,耶和华 就必将 奇 灾,就是 至大 至长 的灾,至重 至久 的病,加在你和你后裔的身上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, '也必使 你所 惧怕、埃及人的 病 都临 到你,贴 在你身上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, ' 又 必将 没有 写 在这 律法 书 上的各样 疾病、 灾殃 降 在你身上,直到 你灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, '你们先前 虽然像天上 的星 那样多,却因 不 听从 耶和华─你 神 的话,所 剩 的人数 就稀少了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, '先前 耶和华 怎样 喜悦 善待 你们,使你们 众多, 也要照样 喜悦 毁灭 你们,使你们 灭亡;并且你们 从 所 要进去 得的 地上 必被拔除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, '耶和华 必使你们分散 在万 民中,从地 这边 到 地 那边,你必在那里 事奉 你 和你列祖素 不 认识、木头 石头 的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, '在那些 国中,你必不 得安逸,也不 得 落 脚之地;耶和华 却使 你 在那里 心中 跳动,眼目 失明,精神 消耗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, '你的性命 必 悬悬 无定;你昼 夜 恐惧,自料性命 难 保。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, '你因心里 所 恐惧的,眼中 所 看见 的,早晨 必说,巴不得 到 晚上才好;晚上 必说,巴不得 到 早晨才好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, '耶和华 必使你坐船 回 埃及去,走我曾 告诉 你 不得 再 见 的路;在那里 你必卖己身 与仇敌 作奴 婢,却无人 买 。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, '这是 耶和华 在摩押 地 吩咐 摩西 与 以色列 人 立 约 的话,是在他和他们 于 何烈山 所 立的 约 之外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, '摩西 召了 以色列 众人来,对他们 说:「耶和华 在埃及 地,在你们眼前 向法老 和他众 臣仆,并他全 地 所 行 的一切事,你们 都看见了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, '就是 你亲眼 看见 的大 试验 和神迹,并那些 大 奇事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, '但耶和华 到 今 日 没有 使 你们 心 能明白,眼 能看见,耳 能听见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, '我领 你们 在旷野 四十 年,你们身上的 衣服 并没有 穿破,脚上 的鞋 也没有 穿坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, '你们没有 吃 饼,也没有 喝 清酒 浓酒。这要使 你们知道, 耶和华是你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, '你们来 到 这 地方,希实本 王 西宏、巴珊 王 噩 都出来 与我们交 战 ,我们就击杀了他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, '取了 他们的地 给 流便支派、迦得支派,和玛拿西 半 支派 为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, '所以你们要谨守 遵行 这 约 的话,好叫 你们在一切 所 行 的事上亨通。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, '「今日,你们 的首领、族长(原文是支派)、长老、官长、以色列的 男丁,你们的妻子 儿女, 和营 中 寄居的,以及为你们劈 柴 挑 水的人,都 站在 耶和华─你们的 神 面前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, '为要你顺从 耶和华─你 神 今日 与你 所 立 的约, 向你所起的誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, '这样,他要照他向你 所 应许的话,又向你列祖 亚伯拉罕、以撒、雅各 所 起的誓,今日 立 你 作他的 子民,他 作 你的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, '我 不 但 与你们 立 这 约,起 这 誓, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, ' 凡 与我们 一同 站 在耶和华─我们 神 面前的,并 今日 不 在我们 这里的人,我也与他们立这约,起这誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, '「 我们 曾住过 埃及 地,也 从 列国 经过;这是 你们 知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, '你们也看见 他们中间 可憎之物,并 他们木、石、金、银 的 偶像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, '惟恐 你们中间,或男 或 女,或 族长 或 支派长,今日 心里 偏离 耶和华─我们的 神,去 事奉 那些 国的 神;又怕 你们中间 有 恶根 生出 苦菜 和茵𫈟来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, ' 听见 这 咒诅 的话,心里 仍是自夸 说:『我虽然 行事 心里 顽梗, 连累 众人,却还是 平安。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, '耶和华 必 不 饶恕 他; 耶和华 的怒气 与愤恨 要向他发作,如烟冒出,将这 书上 所写的 一切 咒诅 都加 在他身上。耶和华 又要从天 下 涂抹 他的名, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, ' 也必照著写在 律法 书上、约 中的一切 咒诅 将他从以色列 众 支派 中分别出来,使他受祸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, ' 你们的后 代,就是 以后 兴起来 的子孙,和 远 方 来 的外人,看见 这 地 的灾殃,并 耶和华 所 降与 这地 的疾病, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, '又看见遍 地 有硫磺,有盐卤,有火迹,没有 耕种,没有 出产,连草 都 不 生长─好像耶和华 在忿 怒 中所 倾覆 复 的所多玛、蛾摩拉、押玛、洗扁一样─ ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, '所看见的人,连万 国人,都必问说:『耶和华 为 何 向此 地 这样 行呢?这样 大 发烈 怒 是什么意思呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, '人必回答说:『是因 这地的人 离弃了 耶和华─他们列祖的 神,领 他们 出埃及 地 的时候与他们 所 立 的约, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, '去 事奉 敬拜素 不 认识 的 别 神,是耶和华所未 曾给他们 安排的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, '所以耶和华 的怒气 向这 地 发作,将 这 书上 所写的 一切 咒诅 都降 在这地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, '耶和华 在怒气、忿怒、大 恼恨 中将他们从 本地 拔出来,扔 在 别的 地上,像今 日一样。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, '「隐秘的事 是属耶和华─我们 神的;惟有明显的事 是永远 属我们 和我们子孙的,好叫我们遵行 这 律法 上的一切 话。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, '「 我所 陈明 在你面前 的这 一切 咒诅 都临 到你身上;你在耶和华─你 神 追赶你到的 万 国中必 心里 追念 祝福的话; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, '你 和你的子孙 若尽 心 尽 性 归 向 耶和华─你的 神,照著 我 今日 一切 所 吩咐 的听从 他的话; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, '那时,耶和华─你的 神 必怜恤你,救回 你这被掳的子民;耶和华─你的 神 要回转过来,从分散你 到的 万 民 中将你招聚回来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, '你被赶散的人,就 是 在天 涯的,耶和华─你的 神 也必从那里 将你招聚 回来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, '耶和华─你的 神 必领你 进入 你列祖 所 得的 地,使你可以得著;又必善待你,使你的人数比你列祖 众多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, '耶和华─你 神 必将 你心里 和 你后裔 心里 的污秽除掉,好叫你尽 心 尽 性 爱 耶和华─你的 神,使 你可以存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, '耶和华─你的 神 必将 这 一切 咒诅 加 在 你仇敌 和 恨恶你、 逼迫你的人身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, '你 必归回,听从 耶和华 的话,遵行 他的一切 诫命,就是 我 今日 所吩咐你的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, '你若 听从 耶和华─你 神 的话,谨守 这 律法 书 上所写 的诫命 律例,又 尽 心 尽 性 归 向 耶和华─你的 神,他必使你手里 所办的 一切事,并你身 所生的,牲畜 所下的,地土 所产的,都绰绰 有余 馀;因为 耶和华 必再 喜悦 你,降福与你,像 从前喜悦 你列祖一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, '「 我 今日 所 吩咐你的 诫命 不 是 你难行的,也不 是 离你 远的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, '不 是 在天上,使你说:『谁 替我们 上 天 取下来,使我们听见 可以遵行呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, '也不 是 在海 外,使你说:『谁 替我们 过 海 取了来,使我们听见 可以遵行呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, '这话 却 离你 甚 近,就在你口中,在你心里,使你可以遵行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, '「看哪,我今日 将 生 与 福, 死 与 祸,陈明 在你面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, ' 吩咐你 爱 耶和华─你的 神,遵行 他的道,谨守 他的诫命、律例、典章,使你可以存活,人数增多,耶和华─你 神 就必在你 所 要进去 得为业 的地上 赐福与你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, '倘若 你心里 偏离,不肯 听从,却被勾引 去敬拜 事奉 别 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, '我今日 明明告诉 你们, 你们必要 灭亡;在 你 过 约旦河、进去 得为业 的地上, 你的日子 必不 长久。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, '我今日 呼 天 唤 地 向你 作见证;我将生 死 祸 福 陈明 在你面前,所以你要拣选 生命,使 你 和你的后裔 都得存活; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, '且爱 耶和华─你的 神,听从 他的话,专靠 他;因为 他是 你的生命,你的日子 长久也在乎他。这样,你就可以在 耶和华 向你列祖 亚伯拉罕、以撒、雅各 起誓 应许所 赐 的地上 居住。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, '摩西 去 告诉 以色列 众人 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, '说:「我 现在 一百 二十 岁了,不 能 照常 出 入;耶和华 也曾对我 说:『你必不得 过 这 约旦河。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, '耶和华─你们的 神 必 引导你们 过去, 将 这些 国民 在你们面前 灭绝,你们就得他们的地。约书亚 必 引导你们 过去,正如 耶和华 所说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, '耶和华 必待 他们,如同 从前待 他所 灭绝 的亚摩利 二王 西宏 与噩 以及他们的国一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, '耶和华 必将他们交 给你们;你们要照我所 吩咐 的一切 命令 待 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, '你们当刚强 壮胆,不要 害怕,也不要 畏惧 他们,因为 耶和华─你的 神 和你 同去。他必不 撇下你,也不 丢弃你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, '摩西 召了 约书亚来,在以色列 众人 眼前 对他 说:「你当刚强 壮胆!因为,你 要和 这 百姓 一同进 入 耶和华 向他们列祖 起誓 应许所 赐 之地;你 也要使他们 承受那地为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, '耶和华 必 在你前面 行;他 必 与你同在,必不 撇下你,也不 丢弃你。不要 惧怕,也不要 惊惶。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, '摩西 将 这 律法 写出来,交 给 抬 耶和华 约 柜 的祭司 利未 子孙 和 以色列 的众 长老。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, '摩西 吩咐 他们 说:「每逢七 年 的末一年,就在豁免 年 的定期 住棚 节的时候, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, '以色列 众人 来 到耶和华─你 神 所 选择 的地方 朝见 他。那时,你要在以色列 众人 面前 将 这 律法 念 给他们听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, '要招聚 他们 男、女、孩子,并 城里 寄居的,使 他们听,使 他们学习,好敬畏 耶和华─你们的 神,谨守、遵行 这 律法 的一切 话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, '也使 他们未 曾晓得 这律法的儿女 得以听见,学习 敬畏 耶和华─你们的 神,在 你们 过 约旦河 要得为业 之 地, 存活 的 日子,常常这样行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, '耶和华 对 摩西 说:「 你的死 期 临近了;要召 约书亚来,你们二人站 在会 幕里,我好嘱咐他。」于 是摩西 和约书亚 去 站 在会 幕里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, '耶和华 在会幕 里云 柱 中显现,云 柱 停 在 会幕 门以上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, '耶和华 又对 摩西 说:「你 必和 你列祖 同睡。这 百姓 要起来,在他们 所 要去 的地上,在那地的人中,随从 外邦 神 行邪淫,离弃我,违背 我与他们 所 立 的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, '那 时,我的怒气 必向他们 发作;我也必离弃他们,掩 面 不顾他们,以致他们 被吞灭,并有许多 的祸患 灾难 临到他们。那 日 他们必说:『这些 祸患 临到我们,岂不是 因我们的 神 不 在我们中间吗?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, '那 时,因 他们偏 向 别 神 所 行的 一切 恶,我 必定 掩 面不顾他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, '现在你要 写 一篇歌,教导 以色列 人,传给他们,使 这 歌 见证 他们的不是; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, '因为 我将他们领 进 我向他们列祖 起誓 应许 那流 奶 与蜜 之地,他们在那里吃 得饱足,身体肥胖,就必偏 向 别 神,事奉他们,藐视我,背弃 我的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, '那时,有许多 祸患 灾难 临到 他们,这 歌 必在他们面前 作 见证, 他们后裔 的口中 必念诵不 忘。 我未 领他们 到 我所 起誓 应许之地 以先,他们 所 怀的 意念 我都知道了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, '当 日 摩西 就写了 一篇歌,教导 以色列 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, '耶和华嘱咐 嫩 的儿子 约书亚 说:「你当刚强 壮胆,因为 你 必领 以色列 人 进 我所 起誓 应许他们 的地;我 必 与你同在。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, '摩西 将 这 律法 的话 写在 书上,及至 写 完了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, ' 就吩咐 抬 耶和华 约 柜 的利未人 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, '「 将 这 律法 书 放 在耶和华─你们 神 的约 柜 旁,可以在 那里 见证 以色列人的不是; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, '因为 我 知道 你们是悖逆的, 是硬著 颈项的。 我今日 还 活著 与你们同在,你们尚且 悖逆 耶和华,何况 我死 后呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, '你们要将 你们支派 的众 长老 和官长 都招聚 了来,我好将 这些 话 说 与他们听,并呼 天 唤 地 见证 他们的不是。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, ' 我知道 我死 后,你们必 全然 败坏,偏离 我所 吩咐 你们 的道, 行 耶和华 眼中 看为恶的事,以手 所做的 惹他发怒;日 后 必有祸患 临到 你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, '摩西 将 这 一篇歌 的话都 说 与以色列全 会 众 听。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, '诸天哪,侧耳,我要说话;愿 地 也听 我口中 的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, '我的教训 要淋漓 如雨;我的言语 要滴落 如露,如细雨 降在 嫩草上,如甘霖 降在 菜蔬中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, ' 我要宣告 耶和华 的名;你们要将大德 归与我们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, '他是磐石,他的作为 完全; 他所行的 无不 公平,是诚实 无 伪的 神,又 公义,又正直。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, '这乖僻 弯曲 的世代 向他 行事邪僻;有这弊病 就不是 他的儿女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, '愚昧 无 知 的民哪,你们这样 报答 耶和华吗?他 岂不是 你的父、将你买 来的吗?他 是制造你、建立你的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, '你当追想 上古 之日,思念 历 代 之年;问 你的父亲,他必指示你;问你的长者,他必告诉 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, '至高者 将地业赐 给列邦,将世 人 分开 ,就照以色列 人 的数目 立定 万民 的疆界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, '耶和华 的分 本是 他的百姓;他的产业 本是雅各。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, '耶和华遇见他 在旷野─荒凉 野兽吼叫 之地,就环绕他,看顾他,保护他,如同保护眼中 的瞳人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, '又如鹰 搅动 巢窝,在 雏鹰 以上两翅 搧 展,接取雏鹰,背 在 两翼之上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, '这样,耶和华 独自 引导他,并无 外邦 神 与他同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, '耶和华使他乘 驾 地 的高处,得吃 田间 的土产;又使他从磐石 中咂 蜜,从坚 石 中吸油; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, '也吃牛 的奶油,羊 的奶,羊羔 的 脂油,巴珊 所出的 公绵羊 和山羊,与 上好的 麦子,也喝 葡萄 汁 酿的酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, '但耶书仑  渐渐肥胖,粗壮,光润,踢跳,奔跑, 便离弃 造他的 神,轻看 救他 的磐石; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, '敬拜别神,触动 神的愤恨,行可憎恶的事,惹了他的怒气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, '所祭祀 的鬼魔 并非 真神,乃是素不 认识 的神,是近来 新 兴的,是你列祖 所不 畏惧的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, '你轻忽 生 你的磐石,忘记 产你的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, '耶和华 看见 他的儿 女 惹动他,就厌恶他们,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, '我要向他们 掩 面,看 他们的结局 如何。他们 本是 极乖僻 的族类,心中 无 诚实 的儿女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, '他们以那「不算为 神」的触动我的愤恨,以虚无 的神惹了我的怒气。我也要以那「不 成子民」的触动他们的愤恨,以愚昧 的国民 惹了他们的怒气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, '因为 在我怒中 有火 烧起,直 烧到 极深 的阴间,把地 和地的出产 尽都焚烧,山 的根基 也烧著了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, '我要将祸患 堆 在他们身上,把我的箭 向他们 射尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, '他们必因饥饿 消瘦,被炎热 苦毒 吞 灭。我要打发 野兽 用牙齿 咬他们,并土中 腹行的,用 毒气害他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, '外头 有刀剑,内室 有惊恐,使人丧亡,使 少男、 童女、吃奶的、 白发 的,尽都灭绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, '我说,我必将他们分散远方,使他们的名号 从人间 除灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, '惟 恐 仇敌 惹动我,只怕 敌人 错看, 说:是我们手 的能力,并非 耶和华 所行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, '因为 以色列民 毫无 计谋, 心中 没有 聪明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, '惟愿  他们有智慧,能明白 这事,肯思念 他们的结局。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, '若 不是 他们的磐石 卖了他们,若不是耶和华 交出他们,一人 焉能 追赶 他们千人?二人 焉能使万人 逃跑呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, '据我们的仇敌 自己断定, 他们的磐石 不 如我们的磐石。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, ' 他们的葡萄树 是所多玛 的葡萄树,蛾摩拉 田园所生的;他们的 葡萄 是毒 葡萄,全挂 都是苦的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, '他们的酒 是大蛇 的毒气,是虺蛇 残害的恶 毒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, '这 不 都是积蓄 在我这里,封锁 在我府库中吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, '他们失 脚 的时候,伸冤 报应 在我;因 他们遭灾 的日子 近了;那要临在 他们身上 的必速速来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, ' 耶和华 见 他百姓毫无 能力,无论困住的、自由的 都没有剩下,就 必为他们 伸冤,为 他的仆人 后悔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, '他必说: 他们的神,他们所投靠的 磐石, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, '就是 向来吃 他们祭牲 的脂油,喝 他们奠祭 之酒的,在哪里呢?他可以兴起 帮助你们, 护卫 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, '你们如今 要知道: 我,惟有我 是 神;在我以外 并无 别神。我 使人死,我使人活;我损伤,我 也医治,并无人 能从我手中 救出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, ' 我向 天 举 手 说:我 凭我的永 生起誓: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, '我若 磨 我闪亮 的刀,手 掌 审判之权,就必 报复 我的敌人,报应 恨我的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, '我要使我的箭 饮血 饮醉,就是被杀 被掳 之人的血。我的刀 要吃 肉,乃是仇敌中 首领 之头的肉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, '你们外邦人 当与主的百姓 一同欢呼;因 他要伸 他仆人 流血的冤,报 应 他的敌人,洁净 他的地,救赎他的百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, '摩西 和嫩 的儿子 约书亚 去 将 这 歌 的一切 话 说 给百姓 听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, '摩西 向 以色列 众人 说 完了 这 一切 的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, '又说:「我 今日 所 警教 你们 的,你们都 要放 在心上; 要吩咐 你们的子孙 谨守 遵行 这 律法上的 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, '因为 这 不是 虚空、与你们 无关的事,乃 是 你们的生命;在 你们 过 约旦河 要 得为业 的地上 必因这 事 日子 得以长久。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, '当 日,耶和华 吩咐 摩西 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, '「你上 这 亚巴琳 山 中的尼波 山去, 在摩押 地与 耶利哥 相 对,观看 我 所 要赐 给以色列 人 为业 的迦南 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, '你必死 在你 所 登的 山上,归你列祖(原文是本民)去,像 你哥哥 亚伦 死 在何珥 山上,归 他的列祖一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, '因 为 你们在寻 的旷野,加低斯的米利巴 水,在以色列 人 中 没有 尊我 为圣, 得罪了 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, '我 所 赐 给以色列 人 的地, 你可以远远地 观看,却 不 得进去。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, '以下是 神 人 摩西 在未死 之先 为 以色列 人 所 祝 的福: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, '他说:耶和华 从西奈 而来,从西珥 向他们 显现,从巴兰 山 发出光辉,从万万 圣者 中来临,从他右手 为百姓 传出烈火 的律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, ' 他疼爱 百姓;众 圣徒 都在他手中。他们 坐 在他的脚下,领受 他的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, '摩西 将律法 传 给我们,作为雅各 会众 的产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, '百姓 的众首领,以色列 的各支派,一同 聚会的时候,耶和华(原文是他)在耶书仑  中为 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, '愿 流便 存活,不致 死亡;愿 他 人数 不致稀少。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, ' 为犹大 祝福说:求耶和华 俯听 犹大 的声音,引导他 归于  本族;他曾用手 为自己 争战 ,你必 帮助 他攻击敌人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, '论利未 说:耶和华啊,你的土明 和乌陵 都在你的虔诚 人那里。 你在玛撒 曾试验他,在 米利巴 水 与他争论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, '他论自己的父 母 说:我未 曾看见;他也不 承认 弟兄,也不 认识 自己的儿女。这是因 利未人遵行 你的话,谨守 你的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, '他们要将你的典章 教训 雅各,将你的律法 教训以色列。他们要把香 焚 在你面前,把全牲的燔祭 献在 你的坛上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, '求耶和华 降福 在他的财物上,悦纳 他手里 所办的事。那些起来 攻击他和恨恶他的人,愿 你刺透 他们的腰,使他们不得 再起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, '论便雅悯 说:耶和华 所亲爱的 必同耶和华 安然 居住;耶和华终 日 遮蔽 他,也住 在 他两肩之中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, '论约瑟 说:愿 他的地 蒙耶和华 赐福,得天上 的宝物、甘露,以及地里 所藏的 泉水; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, '得太阳 所晒熟的美 果,月亮 所养成 的宝物; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, '得上古 之山 的至宝,永世 之岭 的宝物; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, '得地 和其中所充满 的宝物,并住 荆棘中 上主的喜悦。愿 这些福都归于  约瑟 的头上,归于 那与弟兄 迥别 之人的顶上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, '他为牛群 中头生的,有威严;他的角 是野牛 的角,用以抵触 万 邦,直到地 极。这角是 以法莲 的万万, 玛拿西 的千千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, '论西布伦 说:西布伦哪,你出外 可以欢喜。以萨迦啊,在你帐棚里可以快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, '他们要将列邦 召到 山上,在那里 献 公义 的祭;因为 他们要吸取 海里 的丰富,并沙中 所藏 的珍宝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, '论迦得 说:使迦得 扩张 的应当称颂!迦得住 如母狮;他撕裂 膀臂,连 头顶也撕裂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, '他为自己 选择 头一段地,因 在那里 有设立律法者 的分 存留。他与百姓 的首领 同来;他施行 耶和华 的公义 和耶和华与 以色列 所立的典章。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, '论但 说:但 为小 狮子,从 巴珊 跳出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, '论拿弗他利 说:拿弗他利啊,你足沾 恩惠,满得 耶和华 的福,可以得 西方 和南方为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, '论亚设 说:愿 亚设 享受多子 的福乐,得 他弟兄 的喜悦,可以把脚 蘸 在油中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, '你的门闩(或译:鞋)是铜的,铁的。你的日子如何,你的力量也必如何。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, '耶书仑 哪,没有能比 神的。他为帮助你,乘在 天空,显其威荣,驾行穹苍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, '永生的 神 是你的居所;他永久 的膀臂 在你以下。他在你前面 撵出 仇敌,说:毁灭吧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, '以色列 安然 居住;雅各 的本源 独 居 五谷 新酒 之地。他的天 也 滴 甘露。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, '以色列啊,你是有福的!谁 像你 这蒙耶和华 所拯救 的百姓呢?他是你的盾牌,帮助你,是 你威荣 的刀剑。你的仇敌 必投降 你;你 必踏 在 他们的高处。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, '摩西 从摩押 平原 登 尼波 山,上了那 与耶利哥 相 对 的毘斯迦 山顶。耶和华 把 基列 全 地 直到 但, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, ' 拿弗他利 全地, 以法莲、玛拿西 的地, 犹大 全 地 直到 西 海, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, ' 南地 和 棕树 城 耶利哥 的平原,直到 琐珥,都指给他看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, '耶和华 对他 说:「这就是 我向亚伯拉罕、以撒、雅各 起誓 应许之 地,说:『我必将这地赐 给你的后裔。』现在我使你眼睛 看见了,你却不得 过到那里 去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, '于 是,耶和华 的仆人 摩西 死 在摩押 地,正如 耶和华 所说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, '耶和华将他 埋葬 在摩押 地、伯‧毘珥 对面 的谷中,只是到 今 日 没有 人 知道 他的坟墓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, '摩西 死 的时候年 一百 二十 岁;眼目 没有 昏花,精神 没有 衰败。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, '以色列 人 在摩押 平原 为 摩西 哀哭了 三十 日,为摩西 居丧 哀哭 的日子 就满了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, '嫩 的儿子 约书亚;因为 摩西 曾按 手 在他头上,就被智慧 的灵 充满,以色列 人 便听 从他,照著 耶和华 吩咐 摩西 的行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, '以后 以色列 中再 没有 兴起 先知 像摩西的。他是 耶和华 面 对 面 所认识的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, '耶和华 打发他 在埃及 地 向法老 和他的一切 臣仆,并他的全 地, 行 各样 神迹 奇事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, ' 又在以色列 众人 眼前显 大能 的手, 行 一切 大 而可畏的事。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, ' 耶和华 的仆人 摩西 死了 以后,耶和华 晓谕 摩西 的帮手,嫩 的儿子 约书亚,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, '「我的仆人 摩西 死了。现在 你 要起来,和众 百姓 过 这 约旦河,往 我 所 要赐 给 以色列 人 的地去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, '凡 你们脚 掌 所 踏 之地,我都照著我所 应许 摩西 的话赐 给你们了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, '从旷野 和这 黎巴嫩,直到 幼发拉底 大 河,赫人 的全 地,又到 大 海 日 落之处,都要作 你们的境界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, '你平生 的日子,必无 一人 能在你面前 站立得住。我怎样与 摩西 同在,也必照样 与你 同在;我必不 撇下你,也不 丢弃你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, '你当刚强 壮胆!因为 你必使 这 百姓 承受 那地为业,就是 我向他们列祖 起誓 应许赐 给他们的地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, '只要 刚强,大大 壮胆,谨守 遵行 我仆人 摩西 所 吩咐你 的一切 律法,不可 偏离 左 右,使 你无论往哪里 去,都可以顺利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, '这 律法 书 不可 离开  你的口,总要昼 夜 思想,好使 你谨守 遵行 这书上 所写的 一切话。如此, 你的道路 就可以亨通, 凡事顺利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, '我岂没有 吩咐你吗?你当刚强 壮胆!不要 惧怕,也不要 惊惶;因为 你无论往哪里 去,耶和华─你的 神 必与你同在。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, '于 是,约书亚 吩咐 百姓 的官长 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, '「你们要走 遍 营中,吩咐 百姓 说:『当预备 食物;因为 三 日 之内 你们 要过 这 约旦河,进去 得 耶和华─你们 神 赐 你们 为业 之地。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, '约书亚 对流便人、迦得人,和 玛拿西 半 支派 的人说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, '「你们要追念 耶和华 的仆人 摩西 所 吩咐 你们 的话 说:『耶和华─你们的 神 使你们 得享平安,也必将 这 地 赐 给你们。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, '你们的妻子、孩子,和牲畜 都可以留 在 约旦河 东、摩西 所 给 你们 的地;但你们 中间一切 大能 的勇士 都要带著兵器 在你们的弟兄 前面 过去,帮助 他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, '等到 耶和华 使你们的弟兄 像你们一样 得享平安,并且 得著 耶和华─你们 神 所 赐 他们 为业之地,那时才可以回 你们所得 之地,承受 为业,就是耶和华 的仆人 摩西 在 约旦河 东、向日 出 之地所 给 你们的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, '他们回答 约书亚 说:「你所 吩咐我们行的,我们都必行;你所 差遣我们去的,我们都必去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, '我们从前在一切事上怎样 听从 摩西,现在也必照样 听从 你;惟愿  耶和华─你的 神 与你同在,像与 摩西 同在 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, '无论什么 人 违背 你的命令,不 听从 你所 吩咐他 的一切 话,就必治死他。你只要 刚强 壮胆!」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, '当下,嫩 的儿子 约书亚 从 什亭 暗暗 打发 两个 人 作探子,吩咐说:「你们去 窥探 那地和 耶利哥。」于 是二人去了,来 到一个妓 女 名叫 喇合 的家里,就在那里 躺卧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, '有人告诉 耶利哥 王 说:「 今夜 有 以色列 人 来到 这里 窥探 此地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, '耶利哥 王 打发 人去见 喇合 说:「那 来到 你这里、进了 你家 的人 要交出来,因为 他们来 窥探 全 地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, '女人 将 二 人 隐藏,就回答说:「那人 果然 到我这里 来;他们 是哪里来的 我却不 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, ' 天黑、要关 城门的时候,他们 出去了, 往哪里 去 我却不 知道。你们快快地 去追赶,就必 追上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, '(先是女人 领二人上了 房顶,将他们藏 在 那里 所摆的 麻 秸中。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, '那些人 就往 约旦河 的渡口 追赶 他们 去了。追赶 他们 的人一 出去,城门 就关了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, '二人 还没有 躺卧,女人 就上 房顶,到他们那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, '对 他们 说:「我知道 耶和华 已经把 这地 赐 给你们,并且因 你们的缘故我们 都惊慌了。 这地 的一切 居民 在你们面前 心都消化了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, '因为 我们听见 你们出 埃及的时候,耶和华 怎样 在你们前面 使 红 海 的水 干了,并且你们怎样 待 约旦河 东 的 两个 亚摩利 王 西宏 和噩,将 他们 尽行毁灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, '我们一听见这些事,心 就消化了。因你们的缘故,并 无 一人 有 胆气。 耶和华─你们的 神 本是 上 天 下 地的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, '现在 我既 是 恩 待 你们,求 你们指著耶和华 向我 起誓,也 要 恩 待 我父 家,并给 我 一个实在 的证据, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, '要救活 我的父 母、弟兄、姊妹,和 一切 属他们的,拯救 我们性命 不死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, '二人 对她 说:「你若 不 泄漏 我们这 件事,我们 情愿 替你们 死。 耶和华 将 这地 赐 给我们的时候,我们必以慈爱 诚实 待 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, '于 是女人用绳子 将二人从 窗户 里缒下去;因 她的房子 是在城 墙边上,她 也住 在城墙上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, '她对他们 说:「你们且往山上 去,恐怕 追赶的人 碰见 你们;要在那里 隐藏 三 天,等 追赶 的人回来,然后 才可以走 你们的路。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, '二人 对她 说:「你要这样行。不然,你叫我们所 起的 誓 就与我们 无干了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, ' 我们 来 到这地的时候,你要把 这条 朱红 线 缐 绳 系 在 缒我们下去 的 窗户 上,并要使你的父 母、弟兄,和 你父 的全 家 都聚集 在你 家中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, ' 凡 出了 你家 门 往街上 去的,他的罪(原文是血)必归到自己的头上,与我们 无干了。凡 在你家里 的,若 有人下手害 他,流他血 的罪就归到我们的头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, '你若 泄漏 我们这件 事,你叫我们所 起 的誓 就与我们 无干了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, '女人说:「照你们的话行吧!」于 是打发他们 去了,又把 朱红 线 缐绳 系 在窗户上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, '二人到 山上,在那里 住了 三 天,等著 追赶的人 回去了。追赶的人 一 路 找他们,却找 不著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, '二 人 就下 山 回来,过了河,到 嫩 的儿子 约书亚那里,向他述说 所 遭遇的 一切事; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, '又对 约书亚 说:「耶和华 果然 将 那全 地 交 在我们手中; 那地 的一切 居民 在我们面前 心都消化了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, '约书亚 清早 起来, 和以色列 众 人 都离开  什亭,来 到 约旦河,就住 在那里,等候 过河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, ' 过了 三 天,官长 走 遍营 中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, '吩咐 百姓 说:「你们 看见 耶和华─你们 神 的约 柜,又见祭司 利未人 抬著,就要离开  所住的地方,跟著 约柜去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, '只是 你们和 约柜相 离 要 量 二千 肘,不可 与约柜 相近,使 你们知道 所 当走 的路,因为 这条路 你们向来 没有 走过。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, '约书亚吩咐 百姓 说:「你们要自洁,因为 明天 耶和华 必在你们中间 行 奇事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, '约书亚 又吩咐 祭司 说:「你们抬起 约 柜,在百姓 前头 过去。」于 是他们抬起 约 柜,在百姓 前头 走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, '耶和华 对 约书亚 说:「从今 日 起,我必使你在以色列 众人 眼前 尊大,使 他们知道 我怎样 与 摩西 同在,也必 照样与你同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, '你要 吩咐 抬 约 柜 的祭司 说:『你们到了 约旦河 的水 边上,就要在约旦河水里 站住。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, '约书亚 对 以色列 人 说:「你们近 前来,听 耶和华─你们 神 的话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, '约书亚 说:「看哪,普 天下 主 的约 柜 必在你们前头 过去,到约旦河里,因此 你们就知道 在你们中间 有永生 神;并且他必在你们面前 赶出 迦南人、赫人、希未人、比利洗人、革迦撒人、亚摩利人、耶布斯人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, '你们 现在 要从 以色列 支派 中拣选 十二个 人,每支派 一 人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, ' 等到抬 普 天下 主 耶和华 约柜 的祭司 把脚 站 在约旦河 水里,约旦河 的水,就是从上 往下流的 水,必然断绝,立起 成垒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, ' 百姓 离开  帐棚 要过 约旦河的时候,抬 约 柜 的祭司 乃在百姓 的前头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, '他们 到了 约旦河, 脚 一入水(原来约旦河水 在收割 的日子 涨 过 两 岸), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, '那从上 往下流的 水 便在极 远之地、 撒拉但 旁 的亚当 城 那里停住,立起 成垒;那往 亚拉巴 的海,就是盐 海,下流的水 全然 断绝。于 是百姓 在耶利哥 的对面 过去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, '抬 耶和华 约 柜 的祭司 在约旦河 中 的干地上 站 定,以色列 众人 都从干地上 过去,直到 国民 尽 都 过了 约旦河。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, ' 国民 尽 都 过了 约旦河,耶和华 就对 约书亚 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, '「你 从 民 中要拣选 十二个 人,每支派 一 人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, '吩咐 他们 说:『你们 从这里,从约旦河 中、祭司 脚 站定 的地方,取 十二 块石头带 过去,放 在 你们今夜 要 住宿 的地方。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, '于 是,约书亚 将他从 以色列 人 中所 预备的那 十二 个人,每支派 一 人,都召了来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, ' 对他们 说:「你们下 约旦河 中,过 到耶和华─你们 神 的约柜 前头,按著以色列 人 十二支派 的数目,每人 取 一块 石头 扛在 肩上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, ' 这些 石头在你们中间 可以作为 证据。 日后,你们的子孙 问 你们说:『这些 石头 是什么意思?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, '你们就对他们 说:『这是 因为约旦河 的水 在耶和华 的约 柜 前 断绝;约柜过 约旦河的时候,约旦河 的水 就断绝了。这些 石头 要作 以色列 人 永远 的纪念。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, '以色列 人 就照 约书亚 所吩咐的,按著以色列 人 支派 的数目,从约旦河 中 取了 十二 块石头,都遵 耶和华 所吩咐 约书亚 的行了。他们把石头带 过去,到 他们所住宿的地方,就放 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, '约书亚 另把十二 块石头 立 在约旦河 中,在 抬 约 柜 的祭司 脚 站立的地方;直到 今日,那石头还在 那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, '抬 约柜 的祭司 站 在约旦河 中,等到 耶和华 晓谕 约书亚 吩咐 百姓的事 办完了,是照 摩西 所 吩咐 约书亚的一切话。于 是百姓 急速 过去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, ' 众 百姓 尽 都过了河,耶和华 的约柜 和祭司 就在百姓 面前 过去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, '流便 人、迦得 人、玛拿西 半 支派 的人都照 摩西 所吩咐 他们的,带著兵器 在以色列 人 前头 过去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, '约有四万 人都准备 打仗,在耶和华 面前 过去,到 耶利哥 的平原,等候上阵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, '当那日,耶和华 使 约书亚 在以色列 众人 眼前 尊大。在他平生 的日子,百姓敬畏 他,像 从前敬畏 摩西一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, '耶和华 晓谕 约书亚 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, '「你吩咐 抬 法 柜 的祭司 从 约旦河 里上来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, '约书亚 就吩咐 祭司 说:「你们从 约旦河 里上来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, ' 抬 耶和华 约 柜 的祭司 从约旦河 里 上来, 脚 掌 刚落 旱地,约旦河 的水 就流 到原处,仍旧 涨 过 两岸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, '正 月 初十日,百姓 从 约旦河 里上来,就在吉甲,在耶利哥 的东 边 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, '他们从 约旦河 中取来 的 那 十 二 块石头,约书亚 就立 在吉甲, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, ' 对 以色列 人 说:「 日后 你们的子孙 问 他们的父亲 说:『这些 石头 是什么意思?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, '你们就告诉 他们 说:『以色列人 曾走干地 过 这 约旦河; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, '因为 耶和华─你们的 神 在你们前面 使 约旦河 的水 干了,等著 你们过来,就如 耶和华─你们的 神 从前 在我们前面 使红 海 干了,等著 我们过来一样, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, '要使 地上 万 民 都知道, 耶和华 的手 大有 能力,也要使 你们永远 敬畏 耶和华─你们的 神。』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, ' 约旦河 西 亚摩利人 的诸 王 和靠 海 迦南人 的诸 王,听见 耶和华 在以色列 人 前面 使 约旦河 的水 干了,等到 我们过去,他们的心因 以色列 人 的缘故就消化了,不 再 有 胆气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, '那 时,耶和华 吩咐 约书亚 说:「你 制造 火石 刀,第二次 给 以色列 人 行割礼。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, '约书亚就 制造了 火石 刀,在「除皮 山」那里给 以色列 人 行割礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, '约书亚 行割礼 的缘故,是因为 从埃及 出来的 众 民,就是一切 能打仗 的男 丁,出了 埃及以后,都死 在旷野 的路上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, '因为 出来 的众 民都 受过割礼;惟独出 埃及以后、在旷野 的路上 所生的 众 民 都没有 受过割礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, ' 以色列 人 在旷野 走了 四十 年,等到 国民,就是出 埃及 的兵丁,都 消灭了,因为 他们没有 听从 耶和华 的话。 耶和华 曾向他们 起誓,必不容 他们看见 耶和华 向他们列祖 起誓、应许赐 给我们 的地,就是 流 奶 与蜜 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, ' 他们的子孙,就是耶和华所兴起来 接续他们的,都 没有受过割礼;因为 在路上 没有 给他们 行割礼,约书亚 这才给他们 行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, ' 国民 都 受完了 割礼,就住 在营中 自己的地方,等到 痊愈了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, '耶和华 对 约书亚 说:「我今日 将埃及的 羞辱 从你们身上 滚去了。」因此,那 地方 名 叫 吉甲(就是滚的意思),直到 今日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, '以色列 人 在吉甲 安营。正月 十 四 日 晚上,在耶利哥 的平原 守 逾越节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, '逾越节 的次日,他们就吃了 那地 的出产;正当 那 日 吃无酵饼 和烘的谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, '他们吃了 那地 的出产,第二日 吗哪 就止住了,以色列 人 也不 再 有 吗哪了。那一 年,他们却吃 迦南 地 的出产。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, ' 约书亚 靠近耶利哥 的时候,举 目 观看,不料,有一个人 手里 有拔出来的 刀,对面 站立。约书亚 到 他那里,问他 说:「你是 帮助我们呢,是 帮助我们敌人呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, '他回答说:「不是的, 我 来 是要 作耶和华 军队 的元帅。」约书亚 就俯伏 在地 下拜,说:「我主 有什么话 吩咐 仆人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, '耶和华 军队 的元帅 对 约书亚 说:「把你脚 上的鞋 脱 下来,因为 你 所 站 的地方 是 圣的。」约书亚 就照著 行了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, '耶利哥 的城门因 以色列 人 就关得 严紧,无人 出 入。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, '耶和华晓谕 约书亚 说:「看哪,我已经把 耶利哥和 耶利哥的王,并大能 的勇士,都交 在你手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, '你们的一切 兵丁 要围绕 这城,一日围绕 一 次,六 日 都要这样 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, '七个 祭司 要拿七个 羊 角 走 在约柜 前。到第七 日,你们要绕 城 七 次,祭司 也要吹 角。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, ' 他们吹的角声 拖长,你们听见 角 声,众 百姓 要大 声 呼喊,城 墙 就必塌陷,各人 都要往前 直上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, '嫩 的儿子 约书亚 召了 祭司来,吩咐他们 说:「你们抬起 约 柜来,要有七 个祭司 拿 七 个羊 角 走在耶和华 的约柜 前」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, '又对 百姓 说:「你们前去 绕 城,带兵器的 要走 在耶和华 的约柜 前。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, ' 约书亚 对 百姓 说完了话,七 个祭司 拿 七 个羊 角 走 在耶和华 面前 吹 角;耶和华 的约 柜 在他们后面 跟随。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, '带兵器的 走 在吹 角 的祭司 前面,后队 随著 约柜 行。祭司一面走 一面吹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, '约书亚 吩咐 百姓 说:「你们不可 呼喊,不可 出声,连一句话 也不可 出 你们的口,等到 我吩咐 你们 呼喊 的日子,那时才可以呼喊。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, '这样,他使耶和华 的约柜 绕 城,把城绕 了一 次;众人回到 营里,就在营里 住宿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, '约书亚 清早 起来,祭司 又抬起 耶和华 的约柜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, '七个 祭司 拿 七个 羊 角 在耶和华 的约柜 前,时常 行走 吹 角;带兵器的 在他们前面 走,后队 随著 耶和华 的约柜 行。祭司一面走 一面吹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, '第二 日,众人把 城 绕了 一 次,就回 营里去。六 日 都是这样 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, ' 第七 日清早,黎明 的时候,他们起来,照样 绕 城 七 次;惟独 这 日 把 城 绕了 七 次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, ' 到了第七 次,祭司 吹 角的时候,约书亚 吩咐 百姓 说:「呼喊吧,因为 耶和华 已经把 城 交 给你们了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, ' 这城 和其中 所有的 都要 在耶和华面前 毁灭;只有 妓女 喇合 与她 家中 所有的 可以存活,因为 她隐藏了 我们所 打发 的使者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, '至于  你们,务要谨慎,不可取 那当灭的物,恐怕 你们 取了 那当灭的物 就连累 以色列 的全营,使 全营受咒诅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, '惟有金子、银子,和铜 铁 的器皿 都 要 归耶和华 为圣,必入 耶和华 的库中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, '于 是百姓 呼喊,祭司也吹 角。 百姓 听见 角 声, 便大 声 呼喊,城墙 就塌陷,百姓 便上去 进城,各人 往前直上,将 城 夺取; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, '又将 城中 所有的,不拘男女 老 少, 牛 羊 和驴,都用刀 杀尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, '约书亚 吩咐窥探 地 的两个 人 说:「你们进 那妓 女 的家,照著你们向她 所 起的誓,将 那女人和 她 所有的 都从那里 带出来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, '当探子的 两个少年人 就进去, 将 喇合 与她的父 母、弟兄,和 她 所有的,并 她一切的 亲眷,都带出来,安置 在以色列 的营 外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, '众人就用火 将城 和其中 所有的 焚烧了;惟有 金子、银子,和铜 铁 的器皿 都放 在耶和华 殿 的库中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, '约书亚 却把 妓女 喇合与 她父 家,并 她 所有的,都救活了;因为 她隐藏了 约书亚 所 打发 窥探 耶利哥 的使者,她就住 在以色列 中,直到 今日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, '当时,约书亚 叫众人起誓 说:「有 兴起 重修 这 耶利哥 城 的人,当在耶和华 面前 受咒诅。他立根基的时候,必丧长子,安 门的时候,必丧幼子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, '耶和华 与 约书亚 同在, 约书亚的声名 传扬遍 地。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, '以色列 人 在当灭的物上 犯了 罪;因为犹大 支派中,谢拉 的曾孙,撒底 的孙子,迦米 的儿子 亚干 取了 当灭的物;耶和华 的怒气 就向以色列 人 发作。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, '当下,约书亚 从耶利哥 打发 人 往伯特利 东边、靠近伯‧亚文 的 艾城去,吩咐 他们 说:「你们上去 窥探 那地。」他们 就上去 窥探 艾城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, '他们回 到 约书亚那里,对他 说:「众 民 不必 都上去,只要二 三 千 人 上去 就能攻取 艾城;不必 劳累 众 民都去,因为那里的人 少。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, '于 是民中 约有三 千 人 上 那里去,竟在艾城 人 面前 逃跑了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, '艾城 的人 击杀了 他们 三十 六 人,从城门 前 追赶他们,直到 示巴琳,在下坡 杀败他们;众民 的心 就消化 如水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, '约书亚 便撕裂 衣服;他 和以色列 的长老 把灰 撒 在 头上,在耶和华 的约柜 前 俯伏 在地,直到 晚上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, '约书亚 说:「哀哉!主 耶和华啊,你为什么 竟领 这 百姓 过 约旦河,将我们 交 在亚摩利人 的手中,使我们灭亡呢?我们不如 住 在约旦河 那边 倒好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, '主 啊,以色列人 既 在仇敌 面前 转 背逃跑,我还有什么 可说的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, '迦南人 和这地 一切的 居民 听见了 就必围困 我们,将 我们的名 从 地上 除灭。那时你为你的大 名 要怎样 行呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, '耶和华 吩咐 约书亚 说:「起来!你 为何 这样 俯伏在地呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, '以色列人 犯了罪, 违背了 我所 吩咐 他们 的约, 取了 当灭的物;又 偷窃,又 行诡诈,又 把那当灭的放 在他们的家具里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, '因此,以色列 人 在仇敌 面前 站立 不 住。他们在仇敌 面前 转 背逃跑,是因 成了 被咒诅的;你们若 不 把当灭的物 从你们中间 除掉,我就不 再 与你们 同在了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, '你起来,叫 百姓 自洁,对他们说:『你们要自洁,预备明天,因为 耶和华─以色列的 神 这样 说:以色列啊,你们中间 有当灭的物,你们若不 除掉,在仇敌 面前 必站立 不 住!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, '到了早晨,你们要按著支派 近前来; 耶和华 所 取 的支派,要按著宗族 近前来;耶和华 所 取 的宗族,要按著家室 近前来;耶和华 所 取 的家室,要按著人丁,一个一个地近前来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, ' 被取的人 有当灭的物在他那里,他 和 他 所有的 必被火 焚烧;因 他违背了 耶和华 的约,又因 他在以色列中 行了 愚妄的事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, '于 是,约书亚 清早 起来,使 以色列人 按著支派 近前来,取出来 的是犹大 支派; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, '使 犹大支派(原文是宗族)近前来,就取了 谢拉 的宗族;使 谢拉 的宗族,按著家室人丁,一个一个地近前来,取出来 的是撒底; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, '使 撒底的家室,按著人丁,一个一个地近前来,就取出 犹大 支派 的人谢拉 的曾孙,撒底 的孙子,迦米 的儿子 亚干。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, '约书亚 对 亚干 说:「我儿,我劝你 将荣耀 归给 耶和华─以色列的 神,在他面前 认 罪,将你所 做 的事告诉 我,不要 向我 隐瞒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, '亚干 回答 约书亚 说:「我 实在 得罪了 耶和华─以色列的 神。我所做 的事如此 如此: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, '我在所夺的财物中 看见 一件 美好的 示拿 衣服,二百 舍客勒 银子,一 条 金子 重 五十 舍客勒,我就贪爱这些物件,便拿去了。现今 藏 在我帐棚 内 的地里,银子 在衣服底下。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, '约书亚 就打发 人 跑 到亚干的帐棚里。那件衣服果然 藏 在他帐棚内,银子 在底下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, '他们就从帐棚 里 取出来,拿 到 约书亚和 以色列 众 人那里,放 在耶和华 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, '约书亚 和 以色列 众 人把 谢拉 的曾孙 亚干和 那银子、 那件衣服、 那条 金子,并亚干的儿女、牛、驴、羊、帐棚,以及 他 所有的,都带 到亚割 谷 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, '约书亚 说:「你为什么 连累我们呢?今日 耶和华 必叫你受连累。」于 是以色列 众人 用石头 打死 他,将石头 扔 在其上,又用火 焚烧他所有的(原文是他们)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, '众人在亚干身上 堆 成一大 堆 石头,直 存到今日。于 是耶和华 转意,不发 他的烈 怒。因此 那 地方 名 叫 亚割 谷(就是连累的意思),直到 今日。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, '耶和华 对 约书亚 说:「不要 惧怕,也不要 惊惶。你起来,率领 一切 兵 丁 上 艾城去, 我已经把 艾城 的王和 他的民、他的城,并 他的地,都交 在你手里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, '你怎样 待 耶利哥 和耶利哥的王,也当照样待 艾城 和艾城的王。只是 城内所夺的财物 和牲畜,你们可以取为自己的掠物。你 要在城 后 设下 伏兵。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, '于 是,约书亚 和一切 兵 丁 都起来,要上 艾城去。约书亚 选了 三万 大能的 勇 士,夜间 打发他们前往, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, '吩咐 他们 说:「 你们 要在城 后 埋伏,不可 离 城 太 远,都 要 各自准备。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, '我 与我所带领的 众 民 要向 城 前往。 城里的人像 初次 出来 攻击我们 的时候,我们就在他们面前 逃跑, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, '他们必出来 追赶我们,直到 我们引诱 他们 离开  城;因为 他们必说:『这些人像 初次 在我们面前 逃跑。』所以我们要在他们面前 逃跑, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, '你们 就从埋伏的地方 起来,夺取 那城,因为耶和华─你们的 神 必把城交 在你们手里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, ' 你们夺了 城以后,就放 火烧 城,要照耶和华 的话 行。 这是我吩咐 你们的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, '约书亚 打发他们前往,他们就上 埋伏的地方 去,住 在 伯特利 和艾城 的中间,就是在艾城 的西边。这 夜 约书亚 却在民 中 住宿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, '约书亚 清早 起来,点齐 百姓,他 和以色列 的长老 在百姓 前面 上 艾城去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, '众 民,就是他所 带领的 兵丁,都上去,向前直往,来到 城 前,在艾城 北边 安营。在约书亚 和艾城 中间 有一山谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, '他挑了 约有五 千 人,使 他们 埋伏 在 伯特利 和艾城 的中间,就是在艾城 的西边, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, '于 是安置了 百姓, 就是 城 北 的全 军和 城 西 的伏兵。这 夜 约书亚 进入 山谷 之中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, ' 艾城 的王 看见这景况,就 和全 城 的人,清早急忙 起来, 按所定的时候,出 到亚拉巴 前,要与 以色列人 交战 ;王 却不 知道 在城 后 有伏兵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, '约书亚 和以色列 众人 在他们面前 装败,往那通旷野 的路 逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, ' 城内 的众 民 都被招聚,追赶 他们;艾城人追赶的时候,就被引诱 离开  城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, '艾城 和伯特利城 没有 一人 不 出来 追赶 以色列人的,撇了 敞开 的 城门,去追赶 以色列人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, '耶和华 吩咐 约书亚 说:「你向 艾城 伸出 手里的 短枪,因为 我要将城交 在你手里。」约书亚 就向 城 伸出 手里的 短枪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, '他一伸 手,伏兵 就从埋伏的地方 急忙 起来,夺了城,跑 进 城去, 放 火焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, '艾城 的人 回 头 一看,不料,城 中烟气 冲 天,他们就 无 力 向左 向右 逃跑。那往旷野 逃跑的 百姓 便转身 攻击 追赶他们的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, '约书亚 和以色列 众人 见 伏兵 已经夺了 城, 城 中烟气 飞腾,就转身回去,击杀 艾城 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, '伏兵 也出 城 迎击艾城人, 艾城人就困在以色列人 中间,前 后都是以色列人。于 是以色列人击杀 他们, 没有 留下 一个,也没有一个逃脱的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, '生 擒了 艾城 的王,将他 解 到 约书亚那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, ' 以色列人 在田间 和旷野 杀 尽 所 追赶 一切 艾城 的居民。艾城人 倒 在刀 下,直到 灭尽;以色列 众人 就回 到艾城,用刀 杀了 城中的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, ' 当日 杀毙的人,连男 带 女 共有一万二 千,就是艾城 所有的 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, '约书亚 没有 收回 手 里所 伸出来 的短枪,直到 把 艾城 的一切 居民 尽行杀灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, '惟独 城中 的牲畜 和财物,以色列人 都取为自己的 掠物,是照耶和华 所 吩咐 约书亚 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, '约书亚 将 艾城 焚烧,使 城永 为高堆、荒场,直到 今日; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, '又将 艾城 王 挂 在 树上,直到 晚上。日 落的时候,约书亚 吩咐 人把 尸首 从 树 上取下来,丢 在 城 门 口,在尸首上 堆 成一大 堆 石头,直 存到今日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, '那时,约书亚 在以巴路 山 上为耶和华─以色列的 神 筑 一座坛, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, ' 是 用没有 动过 铁器的 整 石头筑的,照著耶和华 仆人 摩西 所 吩咐 以色列 人的话,正如摩西 律法 书上 所写的。众人在这坛上 给耶和华 奉献 燔祭 和 平安祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, '约书亚在那里,当著以色列 人 面前,将 摩西 所 写 的律法 抄写 在 石头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, '以色列 众人,无论是本地人、是寄居的,和长老、官长,并审判官,都站 在约柜 两旁,在抬 耶和华 约 柜 的祭司 利未人 面前,一半 对著 基利心 山,一半 对著 以巴路 山,为 以色列 民 祝福,正如 耶和华 仆人 摩西 先前 所 吩咐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, '随后,约书亚将 律法 上祝福、咒诅 的话,照著律法 书上 一切 所写的,都 宣读了一遍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, '摩西 所 吩咐 的一切 话,约书亚 在以色列 全 会众 和妇女、孩子,并他们中间 寄居的 外人 面前,没有一句 不 宣读的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, ' 约旦河 西,住山地、高原,并对著 黎巴嫩山 沿 大 海 一带 的诸 王,就是赫人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人的诸王,听见这事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, '就都聚集,同心合意地 要与 约书亚 和 以色列人 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, '基遍 的居民 听见 约书亚 向耶利哥 和艾城 所 行的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, ' 就设 诡计, 假充使者,拿 旧 口袋 和破裂 缝补 的旧 皮酒 袋 驮在驴上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, '将补过的旧 鞋 穿 在脚上,把旧 衣服 穿在身上;他们所带 的饼 都 是干的,长了 霉了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, '他们到 吉甲 营中 见 约书亚,对他 和 以色列 人 说:「我们是从远 方 来的,现在 求你与我们 立 约。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, '以色列 人 对 这些希未人 说:「只怕 你们是 住 在我们中间的;若是这样,怎能 和你们 立 约呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, '他们对 约书亚 说:「我们是 你的仆人。」约书亚 问他们 说:「你们是 什么人?是从哪里 来的?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, '他们回答说:「仆人 从极 远 之地 而来,是因 听见 耶和华─你 神 的名 声和 他在埃及 所 行 的一切事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, '并 他向约旦河 东 的 两 个亚摩利 王,就是希实本 王 西宏 和在亚斯他录 的 巴珊 王 噩 一切 所 行的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, '我们的长老 和我们那地 的一切 居民 对我们 说:『你们手里 要带 著路上用的 食物 去 迎接以色列人,对他们 说:我们是 你们的仆人;现在 求你们与我们 立 约。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, '我们出来 要往你们这里 来 的日子,从家里 带出来 的 这 饼 还是热的;看哪,现在 都干了,长了 霉了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, '这 皮酒 袋,我们盛 酒的时候 还是新的;看哪,现在已经破裂。我们这 衣服 和鞋,因为道路 甚 远,也都穿旧了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, '以色列人 受了 他们些食物,并没有 求问 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, '于 是约书亚 与他们 讲 和,与他们 立 约,容他们活著;会众 的首领 也向他们 起誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, ' 以色列人与他们 立 约 之后, 过了 三 天 才听见 他们是 近邻, 住 在以色列人中间的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, '以色列 人 起行,第三 天 到了 他们的城邑, 就是基遍、基非拉、比录、基列‧耶琳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, '因为 会众 的首领 已经指著耶和华─以色列的 神 向他们 起誓,所以以色列 人 不 击杀他们;全 会众 就向 首领 发怨言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, '众 首领 对 全 会众 说:「我们 已经指著耶和华─以色列的 神 向他们 起誓,现在 我们不 能 害 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, '我们要如此 待 他们,容他们 活著,免得 有 忿怒 因 我们所 起 的誓 临到我们身上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, '首领 又对会众 说:「要容他们活著。」于 是他们为全 会众 作了 劈 柴 挑 水的人,正如首领 对他们 所 说的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, '约书亚 召了 他们来, 对他们 说:「为什么 欺哄 我们 说『我们 离你们 甚 远』呢?其实你们是 住 在我们中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, '现在 你们是 被咒诅的!你们中间的人 必断 不了 作奴仆,为我 神 的殿 作劈 柴 挑 水的人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, '他们回答 约书亚 说:「因为 有人实在 告诉 你的仆人, 耶和华─你的 神 曾吩咐 他的仆人 摩西, 把 这全 地 赐 给你们,并在你们面前 灭绝 这地 的一切 居民,所以我们为你们的缘故 甚 怕 丧命,就行了 这 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, '现在 我们在你手中,你 以怎样待 我们 为善 为正,就怎样做吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, '于 是约书亚这样 待 他们,救 他们 脱离以色列 人 的手,以色列人就没有 杀他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, '当 日 约书亚 使他们 在 耶和华所 要选择 的地方,为会众 和耶和华 的坛 作劈 柴 挑 水的人,直到 今 日。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, ' 耶路撒冷 王亚多尼‧洗德 听见 约书亚 夺了 艾城,尽行毁灭,怎样 待 耶利哥 和耶利哥的王,也照样 待 艾城 和艾城的王,又听见 基遍 的居民 与 以色列人 立了和约,住在 他们中间, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, '就甚 惧怕;因为 基遍 是一座大 城,如都 城 一般, 比 艾城 更大,并且城内的人 都 是勇士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, '所以耶路撒冷 王亚多尼‧洗德 打发 人去见 希伯仑  王 何咸、 耶末 王 毘兰、 拉吉 王 雅非亚,和 伊矶伦 王 底璧,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, '「求你们上 来 帮助我,我们好攻打 基遍,因为 他们与 约书亚 和 以色列 人 立了和约。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, '于 是五 个亚摩利 王,就是耶路撒冷 王、希伯仑  王、耶末 王、拉吉 王、伊矶伦 王,大家聚集, 率领他们的众 军 上去,对著 基遍 安营,攻打 基遍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, '基遍 人 就打发 人往 吉甲 的营 中去见 约书亚,说:「你不要 袖 手 不顾你的仆人,求你速速 上 来 拯救 我们,帮助我们,因为 住 山地 亚摩利人 的诸 王 都聚集 攻击我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, '于 是约书亚 和他 一切 兵丁,并大能 的勇士,都从 吉甲 上去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, '耶和华 对 约书亚 说:「不要 怕 他们;因为 我已将他们交 在你手里,他们 无 一人 能在你面前 站立得住。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, '约书亚 就终 夜 从 吉甲 上去,猛然 临 到他们那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, '耶和华 使他们在以色列人 面前 溃乱。约书亚在基遍 大大地 杀败他们,追赶他们,在伯‧和仑  的上坡 路 击杀他们,直到 亚西加 和 玛基大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, ' 他们 在以色列人 面前 逃跑,正在伯‧和仑  下坡的时候,耶和华 从 天上 降 大冰雹(原文是石头)在他们身上,直降到 亚西加,打死他们。被冰雹 打死 的,比 以色列 人 用刀 杀 死的还多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, '当耶和华 将 亚摩利人 交付 以色列 人 的日子,约书亚 就 祷告 耶和华,在以色列人 眼前 说:日头啊,你要停 在基遍;月亮啊,你要止在亚雅仑  谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, '于 是日头 停留,月亮 止住,直等 国民 向敌人 报仇。这事 岂不是 写 在 雅煞珥 书上吗?日头 在天 当中 停住,不 急速 下落,约有一 日之久。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, ' 在这日以前,这日以后,耶和华 听 人 的祷告,没有 像这 日的,是因 耶和华 为以色列 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, '约书亚 和 以色列 众人 回 到 吉甲 的营中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, '那 五 王 逃跑,藏 在玛基大 洞里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, '有人告诉 约书亚 说:「那五 王 已经找到了,都藏 在玛基大 洞里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, '约书亚 说:「你们把几块大 石头 滚 到 洞 口,派 人 看守, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, '你们却 不可 耽延,要追赶 你们的仇敌,击杀他们尽 侭后边 的人,不 容他们 进 自己的城邑,因为 耶和华-你们的 神 已经把他们交 在你们手里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, ' 约书亚 和以色列 人 大大 杀败他们,直到 将他们灭尽;其中 剩下的人 都进了 坚固 的城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, '众 百姓 就安然 回 玛基大 营中,到 约书亚那里。没有 一人敢向 以色列 人 饶 舌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, '约书亚 说:「打开  洞 口,将 那 五 王 从 洞 里带出来,领到我面前。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, '众人就这样 行,将 那 五 王,就是 耶路撒冷 王、 希伯仑  王、 耶末 王、 拉吉 王、 伊矶伦 王,从 洞 里带出来,领到约书亚面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, ' 带出 那 五王 到 约书亚面前的时候,约书亚 就召了 以色列 众 人来,对 那些和他 同去 的军 长 说:「你们近前来,把 脚 踏 在 这些 王 的颈项上。」他们就近前来,把 脚 踏 在 这些 王 的颈项上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, '约书亚 对他们 说:「你们不要 惧怕,也不要 惊惶。应当刚强 壮胆,因为 耶和华 必这样 待 你们 所 要攻打 的一切 仇敌。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, '随后 约书亚 将这五王杀 死,挂 在 五棵 树上。他们就 在 树 上直挂 到 晚上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, ' 日头 要落 的时候,约书亚 一吩咐,人就把尸首从树 上 取下来,丢 在 他们藏过 的 洞 里,把几块大 石头 放 在 洞 口,直 存到今日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, '当日,约书亚 夺了 玛基大,用刀 击杀 城中的人 和王;将 其中 一切 人口 尽行杀灭,没有 留下 一个。他待 玛基大 王,像 从前待 耶利哥 王一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, '约书亚 和 以色列 众人 从玛基大 往 立拿去,攻打 立拿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, '耶和华 将 立拿和 立拿的王 也 交 在以色列 人手里。约书亚攻打这城,用刀 击杀了 城中 的 一切 人口,没有 留下 一个。他待 立拿王,像 从前待 耶利哥 王一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, '约书亚 和 以色列 众人 从立拿 往拉吉 去,对著 拉吉安营,攻打 这城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, '耶和华 将 拉吉 交 在以色列人 的手里。第二 天 约书亚 就夺了拉吉,用 刀 击杀了 城中 的 一切 人口,是照他向立拿 一切 所 行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, '那时 基色 王 荷兰 上来 帮助 拉吉,约书亚 就把 他和他的民 都击杀了, 没有 留下 一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, '约书亚 和 以色列 众人 从拉吉 往伊矶伦 去,对著 伊矶伦安营,攻打 这城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, '当日 就夺了城,用 刀 击杀了城中的人。那日,约书亚 将 城中 的 一切 人口 尽行杀灭,是照他向拉吉 一切 所 行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, '约书亚 和 以色列 众人 从伊矶伦 上希伯仑  去,攻打 这城, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, '就夺了希伯仑 和属希伯仑 的 诸 城邑,用 刀 将 城中的人与王,并 那些城邑中 的 人口,都 击杀了,没有 留下 一个,是照 他向伊矶伦 所 行的,把 城中 的 一切 人口 尽行杀灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, '约书亚 和 以色列 众人 回 到底璧,攻打 这城, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, '就夺了 底璧和 属底璧的城邑,又 擒获底璧的王,用刀 将 这些城中 的 人口 尽行杀灭,没有 留下 一个。他待 底璧 和底璧王,像 从前待 希伯仑 和 立拿 与立拿王 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, '这样,约书亚 击杀 全 地的人,就是山地、南地、高原、山坡的人,和 那些地的诸 王,没有 留下 一个。将凡 有气息的 尽行杀灭,正如耶和华─以色列的 神 所 吩咐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, '约书亚从加低斯‧巴尼亚 攻击 到 迦萨,又 攻击歌珊 全 地,直到 基遍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, '约书亚 一 时 杀败了 这些 王,并 夺了他们的地,因为 耶和华─以色列的 神 为以色列 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, '于 是约书亚 和 以色列 众人 回 到 吉甲 的营中。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, ' 夏琐 王 耶宾 听见这事,就打发 人去见 玛顿 王 约巴、 伸仑  王、 押煞 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, '与 北方 山地、基尼烈 南边 的亚拉巴 高原,并西边 多珥 山冈 的 诸王; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, '又去见东方 和西方 的迦南人,与山地 的亚摩利人、赫人、比利洗人、耶布斯人,并黑门山 根 米斯巴 地 的希未人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, '这些王 和他们 的众 军 都出来,人 数多如 海 边 的沙,并有许 多 马匹 车辆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, '这 诸王 会合,来 到 米伦 水边,一同 安营,要与 以色列 人争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, '耶和华 对 约书亚 说:「你不要 因他们 惧怕。 明日 这 时,我必 将 他们交付 以色列 人全然 杀了。你要砍断 他们马的蹄筋,用火 焚烧 他们的车辆。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, '于 是约书亚 率领 一切 兵 丁,在 米伦 水边 突然 向前攻打 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, '耶和华 将他们交 在以色列 人手里,以色列 人就击杀他们,追赶他们 到 西顿 大城,到米斯利弗‧玛音,直到 东边 米斯巴 的平原,将他们击杀, 没有 留下 一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, '约书亚 就照耶和华 所 吩咐 他 的去行,砍断 他们马的蹄筋,用火 焚烧 他们的车辆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, '当时,约书亚 转回 夺了 夏琐,用刀 击杀 夏琐王。( 素来 夏琐 在这 诸 国 中是 为首的。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, '以色列 人用 刀 击杀 城中 的 人口,将他们尽行杀灭;凡 有气息 的没有 留下一个。约书亚 又用火 焚烧 夏琐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, '约书亚 夺了 这些 王 的一切 城邑,擒获 其中的诸 王,用 刀 击杀他们,将他们 尽行杀灭,正如耶和华 仆人 摩西 所 吩咐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, '至于  造 在 山冈 上的城,除了 夏琐以外,以色列 人都 没有 焚烧。约书亚 只 将夏琐焚烧了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, '那些 城邑 所有的 财物 和牲畜,以色列 人 都取 为自己的掠物;惟有 一切 人口 都用 刀 击杀,直到 杀尽;凡 有气息的 没有 留下一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, '耶和华 怎样 吩咐 他仆人 摩西,摩西 就照样 吩咐 约书亚,约书亚 也照样 行。凡 耶和华 所 吩咐 摩西的,约书亚 没有 一件 懈怠不行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, '约书亚 夺了 那 全 地,就是山地、 一带 南地、 歌珊 全 地、 高原、 亚拉巴、 以色列 的山地,和山下的高原。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, '从 上 西珥 的哈拉 山,直到 黑门 山 下 黎巴嫩 平原的巴力‧迦得,并且擒获 那些地的诸 王,将他们杀 死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, '约书亚 和 这 诸 王 争战  了许多 年日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, '除了 基遍 的希未 人之外,没 有 一城 与 以色列 人 讲和 的,都 是以色列 人争战  夺来 的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, '因为 耶和华 的意思 是要 使 他们心 里刚硬,来 与 以色列 人争战 ,好叫 他们尽被杀灭,不 蒙 怜悯,正如耶和华 所 吩咐 摩西的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, '当 时 约书亚 来到,将 住 山地、 希伯仑 、 底璧、 亚拿伯、 犹大 山地、 以色列 山地 所有的亚衲族人 剪除了。约书亚 将他们和 他们的城邑 尽都毁灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, '在以色列 人 的地 没有 留下 一个亚衲族人,只 在迦萨、迦特,和亚实突 有留下的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, '这样,约书亚 照著 耶和华 所 吩咐 摩西 的一切话 夺了 那 全 地, 就按著以色列 支派 的宗族 将地分给 他们为业。于 是国中 太平,没有争战 了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, '以色列 人 在约旦河 外 向日 出 之地 击杀 二王,得 他们的地,就是 从亚嫩 谷 直到 黑门 山,并东边 的全 亚拉巴之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, '这二王,有住 希实本、亚摩利人 的王 西宏。他所管 之地是 从 亚嫩 谷 边 的亚罗珥 和谷 中的城,并基列 一半,直到 亚扪 人 的境界,雅博 河 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, '与约旦河东边 的亚拉巴,直到 基尼烈 海,又到亚拉巴 的海,就是盐 海,通伯‧耶西末 的路,以及南方,直到毘斯迦 的山根。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, ' 又有巴珊 王 噩。他是利乏音人 所剩下的,住 在亚斯他录 和以得来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, '他所管 之地是黑门 山、撒迦、巴珊 全地,直到 基述人 和玛迦人 的境界,并基列 一半,直到希实本 王 西宏 的境界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, '这二王是耶和华 仆人 摩西 和以色列 人 所击杀的;耶和华 仆人 摩西 将他们的地 赐 给流便人、迦得人,和玛拿西 半 支派的人为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, '约书亚 和以色列 人 在约旦河 西 击杀 了诸王。他们的 地 是 从黎巴嫩 平原的巴力‧迦得,直到 上 西珥 的哈拉 山。约书亚 就将那地按著以色列 支派 的宗族 分给 他们为业, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, '就是赫人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人 的山地、高原 亚拉巴、山坡、旷野,和南地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, '他们的王:一个 是耶利哥 王,一个 是靠近 伯特利 的 艾城 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, '一个 是耶路撒冷 王,一个 是希伯仑  王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, '一个 是耶末 王,一个 是拉吉 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, '一个 是伊矶伦 王,一个 是基色 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, '一个 是底璧 王,一个 是基德 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, '一个 是何珥玛 王,一个 是亚拉得 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, '一个 是立拿 王,一个 是亚杜兰 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, '一个 是玛基大 王,一个 是伯特利 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, '一个 是他普亚 王,一个 是希弗 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, '一个 是亚弗 王,一个 是拉沙仑  王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, '一个 是玛顿 王,一个 是夏琐 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, '一个是伸仑 ‧米仑  王,一个 是押煞 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, '一个 是他纳 王,一个 是米吉多 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, '一个 是基低斯 王,一个 是靠近迦密 的约念 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, '一个 是多珥 山冈的 多珥 王,一个 是吉甲的 戈印 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, '一个 是得撒 王;共计 三十 一 个王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, '约书亚 年纪 老 迈,耶和华 对他 说:「你 年纪 老 迈了,还有 许 多 未得 之地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, '就是 非利士人 的全 境 和基述人 的全 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, '从 埃及 前 的 西曷河 往北,直到 以革伦 的境界,就算 属迦南人之地。有非利士人 五个 首领 所管的迦萨人、亚实突人、亚实基伦人、迦特人、以革伦人之地,并有南方亚卫人之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, ' 又有迦南人 的全 地,并属西顿人 的 米亚拉 到 亚弗,直到 亚摩利人 的境界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, '还有迦巴勒人 之地,并向日 出的 全 黎巴嫩,就是从黑门 山 根的巴力‧迦得,直到 哈马 口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, '山地 的一切 居民,从 黎巴嫩 直到米斯利弗‧玛音,就是所有的 西顿人,我必 在以色列 人 面前 赶出他们去。你只管 照我所 吩咐的,将这地拈阄 分给以色列人 为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, '现在 你要把 这 地 分 给九个 支派 和玛拿西 半个 支派 为业。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, '玛拿西那半支派和 流便、迦得 二支派已经受了 产业,就是 耶和华 的仆人 摩西 在约旦河 东 所 赐 给他们的: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, '是从亚嫩 谷 边 的 亚罗珥 和谷 中 的 城,并米底巴 的全 平原,直到 底本, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, '和在希实本 作王 亚摩利 王 西宏 的 诸 城,直到 亚扪 人 的境界; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, '又有基列地、基述人、玛迦人 的地界,并黑门 全 山、巴珊 全地,直到 撒迦; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, '又有巴珊 王噩 的 全 国─他在亚斯他录 和以得来 作王(利乏音人 所存留的 只剩下 他)。这些地的人都是摩西 所击杀、所赶逐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, '以色列 人 却没有 赶逐 基述人、 玛迦人;这些人 仍住 在以色列 中,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, '只是 利未 支派,摩西(原文是他)没有 把产业 分给他们。他们的产业 乃是 献与耶和华─以色列 神 的火祭,正如耶和华 所 应许 他们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, '摩西 按著流便 支派 的宗族 分给他们产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, '他们的 境界 是 亚嫩 谷 边 的 亚罗珥 和谷 中 的 城,靠近 米底巴 的全 平原; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, '希实本 并属希实本平原 的 各 城,底本、巴末‧巴力、伯‧巴力‧勉、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, '雅杂、基底莫、米法押、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, '基列亭、西比玛、谷 中山的细列‧哈沙辖、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, '伯‧毘珥、毘斯迦山坡、伯‧耶西末; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, '平原 的各 城,并亚摩利 王 西宏 的全 国。这西宏 曾在希实本 作王, 摩西 把他 和 米甸 的族长 以未、 利金、 苏珥、 户珥、 利巴 击杀了;这都是住 那地 属西宏 为首领的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, '那时以色列 人 在所杀 的人中,也用刀 杀了 比珥 的儿子 术士 巴兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, '流便 人 的境界 就是 约旦河 与靠近约旦河的地。以上是 流便 人 按著宗族 所得为业的诸城,并属城的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, '摩西 按著迦得 支派 的宗族 分给 他们产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, '他们的 境界 是 雅谢 和基列 的各 城,并亚扪 人 的一半 地,直到 拉巴 前 的 亚罗珥; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, '从希实本 到拉抹‧米斯巴 和比多宁,又从玛哈念 到 底璧 的境界, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, '并谷中的伯‧亚兰、伯‧宁拉、疏割、撒分,就是希实本 王 西宏 国 中的余 馀地,以及约旦河 与靠近约旦河的地,直到 基尼烈 海 的极边,都在 约旦河 东。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, '以上是 迦得 人 按著宗族 所得为业 的诸城,并属城的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, '摩西 把产业分给 玛拿西 半 支派,是 按著玛拿西 半 支派 的宗族所分的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, '他们的境界 是 从玛哈念起,包括巴珊 全地,就是巴珊 王 噩 的全 国,并 在巴珊、睚珥 的一切 城邑,共六十 个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, '基列 的一半,并亚斯他录、以得来,就是属巴珊 王噩 国 的二城,是按著宗族 给玛拿西 的儿子 玛吉 的一半 子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, '以上是 摩西 在约旦河 东 对著 耶利哥 的摩押 平原 所 分给他们的产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, '只是利未 支派,摩西 没有 把产业 分给他们。耶和华─以色列的 神 是 他们的产业,正如耶和华所 应许 他们的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, '以色列 人 在迦南 地 所 得的产业,就是 祭司 以利亚撒 和嫩 的儿子 约书亚,并以色列 各支派 的族 长 所分 给他们的,都记在下面, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, '是照耶和华 藉 借 摩西 所 吩咐的,把产业 拈阄 分给九 个 半 支派。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, '原来,摩西 在约旦河 东 已经把产业 分给 那两 个 半 支派,只是在他们中间 没有 把产业 分 给利未人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, '因为 约瑟 的子孙 是 两个 支派,就是玛拿西 和以法莲,所以没有 把 地 分 给利未人,但 给他们城邑 居住,并城邑的郊野,可以牧养他们的牲畜,安置他们的财物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, '耶和华 怎样 吩咐 摩西,以色列 人 就照样 行,把 地 分了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, '那时,犹大 人 来 到吉甲 见 约书亚,有基尼洗族 耶孚尼 的儿子 迦勒 对约书亚 说:「耶和华在加低斯‧巴尼亚 指著我与 你 对 神 人 摩西 所 说的 话,你 都知道了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, '耶和华 的仆人 摩西从加低斯‧巴尼亚 打发 我 窥探 这 地,那时我 正四十 岁;我按 著 心意 回 报 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, '然而,同我 上去 的 众弟兄 使 百姓 的心 消化;但我 专心 跟从 耶和华─我的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, '当 日 摩西 起誓 说:『你脚 所 踏之 地 定要 归 你 和你的子孙 永远 为业,因为 你专心 跟从 耶和华─我的 神。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, ' 自从 耶和华 对 摩西 说 这 话的时候,耶和华 照他所 应许的 使我 存活 这 四十 五 年;其间 以色列 人在旷野 行走。看哪,现今 我 八十 五 岁了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, '我还是 强壮,像 摩西 打发 我 去的那天一样;无论是争战 ,是出 入,我的力量 那时 如何,现在 还是如何。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, ' 求你将耶和华 那 日 应许我的 这 山地 给 我; 那里 有亚衲族人,并宽大 坚固 的城, 你也曾 听见了。或者 耶和华 照他所 应许的 与我同在,我就把他们赶出去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, '于 是约书亚 为耶孚尼 的儿子 迦勒 祝福,将 希伯仑  给 他为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, '所以 希伯仑  作了 基尼洗族 耶孚尼 的儿子 迦勒 的产业,直到 今 日,因为 他专心 跟从 耶和华─以色列的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, '希伯仑  从前 名叫基列‧亚巴;亚巴是 亚衲族中 最尊大的 人。于 是国中 太平,没有争战 了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, '犹大 支派 按著宗族 拈阄 所得之地是 在尽 侭 南边,到 以东 的交界,向南 直到寻 的旷野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, '他们的 南 界 是 从盐 海 的尽 侭边,就是从 朝 南 的海汊起, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, '通 到 亚克拉滨坡 的南边,接连 到寻,上到加低斯‧巴尼亚 的南边,又过 希斯仑 ,上 到亚达珥,绕 到甲加, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, '接连 到押们,通 到埃及 小河,直通 到 海 为止。这 就是 他们的 南 界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, '东 界 是从盐 海 南边到 约旦河 口。北 界 是从约旦河 口 的海 汊起, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, ' 上到伯‧曷拉,过伯‧亚拉巴 的北边, 上 到流便 之子 波罕 的磐石; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, '从亚割 谷 往北, 上 到底璧, 直 向 河 南 亚都冥 坡 对面 的 吉甲; 又接连 到隐‧示麦 泉, 直通 到隐‧罗结, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, ' 上 到欣嫩 子 谷,贴近 耶布斯 的南 界(耶布斯就是 耶路撒冷); 又上 到 欣嫩 谷 西 边 的 山 顶,就是 在利乏音 谷 极北的 边界; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, ' 又从山 顶 延 到 尼弗多亚 的水 源,通 到 以弗仑  山 的城邑, 又延 到巴拉(巴拉就是基列‧耶琳); ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, ' 又从巴拉 往西 绕 到 西珥 山,接连 到 耶琳 山 的北 边(耶琳就是 基撒仑 );又下到伯‧示麦 过 亭纳, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, ' 通 到 以革伦 北 边, 延 到施基仑 ,接连 到巴拉 山;又通 到雅比聂, 直通到海 为 止。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, '西 界 就是大 海 和靠近大海之地。这 是犹大 人 按著宗族 所得之地四围 的交界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, '约书亚 照 耶和华 所吩咐的,将犹大 人 中 的一段地,就是基列‧亚巴,分给 耶孚尼 的儿子 迦勒。亚巴是亚衲族 的始祖(基列‧亚巴就是 希伯仑 )。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, '迦勒 就从那里 赶出 亚衲族 的三个 族长,就是 示筛、 亚希幔、 挞买 ; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, '又从那里 上去,攻击 底璧 的居民。(这底璧 从前 名叫基列‧西弗。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, '迦勒 说:「谁 能攻打基列‧西弗 将城夺取,我就把 我女儿 押撒 给 他 为妻。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, '迦勒 兄弟 基纳斯 的儿子 俄陀聂 夺取了那城,迦勒就把 女儿 押撒 给 他 为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, ' 押撒过门的时候,劝 丈夫向 她父亲 求 一块田,押撒一 下 驴,迦勒 问她 说:「你 要什么?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, '她说:「求你赐 福 给我,你既 将我安置 在南 地,求你也给 我 水 泉。」她父亲就把 上 泉 下 泉 赐 给她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, '以下是 犹大 支派 按著宗族 所得的产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, '犹大 支派 尽 侭 南边 的城邑,与以东 交界 相近的,就是 甲薛、以得、雅姑珥、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, '基拿、底摩拿、亚大达、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, '基低斯、夏琐、以提楠、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, '西弗、提炼 链 𫔀、比亚绿、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, '夏琐‧哈大他、加略‧希斯仑 (加略‧希斯仑 就是 夏琐)、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, '亚曼、示玛、摩拉大、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, '哈萨‧迦大、黑实门、伯‧帕列、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, '哈萨‧书亚、别是巴、比斯约他、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, '巴拉、以因、以森、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, '伊勒多腊、基失、何珥玛、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, '洗革拉、麦玛拿、三撒拿、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, '利巴勿、实忻、亚因、临门,共 二十 九 座城,还有属城的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, '在高原 有以实陶、琐拉、亚实拿、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, '撒挪亚、隐‧干宁、他普亚、以楠、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, '耶末、亚杜兰、梭哥、亚西加、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, '沙拉音、亚底他音、基底拉、基底罗他音,共十 四 座城,还有属城的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, '又有洗楠、哈大沙、麦大‧迦得、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, '底连、米斯巴、约帖、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, '拉吉、波斯加、伊矶伦、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, '迦本、拉幔、基提利、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, '基低罗、伯‧大衮、拿玛、玛基大,共十 六 座城,还有属城的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, '又有立拿、以帖、亚珊、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, '益弗他、亚实拿、尼悉、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, '基伊拉、亚革悉、玛利沙,共九座 城,还有属城的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, '又有以革伦 和属以革伦的镇市 村庄; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, '从以革伦 直到海,一切 靠近 亚实突 之地,并属其地的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, '亚实突 和属亚实突的镇市 村庄;迦萨 和属迦萨的镇市 村庄;直到 埃及 小河,并大 海 和靠近大海之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, '在山地 有沙密、雅提珥、梭哥、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, '大拿、基列‧萨拿(基列‧萨拿就是 底璧)、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, '亚拿伯、以实提莫、亚念、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, '歌珊、何伦、基罗,共十 一 座城,还有属城的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, '又有亚拉、度玛、以珊、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, '雅农、伯‧他普亚、亚非加、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, '宏他、基列‧亚巴(基列‧亚巴就是 希伯仑 )、洗珥,共九座 城,还有属城的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, '又有玛云、迦密、西弗、淤他、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, '耶斯列、约甸、撒挪亚、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, '该隐、基比亚、亭纳,共十座 城,还有属城的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, '又有哈忽、伯‧夙、基突、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, '玛腊、伯‧亚诺、伊勒提君,共六座 城,还有属城的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, '又有基列‧巴力(基列‧巴力就是基列‧耶琳)、拉巴,共两座 城,还有属城的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, '在旷野有伯‧亚拉巴、密丁、西迦迦、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, '匿珊、盐城、隐‧基底,共六座 城,还有属城的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, '至于  住 耶路撒冷 的耶布斯人,犹大 人 不 能 把他们赶出去,耶布斯人 却在耶路撒冷 与 犹大 人 同住,直到 今 日。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, '约瑟 的子孙 拈 阄所得之地 是从靠近耶利哥 的约旦河起,以耶利哥 东边 的水为界:从耶利哥 上去,通过山地 的旷野,到伯特利; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, ' 又从伯特利 到路斯,接连 到 亚基人 的境界,至亚他绿; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, '又往西 下 到 押利提人 的境界,到 下伯‧和仑  的境界,直到 基色,通到海 为 止。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, '约瑟 的儿子 玛拿西、以法莲 就得了他们的地业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, '以法莲 子孙 的境界,按著宗族所得的,记在下面:他们地业 的东 界 是亚他绿‧亚达 到 上伯‧和仑 ; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, ' 往西 通到北边的 密米他,又 向东 绕到他纳‧示罗,又接连 到雅挪哈 的东边; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, '从雅挪哈 下 到亚他绿,又到拿拉,达 到耶利哥,通 到约旦河为止; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, ' 从他普亚 往西,到加拿 河,直通到海 为 止。这就是 以法莲 支派 按著宗族 所得的地业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, '另外 在玛拿西 人 地业 中 得了些城邑 和属城的村庄。这都 是分给以法莲 子孙的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, '他们没有 赶出 住 基色 的 迦南人;迦南人 却住 在以法莲人 中间,成为 做苦工 的仆人,直到 今日。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, ' 玛拿西 是 约瑟 的长子,他的支派 拈阄 所得之地记在下面。至于 玛拿西 的长子 基列 之父(或译:主)玛吉,因为 是 勇士 就得了 基列 和巴珊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, '玛拿西 其余 馀 的子孙,按著宗族拈阄分地,就是 亚比以谢 子孙,希勒 子孙,亚斯列 子孙,示剑 子孙,希弗 子孙,示米大 子孙;这些按著宗族,都是约瑟 儿子 玛拿西 子孙 的男丁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, '玛拿西 的玄孙,玛吉 的曾孙,基列 的孙子,希弗 的儿子 西罗非哈 没有 儿子,只有 女儿。 他的女儿 名 叫玛拉、挪阿、曷拉、密迦、得撒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, '她们来到 祭司 以利亚撒 和嫩 的儿子 约书亚 并众首领 面前,说:「耶和华 曾吩咐 摩西 在我们弟兄 中 分 给我们 产业。」于 是约书亚 照 耶和华 所吩咐的,在她们伯叔 中,把产业 分 给她们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, '除了 约旦河 东 的基列 和巴珊 地之外,还有十 分地 归 玛拿西, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, '因为 玛拿西 的孙女们 在玛拿西的孙子 中 得了 产业。基列 地 是 属玛拿西 其余 馀的 子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, ' 玛拿西 的境界:从亚设起,到 示剑 前 的 密米他, 往 北 到隐‧他普亚 居民之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, '他普亚 地 归 玛拿西,只是玛拿西 境界 上 的他普亚城 归以法莲 子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, '其界 下 到加拿 河 的南边。 在玛拿西 城邑 中 的这些 城邑 都归以法莲。玛拿西 的地界 是在河 北 直通 到海 为止; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, '南 归以法莲,北 归玛拿西,以海 为 界;北边 到 亚设,东边 到以萨迦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, '玛拿西 在以萨迦 和亚设境内,有伯‧善和属伯‧善的镇市,以伯莲 和属以伯莲的镇市, 多珥的居民 和属多珥 的镇市;又有三 处山冈,就是隐‧多珥和属隐‧多珥的镇市;他纳 的居民 和属他纳的镇市,米吉多 的居民 和属米吉多的镇市。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, '只是玛拿西 子孙 不 能 赶出 这些 城的居民,迦南人 偏要 住 在那 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, '及至 以色列 人 强盛了,就使 迦南人 做苦工,没有 把他们全然 赶出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, '约瑟 的子孙 对 约书亚 说:「耶和华 到如今 既然 赐福与我们,我们 也族 大人多,你为什么 仅将一 阄 一 段 之地分给 我们 为业呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, '约书亚 说:「你们 如果 族 大人多,嫌 以法莲 山 地窄小,就可以上 比利洗人、利乏音人 之地,在树林中 砍伐树木。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, '约瑟 的子孙 说:「那山地 容 不 下我们,并且住 平原 的迦南人,就是住伯‧善和属伯‧善的镇市,并 住耶斯列 平原的人,都 有铁 车。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, '约书亚 对 约瑟 家,就是以法莲 和玛拿西人,说:「你是 族 大人多,并且强盛,不可 仅有 一 阄之地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, ' 山地 也要 归你,虽 是 树林,你也可以砍伐;靠近之地 必 归你。迦南人 虽 有铁 车,虽 是 强盛,你也能 把他们 赶出去。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, '以色列 的全 会众 都聚集 在示罗,把 会 幕 设立 在那里,那地 已经被他们 制伏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, '以色列 人中 其余 馀的 七个 支派 还没有 分 给他们 地业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, '约书亚 对 以色列 人 说:「耶和华-你们列祖的 神 所 赐 给你们的 地,你们 耽延 不去 得,要到 几时呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, '你们 每支派 当选举 三个 人,我要打发他们去,他们就要起身 走 遍那地,按著 各支派应得的地业 写明(或译:画 划图),就回到 我这里来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, '他们要将 地分 做七 分;犹大 仍在南方,住 在 他的境内。约瑟 家 仍在北方,住 在 他的境内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, '你们 要将 地 分做七 分,写明了 拿 到我 这里来。 我要在耶和华─我们 神 面前,为你们 拈 阄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, ' 利未人 在你们中间 没有 分,因为 供耶和华 祭司的职任 就是他们的产业。迦得支派、流便支派,和玛拿西 半 支派 已经在 约旦河 东 得了 地业,就是耶和华 仆人 摩西 所 给 他们的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, '划 㓰 地势 的人 起身 去的时候,约书亚 嘱咐 他们 说:「你们去 走 遍那地,划 㓰明 地势,就回 到我这里来。我要在示罗 这里,耶和华 面前,为你们 拈 阄。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, '他们 就去了,走遍 那地,按著城邑 分做七 分,写 在 册子上,回 到 示罗 营 中见 约书亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, '约书亚 就在示罗,耶和华 面前,为他们 拈 阄。约书亚 在那里,按著以色列 人的 支派,将 地 分给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, ' 便雅悯 支派,按著宗族 拈 阄 所得之地,是在 犹大、约瑟 子孙 中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, '他们 的北 界 是 从 约旦河起, 往上 贴近 耶利哥 的北 边;又往 西 通过山地,直到伯‧亚文 的旷野; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, ' 从那里 往南 接连 到路斯,贴近 路斯(路斯就是 伯特利), 又下到亚他绿‧亚达, 靠近 下伯‧和仑  南边 的山; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, ' 从那里往 西,又转 向 南,从伯‧和仑  南 对 面 的山,直达 到 犹大 人 的城基列‧巴力(基列‧巴力就是基列‧耶琳);这是 西 界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, '南 界是从基列‧耶琳 的尽 侭边起, 往 西 达 到 尼弗多亚 的水 源; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, ' 又下 到 欣嫩 子 谷 对 面 山 的尽 侭边,就是 利乏音 谷 北边的山;又下 到欣嫩 谷,贴近 耶布斯 的南 边;又下到隐‧罗结; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, '又往 北 通到隐‧示麦,达 到 亚都冥 坡 对面的 基利绿;又下 到流便 之子 波罕 的磐石; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, '又接连 到 亚拉巴 对面,往北 下 到亚拉巴; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, ' 又接连 到伯‧曷拉 的北 边, 直通 到 盐 海 的北 汊, 就是约旦河 的南 头;这是 南 界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, '东 界 是约旦河。这是 便雅悯 人 按著宗族,照他们四围 的交界 所得的地业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, '便雅悯 支派 按著宗族 所得的城邑 就是:耶利哥、伯‧曷拉、伊麦‧基悉、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, '伯‧亚拉巴、洗玛脸、伯特利、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, '亚文、巴拉、俄弗拉、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, '基法‧阿摩尼、俄弗尼、迦巴,共十 二 座城,还有属城的村庄; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, '又有基遍、拉玛、比录、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, '米斯巴、基非拉、摩撒、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, '利坚、伊利毘勒、他拉拉、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, '洗拉、以利弗、耶布斯(耶布斯就是 耶路撒冷)、基比亚、基列,共十 四 座城,还有属城的村庄。这是 便雅悯 人 按著宗族 所得的地业。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, '为西缅 支派 的人,按著宗族,拈出 第二 阄。他们所得的地业 是 在犹大 人 地业 中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, '他们 所得为业 之地就是:别是巴(或名示巴)、摩拉大、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, '哈萨‧书亚、巴拉、以森、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, '伊利多拉、比土力、何珥玛、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, '洗革拉、伯‧玛加博、哈萨‧苏撒、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, '伯‧利巴勿、沙鲁险,共十 三 座城,还有属城的村庄; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, '又有亚因、利门、以帖、亚珊,共四座 城,还有属城的村庄; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, '并有这些 城邑 四围 一切的 村庄,直到巴拉‧比珥,就是南地 的拉玛。这是 西缅 支派 按著宗族 所得的地业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, '西缅 人 的地业 是从犹大 人 地业中得来的;因为 犹大 人 的分 过多,所以西缅 人 在他们的地业 中 得了地业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, '为西布伦 人,按著宗族,拈出 第三 阄。他们地业 的境界 是 到 撒立; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, ' 往西 上 到玛拉拉,达 到大巴设,又达 到 约念 前 的 河; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, '又从撒立 往东 转 向日 出之地,到吉斯绿‧他泊 的境界,又通 到 大比拉,上 到雅非亚; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, '从那里 往东,接连到迦特‧希弗,至以特‧加汛,通 到临门,临门延到 尼亚; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, ' 又绕过 尼亚 的北边,转到哈拿顿,通到伊弗他‧伊勒 谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, '还有加他、拿哈拉、伸仑 、以大拉、伯利恒,共十 二 座城,还有属城的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, '这些 城 并属城的村庄 就是 西布伦 人 按著宗族 所得的地业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, '为以萨迦 人,按著宗族,拈出 第四 阄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, '他们的境界 是 到耶斯列、基苏律、书念、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, '哈弗连、示按、亚拿哈拉、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, '拉璧、基善、亚别、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, '利篾、隐‧干宁、隐‧哈大、伯‧帕薛; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, ' 又达 到他泊、沙哈洗玛、伯‧示麦, 直通 到约旦河为止,共十 六 座城,还有属城的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, '这些城 并属城的村庄 就是 以萨迦 支派 按著宗族 所得的地业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, '为亚设 支派,按著宗族,拈出 第五 阄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, '他们的境界 是 黑甲、哈利、比田、押煞、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, '亚拉米勒、亚末、米沙勒;往西 达 到迦密,又到希曷‧立纳, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, '转 向日 出之地,到伯‧大衮,达 到细步纶;往北到伊弗他‧伊勒 谷,到伯‧以墨 和尼业,也通 到 迦步勒 的左边; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, '又到义伯仑 、利合、哈们、加拿,直到 西顿 大城; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, ' 转 到拉玛 和 坚固 城 泰尔; 又转 到何萨, 靠近亚革悉 一带地方,直通 到海; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, '又有乌玛、亚弗、利合,共二十 二 座城,还有属城的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, '这些 城 并属城的村庄 就是 亚设 支派 按著宗族 所得的地业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, '为拿弗他利 人,按著宗族,拈出 第六 阄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, '他们的境界 是 从希利弗 从撒拿音 的橡树,从亚大米‧尼吉 和雅比聂,直到 拉共,通到 约旦河; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, ' 又转 向西到亚斯纳‧他泊,从那里 通 到户割,南边 到 西布伦,西边 到 亚设,又向日 出之地,达到约旦河 那里的犹大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, '坚固的 城就是:西丁、侧耳、哈末、拉甲、基尼烈、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, '亚大玛、拉玛、夏琐、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, '基低斯、以得来、隐‧夏琐、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, '以利稳、密大‧伊勒、和琏、伯‧亚纳、伯‧示麦,共十 九 座城,还有属城的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, '这些城 并属城的村庄 就是 拿弗他利 支派 按著宗族 所得的地业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, '为但 支派,按著宗族,拈出 第七 阄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, '他们地业 的境界 是 琐拉、以实陶、伊珥‧示麦、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, '沙拉宾、亚雅仑 、伊提拉、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, '以伦、亭拿他、以革伦、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, '伊利提基、基比顿、巴拉、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, '伊胡得、比尼‧比拉、迦特‧临门、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, '美‧耶昆、拉昆,并 约帕 对面的 地界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, '但 人 的地界 越过 原得的地界;因为但 人 上去 攻 取 利善,用 刀 击杀 城中的人,得了 那城,住 在其中,以他们先祖 但 的名 将利善 改名 为但。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, '这些 城 并属城的村庄 就是 但 支派 按著宗族 所得的地业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, '以色列 人 按著境界 分 完 了 地业,就在他们中间 将地给 嫩 的儿子 约书亚 为业, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, '是照 耶和华 的吩咐,将 约书亚 所 求 的城,就是 以法莲 山地的亭拿‧西拉城,给了 他。他就修 那 城,住 在其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, '这就是 祭司 以利亚撒 和嫩 的儿子 约书亚,并以色列 各支派 的族 长,在示罗 会 幕 门口,耶和华 面前,拈阄 所 分 的地业。这样,他们把 地 分 完了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, '耶和华 晓谕 约书亚 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, '「你吩咐 以色列 人 说:你们要照著我藉 借 摩西 所 晓谕 你们的,为自己 设立 逃 城, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, '使那 无 心 而误 杀 人的,可以逃 到那里。这些城可以作 你们 逃避 报 血仇人的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, '那杀人的要逃 到 这些 城中 的一座城,站 在城 门 口,将 他的事情 说给 城内 的长老 们听。他们就把他 收 进 城里,给 他 地方,使他住 在他们中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, '若是 报 血 仇的追了 他来,长老不可 将 他 交 在报血仇的手里;因为 他是 素 无 仇恨,无 心 杀了 人的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, '他要住 在那 城里, 站 在会众 面前 听审判,等到 那 时 的大 祭司 死了,杀人的 才 可以回 到 本城 本家, 就是他所 逃 出来的那 城。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, '于 是,以色列人在拿弗他利 山地 分定 加利利的 基低斯;在以法莲 山地分定 示剑;在犹大 山地分定基列‧亚巴(基列‧亚巴就是 希伯仑 ); ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, '又在约旦河 外 耶利哥 东,从流便 支派中,在旷野 的平原,设立 比悉;从迦得 支派 中设立基列的 拉末;从玛拿西 支派 中设立巴珊的 哥兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, '这 都是 为以色列 众 人 和在他们中间 寄居的 外人 所分定 的城邑,使误 杀 人 的都 可以逃 到那里,不 死 在报 血 仇人的手中,等 他站 在会众 面前听审判。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, '那时,利未人 的众族 长 来 到 祭司 以利亚撒 和 嫩 的儿子 约书亚,并 以色列 各支派 的族 长面前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, ' 在迦南 地 的示罗 对他们 说:「从前耶和华 藉 借著 摩西 吩咐 给 我们 城邑 居住,并城邑的郊野 可以牧养我们的牲畜。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, '于 是以色列 人 照 耶和华 所吩咐的,从自己的地业中,将 以下所记 的城邑 和 城邑的郊野 给了 利未人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, '为哥辖 族 拈 阄: 利未人 的 祭司、亚伦 的子孙,从犹大 支派、西缅 支派、便雅悯 支派的地业中,按阄 得了十 三 座城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, '哥辖 其余 馀的 子孙,从以法莲 支派、但 支派、玛拿西 半 支派的地业中,按阄 得了十座 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, '革顺 的子孙,从以萨迦 支派、亚设 支派、拿弗他利 支派、住巴珊 的玛拿西 半 支派的地业中,按阄 得了十 三 座城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, '米拉利 的子孙,按著宗族,从流便 支派、迦得 支派、西布伦 支派的地业中,按阄得了十 二 座城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, '以色列 人 照著 耶和华 藉 借 摩西 所吩咐的,将 这些 城邑 和 城邑的郊野,按阄 分 给利未人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, ' 从犹大 支派、西缅 支派的地业中,将 以下 所 记 的城 给了 利未 支派 哥辖 宗族 亚伦 的子孙;因为 给他们 拈出 头一 阄, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, '将 犹大 山地的基列‧亚巴 和 四围的 郊野 给了 他们。亚巴是亚衲族 的始祖。(基列‧亚巴就是 希伯仑 )。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, '惟将 属城 的田地 和 村庄 给了 耶孚尼 的儿子 迦勒 为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, '以色列 人将 希伯仑 ,就是 误杀人 的逃 城 和 属城的郊野,给了 祭司 亚伦 的子孙;又给他们 立拿 和 属城的郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, ' 雅提珥 和 属城的郊野, 以实提莫 和 属城的郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, ' 何仑  和 属城的郊野, 底璧 和 属城的郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, ' 亚因 和 属城的郊野, 淤他 和 属城的郊野,伯‧示麦 和 属城的郊野,共九座 城,都是从 这 二 支派中分出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, '又从便雅悯 支派的地业中给了他们 基遍 和 属城的郊野, 迦巴 和 属城的郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, ' 亚拿突 和 属城的郊野, 亚勒们 和 属城的郊野,共四座 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, '亚伦 子孙 作祭司 的 共 有十 三 座城,还有属城的郊野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, '利未支派中 哥辖 的宗族,就是哥辖 其余 馀的 子孙,拈阄 所得 的城 有从以法莲 支派中分出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, '以色列人将 以法莲 山地 的示剑,就是 误杀人的 逃 城 和 属城的郊野,给了 他们;又给他们 基色 和 属城的郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, ' 基伯先 和 属城的郊野,伯‧和仑  和 属城的郊野,共四座 城; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, '又从但 支派的地业中给了他们 伊利提基 和 属城的郊野, 基比顿 和 属城的郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, ' 亚雅仑  和 属城的郊野,迦特‧临门 和 属城的郊野,共四座 城; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, '又从玛拿西 半 支派的地业中给了他们 他纳 和 属城的郊野,迦特‧临门 和 属城的郊野,共两座 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, '哥辖 其余 馀的 子孙 共 有十座 城,还有属城的郊野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, '以色列 人又从玛拿西 半 支派 的地业中将 巴珊 的哥兰,就是 误杀人的 逃 城 和 属城的郊野,给了利未 支派 革顺 的子孙;又给他们比‧施提拉 和 属城的郊野,共两座 城; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, '又从以萨迦 支派的地业中给了他们 基善 和 属城的郊野, 大比拉 和 属城的郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, ' 耶末 和 属城的郊野,隐‧干宁 和 属城的郊野,共四座 城; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, '又从亚设 支派的地业中给了他们 米沙勒 和 属城的郊野, 押顿 和 属城的郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, ' 黑甲 和 属城的郊野, 利合 和 属城的郊野,共四座 城; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, '又从拿弗他利 支派 的地业中将 加利利 的基低斯,就是 误杀人 的逃 城 和 属城的郊野,给了他们;又给他们哈末‧多珥 和 属城的郊野, 加珥坦 和 属城的郊野,共三座 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, '革顺人 按著宗族 所得的城,共 十 三 座,还有属城的郊野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, '其余 馀 利未 支派米拉利 子孙,从 西布伦 支派的地业中所得的,就是 约念 和 属城的郊野, 加珥他 和 属城的郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, ' 丁拿 和 属城的郊野, 拿哈拉 和 属城的郊野,共四座 城; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, '又从流便 支派的地业中给了他们 比悉 和 属城的郊野, 雅杂 和 属城的郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, ' 基底莫 和 属城的郊野, 米法押 和 属城的郊野,共四座 城; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, '又从迦得 支派的地业中,将 基列 的拉末,就是 误杀人的 逃 城 和 属城的郊野,给了他们;又给他们 玛哈念 和 属城的郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, ' 希实本 和 属城的郊野, 雅谢 和 属城的郊野,共 四座 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, '其余 馀 利未 支派的人,就是米拉利 的子孙,按著宗族 拈阄 所得 的,共 十 二 座城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, '利未人 在以色列 人 的地业 中 所得的城,共 四十 八 座,并有属城的郊野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, '这些 城 四围 都有 属城 的郊野,城 城 都 是 如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, '这样,耶和华 将 从前向他们列祖 起誓 所应许 的全 地 赐 给以色列人,他们就得了为业,住 在其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, '耶和华 照著向他们列祖 起誓 所 应许的一切话,使他们 四境 平安;他们一切 仇敌中,没有 一人 在他们面前 站立得住。耶和华 把 一切 仇敌 都交 在他们手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, '耶和华 应许 赐福 给 以色列 家 的话 一 句 也没有 落空,都 应验了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, '当时,约书亚 召了 流便人、迦得人,和玛拿西 半 支派的人来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, '对他们 说:「 耶和华 仆人 摩西 所 吩咐 你们的,你们 都 遵守了;我所 吩咐 你们的,你们也都 听从了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, '你们这 许多 日子,总没有 撇离 你们的弟兄,直到 今 日,并守了 耶和华─你们 神 所吩咐 你们当守的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, '如今 耶和华─你们 神 照著 他所应许的,使你们弟兄 得享平安,现在 可以转回 你们 的帐棚,到 耶和华 的仆人 摩西 在约旦河 东 所 赐 你们 为业 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, '只要 切切地 谨慎 遵行 耶和华 仆人 摩西 所 吩咐你们的 诫命 律法,爱 耶和华─你们的 神,行 他一切 的道,守 他的诫命,专靠 他,尽 心 尽 性 事奉他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, '于 是约书亚 为他们祝福,打发他们去,他们就回 自己的帐棚 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, '玛拿西 那半 支派,摩西 早已在巴珊 分给他们地业。这半支派,约书亚 在 约旦河 西,在 他们弟兄中,分给他们地业。 约书亚 打发 他们回 帐棚 的时候 为他们祝福, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, ' 对他们 说:「你们带许多 财物,许 多 牲畜 和金、银、铜、铁,并许 多 衣服,回 你们的帐棚去,要将你们从仇敌 夺来的物,与 你们众弟兄 同分。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, '于 是流便 人、迦得 人、玛拿西 半 支派 的人从迦南 地 的 示罗 起行,离开  以色列 人,回 往 他们得为业的 基列 地,就是 照 耶和华 藉 借 摩西 所吩咐的 得了 为业 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, '流便 人、迦得 人,和玛拿西 半 支派 的人到了 靠近 约旦河 的一带 迦南 地,就在 约旦河 那里 筑了 一座坛;那坛 看著 高大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, '以色列 人 听 说 流便 人、迦得 人、玛拿西 半 支派 的人靠近 约旦河 边,在 迦南 地 属 以色列 人 的那边 筑了 一座坛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, ' 全 会众 一听见, 就聚集 在示罗,要上去 攻打 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, '以色列 人 打发 祭司 以利亚撒 的儿子 非尼哈,往 基列 地 去见 流便 人、 迦得 人、 玛拿西 半 支派的人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, '又打发十个 首领 与非尼哈同去,就是 以色列 每 支派 的一个 首领,都 是 以色列 军中 的统领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, '他们到 了 基列 地,见 流便 人、 迦得 人,和 玛拿西 半 支派的人, 对他们 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, '「耶和华 全 会众 这样 说,你们今日 转去 不跟从 耶和华,干犯 以色列的 神,为自己 筑 一座坛,悖逆了 耶和华, 这 犯的 是什么 罪呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, ' 从前拜毘珥 的罪孽 还算小吗?虽然瘟疫 临到 耶和华 的会众,到 今 日 我们 还没有 洗净 这罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, '你们 今日 竟转去 不跟从 耶和华吗?你们 今日 既悖逆 耶和华,明日 他必 向 以色列 全 会众 发怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, ' 你们所得为业 之地,若 嫌不洁净,就可以过 到 耶和华 之地,就是 耶和华 的帐幕 所住 之地,在我们中间 得 地业。只是不可 悖逆 耶和华,也不可 得罪 我们,在耶和华─我们 神 的坛 以外 为自己 筑 坛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, '从前谢拉 的曾孙 亚干 岂不是 在那当灭的物上 犯了 罪,就有 忿怒 临到 以色列 全 会众吗?那 人 在所犯的罪中 不 独一人 死亡。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, '于 是流便 人、迦得 人、玛拿西 半 支 派的人回答 以色列 军中 的统领 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, '「大能者 神 耶和华!大能者 神 耶和华!他是 知道的!以色列 人也必 知道!我们若 有悖逆的意思,或是 干犯 耶和华(愿 你今 日 不 保佑我们), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, '为自己 筑 坛,要转去 不跟从 耶和华,或是 要将燔祭、素祭、 平安 祭 献 在坛上,愿 耶和华 亲自 讨我们的罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, ' 我们行 这 事并非无 故,是特意做的,说:恐怕 日后 你们的子孙 对我们的子孙 说:『你们 与耶和华─以色列的 神 有何关涉呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, '因为耶和华 把 约旦河 定为 我们 和你们 这流便 人、迦得 人 的交界,你们 与耶和华 无 分了。』这样,你们的子孙 就使 我们的子孙 不再 敬畏 耶和华了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, '因此我们说:『不如 为自己 筑 一座坛,不是 为献燔祭,也不是 为献别的祭, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, '乃 是 为你 我中间 和你我后 人 中间 作证据,好叫我们也在耶和华 面前 献 燔祭、平安祭,和别的祭 事奉他,免得 你们的子孙 日后 对我们的子孙 说,你们 与耶和华 无 分了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, '所以 我们说:『日后你们对我们,或对 我们的后 人 这样说,我们就可以回答说,你们看 我们列祖 所 筑 的坛是耶和华 坛 的样式;这并不是 为献燔祭,也不是 为献别的祭,乃 是 为作你 我中间 的证据。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, '我们在耶和华─我们 神 帐幕 前 的 坛 以外,另筑 一座坛,为献燔祭、素祭,和别的祭, 悖逆 耶和华,今日 转去 不跟从 他,我们 断没有这个意思。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, '祭司 非尼哈 与会 中的首领,就是 与他 同来以色列 军中 的统领,听见 流便 人、迦得 人、玛拿西 人 所 说 的话,就都以为 美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, '祭司 以利亚撒 的儿子 非尼哈 对 流便 人、 迦得 人、 玛拿西 人 说:「今日 我们知道 耶和华 在我们中间,因为 你们没有 向他 犯了 这 罪。现在 你们救 以色列 人 脱离耶和华 的手了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, '祭司 以利亚撒 的儿子 非尼哈 与众首领 离了 流便 人、 迦得 人,从基列 地 回 往 迦南 地,到了 以色列 人那里,便将这事 回 报他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, '以色列 人 以这事 为 美, 就称颂 神,不 再提 上去 攻打 流便 人、迦得 人、毁坏 他们所 住的 地了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, '流便 人、迦得 人 给坛 起名叫证坛,意思说:这坛 在我们中间 证明 耶和华是 神。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, ' 耶和华 使以色列人 安静,不与四围 的一切 仇敌争战 ,已经 多 日。约书亚 年纪 老 迈, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, ' 就把以色列 众人 的长老、族长、审判官,并官长 都召了来,对他们 说:「我 年纪 已经老 迈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, ' 耶和华─你们的 神 因你们的缘故 向 那些 国 所 行 的一切事,你们 亲眼看见了,因 那 为你们 争战  的是耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, ' 我所 剪除 和所剩下的 各 国,从 约旦河 起到日 落之处 的大 海,我已经拈阄分 给你们 各支派 为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, '耶和华─你们的 神 必 将他们从你们面前 赶出去,使他们 离开  你们,你们就必得 他们的地为业,正如耶和华─你们的 神 所 应许的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, '所以,你们要大大 壮胆,谨守 遵行 写 在摩西 律法 书上 的一切话,不可 偏离 左 右。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, '不可 与你们中间 所 剩下的 这些 国民 搀杂。他们的神,你们不可 提 他的名,不可 指著他起誓,也不可 事奉、 叩拜; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, '只要 照著 你们到 今 日 所行的,专靠 耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, '因为耶和华 已经把又大 又强 的国民 从你们面前 赶出; 直到 今 日,没有 一人 在你们面前 站立得住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, '你们 一 人 必追赶 千人,因 耶和华─你们的 神 照他所 应许的,为你们 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, '你们 要分外 谨慎,爱 耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, ' 你们若 稍微 转去,与你们中间 所 剩下的 这些 国民 联络,彼此 结亲,互相 往来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, '你们要确实 知道, 耶和华─你们的 神 必不 再 将 他们 从你们眼前 赶出;他们却要成为 你们 的网罗、机槛、肋上 的鞭、眼中 的刺,直到 你们在 耶和华─你们 神 所 赐的 这 美 地 上灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, '「 我 现在 要走 世人 必走的路。你们是一 心 一 意地 知道, 耶和华─你们 神 所 应许 赐福 与你们 的话 没有 一 句 落空,都 应验 在你们身上了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, '耶和华─你们 神 所 应许的 一切 福气 怎样 临 到你们身上,耶和华 也必 照样 使 各样 祸患 临 到你们身上,直到 把你们 从 耶和华─你们 神 所 赐的 这 美 地 上除灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, '你们若违背 耶和华─你们 神 吩咐 你们所守的 约,去 事奉 别 神,叩拜 他,耶和华 的怒气 必向你们 发作,使你们在 他所 赐的 美 地 上速速 灭亡。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, '约书亚 将 以色列 的众 支派 聚集 在示剑,召了 以色列 的长老、族长、审判官,并官长来,他们就站在 神 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, '约书亚 对 众 民 说:「耶和华─以色列的 神 如此 说:『古时 你们的列祖,就是亚伯拉罕 和拿鹤 的父亲 他拉,住 在大河 那边 事奉 别 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, '我将 你们的祖宗 亚伯拉罕 从大河 那边 带来,领 他 走遍迦南 全 地,又使 他的子孙 众多,把 以撒 赐 给他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, '又把 雅各 和 以扫 赐 给以撒,将 西珥 山 赐 给以扫 为业;后来雅各 和他的子孙 下 到埃及去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, '我差遣 摩西、 亚伦,并照 我在埃及中 所行 的降灾 与 埃及,然后 把你们 领出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, '我领 你们列祖 出埃及,他们就到了 红海;埃及人 带领车辆 马兵 追 赶 你们列祖 到红 海。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, '你们列祖哀求 耶和华,他就使 你们 和埃及人 中间 黑暗了,又使 海水 淹没 埃及人。 我在埃及 所 行的事,你们亲眼 见过。你们在旷野 也住了 许多 年日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, '我领 你们 到 约旦河 东 亚摩利人 所住 之地。他们与你们 争战 ,我将他们 交 在你们手中,你们便得了 他们的地 为业;我也在你们面前 将他们灭绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, '那时,摩押 王 西拨 的儿子 巴勒 起来 攻击 以色列人,打发 人召了 比珥 的儿子 巴兰 来咒诅 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, '我不 肯 听 巴兰的话,所以他倒为你们 连连 祝福。这样,我便救 你们 脱离巴勒的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, '你们过了 约旦河,到 了 耶利哥;耶利哥 人、亚摩利人、比利洗人、迦南人、赫人、革迦撒人、希未人、耶布斯人 都与你们 争战 ;我把他们 交 在你们手里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, '我打发 黄蜂 飞在你们前面,将 亚摩利人 的二 王 从你们面前 撵出,并不是 用你的刀,也不是 用你的弓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, '我赐 给你们 地土,非 你们所 修治的;我赐给你们城邑,非 你们所 建造的。你们就住 在其中, 又得吃 非 你们所 栽种 的葡萄园、橄榄园的果子。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, '「现在 你们要敬畏 耶和华,诚心&lt;WAHb&gt;实意地&lt;WAHb&gt; 事奉 他,将 你们列祖 在大河 那边 和在埃及 所 事奉 的神 除掉,去事奉 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, '若是 你们以 事奉 耶和华 为不好,今日就 可以选择所要 事奉的:是 你们列祖 在大河 那边 所 事奉 的神呢?是 你们 所 住 这地 的亚摩利人 的神呢?至于 我 和我家,我们必定事奉 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, '百姓 回答 说:「我们 断不敢 离弃 耶和华 去事奉 别 神; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, '因 耶和华─我们的 神曾 将我们 和 我们列祖 从埃及 地 的为奴 之家 领出来, 在我们眼前 行了 那些 大 神迹,在 我们所 行 的 道上,所 经 过 的诸 国,都保护了我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, '耶和华 又把 住 此地的 亚摩利人 都 从我们面前 赶出去。所以,我们必 事奉 耶和华,因为 他是我们的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, '约书亚 对 百姓 说:「你们不 能 事奉 耶和华;因为 他是 圣洁的 神,是 忌邪的 神,必不 赦免 你们的过犯 罪恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, '你们若 离弃 耶和华 去事奉 外邦 神,耶和华在 降福 之后,必转 而降祸 与你们,把你们 灭绝。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, '百姓 回答 约书亚 说:「不然,我们定要 事奉 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, '约书亚 对 百姓 说:「 你们 选定 耶和华,要事奉 他,你们 自己 作见证吧!」他们说:「我们愿 意作见证。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, '约书亚说:「你们现在 要除掉 你们中间的 外邦 神,专 心 归向 耶和华─以色列的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, '百姓 回答 约书亚 说:「我们必事奉 耶和华─我们的 神,听从 他的话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, '当 日,约书亚 就与百姓 立 约,在示剑 为他们 立定 律例 典章。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, '约书亚 将 这些 话 都写在 神 的律法 书上,又将 一块大 石头 立 在橡树 下 耶和华 的圣所 旁边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, '约书亚 对 百姓 说:「看哪,这 石头 可以 向我们 作见证;因为 是 听见了 耶和华 所 吩咐 我们 的一切 话,倘或 你们背弃你们的 神,这石头就可以 向你们 作见证(倘或...见证:或译所以要向你们作见证,免得你们背弃耶和华─你们的 神)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, '于 是约书亚 打发 百姓 各 归自己的地业去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, ' 这些 事 以后,耶和华 的仆人 嫩 的儿子 约书亚,正一百 一十 岁,就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, '以色列 人将他 葬 在他地业 的境内,就是 在以法莲 山地的亭拿‧西拉,在迦实 山 的北边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, '约书亚 在世 和约书亚 死后,那些 知道 耶和华 为以色列人 所 行 诸 事 的长老 还在 的时候,以色列人 事奉 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, '以色列 人 从埃及 所 带来 约瑟 的骸骨,葬埋 在示剑,就是 在雅各 从前用一百 块银子 向 示剑 的父亲、哈抹 的子孙 所买 的 那块 地里;这就作了 约瑟 子孙 的产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, '亚伦 的儿子 以利亚撒 也死了,就把他 葬 在他儿子 非尼哈 所 得 以法莲 山 地的小山上。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, ' 约书亚 死 后,以色列 人 求问 耶和华 说:「我们中间 谁 当首先 上去 攻击 迦南人,与他们 争战 ?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, '耶和华 说:「犹大 当先上去,我已将 那地 交 在他手中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, '犹大 对他哥哥 西缅 说:「请你同我 到 拈阄所得之地去,好与迦南人 争战 ;以后我 也 同你 到 你拈阄所得之地去。」于 是西缅 与他 同去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, '犹大 就上去;耶和华 将 迦南人 和比利洗人 交 在他们手中。他们在比色 击杀了 一万 人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, '又在那里 遇见亚多尼‧比色,与他 争战 ,杀败 迦南人 和 比利洗人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, '亚多尼‧比色 逃跑;他们追 赶,拿住 他,砍断 他手 脚 的大拇指。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, '亚多尼‧比色 说:「从前有 七十个 王,手 脚 的大拇指 都被我砍断,在我桌子 底下 拾取零碎食物。现在 神 按著我所 行的 报应 我了。」于 是他们将亚多尼‧比色带到 耶路撒冷,他就死在 那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, '犹大 人 攻打 耶路撒冷,将城 攻取,用 刀 杀了城内的人,并且 放 火烧 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, '后来 犹大 人 下去,与住 山地、南地,和高原 的迦南人 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, '犹大人 去 攻击 住 希伯仑  的迦南人,杀了 示筛、 亚希幔、 挞买 。希伯仑  从前 名叫基列‧亚巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, '他们从那里 去 攻击 底壁 的居民;底壁 从前 名叫基列‧西弗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, '迦勒 说:「谁 能攻打基列‧西弗,将城夺取,我就把 我女儿 押撒 给 他 为妻。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, '迦勒 兄弟 基纳斯 的儿子 俄陀聂 夺取了那城,迦勒就把 女儿 押撒 给 他 为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, ' 押撒过门的时候,劝 丈夫向 她父亲 求 一块田。押撒一 下 驴,迦勒 问 她说:「你要 什么?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, '她说:「求你赐 福 给我,你既 将我安置在 南 地,求你也给 我 水 泉。」迦勒就把 上 泉 下 泉 赐 给她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, '摩西的内兄(或译:岳父)是基尼人,他的子孙 与 犹大 人 一同离了 棕树 城,往亚拉得 以南 的 犹大 旷野 去,就住 在 民中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, '犹大 和 他哥哥 西缅 同去,击杀了 住 洗法 的迦南人,将城 尽行毁灭,那城 的名 便叫 何珥玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, '犹大 又取了 迦萨 和 迦萨的四境, 亚实基伦 和 亚实基伦的四境, 以革伦 和 以革伦的四境。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, '耶和华 与 犹大 同在,犹大就赶出 山地的居民,只是 不能 赶出 平原 的居民,因为 他们有 铁 车。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, '以色列人照摩西 所 说的,将 希伯仑  给了 迦勒;迦勒就从那里 赶出 亚衲族 的三个 族长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, '便雅悯 人 没有 赶出 住 耶路撒冷 的 耶布斯人。耶布斯人 仍在耶路撒冷 与 便雅悯 人 同住,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, '约瑟 家 也 上去 攻打伯特利;耶和华 与他们同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, '约瑟 家 打发人去窥探 伯特利(那城 起先 名 叫路斯)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, '窥探的人 看见 一个人 从 城 里出来,就对他 说:「求你 将 进城 的路 指示我们,我们必恩 待 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, '那人将 进城 的路 指示他们,他们就用 刀 击杀了 城中的居民,但将 那人 和 他全 家 放去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, '那人 往赫人 之地 去,筑了 一座城,起 名 叫路斯。那城 到 如 今 还叫这名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, '玛拿西 没有 赶出伯‧善 和属伯‧善乡村的居民, 他纳 和 属他纳乡村的居民, 多珥 和 属多珥乡村 的居民, 以伯莲 和 属以伯莲乡村 的居民, 米吉多 和 属米吉多乡村 的居民;迦南人 却执意 住 在那些 地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, '及至 以色列 强盛了,就使 迦南人 做苦工,没有 把他们全然 赶出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, '以法莲 没有 赶出 住 基色 的迦南人。于 是迦南人 仍住 在基色,在以法莲中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, '西布伦 没有 赶出 基伦 的居民 和 拿哈拉 的居民。于 是迦南人 仍住在 西布伦中间,成了 服苦的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, '亚设 没有 赶出 亚柯 和 西顿 的居民, 亚黑拉 和 亚革悉的居民, 黑巴、 亚弗革 与 利合的居民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, '于 是,亚设 因为 没有 赶出 那地 的迦南人,就住在 他们 中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, '拿弗他利 没有 赶出伯‧示麦 和伯‧亚纳 的居民,于 是拿弗他利就住 在那地 的 迦南人 中间;然而伯‧示麦和伯‧亚纳 的居民 成了 服苦的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, '亚摩利人 强逼 但 人 住在山地, 不 容 他们下 到平原; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, '亚摩利人 却执意 住 在希烈 山 和亚雅伦 并沙宾。然而约瑟 家 胜了他们,使他们成了 服苦的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, '亚摩利人 的境界,是从亚克拉滨 坡,从西拉 而上。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, '耶和华 的使者 从 吉甲 上 到 波金,对以色列人说:「我使你们 从埃及 上来,领 你们 到 我向你们列祖 起誓 应许之 地。我又说:『我永 不 废弃 与你们 所立的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, '你们 也不可 与这 地 的居民 立 约,要拆毁 他们的祭坛。你们竟没有 听从 我的话!为何 这样 行呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, '因此我又 说:『我必不 将他们 从你们面前 赶出;他们必作 你们 肋下的荆棘。他们的 神 必作 你们的 网罗。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, ' 耶和华 的使者 向 以色列 众 人 说 这 话的时候,百姓 就放 声 而哭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, '于 是给那 地方 起名 叫 波金(就是哭的意思)。众人在那里 向耶和华 献祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, '从前约书亚 打发 以色列 百姓 去的时候,他们 各 归自己的地业,占据 地土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, '约书亚 在世 和 约书亚 死后,那些 见 耶和华 为以色列人 所 行 大 事 的 长老 还在 的时候,百姓 都事奉 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, '耶和华 的仆人、嫩 的儿子 约书亚,正一百 一十 岁 就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, '以色列人将他 葬 在他地业 的境内,就是在以法莲 山地的亭拿‧希烈,在迦实 山 的北边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, '那 世代 的人也 都 归 了 自己的列祖。后来 有别的 世代 兴起, 不 知道 耶和华,也不知道 耶和华 为以色列人 所 行 的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, '以色列 人 行 耶和华 眼中 看为恶的事,去事奉 诸巴力, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, '离弃了 领 他们 出埃及 地 的耶和华─他们列祖的 神,去 叩拜 别 神,就是 四围 列国 的神,惹 耶和华 发怒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, '并离弃 耶和华,去事奉 巴力 和亚斯她录。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, '耶和华 的怒气 向以色列人 发作,就把他们交在 抢 夺 他们 的人手中,又将他们付与 四围 仇敌 的手中,甚至他们在仇敌 面前 再 不 能 站立得住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, '他们无论往 何处 去,耶和华 都 以灾祸 攻击他们,正如耶和华 所 说的话,又如耶和华 向他们 所 起的誓;他们 便极其 困苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, '耶和华 兴起 士师,士师就拯救他们 脱离抢夺他们 人的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, '他们却 不 听从 士师,竟 随从 叩拜 别 神,行了邪淫,速速地 偏离 他们列祖 所 行 的 道,不 如 他们列祖顺从 耶和华 的命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, ' 耶和华 为他们 兴起 士师,就 与 那士师同在。士师 在世的一切 日子,耶和华 拯救他们 脱离仇敌 的手。他们因 受欺压 扰害,就哀声叹气,所以 耶和华 后悔了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, '及至 士师 死后,他们就转去 行恶,比他们列祖更甚,去 事奉 叩拜 别 神,总不 断绝 顽梗 的恶 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, '于 是耶和华 的怒气 向以色列人 发作。他说:「因 这 民 违背 我吩咐 他们列祖 所守的 约,不 听从 我的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, '所以约书亚 死的时候 所 剩下的 各族,我 必 不 再 从他们面前 赶出, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, '为要 借此 试验 以色列人,看他们 肯照 他们列祖 谨守 遵行 我 的道 不肯。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, '这样耶和华 留下各 族,不 将他们速速 赶出,也没有 交付 约书亚 的手。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, ' 耶和华 留下 这 几族,为要 试验 那 不曾 知道与 迦南 争战 之事的 以色列人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, '好叫 以色列 的后代 又知道 又学习 未曾 晓得 的战 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, '所留下的就是非利士 的五个 首领 和一切 迦南人、西顿人,并住 黎巴嫩 山 的希未人,从巴力‧黑们 山 直到 哈马 口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, '留下这几族,为要 试验 以色列人,知道 他们肯听从 耶和华 藉 借 摩西 吩咐 他们列祖 的诫命不肯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, '以色列 人 竟住在 迦南人、赫人、亚摩利人、比利洗人、希未人、耶布斯人 中间, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, '娶 他们的女儿 为妻,将 自己的女儿 嫁 给他们的儿子,并事奉 他们的神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, '以色列 人 行 耶和华 眼中 看为恶的事,忘记 耶和华─他们的 神,去事奉 诸巴力和 亚舍拉, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, '所以耶和华 的怒气 向以色列人 发作,就把他们交在 美索不达米亚 王古珊‧利萨田 的手中。以色列 人 服事古珊‧利萨田 八 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, '以色列 人 呼求 耶和华的时候,耶和华 就为他们 兴起 一位拯救者 救他们,就是 迦勒 兄弟 基纳斯 的儿子 俄陀聂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, '耶和华 的灵 降 在他身上,他就作了 以色列 的士师,出去 争战 。耶和华将 美索不达米亚 王古珊‧利萨田 交 在他手中,他 便胜了古珊‧利萨田。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, '于 是国中 太平 四十 年。基纳斯 的儿子 俄陀聂 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, '以色列 人 又 行 耶和华 眼中 看为恶的事,耶和华 就使 摩押 王 伊矶伦 强盛,攻击 以色列人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, '伊矶伦 招聚 亚扪 人 和亚玛力人,去 攻打 以色列人,占据 棕树 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, '于 是以色列 人 服事 摩押 王 伊矶伦 十八 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, '以色列 人 呼求 耶和华的时候,耶和华 就为他们 兴起 一位拯救者,就是 便雅悯 人 基拉 的儿子 以笏;他 是左 手 便利的。以色列 人 托 讬他 送 礼物 给摩押 王 伊矶伦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, '以笏 打了 一把两 刃 的剑,长 一肘,带 在 右 腿 上衣服 里面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, '他将 礼物 献 给摩押 王 伊矶伦(原来伊矶伦 极其 肥胖); ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, ' 以笏献 完 礼物,便将 抬 礼物 的人 打发走了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, '自己 却从 靠近 吉甲 凿石之地 回来,说:「王啊,我有 一件机密 事 奏告你。」王说:「回避吧!」于 是左右侍立的人 都 退去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, '以笏 来 到王面前;王 独自 一人 坐 在凉 楼上。以笏 说:「我奉 神 的命报告你 一件事。」王就从 座位 上站起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, '以笏 便伸 左 手,从 右 腿 上拔出 剑来,刺 入王的肚腹, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, '连 剑 把 都刺进去了。剑 被肥肉 夹 住, 他没有 从王的肚腹 拔出来,且穿通 了后身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, '以笏 就出 到游廊,将楼 门 尽都关 锁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, '以笏 出来之后,王的仆人 到了,看见 楼 门 关锁,就说:「他 必是 在楼上 大解。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, '他们等 烦了,见 仍不 开  楼 门,就拿 钥匙 开 了,不料,他们的主人 已死,倒 在地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, '他们耽延 的时候,以笏 就逃跑了, 经过 凿石之地,逃 到西伊拉; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, ' 到了,就在以法莲 山地 吹 角。以色列 人 随著他 下 了 山地,他 在前头引路, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, '对他们 说:「你们随我 来,因为 耶和华 已经把 你们的仇敌 摩押人 交 在你们手中。」于 是他们跟著他 下去,把守 约旦河 的渡口,不 容 摩押 一人 过去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, '那 时 击杀了 摩押 人 约有一万,都 是强壮的 勇 士,没有 一人 逃脱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, '这样,摩押就被 以色列人 制伏了。国 中太平 八十 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, '以笏之后,有 亚拿 的儿子 珊迦,他用赶牛 的棍子 打死 六 百 非利士 人。他 也 救了 以色列人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, '以笏 死后,以色列 人 又 行 耶和华 眼中 看为恶的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, '耶和华 就把他们付与 在夏琐 作王 的 迦南 王 耶宾 手中;他的将 军 是 西西拉,住在 外邦人 的夏罗设。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, ' 耶宾王有 铁 车 九 百辆。他 大大 欺压 以色列 人 二十 年,以色列 人 就呼求 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, '有一位女 先知 名叫底波拉,是拉比多 的妻,当 时 作 以色列 的士师。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, '她 住在 以法莲 山地 拉玛 和 伯特利 中间,在底波拉 的棕树 下。以色列 人 都上 她那里 去听判断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, '她打发 人从拿弗他利 的基低斯 将亚比挪庵 的儿子 巴拉 召了来,对他 说:「 耶和华─以色列的 神 吩咐你说:『你率 领 一万 拿弗他利 和西布伦 人 上他泊 山 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, '我必使 耶宾 的将 军 西西拉 率领 他的车辆 和 全军 往 基顺 河,到你那里去;我必将他交 在你手中。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, '巴拉 说:「你若 同我 去,我就去;你若 不 同我 去,我就不 去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, '底波拉说:「我必 与你 同去,只是 你 在 所 行 的路上 得 不 著荣耀,因为 耶和华 要将 西西拉 交 在一个妇人 手里。」于 是底波拉 起来,与 巴拉 一同往基低斯 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, '巴拉 就招聚 西布伦人 和 拿弗他利人 到基低斯,跟他 上去 的有一万 人。底波拉 也同他 上去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, '摩西 岳父(或译:内兄)何巴 的后裔,基尼 人 希百 曾离开  基尼族,到 靠近 基低斯、撒拿音 的 橡树 旁支搭 帐棚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, '有人告诉 西西拉说:「亚比挪庵 的儿子 巴拉 已经上 他泊 山了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, '西西拉 就聚集 所有的 铁 车 九 百 辆 和 跟随他 的 全 军,从外邦人 的夏罗设出来,到了 基顺 河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, '底波拉 对 巴拉 说:「你起来, 今 日 就是 耶和华 将 西西拉 交 在你手的日子。耶和华 岂不 在你前头 行吗?」于 是巴拉 下 了他泊 山,跟随他 有一万 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, '耶和华 使 西西拉 和 他一切 车辆 全 军 溃乱,在巴拉 面前 被 刀杀败;西西拉 下 车 步行 逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, '巴拉 追 赶 车辆、 军队,直到 外邦人 的夏罗设。西西拉 的全 军 都倒 在刀 下,没有 留下 一人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, '只有西西拉 步行 逃跑,到了 基尼人 希百 之妻 雅亿 的帐棚,因为 夏琐 王 耶宾 与 基尼人 希百 家 和好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, '雅亿 出来 迎接 西西拉,对他 说:「请 我主 进 来,不要 惧怕」;西西拉就进了 她的帐棚。雅亿用被 将他遮盖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, '西西拉对 雅亿说:「 我渴了,求你 给我一点 水 喝。」雅亿就打开  皮袋,给他奶子 喝,仍旧把他遮盖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, '西西拉又对 雅亿说:「请你站 在帐棚 门口,若 有 人 来 问你 说:『有 人 在这里没有?』你就说:『没有。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, '西西拉 疲乏 沉睡。希百的 妻 雅亿 取了 帐棚 的橛子,手里 拿著 锤子,轻悄悄地 到 他旁边,将 橛子 从他鬓边 钉进去,钉入 地里。西西拉就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, ' 巴拉 追赶 西西拉的时候,雅亿 出来 迎接他 说:「来吧,我将 你 所 寻找 的人 给你看。」他就进 入帐棚,看见 西西拉 已经死了,倒在地上,橛子 还在他鬓中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, ' 这样, 神 使 迦南 王 耶宾被 以色列 人 制伏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, '从此以色列 人 的手 越发 有力,胜了 迦南 王 耶宾,直到 将 他 灭绝了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, '那 时,底波拉 和亚比挪庵 的儿子 巴拉 作歌,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, '因为以色列中 有军长 率领,百姓 也甘心牺牲自己,你们应当颂赞 耶和华! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, '君王啊,要听!王子啊,要侧耳而听!我 要向耶和华 歌唱;我 要歌颂 耶和华─以色列的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, '耶和华啊,你从西珥 出来,由以东 地 行走。那时地 震 天 漏,云 也 落 雨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, '山 见耶和华 的面 就震动,西奈山 见耶和华─以色列 神 的面 也是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, '在亚拿 之子 珊迦 的时候,又在雅亿 的日子,大道 无人行走, 都是绕道 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, '以色列中 的官长 停职, 直到 我底波拉 兴起,等我兴起 作以色列 的母。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, '以色列人选择 新 神,争战  的事就 临到城门。那时,以色列 四万 人中岂能 见 盾牌 枪矛呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, '我心 倾向以色列 的首领,他们在民中 甘心牺牲自己。你们应当颂赞 耶和华! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, '骑 白 驴的、坐 绣花毯子的、行 路的,你们都当传扬! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, '在远离弓箭 响声 打水之处, 人必述说 耶和华 公义的作为,就是他治理 以色列 公义的作为。那时 耶和华 的民 下 到城门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, '底波拉啊,兴起!兴起!你当兴起,兴起,唱歌。亚比挪庵 的儿子 巴拉啊,你当奋兴,掳掠 你的敌人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, '那时 有余 馀剩 的贵胄 和百姓 一同下来;耶和华 降临,为我 攻击勇士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, '有根本 在亚玛力人的地,从 以法莲下来的;便雅悯 在民中 跟随你。有掌权的 从玛吉 下来;有持 杖 检点民数 的从西布伦下来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, '以萨迦 的首领 与 底波拉同来;以萨迦怎样,巴拉 也怎样。众人都跟随 巴拉 冲下平原;在流便 的溪水 旁有心 中定大 志的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, '你为何 坐 在 羊圈内 听 群 中吹笛的声音呢?在流便 的溪水 旁有心 中设大 谋的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, '基列人 安居 在约旦河 外。但人 为何 等 在船上?亚设人 在海 口 静坐,在 港口 安居。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, '西布伦 人 是拚 命 敢死的;拿弗他利人 在 田野 的高处也是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, '君王 都来 争战 。那时 迦南 诸王 在 米吉多 水旁 的他纳 争战 ,却未 得掳掠 银钱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, '星宿 从 天上 争战 ,从其轨道 攻击 西西拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, '基顺 古 河 把敌人冲没;我的灵啊,应当努力 前行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, '那时 壮 马 驰 驱,踢跳,奔腾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, '耶和华 的使者 说:应当咒诅 米罗斯,大大 咒诅 其中的居民;因为 他们不 来 帮助 耶和华,不来帮助 耶和华 攻击勇士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, '愿 基尼人 希百 的妻 雅亿 比众妇人 多得福气,比住帐棚 的妇人 更蒙福祉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, '西西拉求 水,雅亿给 他奶子,用宝贵的 盘子 给他 奶油。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, '雅亿左手 拿著 帐棚的橛子,右手 拿著匠人 的锤子,击打 西西拉,打伤 他的头,把他的鬓角 打破 穿通。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, '西西拉在 她脚 前曲身 仆倒,在 她脚 前曲身 倒卧;在那里 曲身,就在那里 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, '西西拉 的母亲 从窗户 里往外 观看,从 窗櫺 中呼叫说:他的战 车 为何 耽延 不来呢?他的车 轮 为何 行得慢呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, '聪明的 宫女安慰她(原文是回答她),她 也 自言 自语地说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, '他们莫非 得 财 而分?每人 得了一两个 女子?西西拉 得了彩衣 为掳物,得绣花 的彩衣 为掠物。这彩衣 两面绣花,乃是披在被掳之人 颈项上的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, '耶和华啊,愿 你的仇敌 都 这样 灭亡!愿 爱你的人 如日头 出现,光辉烈烈!这样,国 中太平 四十 年。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, '以色列 人 又行 耶和华 眼中 看为恶的事,耶和华 就把他们交在 米甸人 手里 七 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, '米甸人 压制 以色列人;以色列 人 因为 米甸人,就 在山中 挖 穴、挖 洞、建造 营寨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, ' 以色列人 每逢 撒种之后,米甸人、亚玛力人,和东方 人 都上来 攻打他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, '对著他们 安营,毁坏 土 产,直 到 迦萨,没有 给以色列人 留下 食物,牛、羊、驴也没有留下; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, '因为 那些人 带著 牲畜 帐棚 来,像 蝗虫 那样多,人 和骆驼 无 数,都进入 国内,毁坏全地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, '以色列人 因 米甸人的缘故,极其 穷乏, 就呼求 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, ' 以色列 人 因 米甸人 的缘故,呼求 耶和华, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, '耶和华 就差遣 先知 到 以色列 人那里,对他们 说:「耶和华─以色列的 神 如此 说:『我 曾领你们 从埃及 上来,出了 为奴 之家, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, '救 你们 脱离埃及人 的手,并脱离一切 欺压你们之人 的手,把他们 从你们面前 赶出,将 他们的地 赐 给你们』; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, '又对你们 说:『我是 耶和华─你们的 神。你们 住在 亚摩利人 的 地,不可 敬畏他们的 神。你们竟不 听从 我的话。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, '耶和华 的使者 到了 俄弗拉,坐在 亚比以谢族人 约阿施的 橡树 下。约阿施的儿子 基甸 正在酒醡 那里打 麦子,为 要防备 米甸人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, '耶和华 的使者 向基甸 显现,对他 说:「大能 的勇士啊,耶和华 与你同在!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, '基甸 说:「 主啊,耶和华 若与我们同在,我们何致 遭遇 这 一切事呢?我们的列祖 不是 向我们 说『耶和华 领我们 从埃及上来』吗?他那样 奇妙的作为 在哪里呢?现在 他 却丢弃我们,将我们交 在米甸人 手里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, '耶和华 观看 基甸,说:「你靠著你这 能力 去 从米甸人 手里 拯救 以色列人,不是 我差遣你去的吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, '基甸说:「 主啊,我有何 能拯救 以色列人呢? 我家 在玛拿西 支派中是至贫穷的。我 在我父 家 是至微小的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, '耶和华 对他 说:「 我与你 同在,你就必击打 米甸人,如击打一 人一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, '基甸说:「我若 在你眼前 蒙 恩,求 你给 我 一个证据,使我知道与我 说话 的就是主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, '求 你不要 离开  这里,等 我归 回 将 礼物 带来 供 在你面前。」主说:「我必 等 你回来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, '基甸 去 预备了 一只山羊 羔,用一伊法 细面 麺 做了无酵饼,将肉 放 在筐内,把汤 盛 在壶中,带 到 橡树 下,献在使者面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, '神 的使者 吩咐基甸 说:「 将 肉 和 无酵饼 放 在 这 磐石上,把 汤 倒出来。」他就这样 行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, '耶和华 的使者 伸出 手内 的 杖,杖头 挨了 肉 和无酵饼,就有火 从 磐石 中出来,烧尽了 肉 和 无酵饼。耶和华 的使者 也就不见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, '基甸 见 他是 耶和华 的使者, 就说:「哀哉!主 耶和华啊,我不好了,因为 我觌 面 看见 耶和华 的使者。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, '耶和华 对他 说:「你 放心,不要 惧怕,你必不 致死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, '于 是基甸 在那里 为耶和华 筑了 一座坛,起名 叫「耶和华沙龙」(就是耶和华赐平安的意思)。(这坛在 亚比以谢族 的俄弗拉 直到 如 今。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, ' 当那 夜,耶和华 吩咐基甸 说:「你取 你父亲 的 牛来,就是(或译:和)那七 岁 的第二 只牛,并拆毁 你父亲 为巴力 所 筑的坛,砍下 坛 旁 的木偶, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, '在 这磐石(原文是保障)上 整整齐齐地 为耶和华─你的 神 筑 一座坛, 将 第二只 牛 献 为燔祭,用你所 砍下 的木偶 作柴。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, '基甸 就从他仆人 中挑了 十个 人,照著 耶和华 吩咐 他的 行了。 他因 怕 父 家 和 本城 的人,不敢在白昼 行这事,就在夜间 行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, '城 里的人 清早 起来,见 巴力 的坛 拆毁,坛旁的 木偶 砍下, 第二只 牛 献 在 新筑 的坛上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, '就彼此 说:「这 事 是谁 做的呢?」他们访 查之后,就说:「这是 约阿施 的儿子 基甸 做的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, '城 里的人 对 约阿施 说:「将 你儿子 交出来,好治死他;因为 他拆毁了 巴力 的坛, 砍下 坛旁的 木偶。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, '约阿施 回答站著 攻击他 的 众人 说:「你们 是为巴力 争论吗?你们 要 救 他吗?谁 为他 争论,趁 早 将谁治死!巴力若果 是 神, 有人拆毁 他的坛,让他为自己 争论吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, '所以当 日 人称 基甸为耶路‧巴力,意思说:「 他拆毁 巴力的坛,让巴力 与他 争论。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, '那时, 米甸人、亚玛力人,和东方 人 都 聚集 过河,在耶斯列 平原 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, '耶和华 的灵 降 在 基甸身上,他就吹 角;亚比以谢族 都聚集 跟随他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, '他打发 人 走遍 玛拿西地,玛拿西人 也 聚集 跟随他;又打发 人 去见亚设人、西布伦人、拿弗他利人,他们也都出来 与他们会合。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, '基甸 对 神 说:「你 若 果照著所 说的话,藉 借我手 拯救 以色列人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, ' 我 就把 一团 羊毛 放 在禾场上:若 单是 羊毛上 有 露水, 别的地方 都 是干的,我就知道 你必 照著所 说的话,藉 借我手 拯救 以色列人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, '次日 早晨基甸起来,见果然是 这样;将 羊毛 挤一挤,从 羊毛 中拧出 满 盆 的露 水来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, '基甸 又对 神 说:「求你不要 向我 发 怒,我再 说 这一次: 让我将羊毛 再试 一 次。但愿  羊毛 是 干的, 别的地方 都 有 露水。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, '这 夜 神 也如此 行:独 羊毛 上是 干的, 别的地方 都 有 露水。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, '耶路‧巴力 就是 基甸,他和一切 跟随的 人 早晨起来,在 哈律 泉旁安营。米甸 营 在 他们 北边 的平原,靠近摩利 冈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, '耶和华 对 基甸 说:「跟随你 的 人 过多,我不能将 米甸人 交 在他们手中,免得 以色列人 向我 夸大,说:『是我们自己的手 救 了我们。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, '现在 你要向 这些人 宣告 说:『凡 惧怕 胆怯的,可以离开  基列 山 回去。』」于 是有 二万二千 人 回去,只剩下 一万。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, '耶和华 对 基甸 说:「人 还是 过多;你要带他们 下 到 水旁,我好在那里 为你 试试他们。我指点 谁 说:『这人 可以同你 去』,他 就可以同你 去;我 指点谁 说:『这人 不可 同你 去』,他 就不可 同你去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, '基甸就带他们 下 到 水旁。耶和华 对 基甸 说:「凡 用舌头 舔 水,像 狗 舔 的,要使他 单 站在一处;凡 跪下 喝 水的,也要使他单站在一处。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, '于 是用手捧著 舔 水的 有 三 百 人,其余 馀 的 都 跪下 喝 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, '耶和华 对 基甸 说:「我要用这舔 水的三 百 人 拯救 你们,将 米甸人 交 在你手中;其余 馀的人 都 可以各 归各处 去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, '这三百人 就带著 食物 和 角;其余 馀 的以色列 人,基甸都 打发 他们各归各的帐棚,只留下 这三 百 人。米甸 营 在 他 下边的 平原里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, ' 当那 夜,耶和华 吩咐基甸 说:「起来,下 到米甸营里去,因 我已将他们交 在你手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, '倘若 你 怕 下去, 就带你的仆人 普拉 下 到 那营里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, '你必听见 他们所 说的,然后 你 就有胆量 下去 攻营。」于 是基甸 带著仆人 普拉 下 到 营旁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, '米甸人、亚玛力人,和一切 东方 人 都布散 在平原,如同蝗虫 那样多。他们的骆驼 无 数,多 如海 边 的 沙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, '基甸 到了,就听见 一人 将梦 告诉 同伴 说:「 我做了 一梦,梦见 一个大麦 饼 滚 入米甸 营中,到 了 帐幕,将帐幕撞 倒,帐幕 就翻 转 倾覆 复了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, '那同伴 说:「这 不是 别的,乃是 以色列 人 约阿施 的儿子 基甸 的刀; 神 已将 米甸 和 全 军 都交在 他的手中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, ' 基甸 听见 这 梦 和 梦的讲 解,就敬拜 神,回 到 以色列 营中,说:「起来吧! 耶和华 已将 米甸 的军队 交在 你们手中了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, '于 是基甸将 三 百 人 分 作三 队,把角 和空 瓶 交 在各人 手里(瓶 内 都藏著火把), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, '吩咐他们 说:「你们要看 我 行 事: 我 到 了营 的旁边 怎样 行,你们也要 怎样 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, '我 和一切 跟随我 的人 吹 角的时候,你们 也 要在营 的四 围 吹 角,喊叫说:『耶和华 和基甸的刀!』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, '基甸 和跟随他 的 一百 人,在三 更 之初 才 换 更的时候,来到 营 旁,就吹 角,打破 手中 的 瓶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, '三 队 的人就都吹 角,打破 瓶子,左 手 拿著 火把,右 手 拿著角,喊叫说:「耶和华 和基甸 的刀!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, '他们在营 的四围 各 站 各的地方;全 营 的人都乱窜。三百人呐喊,使他们逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, '三 百 人就吹 角,耶和华 使 全 营 的人 用 刀 互相击杀, 逃 到 西利拉的伯‧哈示他,直逃到 靠近 他巴的亚伯‧米何拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, '以色列 人 就从拿弗他利、 亚设,和 玛拿西 全 地聚集 来追 赶 米甸人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, '基甸 打发 人 走遍 以法莲 山地,说:「你们下来 攻击 米甸人,争先把守 约旦河 的 渡口,直到伯‧巴拉。」于 是以法莲 的众 人 聚集,把守 约旦河 的 渡口,直到伯‧巴拉, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, '捉住 了米甸人 的两 个首领:一名 俄立,一名 西伊伯;将 俄立 杀 在俄立 磐石上,将 西伊伯 杀 在西伊伯 酒醡那里;又追赶 米甸人,将俄立 和西伊伯 的首级 带 过 约旦河,到 基甸那里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, '以法莲 人 对基甸 说:「 你去与米甸人 争战 ,没有 招 我们 同去,为什么 这样 待 我们呢?」他们就与基甸 大大地 争吵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, '基甸对他们 说:「 我所行 的岂 能比你们所行的呢?以法莲 拾取剩下的 葡萄不 强 过亚比以谢 所摘的葡萄吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, '神 已将 米甸人 的两个首领 俄立 和 西伊伯 交 在你们手中;我所行 的岂 能 比你们所行的呢?」基甸说了 这 话,以法莲人的 怒气 就 消了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, '基甸 和跟随他 的 三 百 人 到 约旦河 过渡,虽然疲乏,还是追赶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, '基甸对疏割 人 说:「求 你们拿 饼 来给跟随我 的 人吃,因为 他们 疲乏了;我 们追 赶 米甸人 的两个王 西巴 和撒慕拿。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, '疏割 人的首领 回答说:「 西巴 和撒慕拿 已经 在你手里,你使 我们将饼 给 你的军兵吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, '基甸 说:「耶和华 将 西巴 和 撒慕拿 交 在我手 之后,我就用 野地 的荆条 和 枳棘 打伤 你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, '基甸从那里 上到 毘努伊勒,对那里的人 也是这样 说;毘努伊勒 人 也与疏割 人 回答 他 的话一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, '他 向毘努伊勒 人 说:「我平平安安 回来的时候,我必拆毁 这 楼。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, '那时西巴 和撒慕拿,并跟随他们 的军队 都在加各,约有一万五 千人,就是 东方 人 全 军 所剩下的;已经被杀 约有十二万 拿刀的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, '基甸 就由挪巴 和约比哈 东边,从住 帐棚 人的路 上去,杀败了 米甸人的军兵,因为他们 坦然无惧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, '西巴 和撒慕拿 逃跑;基甸追赶 他们,捉住 米甸 的二 王 西巴 和 撒慕拿,惊散 全 军。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, '约阿施 的儿子 基甸 由希列斯 坡 从 阵 上回来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, '捉住 疏割的一个 少年人,问他:「疏割的首领长老是谁?」他就将 首领 长老 七十 七 个人 的名字写出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, '基甸到了 疏割,对 那里的人 说:「你们从前讥诮 我 说:『 西巴 和撒慕拿 已经 在你手里,你使 我们将饼 给 跟随你的疲乏 人吗?』现在 西巴 和撒慕拿在这里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, '于 是捉住 那 城 内的长老,用 野地 的荆条 和 枳棘 责打(原文是指教) 疏割 人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, '又拆了 毘努伊勒 的楼,杀了 那 城 里的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, '基甸问 西巴 和 撒慕拿 说:「你们在他泊 山所 杀 的人 是什么样式?」回答说:「他们 好像你,各人 都有王子 的样式。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, '基甸说:「他们是 我同母 的弟兄,我指著永生 的耶和华起誓,你们从前若 存留他们 的性命,我如今就不 杀 你们了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, '于 是对他的长子 益帖 说:「你起来 杀 他们。」但益帖 因为 是 童子, 害怕,不 敢拔 刀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, '西巴 和撒慕拿 说:「你自己 起来 杀 我们吧!因为 人如何,力量也是如何。」基甸 就起来,杀了 西巴 和 撒慕拿,夺 获 他们骆驼 项上 戴的 月牙圈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, '以色列 人 对 基甸 说:「你既 救我们 脱离米甸人 的手,愿  你 和 你的儿 孙 管理 我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, '基甸 说:「我 不 管理 你们,我的儿子 也不 管理 你们,惟有耶和华 管理 你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, '基甸 又对他们 说:「我有一件事 求 你们:请你们各人 将所夺的 耳环 给 我。」(原来 仇敌是 以实玛利人,都是 戴 金 耳环的。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, '他们说:「我们情愿  给你」,就铺开  一件外衣,各人 将所夺的 耳环 丢在 其上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, ' 基甸所 要出来的 金 耳环 重 一千 七 百 舍客勒金子。此外 还有 米甸 王 所戴的 月环、耳坠,和所穿的紫色 衣服,并 骆驼 项上 的 金链子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, '基甸 以此 制造 了一个以弗得,设立 在本城 俄弗拉。后来 以色列人 拜那 以弗得行了邪淫;这就作了 基甸 和他全家 的网罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, '这样,米甸人被 以色列 人 制伏了,不 敢再 抬 头。基甸 还在的日子,国 中太平 四十 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, '约阿施 的儿子耶路‧巴力 回去,住 在自己家里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, '基甸 有 七十 个亲生 的儿子,因为 他 有 许多 的妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, '他的妾 住在示剑, 也 给他 生了 一个儿子。基甸与他 起名 叫 亚比米勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, '约阿施 的儿子 基甸,年纪老迈 而死,葬 在亚比以谢族 的俄弗拉,在他父亲 约阿施 的坟墓里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, ' 基甸 死后,以色列 人 又去 随从 诸巴力 行邪淫,以巴力‧比利土 为他们的神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, '以色列 人 不 记念 耶和华─他们的 神,就是拯救 他们 脱离四围 仇敌 之手的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, '也不 照著耶路‧巴力,就是基甸 向 他们 所 施 的恩惠 厚 待 他的家。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, '耶路‧巴力 的儿子 亚比米勒 到了 示剑 见 他的众母舅,对他们 和 他外 祖 全 家 的人 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, '「请你们问 示剑 的众 人 说,是耶路‧巴力 的众 子 七十 人 都管理 你们 好呢?还是 一 人 管理 你们好呢?你们又要记念 我是 你们的骨 肉。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, '他的众母舅 便将 这 一切 话 为他 说 给示剑 人听,示剑人的心 就归向 亚比米勒。 他们说:「他原是 我们的弟兄」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, '就从巴力‧比利土 的庙 中取了七十 舍客勒银子 给 亚比米勒;亚比米勒 用以 雇 了些匪 徒 跟随 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, '他往 俄弗拉 到他父亲的 家,将 他弟兄、耶路‧巴力 的众子 七十 人 都杀 在 一 块磐石上;只剩下耶路‧巴力 的小 儿子 约坦,因为 他躲藏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, '示剑 人 和 米罗 人都一同聚集,往 示剑 橡树 旁 的 柱子那里,立 亚比米勒 为王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, '有人将这事告诉 约坦,他就去 站 在基利心 山 顶上,向众人 大 声 喊叫 说:「示剑 人哪,你们要听 我的话, 神 也就听 你们的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, '有一时,树木 要膏 一树为王,管理他们,就去 对橄榄树 说:『请你作 我们的王。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, '橄榄树回答 说:『我岂肯止住 供奉神 和尊重 人 的 油,飘 飖 在 众树之上呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, '树木 对无花果树 说:『请你 来 作 我们的王。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, '无花果树回答 说:『我岂肯止住所结 甜 美 的果子,飘 飖 在 众树之上呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, '树木 对葡萄树 说:『请你 来 作 我们的王。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, '葡萄树回答 说:『我岂肯止住 使神 和人 喜乐 的 新酒,飘 飖 在 众树之上呢。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, '众 树 对 荆棘 说:『请你 来 作 我们的王。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, '荆棘回答 说:『你们 若 诚诚实实地 膏 我 为王,就要 投 在我的荫下;不然,愿 火 从 荆棘 里出来,烧灭 黎巴嫩 的香柏树。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, '「现在 你们立 亚比米勒 为王,若 按诚实 正直 善 待耶路‧巴力 和 他的全家,这就是 酬 他的 劳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, ' 从前我父 冒 死 为你们 争战 ,救了 你们 脱离米甸人 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, '你们 如今 起来 攻击 我的父 家,将 他众子 七十 人 杀 在 一 块磐石上,又立 他婢女 所生的儿子 亚比米勒 为 示剑 人的王;他 原是 你们的弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, '你们如 今 若 按诚实 正直 待耶路‧巴力 和 他的家,就可因亚比米勒 得欢乐,他 也 可因你们 得欢乐; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, '不然,愿 火 从亚比米勒 发出,烧灭 示剑 人 和 米罗 众人,又愿 火 从示剑 人 和米罗 人 中出来,烧灭 亚比米勒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, '约坦 因怕他 弟兄 亚比米勒,就逃 跑,来 到比珥,住 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, '亚比米勒 管理 以色列人 三 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, '神 使 恶 魔 降在 亚比米勒 和示剑 人 中间,示剑 人 就以诡诈 待亚比米勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, '这是要叫耶路‧巴力 七十 个儿子 所受 的残害 归 与 他们的哥哥 亚比米勒,又叫那 流 他们 血 的罪归与 帮助 他 杀 弟兄 的示剑 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, '示剑 人 在 山 顶 上设 埋伏,等候亚比米勒。凡 从他们 那里 经过的人,他们就抢夺。有人将这事告诉 亚比米勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, '以别 的儿子 迦勒 和他的弟兄 来 到 示剑,示剑 人 都信靠 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, '示剑人出 城到田间去,摘下 葡萄,踹酒,设摆 筵宴,进 他们神 的庙 中吃 喝,咒诅 亚比米勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, '以别 的儿子 迦勒 说:「亚比米勒 是谁?示剑 是谁?使 我们服事他呢?他不是耶路‧巴力 的儿子吗?他的帮手 不是 西布勒吗?你们可以服事 示剑 的父亲 哈抹 的后裔。我们 为何 服事亚比米勒呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, '惟愿  这 民 归 我的手下,我就除掉 亚比米勒。」迦勒又对亚比米勒 说:「增添 你的军兵 出来吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, '邑 宰 西布勒 听见 以别 的儿子 迦勒 的话,就发 怒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, '悄悄地 打发 人 去见 亚比米勒,说:「 以别 的儿子 迦勒 和他的弟兄 到 了示剑, 煽惑 城 中的民攻击你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, '现在 你 和跟随你 的 人 今夜 起来,在田间 埋伏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, ' 到早晨 太阳 一出,你就起来 闯 城。 迦勒 和跟随他 的 人 出来 攻击你的时候,你 便向他们 见 机 而做。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, '于 是,亚比米勒 和跟随他 的 众 人 夜间 起来,分作四 队,埋伏 等候 示剑人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, '以别 的儿子 迦勒 出去,站在 城 门 口。亚比米勒 和跟随他 的 人 从 埋伏之处 起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, '迦勒 看见 那些人,就对 西布勒 说:「看哪,有人 从山 顶 上下来了。」西布勒 说:「你 看见 山 的影子,以为是人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, '迦勒 又 说:「看哪,有人 从 高 处 下来,又有一 队 从米恶尼尼 橡树 的路上 而来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, '西布勒 对他 说:「你 曾说,亚比米勒 是谁,叫 我们服事他? 你所夸的口 在哪里呢?这不是 你所 藐视的 民吗?你现在 出去, 与他们 交战 吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, '于 是迦勒 率领 示剑 人 出去,与亚比米勒 交战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, '亚比米勒 追赶迦勒;迦勒在他面前 逃跑,有许多 受伤 仆倒的,直到 城 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, '亚比米勒 住 在亚鲁玛。西布勒 赶出 迦勒 和 他弟兄,不准他们住 在示剑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, ' 次日,民 出到 田间,有人告诉 亚比米勒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, '他就把 他的人 分作 三 队,埋伏 在田间,看见 示剑人 从城里 出来,就起来 击杀 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, '亚比米勒 和跟随他 的 一队 向前闯去,站在 城 门 口;那两 队 直闯 到 田间,击杀 了众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, '亚比米勒 整 天 攻打 城,将 城 夺取,杀了 其 中的 居民,将 城 拆毁,撒上 了盐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, '示剑 楼的 人 听见了,就躲 入巴力‧比利土 庙 的卫所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, '有人告诉 亚比米勒说:「 示剑 楼 的人 都 聚在一处。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, '亚比米勒 和跟随他 的 人 就都 上 撒们 山。亚比米勒 手 拿 斧子,砍下 一根树 枝,扛 在 肩上,对 跟随他 的 人 说:「你们看 我所 行的,也当赶紧 照样 行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, '众 人 就 各 砍 一枝,跟 随 亚比米勒,把树枝堆 在 卫所的四围,放 火 烧了 卫所,以致 示剑 楼 的人 都 死了,男 女 约有一千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, '亚比米勒 到 提备斯,向提备斯 安营,就攻取了那城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, '城 中 有 一座坚固的 楼;城 里的众 人,无论男 女,都 逃进 楼去,关 上门,上了 楼 顶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, '亚比米勒 到了 楼 前攻打,挨 近 楼 门,要用火 焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, '有一个 妇人 把一块 上磨石 抛 在 亚比米勒的 头上,打破了 他的脑骨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, '他就急忙 喊叫 拿 他兵器 的少年人,对他 说:「拔出 你的刀来,杀了我吧!免得 人议论我 说,他为一个妇人 所杀。」于 是少年人 把他刺透,他就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, '以色列 人 见 亚比米勒 死了,便各 回 自己的地方去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, '这样, 神 报应 亚比米勒 向他父亲 所 行 的恶,就是杀了 弟兄 七十个人的恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, ' 示剑 人 的一切 恶, 神 也都报应 在他们头上;耶路‧巴力 的儿子 约坦 的咒诅 归 到他们身上了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, '亚比米勒 以后,有以萨迦 人 朵多 的孙子、普瓦 的儿子 陀拉 兴起,拯救 以色列人。他 住 在以法莲 山地 的沙密。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, '陀拉作 以色列 的士师 二十 三 年,就死了,葬 在沙密。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, '在他以后 有基列人 睚珥 兴起,作 以色列 的士师 二十 二 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, '他有 三十 个儿子,骑 著 三十 匹驴驹。他们有 三十 座城邑,叫作哈倭特‧睚珥,直到 如 今,都是 在基列 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, '睚珥 死了,就葬 在加们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, '以色列 人 又 行 耶和华 眼中 看为恶的事,去事奉 诸巴力 和 亚斯她录,并 亚兰 的神、 西顿 的神、 摩押 的神、 亚扪 人 的神、 非利士人 的神,离弃 耶和华,不 事奉他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, '耶和华 的怒气 向以色列人 发作,就把他们交 在非利士人 和亚扪 人 的手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, '从那 年起,他们扰害 欺压 约旦河 那边、住亚摩利人 之 基列 地 的 以色列 人,共有十 八 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, '亚扪 人 又渡过 约旦河 去攻打 犹大 和便雅悯,并以法莲 族。以色列人 就甚 觉窘迫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, '以色列 人 哀求 耶和华 说:「我们得罪了 你;因为 离弃了我们 神,去事奉 诸巴力。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, '耶和华 对 以色列 人 说:「我岂没有 救过你们脱离埃及人、 亚摩利人、 亚扪 人,和 非利士人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, '西顿人、亚玛力人、马云人 也都欺压 你们;你们哀求 我,我也拯救 你们 脱离他们的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, '你们 竟离弃 我,事奉 别 神!所以 我不 再 救 你们了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, '你们去 哀求 所 选择 的神;你们遭遇急难 的时候,让他 救 你们吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, '以色列 人 对 耶和华 说:「我们犯罪了,任凭你 随 意 待 我们吧!只 求 你今 日 拯救我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, '以色列人就除掉 他们中间 的外邦 神,事奉 耶和华。耶和华因以色列人 受的苦难,就心 中担忧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, '当时亚扪 人 聚集,安营 在基列。以色列 人 也聚集,安营 在米斯巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, '基列 的民 和众首领 彼此 商议说:「谁 能先 去攻打 亚扪 人,谁必作 基列 一切 居民 的领袖。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, '基列人 耶弗他 是 个大能 的勇士,是 妓 女 的儿子。耶弗他是 基列 所生 的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, '基列 的妻 也生了 几个儿子:他妻 所生的儿子 长大了,就赶逐 耶弗他,说:「你不可 在我们父 家 承受产业,因为 你是 妓 女 的儿子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, '耶弗他 就逃避 他的弟兄,去住 在陀伯 地,有些匪 徒 到 他 那里聚集,与他 一同出入。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, ' 过了些日子,亚扪 人 攻打 以色列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, ' 亚扪 人 攻打 以色列 的时候,基列 的长老 到陀伯 地 去,要叫 耶弗他 回来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, '对耶弗他 说:「请你来 作 我们 的元帅,我们好与亚扪 人 争战 。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, '耶弗他 回答基列 的长老 说:「从前你们 不是 恨 我、赶逐我 出离父 家吗?现在 你们 遭遇 急难 为何 到我 这里来呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, '基列 的长老 回答 耶弗他 说:「 现在 我们到你 这里来,是要你同我们 去,与亚扪 人 争战 ;你可以作 基列 一切 居民 的领袖。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, '耶弗他 对 基列 的长老 说:「 你们 叫我 回去,与亚扪 人 争战 ,耶和华 把他 交 给我,我 可以作 你们 的领袖吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, '基列 的长老 回答 耶弗他 说:「有耶和华 在你我中间 作 见证,我们必定 照你的话 行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, '于 是耶弗他 同 基列 的长老 回去,百姓 就立 耶弗他 作领袖、作元帅。耶弗他 在米斯巴 将 自己的一切 话 陈明 在耶和华 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, '耶弗他 打发 使者 去 见亚扪 人 的王,说:「你与我有什么相干,竟 来 到 我国中 攻打 我呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, '亚扪 人 的王 回答 耶弗他 的使者 说:「因为 以色列人 从埃及 上来 的时候占据 我的地,从亚嫩河 到 雅博河,直到 约旦河。现在 你要好好地 将这地 归还吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, '耶弗他 又 打发 使者 去见 亚扪 人 的王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, '对他 说:「耶弗他 如此 说,以色列人 并没有 占据 摩押 地 和 亚扪 人 的地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, '以色列人 从埃及 上来 乃是 经过 旷野 到 红 海,来到 加低斯, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, ' 就打发 使者 去见 以东 王,说:『求 你容我从你的地 经过。』以东 王 却不 应允。又 照样打发 使者去见 摩押 王,他也不 允准。以色列人 就住 在加低斯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, '他们又经过 旷野,绕著 以东 和 摩押 地,从摩押 地 的东边 过来,在亚嫩河 边 安营,并没有 入 摩押 的境内,因为 亚嫩河 是摩押 的边界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, '以色列人 打发 使者 去见 亚摩利 王 西宏,就是希实本 的王, 对他 说:『求 你容我们从你的地 经过,往 我们自己的地方去。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, '西宏 却不 信服 以色列人,不容他们经过 他的境界, 乃招聚 他的众 民 在雅杂 安营,与 以色列人 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, '耶和华─以色列的 神 将 西宏 和 他的众 民 都交 在以色列人 手中,以色列人 就击杀他们,得了 亚摩利人 的全 地: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, ' 从亚嫩河 到 雅博河,从 旷野 直到 约旦河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, ' 耶和华─以色列的 神 在他百姓 以色列 面前 赶出 亚摩利人,你 竟要得他们的地吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, '你的神 基抹 所 赐 你的地你不是 得 为业吗?耶和华─我们的 神 在我们面前 所 赶出 的人,我们就得 他的地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, '难道 你 比摩押 王 西拨 的儿子 巴勒 还 强吗?他曾 与 以色列人 争竞,或是 与他们 争战 吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, '以色列人 住 希实本 和属希实本的乡村,亚罗珥 和属亚罗珥的乡村,并 沿 亚嫩河 的一切 城邑,已经有三 百 年了;在这 三百年之内,你们为什么 没有 取回这些地方呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, '原来我 没有 得罪 你,你却 攻打 我,恶 待 我。愿 审判 人的耶和华 今日 在 以色列 人 和亚扪 人 中间 判断是非。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, '但亚扪 人 的王 不 肯听 耶弗他 打发人 说的 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, ' 耶和华 的灵 降在 耶弗他身上,他就经过 基列 和 玛拿西,来到 基列 的米斯巴,又从米斯巴 来到 亚扪 人那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, '耶弗他 就向耶和华 许 愿 ,说:「你若 将 亚扪 人 交 在我手中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, '我从亚扪 人 那里平平安安 回来的时候, 无论什么人,先从我家 门 出来 迎接我,就必 归你,我也必将他献上 为燔祭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, '于 是耶弗他 往 亚扪 人 那里去,与他们 争战 ;耶和华 将他们交 在他手中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, '他就大 大 杀败他们,从亚罗珥 到 米匿,直到 亚备勒‧基拉明,攻取了二十 座城。这样亚扪 人 就被 以色列 人 制伏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, '耶弗他 回 米斯巴 到了 自己的家,不料,他女儿 拿著鼓 跳舞 出来 迎接他,是 他独 生的,此外 无 儿 无 女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, ' 耶弗他 看见 她,就撕裂 衣服,说:「哀哉!我的女儿啊,你 使我 甚是愁苦,叫 我作难了;因为我 已经向 耶和华 开  口许愿 ,不 能 挽回。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, '他女儿回答 说:「父啊,你既向 耶和华 开  口,就当照你口 中所 说 的向我 行,因 耶和华 已经在仇敌 亚扪 人 身上为你 报 仇」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, '又对 父亲 说:「有一件 事 求你允准:容 我 去 两个 月,与同伴 在 山上,好哀哭 我 终为处女。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, '耶弗他说:「你去吧!」就容 她 去两个 月。她 便和同伴 去了,在 山上 为 她终为处女 哀哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, ' 两 月 已满,她回 到 父亲那里,父亲就照 所 许 的愿  向她 行了。女儿 终身没有 亲近 男子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, '此后以色列中 有 个规矩,每 年 以色列 的女子 去 为基列人 耶弗他 的女儿 哀哭 四 天。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, '以法莲 人 聚集,到了 北方,对耶弗他 说:「你去 与亚扪 人 争战 ,为什么 没有 招 我们 同 去呢?我们必用火 烧 你 和你的房屋。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, '耶弗他 对他们 说:「我 和我的民 与亚扪 人 大大 争战 ;我招 你们来,你们竟没有 来救 我 脱离他们的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, '我见 你们不 来救我,我就拚 命 前去 攻击 亚扪 人,耶和华 将他们交 在我手中。你们今 日 为什么 上 我这里 来攻打 我呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, '于 是耶弗他 招聚 基列 人,与 以法莲人 争战 。基列 人 击杀 以法莲人,是因 他们说:「你们 基列人 在 以法莲、玛拿西 中间,不过是以法莲 逃亡的人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, '基列人 把守 约旦河 的渡口,不容以法莲人过去。 以法莲 逃走的人 若 说:「容我过去。」基列 人 就问他 说:「你是 以法莲人不是?」他若说:「不是」, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, '就对他 说:「 你说『示播列』。」以法莲人因为咬 不 真 字音,便说「西播列」。基列人就将他 拿住,杀 在 约旦河 的渡口。那 时 以法莲人 被杀 的有四万 二 千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, '耶弗他作 以色列 的士师 六 年。基列人 耶弗他 死了,葬 在基列 的一座城里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, '耶弗他以后,有伯利恒人 以比赞作 以色列的 士师。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, '他 有 三十 个儿子,三十个 女儿;女儿都嫁 出去了。他给众子 从 外乡 娶了 三十个 媳妇。他作 以色列 的士师 七 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, '以比赞 死了,葬 在伯利恒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, '以比赞之后,有西布伦人 以伦,作 以色列 的士师 十 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, '西布伦人 以伦 死了,葬 在西布伦 地 的亚雅仑 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, '以伦之后,有比拉顿人 希列 的儿子 押顿作 以色列 的士师。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, '他 有 四十 个儿子,三十 个孙子,骑 著 七十 匹驴驹。押顿作 以色列 的士师 八 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, '比拉顿人 希列 的儿子 押顿 死了,葬 在以法莲 地 的比拉顿,在亚玛力人 的山地。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, '以色列 人 又 行 耶和华 眼中 看为恶的事,耶和华 将他们 交 在非利士人 手中 四十 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, '那时,有 一个 琐拉 人,是属但 族的,名 叫玛挪亚。他的妻 不怀孕,不 生育。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, '耶和华 的使者 向 那妇人 显现,对她 说:「 向来你 不怀孕,不 生育,如今 你必怀孕 生 一个儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, '所以 你当谨慎, 清酒 浓酒 都不可 喝,一切 不洁 之物也不可 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, ' 你必 怀孕 生 一个儿子,不可 用剃头刀 剃 他的头,因为 这孩子 一出 胎就归 神 作 拿细耳人。他 必起首 拯救 以色列人 脱离非利士人 的手。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, '妇人 就回去 对丈夫 说:「有一个神 人 到我面前 来,他的相貌如 神 使者 的相貌,甚是 可畏。我没有 问 他 从 哪里来,他也没有 将 他的名 告诉 我, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, '却对我 说:『 你要怀孕 生 一个儿子,所以 清酒 浓酒 都不可 喝,一切 不洁之物 也不可 吃;因为 这孩子 从出 胎 一直到 死,必归 神 作 拿细耳人。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, '玛挪亚 就祈求 耶和华 说:「主 啊,求 你再 差遣 那 神 人 到我们 这里来,好指教我们 怎样 待 这将要生 的孩子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, '神 应允 玛挪亚 的话;妇人 正坐 在田间的时候, 神 的使者 又 到 她 那里,她丈夫 玛挪亚 却没 有同她在一处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, '妇人 急忙 跑 去告诉 丈夫 说:「 那日 到我面前 来 的 人,又向我 显现。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, '玛挪亚 起来 跟随 他的妻 来 到 那人面前,对他 说:「与 这妇人 说话 的 就是你吗?」他说:「是我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, '玛挪亚 说:「愿  你的话 应验!我们当怎样 待 这孩子,他后来当 怎样呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, '耶和华 的使者 对 玛挪亚 说:「我告诉 妇人 的 一切事,她都当谨慎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, '葡萄树 所 结 的都 不可 吃,清酒 浓酒 都不可 喝,一切 不洁之物 也不可 吃。凡 我所 吩咐的,她都当遵守。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, '玛挪亚 对 耶和华 的使者 说:「求 你容我们款留 你,好为你 预备 一只山羊羔。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, '耶和华 的使者 对 玛挪亚 说:「你虽然 款留我,我却不 吃 你的食物,你若 预备 燔祭 就当献 与耶和华。」原来 玛挪亚 不 知道 他是 耶和华 的使者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, '玛挪亚 对 耶和华 的使者 说:「请将 你的名告诉我, 到你话 应验的时候,我们好尊敬你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, '耶和华 的使者 对他 说:「你何必 问 我的名,我名是 奇妙的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, '玛挪亚 将 一只山羊羔 和 素祭 在 磐石 上献 与耶和华,使者行 奇妙的事;玛挪亚 和他的妻 观看, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, ' 见火焰 从 坛 上往上 升,耶和华 的使者 在坛 上的火焰中 也升上去了。玛挪亚 和他的妻 看见,就俯伏 于  地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, '耶和华 的使者 不 再 向 玛挪亚 和 他的妻 显现,玛挪亚 才 知道 他是 耶和华 的使者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, '玛挪亚 对 他的妻 说:「我们必要 死,因为 看见了 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, '他的妻 却对他 说:「耶和华 若 要 杀我们,必不 从我们手里 收纳 燔祭 和素祭,并不 将 这 一切 事指示我们,今日 也不 将这些话 告诉我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, '后来妇人 生了 一个儿子,给他起 名 叫 参孙。孩子 长大,耶和华 赐福与他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, '在玛哈尼‧但,就是 琐拉 和以实陶 中间,耶和华 的灵 才 感动他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, '参孙 下 到亭拿,在那里 看见 一个女子,是非利士人 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, '参孙上来 禀告 他父 母 说:「我在亭拿 看见 一个女子,是非利士人 的女儿,愿  你们给我 娶来 为妻。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, '他父 母 说:「在你弟兄 的女儿中,或在 本国的民中,岂没有 一个女子,何致 你 去 在未受割礼的 非利士人中 娶 妻呢?」参孙 对 他父亲 说:「愿 你给我 娶 那女子,因 我 喜悦她。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, '他的父 母 却不 知道 这事是 出于 耶和华,因为 他找 机会 攻击非利士人。那 时,非利士人 辖制 以色列人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, '参孙 跟他父 母 下 亭拿 去,到了 亭拿 的葡萄园,见 有一只少壮 狮子 向他 吼叫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, '耶和华 的灵 大大 感动参孙,他虽然手 无 器械,却将狮子撕裂,如同撕裂 山羊羔一样。他行 这事 并没有 告诉 父 母。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, '参孙下 去 与女子 说话,就喜悦她; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, '过了些日子,再 下去要娶那女子,转向 道旁要看 死 狮,见 有一群 蜂子 和蜜 在死 狮之内, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, '就用 手 取蜜, 且吃 且走;到了 父 母那里,给 他父母,他们也吃了;只是没有 告诉 这蜜 是从死 狮 之内取来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, '他父亲 下去 见 女子。参孙 在那里 设摆 筵宴,因为 向来 少年人 都有这个规矩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, ' 众人看见 参孙,就请了 三十 个人陪伴 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, '参孙 对他们 说:「 我给你们 出 一个谜语,你们在七 日 筵宴之内,若 能 猜出 意思 告诉我,我就给 你们 三十 件里衣,三十 套 衣裳; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, '你们若 不 能 猜出意思告诉 我,你们 就给 我 三十 件里衣,三十 套 衣裳。」他们说:「请将谜语 说给 我们听。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, '参孙对他们 说:吃的 从吃者 出来;甜的 从强者 出来。他们三 日 不 能 猜出 谜语的意思。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, ' 到第七 天,他们对参孙 的妻 说:「你诓哄 你丈夫,探出 谜语 的意思告诉 我们,免得 我们用火 烧 你 和 你父 家。你们请了 我们来,是要夺我们所有的 吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, '参孙的 妻 在 丈夫面前啼哭 说:「你是 恨我,不是 爱我,你给我本国 的人 出 谜语,却没有 将意思告诉 我。」参孙回答 说:「 连我父 母 我都没有 告诉,岂可告诉 你呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, '七 日 筵宴 之 内,她在丈夫面前 啼哭,到 第七 天 逼著他,他才将谜语 的意思告诉 他妻,他妻就告诉 本国 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, '到第七 天,日头 未落 以前,那城 里的人 对参孙 说:有什么 比蜜 还甜呢?有什么 比狮子 还强呢?参孙对他们 说:你们若非 用我的母牛犊 耕地,就猜不 出 我谜语的意思来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, '耶和华 的灵 大大感动 参孙,他就下 到亚实基伦,击杀了 三十 个人,夺了 他们的衣裳,将 衣裳 给了 猜出 谜语的人。参孙发 怒,就上 父 家去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, '参孙的 妻 便归了 参孙的陪伴,就是 作过他 朋友的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, '过了 些日子,到割 麦子 的时候,参孙 带著一只山羊羔 去看 他的妻,说:「我要进 内室 见 我的妻。」他岳父 不 容 他进去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, ' 说:「我估 定 你是极其 恨她,因此我将她给了 你的陪伴。她的妹子 不是 比她 还美丽吗? 你 可以 娶来代替她吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, '参孙 说:「这回 我 加 害 于  非利士人 不算有罪。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, '于 是参孙 去 捉了 三 百 只狐狸(或译:野狗), 将狐狸尾巴 一对 一对 地捆上,将 火把 捆 在 两 条尾巴 中间, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, '点著 火把,就放狐狸进入 非利士人 站著的禾稼,将堆集的禾捆 和 未割的禾稼,并 橄榄园 尽都烧了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, '非利士人 说:「这事 是谁 做的呢?」有人说:「是亭拿人 的女婿 参孙,因为 他岳父 将 他的妻 给了 他的陪伴。」于 是非利士人 上去,用火 烧了 妇人 和 她的父亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, '参孙 对非利士人 说:「你们既然 这样 行,我必 向你们 报仇 才 肯罢休。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, '参孙就大大 击杀 他们,连腿 带 腰 都砍断了。他便下去,住在 以坦 磐 的穴内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, '非利士人 上去 安营 在犹大,布散 在利希。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, '犹大 人 说:「你们为何 上来 攻击我们呢?」他们说:「我们上来 是要捆绑 参孙;他向我们 怎样 行,我们也要向他 怎样行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, '于 是有三 千 犹大 人 下 到 以坦 磐 的穴内,对参孙 说:「 非利士人 辖制 我们,你不 知道吗?你向我们 行 的是什么 事呢?」他回答说:「他们向我 怎样 行,我也要向他们 怎样 行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, '犹大人对他 说:「我们下来 是要捆绑你,将你交 在非利士 人手中。」参孙 说:「你们要向我 起誓,应承 你们自己 不害死 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, '他们 说:「 我们断 不 杀你,只要 将你捆 绑 交 在非利士人手中。」于 是用两 条新 绳 捆绑参孙,将他从 以坦磐 带上去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, '参孙 到 了 利希,非利士人 都迎著 喧嚷。耶和华 的灵 大大感动 参孙,他 臂 上的 绳 就像 火 烧 的麻一样,他的绑绳 都从 他手 上脱落下来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, '他见 一块未干的 驴 腮骨,就伸 手 拾起来,用以 击杀 一千 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, '参孙 说:我用驴 腮骨 杀人成堆,用驴 腮骨 杀了 一千 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, ' 说 完这话,就把那腮骨 从手里 抛出去了。那 地 便叫拉末‧利希。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, '参孙甚 觉口渴,就求告 耶和华 说:「你 既藉 借仆人 的手 施行 这么 大 的拯救,岂可 任我渴 死、落在 未受割礼 的人手中呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, '神 就使 利希 的 洼处 裂开 ,有水 从其中 涌出来。参孙喝了,精神 复 原;因此 那泉名 叫隐‧哈歌利,那泉 直到 今 日 还在利希。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, '当非利士人 辖制以色列人的时候,参孙作 以色列 的士师 二十 年。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, '参孙 到了 迦萨,在那里 看见 一个妓 女,就与她 亲近。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, '有人告诉迦萨人 说:「参孙 到 这里来了!」他们就把他团团围住,终 夜 在城 门 悄悄 埋伏,说:「等到 天 亮 我们便杀他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, '参孙 睡 到 半 夜,起来, 将城 门 的门扇、门框、门闩,一齐 拆下来,扛 在 肩上,扛 到 希伯仑  前 的 山 顶 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, ' 后来,参孙在梭烈 谷 喜爱 一个妇人,名 叫大利拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, '非利士人 的首领 上去 见那妇人,对她 说:「求你诓哄 参孙,探探 他因何 有这么大 的力气,我们用何法 能胜 他,捆绑 克 剋制他。我们 就每人 给 你 一千 一百 舍客勒银子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, '大利拉 对 参孙 说:「求你告诉 我,你因何 有这么大 的力气,当用何法 捆绑 克 剋制你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, '参孙回答 说:「人若 用七 条未 干 的 青 绳子 捆绑我,我就 软弱 像别 人一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, '于 是非利士人 的首领 拿了 七 条未 干 的 青 绳子来,交给妇人,她就用绳子 捆绑参孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, '有人预先埋 伏 在妇人 的内室里。妇人 说:「参孙哪,非利士人 拿你来了!」参孙就挣断 绳子,如 挣断 经 火 的麻 线 缐一般。这样,他力气 的根由人还是不 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, '大利拉 对 参孙 说:「 你欺哄 我,向我 说 谎言。现在 求 你告诉 我 当用何法 捆绑你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, '参孙回答 说:「人若 用 没有 使 过 的 新 绳 捆 绑我,我就 软弱 像别 人一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, '大利拉 就 用 新 绳 捆绑他,对他 说:「参孙哪,非利士人 拿你来了!」有人预先埋 伏 在内室里。参孙将 臂 上的绳挣断了,如挣断一条线 缐一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, '大利拉 对 参孙 说:「你到 如今 还是欺哄 我,向我 说 谎言。求你告诉 我,当用何法 捆绑你。」参孙回答 说:「你若 将 我头 上的七 条发绺,与 纬线 缐 同织就可以了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, '于 是大利拉将他的发绺与纬线 缐同织,用橛子 钉住,对他 说:「参孙哪,非利士人 拿你来了!」参孙从睡中 醒来,将 机 上的橛子 和 纬线 缐 一齐都拔出来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, '大利拉对参孙 说:「你既不 与我 同心,怎么 说 你爱我呢?你这 三 次 欺哄 我,没有 告诉 我,你因何 有这么大的 力气。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, ' 大利拉天天 用话 催 逼 他,甚至他心 里烦闷 要死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, '参孙就把 心 中所藏的都 告诉 了她,对她 说:「向来人没有 用剃头刀 剃 我的头,因为 我 自出母 胎就归 神 作拿细耳人;若 剃了我的头发,我的力气 就离开  我,我便 软弱 像 别人一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, '大利拉 见 他把 心 中所藏的都 告诉了 她,就打发 人到非利士人 的首领那里,对他们说:「 他已经把 心 中所藏的都告诉了 我,请你们再上来 一次。」于 是非利士人 的首领 手里 拿著 银子,上 到妇人那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, '大利拉使参孙枕著 她的膝 睡觉,叫了 一个人 来剃除 他头 上的七 条发绺。于 是大利拉 克 剋制他,他的力气 就离开  他了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, '大利拉说:「参孙哪,非利士人 拿你来了!」参孙从睡中 醒来,心里说:「我要像前 几次 出去 活动身体」;他 却不 知道 耶和华 已经离开  他了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, '非利士人 将他拿住,剜了 他的眼睛,带他 下到 迦萨,用铜炼 链 𫔀 拘索他;他就 在 监 里推磨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, '然而他的头 发 被剃 之后,又渐渐 长起来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, '非利士人 的首领 聚集,要给他们的神 大衮 献 大 祭,并且欢乐,因为他们说:「我们的神 将 我们的仇敌 参孙 交 在我们手中了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, '众人 看见 参孙,就赞美 他们的神 说:「我们的神 将 毁坏 我们地、 杀害 我们许多 人的 仇敌 交 在我们手中了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, '他们正 宴乐的时候,就说:「叫 参孙来,在我们 面前戏耍戏耍。」于 是将参孙 从 监 里提出来,他就在众人面前 戏耍。他们使他 站 在两柱 中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, '参孙 向 拉 他手 的童子 说:「求你让 我 摸著 托 房 的 柱子,我要靠一靠。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, '那时房 内充满 男 女,非利士人 的众 首领 也都在那里。房的平顶 上 约有三 千 男 女 观看 参孙 戏耍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, '参孙 求告 耶和华 说:「主 耶和华啊,求 你眷念我。 神啊,求你 赐我这 一次 的力量,使我在非利士人 身上报 那 剜我双 眼 的仇。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, '参孙 就抱住 托 房 的 那两 根 柱子:左手 抱 一根,右手 抱一根, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, ' 说:「我 情愿 与 非利士人 同死!」就尽力 屈身,房子 倒塌,压住 首领 和 房内 的 众 人。这样,参孙 死时 所 杀的 人比 活著 所杀的 还 多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, '参孙的弟兄 和他父 的全 家 都下去 取 他的尸首,抬上来 葬 在 琐拉 和以实陶 中间,在他父 玛挪亚 的坟墓里。参孙作 以色列 的士师 二十 年。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, '以法莲 山 地有 一个人 名 叫米迦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, '他对母亲 说:「你 那一千 一百 舍客勒银子 被人拿去,你 因此咒诅,并且 告诉了 我。看哪,这银子 在我这里,是我 拿去了。」他母亲 说:「我儿啊,愿 耶和华 赐福与你!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, '米迦就把 这一千 一百 舍客勒银子 还 他母亲。他母亲 说:「我 分出 这 银子 来为你 献 给耶和华,好雕刻 一个像,铸成一个像。现在 我还是交给 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, '米迦将 银子 还 他母亲,他母亲 将 二百 舍客勒银子 交 给银匠,雕刻 一个像,铸成一个像,安置 在米迦 的屋内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, '这 米迦 有了 神 堂,又制造 以弗得 和家中的神像,分派 他一个 儿子 作 祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, '那 时 以色列中 没有 王,各人 任意 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, '犹大 的伯利恒 有 一个少年人,是 犹大 族 的利未人,他 在那里 寄居。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, '这人 离开  犹大 的伯利恒 城,要找 一个可住的 地方。行 路的时候,到了 以法莲 山地,走到 米迦 的家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, '米迦 问他 说:「你从哪里 来?」他回答 说:「从犹大 的伯利恒 来。我是 利未人,要找 一个可住的 地方。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, '米迦 说:「你可以住 在我这里,我 以你为 父、为祭司。我 每年 给 你 十 舍客勒银子,一套 衣服 和度日的食物。」利未人 就进了他的家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, '利未人 情愿  与 那人 同住;那人 看 这少年人 如自己 的儿子一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, '米迦 分派 这少年 的利未人 作 祭司,他就 住在米迦 的家里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, '米迦 说:「现在 我知道 耶和华 必赐福 与我,因 我 有 一个利未人 作祭司。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, '那 时,以色列中 没有 王。 但 支派 的人仍是寻 地 居住;因为 到 那 日子,他们 还没有 在以色列 支派 中 得 地为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, '但 人 从琐拉 和以实陶 打发 本族中 的五 个 勇 士,去仔细窥 探 那 地,吩咐他们 说:「你们去 窥探 那 地。」他们来到 以法莲 山地,进了 米迦 的住宅,就在那里 住宿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, '他们 临近 米迦 的住宅, 听出 那 少年 利未人 的口音来,就进去 问他 说:「谁 领你 到这里来?你 在这里 做 什么?你 在这里 得什么?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, '他回答 说:「米迦 待 我 如此 如此,请 我作 祭司。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, '他们对他 说:「请 你求问 神,使我们 知道 所 行 的道路 通达不通达。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, '祭司 对他们 说:「你们可以平平安安地 去,你们所 行 的道路 是在 耶和华 面前的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, '五 人 就走了,来到 拉亿,见 那里 的 民 安 居无虑,如同西顿人 安 居 一样。在那地 没有人 掌 权 扰乱 他们;他们 离西顿人 也远,与 别人 没有 来往。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, '五人回 到 琐拉 和以实陶,见他们的弟兄;弟兄 问他们 说:「你们 有什么话?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, '他们回答说:「起来,我们上去 攻击他们吧!我们已经 窥探 那 地,见 那地甚 好。你们 为何静坐不动呢?要急速前 往 得 那 地为业,不可 迟延。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, '你们到了那里,必看见 安居 无虑的民,地也 宽阔。 神 已 将那地 交 在你们手中;那地 百 物俱全, 一无 所缺。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, '于 是但 族中的 六 百 人,各带 兵 器,从琐拉 和以实陶 前往, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, '上到 犹大的基列‧耶琳,在基列‧耶琳 后边 安营。因此 那地方 名叫玛哈尼‧但,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, '他们从那里 往以法莲 山地 去,来 到 米迦 的住宅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, '从前窥 探 拉亿 地 的五 个人 对 他们的弟兄 说:「 这 宅子里 有 以弗得 和家中的神像,并雕刻的像 与铸成的像,你们知道吗?现在 你们要想一想 当怎样 行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, '五人就进 入 米迦 的住宅,到了 那少年 利未人 的房 内问 他 好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, '那六 百 但 人 各 带 兵 器,站在 门 口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, '窥 探 地 的五 个人 走 进 去,将 雕刻的像、 以弗得、 家中的神像,并 铸成的像,都拿了去。祭司 和带 兵 器 的六 百 人,一同站在 门 口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, '那 五个人进入 米迦 的住宅,拿出 雕刻的像、以弗得、 家中的神像,并 铸成的像,祭司 就问他们 说:「你们 做 什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, '他们回答 说:「不要作声,用手 摀 口,跟我们 去吧!我们必以 你为 父、为祭司。你作 一 家 的祭司 好呢?还是 作 以色列 一族 一支派 的祭司好呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, '祭司 心 里喜悦,便拿 著 以弗得 和 家中的神像,并 雕刻的像,进入 他们 中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, '他们就转身 离开 那里,妻子、 儿女、 牲畜、 财物 都在 前头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, ' 离米迦 的住宅 已远, 米迦 的 近 邻 都聚集来,追赶 但 人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, '呼叫 但 人。但人回 头 问米迦 说:「 你 聚集 这许多人来做什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, '米迦说:「你们将 我所 做 的神像 和 祭司 都带了 去,我 还有 所剩的吗?怎么 还问我 说『做什么』呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, '但 人 对米迦 说:「你不要 使我们 听见 你的声音,恐怕 有性 暴 的人 攻击 你,以致你 和你的全家 尽都丧 命。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, '但 人 还是走 他们的路。米迦 见 他们 的势力 比自己强盛,就转身 回 家去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, '但人 将 米迦 所 做 的神像和 他的 祭司 都带 到 拉亿,见 安居 无虑 的民,就用 刀 杀了 那民,又放火 烧了 那城, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, '并无人 搭救;因为 离西顿 远,他们 又与 别人 没有 来往。城 在平原,那平原靠近伯‧利合。但人又在那里修 城 居住, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, '照著他们始祖 以色列 之 子 但 的名字,给那城 起名 叫 但;原 先 那城 名 叫拉亿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, '但 人 就为自己 设立 那 雕刻的像。摩西 的孙子、革舜 的儿子 约拿单, 和他的子孙 作 但 支派 的祭司,直到 那地 遭掳掠 的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, '神 的殿 在 示罗 多少 日子,但人为自己 设立 米迦 所 雕刻 的像也在但多少日子。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, '当 以色列中 没有 王 的时候,有 住 以法莲 山地 那边 的一个 利未人,娶了 一个犹大 伯利恒的 女子 为妾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, '妾 行淫 离开  丈夫,回 犹大 的伯利恒,到了 父 家, 在那里 住了四 个月。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, '她丈夫 起来,带著 一个仆人、两匹 驴 去 见她,用好话 劝 她 回来。女子 就引 丈夫进入父 家。她父 见了那人,便欢欢喜喜 地迎接。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, '那人的岳父,就是女子 的父亲,将那人 留下 住了 三 天。于 是二人一同 吃 喝、住宿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, '到 第四 天,利未人清 早 起来 要走,女子 的父亲 对 女婿 说:「请你吃点 饭,加添 心力,然后 可以行路。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, '于 是二 人坐下 一同 吃 喝。女子 的父亲 对 那人 说:「 请 你再住一夜,畅快 你的心。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, '那人 起来 要走,他岳父 强留 他,他又 住了一宿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, '到第五 天,他清早 起来 要走,女子 的父亲 说:「请你吃点饭,加添 心力,等 到 日头偏 西再走。」于 是二 人一同吃饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, '那人 同他的妾 和仆人 起来 要走,他岳父,就是女子 的父亲,对他 说:「看哪, 日头偏 西了,请 你再住一夜; 天 快晚了,可以在这里 住宿,畅快 你的心。明天 早早起 行 回家 去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, '那人 不 愿  再住一夜,就 备上 那两 匹驴,带著 妾 起身 走了,来 到 耶布斯 的对面(耶布斯就是 耶路撒冷。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, ' 临近 耶布斯的时候,日头 快要落了,仆人 对 主人 说:「 我们不如 进 这 耶布斯人 的城 里住宿。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, '主人 回答 说:「我们不可 进 不是 以色列 人 住的 外邦 城,不如过 到 基比亚去」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, '又对仆人 说:「我们可以 到 一个 地方,或住 在基比亚,或 住在拉玛。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, '他们就往前 走。将到 便雅悯 的 基比亚,日头 已经落了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, '他们 进入 基比亚 要在那里 住宿, 就坐 在城 里的街上,因为无 人 接 他们 进家 住宿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, '晚上, 有一个老 年人 从 田 间做工 回来。他 原是以法莲 山地 的人,住 在基比亚;那地方 的人 却是便雅悯 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, '老年 人 举 目 看见 客 人 坐在城 里的街上,就问他说:「你从哪里 来?要往哪里 去?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, '他回答 说:「我们 从犹大 的伯利恒 来,要往 以法莲 山地 那边去。我 原是那里的人,到 过 犹大 的伯利恒,现在我 往 耶和华 的殿 去,在这里无 人 接 我 进他的家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, '其实我有 粮 草 可以喂 𫗭驴,我 与我的妾,并 我 的仆人,有 饼 有 酒,并不 缺少 什么。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, '老年 人 说:「愿 你 平安! 你所需用 的我都 给你,只是 不可 在街上 过夜。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, '于 是领他们 到家里,喂 𫗭上 驴,他们就洗 脚 吃 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, '他们 心里 正欢畅的时候, 城 中的 匪徒 围 住 房子,连连叩 门, 对 房 主 老 人 说:「你把 那 进 你家 的人 带出来,我们要与他交合。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, '那 房 主 出来 对他们 说:「 弟兄们哪,不要 这样作恶;这 人 既然 进了 我的家,你们就不要 行 这 丑事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, ' 我有个女儿,还是处女,并有这人的妾, 我将她们 领出来 任凭 你们 玷辱 她们,只是向这 人 不可 行 这样 的丑 事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, '那些人 却 不 听从 他的话。那人 就把 他的妾 拉 出去 交给他们,他们便与她 交合,终 夜 凌辱 她,直到 天 色快亮 才放她去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, '天 快亮的时候,妇人 回到 她主 人 住宿 的 房 门前,就仆倒在地,直到 天亮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, '早晨,她的主人 起来 开 了 房 门,出去 要行 路,不料 那妇人 仆倒 在房 门前,两手 搭在 门槛上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, '就对妇人 说:「起来,我们走吧!」妇人却不 回答。那人 便将她驮 在 驴上,起身 回 本处去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, '到 了 家里,用 刀 将 妾 的尸身 切成 十 二 块,使人拿著传送 以色列 的四 境。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, ' 凡 看见 的人都说:「从 以色列 人 出 埃及 地,直到 今 日,这样的事 没有 行过,也没有 见过。现在应当思想,大家商 议当怎样办理。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, '于 是以色列 从但 到 别是巴,以及住基列 地 的众人 都出来,如同一 人,聚集 在 米斯巴 耶和华面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, '以色列 民 的首领,就是各 支派的军长,都站在 神 百姓 的会中;拿 刀 的步 兵 共有四 十万。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, ' 以色列 人 上到 米斯巴,便雅悯 人 都听见了。以色列 人 说:「请你将这 件恶事的情由 对我们说明。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, '那利未 人,就是被害 之妇人 的丈夫,回答 说:「我 和我的妾 到了 便雅悯 的 基比亚 住宿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, '基比亚 人 夜间 起来,围了 我住的 房子,想 要杀 我,又将 我的妾 强奸 致死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, '我就把 我妾 的尸身切成块子,使人拿著传送 以色列 得为业 的全 地,因为 基比亚人在以色列中 行了 凶淫 丑恶的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, ' 你们以色列 人 都 当 筹划 㓰 商议。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, '众 民 都起来 如同一 人,说:「我们连一人 都不 回 自己帐棚、 自己 房屋 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, ' 我们向基比亚人 必这样 行,照所掣的签 去攻击他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, '我们要在以色列 各 支派中,一百 人挑取 十 人,一千 人挑取百人,一万 人挑取千人,为民 运 粮,等大众到了 便雅悯 的基比亚,就照 基比亚人在以色列中 所 行 的丑事 征伐他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, '于 是以色列 众 人 彼此连合 如同一 人,聚集 攻击 那城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, '以色列 众支派 打发 人去,问便雅悯 支派 的各 家说:「你们中间 怎么 做了 这样 的 恶事呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, '现在 你们要将 基比亚 的 那些匪徒 交出来,我们好治死他们,从以色列中 除掉 这恶。」便雅悯 人 却不 肯 听从 他们弟兄 以色列 人 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, '便雅悯 人 从 他们的各城 里出来,聚集 到了基比亚,要与 以色列 人 打仗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, '那 时 便雅悯 人 从各城里 点出 拿 刀的,共有二万 六 千;另外还有 基比亚 人 点出 七 百 精 兵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, '在众 军 之中 有拣选的七 百 精 兵,都是 左手 便利的,能用机弦甩 石打人, 毫发 不 差。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, '便雅悯人 之外,点出 以色列 人 拿 刀的,共有四 十万,都是 战  士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, '以色列 人 就起来,到 伯特利 去求问 神 说:「我们中间 谁 当首先 上去 与 便雅悯 人 争战 呢?」耶和华 说:「犹大 当先上去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, '以色列 人 早晨 起来,对著 基比亚 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, '以色列 人 出来,要与 便雅悯人 打仗, 就在 基比亚 前摆 阵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, '便雅悯 人 就从 基比亚 出来,当 日 杀死 以色列人 二万二 千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, '以色列 人 彼此奋勇,仍在头一 日 摆 阵 的 地方 又 摆阵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, '未摆阵之先,以色列 人 上去,在耶和华 面前 哭号,直到 晚上,求问 耶和华 说:「我们再 去 与 我们弟兄 便雅悯 人 打仗可以不可以?」耶和华 说:「可以上去 攻击他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, '第二 日,以色列 人 就上前 攻击 便雅悯 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, '便雅悯人 也在这 日 从 基比亚 出来,与以色列 人 接战 ,又 杀死 他们一万八 千,都是 拿 刀的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, '以色列 众 人 就上 到 伯特利,坐在 耶和华 面前 哭号,当 日 禁食 直到 晚上;又在耶和华 面前 献 燔祭 和平安祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, '那 时, 神 的约 柜 在那里; 亚伦 的孙子、以利亚撒 的儿子 非尼哈 侍立 在约柜前。以色列 人 问 耶和华 说:「我们当再 出去 与 我们弟兄 便雅悯 人 打仗呢?还是 罢兵呢?」耶和华 说:「你们当上去,因为 明日 我必将他们交 在你们手中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, '以色列人 在 基比亚 的四围 设下 伏兵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, '第三 日,以色列 人 又上去 攻击 便雅悯 人,在 基比亚 前摆阵,与前两次 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, '便雅悯 人 也出来 迎 敌,就被引诱 离 城;在田间 两条路上, 一 通 伯特利,一 通基比亚,像 前两次,动手 杀死 以色列 人 约有三十 个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, '便雅悯 人 说:「他们 仍旧 败 在我们面前。」但以色列 人 说:「我们不如逃跑,引诱他们 离开  城 到 路上来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, '以色列 众 人 都起来,在巴力‧他玛 摆阵,以色列 的伏兵 从马利‧迦巴 埋伏的地方 冲上前去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, '有 以色列人中 的一万 精 兵,来到 基比亚 前接战 ,势派 甚是凶猛;便雅悯人 却不 知道 灾祸 临近了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, '耶和华 使 以色列人 杀败 便雅悯人。那 日,以色列 人 杀死 便雅悯人 二万 五 千 一百,都是 拿 刀的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, '于 是便雅悯 人 知道 自己败了。先是以色列 人;因为 靠 著 在 基比亚 前所 设 的伏兵,就在便雅悯人面前 诈败。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, '伏兵 急忙 闯 进 基比亚, 用 刀 杀死 全 城的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, '以色列 人 预先同 伏兵 约定在 城 内放 火,以烟气 上腾 为 号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, '以色列 人 临退 阵的时候,便雅悯人 动手 杀死 以色列 人, 约有三十 个,就 说:「他们 仍 像前 次 被我们 杀败了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, '当 烟气 如柱 从 城 中 上腾的时候,便雅悯人 回头 观看,见 全 城 的烟气冲 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, '以色列 人 又转身回来,便雅悯 人 就甚惊惶,因为 看见 灾祸 临 到自己了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, '他们在以色列 人 面前 转身 往 旷野逃跑; 以色列人在后面追杀。那 从各城里出来的,也都夹攻 杀灭 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, '以色列人围绕 便雅悯人,追赶他们,在他们歇脚之处、 对著 日 出之地 的基比亚 践踏他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, '便雅悯人 死了 的有一万八 千, 都是 勇 士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, '其余 馀的人转身 向旷野 逃跑,往 临门 磐去。以色列人在道路上 杀了他们 五 千 人,如拾取遗穗一样,追 到 基顿 又杀了 他们 二千 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, '那 日 便雅悯 死了的 共 有 二万 五 千 人, 都是 拿 刀 的勇 士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, '只剩下六 百 人,转身 向旷野 逃跑,到了 临门 磐,就在那里 住了 四 个月。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, '以色列 人 又转 到 便雅悯地,将各城 的人 和 牲畜,并 一切 所遇见的,都用 刀 杀尽,又 放 火 烧了一切 城邑。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, '以色列 人 在米斯巴 曾起誓 说:「我们都 不 将女儿 给 便雅悯人 为妻。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, '以色列人 来到 伯特利,坐在 神 面前 直到 晚上,放 声 痛哭, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, '说:「耶和华─以色列的 神啊,为何 以色列中 有 这样 缺了 一 支派的事呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, ' 次日清早,百姓 起来,在那里 筑了 一座坛,献 燔祭 和平安祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, '以色列 人 彼此问说:「以色列 各 支派中,谁 没有 同会众 上 到 耶和华面前来呢?」 先是以色列人起过大 誓 说, 凡 不 上 米斯巴 到 耶和华面前来的,必 将他治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, '以色列 人 为 他们的弟兄 便雅悯 后悔,说:「如今 以色列中 绝了 一个 支派了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, '我们 既在耶和华 面前起誓说,必不 将我们的女儿 给 便雅悯人 为妻,现在我们当怎样 办理、使他们 剩下 的人有妻呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, '又彼此问说:「以色列 支派中 谁 没有 上 米斯巴 到 耶和华面前来呢?」 他们就查出基列‧雅比 没有 一人 进 营 到 会众那里; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, '因为百姓 被数的时候, 没有 一个 基列‧雅比 人 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, '会众 就打发 一万二 千 大勇士,吩咐 他们 说:「你们去 用 刀 将 基列‧雅比 人 连妇女 带孩子 都击杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, '所 当行 的就是这 样:要将一切 男子 和 已嫁 的女子 尽行杀戮。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, '他们在基列‧雅比 人中,遇见了 四 百个 未 嫁的 处女,就带 到 迦南 地 的 示罗 营里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, '全 会众 打发 人到 临门 磐 的 便雅悯 人那里,向他们 说 和睦 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, '当 时 便雅悯人 回来了,以色列人就把所 存活 基列‧雅比 的女子 给 他们 为妻,还是 不 够。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, '百姓 为便雅悯人 后悔,因为 耶和华 使 以色列人 缺了一个支派(原文是使以色列中有了破口)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, '会 中的长老 说:「便雅悯中 的女子 既然 除灭了,我们当怎样 办理、使那余 馀剩 的人有妻呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, '又说:「便雅悯 逃脱的人 当有地业,免得 以色列中 涂抹了 一个支派。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, '只是我们 不 能 将自己的女儿 给 他们 为妻;因为 以色列 人 曾起誓 说,有将女儿给 便雅悯人 为妻的,必受咒诅。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, '他们又说:「 在利波拿 以南,伯特利 以北, 在示剑 大路 以东 的 示罗,年 年 有耶和华 的节期」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, '就吩咐 便雅悯 人 说:「你们去,在葡萄园中 埋伏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, '若 看见 示罗 的女子 出来 跳 舞,就从 葡萄园 出来,在示罗 的女子中 各 抢 一个为妻,回便雅悯 地 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, ' 他们的父亲 或是 弟兄 若 来 与我们 争竞,我们就 说:『求你们看我们的情面,施恩 给这些人,因 我们在争战  的时候 没有 给 他们 留下 女子为妻。这 也不是 你们 将女子给 他们的;若是你们给的,就算有罪。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, '于 是便雅悯 人 照样 而行,按著他们的数目 从 跳舞的女子中 抢去 为 妻,就回 自己的地业 去,又重修 城邑 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, '当 时 以色列 人 离 开 那里,各 归本支派、本宗族、 本地业 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, '那 时,以色列中 没有 王,各人 任意 而行。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, '当 士师 秉政 的时候,国中 遭遇 饥荒。在犹大的 伯利恒,有一个人 带著妻子 和两个 儿子 往摩押 地 去 寄居。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, '这人 名 叫以利米勒,他的妻 名 叫拿俄米;他两个 儿子,一个名 叫玛伦,一个名叫基连,都是犹大 伯利恒 的以法他人。他们到了 摩押 地,就住在 那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, '后来拿俄米 的丈夫 以利米勒 死了,剩下妇人 和她两个 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, '这两个儿子 娶了 摩押女子 为妻,一个 名 叫俄珥巴,一个 名 叫路得,在那里 住了 约有十 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, '玛伦 和基连 二人 也 死了,剩下 拿俄米,没有丈夫,也没有 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, '她 就与两个儿妇 起身,要从摩押 地 归回;因为 她在摩押 地 听见 耶和华 眷顾 自己的百姓,赐 粮食 与他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, '于 是她和 两个 儿妇 起行 离开  所住的 地方, 要回 犹大 地去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, '拿俄米 对两个 儿妇 说:「你们各人 回 娘 家 去吧。愿 耶和华 恩 待 你们,像 你们恩待 已死的人 与我一样! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, '愿 耶和华 使 你们 各 在新夫 家中 得 平安!」于 是拿俄米与她们 亲嘴。她们就放 声 而哭, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, ' 说:「不然,我们必与你 一同回 你本国去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, '拿俄米 说:「我女儿们哪,回去吧!为何 要跟我 去呢?我 还能生 子 作 你们 的丈夫吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, '我女儿们哪,回 去吧! 我年纪老迈,不能再有 丈夫;即或 说,我 还有 指望, 今夜 有 丈夫 可以生 子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, '你们岂能 等著 他们长大呢?你们岂能 等著他们 不嫁 别人呢?我女儿们哪,不要这样。 我 为你们 的缘故甚是 愁苦,因为 耶和华 伸手 攻击 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, '两个儿妇又 放 声 而哭,俄珥巴 与婆婆 亲嘴而别,只是路得 舍不得拿俄米。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, '拿俄米说:「看哪,你嫂子 已经回 她本国 和 她所拜的神那里去了,你也跟著 你嫂子 回去吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, '路得 说:「不要 催 我 回去 不跟随你。 你往 哪里 去,我也往那里去;你在哪里 住宿,我也在那里住宿;你的国 就是我的国,你的 神就是我的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, '你在哪里 死,我也在那里死,也葬 在那里。除非 死 能使你 我 相离!不然,愿  耶和华 重重地 降罚 与我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, '拿俄米见路得 定意 要跟随自己 去,就不再 劝 她了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, '于 是二人 同行,来 到 伯利恒。 她们到了 伯利恒,合 城 的人就都惊讶。妇女们说:「这是 拿俄米吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, '拿俄米对他们 说:「不要 叫 我 拿俄米(就是甜的意思),要叫 我 玛拉(就是苦的意思),因为 全能者 使我 受了大 苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, '我 满满地 出去,耶和华 使我空空地 回来。耶和华 降祸 与我;全能者 使我 受苦。既是这样,你们为何 还叫 我 拿俄米呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, '拿俄米 和她 儿妇 摩押女子 路得,从摩押 地 回来 到 伯利恒,正是动手 割 大麦的时候。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, '拿俄米 的丈夫 以利米勒 的亲族中, 有一个人 名 叫波阿斯,是个大 财主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, '摩押女子 路得 对 拿俄米 说:「容 我往田间 去,我蒙谁的 恩,就在谁 的身后 拾取 麦穗。」拿俄米说:「女儿啊,你只管去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, '路得就去了,来到 田间,在收割的人 身后 拾取麦穗。她恰巧到了 以利米勒 本族的人 波阿斯 那块 田里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, ' 波阿斯 正从伯利恒 来,对收割的人 说:「愿 耶和华 与你们同在!」他们回答说:「愿 耶和华 赐福与你!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, '波阿斯 问监管 收割的 仆人 说:「那是 谁家的 女子?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, '监管 收割的 仆人 回答 说:「是 那摩押 女子,跟随 拿俄米 从摩押 地 回来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, '她说:『请 你容我跟著 收割的人 拾取 打捆 剩下的麦穗。』她从 早晨 直到 如今,除了 在屋子里 坐 一会儿, 常在这里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, '波阿斯 对 路得 说:「女儿啊, 听我说,不要 往 别人 田里 拾取麦穗,也 不要 离开  这里,要 常与 我使女们 在一处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, '我的仆人在那 块田 收割,你 就跟著他们 去。我 已经吩咐 仆人 不可 欺负你;你若渴了,就可以到 器皿 那里喝 仆人 打来 的水。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, '路得就俯伏 在地 叩拜,对他 说:「我 既是外邦人,怎么 蒙 你 的恩,这样顾恤我呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, '波阿斯 回答 说:「自从你丈夫 死 后,凡 你向 婆婆 所 行的,并你离开  父 母 和本 地,到 素 不 认识 的民中,这些事人全都 告诉 我了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, '愿 耶和华 照你所行的 赏赐你。 你来 投靠 耶和华─以色列 神 的翅膀 下,愿 你满 得 他的赏赐。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, '路得说:「我主啊,愿 在你眼前 蒙 恩。我 虽然 不 及 你的一个 使女,你还 用慈爱的话 安慰我的 心。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, '到了吃饭 的时候,波阿斯 对路得 说:「你到 这里 来吃 饼,将饼 蘸 在醋里。」路得就在收割的人 旁边 坐下;他们把烘了的穗子 递 给她。她吃 饱了,还有余 馀剩的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, '她起来 又拾取麦穗,波阿斯 吩咐 仆人 说:「她就是 在捆 中 拾取麦穗,也可以容她,不可 羞辱她; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, '并 要 从 捆里 抽出些来,留 在地下任她拾取,不可 叱吓 她。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, '这样,路得在田间 拾取麦穗,直到 晚上,将 所 拾取的 打了,约有 一伊法 大麦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, '她就把 所 拾取 的带 进 城 去给 婆婆 看,又把 她吃饱了 所 剩的 给了 婆婆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, '婆婆 问她 说:「你今日 在哪里 拾取麦穗,在哪里 做工呢?愿 那顾恤你 的得 福。」路得就告诉 婆婆 说:「我今日 在一个名 叫波阿斯 的人 那里 做工。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, '拿俄米 对儿妇 说:「愿 那人 蒙耶和华 赐福,因为 他不 断 地恩待 活人 死人。」拿俄米又 说:「那是 我们 本族 的人,是一个至近的亲属。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, '摩押女子 路得 说:「 他对我 说:『你要紧 随 我的 仆人拾取麦穗,直 等 他们收完了 我的 庄稼。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, '拿俄米 对 儿妇 路得 说:「女儿啊,你跟著 他的使女 出去,不 叫人遇见 你 在别人 田间,这 才为好。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, '于 是路得与波阿斯 的使女 常在一处 拾取麦穗,直到 收完了 大麦 和小麦。路得仍与 婆婆 同住。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, '路得的婆婆 拿俄米 对她 说:「女儿啊,我不 当为你 找 个安身之处, 使你 享福吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, ' 你与 波阿斯的使女 常在一处, 波阿斯 不是 我们的亲族吗? 他 今夜 在 场上 簸 大麦; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, '你要沐浴 抹膏,换上 衣服,下到 场上,却不要 使那人 认出你来。你等 他吃 喝 完了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, '到 他睡的时候,你看 准 他睡 的 地方,就进去 掀开  他脚上的被,躺卧 在那里,他 必告诉 你 所 当做的事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, '路得 说:「凡 你所 吩咐的,我必遵行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, '路得就下到 场上,照 她婆婆 所 吩咐 她的而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, '波阿斯 吃 喝完了,心里 欢畅,就去 睡 在麦堆 旁边。路得便悄悄地 来 掀开  他脚上的被,躺卧在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, '到了 夜 半,那人 忽然惊醒,翻过身来,不料 有女子 躺在 他的脚下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, '他就说:「你 是谁?」回答说:「我 是你的婢女 路得。求你用你的衣襟 遮盖 我,因为 你 是我一个至近的亲属。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, '波阿斯说:「女儿啊,愿 你 蒙耶和华 赐福。你末后的 恩 比 先前 更大;因为少年人 无论 贫 富,你都没有 跟 从。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, '女儿啊,现在 不要 惧怕,凡 你所 说的,我必照著行; 我本城 的人 都 知道 你 是个贤德 的女子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, ' 我 实在 是你一个至近的亲属,只是 还有 一个人 比我更 近。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, '你今夜 在这里住宿, 明早 他若 肯为你尽亲属的本分,就由他吧!倘若 不 肯,我指著永生的 耶和华起誓,我 必为你尽了本分,你只管躺 到 天亮。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, '路得便在他脚下 躺 到 天快亮,人 彼此 不能 辨认 的时候就起来了。波阿斯说:「不可 使人知道 有女子 到 场上来」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, '又对路得说:「 打开  你 所 披的外衣。」她打开 了,波阿斯就撮了 六 簸箕大麦,帮她 扛 在肩上,她便进 城去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, '路得回 到 婆婆那里,婆婆说:「女儿啊,怎么样了?」路得就将 那人 向她 所 行 的述说了一遍, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, '又说:「那人给了 我 六 簸箕大麦, 对我说:『你不可 空手 回去 见 你的婆婆。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, '婆婆说:「女儿啊,你只管安坐等候, 看 这事 怎样 成就,因为 那人 今日不 办成 这事 必不 休息。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, '波阿斯 到了 城门,坐在 那里,恰巧 波阿斯 所 说 的那至近的亲属 经过。波阿斯说:「某人哪,你来 坐在 这里。」他就来 坐下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, '波阿斯又从本城 的长老中 拣选了 十 人,对他们说:「请你们坐在 这里。」他们就都坐下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, '波阿斯对那至近的亲属 说:「从摩押 地 回来的 拿俄米,现在要卖 我们族兄 以利米勒 的那块 地; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, '我 想 当赎那块地的是你,其次 是我, 以外 再没有别人了。你可以在这里的人 面前 和我本国 的长老 面前 说明,你若 肯赎 就赎,若 不 肯赎 就告诉 我。」那人回答说:「我 肯赎。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, '波阿斯 说:「你从拿俄米 手中 买  这地 的时候,也当娶(原文是买 ;十节同)死人 的妻 摩押女子 路得,使死人 在 产业 上存留 他的名。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, '那人 说:「这样我 就不 能 赎了,恐怕 于  我的产业 有碍。你 可以赎 我所 当赎的, 我不 能 赎了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, ' 从前,在以色列中 要定夺 什么 事,或 赎回,或 交易,这人 就脱 鞋 给 那人。以色列人 都以此 为证据。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, '那人 对波阿斯 说:「你自己 买 吧!」于 是将鞋 脱下来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, '波阿斯 对长老 和众 民 说:「你们 今日 作见证, 凡 属以利米勒 和 基连、玛伦的,我都从拿俄米 手中 置买 了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, '又 娶了 玛伦 的妻 摩押女子 路得 为妻,好在 死人 的产业 上存留 他的名,免得 他 的名 在 本族 本乡 灭没。你们 今日 可以作见证。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, '在城门 坐著的 众 民 和长老 都说:「我们作见证。愿 耶和华 使 进 你家 的这 女子,像建立 以色列 家 的 拉结、利亚 二人一样。又愿 你在以法他 得 亨通,在伯利恒 得 名声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, '愿 耶和华 从 这 少年女子 赐 你 后裔,使 你的家 像她玛 从犹大 所 生 法勒斯 的家一般。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, '于 是,波阿斯 娶了 路得 为 妻,与她 同房。耶和华 使 她 怀孕 生了 一个儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, '妇人们 对 拿俄米 说:「耶和华 是应当称颂的! 因为今日 没有撇下你,使你 无 至近的亲属。愿 这孩子在以色列中 得 名声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, '他必 提起 你 的精神,奉养 你的老,因为 是爱慕你 的那 儿妇 所生的。有这儿妇 比有七个 儿子 还好!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, '拿俄米 就把 孩子 抱 在怀中,作 他的 养母。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, '邻舍 的妇人说:「拿俄米 得 孩子了!」就给孩子 起 名 叫 俄备得。这俄备得是 耶西 的父,耶西是大卫 的父。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, '法勒斯 的后代 记在下面:法勒斯 生 希斯仑 ; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, '希斯仑  生 兰;兰 生 亚米拿达; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, '亚米拿达 生 拿顺;拿顺 生 撒门; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, '撒门 生 波阿斯;波阿斯 生 俄备得; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, '俄备得 生 耶西;耶西 生 大卫。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, '以法莲 山地的拉玛.琐非 有 一个 以法莲 人,名 叫以利加拿,是苏弗 的玄孙,托 讬户 的曾孙,以利户 的孙子,耶罗罕 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, '他有 两个 妻:一 名 哈拿,一 名 毘尼拿。毘尼拿 有 儿女,哈拿 没有 儿女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, '这 人 每年 从本城 上 到示罗,敬拜 祭祀 万军 之耶和华;在那里 有以利 的两个 儿子 何弗尼、非尼哈 当耶和华的 祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, '以利加拿 每逢 献祭 的日子,将祭肉 分给 他的妻 毘尼拿 和 毘尼拿所生的儿 女; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, '给 哈拿 的却是双 分,因为 他爱 哈拿。无奈耶和华 不使 哈拿生育。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, '毘尼拿见 耶和华 不使 哈拿生育,就作她的对头,大大激动她,要使 她生气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, '每年 上 到耶和华 殿 的时候,以利加拿都以双分给哈拿;毘尼拿仍是 激动她,以致她哭泣 不 吃饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, '她丈夫 以利加拿 对她 说:「哈拿啊,你为何 哭泣, 不 吃饭, 心 里愁闷呢? 有我 不 比十个 儿子 还好吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, '他们在示罗 吃 喝 完了,哈拿 就站起来。祭司 以利 在 耶和华 殿 的门框旁边,坐 在 自己的位上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, '哈拿 心里 愁苦,就痛痛 哭泣,祈祷 耶和华, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, '许 愿  说:「万军 之耶和华啊,你若 垂 顾 婢女 的苦情,眷念 不 忘 婢女,赐 我 一个儿子,我必使他 终 身 归与耶和华,不 用剃头刀 剃 他的头。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, ' 哈拿在耶和华 面前 不住地 祈祷,以利 定睛看 她的嘴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, '(原来哈拿 心 中 默祷,只 动 嘴唇,不 出 声音,因此以利 以为 她 喝醉了。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, '以利 对她 说:「你要醉 到 几时呢?你 不应该喝 酒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, '哈拿 回答 说:「主啊,不是这样。我 是心里 愁苦 的妇人,清酒 浓酒 都没有 喝,但在耶和华 面前 倾 心吐意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, '不要 将 婢女 看 作 不正经的 女子。我因 被人激动,愁苦 太多,所以祈求 到 如今。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, '以利 说:「你可以平平安安地 回去。愿 以色列的 神 允准 你向他 所 求 的!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, '哈拿说:「愿 婢女 在你眼前 蒙 恩。」于 是妇人 走 去 吃饭,面上 再 不 带愁容了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, '次日清早,他们起来,在耶和华 面前 敬拜,就回 拉玛。到 了 家里,以利加拿 和 妻 哈拿 同房,耶和华 顾念哈拿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, '哈拿 就怀孕。 日期 满足,生了 一个儿子,给他起 名 叫撒母耳,说:「这是 我从耶和华 那里求来的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, ' 以利加拿 和他全 家 都上示罗去,要向耶和华 献 年 祭,并 还所许的愿 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, '哈拿 却没有 上去, 对丈夫 说:「等 孩子 断了奶,我便带他 上去朝见 耶和华,使他 永远 住 在那里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, '她丈夫 以利加拿 说:「就随你 的意 行吧!可以等 儿子 断了奶。但愿  耶和华 应验 他的话。」于 是妇人 在家里 乳养 儿子,直到 断了奶; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, '既 断了奶,就把孩子带 上 示罗,到了 耶和华 的殿;又带了三 只公牛,一 伊法 细面 麺,一皮袋 酒。(那时,孩子 还小。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, '宰了 一只公牛,就领 孩子 到 以利面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, '妇人说:「主 啊,我敢在你 面前 起誓,从前在你 这里 站著 祈求 耶和华 的那妇人,就是我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, '我祈求 为要 得这 孩子;耶和华 已将我 所 求 的 赐 给我了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, '所以,我 将这孩子归 与耶和华,使他 终 身 归 与耶和华。」于 是在那里 敬拜 耶和华。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, '哈拿 祷告 说:我的心 因耶和华 快乐;我的角 因耶和华 高举。我的口 向 仇敌 张开 ;我因 耶和华的救恩 欢欣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, '只有 耶和华 为圣;除 他以外 没有可比的,也没有 磐石像我们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, '人不要 夸口 说 骄傲的话,也不要 出 狂妄的言语;因 耶和华 是大有智识的 神,人的行为 被他 衡量。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, '勇士 的弓 都已折断;跌倒的人 以力量 束腰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, '素来饱足的,反作用人 求食;饥饿的,再不饥饿。 不生育的,生了 七个儿子;多 有儿女的,反倒衰微。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, '耶和华 使人死,也使人活,使人下 阴间,也使人往上升。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, ' 他使人贫穷,也使人富足,使人卑微,也 使人高贵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, '他从灰尘里 抬举 贫寒人,从粪堆中 提拔 穷乏人,使他们与 王子 同坐,得著 荣耀的 座位。 地 的柱子 属于 耶和华;他将世界 立 在其上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, '他必保护 圣民 的脚步,使恶人 在黑暗中 寂然不动; 人 都不能 靠力量 得胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, '与耶和华 争竞的,必被打碎;耶和华 必从天上 以雷 攻击他,必审判 地 极的人,将力量 赐 与所立的王,高举 受膏者 的角。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, '以利加拿 往 拉玛 回 家去了。那孩子 在 祭司 以利 面前 事奉 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, '以利 的两个儿子 是恶人,不 认识 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, '这二祭司 待 百姓 是这样的规矩:凡 有人 献 祭,正煮 肉的时候,祭司 的仆人 就来,手 拿三 齿 的叉子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, '将叉子 往罐里,或 鼎里,或 釜里,或 锅里 一插, 插 上来的肉,祭司 都取了 去。凡 上 到示罗 的以色列人,他们都是这样 看待。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, '又 在未烧 脂油 以前,祭司 的仆人 就来 对献祭 的人 说:「将肉 给 祭司,叫他烤吧。他不要 煮过的, 要生的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, '献祭的人 若说:「必须 先 烧 脂油,然后你 可以随 意 取肉。」仆人就说:「 你立时 给我,不然 我便抢去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, '如此,这二少年人 的罪 在 耶和华 面前 甚 重了,因为他们藐视耶和华的祭物(或译:他们使人 厌弃 给耶和华 献祭)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, '那时,撒母耳 还是孩子,穿著 细麻布 的以弗得,侍立 在 耶和华 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, '他母亲 每年 为他 做 一件小 外袍,同著 丈夫 上来 献 年 祭 的时候带来 给他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, '以利 为 以利加拿 和 他的妻 祝福,说:「愿 耶和华 由 这 妇人 再赐 你 后裔,代替 你从耶和华 求 来的孩子。」他们就回 本乡去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, ' 耶和华 眷顾 哈拿,她就怀孕 生了 三个 儿子,两个 女儿。那孩子 撒母耳 在 耶和华 面前渐渐长大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, '以利 年甚 老迈,听见 他两个儿子 待 以色列 众人 的事,又听见 他们与 会 幕 门 前伺候 的妇人 苟合, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, '他就对他们 说:「你们为何 行 这 样的事呢? 我 从 这 众 百姓 听见 你们的恶 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, '我儿啊,不可这样! 我 听见 你们的风声 不 好,你们使耶和华 的百姓 犯了罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, '人 若 得罪 人,有士师 审判他;人 若 得罪 耶和华,谁 能为他 祈求呢?」然而他们还是不 听 父亲 的话,因为 耶和华 想要 杀他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, '孩子 撒母耳 渐渐 长大, 耶和华 与 人 越发喜爱他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, '有神 人 来 见 以利,对他 说:「耶和华 如此 说:『你祖父 在 埃及 法老 家作奴仆的时候,我不是向 他们 显现吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, '在以色列 众 支派中,我不是拣选 人 作我的 祭司,使他烧 香,在 我坛 上献祭,在我面前 穿 以弗得,又将 以色列 人 所 献的火祭 都赐 给你父 家吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, '我所 吩咐 献在我居所 的祭 物,你们为何 践踏?尊重 你的儿子 过于 尊重我,将我民 以色列 所献美好的 祭物 肥己呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, '因此,耶和华─以色列的 神 说:『我曾说,你 和你父 家 必永远 行 在我面前;现在 我 却说,决不容你们这样行。因为 尊重我的,我必重看他;藐视我的,他必被轻视。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, ' 日子 必到,我要折断 你的膀臂 和 你父 家 的膀臂,使你家中 没有 一个老年人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, '在 神使 以色列人 享 福的时候,你必看见 我居所 的败落。在你家中 必永远 没 有 一个老年人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, '我必不 从 我坛 前灭尽 你家中的 人;那未灭的必使 你眼目 干瘪、 心中 忧伤。你家 中所生的人 都 必死 在中年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, ' 你的两个 儿子 何弗尼、非尼哈 所 遭遇 的事 可作你的 证据:他们二人必一 日 同 死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, '我要为自己 立 一个忠心的 祭司;他必照 我的心 意 而行。我要为他 建立 坚固的 家;他必永远 行 在我的受膏者 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, '你家 所剩下的 人都 必 来 叩拜 他,求块 银子,求个 饼,说:求 你赐我 祭司的职分,好叫我得点 饼 吃。』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, '童子 撒母耳 在以利 面前 事奉 耶和华。当那些 日子,耶和华 的言语 稀少,不 常有 默示。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, ' 一日,以利 睡卧 在自己的地方;他眼目 昏花,看 不 分明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, '神 的灯在 神 耶和华 殿内 约柜 那里,还没有 熄灭,撒母耳 已经睡了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, '耶和华 呼唤 撒母耳。撒母耳说:「我在这里!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, '就跑 到 以利那里,说:「 你呼唤 我?我在这里。」以利回答说:「我没有 呼唤你,你去 睡吧。」他就去 睡了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, '耶和华 又 呼唤 撒母耳。撒母耳 起来,到 以利那里,说:「 你呼唤 我?我在这里。」以利回答说:「我的儿,我没有 呼唤你,你去 睡吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, '那时撒母耳 还未 认识 耶和华,也未 得 耶和华 的 默示。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, ' 耶和华 第三次 呼唤 撒母耳。撒母耳起来,到 以利那里,说:「 你又呼唤 我?我在这里。」以利 才明白 是 耶和华 呼唤 童子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, '因此以利 对撒母耳 说:「你仍去 睡吧; 若 再呼唤 你,你就说:『耶和华啊,请说, 仆人 敬听!』」撒母耳 就去,仍睡 在原处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, '耶和华 又来 站著,像前 三次 呼唤说:「撒母耳啊!撒母耳啊!」撒母耳 回答说:「请说, 仆人 敬听!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, '耶和华 对 撒母耳 说:「 我 在以色列中 必行 一件事,叫听见的 人 都 必耳 鸣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, '我指著 以利家 所 说的话,到了 时候,我必始 终 应验 在 以利身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, '我曾告诉 他 必 永远 降罚 与 他的家,因 他知道 儿子 作孽,自招 咒诅,却不 禁止 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, '所以 我向以利 家 起誓说:『以利 家 的罪孽,虽献祭 奉礼物,永 不能 得赎去。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, '撒母耳 睡 到 天亮,就开 了 耶和华 的殿 门, 不敢 将 默示 告诉 以利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, '以利 呼唤 撒母耳 说:「我儿 撒母耳啊!」撒母耳回答说:「我在这里!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, '以利说:「耶和华 对你 说 什么, 你不要 向我 隐瞒;你若将 神 对你 所 说 的隐瞒 一句,愿 他 重重地 降罚 与你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, '撒母耳 就把 一切 话 都告诉了 以利,并没有 隐瞒。以利说:「这是 出于 耶和华,愿 他凭自己的 意旨 而行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, '撒母耳 长大了,耶和华 与他 同在,使他所说的话 一句都 不 落空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, '从但 到 别是巴 所有的 以色列人 都知道 耶和华 立 撒母耳 为先知。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, '耶和华 又 在示罗 显现;因为 耶和华 将自己 的话 默示 撒母耳,撒母耳 就把这 话 传遍 以色列地。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, '以色列人 出去 与 非利士人 打仗,安营 在 以便以谢;非利士人 安营 在亚弗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, '非利士人 向 以色列人 摆阵。两军交 战 的时候,以色列人 败 在非利士人 面前;非利士人在战 场上 杀了 他们的军兵 约有四 千 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, '百姓 回 到 营里,以色列 的长老 说:「耶和华 今日 为何 使我们败在 非利士人 面前呢?我们不如将 耶和华 的约 柜 从示罗 抬 到我们这里来,好 在我们中间 救我们 脱离敌人 的手。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, '于 是百姓 打发人 到示罗,从那里 将 坐在 二基路伯 上万军 之耶和华 的约 柜 抬来。以利 的两个 儿子 何弗尼、非尼哈 与 神 的约 柜 同来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, ' 耶和华 的约 柜 到了 营中,以色列 众人 就大 声 欢呼,地 便震动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, '非利士人 听见 欢呼 的声音,就说:「在希伯来人 营里 大 声 欢呼,是什么 缘故呢?」随后就知道 耶和华 的约柜 到了 营中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, '非利士人 就惧怕起来, 说:「有神 到了 他们营中」;又说:「我们 有祸了! 向来 不 曾有 这样的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, '我们 有祸了!谁 能救我们 脱离这些 大能之 神 的手呢?从前在旷野 用各样 灾殃 击打 埃及人的,就是 这些 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, '非利士人哪,你们要刚强,要作 大丈夫,免得 作 希伯来人的奴仆,如同 他们作 你们的奴仆一样。你们要作 大丈夫,与他们争战 。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, '非利士人 和以色列人打仗,以色列人 败了,各 向各家 奔逃,被杀的人 甚 多,以色列的 步兵 仆倒了 三万。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, '神 的约柜 被掳去,以利 的两个 儿子 何弗尼、非尼哈 也都被杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, '当 日,有一个便雅悯 人 从阵上 逃跑,衣服 撕裂, 头 蒙灰尘,来到 示罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, '到了的时候, 以利 正在道 旁 坐 在 自己的位上 观望, 为 神 的约柜 心里 担忧。那人 进 城 报信,合 城 的人就都呼喊起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, '以利 听见 呼喊 的声音 就问说:「这 喧嚷 是什么缘故呢?」那人 急忙 来 报信 给以利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, '那时以利 九十 八 岁 了,眼目 发直,不 能 看见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, '那人 对 以利 说:「我是 从 阵上 来的,今日 我 从阵上 逃回。」以利说:「我儿,事情 怎样?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, '报信的 回答 说:「以色列人 在非利士人 面前 逃跑, 民中 被杀的 甚多!你的两个 儿子 何弗尼、非尼哈 也 都死了,并且 神 的约柜 被掳去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, '他一 提 神 的约柜,以利就从 他的位 上往后 跌倒,在 门 旁 折断 颈项 而死;因为 他 年纪老迈,身体沉重。以利作 以色列 的士师 四十 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, '以利的儿妇、非尼哈 的妻 怀孕 将到产期,她听见 神 的约柜 被掳去,公公 和丈夫 都死了,就 猛然 疼痛,曲身 生产; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, '将要死 的时候,旁边 站著 的妇人们对她 说:「不要 怕! 你生了 男孩子了。」她却不 回答,也不 放 在心上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, '她给孩子 起名叫 以迦博,说:「荣耀 离开  以色列了!」这是因 神 的约柜 被掳去,又因 她公公 和丈夫都死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, '她又说:「荣耀 离开  以色列,因为 神 的约柜 被掳去了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, '非利士人 将 神 的约柜 从以便以谢 抬 到 亚实突。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, '非利士人 将 神 的约柜 抬 进 大衮 庙,放 在大衮 的旁边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, '次日清早,亚实突人 起来,见 大衮 仆倒 在耶和华 的约柜 前,脸 伏于 地,就把 大衮 仍立 在原处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, '又次日 清早 起来,见 大衮 仆倒 在耶和华 的约柜 前,脸 伏于 地,并且大衮 的头 和两 手 都在 门槛上 折断,只 剩下 大衮的残体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, '(因 此,大衮 的祭司 和一切 进 亚实突、大衮 庙 的人都不 踏 大衮庙 的门槛,直到 今 日。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, '耶和华 的手 重重 加在 亚实突人身上,败坏他们,使 他们 生痔疮。 亚实突 和 亚实突的四境都是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, '亚实突 人 见 这 光景,就说:「以色列 神 的约柜 不可 留 在我们这里,因为 他的手 重重 加在我们 和 我们神 大衮的身上」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, '就打发 人去请 非利士 的众 首领 来 聚集,问他们说:「我们向以色列 神 的约柜 应当怎样 行呢?」他们回答说:「可以将以色列 神 的约柜 运到 迦特去。」于 是将 以色列 神 的约柜 运到那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, ' 运到 之后, 耶和华 的手 攻击 那城,使那城 的 人 大 大 惊慌,无论 大 小都 生 痔疮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, '他们就把 神 的约柜 送到 以革伦。 神 的约柜 到了,以革伦人 就喊嚷起来 说:「他们将 以色列 神 的约柜 运 到我们这里,要害我们 和 我们的众民!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, '于 是打发人 去请 非利士 的众 首领 来,说:「愿 你们将 以色列 神 的约柜 送 回 原处,免得 害了 我们 和 我们的众民!」原来 神 的手 重 重 攻击那城, 城 中的人有 因惊慌 而死的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, ' 未 曾死 的人 都生了 痔疮。合城 呼号,声音上达 于 天。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, ' 耶和华 的约柜 在非利士人 之地 七个 月。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, '非利士人 将祭司 和占卜的 聚了来,问他们说:「我们向耶和华 的约柜 应当怎样 行?请指示我们 用何法 将约柜送回 原处。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, '他们说:「若 要将 以色列 神 的约柜 送回去,不可 空空地 送去,必 要 给他 献 赔罪的礼物,然后 你们可得痊愈,并知道 他的手 为何 不 离开  你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, '非利士人说:「应当用什么 献 为 赔罪的礼物呢?」他们回答说:「当照非利士 首领 的数目,用五个 金 痔疮,五个 金 老鼠,因为 在你们众人 和你们首领 的身上都是一样的 灾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, '所以当制造 你们痔疮 的像 和毁坏 你们田地 老鼠 的像,并要归 荣耀 给以色列的 神,或者 他向你们 和 你们的神,并 你们的田地,把 手 放轻些。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, '你们为何 硬 著 心 像 埃及人 和法老 一样呢? 神在埃及人中间 行奇事,埃及人岂不 释放以色列人,他们就去了吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, '现在 你们应当造 一辆 新 车,将 两只 未 曾负 轭 有乳的 母牛 套 在车上,使 牛犊 回家去,离开 母牛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, '把 耶和华 的约柜 放 在 车上,将 所 献 赔罪 的金 物 装 在匣子里,放在柜旁,将柜 送 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, '你们要看看:车若 直行 以色列的境界到伯.示麦去, 这 大 灾 就是耶和华 降 在我们身上的;若 不然,便可以知道 不是 他的手 击打 我们,是 我们 偶然 遇见的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, '非利士人 就这 样行:将 两只 有乳的 母牛 套 在车上,将 牛犊 关 在家里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, '把 耶和华 的约柜 和 装金 老鼠 并 金痔疮 像的 匣子 都放 在 车上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, '牛 直行 大道,往伯.示麦 去,一面走 一面叫,不 偏 左 右。非利士 的首领 跟 在后面,直到伯.示麦 的境界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, '伯.示麦人 正在平原 收割 麦子,举 目 看见 约柜,就欢喜了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, '车 到了伯.示麦人 约书亚 的田间,就站住了。在那里 有一块大 磐石,他们把 车 劈了,将 两只母牛 献 给耶和华 为燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, '利未人 将 耶和华 的约柜 和装 金 物 的 匣子 拿下来,放 在 大 磐石上。当 日伯.示麦 人 将燔祭 和 平安祭 献 给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, '非利士人 的五个 首领 看见,当 日 就回 以革伦去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, '非利士人 献 给耶和华 作 赔罪 的金 痔疮像,就是这些:一个 是为亚实突,一个 是为迦萨,一个 是为亚实基伦,一个 是为迦特,一个 是为以革伦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, '金 老鼠 的数目 是照非利士 五个 首领的 城邑,就是坚固的 城邑 和 乡村,以及 大 磐石。这磐石是 放 耶和华 约柜的,到 今 日还在伯.示麦人 约书亚 的田间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, '耶和华因伯.示麦 人 擅观 他的 约柜,就击杀了 他们 七十 人;那时有五万 人在那里(原文是七十人加五万人)。百姓 因 耶和华 大大 击 杀 他们,就哀哭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, '伯.示麦 人 说:「谁 能 在 耶和华 这 圣洁的 神 面前侍立呢?这约柜可以从我们 这里送 到 谁那里去呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, '于 是打发 人 去见基列.耶琳 的居民,说:「非利士人 将 耶和华 的约柜 送回来了,你们下来 将约柜 接 到你们那里去吧!」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, '基列.耶琳 人 就下来,将 耶和华 的约柜 接上去,放 在 山上 亚比拿达 的家中,分派 他儿子 以利亚撒 看守 耶和华 的约柜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, ' 约柜在基列.耶琳 许久。过了 二十 年,以色列 全 家 都倾 向 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, '撒母耳 对 以色列 全 家 说:「你们 若 一 心 归顺 耶和华,就要把 外邦的 神 和亚斯她录 从你们中间 除掉,专 心 归向 耶和华,单单地 事奉他。他必救 你们 脱离非利士人 的手。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, '以色列 人 就除掉 诸巴力 和 亚斯她录,单单地 事奉 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, '撒母耳 说:「要使 以色列 众人 聚集 在米斯巴,我好为你们 祷告 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, '他们就聚集 在米斯巴,打 水 浇 在耶和华 面前,当 日 禁食,说:「我们得罪了 耶和华。」于 是撒母耳 在米斯巴 审判 以色列 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, '非利士人 听见 以色列 人 聚集 在米斯巴,非利士 的首领 就上来 要攻击 以色列人。以色列 人 听见,就惧怕非利士人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, '以色列 人 对 撒母耳 说:「愿 你不 住地 为我们 呼求 耶和华─我们的 神,救 我们脱离非利士人 的手。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, '撒母耳 就把 一只 吃奶的 羊羔 献 与耶和华 作全牲的 燔祭, 为 以色列人 呼求 耶和华;耶和华 就应允他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, '撒母耳 正 献 燔祭的时候,非利士人 前来 要与以色列人 争战 。当 日,耶和华 大 发雷 声,惊乱 非利士人,他们就败 在以色列人 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, '以色列 人 从 米斯巴 出来,追赶 非利士人,击杀他们,直到伯.甲 的下边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, '撒母耳 将 一块 石头 立 在米斯巴 和 善 的中间,给石头起 名 叫 以便以谢,说:「到 如今 耶和华 都帮助我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, '从此,非利士人 就被制伏,不 敢 再 入 以色列人 的境内。撒母耳 作士师的时候, 耶和华 的手 攻击非利士人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, '非利士人 所 取 以色列人 的城邑,从以革伦 直到 迦特,都归 以色列人了。 属这些城的四境,以色列人 也从非利士人 手下 收回。那时 以色列人 与 亚摩利人 和好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, '撒母耳 平生 作 以色列 的士师。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, '他每年 巡 行 到伯特利、吉甲、米斯巴,在 这 几 处 审判 以色列人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, '随后回到 拉玛,因为 他的家 在那里;也在那里 审判 以色列人,且 为耶和华 筑了 一座坛。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, ' 撒母耳 年纪老迈,就立 他儿子 作以色列的 士师。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, '长 子 名 叫 约珥,次子 名 叫亚比亚;他们在别是巴 作士师。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, '他儿子 不 行 他的道,贪图 财利,收受 贿赂,屈枉 正直。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, '以色列 的长老 都 聚集,来到 拉玛 见 撒母耳, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, '对他 说:「 你 年纪老迈了,你儿子 不 行 你的道。现在 求你为我们 立 一个王 治理我们,像列 国一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, '撒母耳 不喜悦 他们说「立 一个王 治理我们」,他 就祷告 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, '耶和华 对 撒母耳 说:「百姓 向你 说 的 一切 话,你只管依从;因为 他们不是 厌弃 你,乃是 厌弃 我,不要我作他们 的王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, '自从 我领 他们 出埃及 到 如 今,他们常常离弃我,事奉 别 神。现在 他们 向你 所行 的,是照 他们素来所 行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, '故此 你要依从 他们的话,只是 当 警戒 他们,告诉 他们 将来那王 怎样 管辖 他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, '撒母耳 将 耶和华 的话 都 传 给 求 他 立王 的百姓,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, '「管辖 你们 的王 必 这 样行:他 必 派 你们的儿子 为他 赶车、跟马,奔走 在车 前; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, '又派 他们作千夫 长、五十夫 长,为他 耕种 田地,收割 庄稼,打造 军 器 和车上 的器械; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, '必取 你们的女儿 为他制造香膏,做饭 烤饼; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, '也必取 你们最好的 田地、 葡萄园、橄榄园 赐 给他的臣仆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, '你们的粮食 和葡萄园所出的,他必取十分之一 给 他的太监 和臣仆; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, '又必取 你们的仆人 婢女,健壮的 少年人 和 你们的驴,供 他的差役。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, '你们的羊群 他必取十分之一,你们 也必作 他的 仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, '那 时 你们必因 所 选的 王 哀求耶和华,耶和华 却不 应允 你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, '百姓 竟不肯 听 撒母耳 的话,说:「不然!我们定 要 一个王 治理我们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, ' 使 我们 像列 国一样,有王 治理我们,统领 我们,为我们争 战 。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, '撒母耳 听见 百姓 这一切 话,就将这话陈明 在 耶和华面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, '耶和华 对 撒母耳 说:「你只管依从 他们的话,为他们 立 王。」撒母耳 对 以色列 人 说:「你们各 归各城 去吧!」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, '有 一个 便雅悯人,名 叫基士,是便雅悯 人 亚斐亚 的玄孙,比歌拉 的曾孙,洗罗 的孙子,亚别 的儿子,是个大能的 勇士(或译:大财主)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, '他 有 一个儿子,名 叫扫罗,又健壮、又俊美,在以色列 人中 没有 一个 能比他 的;身体比众 民 高 过 一头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, '扫罗 的父亲 基士 丢了 几头驴, 他就吩咐 儿子 扫罗 说:「 你带 一个 仆人 去 寻找 驴。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, '扫罗就走过 以法莲 山地,又过 沙利沙 地,都没有 找著;又过 沙琳 地,驴也不在那里;又过 便雅悯 地,还没有 找著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, ' 到了 苏弗 地,扫罗对 跟随他 的仆人 说:「 我们不如回去,恐怕 我父亲 不为 驴挂心,反为我们 担忧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, '仆人说:「 这 城里 有一位神 人,是众人所尊重的,凡 他所 说的 全都应验。我们不如 往他那里 去,或者 他能将我们 当走的 路 指示 我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, '扫罗 对仆人 说:「 我们若去,有什么 可以送 那人呢? 我们囊中 的食物 都吃尽了,也没有 礼物 可以送 那神 人,我们还有 什么没有?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, '仆人 回答 扫罗 说:「 我手里 有 银子 一舍客勒 的四分之一,可以送 那神 人,请他指示 我们 当走的路。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '(从前 以色列中,若有人 去 问 神,就 说:「 我们问 先见 去吧!」 现在称为「先知」的,从前 称为「先见」。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, '扫罗 对仆人 说:「你说的 是, 我们可以去。」于 是他们往 神 人 所住的 城里 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, '他们 上 坡 要进城,就 遇见 几个少年女子 出来 打 水,问她们 说:「先见 在这里 没有?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, '女子回答 说:「在这里, 他在你们前面。快去吧! 他今日 正到 城里,因为 今日 百姓 要在邱坛 献祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, '在他还没有 上 邱坛 吃祭物之先,你们一进 城 必 遇见 他;因 他未 到,百姓 不能 吃,必 等他 先祝 祭,然后 请的客 才吃。现在 你们上去,这时候 必遇见 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, '二人就上去; 将进 城的时候, 撒母耳 正迎著他们 来,要上 邱坛去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, '扫罗 未到 的前 一 日,耶和华 已经指示 撒母耳 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, '「明日 这时候,我必使 一个人 从便雅悯 地 到你这里来,你要膏他 作 我民 以色列 的君。他必救 我民 脱离非利士人 的手;因 我民 的哀声 上达 于 我,我就眷顾他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, '撒母耳 看见 扫罗的时候,耶和华 对他说:「看哪,这人 就是我对你 所 说的,他 必治理 我的民。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, '扫罗 在 城门 里走到 撒母耳跟前,说:「请 告诉 我,先见 的寓所 在哪里?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, '撒母耳 回答 说:「我就是 先见。你在我前面 上 邱坛去,因为你们今日 必与我 同席;明日早晨 我送你去,将你心里 的事 都 告诉 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, '至于 你 前 三 日 所丢的 那几头驴, 你心里 不必 挂念,已经 找著了。以色列 众人 所仰慕的 是谁呢?不是 仰慕你 和你父 的全 家吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, '扫罗 说:「我 不是 以色列 支派 中至小 的便雅悯人吗?我家 不是便雅悯 支派 中至小的 家吗?你为何 对我 说 这样 的话呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, '撒母耳 领 扫罗 和 他仆人 进了 客堂,使他们 在请来的客 中坐 首 位;客 约有三十个 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, '撒母耳 对厨役 说:「我交 给你 收存的 那 一分祭肉 现在可以拿来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, '厨役 就把收存的 腿 拿来,摆 在扫罗 面前,撒母耳说:「 这是所留下的,放在 你面前。吃吧!因 我请 百姓的时候,特意为你 存留 这肉到此时。」当 日,扫罗 就与 撒母耳 同席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, '众人从邱坛 下来 进城,撒母耳和 扫罗 在 房顶上 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, '次日清早起来, 黎明的时候,扫罗 在房顶上。撒母耳 呼叫 他 说:「起来吧,我好送你回去。」扫罗 就起来, 和撒母耳 一同 出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, '二人 下 到城 角,撒母耳 对 扫罗 说:「要吩咐 仆人 先 走(仆人就先走了);你 且站在 这里,等我将 神 的话 传与你听。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, '撒母耳 拿 瓶 膏油 倒 在 扫罗的头上,与他亲嘴,说:「这不是 耶和华 膏你 作 他产业 的君吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, '你今日 与我 离别之后,在便雅悯 境内 的泄撒,靠近 拉结 的坟墓,要遇见 两个 人。他们必对你 说:『你去 找 的那 几头驴 已经找著了。现在 你父亲 不为 驴 挂心,反为你 担忧,说:我为儿子 怎么 才好呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, '你从那里 往前 行,到了 他泊 的橡树 那里,必遇见 三个 往 伯特利 去拜 神 的人:一个 带著 三只 山羊羔,一个 带著 三 个 饼,一个 带著 一皮袋 酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, '他们必问 你 安,给 你 两个 饼,你就从他们手中 接过来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, '此 后 你到 神 的山, 在那里 有非利士人 的防兵。 你到了 城的时候,必遇见 一班 先知 从邱坛 下来,前面 有鼓瑟的、击鼓的、吹笛的、弹琴的,他们 都受感说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, '耶和华 的灵 必大大感动 你,你就与他们 一同受感说话;你要变为 新 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, ' 这 兆头 临到 你,你 就可以 趁 时 而做,因为 神 与你同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, '你当在我以先 下到 吉甲, 我 也必下 到那里献 燔祭和 平安 祭。你要等候 七 日,等 我到了 那里,指示 你 当行 的事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, ' 扫罗转 身 离 别 撒母耳, 神 就赐 他 一个新 心。当 日 这 一切 兆头 都应验了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, '扫罗到了 那 山, 有一班 先知 遇见他, 神 的灵 大大感动 他,他就在先知中 受感说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, ' 素来 认识扫罗的,看见 他和 先知 一同受感说话, 就彼此 说:「基士 的儿子 遇见什么了?扫罗 也 列在先知中吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, '那地方 有一个人 说:「这些人的父亲 是谁呢?」此后 有 句俗语说:「扫罗 也 列在先知中吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, '扫罗受感说话 已毕,就上 邱坛去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, '扫罗 的叔叔 问扫罗 和 他仆人 说:「你们往哪里 去了?」回答说:「找 驴去了。我们见 没有驴,就到了 撒母耳那里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, '扫罗 的叔叔 说:「请 将撒母耳 向你们 所 说 的话告诉 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, '扫罗 对 他叔叔 说:「他明明地 告诉 我们 驴 已经找著了。」至于  撒母耳 所 说的 国 事,扫罗却没有 告诉 叔叔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, '撒母耳 将 百姓 招聚 到 米斯巴 耶和华那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, '对 他们 说:「耶和华─以色列的 神 如此 说:『我 领你们 以色列人 出埃及,救 你们 脱离埃及人 的手,又救你们脱离欺压 你们 各 国 之人的手。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, '你们 今日 却厌弃了 救 你们 脱离一切 灾 难 的 神,说:『求 你立 一个王 治理我们。』现在 你们应当按著支派、宗族 都站在 耶和华 面前。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, '于 是,撒母耳 使 以色列 众 支派 近前来掣签,就掣出 便雅悯 支派来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, '又使 便雅悯 支派 按著宗族 近前来,就掣出 玛特利 族,从其中又掣出 基士 的儿子 扫罗。众人寻找他 却寻不 著, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, '就 问 耶和华说:「那人 到 这里 来了没有?」耶和华 说:「 他 藏 在 器具中了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, '众人就跑去 从那里 领出他来。他站 在 百姓中间,身体比众 民 高 过 一头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, '撒母耳 对 众 民 说:「你们看 耶和华 所 拣选的 人, 众 民中 有可 比他的吗?」众 民 就大声欢呼 说:「愿 王 万岁!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, '撒母耳 将 国 法 对 百姓 说明,又记 在书上,放 在耶和华 面前, 然后遣散 众 民,各 回各家去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, '扫罗 往 基比亚 回家去,有 神 感动 的 一群人 跟随 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, '但有些匪 徒 说:「这人 怎能 救我们呢?」就藐视他,没有 送 他 礼物;扫罗却 不理会。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, '亚扪人 的王拿辖 上来,对著基列.雅比 安营。雅比 众 人 对 拿辖 说:「你与我们 立 约,我们就服事你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, '亚扪人 拿辖 说:「你们 若 由我剜出 你们各人 的右 眼,以此 凌 辱 以色列 众人,我就与你们 立约。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, '雅比 的长老 对他 说:「求你宽容 我们 七 日,等我们打发 人 往以色列 的全 境去;若 没有人 救 我们,我们就出来 归顺你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, '使者 到了 扫罗 住的基比亚,将这话 说 给百姓 听,百姓 就都 放 声 而哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, '扫罗 正 从 田间 赶 牛 回来, 问说:「百姓 为什么 哭呢?」众人将 雅比 人 的话 告诉 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, '扫罗 听见 这 话,就被 神 的灵 大大感动,甚是 发 怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, '他将 一对 牛 切成块子,托 讬付 使者 传送 以色列 的全 境,说:「凡 不 出来 跟随 扫罗 和 撒母耳的,也必这样 切开  他的牛。」于 是耶和华 使 百姓 惧怕,他们就都出来,如同一 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, '扫罗在比色 数点他们:以色列 人 有 三十万,犹大 人 有三万。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, '众人对那 使者 说:「你们要回复基列.雅比 人 说,明日 太阳 近午的时候,你们 必得 解救。」使者 回去 告诉 雅比 人,他们就欢喜了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, '于 是雅比 人 对亚扪人说:「明日 我们出来 归顺你们,你们可以随 意 待 我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, ' 第二日,扫罗 将 百姓 分为 三 队,在晨 更的时候 入了 亚扪人的 营,击杀 他们 直到 太阳 近午, 剩下的人 都逃散,没有 二人 同 在一处 的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, '百姓 对 撒母耳 说:「那说『扫罗 岂能管理 我们』的是谁呢?可以将他 交出来,我们好杀死他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, '扫罗 说:「今 日 耶和华 在以色列中 施行 拯救, 所以不可 杀 人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, '撒母耳 对 百姓 说:「 我们要往吉甲 去,在那里 立 国。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, '众 百姓 就到了 吉甲 那里,在 耶和华 面前 立 扫罗 为王,又在耶和华 面前 献 平安 祭。 扫罗 和以色列 众 人 大大 欢喜。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, '撒母耳 对 以色列 众人 说:「 你们向我 所 求的,我已应 允了,为你们 立了 一个王; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, '现在 有这王 在你们前面 行。我 已年老 发白,我的儿子 都在你们这里。我 从幼年 直到 今 日 都在你们前面 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, '我在这里,你们要在耶和华 和 他的受膏者 面前 给我 作见证。我夺过 谁 的牛,抢过 谁 的驴,欺负过 谁,虐待过 谁,从谁 手里 受过 贿赂 因而 眼 瞎呢?若有,我必偿还。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, '众人说:「你未 曾欺负我们, 虐待我们,也未 曾从谁 手里 受过 什么。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, '撒母耳对他们 说:「 你们 在我手里 没有 找著 什么,有耶和华 和 他的受膏者 今 日 为证。」他们说:「愿 他为证。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, '撒母耳 对 百姓 说:「从前 立 摩西、 亚伦,又 领 你们列祖 出埃及 地 的是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, '现在 你们要站住,等我在耶和华 面前 对你们 讲论 耶和华 向你们 和 你们列祖 所 行 一切 公义的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, '从前 雅各 到了 埃及,后来你们列祖 呼求 耶和华,耶和华 就差遣 摩西、 亚伦 领 你们列祖 出埃及,使他们在这 地方 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, '他们却忘记 耶和华─他们的 神,他就把他们 付与 夏琐 将军 西西拉 的手里,和 非利士人 并摩押 王 的手里。于 是这些人常来攻击 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, '他们就呼求 耶和华 说:『 我们离弃 耶和华,事奉 巴力 和 亚斯她录,是有罪了。现在 求你救我们 脱离仇敌 的手,我们必事奉你。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, '耶和华 就差遣耶路.巴力、 比但、 耶弗他、 撒母耳 救 你们 脱离四围 仇敌 的手,你们才安然 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, '你们见 亚扪 人 的王 拿辖 来 攻击你们,就对我 说:『 我们定要 一个王 治理 我们。』其实耶和华─你们的 神 是你们的王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, '现在,你们所 求 所 选 的王 在这里。看哪,耶和华 已经为你们 立 王了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, '你们若 敬畏 耶和华,事奉 他,听从 他的话,不 违背 他 的命令, 你们 和 治理 你们 的 王 也都顺从 耶和华─你们的 神 就好了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, '倘若 不 听从 耶和华 的话,违背 他 的命令,耶和华 的手 必 攻击你们,像从前攻击你们列祖一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, ' 现在 你们要站住,看 耶和华 在你们眼前要 行 一件 大 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, '这不是 割 麦子 的时候吗?我求告 耶和华,他必 打雷 降雨,使你们又知道 又看出, 你们 求 立王 的事 是在耶和华 面前 犯 大 罪了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, '于 是撒母耳 求告 耶和华,耶和华 就在这 日 打雷 降雨,众 民 便甚 惧怕 耶和华 和 撒母耳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, '众 民 对 撒母耳 说:「求你为 仆人们 祷告 耶和华─你的 神,免得 我们死亡;因为 我们 求 立王的事正是 罪 上 加 罪了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, '撒母耳 对 百姓 说:「不要 惧怕!你们 虽然行了 这 恶,却 不要 偏离 耶和华,只要尽 心 事奉 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, '若 偏离耶和华去 顺从 那 不能 救 人的虚 神是 无 益的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, '耶和华 既 喜悦 选 你们 作他的 子民, 就必 因 他的大 名 不 撇弃 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, '至于  我,断 不停止 为你们 祷告,以致得罪 耶和华。我必以善 道正 路 指教 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, '只要 你们敬畏 耶和华,诚诚实实地 尽 心 事奉 他, 想念 他向你们 所行的事 何等大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, '你们若 仍然 作恶, 你们 和 你们的王 必一同灭亡。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, '扫罗 登基 年四十岁;作 以色列 王二 年的时候, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, ' 就从以色列中 拣选了 三 千人: 二千 跟随 扫罗 在密抹 和伯特利 山, 一千 跟随 约拿单 在便雅悯 的基比亚;其余 馀的 人 扫罗都打发 各 回各家去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, '约拿单 攻击在 迦巴的 非利士人 的防营,非利士人 听见了。扫罗 就在遍 地 吹 角,意思说,要使希伯来人 听见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, '以色列 众人 听见 扫罗 攻击 非利士人 的防营,又 听见以色列人 为非利士人 所憎恶, 就跟随 扫罗 聚集 在吉甲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, '非利士人 聚集,要与 以色列人 争战 ,有车 三万辆,马兵 六 千,步兵 像 海 边 的沙 那样多,就上来在伯‧亚文 东边 的密抹 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, '以色列 百姓 见 自己 危急窘迫, 就藏 在山洞、丛林、石穴、隐密处,和坑中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, '有些希伯来人 过了 约旦河,逃到迦得 和基列 地。扫罗 还是 在吉甲,百姓 都 战 战 兢兢地 跟随他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, '扫罗照著撒母耳 所 定的日期 等了 七 日。撒母耳 还没有 来 到吉甲,百姓 也离开 扫罗 散去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, '扫罗 说:「把燔祭 和平安祭 带 到我这里来。」扫罗就献上 燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, ' 刚献 完 燔祭, 撒母耳 就到了。扫罗 出去 迎接他,要问他好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, '撒母耳 说:「你做 的是什么事呢?」扫罗 说:「因为 我见 百姓 离开 我 散去,你 也不 照所定的 日期 来到,而且非利士人 聚集 在密抹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, '所以我心里说:恐怕我没有 祷告 耶和华。 非利士人 下到 吉甲 攻击我,我就勉强 献上 燔祭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, '撒母耳 对 扫罗 说:「你做了糊涂事了,没有 遵守 耶和华─你 神 所 吩咐你 的命令。若遵守,耶和华 必在 以色列 中坚立 你的王位,直到 永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, '现在 你的王位 必不 长久。耶和华 已经寻著 一个合他心意 的人, 立他 作 百姓 的君,因为 你没有 遵守 耶和华 所 吩咐你的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, '撒母耳 就起来,从 吉甲 上到 便雅悯 的基比亚。扫罗 数点 跟随他的,约有六 百 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, '扫罗 和他儿子 约拿单,并 跟随他们 的人,都住 在便雅悯 的迦巴;但非利士人 安营 在密抹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, '有掠兵 从非利士 营中 出来,分为三 队:一 队 往 俄弗拉 向 书亚 地 去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, '一 队 往伯‧和仑  去,一 队 往 洗波音 谷 对面 的地境 向旷野 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, '那时,以色列 全 地 没有 一个铁匠;因为 非利士人 说,恐怕 希伯来人 制造 刀 枪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, ' 以色列 人 要磨 锄、 犁、 斧、 铲,就下到 非利士人那里去磨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, '但有 锉 可以锉铲、犁、三 齿叉、斧子,并赶 牛锥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, '所以到了 争战  的日子, 跟随 扫罗 和 约拿单的 人 没有 一个手里 有 刀 有枪的,惟独扫罗 和他儿子 约拿单 有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, '非利士人 的一队防兵 到了 密抹 的隘口。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, '有 一日,扫罗 的儿子 约拿单 对 拿 他兵器 的少年人 说:「 我们不如过 到那 边, 到 非利士人 的防营那里去。」但他没有 告诉 父亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, '扫罗 在基比亚 的尽 侭边, 坐 在米矶仑  的石榴树 下, 跟随他 的约有六 百 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, '在那里有亚希突 的儿子 亚希亚,穿著 以弗得。(亚希突是以迦博 的哥哥,非尼哈 的儿子,以利 的孙子。以利从前在示罗 作耶和华 的祭司。) 约拿单 去了,百姓 却不 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, '约拿单 要 从 隘口 过 到 非利士 防营那里去。这 隘口两边 各有一个山 峰: 一 名 播薛,一 名 西尼; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, '一 峰 向 北,与密抹 相对,一 峰向南,与迦巴 相对。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, '约拿单 对 拿 兵器 的少年人 说:「 我们不如过 到 未受割礼人 的防营那里去,或者 耶和华 为我们 施展能力;因为 耶和华 使人得胜,不 在乎 人多 人少。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, '拿 兵器 的对他 说:「 随你的心意 行吧。你 可以上去, 我必跟随你,与你同心。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, '约拿单 说:「 我们 要过 到 那些人那里去,使他们 看见我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, '他们若 对我们 说:『你们站住,等 我们到 你们那里去』,我们就站住,不 上 他们那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, '他们若 说:『你们上 到我们这里来』,这话 就是我们的 证据;我们便上去,因为 耶和华 将他们交在 我们手里了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, '二人 就使 非利士 的防兵 看见。非利士人 说:「 希伯来人 从 所 藏 的 洞穴 里出来了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, '防 兵 对 约拿单 和 拿 兵器 的人说:「你们上 到这里来,我们有一件事 指示 你们。」约拿单 就 对拿 兵器 的人说:「你跟随我 上去,因为 耶和华 将他们交 在以色列人 手里了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, '约拿单就爬 上去,拿 兵器 的人跟随他。约拿单 杀倒非利士人,拿 兵器 的人也随著 杀他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, ' 约拿单 和拿 兵器 的人起头 所 杀的 约有二十 人,都在一亩 地 的半 犁沟之内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, '于 是在营中、在田野、在众 民 内都有 战 兢,防兵 和掠兵 也 都 战 兢,地 也震动, 战 兢 之势甚大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, '在便雅悯 的基比亚,扫罗的 守望兵 看见 非利士的军众 溃散,四围乱 窜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, '扫罗就对 跟随他 的民 说:「你们查点查点,看 从我们这里 出去 的是谁?」他们一查点,就知道 约拿单 和拿 兵器 的人没有在这里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, ' 那 时 神 的约柜 在 以色列 人那里。扫罗 对亚希亚 说:「你将 神 的约柜 运了来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, ' 扫罗 正 与 祭司 说话的时候,非利士 营中 的 喧嚷 越发 大了;扫罗 就对 祭司 说:「停 手吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, '扫罗 和 跟随他 的人 都 聚集,来 到 战 场,看见 非利士人 用刀 互相击杀,大大 惶乱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, ' 从前 由四方 来 跟随 非利士 军 的希伯来人现在 也 转过来,帮助 跟随 扫罗 和约拿单的 以色列人了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, '那藏在 以法莲 山地 的以色列 人 听说 非利士人 逃跑, 就 出来紧紧地 追杀他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, '那 日,耶和华 使 以色列人 得胜,一直战  到伯‧亚文。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, '扫罗 叫 百姓 起誓 说,凡 不等到 晚上 向敌人 报完了仇 吃 什么 的,必受咒诅。因此这 日 百姓 没有 吃 什么, 就极其困惫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, '众 民 进 入树林,见有 蜜 在 地 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, '他们 进了 树林,见 有蜜 流下来,却没有人 敢用手 取 蜜入 口,因为 他们 怕 那誓言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, '约拿单 没有 听见 他父亲 叫 百姓 起誓,所以伸 手中 的杖,用 杖 头 蘸 在蜂 房里,转 手 送入 口内,眼睛 就明亮了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, '百姓中 有一人 对他 说:「你父亲 曾叫 百姓 严严地 起誓 说,今日 吃 什么 的, 必受咒诅;因此百姓 就疲乏了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, '约拿单 说:「我父亲 连累 你们了。你看, 我尝了 这 一点 蜜,眼睛 就 明亮了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, '今日 百姓 若 任意 吃了 从仇敌 所 夺的 物, 击杀的 非利士人 岂不 更 多吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, '这 日,以色列人击杀 非利士人,从密抹 直到亚雅仑 。百姓 甚是 疲乏, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, ' 就急忙 将 所夺的 牛 羊 和牛 犊 宰 于 地上,肉还带 血 就吃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, '有人告诉 扫罗 说:「 百姓 吃 带 血的肉,得罪 耶和华了。」扫罗说:「你们有罪了,今日 要将大 石头 滚 到我这里来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, '扫罗 又说:「你们散 在百姓中,对他们 说,你们各人 将牛 羊 牵 到我 这里 来宰了 吃,不可 吃 带 血 的肉得罪 耶和华。」这夜, 百姓 就把 牛羊 牵 到那里 宰了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, '扫罗 为耶和华 筑了 一座坛,这是他 初次 为耶和华 筑 的坛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, '扫罗 说:「我们不如夜里 下去 追赶 非利士人,抢掠 他们,直到 天 亮,不 留 他们 一人。」众民说:「 你看 怎样好 就去行吧!」祭司 说:「我们先 当亲近 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, '扫罗 求问 神说:「我下去 追赶 非利士人可以不可以?你将他们交 在以色列 人手里不交?」这 日 神 没有 回答他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, '扫罗 说:「你们百姓 中的长老 都 上 这里来,查 明 今日 是 谁 犯了罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, ' 我指著救 以色列─永生的 耶和华起誓, 就是 我儿子 约拿单犯了罪, 他也必 死。」但百姓 中 无一人 回答他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, '扫罗就对 以色列 众人 说:「你们 站在 一 边,我 与我儿子 约拿单 也站在 一 边。」百姓 对 扫罗 说:「你看 怎样好 就去行吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, '扫罗 祷告 耶和华─以色列的 神 说:「求你指示 实情。」于 是掣签掣出 扫罗 和约拿单来;百姓 尽都无事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, '扫罗 说:「你们再掣签,看是我,是 我儿子 约拿单」,就掣出 约拿单来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, '扫罗 对 约拿单 说:「你告诉 我,你做了 什么事?」约拿单 说:「我实在以手里 的杖,用杖 头 蘸了一点 蜜 尝了 一尝。 这样我就死吗(或译:吧!)?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, '扫罗 说:「约拿单哪, 你定要 死!若不然,愿  神 重重地 降罚与我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, '百姓 对 扫罗 说:「约拿单 在以色列人中 这样 大 行 拯救,岂可使他死呢?断乎不可!我们指著永生的 耶和华起誓,连他的一根头 发 也不可 落 地,因为 他今 日 与 神 一同做事。」于 是百姓 救 约拿单 免了 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, '扫罗 回去,不追赶 非利士人;非利士人 也回 本地去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, '扫罗 执掌 以色列 的国权,常常攻击 他四围的 一切 仇敌,就是摩押人、亚扪 人、以东人,和琐巴 诸王,并非利士人。他无论 往 何处去,都打败仇敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, '扫罗奋勇 攻击 亚玛力人,救了 以色列人 脱离抢掠他们 之人的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, '扫罗 的儿子 是 约拿单、亦施韦、麦基舒亚。他的两个 女儿:长女 名 米拉,次女 名 米甲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, '扫罗 的妻 名 叫亚希暖,是亚希玛斯 的女儿。扫罗的元帅 名 叫押尼珥,是尼珥 的儿子;尼珥是扫罗的 叔叔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, '扫罗 的父亲 基士,押尼珥 的父亲 尼珥,都是亚别 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, ' 扫罗 平生 常与 非利士人 大大 争战 。扫罗 遇见 有能力 的人 或 勇 士,都招募了 来跟随他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, '撒母耳 对 扫罗 说:「耶和华 差遣 我 膏你 为王,治理 他的百姓 以色列;所以 你当听从 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, '万军 之耶和华 如此 说:『以色列人 出 埃及的时候,在路上 亚玛力人 怎样 待他们,怎样 抵挡 他们,我都没忘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, '现在 你要去 击打 亚玛力人,灭尽 他们 所有 的,不可 怜惜 他们,将男 女、孩童、 吃奶的,并牛、 羊、骆驼,和 驴 尽行杀死。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, '于 是扫罗 招聚 百姓 在提拉因,数点他们,共有步兵 二十万,另有 犹大 人 一万。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, '扫罗 到了 亚玛力 的京城,在谷中 设下埋伏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, '扫罗 对 基尼人 说:「 你们离开  亚玛力人 下去吧,恐怕 我将你们和亚玛力人一同 杀灭;因为 以色列 人 出 埃及的时候,你们 曾恩 待 他们。」于 是基尼人 离开  亚玛力人去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, '扫罗 击打 亚玛力人,从哈腓拉 直到 埃及 前 的 书珥, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, '生 擒了 亚玛力 王 亚甲,用 刀 杀尽 亚玛力的众 民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, '扫罗 和百姓 却怜惜 亚甲,也 爱惜上好的 牛、羊、牛犊、羊羔,并 一切 美物,不 肯 灭绝。凡 下贱 瘦弱的,尽都杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, '耶和华 的话 临 到 撒母耳 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, '「 我立 扫罗 为王,我后悔了;因为 他转去 不跟从我,不 遵守 我的命令。」撒母耳 便甚忧愁,终 夜 哀求 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, '撒母耳 清早 起来,迎接 扫罗。有人告诉 撒母耳 说:「扫罗 到了 迦密,在那里 立了 纪念碑,又转 身 下 到吉甲。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, '撒母耳 到了 扫罗那里,扫罗 对他 说:「愿 耶和华 赐福 与你, 耶和华 的命令 我已遵守了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, '撒母耳 说:「我 耳中 听见 有 羊 叫、牛 鸣,是从哪里来的呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, '扫罗 说:「这是百姓 从亚玛力人 那里带来的;因为 他们爱惜 上好的 牛 羊,要 献 与耶和华─你的 神; 其余 馀的,我们都灭尽了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, '撒母耳 对 扫罗 说:「你住口吧!等我将 耶和华 昨夜 向我 所 说 的话告诉 你。」扫罗说:「请讲。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, '撒母耳 对扫罗说:「从前你 虽然 以自己为 小, 岂不是 被立为以色列 支派 的元首吗?耶和华 膏你 作 以色列 的王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, '耶和华 差遣你,吩咐你说,你去 击打 那些 犯罪的 亚玛力人,将他们 灭绝 净尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, '你为何 没有 听从 耶和华 的命令,急忙 掳掠 财物,行 耶和华 眼中 看为恶的事呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, '扫罗 对 撒母耳 说:「我实在 听从了 耶和华 的命令,行了 耶和华 所 差遣我 行的路,擒了 亚玛力 王 亚甲来,灭尽了 亚玛力人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, '百姓 却在 所当灭的物中,取了 最好的 牛 羊,要在吉甲 献 与耶和华─你的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, '撒母耳 说:耶和华 喜悦 燔祭 和平安祭,岂如喜悦人听从 他 的话呢? 听命 胜 于 献祭;顺从 胜于 公羊 的脂油。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, '悖逆 的罪与行邪术 的罪 相等;顽梗 的罪与拜虚神和偶像 的罪相同。你既 厌弃 耶和华 的命令,耶和华也厌弃你 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, '扫罗 对 撒母耳 说:「我有罪了,我因 惧怕 百姓,听从 他们的话,就 违背了 耶和华 的命令 和 你的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, '现在 求 你赦免 我的罪,同我 回去,我好敬拜 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, '撒母耳 对 扫罗 说:「我不 同你 回去;因为 你厌弃 耶和华 的命令,耶和华 也厌弃 你作 以色列 的王。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, '撒母耳 转身 要走,扫罗就扯住 他外袍 的衣襟,衣襟就撕断了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, '撒母耳 对他 说:「如此,今日 耶和华 使 以色列 国 与你 断绝,将这国赐 与比你更 好的 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, ' 以色列 的大能者 必不 致说谎,也不 致后悔;因为 他 迥非 世人,决不后悔。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, '扫罗说:「我有罪了,虽然如此,求 你在我百姓 的长老 和 以色列人 面前 抬举我,同我 回去,我好敬拜 耶和华─你的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, '于 是撒母耳 转身 跟随 扫罗回去,扫罗 就敬拜 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, '撒母耳 说:「要把 亚玛力 王 亚甲 带 到我这里来。」亚甲 就欢欢喜喜地 来 到他面前, 心里说,死亡 的苦难 必定 过去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, '撒母耳 说:「你既 用刀 使妇人 丧子,这样,你母亲 在妇人中 也必丧子。」于 是,撒母耳 在吉甲 耶和华 面前 将 亚甲 杀死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, '撒母耳 回了 拉玛。扫罗 上 他所住的基比亚,回 自己的 家去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, '撒母耳 直到 死 的日子,再 没有 见 扫罗;但 撒母耳 为 扫罗 悲伤,是因耶和华 后悔 立 他 为 以色列的王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, '耶和华 对 撒母耳 说:「我 既厌弃 扫罗 作 以色列 的王,你 为 他悲伤 要到 几时呢?你将膏油 盛满了 角,我差遣你 往 伯利恒人 耶西 那里去;因为 我在他众子之内,预定 一个作王的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, '撒母耳 说:「我怎能 去呢?扫罗 若听见,必要杀我。」耶和华 说:「你可以带 一只牛 犊去,就说:『我来 是要向耶和华 献祭。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, '你要请 耶西 来吃祭肉,我就指示你 所 当行的事。我所 指给 你的人,你要 膏 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, '撒母耳 就照 耶和华 的话 去行。到了 伯利恒,那城 里的长老 都战 战 兢兢地 出来迎接他,问他说:「你是为平安 来的吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, '他说:「为平安 来的,我是给耶和华 献祭。你们当自洁,来 与我 同吃祭肉。」撒母耳就使 耶西 和 他众子 自洁,请 他们 来吃祭肉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, ' 他们来的时候,撒母耳看见 以利押,就心里说,耶和华 的受膏者 必定 在他面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, '耶和华 却对 撒母耳 说:「不要 看 他的外貌 和 他身材 高大, 我不拣选他。因为,耶和华不 像 人 看人:人 是 看 外貌;耶和华 是看 内心。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, '耶西 叫 亚比拿达 从撒母耳 面前 经过,撒母耳说:「耶和华 也 不 拣选 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, '耶西 又叫沙玛 从撒母耳面前经过,撒母耳说:「耶和华 也 不 拣选 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, '耶西 叫他七个 儿子 都从撒母耳 面前 经过,撒母耳 说:「这 都不是 耶和华 所拣选的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, '撒母耳 对 耶西 说:「你的儿子 都在这里吗?」他回答说:「 还有 个小的,现在 放 羊。」撒母耳 对 耶西 说:「你打发 人去叫他来;他若 不 来,我们必不 坐席。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, '耶西就打发人 去叫了他来。他 面色光红, 双目 清秀,容貌 俊美。耶和华 说:「 这 就是他,你起来 膏他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, '撒母耳 就用 角 里的膏油,在 他诸兄 中 膏了 他。从这 日 起,耶和华 的灵 就大大感动 大卫。撒母耳 起身 回 拉玛去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, '耶和华 的灵 离开  扫罗,有恶 魔 从 耶和华 那里来扰乱他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, '扫罗 的臣仆 对他 说:「现在 有恶 魔从 神 那里来扰乱你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, '我们的主 可以 吩咐 面前的 臣仆,找 一个 善于  弹 琴的来,等 神 那里来的恶 魔 临 到你身上的时候,使他用手 弹琴,你 就好了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, '扫罗 对 臣仆 说:「你们可以 为我 找 一个 善于  弹琴的,带 到我这里来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, '其中有一个 少年人 说:「 我曾见 伯利恒人 耶西 的一个儿子 善于  弹琴,是大 有勇敢 的战  士,说话 合宜,容貌俊美,耶和华 也与他同在。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, '于 是扫罗 差遣 使者 去见 耶西,说:「请你打发 你放羊 的 儿子 大卫 到我这里来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, '耶西 就把 几个饼 和一皮袋 酒,并一只 山羊 羔,都驮在驴上,交给 他儿子 大卫,送 与 扫罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, '大卫 到了 扫罗那里,就侍立 在扫罗面前。扫罗甚 喜爱他,他就作了 扫罗拿 兵器的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, '扫罗 差遣人 去见 耶西,说:「求 你容大卫 侍立 在我面前,因为 他在我眼前 蒙了 恩。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, '从 神 那里来的恶魔 临 到 扫罗身上的时候,大卫 就拿 琴,用手 而弹,扫罗 便舒畅 爽快,恶 魔 离了 他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, '非利士人 招聚 他们的军旅,要来争战 ;聚集 在属犹大 的 梭哥,安营 在 梭哥 和亚西加 中间的以弗‧大悯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, '扫罗 和以色列 人 也聚集,在以拉 谷 安营,摆列队伍,要与 非利士人 打仗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, '非利士人 站 在 这边 山上,以色列人 站 在 那边 山上,当中 有谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, '从非利士 营中 出来 一个讨战  的人,名 叫歌利亚,是迦特人,身高 六 肘 零一虎口; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, '头 戴 铜 盔, 身穿 铠甲,甲 重 五 千 舍客勒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, '腿 上 有铜 护膝,两肩 之中 背负铜 戟; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, '枪 杆 粗如织布的 机轴,铁 枪 头 重六 百 舍客勒。有一个拿 盾牌 的人在他前面 走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, '歌利亚对著 以色列 的军队 站立,呼叫 说:「你们出来 摆列 队伍 做什么呢?我 不是 非利士人吗?你们 不是扫罗的 仆人吗?可以从你们 中间拣选 一人,使他下 到我这里来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, '他若 能 与我 战 斗,将我杀死,我们就作 你们的 仆人;我 若 胜了他,将他杀死,你们就作 我们的 仆人,服事 我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, '那非利士人 又说:「我 今 日 向 以色列人 的军队 骂阵。你们叫 一个人出来,与我 战 斗。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, '扫罗 和以色列 众人 听见 非利士人 的这些 话,就惊惶,极其 害怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, '大卫 是犹大、伯利恒的 以法他 人 耶西 的儿子。耶西有 八个 儿子。当扫罗 的时候,耶西 已经 老迈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, '耶西 的三个 大 儿子 跟随 扫罗 出 征。这 出 征 的三个 儿子:长子 名 叫以利押,次子 名叫亚比拿达,三子 名叫沙玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, '大卫 是 最小的;那三个 大 儿子 跟随 扫罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, '大卫 有时离开  扫罗,回 伯利恒 放 他父亲 的羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, '那非利士人 早 晚 都出来 站著,如此四十 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, '一日,耶西 对他儿子 大卫 说:「 你拿 一伊法 烘了的穗子 和 十个 饼,速速地送到 营里去,交给你哥哥们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, '再 拿这 十块 奶饼,送 给他们的千夫 长,且问 你哥哥 们好,向他们要 一封信来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, '扫罗 与 大卫的三个哥哥和以色列 众 人,在以拉 谷 与 非利士人 打仗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, '大卫 早晨 起来,将 羊 交托 讬 一个看守的人,照著 他父亲 所吩咐的话,带著 食物去了。到了 辎重营,军兵 刚出 到 战 场,呐喊 要战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, '以色列人 和非利士人 都摆列队伍,彼此 相对。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, '大卫 把 他带来的 食物 留 在 看守 物件 人的手下,跑 到战 场, 问 他哥哥们 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, ' 与他们 说话的时候, 那讨战 的,就是属迦特 的非利士人 歌利亚,从非利士 队 中出来,说 从前所说的 话;大卫 都听见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, '以色列 众 人 看见 那人,就逃跑,极其 害怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, '以色列 人 彼此说:「这 上来 的人 你看见了吗?他上来 是 要向 以色列人 骂阵。若有 能杀他的,王 必赏赐他 大 财,将 自己的女儿 给 他为妻,并 在以色列人中 免 他父 家 纳粮当差。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, '大卫 问 站 在旁边 的人 说:「有人 杀 这 非利士人,除掉 以色列人 的耻辱,怎样 待 他呢? 这 未受割礼 的非利士人 是谁呢?竟敢 向永生 神 的军队 骂阵吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, '百姓 照先前 的话 回答 他 说:「有人 能杀这非利士人,必如此如此 待 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, '大卫 的长 兄 以利押 听见 大卫与 他们 所说的话, 就向他 发 怒,说:「你下来 做什么呢?在旷野 的那 几只 羊,你交托 讬了 谁呢?我 知道 你的骄傲 和 你心里 的恶意, 你下来 特为要 看 争战 !」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, '大卫 说:「我做了 什么呢? 我来岂没 有 缘故吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, '大卫就离开 他 转向 别人,照先前 的话 而问;百姓 仍照 先前的 话 回答他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, '有人听见 大卫 所 说 的话,就告诉了 扫罗;扫罗便打发人叫他来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, '大卫 对 扫罗 说:「人 都不必 因 那非利士人胆 怯。你的仆人 要去 与 那 非利士人 战 斗。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, '扫罗 对 大卫 说:「你不 能 去 与 那 非利士人 战 斗;因为 你 年纪太轻,他 自幼 就作战  士。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, '大卫 对 扫罗 说:「你仆人 为父亲 放 羊,有时来了 狮子, 有时来了熊,从群中 啣 一只羊羔去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, '我就 追赶牠,击打牠,将羊羔从牠口中 救出来。牠起来 要害我,我就揪著 牠的胡子,将牠打 死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, '你仆人 曾打死 狮子 和 熊,这 未受割礼 的非利士人 向永生 神 的军队 骂阵,也必 像狮子和熊 一般。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, '大卫 又说:「耶和华 救我脱离 狮子 和熊 的爪,也必 救我 脱离这 非利士人 的手。」扫罗 对 大卫 说:「你可以去吧!耶和华 必 与你同在。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, '扫罗 就把自己的战 衣 给 大卫 穿上,将铜 盔 给 他 戴上,又给他 穿上 铠甲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, '大卫 把 刀 跨 在 战 衣外,试试 能走不能走;因为 素来没有 穿惯, 就对 扫罗 说:「我穿戴这些 不 能 走,因为 素来没有 穿惯。」 于 是摘 脱了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, '他手中 拿 杖,又在 溪中 挑选了 五块 光滑 石子,放 在袋里,就是 牧人 带的囊里;手中 拿著甩石的机弦,就去迎 那非利士人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, '非利士人 也渐渐地 迎著 大卫 来,拿 盾牌 的 走在前头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, '非利士人 观看,见了 大卫,就藐视他;因为 他 年轻,面色光红, 容貌 俊美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, '非利士人 对 大卫 说:「 你 拿杖 到我这里 来,我 岂是狗呢?」非利士人 就指著自己的神 咒诅 大卫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, '非利士人 又对 大卫 说:「来吧!我将 你的肉 给 空中 的飞鸟、田野 的走兽吃。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, '大卫 对 非利士人 说:「你 来 攻击我,是靠著刀 枪 和铜戟;我 来 攻击你,是靠著万军 之耶和华 的名,就是你所 怒骂 带领以色列 军队的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, '今 日 耶和华 必将你交 在我手里。我必杀你,斩 你的头, 又将非利士 军兵 的尸首 给 空中 的飞鸟、地上 的野兽吃,使普天下的人 都知道 以色列中 有 神; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, '又使这 众 人 知道 耶和华 使人得胜,不是 用刀 用枪,因为 争战  的胜败全在乎耶和华。他必将你们 交 在我们手里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, ' 非利士人 起身, 迎著 大卫 前来。大卫 急忙 迎著 非利士人,往战 场 跑去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, '大卫 用 手 从 囊中 掏 出 一块石子来,用机弦甩去,打 中 非利士人 的 额,石子 进入 额内,他就仆倒,面 伏于  地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, '这样,大卫 用机弦 甩石,胜了 那非利士人,打 死他;大卫 手中 却没有 刀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, '大卫 跑去,站 在 非利士人身旁, 将 他的刀 从鞘中 拔出来,杀死他,割了 他的头。非利士众人 看见 他们讨战 的勇士 死了,就都逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, '以色列 人 和犹大人 便起身 呐喊,追赶 非利士人,直 到迦特(或译:该) 和 以革伦 的城门。被杀的 非利士人 倒在 沙拉音 的路上,直到 迦特 和 以革伦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, '以色列 人 追赶 非利士人 回来,就夺了 他们的营盘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, '大卫 将 那非利士人 的头 拿 到 耶路撒冷,却将 他军装 放 在自己的帐棚里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, '扫罗 看见 大卫 去 攻击 非利士人,就问 元帅 押尼珥 说:「押尼珥啊,那 少年人 是谁 的儿子?」押尼珥 说:「 我敢在王面前起誓,我不 知道。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, '王 说:「你 可以问问 那 幼年人 是谁 的儿子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, '大卫 打死 非利士人 回来,押尼珥 领 他 到 扫罗 面前,他手中 拿著非利士人 的头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, '扫罗 问他 说:「少年人哪,你是 谁 的儿子?」大卫 说:「我是你仆人 伯利恒人 耶西 的儿子。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, ' 大卫对 扫罗 说 完了话,约拿单 的心 与大卫 的心 深相契合。约拿单 爱大卫,如同爱自己的性命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, '那 日 扫罗 留住大卫,不 容他 再回 父 家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, '约拿单 爱 大卫 如同爱自己的性命,就与他 结 盟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, '约拿单 从身上 脱下 外袍,给了 大卫,又将战 衣、 刀、 弓、 腰带都给了他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, '扫罗 无论差遣 大卫 往何处 去,他都做事精明。扫罗 就立 他作 战  士长,众 百姓 和 扫罗 的臣仆 无不喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, ' 大卫 打死了 那 非利士人,同众人回来的时候,妇女们 从以色列 各 城 里出来,欢欢喜喜,打鼓 击磬,歌唱 跳舞,迎接 扫罗 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, '众妇女 舞蹈 唱和,说:「扫罗 杀死 千千,大卫 杀死万万。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, '扫罗 甚 发怒,不喜悦 这 话,就说:「将万万 归 大卫,千千 归 我,只 剩下 王位 没有给他了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, ' 从这 日 起,扫罗 就怒视 大卫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, ' 次日,从 神 那里来的恶 魔 大大降 在 扫罗身上,他就在 家 中胡言乱语。大卫 照 常 弹琴,扫罗 手里 拿著枪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, '扫罗 把 枪 一抡,心里说,我要将大卫 刺透,钉在墙上。大卫 躲避 他 两次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, '扫罗 惧怕 大卫;因为 耶和华 离开  自己, 与大卫同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, '所以扫罗 使大卫离开  自己,立他 为 千夫 长,他就领 兵 出 入。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, ' 大卫 做事 无不 精明,耶和华 也与他同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, '扫罗 见 大卫 做事精明,就甚怕 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, '但以色列 和犹大 众人 都爱 大卫,因为 他 领他们 出 入。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, '扫罗 对 大卫 说:「 我将 大 女儿 米拉 给 你 为妻,只要你 为我 奋勇,为耶和华 争战 。」扫罗 心里说:「我不好 亲手 害他,要 藉 借非利士人 的手 害他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, '大卫 对 扫罗 说:「我是 谁,我是什么 出身,我父 家 在以色列中是何等的家,岂敢 作 王的 女婿呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, '扫罗 的女儿 米拉 到了 当给 大卫 的时候,扫罗却 给了 米何拉人 亚得列 为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, '扫罗 的次女 米甲 爱 大卫。有人告诉 扫罗,扫罗 就喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, '扫罗 心里说:「我将这女儿给 大卫,作 他的 网罗, 好藉 借非利士人 的手 害他。」所以扫罗 对 大卫 说:「你今日 可以第二次 作我的 女婿。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, '扫罗 吩咐 臣仆说:「你们暗中 对 大卫 说:『 王 喜悦 你,王的臣仆 也都 喜爱你,所以你当 作王的 女婿。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, '扫罗 的臣仆 就照 这 话 说 给大卫 听。大卫 说:「你们以为 作王的 女婿 是一件小事吗?我是 贫穷 卑微 的人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, '扫罗 的臣仆 回奏 说,大卫 所说的 如此如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, '扫罗 说:「你们要对大卫 这样 说:『王 不 要 什么聘礼,只要 一百 非利士人 的阳皮,好在王 的仇敌 身上报仇。』」扫罗 的意思 要使 大卫 丧 在非利士人 的手里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, '扫罗的臣仆 将 这 话 告诉 大卫,大卫 就欢喜 作王 的女婿。日期 还没有 到, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, '大卫 和跟随他的人 起身 前往,杀了 二百 非利士人, 将 阳皮 满数 交 给王,为要作王的 女婿。于 是扫罗 将 女儿 米甲 给 大卫 为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, '扫罗 见 耶和华 与 大卫同在,又知道 女儿 米甲 爱大卫, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, ' 就 更 怕 大卫, 常 作 大卫 的仇敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, ' 每逢 非利士 军长 出来打仗,大卫 比 扫罗 的臣仆 做事精明,因此他的名 被人尊重。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, '扫罗 对 他儿子 约拿单 和 众 臣仆 说,要杀 大卫;扫罗 的儿子 约拿单 却甚 喜爱 大卫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, '约拿单 告诉 大卫 说:「我父 扫罗 想要 杀你,所以 明日早晨 你要 小心,到 一个僻静地方 藏身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, '我 就出 到你 所 藏的田里,站 在我父亲 旁边 与 他 谈论。我看他 情形怎样,我 必告诉 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, '约拿单 向 他父亲 扫罗 替大卫 说 好话,说:「王 不可 得罪 王的仆人 大卫;因为 他未 曾得罪 你, 他所行 的都与你 大有 益处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, '他拚 命 杀 那 非利士人,耶和华 为 以色列众人 大 行 拯救;那时你看见,甚是欢喜,现在为何 无故 要杀 大卫,流无辜人 的血,自己取罪呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, '扫罗 听了 约拿单 的话, 就指著永生的 耶和华 起誓说:「我必不 杀他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, '约拿单 叫 大卫来, 把 这 一切 事 告诉 他, 带 他 去见 扫罗。他就仍然 侍立在 扫罗面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, '此后又 有 争战 的事。大卫 出去 与非利士人 打仗,大大 杀败 他们,他们就在他面前 逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, '从耶和华 那里来的恶 魔 又降 在 扫罗身上(扫罗 手里 拿枪 坐 在屋里),大卫 就用手 弹琴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, '扫罗 用枪 想要 刺透 大卫,钉在墙上;他却躲开 ,扫罗 的 枪 刺 入墙内。当 夜 大卫 逃走,躲避了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, '扫罗 打发 人 到 大卫 的房屋 那里窥探他,要等到天亮 杀他。大卫的 妻 米甲 对他 说:「你今夜 若 不 逃 命,明日 你 要被杀。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, '于 是米甲 将 大卫 从 窗户 里缒下去,大卫就逃 走,躲避了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, '米甲 把 家中的神像 放 在 床上,头 枕在 山羊毛 装的枕头上,用被 遮盖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, '扫罗 打发 人 去捉拿 大卫,米甲说:「他 病了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, '扫罗 又打发 人 去看 大卫,说:「当连床 将他 抬 来,我好杀他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, '使者 进去,看见 床 上 有神像,头 枕在山羊毛 装的枕头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, '扫罗 对 米甲 说:「你为什么 这样 欺哄我,放 我仇敌 逃走呢?」米甲回答 说:「他 对我 说:『你放我走,不然 我要杀你。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, '大卫 逃 避,来 到拉玛 见 撒母耳,将 扫罗 向他 所 行 的事述说了一遍。他 和撒母耳 就往 拿约 去居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, '有人告诉 扫罗,说 大卫 在拉玛 的拿约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, '扫罗 打发 人 去捉拿 大卫。去的人见 有 一班 先知 都受感说话,撒母耳 站 在其中 监管他们; 打发去的人 也 受 神 的灵 感动说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, '有人将这事告诉 扫罗,他又 打发 人去,他们 也 受感说话。扫罗 第三次 打发 人去,他们 也 受感说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, '然后 扫罗自己 往拉玛 去,到了 西沽 的 大 井,问 人说:「撒母耳 和大卫 在哪里呢?」有人说:「 在拉玛 的拿约。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, '他就往 拉玛的 拿约 去。 神 的灵 也 感动 他,一面走 一面说话,直 到 拉玛 的拿约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, ' 他 就脱了 衣服, 在撒母耳 面前 受感说话, 一 昼 一 夜 露体 躺卧。因此 有句俗语说:「扫罗 也 列在先知中吗?」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, '大卫 从拉玛 的拿约 逃跑,来到 约拿单 那里,对他说:「我做了 什么?有什么 罪孽呢?在你父亲 面前 犯了什么 罪,他竟 寻索 我的性命呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, '约拿单回答说:「断然不是!你必不 致死。 我父 做 事,无论大 小,没有 不 叫 我 知道的。 怎么 独有 这 事 隐瞒 我呢?决不 如此。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, '大卫 又 起誓 说:「你父亲 准 知 我在你眼前 蒙 恩。他心里说,不如不 叫约拿单 知道,恐怕 他愁烦。 我指著永生的 耶和华,又敢 在你面前起誓, 我离 死 不过一步。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, '约拿单 对 大卫 说:「你心里 所 求的,我必为你 成就。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, '大卫 对 约拿单 说:「 明日 是初一,我 当 与 王 同席,求你容我去 藏 在田野,直到 第三 日晚上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, '你父亲 若 见我不在席上,你就说:『大卫 切 求 我 许他回 本城 伯利恒去,因为 他全 家 在那里 献年 祭。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, '你父亲若 说 好,仆人 就平安了;他 若 发 怒,你就知道 他 决意 要害我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, '求你施 恩 与 仆人,因 你在耶和华 面前曾与 仆人 结 盟。我若 有 罪,不如你自己 杀我, 何必 将我交给 你父亲呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, '约拿单 说:「断无此事! 我若 知道 我父亲 决意 害 你,我岂不 告诉 你呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, '大卫 对 约拿单 说:「你父亲 若 用厉言 回答你,谁 来告诉 我呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, '约拿单 对 大卫 说:「你我且往 田野 去。」二人 就往 田野去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, '约拿单 对 大卫 说:「愿 耶和华─以色列的 神为证。明日 约在这时候,或第三日, 我探 我父亲的意思, 若向 你 有好意,我岂 不 打发人 告诉 你吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, ' 我父亲 若 有意 害 你,我不告诉 你 使你 平平安安地 走,愿 耶和华 重重地 降 罚 与我。愿 耶和华 与你 同在,如同从前 与 我父亲 同在一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, '你要照耶和华 的慈爱 恩待 我,不 但 我 活著 的时候免 我死亡, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, '就是我死后,耶和华 从 地 上 剪除 你 仇敌的时候, 你也永 不可 向 我家 绝了 恩惠。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, '于 是约拿单 与 大卫 家 结盟,说:「愿 耶和华 藉 借 大卫 的仇敌 追讨背约的罪。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, '约拿单 因 爱 大卫 如同爱 自己的性命,就使他 再 起誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, '约拿单 对他 说:「明日 是初一, 你的座位 空设,人必理会你不在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, '你等三日,就要速速 下去,到你从前 遇事 所 藏 的地方,在以色 磐石 那里 等候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, '我 要向磐石旁边 射 三 箭,如同 射 箭靶一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, ' 我要打发 童子,说:『去 把 箭 找来。』我若 对童子 说:『 箭 在 后头,把箭拿来』,你就可以回来;我指著永生的 耶和华起誓,你 必 平安 无 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, '我若 对童子 说:『 箭 在 前头』,你就要去,因为 是耶和华 打发你去的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, '至于 你 我 今日所 说 的话, 有耶和华 在你 我中间为证,直到 永远。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, '大卫 就去藏 在田野。到了 初一日,王 坐席 要吃 饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, '王 照 常 坐 在 靠 墙 的位上,约拿单 侍立,押尼珥 坐 在扫罗 旁边,大卫 的座位 空设。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, '然而这 日 扫罗 没有 说 什么, 他想 大卫 遇事, 偶染不 洁,他必定 是不 洁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, ' 初二 日 大卫 的座位 还空设。扫罗 问 他儿子 约拿单 说:「耶西 的儿子 为何 昨日、 今日 没有 来 吃饭呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, '约拿单 回答 扫罗说:「大卫 切 求 我 容他往 伯利恒去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, '他说:『求 你容我去,因为 我 家 在城里 有献祭的事;我长兄 吩咐 我去。如今 我若 在你眼前 蒙 恩,求 你容我去 见 我的弟兄』;所以 大卫没有 赴 王 的席。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, '扫罗 向约拿单 发 怒,对他 说:「你这顽梗 背逆 之妇人所生的,我岂不 知道 你 喜悦 耶西 的儿子,自取羞辱,以致你母亲 露体 蒙羞吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, ' 耶西 的儿子 若 在 世间 活著,你 和你的国位 必站立 不住。现在 你要打发人去,将他 捉拿 交给我; 他是 该死的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, '约拿单 对 父亲 扫罗 说:「他为什么 该死呢?他做了 什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, '扫罗 向约拿单 抡 枪 要刺他,约拿单 就知道 他父亲 决意 要杀 大卫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, '于 是约拿单 气忿忿地 从 席上 起来,在这初 二 日 没有 吃 饭。他因 见父亲 羞辱大卫,就 为 大卫 愁烦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, ' 次日早晨,约拿单 按著与大卫 约会 的时候出到 田野,有一个童子 跟随。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, '约拿单对童子 说:「你跑去, 把 我 所 射 的箭 找来。」童子 跑去,约拿单 就把箭 射 在童子前头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, '童子 到 了 约拿单 落 箭 之 地,约拿单 呼叫 童子 说:「箭 不是 在你 前头吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, '约拿单 又呼叫 童子说:「速速地去,不要 迟延!」 童子 就拾起 箭来,回 到 主人那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, '童子 却不 知道 这是什么意思,只有 约拿单 和大卫 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, '约拿单 将 弓箭 交 给 童子,吩咐说:「你拿到 城 里去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, '童子 一去,大卫 就从磐石的南 边 出来,俯伏 在地,拜了 三 拜;二人 亲嘴,彼此 哭泣,大卫 哭得更 恸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, '约拿单 对大卫 说:「 我们 二人 曾指著耶和华 的名 起誓 说:『愿  耶和华 在你 我中间,并 你我后裔 中间为证,直到 永远。』如今你平平安安地 去吧!」大卫就起身 走了;约拿单 也回 城里去了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, '大卫 到了 挪伯 祭司 亚希米勒那里,亚希米勒 战 战 兢兢地 出来迎接 他,问他 说:「你 为什么 独自来,没有 人 跟随呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, '大卫 回答祭司 亚希米勒 说:「王 吩咐我 一件事 说:『 我 差遣你 委托 讬你 的 这 件事,不要 使人 知道。』故此我已派定 少年人 在 某处等候我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, '现在 你手 下 有 什么?求你给 我 五个 饼 或是 别样的食物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, '祭司 对 大卫 说:「 我手 下 没有 寻常的 饼,只 有 圣 饼;若 少年人 没有 亲近 妇人才可以给。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, '大卫 对 祭司 说:「实在 约有三 日 我们 没有亲近 妇人;我出来的时候,虽是 寻常 行路,少年人 的器皿 还是洁净的;何况 今日 不更是 洁净吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, '祭司 就拿 圣 饼给他;因为 在那里 没 有 别样饼,只有 更 换 新 饼,从 耶和华 面前撤下来 的陈设 饼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, '(当 日有 扫罗的 一个臣子 留在 耶和华 面前。他名 叫多益,是以东人,作扫罗 的 司牧 长。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, '大卫 问亚希米勒 说:「你手 下 有 枪 有 刀 没有?因为 王 的事 甚急, 连 刀剑 器械 我 都没有 带。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, '祭司 说:「你在以拉 谷 杀 非利士人 歌利亚 的那 刀 在这里,裹 在布中,放在以弗得 后边, 你要 就可以拿去; 除此以外, 再没有 别的。」大卫 说:「这刀没有 可比的!求你给 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, '那 日 大卫 起来,躲避 扫罗,逃 到 迦特 王 亚吉那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, '亚吉 的臣仆 对亚吉 说:「这 不是 以色列 国王 大卫吗?那里的妇女跳舞 唱和,不是 指著他 说『扫罗 杀死 千千,大卫 杀死万万』吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, '大卫 将 这 话 放 在心里,甚 惧怕 迦特 王 亚吉, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, '就在众人面前 改变了 寻常的举动,在他们手下 假装疯癫,在 城门 的门扇 上胡写乱画 划,使唾沫 流 在 胡子上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, '亚吉 对 臣仆 说:「 你们看,这人 是疯子。为什么 带 他 到我这里来呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, '我 岂缺少 疯子, 你们带 这人 来在我面前 疯癫吗?这人 岂可进 我的家呢?」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, '大卫 就离开  那里,逃 到 亚杜兰 洞。他的弟兄 和他父亲 的全 家 听见了,就都下 到他 那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, '凡 受窘迫的、 欠债的、 心里 苦恼 的都聚集 到大卫那里;大卫就作 他们的 头目,跟随他 的约有 四 百 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, '大卫 从那里 往 摩押 的米斯巴去,对 摩押 王 说:「求 你容我父 母 搬来,住在你们这里,等 我知道 神 要为我 怎样 行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, '大卫领 他父母到 摩押 王 面前。大卫 住 山寨 多少 日子,他父母也住摩押王那里多少日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, '先知 迦得 对 大卫 说:「你不要 住 在山寨, 要往 犹大 地去。」大卫 就离开 那里,进入 哈列 的树林。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, '扫罗 在基比亚 的拉玛,坐 在垂丝柳树 下,手里 拿著枪,众 臣仆 侍立 在左右。扫罗 听见 大卫 和跟随他 的 人 在何处, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, ' 就对左右 侍立 的臣仆 说:「便雅悯人哪,你们要 听我的话!耶西 的儿子 能将田地 和葡萄园 赐 给你们各人吗?能立 你们各人 作千夫 长 百夫 长吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, '你们竟 都 结党 害我!我的儿子 与 耶西 的儿子 结盟的时候,无人 告诉 我; 我的儿子 挑唆 我的臣子 谋害 我,就如今 日的光景,也无人 告诉 我,为我 忧虑。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, '那时以东人 多益 站 在 扫罗 的臣仆中,对他说:「我曾看见 耶西 的儿子 到 了 挪伯,亚希突 的儿子 亚希米勒那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, '亚希米勒为他 求问 耶和华,又给 他 食物,并给 他 杀非利士人 歌利亚 的 刀。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, '王 就打发 人将 祭司 亚希突 的儿子 亚希米勒 和 他父亲 的全 家,就是 住挪伯 的祭司 都召了来;他们 就来 见 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, '扫罗 说:「亚希突 的儿子,要 听我的话!」他回答说:「主啊,我在这里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, '扫罗 对他 说:「你 为什么 与 耶西 的儿子 结党 害我,将食物 和刀 给 他,又为他 求问 神,使他起来 谋害 我,就如今 日的光景?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, '亚希米勒 回答 王 说:「 王的臣仆 中有谁 比大卫 忠心呢?他是王 的女婿,又是 王的参谋,并且在王家中 是尊贵的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, '我岂是从今日 才 为他 求问 神呢?断不是这样!王 不要 将罪 归我 和我父 的全 家;因为 这 事,无论 大 小,仆人 都 不 知道。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, '王 说:「亚希米勒啊,你 和你父 的全 家 都是该 死的!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, '王 就吩咐左右的 侍卫 说:「你们去 杀 耶和华 的祭司;因为 他们帮助 大卫,又 知道 大卫 逃跑,竟没有 告诉 我。」扫罗 的臣子 却不 肯 伸 手 杀 耶和华 的祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, '王 吩咐多益 说:「你 去 杀 祭司吧!」以东人 多益 就 去 杀 祭司,那 日 杀了 穿 细麻布 以弗得 的八十 五 人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, '又用 刀 将 祭司 城 挪伯 中的男 女、孩童、 吃奶的,和牛、羊、驴 尽都杀灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, '亚希突 的儿子 亚希米勒 有一个 儿子,名叫 亚比亚他,逃 到 大卫那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, '亚比亚他 将 扫罗 杀 耶和华 祭司 的事告诉 大卫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, '大卫 对亚比亚他 说:「那 日 我见以东人 多益 在那里,就 知道 他必 告诉 扫罗。你父 的全 家 丧命,都是因我 的缘故。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, '你可以住 在我这里,不要 惧怕。因为 寻索 你命 的就是 寻索 我的命;你 在我这里 可 得保全。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, '有人告诉 大卫 说:「 非利士人 攻击 基伊拉, 抢夺 禾场。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, '所以大卫 求问 耶和华 说:「我去 攻打 那些 非利士人可以不可以?」耶和华 对 大卫 说:「你可以去 攻打 非利士人,拯救 基伊拉。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, '跟随大卫 的人 对他 说:「 我们 在犹大 地这里 尚且惧怕,何况 往 基伊拉 去攻打 非利士人 的军旅呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, '大卫 又 求问 耶和华。耶和华 回答 说:「你起身 下 基伊拉去,我 必 将 非利士人 交 在你手里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, '大卫 和跟随他的人 往 基伊拉去,与非利士人 打仗,大大 杀 败 他们,又夺获 他们的牲畜。这样,大卫 救了 基伊拉 的居民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, ' 亚希米勒 的儿子 亚比亚他 逃 到 基伊拉 见 大卫的时候,手里 拿著以弗得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, '有人告诉 扫罗说:「 大卫 到了 基伊拉。」扫罗 说:「 他进了 有门 有闩 的城,困闭在里头;这是 神 将他 交 在我手里了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, '于 是扫罗 招聚 众 民,要下去 攻打 基伊拉城,围困 大卫 和 跟随他的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, '大卫 知道 扫罗 设计 谋害 他,就对 祭司 亚比亚他 说:「将以弗得 拿过来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, '大卫 祷告说:「耶和华─以色列的 神啊,你仆人 听 真了 扫罗 要 往 基伊拉 来,为我的缘故 灭 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, '基伊拉 人 将我交 在扫罗手里不交?扫罗 照著 你仆人 所听 的话下来不下来?耶和华─以色列的 神啊,求 你指示 仆人!」耶和华 说:「扫罗必下来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, '大卫 又说:「基伊拉 人 将我 和 跟随我的人 交 在扫罗 手里不交?」耶和华 说:「必交出来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, '大卫 和跟随他的 约有六 百 人,就起身 出了 基伊拉,往 他们所 能往的地方去。有人告诉 扫罗, 大卫 离开 基伊拉 逃走;于 是扫罗不 出来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, '大卫 住 在旷野 的山寨里,常在 西弗 旷野 的山地。扫罗 天天 寻索大卫, 神 却不 将大卫交 在他手里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, '大卫 知道 扫罗 出来 寻索 他的命。那时,他住在西弗 旷野 的树林里; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, '扫罗 的儿子 约拿单 起身,往 那树林 里去见 大卫,使 他倚靠 神 得以坚固, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, '对他 说:「不要 惧怕! 我父 扫罗 的手 必不 加害于 你;你 必作 以色列 的王,我 也作 你的 宰相。 这事 我父 扫罗 知道了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, '于 是二人 在耶和华 面前 立 约。大卫 仍住在 树林里,约拿单 回 家去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, '西弗人 上到 基比亚 见 扫罗,说:「大卫 不是 在我们 那里的树林里 山寨中、 旷野 南边 的哈基拉 山 藏著吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, '王啊, 请你随 你的心 愿  下 来,我们必 亲自将他交 在王 的手里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, '扫罗 说:「愿 耶和华 赐福 与你们,因 你们顾恤 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, '请 你们回去,再 确实 查 明 他的住处 和 行踪,是谁 看见 他在那里,因为 我听见 人说 他 甚 狡猾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, '所以要看 准 他藏匿 的 地方,回来 据实地 告诉我,我就与你们同 去。他 若 在 犹大 的境内,我必从千门万户 中搜出 他来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, '西弗人就起身,在扫罗 以先 往 西弗去。大卫 和跟随他的人 却在玛云 旷野 南边 的 亚拉巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, '扫罗 和跟随他的人 去 寻找大卫;有人告诉 大卫,他就下到 磐石,住在 玛云 的旷野。扫罗 听见,便在玛云 的旷野 追赶 大卫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, '扫罗 在山 这 边 走,大卫 和跟随他的人 在山 那 边走。大卫 急忙 躲避 扫罗;因为扫罗 和跟随他的人,四面围住 大卫 和 跟随他的人,要拿获他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, '忽有使者 来 报告 扫罗 说:「 非利士人 犯 境 抢掠,请王快快 回去!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, '于 是扫罗 不追赶 大卫,回 去 攻打 非利士人。因此 那 地方 名叫西拉‧哈玛希罗结。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, '大卫 从那里 上去,住在隐‧基底 的山寨里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, ' 扫罗 追赶 非利士人 回来,有人告诉 他 说:「 大卫在隐‧基底 的旷野。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, '扫罗 就从 以色列人中 挑选 三 千 精兵,率领 他们往 野羊 的磐石 去,寻索 大卫 和跟随他的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, '到 了 路 旁 的羊 圈,在那里 有洞,扫罗 进去 大解。大卫 和跟随他的人 正藏 在洞里 的深处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, '跟随的人 对 大卫 说:「 耶和华 曾应许你 说:『 我 要将 你的仇敌 交 在你手里,你可以任 意 待 他。』如今 时候到了!」大卫 就起来,悄悄地 割下 扫罗 外袍 的 衣襟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, ' 随后 大卫 心中 自责,因为 割下 扫罗的 衣襟; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, '对跟随他的人 说:「我的主 乃是耶和华 的受膏者,我 在耶和华 面前万不敢 伸 手 害他,因 他是 耶和华 的受膏者。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, '大卫 用这话 拦住 跟随他的人,不 容他们 起来 害 扫罗。扫罗 起来,从洞里 出去行 路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, '随后 大卫 也起来,从洞 里出去,呼叫 扫罗 说:「我主,我王!」扫罗 回头 观看,大卫 就屈身、脸 伏于 地 下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, '大卫 对扫罗 说:「你为何 听信 人 的谗言,说 大卫 想要 害你呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, ' 今 日 你亲眼 看见 在洞中, 耶和华 将你交 在我手里;有人叫 我杀你,我却爱惜 你,说:『我不 敢伸 手 害我的主,因为 他是 耶和华 的受膏者。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, '我父啊,看 看 你外袍 的衣襟 在我手中。 我割下 你的 衣襟,没有 杀你;你由此可以知道 我 没有 恶意 叛逆你。你 虽然猎 取 我的命,我却没有 得罪 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, '愿 耶和华 在你 我中间 判断是非, 在你身上 为我伸冤,我却不 亲手 加 害于 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, '古人 有句 俗语 说:『恶事 出 于 恶人。』我却不 亲手 加 害于 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, '以色列 王 出来 要寻找 谁呢? 追赶 谁呢?不过追赶 一条死 狗, 一个 虼蚤就是了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, '愿  耶和华 在你 我中间 施行审判,断定是非,并且鉴察,为我伸冤,救我 脱离你的手。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, ' 大卫 向 扫罗 说 完 这 话,扫罗 说:「我儿 大卫,这是 你的声音吗?」 就放 声 大哭, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, '对 大卫 说:「你 比我 公义;因为 你 以善 待我,我 却以恶 待你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, '你 今日 显明 是 以善 待 我;因为 耶和华 将 我交 在你手里,你却没有 杀我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, '人 若 遇见 仇敌,岂肯放 他平安无事地 去呢?愿  耶和华 因 你今 日 向我 所 行的,以善 报你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, ' 我也知道 你必要 作王,以色列 的国 必坚立 在你手里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, '现在 你要指著耶和华 向我 起誓,不 剪除 我的 后裔,在我父 家 不 灭没 我的名。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, '于 是大卫 向扫罗 起誓,扫罗 就回 家去;大卫 和跟随他的人 上 山寨去了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, '撒母耳 死了,以色列 众人 聚集,为他 哀哭,将他葬 在拉玛─他自己的坟墓(原文是房屋)里。大卫 起身,下 到 巴兰 的旷野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, '在玛云 有一个人,他的产业 在迦密,是一个大 富 户,有 三 千 绵羊,一千 山羊;他正 在迦密 剪 羊毛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, '那人 名叫 拿八,是 迦勒族的人;他的妻 名叫 亚比该,是聪明 俊美 的妇人。拿八 为人 刚愎 凶恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, '大卫 在旷野 听见 说 拿八 剪 羊毛, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, '大卫 就打发 十个 仆人,吩咐他们 说:「你们上 迦密 去 见 拿八,提我的名 问 他 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, '要对那富户 如此 说:『愿 你 平安,愿 你家 平安,愿 你 一切 所有 的都平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, '现在 我听说 有人为你 剪羊毛, 你的牧人 在 迦密的 时候 和我们在一处,我们没有 欺负他们,他们 也未 曾失落 什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, '可以问 你的仆人,他们必告诉 你。所以愿 我的仆人 在你眼前 蒙 恩,因为 是在 好 日子 来的。求 你随手 取点 赐 与仆人 和你儿子 大卫。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, '大卫 的仆人 到了,将这 话 提大卫 的名 都 告诉了 拿八,就住了口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, '拿八 回答 大卫 的仆人 说:「大卫 是谁?耶西 的儿子 是谁?近来 悖逆 主人 奔逃的 仆人 甚多, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, '我岂可将 饮 食 和 为我剪羊毛人 所 宰 的肉 给 我不 知道 从哪里 来的人呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, '大卫 的仆人 就转身 从原路 回 去,照 这 话 告诉 大卫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, '大卫 向跟随他的人 说:「你们各人 都要带上 刀!」众人 就都带上 刀,大卫 也 带上 刀。跟随 大卫 上去 的约有四 百 人,留下 二百 人看守 器具。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, '有拿八的一个 仆人 告诉 拿八 的妻 亚比该 说:「 大卫 从旷野 打发 使者 来问 我主人的安,主人却辱骂 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, '但是那些人 待我们 甚 好;我们 在田野 与他们 来往的 时候,没有 受他们的欺负,也未 曾失落 什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, '我们 在他们那里 牧 羊的 时候,他们 昼 夜 作 我们的 保障。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, '所以 你当筹划 㓰,看 怎样 行才好;不然,祸患 定要临 到 我主人 和 他全 家。他 性情凶暴,无人敢与他 说话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, '亚比该 急忙 将 二百 饼,两 皮袋 酒,五只 收拾好了 的羊,五 细亚 烘好了的穗子,一百 葡萄饼,二百 无花果饼,都驮 在 驴上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, '对仆人 说:「你们前头 走,我 随著你们 去。」这事她却没有 告诉 丈夫 拿八。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, ' 亚比该 骑著 驴,正下 山 坡,见 大卫 和跟随他的人 从对面 下来,亚比该就迎接 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, '大卫 曾说:「我在旷野 为那人 看守 所有的,以致他 一样 不 失落,实在 是徒然了!他向我 以 恶 报 善。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, '凡属拿八的男丁,我若 留 一个 到 明日早晨,愿  神 重重 降罚与我!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, '亚比该 见 大卫,便急忙 下 驴,在大卫 面前 脸 伏 于 地 叩拜, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, '俯伏 在 大卫 的脚前,说:「我主啊,愿 这罪 归我!求 你容婢女 向你 进言,更求你听 婢女 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, '我主 不要 理 这 坏 人 拿八, 他 的性情与他的名 相称;他名 叫拿八(就是愚顽的意思),他为人 果然愚顽。但 我主 所 打发 的仆人, 婢女 并没有 看见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, ' 我主啊,耶和华 既然 阻止你 亲手 报仇,取 流血的罪,所以我指著永生 的耶和华、又敢 在你面前起誓说:『 愿  你的仇敌 和谋 害 你 的人都像拿八一样。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, '如今 求你将 婢女 送来的 礼物 给 跟随你 的仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, '求 你饶恕 婢女 的罪过。 耶和华 必 为我主 建立 坚固 的家,因 我主 为耶和华 争战 ;并且在你平生的日子 查 不 出有什么过来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, '虽有人 起来 追逼你,寻索 你的性命,你 的性命 却在 耶和华─你的 神 那里蒙 保护,如包裹 宝器一样; 你仇敌 的性命,耶和华 必抛去,如用机弦甩石一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, '我主 现在若不亲手 报仇 流 无辜人 的血,到了 耶和华 照 所 应许你 的话赐 福 与你,立你 作 以色列 的王,那时我主 必 不致 心里不安, 觉得良心 有亏。耶和华 赐福 与我主的时候,求你记念 婢女。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, '大卫 对亚比该 说:「耶和华─以色列的 神 是应当称颂的,因为他 今 日 使 你来迎接我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, '你 和你的见识 也当称赞;因为你 今 日 拦阻我 亲手 报仇、流 人的血。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, '我指著 阻止 我加害 于 你 的耶和华─以色列 永生的 神起誓,你若 不速速地 来 迎接我,到 明日早晨,凡属拿八 的男丁 必定 不 留一个。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, '大卫 受了 亚比该 送来的 礼物,就对她 说:「 我听了 你的话,准了 你的情面,你可以平平安安地 回 家吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, '亚比该 到 拿八那里,见 他 在家里 设摆筵席,如同王 的筵席;拿八 快乐 大 醉。亚比该无论大 小 事 都没有 告诉 他,就等到 次日早晨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, '到了 早晨,拿八 醒了 酒,他的妻 将 这些 事 都告诉 他,他就魂 不附 体, 身僵如石头一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, '过了 十 天,耶和华 击打 拿八,他就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, '大卫 听见 拿八 死了,就说:「应当称颂 耶和华,因他 伸了 拿八 羞辱 我的冤,又阻止 仆人 行恶; 也使 拿八 的恶 归到 拿八的头上。」于 是大卫 打发人去,与亚比该 说,要娶她 为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, '大卫 的仆人 到了 迦密 见 亚比该, 对她 说:「大卫 打发我们 来见你,想要娶你 为妻。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, '亚比该就起来,俯伏 在地,说:「 我 情愿 作婢女,洗 我主 仆人 的脚。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, '亚比该 立刻 起身,骑 上 驴,带著 五个 使女,跟从 大卫 的使者去了,就作了 大卫 的妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, '大卫 先娶了 耶斯列人 亚希暖,她们二人 都 作了 他的 妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, '扫罗 已将 他的女儿 米甲,就是 大卫 的妻,给了 迦琳人 拉亿 的 儿子 帕提为妻。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, '西弗人 到 基比亚 见 扫罗,说:「大卫 不是 在 旷野 前 的哈基拉 山 藏著吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, '扫罗 就起身,带领 以色列 人中挑选的三 千 精 兵 下 到 西弗 的旷野,要在那里 寻索 大卫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, '扫罗 在 旷野 前 的 哈基拉 山,在 道路 上安营。大卫 住 在旷野,听说 扫罗 到 旷野 来追寻他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, ' 就打发 人去探听,便知道 扫罗 果然 来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, '大卫 起来,到 扫罗 安营 的 地方, 看见 扫罗 和他的元帅 尼珥 的儿子 押尼珥 睡卧 之 处;扫罗 睡 在辎重营里,百姓 安营 在他周围。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, '大卫 对 赫人 亚希米勒 和 洗鲁雅 的儿子 约押 的兄弟 亚比筛 说:「谁 同我 下 到 扫罗 营里去?」亚比筛 说:「我 同你 下去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, '于 是大卫 和亚比筛 夜间 到 了 百姓那里,见 扫罗 睡 在辎重营里;他的枪 在头旁,插 在地上。押尼珥 和百姓 睡 在他周围。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, '亚比筛 对 大卫 说:「现在 神 将 你的仇敌 交 在你手里, 求 你容我拿枪 将他刺透 在地,一刺就成,不用 再刺。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, '大卫 对 亚比筛 说:「不可 害死他。有 谁 伸 手 害耶和华 的受膏者 而无罪呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, '大卫 又说:「我指著永生 的耶和华起誓, 他或 被耶和华 击打,或是 死 期 到了,或是 出 战  阵亡; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, '我 在耶和华面前,万不敢 伸 手 害耶和华 的受膏者。现在 你可以 将 他头旁 的 枪 和 水 瓶 拿来,我们 就走。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, '大卫 从扫罗 的头旁 拿了 枪 和 水 瓶,二人 就走了,没有人 看见,没有人 知道,也没有人 醒起, 都 睡著了,因为 耶和华 使 他们 沉沉地睡了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, '大卫 过到 那边去,远远地 站 在 山 顶上,与他们相 离甚 远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, '大卫 呼叫 百姓 和 尼珥 的儿子 押尼珥 说:「押尼珥啊,你为何不 答应呢?」押尼珥 说:「你是 谁?竟敢呼叫 王呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, '大卫 对 押尼珥 说:「你 不是 个勇士吗?以色列中 谁 能比你呢? 民 中有人 进来 要害死 王─你的主,你为何 没有 保护 王─你的主呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, '你这样 是不 好的!我指著永生 的耶和华起誓, 你们 都是该 死的;因为 没有 保护 你们的主,就是 耶和华 的受膏者。现在 你看看 王 头旁 的 枪 和 水 瓶 在哪里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, '扫罗 听出 是 大卫 的声音,就说:「我儿 大卫,这是 你的声音吗?」大卫 说:「主─我的王啊,是我的声音」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, '又说:「 我做了 什么?我手里 有什么 恶事?我主 竟 追赶 仆人呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, ' 求 我主 我王 听 仆人 的话:若是 耶和华 激发你 攻击我,愿 耶和华收纳 祭物;若是 人激发你,愿 他 在耶和华 面前 受咒诅;因为 他现今 赶逐我,不容我在耶和华 的产业上 有分,说:『你去 事奉 别 神吧!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, '现在 求王不要 使我的血 流 在离 耶和华 远的地方。 以色列 王 出来 是寻找 一个 虼蚤,如同 人在山上 猎取 一个鹧鸪一般。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, '扫罗 说:「我有罪了!我儿 大卫,你可以回来,因 你今 日 看 我的性命 为宝贵;我必 不 再 加害 于 你。 我是糊涂人,大大 错了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, '大卫 说:「王 的枪 在这里,可以吩咐一个 仆人 过来 拿去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, '今日 耶和华 将王交 在我手里,我却不 肯 伸 手 害耶和华 的受膏者。耶和华必照各人的 公义 诚实 报应 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, ' 我 今 日 重看 你的性命,愿 耶和华 也 重看 我的性命,并且拯救我 脱离一切 患难。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, '扫罗 对 大卫 说:「我儿 大卫,愿 你 得福!你必 做 大事,也 必 得胜。」于 是大卫 起行,扫罗 回 他的本处去了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, '大卫 心里 说:「必有 一 日 我死 在扫罗 手里,不 如 逃奔 非利士 地去。扫罗 见我不在 以色列的 境内,就必绝望,不再 寻索我;这样我可以脱离 他的手。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, '于 是大卫 起身, 和跟随他的 六 百 人 投奔 迦特 王─玛俄 的儿子 亚吉去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, '大卫 和他的两个 妻,就是耶斯列人 亚希暖 和作过拿八 妻 的迦密人 亚比该,并跟随他的人,连各人 的眷属, 都住 在 迦特 的亚吉那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, '有人告诉 扫罗 说:「大卫 逃到 迦特。」扫罗就不 再 寻索他了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, '大卫 对 亚吉 说:「我若 在你眼前 蒙 恩,求 你在京外 的城邑 中赐 我 一个 地方 居住。仆人 何必 与王同 住 京 都呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, '当 日 亚吉 将 洗革拉 赐 给他,因此 洗革拉 属 犹大 王,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, ' 大卫 在非利士 地 住了 一年 零四个 月。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, '大卫 和跟随他的人 上去,侵夺 基述人、基色人、亚玛力人之地。 这 几族 历来 住在 那地,从 书珥 直到 埃及。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, '大卫 击杀 那地的人,无论男 女 都没有 留下一个,又夺获 牛、羊、骆驼、驴,并衣服,回 来 见 亚吉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, '亚吉 说:「你们今日 侵夺了 什么地方呢?」大卫 说:「侵夺了 犹大 的南方、 耶拉篾 的南方、 基尼 的南方。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, '无论男 女,大卫 没有 留下 一个带到 迦特来。他说:「恐怕 他们将我们的事 告诉人,说 大卫 住在 非利士 地 的 时候 常常 这样 行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, '亚吉 信了 大卫,心里说:「大卫使本族 以色列人 憎恶他,所以他必永远 作 我的 仆人了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, ' 那 时,非利士人 聚集 军旅,要与以色列人 打仗。亚吉 对 大卫 说:「你当 知道, 你 和跟随你的人 都要随我 出 战 。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, '大卫 对 亚吉 说:「 仆人 所 能做的事,王 必 知道。」亚吉 对 大卫 说:「这样,我立 你永远 作我的护卫 长。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, '那时撒母耳 已经死了,以色列众 人 为他 哀哭,葬他 在拉玛,就是在他本城里。扫罗 曾在国内 不容有 交鬼的 和 行巫术的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, '非利士人 聚集,来 到书念 安营;扫罗 聚集 以色列众 人 在基利波 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, '扫罗 看见 非利士 的军旅 就惧怕,心中 发颤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, '扫罗 求问 耶和华,耶和华 却不 藉 借梦,或 乌陵,或 先知 回答他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, '扫罗 吩咐臣仆 说:「当为我 找 一个交鬼 的妇人,我好去 问 她。」臣仆 说:「在隐‧多珥 有一个交鬼 的妇人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, '于 是扫罗 改了装,穿上 别的 衣服, 带著 两个 人,夜里 去 见 那妇人。扫罗说:「求 你用交鬼 的法术,将 我所 告诉 你的死人,为我 招上来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, '妇人 对他 说:「 你 知道 扫罗 从 国中 剪除 交鬼 的和 行巫术的。你 为何 陷害 我的性命,使我死呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, '扫罗 向妇人 指著耶和华 起誓 说:「我指著永生 的耶和华起誓,你必 不因这 事 受 刑。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, '妇人 说:「我为你招 谁 上来呢?」回答说:「为我招 撒母耳 上来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, '妇人 看见 撒母耳,就大 声 呼叫, 对 扫罗 说:「你是 扫罗,为什么 欺哄我呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, '王 对妇人 说:「不要 惧怕, 你看见了 什么呢?」妇人 对 扫罗 说:「我看见 有神 从 地里 上来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, '扫罗 说:「他是怎样 的形状?」妇人说:「有一个老 人 上来, 身穿 长衣。」扫罗 知道 是 撒母耳,就屈身,脸 伏于 地 下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, '撒母耳 对 扫罗 说:「你为什么 搅扰我,招我 上来呢?」扫罗 回答说:「我 甚 窘急;因为非利士人 攻击 我, 神 也离开  我,不 再 藉 借 先知 或 梦 回答我。因此请 你上来,好指示我 应当怎样 行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, '撒母耳 说:「耶和华 已经离开  你,且与你为 敌,你何必 问我呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, '耶和华 照 他 藉 借我 说 的话, 已经从你手里 夺去 国权,赐 与别人,就是大卫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, '因 你没有 听从 耶和华 的命令;他恼怒 亚玛力人,你没有 灭绝他们,所以 今 日 耶和华 向你 这样 行, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, '并且 耶和华 必将 你和 以色列人 交 在非利士人 的手里。明日 你 和你众子 必与我在一处了; 耶和华 必将 以色列 的军兵 交 在非利士人 手里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, '扫罗 猛然 仆倒,挺身 在地,因撒母耳 的话 甚是 惧怕;那一 昼 一 夜,没有 吃 什么,就 毫无 气力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, '妇人 到 扫罗面前,见 他极其 惊恐,对他 说:「 婢女 听从 你的话,不顾惜 自己的 性命,遵从 你所 吩咐 的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, '现在 求 你 听 婢女 的话,容我在你面前 摆上 一点 食物,你吃了,可以 有 气力 行 路。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, '扫罗不肯,说:「我不 吃。」但他的仆人 和 妇人 再三劝 他,他才听了 他们的话,从地上 起来,坐 在 床上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, '妇人 急忙 将家里 的一只肥 牛犊 宰了,又拿 面 麺 抟成 无酵饼 烤了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, '摆在 扫罗 和他仆人 面前。他们吃完,当 夜 就起身 走了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, '非利士人 将 他们的军旅 聚 到亚弗;以色列人 在耶斯列 的 泉 旁安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, '非利士人 的首领各率军队,或百 或千,挨次前进;大卫 和跟随他的人 同著 亚吉 跟 在后边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, '非利士人 的首领 说:「这些 希伯来人 在这里做什么呢?」亚吉 对 他们 说:「这 不是 以色列 王 扫罗 的臣子 大卫吗?他 在 我这里 有些 年 日了。自从 他投降 我直到 今 日,我未 曾见 他 有过错。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, '非利士人 的首领 向亚吉 发怒, 对他 说:「你要 叫 这人 回 你所 安置他的 地方,不可 叫他同我们 出 战 ,恐怕 他在阵上 反为 我们的 敌人。他 用什么 与 他主人 复和呢?岂不是 用我们这些 人 的首级吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, '从前以色列的妇女跳舞 唱和 说:『扫罗 杀死 千千,大卫 杀死万万』,所 说的 不是 这个 大卫吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, '亚吉 叫 大卫来,对他 说:「我指著永生 的耶和华起誓, 你是 正直人。你随我 在军中 出 入,我看 你甚好。自从 你投奔 我 到 如 今,我未 曾见 你 有什么过失;只是众首领 不 喜悦 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, '现在 你可以平平安安地 回 去,免得非利士人 的首领 不 欢喜你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, '大卫 对 亚吉 说:「 我做了 什么呢?自从 仆人 到 你面前,直到 今 日,你查出 我 有什么过错, 使我不 去 攻击 主─我王 的仇敌呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, '亚吉 说:「我知道 你 在我眼前 是好人,如同 神 的使者一般;只是 非利士人 的首领 说:『这人不可 同我们 出 战 。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, '故此 你和跟随 你的人,就是 你本主 的仆人,要明日早晨 起来,等到天 亮 回去吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, '于 是大卫和 跟随他的人 早晨 起来,回 往 非利士 地 去。非利士人 也上 耶斯列去了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, ' 第三 日,大卫 和跟随他的人 到了 洗革拉。亚玛力人 已经侵夺 南地,攻破 洗革拉,用火 焚烧, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, '掳了 城内的妇女 和 其中的 大 小人口,却没有 杀 一个,都带著 走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, '大卫 和跟随他的人 到了 那城,不料,城已烧毁,他们的妻子 儿 女 都被掳去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, '大卫 和 跟随他 的人 就放 声 大哭,直 哭得 没有 气力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, '大卫 的两个 妻─耶斯列人 亚希暖 和作过拿八 妻 的迦密人 亚比该,也被掳去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, '大卫 甚是 焦急,因 众 人 为 自己的 儿 女 苦恼,说:「 要用石头打死他。」大卫 却倚靠耶和华─他的 神,心里坚固。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, '大卫 对 亚希米勒 的儿子 祭司 亚比亚他 说:「请 你将以弗得 拿过来。」亚比亚他 就将 以弗得 拿 到 大卫面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, '大卫 求问 耶和华 说:「我追赶 敌军,追得上追不上呢?」耶和华说:「你可以追, 必 追得上,都 救得回来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, '于 是,大卫和 跟随他 的六 百 人 来 到 比梭 溪;有不能前去的 就留在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, '大卫 却 带著四 百 人 往前追赶,有二百 人 疲乏,不能过 比梭 溪,所以留在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, '这四百人在田野 遇见 一个埃及 人,就带 他 到 大卫面前,给 他 饼 吃,给他水 喝, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, '又给 他 一块 无花果饼,两个 葡萄饼。他吃了,就精神 复原;因为 他三 日 三 夜 没有 吃 饼,没有 喝 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, '大卫 问他 说:「你是 属谁的?你是 哪里的人?」他回答说:「我是 埃及 的少年人,是亚玛力 人 的奴仆;因 我三 日 前患病,我主人 就把我撇弃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, '我们 侵夺了 基利提 的南方 和 属 犹大的地,并 迦勒地 的南方,又用火 烧了 洗革拉。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, '大卫 问他 说:「你肯领我们 到 敌军 那里不肯?」他回答说:「你要向我指著 神 起誓,不 杀我,也不 将我交 在我主人 手里,我就领你下 到 敌军 那里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, '那人领大卫下去,见 他们散 在 地 上,吃 喝 跳舞,因为 从非利士 地 和犹大 地 所 掳来 的财物 甚多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, '大卫 从黎明 直到 次日 晚上,击杀他们,除了 四 百 骑 骆驼 的 少年 人之外,没有 一个 逃脱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, ' 亚玛力人 所 掳去的财物,大卫 全都 夺回, 并救回 他的两个 妻来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, ' 凡 亚玛力人 所 掳去的,无论 大 小、 儿 女、财物,大卫 都 夺回来,没有 失落一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, '大卫 所夺来的 牛群 羊群,跟随他的人赶在 原有的 群畜 前边,说:「这是 大卫 的掠物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, '大卫 到了 那 疲乏 不能跟随、留在 比梭 溪 的二百 人那里。他们出来 迎接 大卫并 跟随的人。大卫 前来 问 他们 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, ' 跟随 大卫 人中的 恶 人 和匪类 说:「这些人既然 没有 和我们 同去,我们所 夺的 财物 就不 分给 他们,只 将 他们各人 的妻子 儿女给他们,使他们带 去就是了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, '大卫 说:「弟兄们, 耶和华 所 赐 给我们的,不可 不分给他们;因为他保佑 我们,将 那攻击 我们 的敌军 交 在我们手里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, '这 事 谁 肯依从 你们呢? 上 阵 的得多少,看守 器具 的也得多少;应当大家平 分。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, '大卫定 此为以色列 的律例 典章, 从那 日 直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, '大卫 到了 洗革拉,从掠物中 取些送 给他朋友 犹大 的长老,说:「这是 从耶和华 仇敌 那里夺来的,送你们 为礼物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, '他送礼物给 住伯特利的, 南地 拉末的, 雅提珥的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, ' 住亚罗珥的, 息末的, 以实提莫的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, ' 住拉哈勒的, 耶拉篾 各城的, 基尼 各城的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, ' 住何珥玛的, 歌拉珊的, 亚挞的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, ' 住希伯仑 的,并 大卫 和 跟随他的人 素来所 到 之处的人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, '非利士人 与以色列人 争战 。以色列 人 在非利士人 面前 逃跑,在 基利波 有被杀 仆倒的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, '非利士人 紧追 扫罗 和 他儿子们, 就杀了 扫罗 的儿子 约拿单、 亚比拿达、 麦基舒亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, '势派 甚大, 扫罗 被弓箭 手 追上,射伤 甚重, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, ' 就吩咐 拿 他兵器的人说:「你拔出 刀来,将我刺死,免得 那些 未受割礼的人 来 刺我,凌辱 我。」但拿 兵器的人 甚 惧怕,不 肯刺他;扫罗 就自己 伏 在 刀上死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, '拿 兵器 的人见 扫罗 已死,也 伏 在 刀 上死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, '这样,扫罗 和他三个 儿子,与拿 他兵器的人,以及 跟随他的人, 都 一同 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, ' 住平原 那边 并 约旦河 西 的以色列 人,见 以色列 军兵 逃跑, 扫罗 和他儿子 都死了,也就弃 城 逃跑。非利士人 便来 住 在其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, ' 次日,非利士人 来 剥 那被杀之人的衣服,看见 扫罗 和 他三个 儿子 仆倒 在基利波 山, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, '就割下 他的首级,剥了 他的军装,打发人到(或译:送到)非利士 地 的四境,报信 与他们庙里 的偶像 和 众民; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, '又将 扫罗的军装 放在 亚斯她录 庙里,将 他的尸身 钉在伯‧珊 的城墙上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, ' 基列‧雅比 的居民 听见 非利士人 向扫罗 所 行的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, '他们中间所有的 勇 士 就起身,走了 一 夜,将 扫罗 和 他儿子 的尸身从伯‧珊 城墙上 取下来,送到 雅比 那里,用火烧了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, ' 将 他们骸骨 葬 在雅比 的垂丝柳树 下,就禁食 七 日。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, ' 扫罗 死 后,大卫 击杀 亚玛力人 回来, 在洗革拉 住了 两 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, ' 第三 天, 有一人 从 扫罗 的营 里出来,衣服 撕裂, 头 蒙灰尘, 到 大卫 面前伏 地 叩拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, '大卫 问他 说:「你从 哪里 来?」他说:「我从以色列 的营 里逃来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, '大卫 又问他 说:「 事情 怎样?请你 告诉 我。」他回答说:「百姓 从 阵 上逃跑,也 有许多 人 仆倒 死亡;扫罗 和他儿子 约拿单 也 死了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, '大卫 问 报信的 少年人 说:「你怎么 知道 扫罗 和他儿子 约拿单 死了呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, '报信的 少年人 说:「我偶然 到 基利波 山,看见 扫罗 伏 在 自己枪上, 有战 车、马 兵 紧紧地追他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, '他回头 看见我,就呼叫 我。我说:『我在这里。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, '他问我 说:『你 是什么人?』我说:『我是 亚玛力人。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, '他说:『请你 来,将我杀死;因为 痛苦 抓住我, 我的生命 尚 存。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, '我准 知 他 仆倒 必不能 活,就去 将他杀死,把他头 上 的 冠冕、臂 上 的 镯子 拿 到 我主 这里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, '大卫 就 撕裂 衣服, 跟随他 的人 也是如此, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, '而且悲哀 哭号,禁食 到 晚上,是因 扫罗 和 他儿子 约拿单,并 耶和华 的民 以色列 家的人, 倒 在刀下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, '大卫 问 报信的 少年人 说:「你 是 哪里的人?」他说:「我是 亚玛力 客 人 的儿子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, '大卫 说:「你伸 手 杀害 耶和华 的受膏者,怎么 不 畏惧呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, '大卫 叫了 一个 少年人来,说:「你去 杀 他吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, '大卫 对他 说:「你流人血 的罪归到 自己的头上,因为 你亲口 作见证 说:『我 杀了 耶和华 的受膏者。』」少年人就把他杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, '大卫 作 哀歌,吊 扫罗 和 他儿子 约拿单, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, '且吩咐 将这歌教导 犹大 人。这歌名叫「弓歌」, 写 在 雅煞珥 书上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, '歌中说:以色列啊,你尊荣者 在 山上 被杀!大英雄 何竟 死亡! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, '不要 在迦特 报告;不要 在亚实基伦 街上 传扬;免得 非利士 的女子 欢乐;免得 未受割礼 之人的女子 矜夸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, '基利波 山哪,愿 你那里 没有 雨 露!愿 你 田地 无 土产可作供物!因为 英雄 的盾牌 在那里 被污丢弃;扫罗 的盾牌 仿佛未曾 抹 油。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, '约拿单 的弓箭 非流敌人 的血 不 退缩;扫罗 的刀剑 非剖勇士 的油 不 收回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, '扫罗 和约拿单─活时 相悦 相爱,死时 也不 分离─他们比鹰 更快,比狮子 还强。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, '以色列 的女子啊,当为 扫罗 哭号!他曾使你们穿 朱红色 的美衣,使 你们衣服 有 黄金 的妆饰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, '英雄 何竟 在阵 上 仆倒!约拿单 何竟在 山上 被杀! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, '我兄 约拿单哪,我 为你 悲伤!我 甚 喜悦你!你向我 发的爱情 奇妙非常,过于 妇女 的爱情。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, '英雄 何竟 仆倒!战  具 何竟灭没!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, ' 此后,大卫 问 耶和华 说:「我上 犹大 的一个 城去可以吗?」耶和华 说:「可以。」大卫 说:「我上 哪一个城去呢?」耶和华说:「上希伯仑 去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, '于 是大卫 和 他的两个 妻─一个是耶斯列人 亚希暖,一个是作过迦密人 拿八 妻 的亚比该─都上 那里去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, '大卫 也将 跟随他 的人 和他们各人 的眷属 一同带上去,住 在希伯仑  的城邑中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, '犹大 人 来到 希伯仑 ,在那里 膏 大卫 作 犹大 家 的王。有人告诉 大卫 说:「葬埋 扫罗 的是 基列‧雅比 人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, '大卫 就差 人 去见 基列‧雅比 人,对他们 说:「你们厚 待 你们的主─ 扫罗,将他 葬埋。愿 耶和华 赐福 与你们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, '你们既 行了 这事, 愿 耶和华 以慈爱 诚实 待 你们,我 也 要为此 厚 待 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, '现在 你们的主─扫罗 死了, 犹大 家 已经膏 我 作他们 的王,所以你们 要刚强 奋勇。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, ' 扫罗的 元帅 尼珥 的儿子 押尼珥,曾将 扫罗 的儿子 伊施波设 带 过河,到玛哈念, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, '立他作王,治理 基列、 亚书利、 耶斯列、 以法莲、 便雅悯,和 以色列 众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, '扫罗 的儿子 伊施波设 登基 的时候年 四十 岁,作 以色列 王 二 年;惟独 犹大 家 归 从 大卫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, ' 大卫 在希伯仑  作 犹大 家 的王,共 七 年 零六个 月。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, '尼珥 的儿子 押尼珥 和扫罗 的儿子 伊施波设 的仆人 从玛哈念 出来,往基遍去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, '洗鲁雅 的儿子 约押 和大卫 的仆人 也出来,在 基遍 池 旁与他们相 遇;一班 坐 在 池 这边,一班 坐在 池 那边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, '押尼珥 对 约押 说:「让 少年人 起来,在我们面前 戏耍吧!」约押 说:「可以。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, '就按著定数 起来:属扫罗 儿子 伊施波设 的便雅悯人 过去 十 二名,大卫 的仆人 也过去十 二名, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, '彼此 揪 头,用刀 刺肋,一同 仆倒。所以,那 地 叫作希利甲‧哈素林,就 在基遍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, '那 日 的战 事 凶 猛,押尼珥 和以色列 人 败 在大卫 的仆人 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, '在那里 有 洗鲁雅 的三个 儿子:约押、亚比筛、亚撒黑。亚撒黑 脚 快如 野鹿一般; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, '亚撒黑 追 赶 押尼珥,直追 赶 他 不 偏 左 右。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, '押尼珥 回头 说:「你 是 亚撒黑吗?」回答说:「是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, '押尼珥 对他 说:「你或 转 向 左 转向 右,拿住 一个 少年人,剥去 他的战 衣。」亚撒黑 却不 肯 转开  不追赶他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, '押尼珥 又 对 亚撒黑 说:「你 转开  不追赶我吧!我何必 杀你呢?若杀你,有什么 脸 见 你哥哥 约押呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, '亚撒黑仍不肯 转开 。故此,押尼珥 就用枪 𨱔 刺 入 他的肚腹,甚至枪 从背后 透出,亚撒黑 就在那里 仆倒 而 死。 众人 赶 到 亚撒黑 仆倒 而死 的 地方,就都站住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, '约押 和亚比筛 追 赶 押尼珥,日 落的时候, 到了 通基遍 旷野 的路旁,基亚 对 面 的 亚玛 山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, '便雅悯 人 聚集,跟随 押尼珥 站 在 一个 山 顶上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, '押尼珥 呼叫 约押 说:「刀剑 岂可永远 杀人吗?你岂不 知 终久 必有 苦楚吗?你要等 何时 才 叫 百姓 回去、不追赶 弟兄呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, '约押 说:「我指著永生的 神起誓: 你若不 说戏耍的那句话, 今日早晨 百姓 就回去, 不追赶 弟兄了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, '于 是约押 吹 角,众 民 就站住,不 再 追 赶 以色列人,也不 再 打仗了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, '押尼珥 和跟随他的人 整 夜 经过 亚拉巴,过 约旦河,走过 毕伦,到了 玛哈念。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, '约押 追赶 押尼珥 回来,聚集 众 民,见大卫 的仆人 中缺少了 十 九 个人 和亚撒黑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, '但大卫 的仆人 杀了 便雅悯人 和跟随押尼珥 的人,共三 百 六十 名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, '众人将 亚撒黑 送到 伯利恒, 葬 在他父亲 的坟墓里。约押 和跟随他的人 走了 一 夜,天亮的时候 到了希伯仑 。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, ' 扫罗 家 和 大卫 家 争战  许久。大卫 家日见 强盛;扫罗 家 日见 衰弱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, '大卫 在希伯仑  得了 几个儿子:长子 暗嫩 是 耶斯列人 亚希暖所生的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, '次子 基利押(在历代上三章一节作但以利)是作过迦密人 拿八 的妻 亚比该所生的;三子 押沙龙 是基述 王 达买  的女儿 玛迦 所生的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, '四 子 亚多尼雅 是哈及 所生的;五 子 示法提雅 是亚比她 所生的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, '六 子以特念 是大卫 的妻 以格拉所生的。大卫 这 六个儿子 都是在希伯仑  生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, ' 扫罗 家 和 大卫 家 争战 的时候,押尼珥 在扫罗 家 大有 权势。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, '扫罗 有一妃嫔,名 叫利斯巴,是爱亚 的女儿。一日,伊施波设对 押尼珥 说:「你为什么 与 我父 的妃嫔 同房呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, '押尼珥 因 伊施波设 的话 就甚 发怒,说:「我 岂是 犹大的 狗 头呢? 我恩 待 你父 扫罗 的家 和 他的弟兄、 朋友,不 将你交 在大卫 手里,今日 你竟为 这妇人 责备 我吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, '我若 不照著 耶和华 起誓 应许大卫的话 行,废去 扫罗 的位,建立 大卫 的位,使他治理 以色列 和 犹大,从但 直到 别是巴,愿  神 重重地 降 罚 与我!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, '伊施波设惧怕 押尼珥,不 敢 回答 一句。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, '押尼珥 打发 人 去见 大卫,替他 说:「这国 归谁呢?」又说:「你与我 立 约, 我 必帮助你,使 以色列 人都 归服 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, '大卫说:「好!我 与你 立 约。但 有一 件,你来 见 我面的时候,若不 将 扫罗 的女儿 米甲 带来,必不得 见 我的面。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, '大卫 就打发 人 去见 扫罗 的儿子 伊施波设,说:「你要将 我的妻 米甲 归还我;她是 我从前用一百 非利士人 的阳皮 所聘定的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, '伊施波设 就打发人去,将米甲从 拉亿 的儿子、她丈夫 帕铁 那里接回来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, '米甲的丈夫 跟著 她,一面走 一面哭,直跟 到 巴户琳。押尼珥 说:「你回 去吧!」帕铁就回去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, '押尼珥 对 以色列 长老 说:「 从 前 你们 愿 意 大卫 作王 治理你们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, '现在 你们可以照心愿 而行。因为 耶和华 曾论 到 大卫 说:『我必藉 借我仆人 大卫 的手,救 我民 以色列 脱离 非利士人 和众 仇敌 的手。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, '押尼珥 也 用这话说 给便雅悯人 听, 又 到 希伯仑 ,将 以色列人和 便雅悯 全 家 一切 所 喜悦 的事说 给大卫 听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, '押尼珥 带著 二十个 人 来 到希伯仑  见 大卫,大卫 就为押尼珥和 他带来 的人 设摆 筵席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, '押尼珥 对 大卫 说:「我要起身 去 招聚 以色列 众人 来见 我主 我王,与你 立 约,你就可以照著 心 愿  作王。」于 是大卫 送 押尼珥去,押尼珥就平平安安地 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, ' 约押 和大卫 的仆人 攻击 敌军,带回 许多的 掠物。那时押尼珥 不 在希伯仑  大卫 那里,因 大卫已经送他去,他也平平安安地 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, '约押 和 跟随他 的全 军 到了,就有人告诉 约押 说:「尼珥 的儿子 押尼珥 来 见 王,王送他去,他也平平安安地 去了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, '约押 去 见 王 说:「你这是做 什么呢? 押尼珥 来 见你,你为何 送他去,他就踪影 不见了呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, '你当晓得, 尼珥 的儿子 押尼珥 来 是要 诓哄你,要知道 你的出 入和 你 一切 所 行的事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, '约押 从 大卫 那里出来,就打发 人 去追赶 押尼珥,在西拉 井追上他,将他 带回来,大卫 却不 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, '押尼珥 回到 希伯仑 ,约押 领他 到 城门 的瓮洞,假作要与他 说 机密话,就在那里 刺透 他的肚腹,他便死了。这是报杀他兄弟 亚撒黑的仇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, ' 大卫 听见了,就说:「流尼珥 的儿子 押尼珥 的血,这罪在 耶和华 面前必永 不归 我 和我的国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, '愿 流他血的罪归 到 约押 头上 和 他父 的全 家;又愿 约押 家 不 断有 患漏症的,长大痲疯的,架 拐而行的,被刀 杀死的,缺乏 饮食的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, '约押 和他兄弟 亚比筛 杀了 押尼珥,是因 押尼珥 在基遍 争战  的时候杀了 他们的兄弟 亚撒黑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, '大卫 吩咐 约押 和 跟随他 的众 人 说:「你们当撕裂 衣服,腰束 麻布,在押尼珥 棺前 哀哭。」大卫 王 也跟 在棺 后。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, '他们将 押尼珥 葬 在希伯仑 。王 在 押尼珥 的墓 旁放 声 而哭,众 民 也都哭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, '王 为 押尼珥 举哀,说:押尼珥 何竟像愚顽人 死呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, '你手 未 曾捆绑,脚 未 曾锁住。你死,如人死 在 罪孽 之辈手下一样。于 是众 民 又 为押尼珥 哀哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, '日头 未落的时候,众 民 来 劝 大卫 吃饭,但大卫 起誓 说:「我若 在日头 未落 以前 吃 饭,或 吃别物,愿  神 重重地 降 罚 与我!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, '众 民 知道了 就都喜悦。凡 王 所 行的,众 民无不喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, '那 日, 以色列 众 民 才知道 杀 尼珥 的儿子 押尼珥 并非 出于 王意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, '王 对 臣仆 说:「你们岂不 知 今 日 以色列 人中死了 一个作元帅 的大丈夫吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, '我 虽然受膏 为王,今日 还是软弱;这 洗鲁雅 的两个儿子 比我 刚强。愿 耶和华 照著恶人 所行 的恶 报应他。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, '扫罗 的儿子 伊施波设听见 押尼珥 死 在希伯仑 ,手 就发软;以色列 众人 也都惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, '扫罗 的儿子 伊施波设有 两 个 军 长,一 名 巴拿,一 名 利甲,是便雅悯支派、比录人 临门 的儿子。 比录 也 属 便雅悯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, '比录人 早先逃到 基他音,在那里 寄居,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, '扫罗 的儿子 约拿单 有一个儿子 名叫 米非波设,是瘸 腿的。扫罗 和约拿单 死亡的消息 从耶斯列 传到的时候,他 才五 岁。他乳母 抱著他 逃跑; 因为跑得 太急,孩子掉在地上,腿就瘸了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, '一日,比录人 临门 的两个儿子 利甲 和巴拿 出去,约在午热 的时候 到了 伊施波设 的家;伊施波设 正睡 午 觉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, ' 他们进了 房子,假作要取 麦子,就刺透 伊施波设的 肚腹, 逃跑了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, '他们进 房子的时候,伊施波设 正在卧 房 里躺 在 床上,他们将他杀 死,割了 他的首级,拿著 首级 在亚拉巴 走了 一 夜, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, '将 伊施波设 的首级 拿到 希伯仑  见 大卫 王,说:「王的仇敌 扫罗 曾寻索 王的性命。看哪,这是他儿子 伊施波设 的首级;耶和华 今 日 为我主 我王 在扫罗 和他后裔 的身上报了 仇。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, '大卫 对 比录人 临门 的儿子 利甲 和 他兄弟 巴拿 说:「我指著救 我性命 脱离一切 苦难、 永生 的耶和华起誓: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, ' 从前有人报告 我 说, 扫罗 死了,他 自 以为 报好消息;我就拿住 他,将他杀 在洗革拉,这 就作了 他 报消息的赏赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, '何况 恶 人 将 义 人 杀 在 他的床上, 我岂不 向你们 讨 流他血的罪、从 世上 除灭 你们呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, '于 是大卫 吩咐 少年人 将他们杀了,砍断 他们的手 脚,挂 在 希伯仑  的池旁,却 将 伊施波设 的首级 葬 在希伯仑  押尼珥 的坟墓里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, '以色列 众 支派 来 到希伯仑  见 大卫, 说:「 我们 原是你的骨 肉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, ' 从前 扫罗 作 我们 王的时候,率领 以色列 人出 入 的是 你;耶和华 也曾应许你 说:『你 必牧养 我的民 以色列, 作 以色列 的君。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, '于 是以色列 的长老 都 来 到 希伯仑  见大卫 王,大卫 在希伯仑  耶和华 面前 与他们 立 约,他们就膏 大卫 作 以色列 的王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, '大卫 登基 的时候年 三十 岁,在位 四十 年; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, '在希伯仑  作 犹大 王 七 年 零六个 月,在耶路撒冷 作 以色列 和犹大 王 三十 三 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, '大卫 和跟随他的人 到了 耶路撒冷,要攻打 住 那地方的耶布斯人。耶布斯人 对大卫 说:「你若不 赶出 瞎子、瘸子,必不能 进 这地方」;心里想 大卫 决不能 进去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, '然而大卫 攻取 锡安 的保障,就是 大卫 的城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, '当 日,大卫 说:「谁 攻打 耶布斯人,当上 水沟 攻打我 心里 所恨恶的 瘸子、 瞎子。」从 此 有俗语说:「在那里有瞎子、瘸子,他不能 进 屋去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, '大卫 住 在保障里,给保障 起名叫 大卫 城。大卫 又从 米罗 以里,周围 筑墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, '大卫 日见 强盛,因为耶和华─万军之 神 与他同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, '泰尔 王 希兰 将香柏 木 运到 大卫那里,又差遣 使者 和木匠、石匠 给大卫 建造 宫殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, '大卫 就知道 耶和华 坚立他 作 以色列 王,又 为 自己的民 以色列 使他的国 兴旺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, '大卫 离开  希伯仑  之后,在耶路撒冷 又 立 后 妃,又 生 儿 女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, '在耶路撒冷 所生的儿子是 沙母亚、朔罢、拿单、所罗门、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, '益辖、以利书亚、尼斐、雅非亚、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, '以利沙玛、以利雅大、以利法列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, '非利士人 听见 人膏 大卫 作 以色列 王,非利士 众人 就上来 寻索 大卫;大卫 听见,就下 到 保障。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, '非利士人 来了,布散 在利乏音 谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, '大卫 求问 耶和华 说:「我可以上去 攻打 非利士人吗?你将他们交 在我手里吗?」耶和华 说:「你可以上去, 我必 将 非利士人 交 在你手里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, '大卫 来到巴力‧毘拉心, 在那里 击杀非利士人,说:「耶和华 在我面前 冲破 敌人,如同水 冲去一般。」因 此 称 那 地方 为巴力‧毘拉心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, '非利士人将 偶像 撇 在那里,大卫 和跟随他的人 拿去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, '非利士人 又 上来,布散 在利乏音 谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, '大卫 求问 耶和华;耶和华说:「不要 一直地上去,要转 到 他们后头,从桑林 对面 攻打 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, ' 你听见 桑树 梢上 有脚步 的声音,就要 急速前去,因为 那时 耶和华 已经在你前头 去 攻打 非利士人 的军队。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, '大卫 就遵著 耶和华 所 吩咐 的去行,攻打 非利士人,从迦巴 直 到 基色。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, '大卫 又 聚集 以色列 中所有 挑选 的人三万。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, '大卫 起身,率领 跟随他 的众 人 前往,要从巴拉‧犹大 将 神 的约柜 运来;这约柜 就是 坐 在 二基路伯 上万军 之耶和华 留名的约柜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, '他们将 神 的约柜 从冈上 亚比拿达 的家 里抬出来,放 在 新 车上;亚比拿达 的两个儿子 乌撒 和亚希约 赶 这新 车。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, '他们将 神 的约柜 从冈上 亚比拿达 家 里抬出来的时候,亚希约 在柜 前 行走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, '大卫 和以色列 的全 家 在耶和华 面前,用松 木 制造的各样 乐器和琴、瑟、鼓、钹、锣,作乐跳舞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, '到了 拿艮 的禾场,因为 牛失前蹄(或译:惊跳),乌撒 就伸手 扶住 神 的约柜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, '神 耶和华 向乌撒 发 怒,因 这错误 击杀他,他就死 在 神 的约柜旁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, '大卫 因 耶和华 击杀(原文是闯杀)乌撒,心里愁烦,就称 那 地方为毘列斯‧乌撒,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, '那 日,大卫 惧怕 耶和华,说:「耶和华 的约柜 怎可 运到我这里 来?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, '于 是大卫 不 肯 将 耶和华 的约柜 运 进 大卫 的城, 却运 到 迦特人俄别‧以东 的家中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, '耶和华 的约柜 在 迦特人俄别‧以东 家中 三个 月;耶和华 赐福 给俄别‧以东 和 他的全 家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, '有人告诉 大卫 王 说:「耶和华 因为 约柜 赐福 给俄别‧以东 的家 和 一切 属他的。」大卫 就去,欢欢喜喜地 将 神 的约柜从俄别‧以东 家中 抬 到大卫 的城里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, ' 抬 耶和华 约柜 的人走了 六 步,大卫就献 牛 与肥羊为祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, '大卫 穿著 细麻布 的以弗得, 在耶和华 面前 极 力 跳舞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, '这样,大卫 和以色列 的全 家 欢呼 吹 角,将 耶和华 的约柜 抬上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, ' 耶和华 的约柜 进 了大卫 城的时候,扫罗 的女儿 米甲 从 窗户里 观看,见 大卫 王 在耶和华 面前 踊跃 跳舞,心里 就轻视 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, '众人将 耶和华 的约柜 请进去,安放 在所预备的地方,就是 在大卫 所搭 的帐幕 里。大卫 在耶和华 面前 献 燔祭 和平安祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, '大卫 献 完了 燔祭 和平安祭,就奉万军 之耶和华 的名 给 民 祝福, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, '并且分 给 以色列 众 人,无论男 女,每人 一 个 饼,一 块肉,一个 葡萄饼;众 人 就各 回 各家去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, '大卫 回 家要给 眷属 祝福;扫罗 的女儿 米甲 出来 迎接 他,说:「以色列 王 今日 在臣仆 的婢女 眼前 露体, 如同一个 轻贱人 无耻 露体一样, 有好大的 荣耀啊!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, '大卫 对 米甲 说:「这是在耶和华 面前;耶和华 已拣选 我,废了你父 和你父的全 家,立 我 作 耶和华 民 以色列 的君,所以我必在耶和华 面前 跳舞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, '我也必 更加 卑微,自己看 为 轻贱。你所 说的那些 婢女,她们 倒要尊敬我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, '扫罗 的女儿 米甲,直到 死 日,没 有 生养儿女。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, ' 王 住 在自己宫中,耶和华 使他 安靖,不被四围的 仇敌扰乱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, '那时,王 对 先知 拿单 说:「看哪,我 住 在香柏木 的宫中, 神 的约柜 反在 幔子 里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, '拿单 对 王 说:「你可以照 你的心意 而 行,因为 耶和华 与你同在。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, ' 当 夜,耶和华 的话 临 到 拿单 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, '「你去 告诉 我仆人 大卫,说 耶和华 如此说:『你 岂可建造 殿宇 给我 居住呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, '自从 我领 以色列 人 出埃及 直到 今 日, 我未 曾住过 殿宇,常 在会幕 和帐幕 中行走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, '凡 我同以色列 人 所 走的地方,我何 曾 向 以色列 一 支派的士师,就是 我吩咐 牧养 我民 以色列 的说:你们为何 不 给我 建造 香柏木 的殿宇呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, '「现在, 你要告诉我仆人 大卫,说 万军 之耶和华 如此 说:『我 从 羊圈中 将你召来,叫你不再跟从 羊群,立你 作 我民 以色列 的君。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, '你无论 往哪里 去,我常 与你同在,剪除 你 的一切 仇敌。我必使你 得 大 名,好像 世上 大大 有名的人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, '我必为我民 以色列 选定 一个地方,栽培他们,使他们住 自己的地方,不 再 迁移;凶恶 之子 也不 像 从前 扰害他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, '并不 像 我命 士师 治理 我民 以色列 的时候一样。我必使你 安靖,不被一切 仇敌扰乱,并且我─耶和华 应许 你, 必 为你 建立 家室。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, ' 你寿数 满足、与 你列祖 同睡的时候,我必 使 你的后 裔接续你的位;我也必坚定 他的国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, '他 必为我的名 建造 殿宇;我必坚定 他的国 位,直到 永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, '我 要作 他的 父,他 要作 我的 子;他若 犯了罪,我必用人 的杖 责打他,用人 的鞭责罚他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, '但我的慈爱 仍不 离开  他,像 离开  在你面前 所 废弃 的扫罗一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, '你的家 和你的国必在我(原文是你)面前 永远 坚立。你的国位 也必 坚定,直到 永远。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, '拿单 就按这 一切 话,照 这 默示, 告诉 大卫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, '于 是大卫 王 进去,坐 在耶和华 面前,说:「主 耶和华啊,我 是谁?我的家 算什么?你竟 使我到 这地步呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, '主 耶和华啊,这 在你眼中 还 看为小,又 应许 你仆人 的家 至于 久远。主 耶和华啊,这 岂是人 所常遇的事吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, '主 耶和华啊,我 还 有 何 言可以对你 说呢?因为你 知道 你的仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, '你行 这 大事 使 仆人 知道,是因 你所应许的话,也是照你的心意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, '主 耶和华啊,你本 为大,照 我们耳中 听见, 没有 可比你的;除你以外 再无 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, '世上 有何 民 能比你的民 以色列呢? 你 从埃及 救赎 他们 作自己的子民,又在你赎出来 的 民 面前 行 大 而可畏的事,驱逐列邦人和他们的 神,显出 你的 大名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, '你曾坚立 你的民 以色列 作你的 子民,直到 永远;你─耶和华 也作了 他们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, '「 耶和华 神啊,你所 应许 仆人 和 仆人家 的话,求你坚定,直到 永远;照你所 说的 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, '愿 人永远 尊你的名 为大,说:『万军 之耶和华 是治理 以色列的 神。』这样,你仆人 大卫 的家 必 在你面前 坚立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, '万军 之耶和华─以色列的 神啊,因 你 启示 你的仆人 说:『我必为你 建立 家室』,所以 仆人 大胆 向你 如此祈祷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, '「 主 耶和华啊,惟有你 是 神。你的话 是 真实的;你也应许 将 这 福气 赐给 仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, '现在 求 你赐福 与 仆人 的家,可以永 存 在你面前。主 耶和华啊, 这是你 所应许的。愿 你永远 赐 福 与仆人 的家!」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, ' 此 后,大卫 攻打 非利士人,把他们治服, 从他们 手下 夺取了京城的权柄(原文是母城的嚼环); ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, '又攻打 摩押人,使他们 躺卧 在地上,用绳 量一量:量 二 绳 的杀了,量一 绳 的存留。摩押人 就归服 大卫,给他进 贡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, '琐巴 王 利合 的儿子 哈大底谢 往大 河 去,要夺回 他的国权。大卫 就攻打 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, ' 擒拿了 他的 马兵 一千 七 百,步 兵 二万, 将 拉战 车的马 砍断蹄筋,但留下 一百辆 车 的马。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, '大马士革 的亚兰人 来 帮助 琐巴 王 哈大底谢,大卫 就杀了 亚兰人 二万二千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, '于 是大卫 在大马士革 的亚兰地 设立 防营,亚兰人 就归 服他,给他进 贡。大卫 无论 往哪里 去,耶和华 都使他 得胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, '他 夺了 哈大底谢 臣仆 所拿 的金 盾牌,带到 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, '大卫 王 又从属哈大底谢 的比他 和比罗他 城中 夺取了 许多 的铜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, '哈马 王 陀以 听见 大卫 杀败 哈大底谢 的全 军, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, ' 就打发 他儿子 约兰 去见 大卫 王,问 他的 安,为他祝福,因 为 他杀败了 哈大底谢(原来 陀以 与哈大底谢 常常 争 战 )。约兰 带了 金 银 铜 的器皿来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, '大卫 王 将这些 器皿和他 治服 各 国 所 得来的金 银 都 分别为圣,献 给耶和华, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, '就是从亚兰、摩押、亚扪、非利士、亚玛力人所得来的,以及从琐巴 王 利合 的儿子 哈大底谢 所掠之物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, '大卫 在盐 谷 击杀了 亚兰(或译:以东,见诗篇六十篇诗题)一万 八 千 人回来,就得了 大名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, '又在以东 全 地 设立 防营,以东人 就都 归 服 大卫。大卫 无论 往哪里 去,耶和华 都使他 得胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, '大卫 作 以色列 众人 的王, 又 向众 民 秉公 行 义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, '洗鲁雅 的儿子 约押 作 元帅;亚希律 的儿子 约沙法 作史官; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, '亚希突 的儿子 撒督 和亚比亚他 的儿子 亚希米勒 作祭司长;西莱雅 作书记; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, '耶何耶大 的儿子 比拿雅 统辖基利提人 和比利提人。大卫 的众子 都作 领袖。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, '大卫 问说:「 扫罗 家 还 有 剩下 的人没有?我要因 约拿单 的缘故向他 施 恩。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, '扫罗 家 有一个仆人,名 叫洗巴,有人叫 他 来见 大卫,王 问他 说:「你 是洗巴吗?」回答说:「仆人是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, '王 说:「扫罗 家 还有 人 没有?我要照 神 的慈爱 恩待 他。」洗巴 对 王 说:「还有 约拿单的 一个儿子,是瘸 腿的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, '王 说:「他 在哪里?」洗巴 对 王 说:「 他在罗‧底巴,亚米利 的儿子 玛吉 家里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, '于 是大卫 王 打发人去,从罗‧底巴 亚米利 的儿子 玛吉 家里 召了他来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, '扫罗 的孙子、约拿单 的儿子 米非波设 来 见 大卫,伏 地 叩拜。大卫 说:「米非波设!」米非波设说:「仆人 在此。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, '大卫 说:「你不要 惧怕, 我必 因 你父亲 约拿单 的缘故施 恩 与你,将 你祖父 扫罗 的一切田地 都 归还 你;你 也可以常 与 我同席 吃 饭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, '米非波设又叩拜,说:「仆人 算什么,不过 如死 狗 一般,竟 蒙王这样眷顾!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, '王 召了 扫罗 的仆人 洗巴来,对他 说:「我已将 属扫罗 和他的一切 家产 都赐 给你主人 的儿子了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, '你 和你的众子、仆人 要为你主人 的儿子 米非波设 耕种 田地,把所产的拿来 供他 食 用;他 却要常 与 我同席 吃 饭。」洗巴 有十五个 儿子,二十个 仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, '洗巴 对 王 说:「凡 我主 我王 吩咐 仆人的,仆人 都必遵 行。」王又说:「米非波设 必与 我同席 吃饭,如 王 的儿子一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, '米非波设 有一个小 儿子,名叫 米迦。凡住在 洗巴 家里 的人都 作了米非波设的 仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, '于 是米非波设 住 在耶路撒冷, 常 与 王 同席 吃饭。他 两 腿 都是瘸的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, ' 此后,亚扪 人 的王 死了,他儿子 哈嫩 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, '大卫 说:「我要照 哈嫩的父亲 拿辖厚 待 我 的恩典 厚 待 哈嫩。」于 是大卫 差遣 臣仆,为他丧 父 安慰他。大卫 的臣仆 到了 亚扪 人 的境内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, '但亚扪 人 的首领 对 他们的主 哈嫩 说:「 大卫 差 人来安慰 你,你想 他是尊敬 你父亲吗?他 差 臣仆来 不 是 详察 窥探、要倾覆 复 这城吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, '哈嫩 便 将 大卫 臣仆 的胡须 剃去 一半,又割断 他们下半截 的衣服,使他们露出 下体,打发他们回去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, '有人告诉 大卫,他就差 人去迎接他们,(因为 他们 甚 觉 羞耻), 告诉他们说:「可以住 在耶利哥,等到 胡须 长起 再回来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, '亚扪 人 知道 大卫 憎恶他们, 就打发人去,招募伯‧利合 的亚兰人 和 琐巴 的亚兰人,步兵 二万,与 玛迦 王 的人 一千、陀伯 人 一万 二 千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, '大卫 听见了,就差派 约押 统带 勇猛 的全 军出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, '亚扪 人 出来,在城 门前 摆 阵;琐巴 与利合 的亚兰人、陀伯人,并玛迦人,另 在郊野摆阵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, '约押 看见 敌人在 他 前 后 摆阵,就从 以色列 军中挑选 精兵,使他们对著 亚兰人 摆阵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, ' 其余 馀的 兵 交 与 他兄弟 亚比筛,对著 亚扪 人 摆阵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, '约押对亚比筛说:「亚兰人 若 强 过我,你就 来帮助 我;亚扪 人 若 强 过你,我就去 帮助 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, '我们都当刚强,为 本国的民 和 神 的城邑 作大丈夫。愿 耶和华 凭他的 意旨 而行!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, '于 是,约押 和 跟随他 的人 前进 攻打 亚兰人;亚兰人在约押面前 逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, '亚扪 人 见 亚兰人 逃跑,他们也在亚比筛 面前 逃跑 进 城。约押 就离开  亚扪 人那里,回 耶路撒冷 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, '亚兰人 见 自己被 以色列人 打败,就又聚 集。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, '哈大底谢 差遣人,将 大河 那边 的 亚兰人 调来;他们到了 希兰,哈大底谢 的将军 朔法 率领他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, '有人告诉 大卫,他就聚集 以色列 众人,过 约旦河,来到 希兰。亚兰人 迎著 大卫 摆阵,与他 打仗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, '亚兰人 在以色列人 面前 逃跑;大卫 杀了 亚兰 七 百 辆战 车的人,四万 马兵,又杀了 亚兰的将 军 朔法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, '属 哈大底谢 的诸 王 见 自己被 以色列人 打败,就与 以色列人 和好,归服他们。于 是亚兰人 不敢 再 帮助 亚扪 人了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, ' 过了 一年,到列王 出战  的时候,大卫 又差派 约押, 率领 臣仆 和 以色列 众人出战 。他们就打败 亚扪 人,围攻 拉巴。大卫 仍住 在耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, '一日,太阳平西,大卫 从 床上 起来,在 王 宫 的平顶上 游行,看见 一个妇人 沐浴, 容貌 甚 美, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, '大卫 就差人 打听 那妇人是谁。有人说:「她是 以连 的女儿,赫人 乌利亚 的妻 拔示巴。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, '大卫 差 人去,将妇人接来;那时她 的月经 才得洁净。她来了,大卫与她 同房,她就回 家 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, '于 是她 怀了孕,打发人 去告诉 大卫 说:「我 怀了孕。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, '大卫 差人 到 约押那里,说:「你打发 赫人 乌利亚 到我这里来。」约押 就打发 乌利亚 去见 大卫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, '乌利亚 来了,大卫 问 约押 好,也问兵 好,又问争战  的事怎样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, '大卫 对乌利亚 说:「你回 家去,洗洗 脚吧!」乌利亚 出了 王 宫,随后 王 送他一分食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, '乌利亚 却和 他主人的 仆人 一同睡在 宫 门外,没有 回 家 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, '有人告诉 大卫 说:「乌利亚 没有 回 家 去。」大卫 就问 乌利亚 说:「你 从远路 上来,为什么 不 回 家去呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, '乌利亚 对 大卫 说:「约柜 和以色列 与犹大 兵都住 在棚里,我主 约押 和我主(或译:王)的仆人 都在 田野 安营,我 岂可回 家 吃 喝、与 妻子 同寝呢?我敢在王面前起誓(原文是我指著王 和王 的性命起誓):我决不 行 这 事!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, '大卫 吩咐 乌利亚 说:「你今日 仍 住 在这里,明日 我打发你去。」于 是乌利亚 那 日 和次日 住 在耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, '大卫 召了 乌利亚来,叫他在自己面前 吃 喝,使他喝醉。到了晚上,乌利亚出去 与 他主 的仆人 一同住宿,还没有 回到 家里 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, ' 次日早晨,大卫 写 信 与 约押,交乌利亚 随手 带去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, '信内 写著 说:「要派 乌利亚 前进,到 阵势 极险之处,你们便退 后,使他被杀。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, ' 约押 围 城的时候, 知道 敌人 那里 有勇士,便将 乌利亚 派 在 那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, '城里 的人 出来 和 约押 打仗;大卫 的仆人 中有 几个 被杀的,赫人 乌利亚 也 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, '于 是,约押 差人 去将 争战  的一切 事 告诉 大卫, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, '又嘱咐 使者 说:「你把 争战  的一切 事 对 王 说 完了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, ' 王 若 发 怒,问你 说:『你们打仗 为什么 挨近 城墙呢?岂不 知 敌人 必从 城上 射箭吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, '从前打死耶路‧比设(就是耶路‧巴力,见士师记九章一节)儿子 亚比米勒 的是谁呢?岂不是 一个妇人 从 城上 抛下 一块 上磨石来,打在他身上,他就死 在提备斯么?你们为什么 挨近 城墙呢?』你就说:『王的仆人─赫人 乌利亚 也 死了。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, '使者 起身,来见大卫,照著约押 所 吩咐他的 话奏告 大卫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, '使者 对 大卫 说:「 敌人 强 过我们,出到 郊野 与我们打仗,我们 追杀他们,直到 城门 口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, '射箭的 从 城上 射 王 的仆人,射死 几个, 赫人 乌利亚 也 死了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, '王 向 使者 说:「你告诉 约押 说:『不要 因 这 事 愁闷, 刀剑 或吞灭 这人 或吞灭那人,没有一定的;你只管竭力 攻 城,将城倾覆 复。』可以用这话勉励约押。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, '乌利亚 的妻 听见 丈夫 乌利亚 死了,就为 他 哀哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, '哀哭 的日子过了,大卫 差人 将她接 到 宫里,她就作了 大卫的 妻,给大卫 生了 一个儿子。但大卫 所 行的 这事,耶和华 甚不喜悦。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, '耶和华 差遣 拿单 去见 大卫。拿单到了 大卫那里,对他 说:「在一座 城里 有 两个 人:一个 是富户,一个 是穷人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, ' 富户 有 许多 牛群 羊群; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, '穷人 除了 所 买 来 养活 的一只 小 母羊羔之外,别无 所有。羊羔在他家里 和 他儿女 一同 长大,吃 他所吃的,喝 他所喝的,睡 在他怀中,在他 看来 如同女儿一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, '有一客人 来到 这富 户家里;富户舍不得 从自己的牛群 羊群 中取 一只预备 给客人吃,却取了 那穷 人 的羊羔,预备 给客人吃。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, '大卫 就甚 恼 怒 那人,对 拿单 说:「我指著永生的 耶和华起誓, 行 这事 的人 该 死! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, '他必偿还 羊羔 四倍;因为 他 行 这 事, 没有 怜恤的心。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, '拿单 对 大卫 说:「你 就是那人!耶和华─以色列的 神 如此 说:『我 膏你 作 以色列 的王, 救你 脱离扫罗 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, '我将 你主人 的家 业赐 给你,将 你主人 的妻 交在你怀里,又将 以色列 和犹大 家 赐 给你;你若 还以为不足,我早就 加倍地 赐 给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, '你为什么 藐视 耶和华 的命令,行 他眼中 看为恶的事呢?你借亚扪 人 的刀 杀 害 赫人 乌利亚,又娶了 他的妻 为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, '你既 藐视我,娶了 赫人 乌利亚 的妻 为 妻,所以 刀 剑必永 不 离开  你的家。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, '耶和华 如此 说:『 我必从你家中 兴起 祸患 攻击你;我必在你眼前 把 你的妃嫔 赐 给别人,他在 日光 之下 就与 她们 同寝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, ' 你 在暗中 行这事,我 却要在以色列 众人 面前,日光 之下,报应你。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, '大卫 对 拿单 说:「我得罪 耶和华了!」拿单 说:「 耶和华 已经除掉 你的罪,你必不至 于 死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, '只是 你行这 事,叫 耶和华 的仇敌 大得 亵渎的机会,故此,你 所得的 孩子 必定 要死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, '拿单 就回 家 去了。耶和华 击打 乌利亚 妻 给大卫 所 生的 孩子,使他得重病。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, '所以大卫 为 这孩子 恳求 神,而且 禁 食,进入内室,终夜 躺在 地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, '他家中 的老臣 来到 他旁边,要把他从 地上 扶起来,他却不 肯起来,也不 同他们 吃 饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, '到 第七 日,孩子 死了。大卫 的臣仆 不敢 告诉 他 孩子 死了,因 他们说:「 孩子 还 活著的时候,我们劝 他,他尚且不肯 听 我们的话,若告诉 他 孩子 死了,岂 不更加 忧伤吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, '大卫 见 臣仆 彼此低声说话, 就知道 孩子 死了, 问 臣仆 说:「孩子 死了吗?」他们说:「死了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, '大卫 就从地上 起来,沐浴,抹膏,换了 衣裳,进 耶和华 的殿 敬拜;然后回 宫,吩咐 人摆 饭,他便吃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, '臣仆 问他 说:「你所 行的 是什么 意思?孩子 活著 的时候,你禁食 哭泣; 孩子 死了,你倒起来 吃 饭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, '大卫说:「孩子 还 活著,我禁食 哭泣;因为 我想,或者耶和华 怜恤我,使孩子 不死 也未 可知。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, ' 孩子死了,我 何必 禁食,我岂能 使他返回呢?我 必往他那里 去,他 却不能 回 我这里来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, '大卫 安慰 他的妻 拔示巴, 与她 同寝,她就生了 儿子,给他起 名 叫 所罗门。耶和华 也喜爱他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, '就藉 借 先知 拿单 赐他一个 名字,叫 耶底底亚,因为 耶和华爱他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, '约押 攻 取 亚扪 人 的京 城 拉巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, '约押 打发 使者 去见 大卫,说:「我攻打 拉巴, 取其 水 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, '现在 你要聚集 其余 馀 的军兵来,安营 围 攻 这城,恐怕 我 取了 这城,人就以 我的名 叫这城。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, '于 是大卫 聚集 众 军,往拉巴 去 攻 城,就取了这城, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, '夺了 亚扪人之王 所 戴 的金冠冕(王:或译玛勒堪;玛勒堪就是米勒公,又名摩洛,亚扪族之神名),其上的金子 重 一他连得,又嵌著宝 石。人将这冠冕戴 在 大卫 头上。大卫从城里 夺了 许 多 财物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, '将 城 里 的人 拉出来,放 在锯下,或铁 耙下,或铁 斧下,或叫他 经过 砖窑(或译:强他们用锯,或用打粮食的铁器,或用铁斧做工,或使在砖窑里服役);大卫待 亚扪 各 城 的居民 都是如此。其后,大卫 和众 军 都回 耶路撒冷去了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, ' 大卫 的儿子 押沙龙有 一个美貌的 妹子,名叫 她玛。大卫 的儿子 暗嫩 爱她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, '暗嫩 为 他妹子 她玛 忧急 成病。 她玛 还是处女,暗嫩 以为 难 向她 行 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, '暗嫩有 一个朋友,名叫 约拿达,是大卫 长兄 示米亚 的儿子。这约拿达 为人 极其 狡猾; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, '他问暗嫩 说:「王 的儿子啊,为何 一天 比一天 瘦弱呢?请 你告诉 我。」暗嫩 回答 说:「我 爱 我兄弟 押沙龙 的妹子 她玛。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, '约拿达 说:「你不如躺 在 床上 装病;你父亲 来 看你,就对他 说:『求 父叫我妹子 她玛 来,在我眼前 预备 食物,递给我 吃,使 我看见,好从她手 里接过来吃。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, '于 是暗嫩 躺卧 装病。王 来 看他,他 对 王 说:「求 父 叫我妹子 她玛 来,在我眼前 为我做 两个 饼,我好从她手里 接过来吃。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, '大卫 就打发 人到宫里,对 她玛 说:「 你往你哥哥 暗嫩 的屋里 去,为他 预备 食物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, '她玛 就到 她哥哥 暗嫩 的屋里;暗嫩 正躺卧。她玛抟 面 麺,在他眼前 做饼,且烤熟了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, '在他面前 将饼从 锅 里倒出来,他却不肯 吃, 便说:「众 人 离开 我 出去吧!」众 人 就都离开 他,出去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, '暗嫩 对 她玛 说:「你把食物 拿进 卧房,我好从你手里 接过来吃。」她玛 就把 所 做 的饼 拿 进 卧房,到她哥哥 暗嫩那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, '拿著饼上前 给他 吃,他便拉住 她玛,说:「我妹妹,你来 与我 同寝。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, '她玛说:「我哥哥,不要 玷辱我。 以色列 人中不当 这样 行,你不要 做 这 丑事; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, '你玷辱了我,我 何以 掩盖 我的羞耻呢?你 在以色列 中也成了 愚妄人。 你可以求 王,他必 不 禁止我 归你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, '但暗嫩不 肯 听 她的话,因比她 力大,就玷辱她,与她 同寝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, '随后,暗嫩 极 其 恨她, 那 恨她 的心比先前 爱她 的心 更甚, 对她 说:「你起来,去吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, '她玛说:「不要 这样!你赶出我去 的这 罪 比 你才行的 更重!」但暗嫩不 肯 听 她的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, '就叫 伺候自己 的仆人来,说:「 将 这个女子 赶 出去!她一出去,你就关门,上闩。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, '那时她玛穿著 彩 衣,因为 没有出嫁 的公主 都是这样 穿。暗嫩的仆人 就把她 赶 出去, 关门 上闩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, '她玛 把灰尘 撒 在 头上,撕裂 所 穿的彩 衣,以手 抱 头,一面行走,一面 哭喊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, '她胞兄 押沙龙 问她 说:「莫非你哥哥 暗嫩 与你 亲近了吗?我妹妹,暂且 不要作声,他是 你的哥哥,不要 将这 事 放 在 心上。」她玛 就孤孤单单地 住 在她胞兄 押沙龙 家里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, '大卫 王 听见 这 事,就甚 发怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, '押沙龙 并不 和 他哥哥暗嫩 说 好 说歹;因 为 暗嫩 玷辱 他妹妹 她玛,所以 押沙龙 恨恶 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, '过了 二年,在靠近 以法莲 的巴力‧夏琐 有人 为押沙龙 剪羊毛;押沙龙 请 王 的众 子与他同去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, '押沙龙 来 见 王,说:「现在 有人为仆人 剪羊毛,请 王 和王的臣仆 与 仆人 同去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, '王 对 押沙龙 说:「 我儿,我们不必 都 去,恐怕 使你 耗费太多。」押沙龙再三 请王,王仍是不 肯 去,只为他祝福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, '押沙龙 说:「王若不去,求 王许我哥哥 暗嫩 同 去。」王 说:「何必 要他去呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, '押沙龙 再三求 王,王就许 暗嫩 和 王 的众 子 与他 同去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, '押沙龙 吩咐 仆人 说:「 你们注意,看暗嫩 饮酒 畅快的时候,我对你们 说 杀 暗嫩,你们便杀 他,不要 惧怕。这不是 我 吩咐 你们的吗?你们只管壮胆 奋勇!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, '押沙龙 的仆人 就照 押沙龙 所吩咐的,向暗嫩 行了。王 的众 子 都起来,各人 骑 上 骡子,逃跑了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, '他们 还 在路上,有风声 传 到 大卫那里,说:「押沙龙 将 王 的众 子 都杀了,没有 留下 一个。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, '王 就起来,撕裂 衣服,躺 在地上。王的臣仆 也都 撕裂 衣服,站在旁边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, '大卫 的长兄,示米亚 的儿子 约拿达 说:「我主,不要 以为 王 的众 子─少年人 都杀了, 只有 暗嫩 一个人死了。自从暗嫩玷辱 押沙龙妹子 她玛 的那日, 押沙龙 就 定意杀暗嫩了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, '现在,我主 我王,不要 把这事 放 在 心上,以为 王 的众 子 都死了, 只有 暗嫩 一个人死了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, '押沙龙 逃跑了。守望的 少年人 举 目 观看,见 有许多 人 从山 坡 的路上 来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, '约拿达 对 王 说:「看哪,王 的众子 都来了,果然 与你仆人 所说的相合。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, '话才 说 完, 王 的众子 都到了,放 声 大哭;王 和臣仆 也 都 哭 得甚 恸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, '押沙龙 逃 到 基述 王 亚米忽 的儿子 达买  那里去了。大卫天天 为 他儿子 悲哀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, '押沙龙 逃 到 基述,在 那里 住了三 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, ' 暗嫩 死了以后,大卫 王 得了安慰, 心里切切 想念 押沙龙。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, '洗鲁雅 的儿子 约押,知道 王 心里 想念 押沙龙, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, ' 就打发 人往提哥亚去,从那里 叫了 一个聪明的 妇人来,对她 说:「请 你假装居丧的, 穿上 孝衣,不要 用膏 抹身,要装作 为 死者 许久 悲哀 的 妇人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, '进去 见 王,对王 如此如此 说。」于 是约押 将 当说的话 教导了 妇人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, '提哥亚 妇人 到 王 面前,伏 地 叩拜,说:「王啊,求你拯救!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, '王 问她 说:「你 有什么事呢?」回答说:「婢女 实在 是寡 妇,我丈夫 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, '我有 两个 儿子, 一日在田间 争斗,没有人 解劝,这个 就打 死 那个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, ' 现在全 家 的人都起来 攻击 婢女,说:『你将 那 打死 兄弟 的交出来,我们好治死他,偿他打死 兄弟 的命, 灭绝 那承受家业的。』这样,他们要将 我剩下 的 炭火 灭尽,不 与我丈夫 留 名 留后 在 世 上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, '王 对 妇人 说:「你回家 去吧!我 必为你 下令。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, '提哥亚 妇人 又对 王 说:「我主 我王,愿 这罪 归我 和 我父 家,与王 和王的位 无干。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, '王 说:「凡难为 你的,你就带他 到我这里来,他必不 再 搅扰 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, '妇人说:「愿  王 记念 耶和华─你的 神,不许 报 血 仇的人施行灭绝,恐怕 他们灭绝 我的儿子。」王说:「我指著永生的 耶和华起誓:你的儿子 连 一根头发 也不致落在 地上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, '妇人 说:「求 我主 我王 容婢女 再说 一句话。」王说:「你说吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, '妇人 说:「王为何也 起意 要害 神 的民呢?王 不 使 那逃亡的人 回来,王 的这 话 就是自证己错了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, ' 我们都是必 死的,如同水 泼 在地上, 不能 收回。 神 并不 夺取 人的性命,乃设 法 使 逃亡的人 不致成为赶出、回不来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, ' 我来 将 这 话 告诉 我主 我王,是因 百姓 使我惧怕。婢女 想,不如 将这话告诉 王,或者 王 成就 婢女 所求的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, '人要将我 和 我儿子从 神 的地业 上一同 除灭,王 必 应允 救 我 脱离他 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, '婢女 又想,我主 我王 的话 必 安慰我;因为 我主 我王 能辨别 是 非,如同 神 的使者 一样。惟愿 耶和华─你的 神 与你 同在!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, '王 对 妇人 说:「 我 要问 你一句话, 你一点 不要 瞒 我。」妇人 说:「愿  我主 我王 说。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, '王 说:「你 这些 话莫非是约押 的主意吗?」妇人 说:「我敢在我主 我王 面前起誓: 王 的 话正对,不偏 左 右, 是王的仆人 约押 吩咐我的, 这些 话 是他 教导 我的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, '王的仆人 约押 如此 行,为要 挽回 这事。我主 的智慧却如 神 使者 的智慧,能知 世上 一切事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, '王 对 约押 说:「 我应允你 这 事。你可以去,把 那少年人 押沙龙 带回来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, '约押就 面 伏于  地 叩拜,祝谢 于  王, 又说:「王 既 应允 仆人 所求的,仆人 今日 知道 在我主 我王 眼前 蒙 恩了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, '于 是约押 起身 往基述 去,将 押沙龙 带回 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, '王 说:「使他回 自己家里 去,不要 见 我的面。」押沙龙 就回 自己家里 去,没有 见 王 的面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, '以色列 全地之中,无 人 像押沙龙 那样俊美,得人的称赞,从脚 底 到 头顶 毫无 瑕疵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, ' 他的头发 甚重,每 到 年 底 剪 发一次;所 剪下来的,按王 的平 称 一称,重二百 舍客勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, '押沙龙 生了 三个 儿子,一个 女儿。女儿名叫 她玛, 是 个容貌 俊美的 女子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, '押沙龙 住 在耶路撒冷 足有二年,没有 见 王 的面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, '押沙龙 打发 人去 叫约押来,要托 讬 他 去见 王,约押却不 肯 来。第二次 打发人去叫他,他仍不 肯 来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, '所以押沙龙对 仆人 说:「你们看,约押 有一块田,与 我的田相近,其 中 有大麦,你们去 放火 烧了。」押沙龙 的仆人 就去放火 烧了 那田。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, '于 是约押 起来,到了 押沙龙 家里,问他 说:「你的仆人 为何 放火 烧了 我 的 田呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, '押沙龙回答 约押 说:「 我打发人去 请你 来, 好托 讬 你 去见 王,替我说:『我为何 从基述 回来呢? 不如 仍 在那里。』现在 要许我见 王 的面;我 若 有 罪,任凭王杀我就是了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, '于 是约押 去 见 王,将这话奏告 王,王便叫 押沙龙来。押沙龙来见 王,在王 面前 俯伏 于  地,王就 与押沙龙 亲嘴。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, ' 此后,押沙龙 为自己 预备 车 马,又派五十 人 在他前头 奔走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, '押沙龙 常常早晨起来,站 在 城门 的道 旁,凡 有 争讼 要去 求 王 判断的,押沙龙 就叫 他过来,问他说:「你 是哪 一 城的人?」回答说:「仆人 是以色列 某 支派的人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, '押沙龙 对他 说:「 你的事 有情 有理,无奈 王 没有 委人听 你伸诉。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, '押沙龙 又说:「恨不得 我作 国中 的士师!凡 有 争讼 求审判 的到我 这里来,我必秉公判断。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, '若有 人 近前 来要拜押沙龙,押沙龙就伸 手 拉住 他,与他 亲嘴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, ' 以色列人中,凡 去见 王 求判断的,押沙龙 都是如此 待他们。这样,押沙龙 暗中得了 以色列 人 的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, ' 满了 四十 年(有作四年的),押沙龙 对 王 说:「求 你准我往希伯仑  去,还 我向耶和华 所 许 的愿 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, '因为 仆人 住 在亚兰 的基述,曾许 愿  说:『耶和华 若 使我再回 耶路撒冷,我必事奉 他。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, '王 说:「你平平安安地 去吧!」押沙龙就起身,往希伯仑  去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, '押沙龙 打发 探子 走遍以色列 各 支派,说:「你们一听见 角 声 就说:『押沙龙 在希伯仑  作王了!』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, '押沙龙 在耶路撒冷 请了 二百 人 与他 同去,都是诚诚实实 去的,并不 知道其中的 真情。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, '押沙龙 献 祭的时候,打发 人去将 大卫 的谋士、基罗人 亚希多弗 从他本城请了来。于 是叛逆的势派 甚大;因为随从 押沙龙 的人民,日渐 增多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, '有人报告 大卫 说:「以色列 人 的心 都归 向 押沙龙了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, '大卫就对 耶路撒冷 跟随他 的臣仆 说:「我们要起来 逃走,不然 都不 能 躲避 押沙龙了;要速速地 去,恐怕 他忽然 来到,加 害 于 我们,用 刀 杀尽 合城的人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, '王 的臣仆 对 王 说:「我主 我王 所 定的, 仆人都愿 遵行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, '于 是王 带著全 家的人 出去了,但 留下 十个 妃 嫔 看守 宫殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, '王 出去,众 民 都跟随他,到伯墨哈,就住下了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, '王的臣仆 都 在他 面前 过去。 基利提人、 比利提人, 就是 从迦特 跟随王 来 的六 百 人,也都在 他 面前 过去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, '王 对 迦特人 以太 说:「 你 是外邦 逃来的人,为什么 与我们 同去呢?你 可以回去 与 新王 同住,或者回你本地去吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, '你来 的日子不多,我今日 怎好叫你与我们一同 飘流、没有一定的住处呢?你 不如带 你的弟兄 回去吧!愿 耶和华用慈爱 诚实 待你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, '以太 对 王 说:「我指著永生的 耶和华起誓,又敢在 王面前起誓:无论 生 死, 王 在哪里, 仆人 也必 在那里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, '大卫 对 以太 说:「你前去 过河吧!」于 是迦特人 以太 带著 跟随他的 人 和所有的 妇人孩子,就都过去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, '本地 的人都 放声 大 哭。众 民 尽都过去,王 也过了 汲沦 溪;众 民 往 旷野 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, ' 撒督 和抬 神 约 柜的 利未人 也 一同来了,将 神 的约柜 放下。亚比亚他 上来,等著 众 民 从城里 出来 过去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, '王 对撒督 说:「你将 神 的约柜 抬回 城去。我若 在耶和华 眼前 蒙 恩,他必使我回来,再见 约柜 和 他的居所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, '倘若他 说:『我不 喜悦 你』,看哪,我在这里,愿 他凭 自己的 意旨 待 我!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, '王 又对 祭司 撒督 说:「你 不是先见吗?你可以安然 回 城;你儿子 亚希玛斯 和亚比亚他 的儿子 约拿单 都 可以与你同去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, ' 我 在旷野 的渡口 那里等 你们 报信 给我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, '于 是撒督 和亚比亚他 将 神 的约柜 抬回 耶路撒冷,他们就住 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, '大卫 蒙 头 赤脚 上 橄榄山,一面上 一面哭。 跟随他 的人 也都 蒙 头 哭著 上去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, '有人告诉 大卫 说:「亚希多弗 也在叛党之中,随从 押沙龙。」大卫 祷告说:「耶和华啊,求 你使 亚希多弗 的计谋 变为愚拙!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, ' 大卫 到了 山顶、 敬拜 神 的地方,见 亚基人 户筛,衣服 撕裂,头 蒙 灰尘 来迎接他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, '大卫 对他 说:「你若 与我 同去,必 累赘 我; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, '你若 回 城去,对押沙龙 说:『王啊,我 愿 作 你的仆人;我 向来 作你父亲 的仆人,现在 我 也照样作你的仆人。』这样,你就可以为我 破坏 亚希多弗 的计谋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, '祭司 撒督 和亚比亚他 岂不都 在 那里吗?你在王 宫 里听见 什么,就要告诉 祭司 撒督 和亚比亚他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, ' 撒督的 儿子亚希玛斯,亚比亚他的 儿子约拿单, 也都在 那里。凡 你们所听见 的可以托 讬这二人 来报告我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, '于 是,大卫 的朋友 户筛 进了 城;押沙龙 也进了 耶路撒冷。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, '大卫 刚 过 山顶,见 米非波设 的仆人 洗巴 拉著 备好了的两匹 驴,驴上驮著 二百 面 麺饼,一百 葡萄饼,一百个 夏天的果饼,一皮袋 酒 来迎接他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, '王 问 洗巴 说:「你 带这些 来是什么意思呢?」洗巴 说:「驴 是给王 的家眷 骑的;面 麺饼 和夏天的果饼 是给少年人 吃的;酒 是给在旷野 疲乏 人喝的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, '王 问说:「你主人 的儿子 在哪里呢?」洗巴 回答 王 说:「 他仍在 耶路撒冷,因 他说:『以色列 人 今日 必将 我父 的国 归还 我。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, '王 对洗巴 说:「 凡 属米非波设 的都归你了。」洗巴 说:「我叩拜 我主 我王,愿 我在你眼前 蒙 恩。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, '大卫 王 到了 巴户琳,见 有一个人 出来,是扫罗 族 基拉 的儿子,名叫 示每。他一面走 一面 咒骂, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, '又拿石头 砍 大卫 王和 王的 臣仆;众 民 和 勇士 都在王的左 右。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, '示每 咒骂 说:「你这 流人血 的坏 人哪,去吧 去吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, '你流扫罗 全 家 的血, 接续他 作王;耶和华 把这罪归 在你身上, 将 这国 交给 你儿子 押沙龙。现在你 自取其祸,因为 你是 流人血 的人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, '洗鲁雅 的儿子 亚比筛 对 王 说:「这 死 狗 岂可 咒骂 我主 我王呢?求 你容我过去,割下 他的头来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, '王 说:「洗鲁雅 的儿子,我 与你们 有何关涉呢? 他咒骂 是因 耶和华 吩咐他 说:『你要咒骂 大卫。』如此,谁 敢说 你为什么 这样 行呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, '大卫 又对 亚比筛 和 众 臣仆 说:「 我亲 生 的 儿子 尚且寻索 我的性命,何况 这便雅悯人呢?由 他 咒骂吧!因为 这是耶和华 吩咐 他的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, '或者 耶和华 见 我遭难,为 我今 日 被这人咒骂,就施 恩 与我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, '于 是大卫 和跟随他的人往前 行走。示每 在大卫 对面 山 坡,一面行走 一面咒骂,又拿石头 砍 他,拿土 扬他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, '王 和 跟随他 的众 人 疲疲乏乏地 到了一个地方,就在那里 歇息歇息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, '押沙龙 和以色列 众 人 来到 耶路撒冷;亚希多弗 也与他同来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, ' 大卫 的朋友 亚基人 户筛 去 见 押沙龙, 对 他 说:「愿 王 万岁!愿 王 万岁!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, '押沙龙 问 户筛 说:「这 是你恩待 朋友吗?为什么 不 与 你的朋友 同去呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, '户筛 对 押沙龙 说:「不然, 耶和华 和这 民,并以色列 众 人 所 拣选的,我必 归顺他,与他 同住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, '再者,我 当服事 谁呢?岂不是 前王的 儿子吗?我怎样 服事 你父亲,也必照样 服事 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, '押沙龙 对 亚希多弗 说:「你们出个 主意,我们怎样 行才好?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, '亚希多弗 对 押沙龙 说:「你父 所 留下 看守 宫殿 的妃嫔,你可以与她们 亲近。以色列 众人 听见 你父亲 憎恶你,凡 归顺你 人的手 就更坚强。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, '于 是人为押沙龙 在 宫殿的平顶 上支搭 帐棚;押沙龙 在以色列 众人 眼前,与 他父 的妃嫔 亲近。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, '那 时 亚希多弗 所 出 的主意 好像 人 问 神 的话一样;他昔日 给大卫,今日 给押沙龙 所出的主意,都 是这样。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, '亚希多弗 又对 押沙龙 说:「求 你准我挑选 一万二 千 人,今夜 我就起身 追 赶 大卫, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, '趁他 疲乏 手 软,我忽然追 上他,使他 惊惶;跟随他 的 民 必都 逃跑,我就单 杀 王一人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, '使众 民 都归 顺你。你 所 寻找 的人既然死了,众 民就如已经 归顺你;这样,也都 平安无事了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, '押沙龙和 以色列 的长老 都 以这话 为美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, '押沙龙 说:「要 召 亚基人 户筛来,我们也 要听 他 怎样 说。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, '户筛 到了 押沙龙面前,押沙龙 向他 说:「亚希多弗 是如此如此 说的,我们照著 他的话 行可以不可以?若 不可,你 就说吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, '户筛 对 押沙龙 说:「亚希多弗 这 次 所 定 的谋 不 善。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, '户筛 又说:「你 知道, 你父亲 和 跟随他的人 都是 勇士,现在他们 心里 恼怒,如同田野 丢崽子 的母熊一般,而且你父亲 是个战  士,必不 和 民 一同住宿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, ' 他 现今 或藏 在 坑 中或 在 别处,若有人 首先 被杀,凡 听见 的必说:『 跟随 押沙龙 的民 被杀了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, '虽有人 胆大 如 狮子,他 的心 也 必 消化;因为 以色列人 都 知道 你父亲 是英雄,跟随他 的人 也都是勇 士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, ' 依我之计,不如将以色列 众人─从但 直到 别是巴,如同 海 边 的沙 那样多─聚 集 到你这里来,你也亲自 率领他们出 战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, '这样, 我们 在 何处 遇见他,就下到他 那里,如同 露水 下 在 地上一般,连他 带 跟随他 的 人,一个 也 不 留下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, '他若 进了 哪一座城,以色列 众人 必带 绳子 去,将 那 城 拉 到 河里,甚至 连 一块小石头 都不 剩下。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, '押沙龙 和以色列 众 人 说:「亚基人 户筛 的计谋 比亚希多弗 的计谋 更好!」这是因耶和华 定意 破坏 亚希多弗 的良 谋, 为要 降 祸 与 押沙龙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, '户筛 对 祭司 撒督 和 亚比亚他 说:「亚希多弗 为 押沙龙 和 以色列 的长老 所定的计谋 是如此 如此,我 所定的计谋 是如此 如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, '现在 你们要急速 打发人去,告诉大 卫 说:『今夜 不可 住 在旷野 的渡口, 务要 过河,免得 王 和 跟随他 的 人 都被吞灭。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, '那时,约拿单 和亚希玛斯在隐‧罗结 那里等候,不 敢 进 城,恐怕被人看见。有一个使女 出来,将这话告诉 他们,他们 就去 报信 给大卫 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, '然而有一个童子 看见 他们,就去告诉 押沙龙。他们 急忙 跑 到 巴户琳 某人 的家里;那人 院 中有一口井,他们就下到 井里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, '那家的妇人 用 盖 盖 上 井 口,又在上头 铺 上碎麦,事 就没有 泄漏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, '押沙龙 的仆人 来 到 那家,问妇人 说:「亚希玛斯 和约拿单 在哪里?」妇人 说:「他们过了 河了。」仆人找他们,找 不著,就回 耶路撒冷去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, ' 他们走 后,二人从井 里上来,去 告诉 大卫 王 说:「 亚希多弗 如此如此 定计 害你,你们务要起来,快快 过 河。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, '于 是大卫 和跟随他 的 人 都 起来,过 约旦河。到了 天亮, 无 一人 不 过 约旦河的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, '亚希多弗 见 不 依从 他的计谋,就备 上 驴,归 回 本城;到了 家,留下遗言,便吊 死了,葬 在他父亲 的坟墓里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, '大卫 到了 玛哈念,押沙龙 和跟随他 的以色列 人 也都 过了 约旦河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, '押沙龙 立 亚玛撒 作 元帅,代替 约押。亚玛撒是以实玛利人(又作以色列人) 以特拉 的儿子。以特拉 曾与 拿辖 的女儿 亚比该 亲近;这亚比该与约押 的母亲 洗鲁雅 是姊妹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, '押沙龙 和以色列 人都安营 在基列 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, ' 大卫 到了 玛哈念,亚扪族 的拉巴人 拿辖 的儿子 朔比,罗‧底巴人亚‧米利 的儿子 玛吉,基列 的罗基琳人 巴西莱, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, '带著 被、褥、盆、碗、瓦 器、小麦、大麦、麦面 麺、炒谷、豆子、红豆、炒豆、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, '蜂蜜、奶油、绵羊、奶 饼,供给大卫 和跟随他 的 人 吃; 他们说:「民 在旷野,必饥 渴 困乏了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, '大卫 数点 跟随他 的 人,立 千 夫长、百 夫长 率领他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, '大卫 打发 军兵出战 ,分为三队:一队 在约押 手下,一队 在洗鲁雅 的儿子、约押 兄弟 亚比筛 手下,一队 在迦特人 以太 手下。大卫 对 军兵 说:「 我 必 与你们 一同出战 。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, '军兵 却说:「你不可 出战 。 若 是我们逃 跑,敌人必不 介 意; 我们阵亡 一半,敌人也不 介 意。因为 你一人强似我们 万人, 你不如 在城 里预备 帮助 我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, '王 向他们 说:「你们以为 怎样 好,我就怎样行。」于 是王 站 在 城门 旁, 军兵 或百 或千 地挨次出去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, '王 嘱咐 约押、 亚比筛、 以太 说:「你们要为我 的缘故宽待 那少年人 押沙龙。」王 为 押沙龙 嘱咐 众 将 的话,兵 都 听见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, '兵 就出到 田野 迎著 以色列人,在以法莲 树林里 交战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, '以色列 人 败 在大卫 的仆人 面前;那 日 阵亡的 甚多,共有二万人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, ' 因为在那里 四 面 打仗, 死于  树林 的比 死于  刀剑的 更多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, '押沙龙偶然 遇见 大卫 的仆人。押沙龙 骑 著 骡子, 从大 橡树 密枝 底下 经过,他的头 发被树枝 绕住,就悬挂起来,所 骑的 骡子 便离他去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, '有个 人 看见,就告诉 约押 说:「 我看见 押沙龙 挂 在橡树上了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, '约押 对报信 的人 说:「你既 看见他,为什么 不 将他打死 落在地上呢?你若打死他,我就赏 你 十 舍客勒银子,一条 带子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, '那人 对 约押 说:「我 就是 得 你 一千 舍客勒银子,我也不敢 伸 手 害 王 的儿子;因为 我们听见 王 嘱咐 你 和 亚比筛 并 以太 说:『你们要谨慎, 不可害那少年人 押沙龙。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, '我若 妄 为 害了他的性命,就是你自己 也必 与我为敌(原来,无论 何事 都瞒 不 过 王。)」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, '约押 说:「我不能 与你 留连。」约押手 拿 三 杆短枪,趁押沙龙 在 橡树 上还 活著,就刺透 他的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, '给约押 拿 兵器 的十个 少年人 围绕 押沙龙,将他 杀 死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, '约押 吹 角, 拦阻 众人,他们 就回来,不再追 赶 以色列人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, '他们 将 押沙龙 丢 在林中 一个大 坑里,上头 堆起 一 大 堆 石头。以色列 众人都 逃跑,各 回各家去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, '押沙龙 活著的时候, 在王 谷 立了一根 石柱,因 他说:「我没有 儿子 为 我留 名。」他就以 自己的名 称 那石柱 叫 押沙龙 柱,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, '撒督 的儿子 亚希玛斯 说:「容 我跑去,将 耶和华 向 仇敌 给王 报仇 的信息 报 与王知。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, '约押 对他 说:「你 今 日 不可 去报信,改 日 可以报信; 因为 今 日 王 的儿子 死了,所以你不可 去报信。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, '约押 对古示人 说:「你去 将你所 看见 的告诉 王。」古示人 在约押 面前下拜,就跑去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, '撒督 的儿子 亚希玛斯 又 对 约押 说:「无论怎样,求你容 我 随著 古示人 跑去。」约押 说:「我儿,你 报这信息,既不 得赏赐,何必 要跑去呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, '他又说:「无论怎样,我要跑去。」约押说:「你跑去吧!」亚希玛斯 就从 平原 往前跑,跑过 古示人去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, '大卫 正坐 在 城 瓮里。守望的人 上 城门 楼 的顶上,举 目 观看,见 有一个人 独自 跑来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, '守望的人 就大声 告诉 王。王 说:「他若 独自来,必是报口 信的。」那人跑 得渐渐 近了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, '守望的人 又见 一 人 跑来, 就对 守城门的人 说:「 又有一人 独自 跑来。」王 说:「这 也 必是报信的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, '守望的人 说:「我 看 前头 人的跑法,好像撒督 的儿子 亚希玛斯 的跑法一样。」王 说:「他是 个好 人,必是报 好 信息。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, '亚希玛斯 向 王 呼叫 说:「平安了!」就在王 面前脸 伏于 地 叩拜,说:「耶和华─你的 神 是应当称颂的,因他 已将 那 举 手 攻击我主 我王 的人 交给王了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, '王 问说:「少年人 押沙龙 平安不平安?」亚希玛斯 回答说:「约押 打发 王 的仆人,那时 仆人 听见 众民大声 喧哗,却不 知道 是什么事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, '王 说:「你退去,站在 旁边。」他就退去,站在旁边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, ' 古示人 也来到, 说:「有信息 报给我主 我王! 耶和华 今日 向 一切 兴起 攻击你的人 给你报仇了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, '王 问 古示人 说:「少年人 押沙龙 平安不平安?」古示人 回答说:「愿 我主 我王 的仇敌,和一切 兴起 要杀害 你的人,都 与那少年人一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, '王 就心里伤恸,上 城门 楼 去哀哭,一面走 一面 说:「我儿 押沙龙啊!我儿,我儿 押沙龙啊!我 恨不 得 替你 死,押沙龙啊,我儿!我儿!」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, '有人告诉 约押说:「 王 为 押沙龙 哭泣 悲哀。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, ' 众 民 听 说 王 为 他儿子 忧愁, 他们 得胜 的欢乐却变成 悲哀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, '那 日 众民 暗暗地 进 城,就如 败阵 逃跑、惭愧 的民一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, '王 蒙 著 脸, 大 声 哭号说:「我儿 押沙龙啊!押沙龙,我儿,我儿啊!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, '约押 进去 见 王,说:「你今日 使 你一切 仆人 脸面 惭愧了!他们今日 救了 你的性命 和 你儿 女 妻 妾 的性命, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, '你却爱 那恨你的人,恨 那爱你的人。 你 今日 明明地 不 以将帅、仆人为念。 我今日 看明, 若 押沙龙 活著, 我们都 死亡, 你就 喜悦了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, '现在 你当 出去,安慰 你仆人 的心。 我指著耶和华 起誓:你若 不 出去,今夜 必无 一人 与你 同在一处;这 祸患 就比你 从幼年 到 如今 所 遭的 更甚!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, '于 是王 起来,坐 在城门口。众 民 听 说 王 坐 在城门口, 就都 到 王 面前。以色列人 已经逃跑,各 回各家去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, ' 以色列 众 支派的 人 纷纷议论 说:「王 曾救我们 脱离仇敌 的手,又 救我们脱离 非利士人 的手,现在 他躲避 押沙龙 逃走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, '我们膏 押沙龙 治理我们,他 已经阵 亡。现在 为什么 不出一言 请 王 回来呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, '大卫 王 差 人去见 祭司 撒督 和 亚比亚他,说:「你们当 向 犹大 长老 说:『以色列 众人 已经有 话 请 王 回 宫,你们 为什么 落在他们后头呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, '你们是 我的弟兄,是 我的骨 肉, 为什么 在人后头 请 王 回来呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, '也要对亚玛撒 说:『你 不是 我的骨 肉吗?我若 不 立你替 约押 常 作 元帅,愿  神 重重地 降 罚 与我!』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, '如此就挽回 犹大 众 人 的心,如同一 人的心。他们便打发 人去见 王,说:「请王 和王的一切 臣仆 回来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, '王 就回来,到 了 约旦河。犹大人 来到 吉甲,要去 迎接 王,请 他 过约旦河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, '巴户琳的 便雅悯人、基拉 的儿子 示每 急忙 与 犹大 人 一同下去 迎接 大卫 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, '跟从 示每的有一千 便雅悯 人,还有扫罗 家 的仆人 洗巴 和 他十 五 个儿子,二十 个仆人;他们都逿过 约旦河 迎接 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, '有摆渡船 过去,渡 王 的家眷,任 王 使用。王要过 约旦河的时候,基拉 的儿子 示每 就俯伏 在王 面前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, '对 王 说:「我主 我王 出 耶路撒冷 的时候, 仆人 行悖逆的事,现在求我主 不要 因此加 罪 与仆人,不要 记念, 也不要放 在 心上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, ' 仆人 明知 自己 有罪, 所以约瑟 全 家之中,今日 我首先 下 来 迎接 我主 我王。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, '洗鲁雅 的儿子 亚比筛 说:「示每 既 咒骂 耶和华 的受膏者, 不 应当治死他吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, '大卫 说:「洗鲁雅 的儿子,我 与你们 有何关涉, 使你们 今日 与我 反对呢?今日 在以色列 中岂可治死 人呢?我岂 不 知 今日 我 作 以色列 的王吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, '于 是王 对 示每 说:「你必不 死。」王 就向他 起誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, '扫罗 的孙子 米非波设 也下去 迎接 王。他自从 王 去 的日子,直到 王平平安安地 回来,没有 修 脚,没有 剃 胡须,也没有 洗 衣服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, ' 他来到 耶路撒冷 迎接 王的时候,王 问他 说:「米非波设,你为什么 没有 与我 同去呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, '他回答说:「我主 我王, 仆人 是瘸腿的。那日我 想 要备 驴 骑 上,与 王 同去, 无奈我的仆人 欺哄了我, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, '又在 我主 我王 面前谗毁 我。然而我主 我王如同 神 的使者一般,你看 怎样好,就怎样行吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, '因为 我祖 全 家的人,在我主 我王 面前都算为 死 人,王却使 仆人 在王的席上 同人吃饭,我现在向 王 还 能 辨理 诉冤吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, '王 对他 说:「你何必 再 提 你的事呢?我说,你 与洗巴 均分 地土。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, '米非波设 对 王 说:「我主 我王 既 平平安安地 回 宫,就任凭洗巴都取了 也可以。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, '基列人 巴西莱 从罗基琳 下来,要送王 过 约旦河,就与 王 一同过了约旦河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, '巴西莱 年纪老 迈,已经八十 岁了。王住在 玛哈念的时候,他 就拿食物 来供给 王;他 原是 大 富 户。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, '王 对 巴西莱 说:「你 与我 同去,我要在耶路撒冷 那里养 你的老。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, '巴西莱 对 王 说:「我在世 的年日 还能有多少, 使我与 王 同上 耶路撒冷呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, ' 仆人 现在 八十 岁了,还能 尝出 饮 食的滋味、辨别 美 恶吗?还 能 听 男 女 歌唱的声音吗?仆人 何必 累赘 我主 我王呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, '仆人 只 要送 王 过 约旦河,王 何必 赐我 这样的 恩典呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, '求 你准我 回去,好死 在我本城,葬在 我父 母 的墓旁。这里有 王的仆人 金罕,让他同 我主 我王 过去,可以随 意 待 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, '王 说:「金罕 可以与我 同去,我 必照 你的心愿  待 他。你向我 求 什么,我都必为你 成就。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, '于 是众 民 过 约旦河,王 也过去。王 与巴西莱 亲嘴,为他祝福,巴西莱就回 本地去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, '王 过去,到了吉甲,金罕 也跟他 过去。犹大 众 民 和以色列 民 的一半 也 都送 王 过去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, ' 以色列 众 人 来 见 王,对 他 说:「我们弟兄 犹大 人 为什么 暗暗 送 王 和 王的家眷,并 跟随 王 的人 过 约旦河?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, '犹大 众 人 回答 以色列 人说:「因为 王 与我们 是亲属,你们为何 因 这 事 发怒呢?我们吃了 王 的什么呢?王 赏赐 了我们 什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, '以色列 人 回答 犹大 人 说:「按支派,我们 与王 有十 分的情分;在大卫身上,我们 也 比你们更有情分。你们为何 藐视我们,请 王 回来 不 先 与我们 商量呢?」但犹大 人 的话 比以色列 人 的话 更硬。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, '在那里 恰巧 有一个匪 徒,名 叫示巴,是便雅悯 人 比基利 的儿子。他吹 角,说:「我们 与大卫 无 分, 与耶西 的儿子 无 涉。以色列 人哪,你们各 回各家去吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, '于 是以色列 人 都 离开  大卫,跟随 比基利 的儿子 示巴。但犹大 人 从 约旦河 直到 耶路撒冷,都紧紧跟随 他们的王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, '大卫 王 来 到耶路撒冷,进了 宫殿,就把 从前 留下 看守 宫殿 的十 个妃 嫔 禁闭 在冷 宫,养活她们,不 与她们 亲近。她们 如同 寡妇 被禁,直到 死 的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, '王 对 亚玛撒 说:「你要在三 日 之内将 犹大 人 招聚 了来,你 也回 到这里来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, '亚玛撒 就去 招聚 犹大人,却耽延 过了 王所 限 的日期。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, '大卫 对 亚比筛 说:「现在 恐怕比基利 的儿子 示巴 加害 于 我们 比 押沙龙更甚。你 要带领 你主 的仆人 追 赶他,免得 他得了 坚固 城,躲避 我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, '约押 的人 和基利提人、比利提人,并所有的 勇士, 都跟著亚比筛,从耶路撒冷 出去 追 赶 比基利 的儿子 示巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, '他们 到了 基遍 的 大 磐石那里,亚玛撒 来 迎接他们。那时约押 穿著 战 衣, 腰 束 佩刀的带子,刀 在鞘内;约押 前行,刀从鞘内掉出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, '约押左手拾起刀来,对亚玛撒 说:「我兄弟,你 好啊!」 就用右 手 抓住 亚玛撒 的胡子,要与他 亲嘴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, '亚玛撒 没有 防备 约押 手 里所 拿的刀;约押用刀刺 入 他的肚腹,他的肠子 流在 地上,没有 再 刺他,就死了。约押 和他兄弟 亚比筛 往前追 赶 比基利 的儿子 示巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, '有约押 的一个 少年人 站 在亚玛撒尸身旁边,对众人说:「谁 喜悦 约押,谁 归顺大卫,就当跟随 约押去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, '亚玛撒 在道路 上 滚 在自己的血里。那人 见 众 民 经过 都站住,就把 亚玛撒 的尸身从 路上 挪 到田间,用 衣服 遮盖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, ' 尸身从 路上 挪移之后,众 民 就都跟 随 约押 去追 赶 比基利 的儿子 示巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, '他走 遍以色列 各 支派,直到伯‧玛迦 的亚比拉,并比利人 的全地;那些地方的人也 都聚集 跟 随他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, '约押和跟随的人到了伯‧玛迦 的亚比拉,围困 示巴,就对著 城 筑 垒;跟随 约押 的 众 民 用锤撞 城,要使城塌陷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, '有一个聪明 妇人 从 城 上呼叫 说:「听啊,听啊,请 约押 近前来,我好与他 说话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, '约押就近前 来,妇人 问他说:「你是 约押不是?」他说:「我是。」妇人说:「求你听 婢女 的话。」约押说:「我 听。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, '妇人说:「古时 有话 说,当 先在亚比拉 求问,然后 事就定妥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, '我们这城的人 在以色列 人中是和平、忠厚的。你 为何 要 毁坏 以色列 中的大 城,吞灭 耶和华 的产业呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, '约押 回答 说:「我 决 不 吞灭 毁坏, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, ' 乃因 以法莲 山地 的一个人─比基利 的儿子 示巴─举 手 攻击大卫 王,你们若将他 一人 交出来,我便离 城 而去。」妇人 对 约押 说:「 那人的首级 必从 城墙 上丢 给你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, '妇人 就凭她的智慧 去 劝 众 人。他们便割 下 比基利 的儿子 示巴 的首级,丢 给 约押。约押吹 角,众人就离 城 而散,各 归各家去了。约押 回 耶路撒冷,到 王那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, '约押 作 以色列 全 军的元帅;耶何耶大 的儿子 比拿雅 统辖 基利提人 和 比利提人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, '亚多兰 掌管 服苦的人;亚希律 的儿子 约沙法 作史官; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, '示法 作书记;撒督 和亚比亚他 作祭司长; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, ' 睚珥人 以拉 作 大卫的 宰相。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, '大卫 年间 有 饥荒,一 连 三 年,大卫 就求问 耶和华。耶和华 说:「这饥荒是因 扫罗 和 他流人血 之家 杀死 基遍人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, '原来这基遍人 不是 以色列 人,乃 是 亚摩利人 中所剩的;以色列 人 曾向他们 起誓,不杀灭他们,扫罗 却为以色列 人 和犹大人 发热心,想要 杀灭他们。大卫王 召 了他们来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, ' 问 他们 说:「我当为你们怎样 行呢?可用什么 赎这罪,使你们为 耶和华 的产业 祝福呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, '基遍人回答 说:「我们和 扫罗 与 他家 的事并不 关乎金 银,也不要 因我们 的缘故杀 一个 以色列人。」大卫说:「你们 怎样 说,我就为你们 怎样行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, '他们对 王 说:「那 从前谋害我们、 要灭我们、使我们不得再住 以色列 境内 的人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, '现在愿 将他的子孙 七 人 交 给我们,我们好在耶和华面前,将他们悬挂 在耶和华 拣选 扫罗 的基比亚。」王 说:「我 必交给你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, '王 因为 曾与 扫罗 的儿子 约拿单 指著耶和华 起誓结盟,就爱惜 扫罗 的孙子、约拿单 的儿子 米非波设,不交出来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, ' 却把 爱雅 的女儿 利斯巴 给扫罗 所 生 的两个 儿子 亚摩尼、 米非波设,和 扫罗 女儿 米甲 的姊姊给米何拉人 巴西莱 儿子 亚得列 所 生 的五个 儿子 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, '交 在基遍人 的手里。基遍人就把他们,在耶和华 面前,悬挂 在山上,这七人 就一同 死亡。 被杀 的时候正是收割 的日子,就是 动手 割 大麦的时候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, '爱雅 的女儿 利斯巴 用 麻布 在 磐石 上搭棚,从动手 收割 的时候直到 天 降 雨 在尸身上的时候,日间 不 容 空中 的雀鸟 落 在尸身上,夜间 不让 田野 的走兽前来糟践。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, '有人将 扫罗 的妃嫔 爱雅 女儿 利斯巴 所 行 的这事告诉 大卫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, '大卫 就去,从基列‧雅比 人 那里将 扫罗 和 他儿子 约拿单 的骸骨 搬了来(是因 非利士人从前 在基利波 杀 扫罗, 将尸身悬挂在伯‧珊 的街市上,基列‧雅比人 把尸身 偷了去。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, '大卫 将 扫罗 和 他儿子 约拿单 的骸骨 从那里 搬了来,又收殓 被悬挂 七人的骸骨, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, '将 扫罗 和他儿子 约拿单 的骸骨 葬 在 便雅悯 的洗拉,在扫罗父亲 基士 的坟墓里;众人行 了王 所 吩咐的。此 后 神 垂听 国民所求的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, ' 非利士人 与 以色列 人打仗;大卫 带领 仆人 下去,与 非利士人 接战 ,大卫 就疲乏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, '伟人 的 一个儿子以实‧比诺 要 杀 大卫;他的铜 枪 重 三 百 舍客勒,又 佩著 新刀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, '但洗鲁雅 的儿子 亚比筛 帮助 大卫,攻打 非利士人,将他杀死。当日,跟随大卫 的人 向大卫 起誓 说:「以后你不可 再 与我们 一同出 战 ,恐怕 熄灭 以色列 的灯。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, ' 后 来,以色列 人在歌伯 与 非利士人 打仗, 户沙人 西比该 杀了 伟人 的 一个儿子 撒弗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, '又 在歌伯 与 非利士人 打仗,伯利恒人 雅雷俄珥金 的儿子 伊勒哈难 杀了 迦特人 歌利亚。这人的枪 杆 粗如织布 的机轴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, '又 在迦特 打仗,那里有 一个身量高大 的人,手 脚 都是 六 指,共有 二十 四个指头;他 也是 伟人的 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, '这人向 以色列 人骂阵,大卫 的哥哥 示米亚 的儿子 约拿单 就杀了他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, ' 这 四 个人是迦特 伟人的 儿子,都死 在大卫 和他仆人 的手下。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, '当耶和华 救 大卫 脱离 一切 仇敌 和扫罗 之手 的日子,他 向耶和华 念 这 诗, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, '说:耶和华 是我的岩石,我的山寨,我的救主, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, '我的 神,我的磐石,我所投靠 的。他是我的盾牌,是拯救我 的角,是我的高台,是我的避难所。我的救主啊,你是救我 脱离强暴的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, '我要求告 当赞美 的耶和华,这样,我必从仇敌 手中被救出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, '曾有 死亡 的波浪 环绕我,匪类 的急流 使我惊惧, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, '阴间 的绳索 缠绕我,死亡 的网罗 临到我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, '我 在急难中 求告 耶和华,向我的 神 呼求。他从殿 中听了 我的声音;我的呼求 入了他的耳中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, '那时因 他 发怒,地 就摇撼 战 抖;天 的根基 也震动 摇撼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, '从他鼻孔 冒烟 上腾;从他口 中发火 焚烧,连炭 也著了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, '他又使天 下垂,亲自降临;有黑云 在他脚 下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, '他坐 著 基路伯 飞行,在 风 的翅膀 上显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, '他以黑暗 和聚集的 水、天空 的厚云 为 他四围 的行宫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, '因他面前 的光辉 炭 都著了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, '耶和华 从 天上 打雷;至高者 发出 声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, '他射出 箭来,使仇敌四散,发出闪电,使他们扰乱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, '耶和华 的斥责一发,鼻孔 的气 一出,海 底 就出现,大地 的根基 也显露。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, '他从高天 伸手 抓住我,把我从大 水 中拉上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, '他救我 脱离我的劲 敌 和那些恨我的人,因为 他们比我 强盛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, '我遭遇灾难 的日子,他们来攻击我;但耶和华 是 我的 倚靠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, '他又领 我 到宽阔之处;他救拔我,因 他喜悦 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, '耶和华 按著我的公义 报答我,按著我手 中的清洁 赏赐 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, '因为 我遵守 了耶和华 的道,未 曾作恶离开 我的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, ' 他的一切 典章 常在我面前;他的律例,我也未 曾离弃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, '我在他面前 作了 完全人;我也保守自己 远离我的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, '所以耶和华 按我的公义,按我在他眼 前 的清洁 赏赐 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, '慈爱的人,你以慈爱 待他;完全 的人,你以完全 待他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, '清洁的人,你以清洁 待他;乖僻的人,你以弯曲 待他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, ' 困苦的 百姓,你必拯救;但你的眼目 察看 高傲的人,使他降卑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, '耶和华啊, 你是 我的灯;耶和华 必照明 我的黑暗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, ' 我藉 借著你 冲 入敌军,藉 借著我的 神 跳过 墙垣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, '至于  神,他的道 是完全的;耶和华 的话 是炼净的。凡 投靠 他的,他 便作他们的盾牌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, '除了 耶和华, 谁是 神呢?除了我们的 神,谁 是磐石呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, '神 是我坚固的 保障;他引导 完全人 行他的路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, '他使 我的脚 快 如母鹿的蹄,又使我在 高处 安稳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, '他教导 我的手 能以争战 ,甚至我的膀臂 能开  铜 弓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, '你把你的救恩 给 我 作盾牌;你的温和 使我为大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, '你使我脚下 的地步 宽阔;我的脚 未 曾滑跌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, '我追赶 我的仇敌,灭绝了他们,未 灭以先,我没有 归回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, '我灭绝了他们,打伤了他们,使他们不能 起来;他们都倒 在我的脚 下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, '因为你曾以力量 束我的腰,使我能争战 ;你也使那起来 攻击我的都服 在我以下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, '你又使 我的仇敌 在我面前 转背逃跑,叫我能以剪除 那恨我的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, '他们仰望,却无人 拯救;就是呼求 耶和华,他也不 应允。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, '我捣碎他们,如同地上 的灰尘,践踏他们,四散在地,如同街上 的泥土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, '你救我 脱离我百姓 的争竞,保护我 作列国 的元首;我素不 认识 的民 必事奉我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, '外邦人 要投降 我,一听见 我的名声就必顺从 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, '外邦人 要衰残,战 战 兢兢地 出他们的营寨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, '耶和华是活 神,愿 我的磐石 被人称颂!愿  神─那拯救我 的磐石 被人尊崇! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, '这位 神 就是那为我 伸 冤、使众民 服 在我以下的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, '你救我 脱离仇敌,又把我举起,高过那些起来攻击我的;你救我 脱离强暴 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, '耶和华啊,因 此 我要在外邦 中称谢你,歌颂 你的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, '耶和华 赐极大的 救恩 给他所立的王,施 慈爱 给他的受膏者,就是给大卫 和他的后裔,直到 永远!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, '以下 是大卫 末了的 话。耶西 的儿子 大卫 得居 高位,是雅各 神 所膏的,作以色列 的美 歌者,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, '耶和华 的灵 藉 借著我 说:他的话 在 我口中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, '以色列的 神、以色列 的磐石 晓谕 我 说:那以公义 治理 人民的,敬畏 神 执掌权柄, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, '他必像日 出 的晨 光,如无 云 的清晨,雨后 的晴光,使地 发生嫩草。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, ' 我家 在 神 面前并非 如此; 神 却 与我 立 永远 的约。这约凡事 坚 稳, 关乎我的一切 救恩 和我一切 所想望的,他岂 不 为我成就吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, '但匪类 都 必像荆棘 被丢弃; 人不敢 用手 拿它; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, '拿 它 的人 必带 铁器 和枪 杆,终久它必 被火 焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, '大卫 勇士 的 名字 记在下面:他革扪人约设‧巴设, 又称伊斯尼人 亚底挪,他是军长的统领,一 时 击杀 了 八 百人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, '其次 是亚合人 朵多 的儿子 以利亚撒。从前非利士人聚集 要打仗,以色列 人 迎著上去,有跟随 大卫 的三 个勇士 向非利士人 骂阵,其中有以利亚撒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, '他 起来 击杀 非利士人,直到 手臂 疲乏,手 黏 住 刀把。那 日 耶和华 使 以色列 人大 获全胜;众民 在以利亚撒后头 专 夺财物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, '其次 是哈拉人 亚基 的儿子 沙玛。一日,非利士人 聚集 成群,在一块 长满 红豆 的田里,众民 就在非利士人 面前 逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, '沙玛却站 在那田 间 击杀 非利士人,救护了那田。耶和华 使 以色列人大 获全胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, ' 收割的时候,有三十 个勇士 中的三 个人下 到 亚杜兰 洞 见 大卫。非利士 的军兵 在利乏音 谷 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, '那时 大卫 在山寨,非利士人 的防营 在伯利恒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, '大卫 渴想,说:「甚愿 有人 将伯利恒 城门旁、 井 里的水 打来给我喝。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, '这三 个勇士 就闯过 非利士人 的营盘,从伯利恒 城门 旁的 井 里打 水,拿来 奉 给 大卫。他却不 肯 喝,将水 奠 在耶和华面前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, '说:「耶和华啊,这三个人冒死 去打水;这水好像他们 的血一般,我 断 不敢喝。」如此,大卫不 肯 喝。这是 三 个勇士 所做的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, '洗鲁雅 的儿子、约押 的兄弟 亚比筛 是 这三 个勇士的首领;他 举 枪 杀 了 三 百人,就在三 个勇士里得了名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, '他在 这三 个勇士里是最 尊贵的,所以作 他们的 首领,只是不 及 前三个勇士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, '有甲薛 勇士 耶何耶大 的儿子 比拿雅 行过大能 的事;他 杀了 摩押人 亚利伊勒 的两个儿子,又 在下雪 的时候 下 坑 里去,杀了 一个狮子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, '又 杀了 一个强壮 的埃及 人;埃及人 手 里拿著枪,比拿雅只拿著棍子 下去,从埃及人 手 里夺过 枪来,用那枪 将他杀死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, '这是 耶何耶大 的儿子 比拿雅 所行的事,就在三 个勇士 里得了名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, '他比 那三十 个勇士都尊贵,只是不 及 前 三个勇士。大卫 立他 作 护卫长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, '三十 个勇士里有约押 的兄弟 亚撒黑,伯利恒人 朵多 的儿子 伊勒哈难, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, '哈律人 沙玛,哈律人 以利加, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, '帕勒提人 希利斯,提哥亚人 益吉 的儿子 以拉, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, '亚拿突人 亚比以谢,户沙人 米本乃, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, '亚合人 撒们,尼陀法人 玛哈莱, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, '尼陀法人 巴拿 的儿子 希立,便雅悯 族、基比亚人 利拜 的儿子 以太, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, '比拉顿人 比拿雅,迦实 溪 人希太, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, '伯亚拉巴人 亚比亚本,巴鲁米人 押斯玛弗, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, '沙本人 以利雅哈巴,雅善 儿子 中的约拿单, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, '哈拉人 沙玛,哈拉人 沙拉 的儿子 亚希暗, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, '玛迦人 亚哈拜 的儿子 以利法列,基罗人 亚希多弗 的儿子 以连, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, '迦密人 希斯莱,亚巴人 帕莱, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, '琐巴人 拿单 的儿子 以甲,迦得人 巴尼, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, '亚扪人 洗勒,比录人 拿哈莱(是给洗鲁雅 的儿子 约押 拿 兵器的), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, '以帖人 以拉,以帖人 迦立, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, '赫人 乌利亚,共有 三十 七人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, '耶和华 又 向以色列 人发 怒,就激动 大卫,使他吩咐 人去 数点 以色列 人和 犹大人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, '大卫 就吩咐 跟随他 的 元帅 约押说:「你 去走遍 以色列 众 支派,从但 直到 别是巴,数点 百姓,我好知道 他们 的数目。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, '约押 对 王 说:「无论 百姓 多少,愿 耶和华─你的 神 再加增 百 倍,使我主 我王 亲眼 得见。我主 我王 何必 喜悦 行这 事呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, '但王 的命令 胜 过 约押 和 众军 长。约押 和众军 长 就从王 面前 出去,数点 以色列的 百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, '他们过了 约旦河,在迦得 谷 中、城 的 右边 亚罗珥 安营,与雅谢 相对, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, '又到 了基列 和他停‧合示 地,又到了但‧雅安,绕 到 西顿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, '来到 泰尔 的保障,并希未人 和迦南人 的各 城,又到 犹大 南方 的别是巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, '他们走 遍全 地,过了 九 个月 零二十 天,就回到 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, '约押 将 百姓 的总 数 奏告 于  王:以色列 拿 刀 的勇 士 有 八 十万;犹大 有五 十万。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, '大卫 数点 百姓 以后,就心 中自责, 祷告 耶和华 说:「我行这事 大 有罪了。 耶和华啊,求 你除掉 仆人 的罪孽,因 我所行的甚是 愚昧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, '大卫 早晨 起来,耶和华 的话 临 到 先知 迦得,就是大卫 的先见,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, '「你去 告诉 大卫,说耶和华 如此 说:『我 有 三样灾,随你 选择 一 样,我好降 与你。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, '于 是迦得 来 见 大卫,对他 说:「你愿 意国中 有 七 年 的饥荒呢?是 在你敌人 面前 逃跑,被 追赶 三 个月呢?是 在你国中 有 三 日 的瘟疫呢?现在 你要揣摩 思想, 我好回 覆 复 那差我来的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, '大卫 对 迦得 说:「我 甚 为难!我愿  落 在耶和华 的手里,因为 他有丰盛的 怜悯。我不 愿 落 在人 的手里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, '于 是,耶和华 降 瘟疫 与以色列人,自早晨 到 所定的 时候;从但 直到 别是巴, 民间 死 了七万 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, '天使 向耶路撒冷 伸 手 要灭城的时候,耶和华 后悔,就 不降这灾了,吩咐 灭 民 的天使说:「够了! 住 手吧!」那时耶和华 的使者 在 耶布斯人 亚劳拿 的禾场那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, '大卫 看见 灭 民 的天使,就祷告 耶和华 说:「 我 犯了罪, 行了恶;但这 群羊 做 了什么呢?愿  你的手 攻击我 和我的父 家。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, '当 日,迦得 来 见 大卫,对他 说:「你上去,在耶布斯人 亚劳拿 的禾场 上为耶和华 筑 一座坛。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, '大卫 就照著迦得 奉耶和华 名所 说 的话 上去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, '亚劳拿 观看,见 王 和 他臣仆 前来, 就迎接出去,脸 伏于 地,向王 下拜, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, ' 说:「我主 我王 为何 来 到 仆人这里呢?」大卫 说:「我要买  你 这禾场,为耶和华 筑 一座坛,使 民间 的瘟疫 止住。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, '亚劳拿 对 大卫 说:「我主 我王,你 喜悦用什么,就拿去 献祭。看哪,这里有牛 可以作燔祭,有打粮的器具 和套牛 的轭 可以当柴烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, '王啊,这一切,我亚劳拿 都奉 给你」; 又对 王 说:「愿 耶和华─你的 神 悦纳你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, '王 对 亚劳拿 说:「不然。 我必 要按著价值 向你 买 ;我不肯 用白得 之物作燔祭 献 给耶和华─我的 神。」大卫 就用五十 舍客勒 银子 买  了 那禾场 与 牛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, '大卫 在那里 为耶和华 筑 了一座坛,献 燔祭 和平安祭。如此,耶和华 垂听国民 所求的,瘟疫 在 以色列 人中就止住了。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, '大卫 王 年纪 老 迈,虽用被 遮盖,仍不 觉暖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, '所以臣仆 对他 说:「不如为我主 我王 寻找 一个处女,使她伺候 王, 奉养 王,睡 在王的怀中,好叫我主 我王 得暖。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, '于 是在以色列 全 境 寻找 美貌 的童女,寻得 书念 的一个童女亚比煞,就带 到王那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, '这童女 极 其 美貌,她 奉养 王,伺候王,王 却没有 与她亲近。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, '那时,哈及 的儿子 亚多尼雅 自尊,说:「我 必作王」,就为自己 预备 车辆、马兵,又派五十 人 在他前头 奔走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, '他父亲 素来 没有 使他忧闷,说:「 你是做 什么呢?」 他 甚 俊 美, 生 在押沙龙 之后。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, '亚多尼雅 与 洗鲁雅 的儿子 约押,和 祭司 亚比亚他 商议;二人就顺从他,帮助他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, '但祭司 撒督、耶何耶大 的儿子 比拿雅、先知 拿单、示每、利以,并 大卫的 勇士 都不 顺从 亚多尼雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, '一日,亚多尼雅在隐‧罗结 旁、 琐希列 磐石 那里 宰了 牛 羊、肥犊,请 他的诸 弟兄,就是王 的众子,并所有 作王 臣仆 的犹大 人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, '惟独 先知 拿单 和比拿雅 并 勇士,与 他的兄弟 所罗门,他都没有 请。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, '拿单 对 所罗门 的母亲 拔示巴 说:「 哈及 的儿子 亚多尼雅 作王了,你没有 听见吗?我们的主 大卫 却不 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, '现在 我可以 给你出个 主意,好保全 你 和你儿子 所罗门 的性命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, '你进 去 见 大卫 王,对他 说:『我主 我王啊,你 不 曾向婢女 起誓 说:你儿子 所罗门 必 接续我 作王, 坐 在 我的位上吗?现在亚多尼雅 怎么 作了王呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, ' 你还 与 王 说话 的时候,我 也随后 进去,证实 你的话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, '拔示巴 进 入内室 见 王,王 甚 老迈,书念 的童女亚比煞 正伺候 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, '拔示巴 向王 屈身 下拜;王 说:「你 要什么?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, '她说:「我主啊,你 曾向婢女 指著耶和华─你的 神 起誓 说:『你儿子 所罗门 必接续我 作王, 坐 在 我的位上。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, '现在 亚多尼雅 作王了, 我主 我王 却不 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, '他宰了 许多 牛 羊、肥犊,请了 王 的众 子 和祭司 亚比亚他,并元帅 约押;惟独王的仆人 所罗门,他没有 请。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, ' 我主 我王啊,以色列 众人 的眼目 都仰望你,等你晓谕 他们,在我主 我王 之后 谁 坐 你的位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, '若不然,到 我主 我王 与 列祖 同睡以后,我 和我儿子 所罗门 必算为 罪人了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, ' 拔示巴还 与 王 说话的时候,先知 拿单 也进来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, '有人奏告 王 说:「 先知 拿单来了。」拿单进 到王 前, 脸 伏 于 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, '拿单 说:「我主 我王 果然应许亚多尼雅 说『你必接续我 作王, 坐 在 我的位上』吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, ' 他今日 下去,宰了 许多 牛 羊、肥犊,请了 王 的众 子 和军 长,并祭司 亚比亚他;他们 正在亚多尼雅面前 吃 喝,说:『愿 亚多尼雅 王 万岁!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, '惟独 我,就是你的仆人 和祭司 撒督,耶何耶大 的儿子 比拿雅,并王的仆人 所罗门,他都没有 请。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, '这 事 果然 出乎 我主 我王吗?王却没有 告诉 仆人们,在我主 我王 之后 谁 坐 你的位。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, '大卫 王 吩咐 说:「叫 拔示巴来。」拔示巴就进来,站 在王 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, '王 起誓 说:「我指著救 我性命 脱离一切 苦难、 永生 的耶和华起誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, '我既然 指著耶和华─以色列的 神 向你 起誓 说:你儿子 所罗门 必 接续我 作王, 坐 在 我的位上。我今 日 就必 照这话 而行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, '于 是,拔示巴 脸 伏 于 地,向王 下拜,说:「愿 我主 大卫 王 万 岁!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, '大卫 王 又吩咐说:「将祭司 撒督、先知 拿单、耶何耶大 的儿子 比拿雅 召来!」他们就都来 到王 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, '王 对他们 说:「要带 领 你们主 的仆人,使 我儿子 所罗门 骑 我的 骡子,送他 下 到 基训; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, '在那里,祭司 撒督 和先知 拿单 要膏 他 作 以色列 的王;你们也要吹 角,说:『愿 所罗门 王 万岁!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, '然后要跟随他 上来, 使他坐 在 我的位上, 接续我 作王。我已立 他 作 以色列 和 犹大 的君。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, '耶何耶大 的儿子 比拿雅 对 王 说:「阿们!愿 耶和华─我主 我王的 神 也这样 命定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, '耶和华 怎样 与 我主 我王 同在,愿 他照样 与 所罗门 同在,使 他的国位 比我主 大卫 王 的国位 更大。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, '于 是,祭司 撒督、先知 拿单、耶何耶大 的儿子 比拿雅,和基利提人、比利提人 都下去 使 所罗门 骑 大卫 王 的骡子,将他 送 到 基训。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, '祭司 撒督 就从 帐幕 中取了 盛膏油 的角来,用膏膏 所罗门。人就吹 角,众 民 都说:「愿 所罗门 王 万岁!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, '众 民 跟随他 上来, 且吹 笛,大大 欢 呼,声音 震 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, '亚多尼雅 和 所 请 的众客 筵宴方 毕,听见这声音;约押 听见 角 声 就说:「城 中为何 有这响 声呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, '他正 说话的时候, 祭司 亚比亚他 的儿子 约拿单 来了。亚多尼雅 对他说:「进来吧! 你 是个忠义 的人,必是报好 信息。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, '约拿单 对亚多尼雅 说:「我们的主 大卫 王 诚然 立 所罗门 为王了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, '王 差遣 祭司 撒督、 先知 拿单、 耶何耶大 的儿子 比拿雅,和基利提人、比利提人 都去使 所罗门骑 王 的骡子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, '祭司 撒督 和先知 拿单 在基训 已经膏 他 作王。众人都从那里 欢呼 著上来,声音使城 震动,这就是 你们所 听见 的声音; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, '并且 所罗门 登了 国 位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, '王 的臣仆 也 来 为 我们的主 大卫 王 祝福,说:『愿 王的 神 使 所罗门 的名 比王的名 更尊荣;使 他的国位 比王的国位 更大。』王 就在 床 上屈身下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, '王 又 说:『耶和华─以色列的 神 是应当称颂的;因他 赐 我一人今日 坐 在 我的位上,我也亲眼 看见了。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, '亚多尼雅的 众 客 听见这话就都惊惧,起来 四散。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, '亚多尼雅 惧怕 所罗门,就起来,去 抓住 祭坛 的角。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, '有人告诉 所罗门 说:「 亚多尼雅 惧怕 所罗门 王,现在 抓住 祭坛 的角,说:『愿 所罗门 王 今日 向我 起誓,必不 用刀 杀 仆人。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, '所罗门 说:「他若 作 忠义 的人,连一根头发 也不致 落 在地上;他若 行恶,必要死亡。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, '于 是所罗门 王 差遣人,使亚多尼雅从 坛 上下来,他就来,向所罗门 王 下拜;所罗门 对他 说:「你回家 去吧!」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, '大卫 的死 期 临近了,就嘱咐 他儿子 所罗门 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, '「我 现在要走 世人 必走的路。所以,你当刚强,作 大丈夫, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, '遵守 耶和华─你 神 所吩咐的,照著摩西 律法 上所写 的行 主的道,谨守 他的律例、诫命、典章、法度。这样, 你无论 做 什么事, 不拘 往何 处 去,尽都亨通。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, ' 耶和华 必成就 向我 所 应许 的话 说:『你的子孙 若 谨慎 自己的行为,尽 心 尽 意 诚诚实实 地行 在我面前, 就不 断 人 坐 以色列 的国位。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, ' 你 知道 洗鲁雅 的儿子 约押 向我 所 行的,就是 杀了 以色列 的两 个元帅:尼珥 的儿子 押尼珥 和益帖 的儿子 亚玛撒。他在太平 之时流 这二人的血,如在争战 之时一样,将这 血 染了 腰 间束的 带 和脚 上穿的 鞋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, '所以你要照你的智慧 行,不容 他白头 安然 下 阴间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, '你当恩 待 基列人 巴西莱 的众子,使他们 常与你同席 吃饭;因为 我躲避 你哥哥 押沙龙的时候,他们拿食物 来迎接 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, ' 在你 这里有巴户琳的 便雅悯 人,基拉 的儿子 示每;我往玛哈念 去 的那日,他 用狠毒 的言语 咒骂我, 后来却下 约旦河 迎接我,我就指著耶和华 向他 起誓 说:『我必 不用刀 杀你。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, '现在 你不要 以他为无罪。 你是 聪明 人,必知道 怎样 待 他,使 他白头见杀,流血 下到 阴间。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, '大卫 与 他列祖 同睡,葬 在大卫 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, ' 大卫 作 以色列 王 四十 年:在希伯仑  作王 七 年,在耶路撒冷 作王 三十 三 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, '所罗门 坐 他父亲 大卫 的位,他的国 甚 是坚固。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, '哈及 的儿子 亚多尼雅 去 见 所罗门 的母亲 拔示巴,拔示巴问他说:「你来 是为平安吗?」回答说:「是为平安」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, '又说:「我有 话 对你说。」拔示巴说:「你说吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, '亚多尼雅说:「你 知道 国 原是 归我的,以色列 众人 也都仰望 我 作王,不料,国 反 归了 我兄弟,因 他 得国是 出乎耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, '现在 我 有一 件事 求 你,望你不要 推辞。」拔示巴说:「你说吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, '他说:「求 你请 所罗门 王 将 书念 的女子亚比煞 赐 我 为妻,因 他必不 推辞 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, '拔示巴 说:「好,我 必为你 对 王 提说。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, '于 是,拔示巴 去 见 所罗门 王,要为 亚多尼雅 提说;王 起来 迎接,向她 下拜,就坐 在 位上,吩咐人为王 母 设 一座位,她便坐 在王的右边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, '拔示巴说:「我 有一件 小 事 求 你,望你不要 推辞。」王 说:「请母亲 说, 我必不 推辞。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, '拔示巴说:「求你将 书念 的女子亚比煞 赐 给你哥哥 亚多尼雅 为妻。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, '所罗门 王 对他母亲 说:「 为何 单替他 求 书念 的女子亚比煞呢?也可以为他 求 国吧! 他是 我的 哥哥,他有 祭司 亚比亚他 和洗鲁雅 的儿子 约押为辅佐。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, '所罗门 王 就指著耶和华 起誓 说:「亚多尼雅 这 话 是 自己送命,不然,愿  神 重重地 降 罚 与我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, '耶和华 坚立我,使我坐 在 父亲 大卫 的位上, 照著所 应许 的话为我 建立 家室;现在 我指著永生 的耶和华起誓,亚多尼雅 今日 必 被治死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, '于 是所罗门 王 差遣 耶何耶大 的儿子 比拿雅,将亚多尼雅 杀 死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, '王 对祭司 亚比亚他 说:「你回 亚拿突 归 自己的田地去吧!你 本是 该死 的,但因 你在我父亲 大卫 面前 抬过 主 耶和华 的约柜,又 与我父亲 同受 一切 苦难,所以我今 日 不 将你杀死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, '所罗门 就革除 亚比亚他,不许他作 耶和华的 祭司。这样,便应验 耶和华 在示罗 论 以利 家 所 说 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, '约押 虽然没有 归 从 押沙龙,却 归 从了 亚多尼雅。他 听见这 风声, 就逃 到 耶和华 的帐幕,抓 住祭坛 的角。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, '有人告诉 所罗门 王说:「 约押 逃 到 耶和华 的帐幕,现今 在祭坛 的旁边。」所罗门 就差遣 耶何耶大 的儿子 比拿雅,说:「你去 将他 杀死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, '比拿雅 来 到 耶和华 的帐幕,对约押 说:「王吩咐 说,你出来吧!」他说:「我不出去, 我要死 在这里。」比拿雅 就去回复 王,说 约押 如此 如此 回答我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, '王 说:「你可以照著 他的话 行,杀 死他,将他葬埋,好叫约押 流 无辜 人血 的罪 不归 我 和 我的父 家了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, '耶和华 必使 约押流人血 的罪归 到 他自己的头上;因为他 用刀 杀了 两个 比他 又义 又好 的人,就是 以色列 元帅 尼珥 的儿子 押尼珥 和 犹大 元帅 益帖 的儿子 亚玛撒,我父亲 大卫 却不 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, '故此,流这二人血 的罪必归 到约押 和他后裔 的头上,直到永远;惟有大卫 和他的后裔,并他的家 与国,必从 耶和华 那里得 平安,直到 永远。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, '于 是耶何耶大 的儿子 比拿雅 上去, 将约押 杀死,葬 在旷野约押自己的坟墓(原文是房屋)里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, '王 就立 耶何耶大 的儿子 比拿雅 作 元帅,代替约押, 又 使 祭司 撒督 代替 亚比亚他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, '王 差遣 人将示每 召来,对他 说:「你要在耶路撒冷 建造 房屋 居住,不可 出来 往别 处去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, '你当 确实地 知道, 你何日 出来 过 汲沦 溪,何日必 死!你的罪(原文是血)必归 到自己的头上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, '示每 对王 说:「这话 甚好!我主 我王 怎样 说,仆人 必怎样 行。」于 是示每 多 日 住 在耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, ' 过了 三 年,示每的 两个 仆人 逃 到 迦特 王 玛迦 的儿子 亚吉那里去。有人告诉 示每 说:「 你的仆人 在迦特。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, '示每 起来,备 上 驴,往 迦特 到 亚吉 那里去找 他的仆人, 就从迦特 带 他仆人回来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, '有人告诉 所罗门说:「示每 出耶路撒冷 往迦特 去,回来了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, '王 就差遣 人将示每 召了来,对他 说:「我岂不是 叫你指著耶和华 起誓,并且警戒 你 说『你当确实地 知道, 你哪日 出来 往别 处 去,那日必 死』吗?你也对我 说:『这话 甚好,我必听从。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, '现在你为何 不 遵守 你指著耶和华 起的誓 和 我所 吩咐 你 的命令呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, '王 又对 示每 说:「你 向我父亲 大卫 所 行 的一切 恶事, 你自己 心 里也知道,所以耶和华 必使 你的罪恶 归 到自己的头上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, '惟有所罗门 王 必得福,并且大卫 的国位 必 在耶和华 面前 坚定,直到 永远。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, '于 是王 吩咐 耶何耶大 的儿子 比拿雅,他就去 杀 死 示每。这样,便坚定了 所罗门 的国位。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, '所罗门 与 埃及 王 法老 结亲,娶了 法老 的女儿为妻,接她 进入 大卫 城,直等到 造 完了 自己的宫 和 耶和华 的殿,并 耶路撒冷 周围 的城墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, '当 那些 日子,百姓 仍 在邱坛 献祭,因为 还没有 为耶和华 的名 建 殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, '所罗门 爱 耶和华,遵行 他父亲 大卫 的律例,只是 还在邱坛 献祭 烧香。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, '所罗门王 上基遍 去 献祭;因为 在那里有 极大(或译:出名)的邱坛,他 在 那 坛 上献 一千 牺牲作燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, '在基遍,夜 间梦中,耶和华 向 所罗门 显现, 对他说:「你愿 我赐 你 什么?你可以求。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, '所罗门 说:「你仆人─我父亲 大卫 用诚实、公义、正直 的心 行 在你面前,你 就向他 大 施 恩典,又为他 存留 大 恩,赐 他 一个儿子 坐 在 他的位上,正如今 日一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, '耶和华─我的 神啊,如今 你 使 仆人 接续 我父亲 大卫 作王;但我 是幼 童,不 知道 应当怎样出 入。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, '仆人 住在你所 拣选 的民 中,这 民 多 得 不可 胜 数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, '所以求你赐 我 智慧,可以判断 你的民,能辨别 是 非。不然,谁 能 判断 这 众多的 民呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, '所罗门 因为 求 这 事, 就蒙主 喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, '神 对他 说:「你既 然 求 这 事,不 为自己 求 寿、 求 富,也不 求 灭绝你仇敌 的性命,单求 智慧 可以听 讼, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, '我就 应允你 所求的, 赐 你 聪明 智慧,甚至 在你以前 没 有 像你的,在你以后 也没有 像你的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, '你所 没有 求的,我也 赐 给你,就是 富足、 尊荣,使你在世的 日子,列王中 没 有 一个 能比你的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, '你若 效法 你父亲 大卫,遵行 我的道,谨守 我的律例、诫命,我必使你长 寿。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, '所罗门 醒了,不料 是个梦。他就回到 耶路撒冷,站 在耶和华 的约 柜 前,献 燔祭 和 平安祭,又为他众 臣仆 设摆 筵席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, '一日,有两个 妓 女 来,站 在 王 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, '一个 说:「我主 啊,我 和这 妇人 同住 一 房;她 在房中的时候,我生了一个男孩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, ' 我生 孩子后第三 日,这 妇人 也 生了孩子。我们 是同住的, 除了 我们 二人之外,房 中再没有 别人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, '夜间,这 妇人睡著的时候, 压 死 了她的孩子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, '她半 夜 起来,趁我 睡著,从我旁边 把 我的孩子 抱去,放 在她怀里,将 她的死 孩子 放 在我怀里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, '天要亮的时候,我起来 要给 我的孩子 吃奶,不料,孩子死了;及至天亮,我细细地察看, 不 是 我所生 的 孩子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, '那 妇人 说:「不然, 活 孩子是我的,死 孩子是你的。」这 妇人说:「不然, 死 孩子是你的,活 孩子是我的。」她们在王 面前 如此争论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, '王 说:「这 妇人说『 活 孩子是我的,死 孩子是你的』,那 妇人说『不然, 死 孩子是你的,活 孩子是我的』」, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, ' 就吩咐说:「拿 刀来!」人就拿 刀 来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, '王 说:「将 活 孩子 劈 成两半, 一半 给 那妇人, 一半 给这妇人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, '活 孩子 的 母亲 为 自己的孩子 心 里急痛,就说:「求 我主 将 活 孩子 给 那妇人吧,万 不可 杀他!」那 妇人说:「这孩子 也 不 归我,也 不归你,把他劈了吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, '王 说:「将 活 孩子 给 这妇人,万 不可 杀他;这妇人实在是 他的母亲。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, '以色列 众人 听见 王这样 判断,就都敬畏 他;因为 见 他心里有 神 的智慧,能以断 案。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, ' 所罗门 作 以色列 众人 的王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, '他的 臣子 记在下面: 撒督 的儿子 亚撒利雅作祭司, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, '示沙 的两个儿子 以利何烈、亚希亚 作书记,亚希律 的儿子 约沙法 作史官, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, '耶何耶大 的儿子 比拿雅 作 元帅,撒督 和亚比亚他 作祭司长, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, '拿单 的儿子 亚撒利雅 作 众吏长,王 的朋友 拿单 的儿子 撒布得 作领袖, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, '亚希煞 作 家宰,亚比大 的儿子 亚多尼兰 掌管 服苦的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, '所罗门 在 以色列 全 地立了十 二 个官吏,使他们供给 王 和 王家 的食物,每年 各人 供给 一月。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, '他们的名字 记在下面:在以法莲 山地有便‧户珥; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, '在玛迦斯、沙宾、伯‧示麦、以伦‧伯‧哈南有便‧底甲; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, '在亚鲁泊有便‧希悉,他管理 梭哥 和希弗 全 地; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, '在多珥 山冈(或译:全境)有便‧亚比拿达,他 娶了 所罗门 的女儿 她法 为妻; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, '在他纳 和米吉多,并靠近 撒拉他拿、耶斯列 下边的伯.善 全地,从伯.善 到亚伯.米何拉 直到 约念 之外,有亚希律 的儿子 巴拿; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, '在基列 的拉末有便‧基别,他管理 在基列 的 玛拿西 子孙 睚珥 的城邑, 巴珊 的亚珥歌伯 地 的大 城 六十座,都有城墙 和铜 闩; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, '在玛哈念 有易多 的儿子 亚希拿达; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, '在拿弗他利 有亚希玛斯,他 也 娶了 所罗门 的一个女儿 巴实抹 为妻; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, '在亚设 和亚禄 有户筛 的儿子 巴拿; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, '在以萨迦 有帕路亚 的儿子 约沙法; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, '在便雅悯 有以拉 的儿子 示每; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, '在基列 地,就是从前属亚摩利 王 西宏 和巴珊 王 噩 之地,有乌利 的儿子 基别 一人 管理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, '犹大人 和以色列人 如同海 边 的 沙 那样多,都吃 喝 快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, ' 所罗门 统管 诸 国,从 大河 到非利士 地,直到 埃及 的边界。所罗门 在世 的日子,这些国都进 贡 服事 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, ' 所罗门 每 日 所用的食物:细面 麺 三十 歌珥,粗面 麺 六十 歌珥, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, '肥 牛 十只,草场 的牛 二十只,羊 一百只,还有 鹿、羚羊、麃子,并肥 禽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, ' 所罗门 管理 大河 西边 的诸 王,以及从提弗萨 直到 迦萨 的全地, 四 境 尽 都平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, '所罗门 在世的日子,从但 到 别是巴 的犹大人 和以色列人 都在自己的葡萄树 下 和无花果树 下 安然 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, ' 所罗门有 套车的 马 四万,还有马兵 一万二 千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, '那 十二个官吏 各 按各月供给 所罗门 王,并 一切 与 他 同席 之人的食物,一 无 所缺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, '众人各 按各分,将养马 与快马 的大麦 和干草 送 到 官吏那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, '神 赐 给所罗门 极 大 的智慧 聪明 和广大 的心,如同 海 沙不可测量。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, '所罗门 的智慧 超过 东方 人 和 埃及人 的一切 智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, '他的智慧 胜过万 人,胜过以斯拉人 以探,并玛曷 的儿子 希幔、甲各、达大的智慧。他的名声 传扬 在四围 的列 国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, '他作 箴言 三 千句, 诗歌 一千 零五首。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, '他讲 论 草木,自 黎巴嫩 的 香柏树 直到 墙 上长 的 牛膝草,又讲 论 飞禽 走兽、 昆虫 水族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, ' 天下 列 王 听见 所罗门 的智慧,就都 差人 来 听 他的智慧话。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, ' 泰尔 王 希兰,平素 爱 大卫; 他听见 以色列人膏 所罗门,接续 他父亲 作王, 就差遣 臣仆 来见他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, '所罗门 也差遣 人去见 希兰,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, '「你 知道 我父亲 大卫 因 四围 的 争战 ,不 能 为耶和华─他 神 的名 建 殿,直等到 耶和华 使仇敌 都服 在 他脚下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, '现在 耶和华─我的 神 使我 四围 平安,没有 仇敌,没有 灾 祸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, '我 定意 要为耶和华─我 神 的名 建 殿,是照 耶和华 应许 我父亲 大卫 的话说:『我必使 你儿子 接续你 坐 你的位,他 必为我的名 建 殿。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, '所以 求你吩咐 你的仆人在 黎巴嫩 为我 砍伐 香柏木,我的仆人 也必 帮助 他们,我必照 你所 定的,给 你仆人 的工价;因为 你 知道, 在我们中间 没有 人 像西顿人 善 于 砍伐 树木。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, ' 希兰 听见 所罗门 的话,就甚 喜悦,说:「今日 应当称颂 耶和华;因他 赐 给大卫 一个有智慧 的儿子,治理 这 众多 的民。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, '希兰 打发 人去见 所罗门,说:「你差遣 人向我 所提的那事,我都听见了;论到香柏 木 和松 木,我 必照 你的心愿  而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, '我的仆人 必将这木料从 黎巴嫩 运 到海里, 扎 成筏子,浮海 运到 你所 指定 我 的地方,在那里 拆开 ,你 就可以收取;你 也要成全 我的心愿 ,将食物 给 我的家。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, '于 是 希兰 照著所罗门所 要的,给 他 香柏 木 和松 木; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, '所罗门 给 希兰 麦子 二万 歌珥,清 油 二十 歌珥,作他家的 食物。所罗门 每年 都是这样 给 希兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, '耶和华 照著所 应许的 赐 智慧 给所罗门。 希兰 与 所罗门 和好,彼此 立 约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, '所罗门 王 从 以色列人 中挑取 服苦的人 共有 三万, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, '派他们 轮流 每月 一万 人上黎巴嫩去; 一个月 在黎巴嫩,两个 月 在家里。亚多尼兰 掌管 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, '所罗门 用 七万 扛抬的,八万 在山 上凿石头的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, '此外,所罗门 用三 千 三 百 督 工 的,监管 工 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, '王 下令,人就凿出 又大 又宝贵 的石头来,用以立 殿 的根基。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, '所罗门 的匠人 和希兰 的匠人,并迦巴勒人,都将石头凿好,预备 木料 和石头 建 殿。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, ' 以色列 人 出 埃及 地 后四 百 八十 年,所罗门 作 以色列 王 第四 年 西弗 月,就是 二 月,开 工建造 耶和华的 殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, '所罗门 王 为耶和华 所 建 的殿,长 六十 肘,宽 二十肘,高 三十 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, ' 殿 前 的廊子 长 二十 肘,与殿 的 宽窄一样, 阔 十 肘; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, '又为殿 做 了严紧 的窗 櫺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, ' 靠著 殿 墙, 围著 外殿 内殿,造了 三层旁屋; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, '下 层 宽 五 肘,中 层宽 六 肘,上 层宽 七 肘。 殿 外 旁屋的梁木搁 在殿墙 坎上,免得 插入 殿 墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, '建 殿 是用山中凿 成 的石头。建 殿的时候,锤子、斧子,和别样铁 器 的响声都 没有 听见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, '在 殿 右 边 当中 的旁屋 有门,门内有旋螺的楼梯,可以上 到 第二层,从 第二 层可以上到 第三层。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, '所罗门建 殿,安置香柏木的栋梁,又用香柏木 板 遮盖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, '靠著 殿 所造 的旁屋,每层高 五 肘,香柏 木 的栋梁搁 在殿墙坎上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, '耶和华 的话 临 到 所罗门 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, '「论到你 所 建 的这 殿,你若 遵行 我的律例,谨守 我的典章,遵从 我的一切 诫命,我必向你 应验 我所 应许 你父亲 大卫 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, '我必住 在以色列 人 中间,并不 丢弃 我民 以色列。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, '所罗门 建造 殿宇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, '殿 里面 用香柏木 板 贴 墙, 从地 到 棚 顶 都用木板 遮蔽,又用松木 板 铺 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, ' 内 殿,就是至 圣 所, 长二十 肘,从 地 到 棚 顶用香柏木 板 遮蔽(或译:隔断)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, ' 内殿 前 的外殿, 长四十 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, ' 殿 里 一点石头 都不 显露,一概 用香柏木遮蔽; 上面刻 著野瓜 和初开  的花。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, ' 殿 里 预备了 内殿,好安放 耶和华 的约 柜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, ' 内殿 长 二十 肘,宽 二十 肘,高 二十 肘,墙面都贴 上精 金;又用香柏木 做坛,包上精金。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, '所罗门 用精 金 贴了 殿 内的墙,又用金 链子 挂在内殿 前 门扇,用金 包裹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, ' 全 殿 都贴 上金子,直到 贴完;内殿 前的 坛,也都 用金 包裹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, '他用橄榄 木 做 两个 基路伯,各高 十 肘,安在内殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, '这一个 基路伯 有两个翅膀,各长五 肘, 从这翅膀 尖 到 那翅膀 尖 共有十 肘; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, '那一个 基路伯 的两个翅膀也是十 肘,两个 基路伯 的尺寸、形像 都是一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, '这 基路伯 高 十 肘,那 基路伯 也是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, '他将 两个基路伯 安 在内 殿 里; 基路伯 的翅膀 是张开 的,这 基路伯的一个翅膀 挨 著这边的墙,那 基路伯 的一个翅膀 挨 著那边 的墙,里边的两个翅膀 在 殿 中间 彼此 相接; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, '又用金子 包裹 二基路伯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, '内殿、外 殿 周围的 墙 上都 刻 著基路伯、棕树,和初开  的花。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, '内殿、外 殿的 地板 都贴 上金子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, '又用橄榄 木 制造 内殿 的门 扇、门楣、门框;门口有墙的五分之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, '在橄榄 木 做的两 门扇 上 刻著 基路伯、棕树,和初开  的花,都贴上 金子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, '又 用橄榄 木 制造 外殿 的门框,门口 有墙的 四分之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, '用松 木 做门 两扇。这 扇 分两 扇,是折叠的;那 扇 分两 扇,也是折叠的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, '上面刻著 基路伯、棕树,和初开  的花,都用金子 贴了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, '他又用凿成的石头 三 层、香柏木 一层 建筑 内 院。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, '所罗门在位第四 年 西弗 月,立了耶和华 殿 的根基。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, '到十 一 年 布勒 月,就是 八 月,殿 和一切 属殿的 都按著 样式 造成。他建 殿的工夫共有七 年。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, '所罗门 为自己建造 宫室,十 三 年 方才造成; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, '又建造 黎巴嫩 林 宫,长 一百 肘,宽 五十 肘,高 三十 肘,有香柏木 柱三(原文是四)行,柱 上 有香柏木 柁梁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, ' 其上 以香柏木 为盖, 每行 柱子 十五根,共有四十 五根。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, '有窗户 三 层,窗 与窗 相对。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, '所有的 门 框 都是厚木见方的,有窗户三层,窗 与窗 相对。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, '并 建造 有柱子 的廊子,长 五十 肘,宽 三十 肘;在 这廊前 又有廊子, 廊外 有柱子 和台阶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, '又建造 一廊,其 中 设立审判 的座位,这 廊 从地 到 顶 都用香柏木 遮蔽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, '廊 后 院 内 有 所罗门住 的宫室;工作与 这 工作相同。所罗门 又为所 娶 法老 的女儿 建造 一宫,做法与这 廊子一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, '建造这 一切 所用的石头 都是宝贵的,是按著尺寸 凿成的,是用锯 里 外 锯齐的;从根基 直到 檐石,从外头 直到 大 院,都是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, '根基 是宝贵 的大 石头,有长十 肘 的,有长八 肘 的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, '上面 有香柏木 和按著尺寸 凿成 宝贵 的石头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, '大 院 周围 有凿成的石头 三 层、香柏木 一层,都照耶和华 殿 的内 院 和殿 廊的样式。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, '所罗门 王 差遣 人往泰尔去,将 户兰 召了来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, '他是 拿弗他利 支派中 一个寡 妇 的儿子,他父亲 是泰尔 人,作铜 匠的。户兰满有 智慧、 聪明、 技能,善于  各样 铜 作。他来 到 所罗门 王那里,做 王一切 所要做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, '他制造 两 根铜 柱,每 根 高 十 八 肘, 围 十 二 肘; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, '又用 铜 铸了 两个 柱顶 安 在 柱 上, 各高 五 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, ' 柱 顶 上 有装修 的网子 和拧成 的炼 链 𫔀索,每 顶七个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, ' 网子 周围 有两 行 石榴 遮盖 柱 顶, 两个 柱顶 都是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, '廊子 的柱 顶 径四 肘,刻著百合花。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, ' 两 柱 顶 的鼓 肚 上 挨著 网子,各有两行石榴 环绕,两行 共有二百。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, '他将 两根柱子 立 在殿 廊前头:右边 立 一根,起 名 叫 雅斤;左边 立 一根,起 名 叫 波阿斯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, '在 柱 顶上 刻著百合花。这样,造柱子 的工 就完毕了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, '他又 铸 一个铜海,样式是 圆的,高 五 肘,径 十 肘, 围 三十 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, '在海边 之下,周 围 有野瓜的样式;每肘 十瓜, 共有两 行,是铸 海的时候铸上的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, '有十 二只 铜牛 驮 海:三只 向 北,三只 向 西,三只 向 南,三只 向 东;海 在 牛上,牛尾 都 向内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, '海厚 一掌,边 如 杯 边,又如百合 花,可容 二千 罢特。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, '他用铜 制造 十个 盆座,每 座 长 四 肘,宽 四 肘,高 三 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, '座 的造法 是这样:四面 都有心子,心子 在边子 当中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, '心子 上 有狮子 和牛,并基路伯; 边 上 有小座,狮子 和牛 以下 有垂下 的璎珞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, '每 盆座 有 四个 铜 轮 和铜 轴。小座的四 角 上在盆 以下,有铸成 的盆架,其旁 都有 璎珞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, ' 小座高 一肘,口 是圆的,仿佛 座 的样式,径一肘 半, 在 口 上有雕工,心子 是方的,不是 圆的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, '四个 轮子 在心子 以下,轮 轴 与座相连,每 轮 高 一肘 半。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, '轮 的样式 如同 车 轮;轴、辋、辐、毂 都是 铸的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, '每 座 四 角 上 都有 盆 架,是与 座一同铸成的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, '座 上 有圆架, 高 半 肘; 座 上 有撑子 和心子,是与座一同铸的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, '在 撑子 和 心子上 刻著 基路伯、狮子,和棕树,周围 有璎珞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, ' 十个 盆座 都是 这样,铸法、尺寸、样式 相同。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, '又用铜 制造 十个 盆,每 盆 可容 四十 罢特。 盆 径四 肘,在 那十 座上,每 座安设一 盆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, '五个 安 在 殿 门的右 边,五个 放在殿 门的左 边;又将 海 放 在殿 门的右 旁,就是 南边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, '户兰 又造了 盆、 铲子,和 盘子。这样,他 为所罗门 王 做 完了 耶和华 殿 的一切 工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, '所 造的就是:两根 柱子 和柱 上 两个 如球 的顶;并两个 盖 柱 顶 的网子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, '和 四 百 石榴,安在两个 网子上,每 网 两 行,盖著 两个 柱 上 如球 的顶; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, ' 十个 座 和 其 上 的十个 盆; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, ' 海 和 海 下 的十 二 只牛; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, ' 盆、 铲子、 盘子。 这 一切 都是户兰 给所罗门 王 用光亮 的铜 为耶和华 的殿 造成的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, '是遵王 命在约旦 平原、 疏割 和 撒拉但 中间藉 借 胶泥 铸成的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, ' 这一切 所罗门 都没有过秤;因为甚 多,铜 的轻重 也无法 可查。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, '所罗门 又造 耶和华 殿 里的 金 坛 和 陈设 饼 的金 桌子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, ' 内殿 前 的精 金 灯台:右边 五个,左边 五个,并其上的金 花、灯盏、蜡剪, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, '与精 金 的杯、盘、镊子、调羹、火鼎,以及至 圣所、内 殿 的门枢,和 外殿 的 门 枢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, '所罗门 王 做 完了 耶和华 殿 的一切 工, 就把他 父 大卫 分别为圣的 金 银 和 器皿 都带来 放 在耶和华 殿 的府库里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, '那时,所罗门 将 以色列 的长老 和 各 支派 的首领,并以色列 的族 长,招聚 到 耶路撒冷,要把 耶和华 的约 柜 从大卫 城─就是 锡安─运上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, '以他念 月,就是 七 月,在节前,以色列 人 都 聚集 到 所罗门 王那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, '以色列 长老 来到,祭司 便抬起 约柜, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, '祭司 和利未人 将 耶和华 的约柜 运上来,又将 会 幕 和 会幕 的 一切 圣 器具 都带上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, '所罗门 王 和聚集 到他那里 的以色列 全 会众,一同 在约柜 前 献 牛 羊为祭, 多 得不可 胜数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, '祭司 将 耶和华 的约 柜 抬 进 内殿,就是 至 圣所,放在 两个基路伯 的翅膀 底下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, ' 基路伯 张著 翅膀 在 约柜之上, 遮掩 约柜 和 抬 柜的杠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, '这杠 甚长,杠 头 在 内殿 前的 圣所 可以看见,在殿外 却不能 看见,直到 如 今 还在 那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, '约柜 里惟 有两块 石 版,就是 以色列 人 出 埃及 地后,耶和华 与 他们立约 的时候摩西 在何烈山 所 放的。除此以外,并无别物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, ' 祭司 从 圣所 出来的时候,有云 充满 耶和华 的殿; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, '甚至祭司 不 能 站立 供职, 因为 耶和华 的荣光 充满了 殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, '那时 所罗门 说:耶和华 曾说,他必住 在幽暗之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, '我已经 建造 殿宇 作你的居所,为你 永远 的住 处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, '王 转 脸 为 以色列 会众 祝福,以色列 会众 就都 站立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, '所罗门说:「耶和华─以色列的 神 是应当称颂的!因他亲口 向 我父 大卫 所 应许的,也亲手 成就了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, '他说:『自从 我领 我民 以色列 出 埃及以来,我未 曾在以色列 各 支派 中选择 一城 建造 殿宇─为 我名 的居所,但拣选 大卫 治理 我民 以色列。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, '所罗门说:「我父 大卫 曾 立 意,要为耶和华─以色列 神 的名 建 殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, '耶和华 却对 我父 大卫 说:『 你立 意 为我的名 建 殿, 这意思 甚好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, '只是 你 不可 建 殿,惟你 所生 的儿子 必为我名 建 殿。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, '现在耶和华 成就了 他所 应许 的话,使我 接续 我父 大卫 坐 以色列 的国位,又为耶和华─以色列 神 的名 建造了 殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, '我也在其中 为约柜 预备 一处。约柜内 有耶和华 的约,就是 他领我们列祖 出 埃及 地的时候,与 他们 所立的约。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, '所罗门 当著 以色列 会众,站 在耶和华 的坛 前,向天 举 手 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, '「耶和华─以色列的 神啊,天 上 地 下 没有 神 可比你的!你向那尽 心 行 在你面前 的仆人 守 约 施慈爱; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, '向你仆人─我父 大卫 所 应许 的话现在 应验了。你亲口 应许,亲手 成就,正如 今日一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, '耶和华─以色列的 神啊,你所 应许 你仆人─我父 大卫 的话说:『你的子孙 若 谨慎 自己的行为,在我面前 行事 像你所 行的一样,就不 断 人 坐 以色列 的国位。』现在 求你应验这话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, ' 以色列的 神啊,求 你成就 向你仆人─我父 大卫 所 应许 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, '「 神 果真 住 在 地上吗?看哪,天 和天 上的天 尚且不 足你居住的,何况 我所 建 的这 殿呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, '惟求耶和华─我的 神 垂顾 仆人 的祷告 祈求,俯听 仆人 今日 在你面前的 祈祷 呼吁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, '愿 你 昼 夜 看顾 这殿, 就是 你应许 立为 你名 的居所;求你垂听 仆人 向 此 处 祷告 的 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, ' 你仆人 和你民 以色列 向 此 处 祈祷的时候,求你 在 天上 你的居 所 垂听,垂听 而赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, '「 人 若 得罪 邻舍,有人叫他 起 誓,他来 到这 殿 在你的坛 前 起誓, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, '求你 在天 上垂听, 判断 你的仆人:定恶人 有罪,照他所行 的报应 在他头上;定义人 有理,照他的义 赏赐 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, '「你的民 以色列 若 得罪 你,败 在仇敌 面前,又归 向你,承认 你的名,在这 殿里 祈求 祷告, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, '求你 在天 上垂听,赦免 你民 以色列 的罪,使他们归 回 你赐 给他们列祖 之 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, '「你的民因 得罪 你, 你惩罚他们,使天 闭塞 不 下 雨;他们若向 此 处 祷告,承认 你的名,离开  他们的罪, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, '求你 在天 上垂听,赦免 你仆人 以色列 民 的罪, 将 当行 的 善 道 指教他们,且降 雨 在 你的地,就是 你赐 给你民 为业之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, '「国 中若 有 饥荒、 瘟疫、旱风、霉烂、蝗虫、蚂蚱,或有 仇敌 犯境 围困 城邑,无论遭遇什么 灾祸 疾病, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, '你的 民 以色列,或是众 人,或是 一人,自觉 有罪(原文是灾),向 这 殿 举 手, 无论祈求 什么,祷告 什么, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, '求你 在天上 你的居 所 垂听 赦免。你是知道 人 心的,要照 各人所行的 待 他们( 惟有 你 知道 世 人 的心), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, '使 他们在 你赐 给我们列祖 之 地 上 一生 一世 敬畏你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, '「论 到 不 属你民 以色列 的 外邦人, 为 你名 从远 方 而来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '( 他们听人论说 你的大 名 和 大能 的手,并伸出来 的膀臂) 向 这 殿 祷告, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, '求你 在天上 你的居 所 垂听,照著 外邦人 所 祈求 的而行,使 天下 万 民 都认识 你的名,敬畏 你 像你的民 以色列一样;又使他们知道 我建造 的 这 殿 是称 为 你名下的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, '「你的民 若 奉你的差遣,无论往何 处 去 与 仇敌 争战 ,向 耶和华 所 选择 的 城 与我为你名 所 建造 的殿 祷告, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, '求你在天上 垂听 他们的祷告 祈求,使他们得 胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, '「你的民若 得罪 你( 世上没有 不 犯罪 的 人),你向他们 发怒,将他们交 给 仇敌 掳 到 仇敌 之地,或远 或 近, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, '他们若在掳到 之 地 想起罪来,回 心 转意, 恳求 你 说:『我们有罪了,我们悖逆了,我们作恶了』; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, '他们若在 掳到 之 地 尽 心 尽 性 归 服你,又向 自己的地,就是 你赐 给他们列祖 之地和你所 选择 的城,并我为你名 所 建造 的殿 祷告, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, '求你在天上 你的居 所 垂听 他们的祷告 祈求,为他们伸 冤; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, '饶恕 得罪 你 的 民,赦免他们的一切 过犯,使他们在掳他们 的人面前 蒙 怜恤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, '因为 他们 是你的子民,你的产业,是 你从埃及 领出来 脱离 铁 炉的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, '愿  你的眼目 看顾 仆人,听 你民 以色列 的祈求,无论 何时向你 祈求,愿 你垂听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, '主 耶和华啊, 你 将他们从地上 的万 民 中分别出来 作你的 产业,是照 你领 我们列祖 出 埃及的时候,藉 借 你仆人 摩西 所应许的话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, '所罗门 在耶和华 的坛 前 屈 膝 跪著,向天 举 手,在 耶和华面前 祷告 祈求 已 毕,就起来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, '站著,大 声 为 以色列 全 会众 祝福,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, '「耶和华 是应当称颂的!因为他照著一切 所 应许 的赐 平安 给他的民 以色列人,凡 藉 借 他仆人 摩西 应许 赐福 的 话,一 句 都没有 落空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, '愿  耶和华─我们的 神 与我们同在,像 与 我们列祖 同在一样,不 撇下我们,不 丢弃我们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, '使我们的心 归 向他,遵行 他的道,谨守 他吩咐 我们列祖 的 诫命、律例、典章。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, '我在耶和华 面前 祈求 的 这些 话,愿  耶和华─我们的 神 昼 夜 垂念, 每日 为他仆人 与他民 以色列 伸 冤, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, '使 地上 的万 民 都知道 惟独耶和华 是 神,并无 别神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, '所以你们当 向 耶和华─我们的 神 存诚实 的心,遵行 他的律例,谨守 他的诫命,至终如今 日一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, '王 和以色列 众民 一同 在耶和华 面前 献 祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, '所罗门 向耶和华 献 平安 祭, 用牛 二万二 千,羊 十二万。这样,王 和以色列 众 民 为 耶和华 的殿 行奉献之礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, '当 日,王 因 耶和华 殿前 的 铜 坛 太小, 容不下 燔祭、 素祭,和 平安祭牲 的脂油,便将 耶和华 殿 前 院子 当中 分别为圣,在那里 献 燔祭、 素祭,和 平安祭牲 的脂油。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, '那 时,所罗门 和 以色列 众人,就是从哈马 口 直到 埃及 小河 所有的以色列人,都聚集成为大 会,在耶和华─我们的 神 面前 守 节 七 日 又七 日,共十 四 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, '第八 日,王遣散 众民;他们都为 王 祝福。因 见耶和华 向他仆人 大卫 和他民 以色列 所 施 的一切 恩惠,就都心中 喜乐,各归 各家去了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, ' 所罗门 建造 耶和华 殿 和 王 宫,并 一切 所 愿 意 建造 的都完毕了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, '耶和华 就二次 向 所罗门 显现,如 先前在基遍 向他 显现一样, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, ' 对他 说:「你向我 所 祷告 祈求的,我都应允了。我已将 你所 建的 这 殿 分别为圣,使 我的名 永远 在其中;我的眼、我的心 也必 常 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, '你 若 效法 你父 大卫,存诚实 正直 的心 行 在我面前,遵行 我一切 所 吩咐你的,谨守 我的律例 典章, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, '我就必坚固 你的国 位 在 以色列中,直到永远,正如 我应许 你父 大卫 说:『你的子孙必不 断 人 坐 以色列 的国位。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, '倘若 你们 和你们的子孙 转 去 不跟从我,不 守 我指示 你们 的 诫命 律例,去 事奉 敬拜 别 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, '我就必将 以色列人 从 我赐 给他们 的 地 上 剪除,并且 我为己名 所 分别为圣 的殿 也必舍弃 不 顾,使以色列人 在万 民 中作 笑谈,被讥诮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, '这 殿 虽然甚 高,将来 经过 的人必惊讶、嗤笑,说:『耶和华 为 何 向这 地 和这 殿 如此 行呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, '人必回答说:『是因 此地的人 离弃 领 他们列祖 出 埃及 地 之 耶和华─他们的 神,去亲近 别 神,事奉 敬拜 他,所 以 耶和华 使 这 一切 灾祸 临到 他们。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, ' 所罗门 建造 耶和华 殿 和 王 宫, 这两所 二十 年 才完毕了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, '泰尔 王 希兰 曾照所罗门所 要的,资助 他 香柏 木、松 木,和金子; 所罗门 王 就把加利利 地 的二十座 城 给了 希兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, '希兰 从泰尔 出来,察看 所罗门 给 他 的 城邑,就不 喜悦, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, '说:「我兄啊,你给 我 的 是什么 城邑呢?」他就给这城邑 之地 起名叫 迦步勒,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, '希兰 给所罗门 一百 二十 他连得 金子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, '所罗门 王 挑取 服苦的人,是为建造 耶和华 的殿、 自己的宫、 米罗、 耶路撒冷 的城墙、 夏琐、 米吉多,并 基色。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, '先前埃及 王 法老 上来 攻取 基色,用火 焚烧,杀了 城 内居住 的迦南人,将城赐 给他女儿 所罗门 的妻 作妆奁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, '所罗门 建造 基色、 下伯‧和仑 、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, ' 巴拉,并 国 中旷野 里的达莫, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, '又建造所有的 积货 城,并 屯车 和 马兵 的城,与耶路撒冷、黎巴嫩,以及 自己 治理 的全 国 中所 愿  建造的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, '至于 国中 所剩下 不 属以色列 人 的 亚摩利人、赫人、比利洗人、希未人、耶布斯人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, '就是 以色列 人 不 能 灭尽的,所罗门 挑取 他们的后裔 作服苦 的奴仆,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, '惟有以色列 人,所罗门 不 使 他们作奴仆,乃是 作 他的战  士、臣仆、统领、军长、车兵长、马兵 长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, ' 所罗门 有五 百 五十 督 工 的,监管 工 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, ' 法老 的女儿 从大卫 城 搬 到 所罗门为她 建造 的 宫里。那时,所罗门才建造 米罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, '所罗门 每年 三 次 在 他为耶和华 所 筑 的坛 上献 燔祭 和平安祭,又在 耶和华 面前 的 坛 上烧香。这样,他建造 殿 的工程完毕了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, '所罗门 王 在 以东 地 红 海 边, 靠近 以禄的以旬‧迦别 制造 船只。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, '希兰 差遣 他的仆人,就是熟悉 泛海 的船 家,与 所罗门 的仆人 一同坐船航海。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, '他们到了 俄斐,从那里 得了 四 百 二十 他连得 金子,运 到 所罗门 王那里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, '示巴 女王 听见 所罗门 因耶和华 之名 所得的名声,就来 要用难解的话 试问所罗门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, '跟随她到 耶路撒冷 的人 甚 多,又有骆驼 驮著 香料、宝 石,和许 多 金子。她来 见了 所罗门王,就把 心里所有的 对所罗门 都 说出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, '所罗门 王 将 她 所问 的都 答上了,没 有 一句 不明白、 不能 答的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, '示巴 女王 见 所罗门 大有 智慧,和他所 建造 的宫室, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, '席 上的珍馐美味,群臣 分列而坐,仆人 两旁侍立,以及他们的衣服装饰和酒政 的衣服装饰,又见他上 耶和华 殿 的 台阶(或译:他在耶和华殿里所献的燔祭),就诧异得 神 不 守 舍; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, '对 王 说:「我在本国 里所 听见 论到 你的事 和 你的智慧 实在是 真 的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, '我先不 信 那些话,及至 我来 亲眼 见了才知道 人所告诉 我 的还不到 一半。你的智慧 和你的福分 越 过 我所 听见 的风声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, ' 你的臣子、 你的仆人 常 侍立 在你面前 听 你智慧的话 是有福的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, '耶和华─你的 神 是 应当称颂的!他 喜悦 你,使你 坐 以色列 的国位;因为他 永远 爱 以色列,所以立 你作王,使你秉公 行 义。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, '于 是,示巴 女王 将一百 二十 他连得 金子 和宝 石,与极 多 的香料,送 给所罗门 王。她送 给王 的 香料,以后奉来 的不 再 有这样 多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, '( 希兰 的船只 从俄斐 运了 金子来,又从俄斐 运了 许多 檀香 木(或译:乌木;下同)和宝 石来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, '王 用 檀香 木 为耶和华 殿 和王 宫 做 栏杆,又为歌唱的人 做琴 瑟。以后再没有 这样的 檀香 木 进国来,也没有 人看见过,直到 如 今。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, '示巴 女王 一切 所 要 所求的,所罗门 王 都送 给她,另外 照 自己 的厚意 餽送 她。于 是女王 和她臣仆 转回 本国 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, '所罗门 每 年 所 得 的金子 共有 六 百 六十 六 他连得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, '另外 还有商 人 和杂族(杂族在历代下九章十四节是阿拉伯)的诸 王,与国 中的省长所进的金子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, '所罗门 王 用锤出 来的金子 打成 挡牌 二百面,每 面 用 金子 六 百舍客勒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, '又用锤出来 的金子 打成盾牌 三 百面,每 面 用 金子 三 弥那, 都放 在黎巴嫩 林 宫里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, '王 用象牙 制造 一个 宝座,用精 金 包裹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, '宝座 有六层 台阶,座的 后 背 是圆的, 两 旁 有扶手,靠近 扶手 有两个 狮子 站立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, ' 六层 台阶 上有十 二个 狮子 站立,每层有两个:左边一个,右边一个;在列 国 中没有 这样 做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, '所罗门 王 一切 的饮 器 都是金子的。黎巴嫩 林 宫 里的一切 器皿 都是精 金的。所罗门 年间, 银子 算 不了 什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, '因为 王有 他施 船只 与 希兰 的船只 一同航海, 三 年 一次,装载金 银、象牙、猿猴、孔雀 回来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, '所罗门 王 的财宝 与智慧 胜过 天下 的列 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, '普 天下 的王都求见 所罗门,要听 神 赐给他 智慧 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, '他们 各 带 贡物,就是金 器、银 器、衣服、军械、香料、骡 马,每年 有一定之例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, '所罗门 聚集 战 车 马兵,有 战 车 一千 四 百辆,马兵 一万二千名,安置 在屯车 的城邑 和耶路撒冷,就是 王那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, '王 在耶路撒冷 使 银子 多如石头, 香柏木 多 如高原 的 桑树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, '所罗门 的 马 是从埃及 带来的,是王 的商人 一群 一群 按著定价 买 来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, '从埃及 买  来 的车,每辆价银 六 百舍客勒,马 每匹一百 五十舍客勒。赫人 诸 王 和亚兰 诸王所买 的车马,也是 按这价值经他们手 买 来的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, '所罗门 王 在 法老 的女儿之外,又宠爱 许多 外邦 女子,就是摩押女子、亚扪女子、以东女子、西顿女子、赫人女子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, '论到 这些 国的人,耶和华 曾晓谕 以色列 人 说:「你们不可 与她们 往来 相通,因为她们必 诱惑 你们的心 去随从 她们的神。」所罗门 却恋 爱 这些女子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, '所罗门 有 妃 七 百,都是公主;还有嫔 三 百。这些妃嫔 诱惑 他的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, ' 所罗门 年老 的时候,他的妃嫔 诱惑 他的心 去随从 别 神, 不 效法 他父亲 大卫 诚诚实实地 顺服 耶和华─他的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, '因为所罗门 随 从 西顿人 的女神 亚斯她录 和 亚扪人 可憎的神 米勒公。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, '所罗门 行 耶和华 眼中 看为恶的事,不 效法他父亲 大卫 专心 顺从 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, ' 所罗门 为摩押 可憎的神 基抹 和亚扪 人 可憎的神 摩洛,在耶路撒冷 对 面 的 山上 建筑 邱坛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, '他为 那些向自己的神 烧香 献祭 的外邦女子,就是他娶来的妃嫔 也是这样 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, '耶和华 向所罗门 发怒,因为 他的心 偏离 向他 两次 显现 的耶和华─以色列的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, '耶和华曾吩咐 他 不可 随 从 别 神,他却没有 遵守 耶和华 所 吩咐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, '所以耶和华对他 说:「你 既 行了 这事,不 遵守 我所 吩咐 你 守的约 和律例,我必 将 你的国 夺回,赐 给你的臣子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, '然而,因 你父亲 大卫的缘故,我不 在你活著的日子 行这事,必从你儿子 的手 中将国夺回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, '只是 我不 将 全 国 夺回,要因 我仆人 大卫 和 我所 选择 的耶路撒冷,还留一 支派 给 你的儿子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, '耶和华 使 以东人 哈达 兴起,作所罗门 的敌人;他是 以东 王 的后裔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, '先前 大卫 攻击 以东,元帅 约押 上去 葬埋 阵亡的人,将以东 的男丁 都 杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, ' 约押 和以色列 众人 在以东 住了 六个 月,直到 将以东 的男丁 尽都 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, '那时哈达 还是幼 童;他 和 他父亲 的臣仆,几个 以东人 逃 往 埃及。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, '他们从米甸 起行,到了 巴兰;从巴兰 带 著 几个人 来到 埃及 见 埃及 王 法老;法老为他 派定 粮食,又给 他 房屋 田地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, '哈达 在法老 面前 大 蒙 恩惠,以致法老将 王后 答比匿 的妹子 赐 他 为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, '答比匿 的妹子 给哈达 生了 一个儿子,名叫基努拔。答比匿 使基努拔在法老 的宫 里 断奶,基努拔 就 与 法老 的众子 一同住在法老 的宫里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, '哈达 在埃及 听见 大卫 与 他列祖 同睡, 元帅 约押 也死了, 就对 法老 说:「求王容我 回 本国 去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, '法老 对他 说:「 你 在我 这里有什么 缺乏,你竟 要 回 你本国 去呢?」他回答说:「我没有缺乏什么,只是 求王容 我回去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, '神 又使 以利亚大 的儿子 利逊 兴起,作所罗门 的敌人。他 先前逃避 主人 琐巴 王 哈大底谢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, '大卫 击杀 琐巴人的时候,利逊招聚了 一群人,自己 作 他们的 头目,往 大马士革 居住,在那里 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, '所罗门 活著的时候, 哈达 为 患之外,利逊也作 以色列的 敌人。他恨恶 以色列人,且作了 亚兰人 的王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, '所罗门的 臣仆、尼八 的儿子 耶罗波安 也举 手 攻击王。他是以法莲支派 的 洗利达人,他母亲 是寡 妇,名 叫洗鲁阿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, '他举 手 攻击王 的 缘故,乃由先前所罗门 建造 米罗,修补 他父亲 大卫 城 的破口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, '耶罗波安 是大有 才能 的人。所罗门 见 这少年人 殷勤,就派 他 监管约瑟 家 的一切 工程。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, ' 一 日,耶罗波安 出了 耶路撒冷,示罗人 先知 亚希雅 在路 上遇见 他;亚希雅 身上穿著 一件新 衣。他们二人 在田野,以外并无别人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, '亚希雅 将自己穿 的 那件新 衣 撕成 十 二 片, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, '对耶罗波安 说:「你 可以拿 十 片。 耶和华─以色列的 神 如此 说:『 我必将 国 从所罗门 手 里夺回,将 十个 支派 赐 给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, '(我因 仆人 大卫 和 我在以色列 众 支派 中所 选择的 耶路撒冷 城的缘故,仍给所罗门 留 一个 支派。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, '因 为 他离弃我,敬拜 西顿人 的女神 亚斯她录、摩押 的神 基抹,和亚扪 人 的神 米勒公,没有 遵从 我的道,行 我眼中 看为正的事,守我的律例 典章,像他父亲 大卫一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, '但我不 从他手 里将 全 国 夺回; 使他 终 身 为君,是因 我所 拣选 的仆人 大卫 谨守 我的诫命 律例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, '我必从他儿子 的手 里将国 夺回,以 十个 支派 赐 给你, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, '还留一个 支派 给 他的儿子,使 我仆人 大卫 在我所 选择 立 我名 的耶路撒冷 城里,在我面前 长 有 灯光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, '我必拣选 你,使你照心里 一切 所 愿 的,作 王 治理 以色列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, ' 你若 听从 我一切 所 吩咐你的,遵行 我的道,行 我眼中 看为正的事,谨守 我的律例 诫命,像我仆人 大卫 所 行的,我就 与你同在,为你 立 坚固 的家,像我为大卫 所 立的一样,将 以色列人 赐 给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, '我必因 所罗门所行的 使 大卫 后裔 受患难,但 不 至于 永远。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, '所罗门 因此想要 杀 耶罗波安。耶罗波安 却起身 逃往 埃及;到了 埃及 王 示撒那里,就住 在埃及,直到 所罗门 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, '所罗门 其余 馀 的事,凡 他所 行 的和他的智慧 都 写 在 所罗门 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, '所罗门 在耶路撒冷 作 以色列 众人 的王 共 四十 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, '所罗门 与 他列祖 同睡,葬 在他父亲 大卫 的城里。他儿子 罗波安 接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, '罗波安 往 示剑去;因为 以色列人 都 到了 示剑 要立 他作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, ' 尼八 的儿子 耶罗波安 先前躲避 所罗门 王,逃往 埃及, 住 在那里(他听见这事。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, '以色列人打发 人去请 他来,他 就和以色列 会众 都 来 见 罗波安,对他说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, '「你父亲 使 我们负重轭,做苦工,现在 求你 使 我们 做的苦 工、负的重 轭 轻松些,我们就事奉你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, '罗波安对他们 说:「你们暂且 去,第三 日 再来 见我。」民 就去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, '罗波安之父 所罗门 在 世的日子,有 侍立 在他面前 的老年人,罗波安 王 和 他们商议,说:「你们 给我出个什么 主意,我好回 覆 复 这 民。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, '老年人 对他 说:「现在 王若 服事 这 民 如 仆人,用好 话 回答 他们,他们就永远 作 王的 仆人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, '王却不用 老年人 给他 出的主意,就和 那些 与他 一同长大、 在他面前 侍立 的少年人 商议, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, '说:「这 民 对我 说:『你父亲 使 我们负 重轭, 求你使我们轻松 些。』你们 给我出个什么 主意,我好回 覆 复 他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, '那 同他 长大 的少年人 说:「 这 民 对王 说:『你父亲 使我们负 重轭,求你 使我们 轻松些。』王要对他们 如此 说:『我的小拇指头 比我父亲 的腰 还粗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, ' 我父亲 使你们 负 重 轭,我 必使你们负 更重 的轭!我父亲 用鞭子 责打 你们,我 要用蝎子鞭 责打 你们!』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, '耶罗波安 和众 百姓 遵著 罗波安 王 所说「你们第三 日 再来 见我」的那话,第三 日 他们果然来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, '王 用严厉的 话回答 百姓,不用 老年人 给他 所 出的主意, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, '照著少年人 所出的主意 对民 说:「我父亲 使你们负重 轭,我 必使你们负 更重 的轭!我父亲 用鞭子 责打 你们,我 要用蝎子鞭 责打 你们!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, '王 不肯 依 从 百姓,这事 乃 出于  耶和华,为 要应验 他 藉 借 示罗人 亚希雅 对 尼八 的儿子 耶罗波安 所 说 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, '以色列 众民 见 王 不 依 从他们, 就 对 王 说:我们 与大卫 有什么 分儿呢?与耶西 的儿子 并没有 关涉。以色列人哪,各回各家去吧! 大卫家啊,自己顾自己吧!于 是,以色列人 都回自己家 里去了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, '惟独住 犹大 城邑 的以色列 人,罗波安 仍作他们 的王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, '罗波安 王 差遣 掌管 服苦之人 的 亚多兰往以色列人那里去, 以色列人 就用石头 打 死 他。罗波安 王 急忙 上 车,逃回 耶路撒冷去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, '这样,以色列人 背叛 大卫 家,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, ' 以色列众 人 听见 耶罗波安 回来了,就打发 人去请 他 到 会众面前,立他 作 以色列 众人 的王。除了 犹大 支派 以外,没 有 顺从 大卫 家的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, '罗波安 来到 耶路撒冷,招聚 犹大 全 家 和 便雅悯 支派 的人共十八万,都是挑选 的战  士,要与 以色列 家 争战 ,好将 国 夺回,再归所罗门 的儿子 罗波安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, '但 神 的话 临 到 神 人 示玛雅,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, '「你去告诉 所罗门 的儿子 犹大 王 罗波安 和 犹大、便雅悯 全 家,并其余 馀 的民 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, '『耶和华 如此 说:你们不可 上去 与 你们的弟兄 以色列 人 争战 。各 归 各家去吧!因为 这 事 出于 我。』」众人就听从 耶和华 的话,遵著耶和华 的命 回 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, '耶罗波安 在以法莲 山地 建筑 示剑,就住 在其中;又从示剑 出去,建筑 毘努伊勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, '耶罗波安 心里 说:「恐怕 这国 仍归 大卫 家; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, '这 民 若 上 耶路撒冷去,在耶和华 的殿 里献 祭,他们 的心 必归 向 他们的主─犹大 王 罗波安,就把我杀了,仍归 犹大 王 罗波安。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, '耶罗波安王 就筹划 㓰定妥,铸造了 两个 金 牛犊,对众民 说:「以色列人哪,你们上 耶路撒冷 去实在是难; 这就是 领你们出 埃及 地的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, '他就把 牛犊一只 安 在伯特利, 一只 安 在但。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, '这 事 叫 百姓 陷在罪里,因为他们往 但 去 拜那牛犊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, '耶罗波安在邱坛 那里建 殿,将那 不 属利未 人 的凡 民 立 为祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, '耶罗波安 定 八 月 十 五 日 为节期,像 在犹大 的节期一样,自己上 坛 献祭。他在伯特利 也这样 向他所 铸 的牛犊 献祭,又将 立 为 邱坛 的祭司 安置 在伯特利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, '他 在八 月 十 五 日,就是 他私自 所定 的月日,为以色列 人 立作 节期的日子,在伯特利 上 坛 烧香。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, '那时,有一个神 人 奉耶和华 的命 从犹大 来 到 伯特利。耶罗波安 正站 在 坛 旁要烧香; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, '神人奉耶和华 的命 向 坛 呼叫,说:「坛哪,坛哪!耶和华 如此 说: 大卫 家 里必生 一个儿子,名 叫约西亚,他必将 邱坛 的祭司,就是在你上面 烧香的,杀 在你上面,人 的骨头 也必烧 在你上面。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, '当 日,神人设 个预兆,说:「这 坛 必破裂, 坛上 的 灰 必倾撒,这是 耶和华 说 的预兆。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, ' 耶罗波安 王 听见 神 人 向 伯特利 的坛 所 呼叫的 话,就从 坛 上伸 手,说:「拿住他吧!」王向神人 所 伸 的手 就枯干了,不 能 弯 回; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, '坛 也破裂了,坛 上 的灰 倾撒了,正如 神 人 奉耶和华 的命 所 设 的预兆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, '王 对 神 人 说:「请 你为我 祷告,求 耶和华─你 神 的恩典使我的手 复原。」于 是神 人 祈祷 耶和华,王 的手 就复了原,仍 如寻常一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, '王 对 神 人 说:「请你同我 回去吃饭,加添心力,我也必给 你 赏赐。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, '神 人 对 王 说:「你就是 把 你的宫 一半 给 我,我也不 同你 进去,也不 在这 地方 吃 饭 喝 水; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, '因为 有 耶和华 的话 嘱咐 我,说 不可 在伯特利吃 饭 喝 水,也不可 从你去 的 原路 回来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, '于 是神人从别的 路 回去,不 从 伯特利 来 的 原路 回去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, '有一个 老 先知 住 在伯特利,他儿子们 来,将 神 人 当日 在伯特利 所 行 的一切 事 和 向 王 所 说 的话 都告诉了 父亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, '父亲 问他们 说:「神人从哪 条路 去了呢?」儿子们就告诉他;原来他们看见 那从犹大 来 的神 人 所 去 的路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, '老先知就吩咐 他儿子们 说:「你们为我 备 驴。」他们备 好了驴,他就骑 上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, '去追 赶 神 人,遇见 他坐 在橡树 底下,就问他 说:「你 是 从犹大 来 的神 人不是?」他说:「是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, '老先知对他 说:「请你同我 回 家 吃 饭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, '神人说:「我不 可 同你 回去 进你的家,也不可 在这 里 同你 吃 饭 喝 水; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, '因为 有耶和华 的话 嘱咐 我说:『你在那里 不可 吃 饭 喝 水,也不可 从你去 的 原路 回 来。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, '老先知对他 说:「我 也是 先知,和你一样。有天使 奉耶和华 的命 对我 说:『你去把他 带 回 你的家,叫他吃 饭 喝 水。』」这都是老先知诓哄 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, '于 是神人同 老先知回去,在他家 里吃 饭 喝 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, ' 二人 坐 席的时候,耶和华 的话 临 到 那 带神人回来 的先知, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, '他就 对 那 从犹大 来 的神 人 说:「耶和华 如此 说:你既 违背 耶和华 的话,不 遵守 耶和华─你 神 的 命令, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, '反倒回来,在耶和华 禁止 你 吃 饭 喝 水 的 地方 吃了 喝了,因此你的尸身 不 得入 你列祖 的坟墓。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, ' 吃 喝 完了,老先知为 所 带回来 的先知 备 驴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, '他就去了,在路 上有个狮子 遇见他,将他咬死, 尸身 倒 在路上,驴 站 在尸身旁边,狮子 也站 在 尸身旁边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, ' 有人 从那里经过,看见 尸身 倒 在路上, 狮子 站 在 尸身旁边,就来到 老 先知 所 住 的城 里述说这事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, '那带神人 回来 的先知 听见这事,就说:「这是 那 违背了 耶和华 命令 的神 人,所以耶和华 把他交 给狮子;狮子抓伤他,咬死他,是应验耶和华 对他 说 的 话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, '老先知就吩咐 他儿子们 说:「你们为我 备 驴。」他们就备了驴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, '他去了,看见 神人的尸身 倒 在路上,驴 和狮子 站 在尸身 旁边,狮子 却没有 吃 尸身,也没有 抓伤 驴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, '老先知 就把 神 人 的尸身 驮 在 驴上,带回 自己的城里, 要哀哭他,葬埋他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, '就把 他的尸身 葬 在自己的坟墓里,哀哭 他,说:「哀哉!我兄啊。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, ' 安葬 之后,老先知 对 他儿子们 说:「我死了,你们要葬 我 在神 人 的坟墓里, 使 我的尸骨 靠近 他的尸骨, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, '因为 他奉耶和华 的命 指著 伯特利 的 坛 和 撒马利亚 各 城 有邱坛 之 殿 所 说 的话 必定 应验。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, '这 事 以后,耶罗波安 仍不 离开  他的恶 道, 将凡 民 立 为邱坛 的祭司;凡愿 意的,他都分别为圣,立为 邱坛 的祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, '这 事 叫 耶罗波安 的家 陷在罪里,甚至他的家从 地 上 除 灭了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, '那 时,耶罗波安 的儿子 亚比雅 病了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, '耶罗波安 对他的妻 说:「你可以 起来 改装,使人不 知道 你 是耶罗波安 的妻,往示罗 去, 在那里 有先知 亚希雅。他 曾告诉 我说,你必作 这 民 的王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, '现在你 要带 十个 饼,与几个薄饼,和一瓶 蜜 去 见他,他 必告诉 你 儿子 将要 怎样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, '耶罗波安 的妻 就这样 行,起身 往示罗 去,到了 亚希雅 的家。亚希雅 因 年纪老迈,眼目 发直,不 能 看见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, '耶和华 先晓谕 亚希雅 说:「 耶罗波安 的妻 要来 问 你, 因 她儿子 病了,你当如此 如此 告诉 她。 她进来 的时候必 装作别的妇人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, ' 她刚进 门,亚希雅 听见 她脚步 的响声,就说:「耶罗波安 的妻,进来吧!你 为何 装作别的妇人呢?我 奉差遣 将凶 事告诉你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, '你回去 告诉 耶罗波安说:『耶和华─以色列的 神 如此 说: 我从民 中 将你高举,立你 作 我民 以色列 的君, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, '将 国 从大卫 家 夺回 赐给 你;你却不 效法 我仆人 大卫, 遵守 我的诫命, 一 心 顺 从我, 行 我眼中 看为正的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, '你竟行 恶,比 那 在 你以先的更甚, 为自己 立了 别 神,铸了偶像,惹我发怒,将我 丢 在背 后。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, '因此, 我必使灾祸 临 到 耶罗波安 的家,将属耶罗波安 的男丁,无论困住的、自由的 都从以色列 中剪除,必除尽 耶罗波安 的家,如 人除 尽 粪土一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, '凡属耶罗波安的人,死 在城 中的必被狗 吃,死 在田野 的必被空中 的鸟 吃。这是 耶和华 说的。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, '所以你 起身 回家 去吧!你的脚 一进 城,你儿子 就必死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, '以色列 众人 必为他 哀哭,将他 葬埋。凡属耶罗波安的人, 惟有他 得入 坟墓;因为 在耶罗波安 的家中,只有他 向 耶和华─以色列的 神 显出 善 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, '耶和华 必另立 一王 治理 以色列。到了 日期,他 必剪除 耶罗波安 的家;那日期 已经 到了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, '耶和华 必击打 以色列人,使他们摇动,像 水 中的芦苇一般;又将 他们 从耶和华 赐 给他们列祖的 美 地 上拔出来,分散 在大河 那边;因为 他们做 木偶,惹 耶和华 发怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, '因 耶罗波安 所 犯 的罪,又 使 以色列人 陷在罪里,耶和华 必将 以色列人交给仇敌。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, '耶罗波安 的妻 起身 回去,到了 得撒, 刚到 门槛,儿子 就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, '以色列 众人 将他 葬埋,为他 哀哭,正如耶和华 藉 借 他仆人 先知 亚希雅 所 说 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, '耶罗波安 其余 馀 的事,他怎样 争战 ,怎样 作王, 都写 在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, '耶罗波安 作王 二十 二 年,就与 他列祖 同睡。他儿子 拿答 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, '所罗门 的儿子 罗波安 作 犹大王。他 登基 的时候年 四十 一 岁,在耶路撒冷,就是 耶和华 从以色列 众 支派 中所选择 立 他名 的城,作王 十 七 年。罗波安的母亲 名 叫拿玛,是亚扪人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, '犹大人 行 耶和华 眼中 看为恶的事, 犯 罪 触动他 的愤恨,比他们列 祖更甚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, '因为 他们 在 各 高 冈上,各 青翠 树 下 筑 坛,立柱像 和木偶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, '国 中也 有 娈童。犹大人效法耶和华 在以色列 人 面前 所 赶出 的外邦人,行 一切 可憎恶的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, ' 罗波安 王 第五 年,埃及 王 示撒 上来 攻取 耶路撒冷, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, '夺了 耶和华 殿 和 王 宫 里的宝物,尽都 带走,又夺去 所罗门 制造的 金 盾牌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, '罗波安 王 制造 铜 盾牌 代替那金盾牌,交 给 守 王 宫 门 的护卫 长看守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, ' 王 每逢 进 耶和华 的殿,护卫兵 就拿这盾牌,随后仍将盾牌送回,放在 护卫 房。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, '罗波安 其余 馀 的事,凡 他所 行的, 都 写 在 犹大 列王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, ' 罗波安 与 耶罗波安 时常 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, '罗波安 与 他列祖 同睡,葬 在 大卫 城 他列祖的坟地里。他母亲 名 叫拿玛,是亚扪人。他儿子 亚比央(又名亚比雅)接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, '尼八 的儿子 耶罗波安 王 十 八 年,亚比央 登基 作 犹大王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, '在耶路撒冷 作王 三 年。他母亲 名 叫玛迦,是押沙龙 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, '亚比央行 他父亲 在他以前 所 行 的一切 恶,他的心 不 像 他祖 大卫 的心,诚诚实实地 顺服 耶和华─他的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, '然而 耶和华─他的 神 因 大卫的缘故,仍使他 在耶路撒冷 有 灯光, 叫 他儿子 接续他作王,坚立 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, '因为 大卫 除了 赫人 乌利亚 那件事,都是行 耶和华 眼中 看为正的事,一 生 没有 违背 耶和华一切 所 吩咐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, ' 罗波安 在世 的日子常 与 耶罗波安 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, '亚比央 其余 馀 的事,凡 他所 行的, 都写 在 犹大 列王 记上。 亚比央 常与 耶罗波安 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, '亚比央 与 他列祖 同睡,葬 在大卫 的城里。他儿子 亚撒 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, '以色列 王 耶罗波安 二十 年,亚撒 登基 作犹大 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, '在耶路撒冷 作王 四十 一 年。他祖母 名 叫玛迦,是押沙龙 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, '亚撒 效法他祖 大卫 行 耶和华 眼中 看为正的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, '从 国 中除去 娈童,又除掉 他列祖 所 造 的一切 偶像; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, '并且 贬了 他祖母 玛迦 太后的位,因 她造了 可憎的偶像 亚舍拉。亚撒 砍下 她的偶像,烧 在汲沦 溪边, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, '只是邱坛 还没有 废去。亚撒 一生 却 向 耶和华 存 诚实 的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, '亚撒将 他父亲 所分别为圣 与自己所分别为圣 的金 银 和器皿 都奉 到耶和华 的殿里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, ' 亚撒 和 以色列 王 巴沙 在世的日子 常常争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, '以色列 王 巴沙 上来 要攻击 犹大,修筑 拉玛,不 许 人从犹大 王 亚撒 那里出 入。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, '于 是亚撒 将 耶和华 殿 和 王 宫 府库 里所剩下 的金 银 都 交 在他臣仆 手中, 打发他们 往 住 大马士革 的亚兰 王─希旬 的孙子、他伯利们 的儿子便‧哈达那里去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, '说:「 你父 曾与 我父立约, 我与你 也要立约。现在 我将金 银 送 你 为礼物,求你 废掉 你与 以色列 王 巴沙 所立的约,使他离开  我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, '便‧哈达 听 从 亚撒 王的话,派 军 长 去攻击 以色列 的城邑;他们就攻破 以云、 但、亚伯‧伯‧玛迦、 基尼烈 全境、 拿弗他利 全 境。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, ' 巴沙 听见,就停工 不修筑 拉玛了,仍住 在得撒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, '于 是亚撒 王 宣告 犹大 众人,不准 一个推辞,吩咐他们将 巴沙 修筑 拉玛 所 用的石头、 木头 都运去, 用以 修筑 便雅悯 的迦巴 和 米斯巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, '亚撒 其余 馀 的 事,凡 他所 行的,并 他的勇力 与他所 建筑 的城邑, 都写 在 犹大 列王 记上。 亚撒年老 的时候, 脚 上有病。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, '亚撒 与 他列祖 同睡,葬 在 他祖 大卫 城 他列祖的坟地里。他儿子 约沙法 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, '犹大 王 亚撒 第二 年,耶罗波安 的儿子 拿答 登基 作 以色列 王 共二 年, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, '拿答行 耶和华 眼中 看为恶的事,行 他父亲 所行的,犯 他父亲使 以色列人 陷在罪 里的那罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, '以萨迦 人 亚希雅 的儿子 巴沙 背叛 拿答, 在非利士 的 基比顿 杀了他。那时拿答 和以色列 众人 正围困 基比顿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, '在犹大 王 亚撒 第三 年 巴沙 杀了他,篡了他 的位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, ' 巴沙一作王 就杀了 耶罗波安 的全 家, 凡 有气息的 没有 留下一个,都 灭尽了,正应验耶和华 藉 借 他仆人 示罗人 亚希雅 所 说 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, '这是因为 耶罗波安 所 犯 的罪 使 以色列人 陷在罪里,惹动 耶和华─以色列 神 的 怒气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, '拿答 其余 馀 的事,凡 他所 行的, 都写 在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, ' 亚撒 和 以色列 王 巴沙 在世的日子常常 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, '犹大 王 亚撒 第三 年,亚希雅 的儿子 巴沙 在得撒 登基作 以色列 众人 的王 共二十 四 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, '他行 耶和华 眼中 看为恶的事,行 耶罗波安 所行的道,犯 他使 以色列人 陷在罪 里的那罪。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, '耶和华 的话 临 到 哈拿尼 的儿子 耶户,责备 巴沙 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, '「我既 从 尘埃 中提拔你,立你 作 我民 以色列 的君,你竟行 耶罗波安 所行的道, 使 我民 以色列 陷在罪里,惹我发怒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, ' 我必除尽 你 和 你的家, 使 你的家 像尼八 的儿子 耶罗波安 的家一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, '凡属巴沙的人,死 在城中 的必被狗 吃,死 在田野 的必被空中 的鸟 吃。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, '巴沙 其余 馀 的事,凡他所 行 的和他的勇力, 都写 在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, '巴沙 与 他列祖 同睡,葬 在得撒。他儿子 以拉 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, ' 耶和华 的话 临 到哈拿尼 的儿子 先知 耶户,责备 巴沙 和 他的家,因 他行 耶和华 眼中 看为恶 的 一切事,以他手 所做的 惹耶和华发怒,像 耶罗波安 的家一样,又因 他杀了 耶罗波安的全家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, '犹大 王 亚撒 二十 六 年,巴沙 的儿子 以拉 在得撒 登基 作 以色列 王共二年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, '有管理 他一半 战 车 的臣子 心利 背叛 他。当他 在得撒 家 宰 亚杂 家 里喝 醉的时候, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, '心利 就进去 杀了他,篡了他 的位。这是犹大 王 亚撒 二十 七 年的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, ' 心利一坐 王 位 就杀了 巴沙 的全 家,连他的亲属、朋友 也没有 留下一个 男丁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, '心利 这样灭绝 巴沙 的全 家,正如 耶和华 藉 借 先知 耶户 责备 巴沙 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, '这是因 巴沙 和他儿子 以拉 的 一切 罪,就是 他们使 以色列人 陷在罪里的那罪,以虚无的神 惹 耶和华─以色列 神 的怒气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, '以拉 其余 馀 的事,凡 他所 行的, 都写 在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, '犹大 王 亚撒 二十 七 年,心利 在得撒 作王 七 日。那时民 正安营 围攻 非利士的 基比顿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, '民 在营中 听 说 心利 背叛,又 杀了 王,故此以色列 众人 当 日 在营 中立 元帅 暗利 作 以色列 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, '暗利 率领 以色列 众人,从基比顿 上去,围困 得撒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, ' 心利 见 城 破失,就进了 王 宫 的卫所,放火 焚烧 宫 殿,自焚 而死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, '这是因 他 犯 罪,行 耶和华 眼中 看为恶的事,行 耶罗波安所行的,犯 他使 以色列人 陷在罪里的 那罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, '心利 其余 馀 的 事 和他背叛 的情形 都写 在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, '那时,以色列 民 分 为两半: 一半 随 从 基纳 的儿子 提比尼,要立他作王;一半 随从 暗利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, '但随从 暗利 的 民 胜过 随从 基纳 的儿子 提比尼 的民。提比尼 死了,暗利 就作了王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, '犹大 王 亚撒 三十 一 年,暗利 登基 作 以色列 王共十 二 年;在得撒 作王 六 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, '暗利用二他连得 银子 向 撒玛 买 了 撒马利亚 山,在山 上造城,就按著 山 的原主 撒玛 的名,给所 造 的城 起 名 叫 撒马利亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, '暗利 行 耶和华 眼中 看为恶的事,比 他以前 的列王 作恶更甚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, '因他行了 尼八 的儿子 耶罗波安所行的,犯 他使 以色列人 陷在罪里 的那罪,以虚无的神 惹 耶和华─以色列 神 的怒气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, '暗利 其余 馀 的事 和他所 显出 的勇力 都写 在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, '暗利 与 他列祖 同睡,葬 在撒马利亚。他儿子 亚哈 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, '犹大 王 亚撒 三十 八 年,暗利 的儿子 亚哈 登基 作了 以色列王。暗利 的儿子 亚哈 在撒马利亚 作 以色列 王 二十 二 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, '暗利 的儿子 亚哈 行 耶和华 眼中 看为恶的事,比 他以前 的列王更甚, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, ' 犯了 尼八 的儿子 耶罗波安 所犯的罪;他还以为轻,又娶了 西顿 王 谒巴力 的女儿 耶洗别 为妻,去 事奉 敬拜 巴力, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, '在撒马利亚 建造 巴力 的庙,在庙里 为巴力 筑 坛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, '亚哈 又做 亚舍拉,他 所行 的惹 耶和华─以色列 神 的怒气,比 他以前 的 以色列 诸王 更甚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, '亚哈在位的时候,有伯特利人 希伊勒 重修 耶利哥城;立根基的时候,丧了长子 亚比兰;安 门的时候,丧了幼子 西割,正如 耶和华 藉 借 嫩 的儿子 约书亚 所说 的话。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, '基列 寄居的 提斯比人 以利亚 对 亚哈 说:「我指著所 事奉 永生 耶和华─以色列的 神起誓,这 几年 我若不 祷告,必不 降露,不下雨。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, '耶和华 的话 临 到以利亚 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, '「你离开  这里 往 东去,藏 在 约旦河 东边 的 基立 溪旁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, '你要 喝 那溪里的水,我已吩咐 乌鸦 在那里 供养你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, '于 是以利亚 照著耶和华 的话,去 住 在 约旦河 东 的 基立 溪旁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, '乌鸦 早 晚 给他 叼饼 和肉 来,他也 喝 那溪里的水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, ' 过了 些日子,溪水 就干了,因为 雨 没 有 下在地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, '耶和华 的话 临 到他 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, '「你起身 往西顿 的 撒勒法去,住 在那里; 我已吩咐 那里 的一个寡 妇 供养你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, '以利亚就起身 往撒勒法 去。到了 城 门,见 有一个寡妇 在那里 捡 柴,以利亚呼叫 她 说:「求 你用器皿 取 点 水 来给我 喝。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, '她去 取水的时候,以利亚又呼叫 她 说:「也求你 拿 点 饼 来给我!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, '她说:「我指著永生 耶和华─你的 神起誓,我 没有 饼,坛 内只有 一把 面 麺,瓶 里只有一点 油;我现在 找 两根 柴,回 家要为我 和我儿子 做饼;我们吃了,死就死吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, '以利亚 对她 说:「不要 惧怕!可以照你所说的 去 做吧!只要 先 为我 做 一个小 饼 拿来 给我,然后 为你 和你的儿子 做饼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, '因为 耶和华─以色列的 神 如此 说:坛 内的面 麺 必不 减少,瓶 里的油 必不 缺短,直到 耶和华 使雨 降 在 地 上 的日子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, '妇人就照以利亚 的话 去 行。她 和她家中的人,并以利亚,吃了 许多日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, '坛 内的面 麺 果不 减少,瓶 里的油 也不 缺短,正如耶和华 藉 借 以利亚 所 说 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, ' 这 事 以后,作那家 主母 的妇人,她儿子 病了; 病 得甚 重,以致 身 无 气息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, '妇人对 以利亚 说:「神 人哪,我 与你 何干?你竟到我 这里来,使 神想念 我的罪,以致 我的儿子 死呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, '以利亚对她 说:「把 你儿子 交 给我。」以利亚就从妇人怀中 将孩子接过来,抱 到 他 所 住 的楼中,放 在 自己的床上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, '就求告 耶和华 说:「耶和华─我的 神啊,我 寄居 在 这 寡妇的家里,你就 降祸 与她,使 她的儿子 死了吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, '以利亚三 次 伏 在 孩子的身上,求告 耶和华 说:「耶和华─我的 神啊,求 你使这 孩子 的灵魂 仍入 他的身体!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, '耶和华 应允 以利亚 的话,孩子 的灵魂 仍入 他的身体,他就活了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, '以利亚 将 孩子 从 楼上 抱 下来,进屋子 交 给他母亲, 说:「看哪,你的儿子 活了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, '妇人 对 以利亚 说:「现在 我知道 你 是神 人,耶和华 藉 借你口 所说的话 是真的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, ' 过了许久,到第三 年,耶和华 的话 临 到 以利亚 说:「你去,使 亚哈 得见你;我要降 雨 在 地 上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, '以利亚 就去,要使 亚哈 得见他。那时,撒马利亚 有大 饥荒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, '亚哈将他的 家 宰 俄巴底 召了来。(俄巴底 甚 是 敬畏 耶和华, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, ' 耶洗别 杀 耶和华 众先知的时候,俄巴底 将一百个 先知 藏了,每五十 人 藏 在一个洞里,拿饼 和水 供养他们。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, '亚哈 对 俄巴底 说:「我们走 遍这地,到 一切 水 泉 旁和 一切 溪边,或者 找得著 青草,可以救活 骡 马,免得 绝了 牲畜。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, '于 是二人 分 地 游行,亚哈 独 走 一 路,俄巴底 独 走 一 路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, ' 俄巴底 在路 上恰 与以利亚 相遇,俄巴底认出他来,就俯伏 在 地,说:「你 是 我主 以利亚不是?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, '回答说:「是。你去 告诉 你主人说,以利亚 在这里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, '俄巴底说:「仆人有什么 罪,你 竟 要将 我 交 在亚哈 手里,使他杀我呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, '我指著永生 耶和华─你的 神起誓,无论 哪 一邦 哪一国, 我主 都打发 人去找你。若说 你没有在那里,就必使 那邦 那国 的人起誓说,实在 是找 不著你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, '现在 你 说,要去 告诉 你主人说,以利亚 在这里; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, '恐怕我 一 离开  你,耶和华 的灵 就提你 到 我所 不 知道的地方去。这样,我去 告诉 亚哈,他若找 不著你,就必杀我;仆人 却是自幼 敬畏 耶和华的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, '耶洗别 杀 耶和华 众先知的时候,我将耶和华 的一百 个 先知 藏了,每 五十 人 藏在一个洞里,拿饼 和水 供养他们,岂没有 人将这事 告诉 我主吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, '现在 你 说,要去 告诉 你主人说,以利亚 在这里,他必杀我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, '以利亚 说:「我指著所 事奉 永生 的万军 之耶和华起誓,我今日 必 使亚哈 得见我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, '于 是俄巴底 去 迎著 亚哈,告诉 他;亚哈 就去 迎著 以利亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, ' 亚哈 见了 以利亚, 便说:「使以色列 遭灾 的就是 你吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, '以利亚说:「使 以色列 遭灾 的不是我,乃是 你 和你父 家;因为你们离弃 耶和华 的诫命,去随 从 巴力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, '现在 你当差遣人,招聚 以色列 众人 和 事奉巴力 的那四 百 五十个 先知,并 耶洗别 所供养 事奉亚舍拉 的那四 百 个先知,使他们都上 迦密 山 去见我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, '亚哈 就差遣 人招聚 以色列 众 人 和 先知 都上 迦密 山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, '以利亚 前来 对 众 民 说:「你们 心持 两 意 要到 几时呢?若 耶和华是 神,就当顺 从耶和华;若 巴力是 神,就当顺 从巴力。」众民 一言 不 答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, '以利亚 对 众民 说:「作耶和华 先知 的只剩下 我 一个人;巴力 的先知 却有四 百 五十个 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, '当给 我们 两只 牛犊,巴力的先知 可以挑选 一只,切成块子,放 在 柴上,不要 点 火;我 也预备 一只 牛犊 放 在 柴上,也不 点 火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, '你们求告 你们神 的名,我 也求告 耶和华 的名。那 降火 显应的 神,就 是 神。」众 民 回答 说:「这话 甚好。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, '以利亚 对巴力 的先知 说:「你们 既是 人多,当先 挑选 一只 牛犊,预备好了,就求告 你们神 的名,却不要 点 火。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, '他们 将 所 得 的牛犊 预备好了,从早晨 到 午间,求告 巴力 的名 说:「巴力啊,求你应允我们!」却没有 声音,没有 应允的。他们在 所 筑 的坛 四围踊跳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, '到了 正午,以利亚 嬉笑 他们,说:「大 声 求告吧!因为 他是 神,他或 默想,或 走到一边,或 行路,或 睡觉,你们当叫醒他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, '他们大 声 求告,按著他们的规矩,用刀 枪 自割、自刺,直到 身体 流 血。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, ' 从午 后 直到 献 晚祭的时候,他们狂呼乱叫,却没有 声音,没有 应允的,也没有 理会的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, '以利亚 对众 民 说:「你们到 我这里来。」众 民 就到 他那里。他便重修 已经毁坏 耶和华 的坛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, '以利亚 照雅各 子孙 支派 的数目,取了 十 二块 石头(耶和华 的话 曾临 到 雅各 说:「你的名 要叫 以色列」), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, '用 这些石头 为耶和华 的名 筑 一座坛,在坛的 四围 挖 沟,可容 谷种 二细亚, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, '又在坛上摆好了 柴,把 牛犊 切成块子 放 在 柴上,对众人说:「你们用四个 桶 盛满 水,倒 在 燔祭 和 柴上」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, '又说:「倒第二次。」他们就倒第二次;又说:「倒第三次。」他们就倒第三次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, '水 流 在坛的 四围, 沟 里也 满了 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, '到了 献 晚祭的时候,先知 以利亚 近前来,说:「亚伯拉罕、以撒、以色列的 神,耶和华啊,求你今日 使人知道 你 是以色列的 神,也知道我 是你的仆人,又是奉你的命 行 这 一切 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, '耶和华啊,求你应允我,应允我!使这 民 知道 你─耶和华是 神,又知道是你 叫 这民的心 回转。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, '于 是,耶和华 降下 火来,烧尽 燔祭、 木柴、 石头、 尘土,又 烧干 沟 里的 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, '众 民 看见了,就俯伏 在 地,说:「耶和华 是 神!耶和华 是 神!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, '以利亚 对他们 说:「拿住 巴力 的先知,不容 一人 逃脱!」众人就拿住他们。以利亚 带 他们到 基顺 河边,在那里 杀了他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, '以利亚 对亚哈 说:「你现在可以上去 吃 喝,因为 有多 雨 的响声了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, '亚哈 就上去 吃 喝。以利亚 上了 迦密山 顶,屈身 在地,将脸 伏 在 两膝之中; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, '对 仆人 说:「你上去,向 海 观看。」仆人就上去 观看,说:「没有 什么。」他说:「你再去观看。」如此七 次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, ' 第七次 仆人说:「我看见 有一小片 云 从海 里上来,不过如人 手那样大。」以利亚说:「你上去 告诉 亚哈,当套 车下去,免得 被雨 阻挡。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, ' 霎时间,天 因风 云 黑暗,降下 大 雨。亚哈 就坐车 往耶斯列 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, '耶和华的灵(原文是手)降 在 以利亚身上,他就束上 腰,奔 在亚哈 前头,直到 耶斯列 的城门。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, '亚哈 将 以利亚 一切 所 行 的和 他用刀 杀 众 先知 的事 都 告诉 耶洗别。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, '耶洗别 就差遣 人 去见 以利亚,告诉他说:「明日 约在这时候,我若不 使 你的性命 像那些 人 的性命一样,愿 神明 重重地 降 罚与我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, '以利亚见 这光景就起来 逃 命,到了 犹大 的 别是巴,将 仆人 留 在那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, '自己 在旷野 走了 一日 的路程,来到 一棵 罗腾 树下(小树名,松类;下同),就坐 在那里求 死,说:「耶和华啊,罢了! 求你取 我的性命,因为 我 不 胜 于 我的列祖。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, '他就躺 在 罗腾树 下,睡著了。 有 一个天使 拍 他,说:「起来 吃吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, '他观看,见 头 旁有一瓶 水 与炭火 烧的饼,他就吃了 喝了,仍然 躺下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, '耶和华 的使者 第二次 来 拍 他,说:「起来 吃吧!因为 你 当走的路 甚远。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, '他就起来 吃了 喝了,仗著这 饮食 的力,走了 四十 昼 夜,到了 神 的山,就是何烈山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, '他在那里 进了 一个洞,就住 在洞中。 耶和华 的话 临到他 说:「以利亚啊,你 在这里 做什么?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, '他说:「我为耶和华─万军之 神 大发 热心;因为 以色列 人 背弃了 你的约,毁坏了 你的坛,用刀 杀了 你的先知,只剩下 我 一个人,他们还要寻 索 我的命。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, '耶和华说:「你出来 站 在山上,在我 面前。」那时 耶和华 从那里经过,在他 面前 有烈 风 大作,崩 山 碎 石,耶和华 却不 在风中;风 后 地震,耶和华 却不 在其中; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, '地震 后 有火,耶和华 也不 在火中;火 后 有微 小 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, ' 以利亚 听见,就用外衣 蒙上 脸,出来 站 在洞 口。 有声音 向他 说:「以利亚啊,你 在这里 做什么?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, '他说:「我为耶和华─万军之 神 大发 热心;因为 以色列 人 背弃了 你的约,毁坏了 你的坛,用刀 杀了 你的先知,只剩下 我 一个人,他们还要寻 索 我的命。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, '耶和华 对他 说:「你回 去,从旷野 往 大马士革去。到了那里,就要膏 哈薛 作 亚兰 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, '又膏 宁示 的孙子 耶户 作 以色列 王,并膏亚伯‧米何拉人 沙法 的儿子 以利沙 作先知 接续你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, '将来 躲避 哈薛 之刀的,必被耶户 所杀;躲避 耶户 之刀的,必被以利沙 所杀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, '但我在以色列人 中为自己留下 七 千人,是 未 曾向巴力 屈 膝的, 未 曾与巴力 亲 嘴的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, '于 是,以利亚离开  那里走了,遇见 沙法 的儿子 以利沙 耕地;在他前头 有十 二 对牛,自己 赶著第十 二对。以利亚 到他 那里去,将自己的外衣 搭 在他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, '以利沙就离开  牛,跑 到 以利亚那里,说:「求 你容我先与父 母 亲嘴,然后我便跟 随你。」以利亚对他 说:「你回 去吧, 我向你 做了 什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, '以利沙就离开 他 回去, 宰了 一对 牛,用套牛 的器具 煮 肉 给 民 吃,随后就起身 跟 随 以利亚,服事他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, '亚兰 王便‧哈达 聚集 他的全 军,率领 三十 二个 王,带著车 马 上来 围 攻 撒马利亚; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, '又差遣 使者 进城 见 以色列 王 亚哈,对他 说:「便‧哈达 如此 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, '你的金 银 都要 归我,你妻子 儿女 中最美 的也要 归我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, '以色列 王 回答 说:「我主 我王啊,可以依著你的话,我 与 我所有的 都归你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, '使者 又来 说:「便‧哈达 如此 说: 我已差遣 人去见你,要你将你的金 银、妻子、儿女 都给 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, '但 明日 约在这时候,我还要差遣 臣仆 到你那里,搜查 你的家 和 你仆人 的家, 将你眼中 一切 所喜爱 的都 拿了去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, '以色列 王 召了 国中的 长老来,对他们说:「请 你们 看看, 这 人是怎样地谋 害我, 他先差遣 人到我这里来,要我的妻子、儿女,和金 银,我并没有 推辞 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, ' 长老 和 百姓 对王 说:「不要 听从他,也不要 应允他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, '故此,以色列王对便‧哈达 的使者 说:「你们告诉 我主 我王说:王头一次 差遣 人向 仆人 所要的,仆人都 依从;但这次 所要的,我不 能 依从。」使者 就去 回 覆 复便‧哈达。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, '便‧哈达 又差遣 人去见亚哈 说:「撒马利亚 的尘土 若 够 跟从我 的 人 每人 捧一捧的,愿 神明 重重地 降 罚 与我!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, '以色列 王 说:「你告诉他说,才顶盔贯甲的,休要 像摘盔卸甲 的夸口。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, '便‧哈达 和诸王 正 在帐幕 里喝酒, 听见 这 话,就对 他臣仆 说:「摆队吧!」他们就摆队 攻 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, '有 一个 先知 来 见 以色列 王 亚哈,说:「耶和华 如此 说:『 这 一大 群人 你看见了吗? 今日 我必将他们交 在你手里,你就知道 我 是耶和华。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, '亚哈 说:「藉 借著谁呢?」他回答说:「耶和华 说,藉 借著跟从省 长 的少年人。」亚哈说:「要谁 率领呢?」他说:「要你亲自率领。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, '于 是亚哈数点 跟从省 长 的少年人,共有 二 百 三十 二名,后 又数点 以色列 的众兵,共有七 千名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, '午间,他们就出城;便‧哈达 和帮助 他 的三十 二 个王 正 在帐幕 里痛 饮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, '跟从省 长 的少年人 先 出城;便‧哈达 差遣人去探望,他们回报 说:「有人 从撒马利亚 出来了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, '他说:「他们若 为讲和 出来,要活 捉他们;若 为打仗 出来,也要活 捉他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, '跟从省 长的 少年人 出 城,军兵 跟随他们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, '各人 遇见敌人 就杀。亚兰人 逃跑,以色列人 追赶他们;亚兰 王便‧哈达 骑著 马 和马兵 一同逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, '以色列 王 出城 攻打 车 马,大大 击杀 亚兰人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, '那先知 来 见 以色列 王,对他 说:「你当 自强,留心 怎样 防备;因为 到明 年这时候,亚兰 王 必上来 攻击你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, '亚兰 王 的臣仆 对亚兰王 说:「以色列人的神 是山 神,所以 他们胜 过我们;但 在平原 与他们 打仗,我们必定 得胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, '王当这 样 行:把诸 王 革去,派 军长 代替他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, '又照著王丧失 军兵之数, 再招募 一军,马 补马,车 补车,我们在平原 与他们 打仗,必定 得胜。」王便听 臣仆的话 去行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, ' 次 年,便‧哈达 果然点齐 亚兰人 上 亚弗去,要与 以色列人 打仗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, '以色列 人 也点齐军兵,预备食物,迎著 亚兰人出去, 对著他们 安营,好像两 小群 山羊羔;亚兰人 却满了 地面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, '有神 人 来 见 以色列 王,说:「耶和华 如此 说:『亚兰人 既 说我─耶和华 是山 神,不 是 平原 的神,所以我必将 这 一大 群人 都 交 在你手中,你们就知道 我 是耶和华。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, '以色列人 与亚兰人 相对 安营 七 日,到 第七 日 两军交 战 ;那一 日 以色列 人 杀了 亚兰人 步兵 十万, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, '其余 馀 的逃 入 亚弗 城;城墙 塌倒,压死 剩下 的二 万七 千 人。便‧哈达 也逃 入 城,藏在严密 的屋子里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, '他的臣仆 对他 说:「 我们听说 以色列 王 都 是 仁慈 的王,现在我们不如 腰 束 麻布,头 套绳索,出去 投降 以色列 王,或者 他存留 王的性命。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, '于 是他们腰 束 麻布,头 套绳索,去 见 以色列 王,说:「王的仆人便‧哈达 说,求 王存留 我的性命。」亚哈说:「他还 活著吗?他是 我的兄弟。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, '这些人 留心探出 他的口气来,便急忙 就著 他的话说:「便‧哈达 是王的兄弟!」王说:「你们去 请他来。」便‧哈达 出来 见王,王就请他上 车。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, '便‧哈达对王 说:「我父 从 你父 那里所 夺 的城邑,我必归还。你可以在大马士革 立 街市,像 我父 在撒马利亚 所立的一样。」亚哈说:「我 照此立约,放你回去」,就与他 立 约,放他去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, '有先知 的一 个 门徒 奉耶和华 的命 对 他的同伴 说:「 你打我吧!」那人 不肯 打他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, '他就对那人 说:「你既 不 听从 耶和华 的话,你 一离 开 我,必有狮子 咬死你。」那人一离 开 他,果然遇见 狮子,把他咬死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, '先知的门徒又遇见 一个人,对他说:「 你打我吧!」那人 就打他,将他打 伤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, '他 就去了,用头巾 蒙 眼,改换面目,在 路 旁等候 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, ' 王 从那里经过,他 向 王 呼叫 说:「仆人 在阵 上的时候, 有人 带了 一个人 来,对我说:『你看守 这 人,若 把他失了,你的性命 必 代替 他的性命;不然,你必交出 一他连得 银子来。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, '仆人 正 在忙乱 之间,那人 就不见了。」以色列 王 对他 说:「你 自己定妥了,必照样 判断你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, '他急忙 除掉 蒙 眼 的头巾,以色列 王 就认出 他 是 一个先知。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, '他对王 说:「耶和华 如此 说:『因 你将 我定要灭绝 的人 放去,你的命 就必 代替 他的命,你的民 也必代替 他的民。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, '于 是以色列 王 闷闷不乐地 回 到 撒马利亚,进了 他的宫。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, ' 这 事 以后,又有一事。耶斯列人 拿伯 在耶斯列 有 一个葡萄园,靠近 撒马利亚 王 亚哈 的宫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, '亚哈 对 拿伯 说:「你将 你的葡萄园 给 我 作 菜 园,因为 是 靠 近 我的宫;我就把更 好 的葡萄园 换 给 你,或是你 要银子,我就按著 价值 给 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, '拿伯 对 亚哈 说:「我 敬畏耶和华,万不敢 将 我先人 留下的产业 给 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, '亚哈 因 耶斯列人 拿伯 说「我不敢 将 我先人 留下的产业 给 你」,就闷闷 不乐地 回 宫,躺 在 床上,转 脸向内,也不 吃 饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, '王后 耶洗别 来 问他 说:「你为什么 心里 这样 忧闷,不 吃 饭呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, '他回答 说:「因 我 向 耶斯列人 拿伯 说:『你将 你的葡萄园 给 我,我给你价银,或是 你 愿 意,我就把别的葡萄园 换 给 你』;他却说:『我不 将 我的葡萄园 给 你。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, '王后 耶洗别 对亚哈 说:「你 现在 是治理 以色列 国不是?只管起来,心里 畅畅快快地 吃 饭,我 必将 耶斯列人 拿伯 的葡萄园 给 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, '于 是托 讬亚哈 的名 写 信,用王的印 印上,送 给 那些 与 拿伯 同城 居住的 长老 贵胄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, '信 上写著 说:「你们当宣告 禁食,叫 拿伯 坐 在民 间的高位上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, '又叫两 个 匪 徒 坐 在拿伯对面,作见证 告他说:『你谤渎 神 和王了』;随后就把他拉出去 用石头打 死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, '那些 与拿伯同城 居住 的长老 贵胄 得了 耶洗别的信, 就照 信 而行, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, '宣告 禁食,叫 拿伯 坐 在民 间的高位上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, '有两 个 匪 徒 来,坐 在拿伯的对面, 当著 众民 作见证 告 他 说:「拿伯 谤渎 神 和王了!」众人就把他拉到 城 外,用石头 打 死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, '于 是打发 人去见 耶洗别,说:「拿伯 被石头打 死了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, ' 耶洗别 听见 拿伯 被石头打 死, 就对 亚哈 说:「你起来 得 耶斯列人 拿伯 不肯 为价银 给 你 的 葡萄园吧! 现在他已经 死了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, ' 亚哈 听见 拿伯 死了, 就起来,下去 要得 耶斯列人 拿伯 的葡萄园。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, '耶和华 的话 临 到 提斯比人 以利亚 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, '「你起来,去 见 住撒马利亚 的 以色列 王 亚哈, 他下去 要得 拿伯 的葡萄园,现今正在那 园里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, '你要 对他 说:『耶和华 如此 说:你杀了人,又 得他的产业吗?』又要 对他 说:『耶和华 如此 说:狗 在何 处 舔 拿伯 的血, 也 必在何处舔 你的血。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, '亚哈 对 以利亚 说:「我仇敌啊,你找到我吗?」他回答说:「我找到你了;因为 你卖了自己,行 耶和华 眼中 看为恶的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, '耶和华说:『我 必使灾祸 临 到你,将你 除尽。凡属你 的男丁,无论困住的、自由的,都从以色列 中剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, '我必使 你的家 像尼八 的儿子 耶罗波安 的家,又像亚希雅 的儿子 巴沙 的家;因为 你惹我 发 怒,又使 以色列人 陷在罪里。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, '论到 耶洗别,耶和华 也 说:『狗 在耶斯列 的外郭 必吃 耶洗别的肉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, '凡属亚哈的人,死 在城 中的必被狗 吃,死 在田野 的必被空中 的鸟 吃。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, '(从来 没 有 像亚哈的,因 他自卖,行 耶和华 眼中 看为恶的事,受了 王后 耶洗别 的耸动; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, '就照 耶和华 在以色列 人 面前 所 赶出 的亚摩利人,行了 最 可憎恶的事,信 从 偶像。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, ' 亚哈 听见 这 话,就撕裂 衣服,禁食, 身 穿 麻布,睡卧 也穿著麻布,并且缓缓 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, '耶和华 的话 临 到 提斯比人 以利亚 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, '「 亚哈 在我面前 这样自卑,你看见了吗?因 他在我面前 自卑,他还在世的时候,我不 降 这祸;到他儿子 的时候,我必降 这祸 与 他的家。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, ' 亚兰国 和 以色列国 三 年 没有 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, '到 第三 年,犹大 王 约沙法 下去 见 以色列 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, '以色列 王 对 臣仆 说:「你们不知道 基列 的拉末 是属我们的吗?我们 岂可静坐不动,不从亚兰 王 手 里夺回来吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, '亚哈问 约沙法 说:「你肯同我 去 攻取 基列 的拉末吗?」约沙法 对 以色列 王 说:「你 我不分彼此,我的民 与你的民一样,我的马 与你的马一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, '约沙法 对 以色列 王 说:「请 你先 求问 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, '于 是以色列 王 招聚 先知,约有四 百 人,问他们 说:「我上去 攻取 基列 的拉末 可以 不可以?」他们说:「可以上去,因为主 必将那城交 在王 的手里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, '约沙法 说:「这里 不是 还 有耶和华的 先知,我们可以求问 他吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, '以色列 王 对 约沙法 说:「还有 一个 人,是音拉 的儿子 米该雅,我们可以托 讬他 求问 耶和华。只是我 恨他;因为 他指著我 所说的预言,不 说吉语,单 说凶言。」约沙法 说:「王 不必 这样 说。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, '以色列 王 就召了 一个 太监来,说:「你快去,将音拉 的儿子 米该雅召来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, '以色列 王 和犹大 王 约沙法 在撒马利亚 城门 前 的空场上,各 穿 朝服,坐 在 位上,所有的 先知 都在他们面前 说预言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, '基拿拿 的儿子 西底家 造了 两个铁 角,说:「耶和华 如此 说:『你要用这 角抵触 亚兰人,直到 将他们灭尽。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, '所有的 先知 也都这样 预言 说:「可以上 基列 的拉末去,必然得胜,因为耶和华 必将那城交 在王 的手中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, '那 去 召 米该雅 的使者 对米该雅 说:「 众先知 一 口 同音地都向 王 说吉 言, 你不如与他们 说一样 的话,也说 吉 言。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, '米该雅 说:「我指著永生 的耶和华起誓, 耶和华 对我 说 什么,我就说 什么。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, '米该雅到 王面前,王 问他 说:「米该雅啊,我们上去 攻取 基列 的拉末 可以 不可以?」他回答 说:「可以上去,必然得胜,耶和华 必将那城交 在王 的手中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, '王 对他 说:「我 当嘱咐你 几 次,你才 奉耶和华 的名 向我 说 实话呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, '米该雅说:「我看见 以色列 众民 散 在 山上,如同 没有 牧人 的羊群一般。耶和华 说:『这民 没有 主人,他们可以平平安安地 各 归 各家去。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, '以色列 王 对 约沙法 说:「我岂没有 告诉 你,这人指著我 所说的预言,不 说吉语 单 说凶言吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, '米该雅说:「 你要听 耶和华 的话!我看见 耶和华 坐 在 宝座上,天上 的万 军 侍立 在 他左 右。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, '耶和华 说:『谁 去引诱 亚哈 上 基列 的拉末 去阵亡呢?』这个 就这样 说,那个 就那样 说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, '随后有一个神灵 出来,站 在耶和华 面前,说:『我 去引诱他。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, '耶和华 问他 说:『你用何法呢?』他说:『我去,要在他众 先知 口中 作 谎言 的灵。』耶和华说:『这样,你必 能 引诱他,你去 如此 行吧!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, '现在 耶和华 使 谎言 的灵 入了你这些 先知 的口,并且耶和华 已经命定 降祸 与你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, '基拿拿 的儿子 西底家 前来,打 米该雅 的 脸,说:「耶和华 的灵 从哪里 离开  我 与你 说话呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, '米该雅 说:「你 进 严密 的屋子 藏躲 的 那 日,就必看见了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, '以色列 王 说:「将 米该雅 带 回,交给 邑 宰 亚们 和 王 的儿子 约阿施,说 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, '王 如此 说,把 这个 人下 在监里,使他受苦,吃 不饱 喝不足,等候 我平平安安地 回来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, '米该雅 说:「你若 能 平平安安地 回来,那就是耶和华 没有 藉 借我 说这话了」;又说:「众民哪,你们都 要听!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, '以色列 王 和犹大 王 约沙法 上 基列 的拉末去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, '以色列 王 对 约沙法 说:「我要改装 上 阵,你 可以仍穿 王服。」以色列 王 就改装 上 阵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, '先是亚兰 王 吩咐 他的 三十 二个 车 兵长 说:「他们的兵将,无论 大 小,你们都不可 与他们争战 , 只要 与 以色列 王争战 。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, ' 车 兵长 看见 约沙法,便 说:「这必 是 以色列 王!」就转过去 与他 争战 ,约沙法 便呼喊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, ' 车 兵长 见 不 是 以色列 王,就转去 不追他了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, '有一人 随便 开  弓,恰巧射入 以色列 王 的 甲 缝 里。王对赶车的 说:「 我受了重伤,你转 过车来,拉我 出 阵吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, '那 日,阵势 越战 越猛,有人扶 王 站 在车上,抵挡 亚兰人。到晚上,王就死了,血 从伤处 流 在 车 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, '约在日 落的时候,有号令 传遍 军中,说:「各 归 本城,各 归 本地吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, '王 既死了,众人将他送到 撒马利亚, 就葬在那里; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, '又有人把 他的车 洗 在 撒马利亚 的池旁(妓女 在那里洗澡),狗 来舔 他的血,正如耶和华 所 说 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, '亚哈 其余 馀 的事,凡 他所 行 的和他所 修造 的象牙 宫,并所 建筑 的一切 城邑, 都写 在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, '亚哈 与 他列祖 同睡。他儿子 亚哈谢 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, '以色列 王 亚哈 第四 年,亚撒 的儿子 约沙法 登基 作了 犹大王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, '约沙法 登基 的时候年 三十 五 岁,在耶路撒冷 作王 二十 五 年。他母亲 名 叫阿苏巴,乃示利希 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, '约沙法行 他父亲 亚撒所行的 道,不 偏离 左右,行 耶和华 眼中 看为正的事;只是 邱坛 还没有 废去,百姓 仍在那里 献祭 烧香。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, '约沙法 与 以色列 王 和好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, '约沙法 其余 馀 的事 和他所 显出 的勇力,并他怎样 争战 , 都写 在 犹大 列王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, '约沙法将他父亲 亚撒 在世 所 剩下 的 娈童 都从 国 中除去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, '那时以东 没有 王,有总督 治理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, '约沙法 制造 他施 船只,要往 俄斐去,将金子运来;只是没有 去,因为 船在以旬‧迦别 破坏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, ' 亚哈 的儿子 亚哈谢 对 约沙法 说:「容我的仆人 和 你的仆人 坐船 同去吧!」约沙法 却不 肯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, '约沙法 与 列祖 同睡。葬在 大卫 城 他列祖的坟地里。他儿子 约兰 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, '犹大 王 约沙法 十 七 年,亚哈 的儿子 亚哈谢 在撒马利亚 登基,作 以色列 王 共二年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, '他行 耶和华 眼中 看为恶的事,效法 他的父 母,又 行 尼八 的儿子 耶罗波安 使 以色列人 陷在罪里的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, '他照他父亲 一切 所 行的,事奉 敬拜 巴力,惹 耶和华─以色列 神 的怒气。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, '亚哈 死 后,摩押 背叛 以色列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, '亚哈谢 在撒马利亚, 一日从 楼上 的栏杆 里掉下来,就病了;于 是差遣 使者 说:「你们去 问 以革伦 的神巴力.西卜,我这 病 能好 不能好。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, '但耶和华 的使者 对 提斯比人 以利亚 说:「你起来,去 迎著 撒马利亚 王 的使者,对他们 说:『你们 去 问 以革伦 神巴力.西卜,岂因 以色列 中没有 神吗?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, '所以 耶和华 如此 说:『你必不 下 你所 上的 床, 必定 要死!』」以利亚 就去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, '使者 回来 见王,王问他们 说:「你们为什么 回来呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, '使者回答 说:「有一个人 迎著我们 来,对我们 说:『你们 回去 见 差 你们 来的 王,对他 说:耶和华 如此 说,你 差 人去问 以革伦 神巴力.西卜,岂因 以色列 中没有 神吗?所以 你必不 下 所 上的 床, 必定 要死。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, '王问他们 说:「 迎著你们 来告诉 你们 这 话的,是怎 样 的人?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, '回答 说:「他 身穿毛衣,腰 束 皮 带。」王说:「这必是 提斯比人 以利亚。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, '于 是,王 差遣 五十夫 长,带领五十人 去见以利亚,他就上 到以利亚那里; 以利亚正坐 在 山 顶上。五十夫长对他 说:「神 人哪,王 吩咐 你下来!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, '以利亚 回答 说:「我 若 是神 人,愿 火 从 天上 降下来,烧灭 你 和 你那五十人!」于 是有火 从 天上 降下来,烧灭 五十夫长 和 他那五十人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, '王第二次 差遣 一个 五十夫 长,带领五十人 去见以利亚。五十夫长 对以利亚 说:「神 人哪,王 吩咐 你快快 下来!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, '以利亚 回答 说:「我 若 是神 人,愿 火 从 天上 降下来,烧灭 你 和 你那五十人!」于 是 神 的火 从 天上 降下来,烧灭 五十夫长 和 他那五十人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, '王第三次 差遣 一个五十夫 长,带领五十人去。这 五十夫 长 上 去, 双膝 跪 在以利亚 面前,哀求 他 说:「神 人哪,愿  我的性命 和你这 五十个 仆人 的性命 在你眼前 看为宝贵! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, ' 已经有火 从 天上 降下来,烧灭 前 两次 来的五十夫 长 和 他们各自带的五十人;现在 愿 我的性命 在你眼前 看为宝贵!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, '耶和华 的使者 对 以利亚 说:「你同著他 下去,不要 怕 他!」以利亚就起来,同著他 下去 见 王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, '对王 说:「耶和华 如此 说:『 你差 人 去问 以革伦 神巴力.西卜,岂因 以色列 中没有 神 可以求问吗?所以 你必不 下 所 上的 床, 必定 要死!』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, '亚哈谢果然死了,正如耶和华 借以利亚 所 说 的话。因 他 没 有 儿子,他兄弟约兰 接续他 作王,正在犹大 王 约沙法 的儿子 约兰 第二 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, '亚哈谢 其余 馀 所 行 的事 都写 在 以色列 诸王 记上。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, ' 耶和华 要用旋风 接 以利亚 升 天的时候,以利亚 与以利沙 从 吉甲 前往。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, '以利亚 对 以利沙 说:「 耶和华 差我 往 伯特利去,你可以 在这里 等候。」以利沙 说:「我指著永生 的耶和华,又敢在你面前起誓,我必不 离开 你。」于 是二人下到 伯特利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, '住伯特利 的 先知 门徒 出来 见 以利沙,对他 说:「 耶和华 今日 要接 你的师傅 离开  你,你知道不知道?」他说:「 我 知道,你们不要作声。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, '以利亚 对 以利沙 说:「 耶和华 差遣我 往耶利哥去,你可以 在这里 等候。」以利沙说:「我指著永生 的耶和华,又敢在你面前起誓,我必不 离开 你。」于 是二人到了 耶利哥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, '住耶利哥 的 先知 门徒 就近 以利沙,对他 说:「 耶和华 今日 要接 你的师傅 离开  你,你知道不知道?」他说:「 我 知道,你们不要作声。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, '以利亚 对以利沙 说:「 耶和华 差遣我 往约旦河去,你可以 在这里 等候。」以利沙说:「我指著永生 的耶和华,又敢在你面前起誓,我必不 离开 你。」于 是二 人一同前往。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, '有先知 门徒 去了 五十 人,远远地 站 在他们对面;二 人在 约旦河 边站住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, '以利亚 将 自己的外衣 卷起来,用以打 水,水就左 右 分开 ,二 人走 干地而过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, ' 过去之后,以利亚 对 以利沙 说:「我未曾 被接去 离开 你,你要我为你 做 什么,只管求我。」以利沙 说:「愿  感动你的灵 加 倍 地感动我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, '以利亚说:「你所求的 难得。虽然如此,我被接去 离开 你的时候,你若 看见 我,就必 得著;不然,必 得不著了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, ' 他们 正 走著 说话,忽 有火 车 火 马 将 二 人隔开 ,以利亚 就乘旋风 升 天去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, '以利沙 看见,就 呼叫说:「我父啊!我父啊!以色列 的战 车 马兵啊!」以后不 再 见他了。于 是以利沙把 自己的衣服 撕为 两 片。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, '他拾起 以利亚 身上 掉下来 的 外衣,回去 站 在 约旦河 边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, '他用 以利亚 身上 掉下来 的 外衣 打 水,说:「耶和华─以利亚的 神 在哪里呢?」 打 水之后,水也 左 右 分开 ,以利沙 就过来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, '住耶利哥 的 先知 门徒 从对面 看见他,就说:「感动以利亚 的灵 感动 以利沙了。」他们就来 迎接他,在他 面前俯伏 于 地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, '对他 说:「 仆人们 这里 有 五十 个 壮 士,求 你容他们去 寻找 你师傅,或者 耶和华 的灵 将他提起来,投 在某 山 某 谷。」以利沙说:「你们不必 打发人去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, '他们再三催促 他, 他难以推辞,就说:「你们打发人去吧!」他们便打发 五十 人去,寻找了 三 天,也没有 找著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, '以利沙 仍然在耶利哥 等候 他们回 到他那里;他对他们 说:「我岂没有 告诉 你们 不必 去吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, '耶利哥城 的人 对 以利沙 说:「 这城 的地势 美好, 我主 看见了;只是水 恶劣,土 产不熟而落。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, '以利沙说:「你们拿 一个新 瓶来,装 盐 给我」;他们就拿来 给他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, '他出 到 水 源,将盐 倒在水中,说:「耶和华 如此 说:『我治好 了这 水,从此 必 不 再 使人死,也不再使地土不生产。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, '于 是那水 治好了,直到 今 日,正如 以利沙 所 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, '以利沙从那里 上 伯特利去, 正 上去的时候,有些童子 从 城里 出来,戏笑 他 说:「秃头的 上去吧!秃头的 上去吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, '他回头 看见,就奉耶和华 的名 咒诅他们。于 是有两 个母熊 从 林中 出来,撕裂 他们 中间四十 二 个童子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, '以利沙从伯特利 上 迦密 山,又从迦密山 回到 撒马利亚。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, '犹大 王 约沙法 十 八 年,亚哈 的儿子 约兰 在撒马利亚 登基 作了 以色列 王 十 二 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, '他行 耶和华 眼中 看为恶的事,但 不致 像他父 母所行的,因为除掉 他父 所 造 巴力 的柱像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, '然而,他贴近 尼八 的儿子 耶罗波安 使 以色列人 陷在罪 里的那罪,总不 离开 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, '摩押 王 米沙 牧养许多羊,每年将十万 羊羔 的毛和十万 公绵羊 的毛 给 以色列 王进贡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, ' 亚哈 死后,摩押 王 背叛 以色列 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, '那 时 约兰 王 出 撒马利亚,数点 以色列 众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, '前行的时候,差 人去见 犹大 王 约沙法,说:「摩押 王 背叛 我,你肯同我 去 攻打 摩押吗?」他说:「我肯上去,你 我不分彼此,我的民 与你的民一样,我的马 与你的马一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, '约兰说:「我们从 哪 条路 上去呢?」回答说:「从以东 旷野 的路上去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, '于 是,以色列 王 和犹大 王,并以东 王,都一同去 绕行 七 日 的路程;军队 和所 带的 牲畜 没 有 水喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, '以色列 王 说:「哀哉! 耶和华 招聚 我们这 三 王,乃要交 在摩押人 的手里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, '约沙法 说:「这里 不是 有耶和华的 先知吗?我们可以托 讬他 求问 耶和华。」以色列王 的一个 臣子 回答 说:「这里 有沙法 的儿子 以利沙,就是从前服事以利亚的(原文是倒 水 在 以利亚 手上的)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, '约沙法 说:「他 必有 耶和华 的话。」于 是以色列 王 和约沙法,并以东 王 都下去 见他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, '以利沙 对 以色列 王 说:「我 与你 何干?去 问 你父亲 的先知 和 你母亲 的先知吧!」以色列 王 对他 说:「不要这样说, 耶和华 招聚 我们这 三 王,乃要交 在摩押人 的手里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, '以利沙 说:「我指著 所 事奉 永生 的万军 耶和华起誓, 我 若不 看 犹大 王 约沙法 的情面,必不 理 你,不 顾你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, '现在 你们给我 找 一个弹琴的来。」 弹 琴的时候,耶和华的灵(原文是手)就降 在以利沙身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, '他便说:「耶和华 如此 说:『你们要在这 谷中 满处 挖 沟; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, '因为 耶和华 如此 说:你们虽不 见 风,不 见 雨,这 谷 必满了 水,使你们 和牲畜 有水喝。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, '在耶和华 眼中 这 还算为小事,他也必将 摩押人 交 在你们手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, '你们必攻破 一切 坚 城 美 邑,砍伐 各种 佳 树,塞住 一切 水 泉,用石头 糟踏 一切 美 田。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, ' 次日早晨,约在献 祭的时候, 有水 从 以东 而来,遍地 就满了 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, '摩押 众人 听见 这三王 上来 要与他们 争战 ,凡 能顶 盔 贯甲的,无论老少,尽都聚集 站 在 边界上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, '次日早晨,日 光照 在 水上,摩押人 起来,看见 对面 水 红 如血, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, '就说:「这 是血啊!必是三王 互相 击杀,俱都 灭亡。摩押人哪,我们现在 去抢夺财物吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, '摩押人到了 以色列 营,以色列人 就起来 攻打 他们,以致他们在以色列人面前 逃跑。以色列人往前追杀 摩押人,直杀 入摩押的境内, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, '拆毁 摩押的城邑,各人 抛 石 填满 一切 美 田,塞住 一切 水 泉,砍伐 各种 佳 树,只 剩下吉珥‧哈列设 的石墙;甩石的兵 在四围 攻打那城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, '摩押 王 见 阵势 甚大,难以对敌,就率 领 七 百 拿 刀 的兵,要冲过 阵去到 以东 王那里,却是不 能; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, '便将 那 应当接续他 作王 的长 子,在 城上 献为 燔祭。 以色列人 遭遇 耶和华的大 怒(或译:招人痛恨),于 是三王离开  摩押王,各回 本国去了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, '有一 个 先知 门徒 的妻 哀求 以利沙 说:「你仆人─我丈夫 死了, 他 敬畏 耶和华 是你 所知道的。现在有债主 来,要取 我两 个儿子 作奴仆。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, '以利沙 问她 说:「我可以为你 做 什么呢?你告诉 我,你家里 有 什么?」她说:「婢女 家中 除了 一瓶 油之外,没有 什么。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, '以利沙说:「你去,向 你众 邻舍 借 空 器皿,不要 少借; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, '回到家里,关上 门,你 和你儿子 在里面 将油倒 在 所有的 器皿里,倒满了的 放在一边。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, '于 是,妇人离开  以利沙去了,关上 门,自己 和儿子 在里面;儿子 把器皿拿来,她 就倒油。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, ' 器皿 都满了,她对 儿子 说:「再 给我 拿 器皿来。」儿子说:「再 没有 器皿了。」油 就止住了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, '妇人去 告诉 神 人,神人说:「你去 卖 油 还 债,所剩的 你 和你儿子 可以靠著度日。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, ' 一日,以利沙 走 到 书念,在那里 有一个大 户的妇人 强留 他 吃 饭。此后,以利沙每从 那里 经过 就进去 吃 饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, '妇人对 丈夫 说:「 我看出 那常 从我们 这里经过 的是 圣洁 的神 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, '我们可以 为他 在墙 上盖 一间小 楼,在其中 安放 床榻、桌子、椅子、灯台, 他来 到我们这里,就可以住在 其间。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, ' 一日,以利沙来到 那里,就进了 那楼 躺卧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, '以利沙吩咐 仆人 基哈西 说:「你叫 这 书念妇人来。」他就把妇人 叫了来,妇人站在 以利沙面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, '以利沙吩咐仆人 说:「 你对她 说: 你既为我们 费了许多 心思,可以为你 做 什么呢?你 向 王 或 元帅 有 所求的没有?」她回答说:「我 在 我本乡 安居无事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, '以利沙对仆人说:「究竟当为她 做 什么呢?」基哈西 说:「 她 没有 儿子,她丈夫 也老了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, '以利沙说:「再叫 她来。」于 是叫了 她来,她就站 在门口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, '以利沙说:「明年 到这 时候,你 必抱 一个儿子。」她说:「 神 人,我主啊,不要 那样欺哄 婢女。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, '妇人 果然怀孕,到了 那 时候,生了 一个儿子,正如 以利沙 所说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, '孩子 渐渐长大, 一日 到 他父亲 和 收割的人那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, '他对 父亲 说:「我的头啊,我的头啊!」他父亲对 仆人 说:「把他抱 到 他母亲那里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, '仆人抱去,交 给 他母亲;孩子坐 在 母亲的膝上,到 晌午 就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, '他母亲抱他上了楼,将他放 在 神 人 的床上,关上门 出来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, '呼叫 她丈夫 说:「 你叫 一个 仆人 给我 牵一 匹驴来,我要快快地 去见 神 人,就回来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, '丈夫说:「今日 不是 月朔,也不是 安息日,你 为何 要去 见他呢?」妇人说:「平安无事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, '于 是备 上驴,对 仆人 说:「你快快赶著 走,我若不 吩咐 你,就不要 迟 慢。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, '妇人就 往 迦密 山 去 见 神 人。 神 人 远远地 看见 她,对 仆人 基哈西 说:「看哪, 书念的妇人来了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, ' 你跑去 迎接她,问她 说:你 平安吗?你丈夫 平安吗?孩子 平安吗?」她说:「平安。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, '妇人上了 山,到 神 人那里,就抱住 神人的脚。基哈西 前来 要推开 她,神 人 说:「由 她吧!因为 她心里 愁苦,耶和华 向我 隐瞒,没有 指示 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, '妇人说:「我何尝向 我主 求过 儿子呢?我岂没有 说过,不要 欺哄 我吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, '以利沙吩咐基哈西 说:「你束上 腰,手 拿 我的杖 前去;若 遇见 人,不要 向他问安;人 若 向你问安,也不要 回答;要把我的杖 放 在 孩子 脸上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, '孩子 的母亲 说:「我指著永生 的耶和华,又敢在你面前起誓,我必不 离开 你。」于 是以利沙起身,随著她 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, '基哈西 先 去,把 杖 放 在 孩子 脸上,却没有 声音,也没有 动静。基哈西就迎著 以利沙回来,告诉 他 说:「孩子 还没有 醒过来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, '以利沙 来到,进了屋子,看见 孩子 死了,放 在 自己的床上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, '他就 关上 门,只有自己和孩子 在里面,他便祈祷 耶和华, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, '上床 伏 在 孩子身上, 口 对 口,眼 对 眼,手 对 手;既伏 在孩子身上,孩子 的身体 就渐渐温和了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, '然后他下来,在屋里 来 往 走了一趟,又上去 伏 在孩子身上,孩子 打了 七 个喷嚏, 就睁开  眼睛了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, '以利沙叫 基哈西 说:「你叫 这 书念妇人来」;于 是叫了她 来。以利沙说:「将你儿子 抱起来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, '妇人就进来, 在 以利沙脚前 俯伏 于 地,抱起 她儿子 出去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, '以利沙 又来到 吉甲,那地 正有饥荒。先知 门徒 坐 在他面前,他吩咐仆人 说:「你将大 锅 放在火上,给先知 门徒 熬 汤。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, '有一 个人去 到 田野 掐 菜,遇见 一棵野 瓜籐,就摘了一 兜 野 瓜 回来,切了 搁在 熬汤 的锅中,因为 他们不 知道是什么东西; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, '倒出来 给众人 吃, 吃的时候,都 喊叫 说:「神 人哪,锅 中有致死的毒物!」所以众人不 能 吃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, '以利沙说:「拿 点面 麺来」,就把面 麺撒 在 锅中,说:「倒出来,给众人 吃吧!」锅 中就没 有 毒了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, '有一个人从巴力‧沙利沙 来,带著 初熟 大麦 做的饼 二十 个,并新穗子,装在口袋 里送给神 人。神人说:「把这些给 众人 吃。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, '仆人 说:「这 一点岂可 摆给 一百 人吃呢?」以利沙说:「你只管给 众人 吃吧!因为 耶和华 如此 说,众人必吃了,还剩下。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, '仆人就摆 在众人面前,他们吃了,果然还剩下,正如耶和华 所说的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, '亚兰 王 的元帅 乃缦 在他主人 面前 为 尊 为大,因 耶和华 曾藉 借他 使 亚兰人 得胜;他又是 大能 的勇士,只是长了大痲疯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, '先前亚兰人 成群地 出去,从以色列 国 掳了 一个小 女子,这女子就服事 乃缦 的妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, '她对 主母 说:「巴不得 我主人 去见 撒马利亚 的 先知, 必能治好 他 的大痲疯。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, '乃缦进去,告诉 他主人 说,以色列 国 的 女子 如此 如此 说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, '亚兰 王 说:「你可以去,我也达 信 于  以色列 王。」于 是乃缦 带 银子 十 他连得,金子 六 千舍客勒,衣裳 十 套,就去了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, '且带 信 给 以色列 王,信上说:「 我打发 臣仆 乃缦 去见你, 你 接到 这 信,就要治好他 的大痲疯。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, ' 以色列 王 看了 信 就撕裂 衣服,说:「我岂是 神,能使人死 使人活呢?这人 竟 打发 人来,叫我治好 他 的大痲疯。 你们看一看,这人 何以 寻隙 攻击我呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, ' 神 人 以利沙 听见 以色列 王 撕裂 衣服,就打发 人去见 王,说:「你为什么 撕了 衣服呢?可 使那人到我 这里来,他就知道 以色列 中有 先知了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, '于 是,乃缦 带著车 马 到了 以利沙 的家,站在 门前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, '以利沙 打发 一个使者,对 乃缦说:「你去 在约旦河 中沐浴 七 回,你的肉 就必复原,而得洁净。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, '乃缦 却发怒 走了,说:「 我想 他必定 出来 见我,站著 求告 耶和华─他 神 的名,在 患处 以上摇 手,治好 这大痲疯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, '大马士革 的河 亚罢拿 和法珥法 岂不 比以色列 的一切 水 更好吗?我在那里 沐浴 不 得洁净吗?」于 是气忿忿地 转身 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, '他的仆人 进前来, 对他 说:「我父啊,先知 若吩咐 你 做一件大 事,你岂不 做吗?何况 说 你去沐浴 而得洁净呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, '于 是乃缦下去,照著神 人 的话,在约旦河 里沐浴 七 回;他的肉 复原,好像小 孩子 的肉,他就洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, '乃缦 带著一切 跟随他的人,回 到 神 人那里, 站 在他面前,说:「如今 我知道, 除了 以色列之外,普 天下 没有 神。现在 求 你收点 仆人 的 礼物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, '以利沙说:「我指著 所 事奉 永生 的耶和华起誓,我必不 受。」乃缦再三地求 他,他却不受。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, '乃缦 说:「你若不肯受,请 将两 骡子 驮 的土 赐 给仆人。从今以后,仆人 必不 再 将燔祭 或平安祭 献与 别 神,只 献给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, '惟有一件 事,愿 耶和华 饶恕 你仆人:我主人 进 临门 庙 叩拜的时候,我用 手 搀 他 在临门 庙,我也屈身。我在临门 庙 屈身 的这 事,愿  耶和华 饶恕我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, '以利沙对他 说:「你可以平平安安地 回去!」乃缦就离开  他去了;走了不 远, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, '神 人 以利沙 的仆人 基哈西 心里说:「 我主人 不愿  从这 亚兰人 乃缦 手 里受 他带来 的礼物,我指著永生 的耶和华起誓,我必 跑去 追上他,向他 要 些。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, '于 是基哈西 追赶 乃缦。乃缦 看见 有人追赶,就急忙下 车 迎著他,说:「都平安吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, '说:「都平安。我主人 打发我 来说:『 刚才 有两 个少年人,是先知 门徒,从以法莲 山 地来 见我,请 你赐 他们 一他连得 银子,两 套 衣裳。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, '乃缦 说:「请 受 二他连得」;再三地请受,便将二 他连得 银子 装 在两 个口袋里,又将两 套 衣裳 交 给 两 个仆人;他们就在基哈西前头 抬著走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, '到了 山冈,基哈西从他们手 中接过来,放 在屋里,打发 他们 回去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, '基哈西 进去,站 在 他主人面前。以利沙 问他 说:「基哈西 你从哪里来?」回答说:「仆人 没有 往 哪里 去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, '以利沙对他 说:「那人 下 车 转回 迎你 的时候,我的心 岂没有 去呢?这岂是受 银子、衣裳、买  橄榄园、葡萄园、牛 羊、仆 婢 的时候呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, '因此,乃缦 的大痲疯 必沾染 你 和你的后裔,直到永远。」基哈西从以利沙面前 退出去,就长了大痲疯,像雪那样白。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, '先知 门徒 对 以利沙 说:「看哪,我们 同你 所 住 的地方 过于 窄小, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, '求 你容我们往 约旦河 去,各人 从那里 取 一 根木料 建造 房屋 居住。」他说:「你们去吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, '有一 人说:「求 你与 仆人 同去。」回答说:「我 可以去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, '于 是以利沙与他们 同去。到了 约旦河,就砍伐 树木。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, '有 一 人砍 树的时候, 斧头 掉 在 水里,他就呼叫 说:「哀哉!我主啊,这斧子 是借的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, '神 人 问说:「掉 在哪里了?」他将 那地方 指给以利沙看。以利沙砍了 一根木头,抛 在水里,斧头 就漂上来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, '以利沙说:「拿起来吧!」那人就伸 手 拿起来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, '亚兰 王 与以色列人 争战 ,和 他的臣仆 商议 说:「我要在 某 处某 处 安营。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, '神 人 打发 人去见 以色列 王,说:「你要谨慎,不要从某 处 经过,因为 亚兰人 从那里 下来了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, '以色列 王 差 人去 窥探神 人 所 告诉 所警戒 他去的地方,就防备未受其害,不止 一 两次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, '亚兰 王 因 这 事 心 里惊疑,召了 臣仆 来,对他们 说:「我们这里有 谁 帮助 以色列 王,你们不 指 给我吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, '有一 个臣仆 说:「我主,我王!无人帮助他,只有 以色列 中的 先知 以利沙,将 王在卧 房 所 说的 话 告诉 以色列 王了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, '王说:「你们去 探 他 在哪里,我好打发 人去捉拿他。」有人告诉 王 说:「 他在多坍。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, '王就打发 车 马 和大 军 往那里 去,夜间到了,围困 那城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, '神 人 的仆人 清早 起来 出去,看见 车 马 军兵 围困了 城。仆人 对神人 说:「哀哉!我主啊,我们怎样 行才好呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, '神人说:「不要 惧怕! 与我们 同在的 比 与他们 同在的更多。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, '以利沙 祷告 说:「耶和华啊,求 你开  这少年人 的眼目,使他能看见。」耶和华 开  他的眼目,他就看见 满 山 有火 车 火马 围绕 以利沙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, '敌人下 到以利沙那里,以利沙 祷告 耶和华 说:「求 你 使 这 些人 的眼目昏迷。」耶和华就照以利沙 的话,使他们 的眼目昏迷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, '以利沙 对他们 说:「这不是 那 道,也不是 那 城;你们跟我 去,我必领 你们 到 所 寻找 的人那里。」于 是领 他们 到了撒马利亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, ' 他们进了 撒马利亚,以利沙 祷告说:「耶和华啊,求你开  这些 人的眼目,使他们能看见。」耶和华 开  他们的眼目,他们就看见了,不料,是在撒马利亚 的城中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, '以色列 王 见了 他们,就问 以利沙 说:「我父啊,我可以 击杀他们吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, '回答说:「不可 击杀他们!就是 你用刀 用弓 掳来的, 岂可击杀他们吗(或译:也不可击杀,何况这些人呢)?当在他们面前 设摆 饮 食,使他们吃 喝 回 到 他们的主人那里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, '王就为他们 预备了 许多 食物;他们吃 喝完了,打发 他们回 到 他们主人那里。从此,亚兰 军 不 再 犯 以色列 境了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, ' 此 后,亚兰 王便‧哈达 聚集 他的全 军,上来 围困 撒马利亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, '于 是撒马利亚 被围困,有 饥荒,甚至 一个驴 头 值银 八十舍客勒,二升 鸽子粪 值银 五舍客勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, '一日,以色列 王 在 城 上经过,有一个妇人 向他 呼叫 说:「我主,我王啊!求你帮助。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, '王说:「耶和华 不 帮助你,我从何处 帮助你?是从 禾场,是 从 酒醡呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, '王 问妇人 说:「你有 什么苦处?」她回答说:「这 妇人 对我 说:『将 你的儿子 取来,我们今日 可以吃,明日 可以吃 我的儿子。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, '我们就煮了 我的儿子 吃了。次 日 我对她 说:『要将 你的儿子 取来,我们可以吃。』她却将 她的儿子 藏起来了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, ' 王 听见 妇人 的话,就撕裂 衣服;(王 在 城上 经过)百姓 看见 王贴 身 穿著麻衣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, '王说:「我今日 若 容沙法 的儿子 以利沙 的头 仍 在他项上,愿  神 重重地 降 罚 与我!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, '那时,以利沙 正坐 在家中,长老 也与他 同坐。王打发 一个伺候他 的人去;他 还没有 到,以利沙 对 长老 说:「你们看 这 凶手 之子,打发 人来斩 我的头;你们看著 使者 来到,就关上 门,用门 将他 推出去。在他后头 不是 有他主人 脚步 的响声吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, '正 说话的时候, 使者 来 到,王也到了,说:「 这 灾祸 是从 耶和华那里来的,我何必 再 仰望 耶和华呢?」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, '以利沙 说:「你们要听 耶和华 的话,耶和华 如此 说:明日 约到这时候,在撒马利亚 城门口,一细亚 细面 麺 要卖银一舍客勒,二细亚 大麦 也要卖银一舍客勒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, '有一个 搀扶 王的 军长 对 神 人 说:「即便 耶和华 使天 开 了 窗户,也不能有 这 事。」以利沙说:「 你必亲眼 看见,却不 得吃。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, '在城门 那里 有 四 个长大痲疯 的人,他们彼此 说:「我们 为何 坐 在这里 等 死呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, '我们若 说,进 城去吧!城 里有饥荒,必死 在那里;若 在这里 坐著不动,也必是死。 来吧,我们去投降 亚兰人 的军队,他们若 留我们的活命,就活著;若 杀我们,就死了吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, '黄昏的时候,他们起来 往 亚兰人 的营盘 去;到了 营 边, 不 见一人 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, '因为主 使 亚兰人 的军队 听见 车 马 的声音,是大 军 的声音;他们就彼此 说:「 这必是以色列 王 贿买  赫人 的诸王 和 埃及人 的诸王 来 攻击我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, '所以,在黄昏 的时候他们起来 逃跑,撇下 帐棚、 马、 驴,营盘 照旧,只顾逃 命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, '那些 长大痲疯 的到了 营 边,进了 帐棚,吃了 喝了,且从其中 拿出 金 银 和衣服来,去 收藏了;回来 又进了 一 座帐棚,从其中 拿 出财物来去 收藏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, '那时,他们彼此 说:「我们 所做 的不 好!今 日 是 有好信息 的日子,我们 竟不作声!若等 到 天 亮,罪 必临到我们。 来吧,我们与王 家 报 信去!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, '他们就去 叫 守城 门的,告诉 他们 说:「我们到了 亚兰人 的营, 不 见一人 在那里,也无人 声,只有 拴著 的马 和 驴,帐棚 都照旧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, '守城门的叫了 众守门的人来,他们就进去 与王 家 报信。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, '王 夜间 起来,对 臣仆 说:「 我告诉 你们 亚兰人 向我们 如何 行。他们知道 我们 饥饿,所以离 营,埋伏 在田野,说:『 以色列人出 城的时候,我们就活 捉他们,得以进 城。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, '有一 个臣仆 对王说:「我们不如 用 城里 剩下之 马 中的五匹马(马 和城里 剩下 的 以色列 人 都是一样, 快要灭绝),打发 人去窥探。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, '于 是取了 两 辆车 和马,王 差 人去追寻 亚兰 军,说:「你们去 窥探窥探。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, '他们就追 寻 到 约旦河,看见 满 道 上都 是亚兰人 急 跑时丢弃 的 衣服 器具,使者 就回来 报告 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, '众人 就出去,掳掠 亚兰人 的营盘。于 是 一细亚 细面 麺 卖银一舍客勒,二细亚 大麦 也卖银一舍客勒,正如耶和华 所说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, '王 派 搀扶 他 的 那军长 在 城门口弹压,众人在那里 将他践踏,他就死了,正如 神 人 在王 下来 见他 的时候所 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, ' 神 人曾 对 王 说:「 明日 约到这时候,在撒马利亚 城门口,二细亚 大麦 要卖银一舍客勒,一细亚 细面 麺 也要卖银一舍客勒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, '那军长 对 神 人 说:「即便 耶和华 使天 开 了 窗户,也不能有 这 事。」神人说:「 你必亲眼 看见,却不 得吃。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, '这话果然 应验 在他身上;因为众人 在城门 口将他 践踏,他就死了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, '以利沙 曾 对 所 救活 之子 的那妇人 说:「你 和你的全家 要起身 往 你可住 的地方 去住,因为 耶和华 命 饥荒 降 在 这地 七 年。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, '妇人 就起身,照神 人 的话 带著全家 往非利士 地 去,住了 七 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, ' 七 年 完了,那妇人 从非利士 地 回来,就出去 为自己的房屋 田地 哀告 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, '那时王 正 与 神 人 的仆人 基哈西 说:「请 你将 以利沙 所 行的 一切 大事 告诉 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, ' 基哈西 告诉 王 以利沙如何 使 死人 复活,恰巧 以利沙所 救活、 她儿子 的那妇人 为 自己的房屋 田地 来哀告 王。基哈西 说:「我主 我王,这 就是那妇人,这 是她的儿子,就是 以利沙 所救活的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, '王 问 那妇人,她就把那事告诉 王。于 是王 为她 派 一 个太监,说:「 凡 属这妇人的 都 还给她, 自从 她离开  本地 直到 今日, 她田地 的出产 也都还给她。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, '以利沙 来 到大马士革,亚兰 王便‧哈达 正患病。有人告诉 王 说:「神 人 来 到 这里了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, '王 就吩咐 哈薛 说:「你 带著 礼物 去 见 神 人,托 讬他 求问 耶和华,我这 病 能好不能好?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, '于 是哈薛 用 四十 个骆驼,驮著 大马士革 的各样 美物 为礼物,去 见以利沙。到了他那里,站 在他面前,说:「你儿子 亚兰 王便.哈达 打发我 来见你,他问说:『我这 病 能好不能好?』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, '以利沙 对哈薛 说:「你回去 告诉 他说,这病必 能好;但耶和华 指示我, 他必 要死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, '神人定 睛 看著哈薛,甚至 他惭愧。神 人 就哭了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, '哈薛 说:「我主 为什么 哭?」回答 说:「因为 我知道 你必 苦害 以色列 人,用火 焚烧 他们的保障,用刀 杀死 他们的壮丁,摔死 他们的婴孩,剖开  他们的孕妇。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, '哈薛 说:「 你仆人 算什么,不过是一条狗,焉能 行 这 大 事呢?」以利沙 回答说:「耶和华 指示我,你 必作 亚兰 王。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, '哈薛离开  以利沙,回去 见 他的主人。主人问他 说:「以利沙 对你 说 什么?」回答说:「他告诉 我 你必 能好。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, ' 次日,哈薛拿 被窝 浸 在水中,蒙 住 王的脸,王就死了。于 是哈薛 篡了他 的位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, '以色列 王 亚哈 的儿子 约兰 第五 年,犹大 王 约沙法还在位的时候,约沙法 的儿子 约兰 登基 作了犹大 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, ' 约兰登基 的时候年 三十 二 岁,在耶路撒冷 作王 八 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, '他行 以色列 诸王 所 行 的,与亚哈 家一样;因为 他娶了亚哈 的女儿 为 妻,行 耶和华 眼 中看为恶的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, '耶和华 却因 他仆人 大卫的缘故,仍不 肯 灭绝 犹大,照他所 应许 大卫的话,永远 赐 灯光 与他的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, '约兰年间,以东人 背叛 犹大,脱离他的权 下,自己 立 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, '约兰 率领 所有的 战 车 往撒益 去, 夜间 起来,攻打 围困 他的 以东人 和 车 兵长;犹大兵 就逃跑,各回各家去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, '这样,以东人 背叛 犹大,脱离他的权 下,直到 今 日。 那 时 立拿人 也背叛了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, '约兰 其余 馀 的事,凡 他所 行的, 都写 在 犹大 列王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, '约兰 与 他列祖 同睡,葬 在大卫 城 他列祖的坟地里。他儿子 亚哈谢 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, '以色列 王 亚哈 的儿子 约兰 十 二 年,犹大 王 约兰 的儿子 亚哈谢 登基。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, '他 登基 的时候年 二十 二 岁,在耶路撒冷 作王 一 年。他母亲 名 叫亚她利雅,是以色列 王 暗利 的孙女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, '亚哈谢效法 亚哈 家 行 耶和华 眼 中看为恶 的事,与亚哈 家一样,因为 他是 亚哈 家 的女婿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, '他与 亚哈 的儿子 约兰 同往基列 的拉末 去,与 亚兰 王 哈薛 争战 。亚兰人 打伤了 约兰, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, '约兰 王 回 到耶斯列,医治 在拉末 与 亚兰 王 哈薛 打仗 的时候 所 受 的 伤。犹大 王 约兰 的儿子 亚哈谢 因为 亚哈 的儿子 约兰 病了,就下 到耶斯列 看望 他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, '先知 以利沙 叫了 一 个先知 门徒来,吩咐他 说:「你束上 腰,手 拿 这 瓶 膏油 往基列 的拉末 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, '到了 那里,要寻找 宁示 的孙子、约沙法 的儿子 耶户, 使他从同僚 中 起来,带他 进 严密 的屋子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, '将 瓶 里的膏油 倒 在 他头上,说:『耶和华 如此 说:我膏你 作 以色列 王。』说完了,就开  门 逃跑,不要 迟延。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, '于 是那少年 先知 往基列 的拉末 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, '到了那里,看见 众军 长 都坐著,就说:「将军哪,我有 话 对你说。」耶户 说:「我们众人里,你要对 哪一个说呢?」回答说:「将军哪,我要对你说。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, '耶户就起来,进了 屋子,少年人将膏油 倒 在 他头上,对他 说:「耶和华─以色列的 神 如此 说:『我膏你 作 耶和华 民 以色列 的王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, '你要击杀 你主人 亚哈 的全家,我好在 耶洗别 身上伸 我仆人 众先知 和耶和华 一切 仆人 流血的冤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, '亚哈 全 家 必都灭亡,凡属亚哈 的男丁,无论是困住的、自由的,我必从以色列 中剪除, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, '使 亚哈 的家 像尼八 儿子 耶罗波安 的家,又像亚希雅 儿子 巴沙 的家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, ' 耶洗别 必在耶斯列 田里 被狗 所吃,无人 葬埋。』」说完了,少年人就开  门 逃跑了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, '耶户 出来,回到 他主人 的臣仆那里,有一人问他 说:「平安吗?这 狂妄 的人来 见你 有什么事呢?」回答说:「你们 认得 那人,也知道 他说什么。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, '他们说:「这是假话, 你据实地告诉 我们。」回答说:「他如此 如此 对我 说。他说:『耶和华 如此 说:我膏你 作 以色列 王。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, '他们就急忙 各 将 自己的衣服 铺 在 上层 台阶,使耶户坐在其上;他们吹 角,说:「耶户 作王了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, '这样,宁示 的孙子、约沙法 的儿子 耶户 背叛 约兰。先是约兰 和以色列 众人 因为 亚兰 王 哈薛的缘故, 把守 基列 的拉末; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, '但约兰 王 回 到耶斯列,医治 与 亚兰 王 哈薛 打仗 所 受的 伤。耶户 说:「若 合 你们的意思,就不 容人逃 出 城 往耶斯列 报信 去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, '于 是耶户 坐车 往耶斯列 去,因为 约兰 病卧 在那里。犹大 王 亚哈谢 已经下去 看望 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, '有一个守望的人 站 在 耶斯列 的楼上,看见 耶户 带著一群人 来,就说:「我 看见 一群人。」约兰 说:「 打发 一个骑马的 去迎接他们,问说:平安不平安?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, '骑 马的 就去 迎接耶户,说:「王问 说,平安不平安?」耶户 说:「平安 不平安与你 何干?你转 在 我后头吧!」守望的人 又 说:「使者 到了 他们那里,却不 回来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, '王又 打发 一个骑 马的去。这人到了 他们那里,说:「王问 说,平安不平安?」耶户 说:「平安 不平安与你 何干?你转 在 我后头吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, '守望的人 又 说:「他到了 他们那里,也不 回来;车 赶得 甚 猛,像宁示 的孙子 耶户 的赶法。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, '约兰 吩咐说:「套车!」人就给他套 车。以色列 王 约兰 和犹大 王 亚哈谢 各 坐自己的车 出去 迎接 耶户,在耶斯列人 拿伯 的田 那里遇见他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, ' 约兰 见 耶户 就说:「耶户啊,平安吗?」耶户说:「 你母亲 耶洗别 的淫行 邪术 这样多,焉能 平安呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, '约兰 就转 车 逃跑,对 亚哈谢 说:「亚哈谢啊,反了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, '耶户 开  满了 弓,射中 约兰的脊背,箭 从心窝 穿出,约兰就仆倒 在车上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, '耶户对 他的军长 毕甲 说:「你把他 抛 在耶斯列人 拿伯 的田 间。你当 追想,你 我 一同 坐车 跟随 他父 亚哈的时候,耶和华 对亚哈 所说的 预言, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, '说:『我昨日 看见 拿伯 的血 和 他众子 的血,我必 在这 块田 上报应 你。』这是耶和华 说的,现在 你要照著耶和华 的话,把 他抛 在这田间。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, '犹大 王 亚哈谢 见这光景,就从园 亭 之路 逃跑。耶户 追 赶他,说:「把这人 也 杀 在 车上。」到了靠近 以伯莲 的 姑珥 坡上击伤了他。他逃 到米吉多,就死 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, '他的臣仆 用车将他 的尸首送 到耶路撒冷,葬 在大卫 城 他自己的坟墓里,与 他列祖同葬。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, '亚哈谢 登基 作 犹大王的时候,是在亚哈 的儿子 约兰 第十 一 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, '耶户 到了 耶斯列;耶洗别 听见 就擦 粉、梳 头,从 窗户 里往外观看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, '耶户 进 门的时候,耶洗别说:「杀 主人 的心利啊,平安吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, '耶户抬 头 向 窗户观看,说:「谁 顺从我?」有两 三 个太监 从窗户往外看 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, '耶户说:「把她扔下来!」他们就把她扔下来。她的血 溅 在 墙 上和 马上;于 是把她践踏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, '耶户进去,吃了 喝了,吩咐说:「 你们把 这 被咒诅的妇人 葬埋了,因为 她 是王 的女儿。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, '他们就去 葬埋她,只 寻得 她的头骨 和脚,并手 掌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, '他们回去 告诉 耶户,耶户说:「这正 应验耶和华 藉 借 他仆人 提斯比人 以利亚 所 说 的话,说:『在耶斯列 田间,狗 必吃 耶洗别 的肉; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, '耶洗别 的尸首 必 在 耶斯列 田 间 如同粪土,甚至人 不能 说 这是 耶洗别。』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, '亚哈有 七十 个儿子 在撒马利亚。耶户 写 信 送 到撒马利亚,通知 耶斯列 的首领,就是长老 和 教养 亚哈众子的人,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, '「 你们那里 既有你们主人 的众子 和 车 马、器械、坚固 城, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, '接了 这 信,就可以在你们主人 的众子 中选择 一个贤能 合宜的,使他坐 他父亲 的位,你们也可以为 你们主人 的家 争战 。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, '他们却甚 惧怕,彼此说:「 二 王 在他面前 尚且站立 不住,我们 怎能 站得住呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, ' 家 宰、 邑 宰,和长老,并教养众子的人,打发 人去见 耶户,说:「我们 是你的仆人,凡 你所 吩咐 我们 的都必遵行,我们不 立谁 作王,你看 怎样好 就怎样行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, '耶户又 给他们 写 信 说:「你们 若 归顺我, 听从 我的话,明日 这时候,要将 你们主人 众子 的首级 带 到耶斯列 来 见我。」那时王 的儿子 七十 人 都住在 教养 他们 那城中 的尊贵人家里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, ' 信 一到,他们就把 王 的七十 个 儿子 杀了,将 首级 装 在筐里,送 到 在耶斯列的耶户那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, '有使者 来 告诉 耶户 说:「他们将王 众子 的首级 送来了。」耶户说:「将首级 在城门 口 堆作 两 堆,搁到 明日。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, ' 次日早晨,耶户出来,站著 对 众 民 说:「你们 都是公义的, 我 背叛 我主人,将他杀了; 这些 人却是谁 杀的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, '由此 可知, 耶和华 指著 亚哈 家 所 说 的话 一句没有 落空,因为耶和华 藉 借 他仆人 以利亚 所 说 的话都成就了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, ' 凡 亚哈 家 在耶斯列 所剩下 的人和 他的大臣、密友、祭司,耶户 尽都杀了, 没有 留下一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, '耶户 起身 往 撒马利亚 去。 在路上、牧人剪 羊毛之处, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, ' 遇见 犹大 王 亚哈谢 的弟兄,问他们说:「你们 是谁?」回答说:「我们是 亚哈谢 的弟兄,现在下去 要问 王 和太后 的众子安。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, '耶户吩咐说:「活 捉他们!」跟从的人就活 捉了他们,将他们杀 在 剪羊毛之处 的坑边,共四十 二 人,没有 留下 一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, '耶户从那里 前行,恰遇 利甲 的儿子 约拿达 来迎接他,耶户问他安,对他 说:「 你诚 心 待我像 我诚心 待 你吗?」约拿达 回答说:「是。」耶户说:「若是这样,你向我伸 手」,他就伸 手;耶户拉 他 上 车。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, '耶户说:「你和我 同去,看 我为耶和华 怎样热心」;于 是请他 坐 在车上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, '到了 撒马利亚,就把 撒马利亚 的亚哈 家剩下 的人都 杀了,直到 灭尽,正如耶和华 对 以利亚 所 说 的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, '耶户 招聚 众 民,对他们 说:「亚哈 事奉 巴力 还冷淡,耶户 却 更热心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, '现在 我要 给巴力 献大 祭。应当叫 巴力 的众 先知 和一切 拜巴力的人,并巴力的众 祭司,都到我这里来,不可 缺少 一个;凡 不来的 必不 得活。」耶户 这样行,是用诡计 要 杀尽 拜巴力 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, '耶户 说:「要为巴力 宣告 严肃会!」于 是宣告了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, '耶户 差 人走遍 以色列地;凡 拜 巴力 的人都来齐了,没有 一个 不 来的。他们进了 巴力 庙,巴力 庙 中从前边 直到后边 都满了人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, '耶户吩咐 掌管 礼服 的人说:「拿出 礼服来,给一切 拜 巴力的人穿。」他就拿出 礼服 来给了他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, '耶户 和利甲 的儿子 约拿达 进了 巴力 庙,对拜 巴力 的人说:「你们察看 察看, 在你们 这里 不可 有 耶和华 的仆人,只 可 容留拜巴力 的人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, '耶户和约拿达进去,献 平安祭 和燔祭。耶户 先安派 八十 人 在庙外,吩咐说:「我 将这些 人 交 在 你们手中,若有 一人 脱逃,谁放的 必叫他 偿 命!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, ' 耶户 献 完了 燔祭,就出来吩咐 护卫兵 和众军长说:「你们进去 杀他们,不容 一人 出来!」护卫兵 和军长 就用 刀 杀他们,将尸首抛出去,便到 巴力 庙 的城 去了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, '将 巴力 庙 中的柱像 都拿出来 烧了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, '毁坏了 巴力 柱像,拆毁了 巴力 庙 作为 厕所,直到 今日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, '这样,耶户 在以色列 中灭了 巴力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, '只 是耶户 不 离开  尼八 的儿子 耶罗波安 使 以色列人 陷在罪 里的 那罪,就是 拜伯特利 和 但 的金 牛犊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, '耶和华 对 耶户 说:「因 你办 好 我眼 中看为正的事,照 我的心意 待 亚哈 家,你的子孙 必接续你 坐 以色列 的国位,直到四代。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, '只是耶户 不 尽 心 遵 守 耶和华─以色列 神 的律法,不 离开  耶罗波安 使 以色列人 陷在罪 里的 那罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, '在那些 日子,耶和华 才 割裂 以色列国,使哈薛 攻击 以色列 的境界, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, '乃是 约旦河 东、 基列 全 地,从靠近 亚嫩 谷 边的 亚罗珥起,就是基列 和巴珊 的迦得人、流便人、玛拿西人之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, '耶户 其余 馀 的事,凡 他所 行 的和 他的勇力 都写 在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, '耶户 与 他列祖 同睡,葬 在撒马利亚;他儿子 约哈斯 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, ' 耶户 在撒马利亚 作 以色列 王 二十 八 年。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, '亚哈谢 的母亲 亚她利雅 见 她儿子 死了,就起来 剿灭 王 室。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, '但约兰 王 的女儿,亚哈谢 的妹子 约示巴,将 亚哈谢 的儿子 约阿施 从那被杀的 王 子 中 偷出来,把他 和 他的乳母 都藏 在卧 房里,躲避 亚她利雅,免得 被杀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, '约阿施 和他的乳母 藏在 耶和华 的殿里 六 年;亚她利雅 篡了 国位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, '第七 年,耶何耶大 打发人 叫迦利人(或译:亲兵) 和护卫兵的 众百夫长来,领 他们 进了 耶和华 的殿,与他们 立 约,使他们 在耶和华 殿 里起誓,又将 王 的儿子 指给他们 看, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, '吩咐他们 说:「你们当这样 行:凡安息日 进班的 三分之一 要看 守 王 宫, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, '三分之一 要在苏珥 门,三分之一 要在护卫兵 院的后 门。这样把 守 王宫,拦阻闲 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, '你们 安息日 所有 出班的 三分之二要在 耶和华 的殿 里护卫 王; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, '各人 手 拿兵器,四围 护卫 王。凡擅入 你们班次 的必当治死,王 出 入的时候,你们当 跟随他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, '众百夫长 就照著祭司 耶何耶大 一切 所 吩咐的 去行,各 带 所管安息日 进班 出班 的人 来 见 祭司 耶何耶大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, '祭司 便将 耶和华 殿里 所 藏大卫 王的 枪 和 盾牌 交 给百 夫长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, '护卫兵 手中 各 拿兵器,在坛 和殿那里,从殿 右 直到 殿 左,站 在 王子 的四围。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, '祭司领 王 子 出来,给他 戴上 冠冕,将 律法书交给他,膏 他 作王;众人就拍 掌 说:「愿 王 万岁!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, '亚她利雅 听见 护卫兵 和民 的声音,就到 民那里,进耶和华 的殿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, '看见 王 照例 站 在 柱旁,百夫长 和吹号的人 侍立在 王左右,国中 的众 民 欢乐 吹 号;亚她利雅 就撕裂 衣服,喊叫说:「反了!反了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, '祭司 耶何耶大 吩咐 管辖 军兵 的百夫长 说:「将她 赶出 班 外,凡跟 随她 的必用刀 杀死!」因为 祭司 说「不可 在耶和华 殿里 杀她」, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, '众兵就闪 开  让她去;她从马 路 上 王 宫 去,便在那里 被杀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, '耶何耶大使 王 和 民 与 耶和华 立 约,作 耶和华 的民;又使 王 与 民立约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, '于 是国 民 都 到 巴力 庙,拆毁了庙,打碎 坛 和 像,又在坛 前 将 巴力 的祭司 玛坦 杀了。祭司 耶何耶大派 官 看守 耶和华 的殿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, '又率领 百夫长 和 迦利人(或译:亲兵)与 护卫兵,以及 国中 的众 民,请 王 从耶和华 殿 下来,由护卫兵 的门 进入 王 宫,他就坐了 王 位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, '国 民 都 欢乐,合城 都安静。众人已将 亚她利雅 在王 宫 那里用刀 杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, '约阿施 登基 的时候年 方七 岁。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, '耶户 第七 年,约阿施 登基,在耶路撒冷 作王 四十 年。他母亲 名 叫西比亚,是别是巴人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, '约阿施在 祭司 耶何耶大 教训他 的时候,就行 耶和华 眼中 看为正的事; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, '只是 邱坛 还没有 废去,百姓 仍在那里 献祭 烧香。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, '约阿施 对 众祭司 说:「凡 奉到 耶和华 殿 分别为圣 之物所 值通用 的银子,或各人 当纳 的身 价,或乐意 奉 到 耶和华 殿的 银子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, '你们 当从 所认识 的人 收了来, 修理 殿 的一切 破坏之处。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, '无奈到了 约阿施 王 二十 三 年,祭司 仍未 修理 殿 的破坏之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, '所以约阿施 王 召了 大祭司 耶何耶大 和众祭司来,对他们 说:「你们怎么 不 修理 殿 的破坏之处呢?从今以后,你们不要 从 所认识 的人再收 银子,要 将所收的交出来,修理殿 的破坏之处。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, '众祭司 答应 不再 收 百姓 的银子,也不 修理 殿 的破坏之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, '祭司 耶何耶大 取了 一个 柜子,在柜盖 上钻了 一个窟窿,放 于 坛 旁,在 进 耶和华 殿 的右边;守 门 的祭司 将 奉到 耶和华 殿 的一切 银子 投 在柜里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, ' 他们见 柜 里的银子 多了,便叫王 的书记 和大 祭司 上来,将 耶和华 殿 里的银子 数算 包起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, '把 所平 的银子 交 给 督 工的,就是耶和华 殿 里办 事的人;他们把银子转交 修理 耶和华 殿 的木 匠 和工人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, '并瓦匠、石 匠,又买  木料 和凿成的 石头,修理 耶和华 殿 的破坏之处,以及修理 殿 的各样 使用。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, '但 那奉到 耶和华 殿的 银子,没有 用以做 耶和华 殿 里的银 杯、蜡剪、碗、号,和别样的 金 银 器皿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, '乃 将那银子交 给督 工 的人修理 耶和华 的殿; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, '且将 银子 交 给 办事的人 转交 做 工的人,不 与 他们 算账,因为 他们 办事 诚实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, '惟有赎愆祭、赎罪祭 的银子 没有 奉到 耶和华 的殿,都归 祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, '那时,亚兰 王 哈薛 上来 攻打 迦特,攻取了, 就定 意 上来 攻打 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, '犹大 王 约阿施 将 他列祖 犹大 王 约沙法、约兰、亚哈谢 所 分别为圣 的物 和 自己所分别为圣的物,并 耶和华 殿 与王 宫 府库 里 所有的 金子 都送 给亚兰 王 哈薛;哈薛就不上 耶路撒冷 来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, '约阿施 其余 馀 的事,凡 他所 行的 都写 在 犹大 列王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, '约阿施 的臣仆 起来 背叛,在下 悉拉 的米罗 宫 那里将他 杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, '杀 他的那臣仆 就是示米押 的儿子 约撒甲 和朔默 的儿子 约萨拔。 众人将他 葬 在 大卫 城 他列祖的坟地里。他儿子 亚玛谢 接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, '犹大 王 亚哈谢 的儿子 约阿施 二十 三 年,耶户 的儿子 约哈斯 在撒马利亚 登基 作 以色列 王十 七 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, '约哈斯行 耶和华 眼 中看为恶的事,效法 尼八 的儿子 耶罗波安 使 以色列 人陷在罪 里的 那罪,总不 离开 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, '于 是,耶和华 的怒气 向以色列 人发作,将他们屡次 交 在亚兰 王 哈薛 和他 儿子便.哈达 的手里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, '约哈斯 恳求 耶和华,耶和华 就应允 他,因为 见 以色列 人所受 亚兰 王 的欺压。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, '耶和华 赐 给以色列 人一位拯救者,使他们脱离 亚兰人 的手;于 是以色列 人 仍旧 安 居 在家里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, '然而 他们不 离开  耶罗波安 家 使 以色列人 陷在罪里 的 那罪,仍然去行,并且 在撒马利亚 留下 亚舍拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, ' 亚兰 王 灭绝 约哈斯的民, 践踏 他们如禾场上的尘沙,只 给约哈斯 留下 五十 马兵,十 辆战 车,一万 步兵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, '约哈斯 其余 馀 的事,凡 他所 行 的和他的勇力都 写 在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, '约哈斯 与 他列祖 同睡,葬 在撒马利亚。他儿子 约阿施 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, '犹大 王 约阿施 三十 七 年,约哈斯 的儿子 约阿施 在撒马利亚 登基 作 以色列 王十 六 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, '他行 耶和华 眼 中看为恶的事,不 离开  尼八 的儿子 耶罗波安 使 以色列 人陷在罪里 的 一切 罪,仍然去行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, '约阿施 其余 馀 的事,凡 他所 行 的和他与 犹大 王 亚玛谢 争战  的 勇力,都 写 在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, '约阿施 与 他列祖 同睡,耶罗波安 坐了 他的位。约阿施 与 以色列 诸王 一同葬 在撒马利亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, '以利沙 得了 必死 的 病,以色列 王 约阿施 下来 看他,伏在 他脸 上哭泣,说:「我父啊!我父啊!以色列 的战 车 马兵啊!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, '以利沙 对他 说:「你取 弓 箭来。」王就取了 弓 箭 来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, '又对以色列 王 说:「你用 手 拿 弓。」王就用 手拿弓。以利沙 按 手 在 王 的手上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, '说:「你开  朝东 的窗户。」他就开 了。以利沙 说:「射箭吧!」他就射箭。以利沙说:「这是耶和华的 得胜 箭,就是战 胜 亚兰人 的箭;因为你必在亚弗 攻打 亚兰人,直到 灭尽他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, '以利沙又说:「取 几枝箭来。」他就取了来。以利沙说:「打 地吧!他打了 三次,便止住了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, '神 人 向他 发怒,说:「应当击打 五 六 次,就能 攻打 亚兰人 直到 灭尽;现在 只能打败 亚兰人 三次。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, '以利沙 死了,人将他葬埋。到了 新年,有一群 摩押人 犯 境, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, '有人 正 葬 死人,忽然 看见 一群人,就把 死人 抛 在以利沙 的坟墓里, 一 碰著 以利沙 的骸骨,死人就复活,站起来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, '约哈斯年间,亚兰 王 哈薛屡次 欺压 以色列人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, '耶和华 却因 与 亚伯拉罕、以撒、雅各 所立的约,仍施恩 给 以色列人,怜恤他们,眷顾 他们,不 肯 灭尽他们,尚 未 赶逐他们 离开  自己面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, '亚兰 王 哈薛 死了,他儿子便‧哈达 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, '从前哈薛和约阿施 的父亲 约哈斯 争战 , 攻取了 些城邑, 现在约哈斯 的儿子 约阿施 三 次 打败 哈薛 的儿子便‧哈达,就收 回了 以色列 的城邑。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, '以色列 王 约哈斯 的儿子 约阿施 第二 年,犹大 王 约阿施 的儿子 亚玛谢 登基。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, ' 他登基 的时候年 二十 五 岁,在耶路撒冷 作王 二十 九 年。他母亲 名 叫约耶但,是 耶路撒冷人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, '亚玛谢行 耶和华 眼 中看为正的事,但 不 如他祖 大卫,乃效法 他父 约阿施 一切 所 行的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, '只是 邱坛 还没有 废去,百姓 仍在那里 献祭 烧香。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, '国 一 坚定,就把 杀 他父 王 的臣仆 杀了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, '却没有 治死 杀 王之人的儿子,是照 摩西 律法 书 上耶和华 所 吩咐 的说:「不可 因 子 杀 父,也不可 因 父 杀 子, 各人 要为本身的罪 而死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, '亚玛谢 在盐 谷 杀了 以东人 一万,又攻 取了 西拉,改 名 叫 约帖,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, '那时,亚玛谢 差遣 使者 去见 耶户 的孙子 约哈斯 的儿子 以色列 王 约阿施,说:「你来,我们二人相见于 战 场。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, '以色列 王 约阿施 差遣 使者去见 犹大 王 亚玛谢,说:「黎巴嫩 的 蒺藜 差遣 使者去见 黎巴嫩 的 香柏树,说:将 你的女儿 给 我儿子 为妻。 后来黎巴嫩 有一个野 兽 经过,把 蒺藜 践踏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, '你打败了 以东人 就心 高气傲,你以此为荣耀,在家 里安居就罢了,为何 要惹 祸,使自己 和犹大 国一同 败亡呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, '亚玛谢 却不肯 听这话。于 是以色列 王 约阿施 上来,在犹大 的伯.示麦 与犹大 王 亚玛谢 相见于 战 场。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, '犹大 人败 在以色列 人面前,各自 逃 回家里去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, '以色列 王 约阿施在伯.示麦 擒住 亚哈谢 的孙子、约阿施 的儿子 犹大 王 亚玛谢,就来到 耶路撒冷,拆毁 耶路撒冷 的城墙,从以法莲 门 直到 角 门 共四 百 肘, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, '又将 耶和华 殿 里与王 宫 府库 里 所有的 金 银 和 器皿 都 拿了去,并 带人 去为质,就回 撒马利亚去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, '约阿施 其余 馀 所 行 的事 和他的勇力,并与 犹大 王 亚玛谢 争战  的事,都 写 在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, '约阿施 与 他列祖 同睡,葬 在撒马利亚, 以色列 诸王的坟地里。他儿子 耶罗波安 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, '以色列 王 约哈斯 的儿子 约阿施 死 后,犹大 王 约阿施 的儿子 亚玛谢 又活了 十 五 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, '亚玛谢 其余 馀 的事都 写 在 犹大 列王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, '耶路撒冷 有人背叛亚玛谢,他就逃 到拉吉;叛党却打发 人到拉吉 将他杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, '人就用 马 将他 的尸首驮 到耶路撒冷,葬 在大卫 城 他列祖的坟地里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, '犹大 众 民 立 亚玛谢 的儿子 亚撒利雅(又名乌西雅)接续 他父 作王,那时他 年 十六 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, '亚玛谢 与 他列祖 同睡 之后,亚撒利雅 收回 以拉他 仍归犹大,又重新修理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, '犹大 王 约阿施 的儿子 亚玛谢 十 五 年,以色列 王 约阿施 的儿子 耶罗波安 在撒马利亚 登基,作王四十 一 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, '他行 耶和华 眼 中看为恶的事,不 离开  尼八 的儿子 耶罗波安 使 以色列 人陷在罪里 的 一切 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, '他 收回 以色列 边界之地,从哈马 口 直到 亚拉巴 海,正如耶和华─以色列的 神 藉 借 他仆人 迦特希弗人 亚米太 的 儿子 先知 约拿 所 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, '因为 耶和华 看见 以色列 人甚是 艰苦,无论困住的、自由的 都没有了,也无人 帮助 以色列人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, '耶和华 并没有 说 要将 以色列 的名 从天 下 涂抹,乃藉 借 约阿施 的儿子 耶罗波安 拯救他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, '耶罗波安 其余 馀 的事,凡 他所 行 的和他的勇力,他怎样 争战 ,怎样 收回 大马士革 和 先前属犹大 的哈马 归以色列,都 写 在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, '耶罗波安 与 他列祖 以色列 诸王 同睡。他儿子 撒迦利雅 接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, '以色列 王 耶罗波安 二十 七 年,犹大 王 亚玛谢 的儿子 亚撒利雅 登基, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, ' 他登基 的时候年 十 六 岁,在耶路撒冷 作王 五十 二 年。他母亲 名 叫耶可利雅,是耶路撒冷人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, '亚撒利雅行 耶和华 眼 中看为正的事,效法他父亲 亚玛谢 一切 所 行的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, '只是 邱坛 还没有 废去,百姓 仍在那里 献祭 烧香。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, '耶和华 降灾 与 王,使他 长大痲疯,直到 死 日,他就住在 别 的宫里。他 的儿子 约坦 管理 家事,治理 国 民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, '亚撒利雅 其余 馀 的事,凡 他所 行的都 写 在 犹大 列王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, '亚撒利雅 与 他列祖 同睡,葬 在大卫 城 他列祖的坟地里。他儿子 约坦 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, '犹大 王 亚撒利雅 三十 八 年,耶罗波安 的儿子 撒迦利雅 在撒马利亚 作 以色列 王 六个月。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, '他行 耶和华 眼 中看为恶的事,效法他列祖 所 行的,不 离开  尼八 的儿子 耶罗波安 使 以色列 人陷在罪里 的 那罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, '雅比 的儿子 沙龙 背叛 他,在百姓 面前 击杀他,篡了他 的位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, '撒迦利雅 其余 馀 的事 都写 在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, '这 是从前 耶和华 应许 耶户 说:「你的子孙 必坐 以色列 的国位 直到四代。」这话 果然 应验了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, '犹大 王 乌西雅(就是亚撒利雅)三十 九 年,雅比 的儿子 沙龙 登基 在撒马利亚 作王 一个月。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, '迦底 的儿子 米拿现 从得撒 上 撒马利亚,杀了 雅比 的儿子 沙龙, 篡了他 的位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, '沙龙 其余 馀 的事 和他 背叛 的情形 都写 在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, '那时 米拿现 从得撒 起攻打 提斐萨 和 其四境,击杀 城中 一切的人,剖开  其中所有的 孕妇,都因 他们没有 给他开 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, '犹大 王 亚撒利雅 三十 九 年,迦底 的儿子 米拿现 登基,在撒马利亚 作 以色列 王十 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, '他行 耶和华 眼 中看为恶的事,终身 不 离开  尼八 的儿子 耶罗波安 使 以色列人 陷在罪 里的 那罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, '亚述 王 普勒 来 攻击 以色列 国,米拿现 给他 一千 他连得 银子,请普勒帮助 他 坚定 国位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, '米拿现 向 以色列 一切 大 富户 索要 银子,使他们各 出五十 舍客勒,就给了 亚述 王。于 是亚述 王 回去,不 在国 中停留。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, '米拿 现其余 馀 的事,凡 他所 行的都 写 在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, '米拿现 与 他列祖 同睡。他儿子 比加辖 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, '犹大 王 亚撒利雅 五十 年,米拿现 的儿子 比加辖 在撒马利亚 登基 作 以色列 王二年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, '他行 耶和华 眼 中看为恶的事,不 离开  尼八 的儿子 耶罗波安 使 以色列人 陷在罪里 的 那罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, '比加辖的将军、利玛利 的儿子 比加 背叛 他,在撒马利亚 王宫 里的卫所 杀了他。 亚珥歌伯 和 亚利耶 并基列 的五十 人 帮助比加;比加击杀他,篡了他 的位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, '比加辖 其余 馀 的事,凡 他所 行的都 写 在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, '犹大 王 亚撒利雅 五十 二 年,利玛利 的儿子 比加 在撒马利亚 登基 作 以色列 王二十 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, '他行 耶和华 眼 中看为恶的事,不 离开  尼八 的儿子 耶罗波安 使 以色列人 陷在罪 里的 那罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, '以色列 王 比加 年间,亚述 王提革拉.毘列色 来 夺了 以云、亚伯.伯.玛迦、 亚挪、 基低斯、 夏琐、 基列、 加利利,和拿弗他利 全 地,将这些地方的居民都掳 到亚述去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, '乌西雅 的儿子 约坦 二十 年,以拉 的儿子 何细亚 背叛 利玛利 的儿子 比加,击 杀他,篡了他 的位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, '比加 其余 馀 的事,凡 他所 行的都 写 在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, '以色列 王 利玛利 的儿子 比加 第二 年,犹大 王 乌西雅 的儿子 约坦 登基。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, ' 他登基 的时候年 二十 五 岁,在耶路撒冷 作王 十 六 年。他母亲 名 叫耶路沙,是撒督 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, '约坦行 耶和华 眼 中看为正的事,效法 他父亲 乌西雅 一切 所 行的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, '只是 邱坛 还没有 废去,百姓 仍 在那里 献祭 烧香。约坦 建立 耶和华 殿 的上 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, '约坦 其余 馀 的事,凡他所 行的都 写 在 犹大 列王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, '在那些 日子,耶和华 才 使 亚兰 王 利汛 和 利玛利 的儿子 比加 去攻击犹大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, '约坦 与 他列祖 同睡,葬 在他祖 大卫 城 他列祖的坟地里。他儿子 亚哈斯 接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, '利玛利 的儿子 比加 十 七 年,犹大 王 约坦 的儿子 亚哈斯 登基。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, '他 登基 的时候年 二十 岁,在耶路撒冷 作王 十 六 年;不 像他祖 大卫 行 耶和华─他 神 眼中 看为正的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, '却效法 以色列 诸王 所行的,又 照著耶和华 从以色列 人 面前 赶出 的 外邦人 所行可憎的事,使 他的儿子 经 火, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, '并在邱坛上、 山冈上、各 青翠 树 下 献祭 烧香。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, ' 亚兰 王 利汛 和以色列 王 利玛利 的儿子 比加 上来 攻打 耶路撒冷,围困 亚哈斯,却不 能 胜他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, '当 时 亚兰 王 利汛 收回 以拉他 归与亚兰,将 犹大人 从以拉他 赶出去。亚兰人(有译以东人的)就来到 以拉他,住 在那里,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, '亚哈斯 差遣 使者 去见 亚述 王提革拉.毘列色,说:「我 是你的仆人、你的儿子。现在亚兰 王 和以色列 王 攻击 我,求你来 救我 脱离他们的手。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, '亚哈斯 将 耶和华 殿里 和王 宫 府库里所有的 金 银 都送给 亚述 王 为礼物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, '亚述 王 应允了 他, 就上去 攻打 大马士革,将城攻取,杀了 利汛,把居民掳 到吉珥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, '亚哈斯 王 上 大马士革 去迎接 亚述 王提革拉.毘列色, 在大马士革 看见 一座坛, 就照坛的 规模样式 作法画 划了 图样,送 到 祭司 乌利亚那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, '祭司 乌利亚 照著 亚哈斯 王 从大马士革 送来 的图样,在亚哈斯 王 没有 从大马士革 回来之先, 建筑 一座坛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, '王 从大马士革 回来 看见 坛, 就近 前来,在 坛上献祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, '烧 燔祭、 素祭、浇 奠祭,将 平安祭 牲的 血 洒 在 坛上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, '又 将 耶和华 面前 的 铜 坛 从 耶和华 殿 和新坛 的中间 搬 到 新坛 的北 边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, '亚哈斯 王 吩咐 祭司 乌利亚 说:「 早晨 的燔祭、 晚上的 素祭, 王的 燔祭、 素祭,国内 众 民 的燔祭、素祭、奠祭 都要烧 在 大 坛上。 燔祭牲 和平安祭牲的 血 也要洒 在这坛上,只是铜 坛 我 要用以 求问耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, '祭司 乌利亚 就照著 亚哈斯 王 所 吩咐的 行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, '亚哈斯 王 打掉 盆座 四面镶著的心子,把 盆 从座上 挪下来,又将 铜海 从 驮海的 铜 牛 上搬下来,放 在 铺石 地; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, '又因 亚述 王的缘故,将 耶和华 殿 为安息日 所 盖的 廊子 和 王 从外 入 殿的廊子挪移,围绕耶和华 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, '亚哈斯 其余 馀 所 行的 事都 写 在 犹大 列王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, '亚哈斯 与 他列祖 同睡,葬 在大卫 城 他列祖的坟地里。他儿子 希西家 接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, '犹大 王 亚哈斯 十 二 年,以拉 的儿子 何细亚 在撒马利亚 登基 作 以色列 王九 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, '他行 耶和华 眼中 看为恶的事,只是 不 像在 他以前 的 以色列 诸王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, '亚述 王 撒缦以色 上来 攻击何细亚,何细亚 就 服事 他,给他 进 贡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, '何细亚 背叛, 差 人 去见 埃及 王 梭,不 照 往年 所行的与亚述 王 进 贡。亚述 王 知道了,就把他锁禁,囚 在监 里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, '亚述 王 上来 攻击以色列遍 地,上到 撒马利亚,围困 三 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, '何细亚 第九 年 亚述 王 攻取了 撒马利亚,将 以色列人 掳 到亚述,把他们 安置 在哈腊 与歌散 的哈博 河边,并米底亚人 的城邑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, '这是 因 以色列 人 得罪 那领 他们 出埃及 地、脱离 埃及 王 法老 手 的耶和华─他们的 神,去敬畏 别 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, '随从 耶和华 在他们 面前 所 赶出 外邦人 的风俗 和以色列 诸王 所 立的条规。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, '以色列 人 暗中 行不 正 的 事,违背 耶和华─他们的 神,在他们所有的 城邑,从瞭 了望 楼 直到 坚固 城,建筑 邱坛; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, '在 各 高 冈上、各 青翠 树 下 立 柱像 和木偶; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, '在 邱坛 上烧香,效法耶和华 在他们面前 赶出 的 外邦人所行的,又行 恶 事 惹动 耶和华的怒气; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, '且事奉 偶像,就是 耶和华 警戒 他们 不可 行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, '但耶和华 藉 借 众 先知、 先见 劝戒 以色列人 和犹大人 说:「当离开  你们的恶 行,谨守 我的诫命 律例,遵行我 吩咐 你们列祖,并藉 借 我仆人 众先知 所 传 给你们的 律法。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, '他们却不 听从,竟硬著 颈项,效法 他们列祖, 不 信服 耶和华─他们的 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, '厌弃 他的律例 和 他与 他们列祖 所 立 的约,并 劝戒 他们 的 话,随 从 虚无的神,自己成为虚妄,效法 周围 的 外邦人,就是 耶和华 嘱咐 他们 不可 效法的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, '离弃 耶和华─他们 神 的一切 诫命,为自己 铸了 两个 牛犊 的像,立了 亚舍拉,敬拜 天上的 万 象,事奉 巴力, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, '又使 他们的儿 女 经 火,用 占卜,行法术 卖了自己,行 耶和华 眼 中看为恶的事,惹动他的怒气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, '所以耶和华 向以色列人 大大 发怒,从 自己面前 赶出他们,只 剩下 犹大 一个支派。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, '犹大人 也 不 遵守 耶和华─他们 神 的诫命,随从 以色列人 所 立 的条规。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, '耶和华 就厌弃 以色列 全 族,使他们受苦,把他们交 在抢夺 他们的人手中,以致 赶出他们 离开 自己面前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, ' 将以色列 国从 大卫 家 夺回;他们就立 尼八 的儿子 耶罗波安 作王。耶罗波安 引诱 以色列人 不随从 耶和华,陷在 大 罪里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, '以色列 人 犯 耶罗波安 所 犯 的一切 罪,总不 离开 , ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, '以致 耶和华 从 自己面前 赶出 他们,正如 藉 借 他仆人 众 先知 所说的。这样,以色列人 从 本地 被掳 到亚述,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, '亚述 王 从巴比伦、古他、亚瓦、哈马,和西法瓦音 迁移人来,安置 在撒马利亚 的城邑,代替 以色列 人;他们就得了 撒马利亚,住 在其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, '他们才 住 那里的时候,不 敬畏 耶和华,所以耶和华 叫 狮子 进入他们中间, 咬死了 些人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, '有人告诉 亚述 王 说:「你所 迁移 安置 在撒马利亚 各城 的那些民,不 知道 那地 之神 的规矩,所以那神 叫 狮子 进入他们中间, 咬死 他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, '亚述 王 就吩咐 说:「叫 所 掳来的 祭司 回去 一个,使他住 在那里,将 那地 之神 的规矩 指教那些民。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, '于 是 有一个 从撒马利亚 掳去的 祭司 回来,住 在伯特利, 指教 他们 怎样 敬畏 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, '然而,各族 之人 在所 住的 城 里各为自己 制造 神像,安置 在撒马利亚人 所 造 有邱坛 的殿中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, '巴比伦 人 造疏割‧比讷像;古他 人 造 匿甲像;哈马 人 造 亚示玛像; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, '亚瓦 人造 匿哈 和 他珥他像;西法瓦音 人用火 焚烧 儿女,献给西法瓦音 的神 亚得米勒 和亚拿米勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, ' 他们惧怕 耶和华,也从他们中间 立 邱坛 的祭司,为他们 在有邱坛 的殿中 献祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, '他们又 惧怕 耶和华,又 事奉 自己的神,从何邦 迁移,就随 何邦 的风俗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, '他们 直到 如 今 仍照先前的 风俗 去行,不 专心敬畏 耶和华,不 全守 自己的规矩、典章,也不遵守耶和华 吩咐 雅各 后裔 的 律法、诫命。〈雅各,就是 从前耶和华起 名 叫以色列的。〉 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, '耶和华 曾与他们 立 约,嘱咐他们 说:「不可 敬畏 别 神,不可 跪拜 事奉他,也不可 向他 献祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, '但 那 用大 能 和伸出来的 膀臂 领你们 出 埃及 地 的耶和华,你们当敬畏,跪拜,向他 献祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, '他给你们 写 的 律例、 典章、律法、诫命,你们应当永远 谨守 遵行,不可 敬畏 别 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, '我─耶和华与你们 所 立的 约 你们不可 忘记,也不可 敬畏 别 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, '但 要敬畏 耶和华─你们的 神,他 必救 你们 脱离一切 仇敌的 手。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, '他们 却不 听从,仍 照先前的 风俗 去行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, '如此这些 民 又 惧怕 耶和华,又 事奉 他们的偶像。他们子 子孙 孙 也都 照样 行,效法 他们的祖宗,直到 今 日。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, ' 以色列 王 以拉 的儿子 何细亚 第三 年,犹大 王 亚哈斯 的儿子 希西家 登基。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, ' 他登基 的时候年 二十 五 岁,在耶路撒冷 作王 二十 九 年。他母亲 名叫 亚比,是撒迦利雅 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, '希西家行 耶和华 眼中 看为正的事,效法他祖 大卫 一切 所 行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, '他 废去 邱坛,毁坏 柱像,砍下 木偶,打碎 摩西 所 造的 铜 蛇,因为 到 那 时 以色列 人 仍 向铜蛇 烧香。希西家叫 铜蛇 为铜块(或译:人称铜蛇为铜像)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, '希西家倚靠 耶和华─以色列的 神, 在 他前 后 的犹大 列 王 中没 有 一个及他的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, '因为他专靠 耶和华,总不 离开 ,谨守 耶和华 所 吩咐 摩西 的诫命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, '耶和华 与他 同在,他无论 往何处 去 尽都亨通。他背叛、不肯 事奉 亚述 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, '希西家 攻击 非利士人,直到 迦萨,并 迦萨的四境,从瞭 了望 楼 到 坚固 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, ' 希西家 王 第四 年,就是 以色列 王 以拉 的儿子 何细亚 第七 年,亚述 王 撒缦以色 上来 围困 撒马利亚; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, '过了 三 年 就攻取了城。希西家 第六 年, 以色列 王 何细亚 第九 年,撒马利亚 被攻取了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, '亚述 王 将 以色列 人掳 到亚述,把他们安置 在哈腊 与歌散 的哈博 河边,并米底亚 人的城邑; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, '都因 他们不 听从 耶和华─他们 神 的话,违背 他的约, 就是 耶和华 仆人 摩西 吩咐他们所 当守的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, '希西家 王 十 四 年,亚述 王 西拿基立 上来 攻击 犹大 的一切 坚固 城,将城攻取。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, '犹大 王 希西家 差 人往拉吉 去见 亚述 王,说:「我有罪了,求你离开  我; 凡 你罚 我的,我必承当。」于 是亚述 王 罚 犹大 王 希西家 银子 三 百 他连得,金子 三十 他连得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, '希西家 就把 耶和华 殿 里和王 宫 府库 里所有的 银子 都给了他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, '那 时,犹大 王 希西家 将 耶和华 殿 门 上的金子和 他自己 包 在柱上的 金子 都刮下来,给了 亚述 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, '亚述 王 从 拉吉 差遣 他珥探、 拉伯撒利,和 拉伯沙基 率领大 军 往 耶路撒冷,到 希西家 王那里去。他们上 到 耶路撒冷,就站 在上 池 的水沟旁,在漂布 地 的 大路上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, '他们呼叫 王的时候,就有希勒家 的儿子 家 宰 以利亚敬,并书记 舍伯那 和亚萨 的儿子 史官 约亚,出来 见他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, '拉伯沙基 说:「你们去 告诉 希西家 说,亚述 大 王 如此说:『你所 倚靠的 有什么 可仗赖 的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, '你说 有打仗 的计谋 和能力,我看不过 是虚 话。你到底 倚靠 谁 才 背叛 我呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, ' 看哪,你所倚靠的 埃及是 那 压伤的 苇 杖;人 若靠 这杖,就必刺 透 他的手。埃及 王 法老 向一切 倚靠 他 的人也是这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, '你们若 对我 说:我们倚靠 耶和华─我们的 神,希西家 岂不是将 神 的 邱坛 和 祭坛 废去,且对犹大 和耶路撒冷 的人说:你们当在耶路撒冷 这 坛 前 敬拜吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, '现在 你把当头 给 我主 亚述 王,我给 你 二千 匹马,看 你 这一面骑 马 的人够不够。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, '若不然,怎能 打败 我主 臣仆 中最小的 军长呢?你竟 倚靠 埃及 的战 车 马兵吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, '现在 我上来 攻击 毁灭 这 地,岂没有 耶和华的意思吗?耶和华 吩咐我 说:你上去 攻击 毁灭 这 地吧!』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, '希勒家 的儿子 以利亚敬 和舍伯那,并约亚,对 拉伯沙基 说:「求 你用亚兰言语 和 仆人 说话,因为 我们 懂得;不要 用犹大言语 和我们 说话,达到 城上 百姓 的耳中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, '拉伯沙基 说:「我主 差遣我来,岂是单对 你 和你的主 说 这些 话吗?不 也是对 这些坐 在 城上、要与你们 一同吃 自己粪、喝 自己尿 的人说吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, '于 是拉伯沙基 站著,用犹大言语 大 声 喊著 说:「你们当听 亚述 大 王 的话! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, '王 如此 说:『你们不要 被希西家 欺哄了;因 他不 能 救 你们 脱离我的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, '也不要 听希西家 使你们 倚靠 耶和华,说 耶和华 必要 拯救我们, 这 城 必不 交 在亚述 王 的手中。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, '不要 听 希西家的话!因 亚述 王 如此 说:『你们要与我 和好,出来 投降我,各人 就可以吃 自己葡萄树 和 无花果树的果子, 喝 自己井 里的水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, '等 我来 领 你们 到 一个地方 与你们本地一样,就是有五谷 和新酒 之地,有粮食 和葡萄园 之地,有橄榄 树 和蜂蜜 之地,好使你们存活,不至 于 死。 希西家 劝导 你们,说 耶和华 必拯救我们;你们不要 听他的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, '列国 的神 有哪一个 救 他本国 脱离 亚述 王 的手呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, '哈马、亚珥拔 的神 在哪里呢?西法瓦音、希拿、以瓦 的神 在哪里呢? 他们曾救 撒马利亚 脱离我的手吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, '这些国 的 神 有谁 曾救 自己的国 脱离我的手呢?难道 耶和华 能救 耶路撒冷 脱离我的手吗?』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, '百姓 静默不言,并不 回答 一句,因为 王 曾吩咐 说:「不要 回答他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, '当下,希勒家 的儿子 家 宰 以利亚敬 和书记 舍伯那,并亚萨 的儿子 史官 约亚,都撕裂 衣服,来 到 希西家那里,将拉伯沙基 的话 告诉了 他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, ' 希西家 王 听见,就撕裂 衣服,披上 麻布,进了 耶和华 的殿; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, '使 家 宰 以利亚敬 和书记 舍伯那,并 祭司 中的长老,都披上 麻布,去见 亚摩斯 的儿子 先知 以赛亚, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, '对他 说:「希西家 如此 说:『今 日 是急难、责罚、凌辱 的日子,就 如妇人将 要 生产 婴孩,却没 有力量 生产。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, '或者 耶和华─你的 神 听见 拉伯沙基 的一切 话,就是 他主人 亚述 王 打发 他来辱骂 永生 神的话,耶和华─你的 神 听见 这话,就发斥责。故此,求你为 余 馀剩的 民 扬声 祷告。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, '希西家 王 的臣仆 就去 见 以赛亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, '以赛亚 对他们 说:「要这样 对 你们的主人 说,耶和华 如此 说:『 你听见 亚述 王 的仆人 亵渎 我 的 话,不要 惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, '我必惊动(原文是使 灵进入)他的心,他要听见 风声 就归回 本地。我必使他在那里 倒 在刀下。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, '拉伯沙基 回去,正遇见 亚述 王 攻打 立拿,原来 他早听见 亚述王拔营离开  拉吉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, '亚述王听见 人论 古实 王 特哈加 说:「 他出来 要与你 争战 。」于 是亚述王又 打发 使者 去见 希西家,吩咐他们说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, '「你们对 犹大 王 希西家 如此 说:『不要 听你 所 倚靠的 神 欺哄你,说 耶路撒冷 必不 交 在亚述 王 的手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, ' 你 总听说 亚述 诸王 向列 国 所 行的,乃是尽行灭绝,难道你 还能得救吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, '我列祖 所 毁灭的,就是 歌散、 哈兰、利色,和属提.拉撒 的伊甸 人,这些国 的神 何曾拯救 这些国呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, '哈马 的王、亚珥拔 的王、西法瓦音 城 的王、希拿,和以瓦 的王都在哪里呢?』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, '希西家 从使者 手里接过 书信来,看完了,就上 耶和华 的殿,将书信在耶和华 面前 展开 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, '希西家 向 耶和华 祷告 说:「坐在 二基路伯 上耶和华─以色列的 神啊,你 是 天下 万 国的 神,你 曾创造 天 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, '耶和华啊,求你侧 耳 而听!耶和华啊,求你睁 眼 而看!要听 西拿基立 打发 使者来辱骂 永生 神 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, '耶和华啊,亚述 诸王 果然 使 列国 和 列国之地 变为荒凉, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, '将 列国的神 像都扔 在火里;因为 它 本不是 神,乃是 人 手 所造的,是木头 石头的,所以灭绝它。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, '耶和华─我们的 神啊,现在 求 你救我们 脱离亚述王的手,使天下 万 国 都知道 惟独 你─耶和华是 神!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, '亚摩斯 的儿子 以赛亚 就打发 人去见 希西家,说:「耶和华─以色列的 神 如此 说:『你既然 求 我 攻击 亚述 王 西拿基立,我已听见了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, '耶和华 论他 这 样 说:锡安 的处女 藐视 你,嗤笑 你;耶路撒冷 的女子 向你 摇 头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, '你辱骂 谁?亵渎 谁?扬起 声来,高 举 眼目攻击谁呢?乃是攻击 以色列 的圣者! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, '你藉 借 你的使者 辱骂 主,并说:我 率领许多 战 车 上 山 顶,到黎巴嫩 极深之处;我要砍伐 其中高大的 香柏树 和佳美的 松树;我必上 极 高之处,进入肥田 的树林。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, '我 已经在外邦 挖 井喝 水;我必用脚 掌 踏干 埃及 的一切 河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, '耶和华说,我早先 所做的,古 时 所立的,就是现在 藉 借你使 坚固 城 荒废,变为乱 堆,这事你岂没有 听见吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, '所以其中的居民 力量 甚小,惊惶 羞愧。他们 像野 草,像青 菜,如房顶上 的草,又如未长成 而枯干的 禾稼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, '你坐下,你出去,你进来, 你向我 发烈怒,我都知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, '因 你向我 发烈怒,又因你狂傲的 话达到 我耳中,我就要用 钩子 钩上你的鼻子,把嚼环 放在你口里,使你从你来 的 路 转回去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, '「以色列人哪,我赐你们 一个 证据:你们今年 要吃 自生的,明 年 也要吃自长的;至于 后 年,你们要耕种 收割,栽植 葡萄园,吃 其中的果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, '犹大 家 所逃脱 余 馀剩的,仍要 往下 扎根,向上 结 果。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, '必有 余 馀剩的民 从耶路撒冷 而出;必有逃脱 的人从锡安 山而来。耶和华 的热心 必成就 这事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, '「所以,耶和华 论 亚述 王 如此 说:『他必不得 来 到 这 城,也不 在这里 射 箭,不得 拿盾牌 到城前,也不 筑 垒 攻城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, '他从哪 条路 来,必从那条路回去,必不得 来 到 这 城。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, '因我为自己的缘故,又为 我仆人 大卫的缘故,必保护 拯救 这 城。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, ' 当 夜,耶和华 的使者 出去,在亚述 营中 杀了 十 八 万五 千人。清早 有人起来,一看,都是 死 尸了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, '亚述 王 西拿基立 就拔营 回 去,住 在尼尼微。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, '一日 在他的神 尼斯洛 庙 里叩拜,他儿子 亚得米勒 和沙利色 用刀 杀了他, 就逃 到亚拉腊 地。他儿子 以撒哈顿 接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, '那 时,希西家 病得 要死。亚摩斯 的儿子 先知 以赛亚 去 见他,对他 说:「耶和华 如此 说:『你 当留遗命 与你的家,因为 你必死,不能 活了。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, '希西家就转 脸 朝 墙,祷告 耶和华 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, '「耶和华啊,求 你记念 我在你面前 怎样存完全的 心,按诚实 行事,又做 你眼中 所看为善的。」希西家 就痛 哭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, ' 以赛亚 出来,还没有 到中 院(院:或译城),耶和华 的话 就临 到他,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, '「你回去 告诉 我民 的君 希西家说:耶和华─你祖 大卫的 神 如此 说:『我听见了 你的祷告,看见了 你的眼泪,我必 医治 你;到第三 日,你必上 到耶和华 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, '我必加增 你十 五 年 的寿数,并且我要救你 和 这 城 脱离亚述 王 的手。我为自己 和 我仆人 大卫的缘故,必保护 这 城。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, '以赛亚 说:「当取 一块无花果 饼来。」人就取了来,贴 在 疮上,王便痊愈了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, '希西家 问 以赛亚 说:「 耶和华 必医治 我,到第三 日,我能上 耶和华 的殿,有什么 兆头呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, '以赛亚 说:「耶和华 必 成就 他所 说的。这是 他 给你 的兆头:你要日影 向前进 十 度呢?是 要往后退 十 度呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, '希西家 回答说:「日影 向前进 十 度 容易, 我要日影 往后 退 十 度。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, '先知 以赛亚 求告 耶和华,耶和华就使 亚哈斯 的日晷 向前进 的 日影,往后 退了 十 度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, '那 时,巴比伦 王 巴拉但 的儿子米罗达‧巴拉但 听见 希西家 病而痊愈,就送 书信 和礼物 给 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, '希西家 听从 使者的话,就把 他宝 库的 金子、 银子、 香料、 贵重的 膏油,和 他武 库 的一切军器,并他所有的 财宝,都 给他们看。他家中 和他全 国之内,希西家 没 有 一样 不 给他们看的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, '于 是先知 以赛亚 来 见 希西家 王,问他 说:「这些 人 说 什么?他们从哪里 来 见你?」希西家 说:「他们从远 方 的巴比伦 来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, '以赛亚说:「他们在你家里 看见了 什么?」希西家 说:「 凡 我家中 所有的,他们都看见了;我财宝 中没 有 一样 不 给他们看的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, '以赛亚 对 希西家 说:「你要听 耶和华 的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, ' 日子 必到,凡 你家里 所有的,并 你列祖 积蓄 到 如 今的,都要被掳 到巴比伦去,不 留下 一样。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, '并且 从你 本身 所 生 的众子,其中必有被掳去 在巴比伦 王 宫 里当 太监的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, '希西家 对 以赛亚 说:「你所 说 耶和华 的话 甚好! 若 在我的年日 中有 太平 和稳固的景况,岂不是好吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, '希西家 其余 馀 的事 和 他的勇力,他怎样 挖 池、挖 沟、引 水 入城,都 写 在 犹大 列王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, '希西家 与 他列祖 同睡。他儿子 玛拿西 接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, '玛拿西 登基 的时候年 十 二 岁,在耶路撒冷 作王 五十 五 年。他母亲 名叫 协西巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, '玛拿西行 耶和华 眼中 看为恶的事,效法耶和华 在以色列 人 面前 赶出 的 外邦人 所行可憎的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, '重新 建筑 他父 希西家 所 毁坏 的邱坛,又为巴力 筑 坛,做 亚舍拉像,效法 以色列 王 亚哈 所行的,且敬拜 事奉 天上 的万 象; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, '在耶和华 殿宇 中筑 坛。耶和华 曾指著这殿 说:「我必立 我的名 在耶路撒冷。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, '他在耶和华 殿 的两 院 中为天上 的万 象 筑 坛, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, '并使 他的儿子 经 火,又观兆,用法术,立 交鬼的 和行巫术的,多 行 耶和华 眼中 看为恶的事,惹动他的怒气; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, '又在殿 内立 雕刻的 亚舍拉像。 耶和华 曾对 大卫 和 他儿子 所罗门 说:「我在以色列 众 支派 中所 选择 的耶路撒冷 和这 殿,必立 我的名,直到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, '以色列人 若 谨守 遵行 我一切 所 吩咐他们 的和我仆人 摩西 所 吩咐 他们 的一切 律法,我就不 再 使他们 挪移 离开  我所 赐 给他们列祖 之地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, '他们却不 听从。玛拿西 引诱他们 行 恶,比 耶和华 在以色列 人 面前 所 灭 的列国更甚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, '耶和华 藉 借 他仆人 众先知 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, '「因 犹大 王 玛拿西 行 这些 可憎的 恶事 比 先前 亚摩利人 所 行的更甚, 使 犹大人 拜他的偶像,陷在罪里; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, '所以 耶和华─以色列的 神 如此 说:我必 降 祸 与 耶路撒冷 和犹大,叫一切 听见 的人 无不 耳 鸣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, '我必用量 撒马利亚 的准绳 和 亚哈 家 的线 缐铊 拉 在 耶路撒冷上,必擦净 耶路撒冷,如 人擦 盘,将盘倒 扣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, '我必弃掉 所余 馀剩的子民(原文是产业),把他们交 在仇敌 手中,使他们成为 一切 仇敌 掳掠 之物; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, '是因 他们自从 列祖 出 埃及 直到 如 今,常行 我眼中 看为恶的事, 惹动我 的怒气。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, ' 玛拿西 行 耶和华 眼中 看为恶的事,使 犹大人 陷在罪里,又 流 许 多 无辜人 的血, 充满了 耶路撒冷,从这边 直到那边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, '玛拿西 其余 馀 的事,凡 他所 行 的和他所 犯 的罪都 写 在 犹大 列王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, '玛拿西 与 他列祖 同睡,葬 在自己宫 院 乌撒 的园内;他儿子 亚们 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, '亚们 登基 的时候年 二十 二 岁,在耶路撒冷 作王 二 年。他母亲 名 叫米舒利密,是 约提巴人 哈鲁斯 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, '亚们行 耶和华 眼中 看为恶的事,与他父亲 玛拿西 所 行的一样; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, '行 他父亲 一切 所 行 的,敬奉 他父亲 所 敬奉 的偶像, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, '离弃 耶和华─他列祖的 神,不 遵行 耶和华 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, '亚们 王的臣仆 背叛 他,在宫里 杀了 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, '但国 民 杀了 那些 背叛 亚们 王的人, 立 他儿子 约西亚 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, '亚们 其余 馀 所 行 的事都 写 在 犹大 列王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, '亚们 葬 在乌撒 的园 内自己的坟墓里。他儿子 约西亚 接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, '约西亚 登基 的时候年 八 岁,在耶路撒冷 作王 三十 一 年。他母亲 名叫 耶底大,是波斯加人 亚大雅 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, '约西亚行 耶和华 眼中 看为正的事,行 他祖 大卫 一切 所行的,不 偏 左 右。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, ' 约西亚 王 十 八 年,王 差遣 米书兰 的孙子、亚萨利 的儿子─书记 沙番 上耶和华 殿去,吩咐他说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, '「你去 见 大 祭司 希勒家,使他将 奉到 耶和华 殿 的银子,就是 守 门 的从 民 中收聚的银子,数算数算, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, '交 给 耶和华 殿里 办 事的人,使他们转交 耶和华 殿里 做 工 的人,好修理 殿 的破坏之处, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, '就是转交木匠 和工人,并瓦匠,又买  木料 和凿成的 石头 修理 殿宇, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, '将银子 交 在 办事的人手里, 不 与他们 算帐,因为 他们 办事 诚实。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, '大 祭司 希勒家 对 书记 沙番 说:「我在耶和华 殿里 得了 律法 书。」希勒家 将 书 递 给 沙番,沙番就看了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, '书记 沙番 到 王那里,回 覆 复 王 说:「你的仆人 已将 殿 里 的银子 倒出数算,交 给 耶和华 殿里 办 事的人了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, '书记 沙番 又 对王 说:「祭司 希勒家 递 给我 一卷书。」沙番 就在王 面前 读那书。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, ' 王 听见 律法 书 上的话,便撕裂 衣服, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, ' 吩咐 祭司 希勒家 与 沙番 的儿子 亚希甘、 米该亚 的儿子 亚革波、 书记 沙番 和 王 的臣仆 亚撒雅,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, '「你们去 为我、为 民、为 犹大 众人,以 这 书 上的话 求问 耶和华;因为 我们列祖 没有 听从 这 书 上的言语,没有遵著 书上所吩咐 我们 的去行, 耶和华 就 向我们 大 发 烈怒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, '于 是,祭司 希勒家 和亚希甘、亚革波、沙番、亚撒雅 都去 见 女先知 户勒大。户勒大是掌管 礼服 沙龙 的妻;沙龙是哈珥哈斯 的孙子、特瓦 的儿子。户勒大 住 在耶路撒冷 第二区。他们请问 于 她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, '她对他们 说:「耶和华─以色列的 神 如此 说:『你们可以回复那 差遣 你们 来见我 的人 说, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, '耶和华 如此 说:我必 照著犹大 王 所 读 那书 上的一切 话,降 祸 与 这 地 和其上 的居民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, '因为 他们离弃我,向别 神 烧香,用 他们手 所做的 惹我发怒,所以我的忿怒 必向这 地 发作,总不 止息。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, '然而,差遣 你们 来求问 耶和华 的犹大 王,你们要这样 回复他 说:『耶和华─以色列的 神 如此 说:至于 你所 听见 的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, '就是听见 我指著 这 地 和 其上的居民 所 说、要使这地变为 荒场、民受咒诅的话,你便 心里 敬服,在我 面前 自卑,撕裂 衣服,向我 哭泣,因此 我 应允了你。这是我─耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, ' 我必 使你平平安安地 归 到 坟墓 到 你列祖那里;我 要降 与 这 地 的 一切 灾祸,你也不 致亲眼 看见。』」他们就回 覆 复 王去了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, '王 差遣 人招聚 犹大 和耶路撒冷 的众 长老 来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, '王 和犹大 众 人 与 耶路撒冷 的居民,并 祭司、先知,和所有的 百姓,无论 大 小,都一同上 到耶和华 的殿;王就把 耶和华 殿里 所得的 约 书 念 给他们听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, '王 站 在 柱旁,在耶和华 面前 立 约,要尽 心 尽 性 地顺 从 耶和华,遵守 他的诫命、 法度、 律例,成就 这 书 上 所记的 约 言。众 民 都服从 这约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, '王 吩咐 大 祭司 希勒家 和 副 祭司,并 把 门的,将 那为巴力 和亚舍拉,并天上 万 象 所造的 器皿,都从耶和华 殿里 搬出来,在耶路撒冷 外 汲沦 溪旁的田间 烧了,把 灰 拿 到伯特利去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, '从前犹大 列王 所 立 拜偶像的祭司,在犹大 城邑 的邱坛 和耶路撒冷 的周围 烧香,现在王都废去,又废去 向巴力 和日、月、行星(或译:十二宫),并天上 万 象 烧香的人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, '又从耶和华 殿里 将 亚舍拉 搬 到 耶路撒冷 外 汲沦 溪 边焚烧,打碎 成灰,将 灰 撒 在 平 民 的坟上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, '又拆毁 耶和华 殿里 娈童 的屋子,就是 妇女 为亚舍拉 织 帐子 的屋子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, '并且从犹大 的城邑 带 众 祭司来,污秽 祭司 烧香 的 邱坛,从迦巴 直到 别是巴,又拆毁 城门 旁的 邱坛,这邱坛在邑 宰 约书亚 门 前,进城 门的 左边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, '但是 邱坛 的祭司 不 登 耶路撒冷 耶和华 的坛,只 在他们弟兄 中间 吃 无酵饼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, '又污秽 欣嫩 子 谷 的 陀斐特,不许 人 在那里使 儿 女 经 火 献给摩洛; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, '又将 犹大 列王 在耶和华 殿门旁、太监拿单.米勒 靠近 游廊 的 屋子、向日头 所 献 的马 废去,且用火 焚烧 日 车。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, ' 犹大 列王 在 亚哈斯 楼 顶上 所 筑 的 坛 和 玛拿西 在耶和华 殿 两 院 中所 筑 的坛,王 都拆毁 打碎了,就把 灰 倒 在 汲沦 溪中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, ' 从前以色列 王 所罗门 在 耶路撒冷 前、 邪僻 山 右边 为西顿人 可憎的神 亚斯她录、摩押人 可憎的神 基抹、亚扪 人 可憎的神 米勒公 所 筑 的邱坛,王 都污秽了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, '又打碎 柱像,砍下 木偶,将人 的骨头 充满了 那地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, ' 他将 伯特利 的 坛, 就是 叫 以色列人 陷在罪里、尼八 的儿子 耶罗波安 所 筑 的那 坛,都拆毁 焚烧,打碎 成灰,并焚烧了 亚舍拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, '约西亚 回头,看见 山上 的 坟墓,就打发人 将 坟墓 里的骸骨 取出来,烧 在 坛上,污秽了坛,正如 从前神 人 宣传 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, '约西亚问说:「我 所 看见 的是什么 碑?」那城 里的人回答 说:「先前有 神 人 从犹大 来,预先说 王现在向 伯特利 坛 所 行 的事,这就是他的墓碑。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, '约西亚说:「由他吧! 不要 挪移 他的骸骨。」他们就不动 他的骸骨,也 不动从撒马利亚 来 那 先知 的骸骨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, ' 从前以色列 诸王 在撒马利亚 的 城邑 建筑 邱坛 的殿,惹动耶和华的怒气,现在约西亚 都废去了, 就如 他在伯特利 所 行 的一般; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, '又将 邱坛 的 祭司 都 杀 在 坛上,并在坛上 烧 人 的骨头,就回 耶路撒冷去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, '王 吩咐 众 民 说:「你们当照这 约 书 上 所写的,向耶和华─你们的 神 守 逾越节。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, '自从 士师 治理 以色列人 和以色列 王、犹大 王 的时候,直到如今,实在 没有 守 过这样的 逾越节; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, '只有 约西亚 王 十 八 年 在耶路撒冷 向耶和华 守 这 逾越节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, ' 凡犹大 国 和耶路撒冷 所 有 交鬼的、 行巫术的,与 家中的神像 和 偶像,并 一切 可憎之物,约西亚 尽都除掉, 成就了 祭司 希勒家 在耶和华 殿里 所 得 律法 书 上 所写 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, '在约西亚以前 没 有 王 像他 尽 心、尽 性、尽 力地 归 向 耶和华,遵行摩西 的一切 律法;在他以后 也没有 兴起 一个王像他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, '然而,耶和华 向犹大 所 发 猛烈的 怒 气 仍不 止息,是因 玛拿西 诸 事 惹动他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, '耶和华 说:「我必 将 犹大人 从 我面前 赶出,如同 赶出 以色列人一般;我必弃掉 我从前所 选择 的这 城─ 耶路撒冷 和 我所 说 立 我名 的殿。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, '约西亚 其余 馀 的事,凡 他所 行的都 写 在 犹大 列王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, '约西亚年间,埃及 王 法老 尼哥上 到 幼发拉底 河 攻击 亚述 王;约西亚 王 去 抵挡他。埃及王遇见 约西亚 在米吉多,就杀了他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, '他的臣仆 用车 将他的尸首 从米吉多 送到 耶路撒冷,葬 在他自己的坟墓里。国 民 膏 约西亚 的儿子 约哈斯 接续 他父亲 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, '约哈斯 登基 的时候年 二十 三 岁,在耶路撒冷 作王 三个 月。他母亲 名叫 哈慕她,是立拿人 耶利米 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, '约哈斯行 耶和华 眼中 看为恶的事,效法他列祖 一切 所 行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, '法老尼哥 将约哈斯锁禁 在哈马 地 的利比拉,不许他在耶路撒冷 作王,又 罚 犹大国 银子 一百 他连得,金子 一他连得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, '法老尼哥 立 约西亚 的儿子 以利亚敬 接续 他父亲 约西亚 作王,给 他改 名 叫约雅敬,却将 约哈斯 带 到 埃及,他就死 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, '约雅敬 将金 银 给 法老,遵著 法老 的命 向 国民 征 取 金银,按著各人 的力量派定,索要 金 银,好给 法老尼哥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, '约雅敬 登基 的时候年 二十 五 岁,在耶路撒冷 作王 十 一 年。他母亲 名叫 西布大,是 鲁玛人 毘大雅 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, '约雅敬行 耶和华 眼中 看为恶的事,效法他列祖 一切 所 行的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, '约雅敬年间,巴比伦 王 尼布甲尼撒 上到犹大;约雅敬 服事 他 三 年,然后 背叛 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, '耶和华 使 迦勒底 军、 亚兰 军、 摩押 军,和 亚扪 人 的军 来攻击约雅敬,毁灭 犹大,正如 耶和华 藉 借 他仆人 众先知 所 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, '这祸临 到犹大人,诚然 是耶和华 所 命的,要将他们从 自己面前 赶出,是因玛拿西 所 犯 的一切 罪; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, '又 因他 流 无辜人 的血,充满了 耶路撒冷;耶和华 决不 肯 赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, '约雅敬 其余 馀 的事,凡 他所 行的都 写 在 犹大 列王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, '约雅敬 与 他列祖 同睡。他儿子 约雅斤 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, '埃及 王 不 再 从他国中 出来;因为 巴比伦 王 将埃及 王 所 管之地,从埃及 小河 直到 幼发拉底 河 都 夺去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, '约雅斤 登基 的时候年 十 八 岁,在耶路撒冷 作王 三个 月。他母亲 名 叫尼护施她,是耶路撒冷人 以利拿单 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, '约雅斤行 耶和华 眼中 看为恶的事,效法他父亲 一切 所 行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, '那 时,巴比伦 王 尼布甲尼撒 的军兵 上 到 耶路撒冷,围困 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, '当他军兵 围困 城的时候,巴比伦 王 尼布甲尼撒 就亲自来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, '犹大 王 约雅斤 和他母亲、臣仆、首领、太监 一同出城,投降 巴比伦 王;巴比伦 王 便拿住 他。那时是巴比伦 王 第八 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, '巴比伦王将 耶和华 殿 和王 宫 里的宝物 都拿去了,将 以色列 王 所罗门 所 造 耶和华 殿里 的金 器 都 毁坏了,正如 耶和华 所说的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, '又将 耶路撒冷 的众民 和 众 首领,并 所有 大能的 勇士,共一万人,连一切 木匠、铁匠 都掳了去;除了 国 中极贫穷的 人以外,没有 剩下的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, '并 将 约雅斤 和 王 母、 后妃、 太监,与 国中 的大官,都从耶路撒冷 掳 到巴比伦 去了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, ' 又将 一切 勇 士 七 千 人和木匠、铁匠 一千人,都是 能上 阵 的勇士,全掳 到巴比伦 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, '巴比伦 王 立 约雅斤的叔叔 玛探雅 代替他 作王,给 玛探雅改 名 叫西底家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, '西底家 登基 的时候年 二十 一 岁,在耶路撒冷 作王 十 一 年。他母亲 名叫 哈慕她,是立拿人 耶利米 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, '西底家行 耶和华 眼中 看为恶的事,是照约雅敬 一切 所 行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, '因此 耶和华 的怒气 在耶路撒冷 和犹大 发作,以致 将人民 从 自己面前 赶出。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, '西底家 背叛 巴比伦 王。 他作王 第九 年 十 月 初 十日,巴比伦 王 尼布甲尼撒 率领全 军 来 攻击 耶路撒冷,对城 安营,四围 筑 垒 攻城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, '于 是城 被 围困,直到 西底家 王 十 一 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, '四月 初九日,城里 有大 饥荒,甚至百姓 都没 有 粮食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, '城 被攻破,一切 兵 丁 就在夜间 从靠近 王 园 两城 中间 的门逃跑。迦勒底人 正在四围 攻 城,王就向 亚拉巴 逃走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, '迦勒底 的军队 追 赶 王,在耶利哥 的平原 追上 他;他的全 军 都离开 他 四散了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, '迦勒底人就拿住 王,带 他 到 在利比拉 的巴比伦 王 那里 审判 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, '在西底家 眼前 杀了 他的众子,并且剜了 西底家 的眼睛,用铜炼 链 𫔀 锁著他,带到 巴比伦去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, '巴比伦 王 尼布甲尼撒 十 九 年 五 月 初 七日,巴比伦 王 的臣仆、护卫 长 尼布撒拉旦 来到 耶路撒冷, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, '用火 焚烧 耶和华 的殿 和 王 宫,又焚烧 耶路撒冷的 房屋,就是 各 大 户家的房屋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, ' 跟从护卫 长 迦勒底 的全 军 就拆毁 耶路撒冷 四围 的城墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, '那时护卫 长 尼布撒拉旦 将 城 里 所剩下的 百姓,并 已经投降 巴比伦 王的 人,以及 大众 所剩下的人,都掳去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, '但护卫 长 留下 些民中 最穷的,使他们修理葡萄园,耕种田地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, ' 耶和华 殿 的 铜 柱,并 耶和华 殿 的 盆座 和 铜 海,迦勒底人 都打碎了,将 那铜 运到 巴比伦去了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, '又带去 锅、 铲子、 蜡剪、 调羹,并 所 用的 一切 铜 器, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, ' 火鼎、 碗,无论 金的 银的,护卫 长 也都带去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, '所罗门 为耶和华 殿 所 造 的两根 铜柱、一个 铜海,和几个盆座,这 一切的 铜,多得无法 可称。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, '这一根 柱子 高 十 八 肘,柱上 有铜 顶, 高 三 肘; 铜顶 的周围 有网子 和石榴,都是 铜的。那一根 柱子,照此一样,也有 网子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, '护卫 长 拿住 大 祭司 西莱雅、 副 祭司 西番亚,和 三个 把 门的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, '又从 城中 拿住 一个 管理 兵 丁 的 官(或译:太监),并在城里 所 遇 常见 王 面 的五个 人 和 检点 国 民 军 长 的书记,以及城里 遇见 的国 民 六十个 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, '护卫 长 尼布撒拉旦 将 这些人 带 到 在利比拉 的巴比伦 王那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, '巴比伦 王 就把他们 击 杀 在哈马 地 的利比拉。这样,犹大人 被掳去 离开  本地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, '至于 犹大 国 剩下的 民,就是 巴比伦 王 尼布甲尼撒 所剩下的,巴比伦王立了 沙番 的孙子、亚希甘 的儿子 基大利 作他们的省长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, '众 军 长 和属他们的人 听见 巴比伦 王 立了 基大利作省长,于 是军长尼探雅 的儿子 以实玛利、加利亚 的儿子 约哈难、尼陀法人 单户蔑 的儿子 西莱雅、玛迦人 的儿子 雅撒尼亚, 和属他们的人 都到 米斯巴 见 基大利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, '基大利 向他们 和属他们的人 起誓 说:「你们不必 惧怕 迦勒底 臣仆,只管住 在这地 服事 巴比伦 王,就可以得福。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, ' 七 月间,宗 室 以利沙玛 的孙子、尼探雅 的儿子 以实玛利 带著 十个 人 来,杀了 基大利 和 同他 在米斯巴 的犹大人 与 迦勒底人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, '于 是众 民,无论 大 小,连众军 长;因为 惧怕 迦勒底人,都起身 往埃及 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, ' 犹大 王 约雅斤 被掳 后三十 七 年,巴比伦 王以未.米罗达 元年 十 二 月 二十 七日,使 犹大 王 约雅斤 抬 头,提他出监; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, '又对他 说 恩言,使 他的位 高过 与他 一同在巴比伦 众王 的位, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, '给他脱了 囚 服。他终 身 常 在巴比伦王面前 吃 饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, ' 王 赐 他 所需 用 的食物,日 日 赐他一分,终 身都是这样。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, '亚当 生塞特;塞特生以挪士; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, '以挪士生该南;该南生玛勒列;玛勒列生雅列; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, '雅列生以诺;以诺生玛土撒拉;玛土撒拉生拉麦; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, '拉麦生挪亚;挪亚生闪、含、雅弗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, '雅弗 的儿子 是歌篾、玛各、玛代、雅完、土巴、米设、提拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, '歌篾 的儿子 是亚实基拿、低法(在创世记十章三节是利法)、陀迦玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, '雅完 的儿子 是以利沙、他施、基提、多单。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, '含 的儿子 是古实、麦西、弗、迦南。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, '古实 的儿子 是西巴、哈腓拉、撒弗他、拉玛、撒弗提迦。拉玛 的儿子 是示巴、底但。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, '古实 生 宁录;他 为 世上 英雄 之首。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, '麦西 生 路低人、 亚拿米人、 利哈比人、 拿弗土希人、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, ' 帕斯鲁细人、 迦斯路希人、 迦斐托 讬人; 从迦斐托 讬 出来 的有非利士人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, '迦南 生 长子 西顿,又生 赫 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, '和 耶布斯人、 亚摩利人、 革迦撒人、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, ' 希未人、 亚基人、 西尼人、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, ' 亚瓦底人、 洗玛利人,并 哈马人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, '闪 的儿子 是以拦、亚述、亚法撒、路德、亚兰、乌斯、户勒、基帖、米设(在创世记十章二十三节是玛施)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, '亚法撒 生 沙拉;沙拉 生 希伯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, '希伯 生了 两个 儿子:一个 名 叫法勒(就是分的意思),因为 那时 人就分 地居住;法勒的兄弟 名 叫约坍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, '约坍 生 亚摩答、 沙列、 哈萨玛非、 耶拉、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, ' 哈多兰、 乌萨、 德拉、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, ' 以巴录、 亚比玛利、 示巴、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, ' 阿斐、 哈腓拉、 约巴。这 都是 约坍 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, '闪 生亚法撒;亚法撒生沙拉; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, '沙拉生希伯;希伯生法勒;法勒生拉吴; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, '拉吴生西鹿;西鹿生拿鹤;拿鹤生他拉; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, '他拉生亚伯兰,亚伯兰就是 亚伯拉罕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, '亚伯拉罕 的儿子 是以撒、以实玛利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, '以实玛利的儿子 记在下面:以实玛利 的长子 是尼拜约,其次是基达、押德别、米比衫、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, '米施玛、度玛、玛撒、哈达、提玛、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, '伊突、拿非施、基底玛。这 都是 以实玛利 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, '亚伯拉罕 的妾 基土拉 所生的 儿子,就是 心兰、约珊、米但、米甸、伊施巴、书亚。约珊 的儿子 是示巴、底但。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, '米甸 的儿子 是以法、以弗、哈诺、亚比大、以勒大。这 都是 基土拉 的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, '亚伯拉罕 生 以撒;以撒 的儿子 是以扫 和以色列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, '以扫 的儿子 是以利法、流珥、耶乌施、雅兰、可拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, '以利法 的儿子 是提幔、阿抹、洗玻、迦坦、基纳斯、亭纳、亚玛力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, '流珥 的儿子 是拿哈、谢拉、沙玛、米撒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, '西珥 的儿子 是罗坍、朔巴、祭便、亚拿、底顺、以察、底珊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, '罗坍 的儿子 是何利、荷幔;罗坍 的妹子 是亭纳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, '朔巴 的儿子 是亚勒文、玛拿辖、以巴录、示非、阿南。祭便 的儿子 是亚雅、亚拿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, '亚拿 的儿子 是底顺。底顺 的儿子 是哈默兰、伊是班、益兰、基兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, '以察 的儿子 是辟罕、撒番、亚干。底珊 的儿子 是乌斯、亚兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, '以色列 人 未有君王 治理 之先, 在以东 地 作王 的 记在下面:有比珥 的儿子 比拉,他的京城 名 叫亭哈巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, '比拉 死了,波斯拉人 谢拉 的儿子 约巴 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, '约巴 死了,提幔 地 的人户珊 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, '户珊 死了,比达 的儿子 哈达 接续他 作王。这哈达就是在摩押 地 杀败 米甸人的,他的京城 名 叫亚未得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, '哈达 死了,玛士利加人 桑拉 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, '桑拉 死了,大河 边的利河伯人 扫罗 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, '扫罗 死了,亚革波 的儿子巴勒‧哈南 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, '巴勒‧哈南 死了,哈达 接续他 作王。他的京城 名 叫巴伊,他的妻子 名叫 米希她别,是米‧萨合 的孙女,玛特列 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, '哈达 死了,以东人 的族长 有 亭纳 族长、亚勒瓦 族长、耶帖 族长、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, '亚何利巴玛 族长、以拉 族长、比嫩 族长、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, '基纳斯 族长、提幔 族长、米比萨 族长、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, '玛基叠 族长、以兰 族长。这都是 以东人 的族长。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, '以色列 的儿子 是 流便、西缅、利未、犹大、以萨迦、西布伦、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, '但、约瑟、便雅悯、拿弗他利、迦得、亚设。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, '犹大 的儿子 是珥、俄南、示拉,这三 人是迦南人 书亚 女儿 所生的。 犹大 的长子 珥 在耶和华 眼中 看为恶,耶和华就使他死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, '犹大的儿妇 她玛 给犹大 生 法勒斯 和 谢拉。犹大 共有 五个 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, '法勒斯 的儿子 是希斯仑 、哈母勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, '谢拉 的儿子 是心利、以探、希幔、甲各、大拉(就是达大),共 五人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, '迦米 的儿子 是亚干,这亚干 在当灭的物 上犯了罪,连累了 以色列人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, '以探 的儿子 是亚撒利雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, '希斯仑  所 生的 儿子 是 耶拉篾、 兰、 基路拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, '兰 生 亚米拿达;亚米拿达 生 拿顺。拿顺作犹大 人 的首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, '拿顺 生 撒门;撒门 生 波阿斯; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, '波阿斯 生 俄备得;俄备得 生 耶西; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, '耶西 生 长子 以利押,次子 亚比拿达,三 子示米亚(示米亚就是沙玛,见撒母耳上十六章九节), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, '四 子拿坦业,五 子拉代, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, '六 子阿鲜,七 子大卫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, '他们的姊妹 是洗鲁雅 和亚比该。洗鲁雅 的儿子 是亚比筛、约押、亚撒黑,共三人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, '亚比该 生 亚玛撒;亚玛撒 的父亲 是以实玛利人 益帖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, '希斯仑  的儿子 迦勒 娶 阿苏巴 和 耶略 为妻,阿苏巴的儿子 是 耶设、朔罢、押墩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, '阿苏巴 死了,迦勒 又娶 以法他,生了 户珥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, '户珥 生 乌利;乌利 生 比撒列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, '希斯仑  正 六十 岁 娶了 基列 父亲 玛吉 的女儿, 与 她同房;玛吉的女儿生了 西割; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, '西割 生 睚珥。睚珥 在基列 地 有 二十 三 个城邑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, '后来基述人 和亚兰人 夺了 睚珥 的城邑,并 基纳 和 其乡村,共六十 个。这 都是 基列 父亲 玛吉 之子的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, '希斯仑 在迦勒‧以法他 死 后,他的 妻 亚比雅 给他 生了 亚施户;亚施户是提哥亚 的父亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, '希斯仑  的长子 耶拉篾生 长子 兰,又生布拿、阿连、阿鲜、亚希雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, '耶拉篾 又 娶 一妻 名 叫亚她拉,是 阿南 的母亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, '耶拉篾 长子 兰 的儿子 是 玛斯、雅悯、以结。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, '阿南 的儿子 是 沙买 、雅大。沙买  的儿子 是拿答、亚比述。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, '亚比述 的妻 名 叫亚比孩,亚比孩给他生了 亚办 和 摩利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, '拿答 的儿子 是西列、亚遍;西列 死了 没有 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, '亚遍 的儿子 是以示;以示 的儿子 是示珊;示珊 的儿子 是亚来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, '沙买  兄弟 雅大 的儿子 是益帖、约拿单;益帖 死了 没有 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, '约拿单 的儿子 是比勒、撒萨。这 都是 耶拉篾 的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, '示珊 没 有 儿子,只有 女儿。示珊 有一个仆人 名 叫耶哈,是埃及人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, '示珊 将 女儿 给了 仆人 耶哈 为妻,给他 生了 亚太。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, '亚太 生 拿单;拿单 生 撒拔; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, '撒拔 生 以弗拉;以弗拉 生 俄备得; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, '俄备得 生 耶户;耶户 生 亚撒利雅; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, '亚撒利雅 生 希利斯;希利斯 生 以利亚萨; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, '以利亚萨 生 西斯买 ;西斯买  生 沙龙; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, '沙龙 生 耶加米雅;耶加米雅 生 以利沙玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, '耶拉篾 兄弟 迦勒 的 长子 米沙,是 西弗 之祖 玛利沙 的儿子,是希伯仑  之祖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, '希伯仑  的儿子 是可拉、他普亚、利肯、示玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, '示玛 生 拉含,是约干 之祖。利肯 生 沙买 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, '沙买  的儿子 是玛云;玛云是伯‧夙 之祖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, '迦勒 的妾 以法 生 哈兰、 摩撒、 迦谢;哈兰 生 迦卸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, '〈雅代 的儿子 是利健、约坦、基珊、毘力、以法、沙亚弗。〉 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, '迦勒 的妾 玛迦 生 示别、 特哈拿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, '又生 麦玛拿 之祖 沙亚弗、抹比拿 和基比亚 之祖 示法。迦勒 的女儿 是押撒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, '迦勒 的子孙 就是 以法他 的长子、户珥 的儿子,记在下面:基列‧耶琳 之祖 朔巴, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, '伯利恒 之祖 萨玛,伯迦得 之祖 哈勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, '基列‧耶琳 之祖 朔巴的 子孙 是 哈罗以 和一半米努‧哈人(米努‧哈人就是玛拿哈人)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, '基列‧耶琳 的诸族 是以帖人、布特人、舒玛人、密来人,又从这些 族中生出 琐拉人 和以实陶人来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, '萨玛 的子孙 是伯利恒人、尼陀法人、亚他绿‧伯‧约押人、一半 玛拿哈人、琐利人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, '和住 雅比斯 众文士 家 的特拉人、示米押人、苏甲人。这 都是基尼人 利甲 家 之祖 哈末 所生的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, '大卫 在希伯仑  所 生的 儿子 记在下面:长子 暗嫩 是耶斯列人 亚希暖生的。次子 但以利 是迦密人 亚比该生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, '三 子押沙龙 是基述 王 达买  的女儿 玛迦 生的。四 子亚多尼雅 是哈及 生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, '五 子示法提雅 是亚比她生的。六子 以特念 是大卫的妻 以格拉生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, '这六 人都是大卫 在希伯仑  生的。大卫 在希伯仑  作王 七 年 零六个 月,在耶路撒冷 作王 三十 三 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, ' 大卫在耶路撒冷 所生的 儿子 是示米亚、朔罢、拿单、所罗门。这四人 是亚米利 的女儿拔‧书亚生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, '还有益辖、以利沙玛、以利法列、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, '挪迦、尼斐、雅非亚、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, '以利沙玛、以利雅大、以利法列,共九人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, '这都是 大卫 的儿子,还有他们的妹子 她玛,妃嫔 的儿子 不在其内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, '所罗门 的儿子 是罗波安;罗波安的儿子 是亚比雅;亚比雅的儿子 是亚撒;亚撒的儿子 是约沙法; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, '约沙法的儿子 是约兰;约兰的儿子 是亚哈谢;亚哈谢的儿子 是约阿施; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, '约阿施的儿子 是亚玛谢;亚玛谢的儿子 是亚撒利雅;亚撒利雅的儿子 是约坦; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, '约坦的儿子 是亚哈斯;亚哈斯的儿子 是希西家;希西家的儿子 是玛拿西; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, '玛拿西的儿子 是亚们;亚们的儿子 是约西亚; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, '约西亚 的 长子 是约哈难,次子 是约雅敬,三 子是西底家,四 子是沙龙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, '约雅敬 的儿子 是耶哥尼雅 和西底家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, '耶哥尼雅 被掳。他的儿子 是撒拉铁、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, '玛基兰、毘大雅、示拿萨、耶加米、何沙玛、尼大比雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, '毘大雅 的儿子 是所罗巴伯、示每。所罗巴伯 的儿子 是米书兰、哈拿尼雅,他们的妹子 名叫示罗密。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, '米书兰的儿子是哈舒巴、阿黑、比利家、哈撒底、于沙‧希悉,共五人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, '哈拿尼雅 的儿子 是毘拉提、耶筛亚。还有利法雅 的众子,亚珥难 的众子,俄巴底亚 的众子,示迦尼 的众子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, '示迦尼 的儿子 是示玛雅;示玛雅 的儿子 是哈突、以甲、巴利亚、尼利雅、沙法,共六人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, '尼利雅 的儿子 是以利约乃、希西家、亚斯利干,共三人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, '以利约乃 的儿子 是何大雅、以利亚实、毘莱雅、阿谷、约哈难、第莱雅、阿拿尼,共七人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, '犹大 的儿子 是法勒斯、希斯仑 、迦米、户珥、朔巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, '朔巴 的儿子 利亚雅 生 雅哈;雅哈 生 亚户买  和 拉哈。这 是琐拉人 的诸族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, ' 以坦 之祖 的儿子是耶斯列、伊施玛、伊得巴;他们的妹子 名 叫哈悉勒玻尼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, '基多 之祖 是毘努伊勒。户沙 之祖 是以谢珥。这 都是伯利恒 之祖 以法他 的长子 户珥 所生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, '提哥亚 之祖 亚施户 有 两个 妻子:一名希拉,一名拿拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, '拿拉 给亚施户 生 亚户撒、 希弗、 提米尼、 哈辖斯他利。这 都是拿拉 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, '希拉 的儿子 是洗列、琐辖、伊提南。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, '哥斯 生 亚诺、 琐比巴,并哈仑  儿子 亚哈黑 的诸族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, ' 雅比斯 比他众弟兄 更尊贵,他母亲 给他起 名 叫雅比斯,意思说: 我生他 甚是痛苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, '雅比斯 求告 以色列的 神 说:「甚愿  你赐 福与我,扩张 我的境界, 常与我 同在,保佑 我不遭患难,不 受艰苦。」 神 就应允 他所 求的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, '书哈 的弟兄 基绿 生 米黑,米黑 是伊施屯 之祖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, '伊施屯 生 伯拉巴、 巴西亚,并 珥拿辖 之祖 提欣拿,这 都是利迦 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, '基纳斯 的儿子 是俄陀聂、西莱雅。俄陀聂 的儿子 是哈塔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, '悯挪太 生 俄弗拉;西莱雅 生 革‧夏纳欣 人之祖 约押。 他们都是 匠人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, '耶孚尼 的儿子 是迦勒;迦勒的儿子 是以路、以拉、拿安。以拉 的儿子 是基纳斯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, '耶哈利勒 的儿子 是西弗、西法、提利、亚撒列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, '以斯拉 的儿子 是益帖、米列、以弗、雅伦。米列 娶 法老 女儿 比提雅为妻,生 米利暗、 沙买 ,和 以实提摩 之祖 益巴。米列又娶犹大女子 为妻,生 基多 之祖 雅列, 梭哥 之祖 希伯,和 撒挪亚 之祖 耶古铁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, '荷第雅 的妻 是拿含 的妹子,她所生的儿子 是迦米人 基伊拉 和玛迦人 以实提摩 之祖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, '示门 的儿子 是暗嫩、林拿、便‧哈南、提伦。以示 的儿子 是梭黑与便‧梭黑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, '犹大 的儿子是示拉;示拉 的儿子 是利迦 之祖 珥,玛利沙 之祖 拉大,和属亚实比 族 织 细麻布 的 各家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, '还有约敬、哥西巴 人、约阿施、萨拉,就是 在摩押 地掌权的,又有雅叔比利恒。这都是古时 所记载的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, '这些人 都是窑匠,是尼他应 和基低拉 的居民;与 王 同处,为王做工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, '西缅 的儿子 是尼母利、雅悯、雅立、谢拉、扫罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, '扫罗的儿子 是沙龙;沙龙的儿子 是米比衫;米比衫的儿子 是米施玛; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, '米施玛 的儿子 是哈母利;哈母利的儿子 是撒刻;撒刻的儿子 是示每。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, '示每 有十 六 个儿子,六个 女儿,他弟兄 的儿女 不 多,他们各 家 不 如 犹大 族 的人丁增多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, '西缅人住 在别是巴、摩拉大、哈萨‧书亚、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, '辟拉、以森、陀腊、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, '彼土利、何珥玛、洗革拉、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, '伯‧玛嘉博、哈萨‧苏撒、伯‧比利、沙拉音,这些 城邑 直到 大卫 作王的时候都是属西缅人的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, '他们的 五个 城邑 是以坦、亚因、临门、陀健、亚珊; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, '还有属 城 的 乡村,直到 巴力。这 是他们的住处,他们都有 家谱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, '还有米所巴、雅米勒、亚玛谢 的儿子 约沙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, '约珥、约示比 的儿子 耶户;约示比是西莱雅 的儿子;西莱雅是亚薛 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, '还有以利约乃、雅哥巴、约朔海、亚帅雅、亚底业、耶西篾、比拿雅、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, '示非 的儿子 细撒。示非是亚龙 的儿子;亚龙是耶大雅 的儿子;耶大雅是申利 的儿子;申利是示玛雅 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, '以上 所记的 人名 都是作族 长的,他们宗 族 的人数增 多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, '他们往 平原 东边 基多 口 去,寻找 牧放羊群 的草场, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, '寻得 肥 美 的草场 地,又宽阔 又平静。 从前 住 那里 的是 含族的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, '以上 录 名的人,在犹大 王 希西家 年间,来 攻击 含族人的帐棚 和 那里 所有的 米乌尼人,将他们灭尽,就住在 他们的地方,直到 今 日,因为 那里 有草场 可以牧放羊群。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, '这 西缅 人 中,有五 百 人 上 西珥 山,率领他们的 是以示 的儿子 毘拉提、尼利雅、利法雅,和乌薛, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, '杀了 逃脱 剩下的 亚玛力人,就住 在那里 直到 今 日。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, '以色列 的长子 原 是 流便;因他污秽了 父亲 的床,他长子的名分 就归了 约瑟。只是按家谱 他不 算长子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, ' 犹大 胜过 一切弟兄,君王 也是从他而出;长子的名分 却归约瑟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, '以色列 长子 流便 的儿子 是哈诺、法路、希斯伦、迦米。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, '约珥 的儿子 是示玛雅;示玛雅的儿子 是歌革;歌革的儿子 是示每; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, '示每的儿子 是米迦;米迦的儿子是利‧亚雅;利‧亚雅的儿子 是巴力; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, '巴力的儿子是备‧拉。这备‧拉 作流便支派 的首领, 被亚述 王提革拉‧毘列色 掳去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, '他的弟兄 照著宗族,按著 家谱 作族长 的是耶利、撒迦利雅、比拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, '比拉 是亚撒 的儿子;亚撒是示玛 的儿子;示玛是约珥 的儿子;约珥 所住 的地方是从亚罗珥 直到 尼波和巴力‧免, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, '又向东 延 到 幼发拉底 河 这边 的旷野,因为 他们在基列 地 牲畜 增多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, '扫罗 年间,他们与 夏甲人 争战 ,夏甲人倒 在他们手下,他们就在 基列 东边 的全 地,住 在夏甲人的帐棚里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, '迦得 的子孙 在流便对面,住 在巴珊 地,延到 撒迦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, '他们中间有作族长 的约珥,有作副 族长的沙番,还有雅乃 和住在巴珊 的沙法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, '他们族 弟兄 是米迦勒、米书兰、示巴、约赖、雅干、细亚、希伯,共七人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, '这 都是亚比孩 的儿子。亚比孩是户利 的儿子;户利是耶罗亚 的儿子;耶罗亚是基列 的儿子;基列是米迦勒 的儿子;米迦勒是耶示筛 的儿子;耶示筛是耶哈多 的儿子;耶哈多是布斯 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, '还有古尼 的孙子、押比叠 的儿子 亚希。这都是作族 长的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, '他们住 在基列 与巴珊 和巴珊的乡村,并 沙仑  的郊野,直到 四围的交界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, '这些人在犹大 王 约坦 并在以色列 王 耶罗波安 年间,都 载入家谱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, '流便 人、迦得人,和玛拿西 半 支派的人,能拿 盾牌 和刀剑、拉弓 射箭、出 征 善 战 的 勇 士 共有四 万 四千 七 百 六十名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, '他们与 夏甲人、伊突人、拿非施人、挪答人 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, '他们得了 神的帮助,夏甲人 和跟随夏甲的人 都 交 在他们手中;因为 他们在阵上 呼求 神, 倚赖 神, 神就应允 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, '他们掳掠了 夏甲人的牲畜,有骆驼 五万,羊 二十五万,驴 二千;又有人 十万。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, ' 敌人被杀 仆倒 的甚多,因为 这争战 是出乎 神。他们就住 在敌人的地上,直到 被掳的时候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, '玛拿西 半 支派 的人 住 在那地。从巴珊 延到巴力‧黑们、示尼珥 与黑门 山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, ' 他们的族 长 是以弗、以示、以列、亚斯列、耶利米、何达威雅、雅叠,都是大能的 勇 士,是有名的 人,也是作族 长的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, '他们得罪了 他们列祖的 神,随从 那地 之民 的神 行邪淫;这民就是 神 在他们面前 所除灭的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, '故此,以色列的 神 激动 亚述 王 普勒 和 亚述 王提革拉.毘列色 的心,他们就把流便人、迦得人、玛拿西 半 支派 的人掳 到 哈腊、哈博、哈拉 与歌散 河边,直到 今 日还在那里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, '利未 的儿子 是革顺、哥辖、米拉利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, '哥辖 的儿子 是暗兰、以斯哈、希伯伦、乌薛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, '暗兰 的儿子 是亚伦、摩西,还有女儿米利暗。亚伦 的儿子 是拿答、亚比户、以利亚撒、以他玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, '以利亚撒 生 非尼哈;非尼哈 生 亚比书; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, '亚比书 生 布基;布基 生 乌西; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, '乌西 生 西拉希雅;西拉希雅 生 米拉约; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, '米拉约 生 亚玛利雅;亚玛利雅 生 亚希突; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, '亚希突 生 撒督;撒督 生 亚希玛斯; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, '亚希玛斯 生 亚撒利雅;亚撒利雅 生 约哈难; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, '约哈难 生 亚撒利雅(这亚撒利雅 在所罗门 于 耶路撒冷 所 建造 的殿中, 供祭司的职分); ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, '亚撒利雅 生 亚玛利雅;亚玛利雅 生 亚希突; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, '亚希突 生 撒督;撒督 生 沙龙; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, '沙龙 生 希勒家;希勒家 生 亚撒利雅; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, '亚撒利雅 生 西莱雅;西莱雅 生 约萨答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, '当耶和华 藉 借尼布甲尼撒 的手 掳掠 犹大 和耶路撒冷人的时候,这约萨答 也被掳去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, '利未 的儿子 是革顺、哥辖、米拉利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, ' 革顺 的儿子 名 叫立尼、示每。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, '哥辖 的儿子 是暗兰、以斯哈、希伯伦、乌薛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, '米拉利 的儿子 是抹利、母示。这 是按著利未人 宗族 分的各家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, '革顺 的儿子 是立尼;立尼的儿子 是雅哈;雅哈的儿子 是薪玛; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, '薪玛的儿子 是约亚;约亚的儿子 是易多;易多的儿子 是谢拉;谢拉的儿子 是耶特赖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, '哥辖 的儿子 是亚米拿达;亚米拿达的儿子 是可拉;可拉的儿子 是亚惜; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, '亚惜的儿子 是以利加拿;以利加拿的儿子 是以比雅撒;以比雅撒的儿子 是亚惜; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, '亚惜的儿子 是他哈;他哈的儿子 是乌列;乌列的儿子 是乌西雅;乌西雅的儿子 是少罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, '以利加拿 的儿子 是亚玛赛 和亚希摩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, '亚希摩的儿子 是以利加拿;以利加拿 的儿子 是琐菲;琐菲的儿子 是拿哈; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, '拿哈的儿子 是以利押;以利押的儿子 是耶罗罕;耶罗罕的儿子 是以利加拿;以利加拿的儿子 是撒母耳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, '撒母耳 的长子是约珥,次子 是亚比亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, '米拉利 的儿子 是抹利;抹利的儿子 是立尼;立尼的儿子 是示每;示每的儿子 是乌撒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, '乌撒的儿子 是示米亚;示米亚的儿子 是哈基雅;哈基雅的儿子 是亚帅雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, '约柜 安设之后, 大卫 派人 在耶和华 殿 中管理 歌唱 的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, '他们就在会 幕 前 当 歌唱 的差,及至 所罗门 在耶路撒冷 建造了 耶和华 的殿,他们便按著班次 供 职。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, '供职 的人和他们的子孙 记在下面:哥辖 的子孙 中有歌唱的 希幔。希幔是约珥 的儿子;约珥是撒母耳 的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, '撒母耳是以利加拿 的儿子;以利加拿是耶罗罕 的儿子;耶罗罕是以列 的儿子;以列是陀亚 的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, '陀亚是苏弗 的儿子;苏弗是以利加拿 的儿子;以利加拿是玛哈 的儿子;玛哈是亚玛赛 的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, '亚玛赛是以利加拿 的儿子;以利加拿是约珥 的儿子;约珥是亚撒利雅 的儿子;亚撒利雅是西番雅 的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, '西番雅是他哈 的儿子;他哈是亚惜 的儿子;亚惜是以比雅撒 的儿子;以比雅撒是可拉 的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, '可拉是以斯哈 的儿子;以斯哈是哥辖 的儿子;哥辖是利未 的儿子;利未是以色列 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, '希幔的族兄 亚萨 是比利家 的儿子,亚萨 在 希幔右边 供职。比利家是示米亚 的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, '示米亚是米迦勒 的儿子;米迦勒是巴西雅 的儿子;巴西雅是玛基雅 的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, '玛基雅是伊特尼 的儿子;伊特尼是谢拉 的儿子;谢拉是亚大雅 的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, '亚大雅是以探 的儿子;以探是薪玛 的儿子;薪玛是示每 的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, '示每是雅哈 的儿子;雅哈是革顺 的儿子。革顺是利未 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, '他们的族弟兄 米拉利 的子孙,在 他们左边 供职的有以探。以探是基示 的儿子;基示是亚伯底 的儿子;亚伯底是玛鹿 的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, '玛鹿是哈沙比雅 的儿子;哈沙比雅是亚玛谢 的儿子;亚玛谢是希勒家 的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, '希勒家是暗西 的儿子;暗西是巴尼 的儿子;巴尼是沙麦 的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, '沙麦是末力 的儿子;末力是母示 的儿子;母示是米拉利 的儿子;米拉利是利未 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, '他们的族弟兄 利未人 也被派办 神 殿 中的一切 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, '亚伦 和他的子孙 在 燔祭 坛 和 香 坛 上献祭烧香,又在至 圣所 办理一切的 事,为 以色列 人赎罪,是照 神 仆人 摩西 所 吩咐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, '亚伦 的儿子 是 以利亚撒;以利亚撒的儿子 是非尼哈;非尼哈的儿子 是亚比书; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, '亚比书的儿子 是布基;布基的儿子 是乌西;乌西的儿子 是西拉希雅; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, '西拉希雅的儿子 是米拉约;米拉约的儿子 是亚玛利雅;亚玛利雅的儿子 是亚希突; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, '亚希突的儿子 是撒督;撒督的儿子 是亚希玛斯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, '他们的住处 按著境内 的营寨,记在下面:哥辖 族 亚伦 的子孙 先 拈 阄得地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, '在犹大 地 中得了 希伯仑  和 四围 的郊野; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, '只是 属城 的田地 和 村庄 都为耶孚尼 的儿子 迦勒 所得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, '亚伦 的子孙 得了 逃城 希伯仑 ,又得了 立拿 与 其郊野, 雅提珥、 以实提莫 与 其郊野; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, ' 希仑  与 其郊野, 底璧 与 其郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, ' 亚珊 与 其郊野,伯‧示麦 与 其郊野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, '在便雅悯 支派的地中,得了 迦巴 与 其郊野, 阿勒篾 与 其郊野, 亚拿突 与 其郊野。他们诸家 所得的城 共 十 三 座。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, '哥辖 族 其余 馀的 人又拈阄,在 玛拿西 半 支派 的地中得了十 座城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, '革顺 族 按著宗族,在以萨迦 支派的地中,亚设 支派的地中,拿弗他利 支派的地中,巴珊 内玛拿西 支派的地中,得了十 三 座城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, '米拉利 族 按著宗族 拈阄,在流便 支派的地中,迦得 支派的地中,西布伦 支派的地中,得了十 二 座城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, '以色列 人 将 这些城 与 其郊野 给了 利未人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, ' 这以上 录 名 的 城,在犹大、西缅、便雅悯 三支派的地中,以色列人 拈阄 给了他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, '哥辖 族 中有几家 在以法莲 支派 的地 中也得了 城邑, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, '在以法莲 山地 得了 逃 城 示剑 与 其郊野,又得了 基色 与 其郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, ' 约缅 与 其郊野,伯‧和仑  与 其郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, ' 亚雅仑  与 其郊野,迦特‧临门 与 其郊野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, '哥辖 族 其余 馀的人 在玛拿西 半 支派的地中得了 亚乃 与 其郊野, 比连 与 其郊野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, '革顺 族 在玛拿西 半 支派的地中得了 巴珊 的哥兰 与 其郊野, 亚斯他录 与 其郊野; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, '又在以萨迦 支派的地中得了 基低斯 与 其郊野, 大比拉 与 其郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, ' 拉末 与 其郊野, 亚年 与 其郊野; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, '在亚设 支派的地中得了 玛沙 与 其郊野, 押顿 与 其郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, ' 户割 与 其郊野, 利合 与 其郊野; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, '在拿弗他利 支派的地中得了 加利利 的基低斯 与 其郊野, 哈们 与 其郊野, 基列亭 与 其郊野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, '还有米拉利 族 的人在西布伦 支派的地中得了 临摩挪 与 其郊野, 他泊 与 其郊野; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, '又 在耶利哥 的约旦河 东,在流便 支派的地中得了 旷野 的比悉 与 其郊野, 雅哈撒 与 其郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, ' 基底莫 与 其郊野, 米法押 与 其郊野; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, '又在迦得 支派的地中得了 基列 的拉末 与 其郊野, 玛哈念 与 其郊野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, ' 希实本 与 其郊野, 雅谢 与 其郊野。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, '以萨迦 的儿子 是陀拉、普瓦、雅述(在创世记四十六章十三节是约伯)、伸仑 ,共四人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, '陀拉 的儿子 是乌西、利法雅、耶勒、雅买 、易伯散、示母利,都是陀拉的族 长,是大能的 勇士。到大卫 年间, 他们的人数 共有二万二千 六 百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, '乌西 的儿子 是伊斯拉希;伊斯拉希 的儿子 是米迦勒、俄巴底亚、约珥、伊示雅,共五人,都是 族长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, '他们所率领的,按著宗族 出战  的军 队,共有三 万六 千人,因为 他们的妻 和子 众多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, '他们的族弟兄 在以萨迦 各 族 中都是大能的 勇士,按著家谱 计算共有 八 万七 千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, '便雅悯 的儿子是比拉、比结、耶叠,共三人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, '比拉 的儿子 是以斯本、乌西、乌薛、耶利摩、以利,共五人,都是族 长,是大能的 勇士。按著家谱计算,他们的子孙 共有二 万二 千 零三十 四人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, '比结 的儿子 是细米拉、约阿施、以利以谢、以利约乃、暗利、耶利摩、亚比雅、亚拿突、亚拉篾。这 都是 比结 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, '他们都是族 长,是大能的 勇士。按著家谱 计算,他们的子孙 共有二万 零二百人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, '耶叠 的儿子 是比勒罕;比勒罕 的儿子 是耶乌施、便雅悯、以忽、基拿拿、细坦、他施、亚希沙哈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, '这 都是 耶叠 的儿子,都是族 长,是大能的 勇士;他们的子孙 能上 阵 打仗的,共有一 万七 千 二百人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, '还有以珥 的儿子 书品、户品,并亚黑 的儿子 户伸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, '拿弗他利 的儿子 是雅薛、沽尼、耶色、沙龙。这都是辟拉 的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, '玛拿西 的儿子 亚斯列 是他妾 亚兰人 所 生的,又生了 基列 之父 玛吉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, '玛吉 娶 的妻 是户品、书品 的妹子,名 叫玛迦。玛拿西的次子 名 叫西罗非哈;西罗非哈 但有几个女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, '玛吉 的妻 玛迦 生了 一个儿子,起 名 叫毘利施。毘利施的兄弟 名叫 示利施;示利施的儿子 是乌兰 和利金。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, '乌兰 的儿子 是比但。这 都是基列 的子孙。基列是玛吉 的儿子,玛吉是玛拿西 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, '基列的妹子 哈摩利吉 生了 伊施荷、 亚比以谢、 玛拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, '〈示米大 的儿子 是 亚现、示剑、利克希、阿尼安。〉 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, '以法莲 的儿子 是书提拉;书提拉的儿子 是比列;比列的儿子 是他哈;他哈的儿子 是以拉大;以拉大的儿子 是他哈; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, '他哈的儿子 是撒拔;撒拔的儿子 是书提拉。以法莲又生以谢、以列;这二人因为 下去 夺取 迦特人的牲畜,被本地 的 迦特 人 杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, '他们的父亲 以法莲 为他们悲哀了 多 日,他的弟兄 都来 安慰他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, '以法莲与 妻 同房,他妻就怀孕 生了 一子,以法莲因为 家里 遭 祸,就给这儿子起 名 叫比利亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, '他的女儿 名叫舍伊拉,就是建筑 上伯‧和仑 、 下伯‧和仑 与乌羡‧舍伊拉的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, '比利亚的儿子 是利法 和利悉。利悉的儿子 是他拉;他拉的儿子 是他罕; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, '他罕的儿子 是拉但;拉但的儿子 是亚米忽;亚米忽的儿子 是以利沙玛; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, '以利沙玛的儿子 是嫩;嫩的儿子 是约书亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, '以法莲人的地业 和住处 是伯特利 与其村庄;东边 拿兰,西边 基色 与其村庄;示剑 与其村庄,直到 迦萨 与其村庄; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, '还有靠近 玛拿西 人 的境界,伯‧善 与其村庄;他纳 与其村庄;米吉多 与其村庄;多珥 与其村庄。以色列 儿子 约瑟 的子孙 住 在这些地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, '亚设 的儿子 是音拿、亦施瓦、亦施韦、比利亚,还有他们的妹子 西拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, '比利亚 的儿子 是希别、玛结;玛结 是比撒威 的父亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, '希别 生 雅弗勒、 朔默、 何坦,和 他们的妹子 书雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, '雅弗勒 的儿子 是巴萨、宾哈、亚施法。这 都是雅弗勒 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, '朔默 的儿子 是亚希、罗迦、耶户巴、亚兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, '朔默兄弟 希连 的儿子 是琐法、音那、示利斯、亚抹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, '琐法 的儿子 是书亚、哈尼弗、书阿勒、比利、音拉、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, '比悉、河得、珊玛、施沙、益兰、比拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, '益帖 的儿子 是耶孚尼、毘斯巴、亚拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, '乌拉 的儿子 是亚拉、汉尼业、利写。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, '这 都是 亚设 的子孙,都是族 长,是精壮 大能的 勇士,也是首领 中的头目,按著家谱 计算,他们的子孙 能出 战  的共有二 万六 千 人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, '便雅悯 的长子 比拉,次子 亚实别,三 子亚哈拉, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, '四 子挪哈,五 子拉法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, '比拉 的儿子 是 亚大、基拉、亚比忽、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, '亚比书、乃幔、亚何亚、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, '基拉、示孚汛、户兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, ' 以忽 的儿子 作迦巴 居民 的族 长,被掳 到 玛拿辖; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, '以忽 的儿子乃幔、亚希亚、基拉 也被掳去。基拉生 乌撒、 亚希忽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, '沙哈连 休 他 二妻 户伸 和 巴拉 之后,在摩押 地 生了儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, '他与 妻 贺得同房,生了 约巴、 洗比雅、 米沙、 玛拉干、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, ' 耶乌斯、 沙迦、 米玛。他这些 儿子 都是族 长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, '他的妻户伸 给他生的儿子有 亚比突、 以利巴力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, '以利巴力 的儿子 是希伯、米珊、沙麦。沙麦 建立 阿挪 和 罗德 二城与其村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, '又有比利亚 和示玛 是 亚雅仑  居民 的族 长,是 驱逐 迦特 人的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, '亚希约、沙煞、耶利末、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, '西巴第雅、亚拉得、亚得、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, '米迦勒、伊施巴、约哈 都是比利亚 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, '西巴第雅、米书兰、希西基、希伯、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, '伊施米莱、伊斯利亚、约巴 都是以利巴力 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, '雅金、细基利、撒底、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, '以利乃、洗勒太、以列、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, '亚大雅、比拉雅、申拉 都是示每 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, '伊施班、希伯、以列、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, '亚伯顿、细基利、哈难、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, '哈拿尼雅、以拦、安陀提雅、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, '伊弗底雅、毘努伊勒 都是沙煞 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, '珊示莱、示哈利、亚他利雅、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, '雅利西、以利亚、细基利 都是耶罗罕 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, '这些人都是著名的 族 长, 住 在耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, '在基遍 住 的有基遍 的父亲 耶利。他的妻 名叫 玛迦; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, '他 长子 是亚伯顿。他又生苏珥、基士、巴力、拿答、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, '基多、亚希约、撒迦、米基罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, '米基罗 生 示米暗。 这些人 和 他们的弟兄 在耶路撒冷 对面 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, '尼珥 生 基士;基士 生 扫罗;扫罗 生 约拿单、 麦基舒亚、 亚比拿达、伊施‧巴力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, '约拿单 的儿子是米力‧巴力(在撒母耳下四章四节是米非波设);米力‧巴力 生 米迦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, '米迦 的儿子 是毘敦、米勒、他利亚、亚哈斯; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, '亚哈斯 生 耶何阿达;耶何阿达 生 亚拉篾、 亚斯玛威、 心利;心利 生 摩撒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, '摩撒 生 比尼亚;比尼亚的儿子 是拉法;拉法的儿子 是以利亚萨;以利亚萨的儿子 是亚悉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, '亚悉 有六个 儿子, 他们的名字 是亚斯利干、波基路、以实玛利、示亚利雅、俄巴底雅、哈难。这 都是 亚悉 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, '亚悉兄弟 以设 的 长子 是乌兰,次子 耶乌施,三 子是以利法列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, '乌兰 的儿子 都是 大能的 勇 士,是弓箭 手,他们有许多的 子 孙,共一百 五十名, 都是 便雅悯 人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, '以色列人 都 按家谱计算, 写 在 以色列 诸王 记上。犹大人 因犯罪 就被掳 到巴比伦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, '先从巴比伦回来,住 在自己地业 城邑 中的有 以色列人、祭司、利未人、尼提宁的首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, '住 在耶路撒冷 的有 犹大 人、 便雅悯 人、 以法莲 人、玛拿西人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, '犹大 儿子 法勒斯 的子孙中有乌太。乌太 是亚米忽 的儿子;亚米忽是暗利 的儿子;暗利是音利 的儿子;音利是巴尼 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, '示罗 的子孙中 有长子 亚帅雅 和他的众子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, '谢拉 的子孙 中 有耶乌利 和他的弟兄,共六 百 九十人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, '便雅悯 人 中 有哈西努 的曾孙、何达威雅 的孙子、米书兰 的儿子 撒路, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, '又有耶罗罕 的儿子 伊比尼雅,米基立 的孙子、乌西 的儿子 以拉,伊比尼雅 的曾孙、流珥 的孙子、示法提雅 的儿子 米书兰, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, '和他们的族弟兄,按著家谱 计算共有九 百 五十 六名。这些 人 都是他们 的族 长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, '祭司 中 有耶大雅、耶何雅立、雅斤, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, '还有管理 神 殿 希勒家 的儿子 亚萨利雅。希勒家是米书兰 的儿子;米书兰是撒督 的儿子;撒督是米拉约 的儿子;米拉约是亚希突 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, '有玛基雅 的曾孙、巴施户珥 的孙子、耶罗罕 的儿子 亚大雅,又有亚第业 的儿子 玛赛;亚第业是雅希细拉 的儿子;雅希细拉是米书兰 的儿子;米书兰是米实利密 的儿子;米实利密是音麦 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, '他们和众弟兄都是族 长,共有一千 七 百 六十人,是善于 做 神 殿 使用 之工的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, ' 利未人 米拉利 的子孙 中,有哈沙比雅 的曾孙、押利甘 的孙子、哈述 的儿子 示玛雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, '有拔巴甲、黑勒施、迦拉,并亚萨 的曾孙、细基利 的孙子、米迦 的儿子 玛探雅, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, '又有耶杜顿 的曾孙、迦拉 的孙子、示玛雅 的儿子 俄巴底,还有以利加拿 的孙子、亚撒 的儿子 比利家。他们都住 在尼陀法人 的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, '守门的 是沙龙、亚谷、达们、亚希幔,和他们的弟兄;沙龙 为长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, ' 从前这些人 看守朝东的 王 门,如今是 利未 营中 守门的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, '可拉 的曾孙、以比雅撒 的孙子、可利 的儿子 沙龙,和他的族 弟兄 可拉人 都管理 使用 之工,并守 会幕 的门。他们的祖宗 曾管理 耶和华 的营盘,又把守 营门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, '从前 以利亚撒 的儿子 非尼哈 管理 他们,耶和华 也与他同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, '米施利米雅 的儿子 撒迦利雅 是看守 会 幕 之门的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, '被选 守 门 的人共有 二百 一十 二名。他们 在自己的村庄,按著家谱计算, 是大卫 和先见 撒母耳 所派 当这紧要职任的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, '他们 和他们的子孙 按著班次 看守 耶和华 殿 的门,就是 会幕的门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, '在东 西 南 北,四 方 都有 守门的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, '他们的族弟兄 住在村庄,每七 日 来 与 他们 换 班。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, ' 这四个 门 领 都是 利未人,各有 紧要的职任, 看守 神 殿 的 仓库。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, '他们住在 神 殿 的四围,是因 委托 讬他们 守殿, 要每日 早晨 开 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, '利未人中 有管理 使用 器皿的,按著 数目 拿出 拿入; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, '又有人 管理 器具 和 圣所的 器皿,并 细面 麺、酒、油、乳香、香料。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, '祭司 中 有人 用香料 做 膏油。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, '利未人 玛他提雅 是 可拉族 沙龙 的长子,他紧要的职任 是管理 盘 中烤的物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, '他们族弟兄 哥辖 子孙 中,有管理 陈设 饼的,每 安息日 预备摆列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, ' 歌唱的 有利未人的 族 长,住在属殿的房屋, 昼 夜 供 职,不做别样的工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, '以上 都是利未人著名的 族 长,住 在耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, '在基遍 住 的有基遍 的父亲 耶利。他的妻 名叫 玛迦; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, '他长 子 是亚伯顿。他又生苏珥、基士、巴力、尼珥、拿答、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, '基多、亚希约、撒迦利雅、米基罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, '米基罗 生 示米暗。 这些人 和 他们的弟兄 在耶路撒冷 对面 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, '尼珥 生 基士;基士 生 扫罗;扫罗 生 约拿单、 麦基舒亚、 亚比拿达、伊施‧巴力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, '约拿单 的儿子是米力‧巴力(就是米非波设);米力‧巴力 生 米迦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, '米迦 的儿子 是毘敦、米勒、他利亚、亚哈斯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, '亚哈斯 生 雅拉;雅拉 生 亚拉篾、 亚斯玛威、 心利;心利 生 摩撒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, '摩撒 生 比尼亚;比尼亚生 利法雅;利法雅的儿子 是以利亚萨;以利亚萨的儿子 是亚悉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, '亚悉 有六个 儿子,他们的名字 是 亚斯利干、波基路、以实玛利、示亚利雅、俄巴底雅、哈难。这 都是亚悉 的儿子。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, '非利士人 与以色列人 争战 ,以色列 人 在非利士人 面前 逃跑,在基利波 山 有被杀 仆倒的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, '非利士人 紧 追 扫罗 和 他儿子们, 就杀了 扫罗 的儿子 约拿单、 亚比拿达、 麦基舒亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, '势派 甚大,扫罗 被弓箭 手 追 上, 射 伤甚重, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, ' 就吩咐 拿 他兵器 的人说:「你拔出 刀来,将我刺死,免得 那些 未受割礼的人 来 凌辱 我。」但拿 兵器的人 甚 惧怕,不 肯刺他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, '扫罗 就 自己伏 在 刀上死了。拿 兵器 的人见 扫罗 已死, 也 伏 在 刀上 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, '这样,扫罗 和他三个 儿子,并他的全 家 都一同 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, '住平原 的 以色列 众 人 见 以色列军兵逃跑, 扫罗 和他儿子 都死了,也就弃 城 逃跑,非利士人 便来 住 在其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, ' 次日,非利士人 来 剥 那被杀之人的衣服,看见 扫罗 和 他儿子 仆倒 在基利波 山, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, '就剥了 他的军装,割下 他的首级,打发人到(到:或译送到)非利士 地 的四境 报信 与 他们的偶像 和 众民, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, '又将 扫罗的军装 放 在他们神 的庙里,将 他的首级 钉 在大衮 庙中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, ' 基列‧雅比人 听见 非利士人 向扫罗 所 行 的一切事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, '他们中间所有的 勇 士 就起身前去, 将 扫罗 和 他儿子 的尸身 送到 雅比,将 他们的尸骨 葬 在雅比 的橡树 下,就禁食 七 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, '这样,扫罗 死了。因为 他干犯 耶和华, 没有 遵守 耶和华 的命;又 因他求 问 交鬼的妇人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, '没有 求问 耶和华,所以耶和华使他被杀,把 国 归于  耶西 的儿子 大卫。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, '以色列 众人 聚集 到希伯仑  见 大卫,说:「 我们 原是你的骨 肉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, ' 从前 扫罗 作 王的时候,率领 以色列人 出 入 的是你;耶和华─你的 神 也曾应许你 说:『你 必牧养 我的民 以色列, 作 以色列 的君。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, '于 是以色列 的长老 都 来 到希伯仑  见 大卫王。大卫 在希伯仑  耶和华 面前 与他们 立 约,他们就膏 大卫 作 以色列 的王,是照耶和华 藉 借 撒母耳 所说的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, '大卫 和以色列 众人 到了 耶路撒冷,就是 耶布斯;那时耶布斯人 住 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, '耶布斯 人 对大卫 说:「你决不能 进 这地方。」然而大卫 攻取 锡安 的保障,就是 大卫 的城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, '大卫 说:「谁 先 攻打 耶布斯人,必作 首领 元帅。」洗鲁雅 的儿子 约押 先 上去,就作了 元帅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, '大卫 住 在保障里,所 以 那保障 叫作 大卫 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, '大卫又从 米罗起,四围 建筑 城墙, 其余 馀的 是约押 修理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, '大卫 日 见 强盛,因为万军 之耶和华 与他同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, '以 下记录跟随 大卫 勇士 的首领,就是奋勇 帮助他 得国、照著耶和华 吩咐 以色列人 的话、与 以色列人 一同立他作王的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, ' 大卫 勇士 的数目 记在下面:哈革摩尼 的儿子 雅朔班,他是 军长 的统领,一 时 举 枪 杀了 三 百 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, '其次 是亚合人 朵多 的儿子 以利亚撒,他 是三个 勇士里的一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, '他 从前 与 大卫在巴斯‧达闵,非利士人 聚集 要打仗。那里有 一块 长满 大麦 的田,众民 就在非利士人 面前 逃跑; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, '这勇士便站 在那田 间 击杀 非利士人,救护了那田。耶和华 使以色列人大 获全胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, '三十 个勇士 中 的三 个人下 到 磐石那里,进了 亚杜兰 洞 见 大卫;非利士 的军队 在利乏音 谷 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, '那时 大卫 在山寨,非利士人 的防营 在伯利恒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, '大卫 渴想,说:「甚愿 有人 将 伯利恒 城门 旁井 里的水 打来给我喝!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, '这三个 勇士就闯过 非利士人 的营盘,从 伯利恒 城门 旁的井 里打 水,拿来 奉 给 大卫。他 却不 肯 喝,将水 奠 在耶和华面前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, '说:「我的 神啊,这 三个人 冒死 去打水,这水好像他们的血一般,我 断不敢 喝!」如此,大卫不 肯 喝。这 是三个 勇士 所做的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, '约押 的兄弟 亚比筛 是 这三个 勇士的首领;他 举 枪 杀了 三 百 人,就在三个 勇士里得了名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, '他在这三个 勇士里 是最尊贵的,所以作 他们 的首领;只是不 及 前三个勇士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, '有 甲薛 勇 士 耶何耶大 的儿子 比拿雅 行过大能 的事:他 杀了 摩押人 亚利伊勒 的两个 儿子,又 在下雪 的时候 下 坑 里 去杀了 一个狮子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, '又 杀了 一个埃及 人。埃及 人 身高 五 肘,手 里拿著枪,枪杆粗如织布 的机轴;比拿雅只拿著棍子 下 去,从埃及人 手 里夺过 枪来,用那枪 将他刺死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, '这 是耶何耶大 的儿子 比拿雅 所行的事,就在三个 勇士 里得了名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, ' 他 比 那三十 个勇士都尊贵,只是不 及 前三个勇士。大卫 立他 作 护卫长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, '军中 的勇士 有约押 的兄弟 亚撒黑,伯利恒人 朵多 的儿子 伊勒哈难, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, '哈律人 沙玛,比伦人 希利斯, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, '提哥亚人 益吉 的儿子 以拉,亚拿突人 亚比以谢, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, '户沙人 西比该,亚合人 以来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, '尼陀法人 玛哈莱,尼陀法人 巴拿 的儿子 希立, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, '便雅悯 族 基比亚人 利拜 的儿子 以太,比拉顿人 比拿雅, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, '迦实 溪人 户莱,亚拉巴人 亚比, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, '巴路米人 押斯玛弗,沙本人 以利雅哈巴, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, '基孙人 哈深 的众子,哈拉人 沙基 的儿子 约拿单, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, '哈拉人 沙甲 的儿子 亚希暗,吾珥 的儿子 以利法勒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, '米基拉人 希弗,比伦人 亚希雅, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, '迦密人 希斯罗,伊斯拜 的儿子 拿莱, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, '拿单 的兄弟 约珥,哈基利 的儿子 弥伯哈, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, '亚扪人 洗勒,比录人 拿哈莱〈拿哈莱 是给洗鲁雅的儿子 约押 拿 兵器的〉, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, '以帖人 以拉,以帖人 迦立, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, '赫人 乌利亚,亚莱 的儿子 撒拔, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, '流便人 示撒 的儿子 亚第拿〈他是流便支派中的 一个族长,率领 三十人〉, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, '玛迦 的儿子 哈难,弥特尼人 约沙法, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, '亚施他拉人 乌西亚,亚罗珥人 何坦 的儿子 沙玛、耶利, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, '提洗人 申利 的儿子 耶叠 和他的兄弟 约哈, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, '玛哈未人 以利业,伊利拿安 的儿子 耶利拜、约沙未雅,摩押人 伊特玛、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, '以利业、俄备得,并米琐八人 雅西业。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, '大卫 因 怕基士 的儿子 扫罗, 躲 在洗革拉的时候,有 勇士 到 他那里 帮助 他打仗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, '他们善于  拉弓,能用左 右 两手甩石 射箭,都是便雅悯人 扫罗 的族弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, '为首的 是亚希以谢,其次是约阿施,都是基比亚人 示玛 的儿子。还有亚斯玛威 的儿子 耶薛 和毘力,又有比拉迦,并亚拿突人 耶户, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, '基遍人 以实买 雅〈他在三十人中 是勇士,管理 他们〉,且有耶利米、雅哈悉、约哈难,和基得拉人 约撒拔、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, '伊利乌赛、耶利摩、比亚利雅、示玛利雅,哈律弗人 示法提雅, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, '可拉人 以利加拿、耶西亚、亚萨列、约以谢、雅朔班, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, '基多人 耶罗罕 的儿子 犹拉 和西巴第雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, '迦得支派 中 有人到旷野 的山寨 投奔 大卫,都是大能 的勇士,能拿 盾牌 和枪 的战  士。他们的面貌 好像狮子,快跑 如同山 上 的鹿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, '第一 以薛,第二 俄巴底雅,第三 以利押, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, '第四 弥施玛拿,第五 耶利米, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, '第六 亚太,第七 以利业, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, '第八 约哈难,第九 以利萨巴, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, '第十 耶利米,第十 一 末巴奈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, '这 都是迦得 人 中的军 长, 至小的 能抵一百人,至大的 能抵一千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, '正 月,约旦河 水涨 过 两 岸的时候, 他们 过 河,使 一切 住平原 的人东 奔西 逃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, '又有 便雅悯 和犹大 人 到 山寨 大卫那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, '大卫 出去 迎接他们, 对他们 说:「你们若 是和和平平地 来 帮助 我, 我心 就与你们 相契;你们若 是将我这无 罪 的人卖 在敌人手里,愿 我们列祖的 神 察看 责罚。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, '那时 神的灵 感动 那三十 个勇士的首领 亚玛撒,他就说:大卫啊,我们是归于 你的!耶西 的儿子啊,我们是帮助你的!愿 你 平平 安安,愿 帮助你的 也都平安!因为你的 神 帮助你。大卫 就收留他们,立他们 作军 长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, '大卫从前与 非利士人 同去,要与 扫罗 争战 ,有些玛拿西人 来投奔 大卫,他们却没有 帮助非利士人;因为 非利士人 的首领 商议,打发他们回去,说:「恐怕大卫拿我们的首级,归 降 他的主人 扫罗。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, '大卫往 洗革拉 去的时候,有玛拿西人 的 千夫 长 押拿、约撒拔、耶叠、米迦勒、约撒拔、以利户、洗勒太 都来投奔 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, '这些人 帮助 大卫 攻击 群贼; 他们都是 大能 的勇士,且作 军 长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, ' 那时 天 天 有人来 帮助 大卫,以致 成了大 军,如 神 的军一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, '预备 打仗 的兵 来 到希伯仑  见 大卫,要照著耶和华 的话 将扫罗 的国位 归与 大卫。他们的数目 如下: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, '犹大 支派,拿 盾牌 和枪 预备 打仗 的有六 千 八 百人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, '西缅 支派,能上阵 大能 的勇士 有七 千 一百人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, '利未 支派 有四 千 六 百人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, '耶何耶大 是亚伦 家的首领,跟从他 的有三 千 七 百人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, '还有少年 大能 的勇士 撒督,同著他的有族 长 二十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, '便雅悯 支派,扫罗 的族弟兄 也有三 千人,他们向来 大半 归 顺 扫罗 家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, '以法莲 支派 大能 的勇士,在本 族 著名 的 有二万 零八 百人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, '玛拿西 半 支派, 册上有 名 的共一万八 千人,都来 立 大卫 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, '以萨迦 支派,有二百 族长 都通达 时务,知道 以色列人 所当 行的;他们族弟兄 都 听从 他们的命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, '西布伦支派,能上 阵 用各样 兵 器 打仗、行伍整齐、不 生 二心 的有五万人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, '拿弗他利支派,有一千 军长;跟从他们、拿盾牌 和枪 的有三万七千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, '但 支派,能摆 阵 的有二 万八 千 六 百人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, '亚设支派,能上 阵 打 仗 的有四万人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, '约旦河 东的 流便支派、迦得支派、玛拿西 半 支派,拿著各样 兵 器 打仗 的有十二万人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, '以上 都 是能守 行伍 的战  士,他们都诚 心 来 到希伯仑 ,要立 大卫 作 以色列 的王。以色列 其余 馀的人 也 都 一 心 要立 大卫 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, ' 他们在那里 三 日,与 大卫 一同吃 喝,因为 他们的族弟兄 给他们 预备了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, ' 靠近 他们的人以及 以萨迦、西布伦、拿弗他利人 将许多面 麺饼、无花果饼、干葡萄、酒、油,用驴、骆驼、骡子、牛 驮来,又带了许多 的牛 和羊来,因为 以色列 人甚是欢乐。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, '大卫 与 千夫 长、百夫长,就是一切 首领 商议。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, '大卫 对以色列 全 会众 说:「你们 若 以为美,见这事是出于  耶和华─我们的 神,我们就差遣人 走 遍 以色列 地,见 我们未来的 弟兄,又 见住 在有郊野 之城 的祭司 利未人,使他们都到 这里来聚集。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, '我们要把 神 的约柜 运 到我们这里来;因为 在扫罗 年间,我们没有 在约柜前求问 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, '全 会众 都说 可以如此 行; 这事 在众 民 眼中 都看为好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, '于 是,大卫 将 以色列人 从 埃及 的西曷河 直到 哈马 口 都 招聚了来,要从基列耶琳 将 神 的约柜 运来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, '大卫 率领以色列 众人 上 到巴拉,就是 属犹大的基列‧耶琳,要从那里 将 约柜 运来。这约柜就是坐 在二基路伯 上耶和华 神 留 名的约柜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, '他们将 神 的约柜 从亚比拿达 的家 里抬出来,放在 新 车上。乌撒 和亚希约 赶 车。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, '大卫 和以色列 众人在 神 前 用琴、瑟、锣、鼓、号作乐,极 力 跳舞 歌唱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, '到了 基顿(在撒母耳下六章六节是拿艮)的禾场;因为 牛失前蹄(或译:惊跳),乌撒 就伸 手 扶住 约柜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, '耶和华 向他 发 怒,因 他 伸 手 扶住 约柜 击杀他,他就死在 神 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, '大卫 因 耶和华击杀(原文是闯杀)乌撒,心里愁烦,就称 那 地方为毘列斯‧乌撒,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, '那 日,大卫 惧怕 神,说:「 神 的约柜 怎 可运 到我这里来?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, '于 是大卫 不 将 约柜 运 进 大卫 的城,却运 到 迦特人俄别‧以东 的家中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, '神 的约柜 在俄别‧以东 家中 三个 月,耶和华 赐福 给俄别‧以东 的家 和 他 一切 所有的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, '泰尔 王 希兰 将香 柏木 运到大卫那里,又差遣 使者 和石匠、木匠 给 大卫 建造 宫殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, '大卫 就知道 耶和华 坚立他 作 以色列 王,又为 自己的民 以色列, 使他的国 兴 旺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, '大卫 在耶路撒冷 又 立 后妃, 又 生 儿 女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, '在耶路撒冷 所 生的众子 是沙母亚、朔罢、拿单、所罗门、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, '益辖、以利书亚、以法列、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, '挪迦、尼斐、雅非亚、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, '以利沙玛、比利雅大、以利法列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, '非利士人 听见 大卫 受膏 作 以色列 众人 的王,非利士 众人 就上来 寻索 大卫。大卫 听见,就出去 迎敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, '非利士人 来了,布散 在利乏音 谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, '大卫 求问 神,说:「我可以上去 攻打 非利士人吗?你将他们交 在我手里吗?」耶和华 说:「你可以上去,我必将他们交 在你手里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, '非利士人来到巴力‧毘拉心,大卫 在那里 杀败他们。大卫 说:「 神 藉 借我的手 冲破 敌人,如同水 冲去一般」;因 此 称 那 地方为巴力‧毘拉心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, '非利士人将 神像 撇 在那里,大卫 吩咐 人用火 焚烧了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, '非利士人 又 布散 在利乏音谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, '大卫 又 求问 神。 神 说:「不要 一直地 上去,要转 到 他们后头,从桑林 对面 攻打 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, ' 你听见 桑树 梢上 有脚步 的声音,就 要出 战 ,因为 神 已经在你前头 去 攻打 非利士人 的军队。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, '大卫 就遵著 神 所 吩咐的,攻打 非利士人 的军队,从基遍 直到 基色。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, '于 是大卫 的名 传扬 到列 国,耶和华 使 列 国都 惧怕他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, '大卫 在大卫 城 为自己 建造 宫殿,又为 神 的约柜 预备 地方,支搭 帐幕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, '那时 大卫 说:「除了 利未人之外,无人 可抬 神 的约柜;因为 耶和华 拣选 他们 抬 神 的约柜,且 永远 事奉他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, '大卫 招聚 以色列 众人 到 耶路撒冷,要将 耶和华 的约柜 抬 到 他所 预备 的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, '大卫 又聚集 亚伦 的子孙 和 利未人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, '哥辖 子孙 中有族长 乌列 和他的弟兄 一百 二十人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, '米拉利 子孙 中有族长 亚帅雅 和他的弟兄 二百 二十人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, '革顺 子孙 中有族长 约珥 和他的弟兄 一百 三十人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, '以利撒反 子孙 中有族长 示玛雅 和他的弟兄 二百人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, '希伯仑  子孙 中有族长 以列 和他的弟兄 八十人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, '乌薛 子孙 中有族长 亚米拿达 和他的弟兄 一百 一十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, '大卫 将祭司 撒督 和亚比亚他,并利未人 乌列、亚帅雅、约珥、示玛雅、以列、亚米拿达 召来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, '对他们 说:「你们 是利未人 的族 长,你们 和你们的弟兄 应当自洁,好将 耶和华─以色列 神 的约柜 抬 到 我所预备的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, '因 你们 先前 没有抬这约柜, 按定例 求问 耶和华─我们的 神,所以他刑罚(原文是闯杀)我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, '于 是祭司 利未人 自洁,好将 耶和华─以色列 神 的约柜 抬上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, '利未 子孙 就用杠,肩 抬 神 的约柜,是照 耶和华 藉 借摩西 所吩咐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, '大卫 吩咐 利未人 的族长,派 他们歌唱 的弟兄 用 琴 瑟 和钹 作乐,欢欢喜喜地 大 声 歌颂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, '于 是利未人 派 约珥 的儿子 希幔 和 他弟兄 中比利家 的儿子 亚萨,并 他们族弟兄 米拉利 子孙 里古沙雅 的儿子 以探。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, '其次 还有 他们的弟兄 撒迦利雅、便‧雅薛、示米拉末、耶歇、乌尼、以利押、比拿雅、玛西雅、玛他提雅、以利斐利户、弥克尼雅,并守门的俄别‧以东 和耶利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, '这样,派歌唱的 希幔、亚萨、以探 敲铜 钹,大发响声; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, '派撒迦利雅、雅薛、示米拉末、耶歇、乌尼、以利押、玛西雅、比拿雅 鼓瑟,调用 女音; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, '又派玛他提雅、以利斐利户、弥克尼雅、俄别‧以东、耶利、亚撒西雅 领首 弹琴,调用 第八。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, '利未人 的族长 基拿尼雅 是歌唱人的首领,又教训人 歌唱,因为 他 精通此事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, '比利家、以利加拿 是约柜 前守门的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, '祭司 示巴尼、约沙法、拿坦业、亚玛赛、撒迦利雅、比拿亚、以利以谢在 神 的约柜 前 吹 号。俄别‧以东 和耶希亚 也是约柜 前守门的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, '于 是,大卫 和以色列 的长老,并千夫 长 都去 从俄别‧以东 的家 欢欢喜喜地 将 耶和华 的约 柜 抬上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, ' 神 赐恩 与 抬 耶和华 约 柜 的利未人,他们就献上 七只 公牛,七只 公羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, '大卫 和抬 约柜的 利未人,并歌唱人 的首领 基拿尼雅,以及歌唱的人,都穿著 细麻布 的外袍;大卫 另外穿著 细麻布 的以弗得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, '这样,以色列 众人 欢呼 吹角、吹号、敲钹、鼓瑟、弹琴,大发响声,将 耶和华 的约 柜 抬上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, ' 耶和华 的约 柜 进了 大卫 城的时候,扫罗 的女儿 米甲 从 窗户 里观看,见 大卫 王 踊跃 跳舞,心里 就轻视 他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, '众人将 神 的约柜 请进去,安放 在大卫 所 搭的 帐幕 里,就在 神 面前 献 燔祭 和平安祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, '大卫 献 完了 燔祭 和平安祭,就奉耶和华 的名 给 民 祝福, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, '并且分 给 以色列 人,无论男 女,每人 一个 饼,一块肉,一个葡萄饼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, '大卫 派 几个 利未人 在耶和华 的约柜 前 事奉,颂扬,称谢,赞美 耶和华─以色列的 神: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, '为首的 是亚萨,其次 是撒迦利雅、雅薛、示米拉末、耶歇、玛他提雅、以利押、比拿雅、俄别‧以东、耶利,鼓 瑟 弹琴;惟有亚萨 敲钹,大发响声; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, '祭司 比拿雅 和雅哈悉 常在 神 的约 柜 前 吹号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, '那 日, 大卫 初次 藉 借 亚萨 和他的弟兄 以诗歌称颂 耶和华,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, '你们要称谢 耶和华,求告 他的名,在万民 中传扬 他的作为! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, '要向他 唱诗、歌颂,谈论 他一切 奇妙的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, '要以他的圣 名 夸耀;寻求 耶和华的人,心 中应当欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, '要寻求 耶和华 与他的能力,时常 寻求 他的面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, '他仆人以色列 的后裔,他所拣选雅各的子孙哪,你们要记念 他奇妙的作为 和他的奇事,并他口中 的判语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, '他 是耶和华─我们的 神,全 地 都有他的判断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, '你们要记念 他的约,直到永远;他所吩咐 的话,直到千 代, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, '就是与 亚伯拉罕 所 立的约,向以撒 所起的誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, '他又将这约向雅各 定 为律例,向以色列 定为永远 的约, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, '说:我必将迦南 地 赐 给你,作你产业 的分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, '当时 你们人丁 有限,数目稀少,并且在那地 为寄居的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, '他们从这邦 游 到 那邦,从这国 行到 那 国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, '耶和华不 容 什么人 欺负他们,为他们的缘故 责备 君王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, '说:不可 难为 我受膏的人,也不可 恶待 我的先知! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, '全 地 都要向耶和华 歌唱!天 天 传扬 他的救恩, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, '在列邦 中述说 他的荣耀,在万 民 中述说他的奇事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, '因 耶和华 为大,当受极大 的赞美;他 在 万 神之上,当受敬畏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, ' 外邦 的神 都 属虚无,惟独耶和华 创造 诸天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, '有尊荣 和威严 在他面前,有能力 和喜乐 在他圣所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, '民 中的万族啊,你们要将荣耀 能力 归给 耶和华,都归给 耶和华! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, '要将耶和华 的名 所当得的荣耀 归给 他,拿 供物 来 奉到他面前;当以圣洁的(的:或译为)妆饰 敬拜 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, '全 地 要在他面前 战 抖,世界 也 坚定 不得 动摇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, '愿 天 欢喜,愿 地 快乐;愿 人在列邦 中说:耶和华 作王了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, '愿 海 和其中所充满的 澎湃;愿 田 和其 中 所有的 都欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, '那时,林 中的树木 都要在耶和华 面前 欢呼,因为 他来 要审判 全地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, '应当称谢 耶和华;因 他本为善, 他的慈爱 永远长存! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, '要说:拯救我们的 神啊,求你救我们,聚集我们,使我们脱离 外邦,我们好称赞 你的圣 名,以赞美你 为夸胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, '耶和华─以色列的 神,从 亘古 直到 永远,是应当称颂的!众 民 都说:「阿们!」并且赞美 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, '大卫 派 亚萨 和他的弟兄 在约 柜 前 常常 事奉 耶和华,一日 尽一日 的职分; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, '又派俄别‧以东 和他的弟兄 六十 八人,与耶杜顿 的儿子俄别‧以东,并何萨 作守门的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, '且派 祭司 撒督 和他弟兄 众祭司 在基遍 的 邱坛、耶和华 的帐幕 前 燔祭 坛 上,每日早 晚,照著耶和华 律法书上 所 吩咐 以色列人的,常 给耶和华 献 燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, '与他们一同 被派的有希幔、耶杜顿,和其余 馀 被选 名字 录在册上的,称谢 耶和华,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, '希幔、耶杜顿 同著他们 吹号、敲钹,大发响声,并用别的乐 器随著歌颂 神。耶杜顿 的子孙 作守门的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, '于 是众 民 各 归 各家;大卫 也回去 为 家眷 祝福。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, ' 大卫 住 在自己宫中, 对 先知 拿单 说:「看哪,我 住 在香柏木 的宫中,耶和华 的约 柜 反在幔子 里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, '拿单 对 大卫 说:「你可以照 你的心意 而行,因为 神 与你同在。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, ' 当 夜, 神 的话 临 到 拿单,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, '「你去 告诉 我仆人 大卫,说 耶和华 如此说:『你 不可 建造 殿宇 给我 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, ' 自从 我领 以色列人出埃及,直到 今 日,我未 曾住 过殿宇,乃 从这会幕 到 那会幕,从这帐幕到那帐幕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, '凡 我同以色列人 所 走的地方,我何曾 向 以色列 的一个 士师,就是 我吩咐 牧养 我民 的说:你为何 不 给我 建造 香柏木 的殿宇呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, '现在 你要告诉 我仆人 大卫,说 万军 之耶和华 如此说:『我 从 羊圈 中将你召来,叫你不再 跟从 羊群,立你作 我民 以色列 的君。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, '你无论 往哪里 去,我常 与你同在,剪除 你的一切 仇敌;我必使 你 得大名,好像 世上 大大 有名的人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, '我必为我民 以色列 选定 一个地方,栽培他们,使他们住 自己的地方,不 再 迁移;凶恶 之子 也 不 像 从前 扰害他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, '并不像 我命 士师 治理 我民 以色列 的时候一样。我必治服 你的一切 仇敌,并且我─耶和华 应许 你,必为你 建立 家室。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, ' 你寿数 满足 归 你列祖的时候,我必使 你的后裔 接续你的位, 我也必坚定 他的国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, '他 必为我 建造 殿宇;我必坚定 他的国位 直到 永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, '我 要作 他的 父,他 要作 我的 子;并不 使 我的慈爱 离开  他,像 离开  在 你以前 的扫罗一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, '我却要将他 永远 坚立 在我家 里和我国里;他的国位 也必 坚定,直到 永远。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, '拿单 就按这 一切 话,照 这 默示 告诉 大卫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, '于 是大卫 王 进去,坐 在耶和华 面前,说:「耶和华 神啊,我 是谁,我的家 算什么,你竟 使我 到 这地步呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, '神啊,这 在你眼 中还看为小,又应许 你仆人 的家 至于 久远。耶和华 神啊,你看顾我 好像看顾高 贵 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, '你加于  仆人 的尊荣,我 还 有 何言可说呢?因为你 知道 你的仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, '耶和华啊,你行了 这 大事,并且显明出来,是因 你仆人的缘故,也是照你的心意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, '耶和华啊,照 我们耳 中听见,没有 可比你的,除你以外 再无 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, '世上 有何 民 能比你的民 以色列呢?你 神 从埃及 救赎 他们作自己的 子民, 又在你赎 出来的民 面前 行大 而可畏的事,驱逐 列邦人,显出 你的 大 名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, '你使 以色列 人 作你的 子民,直到 永远;你─耶和华 也作 他们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, ' 耶和华啊,你所 应许 仆人 和 仆人家 的话,求你坚定,直到 永远,照你所 说 的而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, '愿 你的名 永远 坚立,被尊为大,说:『万军 之耶和华 是以色列的 神,是治理以色列的 神。』这样,你仆人 大卫 的家 必在你面前 坚立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, '我的 神啊,因 你 启示 仆人说,我必为你 建立 家室,所 以 仆人 大胆 在你面前 祈祷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, ' 耶和华啊,惟有你 是 神,你也应许 将这 福气 赐给 仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, '现在 你喜悦 赐福 与 仆人 的家,可以永 存 在你面前。 耶和华啊,你 已经赐福,还要赐福 到永远。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, ' 此 后,大卫 攻打 非利士人,把他们治服,从他们 手 下夺取了 迦特 和属迦特的村庄; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, '又攻打 摩押,摩押人 就 归服 大卫,给他进 贡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, '琐巴 王 哈大利谢(在撒母耳下八章三节是哈大底谢)往幼发拉底 河 去,要坚定 自己的国权,大卫 就攻打 他,直到哈马, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, ' 夺了 他的 战 车 一千,马兵 七 千,步 兵 二万, 将 拉战 车 的马砍断蹄筋,但留下 一百 辆车的马。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, '大马士革 的亚兰人 来 帮助 琐巴 王 哈大利谢,大卫 就杀了 亚兰人 二 万二 千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, '于 是大卫 在大马士革 的亚兰地 设立防营,亚兰人 就 归服 他,给他进 贡。大卫 无论 往哪里 去,耶和华 都使他 得胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, '他 夺了 哈大利谢 臣仆 所拿 的金 盾牌 带到 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, '大卫 又从属哈大利谢 的提巴(或译:比他)和均 二城 中夺取了 许 多 的铜。后来所罗门 用此 制造 铜 海、 铜柱,和 一切的铜 器。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, '哈马 王 陀乌 听见 大卫 杀败 琐巴 王 哈大利谢 的全 军, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, '就打发 他儿子 哈多兰 去见 大卫 王,问 他的 安,为他祝福,因为 他杀败了 哈大利谢〈原来 陀乌 与哈大利谢 常常 争战 〉。哈多兰带了金 银 铜 的各样 器皿来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, '大卫 王 将这些器皿,并 从各 国 夺来 的 金 银,就是从以东、摩押、亚扪、非利士、亚玛力人所夺来的,都 分别为圣献 给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, '洗鲁雅 的儿子 亚比筛 在盐 谷 击杀了 以东 一 万八 千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, '大卫 在以东 地设立 防营,以东人 就 都 归服 他。大卫 无论 往哪里 去,耶和华 都使他 得胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, '大卫 作 以色列 众人 的王,又 向众 民 秉公 行 义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, '洗鲁雅 的儿子 约押 作 元帅;亚希律 的儿子 约沙法 作史官; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, '亚希突 的儿子 撒督 和亚比亚他 的儿子 亚希米勒 作祭司长;沙威沙 作书记; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, '耶何耶大 的儿子 比拿雅 统辖 基利提人 和比利提人。大卫 的众子 都在王 的左右 作领袖。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, ' 此 后,亚扪 人 的王 拿辖 死了,他儿子 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, '大卫 说:「我要照 哈嫩的父亲 拿辖 厚待 我 的恩典 厚 待 哈嫩。」于 是大卫 差遣 使者 为 他丧父 安慰他。大卫 的臣仆 到了 亚扪 人 的境内 见 哈嫩,要安慰他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, '但亚扪 人 的首领 对哈嫩 说:「 大卫 差人 来安慰 你,你想 他是尊敬 你父亲吗?他的臣仆 来 见你 不是 为 详察 窥探、倾覆 复 这地吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, '哈嫩 便将 大卫 臣仆 的胡须剃去一半,又割断 他们下半 截的衣服,使他们露出 下体,打发他们 回去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, '有人将臣仆 所遇 的事告诉 大卫,他就差人 去迎接他们,因为 他们 甚 觉羞耻; 告诉他们说:「可以住 在耶利哥,等到 胡须 长起 再回来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, '亚扪 人 知道 大卫 憎恶他们,哈嫩 和亚扪 人 就打发 人拿一千 他连得 银子,从 美索不达米亚、 亚兰玛迦、 琐巴 雇 战 车 和马兵, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, '于 是雇了 三 万二 千 辆战 车 和 玛迦 王 并 他的军兵;他们来 安营 在米底巴 前。亚扪 人 也从他们的城 里出来,聚集 交战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, '大卫 听见了,就差派 约押 统带 勇猛 的全 军出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, '亚扪 人 出来 在城 门 前摆 阵,所 来 的诸王 另 在郊野摆阵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, '约押 看见 敌人在 他 前 后 摆阵,就从 以色列 军中挑选 精兵,使他们对著 亚兰人 摆阵; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, ' 其余 馀的 兵 交 与 他兄弟 亚比筛,对著 亚扪 人 摆阵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, '约押对亚比筛说:「亚兰人 若 强 过我,你就 来帮助 我;亚扪 人 若 强 过你,我就去帮助你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, '我们都当刚强,为 本国的民 和 神 的城邑 作大丈夫,愿 耶和华 凭他的 意旨 而行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, '于 是约押 和 跟随他 的人 前进 攻打 亚兰人;亚兰人在约押面前 逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, '亚扪 人 见 亚兰人 逃跑,他们 也 在约押的兄弟 亚比筛 面前 逃跑 进 城。约押 就回 耶路撒冷去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, '亚兰人 见 自己被 以色列人 打败,就打发 使者 将 大河 那边 的 亚兰人 调来,哈大利谢 的 将军 朔法 率领他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, '有人告诉 大卫,他就聚集 以色列 众人 过 约旦河,来 到亚兰人那里,迎著他们 摆阵。大卫 既摆 阵 攻击 亚兰人,亚兰人就与他 打仗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, '亚兰人 在以色列 人面前 逃跑。大卫 杀了 亚兰 七 千 辆战 车的人,四万 步 兵,又杀了 亚兰 的将军 朔法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, '属哈大利谢 的诸王 见 自己被 以色列 人打败,就与 大卫 和好,归服他。于 是亚兰人 不 敢 再 帮助 亚扪 人了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, ' 过了 一年,到列王 出战  的时候,约押 率领 军 兵 毁坏 亚扪 人 的地, 围攻 拉巴;大卫 仍住 在耶路撒冷。约押 攻打 拉巴,将城倾覆 复。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, '大卫 夺了 亚扪人之王 所 戴 的金冠冕(王:或译玛勒堪。玛勒堪即米勒公,是亚扪族之神名), 其上 的金子 重 一他连得,又嵌著宝 石;人将这冠冕戴 在 大卫 头上。大卫 从城 里夺了 许 多 财物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, '将 城里 的 人 拉出来, 放在锯下,或铁 耙下,或铁斧下(或译:强他们用锯,或用打粮食的铁器,或用铁斧做工),大卫 待 亚扪 各 城 的居民 都是如此。其后大卫 和众 军 都回 耶路撒冷去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, ' 后来,以色列 人在基色 与 非利士人 打 仗。 户沙人 西比该 杀了 伟人 的一个儿子 细派,非利士人就被制伏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, ' 又 与 非利士人 打仗。睚珥 的儿子 伊勒哈难 杀了 迦特人 歌利亚 的兄弟 拉哈米;这人的枪 杆 粗如织布 的机轴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, ' 又 在迦特 打仗。那里有 一个身量 高大的人,手脚都 是六 指,共有二十 四 个指头,他 也 是伟人的 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, '这人向 以色列 人骂阵,大卫 的哥哥 示米亚 的儿子 约拿单 就杀了他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, '这 三个人是迦特 伟人的 儿子,都死 在大卫 和他仆人 的手下。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, '撒但 起来 攻击 以色列人,激动 大卫 数点 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, '大卫 就吩咐 约押 和 民 中的首领说:「你们去 数点 以色列人,从别是巴 直到 但,回来 告诉我,我好知道 他们的数目。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, '约押 说:「愿 耶和华 使 他的百姓比现在 加增 百 倍。我主 我王啊,他们不 都是 你的 仆人吗?我主 为何 吩咐 行这事,为何 使 以色列人 陷在罪里呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, '但王 的命令 胜 过 约押。约押 就出去,走 遍 以色列地,回到 耶路撒冷, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, ' 将 百姓 的总数 奏告 大卫: 以色列人 拿 刀 的有 一 百 一 十万;犹大人 拿 刀 的有四 十 七 万。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, '惟有利未人 和便雅悯人 没有 数 在其中,因为 约押 厌恶 王 的这命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, '神 不喜悦 这 数点百姓的事,便降灾 给 以色列人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, '大卫 祷告 神 说:「 我行 这 事 大 有罪了!现在 求 你除掉 仆人 的罪孽,因 我所行的甚 是愚昧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, '耶和华 吩咐 大卫 的先见 迦得 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, '「你去 告诉 大卫 说,耶和华 如此 说:我 有 三样灾,随你 选择 一 样,我好降 与你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, '于 是,迦得 来 见 大卫,对他 说:「耶和华 如此 说:『你可以随意 选择: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, '或 三 年 的饥荒;或 败 在你敌人 面前,被敌人 的刀 追杀 三 个月;或 在你国 中有耶和华 的刀,就是三 日 的瘟疫,耶和华 的使者 在以色列 的四 境 施行毁灭。』现在 你要想一想, 我好回 覆 复 那差我来的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, '大卫 对 迦得 说:「我甚 为难。我愿  落 在耶和华 的手里,因为 他有丰盛 的怜悯;我不 愿 落 在人 的手里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, '于 是,耶和华 降 瘟疫 与以色列人,以色列人 就死了 七 万。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, '神 差遣 使者 去灭 耶路撒冷,刚要灭的时候,耶和华 看见 后悔,就不降 这灾了,吩咐灭 城的天使 说:「够了, 住 手吧!」那时,耶和华 的使者 站 在 耶布斯人 阿珥楠 的禾场那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, '大卫 举 目,看见 耶和华 的使者 站 在 天 地 间,手 里有拔出来 的刀,伸 在 耶路撒冷以上。大卫 和长老 都身穿 麻衣,面 伏 于 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, '大卫 祷告 神 说:「吩咐 数点 百姓 的不是 我吗?我 犯了罪,行了 恶,但这 群羊 做 了什么呢? 愿  耶和华─我 神 的手 攻击我 和我的父 家,不要 攻击你的民,降瘟疫与他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, '耶和华 的使者 吩咐 迦得 去告诉 大卫, 叫他 上去,在耶布斯人 阿珥楠 的禾场 上为耶和华 筑 一座坛; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, '大卫 就照著迦得 奉耶和华 名 所 说 的话 上去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, '那时阿珥楠 正打 麦子, 回头 看见 天使,就和他 四 个儿子 都藏起来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, '大卫 到 了 阿珥楠那里,阿珥楠 看 见 大卫,就从 禾场 上出去,脸 伏于 地,向他 下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, '大卫 对 阿珥楠 说:「你将这禾场 与相连之地 卖 给我,我必给你足 价,我好在其上 为耶和华 筑 一座坛,使民间 的瘟疫 止住。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, '阿珥楠 对 大卫 说:「你 可以用这禾场,愿 我主 我王 照你所喜悦 的去行。 我也将牛 给 你作燔祭,把打粮的器具 当柴烧,拿麦子 作素祭。这些我都 送给你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, '大卫 王 对阿珥楠 说:「不然! 我必 要用足 价 向你买 。 我不 用 你的 物 献给耶和华,也不用白得 之物献 为燔祭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, '于 是大卫 为那块地 平了 六 百 舍客勒 金子 给 阿珥楠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, '大卫 在那里 为耶和华 筑了 一座坛,献 燔祭 和平安祭,求告 耶和华。耶和华就应允他,使火 从 天 降在 燔祭 坛上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, '耶和华 吩咐 使者,他就收 刀 入 鞘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, '那 时,大卫 见 耶和华 在耶布斯人 阿珥楠 的禾场 上应允了他,就在那里 献祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, '摩西 在旷野 所 造 之耶和华 的帐幕 和燔祭 坛 都在基遍 的高处; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, '只是大卫 不 敢 前去 求问 神,因为 惧怕 耶和华 使者 的刀。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, '大卫 说:「这 就是 耶和华 神 的殿,为以色列人 献燔祭的 坛。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, '大卫 吩咐 聚集 住以色列 地 的 外邦人,从其中派 石匠 凿 石头,要建造 神 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, '大卫 预备 许多 铁 做门 上的钉子 和钩子,又预备许多 铜,多得无法 可称; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, '又预备无 数 的香柏 木,因为 西顿人 和泰尔人 给大卫 运了 许多 香柏 木来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, '大卫 说:「我儿子 所罗门 还年幼 娇嫩,要为耶和华 建造 的殿宇 必须高大 辉煌,使名誉 荣耀 传遍万 国; 所以我要为殿 预备材料。」于 是,大卫 在未死 之先 预备 的材料甚多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, '大卫召了 他儿子 所罗门来,嘱咐他 给耶和华─以色列的 神 建造 殿宇, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, ' 对所罗门 说:「我儿啊, 我心 里本想为耶和华─我 神 的名 建造 殿宇, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, '只是耶和华 的话 临 到我 说:『你流了 多 人的血,打 了多次大 仗,你不可 为我的名 建造 殿宇,因为 你在我眼前 使多 人的血 流 在地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, ' 你 要生 一个儿子,他 必作 太平 的人;我必使他 安静,不被四 围 的仇敌扰乱。 他的名 要叫 所罗门(就是太平的意思)。他在位的日子,我必使 以色列人 平安 康泰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, '他 必为我的名 建造 殿宇。他 要作 我的 子;我 要作他的 父。他作 以色列王;我必坚定 他的国 位,直到 永远。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, '我儿啊,现今 愿 耶和华 与你 同在,使你亨通,照 他指著你 说的话,建造 耶和华─你 神 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, '但愿  耶和华 赐 你 聪明 智慧,好治理 以色列国,遵行 耶和华─你 神 的律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, '你若 谨守 遵行 耶和华藉 借 摩西 吩咐 以色列的 律例 典章, 就得亨通。你当刚强 壮胆,不要 惧怕,也不要 惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, ' 我在困难 之中为耶和华 的殿 预备 了金子 十万 他连得,银子 一 百万 他连得,铜 和铁 多 得无法 可称;我也预备 了木头、石头,你还可以增添。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, '你有 许多 匠人,就是石 匠、木 匠,和一切 能做各样 工 的巧匠, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, '并有无 数 的金 银 铜 铁。你当起来 办事,愿 耶和华 与你 同在。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, '大卫 又吩咐 以色列 的众 首领 帮助 他儿子 所罗门,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, '「耶和华─你们的 神 不是 与你们同在吗?不是叫你们 四围 都平安吗?因 他已将 这地 的居民 交 在我手中,这地 就在耶和华 与他百姓 面前 制伏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, '现在 你们应当立定 心 意,寻求 耶和华─你们的 神;也当起来 建造 耶和华 神 的圣所,好将 耶和华 的约 柜和供奉 神 的圣 器皿 都搬进 为耶和华 名 建造 的殿里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, '大卫 年纪老迈,日子 满足,就立 他儿子 所罗门 作 以色列 的王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, '大卫招聚 以色列 的众 首领 和祭司 利未人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, '利未人 从 三十 岁 以外 的都被数点,他们男 丁 的数目 共有 三 万八 千; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, '其中 有二 万四 千 人管理 耶和华 殿 的事,有六 千 人作官长 和士师, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, '有四 千 人作守门的,又有四 千 人用大卫所 做 的乐器 颂赞 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, '大卫 将利未 人革顺、哥辖、米拉利 的子孙 分了 班次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, '革顺 的子孙有拉但 和示每。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, '拉但 的长 子 是耶歇,还有细坦 和约珥,共三人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, '示每 的儿子 是示罗密、哈薛、哈兰 三人。这是 拉但 族的族 长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, '示每 的儿子 是雅哈、细拿、耶乌施、比利亚 共四人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, '雅哈 是 长子,细撒 是次子。但耶乌施 和比利亚 的子孙 不 多,所以算 为 一 族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, '哥辖 的儿子 是暗兰、以斯哈、希伯伦、乌薛 共四人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, '暗兰 的儿子 是亚伦、摩西。亚伦 和他的子孙 分出来,好分别 至 圣 的物,在耶和华 面前 烧香、事奉他,奉他的名 祝福,直到 永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, '至于 神 人 摩西,他的子孙 名字记 在 利未 支派的册上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, '摩西 的儿子 是革舜 和以利以谢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, '革舜 的长 子 是细布业; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, '以利以谢 的儿子 是利哈比雅。以利以谢 没 有 别 的儿子,但利哈比雅 的子孙 甚 多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, '以斯哈 的长 子 是示罗密。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, '希伯伦 的长 子 是耶利雅,次 子是亚玛利亚,三 子是雅哈悉,四 子是耶加面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, '乌薛 的长 子 是米迦,次 子是耶西雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, '米拉利 的儿子 是抹利、母示。抹利 的儿子 是以利亚撒、基士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, '以利亚撒 死了,没 有 儿子,只有 女儿,他们本族 基士 的儿子 娶了她们为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, '母示 的儿子 是末力、以得、耶利摩 共三人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, '以上 利未 子孙 作族 长的,照著 男丁 的数目,从 二十 岁 以外,都办 耶和华 殿的 事务。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, ' 大卫 说:「耶和华─以色列的 神 已经使他的百姓 平安,他 永远 住 在耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, '利未人 不必 再 抬 帐幕 和 其中所用 的一切 器皿了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, ' 照著大卫 临终 所吩咐的,利未 人 从 二十 岁 以外的都 被数点。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, ' 他们的职任 是服事 亚伦 的子孙,在耶和华 的殿和 院子,并 屋 中办事, 洁净 一切 圣物,就是办 神 殿 的 事务, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, '并管理陈设 饼,素祭 的细面 麺,或无酵 薄饼,或用盘 烤,或用油调和的物,又管理各样的 升斗 尺度; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, '每日 早 晚,站立 称谢 赞美 耶和华, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, '又在安息日、月朔,并节期,按数 照例,将 燔祭 常常 献 给耶和华; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, '又看守 会 幕 和 圣所,并守 耶和华吩咐他们弟兄 亚伦 子孙的,办耶和华 殿 的事。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, '亚伦 子孙 的班次记在下面:亚伦 的儿子 是拿答、亚比户、以利亚撒、以他玛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, '拿答、亚比户 死 在他们父亲 之先,没有 留下 儿子;故此,以利亚撒、以他玛 供祭司的职分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, '以利亚撒 的 子孙 撒督 和以他玛 的 子孙 亚希米勒,同著大卫 将他们的族弟兄分成 班 次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, ' 以利亚撒 子孙 中为首 的比 以他玛 子孙 中为首的更多,分班如下:以利亚撒 的子孙 中有十 六 个族 长,以他玛 的子孙 中有八 个族长; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, '都掣签 分立,彼 此 一样。 在圣所和 神 面前作首领 的有以利亚撒 的子孙,也有以他玛 的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, '作书记 的 利未人 拿坦业 的儿子 示玛雅 在王 和首领,与祭司 撒督、亚比亚他 的儿子 亚希米勒,并祭司 利未人 的族 长 面前 记录他们的名字。在以利亚撒 的子孙中取 一 族,在以他玛 的子孙中取 一族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, '掣签的时候,第一 掣出来 的是耶何雅立,第二 是耶大雅, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, '第三 是哈琳,第四 是梭琳, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, '第五 是玛基雅,第六 是米雅民, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, '第七 是哈歌斯,第八 是亚比雅, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, '第九 是耶书亚,第十 是示迦尼, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, '第十 一 是以利亚实,第十 二 是雅金, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, '第十 三 是胡巴,第十 四 是耶是比押, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, '第十 五 是璧迦,第十 六 是音麦, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, '第十 七 是希悉,第十 八 是哈辟悉, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, '第十 九 是毘他希雅,第二十 是以西结, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, '第二十 一 是雅斤,第二十 二 是迦末, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, '第二十 三 是第来雅,第二十 四 是玛西亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, '这 就是他们的班次,要照耶和华─以色列的 神 藉 借 他们祖宗 亚伦 所 吩咐 的条例 进入 耶和华 的殿 办理事务。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, '利未 其余 馀 的子孙如下:暗兰 的子孙 里有书巴业;书巴业 的子孙 里有耶希底亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, ' 利哈比雅 的子孙 里有长 子伊示雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, '以斯哈的 子孙里有示罗摩;示罗摩 的子孙 里有雅哈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, '希伯伦的子孙 里有长子耶利雅,次 子亚玛利亚,三 子雅哈悉,四 子耶加面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, '乌薛 的子孙 里有米迦;米迦 的子孙 里有沙密。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, '米迦 的兄弟 是伊示雅;伊示雅 的子孙 里有撒迦利雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, '米拉利 的儿子 是抹利、母示、雅西雅;雅西雅 的儿子 有比挪; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, '米拉利 的子孙 里有雅西雅的 儿子比挪、朔含、撒刻、伊比利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, '抹利的 儿子是以利亚撒;以利亚撒没 有 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, ' 基士 的子孙 里有耶拉篾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, '母示 的儿子 是末力、以得、耶利摩。按著宗 族 这 都是利未 的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, '他们 在大卫 王 和撒督,并亚希米勒 与祭司 利未人 的族 长 面前 掣 签,正如 他们弟兄 亚伦 的子孙一般。各族 的长者 与 兄弟没有分别。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, '大卫 和众首 领 分派 亚萨、希幔,并耶杜顿 的子孙 弹琴、鼓瑟、敲钹、唱歌(原文是说预言;本章同)。他们供职 的人 数记在下面: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, '亚萨 的儿子 撒刻、约瑟、 尼探雅、亚萨利拉 都归 亚萨 指教,遵 王 的旨意 唱歌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, ' 耶杜顿 的儿子 基大利、西利、耶筛亚、哈沙比雅、玛他提雅、示每共六人,都归 他们父亲 耶杜顿 指教,弹琴,唱歌, 称谢,颂赞 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, ' 希幔 的儿子 布基雅、玛探雅、乌薛、细布业、耶利摩、哈拿尼雅、哈拿尼、以利亚他、基大利提、罗幔提‧以谢、约施比加沙、玛罗提、何提、玛哈秀; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, '这 都 是希幔的 儿子,吹 角颂赞。希幔奉 神 之命 作王 的先见。 神 赐给 希幔 十 四 个儿子,三 个女儿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, ' 都 归 他们父亲 指教,在耶和华 的殿 唱歌、敲钹、弹琴、鼓瑟,办 神 殿 的事务。亚萨、耶杜顿、希幔 都是 王 所命定的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, '他们和 他们的弟兄 学习 颂赞 耶和华; 善于  歌唱的 共有 二百 八十 八人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, '这些人无论大 小,为师的、 为徒的,都一同 掣 签 分了班次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, '掣签的时候,第一 掣出来 的是亚萨的 儿子约瑟。第二 是基大利;他 和他弟兄 并儿子 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, '第三 是撒刻;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, '第四 是伊洗利;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, '第五 是尼探雅;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, '第六 是布基雅;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, '第七 是耶萨利拉;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, '第八 是耶筛亚;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, '第九 是玛探雅;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, '第十 是示每;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, '第十 一 是亚萨烈;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, '第十 二 是哈沙比雅;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, '第十 三 是书巴业;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, '第十 四 是玛他提雅;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, '第十 五 是耶利摩;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, '第十 六 是哈拿尼雅;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, '第十 七 是约施比加沙;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, '第十 八 是哈拿尼;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, '第十 九 是玛罗提;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, '第二十 是以利亚他;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, '第二十 一 是何提;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, '第二十 二 是基大利提;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, '第二十 三 是玛哈秀;他和他儿子 并弟兄 共十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, '第二十 四是罗幔提‧以谢;他和他儿子 并弟兄 共十 二人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, '守门的 班次记在下面:可拉族 亚萨 的 子孙中,有可利 的儿子 米施利米雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, '米施利米雅 的 长子 是撒迦利亚,次 子是耶叠,三 子是西巴第雅,四 子是耶提聂, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, '五 子是以拦,六 子是约哈难,七 子是以利约乃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, '俄别‧以东 的 长子 是示玛雅,次 子是约萨拔,三 子是约亚,四 子是沙甲,五 子是拿坦业, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, '六 子是亚米利,七 子是以萨迦,八 子是毘乌利太,因为 神 赐福与俄别‧以东。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, '他的儿子 示玛雅 有几个儿子, 都是 大能 的壮士,掌管 父亲 的家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, '示玛雅 的儿子 是俄得尼、利法益、俄备得、以利萨巴。以利萨巴的弟兄 是壮 士,还有以利户 和西玛迦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, '这 都是俄别‧以东 的子孙,他们 和他们的儿子 并弟兄,都是善于  办事 的壮 士。俄别‧以东的 子孙共六十 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, '米施利米雅 的儿子 和弟兄 都是壮 士,共十 八人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, '米拉利 子孙 何萨 有几个儿子:长子 是申利,他原 不 是 长子,是他父亲 立他 作长子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, '次 子是希勒家,三 子是底巴利雅,四 子是撒迦利亚。何萨的 儿子 并弟兄 共十 三人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, '这些人 都是守门 的班 长,与他们的弟兄 一同 在耶和华 殿 里按班 供职。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, '他们无论大 小,都按著宗 族 掣 签 分守 各门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, '掣 签 守东 门的是示利米雅;他的儿子 撒迦利亚 是精明的 谋士,掣 签 守北门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, '俄别‧以东 守南门,他的儿子 守库 房。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, '书聘 与何萨 守西门,在靠近 沙利基 门、通著往上去 的街道上,班 与班 相对。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, '每日 东 门有六 个利未人,北 门有四个, 南 门有四个,库房 有两个,又有两个轮班替换。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, ' 在西面 街道 上有四个,在游廊 上有两个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, '以上 是可拉 子孙 和米拉利 子孙 守门 的班次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, '利未子孙 中有亚希雅 掌管 神 殿 的府库 和圣物 的府库。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, ' 革顺族、拉但 子孙里,作族 长 的是革顺族 拉但 的子孙 耶希伊利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, '耶希伊利 的儿子 西坦 和他兄弟 约珥 掌管 耶和华 殿 里的府库。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, '暗兰族、以斯哈族、希伯伦族、乌泄族也有职分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, '摩西 的孙子、革舜 的儿子 细布业 掌管 府库。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, '还有他的弟兄 以利以谢。以利以谢的儿子 是利哈比雅;利哈比雅的儿子 是耶筛亚;耶筛亚的儿子 是约兰;约兰的儿子 是细基利;细基利的儿子 是示罗密。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, '这 示罗密 和他的弟兄 掌管 府库 的圣物,就是 大卫 王 和众族 长、千 夫长、百夫长,并军 长 所分别为圣的物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, '他们将 争战  时所夺的 财物 分别为圣,以备修造 耶和华 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, '先见 撒母耳、基士 的儿子 扫罗、尼珥 的儿子 押尼珥、洗鲁雅 的儿子 约押 所分别为圣 的物 都 归 示罗密 和他的弟兄 掌管。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, '以斯哈族 有基拿尼雅 和他众子 作官长 和士师,管理 以色列 的外事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, '希伯伦族 有哈沙比雅 和他弟兄 一千 七 百人,都是壮士,在 约旦河 西、 以色列 地办理 耶和华 与王 的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, '希伯伦族 中有耶利雅 作族 长。大卫 作王 第四十 年,在基列 的雅谢,从这 族 中 寻 得 大能的 勇士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, '耶利雅的弟兄 有二千 七 百人,都是壮 士,且作族 长;大卫 王 派他们 在 流便支派、迦得支派、玛拿西 半 支派中办理 神 和王 的事。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, '以色列 人 的族 长、千 夫长、百夫长,和官长 都 分定 班次,每 班 是二 万四 千人,周 年 按 月轮流,替换出 入 服事 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, '正 月 第一 班的班长 是撒巴第业 的儿子 雅朔班; 他班 内有二 万四 千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, '他是法勒斯 的 子孙,统管 正 月 班的一切 军 长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, '二 月 的班长 是亚哈希人 朵代, 还有副官 密基罗; 他班 内有二 万四 千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, '三 月 第三班的班长(原文是军长;下同)是祭司 耶何耶大 的儿子 比拿雅; 他班 内有二 万四 千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, '这 比拿雅 是那三十 人中的勇士,管理 那三十人;他班 内又有他儿子 暗米萨拔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, '四 月 第四 班的班长是约押 的兄弟 亚撒黑。接续他 的是他儿子 西巴第雅; 他班 内有二 万四 千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, '五 月 第五 班的班长 是伊斯拉人 珊合; 他班 内有二 万四 千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, '六 月 第六 班的班长是提哥亚人 益吉 的儿子 以拉; 他班 内有二 万四 千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, '七 月 第七 班的班长是以法莲 族 比伦人 希利斯; 他班 内有二 万四 千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, '八 月 第八 班的班长是谢拉族 户沙人 西比该; 他班 内有二 万四 千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, '九 月 第九 班的班长是便雅悯族 亚拿突人 亚比以谢; 他班 内有二 万四 千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, '十 月 第十 班的班长是谢拉族 尼陀法人 玛哈莱; 他班 内有二 万四 千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, '十 一 月 第十 一 班的班长是以法莲 族 比拉顿人 比拿雅; 他班 内有二 万四 千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, '十 二 月 第十 二 班的班长是俄陀聂族 尼陀法人 黑玳; 他班 内有二 万四 千人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, '管理 以色列 众支派的记在下面:管 流便人 的是细基利 的儿子 以利以谢;管西缅人 的是玛迦 的儿子 示法提雅; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, '管利未人 的是基母利 的儿子 哈沙比雅;管亚伦 子孙的是撒督; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, '管犹大人 的是大卫 的一个哥哥 以利户,管以萨迦人 的是米迦勒 的儿子 暗利; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, '管西布伦人 的是俄巴第雅 的儿子 伊施玛雅;管拿弗他利人 的是亚斯列 的儿子 耶利摩; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, '管以法莲 人 的是阿撒细雅 的儿子 何细亚;管玛拿西 半 支派 的是毘大雅 的儿子 约珥; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, '管基列地 玛拿西 那半 支派的是撒迦利亚 的儿子 易多;管便雅悯人 的是押尼珥 的儿子 雅西业; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, '管但人 的是耶罗罕 的儿子 亚萨列。以上 是以色列 众支派 的首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, '以色列 人 二十 岁 以内的,大卫 没有 记 其数目;因 耶和华 曾应许说,必加增 以色列 人如天上 的星那样多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, '洗鲁雅 的儿子 约押 动手 数点,当时耶和华的 烈怒 临 到 以色列人;因此,没有 点完,数目 也没有 写 在大卫 王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, '掌管 王 府库 的是亚叠 的儿子 押斯马威。掌管 田野 城邑 村庄 保障 之仓库 的是乌西雅 的儿子 约拿单。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, '掌管 耕 田 种 地 的是基绿 的儿子 以斯利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, '掌管 葡萄园 的是拉玛人 示每。掌管 葡萄园 酒 窖 的是实弗米人 撒巴底。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, '掌管 高原 橄榄树 和桑树 的是基第利人巴勒‧哈南。掌管 油 库 的是约阿施。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, '掌管 沙仑  牧放 牛群 的是沙仑 人 施提赉。掌管 山谷 牧养牛群 的是亚第赉 的儿子 沙法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, '掌管 驼群 的是以实玛利人 阿比勒。掌管 驴群 的是米仑 人 耶希底亚。掌管 羊群 的是夏甲人 雅悉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, '这 都 是 给大卫 王 掌管 产业的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, '大卫 的叔叔 约拿单 作谋士;这人 有智慧,又作 书记。哈摩尼 的儿子 耶歇 作 王 众子的师傅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, '亚希多弗 也作王的 谋士。亚基人 户筛 作王 的陪伴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, '亚希多弗 之后,有比拿雅 的儿子 耶何耶大 和亚比亚他接续他作谋士。约押 作王的 元帅。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, '大卫 招聚 以色列 各 支派 的首领 和轮班 服事 王 的军长,与千 夫长、百 夫长,掌管 王 和王子 产业 牲畜的,并 太监,以及 大能 的勇士,都到 耶路撒冷来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, '大卫 王 就站 起来,说:「我的弟兄,我的百姓啊,你们当听我言, 我心 里本想建造 殿宇,安放 耶和华 的约 柜,作为我 神 的脚 凳;我已经预备 建造的材料。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, '只是 神 对我 说:『你不可 为我的名 建造 殿宇;因 你 是战  士,流了 人的血。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, '然而,耶和华─以色列的 神 在我父 的全 家 拣选 我 作 以色列 的王,直到永远。因 他拣选 犹大 为首领;在犹大 支派 中拣选我父 家,在我父 的众子 里喜悦 我,立 我作 以色列 众人的王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, ' 耶和华 赐 我 许多 儿子,在 我儿子 中拣选 所罗门 坐 耶和华 的国 位,治理 以色列人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, '耶和华 对我 说:『你儿子 所罗门 必 建造 我的殿 和院宇;因为 我拣选 他 作我的 子,我 也必作 他的 父。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, '他若 恒久 遵行 我的诫命 典章 如今 日一样,我就必坚定 他的国位,直到 永远。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, '现今 在耶和华 的会中,以色列 众人 眼前所说的,我们的 神 也听见了。你们应当寻求 耶和华─你们 神 的一切 诫命,谨守遵行,如此你们可以 承受 这美 地,遗留 给你们的子孙, 永远为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, '「我儿 所罗门哪,你 当认识 耶和华─你父的 神,诚 心 乐 意 地事奉他;因为 他 鉴察 众人 的心,知道 一切 心思 意念。你若 寻求他,他必使你 寻见;你若 离弃他,他必永远 丢弃你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, ' 你当谨慎,因 耶和华 拣选 你 建造 殿宇 作为圣所。你当刚强 去行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, '大卫 将 殿的游廊、 旁屋、府库、楼房、内 殿,和施恩 所 的样式 指示 他儿子 所罗门, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, '又将被灵感动 所 得 的样式,就是耶和华 神 殿 的院子、周围的 房屋、殿 的府库,和圣物 府库 的一切样式都指示他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, '又指示他祭司 和利未人 的班次 与耶和华 殿 里各样 的 工作,并耶和华 殿 里一切 器皿的样式, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, '以及各样 应用 金 器 的分两 和各样 应用 银 器 的分两, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, '金 灯台 和金 灯 的分两,银 灯台 和银灯 的分两, 轻重各都合宜; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, '陈设饼 金 桌子 的分两,银 桌子 的分两, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, '精 金 的肉叉子、盘子,和爵 的分两,各 金 碗与各 银 碗 的分两, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, '精 金 香 坛 的分两,并用金子做基路伯(原文是用金子做车 式 的基路伯);基路伯张开 翅膀,遮掩 耶和华 的约 柜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, '大卫说:「这一切 工作 的样式 都是耶和华 用手 划 㓰 出来使我 明白的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, '大卫 又对他儿子 所罗门 说:「你当刚强 壮胆 去行!不要 惧怕,也不要 惊惶。因为 耶和华 神就是我的 神,与你同在;他必不 撇下你,也不 丢弃你,直到 耶和华 殿 的工作 都 完毕了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, ' 有祭司 和利未人 的各班,为要办理 神 殿 各样的 事,又有 灵巧的人 在各样的 工作 上乐意 帮助你;并有众首领 和众 民 一 心听从你的命令。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, '大卫 王 对 会众 说:「我儿子 所罗门是 神 特 选的,还年幼 娇嫩;这工程 甚大,因 这殿 不是 为人,乃是 为耶和华 神建造的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, '我为我 神 的殿 已经尽 力,预备 金子 做金器,银子 做银器,铜 做铜器,铁 做铁器,木 做木器,还有红玛瑙 可镶嵌 的宝 石,彩石 和一切的 宝 石,并许多 汉白玉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, '且 因我心中爱慕我 神 的殿,就在 预备 建造圣 殿 的材料之外,又将 我自己 积蓄 的金 银 献上,建造我 神 的殿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, '就是俄斐 金 三 千 他连得、精炼 链 𫔀 的银子 七 千 他连得,以贴 殿 墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, '金子 做金器,银子 做银器,并藉 借匠人 的手 制造 一切。今日 有谁 乐意 将自己 献 给耶和华呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, '于 是,众族 长 和以色列 各支派 的首领、千 夫长、百夫长,并监管王 工 的官长,都乐意献上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, '他们为 神 殿 的使用 献上 金子 五 千 他连得 零一万 达利克,银子 一万 他连得,铜 一万八千 他连得,铁 十万 他连得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, '凡 有 宝石 的都交 给 革顺人 耶歇,送入耶和华 殿 的府库。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, '因这些人 诚 心 乐意 献给耶和华,百姓 就欢喜,大卫 王 也 大大 欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, '所以,大卫在 会众 面前 称颂 耶和华 说:「耶和华─我们的父,以色列的 神 是应当称颂, 直到 永永远远的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, '耶和华啊,尊大、能力、荣耀、强胜、威严 都是你的; 凡 天上 地 下的都是 你的;国度也是你的, 并且你为至高,为万有 之首。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, '丰富 尊荣 都从你而来,你 也治理 万物。在你手 里有大能 大力,使人尊大 强盛 都出于 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, '我们的 神啊,现在 我们 称谢 你,赞美 你荣耀 之名! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, '「 我 算什么,我的民 算什么,竟 能 如 此 乐意奉献?因为 万物 都从你而来,我们把从你 而得的献 给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, ' 我们 在你面前 是客旅,是寄居的,与我们列 祖一样。我们在 世 的日子 如影儿,不能长存(或译:没有 长存的指望)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, '耶和华─我们的 神啊, 我们预备 这 许多 材料,要为你 的圣 名 建造 殿宇,都是 从你而来,都是 属你的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, '我的 神啊,我知道 你 察验 人心,喜悦 正直;我 以正直 的心 乐意献上 这 一切物。现在 我喜欢 见 你的民 在这里 都乐意奉献 与你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, '耶和华─我们列祖 亚伯拉罕、以撒、以色列的 神啊,求你使你的民 常 存 这样的 心 思 意念,坚定 他们的心 归向你, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, '又求你赐 我儿子 所罗门 诚实 的心,遵守 你的命令、法度、律例,成就 这一切的事,用我所 预备 的建造 殿宇。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, '大卫 对全 会众 说:「你们应当 称颂 耶和华─你们的 神。」于 是 会众 称颂 耶和华─他们列祖的 神,低头 拜 耶和华 与王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, '次 日,他们向耶和华 献 平安祭 和 燔祭,就是献公牛 一千只,公绵羊 一千只,羊羔 一千只,并同献的奠祭;又为以色列 众人 献 许多的祭。那 日,他们在耶和华 面前 吃 喝,大大 欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, '他们奉耶和华 的命再 膏 大卫 的儿子 所罗门 作 王,又膏撒督 作祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, '于 是所罗门 坐 在 耶和华 所赐的位上,接续 他父亲 大卫 作王,万事亨通;以色列 众人 也都听 从他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, '众 首领 和勇士,并 大卫 王 的众 子,都顺 服 所罗门 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, '耶和华 使 所罗门 在以色列 众人 眼前 甚为 尊大, 极其威 严, 胜过在 他以前的 以色列 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, '耶西 的儿子 大卫 作 以色列 众人 的王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, ' 作王 共四十 年:在希伯仑  作王 七 年,在耶路撒冷 作王 三十 三年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, '他年纪老 迈,日子 满足,享受丰富、尊荣,就死了。他儿子 所罗门 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, '大卫 王 始 终 的事 都写 在 先见 撒母耳 的书 上和 先知 拿单 并 先见 迦得 的书上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, ' 他的国事 和他的勇力,以及他 和 以色列 并 列 国 所 经过 的事都写在这书上。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, '大卫 的儿子 所罗门 国位 坚固;耶和华─他的 神 与他同在,使他甚为 尊大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, '所罗门 吩咐 以色列 众人,就是千 夫长、百夫长、审判官、 首领与 族 长都来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, '所罗门 和 会众 都 往基遍 的 邱坛 去,因 那里 有 神 的会 幕,就是耶和华 仆人 摩西 在旷野 所 制造的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, '只是 神 的约柜,大卫已经从基列‧耶琳 搬 到他 所预备的地方,因 他曾在耶路撒冷 为约柜 支搭了 帐幕, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, '并且户珥 的孙子、乌利 的儿子 比撒列 所 造的 铜 坛 也在 基遍耶和华 的会幕 前。所罗门 和会众 都就近坛前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, '所罗门 上 到 耶和华 面前 会 幕 的铜 坛 那里,献 一千 牺牲为燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, '当 夜, 神 向所罗门 显现,对他 说:「你愿 我赐 你 什么,你可以求。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, '所罗门对 神 说:「你 曾向 我父 大卫 大 施 慈爱,使我接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, '耶和华 神啊,现在 求你成就 向 我父 大卫 所应许的话;因 你 立我作 这民 的王,他们如同地上 尘沙 那样多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, ' 求你赐 我 智慧 聪明,我好在这 民 前 出 入;不然,谁 能判断 这 众多 的民呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, '神 对所罗门 说:「我已立你作 我民 的王。你既 有 这 心意,并不 求 资财、丰富、尊荣,也不求灭绝 那恨你之人 的性命,又 不 求 大 寿数,只 求 智慧 聪明 好 判断 我的民; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, '我必赐 你 智慧 聪明,也必赐 你 资财、丰富、尊荣。 在你以前 的 列王 都没 有 这样,在你以后 也必 没有 这样的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, '于 是,所罗门从 基遍 邱坛 会 幕 前 回到 耶路撒冷,治理 以色列人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, '所罗门 聚集 战 车 马兵,有 战 车 一千 四 百辆,马兵 一 万二 千名,安置 在屯车 的城邑 和耶路撒冷,就是 王那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, '王 在耶路撒冷 使 金 银 多如石头, 香柏木 多 如高原 的 桑树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, '所罗门 的 马 是从埃及 带来的,是王的 商人 一群 一群 按著定价 买 来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, '他们从埃及 买  来 的车,每辆价银 六 百舍客勒,马 每匹一百 五十舍客勒。赫人 诸 王 和亚兰 诸王所买 的车马,也是按这价值 经他们手 买 来的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, '所罗门 定意 要为耶和华 的名 建造 殿宇,又为自己的国 建造宫室。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, '所罗门 就挑选 七万 扛抬的,八万 在山上 凿石头的,三 千 六 百 督 工的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, '所罗门 差人 去见 泰尔 王 希兰,说:「你曾运 香柏木 与 我父 大卫 建 宫 居住,求你也这样 待我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, ' 我 要为耶和华─我 神 的名 建造 殿宇,分别为圣 献给他,在他面前 焚烧 美 香,常 摆陈设饼,每早 晚、安息日、月朔,并耶和华─我们 神 所定的节期 献燔祭。这是 以色列人 永远的定例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, '我 所 要建造 的殿宇 甚大;因为我们的 神 至大,超乎诸 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, '天 和天 上的天,尚且 不 足他居住的,谁 能 为他 建造 殿宇呢?我 是谁? 能为他 建造 殿宇吗?不过 在他面前 烧香而已。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, '现在 求你差 一个 巧匠来,就是善用金、银、铜、铁,和紫色、朱红色、蓝色线 缐,并精于  雕刻 之工的巧匠,与 我父 大卫 在犹大 和耶路撒冷 所 预备的 巧匠 一同 做工; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, '又求你从黎巴嫩 运 些香柏 木、松木、檀香木到我这里来,因 我 知道 你的仆人 善于  砍伐 黎巴嫩 的树木。 我的仆人 也必与 你的仆人同工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, '这样,可以给我 预备 许多的 木料,因 我 要建造 的 殿宇 高大 出奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, ' 你的仆人 砍 伐 树木,我必给 他们 打好了的 小麦 二万 歌珥,大麦 二万 歌珥,酒 二万 罢特,油 二万 罢特。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, '泰尔 王 希兰 写信 回答 所罗门 说:「耶和华 因为爱 他的子民,所以立你 作他们的 王」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, ' 又说:「 创造 天 地 的耶和华─以色列的 神 是应当称颂的!他 赐 给大卫 王 一个有智慧的 儿子,使他有谋 略 聪明, 可以为耶和华 建造 殿宇,又为自己的国 建造宫室。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, '「现在 我打发 一个精巧 有 聪明 的人去,他是我父亲 希兰所用的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, '是但 支派一个 妇人 的儿子。他父亲 是泰尔 人,他善用 金、银、铜、铁、石、木,和紫色、蓝色、朱红色 线 缐与细麻 制造各物,并精于  雕刻,又能想出 各样的 巧工。 请你派定这人,与 你的巧匠 和你父─我主 大卫 的巧匠一同做工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, '我主 所 说的 小麦、大麦、酒、油, 愿 我主运来 给众仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, '我们 必照 你所需用的,从 黎巴嫩 砍伐 树木,扎成筏子,浮 海 运到 约帕;你 可以从那里运到 耶路撒冷。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, '所罗门 仿照 他父 大卫 数点住在 以色列 地 所有 寄居的外邦 人,共有 十 五 万 三 千 六 百名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, '使 七万 人扛抬材料,八万 人在山上 凿石头,三 千 六 百 人 督理 工作。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, '所罗门 就在耶路撒冷、耶和华 向他父 大卫 显现 的 摩利亚 山上,就是耶布斯人 阿珥楠 的禾场上、大卫 所 指定的地方 预备好了,开 工 建造 耶和华 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, '所罗门 作王 第四 年 二 月 初二 日开 工 建造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, '所罗门 建筑 神 殿 的根基,乃是这样:长 六十 肘,宽 二十 肘,都按著古时 的尺寸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, ' 殿前 的廊子 长 二十 肘,与 殿 的宽窄一样,高 一百 二十肘;里面 贴上 精 金。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, ' 大 殿 的墙都用松 木 板遮蔽,又贴了 精 金,上面 雕刻 棕树 和链子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, '又用宝 石 装饰 殿墙,使殿华美;所用的金子 都是巴瓦音 的金子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, '又用金子 贴 殿 和殿的栋梁、门槛、墙壁、门扇;墙 上 雕刻 基路伯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, '又建造 至 圣 所,长 二十 肘,与 殿 的宽窄 一样,宽 也是二十 肘;贴上 精 金,共用金子六 百 他连得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, '金 钉 重 五十 舍客勒。楼房 都贴上 金子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, '在至 圣 所 按造 像 的法子造 两个 基路伯,用金子 包裹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, '两个基路伯 的翅膀 共长 二十 肘。这基路伯的一个 翅膀 长五 肘,挨著 殿 这边的墙;那一个 翅膀 也长五 肘,与那 基路伯 翅膀 相接。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, '那 基路伯 的一个翅膀 长五 肘,挨著 殿 那边的墙;那一个 翅膀 也长五 肘,与这 基路伯 的翅膀 相接。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, '两个 基路伯 张开  翅膀,共长二十 肘, 面 向外殿 而立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, '又用蓝色、紫色、朱红色 线 缐和细麻 织 幔子,在其上 绣出 基路伯来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, '在殿 前 造了 两根 柱子,高 三十 五 肘;每柱 顶 高五 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, '又照圣所 内链子的样式做 链子,安 在 柱 顶上;又做 一百 石榴,安 在链子上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, '将 两根柱子 立 在 殿 前,一根 在右边,一根 在左边;右边 的起名 叫 雅斤,左边 的起名 叫波阿斯。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, '他又制造 一座铜 坛,长 二十 肘,宽 二十 肘,高 十 肘; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, '又铸 一个铜 海,样式是圆的,高 五 肘,径 十 肘, 围 三十 肘; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, '海 周围有野瓜(野瓜:原文是牛)的样式,每肘 十 瓜,共有两 行,是铸 海的时候铸上的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, ' 有十二只 铜牛 驮海:三只 向 北,三只 向 西,三只 向 南,三只 向 东;海 在 牛上, 牛尾 向内; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, '海厚 一掌,边 如 杯 边,又如百合 花,可 容 三 千 罢特; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, '又制造 十个 盆:五个 放 在右边,五个 放在左边, 献 燔祭 所用之物都洗 在其内;但海 是为祭司 沐浴的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, '他又照所定的样式 造 十个 金灯台, 放 在殿里:五个 在右边,五个 在左边; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, '又造 十张 桌子 放 在殿里:五张 在右边,五张 在左边;又造 一百个 金 碗; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, '又建立 祭司 院 和大 院,并院 门,用铜 包裹 门扇; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, '将 海 安 在殿门的右 边,就是 南边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, '户兰 又造了 盆、 铲、 碗。这样,他 为所罗门 王 做 完了 神 殿 的工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, '所造的就是:两根 柱子 和柱 上 两个 如球 的顶,并两个 盖 柱 顶 的网子 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, '和 四 百 石榴,安在两个 网子上〈每 网 两 行 盖著 两个 柱 上 如球 的顶〉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, ' 盆座 和 其上的 盆, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, ' 海 和 海下 的十 二 只牛, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, ' 盆、 铲子、 肉锸子,与 耶和华 殿 里的一切 器皿,都是巧匠 户兰 用光亮的 铜 为所罗门 王 造成的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, '是在约旦 平原 疏割 和撒利但 中间 藉 借胶 泥 铸成的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, '所罗门 制造 的这 一切 甚 多, 铜 的轻重 无法 可查。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, '所罗门 又造 神 殿里的 金 坛 和 陈设 饼 的桌子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, '并 精 金的 灯台 和灯盏,可以照例 点 在内殿 前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, '灯台上的花 和灯盏,并蜡剪 都是金的,且是 纯 金的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, '又用精 金 制造镊子、盘子、调羹、火鼎。至于 殿 门 和至 圣所 的门 扇,并殿的 门扇,都是金子妆饰的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, '所罗门 做 完了 耶和华 殿 的 一切 工, 就把 他父 大卫 分别为圣的 金 银 和 器皿 都 带来,放在 神 殿 的府库里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, '那时,所罗门 将 以色列 的长老、 各 支派 的首领,并以色列 的族 长 招聚 到 耶路撒冷,要把 耶和华 的约 柜 从大卫 城─就是 锡安─运上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, '于 是以色列 众 人 在七 月 节 前都聚集 到 王那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, '以色列 众 长老 来到,利未人 便抬起 约柜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, '祭司 利未人 将 约柜 运上来,又将 会 幕 和 会幕 的 一切 圣 器具 都带上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, '所罗门 王 和聚集 到他那里 的以色列 全 会众 都在约柜 前 献 牛 羊为祭, 多得 不可 胜数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, '祭司 将 耶和华 的约 柜 抬 进 内 殿,就是 至 圣所,放在 两个基路伯 的翅膀 底下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, ' 基路伯 张著 翅膀 在 约柜之上, 遮掩 约柜 和 抬柜的杠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, '这杠 甚长,杠 头 在 内殿 前 可以看见,在殿外 却不能 看见,直到 如 今 还在 那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, '约柜 里惟有 两块 石版,就是 以色列 人 出 埃及后,耶和华 与 他们立约的时候,摩西 在何烈山 所 放的。除此以外,并无别物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, '当时,在那里 所有的 祭司 都已自洁,并不 分班 供职。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, ' 他们 出 圣所的时候,歌唱的 利未 人亚萨、希幔、耶杜顿,和他们的众子 众弟兄 都 穿 细麻布衣服,站 在坛 的东边,敲钹、鼓瑟、弹琴,同著他们 有一百 二十 个祭司 吹 号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, ' 吹号的、歌唱的 都一齐 发声,声 合为一,赞美 感谢 耶和华。吹号、敲钹,用各种乐 器,扬 声 赞美 耶和华说:耶和华 本为 善,他的慈爱 永远长存!那时,耶和华 的殿 有云 充满, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, '甚至祭司 不 能 站立 供职,因为 耶和华 的荣光 充满了 神 的殿。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, '那时,所罗门 说:耶和华 曾说 他必住 在幽暗之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, '但我 已经建造 殿宇 作你的 居所,为你永远 的住 处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, '王 转 脸 为 以色列 会众 祝福,以色列 会众 就都 站立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, '所罗门说:「耶和华─以色列的 神 是应当称颂的!因他 亲口 向 我父 大卫 所应许的,也亲手 成就了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, '他说:『自从 我领 我民 出埃及 地以来,我未 曾在以色列 众 支派 中选择 一城 建造 殿宇 为 我名 的居所,也未 曾拣选 一人 作 我民 以色列 的君; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, '但选择 耶路撒冷 为 我名 的居所,又拣选 大卫 治理 我民 以色列。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, '所罗门说:「我父 大卫 曾 立 意 要为耶和华─以色列 神 的名 建 殿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, '耶和华 却对 我父 大卫 说:『 你立 意 要为我的名 建 殿, 这意思 甚 好; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, '只是 你 不可 建 殿,惟 你 所生 的儿子 必 为我名 建 殿。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, '「现在耶和华 成就了 他所 应许 的话,使我 接续 我父 大卫 坐 以色列 的国位,是照耶和华 所 说的,又为耶和华─以色列 神 的名 建造 了殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, '我将 约柜 安置 在其中,柜内 有耶和华 的约,就是 他与 以色列 人 所立的约。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, '所罗门当著 以色列 会众,站 在耶和华 的坛 前,举起 手来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, '〈 所罗门 曾造 一个铜 台,长 五 肘,宽 五 肘,高 三 肘,放 在院 中〉就站 在台上,当著 以色列 的会众 跪 下,向天 举 手, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, '说:「耶和华─以色列的 神啊,天上 地下 没有 神 可比你的!你向那尽 心 行 在你面前 的仆人 守 约 施慈爱; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, '向你仆人─我父 大卫 所 应许的话现在 应验了。你亲口 应许,亲手 成就,正如今 日一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, '耶和华─以色列的 神啊,你所 应许 你仆人─我父 大卫 的话说:『 你的子孙 若 谨慎 自己的行为,遵守 我的律法,像你在我面前 所 行的一样,就不 断 人 坐 以色列 的国位。』现在 求你应验这话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, ' 耶和华─以色列的 神啊,求你成就 向你仆人 大卫 所 应许 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, '「 神 果真 与 世人 同住 在 地上吗?看哪,天 和天上 的天 尚且不足 你居住的,何况 我所 建 的这 殿呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, '惟求耶和华─我的 神 垂顾 仆人 的祷告 祈求,俯听 仆人 在你面前 的 祈祷 呼吁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, '愿  你 昼 夜 看顾 这 殿,就是 你应许 立 为你名的 居所;求你垂听 仆人 向 此 处 祷告 的 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, ' 你仆人 和 你民 以色列 向 此 处 祈祷的时候,求你 从 天上 你的居 所 垂听,垂听 而赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, '「人 若 得罪 邻舍,有人叫 他 起 誓,他来 到这 殿,在你的坛 前 起誓, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, '求你 从 天上 垂听, 判断 你的仆人,定恶人有罪,照他所行的 报 应 在他头上;定义人 有理,照他的义 赏赐 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, '「你的民 以色列 若 得罪 你,败 在仇敌 面前,又回心转意 承认 你的名,在这 殿里 向你 祈求 祷告, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, '求你 从 天上 垂听,赦免 你民 以色列 的罪,使他们归回 你赐 给他们 和他们列祖 之 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, '「你的民因 得罪 你, 你惩罚他们,使天 闭塞 不 下 雨,他们若向 此 处 祷告,承认 你的名,离开  他们的罪, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, '求你 在天上 垂听,赦免 你仆人 和你民 以色列 的罪, 将当行 的 善 道 指教他们,且降 雨 在 你的地,就是 你赐 给你民 为业之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, '「国中 若 有 饥荒、 瘟疫、 旱风、霉烂、蝗虫、蚂蚱,或 有仇敌 犯境,围困 城邑,无论遭遇什么 灾祸 疾病, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, '你的民 以色列,或是众 人,或是 一人, 自觉 灾祸 甚苦,向 这 殿 举 手,无论 祈求 什么,祷告 什么, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, '求你 从 天上 你的居 所 垂听 赦免。你是 知道 人心的,要照各人 所行 的待 他们( 惟有 你 知道 世 人 的心), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, '使 他们在 你赐 给我们列祖 之 地 上 一生 一世 敬畏你,遵行 你的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, '「 论到 不 属你民 以色列 的 外邦人, 为 你的大 名 和大能的 手,并伸出来的 膀臂,从远 方 而来,向 这 殿 祷告, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, '求你 从 天上 你的居 所 垂听,照著 外邦人 所 祈求 的而行,使 天下 万 民 都认识 你的名,敬畏 你,像你的民 以色列一样,又使他们知道 我建造 的 这 殿 是称为 你名 下的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, '「你的民 若 奉 你的差遣,无论往何处 去 与 仇敌 争战 ,向 你所 选择的 城 与我为你名 所 建造 的殿 祷告, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, '求你从 天上 垂听 他们的祷告 祈求,使他们得胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, '「你的民若 得罪 你( 世上没有 不 犯罪 的 人),你向他们 发怒,将他们交 给 仇敌 掳 到 或远 或 近 之地; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, '他们若在 掳到 之 地想起罪来,回 心 转意,恳求 你 说:『我们有罪了,我们悖逆了,我们作恶了』; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, '他们若在掳到 之地 尽 心 尽 性 归服 你,又向 自己的地,就是 你赐 给他们列祖 之地和你所 选择 的城,并我为你名 所 建造 的殿 祷告, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, '求你从 天上 你的居 所 垂听 你民的祷告 祈求,为他们伸冤,赦免他们 的 过犯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, '「我的 神啊,现在 求 你睁 眼看,侧耳 听 在此 处 所献的祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, '耶和华 神啊, 求你起来, 和你有能力的 约柜 同入安息之所。耶和华 神啊,愿 你的祭司 披上 救恩;愿 你的圣民 蒙福 欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, '耶和华 神啊,求你不要 厌弃 你的受膏者,要记念 向你仆人 大卫 所施的慈爱。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, '所罗门 祈祷 已毕,就有火 从天上 降下来,烧尽 燔祭 和别的祭。耶和华 的荣光 充满了 殿; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, '因 耶和华 的荣光 充满了 耶和华 殿,所以祭司 不 能 进 殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, '那火 降下、耶和华 的荣光 在 殿上的时候,以色列 众 人 看见,就在 铺石 地 俯 伏 叩拜,称谢 耶和华说:耶和华本为 善, 他的慈爱 永远长存! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, '王 和众 民 在耶和华 面前 献 祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, '所罗门 王 用牛 二万二千,羊 十二万 献 祭。这样,王 和众 民 为 神 的殿 行奉献之礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, '祭司 侍立,各供 其职;利未人 也拿著耶和华 的乐 器,就是 大卫 王 造出来、藉 借 利未人颂赞 耶和华的。( 他的慈爱 永远长存!) 祭司 在众人面前 吹号,以色列人 都 站立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, '所罗门 因 他所 造 的铜 坛 容 不 下 燔祭、 素祭,和 脂油,便将 耶和华 殿 前 院子 当中 分别为圣, 在那里 献 燔祭 和 平安祭牲 的脂油。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, '那 时 所罗门 和 以色列 众人,就是从哈马 口 直到 埃及 小河,所有的以色列人 都聚集成为大 会,守 节 七 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, '第八 日 设立 严肃会, 行 奉献 坛 的礼七 日,守节 七 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, '七 月 二十 三 日,王遣散 众民;他们因 见耶和华 向大卫 和所罗门 与他民 以色列 所 施 的恩惠,就都心中 喜乐,各归各家去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, '所罗门 造成了 耶和华 殿 和 王 宫;在耶和华 殿 和王宫 凡 他 心 中所要做的,都顺顺利利地做成了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, '夜间 耶和华 向 所罗门 显现,对他 说:「我已听了 你的祷告,也选择 这 地方 作为祭祀 我 的殿宇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, '我若 使天 闭塞 不 下 雨,或 使 蝗虫 吃 这地的出产,或 使 瘟疫 流行在我民中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, '这称 为 我名 下的 子民,若是自卑、祷告,寻求 我的面,转离 他们的恶 行,我 必从 天上 垂听,赦免 他们的罪,医治 他们的地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, ' 我必 睁 眼看、侧耳 听 在此 处 所献的祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, '现在 我已选择 这 殿,分别为圣,使 我的名 永 在其中,我的眼、我的心 也必 常 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, '你 若 在我面前 效法 你父 大卫 所 行的,遵行 我一切 所 吩咐你的,谨守 我的律例 典章, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, '我就必坚固 你的国 位,正如我与你父 大卫 所 立的约,说:『你的 子孙必不 断 人 作以色列 的王。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, '「倘若 你们 转去 丢弃 我指示 你们 的 律例 诫命,去 事奉 敬拜 别 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, '我就必将以色列人从 我赐 给他们 的 地上 拔出根来,并且 我为己名 所 分别为圣 的殿 也必舍弃 不 顾,使他 在万 民 中作笑谈,被讥诮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, '这 殿 虽然甚高,将来 经过的人 必惊讶 说:『耶和华 为何 向这 地 和这 殿 如此 行呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, '人必回答说:『是因 此地的人离弃 耶和华─他们列祖的 神,就是 领他们出 埃及 地的 神,去亲近 别 神,敬拜 事奉 他,所 以 耶和华 使 这 一切 灾祸 临到 他们。』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, ' 所罗门 建造 耶和华 殿 和 王宫, 二十 年 才完毕了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, '以后所罗门 重新修筑 希兰 送 给他 的那些 城邑,使 以色列 人 住 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, '所罗门 往哈马琐巴 去,攻取了 那地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, '所罗门 建造 旷野 里的达莫,又建造 哈马 所有的 积货 城, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, '又建造 上伯‧和仑 、 下伯‧和仑  作为保障,都有墙,有门,有闩; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, '又 建造巴拉 和 所有的 积货 城,并 屯车辆 马兵 的城,与耶路撒冷、黎巴嫩,以及 自己 治理 的全 国 中所 愿 意 建造的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, '至于  国中所 剩下 不 属以色列人 的 赫人、亚摩利人、比利洗人、希未人、耶布斯人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, '就是 以色列 人 未 曾灭绝的,所罗门挑取 他们的后裔 作 服苦的奴仆,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, '惟有以色列 人, 所罗门 不 使 他们当奴仆 做工,乃 是 作他的战  士、军长 的统领、车兵 长、马兵长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, ' 所罗门 王 有二百 五十 督 工的,监管 工人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, '所罗门 将 法老 的女儿 带出 大卫 城,上到为她 建造 的 宫里;因 所罗门说:「耶和华 约柜 所 到 之处 都为 圣地,所以我的 妻 不可 住 在以色列 王 大卫 的宫里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, ' 所罗门 在 耶和华 的坛上,就是在廊子 前 他所 筑的坛上,与耶和华 献 燔祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, '又遵著摩西 的吩咐 在安息日、月朔,并一年 三 节,就是除酵 节、七七 节、住棚 节,献 每 日 所当献的祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, '所罗门 照著他父 大卫 所定的例,派定 祭司 的班次,使他们各供 己事,又使利未人 各尽 其职,赞美耶和华,在祭司 面前 做 每 日 所当做的;又派守门的 按著班次 看守 各门,因为 神 人 大卫 是这样 吩咐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, '王 所吩咐 众祭司 和利未人的,无论 是管府库 或办别的事,他们都不 违背。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, '所罗门 建造耶和华 的殿,从 立根基 直到 成功 的日子, 工料 俱备。这样,耶和华 的殿 全然完毕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, '那时,所罗门 往以东 地 靠 海的以旬‧迦别 和 以禄 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, '希兰 差遣 他的臣仆,将船只 和熟悉 泛海 的仆人 送到所罗门那里。他们同著 所罗门 的仆人 到了 俄斐,得了 四 百 五十 他连得 金子,运 到 所罗门 王那里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, '示巴 女王 听见 所罗门 的名声,就来 到耶路撒冷,要用难解的话 试问 所罗门;跟随她的人 甚 多,又有骆驼 驮著 香料、宝 石,和许多 金子。她来 见了 所罗门,就把 心里 所 有的 对所罗门 都 说出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, '所罗门 将 她所问的 都 答上了,没有 一句 不明白、 不能 答的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, '示巴 女王 见 所罗门 的智慧 和他所 建造 的宫室、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, '席上 的珍馐美味、群臣 分列而坐、仆人 两旁侍立,以及他们的衣服装饰、酒政,和酒政的衣服装饰,又见他上 耶和华 殿 的 台阶,就诧异得 神 不 守 舍, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, '对 王 说:「我在本国 里所 听见 论到 你的事 和 你的智慧 实在是真的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, '我先不 信 那些话,及至 我来 亲眼 见了,才 知道你的大 智慧;人所告诉 我的,还不到 一半;你的实迹越 过 我所 听见 的名声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, ' 你的群臣、你的仆人 常 侍立 在你面前 听 你智慧 的话是有福的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, '耶和华─你的 神 是 应当称颂的!他 喜悦 你,使你 坐 他的国位,为耶和华─你的 神 作王;因为你的 神 爱 以色列人,要永远 坚立他们,所以立你 作他们 的王,使你秉公 行 义。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, '于 是示巴 女王 将一百 二十 他连得 金子 和宝 石,与极 多的 香料 送 给所罗门 王;她送 给王 的 香料,以后再没 有 这样的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, ' 希兰 的仆人 和所罗门 的仆人 从俄斐 运了 金子来,也运了 檀香 木(或译:乌木;下同)和宝 石来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, '王 用 檀香 木 为耶和华 殿 和王 宫 做 台,又为歌唱的人 做琴 瑟;犹大 地 从来 没有 见过 这样的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, '所罗门 王 按示巴 女王 所 带来的,还她礼物,另外 照她一切 所要 所 求的,都送 给她。于 是女王 和她臣仆 转回 本国 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, '所罗门 每 年 所 得的 金子 共有 六 百 六十 六 他连得, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, '另外 还有商 人 所进的金子,并且阿拉伯 诸 王 与属国 的省长 都带 金 银 给所罗门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, '所罗门 王 用锤出来的 金子 打成 挡牌 二百面, 每 面 用 金子 六 百舍客勒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, '又用锤出来的 金子 打成盾牌 三 百面, 每 面 用 金子 三 百舍客勒, 都放 在黎巴嫩 林 宫里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, '王 用象牙 制造 一个大 宝座,用精 金 包裹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, '宝座 有六层 台阶,又有金 脚凳,与宝座 相连。 宝座 两 旁 有扶手,靠近 扶手 有两个 狮子 站立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, '六 层台阶 上 有十 二 个狮子 站立,每层有两个:左边一个,右边一个;在列 国 中没有 这样 做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, '所罗门 王 一切的 饮 器 都是金的,黎巴嫩 林 宫 里的一切 器皿 都是精 金的。所罗门 年间,银子 算 不 了什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, '因为 王的 船只 与 希兰 的仆人 一同往 他施去;他施 船只 三 年 一次 装载 金、银、象牙、猿猴、孔雀 回来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, '所罗门 王 的财宝 与智慧 胜过 天下 的列 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, '普天下 的王 都 求 见 所罗门,要听 神 赐 给他 智慧的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, '他们 各 带 贡物,就是金 器、银 器、衣服、军械、香料、骡 马,每 年 有一定之例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, '所罗门 有 套车 的马 四 千 棚,有马兵 一万二千,安置 在屯车 的城邑 和耶路撒冷,就是 王那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, ' 所罗门 统管 诸 王,从 大河 到 非利士 地,直到 埃及 的边界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, '王 在耶路撒冷 使 银子 多如石头, 香柏木 多 如高原 的 桑树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, '有人从埃及 和各 国 为所罗门 赶 马群来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, '所罗门 其余 馀 的事,自始 至终,不 都 写 在 先知 拿单 的书 上和 示罗人 亚希雅 的预言书上,并先见 易多 论 尼八 儿子 耶罗波安 的默示书上吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, '所罗门 在耶路撒冷 作 以色列 众人 的王 共四十 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, '所罗门 与 他列祖 同睡,葬 在他父 大卫 城里。他儿子 罗波安 接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, '罗波安 往示剑 去,因为 以色列人 都 到了 示剑,要立他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, '尼八 的儿子 耶罗波安 先前 躲避 所罗门 王,逃往埃及,住在那里; 他听见这事, 就从埃及 回来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, '以色列人打发 人去请 他,他 就和以色列 众人 来 见 罗波安,对他说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, '「你父亲 使 我们负重轭 做苦工,现在 求你使 我们 做的苦 工 负的重 轭 轻松些,我们就事奉你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, '罗波安对他们 说:「 第三 日 再来 见我吧!」民 就去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, '罗波安之父 所罗门 在 世的日子,有 侍立 在他面前 的老年人,罗波安 王 和 他们商议,说:「你们 给我出个什么 主意,我好回 覆 复 这 民。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, '老年人 对他 说:「王若 恩待 这 民,使他们喜悦,用好 话 回复 他们,他们就永远 作 王的 仆人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, '王却不用 老年人 给他 出的主意,就和 那些 与他 一同长大、在他面前 侍立 的少年人 商议, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, '说:「这 民 对我 说:『你父亲 使 我们负 重轭, 求你使我们轻松 些』;你们 给我出个什么 主意,我好回 覆 复 他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, '那 同他 长大 的少年人 说:「 这民 对王 说:『你父亲 使我们负 重轭,求你 使我们 轻松些』;王要对他们 如此 说:「我的小拇指 比我父亲 的腰 还粗; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, ' 我父亲 使你们 负 重 轭,我 必使你们负 更重的 轭;我父亲 用鞭子 责打 你们,我 要用蝎子鞭责打你们。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, '耶罗波安 和众 百姓 遵著 罗波安 王 所说「你们第三 日 再来 见我」的那话,第三 日 他们果然来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, '罗波安 王 用严厉的 话回复他们, 不用 老年人 所出的主意, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, '照著少年人 所出的主意 对他们 说:「我父亲 使你们负重 轭,我 必使你们负 更重的轭;我父亲 用鞭子 责打 你们,我 要用蝎子鞭责打你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, '王 不肯 依 从 百姓;这事 乃 出于  神,为 要应验 耶和华 藉 借 示罗人 亚希雅 对 尼八 儿子 耶罗波安 所 说 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, '以色列 众民 见 王 不 依 从他们, 就 对 王 说:我们 与大卫 有什么 分儿呢?与耶西 的儿子 并没有 关涉!以色列人哪,各回 各家去吧! 大卫家啊,自己顾 自己吧!于 是,以色列 众人 都回自己家 里去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, '惟独住 在犹大 城邑 的以色列 人,罗波安 仍作他们 的王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, '罗波安 王 差遣 掌管 服苦之人 的 哈多兰往以色列人那里去,以色列 人 就用石头 打 死 他。罗波安 王 急忙 上 车,逃回 耶路撒冷去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, '这样,以色列人 背叛 大卫 家,直到 今 日。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, '罗波安 来到 耶路撒冷,招聚 犹大 家 和便雅悯家,共十八万人,都是挑选 的战  士,要与 以色列人 争战 ,好将 国 夺回 再归自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, '但耶和华 的话 临 到 神 人 示玛雅 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, '「你去告诉 所罗门 的儿子 犹大 王 罗波安 和 住犹大、便雅悯 的以色列 众人 说, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, '耶和华 如此 说:『你们不可 上去 与 你们的弟兄 争战 ,各 归 各家去吧!因为 这 事 出于 我。』」众人就听从 耶和华 的话 归回,不去 与 耶罗波安争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, '罗波安 住 在耶路撒冷,在犹大 地修筑 城邑, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, '为保障 修筑 伯利恒、 以坦、 提哥亚、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, '伯‧夙、 梭哥、 亚杜兰、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, ' 迦特、 玛利沙、 西弗、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, ' 亚多莱音、 拉吉、 亚西加、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, ' 琐拉、 亚雅仑 、 希伯仑 。这 都是犹大 和便雅悯 的坚固 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, '罗波安又坚固 各处的保障,在其中 安置 军长,又预备下 粮食、油、酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, '他在各 城 里预备盾牌 和枪,且使城极 其坚固。犹大 和便雅悯 都归了 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, '以色列 全 地 的 祭司 和利未人 都从四 方 来 归罗波安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, ' 利未人 撇下 他们的郊野 和产业,来到 犹大 与耶路撒冷,是因 耶罗波安 和他的儿子 拒绝他们,不许他们供祭司职分 事奉耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, '耶罗波安为邱坛、为鬼魔(原文是公山羊)、为自己 所 铸造 的牛犊 设立 祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, '以色列 各 支派中,凡立定 心意 寻求 耶和华─以色列 神的,都随从利未人,来到 耶路撒冷 祭祀 耶和华─他们列祖的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, '这样,就坚固 犹大 国,使 所罗门 的儿子 罗波安 强盛 三 年,因为 他们三 年 遵行 大卫 和所罗门 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, '罗波安 娶 大卫 儿子 耶利摩 的女儿 玛哈拉 为妻,又娶耶西 儿子 以利押 的女儿 亚比孩为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, '从她生了 几个儿子,就是 耶乌施、 示玛利雅、 撒罕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, '后来 又娶 押沙龙 的女儿 玛迦(十三章二节是乌列的女儿米该亚),从她生了 亚比雅、 亚太、 细撒、 示罗密。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, '罗波安 娶 十 八 个妻,立六十个 妾,生 二十 八 个儿子,六十个 女儿;他却爱 押沙龙 的女儿 玛迦,比爱别的 妻 妾更甚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, '罗波安 立 玛迦 的儿子 亚比雅 作太子,在他弟兄 中为首,因为 想要立他接续作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, '罗波安办事精明,使他众 子 分散 在犹大 和便雅悯 全 地 各 坚固 城里,又赐 他们 许多 粮食,为他们多 寻 妻子。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, ' 罗波安 的国 坚立,他强盛 的时候就离弃 耶和华 的律法,以色列人 也都 随从他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, ' 罗波安 王 第五 年,埃及 王 示撒 上来 攻打 耶路撒冷,因为 王和民得罪了 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, '示撒带战 车 一千 二百辆,马兵 六万,并且 跟从他 出 埃及 的路比人、苏基人,和古实人, 多得不可 胜数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, '他攻取了 犹大 的 坚固 城,就来 到 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, '那时,犹大 的首领 因为 示撒 就聚集 在 耶路撒冷。有先知 示玛雅 去 见 罗波安 和众首领,对他们 说:「耶和华 如此 说:『你们 离弃了 我, 所以我 使你们 落 在示撒 手里。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, '于 是王 和以色列 的众首领 都自卑 说:「耶和华 是公义的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, '耶和华 见 他们自卑,耶和华 的话 就临 到 示玛雅 说:「他们既自卑,我必不 灭绝他们;必使他们 略 得 拯救,我不 藉 借著示撒 的手 将我的怒气 倒 在耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, '然而 他们必作 示撒的 仆人,好叫他们知道,服事 我与服事 外邦人有何分别。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, '于 是,埃及 王 示撒 上来 攻取 耶路撒冷,夺了 耶和华 殿 和 王 宫 里的宝物, 尽都 带走,又夺去 所罗门 制造 的 金 盾牌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, '罗波安 王 制造 铜 盾牌 代替那金盾牌,交 给 守 王 宫 门 的护卫 长看守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, ' 王 每逢 进 耶和华 的殿,护卫兵 就 拿这盾牌,随后仍将盾牌送回,放在 护卫 房。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, '王自卑的时候,耶和华 的怒气 就转消了,不 将他灭 尽,并且 在犹大 中间也有 善益 的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, '罗波安 王 自强,在耶路撒冷 作王。 他登基 的时候年 四十 一 岁,在耶路撒冷,就是 耶和华 从以色列 众 支派 中所选择 立 他名的 城,作王 十 七 年。罗波安的母亲 名 叫拿玛,是亚扪人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, '罗波安行 恶,因 他不 立定 心意 寻求 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, '罗波安 所行的事,自始 至终 不 都 写 在先知 示玛雅 和先见 易多 的史记上吗?罗波安 与耶罗波安 时常 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, '罗波安 与 他列祖 同睡,葬 在大卫 城里。他儿子 亚比雅 接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, '耶罗波安 王 十 八 年,亚比雅 登基 作 犹大王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, '在耶路撒冷 作王 三 年。他母亲 名叫 米该亚(又作玛迦),是 基比亚人 乌列 的女儿。 亚比雅 常与 耶罗波安 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, '有一次亚比雅 率领挑选的 兵 四十万 摆 阵,都是勇敢的 战  士;耶罗波安 也挑选 大能的 勇 士 八十万,对 亚比雅摆 阵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, '亚比雅 站 在 以法莲 山地 中的 洗玛脸 山上,说:「耶罗波安 和以色列 众人哪,要听我说! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, ' 耶和华─以色列的 神 曾立盐 约(盐就是不废坏的意思),将 以色列 国 永远 赐 给大卫 和他的子孙,你们 不 知道吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, '无奈大卫 儿子 所罗门 的臣仆、尼八 儿子 耶罗波安 起来 背叛 他的主人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, '有些无赖 的匪 徒 聚集 跟从他,逞强 攻击 所罗门 的儿子 罗波安;那时罗波安 还 幼 弱,不能 抵挡 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, '「现在 你们 有意 抗拒 大卫 子孙 手下 所治耶和华 的国,你们 的人也甚 多,你们那里又有 耶罗波安 为你们 所 造 当作神 的金 牛犊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, '你们不是 驱逐 耶和华 的祭司 亚伦 的后裔 和利未人吗?不是照著外邦 人 的恶俗为自己 立 祭司吗?无论何人 牵 一只公 牛 犊、七只 公绵羊 将自己分别出来,就可作 虚无 之神 的祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, '至于 我们,耶和华是我们的 神,我们并没有 离弃他。我们有事奉 耶和华 的祭司,都是亚伦 的后裔,并有利未人 各尽其职, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, '每日 早 晚 向耶和华 献 燔祭,烧美 香,又在 精金 的桌子 上摆陈设 饼;又有金 灯台 和灯盏,每 晚 点起,因为 我们 遵守 耶和华─我们 神 的命;惟有你们 离弃了 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, ' 率领 我们的是 神,我们这里也有 神 的祭司 拿号 向你们 吹出 大声。以色列 人哪,不要 与 耶和华─你们列祖的 神 争战 ,因 你们必不能 亨通。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, '耶罗波安 却在 犹大人的后头 设 伏兵。这样,以色列人在 犹大人 的前头,伏兵 在犹大人的后头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, '犹大人 回头观看,见 前 后都有敌兵,就呼求 耶和华,祭司 也吹 号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, '于 是犹大 人 呐喊; 犹大 人 呐喊的时候, 神 就使 耶罗波安 和以色列 众人 败 在亚比雅 与犹大人 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, '以色列 人 在犹大人 面前 逃跑, 神 将他们交 在犹大人手里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, '亚比雅 和他的军兵 大大 杀戮 以色列人,以色列人 仆倒 死亡 的精 兵 有五十万。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, '那 时,以色列 人 被制伏了,犹大 人 得胜,是因 倚靠 耶和华─他们列祖的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, '亚比雅 追 赶 耶罗波安,攻取了 他的 几座城,就是 伯特利 和 属伯特利的镇市, 耶沙拿 和 属耶沙拿的镇市, 以法拉音(或译:以弗伦)和属以法拉音的镇市。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, '亚比雅 在世的时候,耶罗波安 不能 再 强盛;耶和华 攻击他,他就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, '亚比雅 却渐渐强盛,娶 妻妾 十 四个,生了 二十 二 个儿子,十 六 个女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, '亚比雅 其余 馀 的事 和他的言 行 都写在 先知 易多 的传上。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, '亚比雅 与 他列祖 同睡,葬 在大卫 城里。他儿子 亚撒 接续他 作王。亚撒年间,国中 太平 十 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, '亚撒 行 耶和华─他 神 眼中 看为善 为正的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, '除掉 外邦 神的坛 和邱坛,打碎 柱像,砍下 木偶, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, '吩咐 犹大人 寻求 耶和华─他们列祖的 神,遵行 他的律法、诫命; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, '又在犹大 各 城邑 除掉 邱坛 和 日像,那时国 享太平; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, '又在犹大 建造了 几座坚固 城。 国中 太平 数 年,没有 战 争,因为 耶和华 赐他 平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, '他对犹大人 说:「我们要建造 这些 城邑,四围 筑墙,盖楼,安门,做闩;地 还属我们,是因 寻求 耶和华─我们的 神;我们既寻求他,他就赐我们 四境 平安。」于 是建造城邑,诸事亨通。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, ' 亚撒的 军兵,出自犹大 拿 盾牌 拿枪 的三十万人;出自便雅悯 拿 盾牌 拉 弓 的二十八万人。这 都是 大能的 勇士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, '有古实 王谢拉 率领军兵 一百万,战 车 三 百辆,出来 攻击犹大人,到 了 玛利沙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, '于 是亚撒 出去 与他迎敌,就在玛利沙的 洗法 谷 彼此摆 阵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, '亚撒 呼求 耶和华─他的 神 说:「耶和华啊,惟有你 能帮助 软弱的,胜过 强盛的。耶和华─我们的 神啊,求你帮助我们;因为 我们仰赖 你,奉你的名 来 攻击 这 大军。耶和华啊,你是我们的 神,不要 容人 胜过 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, '于 是耶和华 使 古实人 败 在亚撒 和犹大人 面前,古实人 就逃跑了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, '亚撒 和跟随他 的 军兵 追赶他们,直到 基拉耳。古实人 被杀的甚多,不能 再强盛,因为 败 在耶和华 与他军兵 面前。犹大人就夺了 许多 财物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, '又打破 基拉耳 四围 的城邑; 耶和华 使 其中的人 都甚恐惧。犹大人又将 所有的 城 掳掠一空,因 其中 的财物 甚多, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, '又 毁坏了 群畜 的圈,夺取 许多的 羊 和骆驼,就回 耶路撒冷去了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, '神 的灵 感动 俄德 的儿子 亚撒利雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, '他出来 迎接 亚撒,对他 说:「亚撒 和犹大、便雅悯 众人哪,要听我说:你们若顺从 耶和华,耶和华 必与你们同在;你们若 寻求他,就必寻见;你们若 离弃他,他必离弃 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, '以色列人 不 信真 神,没有 训诲 的祭司,也没有 律法,已经好久了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, '但他们 在急难 的时候归 向 耶和华─以色列的 神,寻求他,他就被他们 寻见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, '那 时,出 入 的人不得 平安, 列 国 的居民 都遭 大 乱; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, '这国 攻击 那国,这城 攻击那城,互相破坏,因为 神 用各样 灾难 扰乱他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, '现在你们 要刚强,不要 手 软,因 你们所行的 必得 赏赐。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, '亚撒 听见 这 话 和俄德 儿子 先知 亚撒利雅的预言,就壮起胆来,在犹大、便雅悯 全 地,并以法莲 山地 所 夺 的各 城,将可憎之物 尽都除掉,又在耶和华 殿的 廊 前 重新修筑 耶和华 的坛; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, '又招聚 犹大、便雅悯 的众人,并他们中间 寄居 的以法莲人、玛拿西人、西缅人。有 许多 以色列人 归降 亚撒,因见 耶和华─他的 神 与他同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, '亚撒 十 五 年 三 月,他们都聚集 在耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, '当 日 他们从 所取的 掳物中,将牛 七 百只、羊 七 千 只献 给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, '他们就立 约,要尽 心 尽 性 地寻求 耶和华─他们列祖的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, '凡 不 寻求 耶和华─以色列 神的,无论 大 小、男 女,必被治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, '他们就大 声 欢呼,吹号 吹角,向耶和华 起誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, '犹大 众人 为 所起的誓 欢喜;因 他们是尽 心 起誓,尽 意 寻求耶和华,耶和华 就被他们 寻见,且赐他们 四境 平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, ' 亚撒 王 贬了 他祖母 玛迦 太后的位,因 她造了 可憎的偶像 亚舍拉。亚撒 砍下 她的偶像,捣得粉碎,烧 在汲沦 溪边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, '只是邱坛 还没有 从以色列 中废去,然而 亚撒 的心 一 生 诚实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, '亚撒将 他父 所分别为圣、与自己所分别为圣 的金 银 和器皿 都奉到 神 的殿里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, '从这时直到 亚撒 三十 五 年,都没 有 争战 的事。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, '亚撒 三十 六 年,以色列 王 巴沙 上来 攻击 犹大,修筑 拉玛,不 许 人从犹大 王 亚撒 那里出 入。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, '于 是亚撒 从耶和华 殿 和王 宫 的府库 里拿出 金 银来,送 与 住 大马士革 的亚兰 王便‧哈达,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, '「 你父 曾与 我父立约,我 与你 也要立约。 现在我将金 银 送 给你, 求你废掉 你与 以色列 王 巴沙 所立的约,使他离开  我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, '便‧哈达 听 从 亚撒 王的话,派 军 长 去攻击 以色列 的城邑。他们就攻破 以云、 但、亚伯‧玛音,和 拿弗他利 一切的 积货 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, ' 巴沙 听见 就停 工,不 修筑 拉玛了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, '于 是亚撒 王 率领 犹大 众人,将 巴沙 修筑 拉玛 所 用的石头、 木头 都运去,用以 修筑 迦巴 和 米斯巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, '那 时,先见 哈拿尼 来 见 犹大 王 亚撒,对他 说:「因你仰赖 亚兰 王,没有 仰赖 耶和华─你的 神,所 以 亚兰 王 的军兵 脱离了 你的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, '古实人、路比人 的军队 不 是 甚大吗?战 车 马兵 不是极 多吗?只因你仰赖 耶和华,他便将他们交 在你手里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, ' 耶和华 的眼目 遍察 全 地,要显大能 帮助 向他 心 存诚实的人。你 这 事行得愚昧; 此后,你 必有 争战 的事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, '亚撒 因 此 恼恨 先见,将他囚 在监里。那 时 亚撒 也虐待 一些 人民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, ' 亚撒 所行的事,自始 至终 都写 在 犹大 和以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, '亚撒 作王 三十 九 年,他脚上 有病,而且 甚 重。 病 的时候没有 求 耶和华,只 求医生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, '他 作王 四十 一 年 而死,与 他列祖 同睡, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, '葬 在大卫 城 自己 所 凿 的坟墓里,放 在床上,其床 堆满 各样 馨香的香料,就是按做香的 作法 调和的香料,又为他 烧了 许 多 的物件。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, '亚撒的儿子 约沙法 接续他 作王,奋勇自强,防备 以色列人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, '安置 军兵 在犹大 一切 坚固 城里,又安置 防兵 在犹大 地 和他父 亚撒 所 得 以法莲 的城邑中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, '耶和华 与 约沙法 同在;因为 他行 他祖 大卫 初 行的道,不 寻求 巴力, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, '只 寻求 他父亲的 神,遵行 他的诫命,不 效法以色列人 的行为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, '所以耶和华 坚定 他的国,犹大 众人 给他 进 贡;约沙法 大 有 尊荣 资财。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, '他高兴 遵行耶和华 的道,并且 从犹大 除掉 一切邱坛 和 木偶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, '他作王 第三 年,就差遣 臣子 便亥伊勒、俄巴底、撒迦利雅、拿坦业、米该亚 往犹大 各城 去教训百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, '同著他们 有利未人 示玛雅、尼探雅、西巴第雅、亚撒黑、示米拉末、约拿单、亚多尼雅、多比雅、驼巴多尼雅,又有祭司 以利沙玛、约兰 同著他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, ' 他们带著 耶和华 的律法 书,走 遍 犹大 各城 教训 百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, ' 耶和华 使 犹大 四围 的 列 国 都甚恐惧,不敢 与 约沙法 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, '有些 非利士人 与约沙法 送 礼物,纳贡 银。阿拉伯人 也 送 他 公 绵羊 七 千 七 百只,公山羊 七 千 七 百只。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, ' 约沙法 日渐 强 大,在犹大 建造 营寨 和积货 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, '他 在犹大 城邑 中有 许多 工程,又在耶路撒冷 有战  士,就是大能的 勇士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, '他们的数目,按著宗 族,记在下面:犹大 族的千夫 长 押拿 为首 率领 大能的 勇士─三十万; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, '其次是,千夫长 约哈难 率领大能的勇士─二十八万; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, '其次是,细基利 的儿子 亚玛斯雅〈他为耶和华 牺牲自己〉率领 大能的 勇士─二十万。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, '便雅悯 族,是大能的 勇士 以利雅大 率领 拿 弓箭 和盾牌的─二十万; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, '其次是,约萨拔 率领 预备 打仗的─十八万。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, '这 都是伺候 王的,还有王 在犹大 全地 坚固 城 所 安置 的不在其内。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, '约沙法 大 有 尊荣 资财,就与亚哈 结亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, '过了 几年,他下到 撒马利亚 去见 亚哈;亚哈 为他 和跟从他 的 人 宰了 许多 牛 羊,劝他 与自己同去 攻取 基列 的拉末。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, '以色列 王 亚哈 问 犹大 王 约沙法 说:「你肯同我 去 攻取基列 的拉末吗?」他回答说:「你 我不分彼此,我的民 与你的民一样,必与你 同去争战 。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, '约沙法 对 以色列 王 说:「请 你先 求问 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, '于 是以色列 王 招聚 先知 四 百 人,问他们 说:「我们上去 攻取 基列 的拉末 可以 不可以?」他们说:「可以上去,因为 神 必将那城交 在王 的手里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, '约沙法 说:「这里 不是 还 有耶和华的 先知,我们可以求问 他吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, '以色列 王 对 约沙法 说:「还有 一个 人,是 音拉 的儿子 米该雅。我们可以托 讬他 求问 耶和华,只是我 恨他;因为 他指著我 所说的预言,不 说吉语, 常 说凶言。」约沙法 说:「王 不必 这样 说。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, '以色列 王 就召了 一个 太监来,说:「你快去 将音拉 的儿子 米该雅召来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, '以色列 王 和犹大 王 约沙法 在撒马利亚 城门 前 的空场上,各 穿 朝服 坐 在 位上,所有的 先知 都在他们面前 说预言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, '基拿拿 的儿子 西底家 造了 两个铁 角,说:「耶和华 如此 说:『你要用这角 抵触 亚兰人,直到 将他们灭尽。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, '所有的 先知 也都这样 预言 说:「可以上 基列 的拉末去,必然得胜,因为耶和华 必将那城交 在王 的手中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, '那 去 召 米该雅 的使者 对米该雅 说:「 众先知 一 口 同音地都向 王 说吉 言, 你不如与他们 说一样 的话,也说 吉言。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, '米该雅 说:「我指著永生的 耶和华起誓,我的 神 说 什么,我就说 什么。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, '米该雅到 王面前,王 问他 说:「米该雅啊,我们上去 攻取 基列 的拉末 可以 不可以?」他说:「可以上去,必然得胜,敌人必交 在你们手里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, '王 对他 说:「我 当嘱咐你 几 次,你才 奉耶和华 的名 向我 说 实话呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, '米该雅说:「我看见 以色列 众民 散 在 山上,如同 没有 牧人 的羊群一般。耶和华 说:『这民 没有 主人,他们可以平平安安地 各 归 各家去。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, '以色列 王 对 约沙法 说:「我岂没有 告诉 你,这人指著我 所说的预言,不 说吉语,单 说凶言吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, '米该雅说:「 你们要听 耶和华 的话。我看见 耶和华 坐 在 宝座上,天上 的万 军 侍立 在 他左 右。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, '耶和华 说:『谁 去引诱 以色列 王 亚哈 上 基列 的拉末 去阵亡呢?』这个 就这样 说,那个 就那样 说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, '随后,有一个神灵 出来,站 在耶和华 面前 说:『我 去引诱他。』耶和华 问他 说:『你用何法呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, '他说:『我去,要在他众 先知 口中 作 谎言 的灵。』耶和华说:『这样,你必 能 引诱他,你去 如此 行吧!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, '现在 耶和华 使 谎言 的灵 入了你这些 先知 的口,并且耶和华 已经命定 降祸 与你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, '基拿拿 的儿子 西底家 前来 打 米该雅 的 脸,说:「耶和华 的灵 从哪里 离开  我 与你 说话呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, '米该雅 说:「你 进 严密的 屋子 藏躲 的 那 日,就必看见了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, '以色列 王 说:「将 米该雅 带 回,交给 邑 宰 亚们 和 王 的儿子 约阿施,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, '『王 如此 说:把 这个 人下 在监里,使他受苦,吃 不饱 喝不足,等候 我平平安安地 回来。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, '米该雅 说:「你若 能 平安 回来,那就是耶和华 没有 藉 借我 说这话了」;又说:「众民哪,你们都 要听!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, '以色列 王 和犹大 王 约沙法 上 基列 的拉末 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, '以色列 王 对 约沙法 说:「我要改装 上 阵,你 可以仍穿 王服。」于 是以色列 王 改装,他们就上 阵去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, '先是亚兰 王 吩咐 车兵 长 说:「他们的兵将,无论 大 小,你们都不可 与他们争战 , 只要 与 以色列 王争战 。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, ' 车兵 长 看见 约沙法便 说,这必是 以色列 王,就转过去 与他 争战 。约沙法 一呼喊,耶和华 就帮助他, 神 又感动 他们离开 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, ' 车兵 长 见 不 是 以色列 王,就转去 不追他了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, '有一人 随便 开  弓,恰巧射入 以色列 王 的 甲 缝 里。王对赶车的 说:「 我受了重伤,你转过车来,拉我 出 阵吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, '那 日 阵势 越战 越猛,以色列 王勉强 站 在车上 抵挡 亚兰人,直到 晚上。约在日 落 的时候,王就死了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, '犹大 王 约沙法 平平安安地 回 耶路撒冷,到 宫里去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, '先见 哈拿尼 的儿子 耶户 出来 迎接 约沙法 王,对他 说:「你岂当帮助 恶人,爱 那恨恶 耶和华的人呢?因此 耶和华 的忿怒 临到你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, '然而 你 还有 善 行,因 你从 国中 除掉 木偶,立定 心意 寻求 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, '约沙法 住 在耶路撒冷,以后又 出巡 民间,从别是巴 直到 以法莲 山地,引导民归 向 耶和华─他们列祖的 神; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, '又在犹大 国 中遍 地的坚固 城 里设立 审判官, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, '对 他们 说:「你们 办 事 应当谨慎;因为 你们判断 不是 为人,乃是 为耶和华。判断的时候,他必与你们同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, '现在 你们 应当 敬畏 耶和华,谨慎 办事;因为耶和华─我们的 神 没有 不义,不偏待 人,也不受 贿赂。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, ' 约沙法 从 利未人 和祭司,并以色列 族 长 中派定人,在耶路撒冷 为耶和华 判断,听民间的争讼,就回 耶路撒冷去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, '约沙法嘱咐 他们 说:「你们当敬畏 耶和华,忠心 诚实 办事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, '住 在各城里 你们的弟兄,若有 争讼的事 来 到你们这里,或 为 流血,或 犯律法、诫命、律例、典章,你们要警戒 他们,免得 他们得罪 耶和华,以致他的忿怒 临 到你们 和 你们的弟兄;这样 行,你们就没有 罪了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, '凡属 耶和华 的事, 有大 祭司 亚玛利雅 管理你们;凡属 王 的事,有犹大 支派 的族长 以实玛利 的儿子 西巴第雅管理你们;在你们面前 有利未人 作官长。你们应当壮胆 办事,愿 耶和华 与 善人 同在。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, ' 此后,摩押 人 和亚扪 人,又有米乌尼人,一同 来 攻击 约沙法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, '有人来 报告 约沙法 说:「从海 外 亚兰(又作以东)那边有大 军 来 攻击你,如今他们在哈洗逊‧他玛,就是隐‧基底。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, '约沙法 便惧怕,定 意 寻求 耶和华,在 犹大 全 地 宣告 禁食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, '于 是犹大人 聚会,求 耶和华帮助。 犹大 各 城 都有人出来 寻求 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, '约沙法 就在犹大 和耶路撒冷 的会中,站 在耶和华 殿 的新 院 前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, '说:「耶和华─我们列祖的 神啊,你 不 是 天上的 神吗?你 不是万 邦 万国 的主宰吗?在你手中 有大能 大力,无人 能抵挡 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, '我们的 神啊,你 不是 曾在你民 以色列人 面前 驱逐 这 地 的居民,将这地赐 给你朋友 亚伯拉罕 的后裔 永远为业吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, '他们住 在这地,又为你的名 建造 圣所,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, '『倘有 祸患 临 到我们,或刀兵 灾殃,或瘟疫 饥荒,我们在急难的时候,站 在这 殿 前 向你 呼求,你必垂听 而拯救,因为 你的名 在这 殿里。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, '从前以色列人出 埃及 地的时候,你不 容 以色列人 侵犯 亚扪 人、摩押人,和西珥 山人,以色列人就 离开  他们,不 灭绝他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, '看哪,他们 怎样报复 我们,要来 驱逐我们 出离你的地,就是 你赐给我们为业之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, '我们的 神啊,你不 惩罚 他们吗?因为 我们 无 力 抵挡 这 来 攻击我们 的大 军,我们 也不 知道 怎样 行, 我们的眼目 单仰望你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, '犹大 众人 和 他们的婴孩、妻子、儿女 都站 在耶和华 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, '那时,耶和华 的灵 在会 中 临 到 利未人 亚萨 的 后裔─玛探雅 的玄孙,耶利 的曾孙,比拿雅 的孙子,撒迦利雅 的儿子 雅哈悉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, '他说:「犹大 众人、耶路撒冷 的居民,和约沙法 王,你们请听。耶和华 对你们 如此 说:『 不要 因 这 大 军 恐惧 惊惶;因为 胜败 不 在乎你们,乃在乎 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, '明日 你们要下去 迎敌,他们 是从洗斯 坡 上来,你们必在耶鲁伊勒 旷野 前 的谷 口 遇见 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, '犹大 和耶路撒冷人哪,这次 你们 不要 争战 ,要摆阵 站著,看 耶和华 为你们 施行拯救。不要 恐惧,也不要 惊惶。明日 当出去 迎敌,因为耶和华 与你们同在。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, '约沙法 就面 伏 于 地,犹大 众人 和耶路撒冷 的居民 也俯伏 在耶和华 面前,叩拜 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, '哥辖 族 和可拉 族 的利未人 都起来,用极 大的 声音 赞美 耶和华 以色列的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, '次日清早,众人起来 往提哥亚 的旷野 去。出去的时候,约沙法 站著 说:「犹大人 和耶路撒冷 的居民哪,要听我说:信 耶和华─你们的 神 就必立稳;信 他的先知 就必亨通。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, '约沙法既与 民 商议了,就设立 歌唱的人,颂赞 耶和华,使他们穿上圣洁 的礼服,走 在军 前 赞美耶和华说:「当称谢 耶和华,因 他的慈爱 永远长存!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, '众人方 唱歌 赞美 的时候,耶和华 就派 伏兵 击杀 那来 攻击犹大人 的亚扪 人、摩押人,和西珥 山人,他们就被打败了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, '因为亚扪 人 和摩押 人起来,击杀 住 西珥 山的人,将他们灭 尽;灭尽 住 西珥山的人之后,他们又彼此 自相 击杀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, '犹大人 来 到 旷野的 望楼,向 那大军 观看,见 尸 横 遍地,没有 一个逃脱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, '约沙法 和他的百姓 就来 收取 敌人的财物,在 尸首 中见了 许多 财物、珍 宝,他们剥脱下来 的多得不可 携带;因为 甚 多, 直收取了 三 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, '第四 日 众人聚集 在比拉迦 谷(就是称颂的意思), 在那里 称颂 耶和华。因 此 那 地方 名 叫 比拉迦 谷,直到 今日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, ' 犹大 人 和耶路撒冷 人都 欢欢喜喜地 回 耶路撒冷,约沙法 率领他们;因为 耶和华 使他们战 胜仇敌,就欢喜快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, '他们弹琴、鼓瑟、吹号 来到 耶路撒冷,进了 耶和华 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, ' 列邦 诸 国 听见 耶和华 战 败 以色列 的仇敌,就 甚惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, '这样,约沙法 的国 得享太平,因为 神 赐他 四境 平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, '约沙法 作 犹大 王,登基 的时候年 三十 五 岁,在耶路撒冷 作王 二十 五 年。他母亲 名叫 阿苏巴,乃示利希 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, '约沙法效法 他父 亚撒 所行的,不 偏 左右,行 耶和华 眼中 看为正的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, '只是 邱坛 还没有 废去,百姓 也 没有 立定 心意 归向他们列祖的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, '约沙法 其余 馀 的事,自始 至终 都 写 在哈拿尼 的儿子 耶户 的书上,也 载 入 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, '此后,犹大 王 约沙法 与 以色列 王 亚哈谢 交好;亚哈谢 行 恶太甚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, '二王 合伙 夥 造 船 要往他施 去,遂在以旬.迦别 造 船。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, '那时玛利沙人、多大瓦 的儿子 以利以谢 向 约沙法 预言 说:「因你与 亚哈谢 交好,耶和华 必破坏 你所造的。」后来那船 果然破坏,不 能 往 他施 去了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, '约沙法 与 他列祖 同睡,葬 在大卫 城 他列祖的坟地里。他儿子 约兰 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, '约兰有 几个兄弟,就是约沙法 的儿子 亚撒利雅、耶歇、撒迦利雅、亚撒列夫、米迦勒、示法提雅。这 都是 犹大 王 约沙法 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, '他们的父亲 将许多 金 银、财宝,和 犹大 地的坚固 城 赐 给他们;但将 国 赐 给约兰,因为 他 是长子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, '约兰 兴起 坐 他父 的位,奋勇自强,就用刀 杀了 他的众 兄弟 和 以色列 的几个首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, '约兰 登基 的时候年 三十 二 岁,在耶路撒冷 作王 八 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, '他行 以色列 诸王 的道,与 亚哈 家一样;因 他 娶了亚哈 的女儿 为 妻,行 耶和华 眼中 看为恶的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, '耶和华 却因 自己与大卫 所 立 的约,不 肯 灭 大卫 的家,照他所 应许的,永远 赐 灯光 与大卫 和他的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, '约兰年间,以东人 背叛 犹大,脱离 他的权下,自己 立 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, ' 约兰 就率领 军长 和 所有的 战 车, 夜间 起来,攻击 围困 他 的以东人 和 车兵 长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, '这样,以东人 背叛 犹大,脱离 他的权下,直到 今 日。那 时,立拿人 也 背叛了,因为 约兰离弃 耶和华─他列祖的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, '他 又 在犹大 诸山 建筑 邱坛,使 耶路撒冷 的居民 行邪淫,诱惑 犹大人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, '先知 以利亚 达 信 与 约兰说:「耶和华─你祖 大卫的 神 如此 说:『因为 你不 行 你父 约沙法 和犹大 王 亚撒 的道, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, '乃行 以色列 诸王 的道,使 犹大人 和 耶路撒冷 的居民 行邪淫,像亚哈 家一样,又 杀了 你父 家 比你 好的 诸兄弟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, '故此, 耶和华 降 大 灾 与你的百姓 和你的妻子、儿女,并你一切 所有的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, ' 你的肠子 必患病,日 加 沉重,以致 你的肠子 坠落下来。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, '以后,耶和华 激动 非利士人 和靠近 古实 的 阿拉伯人 来攻击 约兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, '他们上来 攻击犹大,侵入境内,掳掠了 王 宫 里所有的 财货 和他的妻子、 儿女,除了 他小 儿子 约哈斯(又名亚哈谢)之外,没有 留下 一个儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, '这些 事以后,耶和华 使约兰的肠子 患 不能 医治 的病。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, ' 他患此病 缠绵 日久, 过了 二 年,肠子 坠落下来,病 重 而死。他的民 没有 为他 烧什么物件,像从前为他列祖 所烧的一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, ' 约兰登基 的时候年 三十 二岁,在耶路撒冷 作王 八 年。他去世 无人 思慕,众人葬 他在大卫 城,只是不 在列王 的坟墓里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, '耶路撒冷 的居民 立 约兰的小 儿子 亚哈谢 接续他 作王;因为 跟随阿拉伯人 来 攻营 的军兵 曾杀了 亚哈谢的众 兄长。这样,犹大 王 约兰 的儿子 亚哈谢 作了王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, '亚哈谢 登基 的时候年 四十 二 岁(列王下八章二十六节是二十二岁),在耶路撒冷 作王 一 年。他母亲 名叫 亚她利雅,是暗利 的孙女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, '亚哈谢 也 行 亚哈 家 的道;因为 他母亲 给他主谋,使他行恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, '他行 耶和华 眼中 看为恶的事,像亚哈 家一样;因 他父亲 死 后 有 亚哈家的人 给他 主谋,以致败坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, ' 他听从 亚哈家的计谋,同 以色列 王 亚哈 的儿子 约兰 往基列 的拉末 去,与 亚兰 王 哈薛 争战 ;亚兰人 打伤了 约兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, '约兰回 到耶斯列,医治 在拉末 与 亚兰 王 哈薛 打仗 所 受的 伤,犹大 王 约兰 的儿子 亚撒利雅(就是亚哈谢)因为 亚哈 的儿子 约兰 病了,就下 到耶斯列 看望 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, '亚哈谢 去 见 约兰 就被害了,这是出乎 神;因为他到了,就同 约兰 出去 攻击 宁示 的孙子 耶户。这耶户 是耶和华 所膏、使他剪除 亚哈 家的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, ' 耶户 讨 亚哈 家 罪的时候,遇见 犹大 的众首领 和亚哈谢 的众姪子 服事 亚哈谢,就把他们都杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, '亚哈谢 藏 在撒马利亚,耶户寻找 他,众人将他拿住,送 到 耶户那里,就杀了他,将他葬埋;因 他们说,他 是那 尽 心 寻求 耶和华 之约沙法 的儿子。这样,亚哈谢 的家 无 力 保守 国权。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, '亚哈谢 的母亲 亚她利雅 见 她儿子 死了,就起来 剿灭 犹大 王 室。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, '但王 的女儿 约示巴 将 亚哈谢 的儿子 约阿施 从那被杀 的王 子 中 偷出来,把他 和 他的乳母 都藏 在卧 房里。 约示巴 是 约兰 王 的女儿,亚哈谢 的妹子,祭司 耶何耶大 的妻。她 收藏约阿施,躲避 亚她利雅,免得 被杀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, ' 约阿施和她们 一同藏在 神 殿 里六 年;亚她利雅 篡了 国位。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, '第七 年,耶何耶大 奋勇自强,将 百夫 长 耶罗罕 的儿子 亚撒利雅,约哈难 的儿子 以实玛利,俄备得 的儿子 亚撒利雅, 亚大雅 的儿子 玛西雅, 细基利 的儿子 以利沙法 召来,与他们 立约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, '他们走遍 犹大,从犹大 各 城 里招聚 利未人 和以色列的 众族 长 到 耶路撒冷 来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, ' 会众在 神 殿 里与 王 立 约。耶何耶大对他们 说:「看哪,王 的儿子 必当作王,正如 耶和华 指著 大卫 子孙 所应许的话」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, '又说:「你们当 这 样 行:祭司 和利未人 凡安息日 进班的,三分之一 要把守 各门, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, '三分之一 要在王 宫,三分之一 要在基址 门;众 百姓 要在耶和华 殿 的院内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, '除了 祭司 和供职 的利未人之外,不准 别人进 耶和华 的殿;惟独他们 可以进去,因为 他们 圣洁。众 百姓 要遵守 耶和华 所吩咐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, '利未人 要手中 各 拿兵器,四围 护卫 王;凡擅入 殿宇的,必当治死。王 出 入的时候,你们当 跟随他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, '利未人 和犹大 众人 都照著祭司 耶何耶大 一切 所 吩咐 的去行,各 带 所管安息日 进班 出 班 的人来,因为 祭司 耶何耶大 不许 他们下 班。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, '祭司 耶何耶大 便将 神 殿 里所 藏大卫 王 的枪、 盾牌、 挡牌 交 给百夫 长, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, '又分派 众 民 手中 各 拿兵器,在坛 和殿那里,从 殿 右 直到 殿 左,站在 王 子的四围; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, '于 是领 王 子 出来,给 他戴上 冠冕,将 律法书交给他,立他 作王。耶何耶大 和众子 膏他,众人说:「愿 王 万岁!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, '亚她利雅 听见 民 奔走 赞美 王 的声音,就到 民那里,进耶和华 的殿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, '看见 王 站 在 殿门 的柱旁,百夫长 和吹号的人 侍立在 王左右,国 民 都 欢乐 吹 号,又有歌唱的,用各样的乐 器 领 人歌唱赞美;亚她利雅 就撕裂 衣服,喊叫说:「反了!反了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, '祭司 耶何耶大 带 管辖 军兵 的百夫 长 出来,吩咐他们 说:「将她赶 到 班 外,凡跟 随她 的必用刀 杀死!」因为 祭司 说:「不可 在耶和华 殿 里杀她。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, '众兵就闪开 ,让她去;她走 到 王 宫 的马 门,便在那里 把她杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, '耶何耶大 与 众 民 和 王 立 约,都要作 耶和华 的民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, '于 是众 民 都到 巴力 庙,拆毁了庙,打碎 坛 和 像,又在坛 前 将 巴力 的祭司 玛坦 杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, '耶何耶大 派 官 看守耶和华 的殿,是在祭司 利未人 手下。这 祭司利未人是大卫 分派 在 耶和华 殿中、照摩西 律法 上所写的,给耶和华 献 燔祭,又按 大卫 所定的例,欢乐 歌唱; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, '且设立 守门的 把守 耶和华 殿 的各门,无论为何 事,不洁净 的人都不准 进去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, '又率领 百夫 长 和 贵胄,与 民间 的官长,并 国 中的众 民,请王 从耶和华 殿 下来,由 上 门 进入 王 宫,立 王 坐 在 国 位上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, '国 民 都 欢乐,合城 都安静。众人已将 亚她利雅 用刀 杀了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, '约阿施 登基 的时候年 七 岁,在耶路撒冷 作王 四十 年。他母亲 名叫 西比亚,是别是巴人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, '祭司 耶何耶大 在世的时候,约阿施 行 耶和华 眼中 看为正的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, '耶何耶大 为他 娶了 两个 妻,并且生 儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, ' 此后,约阿施 有 意 重修 耶和华 的殿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, '便召聚 众祭司 和利未人,吩咐他们 说:「你们要往犹大 各城 去,使以色列 众人 捐纳 银子,每 年 可以修理你们 神 的殿;你们 要急速 办理这事。」只是利未人 不 急速办理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, '王 召了 大 祭司耶何耶大来,对他 说:「从前耶和华 的仆人 摩西,为法柜 的帐幕 与以色列 会众 所定的捐项,你为何 不 叫 利未人 照这例从犹大 和耶路撒冷 带来 作殿的费用呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, '(因为 那恶 妇亚她利雅 的众子 曾拆毁 神 的殿,又 用耶和华 殿中 分别为圣的物 供奉 巴力。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, '于 是王 下令,众人做了 一 柜,放 在耶和华 殿 的门 外, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, '又通 告 犹大 和耶路撒冷的百姓,要将 神 仆人 摩西 在旷野 所吩咐 以色列人 的捐项 给耶和华 送来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, '众 首领 和百姓 都 欢欢喜喜地 将银子送来,投入 柜中,直到 捐完。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, ' 利未人 见 银子 多了,就把 柜 抬 到 王 所派的司事面前;王 的书记 和大 祭司 的属员 来 将 柜 倒空,仍放 在 原处。日 日 都是这样,积蓄 的银子 甚多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, '王 与耶何耶大 将银子交 给 耶和华 殿 里办 事 的人, 他们就雇了 石匠、木匠 重修 耶和华 的殿,又 雇了铁 匠、铜 匠修理 耶和华 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, '工人 操作, 渐渐 修成,将 神 殿 修造得 与从前 一样,而且甚是坚固。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, '工程完了,他们就把 其余 馀的 银子 拿到 王 与耶何耶大 面前,用以制造 耶和华 殿 供奉 所用 的器皿 和调羹,并金 银 的器皿。 耶何耶大 在世的时候,众人常 在耶和华 殿 里献 燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, '耶何耶大 年纪老迈,日子 满足 而死。死 的时候年 一百 三十 岁, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, '葬 在大卫 城 列王的坟墓里;因为 他在以色列 人中行 善,又事奉 神,修理 神的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, '耶何耶大 死 后,犹大 的众首领 来 朝拜 王;王 就 听从 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, '他们离弃 耶和华─他们列祖 神 的殿,去事奉 亚舍拉 和 偶像;因他们这 罪,就有忿怒 临 到 犹大 和耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, '但 神仍遣 先知 到他们那里,引导他们归 向 耶和华。这先知警戒 他们,他们却不肯 听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, '那时, 神 的灵 感动 祭司 耶何耶大 的儿子 撒迦利亚,他就站 在上面 对民 说:「 神 如此 说:你们 为何 干犯 耶和华 的诫命,以致不 得亨通呢?因为 你们离弃 耶和华,所以他也离弃 你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, '众民同心谋害 撒迦利亚,就照王 的吩咐,在耶和华 殿 的院 内用石头 打死他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, '这样,约阿施 王 不 想念 撒迦利亚的父亲 耶何耶大 向自己 所 施 的恩,杀了 他的儿子。撒迦利亚临死 的时候说:「愿 耶和华 鉴察 伸冤!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, ' 满了 一年,亚兰 的军兵 上来 攻击约阿施,来 到 犹大 和耶路撒冷,杀了 民 中的 众 首领,将所 掠的财货 送到 大马士革 王那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, '亚兰 的军 兵 虽 来了 一小队,耶和华 却将大队的 军兵 交 在他们手里,是因 犹大人离弃 耶和华─他们列祖的 神,所以藉 借亚兰人惩罚 约阿施。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, '亚兰人离开  约阿施的时候, 他 患 重 病;臣仆 背叛 他,要报祭司 耶何耶大 儿子 流血之仇,杀他 在 床上,葬他 在大卫 城,只是不 葬 在列王 的坟墓里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, '背叛 他 的是 亚扪妇人 示米押 的儿子 撒拔 和摩押妇人 示米利 的儿子 约萨拔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, '至于 他的众子 和他所受 的 警戒,并他重修 神 殿的事,都 写 在 列王 的传上。他儿子 亚玛谢 接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, '亚玛谢 登基 的时候年 二十 五 岁,在耶路撒冷 作王 二十 九 年。他母亲 名叫 约耶但,是耶路撒冷人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, '亚玛谢行 耶和华 眼中 看为正的事,只是 心 不 专诚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, ' 国 一坚定,就把 杀 他父 王 的臣仆 杀了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, '却没有 治死 他们的儿子,是 照 摩西 律法 书 上耶和华 所 吩咐 的说:「不可 因 子 杀 父,也不可 因 父 杀 子, 各人 要为本身的罪 而死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, '亚玛谢 招聚 犹大人,按著 犹大 和便雅悯 的宗 族 设立 千夫 长、百夫 长,又数点人数,从 二十 岁 以外,能拿 枪 拿盾牌 出去 打仗 的精兵 共有 三十万; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, '又用银子 一百 他连得,从以色列 招募了 十万 大能的 勇士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, '有一个神 人 来 见亚玛谢,对他说:「王啊,不要 使以色列 的军兵 与你 同去,因为 耶和华 不 与 以色列人 以法莲 的后裔同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, '你 若一定 要去,就 奋勇 争战 吧!但 神 必使你败 在敌人 面前;因为 神 能 助人得胜,也能使人倾败。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, '亚玛谢 问神 人 说:「我给了 以色列 军 的那 一百 他连得 银子怎么 样呢?」神 人 回答说:「耶和华 能 把更 多的 赐 给你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, '于 是亚玛谢 将那 从以法莲 来 的军兵 分别出来,叫他们回家 去。故此,他们甚 恼 怒 犹大人,气 忿忿地 回 家去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, '亚玛谢 壮起胆来,率领 他的民 到 盐 谷,杀了 西珥 人 一万。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, '犹大 人 又生 擒了 一万 带到 山崖 上,从 那里 把他们扔下去,以致他们都 摔碎了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, '但亚玛谢 所 打发回去、不许一同 出 征 的那些军 兵 攻打 犹大 各城,从撒马利亚 直到伯.和仑 ,杀了 三 千人,抢了 许多 财物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, ' 亚玛谢 杀了 以东人 回来,就把 西珥 的神像 带回,立 为自己 的神,在它面前 叩拜 烧香。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, '因此,耶和华 的怒气 向亚玛谢 发作,就差 一个先知 去见他,说:「这些 神 不能 救 它的民 脱离你的手,你为何 寻求 它呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, ' 先知与王 说话的时候,王对他 说:「谁立你 作王的 谋士呢?你 住口吧!为何 找打呢?」先知 就止住了,又说:「 你行 这事,不 听从 我的劝戒,我知道 神 定意 要灭你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, '犹大 王 亚玛谢 与群臣商议,就差遣 使者去见 耶户 的孙子、约哈斯 的儿子、以色列 王 约阿施,说:「你来,我们二人 相见于 战 场。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, '以色列 王 约阿施 差遣 使者去见 犹大 王 亚玛谢,说:「黎巴嫩 的 蒺藜 差遣 使者去见 黎巴嫩 的 香柏树,说:『将 你的女儿 给 我儿子 为妻。』后来 黎巴嫩 有一个野 兽 经过,把 蒺藜 践踏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, '你说:『看哪,我打败了 以东人』,你就心 高气傲,以致矜夸。 你在家里 安居就罢了,为何 要惹 祸 使自己 和犹大 国一同 败亡呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, '亚玛谢 却不肯 听从。 这是出乎 神,好 将他们交 在敌人手里,因为 他们寻求 以东 的神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, '于 是以色列 王 约阿施 上来,在犹大 的伯‧示麦 与犹大 王 亚玛谢 相 见于 战 场。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, '犹大人 败 在以色列人 面前,各自 逃 回家里去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, '以色列 王 约阿施在伯‧示麦 擒住 约哈斯(就是亚哈谢)的孙子、约阿施 的儿子、犹大 王 亚玛谢,将他带 到耶路撒冷,又拆毁 耶路撒冷 的城墙,从以法莲 门 直到 角 门,共四 百 肘; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, '又将俄别‧以东所看守 神 殿 里的 一切 金 银和 器皿,与 王 宫 里的财宝都拿了去,并 带人 去为质,就回 撒马利亚去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, '以色列 王 约哈斯 的儿子 约阿施 死 后,犹大 王 约阿施 的儿子 亚玛谢 又活了 十 五 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, '亚玛谢 其余 馀 的事,自始 至终 不 都 写 在 犹大 和以色列 诸王 记上吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, '自从 亚玛谢 离弃 耶和华之后,在耶路撒冷 有人背叛 他,他就逃 到拉吉;叛党却打发 人 到拉吉,将他杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, '人就用 马 将他的尸首驮回,葬 在犹大 京城 他列祖的坟地里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, '犹大 众 民 立 亚玛谢 的儿子 乌西雅(又名亚撒利雅)接续 他父 作王,那时他 年 十六 岁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, '(亚玛谢 与 他列祖 同睡 之后,乌西雅 收回以禄 仍归 犹大,又重新修理。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, '乌西雅 登基 的时候年 十六 岁,在耶路撒冷 作王 五十 二 年。他母亲 名叫 耶可利雅,是 耶路撒冷人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, '乌西雅行 耶和华 眼中 看为正的事,效法他父 亚玛谢 一切 所 行的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, '通晓 神 默示,撒迦利亚 在世的时候,乌西雅定意 寻求 神;他寻求 耶和华, 神 就使他亨通。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, '他出去 攻击 非利士人,拆毁了 迦特 城、 雅比尼 城,和 亚实突 城;在非利士人中,在亚实突境内,又建筑了 些城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, '神 帮助他 攻击 非利士人 和 住 在姑珥巴力 的阿拉伯人,并米乌尼人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, '亚扪人 给乌西雅 进 贡。他的名声 传 到 埃及,因 他甚是 强盛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, '乌西雅 在耶路撒冷的 角 门 和 谷 门,并 城墙转弯之处,建筑 城楼,且甚坚固; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, '又在旷野 与高原 和平原,建筑 望楼,挖了 许多 井,因 他的 牲畜 甚多;又在山地 和佳美之地,有农夫 和修理葡萄园的人,因为 他 喜悦 农事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, ' 乌西雅 又有 军 兵,照 书记 耶利 和官长 玛西雅 所数点的,在 王 的一个将军 哈拿尼雅 手下,分队 出 战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, '族 长、大能 勇士 的总 数 共有二千 六 百人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, '他们手 下 的军 兵 共有三 十 万 七 千 五 百人,都有大能,善于  争战 ,帮助 王 攻击 仇敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, '乌西雅 为全 军 预备 盾牌、枪、盔、甲、弓,和甩石 的机弦, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, '又在耶路撒冷 使巧 匠 做 机器, 安在 城楼 和 角楼上,用以射 箭 发 石。乌西雅的名声 传 到 远方;因为 他得了非常的 帮助,甚是 强盛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, '他既强盛,就心 高气傲,以致 行事邪僻,干犯 耶和华─他的 神,进 耶和华 的殿,要在 香 坛 上烧香。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, '祭司 亚撒利雅 率领 耶和华 勇敢的 祭司 八十人,跟随他 进去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, '他们就阻挡 乌西雅 王,对他 说:「乌西雅啊,给耶和华 烧香 不是 你的事,乃是 亚伦 子孙 承接圣职 祭司的事。你出 圣殿吧!因为 你犯了罪。你行这事,耶和华 神 必不 使你 得荣耀。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, '乌西雅 就发怒,手 拿香炉 要烧香。他向 祭司 发怒的时候,在耶和华 殿 中香 坛 旁 众祭司 面前,额上 忽然发出 大痲疯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, '大 祭司 亚撒利雅 和众 祭司 观看,见 他 额上 发出大痲疯,就催他 出殿;他自己 也 急速 出去,因为 耶和华 降灾与他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, ' 乌西雅 王 长大痲疯 直到 死 日,因此住在 别的 宫里, 与耶和华 的殿 隔绝。他儿子 约坦 管理 家事,治理 国 民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, '乌西雅 其余 馀的 事,自始 至终 都是亚摩斯 的儿子 先知 以赛亚 所记的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, '乌西雅 与 他列祖 同睡,葬 在王 陵 的田间 他列祖 的坟地里;因为 人说,他 是长大痲疯的。他儿子 约坦 接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, '约坦 登基 的时候年 二十 五 岁,在耶路撒冷 作王 十 六 年,他母亲 名叫 耶路沙,是撒督 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, '约坦行 耶和华 眼中 看为正的事,效法他父 乌西雅 一切 所 行的,只是 不 入 耶和华 的殿。百姓 还 行邪僻的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, '约坦 建立 耶和华 殿 的上 门,在俄斐勒 城 上多有 建造, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, '又在犹大 山地 建造 城邑,在树林 中建筑 营寨 和高楼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, '约坦 与 亚扪人 的王 打仗 胜了 他们,当 年 他们 进贡 银 一百 他连得,小麦 一万 歌珥,大麦 一万歌珥; 第二 年、第三 年也是 这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, '约坦 在耶和华─他 神 面前 行 正道,以致日渐强盛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, '约坦 其余 馀 的事 和一切 争战 ,并他的行为,都 写 在 以色列 和犹大 列王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, ' 他登基 的时候年 二十 五 岁,在耶路撒冷 作王 十 六 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, '约坦 与 他列祖 同睡,葬 在大卫 城里。他儿子 亚哈斯 接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, '亚哈斯 登基 的时候年 二十 岁,在耶路撒冷 作王 十 六 年;不 像他祖 大卫 行 耶和华 眼中 看为正的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, '却行 以色列 诸王 的道,又 铸造 巴力的 像, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, '并且 在欣嫩 子 谷 烧香,用火 焚烧 他的儿女,行耶和华 在以色列 人 面前 所 驱逐 的外邦人 那可憎的事; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, '并在邱坛上、山冈 上、各 青翠 树 下 献祭 烧香。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, '所以,耶和华─他的 神 将他交 在亚兰 王 手里。亚兰王打败 他,掳了 他 许多 的民,带到 大马士革去。 神 又 将他交 在以色列 王 手里,以色列王向他 大 行 杀戮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, '利玛利 的儿子 比加 一 日 杀了 犹大人 十 二 万,都是 勇 士,因为他们离弃了 耶和华─他们列祖的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, '有一个以法莲 中的勇士,名叫细基利,杀了 王 的儿子 玛西雅 和 管理 王宫 的押斯利甘,并 宰相 以利加拿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, '以色列 人 掳了 他们的弟兄,连妇人 带儿 女 共有二十万,又 掠了 许多 的财物,带 到撒马利亚去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, '但那里 有 耶和华的 一个先知,名叫 俄德,出来 迎接 往撒马利亚 去的 军兵,对他们 说:「 因为耶和华─你们列祖的 神 恼怒 犹大人,所以将他们交 在你们手里,你们竟怒气 冲 天,大行杀戮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, '如今 你们 又有意 强逼 犹大 人 和耶路撒冷 人作你们的 奴 婢,你们 岂不 也 有得罪 耶和华─你们 神的事吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, '现在 你们当听我说,要将 掳来 的弟兄 释放回去,因为 耶和华 向你们 已经大发烈 怒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, '于 是,以法莲 人 的几个 族长─就是约哈难 的儿子 亚撒利雅、米实利末 的儿子 比利家、沙龙 的儿子 耶希西家、哈得莱 的儿子 亚玛撒─起来 拦挡 出兵 回来的人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, '对他们 说:「你们不可 带进 这被掳的人 来! 你们 想要 使我们 得罪 耶和华,加增 我们的罪恶 过犯?因为 我们的 罪过 甚大,已经有烈 怒 临到 以色列人了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, '于 是带兵器的人 将 掳来的人口 和 掠来的财物 都 留 在众首领 和会众 的面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, '以上提 名 的那些 人 就站起,使 被掳的人前来;其中 有赤身的,就从 所掠的财物中拿出衣服和鞋来,给他们穿,又给他们吃 喝,用膏抹他们;其中 有软弱的,就使他们骑 驴,送 到棕树 城 耶利哥 他们弟兄 那里;随后就回 撒马利亚去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, '那 时,亚哈斯 王 差遣 人去见 亚述 诸王,求他们 帮助; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, '因为以东人 又 来 攻击 犹大,掳掠 子民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, '非利士人 也来侵占 高原 和犹大 南方 的城邑,取了伯‧示麦、 亚雅仑 、 基低罗, 梭哥 和属梭哥的乡村, 亭纳 和 属亭纳的乡村,瑾锁 和 属瑾锁的乡村,就住 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, '因为 以色列 王 亚哈斯 在犹大 放肆,大大干 犯 耶和华,所以 耶和华 使 犹大 卑微。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, '亚述 王提革拉‧毘列色 上来,却没有 帮助他,反倒欺凌 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, ' 亚哈斯 从 耶和华 殿里 和 王 宫中,并首领 家内所取的 财宝给了 亚述 王,这也无 济 于 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, '这 亚哈斯 王 在急难 的时候,越发 得罪 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, '他祭祀 攻击 他 的大马士革 之神,说:「因为 亚兰 王 的神 帮助 他们,我也献祭 与他,他好帮助我。」但那些神 使 他 和以色列 众人 败亡了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, '亚哈斯 将 神 殿里 的器皿 都聚了来,毁坏了,且封锁 耶和华 殿 的门;在耶路撒冷 各处 的拐角 建筑 祭坛, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, '又在犹大 各 城 建立 邱坛,与别 神 烧香,惹动 耶和华─他列祖 神 的怒气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, '亚哈斯其余 馀 的事 和 他的行为,自始 至终 都 写 在 犹大 和以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, '亚哈斯 与 他列祖 同睡,葬 在耶路撒冷 城里, 没有 送入 以色列 诸王 的坟墓中。他儿子 希西家 接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, '希西家 登基 的时候年 二十 五 岁,在耶路撒冷 作王 二十 九年。他母亲 名叫 亚比雅,是撒迦利雅 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, '希西家行 耶和华 眼中 看为正的事,效法他祖 大卫 一切 所 行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, ' 元 年 正 月,开 了 耶和华 殿 的门,重新修理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, '他召 众祭司 和 利未人 来,聚集 在东边 的宽阔处, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, '对他们 说:「利未人哪,当听我说:现在 你们要洁净自己,又洁净 耶和华─你们列祖 神 的殿,从 圣 所中除去 污秽之物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, ' 我们列祖 犯了罪,行 耶和华─我们 神 眼中 看为恶的事,离弃他,转 脸 背 向 他的居所, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, ' 封锁 廊 门,吹灭 灯火,不 在圣所 中向以色列 神 烧 香,或 献 燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, '因此,耶和华 的忿怒 临 到 犹大 和耶路撒冷,将其中的人 抛来抛去,令人惊骇、嗤笑,正如你们 亲眼 所 见的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, '所以 我们的祖宗 倒 在刀下,我们的妻子 儿 女 也被掳掠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, '现在 我心中 有意与耶和华─以色列的 神 立 约,好使他的烈怒 转离 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, '我的众子啊,现在 不要 懈怠;因为 耶和华 拣选 你们 站 在他面前 事奉他,与他烧香。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, '于 是,利未人 哥辖 的 子孙、亚玛赛 的儿子 玛哈,亚撒利雅 的儿子 约珥;米拉利 的 子孙、亚伯底 的儿子 基士,耶哈利勒 的儿子 亚撒利雅;革顺 的子孙、薪玛 的儿子 约亚,约亚 的儿子 伊甸; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, '以利撒反 的 子孙 申利 和耶利;亚萨 的 子孙 撒迦利雅 和玛探雅; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, '希幔 的 子孙 耶歇 和示每;耶杜顿 的 子孙 示玛雅 和乌薛; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, '起来 聚集 他们的弟兄,洁净自己,照著王 的吩咐、耶和华 的命令,进去 洁净 耶和华 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, '祭司 进入 耶和华 的殿 要洁净殿,将 殿中 所有 污秽之物 搬到 耶和华 殿 的院内,利未人 接去,搬 到外头 汲沦 溪边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, '从正 月 初一 日洁净 起,初 八 日 到了 耶和华 的殿廊,用八 日 的工夫洁净 耶和华 的殿,到正 月 十 六 日 才洁净完了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, '于 是,他们晋 见 希西家 王,说:「我们已将 耶和华 的全 殿 和 燔祭 坛,并 坛的一切 器皿、 陈设饼 的桌子,与 桌子的一切 器皿 都洁净了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, '并且 亚哈斯 王 在位 犯罪 的时候所 废弃的 器皿,我们预备齐全,且洁净了,现今都 在耶和华 的坛 前。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, '希西家 王 清早起来,聚集 城 里的首领 都上 耶和华 的殿; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, '牵了 七只 公牛,七只 公羊,七只 羊羔,七只 公 山羊,要为 国、为 殿、为 犹大人 作赎罪祭。王吩咐 亚伦 的子孙 众祭司,献 在 耶和华 的坛上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, '就宰了 公牛,祭司 接 血 洒 在坛上,宰了 公羊,把血 洒 在坛上,又宰了 羊羔,也把血 洒 在坛上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, '把 那作赎罪祭 的公山羊 牵到 王 和会众 面前,他们就按 手 在其上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, '祭司 宰了羊,将 血 献在坛 上作赎罪祭,为 以色列 众人 赎罪,因为 王 吩咐 将燔祭 和赎罪祭 为以色列 众人献上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, '王又派 利未人 在耶和华 殿 中敲钹,鼓瑟,弹琴,乃照大卫 和他 先见 迦得,并先知 拿单 所吩咐的,就是 耶和华 藉 借 先知 所吩咐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, '利未人 拿大卫 的乐器,祭司 拿号,一同站立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, '希西家 吩咐 在坛 上献 燔祭, 燔祭 一献,就 唱赞美耶和华 的歌,用号,并用 以色列 王 大卫 的乐器相和。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, '会众 都 敬拜,歌唱的 歌唱,吹号的 吹号,如此 直到 燔祭 献完了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, '献 完了祭,王 和一切 跟 随的人 都俯伏 敬拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, '希西家 王 与众首领 又吩咐 利未人 用大卫 和先见 亚萨 的诗词 颂赞 耶和华;他们就 欢欢喜喜地 颂赞耶和华,低头 敬拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, '希西家 说:「你们既然 归耶和华 为圣,就要前来 把祭物 和感谢祭 奉到 耶和华 殿里。」会众 就把祭物 和感谢祭 奉来,凡 甘心 乐意 的也将燔祭奉来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, '会众 所 奉 的燔祭 如下:公牛 七十只,公羊 一百只,羊羔 二百只,这 都是 作燔祭 献给耶和华的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, '又有分别为圣之物,公牛 六 百只,绵羊 三 千只。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, '但 祭司 太少,不 能 剥 尽 燔祭牲的皮,所以他们的弟兄 利未人 帮助他们,直等 燔祭的事 完了,又等 别的祭司 自洁了;因为 利未人 诚 心 自洁,胜过祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, ' 燔祭 和平安祭牲 的脂油,并燔祭 同献的奠祭 甚多。这样,耶和华 殿 中的事务 俱都齐备了(或译:就整顿了)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, ' 这事 办的甚速,希西家 和众 民 都喜乐,是因 神 为众民 所预备的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, '希西家 差遣人 去见 以色列 和犹大 众人,又 写 信 给 以法莲 和玛拿西人,叫他们到 耶路撒冷 耶和华 的殿,向耶和华─以色列的 神 守 逾越节; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, '因为王 和众首领,并耶路撒冷 全 会众 已经商议,要在二 月 内守 逾越节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, '正月(原文是那 时)间他们不 能 守;因为 自洁 的祭司 尚不 敷用,百姓 也没有 聚集 在耶路撒冷; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, '王 与全 会众 都以这事 为善。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, '于 是定了 命令,传 遍 以色列,从别是巴 直到 但,使他们都来,在耶路撒冷 向耶和华─以色列的 神 守 逾越节;因为 照所写的例,守 这节的不 多了(或译:因为民许久没有照所写的例守节了)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, '驿卒 就把 王 和众首领 的信,遵著王 命 传 遍 以色列 和犹大。信内说:「以色列 人哪,你们当转 向 耶和华─亚伯拉罕、以撒、以色列的 神,好叫他转 向 你们 这脱离 亚述 王 手 的余 馀民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, '你们不要 效法 你们列祖 和你们的弟兄;他们 干犯 耶和华─他们列祖的 神,以致耶和华 丢弃他们,使他们败亡(或译:令人惊骇〕),正如你们 所 见的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, '现在 不要 像你们列祖 硬著 颈项,只要归顺 耶和华,进入 他的圣所,就是 永远 成圣的居所;又要事奉 耶和华─你们的 神,好使他的烈 怒 转离 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, '你们若 转 向 耶和华,你们的弟兄 和儿女 必在掳掠 他们的人面前 蒙怜恤,得以归回 这 地,因为 耶和华─你们的 神 有恩典、施怜悯。你们若 转 向他,他必不 转 脸 不顾你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, '驿卒 就 由这城 跑到 那城,传遍了 以法莲、玛拿西,直到 西布伦。那里的人却 戏笑 他们,讥诮 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, '然而 亚设、玛拿西、西布伦 中也有人 自卑,来到 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, '神 也 感动 犹大人,使 他们 一 心 遵行 王 与众首领 凭耶和华 之言 所发的命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, '二 月,有许多 人 在耶路撒冷 聚集,成为 大 会,要守 除酵 节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, '他们起来, 把 耶路撒冷 的 祭坛 和 烧香 的坛尽都 除去,抛 在汲沦 溪中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, '二 月 十 四日,宰了 逾越节的羊羔。祭司 与利未人 觉得惭愧,就洁净自己,把燔祭 奉到 耶和华 殿中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, '遵著神 人 摩西 的律法,照例 站 在 自己的地方;祭司 从利未人 手里 接过 血来,洒在坛上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, ' 会 中有许多 人 尚未 自洁,所以利未人 为 一切 不 洁 之人宰 逾越节的羊羔,使他们在耶和华 面前成为圣洁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, ' 以法莲、玛拿西、以萨迦、西布伦 有许多 人 尚未 自洁,他们却 也吃 逾越节的羔羊,不 合所记录的定例。 希西家 为他们 祷告 说:「凡 专 心 寻求 神,就是耶和华─他列祖之 神的,虽不 照著圣所 洁净之礼自洁,求至善 的耶和华 也饶恕 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, '耶和华 垂听 希西家的祷告,就饶恕(原文是医治) 百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, '在 耶路撒冷 的以色列 人 大大 喜乐,守 除酵 节 七 日。利未人 和祭司 用响亮的 乐器,日 日 颂赞 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, '希西家 慰劳 一切 善于  事奉 耶和华 的利未人。于 是众人吃 节 筵七 日,又献 平安 祭,且向耶和华─他们列祖的 神 认罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, '全 会众 商议,要再 守 节七 日;于 是欢欢喜喜地 又守 节七 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, ' 犹大 王 希西家 赐 给会众 公牛 一千只,羊 七 千只为祭物;众首领 也赐 给会众 公牛一千只,羊 一万只,并有许多 的祭司 洁净自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, '犹大 全 会众、祭司、利未人,并那从以色列 地 来 的会众和 寄居的人,以及犹大 寄居的人,尽都 喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, '这样,在耶路撒冷 大 有 喜乐, 自从以色列 王 大卫 儿子 所罗门 的时候,在耶路撒冷 没有 这样的喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, '那时,祭司、利未人 起来,为 民 祝福。他们的声音蒙 神 垂听,他们的祷告 达到 天上 的圣 所。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, '这事 既都 完毕,在那里的 以色列 众人 就到 犹大 的城邑,打碎 柱像,砍断 木偶,又在犹大、便雅悯、以法莲、玛拿西 遍 地将 邱坛 和 祭坛 拆毁 净尽。于 是以色列 众 人 各 回 各城,各归各地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, '希西家 派定 祭司 利未人 的 班次,各 按 各职 献燔祭 和平安祭,又在耶和华殿(原文是营)门 内事奉,称谢 颂赞 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, '王 又从 自己的产业 中定出分 来为燔祭,就是早 晚 的燔祭 和安息日、月朔,并节期 的燔祭,都是按耶和华 律法 上所载的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, '又吩咐 住 耶路撒冷 的百姓 将祭司、利未人 所应得的分 给他们,使 他们专心 遵守耶和华 的律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, '谕旨 一出,以色列 人 就把初熟的 五谷、新酒、油、蜜,和 田地 的出产 多多 送来,又把各物的 十分之一 送来 的极多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, '住 犹大 各城 的以色列 人 和犹大人 也 将牛 羊 的十分之一,并分别为圣 归耶和华─他们 神 之物,就是十分取一之物,尽都送来,积成 堆垒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, '从三 月 积 起,到七 月 才完。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, '希西家 和众首领 来,看见 堆垒,就称颂 耶和华,又为 耶和华的民 以色列人祝福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, '希西家 向 祭司、利未人 查问 这堆垒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, '撒督 家 的大 祭司 亚撒利雅 回答 说:「自从 民将供物 送到 耶和华 殿以来,我们不但吃 饱,且剩下的 甚多;因为 耶和华 赐福 给 他的民,所剩下的 才这样 丰盛。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, '希西家 吩咐 在耶和华 殿里 预备 仓房,他们就预备了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, '他们诚心 将 供物 和十分取一之物,并分别为圣之物,都搬入仓内。利未人 歌楠雅 掌管 这事,他兄弟 示每 为副管。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, '耶歇、亚撒细雅、拿哈、亚撒黑、耶利末、约撒拔、以列、伊斯玛基雅、玛哈、比拿雅 都是督理,在歌楠雅 和他兄弟 示每 的手下,是希西家 王 和管理 神 殿 的亚撒利雅 所派的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, '守 东 门的利未人 音拿 的儿子 可利,掌管乐意献与 神 的礼物,发放 献与耶和华 的供物 和至 圣的物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, '在 他手下 有伊甸、岷雅岷、耶书亚、示玛雅、亚玛利雅、示迦尼雅,在祭司 的各城 里供紧要的职任,无论弟兄 大 小,都按著班次 分给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, ' 按家谱, 三 岁 以外 的男丁,凡 每 日 进 耶和华 殿、按班次 供 职的,也分给他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, '又按宗 族 家谱 分给 祭司,按班次 职任分给 二十 岁 以外的 利未人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, '又按家谱计算,分给他们 会中的 妻子、儿 女;因 他们身供要职,自洁 成圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, '按名 派定 的 人 要把应得的分 给 亚伦 子孙,住在各 城 郊 野、祭司 所有的 男丁 和一切 载入家谱 的利未人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, '希西家 在犹大 遍地 这样 办理,行 耶和华─他 神眼中 看为善 为正 为忠的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, '凡 他所 行 的,无论是办 神 殿 的事,是遵律法 守诫命,是寻求他的 神,都是尽 心 去行,无不亨通。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, '这 虔诚 的事 以后,亚述 王 西拿基立 来 侵入 犹大,围困 一切坚固 城,想要 攻破占据。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, '希西家 见 西拿基立 来,定意 要攻打 耶路撒冷, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, '就与 首领 和勇士 商议,塞住 城 外 的 泉 源;他们就都帮助他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, '于 是有许多 人 聚集,塞了 一切 泉源,并 通流 国 中 的小河,说:「亚述 王 来,为何 让他得著 许多 水呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, '希西家力图自强,就修筑 所有 拆毁 的城墙,高 与城楼 相齐;在城外 又 筑一城,坚固 大卫 城 的米罗,制造了 许多 军器、盾牌; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, '设立 军 长 管理 百姓,将他们招聚 在 城 门 的宽阔处,用话 勉励他们,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, '「你们当刚强 壮胆,不要 因 亚述 王 和 跟随他 的大 军 恐惧、 惊慌;因为 与我们同在的,比与他们同在的 更大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, '与他们同在 的是肉 臂,与我们同在 的是耶和华─我们的 神,他必帮助我们,为我们争 战 。」百姓 就靠 犹大 王 希西家 的话,安然无惧了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, '此 后,亚述 王 西拿基立 和他 的全 军 攻打 拉吉,就差遣 臣仆 到耶路撒冷 见 犹大 王 希西家 和 一切 在耶路撒冷 的 犹大人,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, '「亚述 王 西拿基立 如此 说:『你们 倚靠 什么,还 在耶路撒冷 受困呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, '希西家 对你们说「耶和华─我们的 神 必救我们 脱离亚述 王 的手」,这不是 诱惑 你们,使 你们 受饥 渴 而死吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, '这 希西家 岂不是 废去 耶和华的邱坛 和 祭坛,吩咐 犹大 与耶路撒冷 的人说「你们当在一个 坛 前 敬拜,在其上 烧香」吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, '我 与我列祖 向列 邦 所 行的,你们岂不 知道吗?列邦 的神 何尝 能 救 自己的国 脱离我手呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, '我列祖 所 灭的 国,那些 神 中谁 能 救 自己的民 脱离我手呢?难道 你们的神 能 救 你们 脱离我手吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, '所以 你们不要 叫希西家 这样 欺哄 诱惑 你们,也不要 信 他;因为 没有 一 国 一 邦 的神 能 救 自己的民 脱离我手 和我列祖 的手,何况 你们的神 更 不能 救 你们 脱离我的手。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, '西拿基立的臣仆 还有 别的话 毁谤 耶和华 神 和 他仆人 希西家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, '西拿基立也写 信 毁谤 耶和华─以色列的 神 说:「列邦 的神 既 不能 救 他的民 脱离我手,希西家 的神 也 不能 救 他的民 脱离我手了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, '亚述王的臣仆用犹大言语 向 耶路撒冷 城 上 的 民 大 声 呼叫,要惊吓他们,扰乱他们,以便 取 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, '他们论 耶路撒冷的 神,如同论 世上 人 手 所造 的神一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, '希西家 王 和亚摩斯 的儿子 先知 以赛亚 因 此 祷告,向天 呼求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, '耶和华 就差遣 一个使者 进入亚述 王 营中,把所有 大能的 勇士 和官长、将帅 尽都灭了。亚述王满面 含羞地 回 到本国,进了 他神 的庙中,有他亲生的 儿子 在那里 用刀 杀了他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, '这样,耶和华 救 希西家 和 耶路撒冷 的居民 脱离亚述 王 西拿基立 的手,也脱离一切 仇敌的手,又赐他们四境 平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, '有许多人 到耶路撒冷,将供物 献 与耶和华,又将宝物 送给犹大 王 希西家。此 后,希西家在列 邦人 的眼中 看为尊大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, '那 时 希西家 病 得要 死,就祷告 耶和华,耶和华 应允 他,赐 他 一个兆头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, '希西家 却没有 照他 所蒙的恩 报答耶和华;因 他心里 骄傲,所以忿怒 要临 到他 和 犹大 并耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, '但希西家 和耶路撒冷 的居民 觉得心里 骄傲,就一同自卑,以致耶和华 的忿怒 在希西家 的日子 没有 临 到他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, ' 希西家 大 有 尊荣 资财,建造 府库,收藏金 银、宝 石、香料、盾牌,和各样的 宝 器, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, '又建造仓房,收藏 五谷、新酒,和油,又为各 类 牲 畜 盖棚 立圈; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, '并且建立 城邑,还有许多的 羊 群 牛群,因为 神 赐 他 极 多 的财产。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, '这 希西家 也塞住 基训 的上 源,引水直 下,流在大卫 城 的西边。希西家 所行的事 尽都 亨通。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, '惟有一件事,就是巴比伦 王 差遣 使者 来见希西家,访问 国中 所 现 的奇事;这件事 神 离开 他,要试验他,好知道 他心内如何。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, '希西家 其余 馀的 事 和他的善行 都 写 在亚摩斯 的儿子 先知 以赛亚 的默示书 上和 犹大、以色列 的诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, '希西家 与 他列祖 同睡,葬 在大卫 子孙 的高 陵上。他死的时候,犹大人 和耶路撒冷 的居民 都 尊敬 他。他儿子 玛拿西 接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, '玛拿西 登基 的时候年 十 二 岁,在耶路撒冷 作王 五十 五 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, '他行 耶和华 眼中 看为恶的事,效法耶和华 在以色列 人 面前 赶出 的外邦人 那 可憎的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, '重新 建筑 他父 希西家 所 拆毁 的邱坛,又为巴力 筑 坛,作 木偶,且敬拜 事奉 天上 的万 象, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, '在耶和华 的殿宇 中筑 坛─耶和华 曾指著这殿 说:「我的名 必 永远 在耶路撒冷。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, '他在耶和华 殿 的两 院 中为天上 的万 象 筑 坛, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, '并 在欣嫩 子 谷 使 他的儿女 经 火,又观兆,用法术,行邪术,立交 鬼 的和行巫术的,多 行 耶和华 眼中 看为恶的事,惹动他的怒气, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, '又在 神 殿 内立 雕刻的 偶像。 神 曾对 大卫 和 他儿子 所罗门 说:「我在以色列 各 支派 中所 选择 的耶路撒冷 和这 殿,必立 我的名 直到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, ' 以色列 人若 谨守 遵行 我藉 借 摩西 所 吩咐他们 的一切 法度、律例、典章,我就不 再 使他们 挪移 离开  我所 赐 给他们列祖 之地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, '玛拿西 引诱 犹大 和耶路撒冷 的居民,以致他们行 恶 比 耶和华 在以色列 人 面前 所 灭 的列国更甚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, '耶和华 警戒 玛拿西 和 他的百姓,他们却是不 听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, '所以耶和华 使 亚述 王 的 将 帅 来 攻击他们,用铙钩 钩住 玛拿西,用铜炼 链 𫔀 锁住他,带到 巴比伦去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, '他 在急难的时候,就恳求 耶和华─他的 神,且在他列祖的 神 面前 极其 自卑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, '他祈祷 耶和华,耶和华就允准 他的祈求,垂听 他的祷告,使他归回 耶路撒冷,仍坐国位。玛拿西 这才知道 惟独耶和华 是 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, '此 后,玛拿西在大卫 城 外,从谷内 基训 西边 直到鱼 门 口,建筑 城墙,环绕 俄斐勒,这墙筑得甚 高;又在犹大 各 坚固 城 内设立 勇敢的军 长; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, '并除掉 外邦人 的神像 与 耶和华 殿 中的偶像,又将他在耶和华 殿 的山上 和耶路撒冷 所 筑 的各 坛 都拆毁抛 在城 外; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, '重修 耶和华 的祭坛,在坛上 献 平安 祭、感谢祭,吩咐 犹大人 事奉 耶和华─以色列的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, '百姓 却 仍 在邱坛 上献祭,只 献给耶和华─他们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, '玛拿西 其余 馀 的事 和祷告他 神的话,并先见 奉耶和华─以色列 神 的名 警戒 他 的言语,都 写在 以色列 诸王 记上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, '他的祷告,与 神怎样应允 他,他未自卑 以前的 罪愆 过犯,并在 何 处 建筑 邱坛,设立 亚舍拉 和雕刻的偶像,都 写 在 何赛 的书上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, '玛拿西 与 他列祖 同睡,葬 在自己的宫院里。他儿子 亚们 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, '亚们 登基 的时候年 二十 二 岁,在耶路撒冷 作王 二 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, '他行 耶和华 眼中 看为恶的事,效法他父 玛拿西 所 行的, 祭祀 事奉 他父 玛拿西 所 雕刻的 偶像, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, '不 在耶和华 面前 像他父 玛拿西 自卑。 这 亚们 所犯的罪 越犯越大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, '他的臣仆 背叛,在宫里 杀了他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, '但国 民 杀了 那些 背叛 亚们 王的人, 立 他儿子 约西亚 接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, '约西亚 登基 的时候年 八 岁,在耶路撒冷 作王 三十 一 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, '他行 耶和华 眼中 看为正的事,效法他祖 大卫 所行的,不 偏 左 右。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, '他作王 第八 年, 尚且 年幼,就 寻求 他祖 大卫的 神。到了十 二 年 才 洁净 犹大 和耶路撒冷,除掉 邱坛、木偶、雕刻的像,和铸造的像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, '众人在他面前 拆毁 巴力 的坛,砍断 坛上 高高的 日像,又把木偶 和雕刻的像,并铸造的像 打碎 成灰,撒 在 祭 偶像 人的坟 上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, '将他们祭司 的骸骨 烧 在 坛上,洁净了 犹大 和 耶路撒冷; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, '又在玛拿西、以法莲、西缅、 拿弗他利 各城,和四围 破坏之处,都这样行; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, '又拆毁 祭坛,把 木偶 和雕刻的像 打碎 成灰,砍断 以色列 遍 地 所有的 日像,就回 耶路撒冷去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, '约西亚王 十 八 年,净 地 净殿之后,就差遣 亚萨利雅 的儿子 沙番、 邑 宰 玛西雅、 约哈斯 的儿子 史官 约亚 去修理 耶和华─他 神 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, '他们就去 见 大 祭司 希勒家,将 奉到 神 殿 的银子 交给他;这银子 是看守 殿门 的利未人 从 玛拿西、以法莲,和一切 以色列 剩下的人,以及犹大、便雅悯 众人,并耶路撒冷 的居民 收来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, '又将这银子交 给 耶和华 殿 里督 工的,转交 修 理 耶和华 殿 的 工 匠, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, '就是交 给木匠、石匠,买  凿成的 石头 和架木 与栋 梁,修 犹大 王 所 毁坏 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, '这些人 办 事 诚实,督工的 是利未人 米拉利 的 子孙 雅哈、俄巴底;督催的 是哥辖 的 子孙 撒迦利亚、米书兰;还有 善于  作 乐 的利未人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, '他们又监管 扛抬的人,督催 一切 做 工的。利未人 中也有作书记、作司事、作守门的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, ' 他们将奉到 耶和华 殿 的银子 运出来的时候,祭司 希勒家 偶然得了 摩西所传 耶和华 的律法 书。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, '希勒家 对 书记 沙番 说:「我在耶和华 殿里 得了 律法 书。」 遂将 书 递 给 沙番。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, '沙番 把 书 拿到 王那里,回 覆 复 王 说:「凡 交 给 仆人们办的都 办理了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, '耶和华 殿 里的 银子 倒出来,交 给 督工 的和 匠 人 的手里了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, '书记 沙番 又 对王 说:「祭司 希勒家 递 给我 一卷书。」沙番 就在王 面前 读 那书。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, ' 王 听见 律法 上的话,就撕裂 衣服, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, ' 吩咐 希勒家 与 沙番 的儿子 亚希甘、 米迦 的儿子 亚比顿、 书记 沙番,和 王 的臣仆 亚撒雅 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, '「你们去 为我、为 以色列 和犹大 剩下的人,以这 书上 的话 求问 耶和华;因 我们列祖 没有 遵守 耶和华 的言语,没有照 这 书 上 所 记 的去行, 耶和华 的烈怒 就 倒 在我们身上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, '于 是,希勒家 和王 所 派的众人都去 见 女先知 户勒大。户勒大是掌管 礼服 沙龙 的妻,沙龙是哈斯拉 的孙子、特瓦 的儿子。户勒大 住 在耶路撒冷 第二区;他们请问 于 她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, '她对他们 说:「耶和华─以色列的 神 如此 说:『你们可以回复 那 差遣 你们 来见我 的人说, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, '耶和华 如此 说:我 必照著在犹大 王 面前 所 读 那书 上的 一切 咒诅,降 祸 与 这 地 和 其上的居民; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, '因为 他们离弃我,向别 神 烧香,用 他们手 所做的 惹我发怒,所以我的忿怒 如火倒 在这 地上,总不 熄灭。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, '然而 差遣 你们 来求问 耶和华 的犹大 王,你们要这样 回复他 说:『耶和华─以色列的 神 如此 说:至于 你所 听见 的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, ' 就是听见 我指著 这 地 和 其上居民 所说的话,你便心里 敬服,在我 面前 自卑,撕裂 衣服,向我 哭泣, 因此我 应允了你。这是我─耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, '我 必使你平平安安地 归 到 坟墓, 到 你列祖那里, 我 要降 与 这 地 和 其上居民 的一切 灾祸,你也不致 亲眼 看见。』」他们就回 覆 复 王去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, '王 差遣人 招聚 犹大 和耶路撒冷 的众 长老来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, '王 和犹大 众 人,与耶路撒冷 的居民,并祭司 利未人,以及所有的 百姓,无论大 小,都一同上到 耶和华 的殿;王就把 殿里 所得的 约 书 念 给他们听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, '王 站 在 他的地位上,在耶和华 面前 立 约,要尽 心 尽 性 地顺 从 耶和华,遵守 他的诫命、法度、律例,成就 这 书 上 所记 的约 言; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, '又使 住 耶路撒冷 和便雅悯 的人都 服从这约。于 是耶路撒冷 的居民 都遵行 他们列祖之 神 的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, '约西亚 从以色列 各 处 将 一切 可憎之物 尽都除掉, 使 以色列境内的 人 都 事奉 耶和华─他们的 神。约西亚在世的日子,就跟从 耶和华─他们列祖的 神,总不 离开 。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, '约西亚 在耶路撒冷 向耶和华 守 逾越节。正 月 十 四日,就宰了 逾越节的羊羔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, '王分派 祭司 各尽 其职,又勉励他们 办 耶和华 殿中的事; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, '又对那归耶和华 为圣、教训 以色列人 的利未人 说:「你们将 圣 约柜 安放 在以色列 王 大卫 儿子 所罗门 建造 的 殿里,不必 再用肩 扛抬。现在 要事奉 耶和华─你们的 神,服事 他的民 以色列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, '你们应当按著宗 族,照著班次,遵 以色列 王 大卫 和他儿子 所罗门 所写的,自己预备。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, '要按著你们的弟兄,这民 宗 族 的班次,站 在圣所,每班 中要利未 宗 族的几个人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, '要宰 逾越节的羊羔,洁净自己,为你们的弟兄 预备了,好遵守 耶和华 藉 借 摩西 所吩咐的话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, '约西亚 从群畜中赐 给在 那里所有的 人 民,绵羊羔 和山羊 羔 三万只,牛 三 千只, 作逾越节的祭物;这 都是出自王 的产业中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, '约西亚的众首领 也乐意 将牺牲给 百姓 和祭司 利未人;又有管理 神 殿 的希勒家、撒迦利亚、耶歇 将羊羔二千 六 百只,牛 三 百只,给 祭司 作逾越节的祭物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, '利未人 的族长 歌楠雅 和他两个兄弟 示玛雅、拿坦业,与哈沙比雅、耶利、约撒拔 将羊羔五 千只,牛 五 百只,给 利未人 作逾越节的祭物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, '这样,供献的事 齐备了。祭司 站 在 自己的地方,利未人 按著 班次站立,都是照王 所吩咐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, '利未人宰了 逾越节的羊羔,祭司 从他们手里 接过血来洒在坛上;利未人 剥皮, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, '将燔祭 搬来,按著宗 族 的班次 分 给众 民,好照摩西 书上 所写的,献 给耶和华;献牛 也是这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, '他们按著常例,用火 烤 逾越节的羊羔。别的圣物 用锅,用釜,用罐 煮了,速速地 送给众 民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, '然后 为自己 和祭司 预备祭物;因为 祭司 亚伦 的子孙 献 燔祭 和脂油,直到 晚上。所以利未人 为自己 和祭司 亚伦 的子孙,预备祭物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, '歌唱的 亚萨 之子孙,照著大卫、亚萨、希幔,和王 的先见 耶杜顿 所吩咐的,站在 自己的地位上。守门的 看守各 门,不用 离开  他们的职事,因为 他们的弟兄 利未人 给他们 预备祭物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, '当 日,供奉耶和华 的事 齐 备了,就照约西亚 王 的吩咐 守 逾越节,献 燔祭 在 耶和华 的坛上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, '当 时 在 耶路撒冷 的以色列 人 守 逾越节,又守 除酵 节 七 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, '自从 先知 撒母耳以来,在以色列 中没有 守过 这样的 逾越节,以色列 诸 王 也没有 守过,像约西亚、祭司、利未人、在那里的 犹大人,和以色列人,以及耶路撒冷 居民 所 守的 逾越节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, '这 逾越节 是约西亚 作王 十 八 年 守的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, ' 这 事以后, 约西亚 修完了 殿,有埃及 王 尼哥 上来,要攻击 靠近 幼发拉底河 的迦基米施;约西亚 出去 抵挡他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, '他差遣 使者 来见约西亚,说:「犹大 王啊,我 与你 何干?我今日 来不是 要攻击你,乃是 要攻击 与我争战  之家,并且 神 吩咐 我速行,你 不要干预 神的事,免得 他毁灭你,因为 神 是与我同在。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, '约西亚 却不肯 转去 离开 他,改装 要 与他 打仗,不 听 从 神 藉 借尼哥 之口 所说的话,便来到 米吉多 平原 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, '弓箭手 射中 约西亚 王。王 对他的臣仆 说:「 我受了重 伤,你拉我出阵吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, '他的臣仆 扶他 下了 战 车,上 了 次 车,送他到 耶路撒冷,他就死了,葬 在他列祖 的坟墓里。犹大人 和耶路撒冷 人都 为 他 悲哀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, '耶利米 为 约西亚 作哀歌。所有 歌唱的男 女 也唱哀歌,追悼 约西亚,直到 今日;而且在 以色列 中成了 定例。 这歌载 在 哀歌书上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, '约西亚 其余 馀 的事 和他遵著耶和华 律法 上所记 而行的善事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, '并他自始 至终 所行的,都 写 在 以色列 和犹大 列王 记上。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, '国 民 立 约西亚 的儿子 约哈斯 在耶路撒冷 接续 他父 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, '约哈斯 登基 的时候年 二十 三 岁,在耶路撒冷 作王 三个 月。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, '埃及 王 在耶路撒冷 废了他,又罚 犹大国 银子 一百 他连得,金子 一他连得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, '埃及 王 尼哥 立 约哈斯的哥哥 以利雅敬 作 犹大 和耶路撒冷 的王,改 名 叫约雅敬,又 将 约哈斯 带到 埃及去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, '约雅敬 登基 的时候年 二十 五 岁,在耶路撒冷 作王 十 一 年,行 耶和华─他 神 眼中 看为恶的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, '巴比伦 王 尼布甲尼撒 上来 攻击他,用铜炼 链 𫔀 锁著他,要将他带到 巴比伦去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, '尼布甲尼撒 又将耶和华 殿里 的器皿 带到 巴比伦,放在 他神的庙里(或译:自己的宫里)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, '约雅敬 其余 馀 的事 和他所 行 可憎的事,并他 一切的行为,都 写 在 以色列 和犹大 列王 记上。他儿子 约雅斤 接续他 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, '约雅斤 登基 的时候年 八 岁(在列王下二十四章八节是十八岁),在耶路撒冷 作王 三个 月 零十 天,行 耶和华 眼中 看为恶的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, '过了 一年,尼布甲尼撒 差遣人 将约雅斤和 耶和华 殿 里各样宝贵的 器皿 带到 巴比伦,就立约雅斤的叔叔(原文是兄)西底家 作 犹大 和耶路撒冷 的王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, '西底家 登基 的时候年 二十 一 岁,在耶路撒冷 作王 十 一 年, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, '行 耶和华─他 神 眼中 看为恶的事。先知 耶利米 以耶和华 的话劝他,他仍不 在耶利米面前 自卑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, ' 尼布甲尼撒 曾使他指著 神 起誓,他却背叛,强 项 硬 心,不归 服 耶和华─以色列的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, '众 祭司 长 和百姓 也 大大 犯 罪,效法外邦人 一切 可憎的事,污秽 耶和华 在耶路撒冷 分别为圣 的 殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, '耶和华─他们列祖的 神 因为 爱惜 自己的民 和 他的居所,从早起来 差遣 使者 去警戒他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, ' 他们却嘻笑 神 的使者,藐视 他的言语,讥诮 他的先知,以致 耶和华 的忿怒 向他的百姓 发作, 无法 可救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, '所以,耶和华使 迦勒底人 的王 来 攻击他们,在他们圣 殿 里用刀 杀了 他们的壮丁,不 怜恤 他们的少男 处女、老人 白叟。耶和华将他们都 交 在迦勒底王手里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, '迦勒底王将 神 殿里的 大 小 器皿 与耶和华 殿里 的财宝,并王 和众首领 的财宝,都 带到 巴比伦去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, '迦勒底人焚烧 神 的殿,拆毁 耶路撒冷 的城墙,用火 烧了城里的 宫殿,毁坏了城里 宝贵的 器皿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, '凡脱离 刀剑的,迦勒底王都掳 到 巴比伦去,作 他 和他子孙 的仆婢,直到 波斯 国 兴起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, '这就应验 耶和华 藉 借耶利米 口 所说的话: 地 享受 安息; 因为地土荒凉 便守安息,直满了 七十 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, '波斯 王 塞鲁士 元 年,耶和华 为要应验 藉 借耶利米 口 所说的话,就激动 波斯 王 塞鲁士 的心, 使他下诏 通 告 全 国,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, '「波斯 王 塞鲁士 如此 说:耶和华─天上的 神 已将天下 万 国 赐 给我, 又嘱咐 我 在犹大 的 耶路撒冷 为他 建造 殿宇。 你们中间 凡 作他子民的,可以上去,愿 耶和华─他的 神 与他同在。」    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, '波斯 王 塞鲁士 元 年,耶和华 为要应验 藉 借耶利米 口 所说的话, 就激动 波斯 王 塞鲁士 的心, 使他下诏 通 告 全 国 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, '「波斯 王 塞鲁士 如此 说:『耶和华 天上的 神 已将天下 万 国 赐 给我, 又嘱咐 我 在犹大 的 耶路撒冷 为他 建造 殿宇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, ' 在你们中间 凡 作 他子民的,可以上 犹大 的 耶路撒冷, 在耶路撒冷 重建 耶和华─以色列 神 的殿(只有他是 神)。愿  神 与 这人同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, '凡 剩下的人,无论 寄居 何 处,那地 的人 要用金 银、财物、牲畜 帮助他, 另外也要为耶路撒冷 神 的殿 甘心献上礼物。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, '于 是,犹大 和便雅悯 的族 长、祭司、利未人,就是一切被 神 激动 他心的人,都起来 要上 耶路撒冷 去建造 耶和华 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, ' 他们四围的人 就拿银 器、金子、财物、牲畜、珍宝帮助他们(原文是坚固 他们的手),另外 还有 甘心献的礼物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, '塞鲁士 王 也将 耶和华 殿 的器皿 拿出来,这器皿 是尼布甲尼撒 从耶路撒冷 掠来、放 在自己神 之庙中的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, '波斯 王 塞鲁士派 库官 米提利达 将这器皿拿出来,按数 交给犹大 的首领 设巴萨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, '器皿的数目 记在下面:金 盘 三十个,银 盘 一千个,刀 二十 九把, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, '金 碗 三十个,银 碗 之次的 四 百 一十个,别样 的器皿 一千件。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, '金 银 器皿 共有 五 千 四 百件。被掳的人 从巴比伦 上 耶路撒冷的时候,设巴萨 将这一切 都带上来。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, ' 巴比伦 王 尼布甲尼撒 从前掳 到巴比伦 之犹大省 的人,现在他们的子孙 从被掳 到之地 回 耶路撒冷 和犹大,各 归本城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, '他们 是同著 所罗巴伯、耶书亚、尼希米、西莱雅、利来雅、末底改、必珊、米斯拔、比革瓦伊、利宏、巴拿 回来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, '以色列 人 民 的数目记在下面:巴录 的子孙 二千 一百 七十 二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, '示法提雅 的子孙 三 百 七十 二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, '亚拉 的子孙 七 百 七十 五名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, '巴哈‧摩押 的后裔,就是耶书亚 和约押 的子孙 二千 八 百 一十二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, '以拦 的子孙 一千 二百 五十 四名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, '萨土 的子孙 九 百 四十 五名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, '萨改 的子孙 七 百 六十名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, '巴尼 的子孙 六 百 四十 二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, '比拜 的子孙 六 百 二十 三名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, '押甲 的子孙 一千 二 百 二十 二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, '亚多尼干 的子孙 六 百 六十 六名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, '比革瓦伊 的子孙 二千 零五十 六名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, '亚丁 的子孙 四 百 五十 四名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, '亚特 的后裔,就是希西家的 子孙九十 八名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, '比赛 的子孙 三 百 二十 三名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, '约拉 的子孙 一百 一十二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, '哈顺 的子孙 二百 二十 三名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, '吉罢珥 人 九十 五名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, '伯利恒 人 一百 二十 三名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, '尼陀法 人 五十 六名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, '亚拿突 人 一百 二十 八名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, '亚斯玛弗 人 四十 二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, '基列‧耶琳 人、基非拉人、比录 人共七 百 四十 三名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, '拉玛 人、迦巴 人共六 百 二十 一名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, '默玛 人 一百 二十 二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, '伯特利 人、艾 人共二百 二十 三名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, '尼波 人 五十 二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, '末必 人 一百 五十 六名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, '别的 以拦 子孙 一千 二百 五十 四名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, '哈琳 的子孙 三 百 二十名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, '罗德 人、哈第 人、阿挪 人 共七 百 二十 五名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, '耶利哥 人 三 百 四十 五名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, '西拿 人 三 千 六 百 三十名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, '祭司:耶书亚 家 耶大雅 的子孙 九 百 七十 三名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, '音麦 的子孙 一千 零五十 二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, '巴施户珥 的子孙 一千 二百 四十 七名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, '哈琳 的子孙 一千 零一十 七名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, '利未人:何达威雅 的后裔,就是耶书亚 和甲篾 的子孙 七十 四名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, '歌唱的:亚萨 的子孙 一百 二十 八名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, '守门的:沙龙 的子孙、亚特 的子孙、达们 的子孙、亚谷 的子孙、哈底大 的子孙、朔拜 的子孙,共 一百 三十 九名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, '尼提宁(就是殿役):西哈 的子孙、哈苏巴 的子孙、答巴俄 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, '基绿 的子孙、西亚 的子孙、巴顿 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, '利巴拿 的子孙、哈迦巴 的子孙、亚谷 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, '哈甲 的子孙、萨买  的子孙、哈难 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, '吉德 的子孙、迦哈 的子孙、利亚雅 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, '利汛 的子孙、尼哥大 的子孙、迦散 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, '乌撒 的子孙、巴西亚 的子孙、比赛 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, '押拿 的子孙、米乌宁 的子孙、尼普心 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, '巴卜 的子孙、哈古巴 的子孙、哈忽 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, '巴洗律 的子孙、米希大 的子孙、哈沙 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, '巴柯 的子孙、西西拉 的子孙、答玛 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, '尼细亚 的子孙、哈提法 的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, '所罗门 仆人 的后裔,就是琐太 的子孙、琐斐列 的子孙、比路大 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, '雅拉 的子孙、达昆 的子孙、吉德 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, '示法提雅 的子孙、哈替 的子孙、玻黑列‧哈斯巴音 的子孙、亚米 的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, '尼提宁 和所罗门 仆人 的后裔 共 三 百 九十 二名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, '从特‧米拉、特‧哈萨、基绿、押但、音麦 上来的,不 能 指明 他们的宗 族 谱系 是 以色列人 不是; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, '他们是第来雅 的子孙、多比雅 的子孙、尼哥大 的子孙,共六 百 五十 二名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, '祭司中,哈巴雅 的子孙、哈哥斯 的子孙、巴西莱 的子孙;因为他们 的先祖娶了 基列人 巴西莱 的女儿 为妻,所以起 名 叫 巴西莱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, '这 三家的人在族谱 之中寻查 自己的谱系,却寻 不著,因此算为不洁,不准 供祭司的职任。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, '省长 对他们 说:「 不可 吃 至圣 的物,直到 有用乌陵 和土明 决疑的祭司 兴起来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, ' 会众 共 有四 万二 千 三 百 六十名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, '此外,还有他们的 仆 婢 七 千 三 百 三十 七名,又有歌唱的男 女 二百名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, '他们有马 七 百 三十 六匹,骡子 二百 四十 五匹, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, '骆驼 四 百 三十 五只,驴 六 千 七 百 二十匹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, '有些族 长 到了 耶路撒冷 耶和华 殿的地方,便为 神 的殿 甘心献上礼物,要重新建造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, '他们量力 捐 入工程 库 的金子 六万一千 达利克,银子 五 千 弥拿,并祭司 的礼服 一百件。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, '于 是祭司、利未人、民 中的一些人、歌唱的、守门的、尼提宁,并以色列 众人,各住 在自己的城里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, '到了 七 月,以色列 人 住在各城;那时他们 如同一 人,聚集 在 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, '约萨达 的儿子 耶书亚 和他的弟兄 众祭司,并撒拉铁 的儿子 所罗巴伯 与他的弟兄,都起来 建筑 以色列 神 的坛,要照神 人 摩西 律法 书上所写的,在坛上 献 燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, '他们在 原有的根基 上筑 坛,因 惧怕 邻国 的民,又在其上 向耶和华 早 晚 献 燔祭, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, '又照律法书上所写 的守 住棚 节,按数 照例 献每 日 所当献的 燔祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, '其后 献常献的 燔祭,并在月朔 与耶和华 的一切 圣 节献祭,又向耶和华 献 各人的 甘心祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, '从七 月 初一 日 起,他们就向耶和华 献 燔祭。但耶和华 殿 的根基尚未 立定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, '他们又将银子 给石匠、木匠,把粮食、酒、油 给 西顿人、泰尔人,使他们将香柏 树 从 黎巴嫩 运 到 海里,浮海运到约帕,是照波斯 王 塞鲁士 所允准的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, '百姓到了 耶路撒冷 神 殿的地方。第二 年 二 月,撒拉铁 的儿子 所罗巴伯,约萨达 的儿子 耶书亚 和其余 馀 的弟兄,就是祭司、利未人,并一切 被掳 归回 耶路撒冷的人,都兴工建造;又派 利未人,从 二十 岁 以外的,督理 建造耶和华 殿 的工作。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, '于 是犹大(在二章四十节作何达威雅)的后裔,就是耶书亚 和他的子孙 与弟兄,甲篾 和他的子孙,利未人 希拿达 的子孙 与弟兄,都一同 起来,督理那在 神 殿 做 工的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, '匠人 立 耶和华 殿 根基的时候,祭司 皆穿礼服 吹号,亚萨 的子孙 利未人 敲钹,照 以色列 王 大卫 所定的例,都站著 赞美 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, '他们彼此唱和,赞美 称谢 耶和华说:他本为 善, 他向 以色列人 永 发慈爱。他们赞美 耶和华的时候,众 民 大 声 呼喊,因 耶和华 殿 的根基已经立定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, '然而有许多 祭司、利未人、族 长,就是 见过 旧 殿 的老年人,现在亲眼 看见立 这 殿 的根基,便大 声 哭号,也有许多人 大 声 欢 呼, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, '甚至百姓 不能 分辨 欢 呼 的声音 和哭号 的声音;因为 众人 大 声 呼喊,声音 听 到 远处。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, '犹大 和便雅悯 的敌人 听说 被掳 归回的人 为耶和华─以色列的 神 建造 殿宇, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, '就去 见 所罗巴伯 和 以色列的族 长,对他们 说:「请容我们与你们 一同建造;因为 我们寻求你们的 神,与你们一样。自从 亚述 王 以撒哈顿 带我们 上 这地以来,我们 常祭祀 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, '但所罗巴伯、耶书亚,和其余 馀 以色列 的族 长 对他们 说:「我们 建造 神 的殿 与你们 无干, 我们自己 为耶和华─以色列的 神 协力 建造,是照波斯 王 塞鲁士 所 吩咐的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, ' 那地 的民,就在犹大 人 建造的时候,使他们的手 发软,扰乱 他们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, '从波斯 王 塞鲁士 年间,直到 波斯 王 大流士 登基的时候,贿买  谋士,要败坏 他们的谋算。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, '在亚哈随鲁 才 登基的时候,上本 控告 犹大 和耶路撒冷 的居民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, '亚达薛西 年间,比施兰、米特利达、他别,和他们的同党 上本奏告 波斯 王 亚达薛西。本章 是用 亚兰 文字,亚兰 方言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, '省 长 利宏、书记 伸帅 要控告 耶路撒冷人,也 上 本 奏告 亚达薛西 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, ' 省 长 利宏、书记 伸帅, 和同党 的底拿人、亚法萨提迦人、他毘拉人、亚法撒人、亚基卫人、巴比伦人、书珊迦人、底亥人、以拦人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, ' 和尊 大 的亚斯那巴 所迁移、安置 在撒马利亚 城,并大河 西 一带 地方 的人等, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, ' 上奏 亚达薛西 王说:「河 西 的臣 民云云: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, '王 该 知道, 从 王那里 上 到我们 这里的犹大人, 已经到 耶路撒冷 重建 这反叛 恶劣 的城,筑立 根基,建造 城墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, '如今 王 该 知道, 他们若 建造 这 城,城墙 完毕 就不 再 与王进贡,交课,纳税,终久王 必受亏损。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, ' 我们既 食 御 盐,不 忍 见 王 吃亏,因此 奏告 于 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, ' 请王考察 先王 的实 录, 必在其 上 查 知 这 城 是反叛的 城,与列王 和各省 有害;自 古 以来,其中 常有 悖逆的事,因 此 这 城 曾被拆毁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, '我们 谨奏王 知,这 城若 再建造,城墙 完毕, 河 西 之地王 就 无 分了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, '那时王 谕 覆 复 省 长 利宏、书记 伸帅, 和他们的同党,就是住 撒马利亚 并河 西 一带地方的人,说:「愿 你们平安 云云。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, '你们所 上 的本,已经明 读 在我面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, '我 已命人 考查,得知 此 城 古 来 果然 背叛 列王,其中 常有 反叛 悖逆的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, '从前 耶路撒冷 也有 大 君王 统管 河 西 全地,人就给 他们 进贡,交课,纳税。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, '现在 你们要出告示 命 这些 人 停工,使这 城 不得 建造,等 我 降 旨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, '你们当 谨慎,不可迟 延,为何 容害 加重,使王 受亏损呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, ' 亚达薛西 王 的上谕 读 在利宏 和书记 伸帅,并他们的同党 面前,他们就急忙 往 耶路撒冷 去见 犹大人,用势力 强迫他们 停工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, '于 是,在耶路撒冷 神 殿的 工程 就停止了,直停 到 波斯 王 大流士 第二 年。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, '那时,先知 哈该 和易多 的孙子 撒迦利亚 奉以色列 神 的名 向 犹大 和耶路撒冷 的 犹大人 说劝勉的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, '于 是 撒拉铁 的儿子 所罗巴伯 和约萨达 的儿子 耶书亚 都起来 动手 建造 耶路撒冷 神 的殿,有 神 的 先知 在那里 帮助 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, '当 时 河 西 的总督 达乃和示他‧波斯乃,并他们的同党 来 问说:「谁 降 旨 让你们 建造 这 殿,修成 这 墙呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, ' 我们便告诉 他们 建造 这 殿 的人 叫什么 名字。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, '神 的眼目 看顾 犹大 的长老,以致总督等没有 叫 他们 停工,直到 这事 奏告 大流士, 得著他的回 谕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, '河 西 的总督 达乃和示他‧波斯乃,并他们的同党,就是 住河 西 的亚法萨迦人, 上 本 奏告 大流士 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, ' 本上 写著说:「愿 大流士 王 诸事 平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, '王 该 知道, 我们往 犹大 省去,到了至大 神 的殿,这殿 是用大 石 建造的。梁木 插入 墙内, 工作 甚速,他们手下 亨通。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, ' 我们就问 那些 长老 说:『谁 降 旨 让你们 建造 这 殿,修成 这 墙呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, '又 问 他们的 名字,要 记录 他们首领 的名字,奏告于 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, '他们回答 说:『我们 是 天 地 之 神 的仆人,重建 前多年 所 建造 的殿,就是以色列 的一位大 君王 建造 修成的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, '只因 我们列祖 惹天上的 神 发怒, 神 把他们 交在 迦勒底人 巴比伦 王 尼布甲尼撒 的手中,他就拆毁 这 殿,又将百姓 掳到 巴比伦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, '然而 巴比伦 王 塞鲁士 元 年, 他降旨 允准 建造 神 的这 殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, '神 殿 中的 金、 银 器皿,就是 尼布甲尼撒 从 耶路撒冷 的殿 中掠去 带到 巴比伦 庙里的, 塞鲁士 王 从 巴比伦 庙 里取出来,交给 派为 省长 的,名叫 设巴萨, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, '对他 说 可以将这些 器皿 带 去, 放 在耶路撒冷 的 殿中,在 原处 建造 神 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, '于 是 这 设巴萨 来 建立 耶路撒冷 神 殿 的根基。这殿 从 那时 直到 如今 尚未 造 成。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, '现在 王 若 以为 美,请察 巴比伦 王 的 府 库, 看塞鲁士 王 降 旨 允准在耶路撒冷 建造 神 的殿 没有,王 的心意如何?请降 旨 晓谕我们。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, '于 是 大流士 王 降 旨,要寻察 典籍 库内,就是 在巴比伦 藏 宝物 之处; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, ' 在米底亚 省亚马他 城 的宫内 寻得 一 卷,其中 记著 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, '「塞鲁士 王 元 年, 他降 旨 论到耶路撒冷 神 的殿,要建造 这殿 为 献 祭 之处,坚立 殿的根基。殿高 六十 肘,宽 六十 肘, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, '用三 层 大 石头,一层 新 木头,经费 要出 于  王 库; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, '并且 神 殿 的 金 银 器皿,就是 尼布甲尼撒 从 耶路撒冷 的殿 中掠 到 巴比伦的,要归还 带到 耶路撒冷 的 殿中,各按原处 放在 神 的殿里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, '「现在 河 西 的总督 达乃和示他‧波斯乃,并你们的同党,就是 住河 西 的亚法萨迦人,你们当 远 离 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, '不要拦阻 神 殿 的工作,任凭犹大人 的省长 和犹大人 的长老 在 原处 建造 神 的这 殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, '我 又降 旨,吩咐你们向 犹大人 的长老 为建造 神 的殿 当怎样 行,就是从河 西 的 款项中,急速 拨 取 贡 银 作他们 的经费, 免得 耽误工作。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, '他们与天上的 神 献燔祭 所 需用的 公牛 犊、公绵羊、绵羊羔,并所用的麦子、盐、酒、油,都要照 耶路撒冷 祭司 的话, 每 日 供给 他们, 不得 有误; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, ' 好叫 他们献 馨香的祭 给天上的 神,又为王 和王众子 的寿命 祈祷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, '我再 降 旨,无论 谁 更改 这 命令,必从 他房屋 中拆出 一根梁来,把他举起,悬 在其上,又使 他的房屋 成为粪堆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, '若有 王 和民 伸 手 更改这命令,拆毁 这 殿,愿 那 使耶路撒冷 的殿作为他 名 居所 的 神 将他们灭绝。我─大流士 降 这旨意,当速速 遵行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, '于 是,河 西 总督 达乃和示他‧波斯乃,并他们的同党,因 大流士 王 所 发的命令,就 急速 遵行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, '犹大 长老 因先知 哈该 和易多 的孙子 撒迦利亚 所说劝勉的话 就建造这殿,凡事亨通。他们遵著 以色列 神 的命令 和波斯 王 塞鲁士、大流士、亚达薛西 的旨意,建造 完毕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, ' 大流士 王 第六 年,亚达 月 初三 日,这 殿 修成了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, '以色列 的祭司 和利未人,并其余 馀 被掳归回 的人 都欢欢喜喜地 行 奉献 神 殿的礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, '行奉献 神 殿 的礼就献 公牛 一百只,公绵羊 二百只,绵羊羔 四百只,又照以色列 支派 的数目 献公 山羊 十二只,为 以色列 众人 作赎罪祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, '且派 祭司 和利未人 按著班次 在耶路撒冷 事奉 神,是照摩西 律法书 上所写的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, '正 月 十 四日,被掳归回 的人 守 逾越节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, '原来,祭司 和利未人 一同 自洁,无一人不 洁净。利未人为被掳归回 的众 人 和他们的弟兄 众祭司,并为自己 宰 逾越节的羊羔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, '从掳到之地 归回 的以色列 人 和一切 除掉 所染 外邦人 污秽、归附他们、要寻求 耶和华─以色列 神 的人都吃这羊羔, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, '欢欢喜喜地 守 除酵 节 七 日;因为 耶和华 使他们欢喜,又使亚述 王 的心 转 向他们,坚固 他们的手,作以色列 神 殿 的工程。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, '这 事 以后,波斯 王 亚达薛西 年间,有个以斯拉,他是西莱雅 的儿子,西莱雅是亚撒利雅 的儿子,亚撒利雅是希勒家 的儿子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, '希勒家是沙龙 的儿子,沙龙是撒督 的儿子,撒督是亚希突 的儿子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, '亚希突是亚玛利雅 的儿子,亚玛利雅是亚撒利雅 的儿子,亚撒利雅是米拉约 的儿子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, '米拉约是西拉希雅 的儿子,西拉希雅是乌西 的儿子,乌西是布基 的儿子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, '布基是亚比书 的儿子,亚比书是非尼哈 的儿子,非尼哈是以利亚撒 的儿子,以利亚撒是大 祭司 亚伦 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, '这 以斯拉 从巴比伦 上来,他是 敏捷的 文士,通达耶和华─以色列 神 所 赐 摩西 的律法书。王 允准 他 一切 所求的,是因耶和华─他 神 的手 帮助他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, '亚达薛西 王 第七 年,以色列 人、 祭司、利未人、歌唱的、守门的、尼提宁,有上 耶路撒冷的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, ' 王 第七 年 五 月,以斯拉到了 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, ' 正 月 初一日,他 从巴比伦 起 程;因他 神 施恩的 手 帮助他,五 月 初一 日就到了 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, ' 以斯拉 定志 考究 遵行 耶和华 的律法,又将律例 典章 教训 以色列人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, '祭司 以斯拉 是通达 耶和华 诫命 和赐 以色列 之律例 的文士。亚达薛西 王 赐 给他们 谕旨,上面 写著说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, '「诸王 之王 亚达薛西,达于 祭司 以斯拉 通达天上 神 律法 大德 的文士,云云。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, ' 住在我国 中的 以色列 人、祭司、利未人,凡 甘心 上 耶路撒冷去的,我 降 旨 准他们与你 同去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, '王 与七个 谋士 既然 差 你去,照 你手中 神 的律法书 察问 犹大 和耶路撒冷的景况; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, '又带 金 银,就是 王 和谋士 甘心献给 住 耶路撒冷、以色列 神的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, '并带你在巴比伦 全 省 所 得 的 金 银,和 百姓、祭司 乐意 献给 耶路撒冷─他们 神 殿的礼物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, ' 所以你当用这 金银,急速 买  公牛、公绵羊、绵羊羔,和同献的素祭 奠祭之物,献 在 耶路撒冷─你们 神 殿 的坛 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, '剩下 的金 银, 你 和 你的弟兄 看著怎样 好,就怎样用,总要遵著你们 神 的旨意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, '所 交 给你 神 殿 中使用 的器皿,你要交 在耶路撒冷 神 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, '你 神 殿 里若再 有需用 的 经费,你可以从 王 的府 库 里支取。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, '「 我─亚达薛西 王 又降 旨 与河 西 的 一切 库官,说:『通达天上 神 律法 的 文士 祭司 以斯拉,无论 向你们要什么,你们要速速地 备办, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, '就是银子 直到 一百 他连得, 麦子 一百 柯珥, 酒 一百 罢特, 油 一百 罢特, 盐 不 计其数,也要给他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, '凡 天上之 神 所 吩咐的,当为天上 神 的殿 详细 办理。 为何 使忿怒 临 到 王 和王众子 的国呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, '我又晓谕 你们,至于  祭司、利未人、歌唱的、守门的,和尼提宁,并在 神 殿 当差的人,不 可 叫他们 进 贡,交课,纳税。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, '「 以斯拉啊,要照著你 神 赐你 的智慧,将所有 明白你 神 律法 的人立 为 士师、审判官,治理 河 西 的 百姓,使他们教训 一切 不 明白 神律法的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, '凡 不 遵行你 神 律法 和 王 命令 的人就当速速 定 他的 罪,或 治死,或 充军,或 抄家,或囚禁。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, '以斯拉说:「耶和华─我们列祖的 神 是应当称颂的!因他 使王 起 这 心意 修饰 耶路撒冷 耶和华 的 殿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, '又在王 和谋士,并 大能的 军长 面前 施 恩 于 我。因耶和华─我 神 的手 帮助我,我 就得以坚强,从以色列 中招聚 首领,与我 一同上来。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, '当亚达薛西 王 年间,同我 从巴比伦 上来的人,他们的族 长 和他们的家谱 记在下面: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, '属非尼哈 的子孙 有革顺;属以他玛 的子孙 有但以理;属大卫 的子孙 有哈突; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, '属巴录 的后裔,就是示迦尼 的子孙 有撒迦利亚,同著他,按家谱计算,男丁 一百 五十人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, '属巴哈‧摩押 的子孙 有西拉希雅 的儿子 以利约乃,同著他 有男丁 二百; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, '属示迦尼 的子孙 有雅哈悉 的儿子,同著他 有男丁 三百; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, '属亚丁 的子孙 有约拿单 的儿子 以别,同著他 有男丁 五十; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, '属以拦 的子孙 有亚他利雅 的儿子 耶筛亚,同著他 有男丁 七十; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, '属示法提雅 的子孙 有米迦勒 的儿子 西巴第雅,同著他 有男丁 八十; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, '属约押 的子孙 有耶歇 的儿子 俄巴底亚,同著他 有男丁 二百 一十 八; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, '属示罗密 的子孙 有约细斐 的儿子,同著他 有男丁 一百 六十; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, '属比拜 的子孙 有比拜 的儿子 撒迦利亚,同著他 有男丁 二十 八; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, '属押甲 的子孙 有哈加坦 的儿子 约哈难,同著他 有男丁 一百 一十; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, '属亚多尼干 的子孙,就是末尾的,他们的名字 是 以利法列、耶利、示玛雅,同著他们 有男丁 六十; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, '属比革瓦伊 的子孙 有乌太 和撒布,同著他们 有男丁 七十。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, '我招聚 这些人在 流 入 亚哈瓦 的河边,我们在那里 住了 三 日。我查看 百姓 和祭司,见 没有 利未 人 在那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, '就召 首领 以利以谢、亚列、示玛雅、以利拿单、雅立、以利拿单、拿单、撒迦利亚、米书兰,又召教习 约雅立 和以利拿单。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, '我打发 他们 往迦西斐雅 地方 去见 那里的首领 易多,又告诉 他们 当向 易多 和他的弟兄 尼提宁 说 什么话,叫他们为我们 神 的殿 带 使用的人来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, '蒙我们 神 施恩 的手 帮助我们,他们在以色列 的曾孙、利未 的孙子、抹利 的后裔 中带 一个通达 人来;还有示利比 和他的众子 与弟兄 共一十 八人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, '又有 哈沙比雅,同著他 有米拉利 的子孙 耶筛亚,并他的众子 和弟兄 共二十人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, '从前大卫 和众首领 派 尼提宁 服事 利未人,现在从 这尼提宁 中也带了二百 二十人来,都是 按名 指定的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, '那时,我在 亚哈瓦 河 边宣告 禁食,为要在我们 神 面前 克苦己心,求 他 使我们 和妇人孩子,并一切 所有的,都得平坦的 道路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, '我求 王 拨步兵 马兵 帮助我们 抵挡路上 的仇敌,本以为 羞耻;因 我曾 对王 说:「我们 神 施恩 的手 必帮助 一切 寻求他的;但他的能力 和忿怒 必攻击 一切 离弃他的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, '所以我们禁食 祈求我们的 神,他就应允 了我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, '我分派 祭司 长 十 二人,就是示利比、哈沙比雅,和他们的 弟兄 十人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, '将王 和谋士、军长,并在那里的 以色列 众人为我们 神 殿 所献的 金 银 和 器皿,都秤了 交 给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, '我秤了 交 在他们手 中的银子 有六 百 五十 他连得;银 器 重 一百他连得;金子 一百 他连得; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, '金 碗 二十个,重一千 达利克;上等 光 铜 的器皿 两个,宝贵 如金。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, '我对他们 说:「你们 归耶和华 为圣,器皿 也为圣;金 银 是甘心 献给耶和华─你们列祖之 神的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, '你们当警醒 看守,直到 你们在耶路撒冷 耶和华 殿 的库内,在祭司 长 和利未族长,并以色列 的各族 长 面前 过了秤。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, '于 是,祭司、利未人 按著分量 接受 金 银 和器皿,要带到 耶路撒冷我们 神 的殿里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, '正 月 十 二日,我们从亚哈瓦 河 边起行,要往 耶路撒冷去。我们 神 的手 保佑我们,救我们 脱离仇敌和 路上 埋伏 之人的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, '我们到了 耶路撒冷,在那里 住了 三 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, '第四 日,在我们 神 的殿 里把金 银 和器皿 都秤了,交 在祭司 乌利亚 的儿子 米利末 的手中。同著他 有非尼哈 的儿子 以利亚撒,还有 利未人 耶书亚 的儿子 约撒拔 和宾内 的儿子 挪亚底。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, '当 时 都 点了数目,按著分量 写在册上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, '从掳到之地 归回 的人 向以色列的 神 献 燔祭,就是为 以色列 众人 献公牛 十 二只,公绵羊 九十 六只,绵羊羔 七十 七只,又献公山羊 十 二 只作赎罪祭,这都是 向耶和华 焚献的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, '他们将 王 的谕旨 交 给王 所派的总督 与河 西 的省长,他们就帮助 百姓,又供给 神 殿里所需用的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, '这 事做完了,众首领 来 见我,说:「以色列 民 和祭司 并利未人,没有 离绝 迦南人、赫人、比利洗人、耶布斯人、亚扪人、摩押人、埃及人、亚摩利人,仍效法这些国 的民,行可憎的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, '因 他们为自己 和儿子 娶了 这些外邦女子为妻,以致圣洁的 种类 和这些国 的民 混杂;而且 首领 和官长 在这 事上 为 罪魁。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, '我一听见 这 事,就撕裂 衣服 和外袍,拔了 头 发 和胡须,惊惧忧闷 而坐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, '凡 为以色列 神 言语 战 兢的,都因 这被掳归回之人 所犯的罪 聚集 到我这里来。我 就惊惧忧闷 而坐,直到 献晚 祭的时候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, '献晚 祭 的时候我起来,心中愁苦,穿著撕裂的 衣 袍, 双膝 跪下 向 耶和华─我的 神 举 手, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, '说:「我的 神啊,我抱愧 蒙羞,不敢向我 神 仰 面;因为 我们的罪孽 灭 顶,我们的罪恶 滔 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, '从 我们列祖 直到 今 日,我们 的罪恶 甚重;因我们的罪孽,我们 和君王、祭司 都交 在外邦 列王 的手中,杀害、掳掠、抢夺、脸上 蒙羞 正如今 日的光景。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, '现在 耶和华─我们的 神 暂且 施 恩与我们,给我们 留些 逃脱的人,使 我们 安稳如钉子 钉在他的圣 所,我们的 神 好光照 我们的眼目,使我们 在受辖制之中 稍微 复兴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, ' 我们 是奴仆,然而在受辖制之中,我们的 神 仍没有 丢弃我们,在波斯 王 眼前 向我们 施 恩,叫 我们 复兴,能重建我们 神 的殿,修 其毁坏之处,使 我们 在犹大 和耶路撒冷 有墙垣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, '「我们的 神啊,既是 如此,我们还有什么 话可说呢?因为 我们已经离弃 你的命令, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, '就是 你藉 借 你仆人 众先知 所吩咐 的说:『你们 要去 得为业 之地 是 污秽 之地;因列国 之民 的污秽 和可憎的事,叫全地从这边 直到 那边 满了 污秽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, '所以 不可 将你们的女儿 嫁 他们的儿子,也不可 为你们的儿子 娶 他们的女儿,永 不可 求 他们的平安 和他们的利益,这样 你们就可以强盛,吃 这地 的美物,并遗留这地给你们的子孙 永远 为业。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, '神啊, 我们因自己的恶 行 和大 罪,遭遇了 这一切的事,并且 你 刑罚 我们轻于  我们罪所当得的,又给 我们 留下这些 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, '我们岂可再 违背 你的命令,与这 行可憎之事 的民 结亲呢?若这样行,你岂不 向我们 发怒,将我们灭绝,以致 没有 一个剩下 逃脱的人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, '耶和华─以色列的 神啊,因你 是公义的, 我们这剩下的 人才得逃脱,正如今 日的光景。看哪,我们在你面前 有罪恶,因 此 无人 在你面前 站立得住。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, '以斯拉 祷告,认罪,哭泣,俯伏在 神 殿 前的时候,有以色列 中的男 女 孩童 聚集 到以斯拉那里,成了大 会, 众民 无不痛 哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, '属以拦 的子孙、耶歇 的儿子 示迦尼 对以斯拉 说:「我们 在此地 娶了 外邦 女子 为妻,干犯了我们的 神,然而 以色列人 还有 指望。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, '现在当与我们的 神 立 约,休 这一切的 妻,离绝她们 所生的,照著我主和那因 神 命令 战 兢 之人所议定的,按律法 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, '你起来,这是 你当 办的事,我们必帮助你,你 当奋勉 而行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, '以斯拉 便起来,使 祭司 长 和利未人,并以色列 众人 起誓说,必照这 话 去行;他们就起了誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, '以斯拉从 神 殿 前 起来,进 入 以利亚实 的儿子 约哈难 的屋里,到了 那里 不 吃 饭,也不 喝 水;因为 被掳归回之人 所 犯的罪,心里悲伤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, '他们通 告 犹大 和耶路撒冷 被掳归回的 人,叫他们在耶路撒冷 聚集。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, '凡 不 遵首领 和长老 所议定、三 日 之内不来的,就必抄 他的家,使他 离开  被掳归回之人 的会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, '于 是,犹大 和便雅悯 众 人,三 日 之内都聚集 在耶路撒冷。那日正是 九 月 二十日,众 人 都坐在 神 殿 前的宽阔处;因 这事,又因下大雨,就都战 兢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, '祭司 以斯拉 站起来,对他们 说:「你们 有罪了;因你们娶了 外邦的 女子为妻,增添 以色列人 的罪恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, '现在 当向耶和华─你们列祖的 神 认 罪,遵行 他的旨意,离绝 这些国 的民 和 外邦 的女子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, '会众 都 大 声 回答 说:「我们必照著你的话 行, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, '只是 百姓 众多,又逢大雨 的时令,我们不 能 站 在外头,这也不是 一 两 天 办完的事,因 我们在这 事 上犯了大 罪; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, ' 不如为全 会众 派 首领办理。凡 我们城邑 中娶 外邦 女子为妻的,当按所定的 日期,同著 本 城 的长老 和士师 而来,直到 办完这 事, 神 的烈 怒 就转离 我们了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, '惟有 亚撒黑 的儿子 约拿单,特瓦 的儿子 雅哈谢 阻挡(或译:总办) 这事,并有米书兰 和利未人 沙比太 帮助他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, '被掳归回 的人 如此 而行。祭司 以斯拉 和些 族 长 按著宗 族 都 指名 见派;在十 月 初一 日,一同在座 查办 这事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, '到 正 月 初一 日,才查清 娶 外邦 女子的 人数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, '在祭司中 查出 娶 外邦 女子为妻的,就是耶书亚 的子孙 约萨达 的儿子,和他弟兄 玛西雅、以利以谢、雅立、基大利; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, '他们便应许 必休 他们的妻。他们因有罪,就献群 中的一只公绵羊 赎 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, '音麦 的子孙中,有哈拿尼、西巴第雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, '哈琳 的子孙中,有玛西雅、以利雅、示玛雅、耶歇、乌西雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, '巴施户珥 的子孙中,有以利约乃、玛西雅、以实玛利、拿坦业、约撒拔、以利亚撒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, '利未人 中,有约撒拔、示每、基拉雅(基拉雅就是 基利他),还有毘他希雅、犹大、以利以谢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, '歌唱的人 中 有以利亚实。守门的人 中,有沙龙、提联、乌利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, '以色列人 巴录 的子孙中,有拉米、耶西雅、玛基雅、米雅民、以利亚撒、玛基雅、比拿雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, '以拦 的子孙中,有玛他尼、撒迦利亚、耶歇、押底、耶利末、以利雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, '萨土 的子孙中,有以利约乃、以利亚实、玛他尼、耶利末、撒拔、亚西撒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, '比拜 的子孙中,有约哈难、哈拿尼雅、萨拜、亚勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, '巴尼 的子孙中,有米书兰、玛鹿、亚大雅、雅述、示押、耶利末。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, '巴哈‧摩押 的子孙中,有阿底拿、基拉、比拿雅、玛西雅、玛他尼、比撒列、宾内、玛拿西。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, '哈琳 的子孙中,有以利以谢、伊示雅、玛基雅、示玛雅、西缅、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, '便雅悯、玛鹿、示玛利雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, '哈顺 的子孙中,有玛特乃、玛达他、撒拔、以利法列、耶利买 、玛拿西、示每。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, '巴尼 的子孙中,有玛玳、暗兰、乌益、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, '比拿雅、比底雅、基禄、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, '瓦尼雅、米利末、以利亚实、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, '玛他尼、玛特乃、雅扫、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, '巴尼、宾内、示每、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, '示利米雅、拿单、亚大雅、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, '玛拿底拜、沙赛、沙赖、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, '亚萨利、示利米雅、示玛利雅、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, '沙龙、亚玛利雅、约瑟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, '尼波 的子孙中,有耶利、玛他提雅、撒拔、西比拿、雅玳、约珥、比拿雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, '这些 人都 娶 了外邦 女子为妻,其中 也有 生了 儿女的。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, '哈迦利亚 的儿子 尼希米 的言语如下: 亚达薛西王二十 年 基斯流 月,我 在 书珊城 的宫中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, '那时,有我一个 弟兄 哈拿尼, 同著几个人 从犹大 来。我问他们 那些 被掳归回、 剩下 逃脱 的犹大人 和 耶路撒冷的光景。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, '他们对我 说:「那些 被掳 归回 剩下 的人在犹大 省 遭大 难,受凌辱;并且耶路撒冷 的城墙 拆毁,城门 被火 焚烧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, ' 我听见 这 话,就坐下 哭泣,悲哀 几日,在天上的 神 面前 禁食 祈祷,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, '「 耶和华─天上的 神,大 而可畏的 神啊,你向爱你、守 你诫命 的人守 约 施慈爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, '愿 你 睁 眼看, 侧 耳 听, 你仆人 昼 夜 在你面前 为 你众仆人 以色列 民 的祈祷,承认 我们以色列 人 向你 所 犯 的罪;我 与我父 家 都有罪了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, '我们向你 所行的甚是 邪恶,没有 遵守你藉 借著 仆人 摩西 所 吩咐的 诫命、 律例、 典章。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, '求 你记念 所 吩咐 你仆人 摩西 的话,说:『你们 若犯罪,我 就把你们 分散 在万民中; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, '但你们若归 向我,谨守 遵行 我的诫命,你们被赶散 的人虽 在天 涯,我也必从那里 将他们招聚回来,带 到 我所 选择 立 为 我名 的居所。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, '这 都是你的仆人、你的百姓,就是 你用大 力 和大能 的手 所救赎的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, ' 主啊,求 你侧 耳听 你仆人 的祈祷,和 喜爱 敬畏 你名 众仆人 的祈祷, 使你仆人 现今 亨通,在王 面前 蒙 恩。」我 是 作王 酒政的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, ' 亚达薛西 王 二十 年 尼散 月,在王面前 摆酒,我拿起 酒 来奉给 王。我素来在王面前 没 有 愁容。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, '王 对我 说:「你 既没有 病,为什么 面 带愁容呢?这 不是别的,必是 你心中 愁烦。」于 是我甚 惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, '我对王 说:「愿 王 万岁!我列祖 坟墓 所 在的 那城 荒凉,城门 被火 焚烧,我岂能 面 无 愁容吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, '王 问我 说:「你 要求 什么?」于 是我默祷 天上的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, '我对王 说:「仆人 若 在王眼前 蒙恩,王 若 喜欢, 求王差遣我 往 犹大,到 我列祖 坟墓 所在的那城去,我好重新建造。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, '那时王后 坐 在王的旁边。王 问我 说:「 你去 要 多少日子?几时 回来?」我就定了 日期。于 是王 喜欢 差遣我去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, '我又对王 说:「 王 若 喜欢,求王赐 我 诏书,通知 大河 西 的省长 准我经过, 直到 犹大; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, '又赐诏书,通知 管理 王 园林 的 亚萨, 使他给 我 木料,做 属殿 营楼 之 门 的横梁 和城 墙,与我自己房屋使用的。」王 就允准 我,因我 神 施恩 的手 帮助我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, '王 派了 军 长 和马兵 护送我。我到了 河 西 的省长那里,将 王 的诏书 交 给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, '和伦人 参巴拉,并为奴的 亚扪人 多比雅,听见 有 人 来 为以色列 人 求 好处,就甚 恼怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, '我到了 耶路撒冷,在那里 住了 三 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, '我 夜间 起来,有几个 人 也一同起来;但 神 使 我心 里要为耶路撒冷 做 什么事,我并没有 告诉 人。除了 我 骑 的 牲口以外,也没有 别的牲口 在我那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, '当夜 我出了 谷 门,往 野狗 井去(野狗:或译龙),到了 粪厂 门, 察看 耶路撒冷 的城墙,见城墙 拆毁,城门 被火 焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, '我又往前,到了 泉 门 和 王 池,但所骑的牲口 没有 地方 过去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, '于 是夜间 沿溪 而 上, 察看 城墙,又转身 进入 谷 门,就回来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, '我往哪里 去,我 做 什么事,官长 都不 知道。我还 没有 告诉 犹大平民、祭司、贵胄、官长,和其余 馀 做 工的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, '以后,我对他们 说:「我们 所 遭的难,耶路撒冷 怎样 荒凉,城门 被火 焚烧,你们 都看见了。来吧,我们重建 耶路撒冷 的城墙,免得 再 受凌辱!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, '我告诉 他们我 神 施恩 的手 怎样 帮助我,并 王 对我 所 说 的话。他们就说:「我们起来 建造吧!」于 是他们 奋勇 做这善工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, '但和伦人 参巴拉,并为奴的 亚扪人 多比雅 和阿拉伯人 基善 听见 就嗤笑 我们,藐视 我们,说:「你们 做 什么呢? 要背叛 王吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, '我回 答 他们 说:「天上的 神 必 使我们 亨通。我们 作他仆人的,要起来 建造;你们 却在耶路撒冷 无 分、无权、无纪念。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, '那时,大 祭司 以利亚实 和他的弟兄 众祭司 起来 建立 羊 门, 分别为圣,安立 门扇,又筑城墙到 哈米亚 楼,直到 哈楠业 楼,分别为圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, '其 次 是耶利哥 人 建造。其 次 是音利 的儿子 撒刻 建造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, '哈西拿 的子孙 建立 鱼 门, 架横梁、安 门扇,和闩 锁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, '其 次 是哈哥斯 的孙子、乌利亚 的儿子 米利末 修造。其 次 是米示萨别 的孙子、比利迦 的儿子 米书兰 修造。其 次 是巴拿 的儿子 撒督 修造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, '其 次 是提哥亚人 修造;但是他们的贵胄 不 用肩(原文是颈项)担他们主 的工作。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, '巴西亚 的儿子 耶何耶大 与比所玳 的儿子 米书兰 修造 古 门, 架横梁,安 门扇 和闩 锁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, '其 次 是基遍人 米拉提,米伦人 雅顿 与基遍 人,并属河 西 总督 所管的 米斯巴人 修造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, '其 次 是银匠 哈海雅 的儿子 乌薛 修造。其 次 是做香的 哈拿尼雅 修造。这些人修坚 耶路撒冷,直到 宽 墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, '其 次 是管理 耶路撒冷 一半、户珥 的儿子 利法雅 修造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, '其 次 是哈路抹 的儿子 耶大雅 对著 自己的房屋 修造。其 次 是哈沙尼 的儿子 哈突 修造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, '哈琳 的儿子 玛基雅和巴哈‧摩押 的儿子 哈述 修造 一段,并修造 炉 楼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, '其 次 是管理 耶路撒冷 那一半、哈罗黑 的儿子 沙龙 和他的女儿们 修造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, '哈嫩 和撒挪亚 的居民 修造 谷 门, 立门,安 门扇 和闩 锁,又建筑城墙 一千 肘,直到 粪厂 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, '管理伯‧哈基琳、利甲 的儿子 玛基雅 修造 粪厂 门,立门,安 门扇 和闩 锁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, '管理 米斯巴、各荷西 的儿子 沙仑  修造 泉 门,立门,盖门顶,安 门扇 和闩 锁,又修造 靠近王 园 西罗亚 池 的墙垣,直到 那从大卫 城 下来 的台阶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, '其次 是管理伯‧夙 一半、押卜 的儿子 尼希米 修造,直到 大卫 坟地 的对面,又到 挖成 的池子,并 勇士 的房屋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, '其次 是利未人 巴尼 的儿子 利宏 修造。其 次 是管理 基伊拉 一半、哈沙比雅 为他所管的本境 修造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, '其次 是利未人弟兄 中管理 基伊拉那 一半、希拿达 的儿子 巴瓦伊 修造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, '其 次 是管理 米斯巴、耶书亚 的儿子 以谢 修造 一 段,对著 武库 的上坡、城墙转弯之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, '其次 是萨拜 的儿子 巴录 竭力 修造 一段,从 城墙转弯,直到 大 祭司 以利亚实 的府 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, '其次 是哈哥斯 的孙子、乌利亚 的儿子 米利末 修造 一段,从以利亚实 的府 门,直到 以利亚实 府 的尽头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, '其次 是住平原 的祭司 修造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, '其次 是便雅悯 与哈述 对著 自己的房屋 修造。其次 是亚难尼 的孙子、玛西雅 的儿子 亚撒利雅 在靠近 自己的房屋 修造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, '其次 是希拿达 的儿子 宾内 修造 一段,从亚撒利雅 的房屋 直到 城墙转弯,又到 城角。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, '乌赛 的儿子 巴拉 修造对著 城墙的转弯 和王 上 宫 凸出来 的城楼,靠近护卫 院 的那一段。其次 是巴录 的儿子 毘大雅修造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, '(尼提宁 住 在俄斐勒,直到 朝东 水 门 的对面 和凸出来的 城楼。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, '其次 是提哥亚人 又修 一段,对著 那凸出来的 大 楼,直到 俄斐勒 的墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, '从 马 门往上,众祭司 各 对 自己的房屋 修造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, '其次 是音麦 的儿子 撒督 对著 自己的房屋 修造。其次 是守 东 门、示迦尼 的儿子 示玛雅 修造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, '其次 是示利米雅 的儿子 哈拿尼雅 和萨拉 的第六 子 哈嫩 又修 一段。其次 是比利迦 的儿子 米书兰 对著 自己的房屋 修造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, '其次 是银 匠 玛基雅 修造 到 尼提宁 和商人 的房屋,对著 哈米弗甲 门,直到 城的角 楼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, '银匠 与商人 在城的角 楼 和羊 门 中间 修造。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, ' 参巴拉 听见 我们 修造 城墙 就发怒,大大 恼恨,嗤笑 犹大人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, ' 对 他弟兄 和撒马利亚 的军兵 说:「这些软弱的 犹大人 做 什么呢?要保护 自己吗?要献祭吗?要一日 成功吗? 要从土 堆 里拿出火烧 的石头 再立墙吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, '亚扪人 多比雅 站在旁边,说:「他们 所 修造 的石 墙,就是 狐狸 上去 也 必跐倒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, '我们的 神啊,求你垂听,因为 我们被 藐视。求你使他们的毁谤 归 于  他们的头上,使他们 在掳到 之地 作为掠物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, '不要 遮掩 他们的罪孽,不要 使他们的罪恶 从你面前 涂抹,因为 他们在修造的人 眼前 惹动你的怒气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, '这样,我们修造 城墙,城墙 就都 连络,高至 一半,因为百姓 专 心 做工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, ' 参巴拉、多比雅、阿拉伯人、亚扪人、亚实突人 听见 修造 耶路撒冷 城墙, 著手进行 堵塞 破裂的地方,就甚 发怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, '大家 同 谋 要来 攻击 耶路撒冷,使 城 内扰乱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, '然而,我们祷告我们的 神,又因他们的缘故,就派人 看守,昼 夜防备。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, '犹大人 说:「灰土 尚多,扛抬的人 力气 已经衰败,所以我们 不 能 建造 城墙。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, '我们的敌人 且说:「趁他们不 知 不 见, 我们进 入 他们中间,杀他们,使 工作 止住。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, ' 那 靠近 敌人居住 的犹大人 十 次 从各 处 来 见我们,说:「你们必要 回 到我们那里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, '所以我使 百姓 各按宗族 拿 刀、拿枪、拿弓 站 在城墙 后边 低洼 的空 处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, '我察看了,就起来 对 贵胄、 官长,和 其余 馀 的人 说:「不要 怕 他们!当记念 主 是大 而可畏的。你们要为 弟兄、儿 女、妻子、家产 争战 。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, ' 仇敌 听见 我们 知道他们的心意,见 神 也破坏 他们的计谋,就不来了。我们都 回 到 城墙那里,各 做 各的工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, ' 从 那 日起,我的仆人 一半 做 工,一半 拿 枪、拿盾牌、拿弓、穿(或译:拿)铠甲,官长 都站在犹大 众人 的后边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, '修造 城墙的,扛 抬 材料的,都一 手 做 工 一手 拿 兵器。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, '修造 的人 都腰 间 佩 刀 修造,吹 角 的人在我旁边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, '我对 贵胄、 官长,和 其余 馀 的人 说:「这工程 浩大,我们 在 城墙 上相 离 甚远; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, '你们听见 角 声 在 哪里,就聚集 到我们 那里去。我们的 神 必为我们 争战 。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, '于 是,我们 做 工,一半 拿 兵器,从 天亮 直到 星宿 出现的时候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, '那 时,我又 对百姓 说:「各人 和他的仆人 当在 耶路撒冷 住宿, 好在夜间 保守 我们,白昼 做工。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, '这样,我 和弟兄 仆人,并跟从我 的 护 兵 都不 脱 衣服, 出去打水 也带兵器。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, ' 百姓 和他们的妻 大大 呼号,埋怨 他们的弟兄 犹大人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, '有的 说:「我们 和儿 女 人口众多,要去得 粮食 度命」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, '有的 说:「我们 典了 田地、葡萄园、房屋,要得 粮食 充饥」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, '有的 说:「我们已经指著田地、葡萄园,借了 钱 给王 纳税。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, '我们的身体 与我们弟兄 的身体一样;我们的儿女 与他们的儿女一般。现在 我们 将要 使 儿 女 作人的仆婢,我们的女儿 已有 为婢的;我们 并无 力拯救,因为我们的田地、葡萄园 已经归了别人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, ' 我听见 他们呼号说 这些 话,便甚 发怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, '我 心里 筹划 㓰,就斥责 贵胄 和 官长 说:「你们 各人 向弟兄 取 利!」于 是我招聚 大 会 攻击他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, '我对他们 说:「我们 尽力 赎回 我们弟兄,就是卖 与外邦 的犹大人;你们 还要 卖 弟兄,使我们 赎回来吗?」他们就静默不语,无 话 可答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, '我又说:「你们 所 行 的 不 善!你们行事 不 当敬畏我们的 神吗?不然,难免我们的仇敌 外邦人 毁谤我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, '我 和我的弟兄 与仆人 也 将银钱 粮食 借 给百姓;我们大家都当 免去 利息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, '如今 我劝 你们 将他们的田地、葡萄园、橄榄园、房屋,并向他们 所 取 的银钱、粮食、新酒,和油,百分之一 的利息都归还 他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, '众人说:「我们必归还,不再 向他们 索要,必照 你 的话 行。」我就召了 祭司来,叫众人起誓,必照著所应许 的而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, '我也 抖著 胸前的衣襟,说:「凡 不 成就 这 应许的,愿  神 照样 抖 他 离开 家产 和他劳碌得来的,直到 抖 空了。」会众 都 说:「阿们!」又赞美 耶和华。百姓 就照著所应许 的去行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, ' 自从 我 奉派 作 犹大 地 的省长,就是从亚达薛西 王 二十 年 直到 三十 二 年,共十 二 年之久,我 与我弟兄 都没有 吃 省长 的俸禄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, '在我 以前 的 省长 加重 百姓的担子,每日索要 粮食 和酒,并 银子 四十 舍客勒,就是 他们的仆人 也辖制 百姓;但我 因 敬畏 神 不 这样 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, '并且 我恒心 修造 城墙,并没有 置买  田地;我的仆人 也都 聚集 在那里 做 工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, '除了 从 四围 外邦 中来的犹大人以外,有犹大平民 和官长 一百 五十 人 在 我席上吃饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, ' 每 日 预备 一只 公牛,六只 肥 羊,又预备 些飞禽;每 十 日一次,多 预备各样的 酒。虽然 如此,我并不 要 省长 的俸禄,因为 百姓 服 役 甚重。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, '我的 神啊,求你记念 我 为 这 百姓 所 行的 一切事,施恩与我。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, ' 参巴拉、多比雅、阿拉伯人 基善 和我们其余 馀的 仇敌 听见 我已经修完了 城墙,其中 没有 破裂 之处( 那 时 我还没有安 门扇)的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, '参巴拉 和基善 就打发人 来见我,说:「请你来,我们在阿挪 平原 的一个村庄 相 会。」他们 却想 害 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, '于 是我差遣 人 去见他们,说:「我 现在办理 大 工,不 能 下去。焉能 停 工 下去 见你们呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, '他们这 样 四 次 打发人 来见我,我都如 此 回答 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, '参巴拉 第五 次 打发 仆人 来见我,手里 拿著未封 的信, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, '信上 写著说:「外邦人 中有风声,迦施慕(就是基善,见二章十九节)也说,你 和犹大人 谋 反, 修造 城墙,你 要作 他们的 王; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, '你又 派 先知 在耶路撒冷 指著你 宣讲,说 在犹大 有王。现在 这 话 必传 与王知;所以请你来,与我们彼此 商议。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, '我就差遣人 去见他,说:「你 所 说 的这 事,一概没 有,是 你 心 里捏造的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, ' 他们都 要使我们 惧怕,意思说,他们的手 必软弱,以致 工作 不能 成就。 神啊,求你坚固 我的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, '我 到了 米希大别 的孙子、第来雅 的儿子 示玛雅 家里;那时,他 闭门不出。他说:「我们不如在 神的 殿 里 会面,将殿 门 关锁;因为 他们要来 杀你,就是夜 里来 杀你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, '我说:「像我这样的 人 岂要逃跑呢?像我这样的 人 岂 能进入 殿 里保全生命呢?我不 进去!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, '我看明 神 没有 差遣他,是 他自己说 这话 攻击我,是多比雅 和参巴拉 贿买 了他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, ' 贿买  他的缘故,是要叫 我惧怕,依从他 犯 罪, 他们 好 传扬恶 言 毁谤我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, '我的 神啊,多比雅、参巴拉、 女先知 挪亚底,和其余 馀的 先知 要 叫我 惧怕,求你记念 他们所行的这些 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, '以禄月 二十 五日,城墙 修完了,共修了五十 二 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, ' 我们一切 仇敌、 四围的 外邦人 听见了 便惧怕,愁眉 不展;因为见 这 工作 完成 是出乎我们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, ' 在那些 日子,犹大 的贵胄 屡次 寄 信 与 多比雅,多比雅 也来 信 与他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, ' 在犹大 有许多人 与多比雅 结 盟;因 他 是亚拉 的儿子,示迦尼 的女婿,并且他的儿子 约哈难 娶了 比利迦 儿子 米书兰 的女儿为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, ' 他们常在我面前 说 多比雅的善行,也 将我的话 传 与他。多比雅 又常寄 信来,要叫我惧怕。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, ' 城墙 修完,我安了 门扇,守门的、歌唱的,和利未人 都已派定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, '我就派 我的弟兄 哈拿尼 和 营楼 的宰官 哈拿尼雅 管理 耶路撒冷;因为 哈拿尼雅 是忠信的,又敬畏 神 过于 众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, '我吩咐他们 说:「等到 太阳 上升 才可 开  耶路撒冷 的城门;人 尚 看守 的时候就要关 门 上闩;也当派 耶路撒冷 的居民 各 按班次 看守 自己 房屋 对面之处。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, '城 是广 大,其中 的民 却稀少,房屋 还没有 建造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, '我的 神 感动 我心,招聚 贵胄、 官长,和 百姓,要照家谱计算。我找著 第一次 上来 之人的家谱, 其上 写著: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, ' 巴比伦 王 尼布甲尼撒 从前掳去 犹大省 的人,现在他们的子孙从被掳 到之地 回 耶路撒冷 和犹大,各 归本城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, '他们是同著 所罗巴伯、耶书亚、尼希米、亚撒利雅、拉米、拿哈玛尼、末底改、必珊、米斯毘列、比革瓦伊、尼宏、巴拿 回来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, '以色列 人 民 的数目记在下面:巴录 的子孙 二 千 一百 七十 二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, '示法提雅 的子孙 三 百 七十 二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, '亚拉 的子孙 六 百 五十 二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, '巴哈‧摩押 的后裔,就是耶书亚 和约押 的子孙 二千 八 百 一十 八名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, '以拦 的子孙 一千 二百 五十 四名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, '萨土 的子孙 八 百 四十 五名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, '萨改 的子孙 七 百 六十名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, '宾内 的子孙 六 百 四十 八名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, '比拜 的子孙 六 百 二十 八名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, '押甲 的子孙 二千 三 百 二十 二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, '亚多尼干 的子孙 六 百 六十 七名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, '比革瓦伊 的子孙 二千 零六十 七名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, '亚丁 的子孙 六 百 五十 五名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, '亚特 的后裔,就是希西家的 子孙九十 八名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, '哈顺 的子孙 三 百 二十 八名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, '比赛 的子孙 三 百 二十 四名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, '哈拉 的子孙 一百 一十 二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, '基遍 人 九十 五名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, '伯利恒 人 和尼陀法 人共一百 八十 八名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, '亚拿突 人 一百 二十 八名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, '伯‧亚斯玛弗 人 四十 二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, '基列‧耶琳 人、基非拉人、比录 人共七 百 四十 三名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, '拉玛 人 和迦巴 人共六 百 二十 一名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, '默玛 人 一百 二十 二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, '伯特利 人 和艾 人共一百 二十 三名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, '别的 尼波 人 五十 二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, '别的 以拦 子孙 一千 二百 五十 四名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, '哈琳 的子孙 三 百 二十名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, '耶利哥 人 三 百 四十 五名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, '罗德 人、哈第人、阿挪 人共七 百 二十 一名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, '西拿 人 三 千 九 百 三十名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, '祭司:耶书亚 家,耶大雅 的子孙 九 百 七十 三名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, '音麦 的子孙 一千 零五十 二名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, '巴施户珥 的子孙 一千 二百 四十 七名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, '哈琳 的子孙 一千 零一十 七名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, '利未人:何达威 的后裔,就是耶书亚 和甲篾 的子孙 七十 四名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, '歌唱的:亚萨 的子孙 一百 四十 八名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, '守门的:沙龙 的子孙、亚特 的子孙、达们 的子孙、亚谷 的子孙、哈底大 的子孙、朔拜 的子孙,共一百 三十 八名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, '尼提宁(就是殿役):西哈 的子孙、哈苏巴 的子孙、答巴俄 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, '基绿 的子孙、西亚 的子孙、巴顿 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, '利巴拿 的子孙、哈迦巴 的子孙、萨买  的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, '哈难 的子孙、吉德 的子孙、迦哈 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, '利亚雅 的子孙、利汛 的子孙、尼哥大 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, '迦散 的子孙、乌撒 的子孙、巴西亚 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, '比赛 的子孙、米乌宁 的子孙、尼普心 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, '巴卜 的子孙、哈古巴 的子孙、哈忽 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, '巴洗律 的子孙、米希大 的子孙、哈沙 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, '巴柯 的子孙、西西拉 的子孙、答玛 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, '尼细亚 的子孙、哈提法 的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, '所罗门 仆人 的后裔,就是琐太 的子孙、琐斐列 的子孙、比路大 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, '雅拉 的子孙、达昆 的子孙、吉德 的子孙、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, '示法提雅 的子孙、哈替 的子孙、玻黑列‧哈斯巴音 的子孙、亚们 的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, ' 尼提宁 和所罗门 仆人 的后裔 共三 百 九十 二名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, '从特米拉、特哈萨、基绿、亚顿、音麦 上来的,不 能 指明 他们的宗 族 谱系 是 以色列人 不是; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, '他们是 第莱雅 的子孙、多比雅 的子孙、尼哥大 的子孙,共六 百 四十 二名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, '祭司中,哈巴雅 的子孙、哈哥斯 的子孙、巴西莱 的子孙;因为他们的先祖 娶了 基列人 巴西莱 的女儿 为妻,所以起 名 叫巴西莱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, '这 三家的人在族谱 之中寻查 自己的谱系,却寻 不著,因此算为不洁,不准 供祭司的职任。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, '省长 对他们 说:「 不可 吃 至圣的 物,直到 有用乌陵 和土明 决疑的祭司 兴起来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, ' 会众 共有 四 万 二千 三 百 六十名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, '此外,还有 他们的仆 婢 七 千 三 百 三十 七名,又 有歌唱的男 女 二百 四十 五名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, '他们有马 七 百 三十 六匹,骡子 二百 四十 五匹, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, '骆驼 四 百 三十 五只,驴 六 千 七 百 二十匹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, '有些 族 长 为工程 捐助。省长 捐 入库 中的金子 一千 达利克,碗 五十个,祭司 的礼服 五 百 三十件。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, '又有族 长 捐入 工程 库 的金子 二万 达利克,银子 二千 二百 弥拿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, '其余 馀 百姓 所 捐的 金子 二万 达利克,银子 二千 弥拿,祭司 的礼服 六十 七件。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, '于 是祭司、利未人、守门的、歌唱的、民 中的一些人、尼提宁,并以色列 众人,各住 在自己的城里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, '到了 七 月,以色列 人 住在自己的城里。那时, 他们 如同一 人 聚集 在 水 门 前 的 宽阔处,请 文士 以斯拉 将 耶和华 藉 借摩西 传 给 以色列人 的 律法 书 带来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, '七 月 初一 日,祭司 以斯拉 将 律法 书带到 听了 能明白 的男 女 会众 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, '在水 门 前 的 宽阔处,从 清早 到 晌午,在 众男 女、一切听了能明白 的人面前读 这律法 书。众 民 侧 耳而听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, '文士 以斯拉 站 在 为这事 特备 的 木 台上。玛他提雅、示玛、亚奈雅、乌利亚、希勒家,和玛西雅 站 在 他的右 边;毘大雅、米沙利、玛基雅、哈顺、哈拔大拿、撒迦利亚,和米书兰 站在 他的左边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, ' 以斯拉 站在 众 民 以上,在众 民 眼前 展开  这书。他一展开 ,众 民 就都站起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, '以斯拉 称颂 耶和华 至大的 神;众 民 都举 手 应声说:「阿们!阿们!」就低头,面 伏于 地,敬拜 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, '耶书亚、巴尼、示利比、雅悯、亚谷、沙比太、荷第雅、玛西雅、基利他、亚撒利雅、约撒拔、哈难、毘莱雅,和利未人 使 百姓 明白 律法;百姓 都站在 自己的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, '他们清清楚楚地 念 神 的律法 书,讲明 意思,使百姓明白 所念的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, ' 省长 尼希米 和作祭司 的文士 以斯拉,并教训 百姓 的利未人,对众 民 说:「今日 是 耶和华─你们 神 的圣日,不要 悲哀 哭泣。」这是因为 众 民 听见 律法 书上的话 都哭了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, '又对他们 说:「你们去 吃 肥美的,喝 甘甜的,有不能 预备 的就分 给他,因为 今日是我们主的 圣 日。你们不要 忧愁,因 靠耶和华 而得的喜乐 是 你们的力量。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, '于 是利未人 使众 民 静默,说:「 今日是圣 日;不要作声,也不要 忧愁。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, '众 民 都去 吃 喝,也分给人, 大大 快乐,因为 他们明白 所 教训 他们 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, '次 日,众 民 的族 长、祭司,和利未人 都聚集 到 文士 以斯拉那里,要留心 听 律法 上的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, '他们见 律法 上写著, 耶和华 藉 借 摩西 吩咐 以色列 人 要在七 月 节 住 棚, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, '并 要在各 城 和耶路撒冷 宣传 报 告 说:「你们当上 山,将橄榄 树、野橄榄 树、番石榴 树、棕 树,和各样茂密 树 的枝子 取来,照著所写的 搭 棚。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, '于 是百姓 出去,取了树枝来,各人 在 自己的房顶上,或院内,或 神 殿 的院内,或水 门 的宽阔处,或以法莲 门 的宽阔处 搭 棚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, '从 掳到之地 归回 的全 会众 就搭 棚,住 在棚里。 从嫩 的儿子 约书亚 的时候 直到 这 日,以色列 人 没有 这样 行。 于 是众人大 大 喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, '从 头一 天 直到 末一 天,以斯拉每 日 念 神 的律法 书。众人守 节 七 日,第八 日 照例 有严肃会。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, '这 月 二十 四 日,以色列 人 聚集 禁食,身穿麻衣,头蒙 灰尘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, '以色列人(人:原文是种类)就与一切 外邦 人 离绝,站著 承认 自己的罪恶 和列祖 的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, '那日 的四分之一 站 在 自己的地方 念 耶和华─他们 神 的律法 书,又四分之一 认罪,敬拜 耶和华─他们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, '耶书亚、巴尼、甲篾、示巴尼、布尼、示利比、巴尼、基拿尼 站 在 利未人 的台上,大 声 哀求 耶和华─他们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, '利未人 耶书亚、甲篾、巴尼、哈沙尼、示利比、荷第雅、示巴尼、毘他希雅 说:「你们要站起来 称颂 耶和华─你们的 神, 永世 无尽。耶和华啊,你荣耀 之名 是应当称颂的!超乎 一切 称颂 和赞美。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, '「你,惟独你 是 耶和华!你 造了 天 和天 上的天,并天上的万 象,地 和地上 的 万物,海 和海中 所有的; 这一切 都是你 所保存的。天 军 也都敬拜 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, '你 是 耶和华 神,曾 拣选 亚伯兰,领他出 迦勒底 的吾珥,给他改 名 叫亚伯拉罕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, '你见 他在你面前 心 里诚实,就与他 立 约,应许把 迦南人、赫人、亚摩利人、比利洗人、耶布斯人、革迦撒人 之地 赐 给他的后裔,且应验了 你的话,因为 你 是公义的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, '「你曾看见 我们列祖 在埃及 所受的困苦,垂听 他们在 红 海 边的哀求, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, '就施行 神迹 奇事 在法老 和他一切 臣仆,并他国 中的众 民身上。你也得了 名声,正如今 日一样,因为 你知道 他们向我们列祖 行事狂傲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, '你又在我们列祖面前 把海 分开 ,使他们在海 中 行走 干地,将 追赶他们的人 抛 在深海,如 石头 抛在大 水中; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, '并且白昼 用云 柱 引导他们,黑夜 用火 柱 照亮 他们 当行 的 路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, '你也降临 在 西奈 山,从天上 与他们 说话,赐 给他们 正直的 典章、真实的 律法、美好的 条例 与诫命, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, '又使他们 知道 你的安息 圣日,并藉 借 你仆人 摩西 传 给他们 诫命、条例、律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, '从天上 赐下 粮食 充他们 的饥,从磐石 使水 流出 解他们 的渴,又吩咐 他们 进去 得 你起 誓 应许赐 给他们 的 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, '但 我们的列祖 行事狂傲,硬著 颈项 不 听 从 你的诫命; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, '不肯 顺从,也不 记念 你在他们中间 所 行 的奇事,竟硬著 颈项,居心背逆,自立 首领,要回 他们为奴之地。但你是 乐意饶恕人,有恩典,有怜悯,不轻易 发怒,有丰盛 慈爱的 神,并不 丢弃他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, '他们虽然 铸了 一只牛犊,彼此说『这是 领你 出埃及 的 神』,因而大大 惹动 你的怒气; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, '你 还是大施 怜悯,在旷野 不 丢弃他们。白昼, 云 柱 不 离开  他们,仍引导他们 行路;黑夜, 火 柱也不离开 他们,仍照亮 他们 当行 的 路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, '你也赐下 你良善的 灵 教训他们;未尝 不赐 吗哪 使他们糊口,并赐 水 解他们 的渴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, '在旷野 四十 年,你养育他们,他们就一无 所缺:衣服 没有 穿破,脚 也没有 肿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, '并且你将列 国 之地照 分 赐 给他们,他们就得了 西宏 之地、 希实本 王 之地,和 巴珊 王 噩 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, '你也使他们的子孙 多 如天上 的星,带他们 到 你所 应许 他们列祖 进入 得为业 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, '这样, 他们进去 得了 那地,你在他们面前 制伏 那地 的居民,就是迦南人;将迦南人和 其君王,并 那地 的居民,都交 在他们手里,让他们任意 而待。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, '他们得了 坚固的 城邑、肥美的 地土、 充满 各样 美物 的房屋、凿成的 水井、葡萄园、橄榄园,并许多 果木 树。他们就吃 而得饱,身体肥胖,因你的大 恩,心中快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, '「然而,他们不顺从,竟背叛 你,将 你的律法 丢 在背 后,杀害 那 劝 他们 归 向你 的众先知,大大 惹动 你的怒气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, '所以你将他们交 在敌人 的手中,磨难 他们。他们遭难 的时候 哀求 你,你 就从天上 垂听,照你的大 怜悯 赐 给他们 拯救者,救他们 脱离敌人 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, '但他们 得平安之后,又 在你面前 行 恶,所以你丢弃他们 在仇敌 的手中,使仇敌辖制 他们。然而他们转回 哀求你,你 仍从天上 垂听,屡 次 照你的怜悯 拯救他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, '又警戒 他们,要使他们归 服 你的律法。他们 却行事狂傲,不 听从 你的诫命,干犯 你的典章(人 若 遵行 就必因此 活著),扭 转 肩头,硬著 颈项,不肯 听从。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, '但你多 年 宽容 他们,又用你的灵 藉 借 众先知 劝戒 他们,他们仍不 听从,所以你将他们交 在列国 之民 的手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, '然而你大 发怜悯,不 全然 灭绝他们,也不 丢弃他们;因为 你 是有恩典、有怜悯的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, '「我们的 神啊,你是至大、至能、至可畏、守 约 施慈爱的 神。我们的君王、首领、祭司、先知、列祖,和你的众 民,从 亚述 列王 的时候直到 今 日 所 遭遇的 苦难,现在 求你 不要 以为小。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, '在 一切 临 到我们的事上,你 却是公义的;因 你所行 的是诚实,我们 所做的是邪恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, ' 我们的君王、首领、祭司、列祖 都不 遵守 你的律法,不 听从 你的诫命 和你警戒 他们 的 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, '他们 在本国里 沾你大 恩的时候,在你所 赐 给他们 这广大 肥美 之地 上不 事奉你,也不 转离 他们的恶 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, ' 我们 现今 作了奴仆;至于 你所 赐 给我们列祖 享受 其上的土产,并 美物 之地,看哪,我们 在这地上 作了奴仆! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, '这地许多 出产 归了列王,就是 你因我们的罪 所派 辖制我们的。他们任意 辖制 我们的身体 和牲畜,我们 遭了大 难。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, '因这 一切的事,我们 立 确实的约,写在册上。我们的首领、利未人,和祭司都 签了名。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, ' 签名的是:哈迦利亚 的儿子─省长 尼希米,和西底家; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, '祭司:西莱雅、亚撒利雅、耶利米、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, '巴施户珥、亚玛利雅、玛基雅、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, '哈突、示巴尼、玛鹿、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, '哈琳、米利末、俄巴底亚、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, '但以理、近顿、巴录、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, '米书兰、亚比雅、米雅民、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, '玛西亚、璧该、示玛雅; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, '又有利未人,就是亚散尼 的儿子 耶书亚、希拿达 的子孙 宾内、甲篾; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, '还有他们的弟兄 示巴尼、荷第雅、基利他、毘莱雅、哈难、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, '米迦、利合、哈沙比雅、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, '撒刻、示利比、示巴尼、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, '荷第雅、巴尼、比尼努; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, '又有民 的首领,就是巴录、巴哈‧摩押、以拦、萨土、巴尼、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, '布尼、押甲、比拜、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, '亚多尼雅、比革瓦伊、亚丁、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, '亚特、希西家、押朔、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, '荷第雅、哈顺、比赛、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, '哈拉、亚拿突、尼拜、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, '抹比押、米书兰、希悉、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, '米示萨别、撒督、押杜亚、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, '毘拉提、哈难、亚奈雅、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, '何细亚、哈拿尼雅、哈述、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, '哈罗黑、毘利哈、朔百、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, '利宏、哈沙拿、玛西雅、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, '亚希雅、哈难、亚难、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, '玛鹿、哈琳、巴拿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, '其余 馀 的民、祭司、利未人、守门的、歌唱的、尼提宁,和一切 离绝 邻邦 居民 归服 神 律法的,并他们的妻子、儿 女,凡 有知识 能明白的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, '都随 从 他们贵胄 的弟兄,发 咒 起誓,必遵行 神 藉 借 他 仆人 摩西 所 传 的律法,谨守 遵行 耶和华─我们主 的一切 诫命、典章、律例; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, '并 不 将我们的女儿 嫁给 这地 的居民,也不 为我们的儿子 娶 他们的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, '这地 的居民 若在安息 日,或什么圣 日,带了 货物或 粮食 来卖给我们,我们必不 买 。每逢 第七 年 必不耕种,凡 欠我们债的必不追讨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, '我们又为自己 定 例,每年 各人 捐 银一舍客勒 三分之一,为我们 神 殿 的使用, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, '就是为陈设 饼、常献的 素祭,和 燔祭,安息日、月朔、节期 所献的与圣物,并 以色列人 的赎罪祭,以及我们 神 殿 里一切 的费用。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, '我们的祭司、利未人,和百姓 都掣 签,看每 年 是哪一族 按定 期将献祭的 柴 奉到我们 神 的殿里,照著律法 上所写的,烧 在 耶和华─我们 神 的坛上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, '又定每 年 将 我们地上 初熟的 土产和各样 树 上初熟的 果子 都奉到 耶和华 的殿里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, '又照律法 上所写的,将 我们头胎的 儿子 和 首生的 牛 羊 都奉到我们 神 的殿,交给我们 神 殿 里供职 的祭司; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, '并将 初熟 之麦子所磨的面 麺 和举祭、各样 树 上初熟的果子、新酒 与油 奉 给祭司,收在我们 神 殿 的库房里,把我们地上 所产的十分之一 奉给利未人,因利未人 在我们一切 城邑 的土产 中当 取十分之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, '利未人 取十分之一的时候,亚伦 的子孙中,当有 一个祭司 与 利未人同在。利未人 也当从十分之一中 取 十分之一,奉到我们 神 殿的 屋子里,收在库 房中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, ' 以色列 人 和利未 人 要将 五谷、新酒,和油 为举祭,奉 到 收存圣所 器皿 的屋子里,就是 供职 的祭司、守门的、歌唱的所住的屋子。这样,我们就不 离弃我们 神 的殿。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, '百姓 的首领 住 在耶路撒冷。其余 馀的 百姓 掣 签,每十 人中 使一 人来 住 在圣 城 耶路撒冷,那九 人住在别的城邑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, '凡 甘心乐意 住 在耶路撒冷的,百姓 都为他们祝福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, '以色列人、祭司、利未人、尼提宁,和所罗门 仆人 的后裔 都住在 犹大 城邑,各 在自己的地业中。本省 的首领 住 在耶路撒冷 的 记在下面: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, '其中 有些犹大 人 和便雅悯 人。犹大 人 中有法勒斯 的子孙、乌西雅 的儿子 亚他雅。乌西雅是撒迦利雅 的儿子;撒迦利雅是亚玛利雅 的儿子;亚玛利雅是示法提雅 的儿子;示法提雅是玛勒列 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, '又有巴录 的儿子 玛西雅。巴录是谷何西 的儿子;谷何西是哈赛雅 的儿子;哈赛雅是亚大雅 的儿子;亚大雅是约雅立 的儿子;约雅立是撒迦利雅 的儿子;撒迦利雅是示罗尼 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, '住 在耶路撒冷、法勒斯的 子孙 共四 百 六十 八名,都是勇 士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, '便雅悯 人 中有 米书兰 的儿子 撒路。米书兰是约叶 的儿子;约叶是毘大雅 的儿子;毘大雅是哥赖雅 的儿子;哥赖雅是玛西雅 的儿子;玛西雅是以铁 的儿子;以铁是耶筛亚 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, '其次 有迦拜、撒来的子孙,共九 百 二十 八名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, '细基利 的儿子 约珥 是他们的长官。哈西努亚 的儿子 犹大是 耶路撒冷 的副官。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, '祭司 中 有雅斤,又有约雅立 的儿子 耶大雅; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, '还有管理 神 殿 的西莱雅。西莱雅是希勒家 的儿子;希勒家是米书兰 的儿子;米书兰是撒督 的儿子;撒督是米拉约 的儿子;米拉约是亚希突 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, '还有他们的弟兄 在殿 里供 职的,共八 百 二十 二名;又有耶罗罕 的儿子 亚大雅。耶罗罕是毘拉利 的儿子;毘拉利是暗洗 的儿子;暗洗是撒迦利亚 的儿子;撒迦利亚是巴施户珥 的儿子;巴施户珥是玛基雅 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, '还有他的弟兄 作族 长的,二 百 四十 二名;又有亚萨列 的儿子 亚玛帅。亚萨列是亚哈赛 的儿子;亚哈赛是米实利末 的儿子;米实利末是音麦 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, '还有他们弟兄、大能的 勇士 共一百 二十 八名。哈基多琳 的儿子 撒巴第业 是他们的 长官。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, '利未人 中 有哈述 的儿子 示玛雅。哈述是押利甘 的儿子;押利甘是哈沙比雅 的儿子;哈沙比雅是布尼 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, '又有利未人 的族长 沙比太 和约撒拔 管理 神 殿 的外 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, '祈祷的时候,为称谢 领首 的是米迦 的儿子 玛他尼。米迦是撒底 的儿子;撒底是亚萨 的儿子;又有玛他尼弟兄 中的八布迦 为副。还有沙母亚 的儿子 押大。沙母亚是加拉 的儿子;加拉是耶杜顿 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, '在圣 城的 利未人 共二百 八十 四名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, '守门的 是亚谷 和达们,并守 门 的弟兄,共一百 七十 二名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, '其余 馀的 以色列人、祭司、利未人 都住在犹大 的一切 城邑,各 在自己的地业中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, '尼提宁 却住 在俄斐勒;西哈 和基斯帕 管理 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, '在耶路撒冷、利未人 的长官,管理 神 殿 事务 的是歌唱者 亚萨 的子孙、巴尼 的儿子 乌西。巴尼是哈沙比雅 的儿子;哈沙比雅是玛他尼 的儿子;玛他尼是米迦 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, ' 王 为 歌唱的 出命令,每 日 供给他们 必有一定 之粮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, '犹大 儿子 谢拉 的子孙、米示萨别 的儿子 毘他希雅 辅助 王 办理犹大民的 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, '至于  村庄 和属村庄的田地,有犹大 人 住在基列‧亚巴和属基列‧亚巴的乡村;底本 和属底本的乡村;叶甲薛 和属叶甲薛的村庄; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, '耶书亚、摩拉大、伯‧帕列、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, '哈萨‧书亚、别是巴,和属别是巴的乡村; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, '洗革拉、米哥拿,和属米哥拿的乡村; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, '音‧临门、琐拉、耶末、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, '撒挪亚、亚杜兰,和属这两处的村庄;拉吉 和属拉吉的田地;亚西加 和属亚西加的乡村。他们所住 的地方是从别是巴 直到 欣嫩 谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, '便雅悯 人 从迦巴起,住在密抹、亚雅、伯特利 和属伯特利的乡村。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, '亚拿突、挪伯、亚难雅、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, '夏琐、拉玛、基他音、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, '哈叠、洗编、尼八拉、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, '罗德、阿挪、匠人 之谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, '利未人 中 有几班 曾住在犹大地 归于 便雅悯的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, '同著 撒拉铁 的儿子 所罗巴伯 和耶书亚 回来 的祭司 与利未人 记在下面:祭司是西莱雅、耶利米、以斯拉、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, '亚玛利雅、玛鹿、哈突、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, '示迦尼、利宏、米利末、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, '易多、近顿、亚比雅、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, '米雅民、玛底雅、璧迦、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, '示玛雅、约雅立、耶大雅、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, '撒路、亚木、希勒家、耶大雅。这些人 在耶书亚 的时候 作祭司 和他们弟兄 的首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, '利未人 是耶书亚、宾内、甲篾、示利比、犹大、玛他尼。这玛他尼 和他的弟兄 管理 称谢的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, '他们的弟兄 八布迦 和乌尼 照自己的班次 与他们相对。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, '耶书亚 生 约雅金;约雅金 生 以利亚实;以利亚实 生 耶何耶大; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, '耶何耶大 生 约拿单;约拿单 生 押杜亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, '在约雅金 的时候,祭司 作 族 长 的西莱雅族(或译:班;本段同)有米拉雅;耶利米 族有哈拿尼雅; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, '以斯拉 族有米书兰;亚玛利雅 族有约哈难; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, '米利古 族有约拿单;示巴尼 族有约瑟; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, '哈琳 族有押拿;米拉约 族有希勒恺; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, '易多 族有撒迦利亚;近顿 族有米书兰; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, '亚比雅 族有细基利;米拿民族某;摩亚底 族有毘勒太; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, '璧迦 族有沙母亚;示玛雅 族有约拿单; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, '约雅立 族有玛特乃;耶大雅 族有乌西; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, '撒来 族有加莱;亚木 族有希伯; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, '希勒 家族有哈沙比雅;耶大雅 族有拿坦业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, '至于 利未人,当以利亚实、耶何耶大、约哈难、押杜亚 的时候,他们的族 长 记在册上。波斯 王大流士 在 位的时候,作族长的祭司也记在册上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, '利未 人 作族 长 的记 在 历史上,直到 以利亚实 的儿子 约哈难 的时候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, '利未人 的族长 是哈沙比雅、示利比、甲篾 的儿子 耶书亚,与他们弟兄 的班次相对,照著神 人 大卫 的命令 一班 一班 地赞美 称谢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, '玛他尼、八布迦、俄巴底亚、米书兰、达们、亚谷 是守门的,就是在库房 那里守 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, '这都是在 约撒达 的孙子、耶书亚 的儿子 约雅金 和省长 尼希米,并祭司 文士 以斯拉 的时候,有职任的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, '耶路撒冷 城墙 告成的时候,众民就把 各 处的 利未人 招 到 耶路撒冷,要称谢、歌唱、敲钹、鼓瑟、弹琴,欢欢喜喜地 行 告成之礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, '歌唱 的人 从 耶路撒冷 的周围 和 尼陀法 的村庄与伯‧吉甲,又从迦巴 和押玛弗 的田地 聚集,因为 歌唱的人 在耶路撒冷 四围 为自己 立了 村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, '祭司 和利未人 就洁净自己,也洁净 百姓 和 城门,并 城墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, '我带 犹大 的首领 上 城,使 称谢 的人分为两 大队,排列而行:第一队在城 上 往右边 向粪厂 门 行走, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, ' 在他们后头 的有何沙雅 与犹大 首领 的一半, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, '又有亚撒利雅、以斯拉、米书兰、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, '犹大、便雅悯、示玛雅、耶利米。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, '还有些吹号 之祭司 的子孙,约拿单 的儿子 撒迦利亚。约拿单是示玛雅 的儿子;示玛雅是玛他尼 的儿子;玛他尼是米该亚 的儿子;米该亚是撒刻 的儿子;撒刻是亚萨 的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, '又有撒迦利亚的弟兄 示玛雅、亚撒利、米拉莱、基拉莱、玛艾、拿坦业、犹大、哈拿尼,都拿著神 人 大卫 的乐 器,文士 以斯拉 引领他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, '他们经过 泉 门 往前,从 大卫 城 的台 阶 随地势而上,在大卫 宫殿 以上,直行到 朝东 的水 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, '第二 队称谢 的人要与那一队相迎 而行。我 和民 的一半 跟随他们,在 城墙 上过了 炉 楼,直到 宽 墙; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, '又过了 以法莲 门、 古 门、 鱼 门、哈楠业 楼、哈米亚 楼,直到 羊 门,就在护卫 门 站住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, '于 是,这两 队称谢 的人连我 和 官长 的一半,站在 神 的殿里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, '还有祭司 以利亚金、玛西雅、米拿民、米该亚、以利约乃、撒迦利亚、哈楠尼亚 吹号; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, '又有玛西雅、示玛雅、以利亚撒、乌西、约哈难、玛基雅、以拦,和以谢奏乐。歌唱 的就大声歌唱,伊斯拉希雅 管理他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, '那 日,众人献 大 祭 而欢乐;因为 神 使他们大大 欢乐,连妇女 带孩童 也 都欢乐,甚至耶路撒冷 中的欢声 听到 远处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, '当 日,派 人 管理 库 房,将举祭、初熟之物 和所取的十分之一,就是按各城 田地,照律法 所定归给祭司 和利未人 的分,都收 在里头。 犹大人 因 祭司 和 利未人 供职,就欢乐了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, '祭司利未人遵守 神 所吩咐的,并守洁净 的礼。歌唱的、守门的,照著大卫 和他儿子 所罗门 的命令也如此行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, ' 古时,在大卫 和亚萨 的日子,有歌唱 的伶长,并有赞美 称谢 神 的诗歌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, '当 所罗巴伯 和尼希米 的时候,以色列 众人 将歌唱的、守门的,每 日 所当得 的分 供给他们,又给利未人 当得的分;利未人 又给亚伦 的子孙 当得的分。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, '当 日,人念 摩西 的律法书 给百姓 听,遇见 书上 写著 说,亚扪人 和摩押人 永 不可 入 神 的会; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, '因为 他们没有 拿食物 和水 来迎接 以色列 人,且雇了 巴兰 咒诅他们,但我们的 神 使那咒诅 变 为祝福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, ' 以色列民 听见 这律法,就与一切 闲 杂人 绝交。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, '先 是 蒙派管理我们 神 殿 中库房 的祭司 以利亚实 与多比雅 结亲, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, '便为他 预备 一间大 屋子,就 是 从前 收存 素祭、乳香、器皿,和照命令 供给利未人、歌唱的、守门的 五谷、新酒,和油 的十分之一,并归祭司 举祭的屋子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, '那 时 我不 在 耶路撒冷;因为 巴比伦 王 亚达薛西 三十 二 年,我回到 王那里。过了 多日,我向 王 告假。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, '我来到 耶路撒冷,就知道 以利亚实 为多比雅在 神 殿 的院 内预备 屋子 的那件 恶事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, '我 甚 恼怒,就把 多比雅 的一切 家 具 从 屋 里都抛 出去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, '吩咐 人洁净 这屋子,遂将 神 殿 的器皿 和 素祭、乳香 又搬进去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, '我见 利未人 所当得的分 无人 供给他们,甚至供 职 的利未人 与歌唱的 俱各 奔回 自己的田地去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, '我就斥责 官长 说:「为何 离弃 神 的殿呢?」我便招聚利未人,使他们 照旧供 职。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, '犹大 众人 就把五谷、新酒,和油 的十分之一 送 入库房。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, '我派祭司 示利米雅、文士 撒督,和 利未人 毘大雅 作库官 管理 库房;副官 是哈难。哈难是撒刻 的儿子;撒刻是玛他尼 的儿子。 这些人都是 忠信的,他们的职分 是将所供给的分 给他们的弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, '我的 神啊,求你因 这事 记念 我,不要 涂抹我为 神 的殿 与其中的礼节 所 行 的善。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, '那些 日子,我在犹大 见 有人在安息日醡酒(原文是踹 酒醡),搬运 禾捆 驮 在 驴上,又 把酒、葡萄、无花果,和各样的 担子 在安息 日 担 入耶路撒冷,我就在他们卖 食物 的那日 警戒他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, '又有泰尔人 住 在耶路撒冷;他们把鱼 和各样 货物 运进来,在安息日 卖 给犹大 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, '我就斥责 犹大 的贵胄 说:「你们 怎么 行 这 恶 事 犯了 安息 日呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, '从前你们列祖 岂不是 这样 行,以致我们 神 使 一切 灾祸 临 到我们 和 这 城吗?现在你们 还犯 安息日,使忿怒 越发 临 到 以色列!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, '在安息日 的前一日, 耶路撒冷 城门 有黑影的时候,我就吩咐 人将门 关锁, 不过 安息日 不准 开 放。我又派 我几个仆人 管理 城门,免得 有人在安息 日 担什么担子 进城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, '于 是商人 和贩卖 各样 货物的,一 两次 住宿 在耶路撒冷 城外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, '我就警戒 他们 说:「你们 为何 在城 外 住宿呢?若 再这样,我必下 手 拿办你们。」从 此以后,他们在安息日 不 再来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, '我吩咐 利未人 洁净自己,来 守 城门,使 安息 日 为圣。我的 神啊, 求你因这事 记念 我,照你的大 慈爱 怜恤 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, '那些 日子,我也 见 犹大人 娶 了亚实突、亚扪、摩押 的女子为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, '他们的儿女 说话,一半 是亚实突的话,不 会 说 犹大的话,所说的是照著各 族 的方言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, '我就斥责 他们,咒诅他们,打 了他们几个 人,拔下他们的头发,叫他们指著 神 起誓,必不 将 自己的女儿 嫁给外邦人的儿子,也不 为自己 和儿子 娶 他们的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, '我又说:「以色列 王 所罗门 不是 在 这样的事 上犯罪吗?在多 国 中并没 有 一王 像他,且蒙他 神 所爱, 神 立他 作 以色列 全 国的王;然而连他 也 被外邦 女子 引诱犯罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, '如此,我岂听 你们 行 这 大 恶,娶 外邦 女子 干犯我们的 神呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, '大 祭司 以利亚实 的孙子、耶何耶大 的一个儿子 是和伦人 参巴拉 的女婿,我就从我这里 把他赶出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, '我的 神啊,求你记念 他们的罪;因为 他们玷污 了祭司的职任,违背你与祭司 利未人 所立的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, '这样,我洁净他们,使他们离绝一切 外邦人,派定 祭司 和利未人 的班次,使他们各 尽其职。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, '我又派百姓按定 期 献 柴 和初熟的土产。我的 神啊,求你记念 我,施恩与我。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, ' 亚哈随鲁 作王,从印度 直到 古实,统管一百 二十 七 省。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, ' 亚哈随鲁 王 在书珊 城的 宫 登基; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, '在位 第三 年,为他一切 首领 臣仆 设摆 筵席,有波斯 和米底亚 的权贵,就是各省 的贵胄 与首领,在他面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, '他把 他荣耀 之国 的丰富 和 他美好 威严 的尊贵 给他们看了 许多 日,就是一百 八十 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, '这 日子 满了, 又为所有 住 书珊 城 的大 小 人民 在御 园 的院子 里设摆 筵席 七 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, '有白色、绿色、蓝色的帐子,用细麻 绳、紫色 绳从 银 环 内系 在白玉石 柱上;有金 银 的床榻 摆在 红、白、黄、黑 玉石 的铺石地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, '用金 器皿 赐酒,器皿 各 有不同。御 酒 甚多,足显王 的厚意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, '喝酒 有例,不准 勉强人,因 王 吩咐 宫里 的一切 臣宰,让 人各 随己 意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, '王后 瓦实提 在亚哈随鲁 王 的 宫 内 也 为妇女 设摆 筵席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, '第七 日,亚哈随鲁 王 饮酒,心 中快乐,就吩咐 在 他 面前 侍立 的七个 太监 米户幔、比斯他、哈波拿、比革他、亚拔他、西达、甲迦, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, '请 王后 瓦实提 头戴王后 的冠冕 到 王 面前,使各等臣 民 看 她的美貌,因为 她 容貌 甚美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, '王后 瓦实提 却不肯 遵太监 所 传的 王 命 而来,所以王 甚 发怒, 心 如火烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, '那时,在 王 左右 常见 王 面、国 中坐 高位的,有波斯 和米底亚 的七 个大臣,就是甲示拿、示达、押玛他、他施斯、米力、玛西拿、米母干,都是达 时务 的明哲人。按 王 的常规,办事必先询问 知 例 明法的人。王问他们说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, '「王后 瓦实提 不 遵 太监 所传 的 王 命,照例 应当怎样 办理呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, '米母干 在王 和众首领 面前 回答说:「王后 瓦实提这事,不 但 得罪 王,并且 有害于  王 各 省的 臣 民; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, '因为 王后 这事 必传 到 众 妇人的耳中,说:『亚哈随鲁 王 吩咐 王后 瓦实提 到 王面前,她却不 来』,她们 就藐视 自己的丈夫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, '今 日 波斯 和米底亚 的众夫人 听见 王后 这事,必向 王 的大臣照样行;从此必大开  藐视 和忿怒之端。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, ' 王 若 以为美,就 降 旨 写 在波斯 和米底亚 人的例中,永不 更改, 不准 瓦实提 再到 王 面前, 将她王后的位分 赐 给比她还 好 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, ' 所 降 的旨意 传遍 通 国(国度 本来 广大),所有的 妇人,无论丈夫贵 贱 都必尊敬 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, '王 和众首领 都以米母干 的话 为 美,王 就照这话 去行, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, ' 发 诏书,用 各 省 的文字、 各 族 的方言 通知 各 省,使为 丈夫 的在家 中作 主,各说 本地的 方言。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, '这 事 以后,亚哈随鲁 王 的忿怒 止息,就想念 瓦实提 和 她所 行的,并 怎样 降旨 办她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, '于 是王 的侍臣 对王说:「不如为王 寻找 美貌的 处女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, '王 可以派 官 在国中 的各 省 招聚 美 貌 的 处女 到 书珊城(或译:宫)的 女 院,交给 掌管 女子 的太监 希该,给 她们当用的香品。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, '王 所 喜爱的 女子 可以立为王后,代替 瓦实提。」王 以这事 为美,就如此 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, '书珊 城 有 一个 犹大人,名 叫末底改,是便雅悯人 基士 的曾孙,示每 的孙子,睚珥 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, '从前巴比伦 王 尼布甲尼撒将 犹大 王 耶哥尼雅(又名约雅斤)和 百姓 从耶路撒冷 掳去,末底改 也在其内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, ' 末底改抚养 他叔叔 的女儿 哈大沙(后名 以斯帖),因为 她 没有 父 母。这女子 又容貌俊美;她父 母 死了,末底改 就收她 为自己 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, ' 王 的谕 旨 传出,就招聚 许多 女子 到 书珊 城,交给 掌管 女子 的希该;以斯帖 也送 入 王 宫,交付 希该。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, '希该 喜悦 以斯帖,就恩 待 她,急忙 给 她 需用的香品 和 她所当得的分,又派 所当得的七 个宫女 服事她,使她 和 她的宫女 搬入女 院 上好的房屋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, '以斯帖 未 曾将 籍贯 宗族 告诉人,因为 末底改 嘱咐 她 不可 叫人知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, '末底改 天 天 在女 院 前 边 行走,要知道 以斯帖 平安不平安,并后事 如何。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, '众女子 照例 先 洁净 身体 十 二 个月:六个 月 用没药 油,六个 月 用香料 和洁身之物。 满了 日期,然后 挨 次 进去 见 亚哈随鲁 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, '女子 进去 见 王 是这样:从女 院 到 王 宫的时候, 凡 她所 要的 都必给 她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, '晚上 进去,次日 回 到 女子 第二 院,交给 掌管 妃嫔 的太监 沙甲;除非 王 喜爱 她,再提名 召她,就不 再 进去 见 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, '末底改 叔叔 亚比孩 的女儿,就是 末底改收为 自己 女儿 的以斯帖,按 次序 当进去 见 王的时候,除了 掌管 女子 的太监 希该 所 派定给她的,她别 无 所求。凡 看见 以斯帖的 都喜悦她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, '亚哈随鲁 王 第七 年 十 月,就是 提别 月,以斯帖 被引 入 宫 见 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, '王 爱 以斯帖 过于 爱众 女,她在王眼前 蒙 宠 爱 比众 处女更甚。王就把王后 的冠冕 戴 在她头上,立她为王后,代替 瓦实提。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, '王 因 以斯帖 的缘故 给众 首领 和臣仆 设摆 大 筵席,又 豁免 各省的租税,并照王 的厚意 大颁 赏赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, '第二次 招聚 处女的时候,末底改 坐 在朝 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, '以斯帖 照著末底改 所 嘱咐的,还没有 将 籍贯 宗族 告诉人;因为以斯帖 遵 末底改 的命,如 抚养 她的时候一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, '当那 时候,末底改 坐 在朝 门,王 的太监 中有两个 守 门的,辟探 和提列,恼恨 亚哈随鲁 王,想要 下 手 害他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, '末底改 知道 了,就告诉 王后 以斯帖。以斯帖 奉末底改 的名,报告 于 王; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, '究察 这事,果然是实,就把二人 挂 在 木头上,将这事在王 面前 写 于 历史上。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, '这 事 以后,亚哈随鲁 王 抬举 亚甲族 哈米大他 的儿子 哈曼,使他高升,叫 他的爵位 超过 与他 同事的 一切 臣宰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, '在朝 门 的 一切 臣仆 都跪 拜 哈曼,因为 王 如此 吩咐;惟独末底改 不 跪 不 拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, '在朝 门 的 臣仆 问末底改 说:「你 为何 违背 王 的命令呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, ' 他们天 天 劝 他,他还是不 听,他们就告诉 哈曼,要看 末底改 的事 站得住站不住,因 他已经告诉 他们 自己是 犹大人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, '哈曼 见 末底改 不 跪 不拜,他 就怒气 填胸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, ' 他们已将 末底改 的本族 告诉 哈曼;他以为 下 手 害末底改 一人 是小事, 就要 灭绝 亚哈随鲁 王通 国 所有的 犹大人,就是 末底改 的本族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, '亚哈随鲁 王 十 二 年 正 月,就是 尼散 月,人在哈曼 面前,按日 日 月 月 掣 普珥,就是 掣签,要定何月何日为吉,择定了十 二月,就是 亚达 月。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, '哈曼 对亚哈随鲁 王 说:「有 一种 民 散 居 在 王国 各 省 的民中;他们的律例 与万 民 的律例不同,也不 守 王的 律例,所以容留他们 与王 无 益。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, ' 王 若 以为美,请下旨意 灭绝他们;我就捐 一万 他连得 银子 交给 掌管 国帑的人,纳 入 王 的府库。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, '于 是王 从 自己手上 摘下 戒指 给 犹大人 的仇敌─亚甲族 哈米大他 的儿子 哈曼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, '王 对哈曼 说:「这银子 仍赐 给你,这民也交给你,你可以随 意 待 他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, '正 月 十 三 日,就召 了王 的书记来,照著哈曼 一切 所 吩咐的, 用 各 省 的文字、各 族 的方言,奉亚哈随鲁 王 的名 写旨意,传与 总督 和 各省 的省长,并 各 族 的首领;又用王 的戒指 盖印, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, ' 交给 驿卒 传 到 王 的各 省,吩咐将 犹大人,无论 老 少 妇女 孩子,在一 日之间,十 二 月,就是 亚达 月 十 三日,全然剪除,杀戮 灭绝,并夺他们的财 为掠物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, '抄录 这旨意,颁行 各 省,宣告 各 族,使他们 预备 等候那 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, '驿卒 奉王 命 急忙 起行,旨意 也传遍 书珊 城。王 同哈曼 坐下 饮酒,书珊 城 的民却都慌乱。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, '末底改 知道 所 做 的这一切事, 就撕裂 衣服,穿 麻衣,蒙灰尘,在城 中 行走,痛 哭 哀 号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, '到了 朝门 前停住脚步,因为 穿 麻衣 的不可 进 朝 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, '王 的谕 旨 所 到 的各 省 各处,犹大人 大大 悲哀,禁食 哭泣 哀号,穿麻衣 躺 在灰 中的甚多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, '王后 以斯帖 的宫女 和太监 来 把这事告诉 以斯帖,她甚是 忧愁,就送 衣服 给 末底改 穿,要他 脱下 麻衣,他却不 受。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, '以斯帖 就把王 所 派 伺候她 的一个太监,名叫哈他革 召来,吩咐他 去见 末底改,要知道 这 是什么事,是 什么缘故。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, '于 是哈他革 出 到 朝 门 前 的 宽阔处 见 末底改。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, '末底改 将 自己所 遇的事,并 哈曼 为灭绝 犹大人 应许 捐 入 王 库 的 银 数 都 告诉 了他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, '又将 所 抄写 传遍 书珊城 要灭绝 犹大人的旨意 交 给哈他革,要给 以斯帖 看,又要给她 说明,并嘱咐 她 进去 见 王,为 本族的人 在王面前 恳切祈求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, '哈他革 回来,将 末底改 的话 告诉 以斯帖; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, '以斯帖 就吩咐 哈他革 去见 末底改,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, '「王 的一切 臣仆 和各省 的人民 都知道 有 一个 定例:若 不 蒙召,擅入 内 院 见 王 的,无论 男 女 必被治死;除 非 王 向他 伸出 金 杖,不得存活。现在我 没有 蒙召 进去 见 王 已经 三十 日了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, '人就把 以斯帖 这话 告诉 末底改。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, '末底改 托 讬人 回复 以斯帖说:「你 莫 想 在王 宫 里强过一切 犹大人,得免这祸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, '此 时 你若 闭口不言,犹大人 必从别 处 得 解脱,蒙拯救;你 和你父 家 必致灭亡。焉 知 你得了 王后的位分 不是 为现今 的机会吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, '以斯帖 就吩咐 人回报 末底改说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, '「你当去 招聚 书珊城 所有的 犹大人,为我 禁食 三 昼 三夜,不 吃 不 喝;我 和我的宫女 也 要这样 禁食。然后我 违 例 进去 见 王,我若 死 就死吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, '于 是末底改 照以斯帖 一切 所 吩咐的 去 行。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, ' 第三 日,以斯帖 穿上 朝服,进王 宫 的内 院,对 殿 站立。王 在殿 里坐 在 宝 座上,对著 殿 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, ' 王 见 王后 以斯帖 站 在院内,就 施 恩于 她, 向她 伸出 手中 的 金 杖;以斯帖 便向前 摸 杖 头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, '王 对她 说:「王后 以斯帖啊,你 要什么?你求 什么,就是 国 的一半 也必赐 给你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, '以斯帖 说:「 王 若 以为美,就请王 带著哈曼 今日 赴 我所 预备 的筵席。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, '王 说:「叫 哈曼 速速 照 以斯帖 的话 去行」。于 是王 带著哈曼 赴 以斯帖 所 预备 的筵席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, '在酒 席筵前,王 又问以斯帖 说:「你要 什么,我必赐 给你;你求 什么,就是 国 的一半 也必为你成就。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, '以斯帖 回答 说:「我有所要,我有所求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, '我若 在王 眼前 蒙 恩, 王 若 愿 意 赐 我所要的,准 我所求的,就请王 带著哈曼 再赴 我所 要预备 的筵席。明日 我必照王 所问的 说明。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, '那 日 哈曼 心中 快乐,欢欢喜喜地 出来;但 见 末底改 在朝 门 不 站起来,连身也不 动, 就满心 恼怒 末底改。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, '哈曼 暂且忍耐 回 家,叫人 请 他朋友 和 他妻子 细利斯 来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, '哈曼 将 他富厚 的荣耀、众多的 儿女,和 王 抬举他 使他超 乎 首领 臣仆 之上,都 述说 给他们听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, '哈曼 又说:「 王后 以斯帖 预备 筵席,除了 我 之外不许 别人随 王 赴席。明日 王后 又 请 我 随 王赴席; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, ' 只是 我 见 犹大人 末底改 坐 在朝 门,虽有这 一切荣耀,也与我 无 益。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, '他的妻 细利斯 和他一切的 朋友 对他 说:「不如立 一个五丈 高 的木架,明早 求 王 将 末底改 挂 在其上,然后你可以欢欢喜喜地 随 王 赴 席。」哈曼 以 这话 为美,就叫人做了 木架。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, '那 夜 王 睡不著 觉,就吩咐人 取 历史来, 念 给他听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, '正遇见 书上写著 说:王 的太监 中有 两个 守 门的,辟探 和提列,想要 下 手 害亚哈随鲁 王,末底改 将这事 告诉王后。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, '王 说:「末底改行了 这事,赐 他 什么 尊荣 爵位没有?」伺候 王 的臣仆 回答说:「没有 赐 他 什么。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, '王 说:「谁 在院子里?」(那时哈曼 正进 王 宫 的外 院,要求 王 将 末底改 挂 在 他所 预备 的木架上。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, '臣仆 说:「 哈曼 站 在院内。」王 说:「叫他进来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, '哈曼 就进去。王 问他 说:「王 所 喜悦 尊荣的人,当如何 待 他呢?」哈曼 心 里说:「王 所喜悦 尊荣的,不是 我 是谁呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, '哈曼 就回答说:「王 所 喜悦 尊荣 的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, '当 将王 常穿 的朝 服 和 戴 冠 的 御 马, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, ' 都交 给 王 极尊贵 的一个 大臣,命他将衣服给 王 所 喜悦 尊荣 的人 穿上,使他骑 上 马,走遍城 里的街市,在他面前 宣告说:王 所 喜悦 尊荣的人,就如此 待 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, '王 对哈曼 说:「你速速 将 这衣服 和 马,照你所 说的,向坐 在朝 门 的犹大人 末底改 去行。凡 你所 说的,一样 不可 缺。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, '于 是哈曼 将 朝服 给 末底改 穿上,使他骑上 马,走遍城 里的街市,在他面前 宣告说:「王 所 喜悦 尊荣的人,就如此 待 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, '末底改 仍回 到 朝 门,哈曼 却忧忧闷闷 地蒙著 头,急忙 回 家去了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, ' 将 所 遇的 一切事 详细说 给他的妻 细利斯 和他的众 朋友听。他的智慧人 和他的妻 细利斯 对他 说:「你在末底改 面前 始 而败落,他 如果 是犹大 人,你必不 能胜 他,终 必 在他面前 败落。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, '他们还 与 哈曼说话的时候,王 的太监 来 催 哈曼 快去 赴 以斯帖 所 预备 的筵席。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, '王 带著哈曼 来 赴 王后 以斯帖 的筵席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, '这第二次 在酒 席筵前,王 又 问以斯帖 说:「王后 以斯帖啊,你要 什么,我必赐 给你;你求 什么,就是 国 的一半 也必为你成就。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, '王后 以斯帖 回答 说:「我若 在王 眼前 蒙 恩, 王 若 以为美,我所愿 的,是愿 王将我的性命 赐 给我;我所求的,是求王将我的本族赐给我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, '因 我 和我的本族 被卖了,要剪除 杀戮 灭绝我们。我们若 被卖 为奴 为婢,我也闭口不言;但 王 的损失,敌人 万不能 补足。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, '亚哈随鲁 王 问 王后 以斯帖 说:「 擅敢 起意 如此 行 的是 谁?这人 在哪里呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, '以斯帖 说:「仇 人 敌人 就是这 恶人 哈曼!」哈曼 在王 和王后 面前 就甚惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, '王 便大怒,起来 离开 酒 席 往 御 园去了。 哈曼 见 王 定意 要加罪 与他,就起来,求 王后 以斯帖 救 命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, '王 从御 园 回 到 酒 席 之处,见哈曼 伏 在 以斯帖 所 靠 的榻上;王 说:「他竟敢 在宫内、在我面前 凌辱 王后吗?」这话 一出 王 口,人就蒙了 哈曼 的脸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, '伺候 王 的 一个 太监 名叫哈波拿,说:「 哈曼 为那 救 王 有 功 的末底改 做了 五 丈 高 的木架,现今立 在哈曼 家里。」王 说:「把哈曼挂 在其上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, '于 是人将 哈曼 挂 在 他为末底改 所 预备 的木架上。王 的忿怒 这才止息。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, '当 日,亚哈随鲁 王 把 犹大人 仇敌 哈曼 的家产 赐 给王后 以斯帖。末底改 也来 到王 面前,因为 以斯帖 已经告诉王, 末底改是 她的亲属。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, '王 摘下 自己的戒指,就是 从哈曼 追回的,给了 末底改。以斯帖 派 末底改 管理 哈曼 的家产。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, '以斯帖 又 俯伏 在 王 脚 前,流泪 哀告,求 他 除掉 亚甲族 哈曼 害 犹大人 的恶 谋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, '王 向以斯帖 伸出 金 杖;以斯帖 就起来,站 在王 前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, '说:「亚甲族 哈米大他 的儿子 哈曼设谋传旨,要杀灭 在王 各 省 的 犹大人。现今 王 若 愿 意,我若 在王眼前 蒙 恩,王 若以 为美,若喜悦 我,请王另下旨意,废除 哈曼 所 传 的那旨意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, ' 我何 忍 见 我本族 的人受 害?何 忍 见 我同宗 的人被灭呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, '亚哈随鲁 王 对王后 以斯帖 和犹大人 末底改 说:「因 哈曼 要下 手 害犹大人, 我已将他 的家产 赐 给以斯帖,人也将哈曼 挂 在 木架上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, '现在你们 可以随 意 奉王 的名 写 谕旨给 犹大人,用王 的戒指 盖印;因为 奉王 名 所 写、用王 戒指 盖印 的谕旨,人都不能 废除。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, ' 三 月,就是 西弯 月 二十 三日,将王 的书记 召来,按著 末底改 所 吩咐的,用各 省 的文字、各 族 的方言,并 犹大人 的文字 方言 写谕旨,传给那 从印度 直到 古实 一百 二十 七 省的 犹大人 和 总督 省 长 首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, '末底改奉亚哈随鲁 王 的名 写 谕旨,用王 的戒指 盖印,交给 骑 御 马 圈快马 的驿 卒,传到各处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, '谕旨中,王 准 各 省 各 城 的 犹大人 在一 日之间,十 二 月,就是 亚达 月 十 三日,聚集 保护 性命,剪除 杀戮 灭绝 那要攻击 犹大人 的一切 仇敌 和他们的妻子 儿女,夺取他们的财 为掠物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, '抄 录 这谕旨,颁行 各 省,宣告 各 族,使 犹大人 预备等候 那 日,在仇敌 身上报仇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, '于 是骑 快 马 的驿卒 被王 命 催促,急忙 起行;谕旨 也传遍 书珊 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, '末底改 穿著蓝色 白色 的朝 服,头戴大 金 冠冕,又穿紫色 细麻布 的外袍,从王 面前 出来;书珊 城 的人民都欢呼 快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, '犹大人 有 光荣,欢喜 快乐 而得尊贵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, '王 的谕 旨 所 到的 各 省 各 城, 犹大人 都欢喜 快乐,设摆筵宴,以那日为吉 日。那国 的人民,有许多 因 惧怕 犹大人,就入了犹大籍。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, '十 二 月,乃 亚达 月 十 三 日, 王 的谕 旨 将要 举行,就是 犹大人 的仇敌 盼望 辖制 他们 的日子, 犹大人 反倒 辖制 恨他们的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, '犹大人 在亚哈随鲁 王 各 省 的城 里聚集,下 手 击杀那要 害他们的人。无 人 能敌挡 他们,因为 各 族 都惧怕他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, '各 省 的首领、总督、省长,和 办理 王 事的人,因 惧怕 末底改,就都帮助 犹大人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, ' 末底改 在朝 中 为大,名声 传遍 各 省, 日渐 昌盛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, '犹大人 用刀 击杀 一切 仇敌, 任意 杀 灭 恨他们的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, '在书珊 城,犹大人 杀 灭 了五 百 人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, '又杀 巴珊大他、 达分、 亚斯帕他、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, ' 破拉他、 亚大利雅、 亚利大他、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, ' 帕玛斯他、 亚利赛、 亚利代、 瓦耶撒他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, ' 这十 人都是哈米大他 的孙子、犹大人 仇敌 哈曼 的儿子。犹大人却没有 下 手 夺取财物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, '当 日,将书珊 城 被杀 的人数 呈 在王 前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, '王 对王后 以斯帖 说:「犹大人 在书珊 城 杀 灭 了五 百 人,又杀了 哈曼 的十 个儿子,在王 的各省 不知如何 呢?现在你要 什么,我必赐 给你;你还 求 什么,也必为你成就。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, '以斯帖 说:「 王 若 以为美,求你准 书珊 的 犹大人,明日 也 照今日 的旨意 行,并将 哈曼 十个 儿子 的尸首挂 在 木架上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, '王 便允准 如此 行。旨意 传 在书珊,人就把 哈曼 十个 儿子 的尸首挂起来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, '亚达 月 十 四 日,书珊 的 犹大人 又 聚集 在书珊,杀了 三 百 人,却没有 下 手 夺取财物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, '在王 各省 其余 馀 的 犹大人 也都聚集 保护 性命,杀了 恨他们的人 七万五千,却没有 下 手 夺取财物。这样,就脱离仇敌,得享平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, '亚达 月 十 三 日,行了这事;十 四 日 安息,以这日 为 设筵 欢乐 的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, '但书珊 的 犹大人,这十 三 日、十 四 日 聚集杀戮仇敌;十 五 日 安息,以这日 为 设筵 欢乐 的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, '所 以 住 无城墙 乡村 的犹大人,如今都以 亚达 月 十 四 日 为 设筵 欢乐 的吉 日,彼此 餽送 礼物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, '末底改 记录 这 事,写 信 与 亚哈随鲁 王 各 省 远 近 所有的 犹大人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, '嘱咐 他们 每 年 守 亚达 月 十 四、 十 五 两日, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, '以这月 的两日 为 犹大人 脱离仇敌 得平安、 转 忧 为喜、转悲 为乐的吉 日。在这两日 设 筵 欢乐,彼此 餽送 礼物,赒济 穷人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, '于 是,犹大人 按著 末底改 所 写 与他们的信,应承 照 初次 所守 的守为永例; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, '是因 犹大人 的仇敌 亚甲族 哈米大他 的儿子 哈曼 设谋 杀害 犹大人,掣 普珥,就是 掣签,为要杀尽 灭绝他们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, '这事报告 于  王,王便降 旨 使哈曼谋害 犹大人 的 恶 事 归 到 他自己的头上,并吩咐把他 和 他的众子 都挂 在 木架上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, '照著 普珥 的名字,犹大人就 称 这 两日为「普珥日」。他们因 这 信上的 话,又因 所 看见 所 遇见 的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, ' 就应 承 自己 与 后裔,并 归附 他们的人,每 年 按时 必 守 这 两 日,永远不 废。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, '各 省 各 城、家家 户户、世 世 代代 纪念 遵守 这 两日,使这「普珥 日」在犹大人 中 不可 废掉,在他们后裔 中也不可 忘记。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, '亚比孩 的女儿─王后 以斯帖 和犹大人 末底改 以 全 权 写 第二 封信,坚嘱 犹大人守这「普珥日」, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, '用和平 诚实 话 写信 给 亚哈随鲁 王国 中一百 二十 七 省 所有的 犹大人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, '劝他们按时 守 这「普珥日」,禁食 呼求,是照犹大人 末底改 和王后 以斯帖 所 嘱咐的,也照犹大人为 自己 与 后裔 所 应承的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, '以斯帖 命定 守「普珥日」,这 事 也记录 在书上。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, '亚哈随鲁 王 使 旱地 和海 岛 的人民都进贡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, '他以权柄 能力所 行的,并他 抬举 末底改 使他高升 的事,岂不 都 写 在 米底亚 和波斯 王 的历史上吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, ' 犹大人 末底改 作亚哈随鲁 王 的宰相,在犹大人 中为大,得他众 弟兄 的喜悦,为本族的人 求 好处,向 他们 说 和平的话。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, '乌斯 地 有 一个人 名叫 约伯;那 人 完全 正直,敬畏 神,远离 恶事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, '他 生了 七个 儿子,三个 女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, '他的家产 有 七 千 羊,三 千 骆驼,五 百 对 牛,五 百 母驴,并有许 多 仆婢。这 人 在东方 人 中就为 至大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, '他的儿子 按著日子 各 在 自己家 里设摆筵宴,就打发人去,请了 他们的三个 姊妹来,与他们 一同吃 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, ' 筵宴 的日子 过了,约伯 打发 人去叫他们自洁。他清早 起来,按著他们众人 的数目 献 燔祭;因为 他 说:「恐怕 我儿子 犯了罪,心中 弃掉 神。」约伯 常常 这样 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, '有 一天, 神 的众子 来 侍立 在 耶和华面前,撒但 也 来 在其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, '耶和华 问 撒但 说:「你从哪里 来?」撒但 回答 说:「我从地上 走来走去,往返而来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, '耶和华 问 撒但 说:「你曾用 心 察看 我的仆人 约伯没有? 地上 再没有 人 像他 完全 正直,敬畏 神,远离 恶事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, '撒但 回答 耶和华 说:「约伯 敬畏 神,岂是无故呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, '你 岂不是 四面 圈上篱笆 围护他 和 他的家,并 他 一切 所有的吗?他手 所做的 都蒙你赐福;他的家产 也在地上 增多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, '你且 伸 手 毁 他 一切 所有的;他必 当 面 弃掉你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, '耶和华 对 撒但 说:「 凡 他 所 有的都在你手中;只是 不可 伸 手 加害于 他。」于 是撒但 从 耶和华 面前 退去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, '有 一天,约伯的儿 女 正在他们长 兄 的家 里吃饭 喝 酒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, '有报信的 来 见 约伯,说:「牛 正 耕地,驴 在 旁边 吃草, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, '示巴人 忽然闯来,把牲畜掳去,并用 刀 杀了 仆人;惟有 我 一人 逃脱,来报信 给你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, '他 还 说话的时候,又有人 来 说:「 神 从 天上 降下 火来,将群羊 和仆人 都烧 灭了;惟有 我 一人 逃脱,来报信 给你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, '他 还 说话的时候,又有人 来 说:「迦勒底人 分作 三 队 忽然闯来,把 骆驼 掳去,并用 刀 杀了 仆人;惟有 我 一人 逃脱,来报信 给你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, '他 还 说话的时候,又有人 来 说:「你的儿 女 正在他们长 兄 的家 里吃饭 喝 酒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, '不料,有狂 风 从 旷野 刮来,击打 房屋 的四 角,房屋倒塌 在 少年人身上,他们就都死了;惟有 我 一人 逃脱,来报信 给你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, '约伯 便起来,撕裂 外袍,剃了 头,伏在 地上 下拜, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, '说:「我赤身 出 于 母 胎,也必赤身 归回;赏赐 的是耶和华,收取 的也是耶和华。耶和华 的名 是 应当称颂的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, '在这 一切的事上 约伯 并不 犯罪,也不以 神 为愚妄(或译:也不妄评 神)。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, '又有 一天, 神 的众子 来 侍立 在 耶和华面前,撒但 也 来 在其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, '耶和华 问 撒但 说:「你从 哪里 来?」撒但 回答 说:「我从地上 走来走去,往返而来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, '耶和华 问 撒但 说:「你曾用 心 察看 我的仆人 约伯没有? 地上 再没有 人 像他 完全 正直,敬畏 神,远离 恶事。你虽激动我 攻击他,无故地 毁灭他,他仍然 持守 他的纯正。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, '撒但 回答 耶和华 说:「人 以皮 代 皮,情愿 舍去 一切 所有的,保全 性命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, '你且 伸 手 伤 他的骨头 和 他的肉,他必 当 面 弃掉你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, '耶和华 对 撒但 说:「 他在你手中,只要 存留 他的性命。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, '于 是撒但 从 耶和华 面前 退去,击打 约伯,使他从脚 掌 到 头顶 长毒 疮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, '约伯 就坐 在炉灰 中,拿 瓦片 刮 身体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, '他的妻子 对他 说:「你仍然 持守 你的纯正吗?你弃掉 神,死了吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, '约伯却对她 说:「你说话 像 愚顽的妇人 一样。嗳!难道我们从 神 手里得 福,不 也 受 祸吗?」在这 一切的事上 约伯 并不 以口 犯罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, '约伯 的三 个朋友─提幔人 以利法、书亚人 比勒达、拿玛人 琐法─听说 有这 一切的 灾祸 临 到他身上,各人 就从本处 约会 同 来,为他 悲伤,安慰他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, '他们远远地 举 目观看,认 不出他来,就放 声 大哭。各人 撕裂 外袍,把尘土 向天 扬起来,落在 自己的头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, '他们就同他 七 天 七 夜 坐 在地上,一个人也不 向他 说 句话,因为 他极 其 痛苦。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, '此后,约伯 开  口 咒诅 自己的生日, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, ' 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, '愿 我 生 的那日 和说 怀了 男胎 的那夜 都灭没。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, '愿 那 日 变为 黑暗;愿  神 不 从上面 寻找它;愿 亮光 不 照 于 其上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, '愿 黑暗 和死荫 索取那日;愿 密云 停 在其上;愿 日 蚀 恐吓它。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, '愿 那 夜 被幽暗 夺取,不 在年 中的日子 同乐,也不 入 月 中的数目。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, ' 愿  那夜 没有生育,其间 也没 有 欢乐的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, '愿 那咒诅 日子 且能 惹动 鳄鱼 的咒诅那夜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, '愿 那夜黎明 的星宿 变为黑暗,盼 亮 却不亮,也不 见 早晨的光线 缐(原文是眼皮); ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, '因 没有 把怀我胎 的门 关闭,也没有将患难 对我的眼 隐藏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, '我为何 不 出母胎 而死?为何不出 母腹 绝气? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, '为何 有膝 接收我?为何 有奶 哺养我? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, '不然,我就早已躺卧 安 睡, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, '和 地上 为自己 重造 荒邱 的君王、谋士, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, '或 与 有 金子、将银子 装满了 房屋 的王子 一同 安息; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, '或 像隐而未现、不到期而落的胎,归于  无有,如同未 见 光 的婴孩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, '在那里 恶人 止息 搅扰, 困乏人 得享安息, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, '被囚的人 同 得安逸,不 听见 督工 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, '大 小 都在 那里;奴仆 脱离 主人的辖制。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, '受患难的人 为何 有光 赐给他呢?心中 愁苦 的人为何有生命赐给他呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, '他们切望 死,却不得死;求死,胜于 求隐藏的珍宝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, ' 他们寻见 坟墓 就快乐, 极 其欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, '人 的道路 既然 遮隐, 神 又把他 四面围困,为何有光赐给他呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, '我未曾 吃饭 就 发出 叹息;我唉哼 的声音涌出 如水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, '因 我所 恐惧 的临到我身,我所 惧怕 的迎 我而来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, '我不得 安逸,不得 平静,也不得 安息,却有患难 来到。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, '提幔人 以利法 回答 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, '人若想 与你 说话,你就厌烦吗?但谁 能 忍住不 说呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, ' 你素来教导 许多的人,又坚固 软弱 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, '你的言语 曾扶助 那将要跌倒的人;你又使软弱 的膝 稳固。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, '但 现在 祸患临 到你,你就昏迷,挨 近你,你便惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, '你的倚靠 不是 在你敬畏 神吗?你的盼望 不是在你行事 纯正吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, '请 你追想:无辜的 人有 谁 灭亡?正直的 人在何处 剪除? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, '按我所 见,耕 罪孽、种 毒害 的人都照样收割。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, '神 一出气,他们就灭亡; 神一发 怒,他们就消没。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, '狮子 的吼叫 和猛狮 的声音尽都止息;少壮狮子 的牙齿 也都敲掉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, '老狮子 因绝 食 而死;母狮 之子 也都离散。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, '我 暗暗地得了 默示;我耳朵 也听 其 细微的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, '在思念 夜中、异象之间, 世人 沉 睡的时候, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, '恐惧、战 兢 临到我身,使我百 骨 打战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, '有灵 从 我面 前经过,我身 上的毫毛 直立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, '那灵停住,我却不能 辨 其形状;有影像 在我眼 前。我在静默 中听见 有声音说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, '必死的人岂能比 神 公义吗?人 岂能 比造他的主 洁净吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, ' 主不 信靠 他的臣仆,并且指 他的使者 为愚昧; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, '何况 那住 在土 房、 根基 在尘土里、被 蠹虫 所毁坏的人呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, '早 晚之间,就被毁灭,永 归无有,无人 理会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, '他帐棚的绳索 岂不 从中 抽出来呢?他死,且是无 智慧而死。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, '你且 呼求,有 谁答应你?诸圣者之中,你转 向 哪一位呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, ' 忿怒 害死 愚妄人;嫉妒 杀死 痴迷人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, '我 曾见 愚妄人 扎下根,但我忽然 咒诅 他的住处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, '他的儿女 远离 稳妥的地步,在城门口 被压,并无人 搭救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, '他的 庄稼 有饥饿的人 吃尽了,就是在 荆棘 里的也抢去了;他的财宝 有网罗 张口吞灭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, '祸患 原 不是 从土 中出来;患难 也不是 从地 里发生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, ' 人 生 在世必遇患难,如同火 星 飞 腾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, '至于  我,我必仰望 神,把我的事情 托 讬付 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, '他行 大事 不可 测度,行奇事 不可 胜 数: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, '降 雨 在 地 上,赐 水 于  田 里; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, '将卑微 的安置 在高处,将哀痛 的举到 稳妥之地; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, '破坏 狡猾人 的计谋,使他们 所谋的 不得 成就。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, '他叫有智慧的 中了 自己的诡计,使狡诈人 的计谋 速速灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, '他们白昼 遇见 黑暗,午间 摸索 如在夜间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, '神拯救 穷乏人 脱离他们口 中的刀 和强暴人 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, '这样,贫寒的人 有 指望,罪孽之辈 必塞口 无言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, ' 神 所惩治 的人 是有福的!所以你不可 轻看 全能者 的管教。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, '因为 他 打破,又缠裹;他击伤,用手 医治。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, '你六次 遭难,他必救你;就是七次,灾祸 也无法 害 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, '在饥荒中,他必救你 脱离死亡;在争战 中,他必救你脱离刀剑 的权力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, '你必被隐藏,不受口舌 之害;灾殃 临到,你也不 惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, '你遇见灾害 饥馑,就必嬉笑;地上的 野兽,你也不 惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, '因为 你必与 田间的 石头 立约;田里的 野兽 也必与你 和好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, '你必知道 你帐棚 平安,要查看 你的羊圈,一无 所失; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, '也必知道 你的后裔 将来发达,你的子孙 像地上的 青草。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, '你必寿高年迈 才归 坟墓,好像禾捆 到时 收藏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, ' 这理,我们已经考察,本是 如此。你 须要听,要知道 是与自己有益。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, '约伯 回答 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, '惟愿  我的烦恼 称 一称,我一切的 灾害 放 在天平里; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, ' 现今 都比海 沙 更重,所以 我的言语 急躁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, '因 全能者 的箭 射入我身;其 毒,我的灵 喝尽了; 神 的惊吓 摆阵攻击我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, '野驴 有 草 岂能叫唤?牛 有 料 岂 能吼叫? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, '物淡 而无 盐 岂可吃吗?蛋 青 有 什么滋味呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, '看为可厌的 食物, 我心 不肯 挨近。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, '惟愿  我得著 所求的,愿  神 赐 我所切望的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, '就是愿  神 把我压碎,伸 手 将我剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, '我因 没有 违弃 那圣者的 言语,就仍 以此为 安慰,在不 止息的 痛苦 中还可踊跃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, '我有什么 气力 使 我等候?我有什么 结局 使 我忍耐? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, '我的气力 岂是 石头的 气力?我的肉身 岂是 铜的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, '在我 岂不是 毫无 帮助吗?智慧 岂不是从我 心中赶出净尽吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, '那将要灰心、离弃 全能者、不敬畏 神的人,他的朋友 当以慈爱待他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, '我的弟兄 诡诈,好像 溪水,又像溪水 流干 的河道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, '这河因 结冰 发黑,有雪 藏 在其中; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, '天气渐暖 就随时 消化,日头炎热 便从原处 干涸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, '结伴的客旅 离弃大道,顺河偏行,到 荒野之地 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, '提玛 结伴的客旅 瞻望;示巴 同伙 夥的人 等候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, '他们因 失了盼望 就抱愧,来 到那里 便蒙羞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, ' 现在 你们正是 这样,看见 惊吓的事 便惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, '我岂 说:请你们供给 我,从你们的财物 中送礼物 给我? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, '岂说:拯救我 脱离敌人的 手吗?救赎我 脱离强暴人 的手吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, '请你们教导我,我 便不作声;使我 明白 在何事上 有错。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, '正直的 言语 力量何 其大!但你们责备 是责备 什么呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, '绝望人 的讲论 既然如风,你们还想要 驳正 言语吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, '你们想 为 孤儿 拈阄,以 朋友 当货物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, '现在 请你们 看看 我,我决不 当 面 说谎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, '请 你们转意,不 要 不公;请再 转意,我的事 有理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, '我的舌 上岂有 不义吗?我的口 里岂 不 辨 奸恶吗?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, '人 在 世上 岂无 争战 吗?他的日子 不像雇工人 的日子吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, '像奴仆 切慕 黑影,像雇工人 盼望 工价; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, '我 也照样 经过 困苦的 日月,夜间的 疲乏 为我 而定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, ' 我躺卧 的时候便说:我何时 起来,黑夜 就过去呢?我尽 是反来覆 复去,直到 天亮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, '我的肉体 以虫子 和尘土 为衣;我的皮肤 才收了口 又重新破裂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, '我的日子 比梭 更快,都消耗 在无 指望之中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, '求你想念, 我的生命 不过是一口气;我的眼睛 必不 再 见 福乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, '观看我的人,他的眼 必不 再见我;你的眼目 要看我,我却不在了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, '云彩 消散 而过;照样,人下 阴间 也不 再上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, '他不 再 回 自己的家;故土 也不 再 认识他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, ' 我 不 禁止 我口;我灵 愁苦,要发出言语;我心 苦恼,要吐露哀情。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, '我对 神说:我 岂是洋海,岂是 大鱼,你竟 防守 我呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, '若 说:我的床 必安慰我,我的榻 必解释 我的苦情, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, '你就用梦 惊骇我,用异象 恐吓我, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, '甚至我 宁肯 噎死,宁肯死亡,胜似留我这一身的骨头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, '我厌弃性命,不愿  永 活。你任凭 我吧,因 我的日子 都是虚空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, '人 算什么,你竟 看他为大, 将他放 在 心上? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, '每早 鉴察他,时刻 试验他? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, '你到何时 才转眼不 看 我,才 任凭我 咽下 唾沫呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, '鉴察 人的主啊,我若有罪,于 你 何 妨?为何 以 我当你的 箭靶子,使我 厌弃 自己的性命? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, '为何 不 赦免 我的过犯,除掉 我的罪孽? 我现今 要躺卧 在尘土中;你要殷勤地寻找我,我却不在了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, '书亚人 比勒达 回答 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, '这些话 你要说 到 几时?口 中的言语 如狂 风要到几时呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, '神 岂能偏离 公平?全能者 岂能 偏离 公义? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, '或者 你的儿女 得罪了 他;他使他们 受 报应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, '你 若 殷勤地寻求 神,向 全能者 恳求; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, '你 若 清洁 正直,他必定 为你 起来,使你公义的 居所 兴旺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, ' 你起初 虽然微小,终久 必甚 发达。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, ' 请 你考问 前 代,追念 他们的列祖 所查究的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, ' 我们 不过从昨日才有,一无 所知; 我们在 世的 日子 好像影儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, '他们 岂不 指教你,告诉 你,从心 里发出 言语来呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, '蒲草 没有 泥 岂能发长?芦荻 没有 水 岂能生发? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, '尚 青的时候,还没有 割下,比百样的 草 先 枯槁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, '凡 忘记 神的人,景况 也是这样;不虔敬人 的指望 要灭没。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, '他所 仰赖的 必折断;他所倚靠 的是蜘蛛 网。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, '他要倚靠 房屋,房屋却站立 不住;他要抓住 房屋,房屋却不能 存留。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, '他 在日光 之下 发青,蔓子 爬 满了 园子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, '他的根 盘绕 石堆,扎入 石 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, '他若 从本地 被拔出,那地就不认识 他,说:我没有 见过你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, '看哪,这就是 他道 中之乐;以后必另有人 从地 而生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, ' 神 必不 丢弃 完全人,也不 扶助 邪恶人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, '他还要 以喜笑 充满 你的口,以欢呼 充满你的嘴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, '恨恶你的 要披戴 惭愧;恶人 的帐棚 必归于 无有。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, '约伯 回答 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, '我真 知道 是 这样;但人 在 神 面前怎能 成为义呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, '若 愿 意 与他 争辩,千 中 之一 也不能 回答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, '他心 里有智慧,且大 有能力。谁向 神 刚硬 而得亨通呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, '他发怒, 把山 翻倒 挪移,山并不 知觉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, '他使地 震动,离其本位,地的柱子 就摇撼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, '他吩咐 日头不出来,就不 出来,又封闭 众星。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, '他独自 铺张 苍天,步行 在 海 浪之上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, '他造 北斗、参星、昴星,并南方的 密宫; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, '他行 大事, 不可 测度,行奇事,不可 胜 数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, ' 他从我旁边 经过,我却不 看见;他在我面前行走,我倒不 知觉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, ' 他夺取,谁 能阻挡?谁 敢问 他:你做 什么? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, '神 必不 收回 他的怒气;扶助 拉哈伯的,屈身 在他以下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, '既是 这样,我 怎敢回答他,怎敢选择 言语 与他辩论呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, '我虽 有义,也不 回答 他,只要向那审判我的 恳求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, '我若 呼吁,他应允我;我仍不 信 他真听 我的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, '他 用暴风 折断我,无故地 加增 我的损伤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, '我就是喘 一口气,他都不 容,倒 使我满心 苦恼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, '若 论力量,他真有能力! 若 论审判,他说谁 能将我传来呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, '我虽 有义,自己的口 要定我为有罪;我 虽完全,我口必显我为弯曲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, '我 本完全,不 顾 自己;我厌恶 我的性命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, '善恶无分,都是 一样;所 以 我说,完全人 和恶人,他 都灭绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, '若 忽然 遭杀害 之祸,他必戏笑 无辜的人 遇难。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, '世界 交 在恶人 手中;蒙蔽 世界审判官 的脸,若 不是 他,是 谁呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, '我的日子 比 跑信的 更快,急速过去,不 见 福乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, '我的日子过去 如 快 船,如急落 抓 食 的鹰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, '我若 说:我要忘记 我的哀情,除去 我的愁容,心中畅快; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, '我因 愁苦 而惧怕,知道 你必不 以我为无辜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, '我 必被你定为有罪,我何必 徒然 劳苦呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, '我若 用 雪 水 洗身,用碱 洁净 我的手, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, '你还 要扔我 在坑里,我的衣服 都憎恶我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, '他本 不 像我 是人,使我可以回答他,又使我们可以 同 听审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, '我们中间 没 有 听讼的人 可以向 我们两造 按 手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, '愿 他把 杖 离开  我,不 使惊惶 威吓我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, '我就说话,也不 惧怕他,现在我 却 不是 那样。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, '我 厌烦 我的性命,必由著 自己 述说我的哀情;因心里 苦恼,我要说话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, '对 神 说:不要 定我有罪,要指示我,你为 何 与我争辩? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, '你手 所造的,你又 欺压,又 藐视,却光照 恶人 的计谋。这事你 以为美吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, '你的 眼 岂是肉眼?你查看 岂 像人 查看吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, '你的日子 岂像人 的日子,你的年岁 岂 像人 的年岁, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, '就 追问 我的罪孽,寻察 我的罪过吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, '其实, 你知道 我没有 罪恶,并没有 能救我 脱离你手的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, '你的手 创造我,造就 我的四肢百体,你还要毁灭我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, '求 你记念─制造 我如抟泥一般,你还要使我归 于  尘土吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, '你不是 倒出我 来好像奶,使我凝结 如同奶饼吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, '你以皮 和肉 为衣给我穿上,用骨 与筋 把我全体联络。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, '你将生命 和慈爱 赐 给我;你也眷顾 保全 我的心灵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, '然而,你待我的这些事 早已藏 在你心里;我知道 你 久有此意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, '我若 犯罪,你就察看我,并不 赦免 我的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, '我若 行恶,便有了祸;我若为义,也不 敢抬 头,正是满心 羞愧,眼见 我的苦情。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, '我若昂首自得,你就追捕我 如狮子,又 在我身上 显出奇能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, '你重立 见证 攻击我,向我 加增 恼怒,如军兵 更换著 攻击我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, '你为何 使我出 母胎呢?不如我当时气绝,无 人 得见我; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, '这样,就如 没 有我一般,一出母胎 就被送 入坟墓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, '我的日子 不是 甚少吗?求你停 手宽容 我,叫我在往 而不 返 之先─就是往 黑暗 和死荫 之地以先─可以稍得 畅快。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, '那地 甚是 幽暗,是死荫 混沌之地;那里的光 好像 幽暗。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, '拿玛人 琐法 回答 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, '这许多的 言语 岂不 该回答吗?多嘴多舌 的人 岂 可称为义吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, '你夸大的话 岂能使人 不作声吗?你戏笑 的时候岂没有人 叫你害羞吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, '你说:我的道理 纯全;我在你眼前 洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, '惟愿  神 说话;愿 他开  口 攻击你, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, '并将智慧 的奥秘 指示 你; 他有诸般的 智识。所以当知道 神 追讨 你 比你罪孽该得的还少。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, '你考察 就能测透 神吗?你岂能 尽情 测透 全能者吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, '他的智慧高于  天,你还能做 什么?深 于 阴间,你还能知道 什么? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, '其量 比地 长,比 海 宽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, '他若 经过,将人拘禁,招人受审,谁 能阻挡他呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, '他 本 知道 虚妄的 人;人的罪孽,他虽不 留意,还是无所不见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, '空虚的 人 却毫无知识;人 生 在世好像野驴 的驹子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, '你 若 将心 安正,又向主 举 手; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, '你手里 若 有罪孽,就当远远地除掉,也不 容非义 住 在你帐棚之中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, ' 那时,你必仰起 脸 来毫无斑点;你也必 坚固,无 所惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, '你 必 忘记 你的苦楚,就是想起 也如流过去 的水一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, '你在世的日子 要比正午 更明,虽有黑暗 仍 像早晨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, '你因 有 指望 就必稳固,也必四围巡查,坦然 安息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, '你躺卧,无人 惊吓,且有许多人 向你 求恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, '但恶人 的眼目 必要失明。他们 无路可逃;他们的指望 就是气 绝。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, '约伯 回答 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, ' 你们 真是 子民哪,你们死亡,智慧 也就灭没了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, '但我 也 有聪明,与你们一样, 并非 不及 你们。你们所说的,谁 不知道呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, '我这求告 神、蒙他应允 的人竟成了 朋友 所讥笑的;公义 完全 人竟受了人的讥笑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, '安逸的 人心里 藐视 灾祸;这灾祸常常等待 滑 脚的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, '强盗的 帐棚 兴旺,惹 神 的人稳固, 神 多将财物送 到他们 手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, ' 你且 问 走兽,走兽必指教你;又问空中的 飞鸟,飞鸟必告诉 你; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, '或 与地 说话,地必指教你;海中 的鱼 也必向你 说明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, '看这 一切,谁 不 知道 是 耶和华 的手 做成的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, '凡 活物 的生命和 人类 的气息 都 在他手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, '耳朵 岂不 试验 言语,正如上膛 尝 食物吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, '年老的 有智慧;寿高的 有知识。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, '在 神 有智慧 和能力;他有 谋略 和知识。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, ' 他拆毁的,就不能 再建造;他捆 住 人,便不 得开 释。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, ' 他把水 留住,水便枯干;他再发出水来,水就翻 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, '在他 有能力 和智慧,被诱惑的 与诱惑人的 都是属他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, '他把谋士 剥衣 掳去,又使审判官 变成愚人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, '他放松 君王 的绑,又用带子 捆 他们的腰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, '他把祭司 剥衣 掳去,又使有能的人 倾败。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, '他废去 忠信人的 讲论,又夺去 老人 的聪明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, '他使 君王 蒙羞被辱,放松 有力之人 的腰带。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, '他将深奥的事 从 黑暗中 彰显,使死荫 显为 光明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, '他使邦国 兴旺 而又毁灭;他使邦国 开 广 而又掳去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, '他将地上 民 中首领 的聪明 夺去,使他们在荒废 无 路 之地漂流; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, '他们无 光,在黑暗中 摸索,又使他们东倒西歪,像醉酒的人一样。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, ' 这一切,我眼 都见过;我耳 都听过,而且明白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, '你们所知道的,我 也 知道,并 非不 及 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, '我 真要 对 全能者 说话;我愿  与 神 理论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, ' 你们 是编造 谎言的,都是 无用的 医生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, '惟 愿  你们全然 不作声;这就算为 你们 的智慧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, '请 你们听 我的辩论,留心听 我口中 的分诉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, '你们要为 神 说 不义的话吗?为他 说 诡诈的言语吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, '你们要为 神 徇 情吗?要为他争论吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, ' 他查出 你们来,这岂是好吗? 人欺哄 人,你们也要照样欺哄 他吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, '你们若 暗中 徇 情,他必要 责备 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, '他的尊荣 岂不 叫你们 惧怕吗?他的惊吓 岂不临 到你们吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, '你们以为可记念的 箴言 是炉灰的箴言;你们以为可靠的坚垒 是淤泥 的坚垒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, '你们不要作声,任凭我吧!让我 说话,无论 如何 我都承当。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, '我何必 把 我的肉 挂 在牙上,将我的命 放 在手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, ' 他必杀我;我虽无 指望,然而 我在 他面前 还要辩明 我所行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, ' 这 要成为我的 拯救,因为 不虔诚的人 不 得到 他面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, '你们要细 听 我的言语,使我所辩论 的入你们的耳中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, ' 我已陈明 我的案,知道 自己 有义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, '有 谁 与我 争论, 我就情愿 缄默不言,气绝而亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, '惟有 两件 不要 向我 施行,我就 不 躲开  你的面: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, '就是把你的手 缩回,远离我身;又不 使你的惊惶 威吓我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, '这样,你呼叫,我 就回答;或是 让我说话,你回答我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, '我的罪孽 和罪过 有多少呢?求你叫我 知道 我的过犯 与罪愆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, '你为何 掩 面、拿我当 仇敌呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, '你要惊动 被风吹的 叶子吗?要追赶 枯干的 碎秸吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, ' 你按 罪状 刑罚我,又使我担当 幼年的 罪孽; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, '也把我的脚 上了 木狗,并窥察 我一切的 道路,为 我的脚 掌 划 㓰定界限。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, '我 已经像灭绝的 烂物,像虫 蛀 的衣裳。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, '人 为妇人 所生,日子 短少,多有 患难; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, '出来 如花,又被割下,飞去 如影,不能 存留。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, '这样的人 你岂 睁 眼 看他吗?又叫我 来 受审吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, '谁 能使 洁净 之物出于 污秽之中呢?无论谁 也不能! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, '人的日子 既然 限定,他的月 数 在你那里,你也派定 他的界限,使他不能 越过, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, '便求你转眼 不看他,使他得歇息,直等 他像雇工人 完毕 他的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, '树 若 被砍下, 还 可 指望 发芽,嫩枝 生长不 息; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, '其根 虽然 衰老 在地里,干 也死 在土中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, '及至得了水 气,还要发芽,又长 枝条,像 新栽的树一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, '但人 死亡 而消灭;他 气绝,竟在何处呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, '海 中 的水 绝尽,江河 消散 干涸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, '人也是如此,躺下 不再 起来,等到 天 没有了,仍不 得复醒,也不得 从睡 中唤醒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, '惟 愿  你把我藏 在阴间,存于 隐密处,等 你的忿怒 过去;愿 你为我 定了 日期,记念我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, '人 若 死了 岂能再活呢?我只要在 我一切 争战 的 日子,等我被释放(或译:改变)的时候 来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, '你呼叫,我 便回答;你手 所做的,你必羡慕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, '但 如今 你数点 我的脚步,岂不 窥察 我的罪过吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, '我的过犯 被你封 在囊中,也缝严了 我的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, ' 山 崩 变为无有;磐石 挪开  原处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, '水流 消磨 石头,所流溢的 洗去 地上 的尘土;你也照样灭绝 人 的指望。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, '你攻击人常常 得胜,使他去世;你改变 他的容貌,叫他往而不回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, '他儿子 得尊荣,他也不 知道,降为卑,他也不 觉得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, '但 知身 上 疼痛,心 中 悲哀。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, '提幔人 以利法 回答 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, '智慧人 岂可用虚空的 知识 回答,用东风 充满 肚腹呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, '他岂可用无 益的 话 和无 济 于 事 的言语 理论呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, ' 你 是废弃 敬畏的意,在 神 面前 阻止 敬虔的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, ' 你的罪孽 指教 你的口;你选用 诡诈人 的舌头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, '你自己的口 定你有罪,并非 是我;你自己的嘴 见证 你的不是。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, '你岂是头一个 被生的 人吗?你受造 在诸山 之先吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, '你曾听见 神 的密旨吗?你还将智慧 独自 得尽吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, '你知道 什么 是我们不 知道的呢?你明白 什么是 我们 不明白的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, '我们这里 有 白发的 和 年纪老迈的,比你父亲 还 老。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, '神 用温和的 话 安慰 你,你 以为太小吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, '你的心 为何 将你逼去?你的眼 为何 冒出火星, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, ' 使 你的灵 反对 神,也任你的口 发 这言语? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, '人 是什么,竟 算为洁净呢?妇人 所生的是什么,竟 算为义呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, ' 神不 信靠 他的众圣者;在他眼前,天 也不 洁净, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, '何况 那污秽 可憎、喝 罪孽 如水 的世人呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, '我指示你,你要听;我要述说 所 看见的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, '就是 智慧人 从列祖所受,传说 而不 隐瞒的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, '(这地 惟独 赐 给他们,并没有 外人 从他们中间 经过。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, '恶人 一生 之日 劬劳痛苦;强暴人 一生的年 数 也是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, '惊吓的 声音 常在他耳中;在平安时,抢夺的 必临到他那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, '他不 信 自己能从 黑暗中 转回;他 被 刀剑 等候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, '他 漂流在外 求食,说:哪里有食物呢?他知道 黑暗的 日子 在他手边 预备好了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, '急难 困苦 叫他害怕,而且胜了他,好像君王 预备 上阵一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, ' 他伸 手 攻击 神,以骄傲 攻击 全能者, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, '挺著颈项,用盾牌 的厚 凸面 向 全能者直闯; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, '是因 他的脸 蒙上 脂油, 腰 积成 肥肉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, '他曾住 在荒凉 城邑,无人 居住、将成 乱堆 的 房屋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, '他不得 富足,财物 不得 常存,产业 在地上 也不 加增。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, '他不得 出 离 黑暗。火焰 要将他的枝子 烧干;因 神口中 的气,他要灭亡(原文是走去)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, '他不用 倚靠 虚假 欺哄自己,因 虚假 必成为 他的报应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, '他的日期 未到之先,这事必成就;他的枝子 不得 青绿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, '他必像葡萄树的葡萄,未熟 而落;又像橄榄树 的花,一开 而谢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, '原来 不敬虔 之辈 必无生育;受贿赂之人 的帐棚 必被火 烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, '他们所怀的 是毒害,所生的 是罪孽;心里 所预备的 是诡诈。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, '约伯 回答 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, '这样的话 我听了 许多;你们 安慰人,反叫人愁烦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, '虚空的 言语 有穷尽吗? 有什么 话惹动你 回答呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, '我 也 能说 你们那样的话;你们 若 处在 我的 境遇,我也会联络 言语 攻击你们,又能向你们 摇 头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, '但我必用 口 坚固你们,用 嘴 消解你们的忧愁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, '我虽 说话,忧愁 仍不得 消解;我虽停住不说, 忧愁就离开  我吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, '但 现在 神使我困倦,使 亲友 远离我, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, '又抓住我,作 见证 攻击我;我身体的枯瘦 也当面 见证我的不是。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, '主发怒 撕裂我,逼迫我,向我 切 齿;我的敌人 怒 目 看我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, '他们向我 开  口,打 我的脸 羞辱我,聚 会 攻击我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, '神 把我交 给 不敬虔的人,把我扔 到 恶人 的手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, '我素来 安逸,他折断我,掐住 我的颈项,把我摔碎,又立我 为他的 箭靶子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, '他的弓箭手 四面围绕 我;他破裂 我的肺腑,并不 留情,把我的胆 倾倒 在地上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, '将我破裂 又 破裂,如同勇士 向我 直闯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, '我缝 麻布 在 我皮肤上,把我的角 放 在尘土中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, '我的脸 因 哭泣 发紫,在 我的眼皮 上有死荫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, '我的手中却 无 强暴;我的祈祷 也是清洁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, '地啊,不要 遮盖 我的血!不 要 阻挡 我的哀求! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, ' 现今, 在天 有我的见证,在上 有我的中保。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, '我的朋友 讥诮我,我却向 神 眼 泪汪汪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, '愿 人 得与 神 辩白,如同人 与朋友辩白一样; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, '因为 再过 几 年,我必走 那往而不 返 之路。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, '我的心灵 消耗,我的日子 灭尽;坟墓 为我预备好了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, '真有 戏笑我的 在我这里,我眼 常见 他们惹动我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, '愿  主拿凭据给我,自己 为我作保。在你以外谁 肯与我击 掌呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, '因 你使他们 心 不明理,所以 你必不 高举他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, '控告 他的朋友、以朋友为可抢夺的,连他儿女 的眼睛 也要失明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, '神使我作了 民 中的笑谈;他们也 吐唾沫在 我脸上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, '我的眼睛 因忧愁 昏花;我的百 体 好像影儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, '正直人 因 此 必惊奇;无辜的人 要兴起 攻击 不敬虔之辈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, '然而,义人 要持守 所行的道;手 洁 的人要力上加 力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, '至于  你们众人,可以 再 来辩论吧!你们中间,我找 不著 一个智慧人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, '我的日子 已经过了;我的谋算、我心 所想望 的已经断绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, '他们以黑夜 为 白昼,说:亮光 近乎 黑暗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, '我若 盼望 阴间 为我的房屋,若下 榻 在黑暗中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, '若对朽坏 说:你 是我的父;对虫说:你是我的母亲 姊妹; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, '这样,我的指望 在哪里呢?我所指望的 谁 能看见呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, '等到安息 在 尘土中,这指望必下到 阴间 的门闩那里了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, '书亚人 比勒达 回答 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, '你寻 索 言语 要到 几时呢?你可以揣摩思想,然后 我们就说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, '我们为何 算为 畜生,在你眼中 看作污秽呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, '你这恼怒 将自己 撕裂的,难道大地 为你 见弃、磐石 挪开  原处吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, ' 恶人 的亮光 必要熄灭;他的火 焰 必不 照耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, '他帐棚 中的亮光 要变为黑暗;他以上 的灯 也必熄灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, '他坚强的 脚步 必见狭窄;自己的计谋 必将他绊倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, '因为 他被自己的脚 陷入 网中,走 在 缠人的网罗上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, '圈套 必抓住 他的脚跟;机关 必擒获 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, '活扣 为他藏 在土内;羁绊 为他藏在 路上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, '四面 的惊吓 要使他害怕,并且追赶 他的脚跟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, '他的力量 必 因饥饿衰败;祸患 要在他旁边 等候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, '他本身的 肢体 要被吞吃;死亡 的长子 要吞吃 他的肢体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, '他要从所倚靠 的帐棚 被拔出来,带到 惊吓 的王那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, '不 属他的 必住 在他的帐棚里;硫磺 必撒 在 他所住之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, '下边,他的根本 要枯干;上边,他的枝子 要剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, '他的记念 在 地上 必然灭亡;他的 名字 在 街 上 也不存留。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, '他必从光明 中被撵 到 黑暗里,必被赶出 世界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, '在本民 中必无 子 无 孙;在寄居之地 也无一人 存留。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, '以后来的 要惊奇 他的日子,好像以前去的 受了 惊骇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, '不义之人 的住处 总是 这样;此乃 不 认识 神 之人的地步。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, '约伯 回答 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, '你们搅扰 我的心,用言语 压碎我 要到 几时呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, '你们这 十 次 羞辱我;你们苦待 我 也不 以为耻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, '果 真 我有错,这错 乃是在 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, '你们果 然 要向我 夸大,以我的羞辱 为证指责 我, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, '就该 知道 是 神 倾覆 复我,用网罗 围绕 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, ' 我因委曲 呼叫,却不 蒙应允;我呼求,却不得 公断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, '神用篱笆拦住 我的道路,使我不得 经过;又使 我的路径 黑暗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, '他剥去 我的荣光,摘去 我头上 的冠冕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, '他在四围 攻击我,我便归于 死亡,将我的指望 如树 拔出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, '他的忿怒 向我 发作,以我为 敌人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, '他的军旅 一齐 上来,修筑 战 路 攻击我,在我帐棚 的四围 安营。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, '他把我的弟兄 隔 在远处,使我所认识的 全然 与我 生疏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, '我的亲戚 与我断绝;我的密友 都忘记我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, '在我家 寄居的,和我的使女 都以我为 外人;我在他们眼中 看为 外邦人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, '我呼唤 仆人,虽用 口 求 他,他还是不 回答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, '我口的气味,我妻子 厌恶;我的恳求,我同胞也憎嫌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, '连小孩子 也 藐视 我;我若起来,他们都嘲笑 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, '我的密 友 都 憎恶我;我平日所 爱 的人向我 翻脸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, '我的皮 肉 紧贴 骨头;我只剩牙 皮 逃脱了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, '我朋友啊, 可怜我!可怜我!因为 神 的手 攻击 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, '你们为什么 仿佛 神 逼迫我,吃我的肉 还以为不 足呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, '惟 愿  我的言语 现在 写上, 都记录 在书上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, '用铁 笔 镌刻,用铅 灌在磐石上,直存到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, '我 知道 我的救赎主 活著,末了 必站立 在 地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, '我这 皮肉 灭绝 之后,我必在肉体 之外得见 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, ' 我 自己 要见他,亲眼 要看他,并不 像外人。我的心肠 在我里面 消灭了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, '你们若 说:我们逼迫 他 要何等地重呢?惹事 的根 乃在乎 他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, '你们 就当惧怕 刀剑;因为 忿怒 惹动刀剑 的刑罚,使 你们知道有报应(原文是审判)。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, '拿玛人 琐法 回答 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, ' 我心中 急躁,所以 我的思念 叫我回答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, '我已听见 那羞辱我,责备我的话;我的悟性 叫我回答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, '你岂不 知 亘古以来,自从 人 生 在 地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, ' 恶人 夸胜 是暂时的,不敬虔人 的喜乐 不过 转眼之间吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, '他的尊荣 虽 达到 天上,头 虽顶到 云中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, '他终必 灭亡,像自己的粪一样;素来见 他的人要说:他在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, '他必飞去 如梦,不再 寻见,速被赶去,如夜间 的异象。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, '亲眼 见过他的,必不 再见他;他的本处 也再 见 不著他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, '他的儿女 要求穷人 的恩;他的手 要赔还 不义之财。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, '他的骨头 虽然有 青年之力,却要和他 一同躺卧 在 尘土中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, '他口内 虽 以恶 为甘甜,藏 在舌头 底下, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, '爱恋 不 舍,含在 口 中; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, '他的食物 在肚里 却要化为酸,在他里面 成为虺蛇 的恶毒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, '他吞了 财宝,还要吐出; 神 要从他腹中 掏出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, '他必吸饮 虺蛇 的毒气;蝮蛇 的舌头 也必杀他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, '流 奶 与 蜜 之河,他不得 再见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, '他劳碌得来的 要赔还,不得享用(原文是吞下);不能 照所得的 财货 欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, ' 他欺压 穷人,且又离弃;强取 非 自己所盖 的房屋(或译:强取房屋不得再建造)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, '他因 贪 而无 厌,所喜悦的 连一样也不能 保守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, '其余 馀的 没有 一样他不吞灭,所以 他的福乐 不能 长久。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, '他在满足 有余 馀的时候,必到狭窄的地步;凡受苦楚的人 都 必加 手在他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, '他正 要充满 肚腹的时候, 神必将猛烈的 忿怒 降 在他身上;正在他吃饭的时候,要将这忿怒像雨降 在他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, '他要躲避 铁 器;铜 弓 的箭要将他射透。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, '他把箭一抽,就从他身上 出来;发光的箭头 从他胆中 出来,有惊惶 临在他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, '他的财宝 归于  黑暗;人所不 吹 的火 要把他烧灭,要把他帐棚中 所剩下的 烧毁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, '天 要显明 他的罪孽;地 要兴起 攻击他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, '他的家 产 必然过去; 神发怒 的日子,他的货物都要消灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, '这 是恶 人从 神 所得的分,是 神 为他所定 的产业。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, '约伯 回答 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, '你们要细 听 我的言语,就 算是 你们安慰我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, '请宽容我,我 又要说话;说了 以后,任凭你们嗤笑吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, '我 岂是向人 诉冤? 为何 不 焦急呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, '你们要看著 我 而惊奇,用 手 摀 口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, '我每逢 思想,心就惊惶,浑 身 战 兢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, '恶人 为何 存活,享大寿数, 势力 强盛呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, '他们眼见 儿孙,和他们 一同 坚立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, '他们的家宅 平安 无惧; 神 的杖 也不 加在他们身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, '他们的公牛 孳生 而不 断绝;母牛 下犊 而不 掉胎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, '他们打发 小孩子出去,多如羊群;他们的儿女 踊跃跳舞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, '他们随著 琴 鼓歌唱,又因箫 声 欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, '他们度 日 诸事亨通,转眼 下入 阴间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, '他们对 神 说:离开  我们吧!我们不 愿  晓得 你的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, '全能者 是谁, 我们何必事奉他呢?求告 他 有什么 益处呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, '看哪,他们亨通 不 在乎自己;恶人 所谋定的 离我 好远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, '恶人 的灯 何尝 熄灭?患难 何尝临 到他们呢? 神何尝发怒,向他们分散 灾祸呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, ' 他们何尝像风 前 的碎秸,如暴风 刮去 的糠秕呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, '你们说: 神 为恶人的儿女 积蓄 罪孽;我说:不如本人 受报,好使他亲自知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, '愿 他亲眼 看见 自己败亡,亲自饮 全能者 的忿怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, '他的岁月 既尽,他还 顾 他本家吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, '神 既审判 那在高位的,谁能将知识 教训 他呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, '有人 至死 身体强壮,尽 得平靖 安逸; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, '他的奶 桶 充满,他的骨 髓 滋润。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, '有人 至死 心中 痛苦,终身未 尝 福乐的滋味; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, '他们一样 躺卧 在 尘土中,都被虫子 遮盖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, ' 我知道 你们的意思,并诬害 我 的计谋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, ' 你们说:霸者 的房屋 在哪里?恶人 住过的 帐棚 在哪里? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, '你们岂没有 询问 过 路的人吗?不 知道 他们所引的证据吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, '就是 恶人 在祸患 的日子 得存留,在发怒 的日子 得逃脱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, '他所行的,有谁 当 面 给他说明?他 所做的,有谁 报应 他呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, '然而他 要被抬 到茔地;并有人看守 坟墓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, '他 要以谷中 的土块 为甘甜;在他以先 去的无 数,在他以后 去的更多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, '你们对答 的话中既都 错谬,怎么 徒然 安慰我呢?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, '提幔人 以利法 回答 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, '人岂能使 神 有益呢?智慧人 但 能有益 于 己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, ' 你为人公义,岂叫全能者 喜悦呢? 你行为 完全,岂能 使他得利呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, '岂是因你敬畏他 就责备你、 审判 你吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, '你的罪恶 岂不是 大吗?你的罪孽 也没有 穷尽; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, '因 你无故 强取弟兄 的物为当头,剥去 贫寒人 的衣服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, '困乏的人,你没有 给他水 喝;饥饿的人,你没有给 他食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, '有能力的 人 就得地土;尊贵的人 也住 在其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, '你打发 寡妇 空手回去,折断 孤儿 的膀臂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, '因 此,有网罗 环绕你,有恐惧 忽然 使你惊惶; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, '或有 黑暗 蒙蔽你,并有洪 水 淹没你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, '神 岂不是 在高 天吗?你看 星宿 何其 高呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, '你说: 神 知道 什么?他岂能看透 幽暗 施行审判呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, '密云 将他 遮盖,使他不能 看见;他周游 穹 苍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, '你要依从 上古的 道吗?这道 是恶 人 所行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, '他们 未到 死期,忽然除灭;根基 毁坏,好像被江河冲去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, '他们向 神 说:离开  我们吧!又说:全能者 能把 我们 怎么样呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, '哪知 神 以美物 充满 他们的房屋;但恶人 所谋定 的离我 好远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, '义人 看见 他们的结局就欢喜;无辜的人 嗤笑 他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, '说:那起来攻击我们的 果然 被剪除,其余 馀的 都被火 烧灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, ' 你要认识 神,就得平安;福气 也必临 到你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, '你当 领受 他口中 的教训,将他的言语 存 在心里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, '你若 归 向 全能者,从你帐棚中 远除 不义,就必得建立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, '要将你的珍宝 丢 在 尘土里,将俄斐 的黄金丢在溪河 石头之间; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, '全能者 就必为 你的珍宝,作你的 宝 银。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, ' 你就 要以 全能者 为喜乐,向 神 仰起 脸来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, '你要祷告 他,他就听你;你也要还 你的愿 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, '你定意要做 何事,必然给你 成就;亮光 也必照耀 你的路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, ' 人使你降卑,你仍可说:必得高升;谦卑的 人, 神必然拯救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, '人非 无辜, 神且要搭救他;他因你手中 清洁,必蒙拯救。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, '约伯 回答 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, ' 如今 我的哀告 还算为悖逆;我的责罚 比 我的唉哼 还重。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, '惟 愿  我能知道 在哪里可以寻见 神,能到 他的台前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, '我就在他面前 将我的案件 陈明,满 口 辩白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, '我必知道 他回答 我的言语,明白 他向我 所说 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, '他岂用大 能 与我 争辩吗?必不这样!他 必 理会 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, '在他那里 正直人 可以与他 辩论;这样,我必永远 脱离 那审判我的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, '只是,我往前 行,他不在那里,往后退,也不能 见 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, '他在左边 行事,我却不能 看见,在右边 隐藏,我也不能 见他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, '然而 他知道 我 所行的路;他试炼我之后,我必 如精金。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, '我脚 追随 他的步履;我谨守 他的道,并不 偏离。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, '他嘴唇 的命令,我未曾 背弃;我看重 他口中 的言语,过于 我需用的饮食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, '只是他 心志已定,谁 能使他转意呢?他心里 所愿 的,就行出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, '他向我所定的,就必 做成;这类的事 他还有 许多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, '所以 我在他面前 惊惶;我思念 这事便惧怕 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, '神 使我 丧胆;全能者 使我惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, ' 我的恐惧 不是 因为 黑暗,也不是因为幽暗 蒙蔽 我的脸。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, '全能者 既 定 期罚恶,为何 不 使认识 他的人看见 那日子呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, '有人挪移 地界,抢夺 群畜 而牧养。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, '他们拉去 孤儿 的驴,强取寡妇的 牛 为当头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, '他们使 穷人 离开 正道;世上的 贫民 尽都 隐藏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, ' 这些贫穷人如同野驴 出到 旷野,殷勤 寻找 食物;他们 靠著野地 给儿女 糊口, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, '收割 别人田间 的禾稼,摘取 恶人 余 馀剩的葡萄, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, '终夜 赤身 无 衣,天气寒冷 毫无 遮盖, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, '在山上 被大雨 淋湿,因没有 避身之处 就挨近 磐石。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, '又有人从母怀中 抢夺 孤儿,强取 穷人 的衣服为当头, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, '使人赤身 无 衣,到处流行,且因饥饿 扛抬 禾捆, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, '在那些人的围墙 内 造油,醡 酒,自己还口渴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, '在多民的城内 有人 唉哼,受伤的 人 哀号; 神 却不 理会 那恶人的愚妄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, '又有人 背弃 光明,不 认识 光明的道,不 住 在光明的路上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, '杀人的 黎明 起来,杀害 困苦 穷乏人,夜间 又作 盗贼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, '奸夫 等候 黄昏,说:必无 眼 能见我,就把 脸 蒙蔽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, '盗贼黑夜 挖 窟窿;白日 躲藏,并不 认识 光明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, ' 他们 看早晨 如 幽暗,因为 他们晓得 幽暗 的惊骇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, '这些恶人犹如浮萍 快快飘去。他们所得的分 在世上 被咒诅;他们不得 再走 葡萄园 的路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, '干旱 炎热 消没 雪 水;阴间 也如此消没犯罪之辈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, '怀他的母(原文是胎)要忘记他;虫子要吃他,觉得甘甜;他不 再 被人记念。不义的人 必如树 折断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, '他恶待(或译:他吞灭)不怀孕 不 生养的妇人,不 善待 寡妇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, '然而 神用能力 保全 有势力的人;那性命 难 保的 人仍然兴起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, '神使 他们 安稳,他们就有所倚靠; 神的眼目 也看顾 他们的道路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, '他们被高举,不过片时 就没有了;他们降为卑,被除灭,与众人一样,又如谷 穗 被割。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, '若 不是 这样,谁 能证实我是说谎的,将我的言语 驳为 虚空呢?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, '书亚人 比勒达 回答 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, '神有 治理之权,有威严可畏;他在高处 施行 和平。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, '他的诸军 岂能 数算?他的光亮 一发, 谁 不蒙照呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, '这样在 神面前,人 怎能 称义?妇人 所生的 怎能 洁净? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, '在 神眼前,月亮 也 无 光亮,星宿 也不 清洁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, '何况 如虫 的人,如蛆 的世人呢!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, '约伯 回答 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, '无 能 的人蒙你何等 的帮助!膀臂 无 力 的人蒙你何等的拯救! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, '无 智慧 的人蒙你何等 的指教!你向他多 显 大知识! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, '你向 谁 发出 言语来?谁 的灵 从你 而出? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, '在大水 和水族 以下 的阴魂 战 兢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, '在 神面前,阴间 显露;灭亡 也不得 遮掩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, '神将北极 铺 在 空中,将大地 悬 在 虚空; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, '将水 包 在密云中,云 却不 破裂; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, '遮蔽 他的宝座,将云 铺 在其上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, '在 水 面 的周围 划 㓰出界限,直到 光明 黑暗 的交界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, '天 的柱子 因他的斥责 震动 惊奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, '他以能力 搅动(或译:平静)大海;他藉 借知识 打伤 拉哈伯, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, '藉 借他的灵 使天 有妆饰;他的手 刺杀 快 蛇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, '看哪,这不过是 神工作 的些微;我们所听 于 他 的是何等 细微的 声音!他大能的 雷声 谁 能明透呢?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, '约伯 接著 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, '神夺去 我的理,全能者 使我心中 愁苦。我指著永生的 神起誓: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, ' 我的生命 尚 在我里面; 神 所赐呼吸之气 仍在我的鼻孔内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, '我的嘴 决不 说 非义之言;我的舌 也不 说 诡诈之语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, '我 断不 以你们 为是;我至 死 必不 以自己 为不 正! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, '我持定 我的义,必不 放松;在世的日子,我心 必不 责备我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, '愿  我的仇敌 如恶人一样;愿 那起来攻击我的,如不义之人一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, '不敬虔的人 虽然 得利, 神 夺取 其命 的时候还有 什么 指望呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, ' 患难 临 到他, 神 岂能听 他的呼求? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, '他岂 以 全能者 为乐,随 时 求告 神呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, '神 的作为,我要指教 你们;全能者 所行的,我也不 隐瞒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, ' 你们 自己也都 见过,为何 全然 变为虚妄呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, '神 为 恶 人 所定的分,强暴人 从全能者 所得的报(原文是产业)乃是这样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, '倘或 他的儿女 增多,还是 被刀所杀;他的子孙 必不得 饱 食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, '他所遗留 的人必死 而埋葬;他的寡妇 也不 哀哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, '他虽 积蓄 银子 如尘沙,预备 衣服 如泥土; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, '他只管预备,义人 却要穿上;他的银子,无辜的人 要分取。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, '他建造 房屋 如虫做窝,又如守望者 所搭的 棚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, '他虽富足 躺卧,却不 得收殓,转眼之间 就不在了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, '惊恐 如波涛 将他追上;暴风 在夜间 将他刮去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, '东风 把他飘去,又刮 他离开  本处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, '神要向他 射箭,并不 留情;他恨不得逃脱 神的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, '人要向他 拍 掌,并要发叱声,使他 离开 本处。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, ' 银子 有 矿;炼 金 有方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, '铁 从地里 挖出;铜 从石 中镕化。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, '人为黑暗 定 界限, 查究 幽暗 阴翳 的石头,直到极 处, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, '在无人 居住 之处刨开  矿穴,过路的人 也想 不到他们;又与人远离,悬 在空中摇来摇去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, '至于  地,能出 粮食,地内 好像 被火 翻起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, '地中 的石头 有蓝宝石,并有 金 沙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, '矿中的路 鸷鸟 不得 知道;鹰 眼 也未 见过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, '狂傲的 野兽 未 曾行过;猛烈的狮子 也未 曾经过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, '人伸 手 凿开  坚石,倾倒 山 根, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, '在磐石中 凿出 水道,亲眼 看见 各样 宝物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, '他封闭 水 不得滴流,使隐藏的物 显露 出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, '然而,智慧 有何处 可寻?聪明 之处 在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, '智慧的价值 无 人 能知,在活人 之地 也无 处可寻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, '深渊 说: 不 在我内;沧海 说:不 在我中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, '智慧非 用 黄金 可得,也不能 平 白银 为它的价值。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, '俄斐 金 和贵重的 红玛瑙,并蓝宝石,不 足与较量; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, '黄金 和玻璃 不 足与比较;精金的 器皿 不足与兑换。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, '珊瑚、水晶 都不 足论;智慧 的价值胜过珍珠(或译:红宝石)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, '古实 的红璧玺 不 足与比较;精 金 也不 足与较量。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, '智慧 从何处 来呢?聪明 之处 在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, '是向一切 有生命的 眼目 隐藏,向空中的 飞鸟 掩蔽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, '灭没 和死亡 说:我们 风闻 其名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, '神 明白 智慧的道路, 晓得 智慧的所在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, '因 他 鉴察 直到地 极,遍观 普 天 之下, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, '要为风 定 轻重,又度 量 诸水; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, '他为雨露 定 命令,为雷 电 定道路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, '那时 他看见智慧,而且述说;他坚定,并且 查究。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, '他对人 说: 敬畏 主 就是 智慧;远离 恶 便是聪明。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, '约伯 又 接著 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, '惟 愿  我的景况如从前的 月份,如 神 保守我 的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, '那时他的灯 照 在 我头上;我藉 借他的光 行过 黑暗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, '我愿  如 壮年 的时候:那时我在 帐棚中, 神 待我有密友之情; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, '全能者 仍 与我同在;我的儿女 都环绕我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, '奶 多可洗 我的脚;磐石 为我 出 油 成河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, '我出 到 城 门,在街上 设立 座位; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, '少年人 见 我而回避,老年人 也起身 站立; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, '王子 都停止 说话,用 手 摀口; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, '首领 静默 无声,舌头 贴住 上膛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, ' 耳朵 听我的,就称我有福;眼睛 看我的,便称赞我; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, '因 我拯救 哀求 的困苦人 和无人 帮助 的 孤儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, '将要灭亡 的 为我 祝福;我也使寡妇 心中 欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, '我以公义 为衣服,以公平 为外袍 和冠冕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, '我 为 瞎子的 眼,瘸子的 脚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, '我 为穷乏人的 父;素不 认识的人,我查明 他的案件。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, '我打破 不义之人 的牙床,从他牙齿中 夺了 所抢的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, '我便说:我必死 在家中(原文是窝中),必增添 我的日子,多如尘沙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, '我的根 长 到 水边;露水 终夜 沾在我的枝上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, '我的荣耀 在身上 增新;我的弓 在手中 日强。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, '人听见 我 而仰望,静默 等候 我的指教。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, '我说话 之后,他们就不 再说;我的言语 像雨露滴 在他们身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, '他们仰望 我 如仰望雨,又张开  口 如切慕春雨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, '他们不 敢自信,我就向他们 含笑;他们不 使我脸上 的光 改变。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, '我为他们选择 道路,又坐 首位;我如君王 在军队 中居住,又如 吊丧的安慰 伤心的人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, '但如今,比我 年 少 的人戏笑 我;其人之父 我曾藐视,不肯安 在 看守我羊群 的狗中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, '他们 壮年的气力 既 已衰败,其手 之力 与我 何益呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, '他们因穷乏 饥饿,身体枯瘦,在荒废 凄凉 的幽暗中,龈 干燥之地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, '在 草丛 之中采 咸草,罗腾(小树名,松类)的根 为他们的食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, '他们从 人中 被赶出;人追喊 他们 如贼一般, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, '以致他们住 在荒 谷之间,在地 洞 和岩穴中; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, '在 草丛 中叫唤,在荆棘 下 聚集。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, '这都是 愚顽 下贱人 的儿女;他们被鞭打,赶出 境外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, '现在 这些人以我为 歌曲,以我为 笑谈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, '他们厌恶我,躲 在旁边站著,不 住地 吐唾沫 在我脸上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, ' 松开  他们的绳索 苦待我,在我面前 脱去 辔头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, '这等下流人 在 我右边 起来,推开  我的脚,筑成 战  路 来攻击我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, '这些无人 帮助的,毁坏 我的道,加增 我的灾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, '他们来 如同闯进大 破口,在 毁坏 之间滚在我身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, '惊恐 临 到我,驱逐 我的尊荣 如风;我的福禄 如云 过去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, '现在 我心 极其悲伤;困苦 的日子 将我抓住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, '夜间,我里面 的骨头 刺我,疼痛不 止,好像龈我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, '因 神的大 力,我的外衣 污秽不堪,又如里衣 的领子 将我缠住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, '神把我扔 在淤泥中,我就像 尘土 和炉灰一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, '主啊,我呼求 你,你不 应允我;我站起来,你就定睛看 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, '你向我变心,待我 残忍,又用大 能 追逼我, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, '把我提 在 风中,使我驾风而行,又使我消灭 在烈风中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, ' 我知道 要使我临到 死地,到那为众 生 所定 的阴宅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, '然而,人仆倒 岂不 伸 手?遇灾难 岂不 求救呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, '人遭难,我岂 不 为他哭泣呢?人穷乏,我 岂不为他忧愁呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, ' 我仰望 得好处,灾祸 就到了;我等待 光明,黑暗 便来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, '我心里 烦扰 不 安,困苦的 日子 临到我身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, '我没有 日光 就哀哭 行去(或译:我面发黑并非因日晒);我在会中 站著 求救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, '我与野狗 为 弟兄,与鸵鸟 为同伴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, '我的皮肤 黑 而脱落;我的骨头 因 热 烧焦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, '所以,我的琴音 变为 悲音;我的箫声 变为哭 声。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, '我与眼睛 立 约,怎能 恋恋瞻望 处女呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, '从至上的 神 所得之分,从至高 全能者 所得之业 是什么呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, '岂不是 祸患 临到不义的,灾害 临到作 孽的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, '神 岂不是 察看 我的道路,数点 我的脚步呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, '我若 与 虚谎 同行,脚 若追 随 诡诈; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, '(我若被公道的 天平 称度,使 神 可以知道 我的纯正;) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, '我的脚步 若 偏 离 正路,我的心 若随 著 我的眼目,若有玷污 粘 在我手上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, '就愿 我所种的 有别人 吃,我田所产的 被拔出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, '我 若 受迷惑,向 妇人起淫念,在 邻舍 的门外 蹲伏, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, '就愿 我的妻子 给别人 推磨,别人 也与她 同室。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, '因为 这是 大罪,是 审判官 当罚的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, '这本 是 火 焚烧,直到 毁灭,必拔除 我所有的 家产。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, '我的仆 婢 与我 争辩的时候,我若 藐视 不听他们的情节; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, ' 神 兴起,我怎样 行呢?他察问,我怎样 回答呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, '造 我在腹中的,不也是 造他吗?将他与我抟 在腹中 的岂不是一位吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, '我若 不容 贫寒人 得其所愿 ,或叫寡妇 眼中 失望, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, '或独自 吃 我一点食物,孤儿 没有 与我 同吃; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, '( 从幼年时 孤儿与我同长,好像父子一样;我从出母 腹就扶助(原文是引领)寡妇。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, '我若 见 人因无 衣 死亡,或见穷乏人 身无 遮盖; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, '我若 不 使他 因我羊 的毛 得暖,为我祝福; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, '我若 在城门口 见 有帮助我的,举 手 攻击 孤儿; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, '情愿 我的肩头 从缺盆骨 脱落,我的膀臂 从羊矢骨 折断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, '因 神 降的灾祸 使我 恐惧;因他的威严,我不 能妄为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, '我若 以 黄金 为指望,对精金 说:你是我的倚靠; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, '我若 因 财物 丰裕,因 我手 多 得 资财而欢喜; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, '我若 见 太阳 发光,明 月 行在空中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, '心 就暗暗 被引诱,口 便亲 手; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, '这也 是 审判官 当罚的罪孽,又是 我背弃 在上的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, '我若 见恨我的 遭报 就欢喜, 见他遭 灾 便高兴; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, '(我没有 容 口 犯罪, 咒诅 他的生命;) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, '若 我帐棚 的人 未尝 说,谁 不 以 主人的食物 吃饱呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, '(从来我没有 容客旅 在街上 住宿,却开  门 迎接行路的人;) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, '我若 像亚当(或译:别人)遮掩 我的过犯,将罪孽 藏 在怀中; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, '因 惧怕 大 众,又因宗族 藐视 我使我惊恐,以致闭口无言,杜门 不 出; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, '惟愿  有 一位 肯听 我!(看哪,在这里有我所划 㓰的押,愿 全能者 回答我!) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, '愿 那敌我 者 所写 的状词在我这里!我必 带 在 肩上,又绑 在头上 为冠冕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, '我必向他述说 我脚步 的数目,必如 君王 进到他面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, '我若夺取田地,这地 向我 喊冤,犁沟 一同 哭泣; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, '我若 吃 地的出产 不 给价值,或叫原主 丧 命; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, '愿 这地长 蒺藜 代替 麦子,长恶草 代替 大麦。约伯 的话 说完了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, '于 是这 三个 人,因 约伯 自以为 义 就不再 回答 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, ' 那时有布西人 兰 族 巴拉迦 的儿子 以利户 向约伯 发 怒;因 约伯自 以为义,不以 神为义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, '他又向约伯的三个 朋友 发 怒;因为 他们想 不 出回答的话来,仍以 约伯 为有罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, '以利户 要与 约伯 说话,就等候他们,因为 他们 比自己 年 老。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, '以利户 见 这三个 人 口中 无 话回答,就怒气 发作。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, '布西人 巴拉迦 的儿子 以利户 回答 说:我 年 轻,你们 老迈;因此 我退让,不敢 向你们 陈说 我的意见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, '我说,年老的 当先说话;寿 高 的当以智慧 教训人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, '但 在人 里面有 灵;全能者 的气 使人有聪明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, '尊贵的 不 都有智慧;寿高的 不都能明白 公平。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, '因此 我说:你们要听 我言;我 也要 陈说 我的意见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, ' 你们查究 所要说的话; 那时我等候 你们的话,侧耳 听 你们的辩论, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, '留心 听你们;谁知 你们中间 无 一人折服 约伯,驳倒 他的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, '你们切不可 说:我们寻得 智慧; 神 能胜他,人 却不能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, '约伯没有 向我 争 辩;我也不 用你们的话 回答他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, '他们惊奇 不 再 回答,一言 不发。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, '我岂因 他们不 说话, 站住 不 再 回答,仍旧等候呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, '我 也要 回答 我的一分话, 陈说 我的意见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, '因为 我的言语 满怀;我里面的 灵 激动我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, ' 我的胸怀 如盛酒 之囊没有 出气之缝,又如新 皮袋 快要破裂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, '我要说话,使我 舒畅;我要开  口 回答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, '我必 不 看 人 的情面,也不 奉承 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, ' 我不 晓得 奉承;若奉承,造我的 主必快快 除灭我。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, ' 约伯啊,请 听 我的话,留心听 我一切的 言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, ' 我现在开  口,用 舌 发言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, '我的言语 要发明心中 所存的正直;我所知道的,我嘴唇 要诚实地 说出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, '神 的灵 造我;全能者 的气 使我得生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, '你若 回答我,就站起来,在我面前 陈明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, ' 我在 神 面前与你一样,也 是用土 造成。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, ' 我不 用威严 惊吓你,也不 用势力 重压 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, ' 你所说的,我听见了,也听见 你的言 语,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, '我 是清洁 无 过的,我 是无辜的;在我里面 也没有 罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, ' 神找 机会 攻击我,以我为 仇敌, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, '把我的脚 上了 木狗,窥察 我一切的 道路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, ' 我要回答你说:你这话 无 理,因 神 比世人 更大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, '你为何 与他 争论呢?因 他的事 都 不 对人解说? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, ' 神 说 一次、两次,世人却不 理会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, ' 人 躺 在 床上 沉 睡的时候, 神 就用梦 和夜间 的异象, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, ' 开 通 他们 的耳朵,将当受的教训 印在他们心上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, '好叫人 不从 自己的谋算,不行骄傲的事(原文是将骄傲 向人 隐藏), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, '拦阻 人 不 陷于 坑里, 不死 在刀下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, '人在 床上 被惩治, 骨头 中不住地 疼痛, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, '以致他的口 厌弃 食物,心 厌恶 美味。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, '他的肉 消瘦,不得再见;先前不 见 的骨头 都凸出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, '他的灵魂 临近 深坑;他的生命 近于 灭命的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, ' 一千 天使中,若 有 一个 作传话的与 神同在,指示 人 所当行的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, '神就给他开 恩,说:救赎他 免得下 坑;我已经得了 赎价。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, '他的肉 要比孩童 的肉更嫩;他就返老 还 童。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, '他祷告 神, 神就喜悦他,使他欢呼 朝见 神的面; 神又看 他 为义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, '他在 人 前歌唱 说:我犯了罪,颠倒 是非,这竟与我 无 益。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, '神救赎 我的灵魂 免入 深坑;我的生命 也必见 光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, ' 神两次、三次 向 人 行 这 一切的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, '为要从 深坑 救回 人的灵魂,使他被光 照耀,与活人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, '约伯啊,你当侧耳 听 我的话,不要作声,等我 讲说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, '你若 有 话说,就可以回答我;你只管说,因 我愿  以你为是。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, '若 不然,你 就听 我说;你不要作声,我便将智慧 教训你。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, '以利户 又 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, '你们智慧人 要听 我的话;有知识的人 要留心听 我说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, '因为 耳朵 试验 话语,好像上膛 尝 食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, '我们当选择 何为是,彼此 知道 何 为善。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, ' 约伯 曾说:我是公义, 神 夺去 我的理; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, '我虽有 理,还算为说谎言的;我虽无 过,受的伤 还不能医治。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, '谁 像约伯,喝 讥诮 如同喝水呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, '他与 作 孽 的结 伴,和 恶 人 同行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, ' 他说:人 以 神 为乐,总是无 益。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, '所以,你们明理的 人 要听 我的话。 神 断 不致行恶;全能者 断不致作孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, '他必 按人 所做的 报应 人,使各人 照所行的 得报。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, ' 神 必 不 作恶;全能者 也不 偏离 公平。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, '谁 派 他 治理地, 安定 全 世界呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, '他若 专 心 为己,将灵 和气 收 归自己, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, '凡 有血气的 就必一同 死亡;世人 必仍归 尘土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, '你若 明理,就当听 我的话,留心听 我言语 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, '难道 恨恶 公平 的可以掌权吗?那有公义的、有大能的,岂可 定他有罪吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, '他对君王 说:你是鄙陋的;对 贵臣说:你是邪恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, '他 待王子 不 徇 情面,也不 看重 富足的 过于  贫穷的,因为 都是 他手 所造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, '在转眼之间,半 夜之中,他们就死亡。百姓 被震动 而去世;有权力 的被夺去 非 借人手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, ' 神注目 观看 人 的道路,看明人的 脚步。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, '没有 黑暗、 阴翳 能给作 孽 的藏身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, ' 神 审判人, 不必 使 人 到 他面前再三鉴察。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, '他用难 测 之法打破 有能力的人,设立 别人 代替他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, '他原 知道 他们的行为,使他们在夜间 倾倒 灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, '他在 众人眼前 击打他们,如同 击打恶人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, '因为 他们 偏行 不跟从他,也不 留心 他的道, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, '甚至使贫穷人 的哀声 达 到他那里;他也听了 困苦人 的哀声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, '他 使人安静,谁能扰乱(或译:定罪)呢?他掩 面,谁 能见他呢?无论待 一国 或 一人 都是如此─ ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, '使不虔敬的 人 不得作王,免得有人牢笼 百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, '有谁 对 神 说:我受了责罚,不再 犯罪; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, '我所看 不明的,求你 指教我;我若 作了 孽,必不 再作? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, '他施行报应,岂要随你的心愿 、叫 你推辞不受吗? 选定 的是你,不是 我。你所 知道的 只管说吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, '明理的 人 和听 我 话的智慧 人 必对我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, '约伯 说话 没有 知识,言语 中毫无 智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, '愿  约伯 被试验 到 底,因 他回答 像恶 人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, ' 他在 罪 上又加 悖逆;在我们中间 拍手,用许多 言语轻慢 神。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, '以利户 又说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, ' 你以为 有理,或以为 你的公义胜于  神的公义, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, '才 说 这与我 有什么 益处?我不犯罪 比犯罪有什么 好处呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, '我 要回 答 你和 在你 这里的朋友。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, '你要向天 观看,瞻 望 那高 于 你 的穹苍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, '你若 犯罪,能使 神 受何害呢?你的过犯 加增,能使 神 受何损呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, '你若 是公义,还能加增 他 什么呢? 他从你手里 还接受 什么呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, '你的过恶 或能害你这类 的人;你的公义 或能叫世人得益处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, '人因多 受欺压 就哀求,因受能者的辖制(原文是膀臂)便求救, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, '却无人 说:造我的 神 在哪里?他使 人夜间 歌唱, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, '教训我们 胜于 地上 的走兽,使我们有聪明 胜于 空中的 飞鸟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, '他们在那里,因 恶人 的骄傲 呼求,却无人 答应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, '虚妄的呼求, 神 必 不 垂听;全能者 也必不 眷顾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, '何况 你说,你不 得见他;你的案件 在他面前,你等候 他吧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, '但如今 因 他未 曾发怒 降罚,也不 甚 理会 狂傲, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, '所以约伯 开  口 说虚妄的话,多发 无 知识 的言语。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, '以利户 又接著 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, '你再容 我 片时,我就指示你,因 我还有话为 神 说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, '我要将所知道的 从远处 引来,将公义 归给 造我的主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, ' 我的言语 真 不 虚谎;有知识 全备的 与你同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, ' 神 有大能,并不 藐视人;他的智慧 甚 广。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, '他不 保护恶人 的性命,却为困苦人 伸 冤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, '他时常 看顾 义人,使他们和 君王 同坐 宝座,永远 要被高举。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, '他们若 被锁链 捆住,被苦难的 绳索 缠住, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, '他就把他们的作为 和过犯 指示 他们,叫 他们知道有骄傲的行动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, '他也开 通 他们的耳朵 得受教训,吩咐 他们离开 罪孽 转回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, '他们若 听从 事奉他,就必度 日 亨通,历年 福乐; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, '若 不 听从,就要被刀 杀灭,无 知无识 而死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, '那心中 不敬虔的人 积蓄 怒气; 神捆绑他们,他们竟不 求救; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, ' 必在青年时 死亡,与污秽人 一样丧命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, '神藉 借著困苦 救拔 困苦人,趁他们受欺压 开 通 他们的耳朵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, '神也必 引你 出离 患难,进入宽阔 不 狭窄 之地;摆在 你席上 的必满有 肥甘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, '但你满口有 恶人 批评的言语;判断 和刑罚 抓住你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, '不可 容 忿怒触动你,使你不服 责罚;也不可 因赎价 大 就偏行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, '你的呼求(或译:资财),或是你一切的 势力,果有灵验,叫你不 受患难吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, '不要 切慕 黑夜,就是众民 在本处 被除灭的时候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, '你要谨慎,不可 重看 罪孽,因 你选择罪孽 过于 选择苦难。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, ' 神 行事有高大的 能力;教训 人的有谁 像他呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, '谁 派定 他 的道路?谁 能说:你所行的 不义? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, '你不可忘记 称赞他所行的 为大,就是 人 所歌颂的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, '他所行的,万 人 都看见;世人 也从远处 观看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, ' 神 为大,我们不能 全知;他的年 数 不能 测度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, ' 他吸取 水 点,这水点从云雾 中就变成 雨; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, '云彩 将雨 落下,沛然 降 与 世人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, '谁能 明白 云彩 如何铺张,和 神行宫 的雷声呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, ' 他将亮光 普照 在自己的四围;他又遮覆 复 海 底。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, ' 他用这些 审判 众民,且赐 丰富的 粮食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, '他以 电光 遮 手,命 闪电 击中敌人(或译:中了靶子)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, '所发的雷声 显明 他的作为,又 向牲畜 指明 要起暴风。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, ' 因此 我心 战 兢,从原处 移动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, '听啊, 神轰轰的 声音 是他口中 所发的 响声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, '他 发 响声震遍 天 下,发电光 闪到 地 极。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, '随后 人听见 有雷 声 轰轰,大发威严,雷电 接连不 断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, '神 发出 奇妙的 雷声;他行 大事,我们不能 测透。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, ' 他对雪 说:要降在 地上;对大 雨 和暴 雨也是这样说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, '他封住 各 人 的手,叫所造的万 人 都晓得 他的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, '百兽 进 入 穴中,卧 在洞内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, '暴风 出 于  南宫;寒冷 出于 北方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, '神 嘘气 成 冰;宽阔之 水 也都凝结。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, ' 他使密云 盛满 水气,布散 电光 之云; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, '这云 是藉 借他的指引 游行 旋转,得以在 全 地 面上 行 他一切 所 吩咐的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, '或 为 责罚,或 为润地,或 为施行慈爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, '约伯啊,你要留心听,要站立 思想 神 奇妙的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, '神 如何吩咐 这些,如何使云中 的电光 照耀,你知道吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, '云彩 如何浮于  空中,那知识 全备者 奇妙的作为,你知道吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, '南风 使地 寂静,你的衣服 就如 火热,你知道吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, '你岂能与 神 同铺 穹苍吗?这穹苍坚硬,如同铸成的 镜子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, '我们 愚昧 不能 陈说;请你指教我们 该对他 说 什么话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, '人岂可说: 我愿 与他 说话?岂 有人 自愿  灭亡吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, '现在有云遮蔽,人不 得见 穹苍的 光 亮;但风 吹过,天又发晴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, '金光 出 于 北方,在 神 那里有可怕的 威严。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, '论到全能者,我们不能 测度;他大有 能力,有公平 和大 义,必不 苦待人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, '所以,人 敬畏他;凡 自以为心中 有智慧的人,他都不 顾念。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, '那时,耶和华 从 旋风中 回答 约伯 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, '谁 用无 知的 言语 使我的旨意 暗昧不明? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, '你要 如勇士 束 腰;我问你,你可以指示我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, '我立 大地 根基的时候,你在 哪里呢?你若 有 聪明,只管说吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, '你若 晓得就说,是谁 定 地的尺度?是 谁 把准绳 拉 在其上? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, '地的根基 安置 在 何处? 地的角 石 是谁 安放的? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, '那时,晨 星 一同 歌唱; 神 的众 子 也都欢呼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, '海水 冲出,如出 胎胞,那时谁将它 关闭呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, '是我用 云彩 当海的衣服,用幽暗 当包裹它的布, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, '为它 定 界限,又安 门 和闩, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, '说:你只可到 这里,不可 越过;你狂傲的 浪 要到此 止住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, '你自生以来,曾命定 晨光,使清晨的日光 知道 本位, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, '叫这光普照 地 的四极,将恶人 从其中 驱逐出来吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, '因这光,地面改变 如泥 上印印,万物出现 如 衣服一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, '亮光 不照 恶人;强横的 膀臂 也必折断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, '你曾进 到 海 源,或在深渊 的隐密处 行走吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, '死亡 的门 曾向你 显露吗?死荫 的门 你曾见过吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, '地 的广大 你能明 透吗?你若 全 知道,只管说吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, '光明 的居所 从何 而至?黑暗 的本位 在于 何处? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, ' 你能带 到 本境, 能看明 其室 之路吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, '你总知道,因为 你早 已生在世上,你日子 的数目 也多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, '你曾进 入 雪 库,或见过 雹 仓吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, '这雪雹乃是我为 降灾,并打仗 和争战  的日子 所预备的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, '光亮 从何 路 分开 ?东风 从何路分散 遍 地? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, '谁 为雨水 分 道?谁为雷 电 开 路? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, '使雨降 在 无 人 之地、无 人 居住 的旷野? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, '使荒废 凄凉 之地得以丰足,青草 得以发生? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, '雨 有 父吗? 露水 珠 是谁 生的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, '冰 出于  谁 的胎?天上的 霜 是谁 生的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, '诸水坚硬(或译:隐藏)如石头;深渊 之面 凝结成冰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, '你能系住 昴星 的结吗? 能解开  参星 的带吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, '你能按时 领出 十二宫吗?能引导 北斗 和随它的众星(星:原文是子)吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, '你知道 天 的定例吗?能 使地 归 在天的权下吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, '你能向云彩 扬起 声来,使倾盆的 雨 遮盖你吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, '你能发出 闪电,叫它行去,使它对你 说:我们在这里? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, '谁 将智慧 放 在怀中? 谁 将聪明 赐 于 心内? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, '谁 能用智慧 数算 云彩呢?尘土 聚集 成团,土块 紧紧结连;那时,谁 能倾倒 天上的 瓶呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, ' 母狮子 在洞 中蹲伏,少壮狮子 在隐密处 埋伏;你能为牠们抓取 食物,使牠们饱 足吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, '乌鸦之 雏 因 无 食物 飞来飞去,哀告 神;那时,谁 为牠预备 食物呢?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, '山岩间 的野山羊 几时 生产,你知道吗?母鹿 下犊之期,你能察定吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, '牠们怀胎 的月数,你能数算吗?牠们几时 生产,你能晓得吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, '牠们屈身,将子 生下,就除掉 疼痛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, '这子 渐渐肥壮,在荒野 长大,去 而不 回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, '谁 放野驴 出去 自由?谁 解开  快驴 的绳索? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, '我使 旷野 作牠 的住处,使咸地 当牠的居所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, '牠嗤笑 城 内的喧嚷,不 听 赶牲口 的喝声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, '遍 山 是牠的草场;牠寻找 各样 青绿之物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, '野牛 岂肯 服事你?岂 肯住 在 你的槽旁? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, '你岂能用套绳 将野牛 笼在 犁沟之间?牠岂 肯随你 耙 山谷之地? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, '岂可因 牠的力 大 就倚靠 牠?岂可把你的工 交 给牠做吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, '岂可信靠 牠 把你的粮食 运到家,又收聚 你禾场上的谷吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, '鸵鸟的 翅膀 欢然搧展,岂是 显慈爱的 翎毛 和羽毛吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, '因 牠把蛋 留 在地上,在 尘土 中使得温暖; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, '却想不到 被脚 踹碎,或被野 兽 践踏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, '牠忍心 待雏,似乎不是 自己的;虽然徒 受劳苦,也不 为雏惧怕; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, '因为 神 使牠没有 智慧,也未 将悟性 赐 给牠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, '牠几时 挺身 展开 翅膀,就嗤笑 马 和骑马的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, '马 的大力 是你所赐的吗?牠颈项 上挓挲的鬃 是你给牠披上的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, '是你叫牠跳跃 像蝗虫吗?牠喷气 之威 使人惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, '牠在谷中 刨地,自喜 其力;牠出去 迎接 佩带兵器的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, '牠嗤笑 可怕的事 并不 惊惶,也不 因 刀剑 退回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, '箭袋 和发亮的 枪,并短枪 在牠身上 铮铮有声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, '牠发猛烈的 怒气 将地 吞下;一 听角 声 就不 耐站立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, '角 每发声,牠说 呵哈;牠从远处 闻著 战 气,又听见军长 大发雷声 和兵丁呐喊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, '鹰雀 飞翔,展开  翅膀 一直向南,岂是藉 借你的智慧吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, '大鹰 上腾 在高处搭 窝,岂是 听 你的吩咐吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, '牠住 在山岩,以 山 峰 和坚固之所 为家, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, '从那里 窥看 食物,眼睛 远远 观望。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, '牠的雏 也咂 血;被杀的人 在哪里,牠 也在那里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, '耶和华 又 对 约伯 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, '强辩的 岂可与 全能者 争论吗?与 神 辩驳 的可以回答这些吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, '于 是,约伯 回答 耶和华 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, ' 我是卑贱的!我用什么 回答你呢?只好用 手 摀 口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, '我说了 一次,再不 回答;说了两次,就不 再说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, '于 是,耶和华 从 旋风 中回答 约伯 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, '你要 如勇士 束 腰;我问你,你可以指示我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, '你岂可 废弃 我所拟定的?岂可定我有罪,好 显自己为义吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, ' 你有 神 那样的膀臂吗?你能像他 发雷 声吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, '你要 以荣耀 庄严 为妆饰,以尊荣 威严 为衣服; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, '要发出 你满溢的 怒气,见 一切 骄傲的人,使他降卑; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, '见 一切 骄傲的人,将他制伏,把恶人 践踏 在本处; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, '将他们一同 隐藏 在尘土中,把他们的脸 蒙蔽 在隐密处; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, '我 就 认 你右手 能以救 自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, '你且 观看 河马; 我造 你也造牠。牠吃 草 与牛一样; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, ' 牠的气力 在腰间,能力 在肚腹 的筋上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, '牠摇动 尾巴 如 香柏树;牠大腿 的筋 互相联络。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, '牠的骨头 好像铜 管;牠的肢体 仿佛铁 棍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, '牠在 神 所造的物中 为首;创造牠的 给 牠刀剑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, ' 诸山 给牠 出 食物,也是 百 兽 游玩 之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, '牠伏 在莲叶 之下,卧在芦苇 隐密处 和水洼子里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, '莲叶 的阴凉 遮蔽牠;溪旁 的柳树 环绕牠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, ' 河水 泛滥,牠不 发战 ;就是 约旦河 的水涨 到 牠口边,也是安然。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, '在牠防备的时候,谁能捉拿牠?谁能牢笼 牠穿 牠的鼻子呢?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, '你能用鱼钩 钓上 鳄鱼吗?能用绳子 压下 牠的舌头吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, '你能用绳索 穿 牠的鼻子吗?能用钩 穿 牠的腮骨吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, '牠岂 向你 连连 恳求, 说 柔和的话吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, '岂肯与你 立 约,使你拿 牠永远 作奴仆吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, '你岂可拿牠 当雀鸟 玩耍吗?岂可为你的幼女 将牠拴住吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, '搭伙 夥 的渔夫岂可拿牠 当货物吗?能把牠分 给 商人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, '你能用倒钩枪 扎满 牠的皮,能用鱼 叉 叉满牠的头吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, '你按 手 在牠身上,想 与牠争战 ,就不 再这样行吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, ' 人指望 捉拿牠是徒然的;一 见牠,岂不 丧胆吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, '没有 那么凶猛 的人敢 惹牠。这样,谁 能 在我面前 站立得住呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, '谁 先给我什么,使我偿还呢?天 下 万物 都是 我的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, '论到 鳄鱼的肢体 和其大力,并美好的 骨骼,我不能 缄默不言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, '谁 能剥 牠的外 衣?谁 能进 牠上下 牙骨之间呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, '谁 能开  牠的腮 颊?牠牙齿 四围 是可畏的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, '牠以坚固的鳞甲 为可夸,紧紧合闭,封得 严密。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, '这鳞甲一 一 相连,甚至气 不得 透入 其间, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, '都是互相 联络、胶结,不能 分离。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, '牠打喷嚏 就发出 光来;牠眼睛 好像早晨的光线 缐(原文是眼皮)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, '从牠口中 发出 烧著的火把,与飞迸的 火 星; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, '从牠鼻孔 冒出 烟来,如烧开 的 锅 和点著的芦苇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, '牠的气 点著 煤炭,有火焰 从牠口中 发出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, '牠颈项 中存著 劲力;在牠面前 的都恐吓 蹦跳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, '牠的肉 块 互相联络,紧贴 其身,不能 摇动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, '牠的心 结实 如 石头,如下 磨石 那样结实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, '牠一起来,勇士 都惊恐,心里慌乱,便都昏迷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, '人若用刀,用枪,用标枪,用尖枪 扎牠,都是无 用。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, '牠以 铁 为干草,以铜 为烂 木。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, '箭 不能 恐吓牠使牠逃避;弹 石 在牠 看 为碎秸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, '棍棒 算为 禾秸;牠嗤笑 短枪 飕的响声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, '牠肚腹下 如尖 瓦片;牠如钉耙 经过 淤泥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, '牠使深渊 开 滚 如锅,使 洋海 如锅中的膏油。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, '牠行的路 随后 发光,令人想 深渊 如同白发。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, '在 地上 没有 像牠 造的那样,无所 惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, '凡 高大的,牠无不藐视;牠在 骄傲的 水族 上 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, '约伯 回答 耶和华 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, '我知道, 你万事都 能做;你的 旨意 不能 拦阻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, '谁 用无 知 的言语使你的旨意 隐藏呢? 我所说的 是我不 明白的;这些事太 奇妙,是我不 知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, '求 你听我,我 要说话;我问你,求你指示我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, '我 从前风闻有你,现在 亲眼 看见你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, '因此 我厌恶自己(或译:我的言语),在 尘土 和炉灰 中懊悔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, ' 耶和华 对 约伯 说 话 以后, 就对 提幔人 以利法 说:「我的怒气 向你 和你两个 朋友 发作,因为 你们议论 我 不 如我的仆人 约伯 说的是。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, '现在 你们要取 七只 公牛,七只 公羊,到 我仆人 约伯 那里去,为 自己献上 燔祭,我的仆人 约伯 就为你们 祈祷。我因 悦纳 他,就不 按你们 的愚妄 办你们。 你们议论 我,不 如我的仆人 约伯 说的是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, '于 是提幔人 以利法、书亚人 比勒达、拿玛人 琐法 照著耶和华 所 吩咐的 去 行;耶和华 就悦纳 约伯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, '约伯为 他的朋友 祈祷。耶和华 就使 约伯从苦境(原文是掳掠)转回,并且耶和华 赐 给他的 比他从前所有的 加倍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, '约伯的 弟兄、 姊妹,和 以先 所认识的人 都来 见他,在他家里 一同 吃 饭;又论到 耶和华 所 降 与他 的一切 灾祸,都为他 悲伤 安慰 他。每人 也送 他 一块 银子 和一个 金 环。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, '这样,耶和华 后来 赐福 给 约伯 比先前更多。他 有 一万 四 千 羊,六 千 骆驼,一千 对 牛,一千 母驴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, '他 也有 七个 儿子,三个 女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, '他给长 女起 名 叫耶米玛,次 女叫 基洗亚,三 女叫基连‧哈朴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, '在那全 地 的妇女 中找 不著 像约伯 的女儿 那样美貌。她们的父亲 使她们 在弟兄 中 得 产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, '此 后,约伯 又活了 一百 四十 年,得见 他的儿 孙,直到四 代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, '这样,约伯 年纪老迈,日子 满足 而死。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, ' 不 从 恶人 的计谋,不 站 罪人 的道路,不 坐 亵慢人 的座位, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, ' 惟 喜爱 耶和华 的律法,昼 夜 思想,这人 便为有福! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, '他要 像一棵树 栽在 溪 水 旁, 按时候 结 果子,叶子 也不 枯干。凡 他所 做的 尽都顺利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, '恶人 并不是 这样,乃 像糠秕 被风 吹散。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, '因此,当审判的时候 恶人 必站立 不住;罪人 在义人 的会中也是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, '因为 耶和华 知道 义人 的道路;恶人 的道路 却必灭亡。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, '外邦 为什么 争闹?万民 为什么谋算 虚妄的事? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, '世上 的君王 一齐起来,臣宰 一同 商议,要敌挡 耶和华并 他的受膏者, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, '说:我们要挣开  他们的捆绑,脱去 他们的绳索。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, '那坐在 天上 的必发笑;主 必嗤笑 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, '那时,他要在怒中 责备 他们,在烈怒中 惊吓他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, '说:我 已经立 我的君 在锡安─我的圣 山 上了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, '受膏者说:我要传 圣旨。耶和华 曾对我 说:你 是我的儿子,我 今日 生你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, '你求 我,我就将列国 赐 你为基业,将地 极 赐你为田产。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, '你必用铁 杖 打破他们;你必将他们如同窑匠 的瓦器 摔碎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, '现在,你们君王 应当省悟!你们世上 的审判官 该受管教! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, '当存畏惧 事奉 耶和华,又当存战 兢 而快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, '当以嘴亲 子,恐怕 他发怒,你们便在道中 灭亡,因为 他的怒气 快要 发作。凡 投靠 他的,都是有福的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, '(大卫 逃避 他儿子 押沙龙 的时候作的诗。)耶和华啊,我的敌人 何其 加增;有许多人 起来 攻击我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, '有许多人 议论 我 说:他 得不著 神 的帮助。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, '但你─耶和华 是我四围 的盾牌,是我的荣耀,又是叫我抬起 头来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, '我用我的声音 求告 耶和华,他就从他的圣 山 上应允我。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, '我 躺下 睡觉,我醒著, 耶和华 都保佑我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, '虽有成万 的百姓 来 周围 攻击我,我也不 怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, '耶和华啊,求你起来!我的 神啊,求你救我!因为 你打了 我一切 仇敌 的腮骨,敲碎了 恶人 的牙齿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, '救恩 属乎耶和华;愿 你赐福 给 你的百姓。(细拉)   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, '(大卫的 诗,交与伶长。用丝弦的乐器。)显我为义的 神啊,我呼吁的时候,求你应允我!我在困苦中,你曾使我宽广;现在求你怜恤 我,听 我的祷告! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, '你们这上流人哪,你们将我的尊荣 变为羞辱 要到 几时呢?你们喜爱 虚妄,寻找 虚假,要到几时呢?(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, '你们要知道, 耶和华 已经分别 虔诚人 归他自己;我求告耶和华,他 必听我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, '你们应当畏惧,不可 犯罪;在 床上的时候,要心里 思想,并要肃静。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, '当献上 公义 的祭,又当倚靠 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, '有许多人 说:谁 能指示我们 什么好处?耶和华啊,求你仰起 脸来,光照 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, '你使 我心里 快乐,胜过 那丰收 五谷 新酒的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, '我必 安然 躺下 睡觉,因为 独有 你─耶和华 使我安然 居住。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, '(大卫的 诗,交与伶长。用 吹的乐器。)耶和华啊,求你留心听 我的言语,顾念 我的心思! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, '我的王我的 神啊,求你垂听 我呼求 的声音!因为 我向你 祈祷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, '耶和华啊,早晨 你必听 我的声音;早晨 我必向你 陈明我的心意,并要警醒! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, '因为 你 不是 喜悦 恶事的 神,恶人 不能 与你同居。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, '狂傲人 不能 站 在你眼 前;凡 作 孽的,都是你所恨恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, '说 谎言的,你必灭绝;好流人血 弄诡诈 的,都为耶和华 所憎恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, '至于 我,我必凭你丰盛 的慈爱 进入 你的居所;我必存敬畏你 的心向 你的圣 殿 下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, '耶和华啊,求你因 我的仇敌,凭你的公义 引领我,使你的道路 在我面前 正直。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, '因为,他们的口中 没有 诚实;他们的心里 满有邪恶;他们的喉咙 是敞开 的 坟墓;他们用舌头 谄媚人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, '神啊,求你定他们的罪!愿 他们因自己的计谋 跌倒;愿 你在他们许多 的过犯 中把他们逐出,因为 他们背叛了 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, '凡 投靠 你的,愿 他们喜乐,时常 欢呼,因为你护庇 他们;又愿 那爱 你名 的人都靠你 欢欣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, '因为 你 必赐福 与义人;耶和华啊,你必用恩惠 如同盾牌 四面护卫他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, '(大卫的 诗,交与伶长。用丝弦的乐器,调用第八。)耶和华啊,求你不要 在怒中 责备我,也不要 在烈怒中 惩罚我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, '耶和华啊,求你可怜我,因为 我 软弱。耶和华啊,求你医治我,因为 我的骨头 发战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, '我心 也大大地 惊惶。耶和华啊,你 要到 几时才救我呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, '耶和华啊,求你转回 搭救 我!因 你的慈爱 拯救我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, '因为,在死地 无人 记念你,在阴间 有谁 称谢 你? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, '我因唉哼 而困乏;我每 夜 流泪,把床榻 漂起,把褥子 湿透。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, '我因忧愁 眼睛 干瘪,又因我一切的 敌人 眼睛昏花。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, '你们一切 作 孽 的人,离开  我吧!因为 耶和华 听了 我哀哭 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, '耶和华 听了 我的恳求;耶和华 必收纳 我的祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, '我的一切 仇敌 都必羞愧,大大 惊惶;他们必要退后,忽然 羞愧。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, '(大卫 指著 便雅悯 人 古实 的话, 向耶和华 唱 的流离歌。)耶和华─我的 神啊,我投靠 你!求你救我 脱离一切 追赶我的人,将我救拔出来! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, '恐怕 他们像狮子 撕裂 我,甚至撕碎,无人 搭救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, '耶和华─我的 神啊,我若 行了 这事,若 有 罪孽 在我手里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, '我若 以恶 报 那与我交好的人─连那无故 与我为敌的,我也救了他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, '就任凭仇敌 追赶 我,直到追上,将我的性命 踏在 地下,使 我的荣耀 归于  灰尘。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, '耶和华啊,求你在怒中 起来,挺身而立,抵挡我敌人 的暴怒!求你为我 兴起!你已经命定 施行审判! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, '愿 众 民 的会环绕你!愿 你从其上 归 于 高位! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, '耶和华 向众民 施行审判;耶和华啊,求你按我的公义 和我心中的纯正 判断 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, '愿  恶人 的恶 断绝!愿 你坚立 义人!因为公义的 神 察验 人的心肠 肺腑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, '神是 我的盾牌;他拯救 心里 正直的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, '神 是公义的 审判者,又是天 天 向恶人发怒的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, '若 有人不 回头,他的刀 必磨快,弓 必上弦,预备妥当了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, '他 也预备了 杀人 的器械;他所射的 是火 箭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, '试看 恶人因奸恶 而劬劳,所怀 的是毒害,所生 的是虚假。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, '他掘了 坑,又挖深了,竟掉 在自己所挖 的阱里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, '他的毒害 必临 到他自己的头上;他的强暴 必落 到 他自己的脑袋上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, '我要照著耶和华 的公义 称谢他,歌颂 耶和华 至高者的 名。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, '(大卫的 诗,交与伶长。用 迦特乐器。)耶和华─我们的主啊,你的名 在全 地 何其 美! 你将你的荣耀 彰显 于  天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, '你因敌人 的缘故,从婴孩 和吃奶 的口中,建立了 能力,使仇敌 和报仇的 闭口无言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, ' 我观看 你指头 所造 的天,并你所 陈设 的月亮 星宿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, '便说:人 算什么,你竟 顾念他?世人算什么,你竟 眷顾他? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, '你叫他比天使(或译: 神)微小 一点,并赐他荣耀 尊贵 为冠冕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, '你派他管理 你手 所造的,使 万物,就是一切的 牛 羊、田野 的兽、空中 的鸟、海里 的鱼,凡经行 海 道的,都 服在他的脚下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, '耶和华─我们的主啊,你的名 在全 地 何其 美!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, '(大卫的 诗,交与伶长。调用 慕 拉便。)我要一 心 称谢 耶和华;我要传扬 你一切 奇妙的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, '我要因你 欢喜 快乐;至高者啊,我要歌颂 你的名! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, '我的仇敌 转身 退去的时候,他们一见你的面 就跌倒 灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, '因 你已经为我伸 冤,为我辨屈;你坐 在宝座上,按公义 审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, '你曾斥责 外邦,你曾灭绝 恶人;你曾涂抹 他们的名,直到永永远远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, '仇敌 到了尽头;他们被毁坏,直到永远。你拆毁 他们的城邑,连他们 的名号 都归于 无有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, '惟耶和华 坐著为王,直到永远;他已经为审判 设摆 他的宝座。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, '他要 按公义 审判 世界,按正直 判断 万民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, '耶和华 又要 给受欺压的人 作高台,在患难 的时候 作高台。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, '耶和华啊,认识 你名 的人要倚靠 你,因 你没有 离弃 寻求你的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, '应当歌颂 居 锡安 的耶和华,将他所行 的传扬 在众民中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, '因为 那追讨 流人血之罪的─他记念受屈的人,不 忘记 困苦人 的哀求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, '耶和华啊,你是从死 门 把我提拔起来的;求你怜恤我,看 那恨我的人 所加给我的苦难, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, '好叫 我述说 你一切 的美德;我必在锡安城(原文是女子)的门 因你的救恩 欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, '外邦人 陷 在自己所掘 的坑中;他们的脚 在自己 暗设 的网罗里 缠住了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, '耶和华 已将自己显明了,他已施行 审判;恶人 被自己手 所做的 缠住了(或译:他叫恶人被自己手所做的累住了)。( 细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, '恶人,就是忘记 神 的外邦人,都 必归 到阴间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, ' 穷乏人 必不 永久 被忘;困苦人 的指望 必不永远 落空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, '耶和华啊,求你起来,不 容人 得胜!愿 外邦人 在 你面前 受审判! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, '耶和华啊,求你使 外邦人 恐惧;愿 他们 知道 自己 不过是人。(细拉)   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, '耶和华啊,你为什么 站 在远处?在患难 的时候 为什么隐藏? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, '恶人 在骄横中 把困苦人 追得火急;愿 他们陷 在自己所 设 的计谋里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, '因为 恶人 以 心 愿  自夸;贪财的背弃耶和华,并且轻慢他(或译:他祝福 贪财的,却轻慢 耶和华)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, '恶人 面 带骄傲,说:耶和华必不 追究;他一切 所想的 都以为没有 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, '凡他所做的,时常 稳固;你的审判 超过 他的眼界。至于 他一切 的敌人,他都向他们 喷气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, '他心里 说:我必不 动摇,世世代代 不 遭灾难。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, '他满 口 是咒骂、诡诈、欺压,舌 底 是毒害、奸恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, '他在村庄 埋伏 等候;他在隐密处 杀害 无辜的人。他的眼睛 窥探 无倚无靠的人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, '他埋伏 在暗地,如狮子 蹲在洞中。他埋伏,要掳去 困苦人;他拉 网,就把困苦人 掳去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, '他屈身 蹲伏,无倚无靠的人 就倒在他爪牙(爪牙:或译强暴人)之下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, '他心里 说: 神 竟忘记了;他掩 面 永 不 观看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, '耶和华啊,求你起来! 神啊,求你举 手,不要 忘记 困苦人! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, '恶人 为何 轻慢 神,心里 说:你必不 追究? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, '其实你已经观看;因为 奸恶 毒害,你 都看见了,为要以手 施行报应。无倚无靠的人 把自己交托 讬 你;你 向来是 帮助 孤儿的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, '愿 你打断 恶人 的膀臂;至于 坏人,愿 你追究 他的恶,直到净 尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, '耶和华 永永远远 为王;外邦人 从他的地 已经灭绝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, '耶和华啊,谦卑人 的心愿 ,你早已知道(原文是听见)。你必预备 他们的心,也必侧耳 听他们的祈求, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, '为要给孤儿 和受欺压的人 伸冤,使强横的 人 不 再 威吓他们。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, '(大卫的诗,交与伶长。)我是投靠 耶和华;你们怎么 对我 说:你当像鸟 飞 往你的山去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, ' 看哪,恶人 弯 弓,把箭 搭 在 弦上,要在 暗中 射 那心 里正直的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, '根基 若 毁坏,义人 还能做 什么呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, '耶和华 在他的圣 殿里;耶和华 的宝座 在天上;他的慧眼 察 看 世人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, '耶和华 试验 义人;惟有恶人 和喜爱 强暴的人,他心里 恨恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, '他要向 恶人 密布 网罗;有烈火、硫磺、热 风,作他们杯 中的分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, '因为 耶和华 是公义的,他喜爱 公义;正直人 必得见 他的面。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, '(大卫的 诗,交与伶长。调用 第八。)耶和华啊,求你帮助,因 虔诚人 断绝了; 世人中间的 忠信人 没有了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, '人人 向 邻舍 说 谎;他们说话,是嘴唇 油滑,心口不一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, '凡 油滑 的嘴唇 和夸 大 的舌头,耶和华 必要剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, '他们 曾说:我们必能以舌头 得胜;我们的嘴唇 是我们自己的,谁 能作我们的 主呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, '耶和华 说:因为困苦人 的冤屈 和贫穷人 的叹息,我现在 要起来,把他安置 在他 所切慕 的稳妥之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, '耶和华 的言语 是纯净 的言语,如同银子 在泥 炉中 炼过 七次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, '耶和华啊,你 必保护他们;你必保佑他们 永远 脱离 这 世代的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, '下流人 在世人中 升高,就有恶人 到处 游行。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, '(大卫的 诗,交与伶长。)耶和华啊,你忘记我 要到 几时呢?要到永远吗?你掩 面 不顾我 要到 几时呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, '我心里 筹 算,终日 愁苦,要到 几时呢?我的仇敌 升高 压制我,要到 几时呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, '耶和华─我的 神啊,求你看顾我,应允我!使我眼目 光明,免得 我沉睡 至死; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, '免得 我的仇敌 说:我胜了他;免得我的敌人 在我摇动 的时候 喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, '但我 倚靠 你的慈爱;我的心 因你的救恩 快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, '我要向耶和华 歌唱,因 他用厚恩 待我。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, '(大卫的诗,交与伶长。)愚顽人 心里 说:没有 神。他们都是邪恶,行了可憎恶 的事;没有 一个人行 善。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, '耶和华 从天上 垂看 世人,要看 有 明白的没有,有寻求 神的没有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, '他们都 偏离正路,一同 变为污秽;并没有 行 善的,连 一个 也没有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, '作 孽 的都 没有 知识吗?他们吞吃 我的百姓,如同吃 饭一样,并不 求告 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, '他们在那里 大大地害怕,因为 神 在义人 的族类中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, '你们叫困苦人 的谋算 变为羞辱;然而 耶和华 是他的避难所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, '但愿  以色列 的救恩 从锡安 而出。耶和华 救回 他被掳 的子民那时,雅各 要快乐,以色列 要欢喜。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, '(大卫的 诗。)耶和华啊,谁 能寄居 你的帐幕?谁 能住 在你的圣 山? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, '就是行为 正直、做事 公义、心里 说 实话的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, '他不 以 舌头 谗谤人,不 恶 待 朋友,也不 随伙 夥毁谤 邻里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, '他眼中 藐视 匪类,却尊重 那敬畏 耶和华的人。他发了誓,虽然自己吃亏 也不 更改。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, '他不 放 债 取利,不 受 贿赂 以害 无辜。行 这些事 的人必永 不 动摇。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, '(大卫的 金诗。) 神啊,求你保佑我,因为 我投靠 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, '我的心哪,你曾对耶和华 说:你 是我的主;我的好处 不 在你以外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, '论到 世上 的圣民,他们 又美又善,是我最 喜悦的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, '以别神代替耶和华的(或译:送礼物 给别神的),他们的愁苦 必加增;他们所浇奠 的血 我不 献上;我嘴唇 也不 提 别神的名号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, '耶和华 是我的产业,是我杯 中的分;我所得的,你 为我持守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, '用绳 量 给我的地界,坐落在佳美之处;我的 产业 实在 美好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, '我必称颂 那 指教我的 耶和华;我的心肠 在夜间 也 警戒我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, '我将耶和华 常 摆 在我面前,因 他在我右边,我便不致 摇动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, '因此,我的心 欢喜,我的灵(原文是荣耀)快乐;我的肉身 也要 安然 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, '因为 你必不 将我的灵魂 撇 在阴间,也不 叫 你的圣者 见 朽坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, '你必将生命 的道路 指示我。在 你面前 有满足的 喜乐;在你右手中 有永远的 福乐。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, '(大卫的 祈祷。)耶和华啊,求你听闻 公义,侧耳听 我的呼吁!求你留心听 我这不 出于 诡诈 嘴唇 的祈祷! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, '愿 我的判语 从你面前 发出;愿 你的眼睛 观看 公正。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, '你已经试验 我的心;你在夜间 鉴察我;你熬炼我,却找 不著什么;我立志 叫我口中 没有 过失。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, '论到人 的行为,我 藉 借著你嘴唇 的言语 自己谨守,不行强暴人 的道路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, '我的脚 踏定了 你的路径;我的两脚 未 曾滑跌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, '神啊,我 曾求告你,因为 你必应允我;求你向我 侧 耳,听 我的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, '求你显出你奇妙的 慈爱来;你是那用右手 拯救 投靠 你的脱离起来攻击他们的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, '求你保护我,如同保护眼中 的瞳人;将我隐藏 在你翅膀 的荫下, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, '使我脱离 那 欺压我的 恶人,就是围困 我 要害我命 的仇敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, '他们的心被脂油 包裹;他们用口 说 骄傲的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, ' 他们围困了 我们的脚步;他们瞪著 眼,要把我们推倒 在地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, '他像 狮子 急要 抓食,又像少壮狮子 蹲伏 在暗处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, '耶和华啊,求你起来,前去 迎敌,将他打倒!用你的刀 救护 我命 脱离恶人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, '耶和华啊,求你用手 救我脱离世人,脱离那只在今生 有福分 的世 人!你把你的财宝 充满 他们的肚腹;他们因有儿女 就心满意足,将其余 馀 的财物留给 他们的婴孩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, '至于 我,我必在义中 见 你的面;我醒了的时候,得见(或译:著)你的形像 就心满意足了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, '(耶和华 的仆人 大卫的诗,交与伶长。当耶和华 救 他脱离 一切 仇敌 和扫罗 之手 的日子,他 向耶和华 念 这 诗 的话。说:)耶和华,我的力量啊,我爱你! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, '耶和华 是我的岩石,我的山寨,我的救主,我的 神,我的磐石,我所投靠的。他是我的盾牌,是拯救我 的角,是我的高台。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, '我要求告 当赞美的 耶和华;这样我必从 仇敌 手中被救出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, '曾有死亡 的绳索 缠绕我,匪类 的急流 使我惊惧, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, '阴间 的绳索 缠绕我,死亡 的网罗 临到我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, '我 在急难中 求告 耶和华,向我的 神 呼求。他从殿中 听了 我的声音;我在他面前 的呼求 入了 他的耳中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, '那时,因 他 发怒,地 就摇撼 战 抖;山 的根基 也震动 摇撼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, '从他鼻孔 冒烟 上腾;从他口中 发火 焚烧,连炭 也著了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, '他又使天 下垂,亲自降临,有黑云 在他脚 下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, '他坐著 基路伯 飞行;他藉 借著 风 的翅膀 快飞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, '他以 黑暗 为藏身之处,以水 的黑暗、天空 的厚云 为他四围 的行宫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, '因他面前 的光辉,他的厚云 行过 便有冰雹 火 炭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, '耶和华 也在天上 打雷;至高者 发出 声音 便有冰雹 火 炭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, '他射出 箭来,使仇敌四散;多多发出 闪电,使他们扰乱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, '耶和华啊,你的斥责一发,你鼻孔 的气 一出,海 底 就出现,大地 的根基 也显露。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, '他从高天 伸手 抓住我,把我从大 水中 拉上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, '他救我 脱离我的劲 敌 和那些恨我的人,因为 他们比我 强盛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, '我遭遇灾难 的日子,他们来攻击我;但耶和华 是 我的 倚靠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, '他又领我 到宽阔之处;他救拔我,因 他喜悦 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, '耶和华 按著我的公义 报答我,按著我手 中的清洁 赏赐 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, '因为 我遵守了 耶和华 的道,未 曾作恶离开 我的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, ' 他的一切 典章 常在我面前;他的律例 我也未 曾丢弃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, '我在他面前 作了 完全人;我也保守自己 远离我的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, '所以,耶和华 按我的公义,按我在他眼 前 手 中的清洁 偿还 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, '慈爱的人,你以慈爱 待他;完全 的人,你以完全 待他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, '清洁的人,你以清洁 待他;乖僻的人,你以弯曲 待他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, ' 困苦 的百姓,你 必拯救;高傲 的眼目,你必使他降卑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, ' 你 必点著 我的灯;耶和华─我的 神 必照明 我的黑暗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, ' 我藉 借著你 冲入 敌军,藉 借著我的 神 跳过 墙垣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, '至于  神,他的道 是完全的;耶和华 的话 是炼净的。凡 投靠 他的,他 便作他们的盾牌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, ' 除了 耶和华,谁是 神呢?除了我们的 神,谁 是磐石呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, '惟有那以力量 束我的腰、使 我行为 完全的,他是 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, '他使 我的脚 快如母鹿的蹄,又使我在 高处 安稳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, '他教导 我的手 能以争战 ,甚至我的膀臂 能开  铜 弓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, '你把你的救恩 给 我 作盾牌;你的右手 扶持我;你的温和 使我为大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, '你使我脚下 的地步 宽阔;我的脚 未 曾滑跌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, '我要追赶 我的仇敌,并要追上他们;不将 他们灭绝,我总不 归回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, '我要打伤他们,使他们不 能 起来;他们必倒 在我的脚 下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, '因为你曾以力量 束我的腰,使我能争战 ;你也使那起来攻击我的 都服 在我以下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, '你又使 我的仇敌 在我面前 转背逃跑,叫我能以剪除 那恨我的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, '他们呼求,却无人 拯救;就是呼求 耶和华,他也不 应允。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, '我捣碎他们,如同风 前 的灰尘,倒出他们,如同街上 的泥土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, '你救我 脱离百姓 的争竞,立我 作列国 的元首;我素不 认识 的民 必事奉我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, '他们一听见 我的名声 就必顺从 我;外邦 人 要投降 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, '外邦 人 要衰残,战 战 兢兢 地出他们的营寨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, '耶和华 是活 神。愿 我的磐石 被人称颂;愿 救我的 神 被人尊崇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, '这位 神,就是那为我 伸 冤、使众民 服 在我以下的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, '你救我 脱离仇敌,又 把我举起,高过 那些起来攻击我的;你救我 脱离强暴 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, '耶和华啊,因此 我要在外邦中 称谢你,歌颂 你的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, '耶和华赐极大 的救恩 给他所立的王,施 慈爱 给他的受膏者,就是给大卫 和他的后裔,直到 永远。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, '(大卫的 诗,交与伶长。)诸天 述说 神 的荣耀;穹苍 传扬 他的手段。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, '这日 到那日 发出 言语;这夜 到那夜 传出 知识。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, '无 言 无 语,也无 声音 可听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, '它的量带 通 遍 天下,它的言语 传到地 极。 神在其间 为太阳 安设 帐幕; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, '太阳 如同新郎 出 洞房,又如勇士 欢然 奔 路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, '它从天 这边 出来,绕 到 天那边,没有 一物被隐藏 不得它的热气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, '耶和华 的律法 全备,能苏醒 人心;耶和华 的法度 确定,能使愚人 有智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, '耶和华 的训词 正直,能快活 人的心;耶和华 的命令 清洁,能明亮 人的眼目。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, '耶和华 的道理 洁净,存 到永远;耶和华 的典章 真实,全然 公义─ ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, '都比金子 可羡慕,且比极多的 精金可羡慕;比蜜 甘甜,且比蜂房 下滴的蜜甘甜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, '况且 你的仆人 因此 受警戒,守著这些 便有大 赏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, '谁 能知道 自己的错失呢?愿 你赦免我 隐而未现的过错。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, ' 求你拦阻 仆人 不犯任意妄为的罪,不 容这罪辖制 我,我便 完全,免犯 大 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, '耶和华─我的磐石,我的救赎主啊,愿  我口中 的言语、心 里的意念 在你面前 蒙悦纳。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, '(大卫的 诗,交与伶长。)愿 耶和华 在你遭难 的日子 应允你;愿 名 为雅各 神 的高举你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, '愿 他从圣所 救助你,从锡安 坚固你, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, '记念 你的一切 供献,悦纳 你的燔祭,(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, '将你心所愿 的 赐 给你,成就 你的一切 筹算。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, '我们要因你的救恩 夸胜,要奉我们 神 的名 竖立旌旗。愿 耶和华 成就 你一切 所求的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, '现在 我知道 耶和华 救护 他的受膏者,必从他的圣 天 上应允他,用右手 的能力 救护他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, '有人 靠车,有人 靠马,但我们 要提到 耶和华─我们 神 的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, '他们 都屈身 仆倒,我们 却起来,立得正直。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, '求耶和华 施行拯救;我们呼求 的时候,愿 王 应允我们!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, '(大卫的 诗,交与伶长。)耶和华啊,王 必因你的能力 欢喜;因你的救恩,他的快乐 何其 大! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, '他心 里所愿 的,你已经赐 给他;他嘴唇 所求的,你未 尝不应允。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, ' 你以美 福 迎接他,把精金 的冠冕 戴 在他头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, '他向你 求 寿,你便赐 给他,就是日子 长久,直到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, '他因你的救恩 大 有荣耀;你又将尊荣 威严 加 在他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, ' 你使他有 洪福,直到永远,又使他在你面前 欢喜 快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, ' 王 倚靠 耶和华,因至高者 的慈爱 必不 摇动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, '你的手 要搜出 你的一切 仇敌;你的右手 要搜出 那些恨你的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, '你发怒 的时候,要使他们 如在炎热 的火炉中。耶和华 要在他的震怒中 吞灭他们;那火 要把他们烧尽了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, '你必从世上 灭绝 他们的子孙(原文是果子),从人间 灭绝他们的后裔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, '因为 他们有意 加害 于 你;他们想出 计谋,却不 能做成。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, ' 你必使他们 转背逃跑,向 他们的脸 搭 箭在弦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, '耶和华啊,愿 你因自己的能力 显为至高!这样,我们就唱诗,歌颂 你的大能。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, '(大卫的 诗,交与伶长。调用 朝 鹿。)我的 神,我的 神!为什么 离弃我?为什么远离 不救我?不听我唉哼 的言语? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, '我的 神啊,我白日 呼求,你不 应允,夜间呼求,并不 住声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, '但你 是圣洁的,是用以色列 的赞美为宝座(或译:居所)的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, '我们的祖宗 倚靠 你;他们倚靠你,你便解救他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, '他们哀求 你,便蒙解救;他们倚靠 你,就不 羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, '但我是 虫,不是 人,被众人 羞辱,被百姓 藐视。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, '凡 看见我的 都嗤笑 我;他们撇 嘴 摇 头,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, '他把自己交托 讬 耶和华,耶和华可以救他吧!耶和华既 喜悦 他,可以搭救他吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, '但 你 是叫我出 母腹的;我在 母 怀里,你就使我有倚靠的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, '我自出母胎 就被交 在你手里;从我母亲 生我,你就是我的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, '求你不要 远离 我!因为 急难 临近了, 没有人 帮助我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, '有许多 公牛 围绕我,巴珊 大力的公牛 四面困住我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, '牠们向我 张 口,好像抓撕 吼叫 的狮子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, '我如水 被倒出来;我的骨头 都 脱了节;我心 在我里面 如蜡 镕化。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, '我的精力 枯干,如同瓦片;我的舌头 贴 在我牙床上。你将我安置 在死地 的尘土中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, ' 犬类 围著我,恶 党 环绕我;他们扎了 我的手,我的脚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, '我的骨头,我都 能数过;他们 瞪著眼 看 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, '他们 分 我的外衣,为 我的里衣 拈 阄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, '耶和华啊,求你 不要 远离我!我的救主啊,求你快 来帮助我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, '求你救 我的灵魂 脱离刀剑,救我的生命(生命:原文是独一者)脱离 犬类, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, '救我 脱离狮子 的口;你已经应允我,使我脱离野牛 的角。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, '我要将你的名 传 与我的弟兄,在会中 我要赞美你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, '你们敬畏 耶和华 的人要赞美他!雅各 的后裔 都 要荣耀他!以色列 的后裔 都 要惧怕 他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, '因为 他没有 藐视 憎恶 受苦的人,也没有 向他 掩 面;那受苦之人呼吁的时候,他就垂听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, '我在大 会中 赞美你的话 是从你而来的;我要在敬畏 耶和华的人面前 还 我的愿 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, '谦卑的人 必吃 得饱足;寻求 耶和华 的人必赞美他。愿 你们的心 永远 活著! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, '地 的四 极 都要想念 耶和华,并且归顺他;列国 的万 族 都要在你面前 敬拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, '因为 国权 是耶和华的;他是管理 万国的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, '地上 一切 丰肥的人 必吃喝 而敬拜;凡 下到 尘土中─不能 存活 自己性命的人─都要在他面前 下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, '他必有后裔 事奉他;主所行的事 必传 与后代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, '他们必来 把他的公义 传 给将要生 的民,言明 这事是他所行的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, '(大卫的 诗。)耶和华 是我的牧者,我必不 致缺乏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, '他使我躺卧 在青 草地上,领我 在 可安歇 的水边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, '他使我的灵魂 苏醒,为 自己的名 引导我走 义 路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, ' 我虽然 行 过死荫 的幽谷,也不 怕 遭害,因为 你 与我同在;你的杖,你的竿,都 安慰我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, '在我敌人 面前,你为我 摆设 筵席;你用油 膏了 我的头,使我的福杯 满溢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, '我一 生 一世 必有 恩惠 慈爱 随著我;我且要住 在耶和华 的殿中,直到永远。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, '(大卫的 诗。)地 和其中所充满的,世界 和住 在其间的,都属耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, ' 他 把地建立 在 海上,安定 在 大水之上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, '谁 能登 耶和华 的山?谁 能站 在他的圣 所? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, '就是手 洁 心 清、 不 向虚妄、起誓 不 怀诡诈 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, '他必蒙 耶和华 赐福,又蒙救他的 神 使他成义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, '这是 寻求 耶和华的族类,是寻求 你面 的雅各。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, '众城门哪,你们要抬起 头来!永久 的门户,你们要被举起!那荣耀 的王 将要进来! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, ' 荣耀 的王 是谁呢?就是有力 有能 的耶和华,在战 场上 有能的 耶和华! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, '众城门哪,你们要抬起 头来!永久 的门户,你们要把头抬起!那荣耀 的王 将要进来! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, ' 荣耀 的王 是 谁呢?万军 之耶和华,他是 荣耀 的王!(细拉)   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, '(大卫的诗。)耶和华啊,我的心 仰望 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, '我的 神啊,我素来倚靠 你;求你不要 叫我羞愧,不要 叫我的仇敌 向我 夸胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, '凡 等候你的 必 不 羞愧;惟有那无故 行奸诈的 必要羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, '耶和华啊,求你将你的道 指示我,将你的路 教训我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, '求你以你的真理 引导我,教训我,因为 你 是救我的 神。我终 日 等候 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, '耶和华啊,求你记念 你的怜悯 和慈爱,因为 这是 亘古以来所常有的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, '求你不要 记念 我幼年 的罪愆 和我的过犯;耶和华啊,求你 因 你的恩惠,按你的慈爱 记念 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, '耶和华 是良善 正直的,所以 他必指示 罪人 走正路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, '他必按公平 引领 谦卑人,将他的道 教训 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, '凡 遵守 他的约 和他法度的人,耶和华 都以慈爱 诚实待他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, '耶和华啊,求你因 你的名 赦免 我的罪,因为我的罪 重大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, '谁 敬畏 耶和华,耶和华必指示他 当选择 的道路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, '他必 安然 居住;他的后裔 必承受 地土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, '耶和华 与敬畏他的人 亲密;他必将自己的约 指示他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, '我的眼目 时常 仰望 耶和华,因为 他必 将我的脚 从网里 拉出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, '求你转 向我,怜恤我,因为 我是 孤独 困苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, '我心里 的愁苦 甚多,求你救我 脱离我的祸患。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, '求你看顾 我的困苦,我的艰难,赦免 我一切的 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, '求你察看 我的仇敌,因为 他们人多,并且痛痛地 恨我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, '求你保护 我的性命,搭救我,使我不 致羞愧,因为 我投靠 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, '愿 纯全、正直 保守我,因为 我等候你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, '神啊,求你救赎 以色列 脱离他一切的 愁苦。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, '(大卫的诗。)耶和华啊,求你为我伸冤,因 我 向来行事 纯全;我又倚靠 耶和华,并不 摇动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, '耶和华啊,求你察看我,试验我,熬炼 我的肺腑 心肠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, '因为 你的慈爱 常在我眼 前,我也按你的真理 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, '我没有 和 虚谎 人 同坐,也不 与 瞒哄人的 同群。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, '我恨恶 恶人 的会,必不 与 恶人 同坐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, '耶和华啊,我要洗 手 表明无辜,才环绕 你的祭坛; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, '我好发 称谢 的声音,也要述说 你一切 奇妙的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, '耶和华啊,我喜爱 你所住 的殿 和你显荣耀 的居 所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, '不要 把我的灵魂 和 罪人 一同除掉;不要把我的性命 和 流人血 的一同除掉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, '他们 的手中 有奸恶,右手 满有 贿赂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, '至于 我,却要行事 纯全;求你救赎我,怜恤我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, '我的脚 站 在平坦地方;在众会中 我要称颂 耶和华!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, '(大卫的诗。)耶和华 是我的亮光,是我的拯救,我还怕 谁呢?耶和华 是我性命 的保障(或译:力量),我还惧 谁呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, '那作恶的 就是我的 仇 敌,前来 吃 我肉的时候就 绊跌 仆倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, '虽有 军兵 安营 攻击我,我的心 也不 害怕;虽然 兴起 刀兵 攻击我, 我 必仍旧安稳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, '有一件事,我曾求 耶和华, 我仍要寻求:就是一生一世 住 在耶和华 的殿中,瞻仰 他 的荣美,在他的殿里 求问。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, '因为 我遭遇患难,他必暗暗地保守我;在他亭子里,把我藏 在他帐幕 的隐密处,将我高举 在磐石上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, '现在 我得以昂 首,高过 四面 的仇敌。我要在他的帐幕里 欢然 献 祭;我要唱诗 歌颂 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, '耶和华啊,我用声音 呼吁的时候,求你垂听;并求你怜恤我,应允我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, '你说:你们当寻求 我的面。那时我心 向你 说:耶和华啊, 你的面 我正要寻求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, '不要 向我 掩 面。不要 发怒 赶逐 仆人,你向来是 帮助我的。救我的 神啊,不要 丢掉我,也不要 离弃我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, ' 我父 母 离弃我,耶和华 必收留我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, '耶和华啊,求你将你的道 指教我,因 我仇敌 的缘故引导我 走平坦 的路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, '求你不要 把我交给 敌人,遂其所愿 ;因为 妄 作见证的 和口吐 凶言的,起来 攻击我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, '我若不 信 在活人 之地 得见 耶和华 的恩惠,就早已丧胆了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, '要等候 耶和华!当壮胆,坚固 你的心!我再说,要等候 耶和华!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, '(大卫的诗。)耶和华啊,我要求告 你!我的磐石啊,不要 向我 缄默!倘若 你向我 闭口,我就如将死的人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, '我呼求 你,向 你至圣所 举 手的时候,求你垂听 我恳求 的声音! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, '不要 把我和 恶人 并 作 孽 的一同除掉;他们与 邻舍 说 和平话,心里 却是奸恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, '愿 你按著他们所做的,并他们所行 的恶事 待 他们。愿 你照著他们手 所做的 待 他们,将他们所应得的报应 加 给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, '他们既然 不 留心 耶和华 所行的 和 他手 所做的,他就必毁坏他们,不 建立他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, '耶和华 是应当称颂的,因为 他听了 我恳求 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, '耶和华 是我的力量,是我的盾牌;我心里 倚靠 他 就得帮助。所以我心中 欢乐,我必用诗歌 颂赞他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, '耶和华 是他百姓 的力量,又是 他受膏者 得救 的保障。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, '求你拯救 你的百姓,赐福 给 你的产业,牧养他们,扶持他们,直到 永远。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, '(大卫的 诗。) 神 的众子啊,你们要将荣耀、能力 归 给耶和华,归 给耶和华! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, '要将耶和华 的名 所当得的荣耀 归给他,以圣洁的(的:或译为)妆饰 敬拜 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, '耶和华 的声音 发在 水上;荣耀的 神 打雷,耶和华 打雷在 大 水之上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, '耶和华 的声音 大有能力;耶和华 的声音 满有威严。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, '耶和华 的声音 震破 香柏树;耶和华 震碎 黎巴嫩 的香柏树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, '他也使之跳跃 如 牛犊,使黎巴嫩 和西连 跳跃如 野牛 犊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, '耶和华 的声音 使火 焰 分岔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, '耶和华 的声音 震动 旷野;耶和华 震动 加低斯 的旷野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, '耶和华 的声音 惊动母鹿 落胎,树木 也脱落净光。凡在他殿中的,都 称说 他的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, '洪水泛滥之时,耶和华 坐著为王;耶和华 坐著 为王,直到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, '耶和华 必赐 力量 给他的百姓;耶和华 必赐 平安 的福给 他的百姓。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, '(大卫 在献 殿的时候,作这诗 歌。)耶和华啊,我要尊崇你,因为 你曾提拔我,不 叫仇敌 向我 夸耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, '耶和华─我的 神啊,我曾呼求 你,你医治了我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, '耶和华啊,你曾把我的灵魂 从 阴间 救上来,使我存活,不至于 下 坑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, '耶和华 的圣民哪,你们要歌颂他,称赞 他可记念的 圣名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, '因为,他的怒气 不过是转眼之间;他的恩典 乃是一生之久。一宿 虽然有 哭泣,早晨 便必欢呼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, '至于 我,我凡事平顺 便说:我永 不 动摇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, '耶和华啊,你曾施恩,叫我的江山 稳固;你掩了 面,我就 惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, '耶和华啊,我曾求告 你;我向 耶和华 恳求,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, '我被害流血,下 到 坑中,有什么 益处呢?尘土 岂能称赞你,传说 你的诚实么? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, '耶和华啊,求你应允我,怜恤我!耶和华啊, 求你帮助 我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, '你已将我的哀哭 变为 跳舞,将我的麻衣 脱去,给我披上 喜乐, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, '好叫我的灵(原文是荣耀)歌颂你,并不 住声。耶和华─我的 神啊,我要称谢你,直到永远!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, '(大卫的 诗,交与伶长。)耶和华啊,我投靠 你;求你使我永 不 羞愧;凭你的公义 搭救我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, '求你侧 耳而听,快快 救我!作 我 坚固的 磐石,拯救我的 保障! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, '因为 你 是我的岩石,我的山寨;所以,求你为你名 的缘故 引导我,指点我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, '求你救我 脱离人 为我 暗设 的网罗,因为 你 是我的保障。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, '我将我的灵魂 交 在你手里;耶和华 诚实的 神啊,你救赎了 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, '我恨恶 那信奉 虚无之神的人;我 却倚靠 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, '我要为你的慈爱 高兴 欢喜;因为 你见过 我的困苦,知道 我心中 的艰难。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, '你未 曾把我交 在仇敌 手里;你使我的脚 站 在宽阔之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, '耶和华啊,求你怜恤我,因为 我 在急难之中;我的眼睛 因忧愁 而干瘪,连我的身 心也不安舒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, ' 我的生命 为愁苦 所消耗;我的年岁 为叹息所旷废。我的力量 因我的罪孽 衰败;我的骨头 也枯干。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, '我因一切 敌人 成了 羞辱,在我的邻舍 跟前更甚;那认识我的 都惧怕我,在外头 看见我的 都躲避 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, '我被人忘记,如同死人,无人记念;我 好像破碎 的器皿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, ' 我听见了 许多人 的谗谤,四围 都是惊吓;他们一同 商议 攻击我的时候,就图谋 要害 我的性命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, '耶和华啊,我 仍旧倚靠 你;我说:你是我的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, '我终身的事 在你手中;求你救我 脱离仇敌 的手 和那些逼迫我的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, '求你使你的脸 光照 仆人,凭你的慈爱 拯救我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, '耶和华啊,求你叫我不 致羞愧,因为 我曾呼吁你;求你使恶人 羞愧,使他们在阴间 缄默无声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, '那撒谎 的人逞骄傲 轻慢,出 狂妄 的话攻击 义人;愿 他的嘴 哑而无言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, '敬畏你、投靠 你的人,你为他们所 积存的,在世人 面前 所施行 的恩惠 是何等 大呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, '你必把他们藏 在你面前 的隐密处,免得遇见人 的计谋;你必暗暗地保守他们 在亭子里,免受口舌 的争闹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, '耶和华 是应当称颂的,因为 他在坚固 城里 向我 施展奇妙的 慈爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, '至于 我,我曾急促地 说:我从你眼 前 被隔绝。然而,我呼求 你的时候,你仍听 我恳求 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, '耶和华 的圣民哪,你们都 要爱 他!耶和华 保护 诚实人,足足 报应 行事 骄傲的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, '凡 仰望 耶和华的人,你们都要壮胆,坚固 你们的心!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, '(大卫的 训诲诗。)得赦免 其过、遮盖 其罪的,这人是有福的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, '凡心里 没有 诡诈、耶和华 不 算为 有罪的,这人 是有福的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, ' 我闭口不认罪的时候,因终 日 唉哼 而骨头 枯干。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, ' 黑夜 白日,你的手 在我身上 沉重;我的精液 耗尽,如同夏天 的干旱。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, '我向你陈明 我的罪,不 隐瞒 我的恶。我说:我要向耶和华 承认 我的过犯,你 就赦免 我的罪恶。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, '为 此,凡 虔诚人 都当趁你可寻找 的时候 祷告 你;大 水 泛溢的时候,必 不能 到 他那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, '你 是我 藏身之处;你必保佑我 脱离苦难,以得救 的乐歌 四面环绕我。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, '我要教导你,指示你 当行 的路;我要定睛 在你身上 劝戒你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, '你 不可 像那无 知 的骡 马,必用嚼环 辔头 勒住 牠;不然,就不能驯服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, '恶人 必多 受苦楚;惟独倚靠 耶和华 的必有慈爱 四面环绕他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, '你们义人 应当靠耶和华 欢喜 快乐;你们心里 正直 的人都 当欢呼。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, '义人哪,你们应当靠耶和华 欢乐;正直人的 赞美 是合宜的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, '你们应当弹琴 称谢 耶和华,用十弦 瑟 歌颂 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, '应当向他 唱 新 歌,弹得 巧妙,声音洪亮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, '因为 耶和华 的言语 正直;凡 他所做的 尽都诚实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, '他喜爱 仁义 公平;遍地 满了 耶和华 的慈爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, '诸天 藉 借耶和华 的命 而造;万 象 藉 借他口中 的气而成。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, '他聚集 海 水 如垒,收藏 深洋 在库房。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, '愿 全 地 都敬畏 耶和华!愿 世上 的居民 都 惧怕 他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, '因为 他 说有,就有, 命立,就立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, '耶和华 使列国 的筹算 归于 无有,使众民 的思念 无有功效。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, '耶和华 的筹算 永远 立定;他心中 的思念 万代常存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, ' 以耶和华为 神的,那国 是有福的!他所拣选 为自己 产业的,那民是有福的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, '耶和华 从天上 观看;他看见 一切的 世人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, '从他的居 所 往外察看 地上 一切的 居民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, '他是那造成 他们众人 心的,留意 他们一切 作为的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, '君王 不能 因兵 多 得胜;勇士 不能 因力 大 得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, '靠马 得救 是枉然的;马也不能 因力 大 救人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, ' 耶和华 的眼目看顾 敬畏他的人 和仰望 他慈爱的人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, '要救 他们的命 脱离死亡,并使他们在饥荒中 存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, '我们的心 向来等候 耶和华;他是 我们的帮助,我们的盾牌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, '我们的心 必 靠他 欢喜,因为 我们向来倚靠 他的圣 名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, '耶和华啊,求你照著 我们所仰望 你的,向我们施行 慈爱!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, '(大卫 在亚比米勒 面前 装 疯,被他赶出 去,就作这诗。)我要时时 称颂 耶和华;赞美他 的话必常 在我口中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, '我的心 必因耶和华 夸耀;谦卑人 听见 就要喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, '你们和我 当称耶和华 为大,一同 高举 他的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, '我曾寻求 耶和华,他就应允我,救我 脱离了一切的 恐惧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, '凡仰望 他的,便有光荣;他们的脸 必不 蒙羞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, '我这 困苦人 呼求,耶和华 便垂听,救我 脱离一切 患难。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, '耶和华 的使者 在敬畏他的人 四围 安营,搭救他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, '你们要尝尝主恩的滋味,便 知道 他 是美善;投靠 他 的人 有福了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, '耶和华 的圣民哪,你们当敬畏他,因 敬畏他的 一无 所缺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, '少壮狮子 还缺 食忍饿,但寻求 耶和华 的什么好处 都 不 缺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, '众弟子啊,你们当来 听 我的话!我要将敬畏 耶和华 的道教训你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, '有何 人 喜好 存活,爱慕 长寿,得享 美福, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, '就要禁止 舌头 不出恶言,嘴唇 不说 诡诈的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, '要离 恶 行 善,寻求 和睦,一心追赶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, '耶和华 的眼目看顾 义人;他的耳朵听 他们的呼求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, '耶和华 向行 恶 的人变脸,要从世上 除灭 他们的名号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, '义人呼求,耶和华 听见了,便救他们 脱离一切 患难。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, '耶和华 靠近 伤 心的人,拯救 灵性 痛悔的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, '义人 多 有苦难,但耶和华 救他 脱离这一切, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, '又保全 他一身的 骨头,连一根 也不 折断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, '恶 必害死 恶人;恨恶 义人的,必被定罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, '耶和华 救赎 他仆人 的灵魂;凡 投靠 他的,必不 致定罪。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, '(大卫的诗。)耶和华啊, 与我相争的,求你与他们相争! 与我相战 的,求你与他们相战 ! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, '拿著 大小的盾 牌,起来 帮助我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, '抽出 枪来,挡住 那追赶我的;求你对我的灵魂 说:我是 拯救你的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, '愿 那寻索 我命的,蒙羞 受辱!愿 那谋 害我的,退 后 羞愧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, '愿 他们 像风 前 的糠,有耶和华 的使者 赶逐他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, '愿  他们的道路 又暗 又滑,有耶和华 的使者 追赶他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, '因 他们无故地 为我 暗设 网罗,无故地 挖 坑,要害我的性命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, '愿 灾祸 忽然 临到他身上!愿 他 暗设的 网 缠住自己!愿 他落 在其中 遭灾祸! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, '我的心 必靠耶和华 快乐,靠他的救恩 高兴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, '我的骨头 都 要说:耶和华啊,谁 能像你 救护 困苦人 脱离那比他 强壮的,救护困苦 穷乏人 脱离那抢夺他的? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, '凶恶 的见证人 起来,盘问 我所 不 知道的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, '他们向我以恶 报善,使我的灵魂 孤苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, '至于 我,当他们有病的时候,我便穿麻 衣,禁食,刻苦 己心;我所求的 都归 到 自己的怀中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, '我这样行,好像他是我的 朋友,我的弟兄;我屈身 悲哀,如同人为母亲 哀痛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, '我在患难中,他们却欢喜,大家聚集。我所不 认识 的那些下流人 聚集 攻击我;他们不 住地 把我撕裂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, '他们如同席 上好嬉笑的 狂妄人 向我 咬 牙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, '主啊,你看著 不理要到几时呢?求你救 我的灵魂 脱离他们的残害!救我的生命(生命:原文是独一者)脱离少壮狮子! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, '我在大 会中 要称谢你,在众 民中 要赞美你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, '求你不 容那无理 与我为仇的 向我 夸耀!不容那无故 恨 我的向我挤 眼! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, '因为 他们不 说 和平话,倒想出 诡诈的 言语害 地 上的安静人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, '他们大大 张口 攻击我,说:阿哈,阿哈,我们的眼 已经看见了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, '耶和华啊,你已经看见了,求你不要 闭口!主啊,求你不要 远离 我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, '我的 神 我的主啊,求你奋兴 醒起,判清我的事,伸明我的冤! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, '耶和华─我的 神啊,求你按你的公义 判断我,不 容他们向我 夸耀! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, '不 容他们心里 说:阿哈,遂我们的心愿 了!不 容他们说:我们已经把他吞了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, '愿 那喜欢 我遭难 的一同 抱愧 蒙羞!愿 那向我 妄自尊大的 披 惭愧,蒙羞辱! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, '愿 那喜悦我冤屈得伸的(冤屈得伸:原文是公义)欢呼 快乐;愿 他们常 说:当尊耶和华 为大!耶和华喜悦 他的仆人 平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, '我的舌头 要终 日 论说 你的公义,时常赞美你。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, '(耶和华 的仆人 大卫的诗,交与伶长。)恶人的 罪过 在他心 里 说:我眼 中 不 怕 神! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, ' 他自 夸 自媚,以为他的罪孽 终不显露,不被恨恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, '他口 中的言语 尽是罪孽 诡诈;他与智慧 善行 已经断绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, '他在 床上 图谋 罪孽,定意行 不 善的 道,不 憎恶 恶事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, '耶和华啊,你的慈爱 上及诸天;你的信实 达到 穹苍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, '你的公义 好像高 山;你的判断 如同深 渊。耶和华啊,人民、牲畜,你都救护。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, '神啊,你的慈爱 何其 宝贵!世人 投靠 在你翅膀 的荫下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, '他们必因你殿 里的肥甘 得以饱足;你也必叫他们喝 你乐 河的水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, '因为,在你那里 有生命 的源头;在你的光中,我们必得见 光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, '愿 你常施 慈爱 给认识你的人,常以公义 待心 里正直的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, '不容 骄傲人 的脚 践踏我;不容 凶恶人 的手 赶逐我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, '在那里,作 孽 的人已经仆倒;他们被推倒,不 能 再起来。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, '(大卫的诗。)不要 为作恶的 心怀不平,也不要 向那行 不义 的生出嫉妒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, '因为 他们如草 快 被割下,又如青 菜 快要枯干。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, '你当倚靠 耶和华 而行 善,住在 地上,以他的信实 为粮; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, '又要以 耶和华 为乐,他就将你心 里所求的 赐给 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, '当将你的事 交托 讬 耶和华,并倚靠 他,他 就必成全。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, '他要使你的公义 如光 发出,使你的公平 明如正午。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, '你当默然 倚靠耶和华,耐性等候 他;不要 因那道路 通达的和那 恶谋 成就的 心怀不平。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, '当止住 怒气,离弃 忿怒;不要 心怀不平,以致 作恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, '因为 作恶的 必被剪除;惟有等候 耶和华的必 承受 地土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, '还有 片时,恶人 要归于 无有;你就是细察 他的住处 也要归于 无有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, '但谦卑人 必承受 地土,以 丰盛 的平安 为乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, '恶人 设谋害 义人,又向他 咬 牙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, '主 要笑 他,因 见 他受罚的日子 将要来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, '恶人 已经弓 上弦,刀 出鞘,要打倒 困苦 穷乏的人,要杀害 行动 正直的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, '他们的刀 必刺 入自己的心;他们的弓 必被折断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, '一个义人所有的 虽少,强 过许多 恶人 的富余 馀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, '因为 恶人 的膀臂 必被折断;但耶和华 是扶持 义人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, '耶和华 知道 完全人 的日子;他们的产业 要存 到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, '他们在急难 的时候 不致 羞愧,在饥荒 的日子 必得饱足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, '恶人 却 要灭亡。耶和华 的仇敌 要像羊羔的脂油(或译:像草地的华美);他们要消灭,要如烟 消灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, '恶人 借贷 而不 偿还;义人 却恩待人,并且施舍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, ' 蒙耶和华赐福的 必承受 地土;被他咒诅的 必被剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, '义人 的脚步 被耶和华 立定;他的道路,耶和华也喜爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, '他虽 失脚 也不致 全身仆倒,因为 耶和华 用手 搀扶他(或译:搀扶他的手)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, '我从前 年幼,现在 年老,却未 见过 义人 被弃,也未见过他的后裔 讨 饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, '他终 日 恩待人,借给人;他的后裔 也蒙福! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, '你当离 恶 行 善,就可永远 安居。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, '因为,耶和华 喜爱 公平,不 撇弃 他的圣民;他们永 蒙保佑,但恶人 的后裔 必被剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, '义人 必承受 地土,永 居 其上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, '义人 的口 谈论 智慧;他的舌头 讲说 公平。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, '神 的律法 在他心里;他的脚 总不 滑跌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, '恶人 窥探 义人,想要 杀他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, '耶和华 必不 撇 他在恶人手中;当审判的时候,也不 定他的罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, '你当等候 耶和华,遵守 他的道,他就抬举你,使你承受 地土;恶人 被剪除的时候,你必看见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, '我见过 恶人 大有势力,好像一根青翠 树 在本土生发。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, '有人从那里经过,不料,他没有了;我也寻找他,却寻 不著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, '你要细察 那完全人,观看 那正直人,因为 和平 人 有好结局。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, '至于 犯法的人,必一同 灭绝;恶人 终 必剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, '但义人 得救 是由于 耶和华;他在患难 时 作他们的营寨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, '耶和华 帮助他们,解救他们;他解救他们 脱离恶人,把他们救出来,因为 他们投靠 他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, '(大卫的 记念 诗。)耶和华啊,求你不要 在怒中 责备我,不要在烈怒中 惩罚我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, '因为,你的箭 射 入我身;你的手 压住 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, '因 你的恼怒,我的肉 无一 完全;因 我的罪过,我的骨头 也不 安宁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, ' 我的罪孽 高过 我的头,如同重 担 叫我 担当不起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, '因 我的愚昧,我的伤 发臭 流脓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, '我疼痛,大大 拳曲,终 日 哀痛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, ' 我满 腰 是火;我的肉 无一 完全。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, '我被压伤,身体疲倦;因心 里不安,我就唉哼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, '主啊,我的心愿  都 在你面前;我的叹息 不 向你 隐瞒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, '我心 跳动,我力 衰微,连我眼中 的光 也 没有了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, '我的良朋 密友 因我的灾病 都躲在旁边 站著;我的亲戚本家 也远远地 站立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, '那寻索 我命 的设下网罗;那想要 害我的 口出 恶言,终 日 思想 诡计。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, '但我 如聋子 不 听,像哑巴 不 开  口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, '我 如不 听见 的 人,口中 没有 回话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, ' 耶和华啊,我仰望 你!主─我的 神啊,你 必应允我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, ' 我曾说:恐怕 他们向我 夸耀;我失 脚的时候,他们向我 夸大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, ' 我 几乎 跌倒;我的痛苦 常 在我面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, ' 我要承认 我的罪孽;我要因我的罪 忧愁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, '但我的仇敌 又活泼 又强壮,无理 恨我的 增多了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, '以恶 报善 的与我作对,因 我是追求 良善。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, '耶和华啊,求你不要 撇弃我!我的 神啊,求你不要 远离 我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, '拯救我 的主啊,求你快快 帮助我!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, '(大卫的 诗,交与伶长 耶杜顿。)我曾说:我要谨慎 我的言行,免得我舌头 犯罪;恶人 在我面前 的时候,我要用嚼环 勒住 我的口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, '我默然 无声,连好话 也不出口;我的愁苦 就发动了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, '我的心 在我里面 发热。我默想的时候,火 就烧起,我便用舌头 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, '耶和华啊,求你叫我晓得 我身之终!我的寿 数 几何?叫我知道 我的生命不长! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, ' 你使 我的年日 窄如手掌;我一生的年数,在你面前 如同无有。各 人 最稳妥的时候,真是 全然 虚幻。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, '世人 行动 实 系幻影。他们忙乱,真是 枉然;积蓄财宝,不 知 将来有谁 收取。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, '主啊,如今 我等 什么呢?我的指望 在乎你! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, '求你救我 脱离一切 的过犯,不要 使我 受愚顽人 的羞辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, '因 我所遭遇的是出于  你,我就默然 不 语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, '求你把你的责罚 从我身上 免去;因你手 的责打,我 便消灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, '你因 人 的罪恶 惩罚他的时候,叫他的笑容(的笑容:或译所喜爱的)消灭,如衣被虫所咬。世人 真是 虚幻!(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, '耶和华啊,求你听 我的祷告,留心听 我的呼求! 我流泪,求你不要 静默无声!因为 我 在你面前 是客旅,是寄居的,像我列 祖一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, '求你宽容 我,使我在去 而不返 之先 可以力量复原。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, '(大卫的 诗,交与伶长。)我曾耐性 等候 耶和华; 他垂听 我的呼求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, '他从祸 坑里,从淤 泥中,把我拉上来,使我的脚 立 在 磐石上,使我脚步 稳当。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, '他使 我口 唱新 歌,就是赞美我们 神的话。许多人 必看见 而惧怕,并要倚靠 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, '那 倚靠 耶和华、不 理会 狂傲 和偏向 虚假之辈的,这人 便为有福! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, '耶和华─我的 神啊,你 所行的 奇事,并你向我们 所怀的意念 甚多,不能 向你 陈明。若要陈明,其事不可胜 数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, '祭物 和礼物,你不 喜悦;你已经开 通 我的 耳朵。燔祭 和赎罪祭 非 你所要。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, '那时 我说:看哪,我来了!我的事 在经 卷上 已经记载了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, '我的 神啊,我乐意 照你的旨意 行;你的律法 在我心 里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, '我在大 会中 宣传 公义的佳音; 我必不 止住 我的嘴唇。耶和华啊,这是你 所知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, '我未 曾把你的公义 藏 在心 里;我已陈明 你的信实 和你的救恩;我在大 会中 未 曾隐瞒 你的慈爱 和诚实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, '耶和华啊,求你 不要 向我 止住 你的慈悲!愿 你的慈爱 和诚实 常常 保佑我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, '因 有 无 数 的祸患 围困 我,我的罪孽 追上了我,使我不 能 昂首;这罪孽比我的头 发 还多,我就心 寒胆战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, '耶和华啊,求你开 恩 搭救我!耶和华啊,求你速速 帮助我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, '愿 那些寻找我、要灭 我命的,一同 抱愧 蒙羞!愿 那些喜悦 我受害的,退 后 受辱! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, '愿 那些对我 说 阿哈、阿哈的,因 羞愧 而败亡! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, '愿 一切 寻求你的,因你 高兴 欢喜!愿 那些喜爱 你救恩的,常 说:当尊耶和华 为大! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, '但我 是困苦 穷乏的,主 仍顾念 我;你 是帮助我的,搭救我的。 神啊,求你不要 耽延!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, '(大卫的 诗,交与伶长。)眷顾 贫穷 的有福了!他遭难 的日子,耶和华 必搭救他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, '耶和华 必保全他,使他存活;他必在地上 享福。求你不要 把他交给 仇敌,遂其所愿 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, '他病重 在 榻,耶和华 必扶持他;他在病中,你必给他铺 床。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, '我 曾说:耶和华啊,求你怜恤我,医治 我!因为 我得罪了 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, '我的仇敌 用恶言 议论 我说:他几时 死,他的名 才灭亡呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, ' 他来 看 我就说 假话;他心 存 奸恶,走 到外边 才说出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, '一切 恨我的,都 交头接耳地议论 我;他们设计 要害 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, '他们说:有怪 病 贴 在他身上; 他已躺卧,必不能 再 起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, '连 我知己 的朋友,我所 倚靠、吃过 我饭 的也用脚 踢 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, '耶和华啊,求你 怜恤我,使我起来,好报复 他们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, '因 我的仇敌 不得 向我 夸胜,我从此 便知道 你喜爱 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, '你因我纯正 就扶持 我,使我 永远 站 在你的面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, '耶和华─以色列的 神 是应当称颂的,从亘古 直到 永远。阿们!阿们!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, '(可拉 后裔的 训诲诗,交与伶长。) 神啊, 我的心 切慕 你,如鹿 切慕 溪 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, '我的心 渴想 神,就是永生 神;我几时 得朝 见 神呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, '我 昼 夜 以眼泪 当 饮食;人不住地 对我 说:你的 神 在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, ' 我从前与众人 同往,用欢呼 称赞 的声音 领他们 到 神 的殿里,大家 守节。我追想 这些事,我的心 极其悲伤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, '我的心哪,你为何 忧闷?为何在我里面 烦躁?应当仰望 神,因 他笑脸 帮助我;我还要 称赞他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, '我的 神啊,我的心 在我里面 忧闷,所以 我从约旦 地,从黑门岭,从米萨 山 记念你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, '你的瀑布 发声,深渊 就与 深渊 响应;你的波浪 洪涛 漫过 我身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, '白昼,耶和华 必向我施 慈爱;黑夜,我 要歌颂 祷告 赐我生命的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, '我要对 神─我的磐石 说:你为何 忘记我呢?我为何 因仇敌 的欺压 时常 哀痛呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, '我的敌人 辱骂我,好像打碎 我的骨头,不住地 对我 说:你的 神 在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, '我的心哪,你为何 忧闷?为何 在我里面 烦躁?应当仰望 神,因 我还要 称赞他。他是我脸上的光荣(原文是帮助),是我的 神。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, '神啊,求你伸我的冤,向不 虔诚的 国 为我辨 屈;求你救我 脱离诡诈 不义 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, '因为 你 是赐我力量的 神,为何 丢弃我呢?我为何 因仇敌 的欺压 时常 哀痛呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, '求你发出 你的亮光 和真实,好 引导我,带我 到 你的圣 山,到 你的居所! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, '我就走 到 神 的祭坛,到 我最喜乐的 神那里。 神啊,我的 神,我要弹琴 称赞你! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, '我的心哪,你为何 忧闷?为何 在我里面 烦躁?应当仰望 神,因 我还要 称赞他。他是我脸上的光荣(原文是帮助),是我的 神。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, '(可拉 后裔的 训诲诗,交与伶长。) 神啊,你在古 时,我们列祖的日子 所行 的事,我们亲耳 听见了;我们的列祖 也给我们 述说过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, '你 曾用手 赶出 外邦人,却栽培了我们列祖;你苦待 列邦,却叫我们列祖发达。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, '因为 他们不是 靠自己的刀剑 得 地土,也不是 靠自己的膀臂 得胜,乃是 靠你的右手、你的膀臂,和你脸上 的亮光,因为 你喜悦他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, '神啊,你 是 我的王;求你出令 使雅各 得胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, '我们靠你 要推倒 我们的敌人,靠你的名 要践踏 那起来攻击我们的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, '因为,我必不 靠 我的弓;我的刀 也不能 使我得胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, '惟 你救了我们 脱离敌人,使恨我们的人 羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, '我们终 日因 神 夸耀,还要永远 称谢 你的名。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, '但 如今你丢弃了我们,使我们受辱,不 和我们的军兵 同去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, '你使我们向 敌人 转身 退后;那恨我们的人 任意抢夺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, '你使我们 当作快要被吃 的羊,把我们分散 在列邦中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, '你卖了 你的子民 也不 赚利,所得的价值 并不 加添你的资财。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, '你使我们 受邻国 的羞辱,被四围的人 嗤笑 讥刺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, '你使我们 在列邦中 作了笑谈,使众民 向我们摇 头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, '我的凌辱 终 日 在我面前,我脸上 的羞愧 将我遮蔽, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, '都因那辱骂 毁谤人 的声音,又因仇敌 和报仇人 的缘故。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, '这 都 临到我们身上,我们却没有 忘记你,也没有 违背 你的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, '我们的心 没有 退 后;我们的脚 也没有偏 离 你的路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, ' 你在野狗 之处 压伤我们,用死荫 遮蔽 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, '倘若 我们忘了 神 的名,或向别 神 举 手, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, '神 岂不 鉴察 这事吗?因为 他 晓得 人心里 的隐秘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, ' 我们为你的缘故 终 日 被杀;人看我们 如将宰的 羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, '主啊,求你睡醒,为何 尽 侭睡呢?求你兴起,不要 永远 丢弃我们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, '你为何 掩 面,不顾 我们所遭的苦难 和所受的欺压? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, ' 我们的性命 伏 于 尘土;我们的肚腹 紧贴 地面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, '求你起来 帮助 我们!凭 你的慈爱 救赎我们!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, '(可拉 后裔的 训诲诗,又是爱慕 歌,交与伶长。调用 百合花。)我心里 涌出 美 辞;我 论到 我为王 做的事,我的舌头 是快手 笔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, '你比世人 更美;在你嘴里 满有 恩惠;所以 神 赐福给你,直到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, '大能者啊,愿 你腰间 佩 刀,大有荣耀 和威严! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, '为 真理、谦卑、公义 赫然 坐车前往,无不得胜;你的右手 必显明 可畏的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, '你的箭 锋快,射中王 敌 之心;万民 仆倒 在你以下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, '神啊,你的宝座 是永永远远的;你的国 权 是正直的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, '你喜爱 公义,恨恶 罪恶;所以 神─就是你的 神─用喜乐 油 膏你,胜过膏你的同伴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, '你的衣服 都 有没药、沉香、肉桂的香气; 象牙 宫 中有丝弦乐器 的声音使你欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, '有君王 的女儿 在你尊贵妇女之中;王后 佩戴俄斐 金饰 站 在你右边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, '女子啊,你要听,要想,要侧 耳而听!不要记念 你的民 和你的父 家, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, '王 就羡慕 你的美貌;因为 他是 你的主,你当敬拜 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, '泰尔的民(原文是女子)必来送礼;民 中的富足人 也必向你 求恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, '王 女 在宫里 极其 荣华;她的衣服 是用金 线 缐绣的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, '她要穿锦绣的衣服,被引 到王前;随从她 的陪伴 童女 也要被带 到你面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, '她们要欢喜 快乐 被引导;她们要进 入王 宫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, '你的子孙 要 接续 你的列祖;你要立他们 在全 地 作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, '我必叫你的名 被万 代 记念,所以 万民 要永永远远 称谢你。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, '(可拉 后裔的 诗歌,交与伶长。调用 女音。) 神 是我们的 避难所,是我们的力量,是我们在患难中 随时的 帮助。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, '所以,地 虽改变,山 虽摇动 到海 心, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, '其中的水 虽匉訇 翻腾,山 虽因海涨 而战 抖,我们也不 害怕。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, '有一道河,这河的分汊使 神 的城 欢喜;这城就是至高者 居住 的圣所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, '神 在其中,城必不 动摇;到天一 亮, 神 必帮助这城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, '外邦 喧嚷,列国 动摇; 神发 声,地 便镕化。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, '万军 之耶和华 与我们同在;雅各的 神 是我们的 避难所!(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, '你们来 看 耶和华 的作为,看他使 地 怎样 荒凉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, '他止息 刀兵,直到 地 极;他折 弓、断 枪,把战 车 焚烧 在火中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, '你们要休息,要知道 我是 神!我必在外邦中 被尊崇,在遍地上 也被尊崇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, '万军 之耶和华 与我们同在;雅各的 神 是我们的 避难所!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, '(可拉 后裔的 诗,交与伶长。)万 民哪,你们都要拍 掌!要用夸胜 的声音向 神 呼喊! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, '因为 耶和华 至高者 是可畏的;他是治理 全 地 的大 君王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, '他叫万民 服 在我们以下,又叫列邦 服在我们脚 下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, '他为我们 选择 产业,就是 他所 爱 之雅各 的荣耀。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, '神 上升,有喊声相送;耶和华上升,有角 声相送。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, '你们要向 神 歌颂,歌颂!向我们王 歌颂,歌颂! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, '因为 神 是全 地 的王;你们要用悟性 歌颂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, '神 作王治理 万国; 神 坐 在 他的圣 宝座上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, '列邦 的君王 聚集 要作亚伯拉罕之 神 的民。因为 世界 的盾牌是属 神的;他为至 高!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, '(可拉 后裔的 诗 歌。)耶和华 本为大!在我们 神 的城中,在他的圣 山上,该受大 赞美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, '锡安 山─大 君王 的城,在北 面 居高 华美,为全 地 所喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, '神 在其宫中,自显 为避难所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, ' 看哪,众王 会合,一同 经过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, '他们 见了 这城就 惊奇 丧胆,急忙逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, '他们在那里 被战 兢 疼痛 抓住,好像产难的妇人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, '神啊,你用东 风 打破 他施 的船只。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, '我们在万军 之耶和华 的城中─就是我们 神 的城中─所 看见的,正如 我们所听见的。 神 必坚立这城,直到 永远。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, '神啊,我们在你的殿 中 想念 你的慈爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, '神啊,你受的赞美 正与你的名 相称,直到 地 极!你的右手 满了 公义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, '因 你的判断,锡安 山 应当欢喜,犹大的城邑(原文是女子)应当快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, '你们当周游 锡安,四围旋绕,数点 城楼, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, '细 看 她的外郭,察看 她的宫殿,为要 传说 到后 代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, '因为 这 神 永永远远为我们的 神;他必 作我们引路的,直到 死时。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, '(可拉 后裔的 诗,交与伶长。)万 民哪,你们都当听 这话!世上 一切的 居民, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, '无论 上流 下流,富足 贫穷,都 当留心听! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, '我口 要说 智慧的言语;我心 要想 通达的道理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, '我要侧 耳 听比喻,用琴 解 谜语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, '在患难的 日子,奸恶 随我脚跟,四面环绕我,我何必 惧怕? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, '那些倚仗 财货 自夸 钱财 多的人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, '一个 也无法 赎 自己的弟兄,也不能 替他将赎价 给 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, '叫他长远 活著,不 见 朽坏;因为赎 他生命 的价值极贵,只可永远 罢休。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, '他必 见 智慧人 死,又见愚顽人 和畜类人 一同 灭亡,将他们的财货 留 给别人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, '他们心里思想:他们的家室 必永存,住宅 必留到万代;他们以自己的名 称 自己的地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, '但人 居尊贵中 不能 长久,如同 死亡 的畜类一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, '他们行的这 道 本为自己的 愚昧;但他们以后的人 还佩服 他们的话语。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, '他们如同羊群 派定 下阴间;死亡 必作他们的牧者。到了早晨,正直人 必管辖 他们;他们的美容 必被阴间 所灭,以致无处可存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, '只是 神 必救赎 我的灵魂 脱离阴间 的权柄,因 他必收纳我。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, ' 见人 发财、 家室 增 荣的时候,你不要 惧怕; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, '因为,他死的时候 什么也 不能 带去;他的荣耀 不能 随他 下去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, '他活著的时候,虽然 自 夸为有福(你若 利 己,人必夸奖你); ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, '他仍必归 到 他历代 的祖宗那里, 永 不 见 光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, '人 在尊贵中 而不 醒悟,就如 死亡 的畜类一样。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, '(亚萨的 诗。)大能者 神─耶和华 已经发言 招呼 天下,从日 出 之地到 日落之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, '从全 美 的锡安中, 神 已经发光了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, '我们的 神 要来,决不 闭口。有烈火 在他面前 吞灭;有暴风在他四围 大 刮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, '他招呼 上 天 下地,为要审判 他的民, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, '说:招聚 我的圣民 到我这里来,就是那些用 祭物 与我立 约的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, '诸天 必表明 他的公义,因为 神 是 施行审判的。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, '我的民哪,你们当听 我的话!以色列啊,我要劝戒 你;我是 神,是你的 神! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, '我并不 因 你的祭物 责备你;你的燔祭 常 在我面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, '我不 从你家中 取 公牛,也不从你圈内 取山羊; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, '因为,树林 中的百 兽 是我的,千 山上 的牲畜也是我的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, '山 中的飞鸟,我都 知道;野地 的走兽 也都属我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, '我若 是饥饿,我不用 告诉 你,因为 世界 和其中所充满的 都是我的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, '我岂吃 公牛 的肉呢?我岂喝 山羊 的血呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, '你们要以感谢 为祭献与 神,又要向至高者 还 你的愿 , ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, '并要在患难 之日 求告我;我必搭救你,你也要荣耀我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, '但 神 对恶人 说:你 怎 敢传说 我的律例,口中 提到 我的约呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, '其实你 恨恶 管教,将我的言语 丢 在背后。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, ' 你见了 盗贼 就乐意 与他同伙 夥,又与 行奸淫的人 一同有分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, '你口 任说 恶言;你舌 编造 诡诈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, '你坐著 毁谤 你的兄弟,谗毁 你亲母 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, '你行了 这些事,我还闭口不言,你想 我恰 和你一样;其实我要责备你,将这些事摆在 你眼前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, '你们忘记 神的,要 思想 这事,免得 我把你们撕碎,无人 搭救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, '凡以感谢 献上为祭的 便是荣耀我;那按正路 而行的,我必使他得著 我 的救恩。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, '(大卫 与 拔示巴 同室 以后,先知 拿单 来 见他;他 作这诗,交与伶长。) 神啊,求你按你的慈爱 怜恤我!按你丰盛的 慈悲 涂抹 我的过犯! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, '求你将我的罪孽 洗除 净尽,并洁除 我的罪! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, '因为,我 知道 我的过犯;我的罪 常 在我面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, '我向你 犯罪,惟独得罪了你;在你眼前 行了 这恶,以致 你责备我的时候 显为公义,判断我的时候 显为清正。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, ' 我是在罪孽里 生的,在我母亲 怀胎 的时候就有了罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, ' 你所喜爱 的是内里 诚实;你在我隐密处,必使我得 智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, '求你用牛膝草 洁净我,我就干净;求你洗涤我,我就比雪 更白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, '求你使我得听 欢喜 快乐的声音,使你所压伤 的骨头 可以踊跃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, '求你掩 面 不看我的罪,涂抹 我一切的 罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, '神啊,求你为我 造 清洁的 心,使我里面 重新有正直(或译:坚定)的灵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, '不要 丢弃我,使我离开 你的面;不要 从我 收回 你的圣 灵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, '求你使我 仍得 救恩 之乐,赐我乐意的 灵 扶持我, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, '我就把你的道 指教 有过犯的人,罪人 必归顺 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, '神啊,你是拯救我的 神;求你救我脱离 流人血的罪!我的舌头 就高声歌唱 你的公义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, '主啊,求你使我嘴唇 张开 ,我的口 便传扬 赞美你的话! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, ' 你本不 喜爱 祭物,若喜爱,我就献上;燔祭,你也不 喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, '神 所要的祭 就是忧伤的 灵; 神啊,忧伤 痛悔 的心,你必不 轻看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, '求你随你的美意 善待 锡安,建造 耶路撒冷 的城墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, '那时,你必喜爱 公义 的祭 和燔祭 并全牲的燔祭;那时,人必将公牛 献 在 你坛上。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, '(以东人 多益 来 告诉 扫罗 说:大卫 到了 亚希米勒 家。那时,大卫 作这训诲诗,交与伶长。)勇士啊,你为何 以作恶 自夸? 神 的慈爱 是常存的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, '你的舌头 邪恶 诡诈,好像剃头刀,快利 伤人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, '你爱 恶 胜似爱善,又爱说谎,不爱说 公义。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, '诡诈 的舌头啊,你爱 说一切 毁灭 的话! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, '神 也要 毁灭你,直到永远;他要把你拿去,从你的帐棚中 抽出,从活人 之地 将你拔出。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, '义人 要看见 而惧怕,并要笑 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, '说:看哪,这就是那不 以 神 为他力量 的人,只倚仗 他丰富的 财物,在邪恶上 坚立自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, '至于 我,就像 神 殿中 的青 橄榄树;我永永远远 倚靠 神 的慈爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, '我要称谢你,直到永远,因为 你行了这事。我也要在你圣民 面前 仰望 你的名; 这名本为美好。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, '(大卫的 训诲诗,交与伶长。调用麻哈拉。)愚顽人 心里 说:没有 神。他们都是邪恶,行了可憎恶的 罪孽;没有一个人 行 善。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, '神 从天上 垂看 世人,要看 有 明白的没有?有寻求他的没有? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, '他们各人都 退后,一同 变为污秽;并没有 行 善的,连 一个 也没有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, '作 孽 的没有 知识吗?他们吞吃 我的百姓 如同吃 饭一样,并不 求告 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, '他们在无 可 惧怕 之处 就大大害怕,因为 神 把那安营攻击你之人 的骨头 散开 了。你使他们蒙羞,因为 神 弃绝了他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, '但愿  以色列 的救恩 从锡安而出。 神 救回 他被掳的 子民那时,雅各 要快乐,以色列 要欢喜。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, '(西弗人 来 对扫罗 说:大卫 岂不是 在我们 那里藏身吗?那时,大卫 作这训诲诗,交与伶长。用丝弦的乐器。) 神啊,求你以你的名 救我,凭你的大能 为我伸冤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, '神啊,求你听 我的祷告,留心听 我口中 的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, '因为,外人 起来 攻击我,强暴人 寻索 我的命;他们眼中 没有 神。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, ' 神 是帮助 我的, 是扶持 我命的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, '他要报应 我仇敌 所行的恶;求你凭你的诚实 灭绝他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, '我要把甘心祭 献 给你。耶和华啊,我要称赞 你的名; 这名本为美好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, ' 他从一切的 急难 中把我救出来;我的眼睛 也看见了 我仇敌遭报。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, '(大卫的 训诲诗,交与伶长。用丝弦的乐器。) 神啊,求你留心听 我的祷告,不要 隐藏 不听我的恳求! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, '求你侧耳听 我,应允我。我哀叹 不安,发声唉哼, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, '都因仇敌 的声音, 恶人 的欺压;因为 他们将罪孽 加 在我身上,发怒气 逼迫我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, '我心 在我里面 甚是疼痛;死 的惊惶 临 到我身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, '恐惧 战 兢 归 到我身;惊恐 漫过了我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, '我说:但愿  我有 翅膀 像鸽子,我就飞去,得享安息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, ' 我必远 游,宿 在旷野。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, '我必速速 逃到避所,脱离狂 风 暴雨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, '主啊,求你吞灭他们,变乱 他们的舌头!因为 我在城中 见了 强暴 争竞的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, '他们在城墙上 昼 夜 绕行;在城内 也有罪孽 和奸恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, '邪恶 在其中;欺压 和诡诈 不 离 街市。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, '原来 不是 仇敌 辱骂我,若是仇敌,还可忍耐;也不是 恨我的人 向我 狂大,若是恨我的人就必躲避 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, '不料是你;你 原与我平等,是我的同伴,是我知己的朋友! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, '我们素常 彼此 谈论,以为甘甜;我们与群众在 神 的殿中 同行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, '愿 死亡 忽然临 到他们!愿 他们活活地 下入 阴间!因为 他们的住处,他们的心中,都是邪恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, '至于 我,我要求告 神;耶和华 必拯救我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, '我要晚上、早晨、晌午 哀声 悲叹;他也必听 我的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, '他救赎 我命 脱离攻击 我的人,使我得享平安,因为 与我相争的人 甚多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, '那 没有 更变、不 敬畏 神的人,从太古 常存的 神 必听见 而苦待他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, '他背了 约,伸 手 攻击与他和好的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, '他的口 如奶油 光滑,他的心 却怀著争战 ;他的话 比油 柔和,其实是 拔出来的刀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, '你要把你的重担 卸 给 耶和华,他 必抚养你;他永 不 叫 义人 动摇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, '神啊,你 必使恶人下 入灭亡 的坑;流人血、行诡诈 的人 必活不 到半 世,但我 要倚靠 你。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, '(非利士人 在迦特 拿住大卫。那时,他 作这金诗,交与伶长。调用 远方无声鸽。) 神啊,求你怜悯我,因为 人 要把我吞了,终 日 攻击 欺压我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, '我的仇敌 终 日 要把我吞了,因 逞骄傲 攻击 我 的人甚多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, '我 惧怕 的时候 要倚靠 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, '我倚靠 神,我要赞美 他的话;我倚靠 神,必不 惧怕。血气之辈 能把我 怎么样呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, '他们终 日 颠倒 我的话;他们一切的 心思 都是要害 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, '他们 聚集,埋伏 窥探 我的脚踪, 等候 要害我的命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, '他们岂能 因 罪孽 逃脱吗? 神啊,求你在怒中 使众民 堕落! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, '我几次流离,你都记数;求你 把我眼泪 装 在你的皮袋里。这不 都记在你册子上吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, '我呼求 的日子, 我的仇敌 都要转身 退后。 神 帮助我,这是 我所知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, '我倚靠 神,我要赞美 他的话;我倚靠耶和华,我要赞美 他的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, '我倚靠 神,必不 惧怕。人 能把我 怎么样呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, '神啊,我向你所许的愿  在我身上;我要将感谢祭 献 给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, '因为 你救 我的命 脱离死亡。你岂不是 救护我的脚 不跌倒、使我在生命 光中 行在 神 面前吗?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, '(大卫 逃避 扫罗,藏在洞里。那时,他 作这金诗,交与伶长。调用休要毁坏。) 神啊,求你怜悯我,怜悯我!因为 我的心 投靠 你。我要投靠 在你翅膀 的荫下,等到 灾害 过去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, '我要求告 至高的 神,就是为我 成全诸事的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, '那要吞我的人 辱骂我的时候, 神 从天上 必施 恩救我, 也必向我发出 慈爱 和诚实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, '我的性命 在狮子 中间;我躺卧 在性如烈火 的世人当中。他们的牙齿 是枪、箭;他们的舌头 是快 刀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, '神啊,愿 你崇高 过于  诸天!愿 你的荣耀 高过 全 地! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, '他们为我的脚 设下 网罗,压制 我的心;他们在我面前 挖了 坑,自己反掉 在其中。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, '神啊,我心 坚定,我心 坚定;我要唱诗,我要歌颂! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, '我的灵(原文是荣耀)啊,你当醒起!琴瑟啊,你们当醒起!我自己要极早 醒起! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, '主啊,我要在万民中 称谢你,在列邦中 歌颂你! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, '因为,你的慈爱 高 及 诸天;你的诚实 达到 穹苍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, '神啊,愿 你崇高 过于  诸天!愿 你的荣耀 高过 全 地!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, '(大卫的 金诗,交与伶长。调用休要毁坏。)世人哪,你们默然不 语,真 合公义吗?施行审判,岂按正直吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, '不然!你们是心中 作 恶;你们在地上 秤出 你们手 所行的强暴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, '恶人 一出母胎就与 神疏远,一离母腹 便走错路,说 谎话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, '他们的 毒气 好像 蛇 的毒气;他们好像 塞 耳 的聋 虺, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, ' 不 听 行法术 的声音,虽用极灵的 咒语也是不听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, '神啊,求你敲碎 他们口中 的牙;耶和华啊,求你敲掉 少壮狮子 的大牙! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, '愿 他们消灭,如 急流的 水一般;他们瞅准 射箭的时候,愿 箭头仿佛 砍断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, '愿 他们像 蜗牛 消化 过去,又像妇人 坠落未 见 天日 的胎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, '你们用荆棘烧火,锅 还未 热,他要用旋风把 青的和 烧著的 一齐刮去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, ' 义人 见 仇敌遭报 就欢喜,要在恶人 的血中 洗 脚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, '因此,人 必说:义人 诚然 有善报;在地上 果 有 施行判断的 神!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, '(扫罗 打发 人窥探 大卫的房屋,要杀他。那时,大卫 作这金诗,交与伶长。调用休要毁坏。)我的 神啊,求你救我 脱离仇敌,把我安置在高处,得脱那些起来攻击我的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, '求你救我 脱离作 孽 的人和 喜爱流人血 的人! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, '因为, 他们埋伏 要害我的命;有能力的人 聚集 来攻击我。耶和华啊,这不是 为我的过犯,也不是 为我的罪愆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, '我虽然无 过,他们预备整齐,跑来攻击我。求你兴起 鉴察,帮助我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, '万军之 神─耶和华 以色列的 神啊!求你 兴起,惩治 万 邦!不要 怜悯 行诡诈 的恶人!(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, '他们晚上 转回,叫号 如狗,围城 绕行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, ' 他们口中 喷吐恶言,嘴里 有刀;他们说: 有谁 听见? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, '但你─耶和华 必笑话 他们;你要嗤笑 万 邦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, '我的力量啊,我必仰望 你,因为 神 是我的高台。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, '我的 神 要以慈爱 迎接我; 神 要叫我看见 我仇敌遭报。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, '不要 杀他们,恐怕 我的民 忘记。主啊,你是我们的盾牌;求你用你的能力 使他们四散,且降为卑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, '因他们口中 的罪 和嘴里 的言语,并咒骂 虚谎 的话,愿 他们在骄傲之中 被缠住了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, ' 求你发怒,使他们消灭,以致归于 无有,叫他们知道 神 在雅各中间 掌权,直到地 极。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, '到了晚上,任凭他们转回;任凭他们叫号 如狗,围城 绕行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, '他们 必走来走去,寻找食物,若 不得 饱 就终夜在外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, '但我 要歌颂 你的力量,早晨 要高唱 你的慈爱;因为 你作过 我的 高台,在我 急难 的日子 作过我的避难所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, '我的力量啊,我要歌颂 你;因为 神 是我的高台,是赐恩与我的 神。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, '(大卫与 两河间的亚兰 并 琐巴的亚兰 争战 的时候,约押 转回,在盐 谷 攻击 以东,杀了一万二 千人。那时,大卫 作这金诗 叫人学习,交与伶长。调用 为证的百合花。) 神啊,你丢弃了我们,使我们破败;你向我们发怒,求你使我们 复兴! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, '你使地 震动,而且崩裂;求你将裂口 医好,因为 地摇动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, '你叫你的民 遇见 艰难;你叫我们喝 那使人东倒西歪 的酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, '你把旌旗 赐 给敬畏你的人,可以为 真理 扬起来。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, '求你应允我们,用右手 拯救我们,好叫 你所亲爱的人 得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, '神 已经指著他的圣洁 说(说:或译应许我):我要欢乐;我要分开  示剑,丈量 疏割 谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, '基列 是我的,玛拿西 也是我的。以法莲 是护卫 我头的;犹大 是我的杖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, '摩押 是我的沐浴 盆;我要向 以东 抛 鞋。 非利士啊,你还能因我欢呼吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, '谁 能领我进 坚固 城?谁 能引我 到 以东地? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, '神啊,你 不是 丢弃了我们吗? 神啊,你不 和我们的军兵 同去吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, '求你 帮助 我们 攻击敌人,因为人 的帮助 是枉然的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, '我们倚靠 神 才得施展 大能,因为践踏 我们敌人 的就是他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, '(大卫的诗,交与伶长。用 丝弦的乐器。) 神啊,求你听 我的呼求,侧耳听 我的祷告! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, '我心里 发昏的时候,我要从地 极 求告 你。求你领我 到那比我更 高的 磐石! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, '因为 你作过 我的 避难所,作过我的坚固 台,脱离 仇敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, '我要永远 住 在你的帐幕里!我要投靠 在你翅膀 下的隐密处!(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, '神啊,你 原是 听了 我所许的愿 ;你将产业 赐给 敬畏 你名的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, '你要加添 王 的寿数;他的年岁 必存到世世。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, '他必永远 坐在 神 面前;愿 你预备 慈爱 和诚实 保佑他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, '这样,我要歌颂 你的名,直到永远,好天 天 还 我所许的愿 。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, '(大卫的 诗,照 耶杜顿的作法,交与伶长。)我的心 默默无声,专 等候 神;我的救恩 是从他而来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, '惟独 他是 我的磐石,我的拯救;他是我的高台,我必不 很 动摇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, '你们大家 攻击 一人,把他毁坏,如同毁坏 歪斜的 墙、将倒的 壁,要到 几时呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, '他们彼此商议,专要 从他的尊位上 把他推下;他们喜爱 谎话,口 虽祝福,心 却咒诅。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, '我的心哪,你当默默无声,专等候 神,因为 我的盼望 是从他而来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, '惟独 他 是我的磐石,我的拯救;他是我的高台,我必不 动摇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, '我的拯救、我的荣耀 都在乎 神;我力量 的磐石、我的避难所都在乎 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, '你们众民 当时时 倚靠 他,在他面前 倾 心吐意; 神 是我们的 避难所。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, '下流人 真是 虚空;上流人 也是虚假;放在天平里 就必浮起;他们 一共 比空气还轻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, '不要 仗势 欺人,也不要 因抢夺 而骄傲;若 财宝 加增,不要 放在 心上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, '神 说了 一次、两次,我都听见:就是 能力都属乎 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, '主啊,慈爱 也是属乎你,因为 你 照著各人 所行的 报应他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, '(大卫 在 犹大 旷野的时候,作了这诗。) 神啊,你是我的 神,我要切切地寻求你,在干旱 疲乏 无 水 之地,我 渴想 你;我的心 切慕 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, '我在圣所中 曾如此 瞻仰你,为要见 你的能力 和你的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, '因 你的慈爱 比生命 更好,我的嘴唇 要颂赞你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, '我还活的时候 要这样 称颂你;我要奉你的名 举 手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, ' 我在 床 上记念你,在夜更的时候 思想 你;我的心 就像 饱足了 骨髓 肥油,我也要以欢乐 的嘴 唇 赞美你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, '因为 你曾 帮助 我,我就在你翅膀 的荫下 欢呼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, '我心 紧紧地 跟随你;你的右手 扶持 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, '但那些 寻索 要灭 我命 的人必往地 底下 去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, '他们必被 刀剑 所杀, 被野狗 所吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, '但是王必因 神 欢喜。凡 指著他 发誓的 必要夸口,因为 说 谎 之人的口 必被塞住。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, '(大卫的 诗,交与伶长。) 神啊,我哀叹的时候,求你听 我的声音!求你保护 我的性命,不受仇敌 的惊恐! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, '求你把我隐藏,使我脱离作恶之人 的暗谋 和作 孽 之人的扰乱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, '他们 磨 舌 如刀,发出苦毒 的言语,好像比准了 的箭, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, '要在暗地 射 完全人;他们忽然 射他,并不 惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, '他们 彼此勉励 设下恶 计;他们商量 暗设 网罗,说:谁能 看见? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, '他们图谋 奸恶,说:我们是极力 图 谋的。他们各人 的意念 心思 是深的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, '但 神 要射他们;他们 忽然 被箭 射伤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, '他们必然绊跌,被自己的 舌头所害;凡 看见 他们 的必都摇头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, '众 人 都要害怕,要传扬 神 的工作,并且明白 他的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, '义人 必因耶和华 欢喜,并要投靠 他;凡 心里 正直 的人都要夸口。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, '(大卫的 诗 歌,交与伶长。) 神啊,锡安的人 都等候 赞美 你;所许的愿  也要向你 偿还。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, '听 祷告的主啊,凡 有血气 的都要来 就你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, '罪孽 胜了 我;至于 我们的过犯,你 都要赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, '你所拣选、使他亲近你、住在 你院中的,这人便为有福!我们必因你居所、你圣 殿 的美福 知足了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, '拯救我们的 神啊,你必以威严 秉公义 应允我们;你本是一切 地 极 和海 上远处 的人所倚靠的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, '他既以大能 束腰,就用力量 安定 诸山, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, '使诸海 的响声 和其中波浪 的响声,并万民 的喧哗,都平静了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, '住在 地极 的人因你的神迹 惧怕;你使日 出 日落 之地都欢呼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, '你眷顾 地,降下透雨,使地大得 肥美。 神 的河 满了 水;你这样 浇灌了地,好为人预备 五谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, '你浇透 地的犁沟,润平 犁脊,降甘霖,使地软和;其中发长的,蒙你赐福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, '你以恩典 为年岁 的冠冕;你的路径 都滴下 脂油, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, '滴在 旷野 的草场上。小山 以欢乐 束腰; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, '草场 以羊群 为衣;谷 中也长满了 五谷。这一切都 欢呼 歌唱。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, '(一篇诗 歌,交与伶长。)全 地都当向 神 欢呼! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, '歌颂 他名 的荣耀!用赞美 的言语将他的荣耀 发明! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, '当对 神 说:你的作为 何等 可畏!因你的大 能,仇敌 要投降 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, '全 地 要敬拜 你,歌颂 你,要歌颂 你的名。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, '你们来 看 神 所行的,他向 世人 所做之事 是可畏的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, '他将海 变成 干地,众民步 行 过河;我们在那里 因他 欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, '他用权能 治理万民,直到永远。他的眼睛 鉴察 列邦;悖逆的人 不可 自高。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, '万民哪,你们当称颂我们的 神,使人得听 赞美他 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, '他使 我们的性命 存活,也不 叫 我们的脚 摇动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, '神啊,你曾 试验我们,熬炼我们,如熬炼 银子一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, '你使我们进入 网罗,把重担 放 在我们的身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, '你使人 坐车轧 我们的头;我们经过 水 火,你却使我们到 丰富之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, '我要用燔祭 进 你的殿,向你 还 我的愿 , ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, '就是在急难时 我嘴唇 所 发的、口中 所许的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, '我要把肥牛 作燔祭,将 公羊 的香祭 献 给你,又把公牛 和 山羊 献上。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, '凡 敬畏 神的人,你们都来 听!我要述说 他为我 所 行的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, '我曾用 口 求告 他;我的舌头 也称他为高。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, '我若 心里 注重 罪孽,主 必不 听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, '但 神 实在 听见了;他侧耳听了 我祷告 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, '神 是应当称颂的! 他并没有 推却 我的祷告,也没有叫他的慈爱 离开 我。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, '(一篇诗 歌,交与伶长。用丝弦的乐器。)愿  神 怜悯我们,赐福与我们,用脸 光照 我们,(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, '好叫世界 得知 你的道路,万 国 得知你的救恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, '神啊,愿 列邦 称赞你!愿 万 民 都称赞你! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, '愿 万国 都快乐 欢呼;因为 你必按公正 审判 万民,引导 世上 的万国。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, '神啊,愿 列邦 称赞你!愿 万 民 都称赞你! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, '地 已经出了 土产; 神─就是我们的 神 要赐福与我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, '神 要赐福与我们;地 的四 极 都要敬畏 他!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, '(大卫的 诗 歌,交与伶长。)愿  神 兴起,使他的仇敌 四散,叫那恨他的人 从他面前 逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, '他们被驱逐,如烟 被风吹散;恶人见 神 之面 而消灭,如蜡被 火 镕化。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, '惟有义人 必然欢喜,在 神 面前 高兴 快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, '你们当向 神 唱诗,歌颂 他的名;为那坐车 行过旷野 的修平大路。他的名 是耶和华,要在他面前 欢乐! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, '神 在他的圣 所 作孤儿 的父,作寡妇 的伸冤者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, '神 叫 孤独的 有家,使被囚的 出来 享福;惟有 悖逆的 住在 干燥之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, '神啊,你曾在你百姓 前头 出来,在旷野 行走。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, '那时,地见 神 的面 而震动,天 也 落雨; 西奈山 见以色列 神 的面也震动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, '神啊,你降下 大 雨;你产业 以色列疲乏的时候,你 使他坚固。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, '你的会众 住 在其中; 神啊,你的恩惠 是为困苦人 预备的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, '主 发 命令,传好信息的妇女 成了大 群。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, '统兵 的君王 逃跑了,逃跑了;在家 等候的妇女 分受 所夺的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, ' 你们安卧 在 羊圈的时候,好像鸽子 的翅膀 镀 白银,翎毛 镀黄 金一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, '全能者 在境内赶散 列王的时候, 势如飘雪 在撒们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, '巴珊 山是 神 的山;巴珊 山 是多峰多岭 的山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, '你们多峰多岭 的山哪,为何 斜看 神 所愿  居住 的山?耶和华 必 住这山,直到永远! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, '神 的车辇 累万 盈 千;主 在其中,好像在西奈 圣山一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, '你已经升上 高天,掳掠 仇敌;你在人间,就是 在悖逆的人间,受了 供献,叫耶和华 神 可以与他们同住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, '天 天 背负 我们 重担的主,就是拯救我们的 神,是应当称颂的!(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, '神 是为我们 施行诸般救恩的 神;人能脱离 死亡 是在乎主 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, '但 神 要打破 他仇敌 的头,就是那常犯 罪 之人的发 顶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, '主 说:我要使众民从巴珊 而归,使他们从深 海 而回, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, '使 你打碎 仇敌,你的脚 踹在血中,使你狗 的舌头 从其中得分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, '神啊,你是我的 神,我的王;人已经看见 你行走,进入圣所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, '歌唱的 行在前,作乐的 随在后,都在击鼓的 童女 中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, '从以色列 源头而来的,当在各会中 称颂 主 神! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, '在那里,有统管他们的 小 便雅悯,有犹大 的首领 和他们的群众,有西布伦 的首领,有拿弗他利 的首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, '以色列的能力是 神 所赐的; 神啊,求你坚固 你为我们 所 成全的事! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, '因 你耶路撒冷 的殿,列王 必带 贡物 献给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, '求你叱喝 芦苇 中的野兽 和群 公牛,并列邦 中的牛犊。把银 块 踹在脚下; 神已经赶散 好 争战  的列邦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, '埃及的 公侯 要出来朝见 神;古实人 要急忙举 手祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, '世上 的列国啊,你们要向 神 歌唱;愿 你们歌颂 主! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, '歌颂那自古 驾行 在诸天以上的主! 他发出 声音,是极大 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, '你们要将能力 归给 神。他的威荣 在 以色列之上;他的能力 是在穹苍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, '神啊,你从圣所 显为可畏;以色列的 神 是那 将力量 权能 赐 给他百姓的。 神 是应当称颂的!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, '(大卫的诗,交与伶长。调用 百合花。) 神啊,求你救我!因为 众水 要淹 没 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, '我陷 在深 淤泥中,没有 立脚之地;我到了 深 水中,大水 漫过我身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, '我因呼求 困乏,喉咙 发干;我因等候 神,眼睛 失明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, '无故 恨我的,比我头 发 还多;无理 与我为仇、要把我剪除的,甚为强盛。我没有 抢夺 的,要 叫我偿还。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, '神啊,我的愚昧,你 原知道;我的罪愆 不能 隐瞒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, '万军 的主─耶和华啊,求你叫那等候你的,不要 因我 蒙羞!以色列的 神啊,求你叫那寻求你的,不要 因我 受辱! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, '因 我为你的缘故 受了 辱骂,满 面 羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, '我的弟兄 看我为 外路人;我的同胞 看我为外邦人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, '因 我为你的殿 心里焦急,如同火烧,并且辱骂你人 的辱骂 都落 在我身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, '我哭泣,以禁食 刻苦我心;这倒算为 我的 羞辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, '我拿 麻布 当衣裳,就成了 他们的 笑谈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, '坐 在城门口的 谈论 我;酒徒 也以我为歌曲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, '但我 在悦纳 的时候 向你─耶和华 祈祷。 神啊,求你按你丰盛的 慈爱,凭你拯救 的诚实 应允我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, '求你搭救我 出离淤泥,不 叫我陷在其中;求你使我脱离 那些恨我的人,使我出离深 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, '求你不容 大水 漫过我,不容 深渊 吞灭我,不容 坑坎 在我以上 合 口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, '耶和华啊,求你应允我!因为 你的慈爱 本为美好;求你按你丰盛的 慈悲 回转 眷顾我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, '不要 掩 面 不顾你的仆人; 我 是在急难之中,求你速速地 应允我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, '求你亲近 我,救赎我!求你因 我的仇敌 把我赎回! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, '你 知道 我受的辱骂、欺凌、羞辱;我的敌人 都 在你面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, '辱骂 伤破了 我的心,我又满了忧愁。我指望 有人体恤,却没有一个;我指望有人安慰,却找 不著一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, '他们拿苦胆 给 我当食物;我渴了,他们拿醋 给我喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, '愿 他们的筵席 在他们面前 变为 网罗,在他们平安的 时候变为机槛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, '愿 他们的眼睛 昏蒙,不得看见;愿 你使他们的腰 常常 战 抖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, '求你将你的恼恨 倒 在他们身上,叫你的烈 怒 追上他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, '愿 他们的住处 变为 荒场;愿 他们的帐棚 无人 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, '因为,你 所 击打的,他们就逼迫;你所击伤的,他们戏说 他的愁苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, '愿 你在他们的罪 上 加 罪,不容 他们在 你面前称义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, '愿 他们从生命 册上 被涂抹,不得 记录 在 义人之中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, '但我 是困苦 忧伤的; 神啊,愿 你的救恩 将我安置在高处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, '我要以诗歌 赞美 神 的名,以感谢 称他为大! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, '这便叫耶和华 喜悦,胜似献牛,或是献有角 有蹄 的公牛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, '谦卑的人 看见了 就喜乐;寻求 神的人,愿 你们的心 苏醒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, '因为 耶和华 听了 穷乏人,不 藐视 被囚的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, '愿 天 和地、洋海 和其中 一切的 动物 都赞美他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, '因为 神 要拯救 锡安,建造 犹大 的城邑;他的民要在那里 居住,得以为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, '他仆人 的后裔 要承受为业;爱 他名 的人也要住 在其中。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, '(大卫的 记念诗,交与伶长。) 神啊,求你快快搭救我!耶和华啊,求你速速 帮助我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, '愿 那些寻索 我命的,抱愧 蒙羞;愿 那些喜悦 我遭害的,退 后 受辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, '愿 那些对我说 阿哈、阿哈的,因 羞愧 退后。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, '愿 一切 寻求你的,因你 高兴 欢喜;愿 那些喜爱 你救恩的,常 说:当尊 神 为大! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, '但我是 困苦 穷乏的; 神啊,求你速速 到我这里来!你 是帮助我的,搭救我的。耶和华啊,求你不要 耽延!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, '耶和华啊,我投靠 你;求你叫我永 不 羞愧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, '求你凭你的公义 搭救我,救拔我;侧 耳 听我,拯救我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, '求你作 我 常 住 的磐石;你已经命定 要救我,因为 你 是我的岩石,我的山寨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, '我的 神啊,求你救我 脱离恶人 的手,脱离不义 和残暴 之人的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, ' 主─耶和华啊,你 是我所盼望的;从我年幼,你是我所倚靠的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, '我从出母胎 被你 扶持;使我出 母 腹 的是你。我必常常 赞美 你! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, '许多人 以我为 怪,但你是 我坚固 的避难所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, '你的赞美,你的荣耀 终 日 必满了 我的口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, '我年老 的时候,求你不要 丢弃我!我力气 衰弱的时候,求你不要 离弃我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, ' 我的仇敌 议论 我;那些窥探要害 我命 的彼此 商议, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, '说: 神 已经离弃他;我们追赶他,捉拿他吧!因为 没有人 搭救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, '神啊,求你不要 远离 我!我的 神啊,求你速速 帮助我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, '愿 那与我性命 为敌的,羞愧 被灭;愿 那谋 害我的,受辱 蒙 羞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, '我 却要常常 盼望,并要越发 赞美你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, '我的口 终 日 要述说 你的公义 和你的救恩,因 我不 计 其数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, '我要来 说主─耶和华 大能的事;我单要 提说 你的公义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, '神啊,自我年幼时,你就教训我;直到 如今,我传扬 你奇妙的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, ' 神啊,我到 年老 发白的时候,求你不要 离弃我!等 我将你的能力 指示 下代,将你的大能指示 后世的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, '神啊,你的公义 甚 高; 行过 大事的 神啊,谁 能像你! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, '你是 叫我们多经历 重大 急难的,必使我们复 活,从地 的深处 救 上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, '求你使我越发 昌大,又转来 安慰我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, '我的 神啊,我要 鼓瑟 称赞你,称赞你的诚实!以色列 的圣者啊,我要弹琴 歌颂 你! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, ' 我歌颂 你的时候,我的嘴唇 和你所 赎 我的灵魂 都必欢呼; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, '并且 我的舌头 必终 日 讲论 你的公义,因为 那些谋 害我的人已经 蒙羞 受辱了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, '(所罗门的诗。) 神啊,求你将判断 的权柄赐 给王,将公义 赐给王 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, '他要按公义 审判 你的民,按公平 审判你的困苦人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, '大山 小山 都要因公义 使民 得享 平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, '他必为民 中的困苦人 伸冤,拯救 穷乏 之辈,压碎 那欺压人的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, '太阳 还存,月亮 还在,人要敬畏你,直到万代! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, '他必降临,像雨 降在 已割的草地上,如甘霖 滋润 田地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, '在他的日子,义人 要发旺,大有 平安,好像月亮 长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, '他要执掌权柄,从这海 直到 那海,从大河 直到 地 极。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, '住在旷野的,必在他面前 下拜;他的仇敌 必要舔 土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, '他施 和海岛 的王 要进 贡;示巴 和西巴 的王 要献 礼物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, '诸 王 都要叩拜 他;万 国 都要事奉他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, '因为,穷乏人 呼求的时候,他要搭救;没有人 帮助 的困苦人,他也要搭救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, '他要怜恤 贫寒 和穷乏的人,拯救 穷苦人 的性命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, '他要救赎 他们 脱离欺压 和强暴;他们的血 在他眼中 看为宝贵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, '他们要存活。示巴 的金子 要奉 给他;人要常常 为他 祷告,终 日 称颂他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, '在地 的山 顶上,五谷必然茂盛(或译:有 一把 五谷);所结的谷实 要响动,如黎巴嫩的树林;城里的人 要发旺,如地上 的草。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, '他的名 要存 到永远, 要留传 如 日之久。人要因他 蒙福;万 国 要称他有福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, '独 行 奇事 的耶和华─以色列的 神 是应当称颂的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, '他荣耀 的名 也当称颂,直到永远。愿 他的荣耀 充满 全 地!阿们!阿们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, '耶西 的儿子─大卫 的祈祷 完毕。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, '(亚萨的 诗。) 神 实在 恩待 以色列 那些清 心的人! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, '至于 我,我的脚 几乎 失闪;我的脚 险些 滑跌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, '我见 恶人 和狂傲人 享平安 就 心怀不平。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, ' 他们死的时候 没有 疼痛;他们的力气 却也壮实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, '他们不像 别人 受苦,也不 像 别人 遭灾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, '所以,骄傲 如链子戴在他们的项上;强暴 像衣裳 遮住 他们的身体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, '他们的眼睛 因体胖 而凸出;他们所得的,过于  心里 所想的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, '他们讥笑人,凭恶意 说 欺压人的话;他们说话 自高。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, '他们的口 亵渎 上天;他们的舌 毁谤 全地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, '所以 神的民 归到 这里,喝尽了 满杯 的苦水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, '他们说: 神 怎能 晓得?至高者 岂有 知识呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, '看哪,这就是 恶人;他们既是常 享安逸,财宝 便加增。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, '我实在 徒然 洁净了 我的心,徒然洗 手 表明无辜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, '因为,我 终 日 遭灾难;每早晨 受惩治。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, '我若 说,我要这样 讲,这就是 以奸诈 待你的众子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, '我思索 怎能明白 这事,眼看实系 为难, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, '等 我进了 神 的圣所,思想 他们的结局。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, '你实在 把他们 安 在滑地,使他们掉 在沉沦之中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, '他们转眼之间 成了 何等的 荒凉!他们被 惊恐 灭 尽了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, '人睡醒了,怎样看梦;主啊,你醒了 也必照样轻看 他们的影像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, '因而,我心 里发酸,肺腑 被刺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, '我 这样愚昧 无 知,在你面前如 畜类一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, '然而,我 常 与你同在;你搀著 我的右 手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, '你要以你的训言 引导我,以后 必接我 到荣耀里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, '除你以外,在天上 我 有谁呢?除你以外,在地上 我也没有 所爱慕的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, '我的肉体 和我的心肠 衰残;但 神 是我心 里的力量,又是我的福分,直到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, ' 远离你的,必要死亡;凡 离弃你 行邪淫的,你都灭绝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, '但我 亲近 神 是与我 有益;我以 主 耶和华 为我的避难所,好叫我述说 你一切的 作为。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, '(亚萨的 训诲诗。) 神啊,你为何 永远 丢弃我们呢?你为何向你草场 的羊 发怒,如烟冒出呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, '求你记念 你古时 所得来 的会众,就是你所赎、作你产业 支派的,并记念 你向来所居住 的锡安 山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, '求你举 步 去看那日久 荒凉之地,仇敌 在圣所中 所行的一切 恶事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, '你的敌人 在你会 中 吼叫;他们竖了 自己的旗 为记号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, '他们好像 人扬 起 斧子,砍伐林中的 树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, '圣所中一切 雕刻的,他们现在 用斧子 锤子 打坏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, '他们用 火 焚烧你的圣所,亵渎 你名 的居所,拆毁到地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, '他们心里 说:我们要尽 行毁灭;他们就在遍地把 神 的会所 都 烧毁了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, '我们不 见 我们的标帜,不 再 有先知;我们内中 也没有人 知道 这灾祸要到 几时呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, '神啊,敌人 辱骂 要到 几时呢?仇敌 亵渎 你的名 要到永远吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, '你为什么 缩回 你的右 手?求你从 怀中伸出来,毁灭他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, '神 自古以来 为我的王,在 地 上施行 拯救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, '你 曾用能力 将海 分开 ,将水 中 大鱼 的头 打破。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, '你 曾砸碎 鳄鱼 的头,把牠给 旷野的禽兽(禽兽:原文是民)为食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, '你 曾分裂磐石,水 便成了溪河;你 使长流的 江河 干了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, '白昼 属你,黑夜 也 属你;亮光 和日头 是你 所预备的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, '地 的一切 疆界 是你 所立的;夏天 和冬天 是你 所定的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, '耶和华啊,仇敌 辱骂,愚顽 民 亵渎了 你的名,求你记念 这事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, '不要 将你斑鸠 的性命 交 给野兽;不要 永远 忘记 你困苦人 的性命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, '求你顾念 所立的约,因为 地上 黑暗之处 都满了 强暴 的居所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, '不要 叫受欺压的人 蒙羞 回去;要叫困苦 穷乏的人 赞美 你的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, '神啊,求你起来 为自己伸诉!要记念 愚顽人 怎样 终 日 辱骂你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, '不要 忘记 你敌人 的声音;那起来 敌你之人的喧哗 时常 上升。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, '(亚萨的 诗 歌,交与伶长。调用休要毁坏。) 神啊,我们称谢 你,我们称谢你!因为你的名 相近,人都述说 你奇妙的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, ' 我到了所定 的日期, 必按正直 施行审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, '地 和其上的居民 都 消化了;我 曾立了 地的柱子。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, '我对狂傲人 说:不要 行事狂傲!对凶恶人说:不要 举 角! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, '不要 把你们的角 高 举;不要挺著 颈项 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, '因为 高举 非 从东,非从西,也非 从南而来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, '惟有 神 断定;他使这人 降卑,使那人 升高。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, ' 耶和华 手里 有杯,其中的酒 起沫,杯内满了 搀杂的酒;他倒 出来,地上 的恶人 必 都 喝 这酒的渣滓,而且喝尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, '但我 要宣扬,直到永远!我要歌颂 雅各的 神! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, '恶人 一切的 角,我要砍断;惟有义人 的角 必被高举。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, '(亚萨的 诗 歌,交与伶长。用丝弦的乐器。)在犹大, 神 为人所认识;在以色列,他的名 为大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, '在撒冷 有 他的帐幕;在锡安 有他的居所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, '他在那里 折断 弓 上的火箭,并盾牌、刀剑,和争战 的兵器。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, '你 从有野食 之山而来,有光华 和荣美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, '心中 勇敢 的人都被抢夺;他们睡了 长觉,没有 一个 英雄 能措 手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, '雅各的 神啊,你的斥责一发,坐车的、骑马的 都沉睡了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, '惟独 你 是可畏的!你怒气 一发,谁 能在你面前 站得住呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, '你从天上 使人听 判断。 神 起来 施行审判,要救 地上 一切 谦卑的人;那时地 就惧怕 而静默。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, ' 人 的忿怒 要成全你的荣美;人的余 馀 怒,你要禁止。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, '你们许愿 ,当向耶和华─你们的 神 还愿 ;在他四面 的人都 当拿 贡物 献给那可畏的主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, '他要挫折 王子 的骄气;他向地上 的君王 显威可畏。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, '(亚萨的 诗,照 耶杜顿的作法,交与伶长。)我要向 神 发声 呼求;我向 神 发声,他必留心听 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, '我在患难 之日 寻求 主;我在夜间 不 住地 举 手祷告;我的心 不肯 受安慰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, '我想念 神,就烦躁不安;我沉吟悲伤,心 便发昏。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, '你叫 我不能闭眼;我烦乱不安,甚至不能 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, '我追想 古时 之日,上古 之年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, '我想起 我夜间 的歌曲,扪 心 自问;我心里 也仔细省察。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, '难道主 要永远 丢弃我,不 再 施恩吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, '难道他的慈爱 永远 穷尽,他的应许 世世 废弃吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, '难道 神 忘记 开 恩,因发怒 就 止住 他的慈悲吗?(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, '我便说:这是 我的懦弱,但我要追念至高者 显出右手 之年代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, '我要提说 耶和华 所行的;我要 记念 你古时的 奇事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, '我也要思想 你的经营,默念 你的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, '神啊,你的作为 是洁净的;有何 神 大如 神呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, '你 是行 奇事的 神;你曾在列邦中 彰显 你的能力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, '你曾用你的膀臂 赎了 你的民,就是雅各 和约瑟 的子孙。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, '神啊,诸水 见你, 一见 就都惊惶;深渊 也 都战 抖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, '云 中倒出 水来;天空 发出 响声;你的箭 也 飞行四方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, '你的雷 声 在旋风中;电光 照亮 世界;大地 战 抖 震动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, '你的道 在海中;你的路 在大 水中;你的脚踪 无人 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, '你曾藉 借摩西 和亚伦 的手 引导 你的百姓,好像羊群一般。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, '(亚萨的 训诲诗。)我的民哪,你们要留心听 我的训诲,侧 耳 听我口中 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, '我要开  口 说比喻;我要说出 古时 的谜语, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, '是我们所 听见、所知道的,也是我们的祖宗 告诉 我们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, '我们不 将这些事向他们的子孙 隐瞒,要将耶和华 的美德 和他的能力,并他 奇妙的作为,述说 给后 代听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, '因为,他在雅各中 立 法度,在以色列中 设 律法;是 他吩咐 我们祖宗 要传 给子孙的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, '使 将要生 的后 代 子孙 可以晓得;他们也要起来 告诉 他们的子孙, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, '好叫他们仰 望 神,不 忘记 神 的作为,惟要守 他的命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, '不 要 像他们的祖宗,是顽梗 悖逆、居 心 不 正 之辈,向著 神,心 不 诚实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, '以法莲 的子孙 带著兵器,拿著 弓,临阵 之日 转身退后。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, '他们不 遵守 神 的约,不肯 照他的律法 行; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, '又忘记 他所行的和他 显给他们 奇妙的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, '他在埃及 地,在琐安 田,在他们祖宗 的眼前 施行 奇事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, '他将海 分裂,使他们过去,又叫水 立起 如 垒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, '他白日 用云彩,终 夜 用火 光 引导他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, '他在旷野 分裂 磐石,多多地 给他们水喝,如从深渊而出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, '他使水 从磐石 涌出,叫水 如江河 下流。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, '他们却 仍旧 得罪 他,在干燥之地 悖逆 至高者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, '他们心中 试探 神,随自己所欲的 求 食物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, '并且妄论 神 说: 神 在旷野 岂能 摆设 筵席吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, ' 他曾击打 磐石,使水 涌出,成了江河;他还 能 赐 粮食吗?还能 为他的百姓 预备 肉吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, '所以,耶和华 听见 就发怒;有烈火 向雅各 烧起;有 怒气 向以色列 上腾; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, '因为 他们不 信服 神,不 倚赖 他的救恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, '他却吩咐 天空,又敞开  天上 的门, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, '降 吗哪,像雨给他们 吃,将天上 的粮食 赐 给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, '各人(或译:人)吃 大能者 的食物;他赐下 粮食,使他们 饱足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, '他领东风 起 在天空,又用能力 引了 南风来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, '他降 肉,像雨在他们当中,多如尘土,又降飞鸟,多如海 沙, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, '落 在他们的营 中,在他们住处 的四面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, '他们吃了,而且饱 足;这样就随了 他们所欲的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, '他们贪 而无 厌,食物 还 在他们口中的时候, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, '神 的怒气 就向他们 上腾,杀 了他们内中的肥壮人,打倒 以色列 的少年人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, '虽是 这样,他们仍旧 犯罪,不 信 他奇妙的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, '因此,他叫他们的日子 全归 虚空,叫他们的年岁 尽属惊恐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, '他杀他们 的时候,他们才求问他,回心转意,切切地寻求 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, '他们也追念 神 是他们的磐石,至高的 神 是他们的救赎主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, '他们却用口 谄媚他,用舌 向他 说谎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, '因他们的心 向他 不 正,在他的约上 也不 忠心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, '但他 有怜悯,赦免 他们的罪孽,不 灭绝他们,而且屡次 消 他的怒气,不 发 尽 他的忿怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, '他想到 他们 不过是血气,是一阵去 而不 返 的风。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, '他们在旷野 悖逆他,在荒地 叫他担忧,何其多呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, '他们再三 试探 神,惹动 以色列 的圣者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, '他们不 追念他的能力(原文是手)和 赎他们 脱离 敌人 的日子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, '他怎样 在埃及地 显 神迹,在琐安 田 显奇事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, '把他们的江河 并河汊的水 都变 为血,使他们不能 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, '他叫 苍蝇 成群落在他们当中,嘬尽他们,又叫青蛙 灭了他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, '把他们的土产 交 给蚂蚱,把他们辛苦得来的 交给蝗虫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, '他降冰雹 打坏 他们的葡萄树,下严霜 打坏他们的桑树, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, '又把他们的牲畜 交 给冰雹,把他们的群畜 交给闪电。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, '他使 猛烈 的怒气 和忿怒、恼恨、苦难 成了 一群降灾 的使者,临到他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, '他为自己的怒气 修平了 路,将他们 交 给瘟疫,使 他们 死亡, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, '在埃及 击杀 一切 长子,在含 的帐棚中 击杀他们强壮 时头生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, '他却领出 自己的民 如羊,在旷野 引他们 如羊群。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, '他领他们 稳稳妥妥地,使他们不致 害怕;海 却淹没 他们的仇敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, '他带他们 到 自己圣地 的边界,到他右手 所得 的这 山地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, '他在他们面前 赶出 外邦人,用绳子 将外邦的地量给他们 为业,叫以色列 支派 的人住 在他们的帐棚里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, '他们仍旧试探、悖逆 至高的 神,不 守 他的法度, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, '反倒退后,行诡诈,像他们的祖宗一样;他们改变,如同翻背的 弓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, '因他们的邱坛 惹了他的怒气;因他们雕刻的偶像 触动他的愤恨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, '神 听见 就发怒,极其 憎恶 以色列人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, '甚至他离弃 示罗 的帐幕,就是他在人间 所搭 的帐棚; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, '又将他的约柜(原文是能力)交 与人掳去,将他的荣耀 交在敌人 手中; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, '并将他的百姓 交 与刀剑,向他的产业 发怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, '少年人 被火 烧灭;处女 也无 喜歌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, '祭司 倒 在刀下,寡妇 却不 哀哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, '那时,主 像世人睡 醒,像勇士 饮酒 呼喊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, '他就打 退 了他的敌人,叫 他们 永 蒙羞辱; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, '并且他弃掉 约瑟 的帐棚,不 拣选 以法莲 支派, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, '却拣选 犹大 支派─ 他所 喜爱的 锡安 山; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, '盖造 他的圣所,好像 高峰,又像他建立 永存 之地; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, '又拣选 他的仆人 大卫,从羊 圈 中将他召来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, '叫他不再跟从 那些带奶的母羊, 为要牧养 自己的百姓 雅各 和自己的产业 以色列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, '于 是,他按心 中的纯正 牧养他们,用手 中的巧妙 引导他们。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, '(亚萨的 诗。) 神啊,外邦人 进 入你的产业,污秽 你的圣 殿,使 耶路撒冷 变成荒堆, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, '把 你仆人 的尸首 交 与天空 的飞鸟 为食,把你圣民 的肉 交与地上 的野兽, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, '在耶路撒冷 周围 流 他们的血 如水,无人 葬埋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, '我们成为 邻国 的羞辱,成为我们四围 人的嗤笑 讥刺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, '耶和华啊,这到 几时呢?你要动怒 到永远吗?你的愤恨 要如 火 焚烧吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, '愿 你将你的忿怒 倒 在 那 不 认识你 的外邦 和 那 不 求告 你名 的国度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, '因为 他们吞了 雅各,把 他的住处 变为荒场。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, '求你不要 记念 我们先祖 的罪孽,向我们追讨;愿 你的慈悲 快 迎著我们,因为 我们落到 极 卑微的地步。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, '拯救我们的 神啊,求你因 你名 的荣耀 帮助我们!为你名 的缘故 搭救我们,赦免 我们的罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, '为何 容外邦人 说他们的 神 在哪里呢?愿 你使外邦人 知道 你在我们眼前 伸你仆人 流 血 的冤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, '愿 被囚之人 的叹息 达 到你面前;愿 你按你的大 能力 存留 那些将要死 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, '主啊,愿 你将我们邻邦 所 羞辱 你的羞辱 加七倍 归 到 他们身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, '这样,你的民,你草场 的羊,要称谢 你,直到永远;要述说 赞美你的话,直到万代。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, '(亚萨的 诗,交与伶长。调用 为证的百合花。)领 约瑟 如领羊群 之以色列 的牧者啊,求你留心听!坐在 二基路伯上的啊,求你发出光来! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, '在以法莲、便雅悯、玛拿西 前面 施展 你的大能,来 救 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, '神啊,求你使我们回转(或译:复兴),使你的脸 发光,我们便要得救! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, '耶和华─万军之 神啊,你向你百姓 的祷告 发怒,要到 几时呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, '你以眼泪 当食物 给他们吃,又多量 出眼泪 给他们喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, '你使 邻邦 因我们纷争;我们的仇敌 彼此 戏笑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, '万军之 神啊,求你使我们回转,使你的脸 发光,我们便要得救! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, '你从埃及 挪出 一棵葡萄树,赶出 外邦人,把这树栽上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, '你在这树根前 预备了地方,它就深深 扎根,爬满了 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, '它的影子 遮满了 山,枝子 好像佳美的 香柏树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, '它发出 枝子,长到 大海,发出蔓子,延到 大河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, '你为何 拆毁 这树的篱笆,任凭一切 过 路 的人摘取? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, '林中出来 的野猪 把它糟踏;野地 的走兽 拿它当食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, '万军之 神啊,求你 回转!从天上 垂看,眷顾 这 葡萄树, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, '保护你右手 所 栽 的和 你为自己 所坚固 的枝子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, '这树已经被火 焚烧,被刀砍伐;他们因你脸上 的怒容 就灭亡了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, '愿  你的手扶持 你右边 的人,就是 你为自己 所坚固 的人 子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, '这样,我们便不 退后 离开 你;求你救活我们,我们就要求告 你的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, '耶和华─万军之 神啊,求你使我们回转,使你的脸 发光,我们便要得救!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, '(亚萨的诗,交与伶长。用 迦特乐器。)你们当向 神─我们的力量 大声欢呼,向雅各的 神 发声欢乐! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, '唱起 诗歌,打 手鼓,弹美 琴 与 瑟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, '当在月朔 并月望─我们过节 的日期 吹 角, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, '因 这是 为以色列 定的律例,是雅各 神的 典章。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, '他去 攻击 埃及 地的时候,在约瑟中间 立 此为证。我在那里听见 我所不 明白 的言语: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, '神说:我使你的肩 得脱 重担,你的手 放下 筐子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, '你在急难中 呼求,我就搭救你;我在雷 的隐密处 应允你,在 米利巴 水 那里试验你。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, '我的民哪,你当听,我要劝戒 你;以色列啊,甚愿  你肯听从 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, '在你当中,不可 有 别的 神;外邦的 神,你也不可 下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, '我 是耶和华─你的 神,曾把你从埃及 地 领上来;你要大大张 口,我就给你充满。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, '无奈,我的民 不 听 我的声音;以色列 全不 理 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, '我便任凭他们 心里 刚硬,随自己的计谋 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, '甚愿  我的民 肯听从 我,以色列 肯行 我的道, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, '我便速速 治服 他们的仇敌,反 手 攻击 他们的敌人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, '恨 耶和华 的人必来投降,但他的百姓必 永久长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, '他也必拿上好的 麦子 给他们吃,又拿从磐石出的 蜂蜜 叫他们饱足。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, '(亚萨的 诗。) 神 站在 有权力者 的会中,在诸神 中 行审判, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, '说:你们审判 不秉公义,徇 恶人 的情面,要到 几时呢?(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, '你们当为贫寒的人 和孤儿 伸冤;当为困苦 和穷乏的人 施行公义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, '当保护 贫寒 和穷乏的人,救 他们脱离恶人 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, '你们仍不 知道,也不 明白,在黑暗中 走来走去;地 的根基 都 摇动了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, '我 曾说:你们 是神,都是 至高者 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, '然而,你们要死,与世人一样,要仆倒,像王子 中的一位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, '神啊,求你起来 审判 世界,因为 你要 得万 邦 为业。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, '(亚萨的 诗 歌。) 神啊,求你 不要 静默! 神啊,求你不要 闭口,也不要 不作声! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, '因为 你的仇敌 喧嚷,恨你的 抬起 头来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, '他们同谋 奸诈 要害 你的百姓,彼此商议 要害 你所隐藏的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, '他们说:来吧,我们将他们剪灭,使他们不再成国!使以色列 的名 不 再 被人记念! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, ' 他们同 心 商议,彼此结 盟,要抵挡你, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, '就是住帐棚的 以东人 和以实玛利人,摩押 和夏甲人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, '迦巴勒、亚扪,和亚玛力、非利士 并 泰尔 的居民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, '亚述 也 与他们 连合;他们作 罗得 子孙的 帮手。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, '求你待 他们,如待米甸,如在基顺 河 待西西拉 和耶宾一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, '他们在隐‧多珥 灭亡,成了 地上的 粪土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, '求你叫 他们的首领 像俄立 和西伊伯,叫他们的王子 都 像西巴 和撒慕拿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, ' 他们说:我们要得 神 的住处,作为自己的产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, '我的 神啊,求你叫他们 像旋风的尘土,像风 前 的碎秸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, '火怎样 焚烧 树林,火焰怎样 烧著 山岭, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, '求你也照样 用狂风 追赶他们,用暴雨 恐吓他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, '愿 你使他们满 面 羞耻,好叫他们寻求你─耶和华 的名! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, '愿 他们永远 羞愧 惊惶!愿 他们惭愧 灭亡! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, '使他们知道: 惟独 你─名 为耶和华的─是全 地 以上 的至高者!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, '(可拉 后裔的 诗,交与伶长。用 迦特乐器。)万军 之耶和华啊,你的居所 何等 可爱! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, '我 羡慕 渴想 耶和华 的院宇;我的心肠,我的肉体 向 永生 神 呼吁(或译:欢呼)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, '万军 之耶和华─我的王,我的 神啊,在 你祭坛那里, 麻雀 为自己找著 房屋,燕子 为自己找著 菢 雏 之窝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, '如此住 在你殿中 的便为有福!他们仍 要赞美你。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, '靠你 有力量、心中 想往锡安大道的,这人 便为有福! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, '他们经过 流泪 谷,叫这谷变为 泉源之地;并 有秋雨 之福 盖满了全谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, '他们行走,力上 加 力,各人到锡安 朝见 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, '耶和华─万军之 神啊,求你听 我的祷告!雅各的 神啊,求你留心听!(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, '神啊,你是我们的盾牌;求你垂顾 观看 你受膏者 的面! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, ' 在你的院宇 住一日,胜 似在别处住千日;宁可在我 神 殿中 看门,不愿 住 在恶人 的帐棚里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, '因为 耶和华─ 神 是日头,是盾牌, 要赐下 恩惠 和荣耀。他未尝 留下 一样好处 不给那些行动 正直的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, '万军 之耶和华啊,倚靠 你 的人 便为有福!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, '(可拉 后裔的 诗,交与伶长。)耶和华啊,你已经向你的地 施恩,救回 被掳的 雅各。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, '你赦免了 你百姓 的罪孽,遮盖了 他们一切的 过犯。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, '你收 转了 所发的忿怒 和你猛烈的 怒气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, '拯救我们的 神啊,求你使我们回转,叫你的恼恨 向我们 止息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, '你要向我们 发怒 到永远吗?你要将你的怒气 延留 到万代吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, '你 不 再 将我们救活,使你的百姓 靠你 欢喜吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, '耶和华啊,求你使我们得见 你的慈爱,又将你的救恩 赐 给我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, '我要听 神─耶和华 所说 的话;因为 他必应许 将平安 赐给 他的百姓─ 他的圣民;他们却不可 再转 去妄行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, '他的救恩 诚然 与敬畏他的人 相近,叫荣耀 住 在我们的地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, '慈爱 和诚实 彼此相遇;公义 和平安 彼此相亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, '诚实 从地 而生;公义 从天 而现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, '耶和华 必 将好处 赐给我们;我们的地 也要多出 土产。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, '公义 要行 在他面前,叫他的脚踪 成为 可走的路。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, '(大卫的 祈祷。)耶和华啊,求你侧 耳 应允我,因 我是 困苦 穷乏的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, '求你保存 我的性命,因 我是 虔诚人。我的 神啊,求你拯救 这倚靠 你 的仆人! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, '主啊,求你怜悯我,因 我终 日 求告 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, '主啊,求你使仆人 心里 欢喜,因为 我的心 仰望 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, '主啊,你 本 为良善,乐意饶恕人,有丰盛的 慈爱 赐给凡 求告你的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, '耶和华啊,求你留心听 我的祷告,垂听 我恳求 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, '我在患难 之日 要求告你,因为 你必应允我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, '主啊,诸神之中 没有 可比你的;你的作为 也无可比。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, '主啊,你所 造 的万 民 都要来 敬拜 你;他们也要荣耀 你的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, '因 你 为大,且行 奇妙的事;惟独 你是 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, '耶和华啊,求你将你的道 指教我;我要照你的真理 行;求你使我专 心 敬畏 你的名! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, '主─我的 神啊,我要一 心 称赞你;我要荣耀 你的名,直到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, '因为,你向我 发的慈爱 是大的;你救了 我的灵魂 免入极深的 阴间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, '神啊,骄傲的人 起来 攻击我,又有一党 强横的人 寻索 我的命;他们没有 将你放 在眼中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, '主啊,你 是有怜悯 有恩典的 神,不轻易 发怒,并有丰盛的 慈爱 和诚实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, '求你向我 转脸,怜恤我,将你的力量 赐 给仆人,救 你婢女 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, '求你向我 显出 恩待 我的凭据,叫恨我的人 看见 便羞愧,因为 你─耶和华 帮助我,安慰我。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, '(可拉 后裔的 诗 歌。)耶和华所立的根基 在圣 山上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, ' 他爱 锡安 的门,胜于 爱雅各 一切的 住处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, '神 的城啊,有荣耀的事 乃指著你 说的。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, '我要提起 拉哈伯 和巴比伦人,是在认识我之中的;看哪,非利士 和泰尔 并 古实人,个个 生 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, '论到锡安,必说:这一个、那一个 都生 在其中,而且至高者 必亲自 坚立这城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, '当耶和华 记录 万民的时候,他要点出 这一个 生 在那里。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, '歌唱的,跳舞的,都要说:我的泉源 都 在你里面。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, '(可拉 后裔的 诗 歌,就是以斯拉人 希幔的 训诲诗,交与伶长。调用 麻哈拉 利暗俄。)耶和华─拯救我的 神啊,我昼 夜 在你面前 呼吁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, '愿 我的祷告 达到 你面前;求你侧 耳 听我的呼求! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, '因为 我心 里满了 患难;我的性命 临近 阴间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, '我算 和下 坑 的人同列, 如同无 力(或译:没有帮助)的人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, '我被丢 在死人中,好像 被杀的人 躺 在坟墓里。 他们是你不 再 记念的, 与你 隔绝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, '你把我放 在极深 的坑里,在黑暗地方,在深处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, '你的忿怒 重压 我身;你用一切的 波浪 困住我。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, '你把我所认识的 隔在远处,使我 为他们 所憎恶;我被拘困,不得 出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, '我的眼睛 因 困苦 而干瘪。耶和华啊,我天天 求告你,向你 举 手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, '你岂要行 奇事 给死人看吗?难道 阴魂 还能起来 称赞你吗?(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, '岂能在坟墓里 述说 你的慈爱吗?岂能在灭亡中 述说你的信实吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, '你的奇事 岂能在幽暗里 被知道吗?你的公义 岂能在忘记 之地被知道吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, '耶和华啊,我 呼求 你;我早晨 的祷告 要达到你面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, '耶和华啊,你为何 丢弃 我?为何掩 面 不顾我? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, '我 自幼 受苦,几乎死亡;我受 你的惊恐,甚至慌张。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, '你的烈怒 漫过 我身;你的惊吓 把我剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, '这些终 日 如水 环绕我,一齐 都来围困 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, '你把我的良朋 密友 隔在远处,使我所认识的人 进入黑暗里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, '(以斯拉人 以探的 训诲诗。)我要歌唱 耶和华 的慈爱,直到永远;我要用口 将你的信实 传 与万代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, '因 我曾说:你的慈悲 必建立 到永远;你的信实 必坚立 在天 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, '我与我所拣选的人 立了 约,向我的仆人 大卫 起了誓: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, '我要建立 你的后裔,直到 永远;要建立 你的宝座,直到万代。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, '耶和华啊,诸天 要称赞 你的奇事;在圣者 的会中,要称赞 你的信实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, ' 在天空 谁 能比 耶和华呢? 神 的众子中,谁能像 耶和华呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, '他在圣者 的会中,是大 有威严的 神,比一切 在 他四围的 更可畏惧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, '耶和华─万军之 神啊,哪一个 大能者 像你 耶和华?你的信实 是在你的四围。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, '你 管辖 海 的狂傲;波浪 翻腾,你 就使它平静了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, '你 打碎了 拉哈伯,似乎是已杀的人;你用有能的 膀臂 打散了 你的仇敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, '天 属你,地 也 属你;世界 和其中所充满的 都为你 所建立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, '南 北 为你 所创造;他泊 和黑门 都因你的名 欢呼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, '你 有 大能的 膀臂;你的手 有力,你的右手 也高举。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, '公义 和公平 是你宝座 的根基;慈爱 和诚实 行在 你前面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, '知道 向你欢呼的,那民 是有福的!耶和华啊,他们在你脸上 的光里 行走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, '他们因你的名 终 日 欢乐,因你的公义 得以高举。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, ' 你 是他们力量 的荣耀;因为你喜悦我们,我们的角 必被高举。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, ' 我们的盾牌 属耶和华;我们的王 属以色列 的圣者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, '当时,你在异象中 晓谕 你的圣民,说:我已把救助 之力加 在 那有能者的身上;我高举 那从民中 所拣选的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, '我寻得 我的仆人 大卫,用我的圣 膏 膏他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, ' 我的手 必使他 坚立;我的膀臂 也必 坚固他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, '仇敌 必不 勒索 他;凶恶 之子 也不 苦害他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, '我要在他面前 打碎 他的敌人,击杀 那恨他的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, '只是我的信实 和我的慈爱 要与他同在;因我的名,他的角 必被高举。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, '我要使他的左手 伸 到海上,右手 伸到河上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, '他 要称呼我说:你 是我的父,是我的 神,是拯救我 的磐石。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, '我 也 要立他 为长子,为世上 最高 的君王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, '我要为他 存留 我的慈爱,直到永远;我与他 立的约 必要坚定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, '我也要使他的后裔 存 到永远,使他的宝座 如天 之久。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, '倘若 他的子孙 离弃 我的律法,不 照我的典章 行, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, ' 背弃 我的律例,不 遵守 我的诫命, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, '我就要用杖 责罚 他们的过犯,用鞭 责罚他们的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, '只是我必不 将我的慈爱 全然收回,也必不 叫我的信实 废弃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, '我必不 背弃 我的约,也不 改变 我口 中所出的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, '我一次 指著自己的圣洁 起誓:我决不 向大卫 说谎! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, '他的后裔 要存 到永远;他的宝座 在我面前 如日之恒一般, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, '又如月亮 永远 坚立,如天上 确实的 见证。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, '但你 恼怒 你的受膏者,就丢掉 弃绝他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, '你厌恶了 与仆人 所立的约,将他的冠冕 践踏 于 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, '你拆毁了 他一切的 篱笆,使他的保障 变为 荒场。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, '凡 过 路 的人都抢夺他;他成为 邻邦的 羞辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, '你高举了 他敌人 的右手;你叫他一切的 仇敌 欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, '你叫 他的刀剑 卷 刃,叫他在争战 之中 站立 不住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, '你使他的光辉 止息,将他的宝座 推倒 于 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, '你减少 他青年 的日子,又使他 蒙 羞。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, '耶和华啊,这要到 几时呢?你要将自己隐藏 到永远吗?你的忿怒 如 火 焚烧要到几时呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, '求你想念 我 的时候 是何等的短少;你创造 世人,要使他们归 何等的 虚空呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, '谁 能 常活 免 死、救 他的灵魂 脱离阴间 的权柄呢?(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, '主啊,你从前 凭你的信实 向大卫 立誓 要施行的慈爱 在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, '主啊,求你记念 仆人们 所受的羞辱,记念 我怎样将一切 强盛 民 的羞辱存在我怀里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, '耶和华啊,你的仇敌 用这羞辱 羞辱了你的仆人, 羞辱了 你受膏者 的脚踪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, '耶和华 是应当称颂的,直到永远。阿们!阿们!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, '(神 人 摩西的 祈祷)主啊,你 世世代代 作 我们的 居所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, '诸山 未曾 生出,地 与世界 你未曾造成,从亘古 到 永远,你是 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, '你使人 归 于  尘土,说:你们世人 要归回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, '在你看来, 千 年 如已过 的昨 日,又如夜间的 一更。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, '你叫他们如水冲去;他们如 睡一觉。早晨,他们如生长 的草, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, '早晨 发芽 生长,晚上 割下 枯干。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, '我们因你的怒气 而 消灭,因你的忿怒 而惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, '你将我们的罪孽 摆在 你面前,将我们的隐恶 摆在你面 光之中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, ' 我们经过 的日子 都 在你震怒之下;我们度尽 的年岁 好像 一声叹息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, '我们一生的年 日 是七十 岁,若是 强壮 可到八十 岁;但其中 所矜夸的 不过是劳苦 愁烦, 转眼 成空,我们便如飞而去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, '谁 晓得 你怒气 的权势?谁按著你该受的敬畏 晓得你的忿怒呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, ' 求你指教 我们怎样数算 自己的日子,好叫我们得著 智慧 的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, '耶和华啊,我们要等到 几时呢?求你转回,为 你的仆人 后悔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, '求你使我们早早 饱得 你的慈爱,好叫我们一生一世 欢呼 喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, '求你照著你使我们受苦 的日子,和我们遭 难 的年岁,叫我们喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, '愿 你的作为 向 你仆人 显现;愿 你的荣耀 向 他们子孙显明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, '愿 主─我们 神 的荣美 归于  我们身上。愿 你坚立 我们手 所做的工;我们手 所做的工,愿 你坚立。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, '住 在至高者 隐密处的,必住 在全能者 的荫下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, '我要论到耶和华 说:他是我的避难所,是我的山寨,是我的 神,是我所倚靠的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, ' 他必 救你 脱离捕鸟人 的网罗 和毒害 的瘟疫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, '他必用自己的翎毛 遮蔽 你;你要投靠 在他的翅膀 底下;他的诚实 是大小的盾 牌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, '你必不 怕 黑夜 的惊骇,或是白日 飞 的箭, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, '也不怕黑夜 行 的瘟疫,或是午间 灭人的 毒病。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, '虽有千 人仆倒 在你旁边,万 人仆倒在你右边,这灾却不得 临近 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, '你惟 亲眼 观看,见 恶人 遭报。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, ' 耶和华 是我的避难所;你 已将至高者 当 你的居所, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, '祸患 必不 临到 你,灾害 也不 挨近 你的帐棚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, '因 他要为你 吩咐 他的使者,在你行的一切 道路 上保护你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, '他们要用 手 托著你,免得 你的脚 碰 在石头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, '你要踹 在 狮子 和虺蛇的身上,践踏 少壮狮子 和大蛇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, '神说:因为 他专心爱 我,我就要搭救他;因为 他知道 我的名,我要把他安置在高处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, '他若求告我,我就应允他;他在急难中,我要 与他同在;我要搭救他,使他尊贵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, '我要使他足享 长 寿,将我的救恩 显明给他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, '(安息 日的 诗 歌。)称谢 耶和华!歌颂 你至高者 的名! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, '用 十弦 的乐器和 瑟,用琴弹 幽雅的声音,早晨 传扬 你的慈爱;每夜 传扬你的信实。这本为美事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, '因你─耶和华 藉 借著你的作为 叫我高兴,我要因你手 的工作 欢呼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, '耶和华啊,你的工作 何其 大!你的心思 极其 深! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, '畜类 人 不 晓得;愚顽人 也不 明白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, '恶人 茂盛 如 草,一切 作 孽 之人发旺的时候,正是他们要灭亡,直到 永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, '惟你─耶和华 是至高,直到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, ' 耶和华啊, 你的仇敌 都要灭亡;一切 作 孽 的也要离散。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, '你却高举了 我的角,如野牛的角;我是被新 油 膏了的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, '我眼睛 看见 仇敌遭报;我耳朵 听见 那些起来 攻击我 的恶人受罚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, '义人 要发旺 如棕树,生长 如黎巴嫩的 香柏树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, '他们栽 于 耶和华 的殿中,发旺在我们 神 的院里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, '他们年老的时候 仍 要结果子,要 满了汁浆 而常发青, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, '好显明 耶和华 是正直的。他是我的磐石,在他 毫无 不义。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, '耶和华 作王!他以威严 为衣穿上;耶和华 以能力 为衣,以能力束腰,世界 就 坚定,不得 动摇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, '你的宝座 从太初 立定;你 从亘古就有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, '耶和华啊,大水 扬起,大水 发 声,波浪 澎湃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, '耶和华 在高处 大有能力,胜过 诸水 的响声,洋海 的大 浪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, '耶和华啊,你的法度 最 的确;你的殿 永 称为圣,是合宜的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, '耶和华啊,你是伸冤的 神;伸冤的 神啊,求你发出光来! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, '审判 世界的主啊,求你挺身而立,使 骄傲人 受 应得的报应! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, '耶和华啊,恶人 夸胜 要到 几时呢? 要到 几时呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, '他们絮絮叨叨 说 傲慢的话;一切 作 孽 的人都自己夸张。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, '耶和华啊,他们强压 你的百姓,苦害 你的产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, '他们杀死 寡妇 和寄居的,又杀害 孤儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, '他们说:耶和华 必不 看见;雅各的 神 必不 思念。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, '你们民间 的畜类人 当思想;你们愚顽人 到几时 才有智慧呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, '造 耳朵的,难道自己不 听见吗?造 眼睛的,难道 自己不 看见吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, '管教 列邦的,就是叫 人 得知识的,难道自己不 惩治人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, '耶和华 知道 人 的意念 是虚妄的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, '耶和华啊,你所 管教、用律法 所教训 的人 是有福的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, '你使他 在遭难 的日子 得享平安;惟有 恶人 陷在所挖的 坑中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, '因为 耶和华 必不 丢弃 他的百姓,也不 离弃 他的产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, ' 审判 要转 向 公义;心里 正直的,必都 随从。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, '谁 肯为我 起来 攻击 作恶的?谁 肯为我 站起 抵挡 作 孽的? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, '若不是 耶和华 帮助 我,我 就 住在 寂静之中了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, '我正 说 我失了 脚,耶和华啊,那时你的慈爱 扶助我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, '我心里 多 忧多疑,你安慰我,就使我 欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, '那藉 借著 律例 架弄 残害、在位上 行奸恶的,岂能与你相交吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, '他们大家聚集 攻击 义 人,将无辜的 人 定为死罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, '但耶和华 向来作了 我的 高台;我的 神 作了我投靠 的磐石。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, '他叫 他们的罪孽 归到 他们身上。他们正在行恶之中,他要剪除他们;耶和华─我们的 神 要把他们剪除。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, '来啊,我们要向耶和华 歌唱,向拯救我们 的磐石 欢呼! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, '我们要来 感谢 他,用诗歌 向他 欢呼! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, '因 耶和华 为大 神,为大 王,超乎 万 神之上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, '地 的深处 在他手中;山 的高峰 也属他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, '海洋 属他,是他 造的;旱地 也是他手 造成的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, '来啊,我们要屈身 敬拜,在造我们 的耶和华 面前 跪下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, '因为 他是我们的 神;我们是 他草场 的羊,是他手 下的民。惟愿  你们今天 听 他的话: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, '你们不可 硬著 心,像当日 在米利巴,就是在旷野 的玛撒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, '那时,你们的祖宗 试我 探我,并且 观看 我的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, '四十 年之久,我厌烦 那世代,说:这是 心里 迷糊 的百姓, 竟不 晓得 我的作为! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, '所以,我在怒中 起誓,说:他们断不可 进 入 我的安息!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, '你们要向耶和华 唱 新 歌!全 地 都要向耶和华 歌唱! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, '要向耶和华 歌唱,称颂 他的名!天 天 传扬 他的救恩! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, '在列邦中 述说 他的荣耀!在万 民中 述说他的奇事! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, '因 耶和华 为大,当受极大的 赞美;他 在万 神 之上,当受敬畏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, ' 外邦 的神 都 属虚无;惟独耶和华 创造 诸天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, '有尊荣 和威严 在他面前;有能力 与华美 在他圣所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, '民 中的万族啊,你们要将荣耀、能力 归 给耶和华,都归 给耶和华! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, '要将耶和华 的名 所当得的荣耀 归给他,拿 供物 来进 入他的院宇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, '当以圣洁的(的:或译为)妆饰 敬拜 耶和华;全 地 要在他面前 战 抖! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, '人在列邦中 要说:耶和华 作王!世界 就 坚定,不得 动摇;他要按公正 审判 众民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, '愿 天 欢喜,愿 地 快乐!愿 海 和其中所充满的 澎湃! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, '愿 田 和其中 所有的 都欢乐!那时,林中 的树木 都 要在耶和华 面前 欢呼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, '因为 他来了, 他来 要审判 全地。他要按公义 审判 世界,按他的信实 审判万民。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, '耶和华 作王!愿 地 快乐!愿 众 海岛 欢喜! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, '密云 和幽暗 在他的四围;公义 和公平 是他宝座 的根基。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, '有烈火 在他前头 行,烧灭 他四围 的敌人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, '他的闪电 光照 世界,大地 看见 便震动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, '诸山 见耶和华 的面,就是全 地 之主 的面,便消化 如蜡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, '诸天 表明 他的公义;万 民 看见 他的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, '愿 一切 事奉 雕刻的偶像、靠虚无之神 自夸的,都蒙羞愧。万 神哪,你们都当拜 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, '耶和华啊,锡安 听见 你的判断 就欢喜;犹大的城邑(原文是女子)也都快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, '因为 你─耶和华 至高,超乎 全 地;你被尊崇,远 超 万 神之上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, '你们爱 耶和华的,都当恨恶 罪恶;他保护 圣民 的性命,搭救他们 脱离恶人 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, '散布 亮光 是为义人;预备喜乐 是为正直人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, '你们义人 当靠耶和华 欢喜,称谢 他可记念的 圣名。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, '(一篇诗。)你们要向耶和华 唱 新 歌!因为 他行过 奇妙的事;他的右手 和圣 臂 施行救恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, '耶和华 发明了 他的救恩,在列邦人 眼前 显出 公义; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, '记念 他向以色列 家 所发的慈爱,所凭的信实。地 的四 极 都看见我们 神 的救恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, '全 地 都要向耶和华 欢乐;要发起大声,欢呼 歌颂! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, '要用琴 歌颂 耶和华,用琴 和诗歌 的声音歌颂他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, '用号 和角 声,在大君王 耶和华 面前 欢呼! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, '愿 海 和其中所充满的 澎湃;世界 和住 在其间的也要发声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, '愿 大水 拍 手;愿 诸山 在耶和华 面前 一同 欢呼; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, '因为 他来 要审判 遍地。他要按公义 审判 世界,按公正 审判万民。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, '耶和华 作王;万民 当战 抖!他坐 在二基路伯上,地 当动摇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, '耶和华 在锡安 为大;他 超乎 万 民 之上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, '他们当称赞 他大 而可畏的 名;他 本为圣! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, '王 有能力,喜爱 公平, 坚立 公正, 在雅各中 施行 公平 和公义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, '你们当尊崇 耶和华─我们的 神,在他脚 凳前 下拜。他本为 圣! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, '在他的祭司中 有摩西 和亚伦;在求告 他名 的人中有撒母耳。他们求告 耶和华,他 就应允他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, '他在云 柱中 对他们 说话;他们遵守 他的法度 和他所赐 给他们 的律例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, '耶和华─我们的 神啊,你 应允他们;你是 赦免 他们的 神,却按 他们所行的 报应他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, '你们要尊崇 耶和华─我们的 神,在他的圣 山 下拜,因为 耶和华─我们的 神 本为圣!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, '(称谢 诗。)普 天下 当向耶和华 欢呼! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, '你们当乐意 事奉 耶和华,当来 向他 歌唱! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, '你们当晓得 耶和华 是 神!我们是他 造的,也是属他的;我们是他的民,也是他草场 的羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, '当称谢 进入 他的门;当赞美 进入他的院。当感谢 他,称颂 他的名! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, '因为 耶和华 本为善。他的慈爱 存到永远;他的信实 直到 万代。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, '(大卫的 诗)。我要歌唱 慈爱 和公平;耶和华啊,我要向你 歌颂! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, '我要用智慧行 完全的 道。你几时 到我 这里来呢?我要存完全的 心 行 在我家 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, '邪僻 的事,我都不 摆在 我眼 前;悖逆人 所做的事,我甚恨恶,不容 沾 在我身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, '弯曲的 心思,我必远离;一切的恶人(或译:恶事),我不 认识。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, '在暗中 谗谤 他邻居的,我必将他 灭绝;眼目 高傲、心 里骄纵的,我必不 容 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, '我眼 要看国中 的诚实人,叫他们与我 同住;行为 完全的,他要 伺候我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, '行 诡诈的,必不 得住 在我家 里;说 谎话的,必不 得立 在我眼 前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, '我每日早晨 要灭绝 国 中所有的 恶人,好把一切 作 孽 的从耶和华 的城里 剪除。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, '(困苦人 发昏 的时候,在耶和华 面前 吐露 苦情 的祷告。)耶和华啊,求你听 我的祷告,容我的呼求 达 到你面前! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, '我 在急难 的日子,求你向我 侧 耳;不要 向我 掩 面!我呼求 的日子,求你快快 应允我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, '因为,我的年日 如烟云 消灭;我的骨头 如 火把 烧著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, '我的心 被伤,如草 枯干,甚至 我忘记 吃 饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, '因我唉哼 的声音,我的肉 紧贴 骨头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, '我如同 旷野 的鹈鹕;我 好像荒场 的鸮鸟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, '我警醒不睡;我 像房顶 上 孤单的 麻雀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, '我的仇敌 终 日 辱骂我;向我猖狂的人 指著我 赌咒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, ' 我吃过 炉灰,如同吃饭;我所喝的 与眼泪 搀杂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, '这都因 你的恼恨 和忿怒; 你把我拾起来,又把我摔下去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, '我的年日 如日影 偏斜;我 也如草 枯干。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, '惟你─耶和华 必存 到永远;你可记念 的名也存到万代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, '你 必起来 怜恤 锡安,因 现在是可怜她 的时候, 日期 已经到了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, '你的仆人 原来 喜悦 她的石头,可怜 她的尘土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, '列国 要敬畏 耶和华 的名;世上 诸 王都敬畏 你的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, '因为 耶和华 建造了 锡安,在他荣耀里 显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, '他垂听 穷人 的祷告,并不 藐视 他们的祈求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, '这 必为后 代 的人记下,将来受造 的民 要赞美 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, '因为,他从至高的 圣所 垂看;耶和华 从天 向 地 观察, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, '要垂听 被囚之人 的叹息,要释放 将要死 的人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, '使人在锡安 传扬 耶和华 的名,在耶路撒冷 传扬赞美他的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, '就是在万民 和列国 聚 会 事奉 耶和华的时候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, '他使我的力量 中道 衰弱,使我的年日 短少。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, '我说:我的 神啊,不要 使我中 年 去世。你的年数 世世无穷! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, '你起初 立了 地的根基;天 也是你手 所造的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, '天地 都要灭没,你 却要长存;天地都 要如外衣 渐渐旧了。你要将天地如里衣 更换,天地就都改变了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, '惟有你永不改变;你的年数 没有 穷尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, '你仆人 的子孙 要长存;他们的后裔 要坚立 在你面前。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, '(大卫的诗。)我的心哪,你要称颂 耶和华!凡 在我里面的,也要称颂 他的圣 名! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, '我的心哪,你要称颂 耶和华!不可 忘记 他的一切 恩惠! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, '他赦免 你的一切 罪孽,医治 你的一切 疾病。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, '他救赎 你的命 脱离死亡,以仁爱 和慈悲 为你的冠冕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, '他用美物 使你所愿 的 得以知足,以致你如鹰 返老还 童。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, '耶和华 施行 公义,为一切 受屈的人 伸冤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, '他使摩西 知道 他的法则,叫以色列 人 晓得他的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, '耶和华 有怜悯,有恩典,不轻易 发怒,且有丰盛的 慈爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, '他不 长久 责备,也不 永远 怀怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, '他没有 按我们的罪过 待 我们,也没有 照我们的罪孽 报应 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, '天 离 地 何等的 高,他的慈爱 向 敬畏他的人 也是何等的大! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, '东 离西 有多远,他叫 我们的过犯 离我们 也有多远! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, '父亲 怎样怜恤 他的儿女,耶和华 也怎样怜恤 敬畏他的人! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, '因为 他 知道 我们的本体,思念 我们不过是 尘土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, '至于 世人,他的年日 如草一样。他发旺 如 野地 的花, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, ' 经风 一吹,便归无有;它的原处 也不 再 认识它。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, '但耶和华 的慈爱 归于  敬畏他的人,从亘古 到 永远;他的公义 也归于 子子 孙孙─ ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, '就是那些遵守 他的约、记念 他的训词 而遵行的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, '耶和华 在天上 立定 宝座;他的权柄(原文是国)统管 万有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, '听从 他命令、成全 他旨意、有大 能的 天使,都要称颂 耶和华! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, '你们作他的诸 军,作他的仆役,行 他所喜悦的,都要称颂 耶和华! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, '你们一切 被他造的,在他所治理 的各 处,都要称颂 耶和华!我的心哪,你要称颂 耶和华!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, '我的心哪,你要称颂 耶和华!耶和华─我的 神啊,你为至 大!你以尊荣 威严 为衣服, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, '披上 亮光,如披外袍,铺张 穹苍,如铺幔子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, '在水中 立 楼阁的栋梁,用 云彩 为车辇,藉 借著 风 的翅膀 而行, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, '以风 为 使者,以火 焰 为仆役, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, '将地 立 在 根基上,使地永 不 动摇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, '你用深水 遮盖地面,犹如衣裳;诸水 高 过 山岭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, '你的斥责 一发,水便奔逃;你的雷 声 一发,水便奔流。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, '诸山 升上,诸谷 沉下(或译:随山上翻,随谷下流),归 你为它 所 安定 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, '你定了 界限,使水不能 过去,不再 转回 遮盖 地面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, '耶和华使 泉源 涌在山谷,流 在 山间, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, '使野地的 走兽 有水喝,野驴 得解 其渴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, '天上 的飞鸟 在水旁 住宿,在 树枝 上啼叫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, '他从楼阁中 浇灌 山岭;因他作为 的功效,地 就丰足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, '他使草 生长,给六畜吃,使菜蔬发长,供给人 用,使人从 地 里能得 食物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, '又得酒 能悦 人 心,得油 能润 人面,得粮 能养 人 心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, '佳美的树木,就是黎巴嫩 的香柏树,是耶和华 所 栽种的,都满了汁浆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, '雀鸟 在其 上 搭窝;至于 鹤,松树 是牠的房屋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, '高 山 为野山羊 的住所;岩石 为沙番的藏处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, '你安置 月亮 为定节令;日头 自知 沉落。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, '你造 黑暗 为 夜, 林 中的百 兽 就都爬出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, '少壮狮子 吼叫,要抓食,向 神 寻求 食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, '日头 一出,兽便躲避,卧 在 洞里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, '人 出去 做工,劳碌 直到 晚上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, '耶和华啊,你所造的 何其 多!都 是你用智慧 造成的;遍地 满了 你的丰富。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, '那里 有海,又大 又广;其中 有无 数 的动物,大 小 活物都有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, '那里 有船 行走,有 你所造的 鳄鱼 游泳 在其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, '这都 仰望 你 按时 给 牠食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, '你给 牠们,牠们便拾起来;你张 手,牠们饱得 美食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, '你掩 面,牠们便惊惶;你收回 牠们的气,牠们就死亡,归 于  尘土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, '你发出 你的灵,牠们便受造;你使地 面 更换为新。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, '愿 耶和华 的荣耀 存 到永远!愿 耶和华 喜悦 自己所造的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, '他看 地,地便震动;他摸 山,山就冒烟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, '我要一生 向耶和华 唱诗!我还活的时候,要向我 神 歌颂! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, '愿 他 以我的默念 为甘甜!我要 因耶和华 欢喜! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, '愿 罪人 从 世 上消灭!愿 恶人 归于  无有!我的心哪,要称颂 耶和华!你们要赞美 耶和华(原文是哈利路亚;下同)!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, '你们要称谢 耶和华,求告 他的名,在万民中 传扬 他的作为! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, '要向他 唱诗 歌颂,谈论 他一切 奇妙的作为! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, '要以他的圣 名 夸耀!寻求 耶和华的人,心 中应当欢喜! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, '要寻求 耶和华 与他的能力,时常 寻求 他的面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, '他仆人 亚伯拉罕 的后裔,他所拣选 雅各 的子孙哪,你们要记念 他奇妙的作为和 他 的 奇事,并他口中 的判语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, '他是 耶和华─我们的 神;全 地 都有他的判断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, '他记念 他的约,直到永远;他所吩咐的 话,直到千 代─ ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, '就是与 亚伯拉罕 所 立的约,向以撒 所起的誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, '他又将这约向雅各 定 为律例,向以色列 定为永远 的约, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, '说:我必将 迦南 地 赐 给你,作你产业 的分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, '当时,他们人丁有限,数目 稀少,并且在那地 为寄居的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, '他们从这邦 游 到 那邦,从这国 行到 那 国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, '他不 容 什么人 欺负他们,为他们的缘故 责备 君王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, '说:不可 难为 我受膏的人,也不可 恶待 我的先知。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, '他命 饥荒 降在 那地上,将所倚靠 的粮食 全行 断绝, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, '在他们以先 打发 一个人去─约瑟 被卖 为奴仆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, '人用脚镣 伤 他的脚;他 被铁链 捆拘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, '耶和华 的话 试炼他,直 等到 他所说的 应验了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, '王 打发 人把他解开 ,就是治理 众民的,把他释放, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, '立他 作王家 之主,掌管 他一切 所有的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, '使他随意 捆绑 他的臣宰,将智慧教导 他的长老。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, '以色列 也到了 埃及;雅各 在含 地 寄居。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, '耶和华使 他的百姓 生养 众多,使他们比敌人 强盛, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, '使敌人的心 转去 恨 他的百姓,并用诡计 待他的仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, '他打发 他的仆人 摩西 和他所 拣选的 亚伦, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, '在敌人中间 显 他的神迹,在含 地 显他的奇事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, '他命 黑暗,就有黑暗;没有 违背 他话的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, '他叫 埃及的水 变 为血,叫 他们的鱼 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, '在他们的地 上以及王 宫的内室,青蛙 多多滋生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, '他说一声,苍蝇 就成群而来,并有虱子 进入他们四 境。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, '他给 他们降下冰雹 为雨,在他们的地上 降下火 焰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, '他也击打 他们的葡萄树 和无花果树,毁坏 他们境内 的树木。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, '他说一声,就有蝗虫 蚂蚱 上来,不 计其数, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, '吃尽了 他们地上 各样的 菜蔬 和 田地 的出产。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, '他又击杀 他们国内 一切的 长子,就是 他们强壮 时头生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, '他领自己的百姓 带银子 金子出来;他支派中 没有一个 软弱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, '他们出来的时候,埃及人 便欢喜;原来 埃及人惧怕 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, '他铺张 云彩 当遮盖,夜间 使火 光照。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, '他们一求,他就使鹌鹑 飞来,并用天上 的粮食 叫他们饱足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, '他打开  磐石,水 就涌出;在干旱之处,水流 成河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, '这都因 他记念 他的圣 言和 他的仆人 亚伯拉罕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, '他带领 百姓 欢乐而出,带领 选民 欢呼前往。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, '他将列国 的地 赐 给他们,他们便承受 众民 劳碌得来的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, '好使 他们遵 他的律例,守 他的律法。你们要赞美 耶和华!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, '你们要赞美 耶和华!要称谢 耶和华,因 他本为善; 他的慈爱 永远长存! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, '谁 能传说 耶和华 的大能?谁能表明 他一切的 美德? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, '凡遵守 公平、常 行 公义的,这人便为有福! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, '耶和华啊,你用恩惠 待你的百姓;求你也用这恩惠记念我,开 你的救恩 眷顾我, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, '使我见 你选民 的福,乐 你国民 的乐,与 你的产业 一同夸耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, '我们与 我们的祖宗 一同犯罪;我们作了孽,行了恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, '我们的祖宗 在埃及 不 明白 你的奇事,不 记念 你丰盛的 慈爱,反倒在 红 海 行了悖逆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, '然而,他因 自己的名 拯救他们,为要彰显 他的大能, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, '并且斥责 红 海,海便干了;他带领他们 经过深处,如同经过旷野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, '他拯救他们 脱离恨 他们人的手,从仇敌 手中 救赎他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, '水 淹没 他们的敌人,没有 一个 存留。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, '那时,他们才信了 他的话,歌唱 赞美他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, '等不多时,他们就忘了 他的作为,不 仰望 他的指教, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, '反倒在旷野 大起 欲心,在荒地 试探 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, '他将他们所求的 赐 给他们,却使 他们的心灵 软弱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, '他们又在营中 嫉妒 摩西 和耶和华 的圣者 亚伦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, '地 裂开 ,吞下 大坍,掩盖 亚比兰 一党的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, '有火 在他们的党中 发起;有火焰 烧毁了 恶人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, '他们在何烈山 造了 牛犊,叩拜 铸成的像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, '如此将 他们荣耀 的主换 为吃 草 之牛 的像, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, '忘了 神─他们的救主;他曾在埃及 行 大事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, '在含 地 行奇事,在 红 海 行可畏的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, '所以,他说 要灭绝他们;若非 有他所拣选 的摩西 站 在当中(原文是破口),使他的忿怒 转消,恐怕他就灭绝他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, '他们又藐视 那美 地,不 信 他的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, '在自己帐棚内 发怨言,不 听 耶和华 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, '所以,他对他们 起誓:必叫他们 倒 在旷野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, '叫他们的后裔 倒 在列国之中,分散 在各地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, '他们又与巴力•毘珥 连合,且吃了 祭死神(或译:人)的物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, '他们这样行,惹耶和华发怒,便有瘟疫 流行 在他们中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, '那时,非尼哈 站起,刑罚恶人,瘟疫 这才止息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, '那就算为 他的 义,世世代代,直到 永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, '他们在 米利巴 水 又叫耶和华发怒,甚至摩西 也受了亏损, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, '是因 他们惹动 他的灵,摩西(原文是他)用嘴 说了急躁的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, '他们不 照耶和华 所 吩咐的 灭绝 外邦人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, '反与他们 混杂相合,学习 他们的行为, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, '事奉 他们的偶像,这就成了 自己的 网罗, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, '把 自己的儿 女 祭祀 鬼魔, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, '流 无辜人 的血,就是自己儿 女 的血,把他们 祭祀 迦南 的偶像,那地 就被血 污秽了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, '这样,他们被自己所做的 污秽了,在行为上 犯了邪淫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, '所以,耶和华 的怒气 向他的百姓 发作,憎恶 他的产业, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, '将他们交 在外邦人 的手里;恨他们的人 就辖制 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, '他们的仇敌 也欺压他们,他们就伏 在敌人手 下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, '他屡 次 搭救他们,他们 却设谋 背逆,因自己的罪孽 降为卑下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, '然而,他听见 他们哀告的时候,就眷顾 他们的 急难, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, '为他们 记念 他的约,照他丰盛的 慈爱 后悔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, '他也使 他们 在凡 掳掠他们的人 面前 蒙怜恤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, '耶和华─我们的 神啊,求你拯救我们,从 外邦 中招聚我们,我们好称赞 你的圣 名,以赞美你 为夸胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, '耶和华─以色列的 神 是应当称颂的,从 亘古 直到 永远。愿 众 民 都说:阿们!你们要赞美 耶和华!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, '你们要称谢 耶和华,因 他本为善; 他的慈爱 永远长存! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, '愿 耶和华 的赎民 说这话,就是他从敌人 手 中所 救赎的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, '从各地,从东 从西,从南 从北,所招聚来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, '他们在旷野 荒 地 漂流,寻不 见 可住 的城邑, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, '又饥 又 渴,心 里 发昏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, '于 是,他们 在苦难中 哀求 耶和华;他从他们的祸患中 搭救他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, '又领他们 行走直 路,使他们往 可居住 的城邑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, '但愿 人因耶和华 的慈爱 和他向人 所行的奇事 都称赞他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, '因 他使心里 渴慕的人 得以知足,使心里 饥饿 的人得饱 美物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, '那些坐在 黑暗中、死荫 里的人被困苦 和铁 炼 链 𫔀捆锁, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, '是因 他们违背 神 的话语,藐视 至高者 的旨意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, '所以,他用劳苦 治服 他们的心;他们仆倒,无人 扶助。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, '于 是,他们 在苦难中 哀求 耶和华;他从他们的祸患中 拯救他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, '他从黑暗中 和死荫 里领他们出来,折断 他们的绑索。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, '但愿 人因耶和华 的慈爱 和他向人 所行的奇事 都称赞他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, '因为 他打破了 铜 门,砍断了 铁 闩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, '愚妄人 因 自己的过犯 和自己的罪孽 便受苦楚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, '他们心里 厌恶 各样的 食物,就临近 死 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, '于 是,他们 在苦难中 哀求 耶和华;他从他们的祸患中 拯救他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, '他发 命 医治他们,救 他们脱离死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, '但愿 人因耶和华 的慈爱 和他向人 所行的奇事 都称赞他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, '愿 他们以感谢 为祭 献给他,欢呼 述说 他的作为! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, '在 海 上坐船,在大 水中 经理 事务的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, '他们 看见 耶和华 的作为,并他在深水中 的奇事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, '因他一吩咐,狂 风 就起来,海中的波浪 也扬起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, '他们上到 天空,下到 海底;他们的心 因患难 便消化。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, '他们摇摇晃晃,东倒西歪,好像醉酒的人; 他们的智慧 无法可施。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, '于 是,他们 在苦难中 哀求 耶和华,他从他们的祸患中 领出他们来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, '他使 狂风 止息,波浪 就平静。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, ' 风息浪静,他们便欢喜;他就引他们 到 所愿 去 的海口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, '但愿 人因耶和华 的慈爱 和他向人 所行的奇事 都称赞他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, '愿 他们在民 的会中 尊崇他,在长老 的位上 赞美他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, '他使江河 变 为旷野,叫水 泉 变为干渴之地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, '使肥 地 变为碱地;这都因其间 居民的 罪恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, '他使旷野 变 为水 潭,叫旱 地 变为水 泉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, '他使饥饿 的人住 在那里,好建造 可住 的城邑, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, '又种 田地,栽 葡萄园,得享所出的 土产。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, '他又赐福给他们,叫他们生养 众多,也不 叫他们的牲畜 减少。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, '他们又因暴虐、患难、愁苦,就减少 且卑下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, '他使 君王 蒙羞 被辱,使他们在荒废 无 路 之地漂流。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, '他却将穷乏人 安置在高处,脱离苦难,使 他的家属 多如羊群。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, '正直人 看见 就欢喜;罪孽之辈 必塞 口无言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, '凡 有智慧的,必在这些事上 留心,也必思想 耶和华 的慈爱。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, '(大卫的 诗 歌。) 神啊,我心 坚定;我口(原文是荣耀)要唱诗 歌颂! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, '琴 瑟啊,你们当醒起!我自己要极早 醒起! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, '耶和华啊,我要在万民中 称谢你,在列邦中 歌颂你! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, '因为,你的慈爱 大 过 诸天;你的诚实 达到 穹苍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, '神啊,愿 你崇高 过于  诸天!愿 你的荣耀 高过 全 地! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, '求你应允我们,用右手 拯救我们,好叫 你所亲爱的人 得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, '神 已经指著他的圣洁 说(说:或译应许我):我要欢乐;我要分开  示剑,丈量 疏割 谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, '基列 是我的;玛拿西 是我的;以法莲 是护卫 我头的;犹大 是我的杖; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, '摩押 是我的沐浴 盆;我要向 以东 抛 鞋;我必因胜 非利士 呼喊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, '谁 能领我 进坚固 城?谁 能引我 到 以东地? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, '神啊,你不是 丢弃了我们吗? 神啊,你不 和我们的军兵 同去吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, '求你 帮助 我们 攻击敌人,因为人 的帮助 是枉然的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, '我们倚靠 神 才得施展 大能,因为践踏 我们敌人 的就是他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, '(大卫的 诗,交与伶长。)我所赞美的 神啊,求你不要 闭口不言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, '因为 恶人 的嘴 和诡诈人 的口 已经张开  攻击我;他们用撒谎 的舌头 对我 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, '他们围绕我,说怨恨 的话,又无故地 攻打我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, '他们与我为敌 以报 我爱,但我 专心祈祷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, '他们向我 以恶 报 善,以恨 报 爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, '愿 你派 一个恶人 辖制他,派一个对头 站 在 他右边! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, '他受审判的时候,愿 他出来 担当罪名!愿 他的祈祷 反成为 罪! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, '愿  他的年日 短少!愿 别人 得 他的职分! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, '愿  他的儿女 为孤儿,他的妻子 为寡妇! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, '愿 他的儿女 漂流 讨饭,从他们荒凉之处出来 求食! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, '愿 强暴的债主 牢笼 他 一切 所有的!愿 外人 抢 他劳碌得来的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, '愿  无人 向他 延绵 施恩!愿  无人 可怜 他的孤儿! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, '愿  他的后人 断绝,名字 被涂抹,不传于 下 代! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, '愿 他祖宗 的罪孽 被 耶和华 记念!愿 他母亲 的罪过 不 被涂抹! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, '愿  这些罪常 在耶和华 面前,使他的名号 断绝 于 世! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, '因为 他不 想 施 恩,却逼迫 困苦 穷乏 的和伤 心 的人,要把他们治死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, '他爱 咒骂,咒骂就临到他;他不 喜爱 福乐,福乐就与他 远离! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, '他拿咒骂 当衣服 穿上;这咒骂就如水 进 他里面,像油 入他的骨头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, '愿  这咒骂当他 遮 身的衣服,当他常 束 的腰带! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, '这 就是我对头 和用恶言 议论 我 的人从 耶和华 那里所受的报应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, '主─耶和华啊,求你 为 你的名 恩待 我;因 你的慈爱 美好,求你搭救我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, '因为 我 困苦 穷乏,内 心 受伤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, '我如日影 渐渐偏斜 而去;我如蝗虫 被抖出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, '我因禁食,膝骨 软弱;我身上的肉 也渐渐瘦了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, '我受 他们的 羞辱,他们看见我 便摇 头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, '耶和华─我的 神啊,求你帮助我,照你的慈爱 拯救我, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, '使他们知道 这是 你的手,是你─耶和华 所行的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, '任凭他们 咒骂,惟愿 你 赐福;他们几时起来 就必蒙羞,你的仆人 却要欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, '愿 我的对头 披戴 羞辱!愿 他们以自己的羞愧 为外袍 遮身! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, '我要用口 极力 称谢 耶和华;我要在众人 中间 赞美他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, '因为 他必站 在穷乏人 的右边,要救 他脱离审判 他灵魂的人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, '(大卫的 诗。)耶和华 对我主 说:你坐 在我的右边,等 我使 你仇敌 作你的脚 凳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, '耶和华 必使你从锡安 伸出 能力 的杖来;你要在你仇敌 中 掌权。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, '当你掌权 的日子(或译:行军的日子),你的民 要以圣洁 的妆饰为衣(或译:以圣洁为妆饰),甘心牺牲自己;你的民多如清晨的甘露(或译:你少年时光耀如清晨 的甘露)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, '耶和华 起了誓,决不 后悔,说:你 是照著 麦基洗德 的等次 永远 为祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, '在 你右边 的主,当他发怒 的日子,必打伤 列王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, '他要在列邦中 刑罚恶人,尸首 就遍满各处;他要在 许多 国 中打破 仇敌的头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, '他要喝 路 旁的河水,因此 必抬起 头来。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, '你们要赞美 耶和华!我要在正直人 的大会中,并公会中,一 心 称谢 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, '耶和华 的作为 本为大;凡 喜爱的 都必考察。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, '他所行的 是尊荣 和威严;他的公义 存到 永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, '他行了 奇事,使人记念;耶和华 有恩惠,有怜悯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, '他赐 粮食 给敬畏他的人;他必永远 记念 他的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, '他向百姓 显出 大能 的作为,把外邦 的地赐 给他们 为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, '他手 所行的 是诚实 公平;他的训词 都 是确实的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, '是永永 远远 坚定的,是按诚实 正直 设立的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, '他向百姓 施行 救赎,命定 他的约,直到永远;他的名 圣 而可畏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, '敬畏 耶和华 是智慧 的开 端;凡 遵行 他命令的是聪明人。耶和华是永远 当赞美的!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, '你们要赞美 耶和华!敬畏 耶和华,甚 喜爱 他命令的,这人 便为有福! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, '他的后裔 在世 必 强盛;正直人 的后代 必要蒙福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, '他家中 有货物,有钱财;他的公义 存 到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, '正直人 在黑暗中,有光 向他发现;他有恩惠,有怜悯,有公义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, '施恩与人、借贷与人的,这人 事情顺利;他被审判的时候 要诉明 自己的冤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, ' 他永 不 动摇;义人 被记念,直到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, '他必不 怕 凶恶 的信息;他心 坚定,倚靠 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, '他心 确定,总不 惧怕,直到 他看见 敌人遭报。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, '他施舍钱财,赒济 贫穷;他的仁义 存 到永远。他的角 必被高举,大有荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, '恶人 看见 便恼恨,必咬 牙 而消化;恶人 的心愿  要归灭绝。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, '你们要赞美 耶和华!耶和华 的仆人哪,你们要赞美,赞美 耶和华 的名! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, '耶和华 的名 是 应当称颂的,从今时 直到 永远! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, '从日 出 之地到 日落之处,耶和华 的名 是应当赞美的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, '耶和华 超乎 万 民 之上;他的荣耀 高过 诸天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, '谁 像耶和华─我们的 神呢?他坐在 至高之处, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, '自己谦卑,观看 天上 地下的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, '他从灰尘里 抬举 贫寒人,从粪堆中 提拔 穷乏人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, '使他们与 王子 同坐,就是与 本国 的王子同坐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, '他使不能生育的妇人 安居 家中,为多子 的乐 母。你们要赞美 耶和华!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, '以色列 出了 埃及,雅各 家 离开 说异言 之民; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, '那时,犹大 为 主的圣所,以色列 为他所治理的国度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, '沧海 看见 就奔逃;约旦河 也倒 流。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, '大山 踊跃,如公羊;小山跳舞,如羊羔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, '沧海啊,你 为何 奔逃?约旦哪,你为何倒 流? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, '大山哪,你为何踊跃,如公羊?小山哪,你为何跳舞,如羊羔? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, '大地啊,你因见主 的面,就是雅各 神 的面,便要震动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, '他叫磐石 变为 水 池,叫坚石 变为泉源。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, '耶和华啊,荣耀 不要 归与我们,不要 归与我们;要 因 你的慈爱和 诚实 归 在你的名下! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, '为何 容外邦人 说:他们的 神 在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, '然而,我们的 神 在天上,都随 自己的意旨 行事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, '他们的偶像 是金的,银的,是人 手 所造的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, '有口 却不 能言,有眼 却不 能看, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, '有耳 却不 能听,有鼻 却不 能闻, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, '有手 却不 能摸,有脚 却不 能走,有喉咙 也不 能出声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, '造他的 要 和他一样;凡 靠 他的也要如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, '以色列啊,你要倚靠 耶和华!他是 你的帮助 和你的盾牌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, '亚伦 家啊,你们要倚靠 耶和华!他是 你们的帮助 和你们的盾牌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, '你们敬畏 耶和华的,要倚靠 耶和华!他是 你们的帮助 和你们的盾牌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, '耶和华 向来眷念我们;他还要赐福给我们:要赐福 给 以色列 的家,赐福 给 亚伦 的家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, '凡敬畏 耶和华的,无论 大 小,主必赐福给他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, '愿 耶和华 叫你们 和 你们的子孙 日见加增。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, '你们 蒙了造 天 地 之耶和华 的福! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, '天,是耶和华的 天;地,他却给了 世人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, '死人 不 能赞美 耶和华;下到 寂静 中的也都 不能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, '但我们 要称颂 耶和华,从今时 直到 永远。你们要赞美 耶和华!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, '我爱 耶和华,因为 他听了 我的声音 和我的恳求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, '他既 向我 侧 耳,我一生 要求告他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, '死亡 的绳索 缠绕我;阴间 的痛苦 抓住我;我遭遇 患难 愁苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, '那时,我便求告 耶和华 的名,说:耶和华啊,求 你救 我的灵魂! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, '耶和华 有恩惠,有公义;我们的 神 以怜悯为怀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, '耶和华 保护 愚人;我落到卑微的地步,他救了 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, '我的心哪!你要仍归 安乐,因为 耶和华 用厚恩 待你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, '主啊,你救 我的命 免了死亡,救 我的眼 免了 流泪,救 我的脚 免了跌倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, '我要在耶和华 面前 行 活人 之路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, '我因信,所以 如此说话;我 受了极大 的困苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, '我 曾急促地 说:人 都 是说谎的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, '我拿什么 报答 耶和华 向我 所赐的一切 厚恩? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, '我要举起 救恩 的杯,称扬 耶和华 的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, '我要 在他众 民 面前 向耶和华 还 我的愿 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, '在耶和华 眼中,看圣民 之死 极为宝贵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, '耶和华 啊,我 真是 你的仆人;我是 你的仆人,是你婢女 的儿子。你已经解开  我的绑索。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, '我要以感谢 为祭 献 给你,又要求告 耶和华 的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, '我要 在他众 民 面前,在耶和华 殿 的院内,在耶路撒冷 当中,向耶和华 还 我的愿 。你们要赞美 耶和华! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'a   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, '万 国啊,你们都当赞美 耶和华!万 民哪,你们都当颂赞他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, '因为 他向我们 大 施慈爱;耶和华 的诚实 存到永远。你们要赞美 耶和华!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, '你们要称谢 耶和华,因 他本为善; 他的慈爱 永远长存! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, '愿  以色列 说: 他的慈爱 永远长存! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, '愿  亚伦 的家 说: 他的慈爱 永远长存! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, '愿  敬畏 耶和华 的说: 他的慈爱 永远长存! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, '我在急难中 求告 耶和华,他 就应允我,把我安置在宽阔之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, '有耶和华 帮助我,我必不 惧怕,人 能把我 怎么样呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, '在那帮助我的人中,有耶和华 帮助我,所以我要 看见 那恨我的人遭报。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, '投靠 耶和华,强 似倚赖 人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, '投靠 耶和华,强 似倚赖 王子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, '万 民 围绕我,我靠耶和华 的名 必 剿灭他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, '他们环绕我, 围困我,我靠耶和华 的名 必 剿灭他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, '他们如同蜂子 围绕我,好像烧荆棘 的火,必被熄灭;我靠耶和华 的名,必 剿灭他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, '你推我,要叫我跌倒,但耶和华 帮助了我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, '耶和华 是我的力量,是我的诗歌;他也成了 我的 拯救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, '在义人 的帐棚里,有欢呼 拯救 的声音;耶和华 的右手 施展 大能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, '耶和华 的右手 高举;耶和华 的右手 施展 大能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, '我必不 致死,仍要 存活,并要传扬 耶和华 的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, '耶和华 虽严严地 惩治我,却未 曾将我交 于 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, '给我 敞开  义 门;我要进去 称谢 耶和华! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, '这是 耶和华的 门;义人 要进去! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, '我要称谢你,因为 你已经应允我,又成了 我的 拯救! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, '匠人 所弃 的石头 已成了 房角 的头块石头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, '这 是 耶和华 所做的,在我们眼中 看为 希奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, '这是 耶和华 所定 的日子,我们在其中 要高兴 欢喜! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, '耶和华啊, 求 你拯救!耶和华啊, 求 你使我们亨通! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, '奉耶和华 名 来的 是应当称颂的!我们从耶和华 的殿 中为你们祝福! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, '耶和华是 神;他光照了 我们。理当用绳索 把祭牲 拴住,牵到 坛 角那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, '你是我的 神,我要称谢你!你是我的 神,我要尊崇你! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, '你们要称谢 耶和华,因 他本为善; 他的慈爱 永远长存!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, '行为 完全、遵行 耶和华 律法的,这人便为有福! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, '遵守 他的法度、一 心 寻求他的,这人便为有福! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, ' 这人不 做 非义的事,但遵行 他的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, '耶和华啊,你 曾将你的训词 吩咐我们,为要我们殷勤 遵守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, '但愿  我行事 坚定,得以遵守 你的律例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, '我看重 你的一切 命令,就 不 至于 羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, '我学了 你公义 的判语,就要以正直 的心 称谢你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, '我必守 你的律例;求你总 不要 丢弃我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, '少年人 用什么 洁净 他的行为呢?是要遵行 你的话! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, '我一 心 寻求了你;求你不要 叫我偏离 你的命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, '我将你的话 藏 在心里,免得 我得罪 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, '耶和华啊,你 是应当称颂的!求你将你的律例 教训我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, '我用嘴唇 传扬 你口中 的一切 典章。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, '我喜悦 你的法度,如同 喜悦一切的 财物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, '我要默想 你的训词,看重 你的道路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, '我要在你的律例中 自乐;我不 忘记 你的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, '求你用厚恩 待 你的仆人,使我存活,我就遵守 你的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, '求你开  我的眼睛,使我看出 你律法中 的奇妙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, '我是 在地上 作寄居的;求你不要 向我 隐瞒 你的命令! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, '我时常 切慕 你的典章,甚至心 碎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, '受咒诅、偏离 你命令 的骄傲人,你已经责备他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, '求你除掉 我所受的 羞辱 和藐视,因 我遵守 你的法度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, '虽 有首领 坐著 妄论 我,你仆人 却思想 你的律例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, ' 你的法度 是我所喜乐的,是我的谋士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, '我的性命 几乎归 于 尘土;求你照你的话 将我救活! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, '我述说 我所行的,你应允了我;求你将你的律例 教训我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, '求你使我明白 你的训词,我就思想 你的奇事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, '我的心 因愁苦 而消化;求你照你的话 使我坚立! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, '求你使我 离开  奸诈 的道,开 恩 将你的律法赐给我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, '我拣选了 忠信 的道,将你的典章 摆在我面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, '我持守 你的法度;耶和华啊,求你不要 叫我羞愧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, '你开 广 我心 的时候,我就往你命令 的道 上直奔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, '耶和华啊,求你将你的律例 指教我,我必遵守 到底! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, '求你赐我悟性,我便遵守 你的律法,且要一 心 遵守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, '求你叫我遵行 你的命令,因为 这是 我所喜乐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, '求你使我的心 趋 向 你的法度,不 趋向 非义之财。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, '求你叫我转 眼 不看 虚假,又叫我在你的道中 生活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, '你向敬畏你的人 所 应许的话,求你向仆人 坚定! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, '求你使我所 怕 的羞辱 远离我,因 你的典章 本为美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, ' 我羡慕 你的训词;求你使我在你的公义上 生活! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, '耶和华啊,愿 你照你的话,使你的慈爱,就是你的救恩,临到我身上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, '我就有话 回答 那羞辱我的,因 我倚靠 你的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, '求你叫真理 的话 总 不 离开  我口,因 我仰望 你的典章。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, '我要常 守 你的律法,直到永永远远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, '我要自由而行(或译:我要行在宽阔之地),因 我素来考究 你的训词。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, '我也要在君王 面前 论说 你的法度,并不 至于 羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, '我要在你的命令中 自乐;这命令 素来是我所爱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, '我又要遵行(原文是举 手) 你的命令,这命令 素来是我所爱的;我也要思想 你的律例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, '求你记念 向你仆人 所应许的话, 叫我有盼望。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, '这 话 将我救活了;我在患难中,因此 得安慰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, '骄傲的人 甚 侮慢我,我却未 曾偏离 你的律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, '耶和华啊,我记念 你从古 以来的典章,就得了安慰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, '我见恶人 离弃 你的律法,就怒气 发作,犹如火烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, '我在世 寄居,素来以你的律例 为 诗歌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, '耶和华啊,我夜间 记念 你的名,遵守 你的律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, '我 所以如此,是 因 我守 你的训词。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, '耶和华 是我的福分;我曾说,我要遵守 你的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, '我一 心 求过 你的恩;愿 你照你的话 怜悯我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, '我思想 我所行的道,就转 步 归向 你的法度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, '我急忙 遵守 你的命令,并不 迟延。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, '恶人 的绳索 缠绕我,我却没有 忘记 你的律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, '我因 你公义 的典章,半 夜 必起来 称谢 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, '凡 敬畏你、守 你训词的人,我 都与他作伴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, '耶和华啊,你的慈爱 遍满 大地;求你将你的律例 教训我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, '耶和华啊,你向来是照你的话 善 待 仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, '求你将精明 和知识 赐给我,因 我信了 你的命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, '我 未受苦 以先 走迷了路,现在 却遵守 你的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, '你 本为善,所行的也善;求你将你的律例 教训我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, '骄傲人 编造 谎言 攻击我,我 却要一 心 守 你的训词。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, '他们心 蒙脂 油,我 却喜爱 你的律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, ' 我受苦 是与我 有益,为要 使我学习 你的律例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, '你口中的训言(或译:律法)与我 有益,胜于 千万 的金 银。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, '你的手 制造我,建立我;求你赐我悟性,可以学习 你的命令! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, '敬畏你的人 见我 就要欢喜,因 我仰望 你的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, '耶和华啊,我知道 你的判语 是公义的;你使我受苦 是以诚实待我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, ' 求 你照著应许仆人 的话,以慈爱 安慰我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, '愿 你的慈悲 临到我,使我存活,因 你的律法 是我所喜爱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, '愿 骄傲人 蒙羞,因为 他们无理 地倾覆 复我;但我 要思想 你的训词。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, '愿 敬畏你的人 归 向我,他们就知道 你的法度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, ' 愿 我的心 在你的律例上 完全,使 我不 致蒙羞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, '我心 渴想 你的救恩,仰望 你的应许。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, '我因盼望你的应许 眼睛 失明,说:你何时 安慰我? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, ' 我 好像烟薰 的皮袋,却不 忘记 你的律例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, '你仆人 的年日 有多少呢?你几时 向逼迫我的人 施行 审判呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, '不 从你律法 的 骄傲人 为我 掘了 坑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, '你的命令 尽都 诚实;他们无理 地逼迫我,求你帮助我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, '他们几乎 把我从世上 灭绝,但我 没有 离弃 你的训词。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, '求你照你的慈爱 将我救活,我就遵守 你口中 的法度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, '耶和华啊,你的话 安定 在天,直到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, '你的诚实 存到万代;你坚定了 地,地就长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, '天地照你的安排 存 到今日; 万物 都是你的仆役。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, '我若不是 喜爱 你的律法,早就 在苦难中 灭绝了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, '我永 不 忘记 你的训词,因 你用这训词 将我救活了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, '我 是属你的,求你救我,因 我寻求了 你的训词。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, '恶人 等待 我,要灭绝我,我却要揣摩 你的法度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, '我看 万 事 尽都有限,惟有你的命令 极其 宽广。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, '我何等 爱慕 你的律法, 终 日 不住地思想。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, '你的命令 常 存 在我心里,使我比仇敌 有智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, '我比 我的师傅 更通达,因 我 思想 你的法度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, '我比年老的 更明白,因 我守了 你的训词。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, '我禁止 我脚 走一切的 邪 路,为要 遵守 你的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, '我没有 偏离 你的典章,因为 你 教训了我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, '你的言语 在我上膛 何等 甘美,在我口中 比蜜更甜! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, '我藉 借著你的训词 得以明白,所以 我恨 一切的 假 道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, '你的话 是我脚前的 灯,是我路上的 光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, '你公义 的典章,我曾起誓 遵守,我必按誓而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, '我甚是 受苦;耶和华啊,求你照你的话 将我救活! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, '耶和华啊,求 你悦纳 我口中 的赞美为供物,又将你的典章 教训我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, '我的性命 常 在危险之中,我却不 忘记 你的律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, '恶人 为我 设下 网罗,我却没有 偏离 你的训词。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, '我以你的法度 为永远 的产业,因 这是 我心中 所喜爱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, '我的心 专向 你的律例,永远 遵行,一直到底。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, '心怀二意的人 为我所恨;但你的律法 为我所爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, '你 是我藏身之处,又是我的盾牌;我甚仰望 你的话语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, '作恶的人哪,你们离开  我吧!我好遵守我 神 的命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, '求你照你的话 扶持我,使我存活,也不 叫我因失望 而害羞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, '求你扶持我,我便得救,时常 看重 你的律例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, '凡 偏离 你律例的人,你都轻弃他们,因为 他们的诡诈 必归虚空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, '凡 地上 的恶人,你除掉他,好像除掉渣滓;因此 我爱 你的法度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, '我因惧怕你,肉 就发抖;我也怕 你的判语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, '我行过 公平 和公义,求你不要 撇下我 给欺压我的人! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, '求你为仆人 作保,使我得好处,不 容骄傲人 欺压我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, '我因盼望你的救恩 和你公义 的话 眼睛 失明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, '求你照你的慈爱 待 仆人,将你的律例 教训我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, '我是 你的仆人,求你赐我悟性,使我得知 你的法度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, '这是耶和华 降罚 的时候,因人废了 你的律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, '所以,我爱 你的命令 胜于 金子,更胜于 精金。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, ' 你一切的 训词,在万事上 我都以为正直;我却恨恶 一切 假 道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, '你的法度 奇妙,所以 我一心 谨守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, '你的言语 一解开  就发出亮光,使愚人 通达。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, '我张 口 而气喘,因 我切慕 你的命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, '求你转 向我,怜悯我,好像你素常 待那些爱 你名的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, '求你用你的话 使我脚步 稳当,不许 什么 罪孽 辖制 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, '求你救我 脱离人 的欺压,我要遵守 你的训词。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, '求你用脸 光照 仆人,又将 你的律例 教训我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, '我的眼泪 下流 成河,因为 他们不 守 你的律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, '耶和华啊,你 是公义的;你的判语 也是正直的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, '你所命定 的法度 是凭公义 和至 诚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, '我心焦急,如同火烧,因 我敌人 忘记 你的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, '你的话 极其 精炼,所以你的仆人 喜爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, '我 微小,被人藐视,却不 忘记 你的训词。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, '你的公义 永远长存;你的律法 尽都真实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, '我遭遇 患难 愁苦,你的命令 却是我所喜爱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, '你的法度 永远 是公义的;求你赐我悟性,我就活了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, '耶和华啊,我一 心 呼吁你;求你应允我,我必谨守 你的律例! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, '我向你呼吁,求你救我!我要遵守 你的法度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, '我趁 天未亮 呼求;我仰望了 你的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, '我趁 夜更 未换将眼睁开 ,为要思想 你的话语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, '求你照你的慈爱 听 我的声音;耶和华啊,求你照你的典章 将我救活! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, '追求 奸恶 的人临近了;他们远离 你的律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, '耶和华啊,你 与我相近;你一切的 命令 尽都真实! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, '我因学你的法度,久 已知道是 你永远 立定的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, '求你看顾 我的苦难,搭救我,因 我不 忘记 你的律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, '求你为我辨 屈,救赎我,照你的话 将我救活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, '救恩 远 离恶人,因为 他们不 寻求 你的律例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, '耶和华啊,你的慈悲 本为大;求你照你的典章 将我救活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, '逼迫我的,抵挡我的,很多,我却没有 偏离 你的法度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, '我看见 奸恶的人 就甚憎恶,因为 他们不 遵守 你的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, '你看 我怎样 爱 你的训词!耶和华啊,求你照你的慈爱 将我救活! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, '你话 的总纲 是真实;你一切 公义 的典章 是永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, '首领 无故地 逼迫我,但我的心 畏惧 你的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, '我 喜爱 你的话,好像人得了 许多 掳物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, '谎话 是我所恨恶 所憎嫌的;惟你的律法 是我所爱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, '我因 你公义 的典章 一天 七次 赞美你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, '爱 你律法 的人有大 平安,什么都不能 使他们 绊脚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, '耶和华啊,我仰望了 你的救恩,遵行了 你的命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, '我心里 守了 你的法度;这法度我甚 喜爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, '我遵守了 你的训词 和法度,因 我一切 所行的 都在你面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, '耶和华啊,愿 我的呼吁 达 到你面前,照你的话 赐我悟性。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, '愿 我的恳求 达 到你面前,照你的话 搭救我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, '愿 我的嘴 发出 赞美的话,因为 你将律例 教训我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, '愿 我的舌头 歌唱 你的话,因 你一切的 命令 尽都公义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, '愿  你用手 帮助我,因 我拣选了 你的训词。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, '耶和华啊,我切慕 你的救恩!你的律法 也是我所喜爱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, '愿 我的性命 存活,得以赞美你!愿 你的典章 帮助我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, '我如亡 羊 走迷了路,求你寻找 仆人,因 我不 忘记 你的命令。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, '(上行(或作登阶,下同)之诗。)我 在急难中 求告 耶和华,他就应允我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, '耶和华啊,求你救 我 脱离说谎 的嘴唇 和诡诈 的舌头! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, '诡诈 的舌头啊,要给 你 什么呢?要拿什么 加 给你呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, '就是勇士 的利 箭 和 罗腾木(小树名,松类)的炭火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, ' 我寄居 在米设,住 在基达 帐棚 之中,有祸了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, '我 与 那恨恶 和睦 的人许久 同住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, '我 愿 和睦,但 我发言,他们就要 争战 。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, '(上行之 诗。)我要向 山 举 目;我的帮助 从何 而来? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, '我的帮助 从 造 天 地 的耶和华而来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, '他必不 叫 你的脚 摇动;保护你的 必不 打盹! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, ' 保护 以色列的,也不 打盹 也不 睡觉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, '保护你的 是耶和华;耶和华 在 你右边 荫庇你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, '白日,太阳 必不 伤你;夜间,月亮必不害你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, '耶和华 要保护你,免受一切的 灾害;他要保护 你的性命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, '你出 你入,耶和华 要保护你,从今时 直到 永远。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, '(大卫 上行 之诗。)人对我 说:我们往耶和华 的殿 去,我就欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, '耶路撒冷啊, 我们的脚 站 在你的门内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, '耶路撒冷 被建造,如同连络 整齐 的一座城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, '众支派,就是耶和华 的支派,上 那里去,按以色列的 常例(或译:作以色列的证据)称赞 耶和华 的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, '因为 在那里 设立 审判的 宝座,就是大卫 家的 宝座。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, '你们要为耶路撒冷 求 平安!耶路撒冷啊,爱你的人 必然兴旺! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, '愿  你城中 平安!愿 你宫内 兴旺! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, '因 我弟兄 和同伴的缘故,我要说:愿  平安 在你中间! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, '因 耶和华─我们 神 殿的缘故,我要为你 求 福!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, '(上行 之诗。)坐 在天上的主啊,我向你 举 目。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, '看哪,仆人 的眼睛 怎样望 主人 的手,使女 的眼睛 怎样望 主母 的手,我们的眼睛 也照样 望 耶和华─我们的 神,直到 他怜悯我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, '耶和华啊,求你怜悯我们,怜悯我们!因为 我们被藐视,已到极处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, '我们 被那些安逸人 的讥诮 和骄傲人 的藐视,已到极处。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, '(大卫 上行 之诗。)以色列 人要 说:若不是 耶和华 帮助 我们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, '若不是 耶和华 帮助 我们,当人 起来 攻击我们、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, '向我们 发 怒的时候,就 把我们活活地 吞了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, '那时,波涛 必漫过我们,河水 必淹 没 我们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, ' 狂傲的 水 必淹 没 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, '耶和华 是应当称颂的!他没有 把我们当野食 交给他们吞吃(原文是牙齿)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, '我们 好像雀鸟,从捕鸟人 的网罗 里逃脱;网罗 破裂,我们 逃脱了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, '我们得帮助,是在乎倚靠造 天 地 之耶和华 的名。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, '(上行 之诗。)倚靠 耶和华 的人好像锡安 山, 永 不 动摇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, '众山 怎样围绕 耶路撒冷,耶和华 也照样围绕 他的百姓,从今时 直到 永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, ' 恶人 的杖 不 常落 在 义人 的分上,免得 义人 伸 手 作恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, '耶和华啊,求你善待 那些为善 和心里 正直的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, '至于 那偏行 弯曲道路的人,耶和华 必使他和 作 恶 的人一同 出去受刑。愿 平安 归于  以色列!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, '(上行 之诗。)当耶和华 将 那些被掳的 带回 锡安的时候,我们 好像做梦的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, ' 我们满 口 喜笑、满舌 欢呼的时候,外邦中 就 有人说:耶和华 为 他们 行了 大事! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, '耶和华 果然为我们 行了 大事,我们就 欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, '耶和华啊,求你使 我们被掳的人 归回,好像南地的 河水复流。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, '流泪 撒种的,必欢呼 收割! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, '那带 种 流泪 出 去的,必要欢欢乐乐地 带 禾捆 回 来!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, '(所罗门 上行 之诗。)若 不是 耶和华 建造 房屋,建造的人 就枉然 劳力;若 不是 耶和华 看守 城池,看守的人 就枉然 警醒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, '你们清晨早 起,夜晚 安歇,吃 劳碌 得来的饭,本是枉然;惟有 耶和华所亲爱的,必叫 他安然睡觉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, ' 儿女 是耶和华 所赐的产业;所怀的胎 是他所给的赏赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, ' 少年时 所生的儿女 好像勇士 手中 的箭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, ' 箭袋 充满 的人 便为有福;他们 在城门口 和 仇敌 说话 的时候,必不至 于 羞愧。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, '(上行 之诗。)凡 敬畏 耶和华、遵行 他道 的人便为有福! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, '你要 吃 劳碌 得来的;你要享福,事情顺利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, '你妻子 在你的内 室,好像多结果子的 葡萄树;你儿女 围绕 你的桌子,好像橄榄 栽子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, '看哪,敬畏 耶和华 的人 必要 这样 蒙福! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, '愿 耶和华 从锡安 赐福给你!愿 你一生一世 看见 耶路撒冷 的好处! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, '愿 你看见 你儿女 的儿女!愿 平安 归于  以色列!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, '(上行 之诗。)以色列 当 说:从我幼年以来,敌人屡次 苦害我, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, '从我幼年以来,敌人屡次 苦害我,却 没有 胜了 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, '如同扶犁的 在 我背 上扶犁而耕,耕的犁沟 甚长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, '耶和华 是公义的;他砍断了 恶人 的绳索。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, '愿 恨恶 锡安 的都 蒙羞 退 后! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, '愿 他们 像房顶上 的草,未 长成 而枯干, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, '收割的 不 够 一把,捆禾的 也不满怀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, '过路的 也不 说:愿 耶和华 所赐的福 归与你们!我们奉耶和华 的名 给你们 祝福!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, '(上行 之诗。)耶和华啊,我从深处 向你求告! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, '主啊,求你听 我的声音!愿  你侧 耳 听我恳求 的声音! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, '主─耶和华啊,你若 究察 罪孽,谁 能站得住呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, '但 在你 有赦免之恩,要 叫人敬畏你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, '我等候 耶和华,我的心 等候;我也仰望 他的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, '我的心 等候主,胜于 守夜的,等候天亮,胜于 守夜的,等候天亮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, '以色列啊,你当仰望 耶和华!因 他 有 慈爱,有 丰盛的 救恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, '他必 救赎 以色列 脱离一切的 罪孽。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, '(大卫 上行 之诗。)耶和华啊,我的心 不 狂傲,我的眼 不 高大;重大 和测不透的事,我也不 敢行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, ' 我的心 平稳 安静,好像断过奶的孩子 在 他母亲的怀中;我的心 在我里面 真像断过奶的孩子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, '以色列啊,你当仰望 耶和华,从今时 直到 永远!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, '(上行 之诗。)耶和华啊,求你记念 大卫 所受的 一切 苦难! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, '他怎样 向耶和华 起誓,向雅各 的大能者 许愿 , ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, '说:我必不 进 我 的帐幕,也不 上 我的床榻; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, '我不 容 我的眼睛 睡觉,也不容我的眼目 打盹; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, '直等 我为耶和华 寻得 所在,为雅各 的大能者 寻得居所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, ' 我们听 说约柜在以法他,我们在基列‧耶琳 就寻见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, '我们要进 他的居所,在他脚 凳前 下拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, '耶和华啊,求你兴起,和你 有能力 的约柜 同入安息之所! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, '愿 你的祭司 披上 公义!愿 你的圣民 欢呼! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, '求你因你仆人 大卫 的缘故,不要 厌弃 你的受膏者! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, '耶和华 向大卫、凭诚实 起了誓,必不 反复,说:我要使你 所生的 坐 在你的 宝座上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, '你的众子 若 守 我的约 和我所 教训他们 的法度,他们的子孙 必 永远 坐 在你的 宝座上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, '因为 耶和华 拣选了 锡安,愿 意 当作自己的 居所, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, '说:这是 我永远 安息之所;我要住 在这里,因为 是我所愿 意的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, '我要使其中的粮食 丰满,使其中的穷人 饱足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, '我要使祭司 披上 救恩,圣民 大声 欢呼! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, '我要叫 大卫的 角 在那里 发生;我为我的受膏者 预备 明灯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, '我要使他的仇敌 披上 羞耻;但他的冠冕 要在 头上发光。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, '(大卫 上行 之诗。)看哪,弟兄 和睦同 居 是何等地 善,何等地 美! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, '这好比那贵重的 油 浇在 亚伦 的头上,流 到 胡须,又流 到 他的衣 襟; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, '又好比黑门 的甘露 降 在 锡安 山;因为 在那里 有耶和华 所 命定 的福,就是永远 的生命。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, '(上行 之诗。) 耶和华的 仆人 夜间 站 在耶和华 殿中的,你们当称颂 耶和华! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, '你们当向圣所 举 手,称颂 耶和华! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, '愿 造 天 地 的耶和华,从锡安 赐福给你们!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, '你们要赞美 耶和华!你们要赞美 耶和华 的名!耶和华 的仆人 站 在耶和华 殿中;站在我们 神 殿 院中的,你们要赞美他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, '你们要赞美 耶和华!耶和华 本为 善;要歌颂 他的名,因为 这是美好的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, ' 耶和华 拣选 雅各 归自己,拣选以色列 特作自己的子民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, '原来 我 知道 耶和华 为大,也知道我们的主 超乎万 神之上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, '耶和华 在天上,在地下,在海中,在一切的 深处,都 随 自己的意旨 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, '他使云雾 从地 极 上腾,造 电 随雨而闪,从府库中 带出 风来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, '他将埃及 头生的,连人 带 牲畜 都击杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, '埃及啊,他施行 神迹 奇事,在你当中,在法老 和他一切 臣仆身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, '他击杀 许多 的民,又杀戮 大能 的王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, '就是亚摩利 王 西宏 和巴珊 王 噩,并迦南 一切的 国王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, '将他们的地 赏赐 他的百姓 以色列 为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, '耶和华啊,你的名 存到永远!耶和华啊,你可记念的 名存到万代! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, ' 耶和华 要为他的百姓 伸冤,为 他的仆人 后悔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, '外邦 的偶像 是金的,银的,是人 手 所造的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, '有 口 却不能 言,有 眼 却不能 看, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, '有 耳 却不能 听,口中 也 没 有 气息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, '造他的 要 和他一样,凡 靠 他的也要如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, '以色列 家啊,你们要称颂 耶和华!亚伦 家啊,你们要称颂 耶和华! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, '利未 家啊,你们要称颂 耶和华!你们敬畏 耶和华的,要称颂 耶和华! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, '住 在耶路撒冷 的耶和华 该从锡安 受称颂。你们要赞美 耶和华!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, '你们要称谢 耶和华,因 他本为善; 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, '你们要称谢 万神 之神,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, '你们要称谢 万主 之主,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, '称谢那独 行 大 奇事的,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, '称谢那用智慧 造 天的,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, '称谢那铺 地 在 水以上的,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, '称谢那造成 大 光的,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, '他造 日头 管 白昼,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, '他造 月亮 星宿 管 黑夜,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, '称谢那击杀 埃及人 之长子的,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, '他领以色列人 从他们中间 出来,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, '他施展大能 的手 和伸出来 的膀臂,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, '称谢那分裂 红 海的,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, '他领以色列 从其中 经过,因 他的慈爱 永远长存; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, '却把法老 和他的军兵 推翻 在红 海里,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, '称谢那引导自己的民 行走 旷野的,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, '称谢那击杀 大 君王的,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, '他杀戮 有名的 君王,因 他的慈爱 永远长存; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, '就是杀戮亚摩利 王 西宏,因 他的慈爱 永远长存; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, '又杀巴珊 王 噩,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, '他将他们的地 赐 他的百姓为业,因 他的慈爱 永远长存; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, '就是赐他的仆人 以色列 为业,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, '他顾念 我们 在卑微的地步,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, '他救拔我们 脱离敌人,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, '他赐 粮食 给凡 有血气的,因 他的慈爱 永远长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, '你们要称谢 天上的 神,因 他的慈爱 永远长存。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, '我们曾在 巴比伦 的河 边 坐下,一追想 锡安 就 哭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, '我们把琴 挂 在 那里 的柳树上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, '因为 在那里,掳掠我们的 要我们 唱歌,抢夺我们的 要我们作乐,说:给我们 唱 一首锡安 歌吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, '我们怎能 在 外邦 唱 耶和华 的歌呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, '耶路撒冷啊,我若 忘记你,情愿 我的右手 忘记技巧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, '我若 不 记念你,若 不 看 耶路撒冷 过于  我所最 喜乐的,情愿 我的舌头 贴 于 上膛! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, ' 耶路撒冷 遭难的日子,以东 人 说:拆毁!拆毁!直拆到 根基!耶和华啊,求你记念这仇! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, '将要被灭 的巴比伦城啊(城:原文是女子),报复 你像 你待 我们的,那人便为有福! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, '拿 你的婴孩 摔 在 磐石上的,那人便为有福!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, '(大卫的诗。)我要一 心 称谢你,在诸神 面前 歌颂你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, '我要向 你的圣 殿 下拜,为 你的慈爱 和 诚实 称赞 你的名;因 你使你的话 显为大,过于 你所应许的(或译:超乎 你的名声)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, '我呼求 的日子,你就应允我,鼓励我,使我心里 有能力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, '耶和华啊,地上 的君王 都 要称谢你,因 他们听见了 你口中 的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, '他们要歌颂 耶和华 的作为,因 耶和华 大 有荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, '耶和华 虽 高,仍看顾 低微的人;他却从远处 看出 骄傲的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, '我虽 行 在患难 中,你必将我救活;我的仇敌 发怒,你必伸 手抵挡他们;你的右手 也必救我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, '耶和华 必成全 关乎我的事;耶和华啊,你的慈爱 永远长存!求你不要 离弃 你手 所造的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, '(大卫的 诗,交与伶长。)耶和华啊,你已经鉴察我,认识我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, '我坐下,我起来,你 都晓得;你从远处 知道 我的意念。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, '我行路,我躺卧,你都细察;你也深知 我一切 所行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, ' 耶和华啊, 我舌头上 的话,你没有一句 不知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, '你在我前 后 环绕我,按 手 在我身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, '这样的知识 奇妙,是我不能测的,至高,是我不 能及的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, '我往哪里 去 躲避你的灵?我往哪里 逃、躲避你的面? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, '我若 升 到天上,你 在那里;我若在阴间 下榻,你也在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, '我若展开  清晨 的翅膀,飞到海 极 居住, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, '就是 在那里,你的手 必引导我;你的右手 也必扶持我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, '我若说:黑暗 必定 遮蔽我,我周围 的亮光 必成为黑夜; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, '黑暗 也 不能 遮蔽我,使你不见,黑夜 却如白昼 发亮。黑暗 和光明,在你看都是一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, ' 我的肺腑 是你 所造的;我在母 腹中,你已覆 复庇我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, '我要称谢你,因 我受造,奇妙可畏;你的作为 奇妙,这是我心 深 知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, '我在暗中 受造,在地 的深处 被联络;那时,我的形体 并不 向你 隐藏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, '我未成形的体质,你的眼 早已看见了;你所定的日子,我尚未度一日(或译:我被造 的肢体尚未 有其 一),你都 写 在 你的册上了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, '神啊,你的意念 向我 何等 宝贵!其数 何等 众多! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, '我若数点,比海沙 更多;我睡醒的时候,仍 和你同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, '神啊,你必要 杀戮 恶人;所以,你们好流人血 的,离开  我去吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, '因为 他们说 恶言顶撞你;你的仇敌 也妄 称你的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, '耶和华啊,恨恶你的,我岂不 恨恶他们吗?攻击你的,我岂不憎嫌他们吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, '我切切地 恨恶他们,以他们为 仇敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, '神啊,求你鉴察我,知道 我的心思,试炼我,知道 我的意念, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, '看 在我里面 有什么 恶 行没有,引导我 走永生 的道路。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, '(大卫的 诗,交与伶长。)耶和华啊,求你拯救我 脱离凶恶的 人,保护我 脱离强暴 的人! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, '他们 心中 图谋 奸恶,常常 聚集 要争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, '他们使舌头 尖利 如 蛇,嘴 里 有虺蛇 的毒气。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, '耶和华啊,求你拯救我 脱离恶人 的手,保护我 脱离强暴的 人!他们 图谋 推 我跌倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, '骄傲人 为我 暗设 网罗 和绳索;他们在路 旁 铺下 网,设下 圈套。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, '我曾对耶和华 说:你是我的 神。耶和华啊,求你留心听 我恳求 的声音! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, '主─耶和华、我救恩 的力量啊,在争战  的日子,你遮蔽了 我的头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, '耶和华啊,求你不要 遂 恶人 的心愿 ;不要 成就 他们的计谋,恐怕他们自高。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, '至于 那些昂首 围困我的人,愿 他们嘴唇 的奸恶陷害(原文是遮蔽)自己! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, '愿 火炭 落 在他们身上!愿 他们被丢 在火中,抛在深坑里,不能再 起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, '说恶言 的人 在地上 必坚立 不住;祸患 必猎取 强暴 的人,将他打倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, '我知道 耶和华 必 为困苦人 伸冤,必为穷乏人 辨屈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, '义人 必 要称赞 你的名;正直人 必住 在 你面前。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, '(大卫的 诗。)耶和华啊,我曾求告你,求你快快 临到我这里!我求告 你的时候,愿 你留心听 我的声音! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, '愿 我的祷告 如香 陈列 在你面前!愿 我举 手祈求,如献晚 祭! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, '耶和华啊,求你禁止 我的口,把守 我的嘴! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, '求你不叫 我的心 偏向 邪恶,以致我和 作 孽 的人 同行 恶 事;也不叫 我吃 他们的美食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, '任凭义人 击打我,这算为仁慈;任凭他责备我,这算为头上 的膏油;我的头 不要 躲闪。正在 他们行恶的时候,我仍要 祈祷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, '他们的审判官 被扔 在 岩下;众人要听 我的话,因为 这话甘甜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, '我们的骨头 散 在墓 旁,好像 人耕田、刨 地的土块。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, '主─耶和华啊, 我的眼目 仰望你;我投靠 你,求你不要 将我 撇得孤苦! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, '求你保护我 脱离 恶人为我 设 的网罗 和作 孽 之人的圈套! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, '愿 恶人 落 在自己的网里,我却 得以 逃脱。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, '(大卫 在 洞里 作的训诲诗,乃是祈祷。)我发声 哀告 耶和华,发声 恳求 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, '我在他面前 吐露 我的苦情, 陈说 我的患难。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, '我的灵 在我里面 发昏的时候,你 知道 我的道路。在 我行 的路上,敌人为我 暗设 网罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, '求你向我右边 观看, 因为没有人 认识 我;我 无处 避难,也没有人 眷顾 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, '耶和华啊,我曾向你 哀求。我说:你 是我的避难所;在活人 之地,你是我的福分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, '求你侧耳听 我的呼求,因 我落到 极 卑之地;求你救我 脱离逼迫我的人,因为 他们比我 强盛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, '求你领 我 出离被囚之地,我好称赞 你的名。义人 必环绕 我,因为 你是用厚恩 待我。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, '(大卫的 诗。)耶和华啊,求你听 我的祷告,留心听 我的恳求,凭你的信实 和公义 应允我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, '求你不要 审问 仆人;因为 在你面前,凡 活著的人 没有一个 是义的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, '原来 仇敌 逼迫 我,将我 打倒 在地,使我住 在幽暗之处,像死了 许久的人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, '所以,我的灵 在我里面 发昏;我的心 在我里面 凄惨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, '我追想 古时 之日,思想 你的一切 作为,默念 你手 的工作。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, '我向你 举 手;我的心 渴想你,如干旱 之地盼雨一样。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, '耶和华啊,求你速速 应允我!我心神 耗尽!不要 向我 掩 面,免得我像 那些下 坑 的人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, '求你使我清晨 得听 你慈爱之言,因 我倚靠 你;求你使我知道 当行 的路,因 我的心 仰望 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, '耶和华啊,求你救我 脱离我的仇敌!我往你那里 藏身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, '求你指教我 遵行 你的旨意,因 你是我的 神。你的灵 本为善;求你引我到 平坦 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, '耶和华啊,求你为 你的名 将我救活,凭你的公义,将我 从患难中 领出来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, '凭你的慈爱 剪除 我的仇敌,灭绝 一切 苦待 我的人,因 我是 你的仆人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, '(大卫的诗。)耶和华─我的磐石 是应当称颂的!他教导 我的手 争战 ,教导我的指头 打仗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, '他是我慈爱的主,我的山寨,我的高台,我的救主, 我的盾牌, 是我所投靠的;他使我的百姓 服在 我以下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, '耶和华啊,人 算什么,你竟认识他!世人算什么,你竟顾念他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, '人 好像 一口气;他的年日 如同影儿 快快过去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, '耶和华啊,求你使天 下垂,亲自降临,摸 山,山就冒烟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, '求你发出 闪电,使他们四散,射出 你的箭,使他们扰乱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, '求你从上 伸 手 救拔我,救我 出离大 水,救我脱离外邦 人 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, ' 他们的口 说 谎话;他们的右手 起假誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, '神啊,我要向你 唱 新 歌,用十弦 瑟 向你 歌颂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, '你是那 拯救 君王的;你是那救 仆人 大卫 脱离害命 之刀的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, '求你救拔我,救我 脱离外邦 人 的手。 他们的口 说 谎话;他们的右手 起假誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, '我们的 儿子 从幼年 好像树栽子 长大;我们的女儿 如同殿角石,是按建宫 的样式 凿成的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, '我们的仓 盈满,能 出 各样的粮食;我们的羊 在田间 孳生千 万。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, '我们的牛 驮著满驮,没有人 闯进来抢夺,也没有人 出去争战 ;我们的街市上 也没有 哭号的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, '遇见这光景 的 百姓 便为有福!有耶和华为他们的 神,这百姓 便为有福!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, '(大卫的 赞美诗。)我的 神 我的王啊,我要尊崇你!我要永永远远 称颂 你的名! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, '我要天天 称颂你,也要永永远远 赞美 你的名! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, '耶和华 本为大,该受大 赞美;其大 无法 测度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, '这代 要对那代 颂赞 你的作为,也要传扬 你的大能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, '我要默念 你威严 的尊 荣 和你奇妙 的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, '人要传说 你可畏之事 的能力;我也要传扬 你的大德。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, '他们记念 你的大 恩 就要传出来,并要歌唱 你的公义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, '耶和华 有恩惠,有怜悯,不轻易 发怒,大 有慈爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, '耶和华 善待 万民;他的慈悲 覆 复庇 他一切 所造的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, '耶和华啊,你一切 所造的 都要称谢你;你的圣民 也要称颂你, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, '传说 你国 的荣耀,谈论 你的大能, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, '好叫世人 知道 你大能的作为,并你国度 威严 的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, '你的国 是永远 的国!你执掌的权柄 存到万 代! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, '凡 跌倒的,耶和华 将他们扶持;凡 被压下的,将他们扶起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, '万民 都举目 仰望 你;你 随时 给 他们 食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, '你张 手,使有生气的 都随愿  饱足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, '耶和华 在他一切 所行的,无不公义;在他一切 所做的 都有慈爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, '凡 求告耶和华的,就是 诚心 求告他的,耶和华 便与他们相近。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, '敬畏他的,他必成就 他们的心愿 ,也必听 他们的呼求,拯救他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, '耶和华 保护 一切 爱他的人,却要灭绝 一切的 恶人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, '我的口 要说出 赞美 耶和华的话;惟愿 凡 有血气的 都永永远远 称颂 他的圣 名。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, '你们要赞美 耶和华!我的心哪,你要赞美 耶和华! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, '我一生 要赞美 耶和华!我还活的时候 要歌颂我的 神! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, '你们不要 倚靠 君王,不要倚靠世人;他 一点不能 帮助。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, '他的气 一断,就归回 尘土;他所打算的,当 日 就消灭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, '以雅各的 神 为帮助、仰望 耶和华─他 神的,这人便为有福! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, '耶和华造 天、地、 海,和 其 中的 万物;他守 诚实,直到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, '他为受屈的 伸 冤,赐 食物 与饥饿的。耶和华 释放 被囚的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, '耶和华 开 了 瞎子的眼睛;耶和华 扶起 被压下的人。耶和华 喜爱 义人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, '耶和华 保护 寄居的,扶持 孤儿 和寡妇,却使恶人 的道路 弯曲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, '耶和华 要作王,直到永远!锡安哪,你的 神要作王,直到万代!你们要赞美 耶和华!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, '你们要赞美 耶和华!因歌颂我们的 神 为 善 为 美;赞美的话 是合宜的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, '耶和华 建造 耶路撒冷,聚集 以色列 中被赶散的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, '他医好 伤 心的人,裹好 他们的伤处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, '他数点 星宿 的数目,一一 称 他的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, '我们的主 为大,最 有能力;他的智慧 无法 测度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, '耶和华 扶持 谦卑人,将恶人 倾覆 复 于  地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, '你们要以感谢 向耶和华 歌唱,用琴向我们的 神 歌颂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, '他用云 遮 天,为地 降 雨,使草 生长 在山上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, '他赐 食 给走兽 和啼叫 的 小 乌鸦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, '他不 喜悦 马 的力大,不 喜爱 人 的腿快。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, '耶和华 喜爱 敬畏他和 盼望 他慈爱的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, '耶路撒冷啊,你要颂赞 耶和华!锡安哪,你要赞美你的 神! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, '因为 他坚固了 你的门 闩,赐福 给你中间 的儿女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, '他使 你境内 平安,用上好的 麦子 使你满足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, '他发 命 在地;他的话 颁行 最快。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, '他降 雪 如羊毛,撒 霜 如炉灰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, '他掷下 冰雹 如碎渣;他发出 寒冷,谁能 当得起呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, '他一出 令,这些就都消化;他使风 刮起,水 便流动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, '他将他的道 指示 雅各,将他的律例 典章 指示以色列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, '别 国 他都没有 这样 待过;至于 他的典章,他们向来没有 知道。你们要赞美 耶和华!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, '你们要赞美 耶和华!从 天上 赞美 耶和华,在高处 赞美他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, '他的众 使者 都要赞美他!他的诸 军 都要赞美他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, '日头 月亮,你们要赞美他!放光 的星宿,你们都 要赞美他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, '天 上的天 和天 上 的 水,你们都要赞美他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, '愿 这些都赞美 耶和华 的名!因 他 一吩咐 便都造成。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, '他将这些立定,直到永永 远远;他定了 命,不能废去(或译:越过)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, '所有在地上的,大鱼 和一切 深洋, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, '火 与冰雹,雪 和雾气,成就 他命 的狂 风, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, '大山和 小山,结果 的树木 和一切 香柏树, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, '野兽 和一切 牲畜,昆虫 和飞 鸟, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, '世上 的君王 和万 民,首领 和世上 一切 审判官, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, '少年人 和 处女,老年人 和 孩童,都当赞美 耶和华! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, '愿 这些都赞美 耶和华 的名!因为 独有 他的名 被尊崇;他的荣耀 在 天 地之上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, '他将他百姓 的角 高举,因此他(或译:他使)一切 圣民 以色列 人,就是与他相近 的百姓,都赞美他!你们要赞美 耶和华!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, '你们要赞美 耶和华!向耶和华 唱 新 歌,在圣民 的会中 赞美他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, '愿 以色列 因造他的主 欢喜!愿 锡安 的民 因他们的王 快乐! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, '愿 他们跳舞 赞美 他的名,击鼓 弹琴 歌颂 他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, '因为 耶和华 喜爱 他的百姓;他要用救恩 当作谦卑人 的妆饰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, '愿 圣民 因所得的荣耀 高兴!愿 他们在 床 上欢呼! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, '愿 他们口中称赞 神 为高,手里 有两刃 的刀, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, '为要 报复 列邦,刑罚 万民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, '要用链子 捆 他们的君王,用铁 镣 锁他们的大臣; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, '要在他们身上 施行 所记录的 审判。 他的圣民 都有这 荣耀。你们要赞美 耶和华!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, '你们要赞美 耶和华!在 神 的圣所 赞美他!在他显能力 的穹苍 赞美他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, '要因他大能的作为 赞美他,按著他极美 的大德 赞美他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, '要用角 声 赞美他,鼓瑟 弹琴 赞美他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, '击鼓 跳舞 赞美他!用丝弦的乐器 和箫 的声音赞美他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, '用大响 的钹 赞美他!用高声 的钹 赞美他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, '凡 有气息的 都要赞美 耶和华!你们要赞美 耶和华!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, '以色列 王 大卫 儿子 所罗门 的箴言: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, '要使人晓得 智慧 和训诲,分辨 通达 的言语, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, '使人处事领受 智慧、仁义、公平、正直 的训诲, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, '使 愚人 灵明,使少年人 有知识 和谋略, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, '使智慧人 听见,增长 学问,使聪明人 得著 智谋, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, '使人明白 箴言 和譬喻,懂得智慧人 的言词 和谜语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, '敬畏 耶和华 是知识 的开 端;愚妄人 藐视 智慧 和训诲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, '我儿,要听 你父亲 的训诲,不可 离弃 你母亲 的法则(或译:指教); ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, '因为 这要作 你头上 的华 冠,你项上 的金链。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, '我儿,恶人 若 引诱你,你不可 随从。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, '他们若 说:你与我们 同去,我们要埋伏 流人之血,要蹲伏 害无罪之人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, '我们好像阴间,把他们活活 吞下;他们如同下 坑的人,被我们囫囵吞了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, '我们必得 各样 宝 物,将所掳来的,装满 房屋; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, '你与我们 大家同 分, 我们共用 一个 囊袋; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, '我儿,不要 与他们 同行 一道,禁止 你脚 走他们的路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, '因为,他们的脚 奔跑 行恶;他们急速 流 人的血, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, '好像 飞鸟,网罗 设 在眼前 仍 不躲避。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, '这些人 埋伏,是为自流己血;蹲伏,是为自害己命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, '凡 贪恋财利的,所行之路 都是如此;这贪恋之心乃夺去 得财者 之命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, '智慧 在街市 上呼喊,在宽阔处 发 声, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, '在热闹 街头 喊叫,在城门 口,在城中 发出 言语, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, '说:你们 愚昧人 喜爱 愚昧,亵慢人 喜欢 亵慢,愚顽人 恨恶 知识,要到 几时呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, '你们当因我的责备 回转; 我要将我的灵 浇灌 你们,将我的话 指示 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, ' 我呼唤,你们不肯听从;我伸 手,无人 理会; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, '反轻弃 我一切的 劝戒,不 肯 受我的责备。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, '你们遭灾难,我 就 发笑;惊恐 临到你们,我必嗤笑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, '惊恐 临到你们,好像狂风;灾难 来到,如同暴风;急难 痛苦 临 到你们身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, '那时,你们必呼求我,我却不 答应,恳切地寻找我,却寻 不见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, ' 因为,你们恨恶 知识,不 喜爱 敬畏 耶和华, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, '不 听 我的劝戒,藐视 我一切的 责备, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, '所以必吃 自结的 果子,充满 自设的计谋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, ' 愚昧人 背道,必杀己身;愚顽人 安逸,必害己命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, '惟有听从 我的,必安然 居住,得享安静,不怕 灾祸。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, '我儿,你若 领受 我的言语,存记 我的命令, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, '侧 耳 听智慧,专心 求聪明, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, ' 呼求 明哲,扬 声 求聪明, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, ' 寻找它,如寻找银子,搜求它,如搜求隐藏的珍宝, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, '你就 明白 敬畏 耶和华,得以 认识 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, '因为,耶和华 赐人 智慧;知识 和聪明 都由他口而出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, '他给正直人 存留 真智慧,给行为 纯正 的人作盾牌, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, '为要保守 公平人 的路,护庇 虔敬人 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, '你也必 明白 仁义、公平、正直、一切的 善 道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, '智慧 必 入 你心;你的灵 要以知识 为美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, '谋略 必护卫 你;聪明 必保守你, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, '要救你 脱离恶 道(或译:恶人的道),脱离说 乖谬话 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, '那等人舍弃 正直 的路,行走 黑暗 的道, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, '欢喜 作 恶,喜爱 恶人 的乖僻, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, '在他们的 道 中弯曲,在他们的路上 偏僻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, '智慧要救你 脱离淫 妇,就是那油嘴 滑舌 的外女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, '她离弃 幼年 的配偶,忘了 神 的盟约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, ' 她的家 陷 入 死地;她的路 偏向 阴间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, '凡 到她那里去的,不得 转回,也得 不著 生命 的路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, '智慧必使 你行 善人 的道,守 义人 的路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, ' 正直人 必在世上 居住;完全人 必在地上 存留。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, '惟有恶人必然 剪除;奸诈的,必然拔出。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, '我儿,不要 忘记 我的法则(或译:指教);你心 要谨守 我的诫命; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, '因为 它必将长久 的日子,生命 的年数 与平安,加 给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, '不可 使慈爱、诚实 离开 你,要系 在 你颈项上,刻 在 你心 版上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, '这样,你必在 神 和世人 眼前 蒙 恩宠,有聪明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, '你要专 心 仰赖 耶和华,不可 倚靠 自己的聪明, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, '在你一切 所行的事上 都要认定他,他 必指引 你的路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, '不要 自以为 有 智慧;要敬畏 耶和华,远离 恶事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, '这便 医治 你的肚脐,滋润 你的百骨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, '你要以财物 和一切 初熟的 土产 尊荣 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, '这样,你的仓房 必充满 有余 馀;你的酒醡 有新酒 盈溢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, '我儿,你不可 轻看 耶和华 的管教(或译:惩治),也不可 厌烦 他的责备; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, '因为 耶和华 所 爱的,他必责备,正如父亲责备 所喜爱的 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, '得 智慧,得 聪明的,这人 便为有福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, '因为 得 智慧胜过 得 银子,其利益 强如精金, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, '比珍珠(或译:红宝石)宝贵;你一切 所喜爱的,都不足 与 比较。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, '她右手 有长 寿,左手 有富 贵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, '她的道 是安乐;她的路 全是 平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, '她 与持守 她的 作生命 树;持定她的,俱各有福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, '耶和华 以智慧 立 地,以聪明 定 天, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, '以知识 使深渊 裂开 ,使天空 滴下 甘露。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, '我儿,要谨守 真智慧 和谋略,不可 使她离开  你的眼目。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, '这样,她必作 你 的生命,颈项 的美饰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, '你就 坦然 行 路,不致 碰 脚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, ' 你躺下,必不 惧怕;你躺卧,睡得 香甜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, '忽然来的 惊恐,不要 害怕; 恶人 遭 毁灭,也不要恐惧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, '因为 耶和华 是 你所倚靠的;他必保守 你的脚 不陷入网罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, '你手 若有 行善 的力量,不可 推辞,就当向那应得的人 施行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, '你那里 若有现成的,不可 对邻舍 说:去吧,明天 再来,我必给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, '你的邻舍 既在你附近 安 居,你不可 设计 害 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, '人 未曾 加 害 与你,不可 无故 与 他 相争。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, '不可 嫉妒 强暴的 人,也不可 选择 他所行的 路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, '因为,乖僻人 为耶和华 所憎恶;正直人 为 他所亲密。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, '耶和华 咒诅 恶人 的家庭,赐福 与义人 的居所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, '他 讥诮 那好讥诮的人,赐 恩 给谦卑的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, '智慧人 必承受 尊荣;愚昧人 高升 也成为羞辱。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, '众子啊,要听 父亲 的教训,留心 得知 聪明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, '因 我所给 你们 的是好 教训;不可 离弃 我的法则(或译:指教)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, ' 我在父亲 面前为 孝子,在母亲 眼中 为独一的 娇儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, '父亲教训我 说:你心 要存记 我的言语,遵守 我的命令,便得存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, '要得 智慧,要得 聪明,不可 忘记,也不可 偏离 我口中 的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, '不可 离弃智慧,智慧就护卫你;要爱她,她就保守你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, '智慧 为首;所以,要得 智慧。在你一切 所得 之内必得 聪明(或译:用你一切所得的去换聪明)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, '高举智慧,她就使你高升; 怀抱智慧,她就使你尊荣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, '她必将华 冠 加 在你头上,把荣 冕 交给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, '我儿,你要听 受 我的言语,就必延 年 益寿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, '我已指教你 走智慧 的道,引导你 行正直 的路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, '你行走,脚步 必不致 狭窄; 你奔跑,也不致 跌倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, '要持定 训诲,不可 放松;必当谨守,因为 它 是你的生命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, '不可 行 恶人 的路;不要 走 坏人 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, '要躲避,不可 经过;要转身 而去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, '这等人若 不 行恶, 不得 睡觉; 不 使人跌倒,睡卧 不安; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, '因为 他们以奸恶 吃 饼,以强暴 喝 酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, '但义人 的路 好像黎明的 光,越照 越明,直到 日 午。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, '恶人 的道 好像幽暗,自己不 知 因什么 跌倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, '我儿,要留心 听我的言词,侧 耳 听我的话语, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, '都不可 离 你的眼目,要存记 在你心 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, '因为 得著它的, 就得了生命,又得了医 全 体的良药。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, '你要保守 你心,胜过保守一切(或译:你要切切保守你心),因为 一生 的果效 是由心发出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, '你要除掉 邪僻的 口,弃绝 乖谬的 嘴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, '你的眼目 要向前正 看;你的眼睛(原文是皮)当向前 直观。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, '要修平 你脚 下的路,坚定 你一切 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, '不可 偏向 左 右;要使你的脚 离开  邪恶。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, '我儿,要留心 我智慧的话语,侧 耳 听我聪明的言词, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, '为要使你谨守 谋略,嘴唇 保存 知识。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, '因为 淫妇 的嘴 滴下 蜂蜜;她的口 比油 更滑, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, '至终 却苦 似茵𫈟,快 如两刃 的刀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, '她的脚 下入 死地;她脚步 踏住 阴间, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, '以致 她找不著生命 平坦 的道。她的路 变迁不定,自己还不 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, '众子啊,现在 要听 从我;不可 离弃 我口中 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, '你所行的道 要离 她 远,不可 就近 她的房 门, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, '恐怕 将你的尊荣 给 别人,将你的岁月 给残忍的人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, '恐怕 外人 满得 你的力量,你劳碌得来的,归入外人 的家; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, '终久,你皮肉 和身体 消毁,你就悲叹, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, '说:我怎么 恨恶 训诲,心中 藐视 责备, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, '也不 听从 我师傅 的话,又不 侧 耳 听那教训我的人? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, '我在圣会 里,几乎 落 在诸般 恶中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, '你要喝 自己池中 的水,饮自己井 里 的活水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, '你的泉源 岂可涨溢 在外?你的河 水 岂可流在街上? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, '惟独 归 你一人,不可 与 外人同用。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, '要使 你的泉源 蒙福;要喜悦 你幼年 所娶的妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, '她如可爱的 麀鹿,可喜的 母鹿;愿 她的胸怀 使你 时 时 知足,她的爱情 使你 常常 恋慕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, '我儿,你为何 恋慕 淫妇?为何抱 外女 的胸怀? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, '因为,人 所行的道 都在耶和华 眼 前;他也修平 人一切的 路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, ' 恶人 必被自己的罪孽 捉住;他必被自己的罪恶 如绳索 缠绕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, '他 因不 受训诲 就必死亡;又因愚昧 过甚,必走差了路。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, '我儿,你若 为朋友 作保,替外人 击 掌, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, '你就被口中 的话语 缠住,被嘴里 的言语 捉住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, '我儿,你既 落 在朋友 手中,就当 这样 行 才可救自己:你要自卑,去 恳求 你的朋友。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, '不要 容 你的眼睛 睡觉;不要容你的眼皮 打盹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, '要救自己,如鹿 脱离猎户的手,如鸟 脱离捕鸟人 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, '懒惰人哪,你去 察看 蚂蚁 的动作 就可得智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, '蚂蚁 没有 元帅,没有官长,没有君王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, '尚且在夏天 预备 食物,在收割时 聚敛 粮食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, '懒惰人哪,你要睡 到 几时呢?你何时 睡 醒呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, '再睡 片时,打盹 片时,抱著 手 躺卧 片时, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, '你的贫穷 就必如强盗 速来,你的缺乏 仿佛拿兵器的 人来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, '无赖的 恶 徒,行动 就用乖僻的 口, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, '用眼 传神,用脚 示意,用指 点划 㓰, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, '心中 乖僻,常 设 恶谋,布散 纷争。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, '所以,灾难 必忽然 临到他身;他必顷刻 败坏,无法 可治。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, '耶和华 所恨恶的有 六样,连他心 所憎恶的 共有七样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, '就是高傲的 眼,撒谎的 舌,流 无辜人 血 的手, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, '图谋 恶 计 的心,飞 跑 行恶 的脚, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, '吐 谎言 的假 见证,并弟兄 中 布散 纷争的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, '我儿,要谨守 你父亲的 诫命;不可 离弃 你母亲 的法则(或译:指教), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, '要常 系 在 你心上,挂 在 你项上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, '你行走,它必引导 你;你躺卧,它必保守 你;你睡醒,它 必与你谈论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, '因为 诫命 是灯,法则(或译:指教)是光,训诲 的责备 是生命 的道, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, '能保你 远离恶 妇,远离外女 谄媚 的舌头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, '你心中 不要 恋慕 她的美色,也不要 被她眼皮 勾引。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, '因为,妓 女 能使人只剩 一块 饼;淫妇 猎取 人宝贵的 生命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, '人 若怀里 搋 火,衣服 岂能不 烧呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, '人 若 在 火炭 上走,脚 岂能不 烫呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, '亲近 邻舍 之妻的,也是如此;凡 挨近 她的,不 免受罚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, ' 贼 因 饥饿 偷窃 充饥,人不 藐视他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, '若被找著,他必赔还 七倍,必将 家中 所有的 尽都 偿还。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, '与妇人 行淫的,便是无 知;行这事的, 必丧掉 生命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, '他必受 伤损,必被 凌辱;他的羞耻 不得 涂抹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, '因为 人 的嫉恨 成了烈怒,报仇 的时候 决不 留情。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, '什么 赎价,他都不 顾;你虽 送许多 礼物,他也不肯 干休。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, '我儿,你要遵守 我的言语,将我的命令 存记 在心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, '遵守 我的命令 就得存活;保守我的法则(或译:指教),好像保守眼中 的瞳人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, '系 在 你指头上,刻 在 你心 版上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, '对智慧 说:你是 我的姊妹,称呼 聪明 为你的亲人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, '她就保你 远离淫 妇,远离说谄媚 话 的外女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, ' 我曾在我房屋 的窗户内,从我窗棂 之间 往外观看: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, '见 愚蒙人内,少年人中,分明 有一个无 知 的少年人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, '从街上 经过,走近 淫妇的巷口,直往 通她家 的路 去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, '在黄昏,或晚上,或半 夜,或黑暗之中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, '看哪,有一个妇人 来迎接他,是妓女 的打扮,有诡诈 的心思。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, '这妇人 喧嚷,不守约束,在家里 停 不住 脚, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, '有时 在街市上,有时 在宽阔处,或在 各 巷口 蹲伏, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, '拉住 那少年人,与他 亲嘴,脸 无羞耻 对他 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, '平安 祭 在我这里,今日 才还了 我所许的愿 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, '因此,我出来 迎接你,恳切求见 你的面,恰巧遇见了你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, '我已经用绣花毯子 和埃及 线 缐织的 花纹布 铺了 我的床。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, '我又用没药、沉香、桂皮 薰了 我的榻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, '你来,我们可以饱享 爱情,直到 早晨;我们可以彼此亲爱 欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, '因为 我丈夫 不 在家,出门行 远 路; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, '他手 拿 银 囊,必到月望 才回 家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, '淫妇用许多 巧言 诱他随从,用谄媚的 嘴 逼他同行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, '少年人立刻 跟 随她,好像牛 往 宰杀之地;又像愚昧人 带锁链 去 受刑罚, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, '直等 箭 穿 他的肝;如同雀鸟 急 入 网罗,却不 知 是 自丧己命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, '众子啊,现在 要听 从我,留心听 我口中 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, '你的心 不可 偏 向 淫妇的道,不要 入她的迷 途。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, '因为,被她伤害 仆倒的 不少;被她杀戮的而且 甚多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, '她的家 是在阴间 之路,下 到 死亡 之宫。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, '智慧 岂不 呼叫?聪明 岂不发 声? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, '她在 道旁 高处 的顶上,在十字 路口 站立, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, '在城门 旁,在城 门口,在城门 洞,大声说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, '众人哪,我呼叫 你们,我向 世人 发声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, '说:愚蒙人哪,你们要会悟 灵明;愚昧人哪,你们当心里 明白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, '你们当听,因 我要说 极美的话;我张 嘴 要论正直的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, '我的口 要 发出 真理;我的嘴 憎恶 邪恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, '我口中 的言语 都是 公义,并无 弯曲 乖僻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, '有聪明的,以为 明显,得 知识的,以为正直。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, '你们当受 我的教训,不受 白银;宁得 知识,胜过黄金。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, '因为 智慧比珍珠(或译:红宝石)更美;一切 可喜爱的 都不足 与 比较。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, '我─智慧 以灵明 为居所,又寻得 知识 和谋略。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, '敬畏 耶和华 在乎恨恶 邪恶;那骄傲、狂妄,并恶 道,以及乖谬的 口,都为我所恨恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, '我有 谋略 和真知识;我 乃聪明,我有 能力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, '帝王 藉 借我 坐国位;君王 藉 借我定 公平。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, '王子 和首领,世上 一切的 审判官,都是藉 借我 掌权。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, '爱我的,我 也爱他;恳切寻求我的,必寻得见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, '丰富 尊荣 在我;恒久的 财 并公义也在我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, '我的果实 胜 过黄金,强如精金;我的出产 超乎高 银。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, '我在公义 的道上 走,在公平 的路 中行, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, '使爱我的,承受 货财,并充满 他们的府库。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, '在耶和华 造化 的起头,在太初 创造万物 之先,就有了我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, '从亘古,从太初,未有世界 以前,我已被立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, '没有 深渊,没有 大 水 的泉源,我已生出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, '大山 未曾 奠定,小山 未有之先,我已生出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, '耶和华还 没有 创造 大地 和田野,并世上 的土 质,我已生出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, '他立 高天,我 在那里;他在 渊 面的周围,划 㓰出 圆圈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, '上 使穹苍 坚硬,下使渊 源 稳固, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, '为沧海 定出 界限,使水 不 越过 他的命令,立定 大地 的根基。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, '那时,我在他那里 为 工师,日 日 为 他所喜爱,常常 在他面前 踊跃, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, '踊跃 在他为人预备可住 之地,也喜悦住在 世人之间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, '众子啊,现在 要听 从我,因为谨守 我道的,便为有福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, '要听 教训 就得智慧,不可 弃绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, '听 从我、日 日 在 我门口 仰望、在我门 框 旁边等候的,那人 便为有福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, '因为 寻得我的,就寻得 生命,也必蒙 耶和华的 恩惠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, '得罪我的,却害了 自己的性命;恨恶我的,都 喜爱 死亡。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, '智慧 建造 房屋,凿成 七根 柱子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, '宰杀 牲畜,调和 旨酒, 设摆 筵席; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, '打发 使女 出去,自己在 城中 至高处 呼叫, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, '说:谁 是愚蒙人,可以转到 这里来!又对 那无 知 的人说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, '你们来,吃 我的饼,喝 我调和 的酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, '你们愚蒙人,要舍弃 愚蒙,就得存活,并要走 光明的 道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, '指斥 亵慢人的,必受 辱骂;责备 恶人的,必被玷污。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, '不要 责备 亵慢人,恐怕 他恨你;要责备 智慧人,他必爱你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, '教导 智慧人,他就越发 有智慧;指示 义人,他就增长 学问。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, '敬畏 耶和华 是智慧 的开 端;认识 至圣者 便是聪明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, ' 你藉 借著我,日子 必增多,年 岁 也必加添。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, '你若 有智慧,是与自己 有益;你若亵慢,就必独自 担当。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, '愚昧的 妇人 喧嚷;她是愚蒙,一 无 所知。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, '她坐 在自己的家 门口,坐在 城中 高处 的座位上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, '呼叫 过 路的,就是直行 其道的人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, '说:谁 是愚蒙人,可以转到 这里来!又对 那无 知 的人说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, '偷来的 水 是甜的,暗吃的 饼 是好的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, '人却不 知 有阴魂 在她那里;她的客 在阴间 的深处。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, '所罗门 的箴言:智慧 之子 使父亲 欢乐;愚昧 之子 叫母亲 担忧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, '不义 之财 毫无 益处;惟有公义 能救人 脱离死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, '耶和华 不 使义 人 受饥饿;恶人 所欲的,他必推开 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, '手 懒的,要受 贫穷;手 勤的,却要富足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, '夏天 聚敛的,是智慧 之子;收割时 沉睡的,是贻羞 之子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, '福祉 临到义人 的头;强暴 蒙蔽 恶人 的口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, '义人 的纪念 被称赞;恶人 的名字 必朽烂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, '心中 智慧的,必受 命令;口里 愚妄的,必致倾倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, '行正直 路的,步步 安稳;走弯曲道 的,必致败露。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, '以眼 传神的,使人 忧患;口里 愚妄的,必致倾倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, '义人 的口 是生命 的泉源;强暴 蒙蔽 恶人 的口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, '恨 能挑启 争端;爱 能遮掩 一切 过错。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, '明哲人 嘴里 有 智慧;无 知 人背上受 刑杖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, '智慧人 积存 知识;愚妄人 的口 速致 败坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, '富户 的财物 是他的坚 城;穷人 的贫乏 是他的败坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, '义人 的勤劳 致生;恶人 的进项致死(死:原文是罪)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, '谨守 训诲的,乃在生命 的道上;违弃 责备的,便失迷了路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, '隐藏 怨恨的,有说谎的 嘴;口出 谗谤的,是 愚妄的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, '多 言多语 难 免 有过;禁止 嘴唇 是有智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, '义人 的舌 乃似高 银;恶人 的心 所值无几。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, '义人 的口 教养 多人;愚昧人 因无 知 而死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, '耶和华 所赐的福 使人富足,并不 加上 忧虑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, '愚妄人 以行 恶 为戏耍;明哲 人 却以智慧为乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, '恶人 所怕的,必 临到他;义人 所愿 的,必蒙应允。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, '暴风 一过,恶人 归于 无有;义人 的根基 却是永久。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, ' 懒惰人 叫差他的人 如醋 倒牙,如烟 薰目。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, '敬畏 耶和华 使人日子 加多;但恶人 的年岁 必被减少。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, '义人 的盼望 必得喜乐;恶人 的指望 必致灭没。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, '耶和华 的道 是正直人 的保障,却成了作 孽 人的败坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, '义人 永 不 挪移;恶人 不得 住在 地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, '义人 的口 滋生 智慧;乖谬 的舌 必被割断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, '义人 的嘴 能令人 喜悦;恶人 的口 说乖谬的话。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, '诡诈 的天平 为耶和华 所憎恶;公平 的法码 为他所喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, '骄傲 来,羞耻 也来;谦逊人却有 智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, '正直人 的纯正 必引导自己;奸诈人 的乖僻 必毁灭自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, '发怒 的日子 资财 无 益;惟有公义 能救人 脱离死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, '完全人 的义 必指引 他的路;但恶人 必因自己的恶 跌倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, '正直人 的义 必拯救自己;奸诈人 必陷 在自己的罪孽中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, '恶 人 一死,他的指望 必灭绝;罪人 的盼望 也必灭没。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, '义人 得脱离 患难,有恶人 来 代替他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, '不虔敬的人 用口 败坏 邻舍;义人 却因知识 得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, '义人 享福,合城 喜乐;恶人 灭亡,人都欢呼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, '城 因正直人 祝福 便高举,却因邪恶人 的口 就倾覆 复。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, '藐视 邻舍的,毫无 智慧;明哲 人 却静默不言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, '往来 传舌的,泄漏 密事;心中 诚实的,遮隐 事情。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, '无 智谋,民 就败落;谋士 多,人便安居。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, '为 外人 作保的,必受 亏损;恨恶 击掌的,却得安稳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, '恩德 的妇女 得 尊荣;强暴的男子 得 资财。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, '仁慈 的人 善待 自己;残忍的人 扰害 己身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, '恶人 经营,得虚浮 的工价;撒义 种的,得实在 的果效。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, '恒心为义的,必得生命;追求 邪恶的,必致死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, '心中 乖僻的,为耶和华 所憎恶;行事 完全的,为他所喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, '恶人 虽然连手,必不免 受罚;义人 的后裔 必得拯救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, '妇女 美貌 而无 见识,如同金 环 带在猪 鼻上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, '义人 的心愿  尽得 好处;恶人 的指望 致干忿怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, '有 施散的,却更 增添;有吝惜 过度的,反致 穷乏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, '好施舍的,必得丰裕;滋润人的,必得 滋润。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, '屯粮 不卖的,民 必咒诅他;情愿 出卖的,人必为他 祝福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, '恳切求 善的,就求得 恩惠;惟独求 恶的,恶必临到他身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, '倚仗 自己财物的, 必跌倒;义人 必发旺,如青叶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, '扰害 己家的,必承受 清风;愚昧人 必作慧 心 人的仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, '义人 所结的果子 就是生命 树;有智慧的,必能得 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, '看哪,义人 在世 尚且受报,何况 恶人 和罪人呢?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, '喜爱 管教的,就是喜爱 知识;恨恶 责备的,却是畜类。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, '善人 必蒙 耶和华 的恩惠;设诡计 的人,耶和华必定他的罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, '人 靠恶行 不能 坚立;义人 的根 必不 动摇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, '才德的 妇人 是丈夫 的冠冕;贻羞的 妇人如同朽烂 在她丈夫的骨中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, '义人 的思念 是公平;恶人 的计谋 是诡诈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, '恶人 的言论 是埋伏 流人的血;正直人 的口 必拯救人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, '恶人 倾覆 复,归于 无有;义人 的家 必站得住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, '人 必按 自己的智慧 被称赞;心中 乖谬的,必 被藐视。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, '被人轻贱,却有 仆人,强 如自尊,缺少 食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, '义人 顾惜 他牲畜 的命;恶人 的怜悯 也是残忍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, '耕种 自己田地的,必得饱 食;追随 虚浮的,却是无 知。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, '恶人 想 得坏人 的网罗;义人 的根 得以结实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, '恶人 嘴中 的过错 是自己的网罗;但义人 必脱离 患难。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, '人 因口 所结的果子,必饱得 美福;人 手 所做的,必为自己 的报应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, '愚妄人 所行的,在自己眼中 看为正直;惟智慧人 肯听 人的劝教。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, '愚妄人 的恼怒 立时 显露;通达人 能忍辱藏 羞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, '说出 真话的,显明 公义;作假 见证的,显出诡诈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, ' 说话浮躁的,如刀 刺人;智慧人 的舌头 却为医人的良药。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, '口 吐真言,永远 坚立;舌 说谎话,只存 片时。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, '图谋 恶事的,心存 诡诈;劝人 和睦的,便得喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, '义人 不 遭 灾害;恶人 满受 祸患。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, '说谎言的 嘴 为耶和华 所憎恶;行事 诚实的,为他所喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, '通达 人 隐藏 知识;愚昧人 的心 彰显 愚昧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, '殷勤人 的手 必掌权;懒惰 的人必 服苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, '人 心 忧虑,屈而不伸;一句良 言,使心欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, '义人 引导 他的邻舍;恶人 的道 叫人失迷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, '懒惰的人 不 烤 打猎所得的;殷勤 的人 却得宝贵 的财物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, '在公义 的道 上有生命;其路 之中 并无 死亡。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, '智慧 子 听父亲 的教训;亵慢人 不 听 责备。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, '人 因口 所结的果子,必享 美福;奸诈 人 必遭强暴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, '谨守 口的,得保 生命;大张 嘴的,必致败亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, '懒惰 人 羡慕,却无所得;殷勤 人 必得丰裕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, '义人 恨恶 谎 言;恶人 有臭名,且致惭愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, '行为 正直的,有公义 保守;犯罪的,被邪恶 倾覆 复。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, ' 假作富足的,却一无 所有;装作穷乏的,却广 有财物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, '人 的资财 是他生命 的赎价;穷乏人 却听 不 见威吓的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, '义人 的光明亮(原文是欢喜);恶人 的灯 要熄灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, '骄傲 只 启 争竞;听 劝言的,却有智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, '不劳而得 之财 必然消耗;勤劳 积蓄的,必见加增。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, '所盼望 的迟延未得,令人心 忧;所愿 意 的临到,却是生命 树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, '藐视 训言的,自取 灭亡;敬畏 诫命的,必 得善报。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, '智慧人 的法则(或译:指教)是生命 的泉源,可以使人离开  死亡 的网罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, '美好的 聪明 使 人蒙恩;奸诈人 的道路 崎岖难行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, '凡 通达人 都凭知识 行事;愚昧人 张扬 自己的愚昧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, '奸恶 的使者 必陷 在祸患里;忠信 的使臣 乃医人的良药。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, '弃绝 管教的,必致贫 受辱;领受 责备的,必得尊荣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, '所欲 的成就,心 觉甘甜;远离 恶事,为愚昧人 所憎恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, '与 智慧人 同行的,必得智慧;和愚昧人 作伴的,必受亏损。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, '祸患 追赶 罪人; 义人 必得善 报。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, '善 人给子 孙 遗留产业;罪人 为义人 积存 资财。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, '穷人 耕种 多 得粮食,但因不 义,有 消灭的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, '不忍 用杖 打儿子的,是恨恶他;疼爱儿子的,随时 管教。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, '义人 吃 得饱足;恶人 肚腹 缺粮。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, '智慧 妇人 建立 家室;愚妄 妇人亲手 拆毁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, '行动 正直的,敬畏 耶和华;行事 乖僻的,却藐视他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, '愚妄人 口 中骄傲,如杖责打己身;智慧人 的嘴 必保守自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, '家里无 牛,槽头 干净;土产 加多 乃凭牛 力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, '诚实 见证人 不 说谎话;假 见证人 吐出 谎言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, '亵慢人 寻 智慧,却寻不著;聪明人 易 得知识。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, '到 愚昧 人 面前,不 见 他嘴 中有知识。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, '通达人 的智慧 在乎明白 己道;愚昧人 的愚妄 乃是诡诈(或译:自欺)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, '愚妄人 犯罪,以为戏耍(或译:赎愆祭愚弄愚妄人);正直人 互相 喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, '心 中的苦楚,自己 知道;心里的喜乐,外人 无 干。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, '奸恶人 的房屋 必倾倒;正直人 的帐棚 必兴盛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, '有 一条路,人 以为 正,至终 成为死亡 之路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, '人在喜笑中,心 也 忧愁;快乐 至极 就生愁苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, '心 中背道的,必满得自己的结果;善 人 必从自己的行为得以知足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, '愚蒙人 是话 都 信;通达人 步步 谨慎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, '智慧人 惧怕,就远离 恶事;愚妄人 却狂傲 自恃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, '轻易 发怒的,行事 愚妄;设立诡计 的,被人恨恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, '愚蒙人 得愚昧 为产业;通达人 得知识 为冠冕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, '坏人 俯伏 在善人 面前;恶人 俯伏在 义人 门口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, '贫穷人 连 邻舍 也恨他;富足人 朋友 最多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, '藐视 邻舍的,这人有罪;怜悯 贫穷的,这人有福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, '谋 恶的,岂非 走入迷途吗?谋 善的,必得慈爱 和诚实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, '诸般 勤劳 都有 益处;嘴 上多言 乃致 穷乏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, '智慧人 的财 为自己的冠冕;愚妄人 的愚昧 终是愚昧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, '作真 见证的,救 人性命;吐出 谎言的,施行诡诈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, '敬畏 耶和华的,大 有倚靠;他的儿女 也有 避难所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, '敬畏 耶和华 就是生命 的泉源,可以使人离开  死亡 的网罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, '帝王 荣耀 在乎民 多;君王 衰败 在乎民 少。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, '不轻易 发怒的,大 有聪明;性情 暴躁的,大显 愚妄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, '心 中安静 是肉体 的生命;嫉妒 是骨 中的朽烂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, '欺压 贫寒的,是辱没 造他的主;怜悯 穷乏的,乃是尊敬主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, '恶人 在所行的恶 上必被推倒;义人 临死,有所投靠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, '智慧 存在 聪明人 心中;愚昧人 心里所存的,显而易见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, '公义 使邦国 高举;罪恶 是人民 的羞辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, '智慧 的臣子 蒙王 恩惠;贻羞 的仆人遭 其震怒。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, '回答 柔和,使怒 消退;言语 暴戾,触动 怒气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, '智慧人 的舌 善发 知识;愚昧人 的口 吐出 愚昧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, '耶和华 的眼目 无 处不在;恶人 善人,他都鉴察。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, '温良 的舌 是生命 树;乖谬 的嘴 使人心 碎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, '愚妄人 藐视 父亲 的管教;领受 责备的,得著见识。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, '义人 家 中多有 财宝;恶人 得利 反受扰害。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, '智慧人 的嘴 播扬 知识;愚昧人 的心 并不 如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, '恶人 献祭,为耶和华 所憎恶;正直人 祈祷,为他所喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, '恶人 的道路,为耶和华 所憎恶;追求 公义的,为他所喜爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, '舍弃 正路的,必受严 刑;恨恶 责备的,必致死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, '阴间 和灭亡 尚在耶和华 眼前,何况 世 人 的心呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, '亵慢人 不 爱 受责备;他也不 就近 智慧人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, '心 中喜乐,面 带笑容;心 里忧愁,灵 被损伤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, '聪明人 心 求 知识;愚昧人 口 吃 愚昧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, '困苦人 的日子 都 是愁苦;心中 欢畅的,常 享丰筵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, '少有财宝,敬畏 耶和华,强 如多 有财宝,烦乱不安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, '吃 素菜,彼此相爱,强 如吃肥 牛,彼此相恨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, '暴怒 的人 挑启 争端;忍 怒 的人止息 纷争。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, '懒惰人 的道 像荆棘 的篱笆;正直人 的路 是平坦的大道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, '智慧 子 使父亲 喜乐;愚昧 人 藐视 母亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, '无 知 的人以愚妄 为乐;聪明 的人 按正直 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, '不 先商议,所谋 无效;谋士 众多,所谋乃成。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, '口 善应对,自觉 喜乐;话 合其时,何等 美好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, '智慧人 从生命 的道 上升,使 他远离 在下 的阴间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, '耶和华 必拆毁 骄傲人 的家,却要立定 寡妇 的地界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, '恶 谋 为耶和华 所憎恶;良 言 乃为纯净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, '贪恋 财利的,扰害 己家;恨恶 贿赂的,必得存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, '义人 的心,思量 如何回答;恶人 的口 吐出 恶言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, '耶和华 远离 恶人,却听 义人 的祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, '眼 有光,使心 喜乐;好 信息,使骨 滋润。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, '听从 生命 责备 的,必常在 智慧人 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, '弃绝 管教的,轻看 自己的生命;听从 责备的,却得 智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, '敬畏 耶和华 是智慧 的训诲;尊荣 以前,必有谦卑。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, '心中 的谋算 在乎人;舌头 的应对 由于 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, '人 一切 所行的,在自己眼中 看为清洁;惟有耶和华 衡量 人心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, '你所做的,要交托 讬 耶和华,你所谋的,就必成立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, '耶和华 所造的,各 适其用;就是 恶人 也为祸患 的日子所造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, '凡 心里 骄傲的,为耶和华 所憎恶;虽然连手,他必不免 受罚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, '因怜悯 诚实,罪孽 得赎;敬畏 耶和华的,远离 恶事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, '人 所行的,若蒙耶和华 喜悦,耶和华也 使他的仇敌 与他 和好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, '多 有财利,行事不 义,不 如少有财利,行事公义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, '人 心 筹算 自己的道路;惟耶和华 指引 他的脚步。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, '王 的嘴 中有 神语,审判之时,他的口 必不 差错。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, '公道 的天平 和秤 都属耶和华;囊 中一切 法码 都为他所定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, '作 恶,为王 所憎恶,因 国位 是靠公义 坚立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, '公义 的嘴 为王 所喜悦;说 正直话的,为王所喜爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, '王 的震怒 如杀人 的使者;但智慧 人 能止息王怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, '王 的脸 光 使人有生命;王的恩典 好像春云 时雨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, '得 智慧 胜 似得金子;选 聪明 强如选 银子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, '正直人 的道 是远离 恶事;谨守 己路的,是保全 性命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, '骄傲 在败坏 以先;狂 心 在跌倒 之前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, '心 里谦卑 与 穷乏人来往,强如 将掳物 与 骄傲 人同分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, '谨守 训言的,必得 好处;倚靠 耶和华的,便为有福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, '心中 有智慧,必称为 通达人;嘴 中的甜言,加增 人的学问。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, '人有 智慧 就有生命 的泉源;愚昧人 必被愚昧 惩治。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, '智慧人 的心 教训 他的口,又使 他的嘴 增长 学问。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, '良 言 如同蜂房,使心 觉甘甜,使骨 得医治。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, '有 一条路,人 以为 正,至终 成为死亡 之路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, '劳力 人 的胃口使他 劳力,因为 他的口 腹催逼 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, '匪 徒 图谋 奸恶,嘴 上 仿佛有烧焦 的火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, '乖僻 人 播散 纷争;传舌的,离间 密友。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, '强暴 人 诱惑 邻舍,领他走 不 善 之道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, '眼目 紧合的,图谋 乖僻;嘴唇 紧闭的,成就 邪恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, '白发 是荣耀 的冠冕,在公义 的道 上必能得著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, '不轻易 发怒的,胜过 勇士;治服 己心的,强如取 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, ' 签 放 在怀里, 定事 由耶和华。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, '设筵 满 屋,大家相争,不如 有块干 饼,大家相安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, '仆人 办事聪明,必管辖 贻羞 之子,又在众子 中 同分 产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, '鼎 为炼银,炉 为炼金;惟有耶和华 熬炼 人心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, '行恶的,留心 听 奸诈 之言;说谎的,侧耳 听 邪恶 之语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, '戏笑 穷人的,是辱没 造他的主;幸 灾乐祸的,必不免 受罚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, '子 孙 为老人 的冠冕;父亲 是儿女 的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, '愚顽人 说美 言 本不 相宜,何况 君王 说谎 话呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, '贿赂 在餽送的人 眼 中看为宝 玉, 随处 运动 都 得顺利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, '遮掩 人过的,寻求 人爱;屡次 挑错的,离间 密友。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, '一句责备话 深入 聪明人的心,强如责打 愚昧人 一百下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, '恶人 只 寻 背叛,所以必有严厉 的使者 奉差 攻击他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, '宁可遇见丢崽子 的母熊,不可 遇见 正行愚妄 的愚昧 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, '以 恶 报 善的,祸患 必不 离 他的家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, '纷争 的起头 如水 放开 ,所以,在争闹 之先 必当止息 争竞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, '定恶人 为义的,定义人 为恶的, 这都 为耶和华 所憎恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, '愚昧人 既无 聪明,为何 手 拿价银 买  智慧呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, '朋友 乃时常 亲爱,弟兄 为患难 而生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, '在邻舍 面前 击 掌 作 保 乃是无 知 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, '喜爱 争竞的,是喜爱 过犯;高立 家门的,乃自取 败坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, '心 存邪僻的,寻 不著 好处;舌 弄 是非的,陷 在祸患中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, '生 愚昧子的,必自 愁苦;愚顽人 的父 毫无 喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, '喜乐 的心 乃是良 药;忧伤 的灵 使骨 枯干。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, '恶人 暗中 受 贿赂,为要颠倒 判断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, ' 明哲人 眼前 有智慧;愚昧人 眼 望地 极。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, '愚昧 子 使父亲 愁烦,使母亲 忧苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, ' 刑罚 义人 为不 善;责打 君子 为 不义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, '寡少 言语的,有 知识;性情 温良的,有聪明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, '愚昧人 若静默不言 也 可算为 智慧;闭 口 不说也可算为聪明。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, '与众寡合的,独自寻求 心愿 ,并恼恨 一切 真智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, '愚昧人 不 喜爱 明哲,只 喜爱显露 心意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, '恶人 来,藐视 随 来;羞耻到,辱骂 同到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, '人 口 中的言语 如同深 水;智慧 的泉源 好像涌流 的河水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, '瞻徇 恶人 的情面,偏断 义人 的案件,都为不 善。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, '愚昧人 张嘴 启 争端,开 口 招 鞭打。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, '愚昧人 的口 自取 败坏;他的嘴 是他生命 的网罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, '传舌人 的言语 如同美食, 深入 人的心 腹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, ' 做工 懈怠的,与浪费 人 为 弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, '耶和华 的名 是坚固 台;义人 奔入 便得安稳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, '富足人 的财物 是他的坚 城,在他心想,犹如高 墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, '败坏 之先,人 心 骄傲;尊荣 以前,必有谦卑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, '未曾听完 先 回答的,便是 他的 愚昧 和羞辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, '人 有疾病,心 能忍耐;心灵 忧伤,谁 能承当呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, '聪明人 的心 得 知识;智慧人 的耳 求 知识。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, '人 的礼物 为他 开 路,引他到 高位 的人面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, '先 诉情由的,似乎有理;但邻舍 来到,就察出实情。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, '掣签 能止息 争竞,也能解散 强胜的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, '弟兄 结怨,劝他和好,比取坚固 城还难;这样的争竞 如同坚寨 的门闩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, '人 口 中所结的果子,必充满 肚腹;他嘴 所出的,必使他饱足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, '生 死 在舌头 的权下,喜爱它的,必吃 它所结的果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, '得著 贤妻的,是得著 好处,也是蒙了 耶和华 的恩惠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, '贫穷人 说 哀求的话;富足人 用威吓 的话回答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, '滥交朋友 的,自取败坏;但有 一朋友 比弟兄 更亲密。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, '行为 纯正 的贫穷人 胜 过乖谬 愚妄的富足人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, ' 心 无 知识的,乃为不 善;脚步 急快的,难免犯罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, '人 的愚昧 倾败 他的道;他的心 也抱怨 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, '财物 使 朋友 增多;但穷人 朋友 远离。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, '作假 见证的,必不 免受罚;吐出 谎言的,终不能 逃脱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, '好施散的,有多 人求 他的恩情;爱送礼的,人都 为他的 朋友。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, '贫穷人,弟兄 都 恨他;何况 他的朋友,更远离 他!他用言语 追随,他们 却走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, '得著 智慧的,爱惜 生命;保守 聪明的,必得 好处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, '作假 见证的,不 免受罚;吐出 谎言的,也必灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, '愚昧人 宴乐 度日是不 合宜的;何况 仆人 管辖 王子呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, '人 有见识 就不轻易 发怒;宽恕 人的过失 便是自己的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, '王 的忿怒 好像狮子 吼叫;他的恩典 却如草 上 的甘露。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, '愚昧 的儿子 是父亲的 祸患;妻子 的争吵 如雨连连 滴漏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, '房屋 钱财 是祖宗 所遗留的;惟有贤慧 的妻 是耶和华所赐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, '懒惰 使 人沉睡;懈怠 的人 必受饥饿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, '谨守 诫命的,保全 生命;轻忽 己路的,必致死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, '怜悯 贫穷的,就是借给 耶和华;他的善行,耶和华必偿还。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, '趁 有 指望,管教 你的儿子;你的心 不可 任 他死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, '暴 怒 的人 必受 刑罚;你若 救他,必须再救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, '你要听 劝教,受 训诲,使 你终久 有智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, '人 心 多 有计谋;惟有耶和华 的筹算才能 立定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, '施行仁慈的,令人 爱慕;穷人 强 如 说谎言的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, '敬畏 耶和华的,得著生命;他必恒久 知足,不 遭 祸患。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, '懒惰人 放 手 在盘子里,就是 向 口 撤回,他也不肯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, '鞭打 亵慢人,愚蒙人 必长见识;责备 明哲人,他就明白 知识。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, '虐待 父亲、撵出 母亲的,是贻羞 致辱 之子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, '我儿,不可 听了 教训 而又偏离 知识 的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, '匪徒 作见证 戏笑 公平;恶人 的口 吞下 罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, '刑罚 是为亵慢人 预备的;鞭打 是为愚昧人 的背预备的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, '酒 能使人亵慢,浓酒 使人喧嚷;凡 因酒 错误的,就无 智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, '王 的威吓 如同狮子 吼叫;惹动他怒的,是自害 己命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, '远离 纷争 是人的 尊荣;愚妄人 都 爱争闹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, '懒惰人 因冬寒 不肯 耕种,到收割的时候,他必讨 饭而无所得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, '人 心 怀藏谋略,好像深 水,惟明哲 人 才能汲引出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, '人 多 述说 自己 的仁慈,但忠信 人 谁 能遇著呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, '行为 纯正 的义人,他的子孙 是有福的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, '王 坐 在 审判 的位上,以眼目 驱散 诸 恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, '谁 能说,我洁净了 我的心,我脱净了 我的罪? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, '两样的法码,两样的升斗, 都 为耶和华 所憎恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, ' 孩童 的动作 是 清洁,是 正直,都显明 他的本性。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, '能听 的耳,能看 的眼, 都是 耶和华 所造的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, '不要 贪 睡,免致 贫穷;眼 要睁开 ,你就吃 饱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, '买 物的 说:不好,不好;及至买 去,他便 自夸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, '有 金子 和许多珍珠(或译:红宝石),惟有知识 的嘴 乃为贵重 的珍宝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, '谁 为生人 作保,就拿 谁的衣服;谁为 外人 作保,谁就要承当。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, '以虚谎 而得的食物,人 觉甘甜;但后来,他的口 必充满 尘沙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, '计谋 都凭筹算 立定;打 仗 要凭智谋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, '往来 传舌的,泄漏 密事;大张 嘴的,不可 与他结交。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, '咒骂 父 母的,他的灯 必灭,变为漆黑 的黑暗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, '起初 速得 的产业,终久 却不为 福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, '你不要 说,我要以恶报 恶;要等候 耶和华,他必拯救 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, '两样的法码 为耶和华 所憎恶;诡诈 的天平 也为不 善。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, '人 的脚步 为耶和华所定;人 岂能 明白 自己的路呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, '人 冒失说,这是圣物,许愿  之后 才查问,就是自陷网罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, '智慧 的王 簸散 恶人,用碌碡滚 轧 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, '人 的灵 是耶和华 的灯,鉴察 人的心 腹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, '王 因仁慈 和诚实 得以保全 他的国位,也因仁慈 立稳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, '强壮 乃少年人 的荣耀;白发 为老年人 的尊荣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, '鞭 伤 除净 人的罪恶;责打 能入人的心 腹。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, '王 的心 在耶和华 手中,好像陇沟 的水 随 意 流转。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, '人 所 行的,在自己眼 中都看为正;惟有耶和华 衡量 人心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, '行 仁义 公平 比献祭 更蒙耶和华 悦纳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, '恶人发达(发达:原文是灯),眼 高 心 傲,这乃是罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, '殷勤 筹划 㓰的,足致 丰裕; 行事急躁的,都必 缺乏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, '用诡诈 之舌 求 财的,就是自己取 死;所得之财乃是吹来吹去的 浮云。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, '恶人 的强暴 必将自己扫除,因 他们不肯 按公平 行事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, '负罪 之人 的路 甚是弯曲;至于 清洁的人,他所行 的乃是正直。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, '宁可 住 在 房顶 的角上,不在宽阔 的房屋 与争吵的 妇人同住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, '恶人 的心 乐 人受祸;他眼 并不 怜恤 邻舍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, '亵慢的人 受刑罚,愚蒙的人 就得智慧;智慧人 受训诲,便得 知识。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, '义 人思想 恶人 的家,知道恶人 倾倒,必致灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, '塞 耳 不听穷人 哀求的,他 将来呼吁 也 不 蒙应允。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, '暗中 送的礼物 挽回 怒气;怀中 搋的贿赂 止息暴 怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, '秉公行 义 使义人 喜乐,使作 孽 的人败坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, '迷离 通达 道路 的,必住在 阴魂 的会中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, '爱 宴乐的,必致穷乏;好 酒,爱膏油的,必不 富足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, '恶人 作了义人 的赎价;奸诈人 代替 正直人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, '宁可 住 在 旷野,不与争吵 使气 的妇人同住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, '智慧 人家中 积蓄 宝物 膏油;愚昧 人 随得来随吞下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, '追求 公义 仁慈的,就寻得 生命、公义,和尊荣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, '智慧人 爬上 勇士 的城墙,倾覆 复 他所倚靠 的坚垒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, '谨守 口 与舌的,就保守 自己 免受灾难。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, '心骄 气傲 的人名 叫亵慢;他行事 狂妄,都出于 骄傲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, '懒惰人 的心愿  将他杀害,因为 他手 不肯 做工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, '有终 日 贪得 无餍的;义人 施舍 而不 吝惜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, '恶人 的祭物 是可憎的;何况 他存恶意 来献呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, '作假 见证 的必灭亡;惟有听 真情而言 的,其言长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, '恶 人 脸 无羞耻;正直人 行事 坚定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, '没有人 能以智慧、 聪明、 谋略 敌挡 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, '马 是为打仗 之日 预备的;得胜 乃在乎耶和华。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, '美名 胜过 大 财;恩 宠 强如金 银。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, '富户 穷人 在世相遇,都 为耶和华 所造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, '通达 人见 祸 藏躲;愚蒙人 前往 受害。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, '敬畏 耶和华 心存谦卑,就得富有、尊荣、生命 为赏赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, '乖僻人 的路 上有荆棘 和网罗;保守 自己生命的,必要远离。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, '教养 孩童,使他走 当行 的道,就是 到老 他也 不 偏离。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, '富户 管辖 穷人;欠债 的 是债主 的仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, '撒 罪孽的,必收 灾祸;他逞怒 的杖 也必废掉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, '眼目 慈善的,就必 蒙福,因 他将食物 分 给穷人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, '赶出 亵慢人,争端 就消除;纷争 和羞辱 也必止息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, '喜爱 清 心 的人因他嘴 上的恩言,王 必与他为友。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, '耶和华 的眼目 眷顾 聪明人,却倾败 奸诈人 的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, '懒惰人 说:外头 有狮子;我在 街上 就必被杀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, '淫妇 的口 为深 坑;耶和华 所憎恶的,必陷 在其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, '愚蒙 迷住 孩童 的心,用管教 的杖 可以远远赶除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, '欺压 贫穷 为要利 己的,并送 礼与富户的,都必 缺乏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, '你须侧 耳 听受 智慧人 的言语,留心 领会 我的知识。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, '你若 心中 存记,嘴 上 咬定,这便 为美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, '我今日 以此特特 指教你,为要使 你倚靠 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, '谋略 和知识 的美事,我岂没有 写 给你吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, '要使你知道 真 言 的实理,你好将真 言 回复 那打发你来的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, '贫穷人,你不可 因 他 贫穷 就抢夺他的物,也不可 在城门口 欺压 困苦人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, '因 耶和华 必为他辨 屈;抢夺他的,耶和华必夺取 那人的命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, '好生气 的人,不可 与他 结交;暴怒 的人,不可 与他 来往; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, '恐怕 你效法 他的行为,自己 就陷在 网罗里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, '不要 与人击 掌,不要为欠债 的作保。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, '你 若 没有 什么偿还,何必 使人夺去 你睡卧 的床呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, '你先祖 所 立 的地界,你不可 挪移。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, '你看见 办事 殷勤 的人吗?他必站在 君王 面前,必不 站在 下贱人 面前。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, '你若 与 官长 坐 席,要 留意 在你面前 的是谁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, '你 若 是贪食 的,就当拿刀 放 在喉咙上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, '不可 贪恋 他的美食,因为是 哄人的 食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, '不要 劳碌 求富,休 仗自己的聪明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, '你岂要定 睛 在虚无的 钱财上吗?因 钱财 必 长 翅膀,如鹰 向天 飞去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, '不要 吃 恶 眼 人的饭,也不要 贪 他的美味; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, '因为 他心 怎样 思量,他 为人就是怎样。他虽对你 说,请吃,请喝,他的心 却与你 相背。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, '你所吃 的那点 食物必吐出来;你所说的甘美 言语 也必落空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, '你不要 说话 给愚昧人 听,因 他必藐视 你智慧 的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, '不可 挪移 古时 的地界,也不可 侵入 孤儿 的田地; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, '因 他们的救赎主 大有能力,他 必向你 为他们辨 屈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, '你要留心 领受 训诲,侧耳 听从知识 的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, '不可 不 管教 孩童; 你用杖 打他,他必不 至于 死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, '你 要用杖 打他,就可以救 他的灵魂 免下阴间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, '我儿,你心 若 存智慧,我 的心 也 甚欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, '你的嘴 若说 正直话,我的心肠 也必快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, '你心 中不要 嫉妒 罪人,只要 终 日 敬畏 耶和华; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, '因为 至终 必 有善报,你的指望 也不致 断绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, '我儿,你 当听,当存智慧,好在正道上 引导 你的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, '好饮 酒的,好吃 肉的,不要 与他们来往; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, '因为 好酒 贪食的,必致贫穷;好睡觉的,必穿 破烂衣服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, '你要听从 生 你的父亲; 你母亲 老了,也不可 藐视她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, '你当买  真理;就是智慧、训诲,和聪明 也都不可 卖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, '义人 的父亲 必大 得快乐;人生 智慧 的儿子,必因他 欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, '你要使父 母 欢喜,使生你的 快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, '我儿,要将你的心 归 我;你的眼目 也要喜悦 我的道路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, ' 妓女 是深 坑;外女 是窄 阱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, ' 她 埋伏 好像强盗;她使人中 多有 奸诈的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, '谁有 祸患?谁有 忧愁?谁有 争斗?谁有哀叹(或译:怨言)?谁 无故 受伤?谁 眼目 红赤? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, '就是那流连 饮 酒、常去 寻找 调和酒的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, '酒 发红, 在杯 中闪烁,你不可 观看,虽然下咽 舒畅,终久 是咬 你如蛇,刺 你如毒蛇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, '你眼 必看见异怪的事(或译:淫妇);你心 必发出 乖谬的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, '你必 像躺 在海 中,或像卧 在桅杆 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, '你必说:人打我,我却未 受伤;人鞭打我,我竟不 觉得。我几时 清醒,我仍 去寻酒。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, '你不要 嫉妒 恶 人,也不要 起意 与他们 相处; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, '因为,他们的心 图谋 强暴,他们的口 谈论 奸恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, '房屋 因智慧 建造,又因聪明 立稳; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, '其中 因知识 充满 各样 美好 宝贵 的财物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, '智慧 人 大有能力;有知识 的人 力上加 力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, '你 去打 仗, 要凭智谋;谋士 众多,人便得胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, '智慧 极高,非愚昧人所能及,所以在城门 内不敢 开  口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, '设计 作恶的,必称 为 奸 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, '愚妄人 的思念 乃是罪恶;亵慢者 为人 所憎恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, '你在患难 之日 若胆怯,你的力量 就微小。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, '人被拉 到死地,你要解救;人将 被杀,你须 拦阻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, '你若 说: 这事 我未 曾知道,那衡量 人心 的岂不 明白吗?保守 你命 的岂不 知道吗?他岂不按各人所行 的报应 各人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, '我儿,你要吃 蜜,因为 是好的;吃蜂房下滴的蜜 便 觉 甘甜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, '你心 得了智慧,也必觉得 如此。你若 找著,至终 必有善报;你的指望 也不致 断绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, '你这恶人,不要 埋伏攻击 义人 的家;不要 毁坏 他安居之所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, '因为,义人 虽七次 跌倒,仍必兴起;恶人 却被祸患 倾倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, '你仇敌 跌倒,你不要 欢喜;他倾倒,你心 不要 快乐; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, '恐怕 耶和华 看见 就不喜悦,将怒气 从仇敌身上 转过来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, '不要 为作恶的 心怀不平,也不要 嫉妒 恶人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, '因为,恶人 终 不 得善报;恶人 的灯 也必熄灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, '我儿,你要敬畏 耶和华 与君王,不要 与 反复无常的人 结交, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, '因为 他们的灾难 必忽然 而起。耶和华与君王 所施行的毁灭,谁 能知道呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, '以下 也 是智慧人的箴言:审判时 看 人情面 是不 好的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, '对恶人 说「你是 义人」的,这人万民 必咒诅,列邦 必憎恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, '责备恶人的,必得喜悦;美好的 福 也必临 到他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, '应对 正直的,犹如与人亲 嘴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, '你要在外头 预备 工料,在田间 办理整齐,然后 建造 房屋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, '不可 无故 作见证 陷害邻舍,也不可用嘴 欺骗人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, '不可 说:人怎样 待 我,我也怎样 待 他;我必照他所行的 报复他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, '我经过 懒惰 人 的田地、 无 知 人 的葡萄园, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, ' 荆棘 长 满了地皮,刺草 遮盖 了田面,石 墙 也坍塌了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, '我 看见 就留心 思想;我看著 就领了 训诲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, '再睡 片时,打盹 片时,抱著 手 躺卧 片时, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, '你的贫穷 就必如强盗 速来,你的缺乏 仿佛拿兵器 的人来到。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, '以下 也是 所罗门 的箴言,是 犹大 王 希西家 的人 所誊录的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, '将事 隐秘乃 神 的荣耀;将事 察清 乃君王 的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, '天 之高,地 之厚,君王 之心 也测 不透。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, '除去 银子 的渣滓 就有银子出来,银匠 能以做器皿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, '除去 王 面前 的恶人,国位 就靠公义 坚立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, '不要 在王 面前 妄自尊大;不要 在大人 的位 上站立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, '宁可 有人说:请你上来,强 如 在你 觐见 的王子 面前 叫你退下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, '不要 冒失 出去 与人争竞,免得 至终 被他 羞辱,你就不知道怎样 行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, '你与 邻舍 争讼,要与他一人辩论,不可 泄漏 人 的密事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, '恐怕 听见的人 骂你,你的臭名 就难以 脱离。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, '一句话 说得 合宜,就如金 苹 𬞟果 在银 网子里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, '智慧人 的劝戒,在 顺从的人 耳中,好像金 耳环 和精金 的妆饰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, '忠信 的使者 叫差他的 人 心 里舒畅,就如在收割 时 有冰雪 的凉气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, '空 夸 赠送礼物 的,好像无 雨 的风 云。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, '恒常 忍耐 可以劝动 君王;柔和的 舌头 能折断 骨头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, '你得了 蜜吗?只可吃 够而已,恐怕 你过饱 就呕吐出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, '你的脚 要少进 邻舍 的家,恐怕 他厌烦你,恨恶你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, '作 假 见证 陷害邻舍 的,就是大槌,是利刀,是快 箭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, '患难 时 倚靠 不忠诚的人,好像破坏的 牙,错骨缝 的脚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, '对 伤 心 的人唱 歌,就如冷 天 脱 衣服,又如碱 上 倒醋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, '你的仇敌 若 饿了,就给他饭 吃;若 渴了,就给他水 喝; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, '因为,你 这样行就是把炭火 堆 在 他的头上;耶和华 也必赏赐 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, '北 风 生 雨,谗谤人 的舌头 也生怒 容。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, '宁可 住 在 房顶 的角上,不在宽阔的 房屋 与争吵的 妇人同住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, '有好 消息 从远 方来,就如拿凉 水 给 口渴 的人喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, '义 人在恶人 面前 退缩,好像逿浑 之泉,弄浊 之井。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, '吃 蜜 过多 是不 好的;考究 自己的荣耀 也是可厌的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, '人 不 制伏 自己的心,好像毁坏 的城邑 没有 墙垣。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, '夏天 落雪,收割时 下雨,都不 相宜;愚昧人 得尊荣 也是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, '麻雀 往来,燕子 翻飞;这样,无故的 咒诅 也必不 临到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, '鞭子 是为打马,辔头 是为勒驴;刑杖 是为打愚昧人 的背。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, '不要 照愚昧人 的愚妄 话回答他,恐怕 你 与他 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, '要照愚昧人 的愚妄 话回答他,免得 他自以为 有 智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, '藉 借愚昧人 手 寄 信的,是砍断 自己的脚,自受(原文是:喝)损害。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, '瘸子 的脚 空存无用;箴言 在愚昧人 的口中也是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, '将尊荣 给 愚昧人的,好像 人把石子 包 在机弦里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, '箴言 在愚昧人 的口中,好像荆棘 刺入 醉汉 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, '雇 愚昧人的,与雇 过路人的,就像射伤 众人的 弓箭手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, '愚昧人 行愚妄事,行了又行,就如狗 转过来 吃 牠所吐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, '你见 自以为 有智慧 的人吗?愚昧人 比他 更有指望。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, '懒惰 人说:道 上有猛狮,街 上 有壮狮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, '门 在 枢纽 转动,懒惰人 在 床上也是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, '懒惰人 放 手 在盘子里,就是向 口 撤回 也以为劳乏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, '懒惰人 看自己 比七 个善于  应对 的人更有智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, '过路 被事激动,管理 不 干己 的争竞,好像人揪住 狗 耳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, ' 人 欺凌 邻舍,却说:我 岂不是 戏耍吗?他就像疯狂的人 抛掷 火把、利箭,与杀人的兵器(原文是死亡)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, '火 缺了 柴 就必熄灭;无人 传舌,争竞 便止息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, '好争竞 的人 煽惑 争端,就如余 馀火 加炭,火 上加柴一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, '传舌人 的言语,如同美食, 深入 人的心 腹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, '火热 的嘴,奸恶 的心,好像银 渣 包的 瓦器。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, '怨恨人的,用嘴 粉饰,心里 却藏著 诡诈; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, ' 他用甜言蜜语,你不可 信 他,因为 他心中 有七 样可憎恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, '他虽用诡诈 遮掩 自己的怨恨,他的邪恶 必在会中 显露。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, '挖 陷坑的,自己必掉 在其中;滚 石头的,石头必反滚 在他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, '虚谎 的舌 恨 他所压伤的人;谄媚的 口 败坏 人的事。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, '不要 为明 日 自夸,因为 一日 要生 何事,你尚且不能 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, '要别人 夸奖你,不可 用口自夸;等外人称赞你,不可 用嘴自称。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, '石头 重,沙土 沉,愚妄人 的恼怒 比这两样 更重。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, '忿怒 为残忍,怒气 为狂澜,惟有 嫉妒,谁 能敌得住呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, '当面的 责备 强如 背地的 爱情。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, '朋友 加的伤痕 出于 忠诚;仇敌 连连亲嘴 却是多余 馀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, '人 吃饱了,厌恶 蜂房的蜜;人 饥饿了,一切 苦物 都觉甘甜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, ' 人 离本处 飘流,好像雀鸟 离 窝 游飞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, '膏油 与香料 使人心 喜悦;朋友 诚实 的劝教 也是如此甘美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, '你的朋友 和父亲 的朋友,你都不可 离弃。你遭难 的日子,不要 上弟兄 的家 去;相近的 邻舍 强如 远方的 弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, '我儿,你要作智慧人,好叫我的心 欢喜,使我可以回答 那讥诮我的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, '通达人 见 祸 藏躲;愚蒙人 前往 受害。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, ' 谁为生人 作保,就拿 谁的衣服;谁为 外女 作保,谁就承当。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, '清晨 起来,大 声 给朋友 祝福的,就算是 咒诅 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, '大雨 之日 连连 滴漏,和争吵的 妇人 一样; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, '想拦阻她的,便是拦阻 风,也是右手 抓 油。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, '铁 磨 铁,磨出刃来;朋友相感(原文是磨 朋友 的脸)也是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, '看守 无花果树的,必吃 树上的果子;敬奉 主人的,必得尊荣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, '水 中照脸,彼此相符;人 与人,心 也相对。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, '阴间 和灭亡 永不 满足;人 的眼目也是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, '鼎 为炼银,炉 为炼金,人 的称赞也试炼人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, '你虽 用杵 将 愚妄人 与打碎的麦子 一同捣 在臼 中,他的愚妄 还是离 不了 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, '你要详细 知道 你羊群 的景况,留心 料理 你的牛群; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, '因为 资财 不能 永有,冠冕 岂能 存到万代? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, '干草 割去,嫩草 发现,山上 的菜蔬 也被收敛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, '羊羔 之毛是为你作衣服;山羊 是为作田地 的价值, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, '并有母山羊 奶 够 你吃,也够你的家眷 吃,且够养 你的婢女。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, '恶人 虽无人 追赶 也逃跑;义人 却胆壮 像狮子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, '邦国 因有罪过,君王 就多更换;因有聪明 知识 的人,国必 长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, '穷 人 欺压 贫民,好像暴 雨 冲没 粮食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, '违弃 律法的,夸奖 恶人;遵守 律法的,却与恶人 相争。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, '坏 人 不 明白 公义;惟有寻求 耶和华的,无不 明白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, '行为 纯正 的穷乏人 胜过 行事 乖僻的 富足人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, '谨守 律法的,是智慧 之子;与贪食人 作伴的,却羞辱 其父。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, '人以厚 利 加增 财物,是给那怜悯 穷人 者积蓄的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, '转 耳 不听 律法的,他的祈祷 也为 可憎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, '诱惑正直人 行 恶 道的, 必掉在 自己的坑里;惟有完全人 必承受 福分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, '富足 人 自以为 有智慧,但聪明的 贫穷人 能将他查透。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, '义人 得志,有大 荣耀;恶人 兴起,人 就躲藏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, '遮掩 自己罪过的,必不 亨通;承认 离弃罪过的,必蒙怜恤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, '常存 敬畏 的,便为有福;心 存刚硬的,必陷在 祸患里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, '暴虐的 君王 辖制 贫 民,好像吼叫的 狮子、觅食的 熊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, '无 知 的君 多行 暴虐;以贪财 为可恨的,必年长 日久。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, '背负 流人 血 之罪的,必往 坑里 奔跑,谁也不可 拦阻 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, '行动 正直的,必蒙拯救;行事 弯曲的,立时 跌倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, '耕种 自己田地的,必得饱 食;追随 虚浮的,足受穷乏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, '诚实 人 必多 得福;想要急速 发财的,不 免受罚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, '看 人的情面 乃为不 好;人 因 一块 饼 枉法也为不好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, '人 有恶 眼 想要急速 发财,却不 知 穷乏 必临到他身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, '责备 人的,后来 蒙人 喜悦,多于 那用舌头 谄媚人的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, '偷窃 父 母的,说:这不是 罪,此人 就是 与强盗 同类。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, '心中 贪婪的,挑起 争端;倚靠 耶和华的,必得丰裕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, '心中 自是的,便是 愚昧人;凭智慧 行事的,必 蒙拯救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, '赒济 贫穷的,不致 缺乏;佯为不见的,必多受 咒诅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, '恶人 兴起,人 就躲藏;恶人败亡,义人 增多。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, '人 屡次受责罚,仍然硬著 颈项;他必顷刻 败坏,无法 可治。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, '义人 增多,民 就喜乐;恶人 掌权,民 就叹息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, '爱慕 智慧 的,使父亲 喜乐;与妓女 结交的,却浪费 钱财。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, '王 藉 借公平,使国 坚定; 索要贿赂,使国倾败。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, '谄媚 邻舍 的,就是设 网罗 绊 他的脚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, '恶 人 犯罪,自陷网罗;惟独义人 欢呼 喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, '义人 知道 查明穷人 的案;恶人 没有 聪明,就不得而知。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, '亵慢 人 煽惑 通城;智慧人 止息 众怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, '智慧 人 与 愚妄 人 相争,或怒 或笑,总不能 使他止息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, '好流人血的,恨恶 完全人,索取 正直人 的性命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, '愚妄人 怒气 全 发;智慧人 忍气含怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, '君王 若听 谎 言,他一切 臣仆 都是奸恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, '贫穷人、强暴 人 在世相遇;他们 的眼目 都蒙耶和华 光照。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, '君王 凭诚实 判断 穷人;他的国位 必永远 坚立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, '杖 打和责备 能加增 智慧;放纵的 儿子 使母亲 羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, '恶人 加多,过犯 也加多,义人 必看见 他们跌倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, '管教 你的儿子,他就使你得安息,也必使 你心里 喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, '没有 异象(或译:默示),民 就放肆;惟遵守 律法的,便为有福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, '只用言语,仆人 不肯 受管教;他虽然 明白,也不 留意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, '你见 言语 急躁的 人吗?愚昧人 比他更 有指望。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, '人将仆人 从小 娇养,这仆人终久 必成了 他的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, '好气的 人 挑启 争端;暴怒的 人 多多 犯罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, '人 的高傲 必使他卑下;心里 谦逊的,必得 尊荣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, '人与 盗贼 分赃,是恨恶 自己的性命;他听见 叫人发誓的声音,却不 言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, '惧怕 人的,陷入 网罗;惟有倚靠 耶和华的,必得安稳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, '求 王 恩 的人多;定 人 事 乃在耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, '为非作歹 的,被义人 憎嫌;行事 正直的,被恶人 憎恶。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, '雅基 的儿子 亚古珥 的言语 就是真言。这人 对以铁 和乌甲 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, ' 我 比众人 更蠢笨,也没有 人 的聪明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, '我没有 学好 智慧,也不认识 至圣者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, '谁 升 天 又降下来?谁 聚 风 在掌握中?谁 包 水 在衣服里?谁 立定 地 的四 极?他名 叫什么?他儿子 名 叫什么? 你知道吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, '神 的言语 句句都是 炼净的;投靠 他的,他 便作他们的盾牌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, ' 他的言语,你不可 加添,恐怕 他责备 你,你就显为说谎言的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, '我求 你 两件事,在我未死 之先,不要 不赐 给我: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, '求你使虚假 和谎言 远离 我;使 我 也不 贫穷 也不富足;赐给我 需用的 饮食, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, '恐怕 我饱足 不认你,说:耶和华 是谁呢?又恐怕 我贫穷 就偷窃,以致亵渎我 神 的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, '你不要 向 主人 谗谤 仆人,恐怕 他咒诅你,你便算为有罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, '有一宗人(宗:原文是代;下同),咒诅 父亲,不 给 母亲 祝福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, '有一宗人,自以为 清洁,却没有 洗去 自己的污秽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, '有一宗人,眼目 何其 高傲,眼皮 也是高举。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, '有一宗人,牙 如剑,齿 如刀,要吞灭 地上 的困苦人 和世间 的穷乏人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, '蚂蟥有 两个 女儿,常说:给呀,给呀! 有三样 不 知足的,连不 说「够的」共有四样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, '就是阴间 和石胎,浸 水 不 足 的地,并火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, '戏笑 父亲、藐视 而不听从 母亲的,他的眼睛 必为谷中 的乌鸦 啄出来,为鹰 雏 所吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, '我所测不透 的奇妙 有 三样,连我所不 知道的 共有四样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, '就是鹰 在空中 飞的道;蛇 在 磐石 上爬的道;船 在海 中 行的道;男 与女 交合的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, '淫 妇 的道 也是这样:她吃了,把嘴 一擦 就说:我没 有行 恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, ' 使地 震动的 有三样,连 地担 不 起 的共有四样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, ' 就是 仆人 作王; 愚顽人 吃饱; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, ' 丑恶的女子 出嫁;婢女 接续 主母。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, '地上 有 四样 小物, 却甚 聪明: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, '蚂蚁 是无 力 之类,却在夏天 预备 粮食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, '沙番 是软弱 之类,却在磐石中 造 房。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, '蝗虫 没有 君王,却 分队 而出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, '守宫 用爪 抓墙, 却住在王 宫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, '步行 威武的 有 三样,连行走 威武的 共有四样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, '就是狮子─乃百兽中 最为猛烈、无 所 躲避的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, '猎狗, 公山羊,和无人能敌的 君王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, '你若 行事愚顽,自高自傲,或是 怀了恶念,就当用手 摀口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, ' 摇 牛奶 必成 奶油;扭 鼻子 必出 血。照样,激动 怒气 必起 争端。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, '利慕伊勒 王 的言语,是 他母亲 教训他 的真言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, ' 我的儿啊, 我腹中 生的儿啊, 我许愿  得的儿啊!我当怎样教训你呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, '不要 将你的精力 给 妇女;也不要有败坏 君王 的行为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, '利慕伊勒啊,君王喝酒,君王 喝 酒 不相宜;王子 说浓酒 在那里 也不相宜; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, '恐怕 喝了 就忘记 律例,颠倒 一切 困苦 人 的是非。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, '可以把浓酒 给 将亡的人喝,把清酒 给苦 心的人喝, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, '让他喝了,就忘记 他的贫穷,不 再 记念 他的苦楚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, '你当为哑巴(或译:不能自辩的)开  口,为 一切 孤独的 伸冤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, '你当开  口 按公义 判断,为困苦 和穷乏的 辨屈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, '才德的 妇人 谁 能得著呢?她的价值 远胜过 珍珠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, '她丈夫 心里 倚靠 她,必不 缺少 利益; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, '她一 生 使丈夫有 益 无 损。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, '她寻找 羊羢 和麻,甘心 用手 做工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, '她 好像商 船 从远方 运 粮 来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, '未到黎明 她就起来,把食物 分给 家中的人,将当做的工 分派婢女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, '她想得 田地 就买 来;用手 所得之利 栽种 葡萄园。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, '她以能力 束 腰,使膀臂 有力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, '她觉得 所经营的 有利;她的灯 终夜 不 灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, '她手 拿 撚线 缐竿,手 把 纺线 缐车。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, '她张 手 赒济困苦人,伸 手 帮补穷乏人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, '她不 因下雪 为家里的人 担心,因为 全 家 都穿著 朱红衣服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, '她为自己 制作 绣花毯子;她的衣服 是细麻 和紫色布做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, '她丈夫 在城门口 与 本地 的长老 同坐,为众人所认识。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, '她做 细麻布衣裳 出卖,又将腰带 卖 与商家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, '能力 和威仪 是她的衣服;她想到日 后的景况 就喜笑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, '她开  口 就发智慧;她舌 上 有仁慈的 法则。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, '她观察 家务,并不 吃 闲  饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, '她的儿女 起来 称她有福;她的丈夫 也称赞她, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, '说:才德的 女子 很多,惟独你 超过 一切。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, '艳丽 是虚假的,美容 是虚浮的;惟敬畏 耶和华 的妇女 必 得称赞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, '愿 她 享受 操作 所得的;愿 她的工作 在城门口 荣耀她。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, '在耶路撒冷 作王、大卫 的儿子、传道者 的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, '传道者 说:虚空 的虚空,虚空 的虚空,凡事 都是虚空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, '人 一切的 劳碌,就是 他在日光 之下 的劳碌,有什么 益处呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, '一代 过去,一代 又来,地 却永远 长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, '日头 出来,日头 落下,急 归 所 出 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, '风 往 南 刮,又向 北 转,不住地 旋转,而且 返回 转行 原道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, '江河 都 往 海 里流,海 却不 满;江河 从 何处 流,仍 归 还 何处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, '万 事令人厌烦(或译:万物满有困乏),人 不 能 说尽。眼看,看 不 饱;耳听,听 不 足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, '已有的事 后必再有;已行的事 后必再行。日光 之下 并无 新事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, '岂有 一件事 人能指著说 这 是 新的?哪知,在 我们以前 的世代 早已 有了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, '已过的世代,无人 记念;将来的世代,后来的人 也 不 记念。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, '我 传道者 在耶路撒冷 作过 以色列 的王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, '我专 心 用智慧 寻求、查究 天 下 所 做 的一切事,乃知 神 叫 世人 所经练的 是 极重的 劳苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, '我见 日光 之下 所做 的一切 事, 都是 虚空,都是捕 风。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, '弯曲的,不 能 变直;缺少的,不 能 足数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, '我 心里 议论 说: 我 得了 大 智慧,胜过 我以前 在 耶路撒冷 的众人,而且我心中 多 经历 智慧 和知识的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, '我又专 心 察明 智慧、 狂妄,和愚昧,乃知 这 也 是 捕 风。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, '因为 多有 智慧,就多有 愁烦;加增 知识的,就加增 忧伤。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, '我 心里 说:「来吧,我以喜乐 试试你,你好享 福!」谁知,这也 是 虚空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, '我指嬉笑 说:「这是狂妄。」论喜乐说:「 有何 功效呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, '我心里 察究,如何用酒使 我肉体 舒畅,我心 却仍以智慧 引导我;又如何持住 愚昧,等 我看明 世人,在天 下 一生 当行 何事 为 美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, '我为自己动大 工程,建造 房屋,栽种 葡萄园, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, '修造 园 囿,在其中 栽种 各样 果 木树; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, '挖造 水 池,用 以浇灌 嫩小的 树木。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, '我买 了 仆 婢,也有 生 在家中的仆婢;又 有 许多 牛 群 羊群,胜过以前 在耶路撒冷 众人 所有的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, '我又 为自己 积蓄 金 银 和君王 的财宝,并各省的财宝;又 得 唱歌的男 女 和世人 所喜爱的物,并许多的妃嫔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, '这样,我就日见昌盛,胜过 以前 在耶路撒冷 的众人。我的智慧 仍然 存留。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, '凡 我眼 所求的,我没有 留下 不给它的; 我心 所 乐的,我没有 禁止不享受的;因 我的心 为我一切 所劳碌的 快乐,这 就是我从 劳碌 中所得的分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, '后来,我 察看 我手 所经营 的一切 事 和我劳碌 所成的 功。谁知 都 是虚空,都是捕 风;在日光 之下 毫无 益处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, '我 转念 观看 智慧、狂妄,和愚昧。在王 以后 而来的 人 还 能做什么呢?也不过行 早先 所行的就是了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, '我 便看出 智慧 胜过 愚昧,如同 光明 胜过 黑暗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, '智慧人 的眼目光明(光明:原文是在他头上),愚昧人 在黑暗里 行。我 却 看明 有一件 事,这两等人 都 必遇见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, '我 就心里 说:「愚昧人 所遇见的,我 也 必遇见, 我 为何 更有 智慧呢?」我心里 说,这 也是 虚空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, '智慧人 和 愚昧人一样,永远 无人 记念,因为 日 后 都 被忘记;可叹 智慧人 死亡,与 愚昧人无异。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, '我所以恨恶 生命;因为 在日光 之下 所行 的事 我都以为 烦恼, 都 是虚空,都是捕 风。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, '我 恨恶 一切的 劳碌,就是我 在日光 之下 的劳碌,因为我得来的必留给 我以后的 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, '那人是 智慧 是 愚昧,谁 能知道?他竟要管理 我劳碌 所得的,就是我在日光 之下 用智慧所得的。这 也 是虚空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, '故此,我 转想 我在日光 之下 所劳碌 的一切 工作, 心 便绝望。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, '因为 有 人 用智慧、知识、灵巧 所劳碌得来的,却要留给 未 曾劳碌 的人 为分。这 也 是虚空,也是大 患。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, '人 在日光 之下 劳碌 累 心, 在他 一切的 劳碌 上得著 什么呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, '因为 他日日 忧虑,他的劳苦 成为愁烦,连 夜间 心 也不 安。这 也 是 虚空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, '人 莫 强如 吃 喝,且 在劳碌中 享 福,我 看 这 也 是出于  神 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, '论到 吃用、享福,谁 能胜过 我呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, ' 神喜悦 谁,就给谁 智慧、知识,和喜乐;惟有罪人, 神使 他劳苦,叫他将所收聚的、所堆积的 归给 神 所喜悦的人。这 也 是虚空,也是捕 风。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, '凡事 都有定期,天 下 万 务 都有定时。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, '生 有时,死 有时;栽种 有时,拔出 所栽种的 也有时; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, '杀戮 有时,医治 有时;拆毁 有时,建造 有时; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, '哭 有时,笑 有时;哀恸 有时,跳舞 有时; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, '抛掷 石头 有时,堆聚 石头 有时;怀抱 有时,不 怀抱 有时; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, '寻找 有时,失落 有时;保守 有时,舍弃 有时; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, '撕裂 有时,缝补 有时;静默 有时,言语 有时; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, '喜爱 有时,恨恶 有时;争战  有时,和好 有时。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, '这样看来,做事的人 在 他 的劳碌 上有什么 益处呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, '我见 神 叫 世人 劳苦, 使他们在其中 受经练。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, '神 造 万物,各按其时 成为美好,又 将永生(原文是永远)安置 在世人心里。然而 神 从始 至 终 的 作 为,人 不能 参透。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, '我知道 世人,莫 强 如 终身 喜乐 行 善; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, '并且 人人 吃 喝,在他一切 劳碌 中享 福,这也是 神 的恩赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, '我知道 神 一切 所 做 的都必 永存;无 所增添,无 所减少。 神 这样行,是要人在他面前 存敬畏的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, '现今的事 早先 就有了,将来的事 早已 也有了,并且 神使已过的事重新再来(或译:并且 神再寻回 已过的事)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, '我又 见 日光 之下,在审判 之处有 奸恶,在公义 之处也有 奸恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, '我 心里 说, 神 必审判 义人和 恶人;因为 在那里,各样 事务, 一切 工作,都有定时。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, '我 心里 说,这乃为 世人 的缘故,是 神 要试验他们,使他们 觉得 自己 不过像兽一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, '因为 世人 遭遇的,兽 也遭遇,所遭遇的 都是一样:这个 怎样死,那个 也怎样 死,气息 都 是一样。人 不能 强 于  兽, 都 是虚空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, '都 归 一 处,都 是 出于  尘土,也都 归 于  尘土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, '谁 知道 人 的灵 是 往上 升,兽 的魂 是 下 入 地呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, '故此,我见 人 莫 强 如 在他经营的事上 喜乐,因为 这是 他的分。 他身后 的 事 谁 能使他回来 得见呢?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, '我 又转念,见 日光 之下 所 行的 一切 欺压。看哪,受欺压的 流泪,且无人 安慰; 欺压他们的 有势力,也无人 安慰 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, '因此,我 赞叹 那 早已 死的 死人,胜过 那 还 活著 的活人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, '并且我以为 那 未 曾 生的,就是 未 见过 日光 之下 恶 事的,比这两等人 更强。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, '我 又见 人为 一切的 劳碌和 各样 灵巧的 工作 就 被邻舍 嫉妒。这 也 是虚空,也是捕 风。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, '愚昧人 抱著 手,吃 自己的肉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, '满了 一把,得享安静,强 如满了 两把,劳碌 捕 风。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, '我 又转念,见 日光 之下 有一件虚空的事: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, '有 人孤单 无 二, 无 子 无 兄,竟 劳碌 不 息,眼目 也 不 以钱财 为足。他说:「我 劳劳碌碌,刻苦 自己,不享福乐,到底是为谁呢?」这 也 是虚空,是 极重的 劳苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, '两个人 总比 一个人 好,因为 二人劳碌 同得 美好的 果效。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, ' 若 是跌倒,这人 可以扶起 他的同伴;若是孤身 跌倒,没有 别人 扶起他来,这人就有祸了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, '再者, 二人 同睡 就都暖和,一人 独睡怎能 暖和呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, '有人攻胜 孤身一人,若 有二人 便能敌挡 他;三股合成 的绳子 不 容易 折断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, '贫穷 而有智慧 的少年人 胜过 年老 不 肯 纳谏 𫍝 的愚昧 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, '这人 是从 监牢中 出来 作王,在他国中,生来 原是 贫穷的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, '我见 日光 之下 一切 行动 的活人 都随从 那第二位,就是 起来 代替 老王的少年人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, '他所治理的 众人 就是 他的百姓,多得无 数;在他后来的人 尚且 不 喜悦 他。这 真 是虚空,也是捕 风。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, ' 你到 神 的殿 要谨慎 脚步;因为近前 听,胜过愚昧人献祭(或译:胜过献 愚昧人 的祭), 他们本不 知道 所做的 是恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, '你在 神 面前 不可 冒失 开 口,也不可 心 急 发 言;因为 神 在天上,你 在 地下,所以 你的言语 要 寡少。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, '事务 多,就 令人做 梦;言语 多,就显出愚昧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, '你向 神 许 愿 ,偿还 不可 迟延,因 他不 喜悦 愚昧人,所以你许的愿  应当偿还。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, '你许愿  不 还,不如 不 许。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, '不可 任 你的口 使 肉体 犯罪,也不可在祭司(原文是使者)面前 说 是 错许了。为何使 神 因 你的声音 发怒,败坏 你手 所做的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, ' 多 梦 和多 言,其中多有虚幻,你只要 敬畏 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, '你若 在一省之中 见 穷人 受欺压,并夺去 公义 公平的事,不要 因 此 诧异;因 有一位高 过 居高位的 鉴察,在他们以上 还有更高的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, '况且地 的益处 归众人,就是君王 也受田地 的供应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, '贪爱 银子的,不 因得银子 知足;贪爱 丰富 的,也不 因得利益知足。这 也是 虚空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, '货物 增添,吃的人 也增添,物主 得什么 益处呢? 不过 眼 看而已! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, '劳碌的人 不拘吃多吃少,睡 得香甜;富足人 的丰满 却不 容 他 睡觉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, '我见 日光 之下 有 一宗大 祸患,就是财主 积存 资财,反害自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, '因遭遇祸患,这些 资财 就消灭;那人若生了 儿子,手里 也一无 所有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, '他怎样从 母 胎 赤身而来,也必照样 赤身 而去;他所劳碌 得来的,手中 分毫 不能 带去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, '他来 的情形怎样,他去 的情形也怎样。这 也 是一宗大 祸患。他 为风 劳碌 有什么 益处呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, '并且 他终身 在黑暗中 吃喝,多有 烦恼,又有病患 呕气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, ' 我 所见 为善 为美的,就是人在 神 赐 他 一 生 的日子 吃 喝,享受 日光 之下 劳碌 得来 的好处,因为 这是 他的分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, ' 神 赐 人 资财 丰富,使他能 以 吃用,能取 自己的分,在他劳碌中 喜乐,这 乃是 神 的恩赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, ' 他不 多 思念 自己一生 的年日,因为 神 应 他的心 使他喜乐。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, ' 我见 日光 之下 有 一宗祸患 重压 在 人身上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, '就是人蒙 神 赐 他 资财、丰富、尊荣,以致他心里 所 愿  的一样都 不 缺,只是 神 使他 不 能 吃用,反有 外人 来吃用。这是 虚空,也是 祸 患。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, '人 若 生 一百个儿子,活 许多 岁数,以致他的年 日 甚 多,心里 却不得 满享 福乐,又 不 得 埋葬;据我说,那不到期而落的胎 比他 倒好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, '因为 虚虚 而来,暗暗 而去,名字 被黑暗 遮蔽, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, '并且 没有 见过 天日,也毫无 知觉;这胎,比那人 倒享安息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, '那人虽然 活 千 年,再活千年,却不 享 福,众人 岂不 都归 一个 地方 去吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, '人 的劳碌 都 为口腹,心里 却 不 知足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, '这样看来,智慧人 比 愚昧人 有什么 长处呢?穷人 在众人 面前 知道 如何行,有什么长处呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, '眼睛 所看的 比心里 妄想的 倒好。这 也是 虚空,也是捕 风。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, '先前所有的,早已 起了 名,并知道 何为 人,他也不 能 与 那比自己 力大的 相争。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, '加增 虚浮 的事 既 多,这与人 有什么 益处呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, ' 人 一生 虚度的 日子,就如影儿 经过,谁 知道 什么 与他有益呢? 谁 能告诉 他 身后 在日光 之下 有 什么事呢?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, '名誉 强如美好的 膏油;人死 的日子 胜过人生 的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, '往 遭丧 的家 去,强如 往 宴乐 的家 去;因为 死是 众人 的结局,活人 也必将这事放 在 心上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, '忧愁 强如 喜笑;因为 面 带愁容,终必使心 喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, '智慧人 的心 在遭丧 之家;愚昧人 的心 在快乐 之家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, '听 智慧人 的责备,强如 听 愚昧人 的歌唱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, ' 愚昧人 的笑声,好像锅 下 烧荆棘 的爆声;这 也 是虚空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, ' 勒索 使智慧人 变为愚妄;贿赂 能败坏 人的慧心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, '事情 的终局 强如 事情的起头;存心 忍耐的,胜过 居心 骄傲的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, '你不要 心里 急躁 恼怒,因为 恼怒 存在 愚昧人 的怀中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, '不要 说:先前的 日子 强过 如今的日子,是 什么缘故呢? 你这样 问,不是 出于 智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, '智慧 和 产业 并好,而且见 天日 的人得智慧更为有益。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, '因为 智慧 护庇人,好像银钱 护庇人一样。惟独智慧 能保全 智慧人的生命。这就是知识 的益处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, '你要察看 神 的作为;因 神使为曲的,谁 能 变为直呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, '遇亨通 的日子 你当 喜乐;遭患难 的日子 你当思想;因为 神 使 这两样 并列,为的是 叫人 查不 出 身后 有什么事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, '有 义人 行义,反致灭亡;有 恶人 行恶,倒享长寿。这都是 我在虚度 之日 中所见过的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, '不要 行义 过分,也不要 过于  自逞智慧,何必 自取败亡呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, '不要 行恶 过分,也不要 为人愚昧,何必 不到 期 而死呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, '你持守 这个 为美,那个 也 不要 松 手;因为 敬畏 神的人,必从这两样 出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, '智慧 使有智慧的人 比城中 十个 官长 更有能力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, '时常行 善 而不 犯罪 的义 人, 世上 实在 没有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, ' 人所 说 的一切 话,你不要 放在 心上,恐怕 听见 你的仆人 咒诅你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, '因为 你心里 知道, 自己 也 曾屡 次 咒诅 别人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, '我曾用智慧 试验 这 一切事;我说,要得智慧,智慧却 离我 远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, '万事之理,离我甚远,而且最 深,谁 能测透呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, '我 转念,一心 要知道,要考察,要寻求 智慧 和万事的理由;又要知道 邪恶 为愚昧,愚昧 为狂妄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, '我 得知 有等妇人 比死 还苦: 她的心 是 网 罗,手 是锁链。凡蒙 神 喜悦 的人必能躲避 她;有罪的人 却被她 缠住了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, '传道者 说:「看哪,一千男子中,我找到 一个 正直人,但众 女子 中,没有 找到一个。」我将这事一 一比较,要寻求 其理, 我心 仍要 寻找,却未 曾找到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, ' 我所找到 的只有一件,就是 神 造 人 原是正直,但他们 寻出 许多 巧计。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, '谁 如智慧人呢?谁 知道 事情 的解释呢?人 的智慧 使他的脸 发光,并使他脸上 的暴气 改变。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, '我 劝你遵守 王 的命令;既指 神 起誓,理当如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, '不要 急躁 离开  王的面前,不要 固执 行恶,因为 他凡事 都随自己的心意 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, ' 王 的话 本有权力,谁 敢问他 说「你做 什么」呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, '凡遵守 命令的,必不 经历 祸患;智慧人 的心 能辨明 时候和定理(原文是审判;下节同)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, ' 各样 事务 成就都有 时候 和定理,因为 人 的苦难 重压 在他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, ' 他不 知道 将来的事,因为 将来 如何,谁 能告诉 他呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, '无 人 有权力掌管 生命,将 生命 留住;也无人 有权力掌管 死 期;这场争战 ,无人 能免;邪恶 也不能 救 那好行邪恶的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, ' 这 一切 我都见过,也专 心 查考日光 之下 所 做 的一切 事。有时 这人 管辖 那人,令人 受害。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, ' 我见 恶人 埋葬,归入坟墓;又见行正直事的 离开  圣 地,在城中 被人忘记。这 也 是虚空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, '因为 断定 罪名 不 立刻 施刑,所以 世人 满 心 作 恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, '罪人 虽然 作 恶 百次,倒享长久的年日;然而 我 准 知道, 敬畏 神的,就是 在他面前 敬畏的人,终久必得 福乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, '恶人 却不 得 福乐,也不 得长久的 年日;这年日好像影儿,因 他不 敬畏 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, '世上 有 一件虚空的事,就是 义人 所 遭遇的,反照恶人 所行的;又有 恶人 所遭遇的,反照义人 所行的。我说,这 也是 虚空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, '我 就称赞 快乐,原来 人 在日光 之下,莫 强 如 吃 喝 快乐;因为他 在日光 之下, 神 赐 他 一生 的年日,要从劳碌中,时常享受所得的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, ' 我专 心 求 智慧,要看 世上 所 做 的事。(有昼 夜 不睡觉 不 合眼的。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, '我就看明 神 一切的 作为, 知道人 查 不 出 日光 之下 所 做 的事; 任凭 他 费多少力 寻查,都查不 出来,就是 智慧人 虽想 知道,也是 查不 出来。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, ' 我将 这 一切事 放 在 心上,详细考究,就知道 义人 和智慧人,并他们的作为都在 神 手中;或是 爱,或是 恨,都 在他们的前面,人 不能 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, '凡 临到众人 的事都是一样:义人 和恶人 都遭遇一样的 事;好人,洁净人 和不洁净人,献祭的 与不 献祭的,也是一样。好人如何,罪人也如何;起誓的如何,怕 起誓的 也如何。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, '在日光 之下 所 行 的一切事上 有一件 祸患,就是 众人 所遭遇的 都是一样,并且 世人 的心 充满了 恶;活著的时候 心里 狂妄,后来 就归 死人那里去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, ' 与 一切 活人 相连的,那人还有 指望,因为 活著 的狗 比 死了的 狮子 更强。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, ' 活著的人 知道 必死;死了的人 毫无 所知,也不 再 得赏赐; 他们的名 无人记念。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, ' 他们的爱, 他们的恨, 他们的嫉妒,早 都消灭了。在日光 之下 所 行 的一切事上,他们 永 不 再 有分了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, '你只管去 欢欢喜喜 吃 你的饭,心中 快乐 喝 你的酒,因为 神 已经 悦纳 你的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, '你的衣服 当 时 常 洁白,你头上 也不要 缺少 膏油。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, '在你一 生 虚空的 年日,就是 神 赐 你 在日光 之下 虚空的 年日,当同 你所 爱的 妻,快活 度日,因为 那是 你 生前 在日光 之下 劳碌 的事上所 得 的分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, '凡 你手 所 当 做 的事要尽力 去做;因为 在你 所 必去 的阴间 没有 工作,没有谋算,没有知识,也没有智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, '我又转念:见 日光 之下, 快 跑的未必 能赢;力 战 的未必 得胜; 智慧的 未必 得粮食; 明哲的 未必 得资财; 灵巧的 未必 得喜悦。 所 临到 众人 的是在乎当时 的机会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, '原来 人 也 不 知道 自己的定期。鱼 被恶 网 圈住,鸟 被网罗 捉住,祸患 忽然 临 到 的时候,世人 陷在 其中也是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, ' 我见 日光 之下 有一样 智慧,据我 看乃是 广大, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, '就是有一小 城,其中的 人 数稀少,有大 君王 来 攻击,修筑 营垒,将城 围困。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, '城中 有 一个贫穷的 智慧 人,他 用智慧 救了 那 城,却没有 人 记念 那 穷 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, '我 就说,智慧 胜 过勇力;然而那贫穷人 的智慧 被人藐视,他的话 也无人 听从。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, '宁可在安静之中 听 智慧人 的言语,不听掌管 愚昧人 的喊声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, '智慧 胜 过打仗 的兵器;但一个 罪人 能败坏 许多 善事。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, '死 苍蝇 使做香 的膏油 发出 臭气;这样,一点 愚昧 也能败坏 智慧 和尊荣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, '智慧人 的心 居右;愚昧人 的心 居左。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, '并且 愚昧人 行 路 显出无 知,对众人 说,他是 愚昧人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, '掌权者 的心 若 向你 发怒,不要 离开  你的本位,因为 柔和 能免 大 过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, '我见 日光 之下 有 一件祸患,似乎出 于  掌权 的错误, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, '就是愚昧人 立 在高位;富足人 坐 在低位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, '我见过 仆人 骑 马,王子 像仆人 在 地上 步行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, '挖 陷坑的,自己必掉 在其中;拆 墙垣的,必为蛇 所咬。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, '凿开 (或译:挪移)石头的,必受损伤;劈开  木头的,必遭危险。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, '铁器 钝了, 若 不 将刃 磨快,就必多费 气力;但得智慧 指教,便有益处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, '未 行法术以先,蛇 若 咬人,后行 法术 也是无 益。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, '智慧人 的口 说出恩 言;愚昧人 的嘴吞 灭自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, '他口 中的言语 起头 是愚昧;他话 的末尾 是奸恶 的狂妄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, '愚昧人 多有 言语,人 却不 知 将来有 什么事;他身后 的事 谁 能告诉 他呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, '凡愚昧人,他的劳碌 使自己困乏,因为 连进 城的路,他也不 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, '邦国啊,你的王 若是孩童,你的群臣 早晨 宴乐,你 就有祸了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, '邦国啊,你的王 若是贵胄 之子,你的群臣 按时 吃喝,为要补力,不 为酒醉,你就有福了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, '因人懒惰,房顶 塌下;因人手 懒,房屋 滴漏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, '设摆 筵席 是为喜笑。酒 能使人 快活;钱 能叫 万事 应心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, '你不可 咒诅 君王,也 不可心怀此念;在你卧房 也不可 咒诅 富户。因为 空中 的鸟 必传扬 这 声音,有 翅膀 的也必述说 这事。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, '当将你的粮食 撒 在 水 面,因为 日 久 必能得著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, '你要分 给 七人,或 分给八人,因为 你不 知道 将来有 什么 灾祸 临到 地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, '云 若 满了 雨,就必倾倒 在 地上。树 若 向南 倒,或 向北倒,树 倒 在何处,就存在 何处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, '看 风的,必不 撒种;望 云的,必不 收割。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, '风 从何 道来,骨头 在怀孕 妇人的胎中如何长成,你尚且 不 得知道;这样,行 万事之 神 的 作为,你更 不 得知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, '早晨 要撒 你的种,晚上 也不要 歇 你的手,因为 你不 知道 哪 一样 发旺;或是早撒的,或是晚撒的,或是 两 样 都好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, '光 本是佳美的,眼 见 日光 也是可悦的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, '人 活 多 年,就 当 快乐 多年;然而也当想到 黑暗 的日子。因为 这日子必 多,所要来的 都 是虚空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, '少年人哪,你在幼年时 当快乐。在幼年 的日子,使你的心 欢畅,行 你心 所愿 行的,看你眼 所爱看的;却要知道, 为 这 一切的事, 神 必 审问你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, '所以,你当从心中 除掉 愁烦,从肉体 克去 邪恶;因为 一生的开 端 和幼年之时,都是虚空的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, '你趁著年幼、 衰败的 日子 尚 未 来到,就是 你所说,我 毫无 喜乐 的 那些年日 未曾临近之先,当记念 造你的主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, '不要 等到 日头、光明、月亮、星宿 变为黑暗,雨 后 云彩 反回, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, ' 看守 房屋 的发颤,有力的 屈身,推磨的 稀少 就止息,从窗户 往外看 的都昏暗; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, '街 门 关闭,推磨 的响声 微小,雀鸟 一叫,人就起来,唱歌 的女子 也都 衰微。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, ' 人怕 高处,路上 有惊慌,杏树 开 花,蚱蜢 成为重担,人所愿  的也都废掉;因为 人 归 他永远的 家,吊丧的 在街上 往来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, ' 银 炼 链 𫔀 折断,金 罐 破裂,瓶子 在 泉 旁损坏,水轮 在 井口 破烂, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, '尘土 仍归 于  地, 灵 仍归 于  赐 灵的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, '传道者 说:「虚空 的虚空,凡事 都是虚空。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, '再者,传道者 因有 智慧,仍 将知识 教训 众人;又默想,又考查,又陈说 许多 箴言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, '传道者 专心 寻求 可喜悦 的言语,是凭正直 写 的诚实 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, '智慧人 的言语 好像刺棍;会中 之师 的言语又像钉稳 的钉子,都是一个 牧者 所赐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, '我儿,还有 一层,你当受劝戒:著 书 多,没有 穷尽;读书 多,身体 疲倦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, '这些事 都 已听见了,总意就是:敬畏 神,谨守 他的诫命, 这是 人所当尽的本分(或译:这是众人的本分)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, '因为 人所做的事, 连一切 隐藏的事,无论是 善 是 恶, 神 都必 审问。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, '所罗门的歌,是 歌 中的雅歌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, '愿 他用口 与我亲嘴;因 你的爱情 比酒 更美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, '你的膏油 馨 香;你的名 如同倒出来的 香膏,所以 众童女 都爱你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, '愿 你吸引我,我们就快跑 跟随你。王 带我进了 内室,我们必因你 欢喜 快乐。我们要称赞 你的爱情,胜似称赞美酒。他们爱你 是理所当然的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, '耶路撒冷 的众女子啊,我 虽然黑,却是秀美,如同基达 的帐棚,好像所罗门 的幔子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, '不要 因日头 把我 晒 黑 了就轻看我。我同母 的弟兄 向我 发怒,他们使 我看守 葡萄园;我自己的 葡萄园 却没有 看守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, '我心 所爱的啊,求你告诉 我,你在何处 牧羊?晌午 在何处 使羊歇卧?我何必 在 你同伴 的羊群 旁边 好像蒙著脸的人呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, '你这女子中 极美丽的,你 若 不 知道,只管跟随羊群 的脚踪 去,把 你的山羊羔 牧放 在 牧人 帐棚的旁边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, '我的佳偶,我将你比 法老 车上 套的骏马。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, '你的两腮 因发辫 而秀美;你的颈项 因珠串而华丽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, '我们要为你 编上 金 辫,镶上 银 钉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, '王 正 坐席的时候,我的哪哒香膏 发出 香味。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, '我以 我的良人 为一袋 没药,常在 我怀 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, '我以 我的良人 为一棵 凤仙花,在隐‧基底 葡萄园中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, ' 我的佳偶,你甚美丽! 你甚美丽!你的眼 好像鸽子眼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, ' 我的良人哪,你甚 美丽 可爱! 我们以青草 为床榻, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, '以香柏树 为房屋 的栋梁,以松树 为椽子。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, '我 是沙仑  的玫瑰花(或译:水仙花),是谷中 的百合花。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, ' 我的佳偶 在 女子中,好像百合花 在 荆棘内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, ' 我的良人 在 男子中,如同苹 𬞟果树 在树 林中。我欢欢喜喜 坐 在他的荫下,尝 他果子的滋味,觉得甘甜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, '他带我 入 筵宴所,以爱 为旗 在我以上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, '求你们给我葡萄干 增补我力,给我苹 𬞟果 畅快我心,因 我 思爱 成病。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, '他的左手 在我头 下;他的右手 将我抱住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, '耶路撒冷 的众女子啊,我指著羚羊 或 田野 的母鹿 嘱咐 你们:不要 惊动、不要 叫醒 我所亲爱的,等 他自己情愿 (不要叫醒......情愿 :或译不要激动爱情,等它自发)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, '听啊!是我良人 的声音;看哪! 他蹿 山 越 岭 而来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, '我的良人 好像 羚羊,或 像小 鹿。 他站在 我们墙壁 后,从 窗户 往里观看,从 窗棂 往里窥探。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, '我良人 对我 说:我的佳偶,我的美人,起来,与我同去! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, '因为 冬天 已往,雨水 止住 过去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, '地上 百花 开 放,百鸟鸣叫 的时候(或译:修理葡萄树的时候)已经来到;斑鸠 的声音 在我们境内 也听见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, '无花果树 的果子渐渐成熟;葡萄树 开 花 放 香。我的佳偶,我的美人,起来,与我同去! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, '我的鸽子啊,你在磐石 穴中,在陡岩 的隐密处。求你容我得见 你的面貌,得听 你的声音;因为 你的声音 柔和,你的面貌 秀美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, '要给我们 擒拿 狐狸,就是毁坏 葡萄园 的小 狐狸,因为我们的葡萄 正在开 花。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, '良人 属我,我 也属他;他在百合花中 牧放群羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, '我的良人哪,求你等到 天 起凉风、日影 飞去 的时候,你要 转回,好像 羚羊,或 像小 鹿 在 比特 山上。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, '我夜间 躺卧在 床上,寻找 我心 所爱的;我寻找他,却寻 不见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, '我说:我要起来,游行 城中,在街市上,在宽阔处,寻找 我心 所爱的。我寻找他,却寻 不见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, '城中 巡逻 看守的人 遇见我;我问他们:你们看见 我心 所爱的没有? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, '我刚 离开  他们 就 遇见 我心 所爱的。我拉住他,不 容他走, 领他 入 我母 家,到 怀我者 的内室。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, '耶路撒冷 的众女子啊,我指著羚羊 或 田野 的母鹿 嘱咐 你们:不要 惊动、不要 叫醒 我所亲爱的,等 他自己情愿 (不要叫醒......情愿 :或译不要激动爱情,等它自发)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, '那 从 旷野 上来、形状如烟 柱、以没药 和乳香 并商人 各样 香粉 薰的 是谁呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, '看哪,是所罗门 的轿; 四围 有六十个 勇士,都是以色列 中的勇士; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, '手都 持 刀,善于  争战 , 腰间 佩刀,防备夜间 有惊慌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, '所罗门 王 用黎巴嫩 木 为自己 制造 一乘华轿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, '轿柱 是用银 做的,轿底 是用金做的;坐垫 是紫色的,其中 所铺的 乃耶路撒冷 众女子 的爱情。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, '锡安 的众女子啊,你们出去 观看 所罗门 王!头戴冠冕,就是在他婚筵 的日子、心中 喜乐 的时候,他母亲 给他 戴上的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, ' 我的佳偶,你甚美丽! 你甚美丽!你的眼 在帕子 内 好像鸽子眼。你的头发 如同山羊 群 卧在 基列 山旁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, '你的牙齿 如新剪毛的 一群母羊, 洗净 上来,个个都 有双生,没有 一只丧掉子的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, '你的唇 好像一条朱红 线 缐;你的嘴 也秀美。你的两太阳 在帕子 内,如同一块 石榴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, '你的颈项 好像大卫 建造 收藏军器 的高台,其上 悬挂 一千 盾牌,都是 勇士 的籐牌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, '你的两 乳 好像百合花中 吃草的 一对 小 鹿,就是母鹿双生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, '我要往 没药 山 和 乳香 冈 去,直等到 天起凉风、日影 飞去 的时候回来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, '我的佳偶,你全然 美丽,毫无 瑕疵! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, '我的新妇,求你与我 一同离开  黎巴嫩,与我 一同离开 黎巴嫩。从亚玛拿 顶,从示尼珥 与黑门 顶,从有狮子 的洞,从有豹子 的山 往下观看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, '我妹子,我新妇,你夺了我的心。你用眼 一看,用你项上 的一条 金链,夺了我的心! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, '我妹子,我新妇,你的爱情 何其 美!你的爱情 比酒 更美!你膏油 的香气 胜过一切 香品! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, '我新妇,你的嘴唇 滴蜜,好像蜂房滴蜜;你的舌 下 有蜜,有奶。你衣服 的香气 如黎巴嫩 的香气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, '我妹子,我新妇,乃是关锁的 园,禁闭的 井,封闭的 泉源。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, '你园内 所种的 结了石榴,有 佳美的 果子,并凤仙花 与 哪哒树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, '有哪哒 和番红花,菖蒲 和桂树,并 各样 乳香 木、没药、沉香,与 一切 上等的 果品。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, '你是园中 的泉,活 水 的井,从 黎巴嫩 流下来的溪水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, '北风啊,兴起!南风啊,吹来!吹在 我的园内,使其中的香气 发出来。愿 我的良人 进入 自己园里,吃 他佳美的 果子。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, '我妹子,我新妇,我进了 我的园中,采了 我的没药 和 香料,吃了 我的蜜房 和 蜂蜜,喝了 我的酒 和 奶。我的朋友们,请吃!我所亲爱的,请喝,且多多地喝! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, '我 身睡卧,我心 却醒。这是我良人 的声音;他敲门说:我的妹子,我的佳偶,我的鸽子,我的完全人,求你给我 开 门;因我的头 满了 露水,我的头发 被夜 露滴湿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, '我回答说:我脱了 衣裳,怎能 再穿上呢?我洗了 脚,怎能 再玷污呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, '我的良人 从 门孔 里伸进 手来,我便因他 动了 心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, '我 起来,要给我良人 开 门。我的两手 滴下 没药;我的指头 有没药汁 滴在 门 闩 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, '我 给我的良人 开 了门;我的良人 却已转身 走了。他说话的时候,我神 不守舍;我寻找他,竟寻 不见;我呼叫他,他却不 回答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, '城中 巡逻 看守的人 遇见我,打了我,伤了我;看守 城墙 的人 夺 去 我的披肩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, '耶路撒冷 的众女子啊,我嘱咐 你们:若 遇见 我的良人,要告诉 他,我 因思爱 成病。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, '你这女子中 极美丽的,你的良人 比别人的良人 有何强处?你的良人 比别人的良人 有何强处,你就这样 嘱咐我们? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, '我的良人 白 而且红,超乎 万人之上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, '他的头 像至精 的金子;他的头发 厚密累垂,黑 如乌鸦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, '他的眼 如溪 水 旁 的鸽子眼,用奶 洗净,安得 合 式。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, '他的两腮 如香花 畦,如香草 台;他的嘴唇 像百合花,且滴下 没药 汁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, '他的两手 好像金 管,镶嵌 水苍玉;他的身体 如同雕刻的 象牙,周围镶嵌 蓝宝石。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, '他的腿 好像白玉石 柱,安在 精金 座 上;他的形状 如黎巴嫩,且佳美 如香柏树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, '他的口 极其甘甜;他全然 可爱。耶路撒冷 的众女子啊,这是 我的良人;这是 我的朋友。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, '你这女子中 极美丽的,你的良人 往何处 去了?你的良人 转向 何处去了,我们好与你 同去寻找他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, '我的良人 下入 自己园中,到香花 畦,在园内 牧放群羊,采 百合花。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, '我 属我的良人,我的良人 也属我;他在百合花中 牧放群羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, '我的佳偶啊,你 美丽 如得撒,秀美 如耶路撒冷,威武 如展开 旌旗的军队。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, '求你掉转 眼目 不看我,因你的眼目 使我惊乱。你的头发 如同山羊 群 卧在 基列山 旁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, '你的牙齿 如一群 母羊 洗净 上来,个个都 有双生,没有 一只丧掉子的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, '你的两太阳 在 帕子内,如同一块 石榴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, '有 六十 王后 八十 妃嫔,并有无 数 的童女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, '我的鸽子,我的完全人,只有 这一个 是 她母亲 独生的,是 生养她者 所宝爱的。众女子 见了 就称她有福;王后 妃嫔 见了也赞美她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, '那 向外观看、如 晨光发现、美丽 如月亮、皎洁 如日头、威武 如展开 旌旗军队的 是谁呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, '我下 入 核桃 园,要看 谷中 青绿的植物,要看 葡萄 发芽没有,石榴 开 花没有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, '不 知不觉,我的心 将我安置在 我尊长 的车中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, '回来,回来,书拉密女;你回来,你回来,使我们得观看 你。你们为何 要观看 书拉密女,像观看玛哈念 跳舞的呢?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, '王 女啊,你的脚 在鞋中 何其 美好!你的大腿 圆润,好像 美玉,是巧匠 的手 做成的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, '你的肚脐 如圆 杯,不 缺 调和的酒;你的腰 如一堆 麦子,周围 有百合花。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, '你的两 乳 好像一对 小鹿,就是母鹿 双生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, '你的颈项 如象牙 台;你的眼目 像希实本、巴特‧拉并 门 旁 的水池;你的鼻子 仿佛朝 大马士革 的黎巴嫩 塔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, '你的头 在你身上 好像迦密山;你头上 的发 是紫黑色;王 的心因这下垂的发绺 系住了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, '我所爱的,你何其 美好!何其 可悦,使人欢畅喜乐! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, '你的 身量 好像 棕树;你的两乳如同其上的果子,累累下垂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, '我说:我要上 这棕树,抓住 枝子。愿  你的两乳 好像葡萄 累累下垂,你鼻子 的气味 香如苹 𬞟果; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, '你的口 如上好的 酒。女子说:为我的良人 下咽 舒畅,流入 睡觉人 的嘴中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, '我 属我的良人,他也恋慕 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, '我的良人,来吧!你我可以往 田间 去;你我可以在村庄 住宿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, '我们早晨起来 往葡萄园去,看看 葡萄 发芽 开 花 没有,石榴 放蕊没有;我在那里 要将 我的爱情 给 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, '风茄 放 香,在 我们的门内 有各样 新 陈 佳美的果子;我的良人,这都是我为你 存留的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, '巴不得 你像我的 兄弟,像吃 我母亲 奶的兄弟;我在外头 遇见你 就与你亲嘴,谁也 不 轻看 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, '我必引导你,领你 进 我母亲 的家;我可以领受教训,也就使你喝 石榴 汁 酿的香 酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, '他的左手 必在我头 下;他的右手 必将我抱住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, '耶路撒冷 的众女子啊,我嘱咐 你们:不要 惊动、不要 叫醒 我所亲爱的,等 他自己情愿 (不要叫醒......情愿 :或译不要激动爱情,等它自发)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, '那 靠著 良人 从 旷野 上来的 是谁呢?我在苹 𬞟果树 下 叫醒你。你母亲 在那里 为你劬劳;生养你的 在那里 为你劬劳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, '求你将我放在 你心 上 如印记,带在你臂 上 如戳记。因为 爱情 如死 之坚强,嫉恨 如阴间 之残忍;所发的电光 是火焰 的电光,是耶和华的烈焰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, ' 爱情,众 水 不 能 息灭,大水 也不能 淹没。若 有人 拿 家中 所有的 财宝 要换爱情,就全 被藐视。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, '我们 有一小 妹;她的 两乳 尚未 长成,人来提亲 的日子,我们当为她 怎样 办理? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, '她 若是 墙,我们要在其上 建造 银 塔;她 若是 门,我们要用香柏木 板 围护 她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, '我 是墙;我两乳 像其上的楼。那时,我在他眼中 像 得 平安的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, '所罗门在巴力‧哈们 有 一葡萄园;他将 这葡萄园 交 给看守的人,为其中的果子 必 交 一千 舍客勒银子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, '我自己 的葡萄园 在我面前。所罗门哪,一千 舍客勒归你,二百 舍客勒归看守 果子的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, '你这住 在园中的,同伴 都要听 你的声音,求你使我也得听见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, '我的良人哪,求你快来!如 羚羊 或 小 鹿 在 香草 山上。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, '当乌西雅、约坦、亚哈斯、希西家 作犹大 王 的时候,亚摩斯 的儿子 以赛亚 得 默示,论到 犹大 和耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, '天哪,要听!地啊,侧耳而听!因为 耶和华 说:我养育 儿女,将他们养大,他们 竟悖逆 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, '牛 认识 主人,驴 认识主人 的槽,以色列 却不 认识;我的民 却不 留意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, '嗐!犯罪的 国民,担著 罪孽 的百姓;行恶的 种类,败坏的 儿女!他们离弃 耶和华,藐视 以色列 的圣者,与他生疏,往后退步。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, '你们为 什么 屡次 悖逆,还要 受责打吗?你们已经满 头 疼痛,全 心 发昏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, '从脚 掌 到 头顶,没有一处 完全的,尽是伤口、青肿,与新打的 伤痕,都没有 收口,没有 缠裹,也没有 用膏 滋润。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, '你们的地土 已经荒凉;你们的城邑 被火 焚毁。你们的田地 在你们眼前 为外邦人 所侵吞,既被外邦人 倾覆 复 就成为荒凉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, '仅存 锡安城(原文是女子),好像葡萄园 的草棚,瓜田 的茅屋,被围困的 城邑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, '若不是 万军 之耶和华 给我们 稍 留 余 馀种,我们早已 像 所多玛、蛾摩拉的样子了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, '你们这所多玛 的官长啊,要听 耶和华 的话!你们这蛾摩拉 的百姓啊,要侧耳听我们 神 的训诲! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, '耶和华 说:你们所献的许多 祭物 与我 何益呢?公绵羊 的燔祭 和肥畜 的脂油,我已经够了;公牛 的血,羊羔的血,公山羊的血,我都不 喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, ' 你们来 朝见 我,谁 向你们 讨 这些,使你们践踏 我的院宇呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, '你们不要 再 献 虚浮的 供物。香品 是 我 所憎恶的;月朔 和安息日,并宣召的 大会,也是我所憎恶的;作罪孽,又守严肃会,我也不能 容忍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, '你们的月朔 和节期,我心 里恨恶,我 都以为 麻烦;我担当,便不耐烦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, '你们举 手祷告,我必遮 眼不看;就是 你们多多地 祈祷,我也不 听。你们的手 都满了 杀人的血。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, '你们要洗濯、自洁,从我眼 前 除掉 你们的恶 行,要止住 作恶, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, '学习 行善,寻求 公平,解救 受欺压的;给孤儿 伸冤,为寡妇 辨屈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, '耶和华 说: 你们来,我们彼此辩论。你们的罪 虽 像朱红,必变成雪 白;虽 红 如丹颜,必 白如羊毛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, '你们若 甘心 听从,必吃 地 上的美物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, '若 不听从,反倒悖逆,必被刀剑 吞灭。这是 耶和华 亲口 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, '可叹,忠信的 城 变 为妓女!从前充满了 公平,公义 居 在其中,现今 却有凶手居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, '你的银子 变 为渣滓;你的酒 用水 搀对。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, '你的官长 居心悖逆,与盗贼 作伴,各都 喜爱 贿赂,追求 赃私。他们不 为孤儿 伸冤;寡妇 的案件 也不 得呈到 他们面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, '因此,主─万军 之耶和华、以色列 的大能者 说:哎!我要向我的对头 雪恨,向我的敌人 报仇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, '我必反 手 加在你身上,炼 尽 你的渣滓,除 净 你的杂质。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, '我也必复还 你的审判官,像起初一样,复还你的谋士,像起先一般。然后,你 必称为 公义 之城,忠信 之邑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, '锡安 必因公平 得蒙救赎;其中归正的人 必因公义得蒙救赎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, '但悖逆的 和犯罪的 必一同 败亡;离弃 耶和华 的必致消灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, '那等人必 因你们所 喜爱的 橡树 抱愧;你们必因所 选择的 园子 蒙羞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, '因为,你们必 如叶子 枯干的 橡树,好像 无 水浇灌的 园子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, '有权势的 必 如麻瓤;他的工作 好像火星,都要 一同 焚毁,无人 扑灭。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, '亚摩斯 的儿子 以赛亚 得 默示, 论到 犹大 和耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, ' 末后的 日子,耶和华 殿 的山 必 坚立,超乎 诸山,高举 过于 万岭;万 民 都要流 归这山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, '必有许多 国的民 前往,说:来吧,我们登 耶和华 的山,奔 雅各 神 的殿。主必将他的道 教训我们;我们也要行 他的路。因为 训诲 必 出 于 锡安;耶和华 的言语 必出于 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, '他必在列国 中 施行审判,为许多 国民 断定是非。他们要将刀 打成 犁头,把枪 打成镰刀。这国 不 举 刀 攻击 那国;他们也不 再 学习 战 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, '雅各 家啊,来吧!我们在耶和华 的光明中 行走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, '耶和华, 你离弃了 你百姓 雅各 家,是因 他们充满了 东方的风俗,作观兆的,像非利士人一样,并与外邦 人 击掌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, '他们的国 满了 金 银,财宝 也无 穷;他们的地 满了 马匹,车辆 也无 数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, '他们的地 满了 偶像;他们跪拜 自己手 所造的,就是自己指头 所 做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, '卑贱人 屈膝;尊贵人 下跪;所以不可 饶恕 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, '你当进 入岩穴,藏 在土中,躲避 耶和华 的惊吓 和他威严 的荣光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, '到那 日,眼目 高傲的 必降为卑;性情狂傲 的都必屈膝;惟独 耶和华 被尊崇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, '必有 万军 耶和华 降罚的一个日子,要临到 骄傲 狂妄的; 一切 自高的 都必降为卑; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, '又临到 黎巴嫩 高大的 香柏树 和 巴珊 的橡树; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, '又临到 一切 高 山的 峻 岭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, '又临到 高 台 和 坚固 城墙; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, '又临到 他施 的船只 并 一切 可爱 的美物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, '骄傲的 必屈膝;狂妄的 必降卑。在那 日,惟独 耶和华 被尊崇; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, '偶像 必全然 废弃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, '耶和华 兴起,使地 大震动的时候,人就进 入石 洞,进入土 穴,躲避 耶和华 的惊吓 和他威严 的荣光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, '到那 日,人 必将为拜 而 造的 金 偶像、 银 偶像 抛 给田鼠 和蝙蝠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, '到耶和华 兴起,使地 大震动的时候,人好进 入磐石 洞中 和岩石 穴里,躲避 耶和华 的惊吓 和他威严 的荣光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, '你们 休要 倚靠 世人。他 鼻孔里 不过 有气息;他 在一切事上可算 什么呢?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, ' 主─万军 之耶和华 从耶路撒冷 和犹大,除掉 众人所倚靠的,所仗赖的,就是所倚靠的 粮,所仗赖 的 水; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, '除掉勇士 和战 士,审判官 和先知,占卜的 和长老, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, '五十 夫长 和尊贵 人,谋士 和有巧艺的,以及妙行法术的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, '主说:我必使 孩童 作他们的首领,使婴孩 辖管 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, '百姓 要彼此 欺压;各人 受邻舍的欺压。少年人 必侮慢 老年人;卑贱人 必侮慢尊贵人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, ' 人 在父 家 拉住 弟兄,说:你有 衣服,可以作 我们的 官长。这 败落的事 归在你手 下吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, '那 时,他必扬声 说:我不 作 医治你们的人;因我家中 没有 粮食,也没有 衣服,你们不可 立我作 百姓 的官长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, ' 耶路撒冷 败落,犹大 倾倒;因为 他们的舌头 和行为 与 耶和华反对,惹了 他荣光 的眼目。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, '他们的面 色 证明 自己的不正;他们述说 自己的罪恶,并不 隐瞒,好像所多玛一样。他们 有祸了!因为 作恶 自 害。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, '你们要论义人 说: 他必享福乐,因为 要吃 自己行为 所结的果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, '恶人 有祸了!他必遭灾难!因为 要照自己 手 所行的受 报应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, '至于 我的百姓,孩童 欺压他们,妇女 辖管 他们。我的百姓啊,引导你的 使你走错,并毁坏 你所行的 道路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, '耶和华 起来 辩论,站著 审判 众民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, '耶和华 必 审问 他民中 的长老 和首领,说:吃尽 葡萄园 果子的就是你们;向贫穷 人所夺的 都在你们家中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, '主─万军 之耶和华 说:你们为何 压制 我的百姓,搓磨 贫穷人 的脸呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, '耶和华 又说:因为 锡安 的女子 狂傲,行走 挺 项,卖弄 眼目,俏步 徐行,脚下 玎珰, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, '所以,主 必使 锡安 的女子 头 长秃疮;耶和华 又使她们赤露 下体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, '到 那日,主 必除掉 她们华美 的脚钏、发网、月牙圈、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, '耳环、手镯、蒙脸的帕子、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, '华冠、足炼 链 𫔀、华带、香 盒、符囊、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, '戒指、鼻 环、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, '吉服、外套、云肩、荷包、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, '手镜、细麻衣、裹头巾、蒙身的帕子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, '必有 臭烂 代替 馨香, 绳子 代替 腰带,光秃 代替 美 发,麻衣 系腰 代替 华服,烙伤 代替 美容。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, '你的男丁 必倒 在刀下;你的勇士 必死在阵上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, '锡安(原文是她)的城门 必悲伤、哀号;她必荒凉 坐 在地上。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, '在那 日,七个 女人 必拉住 一个 男人,说:「我们吃 自己的食物,穿 自己的衣服,但 求你许我们 归 你名下;求你除掉 我们的羞耻。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, '到那 日,耶和华 发生的苗 必 华美 尊荣,地 的出产 必为以色列 逃脱的人 显为荣华 茂盛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, ' 主 以公义 的灵 和焚烧 的灵,将 锡安 女子 的污秽 洗去,又将 耶路撒冷 中 杀人的血 除净。那时,剩 在锡安、留 在耶路撒冷的,就是一切 住耶路撒冷、在生命 册上记名的,必称为 圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, '耶和华 也必 在 锡安 全 山,并 各会众以上,使白日 有烟 云,黑夜 有火焰 的光。因为 在 全 荣耀 之上必有遮蔽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, '必有 亭子,白日 可以得荫 避暑,也可以作为藏身之处,躲避 狂风 暴雨。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, '我要 为我所亲爱的 唱歌,是我所爱者 的歌,论他葡萄园的事:我所亲爱的 有 葡萄园 在肥美的 山冈上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, '他刨挖园子,捡去石头,栽种 上等的葡萄树,在园中 盖了 一座楼,又 凿出 压酒池;指望 结 好葡萄,反倒结了 野葡萄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, ' 耶路撒冷 的居民 和犹大 人哪,请你们 现今在我 与我的葡萄园 中,断定是非。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, '我为 我葡萄园 所做 之外,还有 什么 可做的呢?我指望 结 好葡萄,怎么 倒结了 野葡萄呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, '现在 我告诉 你们, 我 要向我葡萄园 怎样 行:我必撤去 篱笆,使它 被吞灭,拆毁 墙垣,使它 被践踏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, '我必使 它荒废,不再 修理,不再 锄刨,荆棘 蒺藜 倒要生长。我也必命 云 不降 雨 在其上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, '万军 之耶和华 的葡萄园 就是 以色列 家;他所喜爱的 树 就是犹大 人。他指望的 是公平,谁知倒有暴虐(或译:倒流人血);指望的是公义, 谁知倒有冤声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, '祸哉!那些以房 接 房,以地 连 地,以致 不留 余 馀地的,只顾自己独 居 境 内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, '我耳闻 万军 之耶和华说:必有 许多 又大 又美 的房屋 成为 荒凉,无人 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, ' 三十 亩 葡萄园 只出 一 罢特酒;一贺梅珥 谷种 只结 一伊法粮食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, '祸哉!那些清早 起来 追求 浓酒,留连 到夜深,甚至因酒 发烧的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, '他们在 筵席 上弹琴,鼓瑟,击鼓,吹笛,饮酒,却不 顾念 耶和华 的作为,也不 留心 他手 所做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, '所以,我的百姓 因无 知 就被掳去;他们的尊贵 人 甚是饥饿,群众 极其干渴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, '故此,阴间 扩张 其欲,开 了 无 限量 的口;他们的荣耀、群众、繁华,并快乐的人 都落 在其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, '卑贱人 被压服;尊贵人 降为卑;眼目 高傲的人 也降为卑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, '惟有万军 之耶和华 因公平 而崇高;圣者 神 因公义 显为圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, '那时,羊羔 必来吃草,如同在自己的草场;丰肥人 的荒场 被游行的人 吃尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, '祸哉!那些以虚假 之细绳 牵 罪孽的人!他们又像以套 绳 拉罪恶, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, '说:任他急速行,赶快 成就他的作为,使 我们看看;任以色列 圣者 所谋划 㓰的 临近 成就,使我们知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, '祸哉!那些称 恶 为善,称善 为恶,以 暗 为光,以光 为暗,以 苦 为甜,以甜 为苦的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, '祸哉!那些自以为 有智慧,自看 为通达的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, '祸哉!那些勇于  饮 酒,以能力 调 浓酒 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, '他们因 受贿赂,就称恶人 为义,将义人 的义 夺去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, ' 火 苗 怎样吞灭 碎秸,干草 怎样落在 火焰之中,照样,他们的根 必像朽物,他们的花 必 像灰尘 飞腾;因为 他们厌弃 万军 之耶和华 的训诲,藐视 以色列 圣者 的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, '所以,耶和华 的怒气 向他的百姓 发作。他的手 伸出 攻击他们,山岭 就震动; 他们的尸首 在 街市 上好像粪土。虽然 如此,他的怒气 还未 转消;他的手 仍 伸不缩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, '他必竖立 大旗,招远方的 国民,发嘶声 叫他们 从地 极而来;看哪,他们必急速 奔来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, '其中 没有 疲倦的, 绊跌的;没有 打盹的, 睡觉的;腰 带 并不 放松,鞋 带 也不 折断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, '他们的 箭 快利, 弓 也上了弦。马蹄 算 如坚石,车轮 好像旋风。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, '他们要吼叫,像母狮子,咆哮,像少壮狮子;他们要咆哮 抓 食,坦然叼去,无人 救回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, '那 日,他们要向 以色列人吼叫,像海浪 匉訇;人若望 地,只见 黑暗 艰难,光明 在云中 变为昏暗。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, '当乌西雅 王 崩 的那年,我见 主 坐 在 高 高 的宝座上。他的衣裳垂下,遮满 圣殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, '其上 有撒拉弗 侍立,各 有六个 翅膀:用两个 翅膀遮 脸,两个 翅膀遮 脚,两个 翅膀飞翔; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, '彼此 呼喊 说:圣哉!圣哉!圣哉!万军 之耶和华;他的荣光 充满 全 地! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, '因呼喊者 的声音,门槛 的根基 震动,殿 充满了 烟云。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, '那时我说:「祸哉! 我 灭亡了!因为 我 是嘴唇 不洁 的人, 又住 在嘴唇 不洁 的民 中,又因 我眼 见 大君王─万军 之耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, '有一 撒拉弗 飞 到我跟前,手里 拿著红炭,是用火剪 从 坛 上取下来的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, '将炭沾 我的口,说:「看哪,这 炭沾了 你的嘴,你的罪孽 便除掉,你的罪恶 就赦免了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, '我又听见 主 的声音 说:「我可以差遣 谁呢?谁 肯为我们 去呢?」我说:「我在这里,请差遣我!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, '他说:「你去 告诉 这 百姓说:你们听 是要听见,却不 明白;看 是要看见,却不 晓得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, '要使这 百姓 心 蒙脂油,耳朵 发沉,眼睛 昏迷;恐怕 眼睛 看见,耳朵 听见,心里 明白,回转过来,便得医治。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, '我就说:「主啊,这到 几时为止呢?」他说:直到 城邑 荒凉,无人 居住,房屋 空闲 无 人,地土 极其 荒凉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, '并且耶和华 将 人 迁到远方,在这境 内 撇下的 地土很多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, '境内 剩下的人 若还有 十分之一,也必 被吞灭,像栗树、橡树 虽被砍伐,树墩子却仍存留。这圣洁 的种类 在国中 也是如此。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, ' 乌西雅 的孙子、约坦 的儿子、犹大 王 亚哈斯 在位的时候,亚兰 王 利汛 和利玛利 的儿子、以色列 王 比加 上来 攻打 耶路撒冷,却不 能 攻取。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, '有人告诉 大卫 家 说:「亚兰 与 以法莲 已经同盟。」王的心 和百姓 的心 就都跳动,好像林中 的树 被 风 吹动一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, '耶和华 对 以赛亚 说:「你 和你的儿子 施亚雅述 出去,到 上 池 的水沟 头,在 漂布 地 的大路上,去迎接 亚哈斯, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, '对他 说:『你要谨慎 安静,不要 因亚兰 王利汛 和利玛利 的儿子 这 两个 冒烟的 火把 头 所发的烈 怒 害怕,也不要 心里 胆怯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, '因为 亚兰 和以法莲,并利玛利 的儿子,设 恶谋 害你, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, '说:我们 可以上去 攻击犹大,扰乱它,攻破它,在其中 立 他比勒 的儿子 为王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, '所以主 耶和华 如此 说:这所谋的必立 不住,也不得 成就。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, '原来 亚兰 的首城 是大马士革;大马士革 的首领 是利汛。(六十 五 年 之内,以法莲 必然破坏,不再成为国民。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, '以法莲 的首城 是撒马利亚;撒马利亚 的首领 是利玛利 的儿子。你们若是 不 信,定然 不得 立稳。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, '耶和华 又 晓谕 亚哈斯 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, '「你 向 耶和华─你的 神 求 一个兆头:或求 显在深处,或 求显在高处。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, '亚哈斯 说:「我不 求;我不 试探 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, '以赛亚说:「大卫 家啊,你们当 听!你们 使人 厌烦 岂算 小事,还要 使我的 神 厌烦吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, '因此,主 自己 要给 你们 一个兆头, 必有童女 怀孕 生 子,给他起名 叫 以马内利(就是 神与我们同在的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, '到他晓得 弃 恶 择 善的时候,他必吃 奶油 与蜂蜜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, '因为 在这孩子 还不晓得 弃 恶 择 善 之先,你 所 憎恶的 那二 王 之地 必致见弃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, '耶和华 必使 亚述 王 攻击你的日子临 到你 和 你的百姓,并 你的父 家,自从 以法莲 离开  犹大以来,未曾 有 这样的 日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, '「 那 时,耶和华 要发嘶声,使埃及 江河 源头 的 苍蝇 和亚述 地 的 蜂子飞来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, '都 必飞来,落 在荒凉的 谷内、磐石 的穴里,和一切 荆棘篱笆中,并一切的 草场上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, '「那 时,主 必用大河 外 赁 的剃头刀,就是亚述 王,剃去 头发 和脚上 的毛,并要 剃净 胡须。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, '「 那 时,一个人 要养活 一只母牛犊,两只 母绵羊; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, ' 因为出的 奶 多,他就得吃 奶油, 在境 内 所剩的 人都 要吃 奶油 与蜂蜜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, '「从前, 凡 种一千 棵葡萄树、值银一千 舍客勒 的地方,到 那 时 必 长荆棘 和蒺藜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, '人上那里 去,必带弓 箭,因为 遍 地 满了 荆棘 和蒺藜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, '所有 用锄刨 挖 的 山地,你因怕 荆棘 和蒺藜,不敢 上那里 去;只可成了 放 牛之处,为羊 践踏之地。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, '耶和华 对我 说:「你 取 一个大 牌,拿人 所用的笔(或译:人常用的字),写 上『玛黑珥‧沙拉勒‧哈施‧罢斯』(就是掳掠速临、抢夺快到的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, '我要 用诚实的 见证人, 祭司 乌利亚 和 耶比利家 的儿子 撒迦利亚 记录这事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, '我─以赛亚与妻子(原文是女先知)同室;她怀孕 生 子,耶和华 就对我 说:「给他起名 叫玛黑珥‧沙拉勒‧哈施‧罢斯; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, '因为 在这小孩子 不晓得 叫 父 叫母 之先, 大马士革 的财宝 和 撒马利亚 的掳物 必在亚述 王 面前 搬了去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, '耶和华 又 晓谕 我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, '「这 百姓 既 厌弃 西罗亚 缓 流 的水,喜悦 利汛 和利玛利 的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, '因此, 主 必使 大 河 翻腾的水 猛然 冲来,就是 亚述 王 和 他所有的 威势,必漫 过 一切的 水道,涨 过 两 岸; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, '必冲入 犹大,涨溢 泛滥, 直到 颈项。以马内利啊, 他展开  翅膀,遍满 你的地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, '列国的人民哪,任凭你们喧嚷,终必破坏;远 方 的众人哪,当侧耳而听!任凭你们束起腰来,终必破坏;你们束起腰来,终必破坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, '任凭你们 同谋,终归无有;任凭你们言定,终不 成立;因为 神 与我们同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, ' 耶和华 以大能 的手,指教我 不可行 这 百姓 所行的道,对我这样 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, '「这 百姓 说 同谋背叛,你们不要 说 同谋背叛。 他们所怕的,你们不要 怕,也不要 畏惧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, '但要尊 万军 之耶和华 为圣,以他为 你们所当怕的, 所当畏惧的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, '他必作 为圣所,却向以色列 两 家 作绊脚的 石头,跌人的 磐石;向耶路撒冷 的居民 作为圈套 和网罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, '许多人 必在其上 绊脚 跌倒,而且跌碎,并陷入网罗,被缠住。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, '你要卷起 律法书,在我门徒中间 封住 训诲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, '我要等候 那掩 面 不顾雅各 家 的耶和华;我也要仰望 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, '看哪,我 与耶和华 所 给 我 的儿女,就是从 住 在锡安 山 万军 之耶和华来的,在以色列中 作为预兆 和奇迹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, ' 有人对你们 说:「当求问 那些交鬼的 和 行巫术的,就是声音绵蛮,言语微细的。」你们便回答说:「百姓 不当 求问自己的 神吗?岂可为 活人求问 死人呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, '人当以训诲 和法度为标准;他们所说的,若 不 与此相符, 必不 得见晨光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, '他们必经过 这地,受艰难,受饥饿;饥饿 的时候,心中焦躁,咒骂 自己的君王和自己的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, '仰观 上天,俯察 下地,不料,尽是艰难、黑暗,和幽暗 的痛苦。他们必被赶入 乌黑的黑暗中去。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, '但 那 受过痛苦的 必不 再见幽暗。从前 神使西布伦 地 和拿弗他利 地 被藐视,末后 却使这沿海 的路,约旦河 外,外邦人 的加利利地 得著荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, '在黑暗中 行走的 百姓 看见了 大 光;住 在死荫 之地 的人有光 照耀 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, '你使这国民 繁多,加增 他们的喜乐;他们在你面前 欢喜,好像收割 的欢喜,像 人分 掳物 那样的快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, '因为 他们所负的 重轭 和 肩头 上的杖,并欺压 他们人的棍,你都已经折断,好像在米甸 的日子一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, ' 战 士 在乱杀之间所穿戴的 盔甲,并那滚 在血中 的衣服,都必 作为可烧的,当作火柴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, '因 有一婴孩 为我们 而生;有一子 赐 给我们。政权 必 担在 他的肩头上;他名 称为「奇妙 策士、全能的 神、永在 的父、和平 的君」。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, '他的政权 与平安 必加增 无 穷。他必在 大卫 的宝座 上治理 他的国,以公平 公义 使国 坚定稳固,从今 直到 永远。万军 之耶和华 的热心 必成就 这事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, '主 使 一言 入于 雅各家,落 于 以色列家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, '这众 百姓,就是以法莲 和撒马利亚 的居民,都要知道;他们凭骄傲 自大 的心 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, '砖墙 塌了,我们却要凿石头 建筑;桑树 砍了,我们却要换 香柏树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, '因此,耶和华 要高举 利汛 的敌人 来攻击以色列,并要激动 以色列的仇敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, '东有 亚兰人,西有 非利士人;他们张 口 要吞吃 以色列。虽然如此,耶和华的怒气 还未 转消;他的手 仍 伸不缩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, '这百姓 还没有 归 向 击打他们的主,也没有 寻求 万军 之耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, '因此,耶和华 一 日 之间必从以色列 中剪除 头 与尾,棕枝 与芦苇─ ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, '长老 和尊贵人 就是 头,以谎言 教 人的先知 就是 尾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, '因为,引导 这 百姓 的使他们走错了路;被引导的 都必 败亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, '所以,主 必不 喜悦 他们的少年人,也不 怜恤 他们的孤儿 寡妇;因为,各人 是亵渎的,是行恶的,并且各人 的口 都说 愚妄的话。虽然 如此,耶和华 的怒气 还未 转消;他的手 仍 伸不缩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, ' 邪恶 像火 焚烧,烧灭 荆棘 和蒺藜,在稠密 的树林 中著起来,就成为烟柱,旋转 上腾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, '因万军 之耶和华 的烈怒,地 都烧遍;百姓 成为 火 柴;无 人 怜爱 弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, '有人 右边 抢夺,仍受饥饿, 左边 吞吃,仍不 饱足;各人 吃 自己膀臂 上的肉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, '玛拿西吞吃(或译:攻击;下同) 以法莲;以法莲吞吃 玛拿西,又 一同 攻击 犹大。虽然 如此,耶和华的怒气 还未 转消;他的手 仍 伸不缩。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, '祸哉!那些设立 不义 之律例 的和记录 奸诈 之判语的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, '为要屈 枉 穷乏人,夺去 我民中 困苦人 的理,以寡妇 当作 掳物,以 孤儿 当作掠物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, '到降罚 的日子,有灾祸 从远方 临到,那时,你们怎样 行呢?你们向 谁 逃奔 求救呢?你们的荣耀(或译:财宝)存留 何处呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, '他们只得 屈身 在被掳的人 以下,仆倒 在被杀的人 以下。虽然 如此,耶和华 的怒气 还未 转消;他的手 仍 伸不缩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, ' 亚述 是我怒气 的棍, 手中 拿我恼恨 的杖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, '我要打发他 攻击亵渎的 国民,吩咐他 攻击 我所恼怒 的百姓,抢 财为掳物,夺 货为掠物,将他们 践踏,像街上 的泥土一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, '然而,他 不是 这样 的意思;他心 也不 这样 打算。他心里 倒 想毁灭,剪除 不 少的 国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, ' 他说:我的臣仆 岂不 都是 王吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, '迦勒挪 岂不 像迦基米施吗?哈马 岂 不 像亚珥拔吗?撒马利亚 岂 不 像大马士革吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, ' 我手 已经搆到 有偶像 的国;这些国雕刻的偶像 过于 耶路撒冷 和撒马利亚的偶像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, '我怎样 待 撒马利亚 和其中的偶像,岂不 照样 待 耶路撒冷 和其中的偶像吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, ' 主 在锡安 山 和耶路撒冷 成就 他一切 工作 的时候,主说:「我必罚 亚述 王 自大 的心 和 他高傲 眼目 的荣耀。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, '因为 他说:我所成就的 事是靠我手 的能力 和我的智慧,我本 有聪明。我挪移 列国 的地界,抢夺 他们所积蓄的财宝;并且我像勇士,使坐宝座的 降为卑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, '我的手 搆到 列国 的财宝,好像人搆到鸟窝;我 也得了 全 地,好像人拾起 所弃的 雀蛋。没有 动 翅膀的;没有张 嘴的,也没有鸣叫的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, '斧 岂可向 用斧 砍木的 自夸呢?锯 岂可 向 用锯的 自大呢?好比棍 抡起 那举棍的,好比杖 举起 那非 木的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, '因此,主─万军 之耶和华 必使 亚述王的肥壮人 变为瘦弱,在他的荣华 之下 必有火 著起, 如同焚烧一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, '以色列 的光 必 如火;他的圣者 必如火焰。在一 日之间,将亚述王的荆棘 和蒺藜 焚烧 净尽; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, '又将他树林 和肥田 的荣耀 全然 烧尽,好像 拿军旗的 昏过去一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, '他林中 剩下的 树 必 稀少,就是孩子 也能写其数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, '到 那 日,以色列 所剩下的 和雅各 家 所逃脱的,不 再 倚靠 那击打他们的,却要诚实 倚靠 耶和华─以色列 的圣者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, '所剩下的,就是雅各 家所剩下的,必归 回 全能的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, ' 以色列啊,你的百姓 虽多 如海 沙,惟有剩下的 归回。原来灭绝的事 已定,必有公义施行,如水涨溢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, '因为 主─万军 之耶和华 在全 地 之中 必成就 所定规 的结局。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, '所以,主─万军 之耶和华 如此 说:「住 锡安 我的百姓啊,亚述 王虽然用棍 击打你,又照埃及 的样子 举 杖 攻击你,你却不要 怕他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, '因为 还有 一点 点时候,向你们发的忿恨 就要完毕,我的怒气 要向他发作,使他灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, '万军 之耶和华 要兴起 鞭 来攻击他,好像在俄立 磐石 那里杀戮 米甸人一样。耶和华的杖 要向 海伸出,把杖举起,像在埃及 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, '到 那 日,亚述王的重担 必离开  你的肩头;他的轭 必离开  你的颈项;那轭 也必因 肥壮 的缘故撑断(或译:因膏油的缘故毁坏)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, '亚述王来 到 亚叶,经过 米矶仑 ,在密抹安 放 辎重。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, '他们过了 隘口,在迦巴 住宿。拉玛人 战 兢;扫罗 的基比亚 人逃跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, '迦琳的居民(原文是女子)哪,要高 声呼喊!莱煞人哪,须听!哀哉!困苦的 亚拿突啊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, '玛得米那 人躲避;基柄 的居民 逃遁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, '当 那日,亚述王要在挪伯 歇兵,向锡安 女子 的山─就是耶路撒冷 的山─抡 手攻他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, '看哪,主─万军 之耶和华 以惊吓 削去 树枝;长 高的 必被砍下,高大的 必被伐倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, '稠密 的树林,他要用铁器 砍下;黎巴嫩 的树木必被大能者 伐倒。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, '从耶西 的本(原文是丕)必发 一条;从他根 生的枝子 必结果实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, '耶和华 的灵 必住 在他身上,就是使他有智慧 和聪明 的灵,谋略 和能力 的灵,知识 和敬畏 耶和华 的灵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, '他必以敬畏 耶和华 为乐;行审判 不 凭眼 见,断是非 也不凭 耳 闻; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, '却要以公义 审判 贫穷人,以正直 判断 世上 的谦卑人,以口中 的杖 击打 世界,以嘴里 的气 杀戮 恶人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, '公义 必当 他的腰 带;信实 必当他胁下 的带子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, '豺狼 必与 绵羊羔 同居,豹子 与 山羊羔 同卧;少壮狮子 与牛犊 并肥畜 同群;小 孩子 要牵引 牠们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, '牛 必与熊 同食;牛犊 必与小熊同 卧;狮子 必吃 草,与牛一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, '吃奶的 孩子必玩耍 在 虺蛇 的洞口;断奶的 婴儿必按 手 在 毒蛇 的穴上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, '在 我圣 山的遍处,这一切都不 伤人,不 害物;因为认识 耶和华 的知识 要充满 遍地,好像水 充满 洋海一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, '到 那 日,耶西 的根 立 作万民 的大旗;外邦人 必寻求 他,他安息之所 大有 荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, '当 那 日,主 必 二次 伸手 救回 自己百姓 中所 余 馀剩的,就是在亚述、埃及、巴忒罗、古实、以拦、示拿、哈马,并众海 岛 所剩下的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, '他必向列国 竖立 大旗,招回 以色列 被赶散的人,又从地 的四 方 聚集 分散的 犹大人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, '以法莲 的嫉妒 就必消散;扰害 犹大 的必被剪除。以法莲 必不 嫉妒 犹大,犹大 也不 扰害 以法莲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, '他们要向西 飞,扑在非利士人 的肩头上(肩头上:或译西界),一同 掳掠 东方 人,伸 手 按住以东 和摩押;亚扪 人 也必顺服他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, '耶和华 必使 埃及 海 汊 枯干,抡 手 用暴热的 风使 大河 分为 七 条,令人过去 不致湿脚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, '为主余 馀剩的 百姓,就是 从亚述 剩下回来的,必有 一条大道,如 当日 以色列 从埃及 地 上来一样。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, '到那 日,你必说:耶和华啊,我要称谢你!因为 你虽然向我 发怒,你的怒气 却已转消;你又安慰了我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, '看哪! 神 是我的拯救;我要倚靠他,并不 惧怕。因为 主 耶和华 是我的力量,是我的诗歌,他也成了 我的 拯救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, '所以,你们必从救恩 的泉源 欢然 取 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, '在那 日,你们要说:当称谢 耶和华,求告 他的名;将他所行的 传扬 在万民中,提说 他的名 已被尊崇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, '你们要向耶和华 唱歌,因 他所行的 甚是美好;但愿 这事 普传 天下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, '锡安 的居民哪,当扬声 欢呼,因为 在你们中间的 以色列 圣者 乃为至大。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, '亚摩斯 的儿子 以赛亚 得 默示,论 巴比伦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, '应当在 净光的 山 竖立 大旗,向群众 扬 声 招 手,使他们进入 贵胄 的门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, '我 吩咐 我所挑出来的人; 我招呼 我的勇士─就是那矜夸 高傲之辈,为要成就我怒中所定的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, '山间 有多 人的声音,好像 是大 国人民。有许多国 的民 聚集 哄嚷的 声音;这是万军 之耶和华 点齐 军队,预备打仗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, '他们从远 方 来,从天 边来,就是耶和华 并他恼恨的 兵器 要毁灭 这全 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, '你们要哀号,因为 耶和华 的日子 临近了!这日来到,好像毁灭 从全能者来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, '所以,人手 都 必软弱;人 心 都 必消化。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, '他们必惊惶 悲痛;愁苦 必将他们抓住。他们疼痛,好像产难的妇人一样,彼此 惊奇相看,脸如 火焰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, ' 耶和华 的日子 临到,必有残忍、忿恨、烈怒,使 这地 荒凉,从其中 除灭 罪人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, ' 天上 的众星 群宿 都不 发 光;日头 一出 就变黑暗;月亮 也不 放 光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, '我必因邪恶 刑罚 世界,因罪孽刑罚 恶人,使骄傲人 的狂妄 止息,制伏 强暴人 的狂傲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, '我必使人 比精金 还少,使人 比俄斐 纯金更少。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, '我─万军 之耶和华 在忿恨中 发烈 怒 的日子,必使天 震动,使地 摇撼,离其本位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, '人必 像被追赶 的鹿,像无人 收聚 的羊,各 归 回 本族,各 逃 到 本土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, '凡 被仇敌追上的 必被刺死;凡 被捉住的 必被刀 杀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, '他们的婴孩 必在他们眼前 摔碎;他们的房屋 必被抢夺;他们的妻子 必被玷污。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, '我 必激动 米底亚人 来攻击他们。米底亚人 不 注重 银子,也不 喜爱 金子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, '他们必用弓 击碎 少年人,不 怜悯 妇人所生的,眼 也不 顾惜 孩子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, '巴比伦 素来为 列国 的荣耀,为迦勒底人 所矜夸的 华美,必像 神 所倾覆 复的 所多玛、 蛾摩拉一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, '其内必永 无 人烟,世世 代代 无人 居住。阿拉伯人 也不 在那里 支搭帐棚;牧羊的人 也不 使羊群卧在 那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, '只有旷野的走兽 卧 在那里;咆哮的兽 满了 房屋。鸵鸟 住 在那里;野山羊 在那里 跳舞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, '豺狼 必在它宫中 呼号;野狗 必在它华美 殿内吼叫。巴比伦受罚的时候 临 近;它的日子 必不 长久。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, ' 耶和华 要怜恤 雅各,必再 拣选 以色列,将他们安置 在 本地。寄居的 必与他们 联合,紧贴 雅各 家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, '外邦人 必将他们 带 回 本土;以色列 家 必在 耶和华 的地 上得 外邦人为仆 婢,也要 掳掠 先前掳掠他们的,辖制 先前欺压他们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, '当 耶和华 使你 脱离愁苦、烦恼,并人 勉强你 做 的苦 工,得享安息 的日子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, '你必题 这 诗歌 论 巴比伦 王 说:欺压人的 何竟 息灭?强暴的 何竟止息? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, '耶和华 折断了 恶人 的杖,辖制人 的圭, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, '就是在忿怒中 连连 攻击 众民的,在怒气中 辖制 列国,行逼迫 无人 阻止的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, '现在全 地 得安息,享平静;人皆发声 欢呼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, '松树 和 黎巴嫩 的香柏树 都因你 欢乐,说:自从 你仆倒,再无人 上来 砍伐 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, '你下到阴间,阴间 就因你 震动 来 迎接你,又因你 惊动 在世曾为 首领 的阴魂,并使那曾为列 国 君王的,都离位 站起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, '他们都要 发言 对你 说:你 也 变为软弱 像我们一样吗?你也成了 我们的 样子吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, '你的威势 和你琴瑟 的声音 都下到 阴间。你下 铺的 是虫,上盖的 是蛆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, '明亮之星,早晨 之子啊,你何竟 从天 坠落?你这攻败 列国 的何竟被砍倒 在地上? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, '你 心里 曾说:我要升到 天上;我要高举 我的宝座在 神 众星 以上;我要坐 在聚会 的山上,在北方 的极处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, '我要升 到 高 云之上;我要与至上者 同等。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, '然而,你必坠落 阴间,到 坑中 极深之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, '凡看见你的 都要定睛 看你,留意 看你,说:使大地 战 抖,使列国 震动, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, '使 世界 如同荒野,使城邑 倾覆 复,不 释放 被掳的人 归家,是这个 人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, '列国的 君王 俱 各 在自己阴宅 的荣耀中 安睡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, '惟独你 被抛弃,不得入你的坟墓,好像可憎的 枝子,以被杀的人 为衣,就是被刀 刺透,坠落 坑中 石头那里的;你又像被践踏 的尸首一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, '你不得 与君王 同 葬;因为 你败坏 你的国,杀戮 你的民。恶人 后裔的名,必永 不 提说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, '先人 既有罪孽,就要预备 杀戮 他的子孙,免得 他们兴起来,得了 遍地,在世上 修满 城邑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, '万军 之耶和华 说:我必兴起 攻击他们,将巴比伦的 名号 和所余 馀剩的人,连子 带孙 一并剪除。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, '我必使 巴比伦为箭猪 所得,又变为水 池;我要用灭亡的 扫帚 扫净它。这是万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, '万军 之耶和华 起誓 说: 我怎样 思想,必 照样 成就;我怎样 定意,必 照样成立, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, '就是在我地上 打折 亚述人,在 我山 上将他践踏。他加的轭 必离开 以色列人;他加的重担 必离开  他们的肩头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, '这是 向 全 地 所定的 旨意;这是 向 万 国 所伸出的 手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, '万军 之耶和华 既然 定意,谁 能废弃呢?他的手 已经伸出,谁 能转回呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, '亚哈斯 王 崩 的那年,就有 以下 的默示: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, '非利士 全地啊,不要 因 击打 你的杖 折断 就喜乐。因为 从蛇 的根 必生出 毒蛇;牠所生的 是火焰的 飞 龙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, '贫寒人 的长子 必有所食;穷乏人 必安然 躺卧。我必以饥荒 治死 你的根;你所余 馀剩的人 必被杀戮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, '门哪,应当哀号!城啊,应当呼喊!非利士 全地啊,你都消化了!因为 有烟 从北方 出来,他行伍中 并无 乱队的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, '可怎样 回答 外邦(或指非利士)的使者呢?必说: 耶和华 建立了 锡安;他百姓中 的困苦人 必投奔 在其中。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, '论摩押 的默示: 一夜之间,摩押 的亚珥 变为荒废,归于 无有; 一夜之间,摩押 的基珥 变为荒废,归于 无有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, '他们上 巴益,又往底本,到高处 去哭泣。摩押人 因 尼波 和 米底巴 哀号,各人 头上 光秃, 胡须 剃净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, '他们在街市上 都腰束 麻布,在 房顶 上和宽阔处 俱各 哀号,眼泪 汪汪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, '希实本 和以利亚利 悲哀 的声音 达 到 雅杂,所以 摩押 带兵器的 高声喊嚷,人心 战 兢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, '我心 为摩押 悲哀;他的贵胄(或译:逃民)逃到 琐珥,到伊基拉‧施利施亚。 他们上 鲁希 坡,随走随哭; 在何罗念 的路上,因毁灭 举起 哀声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, '因为 宁林 的水 成为 干涸, 青草 枯干,嫩草 灭没,青绿之物,一无 所有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, '因 此,摩押人所得的 财物 和所积蓄的 都要运 过 柳树 河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, ' 哀声 遍闻 摩押 的四境;哀号 的声音达到 以基莲;哀号的声音达到比珥‧以琳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, ' 底们 的水 充满了 血;我还 要 加增 底们的灾难,叫狮子 来追上摩押 逃脱的民 和那地上 所余 馀剩的人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, '你们当将羊羔 奉给 那地 掌权的,从西拉 往旷野,送到 锡安城(原文是女子)的山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, ' 摩押的居民(原文是女子)在亚嫩 渡口,必 像游飞 的鸟,如拆 窝的雏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, '求你献 谋略,行 公平,使 你的影子 在午 间 如黑夜,隐藏 被赶散的人,不可 显露 逃民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, '求你容我这被赶散的人 和你 同居。至于 摩押,求你作 他的 隐密处,脱离灭命者 的面。 勒索人的 归于 无有,毁灭的事 止息了,欺压人的 从 国中 除灭了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, '必有宝座 因慈爱 坚立;必有一位诚诚实实 坐 在其上,在大卫 帐幕中 施行审判,寻求 公平,速行 公义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, '我们听说 摩押人 骄傲,是极其 骄傲;听说他狂妄、骄傲、忿怒;他夸大的话 是虚空的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, '因此,摩押人 必为摩押 哀号;人人都 要哀号。你们摩押人要为吉珥‧哈列设 的葡萄饼 哀叹,极其 忧伤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, '因为 希实本 的田地 和西比玛 的葡萄树 都衰残了。列国 的君主 折断 其上美好的枝子;这枝子长 到 雅谢 延到 旷野,嫩枝 向外探出,直探过 盐海。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, '因 此,我要为西比玛 的葡萄树 哀哭,与雅谢人 哀哭一样。希实本、以利亚利啊,我要以眼泪 浇灌你;因为 有交战 呐喊的声音 临到 你夏天的果子,并 你收割的 庄稼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, '从 肥美的田 中夺去了 欢喜 快乐;在葡萄园里 必无 歌唱,也无 欢呼的声音。踹酒的 在酒醡中 不得 踹出 酒来;我使他欢呼的声音 止息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, '因 此,我心腹 为摩押 哀鸣 如琴;我心肠为吉珥‧哈列设也是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, ' 摩押人 朝见 的时候,在 高处 疲乏,又到 他圣所 祈祷,也不 蒙应允。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, '这是 耶和华 从前 论 摩押 的 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, '但现在 耶和华 说:「三 年之内,照雇工 的年数,摩押 的荣耀与他的 群众 必被藐视,余 馀剩的人 甚 少 无 几。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, '论大马士革 的默示:看哪,大马士革 已被废弃,不再为城,必变作 乱 堆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, '亚罗珥 的城邑 已被撇弃,必成为 牧羊之处;羊在那里躺卧,无人 惊吓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, '以法莲 不再有 保障;大马士革 不再有国权;亚兰 所剩下的 必 像以色列 人 的荣耀消灭一样。这是万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, '到 那 日,雅各 的荣耀 必至枵薄;他肥胖 的身体 必渐瘦弱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, '就必 像收割的人 收敛 禾稼,用手 割取 穗子,又 像人在利乏音 谷 拾取 遗落的穗子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, '其间 所剩下的 不多,好像人打 橄榄树─在尽 侭上的 枝梢上 只剩两 三个 果子;在多果树的 旁枝上 只剩四 五个果子。这是耶和华─以色列的 神 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, '当那 日,人 必仰望 造他们的主,眼目 重看 以色列 的圣者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, '他们必不 仰望 祭坛,就是自己手 所 筑的,也不 重看 自己指头 所 做的,无论是木偶 是日像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, '在那 日,他们的坚固 城 必 像树林中 和山顶上 所 撇弃的地方,就是 从前在以色列 人 面前 被人撇弃的。这样,地就 荒凉了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, '因 你忘记 救你的 神,不 记念 你能力 的磐石;所以,你栽上 佳美的 树秧子,插上 异样的 栽子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, '栽种 的日子,你周围圈上篱笆,又到早晨 使你所种的 开 花;但在愁苦 极其 伤痛的 日子,所收割的 都飞去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, '唉!多 民 哄嚷,好像海浪 匉訇;列邦 奔腾,好像 猛 水 滔滔; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, '列邦 奔腾,好像多 水 滔滔;但 神斥责 他们,他们就远远 逃避,又被追赶,如同山上 的风 前 糠,又如暴风 前 的旋风土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, '到 晚上 有惊吓,未到 早晨 他们就没有了。这是 掳掠我们之人 所得的分,是抢夺我们之人 的报应。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, '唉! 古实 河 外 翅膀 刷刷响声 之地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, '差遣 使者 在 水 面上,坐蒲草 船 过海。先知说:你们快行的 使者,要到 高大 光滑 的民 那里去。自从 开 国 以来,那民 极其可畏,是分地界 践踏人的; 他们的地 有江河 分开 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, '世上 一切的 居民 和地上 所住的人哪,山上 竖立 大旗 的时候你们要看;吹 角 的时候你们要听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, ' 耶和华 对我 这样 说:我要安静,在我的居所 观看,如同日光 中 的清 热,又如露水 的云雾 在收割 的热天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, ' 收割 之先,花 开 已谢,花 也成了 将熟的 葡萄;他必用镰刀 削去 嫩枝,又砍 掉 蔓延的枝条, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, '都要 撇给 山间 的鸷鸟 和地上 的野兽。夏天,鸷鸟 要宿在其上;冬天, 野兽 都 卧在其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, '到那 时,这高大 光滑 的民,就是 从 开 国 以来 极其可畏、分地界 践踏人的, 他们的地 有江河 分开 ;他们必将礼物 奉给 万军 之耶和华,就是奉到 锡安 山─ 耶和华 安置他名 的地方。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, '论埃及 的默示:看哪,耶和华 乘驾 快 云,临到 埃及。埃及 的偶像 在他面前 战 兢;埃及人 的心 在里面 消化。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, '我必激动 埃及人 攻击埃及人─弟兄 攻击 弟兄,邻舍 攻击邻舍;这城 攻击那城,这国 攻击那国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, '埃及人 的心神 必在里面 耗尽;我必败坏 他们的谋略。他们必求问 偶像 和 念咒的、 交鬼的、 行巫术的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, '我必将 埃及人 交 在残忍 主 的手中;强暴 王 必辖制 他们。这是主─万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, '海中的 水 必绝尽,河 也消没 干涸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, '江河 要变臭;埃及 的河水 都必减少 枯干。苇子 和芦荻 都必衰残; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, '靠 尼罗河 旁 的草田,并 沿 尼罗河 所种的田,都必枯干。庄稼被风吹去,归于 无有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, '打鱼的 必哀哭。在尼罗河 一切 钓鱼的 必悲伤;在 水 上 撒 网 的必都衰弱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, '用梳好的 麻 造物的 和织 白布 的都必羞愧; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, '国柱 必 被打碎,所有佣工的,心 必愁烦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, '琐安 的首领 极其 愚昧;法老 大有智慧 的谋士,所筹划 㓰的 成为愚谋。你们怎敢 对 法老 说:我 是智慧人 的子孙,我是古 王 的后裔? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, ' 你的智慧人 在哪里呢?万军 之耶和华 向 埃及 所 定的旨意,他们可以知道,可以 告诉 你吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, '琐安 的首领 都变为愚昧;挪弗 的首领 都受了迷惑。当埃及支派 房角石的,使 埃及人 走错了路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, '耶和华 使乖谬的 灵 搀入 埃及中间;首领使 埃及 一切 所做的 都有差错,好像醉酒之人 呕吐的时候 东倒西歪一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, '埃及中,无论 是头 与尾,棕枝 与芦苇,所 做之工 都不 成就。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, '到那 日,埃及人 必 像妇人一样,他们必因 万军 之耶和华 在埃及以上 所 抡的 手,战 兢 惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, '犹大 地 必 使埃及 惊恐,向谁 提起犹大地,谁 就惧怕。这是因 万军 之耶和华向埃及 所 定的 旨意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, '当那 日,埃及 地 必有 五 城 的人说 迦南 的方言,又指著万军 之耶和华 起誓。有一 城必称为「灭亡 城」。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, '当那 日,在埃及 地 中 必有 为耶和华 筑的一座坛;在 埃及的边界 上 必有为耶和华 立的一根柱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, '这都要在埃及 地 为万军 之耶和华 作 记号 和证据。埃及人因为 受人的欺压 哀求 耶和华,他就差遣 一位救主 作护卫者,拯救他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, '耶和华 必被埃及人 所认识。在那 日,埃及人 必认识 耶和华,也要献 祭物 和供物敬拜他,并向耶和华 许 愿  还愿 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, '耶和华 必击打 埃及,又击打 又医治,埃及人就归 向 耶和华。他必应允 他们的祷告,医治他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, '当那 日,必有 从埃及 通亚述 去的大道。亚述人 要进 入埃及,埃及人 也进入亚述;埃及人 要与 亚述人 一同敬拜耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, '当那 日,以色列 必 与埃及、亚述 三国一律,使地上 的人得福; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, '因为万军 之耶和华 赐福 给他们,说:「埃及─我的百姓,亚述─我手 的工作,以色列─我的产业,都有福了!」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, '亚述 王 撒珥根 打发 他珥探 到 亚实突 的那年,他珥探就攻打 亚实突,将城攻取。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, '那 时,耶和华 晓谕 亚摩斯 的儿子 以赛亚 说:「你去 解掉 你腰间 的麻布,脱下 你脚上 的鞋。」以赛亚就这样 做,露身 赤脚 行走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, '耶和华 说:「我仆人 以赛亚 怎样 露身 赤脚 行走 三 年,作为关乎 埃及 和 古实 的预兆 奇迹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, '照样,亚述 王 也必掳去 埃及人,掠去 古实人,无论老 少,都露身 赤脚,现出 下体,使埃及 蒙羞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, '以色列人必因所仰望的 古实,所夸耀的 埃及,惊惶 羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, '「那 时,这 沿海 一带的居民 必说:『看哪,我们素所仰望的,就是 我们为脱离 亚述 王 逃 往 求救的,不过是如此!我们 怎能 逃脱呢?』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, '论海旁 旷野 的默示:有仇敌从旷野,从可怕 之地 而来,好像南方 的旋风,猛然扫过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, '令人凄惨的 异象 已默示 于 我。诡诈的 行诡诈,毁灭的 行毁灭。以拦哪,你要上去!米底亚啊,你要围困!主说:我使一切 叹息 止住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, '所以,我满 腰 疼痛;痛苦 将我抓住,好像产 难的妇人一样。我疼痛 甚至不能听;我惊惶 甚至不能看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, '我心 慌张,惊恐 威吓我。我所羡慕的 黄昏,变为 我的 战 兢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, '他们摆设 筵席,派人守望,又吃,又喝。首领啊,你们起来,用油抹 盾牌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, ' 主 对我 如此 说:你去 设立 守望的,使他将所 看见的 述说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, '他看见 军队,就是骑马的 一对一对地来,又看见驴 队,骆驼 队,就要侧耳细听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, '他像狮子 吼叫,说:主啊,我 白日 常 站 在 望楼上, 整 夜 立 在 我守望所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, '看哪, 有一队 军兵 骑著马,一对一对 地来。他就 说:巴比伦 倾倒了!倾倒了!他一切 雕刻的神 像 都打碎 于 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, '我被打的禾稼,我场上 的谷啊,我从 万军 之耶和华─以色列的 神 那里所 听见的,都告诉 你们了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, '论度玛 的默示:有人声从西珥 呼 问我说:守望的啊,夜里 如何?守望的啊,夜里 如何? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, '守望的 说:早晨 将到,黑夜 也来。你们若 要问 就可以问,可以回头 再来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, '论阿拉伯 的默示:底但 结伴的客旅啊,你们必在阿拉伯 的树林中 住宿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, '提玛 地 的居民 拿 水来,送给 口渴的,拿饼 来迎接 逃避的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, '因为 他们逃避 刀剑 和 出了鞘的 刀,并 上了弦的 弓 与 刀兵 的重灾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, ' 主 对我 这样 说:「一年 之内,照雇工 的年数,基达 的一切 荣耀 必归于 无有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, '弓箭手 所余 馀剩的,就是基达 人 的勇士,必然稀少,因为 这是耶和华─以色列的 神 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, '论异象 谷 的默示:有什么 事使你 这 满城的人都 上 房顶呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, '你这满处 呐喊、大有喧哗 的城,欢乐 的邑啊,你中间被杀的 并不是 被刀 杀,也不是 因打仗 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, '你所有的 官长 一同 逃跑,都为弓箭手 所捆绑。你中间一切 被找到的 都一同 被捆绑;他们本是逃往 远方的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, '所以 我说:你们转眼 不看我,我要痛 哭。不要 因我众民(原文是民 女)的毁灭,就竭力 安慰我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, '因为 主─万军 之耶和华使「异象 谷」有溃乱、践踏、烦扰 的日子。城 被攻破,哀声 达到 山间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, '以拦 带著 箭袋,还有坐战 车 的和马 兵;吉珥 揭开  盾牌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, ' 你嘉美的 谷 遍满 战 车,也有马兵 在城门 前 排列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, '他去掉 犹大 的遮盖。那 日,你就仰望 林 库 内的军器。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, '你们看见 大卫 城 的破口 很多,便聚积 下 池 的水, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, '又数点 耶路撒冷 的房屋,将房屋 拆毁,修补 城墙, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, '又在两道城墙 中间 挖 一个聚水池 可盛旧 池 的水,却不 仰望 做这事的主,也不 顾念 从古 定这事的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, '当那 日,主─万军 之耶和华 叫人 哭泣 哀号,头上光秃,身披 麻布。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, '谁知,人倒欢喜 快乐,宰 牛 杀 羊,吃 肉 喝 酒,说:我们吃 喝吧!因为 明天 要死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, '万军 之耶和华 亲自默示 我说:这 罪孽 直到 你们 死,断不得 赦免!这是主─万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, '主─万军 之耶和华 这样 说:「你 去 见 掌银库的,就是 家宰 舍伯那,对他说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, '『你 在这里 做什么呢?有 什么人 竟 在这里 凿 坟墓,就是在高处 为自己 凿 坟墓,在磐石中 为自己 凿出 安身之所? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, '看哪,耶和华 必像大 有力的人,将你紧紧 缠裹,竭力抛去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, '他必 将你滚成 一团,抛在 宽阔 之地,好像抛球一样。你这主人 家 的羞辱,必在那里 坐你荣耀 的车,也必在那里 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, '我必赶逐你 离开 官职;你必从你的原位 撤下。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, '「到 那 日,我必召 我仆人 希勒家 的儿子 以利亚敬来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, '将你的外袍 给他穿上,将你的腰带 给他系紧,将你的政权 交 在他手中。他必作 耶路撒冷 居民 和犹大 家 的父。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, '我必将大卫 家 的钥匙 放 在 他肩头上。他开 ,无人 能关;他关,无人 能开 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, '我必将他安稳,像钉子 钉在坚固 处;他必作 为他父 家 荣耀 的宝座。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, '他父 家 所有的 荣耀,连儿女 带子孙,都挂 在他身上,好像一切 小 器皿,从 杯子 到 酒瓶挂上一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, '万军 之耶和华 说:当那 日,钉 在坚固 处 的钉子 必压斜,被砍断 落地; 挂在其上的 重担 必被剪断。因为 这是耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, '论泰尔 的默示:他施 的船只 都要哀号;因为 泰尔变为荒场,甚至没有房屋,没有可进之路。这消息是从基提 地 得来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, '沿海的 居民,就是素来靠航 海 西顿 的商家 得丰盛的,你们当静默无言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, '在大 水之上,西曷 的粮食、尼罗河 的庄稼 是泰尔的进项;她作 列国 的大码头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, '西顿哪,你当惭愧;因为 大海 说,就是海中 的保障 说:我没有 劬劳,也没有 生产,没有 养育 男子,也没有抚养 童女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, ' 这风声 传到埃及;埃及人为泰尔 的风声 极其疼痛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, '泰尔人哪,你们当过到 他施去;沿海的 居民哪,你们都当哀号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, '这是 你们 欢乐的城,从 上古 而有的吗?其中的居民 往 远方 寄居。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, '泰尔 本是赐冠冕的。她的 商家 是王子;她的买 卖人 是世上 的尊贵人。遭遇 如此 是谁 定的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, '是万军 之耶和华 所定的!为要污辱 一切 高傲的 荣耀,使地上 一切的 尊贵人 被藐视。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, '他施的民(原文是女)哪,可以流行 你的地,好像尼罗河;不 再 有腰带拘紧你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, '耶和华 已经向 海 伸 手,震动 列国。至于  迦南,他已经吩咐 拆毁 其中的保障。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, '他又说:受欺压 西顿 的居民(原文是处女)哪,你必不 得 再 欢乐。起来!过到 基提 去;就是 在那里 也不得 安歇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, '(看哪,迦勒底人 之地 向来没 有 这 民,这国是亚述人 为住旷野的人 所立的。现在他们建筑 戍楼,拆毁 泰尔的宫殿,使她成为 荒凉。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, '他施 的船只 都要哀号,因为 你们的保障 变为荒场。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, '到 那 时,泰尔 必被忘记 七十 年,照著一 王 的年日。七十 年 后,泰尔的 景况必 像妓女 所唱的歌: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, '你这被忘记的 妓女啊,拿 琴 周流 城内,巧 弹 多 唱,使人 再想念你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, ' 七十 年 后,耶和华 必眷顾 泰尔,她就仍得利息(原文是雇价;下同),与 地 上 的万 国交易(原文是行淫)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, '她的货财 和利息 要归耶和华 为 圣,必不 积攒 存留;因为 她的货财 必为 住 在耶和华 面前的人所得,使他们吃 饱,穿耐久的 衣服。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, '看哪,耶和华 使地 空虚,变为荒凉;又翻转 大地,将居民 分散。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, '那时 百姓怎样,祭司也怎样;仆人怎样,主人也怎样;婢女怎样,主母也怎样;买 物的怎样,卖物的也怎样;放债的怎样,借债的也怎样;取利的怎样,出利的也怎样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, '地 必全然 空虚,尽都 荒凉;因为 这 话 是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, '地上 悲哀 衰残,世界 败落 衰残;地上 居高位的 人 也败落了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, '地 被其上的 居民 污秽;因为 他们犯了 律法,废了 律例,背了 永 约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, '所以,地 被咒诅 吞灭;住 在其上的 显为有罪。 地上 的居民 被火焚烧,剩下的 人 稀少。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, '新酒 悲哀,葡萄树 衰残;心中 欢乐的 俱都 叹息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, '击鼓 之乐 止息;宴乐人 的声音 完毕,弹琴 之乐 也止息了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, '人必不得 饮 酒 唱歌;喝 浓酒的,必以为苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, '荒凉 的城 拆毁了;各 家 关门闭户,使人都不得进去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, '在街上 因 酒 有悲叹的声音;一切 喜乐 变为昏暗;地上 的欢乐 归于 无有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, '城中 只有 荒凉;城门 拆毁 净尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, ' 在 地上 的万民 中,必 像打过的 橄榄树,又像已摘 的葡萄 所剩无几。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, '这些人 要高声 欢呼;他们为耶和华 的威严,从海 那里扬起 声来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, '因 此,你们要在东方 荣耀 耶和华,在众海 岛 荣耀耶和华─以色列 神 的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, '我们听见 从地 极 有人歌唱,说:荣耀 归于 义人。我却说:我 消灭了!我 消灭了,我 有祸了!诡诈的 行诡诈;诡诈的 大 行诡诈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, '地上 的居民哪,恐惧、陷坑、网罗 都临近你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, '躲避 恐惧 声音 的必 坠 入 陷坑;从 陷坑 上来的 必被网罗 缠住;因为 天上 的窗户 都开 了,地 的根基 也震动了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, '地 全然 破坏, 尽都 崩裂, 大大地 震动了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, '地 要东倒 西歪,好像醉酒的人;又摇来摇去,好像吊床。罪过 在其上 沉重,必然塌陷,不能 复 起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, '到 那 日,耶和华 在高处 必惩罚 高处 的众军,在地 上必惩罚 地上 的列王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, '他们必被聚集,像囚犯 被聚 在 牢狱中,并要囚 在 监牢里,多 日 之后便被讨罪(或译:眷顾)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, '那时,月亮 要蒙羞,日头 要惭愧;因为 万军 之耶和华 必在锡安 山,在耶路撒冷 作王;在敬畏他的长老 面前,必有荣耀。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, '耶和华啊,你是我的 神;我要尊崇你,我要称赞 你的名。因为 你以忠信 诚实 行过 奇妙的事,成就你古时 所定的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, ' 你使 城 变为乱堆,使坚固 城 变为荒场,使外邦人 宫殿 的城不再为城,永远 不 再建造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, '所以,刚强的 民 必荣耀你;强暴 之国 的城 必敬畏你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, '因为 当强暴人 催逼人的时候,如同暴风 直吹墙壁,你就 作 贫穷人 的保障,作困乏人 急难中 的保障,作躲暴风 之处,作避炎热 的阴凉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, '你要压制 外邦人 的喧哗,好像干燥地 的热气下落;禁止 强暴人 的凯歌,好像热气 被云 影消化。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, '在这 山上,万军 之耶和华 必为万 民 用肥甘 设摆 筵席,用陈酒 和满髓 的肥甘,并澄清 的陈酒,设摆筵席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, '他又必在这 山上 除灭 遮盖 万 民 之物 和遮蔽 万 国 蒙脸 的帕子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, '他已经吞灭 死亡 直到永远。主 耶和华 必擦去 各人 脸上 的眼泪,又除掉 普 天下 他百姓 的羞辱,因为 这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, '到那 日,人必说:「看哪,这是我们的 神;我们素来等候 他,他必拯救我们。这是 耶和华,我们素来等候 他,我们必因他的救恩 欢喜 快乐。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, '耶和华 的手 必 按 在这 山上;摩押人 在所居之地 必被践踏,好像干草 被践踏 在 粪池 的水中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, '他必在其中 伸开  手,好像 洑水的 伸开  手洑水一样;但耶和华必使他的骄傲 和 他手 所行的诡计 一并败落。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, '耶和华使你城上 的坚固 高台 倾倒,拆平, 直到 尘埃。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, '当那 日,在犹大 地 人必唱 这 歌说:我们有 坚固 的城。耶和华要将救恩 定为 城墙,为外郭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, '敞开  城门,使守 信 的义 民 得以进入。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, '坚心 倚赖你的,你必保守 他十分 平安,因为 他倚靠 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, '你们当倚靠 耶和华 直到 永远,因为 耶和华 是永久的 磐石。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, ' 他使住 高处的 与高 城 一并败落,将城拆毁,拆平, 直到 尘埃, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, '要被脚 践踏,就是被困苦人 的脚 和穷乏人 的脚践踏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, '义人的 道 是正直的;你为正直的主,必修平 义人 的路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, ' 耶和华啊,我们在你行审判 的路 上等候你;我们心里 所羡慕的 是你的名,就是你那可记念的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, '夜间,我心中 羡慕你; 我里面 的灵 切切寻求你。因为 你在世上 行审判的时候,地上 的居民 就学习 公义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, '以恩惠待 恶人,他仍不 学习 公义;在正直 的地上,他必行事不义,也不 注意 耶和华 的威严。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, '耶和华啊,你的手 高举,他们仍然不 看;却要看 你为百姓 发的热心,因而抱愧,并且 有火 烧灭 你的敌人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, '耶和华啊,你必派定 我们 得平安,因为 我们所做的事 都是 你给我们 成就的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, '耶和华─我们的 神啊,在你以外 曾有别的主 管辖我们,但我们专 要倚靠你,提 你的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, '他们死了,必不能 再活;他们去世,必不能 再起;因为 你刑罚他们,毁灭他们,他们的 名号 就全然 消灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, '耶和华啊,你增添 国民,你增添 国民;你得了荣耀,又扩张 地 的四 境。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, '耶和华啊,他们在急难中 寻求你;你的惩罚 临到他们身上,他们就倾心吐胆 祷告你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, ' 妇人怀孕,临 产 疼痛,在痛苦之中 喊叫;耶和华啊,我们在你面前 也是 如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, '我们也曾怀孕 疼痛,所产的 竟像 风一样。我们在地上 未曾 行 什么拯救的事;世上 的居民 也未曾 败落。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, '死人(原文是你的死人)要复活,尸首(原文是我的尸首)要兴起。睡在 尘埃的啊,要醒起 歌唱!因 你的甘露 好像菜蔬 上的甘露,地 也要交出 死人来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, '我的百姓啊,你们要来 进 入内室,关上 门,隐藏 片 时,等到 忿怒 过去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, '因为 耶和华 从他的居所 出来,要刑罚 地 上 居民 的罪孽。地 也必露出 其中的血,不 再 掩盖 被杀的人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, '到那 日,耶和华 必用他刚硬 有力 的大 刀 刑罚 鳄鱼─就是那快行的 蛇,刑罚 鳄鱼─就是那曲行的 蛇,并杀 海中的 大鱼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, '当那 日,有出酒的 葡萄园,你们要指这园 唱歌说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, '我─耶和华 是看守葡萄园的;我必时刻 浇灌,昼 夜 看守,免得 有人损害。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, '我 心中不 存忿怒。惟愿  荆棘 蒺藜 与我 交战 ,我就勇往直前,把它 一同 焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, '不然,让它持住 我的能力,使它 与我 和好,愿 它 与我 和好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, '将来 雅各 要扎根,以色列 要发芽 开 花;他们的果实 必充满 世界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, '主击打他们,岂像击打 那些击打他们的人吗?他们被杀戮,岂像 被他们所杀戮的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, '你打发他们去,是相机宜 与他们相争;刮东风 的日子,就用暴 风 将他们逐去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, '所以,雅各 的罪孽 得赦免,他的罪过 得除掉的 果效,全 在乎此:就是他叫 祭坛的 石头 变为打碎的 灰 石,以致木偶 和日像 不 再立起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, '因为 坚固 城 变为凄凉,成了撇下 离弃的 居所,像旷野一样;牛犊 必在那里 吃草,在那里 躺卧,并吃尽 其中的树枝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, '枝条 枯干,必被折断;妇女 要来 点火烧著。因为 这 百姓 蒙昧无 知,所以,创造他们的 必不 怜恤他们;造成他们的 也不 施恩与他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, '以色列 人哪,到 那 日,耶和华 必从大 河,直到 埃及 小河,将你们 一 一 地收集,如同人打树拾果一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, '当 那 日,必大 发 角声,在亚述 地 将要灭亡的,并在埃及 地 被赶散的,都要来,他们就在耶路撒冷 圣 山上 敬拜 耶和华。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, '祸哉!以法莲 的酒徒, 住在 肥 美 谷 的山上,他们心里高傲,以所夸的 为冠冕,犹如将残 之花。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, '看哪,主 有一大能 大力者,像一阵 冰雹,像毁灭的 暴风,像 涨溢的 大 水,他必用手 将冠冕摔落 于 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, '以法莲 高傲的 酒徒,他的冠冕 必被踏 在脚下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, ' 那荣 美 将残 之花,就是 在 肥美 谷 山上的,必像夏令 以前 初熟的无花果; 看见 这果 的就注意,一 到手中 就吞吃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, '到那 日,万军 之耶和华 必作 他余 馀剩 之民 的荣 冠 华 冕, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, '也作了在 位上 行审判 者公平 之灵,并城门口 打退 仇敌者 的力量。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, '就是这地的人 也 因酒 摇摇晃晃,因浓酒 东倒西歪。祭司 和先知 因浓酒 摇摇晃晃,被 酒 所困,因 浓酒 东倒西歪。他们 错解 默示,谬行 审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, '因为 各 席上 满了 呕吐 的污秽,无一 处干净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, '讥诮先知的说:他要将知识 指教 谁呢?要使 谁 明白 传言呢?是那刚断 奶 离 怀的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, '他竟 命 上加命,令 上加令,律 上加律,例 上加例,这里 一点,那里 一点。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, '先知说:不然,主要藉 借异邦人 的嘴唇 和外邦人 的舌头 对 这 百姓 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, '他 曾对他们 说:你们要使疲乏人 得安息,这样 才得安息, 才得舒畅,他们却不 肯 听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, '所以,耶和华 向他们 说的话 是 命 上加命,令 上加令,律 上加律,例 上加例,这里 一点,那里 一点,以致 他们前行 仰面 跌倒,而且跌碎,并陷入网罗 被缠住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, '所以,你们这些亵慢的 人,就是 辖管 住在耶路撒冷 这 百姓的,要听 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, ' 你们曾说:我们与 死亡 立 约,与 阴间 结 盟;敌军(原文是鞭子)如水涨漫 经过的时候,必不 临到我们;因 我们以 谎言 为避所,在虚假 以下藏身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, '所以,主 耶和华 如此 说:看哪,我在锡安 放 一块石头作为根基,是试验过的 石头,是稳固 根基,宝贵的 房角石;信靠的人 必不 著急。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, '我必以 公平 为准绳,以公义 为线 缐铊。冰雹 必冲去 谎言的 避所;大水 必漫过 藏身之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, '你们与 死亡 所立的约 必然废掉,与 阴间 所结的盟 必立 不住。敌军(原文是鞭子)如水涨漫 经过的时候,你们必 被他 践踏; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, '每逢 经过 必将你们 掳去。因为 每 早晨 他必经过,白昼 黑夜 都必如此。明白 传言 的必受 惊恐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, '原来,床 榻短,使人不能舒身;被窝 窄,使人不能遮体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, '耶和华 必 兴起,像在毘拉心 山;他必发怒,像在基遍 谷,好做成 他的工,就是非常的 工;成就 他的事,就是奇异 的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, '现在 你们不可 亵慢,恐怕 捆你们的绑索 更结实了;因为 我从 主─万军 之耶和华 那里听见,已经决定 在 全 地 上施行灭绝的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, '你们当侧耳 听 我的声音,留心 听 我的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, '那耕地 为要撒种的,岂是常常 耕地呢?岂是常常开 垦 耙 地呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, '他拉平了 地面,岂 不 就撒种 小茴香,播种 大茴香,按行列 种 小麦,在定处 种大麦,在田边 种粗麦呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, '因为他的 神 教导 他务农相宜,并且指教他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, '原来 打 小茴香,不 用尖利的器具,轧 大茴香,也不用碌碡(原文是车 轮;下同);但 用杖 打 小茴香,用棍 打大茴香。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, '做饼的粮食 是用磨磨碎,因 它不 必常 打;虽用碌碡 和马 打散,却不 磨它。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, '这 也 是出 于  万军 之耶和华─他的谋略 奇妙;他的智慧 广大。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, '唉!亚利伊勒,亚利伊勒,大卫 安营 的城,任凭你年 上 加 年,节期 照常周流。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, '我终必使亚利伊勒 困难;她必 悲伤 哀号,我却 仍以她 为亚利伊勒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, '我必四围 安营 攻击你,屯兵 围困 你,筑 垒 攻击你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, '你必败落,从地中 说话;你的言语 必微细 出于 尘埃。你的声音 必 像那交鬼者 的声音出于 地;你的言语 低低微微 出于 尘埃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, '你仇敌的 群众,却要 像细 尘;强暴人 的群众,也要像飞 糠。这事必顷刻之间 忽然 临到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, ' 万军 之耶和华 必用雷轰、地震、大 声、旋风、暴风,并吞灭的 火 焰,向她讨罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, '那时,攻击 亚利伊勒 列 国 的群众,就是一切 攻击亚利伊勒 和她的保障,并使她困难的,必 如梦景,如夜间 的异象; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, '又必 像 饥饿的人 梦中 吃饭, 醒了 仍觉腹 空;或 像 口渴的人 梦中 喝水, 醒了 仍觉发昏,心里 想喝。攻击 锡安 山 列 国 的群众 也必 如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, '你们等候 惊奇吧!你们宴乐 昏迷吧!他们醉了,却非 因酒;他们东倒西歪,却非 因浓酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, '因为 耶和华 将沉睡的 灵 浇灌 你们,封闭 你们的眼,蒙盖 你们的头。你们的眼就是 先知;你们的头就是先见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, '所有的 默示, 你们 看如封住的 书卷,人将 这书卷 交 给 识字的,说:「请 念吧!」他说:「我不 能念,因为 是 封住了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, '又将这书卷 交 给 不 识 字的人,说:「请 念吧!」他说:「我不 识字。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, '主 说:因为 这 百姓 亲近我,用嘴 唇 尊敬我,心 却远离 我;他们敬畏 我,不过是 领受 人 的吩咐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, '所以,我 在 这 百姓 中要行 奇妙的事,就是奇妙 又奇妙的事。他们智慧人 的智慧 必然消灭,聪明人 的聪明 必然隐藏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, '祸哉!那些向耶和华 深 藏 谋略的, 又在暗中 行事,说:谁 看见我们呢?谁 知道我们呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, '你们把事颠倒了,岂可 看 窑匠 如泥吗?被制作的物 岂可 论制作物的 说:他没有 制作我?或是被创造的物 论造物的 说:他没有 聪明? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, '黎巴嫩 变为 肥田,肥田 看 如树林,不是 只有 一点 点时候吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, '那 时,聋子 必听见 这书 上的话;瞎子 的眼 必从迷蒙 黑暗中 得以看见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, '谦卑人 必因耶和华 增添 欢喜;人间 贫穷的 必因以色列 的圣者 快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, '因为,强暴人 已归无有,亵慢人 已经灭绝,一切 找机会 作孽的 都被剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, '他们在争讼的事 上定无罪的 为有罪,为城门口 责备人的 设下网罗,用虚无的事 屈枉 义人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, '所以, 救赎 亚伯拉罕 的耶和华 论 雅各 家 如此 说:雅各 必不 再 羞愧,面容 也不 致 变色。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, '但 他看见 他的众子,就是我手 的工作 在他那里,他们必尊 我的名 为圣,必尊 雅各 的圣者 为圣,必敬畏 以色列的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, '心中 迷糊的 必得 明白;发怨言的 必受 训诲。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, '耶和华 说:祸哉!这悖逆的 儿女。他们同 谋,却不 由于 我,结 盟,却不 由于 我的灵,以致 罪 上 加 罪; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, '起身下 埃及 去,并没有 求问 我;要靠法老 的力量 加添自己的力量,并投 在埃及 的荫下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, '所以,法老 的力量 必作 你们的 羞辱;投 在埃及 的荫下,要为你们的惭愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, ' 他们的首领 已在 琐安;他们的使臣 到了 哈内斯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, '他们 必因 那不 利 于 他们 的民 蒙羞。那民并非 帮助,也非 利益,只 作羞耻 凌辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, '论南方 牲畜 的默示:他们把财物 驮 在 驴驹 的脊背上,将宝物 驮在 骆驼 的肉鞍上,经过艰难 困苦 之地,就是 公狮、母狮、蝮蛇、火焰的飞 龙之地,往 那不 利于 他们 的民那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, '埃及 的帮助 是徒然 无益的;所以 我称 她 为「坐而不动 的拉哈伯」。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, '现今 你去,在他们 面前将这话刻 在 版上,写 在 书上,以便 传留后 世,直到 永永 远远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, '因为 他们是 悖逆的 百姓、说谎的 儿女,不 肯 听从 耶和华 训诲 的儿女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, '他们 对先见 说:不要 望见不吉利的事,对先知说:不要 向我们 讲 正直的话;要向我们 说 柔和的话,言 虚幻的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, '你们要离弃 正道,偏离 直路,不要 在我们面前再提说 以色列 的圣者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, '所以,以色列 的圣者 如此 说:因为 你们藐视 这 训诲的话,倚赖 欺压 和乖僻,以此 为可靠的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, '故此,这 罪孽 在你们身上,好像将要破裂 凸出来 的高 墙, 顷刻之间 忽然 坍塌; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, '要被打碎,好像 把窑匠的 瓦器 打碎,毫不 顾惜,甚至碎块中 找 不到 一片 可用以从炉内 取 火,从池中 舀 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, ' 主 耶和华─以色列 的圣者 曾如此 说:你们得救 在乎归回 安息;你们得 力 在乎平静 安稳;你们竟自不 肯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, '你们却说:不然,我们要 骑 马 奔走。所以 你们必然奔走;又说:我们要骑 飞快的牲口。所以 追赶你们的,也必飞快。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, ' 一人 叱喝,必令 千人逃跑; 五人 叱喝,你们都必逃跑;以致 剩下的,好像 山 顶 的旗杆, 冈 上的大旗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, '耶和华 必然 等候,要施恩给你们;必然 兴起,好怜悯你们。因为 耶和华 是公平的 神;凡 等候 他 的都是有福的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, ' 百姓 必在锡安、在耶路撒冷 居住;你不 再 哭泣。主必因你哀求 的声音 施恩给你;他听见的时候 就必应允你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, '主 虽然以艰难 给 你 当饼,以困苦 给你当水,你的教师 却不 再 隐藏; 你眼 必看见 你的教师。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, '你或 向左 或 向右,你 必听见 后边 有声音 说:「这是 正路,要行 在其间。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, '你雕刻偶像所 包的 银子 和铸造偶像所 镀的 金子,你要玷污,要抛弃,好像 污秽之物,对偶像 说:「去吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, '你将种子 撒 在地里,主必降 雨在其上,并使地 所出 的粮 肥美 丰盛。到那 时,你的牲畜 必在宽阔 的草场 吃草。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, '耕 地 的牛 和驴驹 必吃 加盐的 料;这料 是用木杴 和杈子 扬净的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, '在大 行杀戮 的日子,高台 倒塌的时候, 各 高 山 冈陵 必有 川 流 河涌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, '当耶和华 缠裹 他百姓 的损处,医治 他民鞭 伤 的日子,月 光 必 像日 光,日 光 必 加七倍,像七 日 的光一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, '看哪,耶和华 的名 从远方 来,怒气 烧起,密烟 上腾。他的嘴唇 满有 忿恨;他的舌头 像吞灭的 火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, '他的气 如涨溢的 河水,直涨 到 颈项,要用毁灭 的筛箩 筛净 列国,并且在 众民 的口 中必有使人错行 的嚼环。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, '你们 必 唱歌,像守圣 节 的夜间一样,并且心中 喜乐,像人吹 笛,上 耶和华 的山,到 以色列 的磐石那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, '耶和华 必使人听 他威严 的声音,又显 他降罚的 膀臂 和他怒中 的忿恨,并吞灭 的火 焰 与霹雷、暴风、冰雹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, '亚述人 必因 耶和华 的声音 惊惶;耶和华必用杖 击打他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, '耶和华 必将 命定的 杖 加 在他身上;每 打一下,人必 击鼓 弹琴。打仗的时候,耶和华必抡起手来,与他 交战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, '原来 陀斐特 又深 又宽,早已 为王 预备 好了;其中堆 的是火 与许多 木柴。耶和华 的气 如一股 硫磺 火使他 著起来。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, '祸哉!那些下 埃及 求帮助的,是因 仗赖 马匹,倚靠 甚多的 车辆,并倚靠 强 壮的 马兵,却不 仰望 以色列 的圣者,也不 求问 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, '其实,耶和华有 智慧;他必降 灾祸,并不 反悔 自己的话,却要兴起 攻击 那作恶 之家,又攻击 那作 孽 帮助人的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, '埃及人 不过是人,并不是 神;他们的马 不过是血肉,并不是 灵。耶和华 一伸 手,那帮助人的 必绊跌,那受帮助的 也必跌倒,都 一同 灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, ' 耶和华 对我 如此 说: 狮子 和少壮狮子 护 食 咆哮,就是 喊 许多 牧人 来攻击牠,牠总不 因他们的声音 惊惶,也不 因他们的喧哗 缩伏。如此,万军 之耶和华 也必降临 在 锡安 山 冈 上争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, '雀鸟 怎样搧翅覆 复雏,万军 之耶和华 也要照样 保护 耶路撒冷。他必保护 拯救,要越 门保守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, '以色列 人哪,你们深深地 悖逆耶和华,现今要归向 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, ' 到那 日,各人 必将他金 偶像 银 偶像,就是 亲手 所造、陷自己 在罪中的,都抛弃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, '亚述人 必倒 在刀下,并非 人的刀;有刀 要将他吞灭,并非 人的刀。他 必逃避 这刀;他的少年人 必成为 服苦的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, '他的磐石 必因惊吓 挪去;他的首领 必因大旗 惊惶。这是那 有火 在锡安、有炉 在耶路撒冷 的耶和华 说的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, '看哪,必有一王 凭公义 行政;必有首领 藉 借公平 掌权。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, '必有 一人 像避风 所 和避暴雨 的隐密处,又像河 流 在干旱之地,像大 磐石 的影子 在疲乏 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, '那能看的人,眼 不 再昏迷;能听的人,耳 必得听闻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, '冒失人 的心 必明白 知识;结巴人 的舌 必说话 通 快。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, '愚顽人 不 再 称为 高明;吝啬人 不 再称为 大方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, '因为 愚顽人 必说 愚顽话,心里 想作 罪孽,惯行 亵渎的事,说 错谬的话 攻击 耶和华,使饥饿 的人 无食可吃,使口渴的人 无 水可喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, '吝啬人 所用的法子 是恶的;他 图谋 恶计,用谎 言 毁灭 谦卑人;穷乏人 讲 公理的时候,他也是这样行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, '高明人 却谋 高明事,在 高明事 上也必 永存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, '安逸的 妇女啊,起来 听 我的声音!无虑的 女子啊,侧耳 听我的言语! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, '无虑的女子啊,再过 一年 多,必受骚扰;因为 无葡萄 可摘,无果子(或译:禾稼)可收。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, '安逸的妇女啊,要战 兢;无虑的女子啊,要受骚扰。脱去衣服,赤著身体, 腰 束麻布。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, '她们必为 美好的 田地 和 多结果的 葡萄树,搥 胸 哀哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, '荆棘 蒺藜 必长 在 我百姓 的地上,又 长在 欢乐的 城 中和一切 快乐 的房屋上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, '因为 宫殿 必被撇下,多民的 城 必被离弃;山冈 望楼 永 为 洞穴,作野驴 所喜乐的,为羊群 的草场。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, '等到 圣灵 从上 浇灌 我们,旷野 就变为 肥田,肥田 看如 树林。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, '那时,公平 要居 在旷野;公义 要居 在肥田。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, '公义 的果效 必是 平安;公义 的效验 必是平稳,直到 永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, '我的百姓 必住 在平安的 居所,安稳的 住处,平静的 安歇所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, '(但要降冰雹 打倒 树林;城 必全然拆 平。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, '你们在 各 水 边撒种、牧放 牛 驴 的有福了!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, '祸哉!你 这毁灭人的,自己倒不 被毁灭;行事诡诈的,人倒不 以诡诈 待你。你毁灭 罢休了,自己必被毁灭;你行完了 诡诈,人必以诡诈 待你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, '耶和华啊,求你施恩于 我们;我们等候 你。求你每早晨 作 我们的膀臂,遭难 的时候 为 我们的拯救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, '喧嚷 的响声一发,众民 奔逃;你一兴起,列国 四散。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, '你们所掳的 必被敛尽,好像蚂蚱吃(原文是敛)尽禾稼。人要蹦 在其上,好像 蝗虫一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, '耶和华 被尊崇,因 他居 在高处;他以公平 公义 充满 锡安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, '你一生一世 必得 安稳─有丰盛 的救恩,并智慧 和知识;你以敬畏 耶和华 为 至宝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, '看哪,他们的豪杰 在外头 哀号;求和 的使臣 痛痛 哭泣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, '大路 荒凉,行 人 止息;敌人背 约,藐视 城邑,不 顾 人民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, '地上 悲哀 衰残;黎巴嫩 羞愧 枯干;沙仑  像 旷野;巴珊 和迦密 的树林凋残。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, '耶和华 说:现在 我要起来; 我要兴起; 我要勃然而兴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, '你们要怀 的是糠秕,要生 的是碎秸;你们的气 就是吞灭 自己的火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, '列邦 必 像已烧的 石灰,像已割的 荆棘 在火中 焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, '你们远方的 人当听 我所 行的;你们近处的 人当承认 我的大能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, '锡安中 的罪人 都惧怕;不敬虔的人 被战 兢 抓住。我们中间 谁 能与吞灭 的火 同住?我们中间 谁 能与永 火 同住呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, '行事 公义、说话 正直、憎恶 欺压的 财利、摆 手 不受 贿赂、塞 耳 不听 流血的话,闭 眼 不看 邪恶事的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, '他 必居 高处;他的保障 是磐石 的坚垒;他的粮必不缺乏(原文是赐给);他的水 必不断绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, '你的眼 必见 王 的荣美,必见 辽阔 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, '你的心 必思想 那惊吓的事,自问说:记数目的 在哪里呢?平贡银的 在哪里呢?数 戍楼 的在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, '你必不 见 那 强暴的 民,就是说话 深奥,你不能明白,言语 呢喃,你不 能懂得 的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, '你要看 锡安─我们守圣节 的城!你的眼 必见 耶路撒冷 为安静的 居所,为不 挪移 的帐幕,橛子 永 不 拔出, 绳索 一根也不 折断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, '在那里,耶和华 必 显威严 与我们同在,当作江河 宽阔 之地;其中 必没有 荡桨摇橹 的船 来往,也没有 威武的 船 经过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, '因为,耶和华 是审判我们的;耶和华 是给我们设律法的;耶和华 是我们的王;他 必拯救我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, '你的绳索 松开 :不能 栽 稳 桅杆,也不能 扬起 篷来。那时 许多 掳来的 物 被分了;瘸腿的 把掠物 夺去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, '城内居民 必不 说:我病了;其中 居住的 百姓,罪孽 都赦免了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, '列国啊,要近前来 听!众民哪,要侧耳而听!地 和其上所充满的,世界 和其中一切 所出的 都应当听! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, '因为 耶和华 向 万 国 发忿恨,向 他们的全 军 发烈怒,将他们灭尽,交出 他们受杀戮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, '被杀的 必然抛弃,尸首 臭气 上腾;诸山 被他们的血 融化。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, '天上 的万 象 都要消没;天 被卷起,好像书卷。其上的万 象 要残败,像葡萄树的 叶子 残败,又像无花果树的 叶子残败一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, '因为 我的刀 在天上 已经喝足; 这刀必临 到 以东 和 我所咒诅 的民,要施行审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, '耶和华的 刀 满了 血,用脂油 和羊羔、公山羊 的血,并公绵羊 腰子 的脂油 滋润的;因为 耶和华 在波斯拉 有献祭的事,在以东 地 大 行杀戮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, '野牛、牛犊,和 公牛 要一同 下来。他们的地 喝醉 了血;他们的尘土 因脂油 肥润。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, '因 耶和华 有报仇 之日,为锡安 的争辩 有报应 之年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, '以东的河水 要变 为石油,尘埃 要变为硫磺;地土 成为 烧著的 石油, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, '昼 夜 总不 熄灭,烟气 永远 上腾,必世世 代代 成为荒废,永永远远 无人 经过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, '鹈鹕、箭猪 却要得为业;猫头鹰、乌鸦 要住 在其间。耶和华 必将空虚的 准绳,混沌的 线 缐铊,拉 在其上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, '以东人要召 贵胄 来治国;那里 却无一个,首领 也都 归 于 无有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, '以东的宫殿 要长 荆棘;保障 要长蒺藜 和刺草;要作 野狗 的住处,鸵鸟 的居所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, '旷野 的走兽要和 豺狼 相遇;野山羊 要与 伴偶 对叫。夜间的怪物 必 在那里 栖身,自 找 安歇之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, '箭蛇 要在那里 做窝,下蛋,菢蛋,生子,聚 子在其影下;鹞鹰 各 与伴偶 聚集 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, '你们要查考 宣读 耶和华 的书。这 都无 一 缺少,无 一 没有 伴偶;因为 我的口 已经吩咐,他的灵 将他们聚集。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, '他 也为他们 拈 阄,又亲手 用准绳 给他们 分地;他们必永 得为业,世世 代代 住 在其间。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, '旷野 和干旱之地 必然欢喜;沙漠 也必快乐;又像玫瑰 开 花, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, '必开 花 繁盛,乐 上加 乐,而且欢呼。黎巴嫩 的荣耀,并迦密 与沙仑  的华美,必赐 给它。人 必看见 耶和华 的荣耀,我们 神 的华美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, '你们要使软弱的 手 坚壮,无力的 膝 稳固。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, '对胆怯的 人 说:你们要刚强,不要 惧怕。看哪,你们的 神 必来报仇, 必来 施行极大的报应;他 必来 拯救你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, '那时,瞎子 的眼 必睁开 ;聋子 的耳 必开 通。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, '那时,瘸子 必跳跃 像鹿;哑巴 的舌头 必能歌唱。在旷野 必 有水 发出;在沙漠 必有河涌流。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, '发光的沙(或译:蜃楼)要变 为水池;干渴之地 要变为泉源。在野狗 躺卧 之处,必有青草、芦苇,和蒲草。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, '在那里 必有 一条大道, 称 为 圣 路。污秽人 不 得经过,必 专为赎民行走;行 路 的人虽愚昧,也不致 失迷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, '在那里 必 没有 狮子,猛 兽 也不 登这路;在那里 都遇 不见,只有赎民 在那里行走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, '并且耶和华 救赎的民 必归回,歌唱 来到 锡安;永 乐 必归到 他们的头上;他们必得著 欢喜 快乐,忧愁 叹息 尽都逃避。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, ' 希西家 王 十 四 年,亚述 王 西拿基立 上来 攻击 犹大 的一切 坚固 城,将城攻取。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, '亚述 王 从拉吉 差遣 拉伯沙基 率领大 军 往耶路撒冷,到 希西家 王那里去。他就站 在上 池 的水沟旁,在漂布 地 的大路上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, '于 是希勒家 的儿子 家 宰 以利亚敬,并书记 舍伯那 和亚萨 的儿子 史官 约亚,出来 见拉伯沙基。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, '拉伯沙基 对他们 说:「 你们去 告诉希西家 说,亚述 大 王 如此说:『你所 倚靠的 有什么 可仗赖 的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, '你说,有打仗的 计谋 和能力,我看不过 是虚 话。你到底 倚靠 谁 才 背叛 我呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, '看哪,你所倚靠 的埃及 是那 压伤的 苇 杖,人 若靠 这杖,就必刺 透 他的手。埃及 王 法老 向一切 倚靠 他 的人也是这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, '你若 对我 说:我们倚靠 耶和华─我们的 神。希西家 岂 不是 将 神的 邱坛 和 祭坛 废去,且对犹大 和耶路撒冷 的人说:你们当在这 坛 前 敬拜吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, '现在 你 把当头 给 我主 亚述 王,我给 你 二千 匹马,看 你 这一面骑马 的人 够不够。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, '若不然,怎能 打败 我主 臣仆 中最小的 军长呢?你 竟倚靠 埃及 的战 车 马兵吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, '现在 我上来 攻击 毁灭 这 地,岂没有 耶和华的意思吗?耶和华 吩咐我 说,你上去 攻击 毁灭 这 地吧!』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, '以利亚敬、舍伯那、约亚 对 拉伯沙基 说:「求你 用亚兰言语 和 仆人 说话,因为 我们 懂得;不要 用犹大言语 和我们 说话,达到 城上 百姓 的耳中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, '拉伯沙基 说:「我主 差遣我来,岂是单对你 和 你的主 说 这些 话吗?不 也是对 这些坐 在 城上、要与你们 一同吃 自己粪 喝 自己尿 的人说吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, '于 是,拉伯沙基 站著,用犹大言语 大 声 喊著 说:「你们当听 亚述 大 王 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, '王 如此 说:『你们 不要 被希西家 欺哄了,因 他不 能 拯救 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, '也不要 听希西家 使你们 倚靠 耶和华 说:耶和华 必要 拯救我们,这 城 必不 交 在亚述 王 的手中。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, '不要 听 希西家的话,因 亚述 王 如此 说:『你们要与我 和好。出来 投降我,各人 就可以吃 自己葡萄树 和 无花果树的果子, 喝 自己井 里的水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, '等 我来 领 你们 到 一个地方,与你们本地一样,就是有五谷 和新酒 之地,有粮食 和葡萄园 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, '你们要谨防,恐怕 希西家 劝导 你们 说:耶和华 必拯救我们。列国 的神 有哪一个 救 他本国 脱离亚述 王 的手呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, '哈马 和亚珥拔 的神 在哪里呢?西法瓦音 的神 在哪里呢? 他们曾救 撒马利亚 脱离我的手吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, '这些 国的 神 有 谁 曾救 自己的国 脱离我的手呢?难道 耶和华 能救 耶路撒冷 脱离我的手吗?』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, '百姓静默不言,并不 回答 一句,因为 王 曾吩咐 说:「不要 回答他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, '当下希勒家 的儿子 家 宰 以利亚敬 和书记 舍伯那,并亚萨 的儿子 史官 约亚,都撕裂 衣服,来 到 希西家那里,将 拉伯沙基 的话 告诉 了他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, ' 希西家 王 听见 就撕裂 衣服,披上 麻布,进了 耶和华 的殿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, '使 家 宰 以利亚敬 和 书记 舍伯那,并 祭司 中的长老,都披上 麻布,去见 亚摩斯 的儿子 先知 以赛亚, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, '对他 说:「希西家 如此 说:『今 日 是急难、责罚、凌辱 的日子,就 如妇人将 要 生产 婴孩,却没有 力量 生产。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, '或者 耶和华─你的 神 听见 拉伯沙基 的话,就是 他主人 亚述 王 打发他 来辱骂 永生 神 的话; 耶和华─你的 神 听见 这话 就发斥责。故此,求你为 余 馀剩 的民 扬声 祷告。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, '希西家 王 的臣仆 就去 见 以赛亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, '以赛亚 对他们 说:「要这样 对 你们的主人 说,耶和华 如此 说:『 你听见 亚述 王 的仆人 亵渎 我 的话,不要 惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, '我必惊动(原文是使灵 进入)他的心;他要听见 风声 就归 回 本地,我必使他在那里 倒 在刀下。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, '拉伯沙基 回去,正遇见 亚述 王 攻打 立拿;原来 他早听见 亚述王拔营离开  拉吉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, '亚述王听见 人论 古实 王 特哈加 说:「他出来 要与你 争战 。」亚述王一听见,就打发 使者 去见 希西家,吩咐他们说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, '「你们 对 犹大 王 希西家 如此 说:『不要 听你 所 倚靠的 神 欺哄你 说:耶路撒冷 必不 交 在亚述 王 的手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, ' 你 总听说 亚述 诸王 向列 国 所 行的 乃是尽行灭绝,难道你 还能得救吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, '我列祖 所 毁灭的,就是 歌散、 哈兰、利色,和属提‧拉撒 的伊甸 人;这些国 的神 何曾拯救这些国呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, '哈马 的王,亚珥拔 的王,西法瓦音 城的 王,希拿 和以瓦的王,都在哪里呢?』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, '希西家 从使者 手 里接过 书信来,看完了,就上 耶和华 的殿, 将书信在耶和华 面前 展开 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, '希西家 向 耶和华 祷告 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, '「坐在 二基路伯 上万军 之耶和华─以色列的 神啊,你─惟有你 是 天下 万 国的 神,你 曾创造 天 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, '耶和华啊,求你侧 耳 而听;耶和华啊,求你睁 眼 而看,要听 西拿基立 的一切 话, 他是打发 使者来辱骂 永生 神的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, '耶和华啊,亚述 诸王 果然 使 列 国 和 列国之地 变为荒凉, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, '将 列国的神 像都扔 在火里;因为 他 本不是 神,乃是 人 手 所造的,是木头、石头的,所以灭绝他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, '耶和华─我们的 神啊,现在 求你救我们 脱离亚述王的手,使天下 万国 都 知道 惟有 你 是耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, '亚摩斯 的儿子 以赛亚 就打发 人去见 希西家,说:「耶和华─以色列的 神 如此 说,你既然 求 我 攻击 亚述 王 西拿基立, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, '所以 耶和华 论他 这样 说:锡安 的 处女 藐视 你,嗤笑 你;耶路撒冷 的女子 向你 摇 头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, '你辱骂 谁,亵渎谁?扬起 声来,高 举 眼目 攻击 谁呢?乃是攻击 以色列 的圣者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, '你藉 借 你的臣仆 辱骂 主 说:我 率领许多 战 车 上 山 顶,到黎巴嫩 极深之处;我要砍伐 其中高大的 香柏树 和佳美的 松树。我必上 极高 之处,进入肥田 的树林。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, '我 已经挖 井喝 水;我必用脚 掌 踏干 埃及 的一切 河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, '耶和华说:你岂没有 听见 我早先 所做的、古 时 所立的吗?现在 藉 借你 使 坚固 城 荒废,变为乱 堆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, '所以其中的居民 力量 甚小,惊惶 羞愧。他们 像野 草,像青 菜,如房顶上 的草,又如田间 未 长成的禾稼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, '你坐下,你出去,你进来,你向我发 烈怒,我都知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, '因 你向我 发烈怒,又因你狂傲的话 达到 我耳中,我就要用钩子 钩上 你的鼻子,把嚼环 放在你口里,使你从原路 转回去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, '「以色列人哪, 我赐你们 一个证据:你们今年 要吃 自生的,明 年 也要吃自长的,至于 后 年,你们要耕种 收割,栽植 葡萄园,吃 其中的果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, '犹大 家 所逃脱 余 馀剩的,仍要 往下 扎根,向上 结 果。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, '必有 余 馀剩的民 从耶路撒冷 而出;必有逃脱的人 从锡安 山而来。万军 之耶和华 的热心 必成就 这事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, '「所以 耶和华 论 亚述 王 如此 说:他必不得 来 到 这 城,也不 在这里 射 箭,不得 拿盾牌 到城前,也不 筑 垒 攻城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, '他从哪 条路 来,必从那条路 回去,必不得 来 到 这 城。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, '因我为自己的缘故,又为我仆人 大卫 的缘故,必保护 拯救 这 城。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, '耶和华 的使者 出去,在亚述 营中 杀了 十八万 五 千人。清早 有人起来 一看,都是 死 尸了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, '亚述 王 西拿基立 就拔营 回 去,住 在尼尼微。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, '一日 在他的神─尼斯洛 庙里 叩拜,他儿子 亚得米勒 和沙利色 用刀 杀了他, 就逃 到亚拉腊地。他儿子 以撒哈顿 接续他 作王。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, '那 时 希西家 病得 要死,亚摩斯 的儿子 先知 以赛亚 去 见他,对他 说:「耶和华 如此 说:你当留遗命 与你的家,因为 你 必死 不能 活了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, '希西家 就转 脸 朝 墙,祷告 耶和华 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, '「耶和华啊, 求你 记念 我在你面前 怎样 存完全的 心,按诚实 行事,又做 你眼中 所看为善的。」希西家 就痛 哭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, '耶和华 的话 临 到 以赛亚 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, '「你去 告诉 希西家 说,耶和华─你祖 大卫的 神 如此 说:我听见了 你的祷告,看见了 你的眼泪。我 必加增 你十 五 年 的寿数; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, '并且我要救你 和 这 城 脱离亚述 王 的手,也要保护 这 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, '「我─耶和华必 成就 我所 说的。 我先 给你 一个兆头, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, ' 就是 叫 亚哈斯 的日 晷,向前进 的 日 影 往后 退 十 度。」于 是, 前进 的日影 果然在日晷上 往后退了 十 度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, '犹大 王 希西家 患 病 已经痊愈,就作诗说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, '我 说:正在我中年(或译:晌午)之日 必进入 阴间 的门;我余 馀剩的 年岁 不得享受。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, '我说:我必不 得见 耶和华,就是在活人 之地 不见耶和华;我与 世上 的居民 不 再 见面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, '我的住处 被迁去 离开  我,好像牧人 的帐棚一样;我将性命 卷起,像织布的卷布一样。耶和华 必将我从机头 剪断,从早 到 晚,他要使我完结。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, '我使自己安静 直到 天亮;他像狮子 折断 我一切的 骨头,从早 到 晚,他要使我完结。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, '我像燕子呢喃,像 白鹤 鸣叫,又像鸽子 哀鸣;我因仰观,眼睛 困倦。耶和华啊,我 受欺压,求你为我作保。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, '我可说 什么呢?他应许 我的,也 给我成就了。我因 心里 的苦楚,在一生 的年日 必悄悄而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, '主啊,人得存活 乃在乎此。我灵 存活 也全 在此。所以求你使我痊愈,仍然存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, '看哪,我 受 大苦,本为使我得平安;你 因爱 我的灵魂(或译:生命)便救我脱离败坏的 坑,因为 你将我一切的 罪 扔 在 你的背后。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, '原来,阴间 不能 称谢你,死亡 不能颂扬你;下 坑 的人不能 盼望 你的诚实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, '只有活人,活人 必 称谢你,像我 今日称谢你一样。为父的,必使儿女 知道 你的诚实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, '耶和华 肯救我,所以,我们要一生 一 世 在 耶和华 殿中 用丝弦的乐器 唱我的诗歌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, '以赛亚 说:「当取 一块无花果 饼来,贴 在 疮上,王必痊愈。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, '希西家 问说:「我能 上 耶和华 的殿,有什么 兆头呢?」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, '那 时,巴比伦 王 巴拉但 的儿子米罗达‧巴拉但 听见 希西家 病 而痊愈,就送 书信 和礼物 给他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, '希西家 喜欢 见使者,就把 自己宝 库的 金子、 银子、 香料、 贵重的 膏油,和 他武库 的一切 军器,并 所有的 财宝 都给他们看;他家中 和全 国之内,希西家 没 有 一样 不 给他们看的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, '于 是先知 以赛亚 来 见 希西家 王,问他 说:「这些 人 说 什么?他们从哪里 来 见你?」希西家 说:「他们从远 方 的巴比伦 来 见我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, '以赛亚说:「他们在你家里 看见了 什么?」希西家 说:「 凡 我家中 所有的,他们都看见了;我财宝中 没 有 一样 不 给他们看的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, '以赛亚 对 希西家 说:「你要听 万军 之耶和华 的话: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, ' 日子 必到,凡 你家里 所有的,并 你列祖 积蓄 到 如 今的,都要被掳到 巴比伦去,不 留下 一样;这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, '并且从你 本身所 生的 众子,其中 必有被掳去、在巴比伦 王 宫里 当 太监的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, '希西家 对 以赛亚 说:「你所 说 耶和华 的话 甚好, 因为 在我的年日中 必有 太平 和稳固的景况。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, '你们的 神 说:你们要安慰,安慰 我的百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, '要对 耶路撒冷 说 安慰的话,又向她 宣告说, 她争战  的日子已满了; 她的罪孽 赦免了; 她为自己的一切 罪,从耶和华 手中 加倍 受罚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, '有人声 喊著说:在旷野 预备 耶和华 的路(或译:在旷野,有人声喊著说:当预备耶和华的路),在沙漠地 修平我们 神 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, '一切 山洼 都要填满,大小 山 冈 都要削平;高高低低的 要改为 平坦,崎崎岖岖 的必成为平原。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, '耶和华 的荣耀 必然显现;凡 有血气的 必一同 看见;因为 这是耶和华 亲口 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, '有人声 说:你喊叫吧!有一个说:我喊叫 什么呢?说:凡 有血气的 尽都如草;他的美容 都 像野地 的花。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, '草 必枯干,花 必凋残,因为 耶和华 的气 吹 在其上;百姓 诚然 是草。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, '草 必枯干,花 必凋残,惟有我们 神 的话 必永远 立定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, '报好信息 给锡安的啊,你 要登 高 山;报好信息 给耶路撒冷的啊,你要极力 扬 声。扬声 不要 惧怕,对犹大 的城邑 说:看哪,你们的 神! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, ' 主 耶和华 必像大能者 临到;他的膀臂 必为他 掌权。 他的赏赐 在他那里;他的报应 在他面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, '他必像牧人 牧养 自己的羊群,用膀臂 聚集 羊羔 抱 在怀中,慢慢引导 那乳养小羊的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, '谁 曾用手心 量 诸水,用手虎口 量 苍天,用升斗 盛 大地 的尘土,用秤 称 山岭,用天平 平冈陵呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, '谁 曾测度 耶和华 的心(或译:谁曾指示耶和华的灵),或作他的谋 士 指教他呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, '他与 谁 商议,谁教导他,谁将公平 的路 指示他,又将知识 教训他,将通达 的道 指教他呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, '看哪,万民 都像水桶 的一滴,又算 如天平上 的微尘; 他举起 众海岛,好像极微之物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, '黎巴嫩 的树林不 够 当柴烧;其中的走兽 也不 够 作燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, '万 民 在他面前 好像虚无,被他 看为 不及虚无,乃为虚空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, '你们究竟将 谁 比 神,用什么 形像与 神 比较呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, '偶像 是匠人 铸造,银匠 用金 包裹,为它铸造 银 炼 链 𫔀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, '穷乏 献不起这样供物的,就拣选 不能 朽坏 的树木,为自己 寻找 巧 匠,立起 不能 摇动 的偶像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, '你们岂不 曾知道吗?你们岂不 曾听见吗?从起初 岂没有 人告诉 你们吗?自从立地 的根基,你们岂没有 明白吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, '神坐 在 地球 大圈之上;地上的居民 好像蝗虫。他铺张 穹苍 如幔子,展开  诸天如可住 的帐棚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, '他使 君王 归于 虚无,使地上 的审判官 成为 虚空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, '他们是刚才(或译:不曾;下同)栽上, 刚才 种上,根 也 刚才 扎 在地里,他一 吹 在其上,便都枯干;旋风 将他们吹去,像碎秸一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, '那圣者 说:你们将 谁 比我,叫他与我相等呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, '你们向上 举 目,看 谁 创造 这 万象,按数目 领出,他一一 称 其名;因他的权能,又因他的大 能 大 力,连一个 都不 缺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, '雅各啊,你为何 说,我的道路 向耶和华 隐藏?以色列啊,你为何言,我的冤屈 神并不 查问? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, '你岂不 曾知道吗?你岂 不 曾听见吗?永在的 神 耶和华,创造 地 极的主,并不 疲乏,也不 困倦;他的智慧 无法 测度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, '疲乏的,他赐 能力;软弱的,他加 力量。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, '就是少年人 也要疲乏 困倦;强壮的 也必全然 跌倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, '但那等候 耶和华 的必重新得 力。他们必如鹰 展翅 上腾;他们奔跑 却不 困倦,行走 却不 疲乏。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, '众海岛啊,当在我面前 静默;众民 当重新得 力,都要近前来 才可 以说话,我们可以 彼此 辩论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, '谁 从东方 兴起一人,凭公义 召他 来到脚前呢?耶和华将列国 交 给他,使他管辖 君王,把他们如灰尘 交 与他的刀,如风吹 的碎秸 交与他的弓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, '他追赶他们,走他 所未 走 的道,坦然 前行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, '谁 行做 成就这事,从起初 宣召 历代呢?就是我─耶和华!我 是 首先的,也与 末后的同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, '海岛 看见 就都害怕;地 极 也都战 兢,就近前 来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, '他们各人 帮助 邻舍,各人对弟兄 说:壮胆吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, '木匠 勉励 银匠,用锤 打光的勉励 打 砧的,论銲工说, 銲 得好;又用钉子 钉稳,免得 偶像动摇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, '惟你 以色列─我的仆人,雅各─我所 拣选的,我朋友 亚伯拉罕 的后裔, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, '你是我从地 极 所领(原文是抓)来的,从地角 所召来的,且对你 说:你 是我的仆人;我拣选你,并不 弃绝你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, '你不要 害怕,因为 我 与你同在;不要 惊惶,因为 我是你的 神。我必坚固你,我必 帮助你;我必 用我公义 的右手 扶持你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, '凡 向你 发怒的 必都抱愧 蒙羞;与你相争 的 必 如无有,并要灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, ' 与你争竞的,你要找他们 也找 不著; 与你争战  的必如无有,成为 虚无。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, '因为 我 耶和华─你的 神 必搀扶 你的右手,对你 说:不要 害怕!我 必帮助你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, '你这虫 雅各 和你们以色列 人,不要 害怕!耶和华 说:我 必帮助你。你的救赎主 就是以色列 的圣者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, '看哪,我已使你成为 有 快 齿 打粮的新 器具;你要把山岭 打得 粉碎,使 冈陵 如同糠秕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, '你要把它簸扬,风 要吹去;旋风 要把它 刮散。你 倒要以耶和华 为喜乐,以以色列的 圣者 为夸耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, '困苦 穷乏人 寻求 水 却没有;他们因口渴,舌头 干燥。我─耶和华 必应允他们;我─以色列的 神 必不 离弃他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, '我要在 净光的高处 开  江河,在谷 中 开 泉源;我要使沙漠 变为 水 池,使干 地 变为涌 泉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, '我要在旷野 种上 香柏树、皂荚树、番石榴树,和野橄榄 树。我在沙漠 要把松树、杉树,并黄杨树 一同 栽植; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, '好 叫人看见、知道、思想、明白; 这 是耶和华 的手 所做的,是以色列 的圣者 所造的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, '耶和华 对假神说:你们要呈上 你们的案件;雅各 的君 说:你们要声明 你们确实的理由。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, '可以声明,指示 我们 将来必遇的事,说明 先前的 是 什么事,好叫我们思索,得知 事的结局,或者 把将来 的事指示我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, '要说明 后 来的事,好叫我们知道 你们是 神。你们或 降福,或降祸,使我们惊奇,一同 观看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, '看哪,你们 属乎虚无;你们的作为 也属乎虚空。那选择 你们 的是可憎恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, '我从北方 兴起一人;他是求告 我名的,从日 出 之地而来。他必临到 掌权的,好像 临到灰泥,仿佛 窑匠 踹 泥一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, '谁 从起初 指明这事,使我们知道呢?谁从先前说明,使我们说 他不错呢?谁也 没有 指明;谁也 没有 说明;谁也 没有 听见 你们的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, '我首先 对锡安说:看哪, 我要将一位报好信息的 赐 给耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, '我看 的时候并没有 人;我问的时候,他们中间 也没有 谋士 可以回答 一句。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, '看哪,他们和他们的工作 都是 虚空,且是虚无。他们所铸的偶像 都是风,都是虚的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, '看哪,我的仆人─我所扶持 所拣选、心里 所喜悦的!我已将我的灵 赐 给他;他必将公理 传 给外邦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, '他不 喧嚷,不 扬声,也不 使街上 听见 他的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, '压伤 的芦苇,他不 折断;将残 的灯火,他不 吹灭。他凭真实 将公理 传开 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, '他不 灰心,也不 丧胆,直到 他在地上 设立 公理;海岛 都等候 他的训诲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, '创造 诸天,铺张穹苍,将地 和地所出的 一并铺开 ,赐 气息 给地上 的众人,又赐灵性 给行 在其上之人的 神 耶和华,他如此 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, '我─耶和华 凭公义 召你,必搀扶 你的手,保守你,使你 作众民的中保(中保:原文是约),作外邦人 的光, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, '开  瞎子 的眼,领 被囚的 出牢狱,领坐 黑暗 的出监 牢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, '我 是耶和华,这是 我的名;我必不 将我的荣耀 归 给假神,也不将我的称赞 归给雕刻的偶像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, '看哪,先前的 事已经成就,现在我 将新 事说明,这事未发 以先,我就说给你们 听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, '航 海 的和海中所有的,海岛 和其上的居民,都当向耶和华 唱 新 歌,从地 极 赞美他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, '旷野 和其中的城邑,并基达人 居住 的村庄 都当扬声;西拉 的居民 当欢呼,在山 顶上 呐喊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, '他们当将荣耀 归 给耶和华,在海岛 中传扬 他的颂赞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, '耶和华 必像勇士 出去,必像战  士 激动 热心,要喊叫, 大声呐喊,要用大力 攻击 仇敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, '我许久 闭口不言,静默 不语;现在我要喊叫,像产难的妇人;我要急气 而 喘哮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, '我要使大山 小冈 变为荒场,使其上的花草 都 枯干;我要使江河 变为 洲岛,使水池 都干涸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, '我要引 瞎子 行不 认识 的道,领他们 走不 知道 的路;在他们面前 使黑暗 变 为光明,使弯曲 变为平直。这些 事 我都要行,并不 离弃他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, '倚靠 雕刻的偶像,对铸造的偶像 说:你 是我们的神;这等人要退 后,全然蒙 羞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, '你们这耳聋的,听吧!你们这眼瞎的,看吧!使你们能看见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, '谁比 我的仆人 眼瞎呢?谁比我差遣 的使者 耳聋呢?谁 瞎眼 像那与我和好的?谁瞎眼 像耶和华 的仆人呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, '你看见 许多 事却不 领会,耳朵 开 通 却不 听见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, '耶和华 因自己公义 的缘故,喜欢 使律法(或译:训诲)为大,为尊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, '但这 百姓 是被抢 被夺的,都 牢笼 在坑中,隐藏 在狱 里;他们作 掠物,无人 拯救,作掳物,无人 说 交还。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, '你们中间 谁 肯侧耳听 此,谁肯留 心而听,以防将来呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, '谁 将雅各 交出 当作掳物,将以色列 交给抢夺的呢?岂不是 耶和华吗?就是我们所得罪的 那位。他们不 肯 遵行 他的道,也不 听从 他的训诲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, '所以,他将猛烈 的怒气 和争战  的勇力 倾倒 在以色列的身上。在他四围 如火著起,他还不 知道,烧著 他,他也不 介意。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, '雅各啊,创造你 的耶和华,以色列啊,造成你的那位,现在 如此 说:你不要 害怕!因为 我救赎了你。我曾提你的名 召你,你 是属我的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, ' 你从水中 经过,我 必与你同在;你蹚过江河,水必不 漫过你; 你从火 中 行过,必不 被烧,火焰 也不 著 在你身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, '因为 我 是耶和华─你的 神,是以色列 的圣者─你的救主;我已经使 埃及 作你的赎价,使古实 和西巴 代替你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, '因 我看 你为宝 为尊;又因我 爱你,所以我使 人 代替你,使列邦人 替换 你的生命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, '不要 害怕,因 我 与你同在;我必领你的后裔 从东方 来,又从西方 招聚你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, '我要对北方 说,交出来!对南方说,不要 拘留!将我的众子 从远方 带来,将我的众女 从地 极领回, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, '就是凡 称为 我名下的人,是我为自己的荣耀 创造的,是我所做成, 所造作的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, '你要将有 眼 而瞎、有 耳 而聋 的民 都带出来! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, '任凭万 国 聚 集;任凭众民 会合。其中 谁 能将此 声明,并将先前的事 说给我们听呢?他们可以带出 见证来,自显为是;或者他们听见 便说:这是真的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, '耶和华 说:你们 是我的见证,我所 拣选 的仆人。既是这样,便可以知道,且信服 我,又明白 我就是耶和华。在我以前 没有 真神(真:原文是造作的);在我以后 也必没 有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, '惟有我 是 耶和华;除我以外 没有 救主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, '我 曾指示,我曾拯救,我曾说明,并且在你们中间 没有 别神。所以耶和华 说:你们 是我的见证。我也是 神; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, ' 自从有日子以来,我就是 神;谁也不能 救 人脱离我手。我要行事 谁 能阻止呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, '耶和华─你们的救赎主、以色列 的圣者 如此 说:因你们的缘故,我已经打发人 到巴比伦去;并且我要使迦勒底人 如逃民,都 坐自己喜乐 的船 下来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, '我 是耶和华─你们的圣者,是创造 以色列的,是你们的君王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, '耶和华在沧海中 开  道,在大 水中 开 路, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, '使车辆、马匹、军兵、勇士 都出来,一同 躺下,不再 起来;他们灭没,好像熄灭 的灯火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, '耶和华 如此 说:你们不要 记念 从前的事,也不要 思想 古时的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, '看哪,我 要做 一件新事;如今 要发现,你们岂不 知道吗?我必 在旷野 开  道路,在沙漠 开 江河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, '野地 的走兽 必尊重我;野狗 和鸵鸟也必如此。因 我使 旷野 有水,使沙漠 有河,好赐给我的百姓、我的选民 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, '这 百姓 是我为自己 所造的,好述说 我的美德。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, '雅各啊,你并没有 求告 我; 以色列啊,你倒厌烦 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, '你没有 将你的羊 带来 给我 作燔祭,也没有 用祭物 尊敬我;我没有 因供物 使你服劳,也没有 因乳香 使你厌烦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, '你没有 用银子 为我 买  菖蒲,也没有 用祭物 的脂油 使我饱足;倒 使我因你的罪恶 服劳,使我因你的罪孽 厌烦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, '惟有我 为自己的缘故 涂抹 你的过犯;我也不 记念 你的罪恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, '你要提醒我,你我可以一同 辩论;你 可以将你的理陈明, 自显为义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, '你的始 祖 犯罪;你的师傅 违背 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, '所以,我要辱没 圣所 的首领,使雅各 成为 咒诅,使以色列 成为辱骂。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, '我的仆人 雅各,我所拣选的 以色列啊,现在 你当听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, '造作你,又从你出胎 造就你,并要帮助你 的耶和华 如此 说:我的仆人 雅各,我所拣选的 耶书仑 哪,不要 害怕! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, '因为 我要将水 浇灌 口渴的人,将河浇灌 干旱之地。我要将我的灵 浇灌 你的后裔,将我的福浇灌 你的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, '他们要发生 在草 中,像溪 水 旁 的柳树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, '这个 要说:我 是属耶和华的;那个 要以雅各 的名 自称;又一个 要亲手 写:归耶和华的(或译:在手上写归耶和华),并自称为 以色列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, '耶和华─以色列 的君,以色列的救赎主─万军 之耶和华 如此 说:我 是首先的,我 是末后的;除我以外 再没有 真神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, '自从我设立 古时 的民,谁 能像我 宣告,并且指明,又为自己 陈说呢?让他将未来 的事和 必成 的事说明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, '你们不要 恐惧,也不要 害怕。我岂不 是从上古 就说明 指示你们吗?并且你们 是我的见证!除我以外,岂有 真神吗?诚然没有 磐石,我不 知道一个! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, '制造 雕刻偶像 的尽都 虚空;他们所喜悦的 都无 益处;他们 的见证 无 所看见,无 所知晓, 他们便觉羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, '谁 制造 神像,铸造 无 益 的偶像? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, '看哪,他的同伴 都 必羞愧。工匠 也不过是 人,任他们聚会,任他们 站立,都必惧怕,一同 羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, '铁 匠 把铁 在火炭中 烧热,用锤 打铁器,用他有力 的膀臂锤成; 他饥饿 而无 力,不 喝 水 而发倦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, '木 匠 拉 线 缐,用笔 划 㓰出样子,用铇子 铇成形状,用圆尺 划 㓰了模样,仿照人 的体态,做成 人 形,好住 在房屋中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, '他 砍伐 香柏树,又取柞(或译:青桐)树 和橡树,在树 林 中选定了一棵。他栽种 松树,得雨 长养。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, '这树,人 可用以烧火;他自己取 些 烤火,又 烧著 烤 饼,而且 做 神像 跪拜,做 雕刻的偶像 向它 叩拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, '他把一分 烧 在火 中,把 一分 烤 肉 吃 饱。 自己烤火 说:「啊哈,我暖和了,我见 火了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, '他用剩下的 做了 一神,就是雕刻的偶像。他向这偶像 俯伏 叩拜,祷告 它 说:「求你拯救我,因 你 是我的神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, '他们不 知道,也不 思想;因为 耶和华闭住 他们的眼,不能看见,塞住他们的心,不能明白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, '谁 心 里也不 醒悟,也没有 知识,没有 聪明,能说:「我曾拿一分 在火 中 烧了, 在 炭火 上烤过 饼;我也烤过 肉 吃。这剩下的,我岂要作 可憎的物吗?我岂可向木 墩子 叩拜呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, '他以灰 为食,心 中昏迷,使他偏邪,他不能自 救,也不能 说:「我右手中 岂不是 有虚谎吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, '雅各,以色列啊, 你 是我的仆人,要记念 这些事。以色列啊,你 是我的 仆人,我造就你 必不 忘记你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, '我涂抹了 你的过犯,像厚云消散;我涂抹了你的罪恶,如薄云灭没。你当归 向我,因 我救赎了你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, '诸天哪,应当歌唱,因为 耶和华 做成这事。地 的深处啊,应当欢呼;众山 应当发声 歌唱;树林 和其中 所有 的树都当如此!因为 耶和华 救赎了 雅各,并要因以色列 荣耀自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, '从你出胎,造就你 的救赎主─耶和华 如此 说:我─耶和华 是创造 万物的,是独自 铺张 诸天、铺开  大地的。谁 与我同在呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, '使说假话 的兆头 失效,使占卜的 癫狂,使智慧人 退 后,使他的知识 变为愚拙; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, '使我仆人 的话语 立定,我使者 的谋算 成就。论到耶路撒冷 说:必有人居住;论到犹大 的城邑说:必被建造,其中的荒场 我也必兴起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, '对深渊 说:你干了吧!我也要使你的江河 干涸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, '论塞鲁士 说:他是我的牧人,必成就我 所喜悦的,必下令 建造 耶路撒冷,发命立稳 圣殿的根基。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, '我─耶和华 所膏 的塞鲁士; 我搀扶 他的右手,使列国 降伏 在他面前。我也要放松 列王 的腰带,使城 门 在他面前 敞开 ,不得 关闭。我对他如此 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, '我 必在你前面 行,修平 崎岖之地。我必打破 铜 门,砍断 铁 闩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, '我要将暗中 的宝物 和隐密 的财宝 赐 给你,使 你知道 提名 召你的,就是 我─耶和华、以色列的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, '因 我仆人 雅各,我所拣选 以色列的缘故,我就提名 召 你;你虽不 认识我,我也加给你名号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, '我 是耶和华,在我以外并没有别神;除了我以外 再没有 神。你虽不 认识我,我必给你束腰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, '从日 出之地 到日落之处 使人 都知道 除了我以外,没有别神。我 是耶和华;在我以外并没有别神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, '我造 光,又造 暗;我施 平安,又降 灾祸;造作 这 一切 的是我─耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, '诸天哪,自上 而滴,穹苍 降下 公义;地面 开 裂,产出 救恩,使公义 一同 发生;这都是我─耶和华 所造的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, '祸哉,那与 造他 的主争论的!他不过是地上 瓦片 中的一块 瓦片。泥土 岂可对抟弄它 的说:你做 什么呢?所做的物岂可说:你 没有 手呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, '祸哉,那对父亲 说:你生 的是什么呢?或对母亲(原文是妇人)说:你产 的是什么呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, '耶和华─以色列 的圣者,就是造就 以色列 的如此 说:将来的事,你们可以问我;至于  我的众子,并 我手 的工作,你们可以求我命定(原文是吩咐我)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, '我 造 地,又造 人 在地上。我 亲手 铺张 诸天;天上万 象 也是我所命定的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, '我 凭公义 兴起塞鲁士(原文是他),又要修直 他一切 道路。他 必建造 我的城,释放 我被掳的民;不是 为工价,也不是 为赏赐。这是万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, '耶和华 如此 说:埃及 劳碌 得来的和古实 的货物必归你;身量高大 的西巴 人 必投降 你,也要 属你。他们必带著锁链 过来 随 从你,又向你 下拜,祈求 你说: 神 真 在你们中间,此外再没有别神;再 没有 别的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, '救主─以色列的 神啊,你 实在 是自隐的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, '凡制造 偶像 的都必抱愧 蒙羞,都 要一同 归 于 惭愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, '惟有以色列 必蒙耶和华 的拯救,得永远 的救恩。你们必不 蒙羞,也不 抱愧,直到 永世 无尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, '创造 诸天的耶和华,制造 成全 大地的 神,他 创造 坚定大地,并非 使地荒凉, 是要给人居住。 他如此 说:我 是耶和华,再 没有别神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, '我没有 在隐密 黑暗之 地 说话;我没有 对雅各 的后裔 说:你们寻求我 是徒然的。我─耶和华 所讲 的是公义,所说的 是正直。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, '你们从列国 逃脱的人,要一同 聚集 前 来。那些抬著 雕刻木 偶、祷告 不能 救人 之神的,毫无 知识。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, '你们要述说 陈明你们的理, 让他们彼此 商议。谁 从古时 指明?谁从上古 述说?不是 我─耶和华吗?除了我以外,再 没有 神;我是公义的 神,又是救主;除了我以外,再没有别神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, '地 极 的人都 当仰望 我,就必得救;因为 我是 神,再 没有别神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, '我指著自己 起誓,我口 所出 的话 是凭公义,并不 反回: 万 膝 必向我 跪拜;万 口 必凭我起誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, '人论我 说,公义、能力,惟独 在乎耶和华;人都必归 向他。凡 向他 发怒 的必至蒙羞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, '以色列的 后裔 都必因耶和华 得称为义,并要夸耀。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, '彼勒 屈身,尼波 弯腰;巴比伦的偶像 驮 在兽 和牲畜上。他们所抬的 如今成了重驮, 使牲畜疲乏, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, '都一同 弯腰 屈身,不 能 保全 重驮,自己 倒被掳 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, '雅各 家,以色列 家 一切 余 馀剩 的要听 我言:你们自从 生下,就蒙我保抱,自从 出胎,便蒙我怀搋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, '直到 你们年老,我 仍这样;直到 你们发白,我 仍怀搋。我 已造作,也 必保抱;我 必怀抱,也必拯救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, '你们将谁 与我相比,与我同等,可以与我比较,使我们相同呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, '那从囊中 抓 金子,用天平 平 银子的人,雇 银匠 制造 神像,他们又俯伏,又 叩拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, '他们将神像抬起,扛 在 肩上,安置 在定处,它就站立,不 离 本位; 人呼求 它,它不能 答应,也不能 救人 脱离患难。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, '你们当想念 这事,自己作大丈夫。悖逆的人哪,要 心 里思想。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, '你们要追念 上 古的事。因为 我是 神,并 无别神;我是 神,再没有 能比我的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, '我从起初 指明 末后的事,从古时言明 未 成的事,说:我的筹算 必立定;凡 我所喜悦的,我必成就。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, '我召 鸷鸟 从东方来,召那成就我筹算 的人 从远 方来。我已 说出,也必 成就;我已谋定,也必 做成。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, '你们这些心 中顽梗、远离 公义的,当听 我言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, '我使我的公义 临近,必不 远离。我的救恩 必不 迟延;我要为以色列─我的荣耀,在锡安 施行 救恩。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, '巴比伦 的 处女啊,下来 坐 在 尘埃;迦勒底 的闺女啊,没有 宝座,要坐 在地上;因为 你 不 再 称为 柔弱 娇嫩的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, '要用 磨 磨 面 麺,揭去 帕子,脱去 长衣,露 腿 蹚 河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, '你的下体 必被露出; 你的丑陋 必被看见。我要报仇,谁 也不 宽容。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, '我们救赎主 的名 是万军 之耶和华─以色列 的圣者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, '迦勒底 的闺女啊,你要默然静 坐,进入 暗中,因为 你 不 再 称为 列国 的主母。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, '我向 我的百姓 发怒,使我的产业 被亵渎,将他们交 在你手中,你毫不 怜悯 他们,把极 重的轭 加 在 老年人身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, '你自己说:我必 永 为 主母,所以 你不 将这事 放 在 心上,也不 思想 这事的结局。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, '你这专好宴乐、安然 居住的,现在 当听 这话。你心中 说:惟有我,除我以外再 没有别的。我必不致 寡 居,也不 遭 丧子之事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, '哪知,丧子、寡居 这 两件 事在一 日 转眼之间 必临 到你;正在你多 行邪术、广施 符咒的时候,这两件事必全然 临 到你身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, '你素来倚仗 自己的恶行,说:无人 看见我。你的智慧 聪明 使你偏邪,并且你心里 说:惟有我,除我以外再 没有别的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, '因此,祸患 要临 到你身,你不 知 何时发现(或译:如何驱逐);灾害 落 在你身上,你也不 能 除掉;所不 知道 的毁灭 也必忽然 临 到你身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, ' 站起来吧!用你 从幼年 劳神 施行的符咒 和你许多的 邪术;或者 可得 益处,或者可得强胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, '你筹划 㓰 太多,以致疲倦。让 那些观 天象的,看 星宿的,在月朔 说预言的,都站起来,救你 脱离所 要临 到你的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, ' 他们要 像碎秸 被火 焚烧,不能 救 自己 脱离火焰 之力;这火并非 可烤 的炭火,也不是可以坐在 其前 的火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, '你所 劳神 的事都要 这样 与你无益;从幼年 与你贸易 的也都各 奔 各乡,无人 救你。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, '雅各 家,称为 以色列 名下,从犹大 水源 出来的,当听我言!你们指著耶和华 的名 起誓,提说 以色列的 神,却不 凭诚实,不 凭公义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, ' 他们自称为 圣 城的人,所倚靠 的是名 为万军 之耶和华─以色列的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, '主说:早先的事,我从古时 说明,已经出了 我的口,也是我所指示的;我忽然 行做,事便成就。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, '因为我素来知道 你 是顽梗的─你的颈项 是铁 的;你的额 是铜的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, '所以,我从古时 将这事给你 说明,在未成 以先 指示你,免得 你说:这些事是我的偶像 所行的,是我雕刻的偶像 和我铸造的偶像 所命定的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, '你已经听见,现在要看见 这一切;你 不 说明吗?从今以后,我将新事,就是你所不 知道 的隐密事 指示你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, '这事是现今 造的,并非 从古就有;在今日 以先,你也未 曾听见,免得 你说: 这事我早已知道了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, ' 你未 曾听见, 未 曾知道; 你的耳朵 从来 未 曾开 通。 我原知道 你行事极其 诡诈,你 自从出胎以来,便称为 悖逆的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, '我为 我的名 暂且忍 怒,为我的颂赞 向你 容忍,不 将你剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, ' 我熬炼你,却不 像熬炼银子;你在苦难 的炉中,我拣选你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, '我为 自己的缘故 必行这事,我焉 能 使我的名被亵渎?我必不 将我的荣耀 归 给假神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, '雅各─我所选召 的以色列啊,当听 我言:我是耶和华,我 是首先的, 也 是末后的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, ' 我手 立了 地的根基;我右手 铺张 诸天;我 一招呼 便都 立住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, '你们都 当聚集 而听,他们(或译:偶像)内中 谁 说过 这些事?耶和华 所爱 的人必向巴比伦 行 他所喜悦的事;他的膀臂 也要加在迦勒底人身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, '惟有 我 曾说过,我又 选召他,领他来,他的道路 就必亨通。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, '你们要就近 我 来听 这话:我从起头 并未 曾在隐密处 说话;自从 有这事,我 就在那里。现在,主 耶和华 差遣我 和他的灵来(或译:耶和华和他的灵差遣我来)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, '耶和华─你的救赎主,以色列 的圣者 如此 说:我 是耶和华─你的 神,教训你,使你得益处,引导你 所当行 的路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, '甚愿  你素来听从 我的命令!你的平安 就 如河水;你的公义 就如海 浪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, '你的后裔 也必 多如海沙;你腹 中所生的 也必多如沙粒。他的名 在我面前 必不 剪除,也不 灭绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, '你们要从巴比伦 出来,从迦勒底人 中逃脱,以欢呼 的声音 传扬 说:耶和华 救赎了 他的仆人 雅各!你们要将这事 宣 扬 到 地 极。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, '耶和华引导他们 经过沙漠。他们并不 干渴;他为他们 使水 从磐石 而流,分裂 磐石,水 就涌出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, '耶和华 说:恶人 必不 得平安!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, '众海岛啊,当听 我言!远方 的众民哪,留心而听!自我出胎,耶和华 就选召我;自出母 腹,他就提 我的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, '他使 我的口 如快 刀,将我藏 在他手 荫之下;又使我成为 磨亮 的箭,将我藏 在他箭袋之中; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, '对我 说:你 是我的仆人 以色列; 我必因你 得荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, '我 却说:我劳碌 是徒然;我尽 力 是虚无 虚空。然而,我当得的理 必 在 耶和华那里;我的赏赐 必在我 神那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, '耶和华 从我出胎,造就我 作他 的仆人, 要使雅各 归 向他,使以色列 到他那里 聚集。原来耶和华 看 我为尊贵;我的 神 也成为 我的力量。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, '现在 他说:你作 我 的仆人,使 雅各 众支派 复兴,使以色列 中得保全 的归回 尚为小事,我还要使你 作外邦人 的光,叫你施行 我的救恩,直到 地 极。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, '救赎主─以色列 的圣者 耶和华 对那被人 所藐视、本国 所憎恶、官长所虐待的 如此 说:君王 要看见 就站起,首领 也要下拜;都因 信实 的耶和华,就是 拣选你─以色列 的圣者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, '耶和华 如此 说:在悦纳 的时候,我应允了你;在拯救 的日子,我济助了你。我要保护你,使你 作众民的中保(中保:原文是约);复兴 遍地,使人承受 荒凉 之地为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, '对那被捆绑的人 说:出来吧!对那 在黑暗的人说:显露吧!他们在 路 上必得饮食,在一切 净光的高处 必有食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, '不 饥 不 渴,炎热 和烈日 必不 伤害他们;因为 怜恤他们的 必引导他们,领他们 到 水 泉旁边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, '我必使 我的众 山 成为大道;我的大路 也被修高。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, '看哪,这些 从远方 来; 这些 从北方、从西方来;这些从秦(原文是希尼)国来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, '诸天哪,应当欢呼!大地啊,应当快乐!众山哪,应当发声 歌唱!因为 耶和华 已经安慰 他的百姓,也要怜恤 他困苦之民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, '锡安 说:耶和华 离弃了我;主 忘记了我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, '妇人 焉能忘记 她吃奶的婴孩,不怜恤 她所生 的儿子?即或 有 忘记的,我 却不 忘记你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, '看哪,我将你铭刻 在 我掌上;你的墙垣 常 在我眼前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, '你的儿女 必急速归回;毁坏你的,使你荒废的,必都离你 出去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, '你举 目 向四方 观看;他们都 聚集 来 到你这里。耶和华 说:我 指著我的永生起誓: 你必要以他们 为妆饰 佩戴,以他们为华带束腰,像新妇一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, '至于  你荒废 凄凉之处,并你被毁坏 之地, 现今 众民居住 必显为太窄;吞灭你的 必离你遥远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, '你必 听见 丧子 之后所生的儿女 说:这地方 我 居住太窄,求你给 我 地方居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, '那时你心里 必说:我 既丧子 独居,是被掳的,漂流在外。谁 给我 生 这些?谁 将这些 养大呢? 撇下 我 一人独居的时候,这些 在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, '主 耶和华 如此 说: 我必向 列国 举 手,向 万民 竖立 大旗;他们必将你的众子 怀中 抱来,将你的众女 肩 上扛来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, '列王 必作 你的养父;王后 必作你的乳母。他们必将脸 伏地,向你 下拜,并舔 你脚 上的尘土。你便知道 我 是耶和华;等候我 的 必不致 羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, '勇士 抢去的 岂能夺回?该 掳掠 的岂能 解救吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, '但 耶和华 如此 说:就是勇士 所掳掠的,也 可以夺回;强暴人 所抢的,也可以解救。与你相争的,我 必与他 相争;我 要拯救 你的儿女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, '并且我必使 那欺压你的 吃 自己的肉,也要以自己的血 喝醉,好像喝甜酒一样。凡 有血气的 必都知道 我─耶和华 是你的救主,是你的救赎主,是雅各 的大能者。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, '耶和华 如此 说:我休 你们的母亲, 休 书 在哪里呢?我将你们卖给我哪一个 债主呢? 你们 被卖, 是因你们的罪孽;你们的母亲 被休,是因你们的过犯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, '我来的时候,为何 无 人等候呢?我呼唤的时候,为何无人 答应呢?我的膀臂 岂是 缩短、不能救赎吗?我 岂 无 拯救 之力吗?看哪,我一斥责,海 就干了;我使 江河 变为旷野;其中的鱼 因无 水 腥臭,干渴 而死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, '我使 诸天 以黑暗 为衣服,以麻布 为遮盖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, '主 耶和华 赐 我 受教者 的舌头,使我知道 怎样用言语 扶助 疲乏的人。主每 早晨 提醒,提醒 我的 耳朵,使我能听,像受教者一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, '主 耶和华 开 通 我的 耳朵;我 并没有 违背,也没有 退 后。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, '人打我的背,我任 他打;人拔我腮颊的胡须,我由他拔;人辱我,吐我,我并 不掩 面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, '主 耶和华 必帮助 我,所以 我不 抱愧。 我硬著 脸面 好像坚石;我也知道 我必不致 蒙羞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, '称我为义的 与我相近;谁 与我 争论,可以与我一同 站立;谁 与我作对,可以就近 我来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, ' 主 耶和华 要帮助 我;谁 能定我有罪呢? 他们都 像衣服 渐渐旧了,为蛀虫 所咬。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, '你们中间 谁 是敬畏 耶和华、听从 他仆人 之话的?这 人行 在暗中,没有 亮光。当倚靠 耶和华 的名,仗赖自己的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, ' 凡你们 点 火,用火把 围绕 自己的可以行 在你们的火 焰里,并你们所点 的火把中。这 是 我手所定的:你们必躺 在悲惨之中。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, '你们这追求 公义、寻求 耶和华的,当听 我言!你们要追想 被凿而出 的磐石, 被挖而出 的岩穴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, '要追想 你们的祖宗 亚伯拉罕 和 生养你们 的撒拉;因为 亚伯拉罕独自一人的时候,我选召他,赐福与他,使他人数增多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, ' 耶和华 已经安慰 锡安 和 锡安一切 的荒场,使 旷野 像伊甸,使沙漠 像耶和华 的园囿;在其中 必有 欢喜、快乐、感谢,和歌唱 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, '我的百姓啊,要向我 留心;我的国民哪,要向我 侧耳;因为 训诲 必从我 而出;我必坚定 我的公理 为万民 之光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, '我的公义 临近;我的救恩 发出。我的膀臂 要审判 万民;海岛 都要等候 我,倚赖 我的膀臂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, '你们要向天 举 目,观看 下 地;因为 天 必像烟云 消散,地 必如衣服 渐渐旧了;其上的居民 也要如此 死亡(如此死亡:或译像 蠓虫死亡)。惟有我的救恩 永远 长存;我的公义 也不 废掉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, '知道 公义、将我训诲 存在心中 的民,要听 我言!不要 怕 人 的辱骂,也不要 因人的毁谤 惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, '因为 蛀虫 必咬他们,好像咬衣服;虫子 必咬他们,如同咬羊绒。惟有我的公义 永远 长存,我的救恩 直到万 代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, '耶和华 的膀臂啊,兴起!兴起!以能力 为衣穿上,像古时 的年日、上古 的世代 兴起一样。从前砍碎 拉哈伯、刺透 大鱼的,不 是 你吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, '使海 与深 渊 的水 干涸、使 海 的深处 变为赎民 经过 之路的,不 是 你吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, '耶和华 救赎的民 必归回,歌唱 来到 锡安;永 乐 必归到 他们的头上。他们必得著 欢喜 快乐;忧愁 叹息 尽都逃避。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, '惟有 我,是 安慰你们的。你 是谁,竟怕 那必死 的人?怕那要变 如草 的世人? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, '却忘记 铺张 诸天、立定 地基、创造你 的耶和华?又因 欺压者 图谋 毁灭 要发的暴怒,整 天 害怕,其实那欺压者 的暴怒 在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, '被掳去 的快 得释放,必不 死 而下坑;他的食物 也不致 缺乏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, '我 是耶和华─你的 神─搅动 大海,使海中的波浪 匉訇─万军 之耶和华 是我的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, '我将我的话 传 给你,用我的手 影 遮蔽你,为要栽定 诸天,立定 地基,又对锡安 说:你 是我的百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, '耶路撒冷啊,兴起!兴起!站起来!你 从耶和华 手 中喝了 他忿怒 之杯,喝了 那使人东倒西歪 的爵,以致喝 尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, '她所生育 的诸 子中,没有 一个引导 她的;她所养大 的诸 子中,没有 一个搀扶 她的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, '荒凉、毁灭、饥荒、刀兵,这 几样 临到你,谁 为你 举哀?我如何 能安慰你呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, '你的众子 发昏,在各 市 口上 躺卧,好像黄羊 在网罗之中,都满了 耶和华 的忿怒─你 神 的斥责。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, '因此,你这 困苦 却非 因酒 而醉的,要 听我言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, '你的主 耶和华─就是为他百姓 辨屈的 神 如此 说:看哪,我已将 那使人东倒西歪 的杯,就是 我忿怒 的爵,从你手中 接过来;你必不致 再 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, '我必将这杯递 在苦待你的人 手中;他们 曾对你 说:你屈身,由我们践踏过去吧!你便以 背 为地,好像街市,任人经过。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, '锡安哪,兴起!兴起!披上 你的能力!圣 城 耶路撒冷啊,穿上 你华美 的衣服!因为从今以后,未受割礼、不洁净 的必不 再 进入 你中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, '耶路撒冷啊,要抖下 尘土!起来 坐在位上!锡安 被掳的居民(原文是女子)哪,要解开  你颈项 的锁链! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, ' 耶和华 如此 说:「你们是无价 被卖的,也必无 银 被赎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, ' 主 耶和华 如此 说:起先 我的百姓 下到 埃及,在那里 寄居,又有亚述人 无故 欺压他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, '耶和华 说: 我的百姓 既是无价 被掳去,如今 我 在这里 做什么呢?耶和华 说:辖制他们的人 呼叫,我的名 整 天 受亵渎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, '所以,我的百姓 必知道 我的名; 到那 日他们必 知道说这话的 就是 我。看哪,是我!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, '那报佳音,传 平安,报 好信,传 救恩的,对锡安 说:你的 神 作王了!这人的脚 登 山 何等 佳美! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, '听啊,你守望 之人的声音,他们扬起 声来,一同 歌唱;因为 耶和华 归回 锡安的时候,他们必亲 眼 看见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, '耶路撒冷 的荒场啊,要发起欢声,一同 歌唱;因为 耶和华 安慰了 他的百姓,救赎了 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, '耶和华 在万 国 眼前 露出 圣 臂;地 极 的人都 看见我们 神 的救恩了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, '你们离开 吧!离开 吧!从巴比伦 出来。不要 沾 不洁净的物;要从其中 出来。你们扛抬 耶和华 器皿的人哪,务要自洁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, ' 你们出来 必不致 急忙,也不致 奔 逃。因为,耶和华 必在你们前头 行;以色列的 神 必作你们的后盾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, ' 我的仆人行事必有智慧(或译:行事通达),必被高举 上升,且成为至 高。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, ' 许多人因他(原文是你)惊奇; 他的面貌 比别人 憔悴;他的形容 比世人枯槁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, '这样,他必洗净(或译:鼓动)许多 国民;君王 要向他 闭 口。因 所 未曾 传与 他们的,他们必看见; 未曾 听见的,他们要明白。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, '我们所传的(或译:所传与我们的)有谁 信呢?耶和华 的膀臂 向 谁 显露呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, '他在耶和华面前 生长 如嫩芽,像根 出于 干 地。他 无 佳形 美容;我们看见他的时候,也无 美貌 使我们羡慕他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, '他被藐视,被人 厌弃; 多受痛苦,常经 忧患。他被藐视,好像被人掩 面不看的一样;我们也不 尊重他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, '他 诚然 担当 我们的忧患,背负 我们的痛苦;我们 却以为他 受责罚,被 神 击打 苦待了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, '哪知他 为我们的过犯 受害,为我们的罪孽 压伤。因他 受的刑罚,我们得平安;因他受的鞭伤,我们 得医治。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, '我们都 如羊 走迷;各人 偏行 己路;耶和华 使 我们众人 的罪孽 都归 在他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, '他 被欺压,在受苦的时候 却不 开  口(或译:他受欺压,却自卑不开 口);他像羊羔 被牵 到宰杀之地,又像羊 在剪毛的人 手下 无声,他也是这样不 开  口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, '因受欺压 和审判,他被夺去,至于  他同世的人,谁 想 他 受鞭打、从活人 之地 被剪除,是因我百姓 的罪过呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, '他虽然 未 行 强暴,口中 也没有 诡诈,人还使他 与 恶人 同埋;谁知死的时候 与 财主同葬。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, '耶和华却定意(或译:喜悦)将他压伤,使他受痛苦。耶和华以他为赎罪祭(或译: 他献 本身 为赎罪祭)。他必看见 后裔,并且延长 年日。耶和华 所喜悦的事 必在他手中 亨通。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, '他必看见 自己 劳苦的功效,便心满意足。有许多人 因认识 我的义 仆 得称为义;并且他 要担当 他们的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, '所以,我要使他 与位大的 同分,与 强盛的 均分 掳物。因为 他将命 倾倒,以致于 死;他也被列 在 罪犯之中。他 却担当 多人 的罪,又为罪犯 代求。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, '你这不怀孕、不 生养的 要歌唱;你这未曾 经过产难 的要发声 歌唱,扬声欢呼;因为 没有丈夫的 比有丈夫的 儿女 更多。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, '要扩张 你帐幕 之地,张大 你居所 的幔子,不要 限止;要放长 你的绳子,坚固 你的橛子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, '因为 你要向左 向右 开 展;你的后裔 必得 多国 为业,又使荒凉的 城邑 有人居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, '不要 惧怕,因 你必不致 蒙羞;也不要 抱愧,因 你必不致 受辱。 你必忘记 幼年 的羞愧,不 再 记念 你寡居 的羞辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, '因为 造你的 是你的丈夫;万军 之耶和华 是他的名。救赎你的 是以色列 的圣者;他必称为 全 地之 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, ' 耶和华 召你,如召被离弃 心中 忧伤 的妻,就是幼年所娶 被弃的 妻。这是你 神 所说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, '我离弃你 不过片 时,却要施大 恩 将你收回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, '我的怒气 涨溢,顷刻之间 向你 掩 面,却要以永远的 慈爱 怜恤你。这是耶和华─你的救赎主 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, ' 这事 在我 好像挪亚 的洪水。我怎样 起誓 不再 使挪亚 的洪水 漫过 遍地,我也照样 起誓 不再向你 发怒,也不斥责 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, ' 大山 可以挪开 ,小山 可以迁移;但我的慈爱 必不 离开  你;我平安 的约 也不 迁移。这是怜恤你的 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, '你这受困苦、被风飘荡 不得 安慰的人哪, 我 必以彩色 安置 你的石头,以蓝宝石 立定你的根基; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, '又以红宝石 造 你的女墙,以红 玉 造你的城门,以宝 石 造你四围的 边界(或译:外郭)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, '你的儿女 都 要受耶和华 的教训;你的儿女 必大 享平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, '你必因公义 得坚立,必远离 欺压, 不致 害怕;你必远离惊吓, 惊吓必不 临近 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, ' 即或 有人聚集,却不 由于 我;凡 聚集 攻击你的,必因你 仆倒(或译:投降你)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, ' 吹嘘 炭 火、打造 合用 器械 的铁匠 是我 所造;残害人、行毁灭的 也是我 所造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, '凡 为攻击你 造成的 器械 必不 利用;凡 在审判时 兴起 用舌 攻击你的,你必定他为有罪。这是 耶和华 仆人 的产业,是他们从我 所得的义。这是耶和华 说的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, ' 你们一切 干渴的 都当就近水 来; 没有 银钱 的也可以来。你们都来,买 了 吃;不用 银钱,不用 价值,也来买  酒 和奶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, '你们为何 花钱(原文是平银)买 那不足 为食物的?用劳碌 得来的买 那不 使人饱足的呢?你们要留意 听 我 的话就能吃 那美物,得享肥甘,心中 喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, '你们当就近 我来;侧 耳 而听, 就必得活。我必与你们 立 永 约,就是应许大卫 那可靠 的恩典。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, ' 我已立他 作万民 的见证,为万民 的君王 和司令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, ' 你素不 认识 的国民,你也必召来;素不 认识你 的国民 也必向你 奔跑,都因 耶和华─你的 神 以色列 的圣者,因为 他已经荣耀你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, '当趁耶和华 可寻找的时候 寻找他, 相近 的时候求告他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, '恶人 当离弃 自己的道路;不义 的人 当除掉自己的意念。归 向 耶和华,耶和华就必怜恤他;当归向我们的 神,因为 神必广行 赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, '耶和华 说: 我的意念 非同 你们的意念;我的道路 非同 你们的道路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, ' 天 怎样高 过地,照样,我的道路 高 过你们的道路;我的意念 高过你们的意念。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, ' 雨 雪 从 天 而降,并不 返回, 却 滋润 地土,使地上发芽 结实,使 撒种的 有种,使要吃的 有粮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, '我口 所 出 的话 也必 如此,决不 徒然 返回,却 要 成就 我所 喜悦的,在我发他去成就(发他去成就:或译所命定)的事上 必然亨通。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, ' 你们必欢欢喜喜 而出来,平平安安 蒙引导。大山 小山 必在你们面前 发声 歌唱;田野 的树木 也都 拍 掌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, '松树 长出,代替 荆棘;番石榴 长出,代替 蒺藜。这要 为耶和华 留名,作为永远 的证据,不能 剪除。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, '耶和华 如此 说:你们当守 公平,行 公义;因 我的救恩 临 近,我的公义 将要显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, '谨守 安息日 而不干犯,禁止 己手 而不作 恶; 如此 行、如此 持守 的人 便为有福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, '与 耶和华 联合 的外邦 人 不要 说:耶和华 必定将我 从 他民 中分别出来。太监 也不要 说: 我 是枯 树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, '因为 耶和华 如此 说:那些 谨守 我的安息日,拣选 我所 喜悦的事,持守 我约 的太监, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, '我必使 他们 在我殿中,在我墙内,有记念,有名号,比有儿 女 的更美。我必赐 他们 永远 的名, 不能 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, '还有那些与 耶和华 联合 的外邦 人,要事奉他,要爱 耶和华 的名,要作 他的 仆人─就是凡 守 安息日 不干犯,又持守他(原文是我)约的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, '我必领他们 到 我的圣 山,使他们在祷告 我的殿中 喜乐。他们的燔祭 和平安祭,在 我坛 上必蒙悦纳,因 我的殿 必称为 万 民 祷告 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, '主 耶和华,就是招聚 以色列 被赶散的,说:在这被招聚的人以外,我还要 招聚 别人归并他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, '田野 的诸 兽 都来 吞吃吧!林中 的诸 兽也要如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, '他看守的人 是瞎眼的,都 没有 知识,都是 哑巴 狗,不 能 叫唤;但知做梦,躺卧,贪 睡, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, '这些狗 贪食,不 知 饱足。这些 牧人 不 能 明白─各人 偏行 己路,各 从各方 求自己的利益。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, '他们说:来吧!我去拿 酒,我们饱饮 浓酒;明日 必 和今 日一样,就是宴乐无量 极 大之日。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, '义人 死亡,无 人 放 在 心上;虔诚 人 被收去,无人 思念。这义人 被收去 是 免了 将来的祸患; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, '他们得享(原文是进入)平安。素行 正直的,各人在坟里(原文是床上)安歇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, '你们 这些巫婆 的儿子,奸夫 和妓女 的种子,都要前来! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, '你们向 谁 戏笑?向 谁 张 口 吐 舌呢?你们 岂不是 悖逆 的儿女,虚谎 的种类呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, '你们在橡树中间,在各 青翠 树 下 欲火攻心;在山谷间,在石 穴 下 杀了 儿女; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, '在谷中 光滑石头里 有你的分。这些 就是 你所得的分;你也 向他 浇了 奠祭,献了 供物,因 这事 我岂能容忍吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, '你在 高 而又高 的山 上安设 床榻,也 上 那里 去献 祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, '你在门 后,在门框后,立起 你的纪念;向外人 赤露,又上去 扩张 床榻,与他们 立约;你在那里 看见 他们的床 就甚喜爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, '你把油 带 到王那里,又多加 香料,打发 使者往 远方去,自卑自贱 直到 阴间, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, '你因路 远 疲倦,却不 说 这是枉然;你以为有 复兴 之力,所以 不觉 疲惫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, '你怕 谁?因谁恐惧?竟 说谎,不 记念 我,又不 将这事放 在 心上。我 不是 许久 闭口不言, 你仍不 怕我吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, '我 要指明 你的公义;至于  你所行 的都必与你无 益。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, '你哀求的时候,让你所聚集的 拯救你吧!风 要把 他们 刮散,一口气 要把他们都吹去。但那投靠 我 的必得 地土,必承受 我的圣 山 为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, '耶和华要说:你们修筑 修筑,预备 道路,将绊脚石 从我百姓 的路 中除掉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, '因为 那至高 至上、永远长存(原文是住 在永远)名 为圣者 的如此 说:我住 在至高 至圣的所在,也与 心灵 痛悔 谦卑的人同居;要使谦卑人 的灵 苏醒,也使痛悔人 的心 苏醒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, '我必 不 永远 相争,也不 长久 发怒,恐怕 我 所造 的人 与灵性 都必发昏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, '因他贪婪 的罪孽,我就发怒 击打他;我向他掩面 发怒,他却仍然随 心 背 道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, '我看见 他所行的道,也要医治他;又要引导他,使他 和那一同伤心的人 再得 安慰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, '我造就 嘴唇 的果子;愿 平安 康泰 归与远处的人,也归与近处的人;并且我要医治他。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, '惟独恶人,好像翻腾 的海, 不 得 平静;其中的水 常涌出 污秽 和淤泥来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, '我的 神 说:恶人 必不得 平安!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, '你要大声 喊叫,不可 止息;扬起 声来,好像吹角。向我百姓 说明 他们的过犯;向雅各 家 说明他们的罪恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, '他们天 天 寻求 我,乐意 明白 我的道,好像行 义 的 国民,不 离弃他们 神 的典章,向我求问 公义 的判语,喜悦 亲近 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, '他们说:我们禁食,你为何 不 看见呢?我们刻苦 己心,你为何不 理会呢?看哪,你们禁食 的日子 仍求 利益,勒逼人为 你们做苦工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, ' 你们禁食,却互相争 竞,以凶恶 的拳头 打人。你们今日 禁食,不得 使你们的声音 听闻 于 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, '这样 禁食 岂是 我所拣选、使人 刻苦 己心 的日子吗?岂是叫人垂 头 像苇子,用麻布 和炉灰 铺在他以下吗?你这 可称为 禁食、为耶和华 所悦纳 的日子吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, '我所拣选的 禁食 不是 要松开  凶恶 的绳,解下 轭 上的索,使 被欺压 的得自由,折断 一切 的轭吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, '不是 要把你的饼 分 给饥饿的人,将飘流 的穷人 接到 你家中, 见 赤身 的给他衣服遮体,顾恤自己的骨肉 而不 掩藏吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, '这样,你的光 就必发现 如早晨的光;你所得的医治 要速速 发明。你的公义 必在你前面 行;耶和华 的荣光 必作你的后盾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, '那时 你求告,耶和华 必应允;你呼求,他必说:我在这里。你若 从你中间 除掉 重轭 和指摘人 的指头,并发 恶言的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, '你心 若向饥饿的人 发怜悯,使困苦的 人 得满足,你的光 就必在黑暗中 发现;你的幽暗 必变如正午。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, '耶和华 也必时常 引导你,在干旱之地 使你 心满意足,骨头 强壮。你必 像浇灌 的园子,又像水流 不 绝 的 泉 源。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, '那些出于 你的人 必修造 久 已荒废之处;你要建立 拆毁累代 的根基。你 必称为 补 破口的,和重修 路径 与人居住的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, '你若 在安息日 掉转(或译:谨慎)你的脚步,在我圣 日 不以操作 为喜乐,称 安息日 为可喜乐的,称耶和华 的圣 日为可尊重的;而且尊敬这日,不办 自己的私事,不随 自己的私意,不说 自己的私话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, '你 就以 耶和华 为乐。耶和华要使你乘驾 地 的高处,又以你祖 雅各 的产业 养育你。这是 耶和华 亲口 说的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, ' 耶和华 的膀臂 并非 缩短,不能拯救,耳朵 并非 发沉,不能听见, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, ' 但 你们的罪孽 使 你们 与 神 隔绝;你们的罪恶 使他掩 面 不听 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, '因 你们的手 被血 沾染,你们的指头 被罪孽沾污,你们的嘴唇 说 谎言,你们的舌头 出 恶语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, '无一人 按公义 告状,无一人 凭诚实 辩白;都倚靠 虚妄,说 谎言。所怀的 是毒害;所生的 是罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, '他们菢 毒蛇 蛋,结 蜘蛛 网;人吃 这蛋 必死。这蛋被踏,必出 蝮蛇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, '所结的网 不能 成为 衣服;所做的 也不能 遮盖自己。他们的行为 都是罪孽;手 所做 的都是强暴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, '他们的脚 奔跑 行恶;他们急速 流 无辜人 的血;意念 都是罪孽,所经过的路 都荒凉 毁灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, '平安 的路,他们不 知道;所行的事 没有 公平。他们为自己 修弯曲 的路;凡 行 此路 的都不 知道 平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, '因此,公平 离我们 远,公义 追 不 上我们。我们指望 光亮, 却是黑暗,指望光明,却行 幽暗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, '我们摸索 墙壁,好像瞎子;我们摸索,如同无 目之人。我们晌午 绊脚,如在黄昏一样;我们在肥壮人中,像死人一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, '我们 咆哮 如熊,哀 鸣 如鸽;指望 公平,却是没有;指望救恩,却远离 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, ' 我们的过犯 在你面前 增多,罪恶 作见证 告我们; 过犯 与我们同在。至于 我们的罪孽,我们都知道: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, '就是悖逆、不认识 耶和华,转去 不跟从我们的 神,说 欺压 和叛逆的话,心 怀 谎 言,随即说出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, '并且公平 转而退 后,公义 站 在远处; 诚实 在街上 仆倒,正直 也不 得 进入。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, ' 诚实 少见;离 恶 的人反成掠物。那时,耶和华 看见 没有 公平,甚不喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, '他见 无 人拯救, 无人 代求,甚为诧异,就用自己的膀臂 施行拯救, 以公义 扶持自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, '他以 公义 为铠甲(或译:护心镜),以拯救 为头 盔,以 报仇 为衣 服,以 热心 为外袍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, '他必按 人的行为 施报,恼怒 他的敌人,报复 他的仇敌,向众海岛 施行 报应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, '如此,人从日落之处 必敬畏 耶和华 的名,从日 出之地也必敬畏 他的荣耀;因为 仇敌 好像急流的河水 冲来,是耶和华 之气 所驱逐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, '必有一位救赎主 来 到锡安─雅各族中 转离 过犯的人那里。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, '耶和华 说:「至于 我 与他们 所立的约 乃是这样: 我加给你 的灵, 传 给你 的话,必不 离 你的口,也不离 你后裔 与你后裔 之后裔 的口,从今 直到 永远;这是耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, '兴起,发光!因为 你的光 已经来到!耶和华 的荣耀 发现 照耀你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, ' 看哪,黑暗 遮盖 大地,幽暗 遮盖万民,耶和华 却要显现 照耀你;他的荣耀 要现 在你身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, '万国 要来 就你的光;君王 要来就你发现 的光辉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, '你举 目 向四方 观看;众人都 聚集 来 到你这里。你的众子 从远方 而来;你的众女 也被 怀 抱而来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, '那时,你看见 就有光荣;你心 又跳动 又宽畅;因为 大海 丰盛的货物 必转来 归你;列国 的财宝 也必来 归你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, '成群 的骆驼,并米甸 和以法 的独峰驼 必遮满你;示巴的 众人 都必来到;要奉上 黄金 乳香,又要传说 耶和华 的赞美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, '基达 的羊群 都 必聚集 到你这里,尼拜约 的公羊 要供你使用,在 我坛 上必蒙 悦纳;我必荣耀 我荣耀 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, '那些 飞来 如云、又如鸽子 向 窗户 飞回的是谁呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, '众海岛 必 等候 我,首先 是他施 的船只,将你的众子 连 他们的金 银 从远方 一同带来,都为耶和华─你 神 的名,又为以色列 的圣者,因为 他已经荣耀了你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, '外邦 人 必建筑 你的城墙;他们的王 必服事你。 我曾发怒 击打你,现今却施恩 怜恤你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, '你的城门 必时常 开 放,昼 夜 不 关;使人把列国 的财物 带来 归你,并将他们的君王 牵引而来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, ' 哪一邦 哪一国 不 事奉你,就必灭亡, 也必全然 荒废。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, '黎巴嫩 的荣耀,就是松树、杉树、黄杨树,都必一同 归你,为要修饰 我圣所 之地;我也要使我脚 踏之处 得荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, '素来苦待你的,他的子孙 都必屈身 来 就你;藐视你的,都 要在 你脚下 跪拜。他们要称 你为「耶和华 的城」,为「以色列 圣者 的锡安」。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, '你虽然 被撇弃 被厌恶,甚至无人 经过,我却使你 变为永远 的荣华,成为累代 的喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, '你也必吃 万国 的奶,又吃 君王 的奶。你便知道 我─耶和华 是你的救主,是你的救赎主,雅各 的大能者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, '我要拿 金子 代替 铜,拿 银子 代替 铁,拿铜 代替 木头,拿铁 代替 石头;并要以 和平 为你的官长,以公义 为你的监督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, '你地上 不 再 听见 强暴的事,境内 不再听见荒凉 毁灭的事。你必称 你的墙为「拯救」,称你的门为「赞美」。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, '日头 不 再 作 你白昼 的光;月亮 也不 再发光 照耀 你。耶和华 却要作 你 永远 的光;你 神 要为你的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, '你的日头 不 再 下落;你的月亮 也不 退缩;因为 耶和华 必作 你永远 的光。你悲哀 的日子 也完毕了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, '你的居民 都 成为义人,永远 得 地 为业;是我种 的栽子,我手 的工作,使我得荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, '至小 的族要 加增千倍;微弱 的国 必成为强盛。我─耶和华 要按定期 速成这事。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, '主 耶和华 的灵 在我身上;因为 耶和华 用膏膏 我,叫我传好信息给谦卑的人(或译:传福音给贫穷的人),差遣我 医好 伤 心的人,报告 被掳的 得释放,被囚的 出监牢; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, '报告 耶和华的 恩 年,和我们 神 报仇 的日子;安慰 一切 悲哀的人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, '赐 华冠与 锡安 悲哀的人,代替 灰尘;喜乐 油 代替 悲哀;赞美 衣 代替 忧伤 之灵;使他们 称为「公义 树」,是耶和华 所栽的,叫他得荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, '他们必修造 已久 的荒场,建立 先前 凄凉之处,重修 历代 荒凉 之城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, '那时,外人 必起来 牧放 你们的羊群;外邦 人 必作你们耕种田地的,修理葡萄园的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, '你们 倒要称为 耶和华 的祭司;人必称 你们为我们 神 的仆役。你们必吃用 列国 的财物,因得他们的荣耀 自夸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, '你们必得加倍的好处,代替 所受的羞辱;分中 所得的喜乐,必代替所受的凌辱。 在境内 必得 加倍 的产业;永远 之乐 必归与你们(原文是他们)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, '因为 我─耶和华 喜爱 公平,恨恶 抢夺 和罪孽;我要凭诚实 施行 报应,并要与我的百姓 立 永 约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, '他们的后裔 必在列国中 被人认识;他们的子孙 在众民 中也是如此。凡 看见他们的 必认 他们是 耶和华 赐福 的后裔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, '我因耶和华 大大 欢喜;我的心靠 神 快乐。因 他以拯救 为衣 给我穿上,以公义 为袍 给我披上,好像新郎 戴上 华冠,又像新妇 佩戴 妆饰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, '田地 怎样 使百谷发 芽,园子 怎样使所种 的发生,主 耶和华 必照样 使公义 和赞美 在 万 民 中发出。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, '我因 锡安 必不 静默,为 耶路撒冷 必不 息声,直到 他的公义 如光辉 发出,他的救恩 如明灯 发亮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, '列国 必见 你的公义;列 王 必见你的荣耀。你 必得新 名 的称呼,是耶和华 亲口 所 起的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, '你在耶和华 的手中 要作为 华 冠,在你 神 的掌上 必作为冕 旒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, '你 必不 再 称为「撇弃的」;你的地 也不 再 称为「荒凉的」。你 却要 称为「我所喜悦的」;你的地也必称为「有夫之妇」。因为 耶和华 喜悦 你,你的地 也必归他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, '少年人 怎样 娶 处女,你的众民(民:原文是子)也要照样娶你;新郎 怎样喜悦 新妇,你的 神 也要照样喜悦 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, '耶路撒冷啊,我在 你城 上设立 守望的,他们 昼 夜 必 不 静默。呼吁 耶和华的,你们 不要 歇息, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, '也不要 使 他 歇息,直等 他建立耶路撒冷, 使 耶路撒冷 在地上 成为可赞美的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, '耶和华 指著自己的右手 和大能 的膀臂 起誓说:我必不 再 将 你的五谷 给 你仇敌 作食物;外邦 人 也不 再喝 你劳碌 得来 的新酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, '惟有 那收割的 要吃,并赞美 耶和华;那聚敛的 要在我圣所 的院内 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, '你们当从门 经过 经过,预备 百姓 的路;修筑 修筑 大道,捡去 石头,为 万民 竖立 大旗, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, '看哪,耶和华 曾宣告 到 地 极,对锡安的居民(原文是女子)说: 你的拯救者 来到。 他的赏赐 在他那里;他的报应 在他面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, '人必称 他们为「圣 民」,为「耶和华 的赎民」;你 也必称为「被眷顾、不 撇弃 的城」。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, '这 从以东 的波斯拉 来,穿红 衣服, 装扮 华美,能力 广大,大步行走 的是谁呢?就是我,是凭公义 说话,以大能 施行拯救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, '你的装扮 为何 有红色?你的衣服 为何像踹 酒醡的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, '我独自 踹 酒醡;众民中 无 一人 与我同在。我发怒 将他们踹下,发烈怒 将他们践踏。他们的血 溅 在 我衣服上,并且污染了 我一切 的衣裳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, '因为,报仇 之日 在我心中;救赎 我民之年 已经来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, '我仰望,见无人 帮助;我诧异,没有 人扶持。所以,我自己的膀臂 为我 施行拯救;我的烈怒 将我扶持。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, '我发怒,踹下 众民;发烈怒,使他们沉醉,又将他们的血 倒 在地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, '我要照 耶和华 一切 所 赐给我们的,提起 他的慈爱 和 美德,并他向以色列 家 所 施的大 恩;这恩是照他的怜恤 和丰盛 的慈爱 赐给他们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, '他说:他们 诚然 是我的百姓,不 行虚假 的子民;这样,他就作了 他们的 救主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, '他们在一切 苦难中,他 也同受苦难;并且他面前 的使者 拯救他们;他 以慈爱 和怜悯 救赎他们;在古时的 日子 常保抱他们,怀搋他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, '他们 竟悖逆,使 主的圣 灵 担忧。他就转作 他们的 仇敌,亲自 攻击 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, '那时,他们(原文是他)想起 古时 的日子─摩西 和他百姓,说:将 百姓和牧养 他全群 的人从海里 领上来 的在哪里呢?将 他的圣 灵 降 在他们中间 的在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, '使他荣耀 的膀臂 在摩西 的右手边 行动,在他们前面 将水 分开 ,要建立 自己 永远 的名, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, '带领他们 经过深处,如马 行走旷野,使他们不致 绊跌的在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, '耶和华 的灵 使他们得安息,仿佛牲畜 下 到山谷;照样,你也引导 你的百姓,要建立 自己 荣耀 的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, '求你从天上 垂顾,从你圣洁 荣耀 的居所 观看。你的热心 和你大能的作为 在哪里呢?你爱慕 的心肠 和怜悯 向我们 止住了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, '亚伯拉罕 虽然 不 认识我们,以色列 也不 承认我们,你 却是 我们的父。耶和华啊,你 是我们的父;从万古以来,你名称为「我们的救赎主」。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, '耶和华啊,你为何 使我们走差 离开 你的道,使我们心 里刚硬、不敬畏你呢?求你为 你仆人,为你产业 支派的缘故,转回来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, '你的圣 民 不过暂时 得这产业;我们的敌人 已经践踏 你的圣所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, '我们好像 你未 曾治理的人,又像未曾 得称 你名下的人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, '愿  你裂 天 而降;愿 山 在你面前 震动─ ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, '好像火 烧 干柴,又像火 将水 烧开 ,使你敌人 知道 你的名,使列国 在你面前 发颤! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, '你曾行 我们不能 逆料 可畏的事。那时你降临,山岭 在你面前 震动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, '从古以来,人未曾 听见、未曾 耳闻、未曾 眼 见 在你以外 有什么神 为等候 他 的人行事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, '你迎接 那 欢喜 行 义、记念 你道的人; 你 曾发怒,我们仍犯罪;这景况 已久,我们还能得救吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, '我们都 像不洁净的人;所有 的义 都像污秽 的衣服。我们都 像叶子 渐渐枯干;我们的罪孽 好像风 把我们吹去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, '并且无人 求告 你的名;无人奋力 抓住 你。原来 你掩 面 不顾我们,使我们因 罪孽 消化。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, '耶和华啊,现在 你 仍是我们的父!我们 是泥,你 是窑匠;我们都 是你手 的工作。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, '耶和华啊,求你不要 大 发震怒,也不要 永远 记念 罪孽。 求 你垂顾我们,我们都 是你的百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, '你的圣 邑 变为 旷野。锡安 变为 旷野;耶路撒冷 成为荒场。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, '我们圣洁 华美 的殿─就是 我们列祖 赞美你的所在 被火 焚烧;我们所羡慕 的美地尽都 荒废。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, '耶和华啊,有 这些事,你还忍得住吗?你仍静默使我们深 受苦难吗?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, '素来没有 访问我的,现在求问我;没有 寻找我的,我叫他们遇见;没有 称为 我名下的,我对 他们 说:我在这里!我在这里! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, '我整 天 伸 手招呼 那悖逆 的百姓;他们随 自己的意念 行 不 善 之道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, '这百姓 时常 当 面 惹我 发怒;在园中 献祭,在坛(原文是砖)上烧香; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, '在坟墓间 坐著,在隐密处 住宿,吃 猪 肉;他们器皿 中有可憎之物 做的汤; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, '且对人说:你 站开 吧!不要 挨近 我,因为 我比你圣洁。主说:这些人 是我鼻中 的烟,是整 天 烧著 的火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, '看哪,这都写 在我面前。我必不 静默, 必 施行报应,必将你们的罪孽 和你们列祖 的罪孽,就是 在 山 上烧香,在 冈 上亵渎我的罪孽,一同 报应 在 他们后人怀中,我先 要把他们所行的 量 给 他们;这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, '耶和华 如此 说: 葡萄中 寻得 新酒,人就说:不要 毁坏,因为 福 在其中。我因 我仆人 的缘故也必照样 而行,不 将他们全然 毁灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, '我必从雅各中 领出 后裔,从犹大中 领出承受 我众山的。我的选民 必承受;我的仆人 要在那里 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, '沙仑  平原必成为 羊群 的圈;亚割 谷 必成为牛群 躺卧之处,都为 寻求我 的民所得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, '但你们 这些离弃 耶和华、忘记 我的圣 山、给时运 摆筵席(原文是桌子)、给天命 盛满 调和酒的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, '我要命定 你们 归在刀下,都 必屈身 被杀;因为 我呼唤,你们没有 答应;我说话,你们没有 听从;反倒行 我眼中 看为恶的,拣选 我所 不 喜悦的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, '所以,主 耶和华 如此 说: 我的仆人 必得吃,你们 却饥饿; 我的仆人 必得喝,你们 却干渴; 我的仆人 必欢喜,你们 却蒙羞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, ' 我的仆人 因心 中高兴 欢呼,你们 却因心 中忧愁 哀哭,又因心 里忧伤 哀号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, '你们必留下 自己的名,为我选民 指著赌咒。主 耶和华 必杀你们,另起别 名 称呼 他的仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, '这样,在地上 为自己求福的,必凭真实的 神 求福;在地上 起誓的,必指真实的 神 起誓。因为,从前 的患难 已经忘记,也 从我眼前 隐藏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, ' 看哪!我造 新 天 新 地;从前的事 不再 被记念,也不再 追 想。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, '你们当 因 我 所 造的 永远 欢喜 快乐;因 我 造 耶路撒冷 为人所喜,造其中的居民 为人所乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, '我必因耶路撒冷 欢喜,因我的百姓 快乐;其中 必不 再 听见 哭泣 的声音 和哀号 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, '其中必 没 有 数日 夭亡的婴孩,也没有 寿数 不 满 的老者;因为 百 岁 死 的仍算孩童,有百 岁 死的罪人 算被咒诅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, '他们要建造 房屋,自己居住;栽种 葡萄园,吃 其中的果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, '他们建造的,别人 不 得住;他们栽种的,别人 不 得吃;因为 我民 的日子 必像树木 的日子;我选民 亲手 劳碌 得来的必长久享用。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, '他们必不 徒然 劳碌,所生产的,也不 遭灾害,因为 都是 蒙耶和华 赐福 的后裔;他们的子孙也是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, ' 他们尚未 求告,我 就应允; 正 说话的时候,我 就垂听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, '豺狼 必与羊羔 同 食;狮子 必吃 草 与牛一样;尘土 必作蛇 的食物。在我圣 山 的遍处,这一切都不 伤人,不 害物。这是耶和华 说的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, '耶和华 如此 说:天 是我的座位;地 是我的脚 凳。你们要为我 造 何等 的殿宇?哪里 是我安息 的地方呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, '耶和华 说:这 一切 都是我手 所造的,所以就 都 有了。但我所 看顾的,就是虚心(原文是贫穷)痛悔、因 我话 而战 兢的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, '假冒为善的宰 牛,好像杀 人,献 羊羔,好像打折 狗 项,献 供物,好像献猪 血,烧 乳香,好像称颂 偶像。这等人 拣选 自己的道路,心 里喜悦 行可憎恶的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, '我 也 必拣选 迷惑他们的事,使他们所惧怕的 临到 他们;因为 我呼唤,无人 答应;我说话,他们不 听从;反倒行 我眼中 看为恶的,拣选 我所 不 喜悦的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, '你们因 耶和华 言语 战 兢 的人当听 他的话:你们的弟兄─就是恨恶你们,因 我名 赶出你们的,曾说:愿 耶和华 得荣耀,使我们得见 你们的喜乐;但蒙羞 的究竟是他们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, '有喧哗 的声音 出自城中!有声音 出于 殿中!是耶和华 向仇敌 施行 报应 的声音! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, '锡安未曾 劬劳 就生产,未 觉 疼痛 就生出 男孩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, '国 岂能一 日 而生?民 岂能 一 时 而产?因为 锡安 一 劬劳 便生下 儿女,这样的事 谁 曾听见?谁 曾看见呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, '耶和华 说:我 既使她临产,岂不 使她生产呢?你的 神 说:我既 使她生产,岂能使她闭胎不生呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, '你们爱慕 耶路撒冷 的都要 与她 一同欢喜 快乐;你们为她 悲哀的 都要 与她 一同乐 上加乐; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, '使 你们在她安慰 的怀中 吃 奶得饱,使 他们得她丰盛 的荣耀,犹如挤奶,满心喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, ' 耶和华 如此 说:我 要使平安 延及 她,好像江河,使列国 的荣耀延及她,如同涨溢 的河。你们要从中享受(原文是咂);你们必蒙抱 在 肋旁,摇弄 在 膝上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, '母亲 怎样 安慰 儿子,我 就照样 安慰你们;你们也必因(或译:在)耶路撒冷 得安慰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, '你们看见,就心 中快乐;你们的骨头 必得滋润 像嫩草一样;而且耶和华 的手 向 他仆人 所行的必被人知道;他也要向 仇敌 发恼恨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, ' 看哪,耶和华 必在火 中降临;他的车辇 像旋风,以烈 怒 施行报应,以火 焰 施行责罚; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, '因为 耶和华 在 一切 有血气的人身上,必以火 与刀 施行审判;被耶和华 所杀 的必多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, '「那些分别为圣、洁净自己的,进入 园 内跟 在其中 一个人的后头,吃 猪 肉 和仓鼠 并可憎之物,他们必一同 灭绝;这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, '「我 知道他们的行为 和他们的意念。时候将到,我必将 万 民万族(族:原文是舌)聚 来,看见 我的荣耀, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, '我要显神迹(或译:记号)在他们中间。 逃脱的,我要差 到 列国去,就是 到他施、普勒、拉 弓 的路德 和土巴、雅完,并素来没有 听见 我名声、没有 看见 我荣耀 辽远 的海岛;他们必将 我的荣耀 传扬 在列国中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, '他们必将 你们的弟兄 从列 国 中送回,使他们或骑马,或坐车,坐轿,骑骡子,骑独峰驼,到 我的圣 山 耶路撒冷,作为供物 献给耶和华,好像 以色列 人 用洁净的 器皿 盛 供物 奉到 耶和华 的殿中;这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, '耶和华 说:我也 必从他们中间 取 人为祭司,为利未人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, '耶和华 说: 我 所 要造 的新 天 新 地,怎样 在我面前 长存;你们的后裔 和你们的名字 也必照样 长存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, ' 每逢 月朔、 安息日,凡 有血气 的必来 在我面前 下拜。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, '他们必出去 观看 那些违背 我 人 的尸首;因为 他们的虫 是不 死的;他们的火 是不 灭的;凡 有血气 的都必 憎恶他们。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, '便雅悯 地 亚拿突 城的 祭司中,希勒家 的儿子 耶利米 的话记在下面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, ' 犹大 王 亚们 的儿子 约西亚 在位 十 三 年,耶和华 的话 临 到耶利米。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, '从犹大 王 约西亚 的儿子 约雅敬 在位的时候,直到 犹大 王 约西亚 的儿子 西底家 在位的末年,就是 十一 年 五 月间 耶路撒冷 人被掳的时候,耶和华的话也常临到耶利米。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, '耶利米说,耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, '我未 将你造 在腹中,我已晓得你;你未 出 母胎,我已分别你为圣;我已派你 作列国 的先知。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, '我就说:主 耶和华 啊, 我不 知 怎样说,因为 我是 年幼的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, '耶和华 对我 说:你不要 说 我是 年幼的,因为 我差遣你 到 谁那里去,你都要去;我吩咐你 说什么话,你都要说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, '你不要 惧怕 他们,因为 我 与你同在,要拯救你。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, '于 是耶和华 伸 手 按 我的口, 对我 说: 我已将当说的话 传给 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, '看哪,我今 日 立你 在列邦 列国之上,为要施行拔出、拆毁、毁坏、倾覆 复,又要建立、栽植。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, '耶和华 的话 又临 到我 说:「耶利米,你 看见 什么?」我说:「我 看见 一根杏树 枝。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, '耶和华 对我 说:「你看得 不错;因为 我 留意保守 我的话,使得成就。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, '耶和华 的话 第二次 临 到我 说:「你 看见 什么?」我说:「我 看见 一个烧开 的 锅, 从 北而倾。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, '耶和华 对我 说:「必有灾祸 从北方 发出,临到 这地 的一切 居民。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, '耶和华 说:「 看哪,我要召 北方 列国 的众 族;他们要来,各 安 座位 在耶路撒冷 的城门口,周围 攻击 城墙,又要攻击 犹大 的一切 城邑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, '至于  这民的一切 恶,就是 离弃我、向别 神 烧香、跪拜 自己手 所造的,我要发出 我的判语,攻击他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, '所以你 当束 腰,起来将 我 所 吩咐你的 一切 话告诉 他们;不要 因他们 惊惶,免得 我使你在他们面前 惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, '看哪,我 今日 使你 成为坚 城、铁 柱、铜 墙,与 全 地 和犹大 的君王、首领、祭司,并地上 的众民反对。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, '他们要攻击 你,却不 能胜 你;因为 我 与你同在,要拯救你。这是耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, '「你去 向耶路撒冷 人的耳中 喊叫 说,耶和华 如此 说:你 幼年 的恩爱,婚姻 的爱情,你怎样在旷野,在未 曾耕种 之地 跟随 我,我都记得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, '那时以色列 归耶和华 为圣,作为土产 初熟的果子;凡 吞吃它的 必算为有罪,灾祸 必临 到他们。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, '雅各 家、以色列 家 的各 族啊,你们当听 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, '耶和华 如此 说:你们的列祖 见 我 有什么 不义,竟 远离 我,随 从 虚无的神,自己成为虚妄的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, '他们也不 说:那领我们 从埃及 地 上来,引导 我们 经过旷野,沙漠 有深坑 之地,和干旱 死荫、无 人 经过、无 人 居住 之地 的耶和华 在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, '我领 你们 进入 肥美 之地,使你们得吃 其中的果子 和美物;但你们进入 的时候就玷污 我的地,使 我的产业 成为可憎的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, '祭司 都不 说,耶和华 在哪里呢?传讲 律法 的都不 认识我。官长 违背 我;先知 藉 借巴力 说预言,随 从 无 益的神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, '耶和华 说:我因此 必 与你们 争辩,也必与 你们的子孙 争辩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, '你们且 过到 基提 海岛 去察看,打发人 往基达 去留心 查考,看 曾有 这样的事 没有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, '岂有一国 换了 他的神吗?其实这 不是 神!但我的百姓 将他们的荣耀 换了 那无 益的神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, '诸天哪,要因 此 惊奇,极其恐慌,甚为 凄凉!这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, '因为 我的百姓 做了 两件 恶事,就是离弃 我 这活 水 的泉源,为自己 凿出 池子,是 破裂 不能 存 水 的池子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, '以色列 是仆人吗? 是 家中 生的奴仆吗?为何 成为 掠物呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, '少壮狮子 向他 咆哮,大声吼叫,使 他的地 荒凉;城邑 也都焚烧,无人 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, '挪弗 人 和答比匿人 也 打破你 的头顶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, '这事 临到你身上,不是 你自招的吗?不是因耶和华─你 神 引你行 路 的时候,你离弃 他吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, '现今 你 为何 在埃及 路上 要喝 西曷 的水呢?你 为何 在亚述 路上 要喝 大河 的水呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, '你自己的恶 必惩治你;你背道的事 必责备你。由此可知 可见,你离弃 耶和华─你的 神,不 存敬畏我的心,乃为 恶事,为苦事。这是主─万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, ' 我在古时 折断 你的轭,解开  你的绳索。你说:我必不 事奉耶和华;因为 你 在 各 高 冈上、各 青翠 树 下 屈身 行淫(或译:我在古时折断你的轭,解开 你的绳索,你就说:我必不事奉别神。谁知你在各高冈上、各青翠树下仍屈身行淫)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, '然而,我 栽你 是上等的葡萄树,全然 是真 种子;你怎么 向我 变为 外邦 葡萄树 的坏枝子呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, ' 你虽 用碱、多用 肥皂 洗濯,你罪孽 的痕迹 仍然在我面前显出。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, '你怎能 说:我没有 玷污、没有 随 从 众巴力?你看 你谷中 的路,就知道 你所行的 如何。你是快行 的独峰驼,狂奔 乱走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, '你是野驴,惯在 旷野,欲 心 发动就吸 风;起性的时候 谁 能使牠转去呢?凡 寻找牠的 必不致 疲乏;在牠的月份 必能寻见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, '我说:你不要 使脚上 无鞋,喉咙 干渴。你倒说:这是枉然。 我喜爱 别神,我必随 从他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, ' 贼 被捉拿,怎样羞愧,以色列 家和 他们的君王、首领、祭司、先知 也都照样 羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, '他们向木头 说:你是 我的父;向石头说:你是 生我的。 他们以背 向 我,不 以面向我;及至遭遇患难 的时候 却说:起来 拯救我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, '你为自己 做 的 神 在哪里呢?你遭遇患难 的时候, 叫他们起来 拯救你吧!犹大啊, 你神 的数目与你城 的数目相等。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, '耶和华 说:你们为何 与我 争辩呢?你们都 违背了 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, '我责打 你们的儿女 是徒然的,他们不 受 惩治。你们自己的刀 吞灭 你们的先知,好像残害的 狮子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, '这世代的人哪,你们 要看明 耶和华 的话。我岂向以色列 作 旷野呢?或 作幽暗 之地呢?我的百姓 为何 说:我们脱离约束,再 不 归 向你了? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, '处女 岂能忘记 她的妆饰呢?新妇 岂能忘记她的美衣呢?我的百姓 却忘记了我 无 数的 日子! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, '你怎么 修饰 你的道路 要求 爱情呢?就是 恶劣的妇人 你也 叫 她们行你的路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, '并且 你的衣襟上 有 无辜 穷 人 的血;你杀他们并不是 遇见他们 挖窟窿,乃是 因 这 一切的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, '你还说: 我无辜;耶和华 的怒气 必定 向我 消了。看哪,我必审问 你;因 你自说:我没有 犯罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, '你为何 东跑西奔 要更换 你的路呢?你必 因埃及 蒙羞,像 从前因亚述 蒙羞一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, '你也必 两手 抱 头 从埃及出来;因为 耶和华 已经弃绝 你所倚靠的,你必不 因他们 得顺利。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, '有话说:人 若 休 妻,妻离他 而去,作了 别人 的妻,前夫岂能再 收回 她来?若收回她来,那 地 岂不是 大大 玷污了吗?但你 和许多 亲爱的 行邪淫,还可以归向 我。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, '你向 净光的高处 举 目 观看,你在何处 没有 淫行呢?你坐 在 道旁等候,好像阿拉伯人 在旷野埋伏一样,并且你的淫行 邪恶 玷污了 全地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, '因此甘霖 停止,春(原文是晚)雨 不 降。你 还是 有娼妓 之脸,不顾 羞耻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, '从今以后,你岂不 向我 呼叫说:我父啊,你是 我幼年 的恩主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, '耶和华岂 永远 怀怒,存留 到底吗?看哪,你又发恶言 又行 坏事,随自己的私意而行(或译:你虽这样说,还是行恶放纵欲心)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, '约西亚 王 在位的时候,耶和华 又对我 说:「背道的 以色列 所 行的,你看见没有?她 上 各 高 山,在 各 青翠 树 下 行淫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, '她行 这些 事以后,我说 她必归 向我,她却不 归向我。她奸诈 的妹妹 犹大 也看见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, '背道的 以色列 行淫,我为 这 缘故 给 她 休 书 休她;我看见 她奸诈的 妹妹 犹大,还不 惧怕,也 去 行淫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, ' 因以色列 轻忽了 她的淫乱,和 石头 木头 行淫, 地 就被玷污了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, '虽有 这 一切的事,她奸诈的 妹妹 犹大 还不 一 心 归 向我,不过 是假意归我。这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, '耶和华 对我 说:「背道 的以色列 比奸诈 的犹大 还显为义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, '你去 向北方 宣告 说:耶和华 说:背道的 以色列啊,回来吧!我必不 怒目 看 你们;因为 我 是慈爱的,我必不 永远 存怒。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, '只要 承认 你的罪孽,就是 你违背 耶和华─你的 神,在各 青翠 树 下 向别神 东奔西跑,没有 听从 我的话。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, '耶和华 说:背道 的儿女啊,回来吧!因为 我 作你们的 丈夫,并且我必将你们 从一 城 取 一人,从一族 取两人, 带到 锡安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, '我也必将合我心 的牧者 赐 给你们。他们必以知识 和智慧 牧养 你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, '耶和华 说:「 你们在国中 生养 众多;当 那些 日子,人必不 再 提说 耶和华 的约柜,不 追 想,不 记念,不 觉缺少,也不 再 制造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, '那 时,人必称 耶路撒冷 为耶和华 的宝座;万 国 必到 耶路撒冷,在耶和华 立名 的地方聚集。他们必不 再 随从 自己顽梗 的恶 心 行事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, '当那些 日子,犹大 家 要和以色列 家 同 行,从北方 之地 一同 来 到 我赐 给 你们列祖 为业 之地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, '我 说:我怎样 将你安置 在儿女之中,赐 给你 美 地,就是万国 中肥美 的产业。我又说:你们必称 我 为父,也不再 转去 不跟从我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, '以色列 家,你们向我 行诡诈,真像 妻子 行诡诈 离开 她丈夫 一样。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, '在 净光的高处 听见 人声,就是以色列 人 哭泣 恳求之声,乃因 他们走弯曲 之道,忘记 耶和华─他们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, '你们这背道 的儿女啊,回来吧!我要医治 你们背道的病。看哪,我们来到 你这里,因 你 是耶和华─我们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, '仰望从小山 或从大山 的喧嚷中得帮助,真是 枉然的。以色列 得救,诚然 在乎耶和华─我们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, '从我们幼年以来,那可耻的偶像 将我们列祖 所 劳碌得来的 羊群、 牛群,和 他们的儿 女 都吞吃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, '我们在羞耻中 躺卧吧!愿 惭愧 将我们遮盖;因为从立国(原文是幼年)以来,我们 和我们的列祖 常常得罪 耶和华─我们的 神,没有 听从 耶和华─我们 神 的话。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, '耶和华 说:以色列啊,你若 回来 归 向我,若 从我眼前 除掉 你可憎的偶像,你就不 被迁移。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, '你必凭诚实、公平、公义,指著永生 的耶和华 起誓;列国 必因耶和华称自己 为有福,也必因他 夸耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, ' 耶和华 对犹大 和耶路撒冷 人 如此 说:要开 垦 你们的 荒地,不要 撒种 在 荆棘中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, '犹大 人 和耶路撒冷 的居民哪,你们当自行割礼,归耶和华,将心 里的污秽 除掉;恐怕 我的忿怒 因 你们的恶 行 发作,如火 著起,甚至无人 能以熄灭! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, '你们当传扬 在犹大,宣告 在耶路撒冷 说:你们当在国中 吹 角,高声 呼叫 说:你们当聚集!我们好进 入 坚固 城! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, '应当向锡安 竖立 大旗。要逃避,不要 迟延,因 我必 使灾祸 与大 毁灭 从北方 来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, '有狮子 从密林中 上来,是毁坏 列国的。牠已经动身 出 离本处,要使 你的地 荒凉,使你的城邑 变为荒场 无人 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, '因 此,你们当腰束 麻布,大声 哀号,因为 耶和华 的烈 怒 没有 向我们 转消。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, '耶和华 说:「 到那 时,君王 和首领 的心 都要消灭;祭司 都要惊奇,先知 都要诧异。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, '我说:「哀哉!主 耶和华啊,你真是 大大 地欺哄 这 百姓 和耶路撒冷,说:『你们 必得 平安』。其实刀剑 害 及 性命了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, '那 时,必有话对这 百姓 和耶路撒冷 说:「有一阵热 风 从旷野 净光的高处 向我的众民(原文是民女)刮来,不是 为簸扬,也不是 为扬净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, '必有一阵更大 的风 从这些地方 为我 刮来;现在 我 又 必发出 判语,攻击他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, '看哪,仇敌必如云 上来;他的战 车 如旋风,他的马匹 比鹰 更快。我们 有祸了! 我们败落了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, '耶路撒冷啊,你当洗 去心 中的恶,使你可以 得救。恶 念 存 在你心里 要到 几时呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, ' 有声音 从但 传扬,从以法莲 山 报 祸患。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, '你们当传给 列国,报告 攻击 耶路撒冷的事说:有探望的人 从远 方 来到,向 犹大 的城邑 大声 呐喊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, '他们 周围 攻击耶路撒冷,好像看守 田园的,因为 她背叛了 我。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, '你的行动,你的作为,招惹 这事;这是 你罪恶的结果,实在 是苦, 是害 及 你心了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, '我的肺腑啊,我的肺腑啊,我心 疼痛!我心 在我里面 烦躁不安。我不能 静默不言,因为 我 已经听见 角 声 和打仗 的喊声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, '毁坏 的信息连络不绝,因为 全 地 荒废。我的帐棚 忽然 毁坏;我的幔子 顷刻破裂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, '我看见 大旗,听见 角 声,要到 几时呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, '耶和华说:我的百姓 愚顽,不 认识 我;他们是 愚昧 无 知 的儿女, 有智慧 行恶,没有 知识 行善。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, '先知说:我观看 地,不料,地是空虚 混沌;我观看 天,天也无 光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, '我观看 大山,不料,尽都震动,小山 也都 摇来摇去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, '我观看,不料,无 人;空中 的飞鸟 也都 躲避。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, '我观看,不料,肥田 变为荒地;一切 城邑 在耶和华 面前,因 他的烈 怒 都被拆毁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, ' 耶和华 如此 说:全 地 必然 荒凉,我却不 毁灭 净尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, '因 此,地 要悲哀,在上 的天 也必黑暗;因为 我言已出,我意已定,必不 后悔,也不 转意 不做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, '各 城 的人因马兵 和弓箭 手 的响声 就都逃跑,进 入密林,爬 上磐石;各 城 被撇下,无 人 住 在其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, '你 凄凉 的时候要怎样 行呢?你虽 穿上 朱红衣服, 佩戴 黄金 装饰, 用颜料 修饰 眼目,这样标致 是枉然的!恋爱你的 藐视 你,并且寻索 你的性命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, ' 我听见 有声音,仿佛妇人产难的声音,好像生头胎 疼痛的声音,是锡安 女子(就是指民的意思)的声音;她喘著气、挓挲 手,说:我 有祸了!在杀人的跟前, 我的心 发昏了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, '你们当在耶路撒冷 的街上 跑来跑去,在宽阔处 寻找,看看 有 一人 行 公义 求 诚实 没有?若 有,我就赦免 这城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, '其中的人虽然 指著永生 的耶和华 起誓,所起的誓 实在 是假的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, '耶和华啊,你的眼目 不是 看顾诚实吗?你击打 他们,他们却不 伤恸;你毁灭他们,他们仍不 受 惩治。他们使脸 刚硬 过于 磐石,不肯 回头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, '我 说:这些人 实在 是贫穷的,是愚昧的,因为 不 晓得 耶和华 的作为和他们 神 的法则。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, '我 要去 见 尊大的人,对他们 说话,因为 他们 晓得 耶和华 的作为和他们 神 的法则。哪知,这些人 齐心 将轭 折断,挣开  绳索。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, '因此,林中 的狮子 必害死他们;晚上(或译:野地)的豺狼 必灭绝他们;豹子 要在 城外 窥伺他们。凡 出 城的 必被撕碎;因为 他们的罪过 极多,背道的事 也加增了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, '我怎能 赦免 你呢?你的儿女 离弃我,又指著那不是 神 的起誓。我使他们 饱足,他们就行奸淫,成群地聚集 在娼妓 家里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, '他们像 喂 𫗭饱 的马 到处乱跑,各 向 他邻舍 的妻 发嘶声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, '耶和华 说:我 岂不 因 这些事 讨罪呢?岂 不 报复 这样的 国民呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, '你们要上 她葡萄园的墙 施行毁坏,但不可 毁坏 净尽,只可除掉 她的枝子,因为 不 属耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, '原来 以色列 家 和犹大 家 大 行诡诈 攻击我。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, '他们不认 耶和华,说:这并不是 他,灾祸 必不 临到 我们;刀剑 和饥荒,我们也看不 见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, '先知 的话必成为 风;道 也不 在他们里面。 这灾必临到 他们身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, '所以 耶和华─万军之 神 如此 说:因为 百姓说 这 话,我必 使 我的话 在你口中 为火,使他们 为柴;这火便将他们烧灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, '耶和华 说:以色列 家啊,我必 使 一国的民 从远方 来攻击你,是 强盛 的国,是 从古 而有的国。他们 的言语 你不 晓得,他们 的话 你不 明白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, '他们的箭袋 是敞开  的坟墓;他们都 是勇士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, '他们必吃尽 你的庄稼 和你的粮食,是你儿 女 该吃的;必吃尽 你的牛 羊,吃尽 你的葡萄 和无花果;又必用刀 毁坏 你 所 倚靠 的坚固 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, '耶和华 说:「就是 到那 时,我也不 将你们 毁灭 净尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, ' 百姓若 说:『耶和华─我们的 神 为什么 向我们 行 这 一切事呢?』你就对他们 说:『你们怎样 离弃耶和华(原文是我),在你们的地上 事奉 外邦 神,也必照样 在不 属你们 的地上 事奉 外邦人。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, '当传扬 在雅各 家,报告 在犹大 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, '愚昧 无知 的百姓啊,你们 有眼 不 看, 有耳 不 听,现在 当听 这话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, '耶和华 说:你们怎么不 惧怕 我呢? 我以永远 的定例,用 沙 为海 的界限,水不 得越过。因此,你们在我面前 还不 战 兢吗?波浪 虽然翻腾,却不 能逾越;虽然匉訇,却不 能过去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, '但这 百姓 有 背叛 忤逆 的心;他们叛 我而去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, '心内 也不 说:我们应当 敬畏 耶和华─我们的 神;他按时 赐 雨,就是秋雨 春雨,又为我们 定 收割 的节 令,永存不废。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, '你们的罪孽 使这些事 转离你们;你们的罪恶 使你们 不能得 福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, '因为 在我民中 有 恶人。他们埋伏窥探,好像捕 鸟的人;他们设立 圈套 陷害 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, '笼 内怎样满了 雀鸟,他们的房中 也照样 充满 诡诈;所以 他们得成为大,而且富足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, '他们肥胖 光润, 作 恶 过甚,不 为人伸冤!就是不为孤儿 伸冤,不使他亨通,也不 为穷人 辨 屈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, '耶和华 说:我 岂不 因 这些事 讨罪呢? 岂不 报复 这样的 国民呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, '国中 有 可惊骇、可憎恶的事: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, '就是先知 说假 预言,祭司 藉 借 他们 把持权柄;我的百姓 也喜爱 这些事,到了结局 你们怎样 行呢?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, '便雅悯 人哪,你们要逃 出 耶路撒冷,在提哥亚 吹 角,在伯‧哈基琳 立 号旗;因为 有灾祸 与大 毁灭 从北方 张望。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, '那秀美 娇嫩 的锡安 女子(就是指民的意思),我必剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, '牧人 必引他们的羊群 到 她那里,在她 周围 支搭 帐棚,各在 自己所占之地 使羊吃草。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, '你们要准备 攻击 她。起来吧,我们可以趁午时 上去。哀哉! 日 已渐斜, 晚 影 拖长了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, '起来吧,我们夜间 上去,毁坏 她的宫殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, '因为 万军 之耶和华 如此 说:你们要砍伐 树木,筑 垒 攻打 耶路撒冷。这就是 那该罚的 城,其中 尽是 欺压。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, '井 怎样涌出 水来,这城也照样 涌出 恶来;在其间 常听见 有强暴 毁灭的事,病患 损伤 也常 在 我面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, '耶路撒冷啊,你当受教,免得 我心 与你 生疏,免得 我使你 荒凉,成为无人 居住 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, '万军 之耶和华 曾如此 说:敌人必 掳尽 以色列 剩下的民,如同摘净葡萄一样。你要像摘葡萄的人摘了又摘,回 手 放在 筐子里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, '现在我可以向 谁 说话 作见证,使他们听呢? 他们的耳朵 未受割礼,不 能 听见。看哪,耶和华 的话 他们 以为 羞辱,不 以为喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, '因此我被 耶和华 的忿怒 充满,难以 含忍。我要倾 在 街中 的孩童 和 聚会 的少年人 身上, 连 夫 带 妻,并年老的 与 日子 满足的 都必被擒拿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, '他们的房屋、田地,和妻子 都 必转归 别人; 我要伸 手 攻击 这地 的居民。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, '因为 他们从最小的 到 至大的 都 一味地 贪婪,从先知 到 祭司 都 行事 虚谎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, '他们轻轻忽忽地 医治 我百姓 的损伤,说:平安了!平安了!其实没有 平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, ' 他们行 可憎的事 知道惭愧吗?不然,他们毫 不 惭愧,也 不 知 羞耻。因此,他们必在仆倒的人中 仆倒;我向他们讨罪 的时候,他们必致跌倒。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, '耶和华 如此 说:你们当站 在 路上 察看,访问 古 道,哪 是 善 道,便行 在其间;这样,你们心 里必得 安息。他们却说:我们不 行在其间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, '我设立 守望的人 照管你们,说:要听 角 声。他们却说:我们不 听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, '列国啊,因此 你们当听!会众啊,要知道 他们 必遭遇的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, '地啊,当听! 我必 使灾祸 临 到 这 百姓,就是他们意念 所结的果子;因为 他们不 听 从 我的言语,至于 我的训诲(或译:律法),他们也厌弃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, '从示巴 出 的乳香,从远 方出的菖蒲(或译:甘蔗)奉来给我 有何益呢?你们的燔祭 不 蒙悦纳;你们的平安祭,我 也不 喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, '所以 耶和华 如此 说:我 要将绊脚石 放 在 这 百姓前面。父亲 和儿子 要一同 跌在 其上;邻舍 与朋友 也都灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, '耶和华 如此 说:看哪,有一种民 从北 方 而来,并有一大 国 被激动,从地 极来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, '他们拿 弓 和枪, 性情残忍,不 施怜悯;他们的声音 像海浪 匉訇。锡安城(原文是女子)啊,他们骑 马 都摆队伍,如上战 场 的人 要攻击你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, '我们听见 他们的风声,手 就发软;痛苦 将我们抓住,疼痛 仿佛产难的妇人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, '你们不要 往田野 去,也不要 行 在路上,因 四围 有仇敌 的刀剑 和惊吓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, '我民(原文是民 女)哪,应当腰束 麻布,滚 在灰中。你 要 悲伤,如丧独生子 痛痛 哭号,因为 灭命的 要忽然 临 到我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, '我使你 在我民中 为高台(或译:试验人的),为保障,使你知道 试验 他们的行动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, '他们都是 极 悖逆的,往来 谗谤人。他们 是铜 是铁,都 行坏事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, '风箱 吹火,铅被烧 毁;他们炼 而又炼,终是徒然;因为恶劣的 还未 除掉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, '人必称 他们 为被弃的 银渣,因为 耶和华 已经弃掉 他们。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, ' 耶和华 的话 临到 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, '「你当站 在耶和华 殿 的门口,在那里 宣传 这 话 说:你们进 这些 门 敬拜 耶和华 的一切 犹大人,当听 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, '万军 之耶和华─以色列的 神 如此 说:你们改正 行动 作为,我就使你们 在这 地方 仍然居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, '你们 不要 倚靠 虚谎 的话,说:『这些是 耶和华 的殿,是耶和华 的殿,是耶和华 的殿!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, '「 你们若 实在 改正 行动 作为, 在人 和 邻舍 中间 诚然 施行 公平, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, '不 欺压 寄居的 和孤儿 寡妇,在这 地方 不 流 无辜人 的血,也不 随 从 别 神 陷害 自己, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, '我就使你们 在这 地方 仍然居住,就是我 古时 所 赐 给你们列祖 的地,直到 永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, '「看哪,你们 倚靠 虚谎 无 益 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, '你们偷盗,杀害,奸淫,起假 誓,向巴力 烧香,并随从 素不 认识 的别 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, '且来到 这 称为 我名 下 的殿,在我面前 敬拜;又说:『我们可以自由了。』你们这样的举动 是要行 那些 可憎的事吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, '这 称为 我名 下 的殿 在你们眼中 岂可看为 贼 窝吗? 我 都 看见了。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, '你们 且 往 示罗 去, 就是 我先前 立为 我名 的居所,察看 我因 这百姓 以色列 的罪恶 向那地 所 行的如何。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, '耶和华 说:「现在 因 你们行了 这 一切 的事,我也从早起来 警戒 你们,你们却不 听从;呼唤 你们,你们却不 答应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, '所以我要向这 称 为 我名下、你们 所 倚靠 的殿,与我所 赐 给你们 和你们列祖 的地 施行,照我从前向示罗 所 行的一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, '我必将你们 从 我眼前 赶出,正如 赶出 你们的众 弟兄,就是 以法莲 的一切 后裔。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, '「所以,你 不要 为 这 百姓 祈祷;不要 为他们 呼求 祷告,也不要 向我 为他们祈求,因 我 不 听允 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, '他们 在犹大 城邑中 和耶路撒冷 街上 所 行的,你没有 看见吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, '孩子 捡 柴,父亲 烧 火,妇女 抟 面 麺 做 饼,献给天 后,又向别 神 浇 奠祭, 惹我发怒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, '耶和华 说:「他们 岂是惹我 发怒呢?不是 自己惹祸,以致 脸 上惭愧吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, '所以 主 耶和华 如此 说:「看哪,我必将我的怒气 和忿怒 倾 在 这 地方的 人 和 牲畜身上,并 田野 的树木 和 地 里的出产上,必如火著起,不能 熄灭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, '万军 之耶和华─以色列的 神 如此 说:「你们将燔祭 加 在 平安祭上,吃 肉吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, '因为 我将 你们列祖 从埃及 地 领出来 的那日, 燔祭 平安祭 的事 我并没有 提说,也没有 吩咐 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, ' 我只 吩咐 他们 这 一件 说:『你们当听从 我的话,我就作 你们的 神,你们 也作 我的 子民。你们行 我所 吩咐 的一切 道,就可以 得福。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, '他们却不 听从,不 侧 耳而听,竟随从 自己的计谋 和顽梗 的恶 心, 向后 不 向前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, '自从 你们列祖 出 埃及 地 的那日,直到 今 日,我差遣 我的仆人 众 先知 到你们那里去,每日 从早起来 差遣他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, '你们却不 听从,不 侧 耳而听,竟硬著 颈项 行恶,比你们列祖更甚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, '「你要将 这 一切的 话 告诉 他们,他们却不 听从;呼唤 他们,他们却不 答应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, '你要对他们 说:这 就是 不 听从 耶和华─他们 神 的话、不 受 教训 的国民;从他们的口中,诚实 灭绝了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, '耶路撒冷啊,要剪 发 抛弃,在 净光的高处 举 哀;因为 耶和华 丢掉 离弃了 惹他忿怒 的世代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, '耶和华 说:「 犹大 人 行 我眼中 看为恶的事,将可憎之物 设立 在称 为 我名 下的殿中,污秽这殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, '他们在 欣嫩 子 谷 建筑 陀斐特 的邱坛,好在火中 焚烧自己的 儿 女。这 并不是 我所吩咐的,也不是 我心 所起的意。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, '耶和华 说:「 因此,日子 将到,这地方不 再 称为 陀斐特 和欣嫩 子 谷,反倒 称为杀戮 谷。因为要在陀斐特 葬埋尸首,甚至无 处可葬; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, '并且这 百姓 的尸首 必给空中 的飞鸟 和地上 的野兽 作 食物,并无人 哄赶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, '那时,我必使犹大 城邑中 和耶路撒冷 街上,欢喜 和快乐 的声音,新郎 和新妇 的声音,都止息了,因为 地 必成为 荒场。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, '耶和华 说:「到那 时,人必将 犹大 王 的骸骨 和 他首领 的骸骨、 祭司 的骸骨、 先知 的骸骨,并 耶路撒冷 居民 的骸骨,都从坟墓 中取出来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, '抛散 在日头、月亮,和天上 众 星之下,就是他们从前所 喜爱、所 事奉、所 随 从、所 求问、所 敬拜的。这些骸骨不 再收殓,不 再葬埋,必在 地 面 上成为 粪土; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, '并且这 恶 族 所 剩下的 民 在我所 赶 他们到的各 处,宁可拣 死 不拣生。这是万军 之耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, '你要对他们 说,耶和华 如此 说:人跌倒,不 再起来吗? 人转去,不 再转来吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, '这 耶路撒冷 的民,为何 恒久 背道呢?他们守定 诡诈,不肯 回头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, '我留心听,听见 他们说 不 正直的话。无 人 悔改 恶行,说:我做 的是什么呢?他们各人 转奔 己路,如马 直闯 战 场。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, ' 空中 的鹳鸟 知道 来去的定期;斑鸠 燕子 与白鹤 也守候 当来 的时令;我的百姓 却不 知道 耶和华 的法则。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, '你们怎么 说:我们 有智慧,耶和华 的律法 在我们这里? 看哪,文士 的假 笔 舞弄 虚假。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, '智慧人 惭愧,惊惶,被擒拿; 他们弃掉 耶和华 的话,心里 还有什么 智慧呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, '所以 我必将 他们的妻子 给 别人,将他们的田地 给别人为业;因为 他们从最小的 到 至大的 都 一味地 贪婪,从先知 到 祭司 都 行事 虚谎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, '他们轻轻忽忽地 医治 我百姓 的损伤,说:平安了!平安了!其实没有 平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, ' 他们行 可憎的事 知道惭愧吗?不然,他们毫 不 惭愧,也不 知 羞耻。因此 他们必在仆倒的人中 仆倒;我向他们讨罪 的时候,他们必致跌倒。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, '耶和华 说:我必使他们全然 灭绝;葡萄树上 必没有 葡萄,无花果树上 必没有 果子,叶子 也必枯干。我所赐 给他们的,必离开 他们过去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, '我们 为何 静坐不动呢?我们当聚集,进 入 坚固 城,在那里 静默不言;因为 耶和华─我们的 神 使我们静默不言,又将苦胆 水 给我们喝,都因 我们得罪了 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, '我们指望 平安,却得不著 好处;指望痊愈 的时候,不料,受了惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, '听见 从但 那里敌人的马 喷鼻气,他的壮 马发嘶声,全 地 就都震动;因为他们来 吞灭 这地 和其上所有的,吞灭这城 与其中 的居民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, ' 看哪,我必使 毒蛇 到你们中间,是 不 服法术的,必咬 你们。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, '我有 忧愁,愿 能自慰;我心 在我里面 发昏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, '听啊,是我百姓 的哀 声 从极远 之地而来,说:耶和华 不 在锡安吗? 锡安 的王 不 在其中么?耶和华说:他们为什么 以雕刻的偶像 和外邦 虚无 的神惹我发怒呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, '麦秋 已过,夏令 已完,我们 还未 得救! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, '先知说:因 我百姓 的损伤,我也受了损伤。我哀痛,惊惶 将我抓住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, '在基列 岂没有 乳香呢? 在那里 岂没有 医生呢?我百姓 为何 不 得痊愈呢?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, '但愿  我的头 为 水,我的眼 为泪 的泉源,我好为我百姓(原文是民 女;七节同)中被杀的 人昼 夜 哭泣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, '惟愿  我在旷野 有 行路人 住宿之处,使我可以离开  我的民 出去;因 他们都是 行奸淫的,是行诡诈的 一党。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, '他们弯起 舌头 像弓一样,为要说谎话。他们在国中 增长势力,不是 为行诚实,乃 是 恶上 加 恶,并不 认识 我。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, '你们各人 当谨防 邻舍,不可 信靠 弟兄;因为 弟兄 尽行 欺骗,邻舍 都 往来 谗谤人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, '他们各人 欺哄 邻舍,不 说 真话;他们教 舌头 学习说 谎,劳劳碌碌地 作孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, '你的住处 在诡诈的人 中;他们因行诡诈,不肯 认识 我。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, '所以 万军 之耶和华 如此 说:看哪,我要将他们镕化 熬炼;不然,我因 我百姓 的罪该怎样 行呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, '他们的舌头 是毒 箭,说话 诡诈;人与 邻舍 口 说 和平话,心 却谋 害他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, '耶和华 说:我 岂不 因 这些事 讨 他们的罪呢?岂 不 报复 这样的 国民呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, '我要为 山岭 哭 泣 悲哀,为 旷野 的草场 扬声哀号;因为 都已干焦,甚至无 人 经过。人也听不 见 牲畜 鸣叫,空中 的飞鸟 和 地上的野兽 都已逃 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, '我必使 耶路撒冷 变为乱堆,为野狗 的住处,也必使 犹大 的城邑 变为荒场,无人 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, '谁是 智慧 人,可以明白 这事?耶和华 的口 向谁 说过,使他可以传说?遍地 为何 灭亡,干焦 好像旷野,甚至无人 经过呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, '耶和华 说:「因为 这百姓离弃我,在他们面前 所 设立 的律法 没有 遵行,也没有 听从 我的话; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, '只随从 自己顽梗 的心 行事,照 他们列祖 所 教训的 随从 众巴力。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, '所以 万军 之耶和华─以色列的 神 如此 说:「看哪,我必将茵𫈟 给 这 百姓 吃,又将苦胆 水 给他们喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, '我要把他们散 在列邦中,就是 他们 和他们列祖 素不 认识的列邦。我也要使 刀剑 追杀 他们,直到 将他们 灭尽。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, '万军 之耶和华 如此 说:你们应当思想,将善唱哀歌的妇女 召 来,又打发人 召 善哭 的妇女来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, '叫她们速速 为我们 举 哀,使我们眼 泪 汪汪,使我们的眼皮 涌出 水来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, '因为 听见 哀 声 出于 锡安,说:我们怎样 败落了!我们大大地 惭愧! 我们撇下 地土; 人也拆毁了 我们的房屋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, '妇女们哪,你们当 听 耶和华 的话,领受 他口中 的言语;又当教导 你们的儿女 举哀,各人 教导邻舍 唱哀歌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, '因为 死亡 上来,进了我们的窗户,入了 我们的宫殿;要从外边 剪除 孩童,从街上 剪除少年人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, '你当说,耶和华 如此 说:人 的尸首 必倒 在 田野 像粪土,又像收割的人 遗落 的一把禾稼,无人 收取。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, '耶和华 如此 说:「智慧人 不要 因他的智慧 夸口,勇士 不要 因他的勇力 夸口,财主 不要 因他的财物 夸口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, ' 夸口的 却 因 他有聪明,认识 我 是耶和华,又知道 我 喜悦 在世上 施行 慈爱、公平,和公义,以 此 夸口。这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, '耶和华 说:「看哪,日子 将到,我要刑罚 一切 受过割礼、心却未受割礼的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, '就是 埃及、 犹大、 以东、 亚扪 人、 摩押人,和 一切 住 在旷野 剃 周围头发的;因为 列国人 都 没有受割礼, 以色列 人 心中 也没有受割礼。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, '以色列 家啊,要听 耶和华 对你们 所 说 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, '耶和华 如此 说:你们不要 效法 列国 的行为,也不要 为天 象 惊惶,因 列国 为此事 惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, ' 众民 的风俗 是 虚空的; 他们在树林中 用斧子 砍伐 一棵树,匠人 用手 工造成偶像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, '他们用金 银 妆饰它,用钉子 和锤子 钉稳,使它不 动摇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, '它好像棕树,是旋 镟成的, 不能 说话, 不能 行走,必须 有人抬著。你们不要 怕 它; 它不能 降祸,也 无力 降福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, '耶和华啊,没有能 比你的!你 本为大,有大能 大力 的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, '万国 的王啊,谁 不 敬畏你?敬畏你 本是 合宜的;因为 在列 国 的智慧人中,虽有 政权的尊荣,也不能 比你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, '他们尽都是 畜类,是愚昧的。偶像 的训诲算什么呢?偶像不过是 木头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, '有银子 打成片,是从他施 带来的,并有从乌法 来的金子,都是匠人 和银匠 的手 工,又有蓝色 紫色 料的衣服,都是 巧匠 的工作。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, '惟耶和华 是真 神,是 活 神,是永远 的王。他一发怒,大地 震动;他一恼恨,列国 都担当不 起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, '(你们要对他们 如此 说:不是 那 创造 天 地 的神,必从地上 从 天 下 被除灭!) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, '耶和华 用能力 创造 大地,用智慧 建立 世界,用聪明 铺张 穹苍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, '他一发 声,空中 便有多 水激动;他使云雾 从地 极 上腾;他造 电 随雨而闪,从他府库 中带出 风来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, '各人 都 成了畜类,毫无知识;各 银匠 都因他雕刻的偶像 羞愧。他所铸的偶像 本是 虚假的,其中 并无 气息, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, '都是 虚无的,是迷惑 人的工作;到追讨 的时候 必被除灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, '雅各 的分 不 像这些,因 他是 造作 万有的主。以色列 也是他产业 的支派,万军 之耶和华 是他的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, '受围困 的人哪,当收拾 你的财物,从国中带出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, '因为 耶和华 如此 说: 这 时候,我必将 此地 的居民,好像用机弦甩出去,又必加害 在他们身上,使他们 觉悟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, '民说:祸哉! 我受损伤;我的伤痕 极其重大。我 却说:这 真是 我的痛苦,必须忍受。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, '我的帐棚 毁坏; 我的绳索 折断。我的儿女 离我出去,没有了。无人 再 支搭 我的帐棚,挂起 我的幔子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, '因为 牧人 都成为畜类,没有 求问 耶和华,所以 不 得顺利;他们的羊群 也都 分散。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, '有风 声!看哪,敌人来了!有大 扰乱 从北 方出来,要使 犹大 城邑 变为荒凉,成为野狗 的住处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, '耶和华啊,我晓得 人 的道路 不由自己,行路 的人 也不能 定 自己的脚步。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, '耶和华啊,求 你从宽 惩治我,不要 在你的怒中惩治我,恐怕 使我归于 无有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, '愿 你将忿怒 倾 在 不 认识你 的列国中,和 不 求告 你名 的各族上;因为 他们吞了 雅各,不但吞了,而且灭绝,把 他的住处 变为荒场。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, ' 耶和华 的话 临 到 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, '「当听 这 约 的话,告诉 犹大 人 和 耶路撒冷 的居民, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, '对他们 说,耶和华─以色列的 神 如此 说: 不 听从 这 约 之话 的人 必受咒诅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, '这约是我将 你们列祖 从埃及 地 领出来、脱离铁 炉 的那日 所 吩咐 他们的,说:『你们要听从 我的话,照我一切 所 吩咐的 去行。』这样,你们就作 我的 子民,我 也作 你们的 神; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, '我好 坚定 向你们列祖 所 起的 誓,给 他们 流 奶 与蜜 之地,正如今 日一样。」我就回答 说:「耶和华啊,阿们!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, '耶和华 对我 说:「你要在犹大 城邑中 和耶路撒冷 街市上,宣告 这 一切 话 说:你们当听从 遵行 这 约 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, '因为 我将 你们列祖 从埃及 地 领出来 的那日,直到 今 日,都是从早起来,切切 诰诫 他们 说:『你们当听从 我的话。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, '他们却不 听从,不 侧 耳而听,竟随从自己 顽梗的 恶 心 去行。所以我使 这 约 中一切 咒诅的话 临 到他们身上;这约 是我吩咐 他们行的,他们却不 去行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, '耶和华 对我 说:「在犹大 人 和耶路撒冷 居民中 有 同谋背叛的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, '他们转去 效法 他们的先 祖, 不肯 听 我的话,犯罪作孽,又 随 从 别 神,事奉它。以色列 家 和犹大 家 背了 我与 他们列祖 所 立的 约。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, '所以 耶和华 如此 说:「我 必使灾祸 临 到他们,是 他们不 能 逃脱 的。他们必向我 哀求,我却不 听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, '那时,犹大 城邑 的人和耶路撒冷 的居民 要去 哀求 他们 烧香 所 供奉的神;只是遭难 的时候,这些神毫 不 拯救 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, '犹大啊, 你神 的数目 与你城 的数目 相等;你为那可耻 的巴力 所筑 烧香的 坛 也与耶路撒冷 街道 的数目相等。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, '「所以你 不要 为 这 百姓 祈祷,不要 为他们 呼 求 祷告;因为 他们遭难 向我 哀求 的时候,我必不 应允。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, '我所亲爱的,既行 许多 淫乱,圣 肉 也离了 你,你在我殿中 做什么呢? 你作恶 就 喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, '从前耶和华 给你起 名 叫青 橄榄树,又华美 又结好 果子;如今他用哄 嚷 之声,点 火 在其上,枝子 也被折断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, '原来栽培 你 的万军 之耶和华 已经说,要降祸 攻击你,是因 以色列 家 和犹大 家 行恶,向巴力 烧香,惹我发怒,是 自作 自受。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, '耶和华 指示我,我就 知道;你将他们所行的 给我指明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, '我 却像柔顺的 羊羔 被牵到 宰杀之地;我并不 知道 他们设计 谋 害我,说:我们把树 连果子 都灭了吧!将他从活人 之地 剪除,使他的名 不 再 被纪念。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, '按公义 判断、察验 人肺腑 心肠 的万军 之耶和华啊,我却要见 你在他们身上 报仇,因 我将 我的案件 向你 禀明了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, '所以,耶和华 论到 寻索 你命 的亚拿突 人 如此 说:「他们说:你不要 奉耶和华 的名 说预言,免得 你死 在我们手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, '所以 万军 之耶和华 如此 说:看哪,我必刑罚 他们;他们的少年人 必被刀剑 杀死,他们的儿 女 必因饥荒 灭亡, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, '并且没 有 余 馀剩的 人留给他们;因为 在追讨 之年,我必使灾祸 临 到 亚拿突 人。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, '耶和华啊,我与你 争辩 的时候,你 显为义;但 有一件,我还要与你 理论:恶人 的道路 为何 亨通呢? 大 行诡诈的 为何得安逸呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, '你栽培了他们,他们也 扎了根,长大,而且 结 果。他们的口 是与你 相近,心 却与你远离。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, '耶和华啊,你 晓得我,看见我,察验 我向你 是怎样的心。求你将他们拉出来,好像将宰 的羊,叫他们等候 杀戮 的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, '这地 悲哀,通 国 的青草 枯干,要到 几时呢?因其上 居民 的恶行,牲畜 和飞鸟 都灭绝了。 他们曾说:他看不 见 我们的结局。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, '耶和华说:你若 与 步行的人 同跑,尚且觉累,怎能 与 马 赛跑呢?你 在平安 之地,虽然安稳,在约旦 河边的丛林 要怎样 行呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, '因为 连 你弟兄 和你父 家 都用奸诈 待你。他们 也 在你后边 大声 喊叫,虽 向你 说 好话,你也不要 信 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, '我离了 我的殿宇,撇弃 我的产业,将 我心 里所亲爱的 交 在她仇敌的 手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, '我的产业 向我 如 林中 的狮子,她发 声 攻击我,因此 我恨恶她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, '我的产业 向我 岂如斑点的 鸷鸟呢?鸷鸟 岂在她四围 攻击她呢?你们要去 聚集 田野 的百 兽,带来 吞吃吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, '许多 牧人 毁坏 我的葡萄园,践踏 我的分,使 我美好 的分 变为荒凉 的旷野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, '他们使 地荒凉;地既荒凉,便向我 悲哀。全 地 荒凉,因 无 人 介 意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, '灭命的 都来 到 旷野中 一切 净光的高处; 耶和华的 刀 从地 这边 直到 地 那边 尽行杀灭。凡 有血气的 都不 得平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, '他们种 的是麦子,收 的是荆棘;劳劳苦苦 却毫无 益处。因耶和华 的烈 怒,你们必为自己的土产 羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, '耶和华 如此 说:「 一切 恶 邻,就是 占据 我使 百姓 以色列 所承受 产业的, 我要将他们拔 出 本地,又要将 犹大 家 从他们中间 拔出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, ' 我拔出 他们 以后,我必转过来 怜悯他们,把他们再带回来,各 归本业,各 归故土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, ' 他们若 殷勤 学习 我百姓 的道,指著我的名 起誓说:『我指著永生 的耶和华起誓』,正如 他们从前教 我百姓 指著巴力 起誓,他们就必建立 在我百姓 中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, '他们若是 不 听,我必拔出 那 国,拔出 而且毁灭。这是耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, '耶和华 对我 如此 说:「你去 买  一根麻布 带子 束 腰,不可 放在 水中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, '我就照著耶和华 的话,买 了 一根带子 束 腰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, '耶和华 的话 第二次 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, '「要拿著 你所 买 的 腰带,就是 你腰 上的带子,起来 往幼发拉底河 去,将腰带藏在 那里 的磐石 穴中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, '我就去,照著 耶和华 所吩咐 我的,将腰带藏 在幼发拉底河边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, ' 过了 多 日,耶和华 对我 说:「你起来 往幼发拉底河 去,将 我吩咐 你藏 在那里 的 腰带 取出来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, '我就往幼发拉底河 去, 将 腰带 从 我所 藏 的地方 刨出来,见 腰带 已经变坏,毫 无 用了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, '「耶和华 如此 说:我必照样 败坏 犹大 的骄傲 和 耶路撒冷 的大 骄傲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, '这 恶 民 不肯 听 我的话,按自己顽梗 的心 而行,随 从 别 神,事奉 敬拜,他们也必 像这 腰带 变为无 用。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, '耶和华 说:「 腰带 怎样 紧贴 人 腰,照样,我也使 以色列 全 家 和 犹大 全 家 紧贴 我,好叫他们 属我 为子民,使我得名声,得颂赞,得荣耀;他们却不肯 听。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, '「所以你要对他们 说:『耶和华─以色列的 神 如此 说:各 坛 都要盛满了 酒。』他们必对你 说:『我们岂不 确 知 各 坛 都要盛满了 酒呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, '你就要对他们 说:『耶和华 如此 说: 我必使 这 地 的一切 居民,就是坐 大卫 宝座 的 君王 和 祭司,与 先知,并 耶路撒冷 的一切 居民,都酩酊大醉。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, '耶和华 说:「我要使他们彼此相 碰,就是父 与子 彼此相碰;我必不 可怜,不 顾惜,不 怜悯,以致灭绝他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, '你们当听,当侧耳而听。不要 骄傲,因为 耶和华 已经说了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, '耶和华─你们的 神 未使 黑暗来到,你们的脚 未在 昏暗 山 上绊跌 之先,当将荣耀 归 给他;免得你们盼望 光明,他使光明变为 死荫,成为 幽暗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, '你们若 不 听这话,我 必因 你们的骄傲 在暗地 哭泣;我眼 必痛 哭 流 泪,因为 耶和华 的群众 被掳去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, '你要对君王 和太后 说:你们当自卑,坐在下边;因 你们的头巾,就是你们的华 冠,已经脱落了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, '南方 的城 尽都关闭,无人 开 放;犹大 全 被掳掠,且掳掠 净尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, '你们要举 目 观看 从北方 来的人。先前赐给 你的群众,就是你 佳美 的群众,如今在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, '耶和华立 你自己所交的 朋友 为 首,辖制你,那时 你还有什么 话说呢?痛苦 岂不 将你抓住 像 产难的 妇人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, '你若 心里 说:这一切事 为何 临到我呢?你的衣襟 揭起,你的脚跟 受伤,是因你的罪孽 甚多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, '古实人 岂能改变 皮肤呢?豹 岂能改变斑点呢?若能,你们 这习惯 行恶的 便能 行善了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, '所以我必用旷野 的风 吹散他们,像吹过的 碎秸一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, '耶和华 说:这是 你所当得的,是我 量 给你的分;因为 你忘记 我,倚靠 虚假(或译:偶像)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, '所以 我要 揭起 你的衣襟,蒙在 你脸上,显出 你的丑陋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, '你那些可憎恶之事─就是在田野 的 山 上行奸淫,发嘶声,做淫乱 的事─我都看见了。耶路撒冷啊,你 有祸了!你不肯 洁净,还 要到 几时呢?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, '耶和华 论 到 干旱 之灾的 话 临 到 耶利米: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, '犹大 悲哀,城门 衰败。众人披上黑 衣坐在地上;耶路撒冷 的哀声 上达。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, '他们的贵胄 打发 家僮 打水;他们来 到 水池,见 没有 水,就拿著空 器皿,蒙羞 惭愧,抱 头 而回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, '耕地的 也蒙羞 抱 头;因为 无 雨 降 在地上, 地 都干裂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, ' 田野 的母鹿 生下小鹿,就撇弃,因为 无 草。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, '野驴 站 在 净光的高处,喘 气 好像野狗;因为 无 草,眼目 失明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, '耶和华啊,我们的罪孽 虽然 作见证 告我们,还求你为 你名 的缘故行事。我们本是 多 次背道,得罪了 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, '以色列 所盼望、在患难 时 作他救主的啊,你为何 在这地 像寄居的,又像行路的 只住 一宵呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, '你为何 像受惊的 人,像不 能 救 人的勇士呢?耶和华啊,你 仍在我们中间;我们也称 为你名 下的人,求你不要 离开 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, '耶和华 对这 百姓 如此 说: 这百姓喜爱妄行(原文是飘流),不 禁止 脚步,所以耶和华 不 悦纳他们。现今 要记念 他们的罪孽,追讨 他们的罪恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, '耶和华 又对我 说:「不要 为 这 百姓 祈祷 求好处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, '他们禁食 的时候,我不 听 他们的呼求; 他们献 燔祭 和素祭,我也不 悦纳;我 却 要用刀剑、饥荒、瘟疫 灭绝 他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, '我就说:「唉!主 耶和华啊, 那些先知 常对他们 说:『你们 必不 看见 刀剑,也不 遭遇 饥荒; 耶和华要在这 地方 赐 你们 长久的 平安。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, '耶和华 对我 说:「那些先知 托 讬我的名 说假 预言,我并没有 打发他们,没有 吩咐他们,也没有 对他们 说话;他们 向你们 预言的,乃是虚假 的异象 和占卜,并虚无的 事,以及本心 的诡诈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, '所以 耶和华 如此 说:论到 托 讬我名 说预言的 那些先知,我 并没有 打发他们;他们 还说 这 地 不 能有 刀剑 饥荒,其实那些 先知 必被刀剑 饥荒 灭绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, ' 听他们 说预言的 百姓 必 因 饥荒 刀剑 抛 在 耶路撒冷 的街道上,无人 葬埋。他们 连妻子 带儿 女,都是如此。我必将 他们的恶 倒 在他们身上(或译:我必使他们罪恶的报应临到他们身上)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, '你要将 这 话 对他们 说:愿 我眼 泪 汪汪,昼 夜 不 息,因为 我百姓(原文是民的处女)受了 裂口 破坏的 大 伤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, '我若 出 往田间,就见 有被刀 杀的;我若 进入 城内,就见 有因饥荒 患病的; 连 先知 带 祭司 在 国 中往来,也是毫无 知识(或译:不知怎样才好)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, '你全然 弃掉 犹大吗?你心 厌恶 锡安吗?为何 击打我们,以致无法 医治呢?我们指望 平安,却得不著 好处;指望痊愈,不料,受了惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, '耶和华啊,我们承认 自己的罪恶,和我们列祖 的罪孽,因 我们得罪了 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, '求你为 你名的缘故,不 厌恶我们,不 辱没 你荣耀 的宝座。求你追念,不要 背了 与我们 所立的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, '外邦人 虚无的神中 有 能降雨的吗? 天 能自降 甘霖吗?耶和华─我们的 神啊,能如此的 不是 你吗?所以,我们仍要等候 你,因为 这 一切都 是你 所造的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, '耶和华 对我 说:「虽有 摩西 和撒母耳 站 在我面前代求,我的心 也不 顾惜 这 百姓。你将他们从 我眼 前赶出,叫他们去吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, ' 他们问你 说:『我们往哪里 去呢?』你便告诉 他们,耶和华 如此 说:定为 死亡的,必致死亡;定为 刀杀的,必交刀杀;定为 饥荒的,必遭饥荒;定为 掳掠的,必被掳掠。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, '耶和华 说:「我命定 四 样 害他们,就是 刀剑 杀戮、 狗类 撕裂、 空中 的飞鸟,和 地上 的野兽 吞吃 毁灭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, '又必使他们 在天下 万 国 中抛来抛去,都因 犹大 王 希西家 的儿子 玛拿西 在耶路撒冷 所 行的事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, '耶路撒冷啊, 谁 可怜 你呢?谁 为你 悲伤呢?谁 转身 问 你 的安呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, '耶和华 说:你 弃绝了 我,转身退 后;因此我伸 手 攻击你,毁坏你。我后悔 甚不耐烦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, '我在境内各城门口(或译:我在这地边界的关口),用簸箕 簸了 我的百姓,使他们丧掉儿女。我毁灭他们,他们仍不 转离 所行的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, '他们的寡妇 在我面前 比海 沙 更多;我使 灭命的 午间来,攻击 少年人 的母亲,使痛苦 惊吓 忽然 临 到她身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, '生过 七 子的妇人力衰 气 绝;尚在 白昼,日头 忽落;她抱愧 蒙羞。其余 馀的人,我必在他们敌人 跟前,交 与刀剑。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, '我的母亲哪,我 有祸了!因 你生我 作为遍 地 相争 相竞 的人。我素来没有 借贷与人,人也没有 借贷 与我,人人却都 咒骂我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, '耶和华 说:「我必要 坚固你,使你得好处。灾祸 苦难 临到的时候,我必要 使 仇敌 央求 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, '(人岂能将铜 与铁,就是北方的 铁 折断呢?) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, '「我必因你在四 境 之内所犯的一切 罪,把你的货物 财宝 当掠物,白白地 交给仇敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, '我也必使 仇敌 带这掠物到 你所不 认识 的地去,因 我怒中 起 的火 要将你们 焚烧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, '耶和华啊,你是 知道的;求你记念我,眷顾我,向逼迫我的人 为我 报仇;不要 向他们忍 怒 取我的命,要知道 我为你的缘故 受了 凌辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, '耶和华─万军之 神啊,我得著 你的言语 就当食物吃了;你的言语 是 我 心 中的欢喜 快乐,因 我是称为 你名 下的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, '我没有 坐 在宴乐人 的会中,也没有欢乐;我因你的感动(原文是手)独自 静坐,因 你使我满 心愤恨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, ' 我的痛苦 为何 长久不止呢?我的伤痕 为何无法医治、不能 痊愈呢?难道 你 待我 有诡诈,像 流干的 河道吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, ' 耶和华 如此 说:你若 归回,我就将你再带来,使你站 在我面前;你若 将宝贵的 和下贱的 分别出来,你就可以当作 我的口。他们必 归 向你,你 却不可 归 向他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, '我必使你 向这 百姓 成为坚固的 铜 墙;他们必攻击 你,却不 能胜 你;因 我与你同在,要拯救你,搭救你。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, '我必搭救你 脱离恶人 的手,救赎你 脱离强暴人 的手。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, '耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, '「你 在这 地方 不可 娶 妻, 生儿 养女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, '因为 论到 在这 地方 所生的 儿 女,又论到 在这 国中 生 养 他们 的父 母,耶和华 如此 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, '他们必 死 得甚苦,无人 哀哭,必不 得葬埋,必在 地 上 像粪土,必 被刀剑 和饥荒 灭绝;他们的尸首 必 给空 中的飞鸟 和地 上的野兽 作食物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, ' 耶和华 如此 说:「不要 进入 丧 家,不要 去 哀哭,也不要 为他们 悲伤,因 我已将 我的平安、 慈爱、 怜悯 从 这 百姓 夺去了。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, '连大 带小,都必在这 地 死亡,不 得葬埋。人必不 为他们 哀哭,不 用刀划 㓰身,也不 使头光秃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, '他们有 丧事,人必不 为他们擘饼,因 死人 安慰他们;他们丧 父 丧 母,人也不 给 他们 一杯 酒安慰他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, '你不可 进入 宴乐 的家,与他们 同坐 吃 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, '因为 万军 之耶和华─以色列的 神 如此 说: 你们还活著的日子 在你们眼前,我必使欢喜 和快乐 的声音,新郎 和新妇 的声音,从 这 地方 止息了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, '「 你将 这 一切 的话 指示 这 百姓。他们问你 说:『耶和华 为 什么 说,要降 这 大 灾祸 攻击我们呢?我们有什么 罪孽呢? 我们向耶和华─我们的 神 犯了 什么 罪呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, '你就对他们 说:『耶和华 说:因 为 你们列祖 离弃 我,随 从 别 神,事奉 敬拜, 不 遵守 我的律法, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, '而且你们 行 恶 比你们列祖更甚; 因为各人 随 从 自己顽梗的恶 心 行事,甚至不 听从 我, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, '所以我必将你们 从 这 地 赶出,直赶到 你们和你们列祖 素不 认识 的地。你们 在那里 必昼 夜 事奉 别 神,因为 我必不 向你们 施 恩。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, ' 耶和华 说:「 日子 将到,人必不 再 指著那领 以色列 人 从埃及 地 上来 之永生的 耶和华 起誓, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, ' 却 要指著那领 以色列 人 从北方 之地,并赶他们 到的 各 国 上来 之永生的 耶和华起誓,并且我要领他们 再入 我从前赐 给他们列祖 之地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, '耶和华 说:「 我要召 许多 打鱼的 把以色列人打上来,然后 我要召 许多 打猎的,从 各 山上、 各 冈上、各石 穴 中猎取他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, '因 我的眼目 察看 他们的一切 行为;他们不能 在我面 前遮掩,他们的罪孽 也不能 在 我眼 前隐藏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, '我先 要加倍 报应 他们的罪孽 和罪恶;因为 他们用可憎 之尸 玷污 我的地土,又用可厌之物 充满 我的产业。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, '耶和华啊,你是我的力量,是我的保障;在苦难 之日 是我的避难所。列国人 必从地 极 来 到你这里,说:我们列祖 所承受的,不过是 虚假,是虚空 无 益 之物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, '人 岂可为自己 制造 神呢?其实这 不是 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, '耶和华说:「 我要使他们知道,就是这 一次 使他们知道 我的手 和 我的能力。他们就知道 我的名 是耶和华了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, '犹大 的罪 是用铁 笔、用金钢 钻 记录的,铭刻 在 他们的心 版 上和坛 角上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, '他们的儿女 记念他们 高 冈上、 青翠 树 旁的坛 和木偶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, '我田野 的山哪,我必因你在四 境 之内所犯的罪,把你的货物、 财宝,并邱坛 当掠物 交给仇敌; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, '并且你因自己的罪 必失去 我所 赐 给你 的产业。我也必使你在你所 不 认识的 地上 服事 你的仇敌;因为 你使我怒中 起 火,直烧 到 永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, '耶和华 如此 说:倚靠 人 血肉 的膀臂,心 中离弃 耶和华 的,那人 有祸了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, '因他必 像沙漠 的杜松,不 见 福乐 来到,却要住 旷野 干旱之处,无人 居住 的碱 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, '倚靠 耶和华、以耶和华 为 可靠 的,那人 有福了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, '他必 像树 栽 于  水旁,在 河 边扎 根, 炎热 来到,并不 惧怕,叶子 仍必 青翠,在干旱 之年 毫无 挂虑,而且结 果 不 止。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, '人心 比万物 都诡诈,坏到极处,谁 能识透呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, '我─耶和华 是鉴察 人心、试验 人肺腑的,要照各人 所行的 和他做事 的结果 报应他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, '那不 按正道 得 财的,好像鹧鸪 菢 不是 自己下的蛋;到了中 年,那财都必离开 他,他终久 成为 愚顽人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, '我们的圣所 是荣耀 的宝座,从太初 安置在高 处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, '耶和华─以色列 的盼望啊,凡 离弃你 的必致蒙羞。耶和华说:离开 我的,他们的名字必写 在土里,因为 他们离弃我 这活 水 的泉源。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, '耶和华啊,求你医治我,我便痊愈,拯救我,我便得救;因 你是 我所赞美的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, ' 他们 对我 说:耶和华 的话 在哪里呢?叫 这话应验吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, '至于 我,那跟从你 作牧人的职分,我并没有 急忙离弃,也没有 想 那灾殃 的日子;这是你 知道的。我口 中所出的 言语都 在 你面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, '不要 使 我 因你惊恐;当灾祸 的日子,你是 我的避难所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, '愿 那些逼迫我 的蒙羞,却不要 使我 蒙羞;使他们 惊惶,却不要 使我 惊惶;使灾祸 的日子 临 到他们,以加倍 的毁坏 毁坏他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, '耶和华 对我 如此 说:「你去 站 在平民 的门口,就是 犹大 君王 出 入的门,又站在耶路撒冷 的各 门口, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, '对他们 说:『你们这犹大 君王 和犹大 众人,并耶路撒冷 的一切 居民,凡从这些 门 进入 的都当听 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, '耶和华 如此 说:你们 要谨慎,不要 在安息 日 担 什么担子 进入 耶路撒冷 的各门; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, '也不要 在安息 日 从家中 担出 担子去。无论何工 都 不可 做,只要以 安息 日 为圣日,正如我所 吩咐 你们列祖的。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, '他们却不 听从,不 侧 耳而听,竟硬著 颈项 不 听,不 受 教训。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, ' 耶和华 说:「你们若 留意 听从 我,在安息 日 不 担什么担子 进入 这 城 的各门,只以 安息 日 为圣日,在那日 无论何工 都 不 做; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, '那时就有坐 大卫 宝座 的君王 和首领,他们 与犹大 人,并耶路撒冷 的居民,或坐 车,或骑马,进入 这 城 的各门,而且这 城必存 到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, '也必有人从犹大 城邑 和耶路撒冷 四围的各处,从便雅悯 地、 高原、 山地,并 南地 而来,都带 燔祭、平安祭、素祭,和乳香,并感谢祭,到 耶和华 的殿去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, '你们若 不 听从 我,不 以 安息 日 为圣日,仍在安息 日 担 担子,进 入耶路撒冷 的各门,我必在各门 中点 火;这火也必烧毁 耶路撒冷 的宫殿,不能 熄灭。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, ' 耶和华 的话 临 到 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, '「你起来,下到 窑匠的 家里去,我在那里 要使你听 我的话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, '我就下到 窑匠的 家里去,正遇他 转 轮 做 器皿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, '窑匠 用泥 做 的器皿, 在他 手中 做坏了,他又 用这泥另 做 别的 器皿;窑匠 看 怎样 好,就怎样做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, '耶和华 的话 就临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, '耶和华 说:「以色列 家啊,我待 你们,岂不 能 照这 窑匠弄泥吗? 以色列 家啊,泥 在窑匠的 手中怎样,你们 在我的手中 也怎样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, '我何时 论 到 一邦 或 一国说,要拔出、拆毁、毁坏; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, '我所 说 的 那 一邦,若是转 意离开 他们的恶,我就必后悔, 不将 我想 要施行 的灾祸降与他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, '我何时 论 到 一邦 或 一国说,要建立、栽植; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, '他们若行 我眼中 看为恶的事,不 听从 我的话,我就必后悔, 不将我所 说的 福气 赐 给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, '现在 你要 对 犹大 人 和 耶路撒冷 的居民 说:『耶和华 如此 说: 我 造出 灾祸 攻击你们,定 意 刑罚你们。你们各人 当 回头 离开 所行的恶 道,改正 你们的行动 作为。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, '「他们却说:『这是枉然。 我们要照 自己的计谋 去行。』各人 随自己顽梗 的恶 心 做事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, '所以,耶和华 如此 说:你们且 往各国 访问,有谁 听见 这样的事?以色列民(原文是处女)行了 一件极 可憎恶的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, '黎巴嫩 的雪 从田野 的磐石 上岂能断绝呢?从远处 流 下的凉 水 岂能 干涸呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, '我的百姓 竟 忘记我,向假神 烧香,使他们在所行的路上,在古 道 上绊跌,使他们行 没有 修筑的 斜路, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, '以致 他们的地 令人惊骇,常常 嗤笑;凡 经过 这地 的必惊骇 摇 头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, '我必在仇敌 面前 分散他们,好像用东 风吹散一样。遭难 的日子,我必以背 向他们,不 以面向他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, '他们就说:「来吧!我们可以设 计 谋害 耶利米;因为 我们有祭司 讲律法,智慧人 设谋略,先知 说预言,都不能 断绝。来吧!我们可以用舌头 击打他,不要 理会 他的一切 话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, '耶和华啊,求你理会 我,且听 那些与我争竞之人 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, '岂可以恶 报 善呢?他们竟 挖 坑 要害我的性命!求你记念 我怎样站 在你面前 为他们 代求,要使 你的忿怒 向他们 转消。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, '故此,愿 你将 他们的儿女 交 与饥荒 和 刀剑;愿  他们的妻 无子,且作寡妇;又愿  他们的男人 被死亡 所灭,他们的少年人 在阵上 被刀 击杀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, ' 你使敌军 忽然 临 到他们的时候,愿 人听见 哀声 从他们的屋内发出;因 他们挖 坑 要捉拿我,暗设 网罗 要绊我的脚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, '耶和华啊,他们要杀 我 的那 一切 计谋,你 都知道。不要 赦免 他们的罪孽,也不要 从你面前 涂抹 他们的罪恶,要叫他们 在你面前 跌倒;愿 你发怒 的时候 罚办 他们。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, '耶和华 如此 说:「你去 买  窑匠的 瓦 瓶,又带百姓 中的长老 和祭司 中的长老, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, '出去 到 欣嫩 子 谷、哈珥西(就是瓦片的意思)的 门 口 那里,宣告 我所 吩咐 你 的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, '说:『犹大 君王 和耶路撒冷 的居民哪,当听 耶和华 的话。万军 之耶和华─以色列的 神 如此 说: 我必使灾祸 临 到 这 地方, 凡 听见 的人都必耳 鸣; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, '因为 他们 和他们列祖,并犹大 君王 离弃我,将 这 地方 看为平常,在这里 向素 不 认识 的别 神 烧香,又使 这 地方 满了 无辜人 的血, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, '又建筑 巴力 的邱坛,好在火中 焚烧 自己的儿子,作为燔祭 献给巴力。这不是 我所 吩咐的,不是 我所提说的,也不是 我心 所起的意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, '耶和华 说: 因此,日子 将到,这 地方 不 再 称为 陀斐特 和欣嫩 子 谷,反倒 称为杀戮 谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, '我必在这 地方 使 犹大 和耶路撒冷 的计谋 落空,也必使他们在仇敌 面前 倒 于 刀下,并寻索 其命 的人手下。 他们的尸首,我必给 空中 的飞鸟 和地上 的野兽 作食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, '我必使 这 城 令人惊骇 嗤笑;凡 经过的人,必因这城所遭的 灾 惊骇 嗤笑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, '我必使他们在围困 窘迫之中,就是 仇敌 和寻索 其命 的人窘迫 他们的时候,各人 吃 自己儿 女 的肉 和 朋友 的肉。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, '「你要在同 去 的人 眼前 打碎 那瓶, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, '对他们 说:『万军 之耶和华 如此 说:我要照样 打碎 这 民 和 这 城,正如 人打碎 窑匠的 瓦器,以致 不能 再 囫囵。并且人要在陀斐特 葬埋尸首,甚至无 处 可葬。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, '耶和华 说:我必向这 地方 和其中的居民 如此 行,使 这 城 与陀斐特一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, '耶路撒冷 的房屋 和犹大 君王 的宫殿 是已经 被玷污的,就是 他们在 其上 向天上 的万 象 烧香、向别 神 浇 奠祭 的宫殿房屋,都 必与陀斐特一样。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, '耶利米 从陀斐特─就是 耶和华 差他 去说预言 的地方─回来,站 在耶和华 殿 的院中,对 众 人 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, '「万军 之耶和华─以色列的 神 如此 说: 我必使 我所 说的 一切 灾祸 临 到 这 城 和 属城的一切 城邑,因为 他们硬著 颈项 不 听 我的话。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, '祭司 音麦 的儿子 巴施户珥 作 耶和华 殿 的总 管,听见 耶利米 预言 这些 事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, '他 就打 先知 耶利米,用 耶和华 殿里 便雅悯 高 门内 的 枷,将他 枷在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, ' 次日,巴施户珥 将 耶利米 开  枷 释放。于 是耶利米 对他 说:「耶和华 不是 叫 你的名 为巴施户珥,乃是叫你玛歌珥‧米撒毕(就是四面 惊吓的意思), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, '因 耶和华 如此 说:『 我必使你 自 觉惊吓,你也必使众 朋友惊吓;他们必倒 在仇敌 的刀下,你也必亲眼 看见;我必将 犹大人 全 交 在巴比伦 王 的手中,他要将他们掳 到巴比伦去,也要用刀 将他们杀戮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, '并且我要将 这 城 中的一切 货财 和 劳碌得来的,并 一切 珍宝,以及 犹大 君王 所有的 宝物,都交 在他们仇敌 的手中;仇敌要当作 掠物 带到 巴比伦去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, '你 这巴施户珥 和一切 住 在你家 中的人都必被掳 去;你 和你的众 朋友,就是 你向他们 说假 预言的,都必到 巴比伦去,要死 在那里,葬 在那里。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, '耶和华啊,你曾劝导我,我也听了你的劝导。你比我有力量,且胜了我。我终 日 成为 笑话,人人都 戏弄 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, ' 我每逢 讲论的时候,就发出哀声,我喊叫说:有强暴 和毁灭!因为 耶和华 的话 终 日 成了 我的 凌辱、讥刺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, '我若说:我不 再提耶和华,也不 再 奉他的名 讲论,我便心里 觉得似乎有 烧著 的火 闭塞 在我骨中,我就含忍 不住,不 能自禁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, ' 我听见了 许多 人的谗谤,四围 都是惊吓;就是我知己的 朋友 也都 窥探我,愿 我跌倒,说:告他吧,我们也要告他!或者 他被引诱,我们就能胜 他,在他身上 报 仇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, '然而,耶和华 与我同在,好像甚可怕的 勇士。因 此,逼迫我的 必都绊跌,不能 得胜;他们必大大 蒙羞,就是受永 不 忘记 的羞辱,因为 他们行事没有 智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, '试验 义人、察看 人肺腑 心肠 的万军 之耶和华啊,求你容我见 你在他们身上 报仇,因 我将 我的案件 向你 禀明了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, '你们要向耶和华 唱歌;赞美 耶和华!因 他救了 穷人 的性命 脱离恶人 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, '愿 我生 的那 日 受咒诅;愿 我母亲 产我 的那 日 不 蒙 福! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, '给 我父亲 报信 说「你 得了 儿子」,使 我父亲甚欢喜 的,愿 那人 受咒诅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, '愿  那 人 像耶和华 所 倾覆 复 而不 后悔 的城邑;愿 他早晨 听见 哀声,晌午 听见呐喊; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, '因 他在我未出胎 的时候不 杀我,使我母亲 成了 我的坟墓,胎 就时常 重大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, '我为何 出 胎 见 劳碌 愁苦,使我的年日 因羞愧 消灭呢?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, ' 耶和华 的话 临 到 耶利米。那时,西底家 王 打发 玛基雅 的儿子 巴施户珥 和 玛西雅 的儿子 祭司 西番雅 去见耶利米,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, '「请你 为我们 求问 耶和华;因为 巴比伦 王 尼布甲尼撒 来攻击 我们,或者 耶和华 照他一切 奇妙的作为 待 我们,使巴比伦王离开 我们 上去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, '耶利米 对他们 说:「你们当对 西底家 这样 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, '『耶和华─以色列的 神 如此 说: 我要使 你们手中 的兵 器,就是 你们 在城 外 与 巴比伦 王 和 围困 你们 的迦勒底人 打仗 的兵器 翻转过来,又要使这些 都聚集 在 这 城 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, '并且我 要在怒气、忿怒,和大 恼恨中,用伸出来 的手,并大能 的膀臂,亲自攻击 你们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, '又要击打 这 城 的居民,连 人 带 牲畜 都必遭遇大 瘟疫 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, '以后 我要将 犹大 王 西底家 和 他的臣仆 百姓,就是在城内,从 瘟疫、 刀剑、 饥荒中 剩下的人,都交 在巴比伦 王 尼布甲尼撒 的手中 和他们仇敌,并寻索 其命 的人手中。巴比伦王必用 刀 击杀他们,不 顾惜,不 可怜,不 怜悯。这是耶和华 说的。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, '「你要对 这 百姓 说:『耶和华 如此 说:看哪,我将 生命 的路 和 死亡 的路 摆 在你们面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, '住 在这 城里 的必遭刀剑、饥荒、瘟疫 而死;但出去 归降 围困 你们 迦勒底人 的必得存活,要以自己的命 为 掠物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, '耶和华 说: 我向这 城 变 脸,降祸 不 降福;这城必交 在巴比伦 王 的手中,他必用火 焚烧。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, '「至于 犹大 王 的家,你们当听 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, '大卫 家啊,耶和华 如此 说:你们每早晨 要施行 公平,拯救 被抢夺 的脱离欺压 人的手,恐怕 我的忿怒 因 你们的恶 行 发作,如火 著起,甚至无人 能以熄灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, '耶和华 说:住山谷 和平原 磐石 上的居民,你们说:谁 能下来 攻击我们?谁 能进 入我们的住处呢?看哪,我 与你们为敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, '耶和华 又说:我必按你们做事 的结果 刑罚 你们;我也必使火 在耶路撒冷的林中 著起,将她四围 所有的 尽行烧灭。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, '耶和华 如此 说:「你下到 犹大 王 的宫中,在那里 说 这 话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, '说:『坐 大卫 宝座 的犹大 王啊,你 和你的臣仆,并进入 城门 的百姓,都当听 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, '耶和华 如此 说:你们要施行 公平 和公义,拯救 被抢夺 的脱离欺压 人的手,不可 亏负 寄居的 和孤儿 寡妇,不可 以强暴待他们,在这 地方 也不可 流 无辜人 的血。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, ' 你们若 认真 行 这 事,就必有坐 大卫 宝座 的君王 和他的臣仆 百姓,或坐 车 或骑马,从这 城 的各门 进入。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, '你们若 不 听 这些 话,耶和华 说:我指著自己 起誓, 这 城 必变 为荒场。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, ' 耶和华 论到 犹大 王 的家 如此 说:我 看你 如基列,如黎巴嫩 顶;然而,我必使你 变为旷野,为无人 居住 的城邑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, '我要预备 行毁灭的人,各 拿器械 攻击你;他们要砍下 你佳美 的香柏树,扔 在 火中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, '「许多 国 的民要经过 这 城,各人 对 邻舍 说:『耶和华 为 何 向这 大 城 如此 行呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, '他们必回答说:『是 因 离弃了 耶和华─他们 神 的约,事奉 敬拜 别 神。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, '不要 为死人 哭号;不要 为他 悲伤,却要为离家出外 的人大大 哭号;因为 他不得 再 回来,也不得再见 他的本 国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, '因为 耶和华 论到 从 这 地方 出去 的犹大 王 约西亚 的儿子 沙龙(在列王下二十三章三十节名约哈斯),就是 接续 他父亲 约西亚 作王的,这样 说:「他必不得 再 回到 这里来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, '却要 死在 被掳去 的地方,必不得 再 见 这 地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, '那行不 义 盖 房、行不 公 造楼、白白 使用人 的手工 不 给 工价 的有祸了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, '他说:我要为自己 盖 广大 的房、宽敞 的楼,为自己 开  窗户。这楼房的护墙板 是香柏木的,楼房是丹色 油漆的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, '难道你 作王 是在乎 造香柏木 楼房争胜吗?你的父亲 岂不是 也吃 也喝、也施行 公平 和公义吗?那时 他 得了福乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, '他为困苦 和穷乏人 伸冤,那时 就得了福乐。认识 我 不 在乎此吗?这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, '惟有 你的眼 和你的心 专 顾 贪婪, 流 无辜人 的血,行 欺压 和 强暴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, '所以,耶和华 论到 犹大 王 约西亚 的儿子 约雅敬 如此 说:人必不 为他 举哀说:哀哉!我的哥哥;或说:哀哉!我的姊姊;也不 为他 举哀说:哀哉!我的主;或说:哀哉!我主的荣华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, '他被埋葬,好像埋 驴一样,要拉出去 扔 在耶路撒冷 的城门 之外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, '你要上 黎巴嫩 哀号,在巴珊 扬 声,从亚巴琳 哀号,因为 你所亲爱 的都 毁灭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, '你兴盛的时候,我对你 说话;你却说:我不 听。你自幼年 以来总是这 样, 不 听从 我的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, ' 你的牧人 要被风 吞吃,你所亲爱 的必被掳 去;那时 你必因你一切的 恶 抱愧 蒙羞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, '你这住 黎巴嫩、在香柏树上 搭窝的,有痛苦 临到 你,好像疼痛 临到产难的妇人,那时你何等 可怜! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, '耶和华 说:「犹大 王 约雅敬 的儿子 哥尼雅(又名耶哥尼雅;下同),虽 是 我右 手 上带印的戒指,我 凭我的永生起誓,也必 将你从其上 摘下来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, '并且我必将你交 给寻索 你命的人 和你 所 惧怕 的人 手中,就是巴比伦 王 尼布甲尼撒 和迦勒底人 的手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, '我也必将你 和 生你 的 母亲 赶 到 别 国, 并不是 你们生 的地方;你们必死 在那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, ' 但心中 甚想 归 回 之 地,必不得 归回。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, '哥尼雅 这 人 是被轻看、破坏 的器皿吗?是 无人 喜爱的 器皿吗?他 和他的后裔 为何 被赶 到 不 认识 之 地呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, '地啊,地啊,地啊,当听 耶和华 的话! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, '耶和华 如此 说:要写明 这 人 算为无子, 是平生 不得 亨通的;因为 他后裔中 再无 一人 得亨通,能坐 在 大卫 的宝座 上治理 犹大。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, '耶和华 说:「那些残害、赶散 我草场 之羊 的牧人 有祸了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, ' 耶和华─以色列的 神 斥责 那些牧养 他百姓 的牧人,如此 说:「你们 赶 散 我的羊群,并没有 看顾 他们; 我必讨 你们 这 行 恶的罪。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, '我 要将 我羊群 中所余 馀剩的,从 我赶 他们到的 各 国 内招聚出来,领 他们 归回 本圈;他们也必生养 众多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, '我必设立 照管他们 的牧人,牧养他们。他们不 再 惧怕,不 再惊惶,也不 缺少一个;这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, '耶和华 说:「 日子 将到,我要给大卫 兴起 一个公义 的苗裔;他 必掌王权,行事有智慧,在地上 施行 公平 和公义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, '在他的日子,犹大 必得救,以色列 也安然 居住。他的 名 必 称为『耶和华─我们的义』。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, ' 耶和华 说:「 日子 将到,人必不 再 指著那 领 以色列 人 从埃及 地 上来永生 的耶和华 起誓, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, '却 要 指著那 领 以色列 家 的后裔 从 北方 和 赶他们到 的 各 国中 上来、永生 的耶和华起誓。他们必住 在 本地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, '论到那些先知,我心 在我里面 忧伤,我骨头 都 发颤;因 耶和华 和 他的圣 言,我 像醉酒 的人,像被酒 所胜 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, ' 地 满了 行淫的人! 因 妄自赌咒,地 就悲哀;旷野 的草场 都枯干了。他们所行的道 乃是 恶的;他们的勇力 使得不 正。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, ' 连 先知 带 祭司 都是亵渎的,就是 在我殿中 我也看见 他们的恶。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, '因此,他们的道路 必 像黑暗中 的滑地,他们必被追赶,在这路中 仆倒;因为 当追讨 之年,我必使灾祸 临 到他们。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, '我在撒马利亚 的先知中 曾见 愚妄;他们藉 借巴力 说预言,使 我的百姓 以色列 走错了路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, '我在耶路撒冷 的先知中 曾见 可憎恶的事;他们行奸淫,做事 虚妄,又坚固 恶人 的手,甚至无 人 回头 离开 他的恶。他们 在我面前 都 像所多玛;耶路撒冷的居民 都像蛾摩拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, '所以 万军 之耶和华 论到 先知 如此 说: 我必将茵𫈟 给他们 吃,又将苦胆 水 给他们喝;因为 亵渎的事 出 于  耶路撒冷 的先知,流行遍 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, '万军 之耶和华 如此 说:「这些先知 向你们 说预言,你们不要 听 他们的话。他们 以虚空 教训你们,所说 的异象 是出于 自己的心,不是 出于 耶和华 的口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, '他们常 对藐视我的人 说:『耶和华 说:你们 必 享平安』;又对一切 按自己顽梗 之心 而行的人 说:『必没有 灾祸 临 到你们。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, '有 谁 站 在耶和华 的会中 得以听见 并会悟 他的话呢?有谁 留心 听 他的话呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, '看哪!耶和华 的忿怒 好像暴风,已经发出;是暴烈 的旋风,必转 到 恶人 的头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, '耶和华 的怒气 必不 转消,直到 他心 中所拟定的 成就了。末后 的日子 你们要全然 明白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, '我没有 打发 那些 先知,他们 竟自奔跑;我没有 对他们 说话,他们 竟自预言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, '他们若是 站 在我的会中,就必使 我的百姓 听 我的话,又使他们回头 离开 恶 道 和他们所行 的恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, '耶和华 说:「我 岂为近处的 神呢?不 也为远处的 神吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, '耶和华 说:「人 岂 能在隐密处 藏身,使我 看 不见他呢?」耶和华 说:「我 岂不 充满 天 地吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, '我已听见 那些 先知 所 说的,就是托 讬我名 说的假 预言,他们说:『我做了梦!我做了梦!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, '说假 预言 的先知,就是预言本心 诡诈 的先知,他们这样存 心 要到 几时呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, '他们各人 将所 做的梦 对邻舍 述说,想要 使 我的百姓 忘记 我的名,正如 他们列祖 因巴力 忘记 我的名一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, '得 梦 的 先知 可以述说 那梦;得 我话 的人 可以诚实 讲说 我的话。糠秕 怎能 与 麦子比较呢?这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, '耶和华 说:「我的话 岂不 像 火,又像能打碎 磐石 的大锤吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, '耶和华 说:「那些先知 各 从 邻舍 偷窃 我的言语,因此 我必 与他们反对。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, '耶和华 说:「那些先知 用 舌头,说 是耶和华说的;我必 与他们反对。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, '耶和华 说:「那些以幻 梦 为预言,又述说这梦,以谎言 和矜夸 使 我百姓 走错了路的,我必 与他们反对。我 没有 打发他们,也没有 吩咐他们。他们与这 百姓 毫 无 益处。这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, '「无论 是百姓,是 先知,是 祭司,问你 说:『耶和华 有什么 默示呢?』你就对他们 说:『 什么 默示啊?耶和华 说:我要撇弃 你们。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, '无论是先知,是祭司,是百姓, 说『耶和华 的默示』,我必刑罚 那 人 和 他的家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, '你们各人 要对 邻舍,各人 要对 弟兄 如此 说:『耶和华 回答 什么?』『耶和华 说了 什么呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, '『耶和华 的默示』你们不可 再 提, 各人 所说的话 必作 自己的重担(重担和默示原文同),因为你们谬用 永生 神、万军 之耶和华─我们 神 的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, '你们要对 先知 如此 说:『耶和华 回答 你什么?』『耶和华 说了 什么呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, '你们若 说『耶和华 的默示』,耶和华 就 如此 说:『因 你们说「耶和华 的默示」这 句话,我也打发 人到你们那里去,告诉 你们不可 说「耶和华 的默示」。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, '所以 我必 全然 忘记 你们,将你们 和 我所 赐 给你们 并你们列祖 的城 撇弃了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, '又必使 永远 的凌辱 和长久 的羞耻 临到你们,是 不能 忘记的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, '巴比伦 王 尼布甲尼撒 将 犹大 王 约雅敬 的儿子 耶哥尼雅 和 犹大 的首领,并 工匠、 铁匠 从耶路撒冷 掳去,带到 巴比伦。这事以后,耶和华 指给我看, 有两 筐 无花果 放 在耶和华 的殿 前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, '一 筐 是极 好 的无花果,好像是初熟的;一 筐 是极 坏 的无花果, 坏得 不可 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, '于 是耶和华 问我 说:「耶利米 你 看见 什么?」我说:「我看见无花果,好 的 极 好,坏 的极 坏, 坏得 不可 吃。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, '「耶和华─以色列的 神 如此 说: 被掳去 的犹大人,就是 我打发 离开  这 地 到迦勒底人 之地去的,我必看顾 他们如 这 好 无花果,使他们得好处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, '我要眷顾 他们,使他们得好处,领他们归回 这 地。我也要建立他们,必不 拆毁;栽植他们,并不 拔出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, '我要赐 他们 认识 我 的心,知道 我是 耶和华。他们要作 我的 子民,我 要作 他们的 神,因为 他们要一 心 归 向我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, ' 耶和华 如此 说:「我必 将 犹大 王 西底家 和 他的首领,以及 剩 在这 地 耶路撒冷 的余 馀民,并住 在埃及 地 的犹大人都交出来,好像那极坏、 坏得 不可 吃 的无花果。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, '我必使他们交出来,在天下 万 国 中抛来抛去,遭遇灾祸; 在我赶逐他们 到的 各 处 成为凌辱、笑谈、讥刺、咒诅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, '我必使 刀剑、 饥荒、 瘟疫 临到 他们,直到 他们从 我所 赐 给他们 和他们列祖 之地 灭绝。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, '犹大 王 约西亚 的儿子 约雅敬 第四 年,就是 巴比伦 王 尼布甲尼撒的 元 年,耶和华论 犹大 众 民 的话 临 到 耶利米。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, '先知 耶利米 就将这话 对 犹大 众 人 和 耶路撒冷 的一切 居民 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, '「从 犹大 王 亚们 的儿子 约西亚 十 三 年 直到 今 日,这 二十 三 年之内,常有耶和华 的话 临 到我;我也对你们 传说,就是从早起来 传说,只是你们没有 听从。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, '耶和华 也从早起来,差遣他的 仆人 众先知 到你们这里来(只是你们没有 听从,也没有 侧 耳 而听), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, '说:『你们各人 当 回头,离开 恶 道 和所作 的恶,便可居住 耶和华 古时 所 赐 给你们 和你们列祖 之地,直到 永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, '不可 随 从 别 神 事奉 敬拜, 以你们手 所做的 惹我 发怒;这样,我就不 加害 与你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, '然而你们没有 听从 我,竟以 手 所做的 惹我发怒,陷害 自己。这是耶和华 说的。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, '所以 万军 之耶和华 如此 说:「因 为 你们没有 听从 我的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, '我必 召 北方 的众 族 和 我仆人 巴比伦 王 尼布甲尼撒 来 攻击 这 地 和 这地的居民,并 四围 一切的 国民。我要将他们尽行灭绝,以致他们令人 惊骇、嗤笑,并且永久 荒凉。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, '我又要使欢喜 和快乐 的声音,新郎 和新妇 的声音,推磨 的声音 和灯 的亮光,从他们 中间止息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, '这 全 地 必然 荒凉,令人惊骇。这些 国民 要服事 巴比伦 王 七十 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, '七十 年 满了 以后,我必刑罚 巴比伦 王 和 那 国民,并 迦勒底人 之地,因 他们的罪孽 使 那地 永远 荒凉。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, '我也必使 我向 那 地 所 说的 话,就是 记 在这 书上的话,是 耶利米 向 这些 国民 说的预言,都临 到那地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, '因为 有多 国 和大 君王 必 使迦勒底人 作奴仆;我也必照他们的行为,按他们手 所做的 报应 他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, ' 耶和华─以色列的 神 对我 如此 说:「你从我手中 接 这 杯 忿怒 的酒,使 我 所 差遣 你 去 的各 国的民 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, '他们喝了 就要东倒西歪,并要发狂,因 我 使刀剑 临到 他们中间。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, '我就从耶和华 的手中 接了 这 杯,给 耶和华 所 差遣我 去的各 国的民 喝, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, '就是 耶路撒冷 和 犹大 的城邑,并 耶路撒冷的君王 与 首领,使 这城邑 荒凉,令人惊骇、嗤笑、咒诅,正如今 日一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, '又有 埃及 王 法老 和 他的臣仆、 首领,以及 他的众 民, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, '并 杂族 的人民和 乌斯 地 的诸 王,与 非利士 地 的诸 王( 亚实基伦、 迦萨、 以革伦,以及 亚实突 剩下的人); ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, ' 以东、 摩押、 亚扪 人、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, ' 泰尔 的诸 王、 西顿 的诸 王、 海 岛 的诸 王、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, ' 底但、 提玛、 布斯,和 一切 剃 周围头发的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, ' 阿拉伯 的诸 王、 住 旷野 杂族 人民的诸 王、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, ' 心利 的诸 王、 以拦 的诸 王、 米底亚 的诸 王、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, ' 北方 远 近 的诸 王,以及 天下 地 上的万 国喝了,以后 示沙克(就是巴比伦)王 也要喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, '「你要对他们 说:『万军 之耶和华─以色列的 神 如此 说:你们要喝,且要喝醉,要呕吐,且要跌倒,不得 再起来,都因 我 使刀剑 临 到你们中间。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, '「 他们若 不肯 从你手 接 这杯 喝,你就要对他们 说:『万军 之耶和华 如此 说:你们一定 要喝! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, ' 我 既 从称 为 我名 下的 城 起首 施行灾祸,你们 能尽 免刑罚吗?你们必不能 免,因为 我 要命 刀剑 临到 地上 一切的 居民。这是万军 之耶和华 说的。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, '「所以你 要向他们 预言 这 一切的 话,攻击他们,说:耶和华 必从高天 吼叫,从圣 所 发 声,向 自己的羊群 大声 吼叫;他要向 地上 一切的 居民 呐喊,像踹葡萄的一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, '必有响声 达 到 地 极,因为 耶和华 与列国 相争;凡 有血气的,他必 审问;至于 恶人,他必交 给刀剑。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, '万军 之耶和华 如此 说:看哪,必有灾祸 从这国 发 到 那国,并有大 暴风 从地 极 刮起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, '「到那 日,从地 这边 直到 地 那边 都有 耶和华 所杀戮的。必无人 哀哭,不得 收殓,不得 葬埋,必在 地 上 成为 粪土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, '牧人哪,你们当哀号,呼喊;群众 的头目啊,你们要滚在灰中;因为 你们被杀戮 分散 的日子 足足来到。你们要跌碎,好像美 器打碎一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, '牧人 无 路 逃跑;群众 的头目 也无法逃脱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, '听啊,有牧人 呼喊,有群众 头目 哀号 的声音,因为 耶和华 使 他们的草场 变为荒场。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, ' 耶和华 发出猛烈 的怒气,平安 的羊圈 就都寂静无声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, '他离了 隐密处 像狮子一样, 他们的地,因 刀剑凶猛 的欺压,又因 他猛烈 的怒气 都成为 可惊骇的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, '犹大 王 约西亚 的儿子 约雅敬 登基 的时候,有 这 话 从 耶和华 临到耶利米说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, '「耶和华 如此 说:你站在 耶和华 殿 的院内, 对 犹大 众 城邑的人,就是到 耶和华 殿 来礼拜的,说 我所 吩咐你 的 一切 话,一字 不可 删减。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, '或者 他们肯听从,各人 回头 离开 恶 道,使我后悔 不将 我 因 他们所行 的恶, 想要 施行 的灾祸降 与他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, '你要对他们 说,耶和华 如此 说:『你们若 不 听从 我,不遵行 我设立 在你们面前 的律法, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, '不听 我 从早起来 差遣 到 你们那里 去我仆人 众先知的 话(你们还是没有 听从), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, '我就必使 这 殿 如示罗,使 这 城 为地上 万 国 所咒诅的。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, ' 耶利米 在耶和华 殿中 说的 这些 话,祭司、先知 与众 民 都听见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, ' 耶利米 说 完了 耶和华 所 吩咐 他对 众 人 说 的一切话,祭司、先知 与众 民 都来抓住 他,说:「你必 要死! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, '你为何 托 讬耶和华 的名 预言,说 这 殿 必 如示罗,这 城 必变为荒场 无人 居住呢?」于 是众 民 都在耶和华 的殿中 聚集 到 耶利米那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, '犹大 的首领 听见 这 事,就从王 宫 上 到耶和华 的殿,坐 在耶和华 殿的新 门 口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, ' 祭司、先知 对 首领 和 众 民 说:「这 人 是该 死的;因为 他说预言 攻击 这 城,正如 你们亲耳 所听见的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, ' 耶利米 就对 众 首领 和 众 民 说:「耶和华 差遣我 预言,攻击 这 殿 和 这 城,说 你们所 听见 的这一切 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, '现在 要改正 你们的行动 作为,听从 耶和华─你们 神 的话,他 就必后悔,不将 所 说 的灾祸 降与你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, '至于 我,我 在你们手中,你们眼看 何为善,何为正,就那样待 我吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, '但 你们要确实地 知道, 若 把我 治死, 就 使无辜人 的血 归 到你们 和 这 城,并 其中的居民了;因为 耶和华 实在 差遣我 到你们这里来,将 这 一切 话 传与 你们耳中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, '首领 和众 民 就对 祭司、 先知 说:「这 人 是不 该 死的,因为 他是奉耶和华─我们 神 的名 向我们 说话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, '国中 的长老 就有几个人 起来, 对 聚会 的众 民 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, '「当犹大 王 希西家 的日子,有 摩利沙人 弥迦 对 犹大 众 人 预言 说:万军 之耶和华 如此 说:锡安 必被耕种 像一块田;耶路撒冷 必变为 乱堆;这殿 的山 必像丛林 的高处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, '犹大 王 希西家 和犹大 众人 岂是把他 治死呢?希西家岂不是 敬畏 耶和华、恳求 他的恩吗?耶和华 就后悔,不把 自己所 说 的灾祸 降与他们。若治死这人,我们 就作了 大 恶, 自害己命。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, '(又 有 一个人 奉耶和华 的名 说预言,是基列‧耶琳人 示玛雅 的儿子 乌利亚,他照耶利米 的一切 话 说预言,攻击 这 城 和 这 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, '约雅敬 王 和他众 勇士、众 首领 听见了 乌利亚的话,王 就想要 把他治死。乌利 亚听见 就惧怕,逃 往埃及 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, '约雅敬 王 便打发 亚革波 的儿子 以利拿单,带 领几个人 往 埃及去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, '他们就从埃及 将 乌利亚 带出来,送 到 约雅敬 王那里;王用刀 杀了他,把 他的尸首 抛 在 平民 的坟地中。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, '然而,沙番 的儿子 亚希甘保护 耶利米,不 交 在百姓 的手中 治死他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, '犹大 王 约西亚 的儿子 约雅敬(约雅敬是西底家的别名,看第三节)登基 的时候,有 这 话 从 耶和华 临到 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, '「耶和华 对我 如此 说:你 做 绳索 与轭,加 在 自己的颈项上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, '藉 借那些来到 耶路撒冷 见 犹大 王 西底家 的使臣 之手,把绳索与轭送 到 以东 王、 摩押 王、 亚扪 王、 泰尔 王、 西顿 王那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, '且嘱咐使臣,传与 他们的主人 说,万军 之耶和华─以色列的 神 如此 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, '我 用大 能 和伸出来 的膀臂,创造 大地 和 地 上的 人民、 牲畜。我看 给谁 相宜,就把地给谁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, '现在 我 将 这些 地 都 交 给我仆人 巴比伦 王 尼布甲尼撒 的手,我也 将 田野 的走兽 给 他 使用。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, '列 国 都必服事 他 和 他的儿 孙,直到 他 本国 遭报的日期 来到。那时,多 国 和大 君王 要使他 作他们的奴仆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, '「无论 哪一邦 哪一国, 不 肯服事 这 巴比伦 王 尼布甲尼撒, 也不 把 颈项 放 在巴比伦 王 的轭下,我必用刀剑、饥荒、瘟疫 刑罚 那 邦,直到 我藉 借巴比伦王的手 将他们 毁灭。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, '至于 你们,不可 听从 你们的先知 和 占卜的、 圆梦的、 观兆的,以及 行邪术的; 他们 告诉 你们 说:『你们不致 服事 巴比伦 王。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, ' 他们 向你们 说假 预言,要叫 你们 迁移,远离 本地,以致我将你们 赶出去,使你们灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, '但哪一邦 肯把 颈项 放 在巴比伦 王 的轭下 服事他,我必使那邦仍在 本地 存留,得以耕种 居住。这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, '我就 照这 一切 的话 对 犹大 王 西底家 说:「要把 你们的颈项 放 在巴比伦 王 的轭下,服事 他 和他的百姓,便得存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, '你 和你的百姓 为何 要因刀剑、饥荒、瘟疫 死亡,正如 耶和华 论 到 不 服事 巴比伦 王 的那 国说的话呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, '不可 听 那些先知 对你们 所说 的话;他们说:『你们不致 服事 巴比伦 王』,其实 他们 向你们 说假 预言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, '耶和华 说:『 我并没有 打发他们,他们 却托 讬我的名 说假 预言,好使 我将你们 和向你们 说预言 的那些先知 赶出去, 一同灭亡。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, '我又对 祭司 和 这 众 民 说:「耶和华 如此 说:你们不可 听 那先知 对你们 所说 的预言。他们说:『 耶和华 殿 中的器皿 快要 从巴比伦 带回来』;其实 他们 向你们 说假 预言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, '不可 听从 他们,只管服事 巴比伦 王 便得存活。这 城 何致 变为 荒场呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, '他们 若 果是先知, 有 耶和华 的话 临到他们,让 他们祈求 万军 之耶和华,使那在耶和华 殿中 和犹大 王 宫内,并耶路撒冷 剩下 的器皿,不被 带到巴比伦 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, '(因为 万军 之耶和华 论 到 柱子、 铜海、 盆座,并 剩 在这 城里的 器皿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, '就是巴比伦 王 尼布甲尼撒 掳掠 犹大 王 约雅敬 的儿子 耶哥尼雅, 和 犹大、耶路撒冷 一切 贵胄 的时候所 没有 掠去的器皿。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, ' 论到 那在耶和华 殿 中和犹大 王 宫内,并耶路撒冷 剩下的器皿,万军 之耶和华─以色列的 神 如此 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, '必被带 到巴比伦 存在 那里,直到 我眷顾 以色列人 的日子。那时,我必将这器皿带回来,交 还 此 地。这是耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, '当 年,就是犹大 王 西底家 登基 第四 年 五 月, 基遍人 押朔 的儿子,先知 哈拿尼雅,在耶和华 的殿中 当著 祭司 和众 民 对我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, '「万军 之耶和华─以色列的 神 如此 说:我已经折断 巴比伦 王 的轭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, '二年 之内,我 要将 巴比伦 王 尼布甲尼撒 从 这 地 掠 到 巴比伦的器皿,就是 耶和华 殿 中的一切 器皿 都带回 此 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, '我 又要将 犹大 王 约雅敬 的儿子 耶哥尼雅 和 被掳 到巴比伦 去 的一切 犹大人 带 回 此 地,因为 我要折断 巴比伦 王 的轭。这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, '先知 耶利米 当著 祭司 和 站 在耶和华 殿里 的众 民 对 先知 哈拿尼雅 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, '「阿们!愿 耶和华 如此 行,愿 耶和华 成就 你所 预言 的话,将耶和华 殿 中的器皿 和一切 被掳 去的人从巴比伦 带 回 此 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, '然而 我 向你 和众 民 耳中 所 要说的 话,你应当 听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, '从 古以来, 在 你 我以前 的先知,向 多 国 和 大 邦 说预言,论到争战 、灾祸、瘟疫的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, '先知 预言 的平安,到 话语 成就的时候,人便知道 他 真是 耶和华 所 差来的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, '于 是,先知 哈拿尼雅 将 先知 耶利米 颈项 上 的轭 取下来,折断了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, '哈拿尼雅 又 当著 众 民 说:「耶和华 如此 说:二年 之内 我必照样 从列 国人 的颈项 上 折断 巴比伦 王 尼布甲尼撒 的轭。」于 是先知 耶利米 就走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, '先知 哈拿尼雅 把 先知 耶利米 颈项 上 的轭 折断 以后,耶和华 的话 临 到 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, '「你去 告诉 哈拿尼雅 说,耶和华 如此 说:你折断 木 轭,却换了 铁 轭! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, '因为 万军 之耶和华─以色列的 神 如此 说:我已将铁 轭 加 在 这些 国 的颈项上,使他们服事 巴比伦 王 尼布甲尼撒,他们总要服事他;我也 把 田野 的走兽 给了 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, '于 是先知 耶利米 对 先知 哈拿尼雅 说:「哈拿尼雅啊,你应当 听!耶和华 并没有 差遣你,你 竟使 这 百姓 倚靠 谎言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, '所以 耶和华 如此 说:看哪,我要叫你去 世,你 今年 必死,因为 你向 耶和华 说了 叛逆的话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, '这样,先知 哈拿尼雅 当 年 七 月 间就死了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, ' 先知 耶利米 从耶路撒冷 寄 信 与 被掳 的祭司、 先知,和 众 民,并 生存 的长老,就是 尼布甲尼撒 从耶路撒冷 掳 到巴比伦去的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, '(这在耶哥尼雅 王 和太后、太监,并犹大、耶路撒冷 的首领,以及工匠、铁匠 都离了 耶路撒冷 以后。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, '他藉 借沙番 的儿子 以利亚萨 和希勒家 的儿子 基玛利 的手寄去。 他们二人是犹大 王 西底家 打发 往 巴比伦 去见尼布甲尼撒 王的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, '信上说:「万军 之耶和华─以色列的 神 对一切 被掳去的(就是 我使他们从耶路撒冷 被掳 到巴比伦的人)如此 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, '你们要盖造 房屋,住在其中;栽种 田园,吃 其中所产的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, '娶 妻 生 儿 女,为你们的儿子 娶 妻,使 你们的女儿 嫁 人,生 儿 养女。在那里 生养众多,不致 减少。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, '我所 使你们 被掳 到的那城,你们要为那城 求 平安,为那城 祷告 耶和华;因为 那城得平安,你们 也随著得 平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, ' 万军 之耶和华─以色列的 神 如此 说:不要被 你们 中间 的先知 和占卜 的诱惑,也不要 听信 自己 所 做 的梦; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, '因为 他们 托 讬我的名 对你们 说假 预言,我并没有 差遣他们。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, '「 耶和华 如此 说: 为巴比伦 所定 的七十 年 满了以后,我要眷顾 你们,向你们 成就 我的恩 言,使你们 仍回 此 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, '耶和华 说: 我 知道 我 向你们 所 怀 的意念 是赐平安 的意念,不是 降灾祸的意念,要叫 你们 末后 有指望。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, '你们要呼求 我, 祷告 我,我就应允 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, '你们寻求 我,若 专 心 寻求我,就必寻见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, '耶和华 说:我必被你们 寻见,我也必使 你们被掳 的人归回,将你们 从各 国 中和我所 赶 你们 到的 各 处 招聚了来,又将你们 带 回 我使你们 被掳掠 离开  的地方。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, '「 你们说:『耶和华 在巴比伦 为我们 兴起 先知』; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, '所以 耶和华 论 到 坐 大卫 宝座 的王 和 住 在这 城里 的一切 百姓,就是 未曾 与你们 一同被掳 的弟兄, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, '万军 之耶和华 如此 说:『看哪,我必使 刀剑、 饥荒、 瘟疫 临到他们,使 他们 像极坏 的无花果, 坏得 不可 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, '我必用刀剑、饥荒、瘟疫 追 赶他们,使他们 在天下 万 国 抛来抛去,在我所 赶他们 到的各 国中,令人咒诅、惊骇、嗤笑、羞辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, '耶和华 说:这是因为 他们没有 听从 我的话,就是 我从早起来 差遣 我仆人 众先知 去说的,无奈他们不 听。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, '所以你们 一切 被掳去的,就是 我从耶路撒冷 打发 到巴比伦去的,当听 耶和华 的话。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, '万军 之耶和华─以色列的 神 论到 哥赖雅 的儿子 亚哈,并 玛西雅 的儿子 西底家,如此 说:「他们是托 讬我名 向你们 说假 预言的,我必 将他们 交 在巴比伦 王 尼布甲尼撒 的手中;他要在你们眼 前杀害他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, ' 住巴比伦 一切 被掳的 犹大人 必藉 借这二人 赌 咒 说:『愿 耶和华 使你 像巴比伦 王 在火中 烧 的 西底家 和亚哈一样。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, ' 这二人是在以色列中 行了 丑事,与 邻舍 的妻 行淫,又假 托 讬我名 说 我 未 曾吩咐他们 的话。知道 的是我,作见证的也是我。这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, '「论 到 尼希兰人 示玛雅,你当说, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, '万军 之耶和华─以色列的 神 如此 说: 你 曾用自己的名 寄 信 给 耶路撒冷 的众 民 和 祭司 玛西雅 的儿子 西番雅,并 众 祭司,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, '『耶和华 已经立你 西番雅为祭司,代替 祭司 耶何耶大,使耶和华 殿 中有 官长,好将一切 狂妄 自称为先知 的人 用 枷 枷住,用 锁锁住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, '现在 亚拿突人 耶利米 向你们 自称为先知,你们为何 没有 责备他呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, ' 因为 他寄信 给我们 在巴比伦 的人说:被掳的事必 长久。你们要盖造 房屋,住在其中;栽种 田园,吃 其中所产的。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, '祭司 西番雅 就把 这 信 念 给先知 耶利米 听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, '于 是耶和华 的话 临 到 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, '「你当寄信 给 一切 被掳的人 说:『耶和华 论到 尼希兰人 示玛雅 说:因为 示玛雅 向你们 说预言,我 并没有 差遣他,他使你们 倚靠 谎言; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, '所以 耶和华 如此 说:我必 刑罚 尼希兰人 示玛雅 和 他的后裔,他 必无 一人 存留 住 在这 民 中,也不 得见 我 所 要赐 与我百姓 的福乐,因为 他向 耶和华 说了 叛逆的话。这是耶和华 说的。』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, ' 耶和华 的 话 临 到 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, '「耶和华─以色列的 神 如此 说:你将 我对你 说过 的 一切 话 都写 在 书上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, '耶和华 说: 日子 将到,我要使 我的百姓 以色列 和犹大 被掳的人 归回;我也要使他们回 到 我所 赐 给他们列祖 之地,他们就得这地为业。这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, '以下是 耶和华 论到 以色列 和 犹大 所 说 的话: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, ' 耶和华 如此 说:我们听见 声音,是战 抖 惧怕 而不 平安的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, '你们且 访问 看看, 男人 有产难吗?我怎么 看见 人人 用手 掐 腰,像产难的妇人, 脸面 都变 青了呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, '哀哉! 那 日 为大,无 日可比;这是 雅各 遭难 的时候,但他必被救 出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, '万军 之耶和华 说:「到 那 日,我必从 你颈项 上折断 仇敌的轭,扭开  他的绳索;外邦人 不得 再 使你作他们 的奴仆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, '你们却要事奉 耶和华─你们的 神 和 我为你们 所 要兴起 的王 大卫。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, '故此,耶和华 说:我的仆人 雅各啊, 不要 惧怕;以色列啊,不要 惊惶;因 我要 从远方 拯救你,从被掳 到之地拯救 你的后裔;雅各 必回来 得享平靖 安逸,无人 使他害怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, '因 我 与你同在,要拯救你,也 要将所 赶散你 到的 那些 国 灭绝 净尽,却 不 将你 灭绝 净尽,倒要从宽 惩治你,万 不能 不罚你(不罚你:或译以你为无罪)。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, ' 耶和华 如此 说:你的损伤 无法医治;你的伤痕 极其重大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, '无人 为你分诉,使你的伤痕得以缠裹;你 没有 医治 的良药。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, '你所亲爱 的都 忘记你,不 来探问(或译:理会)你。我因 你的罪孽 甚大,罪恶 众多, 曾用仇敌 加的伤害 伤害你,用残忍者 的惩治惩治你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, '你为何 因 损伤 哀号呢?你的痛苦 无法医治。我因 你的罪孽 甚大,罪恶 众多,曾将这些 加 在你身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, '故此,凡 吞吃你的 必被吞吃; 你的敌人 个个 都被掳 去;掳掠你的 必成为 掳物; 抢夺你的 必成为 掠物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, '耶和华 说:我必 使你 痊愈,医好 你的伤痕,都因 人称 你 为被赶散的,说:这是 锡安,无人 来探问(或译:理会)的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, '耶和华 如此 说:我必 使雅各 被掳 去的帐棚 归回,也必顾惜 他的住处。城 必建造 在 原旧的山冈;宫殿 也照旧 有人居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, '必有感谢 和欢乐 的声音 从其中 发出,我要使他们增多,不致 减少;使他们尊荣,不致 卑微。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, '他们的儿女 要 如往日;他们的会众 坚立 在我面前;凡 欺压他们的,我必刑罚他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, '他们的君王 必是 属乎他们的;掌权的 必从他们中间 而出。我要使他就近我,他也要亲近 我;不然,谁 有 胆量 亲近 我呢?这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, '你们要作 我的 子民,我要 作 你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, '看哪,耶和华 的忿怒 好像暴风 已经发出;是扫灭 的暴风,必转 到 恶人 的头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, '耶和华 的烈怒 必不 转消, 直到 他心中 所拟定的 成就了;末后的 日子 你们要明白。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, '耶和华 说:「那 时,我必作 以色列 各 家的 神;他们 必作 我的 子民。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, '耶和华 如此 说:脱离 刀剑 的就是以色列 人。我使他享 安息的时候,他曾在旷野 蒙 恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, '古时(或译:从远方)耶和华向以色列(原文是我)显现,说:我以永远 的爱 爱你,因 此 我以慈爱 吸引你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, '以色列的民(原文是处女)哪,我要再 建立你,你就被建立;你必再 以击鼓 为美,与欢乐 的人一同跳舞 而出; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, '又 必在撒马利亚 的山上 栽种 葡萄园,栽种的人 要享用所结的果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, '日子 必 到,以法莲 山上 守望的人 必呼叫说:起来吧!我们可以上 锡安,到 耶和华─我们的 神那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, ' 耶和华 如此 说:你们当为雅各 欢乐 歌唱,因万国 中为首的 欢呼。当传扬 颂赞 说:耶和华啊,求你拯救 你的百姓 以色列 所 剩下的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, '我必 将他们 从北 方 领来,从地 极 招聚;同著 他们 来的有瞎子、瘸子、孕妇、产妇;他们必成为大 帮 回到 这里来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, '他们要哭泣 而来。我要照他们恳求 的引导他们,使他们在 河 水 旁走 正直 的路,在其上 不致 绊跌;因为 我是 以色列的 父,以法莲 是 我的长子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, '列国啊,要听 耶和华 的话,传扬 在远处 的海岛 说:赶散 以色列 的必招聚他,又看守他,好像牧人 看守羊群。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, '因 耶和华 救赎了 雅各,救赎他 脱离比他更强 之人的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, '他们要来到 锡安 的高处 歌唱,又流 归 耶和华 施恩之地,就是有 五谷、 新酒,和 油,并 羊羔、牛犊之地。他们的心 必 像浇灌的 园子;他们也不 再 有一点愁烦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, '那时,处女 必欢乐 跳舞;年少的、年老的,也必一同欢乐;因为我要使他们的悲哀 变为 欢喜,并要安慰他们,使他们的愁烦 转为快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, '我必以肥油 使祭司 的心 满足;我的百姓 也要因 我的恩惠 知足。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, '耶和华 如此 说:在拉玛 听见 号咷 痛 哭 的声音,是拉结 哭 她儿女,不肯 受安慰,因为 他们都不在了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, '耶和华 如此 说:你禁止 声音 不要哀哭,禁止眼目 不要流泪,因 你所做之工 必有 赏赐;他们必从敌 国 归回。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, '耶和华 说:你末后 必有 指望;你的儿女 必回 到自己的境界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, '我 听见 以法莲 为自己悲叹说:你责罚我,我便受责罚,像不 惯负轭 的牛犊一样。求你使我回转,我便回转,因为 你是 耶和华─我的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, ' 我回转 以后 就真正懊悔;受教 以后 就拍 腿叹息;我因 担当 幼年 的凌辱 就 抱愧 蒙羞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, '耶和华 说:以法莲 是我的 爱 子吗?是 可喜悦 的孩子吗? 我每逢 责备 他,仍 深 顾念他;所以 我的心肠 恋慕 他;我必要 怜悯他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, '以色列民(原文是处女)哪,你当为自己 设立 指路碑, 竖起 引路柱。你要留心 向大路,就是你所去 的原路;你当回转,回转 到 你这些 城邑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, '背道的民(原文是女子)哪,你反来覆 复去 要到 几时呢? 耶和华 在地上 造了 一件新事,就是女子 护卫 男子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, '万军 之耶和华─以色列的 神 如此 说:我使 被掳之人 归回的时候,他们在犹大 地 和其中的城邑 必再 这 样 说:「公义 的居所啊,圣 山哪,愿 耶和华 赐福给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, '犹大 和 属犹大城邑的人,农夫 和放 羊的人,要一同 住 在其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, '疲乏 的人, 我使他饱饫; 愁烦 的人,我使他知足。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, '先知说:「 我醒了,觉著 睡 得香甜!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, '耶和华 说:「 日子 将到,我要把人 的种 和牲畜 的种 播种 在 以色列 家 和 犹大 家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, '我先前怎样 留意 将他们 拔出、拆毁、毁坏、倾覆 复、苦害,也必 照样 留意 将他们 建立、栽植。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, '当那些 日子,人不 再 说:父亲 吃了 酸葡萄,儿子 的牙 酸倒了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, '但 各人 必因自己的罪 死亡;凡 吃 酸葡萄的,自己的牙 必酸倒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, '耶和华 说:「 日子 将到,我要与 以色列 家 和 犹大 家 另立 新 约, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, '不 像我拉著 他们祖宗 的手,领他们出 埃及 地 的时候,与 他们所 立 的约。 我 虽作他们的 丈夫,他们 却背了 我的约。这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, '耶和华 说:「那些 日子 以后,我与 以色列 家 所 立 的约 乃是 这样:我要将 我的律法 放 在他们里面,写 在 他们心上。我要作 他们的 神,他们 要作 我的 子民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, '他们各人 不 再 教导 自己的邻舍 和 自己的弟兄 说:『你该认识 耶和华』,因为 他们从最小的 到 至大的 都 必认识 我。 我要赦免 他们的罪孽,不 再 记念 他们的罪恶。这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, '那使 太阳 白日 发光,使星 月 有定例,黑夜 发亮,又搅动 大海,使海中波浪 匉訇的,万军 之耶和华 是他的名。他 如此 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, '这些 定例 若 能在我面前 废掉,以色列 的后裔 也就 在我面前 断绝,永远 不再成 国。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, '耶和华 如此 说:若 能量度 上 天,寻察 下 地 的根基,我 就 因 以色列 后裔 一切 所 行 的弃绝 他们。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, '耶和华 说:「 日子 将到,这城 必为耶和华 建造,从哈楠业 楼 直到角 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, '准 绳 要往 外 量出,直到 迦立 山,又转到 歌亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, '抛尸 的全 谷 和倒灰之处,并一切 田地,直到 汲沦 溪,又直到 东方 马 门 的拐角,都要归耶和华 为圣,不 再拔出,不 再 倾覆 复,直到永远。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, '犹大 王 西底家 第十 年,就是 尼布甲尼撒 十 八 年, 耶和华 的 话 临 到 耶利米。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, '那时 巴比伦 王 的军队 围困 耶路撒冷,先知 耶利米 囚在 护卫兵 的院内, 在犹大 王 的宫中; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, '因为 犹大 王 西底家 已将他囚禁,说:「你 为什么 预言 说,耶和华 如此 说:『我必 将 这 城 交 在巴比伦 王 的手中,他必攻取这城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, '犹大 王 西底家 必不能 逃脱 迦勒底人 的手, 定要 交 在巴比伦 王 的手中,要口 对 口 彼此说话,眼 对 眼 彼此相看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, '巴比伦王必将 西底家 带到 巴比伦;西底家必住 在那里,直到 我眷顾 他的时候。你们虽 与 迦勒底人 争战 ,却不 顺利。这是耶和华 说的。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, '耶利米 说:「耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, '『 你叔叔 沙龙 的儿子 哈拿篾 必来 见你,说:我在亚拿突 的 那 块地,求你 买 来;因 你买  这地是合乎赎回 之理。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, '我叔叔 的儿子 哈拿篾 果然照耶和华 的话 来 到 护卫兵 的院内,对我 说:「我在 便雅悯 境内、亚拿突 的 那 块地,求你 买 来;因 你 买 来是合乎承受 之理,是你 当赎的。你为自己 买 来吧!」我─耶利米就知道 这是 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, '我便向 我叔叔 的儿子 哈拿篾 买 了 亚拿突 的那 块地,平了 十 七 舍客勒 银子 给他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, '我在契上 画 划押,将契封缄,又请 见证人来,并用天平 将银子 平给他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, '我便 将 照例 按规 所立的买  契,就是 封缄 的那一张和 敞著的那一张, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, ' 当著 我叔叔 的儿子 哈拿篾 和画 划押 作见证的人,并坐在 护卫兵 院内 的一切 犹大人 眼前,交 给 玛西雅 的孙子 尼利亚 的儿子 巴录。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, '当著他们众人眼前,我嘱咐 巴录 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, '「万军 之耶和华─以色列的 神 如此 说:要 将 这 封缄 的和 敞著 的两张 契 放 在瓦 器里,可以 存留 多 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, '因为 万军 之耶和华─以色列的 神 如此 说:将来在这 地 必有人再 买  房屋、田地,和葡萄园。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, '我将 买  契 交 给 尼利亚 的儿子 巴录 以后,便祷告 耶和华 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, '「 主 耶和华啊, 你 曾用大 能 和伸出来 的膀臂 创造 天 地,在你 没有 难成 的 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, '你施 慈爱 与千万人,又将父亲 的罪孽 报应 在 他后世 子孙 的怀中,是至大 全能的 神,万军 之耶和华 是你的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, '谋事 有大略,行事 有大能, 注目 观看 世人 一切的 举动,为要照各人所行 的和他做事 的结果 报应 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, ' 在埃及 地 显 神迹 奇事,直到 今 日 在以色列 和别人中间也是如此,使自己 得了 名声,正如今 日一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, '用神迹 奇事 和大能 的手,并伸出来 的膀臂 与大 可畏的事,领 你的百姓 以色列 出了埃及。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, '将 这 地 赐 给他们,就是 你向他们列祖 起誓 应许赐 给他们 流 奶 与蜜 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, '他们进入 这地 得了为业,却不 听从 你的话,也不 遵行 你的律法; 你一切 所 吩咐 他们 行的,他们一无 所行,因此你使这 一切的 灾祸 临到 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, '看哪,敌人已经来到,筑垒 要攻取 这城;城 也因 刀剑、饥荒、瘟疫 交 在攻 城 的迦勒底人 手中。你所 说 的话都成就了, 你也看见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, '主 耶和华啊,你 对我 说:要用银子 为自己 买  那块地,又请 见证人。其实这城 已交 在迦勒底人 的手中了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, '耶和华 的话 临 到 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, '「 我是 耶和华,是凡 有血气者的 神,岂有我 难成 的 事吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, ' 耶和华 如此 说:我必 将 这 城 交 付迦勒底人 的手 和巴比伦 王 尼布甲尼撒 的手,他必攻取这城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, '攻 城 的迦勒底人 必来 放 火 焚烧 这 城 和 其中的房屋。在 这 房屋上,人曾向巴力 烧香,向别 神 浇奠, 惹我发怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, ' 以色列 人 和犹大 人 自从幼年以来,专 行 我眼中 看为恶的事; 以色列 人 尽 以手 所做的 惹我 发怒。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, ' 这 城 自从 建造 的那 日 直到 今 日,常 惹 我的 怒气 和 忿怒,使我将这城从 我面前 除掉; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, '是因 以色列 人 和犹大 人 一切的 邪恶,就是 他们 和他们的君王、首领、祭司、先知,并犹大 的众人,以及耶路撒冷 的居民 所行的,惹我发怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, '他们 以背 向我,不 以面向我;我虽 从早起来 教训 他们,他们却不 听从,不受 教训, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, '竟把可憎之物 设立在 称 为 我名 下的殿中,污秽了这殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, '他们在 欣嫩 子 谷 建筑 巴力 的邱坛,好使 自己的儿 女 经 火归摩洛;他们行 这 可憎的事, 使 犹大 陷在罪里,这并不是 我所 吩咐的,也不是 我心 所起的意。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, '现在 论到 这 城,就是 你们 所说、已经因刀剑、饥荒、瘟疫 交 在巴比伦 王 手中的,耶和华─以色列的 神 如此 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, '「我在怒气、忿怒,和大 恼恨中,将以色列人 赶 到各国。日后我 必从 那里 将他们招聚出来,领他们回 到 此 地,使他们安然 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, '他们要作 我的 子民,我 要作 他们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, '我要使 他们 彼此同 心 同 道,好叫他们永远 敬畏 我,使他们 和他们后世 的子孙 得福乐, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, '又要与他们 立 永远 的约,必随著他们 施恩,并 不 离开 他们,且使他们有 敬畏我 的心,不 离开  我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, '我必欢喜 施恩 与他们,要尽 心 尽 意、诚诚实实 将他们栽 于 此 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, '「因为 耶和华 如此 说:我怎样 使 这 一切 大 祸 临 到 这 百姓,我 也要照样 使 我 所 应许 他们 的一切 福乐 都临 到他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, ' 你们 说,这地是 荒凉、无 人民、无牲畜,是交 付迦勒底人 手之地。日后在这 境内,必有人置买  田地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, '在便雅悯 地、耶路撒冷 四围的各处、犹大 的城邑、山地 的城邑、高原 的城邑,并南地 的城邑,人必用银子 买  田地,在契上 画 划押,将契封缄,请出 见证人,因为 我必使 被掳的人 归回。这是耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, '耶利米 还 囚 在护卫兵 的院内,耶和华 的话 第二 次临 到 他 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, '「成就 的是耶和华,造作、为要建立 的也是耶和华;耶和华 是他的名。他如此 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, '你求告 我,我就应允你,并将你所不 知道、又大 又难的事 指示 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, ' 论到 这 城 中的房屋 和 犹大 王 的宫室,就是拆毁 为 挡敌人高垒 和 刀剑的,耶和华─以色列的 神 如此 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, '人 要与 迦勒底人 争战 ,正是拿 死尸 充满这房屋,就是 我在怒气 和忿怒中 所杀的人,因 他们的一切 恶, 我就掩 面 不顾这 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, '看哪,我要使 这城 得以痊愈 安舒,使城中的人得医治,又将丰盛 的平安 和诚实 显明 与他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, '我也要使 犹大 被掳的 和 以色列 被掳的 归回,并建立他们 和起初一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, '我要除净他们 的一切 罪,就是 向我 所犯的罪;又要赦免 他们的一切 罪,就是 干犯 我、 违背 我的罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, '这城要在地上 万 国 人面前使我 得颂赞,得荣耀,名 为可喜可乐之城。万国人 因听见 我向这城 所 赐 的 福乐、 所 施 的 恩惠 平安,就惧怕 战 兢。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, '耶和华 如此 说:「你们 论 这 地方,说 是 荒废 无 人民 无 牲畜 之地,但在这荒凉 无 人民 无 牲畜 的犹大 城邑 和耶路撒冷 的街上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, '必再 听见有欢喜 和快乐 的声音、新郎 和新妇 的声音,并听见有人说:要称谢 万军 之耶和华,因 耶和华 本为善; 他的慈爱 永远长存!又有奉 感谢祭 到耶和华 殿 中之人的声音;因为 我必使 这地 被掳的人 归回,和起初一样。这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, '万军 之耶和华 如此 说:「在这 荒废 无 人民 无 牲畜之地,并其中所有的 城邑,必再 有 牧人 的住处;他们要使羊群 躺卧在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, '在山地 的城邑、高原 的城邑、南地 的城邑、便雅悯 地、耶路撒冷 四围的各处,和犹大 的城邑 必再 有羊群 从 数点的人 手 下经过。这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, '耶和华 说:「 日子 将到, 我应许 以色列 家 和 犹大 家 的恩 言 必然成就。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, '当那 日子,那 时候,我必使大卫 公义 的苗裔 长起来;他必在地上 施行 公平 和公义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, '在那 日子 犹大 必得救,耶路撒冷 必安然 居住,他的名 必称为『耶和华─我们的义』。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, '「因为 耶和华 如此 说:大卫 必永不 断 人 坐 在 以色列 家 的宝座上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, '祭司、利未人 在我面前 也不 断 人 献 燔祭、烧 素祭,时常 办理 献祭的事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, '耶和华 的话 临 到 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, '「耶和华 如此 说:你们若 能废弃 我所立白日 黑夜 的约,使 白日 黑夜 不 按时轮转, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, '就 能废弃 我与 我仆人 大卫 所立的约,使他 没有 儿子 在 他的宝座 上为王,并能废弃我与 事奉我的 祭司、利未人所立的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, ' 天上 的万象 不能 数算,海边 的尘沙 也不能 斗量;我必照样 使 我仆人 大卫 的后裔 和 事奉 我 的利未人 多起来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, '耶和华 的话 临 到 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, '「你没有 揣摩 这 百姓 的话 吗?他们说:『耶和华 所 拣选 的二 族, 他已经弃绝了。』他们这样藐视 我的百姓,以为 不再 成 国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, '耶和华 如此 说:若 是我立白日 黑夜 的约 不能存住,若是我未 曾安排 天 地 的定例, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, ' 我就弃绝 雅各 的后裔 和我仆人 大卫的后裔,不使 大卫的后裔 治理 亚伯拉罕、以撒、雅各 的后裔;因为 我必使 他们被掳的人 归回,也必怜悯他们。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, '巴比伦 王 尼布甲尼撒 率领他的全 军 和地上 属 他 的各 国 各 邦,攻打 耶路撒冷 和 属耶路撒冷 所有的 城邑。那时, 耶和华 的 话 临 到 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, '「耶和华─以色列的 神 说,你去 告诉 犹大 王 西底家, 耶和华 如此 说:我要 将 这 城 交 付巴比伦 王 的手,他必用火 焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, '你 必不能 逃脱 他的手,定 被拿住,交 在他的手中。你的眼 要见 巴比伦 王 的眼,他要口 对 口 和你说话,你也必到 巴比伦去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, '犹大 王 西底家啊,你还要 听 耶和华 的话。耶和华 论到 你如此 说:你必不 被刀剑 杀死, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, '你必平安 而死,人必为你 焚烧物件,好像 为你列祖,就是 在 你以前 的先 王 焚烧一般。人必为你 举哀说:『哀哉!我主啊。』耶和华 说:这 话 是我 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, '于 是,先知 耶利米 在耶路撒冷 将 这 一切 话 告诉 犹大 王 西底家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, '那时,巴比伦 王 的军队 正攻打 耶路撒冷,又攻打 犹大 所剩下 的 城邑,就是 拉吉 和 亚西加。原来 犹大 的坚固 城 只剩下 这 两座。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, '西底家 王 与 耶路撒冷 的 众 民 立 约,要向他们 宣告 自由,叫各人 任 他希伯来 的仆人 和 婢女 自由 出去,谁 也不可 使他的一个犹大 弟兄 作奴仆。(此后,有 耶和华 的 话 临 到 耶利米。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, '所有 立 约 的首领 和众 民 就 任 他 的仆人 婢女 自由 出去,谁也不 再 叫他们 作奴仆。大家 都顺从,将他们释放了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, '后来 却又反悔,叫 所 任去 自由 的仆人 婢女 回来,勉强 他们仍为仆 婢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, '因此耶和华 的话 临 到 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, '「耶和华─以色列的 神 如此 说:我 将 你们的列祖 从埃及 地 为奴 之家 领出来 的时候,与 他们立 约 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, '『 你的一个希伯来 弟兄 若 卖 给你,服事你 六 年,到 第七 年 你们各人 就要任他自由 出去。』只是你们列祖 不 听从 我,也不 侧 耳而听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, '如今 你们 回转,行 我眼中 看为正的事,各人 向邻舍 宣告 自由,并且在称 为 我名 下的 殿中、在我面前 立 约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, '你们却又反悔,亵渎 我的名,各人 叫 所 任去 随意 自由 的仆人 婢女 回来,勉强 他们 仍为 仆 婢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, '所以 耶和华 如此 说:你们 没有 听从 我,各人 向弟兄 邻舍 宣告 自由。看哪!我 向你们 宣告 一样自由,就是使你们自由于  刀剑、 饥荒、 瘟疫之下,并且使 你们 在天下 万 国 中抛来抛去。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, ' 犹大 的首领、耶路撒冷 的首领、太监、祭司,和国中 的众 民 曾将 牛犊 劈开 ,分成两半,从其中 经过,在我面前 立约。后来又违背 我的约, 不 遵行 这 约 上的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, '我必将他们 交 在仇敌 和寻索 其命 的人手中;他们的尸首 必给空中 的飞鸟 和地上 的野兽 作 食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, '并且我必将 犹大 王 西底家 和 他的首领 交 在他们仇敌 和寻索 其命的人,与那暂离你们 而去 巴比伦 王 军队 的手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, '耶和华 说:我必 吩咐 他们回 到 这 城,攻打 这城,将城攻取,用火 焚烧。我也要使 犹大 的城邑 变为荒场,无人 居住。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, '当犹大 王 约西亚 之子 约雅敬 的时候, 耶和华 的 话 临 到 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, '「你去 见 利甲 族的人,和他们 说话,领他们 进入 耶和华 殿 的一间 屋子,给他们 酒 喝。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, '我就 将 哈巴洗尼雅 的孙子 雅利米雅 的儿子 雅撒尼亚 和 他弟兄,并 他众 子,以及 利甲 全 族的人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, '领到 耶和华 的殿,进入 神 人 伊基大利 的儿子 哈难 众子 的屋子。那屋子 在首领 的屋子 旁边, 在沙龙 之子 把门 的玛西雅 屋子 以上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, '于 是我在利甲 族 人 面前 设摆 盛满 酒 的碗 和杯,对他们 说:「请你们喝 酒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, '他们却说:「我们不 喝 酒;因为 我们先祖 利甲 的儿子 约拿达 曾吩咐 我们 说:『你们 与你们的子孙 永 不可 喝 酒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, '也不可 盖 房、 撒 种、 栽种 葡萄园,但 一生的 年日 要住 帐棚,使 你们的日子 在 寄居 之地 得以延 长。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, '凡我们先祖 利甲 的儿子 约拿达 所 吩咐我们 的话,我们都 听从了。我们 和我们的妻子 儿 女 一生的 年日 都不 喝 酒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, '也不 盖 房 居住,也没 有 葡萄园、田地,和种子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, '但住 帐棚,听从 我们先祖 约拿达的话,照 他所 吩咐我们 的去行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, ' 巴比伦 王 尼布甲尼撒 上 此地来,我们因 怕迦勒底 的军队 和 亚兰 的军队,就说:『来吧,我们到耶路撒冷 去。』这样,我们才住 在耶路撒冷。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, '耶和华 的话 临 到 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, '「万军 之耶和华─以色列的 神 如此 说:你去 对犹大 人 和耶路撒冷 的居民 说,耶和华 说:你们不 受 教训,不听从 我的话吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, '利甲 的儿子 约拿达 所 吩咐 他子孙 不可 喝 酒 的话,他们已经遵守,直到 今 日 也不 喝酒,因为 他们听从 先祖 的吩咐。我 从早起来 警戒 你们,你们却不 听从 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, '我从早起来,差遣 我的仆人 众 先知去,说:『你们各人 当 回头,离开 恶 道,改正 行为,不 随 从 事奉 别 神,就必住 在 我所 赐 给你们 和你们列祖 的地上。』只是你们没有 听从 我,也没有 侧 耳而听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, ' 利甲 的儿子 约拿达 的子孙 能遵守 先人 所 吩咐 他们的命,这 百姓 却没有 听从 我! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, '因此,耶和华─万军之 神、以色列的 神 如此 说:我要 使 我所 说 的一切 灾祸 临 到 犹大人 和 耶路撒冷 的一切 居民。因为 我对他们 说话,他们没有 听从;我呼唤 他们,他们没有 答应。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, '耶利米 对利甲 族 的人说:「万军 之耶和华─以色列的 神 如此 说:因 你们听从 你们先祖 约拿达 的吩咐,谨守 他的一切 诫命,照 他所 吩咐 你们 的去行, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, '所以 万军 之耶和华─以色列的 神 如此 说:利甲 的儿子 约拿达 必永 不 缺 人 侍立 在我面前。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, ' 犹大 王 约西亚 的儿子 约雅敬 第四 年, 耶和华 的 话 临 到 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, '「你 取 一书 卷,将 我对你 说 攻击 以色列 和 犹大,并 各 国 的 一切 话,从我对你 说话 的那日,就是从约西亚 的日子 起直到 今 日,都写 在其上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, '或者 犹大 家 听见 我 想要 降 与他们 的 一切 灾祸,各人 就 回头,离开 恶 道,我好赦免 他们的罪孽 和罪恶。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, '所以,耶利米 召了 尼利亚 的儿子 巴录来;巴录 就从耶利米 口中,将 耶和华 对 耶利米所 说 的一切 话 写 在 书 卷上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, '耶利米 吩咐 巴录 说:「我 被拘管,不 能 进 耶和华 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, '所以你 要去 趁禁食 的日子,在耶和华 殿中 将 耶和华 的话,就是 你从我口中 所写 在书卷上的话,念 给百姓 和 一切 从犹大 城邑 出来 的人听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, '或者 他们 在耶和华 面前 恳求 各人 回头,离开 恶 道,因为 耶和华 向 这 百姓 所 说 要发的怒气 和忿怒 是大的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, '尼利亚 的儿子 巴录 就照先知 耶利米 一切 所 吩咐的 去行,在耶和华 的殿 中从书上 念 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, ' 犹大 王 约西亚 的儿子 约雅敬 第五 年 九 月,耶路撒冷 的众 民 和那从犹大 城邑 来 到耶路撒冷 的众 民,在耶和华 面前 宣告 禁食的日子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, '巴录 就在耶和华 殿 的上 院,耶和华 殿 的新 门 口,沙番 的儿子 文士 基玛利雅 的屋内,念 书上 耶利米 的 话 给众 民 听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, '沙番 的孙子、基玛利雅 的儿子 米该亚 听见 书 上耶和华 的 一切 话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, '他就下 到王 宫,进入 文士 的屋子。 众 首领,就是文士 以利沙玛、示玛雅 的儿子 第莱雅、亚革波 的儿子 以利拿单、沙番 的儿子 基玛利雅、哈拿尼雅 的儿子 西底家,和其余 馀的 首领 都坐 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, '于 是米该亚 对他们 述说 他所 听见 的一切 话,就是巴录 向百姓 念 那书 的时候所听见的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, '众 首领 就打发 古示 的曾孙、示利米雅 的孙子、尼探雅 的儿子 犹底 到 巴录那里,对他说:「你将所 念 给百姓 听 的书卷 拿 在手中 到我们这里来。」尼利亚 的儿子 巴录 就手 拿 书卷 来 到他们那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, '他们对他 说:「请 你坐下,念 给我们听。」巴录 就念 给他们听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, ' 他们听见 这一切 话 就害怕,面 面 相观,对 巴录 说:「我们必须 将 这 一切 话 告诉 王。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, '他们问 巴录 说:「请 你告诉 我们,你怎样 从他口中 写 这 一切 话呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, '巴录回答 说:「他用口 向我 说 这 一切 话,我 就用笔墨 写 在 书上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, '众首领 对 巴录 说:「你 和耶利米 要去 藏起来,不可 叫人 知道 你们 在哪里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, '众首领进 院 见 王,却先把 书卷 存 在文士 以利沙玛 的屋内,以后将 这一切 话 说 给王 听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, '王 就打发 犹底 去拿 这书卷来,他便从文士 以利沙玛 的屋内 取来, 念 给王 和王 左右 侍立 的众 首领 听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, '那时正是九 月,王 坐 在过冬 的房屋里,王的前面 火盆 中有烧著的火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, ' 犹底 念了 三 四 篇(或译:行),王就用文士 的刀 将书卷割破,扔 在 火 盆中,直到 全 卷 在 火 中烧尽了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, '王 和听见 这 一切 话的 臣仆 都不 惧怕,也不 撕裂 衣服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, ' 以利拿单 和第莱雅,并基玛利雅 恳求 王 不要 烧 这书卷,他却不 听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, '王 就吩咐 哈米勒 的儿子(或译:王的儿子)耶拉篾 和 亚斯列 的儿子 西莱雅,并 亚伯叠 的儿子 示利米雅,去捉拿 文士 巴录 和 先知 耶利米。耶和华 却将他们隐藏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, '王 烧了 书卷(其上 有巴录 从耶利米 口中 所 写的 话)以后,耶和华 的话 临 到 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, '「你 再 取 一 卷,将 犹大 王 约雅敬 所 烧 第一 卷 上的一切 话 写 在其上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, '论到 犹大 王 约雅敬 你要说,耶和华 如此 说:你 烧了 书卷,说:『你为什么 在其上 写著,说 巴比伦 王 必 要来 毁灭 这 地,使这地上 绝了 人民 牲畜呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, '所以 耶和华 论到 犹大 王 约雅敬 说:他 后裔中必 没有 人坐 在 大卫 的宝座上;他的尸首 必被抛弃,白日 受炎热,黑夜 受寒霜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, '我必因他 和 他后裔,并 他臣仆 的 罪孽 刑罚他们。我要使 我所 说 的一切 灾祸 临 到他们 和 耶路撒冷 的居民,并 犹大 人;只是他们不 听。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, '于 是,耶利米 又取 一 书卷 交 给 尼利亚 的儿子 文士 巴录,他就从耶利米 的口中 写了 犹大 王 约雅敬 所 烧 前卷上 的一切 话,另外 又添了 许多 相彷 仿的 话。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, '约西亚 的儿子 西底家 代替 约雅敬 的儿子 哥尼雅 为王,是 巴比伦 王 尼布甲尼撒 立 在犹大 地作王的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, '但西底家 和他的臣仆,并国 中的百姓,都不 听 从 耶和华 藉 借 先知 耶利米 所 说的 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, '西底家 王 打发 示利米雅 的儿子 犹甲 和 祭司 玛西雅 的儿子 西番雅 去见 先知 耶利米,说:「求 你为我们 祷告 耶和华─我们的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, '那时耶利米 在民 中 出 入,因为他们还没有 把他 囚 在监里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, '法老的 军队 已经从埃及 出来,那围困 耶路撒冷 的迦勒底人 听见 他们的风声,就拔营离开  耶路撒冷 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, '耶和华 的话 临 到 先知 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, '「耶和华─以色列的 神 如此 说:犹大 王 打发 你们 来 求问我,你们要如此 对他 说:『 那出来 帮助 你们 法老的 军队 必回 埃及 本国去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, '迦勒底人 必再来 攻打 这 城,并要攻取,用火 焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, '耶和华 如此 说:你们不要 自 欺 说「迦勒底人 必定 离开  我们」,因为 他们必不 离开 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, '你们即便 杀败了 与你们 争战 的 迦勒底 全 军,但剩下 受伤的 人 也必各人 从帐棚里 起来,用火 焚烧 这 城。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, ' 迦勒底的 军队 因怕 法老的 军队,拔营 离开  耶路撒冷的时候, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, '耶利米 就杂在 民 中出 离耶路撒冷,要往便雅悯 地 去,在那里 得自己的地业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, '他 到了 便雅悯 门 那里,有守门 官 名 叫伊利雅,是哈拿尼亚 的孙子、示利米雅 的儿子,他就拿住 先知 耶利米,说:「你是 投降 迦勒底人哪!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, '耶利米 说:「你这是谎话,我并不是 投降 迦勒底人。」伊利雅 不 听 他的话,就拿住他,解 到 首领那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, '首领 恼怒 耶利米,就打了 他, 将他 囚 在文士 约拿单 的房屋中,因为 他们以这房屋 当作 监 牢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, ' 耶利米 来到 狱中,进 入 牢房, 在那里 囚了 多 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, '西底家 王 打发 人提出他来, 在自己的宫内 私下 问他 说:「从 耶和华 有什么 话临到没有?」耶利米 说:「有!」又说:「你必交 在巴比伦 王 手中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, '耶利米 又对 西底家 王 说:「我在什么事 上得罪 你,或你的臣仆,或这 百姓,你竟 将我 囚 在 监里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, ' 对你们 预言 巴比伦 王 必不 来 攻击你们 和 这 地 的先知,现今在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, '主─我的王啊,求 你现在 垂听, 准 我在你面前 的恳求:不要 使我回到 文士 约拿单 的房屋中,免得 我死 在那里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, '于 是,西底家 王 下令,他们就把 耶利米 交 在护卫兵 的院中,每天 从饼舖 街 取一个 饼 给 他,直到 城中的 饼 用尽了。这样,耶利米 仍在 护卫兵 的院中。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, '玛坦 的儿子 示法提雅、巴施户珥 的儿子 基大利、示利米雅 的儿子 犹甲、玛基雅 的儿子 巴施户珥 听见 耶利米 对 众 人 所 说的 话,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, '「耶和华 如此 说:住 在这 城里 的必遭刀剑、饥荒、瘟疫 而死;但出去 归降 迦勒底人 的必得存活,就是 以自己 命 为掠物的,必得存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, '耶和华 如此 说:这 城 必要 交 在巴比伦 王 军队 的手中,他必攻取这城。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, '于 是首领 对 王 说:「求你 将 这 人 治死;因 他 向 城里 剩下的 兵 丁 和 众 民 说 这样的 话,使 他们的手 发软。 这 人 不是 求 这 百姓 得平安,乃是 叫他们受灾祸。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, '西底家 王 说:「 他 在你们手中,无论 何事,王 也不 能 与你们反对。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, '他们就拿住 耶利米,下 在 哈米勒 的儿子(或译:王的儿子)玛基雅 的牢狱里;那牢狱 在护卫兵 的院中。他们用绳子 将 耶利米 系下去。牢狱里 没有 水,只有 淤泥,耶利米 就陷 在淤泥中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, ' 在王 宫 的 太监 古实人以伯‧米勒,听见 他们将 耶利米 下了 牢狱(那时王 坐在 便雅悯 门口), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, '以伯‧米勒 就从王 宫 里出来, 对 王 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, '「主─我的王啊,这些 人 向先知 耶利米 一味地 行 恶,将 他 下 在 牢狱中;他在那里 必因 饥饿 而死,因为 城中 再 没有 粮食。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, '王 就吩咐 古实人以伯‧米勒 说:「你 从这里 带领 三十 人,趁著先知 耶利米 未死 以前,将他 从 牢狱 中提上来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, '于 是以伯‧米勒 带领 这些人同去,进入 王 宫,到 库房 以下,从那里 取了 些碎 布 和破 烂的衣服,用绳子 缒 下 牢狱 去到 耶利米那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, '古实人以伯‧米勒 对 耶利米 说:「 你用这些碎 布 和破烂的衣服 放 在 绳子上,垫 你的胳肢 窝。」耶利米 就照样 行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, '这样,他们用绳子 将 耶利米 从 牢狱 里拉 上来。耶利米 仍 在护卫兵 的院中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, '西底家 王 打发 人带领 先知 耶利米,进 耶和华 殿中 第三 门 里见王。王 就对 耶利米 说:「我 要问 你 一件事,你丝毫 不可 向我 隐瞒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, '耶利米 对 西底家 说:「我若 告诉 你,你岂不 定要 杀我吗?我若 劝戒你,你必不 听 从我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, '西底家 王 就私下 向 耶利米 说:「我指著 那 造 我们 生命 之永生的 耶和华 起誓:我必不 杀你,也不 将你交在 寻索 你命的 人 手中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, '耶利米 对 西底家 说:「耶和华─万军之 神、以色列的 神 如此 说:你若 出去 归降 巴比伦 王 的首领,你的命 就必存活,这 城 也不致 被火 焚烧,你 和你的全家 都必存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, '你若 不 出去 归降 巴比伦 王 的首领,这 城 必交 在迦勒底人 手中。他们必用火 焚烧,你 也不 得脱离 他们的手。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, '西底家 王 对 耶利米 说:「我 怕 那些 投降 迦勒底人 的犹大人,恐怕 迦勒底人将我 交 在他们手中,他们戏弄 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, '耶利米 说:「迦勒底人必不 将你交出。求你 听从 我 对你 所 说 耶和华 的话,这样你 必得好处,你的命 也必存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, '你 若 不肯 出去,耶和华 指示 我的话 乃是 这样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, ' 犹大 王 宫里 所 剩的 妇女 必都 带 到 巴比伦 王 的首领那里。这些妇女 必说:你知己 的朋友 催逼你,胜过 你;见你的脚 陷 入淤泥中,就转身 退后了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, '「人必将 你的后妃 和 你的儿女 带 到 迦勒底人那里;你 也不 得脱离 他们的手,必 被巴比伦 王 的手 捉住;你也必使 这 城 被火 焚烧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, '西底家 对 耶利米 说:「不要 使人 知道 这些 话,你就不至于  死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, '首领 若 听见了 我与你 说话,就来 见你,问你 说:『你对 王 说 什么 话不要 向我们 隐瞒,我们就不 杀你。王 向你 说 什么 话也要 告诉 我们。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, '你就对他们 说:『我 在王 面前 恳 求 不要 叫我回 到约拿单的 房屋 死 在那里。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, '随后众 首领 来 见 耶利米,问 他,他就照 王 所 吩咐的 一切 话 回答 他们。他们不再与他 说话,因为 事情 没有 泄漏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, '于 是耶利米 仍 在护卫兵 的院中,直到 耶路撒冷 被攻取 的 日子。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, '犹大 王 西底家 第九 年 十 月,巴比伦 王 尼布甲尼撒 率领全 军 来 围困 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, '西底家 十 一 年 四 月 初 九日,城 被攻破。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, '耶路撒冷被攻取的时候,巴比伦 王 的首领尼甲‧沙利薛、三甲‧尼波、撒西金─拉撒力、尼甲‧沙利薛─拉墨,并巴比伦 王 其余 馀的 一切 首领 都 来 坐 在中 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, ' 犹大 王 西底家 和一切 兵 丁 看见他们,就在夜间 从靠近 王 园 两城 中间 的门 出 城 逃 跑,往 亚拉巴 逃去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, '迦勒底的 军队 追赶 他们,在耶利哥 的平原 追上 西底家,将他 拿住,带 到 哈马 地 的利比拉、巴比伦 王 尼布甲尼撒那里;尼布甲尼撒就 审判 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, '巴比伦 王 在利比拉、西底家 眼前 杀了 他的众子, 又杀了 犹大 的一切 贵胄, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, '并且剜 西底家的 眼睛,用铜炼 链 𫔀 锁著他,要带到 巴比伦去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, '迦勒底人 用火 焚烧 王 宫 和 百姓 的房屋,又拆毁 耶路撒冷 的城墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, '那时,护卫 长 尼布撒拉旦 将 城里 所剩下的 百姓 和 投降 他 的 逃民,以及 其余 馀的 民 都掳 到巴比伦去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, '护卫 长 尼布撒拉旦却将 民 中毫无 所有 的 穷人 留 在犹大 地,当 时 给 他们 葡萄园 和田地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, '巴比伦 王 尼布甲尼撒 提到 耶利米,嘱咐 护卫 长 尼布撒拉旦 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, '「你领他去,好好地 看待 他,切不可 害 他;他对你 怎么 说,你就 向他 怎么 行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, ' 护卫 长 尼布撒拉旦 和尼布沙斯班─拉撒力、尼甲‧沙利薛─拉墨,并巴比伦 王 的一切 官长, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, '打发人去,将 耶利米 从护卫兵 院 中提出来,交 与 沙番 的孙子 亚希甘 的儿子 基大利,带 回 家去。于 是耶利米住 在民 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, '耶利米 还 囚 在护卫兵 院中的时候,耶和华 的话 临 到 他说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, '「你去 告诉 古实人以伯‧米勒 说,万军 之耶和华─以色列的 神 如此 说:我 说 降祸 不 降福 的话 必临 到 这 城,到那 时 必在你面前 成就了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, '耶和华 说:到那 日 我必拯救你,你必不致 交 在你 所 怕的 人 手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, ' 我定要 搭救你,你不致 倒 在刀下,却要 以自己 的命 为掠物,因 你倚靠 我。这是耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, '耶利米 锁 在耶路撒冷 和犹大 被掳到 巴比伦的 人中,护卫 长 尼布撒拉旦 将他 从 拉玛 释放 以后, 耶和华 的 话 临 到 耶利米。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, '护卫 长 将耶利米 叫来,对他 说:「耶和华─你的 神 曾说 要降 这 祸 与 此 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, '耶和华 使这祸临到,照 他所说的 行了;因为 你们得罪 耶和华,没有 听从 他的话,所以这 事 临 到你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, '现在 我解开  你手 上的 链子,你若 看 与我 同往巴比伦 去 好,就可以去,我必厚待 你;你若 看 与我 同往巴比伦 去 不好,就不必去。看哪,全 地 在你面前,你以为 哪里 美好,哪里 合宜,只管上 那里 去吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, '耶利米还 没有 回去,护卫长说:「你可以回 到 沙番 的孙子 亚希甘 的儿子 基大利那里去;现在巴比伦 王 立 他 作犹大 城邑的省长。你可以在他那里 住 在民 中,不然,你看 哪里 合宜 就可以上 那里去。」于 是护卫 长 送 他 粮食 和礼物,释放他去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, '耶利米 就到 米斯巴 见 亚希甘 的儿子 基大利,在他那里 住 在境内 剩下的 民 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, '在田野 的 一切 军 长 和属他们 的人 听见 巴比伦 王 立了 亚希甘 的儿子 基大利 作境内的省长,并 将 没有 掳到 巴比伦 的男人、妇女、孩童,和境 内极穷的人 全交 给他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, '于 是军长尼探雅 的儿子 以实玛利,加利亚 的两个儿子 约哈难 和约拿单,单户篾 的儿子 西莱雅,并尼陀法人 以斐 的众子,玛迦人 的儿子 耶撒尼亚 和属他们 的人,都到 米斯巴 见 基大利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, '沙番 的孙子 亚希甘 的儿子 基大利 向他们 和属他们的人 起誓 说:「不要 怕 服事 迦勒底人,只管住 在这地,服事 巴比伦 王,就可以得福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, '至于 我,我 要住 在米斯巴,伺候 那 到我们 这里来 的迦勒底人;只是你们 当积蓄 酒、油,和夏天的果子,收 在器皿里,住 在你们所 占的 城邑中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, ' 在摩押地 和亚扪 人中,在以东地 和 各 国 的一切 犹大人, 听见 巴比伦 王 留下 些犹大 人,并 立 沙番 的孙子 亚希甘 的儿子 基大利 管理他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, '这一切 犹大人 就从所 赶到 的各 处 回来,到 犹大 地 米斯巴的 基大利那里,又积蓄了 许 多 的酒,并夏天的果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, '加利亚 的儿子 约哈难 和 在田野 的一切 军 长 来 到米斯巴 见 基大利, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, '对他 说:「 亚扪 人 的王 巴利斯 打发 尼探雅 的儿子 以实玛利 来要 你的命,你知道吗?」亚希甘 的儿子 基大利 却不 信 他们的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, '加利亚 的儿子 约哈难 在米斯巴 私下 对 基大利 说:「求 你容我去 杀 尼探雅 的儿子 以实玛利,必无 人 知道。何必 让他要 你的命,使聚集 到你这里 来的犹大人 都 分散,以致犹大 剩下的人 都灭亡呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, '亚希甘 的儿子 基大利 对 加利亚 的儿子 约哈难 说:「你不可 行 这 事,你 所论 以实玛利 的话 是 假的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, ' 七 月间,王 的大臣 宗 室 以利沙玛 的孙子、尼探雅 的儿子 以实玛利 带著 十 个人,来 到米斯巴 见 亚希甘 的儿子 基大利。 他们在米斯巴 一同 吃 饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, '尼探雅 的儿 子以实玛利 和同他 来的 那 十 个人 起来,用刀 杀了 沙番 的孙子 亚希甘 的儿子 基大利, 就是 巴比伦 王 所立 为全地省长的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, '以实玛利 又杀了 在米斯巴、基大利 那里 的一切 犹大人 和 所 遇见的 迦勒底 兵 丁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, ' 他杀了 基大利,无 人 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, '第二 天,有八十 人 从示剑 和示罗,并撒马利亚 来,胡须 剃去,衣服 撕裂,身体划 㓰破,手拿 素祭 和乳香,要奉到 耶和华 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, '尼探雅 的儿子 以实玛利 出 米斯巴 迎接他们,随 走 随哭。 遇见了 他们,就对他们 说:「你们可以来 见 亚希甘 的儿子 基大利。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, ' 他们到了 城 中,尼探雅 的儿子 以实玛利 和同著他 的 人 就将他们杀了,抛在 坑 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, '只是他们中间 有 十 个人 对 以实玛利 说:「不要 杀我们,因为 我们有 许多大麦、小麦、油、蜜 藏 在田间。」于 是他住了手,没有 将他们杀 在弟兄 中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, '以实玛利 将 所 杀 之人 的尸首 都 抛在 坑里 基大利 的旁边;这坑是 从前亚撒 王 因怕 以色列 王 巴沙 所 挖的。尼探雅 的儿子 以实玛利 将那些被杀的人 填满了 坑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, '以实玛利 将 米斯巴 剩下的 人,就是 众公主 和 仍住 在米斯巴 所有的 百姓,原是 护卫 长 尼布撒拉旦 交 给 亚希甘 的儿子 基大利的,都掳去了。尼探雅 的儿子 以实玛利 掳了他们,要 往 亚扪 人 那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, '加利亚 的儿子 约哈难 和同著他 的 众 军 长 听见 尼探雅 的儿子 以实玛利 所 行的 一切 恶, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, '就带领 众 人 前往,要和 尼探雅 的儿子 以实玛利 争战 ,在 基遍 的 大 水旁(或译:大水池旁)遇见 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, ' 以实玛利 那里的 众 人 看见 加利亚 的儿子 约哈难 和 同著他 的 众 军 长,就都欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, '这样,以实玛利 从 米斯巴 所 掳去的 众 人 都转身 归 加利亚 的儿子 约哈难 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, '尼探雅 的儿子 以实玛利 和八 个人 脱离 约哈难的手,逃 往 亚扪 人 那里去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, '尼探雅 的儿子 以实玛利 杀了 亚希甘 的儿子 基大利,从 米斯巴 将 剩下的 一切 百姓、 兵 丁、妇女、孩童、太监 掳 到基遍 之后,加利亚 的儿子 约哈难 和同著他 的 众 军 长 将他们都夺 回来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, '带到 靠近 伯利恒 的 金罕 寓(或译:基罗特金罕)住下,要进入 埃及 去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, ' 因为 尼探雅 的儿子 以实玛利 杀了 巴比伦 王 所 立为省长 的亚希甘 的儿子 基大利, 约哈难惧怕 迦勒底人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, '众 军 长 和加利亚 的儿子 约哈难,并何沙雅 的儿子 耶撒尼亚(又名亚撒利雅,见四十三章二节)以及众 百姓,从最小的 到 至大的 都进前来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, '对 先知 耶利米 说:「求你 准 我们在你面前 祈求,为我们 这 剩下的 人祷告 耶和华─你的 神。 我们本来众多,现在剩下的 极少,这是 你亲眼 所见的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, '愿 耶和华─你的 神 指示 我们 所 当走的 路, 所 当做的 事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, '先知 耶利米 对他们 说:「我已经听见你们了,我必 照著你们的话 祷告 耶和华─你们的 神。 耶和华 无论 回答 什么,我必都告诉 你们,毫 不 隐瞒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, '于 是他们 对 耶利米 说:「我们若 不 照 耶和华─你的 神 差遣你 来 说的 一切 话 行,愿 耶和华 在我们中间 作 真实 诚信 的见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, '我们 现在请你 到 耶和华─我们的 神 面前, 他说的 无论是 好 是 歹,我们都必听从; 我们听从 耶和华─我们 神 的话,就可以 得福。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, ' 过了 十 天,耶和华 的话 临 到 耶利米。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, '他就将 加利亚 的儿子 约哈难 和 同著他 的 众 军 长,并众 百姓,从最小的 到 至大的 都叫了来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, '对他们 说:「耶和华─以色列的 神,就是 你们请 我 在他面前 为你们祈 求的主,如此 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, '『你们若 仍 住 在这 地,我就建立 你们,必不 拆毁,栽植 你们,并不 拔出,因 我为 降与 你们 的 灾祸 后悔了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, '不要 怕 你们 所 怕的 巴比伦 王』」。耶和华 说:「不要 怕 他!因为 我 与你们同在,要拯救 你们 脱离 他的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, '我也要使他发 怜悯,好怜悯 你们,叫你们 归 回 本地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, '倘若 你们 说:『我们不 住 在这 地』,以致不 听从 耶和华─你们 神 的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, '说:『我们不住这地,却 要进入 埃及 地,在那里 看不 见 争战 ,听不 见 角 声,也不 致无食 饥饿。我们必住 在那里。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, '你们所剩下的 犹大人哪,现在 要听 耶和华 的话。万军 之耶和华─以色列的 神 如此 说:『你们 若 定 意 要进入 埃及, 在那里 寄居, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, ' 你们 所 惧怕的 刀剑 在埃及 地 必追上 你们!你们 所 惧怕的 饥荒 在埃及 要紧紧地 跟随你们!你们必死 在那里! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, '凡 定 意 要进入 埃及 在那里 寄居的 必 遭刀剑、饥荒、瘟疫 而死, 无 一人 存留,逃脱 我 所 降 与他们 的灾祸。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, '「 万军 之耶和华─以色列的 神 如此 说:『我怎样 将我的怒气 和忿怒 倾 在 耶路撒冷 的居民身上, 你们进入 埃及的时候,我也必照样 将我的忿怒 倾 在你们身上,以致你们令人辱骂、惊骇、咒诅、羞辱,你们不 得再 见 这 地方。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, '所剩下的 犹大人哪,耶和华 论到你们 说:『不要 进入 埃及去。』你们要确实地 知道 我今日 警教 你们了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, ' 你们行诡诈 自害;因为 你们请 我 到 耶和华─你们的 神那里,说:『求 你为我们 祷告 耶和华─我们 神,照 耶和华─我们的 神 一切 所 说的 告诉 我们,我们就必遵行。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, '我今日 将这话告诉 你们,耶和华─你们的 神 为你们的事差遣我 到你们 那里说的,你们却一样 没有 听从。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, '现在 你们要确实地 知道, 你们在所 要 去 寄居 之地 必遭刀剑、饥荒、瘟疫 而死。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, ' 耶利米 向 众 百姓 说 完了 耶和华─他们 神 的 一切 话,就是 耶和华─他们 神 差遣 他去 所说的 一切 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, '何沙雅 的儿子 亚撒利雅 和加利亚 的儿子 约哈难,并一切 狂傲的 人,就 对 耶利米 说:「你 说 谎言!耶和华─我们的 神 并没有 差遣你 来说:『你们不可 进入 埃及,在那里 寄居。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, '这是 尼利亚 的儿子 巴录 挑唆 你 害我们,要 将我们交 在迦勒底人 的手中,使我们 有被杀的,有被掳 到巴比伦去的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, '于 是加利亚 的儿子 约哈难 和一切 军 长,并众 百姓,不 听从 耶和华 的话 住 在犹大 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, '加利亚 的儿子 约哈难 和一切 军 长 却 将 所剩下的 犹大人,就是 从 被赶到 各国 回来 在犹大 地 寄居的 男人、 妇女、 孩童,和 众公主,并 护卫 长 尼布撒拉旦 所 留 在 沙番 的孙子 亚希甘 的儿子 基大利 那里的众 人,与 先知 耶利米,以及 尼利亚 的儿子 巴录, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, '都带入 埃及 地,到了 答比匿。这是因 他们不 听从 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, '在答比匿,耶和华 的话 临 到 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, '「你在犹大 人 眼前 要用手 拿 几块大 石头,藏 在砌砖的 灰泥中,就是 在答比匿 法老 的宫 门那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, '对他们 说:『万军 之耶和华─以色列的 神 如此 说:我 必 召 我的仆人 巴比伦 王 尼布甲尼撒来。在 所 藏的 石头 上我要安置 他的宝座;他必将 光华的宝帐 支搭 在其上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, '他要来 攻击 埃及 地,定为 死亡的,必致死亡;定为 掳掠的,必被掳掠;定为 刀杀的,必交刀杀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, '我要在埃及 神 的庙中 使火 著起,巴比伦王要将庙宇焚烧,神像掳去;他要得(原文是披上) 埃及 地,好像 牧人 披上 外衣,从那里 安然 而去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, '他必打碎 埃及 地伯‧示麦 的柱像,用火 焚烧 埃及 神 的庙宇。』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, '有 临 到 耶利米 的话,论及 一切 住 在埃及 地 的犹大人,就是住 在密夺、答比匿、挪弗、巴忒罗 境内的犹大人,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, '「万军 之耶和华─以色列的 神 如此 说: 我所 降 与 耶路撒冷 和 犹大 各 城 的一切 灾祸 你们 都看见了。 那些城邑今 日 荒凉,无人 居住; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, '这是因 居民所 行 的恶,去 烧香 事奉 别 神,就是 他们 和你们,并你们列祖 所不 认识的神,惹我发怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, '我从早起来 差 遣 我的仆人 众 先知 去 说,你们切 不要 行 我所 厌恶 这 可憎 之事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, '他们却不 听从,不 侧 耳而听,不转离 恶事,仍 向别 神 烧香。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, '因此,我的怒气 和忿怒 都倒 出来,在犹大 城邑中 和耶路撒冷 的街市上,如火著起,以致 都荒废 凄凉,正如今 日一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, '现在 耶和华─万军之 神、以色列的 神 如此 说:你们 为何 作 这大 恶 自害 己命,使你们的 男人、妇女、婴孩,和吃奶的 都从犹大 中 剪除、不 留 一人呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, '就是因你们 手 所做的,在所 去 寄居 的 埃及 地 向别 神 烧香 惹我发怒,使 你们 被剪除, 在 天下 万国 中令人 咒诅 羞辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, ' 你们列祖 的恶行, 犹大 列王 和 他们后妃 的恶行, 你们自己 和 你们妻子 的恶行,就是 在犹大 地、耶路撒冷 街上 所行的,你们都忘了吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, '到 如 今 还没有 懊悔,没有 惧怕,没有 遵行 我在你们 和你们列祖 面前 所 设立的 法度 律例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, '「所以 万军 之耶和华─以色列的 神 如此 说:我 必向你们 变 脸 降灾,以致剪除 犹大 众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, '那 定 意 进入 埃及 地、在那里 寄居的,就是 所剩下的 犹大人,我必使 他们尽都 灭绝,必在埃及 地 仆倒,必因刀剑 饥荒 灭绝;从最小的 到 至大的 都必遭刀剑 饥荒 而死,以致令人 辱骂、惊骇、咒诅、羞辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, '我怎样 用刀剑、饥荒、瘟疫 刑罚 耶路撒冷,也必照样刑罚 那些住 在埃及 地的犹大人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, '甚至那进 入埃及 地 寄居的,就是所剩下的 犹大人,都不 得 逃脱,也不得存留 归回 犹大 地。 他们 心 中甚想 归回 居住 之地;除了 逃脱的以外,一个 都不能 归回。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, '那些 住 在埃及 地 巴忒罗 知道 自己妻子 向别 神 烧香的,与 旁边站立的 众 妇女,聚集成 群,回答 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, '「论到你奉耶和华 的名 向我们 所 说 的话,我们必不 听 从。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, ' 我们定要 成就 我们口中 所 出 的一切 话,向天 后 烧香、浇 奠祭,按著我们 与我们列祖、君王、首领 在犹大 的城邑中 和耶路撒冷 的街市 上素常所 行的一样;因为那时我们 吃饱 饭、享福乐,并不 见 灾祸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, '自从 我们停止 向天 后 烧香、浇 奠祭,我们倒缺乏 一切,又因刀剑 饥荒 灭绝。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, '妇女说:「 我们 向天 后 烧香、浇 奠祭,做 天后像的 饼 供奉她,向她 浇 奠祭,是外乎 我们的丈夫吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, '耶利米 对 一切 那样 回答 他的 男人 妇女 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, '「你们 与你们列祖、君王、首领,并国 内的百姓,在犹大 城邑中 和耶路撒冷 街市上 所 烧的 香,耶和华 岂不 记念, 心 中岂不思想吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, '耶和华 因 你们所作的 恶、 所 行 可憎的事,不 能 再 容忍,所以 你们的地 荒凉,令人惊骇 咒诅,无人 居住,正如今 日一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, ' 你们烧香, 得罪 耶和华,没有 听从 他 的话,没有 遵行 他的律法、条例、法度,所以 你们 遭遇 这 灾祸,正如今 日一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, '耶利米 又对 众 民 和 众 妇女 说:「你们 在埃及 地 的一切 犹大人 当听 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, '万军 之耶和华─以色列的 神 如此 说:你们 和你们的妻 都口中 说、手里 做,说:『我们定要 偿还 所 许 的愿 ,向天 后 烧香、浇 奠祭。』现在你们只管 坚定 所许的 愿  而 偿还吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, '所以 你们住 在埃及 地 的一切 犹大人 当听 耶和华 的话。耶和华 说:我 指著我的大 名 起誓,在埃及 全 地,我的名 不 再 被犹大 一个 人 的口 称呼 说:『我指著主─永生的 耶和华起誓。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, '我 向他们 留意 降祸 不 降福;在埃及 地 的 一切 犹大 人 必因刀剑、饥荒 所灭,直到 灭尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, '脱离 刀剑、从 埃及 地 归回 犹大 地 的人数 很少;那进入 埃及 地 要在那里 寄居的,就是所 剩下的 犹大人,必知道 是谁 的话 立得住,是我的话呢?是他们的话呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, '耶和华 说: 我 在这 地方 刑罚 你们,必有 预兆,使 你们知道 我降祸 与你们 的话 必要 立得住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, '耶和华 如此 说:我 必将 埃及 王 法老合弗拉 交 在他仇敌 和寻索 其命 的人手中,像 我将 犹大 王 西底家 交 在他仇敌 和寻索 其命 的巴比伦 王 尼布甲尼撒 手中一样。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, '犹大 王 约西亚 的儿子 约雅敬 第四 年, 尼利亚 的儿子 巴录 将 先知 耶利米 口中 所 说 的 话 写 在 书上。耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, '「巴录啊,耶和华─以色列的 神 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, '巴录(原文是你)曾说:『哀哉! 耶和华 将忧愁 加 在 我的痛苦上,我因唉哼 而困乏,不 得 安歇。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, '你要这样 告诉 他,耶和华 如此 说:我 所 建立的,我 必拆毁; 我所 栽植的,我 必拔出; 在全 地 我都如此行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, '你 为自己 图谋 大事吗?不要 图谋!我 必 使灾祸 临 到 凡 有血气的。但你无论 往 哪里 去,我必使 你 以 自己的命 为掠物。这是耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, '耶和华 论 列国 的话 临 到 先知 耶利米。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, '论到关乎 埃及 王 法老尼哥 的军队:这军队 安营 在 幼发拉底 河 边的迦基米施,是 巴比伦 王 尼布甲尼撒 在犹大 王 约西亚 的儿子 约雅敬 第四 年 所打败的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, '你们要预备 大小盾牌,往前 上阵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, '你们 套上车,骑上 马!顶盔 站立,磨 枪 贯 甲! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, '我为何 看见 他们 惊惶 转身 退后呢?他们的勇士 打败了,急忙 逃跑,并不 回头;惊吓 四围都有!这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, '不要 容快跑的 逃避;不要 容勇士 逃脱(或译:快跑的不能逃避;勇士不能逃脱);他们在 北方 幼发拉底 河 边绊跌 仆倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, '像尼罗河 涨发,像江河 之水 翻腾 的 是谁呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, '埃及 像尼罗河 涨发,像江河 的水 翻腾。他说:我要涨发 遮盖 遍地;我要毁灭 城邑 和其中 的居民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, '马匹 上去吧!车辆 急行吧!勇士,就是手拿 盾牌 的古实人和弗人(又作利比亚人),并 拉 弓 的路德族,都出去吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, '那 日 是主─万军 之耶和华 报仇 的日子,要向敌人 报仇。刀剑 必吞吃 得饱,饮血 饮足;因为 主─万军 之耶和华 在 北 方 幼发拉底 河 边有献祭的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, '埃及 的民(原文是处女)哪,可以上 基列 取 乳香去;你虽多 服良药,总是徒然,不得 治好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, '列国 听见 你的羞辱,遍地 满了 你的哀声; 勇士 与勇士 彼此相 碰,一齐 跌倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, '耶和华 对 先知 耶利米 所 说 的话,论到巴比伦 王 尼布甲尼撒 要来 攻击 埃及 地: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, '你们要传扬 在埃及,宣告 在密夺,报告 在挪弗、答比匿 说:要站起出队,自作准备,因为 刀剑 在你四围 施行吞灭的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, '你的壮士 为何 被冲去呢?他们站立 不住;因为 耶和华 驱逐他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, '使多人 绊跌;他们也 彼此 撞倒,说:起来吧!我们再往 本民 本 地去,好躲避 欺压的 刀剑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, '他们在那里 喊叫说:埃及 王 法老 不过是个声音(或译:已经败亡);他已错过 所定的时候了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, '君王─名 为万军 之耶和华 的说:我 指著我的永生起誓:尼布甲尼撒(原文是他)来 的势派必 像他泊 在众山之中,像迦密 在海边一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, '住 在埃及的民(原文是女子)哪,要预备 掳去 时所用的物件;因为 挪弗 必成为 荒场,且被烧毁,无人 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, '埃及 是肥美的 母牛犊;但出于 北方的毁灭(或译:牛虻)来到了!来到了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, ' 其中 的雇勇 好像圈里的肥 牛犊, 他们 转身退后,一齐 逃跑,站立 不住;因为 他们遭难 的日子、追讨 的时候 已经临到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, '其中的声音 好像蛇 行一样。敌人要 成队 而来,如砍伐 树木 的手拿斧子 攻击 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, '耶和华 说:埃及的树林 虽然 不能 寻察(或译:穿不过),敌人却要砍伐,因 他们多 于 蝗虫,不可 胜数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, '埃及的民(原文是女子)必然蒙羞,必交 在北方 人 的手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, '万军 之耶和华─以色列的 神 说:「我 必刑罚 挪的 亚扪(埃及尊大之神)和 法老,并 埃及 与 埃及的神,以及 君王,也必刑罚 法老 和 倚靠 他的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, '我要将他们交 付寻索 其命 之人的手 和巴比伦 王 尼布甲尼撒 与他臣仆 的手;以后 埃及必再有人居住,与从前 一样。这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, '我的仆人 雅各啊, 不要 惧怕!以色列啊,不要 惊惶!因 我 要从远方 拯救你,从被掳到 之地拯救 你的后裔。雅各 必回来,得享平靖 安逸,无人 使他害怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, '我的仆人 雅各啊, 不要 惧怕!因 我 与你同在。 我要将我所 赶你到 的 那些 国 灭绝 净尽,却不 将你 灭绝 净尽,倒要从宽 惩治你,万 不能 不罚你(不罚你:或译以你为无罪)。这是耶和华 说的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, '法老 攻击 迦萨 之先,有 耶和华 论 非利士人 的话 临 到 先知 耶利米。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, '耶和华 如此 说: 有水 从北方 发起,成为 涨溢的 河,要涨过 遍地 和其中所有的,并城 和其中 所住的。人 必呼喊;境内 的居民 都 必哀号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, '听见敌人壮 马 蹄跳 的响声 和战 车 隆隆、车轮 轰轰;为父 的手 就发软,不 回头 看顾 儿女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, '因为 日子 将到,要毁灭 一切 非利士人,剪除 帮助 泰尔、西顿 所 剩下的人。原来 耶和华 必毁灭 非利士人,就是迦斐托 讬 海岛 余 馀剩的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, ' 迦萨 成了 光秃;平原中 所剩的 亚实基伦 归于 无有。你用刀划 㓰身,要到 几时呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, '耶和华的 刀剑 哪,你到 几时 才 止息呢?你要入 鞘,安靖 不动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, '耶和华 既吩咐 你 攻击 亚实基伦 和 海 边 之地,他已经派定你,焉能 止息呢?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, '论摩押。万军 之耶和华─以色列的 神 如此 说: 尼波 有祸了!因 变为荒场。基列亭 蒙羞 被攻取;米斯迦 蒙羞 被毁坏; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, '摩押 不 再 被称赞。有人在希实本 设 计 谋害她,说:来吧!我们将她剪除,不再成国。玛得缅哪,你也 必默默无声;刀剑 必追赶 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, '从何罗念 有喊荒凉 大 毁灭 的哀 声: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, '摩押 毁灭了!她的孩童(或译:家僮)发哀声,使人听见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, ' 人上 鲁希 坡 随走随 哭,因为 在何罗念 的下坡 听见 毁灭的 哀声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, '你们要奔逃,自救 性命,独自居住,好像旷野 的杜松。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, '你 因 倚靠 自己所做的 和自己的财宝 必 被攻取。基抹 和属他的祭司、首领 也要一同 被掳 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, '行毁灭的 必来 到 各 城,并无 一城 得免。山谷 必致败落,平原 必被毁坏;正如耶和华 所 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, '要将翅膀 给 摩押,使她可以飞 去。她的城邑 必 致荒凉,无人 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, '(懒惰 为耶和华 行 事的,必受咒诅;禁止 刀剑 不经血的,必受咒诅。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, '摩押 自幼年 以来常享安逸,如酒 在 渣滓 上澄清,没有 从这器皿 倒 在 那器皿里,也未 曾被掳 去。因 此,它的原味 尚存,香气 未 变。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, '耶和华 说:「 日子 将到,我必打发 倒酒的 往她那里去,将她倒出来,倒空 她的器皿,打碎 她的坛子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, '摩押 必因基抹 羞愧,像 以色列 家 从前倚靠 伯特利 的神羞愧一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, '你们怎么 说:我们是 勇士,是有勇力 打仗的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, '摩押 变为荒场,敌人上去 进了她的城邑。她所特选的 少年人 下去 遭了杀戮;这是君王─名 为万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, '摩押 的灾殃 临 近;她的苦难 速速 来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, '凡 在她四围的 和 认识 她名的,你们都要为她 悲伤,说:那结实的 杖 和那美好的 棍,何竟 折断了呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, '住 在底本的民(原文是女子)哪,要从你荣耀的 位上下来,坐 受干渴;因 毁灭 摩押 的上来 攻击你,毁坏了 你的保障。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, '住 亚罗珥的啊,要站 在 道 旁观望,问 逃避的男人 和逃脱的女人 说:是 什么事呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, '摩押 因 毁坏 蒙羞;你们要哀号 呼喊,要在亚嫩 旁报告 说:摩押 变为荒场! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, '「刑罚 临 到 平原 之地的 何伦、 雅杂、 米法押、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, ' 底本、 尼波、伯‧低比拉太音、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, ' 基列亭、伯‧迦末、伯‧米恩、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, ' 加略、 波斯拉,和 摩押 地 远 近 所有的 城邑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, '摩押 的角 砍断了,摩押的膀臂 折断了。这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, '「你们要使摩押 沉醉,因 他向 耶和华 夸大。他要在自己所吐 之中打滚,又 要 被人嗤笑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, '摩押啊, 你 不曾 嗤笑 以色列吗?她岂 是在贼 中查出来的呢? 你每逢 提到 她 便摇头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, '摩押 的居民哪,要离开  城邑,住 在山崖里, 像鸽子 在深渊 口 上 搭窝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, '我们听说 摩押人 骄傲,是极其 骄傲;听说他自高 自傲,并且狂妄,居心 自大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, '耶和华 说:我 知道 他的忿怒 是虚空的;他夸大的话 一无 所成。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, '因 此,我要为 摩押 哀号,为摩押 全地 呼喊;人必为吉珥‧哈列设 人 叹息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, '西比玛 的葡萄树啊,我为你 哀哭,甚于 雅谢人 哀哭。你的枝子 蔓延过 海,直长 到 雅谢 海。那行毁灭的 已经临 到 你夏天的果子 和 你所摘的葡萄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, '肥田 和摩押 地 的欢喜 快乐 都被夺去;我使酒醡 的酒 绝流,无人 踹酒 欢呼;那欢呼却变为仇敌的呐喊(原文是那欢呼 却不是 欢呼)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, '「希实本人 发的 哀 声 达到 以利亚利,直达到 雅杂;从琐珥 达到何罗念,直到 伊基拉‧施利施亚,因为 宁林 的水 必然 干涸。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, '耶和华 说:「我必在摩押地 使那在邱坛 献祭的,和那向他的神 烧香 的都断绝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, ' 我心腹 为摩押 哀鸣 如箫,我心肠 为吉珥•哈列设 人 也是如此,因 摩押人所得的 财物 都灭没了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, '「 各人 头上 光秃, 胡须 剪短, 手 有划 㓰伤, 腰 束麻布。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, '在 摩押 的各 房顶上 和街市上 处处 有人哀哭;因 我打碎 摩押,好像打碎无人 喜悦 的器皿。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, '摩押 何等 毁坏!何等哀号!何等 羞愧 转 背!这样,摩押 必令 四 围 的人嗤笑 惊骇。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, ' 耶和华 如此 说: 仇敌必如大鹰 飞起,展开  翅膀,攻击 摩押。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, '加略 被攻取,保障 也被占据。到那 日,摩押 的勇士 心中疼痛如 临产的 妇人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, '摩押 必被毁灭,不再成国,因 他向 耶和华 夸大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, '耶和华 说:摩押 的居民哪,恐惧、陷坑、网罗 都临近你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, '躲避 恐惧 的必坠 入 陷坑;从 陷坑 上来 的必被网罗 缠住;因 我必使追讨 之年 临 到 摩押。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, '躲避的人 无力 站 在希实本 的影下;因为 有火 从希实本 发出,有火焰 出于  西宏的城,烧尽 摩押 的角 和哄嚷 人 的头顶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, '摩押啊,你 有祸了!属基抹 的民 灭亡了!因 你的众子 都被掳 去,你的众女 也被掳去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, '耶和华 说:到末后,我还要使被掳的 摩押人 归回。摩押 受审判 的话到 此为止。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, '论亚扪 人。耶和华 如此 说:以色列 没有 儿子吗? 没有 后嗣吗?玛勒堪 为何 得 迦得之地为业呢?属他的民 为何住 其中的城邑呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, ' 耶和华 说: 日子 将到,我必使人听见 打仗 的喊声,是攻击 亚扪人 拉巴的喊声。拉巴要成为 乱 堆;属她的乡村(原文是女子)要被火 焚烧。先前得以色列地为业的,此时以色列 倒要得他们的地为业。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, '希实本哪,你要哀号,因为 爱 地变为荒场。拉巴的居民(原文是女子)哪,要呼喊,以麻布 束腰;要哭号,在篱笆中 跑来跑去;因 玛勒堪 和属他的祭司、首领 要一同 被掳 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, '背道的民(原文是女子)哪,你们为何 因有山谷,就是水流的 山谷 夸张呢?为何倚靠 财宝说:谁 能来 到我们这里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, '主─万军 之耶和华 说:我 要使恐吓 从四 围 的人中临 到你们;你们必被赶出,各人 一直前往,没有 人收聚 逃民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, '后来 我还要使 被掳的 亚扪 人 归回。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, '论以东。万军 之耶和华 如此 说:提幔中 再 没有 智慧吗?明哲人 不再有 谋略吗?他们的智慧 尽归无有吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, '底但 的居民哪,要转身 逃跑,住 在深密处;因为 我向以扫 追讨 的时候,必使灾殃 临 到他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, '摘葡萄的 若 来到 他那里,岂不 剩下 些葡萄呢?盗贼 若 夜间而来,岂不毁坏 直到够了呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, '我 却 使 以扫 赤露,显出 他的隐密处;他不 能 自藏。他的后裔、弟兄、邻舍 尽都灭绝;他也归于 无有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, '你撇下 孤儿,我 必保全他们的命;你的寡妇 可以倚靠 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, ' 耶和华 如此 说:「 原 不 该 喝 那杯 的一定要 喝。你 能尽 免刑罚吗?你必不能 免, 一定要 喝!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, '耶和华 说:「 我指著自己 起誓,波斯拉 必 令人 惊骇、羞辱、咒诅,并且荒凉。她的一切 城邑 必变为 永远的 荒场。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, '我从 耶和华 那里听见 信息,并有使者 被差往 列国去,说:你们聚集 来 攻击以东,要起来 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, ' 我使 你在列国中 为最小,在世人中 被藐视。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, '住 在山 穴中 据守 山 顶的啊,论到你的威吓,你因心中 的狂傲 自欺;你虽 如大鹰 高高 搭窝,我却从那里 拉下你来。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, '以东 必令人 惊骇;凡 经过 的人就受惊骇,又因她 一切的 灾祸 嗤笑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, '耶和华 说:必无 人 住 在那里,也无 人 在其中 寄居,要像所多玛、蛾摩拉,和邻近 的城邑倾覆 复的时候一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, ' 仇敌必像狮子 从约旦河 边的丛林 上来,攻击 坚固的 居所。 转眼之间,我要使以东人逃跑,离开 这地。谁 蒙拣选,我就派 谁治理这地。 谁 能比我呢?谁 能给我定规日期呢?有何 牧人 能 在我面前 站立得住呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, ' 你们要听 耶和华 攻击 以东 所 说 的谋略 和他攻击 提幔 居民 所 定 的旨意。仇敌定要 将他们群众 微弱的 拉去,定要 使他们的 居所 荒凉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, '因他们仆倒 的声音,地 就震动。人在红 海 那里必听见 呼喊 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, ' 仇敌必如大鹰 飞 起,展开  翅膀 攻击 波斯拉。到那 日,以东 的勇士 心中疼痛 如 临产 的妇人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, '论大马士革。哈马 和亚珥拔 蒙羞,因 他们听见 凶恶的 信息 就消化了。海上 有忧愁,不 得 平静。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, '大马士革 发软,转身 逃跑。战 兢 将她捉住;痛苦 忧愁 将她抓住,如产难的妇人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, '我所喜乐 可称赞的 城,为何 被撇弃了呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, ' 她的少年人 必仆倒 在街上;当那 日,一切 兵 丁 必默默无声。这是万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, '我必在大马士革 城中 使火 著起,烧灭 便哈达 的宫殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, '论巴比伦 王 尼布甲尼撒 所 攻打 的基达 和夏琐 的诸国。耶和华 如此 说:迦勒底人哪,起来 上 基达 去,毁灭 东方 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, '他们的帐棚 和羊群 都要夺去,将幔子 和一切 器皿,并骆驼 为自己 掠去。人向他们 喊著说:四围 都有惊吓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, '耶和华 说:夏琐 的居民哪,要逃 奔 远方,住 在深密处;因为 巴比伦 王 尼布甲尼撒 设 计 谋害你们,起 意 攻击你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, '耶和华 说:迦勒底人哪,起来!上 安逸 无虑 的居 民那里去;他们是 无 门 无 闩、独自 居住的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, '他们的骆驼 必成为 掠物;他们众多的 牲畜 必成为掳物。我必将剃 周围 头发的人分散 四方(原文是风),使 灾殃 从四 围 临到他们。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, '夏琐 必成为 野狗 的住处, 永远 凄凉;必无 人 住 在那里,也无 人 在其中 寄居。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, '犹大 王 西底家 登 基的时候, 耶和华 论 以拦 的话 临 到 先知 耶利米 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, '「万军 之耶和华 如此 说:我 必折断 以拦人 的弓,就是他们为首 的权力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, '我要使 四 风 从天 的四 方刮来,临到 以拦人,将他们分散 四方(原文是风)。这 被赶散的 人 没 有 一国 不 到的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, '耶和华 说:「我必使 以拦人 在仇敌 和寻索 其命 的人面前 惊惶;我也必使灾祸,就是 我的烈 怒 临 到他们,又必使 刀剑 追杀 他们,直到 将他们 灭尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, '我要在以拦 设立 我的宝座,从那里 除灭 君王 和首领。」这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, '「 到末后,我还要使 被掳的 以拦人 归回。这是耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, '耶和华 藉 借 先知 耶利米 论 巴比伦 和 迦勒底人 之地 所 说 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, '你们要在万国中 传扬 报告,竖立 大旗;要报告,不可 隐瞒,说:巴比伦 被攻取,彼勒 蒙羞,米罗达 惊惶。巴比伦的神像 都蒙羞;她的偶像 都惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, '「因 有一国 从北方 上来 攻击她, 使 她的地 荒凉, 无人 居住,连人 带 牲畜 都逃 走了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, '耶和华 说:「当那 日子、那 时候,以色列 人 要 和犹大 人 同 来,随走 随哭, 寻求 耶和华─他们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, '他们必访问 锡安,又面向 这里,说:『来吧,你们要与 耶和华 联合 为永远 不 忘 的约。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, '「我的百姓 作了 迷失的 羊,牧人 使他们走差路,使他们转到 山上。他们从大山 走 到 小山,竟忘了 安歇之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, '凡 遇见他们的,就把他们吞灭。敌人 说:『我们没有 罪;因 他们 得罪 那作公义 居所 的耶和华,就是他们列祖 所仰望的 耶和华。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, '「我民哪,你们要从巴比伦 中 逃走,从迦勒底人 之地 出去,要 像羊群 前面 走的公山羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, '因 我 必激动 联合的 大 国 从北 方 上来 攻击 巴比伦,他们要摆阵 攻击她;他必从那里 被攻取。他们的箭 好像善射 之勇士的箭,一枝也不 徒然 返回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, '迦勒底 必成为 掠物;凡 掳掠她 的都必心满意足。这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, '抢夺 我产业的啊,你们因 欢喜 快乐,且 像踹谷 撒欢 的母牛犊,又像发嘶声 的壮马。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, '你们的母 巴比伦就极其 抱愧,生你们 的必然蒙羞。 她要列在诸国 之末,成为旷野、旱地、沙漠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, '因耶和华 的忿怒,必无人 居住,要 全然 荒凉。凡 经过 巴比伦 的要受惊骇,又因 她所 遭的灾殃 嗤笑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, '所有 拉 弓的,你们要在 巴比伦 的四围 摆阵,射箭 攻击她。不要 爱惜 箭枝,因 她得罪了 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, '你们要在她 四围 呐喊;她已经投降。外郭 坍塌了,城墙 拆毁了,因为 这是 耶和华 报仇的事。你们要向巴比伦 报仇;她怎样 待人,也要怎样待 她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, '你们要将巴比伦 撒种 的和收割 时 拿 镰刀 的都剪除了。他们各人因 怕欺压的 刀剑,必 归 回 本族, 逃到 本土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, '「以色列 是打散的 羊,是被狮子 赶出的。首先 是亚述 王 将他吞灭,末后 是 巴比伦 王 尼布甲尼撒 将他的骨头折断。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, '所以 万军 之耶和华─以色列的 神 如此 说:「我 必罚 巴比伦 王 和 他的地,像 我从前罚 亚述 王一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, '我必再领 以色列 回 他的草场,他必在迦密 和巴珊 吃草, 又在以法莲 山上 和基列 境内得以饱足。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, '耶和华 说:「当那 日子、那 时候,虽寻 以色列 的罪孽,一无所有;虽寻 犹大 的罪恶,也无 所见;因为 我所 留下的人,我必赦免。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, '耶和华 说:上去 攻击 米拉大翁 之地,又 攻击 比割 的居民。要追 杀 灭尽,照我一切 所 吩咐你 的去行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, '境内 有打仗 和大 毁灭 的响声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, '全 地 的大锤 何竟 砍断 破坏?巴比伦 在列国中 何竟 荒凉? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, '巴比伦哪,我为你 设下网罗,你 不 知不觉 被缠住。你被寻著,也 被捉住;因为 你与耶和华 争竞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, '耶和华 已经开 了 武库,拿出 他恼恨的 兵器;因为 主─万军 之耶和华 在迦勒底人 之地 有 当做的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, '你们要从极远的边界 来 攻击她,开  她的仓廪,将她堆 如 高堆,毁灭净尽, 丝毫不 留。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, '要杀 他的一切 牛犊,使他们下去 遭遇杀戮。他们 有祸了,因为 追讨 他们的日子 已经来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, '(有从巴比伦 之地 逃避 出来的人,在锡安 扬声 报告 耶和华─我们的 神 报仇,就是为他的殿 报仇。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, '「招集 一切 弓箭手 来攻击 巴比伦。要在 巴比伦四围 安营,不要 容 一人逃脱,照著她所做的 报应 她;她怎样 待人,也要怎样待 她,因为 她向 耶和华─ 以色列 的圣者 发了狂傲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, '所以 她的少年人 必仆倒 在街上。当那 日,一切 兵 丁 必默默无声。这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, '主─万军 之耶和华 说: 你这狂傲的啊,我与你反对,因为 我追讨你 的日子 已经来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, '狂傲 的必绊跌 仆倒,无人 扶起。我也必使火 在他的城邑中 著起来,将他四围 所有的 尽行烧灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, '万军 之耶和华 如此 说:「以色列 人 和犹大 人 一同 受欺压;凡 掳掠他们的 都紧紧抓住 他们,不肯 释放。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, '他们的救赎主 大有能力,万军 之耶和华 是他的名。他必 伸清 他们的冤,好 使 全地 得平安,并搅扰 巴比伦 的居民。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, '耶和华 说:有刀剑 临到 迦勒底人 和 巴比伦 的居民,并 她的首领 与 智慧人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, '有刀剑 临到 矜夸的人,他们就成为愚昧;有刀剑 临到 她的勇士,他们就惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, '有刀剑 临到 他的马匹、 车辆,和 其 中 杂族的人民;他们必 像妇女一样。有刀剑 临到 她的宝物,就被抢夺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, '有干旱 临到 她的众水,就必干涸;因为 这是 有雕刻偶像 之地,人因偶像 而颠狂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, '所以 旷野的走兽 和 豺狼 必住在那里,鸵鸟 也住 在其中, 永 无 人烟,世世 代代 无人 居住。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, '耶和华 说:「必无 人 住 在那里,也无 人 在其中 寄居,要像我 倾覆 复 所多玛、 蛾摩拉,和 邻近的城邑一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, '看哪,有一种民 从北方 而来,并有一大 国 和许多 君王 被激动,从地 极来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, '他们 拿 弓 和枪,性情残忍,不 施怜悯;他们的声音 像海浪 匉訇。巴比伦城(原文是女子)啊,他们骑 马,都摆队伍 如上战 场 的人,要攻击你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, '巴比伦 王 听见 他们的风声,手 就发软,痛苦 将他抓住,疼痛 仿佛产难的妇人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, '「 仇敌必像狮子 从约旦河 边的丛林 上来,攻击 坚固的 居所。 转眼之间,我要使他们逃跑,离开 这地。谁 蒙拣选,我就派 谁治理这地。 谁 能比我呢?谁 能给我定规日期呢?有何 牧人 能 在我面前 站立得住呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, ' 你们要听 耶和华 攻击 巴比伦 所 说 的谋略 和他攻击 迦勒底人 之地 所 定 的旨意。仇敌定要 将他们群众 微弱的 拉去,定要 使他们 的居所 荒凉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, '因巴比伦 被取 的声音,地 就震动,人在列邦 都听见 呼喊的声音。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, '耶和华 如此 说:我 必使毁灭的 风 刮起,攻击 巴比伦 和 住在 立加米的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, '我要打发 外邦人 来到巴比伦,簸扬她,使 她的地 空虚。在她遭祸 的日子, 他们要 周围 攻击她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, '拉弓的,要向 拉弓的 和 贯甲 挺身的 射 箭。不要 怜惜 她的少年人;要灭尽 她的全 军。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, '他们必在迦勒底人 之地 被杀 仆倒,在巴比伦的街上 被刺透。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, ' 以色列 和犹大 虽然 境内 充满 违背以色列 圣者 的罪,却没有被他的 神─万军 之耶和华 丢弃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, '你们要从巴比伦 中 逃奔,各 救 自己的性命!不要 陷在她的罪孽中 一同灭亡;因为 这是 耶和华 报仇 的时候,他必向巴比伦 施行 报应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, '巴比伦 素来是耶和华 手中 的金 杯,使 天下 沉醉;万国 喝了 她的酒 就 颠狂了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, '巴比伦 忽然 倾覆 复 毁坏;要为她 哀号;为止她的疼痛,拿 乳香 或者 可以治好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, '我们想医治 巴比伦,她却没有 治好。离开 她吧!我们各人 归 回本国;因为 她受的审判 通 于  上天,达 到 穹苍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, '耶和华 已经彰显 我们的公义。来吧!我们可以在锡安 报告 耶和华─我们 神 的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, '你们要磨尖了 箭头,抓住 盾牌。 耶和华 定意 攻击 巴比伦,将她毁灭,所以激动了 玛代 君王 的心;因 这是 耶和华 报仇,就是为自己的殿 报仇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, '你们要竖立 大旗,攻击 巴比伦 的城墙;要坚固 瞭 了望台,派定 守望的 设下 埋伏;因为 耶和华 指著 巴比伦 居民 所 说的话、所 定的意,他 已经作成。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, '住 在 众 水 之上多有 财宝的啊,你的结局 到了!你贪婪 之量满了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, '万军 之耶和华 指著自己 起誓 说:我必 使敌人 充满你,像蚂蚱一样;他们必呐喊 攻击你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, '耶和华 用能力 创造 大地,用智慧 建立 世界,用聪明 铺张 穹苍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, '他一发 声,空中 便有多 水激动;他使云雾 从地 极 上腾。他造 电 随雨而闪,从他府库中 带出 风来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, '各 人 都成了畜类,毫无知识。各 银匠 都因他的偶像 羞愧;他所铸的偶像 本是 虚假的,其中 并无 气息, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, '都是 虚无的,是迷惑人 的工作,到追讨 的时候,必被除灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, '雅各 的分 不 像这些,因 他是 造作 万有的主;以色列 也是他产业 的支派。万军 之耶和华 是他的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, '你是 我 争战 的斧子 和打仗 的兵器;我要用你 打碎 列国,用你 毁灭 列邦; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, '用你 打碎 马 和骑马的;用你 打碎 战 车 和坐在其上的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, '用你 打碎 男人 和女人;用你 打碎 老年人 和少年人;用你 打碎 壮丁 和处女; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, '用你 打碎 牧人 和他的群畜;用你 打碎 农夫 和他一对牛;用你 打碎 省长 和副省长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, '耶和华 说:「我必在你们眼前 报复 巴比伦人 和迦勒底 居民 在锡安 所 行 的 诸 恶。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, '耶和华 说:你这行毁灭 的山哪,就是毁灭 天下的山,我 与你反对。我必向你 伸 手,将你从山岩 滚下去,使你成为 烧毁 的山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, '人必不 从你那里 取 石头 为房角石,也不取石头 为根基石; 你必 永远 荒凉。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, '要在境内 竖立 大旗,在各国中 吹 角,使列国 预备 攻击巴比伦,将亚拉腊、米尼、亚实基拿 各国 招来 攻击她;又派 军长 来攻击她,使马匹 上来 如蚂蚱, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, '使列国 和 玛代 君王,与 省长 和 副省长,并 他们所管 全 地之人,都预备 攻击她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, '地 必震动 而瘠苦;因 耶和华 向 巴比伦 所定的旨意 成立了,使 巴比伦 之地 荒凉,无人 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, '巴比伦 的勇士 止息 争战 ,藏 在坚垒之中。他们的勇力 衰尽,好像 妇女一样。巴比伦的住处 有火著起,门闩 都折断了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, '跑报的 要彼此 相遇,送信的 要互相 迎接,报告 巴比伦 王 说:城 的四方 被攻取了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, '渡口 被占据了, 苇塘 被火 烧了,兵 丁 也惊慌了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, ' 万军 之耶和华─以色列的 神 如此 说:巴比伦城(原文作女子)好像踹 谷的 禾场;再 过片时,收割 她 的时候 就到了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, '以色列人说:巴比伦 王 尼布甲尼撒 吞灭我,压碎我,使我成为 空虚的 器皿。他像大鱼 将我吞下,用我的美物 充满 他的肚腹,又将我赶出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, '锡安 的居民 要说:巴比伦 以强暴待我,损害我的身体,愿 这罪归给她。耶路撒冷人 要说:愿 流我们血 的罪归到 迦勒底 的居民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, '所以,耶和华 如此 说:我 必为 你 伸冤,为 你 报仇;我必使 巴比伦的海 枯竭,使 她的泉源 干涸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, '巴比伦 必成为 乱堆,为野狗 的住处,令人惊骇、嗤笑,并且无人 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, '他们要像少壮狮子 咆哮,像小 狮子 吼叫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, '他们火热的时候,我必为他们 设摆 酒席,使他们沉醉,好叫 他们快乐,睡了 长 觉,永不 醒起。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, '我必使他们像羊羔、像公绵羊 和 公山羊 下到 宰杀之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, '示沙克(就是巴比伦)何竟 被攻取, 天下 所称赞 的何竟被占据?巴比伦 在列国中 何竟 变 为荒场? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, '海水 涨起,漫过 巴比伦;她被许多 海浪 遮盖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, '她的城邑 变为 荒场、旱 地、沙漠,无 人 居住,无 人 经过 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, '我必刑罚 巴比伦的 彼勒,使他吐 出 所吞的。万民 必不 再 流归 他那里;巴比伦 的城墙 也 必坍塌了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, '我的民哪,你们要从其中 出去!各人 拯救 自己,躲避耶和华 的烈 怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, '你们不要 心 惊胆怯,也不要因境内 所听见 的风声 惧怕;因为这年 有风声 传来;那 年 也有风声传来,境内 有强暴的事,官长 攻击 官长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, ' 日子 将到,我必刑罚 巴比伦 雕刻的偶像。她全 地 必然抱愧;她 被杀的人 必在其中 仆倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, '那时,天 地 和 其中 所有的,必因 巴比伦 欢呼,因为 行毁灭的 要从北方 来到 她那里。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, '巴比伦 怎样 使以色列 被杀的人 仆倒,照样她 全 地 被杀的人 也 必在巴比伦 仆倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, '你们躲避 刀剑 的要快走,不要 站住!要在远方 记念 耶和华, 心中 追想 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, '我们听见 辱骂 就 蒙羞,满 面 惭愧,因为 外邦人 进 入 耶和华 殿 的圣所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, ' 耶和华 说: 日子 将到,我必刑罚 巴比伦雕刻的偶像,通 国 受伤的人 必唉哼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, '巴比伦 虽 升到 天上,虽 使她坚固的 高处 更坚固,还有行毁灭的 从我这里 到 她那里。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, '有哀号 的声音 从巴比伦出来;有大 毁灭 的响声从迦勒底人 之地发出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, '因 耶和华 使 巴比伦 变为荒场,使其中的 大 声 灭绝。仇敌仿佛众 水,波浪 匉訇,响声 已经发出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, '这是 行毁灭的 临 到 巴比伦。巴比伦的勇士 被捉住,他们的弓 折断了;因为 耶和华 是施行报应的 神,必定 施行报应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, '君王─名 为万军 之耶和华 的说:我必使巴比伦的首领、智慧人、省长、副省长,和勇士 都沉醉,使他们睡了 长 觉,永不 醒起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, '万军 之耶和华 如此 说:巴比伦 宽阔的 城墙 必全然 倾倒;他高大的 城门 必被火 焚烧。众民 所劳碌的 必致 虚空;列国 所劳碌的 被火焚烧,他们都必困乏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, '犹大 王 西底家 在位 第四 年,上巴比伦 去的时候,玛西雅 的孙子、尼利亚 的儿子 西莱雅 与王同去(西莱雅 是王宫 的大臣),先知 耶利米 有话 吩咐 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, '耶利米 将 一切 要临 到 巴比伦 的灾祸,就是 论 到 巴比伦 的一切 话,写 在 书上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, '耶利米 对 西莱雅 说:「你到了 巴比伦 务要 念 这 书上的话; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, '又说:『耶和华啊,你 曾论 到 这 地方说:要剪除,甚至连人 带 牲畜 没 有 在这里 居住的,必 永远 荒凉。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, ' 你念 完了 这 书,就把一块石头 拴 在书上,扔 在 幼发拉底河 中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, '说:『巴比伦 因耶和华 所 要降 与她 的灾祸,必如此 沉下去,不 再兴起,人民也必困乏。』」耶利米 的话 到 此为止。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, '西底家 登基 的时候年 二十 一 岁,在耶路撒冷 作王 十 一 年。他母亲 名 叫哈慕他,是立拿人 耶利米 的女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, '西底家行 耶和华 眼中 看为恶的事,是照约雅敬 一切 所 行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, '因 此 耶和华 的怒气 在耶路撒冷 和犹大 发作,以致 将人民 从 自己的面前 赶出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, '西底家 背叛 巴比伦 王。 他作王 第九 年 十 月 初 十日,巴比伦 王 尼布甲尼撒率领 全 军 来 攻击 耶路撒冷,对城 安营,四围 筑 垒 攻城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, '于 是城 被 围困 直到 西底家 王 十一 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, '四 月 初 九日,城里 有大 饥荒,甚至百姓 都没 有 粮食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, '城 被攻破,一切 兵 丁 就在夜间 从靠近 王 园 两城 中间 的门,出 城 逃跑;迦勒底人 正在四围 攻 城。他们就往 亚拉巴 逃去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, '迦勒底 的军队 追 赶 西底家 王,在耶利哥 的平原 追上 他。他的全 军 都离开 他 四散了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, '迦勒底人就拿住 王,带 他 到 在哈马 地 利比拉 的巴比伦 王那里;巴比伦王便 审判 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, '巴比伦 王 在西底家 眼前 杀了 他的众子,又 在利比拉 杀了 犹大 的一切 首领, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, ' 并且剜了 西底家 的眼睛,用铜炼 链 𫔀 锁著他,带 到巴比伦去,将他囚 在监 里,直到 他死 的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, ' 巴比伦 王 尼布甲尼撒 十 九 年 五 月 初 十日,在巴比伦 王 面前 侍立 的护卫 长 尼布撒拉旦 进入 耶路撒冷, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, '用火 焚烧 耶和华 的殿 和 王 宫,又 焚烧 耶路撒冷的 房屋,就是 各 大 户家的房屋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, ' 跟从 护卫 长 迦勒底 的全 军 就拆毁 耶路撒冷 四围的 城墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, '那时护卫 长 尼布撒拉旦 将 民 中最穷的 和 城里 所剩下的 百姓,并 已经 投降 巴比伦 王 的人,以及 大众 所剩下的人,都掳去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, '但护卫 长 尼布撒拉旦 留下 些民中 最穷的,使他们修理葡萄园,耕种田地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, ' 耶和华 殿 的 铜 柱 并 殿内 的 盆座 和 铜 海,迦勒底人 都打碎了,将 那铜 运 到巴比伦去了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, '又带去 锅、 铲子、 蜡剪、 盘子、 调羹,并 所 用 的一切 铜 器、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, ' 杯、 火鼎、 碗、 盆、 灯台、 调羹、 爵,无论 金的 银的,护卫 长 也都带去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, '所罗门 为耶和华 殿 所 造 的两 根铜柱、一 个铜海,并 座 下 的十 二 只铜 牛,这 一切 的铜 多得无法 可 称。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, '这 一 根柱子 高 十 八 肘,厚 四 指,是空的,围 十二 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, '柱上 有铜 顶, 高 五 肘; 铜顶 的周围 有网子 和石榴,都是 铜的。那一 根柱子 照此一样,也有石榴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, '柱子四面 有 九十 六 个石榴,在 网子 周围,共 有一百 石榴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, '护卫 长 拿住 大 祭司 西莱雅、 副 祭司 西番亚,和 三 个把 门的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, '又从 城 中拿住 一个 管理 兵 丁的官(或译:太监),并在城里 所 遇 常见 王 面 的七个 人 和 检点 国民 军 长 的书记,以及城 里 所遇见 的国 民 六十 个人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, '护卫 长 尼布撒拉旦 将这些人 带 到 利比拉 的巴比伦 王那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, '巴比伦 王 就把他们 击 杀 在哈马 地 的利比拉。这样,犹大人 被掳 去离开  本地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, '尼布甲尼撒 所 掳 的民 数记在下面:在他第七 年 掳去犹大人 三 千 零二十 三名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, '尼布甲尼撒 十 八 年 从耶路撒冷 掳去 八 百 三十 二 人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, '尼布甲尼撒 二十 三 年,护卫 长 尼布撒拉旦 掳去 犹大人 七 百 四十 五 名;共有 四 千 六 百 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, ' 犹大 王 约雅斤 被掳 后三十 七 年,巴比伦 王 以未米罗达 元 年 十 二 月 二十 五日,使 犹大 王 约雅斤 抬 头,提他 出 监, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, '又对他 说 恩言,使 他的位 高过 与他 一同在巴比伦 众王 的位, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, '给他脱了 囚 服。他终 身 在巴比伦王面前 吃 饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, ' 巴比伦 王 赐 他 所需用 的食物,日 日 赐他一分,终 身是这样,直到 他死 的日子。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, '先前满有 人民 的城,现在何竟 独 坐!先前在列国中 为大的,现在竟 如寡妇;先前在诸省中 为王后的,现在成为 进贡的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, '她夜间 痛 哭,泪 流满 腮;在一切 所亲爱的 中间没有 一个安慰 她的。她的朋友 都 以诡诈 待她,成为 她的 仇敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, '犹大 因遭遇苦难,又因多 服劳苦 就迁到外邦。她 住 在列国中,寻 不著 安息;追逼她的 都 在 狭窄之地 将她追上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, '锡安 的路径 因无人 来 守圣节 就悲伤; 她的城门 凄凉;她的祭司 叹息;她的处女 受艰难,自己 也愁苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, '她的敌人 为 首;她的仇敌 亨通;因 耶和华 为 她许多的 罪过 使她受苦;她的孩童 被敌人 掳去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, ' 锡安城(原文是女子;下同)的威荣 全都 失去。她的首领 像 找 不著 草场 的鹿;在 追赶的人 前 无 力 行走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, '耶路撒冷 在困苦 窘迫 之时,就追想 古 时 一切的 乐境。她百姓 落 在敌人 手中,无人 救济;敌人 看见,就因 她的荒凉 嗤笑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, '耶路撒冷 大大 犯罪,所以 成为 不洁之物;素来 尊敬她的, 见 她赤露 就都藐视她;她自己 也 叹息 退 后。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, '她的污秽 是在衣襟上;她不 思想 自己的结局,所以非常地 败落,无人 安慰 她。她说:耶和华啊,求你看 我的苦难,因为 仇敌 夸大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, '敌人 伸 手,夺取 她的美物; 她眼见 外邦人 进入 她的圣所─论这外邦人,你曾吩咐 不可 入 你的 会中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, '她的民 都 叹息,寻求 食物;他们用 美物 换粮食,要救 性命。他们说:耶和华啊,求你观 看,因为 我甚是 卑贱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, '你们一切 过 路的人哪,这事你们 不介意吗?你们要观 看:有 像这 临到 我 的痛苦没有─就是 耶和华 在他发烈 怒 的日子 使我所受的 苦? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, '他从高天 使 火 进入我的骨头,克 剋制了我;他铺下 网罗,绊我的脚,使我转 回;他使 我终 日 凄凉 发昏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, '我罪过 的轭 是他手 所绑的,犹如轭绳缚 在 我颈项上;他使我的力量 衰败。主 将我交 在 我所不 能 敌挡的 人手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, '主 轻弃 我中间 的一切 勇士,招聚多人(原文是大会)攻击我,要压碎 我的少年人。主 将犹大 居民 踹下,像在酒醡中一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, '我 因 这些事 哭泣;我眼 泪 汪汪;因为 那当安慰我、救 我性命的,离我 甚远。我的儿女 孤苦,因为 仇敌 得了胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, '锡安 举 手,无人 安慰。耶和华 论雅各 已经出令,使四围的人 作他仇敌;耶路撒冷 在他们中间 像 不洁之物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, '耶和华 是 公义的!他这样待我,是因 我违背 他的命令。众 民哪,请 听我的话,看 我的痛苦;我的处女 和少年人 都被掳去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, '我招呼 我所亲爱的,他们 却愚弄我。我的祭司 和长老 正寻求 食物、救 性命 的时候,就在城中 绝气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, '耶和华啊,求你观看,因为 我在 急难中。我心肠 扰乱;我心 在我里面 翻转,因 我大大 悖逆。在外,刀剑 使人丧子;在家,犹如死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, '听见 我 叹息的有人;安慰 我的 却无人!我的仇敌 都 听见 我所遭的患难;因 你 做这事,他们都喜乐。你必使 你报告 的日子 来到,他们就 像我一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, '愿 他们的恶行 都 呈在 你面前;你怎样因 我的一切 罪过 待 我,求你照样 待 他们;因 我叹息 甚多,心中 发昏。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, '主 何竟 发怒,使黑云遮蔽 锡安 城!他将以色列 的华美 从天 扔 在地上;在他发怒 的日子 并不 记念 自己的脚凳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, '主 吞灭 雅各 一切的 住处,并不 顾惜。他发怒 倾覆 复 犹大 民 的保障,使这保障坍倒 在地;他辱没 这国 和其中的首领。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, '他发烈 怒,把以色列 的角 全然 砍断,在仇敌 面前 收 回 右手。他像火焰 四围 吞灭,将雅各 烧毁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, '他张 弓 好像仇敌;他站著 举起右手,如同敌人 将悦人 眼目的,尽行 杀戮。在锡安 百姓 的帐棚上 倒出 他的忿怒,像火一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, '主 如仇敌 吞灭 以色列 和 锡安的一切 宫殿,拆毁 百姓的保障;在犹大 民中 加增 悲伤 哭号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, '他强取 自己的帐幕,好像是园中的窝棚,毁坏 他的聚会之处。耶和华 使圣节 和安息日 在锡安 都被忘记,又在怒气 的愤恨中 藐视 君王 和祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, '耶和华 丢弃 自己的祭坛,憎恶 自己的圣所,将宫殿 的墙垣 交付 仇敌。他们在耶和华 的殿中 喧嚷,像在圣会 之日一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, '耶和华 定意 拆毁 锡安 的城墙;他拉了 准绳,不 将手 收回,定要毁灭。他使外郭 和城墙 都悲哀,一同 衰败。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, '锡安 的门 都陷入 地内;主将她的门闩 毁坏,折断。她的君王 和首领 落在没有 律法 的列国中;她的先知 不 得见 耶和华的 异象。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, '锡安 城 的长老 坐 在地上 默默无声;他们扬起 尘土 落在 头上,腰束 麻布;耶路撒冷 的处女 垂 头 至地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, '我眼 中流泪,以致失明;我的心肠 扰乱,肝胆 涂 地,都因 我众民 遭毁灭,又因孩童 和吃奶的 在城内 街上 发昏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, '那时,他们在城内 街上 发昏,好像受伤的,在 母亲的 怀里,将要丧 命;对母亲 说:谷、酒 在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, '耶路撒冷 的民哪,我可用什么 向你证明呢?我可用什么 与你 相比呢?锡安 的民哪,我可拿什么 和你 比较,好安慰你呢?因为 你的裂口 大 如海,谁 能医治 你呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, '你的先知 为你 见 虚假 和愚昧的异象,并没有 显露 你的罪孽,使你被掳的 归回;却为你 见 虚假的 默示 和使你被赶出本境的缘故。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, '凡 过 路 的都向你 拍 掌。他们向 耶路撒冷 城 嗤笑,摇 头,说:难道人所 称为 全 美的,称为全 地 所喜悦的,就是这 城吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, '你的仇敌 都 向你 大大张 口;他们嗤笑,又切 齿 说:我们吞灭她。这 真是 我们所盼望的 日子 临到了!我们亲眼看见了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, '耶和华 成就了 他所 定的,应验了 他古 时 所 命定的。他倾覆 复了,并不 顾惜,使你的仇敌 向你 夸耀;使你敌人 的角 也被高举。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, '锡安民的心 哀求 主。锡安 的城墙啊,愿 你 流 泪 如河,昼 夜 不 息;愿 你眼中 的瞳人 泪流不 止。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, '夜间,每逢交 更 的时候要起来 呼喊,在主 面 前 倾 心 如水。你的孩童 在各 市口 上受饿 发昏;你要为 他们的性命 向主 举 手祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, '耶和华啊,求你观看!见 你向谁 这样 行?妇人 岂可 吃 自己所生育 手里所摇弄的 婴孩吗?祭司 和先知 岂可 在主 的圣所中 被杀戮吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, '少年人 和老年人 都在街上 躺卧;我的处女 和壮丁 都倒 在刀下;你发怒 的日子 杀死他们。你杀了,并不 顾惜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, '你招聚 四围 惊吓我的,像在大会 的日子招聚人一样。耶和华 发怒 的日子,无人 逃脱,无人存留。我所 摇弄 所养育的婴孩,仇敌 都杀净了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, '我 是因耶和华忿怒 的杖,遭遇 困苦 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, '他引导 我,使我行在 黑暗中,不 行在光明里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, '他真是 终 日 再三 反 手 攻击我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, '他使我的皮 肉 枯干;他折断(或译:压伤)我的骨头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, '他筑垒 攻击我,用苦楚(原文是苦胆)和艰难 围困我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, '他使我住 在幽暗之处,像死了 许久 的人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, '他用篱笆 围住我,使我不能 出去;他使 我的铜炼 链 𫔀 沉重。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, ' 我哀号 求救;他使我的祷告 不得上达。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, '他用凿过的石头 挡住 我的道;他使我的路 弯曲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, '他 向我 如熊 埋伏,如狮子 在隐密处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, '他使我转离 正路,将我撕碎,使我 凄凉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, '他张 弓 将我当作 箭 靶子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, '他把箭袋 中的箭 射入 我的肺腑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, '我成了 众 民 的笑话;他们终 日 以我为歌曲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, '他用苦楚 充满我,使我饱用 茵𫈟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, '他又用沙石 碜断 我的牙,用灰尘 将我蒙蔽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, '你使 我 远离 平安,我忘记 好处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, '我就说:我的力量 衰败;我在耶和华那里毫无 指望! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, '耶和华啊,求你记念 我如茵𫈟 和苦胆 的困苦 窘迫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, '我心 想念这些,就在里面 忧闷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, '我想起 这事, 心里 就有 指望。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, '我们不致 消灭,是出于  耶和华 诸般的慈爱;是因 他的怜悯 不致 断绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, '每早晨,这都是新的;你的诚实 极其广大! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, '我心里 说:耶和华 是我的分,因此,我要仰望 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, '凡等候耶和华,心里 寻求他的,耶和华 必施恩给他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, '人仰望 耶和华,静默等候 他的救恩,这原是好的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, '人 在幼年 负 轭,这原是好的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, '他当独 坐 无言,因为 这是耶和华加 在他身上的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, '他当口 贴 尘埃,或者 有 指望。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, '他当由人 打 他的腮颊,要满受 凌辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, '因为 主 必不 永远 丢弃人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, '主虽 使人忧愁,还要照他诸般的 慈爱 发怜悯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, '因 他并不 甘心 使人受苦,使人 忧愁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, '人将世上 被囚的踹(原文是压)在脚 下, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, '或在至高者 面 前 屈枉 人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, '或在人 的讼事上 颠倒是非,这都是主 看 不上的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, '除非 主 命定,谁能 说成 就成呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, '祸 福 不 都出于  至高者 的口吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, '活 人 因 自己的 罪受罚,为何 发怨言呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, '我们当深深考 察 自己的行为,再归向 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, '我们当诚心 向 天上 的神 举 手祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, '我们 犯罪 背逆,你 并不 赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, '你自被怒气 遮蔽,追赶我们;你施行杀戮,并不 顾惜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, '你以黑云 遮蔽 自己,以致祷告 不得透入。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, '你使我们 在万民 中 成为污秽 和渣滓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, '我们的仇敌 都 向我们 大大张 口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, '恐惧 和陷坑,残害 和毁灭,都临近 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, '因 我众民 遭的毁灭,我就眼泪 下流 如河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, '我的眼 多多流泪,总不 止息, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, '直等 耶和华 垂顾,从天 观看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, '因我本城 的众 民,我的眼,使 我的心 伤痛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, '无故 与我为仇的 追 逼我,像追雀鸟一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, '他们使我的命 在牢狱中 断绝,并将一块石头 抛在 我身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, '众水 流过 我头,我说:我命断绝了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, '耶和华啊,我从深 牢 中求告 你的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, '你曾听见 我的声音;我求你解救,你不要 掩 耳不听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, '我求告你 的日子,你临近我,说:不要 惧怕! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, '主啊,你伸明了 我 的冤;你救赎了 我的命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, '耶和华啊,你见了 我受的委屈;求你为我伸 冤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, '他们 仇恨我, 谋害 我,你都看见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, '耶和华啊,你听见 他们辱骂我的话,知道他们向我所设的 计, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, '并那些起来攻击我的人 口中所说的话,以及终 日 向我 所设的计谋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, '求你观看,他们坐下,起来,都以我 为歌曲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, '耶和华啊,你要按著 他们手 所做的 向他们 施行 报应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, '你要使 他们 心里 刚硬,使你的咒诅 临到他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, '你要发怒 追赶他们,从耶和华 的天 下 除灭他们。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, '黄金 何其 失光!纯 金 何其变色!圣所 的石头 倒在 各 市 口上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, '锡安 宝贵 的众子 好比 精金,现在何竟 算为 窑匠 手 所做的 瓦 瓶? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, '野狗 尚且 把 奶 乳哺 其子,我民 的妇人 倒成为残忍,好像 旷野 的鸵鸟一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, '吃奶孩子 的舌头 因干渴 贴 住 上膛;孩童 求 饼,无人 擘 给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, '素来吃 美好食物的,现今在街上 变为孤寒;素来卧 朱红褥子的,现今躺卧 粪堆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, '都因我众民 的罪孽 比所多玛 的罪 还大;所多玛虽然无人 加 手 于 她,还是转眼之间 被倾覆 复。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, '锡安的贵胄 素来比雪 纯净,比奶 更白;他们的身体 比红宝玉(或译:珊瑚)更红,像光润 的蓝宝石一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, '现在他们的面貌 比煤炭 更黑,以致在街上 无人 认识;他们的皮肤 紧贴 骨头,枯干 如同 槁木。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, '饿 死的 不如 被刀 杀的,因为 这是 缺了田间 的土产,就身体衰弱,渐渐消灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, '慈悲的 妇人,当我众民 被毁灭的时候,亲手 煮 自己的儿女 作为 食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, '耶和华 发怒 成就他所定的,倒出 他的烈 怒;在锡安 使火 著起,烧毁 锡安的根基。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, '地上 的君王 和世上 的居民 都 不 信 敌人 和仇敌 能进 耶路撒冷 的城门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, '这都因她先知 的罪恶 和祭司 的罪孽;他们在城中 流了 义人 的血。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, '他们在街上 如瞎子 乱走,又被血 玷污,以致人不 能 摸 他们的衣服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, '人向他们 喊著说: 不洁净的,躲开 ,躲开 !不要 挨近我! 他们逃走 飘流的时候,列国中 有人说:他们不可 仍在 这里寄居。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, '耶和华 发怒,将他们分散,不 再 眷顾他们;人不 重看 祭司,也不 厚待 长老。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, '我们仰望 人来帮助,以致 眼目 失明,还是枉然;我们所盼望的,竟盼望 一个不能 救人 的国! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, '仇敌追赶 我们的脚步像打猎的,以致我们不敢在自己的街上 行走。我们的结局 临近;我们的日子 满足; 我们的结局 来到了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, '追赶我们的 比空中 的鹰 更快;他们在山 上 追逼我们,在旷野 埋伏,等候我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, '耶和华 的受膏者 好比我们鼻中 的气,在他们的坑中 被捉住;我们曾论到他 说:我们必在他荫下,在列国中 存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, '住 乌斯 地 的以东 民哪,只管欢喜 快乐;苦杯 也 必传 到你那里;你必喝醉,以致露体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, '锡安 的民哪,你罪孽的刑罚 受足了,耶和华 必不 使你再 被掳去。以东 的民哪,他必追讨 你的罪孽,显露 你的罪恶。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, '耶和华啊,求你记念 我们所遭遇的事,观 看 我们所受的凌辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, '我们的产业 归 与外邦人;我们的房屋 归与外路人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, '我们是 无父的 孤儿;我们的母亲 好像寡妇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, '我们出钱 才得水 喝;我们的柴 是人卖 给我们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, '追赶我们的,到了我们的颈项 上;我们疲乏 不得 歇息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, '我们投降 埃及人 和亚述人,为要得粮 吃饱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, '我们列祖 犯罪,而今不在了;我们 担当 他们的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, '奴仆 辖制 我们,无人 救 我们脱离他们的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, '因为 旷野 的刀剑,我们冒著险 才得 粮食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, '因 饥饿 燥热,我们的皮肤 就黑 如炉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, '敌人在锡安 玷污 妇人,在犹大 的城邑 玷污处女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, '他们吊起 首领 的手,也不 尊敬 老人 的面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, '少年人 扛 磨石,孩童 背木柴,都绊跌了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, '老年人 在城门口 断绝;少年人 不再作乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, '我们心中 的快乐 止息,跳舞 变为 悲哀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, '冠冕 从我们的头 上落下; 我们犯罪了,我们 有祸了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, ' 这些事 我们心里 发昏, 我们的眼睛 昏花。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, ' 锡安 山荒凉,野狗(或译:狐狸)行在 其上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, '耶和华啊,你 存 到永远;你的宝座 存到万代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, '你为何 永远 忘记我们?为何许久 离弃我们? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, '耶和华啊,求你使我们向你 回转,我们便得回转。求你复新 我们的日子,像古时一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, '你竟 全然 弃绝我们,向我们 大 发烈怒?    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, '当 三十 年 四 月 初五日,以西结(原文是我)在 迦巴鲁 河 边被掳 的人中,天 就开 了,得见 神 的异象。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, '正是 约雅斤 王 被掳 去第五 年 四月 初五日, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, '在迦勒底人 之地、 迦巴鲁 河边,耶和华 的话 特特 临 到 布西 的儿子 祭司 以西结;耶和华的灵(原文是手)降 在他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, '我观看,见 狂风 从 北方 刮来,随著有一朵包括闪烁 火 的大 云,周围 有光辉;从其中 的火 内 发出好像光耀 的精金; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, '又从其中 显出四 个活物 的形像来。他们的形状 是这样:有 人 的形像, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, '各 有四个 脸面, 四个 翅膀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, '他们的腿 是直 的,脚 掌 好像牛犊 之蹄,都灿烂如 光明 的铜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, '在 四 面 的翅膀 以下 有人 的手。这四个 活物的脸 和翅膀乃是这样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, '翅膀 彼此 相接,行走 并不 转身,俱各 直 往 前 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, '至于 脸 的形像: 前面各有人 的脸, 右 面各有狮子 的脸, 左面 各有牛 的脸, 后面各有鹰 的脸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, ' 各展开  上边 的两个 翅膀 相接,各 以下边的 两个 翅膀遮 体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, '他们俱各 直 往 前 行。 灵 往 哪里 去,他们就往那里 去,行走 并不 转身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, '至于 四活物 的形像,就如烧 著火 炭 的形状,又如火把 的形状。火 在四活物 中间 上去下来,这火 有光辉,从 火 中发出 闪电。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, '这活物 往来 奔走, 好像电光一闪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, '我正观看 活物的时候,见 活物的 脸 旁 各有一 轮 在地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, '轮 的形状和颜色(原文是作法)好像水苍玉。四 轮都是一个 样式,形状 和作法 好像 轮 中 套轮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, '轮行走的时候,向 四 方 都能直行, 并不 掉转。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, '至于 轮辋,高 而可畏;四 个轮辋 周围 满 有眼睛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, '活物 行走,轮 也在旁边 行走;活物 从 地 上升,轮 也都上升。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, '灵 往 哪里 去, 活物就往那里 去;活物上升,轮 也在活物旁边 上升,因为 活物 的灵 在轮中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, '那些行走,这些也行走;那些站住,这些也站住;那些从 地 上升,轮 也在旁边 上升,因为 活物 的灵 在轮中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, '活物 的头 以上 有穹苍 的形像,看著像 可畏的 水晶,铺张 在 活物的头 以上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, '穹苍 以下,活物的翅膀 直张,彼此相对;每 活物有两个 翅膀遮体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, '活物行走的时候,我听见 翅膀 的响声,像大 水 的声音,像全能者 的声音,也像军队 哄 嚷 的声音。活物站住的时候,便将翅膀 垂下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, '在他们头 以上 的 穹苍 之上 有 声音。他们站住的时候,便将翅膀 垂下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, '在他们头 以上 的 穹苍 之上 有宝座 的形像, 仿佛蓝宝石;在 宝座 形像 以上 有 仿佛人 的形状。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, '我见 从 他腰 以上 有仿佛光耀 的精金,周围 都有火 的形状,又见 从 他腰 以下 有仿佛火 的形状,周围 也有光辉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, '下雨 的日子,云中 虹 的形状 怎样,周围 光辉 的形状 也是怎样。这就是 耶和华 荣耀 的形像。我一看见 就俯伏 在 地,又听见 一位说话 的声音。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, '他对我 说:「人 子啊,你站起来,我要和你 说话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, '他对我 说话 的时候,灵 就进 入我里面,使我站起来,我便听见 那位 对我 说话的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, '他对我 说:「人 子啊,我 差 你 往 悖逆 的国民 以色列 人那里去。他们 是悖逆 我的,他们 和他们的列祖 违背 我,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, '这众子 面无羞耻,心里刚硬。我 差 你 往他们那里去,你要对他们 说:主 耶和华 如此 说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, '他们 或 听,或 不听,( 他们 是悖逆 之家),必知道 在他们中间 有了 先知。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, '人 子啊,虽 有荆棘 和蒺藜 在你那里,你 又住 在 蝎子中间, 总不要 怕 他们,也不要 怕 他们的话;他们 虽 是悖逆 之家,还不要 怕 他们的话,也不要 因他们的脸色 惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, '他们或 听,或 不听,你只管将 我的话 告诉 他们; 他们 是极其悖逆的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, '人 子啊, 要听 我 对你 所 说的话,不 要 悖逆 像那悖逆 之家,你要开  口 吃 我 所 赐 给你的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, '我观看,见 有一只手 向我 伸出来, 手中 有一书 卷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, '他将书卷 在我面前 展开 , 内 外 都写著字,其上 所写 的有哀号、叹息、悲痛的话。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, '他对我 说:「人 子啊,要吃 你所 得的,要吃 这 书卷,好去 对 以色列 家 讲说。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, '于 是我开  口,他就使我吃 这 书卷, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, '又对我 说:「人 子啊,要吃 我 所 赐 给你 的这 书卷,充满 你的肚 腹。」我就吃了,口中 觉得其 甜 如蜜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, '他对我 说:「人 子啊,你往 以色列 家 那里去,将我的话 对他们 讲说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, ' 你 奉差遣 不是 往 那说话 深奥、言语 难懂 的民那里去,乃是往 以色列 家去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, '不是 往 那说话 深奥、言语 难懂 的多 国去,他们 的话语 是你不 懂得的。我若 差你 往他们那里去,他们 必听从 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, '以色列 家 却不 肯 听从 你,因为 他们不 肯 听从 我;原来 以色列 全 家 是 额坚 心硬的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, '看哪,我使 你的脸 硬 过 他们的脸,使 你的额 硬 过 他们的额。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, '我使 你的额 像金钢钻,比火石 更硬。他们 虽 是悖逆 之家,你不要 怕 他们,也不要 因他们的脸色 惊惶。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, '他又对我 说:「人 子啊,我对你 所 说 的一切 话,要心里 领会,耳中 听闻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, '你往 你本国 被掳 的子民 那里去,他们或 听,或 不听,你要对他们 讲说,告诉 他们 这是 主 耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, '那时,灵 将我举起,我就听见 在我身后 有震动 轰轰 的声音,说:「从耶和华 的所在 显出来的荣耀 是该称颂的!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, '我又听见那活物 翅膀 相 碰,与活物旁边 轮子 旋转震动 轰轰 的响声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, '于 是灵 将我举起,带我 而去。我心中甚苦,灵性 忿激,并且耶和华的灵(原文是手)在我身上 大有能力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, '我就来 到提勒‧亚毕,住 在迦巴鲁 河 边 被掳的人那里,到他们 所住 的地方,在 他们中间 忧忧闷闷地 坐了 七 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, '过了 七 日,耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, '「人 子啊,我立你 作以色列 家 守望的人,所以你要听 我口 中的话,替我 警戒 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, '我何时指著恶人 说:他必要 死;你若不 警戒他,也不 劝戒他,使他 离开 恶 行,拯救他的性命,这 恶人 必死 在罪孽之中;我却要向你 讨他丧命的罪(原文是血)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, '倘若 你 警戒 恶人,他仍不 转离 罪恶,也不离开 恶 行,他 必死 在罪孽之中,你 却救 自己脱离了罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, '再者,义 人何时离 义 而犯 罪,我将绊脚石 放 在他面前,他 就必死;因 你没有 警戒他,他必死 在罪中,他素来所 行 的义 不 被记念;我却要向你 讨他丧命的罪(原文是血)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, '倘若 你 警戒 义人,使他 不 犯罪,他 就不 犯罪;他因 受警戒 就必 存活,你 也救 自己脱离了罪。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, '耶和华的灵(原文是手)在那里 降 在我身上。他对我 说:「你起来 往 平原 去,我要在那里 和你 说话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, '于 是我起来 往 平原 去,不料,耶和华 的荣耀 正如我在 迦巴鲁 河 边所 见的一样,停在 那里,我就俯伏 于  地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, '灵 就进 入我里面,使 我站起来。耶和华对我 说:「你进 房屋去,将门关上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, ' 人 子啊, 人必用 绳索 捆绑 你,你就不 能出去 在他们中间来往。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, '我必使你的舌头 贴 住 上膛,以致你哑口,不 能作 责备 他们 的人;他们 原是 悖逆 之家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, '但我对你 说话的时候,必使你开  口,你就要对他们 说:『主 耶和华 如此 说。』听 的可以听,不听 的任他不听,因为 他们 是悖逆 之家。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, '「人 子啊,你 要拿 一块砖,摆 在你面前,将 一座耶路撒冷 城 画 划 在其上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, '又围 困这城,造 台 筑 垒,安 营 攻击,在四围 安设 撞锤 攻城, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, '又 要拿 个铁 鏊,放 在你 和城 的中间,作为铁 墙。你要对 面 攻击这城,使城 被困;这样,好作 以色列 家 的预兆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, '你 要向 左 侧 卧,承当 以色列 家 的罪孽;要按 你向左侧卧 的日 数, 担当 他们的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, '因为我 已将 他们作孽 的年 数定为 你 向左侧卧的日 数,就是三 百 九十 日,你要这样担当 以色列 家 的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, '再者,你满了 这些日子,还要向 右 侧 卧,担当 犹大 家 的罪孽。我给你 定规 侧卧四十 日,一日 顶一年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, '你要 露出 膀臂,面 向 被困 的耶路撒冷,说预言 攻击这城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, ' 我用 绳索 捆绑你,使你不 能辗转,直等 你满了 困 城的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, '你 要取 小麦、大麦、豆子、红豆、小米、粗麦,装 在一 个器皿中,用 以为自己 做饼;要按 你 侧 卧 的三 百 九十 日 吃这饼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, '你所 吃 的 要按分两吃,每日 二十 舍客勒,按时 而吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, '你喝 水 也要按制子,每日喝一欣 六分之一,按时 而喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, '你吃 这饼像吃大麦 饼一样,要 用 人 粪 在众人眼前 烧烤。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, '耶和华 说:「以色列 人 在我所 赶他们 到的各国中,也必这样 吃 不洁净 的食物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, '我说:「哎!主 耶和华啊, 我 素来未曾 被玷污,从幼年 到 如今 没有 吃过 自死的,或被野兽撕裂的,那可憎的 肉 也未曾 入 我的口。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, '于 是他对我 说:「看哪,我给 你 牛 粪 代替 人 粪,你要将 你的饼 烤 在其上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, '他又对我 说:「人 子啊,我 必在耶路撒冷 折断 他们的杖,就是断绝他们的粮。他们吃 饼 要按分两,忧虑而吃;喝 水 也要按制子,惊惶而喝; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, '使 他们缺 粮 缺水,彼此 惊惶,因自己的罪孽 消灭。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, '「人 子啊,你 要拿 一把快 刀,当作 剃头刀,用这刀剃 你的头 发和 你的胡须,用 天平 将须发平分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, '围困 城的日子 满了,你要将三分之一 在城 中 用火 焚烧, 将 三分之一 在城的四围 用刀 砍碎,将三分之一 任风 吹散;我也要拔 刀 追赶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, '你要从其中 取 几 根包 在衣襟里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, '再 从 这几根中取 些扔 在 火 中 焚烧,从里面 必有火 出来 烧入 以色列 全 家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, '主 耶和华 如此 说:这 就是耶路撒冷。我曾将她安置 在列邦 之中;列国 都在她的四围。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, '她行恶,违背 我的典章,过于  列国;干犯 我的律例,过于  四围的 列邦,因为 她弃掉 我的典章。至于 我的律例,她并没有 遵行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, '所以 主 耶和华 如此 说:因为 你们纷争 过于  四围的 列国,也不 遵行 我的律例,不 谨守 我的典章,并以遵从 四围 列国 的恶规 尚不满意, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, '所以 主 耶和华 如此 说:看哪, 我 与你反对,必在列国 的眼前,在你中间,施行 审判; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, '并且因 你一切 可憎的事,我要在你中间 行 我所 未曾 行的, 以后我也不 再 照著 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, ' 在你中间 父亲 要吃 儿子,儿子 要吃 父亲。我必向你 施行 审判,我必将 你所 剩下 的分散 四方(方:原文是风)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, '主 耶和华 说:「 我 指著我的永生起誓,因 你用一切 可憎的物、 可厌的事 玷污了 我的圣所,故此,我 定要 使你人数减少,我眼 必不 顾惜你,也 不 可怜你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, '你的民三分之一 必遭瘟疫 而死,在你中间 必因饥荒 消灭;三分之一 必在你四围 倒 在刀下;我必将三分之一 分散 四方(方:原文是风),并要拔 刀 追赶他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, '「我要这样成就 怒中所定的;我向他们 发的忿怒 止息了,自己就得著安慰。我在他们身上 成就 怒中所定的那时,他们就知道 我─耶和华 所说 的是出于 热心; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, '并且我必使你 在四围的 列国中,在经过 的众人 眼前,成了荒凉 和羞辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, '这样,我必以怒气 和忿怒,并烈怒 的责备,向你 施行 审判。那时,你就在四围的 列国 中成为 羞辱、讥刺、警戒、惊骇。这是我─耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, '那时,我要将 灭人、使人饥荒 的恶 箭,就是 射 去灭人的, 射 在你们身上,并要加增 你们 的饥荒,断绝 你们 所倚靠 的粮食; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, '又要使 饥荒 和恶 兽 到你那里,叫你丧子,瘟疫 和流血 的事也必盛行 在你那里;我也要使 刀剑 临到你。这是我─耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, '「人子啊,你要 面 向 以色列 的众山 说预言, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, '说:以色列 的众山哪,要听 主 耶和华 的话。主 耶和华 对大山、小冈、水沟、山谷 如此 说: 我 必使 刀剑 临到你们,也必毁灭 你们的邱坛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, '你们的祭坛 必然荒凉,你们的日像 必被打碎。我要使你们被杀的 人倒在 你们的偶像 面前; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, '我也要将 以色列 人 的尸首 放 在他们的偶像 面前,将 你们的骸骨 抛散 在你们祭坛 的四围。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, '在你们一切的 住处,城邑 要变为荒场,邱坛 必然凄凉,使 你们的祭坛 荒废,将你们的偶像 打碎。你们的日像 被砍倒,你们的工作 被毁灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, '被杀的人 必倒在 你们中间,你们就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, '你们分散 在各国的时候,我必在列邦 中使你们 有 剩下 脱离 刀剑的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, '那脱离 刀剑的人必在所 掳到 的各国 中记念 我,为 他们心中何等伤破,是因他们起淫 心,远离 我, 眼 对 偶像 行邪淫。他们因 行 一切 可憎的 恶事,必厌恶 自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, '他们必知道 我 是耶和华;我说 要使 这 灾祸 临到他们身上,并非 空话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, '「主 耶和华 如此 说:你当拍 手 顿 足,说:哀哉! 以色列 家 行这一切 可憎的 恶事, 他们必倒 在刀剑、饥荒、瘟疫之下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, '在远处的,必遭瘟疫 而死;在近处的,必倒 在刀剑之下;那存留 被围困的,必因饥荒 而死;我必这样在他们 身上成就 我怒中所定的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, '他们被杀的人 倒 在他们祭坛 四围 的偶像 中,就是 各 高 冈、各 山顶、各 青翠 树 下、各 茂密的 橡树 下,乃是 他们献 馨香 的祭牲给一切 偶像 的地方。那时,他们就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, '我必伸 手 攻击他们,使 他们的地 从旷野 到第伯拉他 一切 住处 极其荒凉,他们就知道 我 是耶和华。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, '耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, '「 人 子啊,主 耶和华 对以色列 地 如此 说:结局 到了,结局 到了 地 的四 境! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, '现在 你的结局 已经临到,我必使 我的怒气 归与你,也必按你的行为 审判 你,照 你一切 可憎的事 刑罚你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, '我眼 必不 顾惜 你,也不 可怜你,却 要按你所行的 报应 你, 照你中间 可憎的事刑罚你。你就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, '「主 耶和华 如此 说:有一灾,独有 一灾;看哪,临近了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, '结局 来了,结局 来了,向你 兴起。看哪,来到了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, '境内 的居民哪,所定的灾 临到你,时候 到了,日子 近了,乃是哄嚷 并非 在山上 欢呼的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, ' 我快 要将我的忿怒 倾在 你身上,向你 成就 我怒中所定的,按你的行为 审判你,照 你一切 可憎的事 刑罚 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, '我眼 必不 顾惜你,也不 可怜你,必按你所行的 报应 你, 照你中间 可憎的事刑罚你。你就知道 击打 你的是我 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, '「看哪,看哪,日子 快到了,所定的灾 已经发出。杖 已经开 花,骄傲 已经发芽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, '强暴 兴起,成了罚恶 的杖。以色列人,或是 他们的群众,或是 他们的财宝,无 一存留,他们中间 也没有 得尊荣的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, '时候 到了,日子 近了,买 主 不可 欢喜,卖主 不可 愁烦,因为 烈怒 已经临到 他们众 人身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, ' 卖主 虽然 存 活,却不 能归 回 再得所卖的,因为 这异象 关乎 他们众 人。谁都不得 归回,也没有 人 在他的罪孽 中坚立自己。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, '「他们已经吹 角,预备 齐全,却无一人 出 战 ,因为 我的烈怒 临到 他们众 人身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, '在外 有刀剑,在内 有瘟疫、饥荒; 在田野的,必遭刀剑 而死; 在城中的,必有饥荒、瘟疫 吞灭他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, '其中所逃脱的 就必逃脱,各人 因自己的罪孽 在 山上 发出悲声,好像谷中 的鸽子哀鸣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, '手 都 发软, 膝 弱 如水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, '要用麻布 束腰,被战 兢 所盖; 各人 脸上 羞愧, 头上 光秃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, '他们要将银子 抛 在街上,金子看 如污秽之物。当耶和华 发怒 的日子,他们的金 银 不 能 救他们,不能 使心里 知足,也不能 使肚腹 饱满,因为 这金银作了 他们罪孽 的绊脚石。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, '论到耶和华妆饰 华美的殿,他建立得 威严,他们却在其中 制造 可憎 可厌 的偶像,所以 这殿我使 他们 看如污秽之物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, '我必将这殿交付 外邦人 为掠物,交付地上 的恶人 为掳物;他们也必亵渎这殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, '我必转 脸 不顾以色列人,他们亵渎 我隐密之所,强盗 也必进去 亵渎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, '「要制造 锁链;因为 这地 遍满 流血 的罪,城邑 充满 强暴的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, '所以我必使列国 中最恶的人 来 占据 他们的房屋;我必使强暴人 的骄傲 止息,他们的圣所 都要被亵渎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, '毁灭 临近了,他们要求 平安,却无平安可得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, '灾害 加上 灾害,风声 接连 风声;他们必向先知 求 异象,但祭司 讲的律法、长老 设的谋略 都必断绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, '君 要悲哀,王 要披凄凉 为衣,国 民 的手 都发颤。我必照 他们的行为 待他们,按他们应得的 审判他们,他们就知道 我 是耶和华。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, ' 第六 年 六 月 初五日,我 坐 在家中;犹大 的众长老 坐 在我面前。在那里 主 耶和华的灵(原文是手)降 在我身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, '我观看,见 有形像 仿佛火 的形状,从他腰 以下 的形状 有火,从他腰 以上 有光辉 的形状,仿佛光耀 的精金。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, '他伸出 仿佛一只手 的样式,抓住 我的一绺 头发,灵 就将我 举 到 天 地 中间,在 神 的异象中,带 我 到 耶路撒冷 朝 北 的内 院 门口, 在那里 有触动主怒 偶像 的坐位,就是惹动忌邪的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, '谁知,在那里 有以色列 神 的荣耀,形状 与我在平原 所 见的一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, '神对我 说:「人 子啊,你 举 目 向北观看。」我就举 目 向北观看,见 祭坛 门的 北边,在门口 有这 惹忌邪的 偶像; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, '又对我 说:「人 子啊,以色列 家 所 行的,就是 在此 行 这大 可憎的事,使我远离 我的圣所,你 看见了吗?你还 要 看见 另有大 可憎的事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, '他领 我 到 院 门口。我观看,见 墙上 有个 窟窿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, '他对我 说:「人 子啊,你要 挖 墙。」我一挖 墙,见 有一 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, '他 说:「你进去,看 他们 在这里 所 行 可憎的 恶事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, '我进去 一看,谁知,在 四面 墙上 画 划著 各 样 爬物 和可憎的 走兽,并以色列 家 一切的 偶像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, '在这些像前 有以色列 家 的七十 个 长老 站立,沙番 的儿子 雅撒尼亚 也站 在其中。各人 手拿 香炉,烟 云 的香气 上腾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, '他对我 说:「人 子啊,以色列 家的 长老 暗中 在各人 画 划像 屋里 所行的,你看见了吗? 他们常说:『耶和华 看不 见 我们;耶和华 已经离弃 这地。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, '他又 说:「你还 要 看见 他们 另外行 大 可憎的事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, '他领 我 到 耶和华 殿 外院朝 北 的门口。谁知,在那里 有妇女 坐著,为 搭模斯 哭泣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, '他对我 说:「人 子啊,你看见了吗?你还 要 看见 比这 更 可憎的事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, '他又领 我 到 耶和华 殿 的内 院。谁知,在耶和华 的殿 门口、 廊子 和祭坛 中间,约有二十 五 个人 背 向 耶和华 的殿,面 向东方 拜 日头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, '他对我 说:「人子啊,你看见了吗?犹大 家 在此 行 这可憎的事 还算为小吗?他们在 这地 遍行 强暴,再三 惹我发怒,他们 手拿 枝条 举向 鼻前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, '因此,我 也 要以忿怒 行事,我眼 必不 顾惜,也不 可怜他们;他们虽向我耳中 大 声 呼求,我还是不 听。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, '他向我耳中 大声 喊叫 说:「要使那监管 这城 的人手中 各 拿灭命的 兵器 前来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, '忽然 有六个 人 从 朝 北的 上 门 而来,各人 手拿 杀人的 兵器;内中 有一 人 身穿 细麻衣,腰间 带著墨盒子。他们进来,站 在铜 祭坛 旁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, '以色列 神 的荣耀本 在 基路伯上,现今从那里 升 到 殿 的门槛。 神将那身穿 细麻衣、 腰间 带著墨盒子 的人 召来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, '耶和华 对他 说:「你去走遍 耶路撒冷 全城,那些因 城中 所行 可憎之事 叹息 哀哭 的人,画 划 记号 在 额上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, '我耳中 听见他对其余 馀的人 说:「要跟随他 走遍 全城,以行击杀。你们的眼 不要 顾惜,也不要 可怜他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, '要将年老的、年少的,并处女、婴孩,和妇女,从圣所 起 全都杀 尽,只是凡 有记号 的人 不要 挨近 他。」于 是他们从殿 前的 长老 杀起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, '他对他们 说:「要污秽 这殿,使 院中 充满 被杀的人。你们出去吧!」他们就出去,在城中 击杀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, ' 他们击杀的时候,我 被留下,我就俯伏 在地,说:「哎!主 耶和华啊,你 将 忿怒 倾 在 耶路撒冷,岂要将 以色列 所剩下的人 都 灭绝吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, '他对我 说:「以色列 家 和犹大 家的罪孽 极其 重大。遍 地 有流血的事,满 城 有冤屈,因为 他们说:『耶和华 已经离弃 这地,他 看 不见我们。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, '故此,我 眼 必不 顾惜,也不 可怜他们,要照他们所行的 报应 在他们头上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, ' 那穿 细麻衣、 腰间 带著墨盒子 的人 将这事 回复 说:「我已经照你所 吩咐的 行了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, '我观看,见 基路伯 头上的 穹苍之中,显出 蓝宝 石的形状,仿佛 宝座 的形像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, '主 对 那穿 细麻衣 的人 说:「你进去,在 旋转的轮 内 基路伯 以下,从 基路伯 中间将火 炭 取满 两手,撒 在 城上。」我就见 他进去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, '那人 进去的时候,基路伯 站 在殿 的右边,云彩 充满了 内 院。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, '耶和华 的荣耀 从 基路伯 那里上升,停在 门槛以上;殿 内满了 云彩,院宇 也被耶和华 荣耀的 光辉 充满。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, '基路伯 翅膀 的响声 听 到 外 院,好像全能 神 说话 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, ' 他吩咐 那穿 细麻衣 的人 说:「要从 旋转的轮内 基路伯 中间取 火。」那人就进去 站 在一个轮子 旁边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, '有一个基路伯 从 基路伯 中伸 手 到 基路伯 中间的 火那里,取 些 放在 那穿 细麻衣 的人两手中,那人就拿 出去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, '在基路伯 翅膀 之下,显出 有人 手 的样式。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, '我又观看,见 基路伯 旁边 有四个 轮子。这 基路伯 旁 有一个 轮子,那 基路伯 旁 有一个 轮子,每基路伯都是如此;轮子的颜色(原文是形状)仿佛 水苍 玉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, '至于 四 轮的形状,都是一个 样式,仿佛 轮 中 套轮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, '轮行走的时候,向 四 方 都能直行,并不 掉转。 头 向 何 方,他们也随 向何方,行走 的时候并不 掉转。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, '他们全 身,连背 带手 和翅膀,并轮 周围 都满了 眼睛。这四 个基路伯的轮子都是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, '至于 这些轮子, 我耳中 听见说 是旋转的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, '基路伯各 有四 脸:第一 是基路伯 的脸,第二 是人 的脸,第三 是狮子 的脸,第四 是鹰 的脸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, '基路伯 升上去了;这是 我在迦巴鲁 河 边所 见的 活物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, '基路伯 行走,轮 也在旁边 行走。基路伯 展开  翅膀,离 地 上升, 轮 也 不 转离 他们旁边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, '那些站住,这些也站住;那些上升,这些也一同 上升,因为 活物 的灵 在轮中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, '耶和华 的荣耀 从 殿 的门槛 那里出去,停 在 基路伯以上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, '基路伯 出去的时候,就展开  翅膀,在我眼前 离 地 上升。轮 也在他们的旁边,都停 在耶和华 殿 的东 门 口。在他们 以上 有以色列 神 的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, '这是 我在迦巴鲁 河 边所 见、以色列 神 荣耀以下 的活物,我就知道 他们是 基路伯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, '各有 四个 脸面, 四个 翅膀,翅膀 以下 有人 手 的样式。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, '至于 他们脸 的模样,并身体的形像,是 我从前在 迦巴鲁 河 边所 看见 的。 他们俱各 直 往 前 行。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, '灵 将我 举起,带 到 耶和华 殿 向 东 的东 门。谁知,在门 口 有二十 五 个人,我见 其中 有民间的 首领 押朔 的儿子 雅撒尼亚 和 比拿雅 的儿子 毘拉提。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, '耶和华对我 说:「人 子啊,这 就是图谋 罪孽 的人,在这 城中 给人设 恶 谋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, '他们说:『盖 房屋 的时候尚未 临近;这 城是锅,我们 是肉。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, '人 子啊,因此 你当说预言,说预言 攻击他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, '耶和华 的灵 降 在我身上,对我 说:「你当说,耶和华 如此 说:以色列 家啊, 你们口中所说的,心里 所想的,我 都知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, '你们在这 城中 杀人 增多,使被杀的人 充满 街道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, '所以 主 耶和华 如此 说:你们杀在 城中 的人 就是 肉,这城就是 锅;你们 却要从其中 被带出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, '你们怕 刀剑,我必使 刀剑 临到你们。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, '我必从这城中 带出 你们去,交 在外邦人 的手中,且要在你们中间 施行 审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, '你们必倒 在刀下;我必在 以色列 的境界 审判 你们,你们就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, '这 城必不 作 你们的 锅,你们 也不作 其中 的肉。我必在 以色列 的境界 审判 你们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, '你们就知道 我 是耶和华;因为 你们没有 遵行 我的律例,也没有 顺从 我的典章,却随从 你们四围 列国的 恶规。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, ' 我正说预言的时候,比拿雅 的儿子 毘拉提 死了。于 是我俯伏在地,大 声 呼叫 说:「哎!主 耶和华啊,你 要将 以色列 剩下的人 灭绝 净尽吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, '「人 子啊,耶路撒冷 的居民 对你的弟兄、你的本族、你的亲属、以色列 全 家, 就是 对大众 说:『你们远离 耶和华吧!这 地 是赐 给我们 为业的。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, '所以 你当说:『耶和华 如此 说:我虽 将以色列全家远远迁移 到列国中, 将他们分散 在列邦内,我还要在他们所 到的 列邦,暂 作 他们的 圣所。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, ' 你当说:『主 耶和华 如此 说:我必从 万民中 招聚 你们,从 分散的 列国 内 聚集 你们,又要将 以色列 地 赐 给你们。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, '他们必到 那里,也必从其中 除掉 一切可憎 可厌的物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, '我要使 他们 有合一 的心,也要将新 灵 放 在他们里面,又从他们肉体中 除掉 石 心,赐 给他们 肉 心, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, '使 他们顺从 我的律例,谨守 遵行 我的典章。他们要作 我的 子民,我 要作 他们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, '至于 那些心中 随 从 可憎可厌之物 的,我必照他们所行的 报应 在他们头上。这是主 耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, '于 是,基路伯 展开  翅膀,轮子 都在他们旁边;在他们 以上 有以色列 神 的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, '耶和华 的荣耀 从 城 中 上升,停 在 城 东的 那座山上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, '灵 将我举起,在异象中藉 借著 神 的灵 将我带进 迦勒底地,到 被掳的人那里;我所 见的 异象 就离我 上升去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, '我便将 耶和华 所 指示我 的一切 事 都说 给 被掳的人听。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, '耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, '「人 子啊,你 住 在悖逆的 家 中。他们 有眼睛 看 不 见,有耳朵 听 不 见,因为 他们 是悖逆 之家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, '所以人 子啊,你 要预备 掳去 使用的物件, 在白日 当他们眼前 从你所住的地方 移 到 别 处去;他们 虽是 悖逆 之家,或者 可以揣摩思想。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, '你要在白日 当他们眼前 带出 你的物件去,好像预备掳去 使用的物件。到了晚上,你要在他们眼前 亲自 出去,像被掳的人 出去一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, '你要在他们眼前 挖 通了墙,从其中 将物件带出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, '到天黑时,你要当他们眼前 搭 在 肩头 上带出去,并要蒙住 脸 看不 见 地,因为 我立你 作以色列 家的 预兆。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, '我就照著所 吩咐的 去行,白日 带出 我的物件,好像预备掳去 使用的物件。到了晚上,我用手 挖通了 墙。天黑的时候,就当他们眼前 搭 在 肩头 上带出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, '次日早晨,耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, '「人 子啊,以色列 家,就是那悖逆 之家,岂不是 问你 说:『你 做 什么呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, '你要对他们 说:『主 耶和华 如此 说:这 是关乎耶路撒冷 的君王 和 他 周围 以色列 全 家的预表(原文是担子)。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, '你要说:『我 作你们的预兆:我怎样 行,他们 所遭遇 的也必怎样,他们必被掳 去。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, '他们 中间 的君王 也必在天黑 的时候将物件搭 在 肩头 上带出去。他们要挖 通了墙,从其中 带出去。他必蒙住 脸, 眼 看不 见 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, '我必将 我的网 撒 在他身上,他必在我的网罗 中缠住。我必带 他 到迦勒底人 之地 的巴比伦;他虽死 在那里,却看不 见 那地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, '周围 一切 帮助 他的 和他所有的 军队,我必分散 四方(方:原文是风),也要拔 刀 追赶他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, '我将他们 四散 在列国、分散 在列邦的时候,他们就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, '我却要留下 他们 几个 人 得免刀剑、饥荒、瘟疫,使 他们在所 到的 各国中 述说 他们一切 可憎的事,人就知道 我 是耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, '耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, '「人 子啊,你吃 饭 必胆战 ,喝 水 必惶惶 忧虑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, '你要对 这地 的百姓 说:主 耶和华 论耶路撒冷 和 以色列 地 的居民 如此 说,他们吃 饭 必忧虑,喝 水 必惊惶。因其中 居住 的众人 所行强暴的事, 这地 必然荒废,一无所存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, '有居民的 城邑 必变为荒场,地 也必变为 荒废;你们就知道 我 是耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, '「人 子啊,在 你们 以色列 地 怎么 有这 俗语,说『日子 迟延,一切 异象 都落了空』呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, ' 你要告诉 他们说:『主 耶和华 如此 说:我必使 这 俗语 止息,以色列中 不 再 用 这俗语。』你却 要对他们 说:『日子 临近,一切的 异象 必都应验。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, '从此,在以色列 家 中 必不 再 有 虚假的 异象 和奉承的 占卜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, ' 我─耶和华 说话, 所 说的 必定成就,不 再 耽延。 你们这悖逆 之家,我所说的 话 必趁你们在世的日子 成就。这是主 耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, '耶和华 的话 又临 到 我说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, '「人 子啊, 以色列 家 的人说:『他 所 见的 异象 是关乎后来许多的 日子, 所说的预言 是指著极远的 时候。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, '所以 你要对他们 说:『主 耶和华 如此 说:我的话 没有 一句 再 耽延的,我所 说的 必定成就。这是主 耶和华 说的。』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, '「人 子啊,你要说预言 攻击 以色列 中说预言 的先知,对那些本己心 发预言的 说:『你们当听 耶和华 的话。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, '主 耶和华 如此 说:「 愚顽的 先知 有祸了,他们 随 从 自己的心意,却一无 所见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, '以色列啊,你的先知 好像 荒场 中的狐狸, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, '没有 上去 堵挡破口,也没有为 以色列 家 重修 墙垣,使他们当耶和华 的日子 在阵上 站立得住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, '这些人所见 的是虚假,是谎诈 的占卜。他们说 是耶和华 说的,其实耶和华 并没有 差遣他们,他们倒使人指望 那话 必然立定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, '你们岂不是 见了 虚假 的异象吗?岂不是说了 谎诈 的占卜吗?你们说,这是耶和华 说的,其实我 没有 说。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, '所以 主 耶和华 如此 说:「因 你们说 的是虚假,见 的是谎诈, 我就与你们反对。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, '我的手 必 攻击 那见 虚假异象、用谎诈 占卜 的先知,他们必 不 列在我百姓 的会中,不 录 在以色列 家 的册上,也不 进 入 以色列 地;你们就知道 我 是主 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, '因为 他们诱惑 我的百姓,说:『平安!』其实没有 平安,就像有人 立起 墙壁,他们 倒用未泡透的灰 抹上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, '所以你要对 那些抹上 未泡透灰 的人说:『墙要倒塌,必有 暴雨 漫过。大冰雹啊,你们 要降下,狂 风 也要吹裂这墙。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, ' 这墙 倒塌之后,人岂不 问你们 说:『 你们抹上 未泡透的灰 在哪里呢?』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, '所以 主 耶和华 如此 说:「我要发怒,使狂 风 吹裂这墙,在怒中 使 暴雨 漫过,又发怒 降下大冰雹,毁灭这墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, '我要这样拆毁 你们那未泡透灰 所 抹 的墙,拆平 到 地,以致根基 露出,墙必倒塌,你们也必在其中 灭亡;你们就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, '我要这样向墙 和用未泡透灰 抹墙 的人成就 我怒中所定的,并要对你们 说:『 墙和抹墙 的人 都没有了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, '这抹墙的就是以色列 的先知,他们指著 耶路撒冷 说预言,为这城 见了 平安 的异象,其实没有 平安。这是主 耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, '「人 子啊,你 要面 向 本民中、从己心 发预言 的女子 说预言,攻击她们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, '说 主 耶和华 如此 说:『这些妇女有祸了!她们为 众人 的膀 臂 缝 靠枕,给高矮之人 做 下垂的头 巾,为要猎取 人的性命。难道你们要猎取 我百姓 的性命,为利己 将人 救活吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, '你们为两把 大麦,为几块 饼,在 我民 中亵渎 我,对肯听 谎言 的民 说谎,杀死 不 该死 的人,救活 不 该活 的人。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, '所以 主 耶和华 如此 说:「看哪,我与 你们的靠枕反对,就是 你们 用以 猎取人、使 人的性命 如鸟飞的。我要将靠枕 从 你们的膀臂 上扯去,释放 你们 猎取 如鸟飞 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, '我也必撕裂 你们下垂的头巾,救 我百姓 脱离你们的手,不 再 被猎取,落在你们手中。你们就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, ' 我 不 使义人 伤心,你们却以谎话 使他伤 心,又坚固 恶人 的手,使他不 回头 离开 恶 道 得以救活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, ' 你们就不 再见 虚假的异象,也不 再 行 占卜的事;我必救 我的百姓 脱离你们的手;你们就知道 我 是耶和华。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, '有几个 以色列 长老 到我 这里来,坐 在我面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, '耶和华 的话 就临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, '「人 子啊,这些 人 已将他们的假神 接 到 心里,把陷于 罪 的绊脚石 放 在面 前,我岂能丝毫 被他们 求问吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, '所以 你要告诉 他们:『主 耶和华 如此 说:以色列 家 的人 中,凡 将 他的假神 接 到 心里,把陷于 罪 的绊脚石 放 在面 前,又就了 先知 来的,我─耶和华 在他所求的事上,必按他众多 的假神 回答 他(或译:必按他拜许多假神的罪报应他), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, '好 在 以色列 家 的心事 上捉住他们,因为他们 都 藉 借著假神 与我 生疏。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, '「所以 你要告诉 以色列 家 说:『主 耶和华 如此 说:回头吧!离开  你们的偶像,转 脸 莫从 你们一切 可憎的事。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, '因为 以色列 家 的人,或 在以色列 中寄居 的外人,凡与我 隔绝,将他的假神 接 到 心里,把陷于 罪 的绊脚石 放 在面 前,又就了 先知 来 要为自己 的事求问 我的,我─耶和华 必亲自 回答 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, '我必向那 人 变脸,使他作了警戒,笑谈,令人惊骇,并且我要将他从我民 中 剪除;你们就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, '先知 若 被迷惑 说 一句预言,是我─耶和华 任 那 先知 受迷惑,我也必向他 伸 手,将他从我民 以色列 中 除灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, '他们必担当 自己的罪孽。先知 的罪孽 和求问之人 的罪孽 都是一样, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, '好使 以色列 家 不 再 走迷 离开 我,不 再 因各样 的罪过 玷污自己,只要作 我的 子民,我 作 他们的 神。这是主 耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, '「人 子啊,若 有一国 犯 罪 干犯 我,我也向他 伸 手 折断 他们的 杖,就是断绝他们的粮,使饥荒 临到 那地,将人 与牲畜 从其中 剪除; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, '其中 虽有 挪亚、但以理、约伯 这 三 人,他们 只能因他们的义 救 自己的性命。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, '我若 使恶 兽 经过 糟践 那地,使 地荒凉,以致因 这些兽,人都不得 经过; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, '虽有这 三 人 在其中,主 耶和华 说:我 指著我的永生起誓,他们 连 儿 带 女 都不能得救,只能 自己得救,那地 仍然 荒凉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, '或者 我使刀剑 临 到 那 地,说:刀剑哪,要经过 那地,以致我将人 与牲畜 从其中 剪除; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, '虽有这 三 人 在其中,主 耶和华 说:我 指著我的永生起誓,他们连儿 带女 都不能 得救, 只能 自己得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, '或者 我叫 瘟疫 流行 那 地,使我灭命(原文是带血)的忿怒 倾 在其上,好将人 与牲畜 从其中 剪除; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, '虽有挪亚、但以理、约伯 在其中,主 耶和华说:我 指著我的永生起誓,他们 连 儿 带 女 都不能救,只能因他们的义 救 自己的性命。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, ' 主 耶和华 如此 说:「 我将这四样 大 灾─就是刀剑、饥荒、恶 兽、瘟疫 降 在 耶路撒冷,将人 与牲畜 从其中 剪除,岂不更重吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, '然而 其中 必有剩下 的人,他们连儿 带女必 带 到你们 这里来,你们看见 他们所行 所为的,要因我 降 给 耶路撒冷的 一切 灾祸,便得了安慰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, ' 你们看见 他们所行 所为的, 得了安慰,就知道 我在耶路撒冷 中所行 的并非 无故。这是主 耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, '「人 子啊,葡萄 树 比别样 树 有 什么强处?葡萄枝 比众树 枝有什么好处? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, '其上 可以取 木料 做 什么工用,可以 取来 做钉子 挂 什么 器皿么? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, '看哪,已经抛 在火 中当作柴烧,火 既烧了 两 头,中间 也被烧了,还有益于  工用吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, ' 完全 的时候 尚且不 合乎 什么工用,何况 被火 烧 坏,还能 合乎 什么工用么?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, '所以,主 耶和华 如此 说: 众树 以内的葡萄 树,我怎样 使 它在火 中当柴,也必照样 待 耶路撒冷 的居民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, '我必向他们 变 脸;他们虽从火 中出来,火 却要烧灭他们。我向他们 变 脸的时候,你们就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, '我必使 地土 荒凉,因为 他们行事 干犯我。这是主 耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, '耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, '「人 子啊,你要使 耶路撒冷 知道 她那些可憎的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, '说 主 耶和华 对耶路撒冷 如此 说:你根本,你出世,是在迦南 地;你父亲 是亚摩利人,你母亲 是赫人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, '论到你出世的景况,在你 初生 的日子 没有 为你断 脐带,也没有 用水 洗你,使你洁净,丝毫 没有 撒盐在你身上,也没有 用布 裹你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, '谁的眼 也不 可怜 你,为你 做 一件 这样的事 怜恤 你;但你 初生 的日子 扔 在 田野,是因你 被厌恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, '「我从你旁边 经过,见 你滚 在血中,就对你 说:你虽在血中,仍可存活; 你虽在血中,仍可存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, '我使 你生长 好像田间 所长的,你就渐渐长 大,以致 极其 俊美,两乳 成形,头发 长成,你 却仍然赤身 露体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, '我从你旁边 经过,看见 你的时候 正动爱情,便用衣襟 搭 在你身上,遮盖 你的赤体;又向你 起誓,与你 结 盟,你就归 于 我。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, '那时我用水 洗你,洗净 你身上的血,又用油 抹你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, '我也使你身穿 绣花衣服,脚穿 海狗皮鞋,并用细麻布 给你束腰,用丝绸 为衣披在你身上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, '又用妆饰 打扮你,将镯子 戴 在 你手上,将金链 戴在 你项上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, '我也将环子 戴 在 你鼻子上,将耳环 戴在 你耳朵上,将华 冠 戴在你头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, '这样,你就有金 银 的妆饰,穿 的是细麻衣 和丝绸,并绣花衣;吃 的是细面 麺、蜂蜜,并油。你也极其 美貌,发达 到王后的尊荣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, '你 美貌 的名声 传 在列邦中, 你十分美貌,是 因我加在 你身上 的威荣。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, '只是你仗著 自己的美貌,又因 你的名声 就行邪淫。你纵情 淫乱,使 过路的 任意 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, '你用 衣服 为自己 在高处 结 彩,在其上 行邪淫。这样的事将来 必没有,也必 不再行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, '你又将 我所 给 你 那华美 的金 银、宝器 为自己 制造 人 像,与他 行邪淫; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, '又用 你的绣花 衣服 给他披上,并将我的膏油 和香料 摆 在他跟前; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, '又将我赐 给你 的食物,就是 我赐给你吃 的细面 麺、油,和蜂蜜,都摆 在他跟前 为馨香 的供物。这是 主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, '并且你将 给我 所 生的 儿 女 焚 献 给他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, '你行淫乱 岂是小事,竟将 我的儿女 杀了,使他们 经 火归 与他吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, '你行这 一切 可憎 和淫乱的事,并未 追念 你幼年 赤身 露体 滚 在血 中的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, ' 你行这一切 恶事 之后(主 耶和华 说:你 有祸了!有祸了!) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, '又为自己 建造 圆顶花楼,在各 街上 做了 高台。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, '你在 一切 市 口 上建造 高台,使 你的美貌 变为可憎的,又 与一切 过路的 多行 淫乱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, '你也和 你邻邦 放纵 情欲 的埃及 人 行淫,加增 你的淫乱,惹我发怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, ' 因此我伸 手 攻击你,减少 你应用的粮食,又将你交 给恨 你的非利士 众女(众女是城邑的意思;本章下同),使她们任意待你。她们见你的淫 行,为你羞耻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, '你因贪色无 厌,又与 亚述 人 行淫,与他们行淫之后,仍 不 满意, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, '并且多行 淫乱,直到 那贸易 之地,就是迦勒底,你仍 不 满意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, '主 耶和华 说:你行 这 一切事,都是不知羞耻 妓 女 所行的,可见你的心 是何等 懦弱! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, '因你在一切 市 口 上建造 圆顶花楼,在各 街 上做了 高台,你却藐视 赏赐,不 像 妓女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, '哎!你这行淫 的妻啊,宁肯接 外人,不接 丈夫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, '凡 妓女 是得 人赠送,你 反倒赠送 你所 爱的人,贿赂 他们 从四围 来 与你 行淫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, '你 行淫 与 别的妇女相 反,因为不是 人从你 行淫;你既赠送 人,人并不 赠送 你;所以你 与别的妇女相反。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, ' 你这妓女啊,要听 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, '主 耶和华 如此 说:因 你的污秽 倾泄了,你与 你所爱的 行淫 露出 下体,又因 你拜一切 可憎 的偶像,流儿女 的血 献 给他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, ' 我 就要 将 你一切 相欢、 相爱的,和 你一切 所 恨 的都聚集来,从四围 攻击你;又将你的下体 露出,使他们看 尽了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, '我也要审判你,好像官长审判 淫妇 和流 人血的妇女一样。我因忿怒 忌恨,使流血 的罪归到你身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, '我又要将你 交 在他们手中;他们必拆毁 你的圆顶花楼,毁坏 你的高台,剥去 你 的衣服,夺取 你的华美 宝器,留下 你赤身 露体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, '他们也必带 多人 来攻击你,用石头 打死 你,用刀剑 刺透你, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, '用火 焚烧 你的房屋,在许多 妇人 眼前 向你 施行 审判。我必使你不再 行淫,也 不 再 赠送与人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, '这样,我就止息 向你 发的忿怒,我的忌恨 也要离开  你,我要安静 不 再 恼怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, '因 你不 追念 你幼年 的日子,在这 一切的 事上向我 发烈怒, 所以我 必 照你所行的 报应 在你头上,你就不再贪 淫,行 那一切 可憎的事。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, '「 凡 说俗语 的必用俗语 攻击你,说:『母亲怎样,女儿也怎样。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, '你 正是你母亲 的女儿,厌弃 丈夫 和儿女;你 正是你姊妹 的姊妹, 厌弃 丈夫 和儿女。你母亲 是赫人,你父亲 是亚摩利人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, '你的姊姊 是撒马利亚,她 和她的众女 住 在 你左边;你的 妹妹 是所多玛,她和她的众女 住 在你右边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, '你没有 效法 她们的行为,也没有照她们可憎的事 去做,你以那为小事,你一切 所行的 倒比她们 更坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, '主 耶和华 说:我 指著我的永生起誓,你妹妹 所多玛 与她的众女 尚未 行 你 和你众女 所 行的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, '看哪,你妹妹 所多玛 的罪孽 是 这样:她 和她的众女都 心骄气傲,粮食 饱足,大享 安逸,并没有 扶助 困苦 和穷乏人 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, '她们狂傲,在我面前 行 可憎的事, 我看见 便将她们 除掉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, '撒马利亚 没有 犯 你一半 的罪,你行 可憎的事 比她 更多,使 你的姊妹 因你所 行 一切 可憎的事,倒显为义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, '你 既 断定 你姊妹为义(为义:或译当受羞辱),就要担当 自己的羞辱;因你所 犯的罪 比她们 更为可憎,她们就比你 更显为义;你 既 使你的姊妹 显为义,你就要抱愧 担当 自己的羞辱。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, '「我必叫 她们被掳的 归回,就是叫 所多玛 和她的众女, 撒马利亚 和她的众女,并 你们中间 被掳的,都要归回, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, '好使 你担当 自己的羞辱,并因你一切 所 行 的使她们 得安慰,你就抱愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, '你的妹妹 所多玛 和她的众女 必归回 原位;撒马利亚 和她的众女,你 和你的众女,也必归回 原位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, '在你骄傲 的日子,你的恶行 没有显露 以先,你的口 就 不 提 你的妹妹 所多玛。 那受了凌辱 的亚兰 众女 和亚兰四 围 非利士 的众女都恨恶你, 藐视 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, '耶和华 说:你贪 淫 和 可憎的事,你 已经担当了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, '「 主 耶和华 如此 说:你这 轻看 誓言、背弃 盟约的,我必照你所 行 的待 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, '然而我 要追念 在你幼年 时 与你 所立的约,也要与你 立定 永 约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, '你接待 你 姊姊 和 你 妹妹的时候,你要追念 你所行的,自觉惭愧;并且我要将她们 赐 你 为女儿,却不是 按著前约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, '我 要坚定 与你 所立的约(你就知道 我 是耶和华), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, '好使 你在我赦免 你 一切 所 行的时候,心里追念,自觉抱愧,又因 你的羞辱 就 不 再 开  口。这是主 耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, '「人 子啊,你要向 以色列 家 出 谜语,设 比喻, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, '说 主 耶和华 如此 说:有一大 鹰,翅膀 大,翎毛 长,羽毛 丰满,彩色 俱备,来 到 黎巴嫩,将 香柏树 梢 拧去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, '就是折去 香柏树尽 侭尖 的嫩枝,叼 到 贸易 之地,放 在买 卖 城中; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, '又将 以色列地 的枝子 栽 于 肥 田里,插 在 大 水旁,如插 柳树, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, '就渐渐生长,成为 蔓延 矮小 的葡萄树。其枝 转 向那鹰,其根 在 鹰以下,于 是成了 葡萄树,生出 枝子,发出 小枝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, '又有 一 大 鹰,翅膀 大,羽毛 多。 这 葡萄树 从栽种 的畦 中向 这鹰弯 过 根来,发出 枝子,好得它的浇灌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, '这 树栽 于  肥 田 多 水 的旁边,好生 枝子,结 果子,成为 佳美 的葡萄树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, '你要说,主 耶和华 如此 说:这葡萄树岂能发旺呢?鹰岂不 拔出 它的根来,芟除 它的果子,使它枯干,使它发 的嫩叶 都 枯干了吗?也不 用大 力 和多 民,就拔出 它 的根来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, ' 葡萄树虽然栽种,岂能发旺呢?一经 东 风,岂不 全然 枯干吗?必在 生长 的畦 中枯干了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, '「 你对那悖逆 之家 说:你们不 知道 这些事 是什么意思么?你要告诉他们说, 巴比伦 王 曾到 耶路撒冷,将 其中的君王 和 首领 带 到巴比伦 自己那里 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, '从以色列的宗室 中取 一人与他 立 约,使他 发 誓,并将 国 中有势力的人 掳去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, '使 国 低微 不能 自强,惟因守 盟约 得以存立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, '他却背叛 巴比伦王,打发 使者 往埃及去,要他们给 他 马匹 和多 民。他岂能亨通呢?行 这样事 的人岂能逃脱呢?他背 约 岂能逃脱呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, '他 轻看 向王所起的誓, 背弃 王与他 所立的约。主 耶和华 说:我 指著我的永生起誓,他定 要死 在立他 作王、巴比伦 王的京都。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, '敌人筑 垒 造 台,与他打仗的时候,为要剪除 多 人,法老 虽领大 军队 和大 群众,还是不能 帮助 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, '他轻看 誓言,背弃 盟约, 已经投降,却又做 这 一切的事,他必不能 逃脱。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, '所以 主 耶和华 如此 说:「我 指著我的永生起誓,他既轻看 指我所 起的誓,背弃 指我所 立的约,我必要 使这罪归 在他头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, '我必将我的网 撒 在他身上,他必在我的网罗 中缠住。我必带他 到巴比伦,并要在那里 因他干犯 我 的 罪 刑罚 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, ' 他的一切 军队,凡 逃跑的,都必倒 在刀下;所剩下的,也必分散 四方(方:原文是风)。你们就知道 说 这话的是我─耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, '主 耶和华 如此 说:「我 要将 香柏树 梢 拧去 栽上,就是从尽 侭尖 的嫩枝 中折 一嫩枝, 栽 于  极 高 的山上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, '在以色列 高处 的山 栽上。它就生 枝子,结 果子,成为 佳美 的香柏树,各 类飞 鸟 都必宿 在其下,就是宿 在枝子 的荫下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, '田野 的树木 都 必知道 我─耶和华 使高 树 矮小,矮 树 高大;青 树 枯干,枯 树 发旺。我─耶和华 如此说,也如此行了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, '耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, '「你们 在 以色列 地 怎么 用 这 俗语 说『父亲 吃了 酸葡萄,儿子 的牙 酸倒了』呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, '主 耶和华 说:「我 指著我的永生起誓,你们 在以色列中,必不 再 有用 这 俗语的因由。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, '看哪,世人 都 是 属我的;为父 的怎样属我,为子 的也照样 属我;犯罪 的,他 必死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, '「人 若 是 公义,且行 正直 与合理的事: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, '未曾 在 山 上吃过祭偶像之物, 未曾 仰望 以色列 家 的偶像,未曾 玷污 邻舍 的妻,未曾 在妇人 的经期 内亲近她, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, '未曾 亏负 人,乃将欠债之人 的当头 还给他;未曾 抢夺人的物件,却将食物 给 饥饿的人吃,将衣服 给赤身 的人穿; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, '未曾 向借钱的弟兄取 利,也未曾 向借粮的弟兄多 要,缩 手 不作罪孽,在两人 之间,按至理 判断; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, '遵行 我的律例,谨守 我的典章,按诚实 行事─这人 是公义的,必定 存活。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, '「他若生 一个儿子,作强盗,是流 人血的, 不 行 以上所 说之善,反行 其 中之恶,乃 在 山 上吃过祭偶像之物,并玷污 邻舍 的妻, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, '亏负 困苦 和穷乏的人,抢夺人的物,未曾 将当头 还给人, 仰望 偶像,并行 可憎的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, '向借钱的弟兄取 利,向借粮的弟兄多 要─这人岂能存活呢?他必不能 存活。他行 这 一切 可憎的事,必要 死亡,他的罪(原文是血)必归 到他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, '「他若 生 一个儿子,见 父亲 所 犯 的一切 罪便惧怕(有古卷:思量),不 照样 去做; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, '未曾 在 山 上吃过祭偶像之物, 未曾仰望 以色列 家 的偶像,未曾 玷污 邻舍 的妻, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, '未曾 亏负 人,未曾 取 人的当头,未曾 抢夺人的物件,却将食物 给 饥饿的人吃,将衣服 给赤身 的人穿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, '缩 手 不害贫穷人,未曾 向借钱的弟兄取 利,也未曾 向借粮的弟兄多要;他顺从 我的典章,遵行 我的律例, 就不 因父亲 的罪孽 死亡,定要 存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, '至于 他父亲;因为 欺人 太甚,抢 夺 弟兄, 在本国的民 中 行 不 善, 他必因自己的罪孽 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, '「你们还说:『儿子 为何 不 担当 父亲 的罪孽呢?』儿子 行 正直 与合理的事,谨守 遵行 我的一切 律例,他必定 存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, '惟有犯罪 的,他 必死亡。儿子 必不 担当 父亲 的罪孽,父亲 也不 担当 儿子 的罪孽。义人 的善果 必 归自己,恶人 的恶报 也必 归自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, '「恶人 若 回头 离开 所 做 的一切 罪恶,谨守 我一切 的律例,行 正直 与合理的事,他必定 存活,不致 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, '他所 犯 的一切 罪过 都不 被记念,因所 行 的义,他必存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, '主 耶和华 说:恶人 死亡,岂是我喜悦的吗?不是 喜悦 他回头 离开 所行的道 存活吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, '义人 若转 离义行 而作 罪孽,照著恶人 所 行 一切 可憎的事 而行,他岂能存活吗?他所 行 的一切 义 都不 被记念;他必因所 犯 的罪、所 行 的恶 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, '「你们还说:『主 的道 不 公平!』以色列 家啊,你们当 听,我的道 岂不 公平吗?你们的道 岂不是 不 公平吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, '义人 若转 离义行 而作 罪孽 死亡,他是因所 作 的罪孽 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, '再者,恶人 若回头 离开 所 行 的恶,行 正直 与合理的事,他 必将 性命 救活了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, '因为他思量,回头 离开 所 犯 的一切 罪过,必定 存活,不致 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, '以色列 家 还说:『主 的道 不 公平!』以色列 家啊,我的道 岂不 公平吗?你们的道 岂不是 不 公平吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, '所以 主 耶和华 说:「以色列 家啊,我必按你们各人 所行的 审判 你们。你们当回头 离开  所犯的一切 罪过。这样,罪孽 必不 使 你们 败亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, '你们要将 所 犯 的一切 罪过 尽行抛弃,自 做 一个新 心 和新 灵。以色列 家啊,你们何必 死亡呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, '主 耶和华 说: 我不 喜悦 那死 人之死,所以你们当回头 而存活。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, '你 当为 以色列 的王 作起 哀歌, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, '说:你的母亲 是什么呢?是个母狮子,蹲伏 在狮子 中间,在少壮狮子 中 养育 小狮子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, '在牠小狮子 中养大 一个,成了 少壮狮子,学会 抓 食 而吃 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, '列国 听见了 就把牠捉 在他们的坑中,用钩子 拉 到 埃及 地去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, '母狮见 自己等候 失了 指望,就从牠小狮子 中又将 一个 养为 少壮狮子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, '牠在众狮子 中 走来走去,成了 少壮狮子,学会 抓 食 而吃 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, '牠知道 列国的宫殿,又使他们的城邑 变为荒场;因牠咆哮 的声音,遍地 和其中所有的 就都荒废。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, '于 是四围 邦国 各省 的人来 攻击牠,将网 撒 在牠身上,捉 在他们的坑中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, '他们用钩子钩住牠,将牠放 在笼中,带 到 巴比伦 王那里,将他放入 坚固之所,使 他的声音 在 以色列 山 上不 再 听见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, '你的母亲 先前如葡萄树,极其茂盛(原文是在你血中),栽 于  水旁。因为水 多,就 多结果子,满生枝子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, '生出 坚固 的枝干,可作 掌权者 的杖。这枝干高 举 在 茂密的枝 中,而且它生长高大,枝子 繁多,远远可见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, '但这葡萄树因忿怒 被拔出 摔 在地上;东 风 吹干 其上的果子,坚固 的枝干 折断 枯干,被火 烧毁了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, '如今 栽 于 旷野 干旱 无水 之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, '火 也从它枝干 中发出,烧灭 果子,以致没 有 坚固 的枝干 可做掌权者 的杖。这 是哀歌,也必用以作 哀歌。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, ' 第七 年 五 月 初十日,有以色列 的几个 长老 来 求问 耶和华,坐 在我面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, '「人 子啊,你要告诉 以色列 的长老 说,主 耶和华 如此 说:你们 来 是求问 我吗?主 耶和华 说:我 指著我的永生起誓,我必不 被你们 求问。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, '人 子啊,你要审问 审问 他们吗?你当使他们知道 他们列祖 那些可憎的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, '对他们 说,主 耶和华 如此 说:当日 我拣选 以色列,向雅各 家 的后裔 起 誓,在埃及 地 将自己向他们 显现,说:我 是耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, '那 日 我向他们 起 誓,必领他们 出埃及 地,到 我为他们 察看的 流 奶 与蜜 之地;那地 在万 国 中是有荣耀的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, '我对他们 说,你们各人 要抛弃 眼 所喜爱那可憎之物,不可 因埃及 的偶像 玷污自己。我 是耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, '他们却悖逆 我,不 肯 听从 我, 不 抛弃 他们眼 所喜爱那可憎之物,不 离弃 埃及 的偶像。「我就说,我要将我的忿怒 倾 在他们身上,在 埃及 地 向他们成就 我怒中所定的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, '我却为 我名 的缘故没有这样行,免得 我名在他们 所 住 的列国人 眼前 被亵渎;我领他们 出埃及 地,在这列国人的 眼前 将自己向他们 显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, '这样,我就使他们 出埃及 地,领他们 到 旷野, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, '将 我的律例 赐给 他们,将 我的典章 指示 他们; 人 若遵行 就必因此 活著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, '又 将 我的安息日 赐 给他们,好在我 与他们中间 为 证据,使他们知道 我─耶和华 是叫他们成为圣的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, '以色列 家 却在旷野 悖逆 我,不 顺从 我的律例,厌弃 我的典章( 人 若遵行 就必因此 活著),大大 干犯 我的安息日。「我就说,要在旷野 将我的忿怒 倾 在他们身上,灭绝他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, '我却为 我名的缘故,没有这样行,免得 我的名在我领他们出埃及的 列国人 眼前 被亵渎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, '并且 我 在旷野 向他们 起 誓,必不 领 他们 进入 我所 赐 给他们流 奶 与蜜 之地(那地 在万 国 中是有荣耀的); ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, '因为 他们厌弃 我的典章,不 顺从 我的律例,干犯 我的安息日, 他们的心 随 从 自己的偶像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, '虽然如此,我眼 仍顾惜 他们,不毁灭他们,不 在旷野 将他们 灭绝 净尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, '「我在旷野 对 他们的儿女 说:不要 遵行 你们父亲 的律例,不要 谨守 他们的恶规,也不要 因他们的偶像 玷污自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, '我 是耶和华─你们的 神,你们要顺从 我的律例,谨守 遵行 我的典章, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, '且以 我的安息日 为圣。这日在我 与你们中间 为 证据,使你们知道 我 是耶和华─你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, '只是他们的儿女 悖逆 我,不 顺从 我的律例,也不 谨守 遵行 我的典章( 人 若遵行 就必因此 活著),干犯 我的安息日。「我就说,要将我的忿怒 倾 在他们身上,在旷野 向他们 成就 我怒中所定的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, '虽然如此,我却为 我名 的缘故缩 手 没有这样行,免得 我的名在我领 他们出埃及的 列国人 眼前 被亵渎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, '并且 我 在旷野 向他们 起 誓,必将他们 分散 在列国,四散 在列邦; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, '因为 他们不 遵行 我的典章,竟厌弃 我的律例,干犯 我的安息日,眼目 仰望 他们父亲 的偶像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, '我 也 任 他们 遵行不 美 的律例,谨守不能 使人活著 的恶规。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, '因他们将一切 头 生的 经火,我就任凭他们在这供献 的事上玷污 自己,好叫 他们凄凉,使 他们知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, '「 人 子啊,你要告诉 以色列 家 说,主 耶和华 如此 说: 你们的列祖 在得罪 我 的事上 亵渎 我; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, '因为我领他们 到了 我起 誓 应许赐 给他们的 地,他们看见 各 高 山、各 茂密 树,就在那里 献 祭, 奉上 惹我发怒 的供物,也在那里 焚烧 馨香 的祭牲,并 浇上 奠祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, '我就对他们 说:你们 所 上 的那高处 叫什么呢?(那 高处的名字 叫 巴麻 直到 今 日。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, '所以 你要对 以色列 家 说,主 耶和华 如此 说:你们 仍照你们列祖 所行的 玷污自己吗? 仍照 他们可憎的事 行邪淫吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, '你们奉上 供物 使你们儿子 经 火的时候, 仍将一切 偶像 玷污自己,直到 今日吗?以色列 家啊,我 岂被你们 求问吗?主 耶和华 说:我 指著我的永生起誓,我必不 被你们 求问。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, '「 你们 说:我们要 像外邦人 和列国 的宗族一样,去事奉 木头 与石头。你们所起的 这心意 万 不能 成就。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, '主 耶和华 说:「我 指著我的永生起誓,我总要作王,用大能 的手 和伸出来 的膀臂,并倾出来 的忿怒,治理 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, '我必用大能 的手 和伸出来 的膀臂,并倾出来 的忿怒,将你们 从 万民 中领出来,从 分散 的 列国 内 聚集 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, '我必带 你们 到 外邦人 的旷野,在那里 当面 刑罚 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, '我怎样 在埃及 地 的旷野 刑罚 你们的列祖,也必照样 刑罚 你们。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, '我必使你们 从杖 下 经过,使 你们 被约 拘束。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, '我必从你们中间 除净 叛逆 和得罪 我的人,将他们 从所寄居 的地方 领出来,他们却不得 入 以色列 地。你们就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, '「以色列 家啊,至于 你们,主 耶和华 如此 说:从此以后 若 不 听从 我,就任凭你们 去 事奉 偶像,只是不可 再 因你们的供物 和偶像 亵渎 我的圣 名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, '「主 耶和华 说: 在我的圣 山, 就是以色列 高处 的山,所有 以色列 的全 家 都要事奉我。我要在那里 悦纳你们, 向你们要 供物 和 初熟 的土产,并一切 的圣物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, '我从万民 中领 你们出来,从 分散的 列国 内 聚集 你们,那时我必悦纳 你们 好像馨香 之祭,要在外邦人 眼前 在你们 身上显为圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, '我领 你们 进入 以色列 地, 就是 我起 誓 应许赐 给你们列祖 之地,那时你们就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, '你们在那里 要追念 玷污自己的 行动 作为,又要因 所 做 的一切 恶事 厌恶自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, '主 耶和华 说:以色列 家啊,我为 我名的缘故,不 照著你们的恶 行 和你们的坏 事 待 你们;你们就知道 我 是耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, '「人 子啊,你要 面 向 南方,向 南 滴下 预言 攻击 南方 田野 的树林。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, '对南方 的树林 说,要听 耶和华 的话。主 耶和华 如此 说:我 必使火 在你中间 著起,烧灭 你中间 的一切 青 树 和枯 树,猛烈 的火焰 必不 熄灭。从南 到北,人的脸面 都 被烧焦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, '凡 有血气的 都必知道 是我─耶和华 使火著起,这火必不 熄灭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, '于 是我说:「哎!主 耶和华啊,人 都指著我 说:他 岂不是 说 比喻的吗?」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, '「人 子啊,你要 面 向 耶路撒冷 和圣所 滴下 预言,攻击 以色列 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, '对以色列 地 说,耶和华 如此 说:我 与你为敌,并要拔 刀 出鞘,从你中间 将义人 和恶人 一并剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, '我既 要从你中间 剪除 义人 和恶人,所以 我的刀 要出 鞘,自南 至北 攻击 一切 有血气的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, '一切 有血气的 就知道 我─耶和华 已经拔 刀 出鞘,必不 再 入鞘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, '人 子啊,你 要叹息,在他们眼前 弯著 腰,苦苦地 叹息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, ' 他们问你 说:『 为 何 叹息呢?』你就说:『因为 有风声、 灾祸要来。人心 都 必消化,手 都 发软, 精神 衰败, 膝 弱 如水。看哪,这灾祸临近,必然成就。这是主 耶和华 说的。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, '「人 子啊,你要预言。耶和华 吩咐 我如此 说:有刀、有刀,是磨快 擦亮的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, '磨快 为 要行 杀戮,擦亮 为 要 像闪电。我们岂可 快乐吗?罚我子 的杖 藐视 各 树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, '这刀 已经交 给人擦亮,为要应手 使用。这刀已经 磨快 擦亮,好交 在行杀戮的 人手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, '人 子啊,你要呼喊 哀号,因为 这 刀临 到我的百姓 和以色列 一切的 首领。他们 和 我的百姓 都交 在 刀下,所以 你要拍 腿叹息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, ' 有试验的事;若 那藐视 的杖 归于  无有,怎么样呢?这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, '「人 子啊,你 要拍 掌 预言。我─耶和华要使这刀,就是致死伤的 刀,一连三次 加倍刺人,进入他们的内屋,使大人 受死伤 的就是 这刀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, '我设立 这恐吓人的 刀,攻击 他们的一切 城门,使 他们的心 消化,加增 他们跌倒的事。哎!这刀造得 像闪电,磨得尖利,要行杀戮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, '刀啊,你归 在右边,摆 在左边;你面 向 哪方,就向那方杀戮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, '我 也 要拍 掌,并要使我的忿怒 止息。这是我─耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, '耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, '「人 子啊,你 要定出 两 条路,好使巴比伦 王 的刀 来。这两 条路必从一 地 分出来,又要在 通城 的路 口 上画 划出 一只手来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, '你要定出 一条路,使刀 来 到亚扪 人的 拉巴;又要定出一条路,使刀来到 犹大 的坚固城 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, '因为 巴比伦 王 站 在 岔 路那里,在两 条路 口 上要占 卜。他摇签(原文是箭)求问 神像,察看 牺牲的肝; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, '在右手 中拿著 为耶路撒冷 占卜的签,使他安设 撞城锤,张 口 叫杀,扬 声 呐喊,筑 垒 造 台,以撞 城锤,攻打 城门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, '据那些曾起 誓 的犹大人 看来,这是 虚假的 占卜;但巴比伦王 要使他们想起 罪孽,以致将他们捉住。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, ' 主 耶和华 如此 说:「因 你们的过犯 显露,使你们的罪孽 被记念,以致你们的罪恶 在行为 上都 彰显出来;又因 你们被记念,就被 捉住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, '你 这受死伤 行恶的 以色列 王啊, 罪孽 的尽头 到了,受报的日子 已到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, '主 耶和华 如此 说:当除掉 冠,摘下 冕,景况 必不 再像先前;要使卑者 升为高,使高者 降为卑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, '我要将 这国倾覆 复,倾覆 复,而又倾覆 复;这 国也必 不 再有,直等到 那 应得的人 来到,我就赐给他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, '「 人 子啊,要发预言 说:主 耶和华 论到 亚扪 人 和 他们的凌辱,吩咐 我如此 说:有刀,有拔出来 的刀,已经擦亮,为行杀戮,使 他像闪电 以行吞灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, '人为你 见 虚假的异象, 行谎诈的 占卜,使 你 倒在 受死伤 之恶人 的颈项上。他们 罪孽 到了 尽头,受报的日子 已到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, '你将刀收 入 鞘吧!在你受造 之 处、生长 之地,我必刑罚 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, '我必将我的恼恨 倒 在你身上,将我烈怒 的火 喷 在你身上;又将你交 在善于  杀灭的 畜类 人 手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, '你必当 柴 被火焚烧,你的血 必流 在国 中,你必不 再被记念,因为 这是我─耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, '耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, '「人 子啊,你 要审问 审问 这流人血的 城吗?当使她知道 她一切 可憎的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, '你要说,主 耶和华 如此 说:哎!这城 有流 人血 的事在其中,叫她受报的日期 来到,又做 偶像 玷污自己,陷害自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, ' 你因流了 人的血,就为有罪; 你做了 偶像,就玷污自己,使你受报之日 临近, 报应之年 来到。所以 我叫 你受列国 的凌辱 和列 邦 的讥诮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, '你这名 臭、多 乱的城啊,那些离你近、离你 远的 都必讥诮 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, '「看哪,以色列 的首领 各 逞其能, 在你中间 流 人之血。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, '在你中间 有轻慢 父 母的,有 欺压 寄居的, 有亏负 孤儿 寡妇的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, '你藐视了 我的圣物,干犯了 我的安息日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, '在你中间 有 谗谤人、 流 人血的;有在 山 上 吃过祭偶像之物的,有行 淫乱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, '在你中间 有露 继母下体羞辱 父亲的, 有玷辱 月经 不洁净之妇人的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, '这人 与 邻舍 的妻 行 可憎的事;那人 贪淫 玷污 儿妇; 还有玷辱 同父 之姊妹的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, '在你中间 有为 流 人血 受 贿赂的;有向借钱的弟兄取 利,向借粮的弟兄多要的。且因贪得无餍,欺压 邻舍 夺取财物,竟忘了 我。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, '「看哪,我因 你 所得 不义之财 和 你中间 所 流 的血,就拍 掌叹息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, '到了 我 惩罚 你 的日子,你的心 还能忍受吗?你的手 还能 有力吗?我─耶和华 说了这话,就必照著行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, '我必将你 分散 在列国,四散 在列邦。我也必从你中间 除掉 你的污秽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, '你必在列国人 的眼前 因自己 所行的被亵渎,你就知道 我 是耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, '「人 子啊,以色列 家 在我 看为 渣滓。他们都 是炉 中 的铜、锡、铁、铅,都是 银 渣滓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, '所以 主 耶和华 如此 说:因 你们都 成为 渣滓, 我 必聚集 你们 在 耶路撒冷 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, '人怎样将银、铜、铁、铅、锡 聚 在 炉 中,吹 火 镕化;照样,我也要发怒气 和忿怒,将你们聚集 放在城中,镕化 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, '我必聚集 你们,把我烈怒 的火 吹 在你们身上,你们就在其中 镕化。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, '银子 怎样镕化 在炉 中,你们也必照样 镕化 在城中,你们就知道 我─耶和华 是将忿怒 倒 在你们身上了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, '「人 子啊,你 要对这地 说:你是 未 得洁净 之地,在恼恨 的日子 也没有 雨下在你以上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, '其中 的先知 同谋背叛,如咆哮的 狮子 抓撕 掠物。他们吞灭 人民,抢夺 财 宝,使这地 多 有寡妇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, '其中的祭司 强解 我的律法,亵渎 我的圣物,不 分别 圣的 和俗的,也不 使人分辨 洁净的 和不洁净的,又遮 眼 不顾我的安息日;我也在他们中间 被亵慢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, '其中 的首领 仿佛豺狼 抓撕 掠物,杀人流 血,伤害 人命,要 得 不义之财。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, '其中的先知 为百姓 用未泡透的 灰抹墙,就是为他们 见 虚假的异象,用谎诈 的占卜,说:『主 耶和华 如此 说』,其实耶和华 没有 说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, '国 内众民 一味地 欺压,惯行 抢夺,亏负 困苦 穷乏的,背 理 欺压 寄居的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, '我在他们中间 寻找 一人 重修 墙垣,在我面前 为 这国 站 在破口防堵,使我不 灭绝这国,却找 不著一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, '所以我将恼恨 倒 在他们身上,用烈怒 的火 灭了他们,照他们所行的 报应 在他们头上。这是主 耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, '耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, '「人 子啊,有 两个 女子,是一 母 所生, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, '她们在埃及 行邪淫,在幼年 时行邪淫。她们在那里 作处女的时候,有人拥抱 她们的怀, 抚摸 她们的乳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, '她们的名字,姊姊 名叫阿荷拉,妹妹 名叫阿荷利巴。她们都归 于 我,生了 儿 女。论到她们的名字,阿荷拉 就是撒马利亚,阿荷利巴 就是耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, '「阿荷拉 归我 之后行邪淫,贪恋 所爱的人,就是 她的邻邦 亚述人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, '这些人都穿 蓝衣,作省长、副省长, 都 骑著 马,是可爱的 少年人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, '阿荷拉就与 亚述 人中 最美的 男子放纵 淫行,她因 所 恋爱 之人的一切 偶像,玷污自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, '自从在埃及的时候,她就没有 离开  淫乱,因为 她年幼 作处女的时候,埃及人与她 行淫, 抚摸 她的乳,纵欲 与她 行淫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, '因此,我将她交在 她所爱的人 手中,就是她所 恋爱的 亚述 人 手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, '他们 就露了 她的下体,掳掠 她的儿 女,用刀 杀了 她,使她 在妇女 中留下臭名,因他们向她 施行 审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, '她妹妹 阿荷利巴 虽然看见了,却还贪恋,比她 姊姊更丑;行 淫乱 比 她姊姊更多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, '她贪恋 邻邦的 亚述 人,就是穿 极华美的衣服, 骑 著马 的省长、副省长,都是 可爱的 少年人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, '我看见 她被玷污了,她姊妹二 人同行一 路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, '阿荷利巴又加增 淫行,因她看见 人 像画 划 在 墙上,就是用丹色 所画 划 迦勒底人 的像, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, '腰间 系著 带子,头上 有下垂的 裹头巾,都 是军长 的形状,仿照巴比伦 人 的形像;他们的故 土 就是迦勒底。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, '阿荷利巴一 看见 就贪恋 他们,打发 使者 往迦勒底 去见他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, '巴比伦 人 就来 登 她爱情 的床,与她 行淫 玷污她。她被玷污,随后心里 与他们 生疏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, '这样,她显露 淫行,又显露 下体;我心 就与她 生疏, 像 先前与 她姊姊 生疏一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, '她还加增 她的淫行,追念 她幼年 在埃及 地 行邪淫的 日子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, '贪恋 情人 身 壮精足,如 驴 如 马。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, '这样,你就想起 你幼年 的淫行。那时,埃及人 拥抱你 的怀, 抚摸 你的乳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, ' 阿荷利巴啊,主 耶和华 如此 说:「我 必激动 你先爱 而后 生疏的 人 来攻击你。我必使他们来,在你四围 攻击你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, '所来的就是巴比伦 人、迦勒底 的众人、比割人、书亚人、哥亚人,同著他们 的还有亚述 众 人,乃是作省长、副省长、作军长 有名声的,都 骑著 马,是 可爱的 少年人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, '他们必带兵器、战 车、辎重车,率领 大 众 来攻击你。他们要拿大小盾牌,顶盔 摆 阵,在你四围 攻击你。我要将 审判 的事交给他们,他们必按著自己的条例 审判你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, '我必以 忌恨 攻击你;他们必以忿怒 办 你。他们必割去 你的鼻子 和耳朵;你遗留(或译:余 馀剩;下同)的人必倒 在刀下。他们 必掳去 你的儿 女;你所遗留的 必被火 焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, '他们必剥去 你的衣服,夺取 你华美的 宝器。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, '这样,我必使你 的淫行 和 你从埃及 地 染来的淫乱 止息了,使你不 再仰 望 亚述,也不 再 追念 埃及。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, ' 主 耶和华 如此 说:我 必将你交在 你所 恨恶的 人手中,就是 你心 与他 生疏 的人手中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, '他们必以恨恶 办 你,夺取 你一切 劳碌得来的,留下你 赤身 露体。你淫乱的 下体,连你的淫行,带你的淫乱,都被显露。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, '人必向你 行 这些事;因 为 你随从 外邦人 行邪淫,被他们的偶像 玷污了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, '你走了你姊姊 所走的 路,所以我必将她的杯 交 在你手中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, '主 耶和华 如此 说:你必喝 你姊姊 所喝的杯;那杯又深 又广,盛得 甚多,使你 被人嗤笑 讥刺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, '你必酩酊大醉,满有 愁苦,喝干你姊姊 撒马利亚 的杯,就是令人惊骇 凄凉 的杯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, '你必喝 这杯,以致喝尽。杯破 又 龈杯片,撕裂 自己的乳;因为 这事我 曾说过。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, ' 主 耶和华 如此 说:「因 你忘记 我,将我 丢 在背 后,所以 你 要担当 你淫行 和 淫乱的报应。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, '耶和华 又对我 说:「人 子啊,你要审问 阿荷拉 与 阿荷利巴吗?当指出 她们 所行可憎的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, ' 她们行淫,手 中有杀人的血,又与 偶像 行淫,并 使 她们为我 所 生的 儿 女经 火烧给偶像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, '此外,她们还有向我 所行的,就是 同 日 玷污 我的圣所,干犯 我的安息日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, '她们杀了 儿女 献与偶像,当 天 又入 我的圣所,将圣所亵渎了。 她们在我殿 中 所行的 乃是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, '「况且 你们二妇打发 使者 去 请远方 人。使者 到 他们那里, 他们就来了。你们为他们 沐浴己身,粉饰 眼目,佩戴 妆饰, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, '坐 在 华美的 床上,前面 摆设 桌案,将我的香料 膏油 摆 在其上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, '在那里 有群众 安逸 欢乐的声音,并有 粗俗的 人 和酒徒 从旷野 同来,把镯子 戴 在 二妇的手上,把华 冠 戴在 她们的头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, '「我论这行淫 衰老的妇人 说:现在 人还要与她行 淫,她也要与人行淫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, '人 与 阿荷拉,并 阿荷利巴 二淫 妇 茍合,好像与 妓 女 苟合。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, '必有义 人, 照审判淫妇 和流 人血 的妇人之例,审判 她们;因为 她们 是淫妇,手 中有杀人的血。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, ' 主 耶和华 如此 说:「我必使 多人 来攻击她们,使 她们 抛来抛去,被人抢夺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, '这些人 必用石头 打死 她们,用刀剑 杀害 她们,又杀戮 她们的儿 女,用火 焚烧 她们的房屋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, '这样,我必使淫行 从 境内 止息,好叫一切 妇人 都受警戒,不 效法 你们的淫行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, '人必照著你们的淫行 报应 你们;你们要担当 拜偶像 的罪,就知道 我 是主 耶和华。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, '第九 年 十 月 初 十日,耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, '「人 子啊, 今 日 正是 巴比伦 王 就近 耶路撒冷的 日子,你要将 这 日 记下, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, '要向 这悖逆 之家 设 比喻 说,主 耶和华 如此 说:将锅 放在火上,放好了,就 倒 水 在其中; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, '将肉块,就是一切 肥美的 肉块、腿,和肩 都聚 在其中,拿美好的 骨头 把锅装满; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, '取 羊群 中最好的, 将柴 堆 在锅下,使锅开  滚, 好把骨头 煮在 其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, '「 主 耶和华 如此 说:祸哉!这流人血的 城,就是 长锈的 锅。其中的锈 未曾 除掉,须要将肉块从其中一一 取出来,不必 为它 拈 阄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, ' 城中 所流的血 倒 在 净光的 磐石上,不 倒 在 地上,用土 掩盖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, '这城中所 流的血 倒 在 净光的 磐石上,不得 掩盖,乃是出于 我,为要发 忿怒 施行 报应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, '所以 主 耶和华 如此 说:祸哉!这流人血的 城,我 也 必大堆 火柴, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, '添上 木柴,使火 著旺,将肉 煮烂,把汤熬 浓,使骨头 烤焦; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, '把锅倒空 坐 在 炭火上,使 锅烧热,使铜 烧红,镕化 其中 的污秽,除净 其上的锈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, '这锅劳碌 疲乏,所长的大 锈 仍未 除掉;这锈 就是用火也不能除掉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, '在你污秽 中有淫行, 我洁净你,你却不 洁净。你的污秽 再 不能 洁净,直等 我向你发的 忿怒 止息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, '我─耶和华 说过的 必定成就,必照话而行,必不 返回,必不 顾惜,也不 后悔。人必照你的举动 行为 审判你。这是主 耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, '耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, '「人 子啊,我 要将 你眼目 所喜爱的 忽然 取去,你却不可 悲哀 哭泣,也不可 流 泪, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, '只可叹息,不可出声,不可 办理 丧 事;头上 仍勒 裹头巾,脚 上仍穿 鞋,不可 蒙 著 嘴唇,也不可 吃 吊丧的 食物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, '于 是我将这事早晨 告诉 百姓,晚上 我的妻 就死了。次日早晨 我便遵 命 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, '百姓 问我 说:「 你 这样 行 与我们 有什么关系,你不 告诉 我们么?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, '我回答他们:「耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, '『你告诉 以色列 家,主 耶和华 如此 说:我 必使 我的圣所,就是你们势力 所夸耀、眼里 所喜爱、心中 所爱惜的 被亵渎,并且你们所 遗留的 儿 女 必倒 在刀下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, '那时,你们必行 我仆人所 行的,不 蒙 著 嘴唇,也不 吃 吊丧的 食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, '你们仍要头 上 勒裹头巾,脚 上穿鞋;不可 悲哀 哭泣。你们必因自己的罪孽 相对 叹息,渐渐消灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, '以西结 必这样为你们 作 预兆;凡 他所 行的,你们也必照样行。那事来到,你们就知道 我 是主 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, '「 人 子啊, 我除掉 他们 所倚靠、所欢喜的 荣耀,并眼中 所喜爱、心里 所重看的 儿 女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, '那 日 逃脱的人 岂不来 到你这里,使你耳 闻这事吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, ' 你必向 逃脱的人 开  口 说话,不 再 哑口。你必这样为他们 作 预兆,他们就知道 我 是耶和华。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, '「人 子啊,你要 面 向 亚扪 人 说预言,攻击他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, '说:你们当听 主 耶和华 的话。主 耶和华 如此 说:我的圣所 被亵渎, 以色列 地 变荒凉, 犹大 家 被 掳掠;那时, 你便因 这些事说:『阿哈!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, '所以 我 必将你的地交 给东方 人 为业;他们必在你的地上 安 营 居 住, 吃 你的果子, 喝 你的奶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, '我必 使 拉巴 为骆驼 场,使 亚扪 人 的地为羊群 躺卧之处,你们就知道 我 是耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, ' 主 耶和华 如此 说:「因 你拍 手 顿 足,以满心的 恨恶 向 以色列 地 欢喜, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, '所以 我 伸 手 攻击你,将你交 给列国 作为掳物。我必从 万民 中剪除你,使你从 万国 中败亡。我必除灭你,你就知道 我 是耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, '主 耶和华 如此 说:「因 摩押 和西珥人 说:『看哪,犹大 家 与列 国无异』, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, '所以 我 要破开  摩押 边 界上 的城 邑,就是摩押人看为本国 之荣耀的伯‧耶西末、巴力‧免、基列亭, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, '好使东方 人 来攻击 亚扪 人。我必将亚扪人之地交 给他们为业,使 亚扪 人 在列国 中不再 被记念。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, '我必向摩押 施行 审判,他们就知道 我 是耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, '主 耶和华 如此 说:「因为 以东 报仇 雪恨,攻击 犹大 家,向他们 报仇,大大 有罪, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, '所以 主 耶和华 如此 说:我必伸 手 攻击 以东,剪除 人 与牲畜,使以东从提幔起,人必倒 在刀下,地要变为 荒凉,直到底但。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, '我必藉 借我民 以色列 的手 报 复 以东;以色列民必照我的怒气,按我的忿怒 在以东 施报,以东人就知道 是我施报。这是主 耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, '主 耶和华 如此 说:「因 非利士人 向犹大人报 仇,就是以恨恶的 心 报仇 雪恨,永怀 仇恨,要毁灭他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, '所以 主 耶和华 如此 说:我 必伸 手 攻击 非利士人,剪除 基利提人,灭绝 沿 海 剩下的居民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, '我向他们 大 施 报应,发怒 斥责他们。我报 复 他们的时候,他们就知道 我 是耶和华。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, ' 第十一 年 十一月 初一日,耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, '「人 子啊,因 泰尔 向 耶路撒冷 说:『阿哈,那作众民 之门 的已经破坏,向我 开 放;她既变为荒场,我必丰盛。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, '所以,主 耶和华 如此 说:泰尔啊,我 必与你为敌,使许多 国民 上来 攻击你,如同海 使波浪 涌上来一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, '他们必破坏 泰尔 的墙垣,拆毁 她的城楼。我也要刮净 尘土,使她 成为 净光的 磐石。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, '她必在海 中 作 晒 网的地方,也必成为 列国 的掳物。 这是 主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, '属泰尔城邑的居民(原文是田间 的众女;八节同)必被刀剑 杀灭,他们就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, ' 主 耶和华 如此 说:「我 必使诸王 之王 的巴比伦 王 尼布甲尼撒 率领马匹 车辆、马兵、军队,和许多 人民 从北方 来 攻击 你泰尔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, '他必用刀剑 杀灭 属你城邑 的居民,也必造 台 筑 垒 举 盾牌 攻击你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, '他必安设 撞城 锤 攻破你的墙垣,用铁器 拆毁 你的城楼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, '因他的马匹 众多,尘土 扬起遮蔽你。他进 入你的城门,好像人进入 已有破口 之城。那时,你的墙垣 必因骑马的 和战 车、辎重车 的响声 震动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, '他的马 蹄 必践踏 你一切 的街道,他必用刀 杀戮 你的居民;你坚固的 柱子(或译:柱像)必倒 在地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, '人必以你的财宝 为掳物,以你的货财 为掠物,破坏 你的墙垣,拆毁 你华美的 房屋,将你的石头、木头、尘土 都抛 在水 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, '我必使你唱歌 的声音 止息,人也不 再 听见 你弹琴 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, '我必 使你成为净光的 磐石,作 晒 网 的地方;你不 得再 被建造,因为 这是 主 耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, '主 耶和华 对泰尔 如此 说:「在你中间 行 杀戮,受伤之人 唉哼的时候,因你倾倒的 响声,海岛 岂不 都震动吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, '那时靠海 的君王 必都 下 位,除去 朝服,脱下 花 衣,披上 战 兢,坐 在 地上,时刻 发抖,为你 惊骇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, '他们必为你 作起 哀歌 说:你这有名 之城,素为航海之人 居住, 在海上 为 最坚固的; 平日你 和居民 使 一切 住 在那里的人 无不惊恐;现在何竟 毁灭了? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, '如今 在你这倾覆 复 的日子,海岛 都必战 兢; 海 中的群岛 见你归于  无有就都惊惶。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, ' 主 耶和华 如此 说:「泰尔啊,我使 你 变为 荒凉, 如无人 居住的 城邑;又使 深水 漫 过你,大 水 淹没你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, '那时,我要叫你下 入 阴府,与 古时 的人 一同在地 的深处、久 已荒凉 之地居住, 使 你不 再有居民。我也要在活人 之地 显 荣耀(我也......荣耀:或译在活人之地不再有荣耀)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, '我必叫你 令人惊恐,不再存留于 世;人虽寻找你,却永 寻 不见。这是主 耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, '耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, '「 人 子啊,要为 泰尔 作起 哀歌, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, '说:你居住 海 口,是众民 的商埠;你的交易通到 许多 的海岛。主 耶和华 如此 说:泰尔啊,你 曾说:我 是全然 美丽的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, '你的境界 在海 中,造你的 使你全然 美丽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, '他们用示尼珥的 松树 做 你的一切 板,用 黎巴嫩的 香柏树 做 桅杆, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, '用巴珊的 橡树 做 你的桨,用象牙 镶嵌 基提 海岛的 黄杨木 为坐板(或译:舱板)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, '你的篷帆 是 用埃及 绣花 细麻布做的,可以做 你的 大旗;你的凉棚 是 用以利沙 岛 的蓝色、紫色布做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, '西顿 和亚发 的居民 作 你 荡桨的。泰尔啊,你中间 的智慧人 作 掌舵的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, '迦巴勒 的老者 和聪明人 都在你中间 作 补缝的;一切 泛海 的船只 和水手都 在你中间 经营 交易的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, '「波斯人、路德人、弗人 在你军营 中作 战  士;他们 在你中间 悬挂 盾牌 和头盔,彰显 你的尊荣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, '亚发 人 和你的军队 都在 你四围 的墙上,你的望楼 也有 勇士;他们悬挂 盾牌, 成全 你的美丽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, '「他施人 因你多有 各类的 财物,就作你的客商,拿银、铁、锡、铅 兑换 你的货物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, '雅完人、土巴人、米设人 都 与你交易;他们用人 口 和铜 器 兑换 你的货物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, '陀迦玛 族 用马 和战 马 并骡子 兑换 你的货物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, '底但 人 与你交易,许多 海岛 作你的码头;他们拿 象牙、乌木 与你兑换(或译:进贡)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, '亚兰人 因你的工作 很多,就作你的客商;他们用 绿宝石、紫色 布绣货、细麻布、珊瑚、红宝石 兑换你的货物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, '犹大 和以色列 地 的人都 与你交易;他们用米匿 的麦子、饼、蜜、油、乳香 兑换 你的货物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, '大马士革人 因你的工作 很多,又因你多 有各类 的财物,就拿黑本 酒 和白 羊毛 与你交易。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, '威但人 和雅完人 拿纺成的线 缐、亮 铁、桂皮、菖蒲 兑换 你的货物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, '底但人 用高贵的 毯子、鞍、屉与你交易。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, '阿拉伯人 和基达 的一切 首领 都 作你的 客商,用羊羔、公绵羊、公山羊 与你交易。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, '示巴 和拉玛 的商人 与你交易,他们 用各类 上好的 香料、各类的 宝 石,和黄金 兑换 你的货物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, '哈兰人、干尼人、伊甸人、示巴 的商人,和亚述人、基抹人 与你交易。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, '这些 商人 以美好的货物 包在绣花 蓝色 包袱内,又有华丽的衣服 装在香柏木 的箱子里,用绳 捆著 与你交易。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, '他施 的船只 接连成帮为你运 货,你便在海 中 丰富 极其 荣华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, '荡桨的 已经把你 荡到 大 水之处,东 风 在海 中 将你打破。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, '你的资财、物件、货物、水手、掌舵的、补缝的、经营 交易的,并 你中间的 战  士 和 人民,在你破坏的 日子 必都沉 在海 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, '你掌舵的 呼号 之声一发,郊野 都必震动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, '凡 荡 桨 的和水手,并一切 泛海 掌舵的,都必下 船 登 岸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, '他们必为你 放 声 痛 哭,把尘土 撒 在 头上,在灰中 打滚; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, '又为你 使 头上光秃,用麻布 束腰,号咷 痛 哭,苦苦 悲哀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, '他们哀号的时候,为你 作起 哀歌 哀哭,说:有何城 如泰尔?有何城如他在海 中 成为寂寞的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, '你由海上 运出 货物,就使许多 国民 充足;你以许多 资财、货物 使地上 的君王 丰富。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, '你在深 水 中被海浪 打破的 时候,你的货物 和你中间的 一切 人民,就都沉下去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, '海岛的 居民 为你 惊奇;他们的君王 都甚恐 慌,面 带愁容。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, '各国民中 的客商 都向你 发嘶声;你 令人惊恐,不再存留于 世,直到 永远。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, '耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, '「人 子啊,你对泰尔 君王 说,主 耶和华 如此 说:因 你心里 高傲,说:我 是神;我在海 中 坐 神 之位。你 虽然居 心 自比神,也不过是人,并不是 神! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, '看哪,你 比但以理 更有智慧,什么 秘事 都不能 向你隐藏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, '你靠自己的智慧 聪明 得了 金 银 财宝,收入 库中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, '你靠自己的大 智慧 和贸易 增添 资财,又因资财 心里 高傲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, '「所以 主 耶和华 如此 说:因 你居 心 自比 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, ' 我 必使 外邦人,就是列国 中的强暴人 临到你这里;他们必拔 刀 砍坏 你用智慧 得来的美物,亵渎 你的荣光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, '他们必使你下 坑;你必死 在海 中,与被杀的 人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, '在杀 你的人面前 你还 能说「我是 神」吗?其实你 在杀害 你的人手中,不过是人,并不是 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, '你必死 在外邦人 手中,与未受割礼(或译:不洁;下同)的人一样,因为 这是主 耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, '「人 子啊,你为 泰尔 王 作起 哀歌,说 主 耶和华 如此 说:你 无所不 备,智慧 充足,全然 美丽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, '你曾 在伊甸 神 的园中,佩戴 各样 宝 石,就是红宝石、红璧玺、金钢石、水苍玉、红玛瑙、碧玉、蓝宝石、绿宝石、红玉,和黄金;又有精美的 鼓 笛 在你那里,都是在你受造 之日 预备齐全的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, '你 是那受膏 遮掩 约柜的基路伯;我将你 安置在 神 的圣 山上;你在发光如火 的宝石 中间 往来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, '你 从受造 之日 所行的 都完全,后来 在你中间 又察出 不义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, '因你贸易 很多,就被强暴 的事 充满,以致犯罪,所以我因你亵渎圣地,就从 神 的山 驱逐你。遮掩 约柜的基路伯啊,我已将你从发光如火 的宝石 中 除灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, '你因美丽 心 中高傲,又因 荣光 败坏 智慧,我已将你摔倒 在 地,使你倒 在君王 面前,好叫他们目睹眼见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, '你因罪孽 众多,贸易 不公,就亵渎 你那里的圣所。故此,我使火 从你中间 发出, 烧灭你,使你 在所有 观看 的人眼前 变为 地 上的炉灰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, '各国民中,凡 认识你的,都必为你 惊奇。你令人 惊恐,不再存留于 世,直到 永远。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, '「人 子啊,你要 向 西顿 预言 攻击她, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, '说 主 耶和华 如此 说:西顿哪,我 与你为敌,我必在你中间 得荣耀。我在你中间 施行 审判、显为圣的时候,人就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, '我必使 瘟疫 进入西顿,使血 流在她街上。被杀的 必在其中 仆倒,四围 有刀剑 临到她,人就知道 我 是耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, '「 四围 恨恶 以色列 家的人,必不 再 向他们 作 刺人的 荆棘,伤人的 蒺藜,人就知道 我 是主 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, '主 耶和华 如此 说:「我将 分散 在万民 中 的 以色列 家 招聚回来,向他们在列邦人 眼前 显为圣的时候,他们就在我 赐 给我仆人 雅各 之地,仍然居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, '他们要在 这地上安然 居住。我向四围 恨恶 他们 的众人 施行 审判以后,他们要盖造 房屋,栽种 葡萄园,安然 居住,就知道 我 是耶和华─他们的 神。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, '第十 年 十 月 十 二日,耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, '「人 子啊,你要 向 埃及 王 法老 预言 攻击他 和 埃及 全地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, '说 主 耶和华 如此 说:埃及 王 法老啊,我 与你 这卧在 自己河 中 的大 鱼为敌。你 曾说:这河 是我的,是我 为自己造的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, '我─耶和华必用 钩子 钩住 你的腮颊,又使江河 中的鱼 贴 住你的鳞甲;我必将 你和所有 贴 住你鳞甲 的鱼,从江河 中 拉上来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, '把你 并 江河 中的鱼 都 抛 在旷野;你必倒 在 田 间,不 被收殓,不 被掩埋。我已将你给 地上 野兽、空中 飞鸟 作食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, '「埃及 一切的 居民,因 向以色列 家 成了 芦苇 的杖,就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, '他们用手 持住 你,你就断折,伤了 他们的 肩;他们倚靠 你,你就断折,闪了 他们的 腰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, '所以 主 耶和华 如此 说:我 必使 刀剑 临到你,从你中间 将人 与牲畜 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, '埃及 地 必 荒废 凄凉,他们就知道 我 是耶和华。「因为 法老说:『这河 是我的,是我 所造的』, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, '所以 我 必与你 并 你的江河为敌, 使 埃及 地,从色弗尼 塔 直到 古实 境界,全然 荒废 凄凉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, '人 的脚、兽 的蹄 都不 经过,四十 年之 久并无人 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, '我必 使 埃及 地 在荒凉的 国 中 成为荒凉,使埃及城 在荒废的 城 中 变为 荒废,共有四十 年。我必将 埃及人 分散 在列国,四散 在列邦。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, ' 主 耶和华 如此 说:「满了 四十 年,我必招聚 分散 在各国民 中的 埃及人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, '我必叫 埃及 被掳的人 回来,使他们 归 回 本 地 巴忒罗。在那里 必成为 低微的 国, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, '必为 列国 中 最低微的,也不 再 自高 于  列国之上。我必减少他们,以致不 再辖制 列国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, '埃及必不 再 作 以色列 家 所倚靠的;以色列家仰望 埃及人的时候,便思念 罪孽。他们就知道 我 是主 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, ' 二十 七 年 正 月 初一日,耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, '「人 子啊,巴比伦 王 尼布甲尼撒 使 他的军兵 大大 效 劳,攻打 泰尔,以致头 都 光秃,肩 都 磨破;然而他 和他的军兵 攻打泰尔, 并没 有 从那里 得什么酬劳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, '所以 主 耶和华 如此 说:我 必将 埃及 地 赐 给巴比伦 王 尼布甲尼撒;他必掳掠 埃及群众,抢 其中的财为掳物,夺 其中的货为掠物,这就可以作 他军兵的 酬劳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, '我将 埃及 地 赐 给他,酬他所 效的 劳,因 王与军兵是为我 勤劳。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, '「当那 日,我必使以色列 家的 角 发生,又必使 你─以西结在他们中间 得以开  口;他们就知道 我 是耶和华。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, '耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, '「人 子啊,你要发预言 说,主 耶和华 如此 说:哀哉 这日!你们应当哭号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, '因为 耶和华的 日子 临近,就是密云 之日, 列国 受罚之期。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, '必有刀剑 临 到埃及;在埃及 被杀之人 仆倒的时候,古实人 就有 痛苦,人民 必被掳掠,基址 必被拆毁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, '古实人、弗人(或译:利比亚)、路德人、 杂族的人民,并古巴人,以及同盟 之地 的人 都要与埃及人 一同倒 在刀下。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, '耶和华 如此 说:扶助 埃及 的也必倾倒。埃及因势力 而有的骄傲 必降低微;其中的人民,从色弗尼 塔起(见二十九章十节)必倒 在刀下。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, '埃及地在荒凉的 国 中 必成为荒凉;埃及城 在荒废的 城 中 也变为荒废。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, '我在埃及 中使 火著起;帮助埃及的,都 被灭绝。那时,他们就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, '「到那 日,必有使者 坐船,从我面前 出去,使 安逸无虑 的古实人 惊惧;必有痛苦 临 到他们,好像埃及 遭灾的日子一样。 看哪,这事临近了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, '主 耶和华 如此 说:我必藉 借巴比伦 王 尼布甲尼撒 的手,除灭 埃及 众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, '他 和随从他 的人,就是列国 中强暴的,必进来 毁灭 这地。他们必拔 刀 攻击 埃及,使 遍地 有 被杀的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, '我必使 江河 干涸,将 地 卖 在恶 人的手中;我必藉 借外邦人 的手,使这地 和其中所有的 变为凄凉。这是我─耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, '主 耶和华 如此 说:我必毁灭 偶像,从挪弗 除灭 神像;必不 再 有 君王 出自埃及 地。我要使 埃及 地 的人惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, '我必使 巴忒罗 荒凉,在琐安 中使 火著起,向挪 施行 审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, '我必将我的忿怒 倒 在 埃及 的保障上,就是训上,并要剪除 挪 的众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, '我必在埃及 中使 火著起;训 必大大 痛苦;挪 必 被攻破;挪弗白日(或译:终日)见仇敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, '亚文 和比伯实 的少年人 必倒 在刀下;这些城的人 必被 掳掠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, '我在答比匿 折断 埃及 的诸轭,使她因势力 而有的骄傲 在其中 止息。那时,日光 必退去;至于 这城,必有密云 遮蔽,其中的女子 必被 掳掠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, '我必这样向埃及 施行 审判,他们就知道 我 是耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, ' 十 一 年 正 月 初七日,耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, '「人 子啊,我已打折 埃及 王 法老 的膀臂; 没有 敷药,也没有用 布 缠好,使他有力 持 刀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, '所以 主 耶和华 如此 说:看哪,我 与 埃及 王 法老为敌,必将 他有力的 膀臂 和 已打折的 膀臂全行打断,使 刀 从他手中 坠落。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, '我必将 埃及人 分散 在列国,四散 在列邦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, '我必使 巴比伦 王 的膀臂 有力,将 我的刀 交 在他手中;却要打断 法老 的膀臂,他就在巴比伦王面前 唉哼,如同受死伤的人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, '我必扶持 巴比伦 王 的膀臂,法老 的膀臂 却要下垂;我将我的刀 交 在巴比伦 王 手中,他必举 刀 攻击 埃及 地,他们就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, '我必将 埃及人 分散 在列国,四散 在列邦;他们就知道 我 是耶和华。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, ' 十 一 年 三 月 初一日,耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, '「人 子啊,你要向 埃及 王 法老 和 他的众 人说:在威势 上 谁 能与你相比呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, ' 亚述 王曾如黎巴嫩 中的香柏树,枝条 荣美,影 密如林,极其高 大,树尖 插入 云中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, '众水 使它生长;深 水使它长大。所栽之地 有 江河 围 流,汊出的 水道 延到 田野 诸 树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, '所以 他高大 超过 田野 诸 树;发旺的时候,枝子 繁多,因得大 水 之力枝条 长长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, '空中 的飞鸟 都 在枝子 上搭窝;田野 的走兽 都 在枝条 下 生子;所有 大 国 的人民都在它荫下 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, '树大 条 长,成为荣美,因为 根 在 众 水之旁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, '神 园中 的香柏树 不能 遮蔽它;松树 不 及 它的枝子;枫树 不 及 它的枝条; 神 园 中的树 都 没 有 它 荣美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, '我使 它的枝条 蕃多,成为荣美,以致 神 伊甸 园中的 树 都 嫉妒它。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, '所以 主 耶和华 如此 说:「因 它高 大,树尖 插 入 云中,心 骄 气傲, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, '我就必将他交 给列国 中大有威势 的人;他必定 办 他。我因他的罪恶,已经驱逐他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, '外邦人,就是列邦 中强暴的,将它砍断 弃掉。它的枝条 落 在 山 间和一切 谷中,它的枝子 折断,落在地 的一切 河旁。地上 的众 民 已经走去,离开  它的荫下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, '空中 的飞鸟 都 要宿 在 这败落的树上,田野 的走兽 都 要 卧在 它的枝条下, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, '好使 水 旁的诸 树 不 因高大 而自尊,也不 将 树尖 插 入 云中,并且那些 得 水滋润、有势力的,也不 得高大 自立。因为 它们在世人 中,和 下 坑 的人都 被交 与死亡,到 阴府去了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, '主 耶和华 如此 说:「它下 阴间 的那日,我便使人悲哀。我为它 遮盖 深渊,使江河 凝结,大 水 停流;我也使黎巴嫩 为它 凄惨,田野 的诸 树 都因它 发昏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, '我将它 扔 到阴间,与 下 坑的人一同下去。那时,列国 听见它坠落 的响声 就都震动,并且伊甸 的一切 树─就是黎巴嫩 得 水滋润、最佳 最美的树─都 在阴府 受了安慰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, '它们 也 与它 同下 阴间,到 被杀的人那里。它们曾作它的膀臂,在列国 中 它的荫下 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, '在这样 荣耀 威势上,在伊甸园 诸树中,谁 能与 你相比呢?然而你要与 伊甸 的诸树 一同下 到 阴府,在未受割礼 的人中,与 被杀的人 一同躺卧。法老 和他的群 众 乃是如此。这是主 耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, ' 十 二 年 十 二 月 初 一日,耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, '「人 子啊,你要为 埃及 王 法老 作 哀歌,说:从前你在列国中,如同 少壮狮子;现在你 却像海中 的大鱼。你冲出 江河,用爪 搅动 诸水,使江河 浑浊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, '主 耶和华 如此 说:我必用多 国 的人民,将 我的网 撒 在你身上,把你拉上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, '我必将你丢 在地上,抛 在 田野,使空中 的飞鸟 都 落 在你身上,使遍 地 的野兽 吃你 得饱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, '我必将 你的肉 丢 在 山间,用你高大的尸首 填满 山谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, '我又必用你的血 浇灌 你所游泳 之地,漫过 山顶;河道 都必充满。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, '我将你扑灭的时候,要把天 遮蔽,使 众星 昏暗,以密云 遮掩 太阳,月亮 也不 放 光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, '我必使天上 的亮 光 都 在你以上 变为昏暗,使 你的地上 黑暗。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, '「我使你败亡 的风声传 到 你所 不 认识 的各国。那时,我必使多 民 的心 因你愁烦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, '我在 许多 国民 和君王 面前 向你 抡 我的刀,国民就必因你 惊奇,君王也必因你极其恐慌。在你仆倒 的日子,他们各人 为自己的性命 时刻 战 兢。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, ' 主 耶和华 如此 说:「巴比伦 王 的刀 必临到你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, '我必藉 借勇士 的刀 使你的众民 仆倒;这勇士都是 列国 中强暴的。他们必使 埃及 的骄傲 归于 无有;埃及的众 民 必被灭绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, '我必从 埃及多 水 旁除灭 所有的 走兽;人 脚 兽 蹄 必不 再 搅浑这水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, '那时,我必使埃及河 澄清,江河 像油 缓流。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, '我使 埃及 地 变为 荒废凄凉;这地 缺少 从前所充满的,又击杀 其中 一切 的居民。那时,他们就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, '「人必用 这 哀歌 去哀哭,列国 的女子 为 埃及 和 她的群 众 也必以此 悲哀。这是主 耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, ' 十 二 年 十二月 十 五日,耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, '「人 子啊,你要为 埃及 群众 哀号,又要将 埃及和有名 之国 的女子,并 下 坑的人,一同扔 到 阴 府去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, '你埃及的美丽 胜过谁呢?你下去 与 未受割礼的人 一同躺卧吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, '他们必在被杀 的人中 仆到。她被交 给刀剑,要把她 和她的群 众 拉去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, '强盛的 勇士 要在 阴间 对 埃及王和 帮助他的 说话;他们是未受割礼 被杀的人,已经下去,躺卧不动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, '「亚述 和她的众 民 都在那里,她民的坟墓 在她四围;他们都 是被杀 倒 在刀下的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, '他们 的坟墓 在坑 中极深之处。他的众民 在 他坟墓 的四围,都是 被杀 倒 在刀下的;他们 曾在活人 之地 使 人惊恐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, '「以拦 也在那里,她的群 众 在她坟墓 的四围,都是 被杀 倒 在刀下、未受割礼 而下 阴 府的;他们 曾在活人 之地 使 人惊恐,并且与 下 坑 的人一同担当 羞辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, '人给她 和她的群 众 在被杀 的人中 设立 床榻。她民的坟墓 在她四围,他们都是 未受割礼 被刀 杀的;他们曾 在活人 之地 使 人惊恐,并且与 下 坑 的人一同担当 羞辱。以拦已经放 在被杀 的人中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, '「米设、土巴,和她们的群 众 都在那里。她民的坟墓 在她四围,他们都是 未受割礼 被刀 杀的;他们曾 在活人 之地 使 人惊恐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, '他们不 得与 那未受割礼 仆倒 的勇士 一同躺卧;这些勇士 带著兵 器 下 阴间, 头 枕 刀剑, 骨头 上有 本身的罪孽;他们曾 在活人 之地 使勇士 惊恐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, '「法老啊,你 必在未受割礼 的人中 败坏,与 那些被杀 的人一同躺卧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, '「以东 也在那里。她君王 和一切 首领 虽然 仗著势力,还是放 在被杀的人中;他们 必与 未受割礼 的 和下 坑 的人一同躺卧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, '「在那里 有北方 的众 王子 和一切 西顿人,都 与 被杀 的人下去。他们虽然仗著势力 使人惊恐,还是蒙羞。他们未受割礼,和 被刀 杀 的一同躺卧,与 下 坑 的人一同担当 羞辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, '「法老 看见 他们,便为 他被杀的 军队 受安慰。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, ' 我任凭 法老在活人 之地 使人惊恐,法老 和他的群 众 必放 在未受割礼 和 被杀 的人中。这是主 耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, '「人 子啊,你要告诉 本国 的子民 说: 我使刀剑 临 到 哪一国,那一国 的民 从他们中间 选 立 一 人 为守望的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, '他见 刀剑 临 到 那地,若吹 角 警戒 众民, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, '凡 听见 角 声 不 受警戒的,刀剑 若来 除灭了他,他的罪(原文是血)就必归到 自己的头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, '他听见 角 声,不 受警戒,他的罪 必归 到自己的身上;他 若受警戒,便是救 了自己的性命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, '倘若 守望的人 见 刀剑 临到,不 吹 角,以致民 不 受警戒,刀剑 来 杀了 他们 中间的一个人,他 虽然死 在罪孽之中,我却要向守望的人 讨他丧命的罪(原文是血)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, '「 人 子啊,我照样立你 作以色列 家 守望的人。所以你要听 我口 中的话,替我 警戒 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, '我对恶人 说:『恶人哪,你必要 死!』你─以西结若不 开 口 警戒 恶人,使他离开 所行的道,这 恶人 必死 在罪孽之中,我却要向你 讨他丧命的罪(原文是血)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, '倘若 你 警戒 恶人 转离所 行的道,他仍不 转离,他必 死 在罪孽之中,你 却救 自己脱离了罪。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, '「人 子啊,你 要对 以色列 家 说:你们常 说:『 我们的过犯 罪恶 在我们身上,我们 必因此 消灭,怎能 存活呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, '你对他们 说,主 耶和华说:我 指著我的永生 起誓,我断不 喜悦 恶人 死亡,惟 喜悦恶人 转离 所行的道 而活。以色列 家啊,你们转回,转回吧!离开 恶 道,何必 死亡呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, '人 子啊,你 要对 本国 的人民 说:义人 的义,在犯罪 之日 不能 救他;至于 恶人 的恶,在他转离 恶行 之日 也不能 使他倾倒;义人 在犯罪 之日 也不 能 因他的义存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, '我对义人 说:『你必定 存活!』他 若倚靠 他的义 而作 罪孽,他所行的义 都 不 被记念。他必因 所 作 的罪孽 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, '再者,我对恶人 说:『你必定 死亡!』他若转离 他的罪,行 正直 与合理的事: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, ' 还 人的当头 和 所抢夺的,遵行 生命 的律例,不 作 罪孽,他必定 存活,不致 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, '他所 犯 的一切 罪 必不 被记念。他行 了正直 与合理的事,必定 存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, '「你本国 的子民 还说:『主 的道 不 公平。』其实他们 的道 不 公平。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, '义人 转离 他的义 而作 罪孽,就必因此 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, '恶人 转离 他的恶,行 正直 与合理的事,就必 因此 存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, '你们还说:『主 的道 不 公平。』以色列 家啊,我必按你们各人 所行的 审判 你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, ' 我们被掳 之后十 二 年 十 月 初 五日,有人从耶路撒冷 逃 到 我这里,说:「城 已攻破。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, '逃来的人 未到 前 一日的晚上,耶和华的灵(原文是手)降 在我身上,开  我的口。到 第二日早晨,那人来 到我这里,我口 就开 了,不 再 缄默。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, '「人 子啊,住 在 以色列 荒废 之地 的人说:『亚伯拉罕 独自一 人能得 这地为业,我们 人数众多,这地 更是给 我们 为业的。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, '所以 你要对他们 说,主 耶和华 如此 说:你们吃 带 血的物, 仰望 偶像,并且杀人流 血,你们还能得 这地为业吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, '你们倚仗 自己的刀剑 行 可憎的事,人人 玷污 邻舍 的妻,你们还能得 这地为业吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, '你要对他们 这样 说,主 耶和华 如此说:我 指著我的永生起誓,在荒场 中的,必 倒 在刀下;在 田野 间的,必交 给野兽 吞吃;在保障 和洞 里的,必遭瘟疫 而死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, '我必 使 这地 荒凉,令人惊骇;她因势力 而有的骄傲 也必止息。以色列 的山 都必荒凉,无人 经过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, '我因 他们所 行 一切 可憎的事 使 地 荒凉,令人惊骇。那时,他们就知道 我 是耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, '「 人 子啊,你本国 的子民 在 墙垣 旁边、在房屋 门口 谈论 你。弟兄 对 弟兄 彼此 说:『 来吧!听听 有什么 话 从 耶和华 而出。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, '他们来 到你 这里如同民 来聚会,坐 在你面前 仿佛是我的民。他们听 你的话却 不 去行;因为 他们的口多 显 爱情,心 却追 随 财利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, '他们 看你 如善于  奏乐、声音 幽雅 之人所唱的雅 歌,他们听 你的话 却不 去行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, '看哪,所说的快要应验;应验了,他们就知道 在他们中间 有了 先知。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, '「人 子 啊,你要向 以色列 的牧人 发预言,攻击他们,说,主 耶和华 如此 说:祸哉!以色列 的牧人 只知牧养 自己。牧人 岂不 当牧养 群羊吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, '你们吃 脂油、穿 羊毛、宰 肥壮的,却不 牧养 群羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, ' 瘦弱的,你们没有 养壮; 有病的,你们没有 医治;受伤的,你们没有 缠裹; 被逐的,你们没有 领回; 失丧的,你们没有 寻找;但用强暴 严严地 辖制。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, '因无 牧人,羊就分散;既分散,便作了 一切 野兽的 食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, '我的羊 在诸 山间、在 各 高 冈 上流离, 在 全 地 上分散,无人 去寻,无人 去找。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, '「所以,你们这些牧人 要听 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, '主 耶和华 说:我 指著我的永生起誓,我的羊 因 无 牧人 就 成为 掠物, 也作了 一切 野兽 的食物。我的牧人 不 寻找 我的羊;这些牧人 只知牧养 自己,并不 牧养 我的羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, '所以 你们这些牧人 要听 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, '主 耶和华 如此 说:我 必与 牧人为敌,必向他们的手 追讨 我的羊,使他们不再 牧放 群羊;牧人 也不 再 牧养 自己。我必救 我的羊 脱离他们的口,不再 作 他们的 食物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, '「 主 耶和华 如此 说:看哪,我必亲自 寻找 我的羊,将牠们寻见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, '牧人 在 羊群 四散 的日子 怎样寻找 他的羊,我必照样 寻找 我的羊。这些羊在密云 黑暗 的日子 散 到各 处,我必从那里 救回 牠们来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, '我必从 万民 中领出牠们,从 各国 内聚集牠们,引导牠们 归回 故土,也必在 以色列 山上─一切溪水旁边、境内 一切 可居之处─牧养牠们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, '我必在美好 的草场 牧养 牠们。牠们的圈 必在 以色列 高处 的山上, 牠们必在佳美 之圈 中躺卧,也在 以色列 山 肥美 的草场 吃草。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, '主 耶和华 说:我必亲自 作我羊 的牧人, 使牠们得以躺卧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, ' 失丧的,我必寻找; 被逐的,我必领回;受伤的,我必缠裹; 有病的,我必医治;只是 肥的 壮的,我必除灭,也要秉公 牧养牠们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, '「我的羊群哪,论到你们,主 耶和华 如此 说:我 必在羊 与羊 中间、公绵羊 与公山羊 中间施行判断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, '你们这些肥壮的羊,在美好 的草场 吃 草还以为小事吗?剩下 的草,你们竟用蹄 践踏了;你们喝 清 水, 剩下的水,你们竟用蹄 搅浑了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, '至于 我的羊,只得吃 你们 所践踏的,喝 你们 所搅浑的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, '「所以,主 耶和华 如此 说: 我 必在 肥 羊 和瘦 羊 中间 施行判断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, '因为 你们用胁 用肩 拥挤 一切 瘦弱的,又用角 抵触,以致 使牠们四散。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, '所以,我必拯救 我的群羊 不 再 作 掠物;我也必在羊 和羊 中间 施行判断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, '我必立 一 牧人 照管他们,牧养 他们,就是 我的仆人 大卫。他必 牧养 他们, 作 他们的 牧人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, '我─耶和华 必作 他们的 神,我的仆人 大卫 必在他们中间 作王。这是 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, '「我必与他们 立 平安 的约,使恶 兽 从 境内 断绝,他们就必安 居 在旷野,躺卧 在林中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, '我必使 他们 与我山 的四围 成为福源,我也必叫时 雨 落下,必有 福 如甘霖而降。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, '田野 的树 必结 果,地 也必有出 产;他们必 在 故土 安然居住。我折断 他们所负的轭,救 他们脱离那以他们 为奴 之人的手;那时,他们就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, '他们必不 再 作 外邦人的 掠物,地上 的野兽 也不再 吞吃他们;却要安然 居住,无人 惊吓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, '我必给他们 兴起 有名的 植物;他们在境内 不 再 为 饥荒 所灭,也不 再 受 外邦人 的羞辱, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, '必知道 我、耶和华─他们的 神 是与他们同在的,并知道他们─以色列 家 是我的民。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, '你们 作我的羊,我草场 上的羊,乃是 以色列人,我也是你们的 神。这是主 耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, '耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, '「人 子啊,你要 面 向 西珥 山 发预言,攻击它, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, '对它 说,主 耶和华 如此 说:西珥 山哪,我 与你为敌,必向你伸 手 攻击你,使你 荒凉,令人惊骇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, '我必使 你的城邑 变为荒场, 成为 凄凉。你就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, '因为 你 永 怀仇恨,在以色列 人 遭 灾、罪孽 到了尽头 的时候,将 他们交 与 刀剑, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, '所以 主 耶和华 说:我 指著我的永生起誓, 我必使 你遭遇流血的报应,罪(原文是血;本节同)必追赶你;你既 不 恨 恶杀人流血,所以这罪 必追赶你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, '我必使 西珥 山 荒凉,令人惊骇,来往 经过 的人我必剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, '我必使 西珥山 满 有被杀的人。被刀 杀的,必倒 在你小山 和山谷,并一切的 溪水 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, '我必使你 永远 荒凉,使你的城邑 无人 居住,你的民就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, '因为 你曾说:『这 二 国 这 二 邦 必归 于 我,我必得为业』(其实耶和华 仍在 那里), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, '所以 主 耶和华 说:我 指著我的永生起誓,我必照你的怒气 和你从仇恨 中向他们 所 发 的嫉妒 待你。我审判你 的时候,必将自己显明 在他们中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, '你也必知道 我─耶和华 听见了 你的一切 毁谤,就是 你攻击 以色列 山 的话,说:『这些山荒凉,是归 我们 吞灭的。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, '你们也用口 向我 夸大,增添 与我 反对的话,我 都听见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, '主 耶和华 如此 说:全 地 欢乐的时候,我必使 你 荒凉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, '你怎样因 以色列 家 的地业 荒凉 而喜乐,我必照 你所行的待 你。西珥 山哪,你和以东 全 地必 都 荒凉。你们就知道 我 是耶和华。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, '「人 子啊,你 要对 以色列 山 发预言 说:以色列 山哪,要听 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, '主 耶和华 如此 说:因 仇敌 说:『阿哈!这永久 的山冈 都归 我们 为业了!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, '所以 要发预言 说,主 耶和华 如此 说:因为 敌人使你 荒凉,四围 吞吃,好叫你归 与其余 馀的 外邦人 为业,并且 多嘴 多舌 的人提起你来,百姓 也说你有臭名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, '故此,以色列 山 要听 主 耶和华 的话。 大山 小冈、水沟 山谷、荒废 之地、被弃 之城,为 四围 其余 馀的 外邦人 所 占据、所讥刺的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, ' 主 耶和华 对你们如此 说:我真 发愤恨 如火,责备 那其余 馀的 外邦人 和 以东 的众人。他们 快乐 满 怀,心 存恨恶,将 我的地 归 自己 为业,又 看为被弃的 掠物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, '所以,你要指著 以色列 地 说预言,对大山 小冈、水沟 山谷 说,主 耶和华 如此 说:我 发愤恨 和忿怒 说,因 你们曾受 外邦人 的羞辱, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, '所以 我 起 誓 说:你们四围的 外邦人 总要 担当 自己的 羞辱。这是主 耶和华说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, '「以色列 山哪,你 必发 枝条,为我的民 以色列 结 果子,因为 他们快要 来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, '看哪,我 是帮助你的,也必向你 转意,使你得以耕 种。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, '我必使以色列 全 家 的人 数在你 上面增多,城邑 有人 居住,荒场 再被建造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, '我必使人 和牲畜 在你 上面加增;他们必生养众多。我要使你 照旧 有人居住,并要赐福 与你比先前更多,你就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, '我必使人,就是 我的民 以色列,行 在你上面。他们必 得你 为业;你也不 再 使他们丧子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, '主 耶和华 如此 说:因为 人对你 说:『你 是吞吃 人的,又 使国民 丧子』, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, '所以 主 耶和华 说:你必不 再 吞吃 人,也不 再 使国民 丧子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, '我使你 不 再 听见 各国 的羞辱,不 再 受 万民 的辱骂,也不 再 使国民 绊跌。这是主 耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, '耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, '「人 子啊,以色列 家 住 在 本地的时候,在行动 作为 上玷污 那地。他们的行为 在我面前,好像正在 经期 的妇人那样污秽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, '所以我因 他们在那地上 流 人的血, 又因他们 以偶像 玷污那地,就把我的忿怒 倾 在他们身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, '我将他们 分散 在列国,四散 在列邦,按他们的行动 作为 惩罚他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, '他们到了 所 去 的列国,就使 我的圣 名 被亵渎;因为人谈论 他们说,这 是耶和华 的民,是从耶和华的地 出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, '我却顾惜 我的圣 名,就是以色列 家 在所 到 的列国 中所 亵渎的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, '「所以,你要对以色列 家 说,主 耶和华 如此 说:以色列 家啊,我 行 这事不是 为你们,乃是 为我的圣 名,就是 在你们到 的 列国 中所亵渎的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, '我要使 我的大 名 显为圣;这名在列国 中已被亵渎,就是 你们在他们中间 所亵渎的。我在他们眼前,在你们 身上显为圣的时候,他们 就知道 我 是耶和华。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, '我必从 各国 收取 你们,从列 邦 聚集 你们,引导 你们 归回 本地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, '我必用清 水 洒 在你们身上,你们就洁净了。我要洁净 你们,使你们脱离一切的 污秽,弃掉一切的 偶像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, '我也要赐 给你们 一个新 心,将新 灵 放 在你们里面,又从你们的肉体 中除掉 石 心,赐 给你 们肉 心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, '我必将 我的灵 放 在你们里面,使 你们顺从 我的律例,谨守 遵行 我的典章。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, '你们必住 在我所 赐 给你们列祖 之地。你们要作 我的 子民,我 要作 你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, '我必救 你们 脱离一切 的污秽,也必命 五谷 丰登,不 使你们 遭遇 饥荒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, '我必使 树木 多结 果子,田地 多出土产,好叫 你们不 再 因饥荒 受 外邦人 的讥诮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, '那时,你们必追想 你们的恶 行 和你们不 善 的 作为,就因 你们的罪孽 和 可憎的事 厌恶 自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, '主 耶和华 说:你们 要知道,我 这样行 不是 为你们。以色列 家啊,当为自己的行为 抱愧 蒙羞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, '「主 耶和华 如此 说:我洁净 你们,使你们脱离一切 罪孽 的日子,必使 城邑 有人居住,荒场 再被建造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, ' 过路的人 虽看 为 荒废 之地,现今 这荒废 之地仍得耕种。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, '他们必说:『这 先前为荒废 之地,现在成 如伊甸 园;这荒废 凄凉、毁坏 的城邑 现在坚固 有人居住。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, '那时,在你们四围 其余 馀的 外邦人 必知道 我─耶和华 修造 那 毁坏之处,培植 那荒废之地。我─耶和华 说过,也必成就。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, '「主 耶和华 如此 说:我要加增 以色列 家 的人数,多如羊群。他们必 为这事 向我求问,我要给他们 成就。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, '耶路撒冷 在守节 作祭 物 所献的羊群怎样多,照样,荒凉 的城邑 必 被人 群 充满。他们就知道 我 是耶和华。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, '耶和华的灵(原文是手)降 在我身上。耶和华 藉 借他的灵 带我出去,将我放 在平原 中;这平原 遍满 骸骨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, '他使我从 骸骨的四围 经过,谁知 在 平原 的骸骨甚 多,而且 极其 枯干。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, '他对我 说:「人 子啊,这些 骸骨 能复活吗?」我说:「主 耶和华啊,你 是知道的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, '他又对我 说:「你向 这些 骸骨 发预言 说:枯干 的骸骨啊,要听 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, '主 耶和华 对这些 骸骨 如此 说:『 我 必使气息 进入 你们里面,你们就要活了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, '我必给你们 加上 筋,使你们 长 肉,又将皮 遮蔽 你们,使 气息 进入你们里面,你们就要活了;你们便知道 我 是耶和华。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, '于 是,我遵 命 说预言。正说预言的时候,不料,有 响声, 有地震;骨 与 骨 互相联络。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, '我观看,见 骸骨上 有筋,也长了 肉,又有皮 遮蔽 其上,只是还没有 气息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, '主对我 说:「人 子啊,你要发预言,向 风 发预言,说 主 耶和华 如此 说:气息啊,要从四方(原文是风)而来,吹 在这些 被杀的人身上,使他们活了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, '于 是我遵 命 说预言,气息 就进入 骸骨,骸骨便活了,并且站起来,成为极 大 的军队。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, '主对我 说:「人 子啊,这些 骸骨 就是 以色列 全 家。 他们说:『我们的骨头 枯干了,我们的指望 失去了,我们灭绝净尽了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, '所以 你要发预言 对他们 说,主 耶和华 如此 说:『 我的民哪,我 必开  你们的坟墓,使你们 从坟墓 中出来,领 你们 进入 以色列 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, '我的民哪,我开  你们的坟墓,使你们 从坟墓 中出来,你们就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, '我必将我的灵 放 在你们里面,你们就要活了。我将你们 安置 在 本地,你们就知道 我─耶和华 如此 说,也如此成就了。这是耶和华 说的。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, '耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, '「人 子啊,你 要取 一 根木杖,在其上 写『为犹大 和他的同伴 以色列 人』;又取 一 根木杖,在其上 写『为约瑟,就是为以法莲,又为他的同伴 以色列 全 家』。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, '你 要使这两根 木杖接连为 一,在你手 中成为 一根。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, ' 你本国 的子民 问 你 说:『这 是什么意思?你不 指示 我们么?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, '你就对他们 说:主 耶和华 如此 说:『 我 要 将 约瑟 和他同伴 以色列 支派 的杖,就是 那在以法莲 手中的, 与 犹大 的杖 一同接连为 一,在我手中 成为 一根。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, ' 你所 写 的那两根杖 要在他们眼前 拿在手中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, '要对他们 说,主 耶和华 如此 说: 我 要将 以色列 人 从 他们所 到 的各国 收取,又从四围 聚集 他们,引导 他们 归回 本地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, '我要使 他们 在那地,在以色列 山上 成为一 国,有一 王 作 他们众民 的王。他们不 再 为 二 国,决不 再 分 为二 国; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, '也不 再 因偶像 和可憎的物,并一切 的罪过 玷污 自己。我却要救 他们出离一切的 住处,就是 他们犯罪 的地方;我要洁净 他们,如此,他们要作 我的 子民,我 要作 他们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, '「我的仆人 大卫 必作他们的 王;众民 必归 一 个牧人。他们必顺从 我的典章,谨守 遵行 我的律例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, '他们必住 在 我赐 给我仆人 雅各 的 地上,就是 你们列祖 所住 之地。他们 和他们的子孙,并子孙 的子孙,都永远 住 在那里。我的仆人 大卫 必作他们的 王,直到 永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, '并且我要与他们 立 平安 的约,作为 永 约。我也要将他们安置在本地,使他们 的人数增多,又在他们中间 设立 我的圣所,直到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, '我的居所 必 在他们中间;我要作 他们的 神,他们 要作 我的 子民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, '我的圣所 在 以色列 人中间 直到永远,外邦人 就必知道 我 是叫 以色列 成为圣 的耶和华。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, '「人 子啊,你要 面 向 玛各 地 的歌革,就是罗施、米设、土巴 的王 发预言 攻击他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, '说 主 耶和华 如此 说:罗施、米设、土巴 的王 歌革啊,我 与你为敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, '我必用 钩子 钩住你的腮颊,调转你,将你 和 你的军兵、马匹、马兵 带出来,都 披挂整齐,成了大 队,有大小盾牌,各 拿 刀剑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, '波斯人、古实人,和弗人(又作利比亚人),各 拿盾牌,头上戴盔; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, '歌篾人 和 他的军队,北方 极处 的陀迦玛 族 和 他的军队,这许多 国的民 都同著你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, '「那聚集 到你这里 的各 队 都当准备;你自己 也要准备,作 他们的 大帅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, '过了多 日,你必被差派。到末后 之年,你必来 到 脱离刀剑 从列 国 收回 之地,到 以色列 常久 荒凉 的山上;但那 从列国 中招聚 出来的 必在其上安然 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, '你和你的 军队,并同著你 许多 国的民,必如暴风 上 来, 如密云 遮盖 地面。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, '主 耶和华 如此 说:「到 那 时, 你心 必起 意念,图谋 恶 计, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, '说:『我要上 那无城墙 的乡村,我要到 那安静的民那里,他们 都 没有 城墙,无门、无 闩,安然 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, '我去要抢 财为掳物,夺 货为掠物,反 手 攻击 那从前荒凉、现在有人居住之地,又攻击 那住 世界 中间、从列国 招聚、得了 牲畜 财货 的民。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, '示巴人、底但人、他施 的客商,和其间的 少壮狮子 都必问你 说:『你 来 要抢 财为掳物吗?你聚集 军队 要夺 货为掠物吗?要夺取 金 银,掳去 牲畜、财货吗?要抢夺 许多 财宝为掳物吗?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, '「人 子啊,你要因此 发预言,对歌革 说,主 耶和华 如此 说:到我民 以色列 安然 居住 之 日,你岂不 知道吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, '你 必从本地,从北方 的极处 率领 许多 国的民 来,都 骑 著马,乃一大队 极多 的军兵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, '歌革啊,你必上来 攻击 我的民 以色列,如密云 遮盖 地面。 末后 的日子,我必带你来 攻击 我的地,到我在外邦人 眼前,在你身上 显为圣的时候,好叫 他们认识 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, '主 耶和华 如此 说:我在古 时 藉 借 我的仆人 以色列 的先知 所 说的,就是 你吗?当 日 他们多年 预言 我必带 你 来攻击以色列人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, ' 主 耶和华 说:「歌革 上来 攻击 以色列 地 的时候,我的怒气 要从鼻孔 里发出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, '我发愤恨 和烈怒 如火 说:那 日 在 以色列 地 必 有 大 震动, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, '甚至海中 的鱼、天空 的鸟、田野 的兽,并地 上 的一切 昆虫,和其上 的 众 人,因见我的面 就都震动;山岭 必崩裂,陡岩 必塌陷,墙垣 都 必坍倒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, '主 耶和华 说:「我必命 我的诸 山 发刀剑 来攻击歌革;人 都要用刀剑杀害 弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, '我必用瘟疫 和流血 的事刑罚 他。我也必将暴雨、大雹 与火,并硫磺 降与他 和 他的军队,并他所 率领 的众 民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, '我必显为大,显为圣,在多 国 人的眼前 显现;他们就知道 我 是耶和华。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, '「人 子啊,你 要向 歌革 发预言 攻击他,说 主 耶和华 如此 说:罗施、米设、土巴 的王 歌革啊,我与你为敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, '我必调转你,领你前往,使你从北方 的极处 上来,带你 到 以色列 的山上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, '我必从你左 手 打落 你的弓,从你右 手 打掉 你的箭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, '你 和 你的军队,并同著你 的 列国人,都必倒 在 以色列 的山上。我必将你给 各 类 的鸷 鸟 和田野 的走兽 作食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, '你必倒 在 田野,因为 我 曾说过。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, '我要降 火 在玛各 和海岛 安然 居住的人身上,他们就知道 我 是耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, '「我要在我民 以色列 中 显出 我的圣 名,也不 容 我的圣 名 再 被亵渎,列国人 就知道 我 是耶和华─以色列中 的圣者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, '主 耶和华 说: 这 日 事情临近,也必成就,乃是我所 说的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, '「住 以色列 城邑 的人必出去 捡器械,就是大小盾牌、弓 箭、梃杖、枪矛,都当柴 烧 火,直烧 七 年, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, '甚至他们不必 从 田野 捡 柴,也不必 从 树林 伐木;因为 他们要用器械 烧 火,并且抢夺 那 抢夺他们的人,掳掠 那 掳掠他们的人。这是主 耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, '「当 那 日,我必将以色列 地的谷,就是海 东 人所经过的谷,赐 给歌革 为坟 地,使 经过 的人到此 停步。在那里 人必葬埋 歌革 和 他的群 众,就称那地为哈们‧歌革 谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, '以色列 家 的人必用七 个月 葬埋他们,为要 洁净 全地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, '全 地 的居民 都必葬埋他们。当我得荣耀 的日子,这事必叫他们 得 名声。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, '他们必分派 人 时常 巡查 遍地,与 过路的人 一同葬埋 那 剩 在 地 面上的尸首,好洁净全地。过了 七 个月,他们还要巡查。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, '巡查遍地的人 要经过 全地,见 有人的 骸骨,就在旁边 立 一标记,等 葬埋 的人来将 骸骨葬 在哈们‧歌革 谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, '他们必这样洁净 那地,并 有一城 名 叫哈摩那。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, '「人 子啊,主 耶和华 如此 说:你 要对各 类的 飞鸟 和田野的 走兽 说:你们聚集 来吧,要从四方 聚 到 我 为你们 献 祭之地,就是 在 以色列 山 上献大 祭之地,好叫你们吃 肉、喝 血。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, '你们必吃 勇士 的肉,喝 地上 首领 的血,就如吃公绵羊、羊羔、公山羊、公牛,都是 巴珊 的肥畜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, '你们吃 我为你们 所 献 的祭,必吃饱 了脂油,喝 醉 了血。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, '你们必在 我席上 饱吃 马匹 和坐车的人,并勇士 和一切的 战  士。这是主 耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, '「我必显 我的荣耀 在列国中;万 民 就必看见 我所 行 的审判 与 我在他们身上 所 加 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, '这样,从 那 日 以后,以色列 家 必知道 我 是耶和华─他们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, '列国人 也必知道 以色列 家 被掳掠 是因他们的罪孽。 他们得罪 我,我就掩 面 不顾,将他们交 在敌人 手中,他们便都 倒 在刀下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, '我是照他们的污秽 和罪过 待 他们,并且我掩 面 不顾他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, ' 主 耶和华 如此 说:「 我要使 雅各 被掳的人 归回,要怜悯 以色列 全 家,又为我的圣 名 发热心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, '他们在 本地 安然 居住,无人 惊吓,是我将他们 从 万民 中领回,从仇敌 之地 召来。我在许多 国的民 眼前,在他们身上 显为圣的时候,他们要担当 自己的羞辱 和干犯 我 的一切 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, '因我使他们 被掳 到 外邦人中,后又聚集 他们归回 本地,他们就知道 我 是耶和华─他们的 神;我必不 再 留 他们 一人在外邦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, '我也不 再 掩 面 不顾他们,因 我已将 我的灵 浇灌 以色列 家。这是主 耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, '我们被掳掠 第二十 五 年, 耶路撒冷城 攻破 后 十 四 年,正在 年 初,月之 初十日,耶和华的灵(原文是手)降 在我身上,他把我 带到 以色列地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, '在 神 的异象中 带我 到 以色列 地,安置 在 至 高 的山上;在 山上的南边 有仿佛一座城 建立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, '他带 我 到那里,见 有一人,颜色(原文是形状)如 铜,手拿 麻 绳 和量度 的竿, 站 在门口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, '那人 对我 说:「人 子啊,凡 我 所 指示 你的,你都要用眼 看,用耳 听,并要放 在心上。 我带 你到这里来,特为要 指示你; 凡 你 所 见的,你都要告诉 以色列 家。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, '我见 殿 四围 有墙。那人 手拿 量度 的竿,长六 肘,每肘是一肘 零一掌。他用竿量 墙, 厚 一 竿,高 一 竿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, '他到了 朝 东 的 门,就上 门的台阶,量 门 的这槛,宽 一 竿;又 量门的那 槛,宽 一 竿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, '又有卫房,每房长 一 竿,宽 一 竿, 相隔 五 肘。门 槛,就是挨著 向殿 的廊 门槛,宽一 竿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, '他又量 向殿 门 的廊子,宽一 竿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, '又量 门 廊,宽八 肘,墙柱 厚二 肘;那门 的廊子 向著殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, '东 门 洞有卫房:这旁 三间,那旁 三间, 都是一 样的尺寸;这边 的柱子 和那边的柱子,也是一 样的尺寸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, '他量 门 口,宽 十 肘, 长 十 三 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, '卫房 前 展出的境界:这边 一 肘, 那边一 肘;卫房 这边 六 肘,那边 六 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, '又量 门洞,从这卫房 顶的后檐 到那卫房顶的后檐,宽 二十 五 肘;卫房门 与门 相对。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, '又量(原文是造) 廊子 六十 肘(七十士译本是二十肘),墙柱外是院子,有 廊为界,在门洞 两边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, '从 大门 口 到 内 廊 前,共五十 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, ' 卫房 和 门洞 两旁 柱 间 并 廊子,都有严紧 的窗櫺;里 边 都有窗櫺,柱 上 有雕刻的棕树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, '他带我 到 外 院,见 院的 四围 有 铺石地;铺石地 上 有屋子 三十间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, '铺石地,就是矮 铺石地 在 各门洞 两旁,以门洞 的长短 为度。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, '他从 下 门 量 到 内 院 外,共宽 一百 肘,东面 北面都是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, '他量 外 院 朝 北 的门,长 宽若干。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, '门洞的卫房,这旁 三间,那旁 三间。门洞的柱子 和廊子, 与第一 门 的尺寸一样。门洞长 五十 肘,宽 二十 五 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, '其窗櫺 和廊子,并雕刻的棕树,与 朝 东 的门 尺寸一样。登 七 层台阶 上到这门,前面 有廊子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, '内 院 有门 与这门 相对,北面 东面都是如此。他从这门 量 到 那门,共一百 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, '他带我 往 南去,见 朝 南 有门,又照先前的 尺寸 量 门洞的柱子 和廊子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, '门洞两旁与廊子 的周围 都有窗櫺,和先量的 窗櫺一样。门洞长 五十 肘,宽 二十 五 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, '登七 层台阶 上到这门,前面 有廊子;柱 上 有雕刻的棕树,这边 一棵,那边 一棵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, '内 院 朝 南 有门。从这门 量 到 朝 南 的那门,共一百 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, '他带我 从南 门 到 内 院,就照先前的 尺寸 量 南 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, '卫房 和柱子,并廊子 都照先前的 尺寸。门洞两旁与廊子 的周围 都有窗櫺。门洞长 五十 肘,宽 二十 五 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, '周围 有廊子,长 二十 五 肘,宽 五 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, '廊子 朝著 外 院,柱 上 有雕刻的棕树。登 八层 台阶上到这门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, '他带我 到 内 院 的东 面,就照先前的 尺寸 量 东门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, '卫房 和柱子,并廊子 都照先前的 尺寸。门洞两旁 与廊子 的周围 都有窗櫺。门洞长 五十 肘,宽 二十 五 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, '廊子 朝著外 院。门洞两 旁 的柱子 都有 雕刻的棕树。登 八 层台阶上到这门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, '他带我 到 北 门,就照先前的 尺寸 量那门, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, '就是量卫房 和柱子,并廊子。门洞周围 都有窗櫺;门洞长 五十 肘,宽 二十 五 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, '廊柱 朝著外 院。门洞两 旁 的柱子 都有 雕刻的棕树。登八 层台阶 上到这门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, '门洞 的柱 旁有屋子 和门;祭司(原文是他们)在那里 洗 燔祭牲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, '在门 廊内,这边 有两 张桌子,那边 有两张桌子,在其上 可以宰杀 燔祭牲、赎罪祭牲,和赎愆祭牲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, '上 到朝北 的门 口, 这 边 有两张 桌子, 门 廊 那 边 也有两张 桌子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, '门 这 边 有四 张桌子,那边 有四 张桌子,共八 张;在其上 祭司宰杀牺牲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, '为燔祭牲 有四张 桌子,是凿过 的石头做成的,长 一肘 半,宽 一肘 半,高 一 肘。祭司将 宰杀 燔祭牲 和平安祭牲 所 用的器皿 放 在其上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, '有钩子,宽一 掌,钉 在廊内 的四围。桌子 上 有牺牲 的肉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, ' 在 北 门 旁,内 院里 有屋子,为歌唱的人而设。这屋子朝 南(南:原文是东); 在 南门 旁,又有一间朝 北。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, '他对我 说:「这 朝 南 的 屋子 是为看守 殿宇 的祭司; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, '那 朝 北 的屋子 是为看守 祭坛 的祭司。这些祭司 是利未 人 中撒督 的子孙,近前 来 事奉 耶和华的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, '他又量 内院,长 一百 肘,宽 一百 肘,是见方的。祭坛 在殿 前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, '于 是他带我 到 殿 前的廊子,量 廊子 的墙柱。这面 厚五 肘,那面厚五 肘。门两旁, 这边 三 肘,那边 三 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, '廊子 长 二十 肘,宽 十一 肘。上 廊子有 台阶。靠近 墙柱 又有柱子,这边 一根,那边 一根。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, '他带我 到 殿 那里量 墙柱:这面 厚 六 肘,那面 厚 六 肘,宽窄 与会幕相同。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, '门口 宽 十 肘。门 两旁,这边 五 肘,那边 五 肘。他量 殿长 四十 肘,宽 二十 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, '他到 内 殿量 墙柱, 各厚二 肘。门口 宽六 肘,门 两旁各宽 七 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, '他量 内 殿, 长 二十 肘,宽 二十 肘。他对我 说:「这 是至 圣所。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, '他又量 殿 墙,厚六 肘;围著 殿 有旁 屋,各宽 四 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, '旁屋 有三层,层叠而上,每层排列 三十间。旁屋 的梁木 搁 在殿 墙 坎上,免 得 插入 殿 墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, '这围 殿 的旁屋 越 高 越宽;因 旁屋 围 殿 悬叠 而上,所以 越上 越宽, 从下一层,由中一层,到 上一层。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, '我又见 围著 殿 有高月台。旁屋 的根基,高足 一竿,就是六 大 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, ' 旁屋的 外 墙 厚 五 肘。旁 屋 之外 还有 余 馀地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, '在旁屋 与对面 的房屋 中间 有空地,宽 二十 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, '旁屋 的门 都向余 馀地:一 门 向 北,一 门 向南。周围 的余 馀 地 宽 五 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, '在 西 面 空地 之后 有 房子,宽 七十 肘,长 九十 肘,墙 四围 厚 五 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, '这样,他量 殿,长 一百 肘,又量空地 和那房子 并墙,共长 一百 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, '殿 的前面 和两旁 的空地,宽 一百 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, '他量 空地 后面 的那房子,并两旁 的楼廊,共长 一百 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, '内 殿、院 廊、门槛、严紧 的窗櫺,并对著 门槛 的三层 楼 廊,从地 到 窗櫺(窗櫺 都有蔽子), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, '直到 门 以上,就是到 内 殿 和外 殿内 外 四 围 墙壁,都按尺寸 用木板 遮蔽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, '墙上雕刻 基路伯 和棕树。每二基路伯 中间 有一棵棕树,每基路伯 有二 脸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, '这边 有人 脸 向著 棕树,那边 有狮子 脸 向著 棕树,殿 内 周围 都是 如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, '从地 至 门 以上,都有基路伯 和棕树。殿 墙 就是这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, '殿 的门柱 是方的。至圣所 的前面,形状 和殿的形状一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, '坛 是木头做的,高 三 肘,长 二 肘。坛 角 和坛面,并四旁,都是木头做的。他对我 说:「这是 耶和华 面前 的 桌子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, '殿 和至圣所 的门 各有两扇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, '每扇 分两 扇,这两 扇 是折叠的。这边 门 分两扇,那边 门也分两 扇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, '殿 的门扇 上 雕刻 基路伯 和棕树,与刻 在墙 上的一般。在 外头 廊 前 有木 槛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, '廊 这边 那边 都有严紧 的窗櫺 和棕树;殿 的旁屋 和槛就是这样。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, '他带我出来 向 北,到 外 院,又带我 进入 圣屋;这圣屋一排 顺著 空地,一排 与 北边 铺石地之屋 相对。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, '这圣屋长 一百 肘,宽 五十 肘,有向 北 的门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, '对著 内 院 那 二十肘宽之空地,又对著 外 院 的 铺石地,在第三 层楼上有楼廊 对著 楼廊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, '在圣屋 前 有一条夹道,宽 十 肘, 长一百肘。房门 都向北。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, '圣屋 因为 楼廊 占去 些地方,所以上 层 比中 下 两层窄些。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, ' 圣屋 有三层,却无 柱子,不像外院 的屋子有柱子;所以 上层比中 下两层 更窄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, '圣屋 外,东边 有墙, 靠著 外 院,长 五十 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, '靠著外 院 的圣屋 长 五十 肘。 殿 北面 的圣屋 长一百 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, '在 圣屋 以下,东头 有进入之处,就是 从外 院 进入之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, '向南(原文是东)在内院 墙 里 有圣屋,一排与铺石地之屋 相对,一排顺著 空地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, '这圣屋 前 的夹道与 北边 圣屋的夹道 长 宽一样; 出入之处 与北屋门 的样式相同。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, ' 正在 墙 前、夹道 的 东 头,有门 可以进入,与 向 南 圣屋 的门一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, '他对我 说:「 顺著 空地 的南 屋 北 屋,都是 圣 屋; 亲近 耶和华 的祭司 当在那里 吃 至 圣的物,也当在那里 放 至 圣的物,就是素祭、赎罪祭,和赎愆祭,因 此处 为圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, '祭司 进去 出了 圣所的时候,不可 直到 外 院,但要在圣屋 放下 他们供职 的衣服,因为 是 圣衣;要穿上 别的 衣服 才可以到 属民 的外院。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, '他 量 完了 内 殿,就带我出 朝 东 的 门,量 院的四围。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, '他用量度 的竿 量 四围,量 东 面 五 百肘(原文是竿;本章下同), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, '用竿 量 北 面 五 百 肘, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, '用竿 量 南 面 五 百 肘, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, '又转 到 西 面,用竿 量 五 百 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, '他量 四 面,四围 有 墙,长 五 百肘,宽 五 百肘,为要分别 圣地 与 俗地。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, '以后,他带我 到 一座门,就是 朝 东 的门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, ' 以色列 神 的荣光 从东 而来。他的声音 如同多 水 的声音;地 就因他的荣耀 发光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, '其状 如 从前他来 灭 城 的时候我所 见 的异象,那异象 如我在 迦巴鲁 河 边所 见 的异象,我就俯伏 在 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, '耶和华 的荣光 从朝 东 的 门 照入 殿中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, '灵 将我举起,带 入 内 院,不料,耶和华 的荣光 充满 了殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, '我听见 有一位从殿 中对我 说话。有 一人 站 在我旁边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, '他对我 说:「人 子啊,这是 我宝座 之地,是 我脚 掌 所踏之地。 我要在这里 住,在以色列 人 中 直到永远。以色列 家 和他们的君王 必不 再 玷污 我的圣 名,就是行邪淫、在锡安的高处 葬埋他们君王 的尸首, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, '使 他们的门槛 挨近 我的门槛,他们的门框 挨近 我的门框;他们与我中间 仅隔一墙,并且 行 可憎的事,玷污了 我的圣 名,所以我发怒 灭绝 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, '现在 他们当从我面前 远除 邪淫 和他们君王 的尸首,我就住 在他们中间 直到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, '人 子啊,你 要将 这殿 指示 以色列 家,使他们因自己的罪孽 惭愧,也要他们量 殿的尺寸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, '他们若 因自己所 行 的一切 事惭愧,你就将殿 的规模、样式、出 入之处,和一切 形状、 典章、 礼仪、 法则 指示 他们,在他们眼前 写上,使他们遵照 殿的一切 规模 典章 去做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, '殿 的法则 乃是如此:殿在 山 顶上,四围 的全 界 要称为至 圣。 这 就是殿 的法则。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, '以下 量 祭坛,是以肘为度(这肘 是一肘 零一掌)。底座 高一肘,边宽 一肘,四围 起 边 高一 掌,这 是坛 的座。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, '从底座 到 下层 磴台,高二 肘,边宽 一 肘。从小 磴台 到 大 磴台,高四 肘,边宽 一肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, '坛上的供台,高四 肘。供台 的四 拐角上 都有角。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, '供台 长 十二肘,宽 十 二肘,四 面 见 方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, '磴台 长 十 四肘,宽 十 四肘,四 面 见方。四围 起边 高半 肘,底座 四围 的边宽一肘。台阶 朝 东。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, '他对我 说:「人 子啊,主 耶和华 如此 说:建造祭坛,为要在其上 献 燔祭 洒 血,造成 的时候 典章 如下: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, '主 耶和华 说,你要将一只公 牛 犊 作为赎罪祭,给 祭司 利未人 撒督 的后裔,就是 那 亲近 我、事奉我的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, '你要取 些公牛的血,抹 在 坛的四 角 和 磴台 的四 拐角,并 四围 所起的边上。你这样洁净 坛,坛就洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, '你又要 将 那作赎罪祭 的公牛犊 烧 在殿外、圣地 之外 预定之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, '次 日,要将无残疾 的公 山羊 献 为赎罪祭;要洁净 坛,像 用公牛犊 洁净的一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, ' 洁净了坛,就要将 一只无残疾 的公 牛 犊和 羊群 中一只无残疾 的公绵羊 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, '奉 到耶和华 前。祭司 要撒 盐 在其上,献 与耶和华 为燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, '七 日内,每日 要预备 一只公山羊 为赎罪祭,也要预备 一只公 牛 犊和 羊群 中的一只公绵羊,都要没有残疾的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, '七 日 祭司洁净 坛,坛就洁净了;要这样把坛 分别为圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, '满了 七日, 自八 日 以后,祭司 要在 坛上 献 你们的燔祭 和 平安祭;我必悦纳 你们。这是主 耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, '他又带我 回到 圣地 朝 东 的外 门;那门 关闭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, '耶和华 对我 说:「这 门 必须 关闭,不可 敞开 ,谁 也不可 由其中 进入;因为 耶和华─以色列的 神 已经由其中 进入,所以必须 关闭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, '至于  王,他 必按王的位分,坐 在其内,在耶和华 面前 吃 饼。他必由 这门 的廊 而入,也必由此 而出。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, '他又带我 由北 门 来到 殿 前。我观看,见 耶和华 的荣光 充满 耶和华 的殿,我就俯伏 在 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, '耶和华 对我 说:「人 子啊, 我 对你 所 说 耶和华 殿 中的一切 典章 法则,你要放 在心上,用眼 看,用耳 听,并要留 心 殿宇 和圣地 一切 出 入之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, '你要对 那悖逆的 以色列 家 说,主 耶和华 如此 说:以色列 家啊,你们行一切 可憎的事,当够了吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, '你们把 我的食物,就是脂油 和血 献上的时候,将身 心 未受割礼的 外邦 人 领 进 我的圣地,玷污了 我的殿;又背了 我的约,在 你们一切 可憎的事上,加上这一层。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, '你们也没有 看守 我的圣物,却派 别人在圣地 替你们看守 我所吩咐你们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, '「主 耶和华 如此 说: 以色列 中的 外邦 人,就是身 心 未受割礼的,都不可 入 我的圣地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, '「当以色列人 走迷的时候, 有 利未人 远离 我,就是 走迷 离开 我、随从 他们的偶像,他们必担当 自己的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, '然而他们必在我的圣地 当 仆役,照管 殿 门,在 殿 中供职; 必为民 宰杀 燔祭牲 和 平安祭牲, 必站 在民前 伺候他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, '因为 这些利未人曾在偶像 前 伺候 这民,成了 以色列 家 罪孽 的绊脚石,所以 我向他们 起 誓:他们必担当 自己的罪孽。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, '他们不可 亲近 我,给我 供祭司的职分,也不可挨近 我的一件 圣物,就是 至圣 的物;他们却要担当 自己的羞辱 和所 行 可憎之事的报应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, '然而我要使 他们 看守 殿宇,办理 其中的一切事,并做 其内 一切 当做之工。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, '「以色列 人 走迷 离开 我的时候, 祭司 利未人 撒督 的子孙 仍看守 我的圣所。他们 必亲近 我,事奉我,并且侍立 在我面前,将脂油 与血 献 给我。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, '他们 必进入 我的圣所, 就近 我的桌 前事奉我,守 我所吩咐的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, ' 他们进 内 院 门 必穿 细麻 衣。在内 院 门 和殿 内供职 的时候不可 穿 羊毛衣服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, '他们头 上 要 戴细麻布 裹头巾, 腰 穿细麻布 裤子;不可 穿 使身体出汗的衣服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, '他们出 到 外 院 的民那里,当脱下 供职 的衣服,放 在圣 屋内,穿上 别的 衣服,免得 因圣衣 使 民 成圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, '不可 剃 头,也不可 容发绺 长长,只 可剪 发。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, '祭司 进 内 院 的时候都 不可 喝 酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, '不可 娶 寡妇 和被休 的妇人为妻,只可 娶 以色列 后裔 中的处女,或是 祭司 遗留的寡妇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, '他们要使 我的民 知道 圣 俗的分别,又使他们分辨 洁净 的和不洁净的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, '有 争讼的事,他们 应当站立 判断,要按我的典章 判断。在我一切的 节期 必守 我的律法、 条例,也必以 我的安息日 为圣日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, '他们不可 挨近 死尸 沾染自己,只可 为父亲、母亲、儿子、女儿、弟兄,和 未 嫁人 的姊妹 沾染自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, '祭司洁净 之后,必再计算 七 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, '当他进 内 院,进 圣所,在圣所 中事奉 的日子,要为自己献 赎罪祭。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, '「祭司必有 产业,我 是他们的产业。不可 在以色列 中给 他们 基业;我 是他们的基业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, '素祭、赎罪祭,和赎愆祭 他们 都可以吃,以色列 中一切 永献的物 都要归 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, '首先 初熟之物 和一切 所献的 供物 都 要归 给祭司。你们也要用初熟 的麦子磨面 麺 给 祭司;这样,福气 就必临 到 你们的家了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, '无论是 鸟是 兽,凡自死的,或是撕裂的,祭司 都 不可 吃。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, '你们拈阄 分 地 为业,要献上 一分 给耶和华 为圣 供 地,长 二万五千肘,宽 一万肘。这分以内,四围 都 为 圣地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, '其中 有 作为 圣所之地,长五 百肘,宽五 百肘,四面 见方。四围 再有五十 肘 为郊野之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, '要以 肘 为度 量地,长 二万五千肘,宽 一万肘。其中 有 圣所,是至 圣的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, '这是 全地 的一分 圣地,要归 与供圣所 职事 的祭司,就是亲近 事奉 耶和华的,作为 他们 房屋 之地 与圣所 之圣地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, '又有一分,长 二万五千肘,宽 一万肘,要归 与在殿 中供职 的利未人,作为二十 间房屋 之业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, '也要分定 属城 的地业,宽 五 千肘,长 二万五千肘,挨著 那分圣 供地,要归 以色列 全 家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, '归王 之地要在圣 供地 和属城 之地 的两旁,就是圣 供地 和属城 之地 的旁边,西 至西 头,东 至东 头,从 西 到 东,其长 与每 支派的分 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, '这地 在以色列 中必归 王 为业。我所立的王 必不 再 欺压 我的民,却要按支派 将地 分给 以色列 家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, '主 耶和华 如此 说:「以色列 的王啊,你们 应当知足,要除掉 强暴 和抢夺的事,施行 公平 和公义,不再 勒 索 我的民。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, '你们 要用 公道 天平、公道 伊法、公道 罢特。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, '伊法 与罢特 大小要 一 样。罢特 可盛 贺梅珥 十分之一,伊法 也可盛贺梅珥 十分之一,都以 贺梅珥 的大小为 准。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, '舍客勒 是二十 季拉;二十 舍客勒,二十 五 舍客勒,十五 舍客勒,为 你们的 弥那。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, '「你们当献 的供物 乃是 这样:一贺梅珥 麦子 要献伊法 六分之一;一贺梅珥 大麦 要献伊法 六分之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, '你们献所分定 的油,按油 的罢特,一 柯珥 油要献罢特 十分之一(原来 十 罢特 就是一贺梅珥)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, '从以色列 滋润的草场 上每 二百 羊中,要献一 只羊羔。这都可作素祭、燔祭、平安祭,为民 赎罪。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, '此地 的民 都 要 奉上 这 供物 给以色列 中的王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, ' 王 的本分是 在节期、月朔、安息日,就是以色列 家 一切的 节期,奉上燔祭、素祭、奠祭。他 要预备 赎罪祭、 素祭、 燔祭,和 平安祭,为 以色列 家 赎罪。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, '主 耶和华 如此 说:「正 月 初一日,你要取 无残疾 的公牛犊,洁净 圣所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, '祭司 要取 些赎罪祭牲 的血,抹 在 殿 的门柱 上和 坛 磴台 的四 角上,并 内 院 的门 框上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, '本月 初七日(七十士译本是七月初一日)也要为 误犯罪 的和愚蒙 犯罪的如此 行,为 殿 赎罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, '「正 月 十 四 日,你们 要 守逾越节,守节 七 日,要吃 无酵饼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, '当 日,王 要为自己 和 国内 的众 民 预备 一只公牛 作赎罪祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, '这节 的七 日,每日 他要为耶和华 预备 无残疾 的公牛 七只、公绵羊 七 只为燔祭。 每日 又要预备公山羊 一只为赎罪祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, '他也要预备 素祭,就是为一只公牛 同献一伊法细面 麺,为一只公绵羊 同献一伊法细面 麺,每一伊法 细面 麺加油 一欣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, '七 月 十 五 日 守节的时候,七 日 他都要如此 行,照逾越节的赎罪祭、燔祭、素祭,和油的条例一样。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, '主 耶和华 如此 说:「内 院 朝 东 的门,在办理事务 的六 日 内必须 关闭;惟有安息 日 和月朔 必须敞开 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, '王 要从 这门 的廊 进入,站 在 门 框旁边。祭司 要为他预备 燔祭 和 平安祭,他就要在 门 槛 那里敬拜,然后出去。这门 直到 晚上 不可 关闭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, '在安息日 和月朔,国内 的居民 要在这 门 口,耶和华 面前 敬拜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, '安息 日,王 所 献 与耶和华 的燔祭 要用无残疾 的羊羔 六只,无残疾 的公绵羊一只; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, '同献的素祭 要为公绵羊 献一伊法细面 麺,为羊羔 照他的力量 而献,一伊法 细面 麺加油 一欣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, '当 月朔,要献无残疾 的公 牛 犊一只,羊羔 六只,公绵羊一只,都要 无残疾的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, '他也要预备 素祭,为公牛 献一伊法细面 麺,为公绵羊 献一伊法细面 麺,为羊羔 照 他的力量 而献,一伊法 细面 麺加油 一欣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, '王 进入 的时候必由 这门 的廊 而入,也必由此 而出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, '在各节期,国内 居民 朝 见 耶和华的时候,从北 门 进入 敬拜的,必由南 门 而出;从南 门 进入的,必由北 门 而出。不可 从所 入 的门 而出,必要 直往前行,由对门而出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, '民进入,王 也要在民中 进入;民出去,王也要一同出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, '「在节期 和圣会 的日子同献的素祭,要 为一只公牛 献一伊法细面 麺,为一只公绵羊 献一伊法细面 麺,为羊羔 照他的力量 而献,一伊法 细面 麺加油 一欣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, ' 王 预备 甘心献的 燔祭 或 平安祭,就是向耶和华 甘心献的,当有人为他 开  朝 东 的门。他就预备 燔祭 和 平安祭,与安息 日 预备 的一样,献毕就出去。他出去 之后,当有人将 门 关闭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, '「每日,你要预备 无残疾 一 岁 的羊羔一只,献与耶和华 为燔祭;要每 早晨 预备。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, '每 早晨 也要预备 同献的 素祭,细面 麺一伊法 六分之一,并油 一欣 三分之一,调和 细面 麺。这素祭 要常 献与耶和华 为永远的 定例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, '每 早晨 要这样预备 羊羔、 素祭,并 油 为常 献的燔祭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, '主 耶和华 如此 说:「王 若 将产业 赐给他 的儿子,就成了 他儿子 的产业,那是 他们承受为业的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, '倘若 王将 一分产业 赐给 他的臣仆,就成了 他臣仆的产业;到 自由 之年 仍要归 与王。至于  王的产业,必归与 他的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, '王 不可 夺取 民的 产业,以致驱逐他们 离开 所承受的;他要从自己的地业中,将产业 赐给 他儿子, 免得 我的民 分散,各人 离开 所承受的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, '那带我的,将我从 门 旁 进入之处、领进 为 祭司 预备的圣 屋,是朝 北的,见 后头 西边 有一块地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, '他对我 说:「这是 祭司 煮 赎愆祭、 赎罪祭, 烤 素祭 之地,免得 带 到 外 院,使 民 成圣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, '他又带我 到 外 院,使我经过 院子 的四 拐角,见 每 拐角 各 有一个院子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, '院子 四 拐角 的院子,周围有墙,每院长 四十肘,宽 三十肘。四 拐角 院子的尺寸 都是一样, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, '其中 周围 有一排房子,房子 内 有 煮肉的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, '他对我 说:「这都是 煮肉 的房子, 殿内 的仆役 要在这里 煮 民 的祭物。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, '他带我回 到 殿 门,见 殿 的门槛 下 有水 往东 流出(原来 殿 面朝 东)。这水 从槛下,由殿 的右 边,在祭坛 的南边 往下流。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, '他带我出 北 门,又领我 从外 边 转到 朝 东 的外 门,见 水 从 右 边 流出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, '他 手拿 准绳 往东 出去的时候,量了 一千 肘,使我蹚过 水,水 到踝子骨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, '他又量 了一千肘,使我蹚过 水,水 就到膝;再量 了一千肘,使我蹚过水,水 便到腰; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, '又量了 一千肘,水便成了河, 使我不 能 蹚过。因为 水势 涨起,成为可洑 的水, 不可 蹚 的河。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, '他对我 说:「人 子啊,你看见了什么?」他就带我 回到 河 边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, '我回到河边的时候,见 在 河 这边 与那边 的岸上 有极 多 的树木。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, '他对我 说:「这 水 往 东 方 流去,必下 到 亚拉巴,直到 海。所发出来的水必流 入 盐海,使水变甜(原文是得医治;下同)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, '这河水 所 到 之处, 凡 滋生的 动物 都必生活,并且因 这 流来 的水 必有 极 多 的鱼,海水也变甜了。这河水 所 到 之处,百物都必生活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, '必有 渔夫 站 在河边,从隐‧基底 直到隐‧以革莲,都作晒(或译:张)网之处。 那鱼 各从其类,好像大 海 的鱼 甚 多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, '只是泥泞之地 与洼湿之处 不 得治好,必为 盐地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, '在 河 这边 与那边的 岸 上必生长 各类的 树木;其果可作食物,叶子 不 枯干,果子 不 断绝。每月 必结新果子,因为 这水 是 从 圣所 流出来的。树上的果子 必作 食物,叶子 乃为治病。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, '主 耶和华 如此 说:「你们要照 地的境界, 按以色列 十 二 支派分 地 为业。约瑟 必得两分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, '你们承受这地 为业,要彼此均分;因为 我曾起 誓 应许将这地赐 与你们的列祖;这 地 必归 你们 为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, '「地 的四界 乃是如此:北 界 从 大 海 往 希特伦,直到 西达达口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, '又往哈马、比罗他、西伯莲(西伯莲 在大马士革 与 哈马 两界 中间),到 浩兰 边界 的哈撒‧哈提干。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, '这样, 境界 从 海边 往大马士革 地界上的哈萨‧以难,北 边以哈马地 为界。这是 北 界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, '东 界 在 浩兰、 大马士革、 基列,和 以色列 地的中间,就是约旦河。你们要从北界 量 到 东 海。这是 东 界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, '南 界 是从他玛 到米利巴‧加低斯 的水,延到 埃及小河,直到 大 海。这是 南界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, '「西 界 就是大 海,从南界 直到 哈马 口 对面之地。这是 西 界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, '「你们要按著以色列 的支派 彼此 分 这 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, '要 拈阄分 这地 为业,归与自己 和你们中间 寄居 的外人,就是 在你们中间 生养 儿女的外人。你们 要看他们 如同以色列 人中 所生的一样;他们在以色列 支派 中 要与你们同得 地业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, ' 外人 寄居 在哪 支派中,你们就在那里 分给 他 地业。这是主 耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, '众支派 按名 所得之地记在下面:从北 头, 由 希特伦 往哈马 口,到大马士革 地界上的哈萨‧以难。北边 靠著 哈马地(各支派的 地都有 东 西 的边界),是但 的一分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, '挨著 但 的地界,从 东 到 西,是亚设 的一分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, '挨著 亚设 的地界,从 东 到 西,是拿弗他利 的一分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, '挨著 拿弗他利 的地界,从 东 到 西,是玛拿西 的一分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, '挨著 玛拿西 的地界,从 东 到 西,是以法莲 的一分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, '挨著 以法莲 的地界,从 东 到 西,是流便 的一分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, '挨著 流便 的地界,从 东 到 西,是犹大 的一分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, '挨著 犹大 的地界,从 东 到 西,必有 你们所 当献 的供地,宽 二万五千肘。从东 界 到 西 界,长短 与各分 之地相同,圣地 当 在其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, ' 你们献 与耶和华 的供地 要长 二万五千肘,宽 一万肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, '这 圣 供地 要归 与祭司,北 长二万五千肘,西 宽 一万肘,东 宽 一万肘,南 长 二万五千肘。耶和华 的圣地 当 在其中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, '这地要归与撒督 的子孙 中成为圣 的祭司,就是那 守 我所吩咐的。当以色列 人 走迷的时候,他们 不 像 那些利未人 走迷了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, '这 要归 与他们 为供地,是全地 中至 圣的。供地挨著 利未人 的地界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, '利未人 所得的地要长 二万五千肘,宽 一万肘,与祭司 的地界 相等,都 长 二万五千肘,宽 一万肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, '这地 不可 卖,不可 换,初熟之物 也不可 归与别人,因为 是归耶和华 为圣的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, '这二万五千肘 前面 所剩下 五千肘 宽 之地要作 俗用,作为造城 盖房 郊野之地。城 要 在当中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, '城的尺寸 乃是如此:北 面 四 千 五 百肘,南 面 四 千 五 百肘,东 面 四 千 五 百肘,西 面 四 千 五 百肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, '城 必有 郊野,向北 二百 五十肘,向南 二百 五十肘,向东 二百 五十肘,向西 二百 五十肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, '靠著 圣 供地 的余 馀地,东 长 一万肘,西长 一万肘,要 与圣 供地相等;其中的土产 要作 城 内工人 的食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, '所有 以色列 支派中,在城 内做工的,都要耕种这地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, '你们所献的 圣 供地 连归 城 之地, 是四方的:长二万五千肘,宽二万五千肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, '圣 供地 连归城 之地,两 边 的余 馀地 要归与王。供地东边, 南北二万五千肘,东至 东 界,西边南北 二万五千肘,西至 西 界,与各分 之地相同,都要 归王。圣 供地 和殿 的圣地 要在其中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, '并且利未人 之地,与归城 之地的东西两边延长之地( 这两地 在王 地中间),就是在 犹大 和便雅悯 两界 中间,要 归与王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, '论到其余 馀 的支派,从 东 到 西,是便雅悯 的一分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, '挨著 便雅悯 的地界,从 东 到 西,是西缅 的一分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, '挨著 西缅 的地界,从 东 到 西,是以萨迦 的一分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, '挨著 以萨迦 的地界,从 东 到 西,是西布伦 的一分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, '挨著 西布伦 的地界,从 东 到 西,是迦得 的一分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, ' 迦得 地 的 南 界 是 从他玛到米利巴‧加低斯 的水,延到埃及小河,直到 大 海。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, '这 就是 你们要拈阄分 给以色列 支派 为业 之地,乃是 他们各支派所得之分。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, '城的北 面 四 千 五 百肘。出 城 之处如下; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, '城 的各门 要按 以色列 支派 的名字。北面 有三 门,一 为流便 门,一 为犹大 门,一 为利未 门; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, ' 东 面 四 千 五 百肘,有三 门,一 为约瑟 门,一 为便雅悯 门,一 为但 门; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, '南 面 四 千 五 百肘,有三 门,一 为西缅 门,一 为以萨迦 门,一 为西布伦 门; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, '西 面 四 千 五 百肘,有三 门,一 为迦得 门,一 为亚设 门,一 为拿弗他利 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, '城四围 共一万八千肘。从此以后,这城 的名字 必称为耶和华的所在。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, '犹大 王 约雅敬 在位 第三 年,巴比伦 王 尼布甲尼撒 来到 耶路撒冷,将城 围困。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, '主 将 犹大 王 约雅敬,并 神 殿 中器皿 的几分 交付 他手。他就把 这器皿 带到 示拿 地,收入他神 的庙里,放在 他神 的库中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, '王 吩咐 太监 长 亚施毘拿,从 以色列 人 的宗室 和 贵胄 中带进几个人来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, '就是 年少 没有 残疾、相貌 俊美、通达 各样 学问、知识 聪明 俱备、 足能 侍立 在王 宫里的,要教他们 迦勒底 的文字 言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, '王 派定 将自己 所用的膳 和所饮 的酒,每日 赐他们 一分,养他们 三 年。满了三年,好叫他们在王 面前 侍立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, '他们中间 有 犹大 族的人:但以理、哈拿尼雅、米沙利、亚撒利雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, '太监 长 给他们 起 名:称但以理 为 伯提沙撒,称哈拿尼雅 为沙得拉,称米沙利 为米煞,称亚撒利雅 为亚伯尼歌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, '但以理 却立 志 不 以王 的膳 和王所饮 的酒 玷污自己,所以求 太监 长 容他不 玷污自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, '神 使 但以理 在太监 长 眼前 蒙恩惠,受怜悯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, '太监 长 对但以理 说:「我 惧怕 我主 我王,他 已经派定 你们的饮 食;倘若 他见 你们的面貌 比 你们同岁的 少年人 肌瘦,怎么好呢?这样,你们就使 我的头 在王 那里难保。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, '但以理 对 太监 长 所 派 管理 但以理、哈拿尼雅、米沙利、亚撒利雅 的委办 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, '「求你 试试 仆人们 十 天,给 我们 素菜 吃,白水 喝, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, '然后看看 我们的面貌 和用 王 膳 那少年人 的面貌,就照你所 看 的待 仆人吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, '委办便允准 他们 这 件事,试看他们 十 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, '过了 十 天,见 他们的面貌 比 用 王 膳 的一切 少年人 更加俊美 肥 胖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, '于 是 委办 撤去 派他们用的膳,饮 的酒,给 他们 素菜吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, '这 四个 少年人, 神 在各样 文字学问(学问:原文是智慧)上赐 给他们 聪明 知识;但以理 又明白 各样的 异象 和梦兆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, '尼布甲尼撒 王 预定 带进 少年人来的日期 满了,太监 长 就把他们带到 王面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, '王 与他们 谈论,见 少年人中 无一人 能比但以理、哈拿尼雅、米沙利、亚撒利雅,所以留他们在王 面前 侍立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, '王 考问 他们 一切 事,就见 他们的智慧 聪明 比 通 国的 术士 和用法术的 胜过十 倍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, '到 古列 王 元 年,但以理 还在。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, '尼布甲尼撒 在位 第二 年, 他做了 梦,心里 烦乱,不能 睡觉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, '王 吩咐 人将术士、用法术的、行邪术的,和迦勒底人 召来,要他们将王的梦 告诉 王,他们就来 站 在王 前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, '王 对他们 说:「我做了 一梦,心里 烦乱,要知道 这是什么梦。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, '迦勒底人 用亚兰的言语 对王 说:「愿 王 万 岁!请将那梦 告诉 仆人,仆人就可以 讲解。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, '王 回答 迦勒底人 说:「梦我已经忘了(或译:我 已定命;八节同),你们若 不 将梦 和梦的讲解 告诉我,就必被凌迟,你们的房屋 必成为 粪堆; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, '你们若 将梦 和梦的讲解 告诉我,就必从 我这里 得 赠品 和赏赐,并大 尊荣。现在 你们要将梦 和梦的讲解 告诉我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, '他们第二次 对王 说:「请王 将梦 告诉 仆人,仆人就可以 讲解。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, '王 回答 说:「我 准 知道 你们 是故意迟延,因为 你们知道 那梦 我 已经忘了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, ' 你们若 不 将梦 告诉我,只有 一 法待你们;因为你们预备了 谎言 乱 语 向我 说,要等候 时势 改变。现在 你们要将梦 告诉 我,因我知道 你们能将梦的讲解 告诉我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, '迦勒底人 在王 面前 回答 说:「世 上 没 有 人 能 将王 所问的事 说出来;因为 没有 君王、大臣、掌权的向 术士,或用法术的,或迦勒底人 问 过这样的 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, '王 所 问 的事 甚难。除了 不 与 世人 同居 的 神明,没 有 人 在王 面前 能说出来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, '因此,王 气忿忿地 大 发烈怒,吩咐 灭绝 巴比伦 所有的 哲士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, '于 是 命令 发出,哲士 将要见杀,人就寻找 但以理 和他的同伴,要杀他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, '王 的 护卫 长 亚略 出来,要杀 巴比伦 的哲士,但以理 就 用婉言 回答 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, ' 向王 的 护卫长 亚略 说:「王 的 命令 为何 这样紧急呢?」亚略 就 将情节 告诉 但以理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, '但以理 遂进去 求 王 宽 限,就可以将梦的讲解 告诉 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, ' 但以理 回到 他的居所,将这事 告诉 他的同伴 哈拿尼雅、米沙利、亚撒利雅, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, '要他们祈求 天上的 神 施怜悯,将 这 奥秘 的事指明,免得 但以理 和他的同伴 与 巴比伦 其余 馀的 哲士 一同灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, '这奥秘 的事就 在 夜间 异象 中给但以理 显明, 但以理 便称颂 天上的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, ' 但以理 说:「 神 的 名 是 应当称颂的!从 亘古 直到 永远,因为 智慧 能力 都属 乎他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, '他 改变 时候、日期,废 王,立 王,将智慧 赐 与智慧人,将知识 赐与聪明人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, '他 显明 深奥 隐秘的事,知道 暗中 所有的,光明 也与他 同居。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, '我列祖的 神啊,我 感谢 你,赞美你,因 你将智慧 才能 赐 给我, 允准我们所 求的,把 王 的事 给我们指明。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, '于 是,但以理 进去 见 亚略,就是 王 所派 灭绝 巴比伦 哲士的, 对他 说:「不要 灭绝 巴比伦 的哲士,求你领 我到王 面前,我要将梦的讲解 告诉 王。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, '亚略 就 急忙 将但以理 领到 王 面前,对王 说:「我在被掳 的 犹大人 中 遇见 一人,他 能将梦的讲解 告诉 王。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, '王 问 称 为 伯提沙撒 的但以理 说:「你 能 将我所 做 的梦 和梦的讲解 告诉我吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, '但以理 在王 面前 回答 说:「王 所 问 的那奥秘事,哲士、用法术的、术士、观兆的 都不 能 告诉 王; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, '只 有 一位在天上的 神 能显明 奥秘的事。他已将 日 后 必有 的事 指示 尼布甲尼撒 王。你的梦 和你在床 上 脑中 的异象 是 这样: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, '王啊,你 在 床 上想 到 后 来 的事,那显明 奥秘事 的主把 将来必有的事 指示你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, '至于 那 奥秘的事 显明 给我,并非 因 我 的智慧 胜过 一切 活人,乃 为 使王 知道 梦的讲解 和 心里 的思念。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, '「王啊,你 梦见 一个 大 像,这 像 甚高,极其 光耀,站 在你面前,形状 甚是可怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, '这 像 的头 是 精 金的,胸膛 和膀臂 是 银的,肚腹 和腰 是 铜的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, '腿 是 铁的,脚 是 半 铁 半 泥的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, '你观看, 见有一块非 人手 凿出来 的 石头 打 在 这像 半铁 半泥 的 脚上,把脚 砸碎; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, '于 是 金、银、铜、铁、泥 都一同 砸得粉碎,成如 夏天 禾场 上的 糠秕,被风 吹散, 无 处 可寻。打碎 这像 的 石头 变成 一座大 山,充满 天下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, '「这 就是那梦。我们在王 面前 要讲解那梦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, '王啊,你 是诸王 之王。 天上的 神 已将国度、权柄、能力、尊荣 都赐 给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, '凡 世人 所 住 之地 的走兽,并天空 的飞鸟,他都交付 你手,使你掌管 这一切。你 就是那 金 头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, '在你以后 必另 兴 一国,不及于  你;又有 第三 国,就是 铜的,必 掌管 天下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, '第四 国,必 坚壮 如铁, 铁 能打碎 克 剋制 百物, 又能压碎 一切,那国 也必打碎 压制 列国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, '你既 见 像的脚 和脚指头,一半 是 窑匠 的 泥,一半 是铁,那国 将来也必 分开 。你既 见 铁 与泥 搀杂,那国也必有 铁 的 力量。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, '那脚 指头,既是半 铁 半 泥,那国 也必 半 强 半 弱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, '你既 见 铁 与泥 搀杂,那国民也必 与各种 人 搀杂,却不 能 彼此 相合,正如 铁 与 泥 不能 相合一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, '当 那 列王 在位的时候,天上的 神 必另立 一国, 永 不 败坏, 也不 归 别 国的人,却要打碎 灭绝 那 一切 国,这国 必存 到永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, '你既 看见 非 人手 凿出来 的 一块石头 从山而出,打碎 金、银、铜、铁、泥,那就是至大的 神 把后来 必有 的 事 给王 指明。这梦 准是这样,这讲解 也是确实的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, '当时,尼布甲尼撒 王 俯伏 在 地,向但以理 下拜,并且吩咐 人给他 奉上 供物 和香品。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, '王 对但以理 说:你既 能 显明 这 奥秘的事,你们的 神 诚然 是 万神 之神、万王 之主,又是显明 奥秘事的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, '于 是 王 高抬 但以理,赏赐 他 许多 上等 礼物,派他 管理 巴比伦 全 省,又立他为总理,掌管 巴比伦 的一切 哲士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, '但以理 求 王,王就派 沙得拉、米煞、亚伯尼歌 管理 巴比伦 省 的 事务,只是但以理 常在 朝中侍立。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, '尼布甲尼撒 王 造了 一个金 像,高 六十 肘,宽 六 肘,立 在巴比伦 省 杜拉 平原。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, '尼布甲尼撒 王 差人 将总督、钦差、巡抚、臬司、藩司、谋士、法官,和各省 的官员 都 召了 来,为尼布甲尼撒 王 所 立 的像 行开 光之礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, '于 是 总督、钦差、巡抚、臬司、藩司、谋士、法官,和各省 的官员 都 聚集了来,要为尼布甲尼撒 王 所立 的像 行开 光之礼,就站 在尼布甲尼撒 所 立 的 像 前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, '那时传令的 大声 呼叫说:「各方、各国、各族(原文是舌:下同)的人哪,有令传 与你们: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, '你们一 听见 角、笛、琵琶、琴、瑟、笙,和各 样 乐器 的声音,就当俯伏 敬拜 尼布甲尼撒 王 所 立 的金 像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, '凡 不 俯伏 敬拜的,必立时 扔 在烈 火 的窑 中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, '因此 各 方、各国、各族 的人民 一听见 角、笛、琵琶、琴、瑟,和各 样 乐器 的声音,就都 俯伏 敬拜 尼布甲尼撒 王 所 立 的金 像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, ' 那 时,有几个 迦勒底人 进前来 控 告 犹大人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, '他们 对尼布甲尼撒 王 说:「愿 王 万岁! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, '王啊,你 曾降 旨 说,凡 听见 角、笛、琵琶、琴、瑟、笙,和各 样 乐器 声音 的都当俯伏 敬拜 金 像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, '凡 不 俯伏 敬拜的,必扔 在烈 火 的窑 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, '现在有 几个 犹大人,就是 王所 派 管理 巴比伦 省 事务 的沙得拉、米煞、亚伯尼歌;王啊,这些 人 不 理 你,不 事奉 你的神,也不 敬拜 你所 立 的金 像。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, '当时,尼布甲尼撒 冲冲大 怒,吩咐 人把沙得拉、米煞、亚伯尼歌 带过来, 他们就把那些 人 带到 王 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, '尼布甲尼撒 问 他们 说:「沙得拉、米煞、亚伯尼歌,你们不 事奉 我的神,也不 敬拜 我所 立 的金 像,是故意的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, ' 你们再听见 角、笛、琵琶、琴、瑟、笙,和各 样 乐器 的声音,若俯伏 敬拜 我所 造 的像,却还可以;若 不 敬拜,必立时 扔 在烈 火 的窑 中,有何 神 能 救 你们脱离 我手呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, '沙得拉、米煞、亚伯尼歌 对王 说:「尼布甲尼撒啊, 这件 事 我们 不 必 回答你; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, '即便如此,我们 所 事奉的 神 能 将我们从 烈 火 的窑 中救出来。王啊,他也必救 我们脱离 你的手; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, '即或 不然,王啊,你 当 知道 我们决不 事奉 你的神,也不 敬拜 你所 立 的金 像。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, '当时,尼布甲尼撒 怒气 填胸,向 沙得拉、米煞、亚伯尼歌 变了 脸色, 吩咐 人把窑 烧热,比寻常 更加 七 倍; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, '又吩咐 他军中 的 几个壮 士,将沙得拉、米煞、亚伯尼歌 捆起来,扔 在烈 火 的窑中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, ' 这 三人 穿著 裤子、内袍、外衣,和别的衣服,被捆起来 扔在 烈 火 的窑 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, ' 因为 王 命 紧急,窑 又甚 热,那 抬 沙得拉、米煞、亚伯尼歌 的人 都被火 焰 烧死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, '沙得拉、米煞、亚伯尼歌 这 三个 人 都被捆著 落在 烈 火 的窑 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, '那时,尼布甲尼撒 王 惊奇,急忙 起来, 对谋士 说:「我捆起来 扔 在火 里 的不是 三个 人吗?」他们回答 王 说:「王啊,是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, '王 说:「看哪,我 见 有四个 人,并没有捆绑,在火 中 游行,也没 有 受伤;那 第四个 的相貌 好像 神 子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, '于 是,尼布甲尼撒 就近 烈 火 窑 门, 说:「至高 神 的 仆人 沙得拉、米煞、亚伯尼歌 出来,上这里来吧!」 沙得拉、米煞、亚伯尼歌 就从 火 中 出来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, '那些总督、钦差、巡抚,和王 的谋士 一同聚集 看 这 三个人,见 火 无 力 伤他们的身体,头 发 也没有 烧焦,衣裳 也没有 变色,并没有 火 燎 的气味。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, '尼布甲尼撒 说:「沙得拉、米煞、亚伯尼歌 的 神 是应当称颂的! 他差遣 使者 救护 倚靠 他 的仆人,他们 不遵 王 命,舍去 己身,在他们 神 以外 不肯 事奉 敬拜 别神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, '现在我 降 旨, 无论 何方、何国、何族的人, 谤讟 沙得拉、米煞、亚伯尼歌 之 神的,必被凌迟,他的房屋 必成 粪堆,因为 没 有 别 神 能 这样 施行拯救。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, '那时 王 在巴比伦 省,高升了 沙得拉、米煞、亚伯尼歌。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, '尼布甲尼撒 王 晓谕住 在全 地 各 方、各国、各族 的人说:「愿 你们大享 平安! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, '我 乐意 将至高的 神 向我 所 行 的神迹 奇事 宣扬出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, '他的神迹 何其 大!他的奇事 何其 盛!他的国 是永远的;他的权柄 存到 万 代! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, '「我 尼布甲尼撒 安居 在宫中,平顺 在殿内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, '我做了 一梦,使我惧怕。我在 床 上的思念,并脑中 的异象,使我惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, '所以我 降 旨 召 巴比伦 的一切 哲士 到我面前,叫他们 把梦 的讲解 告诉我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, '于 是 那些术士、用法术的、迦勒底人、观兆的 都进来,我 将那梦 告诉了 他们,他们却不能 把梦的讲解 告诉 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, ' 末后 那 照我神 的名,称为 伯提沙撒 的但以理 来 到 我面前, 他里头 有圣 神 的灵,我将梦 告诉 他说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, '『术士 的领袖 伯提沙撒啊,因 我 知道 你里头 有圣 神 的灵,什么 奥秘的事 都不能 使你 为难。现在要把我梦 中所 见 的异象 和梦的讲解 告诉我。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, '「我在 床 上脑中 的异象是这样: 我看见 地 当中 有一棵树,极其 高大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, '那树 渐长,而且坚固,高 得顶 天,从地 极 都 能看见, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, '叶子 华美,果子 甚多,可作众生 的食物;田野 的走兽 卧在荫 下,天空 的飞鸟 宿 在枝上;凡 有血气 的都从 这树得食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, '「我 在 床 上脑中 的异象,见 有一位守望 的圣者 从 天 而降。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, '大声 呼叫 说:『伐倒 这树!砍下 枝子!摇掉 叶子!抛散 果子!使走兽 离开  树下,飞鸟 躲开  树枝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, '树墩 却要 留 在地内, 用铁 圈和铜 圈箍住,在田野 的 青草 中让天 露 滴湿,使他 与 地上 的兽 一同吃草, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, '使他的心 改变,不如 人心;给 他 一个兽 心,使他 经过 七 期(期:或译年;本章同)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, '这是守望者 所发 的命,圣者 所出的 令,好叫 世人 知道 至高者 在人 的国中 掌权,要 将国赐与谁 就赐与谁,或立 极卑微的 人 执掌国权。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, '「这是 我─尼布甲尼撒 王 所做的 梦。伯提沙撒啊,你 要说明 这梦的讲解;因为 我国中 的一切 哲士 都 不 能 将梦的讲解 告诉我,惟独你 能,因 你里头 有圣 神 的灵。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, '于 是 称为 伯提沙撒 的 但以理 惊讶 片 时,心意 惊惶。王 说:「伯提沙撒啊,不要 因梦 和梦的讲解 惊惶。」伯提沙撒 回答 说:「我主啊,愿 这梦 归与恨恶你的人,讲解 归与你的敌人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, '你所 见 的树 渐长,而且坚固,高 得顶 天,从 地 极都能看见; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, '叶子 华美,果子 甚多,可作众 生 的食物;田野 的走兽 住在 其下;天空的 飞鸟 宿 在枝上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, '「王啊,这 渐长 又坚固 的树就是 你。你的威势 渐长 及 天,你的权柄 管到地 极。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, '王 既 看见 一位守望的 圣者 从 天 而降,说:『将这树 砍伐 毁坏,树墩 却要 留 在地内, 用铁 圈和铜 圈箍住;在田野 的 青草中,让天 露 滴湿,使他与 地上的 兽 一同吃草,直到 经过 七 期。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, '「王啊,讲解 就是 这样:临 到 我主 我王 的事 是出于 至高者 的命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, '你 必被赶出 离开  世人,与 野地 的兽 同 居, 吃 草 如牛,被天 露 滴湿,且要经过 七 期。等 你知道 至高者 在人 的国 中掌权,要 将国赐与谁 就赐与谁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, '守望者既 吩咐 存留 树 墩,等 你知道 诸天 掌权,以后你的国 必定 归你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, ' 王啊,求你 悦纳 我的谏 𫍝言,以施行公义 断绝 罪过,以怜悯 穷人 除掉罪孽,或者 你的平安 可以 延长。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, '这事都 临 到 尼布甲尼撒 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, '过了 十 二 个月,他游 行 在 巴比伦 王 宫里(原文是上)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, '他 说:「这 大 巴比伦 不 是 我 用大能 大力 建 为 京 都,要显我威严的 荣耀吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, '这话 在王 口中 尚未说完,有声音 从 天 降下,说:「尼布甲尼撒 王啊,有话对你 说,你的国位 离开  你了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, '你 必被赶出 离开  世人,与 野地 的兽 同居, 吃 草 如牛,且要经过 七 期。等 你知道 至高者 在人 的国中 掌权,要将 国赐与谁 就赐与谁。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, '当 时 这话 就应验 在 尼布甲尼撒的身上,他被赶出 离开  世人,吃 草 如牛,身 被天 露 滴湿, 头发 长长,好像鹰毛;指甲长长,如同鸟爪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, '日子 满足,我─尼布甲尼撒 举 目 望天,我的聪明 复归 于 我,我便称颂 至高者,赞美 尊敬 活 到永远的 神。 他的权柄 是永有的;他的国 存到 万 代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, '世上 所有的 居民 都算为 虚无;在天上 的万军 和世上 的居民中,他都凭自己的意旨 行事。无人 能 拦住 他手,或问他 说,你做 什么呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, '那 时,我的聪明 复归 于 我,为我国 的荣耀、威严,和光耀 也都复归 于 我;并且我的谋士 和大臣 也来朝见 我。我又得坚立 在 国位上,至大的 权柄 加增 于 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, '现在 我─尼布甲尼撒 赞美、尊崇、恭敬 天上 的王;因为他所 做的 全都 诚实,他所 行的 也都公平。那行动 骄傲的,他能 降为卑。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, '伯沙撒 王 为他的一千 大臣 设摆 盛 筵,与这一千 人对面 饮 酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, '伯沙撒 欢 饮之间,吩咐 人将他父(或译:祖;下同)尼布甲尼撒 从 耶路撒冷 殿 中所 掠 的金 银 器皿 拿来,王 与大臣、皇后、妃嫔 好用这器皿 饮酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, '于 是 他们把 耶路撒冷 神 殿 库房 中所 掠 的金 器皿 拿来,王 和大臣、皇后、妃嫔 就用这器皿 饮酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, '他们饮 酒,赞美 金、银、铜、铁、木、石 所造的神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, '当 时,忽有人 的 指头 显出,在 王 宫 与灯台 相对 的 粉 墙 上写字。王 看见 写字 的 指头 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, ' 就 变了 脸色,心意 惊惶,腰 骨 好像脱节,双膝 彼此 相碰, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, ' 大声 吩咐 将用法术的 和迦勒底人 并观兆的 领进来, 对巴比伦 的哲士 说, 谁 能读 这 文字,把讲解 告诉我,他必 身穿 紫袍,项 带 金 炼 链 𫔀,在我国中 位 列第三。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, '于 是 王 的一切 哲士 都进来,却不 能 读 那文字,也不能把讲解 告诉 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, ' 伯沙撒 王 就甚 惊惶, 脸色 改变,他的大臣 也都惊奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, '太后(或译:皇后;下同)因 王 和他大臣 所说的话,就进入 宴 宫, 说:「愿 王 万 岁!你心意 不要 惊惶,脸面 不要 变色。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, '在你国中 有 一人, 他里头 有圣 神 的灵,你父 在世的日子,这人心中 光明,又有 聪明 智慧,好像神 的智慧。你父 尼布甲尼撒 王,就是王 的父,立 他为术士、用法术的,和迦勒底人,并观兆的 领袖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, ' 在他 里头 有 美好的 灵性,又有知识 聪明,能圆 梦,释 谜语,解 疑惑。这人名叫但以理, 尼布甲尼撒王 又称 他为 伯提沙撒,现在 可以召他来,他必解明 这意思。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, '但以理 就 被领到 王 前。王 问 但以理 说:「你 是 被掳 之 犹大 人 中 的 但以理吗?就是 我父 王 从 犹大 掳来的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, '我听说 你 里头有神 的灵,心中 光明,又有 聪明 和美好的 智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, '现在 哲士 和用法术的 都领到 我面前,为 叫他们读 这 文字,把讲解 告诉我,无奈他们都不 能 把 讲解 说出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, '我 听说 你 善于  讲 解,能解 疑惑;现在 你若 能 读 这文字,把讲解 告诉我,就必身穿 紫袍,项 戴 金 炼 链 𫔀,在我国中 位 列第三。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, ' 但以理 在王 面前 回答 说:「你的赠品 可以归 你自己,你的赏赐 可以归 给别人;我却要 为王 读 这文字,把讲解 告诉王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, ' 王啊,至高的 神 曾将国位、大权、荣耀、威严 赐 与你父 尼布甲尼撒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, '因 神所 赐 他 的大权,各 方、各国、各族 的人都在 他面前 战 兢 恐惧。 他可以 随意 生 杀, 随意 升 降。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, '但 他心 高气傲,灵 也刚愎,甚至行事狂傲,就被革去 王 位,夺去 荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, '他被赶出 离开  世人,他的心 变 如 兽心,与 野驴 同居,吃 草 如牛,身 被天 露 滴湿,等 他知道 至高的 神 在人 的国中 掌权,凭自己的意旨 立 人 治国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, '伯沙撒啊,你 是他的儿子(或译:孙子),你虽 知道 这 一切,你心 仍不 自卑, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, '竟向 天上 的主 自高,使人将他殿中 的 器皿 拿到 你面前,你 和大臣、皇后、妃嫔 用这器皿 饮 酒。你又赞美 那不能 看、不能 听、无 知无识、金、银、铜、铁、木、石 所 造的神,却没有 将荣耀 归与 那 手中 有你气息,管理你一切 行动的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, '因此 从 神 那里显出 指头来 写 这 文字。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, '「所 写的 文字是:『弥尼,弥尼,提客勒,乌法珥新。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, ' 讲解 是这样:弥尼,就是 神 已经数算 你国 的年日到此完毕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, '提客勒,就是你被称 在天平里,显出 你的亏欠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, '毘勒斯(与乌法珥新同义),就是你的国 分裂,归与 玛代人 和波斯人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, ' 伯沙撒 下令,人就把紫袍 给但以理 穿上,把金 炼 链 𫔀 给他戴在颈项 上,又传令 使他 在国中 位 列第三。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, '当 夜,迦勒底 王 伯沙撒 被杀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, '米底亚人 大利乌 年 六十 二 岁,取了 迦勒底国。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, '大利乌 随 心所愿 ,立 一百 二十 个总督, 治理 通 国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, '又在他们 以上 立总长 三人(但以理 在其中), 使总督 在他们 三人面前 回复 事务,免得 王 受 亏损。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, ' 因 这 但以理 有 美好的 灵性,所以显然 超 乎 其余 馀的总长 和总督,王 又想 立他 治理 通 国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, '那时,总长 和总督 寻 找 但以理 误 国 的 把柄,为要参他;只是找 不 著 他的错误 过失,因 他 忠心办事,毫 无 错误 过失。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, ' 那些 人 便说:「我们要找 参这 但以理 的 把柄,除非 在他 神 的律法 中就 寻 不著。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, '于 是, 总长 和总督 纷纷聚集 来见 王,说:「愿  大利乌 王 万 岁! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, '国中 的总长、钦差、总督、谋士,和巡抚 彼此商议,要立 一条坚定的 禁 令(或译:求王下旨要立一条......), 三十 日 内,不拘何人,若在王 以外,或向 神 或向人 求 什么,就必扔在 狮子 坑中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, '王啊,现在 求你立 这禁令,加盖玉玺,使禁令 决不 更改;照玛代 和波斯人 的例 是 不可 更改的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, '于 是 大利乌 王 立这禁令,加盖玉玺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, '但以理 知道 这禁令盖了 玉玺,就到 自己家里(他楼上 的 窗户 开  向 耶路撒冷), 一日 三次,双膝 跪 在他 神 面前,祷告 感谢,与素常 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, ' 那些 人 就纷纷聚集,见 但以理在他 神 面前 祈祷 恳求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, ' 他们便进到 王 前,提 王的禁令,说:「王啊, 三十 日 内 不拘何 人,若在王 以外, 或向 神 或向人 求什么,必被扔在 狮子 坑中。王不是 在这禁令 上盖了玉玺么?」王 回答 说:「实 有这事,照玛代 和波斯人 的例 是 不可 更改的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, ' 他们 对 王 说:「王啊,那 被掳 之 犹大 人 中 的但以理 不 理 你,也不遵 你盖了玉玺 的 禁令,他竟一日 三 次 祈 祷。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, ' 王 听见 这话,就甚 愁烦,一 心 要救 但以理, 筹划 㓰 解救他,直到 日 落的时候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, ' 那些 人 就纷纷聚集 来见 王,说:「王啊,当知道 玛代人 和波斯人 有例,凡 王 所 立 的禁令 和律例 都 不可 更改。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, ' 王 下令,人就把但以理 带来,扔 在狮子 坑中。王 对但以理 说:「你 所 常 事奉的 神,他 必救你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, '有人搬 石头 放 在 坑 口,王 用自己的玺 和大臣 的印,封闭那坑,使 惩办但以理 的事 毫无 更改。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, ' 王 回 宫,终夜 禁食,无人 拿 乐器 到他面前,并且睡不著 觉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, ' 次日黎明,王 就起来,急忙 往狮子 坑 那里 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, '临近 坑边,哀 声 呼叫 但以理, 对但以理 说:「永生 神 的仆人 但以理啊,你 所 常 事奉的 神 能 救你 脱离 狮子吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, ' 但以理 对 王 说:「愿 王 万 岁! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, '我的 神 差遣 使者,封住 狮子 的口,叫狮子不 伤我;因我在 神面前 无 辜,我 在王 面前 也 没有 行过 亏损的事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, ' 王 就甚 喜乐,吩咐 人将但以理 从 坑里 系上来。于 是但以理 从 坑里 被系上来,身上毫 无 伤损,因为 信靠他的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, '王 下令,人就把 那些 控 告 但以理 的人,连他们 的妻子 儿女 都带来,扔 在狮子 坑中。他们 还 没有 到 坑 底,狮子就抓住(原文是胜了)他们,咬碎 他们的 骨头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, '那时,大利乌 王 传旨,晓谕住 在全 地 各 方、各国、各族的人说:「愿 你们大享 平安! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, '现在我 降 旨 晓谕我所 统辖 的全 国人民,要在但以理 的 神 面前, 战 兢 恐惧。因为 他是 永远 长存 的活 神, 他的国 永不 败坏;他的权柄 永存无极! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, '他护庇人,搭救人,在天上 地下 施行 神迹 奇事, 救了 但以理 脱离 狮子 的口。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, '如此,这 但以理,当大利乌 王在位 的时候和波斯 王古列 在位的时候,大享亨通。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, '巴比伦 王 伯沙撒 元 年,但以理 在 床 上做 梦,见了脑中 的异象,就 记录 这梦,述说 其中的 大意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, '但以理 说:我 夜 里 见 异象,看见 天 的四 风 陡起,刮在大 海之上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, '有四个 大 兽 从 海 中上来,形状 各有不同: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, '头一个 像狮子,有 鹰 的 翅膀;我正 观看的时候, 兽的翅膀 被拔去,兽从 地上 得立起来,用 两脚 站立,像人一样,又得了 人 心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, ' 又有 一兽 如 熊,就是第二兽,旁跨 而坐,口 齿 内 啣著三根 肋骨。有吩咐这兽的 说:起来 吞吃 多 肉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, '此 后 我 观看, 又有一 兽如豹,背 上 有 鸟 的 四个 翅膀;这兽 有四个 头,又得了 权柄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, '其 后 我 在夜间的 异象 中观看,见 第四 兽 甚是可怕,极其 强壮,大有力量,有 大 铁 牙,吞吃 嚼碎,所剩下的 用脚 践踏。这兽 与 前 三 兽 大不相同,头有 十 角。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, '我正 观看 这些角,见 其中 又长起 一个 小 角;先前的 角 中 有三 角在这角前,连根被牠拔出来。 这 角 有眼,像人 的眼,有口 说 夸大的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, '我 观看, 见有宝座 设立,上头坐著 亘古 常在者。他的衣服 洁白 如雪,头 发 如纯净的 羊毛。宝座 乃火 焰,其轮 乃 烈 火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, '从 他面前 有火,像 河 发 出;事奉他 的有千 千,在他面前 侍立 的有万 万;他坐著 要行审判,案卷 都展开 了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, '那时 我 观看, 见 那 兽 因 小角 说 夸大 话 的声音 被杀,身体 损坏,扔 在火中 焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, '其余 馀的 兽,权柄 都被夺去,生命 却仍 存留,直到 所定的时候 和日期。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, '我 在夜间的 异象 中观看,见 有一位像人 子的,驾著 天 云 而 来, 被领 到 亘古 常在 者面前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, '得了 权柄、荣耀、国度,使各 方、各国、各族 的人都事奉 他。他的权柄 是永远的, 不能 废去;他的国必 不 败坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, '至于 我─但以理,我的灵 在我里面 愁烦,我脑中 的异象 使我惊惶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, '我就近 一位 侍立者,问 他 这 一切 的真情。他就告诉 我,将那事 的讲解 给我说明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, '这 四个 大 兽 就是 四 王 将要在 世上 兴起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, '然而,至高者 的圣民,必要得 国 享受,直到 永永 远 远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, '那时 我愿  知道 第四 兽 的真情,牠为何 与 那三兽 的真情大不相同,甚是 可怕,有 铁 牙 铜 爪,吞吃 嚼碎,所剩下的 用脚 践踏; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, ' 头 有 十 角 和那 另 长的一角,在 这角前 有三 角被牠打落。这 角 有 眼,有说 夸大话 的口,形状 强横,过于  牠的同类。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, '我 观看,见这 角 与 圣民 争 战 ,胜了 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, '直到 亘古 常在 者来 给 至高者 的圣民 伸冤,圣民 得 国 的时候 就到了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, '那侍立者这样 说:第四 兽 就是世上 必有 的第四 国, 与 一切 国 大不相同,必吞吃 全 地,并且践踏 嚼碎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, '至于 那十 角,就是从 这国 中必兴起 的十 王,后来 又 兴起一王, 与 先前的 不同;他必制伏 三 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, '他必向 至高者 说 夸大的话,必折磨 至高者 的圣民,必想 改变 节期 和律法。圣民必交付 他手 一载、二载、半 载。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, '然而,审判者 必坐著行审判;他的权柄 必被夺去,毁坏,灭绝,一直到 底。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, '国度、权柄,和 天 下 诸国 的 大权 必赐 给至高者 的圣 民。他的国 是永远的;一切 掌权的 都必事奉 他,顺从他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, '那 事 至 此 完毕。至于 我─但以理,心中 甚是 惊惶,脸色 也改变了,却将那事 存记 在心。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, '伯沙撒 王 在位 第三 年,有异象 现 与 我─但以理,是在先前 所见 的异象之后。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, '我见了 异象的时候,我 以为 在以拦 省 书珊城(或译:宫)中; 我 见 异象 又如在 乌莱 河边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, '我举 目 观看,见 有双角 的 公绵羊 站 在河 边, 两角 都高。这 角高 过 那角,更高的 是后 长的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, '我见 那公绵羊 往西、往北、往南 抵触。兽 在牠面前 都 站立 不住,也没有 能救护 脱离牠手的;但牠任意 而行,自高自大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, '我 正 思想的时候,见 有一只公 山羊 从 西 而来,遍 行全 地,脚不 沾 尘。这山羊 两眼 当中 有一非常的 角。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, '牠往 我所 看见、站 在河 边 有 双角 的公绵羊 那里去,大发 忿怒,向牠 直闯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, '我见 公山羊就 近 公绵羊,向牠 发烈怒,抵触 牠,折断 牠的两 角。绵羊 在牠面前 站立 不 住;牠将绵羊触倒 在地,用脚践踏,没 有 能救 绵羊 脱离牠手的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, '这 山羊 极 其 自高自大,正强盛的时候,那大 角 折断了,又在角根上 向天 的四方(原文是风)长出 四个 非常的角来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, '四角 之中 有一 角长出 一个小 角,向 南、向 东、向 荣美之地,渐渐成为 强大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, '牠渐渐强大,高及 天 象,将些 天象 和 星宿 抛落 在地,用脚践踏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, '并且牠自 高自大,以为高及 天象 之君;除掉 常献给君的燔祭,毁坏 君的圣所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, '因罪过的缘故,有军旅 和 常 献的燔祭交付牠。牠将真理 抛 在地上,任意而行,无不顺利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, '我听见 有一位 圣者 说话,又有一位 圣者 问那 说话 的圣者说:「这除掉常 献的燔祭和施行毁坏 的罪过,将 圣所 与军旅(或译:以色列的军)践踏 的异象,要到 几时才应验呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, '他对我 说:「到 二千 三 百 日,圣所 就必洁净。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, ' 我─但以理 见了 这异象,愿 意明白 其中的意思。忽有 一位形状 像人 的站在 我面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, '我又听见 乌莱河 两岸中 有人 声 呼叫 说:「加百列啊,要使此 人明白 这异象。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, '他便来 到 我所站的地方。他一来,我就惊慌 俯伏 在 地;他对我 说:「人 子啊,你要明白,因为 这是关乎末后 的异象。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, '他与我 说话的时候,我面 伏在 地 沉睡;他就摸 我,扶我 站 起来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, '说:「我 要指示你 恼怒 临完 必有 的事,因为 这是关乎末后 的定期。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, '你所 看见 双角 的公绵羊,就是玛代 和波斯 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, '那公 山羊 就是希腊王(希腊:原文是雅完;下同);两眼 当中 的 大 角 就是 头一 王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, '至于 那折断了的角,在其根上 又长出 四角,这四角就是四 国,必从这国 里兴起来,只是权势 都不及他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, '这四国 末时,犯法的人罪恶 满盈,必有一王 兴起,面貌 凶恶,能用 双关的诈语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, '他的权柄 必大,却不是 因自己的能力;他必行非常的 毁灭,事情顺利,任意而行;又必毁灭 有能力 的和圣 民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, '他用 权术 成就 手 中 的诡计,心里 自高自大,在人坦然无备的时候,毁灭 多人;又要站起来 攻击 万君 之君,至终却非因 人手 而灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, '所 说 二千三百日 的异象 是 真的,但你 要将这异象 封住,因为 关乎后来许多的 日子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, '于 是我─但以理 昏迷不醒,病了 数日,然后起来 办理 王 的事务。我因 这异象 惊奇,却无人 能明白其中的意思。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, '玛代 族 亚哈随鲁 的儿子 大利乌 立为 迦勒底 国 的王 元 年, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, '就是他在位 第一 年,我 但以理 从书上 得知 耶和华 的话 临 到 先知 耶利米,论耶路撒冷 荒凉 的年 数,七十 年 为满。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, '我便禁食,披麻 蒙灰,定 意 向 主 神 祈祷 恳求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, '我向耶和华─我的 神 祈祷、认罪,说:「主 啊,大 而可畏的 神,向爱主、守 主诫命 的人守 约 施慈爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, '我们犯罪 作孽,行恶 叛逆,偏离 你的诫命 典章, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, '没有 听从 你仆人 众先知 奉你名 向 我们君王、首领、列祖,和 国中 一切 百姓 所 说的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, '主啊,你 是公义的,我们 是脸上 蒙羞的;因我们犹大 人 和耶路撒冷 的居民,并以色列众 人,或在近处,或在远处,被你赶到 各 国 的人, 都得罪了 你,正如今 日一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, '主啊,我们 和我们的君王、首领、列祖 因 得罪了 你,就都脸上 蒙羞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, '主─我们的 神 是怜悯 饶恕人的,我们却 违背了 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, '也没有 听从 耶和华─我们 神 的话,没有遵行 他藉 借 仆人 众先知 向我们 所 陈明 的律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, '以色列 众人 都犯了 你的律法,偏行,不 听从 你的话;因此,在你 仆人 摩西 律法 上所 写 的咒诅 和誓言 都倾 在我们身上,因 我们得罪了 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, '他使大 灾祸 临 到我们,成就了 警戒 我们 和 审判我们 官长 的话;原来 在普 天 之下 未 曾行过 像在耶路撒冷 所 行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, ' 这 一切 灾祸 临 到我们身上 是照摩西 律法 上所 写的,我们却没有 求 耶和华─我们 神的恩典,使我们回头 离开 罪孽,明白 你的真理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, '所以耶和华 留意 使 这灾祸 临到我们身上,因为 耶和华─我们的 神 在 他所 行 的事 上都 是公义;我们并没有 听从 他的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, ' 主─我们的 神啊,你曾 用大能的 手 领 你的子民 出埃及 地,使自己 得了 名,正如今 日一样。我们犯了罪,作了恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, '主啊,求 你按 你的大仁大义,使你的怒气 和忿怒 转离 你的城 耶路撒冷,就是你的圣 山。耶路撒冷 和你的子民,因 我们的罪恶 和我们列祖 的罪孽 被四 围 的人羞辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, '我们的 神啊,现在 求你垂听 仆人的 祈祷 恳求,为 自己 使脸 光照 你荒凉的 圣所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, '我的 神啊,求你侧 耳 而听,睁 眼 而看,眷顾我们荒凉 之地和称 为 你名 下 的城。我们 在你面前 恳求,原 不是 因 自己的义,乃 因 你的大 怜悯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, '求主 垂听,求主 赦免,求主 应允 而行,为你自己 不要 迟延。我的 神啊,因 这城 和 这民 都是 称为 你名下的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, '我 说话,祷告,承认 我的罪 和本国之民 以色列 的罪,为我 神 的圣 山,在耶和华─我 神 面前 恳求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, '我 正 祷告的时候,先前 在异象 中所 见 的那位 加百列,奉命迅速 飞来,约在献晚 祭 的时候,按 手在我身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, '他 指教 我 说:「但以理啊,现在 我出来 要使你有智慧,有聪明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, '你初 恳求的时候,就发出 命令,我 来 告诉你,因 你 大蒙眷爱;所以你要思想明白 这以下的事 和异象。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, '「为 你本国之民 和 你圣 城,已经定了 七十个 七。要止住 罪过,除净 罪恶,赎尽 罪孽,引进(或译:彰显)永 义,封住 异象 和预言,并膏 至 圣者(者:或译所)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, '你当知道,当明白,从 出 令 重新 建造 耶路撒冷,直到 有受膏 君的时候,必有七 个七 和六十 二 个七。正在艰难 的时候,耶路撒冷城连街 带濠 都必重新 建造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, '过了 六十 二 个七,那(或译:有)受膏者 必被剪除,一无 所有;必有一王 的民 来 毁灭 这城 和圣所,至终 必如洪水冲没。必有争战 ,一直到 底,荒凉的事 已经定了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, '一 七之内,他必与许多人 坚定 盟约;一七 之半,他必使祭祀 与供献 止息。那行毁坏可憎的(或译:使地荒凉的)如飞而来,并且有忿怒倾在那行毁坏的身上(或译:倾在 那荒凉之地),直到 所定的 结局。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, '波斯 王 古列 第三 年,有事 显给 称 为 伯提沙撒 的但以理。这事 是真的,是指著大 争战 ;但以理通达 这事, 明白 这异象。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, '当那 时,我─但以理 悲伤了 三个 七 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, '美味 我没有 吃,酒 肉 没有 入 我的口,也没有 用油 抹我的身,直到 满了 三个 七 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, '正 月 二十 四 日,我 在 底格里斯 大 河 边, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, '举 目 观看,见 有一 人 身穿 细麻衣,腰 束 乌法 精金带。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, '他身体 如水苍玉,面貌 如 闪电,眼目 如火 把,手 和脚 如 光明的 铜,说话 的声音 如大众 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, ' 这异象 惟有 我─但以理 一人看见, 同著我 的人 没有 看见。 他们 却 大大 战 兢,逃跑 隐藏, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, '只剩下 我 一人。我见了 这 大 异象 便浑身 无 力,面貌 失 色,毫 无 气力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, '我却听见 他说话 的声音,一听见 就 面 伏在 地 沉睡了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, '忽然,有一手 按 在我身上,使我用 膝 和手 掌 支持微起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, '他对我 说:「大蒙眷爱 的 但以理啊,要明白 我 与你 所 说 的话,只管站 起来,因为 我现在 奉差遣 来到你这里。」他对我 说 这 话,我便战 战 兢兢地 立起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, '他就说:「但以理啊,不要 惧怕!因为 从 你第一 日 专 心 求明白将来的事,又在你 神 面前 刻苦己心,你的言语 已蒙应允;我 是因你的言语 而来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, '但波斯 国 的魔君 拦阻 我 二十 一 日。忽然 有大 君(就是天使长;二十一节同)中的一位 米迦勒 来 帮助我,我 就停留 在 波斯 诸王 那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, '现在我来,要使你明白 本国之民 日 后 必遭遇的事,因为 这异象 关乎后来许多的日子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, '他向我 这样 说,我就脸面 朝 地,哑口无声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, '不料,有一位像 人的,摸 我的嘴唇,我便开  口 向 那站 在我面前 的说:「我主啊,因见这异象,我 大大 愁苦,毫 无 气力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, '我主的 仆人 怎 能 与 我主 说话呢?我一见 异象就浑身 无 力,毫 无 气息。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, '有一位形状 像人 的又 摸 我,使我有力量。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, '他说:「大蒙眷爱 的人哪,不要 惧怕,愿 你 平安!你总要 坚强。」他一向我 说话,我便觉得有力量,说:「我主 请说,因 你使我有力量。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, '他就说:「你知道 我为何 来 见你吗?现在 我要回去 与 波斯 的魔君 争战 ,我 去后,希腊(原文是雅完)的魔君 必来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, '但 我要将那录 在真确 书 上的事告诉 你。除了 你们的大君 米迦勒之外,没有 帮助 我 抵挡 这两魔君的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, '又说:「当玛代 王大利乌 元 年,我 曾起来 扶助米迦勒,使他 坚强。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, '现在 我将真事 指示你: 波斯 还有 三 王 兴起,第四 王必 富足 远胜 诸王。他因富足 成为强盛,就必激动 大众 攻击 希腊 国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, '必有一个勇敢的 王 兴起,执掌 大 权,随意 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, '他兴起的时候,他的国 必破裂,向天 的四方(方:原文是风)分开 ,却不 归他的后裔, 治国 的权势 也都不及他;因为 他的国 必被拔出,归与他后裔 之外的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, '南方 的王 必强盛,他将帅 中 必有一个比他 更强盛,执掌权柄,他的权柄 甚大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, '过些年 后,他们必互相连合,南方 王 的女儿 必就了 北方 王 来 立 约;但这女子帮助 之力 存立 不住,王和他所倚靠之力 也不能 存立。这女子 和引导她来的,并生她的,以及当时 扶助她的,都必交与死地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, '但这女子的本家(原文是根)必另生一子(子:原文是枝)继续王位,他必率 领 军队 进 入北方 王 的保障,攻击 他们,而且得胜; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, '并 将他们的神 像和 铸成的偶像,与 金 银 的宝 器 掠到 埃及 去。数年之内,他 不去攻击 北方 的王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, '北方的王(原文是他)必入 南方 王 的国,却要仍回 本地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, '北方王(原文是他)的二子 必动干戈,招聚 许多 军兵。这军兵前 去,如洪水泛滥,又必再去 争战 ,直到 南方王的保障。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, '南方 王 必发烈怒,出来 与 北方 王 争战 ,摆列 大军;北方王的军兵 必交付 他手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, '他的众军 高傲,他的心 也必自高;他虽使数万 人仆倒,却不 得常胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, '北方 王 必回来 摆列 大军,比 先前的 更多。满了 所定的 年数,他必 率领 大 军,带极多的 军装来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, '那时,必有许多 人起来 攻击 南方 王,并且你本国 的强暴 人 必兴起,要应验 那异象,他们却要败亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, '北方 王 必来 筑 垒 攻取 坚固 城;南方 的军兵 必站立 不住,就是选择的精兵(原文是民)也无 力 站住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, '来 攻击他的,必任意 而行,无人在北方王(原文是他)面前 站立得住。他必站 在那荣美 之地,用手 施行毁灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, '他必定 意 用全 国 之力 而来,立公正的约,照约 而行,将自己的女儿 给 南方王 为妻,想要败坏他(或译:埃及),这计却不 得成就,与自己 毫无 益处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, '其后他必转 回 夺取了 许多 海岛。但有一大帅,除掉 他 令人受的羞辱,并且 使这羞辱 归 他本身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, '他就必转 向 本地 的保障,却要绊跌 仆倒,归于 无 有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, '那时,必有一人兴起 接续 他为王,使横征暴敛的人 通行 国中 的荣美地。这王不多 日 就必灭亡,却不 因忿怒,也不 因争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, '必有一个卑鄙的人 兴起 接续 为王,人未 曾将国 的尊荣 给 他,他却趁人坦然无备 的时候,用谄媚的话 得 国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, '必有无数的军兵势 如洪水,在他面前 冲没 败坏;同盟 的君 也必如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, '与 那君结盟 之后,他必行 诡诈,因为他必上来 以微小的军(原文是民)成为强盛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, '趁人坦然无备的时候,他必来到 国中 极肥美之地,行 他列祖 和他列祖 之祖 所 未 曾行的,将掳物、掠物,和财宝 散给 众人,又要设计 攻打 保障,然而这都是 暂时的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, '他必奋 勇向前,率领大 军 攻击 南方 王;南方 王 也必以 极 大 极强 的军兵 与他争 战 ,却站立 不住,因为 有人设 计 谋害南方王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, '吃 王膳的,必败坏他;他的军队 必被冲没,而且被杀 的甚多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, '至于 这二 王,他们心 怀恶计, 同 席 说 谎,计谋却不 成就;因为 到了定期,事就 了结。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, '北方王(原文是他)必带许多 财宝 回往 本国,他的心 反对 圣 约,任意而行,回到 本地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, '到了定期,他必返回,来到 南方。后一次 却不 如 前一次, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, '因为基提 战 船 必来 攻击他,他就丧胆 而回,又要恼恨 圣 约,任意而行;他必回来 联络 背弃 圣 约的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, '他 必兴 兵,这兵必亵渎 圣地,就是保障,除掉 常献的燔祭,设立 那行毁坏 可憎的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, '作恶 违背圣约的人,他必用巧言 勾引;惟独认识 神 的子民 必刚强 行事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, '民间 的智慧人 必训诲 多人;然而他们多日 必倒 在刀下,或被火烧,或被掳掠 抢夺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, '他们仆倒的时候,稍 得 扶助,却有许多 人用谄媚的话 亲近 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, '智慧人 中有些 仆倒的,为要熬炼 其余 馀的人,使他们清净 洁白,直到 末了;因为 到了定期,事就了结。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, '王 必任意 而行,自高 自大,超过 所有的 神,又用 奇异的话 攻击 万神 之神。他必行事亨通,直到 主的忿怒 完毕,因为 所定的事 必然成就。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, '他必不 顾 他列祖 的神,也不 顾 妇女 所羡慕的神, 无论何 神 他都不顾;因为 他必自大,高过 一切。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, '他倒要 敬拜 保障 的神,用金、银、宝 石 和可爱之物 敬奉 他列祖 所 不 认识 的神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, '他必靠 外邦 神的帮助,攻破 最坚固 的保障。凡 承认他的,他必将荣耀 加给他们,使他们管辖 许多人,又为贿赂 分 地与他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, '到末了,南方 王 要与他 交战 。北方 王 必用战 车、马兵,和许多 战 船,势如暴风 来攻击他,也必进入 列国,如洪水泛滥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, '又必进入 那荣美 之地,有许多 国就被倾覆 复,但以东人、摩押人,和一大半 亚扪 人 必脱离 他的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, '他必伸 手 攻击列国;埃及 地 也不 得脱离。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, '他必把持 埃及 的金 银 财宝 和各样的 宝物。利比亚人 和古实人 都必跟从他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, '但从东方 和北方 必有消息 扰乱他,他就大 发烈怒 出去,要将多 人杀灭 净尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, '他必在海 和荣美的 圣 山 中间 设立 他如宫殿 的帐幕;然而到了 他的结局,必无人 能帮助 他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, '那 时,保佑 你本国 之民的天使长(原文是大 君)米迦勒 必站起来,并且有 大艰难, 从有 国 以来直到 此 时,没 有这样的。 你本国的民中,凡 名录 在册上的,必得拯救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, '睡 在尘埃中的,必有多 人复醒。其中有 得永 生的,有 受羞辱 永远 被憎恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, '智慧人 必发光,如同天上的 光;那使多 人归义的,必发光如星,直到永永 远远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, '但以理啊,你 要隐藏 这话,封闭 这书,直到 末 时。必有多 人来往奔跑(或译:切心研究),知识 就必增长。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, '我─但以理 观看,见 另有 两个人 站立:一个 在河 这边,一个 在河 那边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, '有一个问 那 站在河 水 以上、穿 细麻衣 的说:「这奇异的事 到 几时 才应验呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, '我听见 那 站在河 水 以上、穿 细麻衣 的,向 天 举起 左 右手,指著活 到永远 的主起誓 说:「要到 一载、二载、半载,打破 圣 民 权力的时候,这 一切 事就都应验了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, '我 听见这话,却不 明白,就说:「我主啊,这些事 的结局 是怎样呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, '他说:「但以理啊,你只管去;因为 这话 已经隐藏 封闭,直到 末 时。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, '必有许多 人使自己清净 洁白,且被熬炼;但恶人 仍必行恶,一切 恶人 都不 明白,惟独智慧人 能明白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, '从除掉 常献的燔祭,并设立 那行毁坏 可憎之物 的时候,必有一千 二百 九十 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, '等 到 一千 三 百 三十 五 日的,那人便为有福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, '「你 且去 等候结局,因为你必安歇。到了末 期,你必起来,享受你的福分。」    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, '当 乌西雅、约坦、亚哈斯、希西家 作犹大 王,约阿施 的儿子 耶罗波安 作以色列 王 的时候,耶和华 的话 临 到 备利 的儿子 何西阿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, '耶和华 初次 与 何西阿 说话, 对 他 说:「你去 娶 淫妇 为妻,也收那从淫乱 所生的儿女;因为 这地 大 行淫乱,离弃 耶和华。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, '于 是,何西阿去 娶了 滴拉音 的女儿 歌篾。这妇人怀孕,给他 生了 一个儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, '耶和华 对 何西阿说:「给他起名 叫 耶斯列;因为 再过 片时,我必讨 耶户 家 在耶斯列 杀人流血的罪,也必使以色列 家 的国 灭绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, ' 到那 日,我必在耶斯列 平原 折断 以色列 的弓。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, '歌篾又 怀孕 生了 一个女儿,耶和华对 何西阿说:「给她起名 叫罗‧路哈玛(就是不蒙怜悯的意思);因为 我必不 再 怜悯 以色列 家, 决 不赦免 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, '我却要怜悯 犹大 家,使他们靠 耶和华─他们的 神 得救,不 使他们靠 弓、 刀、 争战 、 马匹,与 马兵 得救。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, '歌篾给罗‧路哈玛 断奶以后,又怀孕 生了 一个儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, '耶和华说:「给他起名 叫罗‧阿米(就是非我民的意思);因为 你们 不 作我的子民,我 也不 作你们的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, '然而,以色列 的人 数 必 如 海 沙, 不可 量,不可 数。从前 在什么 地方 对他们 说「你们 不是 我的子民」,将来在那里必对他们 说「你们是永生 神 的儿子」。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, '犹大 人 和以色列 人 必一同 聚集,为 自己立 一个 首领,从 这地 上去(或译:从被掳之地上来),因为 耶斯列 的日子 必为大日。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, '你们要称 你们的弟兄 为阿米(就是我民的意思),称你们的姊妹 为路哈玛(就是蒙怜悯的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, '你们要与你们的母亲 大大 争辩;因为 她 不是 我的妻子,我 也不是 她的丈夫。叫她除掉 脸上 的淫像 和胸 间 的淫态, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, '免得 我剥她的衣服,使她 赤体,与才生 的时候一样,使她 如旷野, 如干旱 之地,因渴 而死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, '我必不 怜悯 她的儿女,因为 他们 是从淫乱 而生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, ' 他们的母亲 行了淫乱,怀他们的母 做了可羞耻的事,因为 她说:我要随 从 所爱的;我的饼、水、羊毛、麻、油、酒 都是他们给的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, '因此, 我必用 荆棘 堵塞 她的道,筑 墙挡住她,使她找 不 著路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, '她必追随 所爱的,却追 不上;她必寻找他们,却寻 不见,便说:我要归 回 前 夫,因我 那时 的光景比 如今 还好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, '她 不 知道 是我 给 她 五谷、新酒,和油,又加增她 的金 银;她却以此供奉(或译:制造) 巴力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, '因此 到了收割的日子,出酒的时候,我必将我的五谷 新酒 收 回,也必将她应当遮 体 的羊毛 和麻 夺回来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, '如今 我必在她所爱的 眼前 显露 她的丑态;必无 人 能救她 脱离我的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, '我也必使她的宴乐、节期、月朔、安息日,并她的一切 大会 都 止息了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, '我也必毁坏 她的葡萄树 和无花果树,就是 她说「这是 我所爱的 给 我 为赏赐」的。我必使 这些树变为 荒林,为田野 的走兽 所吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, '我必追讨她 素日 给 诸巴力 烧香的罪;那时她佩带 耳环 和别样妆饰,随 从 她所爱的,却忘记 我。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, '后来 我 必劝导她,领她 到旷野,对 她说 安慰的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, '她从那里出来,我必赐 她 葡萄园,又赐 她亚割 谷 作为指望 的门。她必在那里 应声(或译:歌唱),与幼年 的日子一样,与从埃及 地 上来 的时候相同。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, '耶和华 说:「 那 日 你必称呼 我伊施(就是我夫的意思),不 再 称呼 我 巴力(就是我主的意思); ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, '因为我必从 我民的口中 除掉 诸巴力 的名号,这名号 不 再 提起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, '当那 日,我必为我的民,与 田野 的走兽 和 空中 的飞鸟,并地 上的昆虫 立 约;又必在国中 折断 弓 刀,止息 争战 ,使他们安然 躺卧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, '我必聘你 永远 归我为妻,以仁义、公平、慈爱、怜悯 聘你 归我; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, '也以诚实 聘你 归我,你就必认识我─ 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, '耶和华 说: 那 日 我必应允,我必应允 天,天 必应允 地; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, '地 必应允 五谷、 新酒,和 油,这些 必应允 耶斯列民(耶斯列就是 神栽种的意思)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, '我必 将她种 在这地。 素不 蒙怜悯的,我必怜悯;本非 我民的,我必对他 说:你是 我的民;他 必说:你是我的 神。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, '耶和华 对我 说:「你再 去 爱 一个淫 妇,就是她情人 所爱的;好像 以色列 人,虽然偏 向 别 神,喜爱 葡萄 饼,耶和华 还是爱 他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, '我便用银子 十 五舍客勒,大麦 一贺梅珥 半,买 她 归我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, '我对她 说:「你当多 日 为我 独居,不可 行淫,不可 归别人 为妻,我 向你 也必这样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, ' 以色列 人 也必多 日 独居,无 君王,无 首领,无 祭祀,无 柱像,无 以弗得,无家中的神像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, '后来 以色列 人 必归回(或译:回心转意),寻求他们的 神─耶和华 和 他们的王 大卫。在末后 的日子,必以敬畏的心 归向 耶和华,领受 他的恩惠。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, '以色列 人哪,你们当听 耶和华 的话。 耶和华 与 这地 的居民 争辩,因 这地上 无 诚实,无 良善,无 人认识 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, '但起假誓,不践前言,杀害,偷盗,奸淫,行强暴,杀人流血,接连不断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, '因此,这地 悲哀,其上 的 民、田野 的兽、空中 的鸟 必都 衰微,海 中的鱼 也 必消灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, '然而,人 都不必 争辩,也不必 指责,因为这民 与抗拒 祭司的人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, '你这祭司必日间 跌倒;先知 也 必夜间 与你 一同跌倒;我必灭绝 你的母亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, '我的民 因无 知识 而灭亡。 你 弃掉 知识,我也必弃掉你,使你不再给我 作祭司。你既忘了你 神 的律法,我 也 必忘记 你的儿女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, '祭司越发增多,就 越发得罪 我;我必使他们的荣耀 变为 羞辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, '他们吃 我民 的赎罪祭,满心 愿 意 我民犯罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, ' 将来民如何,祭司也必如何;我必因他们所行的 惩罚 他们,照他们所做的 报应他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, '他们吃,却不 得饱;行淫,而不 得立后;因为 他们离弃 耶和华,不遵他的命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, '奸淫 和酒,并新酒,夺去 人的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, '我的民 求问 木偶,以为木杖 能指示 他们;因为 他们的淫 心 使他们失迷,他们就行淫 离弃 神,不守约束, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, '在 各山 顶, 各高冈 的橡树、杨树、栗树 之下,献祭 烧香,因为 树影 美好。所以,你们的女儿 淫乱,你们的新妇(或译:儿妇;下同)行淫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, ' 你们的女儿 淫乱, 你们的新妇 行淫,我却不 惩罚她们;因为 你们自己 离群 与 娼妓同居,与 妓女 一同献祭。这无 知 的民 必致倾倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, '以色列啊,你 虽然 行淫,犹大 却不可 犯罪。不要 往吉甲 去,不要 上到伯‧亚文,也不要 指著永生的 耶和华 起誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, ' 以色列 倔强,犹如倔强 的母牛;现在 耶和华 要放他们,如同放羊羔 在宽阔之地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, '以法莲 亲近 偶像,任凭 他吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, '他们所喝的 已经发酸,他们时常 行淫,他们的官长 最 爱 羞耻的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, '风 把他们 裹 在翅膀里;他们因所献的祭 必致蒙羞。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, '众祭司啊,要听 我的话!以色列 家啊,要留心听!王 家啊,要侧耳而听! 审判 要临到你们,因 你们 在米斯巴 如网罗,在 他泊山 如铺张 的网。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, '这些悖逆的人 肆行杀戮,罪孽极深;我 却斥责 他们众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, '以法莲 为我 所知;以色列 不能 向我 隐藏。以法莲哪, 现在 你行淫了,以色列 被玷污了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, '他们所行的 使 他们不能 归 向 神;因 有淫 心 在他们里面,他们也不 认识 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, '以色列 的骄傲 当面 见证自己。故此,以色列 和以法莲 必因自己的罪孽 跌倒;犹大 也 必与他们一同 跌倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, '他们必牵著牛 羊 去 寻求 耶和华,却寻 不见;他已经转去 离开 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, '他们向耶和华 行事诡诈, 生了 私 子。到了 月朔,他们与 他们的地业 必被吞灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, '你们当在基比亚 吹 角,在拉玛 吹号,在伯‧亚文 吹出大声,说:便雅悯哪,有仇敌在你后头! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, '在责罚 的日子,以法莲 必变 为荒场;我在以色列 支派中,指示 将来必成的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, ' 犹大 的首领 如同挪移 地界的人,我必将忿怒 倒 在他们身上,如水一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, '以法莲 因 乐 从 人的命令,就受欺压,被审判 压碎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, '我 使以法莲 如虫蛀之物,使犹大 家 如朽烂之木。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, '以法莲 见 自己有病,犹大见 自己有伤,他们 就打发人 往 亚述 去见 耶雷布 王,他却 不 能 医治 你们,不能 治好 你们的 伤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, ' 我 必向以法莲 如狮子,向犹大 家 如少壮狮子。我 必撕裂 而去,我要夺去,无人 搭救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, '我要回 到 原处,等 他们自觉有罪(或译:承认己罪),寻求 我面;他们 在急难的时候 必切切寻求我。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, '来吧,我们归 向 耶和华! 他 撕裂我们,也必医治;他打伤我们,也必缠裹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, '过两天 他必使我们苏醒,第三 天 他必使我们兴起,我们就在他面前 得以存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, '我们务要认识 耶和华,竭力追求 认识他。他出现 确 如晨光;他必临到 我们 像甘雨,像滋润 田地 的春雨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, '主说:以法莲哪,我可向你 怎样 行呢?犹大啊,我可向你 怎样 做呢?因为你们的良善 如同早晨 的云雾,又如速 散 的甘露。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, '因此,我藉 借先知 砍伐他们,以我口中 的话 杀戮他们;我施行的审判 如光 发出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, ' 我喜爱良善(或译:怜恤),不喜爱 祭祀;喜爱认识 神,胜于 燔祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, '他们 却如亚当 背 约,在境内 向我 行事诡诈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, '基列 是作 孽 之人的城,被血 沾染。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, '强盗成群,怎样埋伏 杀人,祭司 结党,也照样 在示剑 的路上 杀戮,行了 邪恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, '在以色列 家,我见了 可憎的事;在以法莲 那里 有淫行,以色列 被玷污。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, ' 犹大啊,我使被掳 之民 归回的时候,必有为你 所命定 的收场。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, '我想医治 以色列的时候,以法莲 的罪孽 和撒马利亚 的罪恶 就显露出来。 他们行事 虚谎,内有贼人 入室偷窃,外 有强盗成群 骚扰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, '他们心里 并不 思想 我记念 他们的一切 恶;他们所行的 现在 缠绕他们,都在 我面 前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, '他们行恶 使君王 欢喜,说谎 使首领喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, '他们都 是行淫的,像 火炉 被 烤饼的 烧热,从抟 面 麺 到 发面 麺的时候,暂不使 火著旺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, '在我们王 宴乐的日子,首领 因酒 的烈性 成病;王与 亵慢人 拉 手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, '首领埋伏的时候, 心中 热 如火炉,就如烤饼的 整 夜 睡卧,到了早晨 火 气 炎炎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, '众民 也热 如火炉,烧灭 他们的官长。他们的君王 都 仆倒而死;他们中间 无一人 求告 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, '以法莲 与列邦人 搀杂;以法莲 是 没有 翻过 的饼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, '外邦人 吞吃 他劳力得来的,他 却不 知道;头发斑白,他 也 不 觉得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, '以色列 的骄傲 当面 见证自己,虽遭遇这 一切,他们仍不 归 向 耶和华─他们的 神,也不 寻求他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, ' 以法莲 好像鸽子 愚蠢 无 知;他们求告 埃及,投奔 亚述。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, '他们去 的时候,我必将我的网 撒 在他们身上;我要打下他们,如同空中 的鸟。我必按他们会众 所听见的 惩罚他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, '他们 因 离弃 我,必定有祸; 因 违背 我,必被毁灭。我 虽要救赎他们,他们却 向我 说 谎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, '他们并不 诚心 哀求 我,乃 在 床 上呼号;他们为 求五谷 新酒 聚集,仍然悖逆 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, '我 虽教导他们,坚固 他们的膀臂,他们竟图谋 抗拒我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, '他们归向,却不 归向至上者;他们 如同翻背 的弓。他们的首领 必因舌头 的狂傲 倒 在刀下;这 在埃及 地 必作人的讥笑。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, '你用 口 吹角吧!敌人如鹰 来攻打 耶和华 的家;因为 这民违背 我的约,干犯 我的律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, '他们必呼叫 我说:我的 神啊,我们以色列 认识你了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, '以色列 丢弃 良善(或译:福分);仇敌 必追逼他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, '他们 立君王,却不 由我;他们立首领,我却不 认。他们用金 银 为自己 制造 偶像,以致 被剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, '撒马利亚啊,耶和华已经丢弃 你的牛犊;我的怒气 向拜牛犊的人 发作。他们到 几时 方 能 无罪呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, '这牛犊 出于 以色列,是匠人 所造的, 并不是 神。 撒马利亚 的牛犊 必 被打碎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, ' 他们所种的 是风,所收的 是暴风;所种的不成 禾稼,就是发苗 也不 结 实;即便 结实,外邦人 必吞吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, '以色列 被吞吃; 现今 在列国中,好像人不 喜悦 的器皿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, ' 他们 投奔 亚述,如同独行的 野驴; 以法莲 贿买  朋党。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, '他们虽 在列邦中 贿买 人,现在 我却要聚集惩罚他们;他们因君王 和首领 所加的重担 日渐 衰微。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, ' 以法莲 增添 祭坛 取罪;因此,祭坛 使 他 犯罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, '我为他 写了 律法 万条,他却以为 与他 毫无关涉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, '至于 献 给我的祭物,他们自食 其肉,耶和华 却不 悦纳他们。现在 必记念 他们的罪孽,追讨 他们的罪恶;他们 必归回 埃及。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, '以色列 忘记 造他的主,建造 宫殿;犹大 多造 坚固 城,我却要降 火 焚烧他的城邑,烧灭 其中的宫殿。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, '以色列啊,不要 像外邦人 欢喜 快乐;因为 你行邪淫 离弃你的 神,在 各 谷 场上 如妓女喜爱 赏赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, '谷场 和酒醡 都不 够以色列人使用;新酒 也必缺乏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, '他们必不得 住 耶和华 的地;以法莲 却要归回 埃及,必在亚述 吃 不洁净的食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, '他们必不 得向耶和华 奠 酒,即便奠酒也不 蒙悦纳。他们的祭物 必如居丧者 的食物,凡 吃 的必被玷污;因 他们的食物 只为自己的口腹,必不 奉入 耶和华 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, '在大会 的日子,到耶和华 的节 期,你们怎样 行呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, ' 看哪,他们逃避 灾难;埃及人 必收殓他们的尸首,摩弗人 必葬埋他们的骸骨。他们用银子 做的美物 上必长 蒺藜;他们的帐棚中 必生荆棘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, '以色列人 必知道 降罚 的日子 临近,报应 的时候 来到。民说:作先知 的是愚昧;受灵感的 是狂妄,皆因 他们多多 作孽,大 怀怨恨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, '以法莲曾作我 神 守望的;至于 先知,在 他一切的 道 上作为捕鸟 人的网罗,在他 神 的家中 怀怨恨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, '以法莲深深地 败坏,如在基比亚 的日子一样。耶和华必记念 他们的罪孽,追讨 他们的罪恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, '主说:我遇见 以色列 如葡萄 在旷野;我看见 你们的列祖 如无花果树 上春季 初熟的果子。他们 却来到巴力‧毘珥 专拜 那可羞耻的,就成为 可憎恶的,与他们所爱的一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, '至于 以法莲人,他们的荣耀 必如鸟 飞去,必不生产,不怀胎,不成孕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, '纵然 养大 儿女,我却必使他们丧子,甚至不留一个。我离弃 他们,他们就 有祸了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, '我看 以法莲 如 泰尔 栽 于 美地。以法莲 却要将自己的儿女 带出来,交与 行杀戮的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, '耶和华啊,求你加 给他们─加 什么呢?要使 他们 胎 坠 乳 干。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, '耶和华说:他们一切的 恶事 都在吉甲;我在那里 憎恶他们。因 他们所行 的恶,我必从我地 上赶出他们去,不 再 怜爱他们;他们的首领 都 是悖逆的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, '以法莲 受责罚,根本 枯干,必不能 结 果,即或 生产,我必杀 他们所生 的爱子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, '我的 神 必弃绝他们,因为 他们不 听从 他;他们也必 飘流 在列国中。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, '以色列 是茂盛 的葡萄树,结 果繁多。果子 越多,就越增添 祭坛;地土 越肥美,就越造美丽 的柱像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, '他们心 怀二意,现今 要定为有罪。耶和华必 拆毁 他们的祭坛,毁坏 他们的柱像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, ' 他们必说:我们 没有 王,因为 我们不 敬畏 耶和华。王 能为我们 做 什么呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, '他们为立 约 说 谎言,起假 誓;因此,灾罚 如苦菜 滋生 在 田 间的犁沟中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, '撒马利亚 的居民必因伯‧亚文 的牛犊 惊恐;崇拜牛犊的民 和喜爱 牛犊的祭司 都必因 荣耀 离开  它,为它 悲哀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, '人必将牛犊 带 到亚述 当作礼物,献给耶雷布 王。以法莲 必蒙 羞;以色列 必因自己的计谋 惭愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, '至于 撒马利亚,她的王 必灭没,如水 面 的沫子一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, '伯‧亚文 的邱坛─就是以色列 取罪 的地方必被毁灭;荆棘 和蒺藜 必长 在 他们的祭坛上。他们必对大山 说:遮盖我们!对小山说:倒 在我们身上! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, '以色列啊,你从基比亚 的日子 以来时常犯罪。你们的先人曾站 在那里,现今住基比亚 的人以为攻击罪孽 之辈 的战 事 临 不 到自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, '我必随意 惩罚他们。他们为两样 的罪 所缠;列邦的民 必聚集 攻击他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, '以法莲 是驯良 的母牛犊,喜爱 踹谷,我 却将轭加 在 牠肥美 的颈项上,我要使以法莲拉套(或译:被骑)。犹大 必耕田;雅各 必耙地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, '你们要为自己 栽种 公义,就能收割 慈爱。现今正是寻求 耶和华 的时候;你们 要开 垦 荒地,等 他临到,使公义 如雨降 在你们身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, '你们耕种 的是奸恶,收割 的是罪孽,吃 的是谎话 的果子。因 你倚靠 自己的行为,仰赖勇士 众多, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, '所以在这民中 必有 哄嚷之声,你一切的 保障 必被拆毁,就如沙勒幔 在争战  的日子 拆毁伯‧亚比勒,将其中的母 子 一同摔死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, '因 他们的大 恶,伯特利 必使 你们 遭遇如此。到了黎明,以色列 的王 必全然 灭绝。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, '以色列 年幼 的时候,我爱他,就从埃及 召出 我的儿子来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, '先知越发招呼 他们,他们越发 走开 ,向诸巴力 献祭,给雕刻的偶像 烧香。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, '我 原教导 以法莲 行走,用 膀臂 抱著他们,他们却不 知道 是我医治他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, '我用慈绳(慈:原文是人的)爱 索 牵引他们;我 待他们 如人放松 牛的两腮 夹板,把粮食 放 在他们面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, '他们必不 归 回 埃及 地,亚述人 却要作 他们的王,因 他们不肯 归向我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, '刀剑 必临到 他们的城邑,毁坏 门闩,把人吞灭,都因他们随从自己的计谋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, '我的民 偏 要背道离开 我;众先知虽然招呼他们 归向 至上的主,却 无人 尊崇主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, '以法莲哪,我怎能 舍弃你?以色列啊,我怎能弃绝你?我怎能 使你 如押玛?怎能使你 如洗扁?我回 心 转意,我的怜爱 大大 发动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, '我必不 发 猛烈 的怒气,也不 再 毁灭 以法莲。因 我是 神,并非 世人,是你们中间 的圣者;我必不 在怒中 临到你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, '耶和华 必如狮子 吼叫,子民必跟 随他。他 一 吼叫,他们 就从西方 急速而来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, '他们必如雀鸟 从埃及 急速而来,又如鸽子 从亚述 地来到。我必使他们住 自己的房屋。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, '以法莲 用谎话,以色列 家 用诡计 围绕我;犹大 却 靠 神 掌权,向 圣者 有忠心(或译:犹大向 神,向诚实的圣者犹疑不定)。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, '以法莲 吃 风,且追赶 东风,时常 增添 虚谎 和强暴,与 亚述 立 约,把油 送到 埃及。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, '耶和华 与 犹大 争辩,必照雅各 所行的 惩罚他,按他所做的 报应 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, '他在腹中抓住 哥哥 的脚跟,壮年的时候 与 神 较力, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, '与 天使 较力,并且得胜,哭泣 恳求,在伯特利 遇见耶和华。耶和华─万军之 神 在那里 晓谕 我们以色列人;耶和华 是他可记念的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, '所以你 当归向你的 神,谨守 仁爱、公平,常常 等候你的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, '以法莲是商人,手里 有诡诈 的天平,爱 行欺骗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, '以法莲 说:我果然 成了富足,得了 财宝;我所 劳碌得来的,人必不 见 有什么不义, 可算为罪的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, '自从你出埃及 地以来,我就是 耶和华─你的 神;我必使你再 住 帐棚,如在大会 的日子一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, '我 已晓谕 众先知,并且加增 默示,藉 借 先知 设立比喻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, '基列人 没有罪孽 吗?他们全然 是 虚假的。人在吉甲 献牛犊 为祭,他们的祭坛 好像田间 犁沟 中 的乱堆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, '从前雅各 逃到 亚兰 地,以色列 为 得妻 服事人,为 得妻 与人放羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, '耶和华 藉 借 先知 领 以色列 从 埃及上来;以色列也藉 借 先知 而得保存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, '以法莲 大大 惹动主怒,所以他流血 的罪必归 在他身上。主 必将那因以法莲所受的羞辱 归还 他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, '从前以法莲 说话,人都战 兢,他 在以色列中 居处高位;但他在事奉巴力 的事上犯罪 就死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, '现今 他们罪上加 罪,用银子 为自己 铸造 偶像,就是照自己的聪明 制造,都是 匠人 的工作。有人 论说,献祭的 人 可以向牛犊 亲嘴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, '因此,他们必 如早晨 的云雾,又如速散 的甘露,像场上 的糠秕 被狂风吹去,又像烟气 腾于 窗外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, '自从你出埃及 地以来,我就是 耶和华─你的 神。在我以外,你不可 认识 别神;除我以外 并没有 救主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, '我 曾在旷野 干旱 之地 认识你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, '这些民照我所赐的食物 得了饱足;既得饱足,心 就高傲, 忘记了我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, '因此,我 向他们 如 狮子,又如豹 伏 在 道旁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, '我遇见他们 必像丢 崽子的母熊,撕裂他们的胸膛(或译:心 膜)。在那里,我必像母狮 吞吃他们;野 兽 必撕裂他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, '以色列啊,你与我反对,就是 反对帮助你的,自取败坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, '你曾求我说:给我 立 王 和首领。现在 你的王 在哪里呢?治理 你的在哪里呢?让他在你所有的 城 中拯救你吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, '我在怒气中 将王 赐 你,又在烈怒中 将王废去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, '以法莲 的罪孽 包裹;他的罪恶 收藏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, '产妇 的疼痛 必临到 他身上;他是 无 智慧 之子, 到了产 期 不当 迟延。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, '我必救赎他们 脱离 阴间,救赎他们 脱离死亡。死亡啊,你的灾害 在哪里呢?阴间哪,你的毁灭 在哪里呢?在我眼前 绝无 后悔之事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, '他 在弟兄 中 虽然 茂盛,必有东风 刮来,就是耶和华 的风 从旷野 上来。他的泉源 必干;他的源头 必竭;仇敌 必掳掠 他所积蓄的 一切 宝 器。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, '撒马利亚 必担当自己的罪,因为 悖逆她的 神。她必倒 在刀下;婴孩 必被摔死;孕妇 必被剖开 。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, '以色列啊,你要归 向 耶和华─你的 神;你是因 自己的罪孽 跌倒了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, '当归 向 耶和华,用 言语祷告他 说:求你除净 罪孽,悦纳 善行;这样,我们就把嘴唇 的祭代替牛犊 献上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, '我们不 向 亚述 求救,不 骑 埃及的马,也不 再 对我们手 所 造的 说:你是我们的 神。因为孤儿 在你─耶和华那里得蒙怜悯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, '我必医治 他们背道的病,甘心 爱他们;因为 我的怒气 向他们 转消。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, '我必 向以色列 如甘露;他必如百合花 开 放,如黎巴嫩 的树木扎 根。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, '他的枝条 必 延长;他的荣华 如橄榄树;他的 香气 如黎巴嫩的香柏树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, '曾住 在他荫下 的必归回,发旺 如五谷,开 花 如葡萄树。他的香气 如黎巴嫩 的酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, '以法莲必说:我 与偶像 还有 什么关涉呢?我─耶和华回答他,也必顾念他。我 如青翠 的松树;你的果子 从我 而得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, '谁是 智慧人?可以明白这些事;谁是 通达人?可以知道这一切。因为,耶和华 的道 是正直的;义人 必在其中 行走,罪人 却在其上 跌倒。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, '耶和华 的话 临 到 毘土珥 的儿子 约珥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, '老年人哪,当听我的话;国中 的居民哪,都 要侧耳而听。在你们的日子,或 你们列祖 的日子,曾有 这样的事吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, '你们要将这事 传 与子,子 传与孙,孙 传与后 代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, '剪虫 剩下的,蝗虫 来吃;蝗虫 剩下的,蝻子 来吃;蝻子 剩下的,蚂蚱 来吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, '酒醉的人哪,要清醒 哭泣;好 酒的人哪,都 要为 甜酒 哀号,因为 从你们的口中 断绝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, '有一队蝗虫(原文是民) 又强盛 又无 数,侵犯 我的地;牠的牙齿 如狮子 的牙齿,大牙 如母狮的大牙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, '牠 毁坏 我的葡萄树,剥了 我无花果树的皮,剥尽 而丢弃,使枝条 露白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, '我的民哪,你当哀号,像处女 腰束 麻布,为 幼年 的丈夫哀号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, '素祭 和奠祭 从耶和华 的殿中 断绝;事奉 耶和华的 祭司 都悲哀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, '田 荒凉,地 悲哀;因为 五谷 毁坏,新酒 干竭,油 也缺乏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, '农夫啊,你们要惭愧;修理葡萄园的啊,你们要哀号;因为 大麦 小麦 与田间 的庄稼 都灭绝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, '葡萄树 枯干;无花果树 衰残。石榴树、棕树、苹 𬞟果树,连田野 一切的 树木 也 都枯干; 众人 的喜乐 尽都消灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, '祭司啊,你们当腰束 麻布痛哭;伺候 祭坛的啊,你们要哀号;事奉我 神的啊,你们要来 披上麻布 过夜,因为 素祭 和奠祭从你们 神 的殿中 断绝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, '你们要分定 禁食的日子,宣告 严肃会,招聚 长老 和国中 的一切 居民 到耶和华─你们 神 的殿,向 耶和华 哀求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, '哀哉! 耶和华 的日子 临近了。这日来到,好像毁灭 从全能者 来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, '粮食 不是 在我们眼 前 断绝了吗?欢喜 快乐不是从我们 神 的殿中止息了吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, '谷种 在土块 下 朽烂;仓 也荒凉,廪 也破坏;因为 五谷 枯干了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, ' 牲畜 哀鸣;牛 群 混乱,因为 无 草;羊 群 也 受了困苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, '耶和华啊,我向你 求告,因为 火 烧灭 旷野 的草场;火焰 烧 尽 田野 的树木。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, ' 田野 的走兽 向你 发喘;因为 溪 水 干涸,火 也烧灭 旷野 的草场。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, '你们要在锡安 吹 角,在我圣 山 吹出大声。国中 的居民 都 要发颤;因为 耶和华 的日子 将到,已经 临近。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, '那日 是黑暗、幽冥、密云、乌黑 的日子,好像晨光 铺 满 山岭。有一队蝗虫(原文是民)又大 又强;从 来 没 有 这样的,以后 直到 万代 也必 没有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, '牠们前面 如火 烧灭,后面 如火焰 烧尽。未到以前,地 如伊甸 园;过去以后,成了荒凉 的旷野;没有 一样 能 躲避牠们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, '牠们的形状 如马,奔跑 如 马兵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, '在 山 顶 蹦跳 的响声如车辆 的响声,又如火 焰 烧 碎秸 的响声,好像强盛的 民 摆阵 预备打仗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, '牠们一来,众民 伤恸,脸 都 变色。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, '牠们如勇士 奔跑,像战  士 爬 城;各都 步行,不 乱 队伍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, '彼此 并不 拥挤,向前各 行 其路,直 闯 兵器,不 偏左右。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, '牠们蹦 上城,蹿 上墙,爬 上房屋,进 入 窗户 如同盗贼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, '牠们一来,地 震 天 动,日 月 昏暗,星宿 无 光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, '耶和华 在他军旅 前 发 声, 他的队伍 甚 大; 成就 他命 的是强盛者。因为 耶和华 的日子 大 而可畏,谁 能当得起呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, '耶和华 说:虽然 如此,你们应当禁食、哭泣、悲哀,一 心 归 向我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, '你们要撕裂 心肠,不 撕裂衣服。归 向 耶和华─你们的 神;因为 他有 恩典,有怜悯,不轻易 发怒,有丰盛的 慈爱,并且后悔不降 所说的灾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, '或者他转意 后悔,留下 余 馀 福,就是留下献给耶和华─你们 神 的素祭 和奠祭,也未 可知。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, '你们要在锡安 吹 角,分定 禁食的日子,宣告 严肃会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, '聚集 众民,使会众 自洁:招聚 老者,聚集 孩童 和吃 奶的;使新郎 出 离洞房,新妇 出离内室。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, '事奉 耶和华 的祭司 要在廊子 和祭坛 中间 哭泣,说:耶和华啊,求你顾惜 你的百姓,不要 使 你的产业 受羞辱,列邦 管辖 他们。为何 容列国的人 说:「他们的 神 在哪里」呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, '耶和华 就为自己的地 发热心,怜恤 他的百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, '耶和华 应允 他的百姓 说:我必 赐 给你们 五谷、新酒,和油,使你们 饱足;我也不 再 使 你们 受列国 的羞辱; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, '却要使 北方 来的军队远离 你们,将他们赶 到 干旱 荒废 之地: 前队 赶入 东 海,后队 赶入 西 海;因为 他们所行的大恶(原文是事),臭气 上升,腥味 腾空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, '地土啊,不要 惧怕;要欢喜 快乐,因为 耶和华 行了 大事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, '田野 的走兽啊,不要 惧怕;因为,旷野 的草 发生, 树木 结 果,无花果树、葡萄树 也都效 力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, '锡安 的民哪,你们要快乐,为耶和华─你们的 神 欢喜;因 他赐 给你们 合宜的 秋雨,为你们 降下 甘霖,就是秋雨、春雨,和先前一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, '禾场 必满了 麦子;酒醡 与油醡必有新酒 和油 盈溢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, '我打发 到你们中间的 大 军队,就是 蝗虫、蝻子、蚂蚱、剪虫, 那些年 所 吃的,我要补还 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, '你们必多 吃 而得饱足,就赞美 为你们 行 奇妙事 之耶和华─你们 神 的名。我的百姓 必永远 不致 羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, '你们必知道 我是 在以色列 中间,又知道我是 耶和华─你们的 神;在我以外并无 别神。我的百姓 必永远 不致 羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, ' 以后,我要将 我的灵 浇灌 凡 有血气的。你们的儿 女 要说预言;你们的老年人 要做 异梦,少年人 要见 异象。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, '在那些 日子,我要将 我的灵 浇灌 我的仆人 和使女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, '「在天上 地下,我要显出 奇事,有血,有火,有烟 柱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, '日头 要变 为黑暗,月亮 要变为血,这都在耶和华 大 而可畏的 日子 未到 以前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, '到那时候,凡 求告 耶和华 名 的就必得救;因为 照耶和华 所 说的,在锡安 山,耶路撒冷 必有 逃脱的人,在剩下的人中 必有耶和华 所 召的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, '「 到那 日, 我使 犹大 和耶路撒冷 被掳之人 归回 的时候, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, '我要聚集 万 民,带 他们下 到 约沙法 谷,在那里 施行审判;因为 他们将 我的百姓,就是我的产业 以色列,分散 在列国中,又分取 我的地土, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, '且为 我的百姓 拈 阄,将 童子 换妓女,卖 童女 买 酒 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, '「泰尔、西顿,和非利士 四 境的人哪, 你们 与我 何干?你们 要报复 我吗?若 报复 我,我必使报应 速速 归 到你们的头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, '你们既然 夺取 我的金 银,又将我可爱的 宝物 带 入你们宫殿(或译:庙中), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, '并将犹大 人 和耶路撒冷 人 卖 给希腊 人(原文是雅完人),使 他们远离 自己的境界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, '我 必激动他们 离开  你们所 卖到 之地,又必使报应 归 到你们的头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, '我必将 你们的儿 女 卖 在犹大 人 的手中,他们必卖 给 远方 示巴 国的人。这是 耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, '当在万民中 宣告说:要预备 打仗;激动 勇士,使一切 战  士 上 前来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, '要将犁头 打 成刀剑,将镰刀 打成戈矛;软弱的 要说:我有 勇力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, '四围的 列 国啊,你们要速速地 来,一同聚集。耶和华啊,求你使你的大能者 降临。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, '万民 都当兴起,上 到 约沙法 谷;因为 我必坐 在那里,审判 四围的 列 国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, '开  镰吧!因为 庄稼 熟了; 践踏吧!因为 酒醡 满了。酒池 盈溢; 他们的罪恶 甚大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, '许多 许多的人 在断定 谷,因为 耶和华 的日子 临近 断定 谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, '日 月 昏暗,星宿 无 光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, '耶和华 必从锡安 吼叫,从耶路撒冷 发 声,天 地 就震动。耶和华 却要作他百姓 的避难所,作以色列 人 的保障。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, '你们就知道 我是 耶和华─你们的 神,且又住 在锡安─我的圣 山。那时,耶路撒冷 必成为 圣;外邦人 不 再 从其中 经过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, ' 到那 日,大山 要滴 甜酒;小山 要流 奶子;犹大 溪河 都 有水 流。必有泉源 从耶和华 的殿中 流出来,滋润 什亭 谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, '埃及 必然 荒凉,以东 变 为凄凉 的旷野,都因向犹大 人 所行的强暴,又因 在本地 流 无辜人 的血。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, '但犹大 必存 到永远;耶路撒冷 必存到万代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, '我未曾报复(或译:洗除;下同)流血的罪,现在我要报复,因为耶和华 住 在锡安。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, '当 犹大 王 乌西雅,以色列 王 约阿施 的儿子 耶罗波安 在位的时候,大地震 前 二年,提哥亚 牧人中的 阿摩司得 默示 论 以色列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, '他说:耶和华 必从锡安 吼叫,从耶路撒冷 发 声;牧人 的草场 要悲哀;迦密 的山顶 要枯干。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, '耶和华 如此 说:大马士革 三番 四次 地犯罪,我必不 免去她的刑罚;因为 她以打粮食的铁 器 打过 基列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, '我却要降 火 在哈薛 的家中,烧灭 便哈达 的宫殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, '我必折断 大马士革 的门闩,剪除 亚文 平原 的居民和伯•伊甸 掌 权的。亚兰 人 必被掳 到吉珥。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, '耶和华 如此 说:迦萨 三番 四次 地犯罪,我必不 免去她的刑罚;因为 她掳掠 众 民 交 给以东。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, '我却要降 火 在迦萨 的城内,烧灭 其中的宫殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, '我必剪除 亚实突 的居民 和亚实基伦 掌 权的,也必反 手 攻击 以革伦。非利士人 所余 馀剩的 必都灭亡。这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, '耶和华 如此 说:泰尔 三番 四次 地犯罪,我必不 免去她的刑罚;因为 她将众 民 交 给以东,并不 记念 弟兄的 盟约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, '我却要降 火 在泰尔 的城内,烧灭 其中的宫殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, '耶和华 如此 说:以东 三番 四次 地犯罪,我必不 免去她的刑罚;因为 她拿刀 追赶 兄弟,毫无 怜悯,发怒 撕裂,永 怀 忿怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, '我却要降 火 在提幔,烧灭 波斯拉 的宫殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, '耶和华 如此 说:亚扪 人 三番 四次 地犯罪,我必不 免去他们的刑罚;因为 他们剖开  基列 的孕妇, 扩张 自己的境界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, '我却要在争战  呐喊 的日子,旋风 狂暴 的时候,点 火 在拉巴 的城内,烧灭 其中的宫殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, '他们的王 和首领 必 一同 被掳 去。这是耶和华 说的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, '耶和华 如此 说:摩押 三番 四次 地犯罪,我必不 免去她的刑罚;因为 她将以东 王 的骸骨 焚烧 成灰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, '我却要降 火 在摩押,烧灭 加略 的宫殿。摩押 必在哄嚷 呐喊 吹角 之中 死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, '我必剪除 摩押中 的审判者,将其中的一切 首领 和他一同 杀戮。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, '耶和华 如此 说:犹大人 三番 四次 地犯罪,我必不 免去他们的刑罚;因为 他们厌弃 耶和华 的训诲,不 遵守 他的律例。他们列祖 所 随从 虚假的偶像 使他们走 迷了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, '我却要降 火 在犹大,烧灭 耶路撒冷 的宫殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, '耶和华 如此 说:以色列人 三番 四次 地犯罪,我必不 免去他们的刑罚;因 他们为银子 卖了 义人,为 一双鞋 卖了穷人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, '他们见穷人 头上 所蒙 的灰 也都垂涎,阻碍 谦卑人 的道路。父 子 同 一个女子 行淫, 亵渎 我的圣 名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, '他们在各 坛 旁 铺人所当 的衣服,卧 在其上,又在他们神 的庙 中喝 受罚之人 的酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, '我 从以色列人面前 除灭 亚摩利人。他 虽高大 如香柏树, 坚固 如橡树,我却上 灭 他的果子,下 绝他的根本。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, '我 也将你们 从埃及 地 领上来,在旷野 引导 你们 四十 年,使你们得 亚摩利人 之地 为业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, '我从你们子弟中 兴起 先知,又从你们少年人中 兴起拿细耳人。以色列 人哪,不是 这样吗?这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, '你们却给 拿细耳人 酒 喝,嘱咐 先知 说:不要 说预言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, '看哪,在你们所住之地,我 必压 你们,如同 装满 禾捆 的车 压物一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, '快跑的 不能 逃脱;有力的 不能 用 力;刚勇的 也不能 自 救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, '拿 弓 的不能 站立;腿 快 的不能 逃脱;骑 马 的也不能 自 救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, '到那 日,勇士中 最有胆量的,必赤身 逃跑。这是耶和华 说的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, '以色列 人哪, 你们全 家 是 我从埃及 地 领上来的,当听 耶和华 攻击你们的 话: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, '在地上 万 族中,我只 认识 你们;因此,我必追讨 你们的 一切 罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, '二 人若 不 同心,岂能同 行呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, '狮子 若非 抓食,岂能在林中 咆哮呢?少壮狮子 若 无 所得,岂能从洞中 发 声呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, '若没有 机槛,雀鸟 岂能陷 在 网罗里呢?网罗 若无 所 得,岂能从 地上 翻起呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, '城中 若 吹 角,百姓 岂不 惊恐呢?灾祸 若 临 到一城,岂非 耶和华 所降的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, ' 主 耶和华 若 不 将奥秘 指示 他的仆人─众先知,就 一无 所 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, '狮子 吼叫,谁 不 惧怕呢?主 耶和华 发命,谁 能不 说预言呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, '要在 亚实突 的宫殿中 和 埃及 地 的宫殿 里传扬 说:你们要聚集 在 撒马利亚 的山上,就看见 城中 有何等大的 扰乱 与欺压的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, '那些以强暴 抢夺财物、积蓄 在自己家中 的人不 知道 行 正直的事。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, '所以 主 耶和华 如此 说:敌人 必来围攻 这地,使你 的势力 衰微,抢掠 你的家宅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, '耶和华 如此 说:「牧人 怎样 从狮子 口 中抢回 两条 羊腿 或 半个 耳朵,住 撒马利亚 的以色列 人 躺卧在床 角上 或铺绣花毯 的榻上,他们得救 也不过如此。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, '主 耶和华─万军之 神 说:当听这话,警戒 雅各 家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, ' 我讨 以色列 罪 的日子,也要讨 伯特利 祭坛的罪;坛 角 必被砍下,坠落 于 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, '我要拆毁 过冬和 过夏 的房屋。象牙 的房屋 也必毁灭;高大 的房屋 都归无有。这是耶和华 说的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, '你们 住撒马利亚 山 如巴珊 母牛的啊,当听我的 话─你们欺负 贫寒的,压碎 穷乏的,对家主 说:拿酒来,我们喝吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, '主 耶和华 指著自己的圣洁 起誓说: 日子 快到,人必用钩子 将你们 钩去,用鱼 钩 将你们余 馀剩的钩去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, '你们各人 必从破口 直往前 行,投 入哈门。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, '以色列 人哪,任你们往 伯特利 去犯罪,到吉甲 加增 罪过;每日早晨 献上 你们的祭物,每三 日 奉上你们的十分之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, '任你们献有酵的 感谢 祭,把甘心祭 宣传 报告给众人,因为 是 你们所喜爱的。 这是主 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, ' 我 使 你们 在一切 城 中牙齿 干净,在你们各 处 粮食 缺乏,你们仍不 归向 我。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, ' 在收割 的前 三 月,我 使 雨 停止,不降在你们那里;我降雨 在 这 城,不 降雨 在 那 城;这 块 地 有雨,那块地 无 雨;无雨的就枯干了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, '这样,两 三 城的人 凑 到 一 城 去找 水,却喝不 足;你们仍不 归 向我。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, '我以旱风、霉烂 攻击 你们,你们园中 许多菜蔬、葡萄树、无花果树、橄榄树 都被剪虫 所吃;你们仍不 归 向我。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, '我降 瘟疫 在你们中间,像在埃及 一样;用刀 杀戮 你们的少年人, 使你们的马匹 被掳掠,营 中尸首的臭气 扑 鼻;你们仍不 归 向我。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, '我倾覆 复 你们中间的城邑,如同我 从前倾覆 复 所多玛、 蛾摩拉一样,使你们 好像从火 中抽出来 的一根柴;你们仍不 归 向我。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, ' 以色列啊,我必向你 如此 行;以色列啊,我既 这样 行,你当预备 迎见你的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, ' 那创 山、造 风、将 心意 指示 人、使 晨光 变为幽暗、脚踏 在 地 之高处的,他的名 是耶和华─万军之 神。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, '以色列 家啊,要听 我 为你们 所 作的 哀歌: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, '以色列民(原文是处女)跌倒,不得 再 起;躺 在地 上,无人 搀扶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, ' 主 耶和华 如此 说:以色列 家 的城 发出 一千兵的,只剩 一百;发出 一百的,只剩 十个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, ' 耶和华 向以色列 家 如此 说:你们要寻求我,就必存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, '不要 往伯特利 寻求,不要 进入 吉甲,不要 过 到别是巴;因为 吉甲 必 被掳掠,伯特利 也必 归于 无有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, '要寻求 耶和华,就必存活,免得 他在约瑟 家 像火 发出,在伯特利 焚烧,无人 扑灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, '你们这使公平 变为 茵𫈟、将公义 丢弃 于 地的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, '要寻求那造 昴星 和参星,使死荫 变为 晨光,使白日 变为黑 夜,命 海 水 来浇 在 地 上的─耶和华 是他的名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, '他使 力强的 忽遭灭亡,以致 保障 遭遇 毁坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, '你们怨恨 那在城门口 责备人的,憎恶 那说 正直话的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, ' 你们践踏 贫民,向他们 勒索 麦子;你们用凿过的石头 建造 房屋,却不得 住 在其内;栽种 美好 的葡萄园,却不得 喝 所出的酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, ' 我知道 你们的罪过 何等多,你们的罪恶 何等大。你们苦待 义人,收受 贿赂,在城门口 屈枉 穷乏人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, '所以 通达人 见这样的 时势 必静默不言,因为 时势 真 恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, '你们要求 善,不要 求恶,就必 存活。这样,耶和华─万军之 神 必照你们所 说的 与你们 同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, '要恶 恶 好 善,在城门口 秉 公行义;或者 耶和华─万军之 神 向约瑟 的余 馀民 施恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, ' 主 耶和华─万军之 神 如此 说:在一切 宽阔处 必有哀号的声音;在各 街市上 必有人说:哀哉!哀哉!又必叫 农夫 来 哭号,叫善 唱哀歌的 来 举哀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, '在各 葡萄园 必有哀号的声音,因为 我必从你中间 经过。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, '想望 耶和华 日子 来到的有祸了!你们 为何想望 耶和华 的日子呢?那日 黑暗 没有 光明, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, '景况好像 人 躲避 狮子 又遇见 熊,或是进 房屋 以手 靠 墙,就被蛇 咬。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, '耶和华 的日子 不是 黑暗 没有 光明吗?不是幽暗 毫无 光辉吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, '我厌 恶 你们的节期,也不 喜悦 你们的严肃会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, '你们虽然 向我 献 燔祭 和素祭,我却不 悦纳,也不 顾 你们用肥畜 献的平安祭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, '要使你们歌唱 的声音 远离 我,因为我不 听 你们弹琴 的响声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, '惟愿 公平 如大水 滚滚,使公义 如江河 滔滔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, '「以色列 家啊,你们在旷野 四十 年,岂是将祭物 和供物 献 给我呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, '你们抬著 为自己所 造 之摩洛 的帐幕和 偶像 的龛,并你们的神 星。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, '所以我要把你们 掳 到大马士革 以外。」这是耶和华、名 为万军之 神 说的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, '国为列国 之首,人最著名,且为以色列 家 所归向,在锡安 和撒马利亚 山 安逸 无虑的,有祸了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, '你们要过 到甲尼 察看,从那里 往大城 哈马 去,又下到 非利士人 的迦特。看那些 比 你们的国 还强吗? 境界 比你们的境界 还宽吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, '你们以为降祸 的日子 还远,坐在位 上尽行强暴(或译:行强暴使审判临近)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, '你们躺卧 在 象牙 床上,舒身 在 榻上,吃 群中 的羊羔,棚 里 的牛犊; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, '弹琴鼓瑟,唱消闲的歌曲,为自己 制造 乐 器,如同大卫所造的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, '以大碗 喝 酒,用上等 的油 抹身,却不 为 约瑟 的苦难 担忧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, '所以 这些人必 在被掳的人 中首先 被掳,舒身的人 荒宴之乐 必消灭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, '主 耶和华 万军之 神 指著自己 起誓 说,我 憎恶 雅各 的荣华,厌弃 他的宫殿;因此我必将城 和其中所有的 都交付敌人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, '那时,若 在一 房 之内剩下 十个 人,也都必死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, '死人的伯叔,就是烧他尸首的,要将这尸首 搬 到 房外,问房屋 内间 的人 说:「你那里 还有人没有?」他必说:「没有」;又说:「不要作声,因为 我们不可 提 耶和华 的名。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, ' 看哪,耶和华 出令,大 房 就被攻 破,小 屋 就被打裂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, '马 岂能在崖石上 奔跑?人岂能 在那里用牛 耕种呢?你们却 使公平 变为 苦胆,使公义 的果子 变为茵𫈟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, '你们喜爱 虚浮 的事,自夸说,我们不是 凭自己的力量 取了 角吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, ' 耶和华 万军之 神 说:以色列 家啊,我必兴起 一国 攻击你们;他们必欺压 你们,从哈马 口 直到 亚拉巴 的河。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, '主 耶和华 指示我 一件事: 为王 割菜(或译:草)之后,菜又发生;刚 发 生的时候,主造 蝗虫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, ' 蝗虫吃 尽 那地 的青物,我就说:「主 耶和华啊,求 你赦免;因为 雅各 微弱,他 怎能 站立得住呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, '耶和华 就后悔, 说:「这灾可以 免了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, '主 耶和华 又指示我 一件事: 他 命 火 来惩罚以色列,火就吞灭 深 渊,险些将 地 烧灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, '我就说:「主 耶和华啊,求 你止息;因为 雅各 微弱,他 怎能 站立得住呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, '耶和华 就后悔, 说:「这灾也 可 免了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, '他又指示我 一件事: 有一道墙 是按准绳建筑的,主 手拿 准绳 站 在其上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, '耶和华 对我 说:「阿摩司啊,你 看见 什么?」我说:「看见准绳。」主 说:「 我要吊起 准绳 在我民 以色列 中,我必不 再 宽恕 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, '以撒 的邱坛 必然凄凉,以色列 的圣所 必然荒废。我必兴起,用刀 攻击 耶罗波安 的家。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, '伯特利 的祭司 亚玛谢 打发 人到 以色列 王 耶罗波安那里,说:「阿摩司 在以色列 家 中 图谋 背叛你; 他所说的一切 话,这国 担当 不 起; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, '因为 阿摩司 如此 说:『耶罗波安 必被刀 杀,以色列民 定 被掳去 离开  本地。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, '亚玛谢 又对 阿摩司 说:「你 这先见哪,要逃 往 犹大 地 去,在那里 糊口,在那里 说预言, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, '却不要 在伯特利 再 说预言;因为 这里有 王 的圣所,有 王 的宫殿。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, '阿摩司 对 亚玛谢 说:「我 原不是 先知,也不是 先知的门徒(原文是儿子)。我是 牧人,又是 修理 桑树的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, '耶和华 选召我,使我不跟从 羊群, 对我 说:『你去 向 我民 以色列 说预言。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, '亚玛谢啊,现在 你要听 耶和华 的话。你 说:『不要 向 以色列 说预言,也不要 向 以撒 家 滴下预言。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, '所以 耶和华 如此 说:『你的妻子 必在城中 作妓女,你的儿 女 必倒 在刀下;你的地 必有人用绳子 量了分取,你自己 必死 在 污秽 之地。以色列民 定 被掳去 离开  本地。』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, '主 耶和华 又指示我 一件事:我看见 一筐 夏天的果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, '他说:「阿摩司啊,你 看见 什么?」我说:「看见一筐 夏天的果子。」耶和华 说:「 我民 以色列 的结局 到了,我必不 再 宽恕 他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, '主 耶和华 说:「那 日,殿 中的诗歌 变为哀号;必有许多 尸首 在各 处 抛弃,无人作声。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, '你们这些要吞吃 穷乏人、使困苦人 衰败的,当听 我的话! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, '你们说:月朔 几时 过去,我们好卖 粮;安息日几时过去,我们好摆开  麦子;卖出用小 升斗,收银用大 戥子,用诡诈 的天平 欺哄人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, '好用银子 买  贫寒人,用一双鞋 换 穷乏人,将坏了 的麦子 卖给人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, '耶和华 指著雅各 的荣耀 起誓说:他们的一切 行为,我必 永远 不忘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, '地 岂不 因 这事 震动?其上的 居民 不也悲哀吗?地必全然 像尼罗河 涨起,如同埃及 河 涌上 落下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, '主 耶和华 说: 到那 日,我必使日头 在午间 落下,使地 在白 昼 黑暗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, '我必使你们的节期 变为 悲哀, 歌曲 变为哀歌。 众人 腰 束 麻布, 头 上光秃,使 这场悲哀 如丧独生子,至终 如痛苦 的日子一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, '主 耶和华 说: 日子 将到,我必命 饥荒 降在地上。人饥饿 非 因无饼,干渴 非 因无水,乃因 不 听 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, '他们必飘流,从这海 到 那海,从北边 到 东边,往来奔跑,寻求 耶和华 的话,却寻 不著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, '当那 日,美貌 的处女 和少年的男子 必因干渴 发昏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, '那指著撒马利亚牛犊(原文是罪)起誓的 说:但哪,我们指著你那里的活 神起誓;又说:我们指著别是巴 的神道(神:原文是活)起誓。这些人都必仆倒,永不 再 起来。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, '我看见 主 站 在 祭坛旁边;他说:你要击打 柱顶,使门槛 震动,打碎柱顶,落在众人 头上;所剩下的人,我必用刀 杀戮,无 一人 能逃避,无 一人 能逃脱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, '他们虽然 挖透 阴间, 我的手 必取出他们来;虽然 爬上 天去, 我必拿下他们来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, '虽然 藏 在迦密 山顶, 我必搜寻,捉出他们来;虽然 从我眼 前 藏 在海 底, 我必命 蛇 咬他们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, '虽被 仇敌 掳 去, 我必命 刀剑 杀戮他们;我必向他们 定住 眼目,降祸 不 降福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, '主─万军 之耶和华 摸 地,地就消化,凡 住 在地上 的都必悲哀。地必全然 像尼罗河 涨起,如同埃及 河 落下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, '那在天上 建造 楼阁、在地上 安定 穹苍、命 海 水 浇 在地 上的─耶和华 是他的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, '耶和华 说:以色列 人哪,我 岂不 看你们 如古实 人吗?我岂不是 领 以色列人 出埃及 地,领非利士人 出迦斐托 讬,领亚兰人 出吉珥吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, ' 主 耶和华 的眼目 察看这有罪 的国,必将这国 从 地 上 灭绝,却 不 将 雅各 家 灭绝 净尽。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, ' 我必 出令,将 以色列 家 分散 在列 国中,好像 用筛子 筛谷,连一粒 也不 落 在地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, '我民 中的一切 罪人 说:灾祸 必追不 上我们,也迎 不著我们。他们必死 在刀下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, '到那 日,我必建立 大卫 倒塌的 帐幕,堵住 其中的破口,把那破坏的 建立起来,重新修造,像古 时一样, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, ' 使以色列人得 以东 所余 馀剩的 和所有 称为 我名下 的国。此乃行 这事 的耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, ' 耶和华 说:日子 将到,耕种的 必接续 收割的;踹 葡萄 的必接续撒 种的;大山 要滴下 甜酒;小山 都必流奶(原文是消化,见约珥三章十八节)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, '我必使 我民 以色列 被掳的 归回;他们必重修 荒废 的城邑 居住,栽种 葡萄园,喝 其中所出的酒,修造 果木园,吃 其中的果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, '我要将他们栽 于  本地,他们不 再 从 我所 赐 给他们 的地上 拔出来。这是耶和华─你的 神 说的。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, '俄巴底亚 得了耶和华 的默示。论 以东 说:我从 耶和华 那里听见 信息,并有使者 被差 往列国去,说:起来吧,一同起来 与以东 争战 ! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, ' 我使 你─以东在列国中 为最小的,被人大大 藐视。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, '住 在山 穴中、居所 在高处的啊,你因狂傲 自欺,心里 说:谁 能将我拉下 地去呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, '你虽 如大鹰 高飞, 在星宿 之间 搭 窝,我必从那里 拉下你来。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, '盗贼 若 来 在你那里,或 强盗 夜间而来─你何竟 被剪除─岂不 偷窃 直到够了呢?摘葡萄的 若 来 到你那里,岂不 剩下 些葡萄呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, '以扫 的隐密处何竟 被搜寻?他隐藏的宝物 何竟被查出? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, '与你结盟 的 都 送你上路,直到 交界;与你和好 的 欺骗你,且胜过 你;与你一同吃饭的 设下 网罗 陷害你;在你心里 毫无 聪明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, '耶和华 说:到那 日,我岂不 从以东 除灭 智慧人?从以扫 山 除灭聪明人? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, '提幔哪,你的勇士 必惊惶,甚至 以扫 山的 人 都被杀戮 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, '因你向兄弟 雅各 行强暴,羞愧 必遮盖你,你也必永远 断绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, '当外人 掳掠 雅各的财物,外邦人 进入 他的城门,为 耶路撒冷 拈 阄 的日子, 你 竟 站 在一旁,像与他们 同伙 夥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, '你兄弟 遭难 的日子,你不当 瞪眼看著;犹大 人 被灭 的日子,你不当 因此欢乐;他们遭难 的日子,你不当 说狂傲的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, '我民 遭灾 的日子,你不当 进 他们的城门;他们遭灾 的日子, 你 不当 瞪眼看著 他们受苦;他们遭灾 的日子,你不当 伸手抢 他们的财物; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, '你不当 站 在 岔路口 剪除 他们中间逃脱的;他们遭难 的日子,你不当 将他们剩下的人 交付仇敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, ' 耶和华 降罚的日子 临近 万 国。你怎样行,他也必照样 向你 行;你的报应 必归 到你头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, ' 你们犹大人在 我圣 山 怎样喝了苦杯,万 国 也必照样 常常地 喝;且喝 且咽,他们就归于  无 有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, '在锡安 山 必有 逃脱的人,那山也必成 圣;雅各 家 必得 原有的产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, '雅各 家 必成为 大火;约瑟 家 必为火焰;以扫 家 必如碎秸;火必将他 烧著 吞灭。 以扫 家 必无 余 馀剩的。这是 耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, '南地的人 必得 以扫 山;高原的人必得 非利士地,也得 以法莲 地 和 撒马利亚 地;便雅悯人必得 基列。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, ' 在迦南人 中被掳的 以色列 众 人 必得地直到 撒勒法; 在西法拉 中被掳的 耶路撒冷人 必得 南地 的城邑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, '必有拯救者 上 到锡安 山,审判 以扫 山;国度 就归 耶和华了。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, '耶和华 的话 临 到 亚米太 的儿子 约拿,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, '「你起来 往 尼尼微 大 城 去,向 其中的居民呼喊,因为 他们的恶 达到 我面前。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, '约拿 却起来,逃 往他施 去躲避 耶和华;下到 约帕,遇见 一只船,要往 他施去。他就给了 船价,上了 船,要与船上的人同 往 他施去 躲避 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, '然而耶和华 使 海中 起大 风,海 就狂风 大 作,甚至船 几乎 破坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, '水手 便惧怕,各人 哀求 自己的神。他们将 船上的 货物 抛 在 海中,为要 使船轻些。约拿 已下 到 底 舱,躺卧 沉睡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, '船 主 到 他那里 对他 说:「你 这沉睡的人哪,为何这样呢?起来,求告 你的神,或者 神 顾念 我们,使我们不致 灭亡。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, '船上的人彼此 说:「来吧,我们掣 签,看看 这 灾 临到我们 是因谁的缘故。」于 是他们掣 签, 掣出 约拿来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, '众人对他 说:「请 你告诉 我们,这 灾 临到我们 是因谁 的缘故?你以何事 为业?你从哪里 来?你是 哪 一国? 属哪 一族的人?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, '他说:「我是 希伯来人。我 敬畏 耶和华─那 创造 沧海 旱地 之天上的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, '他们 就大大 惧怕,对他 说:「你做 的是什么 事呢?」 他们 已经知道 他 躲避 耶和华,因为 他告诉了 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, '他们问他 说:「我们当向你 怎样 行,使海浪 平静呢?」这话是因 海浪 越发 翻腾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, '他对他们 说:「你们将我抬起来,抛 在 海中,海 就平静了; 我 知道 你们遭 这 大 风 是因我的缘故。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, '然而那些人 竭力荡桨,要把船拢 岸,却是不 能,因为 海浪 越发 向他们 翻腾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, '他们便求告 耶和华 说:「耶和华啊,我们恳求你,不要 因这 人 的性命 使我们死亡,不要 使 流无辜 血 的罪归与我们;因为 你─耶和华 是随 自己的意旨 行事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, '他们遂将 约拿 抬起,抛 在 海中,海 的狂浪 就平息了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, '那些人 便大大 敬畏 耶和华,向耶和华 献 祭,并且许 愿 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, '耶和华 安排 一条大 鱼 吞了 约拿, 他 在鱼 腹中 三 日 三 夜。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, '约拿 在鱼 腹中 祷告 耶和华─他的 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, '说:我 遭遇患难 求告 耶和华,你就应允我;从阴间 的深处 呼求,你就俯听 我的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, '你将我投 下深渊,就是海 的深处;大水 环绕我,你的波浪 洪涛 都 漫过 我身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, '我 说:我从你眼 前 虽被驱逐, 我仍要 仰望 你的圣 殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, '诸水 环绕我,几乎淹没我;深渊 围住我;海草 缠绕 我的头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, '我下到 山 根,地 的门 将我永远 关住。耶和华─我的 神啊,你却将我的性命 从坑中 救出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, '我心 在我里面 发昏的时候,我就想念 耶和华。我的祷告 进 入 你的圣 殿,达到你的面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, '那信奉 虚无之神的人,离弃 怜爱他们的主; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, '但我 必用感谢 的声音 献祭 与你。我所 许的愿 ,我必偿还。救恩 出于 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, '耶和华 吩咐 鱼,鱼就把 约拿 吐 在 旱地上。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, '耶和华 的话 二次 临 到 约拿 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, '「你起来!往 尼尼微 大 城 去,向 其中的居民宣告 我 所 吩咐 你 的话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, '约拿 便照耶和华 的话 起来,往 尼尼微 去。这尼尼微 是 极 大 的城,有三 日 的路程。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, '约拿 进 城 走了一 日,宣告 说:「再等 四十 日,尼尼微 必倾覆 复了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, '尼尼微 人 信服 神,便宣告 禁食,从最大的 到 至小的 都穿 麻衣(或译:披上麻布)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, '这信息 传 到 尼尼微 王的耳中,他就下 了宝座,脱下 朝服,披上 麻布,坐 在 灰中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, '他又使人遍告 尼尼微通城,说:「王 和大臣 有令,人 不可 尝 什么,牲畜、牛 羊 不可 吃草,也不可 喝 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, '人 与牲畜 都当披上 麻布;人要切切 求告 神。各人 回头 离开 所行的恶 道,丢弃 手 中的强暴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, '或者 神 转意 后悔,不发 烈 怒,使我们不 致灭亡,也未可 知。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, '于 是 神 察看 他们的行为, 见他们离开  恶 道,他 就后悔,不 把所 说的 灾祸 降 与他们 了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, '这事 约拿 大大 不悦,且甚发怒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, '就祷告 耶和华 说:「耶和华 啊,我 在 本国 的时候岂不是 这样 说吗? 我知道 你是 有恩典、有怜悯的 神,不轻易 发怒,有丰盛 的慈爱,并且后悔 不降所说的灾,所以 我急速 逃 往他施去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, '耶和华啊,现在 求 你取 我的命吧!因为 我死了 比活著 还好。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, '耶和华 说:「你 这样发怒 合乎理吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, '于 是约拿 出 城,坐 在城 的东边,在那里 为自己 搭了 一座棚,坐 在棚的荫 下,要 看看 那城究竟 如何。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, '耶和华 神 安排 一棵蓖麻,使其发生 高过 约拿, 影儿 遮盖 他的头,救 他 脱离苦楚;约拿 因 这棵蓖麻 大大 喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, ' 次日 黎明, 神 却安排 一条虫子 咬 这蓖麻,以致枯槁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, ' 日头 出来的时候, 神 安排 炎热的 东 风,日头 曝晒 约拿 的头,使他发昏,他就为 自己 求 死,说:「我死 了比活 著还好!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, '神 对 约拿 说:「你 因 这棵蓖麻 发怒 合乎理吗?」他说:「我 发怒 以至 于 死,都合乎理!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, '耶和华 说:「这 蓖麻 不是 你栽种的,也不是 你培养的; 一夜 发生, 一夜 干死,你 尚且爱惜; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, '何况这尼尼微 大 城,其中 不能 分辨 左手 右手的 有 十 二 万 多 人,并有许多 牲畜,我 岂能不 爱惜呢?」    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, '当犹大 王 约坦、亚哈斯、希西家 在位的时候, 摩利沙人 弥迦 得 耶和华 的默示,论 撒马利亚 和耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, '万 民哪,你们都要听!地 和其上所有的,也都要侧耳而听!主 耶和华 从他的圣 殿 要 见证 你们的不是。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, ' 看哪,耶和华 出了 他的居所,降临 步行 地 的高处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, '众山 在他以下 必消化,诸谷 必崩裂,如蜡 化在火 中,如水 冲下 山坡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, '这 都 因雅各 的罪过,以色列 家 的罪恶。雅各 的罪过 在哪里呢?岂不是 在撒马利亚吗?犹大 的邱坛 在哪里呢?岂不是 在耶路撒冷吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, '所以我必使 撒马利亚 变为田野 的乱堆,又作为种葡萄 之处;也必将她的石头 倒 在谷中,露出 根基来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, '她一切 雕刻的偶像 必被打碎; 她所得的财物 必被火 烧;所有的 偶像 我必毁灭;因为 是从妓女 雇价 所聚来的,后必归 为 妓女 的雇价。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, '先知说:因 此 我必大声 哀号,赤脚 露体 而行;又要 呼号 如野狗,哀鸣 如鸵鸟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, '因为 撒马利亚的伤痕 无法医治, 延 及 犹大 和 耶路撒冷 我民 的城门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, '不要 在迦特 报告这事,总 不要 哭泣;我在伯‧亚弗拉 滚 于 灰尘之中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, '沙斐 的居民哪,你们 要赤身 蒙羞 过去。撒南 的居民 不 敢出来。伯‧以薛人 的哀哭 使 你们无 处可站。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, '玛律 的居民 心甚 忧急,切望得好处,因为 灾祸 从 耶和华 那里临到 耶路撒冷 的城门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, '拉吉 的居民哪,要用快马 套 车;锡安民(原文是女子)的罪 由你 而起; 以色列人 的罪过 在你那里 显出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, '犹大啊,你要将礼物 送 给摩利设‧迦特。亚革悉 的众族 必用诡诈 待以色列 诸王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, '玛利沙 的居民哪,我必 使 那夺取你的 来到你这里;以色列的尊贵人(原文是荣耀)必到 亚杜兰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, '犹大啊,要为 你所喜爱 的儿女 剪除你的头发,使头光秃,要大大 地光秃,如同秃鹰,因为 他们都被掳去 离开 你。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, '祸哉,那些在 床 上图谋 罪孽、造作 奸恶的!天 一发亮,因 手 有 能力 就行出来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, '他们贪图 田地 就占据,贪图房屋 便夺取;他们欺压 人,霸占房屋 和产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, '所以 耶和华 如此 说: 我筹划 㓰 灾祸 降与 这 族;这祸 在你们的颈项 上不能 解脱;你们也不能 昂首 而行,因为 这时势 是 恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, '到那 日,必有人向你们 提起 悲惨 的哀歌,讥刺 说:我们全然 败落了!耶和华将我们 的分 转归别人,何竟 使这分离开  我们?他将我们的田地 分 给悖逆的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, '所以 在耶和华 的会中,你 必 没有 人拈阄 拉 准绳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, '他们(或译:假先知)说:你们不可 说预言;不可 向这些人 说预言,不 住地 羞辱我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, '雅各 家啊,岂可说 耶和华 的心不忍耐吗(或译:心肠狭窄吗)? 这些事 是他所行的吗?我─耶和华的言语 岂不是 与 行动 正直 的人有益吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, '然而,近来 我的民 兴起 如仇敌,从那些安然 经过 不愿  打仗 之人身上 剥去 外衣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, '你们将我民 中的妇人 从安乐 家 中赶出,又将我的荣耀 从 她们的小孩子 尽行 夺去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, '你们起来 去吧! 这 不是 你们安息之所;因为 污秽使人(或译:地)毁灭,而且大大 毁灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, '若 有人 心 存 虚假,用谎言说:我要向你们 预言 得清酒 和浓酒。那人就必作 这 民 的先知。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, '雅各家啊,我必要 聚集 你们,必要 招聚 以色列 剩下的人,安置 在一处,如波斯拉 的羊,又如草场上 的羊群;因为人数众多 就必大大喧哗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, '开 路的(或译:破城的)在他们前面 上去;他们直闯 过 城门,从城门 出去。他们的王 在前面 行;耶和华 引导他们。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, '我说:雅各 的首领,以色列 家 的官长啊,你们要 听!你们 不 当知道 公平吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, '你们恶 善 好 恶,从人身上 剥 皮,从人 骨头 上剔肉, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, ' 吃 我民 的肉,剥 他们 的皮,打折 他们的骨头,分成块子 像 要下锅,又像釜 中 的肉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, '到了遭灾的时候,这些人必哀求 耶和华,他却不 应允 他们。那 时 他必照他们所 行 的恶事 向他们 掩 面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, '论到 使 我民 走差路 的先知─他们牙齿 有所嚼的,他们就呼喊说:平安了!凡 不 供给 他们吃的,他们就预备 攻击他(预备攻击他:或译说必遭遇刀兵)─耶和华 如此 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, ' 你们 必遭遇黑夜,以致不见异象; 又必遭遇幽暗,以致不能占卜。日头 必向 你们 沉落,白昼 变为 黑暗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, '先见 必抱愧,占卜的 必蒙羞,都 必摀著 嘴唇,因为 神 不 应允他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, '至于 我,我藉 借 耶和华 的灵,满有 力量、公平、才能,可以向雅各 说明 他的过犯,向以色列 指出他的罪恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, '雅各 家 的首领、以色列 家 的官长啊, 当听 我的话!你们厌恶 公平,在 一切事上 屈枉 正直; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, '以人血 建立 锡安,以罪孽 建造耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, '首领 为贿赂 行审判;祭司 为雇价 施训诲;先知 为银钱 行占卜。他们却倚赖 耶和华,说:耶和华 不是 在我们中间吗?灾祸 必不 临到 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, '所以 因你们的缘故,锡安 必被耕种 像一块田,耶路撒冷 必变为 乱堆;这殿 的山 必像丛林 的高处。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, ' 末后 的日子,耶和华 殿 的山 必 坚立,超乎 诸山, 高举 过于 万岭;万民 都要流 归这山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, '必有许多 国的民 前往,说:来吧,我们登 耶和华 的山,奔 雅各 神 的殿。主必将他的道 教训我们;我们也要行 他的路。因为 训诲 必出 于 锡安;耶和华 的言语 必出于 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, '他必在多 国的民 中 施行审判,为远方 强盛 的国 断定是非。他们要将刀 打 成犁头,把枪 打成镰刀。这国 不 举 刀 攻击 那国;他们也不 再 学习 战 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, '人人 都要坐 在自己葡萄树 下 和无花果树 下,无人 惊吓。这是 万军 之耶和华 亲口 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, ' 万 民 各 奉己神 的名 而行;我们却 永永远远 奉耶和华─我们 神 的名 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, '耶和华 说:到那 日,我必聚集 瘸腿的,招聚 被赶出的 和我所 惩治的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, '我必使 瘸腿的 为余 馀剩之民,使赶到远方的 为强盛 之民。耶和华 要在锡安 山 作王 治理他们,从今 直到 永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, '你 这羊群 的高台、锡安城(原文是女子)的山哪, 从前 的权柄─就是耶路撒冷民(原文是女子)的国权─必归 与你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, '现在 你为何 大声 哭号呢?疼痛 抓住你 仿佛产难的妇人,是因 你中间 没有 君王吗? 你的谋士 灭亡了吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, '锡安的民(原文是女子)哪,你要疼痛 劬劳,仿佛产难的妇人;因为 你必从城里 出来,住 在田野,到巴比伦 去。在那里 要蒙解救;在那里 耶和华 必救赎 你脱离仇敌 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, '现在 有许多 国的民 聚集 攻击你,说:愿 锡安 被玷污!愿 我们亲眼 见她遭报! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, '他们 却不 知道 耶和华 的意念,也不 明白 他的筹划 㓰。 他聚集他们,好像把禾捆 聚到禾场一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, '锡安的民(原文是女子)哪,起来 踹谷吧! 我必使 你的角 成为铁,使 你的蹄 成为铜。你必打碎 多 国的民,将他们的财 献 与耶和华,将他们的货 献与普 天下 的主。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, '成群的民(原文是女子)哪,现在 你要聚集成队;因为仇敌围攻 我们,要用杖 击打 以色列 审判者 的脸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, '伯利恒 的以法他啊,你 在犹大 诸城中 为 小,将来必有一位从你那里 出来,在以色列中 为我 作 掌权的;他的根源 从亘古,从太初就有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, ' 耶和华必将以色列人交付敌人,直等 那生产的妇人 生下子来。那时掌权者(原文是他)其余 馀 的弟兄 必归 到 以色列 人那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, '他必起来,倚靠耶和华 的大能,并耶和华─他 神 之名 的威严,牧养他的羊群。他们要安然居住;因为 他必日见尊大,直到 地 极。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, '这位 必作 我们的平安。当 亚述人 进入 我们的地境, 践踏 宫殿的时候,我们就立起 七个 牧者,八个 首领 攻击他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, '他们必用刀剑 毁坏 亚述 地和 宁录 地 的关口。亚述人 进入 我们的地 境 践踏的时候,他必拯救我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, '雅各 余 馀剩的人 必 在多 国的民 中,如从 耶和华 那里降下的露水,又如甘霖 降在 草上; 不 仗赖 人力,也不 等候 世人之功。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, '雅各 余 馀剩的人 必 在多国 多 民 中,如林 间百兽中 的狮子,又如少壮狮子 在羊 群中。他 若 经过 就必践踏 撕裂,无人 搭救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, '愿 你的手 举起,高过 敌人!愿 你的仇敌 都 被剪除! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, '耶和华 说: 到那 日,我必从你中间 剪除 马匹,毁坏 车辆, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, '也必从你国 中除灭 城邑,拆毁 一切的 保障, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, '又必除掉 你手中 的邪术;你那里 也不再 有 占卜的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, '我必从你中间 除灭 雕刻的偶像 和柱像,你就不 再 跪拜 自己手 所造的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, '我必从你中间 拔出 木偶,又毁灭 你的城邑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, '我也必在怒气 和忿怒中 向 那 不 听从 的列国 施 报。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, '以色列人哪, 当听 耶和华 的话!要起来 向 山岭 争辩,使冈陵 听 你的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, '山岭 和地 永久 的根基啊,要听 耶和华 争辩的话!因为 耶和华 要与 他的百姓 争辩,与 以色列 争论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, '我的百姓啊,我向你 做了 什么呢?我在什么事 上使你厌烦?你可以对我 证明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, ' 我曾将你从埃及 地 领出来,从作奴仆 之家 救赎你;我也差遣 摩西、亚伦,和米利暗 在你前面行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, '我的百姓啊, 你们当追念 摩押 王 巴勒 所设的谋和 比珥 的儿子 巴兰 回答 他的话,并你们从 什亭 到 吉甲所遇见的事,好使 你们知道 耶和华 公义的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, '我朝见 耶和华,在 至高 神 面前跪拜,当献上什么呢?岂可献 一岁 的牛犊 为燔祭吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, '耶和华 岂喜悦 千千 的公羊,或是万万 的油 河吗?我岂可为自己的罪过 献 我的长子吗?为心 中的罪恶 献我身 所生的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, '世人哪,耶和华 已指示 你 何 为善。他向你 所要 的是什么呢?只要 你行 公义,好 怜悯,存谦卑的心,与你的 神 同行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, '耶和华 向这城 呼叫,智慧人 必敬畏 他的名。你们当听 是谁 派定 刑杖的惩罚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, '恶人 家 中不仍 有 非义 之财 和可恶的 小 升斗吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, '我若用不公道 的天平 和囊中 诡诈 的法码,岂可算为清洁呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, ' 城里的富户 满 行强暴;其中的居民 也说 谎言,口中 的舌头 是诡诈的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, '因此,我 击打你,使你的伤痕甚重,使你因 你的罪恶 荒凉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, '你 要吃,却吃不 饱;你的虚弱 必显在你中间。你必挪去,却不得 救护;所 救护的,我必交 给刀剑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, '你 必撒种,却不得 收割; 踹 橄榄,却不得 油 抹身;踹葡萄,却不得 酒 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, '因为你守 暗利 的恶规,行亚哈 家 一切 所行的,顺从 他们的计谋;因此,我必使 你 荒凉,使你的居民 令人嗤笑,你们也必担当 我民 的羞辱。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, '哀哉!我(或译:以色列) 好像夏天的果子 已被收尽,又像摘了葡萄 所剩下的,没有 一挂 可吃的;我心 羡慕 初熟的无花果。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, ' 地上 虔诚人 灭尽;世间 没有 正直人;各人 埋伏,要杀人流血,都 用网罗 猎取 弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, '他们双手 作 恶;君王 徇情面,审判官 要贿赂;位分大的 吐出 恶 意, 都彼此结联行恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, '他们最好的,不过是蒺藜;最正直的,不过是荆棘篱笆。你守望者说,降罚 的日子 已经来到。 他们必 扰乱不安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, '不要 倚赖 邻舍;不要 信靠 密友。要守 住你的口;不要向你怀中的 妻提说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, '因为,儿子 藐视 父亲;女儿 抗拒 母亲;媳妇 抗拒婆婆;人 的仇敌 就是自己家 里的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, '至于 我,我要仰望 耶和华,要等候 那救我的 神;我的 神 必应允我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, '我的仇敌啊,不要 向我 夸耀。我虽 跌倒,却要起来;我虽 坐 在黑暗里,耶和华 却作我的 光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, '我要忍受 耶和华 的恼怒;因 我得罪了 他,直等 他为我辨 屈,为我伸 冤。他必领我 到光明中;我必得见 他的公义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, '那时我的仇敌,就是曾对我 说「耶和华─你 神 在哪里」的,他一看见 这事就被羞愧 遮盖。我必亲眼 见 他遭报; 他必 被践踏,如同街上 的泥土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, '以色列啊,日子必到,你的墙垣 必重修;到那 日,你的境界必开 展(或译:命令 必传到远方)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, '当那 日,人必从 亚述,从埃及 的城邑,从 埃及 到 大河,从这海 到那海,从这山 到那山,都归 到你这里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, '然而,这地 因居民 的缘故,又因他们行事 的结果,必然 荒凉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, '求耶和华在迦密山 的树林 中,用你的杖 牧放 你独 居 的民,就是你产业 的羊群。求你容他们在巴珊 和基列 得食物,像古 时一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, '耶和华说:我要把奇 事显给他们看,好像出 埃及 地 的时候一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, '列国 看见 这事就必为 自己的势力 惭愧;他们必用手 摀 口,掩耳 不听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, '他们必舔 土 如蛇,又如土 中腹行的物,战 战 兢兢地出 他们的营寨。他们必战 惧 投降 耶和华,也必因我们的 神 而惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, '神啊,有何 神 像你,赦免 罪孽,饶恕 你产业 之余 馀民 的罪过,不 永远 怀 怒, 喜爱 施恩? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, '必再 怜悯我们,将我们的罪孽 踏在脚下,又将我们的一切 罪 投 于 深 海。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, '你必按古 时 起誓 应许我们列祖 的话,向雅各 发 诚实,向亚伯拉罕 施慈爱。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, '论尼尼微 的默示,就是伊勒歌斯人 那鸿 所得的默示。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, '耶和华 是忌邪 施报的 神。耶和华 施报 大有忿怒; 向他的敌人 施报, 向他的仇敌 怀怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, '耶和华 不轻易 发怒,大有 能力,万不 以有罪的 为无罪。他 乘旋风 和暴风 而来,云彩 为他脚下 的尘土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, '他斥责 海,使海干了,使一切 江河 干涸。巴珊 和迦密 的树林衰残;黎巴嫩 的花草 也衰残了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, '大山 因他 震动;小山 也都消化。大地 在他面前 突起;世界 和 住 在其间的也都如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, ' 他发忿恨,谁 能立得住呢?他发烈 怒,谁 能当得起呢?他的忿怒 如火 倾倒;磐石 因他 崩裂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, '耶和华 本为善,在患难 的日子 为人的保障,并且认得 那些投靠 他的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, '但他必以 涨溢 的洪水 淹没 尼尼微,又驱逐 仇敌 进入黑暗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, '尼尼微人哪,设 何 谋攻击 耶和华呢?他 必将 你们灭绝净尽;灾难 不 再 兴起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, ' 你们像 丛杂 的荆棘,像喝 醉了的人,又如枯干 的碎秸 全然 烧灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, '有一人从你那里 出来,图谋 邪恶,设 恶计 攻击 耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, '耶和华 如此 说:尼尼微虽然 势力充足, 人数繁多,也 被剪除,归于 无有。犹大啊,我虽然使你受苦,却不 再 使你受苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, '现在 我必从 你颈项上折断 他的轭,扭开  他的绳索。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, '耶和华 已经出令,指著尼尼微说:你名下的人 必不 留后;我必从你神 的庙中 除灭 雕刻的偶像 和铸造的偶像;我必因 你鄙陋,使你归于  坟墓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, '看哪,有报好信 传 平安 之人的脚 登 山,说:犹大啊,可以守 你的节期,还 你所许的愿 吧!因为 那恶人 不 再 从你中间 经过,他已灭绝净尽了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, '尼尼微啊,那打碎邦国的 上来 攻击 你。你要看守 保障,谨防 道路,使腰 强壮,大大 勉 力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, '( 耶和华 复兴 雅各 的荣华,好像以色列 的荣华一样;因为 使地空虚的,已经使雅各和以色列空虚,将他们的葡萄枝 毁坏了。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, '他勇士 的盾牌 是红的,精 兵 都穿朱红衣服。在他预备争战  的日子,战 车上 的钢铁 闪烁如火,柏木把的枪 也抡起来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, '车辆 在街上(或译:城外)急行,在宽阔处 奔来奔去,形状 如火把,飞跑 如闪电。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, '尼尼微王招聚 他的贵胄;他们步行 绊跌,速上 城墙,预备 挡牌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, '河 闸 开 放,宫殿 冲没。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, '王后蒙羞,被人掳去;宫女 搥 胸,哀鸣 如 鸽。此乃命定之事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, '尼尼微 自古以来充满人民, 如同聚水 的池子;现在居民却 都逃跑。虽有人呼喊说:站住!站住!却无人 回顾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, '你们抢掠 金 银吧!因为所积蓄 的无 穷,华美 的宝 器 无数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, '尼尼微现在空 虚 荒凉,人心 消化,双膝 相碰,腰 都 疼痛,脸 都 变 色。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, '狮子 的洞 和少壮狮子 喂 𫗭养之处 在哪里呢? 公狮 母狮 小 狮 游行、无人 惊吓 之地在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, '公狮 为小狮 撕碎 许多食物,为母狮 掐死活物,把撕碎的、掐死的 充满 牠的洞穴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, ' 万军 之耶和华 说:「我与你为敌,必将你的车辆 焚烧 成烟,刀剑 也必吞灭 你的少壮狮子。我必从地上 除灭 你所撕碎的,你使者 的声音 必不 再 听见。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, '祸哉!这流人血 的城, 充满 谎诈 和强暴─抢夺的事 总不 止息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, '鞭 声响亮,车轮 轰轰,马匹 踢跳,车辆 奔腾, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, '马兵 争先,刀剑 发光,枪矛 闪烁,被杀的 甚多,尸首 成了大堆,尸骸 无 数,人碰著 而跌倒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, '都因那美貌 的妓女 多 有淫行,惯行邪术,藉 借淫行 诱惑 列国,用邪术诱惑(原文是卖)多族。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, ' 万军 之耶和华 说:我与你为敌;我必揭起 你的衣襟,蒙在 你脸上,使列国 看见 你的赤体,使列邦 观看你的丑陋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, '我必将可憎污秽之物 抛 在你身上,辱没你,为众目所观。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, ' 凡 看见你的,都必逃跑 离开 你,说:尼尼微 荒凉了!有谁 为你 悲伤呢?我何处 寻得 安慰你的人呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, '你岂比挪 亚们 强呢?挪亚们坐落 在众河之间,周围 有水;海(指尼罗河)作她的 濠沟, 又作她的城墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, '古实 和埃及 是她无 穷 的力量;弗人 和路比族 是 她的帮手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, '但 她 被迁移,被掳 去;她的婴孩 在各 市 口上 也 被摔死。人为 她的尊贵人 拈 阄;她所有的 大人 都被链子 锁著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, '你 也 必喝醉,必 被埋藏,并 因仇敌 的缘故寻求 避难所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, '你一切 保障 必像无花果树 上 初熟的无花果,若 一摇撼 就落 在 想吃之人 的口中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, ' 你地上 的人民 如同妇女;你国 中的关口 向仇敌 敞 开 ;你的门闩 被火 焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, '你 要打 水 预备受困;要坚固 你的保障,踹 土 和 泥,修补 砖窑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, '在那里,火 必烧灭你;刀 必杀戮你,吞灭你 如同蝻子。任你加增 人数多如蝻子, 多如蝗虫吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, '你增添 商贾,多过天上 的星;蝻子 吃尽 而去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, '你的首领 多如蝗虫;你的军长 仿佛成群的 蚂蚱,天凉 的时候 齐落 在篱笆上,日头 一出 便都飞去,人不 知道 落在何 处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, '亚述 王啊,你的牧人 睡觉;你的贵胄 安歇;你的人民 散 在 山间,无人 招聚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, '你的损伤 无法 医治;你的伤痕 极其重大。凡 听 你信息 的必都因此向你 拍 掌。 你所行的恶 谁 没有 时常 遭遇呢?    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, '先知 哈巴谷 所 得 的默示。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, '他说:耶和华啊!我呼求你,你不 应允,要到 几时呢?我因强暴 哀求 你,你还不 拯救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, '你为何 使我看见 罪孽?你为何看著 奸恶而不理呢?毁灭 和强暴 在我面前,又 起了 争端 和相斗的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, '因 此 律法 放松,公理 也不 显明;恶人 围困 义人,所以 公理 显然 颠倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, '耶和华说:你们要向列国中 观 看,大大 惊奇;因为 在你们的时候,我行 一件事,虽 有人告诉你们,你们总是不 信。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, ' 我 必兴起 迦勒底人,就是那残忍 暴躁 之民,通行 遍 地,占据 那不 属自己 的住处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, '他 威武 可畏,判断 和势力都任意 发出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, '他的马 比豹 更快,比晚上 的豺狼 更猛。马兵 踊跃争先,都从远方 而来;他们飞跑 如鹰 抓 食, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, '都 为行强暴 而来,定住 脸面 向前,将掳掠的人 聚集,多如尘沙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, '他们 讥诮 君王, 笑话 首领, 嗤笑 一切 保障,筑 垒 攻取。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, '他以 自己的势力 为神, 像风 猛然扫 过,显为有罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, '耶和华─我的 神,我的圣者啊,你 不是 从亘古而有吗?我们必不 致死。耶和华啊,你派定他 为要刑罚人;磐石啊,你设立他 为要惩治人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, '你眼目 清洁,不看 邪僻,不 看 奸恶;行诡诈的,你为何 看著不理呢?恶人 吞灭 比自己 公义的,你为何静默不语呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, '你为何使 人 如海中 的鱼,又如没有 管辖 的爬物呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, '他用钩 钩住,用网 捕获,用拉网 聚集他们;因 此,他欢喜 快乐, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, '就 向网 献祭,向网 烧香,因 他由此 得肥美 的分 和富裕 的食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, '他岂可 屡次倒空 网罗,将列国 的人时常 杀戮,毫不 顾惜呢?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, '我要站 在 守望所,立 在 望楼上 观看,看 耶和华对我 说 什么话,我可用什么话向他诉冤(向他诉冤:或译回答 所疑问的)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, '他 对我 说:将这默示 明明地 写 在 版上,使 读的人容易读(或译:随跑随读)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, '因为 这默示有 一定的日期,快要 应验,并不 虚谎。虽然 迟延,还要等候;因为 必然 临到,不再 迟延。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, ' 迦勒底人自高自大,心 不 正直;惟义人 因信 得生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, ' 迦勒底人 因 酒 诡诈,狂傲,不 住在家中, 扩充 心欲,好像阴间。他 如死 不能 知足,聚集 万 国,堆积 万 民 都归自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, '这些 国的民岂不 都要 提起 诗歌 并俗语 讥刺他 说:祸哉!迦勒底人,你增添 不 属自己的财物,多多取 人的当头,要到 几时为止呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, '咬伤你的 岂不 忽然 起来,扰害你的 岂不兴起,你就作 他们的 掳物吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, '因 你 抢夺 许多 的国,杀人 流血,向国内 的城 并城中 一切 居民 施行强暴,所以各国剩下 的民 都 必抢夺你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, ' 为本家 积蓄 不义 之财、在高处 搭 窝、指望 免 灾 的有祸了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, '你图谋 剪除 多 国的民,犯了罪,使你的家 蒙羞,自害己命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, ' 墙里 的石头 必呼叫;房内 的栋梁 必应声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, '以人血 建 城、以罪孽 立 邑 的有祸了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, ' 众民 所劳碌得来的被火焚烧,列国 由劳乏 而得的归于  虚空,不都是 出于  万军 之耶和华吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, ' 认识耶和华 荣耀 的知识 要充满 遍地,好像水 充满 洋海一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, '给人 酒喝、又加上 毒物、使他喝醉、好 看见 他下体 的有祸了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, '你满受 羞辱,不得荣耀;你 也 喝吧,显出是未受割礼的!耶和华 右手 的杯 必传 到你那里; 你的荣耀 就变为大大地羞辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, ' 你向黎巴嫩 行强暴 与残害 惊吓 野兽 的事必遮盖你;因你杀人 流血,向国内 的城 并城中 一切 居民 施行强暴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, '雕刻的偶像, 人 将它刻出来,有什么 益处呢?铸造的偶像 就是虚谎 的师傅。 制造者 倚靠这 哑巴 偶像有什么益处呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, '对木偶说:醒起!对哑巴 石像 说:起来!那人有祸了!这个 还能教训人吗?看哪,是 包裹 金 银的,其中 毫 无 气息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, '惟耶和华 在他的圣 殿中;全 地 的人都当在他面前 肃敬静默。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, '先知 哈巴谷的 祷告,调用 流离歌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, '耶和华啊,我听见你的名声(或译:言语)就惧怕。耶和华啊,求你在这些年 间 复兴 你的作为,在这些年 间 显明出来;在发怒 的时候以怜悯 为念。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, '神 从提幔 而来;圣者 从巴兰 山临到。(细拉)他的荣光 遮蔽 诸天;颂赞 充满 大地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, '他的辉煌 如同日光;从他手里 射出光线 缐,在其中 藏著 他的能力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, '在他前面 有瘟疫 流行;在他脚 下有热症 发出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, '他站立,量了 大地(或译:使地震动),观看,赶散 万民。永久 的山 崩裂;长存 的岭 塌陷;他的 作为 与古时一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, '我见 古珊 的帐棚 遭 难,米甸 的幔子 战 兢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, '耶和华啊, 你乘 在 马上,坐在得胜 的车上,岂是 不喜悦 江河、向江河 发怒气、 向洋海 发愤恨吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, '你的弓 全然 显露,向众支派 所起的誓都是可信的。(细拉)你以江河 分开  大地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, '山岭 见你,无不战 惧;大水 泛滥 过去,深渊 发 声,汹涌翻腾(原文是向上 举 手)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, '因你的箭 射出 发光,你的枪 闪出 光耀,日 月 都在本宫 停住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, '你发忿恨 通行 大地,发怒气 责打列国,如同打粮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, '你出来 要拯救 你的百姓,拯救 你的受膏者,打破 恶人 家 长的头,露出他的脚(原文是根基),直到 颈项。(细拉) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, '你用敌人的戈矛 刺透 他战 士 的头;他们来如旋风,要将我们分散。他们所喜爱的是 暗中 吞吃 贫民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, '你乘马 践踏 红海,就是践踏汹涌 的大 水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, '我听见 耶和华的声音,身体 战 兢,嘴唇 发颤,骨 中 朽烂;我在所立之处 战 兢。我只可 安静等候 灾难 之日临到,犯境 之民 上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, '虽然 无花果树 不 发旺,葡萄树 不 结果,橄榄树 也不 效力,田地 不 出 粮食,圈中 绝了 羊,棚内 也没有 牛; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, '然而,我 要因耶和华 欢欣,因救我的 神 喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, '主 耶和华 是我的力量;他使 我的脚 快如母鹿的蹄,又使我稳行 在 高处。这歌交与伶长,用丝弦的乐器。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, '当犹大 王 亚们 的儿子 约西亚 在位的时候,耶和华 的话 临 到 希西家 的玄孙,亚玛利雅 的曾孙,基大利 的孙子,古示 的儿子 西番雅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, '耶和华 说:我必从 地 上 除灭 万类。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, '我必除灭 人 和牲畜,与 空中 的鸟、海里 的鱼,以及绊脚石和 恶人;我必将 人 从 地 上 剪除。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, '我必伸 手 攻击 犹大 和耶路撒冷 的一切 居民,也必从 这 地方 剪除 所 剩下的 巴力,并 基玛林 的名 和 祭司, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, '与 那些在 房顶上 敬拜 天上 万象的,并 那些敬拜 耶和华 指著他起誓,又指著玛勒堪 起誓的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, '与 那些转去 不跟从 耶和华的,和 不 寻求 耶和华 也不 访问他的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, '你要在主 耶和华 面前 静默无声,因为 耶和华 的日子 快到。 耶和华 已经预备 祭物,将他的客 分别为圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, '到了我─耶和华 献祭 的日子,必惩罚 首领 和 王 子,并 一切 穿 外邦 衣服的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, '到那 日,我必惩罚 一切 跳 过 门槛、将强暴 和诡诈 得来之物充满 主人 房屋的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, '耶和华 说: 当那 日,从鱼 门 必发出悲哀 的声音,从 二 城发出哀号的声音,从山间 发出大 破裂的响声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, '玛革提施 的居民哪,你们要哀号,因为 迦南的商 民 都 灭亡了!凡 搬运 银子 的都被剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, ' 那 时,我必用灯 巡查 耶路撒冷;我必惩罚 那些如酒在渣滓上 澄清 的;他们心里 说:耶和华 必不 降福,也不 降祸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, '他们的财宝 必成为 掠物;他们的房屋 必变为荒场。他们必建造 房屋,却不得 住在其内;栽种 葡萄园,却不得 喝 所出的酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, '耶和华 的大 日 临近,临近 而且甚 快,乃是耶和华 日子 的风声;勇士 必痛痛地 哭号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, '那 日 是忿怒 的日子,是急难 困苦 的日子,是荒废 凄凉 的日子,是黑暗 幽冥、密云 乌黑 的日子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, '是吹角 呐喊 的日子,要攻击 坚固 城 和 高大 的城楼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, '我必使灾祸临到 人身上,使他们行走 如同瞎眼的,因为 得罪了 我。他们的血 必倒出 如灰尘;他们的肉 必抛弃如粪土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, '当耶和华 发怒 的日子, 他们的金 银 不 能 救他们;他的忿怒 如火 必烧灭 全 地, 毁灭 这地 的一切 居民,而且 大大毁灭。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, '不 知羞耻 的国民哪,你们应当聚集!趁命令 没有 发出,日子 过去 如风前的糠,耶和华 的烈 怒 未 临 到你们,他 发怒 的日子 未 到 以先,你们应当聚集前来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, ' 世上 遵守 耶和华典章的 谦卑人哪,你们都当寻求 耶和华!当寻求 公义 谦卑,或者 在耶和华 发怒 的日子 可以隐藏起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, ' 迦萨 必 致见弃;亚实基伦 必然荒凉。人在正午 必赶出 亚实突的民;以革伦 也被拔出根来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, '住 沿海之地 的基利提 族 有祸了!迦南、非利士人 之地啊,耶和华 的话 与你反对,说:我必毁灭你,以致无人 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, '沿海之地 要变为 草场,其上有牧人 的住处 和羊群 的圈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, '这地 必为犹大 家 剩下的人 所得;他们必在那里 牧放群羊,晚上 必躺卧 在亚实基伦 的房屋中;因为 耶和华─他们的 神 必眷顾他们,使他们被掳的人 归回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, '我听见 摩押人 的毁谤 和亚扪 人 的辱骂,就是 毁谤 我的百姓,自夸自大,侵犯 他们的境界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, '万军 之耶和华─以色列的 神 说: 我 指著我的永生起誓: 摩押 必 像所多玛,亚扪 人 必像蛾摩拉,都变为刺草、盐坑、永远 荒废 之地。我百姓 所剩下的 必掳掠他们;我国 中所余 馀剩的 必得著他们的地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, '这事 临到他们 是因 他们骄傲, 自夸自大,毁谤 万军 之耶和华 的百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, '耶和华 必向他们 显可畏之威,因 他必叫 世上 的诸 神 瘦弱。列 国 海岛 的居民 各在自己的地方 敬拜 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, ' 古实人哪,你们 必 被我的刀 所杀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, '耶和华必伸 手 攻击 北方,毁灭 亚述, 使 尼尼微 荒凉,又干旱 如旷野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, '群畜,就是各 国(国:或译类)的走兽 必卧 在其中; 鹈鹕 和 箭猪 要宿 在柱顶上。在窗户内 有鸣叫 的声音;门槛 都必毁坏,香柏木 已经 露出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, '这 是素来欢乐 安然 居住 的城,心里 说:惟有我,除 我以外再 没有别的;现在何竟 荒凉 成为野兽 躺卧之处!凡 经过 的人都必摇 手 嗤笑她。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, '这悖逆、污秽、欺压 的城 有祸了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, '她不 听从 命令,不 领受 训诲,不 倚靠 耶和华,不 亲近她的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, '她中间 的首领 是咆哮 的狮子;她的审判官 是晚上 的豺狼,一点食物 也不 留到早晨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, '她的先知 是虚浮 诡诈 的人;她的祭司 亵渎 圣所,强解 律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, '耶和华 在她中间 是公义的,断不 做 非义的事,每 早晨 显明 他的公义,无日 不 然;只是不义的人 不 知 羞耻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, '我─耶和华已经除灭 列国的民;他们的城楼 毁坏。我使他们的街道 荒凉,以致无人 经过;他们的城邑 毁灭,以致无 人,也无 居民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, '我说:你只 要敬畏 我,领受 训诲;如此,你的住处 不 致照我所 拟定的 除灭。只是 你们从早 起来就在一切 事 上败坏自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, '耶和华 说: 你们要等候 我,直到我兴起 掳掠 的日子;因为 我已定意 招聚 列国,聚集 列邦,将我的恼怒─就是我的烈 怒 都 倾 在她们身上。我的忿怒 如火,必 烧灭 全 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, '那时,我必使 万民 用清洁 的言语好 求告我─耶和华 的名,同心合意 地事奉我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, '祈祷我的,就是我所分散 的民(原文是女子;下同),必从 古实 河外来,给我献 供物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, '当那 日,你必不 因你一切 得罪 我 的事 自觉羞愧;因为 那时 我必从你中间 除掉 矜夸 高傲之辈,你也不 再 于 我的圣 山 狂傲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, '我却要在你中间 留下 困苦 贫寒 的民;他们必投靠我─耶和华 的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, '以色列 所剩下的人 必不 作 罪孽,不 说 谎言, 口中 也没有 诡诈 的舌头;而且 吃喝 躺卧,无人 惊吓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, '锡安 的民哪,应当歌唱!以色列啊,应当欢呼!耶路撒冷 的民哪,应当满 心 欢喜 快乐! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, '耶和华 已经除去 你的刑罚,赶出 你的仇敌。以色列 的王─耶和华 在你中间;你必不 再 惧怕 灾祸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, '当那 日,必有话向耶路撒冷 说:不要 惧怕!锡安哪;不要 手 软! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, '耶和华─你的 神 是施行拯救、大有能力的主。他在你中间 必因你 欢欣 喜乐,默然 爱你,且因你 喜乐 而欢呼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, '那些 属你、为无大会 愁烦、因你 担当 羞辱的,我必聚集他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, '那 时,我 必罚办 一切 苦待你的人,又拯救 你瘸腿的,聚集 你被赶出的。那些在全 地 受羞辱的,我必使他们 得称赞,有名声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, '那 时,我必领 你们进来,聚集 你们;我使你们 被掳之人 归回 的时候,就必 使 你们 在地 上的万 民 中有名声,得称赞。这是耶和华 说的。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, '大流士 王 第二 年 六 月 初 一 日, 耶和华 的话 藉 借 先知 哈该 向 犹大 省长 撒拉铁 的儿子 所罗巴伯 和 约撒答 的儿子 大 祭司 约书亚 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, '万军 之耶和华 如此 说:「这 百姓 说,建造 耶和华 殿 的时候 尚未 来到。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, ' 那时耶和华 的话临到 先知 哈该 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, '「这 殿 仍然荒凉, 你们 自己 还住 天花板 的房屋吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, '现在 万军 之耶和华 如此 说:你们要省察 自己的行为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, '你们撒 的种多,收的 却少;你们吃,却不 得饱;喝,却不 得足;穿衣服,却不 得暖;得工钱的,将工钱 装在 破漏 的囊中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, '万军 之耶和华 如此 说:「你们要省察 自己的行为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, '你们要上 山 取 木料,建造 这殿,我就因此 喜乐,且得荣耀。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, '你们盼望 多得, 所得的却少;你们收 到家中,我就吹去。这是为 什么呢?因为 我的殿 荒凉,你们 各人却顾(原文是奔)自己的房屋。这是万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, '所以 为你们的缘故,天 就不降 甘露,地 也不出 土产。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, '我命 干旱 临到 地土、 山冈、 五谷、 新酒,和 油,并 地 上的 出产、 人民、 牲畜,以及 人手 一切 劳碌得来的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, '那时,撒拉铁 的儿子 所罗巴伯 和约撒答 的儿子 大 祭司 约书亚,并 剩下的 百姓,都听从 耶和华─他们 神 的话 和 先知 哈该 奉耶和华─他们 神 差 来所 说的话;百姓 也在耶和华 面前 存敬畏的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, '耶和华 的使者 哈该 奉耶和华 差遣 对百姓 说:「耶和华 说:我 与你们同在。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, '耶和华 激动 犹大 省长 撒拉铁 的儿子 所罗巴伯 和 约撒答 的儿子 大 祭司 约书亚,并 剩下之 百姓 的心,他们就来 为万军 之耶和华─他们 神 的殿 做 工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, '这是在大流士 王 第二 年 六 月 二十 四 日。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, '七 月 二十 一日, 耶和华 的话临到 先知 哈该 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, '「你要 晓谕 犹大 省长 撒拉铁 的儿子 所罗巴伯 和 约撒答 的儿子 大 祭司 约书亚,并 剩下的 百姓,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, '你们中间 存留的,有 谁 见过 这 殿 从前 的荣耀呢?现在 你们 看著 如何?岂不 在眼中 看如 无有吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, '耶和华 说:「所罗巴伯啊,虽然如此,你当刚强!约撒答 的儿子 大 祭司 约书亚啊,你也当刚强!这地 的百姓,你们都 当刚强 做工,因为 我 与你们同在。这是万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, '这是 照著 你们出 埃及 我与你们 立约 的话。那时,我的灵 住 在你们中间,你们不要 惧怕。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, ' 万军 之耶和华 如此 说:「 过不多时,我 必再 一次 震动 天 地、 沧海,与 旱地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, '我必震动 万 国;万 国的珍宝必都运来(或译:万国所羡慕的 必来到),我就使 这 殿 满了 荣耀。这是万军 之耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, '万军 之耶和华 说:「银子 是我的,金子 也是我的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, '这 殿 后来 的荣耀 必 大 过 先前 的荣耀;在 这 地方 我必赐 平安。这是万军 之耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, '大流士 王第二 年 九 月 二十 四日,耶和华 的话 临 到 先知 哈该 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, '万军 之耶和华 如此 说:「你要 向 祭司 问 律法, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, '说:若 有人 用衣 襟 兜 圣 肉,这衣襟 挨 著 饼,或 汤,或 酒,或 油,或 别的 食物,便算为圣吗?」祭司 说:「不算为圣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, '哈该 又说:「若 有人因摸 死尸 染了污秽,然后挨著这些物 的哪一样,这物算污秽吗?」祭司 说:「必算污秽。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, '于 是哈该 说:「耶和华 说: 这 民 这 国,在我面前 也是如此;他们手下 的各样 工作 都是如此;他们在坛上 所 献 的也是 如此。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, '现在 你们要 追想, 此 日 以前,耶和华 的殿 没有 一块石头 垒 在 石头上的光景。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, '在那一切日子,有人 来 到 谷堆,想得二十斗,只得了 十斗。有人来 到 酒池,想得 五十 桶,只得了 二十桶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, ' 在你们手 下的各样 工作上,我以旱风、霉烂、冰雹 攻击 你们,你们 仍不 归向我。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, '你们要 追想 此 日 以前,就是从 这九 月二十 四日起,追想 到 立耶和华 殿 根基 的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, '仓里 有 谷种吗? 葡萄树、无花果树、石榴树、橄榄 树 都没有 结果子。从 今 日起,我必赐福与你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, '这月 二十 四日,耶和华 的话 二次 临 到 哈该 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, '「你要告诉 犹大 省长 所罗巴伯 说:我 必震动 天 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, '我必倾覆 复 列国 的宝座,除灭 列邦 的势力,并倾覆 复 战 车 和坐在其上的。马必跌倒,骑马的 败落,各人 被弟兄 的刀所杀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, '万军 之耶和华 说: 我仆人 撒拉铁 的儿子 所罗巴伯啊,到那 日,我必以你 为印,因 我拣选了 你。这是万军 之耶和华 说的。」    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, '大利乌 王第二 年 八 月,耶和华 的话 临 到 易多 的孙子、比利家 的儿子 先知 撒迦利亚,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, '「耶和华 曾向 你们列祖 大大 发怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, '所以你要对 以色列人说,万军 之耶和华 如此 说:你们要转 向我,我就转 向你们。这是万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, '不要 效法 你们列祖。从前 的先知 呼叫 他们 说,万军 之耶和华 如此 说:『你们要 回头 离开 你们的恶 道 恶 行。』他们却不 听,也不 顺从 我。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, '你们的列祖 在哪里呢?那些先知 能永远 存活吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, '只是 我的言语 和律例,就是所 吩咐 我仆人 众先知的,岂不 临到 你们列祖吗?他们就回头,说:『万军 之耶和华 定意 按我们的行动 作为 向我们 怎样 行,他已照样 行了。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, '大利乌 第二 年 十一 月,就是 细罢特 月 二十 四 日,耶和华 的话 临 到 易多 的孙子、比利家 的儿子 先知 撒迦利亚,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, '「我夜间 观看,见 一人 骑著 红 马, 站 在洼地 番石榴树 中间。在他身后 又有红 马、黄马,和白马。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, '我对与我 说话 的天使 说:「主啊,这 是什么意思?」他说:「我 要指示你 这 是 什么意思。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, '那站 在番石榴树 中间 的人 说:「这 是奉耶和华 差遣 在遍地 走来走去 的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, '那些骑马的对 站 在番石榴树 中间 耶和华 的使者 说:「我们已在遍地 走来走去,见 全 地 都安息 平静。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, '于 是,耶和华 的使者 说:「万军 之耶和华啊,你 恼恨 耶路撒冷 和 犹大 的城邑已经 七十 年, 你不 施怜悯 要到 几时呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, '耶和华 就用美善 的安慰 话 回答 那 与我 说话 的天使。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, '与我 说话 的天使 对我 说:「你要宣告 说,万军 之耶和华 如此 说:我为耶路撒冷 为锡安,心里极其 火热。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, '我 甚 恼怒 那安逸 的列国,因 我 从前稍微 恼怒我民,他们 就加 害过分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, '所以 耶和华 如此 说:现今我回 到耶路撒冷,仍施怜悯,我的殿 必重建 在其中,准绳 必拉 在 耶路撒冷之上。这是万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, '你要再 宣告 说,万军 之耶和华 如此 说:我的城邑 必再 丰盛 发达。耶和华 必再 安慰 锡安, 拣选 耶路撒冷。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, '我举 目 观看,见 有四 角。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, '我就问 与我 说话 的天使 说:「这 是什么意思?」他回答说:「这 是打散 犹大、 以色列,和耶路撒冷 的 角。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, '耶和华 又指 四 个匠人给我看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, '我说:「他们 来 做 什么呢?」他说:「这 是打散 犹大 的角, 使人 不 敢抬 头;但这些 匠人来 威吓 列国,打掉 他们的角,就是举起 打散 犹大 地 的角。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, '我又举 目 观看,见 一人 手 拿准 绳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, '我说:「你 往哪里 去?」他对我 说:「要去量 耶路撒冷,看 有多 宽 多 长。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, ' 与我 说话 的天使 去的时候,又有一位 天使 迎著他 来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, '对他 说:「你跑 去告诉 那 少年人 说,耶路撒冷 必有人居住,好像无城墙的乡村,因为人民 和牲畜 甚多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, '耶和华 说:我 要作 耶路撒冷 四围 的火 城,并要作 其中 的荣耀。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, '耶和华 说:「 我从前分散 你们 在天的四方(原文是犹如天的四 风),现在 你们要从北方 之地 逃回。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, '与巴比伦 人 同住 的锡安 民哪,应当逃脱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, ' 万军 之耶和华 说,在显出荣耀 之后,差遣我 去 惩罚那掳掠 你们 的列国, 摸 你们 的就是摸 他眼 中的瞳人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, ' 看哪,我(或译:他)要向他们 抡 手,他们就必作 服事他们 之人的掳物,你们便知道 万军 之耶和华 差遣我了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, '锡安 城啊,应当欢乐 歌唱,因为 我来 要住 在你中间。这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, '那 时,必有许多 国 归 附 耶和华,作他(原文是我)的 子民。他(原文是我)要住 在你中间,你就知道 万军 之耶和华 差遣我 到你那里去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, '耶和华 必收回 犹大 作 他圣 地 的分,也必再 拣选 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, '凡 有血气的 都当在耶和华 面前 静默无声;因为 他兴起,从圣 所出来了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, '天使(原文是他)又指给我看: 大 祭司 约书亚 站在 耶和华 的使者 面前;撒但 也站 在 约书亚的右边,与他作对。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, '耶和华 向 撒但 说:「撒但哪,耶和华 责备 你!就是拣选 耶路撒冷 的耶和华 责备 你!这 不是 从火 中抽出来 的一根柴吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, '约书亚 穿著 污秽 的衣服 站 在使者 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, '使者 吩咐 站在 面前 的说:「你们要脱去 他 污秽 的衣服」;又对 约书亚说:「 我使你 脱离 罪孽,要给你 穿上 华美的衣服。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, '我说:「要将洁净 的冠冕 戴 在 他头上。」他们就把洁净 的冠冕 戴 在 他头上,给他穿上 华美的衣服,耶和华 的使者 在旁边站立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, '耶和华 的使者 告诫 约书亚 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, '「万军 之耶和华 如此 说:你若 遵行 我的道, 谨守 我的命令,你 就可以 管理 我的家, 看守 我的院宇;我也要使 你 在这些 站立的人 中间 来往。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, '大 祭司 约书亚啊,你 和坐 在你面前 的同伴 都当 听。(他们 是作预兆 的。) 我 必使 我仆人 大卫的苗裔 发出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, ' 看哪,我在约书亚 面前 所 立 的石头,在 一 块石头 上有七 眼。万军 之耶和华 说:我 要亲自雕刻 这石头,并要在一 日 之间除掉 这 地 的罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, '当那 日,你们各人 要请 邻舍 坐在 葡萄树 和 无花果树 下。这是万军 之耶和华 说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, '那与我 说话 的天使 又来 叫醒我,好像人 睡觉 被唤醒一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, '他问我 说:「你看见 了什么?」我说:「我看见了 一个纯 金 的灯台, 顶 上有灯盏,灯台上 有七 盏灯,每 盏 有七 个管子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, '旁边 有两 棵橄榄树,一 棵在灯盏 的右边,一 棵在 灯盏的左边。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, '我 问 与我 说话 的天使 说:「主啊,这 是什么意思?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, '与我 说话 的天使 回答 我 说:「你不 知道 这 是 什么意思么?」我说:「主啊,我不知道。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, '他对我 说:「这 是耶和华 指示 所罗巴伯的。万军 之耶和华 说:不是 倚靠势力,不是 倚靠才能,乃是 倚靠我的灵方能成事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, '大 山哪,你 算什么呢?在所罗巴伯 面前,你必成为平地。他必搬出 一块石头,安在殿顶上。人且大声欢呼说:『愿 恩惠 恩惠 归与这殿(殿:或译石)!』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, '耶和华 的话 又临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, '「所罗巴伯 的手 立了这 殿 的根基,他的手 也必完成这工,你就知道 万军 之耶和华 差遣我 到你们这里来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, ' 谁 藐视 这日 的事为小呢?这 七 眼 乃是 耶和华的眼睛,遍察 全 地,见 所罗巴伯 手拿 线 缐铊 就欢喜。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, '我又问 天使 说:「这 灯台 左 右 的两 棵橄榄树 是什么意思?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, '我二次 问 他 说:「这 两 根橄榄 枝 在两 个流出 金色 油的金 嘴 旁边 是什么意思?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, '他 对我 说:「你不 知道 这 是什么意思么?」我说:「主啊,我不知道。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, '他说:「这 是两 个受膏 者 站 在 普 天下 主的旁边。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, '我又 举 目 观看,见 有一飞行 书卷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, '他问我 说:「你 看见 什么?」我回答说:「我 看见 一飞行 的书卷,长 二十 肘,宽 十 肘。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, '他对我 说:「这 是发出 行在 遍 地 上 的咒诅。 凡 偷窃的 必按 卷上这 面的话除灭;凡 起假誓的 必按 卷上那 面的话除灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, '万军 之耶和华 说:我必使这书卷出去,进 入 偷窃人 的家 和 指我名 起假 誓 人的家,必常 在他家 里,连房屋带 木 石 都毁灭了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, '与我 说话 的天使 出来,对我 说:「你要 举 目 观看,见所 出来 的是什么?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, '我说:「这是 什么呢?」他说:「这 出来的 是量器。」他又说:「这 是恶人在遍 地 的形状。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, '(我见 有一片圆 铅 被举起来。)这 坐 在量器 中 的是个 妇人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, '天使说:「这 是罪恶。」他就把妇人 扔 在 量器 中,将 那片圆铅 扔 在 量器的口上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, '我又举 目 观看,见 有两 个妇人 出来,在她们翅膀 中有风,飞得甚快, 翅膀 如同鹳鸟 的翅膀。她们将 量器 抬起来,悬在天 地 中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, '我问 与我 说话 的天使 说:「她们 要将 量器 抬到 哪里去呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, '他对我 说:「要往示拿 地去,为它 盖造 房屋;等房屋齐备,就把它安置 在 自己的地方。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, '我又 举 目 观看,见 有四 辆车 从两 山 中间 出来;那山 是铜 山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, '第一 辆车 套著红 马,第二 辆车 套著黑 马。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, '第三 辆车 套著白 马,第四 辆车 套著有斑点 的壮 马。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, '我就问 与我 说话 的天使 说:「主啊,这 是什么意思?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, '天使 回答 我 说:「这 是天 的四 风,是从普 天下的 主 面前 出来的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, '套著 黑 马 的车 往 北方 去,白 马 跟随 在 后;有斑点 的马往 南方 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, '壮马 出来,要 在遍地 走来 走去。天使说:「你们只管 在遍地 走来走去。」牠们就照样行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, '他又 呼叫 我 说:「看哪,往 北方 去 的已在北 方 安慰 我的心。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, '耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, '「你要从 被掳之人 中取 黑玳、 多比雅、 耶大雅的金银。这 三人是从巴比伦 来 到 西番雅 的儿子 约西亚 的家里。当 日 你 要进他的家, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, '取 这金 银 做 冠冕,戴 在约撒答 的儿子 大 祭司 约书亚 的头上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, ' 对他 说, 万军 之耶和华 如此 说:看哪,那名称 为大卫苗裔 的,他要在本处 长起来,并要建造 耶和华 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, '他 要建造 耶和华 的殿,并 担负 尊荣,坐 在 位 上掌王权;又必在 位 上作 祭司,使 两 职之间 筹定 和平。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, '这冠冕 要归 希连(就是黑玳)、多比雅、耶大雅,和西番雅 的儿子贤(就是约西亚),放在耶和华 的殿 里为记念。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, '远方 的人也要来 建造 耶和华 的殿,你们就知道 万军 之耶和华 差遣我 到你们这里来。你们若 留意 听从 耶和华─你们 神 的话,这事必然成就。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, ' 大利乌 王 第四 年 九 月,就是基斯流 月初四日,耶和华 的话 临 到 撒迦利亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, '那时伯特利人 已经打发 沙利色 和利坚米勒,并跟从他们的人,去恳求 耶和华的恩, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, '并问 万军 之耶和华 殿中的 祭司 和 先知 说:「我历年以来,在五 月 间哭泣 斋戒,现在 还当这 样 行吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, '万军 之耶和华 的话 就临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, '「你要宣告 国 内的众 民 和 祭司,说:『你们这 七十 年,在五月、七 月禁食 悲哀,岂是 丝毫向我 禁食吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, '你们 吃 喝,不是 为自己 吃,为自己 喝吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, '当耶路撒冷 和四围 的城邑 有 居民,正兴盛,南地 高原 有人居住的时候,耶和华 藉 借 从前 的先知 所 宣告 的话,你们不当听吗?』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, '耶和华 的话 又临 到 撒迦利亚 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, '「万军 之耶和华 曾对你们的列祖如此 说:『要按至 理 判断,各人 以慈爱 怜悯 弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, '不可 欺压 寡妇、孤儿、寄居的,和贫穷人。谁 都不可 心里 谋 害 弟兄。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, '他们却不肯 听从,扭 转 肩头,塞 耳 不听, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, '使 心 硬如金钢石,不听 律法 和 万军 之耶和华 用 灵 藉 借 从前 的先知 所 说的话。故此, 万军 之耶和华 大发 烈 怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, '万军 之耶和华 说:「 我曾呼唤他们,他们不 听; 将来他们呼求我,我也不 听! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, '我必以旋风 吹散他们到素 不 认识 的万 国中。这样,他们的地 就 荒凉,甚至无人来往 经过,因为他们使 美好 之地 荒凉了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, '万军 之耶和华 的话 临 到我说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, '「万军 之耶和华 如此 说:我为锡安 心里极 其火热,我为她 火热,向她的仇敌发烈 怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, '耶和华 如此 说:我现在回 到 锡安,要住 在耶路撒冷 中。耶路撒冷 必称为 诚实 的城,万军 之耶和华 的山 必称为圣 山。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, '万军 之耶和华 如此 说:将来必有 年老的男 女 坐 在耶路撒冷 街上,因为 年纪 老迈 就手拿 拐杖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, '城 中街 上必满有 男孩 女孩 玩耍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, '万军 之耶和华 如此 说:到那 日, 这事在余 馀剩的 民 眼 中看为希奇,在我眼 中也 看为希奇吗?这是万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, '万军 之耶和华 如此 说: 我要从东 方 从西 方 救回 我的民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, '我要领 他们来,使他们住 在耶路撒冷 中。他们要作 我的 子民,我 要作 他们的 神,都凭诚实 和公义。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, '万军 之耶和华 如此 说:「当建造 万军 之耶和华 的殿, 立根基之 日 的先知所说的 话, 现在 你们听见,应当手 里强壮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, ' 那 日 以先,人 得不著 雇价,牲畜也是如此;且因 敌人的缘故,出 入 之人不 得平安,乃因我使 众 人 互相攻击。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, '但如今,我 待这 余 馀剩的 民 必不 像从前。这是万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, '因为 他们必平安 撒种,葡萄树 必结 果子,地土 必有 出产,天 也必降 甘露。我要使 这 余 馀剩的 民 享受 这 一切的福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, '犹大 家 和以色列 家啊, 你们从前在列国 中怎样 成为 可咒诅的;照样,我要拯救 你们,使人称你们为有福的(或译:使你们叫人得福)。你们不要 惧怕,手 要强壮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, ' 万军 之耶和华 如此 说:「你们列祖 惹我 发怒的时候,我怎样 定意 降祸, 并不 后悔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, '现在 我照样 定意 施恩 与 耶路撒冷 和 犹大 家,你们不要 惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, '你们所 当行 的 是这样:各人 与 邻舍 说话 诚实,在城门口 按至 理 判断,使人和睦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, '谁 都不可 心 里谋 害 邻舍,也不可 喜爱 起假 誓,因为 这些事 都 为 我所 恨恶。这是耶和华 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, '万军 之耶和华 的话 临 到我 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, '「万军 之耶和华 如此 说:四 月、五 月禁食的日子,七 月、十 月禁食的日子,必变为 犹大 家 欢喜 快乐 的日子和欢乐 的节期;所以你们要喜爱 诚实 与和平。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, '万军 之耶和华 如此 说:「将来 必有 列国的人 和多 城 的居民 来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, '这 城的居民 必到 那城,说:『我们要快 去 恳求 耶和华的恩,寻求 万军 之耶和华;我 也 要去。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, '必有列邦的人 和强 国 的民来到 耶路撒冷 寻求 万军 之耶和华,恳求 耶和华的恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, '万军 之耶和华 如此 说:在那些 日子,必有十 个人 从列 国诸族(原文是方言)中出来, 拉住 一个犹大人 的衣襟,说:『我们要与你们 同去,因为 我们听见 神 与你们同在了。』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, '耶和华 的默示 应验 在哈得拉 地 大马士革─ 世人 和以色列 各 支派 的眼目 都仰望耶和华─ ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, '和 靠近 的哈马,并泰尔、西顿;因为 这二城的人大 有智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, '泰尔 为自己 修筑 保障,积蓄 银子 如尘沙,堆起精金 如街 上的泥土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, ' 主 必赶出她,打败她 海 上的权利;她 必被火 烧灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, '亚实基伦 看见 必惧怕;迦萨 看见甚 痛苦;以革伦 因 失了盼望 蒙羞。迦萨 必不再有 君王;亚实基伦 也不 再有居民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, '私生子(或译:外族人)必住 在亚实突;我必除灭 非利士人 的骄傲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, '我必除去 他口 中带血 之肉和牙齿 内 可憎之物。他 必 作为余 馀剩的人归与我们的 神,必 在犹大 像族长;以革伦人 必如耶布斯人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, '我必在我家 的四围安营,使敌军 不得任意往 来,暴虐的人 也不 再 经过,因为 我亲眼 看顾我的家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, '锡安 的民哪,应当大大 喜乐;耶路撒冷 的民哪,应当欢呼。看哪,你的王 来 到你这里!他 是公义的,并且施行拯救,谦谦和和 地骑 著 驴,就是骑著 驴 的驹子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, '我必除灭 以法莲 的战 车 和耶路撒冷 的战 马;争战  的弓 也必除灭。他必向列国 讲 和平;他的权柄 必从这海 管到 那海,从大河 管到 地 极。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, ' 锡安哪,我因与你立约 的血,将你中间被掳而囚的人 从无 水 的坑 中释放出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, '你们被囚而有指望 的人 都要转回 保障。 我今日 说明,我必加倍 赐 福给你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, ' 我拿 犹大作上弦的弓;我拿 以法莲 为张弓的箭。锡安哪,我要激发 你的众子,攻击 希腊(原文是雅完)的众子,使 你如勇士 的刀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, '耶和华 必显现 在他们以上;他的箭 必射出 像闪电。主 耶和华 必吹 角,乘南方 的旋风 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, '万军 之耶和华 必保护 他们;他们必吞灭仇敌,践踏 弹 石。他们必喝 血呐喊,犹如 饮酒;他们必像盛满 血的碗,又像坛 的四角满了血。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, '当那 日,耶和华─他们的 神 必看他的民 如群羊,拯救他们;因为 他们必像冠冕 上的宝石,高举 在 他的地以上(或译:在他的地上发光辉)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, ' 他的恩慈 何等大!他的荣美 何其盛!五谷 健壮 少男;新酒 培养处女。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, '当春雨 的时候,你们要向发 闪电 的耶和华 求 雨。他 必为众人 降下 甘霖, 使田园 生长菜蔬。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, '因为,家神 所言 的是虚空;卜士 所见 的是虚假;做梦者所说 的是假 梦。他们白白地 安慰人,所以 众人如 羊 流离,因 无 牧人 就受苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, '我的怒气 向 牧人 发作;我必惩罚 公山羊;因我─万军 之耶和华 眷顾 自己的羊群,就是 犹大 家,必使 他们 如骏 马 在阵上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, '房角石、钉子、争战  的弓,和一切 掌权 的都 从他 而出。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, '他们必 如勇士 在阵 上将仇敌践踏 在街 上的泥土中。他们必争战 ,因为 耶和华 与他们同在;骑 马 的也必羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, '我要坚固 犹大 家,拯救 约瑟 家,要领他们归回。 我要怜恤他们;他们必 像 未曾 弃绝的一样,都因 我 是耶和华─他们的 神,我必应允他们的祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, '以法莲人 必 如勇士;他们心 中畅快 如同 喝酒;他们的儿女 必看见 而快活;他们的心 必因耶和华 喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, '我要发嘶声,聚集他们,因 我已经救赎他们。他们的人数必加增,如 从前加增一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, '我虽然(或译:必)播散他们 在列国中,他们必在远方 记念我。他们与 儿女 都必存活,且得归回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, '我必再领他们 出埃及 地,招聚他们 出亚述,领他们 到 基列 和黎巴嫩;这地 尚且不 够 他们居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, '耶和华必经过 苦 海,击打 海 浪,使尼罗河 的深处 都 枯干。亚述 的骄傲 必致卑微;埃及 的权柄 必然灭没。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, '我必使他们倚靠我,得以坚固;一举一动 必奉我的名。这是耶和华 说的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, '黎巴嫩哪,开 开  你的门,任火 烧灭 你的香柏树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, '松树啊,应当哀号;因为 香柏树 倾倒,佳美的树 毁坏。巴珊 的橡树啊,应当哀号,因为 茂盛 的树林 已经倒了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, '听啊,有牧人 哀号 的声音,因 他们荣华 的草场毁坏了。有少壮狮子 咆哮 的声音,因 约旦河 旁的丛林 荒废了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, '耶和华─我的 神 如此 说:「你─撒迦利亚要牧养 这将宰的 群羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, ' 买 他们的 宰了他们,以自己为无 罪;卖他们的 说:『耶和华 是应当称颂的,因我成为富足。』牧养他们的 并不 怜恤 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, '耶和华 说:『 我不 再 怜恤 这地 的居民, 必将 这民 交给 各人 的邻舍 和他们王 的手中。他们必毁灭 这地,我也不 救这民脱离 他们的手。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, '于 是,我牧养 这将宰的 群羊,就是 群中最困苦的 羊。我拿著 两 根杖,一 根我称为「荣美」,一 根我称为「联索」。这样,我牧养了 群羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, '一 月之内,我除灭 三 个牧人,因为我的心 厌烦 他们;他们的心 也 憎嫌 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, '我就说:「我不 牧养 你们。要死的,由他死;要丧亡的,由他丧亡;余 馀剩的,由他们彼此 相食。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, '我 折断那称为「荣美」的 杖,表明我废弃 与 万 民 所 立 的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, '当 日 就废弃了。这样,那些仰望 我 的困苦 羊 就知道 所说的是 耶和华 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, '我对他们 说:「你们若 以为 美,就给 我工价。不然,就罢了!」于 是他们给 了三十 块钱 作为 我的工价。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, '耶和华 吩咐我 说:「要把众人 所 估定 美好 的价值 丢 给 窑户。」我便将 这三十 块钱,在耶和华 的殿 中丢 给 窑户了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, '我又 折断 称为联索的 那根杖,表明我废弃 犹大 与 以色列 弟兄的情谊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, '耶和华 又吩咐我 说:「你 再 取 愚昧 牧人 所用的器具, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, '因 我 要在这地 兴起 一个牧人。他不 看顾 丧亡的,不 寻找 分散的,不 医治 受伤的,也不 牧养 强壮的;却要吃 肥 羊的肉,撕裂 他的蹄子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, '无用 的牧人 丢弃 羊群 有祸了!刀 必临到 他的膀臂 和 右 眼上。他的膀臂 必全然 枯干;他的右 眼 也必昏暗 失明。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, '耶和华 论 以色列 的默示。铺张 诸天、建立 地 基、造 人 里面 之灵 的耶和华 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, '「 我 必使 耶路撒冷 被围困的时候,向四围 列 国的民 成为 令人昏醉 的杯;这默示也 论到 犹大(或译:犹大也是如此)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, ' 那 日,我必使 耶路撒冷 向聚集 攻击他 的万 民 当作一块重 石头;凡 举起的 必受 重伤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, '耶和华 说:到那 日,我必使 一切 马匹 惊惶,使骑马的 颠狂。我必看顾 犹大 家,使 列国 的一切 马匹 瞎眼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, '犹大 的族长 必心 里说:『耶路撒冷 的居民 倚靠万军 之耶和华─他们的 神,就作我们的 能力。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, '「那 日,我必使 犹大 的族长 如火 盆 在木柴中,又如火 把 在禾捆里;他们必 左 右 烧灭 四围 列 国的民。耶路撒冷人 必仍 住 本处,就是耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, '耶和华 必先 拯救 犹大 的帐棚,免得 大卫 家 的荣耀 和耶路撒冷 居民 的荣耀 胜过 犹大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, '那 日,耶和华 必保护 耶路撒冷 的居民。 他们中间 软弱的 必 如大卫;大卫 的家必如 神,如行在他们前面 之耶和华 的使者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, ' 那 日,我必定意 灭绝 来 攻击 耶路撒冷 各 国的民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, '我必将那施恩 叫人恳求 的灵,浇灌 大卫 家 和 耶路撒冷 的居民。他们必仰望 我(或译:他;本节同), 就是 他们所扎的;必为我 悲哀,如丧 独生子,又为我愁苦,如丧 长子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, '那 日,耶路撒冷 必有大大 的悲哀,如米吉多 平原 之哈达临门 的悲哀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, '境内 一家 一家地 都必悲哀。大卫 家,男的 独在一处,女的 独在一处。拿单 家,男的 独在一处,女的 独在一处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, '利未 家,男的 独在一处,女的 独在一处。示每家,男的 独在一处,女的 独在一处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, '其余 馀 的各 家,男的 独在一处,女的 独在一处。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, '那 日,必 给大卫 家 和耶路撒冷 的居民 开  一个泉源,洗除罪恶 与污秽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, '万军 之耶和华 说:「 那 日,我必从 地上 除灭 偶像 的名,不 再 被人记念;也 必使这地 不再有 假先知 与 污秽 的灵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, ' 若 再 有人 说预言,生 他的父 母 必对他 说:『你不得 存活,因为 你托 讬耶和华 的名 说 假预言。』生 他的父 母 在他说预言的时候,要将他刺透。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, ' 那 日,凡作先知 说预言 的必因他 所论的异象 羞愧,不再 穿 毛 衣 哄骗人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, '他必说:『我不是 先知,我 是耕 地 的;我 从幼年 作人 的奴仆。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, '必有人问他 说:『你两臂 中间是 什么 伤呢?』他必回答说:『这是 我在亲友 家 中所受的伤。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, '万军 之耶和华 说:刀剑哪,应当兴起,攻击 我的牧人 和 我的同伴。击打 牧人,羊 就分散;我必反 手 加在 微小者的身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, ' 耶和华 说:这全 地的人,三分之二 必剪除 而死,三分之一 仍必存留。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, '我要使 这三分之一 经火,熬炼他们,如熬炼 银子;试炼他们,如试炼 金子。他们 必求告 我的名,我必应允 他们。我要说:这是 我的子民。他们 也要说:耶和华是我们的 神。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, ' 耶和华的 日子 临近,你的财物必被抢掠,在你中间 分散。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, '因为我必聚集 万 国 与 耶路撒冷 争战 ,城 必被攻取,房屋 被抢夺,妇女 被玷污,城 中的民一半 被掳 去;剩下的 民 仍在 城中,不致 剪除。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, '那时,耶和华 必出去 与那些 国 争战 ,好像从前 争战  一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, '那 日,他的脚 必站 在 耶路撒冷 前面 朝东 的橄榄 山上。这 山 必从中间 分裂,自东 至西 成为极 大 的谷。山 的一半 向北 挪移,一半 向南挪移。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, '你们要从我山 的谷 中逃跑,因为 山 谷 必延 到 亚萨。你们逃跑,必如 犹大 王 乌西雅 年间 的人逃避 大地震一样。耶和华─我的 神 必降临,有一切 圣者 同来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, ' 那 日,必没 有 光,三光必退缩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, '那 日,必 是 耶和华 所知道的,不是 白昼,也不是 黑夜,到了 晚上 才有 光明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, ' 那 日,必有活 水 从耶路撒冷 出来,一半 往 东 海流,一半 往 西 海流;冬 夏 都是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, '耶和华 必作 全 地 的王。那 日 耶和华 必为 独一无二的,他的名 也是独一无二的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, '全 地,从迦巴 直到耶路撒冷 南方 的临门,要变为 亚拉巴。耶路撒冷必仍居 高位,就是从便雅悯 门 到 第一 门 之处,又到 角 门,并从哈楠业 楼,直到 王 的酒醡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, '人必住在 其中,不 再 有 咒诅。耶路撒冷人 必安然 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, '耶和华 用灾殃 攻击 那 与 耶路撒冷 争战  的 列 国人,必是 这样: 他们 两脚 站立的时候,肉 必消没,眼 在眶 中干瘪,舌 在口 中溃烂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, ' 那 日,耶和华 必使 他们 大大 扰乱。他们各人 彼此 揪住,举 手 攻击。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, '犹大 也 必在耶路撒冷 争战 。那时四围 各 国 的财物,就是许 多 金 银 衣服,必被收聚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, '那 临到 马匹、骡子、骆驼、驴,和 营中 一切 牲畜 的灾殃 是 与那 灾殃 一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, ' 所有 来 攻击 耶路撒冷 列 国 中剩下的人,必 年 年 上来 敬拜 大君王─万军 之耶和华,并守 住棚 节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, ' 地上 万 族中,凡 不 上 耶路撒冷 敬拜 大君王─万军 之耶和华的,必无 雨 降 在他们的地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, '埃及 族 若 不 上来,雨也不 降 在他们的地上;凡 不 上来 守 住棚 节 的列国人,耶和华 也必用 这 灾 攻击 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, '这 就是 埃及 的刑罚 和那 不 上来 守 住棚 节 之列 国 的刑罚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, '当那 日, 马 的铃铛 上必有 归耶和华 为圣的这句话。耶和华 殿 内的锅 必如祭坛 前 的碗一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, '凡 耶路撒冷 和犹大 的锅 都 必 归万军 之耶和华 为圣。凡 献祭的 都必来 取 这锅,煮 肉在其中。当那 日,在万军 之耶和华 的殿 中必不 再 有 迦南人。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, '耶和华 藉 借 玛拉基 传给 以色列 的默示。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, '耶和华 说:「我曾爱 你们。」你们却说:「你在何事上 爱我们呢?」耶和华 说:「以扫 不是 雅各的 哥哥吗?我却爱 雅各, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, '恶 以扫,使 他的山岭 荒凉,把 他的地业 交给旷野 的野狗。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, '以东人 说:「我们现在虽 被毁坏,却要重 建 荒废之处。」万军 之耶和华 如此 说:「任他们 建造,我 必拆毁;人必称 他们的地为『罪恶 之境』;称他们的民 为『耶和华 永远 恼怒之民』。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, '你们 必亲眼 看见,也必说:「愿 耶和华 在以色列 境界 之外 被尊为大!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, '「藐视 我名 的祭司啊,万军 之耶和华 对你们 说:儿子 尊敬 父亲,仆人 敬畏主人;我 既为 父亲,尊敬我 的在哪里呢?我 既为 主人,敬畏我 的在哪里呢?你们却说:『我们在何事上 藐视 你的名呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, '你们将污秽 的食物 献 在 我的坛上,且说:『我们在何事上 污秽你呢?』因你们说,耶和华 的桌子 是 可藐视的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, ' 你们将瞎眼的 献 为祭物,这不为 恶吗? 将瘸腿的、有病的 献上,这不为 恶吗? 你献 给你的省长,他岂喜悦你, 岂能看 你的情面吗?这是万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, '「现在 我劝 你们恳求 神,他好施恩与我们。这妄献的事, 既由你们经手,他岂能看 你们的 情面吗?这是万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, '甚愿  你们中间 有一人 关上 殿门,免得 你们徒然 在我坛 上烧火。万军 之耶和华 说:我 不 喜悦 你们,也不 从你们手中 收纳 供物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, '万军 之耶和华 说: 从日 出 之地到 日落之处,我的名 在外邦中 必尊为大。在各 处,人必奉我的名 烧 香,献洁净 的供物,因为 我的名 在外邦中 必尊为大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, '你们 却亵渎我的名,说:『耶和华 的桌子 是 污秽的,其上的食物 是可藐视的。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, '你们又说:『这些事 何等烦琐!』并嗤之以鼻。这是万军 之耶和华 说的。你们把抢夺的、 瘸腿的、 有病的 拿来献上为 祭。我岂能从你们手中 收纳呢?这是耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, '行诡诈的 在群中 有 公羊,他许愿  却用有残疾 的献 给主,这人是可咒诅的。因为 我是 大 君王,我的名 在外邦中 是可畏的。这是万军 之耶和华 说的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, '「 众祭司啊,这 诫命 是传给你们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, '万军 之耶和华 说:你们若 不 听从,也 不 放 在 心上,将荣耀 归 与我的名,我就使 咒诅 临 到你们,使 你们的福分 变为咒诅; 因 你们不 把诫命放 在 心上,我已经咒诅你们了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, ' 我必斥责 你们 的 种子,又把你们牺牲 的粪 抹 你们的脸上;你们 要与 粪 一同除掉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, '你们就知道 我传 这 诫命 给你们,使我与 利未(或译:利未人)所立的约 可以常存。这是万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, '我曾与他 立 生命 和平安 的约。我将这两样赐 给他,使他存敬畏的心,他 就敬畏我,惧怕 我的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, '真实 的律法 在 他口中,他嘴 里没有 不义的话。他以平安 和正直 与我 同行,使多 人回头 离开 罪孽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, ' 祭司 的嘴 里当存 知识,人也当由他口 中寻求 律法,因为 他是 万军 之耶和华 的使者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, '你们 却偏离 正道,使许多 人在律法 上跌倒。你们废弃 我与利未 所立的约。这是万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, '所以 我 使 你们 被众 人 藐视,看为下贱;因 你们不 守 我的道,竟在律法 上瞻徇 情面。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, '我们岂不 都是 一 位父吗?岂不是 一位 神 所造的吗?我们各人 怎么 以诡诈 待弟兄,背弃了 神与我们列祖 所立的约呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, '犹大人 行事诡诈,并且在以色列 和耶路撒冷 中行 一件可憎的事;因为 犹大 人亵渎 耶和华 所 喜爱 的圣洁(或译:圣地),娶 事奉外邦 神 的女子为妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, '凡 行这事的,无论何人(何人:原文是叫醒的,答应的),就是献 供物 给万军 之耶和华,耶和华 也必从雅各 的帐棚 中剪除 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, '你们又 行 了一件这样的事,使前妻叹息 哭泣 的眼泪 遮盖 耶和华 的坛,以致耶和华不 再 看顾 那供物,也不乐意 从你们手 中收纳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, '你们还说:「这是为 什么呢?」因 耶和华 在你 和你幼年 所娶的妻 中间 作见证。她 虽是你的配偶,又是你盟约 的妻, 你 却以诡诈 待她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, '虽然 神有灵 的余 馀力能造多人,他不是 单造 一人吗?为何 只造一人呢?乃是他愿 人得 虔诚 的后裔。所以当谨守 你们的心,谁也不可 以诡诈 待幼年 所娶的妻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, ' 耶和华─以色列的 神 说:「休 妻的事和以强暴 待 妻的人都是我所恨恶的!所以当谨守 你们的心,不可 行诡诈。」这是万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, '你们用言语 烦琐 耶和华,你们还说:「我们在何事上 烦琐他呢?」因为你们说:「凡 行 恶的,耶和华 眼 看为善,并且他 喜悦 他们」;或说:「公义的 神 在哪里呢?」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, '万军 之耶和华 说:「我 要差遣 我的使者 在我前面 预备 道路。你们 所 寻求 的主 必忽然 进 入 他的殿;立约 的使者,就是 你们 所仰慕的, 快要来到。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, '他来 的 日子,谁 能当得起呢?他显现的时候,谁 能立得住呢?因为 他 如炼金之人 的火,如漂布之人 的碱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, '他必坐下 如炼 净 银子的,必洁净 利未 人,熬炼 他们 像金 银一样;他们就 凭公义 献 供物 给耶和华。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, '那时,犹大 和耶路撒冷 所献的供物 必蒙耶和华 悦纳,仿佛古时 之日、上古 之年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, '万军 之耶和华 说:「我必临近 你们,施行审判。我必 速速 作见证,警戒行邪术的、犯奸淫的、起假 誓的、亏负 人 之工价的、欺压寡妇 孤儿的、屈枉 寄居的,和不 敬畏我的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, '因 我─耶和华 是不 改变的,所以你们 雅各 之子 没有 灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, '万军 之耶和华 说:从你们列祖 的日子以来,你们常常偏离 我的典章 而不 遵守。现在你们要转 向我,我就转 向你们。你们却问说:『我们如何 才是转向呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, '人 岂可夺取 神之物呢?你们 竟 夺取 我的供物。你们却说:『我们在何事上 夺取你的供物呢?』就是你们在当纳的十分之一 和当献的供物上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, '因你们 通 国 的人都夺取 我的供物,咒诅 就临到 你们身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, '万军 之耶和华 说:你们要将 当纳的十分之一 全然 送 入 仓 库,使我家 有 粮,以此 试试我,是 否 为你们 敞开  天上 的窗户,倾 福 与你们,甚至 无处 可容。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, '万军 之耶和华 说:我必为你们 斥责蝗虫(原文是吞噬者),不容 牠毁坏 你们的 土 产。你们田 间的葡萄树 在未熟之先也不 掉果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, '万军 之耶和华 说:万 国 必称 你们 为有福的,因 你们 的地必成为 喜乐 之地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, '耶和华 说:「你们用话 顶撞 我,你们还说:『我们用什么 话 顶撞了你呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, '你们说:『事奉 神 是徒然的, 遵守 神所吩咐的, 在万军 之耶和华 面前 苦苦 斋戒,有什么 益处呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, '如今 我们 称 狂傲的人 为有福,并且 行 恶 的人得建立;他们虽然 试探 神,却得脱离灾难。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, '那时,敬畏 耶和华 的彼此 谈论,耶和华 侧耳 而听,且有纪念 册 在他面前,记录 那敬畏 耶和华、思念 他名的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, '万军 之耶和华 说:「在我 所 定 的日子,他们必 属我,特特归我。我必怜恤 他们,如同 人 怜恤 服事 自己 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, '那时你们必归回,将善人 和 恶人,事奉 神 的和 不 事奉 神的,分别出来。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, '万军 之耶和华 说:「 那日 临近,势如烧著的 火炉,凡 狂傲的 和 行 恶 的必 如碎秸,在那日 必被烧尽, 根本 枝条 一无 存留。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, '但向你们 敬畏 我名 的人必有公义 的日头 出现,其光线 缐(原文是翅膀)有医治之能。你们必出来 跳跃 如圈 里的肥犊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, '你们必践踏 恶人;在我 所 定 的日子, 他们必 如灰尘 在你们脚 掌 之下。这是万军 之耶和华 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, '「你们当记念 我仆人 摩西 的律法,就是 我在何烈山 为 以色列 众人 所吩咐 他 的律例 典章。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, '「看哪,耶和华 大 而可畏 之日 未到 以前,我 必差遣 先知 以利亚 到你们那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, '他必使父亲 的心 转 向 儿女,儿女 的心 转向 父亲,免得 我来 咒诅 遍地。」    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, '亚伯拉罕 的后裔,大卫 的子孙(后裔,子孙:原文是儿子;下同),耶稣 基督 的家 谱: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, '亚伯拉罕 生 以撒; 以撒 生 雅各; 雅各 生 犹大 和 他的 弟兄; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, ' 犹大 从 她玛氏 生 法勒斯 和 谢拉; 法勒斯 生 希斯仑 ; 希斯仑  生 亚兰; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, ' 亚兰 生 亚米拿达; 亚米拿达 生 拿顺; 拿顺 生 撒门; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, ' 撒门 从 喇合氏 生 波阿斯; 波阿斯 从 路得氏 生 俄备得; 俄备得 生 耶西; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, ' 耶西 生 大卫 王。 大卫 从 乌利亚 的妻子 生 所罗门; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, ' 所罗门 生 罗波安; 罗波安 生 亚比雅; 亚比雅 生 亚撒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, ' 亚撒 生 约沙法; 约沙法 生 约兰; 约兰 生 乌西雅; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, ' 乌西雅 生 约坦; 约坦 生 亚哈斯; 亚哈斯 生 希西家; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, ' 希西家 生 玛拿西; 玛拿西 生 亚们; 亚们 生 约西亚; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, '百姓被迁到 巴比伦 的时候, 约西亚 生 耶哥尼雅 和 他的 弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, ' 迁到 巴比伦 之后,耶哥尼雅 生 撒拉铁; 撒拉铁 生 所罗巴伯; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, ' 所罗巴伯 生 亚比玉; 亚比玉 生 以利亚敬; 以利亚敬 生 亚所; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, ' 亚所 生 撒督; 撒督 生 亚金; 亚金 生 以律; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, ' 以律 生 以利亚撒; 以利亚撒 生 马但; 马但 生 雅各; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, ' 雅各 生 约瑟,就是马利亚 的丈夫。那 称为 基督 的耶稣 是从 马利亚 生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, '这样,从 亚伯拉罕 到 大卫 共有 十四 代; 从 大卫 到 迁至 巴比伦 的时候也有十四 代; 从 迁至 巴比伦 的时候到 基督 又有十四 代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, ' 耶稣 基督 降生 的事记在 下面:他 母亲 马利亚 已经许配了 约瑟, 还没有 迎娶,马利亚就 从 圣 灵 怀了 孕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, ' 她 丈夫 约瑟 是 个义人, 不 愿 意 明明地羞辱 她,想要 暗暗地 把她 休了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, ' 正思念 这事的时候, 有主 的使者 向他 梦 中 显现,说:「大卫 的子孙 约瑟,不要 怕!只管娶过 你 的妻子 马利亚来,因 她 所 怀的孕 是 从 圣 灵来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, ' 她将要生 一个儿子, 你要给他 起 名 叫耶稣,因 他 要将自己的 百姓 从 罪恶 里救出来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, '这 一切的事 成就 是要 应验 主 藉 借 先知 所 说 的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, '说: 必有童女 怀 孕 生 子; 人要称 他的 名 为以马内利。(以马内利 翻出来 就是「 神 与我们 同在」。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, ' 约瑟 醒了,起来,就遵著 主 使者 的吩咐 把妻子 娶过来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, '只是 没有 和她 同房,等 她生了儿子(有古卷:等她生了头胎的儿子),就 给他 起 名 叫耶稣。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, ' 当 希律 王 的时候,耶稣 生 在 犹太 的伯利恒。 有几个博士 从 东方 来 到 耶路撒冷,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, '「那生下来 作犹太人 之王 的在 哪里? 我们在 东方 看见 他的 星, 特来 拜 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, ' 希律 王 听见了,就心里不安; 耶路撒冷 合城 的人也都不安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, ' 他就召 齐了 祭司长 和 民间的 文士,问 他们说:「基督 当生 在何处?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, ' 他们回答说:「在 犹太 的伯利恒。因为 有 先知 记著,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, ' 犹大 地 的伯利恒啊,你 在 犹大 诸城 中并不 是 最小的;因为 将来有一位君王 要从 你 那里出来, 牧养 我 以色列 民。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, '当下,希律 暗暗地 召了 博士来,细问 那星 是什么时候 出现的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, '就 差 他们 往 伯利恒去,说:「你们去 仔细 寻访 那小孩子, 寻到了 就来 报信,我也 好 去 拜 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, ' 他们听见 王 的话就去了。在 东方 所 看见 的那星 忽然 在他们 前头行,直行 到 小孩子 的地方,就在上头 停住了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, ' 他们看见 那星,就大大地 欢喜; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, ' 进了 房子,看见 小孩子 和 他 母亲 马利亚,就 俯伏 拜 那小孩子, 揭开  宝盒,拿黄金、 乳香、 没药 为礼物 献给 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, ' 博士因为在 梦 中被主指示 不要 回去 见 希律,就从 别的 路 回 本 地 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, ' 他们 去后, 有主 的使者 向约瑟 梦 中 显现,说:「起来!带著 小孩子 同 他 母亲 逃 往 埃及, 住在 那里,等 我吩咐 你;因为 希律 必 寻找 小孩子,要除灭 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, '约瑟就 起来,夜间 带著 小孩子 和 他 母亲 往 埃及 去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, ' 住在 那里,直到 希律 死了。这是要 应验 主 藉 借 先知 所 说的话,说:「我从 埃及 召出 我的 儿子来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, ' 希律 见 自己被 博士 愚弄,就大大 发怒, 差人 将伯利恒 城里 并 四 境 所有的 男孩,照著 他向 博士 仔细查问 的时候,凡 两岁 以里的,都杀尽了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, '这 就应了 先知 耶利米 的话,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, '在 拉玛 听见 号 咷 大 哭 的声音,是拉结 哭 她 儿女, 不 肯 受安慰,因为 他们都不 在了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, ' 希律 死了以后, 有主 的使者 在 埃及 向约瑟 梦 中 显现,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, '「起来!带著 小孩子 和 他 母亲 往 以色列 地 去,因为 要害 小孩子 性命 的人已经死了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, '约瑟就 起来,把小孩子 和 他 母亲 带 到 以色列 地 去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, '只 因 听见 亚基老 接著 他 父亲 希律 作了犹太 王,就怕 往那里 去,又 在 梦 中被主指示,便往 加利利 境内 去了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, ' 到了 一座城,名叫 拿撒勒,就住 在那里。这是要 应验 先知 所 说, 他将称为 拿撒勒人的话了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, ' 那 时,有施洗 的约翰 出来,在 犹太 的旷野 传道, 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, '「 天 国 近了,你们应当悔改!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, ' 这人 就是 先知 以赛亚 所 说的。他说:「在 旷野 有人声 喊著说:预备 主的 道,修 直 他的 路!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, ' 这 约翰 身 穿 骆驼 毛 的 衣服, 腰 束 皮 带, 吃的 是 蝗虫、 野 蜜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, '那时,耶路撒冷 和 犹太 全地,并 约旦河 一带地方 的人,都出去 到 约翰那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, ' 承认 他们的 罪,在 约旦河 里受 他的 洗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, ' 约翰看见 许多 法利赛人 和 撒都该人 也来 受 洗,就对他们 说:「毒蛇 的种类!谁 指示 你们 逃避 将来 的忿怒呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, '你们要 结出 果子来,与悔改 的心相称。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, ' 不要 自己 心 里 说:『有 亚伯拉罕 为我们的祖宗。』 我告诉 你们, 神 能 从 这些 石头 中给亚伯拉罕 兴起 子孙来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, '现在 斧子 已经放 在 树 根上, 凡 不 结 好 果子 的树 就砍下来, 丢 在 火里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, '我 是 用 水 给你们 施洗,叫 你们悔改。但 那 在我 以后 来的, 能力比我 更大,我就是 给他 提 鞋 也不 配。他 要用 圣 灵 与 火 给你们 施洗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, '他 手 里 拿著 簸箕,要 扬净 他的 场, 把 麦子 收 在 仓里, 把糠 用不灭的 火 烧尽了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, '当下,耶稣 从 加利利 来 到 约旦河,见了 约翰,要受 他的 洗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, ' 约翰 想要拦住 他,说:「我 当 受 你的 洗, 你 反倒上 我 这里来吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, ' 耶稣 回答 说:「你暂且 许我,因为 我们 理 当 这样 尽 诸般的 义(或译:礼)。」于 是 约翰许了 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, ' 耶稣 受了洗,随即 从 水 里上来。 天 忽然 为他 开 了,他就 看见 神 的灵 仿佛 鸽子 降下, 落 在 他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, ' 从 天上 有声音 说:「这 是 我的 爱 子, 我所喜悦的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, '当时,耶稣 被 圣灵 引 到 旷野,受 魔鬼 的试探。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, ' 他禁食 四十 昼 夜,后来 就饿了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, ' 那试探人的 进前来,对他 说:「你若 是 神 的儿子,可以 吩咐 这些 石头 变成 食物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, '耶稣 却 回答 说:「经上记著说:人 活著,不是 单 靠 食物,乃是 靠 神 口 里所出 的一切 话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, '魔鬼 就 带 他 进了 圣 城, 叫他 站 在 殿顶(顶:原文是翅)上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, ' 对他 说:「你若 是 神 的儿子,可以 跳 下去,因为 经上记著 说:主要为 你 吩咐 他的 使者 用 手 托著 你,免得 你的 脚 碰 在 石头上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, '耶稣 对他 说:「经上又 记著说:『不可 试探 主─你的 神。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, '魔鬼 又 带 他 上了 一座最 高的 山, 将世上 的万 国 与 万国的 荣华 都指给他 看, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, ' 对他 说:「你若 俯伏 拜 我,我就把这 一切 都赐给 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, ' 耶稣 说:「撒但(就是抵挡的意思,乃魔鬼的别名),退去吧!因为 经上记著说:当拜 主-你的 神, 单要 事奉 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, '于 是,魔鬼 离了 耶稣, 有天使 来 伺候 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, ' 耶稣听见 约翰 下了监,就退 到 加利利去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, '后又 离开  拿撒勒,往迦百农 去,就住 在那里。那地方 靠海,在 西布伦 和 拿弗他利 的边界上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, '这是要 应验 先知 以赛亚 的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, '说:西布伦 地, 拿弗他利 地,就是沿海 的路,约旦河 外,外邦人 的加利利地─ ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, '那 坐 在 黑暗 里的百姓 看见了 大 光; 坐 在 死 荫 之 地 的人有光 发现 照著他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, '从 那时候,耶稣 就 传起道来, 说:「 天 国 近了,你们应当悔改!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, ' 耶稣在加利利 海 边 行走,看见 弟兄 二人,就是那 称呼 彼得 的西门 和 他 兄弟 安得烈,在 海 里撒 网;他们本 是 打鱼的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, ' 耶稣对他们 说:「来 跟从 我, 我要叫 你们 得人 如得鱼一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, '他们就 立刻 舍了 网,跟从了 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, ' 从那里 往前走,又 看见 弟兄 二人,西庇太 的儿子 雅各 和 他 兄弟 约翰,同 他们的 父亲 西庇太 在 船 上补 网,耶稣就 招呼 他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, ' 他们立刻 舍了 船, 别了 父亲,跟从了 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, ' 耶稣走 遍 加利利,在 各 会堂 里教训人, 传 天国 的福音, 医治 百姓 各样的 病 症。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, '他的 名声 就 传 遍了 叙利亚。 那里的人把一切 害 病的,就是害 各样 疾病、 各样疼痛 的和 被鬼附的、 癫痫的、 瘫痪的,都带了来,耶稣就 治好了 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, '当下,有许多 人 从 加利利、 低加坡里、 耶路撒冷、 犹太、 约旦河 外 来跟著 他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, ' 耶稣看见 这许多的人,就上了 山,既 已坐下, 门徒 到 他跟前来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, '他就 开  口 教训 他们,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, '虚 心 的人有福了!因为 天 国 是 他们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, '哀恸 的人有福了!因为 他们 必得安慰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, '温柔的人 有福了!因为 他们 必承受 地土。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, ' 饥 渴慕 义 的人有福了!因为 他们 必得饱足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, '怜恤人的 人有福了!因为 他们 必蒙怜恤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, '清 心 的人有福了!因为 他们 必得见 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, '使人和睦的人 有福了!因为 他们 必称为 神 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, '为 义 受逼迫 的人有福了!因为 天 国 是 他们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, '「人若 因 我 辱骂 你们, 逼迫你们, 捏造 各样 坏 话毁谤 你们,你们 就有福了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, '应当欢喜 快乐,因为 你们 在 天上 的赏赐 是大的。 在你们 以前 的 先知,人也是这样 逼迫他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, '「你们 是 世上 的盐。 盐 若 失了味,怎能 叫它再咸呢?以后 无 用,不过 丢 在外面,被 人 践踏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, '你们 是 世上 的光。城 造 在 山 上是不 能 隐藏的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, '人点 灯, 不 放 在 斗 底下, 是放在 灯台上,就 照亮 一 家的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, '你们的 光 也当这样 照 在人 前,叫 他们看见 你们的 好 行为, 便将荣耀归给 你们 在 天上 的 父。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, '「莫 想 我来 要废掉 律法 和 先知。我来 不是 要废掉,乃是 要成全。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, ' 我实在 告诉 你们,就是 到 天 地 都废去了,律法 的 一 点 一 画 划 也 不能 废去, 都 要成全。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, '所以,无论 何人 废掉 这 诫命 中最小的 一条,又 教训 人 这样做,他在 天 国 要称为 最小的。但 无论 何人 遵行这诫命,又 教训人遵行,他 在 天 国 要称为 大的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, ' 我告诉 你们, 你们的 义 若 不 胜 于  文士 和 法利赛人的义,断不能 进 天 国。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, '「你们听见 有吩咐 古人的话,说:『不可 杀人』;又说:『凡 杀人的 难免 受 审判。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, '只是 我 告诉 你们, 凡(有古卷在凡字下加:无缘无故地)向 弟兄 动怒的,难免 受 审断; 凡 骂 弟兄 是拉加的, 难免 公会的审断; 凡 骂 弟兄是魔利的, 难免 地狱 的 火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, '所以,你 在 祭坛 上献 礼物 的时候,若 想起 弟兄 向 你 怀 怨, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, '就把 礼物 留 在 坛 前, 先 去 同 弟兄 和好, 然后 来 献 礼物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, '你同告你的 对头 还 在 路上,就赶紧 与 他 和息,恐怕 他 把你 送给 审判官, 审判官 交付衙役,你就 下 在监 里了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, '我实在 告诉 你,若有 一文 钱 没有还清,你断不能 从那里 出来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, '「你们听见 有话说:『不可 奸淫。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, '只是 我 告诉 你们, 凡 看见 妇女 就动 淫念的,这人 心 里 已经 与她 犯奸淫了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, ' 若是 你的 右 眼 叫你 跌倒,就 剜出来 丢掉, 宁可 失去 百体 中的一体, 不叫 全 身 丢 在 地狱里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, ' 若是 右 手 叫你 跌倒,就 砍下来 丢掉, 宁可 失去 百体 中的一体, 不叫 全 身 下 入 地狱。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, '「又 有话说:『人 若休 妻,就当给 她 休书。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, '只是 我 告诉 你们, 凡 休 妻的,若不是 为淫乱 的缘故,就是叫 她 作淫妇了; 人 若娶 这被休的妇人,也是犯奸淫了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, '「你们又 听见 有吩咐 古人的话,说:『 不可 背誓, 所起的誓 总要向主 谨守。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, '只是 我 告诉 你们,什么誓都 不可 起。不可 指著 天起誓,因为 天是 神 的座位; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, '不可 指著 地起誓,因为 地是 他的 脚 凳;也不可 指著 耶路撒冷起誓,因为 耶路撒冷是 大 君 的京城; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, '又不可 指著 你的 头 起誓,因为 你不 能 使 一根 头发 变黑 变 白了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, ' 你们的 话,是,就 说是;不是,就说不是; 若再多 说,就是 出于  那恶者(或译:就是从恶里出来的)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, '「你们听见 有话说:『 以眼 还 眼, 以牙 还 牙。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, '只是 我 告诉 你们,不要 与恶人 作对。 有人 打 你的 右 脸,连左 脸也 转过来 由他打; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, ' 有人想要 告 你, 要拿 你的 里衣,连外衣 也 由他 拿去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, ' 有人 强逼你 走 一 里路,你就同 他 走 二里; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, '有求 你的,就给他; 有 向 你 借贷的,不可 推辞。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, '「你们听见 有话说:『 当爱 你的 邻舍, 恨 你的 仇敌。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, '只是 我 告诉 你们,要爱 你们的 仇敌,为 那 逼迫 你们 的祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, '这样 就可以作 你们 天 父 的儿子;因为 他 叫日头 照 好人,也 照歹人; 降雨 给 义人,也 给不义的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, ' 你们若 单爱 那 爱 你们的人,有 什么 赏赐呢?就是税吏 不 也 是这样 行吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, ' 你们若 单 请你 弟兄 的安,比人有 什么 长处呢?就是外邦人 不 也 是这样 行吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, '所以,你们 要 完全,像 你们的 天 父 完全一样。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, '「你们要小心,不可 将 善事 行 在人 的面前,故意叫 他们 看见,若是这样,就不能 得 你们 天 父 的 赏赐了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, '所以,你 施舍 的时候,不可 在你 前面 吹号,像 那假冒为善的人 在 会堂 里和 街道 上 所行的, 故意要得人 的 荣耀。我实在 告诉 你们,他们已经得了 他们的 赏赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, ' 你 施舍的时候,不要 叫 左手 知道 右手 所做 的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, '要叫 你 施舍的事 行 在 暗中。 你 父 在 暗中 察看,必然报答 你(有古卷:必在明处报答你)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, '「 你们祷告 的时候,不可 像 那假冒为善的人, 爱 站 在 会堂 里和 十字 路口 上 祷告, 故意叫人 看见。我实在 告诉 你们,他们已经得了 他们的 赏赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, ' 你 祷告 的时候,要进 你的 内屋, 关上 门,祷告 你 在 暗中 的父; 你 父 在 暗中 察看,必然报答 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, ' 你们祷告,不可 像 外邦人,用许多重复话, 他们 以为 话多了 必蒙垂听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, ' 你们不可 效法 他们;因为 你们 没有祈求 以先,你们所 需用 的,你们的 父 早已知道了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, '所以,你们 祷告 要这样说:我们 在 天上 的父:愿 人都尊你的 名 为圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, '愿 你的 国 降临;愿 你的 旨意 行 在 地上, 如同 行在 天上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, '我们 日用的 饮食,今日 赐给 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, ' 免 我们的 债, 如同 我们 免了 人的债。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, ' 不 叫 我们 遇见 试探; 救 我们 脱离 凶恶(或译:脱离恶者)。因为 国度、 权柄、 荣耀,全是 你的,直到 永远。阿们(有古卷没有因为......阿们等字)! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, '「 你们饶恕 人 的 过犯,你们的 天 父 也 必饶恕 你们的过犯; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, ' 你们 不 饶恕 人的过犯,你们的 天父 也必不 饶恕 你们的 过犯。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, '「 你们禁食 的时候,不可 像 那假冒为善的人,脸上带著愁容;因为 他们 把脸 弄得难看, 故意叫人 看出 他们是禁食。我实在 告诉 你们,他们已经得了 他们的 赏赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, ' 你 禁食的时候,要梳 头 洗 脸, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, ' 不 叫人 看出 你禁食来,只 叫你 暗中 的父看见; 你 父 在 暗中 察看,必然报答 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, '「不要 为自己 积攒 财宝 在 地上;地上 有虫子咬, 能锈 坏,也 有 贼 挖窟窿 来 偷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, '只要 积攒 财宝 在 天上;天上 没有 虫子咬,不能 锈 坏,也 没有 贼 挖窟窿 来偷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, '因为 你的 财宝 在 哪里,你的 心 也 在 那里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, '「眼睛 就是 身上 的灯。 你的 眼睛 若 瞭 了亮, 全 身 就 光明; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, ' 你的 眼睛 若 昏花, 全 身 就 黑暗。 你 里头 的光 若 黑暗了,那黑暗 是何等大呢!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, '「一个人不 能 事奉 两个 主; 不是 恶 这个、 爱 那个,就是 重 这个、 轻 那个。你们不 能 又事奉 神,又 事奉玛门(玛门:财利的意思)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, '「所以 我告诉 你们,不要 为 生命 忧虑 吃 什么, 喝 什么;为 身体 忧虑穿 什么。生命 不 胜于  饮食吗? 身体 不胜于 衣裳吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, '你们看 那天上的 飞鸟, 也不 种,也不 收,也不 积蓄 在 仓里, 你们的 天 父 尚且养活 牠。你们 不 比飞鸟 贵重 得多吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, ' 你们 哪一个 能 用思虑 使 寿数 多加 一 刻呢(或译:使身量多加一肘呢)? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, ' 何必 为 衣裳 忧虑呢?你想 野地里的 百合花 怎么 长起来;它也不 劳苦,也不 纺线 缐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, '然而 我告诉 你们, 就是所罗门 极 荣华的时候,他所穿戴的,还不 如 这 花一朵呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, ' 你们这小信的人哪!野地里的 草 今天 还在, 明天 就丢 在 炉里, 神 还给它这样的 妆饰,何况 你们呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, '所以,不要 忧虑 说,吃 什么? 喝 什么? 穿 什么? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, ' 这 都是 外邦人 所求的, 你们需用 的这一切 东西,你们的 天 父 是知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, ' 你们要先 求 他的 国 和 他的 义, 这些东西 都要 加给 你们了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, '所以,不要 为 明天 忧虑,因为 明天 自有明天的 忧虑;一天 的难处 一天 当就够了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, '「你们不要 论断人,免得 你们被论断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, '因为 你们怎样 论断人,也必怎样被论断; 你们用 什么 量器 量给人,也必用什么量器量 给你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, ' 为什么 看见 你 弟兄 眼 中 有刺,却 不 想 自己 眼 中 有梁木呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, ' 你自己 眼 中 有梁木, 怎能 对你 弟兄 说:『容 我去掉 你 眼 中的刺』呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, '你这假冒为善的人!先 去掉 自己 眼 中的梁木, 然后 才能看得清楚,去掉 你 弟兄 眼 中的刺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, '不要 把圣 物 给 狗,也不要 把你们的 珍珠 丢 在猪 前,恐怕 牠践踏了 珍珠, 转过来 咬 你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, '「你们祈求,就 给 你们;寻找,就 寻见;叩门,就 给你们 开 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, '因为 凡 祈求的,就得著; 寻找的,就寻见; 叩门的,就给他开 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, ' 你们 中间 谁 有 儿子 求 饼,反 给 他 石头呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, ' 求 鱼,反 给 他 蛇呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, '你们 虽然 不好,尚且 知道 拿好 东西 给 儿女,何况 你们 在 天上 的父,岂不更 把好东西 给 求 他的人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, '所以,无论 何事, 你们愿 意 人 怎样待 你们,你们 也要 怎样 待 人,因为 这 就是 律法 和 先知的道理。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, '「你们要进 窄 门。因为 引 到 灭亡,那门 是宽的, 路 是大的,进去 的人 也 多; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, ' 引 到 永生,那 门 是窄的, 路 是小的,找著的 人也 少。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, '「你们要防备 假先知。他们 到 你们 这里来,外面披著 羊 皮,里面 却 是 残暴的 狼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, '凭著 他们的 果子,就可以认出 他们来。荆棘 上 岂能 摘 葡萄呢? 蒺藜 里 岂能摘无花果呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, '这样,凡 好 树 都结 好 果子,惟独 坏 树 结 坏 果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, '好 树 不 能 结 坏 果子;坏 树 不能 结 好 果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, '凡 不 结 好 果子 的树 就砍下来, 丢 在 火里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, '所以,凭著 他们的 果子 就可以认出 他们来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, '「凡 称呼 我『主啊,主啊』的人不能 都进 天 国;惟独 遵行 我 天 父 旨意的人才能进去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, '当 那 日 必有许多人 对我 说:『主啊,主啊,我们不是 奉你的 名 传道, 奉你的 名 赶 鬼, 奉你的 名 行 许多 异能吗?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, ' 我就 明明地告诉 他们说:『 我从来不 认识 你们,你们这些作 恶的人,离开  我去吧!』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, '「所以,凡 听见 我 这 话 就 去行 的,好比 一个聪明 人, 把 房子 盖 在 磐石上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, ' 雨 淋, 水 冲, 风 吹, 撞著 那 房子, 房子总不 倒塌,因为 根基立 在 磐石上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, ' 凡 听见 我 这 话 不 去行 的,好比 一个无知的 人, 把 房子 盖 在 沙土上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, ' 雨 淋, 水 冲, 风 吹, 撞著 那 房子,房子就 倒塌了,并且 倒塌 得 很大。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, ' 耶稣 讲完了 这些 话,众人 都希奇 他的 教训; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, ' 因为 他教训 他们,正像 有 权柄的人, 不 像 他们的 文士。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, ' 耶稣 下了 山,有许多人 跟著 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, ' 有一个长大痲疯的 来 拜 他,说:「主 若 肯,必能 叫我 洁净了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, ' 耶稣伸 手 摸 他,说:「我肯,你洁净了吧!」他的 大痲疯 立刻 就 洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, ' 耶稣 对他 说:「你切 不可 告诉人,只要 去 把身体 给祭司 察看, 献上 摩西 所吩咐 的礼物,对众人 作 证据。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, ' 耶稣 进了 迦百农,有一个百夫长 进前来,求 他 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, '「主啊,我的 仆人 害瘫痪病,躺 在 家里,甚是 疼苦。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, ' 耶稣 说:「我 去 医治 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, '百夫长 回答 说:「主啊, 你到 我 舍 下,我不 敢 当;只要 你说 一句话, 我的 仆人 就必好了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, '因为 我 在人 的权 下,也有 兵 在我 以下; 对这个 说:『去!』他就 去; 对那个说:『来!』他就 来; 对我的 仆人说:『你做 这事!』他就 去做。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, ' 耶稣 听见 就希奇, 对跟从的 人说:「我实在 告诉 你们,这么大 的信心,就是在 以色列中,我也没有 遇见过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, '我又 告诉 你们, 从 东 从西,将有许多人 来, 在 天 国 里与亚伯拉罕、 以撒、 雅各 一同 坐席; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, '惟有 本国 的子民 竟被赶 到 外边 黑暗里去,在那里 必要 哀哭 切 齿了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, ' 耶稣 对百夫长 说:「你回去吧!照 你的信心,给你 成全了。」 那 时,他的 仆人 就 好了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, ' 耶稣 到了 彼得 家里,见 彼得的 岳母 害热病 躺著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, ' 耶稣把她的 手 一摸,热 就 退了;她就 起来 服事 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, ' 到了 晚上,有人带著 许多 被鬼附的 来到耶稣跟前,他只用一句话 就 把鬼 都赶出去,并且 治好了 一切 有 病的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, '这是要 应验 先知 以赛亚 的话,说:他 代替 我们的 软弱, 担当 我们的疾病。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, ' 耶稣 见 许多人 围著 他,就吩咐 渡到 那边 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, ' 有一个 文士 来,对他 说:「夫子,你无论 往哪里 去,我要跟从 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, ' 耶稣 说:「狐狸 有 洞, 天空的 飞鸟 有窝,人 子 却 没 有 枕 头 的地方。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, '又 有一个 门徒 对耶稣 说:「主啊,容 我 先 回去 埋葬 我的 父亲。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, ' 耶稣 说:「 任凭 死人 埋葬 他们的 死人;你跟从 我吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, ' 耶稣 上了 船, 门徒 跟著 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, ' 海 里 忽然 起了 暴风,甚至 船 被 波浪 掩盖;耶稣 却 睡著了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, ' 门徒来 叫醒了 他,说:「主啊,救我们,我们丧命啦!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, ' 耶稣 说:「你们 这小信的人哪,为什么 胆怯呢?」于 是 起来,斥责 风 和 海, 风和海就 大大地 平静了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, ' 众人 希奇,说:「这 是 怎样的人? 连 风 和 海 也听从 他了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, '耶稣 既 渡到 那边 去,来到 加大拉人 的地方,就有两个 被鬼附的 人从 坟茔 里出来 迎著 他,极其 凶猛,甚至 没 有人 能 从 那条 路 上经过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, ' 他们喊著 说:「 神 的儿子,我们 与 你 有什么相干?时候 还没有到,你就上这里 来 叫我们 受苦吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, ' 离 他们 很远,有一大 群 猪 吃食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, ' 鬼 就央求 耶稣,说:「若 把我们 赶出去,就打发 我们 进入 猪 群吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, ' 耶稣 说:「去吧!」鬼就 出来,进入 猪群。 全 群 忽然 闯 下 山崖,投在 海 里 淹死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, '放 猪的就 逃跑 进 城,将这一切事 和 被鬼附的 人所遭遇的都告诉人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, ' 合 城 的人都出来 迎见 耶稣,既 见了 就央求 他 离开  他们的 境界。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, ' 耶稣上了 船,渡过海, 来 到 自己的 城里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, ' 有人用 褥子 抬著 一个瘫子 到耶稣跟前来。 耶稣 见 他们的 信心,就对瘫子 说:「小子,放心吧!你的 罪 赦了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, ' 有几个 文士 心里 说:「这个 人说僭妄的话了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, ' 耶稣 知道 他们的 心意,就说:「你们为什么 心 里 怀著 恶念呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, '或说『你的 罪 赦了』,或 说『你起来 行走』, 哪一样 容易呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, '但 要叫 你们知道, 人 子 在 地上 有 赦 罪 的权柄」;就 对瘫子 说:「起来!拿 你的 褥子 回 家去吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, '那人就 起来,回 家去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, ' 众人 看见 都惊奇,就 归荣耀与 神,因为他 将这样的 权柄 赐给 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, ' 耶稣 从那里 往前走,看见 一个人 名叫 马太,坐 在 税关上,就 对他 说:「你跟从 我来。」他就 起来 跟从了 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, ' 耶稣 在 屋 里坐席 的时候, 有好些 税吏 和 罪人 来,与耶稣 和 他的 门徒 一同坐席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, ' 法利赛人 看见,就对耶稣 的门徒 说:「你们的 先生 为什么 和 税吏 并 罪人 一同吃饭呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, ' 耶稣听见,就说:「康健 的人用 不 著 医生,有病的 人才 用得著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, '经上说:『我喜爱 怜恤, 不 喜爱祭祀。』这句话 的意思,你们且 去 揣摩。我来 本 不是 召 义人,乃是 召罪人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, '那时,约翰的 门徒 来 见耶稣,说:「我们 和 法利赛人 常常 禁食,你的 门徒 倒 不 禁食,这是为什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, ' 耶稣 对他们 说:「新郎 和陪伴之人 同 在 的时候,陪伴之人 岂 能 哀恸呢?但 日子 将到, 新郎 要离开  他们,那时候 他们就要 禁食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, ' 没有人 把 新 布 补 在 旧 衣服上;因为 所 补上的 反带 坏了 那衣服, 破的 就 更大了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, '也没有 人把新 酒 装 在 旧 皮袋里;若是 这样,皮袋 就裂开 , 酒 漏出来,连皮袋 也 坏了。惟独 把新 酒 装 在 新 皮袋里,两样 就 都保全了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, '耶稣 说 这话的时候, 有一个 管会堂的 来 拜 他,说:「我 女儿 刚才 死了, 求你去 按 手 在 她身上,她就 必活了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, '耶稣 便 起来 跟著 他去; 门徒 也跟了去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, ' 有一个女人,患了十二 年 的血漏,来到 耶稣背后,摸 他的 衣裳 䍁子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, '因为 她 心里 说:「 我只 摸 他的 衣裳,就必痊愈。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, ' 耶稣 转过来, 看见 她,就说:「女儿,放心!你的 信 救了 你。」从 那 时候,女人 就 痊愈了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, ' 耶稣 到了 管会堂的 家里, 看见 有吹手,又有 许多人 乱嚷, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, '就说:「退去吧! 这闺女 不是 死了,是 睡著了。」他们就 嗤笑 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, ' 众人 既 被撵出,耶稣就进去,拉著 闺女 的手,闺女 便 起来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, '于 是 这 风声 传 遍了 那 地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, ' 耶稣 从那里 往前走,有两个 瞎子 跟著 他,喊叫 说:「大卫的 子孙,可怜 我们吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, ' 耶稣进了 房子,瞎子 就来到 他跟前。 耶稣 说:「你们信 我能 做 这事吗?」他们 说:「主啊,我们信。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, '耶稣就 摸 他们的 眼睛,说:「照著 你们的 信 给你们 成全了吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, '他们的 眼睛 就 开 了。 耶稣 切切地嘱咐 他们 说:「你们要小心,不可 叫人知道。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, '他们出去,竟 把他的 名声传 遍了 那 地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, ' 他们 出去的时候, 有人将鬼所附的 一个哑巴 带到 耶稣跟前来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, '鬼 被赶出去,哑巴 就 说出话来。 众人 都希奇,说:「在 以色列中,从来没有 见过 这样的事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, '法利赛人 却 说:「他是靠著 鬼 王 赶 鬼。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, ' 耶稣 走 遍 各城 各乡,在 会堂 里教训人, 宣讲 天国 的福音,又 医治 各样的 病症。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, '他看见 许多的人,就 怜悯 他们;因为 他们 困苦 流离,如同 羊 没 有 牧人一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, '于 是 对 门徒 说:「要 收的庄稼 多, 做工的人 少。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, '所以,你们当求 庄稼 的主 打发 工人 出去收 他的 庄稼。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, ' 耶稣叫了 十二个 门徒来,给 他们 权柄,能 赶逐 污 鬼,并 医治 各样的 病 症。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, ' 这 十二 使徒 的名:头一个 叫西门(又称 彼得),还有 他 兄弟 安得烈, 西庇太 的儿子 雅各 和 雅各的 兄弟 约翰, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, '腓力 和 巴多罗买 ,多马 和 税吏 马太,亚勒腓 的儿子 雅各,和 达太, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, '奋锐党的 西门,还有 卖 耶稣 的加略人 犹大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, '耶稣 差 这 十二个人去,吩咐 他们 说:「外邦人的 路,你们不要 走; 撒马利亚人 的城,你们不要 进; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, ' 宁可 往 以色列 家 迷失的 羊 那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, ' 随走 随传,说『天 国 近了!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, '医治 病人,叫死人 复活,叫长大痲疯的 洁净,把鬼 赶出去。你们白白地 得来,也要白白地 舍去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, ' 腰袋 里 不要 带 金 银 铜钱; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, ' 行路 不要 带口袋;不要 带两件 褂子,也不要 带鞋 和 拐杖。因为 工人 得 饮食 是应当的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, ' 你们无论 进 哪一城, 哪一村,要打听 那里 谁 是 好人,就住 在他家,直 住到 走的时候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, ' 进 他家 里去,要请他 的安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, ' 那家 若 配 得平安,你们 所求的平安 就必临 到 那家; 若 不 配 得,你们 所求的平安 仍归 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, ' 凡 不 接待 你们、不 听 你们 话的人,你们离开  那 家,或是 那城的时候,就把 脚上 的尘土 跺下去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, '我实在 告诉 你们,当 审判的 日子,所多玛 和 蛾摩拉所受的, 比 那 城 还容易受呢!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, '「 我 差 你们去,如同 羊 进 入 狼群;所以 你们要 灵巧 像 蛇, 驯良 像 鸽子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, ' 你们要防备 人;因为 他们要把你们 交 给 公会,也 要在 会堂 里鞭打 你们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, '并且 你们要为我的 缘故 被送到 诸侯 君王 面前,对他们 和 外邦人 作 见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, ' 你们 被交 的时候,不要 思虑 怎样 说话,或 说什么话。 到 那 时候,必赐给 你们 当 说的话; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, '因为 不 是 你们 自己 说的,乃是 你们 父 的灵 在 你们 里头说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, ' 弟兄 要把弟兄, 父亲 要把儿子,送 到 死地; 儿女 要与 父母 为敌, 害死 他们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, '并且 你们要 为 我的 名 被 众人 恨恶。惟有 忍耐 到 底 的 必然得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, ' 有人在 这 城 里逼迫 你们,就逃 到 那城里去。 我实在 告诉 你们,以色列 的城邑,你们还没有 走遍, 人 子 就到了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, '学生 不能 高过 先生;仆人 不能 高过 主人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, '学生 和 先生 一样, 仆人 和 主人 一样,也就 罢了。人既 骂 家主 是别西卜(别西卜:是鬼王的名),何况 他的 家人呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, '「所以,不要 怕 他们;因为 掩盖 的事没 有 不 露出来的, 隐藏 的事 没有不 被人知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, '我在 暗 中告诉 你们 的,你们要在 明处 说出来; 你们耳 中 所听 的,要在 房上 宣扬出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, ' 那 杀 身体、 不 能 杀 灵魂的,不要 怕他们;惟有 能 把身体 和 灵魂 都 灭 在 地狱里的,正要 怕他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, '两个 麻雀 不是 卖 一分银子吗?若是你们的 父 不许, 一个 也 不能 掉 在 地上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, '就是 你们的 头 发 也 都 被数过了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, '所以,不要 惧怕,你们 比许多 麻雀 还贵重!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, '「 凡 在人 面前 认 我的,我在我 天上 的父 面前 也 必认 他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, ' 凡 在人 面前 不认 我的,我在我 天上 的父 面前 也 必不认 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, '「你们不要 想 我来 是叫 地上 太平;我来 并不是 叫 地上太平,乃是 叫地上动刀兵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, '因为 我来 是叫人 与 父亲 生疏, 女儿 与 母亲生疏, 媳妇 与 婆婆生疏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, ' 人 的仇敌 就是自己 家里的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, '「爱 父 母 过于  爱我的, 不 配 作我的门徒; 爱 儿 女 过于  爱我的, 不 配 作我的门徒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, ' 不 背著 他的 十字架 跟从 我的, 也不 配 作我的门徒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, '得著 生命的,将要失丧 生命; 为 我 失丧 生命的,将要得著 生命。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, '「人接待 你们 就是接待 我;接待 我 就是 接待 那差 我来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, '人因为 先知 的名 接待 先知,必得 先知 所得的赏赐; 人因为 义人 的名 接待 义人,必得 义人 所得的赏赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, ' 无论何人,因为 门徒 的名,只 把一杯 凉水 给这 小子 里的一个 喝,我实在 告诉 你们,这人 不能 不 得 赏赐。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, ' 耶稣 吩咐 完了 十二个 门徒,就离开  那里,往 各城 去传道、 教训人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, ' 约翰 在 监 里听见 基督 所做的事,就打发 两个 门徒去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, '问他 说:「那将要来 的是 你吗?还是 我们等候 别人呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, ' 耶稣 回答 说:「你们去,把所 听见、 所看见 的事告诉 约翰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, '就是瞎子 看见, 瘸子 行走,长大痲疯的 洁净, 聋子 听见, 死人 复活, 穷人 有福音传给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, '凡 不 因 我 跌倒 的就 有 福了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, ' 他们走的时候,耶稣 就 对众人 讲论 约翰说:「你们从前出 到 旷野 是要看 什么呢?要看 风 吹动 的芦苇吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, '你们出去 到底 是要看 什么?要看穿 细软 衣服的人吗? 那穿 细软 衣服的人是 在 王 宫里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, '你们出去 究竟 是为什么?是要看 先知吗?我告诉 你们,是的, 他比先知 大多了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, '经 上 记著说:『 我 要差遣 我的 使者 在你 前 面 预备 道路』,所说的就是 这个人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, '我实在 告诉 你们,凡妇人 所生的,没有 一个兴起来 大过 施洗 约翰的;然而 天 国 里 最小的 比他 还大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, ' 从 施洗 约翰 的时候 到 如今,天 国 是努力进入的, 努力的人 就得著了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, '因为 众 先知 和 律法 说预言,到 约翰为止。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, ' 你们若 肯 领受,这人 就是 那 应当 来 的以利亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, '有 耳可听的,就应当听! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, ' 我可用什么 比 这 世代呢? 好像 孩童 坐 在 街市 上 招呼 同伴,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, '我们向你们 吹笛, 你们不 跳舞;我们向你们举哀, 你们不 捶胸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, ' 约翰 来了,也不 吃 也不 喝,人就 说 他是被鬼 附著的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, '人 子 来了,也吃 也 喝,人又 说 他是贪食 好酒 的人,是税吏 和 罪人 的朋友。但 智慧 之子总以 智慧 为是(有古卷:但智慧在行为上就显为是)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, '耶稣在 诸城 中行了 许多 异能, 那些城的人终不 悔改,就 在那时候 责备 他们,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, '「哥拉汛哪,你 有祸了!伯赛大啊,你 有祸了!因为 在 你们 中间所 行 的异能,若 行 在 泰尔、 西顿,他们早已 披 麻 蒙灰 悔改了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, '但 我告诉 你们,当 审判 的日子,泰尔、 西顿所受的, 比 你们 还容易受呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, ' 迦百农啊, 你 已经升 到 天上(或译:你将要升到天上吗),将来必坠落 阴间;因为 在 你 那里所行 的 异能,若 行 在 所多玛,它还可以 存 到 今日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, '但 我告诉 你们, 当 审判 的日子, 所多玛所受的, 比 你 还容易受呢!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, ' 那 时,耶稣 说:「父啊,天 地 的主,我感谢 你!因为 你将这些事 向 聪明 通达 人就藏起来,向婴孩 就 显出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, '父啊,是的,因为 你的 美意 本是 如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, '一切所有的,都是 我 父 交付 我的; 除了 父,没有人 知道 子;除了 子 和 子 所愿 意 指示 的,没有 人 知道 父。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, '凡 劳苦 担重担的 人可以到 我 这里来,我 就使你们 得安息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, ' 我 心 里柔和 谦卑,你们 当负 我的 轭, 学 我 的样式;这样,你们 心里 就必得享 安息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, '因为 我的 轭 是容易的, 我的 担子 是 轻省的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, ' 那 时,耶稣 在安息日 从 麦地 经过。 他的 门徒 饿了,就 掐起 麦穗 来 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, ' 法利赛人 看见,就对耶稣 说:「看哪,你的 门徒 做 安息日 不 可 做的事了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, ' 耶稣对他们 说:「 经上记著大卫 和 跟从 他 的人饥饿 之时 所做的事,你们没有 念过吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, '他怎么 进了 神 的殿, 吃了 陈设 饼,这 饼不 是 他 和 跟从 他 的人可以 吃得,惟 独 祭司才可以吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, '再者,律法 上所记的, 当安息日,祭司 在 殿 里犯了 安息日 还是 没有罪,你们没有 念过吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, '但 我告诉 你们, 在这里 有一人 比殿 更大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, '『我喜爱 怜恤, 不 喜爱祭祀。』 你们若 明白 这 话的意思,就不 将 无罪的 当作有罪的了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, '因为 人 子 是 安息日 的主。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, ' 耶稣离开  那地方,进了 一个会堂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, ' 那里有一个人 枯干了 一只手。 有人问 耶稣 说:「安息日 治病 可以不可以?」意思是要 控告 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, ' 耶稣说:「你们 中间 谁 有 一只 羊, 当安息日 掉 在 坑里,不 把牠 抓住, 拉上来呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, '人 比 羊 何等 贵重呢!所以,在安息日 做 善事 是可以的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, '于 是 对那人 说:「伸出 手来!」 他把手一伸,手就 复了 原,和那 只手一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, ' 法利赛人 出去,商 议 怎样 可以除灭 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, ' 耶稣 知道了,就离开  那里, 有许多 人 跟著 他。 他把其中有病的人 都 治好了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, '又 嘱咐 他们,不要 给 他 传名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, '这是要 应验 先知 以赛亚 的 话,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, '看哪!我的 仆人,我所 拣选、 所亲爱、 心里 所喜悦 的,我要将我的 灵 赐 给 他; 他必将公理 传给 外邦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, '他不 争竞,不 喧嚷;街 上 也没有 人 听见 他的 声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, '压伤的 芦苇,他不 折断; 将残的 灯火,他不 吹灭;等 他 施行 公理,叫 公理得胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, ' 外邦人 都要仰望 他的 名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, '当下,有人将一个被鬼附著、又瞎 又 哑 的人带 到耶稣那里,耶稣就 医治 他,甚至 那哑巴 又能说话,又 能看见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, ' 众人 都 惊奇, 说:「这 不 是 大卫 的子孙吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, '但 法利赛人 听见,就说:「这个人 赶 鬼,无 非是 靠著 鬼 王 别西卜啊。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, ' 耶稣知道 他们的 意念,就对他们 说:「凡 一国 自 相 纷争,就成为荒场; 一城 一家 自 相 纷争,必站立 不住; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, ' 若 撒但 赶逐 撒但,就是 自 相纷争, 他的 国 怎能 站得住呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, ' 我 若 靠著 别西卜 赶 鬼,你们的 子弟 赶 鬼又靠著 谁呢? 这样,他们 就要 断定你们的 是非。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, ' 我 若 靠著 神 的灵 赶 鬼,这就是 神 的国 临 到 你们了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, ' 人 怎 能 进 壮士 家 里, 抢夺 他的 家具呢?除非 先 捆住 那壮士, 才可以 抢夺 他的 家财。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, '不 与 我相合的,就是 敌 我的; 不 同 我 收聚的,就是分散的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, '所以 我告诉 你们:「人一切的 罪 和 亵渎的话 都可得赦免,惟独 亵渎 圣灵, 总不 得赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, ' 凡 说 话 干犯 人 子的, 还可得赦免;惟独 说话 干犯 圣 灵的, 今 世 来世 总不 得赦免。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, '「你们或 以为 树 好, 果子 也 好; 树 坏, 果子 也 坏;因为 看 果子 就可以知道 树。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, '毒蛇 的种类!你们既是 恶人,怎 能 说出 好话来呢?因为 心里 所充满的,口里 就说 出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, '善 人 从 他心里所存的 善 就发出 善来; 恶 人 从 他心里所存的 恶 就发出 恶来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, '我又 告诉 你们, 凡 人 所 说的 闲  话,当 审判 的日子,必要句句 供 出来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, '因为 要凭 你的 话 定你为义,也 要凭 你的 话 定你有罪。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, '当时,有几个 文士 和 法利赛人 对 耶稣 说:「夫子,我们愿 意 你 显个神迹 给我们看。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, ' 耶稣回答 说:「一个邪恶 淫乱 的世代 求 看神迹,除了 先知 约拿 的神迹以外,再 没有 神迹 给 他们看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, ' 约拿 三 日 三 夜 在 大鱼 肚腹中,人 子 也要 这样 三 日 三 夜 在 地 里头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, '当 审判的时候,尼尼微 人 要 起来 定这 世代 的罪,因为 尼尼微人听了 约拿 所传的 就悔改了。 看哪,在这里 有一人比约拿 更大! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, '当 审判的时候,南方 的女王 要 起来 定这 世代 的罪,因为 她从 地 极 而来,要听 所罗门 的智慧话。 看哪,在这里 有一人比所罗门 更大。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, '「 污 鬼 离了 人身,就在无水 之地 过来 过去,寻求 安歇之处,却 寻 不著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, '于 是 说:『我要回 到 我 所 出来 的屋里去。』 到了,就看见 里面空闲 ,打扫干净, 修饰好了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, '便 去 另 带了 七个 比自己 更恶的 鬼来, 都进去 住在 那里。 那 人 末后 的景况 比先前 更不好了。这 邪恶的 世代 也 要 如此。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, '耶稣 还 对众人 说话的时候,不料 他母亲 和 他 弟兄 站在 外边,要 与他 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, ' 有人 告诉 他说:「看哪,你 母亲 和 你 弟兄 站在 外边,要 与你 说话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, '他却 回答 那人 说:「谁 是 我的 母亲? 谁 是 我的 弟兄?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, '就 伸 手 指著 门徒,说:「看哪,我的 母亲, 我的 弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, ' 凡 遵行 我 天 父 旨意 的人,就是 我的 弟兄 姊妹 和 母亲了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, '当 那 一天,耶稣 从房子 里出来,坐 在 海边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, ' 有许多 人 到 他 那里聚集,他 只得 上 船 坐下, 众人 都 站 在 岸上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, ' 他用 比喻 对他们 讲 许多道理,说:「 有一个撒种的 出去 撒种; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, ' 撒 的时候,有 落 在 路旁的, 飞鸟 来 吃尽了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, ' 有 落 在 土 浅 石头地上的, 土 既 不 深, 发苗 最快, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, ' 日头 出来 一晒, 因为 没 有 根,就枯干了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, ' 有 落 在 荆棘里的, 荆棘 长起来, 把它 挤住了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, '又 有 落 在 好 土里的,就 结 实,有 一百倍的, 有 六十倍的, 有 三十倍的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, ' 有 耳可听的,就应当听!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, ' 门徒 进前来,问耶稣 说:「对众人 讲话,为什么 用 比喻呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, ' 耶稣回答 说:「因为 天 国 的奥秘 只叫 你们 知道, 不 叫 他们知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, ' 凡 有的,还要加给 他, 叫他有余 馀; 凡 没 有的,连 他所有的,也要夺去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, '所以 我用 比喻 对他们 讲,是因 他们看 也看 不见,听 也 听 不见,也不 明白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, ' 在他们身上,正应了 以赛亚 的预言, 说:你们听 是要听见,却 不 明白; 看 是要看见,却 不 晓得; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, '因为 这 百姓 油蒙了 心, 耳朵 发沉, 眼睛 闭著,恐怕 眼睛 看见, 耳朵 听见, 心里 明白, 回转过来,我就 医治 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, '「但 你们的 眼睛 是有福的,因为 看见了;你们的 耳朵 也是有福的,因为 听见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, ' 我实在 告诉 你们, 从前有许多 先知 和 义人 要 看 你们所看的,却 没有 看见, 要听 你们所听的,却 没有 听见。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, '「所以,你们 当听 这撒种 的比喻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, '凡 听见 天国 道理 不 明白的,那恶者 就来, 把所 撒 在 他 心里 的夺了去;这 就是 撒 在 路旁的了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, ' 撒 在 石头地上的,就是 人 听了 道, 当下 欢喜 领受, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, '只 因 心 里没 有 根,不过 是 暂时的,及至 为 道 遭了 患难,或是 受了逼迫,立刻 就跌倒了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, ' 撒 在 荆棘里的,就是 人 听了 道, 后来有世上 的思虑、 钱财 的迷惑 把道 挤住了, 不能结实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, ' 撒 在 好 地上的,就是 人 听 道 明白了, 后来 结实, 有 一百倍的, 有 六十倍的, 有 三十倍的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, '耶稣又 设 个比喻 对他们 说:「天 国 好像 人 撒 好 种 在 田里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, ' 及至 人 睡觉的时候,有 仇敌 来, 将稗子 撒 在 麦子 里 就 走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, ' 到长 苗 吐 穗 的时候, 稗子 也 显出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, ' 田主 的仆人 来 告诉他 说:『主啊,你不是 撒 好 种 在 田里吗? 从哪里 来 的稗子呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, ' 主人说:『这 是仇敌 做的。』 仆人 说:『 你要 我们去 薅出来吗?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, ' 主人说:『不必,恐怕 薅 稗子,连 麦子 也拔出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, '容 这两样 一齐长,等著 收割。 当 收割 的时候,我要对收割的人 说,先 将稗子 薅出来, 捆 成 捆,留著 烧;惟有 麦子 要收 在 仓里。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, '他又 设 个比喻 对他们 说:「天 国 好像 一粒 芥菜种, 有人 拿去 种 在 田里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, '这 原 是 百 种 里最小的, 等到 长起来,却 比各样的菜 都大,且 成了 树, 天上 的飞鸟 来 宿 在 它的 枝上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, '他又 对他们 讲 个比喻说:「天 国 好像 面 麺酵, 有妇人 拿来,藏 在 三 斗 面 麺里,直等 全 团 都发起来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, '这 都 是耶稣 用 比喻 对众人 说的话; 若不用 比喻,就不 对他们 说什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, '这是 要应验 先知 的话,说:我 要开  口 用 比喻,把创 世 以来 所隐藏 的事发明出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, '当下,耶稣离开  众人,进了 房子。 他的 门徒 进前来,说:「请把田间 稗子 的比喻 讲 给我们听。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, ' 他回答 说:「那撒 好 种 的就是 人 子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, ' 田地 就是 世界; 好 种 就是 天国 之子; 稗子 就是 那恶者 之子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, ' 撒 稗子 的仇敌 就是 魔鬼; 收割 的时候就是 世界 的末了; 收割的人 就是 天使。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, ' 将稗子 薅出来 用火 焚烧, 世界 的末了 也要 如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, '人 子 要差遣 使者, 把一切 叫人跌倒的 和 作 恶的,从 他 国 里挑出来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, ' 丢 在 火 炉里;在那里 必要 哀哭 切 齿了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, '那时,义人 在 他们 父 的国里,要发出光来,像 太阳一样。 有 耳可听的,就应当听!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, '「天 国 好像 宝贝 藏 在 地里,人 遇见了 就把它 藏起来, 欢欢喜喜地 去 变卖 一切 所有的, 买  这 块地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, '天 国 又 好像 买 卖 人 寻找 好 珠子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, ' 遇见 一颗 重价的 珠子,就去 变卖 他一切 所有的, 买 了 这颗珠子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, '天 国 又 好像 网 撒 在 海里, 聚拢 各样 水族, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, '网 既 满了,人就拉 上 岸来, 坐下,拣好的 收 在 器具里, 将不好的 丢 弃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, ' 世界 的末了 也要 这样。天使 要出来, 从 义人 中 把恶人 分别出来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, ' 丢 在 火 炉里;在那里 必要 哀哭 切 齿了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, '耶稣说:「这 一切 的话你们都明白了吗?」他们说:「我们明白了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, ' 他 说:「 凡 文士 受教作天 国 的门徒,就 像 一个家主 从 他 库 里拿出 新 旧的东西来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, ' 耶稣 说完了 这些 比喻,就离开  那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, ' 来 到 自己的 家乡,在 会堂 里教训 人,甚至 他们 都希奇, 说:「这人 从哪里 有这等 智慧 和 异能呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, '这 不 是 木匠 的儿子吗?他 母亲 不是 叫 马利亚吗? 他 弟兄们 不是叫雅各、 约西(有古卷:约瑟)、 西门、 犹大吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, ' 他 妹妹们 不 是 都 在 我们这里吗?这人 从哪里 有这一切 的事呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, '他们就厌弃他(厌弃他:原文是因 他 跌倒)。 耶稣 对他们 说:「大凡先知,除了 本 地 本家之外,没 有 不被人尊敬的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, ' 耶稣因为 他们 不信,就在那里 不 多 行 异能了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, ' 那 时,分封的王 希律 听见 耶稣 的名声, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, '就 对 臣仆 说:「这 是 施洗 的约翰 从 死 里复活, 所以 这些异能 从 他 里面发出来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, '起先,希律 为 他 兄弟 腓力 的妻子 希罗底的缘故,把约翰 拿住,锁 在 监里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, '因为 约翰 曾对他 说:「你 娶 这妇人 是不 合理的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, '希律就 想要 杀 他,只是怕 百姓,因为 他们以 约翰 为 先知。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, ' 到了 希律的 生日,希罗底 的女儿 在 众人面前 跳舞, 使希律 欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, ' 希律就起 誓,应许 随她所求 的 给 她。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, ' 女儿被 母亲 所使,就说:「请把施洗 约翰 的头 放在 盘子里,拿来 给 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, ' 王 便忧愁,但因 他所起的誓,又 因同席的人,就吩咐 给她; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, '于 是 打发人去,在 监 里斩了 约翰, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, ' 把 头 放在 盘子里, 拿来 给了 女子; 女子拿去给 她 母亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, ' 约翰的 门徒 来,把尸首 领去 埋葬了,就 去 告诉 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, ' 耶稣 听见了,就上 船 从那里 独自 退 到 野 地 里去。 众人 听见,就从 各城 里步行 跟随 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, ' 耶稣出来,见 有许多的 人,就 怜悯 他们, 治好了 他们的 病人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, ' 天将晚的时候, 门徒 进前来,说:「这是 野 地, 时候 已经 过了,请叫众人 散开 ,他们好 往 村子 里去,自己 买  吃的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, ' 耶稣 说:「不 用 他们去,你们 给 他们 吃吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, ' 门徒说:「我们这里 只 有 五个 饼, 两条 鱼。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, ' 耶稣说:「拿 过来 给我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, '于 是 吩咐 众人 坐 在 草地上,就拿著 这五个 饼, 两条 鱼,望著 天 祝福, 擘开  饼,递给 门徒,门徒 又 递给众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, ' 他们都 吃,并且 吃饱了; 把剩下的 零碎 收拾起来,装满了 十二个 篮子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, ' 吃的 人,除了 妇女 孩子,约 有 五千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, ' 耶稣随即 催 门徒 上 船, 先渡 到 那边去,等 他叫众人 散开 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, ' 散了 众人以后,他就独自 上 山 去祷告。 到了 晚上,只有他一人 在 那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, ' 那时 船在海中,因 风 不顺,被 浪 摇撼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, ' 夜里 四 更天,耶稣在 海 面上走,往 门徒 那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, ' 门徒 看见 他 在 海 面上走,就惊慌了,说:「 是 个鬼怪!」便 害怕,喊叫起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, ' 耶稣 连忙 对他们 说:「你们放心,是 我,不要 怕!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, ' 彼得 说:「主,如果 是 你,请叫 我 从水 面上 走 到 你那里去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, ' 耶稣说:「你来吧。」彼得 就 从 船 上下去,在 水 面上走, 要到 耶稣 那里去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, '只 因见 风 甚大,就害怕, 将要 沉下去,便喊著 说:「主啊,救 我!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, ' 耶稣 赶紧 伸 手 拉住 他, 说:「你这小信的人哪,为什么 疑惑呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, ' 他们 上了 船,风 就住了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, ' 在 船 上的人都拜 他,说:「你真 是 神 的儿子了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, ' 他们过了海,来 到 革尼撒勒 地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, ' 那 里 的人 一认出 是耶稣,就打发人 到 周围地方去, 把所有的 病 人带到 他那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, ' 只 求 耶稣 准他们摸 他的 衣裳 䍁子; 摸著的 人就都好了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, '那时,有法利赛人 和 文士 从 耶路撒冷 来 见耶稣,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, '「你的 门徒 为什么 犯 古人 的遗传呢?因为 吃 饭 的时候,他们不 洗 手。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, ' 耶稣回答 说:「你们 为什么 因著 你们的 遗传 犯 神 的诫命呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, ' 神 说:『当孝敬 父 母』;又说:『咒骂 父 母的,必治 死他。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, '你们 倒 说:『无论 何人 对父 母 说: 我 所当奉给 你的 已经作了供献, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, '他就可以不 孝敬 父母。』这就是 你们 藉 借著 遗传,废了 神的 诫命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, '假冒为善的人哪,以赛亚 指著 你们 说的预言 是不错的。他说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, '这 百姓 用嘴唇 尊敬 我, 心 却 远 离 我; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, '他们将人的 吩咐 当作道理 教导人,所以 拜 我 也是枉然。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, '耶稣就 叫了 众人来,对他们 说:「你们要听,也要 明白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, '入 口 的不能 污秽 人, 出 口 的 乃能污秽 人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, '当时,门徒 进前来 对他 说:「 法利赛人 听见 这话,不服(原文是跌倒),你知道吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, ' 耶稣回答 说:「凡 栽种的物, 若不是 我 天 父 栽种的,必要拔出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, '任凭 他们吧!他们是 瞎眼 领路的; 若是 瞎子 领 瞎子,两个人 都要掉 在 坑里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, ' 彼得 对耶稣 说:「请将这 比喻 讲 给我们听。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, ' 耶稣说:「你们 到如今 还 不明白吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, '岂不 知 凡 入 口的,是运 到 肚子里,又 落 在 茅厕里吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, '惟独 出 口的,是从 心里 发出来的,这 才污秽 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, '因为 从 心里 发出来的,有恶 念、凶杀、奸淫、苟合、偷盗、妄证、谤讟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, '这 都是 污秽 人的;至于  不洗 手 吃饭,那却不 污秽 人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, ' 耶稣 离开  那里,退 到 泰尔、 西顿 的境内去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, ' 有一个迦南 妇人,从 那 地方 出来,喊著 说:「主啊,大卫的 子孙,可怜 我!我 女儿 被鬼附 得甚苦。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, '耶稣却 一言 不 答。 门徒 进前来,求 他 说:「 这妇人在我们 后头 喊叫,请打发她 走吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, ' 耶稣说:「我奉差遣 不 过是 到 以色列 家 迷失的 羊那里去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, ' 那妇人来 拜 他,说:「主啊,帮助 我!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, ' 他回答 说:「 不 好 拿 儿女的 饼 丢 给狗吃。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, ' 妇人说:「主啊,不错;但是 狗 也 吃 牠 主人 桌子 上 掉下来 的碎渣儿。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, ' 耶稣 说:「妇人,你的 信心 是大的!照 你所要的,给你 成全了吧。」从 那 时候,她 女儿 就 好了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, ' 耶稣 离开  那地方,来到 靠近 加利利 的海边,就 上 山 坐下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, ' 有许多 人 到 他那里,带著 瘸子、瞎子、哑巴、有残疾的,和 好些 别的病人, 都放 在 他 脚前;他就 治好了 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, '甚至 众人 都希奇;因为看见 哑巴 说话,残疾的 痊愈, 瘸子 行走, 瞎子 看见, 他们就归荣耀 给以色列的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, ' 耶稣 叫 门徒来,说:「我怜悯 这众人;因为 他们同我 在 这里已经 三 天,也 没 有 吃 的了。 我不 愿 意 叫他们 饿著 回去,恐怕 在 路上 困乏。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, ' 门徒 说:「我们 在 这野地,哪里 有这么多的 饼 叫 这许多 人 吃饱呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, ' 耶稣 说:「你们有 多少 饼?」 他们说:「有七个,还有 几条 小鱼。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, '他就 吩咐 众人 坐 在 地上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, ' 拿著 这七个 饼 和 几条鱼,祝谢了,擘开 , 递给 门徒;门徒 又 递给众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, ' 众人都 吃,并且 吃饱了, 收拾 剩下的 零碎,装满了 七个 筐子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, ' 吃的人,除了 妇女 孩子,共有 四千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, ' 耶稣叫众人 散去,就上 船, 来 到 马加丹 的境界。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, '法利赛人 和 撒都该人 来 试探耶稣,请 他 从 天上 显 个神迹 给他们看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, ' 耶稣回答 说:「 晚上 天 发红,你们就说:『天必要晴。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, ' 早晨 天 发红,又发黑,你们就说:『今日 必有风雨。』你们知道 分辨 天上 的气色,倒 不 能 分辨这时候 的神迹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, '一个邪恶 淫乱 的世代 求 神迹, 除了 约拿 的神迹以外,再没有 神迹 给 他看。」耶稣就 离开  他们 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, ' 门徒 渡 到 那边去,忘了 带 饼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, ' 耶稣 对他们 说:「你们要谨慎, 防备 法利赛人 和 撒都该人 的酵。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, ' 门徒彼此 议论 说:「这是因为 我们没有 带 饼吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, ' 耶稣 看出来,就说:「你们这小信的人,为什么 因为 没 有 饼 彼此 议论呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, '你们还不 明白吗?不 记得 那五个 饼 分给五千人、又 收拾了 多少 篮子的零碎吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, '也不 记得那七个 饼 分给四千人、又 收拾了 多少 筐子的零碎吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, '我对你们 说:『 要防备 法利赛人 和 撒都该人 的酵』,这话不是 指著 饼说的,你们怎么 不 明白呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, '门徒这才 晓得 他说 的 不是 叫他们防备 饼 的酵,乃是 防备 法利赛人 和 撒都该人 的教训。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, ' 耶稣 到了 凯撒利亚•腓立比 的境内,就问 门徒 说:「人 说我─(有古卷没有我字)─人 子 是 谁?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, ' 他们说:「有人说是 施洗的 约翰; 有人 说是以利亚;又 有人 说是耶利米 或是 先知 里的一位。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, '耶稣 说:「 你们 说 我 是 谁?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, ' 西门•彼得 回答 说:「你 是 基督,是永生 神 的儿子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, ' 耶稣 对他 说:「西门•巴•约拿,你是 有福的!因为 这不是 属血 肉 的指示 你的,乃是 我 在 天上 的父指示的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, ' 我还 告诉 你, 你 是 彼得, 我要把我的 教会 建造 在 这 磐石上; 阴间的权柄(权柄:原文是门),不能 胜过 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, '我要把天 国 的钥匙 给 你, 凡 你在 地上 所捆绑的,在 天上 也要 捆绑; 凡 你在 地上 所释放的,在 天上 也要 释放。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, '当下,耶稣嘱咐 门徒, 不可 对人说 他 是 基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, '从 此,耶稣 才 指示 门徒, 他 必须 上 耶路撒冷 去, 受 长老、 祭司长、 文士 许多的 苦,并且 被杀, 第三 日 复活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, '彼得 就 拉著 他, 劝 他 说:「主啊,万不可如此!这事 必不 临到 你身上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, ' 耶稣转过来,对彼得 说:「撒但,退 我 后边去吧!你是 绊 我脚的;因为 你不 体贴 神 的意思,只 体贴人的意思。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, '于 是 耶稣 对 门徒 说:「若有 人 要 跟从 我,就当舍 己, 背起 他的 十字架 来跟从 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, '因为,凡 要 救 自己 生命(生命:或译灵魂;下同)的,必丧掉 生命; 凡 为 我 丧掉 生命的,必得著 生命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, ' 人 若 赚得 全 世界, 赔上 自己的 生命,有什么 益处呢?人 还能 拿 什么 换 生命呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, ' 人 子 要 在 他 父的 荣耀里,同著 众使者 降临; 那时候,他要照 各人的 行为 报应 各人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, '我实在 告诉 你们, 站 在这里的,有人 在没 尝 死 味以前 必看见 人 子 降临 在 他的 国里。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, ' 过了 六 天,耶稣 带著 彼得、 雅各,和 雅各的 兄弟 约翰, 暗暗地 上了 高 山, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, '就 在他们 面前 变了形像, 脸面 明亮 如 日头, 衣裳 洁白 如 光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, ' 忽然,有摩西、 以利亚 向他们 显现,同 耶稣 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, ' 彼得 对耶稣 说:「主啊,我们 在 这里 真好!你若 愿 意,我就在这里 搭 三座 棚,一座 为你, 一座 为摩西, 一座 为以利亚。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, ' 说话 之间,忽然 有一朵光明的 云彩 遮盖 他们,且 有声音 从 云彩里出来,说:「这 是 我的 爱 子,我所 喜悦的。你们要听 他!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, ' 门徒 听见,就俯伏 在地, 极其 害怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, ' 耶稣 进前来,摸 他们, 说:「起来, 不要 害怕!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, ' 他们 举 目 不 见一人,只 见耶稣在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, ' 下 山的时候,耶稣 吩咐 他们 说:「人 子 还没有 从 死 里复活,你们不要 将所看见的 告诉人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, ' 门徒 问 耶稣 说:「文士 为什么 说 以利亚 必须 先 来?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, ' 耶稣回答 说:「以利亚 固然 先来,并 要复兴 万事; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, '只是 我告诉 你们, 以利亚 已经 来了,人却 不 认识 他,竟 任 意 待 他。人 子 也 将要 这样 受 他们的 害。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, '门徒 这才 明白 耶稣所说 的是指著 施洗的 约翰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, ' 耶稣和门徒到了 众人那里,有一个人 来 见耶稣,跪下, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, ' 说:「主啊,怜悯 我的 儿子! 他害 癫痫 的病 很苦, 屡次 跌 在 火里, 屡次 跌在 水里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, ' 我带 他 到你 门徒那里,他们却 不 能 医治 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, ' 耶稣 说:「嗳!这又不信 又 悖谬的 世代啊,我在 你们 这里要到 几时呢?我忍耐 你们 要到 几时呢?把他 带到 我 这里来吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, ' 耶稣 斥责 那鬼,鬼 就 出来;从 此 孩子 就 痊愈了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, ' 门徒 暗暗地 到 耶稣跟前,说:「我们 为什么 不 能 赶出 那鬼呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, ' 耶稣说:「是因 你们的 信心小。 我实在 告诉 你们,你们若 有 信心,像 一粒 芥菜种,就是对这座 山 说:『你从这边 挪到 那边』,它也 必挪去;并且 你们 没有 一件不能做的事了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, '至于  这 一类的鬼,若不 祷告、 禁食,他就不 出来(或译:不能赶他出来)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, ' 他们 还住 在 加利利的时候, 耶稣 对门徒 说:「 人 子 将要 被交 在 人 手里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, ' 他们要杀害 他, 第三 日 他要复活。」门徒就 大大地 忧愁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, ' 到了 迦百农,有收 丁税 的人来 见彼得, 说:「你们的 先生 不 纳 丁税(丁税约有半块钱)吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, '彼得说:「纳。」 他进了 屋子,耶稣 先 向他 说:「西门,你的 意思 如何?世上 的君王 向 谁 征收 关税、 丁税?是向 自己的 儿子呢? 是向 外人呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, ' 彼得说:「是向 外人。」耶稣 说:「既然如此,儿子 就可以 免税了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, '但 恐怕触犯(触犯:原文是绊倒)他们,你且往 海 边去 钓鱼, 把先 钓上来 的鱼 拿起来, 开 了 牠的 口,必得 一块钱,可以 拿去 给 他们,作 你 我的税银。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, ' 当 时,门徒 进前来,问耶稣 说:「 天 国 里谁 是 最大的?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, '耶稣便 叫 一个小孩子来,使他 站 在 他们 当中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, ' 说:「我实在 告诉 你们,你们若 不 回转, 变成 小孩子 的样式,断不得 进 天 国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, '所以,凡 自己 谦卑 像 这 小孩子的,他 在 天 国 里就是 最大的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, ' 凡 为 我的 名 接待 一个 像这 小孩子的,就是接待 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, '「 凡 使这 信 我 的一个 小子 跌倒的, 倒不如 把大磨石 拴 在 这人 的颈项上, 沉 在 深 海里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, '这世界 有祸了,因为 将人绊倒; 绊倒 人的事 是免不了的,但 那 绊倒 人 的有祸了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, ' 倘若 你 一只手,或是 一只脚,叫你跌倒,就砍下来 丢掉。你 缺一只手,或是 一只脚,进入 永生, 强 如 有 两 手 两 脚 被丢 在 永 火里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, ' 倘若 你 一只眼 叫你 跌倒,就把它 剜出来 丢掉。你 只有一只眼 进 入 永生, 强 如 有 两只 眼 被丢 在 地狱的 火里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, '「你们要小心,不可 轻看 这 小子 里的一个; 我告诉 你们, 他们的 使者 在 天上,常 见 我 天 父 的面。(有古卷加: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, ' 人 子 来,为要拯救 失丧的人。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, '一个 人 若 有 一百只 羊, 一只 走迷了路,你们的 意思 如何?他岂不 撇下 这九十九只,往 山 里去 找 那只 迷路的羊吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, ' 若 是 找著了,我实在 告诉 你们, 他为 这一只羊 欢喜,比 为 那 没有 迷路 的九十九 只欢喜还大呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, '你们 在 天上 的父 也是 这样,不 愿 意 这 小子 里失丧 一个。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, '「 倘若 你的 弟兄 得罪 你,你就去,趁著只有 他 和 你 在一处的时候,指出他 的错来。他若 听 你,你便得了 你的 弟兄; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, ' 他若 不 听,你 就另外 带 一 两个 人同去,要 凭 两 三 个人的口 作见证,句句 都 可定准。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, ' 若是 不听 他们,就告诉 教会; 若是 不听 教会,就 看他 像 外邦人 和 税吏一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, '「我实在 告诉 你们,凡 你们在 地上 所捆绑的,在 天上 也要 捆绑; 凡 你们在 地上 所释放的,在 天上 也要 释放。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, '我又 告诉 你们, 若是 你们 中间有两个 人在 地上 同心合意地 求 什么 事,我 在 天上 的父 必为 他们 成全。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, '因为 无论在哪里,有 两 三个 人奉 我的 名 聚会,那里 就有我 在 他们 中间。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, '那时,彼得 进前来,对耶稣说:「主啊,我 弟兄 得罪 我, 我当饶恕 他 几次呢?到 七次可以吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, '耶稣 说:「我对你 说,不是 到 七次,乃是 到 七十个 七次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, ' 天 国 好像 一个 王 要 和 他 仆人 算 帐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, ' 才 算的时候,有人带了 一个 欠 一千万银子 的来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, '因为 他 没 有 什么偿还之物,主人 吩咐 把他 和 他妻子 儿女,并 一切 所有 的 都卖了 偿还。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, '那仆人 就 俯伏 拜 他,说:『主啊,宽容 我, 将来我都 要还清。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, '那 仆人 的主人 就 动了慈心,把他 释放了,并且 免了 他的 债。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, '「 那 仆人 出来,遇见 他的 一个 同伴 欠 他 十两银子,便 揪著 他,掐住他的喉咙,说:『你把所欠 的 还我!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, '他的 同伴 就 俯伏 央求 他,说:『宽容 我吧, 将来我必还 清。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, ' 他不 肯,竟 去 把他 下 在 监里,等 他还了 所欠的债。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, ' 众同伴 看见 他所做的事 就甚 忧愁, 去 把这事 都 告诉了 主人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, '于 是 主人 叫了 他来,对他 说:『你这恶 奴才! 你央求 我,我就把你 所欠的 都 免了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, '你 不 应当 怜恤 你的 同伴,像 我 怜恤 你吗?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, ' 主人 就 大怒,把他 交给 掌刑的,等 他 还 清 了所欠的债。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, '你们 各人 若 不 从 心里 饶恕 你的 弟兄,我 天 父 也要 这样 待 你们了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, ' 耶稣 说完了 这些 话,就离开  加利利, 来 到 犹太 的境界 约旦河 外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, ' 有许多人 跟著 他,他就 在那里 把他们 的病人治好了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, ' 有法利赛人 来 试探 耶稣, 说:「人 无论什么 缘故 都可以 休 妻吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, ' 耶稣回答 说:「 那 起初 造人的,是造 男 造女, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, '并且 说:『因 此,人 要离开  父 母, 与 妻子 连合, 二人 成为 一 体。』这经你们没有念过吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, '既然如此,夫妻不再 是 两个人,乃是 一 体的了。 所以, 神 配合的,人 不可 分开 。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, '法利赛人说:「这样,摩西 为什么 吩咐 给 妻子休 书,就 可以休 她呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, '耶稣说:「 摩西 因为 你们的 心硬,所以许 你们 休 妻,但 起初 并不 是 这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, ' 我告诉 你们, 凡 休 妻 另 娶的,若不是 为 淫乱的缘故,就是犯奸淫了;有人娶那被休的妇人,也是犯奸淫了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, ' 门徒 对耶稣 说:「人 和 妻子 既 是 这 样,倒不如 不 娶。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, ' 耶稣 说:「这 话 不是 人都 能领受的,惟独 赐给 谁,谁才能领受。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, '因为 有 生 来是 阉人,也 有 被 人 阉的,并 有 为 天 国 的缘故自 阉的。这话谁能 领受 就可以领受。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, '那时,有人带著 小孩子 来见耶稣,要 耶稣给他们 按 手 祷告,门徒 就 责备 那些人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, ' 耶稣 说:「让 小孩子 到 我 这里来, 不要 禁止 他们;因为 在天 国的,正是 这样的人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, ' 耶稣给他们 按 手,就离开  那地方去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, ' 有一个 人来 见耶稣,说:「夫子(有古卷:良善的夫子),我该做 什么 善事 才能得 永 生?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, ' 耶稣对他 说:「你为什么 以 善事 问 我呢?只有一位 是 善的(有古卷:你为什么称我是良善的?除了 神以外,没有一个良善的)。 你若 要 进 入 永生,就当遵守 诫命。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, '他说:「什么诫命?」 耶稣 说:「就是不可 杀人;不可 奸淫;不可 偷盗;不可 作假见证; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, '当孝敬 父 母;又 当爱 人 如 己。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, '那少年人 说:「这 一切 我都遵守了,还 缺少 什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, '耶稣 说:「你若 愿 意 作 完全人,可去 变卖 你 所有的, 分给 穷人,就 必有 财宝 在 天上;你还要 来 跟从 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, ' 那少年人 听见 这话,就忧忧愁愁地 走了,因为 他 的 产业 很多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, ' 耶稣 对 门徒 说:「我实在 告诉 你们, 财主 进 天 国 是难的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, ' 我又 告诉 你们,骆驼 穿 过 针的 眼,比 财主 进 神的 国 还容易呢!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, ' 门徒 听见这话,就希奇 得很,说:「这样 谁 能 得救呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, ' 耶稣 看著 他们,说:「在 人 这 是 不能的, 在 神 凡事 都能。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, '彼得 就 对他 说:「看哪,我们 已经撇下 所有的 跟从 你, 将来我们 要得 什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, ' 耶稣 说:「我实在 告诉 你们, 你们 这 跟从 我的人,到 复兴 的时候,人 子 坐 在 他 荣耀的 宝座上,你们 也要 坐 在 十二个 宝座上,审判 以色列 十二个 支派。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, ' 凡 为 我的 名 撇下 房屋,或是 弟兄、 姊妹、 父亲、 母亲、(有古卷加:妻子、) 儿女、 田地的,必要得著 百倍,并且 承受 永 生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, '然而,有许多 在前的,将要 在后; 在后的,将要在前。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, '「因为 天 国 好像 家主 清早 去 雇 人 进 他的 葡萄园做工, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, ' 和 工人 讲定 一天 一钱银子,就打发 他们 进 葡萄园去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, ' 约 在巳初 出去,看见 市 上 还有 闲  站的人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, ' 就对他们 说:『你们 也 进 葡萄园 去, 所 当给的,我必给 你们。』他们也进去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, ' 约 在午正 和 申初 又 出去,也是这样 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, ' 约 在酉初 出去,看见 还有人 站在那里,就 问他们 说:『你们为什么 整 天 在这里 闲  站呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, '他们说:『因为 没有人 雇 我们。』他说:『你们 也 进 葡萄园 去。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, ' 到了 晚上,园 主 对 管事的 说:『叫 工人都来, 给 他们 工钱,从 后来 的起,到 先来的为止。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, ' 约 在酉初 雇的人来了,各人 得了 一钱银子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, '及至 那先 雇的来了,他们以为 必要多 得; 谁知也是 各 得 一钱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, ' 他们得了,就埋怨 家主 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, '『我们 整天 劳 苦 受热,那 后来 的只做了 一 小时, 你竟叫 他们 和我们 一样吗?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, ' 家主回答 其中的一人 说:『朋友,我不 亏负 你,你与我 讲定 的不是 一钱银子吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, '拿 你的 走吧! 我给 那 后来的 和 给你 一样,这是我愿 意的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, '我的 东西难道 不 可 随 我的 意思 用吗?因为 我 作 好人, 你 就 红了 眼吗?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, '这样,那在后的,将要在 前; 在前的,将要在后了。(有古卷加:因为 被 召 的人多, 选上的 人少。)」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, ' 耶稣 上 耶路撒冷 去的时候,在 路 上把十二个 门徒 带 到 一边, 对他们 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, '「看哪,我们上 耶路撒冷 去, 人 子 要被交给 祭司长 和 文士。 他们要定 他 死罪, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, '又 交给 外邦人, 将他 戏弄, 鞭打, 钉在十字架上; 第三 日 他要复活。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, '那时,西庇太 儿子 的母亲 同 她 两个儿子 上前来 拜 耶稣, 求 他 一件事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, ' 耶稣说:「你要 什么呢?」她说:「愿  你叫 我 这 两个 儿子 在 你 国里,一个 坐 在 你 右边, 一个 坐在 你 左边。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, ' 耶稣 回答 说:「你们不 知道 所求 的是什么; 我 将要 喝 的杯,你们能 喝吗?」他们说:「我们能。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, '耶稣说:「我 所喝的杯,你们必要 喝;只是 坐 在 我的左 右,不 是 我 可以赐 的,乃是 我 父 为谁 预备的,就赐给谁。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, ' 那十个 门徒听见,就恼怒 他们弟兄 二人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, ' 耶稣 叫了 他们来,说:「你们知道 外邦人 有君王 为主治理 他们, 有大臣 操权管束 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, '只是在 你们中间,不可 这样; 你们 中间 谁 愿  为 大,就必作 你们的 用人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, ' 谁 愿  为 首,就必作 你们的 仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, '正如 人 子 来,不是 要受人的服事,乃是 要服事人,并且 要舍 命,作 多人 的赎价。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, ' 他们 出 耶利哥的时候,有极 多的人 跟随 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, ' 有两个 瞎子 坐 在 路旁,听说 是 耶稣 经过,就喊著 说:「主啊,大卫 的子孙,可怜 我们吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, ' 众人 责备 他们, 不许他们作声;他们却 越发 喊著 说:「主啊,大卫 的子孙,可怜 我们吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, '耶稣 就 站住,叫他们 来, 说:「要 我为你们 做 什么?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, '他们说:「主啊,要 我们的 眼睛 能看见!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, ' 耶稣 就动了慈心,把他们的 眼睛 一摸, 他们立刻 看见,就 跟从了 耶稣。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, ' 耶稣和门徒将近 耶路撒冷, 到了 伯法其,在 橄榄 山那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, '耶稣就 打发两个门徒,对他们 说:「你们 往 对面 村子 里去, 必 看见 一匹驴 拴在那里,还有 驴驹 同在一处;你们解开 ,牵 到我这里来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, ' 若 有人 对你们 说 什么,你们就说:『主 要 用 牠。』 那人必立时 让你们牵来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, ' 这事 成就 是要 应验 先知 的话,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, '要对锡安的居民(原文是女子)说:看哪,你的 王 来到 你这里,是温柔的,又 骑著 驴,就是 骑著 驴 驹 子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, '门徒 就 照 耶稣 所吩咐 的去 行, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, '牵了 驴 和 驴驹来, 把自己的衣服 搭 在上面, 耶稣就骑 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, ' 众人 多半 把 衣服 铺 在 路上;还 有人 砍下 树 枝 来 铺 在 路上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, ' 前行 后随 的众人 喊著 说:和散那(原有求救的意思,在此是称颂的话)归于 大卫的 子孙!奉 主 名 来 的是应当称颂的!高高 在上 和散那! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, '耶稣 既 进了 耶路撒冷,合 城 都惊动了,说:「这 是 谁?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, ' 众人 说:「这 是 加利利 拿撒勒 的先知 耶稣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, ' 耶稣 进了 神的殿, 赶出 殿 里 一切 做买  卖的人, 推倒 兑换银钱之人 的桌子,和 卖 鸽子 之人的凳子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, ' 对他们 说:「经上记著说:我的 殿 必称为 祷告 的殿,你们 倒 使它 成为 贼 窝了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, ' 在 殿 里有瞎子、 瘸子 到 耶稣跟前,他就 治好了 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, ' 祭司长 和 文士 看见 耶稣所 行 的奇事,又 见小孩子 在 殿 里喊著 说:「和散那 归于 大卫的 子孙!」就甚恼怒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, ' 对他 说:「这些人 所 说的,你听见了吗?」 耶稣 说:「是的。经上说『你从 婴孩 和 吃奶的 口 中完全了 赞美』的话,你们没有 念过吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, '于 是 离开  他们,出 城 到 伯大尼 去, 在那里 住宿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, ' 早晨 回 城的时候,他饿了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, ' 看见 路 旁 有一棵 无花果树,就走 到 跟前, 在 树 上找 不著什么,不过 有叶子,就 对树 说:「从今以后, 你 永 不 结 果子。」那无花果树 就 立刻 枯干了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, ' 门徒 看见了,便希奇 说:「无花果树 怎么 立刻 枯干了呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, '耶稣 回答 说:「我实在 告诉 你们,你们若 有 信心, 不 疑惑,不 但 能行 无花果树上所行的事,就是 对这座 山 说:『你挪开 此地, 投 在 海里!』也必成就。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, ' 你们祷告,无论 求 什么,只要信,就必得著。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, ' 耶稣 进了 殿,正教训人的时候,祭司长 和 民间 的长老 来 问他 说:「你仗著 什么 权柄 做 这些事? 给 你 这 权柄 的是谁呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, ' 耶稣 回答 说:「我也要 问 你们 一句 话, 你们若 告诉 我,我就 告诉 你们 我仗著 什么 权柄 做 这些事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, '约翰的 洗礼 是 从哪里来的?是从 天上来的? 是从 人间来的呢?」 他们彼此 商议 说:「我们若 说『从 天上来』,他必对我们 说:『这样,你们为什么 不 信 他呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, ' 若 说『从 人间来』,我们又怕 百姓,因为 他们都 以 约翰 为 先知。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, '于 是 回答 耶稣 说:「我们不 知道。」 耶稣 说:「我 也不 告诉 你们 我仗著 什么 权柄 做 这些事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, '又说:「一个人 有 两个 儿子。 他来 对大儿子 说:『我儿,你今天 到 葡萄园 里去 做工。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, ' 他回答 说:『我不去』, 以后 自己懊悔,就去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, '又 来 对小儿子 也是这样 说。 他回答 说:『父啊,我去』,他却 不 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, '你们想, 这两个 儿子是哪一个 遵行 父 命呢?」他们说:「大儿子。」耶稣 说:「我实在 告诉 你们, 税吏 和 娼妓 倒比你们 先 进 神的 国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, '因为 约翰 遵著 义 路 到 你们 这里来,你们却 不 信 他;税吏 和 娼妓 倒 信 他。 你们 看见了,后来 还是不 懊悔 去信 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, '「你们再听 一个 比喻:有 个 家主 栽了 一个葡萄园, 周围圈上 篱笆, 里面 挖了 一个压酒池, 盖了 一座楼, 租给 园户,就 往外国去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, ' 收果子 的时候 近了,就打发 仆人 到 园户 那里去收 果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, ' 园户 拿住 仆人,打了 一个, 杀了 一个, 用石头打死 一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, '主人又 打发 别的 仆人去,比先前 更多;园户还是 照样 待 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, ' 后来 打发 他的 儿子 到 他们那里去,意思说:『他们必尊敬 我的 儿子。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, '不料,园户 看见 他儿子,就彼此 说:『这 是 承受产业的。来吧,我们杀 他, 占 他的 产业!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, '他们就 拿住 他,推出 葡萄园 外, 杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, ' 园 主 来 的时候 要怎样 处治 这些 园户呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, '他们说:「要下毒手 除灭 那些 恶人, 将葡萄园 另 租给 那 按著 时候 交 果子 的园户。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, '耶稣 说:「经 上写著:匠人 所 弃的 石头 已作了 房角 的头块石头。这 是 主 所做的, 在 我们 眼 中看为 希奇。这经你们没有 念过吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, '所以 我告诉 你们, 神 的国 必从 你们 夺去, 赐给 那能结 果子 的百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, ' 谁掉 在 这 石头上,必要跌碎; 这石头掉 在 谁的身上,就要把谁 砸得稀烂。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, ' 祭司长 和 法利赛人 听见 他的 比喻,就看出 他是指著 他们 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, ' 他们想要 捉拿 他,只是怕 众人,因为 众人以 他 为 先知。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, ' 耶稣 又 用 比喻 对他们 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, '「天 国 好比 一个 王 为他 儿子 摆设 娶亲的筵席, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, '就 打发 仆人去,请 那些被召的人 来赴 席,他们却 不 肯 来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, '王又 打发 别的 仆人,说:『你们告诉 那被召的人, 我的 筵席 已经预备好了, 牛 和 肥畜 已经宰了, 各样 都齐备,请你们来 赴 席。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, ' 那些人不理 就走了;一个 到 自己 田里去; 一个 做买 卖去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, ' 其余 馀的 拿住 仆人,凌辱他们, 把他们杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, '王 就 大怒, 发 兵 除灭 那些 凶手, 烧毁 他们的 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, '于 是 对 仆人 说:『 喜筵 已经 齐备,只是 所召的人 不 配。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, '所以 你们要往 岔路口 上去, 凡 遇见的,都召来 赴 席。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, ' 那些 仆人 就出去,到 大路上,凡 遇见的,不论 善 恶 都 召聚了来, 筵席上 就坐满了 客。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, ' 王 进来 观看 宾客,见 那里 有一个 没有 穿 礼 服的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, '就 对他 说:『朋友,你到这里 来 怎么 不 穿 礼 服呢?』 那人无言可答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, '于 是 王 对使唤的人 说:『捆起 他的 手 脚来,把他 丢 在 外边的 黑暗里;在那里 必要 哀哭 切 齿了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, '因为 被召 的人 多, 选上 的人少。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, '当时,法利赛人 出去 商议,怎样 就著 耶稣的话 陷害 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, '就 打发 他们的 门徒 同 希律党的人 去见耶稣,说:「夫子,我们知道 你是 诚实人,并且 诚诚实实 传 神的 道, 什么人 你 都不 徇情面,因为 你不 看 人的 外貌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, ' 请告诉 我们,你的 意见 如何?纳 税 给凯撒 可以 不可以?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, ' 耶稣 看出 他们的 恶意,就说:「假冒为善的人哪,为什么 试探 我? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, '拿一个上税的 钱 给我 看!」他们就 拿 一个银钱 来给他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, ' 耶稣说:「这 像 和 这号 是谁的?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, '他们说:「是凯撒的。」 耶稣说:「这样,凯撒的 物 当归 给凯撒; 神的 物当归给 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, ' 他们听见 就希奇, 离开  他 走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, '撒都该人 常说 没 有 复活的事。 那 天,他们来 问 耶稣 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, '「夫子,摩西 说:『人 若 死了,没 有 孩子,他 兄弟 当娶 他的 妻, 为 哥哥 生子 立后。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, '从前,在 我们 这里有 弟兄 七人, 第一个 娶了妻,死了, 没 有 孩子,撇下 妻子 给 兄弟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, '第二、 第三、直到 第七个,都 是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, ' 末后,妇人 也死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, '这样,当 复活的时候,她是 七个 人中哪一个 的妻子呢?因为 他们都 娶过 她。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, '耶稣 回答 说:「你们错了;因为不 明白 圣经,也不晓得 神的 大能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, ' 当 复活的时候,人也不 娶 也不 嫁,乃 像 天上 的使者一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, ' 论到 死人 复活, 神 在经上向你们 所说的,你们没有 念过吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, '他说:『我 是 亚伯拉罕的 神, 以撒的 神, 雅各的 神。』 神不 是 死人的 神,乃是 活人的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, ' 众人 听见这话,就希奇 他的 教训。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, ' 法利赛人 听见 耶稣堵住了 撒都该人的口,他们就聚集。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, ' 内中 有一个 人是律法师,要试探 耶稣,就问他说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, '「夫子,律法 上 的诫命,哪一条 是最大的呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, ' 耶稣对他 说:「你要 尽 心、 尽 性、 尽 意 爱 主─你的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, '这 是 诫命 中的第一,且 是最大的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, '其次 也 相 倣,就是要爱 人 如 己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, ' 这 两条 诫命 是律法 和 先知 一切 道理的总纲。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, ' 法利赛人 聚集的时候,耶稣 问 他们 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, '「论到 基督,你们的 意见 如何?他是 谁的 子孙呢?」他们回答说:「是大卫的子孙。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, '耶稣说:「这样,大卫 被 圣灵感动,怎么 还称 他 为主,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, '主 对我 主 说:你坐 在 我的 右边,等 我 把你 仇敌 放 在你的 脚下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, '大卫 既 称 他 为主,他怎么 又是 大卫的 子孙呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, ' 他们没有一个人 能 回答 一言。从 那 日以后,也没有 人 敢 再问 他 什么。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, '那时,耶稣 对众人 和 门徒 讲论, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, '说:「文士 和 法利赛人 坐 在 摩西的 位上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, ' 凡 他们所吩咐 你们的,你们都要谨守 遵行。但 不 要 效法 他们的 行为;因为 他们能说, 不能 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, ' 他们把难担的 重 担 捆起来, 搁 在 人的 肩上,但 自己 一个 指头 也不 肯 动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, ' 他们 一切 所做 的事 都是要 叫人 看见,所以 将 佩戴的经文 做宽了, 衣裳的䍁子 做长了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, ' 喜爱 筵席 上 的首座, 会堂 里 的高位, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, '又 喜爱 人 在 街市 上问他安, 称呼 他拉比(拉比就是夫子)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, '但 你们 不要 受拉比 的称呼,因为 只有一位 是 你们的 夫子; 你们 都 是 弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, '也 不要 称呼 地 上 的人为 父,因为 只有一位 是 你们的 父,就是 在天上的父。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, '也不要 受师尊 的称呼,因为 只有一位 是 你们的 师尊,就是基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, ' 你们 中间谁为大,谁就要作 你们的 用人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, ' 凡 自 高的,必降为卑; 自 卑的,必升为高。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, '「 你们 这假冒为善的 文士 和 法利赛人 有祸了!因为 你们正当人 前,把天 国 的门关了, 自己 不 进去,正要进去的人,你们也不 容 他们进去。(有古卷加: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, '你们 这假冒为善的 文士 和 法利赛人 有祸了!因为 你们侵吞 寡妇的 家产, 假意 做很长的 祷告,所以 要受 更重的 刑罚。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, '「你们 这假冒为善的 文士 和 法利赛人 有祸了!因为 你们走遍 洋海 陆地,勾引 一个 人入教, 既 入了教,却使 他 作地狱 之子,比你们 还加倍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, '「你们 这瞎眼 领路的 有祸了!你们 说:『凡 指著 殿 起誓的,这算 不得什么;只是 凡 指著 殿中 金子 起誓的,他就该谨守。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, '你们这无知 瞎眼的人哪, 什么 是 大的?是金子呢?还是 叫金子 成圣 的殿呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, '你们又说:『凡 指著 坛 起誓的,这算 不得什么;只是 凡 指著 坛 上 礼物 起誓的,他就该谨守。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, '你们这瞎眼的人哪, 什么 是大的?是礼物呢?还是 叫礼物 成圣 的坛呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, '所以,人指著 坛 起誓,就是指著 坛 和 坛 上 一切 所有的起誓; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, ' 人指著 殿 起誓,就是指著 殿 和 那住 在殿 里的起誓; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, ' 人指著 天 起誓,就是指著 神的 宝座 和 那坐 在 上面 的起誓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, '「你们 这假冒为善的 文士 和 法利赛人 有祸了!因为 你们将薄荷、 茴香、 芹菜,献上十分之一, 那律法 上更重的事,就是公义、 怜悯、 信实,反倒不行了。 这 更重的是你们当 行的;那也是 不可 不行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, '你们这瞎眼 领路的,蠓虫 你们就滤出来,骆驼 你们倒 吞下去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, '「你们 这假冒为善的 文士 和 法利赛人 有祸了!因为 你们洗净 杯 盘 的外面,里面 却 盛满了 勒索 和 放荡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, '你这瞎眼的 法利赛人,先 洗净 杯 盘的里面,好叫 外面 也 干净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, '「你们 这假冒为善的 文士 和 法利赛人 有祸了!因为 你们好像 粉饰的 坟墓, 外面 好 看,里面 却 装满了 死人的 骨头 和 一切的 污秽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, '你们 也是 如此,在人前,外面 显出 公义来,里面 却 装满了 假善 和 不法的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, '「你们 这假冒为善的 文士 和 法利赛人 有祸了!因为 你们建造 先知 的坟, 修饰 义人 的墓,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, '『若 是 我们在 我们 祖宗 的时候, 必 不 和他们 同 流 先知的 血。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, '这就是 你们自己 证明 是 杀害 先知 者的子孙了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, ' 你们 去充满 你们 祖宗 的恶贯吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, '你们这些蛇类、毒蛇之 种啊,怎能 逃 脱 地狱的 刑罚呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, '所以 我 差遣 先知 和 智慧人 并 文士 到 你们这里来, 有的 你们要杀害, 要钉十字架; 有的 你们 要在 会堂 里鞭打, 从 这城 追逼 到 那城, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, '叫 世 上 所流 义人 的血 都 归 到 你们身上,从 义人 亚伯 的血起,直到 你们在殿 和 坛 中间 所 杀 的巴拉加 的儿子 撒迦利亚 的血为止。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, '我实在 告诉 你们,这 一切的 罪都要归 到 这 世代了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, '「耶路撒冷啊,耶路撒冷啊,你常杀害 先知,又 用石头打死 那奉差遣 到 你这里来的人。我多次 愿 意 聚集 你的 儿女,好像 母鸡 把小鸡 聚集 在 翅膀底下,只是 你们不 愿 意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, '看哪,你们的 家 成为荒场 留给 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, ' 我告诉 你们,从 今以后,你们不得 再见 我,直等到 你们 说:『奉 主 名 来 的是应当称颂的。』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, ' 耶稣 出了 圣殿,正走的时候, 门徒 进前来,把殿 宇 指给他 看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, ' 耶稣对他们 说:「你们不是 看见 这殿宇吗?我实在 告诉 你们,将来在这里 没有 一块石头 留 在 石头上, 不 被拆毁了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, ' 耶稣 在 橄榄 山 上坐著,门徒 暗暗地 来 说:「请告诉 我们,什么时候 有 这些事? 你 降临 和 世界 的末了 有什么 预兆呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, ' 耶稣 回答 说:「你们要谨慎,免得 有人 迷惑 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, '因为 将来有好些人 冒 我的 名 来,说:『我 是 基督』,并且 要迷惑 许多人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, '你们也 要 听见 打仗 和 打仗 的风声, 总不要 惊慌;因为 这些事是必须 有的,只是 末期 还没有 到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, ' 民 要 攻打 民, 国 要攻打 国; 多处 必有 饥荒、 地震。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, ' 这 都是 灾难(灾难:原文是生产之难)的起头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, '那时,人要把你们 陷 在 患难里,也要 杀害 你们;你们又 要 为 我的 名 被 万 民 恨恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, ' 那时,必有许多人 跌倒,也 要彼此 陷害, 彼此 恨恶; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, '且 有好些 假先知 起来, 迷惑 多人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, '只 因 不法 的事增多,许多人 的爱心 才渐渐冷淡了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, '惟有 忍耐 到 底的, 必然得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, ' 这 天国的 福音 要传 遍 天下,对 万 民 作见证, 然后 末期 才来到。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, '「 你们看见 先知 但以理 所说的『那行毁坏 可憎的』站 在 圣 地(读 这经的人须要会意)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, '那时,在 犹太的,应当逃 到 山上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, '在 房上的,不要 下来 拿 家里的东西; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, ' 在 田里的,也不要 回去 取 衣裳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, ' 当 那些 日子,怀 孕 的和 奶孩子 的有祸了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, ' 你们应当祈求,叫你们 逃走的时候,不 遇见 冬天 或是 安息日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, '因为 那时 必有 大 灾难,从 世界 的起头 直到 如今,没 有 这样的灾难,后来也必 没 有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, ' 若 不 减少 那 日子,凡 有血气的 总没有 一个 得救的;只是 为 选民,那 日子 必减少了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, '那时,若 有人 对你们 说:『 基督 在这里』,或说:『基督在那里』,你们不要 信! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, '因为 假基督、 假先知 将要起来, 显 大 神迹、 大奇事,倘若 能行,连 选民 也 就迷惑了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, '看哪,我预先告诉 你们了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, ' 若 有人对你们 说:『看哪,基督 在 旷野里』,你们不要 出去!或说:『看哪,基督在 内屋中』,你们不要 信! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, ' 闪电 从 东边 发出, 直照 到 西边。人 子 降临 也要 这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, ' 尸首 在 哪里,鹰 也必聚 在那里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, '「 那些 日子 的灾难 一 过去,日头 就变黑了,月亮 也 不 放 光, 众星 要从 天上 坠落, 天 势 都要震动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, ' 那时,人 子 的兆头 要显 在 天上, 地上 的万 族 都要哀哭。 他们要看见 人 子,有 能力, 有大 荣耀,驾著 天上 的云 降临。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, ' 他要差遣 使者,用 号筒的 大声, 将他的 选民,从 四方(方:原文是风),从 天 这边 到 天 那边,都招聚了来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, '「 你们可以从 无花果树 学 个比方:当 树枝 发嫩 长 叶的时候,你们就知道 夏天 近了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, '这样, 你们 看见 这一切 的事,也 该知道 人子 近了,正在 门口了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, '我实在 告诉 你们, 这 世代 还没有 过去, 这些事 都 要成就。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, '天 地 要废去,我的 话 却 不能 废去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, '「但 那 日子, 那时辰,没有人 知道,连天上 的使者 也不知道,子 也不知道,惟 独 父知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, ' 挪亚的 日子 怎样,人 子 降临 也要 怎样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, ' 当 洪水 以前 的 日子,人照常吃 喝 嫁 娶,直到 挪亚 进 方舟 的那日; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, ' 不 知 不觉 洪水 来了, 把他们全都 冲去。人 子 降临 也 要 这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, '那时,两个人 在 田里,取去 一个, 撇下 一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, '两个 女人推 磨,取去 一个, 撇下 一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, '所以,你们要警醒,因为 不 知道 你们的 主 是哪 一天 来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, ' 家主 若 知道 几 更天 有贼 来, 就必警醒, 不 容 人挖透 房屋;这 是你们所知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, '所以,你们 也 要 预备,因为 你们想 不 到的 时候,人 子 就来了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, '「 谁 是 忠心 有见识的 仆人, 为主人 所派,管理 家里的人,按 时 分 粮 给他们呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, ' 主人 来到,看见 他 这样 行,那 仆人 就有福了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, '我实在 告诉 你们, 主人要派 他 管理 一切 所有的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, ' 倘若 那 恶 仆 心 里 说:『我的 主人 必来得迟』, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, '就 动手 打 他的 同伴,又 和 酒醉的人 一同吃 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, '在 想 不 到的日子, 不 知道 的时辰,那 仆人 的主人 要来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, '重重地处治他(或译:把他 腰斩了), 定 他 和假冒为善的人 同 罪;在那里 必要 哀哭 切 齿了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, '「那时,天 国 好比 十个 童女 拿著 灯 出去 迎接 新郎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, ' 其 中 有五个 是 愚拙的, 五个 是聪明的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, ' 愚拙的 拿著 灯,却不 预备 油; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, ' 聪明的 拿著 灯,又预备 油 在 器皿里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, ' 新郎 迟延的时候,她们都 打盹, 睡著了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, ' 半 夜 有人 喊著说:『 新郎来了,你们出来 迎接 他!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, ' 那些 童女 就都 起来 收拾 灯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, ' 愚拙的 对聪明的 说:『请分点 油 给 我们,因为 我们的 灯 要灭了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, ' 聪明的 回答 说:『恐怕 不 够 你 我用的;不如 你们自己 到 卖 油的那里去 买 吧。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, ' 她们 去 买 的时候,新郎 到了。 那预备好了的,同 他 进去 坐席, 门 就关了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, ' 其余 馀的 童女 随后 也 来了,说:『主啊,主啊,给我们 开 门!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, '他却 回答 说:『我实在 告诉 你们,我不 认识 你们。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, '所以,你们要警醒;因为 那日子, 那时辰,你们不 知道。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, '「 天国又好比 一个人 要往外国去,就叫了 仆人来, 把他的 家业 交给 他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, ' 按著 各人 的 才干 给他们银子:一个 给了 五千, 一个 给了二千, 一个 给了一千, 就 往外国去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, '那领 五千 的随即拿去 做买 卖, 另外 赚了 五千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, '那领 二千 的也照样 另 赚了 二千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, '但 那领 一千 的去 掘开  地, 把 主人的 银子 埋藏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, ' 过了 许 久,那些 仆人的 主人 来了, 和 他们 算帐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, ' 那领 五千 银子 的又带著 那另外的 五千 来,说:『主啊,你交给 我 五千 银子。请看,我又 赚了 五千。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, ' 主人 说:『好,你这又良善 又 忠心的 仆人,你在 不多的事 上有 忠心,我要把许多事 派 你 管理;可以进来 享受 你 主人 的快乐。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, ' 那领二 千 的也 来,说:『主啊,你交给 我 二 千银子。请看,我又 赚了 二 千。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, ' 主人 说:『好,你这又良善 又 忠心的 仆人,你在 不多的事 上有 忠心,我要把许多事 派 你 管理;可以进来 享受 你 主人的 快乐。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, ' 那领 一 千 的也 来,说:『主啊,我知道 你 是 忍心的 人,没有 种 的地方 要收割, 没有 散 的地方 要聚敛, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, '我就 害怕,去 把你的 一千银子 埋藏 在 地里。请看,你的 原银子在这里。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, ' 主人 回答 说:『你这又恶 又 懒的 仆人,你既知道 我没有 种 的地方 要收割, 没有 散 的地方 要聚敛, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, ' 就 当 把我的 银子 放给 兑换银钱的人, 到我 来的时候,可以 连本 带 利 收回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, ' 夺过 他 这一千来, 给 那有 一万的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, '因为 凡 有的,还要加给他, 叫他有余 馀; 没 有的,连 他所 有 的也要夺过来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, ' 把这无用的 仆人 丢 在 外面 黑暗里;在那里 必要 哀哭 切 齿了。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, '「 当 人 子 在 他 荣耀里、 同著 众 天使 降临的时候, 要坐 在 他 荣耀 的宝座上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, ' 万 民 都要聚集 在 他面前。 他要把他们 分别出来,好像 牧羊的 分别 绵羊 山羊一般, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, ' 把绵羊 安置 在 右边, 山羊 在 左边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, '于 是 王 要向那 右边 的说:『你们这蒙我 父 赐福的,可来 承受 那创世 以来 为你们 所预备 的国; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, '因为 我饿了, 你们给 我 吃,渴了, 你们给我 喝;我作 客旅, 你们留我 住; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, '我赤身露体, 你们给我 穿;我病了, 你们看顾 我;我 在 监里, 你们来 看 我。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, '义人 就 回答 说:『主啊,我们什么时候 见 你 饿了, 给你吃, 渴了, 给你喝? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, ' 什么时候 见 你 作客旅, 留你住,或是 赤身露体, 给你穿? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, '又 什么时候 见 你 病了,或是 在 监里, 来 看 你呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, ' 王 要回答 说:『我实在 告诉 你们,这些事 你们既做 在 我 这 弟兄 中一个 最小的身上,就是做 在我身上了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, ' 王又 要向那 左边 的说:『你们这被咒诅的人,离开  我!进入 那为魔鬼 和 他的 使者 所预备 的永 火里去! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, '因为 我饿了, 你们不 给 我 吃,渴了, 你们不 给我 喝; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, '我作 客旅, 你们不 留我 住;我赤身露体, 你们不 给我 穿;我病了, 我在 监里, 你们不 来看顾 我。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, ' 他们 也 要回答 说:『主啊,我们什么时候 见 你 饿了,或 渴了,或 作客旅,或 赤身露体,或 病了,或 在 监里, 不 伺候 你呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, ' 王要回答 说:『我实在 告诉 你们,这些事 你们既不 做 在 我这 弟兄中一个 最小的身上,就是不 做 在我身上了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, ' 这些人 要往 永 刑 里去; 那些义人 要往 永 生里去。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, ' 耶稣 说完了 这 一切 的话,就对 门徒 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, '「你们知道, 过 两 天 是 逾越节, 人 子 将要被交给人, 钉在十字架上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, '那时,祭司长 和 民间 的长老 聚集 在 大祭司 称为 该亚法 的院里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, ' 大家商议 要用诡计 拿住 耶稣, 杀他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, '只是 说:「当 节 的日子不可,恐怕 民 间 生 乱。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, ' 耶稣 在 伯大尼 长大痲疯的 西门 家 里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, '有一个女人 拿著 一玉瓶 极贵的 香膏 来,趁耶稣坐席的时候, 浇 在 他的 头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, ' 门徒 看见 就很不喜悦,说:「何用 这样的 枉费呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, ' 这 香膏可以 卖 许多钱, 赒济 穷人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, ' 耶稣 看出他们的意思,就说:「为什么 难为 这女人呢? 她在 我 身上做的 是一件美 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, '因为 常 有 穷人 和你们 同在;只是 你们不 常 有 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, ' 她 将这 香膏 浇 在 我 身上 是为 我 安葬 做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, '我实在 告诉 你们, 普 天之下,无论 在什么地方 传 这 福音,也 要述说 这 女人所 行的,作个 纪念。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, '当下,十二 门徒里有一个 称为 加略人 犹大的,去 见 祭司长,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, '「我 把他 交 给你们,你们愿 意 给 我 多少钱?」 他们就给了 他 三十 块钱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, ' 从 那时候,他就找 机会 要 把耶稣 交给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, ' 除酵节 的第一天,门徒 来 问耶稣 说:「你吃 逾越节的筵席,要 我们在哪里 给你 预备?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, ' 耶稣说:「你们进 城 去,到 某人那里, 对他 说:『夫子 说:我的 时候 快到了,我与 门徒 要在 你 家里守 逾越节。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, ' 门徒 遵著 耶稣 所吩咐 的 就 去预备了 逾越节的筵席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, ' 到了 晚上,耶稣和 十二个 门徒坐席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, ' 正吃的时候,耶稣说:「我实在 告诉 你们, 你们 中间 有一个 人要卖 我了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, '他们就 甚 忧愁, 一个一个地 问他 说:「主, 是 我吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, ' 耶稣回答 说:「同 我 蘸 手 在 盘子里的,就是他 要卖 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, '人 子 必要 去世,正如 经上指著 他 所写的;但 卖 人 子 的人 有祸了! 那 人 不 生 在世上倒 好。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, ' 卖 耶稣 的犹大 问他说:「拉比, 是 我吗?」耶稣说:「你 说的是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, ' 他们 吃的时候,耶稣 拿起 饼来, 祝福,就擘开 , 递 给门徒,说:「你们拿著 吃,这 是 我的 身体」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, '又 拿起 杯来, 祝谢了,递 给他们,说:「你们都 喝 这个; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, '因为 这 是 我 立约 的血, 为 多人 流出来,使 罪 得赦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, '但 我告诉 你们,从 今以后,我不再 喝 这 葡萄 汁,直到 我在 我 父的 国里 同 你们 喝 新的 那 日子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, ' 他们唱了诗,就出来 往 橄榄 山去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, '那时,耶稣 对他们 说:「 今 夜,你们 为 我 的缘故都 要跌倒。因为 经上记著说:我要击打 牧人,羊 就 分散了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, '但 我 复活 以后,要在你们 以先 往 加利利去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, '彼得 说:「众人 虽然 为 你 的缘故跌倒,我 却永不 跌倒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, '耶稣 说:「我实在 告诉 你, 今 夜 鸡 叫 以先,你要三次 不认 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, '彼得 说:「我 就是 必须 和你 同 死,也总不能 不认 你。」众门徒 都是 这样 说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, ' 耶稣 同 门徒 来 到 一个地方,名叫 客西马尼,就 对他们 说:「你们坐 在这里,等 我到 那边 去祷告。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, '于 是 带著 彼得 和 西庇太 的两个 儿子同去,就忧愁 起来, 极其难过, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, '便 对他们 说:「我 心里 甚是 忧伤,几乎要 死;你们在这里 等候, 和我 一同 警醒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, '他就 稍 往前走,俯伏 在地, 祷告 说:「我 父啊,倘若 可 行,求你叫这 杯 离 开  我。然而,不要 照 我的 意思,只要 照 你的意思。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, ' 来 到 门徒那里, 见 他们 睡著了,就 对彼得 说:「怎么样?你们不 能 同 我 警醒 片 时吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, '总要警醒 祷告,免得 入了 迷惑。你们心灵 固然 愿 意,肉体 却 软弱了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, ' 第二次 又 去 祷告 说:「我 父啊,这 杯若 不 能 离开 我,必要 我喝,就愿 你的 意旨 成全。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, ' 又 来,见 他们 睡著了,因为 他们的 眼睛 困倦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, ' 耶稣又 离开  他们 去了。 第三次 祷告, 说 的话 还是与先前一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, '于 是 来 到 门徒那里, 对他们 说:「现在 你们仍然睡觉 安歇吧(吧:或译吗?)! 时候 到了, 人 子 被卖 在 罪人 手里了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, '起来!我们走吧。看哪,卖 我 的人近了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, ' 说话 之间, 那十二个 门徒里的 犹大 来了,并 有许多 人 带著 刀 棒,从 祭司长 和 民间的 长老 那里与他 同来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, ' 那卖 耶稣 的给了 他们 一个暗号,说:「我与谁 亲嘴,谁就是 他。你们可以拿住 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, ' 犹大随即 到 耶稣跟前,说:「请拉比 安」,就 与他 亲嘴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, ' 耶稣 对他 说:「朋友,你来 要做的 事,就做吧。」于 是 那些人上前,下 手 拿住 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, ' 有跟随 耶稣 的一个 人伸 手 拔出 刀来, 将大祭司的 仆人 砍了一刀,削掉了 他 一个耳朵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, ' 耶稣 对他 说:「收 刀 入 鞘吧! 凡 动 刀的,必死 在 刀下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, ' 你想, 我不 能 求 我 父 现在 为我 差遣 十二 营 多 天使来吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, '若是这样,经上所说, 事情必须 如此 的话怎么 应验呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, ' 当 时,耶稣 对众人 说:「你们带著 刀 棒 出来 拿 我,如同 拿 强盗吗?我天天 坐 在 殿 里教训人,你们并 没有 拿 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, '但 这 一切 的事成就了,为要 应验 先知 书上的话。」当下,门徒 都 离开  他 逃走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, ' 拿 耶稣 的人把他带 到 大祭司 该亚法那里去;文士 和 长老 已经在那里 聚会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, ' 彼得 远远地 跟著 耶稣,直到 大祭司 的院子, 进到 里面,就和 差役 同坐,要看 这事到底怎样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, ' 祭司长 和 全 公会 寻找 假见证 控告 耶稣,要 治死 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, '虽有 好些人 来 作假见证,总得不 著实据。 末后 有两个 人前来,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, '「这个人 曾说:『我能 拆毁 神的 殿,三 日 内 又 建造起来。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, '大祭司 就 站起来,对耶稣 说:「你什么都不 回答吗?这些人 作见证告 你 的是什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, '耶稣 却 不言语。 大祭司 对他 说:「我指著 永生 神 叫你 起誓 告诉 我们, 你 是 神 的儿子 基督 不是?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, '耶稣 对他 说:「你 说的是。然而,我告诉 你们,后来 你们要看见 人 子 坐 在 那权能者 的右边, 驾著 天上 的云 降临。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, '大祭司 就 撕开  衣服,说:「他说了僭妄的话,我们何必 再 用 见证人呢? 这僭妄的话,现在 你们都听见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, '你们的 意见 如何?」他们回答 说:「他是 该 死的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, '他们就 吐唾沫 在 他 脸上, 用拳头打 他;也 有用手掌打他的,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, '「基督啊!你是先知,告诉 我们 打 你 的是 谁?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, ' 彼得 在 外面 院子 里坐著, 有一个 使女 前来,说:「你 素来也 是 同那加利利人 耶稣 一伙 夥的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, '彼得在众人 面前 却 不承认,说:「我不 知道 你说的 是什么!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, '既 出去,到了 门口,又有一个 使女看见 他,就 对那里 的人说:「这个人 也是 同拿撒勒人 耶稣 一伙 夥的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, ' 彼得又 不承认,并且 起誓说:「 我不 认得 那个人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, ' 过了 不多的时候,旁边站著 的人前来,对彼得 说:「 你 真 是 他们 一党的, 你的 口音 把 你 露出来了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, ' 彼得就 发咒 起誓地 说:「我不 认得 那个人。」立时,鸡 就 叫了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, ' 彼得 想起 耶稣 所 说 的话:「鸡 叫 以先,你要三次 不认 我。」他就 出去 痛 哭。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, ' 到了 早晨,众 祭司长 和 民间的 长老 大家商 议 要 治死 耶稣, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, '就 把他 捆绑,解去, 交给 巡抚 彼拉多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, '这时候,卖 耶稣 的 犹大 看见 耶稣已经定了罪,就后悔,把那三十块 钱 拿回来 给祭司长 和 长老,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, '「我卖了 无辜之人 的血 是有罪了。」 他们说:「那与 我们 有什么相干?你自己 承当吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, '犹大就 把那银钱 丢 在 殿里,出 去 吊死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, ' 祭司长 拾起 银钱来,说:「 这是 血 价,不 可 放 在 库里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, ' 他们商 议,就用 那银钱 买 了 窑户 的一块田,为要 埋葬 外乡人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, '所以 那块 田 直到 今日 还叫做「血 田」。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, '这就 应了 先知 耶利米 的 话,说:「 他们用 那三十块 钱,就是被估定 之人的价钱, 是以色列 人 中 所估定的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, ' 买 了 窑户的 一块田;这是照著 主 所吩咐 我的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, ' 耶稣 站 在巡抚 面前; 巡抚 问 他 说:「你 是 犹太人的 王吗?」 耶稣 说:「你 说的是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, ' 他 被 祭司长 和 长老 控告 的时候,什么都不 回答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, '彼拉多 就 对他 说:「他们作见证告 你 这么多的事,你没有 听见吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, ' 耶稣仍不 回答,连 一句 话 也不说,以致 巡抚 甚 觉希奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, ' 巡抚 有一个常例,每逢 这节期,随众人 所 要 的释放 一个 囚犯给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, ' 当时 有 一个出名的 囚犯 叫 巴拉巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, ' 众人 聚集的时候,彼拉多 就对他们 说:「你们要 我释放 哪一个 给你们?是巴拉巴呢?是 称为 基督 的耶稣呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, '巡抚原 知道 他们是因为 嫉妒 才把他 解了来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, ' 正坐 堂的时候,他的 夫人 打发 人来 说:「 这 义人的事,你 一点不可管,因为 我今天 在 梦 中为 他 受了许多 的苦。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, ' 祭司长 和 长老 挑唆 众人, 求 释放巴拉巴, 除灭 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, '巡抚 对众人 说:「 这两个人,你们要 我释放 哪一个 给你们呢?」 他们说:「巴拉巴。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, '彼拉多 说:「这样,那 称为 基督 的耶稣 我怎么 办他呢?」他们都 说:「把他钉十字架!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, ' 巡抚说:「为什么呢?他做了 什么 恶事呢?」他们便 极力地 喊著 说:「把他钉十字架!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, ' 彼拉多 见 说也无 济于 事,反 要 生 乱,就拿 水 在众人 面前 洗 手,说:「流 这 义人的血,罪不 在我,你们 承当吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, ' 众人 都 回答 说:「他的 血 归到 我们 和 我们的 子孙身上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, '于 是 彼拉多释放 巴拉巴 给他们, 把耶稣 鞭打了, 交给 人钉十字架。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, '巡抚的 兵 就 把耶稣 带 进 衙门,叫全 营 的兵都聚集 在 他那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, ' 他们给他 脱了衣服, 穿上 一件朱红色 袍子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, ' 用 荆棘 编做 冠冕,戴 在 他 头上, 拿一根苇子 放在 他 右手里, 跪 在他 面前,戏弄 他,说:「恭喜,犹太人的 王啊!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, '又 吐唾沫 在 他脸上,拿 苇子 打 他 的 头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, ' 戏弄 完了,就给他 脱了 袍子,仍 穿上 他 自己的 衣服, 带他 出去,要 钉十字架。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, ' 他们出来的时候,遇见 一个古利奈 人,名叫 西门,就勉强 他同去,好 背著 耶稣的 十字架。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, ' 到了 一个地方 名叫 各各他, 意思 就是「髑髅 地」。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, '兵丁拿 苦胆 调和 的酒 给 耶稣 喝。他尝了,就 不 肯 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, '他们既 将他 钉在十字架上,就拈 阄 分 他的 衣服, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, '又 坐 在那里 看守 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, ' 在他 头 以上 安一个牌子,写著 他的 罪状,说:「这 是 犹太人的 王 耶稣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, '当时,有两个 强盗 和他 同 钉十字架,一个 在 右边, 一个 在 左边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, ' 从那里经过 的人讥诮 他,摇著 头,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, '「你这拆毁 圣殿、 三 日 又 建造起来的,可以救 自己吧!你如果 是 神的 儿子,就从 十字架 上下来吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, '祭司长 和 文士 并 长老 也是 这样 戏弄他,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, '「他救了 别人,不 能 救 自己。他是 以色列的 王,现在 可以从 十字架上 下来,我们就 信 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, '他倚靠 神, 神若 喜悦 他,现在 可以救他;因为 他曾说:『 我是 神的 儿子。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, ' 那 和 他 同钉 的强盗 也是 这样地 讥诮 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, ' 从 午正 到 申初, 遍 地 都 黑暗了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, ' 约在 申初,耶稣 大 声 喊著 说:「以利!以利!拉马 撒巴各大尼?」就是说:「我的 神!我的 神!为什么 离弃 我?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, ' 站 在那里的人,有的 听见 就说:「 这个人 呼叫 以利亚呢!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, ' 内中 有一个人 赶紧 跑去, 拿 海绒 蘸满了 醋, 绑在 苇子上,送给他 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, ' 其余 馀的 人说:「且等著,看 以利亚 来 救 他 不来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, ' 耶稣 又 大 声 喊叫,气 就断了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, ' 忽然,殿 里的幔子 从 上 到 下 裂 为 两半,地 也 震动,磐石 也 崩裂, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, '坟墓 也 开 了, 已睡 圣徒 的身体 多 有起来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, ' 到耶稣 复活 以后,他们从 坟墓 里出来,进了 圣 城, 向许多人 显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, ' 百夫长 和 一同 看守 耶稣 的人看见 地震 并 所经历的事,就极其 害怕,说:「这 真 是 神的 儿子了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, ' 有 好些 妇女 在那里,远远地 观看;她们 是从 加利利 跟随 耶稣 来服事 他的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, '内中 有 抹大拉 的马利亚,又 有雅各 和 约西 的母亲 马利亚,并 有西庇太 两个儿子 的母亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, ' 到了 晚上,有 一个财主,名叫 约瑟,是 亚利马太来的,他 也 是耶稣的 门徒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, '这人 去见 彼拉多,求 耶稣的 身体;彼拉多 就 吩咐 给他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, ' 约瑟 取了 身体,用 干净 细麻布 裹好, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, ' 安放 在 自己的 新 坟墓里,就是 他凿 在 磐石里的。他又 把大 石头 滚 到墓 门口,就去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, ' 有 抹大拉 的马利亚 和 那个 马利亚 在那里,对著 坟墓 坐著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, ' 次日,就 是 预备日 的第二天,祭司长 和 法利赛人 聚集 来 见彼拉多,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, '「大人,我们记得 那 诱惑人的 还 活著 的时候曾说:『三 日 后 我要复活。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, '因此,请吩咐 人将坟墓 把守妥当,直到 第三 日,恐怕 他的 门徒 来,把他 偷了去,就 告诉 百姓说:『他从 死 里复活了。』这样,那后来的 迷惑 比先前的 更利害了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, '彼拉多 说:「你们有 看守的兵,去吧!尽 你们所能的 把守妥当。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, '他们就 带著 看守的兵 同去,封了 石头,将坟墓 把守妥当。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, '安息日 将尽, 七日 的头一日,天快亮的时候,抹大拉 的马利亚 和 那个 马利亚 来 看 坟墓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, ' 忽然, 地大 震动;因为 有主的 使者 从 天上 下 来,把石头 滚开 , 坐 在上面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, ' 他的 相貌 如同 闪电, 衣服 洁白 如 雪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, '看守的人 就 因 他 吓得 浑身乱战 ,甚至 和死人 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, ' 天使 对妇女 说:「 不要 害怕! 我知道 你们是寻找 那 钉十字架 的耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, '他不 在 这里,照 他所说的, 已经复活了。你们来 看 安放 主的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, ' 快 去 告诉 他的 门徒,说 他从 死 里复活了,并且 在你们 以先 往 加利利去,在那里 你们要见 他。看哪,我已经告诉 你们了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, '妇女们就 急忙 离开  坟墓,又 害怕,又 大大地 欢喜,跑去 要报给 他的 门徒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, ' 忽然,耶稣 遇见 她们,说:「愿 你们平安!」她们就 上前 抱住 他的 脚 拜 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, ' 耶稣 对她们 说:「不要 害怕!你们去 告诉 我的 弟兄,叫 他们往 加利利 去,在那里 必见 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, ' 她们 去的时候, 看守的兵 有几个 进 城 去,将所经历 的事都 报给 祭司长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, ' 祭司长和 长老 聚集 商 议,就拿许多 银钱 给 兵丁,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, '「你们要这样说:『 夜间 我们 睡觉的时候,他的 门徒 来,把他 偷去了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, ' 倘若 这 话被巡抚 听见,有我们 劝 他, 保 你们 无事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, ' 兵丁受了 银钱,就照 所嘱咐 他们的去行。 这 话 就传说 在犹太人 中间,直到 今日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, ' 十一个 门徒 往 加利利 去,到了 耶稣 约定 的山上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, '他们见了 耶稣 就 拜他,然而 还有人疑惑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, ' 耶稣 进前来, 对他们 说:「天 上 地 下 所有的 权柄 都赐给 我了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, '所以,你们要去,使万 民 作我的门徒,奉 父、 子、 圣 灵 的名 给他们 施洗(或译:给他们施洗,归于 父、子、圣灵的名)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, '凡 我所吩咐 你们的,都 教训 他们 遵守, 我 就 常 与你们 同在,直到 世界 的末了。」    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, '神的 儿子,耶稣 基督 福音的 起头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, '正如 先知 以赛亚(有古卷没有以赛亚三个字)书上记著说:看哪,我要差遣 我的 使者 在 你 前面, 预备 道路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, '在 旷野 有人声 喊著说:预备 主的 道,修 直 他的 路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, '照这话,约翰 来了,在 旷野施洗, 传 悔改的 洗礼,使 罪 得赦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, ' 犹太 全 地 和 耶路撒冷 的人都 出去 到 约翰那里, 承认 他们的 罪,在 约旦 河 里受 他的 洗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, ' 约翰 穿 骆驼 毛 的衣服,腰 束 皮 带, 吃 的是蝗虫、 野 蜜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, ' 他传道 说:「有一位在我 以后 来的,能力比我 更大,我就是弯腰 给他 解 鞋 带 也是 不 配的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, '我 是用水 给你们 施洗,他 却 要用 圣 灵 给你们 施洗。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, ' 那 时,耶稣 从 加利利 的拿撒勒 来, 在 约旦河 里受了 约翰 的洗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, ' 他从 水 里一 上来,就看见 天 裂开 了, 圣灵 仿佛 鸽子,降 在 他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, '又 有 声音 从 天上来,说:「你 是 我的 爱 子,我喜悦 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, '圣灵 就 把耶稣 催 到 旷野里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, ' 他 在 旷野 四十 天,受 撒但 的试探,并 与野兽 同 在一处,且 有天使 来伺候 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, ' 约翰 下监 以后,耶稣 来 到 加利利,宣传 神的 福音, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, ' 说:「 日期 满了, 神的 国 近了。你们当悔改, 信 福音!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, ' 耶稣顺著 加利利的 海边 走,看见 西门 和 西门的 兄弟 安得烈 在 海 里撒网;他们本 是 打鱼的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, ' 耶稣 对他们 说:「来 跟从 我, 我要叫 你们 得人 如得鱼一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, '他们就 立刻 舍了 网,跟从了 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, ' 耶稣稍 往前走,又见 西庇太的 儿子雅各 和 雅各的 兄弟 约翰 在 船上 补 网。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, ' 耶稣随即 招呼 他们,他们就 把 父亲 西庇太 和 雇工人 留 在 船上,跟从 耶稣去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, ' 到了 迦百农,耶稣就 在安息日 进了 会堂 教训人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, ' 众人很希奇 他的 教训;因为 他教训 他们,正 像 有 权柄的人, 不 像 文士。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, ' 在 会堂里,有 一个人 被污 鬼 附著。 他喊叫 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, '「拿撒勒人 耶稣,我们 与 你 有什么相干?你来 灭 我们吗?我知道 你 是 谁,乃是 神的 圣者。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, ' 耶稣 责备 他 说:「不要作声! 从 这人 身上出来吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, ' 污 鬼 叫那人 抽了一阵疯, 大 声 喊叫,就 出来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, ' 众人 都惊讶,以致 彼此 对 问 说:「这 是 什么事?是个新 道理啊!他用 权柄 吩咐污鬼,连 污 鬼 也 听从了 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, ' 耶稣的 名声 就 传 遍 了 加利利的 四 方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, ' 他们一 出 会堂,就同著 雅各、 约翰,进了 西门 和 安得烈的 家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, ' 西门的 岳母 正害热病 躺著,就 有人告诉 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, ' 耶稣进前 拉著 她的 手,扶她 起来, 热 就退了,她就 服事 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, ' 天晚 日 落 的时候,有人带著 一切 害 病 的,和 被鬼附 的,来到 耶稣跟前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, ' 合 城 的人都 聚集 在 门前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, ' 耶稣治好了 许多 害 各样 病的人,又 赶出 许多 鬼, 不 许 鬼 说话,因为 鬼认识 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, ' 次日早晨,天未亮的时候,耶稣起来, 到 旷野 地方 去,在那里 祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, ' 西门 和 同伴 追了 他去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, ' 遇见了 就对他 说:「 众人 都找 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, ' 耶稣对他们 说:「我们可以往别处 去,到 邻近的 乡村,我也 好 在那里 传道,因为 我是为 这事 出来的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, '于 是 在 加利利 全地,进了 会堂,传道, 赶 鬼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, ' 有一个长大痲疯的 来 求 耶稣,向 他跪下, 说:「 你若 肯,必能 叫我 洁净了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, ' 耶稣动了慈心,就伸 手 摸 他, 说:「我肯,你洁净了吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, ' 大痲疯 即时 离开  他,他就 洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, ' 耶稣严严地嘱咐 他,就 打发 他走, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, ' 对他 说:「你要谨慎,什么话 都不可 告诉人,只要 去 把身体 给祭司 察看,又 因为 你 洁净了,献上 摩西 所 吩咐的礼物,对众人 作 证据。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, '那人 出去,倒 说 许多的话, 把这 件事 传扬开 了,叫 耶稣 以后不 得 再明明地 进 城,只好 在 外边 旷野 地方。 人从各处 都就了 他 来。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, ' 过了 些日子,耶稣又 进了 迦百农。人听见 他 在 房子里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, '就 有许多人 聚集,甚至 连 门 前 都没有 空地;耶稣就 对他们 讲 道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, ' 有人带著 一个瘫子 来 见 耶稣,是用 四个 人抬来的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, ' 因为 人多,不 得 近前,就把耶稣所在 的房子,拆了 房顶,既 拆通了,就把 瘫子 连所躺卧的 褥子 都缒下来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, ' 耶稣 见 他们的 信心,就对 瘫子 说:「小子,你的 罪 赦了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, ' 有 几个 文士 坐 在那里, 心里 议论,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, '「这个人 为什么 这样 说呢?他说僭妄的话了。除了  神以外,谁 能 赦 罪呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, ' 耶稣 心中 知道 他们 心里 这样 议论,就说:「你们 心 里 为什么 这样 议论呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, '或对瘫子 说『你的 罪 赦了』,或 说『起来! 拿 你的 褥子 行走』;哪一样 容易呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, '但 要叫 你们知道, 人 子 在 地上 有 赦 罪 的权柄。」就对瘫子 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, '「我吩咐 你,起来!拿 你的 褥子 回 家 去吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, '那人就 起来,立刻 拿著 褥子, 当众人 面前 出去了,以致 众人 都惊奇, 归荣耀与 神,说:「 我们从来没有 见过 这样的事!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, ' 耶稣又 出到 海边去, 众人 都就了 他 来,他便 教训 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, ' 耶稣经过的时候,看见 亚勒腓的 儿子利未 坐 在税关 上,就 对他 说:「你跟从 我来。」他就 起来,跟从了 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, ' 耶稣 在 利未 家 里坐席的时候,有好些 税吏 和 罪人 与耶稣 并 门徒 一同坐席;因为 这样的人 多,他们也 跟随 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, ' 法利赛人 中的文士(有古卷:文士和法利赛人)看见 耶稣和 罪人 并 税吏 一同吃饭,就对他 门徒 说:「 他和税吏 并 罪人 一同 吃喝吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, ' 耶稣 听见,就对他们 说:「康健的人 用不著 医生,有 病的人 才用得著。我来 本不是 召 义人,乃是 召罪人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, '当下,约翰的 门徒 和 法利赛人 禁食。 他们来 问耶稣 说:「约翰的 门徒 和 法利赛人的 门徒 禁食,你的 门徒 倒 不 禁食,这是为什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, ' 耶稣 对他们 说:「 新郎 和陪伴之人 同 在的时候,陪伴之人 岂能 禁食呢?新郎 还 同 在,他们 不 能 禁食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, '但 日子 将到, 新郎 要离开  他们, 那 日 他们就要 禁食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, '没有人 把新 布 缝 在旧 衣服 上,恐怕 所补上的 新 布带坏了 旧 衣服,破的 就 更大了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, '也 没有人 把新 酒 装 在 旧 皮袋里,恐怕 酒 把皮袋 裂开 , 酒 和 皮袋 就都坏了;惟 把新 酒 装在 新 皮袋里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, ' 耶稣 当 安息日 从麦地 经过。 他 门徒 行 路的时候, 掐了 麦穗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, ' 法利赛人 对耶稣 说:「看哪,他们在安息日 为什么 做 不 可做的事呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, ' 耶稣对他们 说:「经上记著大卫 和 跟从 他的 人缺乏 饥饿 之时 所做 的事,你们没有 念过吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, '他当亚比亚他 作大祭司 的时候,怎么 进了 神的 殿, 吃了 陈设 饼, 又 给 跟从 他的人吃。这 饼除了 祭司以外,人都不 可 吃。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, '又 对他们 说:「安息日 是为 人 设立的, 人 不是 为 安息日设立的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, '所以,人 子 也 是 安息日的 主。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, ' 耶稣又 进了 会堂, 在那里 有 一个人 枯干了 一只手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, ' 众人窥探 耶稣,在安息日 医治 不医治,意思是要 控告 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, ' 耶稣对那 枯干 一只手 的人 说:「起来,站在当中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, '又 问众人 说:「在安息日 行 善 行恶,救 命 害命,哪样是可以的呢?」 他们都不作声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, ' 耶稣 怒 目周围看 他们,忧愁 他们的 心 刚硬,就对那人 说:「伸出 手来!」 他把手一伸, 手 就 复了原。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, ' 法利赛人 出去, 同 希律一党的人 商议 怎样 可以除灭 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, ' 耶稣 和 门徒 退 到 海边去, 有许多人 从 加利利 跟随他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, ' 还有许多 人 听见 他所 做的大事,就从犹太、 耶路撒冷、 以土买 、 约旦河 外,并 泰尔、 西顿 的四方 来 到 他那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, '他因为 人多,就 吩咐 门徒 叫 一只小船 伺候著,免得 众人拥挤 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, ' 他治好了 许多人,所以 凡 有 灾病的,都挤进来 要 摸 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, ' 污 鬼 无论何时 看见 他,就俯伏 在他面前, 喊著 说:「 你 是 神的 儿子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, ' 耶稣再三地 嘱咐 他们,不要 把他 显露出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, ' 耶稣上了 山, 随自己的意思 叫 人来; 他们便来 到 他那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, ' 他就设立 十二个人,要 他们 常和自己 同在,也 要 差 他们 去传道, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, '并 给 他们权柄 赶 鬼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, ' 这十二个人 有西门(耶稣又 给 他起名 叫彼得), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, '还有 西庇太的 儿子 雅各 和 雅各的 兄弟 约翰(又 给 这两个人 起名 叫半尼其,就是 雷 子的意思), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, '又有 安得烈、 腓力、 巴多罗买 、 马太、 多马、 亚勒腓的 儿子雅各、和 达太,并 奋锐党的 西门, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, '还有 卖 耶稣 的加略人 犹大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, ' 耶稣进了 一个屋子, 众人 又 聚集,甚至 他 连 饭 也顾不 得 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, ' 耶稣的亲属 听见,就出来 要拉住 他,因为 他们说 他癫狂了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, ' 从 耶路撒冷 下来 的文士 说:「 他是被别西卜 附著」;又说:「 他是靠著 鬼 王 赶 鬼。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, ' 耶稣叫 他们来,用 比喻 对他们 说:「撒但 怎 能 赶出 撒但呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, ' 若 一国 自 相 纷争,那 国 就站立 不 住; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, ' 若 一家 自 相 纷争,那 家 就站立 不 住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, ' 若 撒但 自 相 攻打 纷争,他就站立 不 住,必 要 灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, ' 没有人 能 进 壮士 家里,抢夺 他的 家具; 必先 捆住 那壮士, 才 可以抢夺 他的 家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, '我实在 告诉 你们, 世人一切的 罪 和 一切亵渎的话 都可得 赦免; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, ' 凡 亵渎 圣 灵的,却永 不 得 赦免,乃 要 担当 永远的 罪。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, '这话是因为 他们说:「他是 被污 鬼附著的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, '当下,耶稣的 母亲 和 弟兄 来, 站 在外边,打发 人 去叫 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, ' 有许多人 在耶稣 周围 坐著, 他们就告诉 他说:「看哪,你 母亲 和 你 弟兄 在外边 找 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, ' 耶稣回答 说:「谁 是 我的 母亲? 谁是我的 弟兄?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, ' 就四面观看 那 周围 坐著的人,说:「看哪,我的 母亲, 我的 弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, ' 凡 遵行  神 旨意 的人 就是 我的 弟兄 姊妹 和 母亲了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, ' 耶稣又 在 海边 教训人。 有许多人 到 他 那里聚集,他 只得 上 船 坐下。船在 海里, 众人 都靠近 海,站在 岸 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, ' 耶稣就用 比喻 教训 他们 许多道理。 在 教训之间,对他们 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, '「你们听啊! 有一个撒种的 出去 撒种。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, ' 撒的时候,有 落 在路 旁的, 飞鸟 来 吃尽了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, ' 有 落 在 土浅 石头地上的, 土 既 不 深,发苗 最快, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, ' 日头 出来 一晒,因为 没 有 根, 就枯干了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, ' 有 落 在荆棘 里的, 荆棘 长起来, 把它 挤住了, 就不 结 实; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, ' 又有 落 在 好 土里的, 就发生长大,结 实 有 三十倍的, 有 六十倍的, 有 一百倍的」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, ' 又说:「 有 耳 可听的,就应当听!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, ' 无人 的时候, 跟随 耶稣的人和 十二个 门徒问 他 这比喻的意思。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, ' 耶稣对他们 说:「 神 国的 奥秘 只叫 你们知道, 若是对外人讲,凡事 就用 比喻, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, ' 叫他们看 是看见, 却不 晓得; 听 是听见, 却不 明白;恐怕 他们 回转过来, 就得赦免。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, '又 对他们 说:「你们不 明白 这 比喻吗? 这样怎能 明白 一切的 比喻呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, '撒种之人 所撒 的就是道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, ' 那 撒 在路 旁 的,就是人听了 道, 撒但 立刻 来, 把撒 在 他 心里的道 夺了去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, ' 那 撒在 石头地上 的, 就是人 听了 道,立刻 欢喜 领受, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, '但 他心里 没 有 根,不过 是 暂时的,及至 为 道 遭了 患难,或是 受了逼迫,立刻就 跌倒了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, ' 还有 那 撒在 荆棘里的,就是 人 听 了道, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, '后来 有世上的 思虑、 钱财的 迷惑,和 别样的 私欲 进来,把道 挤住了,就 不能结实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, ' 那 撒 在好 地 上的,就是 人听 道,又 领受,并且 结实,有 三十倍的, 有 六十倍的, 有 一百倍的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, '耶稣又 对他们 说:「人拿 灯来, 岂是 要放在 斗 底下, 床 底下,不 放 在 灯台上吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, '因为 掩藏的事, 没有不显出来的; 隐瞒的事,没有 不露出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, ' 有 耳 可听的,就应当听!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, '又 说:「你们所听 的 要留心。你们用 什么 量器 量给人,也必用什么量器量 给你们,并且 要多给 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, '因为 有的,还要给 他; 没 有的, 连他所有的 也要夺去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, '又 说:「 神的 国 如同 人 把种 撒 在地 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, ' 黑夜 睡觉, 白日 起来, 这种 就发芽 渐长,那人 却不 晓得 如何这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, '地 生五谷 是出于 自然的:先 发苗,后 长穗,再后 穗 上 结成饱满的 子粒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, ' 谷 既熟了,就 用镰刀 去割,因为 收成 的时候到了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, '又 说:「 神的 国,我们可用什么 比较呢? 可用 什么 比喻 表明呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, '好像 一粒芥菜 种, 种 在地 里的时候,虽比 地 上 的百 种 都小, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, '但 种上以后,就长起来, 比各样的 菜 都大,又 长出 大 枝来,甚至 天上的 飞鸟 可以 宿 在它的 荫 下。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, ' 耶稣用许多 这样的 比喻,照 他们所能 听的,对他们 讲 道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, '若 不用 比喻,就不 对他们讲; 没有人的时候,就把一切的 道讲 给 门徒听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, ' 当 那 天 晚上,耶稣对门徒 说:「我们渡到 那边去吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, ' 门徒离开  众人, 耶稣仍在 船 上,他们就把他 一同带去;也 有 别的 船 和 他同行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, ' 忽然起了 暴 风, 波浪 打 入 船内,甚至 船 要 满了水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, ' 耶稣 在 船尾上,枕著 枕头 睡觉。 门徒叫醒了 他, 说:「夫子! 我们丧命,你 不 顾吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, ' 耶稣醒了,斥责 风, 向海 说:「住了吧!静了吧!」 风 就止住, 大大地 平静了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, ' 耶稣对他们 说:「为什么 胆怯?你们还没 有 信心吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, '他们就 大大地 惧 怕, 彼此 说:「这 到底 是 谁,连 风 和 海 也听从 他了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, ' 他们来 到 海 那边 格拉森人 的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, ' 耶稣 一 下 船,就有一个被污 鬼 附著 的人 从坟茔 里出来 迎著 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, '那人 常 住 在 坟茔里, 没有人 能 捆住 他,就是用铁链 也不能; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, '因为 人屡次 用脚镣 和 铁链 捆锁 他, 铁链 竟被 他 挣断了,脚镣 也 被他弄碎了;总 没有人 能 制伏 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, ' 他 昼 夜 常 在坟茔 里 和 山 中 喊叫, 又用石头 砍 自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, ' 他远远地 看见 耶稣,就跑过去 拜 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, ' 大 声 呼叫 说:「至高 神 的儿子 耶稣,我 与 你 有什么相干?我指著 神 恳求 你,不要 叫我 受苦!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, '是因 耶稣曾吩咐他 说:「污 鬼啊,从这人 身上出来吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, ' 耶稣问 他说:「你 名 叫什么?」 回答 说:「我 名叫『群』,因为 我们 多的缘故」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, '就 再三地 求 耶稣,不要 叫他们 离 开  那地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, ' 在那里 山坡上,有 一大 群 猪 吃食; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, '鬼就 央求 耶稣 说:「求你打发 我们 往 猪群里, 附 著 猪去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, ' 耶稣准了 他们,污 鬼 就 出来,进 入 猪里去。于 是 那群 猪闯 下 山崖,投在 海里, 淹死了。猪的数目约 有二千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, '放 猪的就 逃跑了, 去 告诉 城 里和 乡下的人。众人就 来,要看 是 什么 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, ' 他们来 到 耶稣那里, 看见 那被鬼附著的人,就是从前被群 鬼所附的,坐著,穿上衣服, 心里明白过来,他们就 害怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, ' 看见这事的,便将鬼附之人 所 遇见的 和 那群猪 的事 都告诉了 众人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, '众人就 央求 耶稣 离 开  他们的 境界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, ' 耶稣 上 船的时候,那从前被鬼附著的人 恳求 和耶稣 同 在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, ' 耶稣不 许,却 对他 说:「你回 家 去,到 你的亲属那里, 将主 为你 所做 的是何等大的事, 是怎样怜悯 你,都告诉 他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, '那人就 走了, 在 低加坡里 传扬 耶稣 为他 做了 何等大的事,众人 就 都希奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, ' 耶稣 坐 船 又 渡 到 那边去,就有许多 人 到 他 那里聚集; 他正在 海 边上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, ' 有一个 管会堂的人,名叫 睚鲁,来 见 耶稣,就 俯伏 在 他 脚前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, ' 再三地 求 他,说:「 我的 小女儿 快要死了,求你去 按 手 在她身上,使 她痊愈, 得以活了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, '耶稣就 和他 同 去。 有许多 人 跟随 拥挤 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, ' 有一个女人,患了 十二 年 的血 漏, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, ' 在 好些 医生 手里受了许多的 苦,又 花 尽了 她 所有的, 一点也不 见好,病势反 倒 更 重了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, '她听见 耶稣的事,就从后头 来,杂在 众人中间,摸 耶稣的 衣裳, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, '意思 说:「 我只 摸 他的 衣裳,就必痊愈。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, '于 是 她 血漏 的源头 立刻 干了;她便 觉得 身上 的 灾病 好了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, ' 耶稣 顿时 心里 觉得 有能力 从 自己 身上出去,就在 众人 中间转过来,说:「谁 摸 我的 衣裳?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, ' 门徒 对他 说:「你看 众人 拥挤 你,还 说『谁 摸 我』吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, ' 耶稣周围观看,要见 做 这事的女人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, ' 那女人 知道 在自己 身上所成的事,就恐惧 战 兢,来 俯伏在耶稣 跟前, 将实情 全 告诉 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, ' 耶稣对她 说:「女儿,你的 信 救了 你, 平平安安 地回去吧! 你的 灾病 痊愈了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, ' 还 说话的时候,有人从 管会堂的 家里来,说:「 你的 女儿 死了,何必 还 劳动 先生呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, ' 耶稣 听见 所说 的话,就对管会堂的 说:「不要 怕,只要 信!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, '于 是 带著 彼得、 雅各、和 雅各 的兄弟 约翰同去,不 许 别人 跟随 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, ' 他们来 到 管会堂的 家里; 耶稣看见 那里乱嚷,并 有人大大地 哭泣 哀号, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, ' 进到里面,就对他们 说:「为什么 乱嚷 哭泣呢?孩子 不是 死了,是 睡著了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, '他们就 嗤笑 耶稣。 耶稣 把他们都 撵出去,就带著 孩子的 父 母 和 跟随的人 进了 孩子 所在 的地方, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, '就 拉著 孩子的 手,对她 说:「大利大,古米!」(翻出来 就是 说:「闺女,我吩咐 你 起来!」) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, ' 那闺女 立时 起来 走。他们就 大大地 惊奇; 闺女已经 十二 岁了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, ' 耶稣切切地 嘱咐 他们, 不要 叫人知道 这事,又 吩咐 给 她 东西吃。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, ' 耶稣离开  那里, 来 到 自己的 家乡; 门徒 也 跟从 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, ' 到了 安息日,他 在 会堂 里教训人。 众人 听见,就甚希奇,说:「这人 从哪里 有这些事呢? 所赐给 他 的是什么 智慧? 他 手 所做 的是何等的 异能呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, '这 不 是 那木匠吗?不是马利亚的 儿子 雅各、 约西、 犹大、 西门的 长兄吗? 他 妹妹们 不 也是 在 我们 这里吗?」他们就厌弃他(厌弃他:原文是因 他 跌倒)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, ' 耶稣 对他们 说:「 大凡先知,除了 本 地、 亲属、 本 家之外,没有 不被人尊敬的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, '耶稣就 在那里 不 得 行 什么 异能,不过 按 手 在几个 病人身上,治好他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, '他也 诧异 他们 不信,就 往 周围 乡村 教训人去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, ' 耶稣叫了 十二个门徒来, 差遣 他们 两个 两个地出去,也 赐给 他们 权柄,制伏污 鬼; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, '并且 嘱咐 他们:「 行路 的时候 不要带 食物 和 口袋,腰袋 里 也不要带 钱,除了 拐杖 以外,什么都不要 带; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, '只要 穿 鞋,也 不要 穿 两件 褂子」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, '又 对他们 说:「你们无论 到何处,进了 人的家,就住在 那里,直到 离开  那地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, ' 何处的人 不 接待 你们,不 听 你们,你们离开  那里的时候,就把 脚 上 的尘土 跺下去,对他们 作 见证。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, '门徒就 出去 传道,叫 人悔改, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, '又 赶出 许多的 鬼, 用油 抹了 许多 病人, 治好他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, ' 耶稣 的名声 传扬出来。希律 王 听见了,就 说:「施洗 的约翰 从 死 里复活了, 所以 这些异能 由 他 里面发出来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, '但 别人 说:「是 以利亚。」又 有人 说:「是先知,正像 先知 中的一位。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, '希律 听见 却 说:「是 我 所斩的 约翰,他 复活了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, ' 先是希律 为他 兄弟 腓力 的妻子 希罗底 的缘故,差人去 拿住 约翰, 锁 在 监里,因为 希律已经娶了 那妇人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, ' 约翰 曾对希律 说:「你 娶 你 兄弟的 妻子 是不 合理的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, '于 是 希罗底 怀恨 他, 想要 杀 他,只是 不 能; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, '因为 希律 知道 约翰 是义 人, 是圣人,所以敬畏 他, 保护 他, 听 他讲论,就多照著行(有古卷:游移不定),并且 乐意 听 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, ' 有 一天,恰巧 是 希律 的生日,希律 摆设 筵席,请了 大臣 和 千夫长,并 加利利 作首领的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, ' 希罗底 的 女儿 进来 跳舞,使希律 和 同席的人 都欢喜。王 就对女子 说:「你随意 向我 求 什么, 我必给 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, '又 对她 起誓说:「随你向我 求 什么,就是 我 国 的一半,我也必给 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, '她就 出去 对她 母亲 说:「我可以求 什么呢?」 她母亲说:「施洗 约翰 的头。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, '她就 急忙 进去 见 王,求 他说:「我愿  王立时 把施洗 约翰 的头 放在 盘子 里给 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, '王 就 甚忧愁;但因 他所起的誓,又 因同席的 人,就不 肯 推辞, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, ' 随即 差 一个护卫兵,吩咐 拿 约翰的 头来。护卫兵就 去,在 监 里斩了 约翰, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, ' 把 头 放在 盘子里, 拿来 给 女子,女子 就 给 她 母亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, ' 约翰的 门徒 听见了,就 来 把他的 尸首 领去, 葬 在 坟墓里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, ' 使徒 聚集 到 耶稣那里,将一切 所 做的事、 所 传的道 全告诉 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, '他就 说:「你们 来, 同我暗暗地 到 旷野 地方 去歇一歇。」这是 因为 来 往 的人多,他们连吃饭 也 没有 工夫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, '他们就 坐船,暗暗地 往 旷野 地方 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, ' 众人看见 他们 去, 有许多 认识他们的,就 从 各 城 步行,一同跑 到那里, 比他们 先赶到了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, ' 耶稣出来,见 有许多 的人,就 怜悯 他们,因为 他们 如同 羊 没 有 牧人一般,于 是 开 口 教训 他们 许多道理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, ' 天 已经 晚了, 门徒 进前来,说:「这是 野 地, 天 已经 晚了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, '请叫众人 散开 ,他们好 往 四面 乡 村里去,自己 买  什么 吃。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, '耶稣回答 说:「你们 给 他们 吃吧。」 门徒 说:「我们可以去 买  二十两 银子 的饼 给 他们 吃吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, ' 耶稣 说:「你们有 多少 饼,可以去 看看。」 他们知道了,就说:「五个饼, 两条 鱼。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, ' 耶稣吩咐 他们,叫众人 一帮 一帮 地坐 在 青 草地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, '众人就 一排 一排 地坐下,有 一百一排的, 有 五十一排的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, ' 耶稣拿著 这五个 饼, 两条 鱼,望著 天 祝福, 擘开  饼, 递给 门徒, 摆 在众人面前,也 把那两条 鱼 分给 众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, ' 他们都 吃,并且 吃饱了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, '门徒就 把碎饼 碎 鱼 收拾起来,装满了 十二个 篮子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, ' 吃 饼 的男人 共有 五千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, ' 耶稣随即 催 门徒 上 船, 先渡 到 那边 伯赛大去,等 他 叫众人 散开 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, '他既 辞别了 他们,就往 山上 去 祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, ' 到了 晚上,船 在 海 中, 耶稣 独自 在 岸上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, ' 看见 门徒 因 风 不顺, 摇橹 甚苦。夜里 约有 四 更天,就在 海 面上走,往 他们 那里去, 意思要 走过他们 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, '但 门徒看见 他 在 海 面上走,以为 是 鬼怪,就 喊叫起来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, '因为 他们都 看见了 他,且 甚惊慌。 耶稣连忙 对 他们 说:「你们放心!是 我,不要 怕!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, '于 是 到 他们那里,上了 船,风 就 住了; 他们心里 十分 惊奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, '这是因为 他们不 明白 那分饼的事, 心里 还是 愚顽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, '既 渡过去,来 到 革尼撒勒 地方,就 靠了岸, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, ' 一下 船, 众人认得 是耶稣, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, '就跑遍 那一带地方,听见 他在何处, 便将有 病的人 用 褥子 抬到 那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, ' 凡 耶稣所到 的地方,或 村中,或 城里,或 乡间,他们都将病人 放 在 街市上, 求 耶稣 只 容他们摸 他的 衣裳 䍁子; 凡 摸著的 人就都好了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, ' 有法利赛人 和 几个 文士 从 耶路撒冷 来,到 耶稣 那里聚集。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, ' 他们曾看见 他的 门徒 中有人 用俗手,就是 没有洗的 手,吃 饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, '(原来 法利赛人 和 犹太人 都 拘守 古人 的遗传,若 不 仔细 洗 手 就不 吃饭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, ' 从 市上来,若 不 洗浴 也不 吃饭;还 有 好些 别的规矩, 他们历代拘守,就是洗 杯、 罐、 铜器等物。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, ' 法利赛人 和 文士 问 他说:「你的 门徒 为什么 不 照 古人 的遗传, 用俗 手 吃 饭呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, ' 耶稣 说:「 以赛亚 指著 你们 假冒为善之人 所说的预言 是不错的。如 经上说:这 百姓 用嘴唇 尊敬 我, 心 却 远 离 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, '他们将人 的吩咐 当作道理 教导人,所以 拜 我 也是枉然。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, '你们是离弃 神的 诫命,拘守 人的 遗传」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, '又 说:「你们诚然 是废弃 神的 诫命,要 守 自己的 遗传。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, ' 摩西 说:『当孝敬 父 母』;又说:『咒骂 父 母的,必治 死他。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, '你们 倒 说:『人 若 对父 母 说:我 所 当 奉给你的,已经作了各耳板』(各耳板 就是 供献的意思), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, '以后你们就不容 他 再 奉养 父 母。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, '这就是你们 承接 遗传,废了 神的 道。你们还 做 许多 这样的事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, '耶稣又 叫 众人来,对他们 说:「你们都 要听 我的话,也要 明白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, '从 外面 进去的 不 能 污秽 人,惟有 从 里面 出来的 乃能 污秽 人。」(有古卷加: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, ' 有 耳 可听的,就应当听!) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, ' 耶稣离开  众人,进了 屋子, 门徒 就问 他 这比喻的意思。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, ' 耶稣对他们 说:「你们 也 是 这样 不明白吗?岂不 晓得 凡 从外面 进入 的,不 能 污秽 人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, '因为 不是 入 他的 心,乃是 入 他的肚腹,又 落 到 茅厕里。(这是说,各样的 食物 都是洁净的)」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, '又 说:「 从 人 里面出来的,那 才能污秽 人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, '因为 从里面,就是从 人 心里,发出 恶 念、苟合、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, '偷盗、凶杀、奸淫、贪婪、邪恶、诡诈、淫荡、嫉妒、谤讟、骄傲、狂妄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, '这 一切的 恶 都是从里面 出来,且 能污秽 人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, ' 耶稣从那里 起身,往 泰尔、西顿的境内 去, 进了 一家,不 愿 意 人知道,却 隐藏 不 住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, ' 当下,有一个妇人, 她的 小女儿 被污 鬼 附著,听见 耶稣的事,就来 俯伏 在 他 脚前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, ' 这妇人 是 希腊人,属叙利腓尼基 族。 她求 耶稣 赶出 那鬼 离开  她的 女儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, ' 耶稣对她 说:「让 儿女们 先 吃饱, 不 好 拿 儿女的 饼 丢给 狗吃。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, ' 妇人回答 说:「主啊,不错;但是 狗 在桌子 底下 也吃 孩子们的 碎渣儿。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, ' 耶稣对她 说:「因 这句 话,你回去吧;鬼 已经离开  你的 女儿了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, '她就 回 家去,见 小孩子 躺 在 床上,鬼 已经出去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, ' 耶稣又 离了 泰尔 的境界,经过 西顿,就从 低加坡里 境 内 来 到 加利利 海。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, ' 有人带著 一个耳聋 舌结 的人来见耶稣, 求 他 按 手 在他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, ' 耶稣领 他 离开  众人,到 一边去,就用 指头 探 他的 耳朵, 吐唾沫 抹 他的 舌头, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, ' 望 天 叹息, 对他 说:「以法大!」就是说:「开 了吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, ' 他的 耳朵 就 开 了, 舌 结 也 解了,说话 也 清楚了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, ' 耶稣嘱咐 他们 不要告诉 人;但 他 越发 嘱咐,他们 越发 传扬开 了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, ' 众人分外 希奇,说:「他所做 的事都 好,他连聋子 也 叫 他们听见,哑巴 也 叫他们说话。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, ' 那 时,又 有 许多人聚集,并 没 有 什么 吃的。耶稣叫 门徒来,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, '「我怜悯 这众人;因为 他们同 我 在这里已经 三 天,也 没 有 吃的了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, ' 我若 打发 他们 饿著 回 家,就必在 路上 困乏, 因为其中 有 从 远处 来的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, ' 门徒 回答 说:「在 这 野地, 从哪里 能 得饼,叫这些人 吃饱呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, ' 耶稣问 他们说:「你们有 多少 饼?」 他们说:「七个。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, ' 他吩咐 众人 坐 在 地上,就 拿著 这七个 饼 祝谢了,擘开 , 递给 门徒,叫 他们摆开 ,门徒就 摆 在众人面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, '又 有 几条 小鱼; 耶稣祝了福,就吩咐 也 摆在众人面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, ' 众人都吃,并且 吃饱了, 收拾 剩下的 零碎,有七 筐子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, ' 人数约 有 四千。 耶稣打发他们 走了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, ' 随即 同 门徒 上 船,来 到 大玛努他 境内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, ' 法利赛人 出来 盘问 耶稣,求 他 从 天上 显个神迹给他们看,想要试探 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, ' 耶稣 心里 深深地叹息,说:「这 世代 为什么 求 神迹呢?我实在 告诉 你们,没有 神迹 给 这 世代看。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, '他就 离开  他们,又 上 船往 海那边 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, ' 门徒忘了 带 饼; 在 船上 除了 一个 饼,没 有 别的食物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, ' 耶稣嘱咐 他们 说:「你们要谨慎,防备 法利赛人 的酵 和 希律 的酵。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, ' 他们 彼此 议论说:「这是因为 我们没 有 饼吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, ' 耶稣看出来,就说:「你们为什么 因为 没 有 饼 就议论呢?你们还不 省悟,还不 明白吗?你们的 心 还是 愚顽吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, '你们有 眼睛,看不 见吗? 有 耳朵,听不 见吗?也 不 记得吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, ' 我擘开  那五个 饼 分给 五千人,你们收拾的 零碎 装满了 多少 篮子呢?」他们说:「十二个。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, '「又 擘开 那七个 饼分给 四千人,你们收拾 的零碎 装满了 多少 筐子呢?」 他们 说:「七个。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, ' 耶稣说:「你们还是不 明白吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, ' 他们来 到 伯赛大, 有人带 一个瞎子 来, 求 耶稣 摸 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, ' 耶稣拉著 瞎子的 手,领 他 到村 外,就 吐唾沫 在 他 眼睛上,按 手 在他身上,问 他说:「 你看见 什么了?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, '他就 抬头一看,说:「我看见 人了; 他们好像 树木, 并且行走。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, '随后 又 按 手 在 他 眼睛上, 他定睛一看,就 复了原, 样样 都看 得清楚了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, ' 耶稣打发 他 回 家,说:「连 这村子 你也不要 进去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, ' 耶稣 和 门徒 出去,往 凯撒利亚•腓立比 村庄去; 在 路上 问 门徒 说:「人 说 我 是 谁?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, ' 他们说:「有人说是施洗 的约翰; 有人 说是以利亚;又 有人 说 是先知 里的一位。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, '又 问 他们说:「 你们 说 我 是 谁?」彼得 回答 说:「你 是 基督。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, '耶稣就 禁戒 他们, 不要 告诉人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, ' 从此,他教训 他们说:「 人 子 必须 受许多的 苦, 被 长老、 祭司长,和 文士 弃绝,并且 被杀, 过 三 天 复活。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, ' 耶稣明明地 说 这话,彼得 就 拉著 他, 劝 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, ' 耶稣转过来, 看著 门徒,就责备 彼得 说:「撒但,退我 后边 去吧!因为 你不 体贴 神的意思,只 体贴人的意思。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, '于 是 叫 众人 和 门徒来,对他们 说:「若 有人 要 跟 从 我,就当舍 己, 背起 他的 十字架 来 跟从 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, '因为, 凡 要 救 自己 生命(或译:灵魂;下同)的,必丧掉 生命; 凡 为 我 和 福音 丧掉 生命的,必救了 生命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, ' 人 就是赚得 全 世界, 赔上 自己的 生命,有什么 益处呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, '人 还能 拿 什么 换 生命呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, ' 凡 在 这 淫乱 罪恶 的世代,把我 和 我的 道 当作可耻的,人 子 在他 父 的荣耀 里,同 圣 天使 降临 的时候,也 要把那人 当作可耻的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, '耶稣又 对他们 说:「我实在 告诉 你们, 站 在这里的, 有人 在没 尝 死 味以前,必要看见 神的 国 大有 能力 临到。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, ' 过了 六 天,耶稣 带著 彼得、 雅各、 约翰 暗暗地 上了 高 山,就 在他们 面前 变了形像, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, ' 衣服 放光,极其 洁白, 地上 漂布的,没有 一个能 漂得 那样白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, '忽然,有以利亚 同 摩西 向他们 显现,并且 和耶稣 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, ' 彼得 对耶稣 说:「拉比(就是夫子),我们 在 这里 真好! 可以搭 三座 棚,一座 为你, 一座 为摩西, 一座 为以利亚。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, ' 彼得不 知道 说 什么才好,因为 他们甚是 惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, ' 有 一朵云彩 来遮盖 他们;也 有 声音 从 云彩里出来,说:「这 是 我的 爱 子,你们要听 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, ' 门徒忽然 周围一看,不再 见 一人, 只 见耶稣 同 他们在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, ' 下 山的时候,耶稣嘱咐 他们说:「 人 子 还没有 从 死 里复活,你们不要 将所 看见 的告诉人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, ' 门徒将这话 存记 在 心,彼此议论「从 死 里复活」是什么 意思。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, '他们就 问 耶稣 说:「文士 为什么 说 以利亚 必须 先 来?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, ' 耶稣 说:「以利亚 固然 先 来 复兴 万事; 经上不是 指著 人 子 说, 他要受许多的 苦 被人轻慢呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, ' 我告诉 你们, 以利亚 已经 来了,他们也 任意 待 他,正如 经上所指著 他 的话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, ' 耶稣到了 门徒那里,看见 有许多 人 围著 他们,又有 文士 和 他们 辩论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, ' 众 人 一 见 耶稣,都甚希奇,就 跑上去 问他 的安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, ' 耶稣 问他们说:「你们和 他们 辩论 的是什么?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, ' 众人 中间 有一个人 回答说:「夫子,我带了 我的 儿子 到 你这里来,他被哑巴 鬼 附著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, ' 无论 在哪里,鬼捉弄 他,把他 摔倒,他就 口中流沫, 咬 牙切齿, 身体枯干。 我请过 你的 门徒 把鬼 赶出去,他们却是 不 能。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, '耶稣 说:「嗳!不信的 世代啊,我在 你们 这里 要到 几时呢?我忍耐 你们 要到 几时呢?把他 带 到 我这里来吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, '他们就 带了 他 来。 他一 见 耶稣,鬼 便叫他 重重地抽疯, 倒 在 地上,翻来覆 复去,口中流沫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, ' 耶稣问 他 父亲说:「 他 得 这 病有 多少 日子呢?」 回答说:「从 小的时候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, ' 鬼屡次 把他 扔 在 火里、 水里,要 灭 他。 你若 能 做什么,求你怜悯 我们,帮助 我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, ' 耶稣 对他 说:「你若 能信,在信的人,凡事 都能。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, '孩子 的父亲 立时 喊著 说(有古卷:立时流泪地喊著说):「我信!但我 信不足,求主帮助。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, ' 耶稣 看见 众人 都跑上来,就斥责 那污 鬼,说:「你这聋 哑 的鬼,我 吩咐 你 从 他 里头出来, 再不要 进去!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, ' 那鬼喊叫, 使孩子大大地 抽了一阵疯,就出来了。 孩子 好像 死了一般。以致 众人 多半说:「他是死了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, '但 耶稣 拉著 他的 手,扶他 起来,他就 站起来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, ' 耶稣 进了 屋子, 门徒 就暗暗地 问 他说:「我们 为什么 不 能 赶出 他去呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, ' 耶稣说:「 非 用 祷告(有古卷加:禁食二字),这 一类的 鬼总不 能 出来(或译:不能赶他出来)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, '他们离开  那地方,经过 加利利; 耶稣不 愿 意 人 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, '于 是 教训 门徒, 说:「 人 子 将要被交 在 人 手里, 他们要杀害 他; 被杀以后,过 三 天 他要复活。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, '门徒却 不明白 这话,又 不敢 问 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, ' 他们来 到 迦百农。 耶稣在 屋 里 问 门徒说:「你们在 路 上议论 的是什么?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, ' 门徒不作声,因为 他们在 路 上彼此 争论 谁 为大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, ' 耶稣坐下,叫 十二个门徒来, 说:「若 有人 愿 意 作 首先的,他必作 众人 末后的, 作众人的 用人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, '于 是 领过 一个小孩子来,叫他 站 在 门徒 中间,又 抱起 他来,对他们 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, '「凡 为 我 名 接待 一个 像这 小孩子的,就是接待 我; 凡 接待 我的,不是 接待 我,乃是 接待那差 我来的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, '约翰 对耶稣 说:「夫子,我们看见 一个人 奉 你的 名 赶 鬼,我们就 禁止 他,因为 他不 跟从 我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, ' 耶稣 说:「不要 禁止 他;因为 没 有 人 奉 我 名 行 异能,反倒 轻易 毁谤 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, ' 不 敌挡 我们的,就是 帮助 我们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, ' 凡 因 你们是属 基督, 给你们 一杯 水 喝的,我实在 告诉 你们,他不能 不得 赏赐。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, '「 凡 使这信 我 的一个 小子 跌倒的,倒不如 把 大磨石 拴 在 这人的 颈项上, 扔 在 海里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, ' 倘若 你 一只手 叫你 跌倒,就把它 砍下来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, '你缺了肢体 进 入 永生,强如 有 两只 手 落 到 地狱,入 那不灭的 火里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, ' 倘若 你 一只脚 叫你 跌倒,就把它 砍下来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, '你瘸腿 进 入 永生,强如 有 两只 脚 被丢 在 地狱里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, ' 倘若 你 一只眼 叫你 跌倒,就去掉 它;你只有一只眼 进 入 神的 国,强如 有 两只 眼 被丢 在 地狱里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, '在那里, 虫 是不 死的, 火 是不 灭的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, '因为 必用火 当盐腌 各人。(有古卷加:凡祭物必用盐腌。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, '盐 本是好的, 若 失了 味,可用 什么 叫它 再咸呢?你们 里头 应当有 盐, 彼此 和睦。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, ' 耶稣从那里 起身,来 到 犹太 的境界 并 约旦河 外。 众人 又 聚集 到 他那里, 他又 照 常 教训 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, ' 有法利赛人 来 问 他说:「人 休 妻 可以 不可以?」意思要试探 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, ' 耶稣回答 说:「摩西 吩咐 你们 的是什么?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, ' 他们说:「摩西 许 人写了 休 书 便 可以休妻。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, ' 耶稣 说:「摩西因为 你们的 心硬,所以写 这 条例 给你们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, '但 从 起初 创造的时候, 神造 人 是造男 造女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, '因 此,人 要离开  父 母, 与 妻子 连合, 二 人成 为 一 体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, '既然如此,夫妻不再 是 两个人,乃 是一 体的了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, '所以, 神 配合 的,人 不可 分开 。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, ' 到了 屋里,门徒 就 问 他 这事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, ' 耶稣对他们 说:「凡 休 妻 另 娶的,就是犯奸淫,辜负 他的妻子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, '妻子 若 离弃 丈夫 另 嫁,也是犯奸淫了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, ' 有人带著 小孩子 来见耶稣,要 耶稣 摸 他们,门徒 便 责备那些人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, ' 耶稣 看见 就恼怒, 对门徒 说:「让 小孩子 到 我 这里来,不要 禁止 他们;因为在 神 国的,正是 这样的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, '我实在 告诉 你们,凡 要承受 神 国的,若不 像 小孩子,断不能 进 去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, ' 于 是抱著 小孩子,给 他们 按 手,为他们祝福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, ' 耶稣出来 行路的时候,有一个 人跑来, 跪 在他面前,问 他说:「良善的 夫子,我当做 什么事 才 可以承受 永 生?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, ' 耶稣 对他 说:「你为什么 称 我 是良善的?除了 神 一位之外,再没有 良善的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, '诫命 你是晓得的:不可 杀人;不可 奸淫;不可 偷盗;不可 作假见证;不可 亏负人;当孝敬 父 母。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, ' 他对耶稣 说:「夫子,这 一切 我 从 小 都遵守了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, ' 耶稣 看著 他,就爱 他, 对他 说:「你 还缺少 一件:去 变卖 你所 有的, 分给 穷人,就 必有 财宝 在 天上; 你还要来 跟从 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, ' 他听见 这话,脸上就变了色,忧忧愁愁地 走了,因为 他 的产业 很多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, ' 耶稣 周围一看,对 门徒 说:「有 钱财 的人进 神 的国 是何等地 难哪!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, ' 门徒 希奇 他的 话。 耶稣 又 对 他们 说:「小子,倚靠钱财的人进 神的 国 是 何等地 难哪! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, '骆驼 穿 过 针的 眼,比 财主 进 神的 国 还 容易呢。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, ' 门徒就分外 希奇,对 他 说:「这样 谁 能 得救呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, '耶稣 看著 他们,说:「在 人 是不能,在 神 却 不然,因为 神 凡事 都能。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, '彼得 就 对他 说:「看哪,我们 已经撇下 所有的 跟从 你了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, '耶稣 说:「我实在 告诉 你们, 人 为 我 和 福音 撇下 房屋,或是 弟兄、 姊妹、 父 母、 儿女、 田地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, '没有不 在 今 世 得 百倍的,就是房屋、 弟兄、 姊妹、 母亲、 儿女、 田地,并且要受 逼迫, 在 来 世 必得永 生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, '然而,有许多 在前的,将要在 后, 在后的,将要在前。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, ' 他们行 路 上 耶路撒冷去。 耶稣 在 前头 走, 门徒就希奇, 跟从 的人也害怕。 耶稣又 叫 过十二个门徒来,把自己 将要 遭遇 的事 告诉 他们说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, '「看哪,我们上 耶路撒冷去, 人 子 将要被交给 祭司长 和 文士, 他们要定 他 死罪, 交给 外邦人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, ' 他们要戏弄 他, 吐唾沫 在他脸上, 鞭打 他, 杀害他。 过了 三 天,他要复活。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, ' 西庇太的 儿子 雅各、 约翰 进前来,对耶稣 说:「夫子,我们无论 求 你 什么,愿  你给我们 做。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, ' 耶稣说:「要 我 给你们 做 什么?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, ' 他们说:「赐 我们 在 你的 荣耀里,一个 坐 在 你 右边, 一个 坐在 你左边。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, ' 耶稣 说:「你们不 知道 所求的 是什么,我 所 喝 的杯,你们能 喝吗? 我 所 受 的洗,你们能受吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, ' 他们说:「我们能。」 耶稣 说:「我 所 喝的 杯,你们也要喝; 我 所 受的 洗,你们也要受; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, '只是 坐 在我的 左 右,不 是 我 可以赐的,乃是 为谁 预备的,就赐给谁。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, '那 十个 门徒听见,就 恼怒 雅各、 约翰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, ' 耶稣 叫 他们来,对他们 说:「你们知道, 外邦人 有尊 为君王的,治理 他们, 有 大臣 操权管束 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, '只是 在 你们中间,不 是 这样。 你们 中间,谁 愿  为 大,就必作 你们的 用人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, ' 在 你们中间,谁 愿  为 首,就必作 众人的 仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, '因为 人 子 来,并 不是 要受人的服事,乃是 要服事人,并且 要舍 命 作 多人的 赎价。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, ' 到 了 耶利哥; 耶稣 同 门徒 并 许多 人 出 耶利哥的时候,有一个讨饭的 瞎子,是底买 的 儿子 巴底买 ,坐 在 路旁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, ' 他听见 是 拿撒勒的 耶稣,就 喊 著 说:「大卫的 子孙 耶稣啊!可怜 我吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, ' 有许多人 责备 他, 不许他作声。他却 越发 大 声喊著说:「大卫的 子孙哪,可怜 我吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, ' 耶稣 就站住,说:「叫 过他来。」他们就 叫 那瞎子,对他 说:「放心,起来!他叫 你啦。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, '瞎子就 丢下 衣服,跳起来,走 到 耶稣那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, ' 耶稣 说:「要 我为你 做 什么?」 瞎子 说:「拉波尼(就是夫子), 我要能看见。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, ' 耶稣 说:「你去吧!你的 信 救了 你了。」 瞎子立刻 看见了,就 在 路 上跟随 耶稣。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, ' 耶稣和门徒将近 耶路撒冷,到了 伯法其 和 伯大尼,在 橄榄 山那里;耶稣就打发 两个 门徒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, ' 对他们 说:「你们 往 对面 村子 里去, 一 进 去的时候,必看见 一匹驴驹 拴在那里, 是从来没有 人 骑过的,可以解开 , 牵来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, ' 若 有人 对你们 说:『为什么 做 这事?』你们就说:『主 要 用 牠。』 那人必立时 让你们牵来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, ' 他们去了,便 看见 一匹驴驹 拴 在 门 外 街道 上,就 把牠 解开 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, ' 在那里 站著的人,有几个 说:「你们解 驴驹 做 什么?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, ' 门徒照著 耶稣 所说的 回答,那些人就 任凭 他们牵去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, ' 他们把驴驹 牵 到 耶稣那里, 把自己的 衣服 搭在 上面,耶稣就 骑 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, ' 有许多 人把 衣服 铺 在 路上,也 有人 把田间 的树枝 砍 下来,铺在路上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, ' 前行 后随 的人都喊著说:和散那(和散那:原有求救的意思,在此乃是称颂的话)!奉 主 名 来的 是应当称颂的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, '那将要来的 我 祖 大卫之 国 是应当称颂的!高高在 上 和散那! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, '耶稣进 了 耶路撒冷, 入了 圣殿, 周围看了 各样物件。天色 已 晚,就和 十二个 门徒出城,往 伯大尼去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, ' 第二天,他们 从 伯大尼 出来,耶稣饿了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, ' 远远地 看见 一棵无花果树,树上有 叶子,就往那里去,或者 在 树 上可以找著 什么。 到 了 树下,竟找 不著什么,不过 有叶子,因为 不 是 收无花果 的时候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, '耶稣就 对树 说:「从今以后,永 没有人 吃 你 的 果子。」他的 门徒 也 听见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, ' 他们来 到 耶路撒冷。 耶稣进 入 圣殿, 赶出 殿 里 做买  卖的人, 推倒 兑换银钱 之人的桌子 和 卖 鸽子 之人的凳子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, '也 不 许 人 拿著 器具 从殿里 经过; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, '便 教训 他们 说:「经上不是 记著 说:我的 殿 必称为 万 国 祷告的 殿吗?你们 倒 使 它 成为贼 窝了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, ' 祭司长 和 文士 听见这话,就 想 法子 要除灭 耶稣,却 又怕 他,因为 众人 都 希奇 他的 教训。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, ' 每天晚上,耶稣出 城 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, ' 早晨,他们从那里经过,看见 无花果树 连 根 都枯干了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, ' 彼得 想起耶稣的话来,就对他 说:「拉比,请看!你所 咒诅的 无花果树 已经枯干了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, ' 耶稣 回答 说:「你们当 信服 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, '我实在 告诉 你们, 无论何人 对这 座山 说:『你挪开 此地, 投 在 海里!』 他 若心 里 不 疑惑,只 信 他所 说的 必成,就必给他 成了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, '所以 我告诉 你们,凡你们 祷告 祈求的,无论 是什么,只要信 是 得著的, 就必得著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, ' 你们站著 祷告 的时候,若 想起有人 得罪 你们,就当饶恕他,好叫 你们 在 天上 的父 也 饶恕 你们 的 过犯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, ' 你们 若 不 饶恕人,你们 在 天上 的父 也不 饶恕 你们的 过犯。(有古卷无此节)」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, ' 他们又 来 到 耶路撒冷。 耶稣 在 殿 里行走的时候,祭司长 和 文士 并 长老 进 前来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, ' 问他 说:「你仗著 什么 权柄 做 这些事? 给 你 这 权柄 的是谁呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, ' 耶稣 对他们 说:「我要问 你们 一 句话, 你们回答 我,我就 告诉 你们 我仗著 什么 权柄 做 这些事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, '约翰的 洗礼 是 从 天上来的?是 从 人间来的呢?你们可以回答 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, ' 他们彼此 商议 说:「我们若 说『从 天上来』,他必说:『这样,你们为什么 不 信 他呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, ' 若说『从 人间来』,却又怕 百姓,因为 众人 真 以 约翰 为 先知。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, '于 是 回答 耶稣 说:「我们不 知道。」 耶稣 说:「我 也不 告诉 你们 我仗著 什么 权柄 做 这些事。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, ' 耶稣就 用 比喻 对他们 说:「有人 栽了 一个葡萄园, 周围圈上 篱笆, 挖了 一个压酒池, 盖了 一座楼, 租给 园户,就 往外国去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, ' 到了时候,打发 一个仆人 到 园户那里,要 从 园户 收 葡萄园 的 果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, ' 园户拿住 他,打了他, 叫他 空手回去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, ' 再 打发 一个 仆人 到 他们那里。他们 打伤他的头,并且 凌辱他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, ' 又打发 一个仆人去,他们就杀了 他。后又 打发好些 仆人去,有 被他们打的, 有 被他们杀的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, '园主还 有 一位 是他的爱 子,末后 又打发 他 去,意思说:『他们必尊敬 我的 儿子。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, '不料,那些 园户 彼此 说:『这 是 承受产业的。来吧,我们杀 他,产业 就 归 我们了!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, '于 是 拿住 他,杀了他, 把他 丢在 园 外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, '这样,葡萄园的 主人 要怎么 办呢?他要来 除灭 那些园户, 将葡萄园 转给 别人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, '经上写著说:匠人 所 弃 的石头,已作 了 房角 的 头块石头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, '这 是主 所做的, 在 我们 眼 中看为 希奇。这 经 你们没有 念过吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, ' 他们看出 这 比喻 是指著 他们 说的,就 想要 捉拿 他,只是 惧怕 百姓,于 是 离开  他 走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, '后来,他们打发 几个 法利赛人 和 几个希律党的人 到 耶稣那里,要 就著他的话 陷害 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, ' 他们来了,就对他 说:「夫子,我们知道 你是 诚实的, 什么人 你 都不 徇情面;因为 你不 看 人 的 外貌,乃是 诚诚实实 传 神的 道。纳 税 给凯撒 可以 不可以? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, '我们该纳 不该 纳?」 耶稣知道 他们的 假意,就对他们 说:「你们为什么 试探 我?拿 一个银钱 来 给我 看!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, '他们就 拿了来。 耶稣说:「这 像 和 这号 是谁的?」 他们说:「是凯撒的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, ' 耶稣 说:「 凯撒的 物当归给 凯撒, 神的物当归给 神。」他们就 很希奇 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, ' 撒都该人 常说 没 有 复活的事。他们 来 问 耶稣 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, '「夫子,摩西 为我们 写著 说:『人 若 死了, 撇下 妻子, 没有 孩子,他兄弟 当 娶 他的 妻, 为 哥哥 生子 立后。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, '有 弟兄 七人, 第一个 娶了 妻, 死了,没有 留下 孩子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, ' 第二个 娶了 她,也 死了,没有 留下 孩子。 第三个 也是这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, ' 那七个 人都没有 留下 孩子;末了,那妇人 也 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, '当 复活的时候, 她是 哪一个的 妻子呢?因为 他们 七个人 都娶过 她。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, '耶稣 说:「你们所以错了,岂不是 因为 不 明白 圣经,不晓得 神的 大能吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, ' 人从 死 里复活,也不 娶 也不 嫁,乃 像 天上 的 使者一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, ' 论到 死人 复活,你们没有 念过 摩西的 书 荆棘 篇上所载的吗? 神 对摩西 说:『我是 亚伯拉罕的 神, 以撒的 神, 雅各的 神。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, '神 不 是 死人的 神,乃 是活人的 神。你们是大 错了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, ' 有一个 文士 来,听见 他们 辩论,晓得 耶稣回答 的好,就问 他说:「 诫命 中哪 是 第一要紧的呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, '耶稣 回答 说:「第一 要紧的就是说:『以色列啊,你要听,主─我们 神 是 独一的 主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, ' 你要 尽 心、 尽 性、 尽 意、 尽 力 爱 主─你的 神。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, '其次 就是说:『要爱 人 如 己。』再 没 有 比这两条 诫命 更大的了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, ' 那文士 对耶稣 说:「夫子 说, 神是 一位, 实在 不错; 除了 他 以外,再没有 别的 神; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, '并且 尽 心、 尽 智、 尽 力 爱 他,又 爱 人 如 己,就 比一切 燔祭 和 各样祭祀 好的多。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, ' 耶稣 见 他 回答 的有智慧,就对他 说:「你 离 神的 国 不 远了。」从此以后,没有人 敢 再问 他 什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, ' 耶稣 在 殿 里教训人,就问 他们说:「文士 怎么 说 基督 是 大卫的 子孙呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, '大卫 被 圣 灵感动,说:主 对我 主 说,你坐 在 我的 右边,等 我使 你 仇敌 作你的 脚 凳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, '大卫 既自己 称 他 为主, 他怎么 又是 大卫的 子孙呢?」 众 人 都喜欢 听 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, ' 耶稣 在 教训之间,说:「你们要防备 文士; 他们好 穿 长衣 游行, 喜爱人在 街市 上问他们的安, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, '又 喜爱会堂 里 的高位, 筵席 上 的首座。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, '他们侵吞 寡妇的 家产, 假意 作很长的 祷告。这些人 要受 更重的 刑罚!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, ' 耶稣对 银库 坐著,看 众人 怎样 投 钱 入 库。 有好些 财主 往里投了 若干的钱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, ' 有一个 穷 寡妇 来,往里投了 两个 小钱, 就是 一个大钱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, ' 耶稣 叫 门徒来,说:「我实在 告诉 你们, 这 穷 寡妇 投 入 库里的,比众人 所投的 更多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, '因为,他们 都是 自己有余 馀,拿出来 投在里头;但 这寡妇 是 自己 不足,把她 一切 养生 的 都 投上了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, ' 耶稣 从 殿 里出来的时候,有一个 门徒 对他 说:「夫子,请看,这是何等的 石头! 何等的 殿宇!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, ' 耶稣 对他 说:「你看见 这 大 殿宇吗?将来在这里 没有 一块石头 留在 石头 上, 不 被拆毁了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, ' 耶稣 在 橄榄 山 上对 圣殿 而坐,彼得、 雅各、 约翰,和 安得烈 暗暗地 问 他说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, '「请告诉 我们,什么时候 有 这些事呢? 这一切 事 将 成的 时候 有什么 预兆呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, ' 耶稣 说:「你们要谨慎,免得 有人 迷惑 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, '将来有好些人 冒 我的 名 来,说:『 我 是基督』,并且 要迷惑 许多人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, ' 你们听见 打仗 和 打仗 的风声,不 要惊慌。这些事是必须 有的,只是 末期 还没有到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, ' 民 要 攻打 民, 国 要攻打 国;多 处 必有 地震、 饥荒。这都是灾难(灾难:原文是生产之难)的起头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, '但 你们 要谨慎;因为人要把你们 交 给 公会,并且 你们在 会堂 里要受鞭打,又 为 我的 缘故站在 诸侯 与 君王 面前,对 他们 作见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, '然而,福音 必须 先 传 给 万 民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, ' 人把你们 拉去 交 官的时候,不要 预先思虑 说 什么; 到 那 时候, 赐给 你们 什么话,你们就 说什么;因为 说话的 不 是 你们,乃是 圣 灵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, ' 弟兄 要把弟兄, 父亲 要把儿子,送 到 死地; 儿女 要起来 与父母 为敌, 害死 他们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, '并且 你们要 为 我的 名 被 众人 恨恶。惟有 忍耐 到 底的, 必然得救。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, '「 你们看见 那行毁坏 可憎的,站在 不 当 站的地方(读 这经的人须要会意)。那时,在 犹太的,应当逃 到 山上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, ' 在 房上的,不 要下来,也不 要进 去拿 家 里的东西; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, ' 在 田里的,也不要 回 去 取 衣裳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, ' 当 那些 日子, 怀孕的 和 奶孩子 的有祸了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, '你们应当 祈求,叫 这些事不 在冬天 临到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, '因为 在那些 日子 必有 灾难,自从 神 创造 万物 直到 如今,并没 有 这样的灾难,后来也 必没 有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, ' 若 不是 主 减少 那日子,凡有血气的,总没 有 一个得救的;只是 为 主的选 民,他将那日子 减少了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, ' 那时 若 有人 对你们 说:『看哪,基督 在这里』,或说:『 基督在那里』,你们不要 信! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, '因为 假基督、 假先知 将要起来, 显 神迹 奇事,倘若 能行,就把 选民 迷惑了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, ' 你们 要谨慎。看哪,凡事 我都预先告诉 你们了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, '「 在 那些 日子,那 灾难 以后,日头 要变黑了,月亮 也 不 放 光, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, ' 众星 要 从 天上 坠落, 天 势 都要震动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, ' 那时,他们(马太二十四章三十节是地上的万族)要看见 人 子 有 大 能力、 大荣耀,驾 云 降临。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, ' 他要差遣 天使, 把他的 选民,从 四方(方:原文是风),从 地 极 直到 天 边,都招聚了来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, '「 你们可以从 无花果树 学 个比方:当 树枝 发 嫩 长 叶的时候,你们就知道 夏天 近了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, '这样,你们 几时 看见 这些事 成就,也 该知道人子(人子:或译 神的国) 近了,正在 门口了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, '我实在 告诉 你们,这 世代 还没有 过去, 这些 事 都要成就。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, '天 地 要废去,我的 话 却 不能 废去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, '「但 那 日子, 那时辰,没有人 知道,连 天 上 的使者 也不知道,子 也不知道,惟有 父知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, '你们要谨慎,警醒祈祷,因为 你们不 晓得 那日期 几时 来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, '这事正如 一个人 离开  本 家,寄居外邦, 把权柄 交给 仆人,分派各人 当做的 工,又 吩咐 看门的 警醒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, '所以,你们要警醒;因为 你们不 知道 家 主 什么时候 来,或 晚上,或 半夜,或 鸡叫,或 早晨; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, '恐怕 他忽然 来到,看见 你们 睡著了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, ' 我对你们 所 说的话,也是对众人 说:要警醒!」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, ' 过 两 天 是 逾越节,又 是除酵节, 祭司长 和 文士 想法子 怎么 用 诡计 捉拿 耶稣,杀他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, '只是 说:「当 节 的日子不可,恐怕 百姓 生 乱。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, '耶稣 在 伯大尼 长大痲疯的 西门 家 里 坐席的时候,有一个女人 拿著 一玉瓶 至贵的 真 哪哒 香膏 来, 打破 玉瓶,把膏浇 在耶稣的 头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, ' 有 几个人 心 中 很不喜悦,说:「何 用 这样 枉费 香膏呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, ' 这 香膏 可以 卖 三十 多 两银子 赒济 穷人。」他们就 向那女人 生气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, ' 耶稣 说:「由她 吧!为什么 难为 她呢?她在 我 身上做的 是一件美 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, '因为 常 有 穷人 和 你们同在, 要 向他们 行 善 随时 都可以;只是 你们不 常 有 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, '她所 做的,是尽她所能的;她是为 我安葬 的事把香膏预先 浇 在我 身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, ' 我实在 告诉 你们, 普 天之下,无论 在什么地方 传 这福音,也 要 述说 这女人 所做的,以为 记念。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, ' 十二门徒之中,有一个 加略人 犹大 去 见 祭司长,要 把耶稣 交给 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, ' 他们听见 就欢喜,又 应许 给 他 银子;他就 寻思 如何 得便 把耶稣 交给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, ' 除酵节 的第一 天,就是 宰 逾越羊羔的那一天, 门徒 对耶稣 说:「 你 吃 逾越节 的筵席要我们往哪里 去 预备呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, '耶稣就 打发 两个 门徒, 对他们 说:「你们进 城 去, 必有人 拿著 一瓶 水 迎面而来,你们 就跟著 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, ' 他进哪 家去,你们就对那家的主人 说:『 夫子 说: 客房 在 哪里?我与 门徒 好在那里 吃 逾越节的筵席。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, ' 他 必指给 你们 摆设 整齐的 一间大 楼, 你们就在那里 为我们 预备。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, ' 门徒 出去, 进 了 城, 所遇见的 正如 耶稣 所说的。他们就 预备了 逾越节的筵席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, ' 到了 晚上,耶稣和 十二个 门徒都来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, ' 他们 坐席 正吃的时候,耶稣 说:「我实在 告诉 你们, 你们 中间 有一个 与 我 同吃 的人 要卖 我了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, '他们就 忧愁起来, 一个一个地 问他 说:「是 我吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, ' 耶稣对他们 说:「是十二个 门徒中同 我 蘸 手在 盘子 里的那个人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, ' 人 子 必要 去世,正如 经上指著 他 所写的;但 卖 人 子 的 人 有祸了!那 人 不 生 在世上倒好。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, ' 他们 吃的时候,耶稣拿起 饼来,祝了福,就擘开 , 递给 他们, 说:「你们拿著吃,这 是 我的 身体」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, '又 拿起 杯来,祝谢了,递给 他们; 他们都 喝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, ' 耶稣说:「这 是 我 立约 的血, 为 多人 流出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, '我实在 告诉 你们, 我不再 喝 这 葡萄 汁,直 到 我在 神的 国 里喝 新 的 那 日子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, ' 他们唱了诗,就出来,往 橄榄 山去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, ' 耶稣 对他们 说:「 你们都 要跌倒了,因为 经上记著说:我要击打 牧人,羊 就 分散了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, '但 我 复活 以后,要在你们 以先 往 加利利去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, ' 彼得 说:「众人 虽然 跌倒,我 总 不能。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, ' 耶稣 对他 说:「我实在 告诉 你, 就在今天 夜里,鸡 叫 两遍 以先,你要三次 不认 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, '彼得却 极力地 说:「我 就是 必须 和你 同死,也总不能 不认 你。」众 门徒都是 这样 说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, ' 他们来 到 一个地方, 名叫 客西马尼。 耶稣对 门徒 说:「你们坐 在这里,等 我祷告。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, '于 是 带著 彼得、 雅各、 约翰 同去,就 惊恐 起来, 极其难过, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, ' 对他们 说:「我 心里 甚是 忧伤,几乎 要死;你们在这里 等候, 警醒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, '他就 稍 往前走,俯伏 在 地, 祷告 说:「倘若 可 行,便叫那时候 过去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, ' 他说:「阿爸!父啊!在你 凡事 都能;求你将这 杯 撤去。然而,不要 从 我 的意思,只要 从 你的意思。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, ' 耶稣回来, 见 他们 睡著了,就 对彼得 说:「西门,你睡觉吗?不 能 警醒 片 时吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, '总要警醒 祷告,免得 入 了 迷惑。你们心灵 固然 愿 意,肉体 却 软弱了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, ' 耶稣又 去 祷告,说 的话 还是与先前一样, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, '又 来 见 他们 睡著了,因为 他们的 眼睛 甚是 困倦;他们也 不 知道 怎么 回答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, ' 第三次 来, 对他们 说:「现在 你们仍然 睡觉 安歇吧(吧:或译吗?)!够了,时候 到了。看哪,人 子 被卖 在 罪人 手里了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, '起来!我们走吧。看哪,那卖 我 的人近了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, ' 说话 之间,忽然 那十二个 门徒里的 犹大 来了,并 有许多人 带著 刀 棒,从 祭司长 和 文士 并 长老 那里与 他同来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, ' 卖 耶稣 的人曾给 他们 一个暗号,说:「我与谁 亲嘴,谁 就是他。你们把他 拿住, 牢牢靠靠地 带去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, ' 犹大来了,随即 到 耶稣跟前,说:「拉比」,便 与他 亲嘴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, '他们就 下 手 拿住 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, ' 旁边站著的人,有 一个 拔出 刀来,将大祭司 的仆人 砍了一刀, 削掉了 他 一个耳朵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, ' 耶稣 对他们 说:「你们带著 刀 棒 出来 拿 我,如同 拿 强盗吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, '我天天 教训人, 同 你们 在 殿里,你们并 没有 拿 我。但这事成就,为要 应验 经上的话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, ' 门徒都 离开  他,逃走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, ' 有一个 少年人,赤身 披 著 一块麻布,跟随 耶稣,众人就 捉拿 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, '他却 丢了 麻布,赤身 逃走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, ' 他们把耶稣 带 到 大祭司那里,又 有众 祭司长 和 长老 并 文士 都来和大祭司一同聚集。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, ' 彼得 远远地 跟著 耶稣,一直 进 入 大祭司 的院里,和 差役 一同 坐 在 火光 里 烤火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, ' 祭司长 和 全 公会 寻找 见证 控告 耶稣,要 治死 他,却 寻 不著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, '因为 有好些人 作假见证 告 他, 只是 他们的见证 各不 相合。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, '又 有几个人 站起来 作假见证 告 他,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, '「 我们 听见 他 说:『 我 要拆毁 这 人手 所造的殿,三 日 内 就 另 造 一座不是人手所造的。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, '他们 就是 这么 作见证,也是 各不 相合。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, ' 大祭司 起来 站在 中间,问 耶稣 说:「你什么 都不 回答吗?这些人 作见证告 你 的是什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, '耶稣却 不言语,一句也 不 回答。大祭司 又 问 他 说:「你 是 那当称颂者 的儿子 基督不是?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, ' 耶稣 说:「我 是。 你们必看见 人 子 坐 在 那权能者 的右边, 驾著 天上 的云 降临。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, '大祭司 就 撕开  衣服,说:「我们何 必 再 用 见证人呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, '你们已经听见 他这僭妄的话了。你们 的意见 如何?」 他们都 定 他 该 死 的罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, ' 就 有人 吐唾沫 在他脸上,又 蒙著 他的 脸, 用拳头打 他, 对他 说:「你说预言吧!」 差役 接过他 来,用手掌打他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, ' 彼得 在 下边 院子里;来了 大祭司 的一个 使女, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, ' 见 彼得 烤火,就看著 他,说:「你 素来也 是 同 拿撒勒人 耶稣一伙 夥的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, '彼得却 不承认,说:「我不 知道,也不 明白 你 说的 是什么。」于 是 出 来,到了 前院,鸡 就 叫了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, ' 那使女 看见 他,又 对 旁边站著 的人说:「这 也是 他们 一党的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, ' 彼得又 不承认。 过了 不多的时候,旁边站著 的人又 对彼得 说:「你真 是 他们 一党的! 因为 你是 加利利人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, ' 彼得就 发咒 起誓地 说:「我不 认得 你们说 的 这个 人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, ' 立时 鸡 叫了 第二遍。 彼得 想起 耶稣 对他 所 说 的话:「 鸡 叫 两遍 以先,你要三次 不认 我。」 思想起来,就哭了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, ' 一 到早晨,祭司长 和 长老、 文士、 全 公会 的人大家 商议,就把耶稣 捆绑,解去 交给 彼拉多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, ' 彼拉多 问 他说:「你 是 犹太人的 王吗?」 耶稣回答 说:「你 说的是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, ' 祭司长 告 他 许多的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, ' 彼拉多 又 问 他 说:「你看,他们告 你 这么多的事,你什么 都不 回答吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, '耶稣 仍 不 回答,以致 彼拉多 觉得希奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, ' 每逢 这节期,巡抚照众人所 求的,释放 一个 囚犯 给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, ' 有 一个人名叫 巴拉巴,和作乱的人 一同 捆绑。他们 做乱的时候,曾 杀过人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, ' 众人 上 去 求巡抚,照 常例给他们 办。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, ' 彼拉多 说:「你们要 我释放 犹太人的 王 给你们吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, '他原 晓得, 祭司长 是因为 嫉妒 才把耶稣 解了来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, '只是 祭司长 挑唆 众人, 宁可 释放 巴拉巴 给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, ' 彼拉多 又 说:「那么样,你们 所 称为 犹太人的 王,我怎么 办他呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, ' 他们又 喊著说:「把他 钉十字架!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, ' 彼拉多 说:「为什么呢?他做了 什么 恶事呢?」他们便 极力地 喊著说:「把他 钉十字架!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, ' 彼拉多 要 叫 众人 喜悦,就释放 巴拉巴 给他们, 将耶稣 鞭打了,交 给 人钉十字架。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, ' 兵丁 把耶稣 带 进 衙门 院里, 叫齐了 全 营的兵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, ' 他们给他 穿上 紫袍,又 用荆棘 编做 冠冕 给他 戴上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, ' 就 庆贺 他说:「恭喜,犹太人的 王啊!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, '又 拿一根苇子 打 他的 头, 吐唾沫 在他脸上, 屈 膝 拜 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, ' 戏弄 完了,就给他 脱了 紫袍, 仍穿上 他 自己的 衣服, 带他 出去,要 钉十字架。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, ' 有一个 古利奈人 西门,就是亚历山大 和 鲁孚 的父亲,从 乡下 来,经过那地方,他们就勉强他同去,好 背著 耶稣的 十字架。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, ' 他们带 耶稣 到了 各各他 地方(各各他 翻出来 就是 髑髅 地), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, ' 拿没药调和的 酒 给 耶稣, 他却 不 受。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, '于 是 将他 钉在十字架上, 拈 阄 分 他的 衣服,看是谁 得 什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, ' 钉 他 在十字架上 是 巳初 的时候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, ' 在上面有他的 罪 状,写 的是:「犹太人的 王。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, '他们又 把两个 强盗 和他 同 钉十字架,一个 在 右边, 一个 在 左边。(有古卷加: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, ' 这就应了 经上 的 话说: 他被列 在 罪犯之中。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, ' 从那里经过 的人辱骂 他,摇著 头 说:「咳!你这拆毁 圣殿、 三 日 又 建造起来的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, '可以救 自己,从 十字架 上下来吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, '祭司长 和 文士 也 是这样 戏弄他,彼此 说:「他救了 别人,不 能 救 自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, '以色列 的王 基督,现在 可以从 十字架 上下来,叫 我们看见,就 信了。」 那和 他 同钉 的人也是讥诮 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, ' 从午正 到 申初, 遍 地 都 黑暗了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, ' 申初 的时候,耶稣 大 声 喊著说:「以罗伊!以罗伊!拉马 撒巴各大尼?」(翻出来 就 是:我的 神!我的 神!为什么 离弃 我?) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, ' 旁边站著 的人,有的听见 就说:「看哪,他叫 以利亚呢!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, ' 有一个人 跑去, 把海绒 蘸满了 醋,绑在 苇子上,送给他 喝,说:「且等著,看 以利亚 来 不来 把他 取下。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, ' 耶稣 大 声 喊叫,气就断了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, ' 殿 里的幔子 从 上 到 下 裂 为 两半。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, ' 对面 站著 的 百夫长 看见 耶稣 这样喊叫(有古卷没有喊叫二字)断气,就说:「这 人 真 是 神的 儿子!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, ' 还 有 些妇女 远远地 观看;内中 有抹大拉 的马利亚,又 有小 雅各 和 约西的 母亲 马利亚,并 有撒罗米, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, '就是 耶稣 在 加利利 的时候,跟随 他、 服事 他的那些人,还有 同耶稣 上 耶路撒冷 的 好些妇女在那里观看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, ' 到了 晚上,因为 这是 预备日,就 是 安息日的前一日, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, '有亚利马太 的 约瑟前来,他是尊贵的 议士, 也 是 等候 神 国的。他放胆 进 去 见 彼拉多, 求 耶稣 的身体; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, ' 彼拉多 诧异 耶稣已经 死了,便 叫 百夫长来,问 他 耶稣死了 久不久。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, '既 从 百夫长 得知实情,就把耶稣的尸首 赐给 约瑟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, ' 约瑟买 了 细麻布,把耶稣 取下来,用细麻布 裹好, 安放 在 磐石 中凿 出来 的 坟墓里,又 滚过 一块石头 来 挡住墓 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, ' 抹大拉 的马利亚 和 约西 的母亲马利亚 都看见 安放 他的地方。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, ' 过了 安息日,抹大拉 的马利亚 和 雅各 的母亲 马利亚 并 撒罗米,买 了 香膏 要 去 膏 耶稣的身体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, ' 七日 的第一日 清 早,出 太阳的时候,她们来 到 坟墓那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, ' 彼此 说:「谁 给我们 把石头 从 墓 门 滚开 呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, ' 那 石头原来 很 大,她们抬头一看,却见 石头 已经滚开 了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, ' 她们进了 坟墓,看见 一个少年人 坐 在 右边,穿著 白 袍,就 甚惊恐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, ' 那少年人对她们 说:「不 要惊恐!你们寻找 那 钉十字架的 拿撒勒人 耶稣,他已经复活了,不 在 这里。请看 安放 他 的 地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, ' 你们可以去 告诉 他的 门徒 和 彼得,说:『 他在你们 以先往 加利利 去。在那里 你们要见 他,正如 他从前所告诉 你们的。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, '她们就 出来,从 坟墓 那里逃跑, 又 发抖 又 惊奇,什么 也 不告诉人,因为 她们 害怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, ' 在七日 的第一日 清早,耶稣复活了,就先 向抹大拉 的马利亚 显现。(耶稣从她身上 曾赶 出 七个 鬼。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, '她 去 告诉 那向来 跟随 耶稣的人;那时他们正哀恸 哭泣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, '他们 听见 耶稣活了, 被 马利亚 看见,却是不信。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, '这事以后,门徒中间 有两个 人往 乡下 去。走路的时候,耶稣变了 形像,向 他们显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, '他们 就去 告诉 其余 馀的门徒;其余 馀的门徒也是不 信。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, ' 后来,十一个 门徒坐席的时候,耶稣向他们 显现, 责备 他们 不信, 心里刚硬,因为 他们不 信 那些在他复活 以后看见 他的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, '他又 对他们 说:「你们往 普 天下 去,传 福音给万民(万民:原文是凡 受造的)听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, '信 而 受洗的,必然得救; 不信的,必被定罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, ' 信 的人必有 神迹 随著他们,就是奉 我的 名 赶 鬼;说 新 方言; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, ' 手 能拿 蛇;若 喝了 什么毒 物,也必不 受害;手 按 病人, 病人就必 好了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, ' 主 耶稣 和他们 说完了话,后来 被接 到 天上, 坐 在 神 的右边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, ' 门徒 出去,到处 宣传福音。主 和他们同工,用 神迹 随著, 证实 所传的道。阿们!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, '提阿非罗 大人哪, 有好些人 提笔 作书,述说 在 我们 中间所成就 的事, 是 照 传道 的人 从 起初 亲眼看见 又 传 给我们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, '这些事 我既 从起头 都详细 考察了,就定意 要按著次序 写 给你, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, '使 你知道 所学 之道 都是确实的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, '当 犹太 王 希律 的时候,亚比雅 班 里 有 一个 祭司,名叫 撒迦利亚; 他 妻子 是 亚伦 的后人, 名叫 伊利莎白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, ' 他们二人在 神 面前 都是 义人,遵行 主 的一切 诫命 礼仪,没有可指摘的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, '只是 没 有 孩子;因为 伊利莎白 不生育, 两个 人又 年纪 老迈了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, ' 撒迦利亚 按 班 次在 神 面前 供祭司的职分, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, '照 祭司 的规矩 掣签,得进 主 殿 烧香。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, ' 烧香 的时候,众 百姓 在外面 祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, ' 有主 的使者 站 在 香 坛 的右边,向他 显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, ' 撒迦利亚 看见,就惊慌 害怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, ' 天使 对 他 说:「撒迦利亚,不要 害怕,因为 你 的祈祷 已经被听见了。 你 的妻子 伊利莎白 要给你 生 一个儿子, 你要给他 起名 叫 约翰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, ' 你 必 欢喜 快乐; 有许多人 因 他 出世,也必喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, ' 他在主 面前 将要为 大, 淡酒 浓酒 都不 喝, 从 母 腹 里就 被圣 灵 充满了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, ' 他要使许多 以色列 人 回转,归于  主─他们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, ' 他 必有 以利亚 的心志 能力,行 在主 的前面,叫为父 的心 转 向 儿女, 叫悖逆的人 转从 义人 的智慧,又为主 预备 合用 的百姓。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, ' 撒迦利亚 对 天使 说:「我凭著 什么 可知道 这事呢? 我 已经 老了,我 的妻子 也 年纪 老迈了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, ' 天使 回答 说:「我 是 站在 神 面前 的加百列, 奉差 而来对 你 说话, 将这 好信息报 给你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, ' 到了 时候,这话 必然应验;只因 你不 信, 你必 哑巴, 不 能 说话,直到 这事 成就 的 日子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, ' 百姓 等候 撒迦利亚, 诧异 他 许久 在 殿里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, '及至 他出来,不 能 和他们 说话, 他们就知道 他在 殿 里见 了异象;因为 他 直向他们 打手式,竟 成了 哑巴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, ' 他 供职 的日子 已满,就回 家去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, ' 这些 日子 以后,他的 妻子 伊利莎白 怀了孕,就 隐藏了 五个 月, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, '说:「 主 在 眷顾 我的日子,这样 看待 我,要把我 在 人间 的羞耻 除掉。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, ' 到了 第六个 月,天使 加百列 奉 神 的差遣 往 加利利 的一座城去(这城名叫 拿撒勒), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, '到 一个童女那里,是已经许配 大卫 家 的一个人, 名 叫约瑟。 童女 的名字 叫马利亚; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, ' 天使进去,对 她 说:「蒙大恩的女子,我问你安,主 和你 同在了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, ' 马利亚因 这话 就很惊慌,又 反复思想 这样 问安 是 什么意思。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, ' 天使 对她 说:「马利亚,不要 怕!你在 神 面前 已经蒙恩了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, ' 你 要怀孕 生 子, 可以给他 起名 叫 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, ' 他要为 大, 称为 至高者 的儿子; 主 神 要把他 祖 大卫 的位 给 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, ' 他要作 雅各 家的王,直到 永远;他 的国 也 没 有 穷尽。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, ' 马利亚 对 天使 说:「 我没有 出嫁,怎么 有 这事呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, ' 天使 回答 说:「圣 灵 要临 到 你身上, 至高者 的能力 要荫庇 你,因此 所要生的 圣者 必称为 神 的儿子(或译:所要生的,必称为圣,称为 神的儿子)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, '况且 你 的亲戚 伊利莎白, 在 年老 的时候也 怀了 男胎,就是那 素来称为 不生育的, 现在 有 孕六个 月了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, '因为, 出于  神 的话,没有 一句不带能力的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, ' 马利亚 说:「 我是主 的使女,情愿 照 你 的话 成就 在我身上。」天使 就 离开  她去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, ' 那 时候,马利亚 起身,急忙 往 山地 里去,来到 犹大 的一座城; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, ' 进了 撒迦利亚 的家, 问 伊利莎白安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, ' 伊利莎白 一听 马利亚 问安,所怀的胎 就在 腹 里跳动。伊利莎白 且 被圣 灵 充满, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, ' 高 声 喊著 说:「你 在妇女 中 是有福的!你 所怀的胎 也 是有福的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, ' 我 主 的母 到 我 这里来,这 是从哪里得的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, '因为 你 问安 的声音 一入 我 耳, 我 腹 里的胎 就 欢喜 跳动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, ' 这相信 的女子是有福的!因为 主 对她 所说 的话都要 应验。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, ' 马利亚 说:我 心 尊 主为大; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, ' 我 灵 以 神 我 的救主 为乐; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, '因为 他顾念 他 使女 的卑微; 从 今以后,万 代 要称我 有福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, ' 那有权能的,为我 成就 了大事; 他 的名 为圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, ' 他 怜悯 敬畏 他的人,直到 世世代代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, '他 用 膀臂 施展 大能;那狂傲 的人正 心 里妄想 就被他赶散了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, '他叫有权柄的 失 位, 叫卑贱的 升高; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, '叫饥饿的 得饱 美食, 叫富足的 空手 回去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, '他扶助 了他的 仆人 以色列, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, '为要记念 亚伯拉罕 和 他的 后裔,施怜悯 直到 永远,正如 从前对 我们 列祖 所说的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, ' 马利亚 和伊利莎白 同 住,约有 三 个月,就 回 家去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, ' 伊利莎白 的产 期 到了,就 生 了一个儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, ' 邻里 亲族 听见 主 向 她 大施 怜悯,就 和她 一同欢乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, ' 到了 第八 日,他们来 要给孩子 行割礼,并 要照 他 父亲 的名字 叫 他 撒迦利亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, ' 他 母亲 说:「不可! 要叫 他约翰。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, ' 他们 说:「 你 亲族 中 没 有 叫 这 名字的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, '他们就 向他 父亲 打手式,问他 要 叫 这孩子什么名字。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, ' 他要了 一块写字的板,就写上,说:「他 的名字 是 约翰。」 他们 便都希奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, ' 撒迦利亚 的口 立时 开 了, 舌头 也舒展了,就 说出话来,称颂 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, ' 周围居住 的人都 惧怕;这 一切 的事 就 传 遍 了犹太 的山地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, ' 凡 听见的人 都将这事放 在 心里,说:「这个 孩子 将来 怎么样呢? 因为 有 主 与 他同在。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, ' 他 父亲 撒迦利亚 被圣 灵 充满了,就 预言 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, '主─以色列的 神 是应当称颂的!因 他眷顾 他 的百姓, 为他们施行 救赎, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, ' 在 他 仆人 大卫 家中,为我们 兴起了 拯救 的角, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, '正如 主藉 借著 从 创世 以来 圣 先知 的口 所说的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, '拯救 我们 脱离 仇敌 和 一切 恨 我们 之人的手, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, '向 我们 列祖 施 怜悯, 记念 他 的圣 约─ ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, '就是 他对 我们 祖宗 亚伯拉罕 所起 的誓─ ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, '叫 我们 既从 仇敌 手 中被救出来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, '就可以 终身 在他 面前,坦然无惧地 用 圣洁、 公义 事奉 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, '孩子啊! 你 要称为 至高者 的先知;因为 你要行 在主 的前面,预备 他 的道路, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, '叫 他 的百姓 因 罪 得赦,就知道 救恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, '因 我们 神 怜悯 的心肠, 叫清晨的日光 从 高天 临到 我们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, '要照亮 坐 在 黑暗 中 死 荫里的人,把我们 的脚 引 到 平安 的路上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, ' 那孩子 渐渐长大, 心灵 强健, 住 在 旷野,直到 他 显明 在 以色列人 面前的日子。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, ' 当 那些 日子, 凯撒 奥古斯都 有旨意 下来,叫天下 人民 都报名上册。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, '这是居里扭 作叙利亚 巡抚的时候, 头一次 行报名上册 的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, ' 众人 各 归 各 城,报名上册。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, ' 约瑟 也 从 加利利 的 拿撒勒 城 上 犹太去,到了 大卫 的城, 名叫 伯利恒,因 他 本是 大卫 一族 一家的人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, '要和他 所聘 之妻马利亚 一同 报名上册。那时马利亚的身孕 已经重了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, ' 他们 在 那里的时候,马利亚 的产 期 到了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, '就 生了 头胎 的儿子, 用布包起来, 放 在 马槽里,因为 客店 里没 有 地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, ' 在 伯利恒之野地 里有 牧羊的人, 夜间 按著更次看守 羊群。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, ' 有主 的使者 站 在他们旁边, 主 的荣光 四面照著 他们;牧羊的人就 甚 惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, ' 那天使 对他们 说:「不要 惧怕! 我报 给你们 大 喜的信息, 是 关乎万 民的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, '因 今天 在 大卫 的城里,为你们 生了 救主, 就是 主 基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, ' 你们要看见 一个婴孩,包著布, 卧 在 马槽里,那 就是 记号了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, ' 忽然,有 一大队 天 兵 同 那天使 赞美 神 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, '在 至高之处 荣耀归与 神! 在 地 上平安 归与 他所喜悦 的人(有古卷:喜悦归与人)! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, ' 众天使 离开  他们,升 天去了。牧羊的人 彼此 说:「 我们往 伯利恒 去, 看看 所成的 事,就是 主 所指示 我们的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, ' 他们急忙 去了,就 寻见 马利亚 和 约瑟,又有 那婴孩 卧 在 马槽里; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, '既然 看见,就把 天使论 这 孩子 的话 传开 了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, ' 凡 听见的,就诧异 牧羊之人 对 他们 所说的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, '马利亚 却 把这 一切 的事 存 在 心里,反复思想。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, ' 牧羊的人 回去了,因 所听见 所看见 的一切事,正如 天使向 他们 所说的,就归荣耀与 神, 赞美他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, ' 满了 八 天,就给孩子 行割礼, 与他 起名 叫 耶稣;这 就是没有成胎 以前, 天使 所起的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, ' 按 摩西 律法 满了 洁净 的日子,他们带著 孩子 上 耶路撒冷去,要把他献 与主, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, '(正如 主 的律法 上所记:「 凡 头生的 男子 必称 圣 归主。」) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, '又 要照 主 的律法 上所说,或用一对 斑鸠,或 用两只 雏 鸽 献 祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, ' 在 耶路撒冷 有 一个人, 名 叫西面; 这 人 又公义 又 虔诚,素常盼望 以色列 的安慰者来到,又 有 圣 灵 在 他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, ' 他 得了 圣 灵 的 启示,知道 自己未 死 以前,必 看见 主 所立的基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, ' 他受了 圣灵的感动,进 入 圣殿, 正 遇见耶稣 的父母 抱著孩子 进来, 要照 律法 的规矩 办理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, '西面 就 用 手 接过 他来, 称颂 神 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, '主啊!如今 可以照 你 的话,释放 仆人 安然去世; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, '因为 我 的眼睛 已经看见 你 的救恩─ ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, '就是 你 在万 民 面前 所预备的: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, '是 照亮外邦人 的 光,又 是你 民 以色列 的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, ' 孩子 的父 母 因 这论 耶稣 的话就 希奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, ' 西面 给他们 祝福,又 对 孩子 的母亲 马利亚 说:「 这 孩子被立,是要叫 以色列 中 许多人 跌倒, 许多人兴起;又 要作 毁谤 的话柄, 叫许多人 心里 的意念 显露出来;你 自己 的心 也 要被刀 刺透。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, '又有 女先知,名叫亚拿,是 亚设 支派 法内力 的女儿, 年纪 已经老迈,从 作童女出嫁的时候,同 丈夫 住 了七 年就寡居了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, ' 现在已经 八十 四 岁(或译:就寡居了八十四年), 并不 离开  圣殿,禁食 祈求,昼 夜 事奉 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, ' 正当那 时,她进前来 称谢 神, 将 孩子 的事对一切 盼望 耶路撒冷 得救赎 的人讲说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, ' 约瑟和马利亚照 主 的律法 办完 了一切的事,就回 加利利,到 自己 的城 拿撒勒去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, ' 孩子 渐渐长大, 强健起来,充满 智慧,又有 神 的恩 在 他身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, ' 每年 到逾越节,他 父母 就上 耶路撒冷去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, ' 当 他 十二 岁的时候,他们 按著 节期 的规矩 上去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, ' 守满了 节期, 他们 回去,孩童 耶稣 仍旧 在 耶路撒冷。 他 的父母 并不 知道, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, ' 以为 他 在 同行的人中间,走了 一天 的路程,就 在 亲族 和 熟识的 人中找 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, '既 找 不著,就回 耶路撒冷 去找 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, ' 过了 三 天,就遇见 他 在 殿里,坐 在 教师 中间, 一面听, 一面问。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, ' 凡 听见 他的,都希奇 他 的聪明 和 他的应对。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, ' 他父母看见 就很希奇。 他 母亲 对 他 说:「我儿!为什么 向我们 这样 行呢?看哪,你 父亲 和我 伤心 来找 你!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, ' 耶稣 说:「为什么 找 我呢?岂不 知 我应当以我父的事为念吗(或译:岂不知我应当 在 我 父的家里吗)?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, ' 他 所说 的这话,他们 不 明白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, ' 他就同 他们 下去, 回 到 拿撒勒,并且 顺从 他们。 他 母亲 把这一切的 事 都存 在 心里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, ' 耶稣 的 智慧 和身量(或译:年纪),并 神 和 人 喜爱他的心,都一齐增长。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, ' 凯撒 提庇留 在位 第十五 年,本丢•彼拉多 作犹太 巡抚, 希律 作加利利 分封的王, 他 兄弟 腓力 作以土利亚 和 特拉可尼 地方 分封的王, 吕撒聂 作亚比利尼 分封的王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, ' 亚那 和 该亚法 作大祭司。那时,撒迦利亚 的儿子 约翰 在 旷野里, 神 的话 临 到他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, '他就 来 到 约旦河 一带 地方,宣讲 悔改 的洗礼,使 罪 得赦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, '正如 先知 以赛亚 书 上所记 的话,说:在 旷野 有人声 喊著说:预备 主 的道,修 直 他 的路! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, '一切 山洼 都要填满; 大小山冈 都要削平! 弯弯曲曲 的地方要 改为 正直; 高高低低 的道路 要改为 平坦! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, ' 凡 有血气的,都要见 神 的救恩! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, ' 约翰对那出来 要受 他 洗 的众人 说:「毒蛇 的种类!谁 指示 你们 逃避 将来 的忿怒呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, ' 你们要结出 果子来,与悔改 的心相称。 不要 自己 心里说:『有 亚伯拉罕 为我们的祖宗。』 我告诉 你们, 神 能 从 这些 石头中,给亚伯拉罕 兴起 子孙来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, ' 现在 斧子 已经 放 在 树 根上, 凡 不 结 好 果子 的树 就砍下来, 丢 在 火里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, ' 众人 问 他 说:「这样,我们当做 什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, ' 约翰回答 说:「有 两 件衣裳的,就分给 那没 有的; 有 食物的,也当这样 行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, ' 又有 税吏 来 要受洗, 问 他 说:「夫子,我们当做 什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, ' 约翰 说:「除了 例定的数目,不要 多 取。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, '又 有 兵丁 问 他 说:「我们 当 做 什么呢?」 约翰 说:「不要 以强暴待人,也不要 讹诈人, 自己有 钱粮 就当知足。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, ' 百姓 指望基督来的时候, 人 都 心里 猜疑,或者 约翰 是 基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, '约翰 说:「 我 是用水 给你们 施洗,但 有一位能力比我 更大 的要来, 我就是 给他 解 鞋 带 也不 配。他 要用 圣 灵 与 火 给你们 施洗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, ' 他 手 里拿著簸箕,要扬净 他 的场, 把麦子 收 在 仓里, 把糠 用不灭的 火 烧尽了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, ' 约翰又 用许多 别 的话劝 百姓,向他们传福音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, '只是 分封的王 希律,因 他 兄弟 之妻 希罗底的缘故,并 因 他 所行 的一切 恶事,受了 约翰的责备; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, '又 另外 添了 一件,就是 把约翰 收 在 监里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, ' 众 百姓 都受了洗,耶稣 也 受了洗。 正祷告的时候,天 就开 了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, ' 圣 灵 降临 在 他身上,形状 仿佛 鸽子;又有 声音 从 天上 来,说:「你 是 我 的爱 子,我喜悦 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, ' 耶稣 开 头传道,年纪约有 三十 岁。依 人看来,他是 约瑟 的儿子;约瑟是希里的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, '希里是玛塔的儿子;玛塔是利未的儿子;利未是麦基的儿子;麦基是雅拿的儿子;雅拿是约瑟的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, '约瑟是玛他提亚的儿子;玛他提亚是亚摩斯的儿子;亚摩斯是拿鸿的儿子;拿鸿是以斯利的儿子;以斯利是拿该的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, '拿该是玛押的儿子;玛押是玛他提亚的儿子;玛他提亚是西美的儿子;西美是约瑟的儿子;约瑟是犹大的儿子;犹大是约亚拿的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, '约亚拿是利撒的儿子;利撒是所罗巴伯的儿子;所罗巴伯是撒拉铁的儿子;撒拉铁是尼利的儿子;尼利是麦基的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, '麦基是亚底的儿子;亚底是哥桑的儿子;哥桑是以摩当的儿子;以摩当是珥的儿子;珥是约细的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, '约细是以利以谢的儿子;以利以谢是约令的儿子;约令是玛塔的儿子;玛塔是利未的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, '利未是西缅的儿子;西缅是犹大的儿子;犹大是约瑟的儿子;约瑟是约南的儿子;约南是以利亚敬的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, '以利亚敬是米利亚的儿子;米利亚是买 南的儿子;买 南是玛达他的儿子;玛达他是拿单的儿子;拿单是大卫的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, '大卫是耶西的儿子;耶西是俄备得的儿子;俄备得是波阿斯的儿子;波阿斯是撒门的儿子;撒门是拿顺的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, '拿顺是亚米拿达的儿子; 亚米拿达是亚兰的儿子;亚兰是希斯仑 的儿子;希斯仑 是法勒斯的儿子;法勒斯是犹大的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, '犹大是雅各的儿子;雅各是以撒的儿子;以撒是亚伯拉罕的儿子;亚伯拉罕是他拉的儿子;他拉是拿鹤的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, '拿鹤是西鹿的儿子;西鹿是拉吴的儿子;拉吴是法勒的儿子;法勒是希伯的儿子;希伯是沙拉的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, '沙拉是该南的儿子;该南是亚法撒的儿子;亚法撒是闪的儿子;闪是挪亚的儿子;挪亚是拉麦的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, '拉麦是玛土撒拉的儿子;玛土撒拉是以诺的儿子;以诺是雅列的儿子;雅列是玛勒列的儿子;玛勒列是该南的儿子;该南是以挪士的儿子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, '以挪士是塞特的儿子;塞特是亚当的儿子;亚当是 神的儿子。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, ' 耶稣 被圣 灵 充满,从 约旦河 回来, 圣灵 将他引 到 旷野,四十 天 受 魔鬼 的试探。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, ' 那些 日子 没有 吃什么; 日子满了,他就饿了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, ' 魔鬼 对他 说:「你若 是 神 的儿子,可以吩咐 这 块石头 变成 食物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, ' 耶稣 回答说:「经上记著说:『 人 活著 不是 单 靠 食物,乃是靠 神口里所出的一切话。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, '魔鬼又 领 他上了高山, 霎时间 把天下 的万 国 都指 给他看, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, ' 对他 说:「这 一切 权柄、 荣华,我都要给 你,因为 这原是交付 我的, 我愿 意 给谁 就给 谁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, ' 你 若 在我 面前 下拜,这都 要归 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, ' 耶稣 说:「经上记著说:当拜 主─你的 神, 单 要事奉 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, '魔鬼又 领 他 到 耶路撒冷去, 叫他站 在 殿 顶(顶:原文是翅)上, 对他 说:「你若 是 神 的儿子, 可以从这里 跳 下去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, '因为 经上记著说: 主要为 你 吩咐 他 的使者 保护 你; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, ' 他们要用 手 托著 你,免得 你 的脚 碰 在 石头上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, ' 耶稣 对他 说:「经上说:『 不可 试探 主─你的 神。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, ' 魔鬼 用完了 各样 的试探,就暂时 离开  耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, ' 耶稣 满有 圣灵 的能力,回 到 加利利; 他 的名声 就 传 遍 了四方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, ' 他 在 各会堂 里教训人, 众人 都称赞他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, ' 耶稣来 到 拿撒勒,就是 他长大 的地方。 在 安息 日,照 他 平常的规矩 进了 会堂, 站起来 要念圣经。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, ' 有人把先知 以赛亚 的书 交给 他,他就 打开 ,找到 一处 写著说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, '主 的灵 在 我身上, 因为 他用膏膏 我,叫我传福音 给贫穷的人;差遣 我 报告:被掳的 得释放, 瞎眼的 得看见,叫 那受压制 的得 自由, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, '报告 神 悦纳 人的禧年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, '于 是 把书 卷起来,交还 执事,就坐下。 会堂 里的人都 定睛看 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, ' 耶稣 对 他们 说:「 今天 这 经 应验 在 你们 耳中了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, ' 众人 都称赞 他,并 希奇 他 口 中所出 的恩 言;又 说:「这 不 是 约瑟 的儿子吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, ' 耶稣对 他们 说:「你们必 引这 俗语 向我 说:『医生,你医治 自己吧!我们听见 你在 迦百农 所行 的事,也 当行 在 你 自己家乡里』」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, '又 说:「我实在 告诉 你们, 没有 先知 在 自己 家乡 被人悦纳的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, ' 我对 你们 说 实话,当 以利亚 的时候, 天 闭塞了 三 年 零六 个月, 遍 地 有 大 饥荒,那时,以色列 中 有 许多 寡妇, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, '以利亚 并 没有 奉差 往 她们一个人那里去,只 奉差往 西顿 的撒勒法 一个寡妇 那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, ' 先知 以利沙 的时候,以色列 中 有 许多 长大痲疯的,但 内中除了 叙利亚国 的乃缦, 没有一个 得洁净的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, ' 会堂 里 的 人听见 这话,都怒气 满胸, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, ' 就起来 撵 他 出 城( 他们 的城 造 在山上);他们带 他 到 山 崖, 要把他 推下去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, '他 却 从 他们 中间 直行,过去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, ' 耶稣下 到 迦百农,就是加利利 的一座城, 在 安息日 教训 众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, ' 他们很希奇 他 的教训,因为 他的 话 里有 权柄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, ' 在 会堂 里有 一个人,被污 鬼 的精气 附著, 大 声 喊叫说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, '「唉! 拿撒勒 的耶稣,我们 与 你 有什么相干?你来 灭 我们吗?我知道 你 是谁,乃是 神 的圣者。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, ' 耶稣 责备 他 说:「不要作声, 从 这人 身上出来吧!」 鬼 把那人 摔倒 在 众人中间,就 出来了,却也没有 害 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, ' 众人 都 惊讶, 彼此 对问 说:「这是 什么 道理呢?因为 他用 权柄 能力 吩咐 污 鬼,污鬼就 出来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, '于 是 耶稣 的名声 传遍了 周围 地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, ' 耶稣出了 会堂,进了 西门 的家。 西门 的岳母 害热病 甚重, 有人为 她 求 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, ' 耶稣站 在她 旁边,斥责 那热病,热就 退了。 她立刻 起来 服事 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, ' 日 落的时候,凡 有病人的,不论害 什么病,都带 到 耶稣那里。 耶稣按 手 在他们 各人身上,医好 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, '又有 鬼 从 好些人 身上出来,喊著 说:「你 是 神 的儿子。」 耶稣斥责他们,不 许 他们 说话。因为 他们知道 他 是 基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, ' 天亮的时候,耶稣出来,走 到 旷野 地方。 众人 去找 他, 到了 他那里, 要留住 他,不要 他离开  他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, '但 耶稣对 他们 说:「 我 也 必须 在别 城 传 神 国的福音,因 我奉差 原是为 此。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, '于 是 耶稣在 加利利 的各会堂 传道。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, ' 耶稣 站 在革尼撒勒 湖 边, 众人 拥挤 他, 要听 神 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, ' 他见 有两只 船 湾 在湖 边;打鱼的人 却 离开  船 洗 网去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, ' 有一只 船 是 西门的, 耶稣就上去,请 他 把船撑开 ,稍微 离 岸,就 坐下,从 船 上教训 众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, ' 讲 完了,对 西门 说:「把船开  到 水深之处, 下 网 打鱼。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, ' 西门 说:「夫子,我们 整 夜 劳力,并没有 打著什么。但 依从 你 的话,我就下 网。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, ' 他们下了网,就圈住 许多 鱼, 网 险些裂开 , ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, '便 招呼 那只 船 上 的同伴 来 帮助。他们就 来, 把鱼装满了 两只 船,甚至 船 要沉下去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, ' 西门•彼得 看见,就俯伏 在耶稣 膝前,说:「主啊,离开  我, 我是 个罪 人!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, ' 他 和 一切 同在的人 都 惊讶 这 一网 所打 的鱼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, ' 他 的伙 夥伴 西庇太 的儿子 雅各、 约翰,也是 这样。 耶稣 对 西门 说:「不要 怕!从 今以后,你要 得 人了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, ' 他们把两只船 拢了 岸,就撇下 所有的,跟从了 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, ' 有一回,耶稣 在 一个 城里, 有人 满身 长了大痲疯, 看见 他,就俯伏在地,求 他 说:「主 若 肯,必能 叫我 洁净了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, ' 耶稣伸 手 摸 他,说:「我肯,你洁净了吧!」 大痲疯 立刻 就离了 他的身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, ' 耶稣 嘱咐 他:「你切不可 告诉人,只要 去 把 身体给祭司 察看,又要 为 你 得了洁净,照 摩西 所吩咐 的献上礼物,对众人 作 证据。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, '但 耶稣 的名声 越发 传扬出去。 有极多 的人 聚集 来听道,也 指望医治 他们 的病。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, '耶稣 却 退 到 旷野 去祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, ' 有一 天, 耶稣 教训人, 有 法利赛人 和 教法师 在旁边坐著;他们 是 从 加利利 各 乡村 和 犹太 并 耶路撒冷 来的。 主 的能力 与耶稣同在,使 他能医治 病人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, ' 有人 用 褥子 抬著 一个 瘫子, 要抬 进去 放 在耶稣 面前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, '却 因 人多,寻 不 出法子 抬进去,就上了 房顶,从 瓦间 把他 连 褥子 缒到 当中,正在耶稣 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, ' 耶稣见 他们 的信心,就对瘫子说:「 你 的罪 赦了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, ' 文士 和 法利赛人 就 议论 说:「这 说 僭妄话 的是 谁?除了 神以外,谁 能 赦 罪呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, ' 耶稣 知道 他们 所议论的,就 说:「 你们 心 里议论 的是什么呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, '或说『你 的罪 赦了』,或 说『你起来 行走』,哪一样 容易呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, '但 要叫 你们知道, 人 子 在 地上 有 赦 罪 的权柄。」就对瘫子 说:「我吩咐 你,起来, 拿 你 的褥子 回 家去吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, ' 那人当众人 面前 立刻 起来,拿著 他所 躺卧 的褥子回 家去,归荣耀与 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, ' 众人 都 惊奇,也 归荣耀与 神,并且 满心 惧怕,说:「 我们今日 看见 非常的事了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, ' 这事 以后,耶稣出去, 看见 一个税吏,名叫 利未,坐 在 税关上,就 对他 说:「你跟从 我来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, '他就 撇下 所有的,起来,跟从了 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, ' 利未 在 自己 家 里为耶稣 大 摆 筵席, 有 许多 税吏 和 别人 与 他们 一同坐席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, ' 法利赛人 和 文士 就向 耶稣 的门徒 发怨言 说:「你们为什么 和 税吏 并 罪人 一同吃 喝呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, ' 耶稣 对 他们 说:「无病的人 用不著 医生;有 病的人 才用得著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, '我来 本不是 召 义人悔改,乃是 召罪人 悔改。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, ' 他们 说:「约翰 的门徒 屡次 禁食 祈祷,法利赛人 的门徒 也是 这样;惟独 你的 门徒又吃 又 喝。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, ' 耶稣 对 他们 说:「 新郎 和陪伴之人 同在的时候,岂 能 叫 陪伴之人 禁食呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, '但 日子 将到, 新郎 要离开  他们, 那 日 他们就要禁食了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, ' 耶稣又 设一个比喻,对 他们 说:「 没有人 把 新 衣服 撕下 一块 来补 在 旧衣服上;若是这样,就 把新的 撕破了,并且 所撕下来的那块 新的 和旧的 也不 相称。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, '也 没有人 把新 酒 装 在 旧 皮袋里;若是这样,新 酒 必将皮袋 裂开 ,酒 便 漏出来,皮袋 也 就坏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, '但 新 酒 必须装 在 新 皮袋里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, ' 没有人 喝了 陈 酒又想 喝新的; 他总说 陈的 好。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, ' 有一个安息日,耶稣 从 麦地 经过。 他的 门徒 掐了 麦穗, 用手 搓著 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, ' 有几个 法利赛人 说:「你们为什么 做 安息日 不 可做 的事呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, ' 耶稣 对 他们 说:「经上记著大卫 和 跟从 他 的人饥饿 之时 所做 的事,连这个 你们也没有 念过吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, ' 他怎么进了 神 的殿, 拿 陈设饼 吃,又 给 跟从的人吃?这 饼除了 祭司以外,别人都不 可 吃。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, '又 对他们 说:「人 子 是 安息日 的主。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, ' 又 有一个 安息日,耶稣 进了 会堂 教训人, 在那里 有 一个人 右 手 枯干了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, ' 文士 和 法利赛人 窥探 耶稣, 在 安息日 治病不治病,要 得 把柄去告 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, '耶稣 却 知道 他们 的意念,就 对那 枯干 一只手 的人 说:「起来! 站 在 当中。」那人就 起来,站著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, ' 耶稣 对 他们 说:「我问 你们,在安息日 行善 行恶,救 命 害命,哪样 是可以的呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, '他就 周围看著 他们 众人,对那人 说:「伸出 手来!」 他把手一伸, 手 就 复了原。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, '他们 就 满心 大怒, 彼此 商议 怎样 处治 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, ' 那 时,耶稣 出去,上 山 祷告, 整夜 祷告 神; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, ' 到了 天亮,叫 他 的门徒来,就 从 他们 中间挑选 十二个人, 称 他们 为使徒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, '这十二个人有西门( 耶稣又 给他起名 叫彼得),还有 他 兄弟 安得烈,又有 雅各 和 约翰, 腓力 和 巴多罗买 , ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, ' 马太 和 多马, 亚勒腓 的儿子雅各 和 奋锐党 的西门, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, ' 雅各的儿子(或译:兄弟)犹大,和 卖主的 加略人 犹大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, ' 耶稣和 他们 下了山,站 在 一块平 地上; 同站的有许多 门徒,又有 许多 百姓,从 犹太 全 地和 耶路撒冷,并 泰尔、 西顿 的海边来, 都要 听 他讲道,又指望医治 他们 的病; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, '还有 被 污 鬼 缠磨的,也 得了医治。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, ' 众人 都想要 摸 他;因为 有能力 从 他 身上发出来, 医好了 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, ' 耶稣 举 目 看著 门徒,说:你们贫穷的人 有福了!因为 神 的国 是 你们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, '你们 饥饿 的人有福了!因为 你们将要饱足。你们 哀哭 的人有福了!因为 你们将要喜笑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, '「 人 为 人 子 恨恶 你们, 拒绝 你们, 辱骂你们, 弃掉 你们 的名,以为 是恶,你们就 有福了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, '当 那 日,你们要欢喜 跳跃,因为 你们 在 天 上的赏赐 是大的。 他们 的祖宗 待 先知 也是这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, '但 你们 富足的 人有祸了!因为 你们受过 你们 的安慰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, '你们 饱足 的人有祸了!因为 你们将要饥饿。你们 喜笑 的人有祸了!因为 你们将要哀恸 哭泣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, '「 人 都说 你们 好的时候,你们就有祸了!因为 他们 的祖宗 待 假先知 也是这样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, '「只是 我告诉 你们 这 听道的人,你们的 仇敌,要爱他! 恨 你们的,要待 他好! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, '咒诅 你们的,要为他祝福!凌辱 你们的,要为 他祷告! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, '有人打 你 这边的脸,连那边的 脸也 由他打。 有人夺 你 的外衣,连 里衣 也由他拿去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, '凡 求 你的,就给他。 有人夺 你的东西去,不用 再要回来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, ' 你们愿 意 人 怎样待 你们,你们也要怎样 待 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, ' 你们 若 单爱 那爱 你们的人,有 什么 可酬谢的呢?就是 罪人 也 爱 那爱 他们的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, ' 你们 若 善待 那善待 你们的人,有 什么 可酬谢的呢?就是 罪人 也是这样 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, ' 你们 若 借给人,指望 从 他 收回,有 什么 可酬谢的呢?就是罪人 也 借给 罪人,要 如数 收回。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, '你们 倒要 爱 仇敌,也要 善待他们,并要 借给人 不 指望偿还, 你们的 赏赐 就必 大了,你们也 必作 至高者 的儿子;因为 他 恩待 那忘恩的 和 作恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, '你们要 慈悲,像 你们的 父 慈悲一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, '「 你们不要 论断人,就 不 被论断; 你们不要 定人的罪,就 不 被定罪;你们要饶恕人,就 必蒙饶恕(饶恕:原文是释放); ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, '你们要给人,就 必有给 你们的,并且用十足的 升斗,连摇 带按,上尖下流地 倒 在 你们 怀里;因为 你们用 什么量器 量给人,也必用什么量器量给 你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, '耶稣又 用比喻 对他们 说:「瞎子 岂 能 领 瞎子,两个 人不是 都要掉 在 坑里吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, '学生 不 能 高过 先生; 凡 学成了 的不过 和 先生 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, ' 为什么 看见 你 弟兄 眼 中有刺,却 不 想 自己 眼 中有梁木呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, '你不 见 自己 眼 中有梁木,怎 能 对你 弟兄 说:『 容 我去掉 你 眼 中的刺』呢?你这假冒为善的人!先 去掉 自己 眼 中的梁木, 然后 才能看得清楚,去掉 你 弟兄 眼 中的刺。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, '「因为,没有 好 树 结 坏 果子,也 没有 坏 树 结 好 果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, ' 凡 树木 看 果子,就可以认出它来。 人不是 从 荆棘 上摘 无花果,也不是 从 蒺藜 里摘 葡萄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, '善 人 从 他心 里所存 的善 就发出 善来; 恶 人从 他心里所存的恶 就发出 恶来;因为 心 里所充满的, 口 里就说出来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, '「 你们为什么 称呼 我『主啊,主啊』却 不 遵 我的话 行呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, '凡 到 我 这里来, 听见 我 的话 就 去行的,我要告诉 你们 他 像 什么人: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, '他 像 一个人 盖 房子, 深深地 挖地, 把根基 安 在 磐石上; 到发 大水的时候,水 冲 那 房子, 房子总不 能 摇动,因为根基立在磐石上(有古卷:因为盖造 得好)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, '惟有 听见 不 去行的,就 像 一个人 在 土地 上盖 房子,没有 根基;水 一冲, 随即 倒塌了,并且 那 房子 坏 的 很大。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, ' 耶稣 对 百姓 讲完了 这一切 的话,就进了 迦百农。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, ' 有一个 百夫长 所宝贵的 仆人 害 病,快要 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, ' 百夫长风闻 耶稣的事,就托 讬 犹太人 的几个长老 去求 耶稣 来 救 他 的仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, ' 他们 到 了耶稣那里,就切切地 求 他 说:「 你给他行 这事 是 他所配得的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, '因为 他爱 我们的 百姓, 给我们 建造 会堂。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, '耶稣 就 和他们 同 去。 离 那家 不 远,百夫长 托 讬 几个朋友去见耶稣,对他 说:「主啊!不要 劳动;因 你到 我 舍 下,我不 敢当。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, ' 我 也自以为不 配 去 见你,只要 你说 一句话,我的 仆人 就 必好了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, '因为 我 在人的权 下,也 有 兵 在我 以下,对这个 说:『去!』他就 去; 对那个说:『来!』他就 来; 对我的 仆人说:『你做 这事!』他就 去做。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, ' 耶稣 听见 这话,就希奇 他, 转身 对跟随 的众人 说:「我告诉 你们,这么大 的信心,就是在 以色列中,我也没有 遇见过。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, ' 那托 讬来 的人回 到 百夫长家里,看见 仆人 已经好了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, ' 过了不多时(有古卷:次日),耶稣往 一座城 去,这城名叫 拿因, 他 的门徒 和 极多的 人 与他 同行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, ' 将近 城 门, 有一个死人 被抬出来。这人是他 母亲 独生的 儿子;他 母亲又 是 寡妇。 有 城 里的许多 人 同著 寡妇送殡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, ' 主 看见 那寡妇,就怜悯 她, 对她 说:「不要 哭!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, '于 是 进前 按著 杠,抬 的人就 站住了。 耶稣说:「少年人,我吩咐 你,起来!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, '那死 人就 坐起,并且 说话。耶稣便 把他 交给 他 母亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, ' 众人 都 惊奇, 归荣耀与 神,说:「 有大 先知 在 我们 中间兴起来了!」又说:「 神 眷顾了 他 的百姓!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, ' 他 这事 的风声 就 传 遍了 犹太 和 周围地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, ' 约翰 的门徒 把 这些事 都告诉 约翰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, '他便 叫 了两个 门徒来,打发 他们到 主那里去,说:「那将要来 的是 你吗?还是 我们等候 别人呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, ' 那两个人 来 到 耶稣那里,说:「施洗 的约翰 打发 我们 来问 你:『那将要来 的是 你吗?还是 我们等候 别人呢?』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, '正当 那 时候,耶稣治好了 许多 有疾病的, 受灾患的, 被恶 鬼附著的,又 开 恩 叫好些 瞎子 能看见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, ' 耶稣回答 说:「你们去,把 所看见 所听见 的事告诉 约翰,就是瞎子 看见,瘸子 行走,长大痲疯 的洁净, 聋子 听见,死人 复活,穷人 有福音传给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, ' 凡 不 因 我 跌倒的,就有 福了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, '约翰 所差来的人 既 走了,耶稣就 对 众人 讲论 约翰说:「你们从前出去 到 旷野,是要看 什么呢?要看 风 吹动 的芦苇吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, '你们出去,到底 是要看 什么?要看 穿 细软 衣服 的人吗?那穿 华丽 衣服、 宴乐 度日 的人是 在 王宫里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, '你们出去,究竟 是要看 什么?要看先知吗?我告诉 你们,是的, 他比先知 大多了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, '经上记著说:『 我要差遣 我的 使者 在你 前面 预备 道路』,所说的 就是 这个人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, '我告诉 你们,凡 妇人 所生的,没有一个 大过 约翰的;然而 神 国 里最小的 比他 还大。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, ' 众 百姓 和 税吏 既受过 约翰 的洗,听见这话,就以 神 为义; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, '但 法利赛人 和 律法师 没有 受 过约翰 的洗,竟为 自己 废弃了 神 的旨意。(29-30两节或译:众百姓和税吏听见了约翰的话,就受了他的洗,便以 神为义;但法利赛人和律法师不受约翰的洗,竟为自己废弃了 神的旨意。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, '主又说:「这样,我可用什么 比 这 世代 的人呢? 他们好像 什么呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, '好像 孩童 坐 在 街市上, 彼此 呼叫 说:我们向你们 吹笛, 你们不 跳舞;我们向你们举哀, 你们不 啼哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, ' 施洗 的约翰 来,不 吃 饼,不 喝 酒, 你们说 他是被鬼 附著的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, '人 子 来,也吃 也 喝, 你们说 他是贪食 好酒的 人,是税吏 和 罪人 的朋友。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, '但 智慧 之子 都以智慧 为是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, ' 有一个 法利赛人 请 耶稣 和 他 吃饭;耶稣就 到 法利赛人 家 里去坐席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, ' 那城 里 有一个女人, 是 个罪人, 知道 耶稣在 法利赛人 家 里坐席,就拿著 盛香膏 的玉瓶, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, ' 站 在耶稣背后,挨著 他 的脚 哭, 眼泪 湿了 耶稣 的脚,就 用自己 的头 发 擦干,又 用嘴连连亲 他 的脚, 把香膏 抹上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, ' 请 耶稣 的法利赛人 看见这事, 心 里说:「这人 若 是 先知, 必知道 摸 他 的是谁, 是个怎样 的女人; 乃是 个罪人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, ' 耶稣 对 他 说:「西门!我有 句话要对你 说。」 西门说:「夫子,请说。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, '耶稣说:「一个 债主 有 两个 人欠他的债;一个 欠 五十两 银子, 一个 欠五两银子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, '因为他们 无 力 偿还,债主就开 恩免了 他们两个人的债。 这两个人 哪一个 更 爱 他呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, '西门 回答 说:「我想 是那 多 得恩免的人。」 耶稣 说:「你断 的不错。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, '于 是 转过来 向著 那女人,便对西门 说:「你看见 这 女人吗?我进了 你的 家,你没有 给 我水 洗 脚;但 这 女人用眼泪 湿了 我的 脚, 用 头发 擦干。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, '你没有 与 我 亲嘴;但 这 女人从 我进来 的时候 就不 住地 用嘴亲 我的 脚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, '你没有 用油 抹 我的 头;但 这 女人用香膏 抹 我的 脚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, '所以 我告诉 你,她 许多的 罪 都赦免了,因为 她的爱 多;但 那 赦免 少的,他的爱 就少。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, '于 是 对那女人 说:「你的 罪 赦免了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, ' 同席 的人 心 里说:「这 是 什么人, 竟 赦免 人的罪呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, ' 耶稣对 那女人 说:「你的 信 救了 你; 平平安安 回去吧!」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, ' 过了 不多日, 耶稣 周游 各 城 各乡 传道, 宣讲 神 国的福音。 和他 同 去的有十二个门徒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, '还有 被恶 鬼所附、 被疾病所累、已经治好 的几个 妇女,内中有称为 抹大拉 的马利亚(曾有七 个鬼 从 她 身上赶出来), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, '又 有希律 的家宰 苦撒 的妻子 约亚拿,并 苏撒拿,和 好些 别的妇女, 都是用 自己的 财物 供给 耶稣和门徒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, ' 当许多 人 聚集、又 有人从各 城 里出来 见 耶稣的时候,耶稣就用 比喻 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, '「有一个撒种的 出去 撒 种。 撒的时候, 有落在 路 旁的, 被人践踏, 天上 的飞鸟 又来吃尽了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, ' 有 落 在 磐石上的, 一出来 就枯干了,因为 得不著 滋润。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, ' 有 落 在 荆棘 里的, 荆棘 一同生长,把它 挤住了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, '又 有 落 在 好 土里的, 生长起来,结 实 百倍。」耶稣说了 这些话,就大声说:「有 耳 可听的,就应当听!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, ' 门徒 问 耶稣说:「这 比喻 是 什么意思呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, ' 他说:「 神 国 的奥秘 只叫 你们 知道;至于  别人,就用 比喻,叫 他们看 也看不见, 听 也听不明。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, '「 这比喻 乃是 这样:种子 就是 神 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, ' 那些 在路 旁的,就是 人 听了道,随后 魔鬼 来, 从 他们 心 里把道 夺去,恐怕 他们信了 得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, ' 那些在 磐石上的, 就是 人听道, 欢喜 领受,但 心中没 有 根, 不过暂时 相信, 及至 遇见试炼 就退后了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, ' 那落 在 荆棘里的,就是 人 听了道,走开 以后, 被 今生 的思虑、 钱财、 宴乐 挤住了,便 结 不出成熟的子粒来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, ' 那落在 好 土里的,就是 人 听了 道,持守 在 诚实 善良 的心里,并且 忍耐 著结实。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, '「 没有人 点 灯 用器皿 盖上,或 放 在床 底下,乃是 放 在 灯台上,叫 进来 的人看见 亮光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, '因为 掩藏的 事没有 不 显出来的; 隐瞒的 事没有 不 露出来 被人知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, '所以,你们应当小心 怎样 听;因为 凡 有的,还要加给 他; 凡 没 有的,连 他自以为 有的,也要夺去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, ' 耶稣 的母亲 和 他弟兄 来了, 因为 人多,不 得 到 他跟前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, ' 有人告诉 他说:「你 母亲 和 你 弟兄 站 在外边,要 见 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, ' 耶稣 回答 说:「听了 神 之道 而 遵行 的人就是 我的 母亲, 我的 弟兄了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, ' 有一 天, 耶稣 和 门徒 上了 船, 对 门徒 说:「我们可以渡 到 湖 那边去。」他们就 开 了船。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, ' 正行的时候,耶稣睡著了。 湖 上 忽然起了 暴风, 船将满了水, 甚是危险。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, ' 门徒来 叫醒了 他,说:「夫子!夫子!我们丧命啦!」 耶稣醒了,斥责 那狂风 大浪;风浪就 止住, 平静了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, ' 耶稣对他们 说:「你们的 信心 在哪里呢?」 他们又惧怕 又希奇, 彼此 说:「这 到底 是 谁? 他吩咐 风 和 水,连 风和水也听从 他了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, ' 他们 到 了格拉森(有古卷:加大拉)人的地方, 就是 加利利 的对面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, ' 耶稣 上 了岸,就有 城 里一个 被鬼 附著 的人 迎面而来。 这个人许久 不 穿 衣服, 不 住 房子,只 住在 坟茔里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, ' 他见了 耶稣,就俯伏 在他面前, 大 声 喊叫,说:「至高 神 的儿子 耶稣,我 与 你 有什么相干?求 你 不要 叫我 受苦!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, '是因 耶稣曾吩咐 污 鬼 从 那人 身上出来。原来 这鬼屡次 抓住 他; 他常被人看守,又被铁链 和 脚镣 捆锁, 他竟把锁链 挣断,被 鬼 赶 到 旷野去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, ' 耶稣 问 他说:「你 名 叫 什么?」 他说:「我名叫『群』」;这是因为 附著 他 的鬼 多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, '鬼就 央求 耶稣,不要 吩咐 他们 到 无底坑 里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, ' 那里 有 一大群 猪 在 山 上吃食。 鬼央求 耶稣, 准 他们 进入猪里去。 耶稣准了 他们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, '鬼 就 从 那人 出来,进 入 猪里去。于 是 那群 猪闯 下 山崖,投在 湖 里 淹死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, '放猪的 看见 这 事就 逃跑了, 去告诉 城里 和 乡下的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, ' 众人出来 要看 是什么事; 到了 耶稣那里, 看见 鬼 所离开  的那人,坐 在耶稣 脚 前,穿著衣服, 心里明白过来,他们就 害怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, ' 看见 这事的便将被鬼附著 的人怎么 得救 告诉 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, ' 格拉森 四围的 人,因为 害怕得很,都求 耶稣 离开  他们; 耶稣 就上 船 回去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, ' 鬼 所离开  的那 人 恳求 和耶稣 同 在;耶稣却 打发 他回去,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, '「你回 家去, 传说 神 为你 做了 何等大的事。」他就 去,满 城 里传扬 耶稣 为他 做了 何等大的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, ' 耶稣 回来的时候,众人 迎接 他,因为 他们 都 等候 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, ' 有一个 管 会堂 的, 名叫 睚鲁, 来 俯伏 在 耶稣 脚前,求 耶稣 到 他 家里 去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, '因 他 有 一个独生 女儿,约有 十二 岁, 快要死了。 耶稣 去的时候,众人 拥挤 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, ' 有一个女人,患了 十二 年 的 血 漏, 在医生 手里花尽了 他一切 养生的,并没有 一人 能 医好他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, '她来到 耶稣背后,摸 他 的衣裳 䍁子, 血 漏 立刻 就止住了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, ' 耶稣 说:「摸 我的 是谁?」 众人 都不承认。彼得 和同行的人都说:「夫子,众人 拥拥挤挤 紧靠 著你。(有古卷加:你还问摸我的是谁吗?)」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, ' 耶稣 说:「总有人 摸 我,因 我 觉得 有能力 从 我 身上出去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, ' 那女人 知道 不能 隐藏,就战 战 兢兢地 来 俯伏 在耶稣脚前, 把摸 他 的缘故 和 怎样 立刻 得好了,当著 众人 都说出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, ' 耶稣对她 说:「女儿,你的 信 救了 你; 平平安安地 去吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, ' 还 说话的时候,有人 从 管会堂的 家里来,说:「 你的 女儿 死了,不要 劳动 夫子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, ' 耶稣 听见 就 对他说:「不要 怕,只要 信!你的女儿就 必得救。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, ' 耶稣 到 了他的家,除了 彼得、 约翰、 雅各,和 女儿 的父 母,不 许 别人 同 他 进去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, ' 众人 都为这女儿 哀哭 捶胸。 耶稣说:「不要 哭! 她不是 死了, 是睡著了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, ' 他们晓得 女儿已经死了,就嗤笑 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, ' 耶稣 拉著 她 的手,呼叫 说:「女儿,起来吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, '她 的灵魂 便 回来,她就 立刻 起来了。 耶稣吩咐 给 她 东西吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, ' 她 的父母 惊奇得很; 耶稣嘱咐 他们,不要 把所做的事 告诉人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, ' 耶稣叫齐了 十二个门徒,给 他们 能力、 权柄,制伏 一切的 鬼, 医治 各样的病, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, '又 差遣 他们 去宣传 神 国的道, 医治 病人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, ' 对 他们 说:「 行路的时候,不要 带 拐杖 和 口袋,不要 带食物 和 银子,也不要 带 两件 褂子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, ' 无论 进 哪一家,就住在 那里,也 从那里 起行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, ' 凡 不 接待 你们的,你们离开  那 城的时候,要把 脚 上的尘土 跺下去, 见证 他们的不是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, '门徒就 出去,走 遍 各乡 宣传福音, 到处 治病。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, ' 分封的王 希律 听见 耶稣所做 的一切事,就 游移不定;因为 有人 说:「 是约翰 从 死 里复活」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, '又 有人说:「 是以利亚 显现」;还 有人说:「 是古时的 一个 先知 又活了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, ' 希律 说:「约翰 我 已经斩了,这 却 是 什么人?我竟听见 他 这样的事呢?」就 想要 见 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, ' 使徒 回来,将 所做 的事告诉 耶稣,耶稣就 带 他们 暗暗地 离开 那里,往 一座城去;那城名叫 伯赛大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, '但 众人 知道了,就跟著 他去;耶稣便 接待 他们,对他们 讲论 神 国的道, 医治 那些 需要 医治的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, ' 日头 快要 平西, 十二个 门徒来 对他 说:「请叫众人 散开 ,他们好 往 四面 乡村 里去借宿 找 吃的,因为 我们这里 是 野 地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, ' 耶稣 说:「你们 给 他们 吃吧!」 门徒说:「我们 不 过 有五个 饼, 两条 鱼, 若不 去 为 这 许多人 买  食物就不够。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, '那时,人数约 有 五千。 耶稣对 门徒 说:「叫他们 一排一排地坐下,每排 大约 五十个人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, '门徒就 如此 行, 叫众人 都坐下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, ' 耶稣拿著 这五个 饼, 两条 鱼,望著 天 祝福, 擘开 , 递给 门徒,摆 在众人面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, '他们 就 吃,并且 都吃饱了; 把剩下的 零碎 收拾起来,装满了十二 篮子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, ' 耶稣 自己 祷告的时候,门徒 也同 他在那里。 耶稣问 他们 说:「众人 说 我 是 谁?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, ' 他们 说:「有人说是施洗的 约翰; 有人 说是以利亚;还 有人 说 是古时的 一个 先知 又活了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, ' 耶稣 说:「 你们 说 我 是 谁?」 彼得 回答 说:「是 神 所立的基督。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, ' 耶稣切切地 嘱咐 他们,不可 将这事 告诉人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, '又说:「 人 子 必须 受 许多的苦, 被 长老、 祭司长、和 文士 弃绝,并且 被杀, 第三 日 复活。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, '耶稣又 对 众人 说:「若 有人 要 跟从 我,就当舍 己, 天天 背起 他 的十字架 来跟从 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, '因为,凡 要 救 自己 生命(生命:或译灵魂;下同)的,必丧掉 生命; 凡 为 我 丧掉 生命的, 必救了 生命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, ' 人 若赚得 全 世界,却 丧了 自己, 赔上自己,有什么 益处呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, ' 凡 把我 和 我的 道 当作可耻的,人 子 在 自己 的荣耀里,并 天父 与 圣 天使 的荣耀里降临 的时候,也要把那人 当作可耻的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, ' 我实在 告诉 你们, 站 在这里的,有人 在没 尝 死味 以前,必看见 神 的国。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, ' 说了这 话 以后 约有 八 天, 耶稣带著 彼得、 约翰、 雅各 上 山 去祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, ' 正 祷告的时候,他 的面 貌 就 改变了, 衣服 洁白 放光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, ' 忽然 有 摩西、 以利亚 两个 人 同耶稣 说话; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, '他们 在 荣光 里显现,谈论 耶稣 去世的事,就是 他在 耶路撒冷 将要 成的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, ' 彼得 和 他 的同伴 都 打盹,既 清醒了,就看见 耶稣 的荣光,并 同他 站著 的那两个 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, ' 二人 正要和 耶稣 分离的时候,彼得 对 耶稣 说:「夫子,我们 在 这里 真好! 可以搭 三座 棚,一座 为你, 一座 为摩西, 一座 为以利亚。」他却不 知道 所说的是什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, ' 说 这话的时候,有一朵云彩 来 遮盖 他们; 他们 进 入 云彩 里就惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, ' 有声音 从 云彩 里出来,说:「这是我的儿子,我所拣选的(有古卷:这 是 我的 爱子),你们要听 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, ' 声音 住了,只 见 耶稣一人在那里。 当 那些 日子,门徒 不提 所看见的事, 一样 也不 告诉人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, ' 第二 天,他们 下了 山,就有许多 人 迎见 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, ' 其中 有一人 喊叫 说:「夫子!求 你 看顾 我的 儿子,因为 他是 我的 独生子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, ' 他 被鬼 抓住 就 忽然 喊叫;鬼又 叫他 抽疯, 口中流沫,并且 重重地伤害 他,难以 离开  他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, ' 我求过 你的 门徒, 把鬼 赶出去,他们却是 不 能。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, ' 耶稣 说:「嗳!这又不信 又 悖谬 的世代啊,我 在 你们这里, 忍耐 你们 要到 几时呢?将你的 儿子 带到 这里来吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, ' 正 来的时候,鬼 把他 摔倒, 叫他重重地抽疯。 耶稣 就斥责 那污 鬼, 把孩子 治好了, 交给 他 父亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, ' 众人 都诧异 神 的大能(大能:或译威荣)。 耶稣所做 的一切事,众人 正希奇的时候,耶稣对 门徒 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, '「你们 要把这些 话 存 在 耳中,因为 人 子 将要 被交 在 人 手里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, ' 他们不明白 这 话, 意思乃是 隐藏 的,叫 他们不 能明白,他们也 不敢 问 这 话的意思。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, ' 门徒 中间 起了 议论,谁 将为 大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, ' 耶稣 看出 他们 心 中的议论,就领 一个小孩子来,叫他 站 在自己 旁边, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, ' 对他们 说:「凡 为 我 名 接待 这 小孩子的,就是接待 我; 凡 接待 我的,就是接待 那差 我来的。 你们 中间 最小的,他 便为 大。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, ' 约翰 说:「夫子,我们看见 一个人 奉 你的 名 赶 鬼,我们就 禁止 他,因为 他不 与 我们 一同跟从你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, ' 耶稣 说:「不要 禁止他;因为 不 敌挡 你们的,就是 帮助 你们的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, ' 耶稣 被接上升 的日子 将到, 他 就定意 向 耶路撒冷 去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, '便 打发 使者 在他 前 头走。 他们 到了 撒马利亚 的一个村庄,要 为他 预备。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, ' 那里的人不 接待 他,因 他 面 向 耶路撒冷 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, ' 他的门徒 雅各、 约翰 看见了,就说:「主啊,你要 我们吩咐 火 从 天上 降下来 烧灭 他们,像以利亚所做的(有古卷没有像以利亚所做的这几个字)吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, ' 耶稣转身 责备 两个门徒,说:「你们的心如何,你们并不知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, '人子来不是要灭人的性命(性命或译:灵魂;下同),是要救人的性命。」说著就 往 别的 村庄 去了(有古卷只有五十五节首句,五十六节末句)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, ' 他们 走 路的时候,有一人 对 耶稣 说:「你无论 往哪里去,我要跟从 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, ' 耶稣 说:「狐狸 有 洞, 天空 的飞鸟 有窝,只是 人 子 没 有 枕 头 的地方。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, '又 对 一个人 说:「跟从 我来!」 那人说:「主,容 我 先 回去 埋葬 我的 父亲。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, ' 耶稣 说:「任凭 死人 埋葬 他们的 死人, 你 只管去 传扬 神 国的道。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, '又 有一人 说:「主,我要跟从 你,但 容 我 先 去辞别 我 家里的人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, ' 耶稣 说:「手 扶著 犁 向 后 看的,不 配进 神 的国。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, ' 这事 以后,主 又设立 七十个人, 差遣 他们 两个 两个地 在他 前 面,往 自己 所要 到 的各 城 各地方去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, '就 对 他们 说:「 要收的庄稼 多, 做工的人 少。所以,你们当求 庄稼 的主 打发 工人 出去 收他 的庄稼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, '你们去吧! 我差 你们出去,如同 羊羔 进入 狼群。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, '不要 带 钱囊,不要 带口袋,不要 带鞋;在 路 上也 不要 问人的安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, ' 无论 进 哪一家,先 要说:『愿 这 一家 平安。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, ' 那里 若 有当得平安的人(当得平安的人:原文是平安 之子),你们 所求的平安 就必临 到 那家;不然,就归 与 你们了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, ' 你们要住 在 那 家,吃 喝 他们所供给的,因为 工人 得 工价 是应当的;不要 从 这家 搬 到 那家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, ' 无论 进 哪 一城, 人若接待 你们,给你们 摆上什么,你们就吃什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, ' 要医治 那城 里 的病人, 对他们 说:『 神 的国 临近 你们了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, ' 无论 进 哪 一城, 人若不 接待 你们,你们就 到 街上去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, '说:『就是 你们 城 里的尘土 黏 在 我们的 脚上,我们也当著你们 擦去。虽然 如此,你们该知道 神 的国 临近了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, '我告诉 你们, 当 审判的 日子,所多玛所受的,比 那 城 还 容易受呢!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, '「哥拉汛哪,你 有祸了!伯赛大啊,你 有祸了!因为 在 你们 中间所行 的 异能 若 行 在 泰尔、 西顿,他们早 已 披麻 蒙灰,坐 在地上悔改了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, ' 当 审判的日子,泰尔、 西顿所受的,比 你们 还容易受呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, ' 迦百农啊,你 已经升 到 天上(或译:你将要升到天上吗),将来必推 下 阴间。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, '又对门徒说:「听从 你们 的就是听从 我; 弃绝 你们 的就是弃绝 我; 弃绝 我 的就是弃绝 那差 我来的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, ' 那七十 个人 欢欢喜喜地 回来,说:「主啊!因 你的 名,就是鬼 也 服了 我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, ' 耶稣对他们 说:「我曾看见 撒但 从 天上 坠落,像 闪电一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, ' 我已经给 你们 权柄 可以践踏 蛇 和 蝎子,又 胜过 仇敌 一切的 能力, 断没有 什么 能害 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, '然而,不要 因 鬼 服了 你们 就欢喜,要 因 你们的 名 记录 在 天 上欢喜。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, '正当 那 时,耶稣被 圣 灵 感动就 欢乐,说:「父啊,天 地 的主,我感谢 你!因为 你将这些事 向 聪明 通达 人就藏起来,向婴孩 就 显出来。父啊!是的,因为 你的 美意 本是 如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, '一切所有的 都是 我 父 交付 我的;除了 父, 没有人 知道 子 是 谁;除了 子 和 子 所愿 意 指示的, 没有人知道父 是 谁。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, ' 耶稣转身 暗暗地 对 门徒 说:「 看见 你们所看见的,那眼睛 就有福了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, ' 我告诉 你们, 从前有许多 先知 和 君王 要 看 你们 所看的,却 没有 看见, 要听 你们所听的,却 没有 听见。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, ' 有一个 律法师 起来 试探 耶稣,说:「夫子!我该做 什么 才可以承受 永 生?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, ' 耶稣对 他 说:「律法 上 写 的是什么?你念 的是怎样呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, ' 他回答 说:「你要尽 心、 尽 性、 尽 力、 尽 意 爱 主─你的 神;又要 爱 邻舍 如同 自己。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, ' 耶稣 说:「你回答 的是;你这样 行,就 必得永生。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, ' 那人要 显明 自己有理,就对 耶稣 说:「 谁 是 我的 邻舍呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, '耶稣 回答 说:「有一个 人 从 耶路撒冷 下 耶利哥去, 落 在强盗手中。他们 剥去 他的衣裳, 把他打个半死,就丢下 他 走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, ' 偶然 有一个 祭司 从 这 条路 下来, 看见 他 就从那边过去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, ' 又有 一个利未人 来 到 这地方, 看见他,也照样从那边过去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, '惟有 一个 撒马利亚人 行路 来 到 那里, 看见 他就动了慈心, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, ' 上前 用油 和 酒 倒 在他 的伤处,包裹好了, 扶 他 骑上 自己的 牲口,带 到 店 里去 照应 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, ' 第二天 拿出 二 钱银子来,交 给店主, 说:『你且照应 他; 此外所费用的,我 回来 必还 你。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, '你 想,这 三个 人哪一个 是 落 在 强盗 手中的邻舍呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, ' 他说:「是 怜悯 他的。」 耶稣 说:「你 去 照样 行吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, ' 他们 走路的时候,耶稣 进了 一个 村庄。 有一个 女人,名叫 马大,接 他到自己家里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, ' 她 有 一个妹子,名叫 马利亚, 在 耶稣 脚 前坐著 听 他 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, ' 马大 伺候的事 多,心里忙乱,就 进前来,说:「主啊, 我的 妹子 留下 我 一个人 伺候,你 不 在意吗? 请吩咐 她 来帮助 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, ' 耶稣 回答 说:「马大!马大!你为 许多的事 思虑 烦扰, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, '但 是 不可少的 只有一件; 马利亚 已经选择 那上好的 福分, 是不能 夺去的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, ' 耶稣 在 一个 地方 祷告; 祷告完了,有个 门徒 对 他 说:「求主 教导 我们 祷告,像 约翰 教导 他 的门徒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, ' 耶稣 说:「 你们祷告的时候,要说:我们在天上的父(有古卷:父啊):愿 人都尊你的 名 为圣。愿 你的 国 降临;愿 你的旨意行在地上,如同行在天上(有古卷没有愿 你的旨意....)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, '我们 日用的 饮食, 天天 赐给 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, ' 赦免 我们的 罪,因为 我们 也 赦免 凡 亏欠 我们的人。 不 叫我们 遇见 试探;救我们脱离凶恶(有古卷没有末句)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, '耶稣又 说:「 你们 中间谁 有 一个朋友 半夜 到 他 那里去, 说:『朋友!请借 给我 三 个饼; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, '因为 我 有一个朋友 行 路,来 到 我这里, 我没 有 什么 给他 摆上。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, '那人 在里面 回答 说:『不要 搅扰 我,门 已经 关闭, 孩子们 也 同 我 在 床上了,我不 能 起来 给 你。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, '我告诉 你们,虽 不 因 他 是 朋友 起来 给 他,但 因 他 情词迫切地直求,就必起来 照 他所需用 的给 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, '我又 告诉 你们,你们祈求,就 给 你们;寻找,就 寻见;叩门,就 给你们 开 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, '因为,凡 祈求的,就得著; 寻找的,就寻见; 叩门的,就给他开 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, ' 你们 中间 作父亲的,谁有儿子 求饼,反给他石头呢? 求鱼,反拿 蛇 当 鱼 给他呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, ' 求 鸡蛋,反给 他 蝎子呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, ' 你们 虽然 不好,尚且知道 拿好 东西 给 儿女;何况 天 父,岂不更 将圣 灵 给 求 他的人吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, ' 耶稣 赶出 一个 叫人 哑巴 的鬼; 鬼 出去了,哑巴 就说出话来; 众人 都希奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, '内中 却 有人 说:「他是靠著 鬼 王 别西卜 赶 鬼。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, '又 有人 试探耶稣,向 他 求 从 天上 来的神迹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, ' 他 晓得 他们 的意念,便对他们 说:「凡 一国 自相 纷争,就成为荒场; 凡一家 自相纷争,就必败落。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, ' 若 撒但 自相 纷争,他 的国 怎能 站得住呢?因为 你们说 我 是靠著 别西卜 赶 鬼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, ' 我 若 靠著 别西卜 赶 鬼,你们的 子弟 赶鬼 又靠著 谁呢?这样,他们 就要 断定你们的 是非。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, ' 我 若 靠著 神 的能力 赶 鬼,这就是 神 的国 临 到 你们了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, ' 壮士 披挂整齐,看守 自己的 住宅,他 所有的 都 平安无事; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, '但 有一个比他 更壮的 来,胜过 他,就夺去 他 所倚靠 的盔甲兵器,又 分了 他 的赃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, '不 与 我相合的,就是 敌 我的; 不 同 我 收聚的,就是分散的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, '「 污 鬼 离了 人身,就在 无水 之地 过来过去,寻求 安歇之处;既 寻 不著,便 说:『我要回 到 我 所 出来 的屋里去。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, ' 到了,就看见 里面打扫干净, 修饰好了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, '便 去 另 带了 七个 比自己 更恶 的鬼来,都 进去 住 在那里。 那 人 末后的 景况比先前 更不好了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, ' 耶稣 正说 这话的时候,众人 中间 有一个 女人 大 声 说:「怀 你 胎 的和 乳 养 你的有福了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, ' 耶稣 说:「是,却还不如 听 神 之道 而 遵守 的人有福。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, ' 当众人 聚集的时候,耶稣开  讲说:「这 世代 是 一个邪恶的 世代。他们求 看神迹,除了 约拿 的神迹以外, 再没有 神迹 给 他们看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, ' 约拿 怎样为尼尼微人 成了 神迹,人 子 也要 照样 为这 世代 的人成了神迹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, '当 审判的时候,南方 的女王 要 起来 定这世代的罪;因为 她从 地 极 而来,要听 所罗门 的智慧话。 看哪!在这里 有一人比所罗门 更大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, '当 审判的时候,尼尼微 人 要 起来 定这世代的罪,因为 尼尼微人听了 约拿 所传的 就悔改了。 看哪!在这里 有一人比约拿 更大。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, '「没有人 点 灯 放 在 地窨子里,或是 斗 底下,总是 放在 灯台上,使 进来 的人得见 亮光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, '你 眼睛 就是 身上 的灯。 你的 眼睛 若 瞭 了亮, 全 身 就 光明; 眼睛若 昏花, 全身 就 黑暗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, '所以,你要省察,恐怕 你 里 头的光 或者 黑暗了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, ' 若是 你 全 身 光明,毫无 黑暗,就必 全然 光明,如同 灯 的明光 照亮 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, ' 说话的时候,有一个法利赛人 请 耶稣 同 他 吃饭,耶稣就 进去 坐席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, ' 这法利赛人 看见 耶稣饭 前 不 洗手 便诧异。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, ' 主 对 他 说:「如今 你们 法利赛人 洗净 杯 盘 的外面,你们 里面 却 满了 勒索 和 邪恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, '无知的人哪,造 外面的,不 也 造 里面吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, '只要 把里面的 施舍 给人, 凡物 于 你们 就都 洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, '「 你们 法利赛人 有祸了!因为 你们将薄荷、 芸香 并 各样 菜蔬 献上十分之一,那公义 和 爱 神 的事反倒 不行了。 这 原是你们当 行的;那也是 不可 不行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, '你们 法利赛人 有祸了!因为 你们喜爱 会堂 里 的首位,又 喜爱人在 街市 上问你们的安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, ' 你们 有祸了!因为你们 如同 不显露的 坟墓, 走 在上面 的人 并不 知道。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, ' 律法师 中有一个 回答 耶稣 说:「夫子!你这样 说 也 把我们 糟蹋了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, ' 耶稣说:「你们 律法师 也 有祸了!因为 你们把难担的 担子 放在 人身上, 自己 一个 指头 却不肯 动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, '你们 有祸了!因为 你们修造 先知 的坟墓, 那先知 正是你们的 祖宗 所杀的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, '可见 你们 祖宗 所做的事,你们又证明 又 喜欢;因为 他们 杀了 先知, 你们 修造先知的坟墓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, '所以 神 用智慧(用智慧:或译的智者) 曾说:『我要差遣 先知 和 使徒 到 他们那里去, 有的 他们 要杀害,有的他们 要逼迫』, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, '使 创世 以来 所流 众 先知 血 的罪都要问 在 这 世代的人身上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, '就是从 亚伯 的血起,直到 被杀 在坛 和 殿 中间 撒迦利亚 的血为止。我实在 告诉 你们,这都要问 在 这 世代的人身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, '你们 律法师 有祸了!因为 你们把知识 的钥匙 夺了去,自己 不 进去,正要进去 的人你们也 阻挡他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, ' 耶稣 从那里出来,文士 和 法利赛人 就 极力地 催逼他, 引动 他 多说话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, '私下窥听,要拿 他 的话柄。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, ' 这时,有几万 人 聚集,甚至 彼此 践踏。耶稣开  讲,先 对 门徒说:「你们 要防备 法利赛人 的酵, 就是 假冒为善。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, ' 掩盖 的事没有 不 露出来的; 隐藏的事 没有不 被人知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, '因 此, 你们在 暗 中所说的,将要在 明处 被人听见; 在 内室 附 耳 所说的,将要在 房 上被人宣扬。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, '「 我的 朋友,我对你们 说,那杀 身体 以后 不 能 再 做 什么的,不要 怕他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, ' 我要指示 你们 当怕 的是谁:当怕 那杀了 以后 又有 权柄 丢 在 地狱里的。我实在 告诉 你们,正要怕 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, '五个 麻雀 不是 卖 二分 银子吗?但在 神 面前,一个 也不 忘记; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, '就是 你们的 头 发,也 都 被数过了。不要 惧怕,你们比许多 麻雀 还贵重!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, '「我又 告诉 你们,凡 在人 面前 认 我的,人 子在 神 的使者 面前 也 必认 他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, ' 在人 面前 不认 我的,人子在 神 的使者 面前 也必不认他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, ' 凡 说 话 干犯 人 子的, 还可得赦免;惟独 亵渎 圣 灵的,总不 得赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, ' 人带 你们 到 会堂,并 官府 和 有权柄的人面前,不要 思虑 怎么 分诉, 说 什么话; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, '因为 正在 那 时候,圣 灵 要指教 你们 当 说的话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, ' 众人 中 有一个人 对耶稣 说:「夫子!请你吩咐 我的 兄长 和 我 分开  家业。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, ' 耶稣 说:「你这个人!谁 立 我 作 你们 断事的官, 给你们分家业呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, '于 是 对 众人 说:「你们要谨慎 自守,免去 一切的 贪心,因为 人 的生命 不 在乎 家道 丰富。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, '就 用 比喻 对 他们 说:「有一个 财主 田产 丰盛; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, ' 自己 心里 思想 说:『 我的 出产 没 有 地方 收藏,怎么 办呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, '又 说:『我要这么 办:要把我的 仓房 拆了,另 盖 更大的, 在那里 好收藏 我一切的 粮食 和 财物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, '然后 要对我的 灵魂 说:灵魂哪,你有 许多 财物 积存,可作 多 年的费用,只管安安逸逸地 吃 喝 快乐吧!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, '神 却 对他 说:『无知的人哪,今 夜 必 要 你的 灵魂; 你 所预备 的要归 谁呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, '凡为自己 积财,在 神 面前 却 不 富足的,也是这样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, '耶稣 又 对 门徒 说:「所以 我告诉 你们,不要 为生命 忧虑 吃 什么, 为身体 忧虑穿 什么; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, '因为 生命 胜于  饮食, 身体 胜于 衣裳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, '你想 乌鸦, 也不 种 也不 收, 又没 有 仓 又没有 库, 神 尚且 养活 牠。你们 比飞鸟 是何等地 贵重呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, ' 你们 哪一个 能 用思虑使寿数多加一刻呢(或译:使 身量 多加 一肘呢)? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, ' 这最小的事,你们尚且 不 能做,为什么 还忧虑 其余 馀的事呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, '你想 百合花 怎么 长起来;它也不 劳苦,也不 纺线 缐。然而 我告诉 你们,就是所罗门 极 荣华的时候,他所穿戴的,还不 如 这 花一朵呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, '你们这小信的人哪, 野地 里 的草 今天 还在,明天 就 丢 在 炉里, 神 还 给它这样的 妆饰,何况 你们呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, ' 你们 不要 求 吃 什么, 喝 什么,也 不要 挂心; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, ' 这 都是 外邦人 所求的。 你们必须用 这些东西,你们的 父 是知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, '你们只要 求 他 的国, 这些 东西就必加给 你们了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, '你们这小 群,不要 惧怕,因为 你们的 父 乐意 把国 赐给 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, '你们要变卖 所有 的 赒济人,为自己 预备 永不 坏的 钱囊,用不尽的 财宝 在 天上, 就是贼 不能 近、虫 不能 蛀的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, '因为,你们的 财宝 在 哪里,你们的 心 也 在 那里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, '「你们 腰 里要 束上带,灯 也 要点著, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, ' 自己 好像 仆人 等候 主人 从 婚姻的筵席 上回来。 他来到, 叩门,就立刻 给他 开 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, ' 主人 来了,看见 仆人警醒,那 仆人 就有福了。我实在 告诉 你们, 主人 必叫他们 坐席,自己束上带, 进前 伺候 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, '或是 二更天来,或是 三 更 天来, 看见 仆人这样,那 仆人就 有福了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, ' 家主 若 知道 贼 什么 时候 来,就必警醒,不 容 贼挖透 房屋, 这 是你们所知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, '你们 也 要 预备;因为 你们想 不 到的时候,人 子 就来了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, ' 彼得 说:「主啊,这 比喻 是为 我们 说的呢?还是 为 众人呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, ' 主 说:「 谁 是 那忠心 有见识的 管家, 主人 派 他管理 家里 的人,按时 分 粮给他们呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, ' 主人 来到,看见 仆人这样 行,那 仆人 就有福了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, '我实在 告诉 你们, 主人要派 他 管理 一切 所有的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, ' 那 仆人 若 心 里说:『我的 主人 必来 得迟』,就 动手 打 仆人 和 使女,并且 吃 喝 醉酒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, '在 他想 不到 的日子, 不 知道 的时辰,那 仆人 的主人 要来,重重地处治他(或译: 把他 腰斩了), 定 他 和 不忠心的 人同罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, ' 仆人 知道 主人的 意思,却 不 预备,又不 顺 他 的意思 行,那 仆人必多 受责打; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, '惟有 那不 知道的, 做了 当 受责打的事,必少 受责打;因为 多 给 谁,就向 谁 多 取; 多 托 讬 谁,就向谁 多 要。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, '「我来 要把火 丢 在 地上, 倘若 已经 著起来,不也是我所愿 意 的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, ' 我有 当受的洗 还没有 成就, 我是何等地 迫切呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, '你们以为 我来,是叫 地 上太平吗?我告诉 你们,不是,乃是 叫人纷争。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, ' 从 今以后, 一 家 五个 人将要 纷争:三个 人和 两个人相争, 两个 人和 三个人相争; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, '父亲 和 儿子 相争, 儿子 和 父亲相争;母亲 和 女儿相争, 女儿 和 母亲相争;婆婆 和 媳妇相争, 媳妇 和 婆婆相争。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, ' 耶稣又 对众人 说:「 你们看见 西边 起了 云彩,就 说:『要下 一阵雨』;果然 就 有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, ' 起了 南风,就说:『 将要 燥热』;也就 有了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, '假冒为善的人哪,你们知道 分辨 天 地 的气色, 怎么 不 知道 分辨 这 时候呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, '「 你们又 为何不 自己 审量 什么 是合理的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, ' 你同 告你的 对头 去 见 官,还在 路上,务要 尽力地 和 他 了结;恐怕 他拉 你 到 官面前, 官 交付 差役, 差役 把你 下 在 监里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, '我告诉 你, 若有半文 钱 没有 还清,你断不能 从那里 出来。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, ' 正当 那 时,有人 将 彼拉多 使加利利人 的血 搀杂 在 他们 祭物 中的事告诉 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, ' 耶稣 说:「你们以为 这些 加利利人 比 众 加利利人 更有 罪,所以 受 这害吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, '我告诉 你们,不是的! 你们若 不 悔改,都 要如此 灭亡! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, ' 从前 西罗亚 楼 倒塌 了, 压死 十八个人;你们以为 那些 人比 一切 住 在耶路撒冷 的人 更 有罪吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, '我告诉 你们,不是的! 你们若 不 悔改,都 要如此 灭亡!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, '于 是 用 比喻 说:「一个人 有 一棵无花果树 栽 在 葡萄园里。 他来到 树 前找 果子,却 找 不著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, '就 对 管园的 说:『看哪,我这三 年 来到 这 无花果树 前 找 果子,竟 找 不著。 把它 砍了吧,何必 白占 地土呢!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, ' 管园的 说:『主啊,今 年 且 留著,等 我周围 掘开 土, 加上 粪; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, ' 以后 若 结 果子便罢,不然 再把它 砍了。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, ' 安息日,耶稣在 会堂 里 教训人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, ' 有一个女人 被鬼 附著,病了 十八 年, 腰弯 得 一点直不起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, ' 耶稣 看见,便叫过她来, 对她 说:「女人,你脱离 这病了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, '于 是 用两只手 按著 她; 她立刻 直起腰来,就 归荣耀与 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, ' 管会堂的 因为 耶稣 在安息日 治病,就气忿忿地 对众人 说:「有 六 日 应当 做工; 那 六日之内可以来 求医,在安息 日 却 不可。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, ' 主 说:「假冒为善的人哪,难道你们 各人 在安息日 不 解开  槽上 的 牛、 驴, 牵 去饮吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, '况且 这女人 本是 亚伯拉罕 的后裔, 被撒但 捆绑 了 这十 八 年,不 当 在安息 日 解开  她的 绑吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, ' 耶稣 说 这话,他 的敌人 都 惭愧了; 众人 因 他 所行 一切 荣耀的事,就都欢喜了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, ' 耶稣说:「 神 的国 好像 什么? 我拿什么 来比较呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, ' 好像 一粒芥菜 种,有人 拿 去种 在 园子里, 长大 成 树, 天上 的飞鸟 宿 在 它 的枝上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, ' 又 说:「我拿什么 来比 神 的国呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, '好比 面 麺酵, 有妇人 拿来 藏 在 三 斗 面 麺里,直等 全 团 都发起来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, ' 耶稣 往 耶路撒冷去, 在所经过 的 各城 各乡 教训人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, ' 有一个人 问 他 说:「主啊,得救 的人 少吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, ' 耶稣对众人 说:「你们要努力 进 窄 门。我告诉 你们, 将来有许多人 想要 进去,却是 不 能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, '及至 家主 起来 关了 门, 你们 站 在外面 叩 门,说:『主啊,给我们 开 门!』他就 回答 说:『我不认识你们,不 晓得 你们 是 哪里来的!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, '那时,你们要 说:『我们在你 面前 吃 过 喝过,你也 在 我们的 街 上教训过人。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, ' 他要说:『我告诉 你们,我不 晓得 你们 是 哪里来的。你们这一切 作恶的人,离开  我去吧!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, ' 你们要看见 亚伯拉罕、 以撒、 雅各,和 众 先知 都在 神 的国里,你们 却 被赶 到外面,在那里 必要 哀哭 切齿了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, ' 从 东、 从西、 从 南、 从北 将有人来, 在 神 的国 里坐席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, '只是 有 在后的, 将要 在前; 有 在前的, 将要 在后。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, '正当 那 时,有几个 法利赛人 来 对耶稣 说:「离开  这里 去吧,因为 希律 想要 杀 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, ' 耶稣 说:「你们去 告诉 那个 狐狸说:『 今天、 明天 我赶 鬼 治病, 第三天 我的事就成全了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, '虽然这样,今天、 明天、 后天,我 必须 前行,因为 先知 在耶路撒冷 之外 丧命 是不 能的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, '耶路撒冷啊!耶路撒冷啊! 你常杀害 先知,又 用石头打死 那奉差遣 到 你这里来的人。我多次 愿 意 聚集 你的 儿女,好像 母鸡 把 小鸡 聚集在翅膀 底下;只是 你们不 愿 意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, '看哪,你们的 家 成为荒场留 给你们。 我告诉 你们,从今以后你们不得 再见 我,直等到 你们说:『奉 主 名 来 的是应当称颂的。』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, ' 安息日, 耶稣 到 一个 法利赛人 的首领 家 里去吃 饭,他们 就 窥探 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, ' 在他 面前 有 一个 患水臌 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, ' 耶稣 对 律法师 和 法利赛人 说:「安息日 治病 可以 不 可以?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, '他们却 不言语。耶稣就 治好 那人, 叫他走了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, '便 对 他们 说:「你们 中间谁 有 驴或 有牛,在 安息日 掉 在 井里, 不 立时 拉 牠上来呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, ' 他们不 能 对答 这话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, ' 耶稣见 所请 的客 拣择 首位,就 用比喻 对 他们 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, '「 你被 人 请去 赴 婚姻的筵席,不要 坐 在 首位上,恐怕 有 比你 尊贵的 客被 他 请来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, ' 那请 你们 的人 前来 对你 说:『让 座 给这一位吧!』 你就 羞羞惭惭地 退到 末 位上去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, ' 你被请的时候,就去 坐 在 末 位上,好叫 那请 你 的人来 对你 说:『朋友,请上座。』那时,你 在 同席 的人面前 就有 光彩了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, '因为,凡 自 高的,必降为卑; 自 卑的,必升为高。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, ' 耶稣又 对请 他 的人说:「 你摆设 午饭 或 晚饭,不要 请 你的 朋友、 弟兄、 亲属,和 富足的 邻舍,恐怕 他们 也 请 你,你 就 得了 报答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, ' 你摆设 筵席,倒要 请 那贫穷的、残废的、瘸腿的、瞎眼的,你就 有 福了! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, '因为 他们没 有 什么可报答 你。到 义人 复活的时候, 你 要得著报答。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, ' 同席 的有一人 听见 这话,就对耶稣 说:「 在 神 国 里吃 饭 的有福了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, ' 耶稣对他 说:「有一 人 摆设 大 筵席, 请了 许多客。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, ' 到了坐席 的时候,打发 仆人 去对所请 的人说:『请来吧! 样样都 齐备了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, ' 众人 一 口同音地 推辞。头一个 说:『我买  了一块地, 必须 去 看看。请 你 准我 辞了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, '又 有一个 说:『我买  了五 对 牛, 要去 试一试。请 你 准我 辞了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, '又 有一个 说:『我才娶 了妻, 所以 不 能 去。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, ' 那仆人 回来,把这 事都告诉 了 主人。 家主 就动怒,对 仆人 说:『快 出去,到 城 里大街 小巷, 领 那贫穷的、 残废的、 瞎眼的、 瘸腿的 来。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, ' 仆人 说:『主啊, 你所吩咐 的已经办了, 还 有 空座。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, ' 主人 对 仆人 说:『你出去 到 路 上和 篱笆那里, 勉强 人进来, 坐满 我的 屋子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, ' 我告诉 你们, 先前所请 的 人 没有一个 得尝 我的 筵席。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, ' 有极多的 人 和耶稣 同行。 他转过来 对 他们 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, '「人 到 我 这里来, 若不爱我胜过爱(爱我胜过爱:原文是恨)自己的 父 母、 妻子、 儿女、 弟兄、 姊妹, 和 自己的 性命,就不 能 作 我的 门徒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, ' 凡 不 背著 自己 十字架 跟从 我的,也不 能 作 我的 门徒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, ' 你们 哪一个 要 盖 一座楼,不 先 坐下 算计 花费, 能 盖成不能呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, '恐怕 安 了地基, 不 能 成功, 看见 的人都 笑话 他,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, '『 这个 人 开  了工,却 不 能 完工。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, '或是 一个 王 出去 和别的 王 打仗,岂不 先 坐下 酌量, 能 用 一万 兵去敌 那领 二万 兵来 攻打 他的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, '若是不能,就趁敌人 还 远的时候,派 使者 去求 和息的条款。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, ' 这样, 你们无论什么人, 若不 撇下 一切 所有的,就不 能 作 我的 门徒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, '「盐 本是好的; 盐 若 失了味,可用 什么 叫它再咸呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, ' 或用在 田里,或堆在 粪里,都 不 合式,只好丢 在外面。有 耳 可听的,就应当听!」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, ' 众 税吏 和 罪人 都 挨近 耶稣,要听 他讲道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, ' 法利赛人 和 文士 私下议论 说:「 这个 人接待 罪人,又 同他们 吃饭。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, '耶稣就 用 比喻 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, '「你们 中间 谁 有 一百 只羊 失去 一 只,不 把这九十九 只撇 在 旷野、 去 找那失去的羊,直到 找著呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, ' 找著了,就欢欢喜喜地 扛 在 肩上, 回 到 家里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, '就请 朋友 邻舍来,对他们 说:『 我 失去的 羊 已经找著了,你们和我 一同欢喜吧!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, '我告诉 你们, 一个 罪人 悔改,在 天 上也要 这样 为他欢喜,较比 为 九十九 个不 用 悔改 的义人欢喜更大。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, '「或是 一个 妇人 有 十 块钱,若 失落 一 块,岂不 点上 灯, 打扫 屋子, 细细地 找,直到 找著吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, ' 找著了,就请 朋友 邻舍来,对他们说:『 我失落 的那块钱 已经找著了,你们和我 一同欢喜吧!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, '我告诉 你们, 一个 罪人 悔改,在 神 的使者 面前 也是 这样 为他欢喜。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, '耶稣又 说:「一个 人 有 两个 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, ' 小 儿子对父亲 说:『父亲,请你把我应得 的 家业 分 给我。』他父亲就 把产业 分 给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, ' 过了 不 多 几日,小 儿子 就把他一切所有的 都收拾起来,往 远 方 去了。 在那里 任意放荡,浪费 资财。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, ' 既 耗尽 了一切所有的,又遇著 那 地方 大 遭 饥荒, 就 穷苦起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, '于 是 去 投靠 那 地方 的一个 人; 那人打发 他 到 田 里去放 猪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, ' 他 恨不得 拿 猪 所吃 的豆荚 充饥,也 没有人 给他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, ' 他醒悟 过来,就说:『我 父亲 有多少 的雇工,口粮 有余 馀,我 倒 在这里 饿 死吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, '我要起来,到 我 父亲 那里去, 向他 说:父亲!我得罪 了 天,又 得罪了 你; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, '从今以后,我不 配 称 为 你的 儿子,把我 当作 一个 雇工吧!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, '于 是 起来,往 他 父亲 那里去。 相离 还 远,他 父亲 看见,就 动了慈心, 跑去 抱著 他 的颈项, 连连与他 亲嘴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, ' 儿子 说:『父亲!我得罪 了 天,又 得罪了 你;从今以后,我不 配 称 为 你的 儿子。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, '父亲 却 吩咐 仆人说:『把那上好的 袍子 快 拿出来 给他 穿; 把戒指 戴 在 他 指头上; 把鞋 穿在 他脚上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, ' 把那肥 牛犊 牵来 宰了, 我们可以吃 喝快乐; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, '因为 我 这个 儿子 是 死 而 复活, 失 而 又得的。』他们就 快乐起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, '那时, 大 儿子 正 在 田里。 他回来,离家 不远,听见 作乐 跳舞的声音, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, '便 叫 过一个 仆人来,问 是 什么 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, ' 仆人 说:『 你 兄弟 来了; 你 父亲 因为 得 他 无灾无病地回来,把肥 牛犊 宰了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, '大儿子却 生气, 不 肯 进去; 他 父亲 就出来 劝 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, ' 他对 父亲 说:『 我服事 你 这多 年, 从来没有 违背 过你的 命, 你并没有 给 我 一只山羊羔,叫 我 和 朋友 一同快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, '但 你 这个 儿子 和 娼妓 吞尽 了你的 产业,他一来了,你倒为他 宰 了肥 牛犊。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, ' 父亲对他 说:『儿啊!你 常 和 我 同在, 我 一切所有的 都是 你的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, ' 只是你 这个 兄弟 是 死 而 复活、 失 而 又得的,所以 我们理当 欢喜 快乐。』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, ' 耶稣又 对 门徒 说:「有 一个 财主 的管家, 别人向他主人 告 他 浪费 主人 的财物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, ' 主人叫 他来,对他 说:『我听见 你 这事 怎么样呢?把你 所经管 的 交代明白,因 你不 能 再 作我的管家。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, ' 那管家 心里说:『 主人 辞我,不用 我 再作管家,我将来做 什么?锄地呢?无 力;讨饭呢?怕羞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, '我知道 怎么 行,好叫 人在我不作 管家之后,接 我 到 他们 家里去。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, '于 是 把欠 他 主人债的,一个 一个地 叫了来,问头一个 说:『你欠 我 主人 多少?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, ' 他说:『一百 篓(每篓约五十斤)油。』 管家说:『拿 你的 帐, 快 坐下,写 五十。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, '又 问一个 说:『 你 欠 多少?』 他说:『一百 石 麦子。』管家 说:『拿 你的 帐, 写 八十。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, '主人 就 夸奖 这不义的 管家 做事 聪明;因为 今 世 之子,在 世事之上, 较比 光明 之子 更加聪明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, '我 又 告诉 你们,要 藉 借著 那不义的 钱财 结交 朋友, 到了 钱财无用的时候,他们可以接 你们 到 永存的 帐幕里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, '人在 最小的 事上忠心,在 大事 上也 忠心; 在 最小的 事上不义,在 大事 上也 不义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, ' 倘若 你们在 不义的 钱财 上不 忠心,谁 还把那真实的 钱财托 讬付 你们呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, ' 倘若 你们在 别人的 东西上不 忠心,谁 还把你们自己的 东西给 你们呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, '一个仆人 不 能 事奉 两个 主; 不 是恶 这个 爱 那个,就是 重 这个 轻 那个。你们不 能 又事奉 神,又 事奉玛门。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, ' 法利赛人 是 贪爱钱财的;他们听见 这 一切话,就 嗤笑 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, ' 耶稣对他们 说:「你们 是 在人 面前 自 称为义的,你们的 心, 神 却 知道;因为 人 所尊贵的,是 神 看为 可憎恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, '律法 和 先知 到约翰 为止,从 此 神 国 的福音传开 了, 人人 努力 要进去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, ' 天 地 废去 较比 律法 的一点 一画 划 落空 还容易。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, '凡 休 妻 另 娶 的就是犯奸淫;娶 被休 之妻的也是 犯奸淫。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, '「 有 一个 财主 穿著 紫色袍 和 细麻布衣服,天天 奢华 宴乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, '又 有一个 讨饭的,名叫 拉撒路,浑身生疮,被人放 在 财主 门口, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, ' 要得 财主 桌子 上 掉下来 的零碎充饥; 并且 狗 来 舔 他 的疮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, ' 后来 那讨饭的 死了, 被 天使 带去 放在 亚伯拉罕的 怀里。 财主 也 死了,并且 埋葬了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, ' 他在 阴间 受 痛苦,举 目 远远地 望见 亚伯拉罕,又 望见拉撒路 在 他 怀里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, ' 就 喊著 说:『我祖 亚伯拉罕哪,可怜 我吧! 打发 拉撒路来, 用 指头 尖 蘸点 水, 凉凉 我的 舌头;因为 我在 这 火焰里,极其痛苦。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, ' 亚伯拉罕 说:『儿啊,你该回想 你 生 前享过 福,拉撒路 也 受过苦; 如今 他在这里 得安慰,你 倒 受痛苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, '不但 这样,并且在你 我 之间,有深 渊 限定,以致 人要 从这边 过 到 你们 那边是不 能的;要从那边 过 到 我们 这边也是不能的。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, ' 财主说:『我祖啊!既是这样,求 你 打发 拉撒路 到 我 父 家去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, '因为 我还有 五个 弟兄, 他可以对他们 作见证,免得 他们 也 来 到 这 痛苦 的地方。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, ' 亚伯拉罕 说:『他们有 摩西 和 先知 的话可以听从。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, ' 他说:『我祖 亚伯拉罕哪,不是的, 若 有一个 从 死里复活的,到 他们 那里去的,他们必要悔改。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, ' 亚伯拉罕 说:『若 不 听从 摩西 和 先知的话,就是 有一个 从 死 里复活的,他们也是不 听劝。』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, '耶稣又 对 门徒 说:「绊倒人的事 是 免不了的;但 那 绊倒人的 有祸了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, '就是 把磨石 拴 在 这人 的颈项上, 丢 在 海里,还强如 他 把这 小子 里的一个 绊倒了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, '你们 要谨慎!若是 你的 弟兄 得罪你,就劝戒 他; 他若 懊悔,就饶恕 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, ' 倘若 他一天 七次 得罪 你,又 七次 回转,说:『我懊悔了』,你总要饶恕 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, ' 使徒 对主 说:「求主加增 我们 的信心。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, ' 主 说:「你们若 有 信心 像 一粒 芥菜种, 就是对这 棵桑树 说:『你要拔起根来, 栽 在 海里』,它也 必 听从 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, ' 你们 谁 有 仆人 耕地 或是 放羊, 从 田 里回来,就 对他 说:『你快来 坐下吃饭』呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, ' 岂不 对他 说:『你给我预备 晚饭, 束上带子 伺候 我,等 我吃 喝完了,你 才可以 吃 喝』吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, '仆人 照 所吩咐 的去做,主人还 谢谢他吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, '这样, 你们 做完了 一切 所吩咐的,只当说:『 我们是 无用的 仆人, 所做 的本是我们应分 做的。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, ' 耶稣往 耶路撒冷 去, 经过 撒马利亚 和 加利利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, ' 进 入 一个 村子,有十个 长大痲疯的,迎 面而来, 远远地 站著, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, ' 高 声 说:「耶稣,夫子,可怜 我们吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, ' 耶稣看见,就对他们 说:「你们去 把身体 给祭司 察看。」 他们 去 的时候就洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, ' 内中 有一个 见 自己已经好了,就回来 大 声 归荣耀与 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, '又 俯伏 在 耶稣 脚 前感谢 他; 这人 是 撒马利亚人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, ' 耶稣 说:「洁净 了的不是 十个人吗? 那九个 在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, '除了 这 外族人,再没有 别人回来 归 荣耀与 神吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, '就 对那人 说:「起来,走吧!你的 信 救了 你了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, ' 法利赛人 问:「 神 的国 几时 来到?」耶稣回答 说:「 神 的国 来到 不是 眼所能见的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, '人也不 得说:『看哪,在这里! 看哪,在那里!』因为 神 的国 就在 你们 心里(心里:或译中间)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, '他又 对 门徒 说:「日子 将到, 你们巴不得 看见 人 子 的一个 日子,却 不 得看见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, ' 人将要对你们 说:『看哪,在那里! 看哪,在这里!』你们不要 出去,也不要 跟随他们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, '因为 人 子 在 他 降临的日子,好像 闪电 从 天 这边一闪 直照 到 天那边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, '只是 他 必须 先 受 许多苦,又 被 这 世代 弃绝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, ' 挪亚 的日子 怎样, 人 子 的日子 也 要 怎样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, '那时候的人又吃 又喝,又娶 又嫁,到 挪亚 进 方舟 的那日,洪水 就 来, 把他们全都 灭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, '又好像 罗得 的日子;人又吃 又喝,又买  又卖,又耕种 又盖造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, ' 到罗得 出 所多玛 的那 日,就有火 与 硫磺 从 天 上降下来, 把他们全都 灭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, '人 子 显现 的 日子 也要 这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, '当 那 日, 人在 房 上, 器具 在 屋里,不要 下来 拿; 人在 田里,也 不要 回 家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, '你们要回想 罗得 的妻子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, '凡 想要 保全 生命的,必丧掉 生命; 凡 丧掉生命的,必救活 生命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, '我对你们 说,当那 一夜, 两个 人在 一个 床上,要取去 一个, 撇下 一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, '两个 女人 一同 推磨,要取去 一个, 撇下 一个。(有古卷加: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, '两个 人 在 田里,要取去 一个, 撇下 一个。)」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, ' 门徒 说:「主啊,在哪里有这事呢?」 耶稣 说:「尸首 在哪里, 鹰 也必聚 在那里。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, ' 耶稣设 一个比喻,是 要 人 常常 祷告, 不可 灰心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, '说:「 某 城 里有 一个 官,不 惧怕 神,也 不 尊重 世人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, ' 那 城 里 有 个寡妇, 常 到 他那里,说:『 我 有一个对头,求你给我 伸冤。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, ' 他多日 不 准, 后来 心 里说:『我虽 不 惧怕 神,也不 尊重 世人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, '只 因 这 寡妇 烦扰 我,我就给她 伸冤吧,免得 她常来 缠磨 我!』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, ' 主 说:「你们听 这不义 之官 所说 的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, ' 神 的选民 昼 夜 呼吁 他, 他 纵然为 他们 忍了多时,岂不 终久给他们伸冤吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, '我告诉 你们, 要快快地 给他们 伸冤了。然而,人 子 来的时候, 遇得见 世上 有信德吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, ' 耶稣向 那些 仗著 自己 是 义人, 藐视 别人的, 设 一个 比喻, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, '说:「有两个 人 上 殿 里去祷告:一个 是法利赛人, 一个 是税吏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, '法利赛人 站著,自言自语地 祷告说:『 神啊,我感谢 你, 我不 像 别 人 勒索、不义、奸淫, 也 不像 这个 税吏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, '我一个礼拜 禁食 两次,凡 我所得 的都 捐上十分之一。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, ' 那税吏 远远地 站著,连举 目 望 天 也不 敢,只 捶著 胸 说:『 神啊,开 恩可怜 我 这个罪人!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, '我告诉 你们,这人 回 家 去比 那人 倒算为义了;因为,凡 自 高的,必降为卑; 自 卑的,必升为高。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, ' 有人抱著 自己的婴孩 来见耶稣,要 他摸 他们; 门徒 看见 就责备 那些人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, '耶稣 却 叫 他们来,说:「让 小孩子 到 我 这里来, 不要 禁止 他们,因为在 神 国 的正是 这样的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, '我实在 告诉 你们,凡 要承受 神 国的,若不 像 小孩子,断不能 进 去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, ' 有一个 官 问 耶稣 说:「良善的 夫子,我该做 什么事 才可以承受 永 生?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, ' 耶稣 对他 说:「你为什么 称 我 是良善的?除了 神 一位之外,再没有 良善的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, '诫命 你是晓得的:『不可 奸淫;不可 杀人;不可 偷盗;不可 作假见证;当孝敬 父 母。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, ' 那人说:「这 一切 我从 小 都遵守了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, ' 耶稣 听见了,就 说:「你 还 缺少 一件:要变卖 你一切 所有的, 分 给穷人,就 必有 财宝 在 天上;你还要 来 跟从 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, ' 他听见 这话,就 甚忧愁,因为 他 很 富足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, ' 耶稣 看见 他,就说:「有 钱财 的人进 神 的国 是何等 的难哪! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, ' 骆驼 穿 过 针 的眼 比 财主 进 神 的国 还容易呢!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, ' 听见 的人说:「这样,谁 能 得救呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, ' 耶稣说:「在 人 所不能的事,在 神 却 能。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, ' 彼得 说:「看哪,我们 已经撇下 自己所有的 跟从 你了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, ' 耶稣 说:「我实在 告诉 你们, 人 为 神 的国 撇下 房屋,或是 妻子、 弟兄、 父母、 儿女, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, ' 没有 在 今 世 不 得 百倍, 在 来 世 不得永 生的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, ' 耶稣带著 十二个门徒,对 他们 说:「看哪,我们上 耶路撒冷去, 先知 所写 的一切事 都要成就 在人 子身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, ' 他将要被交 给外邦人; 他们要戏弄他, 凌辱他, 吐唾沫在他脸上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, '并 要鞭打他,杀害 他; 第三 日 他要复活。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, ' 这些事 门徒 一样也不 懂得, 意思 乃是 隐藏的; 他们不 晓得 所说的是什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, ' 耶稣 将近 耶利哥的时候,有一个 瞎子 坐 在 路 旁讨饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, ' 听见 许多人 经过,就问 是 什么事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, ' 他们告诉 他, 是拿撒勒人 耶稣 经过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, '他就 呼叫 说:「大卫 的子孙 耶稣啊,可怜 我吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, '在前头走 的人就 责备 他, 不许他作声;他 却 越发 喊叫说:「大卫 的子孙,可怜 我吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, ' 耶稣 站住,吩咐 把他 领过来, 到了跟前,就问 他说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, '「你要 我为你 做 什么?」 他说:「主啊, 我要能看见。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, ' 耶稣 说:「你可以看见!你的 信 救了 你了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, ' 瞎子立刻 看见了,就 跟随 耶稣,一路归荣耀与 神。 众 人 看见这事,也 赞美 神。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, ' 耶稣进了 耶利哥,正经过的时候, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, ' 有一个人 名 叫 撒该, 作 税吏长, 是个财主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, ' 他要 看看 耶稣 是 怎样的人; 只因 人多, 他的身量 又 矮,所以不 得看见, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, '就 跑到前头,爬 上 桑树,要 看 耶稣,因为 耶稣必 从那里 经过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, ' 耶稣 到了 那里,抬头一看,对 他 说:「撒该,快 下来! 今天 我 必 住 在 你 家里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, '他就 急忙 下来, 欢欢喜喜地 接待 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, ' 众人 看见,都私下议论 说:「 他竟到 罪 人 家里去住宿。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, ' 撒该 站著 对 主 说:「 主啊,我 把所有 的一半 给 穷人; 我若 讹诈 了谁,就还 他四倍。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, ' 耶稣 说:「 今天 救恩 到了 这 家,因为 他 也 是 亚伯拉罕 的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, ' 人 子 来,为要寻找、 拯救 失丧的人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, ' 众人 正在听见 这些话的时候,耶稣 因为 将近 耶路撒冷,又 因他们 以为 神 的国 快 要 显出来,就另设 一个比喻,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, '「有一个 贵胄 往 远 方 去,要 得 国 回来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, '便 叫了 他的 十个 仆人来,交 给他们 十锭(锭:原文是弥拿,一弥拿约银十两)银子, 说:『你们去做生意,直等 我回来。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, '他 本国的人 却 恨 他, 打发 使者 随后去,说:『我们不 愿 意 这个 人作 我们的王。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, ' 他 既得 国 回来,就 吩咐 叫 那 领 银子 的仆人来,要 知道 他们做生意赚了 多少。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, ' 头一个 上来,说:『主啊,你的 一锭 银子已经赚了 十 锭。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, ' 主人 说:『好!良善的 仆人, 你既在 最小的 事上有 忠心, 可以有 权柄 管 十 座城。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, ' 第二个 来,说:『主啊,你的 一锭 银子已经赚了 五 锭。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, ' 主人 说:『你 也 可以管 五座 城。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, '又 有一个 来 说:『主啊,看哪,你的 一锭银子在这里,我 把它 包 在 手巾里存著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, ' 我原是怕 你,因为 你是 严厉的 人; 没有 放下的,还要去拿, 没有 种下的,还要去收。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, '主人对他 说:『你这恶 仆,我要凭 你的 口 定 你的罪。你既知道 我 是 严厉的 人, 没有 放下的,还要去拿, 没有 种下的,还要去收, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, '为什么 不 把我的 银子 交给 银行,等我 来的时候,连本 带 利 都可以 要回来呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, '就 对旁边站著 的人说:『夺过 他 这一锭来, 给 那有 十 锭的。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, ' 他们 说:『主啊,他已经有 十 锭了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, '主人说:『我告诉 你们, 凡 有的,还要加给他; 没 有的,连 他所有 的也 要 夺过来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, '至于  我 那些 仇敌, 不 要 我 作 他们王的,把他们拉来, 在我 面前 杀了吧!』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, ' 耶稣说完 了这话,就在前面 走,上 耶路撒冷去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, ' 将近 伯法其 和 伯大尼,在 一座山 名叫 橄榄山那里,就打发 两个 门徒,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, '「你们往 对面 村子 里去, 进去的时候,必看见 一匹驴驹 拴在那里, 是从来 没有 人 骑过的, 可以解开  牵来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, ' 若 有人 问 为什么 解牠,你们就 说:『 主 要用牠。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, ' 打发 的人去了,所遇见 的正如 耶稣所 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, ' 他们 解 驴驹的时候,主人 问 他们 说:「解 驴驹 做什么?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, ' 他们说:「 主 要用牠。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, ' 他们牵 到 耶稣那里, 把自己的 衣服 搭 在上面,扶著耶稣 骑上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, ' 走的时候,众人把 衣服 铺 在 路上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, ' 将近耶路撒冷,正 下 橄榄 山的时候, 众 门徒 因 所见过 的一切 异能,都 欢乐起来,大 声 赞美 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, '说:奉 主 名 来 的王 是应当称颂的!在 天 上有和平; 在 至高之处 有荣光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, ' 众人 中 有几个 法利赛人 对 耶稣 说:「夫子,责备 你的 门徒吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, ' 耶稣 说:「我告诉 你们,若是 他们 闭口不说,这些石头 必要呼叫起来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, ' 耶稣快到耶路撒冷,看见 城,就为 它 哀哭, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, '说:「 巴不得 你 在 这 日子 知道 关系 你 平安的事;无奈 这事现在 是隐藏的,叫 你的 眼看不出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, '因为 日子 将到, 你的 仇敌 必筑起 土垒, 周围环绕 你, 四面 困住 你, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, '并要 扫灭 你 和 你 里头 的儿女, 连一块石头 也不 留 在 石头上,因 你不 知道 眷顾 你 的时候。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, ' 耶稣进了 殿, 赶出 里头做买 卖的人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, '对他们 说:「经上说: 我的 殿 必作 祷告 的殿,你们 倒 使它 成为 贼 窝了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, ' 耶稣天天 在 殿 里 教训人。 祭司长 和 文士 与 百姓 的尊长 都想要 杀 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, '但 寻 不出法子来,因为 百姓 都侧耳 听 他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, ' 有一 天,耶稣 在 殿 里教训 百姓, 讲福音的时候,祭司长 和 文士 并 长老 上前来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, ' 问 他 说:「你告诉 我们,你仗著 什么 权柄 做 这些事? 给 你 这 权柄 的是 谁呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, ' 耶稣回答 说:「我也要 问 你们 一句话,你们且 告诉 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, '约翰 的洗礼 是 从 天上来的? 是从 人间来的呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, ' 他们彼此 商议 说:「 我们若 说『从 天上来』,他必说:『你们为什么 不 信 他呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, ' 若 说『从 人间来』, 百姓 都要用石头打死 我们,因为 他们 信 约翰 是 先知。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, '于 是 回答说:「不 知道 是从哪里来的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, ' 耶稣 说:「我 也不 告诉 你们,我仗著 什么 权柄 做 这些事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, '耶稣就 设 比喻 对 百姓说:「有人 栽了 一个葡萄园, 租 给园户,就 往外国去 住了许久。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, ' 到了时候,打发 一个仆人 到 园户那里去,叫 他们把 园 中当纳的果子 交 给他;园户 竟 打了 他,叫他空手 回去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, '又 打发 一个 仆人去, 他们也 打了他,并且 凌辱他,叫他空手 回去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, '又 打发 第三个仆人去, 他们也 打伤了他, 把他推出去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, ' 园 主 说:『我怎么 办呢?我要打发 我的 爱 子去,或者 他们尊敬 他。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, '不料,园户 看见 他,就彼此 商量 说:『这 是 承受产业的,我们杀 他吧,使 产业 归 于 我们!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, '于 是 把他 推 出 葡萄园外,杀了。这样,葡萄园 的主人 要怎样 处治 他们呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, '他要来 除灭 这些 园户, 将葡萄园 转给 别人。」 听见 的人说:「这是万不可的!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, ' 耶稣看著 他们 说:「经上记著:匠人 所弃 的石头 已 作了 房角 的头块石头。 这 是 什么意思呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, '凡 掉 在 那 石头上的,必要跌碎; 那石头掉 在 谁的身上,就要把谁 砸得稀烂。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, ' 文士 和 祭司长 看出 这 比喻 是指著 他们 说的,当 时 就想要 下手 拿 他,只是 惧怕 百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, '于 是 窥探耶稣,打发 奸细 装作 好人,要 在他的 话 上得把柄,好 将他 交在 巡抚 的政权之下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, '奸细就 问 耶稣 说:「夫子,我们晓得 你所讲 所传 都是正道,也 不 取 人的外貌,乃是 诚诚实实 传 神 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, '我们 纳 税 给凯撒,可以 不可以?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, ' 耶稣看出 他们 的诡诈,就对 他们 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, '「拿一个银钱 来给我 看。这像 和 这号 是 谁的?」 他们说:「是凯撒的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, ' 耶稣 说:「这样,凯撒 的物 当归给 凯撒, 神 的物当归给 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, ' 他们当著 百姓,在 这话 上得不著把柄,又 希奇 他 的应对,就闭口无言了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, ' 撒都该人 常说 没 有 复活的事。 有几个 来 问 耶稣说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, '「夫子!摩西 为我们 写著说:『人 若 有 妻 无子 就死了,他 兄弟 当娶 他的妻, 为 哥哥 生子立 后。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, ' 有 弟兄 七人, 第一个 娶了 妻,没有孩子 死了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, ' 第二个、 第三个 也娶过 她; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, ' 那七个 人都娶过她,没有 留下 孩子 就 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, '后来 妇人 也 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, '这样,当 复活的时候,她 是 哪一个 的妻子呢?因为 他们七个 人都娶过 她。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, ' 耶稣 说:「这 世界 的人 有娶 有嫁; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, '惟有 算为配 得 那 世界,与 从 死 里复活 的人也不 娶 也 不嫁; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, '因为 他们不 能 再 死, 和天使一样;既 是 复活 的人,就为 神 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, '至于  死人 复活, 摩西 在 荆棘篇上, 称 主 是亚伯拉罕的 神, 以撒的 神, 雅各的 神,就指示明白了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, ' 神原不 是 死人的 神,乃是 活人的 神;因为 在他那里(那里:或译看来),人 都是活的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, ' 有几个 文士 说:「夫子!你说得 好。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, '以后 他们不 敢 再问 他 什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, ' 耶稣对 他们 说:「人怎么 说 基督 是 大卫 的子孙呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, ' 诗篇 上 大卫 自己 说:主 对我 主 说:你坐 在 我的 右边, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, '等 我使 你 仇敌 作你 的脚凳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, '大卫 既 称 他 为主,他怎么 又 是 大卫 的子孙呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, ' 众 百姓 听的时候,耶稣 对门徒 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, '「你们要防备 文士。他们 好 穿 长衣 游行, 喜爱 人在 街市 上问他们安,又 喜爱会堂 里 的高位, 筵席 上 的首座; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, '他们 侵吞 寡妇 的家产, 假意 作很长的 祷告。这些人 要受 更重的 刑罚!」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, ' 耶稣抬头 观看,见财主 把 捐项 投 在 库里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, ' 又见 一个 穷 寡妇 投了 两个 小钱, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, '就 说:「我实在 告诉 你们, 这 穷 寡妇 所投 的比众人 还多; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, '因为 众 人 都是 自己 有余 馀,拿出来投 在 捐项里,但 这寡妇 是 自己 不足,把 她 一切 养生的 都投上了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, ' 有人 谈论 圣殿 是用美 石 和 供物 妆饰的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, '耶稣就说:「论到 你们所看见的 这一切,将来日子 到了,在 这里 没有 一块石头 留 在 石头上, 不 被拆毁了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, ' 他们问 他 说:「夫子! 什么时候 有 这事呢? 这事 将 到 的时候 有什么 预兆呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, ' 耶稣说:「你们要谨慎,不要 受迷惑;因为 将来有好些人 冒 我的 名 来,说:『我 是基督』,又说:『时候 近了』,你们不要 跟从 他们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, ' 你们听见 打仗 和 扰乱的事,不要 惊惶;因为 这些事 必须 先 有,只是 末期 不能 立时就到。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, '当时,耶稣对他们 说:「民 要攻打 民, 国 要攻打 国; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, ' 地 要 大大 震动, 多处必有饥荒、 瘟疫,又 有 可怕的异象 和 大 神迹 从 天上显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, '但 这一切 的事 以先,人要下 手 拿住 你们, 逼迫你们,把你们交 给 会堂,并且 收在监里,又为 我的 名 拉 你们到君王 诸侯 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, '但这些事终必为 你们 的 见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, '所以,你们 当立定 心 意,不要 预先思想 怎样分诉; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, '因为 我 必赐 你们 口才、 智慧, 是你们 一切 敌人 所敌不住、 驳不倒的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, ' 连 你们的父母、 弟兄、 亲族、 朋友 也要把你们交官; 你们 也有 被他们害死的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, ' 你们要 为 我的 名 被 众人 恨恶, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, '然而, 你们 连一根头 发 也必不 损坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, '你们 常存 忍耐,就必保全灵魂(或译:必得 生命)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, '「 你们看见 耶路撒冷 被 兵 围困,就 可知道 它 成荒场 的日子近了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, '那时,在 犹太 的应当逃 到 山上; 在 城 里的应当出来; 在 乡下 的不要 进 城; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, '因为 这 是 报应 的日子, 使 经上所写 的都得应验。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, '当 那些 日子,怀孕的 和 奶孩子 的有祸了!因为 将有 大 灾难 降在 这地方,也有 震怒 临到这 百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, ' 他们要倒 在刀 下,又 被掳 到 各 国去。 耶路撒冷 要 被 外邦人 践踏,直到 外邦人 的日期 满了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, '「 日、 月、 星辰 要显出 异兆, 地 上 的邦国 也有困苦;因海 中波浪 的响声,就 慌慌不定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, ' 天势 都要震动, 人 想起 那将要临到 世界的事,就都吓 得魂不附体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, ' 那时,他们要看见 人 子 有 能力, 有大 荣耀 驾 云 降临。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, ' 一 有 这些事,你们 就当挺身 昂 首,因为 你们 得赎 的日子近了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, ' 耶稣又设比喻 对他们 说:「你们看 无花果树 和 各样的 树; 它 发芽的时候,你们 一看见,自然晓得 夏天 近了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, '这样, 你们 看见 这些事 渐渐地成就,也该晓得 神 的国 近了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, '我实在 告诉 你们, 这 世代 还没有 过去, 这些事 都要成就。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, '天 地 要废去,我的 话 却 不能 废去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, '「 你们 要谨慎,恐怕 因 贪食、 醉酒,并 今生 的思虑 累住 你们 的心, 那 日子 就如同 网罗 忽然 临 到 你们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, '因为 那日子要这样临 到 全 地 上 一切 居住的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, ' 你们要时时警醒,常常 祈求,使 你们能 逃避 这 一切 要 来的事, 得以站立 在人 子 面前。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, ' 耶稣每日 在 殿 里教训人, 每夜 出 城在 一座山,名叫 橄榄山 住宿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, ' 众 百姓 清早上 圣殿,到 耶稣那里,要听 他讲道。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, ' 除酵 节(又名 逾越节)近了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, ' 祭司长 和 文士 想法子 怎么 才能杀害 耶稣,是因 他们惧怕 百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, '这时,撒但 入了 那称为 加略人 犹大的心;他本是 十二 门徒里的一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, ' 他去 和祭司长 并 守殿官 商量,怎么 可以把耶稣 交 给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, ' 他们欢喜,就 约定 给 他 银子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, ' 他应允了,就 找 机会,要趁众人 不在跟前 的时候把耶稣 交给 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, ' 除酵节, 须 宰 逾越羊羔 的那一天 到了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, ' 耶稣打发 彼得、 约翰,说:「你们去 为我们 预备 逾越节的筵席,好叫 我们吃。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, ' 他们问他 说:「要 我们在哪里 预备?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, ' 耶稣 说:「 你们 进了 城,必有人 拿著 一瓶 水 迎面而来,你们 就跟著 他,到 他所进 的房子里去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, ' 对那家 的主人 说:『夫子 说:客房 在 哪里?我 与 门徒 好在那里 吃 逾越节的筵席。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, ' 他必指 给你们 摆设整齐 的一间大 楼,你们就在那里 预备。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, ' 他们去了,所遇见 的正如 耶稣所说的;他们 就 预备 了逾越节的筵席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, ' 时候 到了,耶稣坐席,使徒 也 和 他同坐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, ' 耶稣对 他们 说:「我 很愿 意 在受害 以先 和 你们 吃 这 逾越节的筵席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, ' 我告诉 你们, 我不再 吃 这筵席,直到 成就 在 神 的国里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, ' 耶稣接过 杯来,祝谢了,说:「你们拿 这个, 大家 分著喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, ' 我告诉 你们, 从 今以后,我不再 喝 这葡萄汁,直等 神 的国 来到。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, '又 拿起 饼来,祝谢了,就擘开 , 递 给他们,说:「这 是 我的 身体, 为 你们 舍的,你们也应当如此 行,为的是 记念 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, '饭 后 也 照样 拿起杯来,说:「这 杯 是用 我 血 所立的新 约, 是为 你们 流出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, ' 看哪,那卖 我 之人的手 与 我 一同在 桌子上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, ' 人 子 固然 要照 所预定 的去世,但 卖人子 的 人 有祸了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, '他们 就 彼此 对问,是 哪一个 要 做 这事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, ' 门徒 起了 争论,他们 中间哪一个 可算为 大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, ' 耶稣 说:「外邦人 有君王 为主治理 他们, 那掌权管 他们 的称为 恩主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, '但 你们 不可 这样;你们 里头 为大的,倒 要 像 年幼的, 为首领的,倒要像 服事人的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, ' 是谁 为大?是坐席的呢?是 服事人的呢?不是 坐席的大吗?然而,我 在 你们 中间 如同 服事人的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, ' 我 在 磨炼之中,常和 我 同在 的就是 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, '我 将国 赐 给你们,正如 我 父 赐 给我一样, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, '叫 你们在 我 国里,坐在 我的 席 上吃 喝,并且 坐 在 宝座上,审判 以色列 十二 个支派。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, '主又说:「西门!西门! 撒但 想要 得著你们,好筛 你们像 筛麦子一样; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, '但 我 已经为 你 祈求,叫你 不至于  失了 信心。 你 回头以后,要坚固 你的 弟兄。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, ' 彼得 说:「主啊,我就是 同 你 下 监, 同你受 死,也是 甘心!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, ' 耶稣说:「彼得,我告诉 你,今日 鸡 还没有 叫,你要 三次 说不 认得 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, '耶稣又 对他们 说:「我差 你们 出去的时候,没有 钱囊, 没有口袋, 没有鞋,你们缺少 什么 没有?」 他们说:「没有。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, ' 耶稣 说:「但 如今 有 钱囊 的可以带著,有口袋 的也 可以带著, 没 有 刀 的要卖 衣服 买 刀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, ' 我告诉 你们, 经上写著说:『 他被列 在 罪犯之中。』这话 必 应验 在 我身上;因为 那关系 我 的事 必然成就。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, ' 他们说:「主啊,请看!这里 有两把 刀。」 耶稣 说:「 够了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, ' 耶稣出来,照 常 往 橄榄 山 去, 门徒 也 跟随 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, ' 到了 那地方,就对他们 说:「你们要祷告,免得 入了 迷惑。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, '于 是 离开  他们 约有 扔 一块石头那么远, 跪下 祷告, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, '说:「父啊!你若 愿 意,就把这 杯 撤去;然而,不要 成就我的 意思,只要 成就 你的意思。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, ' 有一位天使 从 天 上 显现,加添 他的力量。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, ' 耶稣极其 伤痛,祷告 更加恳切, 汗珠 如 大血 点 滴 在 地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, ' 祷告完了,就起来, 到 门徒那里,见 他们 因为 忧愁 都睡著了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, '就 对他们 说:「你们为什么 睡觉呢?起来 祷告,免得 入了 迷惑!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, ' 说话之间, 来了许多人。 那十二 个门徒里 名叫 犹大的,走 在前头, 就近 耶稣,要与他 亲嘴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, ' 耶稣 对他 说:「犹大!你用亲嘴 的暗号卖 人 子吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, ' 左右 的人见 光景不好,就说:「主啊!我们拿 刀 砍 可以不可以?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, ' 内中 有一个人 把大祭司 的仆人 砍了一刀, 削掉 了他 的右 耳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, ' 耶稣 说:「到了 这个地步,由他们吧!」就 摸 那人的耳朵,把他 治好了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, ' 耶稣 对 那些来 拿 他 的祭司长 和 守殿 官 并 长老 说:「你们带著 刀 棒 出来拿我,如同 拿 强盗吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, '我 天天 同 你们 在 殿里,你们不 下 手 拿 我。现在 却 是 你们 的时候, 黑暗 掌权了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, ' 他们拿住耶稣,把他 带 到 大祭司 的宅里。 彼得 远远地 跟著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, ' 他们在 院子 里 生了 火, 一同坐著;彼得 也坐 在他们 中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, ' 有一个 使女 看见 彼得 坐 在 火光里,就 定睛看 他,说:「这个人 素来也 是 同 那人一伙 夥的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, '彼得却 不承认,说:「女子,我不 认得 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, ' 过了不多的时候,又有一个 人看见 他,说:「你 也 是 他们一党的。」 彼得 说:「你这个人!我不 是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, ' 约 过了 一 小时,又有一个人 极力地 说:「他实在 是 同 那 人一伙 夥的,因为 他也 是 加利利人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, ' 彼得 说:「你这个人!我不 晓得 你说 的是什么!」 正 说话之间,鸡 就 叫了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, ' 主 转过身来 看 彼得,彼得 便 想起 主 对他 所说 的话:「 今日 鸡 叫 以先,你要三次 不认 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, '他就 出去 痛 哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, ' 看守 耶稣 的人 戏弄 他,打他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, '又 蒙著 他的眼,问 他说:「你是先知,告诉我们打 你 的是 谁?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, '他们还 用许多 别的 话辱骂 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, ' 天 一亮,民间 的众长老 连 祭司长 带 文士 都聚会, 把耶稣 带 到 他们的 公会里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, '说:「你 若 是 基督,就告诉 我们。」 耶稣 说:「我若 告诉 你们,你们也不 信; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, ' 我若 问你们,你们也不 回答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, ' 从 今以后,人 子 要 坐 在 神 权能 的右边。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, ' 他们 都说:「这样,你 是 神 的儿子吗?」 耶稣 说:「你们 所说的 是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, ' 他们说:「何必 再 用见证呢? 他 亲口所说的,我们都亲自 听见了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, ' 众人 都起来,把耶稣 解 到 彼拉多面前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, '就 告 他 说:「我们见 这人 诱惑 国民, 禁止 纳 税 给凯撒,并 说 自己 是 基督,是王。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, ' 彼拉多 问 耶稣 说:「你 是 犹太人 的王吗?」 耶稣回答 说:「你 说的是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, ' 彼拉多 对 祭司长 和 众人 说:「我查 不 出 这 人 有什么罪来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, '但 他们越发极力地 说:「他煽惑 百姓,在 犹太 遍地 传道, 从 加利利 起,直到 这里了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, ' 彼拉多 一听见,就问:「这人 是 加利利人吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, '既 晓得 耶稣 属 希律 所管,就把他 送 到 希律那里去。 那 时 希律 正 在 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, ' 希律 看见 耶稣,就很 欢喜;因为 听见 过 他的事, 久 已想要 见 他,并且 指望 看 他 行 一件 神迹, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, '于 是 问 他 许多 的话,耶稣 却 一言不 答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, ' 祭司长 和 文士 都站著,极力地 告 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, ' 希律 和 他 的兵丁 就 藐视 耶稣, 戏弄他,给他穿上 华丽 衣服,把他 送回 彼拉多那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, ' 从前 希律 和 彼拉多 彼此 有仇, 在 那一 天 就成了 朋友。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, ' 彼拉多 传齐了 祭司长 和 官府 并 百姓, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, '就对 他们 说:「你们解 这 人 到我这里, 说他是诱惑 百姓的。 看哪,我 也曾将 你们告 他 的事,在你们 面前 审问他,并没有 查出 他 什么罪来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, '就是 希律 也是如此,所以 把 他 送回来。 可见 他 没 有 做 什么该 死的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, '故此,我要责打 他,把他释放了。」(有古卷加: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, ' 每逢 这节期,巡抚必须 释放 一个 囚犯给他们。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, '众人却 一齐 喊著 说:「除掉 这个人! 释放 巴拉巴 给我们!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, '这 巴拉巴是 因 在 城 里作 乱 杀人,下 在 监里的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, ' 彼拉多 愿 意 释放 耶稣,就又 劝解 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, '无奈 他们喊著 说:「钉他十字架!钉 他十字架!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, ' 彼拉多第三次 对 他们 说:「为什么呢? 这人 做了 什么 恶事呢?我并没有 查出 他 什么该死 的罪来。所以,我要责打 他,把他释放了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, ' 他们大 声 催逼彼拉多,求 他把耶稣 钉在十字架上。他们 的声音 就 得了胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, ' 彼拉多 这才照 他们 所求的 定案, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, ' 把他们所求 的那 作乱 杀人、下 在 监里 的释放了, 把耶稣 交给他们,任凭他们 的意思行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, ' 带 耶稣去的时候,有一个 古利奈人 西门,从 乡下 来;他们就抓住他,把十字架 搁 在他身上,叫他背著 跟随 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, ' 有许多 百姓 跟随 耶稣, 内中有好些妇女;妇女们 为他 号咷 痛哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, ' 耶稣 转身 对 她们 说:「耶路撒冷 的女子,不要 为 我 哭,当 为 自己 和 自己的 儿女 哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, '因为 日子 要到, 人必说:『不生育的,和 未 曾怀胎的, 未 曾乳养 婴孩的,有福了!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, '那时,人要 向大山 说:倒 在 我们身上! 向小山说:遮盖 我们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, '「 这些事 既行 在 有汁水的 树上, 那枯干的 树将来 怎么样呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, ' 又 有两个 犯人,和 耶稣 一同带来 处死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, ' 到了 一个地方, 名叫「髑髅地」,就在那里 把耶稣 钉在十字架上,又 钉了两个犯人: 一个 在 左边, 一个 在 右边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, ' 当下耶稣 说:「父啊!赦免 他们;因为 他们所做 的,他们不 晓得。」兵丁就 拈 阄 分 他 的衣服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, ' 百姓 站 在那里观看。 官府 也 嗤笑他,说:「他救了 别人;他 若 是 基督, 神 所拣选的,可以救 自己吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, ' 兵丁 也戏弄 他,上前 拿 醋 送给他喝, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, ' 说:「你 若 是 犹太人 的王,可以救 自己吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, ' 在 耶稣 以上 有 一个牌子(有古卷加:用希腊、罗马、希伯来的文字)写著:「这 是犹太人 的王。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, ' 那同钉 的两个犯人 有一个 讥笑 他,说:「你 不是 基督吗?可以救 自己 和 我们吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, ' 那一个 就应声 责备 他,说:「 你 既是 一样 受刑的,还不 怕 神吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, ' 我们 是 应该的,因 我们 所受 的与我们所做 的相称,但 这个人 没有 做过 一件不好的事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, '就 说:「耶稣啊, 你 得国 降临的时候,求你记念 我!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, ' 耶稣对他 说:「我实在 告诉 你,今日 你要 同 我 在 乐园里了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, ' 那时约 有 午正, 遍 地 都 黑暗了,直到 申初, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, '日头 变黑了; 殿 里的幔子 从当中 裂为两半。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, ' 耶稣 大 声 喊著 说:「父啊!我将我的 灵魂 交 在 你 手里。」 说了 这话,气就断了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, ' 百夫长 看见 所成的事,就归荣耀与 神,说:「这 真 是 个义人!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, ' 聚集 观看 的众 人 见了 这所成 的事都捶著 胸 回去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, '还有 一切 与耶稣 熟识的人,和 从 加利利 跟著 他 来的妇女们,都远远地 站著 看 这些事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, ' 有 一个人 名 叫约瑟,是个议士, 为人 善良 公义; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, '众人 所谋 所为, 他并没 有 附从。他本是犹太、 亚利马太 城 里 素常盼望 神 国的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, '这人 去见 彼拉多,求 耶稣 的身体, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, '就 取下来,用细麻布 裹好, 安放 在 石头凿成 的坟墓里;那里头 从来 没有 葬过 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, ' 那日 是 预备日,安息日 也 快到了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, ' 那些 从 加利利 和耶稣 同来 的妇女 跟在后面,看见了 坟墓 和 他 的身体 怎样 安放。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, '她们就 回去,预备了 香料 香膏。她们在安息日,便 遵著 诫命 安息了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, ' 七日 的头一日,黎明的时候,那些妇女带著 所预备 的香料 来 到 坟墓前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, ' 看见 石头 已经从 坟墓 滚开 了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, '她们就 进去,只是不 见 主 耶稣 的身体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, ' 正在 猜疑之间, 忽然有两个 人 站在旁边, 衣服 放光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, ' 妇女 们 惊怕, 将脸 伏 地。那两个人就对 她们 说:「为什么 在 死人 中找 活人呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, '他不 在 这里, 已经复活了。当记念 他还 在 加利利 的时候怎样 告诉 你们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, '说:『 人 子 必须 被交 在 罪 人 手里, 钉在十字架上, 第三 日 复活。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, '她们就 想起 耶稣 的话来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, '便 从 坟墓 那里回去,把这 一切的 事告诉 十一个 使徒和 其余 馀的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, ' 那告诉 使徒 的就是 抹大拉 的马利亚 和 约亚拿,并 雅各 的母亲马利亚,还有 与 她们 在一处的妇女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, ' 她们这些 话, 使徒 以为 是 胡言,就 不相信。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, ' 彼得 起来,跑 到 坟墓前, 低头 往里看,见细麻布 独在一处,就 回去了, 心 里希奇 所成的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, ' 正当 那 日,门徒 中 有两个 人 往 一个村子 去;这村子名叫 以马忤斯,离 耶路撒冷 约有 二十五里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, ' 他们 彼此 谈论 所遇见 的这一切事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, ' 正 谈论 相问 的时候, 耶稣 亲自 就近他们,和他们 同行; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, '只是 他们 的眼睛 迷糊了,不 认识 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, ' 耶稣对 他们 说:「你们走路 彼此 谈论 的 是什么事呢?」他们就站住, 脸上带著愁容。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, ' 二人中有一个 名叫 革流巴 的回答 说:「你 在耶路撒冷 作客,还 不 知道 这几 天 在 那里 所出的事吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, ' 耶稣 说:「什么事呢?」 他们 说:「就是 拿撒勒人 耶稣的事。 他 是 个先知,在 神 和 众 百姓面前, 说话 行事 都有大能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, ' 祭司长 和 我们的 官府 竟把他 解去, 定了 死罪, 钉在十字架上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, '但 我们 素来所盼望、 要 赎 以色列 民的就是 他!不但 如此,而且 这事 成就, 现在已经 三 天了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, '再者,我们 中间 有几个 妇女 使我们 惊奇;她们清早 到了 坟墓那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, ' 不 见 他 的身体,就回来 告诉我们, 说看见了 天使 显现, 说 他 活了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, '又有 我们 的几个人 往 坟墓 那里去, 所 遇见 的 正如 妇女 们所说的,只是 没有 看见 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, ' 耶稣 对 他们 说:「 无知的人哪, 先知 所说 的一切话,你们的心 信 得太迟钝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, '基督 这样 受害,又 进 入 他 的荣耀,岂不是 应当的吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, '于 是 从 摩西 和 众 先知 起,凡 经 上 所指著 自己 的话都给他们 讲解明白了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, ' 将近 他们所去 的村子, 耶稣 好像 还要往前 行, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, '他们却 强留 他,说:「 时候 晚了, 日头 已经 平西了,请你同 我们 住下吧!」 耶稣就进去,要同 他们 住下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, ' 到了 坐席的时候,耶稣拿起 饼来,祝谢了, 擘开 ,递 给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, ' 他们的 眼睛 明亮了,这才 认出 他来。 忽然耶稣 不见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, ' 他们 彼此 说:「在 路上, 他和我们 说话, 给我们 讲解 圣经的时候,我们的 心 岂不 是 火热 的吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, '他们就 立时 起身,回 耶路撒冷去, 正遇见 十一个 使徒和 他们 的同人聚集在一处, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, '说:「 主 果然 复活, 已经现给西门 看了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, ' 两个人就 把 路上所遇见,和 擘 饼 的时候怎么 被他们 认出来的事,都述说了一遍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, ' 正说 这话的时候,耶稣亲自 站 在 他们 当中, 说:「愿 你们 平安!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, '他们却 惊慌 害怕,以为 所看见 的是魂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, ' 耶稣 说:「你们 为什么 愁烦? 为什么 心 里起 疑念呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, '你们看 我的 手, 我的 脚, 就知道实在是 我了。摸 我 看看! 魂 无 骨 无肉, 你们看,我 是有的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, ' 说了 这话,就把手 和 脚 给他们 看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, ' 他们 正 喜 得不敢信,并且 希奇;耶稣 就说:「你们这里 有 什么 吃的没有?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, '他们便 给 他 一片 烧 鱼。(有古卷加:和一块蜜房。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, ' 他接过来,在他们 面前 吃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, ' 耶稣对 他们 说:「这 就是 我 从前 与 你们 同在 之时所告诉 你们 的话说: 摩西 的律法、 先知的书,和 诗篇 上所记的,凡 指著 我 的话都必须 应验。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, '于 是 耶稣开  他们 的心窍,使他们能明白 圣经, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, '又 对他们 说:「 照经上 所写的,基督 必受害, 第三 日 从 死 里复活, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, '并且 人要奉 他 的名 传 悔改、 赦 罪的道,从 耶路撒冷 起 直传到 万 邦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, '你们 就是这些事 的见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, ' 我 要将我 父 所应许 的降 在 你们身上, 你们 要在 城 里等候,直到 你们领受 从 上头 来的能力。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, ' 耶稣领 他们 到 伯大尼的对面,就 举 手 给他们 祝福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, ' 正 祝福的时候,他 就离开  他们, 被带 到 天上去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, '他们 就 拜 他, 大大地 欢喜,回 耶路撒冷去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, ' 常 在 殿 里称颂 神。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, '太初 有 道,道 与 神 同在,道 就是 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, '这道 太初与 神 同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, '万物 是藉 借著 他 造的;凡被造的,没有一样 不是 藉 借著 他 造的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, '生命 在 他里头,这 生命 就是 人 的光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, '光 照在 黑暗里, 黑暗 却不 接受 光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, '有 一个人,是从 神 那里差来的,名叫 约翰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, '这人 来,为要 作见证,就是为 光 作见证,叫 众人 因 他 可以信。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, '他不 是 那 光,乃是 要为 光 作见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, '那光是 真 光,照亮 一切生在 世上的 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, '他在 世界,世界 也是藉 借著 他 造的,世界 却不 认识 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, '他到 自己的 地方来,自己的人 倒不 接待 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, '凡接待 他 的,就是信 他 名的人,他就赐 他们 权柄 作 神 的儿女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, '这等人 不是 从 血气 生的,不是 从 情欲生的,也不是 从 人意生的,乃是 从 神生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, '道 成了 肉身,住在 我们 中间,充充满满地 有恩典 有真理。我们 也见过 他的 荣光,正是 父 独生子 的荣光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, '约翰 为 他 作见证,喊著 说:「这 就是 我曾说:『那在我 以后 来的,反成了 在我 以前的,因 他本来 在我 以前。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, '从 他 丰满的恩典里,我们 都 领受了,而且 恩上 加 恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, '律法 本是藉 借著 摩西 传的;恩典 和 真理 都是由 耶稣 基督 来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, '从来 没有人 看见 神, 只有 在 父 怀里 的独生子将他 表明出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, '约翰 所作的见证记在下面:犹太人 从 耶路撒冷 差 祭司 和 利未人 到 约翰那里, 问 他说:「你 是 谁?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, '他 就明说,并 不 隐瞒,明说:「我 不 是 基督。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, '他们 又问 他说:「这样,你 是谁呢?是 以利亚吗?」他 说:「我 不是。」「是 那先知吗?」他 回答说:「不是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, '于 是 他们 说:「你到底是 谁,叫 我们好回复 差 我们来的人。你自己说,你 是谁?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, '他说:「我 就是那在 旷野 有人声 喊著说:『修直 主 的道路』,正如 先知 以赛亚 所说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, '那些人 是 法利赛人 差来的(或译:那差来的是法利赛人); ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, '他们 就问 他 说:「你 既不是 基督,不是 以利亚,也不是 那先知,为什么 施洗呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, '约翰 回答 说:「我 是用 水 施洗,但有一位站在 你们 中间,是 你们 不 认识的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, '就是那在我 以后 来的,我 给他 解 鞋带 也 不 配。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, '这是 在 约旦河 外 伯大尼(有古卷:伯大巴喇),约翰 施洗 的地方 作的见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, '次日,约翰看见 耶稣 来到 他那里, 就说:「看哪, 神 的羔羊,除去(或译:背负)世人 罪孽的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, '这就是 我 曾说:『有一位 在我 以后 来、反成了 在我 以前的,因 他本来 在我 以前。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, '我 先前不 认识 他,如今 我 来 用 水 施洗,为要 叫 他显明 给以色列人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, '约翰 又作见证 说:「我曾看见 圣灵,仿佛 鸽子 从 天 降下,住在 他 的身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, '我 先前不 认识 他,只是 那差 我 来用 水 施洗的、对 我 说:『你看见 圣灵 降下来,住在 谁 的身上,谁 就是 用 圣 灵 施洗的。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, '我 看见了,就 证明 这 是 神 的儿子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, '再 次日,约翰 同 两个 门徒 站在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, '他 见 耶稣 行走,就说:「看哪,这是 神 的羔羊!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, '两个 门徒 听见 他的话,就 跟从了 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, '耶稣 转过身来, 看见 他们 跟著,就问他们 说:「你们要 什么?」他们说:「拉比,在哪里 住?」(拉比 翻出来 就是夫子。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, '耶稣说:「你们 来 看。」他们就 去 看 他在哪里 住,这一天 便与 他 同住;那 时 约 有 申正了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, '听见 约翰 的话跟从 耶稣 的那 两个人,一个 是 西门•彼得 的兄弟 安得烈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, '他 先 找著 自己的 哥哥 西门,对 他 说:「我们遇见 弥赛亚了。」(弥赛亚翻出来 就是 基督。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, '于 是领 他 去见 耶稣。耶稣 看见 他,说:「你 是 约翰 的儿子 西门(约翰在马太十六章十七节称约拿),你 要称为 矶法。」(矶法 翻出来 就是彼得。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, '又次日,耶稣 想要 往 加利利 去,遇见 腓力,就 对他 说:「来跟从 我吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, '这腓力 是 伯赛大人,和 安得烈、彼得 同 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, '腓力 找著 拿但业,对 他 说:「摩西 在 律法 上所写的和 众先知 所记的 那一位,我们遇见了,就是约瑟 的儿子 拿撒勒 人 耶稣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, '拿但业 对他 说:「拿撒勒 还能 出 什么 好的吗?」腓力 说:「你来 看!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, '耶稣 看见 拿但业 来,就 指著 他 说:「看哪,这是个真 以色列人, 他 心里是没 有 诡诈的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, '拿但业 对耶稣 说:「你从哪里 知道 我呢?」耶稣 回答 说:「腓力 还没有 招呼 你,你在 无花果树 底下,我就看见 你了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, '拿但业 说:「拉比,你 是 神 的儿子,你 是 以色列 的王!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, '耶稣 对他 说:「因为 我说『 在无花果树 底下 看见 你』,你就信吗?你将要看见 比这 更大的事」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, '又 说:「我实实在在地 告诉 你们,你们将要看见 天 开 了, 神 的使者 上去 下来 在 人 子 身上。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, ' 第三 日,在 加利利 的迦拿 有 娶亲的筵席, 耶稣 的母亲 在 那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, ' 耶稣 和 他的 门徒 也被请 去 赴席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, ' 酒 用尽了,耶稣 的母亲 对 他 说:「他们没 有 酒了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, ' 耶稣 说:「母亲(原文是妇人),我 与 你 有什么相干?我的 时候 还没有 到。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, '他 母亲 对用人 说:「他告诉 你们 什么,你们就做什么。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, ' 照 犹太人 洁净的规矩,有 六口 石 缸 摆在 那里,每口 可以盛 两 三 桶水。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, '耶稣 对用人 说:「把缸 倒满了 水。」他们就 倒满了,直到 缸口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, '耶稣又 说:「现在 可以舀出来, 送给 管筵席的。」他们就 送了去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, ' 管筵席的 尝了 那水 变的 酒, 并不 知道 是哪里 来的,只有 舀 水 的用人 知道。管筵席的 便叫 新郎来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, ' 对他 说:「人 都是 先 摆上 好 酒, 等 客喝足了,才摆上次的,你 倒把好 酒 留 到 如今!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, '这是 耶稣 所行 的头一件 神迹,是在 加利利 的迦拿行的, 显出 他的 荣耀来;他的 门徒 就 信 他了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, '这事 以后,耶稣 与 他的 母亲、 弟兄,和 门徒 都下 迦百农去, 在那里 住了 不 多 几日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, ' 犹太人 的逾越节 近了, 耶稣 就上 耶路撒冷 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, ' 看见 殿 里 有卖 牛、 羊、 鸽子的,并有 兑换银钱的 人坐在那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, '耶稣就 拿 绳子 做成 鞭子,把 牛 羊 都 赶出 殿去, 倒出 兑换银钱之人 的银钱, 推翻 他们的桌子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, '又 对卖 鸽子 的说:「把这些东西 拿去!不要 将我 父 的殿 当作 买 卖 的地方。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, '他的 门徒 就想起 经上 记著说:「我 为你的 殿 心里焦急,如同火烧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, '因此 犹太人 问 他 说:「你既 做 这些事,还显 什么 神迹 给我们看呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, '耶稣 回答 说:「你们拆毁 这 殿, 我三 日 内 要再建立 起来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, '犹太人 便 说:「这 殿 是四十 六 年 才造成的, 你 三 日 内 就再建立 起来吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, '但 耶稣 这话 是 以他的 身体 为殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, '所以 到 他从 死里 复活以后,门徒 就想起 他说过 这话,便 信了 圣经 和 耶稣 所 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, ' 当 耶稣在 耶路撒冷 过 逾越节 的时候,有许多人 看见 他所 行的 神迹,就信了 他的 名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, ' 耶稣 却不 将自己 交托 讬 他们;因为 他 知道 万人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, '也 用 不著 谁 见证 人怎样,因 他 知道 人 心里 所存的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, ' 有 一个 法利赛 人,名叫 尼哥底母,是犹太人 的官。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, '这人 夜里 来见 耶稣, 说:「拉比,我们知道 你是由 神 那里来作 师傅的;因为 你 所 行的 神迹,若没有 神 同在,无人 能 行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, '耶稣 回答 说:「我实实在在地 告诉 你,人 若不 重 生,就不能 见 神 的国。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, '尼哥底母 说:「人 已经 老了,如何 能 重生呢?岂能 再进 母 腹 生出来吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, '耶稣 说:「我实实在在地 告诉 你,人 若不是 从 水 和 圣灵 生的,就不能 进 神 的国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, '从 肉身 生的 就是 肉身; 从 灵 生的 就是 灵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, '我说:『你们 必须 重 生』,你 不要 以为 希奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, '风 随著 意思 吹, 你听见 风的 响声,却 不 晓得 从哪里 来, 往哪里 去;凡 从 圣灵 生的,也 是如此。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, '尼哥底母 问 他 说:「怎能 有 这事呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, '耶稣 回答 说:「你是 以色列人 的先生, 还不 明白 这事吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, '我实实在在地 告诉 你,我们所说的 是 我们知道的; 我们所见证的 是 我们见过的; 你们却不 领受 我们的 见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, ' 我对你们 说 地上的事, 你们尚且不 信,若 说 天上的事,如何 能信呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, ' 除了 从 天 降下、 仍旧在天的人 子,没有人 升过 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, ' 摩西 在 旷野 怎样举 蛇,人 子 也 必 照样 被举起来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, ' 叫一切 信 他 的都得 永 生(或译:叫一切信的人在他里面得永生)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, '「 神 爱 世人,甚至 将他的独生 子 赐给他们,叫 一切 信 他的,不 致灭亡,反 得 永 生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, '因为 神 差 他的儿子 降 世,不是 要定 世人的罪(或译:审判世人;下同),乃是 要 叫世人 因 他 得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, '信 他的人,不 被定罪; 不 信的人,罪已经 定了,因为 他不 信 神 独生 子 的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, ' 光 来到 世间, 世人 因 自己的 行为 是 恶的,不爱光,倒 爱 黑暗,定他们的罪 就是在此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, ' 凡 作 恶的 便恨 光,并 不来 就 光,恐怕 他的 行为 受责备。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, '但 行 真理 的必来 就 光,要 显明 他 所行的 是 靠 神 而行。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, '这事 以后,耶稣 和 门徒 到了 犹太 地, 在那里 居住, 施洗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, ' 约翰 在 靠近 撒冷 的哀嫩 也 施洗;因为 那里 水 多, 众人都去 受洗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, '(那时约翰 还没有 下在 监里。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, ' 约翰 的 门徒 和一个犹太人 辩论 洁净的礼, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, '就 来 见 约翰, 说:「拉比, 从前同 你 在 约旦河 外、你 所见证 的那位, 现在施洗, 众人 都往 他 那里去了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, '约翰 说:「若 不是 从 天上 赐的,人 就不能 得 什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, '我曾说:『我 不是 基督, 是 奉差遣 在他 前面的』,你们 自己 可以给我 作见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, '娶 新妇 的就是 新郎; 新郎 的朋友 站著, 听见 新郎的 声音 就甚 喜乐。故此,我 这 喜乐 满足了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, '他 必 兴旺, 我 必衰微。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, '「从天上 来的 是 在万有 之上;从 地上 来 的是 属乎地, 他所说的 也是属乎 地。从 天上 来的 是在 万有 之上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, ' 他将所见 所闻 的 见证出来, 只是没有人 领受 他的 见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, '那领受 他 见证的,就印上印,证明 神 是 真的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, ' 神 所差来的 就说 神 的话,因为 神赐 圣灵 给他是没有 限量的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, '父 爱 子, 已将万有 交在 他 手里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, '信 子 的人有 永 生; 不信 子 的人得不著 永生(原文是不得见永生), 神 的震怒 常在 他身上。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, ' 主 知道 法利赛人 听见 他 收 门徒, 施洗,比 约翰 还多, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(其实 不是 耶稣 亲自 施洗,乃是 他的 门徒施洗,) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, '他就离了 犹太, 又 往 加利利 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, ' 必须 经过 撒马利亚, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, '于 是 到了 撒马利亚 的一座城,名叫 叙加,靠近 雅各 给 他 儿子 约瑟 的那块地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, ' 在 那里 有雅各 井;耶稣 因 走路 困乏,就 坐在 井旁。那时 约有 午正。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, '有一个撒马利亚 的 妇人 来 打 水。耶稣 对她 说:「请你给 我 水喝。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, '( 那时门徒 进 城 买  食物 去了。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, ' 撒马利亚 的妇人 对他 说:「你 既是 犹太人,怎么 向 我 一个 撒马利亚 妇人 要 水喝呢?」原来 犹太人 和撒马利亚人 没有 来往。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, '耶稣 回答 说:「你若 知道 神 的恩赐,和 对你 说『给 我 水喝』的是 谁,你 必 早求 他, 他也必 早给了 你 活 水。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, '妇人 说:「先生,没有 打水的器具, 井 又 深,你 从哪里 得 活 水呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, ' 我们的 祖宗 雅各 将 这井 留给 我们, 他自己 和 儿子 并 牲畜 也都 喝这井里的水,难道 你 比他还大吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, '耶稣 回答 说:「凡 喝 这 水 的还要再 渴; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, ' 人 若喝 我 所赐的 水 就永远不 渴。 我所赐的 水 要在 他 里头 成为泉源,直涌到 永 生。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, '妇人 说:「先生,请把这 水 赐给 我,叫 我不 渴,也不用 来 这么远打水。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, '耶稣 说:「你去 叫 你 丈夫 也 到 这里来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, '妇人 说:「我没有 丈夫。」耶稣 说:「你说 没有 丈夫 是不错的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, ' 你已经有 五 个丈夫, 你现在 有的 并不是 你的 丈夫。你这话 是真的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, '妇人 说:「先生,我看出 你 是 先知。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, '我们的 祖宗 在 这 山上 礼拜, 你们 倒说, 应当 礼拜 的地方 是 在 耶路撒冷。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, '耶稣 说:「妇人,你当信 我。时候 将到, 你们拜 父,也不 在 这 山上,也不 在 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, '你们 所拜的, 你们不 知道;我们所拜的,我们 知道,因为 救恩 是 从 犹太人出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, ' 时候 将到, 如今 就是了, 那真正 拜父的,要用 心灵 和 诚实 拜 他,因为 父 要 这样的 人拜 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, '神 是个灵(或无个字), 所以拜 他 的必须 用 心灵 和 诚实 拜他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, '妇人 说:「我知道 弥赛亚(就是 那称为 基督的)要来; 他 来了,必将一切的事 都告诉 我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, '耶稣 说:「这 和你 说话的 就是他!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, ' 当下 门徒 回来, 就希奇 耶稣和 一个妇人 说话;只是 没有人 说:「你是要 什么?」或说:「你为什么 和 她 说话?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, '那妇人 就 留下 水罐子, 往 城 里去, 对众人 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, '「你们来 看!有一个人 将我素来 所行的 一切事 都给我 说出来了,莫非 这 就是 基督吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, '众人就出 城, 往 耶稣 那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, '这其间,门徒 对耶稣 说:「拉比,请吃。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, ' 耶稣说:「我 有 食物 吃,是 你们 不 知道的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, ' 门徒 就彼此 对问说:「莫非 有人 拿 什么给他 吃吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, '耶稣 说:「我的 食物 就是 遵行 差 我 来者的旨意, 做成 他的 工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, '你们 岂不 说『到 收割 的时候还有 四个月』吗? 我告诉 你们,举 目 向田 观看, 庄稼 已经熟了(原文是发白),可以收割了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, '收割的 人得 工价, 积蓄 五谷 到 永 生,叫 撒种的 和 收割的 一同 快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, ' 俗语说:『 那人 撒种, 这人 收割』,这话可见是真的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, '我 差 你们 去收 你们 所没有 劳苦的;别人 劳苦, 你们 享受 他们 所劳苦的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, ' 那 城 里有好些 撒马利亚人 信了 耶稣,因为 那妇人 作见证 说:「 他将我素来所行的 一切事 都给我 说出来了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, '于 是 撒马利亚人 来见 耶稣,求 他 在他们 那里住下, 他便在那里 住了 两 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, ' 因 耶稣的 话,信的 人就更多了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, ' 便对妇人 说:「现在 我们信,不是因为 你的 话,是 我们 亲自听见了, 知道 这 真是 救世主。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, ' 过了 那两 天,耶稣离了 那地方,往 加利利去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, '因为 耶稣 自己 作过见证说:「 先知 在 本 地 是 没有 人尊敬的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, ' 到了 加利利,加利利人 既然看见 他在 耶路撒冷 过节 所行的 一切事,就接待 他,因为 他们 也是 上去 过节。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, ' 耶稣又 到了 加利利 的迦拿,就是他从前变 水 为酒 的地方。 有 一个 大臣,他的 儿子 在 迦百农 患病。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, '他 听见 耶稣 从 犹太 到了 加利利,就来见 他, 求 他 下去 医治 他的 儿子,因为 他儿子快要 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, ' 耶稣 就对 他 说:「若不 看见 神迹 奇事,你们总是不 信。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, '那大臣 说:「先生,求你趁著我的 孩子 还没有死 就下去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, '耶稣 对他 说:「回去吧,你的 儿子 活了!」那人 信 耶稣 所 说的 话 就 回去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, ' 正 下去的时候,他的 仆人 迎见 他,说 他的 儿子 活了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, ' 他就问 什么时候 见好的。 他们说:「昨日 未时 热 就退了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, ' 他 便知道 这 正是 耶稣 对他 说「你 儿子 活了」的时候; 他自己 和 全 家 就都信了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, '这是 耶稣 在加利利 行的 第二 件神迹,是他从 犹太 回去以后行的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, '这事 以后,到了 犹太人 的一个节期, 耶稣 就上 耶路撒冷 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, ' 在 耶路撒冷,靠近 羊门 有一个池子, 希伯来话 叫作 毕士大,旁边有 五个 廊子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, ' 里面 躺著 瞎眼的、瘸腿的、血气枯干的 许多 病人。(有古卷加:等候水动; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, '因为 有天使 按 时 下 池子 搅动 那水, 水 动 之后,谁先 下去,无论 害 什么病 就 痊愈了。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, ' 在 那里 有一个 人, 病了 三十 八 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, '耶稣 看见 他 躺著, 知道 他病了 许久,就问 他说:「你要 痊愈吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, '病人 回答说:「先生,水 动 的时候,没有 人 把 我 放在 池子 里; 我 正 去的时候,就有别人 比我 先 下去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, '耶稣 对他 说:「起来,拿 你的 褥子 走吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, ' 那人 立刻 痊愈, 就拿起 褥子 来走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, ' 那天 是 安息日,所以 犹太人 对那医好的 人说:「今天是 安息日,你 拿 褥子 是不可的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, '他却 回答说:「那使我 痊愈的, 对我 说:『拿 你的 褥子 走吧。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, '他们问 他说:「对 你 说『拿 褥子 走』的是 什么 人?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, ' 那医好的 人不 知道 是 谁;因为 那里 的人 多,耶稣 已经躲开 了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, '后来 耶稣 在 殿 里遇见 他, 对他 说:「 你已经痊愈了,不要再 犯罪,恐怕 你 遭遇 的更加利害。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, '那人 就去 告诉 犹太人, 使 他 痊愈 的是 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, '所以 犹太人 逼迫 耶稣, 因为 他在 安息日 做了 这事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, ' 耶稣 就对他们 说:「我 父 做事 直到如今,我也 做事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, '所以 犹太人 越发 想要 杀 他;因 他不但 犯了 安息日,并且 称 神 为他的 父,将自己和 神 当作 平等。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, ' 耶稣 对他们 说:「我实实在在地 告诉 你们,子 凭著 自己 不能 做什么,惟有 看见 父 所做的, 子 才能做;父所做的事,子 也 照样 做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, ' 父 爱 子, 将自己 所做的 一切事 指给 他看, 还要将比这 更大的 事 指给 他看,叫 你们 希奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, ' 父 怎样 叫死人 起来, 使他们活著,子 也照样 随自己的意思 使人 活著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, ' 父 不审判 什么人,乃 将审判的事 全 交与 子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, '叫 人 都尊敬 子 如同 尊敬 父一样。不 尊敬 子的,就是不 尊敬 差 子 来的父。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, '我实实在在地 告诉 你们, 那听 我 话、又 信 差 我来者的,就有 永 生; 不 至于 定罪, 是已经出 死 入 生了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, '我实实在在地 告诉 你们, 时候 将到, 现在 就是了, 死人 要听见 神 儿子 的声音, 听见的 人就要活了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, '因为 父 怎样 在 自己 有 生命,就赐给 他儿子 也照样 在 自己 有 生命, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, '并且 因为 他是 人 子,就赐给 他 行 审判 的权柄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, '你们不要 把这事 看作希奇。 时候 要到,凡 在 坟墓 里的,都要听见 他的 声音,就出来: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, ' 行 善的, 复活 得生; 作 恶的, 复活 定罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, '「我 凭著 自己 不能做 什么,我怎么 听见 就怎么审判。我的 审判 也 是 公平的;因为 我不 求 自己的 意思,只 求那差 我 来者的意思。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, '「我 若 为 自己 作见证,我的 见证 就 不 真。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, '另 有 一位给 我 作见证, 我也知道 他给 我 作的 见证 是 真的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, '你们 曾差 人到 约翰那里, 他为真理 作过见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, '其实,我 所受的 见证 不是 从 人来的;然而,我说 这些话,为要 叫你们 得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, '约翰 是 点著的 明 灯, 你们 情愿  暂时 喜欢 他的 光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, '但 我 有 比约翰 更大的 见证;因为 父 交给 我 要 我成就 的事, 就是 我 所做的 事,这便见证 我 是 父 所差来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, ' 差 我 来的父 也为 我 作过见证。你们从来 没有 听见 他的 声音,也没有 看见 他的 形像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, ' 你们并没有 他的 道 存在 心 里;因为 他所差来的,你们 不 信。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, '你们查考 圣经(或译:应当查考圣经),因 你们 以为 内中 有 永 生; 给 我 作见证的 就是 这经。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, '然而,你们不 肯 到 我 这里来 得 生命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, '「我不 受 从 人 来的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, '但 我知道, 你们 心里 没 有 神 的爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, '我 奉 我 父 的名 来, 你们并不 接待 我;若 有别人 奉 自己的 名 来,你们倒要接待 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, '你们 互相 受 荣耀, 却不 求 从 独一之 神 来的荣耀,怎 能 信我呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, '不 要想 我 在 父 面前要告 你们;有 一位告 你们的,就是你们 所仰赖的 摩西。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, ' 你们如果信 摩西,也必信 我,因为 他 书上有指著 我 写的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, ' 你们若 不 信 他的 书,怎能 信 我的 话呢?」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, '这事 以后,耶稣 渡 过 加利利 海,就是提比哩亚海。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, ' 有许多 人 因为 看见 他在 病人 身上所 行 的神迹,就跟随 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, ' 耶稣 上了 山,和 门徒 一同 坐在 那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, ' 那时犹太人 的逾越 节 近了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, '耶稣 举 目 看见 许多人 来,就对 腓力 说:「我们从哪里 买  饼 叫 这些人 吃呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, '( 他说 这话 是要试验 腓力; 他自己 原知道 要 怎样 行。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, '腓力 回答说:「就是二十两 银子 的饼,叫 他们 各人 吃 一 点 也是不 够的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, '有 一个 门徒,就是西门•彼得 的兄弟 安得烈,对耶稣 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, '「在这里 有 一个孩童, 带著 五个 大麦 饼、 两条 鱼,只是 分给 这许多人 还算 什么呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, '耶稣 说:「你们叫 众人 坐下。」原来 那 地方 的草 多, 众人 就坐下,数目 约有 五千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, ' 耶稣 拿起 饼来, 祝谢了,就分给 那坐著的人; 分 鱼 也是这样,都随著 他们所要的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, ' 他们吃饱了,耶稣对门徒 说:「把剩下的 零碎 收拾起来,免得 有 糟蹋的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, ' 他们便将那五个 大麦 饼 的 零碎,就是 众人吃了 剩下的,收拾起来, 装满了 十二个 篮子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, ' 众人 看见 耶稣所 行的 神迹,就说:「这 真 是 那要到 世间 来 的先知!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, '耶稣 既 知道 众人要 来 强 逼他 作 王,就独 自 又 退 到 山上去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, ' 到了 晚上,他的 门徒 下 海边 去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, ' 上了 船,要过 海 往 迦百农去。 天已经 黑了, 耶稣 还没 有来 到 他们那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, ' 忽然狂 风 大作,海 就翻腾起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, ' 门徒摇橹,约 行了十里多路,看见 耶稣 在 海 面上走, 渐渐近了 船, 他们就害怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, ' 耶稣对他们 说:「是 我,不 要怕!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, ' 门徒就喜欢 接 他 上 船, 船 立时 到了 他们所要 去 的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, '第二日,站在 海 那边 的众人 知道 那里 没有 别的 船,只有 一只小船, 又知道耶稣 没 有同他的 门徒 上 船,乃是 门徒 自己 去的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, '然而,有几只 小船 从 提比哩亚 来,靠近主 祝谢 后分饼 给人吃 的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, ' 众人 见 耶稣 和门徒 都不 在 那里, 就上了 船, 往 迦百农 去找 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, ' 既在海 那边 找著了,就对他 说:「拉比,是几时 到这里 来的?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, '耶稣 回答 说:「我实实在在地 告诉 你们,你们找 我,并不 是因 见了 神迹,乃是 因 吃 饼 得饱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, '不 要为那 必坏的 食物 劳力, 要为那 存 到 永 生 的食物劳力,就是 人 子 要赐给 你们的,因为 人子 是父 神 所印证的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, ' 众人问 他 说:「我们当行 什么 才 算做 神 的工呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, '耶稣 回答 说:「 信 神所 差来的,这 就是做 神 的工。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, '他们又 说:「你 行 什么 神迹,叫 我们看见 就 信 你;你到底做什么 事呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, '我们的 祖宗 在 旷野 吃过 吗哪,如 经上写著 说:『他从 天上 赐下粮 来给 他们 吃。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, ' 耶稣 说:「我实实在在地 告诉 你们,那从 天上 来的粮 不是 摩西 赐给 你们的,乃是 我 父 将天上 来的真 粮 赐给 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, '因为 神 的粮 就是 那 从 天上 降下来、 赐 生命 给世界的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, ' 他们说:「主啊,常 将这 粮 赐给 我们!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, '耶稣 说:「我 就是 生命 的粮。到 我 这里来的,必定不 饿; 信 我的,永远不 渴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, '只是 我对你们 说过, 你们已经 看见 我,还是 不 信。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, '凡 父 所赐给 我 的人 必到 我 这里来; 到 我 这里来的,我总不 丢弃他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, '因为 我从 天上 降下来,不是 要 按自己的 意思 行,乃是 要按那差 我 来者的意思行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, ' 差 我 来者的意思 就是: 他所 赐给 我 的,叫我一个也不 失落,在 末 日 却 叫他 复活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, ' 因为我 父 的意思 是 叫 一切 见 子 而 信 的 人得 永 生,并且 在 末 日 我 要叫他 复活。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, ' 犹太人 因为 耶稣说「我 是 从 天上 降下来 的粮」,就私下议论 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, ' 说:「这 不 是 约瑟 的儿子 耶稣吗?他的 父 母 我们 岂不认得吗?他如今 怎么 说『我是从 天上 降下来的』呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, '耶稣 回答 说:「你们 不要 大家议论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, '若不是 差 我 来的父 吸引 人,就没有 能 到 我 这里来的;到我这里来的,在 末 日 我 要叫他 复活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, '在 先知 书上写著说:『 他们 都要蒙 神 的教训。』凡 听见 父 之 教训又学习的,就到 我 这里来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, '这 不是 说有人 看见过 父,惟独 从 神来的,他 看见过 父。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, '我实实在在地 告诉 你们,信的 人有 永 生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, '我 就是 生命 的粮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, '你们的 祖宗 在 旷野 吃过 吗哪,还是 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, '这 是 从 天上 降下来 的粮,叫 人 吃了 就 不 死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, '我 是 从 天上 降下来 生命 的粮;人 若 吃 这 粮,就必永远 活著。 我 所 要赐 的粮 就是 我的 肉,为 世人 之生命所赐的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, '因此,犹太人 彼此 争论 说:「这个人 怎 能 把他的 肉 给 我们 吃呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, ' 耶稣 说:「我实实在在地 告诉 你们,你们若不 吃 人 子 的肉, 不喝 人子的 血,就没 有 生命 在 你们里面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, '吃 我 肉、 喝 我 血 的人就有 永 生,在末 日 我 要叫他 复活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, ' 我的 肉 真 是 可吃的, 我的 血 真 是 可喝的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, '吃 我 肉、 喝 我 血 的人常在 我 里面,我 也常在他 里面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, '永活的 父 怎样 差 我来,我 又因 父 活著;照样,吃 我 肉的人 也要因 我 活著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, '这 就是 从 天上 降下来 的 粮。吃 这 粮 的人就永远 活著,不 像 你们的祖宗 吃过 吗哪还是 死了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, '这些话 是耶稣 在 迦百农 会堂 里 教训人说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, '他的 门徒 中 有好些 人听见了,就说:「这 话 甚难,谁 能 听呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, ' 耶稣 心里 知道 门徒 为 这话 议论,就对他们 说:「这话是 叫你们厌弃(原文是跌倒)吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, '倘或 你们看见 人 子 升到 他原来 所在 之处,怎么样呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, '叫人活著的 乃是 灵,肉体 是无益的。我 对你们 所说 的 话 就是 灵, 就是 生命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, '只是 你们 中间 有 不 信 的 人。」 耶稣 从 起头 就知道 谁 不 信他, 谁 要 卖 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, ' 耶稣又说:「所以 我对你们 说过,若不 是 蒙 我父 的恩赐, 没有人 能 到 我 这里来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, '从此,他 门徒 中 多 有退去的,不再 和 他 同 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, ' 耶稣 就对那十二 个门徒说:「 你们 也 要 去吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, '西门•彼得 回答说:「主啊,你有 永 生 之道,我们还归从 谁呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, ' 我们 已经信了,又 知道 你 是 神的 圣者。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, '耶稣 说:「我 不 是拣选了 你们 十二个门徒吗?但 你们 中间 有一个 是 魔鬼。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, ' 耶稣这话是指著加略人西门 的儿子犹大 说的; 他 本是十二个 门徒里 的一个,后来要 卖 耶稣的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, ' 这事 以后,耶稣 在 加利利 游行, 不 愿  在 犹太 游行,因为 犹太人 想要 杀 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, '当时 犹太人 的住棚 节 近了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, '耶稣 的弟兄 就 对 他 说:「你离开  这里 上 犹太去吧,叫 你的 门徒 也 看见 你 所 行 的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, ' 人 要 显扬 名声, 没有 在 暗处 行 事的;你如果 行 这些事,就当将自己 显明 给世人看。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, '因为 连他的 弟兄说这话,是因为不 信 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, ' 耶稣 就对他们 说:「我的 时候 还没 有到; 你们的 时候 常 是 方便的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, '世人 不能 恨 你们,却是 恨 我,因为 我 指证 他们 所 做的 事 是 恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, '你们 上去 过节吧,我 现在不 上去 过这 节,因为 我的 时候 还没有 满。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, ' 耶稣说了 这 话,仍旧住在 加利利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, '但 他 弟兄 上去以后, 他 也 上去 过节,不 是明去,似乎 是 暗去的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, ' 正在 节期,犹太人 寻找 耶稣, 说:「他 在 哪里?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, ' 众人 为 他 纷纷 议论,有的 说:「 他是 好人。」有的 说:「不然, 他是迷惑 众人的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, '只是 没有人 明明地 讲论 他,因为 怕 犹太人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, '到了 节期,耶稣 上 殿 里 去 教训人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, ' 犹太人 就希奇,说:「这个人 没 有学过,怎么 明白 书呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, ' 耶稣 说:「我的 教训 不 是 我自己的,乃是 那差 我来者的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, '人 若 立志 遵著 他的 旨意行,就必晓得 这教训 或是 出于  神,或是 我 凭著 自己 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, '人凭著 自己 说,是求 自己的 荣耀;惟有 求 那差 他 来者的荣耀,这 人是 真的, 在他 心里 没 有 不义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, '摩西 岂不 是传 律法 给你们吗? 你们 却没有 一个人守 律法。为什么 想要 杀 我呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, '众人 回答说:「你是被鬼 附著了!谁 想要 杀 你?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, '耶稣 说:「我做了 一件 事, 你们都 以为希奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, '摩西 传割礼 给 你们(其实 不 是 从摩西 起的,乃是 从祖先 起的), 因此 你们也在 安息日 给人 行割礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, '人 若 在 安息日 受 割礼,免得 违背 摩西 的律法, 我在 安息日 叫 一个人 全然 好了,你们就向我 生气吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, '不 可按 外貌 断定是非,总要 按公平 断定是非。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, ' 耶路撒冷人 中 有的 说:「这 不 是 他们想要 杀 的人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, ' 你看 他还明明地 讲道, 他们也不向他 说 什么,难道官长 真 知道 这 是 基督吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, '然而,我们知道 这个人 从哪里 来;只是 基督 来 的时候,没有人 知道 他从哪里 来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, '那时,耶稣 在 殿 里教训人,大声 说:「你们也 知道我,也 知道 我 从哪里来; 我来 并不 是由于  自己。但 那差 我 来的是 真的。你们 不 认识 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, '我 却认识 他;因为 我是 从 他来的,他 也是差了 我来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, ' 他们就想要 捉拿 耶稣;只是 没有人 下 手,因为 他的 时候 还没有 到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, ' 但众人 中间 有好些 信 他的, 说:「基督 来 的时候,他所 行 的神迹 岂能 比这 人所行 的更多吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, '法利赛人 听见 众人 为 耶稣 这样 纷纷议论, 祭司长 和 法利赛人 就打发 差役 去 捉拿 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, '于 是 耶稣 说:「我 还有 不多 的时候 和你们 同在, 以后就回 到 差 我来的那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, '你们要找 我,却 找 不 著; 我 所在 的地方 你们 不能 到。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, ' 犹太人 就彼此 对问说:「这人 要 往哪里 去,叫 我们 找 不著呢?难道他要 往 散住 希腊 中的犹太人那里去 教训 希腊人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, ' 他说:『你们要找 我,却 找 不 著; 我 所在 的地方,你们 不能 到』,这 话 是 什么意思呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, ' 节期 的末 日,就是最大之日,耶稣 站著 高声 说:「人 若 渴了, 可以到 我 这里来 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, '信 我 的人就如 经上 所说:『从他 腹中 要流 出 活 水 的江河来。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, ' 耶稣 这 话是指著信 他 之人 要 受 圣灵说的。 那时还没有 赐下圣灵来,因为 耶稣 尚未 得著荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, ' 众人 听见 这 话,有的说:「这 真 是 那先知。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, '有的 说:「这 是 基督。」但 也有的说:「基督 岂是 从 加利利 出来的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, '经上 岂不是 说『基督 是大卫 的 后裔, 从 大卫 本乡 伯利恒 出来的』吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, '于 是 众人 因著 耶稣 起了纷争。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, ' 其中 有人 要 捉拿 他,只是 无人 下 手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, ' 差役 回到 祭司长 和 法利赛人那里。 他们 对差役说:「你们为什么 没有 带 他来呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, '差役 回答说:「从来没有 像他 这样说话的!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, ' 法利赛人 说:「你们 也 受了迷惑吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, '官长 或是 法利赛人 岂有 信 他的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, '但 这 些 不 明白 律法 的百姓 是 被咒诅的!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, '内中 有 尼哥底母,就是从前 去 见耶稣的,对 他们 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, '「不 先 听 本人的口供, 不知道 他所做 的事,难道我们的 律法 还定 他的罪吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, '他们回答 说:「你 也 是 出于  加利利吗?你且去查考,就 可 知道 加利利 没有 出过 先知。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, '');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, '于 是各人都回家去了;耶稣 却往 橄榄 山 去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, ' 清早 又 回到 殿 里。 众 百姓 都到 他 那里去, 他就坐下,教训 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, ' 文士 和 法利赛人 带著 一个行淫 时 被拿 的妇人来, 叫 她 站在 当中, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, '就对耶稣 说:「夫子,这 妇人 是正 行淫 之时 被拿的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, ' 摩西 在 律法 上吩咐 我们 把这样的 妇人用石头打死。 你 说 该把她怎么样呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, ' 他们说 这话,乃试探 耶稣,要 得著 告 他的把柄。 耶稣 却弯著腰,用指头 在 地上 画 划字。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, ' 他们还是不住地 问 他, 耶稣就直起腰来,对他们 说:「你们中间 谁是没有罪的,谁就可以先 拿 石头 打 她。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, '于 是 又 弯著腰,用指头在 地上 画 划字。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, ' 他们听见这话,就从 老到少,一个 一个地 都出去了, 只 剩下耶稣一人,还有 那妇人 仍然站在 当中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, ' 耶稣 就直起腰来,对她 说:「妇人,那些人在 哪里呢?没有人 定 你的罪吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, ' 她说:「主啊,没有。」 耶稣 说:「我 也不 定 你的罪。去吧, 从 此 不要 再犯罪了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, ' 耶稣 又 对众人 说:「我 是 世界 的光。跟从 我的,就不 在 黑暗 里走, 必要得著 生命 的光。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, '法利赛人 对他 说:「你 是为 自己 作见证,你的 见证 不 真。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, '耶稣 说:「我 虽然 为 自己 作见证,我的 见证 还是 真的;因 我知道 我从哪里 来, 往哪里 去;你们 却 不 知道 我从哪里 来, 往哪里 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, '你们 是以外貌(原文是凭肉身)判断人,我 却不 判断 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, ' 就是 判断人,我的 判断 也是 真的;因为 不 是我 独自在这里,还有 差 我 来的父 与 我同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, ' 你们的 律法 上也 记著说:『 两个 人 的见证 是 真的。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, '我 是 为 自己 作见证, 还有差 我 来的父 也是为 我 作见证。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, ' 他们就问 他说:「你的 父 在 哪里?」耶稣 回答说:「你们不 认识 我,也不 认识我的 父;若 是认识 我, 也 就认识 我的 父。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, '这些 话 是耶稣在 殿 里 的库房、教训 人时所说的, 也没有人 拿 他,因为 他的 时候 还没有 到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, ' 耶稣又 对他们 说:「我 要去了, 你们要找 我, 并且你们 要死 在罪 中。我 所去 的地方,你们 不能 到。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, ' 犹太人 说:「 他说『我 所去 的地方,你们 不能 到』,难道他要自 尽吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, ' 耶稣对他们 说:「你们 是 从 下头来的,我 是 从 上头来的;你们 是 属 这 世界的,我 不 是 属 这 世界的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, '所以 我对你们 说, 你们要死在 罪 中。 你们若 不 信 我 是基督,必要死在 罪 中。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, ' 他们就问 他说:「你 是 谁?」耶稣 对他们 说:「就是 我从起初 所告诉 你们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, '我有 许多事 讲论你们, 判断 你们;但 那差 我 来的是 真的,我 在 他 那里 所听见的,我就传给 世人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, '他们 不 明白 耶稣是 指著父 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, '所以 耶稣 说:「 你们举起 人 子 以后,必知道 我是基督,并且 知道我没有一件事 是凭著 自己 做的。 我说 这些话 乃是照著 父 所教训 我的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, ' 那差 我 来的是 与我 同在;他没 有撇下 我 独自在这里,因为 我 常 做 他 所喜悦的事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, '耶稣 说 这话的时候,就有许多 人信 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, ' 耶稣 对 信 他 的犹太人 说:「你们 若 常常 遵守 我的 道, 就真是 我的 门徒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, ' 你们必晓得 真理, 真理 必叫你们 得以自由。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, '他们回答说:「我们是 亚伯拉罕 的后裔, 从来没有 作过谁 的奴仆。你 怎么 说『你们 必得以 自由』呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, '耶稣 回答说:「我实实在在地 告诉 你们, 所有 犯 罪 的就是 罪 的奴仆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, ' 奴仆 不能 永远 住在 家 里;儿子 是永远 住在家里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, '所以 天父的儿子 若 叫你们 自由,你们就 真 自由了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, '我知道 你们是 亚伯拉罕 的子孙, 你们却想要 杀 我,因为 你们 心里 容 不 下我的 道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, '我 所说的 是 在我父 那里 看见的; 你们 所行的 是 在你们的父 那里 听见 的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, '他们说:「我们的 父 就是 亚伯拉罕。」耶稣 说:「你们若 是 亚伯拉罕 的儿子,就必行 亚伯拉罕 所行的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, ' 我 将在 神 那里所 听见的 真理 告诉了 你们,现在 你们却想要 杀 我,这 不 是亚伯拉罕 所行的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, '你们 是行 你们 父 所行的事。」 他们说:「我们 不 是从 淫乱 生的;我们只有 一 位父,就是 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, '耶稣 说:「倘若 神 是 你们的 父,你们就必 爱 我;因为 我 本是出于  神,也是 从 神而来,并不是 由著 自己 来,乃是 他 差 我来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, '你们为什么 不 明白 我的 话呢?无非是因 你们不能 听 我的 道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, '你们 是 出于  你们的父 魔鬼, 你们 父 的私欲 你们偏要 行。他 从 起初 是 杀人的, 不 守 真理,因 他心 里 没 有 真理。 他说 谎 是出于  自己;因 他本来是 说谎的,也是 说谎之人 的父。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, ' 我 将真理 告诉你们,你们就因此 不 信 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, '你们 中间 谁 能指证 我 有 罪呢?我既然 将真理 告诉 你们,为什么 不 信 我呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, ' 出于  神的,必听 神 的话; 你们 不 听,因为 你们不 是 出于  神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, '犹太人 回答 说:「我们 说 你 是 撒马利亚人,并且 是鬼 附著的, 这话岂不 正对吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, '耶稣 说:「我 不 是 鬼附著的; 我尊敬 我的 父, 你们 倒轻慢 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, ' 我 不 求 自己的 荣耀,有 一位为我求荣耀、 定是非的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, '我实实在在地 告诉 你们,人 若 遵守 我的 道,就永远 不 见 死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, ' 犹太人 对他 说:「现在 我们知道 你是鬼 附著的。亚伯拉罕 死了, 众先知也死了, 你 还说:『人 若 遵守 我的 道,就永远 不 尝 死味。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, '难道你 比 我们的 祖宗 亚伯拉罕 还大吗?他 死了, 众先知 也死了,你将自己 当作 什么人呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, '耶稣 回答说:「我 若 荣耀 自己,我的 荣耀 就算不得什么;荣耀 我 的乃是 我的 父, 就是你们 所说 是 你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, ' 你们未 曾认识 他; 我 却认识 他。 我若说 不 认识 他,我就是 说谎的,像 你们一样;但 我认识 他,也 遵守 他的 道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, '你们的 祖宗 亚伯拉罕 欢欢喜喜地 仰望 我的 日子, 既看见了 就 快乐。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, ' 犹太人 说:「你 还没有 五十 岁, 岂见过 亚伯拉罕呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, '耶稣 说:「我实实在在地 告诉 你们,还没有 亚伯拉罕 就有了 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, '于 是 他们拿 石头 要 打 他; 耶稣 却躲藏, 从殿 里出去了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, ' 耶稣过去的时候,看见 一个人 生 来 是瞎眼的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, ' 门徒 问 耶稣 说:「拉比, 这人生来 是瞎眼的,是谁 犯了罪?是这人呢? 是他 父母呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, '耶稣 回答说:「也不 是这人 犯了罪,也不是 他 父母犯了罪, 是要 在 他 身上显出 神 的作为来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, '趁著 白日,我们 必须 做 那差 我 来者的工;黑夜 将到, 就没有人 能 做工了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, '我在 世上 的时候,是 世上 的光。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, ' 耶稣说了这话,就吐唾沫 在地上, 用 唾沫 和 泥 抹在 瞎子的眼睛上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, ' 对他 说:「你往西罗亚 池子 里 去 洗。」(西罗亚翻出来 就是「奉差遣」。) 他去 一洗, 回头 就看见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, ' 他的邻舍 和 那素常 见 他 是 讨饭的,就说:「这 不 是 那从前坐著 讨饭的人吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, '有人 说:「 是他」;又有人 说:「不是,却 是 像 他。」他 自己说:「 是 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, ' 他们 对他说:「 你的 眼睛 是怎么 开 的呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, '他 回答说:「有一个人,名叫 耶稣,他和 泥 抹 我的 眼睛, 对我 说:『你往 西罗亚 池子去 洗。』 我去 一洗,就看见了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, ' 他们 说:「那个人 在 哪里?」他说:「我不 知道。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, '他们把从前 瞎眼的 人 带到 法利赛人那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, ' 耶稣 和 泥 开  他 眼睛 的日子 是 安息日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, ' 法利赛人 也 问 他 是怎么 得看见的。 瞎子对他们 说:「他把泥 抹 在 我的 眼睛上, 我去一洗,就 看见了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, ' 法利赛人 中 有的 说:「这个 人 不 是 从 神来的,因为 他不 守 安息日。」又 有人 说:「一个罪人 怎 能 行 这样的 神迹呢?」 他们 就 起了纷争。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, ' 他们又 对瞎子 说:「他既然 开 了 你的 眼睛,你 说 他 是 怎样的人呢?」他说:「 是 个先知。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, ' 犹太人 不 信 他 从前是 瞎眼, 后来能看见的,等到 叫了 他的 父母来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, ' 问 他们 说:「这 是 你们的 儿子吗?你们 说 他 生来 是瞎眼的, 如今 怎么 能看见了呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, ' 他 父母 回答 说:「他 是 我们的 儿子, 生来 就瞎眼, 这是我们知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, '至于  他如今 怎么 能看见,我们却不 知道; 是谁 开 了 他的 眼睛,我们 也不 知道。他已经 成了人,你们问 他吧,他 自己 必能说。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, '他 父母 说 这话, 是怕 犹太人;因为 犹太人 已经 商议定了, 若 有 认 耶稣 是基督的,要把 他赶出会堂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, '因此 他 父母 说:「 他已经 成了人,你们问 他吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, ' 所以法利赛人第二次 叫了 那 从前 瞎眼的 人来, 对他 说:「你该将荣耀 归给 神,我们 知道 这 人 是 个罪人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, ' 他 说:「他是 个罪人 不是,我不 知道;有一件事 我知道, 从前我是 眼瞎的,如今 能看见了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, ' 他们就问 他说:「他 向你 做什么?是怎么 开 了 你的 眼睛呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, '他回答说:「我方才 告诉 你们, 你们不 听,为什么 又 要 听呢?莫非你们 也 要 作 他的 门徒吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, ' 他们就骂 他 说:「你 是 他的 门徒; 我们 是 摩西 的门徒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, ' 神 对摩西 说话 是我们 知道的;只是这个人,我们不 知道 他从 哪里来!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, '那人 回答 说:「 他开 了 我的 眼睛, 你们 竟不 知道 他从 哪里来, 这 真是 奇怪! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, '我们知道 神 不 听 罪人,惟有敬奉 神、 遵行 他 旨意的, 神才听 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, '从 创世以来,未 曾听见 有人 把生来 是瞎子 的眼睛 开 了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, '这人 若 不 是 从 神来的,什么 也不能 做。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, '他们回答 说:「你 全然 生 在 罪孽中, 还要教训 我们吗?」 于 是把他 赶 出去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, '耶稣 听说 他们把他 赶 出去, 后来遇见 他,就说:「你 信 神的儿子吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, '他 回答 说:「主啊, 谁是 神的儿子,叫 我信 他呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, '耶稣 说:「你已经 看见 他, 现在和 你 说话 的就是 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, ' 他说:「主啊,我信!」 就拜 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, ' 耶稣 说:「我 为 审判 到 这 世上 来, 叫不 能看见的,可以看见; 能看见的,反 瞎了眼。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, ' 同 他 在那里 的法利赛人 听见 这话,就 说:「难道 我们 也 瞎了眼吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, '耶稣 对他们 说:「你们若 瞎了眼,就 没 有 罪了;但 如今 你们说『我们能看见』,所以你们的 罪 还在。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, '「我实实在在地 告诉 你们,人进 羊圈,不 从 门 进去,倒 从别处 爬进去,那人 就是 贼,就是 强盗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, '从 门 进去的,才 是 羊 的牧人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, '看门的 就给他 开 门;羊 也 听 他的 声音。 他按著 名 叫 自己的 羊, 把羊 领出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, '既 放出 自己的羊来,就在 前头 走,羊 也 跟著 他,因为 认得 他的 声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, ' 羊不 跟著 生人;因为 不 认得 他的声音, 必要 逃跑。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, '耶稣 将这 比喻 告诉 他们,但 他们 不 明白 所说 的是 什么意思。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, '所以,耶稣 又 对他们说:「我实实在在地 告诉 你们, 我 就是 羊 的门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, '凡 在我 以先 来 的都是 贼, 是强盗;羊 却 不 听 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, '我 就是 门;凡 从 我 进来 的,必然得救,并且 出 入 得 草吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, '盗贼 来,无 非 要 偷窃, 杀害, 毁坏;我 来了,是要叫羊(或译:人)得 生命,并且 得 的更丰盛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, '我 是 好 牧人;好 牧人 为 羊 舍 命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, '若是 雇工,不 是牧人,羊 也 不 是 他 自己的,他看见 狼 来,就 撇下 羊 逃走; 狼 抓住 羊, 赶散了羊群。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, '雇工逃走,因 他是 雇工,并 不 顾念 羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, '我 是 好 牧人; 我认识 我的羊,我的 羊也 认识 我, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, '正如 父 认识 我,我也 认识 父一样;并且 我 为 羊 舍 命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, ' 我另外 有 羊, 不 是 这 圈 里的;我 必须 领 他们来,他们也 要听 我的 声音,并且 要合成 一 群,归一个 牧人了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, ' 我父 爱 我;因 我 将 命 舍去,好 再 取回来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, '没有人 夺 我 的 命去,是 我 自己 舍的。我有 权柄 舍 了,也 有 权柄 取 回来。这 是我从 我 父 所受 的命令。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, ' 犹太人 为 这些 话 又 起了 纷争。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, ' 内中 有好些人 说:「他是被鬼 附著,而且 疯了,为什么 听 他呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, '又有人 说:「这 不 是 鬼附之人 所说的话。鬼 岂 能 叫瞎子 的眼睛 开 了呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, '在 耶路撒冷 有 修殿节,是 冬天的时候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, ' 耶稣 在 殿里 所罗门 的廊下 行走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, ' 犹太人 围著 他, 说:「你叫 我们 犹疑不定 到几时呢?你 若 是 基督,就明明地 告诉 我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, '耶稣 回答说:「我已经告诉 你们, 你们不 信。 我 奉 我 父 之名 所行 的事 可以为 我 作见证; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, '只是 你们 不 信,因为 你们不 是 我 的 羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, '我的 羊 听 我的 声音,我也 认识 他们,他们也 跟著 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, '我又 赐给 他们 永 生; 他们永 不 灭亡,谁 也不能 从 我 手里 把他们 夺去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, '我 父 把羊赐给 我,他 比万有 都大,谁也 不 能 从 我父 手里 把他们夺去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, '我 与 父 原为 一。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, '犹太人 又 拿起 石头 来要 打 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, '耶稣 对他们 说:「我从 父 显出 许多 善 事 给你们看,你们是为 哪一件 拿石头打 我呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, '犹太人 回答说:「我们不是 为 善 事 拿石头打 你, 是为 你说僭妄的话;又 为 你 是 个人,反将自己 当作 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, '耶稣 说:「你们的 律法 上 岂不 是 写著『 我 曾说 你们是 神』吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, ' 经上的话 是不 能 废的;若 那些 承受 神 道 的人尚且 称为 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, '父 所分别为圣、又 差 到 世间来的, 他自称 是 神 的儿子,你们 还向他 说『你说僭妄的话』吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, '我若 不 行 我 父 的事,你们就不 必信 我; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, ' 我若 行了,你们纵然 不 信 我,也当信 这些事,叫 你们又知道 又 明白 父 在我 里面,我 也在父 里面。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, ' 他们又 要 拿 他,他却 逃 出 他们的 手走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, ' 耶稣又 往 约旦河 外去,到了 约翰 起初 施洗 的地方,就 住在 那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, ' 有许多人 来 到 他那里。 他们说:「约翰 一件神迹 没有 行过,但 约翰 指著 这人 所说 的一切话 都是 真的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, ' 在那里,信 耶稣 的人就多了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, ' 有一个 患病的人,名叫拉撒路,住在 伯大尼, 就是马利亚 和 她 姊姊 马大 的村庄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, '这 马利亚 就是 那 用香膏 抹 主,又 用 头发 擦 他 脚的;患病 的拉撒路 是她 的兄弟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, ' 她姊妹 两个就打发 人去见 耶稣,说:「主 啊,你所爱 的人 病了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, ' 耶稣 听见,就说:「这 病 不 至 于  死,乃 是为 神 的荣耀,叫 神 的儿子 因此 得荣耀。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, '耶稣 素来 爱 马大 和 她 妹子 并 拉撒路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, ' 听 见 拉撒路病了,就 在 所 居 之地 仍 住了 两 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, '然后 对门徒 说:「我们再 往 犹太 去吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, '门徒 说:「拉比,犹太人 近来 要拿 石头打 你, 你还 往那里 去吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, '耶稣 回答说:「白日 不 是有 十二 小时吗?人 在 白日 走路,就不 至跌倒,因为 看见 这 世 上的光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, ' 若 在 黑夜 走路,就必跌倒,因为 他 没 有 光。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, '耶稣说了 这话,随 后 对他们 说:「我们 的朋友 拉撒路 睡了, 我去 叫醒 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, ' 门徒 说:「主啊,他若 睡了,就必好了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, ' 耶稣 这话是指著 他 死 说的,他们 却 以为 是 说 照常 睡了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, '耶稣 就 明明地 告诉 他们说:「拉撒路 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, ' 我没 有在 那里 就欢喜,这是为 你们的缘故,好 叫 你们相信。如今 我们可以往 他 那里去吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, ' 多马,又 称为 低土马,就对那同作门徒 的说:「我们 也 去 和 他 同 死吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, ' 耶稣 到了,就知道 拉撒路 在 坟墓 里已经 四 天了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, ' 伯大尼 离 耶路撒冷 不远,约 有六里 路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, ' 有好些 犹太人 来 看 马大 和 马利亚,要 为 她们的兄弟 安慰 她们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, ' 马大 听见 耶稣 来了,就出去迎接 他;马利亚 却 仍然坐 在 家里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, ' 马大 对 耶稣 说:「主啊,你若 早在 这里,我 兄弟 必不 死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, ' 就是 现在,我也知道, 你无论向 神 求什么, 神 也必赐给 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, '耶稣 说:「你 兄弟 必然复活。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, '马大 说:「我知道 在 末 日 复活 的时候,他必复活。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, '耶稣 对她 说:「复活 在 我,生命 也在我。信 我 的人虽然 死了,也必复活; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, ' 凡 活著 信 我 的人必永远 不 死。你信 这话吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, '马大说:「主啊,是的,我 信 你 是 基督,是 神 的儿子,就是 那要临 到 世界的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, ' 马大说了 这话,就回去 暗暗地 叫 她 妹子 马利亚,说:「夫子 来了, 叫 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, ' 马利亚 听见了,就急忙 起来, 到 耶稣 那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, '那时,耶稣 还没 有进 村子,仍 在 马大 迎接 他 的地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, ' 那些 同 马利亚 在 家 里 安慰 她 的犹太人,见 她 急忙 起来 出去,就跟著 她,以为 她要往 坟墓 那里 去 哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, ' 马利亚 到了 耶稣 那里,看见 他,就俯伏 在 他 脚前,说:「主啊,你若 早在 这里,我 兄弟 必 不 死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, ' 耶稣 看见 她 哭,并 看见与她 同来 的犹太人 也哭,就心 里悲叹,又 甚忧愁, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, '便 说:「你们把他 安放 在哪里?」他们回答说:「请主 来 看。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, '耶稣 哭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, ' 犹太人 就说:「你看 他爱 这人 是何等恳切。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, ' 其中 有人 说:「他 既然开 了 瞎子 的眼睛,岂 不 能 叫 这人 不 死吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, ' 耶稣 又 心里 悲叹,来 到 坟墓前;那 坟墓是 个洞, 有一块石头 挡著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, '耶稣 说:「你们把石头 挪开 。」那死人 的姊姊 马大 对他 说:「主啊,他现在 必是臭了,因为 他死了已经 四天了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, '耶稣 说:「我 不 是对你说过, 你若 信,就必看见 神 的荣耀吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, ' 他们就把石头 挪开 。 耶稣 举 目望天,说:「父啊,我感谢 你, 因为你已经听 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, '我 也 知道 你常 听 我,但 我说 这话是为 周围站著 的众人,叫 他们信 是 你 差了 我来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, ' 说了这话,就大 声 呼叫说:「拉撒路 出 来!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, '那死人 就出来了,手 脚 裹著 布, 脸 上包著 手巾。耶稣 对他们 说:「解开 , 叫他 走!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, ' 那些 来 看 马利亚 的 犹太人 见了 耶稣所 做的事,就多有信 他的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, '但 其中 也有去 见 法利赛人的, 将耶稣 所做 的事 告诉 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, ' 祭司长 和 法利赛人 聚集 公会, 说:「 这 人 行 好些 神迹,我们怎么 办呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, '若 这样 由著 他,人人 都要信 他, 罗马人 也要来 夺 我们 的地土 和 我们的百姓。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, ' 内中 有一个人,名叫该亚法,本 年 作 大祭司,对他们 说:「你们 不知道 什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, ' 独不想 一 个人 替 百姓 死, 免得 通 国 灭亡,就是 你们 的益处。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, ' 他这 话 不 是出于  自己,是 因他本 年 作 大祭司,所以预言 耶稣 将要 替这 一国 死; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, '也 不 但 替 这 一国死, 并要将 神 四散 的子民 都聚集 归 一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, ' 从 那 日起,他们就商议 要 杀 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, '所以,耶稣 不再 显然 行 在犹太人 中间,就 离开  那里 往 靠近 旷野 的地方去,到了 一座城,名叫 以法莲,就在那里 和门徒 同 住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, ' 犹太人 的逾越节 近了, 有许多 人从 乡 下上 耶路撒冷 去,要在节 前 洁净 自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, ' 他们就寻找 耶稣, 站 在殿 里 彼此 说:「你们 的意思 如何, 他不 来 过 节吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, '那时,祭司长 和 法利赛人 早已 吩咐 说,若 有人 知道 耶稣在 哪里,就要报明,好 去拿 他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, ' 逾越节 前 六 日,耶稣 来 到 伯大尼,就 是 他 叫拉撒路 从 死 里复活 之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, '有人在那里 给耶稣 预备 筵席; 马大 伺候,拉撒路 也 在 那同 耶稣 坐席 的人中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, ' 马利亚 就拿著 一斤 极贵 的真哪哒 香膏,抹 耶稣 的脚,又 用自己 头发 去擦,屋里 就 满 了 膏 的香气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, ' 有一个 门徒,就是 那将要 卖 耶稣 的加略人 犹大, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, '说:「这 香膏 为什么 不 卖 三十 两银子 赒济 穷人呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, ' 他说 这话, 并不 是 挂念 穷人,乃 因 他是 个贼,又 带著 钱囊,常取 其中所存的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, ' 耶稣 说:「由 她吧!她是为 我 安葬 之日 存留的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, '因为 常 有 穷人 和 你们同在,只是 你们不 常 有 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, ' 有许多 犹太 人 知道 耶稣在 那里, 就来了,不 但 是为 耶稣的缘故,也 是 要看 他从 死 里所复活 的拉撒路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, '但 祭司长 商议 连拉撒路 也 要杀了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, '因 有好些 犹太人 为拉撒路 的缘故,回去 信 了 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, '第二天,有许多 上来 过 节 的人 听见 耶稣 将到 耶路撒冷, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, '就拿著 棕树 枝 出去 迎接 他, 喊著说:和散那!奉 主 名 来 的 以色列 王 是应当称颂的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, ' 耶稣 得了 一个驴驹,就骑 上,如 经上所 记的说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, '锡安的民(原文是女子)哪,不 要惧怕!你 的王 骑 著 驴 驹 来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, '这些事 门徒 起先 不 明白, 等到 耶稣 得了荣耀 以后 才想起 这话 是 指著 他 写的,并且 众人果然向他 这样 行了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, '当 耶稣呼唤 拉撒路, 叫他 从 死 复活 出 坟墓的时候,同 耶稣 在 那里 的众人 就作见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, '众人 因 听见 耶稣行了 这 神迹,就 去迎接 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, '法利赛人 彼此 说:「看哪,你们是 徒劳 无益, 世人 都随从 他 去了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, ' 那时,上来 过 节 礼拜 的人中,有几个 希腊人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, ' 他们 来 见 加利利 伯赛大 的腓力, 求 他 说:「先生,我们愿 意 见 耶稣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, '腓力 去 告诉 安得烈, 安得烈 同 腓力 去 告诉 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, ' 耶稣 说:「人 子 得荣耀 的 时候 到了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, '我实实 在在地 告诉 你们,一粒 麦子 不 落 在 地 里死了, 仍旧是 一粒, 若 是死了,就结出 许多 子粒来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, '爱惜 自己 生命的,就失丧 生命; 在 这 世上 恨恶 自己 生命的,就要保守 生命 到 永 生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, '若 有人 服事 我,就当跟从 我; 我 在 哪里,服事我 的人 也 要在 那里;若 有人 服事 我,我父 必尊重 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, '「我 现在 心里 忧愁, 我说 什么才好呢?父啊,救 我 脱离 这 时候;但 我原是 为 这 时候 来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, '父啊,愿 你荣耀 你 的名!」当时 就有声音 从 天上 来,说:「我已经 荣耀了我的名,还要 再 荣耀。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, '站在 旁边 的众人 听见,就说:「打雷了。」还有人 说:「有天使 对他 说话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, '耶稣 说:「这 声音 不 是 为 我, 是为 你们来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, '现在 这 世界 受 审判, 这 世界 的王 要被赶 出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, '我 若 从 地 上被举起来,就要吸引 万人 来归 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, ' 耶稣这 话 原是指著 自己将要 怎样 死说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, ' 众人 回答说:「我们 听见 律法上有话说, 基督 是 永 存的, 你 怎么 说『人 子 必须 被举起来』呢?这 人 子 是 谁呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, ' 耶稣 对他们 说:「光 在 你们 中间 还有 不多的 时候,应当趁著 有 光 行走,免得 黑暗 临到 你们; 那在 黑暗 里行走的,不 知道 往何处 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, '你们应当趁著 有 光,信 从 这光,使 你们成为 光明 之子。」耶稣 说了 这话,就离开 他们 隐藏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, '他 虽然 在他们 面前 行了 许多 神迹,他们还是不 信 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, '这是 要应验 先知 以赛亚 的话, 说:主啊,我们 所传 的有谁 信呢? 主 的膀臂 向谁 显露呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, '他们所以 不 能 信,因为 以赛亚 又 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, '主叫他们 瞎了 眼, 硬了 心,免得 他们眼睛 看见, 心里 明白, 回转过来, 我就医治 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, '以赛亚 因为 看见 他 的荣耀,就 指 著 他 说 这话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, '虽然如此,官长 中 却 有好些 信 他的,只 因 法利赛人的缘故,就不 承认,恐怕 被 赶出会堂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, '这是 因他们爱 人 的荣耀 过 于 爱 神 的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, ' 耶稣 大声 说:「信 我的,不 是信 我,乃是 信 那差 我来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, ' 人看见 我,就是看见 那差 我来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, '我 到 世上来,乃是光,叫 凡 信 我的,不 住 在 黑暗里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, ' 若 有人 听见 我 的话 不 遵守,我 不 审判 他。我来 本 不 是要 审判 世界,乃 是要 拯救 世界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, '弃绝 我、 不 领受 我 话的人,有 审判 他的─就是我所 讲 的道 在 末 日 要审判 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, '因为 我 没 有凭著 自己 讲,惟 有差 我 来的父 已经给 我 命令,叫我说 什么, 讲 什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, '我也 知道 他 的命令 就是 永 生。故此,我 所讲 的话 正是 照著 父 对我 所说的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, ' 逾越 节 以前,耶稣 知道 自己 离 世 归 父 的时候 到了。他既然爱 世 间 属 自己的人,就爱 他们 到 底。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, ' 吃晚饭 的时候,魔鬼 已 将 卖 耶稣 的意思放 在 西门 的儿子加略人 犹大 心里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, '耶稣知道 父 已将万有 交在 他 手 里,且 知道自己是 从 神出来的,又 要归 到 神那里去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, '就离 席 站起来, 脱了 衣服, 拿 一条手巾 束 腰, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, '随后 把水 倒 在 盆里, 就 洗 门徒 的脚,并 用 自己所 束 的手巾 擦干。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, ' 挨 到 西门•彼得,彼得对他 说:「主啊,你 洗 我 的脚吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, '耶稣 回答 说:「我 所 做的,你 如今 不 知道, 后来 必明白。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, '彼得 说:「你永 不 可洗 我 的脚!」耶稣 说:「我若不 洗 你,你就 与 我 无 分了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, '西门•彼得 说:「主啊,不 但 我 的脚, 连 手 和 头也要洗。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, '耶稣 说:「凡洗过澡的人, 只要 把脚 一洗, 全身 就 干净了。 你们 是 干净的,然而 不 都是干净的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, '耶稣原 知道 要卖 他 的是谁,所以 说:「你们不 都 是 干净的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, ' 耶稣洗 完了 他们 的脚, 就穿 上 衣服, 又 坐下,对他们 说:「我向你们 所做 的,你们明白吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, '你们 称呼 我 夫子, 称呼我主, 你们说 的不错,我本来 是。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, ' 我 是你们的主, 你们的夫子,尚且洗 你们 的脚,你们 也 当 彼此 洗 脚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, ' 我给 你们 作了榜样,叫 你们 照著 我 向你们 所做 的去做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, '我实实 在在地 告诉 你们,仆人 不 能 大于  主人,差人 也 不能大于  差 他的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, '你们既 知道 这事,若 是去行 就有 福了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, '我这话不 是指著 你们 众人 说的,我 知道 我所拣选 的是谁。 现在要应验 经上的话,说:『同我 吃 饭 的人用 脚 踢 我。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, '如今 事情还没有成就,我要先 告诉 你们,叫 你们到事情成就 的时候 可以信 我 是基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, '我实实 在在地 告诉 你们,有人接待 我所差遣 的,就是接待 我; 接待 我,就是接待 那差遣 我的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, '耶稣 说 了这话,心 里忧愁,就 明 说:「我实实 在在地 告诉 你们, 你们 中间 有一个人 要卖 我了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, '门徒 彼此 对看,猜不透 所 说 的是谁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, '有 一个 门徒,是耶稣 所爱 的,侧身挨近 耶稣 的怀 里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, ' 西门•彼得 点头 对他 说:「你告诉我们, 主是指著 谁 说的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, '那门徒 便就势 靠著 耶稣 的胸膛,问他 说:「主啊,是 谁呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, '耶稣 回答说:「我 蘸 一点饼 给 谁,就是 谁。」 耶稣就蘸 了一点饼,递 给 加略人 西门 的儿子犹大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, ' 他吃了 以后,撒但 就入 了 他的心。 耶稣 便对他 说:「你所 做的,快 做吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, ' 同席 的人 没有一个知道 是 为什么 对他 说 这话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, ' 有人 因 犹大 带著 钱囊,以为 耶稣 是对他 说:「你去买  我们过 节 所 应 用的东西」,或 是叫 他拿什么 赒济 穷人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, '犹大 受了 那点饼,立刻 就 出去。 那时候是 夜间了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, ' 他既出去,耶稣 就说:「如今 人 子 得了荣耀, 神 在 人子 身上也得了荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, ' 神 要因 自己 荣耀 人子,并且 要快快地 荣耀 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, '小子们,我还 有不多的时候 与 你们 同在;后来你们要找 我,但我所去 的地方 你们 不 能 到。 这话我 曾 对犹太人 说过,如今 也照样 对你们 说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, '我赐给 你们 一条新 命令,乃是叫 你们彼此 相爱;我怎样 爱 你们,你们 也 要 怎样相 爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, '你们若 有 彼此 相爱的心,众人 因 此 就认出 你们是 我 的门徒了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, '西门•彼得 问耶稣 说:「主 往哪里 去?」耶稣 回答说:「我所去 的地方,你现在 不 能 跟我去,后来 却 要跟 我去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, '彼得 说:「主啊,我为什么 现在 不 能 跟 你去?我愿 意为 你 舍 命!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, '耶稣 说:「你愿 意为 我 舍 命吗?我实实 在在地 告诉 你,鸡 叫以先, 你要三次 不认 我。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, '「你们 心 里不 要忧愁;你们信 神,也 当信 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, '在 我 父的 家 里有 许多 住处; 若是 没有,我就早已告诉 你们了。 我去 原是为你们 预备 地方去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, ' 我若 去 为你们 预备了 地方,就必再 来 接 你们 到 我 那里去,我 在哪里,叫你们 也 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, ' 我 往哪里 去,你们知道;那条路,你们也知道(有古卷:我往哪里去,你们知道那条路)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, '多马 对他 说:「主啊,我们不 知道 你往哪里 去,怎么 知道 那条路呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, '耶稣 说:「我 就是 道路、 真理、 生命;若 不 藉 借著 我,没有人 能到 父 那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, '你们若 认识 我,也 就认识 我 的父。 从 今以后,你们认识 他,并且 已经看见 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, '腓力 对他 说:「求主 将父 显给 我们看, 我们 就知足了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, '耶稣 对他 说:「腓力,我与 你们 同在 这样长 久,你还 不 认识 我吗?人看见 了我,就是看见 了父;你 怎么 说『将父 显给 我们看』呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, ' 我 在 父 里面, 父 在我 里面,你不 信吗?我 对你们 所 说 的话,不 是凭著 自己 说的,乃 是住 在我 里面 的父 做 他 自己的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, '你们当信 我, 我 在父 里面, 父 在我 里面;即或 不信,也当因 我所做的事 信我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, '我实实在在地 告诉 你们, 我 所做 的事,信 我的 人也 要做,并且 要做 比这 更大的事,因为 我 往 父 那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, ' 你们奉 我 的名 无论 求 什么, 我必成就,叫 父 因 儿子 得荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, '你们若 奉 我 的名 求 什么,我 必成就。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, '「你们若 爱 我,就必遵守 我 的命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, '我 要求 父,父就 另外赐给 你们 一位 保惠师(或译:训慰师;下同),叫 他永 远 与 你们 同在, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, '就是真理 的圣灵,乃世 人不 能 接受 的;因为 不见 他,也 不 认识他。你们 却认识 他,因 他常与 你们 同在,也 要 在你们 里面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, '我不 撇下 你们 为孤儿,我必到 你们 这里来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, '还 有不多的时候, 世 人不再 看见 我,你们 却 看见 我;因为 我 活著,你们 也 要活著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, '到 那 日,你们 就知道 我 在 父 里面, 你们 在我 里面,我 也在你们 里面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, '有 了我的 命令 又 遵守的,这人 就是 爱 我的; 爱 我的必蒙 我 父 爱他,我 也要爱 他,并且 要向他 显现。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, '犹大(不 是加略人犹大)问耶稣 说:「主啊, 为什么 要 向 我们 显现, 不 向世人显现呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, '耶稣 回答 说:「人 若 爱 我,就必遵守 我 的道;我 父 也 必爱 他,并且 我们要到 他 那里去, 与 他 同 住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, '不 爱 我 的人就不 遵守 我 的道。 你们所 听见 的道 不 是 我的,乃 是差 我 来之父的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, '「我还与你们 同 住的时候,已将这些话 对你们 说了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, '但 保惠师,就是父 因 我 的名 所要差来 的 圣 灵,他 要将一切 的事指教 你们,并且 要叫你们 想起 我 对你们 所 说 的一切话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, '我留下 平安 给你们;我将我 的平安 赐给 你们。我 所赐的,不 像 世 人所赐的。你们 心 里不 要忧愁,也不 要胆怯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, '你们听见 我 对你们 说了,我去 还 要到 你们 这里来。你们若 爱 我,因 我到 父 那里去, 就必喜乐,因为 父 是 比我 大的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, ' 现在 事情还没有成就,我预先 告诉 你们,叫 你们到事情成就 的时候 就可以信。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, '以后我不 再 和 你们 多说话,因为 这世界 的王 将到。 他在我 里面 是毫无 所有; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, '但 要叫 世 人知道 我爱 父,并且 父 怎样 吩咐 我,我就怎样 行。起来,我们走 吧!」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, '「我 是 真 葡萄树, 我 父 是 栽培的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, '凡 属 我 不 结 果子 的枝子,他就剪去; 凡 结 果子的,他就修理干净,使 枝子结 果子 更多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, '现在 你们 因 我讲 给你们的 道,已经干净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, '你们要常在 我 里面,我也 常在你们 里面。枝子 若 不 常在 葡萄树 上,自己 就 不能 结 果子;你们 若 不 常 在 我 里面,也是 这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, '我 是 葡萄树,你们 是枝子。常在 我里面的,我也 常在 他里面,这人 就多 结 果子;因为 离了 我,你们就不 能 做 什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, '人 若 不 常在 我里面,就像 枝子 丢 在外面 枯干, 人拾起来, 扔 在 火 里 烧了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, '你们若 常在 我里面,我 的话 也 常在 你们里面,凡 你们所愿 意的,祈求,就 给你们 成就。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, ' 你们多 结 果子,我 父 就因此 得荣耀,你们也就 是 我 的门徒了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, '我 爱 你们,正如 父 爱 我一样;你们 要常在我 的爱 里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, '你们若 遵守 我 的命令,就常在 我 的爱里,正如 我 遵守了 我 父 的命令, 常在 他 的爱里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, '「这些事 我已经对你们 说了,是要叫 我 的喜乐 存在 你们心里,并 叫你们 的喜乐 可以满足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, ' 你们要彼此 相爱,像 我爱 你们一样;这 就是 我 的命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, ' 人 为 朋友 舍 命,人 的 爱心 没有比这个 大的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, '你们 若 遵行 我 所 吩咐的,就是 我 的朋友了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, '以后我不再 称 你们 为仆人,因 仆人 不 知道 主人 所做 的事。我乃 称 你们 为朋友;因 我从 我 父 所 听见 的,已经都告诉 你们了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, '不 是你们 拣选了 我,是 我 拣选了 你们,并且 分派 你们 去 结 果子, 叫你们的 果子 常存,使 你们奉 我的 名,无论 向父 求 什么,他就赐给 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, '我这样 吩咐 你们,是 要叫你们彼此 相爱。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, '「世人 若 恨 你们,你们知道(或译:该知道), 恨你们 以先 已经恨 我了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, '你们若 属 世界,世界 必 爱 属自己的;只 因 你们不 属 世界,乃 是我 从 世界 中拣选了 你们,所以 世界 就恨 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, '你们要记念 我 从前对你们 所 说 的话:『仆人 不 能 大于  主人。』他们若 逼迫了 我,也 要逼迫 你们;若 遵守了 我 的话,也 要遵守 你们的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, '但 他们因 我的名 要向 你们 行 这一切 的事,因为 他们不 认识 那差 我来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, '我若 没有 来 教训 他们,他们就没 有 罪;但 如今 他们 的罪 无 可 推诿了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, '恨 我的,也 恨 我 的父。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, '我若 没有 在他们 中间 行 过别人 未 曾行 的事,他们就没 有 罪;但 如今 连 我 与 我 的父,他们也 看见 也 恨恶了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, ' 这要应验 他们 律法 上 所 写 的话,说:『 他们无故地 恨 我。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, '但 我 要从 父 那里差 保惠师 来,就是 从 父 出来 真理 的圣灵;他来了,就要为 我 作见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, ' 你们 也 要作见证,因为 你们从 起头 就与 我 同在。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, '「我已将这些事 告诉 你们,使 你们不至于  跌倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, '人要把 你们 赶出会堂,并且 时候 将到, 凡 杀 你们 的就以为是 事奉 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, ' 他们这样 行,是因 未 曾认识 父,也未 曾认识我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, ' 我将这事 告诉 你们,是叫 你们 到了 时候 可以想起 我 对你们 说过了。」「 我起先 没有 将这事 告诉 你们,因为 我 与 你们 同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, ' 现今 我往 差 我 来的父那里去,你们 中间 并 没有人 问 我:『你往哪里 去?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, '只 因 我将这事 告诉 你们,你们 就满 心 忧愁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, '然而,我 将真情 告诉 你们, 我 去 是与你们 有益的; 我若 不 去,保惠师 就不 到 你们 这里来; 我若 去,就差 他 来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, '他 既 来了,就要叫世人 为 罪、 为 义、 为 审判,自己责备自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, '为 罪,是 因 他们不 信 我; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, ' 为 义,是因 我往 父 那里去,你们就 不再 见 我; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, ' 为 审判,是因 这 世界 的王 受了审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, '「我还 有 好些事 要告诉 你们,但 你们现在 担当 不了(或译:不能领会)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, ' 只等 真理 的圣灵 来了,他要引导 你们 明白(原文是进入)一切的 真理;因为 他不是 凭 自己 说的,乃是 把他所听见 的都 说出来,并 要把将来 的事告诉 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, '他 要荣耀 我,因为 他要将受 于  我的 告诉 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, '凡 父 所有的,都是 我的;所以 我说, 他要将 受于  我的 告诉 你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, '「等不多时,你们就 不 得见 我; 再 等不多时, 你们还要见 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, '有几个 门徒 就 彼此 说:「 他对我们 说:『等不多时,你们就 不 得见 我; 再 等不多时,你们还要 见 我』;又说:『因 我往 父 那里去。』这 是 什么意思呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, ' 门徒彼此说:「他说『等不多时』到底是 什么意思呢?我们不 明白 他所说 的话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, '耶稣 看出 他们要 问 他,就 说:「我说『等不多时,你们就 不 得见 我; 再 等不多时,你们还要 见 我』,你们为 这话 彼此 相问吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, '我实实在在地 告诉 你们, 你们 将要痛哭、 哀号,世人 倒 要喜乐;你们 将要忧愁,然而 你们的 忧愁 要变 为 喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, '妇人 生产 的时候 就 忧愁,因为 她的 时候 到了;既 生了 孩子,就不再 记念 那苦楚,因为 欢喜 世上 生了 一个人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, ' 你们 现在 也 是 忧愁,但 我要再 见 你们,你们的 心 就 喜乐了;这 喜乐 也 没有人 能 夺去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, ' 到 那 日,你们什么 也就不 问 我了。我实实在在地 告诉 你们, 你们若向父 求 什么,他必因 我的 名 赐给 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, '向来 你们没有 奉 我的 名 求 什么,如今你们求,就 必得著,叫 你们的 喜乐 可以 满足。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, '「这些事,我是用 比喻 对你们 说的;时候 将到, 我不再 用 比喻 对你们 说,乃要 将 父 明明地 告诉 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, '到 那 日,你们要奉 我的 名 祈求; 我并不 对你们 说, 我 要为 你们 求 父。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, ' 父 自己 爱 你们;因为 你们 已经爱 我,又 信 我 是从 父 出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, '我从 父 出来, 到了 世界;我又 离开  世界, 往 父 那里去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, ' 门徒 说:「 如今 你是明 说, 并不 用 比喻了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, '现在 我们晓得 你凡事 都知道,也 不 用 人 问 你,因 此 我们信 你是从 神 出来的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, '耶稣 说:「现在 你们信吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, '看哪,时候 将到,且是 已经到了, 你们要分散,各 归 自己的地方去,留下 我 独自一人;其实 我不 是 独自一人,因为 有父 与 我同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, '我将这些事 告诉 你们,是要 叫你们在 我 里面有 平安。在 世上,你们有 苦难;但 你们可以放心,我 已经胜了 世界。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, '耶稣 说了 这话, 就举 目 望 天,说:「父啊,时候 到了,愿 你荣耀 你的 儿子,使 儿子 也荣耀 你; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, '正如 你曾赐 给他 权柄 管理凡 有血气的, 叫他将永 生 赐 给 你所赐 给他的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, ' 认识 你─独一 的真 神,并且 认识 你所差来 的耶稣 基督, 这 就是 永 生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, '我 在 地上 已经荣耀 你,你所托 讬付 我 的事,我已成全了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, '父啊, 现在 求你 使我 同 你 享荣耀, 就是未有 世界 以先,我同 你 所有的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, '「 你从 世上 赐 给我的人,我已将你 的名 显明 与他们。他们本是 你的,你将他们 赐 给我, 他们也遵守 了你 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, '如今 他们知道, 凡 你所赐 给我 的,都是 从 你那里来的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, '因为 你所赐 给我 的道, 我已经赐 给他们, 他们 也领受了,又 确实 知道, 我是从 你 出来的,并且 信 你 差 了我来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, '我 为 他们 祈求,不 为 世人 祈求,却 为 你所赐 给我的人祈求,因 他们本是 你的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, ' 凡 是我的,都是 你的; 你的 也是我的,并且 我因 他们 得了荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, '从今以后,我不 在 世上, 他们 却在 世上;我 往 你 那里去。圣 父啊,求你 因 你所赐 给我 的名 保守 他们,叫 他们合而 为一 像 我们一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, ' 我与 他们同在的时候,因 你 所赐 给我 的名 保守了他们,我 也 护卫 了他们; 其中除了 那灭亡 之子,没有一个 灭亡的, 好叫经上的话 得应验。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, ' 现在 我往 你 那里去, 我还在 世上 说 这话, 是叫 他们 心里 充满 我的 喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, '我 已将你 的道 赐 给他们。 世界 又恨 他们;因为 他们 不 属 世界,正如 我 不 属 世界一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, '我不 求 你叫 他们 离开  世界,只 求 你保守 他们 脱离 那恶者(或译:脱离罪恶)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, '他们 不 属 世界,正如 我 不 属 世界一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, '求你用 真理 使他们 成圣;你 的道 就是 真理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, ' 你怎样差 我 到 世上,我也 照样差 他们 到 世上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, ' 我为 他们的缘故, 自己 分别为圣,叫 他们 也 因 真理 成圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, '「我不但 为 这些 人祈求, 也 为 那些因 他们 的话 信 我的人祈求, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, '使 他们都 合而为一。正如 你 父 在 我里面,我 在 你里面,使 他们 也 在 我们里面, 叫世人 可以信 你 差 了我来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, '你所赐 给我 的荣耀,我 已赐 给他们,使 他们合而为一,像 我们 合而为一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, '我 在 他们里面, 你 在 我里面,使 他们 完完全全地 合而为一, 叫世人 知道 你 差 了我来,也 知道你爱 他们 如同 爱 我一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, '父啊,我 在 哪里,愿  你所赐 给我 的人 也 同 我在那里, 叫他们看见 你所赐 给我 的 荣耀; 因为 创立 世界 以前,你已经爱 我了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, ' 公义的 父啊,世人 未曾 认识 你,我 却 认识 你;这些人 也 知道 你 差了 我来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, ' 我已将你的 名 指示 他们,还要 指示他们,使 你所爱 我 的爱 在 他们 里面,我 也在他们 里面。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, '耶稣 说了 这话,就同 门徒 出去,过了 汲沦 溪。在 那里 有 一个园子, 他 和 门徒 进去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, ' 卖 耶稣 的犹大 也 知道 那地方,因为 耶稣 和 门徒 屡次 上那里 去聚集。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, '犹大 领了 一队兵,和 祭司长 并 法利赛人的差役,拿著 灯笼、 火把、 兵器,就来到 园里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, ' 耶稣 知道 将要临 到 自己的 一切事,就出来 对他们 说:「你们找 谁?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, '他们回答说:「找拿撒勒人 耶稣。」耶稣 说:「我 就是!」 卖 他 的犹大 也 同 他们 站在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, '耶稣一 说「我 就是」,他们就退 后 倒 在地上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, ' 他又 问 他们说:「你们找 谁?」 他们说:「找拿撒勒人 耶稣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, '耶稣 说:「我已经告诉 你们, 我 就是。 你们若 找 我,就让 这些人 去吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, '这 要应验 耶稣从前的话,说:「你 所 赐给 我的人,我 没有 失落一个。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, ' 西门•彼得 带著 一把刀,就拔出来, 将大祭司 的仆人 砍了一刀, 削掉 他的 右 耳; 那仆人 名 叫 马勒古。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, ' 耶稣 就对彼得 说:「收 刀 入 鞘吧,我父 所 给 我 的那杯,我岂可不 喝呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, ' 那队兵 和 千夫长,并 犹太人 的差役 就拿住 耶稣, 把他 捆绑了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, ' 先 带 到 亚那面前,因为 亚那是 本 年 作 大祭司 该亚法 的岳父。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, ' 这该亚法 就是 从前向犹太人 发议论说「一个 人 替 百姓 死 是有益的」那位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, ' 西门•彼得 跟著 耶稣,还有 一个 门徒跟著。 那 门徒 是 大祭司 所认识的,他就 同 耶稣 进了 大祭司 的院子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, '彼得 却 站 在 门 外。 大祭司 所认识 的那个 门徒 出来, 和看门的使女 说了一声,就 领 彼得进去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, ' 那看门 的使女 对彼得 说:「你 不 也 是 这 人 的门徒吗?」他 说:「我 不是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, ' 仆人 和 差役 因为 天冷,就生 了炭火, 站 在那里烤火; 彼得 也 同 他们 站 著 烤火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, '大祭司 就以耶稣 的门徒 和 他 的教训 盘问他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, '耶稣 回答说:「我 从来是明明地 对世人 说话。我 常 在 会堂 和 殿 里,就是 犹太人 聚集 的地方 教训人; 我在 暗地里 并没有 说什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, '你为什么 问 我呢?可以问 那听见的人,我对他们 说 的是什么; 我 所说 的,他们 都知道。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, ' 耶稣 说了 这话,旁边站著 的一个 差役 用手掌 打 他,说:「你这样 回答 大祭司吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, '耶稣 说:「我若 说的 不是,你可以指证 那 不是; 我若 说的是,你为什么 打 我呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, ' 亚那 就把耶稣 解 到 大祭司 该亚法那里,仍是捆著解去的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, ' 西门•彼得 正站著 烤火, 有人对他 说:「你 不 也 是 他 的 门徒吗?」彼得 不承认, 说:「我不 是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, '有大祭司 的 一个 仆人,是 彼得 削掉 耳朵 那人的亲属,说:「我 不是 看见 你 同 他 在园子 里吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, ' 彼得 又 不承认。 立时 鸡 就叫了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, ' 众人将耶稣 从 该亚法 那里往 衙门内 解去, 那时天 还早。 他们自己 却不 进 衙门,恐怕 染了污秽, 不能 吃 逾越节的筵席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, '彼拉多 就 出来,到 他们那里, 说:「你们 告 这 人 是为 什么事呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, '他们回答 说:「这人 若 不 是 作 恶的,我们 就不 把他 交给 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, ' 彼拉多 说:「你们 自己带他 去, 按著 你们的 律法 审问 他吧。」犹太人 说:「我们 没有 杀 人 的权柄。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, '这要 应验 耶稣 所说 自己将要 怎样 死的话了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, ' 彼拉多 又 进了 衙门, 叫 耶稣来, 对他 说:「你 是 犹太人 的王吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, '耶稣 回答说:「这话 是 你 自己 说的,还是 别人 论 我 对你 说的呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, '彼拉多 说:「我 岂 是 犹太人呢?你 本国 的人和 祭司长 把你 交给 我。你做了 什么事呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, '耶稣 回答说:「我的 国 不 属 这 世界;我的 国 若 属 这 世界, 我的 臣仆 必要争战 ,使我不至于  被交给 犹太人。只是 我的 国 不 属这世界。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, '彼拉多 就 对他 说:「这样,你 是 王吗?」耶稣 回答说:「你 说 我是 王。我 为 此 而生,也 为 此 来 到 世间,特为给 真理 作见证。凡 属 真理 的人就听 我的 话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, '彼拉多 说:「真理 是 什么呢?」 说了 这话,又 出来 到 犹太人那里, 对他们 说:「我 查 不出 他 有什么罪来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, '但 你们 有 个规矩, 在 逾越节 要我给你们 释放 一个人, 你们要 我给你们 释放 犹太人 的王吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, ' 他们又 喊 著说:「不要 这人, 要巴拉巴!」 这巴拉巴 是 个强盗。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, '当下 彼拉多 将 耶稣 鞭打了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, ' 兵丁 用 荆棘 编做 冠冕 戴在 他 头上, 给他 穿上 紫 袍, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, '又 挨近 他, 说:「恭喜,犹太人 的王啊!」他们就 用手掌 打 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, ' 彼拉多 又 出来 对众人 说:「 我带 他 出来 见你们,叫 你们知道 我查 不 出 他 有什么罪来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, ' 耶稣 出来,戴著 荆棘 冠冕, 穿著紫 袍。 彼拉多对他们 说:「你们看 这个人!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, ' 祭司长 和 差役 看见 他,就喊著 说:「钉他十字架!钉他十字架!」彼拉多 说:「你们 自己把 他 钉十字架吧! 我 查 不 出 他 有什么罪来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, '犹太人 回答 说:「我们 有 律法, 按 那律法,他是该 死的,因 他以 自己为 神 的儿子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, ' 彼拉多 听见 这 话,越发 害怕, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, ' 又 进 衙门, 对耶稣 说:「你 是 哪里来的?」耶稣 却 不 回答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, ' 彼拉多 说:「你不 对我 说话吗?你岂不 知 我有 权柄 释放 你,也 有 权柄 把你 钉十字架吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, '耶稣 回答 说:「若不 是 从上头 赐给 你的,你就毫无 权柄 办 我。所以,把我 交给 你 的那人 罪 更重了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, '从 此,彼拉多 想要 释放 耶稣,无奈 犹太人 喊著 说:「你若 释放 这个人,就不 是 凯撒的忠臣(原文是朋友)。凡 以 自己 为王的,就是背叛 凯撒了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, ' 彼拉多 听见 这 话,就带 耶稣 出来, 到了一个地方,名叫「铺华石处」, 希伯来话 叫厄巴大,就在 那里坐 堂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, '那日是 预备 逾越节的日子, 约 有 午正。 彼拉多对犹太人 说:「看哪,这是你们的 王!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, ' 他们 喊著说:「除掉他!除掉他!钉他 在十字架上!」彼拉多 说:「我可以把你们的 王 钉十字架吗?」祭司长 回答说:「除了 凯撒,我们没 有 王。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, '于 是 彼拉多将耶稣 交给 他们 去 钉十字架。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, '他们就把耶稣带了去。 耶稣背著 自己的 十字架 出来,到了 一个地方,名叫「髑髅地」, 希伯来话 叫 各各他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, '他们就在那里 钉他 在十字架上,还有 两个 人和 他一同钉著,一边一个, 耶稣 在中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, '彼拉多 又 用牌子写了 一个名号, 安 在 十字架上, 写的 是:「犹太人 的王,拿撒勒人 耶稣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, ' 有许多 犹太人 念 这 名号;因为 耶稣 被钉十字架 的地方 与城 相近,并且 是 用希伯来、罗马、希腊 三样文字写的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, '犹太人 的祭司长 就 对彼拉多 说:「不要 写『犹太人 的王』, 要写『他自己 说:我是 犹太人 的王』。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, '彼拉多 说:「我所写 的,我已经写上了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, '兵丁 既然 将耶稣 钉在十字架上,就拿 他的 衣服 分为 四 分,每 兵 一分;又 拿他的里衣,这件里衣 原来 没有缝儿,是上下一片 织成的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, '他们就 彼此 说:「我们不要 撕开 ,只要 拈阄,看谁 得著。」这 要应验 经上的话 说:他们 分了 我的 外衣, 为 我的 里衣 拈 阄。 兵丁 果然 做了 这事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, ' 站在 耶稣 十字架 旁边的,有他 母亲 与 他 母亲的 姊妹,并革罗罢 的妻子 马利亚,和 抹大拉 的马利亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, ' 耶稣 见 母亲 和 他所爱 的那 门徒 站在旁边,就对他母亲 说:「母亲(原文是妇人),看,你的 儿子!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, '又 对那门徒 说:「看,你的 母亲!」 从 此,那门徒 就接 她 到 自己家里去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, '这事 以后,耶稣 知道 各样的事 已经 成了,为要 使经上的话 应验,就说:「我渴了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, ' 有 一个器皿 盛满了 醋,放在那里;他们就拿海绒 蘸满了 醋,绑在 牛膝草上,送到 他 口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, ' 耶稣尝(原文是受)了那醋,就说:「成了!」便 低下 头,将灵魂 交付 神了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, '犹太人 因 这日是 预备日,又因 那 安息日 是 个大 日,就求 彼拉多 叫 人打断 他们的 腿, 把他们拿去,免得 尸首 当 安息日 留在 十字架上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, '于 是 兵丁 来, 把头一个 人的腿,并 与耶稣 同钉 第二个人的腿,都打断了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, '只是 来 到 耶稣那里,见 他 已经 死了,就不 打断 他的 腿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, '惟 有一个 兵 拿枪 扎 他的 肋旁,随即 有血 和 水 流出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, '看见 这事的那人就 作见证─ 他的 见证 也是 真的,并且 他 知道 自己所说 的是真的─叫 你们 也 可以信。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, ' 这些事 成了,为要 应验 经上的话说:「他的 骨头一根 也不可 折断。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, ' 经上 又 有一句 说:「他们要仰望 自己所扎的人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, ' 这些事 以后,有亚利马太人 约瑟,是 耶稣 的门徒, 只因 怕 犹太人,就暗暗地作门徒。他来求 彼拉多,要 把耶稣 的身体 领去。 彼拉多 允准,他就 把耶稣 的身体 领去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, '又有 尼哥底母,就是 先前 夜里 去 见 耶稣的,带著 没药 和 沉香 约有 一百 斤 前来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, '他们就 照 犹太人 殡葬 的规矩,把 耶稣 的身体 用细麻布 加上 香料 裹好了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, ' 在 耶稣钉十字架 的地方 有 一个园子, 园子 里 有一座新 坟墓, 是从来没有 葬过人的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, '只因 是犹太人 的预备日,又因 那坟墓 近,他们就 把耶稣 安放 在那里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, ' 七日 的第一 日清早,天 还 黑的时候,抹大拉的 马利亚 来 到 坟墓那里, 看见 石头 从 坟墓 挪开 了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, '就 跑 来 见西门•彼得 和 耶稣 所 爱的 那个 门徒, 对他们 说:「有人把主 从 坟墓 里挪了去, 我们不 知道 放 在哪里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, '彼得 和 那 门徒 就 出来, 往 坟墓 那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, ' 两个人 同 跑, 那 门徒 比彼得 跑得更快, 先 到了 坟墓, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, ' 低头往里看,就见 细麻布 还 放在那里,只是没有 进去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, ' 西门•彼得 随 后 也 到了, 进 坟墓里去,就 看见 细麻布 还放在那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, '又 看见耶稣的 裹 头 巾 没有 和 细麻布 放在一处, 是另 在 一 处 卷著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, ' 先 到 坟墓 的那 门徒 也 进去, 看见 就 信了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, '(因为 他们还不 明白 圣经的意思,就是 耶稣 必 要从 死里 复活。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, '于 是 两个门徒 回 自己的住处去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, '马利亚 却 站 在 坟墓 外面 哭。 哭 的时候,低头 往 坟墓里看, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, '就 见 两个 天使,穿著 白衣,在安放 耶稣 身体 的地方 坐著,一个 在 头, 一个 在 脚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, ' 天使 对她 说:「妇人,你为什么 哭?」她 说:「因为 有人把我 主 挪了去, 我不 知道 放 在那里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, '说了这 话,就转过 身 来, 看见 耶稣 站在那里, 却不 知道 是 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, '耶稣 问她 说:「妇人,为什么 哭?你找 谁呢?」马利亚 以为 是 看园的,就对他 说:「先生,若是 你 把他 移了去,请告诉 我,你把他 放 在哪里,我 便去取 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, '耶稣 说:「马利亚。」马利亚 就转过来,用希伯来话 对他 说:「拉波尼!」( 拉波尼就是 夫子的意思。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, '耶稣 说:「不要 摸 我,因 我还没有 升上去 见我的父。 你往 我 弟兄 那里去, 告诉他们 说,我要升上去 见我的 父,也是 你们的 父, 见我的 神,也是 你们的 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, '抹大拉的 马利亚 就去 告诉门徒 说:「 我已经看见了 主。」她又 将主对她 说的这话 告诉他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, ' 那 日(就是 七日 的第一日)晚上, 门徒 所在 的地方,因 怕 犹太人,门 都关了。耶稣 来, 站 在 当中, 对他们 说:「愿 你们 平安!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, ' 说了 这话,就把手 和 肋旁 指给 他们看。门徒 看见 主,就 喜乐了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, ' 耶稣 又 对他们 说:「愿 你们 平安! 父 怎样差遣了 我,我 也照样差遣 你们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, ' 说了 这话,就向他们吹一口气, 说:「你们受 圣 灵! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, '你们赦免 谁的 罪,谁的 罪就赦免了;你们留下 谁的罪,谁的罪就留下了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, ' 那十二个 门徒中,有称为 低土马 的多马;耶稣 来 的时候,他没 有 和他们 同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, '那些 门徒 就 对他 说:「我们已经看见 主了。」多马却 说:「我非 看见 他 手 上 的钉 痕, 用 指头 探 入 那钉 痕,又 用 手 探 入 他的 肋旁,我总不 信。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, ' 过了 八 日, 门徒 又 在屋里,多马 也 和他们 同在,门 都关了。耶稣 来, 站 在 当中 说:「愿 你们 平安!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, '就 对多马 说:「伸过 你的 指头 来,摸(原文是看)我的 手; 伸出 你的 手来, 探 入 我的 肋旁。 不 要 疑惑,总要 信!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, '多马 说:「我的 主! 我的 神!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, '耶稣 对他 说:「你因 看见了 我 才信;那没有 看见 就 信 的有福了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, ' 耶稣 在 门徒 面前 另外 行了 许多 神迹, 没 有 记 在这 书 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, '但 记 这些事 要叫 你们信 耶稣 是 基督,是 神的 儿子,并且 叫 你们信了他,就可以因 他的 名 得 生命。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, '这些事 以后,耶稣 在 提比哩亚 海边 又 向门徒 显现。 他怎样显现 记在下面: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, '有西门•彼得 和 称为 低土马 的多马,并 加利利 的 迦拿人 拿但业,还有 西庇太 的两个儿子,又有 两个 门徒,都在 一处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, '西门•彼得 对他们 说:「我打鱼 去。」他们 说:「我们 也 和 你 同去。」他们就出去, 上了 船; 那 一夜 并没有 打著什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, ' 天将亮 的时候,耶稣 站 在 岸上, 门徒 却不 知道 是 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, ' 耶稣 就对他们 说:「小子! 你们有 吃的 没有?」他们回答说:「没有。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, ' 耶稣说:「你们把网 撒 在 船 的右 边,就 必得著。」他们便 撒下网去,竟 拉 不上来了,因为 鱼 甚多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, ' 耶稣 所 爱 的那 门徒 对彼得 说:「是 主!」那时 西门•彼得 赤著身子,一听 见 是 主,就束上 一件外衣, 跳在 海 里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, ' 其余 馀 的门徒 离 岸 不 远, 约 有 二百 肘(古时以肘为尺,一肘约有今时尺半),就在 小船 上把那网 鱼 拉过来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, ' 他们上 了 岸,就 看见 那里有炭火, 上面 有 鱼,又 有饼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, '耶稣 对他们 说:「把刚才 打 的 鱼 拿几条来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, ' 西门•彼得 就去(或译:上船), 把网 拉 到 岸上。那网满了 大 鱼,共一百 五十 三条; 鱼虽这样多,网 却没 有 破。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, '耶稣 说:「你们来 吃早饭。」 门徒 中没有 一个敢 问 他:「你 是 谁?」因为知道 是 主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, '耶稣 就来 拿 饼 和 鱼 给 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, '耶稣 从 死 里复活以后,向门徒 显现, 这 是第三次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, ' 他们吃完了早饭,耶稣 对西门•彼得 说:「约翰(在马太十六章十七节称约拿)的儿子西门,你爱 我 比 这些更深吗?」彼得说:「主啊,是的,你 知道 我爱 你。」耶稣对他 说:「你喂 𫗭养 我 的小羊。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, '耶稣第二 次又 对他 说:「约翰 的儿子西门,你爱 我吗?」彼得说:「主啊,是的,你 知道 我爱 你。」耶稣说:「你牧养 我 的羊。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, '第三 次对他 说:「约翰 的儿子西门,你爱 我吗?」彼得 因为 耶稣第三 次对他 说「你爱 我吗」,就忧愁, 对耶稣 说:「主啊,你 是无所 不知的;你 知道 我爱 你。」耶稣 说:「你喂 𫗭养 我 的羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, '我实实 在在地 告诉 你,你 年少 的时候,自己 束上带子, 随 意 往来;但 年老 的时候,你 要伸出 手来, 别 人要把你 束上, 带 你到不 愿 意 去的地方。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, '( 耶稣说 这 话是指著 彼得要怎样 死,荣耀 神。) 说 了这话,就对他 说:「你跟从 我吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, '彼得 转过来,看见 耶稣 所爱 的 那门徒 跟著,( 就 是在 晚饭的时候,靠 著 耶稣 胸膛 说:「主啊,卖 你 的是 谁?」的那门徒。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, ' 彼得 看见 他,就问耶稣 说:「主啊, 这人 将来如何?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, '耶稣 对他 说:「我若 要 他 等 到 我来的时候,与 你 何干?你 跟从 我吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, '于 是 这 话 传在 弟兄 中间,说 那 门徒 不 死。其实,耶稣 不 是说 他 不 死,乃是说:「我若 要 他 等 到 我来的时候,与 你 何干?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, '为这些事 作 见证,并且 记载 这些事 的 就是 这 门徒;我们也 知道 他 的见证 是 真的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, ' 耶稣 所 行 的事 还 有 许多, 若 是一 一地 都写出来,我想,所写 的书 就是世界 也容 不下了。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, '提阿非罗 啊,我已经作 了 前 书,论到 耶稣 开 头 一切 所行 所教训的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, '直到 他藉 借著 圣 灵 吩咐 所 拣选 的使徒, 以后被接上升 的日子为止。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, '他 受害 之后,用 许多的 凭据 将自己 活活地 显 给使徒看,四十 天 之久 向他们 显现, 讲说 神 国的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, ' 耶稣和他们聚集的时候,嘱咐 他们说:「不要 离开  耶路撒冷, 要等候 父 所应许的,就是 你们听见 我说过的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, ' 约翰 是用水 施洗,但 不 多 几日,你们 要受 圣 灵的洗。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, ' 他们聚集的时候,问 耶稣 说:「主啊,你复兴 以色列 国 就在 这 时候吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, ' 耶稣对 他们 说:「 父 凭著 自己的 权柄 所定 的时候、 日期,不 是 你们 可以知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, '但 圣 灵 降临 在 你们身上,你们就必得著 能力,并 要在 耶路撒冷、 犹太 全地,和 撒马利亚, 直到 地 极,作 我的 见证。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, ' 说 了这话,他们 正看的时候,他就被取上升, 有一朵云彩 把他 接去,便看不见他了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, ' 当 他 往上去,他们 定睛 望 天的时候, 忽然有两个 人 身穿 白 衣,站在旁边, 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, '「加利利 人哪,你们为什么 站著 望 天呢?这 离开  你们 被接 升 天 的 耶稣,你们见 他 怎样往 天 上去,他还要 怎样 来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, '有一座山,名叫 橄榄山, 离耶路撒冷 不远,约有 安息日 可走的路程。当下,门徒从 那里回 耶路撒冷去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, ' 进了城,就 上了 所住的一间楼房;在那里 有 彼得、 约翰、 雅各、 安得烈、腓力、 多马、巴多罗买 、 马太、亚勒腓 的儿子雅各、 奋锐党 的西门,和 雅各的儿子(或译:兄弟)犹大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, ' 这些 人同著几个妇人 和 耶稣 的母亲 马利亚,并 耶稣 的弟兄,都 同心合意地 恒切 祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, ' 那时, 有 许多人 聚会,约有 一百 二十名,彼得 就在 弟兄 中间 站起来,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, '「弟兄们! 圣 灵 藉 借 大卫 的口,在圣经 上预言 领人 捉拿 耶稣 的犹大,这话是必须 应验的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, ' 他本来 列 在 我们数中,并且 在 使徒的职任 上得了 一分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, ' 这人 用 他作恶 的工价 买 了 一块田,以后 身子仆倒,肚腹 崩裂, 肠子 都 流出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, ' 住 在耶路撒冷 的众人 都 知道这事,所以 按著他们 那里的 话 给那块 田 起名叫 亚革大马,就是「血 田」的意思。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, '因为 诗篇 上 写著,说:愿 他 的住处 变为 荒场, 无人 在内 居住;又说:愿 别人 得 他 的职分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, '所以, 主 耶稣 在 我们 中间始终出 入 的时候, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, '就是从 约翰 施洗 起,直到 主离开  我们 被接上升 的日子为止,必须 从那常与我们 作伴 的 人 中立 一位 与 我们 同作耶稣 复活 的见证。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, '于 是 选举 两个人,就是那 叫做 巴撒巴,又称呼 犹士都 的约瑟,和 马提亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, '众人就 祷告 说:「主啊,你 知道 万人的心,求你从 这 两个 人中,指明 你所拣选 的是谁,叫他得 这 使徒 的位分。 这 位分犹大 已经丢弃,往 自己 的地方 去了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, '于 是 众人为他们 摇 签, 摇出 马提亚来;他就 和 十一个 使徒 同列。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, ' 五旬节 到了,门徒都 聚集在 一处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, ' 忽然,从 天上 有 响声下来,好像 一阵大 风 吹过, 充满 了他们 所 坐 的 屋子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, '又 有舌头 如 火焰 显现出来,分开  落 在 他们 各人头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, '他们 就 都 被圣 灵 充满, 按著 圣灵 所赐 的口才 说 起别 国的话来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, '那时,有 虔诚的 犹太 人 从天 下 各 国来,住 在 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, ' 这 声音 一响,众人 都来聚集, 各人 听见 门徒 用众人的 乡谈 说话,就 甚纳闷; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, ' 都惊讶 希奇 说:「看哪,这 说话的 不 都 是 加利利人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, ' 我们 各人 怎么 听见 他们说我们 生来 所用的乡谈呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, '我们帕提亚人、 米底亚人、 以拦人,和 住 在美索不达米亚、 犹太、 加帕多家、本都、 亚细亚、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, '弗吕家、 旁非利亚、埃及的人,并 靠近 古利奈 的利比亚 一带地方的人, 从罗马 来的客旅中,或是 犹太人,或是 进犹太教的人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, '克里特 和 阿拉伯人,都听见 他们 用我们的 乡谈,讲说 神 的大作为。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, '众人 就 都惊讶 猜疑,彼此 说:「这 是 什么 意思呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, '还 有人 讥诮 说:「 他们无非是 新酒 灌满了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, ' 彼得 和 十一个 使徒站起,高 声 说:「犹太 人 和 一切 住 在耶路撒冷的人哪,这 件事你们 当 知道,也 当侧耳听 我的 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, ' 你们 想 这些 人是醉了;其实不是醉了,因为 时候刚到 巳初。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, ' 这 正是 先知 约珥 所说的: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, ' 神 说:在 末后的 日子,我要将 我的 灵 浇灌 凡 有血气的。 你们的 儿 女 要说预言; 你们的 少年人 要见 异象; 老年人 要做 异梦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, ' 在 那些 日子,我要将 我的 灵 浇灌 我的 仆人 和 使女,他们就 要说预言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, ' 在 天 上,我要显出 奇事; 在 地 下,我要显出神迹;有血, 有火, 有烟 雾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, '日头 要变 为 黑暗, 月亮 要变为 血;这都在主 大 而 明显的 日子 未到 以前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, ' 到那时候,凡 求告 主 名的,就必得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, '「以色列 人哪,请听 我的 话: 神 藉 借著 拿撒勒 人 耶稣 在 你们 中间 施行 异能、 奇事、神迹,将他 证明出来,这是 你们自己 知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, '他既按著 神 的定旨 先见 被交与人,你们就藉 借著 无法之 人的手,把他钉在十字架上,杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, '神 却将死 的痛苦 解释了,叫他 复活,因为 他原不 能 被 死 拘禁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, ' 大卫 指著 他 说:「我看见 主 常 在我 眼前; 他 在 我 右边,叫我不至于  摇动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, '所以,我 心 里欢喜, 我的灵(原文是舌)快乐;并且 我的 肉身 要 安居 在 指望中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, '因 你必不 将我的 灵魂 撇 在 阴间,也不 叫 你的 圣者 见 朽坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, '你已将生命 的道路 指示我,必叫我因见你的面(或译:叫我 在 你 面前)得著满足 的快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, '「弟兄们! 先祖 大卫的事,我可以 明明地 对 你们 说: 他死了,也 葬埋了,并且 他 的坟墓 直到 今 日 还在 我们这里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, ' 大卫既是 先知,又 晓得 神 曾向他 起誓,要从 他 的后裔 中立一位坐 在 他 的宝座上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, '就预先看明这事,讲论 基督 复活 说:他的灵魂不 撇 在 阴间;他 的肉身 也不 见 朽坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, '这 耶稣, 神 已经叫他复活了,我们 都 为这事 作 见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, '他既被 神 的右手 高举(或译:他既高举在 神的右边),又 从 父 受了 所应许 的圣 灵,就把 你们 所看见 所听见的,浇灌下来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, ' 大卫 并没有 升 到 天上,但 自己 说:主 对我 主 说:你坐 在 我的 右边, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, '等 我使 你 仇敌 作你的 脚 凳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, '「故此,以色列 全 家 当确实地 知道, 你们 钉在十字架 上的这位 耶稣, 神 已经立 他 为主, 为基督了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, ' 众人听见这话,觉得扎 心,就 对 彼得 和 其余 馀的 使徒 说:「弟兄们,我们当怎样 行?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, ' 彼得 说:「你们 各人 要悔改, 奉 耶稣 基督 的名 受洗,叫 你们的 罪 得赦,就 必领受 所赐 的圣 灵; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, '因为 这应许 是 给你们 和 你们的 儿女,并 一切 在 远方的人,就是 主─我们 神 所召来的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, '彼得还 用 许多 话 作见证, 劝勉 他们 说:「你们当救 自己脱离 这 弯曲的 世代。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, '于 是 领受 他 话 的人就受了洗。 那 一天,门徒约 添了 三千 人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, ' 都 恒心遵守 使徒 的教训, 彼此交接,擘 饼, 祈祷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, ' 众 人 都 惧怕; 使徒 又行了 许多 奇事 神迹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, ' 信 的人都 在 一处, 凡物 公 用, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, '并且 卖了 田产、 家业, 照 各人 所需用 的分给 各人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, ' 他们天天 同心合意 恒切地 在 殿里,且 在 家 中擘 饼,存著 欢喜、 诚实的 心 用 饭, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, '赞美 神, 得 众 民 的喜爱。 主 将得救 的人天天 加 给他们。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, ' 申初 祷告 的时候,彼得、 约翰 上 圣殿去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, ' 有一个 人,生来 是 瘸腿的,天天 被人抬来, 放 在 殿 的一个门口(那 门名叫 美门),要求 进 殿 的人赒济。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, '他 看见 彼得、 约翰 将要 进 殿,就求 他们赒济。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, ' 彼得、约翰 定睛看 他;彼得说:「你看 我们!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, ' 那人就留意看 他们,指望 得著 什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, ' 彼得 说:「金 银 我 都没 有,只 把 我所有 的给 你:我奉 拿撒勒人 耶稣 基督 的名,叫你起来 行走!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, '于 是 拉著 他 的右 手,扶 他起来; 他 的脚 和 踝子骨 立刻 健壮了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, '就 跳起来,站著,又 行走, 同 他们 进了 殿,走著, 跳著, 赞美 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, ' 百姓 都看见 他 行走, 赞美 神; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, ' 认得 他 是 那 素常坐 在 殿 的美 门口 求 赒济的,就 因 他 所遇著 的事满心 希奇、 惊讶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, ' 那人 正在 称为 所罗门 的廊下,拉著 彼得、 约翰;众 百姓 一齐跑 到 他们那里,很觉希奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, ' 彼得 看见,就对 百姓 说:「以色列 人哪,为什么 把 这事 当作希奇呢? 为什么 定睛看 我们,以为 我们凭自己的 能力 和 虔诚 使 这人 行走呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, '亚伯拉罕、 以撒、 雅各的 神,就是我们 列祖的 神,已经荣耀 了他的仆人(或译:儿子)耶稣;你们 却 把他 交付彼拉多。彼拉多定意 要释放 他, 你们竟在 彼拉多 面前 弃绝了他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, ' 你们 弃绝 了那圣洁 公义者,反 求著 释放 一个凶手 给你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, ' 你们杀了 那生命 的主, 神 却叫他 从 死 里复活了;我们 都是 为这事 作见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, ' 我们因 信 他 的名,他 的名 便叫 你们所看见 所认识 的这人 健壮了;正是 他 所赐 的信心,叫这人 在你们 众人 面前 全然好了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, ' 弟兄们,我晓得 你们做 这事是出于  不知,你们的 官长 也是 如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, '但 神 曾藉 借 众 先知 的口,预言 基督 将要受害,就这样 应验了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, '所以,你们当悔改 归正, 使你们的 罪 得以涂抹, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, '这样,那安舒的 日子 就必从 主 面前 来到;主也 必差遣 所预定 给你们 的基督(耶稣)降临。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, ' 天 必 留 他,等到 万物复兴 的时候,就是 神 从 创世以来、藉 借著 圣 先知 的口 所说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, '摩西 曾说:『主─ 神 要从 你们 弟兄 中间给你们 兴起 一位先知 像 我, 凡 他 向 你们 所说的,你们都要听从。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, ' 凡 不 听从 那 先知的,必要从 民 中全然灭绝。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, ' 从 撒母耳 以来的众 先知,凡 说预言的,也 都说 到这些 日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, '你们 是 先知 的子孙,也 承受 神 与 你们 祖宗 所立 的约,就是对 亚伯拉罕 说:『 地上 万 族 都要因 你的 后裔 得福。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, '神 既兴起 他的仆人(或译:儿子),就先 差 他 到你们这里来,赐福 给你们,叫 你们 各人 回转,离开  罪恶。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, ' 使徒 对 百姓 说话的时候,祭司 们和 守殿 官,并 撒都该人 忽然来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, '因 他们 教训 百姓, 本著 耶稣,传说 死人 复活,就很烦恼, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, '于 是 下 手 拿住他们;因为 天 已经 晚了, 就把他们押 到 第二天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, '但 听 道 之人有许多 信的, 男丁 数目 约 到 五 千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, ' 第二天, 官府、 长老,和 文士 在 耶路撒冷 聚会, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, '又有 大祭司 亚那 和 该亚法、 约翰、 亚历山大,并 大祭司 的亲族 都在那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, ' 叫使徒 站 在 当中,就问他们说:「你们 用 什么 能力, 奉 谁的 名 做 这事呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, '那时 彼得 被圣 灵 充满,对 他们 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, '「治民 的官府 和 长老啊,倘若 今日 因为在 残疾 人 身上所行的善事 查问 我们 他 是怎么 得了痊愈, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, '你们 众人 和 以色列 百姓 都当 知道, 站 在你们 面前 的这人 得痊愈 是因 你们 所 钉十字架、 神 叫他 从 死 里复活 的拿撒勒人 耶稣 基督 的名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, '他 是 你们 匠人 所弃 的石头, 已成了 房角 的头块石头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, ' 除他以外,别无 拯救;因为 在 天 下 人间,没 有 赐下 别的 名,我们 可以 靠著 得救。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, ' 他们见 彼得、 约翰 的胆量,又 看出 他们原是 没有学问的 小民,就希奇, 认明 他们 是 跟过 耶稣的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, '又 看见 那治好 了的人 和 他们 一同站著,就 无话 可驳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, '于 是 吩咐 他们 从公会 出去,就 彼此 商议 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, '「我们当怎样 办 这 两个人呢? 因为 他们 诚然行了 一件明显的 神迹,凡 住 耶路撒冷 的人都知道, 我们也不 能 说没有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, ' 惟恐 这事越发 传扬 在 民间,我们必须恐吓 他们,叫他们不再 奉 这 名 对 人 讲论。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, '于 是 叫了 他们来,禁止 他们 总不可 奉 耶稣 的名 讲论 教训人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, ' 彼得、 约翰 说:「听从 你们, 不听从神,这在 神 面前 合理不合理,你们自己酌量吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, ' 我们 所 看见 所听见的,不 能 不 说。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, ' 官长为 百姓的缘故,想 不 出法子 刑罚 他们,又恐吓一番,把他们 释放了。这是 因众人 为 所行 的奇事都归荣耀与 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, '原来 藉 借著 神迹 医 好的那 人 有 四十 多 岁了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, '二人既 被释放,就到 会友 那里去, 把祭司长 和 长老 所说 的话 都告诉 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, ' 他们听见了,就 同心合意地 高 声 向 神 说:「主啊!你 是 造 天、 地、 海,和 其 中 万物的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, '你 曾藉 借著 圣 灵,托 讬你 仆人─我们 祖宗 大卫 的口,说:外邦 为什么 争闹? 万民 为什么谋算 虚妄的事? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, '世上 的君王 一齐起来,臣宰 也 聚集,要敌挡 主,并 主 的受膏者(或译:基督)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, '希律 和 本丢•彼拉多, 外邦人 和 以色列 民, 果然 在 这 城 里聚集,要攻打 你 所 膏 的圣 仆(仆:或译子)耶稣, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, '成就 你 手 和 你 意旨 所预定 必有 的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, ' 他们 恐吓我们,现在 求主 鉴察,一面 叫 你 仆人 大 放胆量 讲 你的 道,一面 伸出 你的 手 来医治疾病,并且 使神迹 奇事 因著 你 圣 仆(仆:或译子)耶稣 的名 行出来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, ' 祷告完了, 聚会 的地方 震动,他们 就 都 被圣 灵 充满, 放胆 讲论 神 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, ' 那许多 信 的人都是 一 心 一意的, 没有 一 人说 他 的东西 有一样 是 自己的, 都 是 大家公用。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, ' 使徒 大 有能力, 见证 主 耶稣 复活; 众人 也 都 蒙大 恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, ' 内中也没有 一个 缺乏的;因为 人人 将田产 房屋 都卖了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, '把所卖 的价银 拿来, 放 在 使徒 脚前, 照 各人 所 需用的,分 给各人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, ' 有一个利未人,生在 塞浦路斯,名叫约瑟, 使徒 称 他为巴拿巴( 巴拿巴翻出来 就是 劝慰 子)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, '他 有 田地,也卖了,把价银 拿来, 放 在 使徒 脚前。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, ' 有一个 人,名叫 亚拿尼亚,同 他 的妻子 撒非喇 卖了 田产, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, ' 把 价银 私自留下几分,他的妻子 也 知道, 其余 馀的几分 拿来 放 在 使徒 脚前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, ' 彼得 说:「亚拿尼亚!为什么 撒但 充满了 你的 心,叫你 欺哄 圣 灵, 把 田地 的价银 私自留下几分呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, '田地还没有卖,不是 你自己的吗?既 卖了,价银不是 你 作主吗?你怎么 心 里起 这 意念呢?你不是 欺哄 人,是欺哄 神了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, ' 亚拿尼亚 听见 这话,就仆倒,断了气; 听见 的人都 甚 惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, ' 有些少年人 起来,把他 包裹, 抬出去 埋葬了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, ' 约 过了 三 小时, 他 的妻子 进来,还不 知道 这事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, ' 彼得 对 她 说:「你告诉 我,你们卖 田地 的价银就 是这些吗?」 她说:「 就是这些。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, ' 彼得说:「你们 为什么 同心 试探 主 的灵呢? 埋葬 你 丈夫 之人的脚 已到 门口,他们也 要把你 抬出去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, ' 妇人立刻 仆倒 在 彼得 脚前, 断了气。 那些少年人 进来,见 她 已经死了,就 抬出去,埋 在 她 丈夫旁边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, ' 全 教会 和 听见 这事 的人都 甚 惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, ' 主藉 借 使徒 的手 在 民间 行了 许多 神迹 奇事; 他们(或译:信的人)都 同心合意地 在 所罗门 的廊下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, ' 其余 馀的 人没有一个 敢 贴近 他们,百姓 却 尊重 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, ' 信 而归主 的人越发 增添,连男 带 女 很多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, ' 甚至 有人将病人 抬 到 街上, 放 在 床 上或 褥子上,指望 彼得 过来的时候,或者 得他的影儿 照 在 什么人身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, ' 还有 许多人 带著 病人 和 被 污 鬼 缠磨的,从耶路撒冷 四围的 城邑 来, 全 都得了医治。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, ' 大祭司 和 他 的一切同人, 就是 撒都该 教门的人,都起来,满心 忌恨, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, '就 下 手 拿住 使徒, 收 在 外 监。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, '但 主 的使者 夜间 开  了监 门, 领 他们出来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, '说:「你们去 站 在 殿里, 把这 生命 的道 都讲 给 百姓听。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, ' 使徒听了这话, 天将亮 的时候就进 殿 里 去教训人。 大祭司 和 他 的同人来了,叫齐 公会 的人和 以色列 族 的众 长老,就 差人 到 监里去,要把使徒 提出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, '但 差役 到了,不 见 他们 在 监里,就 回来 禀报 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, '「 我们看见 监牢 关 得 极 妥当, 看守 的人也站 在 门外;及至 开 了门,里面 一个人都不 见。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, ' 守殿 官 和 祭司长 听见 这 话,心里犯难,不知这事 将来如何。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, '有一个人 来 禀报说:「 你们收 在 监 里的人, 现在 站 在 殿 里 教训 百姓。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, '于 是 守殿官 和 差役 去 带 使徒来,并没有 用 强暴,因为 怕 百姓 用石头打他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, ' 带到了,便叫 使徒站在 公会前; 大祭司 问 他们 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, '「我们不是 严严地 禁止 你们,不可 奉 这 名 教训人吗? 你们倒把你们的 道理 充满 了耶路撒冷, 想要 叫这 人 的血 归 到 我们身上!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, ' 彼得 和 众使徒 回答 说:「顺从 神,不顺从 人,是应当的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, ' 你们 挂 在 木头 上杀害 的耶稣,我们 祖宗的 神 已经叫他复活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, '神 且用 右手 将他 高举(或译:他就是 神高举在自己的右边),叫他作君王, 作救主,将悔改 的心和 赦 罪 的恩赐 给以色列人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, ' 我们 为这 事 作 见证; 神 赐 给顺从 之人的圣 灵也为这事作见证。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, '公会的人听见 就 极其恼怒, 想要 杀 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, '但 有一个 法利赛人,名叫 迦玛列,是众 百姓 所敬重的 教法师,在 公会 中站起来,吩咐 人 把使徒暂且 带到 外面去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, '就 对 众人 说:「以色列 人哪,论到 这些 人,你们 应当小心 怎样 办理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, ' 从前 杜达 起来,自 夸 为 大;附从 他 的人 约有 四百,他 被杀后, 附从 他 的全 都散了, 归 于  无有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, '此后, 报名上册 的时候,又 有加利利 的犹大 起来,引诱 些百姓 跟从 他;他也 灭亡, 附从 他 的人也 都四散了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, ' 现在,我劝 你们 不要管 这些 人, 任凭 他们吧! 他们 所谋的、 所行的,若 是 出于  人,必要败坏; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, ' 若 是 出于  神,你们就不 能 败坏 他们,恐怕 你们倒是攻击 神了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, ' 公会的人听从 了他,便 叫 使徒来,把他们打了,又吩咐 他们不可 奉 耶稣 的名 讲道,就 把他们释放了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, ' 他们离开  公会,心里欢喜,因 被算是配 为 这名 受辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, '他们就 每 日 在 殿里、 在 家 里不住地 教训人, 传 耶稣 是基督。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, ' 那时,门徒 增多,有 说希腊话 的犹太人向 希伯来人 发怨言,因为 在 天天的 供给 上忽略 了他们 的寡妇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, ' 十二 使徒叫 众 门徒来,对他们说:「我们 撇下 神 的道 去管理 饭食,原是 不 合宜的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, '所以 弟兄们,当从 你们 中间选出 七个 有好名声、被圣灵 充满、 智慧 充足的人,我们就派 他们 管理 这 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, '但 我们 要专心 以祈祷、 传道 为事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, ' 大众 都喜悦 这话,就 拣选 了司提反,乃是大有信心、 圣 灵 充满 的人,又 拣选腓利、 伯罗哥罗、 尼迦挪、 提门、 巴米拿,并 进犹太教的 安提阿人 尼哥拉, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, '叫他们 站 在 使徒面前。 使徒祷告了,就按 手 在他们头上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, ' 神 的道 兴旺起来; 在 耶路撒冷 门徒 数目 加增 的甚多,也有 许多 祭司 信从 了这道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, ' 司提反 满 得恩惠、 能力,在 民间 行 了大 奇事 和 神迹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, '当时 有 称 利百地拿 会堂 的几个人,并 有古利奈、 亚历山大、 基利家、 亚细亚各处会堂的几个人,都起来 和司提反 辩论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, ' 司提反 是以智慧 和 圣灵 说话,众人敌挡 不住, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, ' 就买 出 人 来说:「 我们听见 他 说 谤讟 摩西 和 神 的话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, '他们又 耸动 了百姓、 长老,并 文士,就 忽然来 捉拿 他, 把他带 到 公会去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, ' 设下 假 见证,说:「这个 人 说话,不住地 糟践 圣 所 和 律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, ' 我们曾听见 他 说, 这 拿撒勒人 耶稣 要毁坏 此 地,也 要改变 摩西 所交 给我们 的规条。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, ' 在 公会 里坐著 的人都定睛看 他,见 他 的面貌,好像 天使 的面貌。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, '大祭司 就 说:「这些事 果然 有吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, ' 司提反 说:「诸位 父 兄 请听!当日我们 的祖宗 亚伯拉罕 在 美索不达米亚 还未 住 哈兰的时候,荣耀的 神 向他 显现, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, ' 对 他 说:『你 要离开  本地 和 亲族, 往 我所 要指示 你 的地方 去。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, ' 他就离开  迦勒底人 之地,住 在 哈兰。他 父亲 死了 以后, 神使他 从那里 搬 到 你们 现在 所 住 之 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, '在 这地方, 神并 没有 给 他 产业,连立足之地 也没有给他;但 应许 要将这地 赐 给他 和 他 的后裔 为 业;那时他 还没 有 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, ' 神 说:『 他 的后裔 必 寄居 外邦, 那里的人要叫他们 作奴仆, 苦待 他们四百 年。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, '神 又说:『 使他们作奴仆 的那国,我 要惩罚。 以后 他们要出来, 在 这 地方 事奉 我。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, '神又 赐 他 割礼 的约。于 是 亚伯拉罕生了 以撒, 第八 日 给他 行了割礼。 以撒 生雅各; 雅各 生十二位 先祖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, '「 先祖 嫉妒 约瑟,把他卖 到 埃及去; 神 却 与 他 同在, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, ' 救 他 脱离 一切 苦难,又 使他 在 埃及 王 法老 面前得 恩典, 有智慧。法老就 派 他 作 埃及国 的宰相兼 管 全 家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, ' 后来 埃及 和 迦南 全 地遭遇饥荒, 大 受艰难,我们的 祖宗 就 绝了 粮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, ' 雅各 听见 在 埃及 有 粮,就打发 我们的 祖宗 初次往那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, ' 第二次 约瑟 与 弟兄 们相认, 他 的亲族 也被法老 知道了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, '约瑟 就 打发 弟兄请 父亲 雅各 和 全 家 七十 五 个人都来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, '于 是 雅各 下了 埃及,后来 他 和 我们的 祖宗 都死在那里; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, '又 被带 到 示剑, 葬 于  亚伯拉罕 在 示剑 用银子 从 哈抹 子孙 买 来 的坟墓里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, '「 及至 神 应许 亚伯拉罕 的 日期 将到,以色列民 在 埃及 兴盛 众多, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, '直到 有 不 晓得 约瑟 的新王 兴起。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, '他 用诡计待 我们的 宗族,苦害 我们的 祖宗,叫 他们 丢弃 婴孩,使 婴孩不能 存活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, ' 那 时,摩西 生下来, 俊美非凡, 在 他父亲 家 里抚养 了三 个月。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, ' 他 被丢弃的时候,法老 的女儿 拾了去, 养 为 自己的 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, ' 摩西 学了 埃及人 一切的 学问, 说话 行事 都有 才能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, '「 他 将到 四十岁, 心中 起意 去看望 他 的弟兄 以色列人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, '到了那里,见 他们一个人 受冤屈,就护庇他, 为那受欺压 的人 报仇,打死 了那埃及人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, ' 他 以为 弟兄 必明白 神 是藉 借 他 的手 搭救 他们;他们却 不 明白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, ' 第二 天, 遇见 两个以色列人争斗,就 劝 他们 和睦,说:『 你们二位是 弟兄,为什么 彼此 欺负呢?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, ' 那欺负 邻舍 的把他 推开 ,说:『谁 立 你 作 我们的 首领 和 审判官呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, '难道你 要杀 我,像 昨天 杀 那埃及人吗?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, '摩西 听见 这 话 就 逃走了, 寄居 于  米甸;在那里 生了 两个 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, '「 过了 四十 年,在 西奈 山 的旷野,有一位天使 从 荆棘 火 焰 中向摩西 显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, ' 摩西 见了 那异象,便觉希奇, 正进前 观看的时候,有 主 的声音说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, '『我 是你 列祖的 神,就是亚伯拉罕的 神, 以撒的 神, 雅各的 神。』 摩西 战 战 兢兢,不 敢 观看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, ' 主 对他 说:『把你 脚 上的鞋 脱下来,因为 你所站 之地 是 圣 地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, '我的 百姓 在 埃及 所受的困苦,我实在看见了,他们 悲叹的声音,我也 听见了。 我下来 要救 他们。 你来!我要差 你 往 埃及去。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, '这 摩西 就是 百姓弃绝 说『谁 立 你 作我们的首领 和 审判官』的; 神 却藉 借 那 在 荆棘 中显现 之使者 的手 差派 他 作首领、 作救赎的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, '这人 领百姓 出来,在 埃及, 在 红 海, 在 旷野,四十 年 间行了 奇事 神迹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, '那 曾对以色列人 说『 神 要从 你们 弟兄 中间给你们 兴起 一位先知 像 我』的,就是 这位 摩西。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, '这人 曾 在 旷野 会 中 和 西奈 山上,与 那 对他 说话 的天使同在,又 与我们的 祖宗同在,并且 领受 活泼 的圣言 传 给我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, '我们的 祖宗 不 肯 听从,反 弃绝他, 心 里归 向 埃及, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, '对亚伦 说:『你且为我们 造 些神像, 在我们 前面引路;因为 领 我们 出 埃及 地 的那个 摩西,我们不 知道 他 遭了 什么事。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, ' 那 时,他们造了一个牛犊,又 拿 祭物 献给那像, 欢喜 自己 手 中 的工作。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, '神 就 转脸不顾, 任凭 他们 事奉 天上 的日月星辰,正如 先知 书 上 所写的说:以色列 家啊,你们四十 年 间在 旷野,岂是 将牺牲 和 祭物 献 给我吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, ' 你们 抬著 摩洛 的帐幕 和 理番 神 的星,就是 你们所造 为要敬拜 的像。因此,我要把你们 迁到 巴比伦 外去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, '「我们的 祖宗 在 旷野,有 法柜 的帐幕,是 神吩咐 摩西 叫 他照 所看见 的样式 做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, ' 这帐幕,我们的 祖宗 相继承受。当 神 在他们 面前 赶出 外邦人去的时候,他们同 约书亚 把帐幕搬进 承受为业之地,直存到 大卫 的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, '大卫 在 神 面前蒙恩, 祈求 为雅各的 神 预备 居所; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, '却 是所罗门为 神 造成 殿宇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, '其实,至高者 并不 住 人手所造的,就如 先知 所言: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, '主 说:天 是我的 座位, 地 是我的 脚 凳;你们要为我 造 何等的 殿宇? 哪里 是我 安息 的地方呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, '这一切 不 都是我 手 所造的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, '「你们 这硬著颈项、 心 与 耳 未受割礼的人,常时 抗拒 圣 灵!你们的 祖宗 怎样,你们 也怎样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, '哪一个 先知 不是 你们 祖宗 逼迫呢?他们也 把 预先传说 那义者 要来 的人杀了;如今 你们 又 把那义者 卖了, 杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, '你们 受了 天使 所传 的律法, 竟不 遵守。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, '众人 听见 这话 就 极其恼怒, 向 司提反 咬牙切齿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, '但 司提反被圣 灵 充满,定睛望 天,看见 神 的荣耀,又 看见耶稣 站 在 神 的右边, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, '就 说:「 我看见 天 开 了, 人 子 站 在 神 的右边。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, ' 众人大 声 喊叫,摀著 耳朵, 齐心 拥上前去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, ' 把他推到 城 外,用石头打他。 作见证的人 把 衣裳 放 在 一个少年人 名叫 扫罗 的脚前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, ' 他们正用石头打的时候,司提反 呼吁 主 说:「求主 耶稣 接收 我的 灵魂!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, '又 跪下 大 声 喊著说:「主啊,不要 将这 罪 归于  他们!」说 了这话,就 睡了。扫罗 也 喜悦 他 被害。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, ' 从 这 日起, 耶路撒冷 的教会 大 遭 逼迫,除了 使徒以外, 门徒 都分散 在 犹太 和 撒马利亚 各处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, ' 有虔诚的 人 把司提反 埋葬了, 为 他 捶胸大哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, '扫罗 却 残害 教会,进 各人的家,拉著 男 女 下 在 监里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, ' 那些分散 的人往各处去 传 道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, ' 腓利 下 撒马利亚 城去, 宣讲 基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, ' 众人 听见了,又 看见 腓利 所行 的神迹,就同心合意地 听从 他的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, '因为 有许多人 被污 鬼 附著,那些鬼大 声 呼叫,从他们身上出来;还有 许多 瘫痪的、 瘸腿的,都得了医治。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, '在 那 城里,就 大 有 欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, ' 有一个 人,名叫 西门,向来 在 那城 里行邪术, 妄自尊大,使撒马利亚 的百姓 惊奇; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, '无论 大 小 都 听从 他,说:「这人 就是 那称为 神 的大 能者。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, ' 他们听从 他,因 他久 用邪术,使他们 惊奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, ' 及至 他们信了 腓利 所传 神 国 的福音和 耶稣 基督 的名,连 男 带 女 就受了洗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, ' 西门 自己 也 信了;既 受了洗,就常与腓利 在一处, 看见 他所行 的神迹 和 大 异能,就甚惊奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, ' 使徒 在 耶路撒冷 听见 撒马利亚人 领受了 神 的道,就打发 彼得、 约翰 往 他们那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, '两个人 到了,就为 他们 祷告,要叫 他们受 圣 灵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, '因为 圣灵还没 有 降 在 他们一个人身上, 他们只 奉 主 耶稣 的名 受了洗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, '于 是 使徒按 手 在 他们头上,他们就 受了 圣 灵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, ' 西门 看见 使徒 按 手,便有圣灵 赐下,就拿 钱 给使徒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, '说:「把这 权柄 也 给我,叫 我手 按 著谁,谁就可以受 圣 灵。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, ' 彼得 说:「你 的银子 和 你 一同 灭亡吧!因 你想 神 的恩赐 是可以用 钱 买 的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, '你 在 这 道 上 无 分 无关;因为在 神 面前,你 的心 不 正。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, ' 你 当懊悔 你 这 罪恶, 祈求 主,或者 你 心 里的意念 可得赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, ' 我看出 你 正在 苦 胆之中, 被罪恶 捆绑。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, ' 西门 说:「愿 你们 为 我 求 主,叫 你们所说的,没有一样 临 到 我身上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, ' 使徒既证明 主 道,而且 传讲,就回 耶路撒冷去, 一路在撒马利亚 好些 村庄 传扬福音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, ' 有主 的一个使者 对 腓利 说:「起来! 向 南 走,往 那从 耶路撒冷 下 迦萨 的路上去。」那 路是 旷野。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, ' 腓利就起身 去了, 不料,有一个衣索匹亚(就是古实,见以赛亚十八章一节)人,是个有大权 的太监, 在衣索匹亚 女王 甘大基 的手下总管 银库, 他上 耶路撒冷 礼拜 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, ' 现在 回来, 在 车 上坐著, 念 先知 以赛亚的书。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, ' 圣灵 对腓利 说:「你去! 贴近 那 车走。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, '腓利 就 跑到太监那里,听见 他 念 先知 以赛亚的书,便 问他说:「你所 念的,你 明白吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, ' 他说:「没有 人 指教 我, 怎 能明白呢?」于 是 请 腓利 上车,与 他 同坐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, ' 他所 念 的那段经,说:他像 羊 被牵 到 宰杀之地,又 像 羊羔 在 剪毛 的人手下无声;他 也是这样 不 开  口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, ' 他 卑微的时候,人不按公义审判他(原文是他 的审判 被夺去);谁 能述说 他 的世代?因为 他 的生命 从 地上 夺去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, ' 太监 对腓利 说:「请问,先知 说 这 话是指著 谁?是指著 自己呢? 是指著 别人呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, '腓利 就 开  口 从 这 经 上起,对他 传讲 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, ' 二人正 往前走,到了 有 水的地方, 太监 说:「看哪,这里有水,我 受洗 有什么 妨碍呢?」(有古卷加: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, ' 腓利 说:「你若是 一 心 相信,就可以。」 他回答 说:「我信 耶稣 基督 是 神 的儿子。」) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, '于 是 吩咐 车 站住, 腓利 和 太监 二人 同下 水里去,腓利就 给他 施洗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, ' 从 水 里上来,主 的灵 把腓利 提了去,太监 也 不再 见 他了,就 欢欢喜喜地 走 路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, ' 后来有人在 亚锁都 遇见 腓利; 他 走遍那地方,在各 城 宣传福音,直到 凯撒利亚。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, ' 扫罗 仍然 向 主 的门徒 口吐 威吓 凶煞的话,去见 大祭司, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, ' 求 文书 给 大马士革 的 各会堂, 若是 找著 信奉这道 的人,无论 男 女,都准他捆绑 带 到 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, ' 扫罗 行路,将到 大马士革,忽然 从 天上 发光,四面照著 他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, '他就 仆倒 在 地,听见 有声音 对他 说:「扫罗!扫罗!你为什么 逼迫 我?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, ' 他说:「主啊!你是 谁?」主说:「我 就是 你 所 逼迫 的耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, ' 起来! 进 城去, 你 所当 做 的事,必有人 告诉 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, ' 同行 的人 站在那里,说不出话来, 听见 声音,却 看 不见人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, ' 扫罗 从 地 上起来, 睁开  眼睛,竟不 能看见什么。 有人拉 他的手,领 他进 了大马士革; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, ' 三 日 不 能看见,也 不 吃 也不 喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, '当下,在 大马士革 有 一个 门徒,名叫 亚拿尼亚。 主 在 异象 中对 他 说:「亚拿尼亚。」 他说:「主, 我在这里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, ' 主 对 他说:「起来!往 直 街 去, 在 犹大 的家里,访问 一个大数人,名叫 扫罗。 他正祷告, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, '又 看见 了一个人,名叫 亚拿尼亚,进来 按 手 在他身上,叫 他能看见。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, ' 亚拿尼亚 回答说:「主啊,我听见 许多人说:这 人 怎样 在 耶路撒冷 多多 苦害 你的 圣徒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, '并且 他在这里 有 从 祭司长 得来的权柄 捆绑 一切 求告 你 名的人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, ' 主 对 亚拿尼亚 说:「你只管去! 他 是 我 所拣选 的器皿,要在外邦人 和 君王,并 以色列人 面前 宣扬 我的 名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, ' 我 也要指示 他, 为 我的 名 必须 受 许多的苦难。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, '亚拿尼亚 就 去了, 进 入 那家, 把手 按 在 扫罗身上,说:「兄弟 扫罗,在 你来 的路 上向你 显现 的主,就是耶稣,打发 我来,叫 你能看见,又 被圣 灵 充满。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, ' 扫罗 的眼睛上,好像 有鳞 立刻 掉下来,他就能看见。于 是 起来 受了洗; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, '吃过饭 就 健壮了。 扫罗和 大马士革 的门徒 同住了 些 日子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, '就 在 各会堂 里宣传 耶稣,说 他 是 神 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, ' 凡 听见 的人都惊奇, 说:「在 耶路撒冷 残害 求告 这 名的,不 是 这人吗?并且 他到这里 来,特 要 捆绑 他们,带 到 祭司长那里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, '但 扫罗 越发 有能力, 驳倒 住 大马士革 的犹太人,证明 耶稣 是 基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, ' 过了 好些 日子,犹太人 商议 要杀 扫罗, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, '但 他们 的计谋 被扫罗 知道了。他们又 昼 夜 在城门 守候,要 杀 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, '他的门徒 就 在夜间 用 筐子 把 他 从 城墙 上 缒下去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, ' 扫罗到了 耶路撒冷,想 与门徒 结交,他们 却 都怕 他,不 信 他是 门徒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, '惟有 巴拿巴 接待 他,领去 见 使徒, 把他在 路 上怎么 看见 主, 主怎么向他 说话, 他在 大马士革 怎么 奉 耶稣 的名 放胆传道,都 述说出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, '于 是 扫罗 在 耶路撒冷 和 门徒 出 入来往, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, '奉 主 的名 放胆 传道,并 与 说希腊话的犹太人 讲论辩驳;他们却 想法子 要杀 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, ' 弟兄们 知道 了就送他 下 凯撒利亚, 打发 他 往 大数去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, ' 那时,犹太、加利利、 撒马利亚 各处 的教会 都得 平安,被建立; 凡事 敬畏 主, 蒙圣 灵 的安慰,人数就增多了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, ' 彼得 周流 四方的时候,也 到了 居住 吕大 的圣徒那里; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, ' 遇见 一个 人,名叫 以尼雅, 得了 瘫痪,在 褥子 上躺卧 八 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, ' 彼得 对他 说:「以尼雅,耶稣 基督 医好 你了,起来! 收拾 你的褥子。」他就 立刻 起来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, ' 凡 住 吕大 和 沙仑  的人都看见 了他, 就归服 主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, ' 在 约帕 有 一个 女徒,名叫 大比大, 翻希腊话 就是 多加(就是羚羊的意思);她 广行 善事, 多施 赒济。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, ' 当时,她患病 而死, 有人 把她 洗了,停 在 楼上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, ' 吕大 原与约帕 相近;门徒 听见 彼得 在 那里,就打发 两个 人 去见 他,央求他说:「快 到 我们那里去,不要 耽延。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, '彼得 就 起身 和他们 同去;到了,便有人领 他上 楼。 众 寡妇 都站在 彼得 旁边哭, 拿 多加 与 她们 同在 时 所做 的里衣 外衣给他看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, ' 彼得 叫 她们 都出去,就 跪下 祷告, 转身 对著 死人 说:「大比大,起来!」她 就 睁开  眼睛, 见了 彼得,便坐起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, ' 彼得 伸手 扶她 起来, 叫 众圣徒 和 寡妇进去,把多加活活地 交 给他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, ' 这事 传遍了 约帕,就 有许多人 信了 主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, '此后,彼得在 约帕 一个 硝皮匠 西门 的家里住了 多 日。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, ' 在 凯撒利亚 有一个 人,名叫 哥尼流,是「意大利 营」的百夫长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, '他是个虔诚人, 他 和 全 家 都敬畏 神,多多 赒济 百姓, 常常 祷告 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, '有一天,约 在 申初,他在 异象 中明明 看见 神 的一个使者 进去,到 他那里, 说:「哥尼流。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, ' 哥尼流定睛看 他, 惊怕 说:「主啊,什么事呢?」 天使 说:「你 的祷告 和 你 的赒济 达到 神 面前,已蒙 记念了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, ' 现在 你当打发 人 往 约帕去, 请 那 称呼 彼得 的西门来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, '他 住 在海边 一个 硝皮匠 西门的家里, 房子 在 海边上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, ' 向他 说话 的天使 去后,哥尼流叫了 两个 家人 和 常伺候 他 的一个虔诚 兵来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, ' 把这 事都述说 给他们听,就打发 他们 往 约帕去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, ' 第二天,他们 行路 将近 那城。彼得 约在 午正,上 房顶 去祷告, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, ' 觉得 饿了, 想要 吃。 那家的人 正预备饭的时候, 彼得 魂游象外, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, ' 看见 天 开 了, 有一 物 降下,好像 一块大 布,系著四 角,缒 在 地上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, ' 里面 有 地 上各样 四足的走兽 和 昆虫,并 天 上的飞鸟; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, '又 有 声音 向 他说:「彼得,起来,宰了 吃!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, '彼得 却 说:「主啊,这是不可的! 凡 俗物 和 不洁净的物,我从来没有 吃过。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, ' 第二次 有声音 向 他说:「 神 所 洁净的,你 不可 当作俗物。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, ' 这样 一连 三次, 那物 随即 收回 天上去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, ' 彼得 心里 正在 猜疑之间,不知所 看见 的异象 是 什么意思。 哥尼流 所差来 的人 已经访问 到西门 的家,站 在 门外, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, ' 喊著 问:「 有 称呼 彼得 的西门 住 在这里没有?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, ' 彼得 还思想 那异象的时候,圣灵 向他 说:「 有三个 人 来找 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, ' 起来,下去, 和 他们 同往,不要 疑惑,因为 是我 差 他们来的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, '于 是 彼得 下去 见 那些 人,说:「 我 就是 你们所 找的人。你们来 是为 什么 缘故?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, ' 他们说:「百夫长 哥尼流 是个义 人, 敬畏 神, 为 犹太 通国 所称赞。他蒙 一位圣 天使 指示,叫他请 你 到 他 家里去, 听 你的 话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, ' 彼得就请他们 进去,住了一宿。 次日,起身 和 他们同去,还有 约帕 的几个 弟兄 同著他 去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, '又 次日,他们进入 凯撒利亚, 哥尼流 已经请了 他 的亲属 密 友 等候 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, ' 彼得 一进去,哥尼流 就迎接 他,俯伏 在 他脚 前拜他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, ' 彼得 却拉 他,说:「你起来,我 也 是 人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, ' 彼得和他 说著话 进去, 见 有好些人 在那里聚集, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, '就 对 他们 说:「你们 知道,犹太 人 和别国的人 亲近 来往 本是 不合例的,但 神 已经指示 我,无论什么人 都不可 看作 俗 而 不洁净的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, '所以 我被请的时候,就不推辞 而来。现在 请问:你们叫 我 来有什么 意思呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, ' 哥尼流 说:「前 四 天, 这个 时候,我 在 家 中 守著申初 的祷告, 忽然有一个人 穿著 光明的 衣裳,站 在我 面前, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, ' 说:『哥尼流,你的 祷告 已蒙垂听, 你的 赒济达到 神 面前 已蒙记念了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, ' 你当打发 人往 约帕去, 请 那 称呼 彼得 的西门来,他 住 在 海 边 一个硝皮匠 西门 的家里。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, '所以 我立时 打发人 去请 你。 你 来了 很好; 现今 我们 都在 神 面前,要听 主 所吩咐 你 的一切话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, '彼得 就 开  口 说:「我真 看出 神 是 不 偏待人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, '原来,各 国 中 那敬畏 主、 行 义 的人都为 主 所悦纳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, '神藉 借著 耶稣 基督(他 是 万有 的主)传 和平的福音,将 这 道 赐 给以色列人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, ' 这话 在约翰 宣传 洗礼 以后,从 加利利 起,传 遍了 犹太。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, '神 怎样 以圣 灵 和 能力 膏 拿撒勒 人耶稣,这都是你们知道的。他 周流四方,行善事, 医好 凡 被 魔鬼 压制的人,因为 神 与 他 同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, '他 在 犹太人 之地,并 耶路撒冷 所 行 的一切事, 有我们 作见证。他们竟 把他 挂 在 木头 上杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, ' 第三 日, 神 叫他 复活, 显现出来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, '不是 显现给众人看,乃是 显现给 神 预先所拣选 为他作见证的人看,就是我们 这些 在他 从 死 里复活 以后 和他 同吃 同喝的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, ' 他吩咐 我们 传道 给众人, 证明 他 是 神 所立定的,要作审判 活人、 死人的主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, '众 先知 也为他 作见证说:『凡 信 他 的人必因 他 的名 得蒙 赦 罪。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, '彼得 还 说 这 话的时候,圣 灵 降 在 一切 听 道的人身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, ' 那些 奉割礼、和彼得 同来 的 信徒, 见圣 灵 的恩赐 也 浇 在 外邦人身上,就都希奇; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, '因 听见 他们 说 方言, 称赞 神为大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, '于 是 彼得 说:「这些人 既受 了圣 灵,与 我们 一样, 谁 能 禁止 用水 给他们 施洗呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, '就 吩咐 奉 耶稣 基督 的名 给他们 施洗。他们又 请 彼得 住 了几天。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, ' 使徒 和 在 犹太 的众弟兄 听说 外邦人 也 领受了 神 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, ' 及至 彼得 上了 耶路撒冷,那些 奉割礼 的门徒和 他 争辩 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, '「 你进入 未受割礼 之人 的家和 他们 一同吃饭了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, '彼得 就 开 口 把这事挨次 给他们 讲解 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, '「我 在 约帕 城 里祷告的时候, 魂游象外,看见 异象,有一 物 降下,好像 一块大 布,系著四 角,从 天 缒下, 直 来到 我跟前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, '我定睛 观看, 见 内中有地上 四足的牲畜 和 野兽、 昆虫,并 天上 的飞鸟。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, ' 我且 听见 有声音 向我 说:『彼得,起来,宰了 吃!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, ' 我说:『主啊,这是不可的! 凡俗 而 不洁净的 物从来没有 入过 我的 口。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, ' 第二次,有声音 从 天上 说:『神 所 洁净的,你 不可 当作俗物。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, ' 这样 一连 三次,就 都 收回 天上去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, ' 正当那时,有三个 人 站 在 我们所 住 的 房门前,是从 凯撒利亚 差来 见 我的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, ' 圣灵 吩咐 我 和他们 同去,不要 疑惑(或译:不要分别等类)。同著 我 去的, 还有 这 六 位弟兄, 我们都进 了那人 的家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, '那人就 告诉 我们,他如何 看见 一位天使 站 在 他 屋里, 说:『你打发人 往 约帕去, 请 那称呼 彼得 的西门来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, '他 有话 告诉 你, 可以叫你 和 你 的全 家 得救。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, ' 我 一开  讲,圣 灵 便降 在 他们身上,正像 当初 降在 我们身上一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, '我就 想起 主 的话 说:『 约翰 是用水 施洗,但 你们 要受 圣 灵 的洗。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, ' 神 既然 给 他们 恩赐,像 在我们信 主 耶稣 基督 的时候给了我们一样;我 是 谁,能 拦阻 神呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, ' 众人听见 这话,就不言语了,只 归荣耀与 神,说:「这样看来, 神 也 赐恩 给外邦人,叫他们悔改 得 生命了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, ' 那些因 司提反 的事遭 患难 四散 的门徒直走 到 腓尼基 和 塞浦路斯,并 安提阿;他们不 向别人讲 道, 只 向犹太人讲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, '但 内中 有 塞浦路斯 和 古利奈 人,他们 到了 安提阿 也 向 希腊人 传讲 主 耶稣(有古卷:也向说希腊话的犹太人传讲主耶稣)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, ' 主 与 他们 同在,信 而归 主 的人 就 很多了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, ' 这风声 传 到 耶路撒冷 教会 人的耳中,他们就 打发 巴拿巴出去,走到 安提阿为止。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, '他 到了那里, 看见 神 所赐的恩 就欢喜, 劝勉 众人,立定 心志,恒久靠 主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, ' 这巴拿巴原是 个好 人, 被圣 灵 充满, 大有信心。于 是 有许多 人 归服 了 主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, '他又 往 大数 去找 扫罗, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, ' 找著了,就带 他到 安提阿去。 他们 足有 一 年 的工夫和 教会 一同聚集, 教训 了许多 人。 门徒 称为「基督徒」是从 安提阿 起首。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, ' 当 那些 日子,有几位先知 从 耶路撒冷 下 到 安提阿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, ' 内中 有一位,名叫 亚迦布,站起来,藉 借著 圣灵 指明 天下 将 有 大 饥荒。(这事 到 克劳第 年间果然有了。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, '于 是 门徒 定意 照 各人 的力量 捐钱,送去 供给住 在 犹太 的弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, '他们就 这样 行,把捐项托 讬 巴拿巴 和 扫罗 送 到 众长老那里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, ' 那 时,希律 王 下 手 苦害 教会 中几个人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, ' 用刀 杀了 约翰 的哥哥 雅各。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, ' 他见 犹太人 喜欢这事,又 去 捉拿 彼得。 那时正是 除酵 的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, '希律 拿了 彼得,收 在 监里,交付 四班 兵丁 看守,每班四个人,意思要 在 逾越节 后把他 提出来,当著百姓办他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, '于 是 彼得 被囚 在 监里; 教会 却 为 他 切切地 祷告 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, ' 希律 将要 提 他 出来的前 一夜,彼得 被两条 铁链 锁著, 睡 在 两个 兵丁当中;看守的人 也 在 门 外看守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, '忽然,有主 的一个使者 站在旁边, 屋 里 有光 照耀, 天使拍 彼得 的肋旁,拍醒 了他,说:「快快 起来!」那铁链 就 从 他 手 上脱落下来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, ' 天使 对 他 说:「束上带子, 穿上 鞋。」他就 那样 做。天使又 说:「披上 外衣, 跟著 我来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, '彼得就 出来 跟著他, 不 知道 天使 所做 是 真的,只 当 见了 异象。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, ' 过了 第一 层 第二 层监牢,就来 到 临 街 的铁 门,那 门自己 开 了。 他们 出来,走过 一条 街,天使 便 离开  他去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, ' 彼得 醒悟过来,说:「我现在 真 知道 主 差遣 他 的使者, 救 我 脱离 希律 的手 和 犹太 百姓 一切 所盼望的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, ' 想了一想,就往 那称呼 马可 的约翰、他母亲 马利亚 家 去,在那里 有好些人 聚集 祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, ' 彼得 敲 外门,有一个使女,名叫 罗大,出来 探听, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, ' 听得 是彼得 的声音,就 欢喜 的顾不得 开  门, 跑进去 告诉众人说:「彼得 站 在 门外。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, ' 他们 说:「你是疯了!」 使女极力地说:「真是他!」 他们说:「必是 他 的天使!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, ' 彼得 不住地 敲门。 他们开 了门,看见 他,就 甚惊奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, ' 彼得摆 手,不要他们 作声,就告诉 他们 主 怎样 领 他 出 监;又 说:「你们把这事 告诉 雅各 和 众弟兄。」于 是 出去,往 别 处 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, ' 到了 天亮, 兵丁 扰乱得很,不知道彼得 往哪里 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, ' 希律 找 他, 找 不著,就审问 看守的人,吩咐 把他们拉去杀了。后来 希律离开  犹太,下 凯撒利亚去,住在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, ' 希律 恼怒 泰尔、 西顿的人。 他们 那一带地方 是从 王 的地土得粮,因此就 托 讬了 王 的内侍臣 伯拉斯都的情, 一心 来 求 和。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, ' 希律 在所定的 日子,穿上 朝服,坐 在 位上, 对 他们 讲论一番。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, ' 百姓 喊著说:「这是 神 的声音, 不是 人的声音。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, '希律不 归 荣耀给 神,所以 主 的使者 立刻 罚 他, 他 被虫所咬,气就绝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, ' 神 的道 日见兴旺, 越发广传。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, ' 巴拿巴 和 扫罗 办完了 他们供给的事,就从 耶路撒冷 回来,带著 称呼 马可 的约翰同去。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, ' 在 安提阿 的 教会中,有 几位先知 和 教师,就是 巴拿巴 和 称呼 尼结 的西面、 古利奈人 路求,与 分封之王 希律 同养的 马念,并 扫罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, ' 他们 事奉 主、 禁食的时候,圣 灵 说:「 要为我 分派 巴拿巴 和 扫罗,去 做我召 他们 所做 的工。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, '于 是 禁食 祷告, 按 手 在他们头上,就打发他们去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, ' 他们 既被 圣 灵 差遣,就下 到 西流基, 从那里 坐船 往 塞浦路斯去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, ' 到了 撒拉米,就在 犹太人 各会堂 里传讲 神 的道, 也 有 约翰 作他们的帮手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, ' 经过 全 岛,直到 帕弗,在那里遇见 一个 有法术、假充先知 的犹太人, 名叫巴•耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, '这人 常和 方伯 士求•保罗 同在。士求•保罗是个通达 人,他 请了 巴拿巴 和 扫罗来,要 听 神 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, '只是 那行法术 的以吕马( 这名 翻出来就是行法术的意思)敌挡 使徒,要叫 方伯 不信 真道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, ' 扫罗 又 名保罗,被圣 灵 充满,定睛看 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, '说:「 你这充满 各样 诡诈 奸恶,魔鬼 的儿子,众 善 的仇敌,你混乱 主 的正 道 还不 止住吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, ' 现在 主 的手 加在 你身上, 你要 瞎眼,暂且 不 见 日光。」 他的眼睛立刻 昏蒙 黑暗, 四下里 求 人拉著手领他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, ' 方伯 看见 所做的事,很希奇 主 的道,就信了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, ' 保罗 和他的同人从 帕弗 开 船,来 到 旁非利亚 的别加,约翰 就 离开  他们,回 耶路撒冷去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, ' 他们 离了 别加 往前行,来 到 彼西底 的安提阿, 在安息 日 进 会堂 坐下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, ' 读 完了 律法 和 先知的书,管会堂的 叫人过去,对 他们 说:「二位兄台,若 有 什么 劝勉 众人的 话,请说。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, '保罗 就 站起来, 举 手,说:「以色列 人 和 一切敬畏 神的人,请听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, '这 以色列 民的 神 拣选 了我们的 祖宗, 当 民寄居 埃及 的时候抬举 他们, 用 大能的 手 领 他们出来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, '又 在 旷野 容忍(或译:抚养)他们,约有 四十年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, '既 灭了 迦南 地 七 族的人,就把那地 分 给他们为业; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, ' 此后 给 他们设立士师,约有 四百 五十 年,直到 先知 撒母耳的时候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, '后来 他们求 一个王, 神 就 将 便雅悯 支派 中基士 的儿子 扫罗,给 他们 作王四十 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, '既 废了 扫罗,就选立 大卫 作 他们 的王,又 为他 作见证 说:『我寻得 耶西 的儿子大卫,他是合 我 心意 的人, 凡事 要遵行 我的 旨意。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, '从 这人 的后裔中, 神 已经照著 所应许的,为以色列人 立了 一位救主,就是耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, '在 他没有出来以先,约翰 向以色列 众 民 宣讲 悔改 的洗礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, ' 约翰 将行尽 他的程途 说:『你们以为 我 是 谁?我 不 是基督;只是 有一位在 我 以后来的,我解 他 脚 上的鞋 带也是 不 配的。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, '「 弟兄们,亚伯拉罕 的子孙 和 你们 中间 敬畏 神的人哪,这 救世 的道 是传 给我们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, ' 耶路撒冷 居住 的人和 他们 的官长,因为不认识 基督,也 不明白 每安息日 所读 众先知 的书,就把基督定了死罪,正应了先知的预言; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, '虽然 查 不 出他有当 死的罪来,还是求 彼拉多 杀 他; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, '既 成就 了经上指著 他 所记 的一切话,就把他从 木头 上取下来,放 在 坟墓里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, '神 却 叫他 从 死 里复活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, '那从 加利利 同 他 上 耶路撒冷 的人 多 日 看见 他,这些人 如今 在 民间 是 他 的见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, '我们 也 报好信息 给你们,就是那 应许 祖宗的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, ' 神 已经向我们 这作 儿女 的应验,叫耶稣 复活了。 正如 诗篇 第二 篇上记著说:你 是 我的 儿子,我 今日 生 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, ' 论到 神叫他 从 死 里复活,不再 归 于  朽坏,就这样 说: 我必将所应许大卫 那圣洁、可靠的 恩典赐 给你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, ' 又有一 篇上 说:你必不 叫 你的 圣者 见 朽坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, '「大卫在世的时候遵行了 神的旨意,就睡了(或译:大卫按 神 的旨意 服事 了他 那一世的人,就睡了), 归 到 他 祖宗那里, 已见 朽坏; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, '惟独 神 所复活的,他 并未 见 朽坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, '所以,弟兄们,你们 当 晓得: 赦 罪 的道是由 这人 传 给你们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, ' 你们靠 摩西 的律法,在 一切 不得 称义 的事上信 靠 这人,就都 得称义了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, '所以,你们务要小心,免得 先知书 上所说 的临到你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, '主说:你们这轻慢的人 要观看, 要惊奇, 要灭亡;因为 在 你们的 时候,我 行 一件事,虽 有人 告诉 你们,你们总是不 信。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, ' 他们 出会堂的时候,众人请 他们到 下 安息日 再讲 这 话 给他们听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, ' 散会以后,犹太人 和 敬虔 进犹太教的人 多 有跟从 保罗、 巴拿巴的。二人 对他们 讲道,劝 他们 务要恒久在 神 的恩中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, ' 到下安息日,合 城 的人几乎 都来聚集,要听 神 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, '但 犹太人 看见 人这样多,就满心 嫉妒, 硬驳 保罗 所说的话,并且毁谤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, '保罗 和 巴拿巴 放胆 说:「 神 的道 先 讲 给你们 原是 应当的;只因 你们弃绝 这道, 断定 自己 不 配得 永 生, 我们就转向 外邦人去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, '因为 主 曾这样 吩咐 我们说:我已经立 你 作 外邦人的 光,叫你 施行 救恩,直到 地 极。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, ' 外邦人 听见这话,就欢喜了, 赞美 神 的道; 凡 预定 得 永 生 的人都信了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, '于 是 主 的道 传 遍了 那一带 地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, '但 犹太人 挑唆 虔敬、尊贵的 妇女 和 城 内有名望的人, 逼迫 保罗、 巴拿巴, 将他们 赶出 境外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, ' 二人对著 众人 跺下 脚 上的尘土,就往 以哥念 去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, ' 门徒 满心喜乐,又 被圣 灵 充满。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, ' 二人 在 以哥念 同 进 犹太人 的会堂, 在那里 讲的,叫 犹太人 和 希腊人 信 的很多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, '但 那不顺从的 犹太人 耸动 外邦人, 叫他们心里 恼恨 弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, ' 二人在那里住 了多 日,倚靠 主 放胆讲道; 主藉 借 他们 的手 施 行神迹 奇事,证明 他 的恩 道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, ' 城 里的众人 就分了党, 有 附从 犹太人的, 有附从 使徒的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, ' 那时, 外邦人 和 犹太人,并 他们 的官长, 一齐拥上来,要凌辱使徒, 用石头打 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, '使徒知道了,就逃 往 吕高尼 的路司得、 特庇 两个城 和 周围地方去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, '在那里 传福音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, ' 路司得 城里坐著 一个 两脚 无力 的人,生来 是瘸腿的, 从来没有 走过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, '他 听 保罗 讲道,保罗 定睛看 他, 见 他有 信心,可得痊愈, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, '就大 声 说:「你起来, 两脚 站直!」那人就 跳起来,而且 行走。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, ' 众人 看见 保罗 所做的事,就用吕高尼的话 大 声 说:「有 神 藉 借著 人形 降临 在 我们中间了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, '于 是 称 巴拿巴 为宙斯, 称保罗 为希耳米,因为 他 说话 领首。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, ' 有 城 外 宙斯 庙的祭司 牵著 牛, 拿著花圈,来到 门前,要 同 众人 向使徒献祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, ' 巴拿巴、 保罗 二使徒 听见,就撕开  衣裳,跳进 众人中间,喊著 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, '「诸君,为什么 做 这事呢?我们 也 是 人,性情 和你们一样。我们传福音 给你们,是叫你们离弃 这些 虚妄,归向 那 创造 天、 地、 海,和 其中 万物 的永生 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, '他 在 从前的 世代,任凭 万 国 各行 其 道; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, '然而 为自己 未尝不 显出 证据来,就如常施恩惠, 从天 降雨, 赏赐 丰年,叫你们饮食 饱足, 满心 喜乐。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, ' 二人说了 这些话,仅仅地 拦住 众人 不 献祭 与他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, '但 有些犹太人 从 安提阿 和 以哥念 来, 挑唆 众人,就 用石头打 保罗,以为 他 是死了,便拖 到城 外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, ' 门徒 正围著 他,他就起来,走 进 城去。 第二天,同 巴拿巴 往 特庇 去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, ' 对那 城 里的人传了福音, 使好些人 作门徒,就回 路司得、 以哥念、 安提阿去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, '坚固 门徒 的心,劝 他们恒守 所信的道;又说:「 我们 进 入 神 的国,必须 经历 许多 艰难。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, ' 二人在各 教会 中 选立 了长老,又 禁食 祷告,就把他们 交托 讬 所信 的主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, ' 二人经过 彼西底,来 到 旁非利亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, ' 在 别加 讲了 道,就下 亚大利去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, '从那里 坐船,往 安提阿去。当初,他们 被众人所托 讬、蒙 神 之恩、要 办 现在所 做之工,就是在这地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, ' 到了那里, 聚集 了会众,就述说 神 藉 借 他们 所行 的一切事,并 神怎样为外邦人 开  了信道 的门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, '二人就 在那里同 门徒 住 了多 日。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, ' 有几个人 从 犹太 下来,教训 弟兄们说:「 你们若不 按摩西 的规条 受割礼,不 能 得救。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, ' 保罗、 巴拿巴 与 他们 大大地 纷争 辩论;众门徒就定规,叫保罗、 巴拿巴 和 本会 中 几个人,为 所辩论的,上 耶路撒冷 去见 使徒 和 长老。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, '于 是 教会 送他们起行。他们经过 腓尼基、 撒马利亚,随处传说 外邦人 归主的事, 叫 众 弟兄 都甚 欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, ' 到了 耶路撒冷, 教会 和 使徒 并 长老 都接待他们,他们就 述说 神 同 他们 所行 的一切事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, ' 惟有几个 信徒,是法利赛 教门的人,起来 说:「 必须 给外邦人行割礼, 吩咐 他们 遵守 摩西的 律法。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, ' 使徒 和 长老 聚会 商议 这 事; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, ' 辩论 已经多了,彼得 就起来, 说:「诸位 弟兄,你们 知道 神 早已 在 你们 中间拣选了我,叫外邦人 从 我 口 中得听 福音 之道,而且 相信。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, '知道人心的 神 也 为他们作了见证,赐 圣 灵 给他们,正如 给我们 一样; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, '又 藉 借著信 洁净 了他们 的心,并不 分 他们 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, ' 现在 为什么 试探 神,要把 我们 祖宗 和我们 所不 能 负 的轭 放 在 门徒 的颈项上呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, '我们得救 乃是 因 主 耶稣 的恩,和他们 一样,这是我们所信的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, ' 众 人 都默默无声, 听 巴拿巴 和 保罗 述说 神 藉 借 他们 在 外邦人 中所行 的 神迹 奇事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, ' 他们 住了声,雅各 就 说:「诸位 弟兄,请听 我的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, '方才西门 述说 神 当初 怎样 眷顾外邦人,从 他们 中间选取 百姓 归于 自己 的名下; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, '众先知 的话 也 与这 意思相合。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, '正如 经上所写的:此后,我要回来, 重新修造 大卫 倒塌 的帐幕, 把那破坏 的重新修造 建立起来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, '叫 余 馀剩的 人,就是 凡 称为 我 名 下 的外邦人,都寻求 主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, '这话是从 创世 以来 显明 这 事的主 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, '「所以 据我 的意见,不可 难为 那 归服 神 的 外邦人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, '只要 写信,吩咐他们 禁戒 偶像 的污秽 和 奸淫,并 勒死的 牲畜和 血。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, '因为 从 古以来,摩西 的书在各 城 有 人传讲,每逢 安息日,在 会堂 里诵读。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, '那时,使徒 和 长老 并 全 教会 定意 从 他们 中间拣选 人,差 他们和 保罗、 巴拿巴 同往 安提阿去;所拣选的就是称呼 巴撒巴 的犹大 和 西拉。这两个人在 弟兄 中是作首领的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, '于 是写信 交付 他们,内中说:「使徒 和 作长老 的弟兄 们问 安提阿、 叙利亚、 基利家 外邦 众弟兄的安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, ' 我们听说, 有几个 人从 我们 这里出去,用言语 搅扰 你们,惑乱 你们的 心。(有古卷加:你们必须受割礼,守摩西的律法。)其实我们并没有 吩咐 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, '所以,我们 同心 定意,拣选 几个人,差 他们同 我们 所亲爱的 巴拿巴 和 保罗 往 你们那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, '这二人 是为 我 主 耶稣 基督 的名 不顾 性命的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, ' 我们就差了 犹大 和 西拉,他们 也 要亲口 诉说 这些事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, '因为 圣 灵 和 我们 定意 不 将别的 重担 放 在你们身上,惟有 几件事 是不可少的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, '就是禁戒 祭偶像的物 和 血,并 勒死的 牲畜和 奸淫。这几件你们若能自己 禁戒 不犯 就 好了。愿 你们平安!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, ' 他们既奉了差遣,就下 安提阿去, 聚集 众人,交付 书信。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, ' 众人念了,因为 信上安慰 的话就欢喜了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, ' 犹大 和 西拉 也 是 先知,就用 许多 话 劝勉 弟兄, 坚固他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, ' 住 了些日子, 弟兄 们打发 他们平平安安地 回到 差遣 他们的人那里去。(有古卷加: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, '惟有 西拉 定意 仍住 在那里。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, '但 保罗 和 巴拿巴 仍住 在 安提阿, 和 许多 别人 一同教训人, 传 主 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, ' 过了 些 日子,保罗 对 巴拿巴 说:「我们可以 回到 从前宣传 主 道 的 各 城,看望 弟兄 们景况 如何。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, ' 巴拿巴 有意 要带 称呼 马可 的约翰同去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, '但 保罗 因为马可 从前在 旁非利亚 离开  他们, 不 和他们 同去 做工,就以为 不可 带 他去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, '于 是 二人 起了 争论,甚至 彼此 分开 。 巴拿巴 带著 马可,坐船 往 塞浦路斯去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, ' 保罗 拣选 了西拉,也出去,蒙 弟兄 们把他交 于 主 的恩中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, '他就 走遍 叙利亚、 基利家,坚固 众教会。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, ' 保罗来 到 特庇,又 到 路司得。 在那里 有 一个门徒,名 叫提摩太,是 信 主之犹太 妇人 的儿子,他父亲 却 是希腊人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, ' 路司得 和 以哥念 的弟兄 都称赞他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, '保罗 要 带他 同 去,只 因 那些 地方 的犹太人 都知道 他 父亲 是 希腊人,就 给他 行了割礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, ' 他们经过 各城,把 耶路撒冷 使徒 和 长老 所定 的条规 交 给门徒 遵守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, '于 是 众教会 信心 越发坚固, 人数 天天 加增。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, ' 圣 灵 既然禁止 他们在 亚细亚 讲 道,他们就 经过 弗吕家、 加拉太 一带地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, ' 到了 每西亚的边界,他们想要 往 庇推尼 去,耶稣 的灵 却 不 许。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, '他们就 越过 每西亚,下 到 特罗亚去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, ' 在 夜间 有异象 现 与保罗。有一个 马其顿 人 站著 求 他 说:「请你过 到 马其顿 来帮助 我们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, ' 保罗既看见 这异象,我们随即 想要 往 马其顿 去,以为 神 召 我们 传福音 给那里的人听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, '于 是 从 特罗亚 开 船,一直行 到 撒摩特喇, 第二天 到了 尼亚坡里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, '从那里 来到 腓立比, 就是 马其顿 这一方 的头一个 城,也是罗马的驻防城。 我们 在 这 城 里住 了几 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, ' 当安息 日,我们出 城门,到了 河边,知道 那里 有 一个祷告的地方,我们就 坐下 对那聚会 的妇女 讲道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, ' 有一个 卖紫色布疋的 妇人,名叫 吕底亚,是推雅推喇 城的人,素来敬拜 神。她听见了,主 就开 导 她的 心,叫她留心听 保罗 所讲的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, ' 她和 她 一家 既领了洗,便求 我们说:「你们若 以为 我 是 真信 主的(或译:你们若以为我是忠心事主的),请到 我 家 里来 住」;于 是 强留 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, '后来,我们 往 那祷告的地方 去。有一个 使女 迎著面 来,她 被巫 鬼 所附,用法术,叫 她 主人 们大 得财利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, '她 跟随 保罗 和 我们,喊著 说:「这些 人 是 至高 神 的仆人, 对你们 传说 救人 的道。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, ' 她 一连多 日 这样喊叫,保罗 就 心中厌烦,转身 对那鬼 说:「我奉 耶稣 基督 的名,吩咐 你 从 她 身上出来!」那鬼当时 就 出来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, ' 使女 的主人 们见 得利 的指望 没有了,便揪住 保罗 和 西拉,拉 他们到 市 上去见 首领; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, '又 带 到官长 面前说:「这些 人 原是 犹太人,竟骚扰 我们的 城, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, ' 传 我们 罗马人 所不 可 受 不可 行 的规矩。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, '众人 就 一同起来 攻击 他们。 官长 吩咐 剥 了他们 的衣裳,用棍打; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, ' 打 了 许多 棍,便将他们下 在 监里,嘱咐 禁卒 严紧 看守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, '禁卒 领 了这样 的命,就把他们 下 在 内 监里, 两脚 上了 木狗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, ' 约 在半夜,保罗 和 西拉 祷告,唱诗赞美 神,众囚犯 也 侧耳而听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, ' 忽然,地大 震动,甚至 监牢 的地基 都摇动了, 监门 立刻 全 开 ,众 囚犯的锁链 也 都松开 了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, ' 禁卒 一 醒, 看见 监 门 全开 ,以为 囚犯 已经逃走,就拔 刀 要 自 杀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, ' 保罗 大 声 呼叫 说:「不要 伤害 自己! 我们都 在 这里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, ' 禁卒叫 人拿灯来,就跳进去, 战 战 兢兢地 俯伏 在保罗、 西拉面前; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, '又 领 他们 出来,说:「二位先生,我 当 怎样 行 才可以 得救?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, ' 他们说:「当信 主 耶稣, 你 和 你 一家 都必得救。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, '他们就 把主 的道 讲 给他 和 他 全 家的人听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, '当夜,就 在 那 时候,禁卒把他们 带去,洗 他们的伤; 他 和 属乎 他 的人立时 都 受了洗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, '于 是 禁卒领 他们 上 自己家里去,给他们摆上 饭。 他和全家,因为信了 神,都很喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, ' 到了 天亮,官长 打发 差役来,说:「释放 那 两个人吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, '禁卒 就 把这 话 告诉 保罗说:「 官长 打发人 来叫 释放你们,如今 可以 出监,平平安安地 去吧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, '保罗 却 说:「我们是 罗马 人,并没有定罪,他们就在众人面前 打 了我们,又把我们下 在 监里, 现在 要私下 撵 我们出去吗?这是 不行的。 叫他们 自己来 领 我们出去吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, ' 差役 把这 话 回禀 官长。 官长听见 他们是 罗马人,就害怕了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, '于 是 来 劝 他们, 领他们出来,请 他们离开  那城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, ' 二人出了 监,往 吕底亚 家里去, 见 了弟兄们,劝慰他们一番,就 走了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, ' 保罗和西拉经过 暗妃坡里、 亚波罗尼亚,来 到 帖撒罗尼迦,在那里 有 犹太人 的会堂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, ' 保罗 照 他素常的规矩 进去, 一连三个安息日,本著 圣经 与他们 辩论, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, '讲解 陈明 基督 必须 受害, 从 死 里复活;又 说:「 我 所传 与你们 的这位 耶稣 就是 基督。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, ' 他们 中间 有些人 听了劝,就 附从 保罗 和 西拉,并 有许多 虔敬 的希腊人,尊贵的 妇女 也 不 少。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, '但 那不信 的犹太人 心里嫉妒, 招聚 了些 市井 匪类, 搭伙 夥成群,耸动 合城 的人 闯进 耶孙 的家,要将保罗、西拉 带 到 百姓那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, ' 找 不著 他们,就把耶孙 和 几个 弟兄 拉 到 地方官那里,喊叫 说:「那 搅乱 天下 的也 到 这里来了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, '耶孙 收留 他们。 这些人 都 违背 凯撒 的命令,说 另有 一个 王 耶稣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, ' 众人 和 地方官 听见 这话,就惊慌了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, '于 是 取 了 耶孙 和 其余 馀之人 的保状,就释放 了他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, ' 弟兄 们随即 在 夜间 打发 保罗 和 西拉 往 庇哩亚去。二人 到了,就进 入 犹太人 的会堂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, ' 这地方的人 贤于  帖撒罗尼迦的人, 甘心 领受 这道,天天 考查 圣经,要晓得这 道是与不是。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, '所以 他们 中间 多 有相信的,又有 希腊 尊贵的 妇女,男子 也 不 少。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, '但 帖撒罗尼迦 的犹太人 知道 保罗 又 在 庇哩亚 传 神 的道,也就往那里 去,耸动 搅扰 众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, ' 当时 弟兄 们便 打发 保罗 往 海边 去, 西拉 和 提摩太 仍住 在庇哩亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, ' 送 保罗 的人带 他到 了雅典,既 领 了保罗的命, 叫 西拉 和 提摩太 速速 到 他 这里来,就回去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, ' 保罗 在 雅典 等候 他们的时候,看见 满城 都是 偶像, 就 心里 著急; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, '于 是 在 会堂 里与犹太人 和 虔敬的人,并 每 日 在 市 上 所遇见的人,辩论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, ' 还有 伊壁鸠鲁 和 斯多亚 两门的学士,与他 争论。 有的 说:「这 胡言乱语的 要 说 什么?」有的说:「他似乎 是 传说 外邦 鬼神的。」这话是因 保罗传讲 耶稣 与 复活的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, '他们就 把 他 带 到亚略•巴古,说:「 你 所讲 的这 新 道,我们也可以 知道吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, '因为 你有些 奇怪的事 传 到 我们 耳中, 我们愿 意 知道 这些事 是什么 意思。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, '( 雅典人 和 住在那里 的客人 都 不 顾 别的事,只将 新闻 说说 听听。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, ' 保罗 站 在亚略•巴古 当中,说:「众位 雅典人哪,我看 你们 凡事 很敬畏鬼神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, ' 我游行的时候, 观看 你们 所敬拜的, 遇见 一座坛,上面 写著『未识 之神』。 你们所不认识 而敬拜 的,我 现在 告诉 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, '创造 宇宙 和 其中 万物的 神, 既是 天 地 的主,就不 住 人手 所造的殿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, '也不 用 人 手 服事,好像缺少 什么;自己 倒将生命、 气息、 万物,赐给 万人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, ' 他从 一本(本:有古卷是血脉)造出 万 族 的人,住 在 全 地 上,并且预先 定准 他们的 年限 和 所住 的疆界, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, '要叫他们寻求 神,或者 可以 揣摩 而 得,其实 他离 我们 各 人 不 远; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, ' 我们生活、 动作、 存留,都在乎 他。就 如 你们 作诗的,有人说:『 我们也 是 他所生的。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, '我们既 是 神 所生的,就不 当 以为 神的神性 像 人 用手艺、 心思 所雕刻 的金、 银、 石。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, ' 世人蒙昧无知 的时候, 神 并不监察,如今 却吩咐 各处的 人 都 要悔改。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, '因为 他已经定了 日子, 要 藉 借著 他所设立 的人 按 公义 审判 天下,并且叫他 从 死里 复活,给 万人 作可信的凭据。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, ' 众人听见 从死里 复活的话,就有 讥诮他的;又 有人说:「我们再 听 你 讲 这个吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, '于 是 保罗 从 他们 当中 出去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, '但 有几个 人 贴近 他,信了主, 其中有亚略•巴古的官 丢尼修,并 一个妇人,名叫 大马哩,还有 别人 一同信从。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, '这事 以后,保罗离了 雅典,来 到 哥林多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, ' 遇见 一个 犹太人,名叫 亚居拉,他生 在本都;因为 革老丢 命 犹太人 都 离开  罗马,新近 带著 妻 百基拉,从 意大利 来。保罗就投奔了 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, ' 他们本是 制造帐棚 为业。保罗因 与他们同业,就和 他们 同住 做工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, ' 每 逢 安息日,保罗在 会堂 里辩论, 劝化 犹太人 和 希腊人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, ' 西拉 和 提摩太 从 马其顿 来 的时候,保罗 为道 迫切,向犹太人 证明 耶稣 是 基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, '他们 既 抗拒、 毁谤,保罗就抖著 衣裳, 说:「你们的罪(原文是血)归到 你们 自己头上,与我无干(原文是我 却干净)。从 今以后,我要往 外邦人 那里去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, '于 是 离开  那里,到了 一个人 的家中;这人名叫 提多 犹士都,是敬拜 神的,他的 家 靠近 会堂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, ' 管会堂的 基利司布 和 全 家 都信了 主,还有 许多 哥林多人 听了,就相信 受洗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, ' 夜 间,主 在 异象 中对保罗 说:「不要 怕,只管 讲, 不要 闭口, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, ' 有我 与 你 同在, 必没有人 下手 害 你,因为 在 这 城里 我 有 许多的 百姓。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, ' 保罗在那里住了 一年 零 六个 月,将 神 的道 教训 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, ' 到迦流 作 亚该亚 方伯的时候,犹太人 同心 起来攻击 保罗, 拉 他 到 公堂, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, '说:「 这个人 劝 人 不按著 律法 敬拜 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, ' 保罗 刚要 开  口,迦流 就对 犹太人 说:「 你们这些犹太人!如果 是 为冤枉 或 奸恶 的事,我理当 耐性听 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, '但所争论的,若 是 关乎 言语、 名目,和 你们的 律法,你们自己去办吧!这样的事 我 不 愿 意 审问」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, '就 把他们 撵 出 公堂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, ' 众人 便揪住 管会堂的 所提尼,在堂 前 打他。 这些事 迦流 都不 管。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, '保罗 又 住了 多日,就辞别 了弟兄,坐船 往 叙利亚去; 百基拉、 亚居拉 和 他同去。他因为 许过 愿 ,就在 坚革哩 剪了 头发。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, ' 到了 以弗所,保罗就 把他们留 在那里, 自己 进了 会堂,和犹太人 辩论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, ' 众人 请 他多 住 些日子,他却不 允, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, '就 辞别他们,说:「 神 若许我,我还要 回到 你们这里」;于 是 开 船 离了 以弗所。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, ' 在 凯撒利亚 下了船,就上 耶路撒冷去 问 教会安,随后下 安提阿 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, ' 住了 些 日子,又离开 那里,挨次 经过 加拉太 和 弗吕家 地方,坚固 众 门徒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, ' 有一个 犹太人,名叫 亚波罗,来 到 以弗所。他生 在亚历山大,是有学问(或译:口才)的,最能 讲解圣经。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, '这人 已经在主 的道 上受了 教训, 心里 火热,将耶稣 的事 详细 讲论 教训人;只是他单 晓得 约翰 的洗礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, ' 他 在 会堂里 放胆讲道; 百基拉、 亚居拉 听见,就接 他来,将 神 的道 给他 讲解 更加详细。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, ' 他 想要 往 亚该亚 去,弟兄们就勉励他,并写信请门徒接待他(或译:弟兄们 就写信 劝 门徒 接待 他)。他 到了那里,多 帮助 那蒙 恩 信主的人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, ' 在众人面前 极有能力 驳倒 犹太人,引 圣经 证明 耶稣 是 基督。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, ' 亚波罗 在 哥林多的时候,保罗 经过 了上边 一带地方,就来 到 以弗所; 在那里遇见 几个 门徒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, ' 问 他们 说:「你们信 的时候受了 圣 灵 没有?」 他们回答说:「没有,也未曾 听见 有 圣 灵赐下来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, ' 保罗说:「这样,你们受 的是什么 洗呢?」 他们说:「 是约翰 的洗。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, ' 保罗 说:「约翰 所行 的是悔改 的洗,告诉 百姓 当信 那在他 以后 要来的, 就是 耶稣。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, ' 他们听见这话,就奉 主 耶稣 的名 受洗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, ' 保罗 按 手 在他们头上,圣 灵 便降 在 他们身上,他们就 说 方言,又 说预言(或译:又讲道)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, ' 一共 约 有 十二个 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, ' 保罗进 会堂,放胆讲道,一连 三 个月,辩论 神 国的事, 劝化众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, '后来,有些人 心里刚硬 不信,在众人 面前 毁谤 这道,保罗就离开  他们,也叫门徒 与他们分离,便在 推喇奴 的学房 天天 辩论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, ' 这样 有 两 年之久,叫 一切 住在 亚细亚的,无论是 犹太人,是 希腊人,都听见 主 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, ' 神 藉 借 保罗 的手 行了 些非常 的奇事; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, '甚至 有人从 保罗 身上 拿 手巾 或 围裙 放在 病人身上,病 就 退了,恶 鬼 也 出去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, '那时,有几个 游行各处、念咒赶鬼 的犹太人,向 那被恶 鬼 附 的人擅自 称 主 耶稣 的名,说:「我奉 保罗 所传 的耶稣 敕令 你们出来!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, ' 做 这事的,有 犹太 祭司长 士基瓦 的七个 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, ' 恶 鬼 回答 他们 说:「耶稣 我 认识,保罗 我也 知道。你们 却 是 谁呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, '恶 鬼 所附 的人 就跳 在 他们身上, 胜了 其中二人,制伏 他们,叫 他们赤著身子 受了伤,从 那 房子 里逃出去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, ' 凡 住在 以弗所的,无论是 犹太人, 是希腊人,都 知道 这事,也 都 惧怕;主 耶稣 的名 从此就 尊大了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, ' 那已经信的,多有人 来 承认 诉说 自己 所行的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, '平素行 邪术的,也 有许多人 把书 拿来,堆积在众人 面前 焚烧。 他们算计 书 价,便 知道 共合五万 块钱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, '主 的道 大大 兴旺,而且 得胜,就是这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, ' 这些事 完了,保罗 心 里 定意 经过 了马其顿、 亚该亚,就往 耶路撒冷 去;又说:「 我 到了 那里 以后, 也 必须 往罗马 去看看。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, '于 是 从帮助 他 的人中打发 提摩太、 以拉都 二 人往 马其顿去,自己 暂时 等 在 亚细亚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, ' 那 时,因为 这道 起 的扰乱 不 小。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, ' 有一个 银匠,名叫 底米丢,是制造 亚底米神 银 龛的,他使 这样手艺人 生意发达。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, '他聚集 他们和同行 的 工人, 说:「众位,你们知道 我们 是倚靠 这 生意 发财。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, '这 保罗 不但 在以弗所,也 几乎 在亚细亚 全地,引诱 迷惑 许多 人,说:『 人手 所做的,不 是 神。』这是 你们所 看见 所听见的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, '这样,不 独 我们 这 事业 被人藐视,就是 大 女神 亚底米 的庙 也要被人轻忽,连 亚细亚 全地 和 普天下 所敬拜 的 大女神 之威荣 也要 消灭了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, ' 众人听见,就 怒气填胸, 喊著 说:「大哉,以弗所人 的亚底米啊!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, ' 满城 都 轰动起来。 众人拿住 与保罗 同行 的马其顿人 该犹 和 亚里达古,齐心 拥 进 戏园里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, ' 保罗 想要 进去,到 百姓那里,门徒 却不 许 他去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, '还有 亚细亚几位 首领,是 保罗 的朋友,打发 人来 劝 他, 不要 冒险 到 戏园里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, ' 聚集的人 纷纷乱乱, 有 喊叫 这个的,有喊叫那个的; 大半 不 知道 是为什么 聚集。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, ' 有人把亚历山大 从 众人 中带出来,犹太人 推 他往前,亚历山大 就 摆 手,要 向百姓 分诉; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, '只因 他们认出 他是 犹太人,就大家 同 声 喊著说:「大哉!以弗所人 的亚底米啊。」如此约有 两 小时。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, ' 那城里的书记 安抚 了众人,就说:「以弗所 人哪,谁 不 知道 以弗所人 的城 是 看守 大 亚底米 的庙和 从宙斯那里落下来的像呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, ' 这事 既 是驳不倒的,你们 就当 安静, 不 可造次。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, ' 你们把这些 人 带来,他们并没有 偷窃庙中之物,也没有 谤讟 我们的 女神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, ' 若是 底米丢 和 他 同 行 的人有 控告 人 的事,自有放告的日子(或译:自有 公堂),也 有 方伯 可以彼此 对告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, ' 你们若 问 别的 事,就可以照 常例 聚集 断定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, ' 今日的 扰乱 本是 无 缘无故,我们难免 被查问。论到 这样 聚众,我们也说 不出 所以然 来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, ' 说了 这话,便叫众人 散去。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, ' 乱 定 之后,保罗 请 门徒来, 劝勉他们,就辞 别 起行,往 马其顿去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, ' 走遍了 那 一带地方, 用许多 话 劝勉 门徒(或译:众人),然后来 到 希腊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, ' 在那里住了 三 个月,将要 坐船 往 叙利亚去,犹太人 设 计 要害他,他就定 意 从 马其顿 回去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, ' 同 他到亚细亚去的,有庇哩亚人 毕罗斯 的儿子所巴特, 帖撒罗尼迦人 亚里达古 和 西公都,还 有特庇人 该犹,并 提摩太,又 有亚细亚人 推基古 和 特罗非摩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, ' 这些人 先走,在 特罗亚 等候 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, ' 过了 除酵 的日子,我们 从 腓立比 开 船, 五 天 到了 特罗亚,和他们相会,在那里 住了 七 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, ' 七日 的第一日,我们 聚会 擘 饼的时候,保罗 因为要 次日 起行,就 与他们 讲论,直 讲 到 半夜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, ' 我们 聚会 的那 座楼 上,有 好些 灯烛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, ' 有一个 少年人,名叫 犹推古,坐 在 窗台上,困倦 沉 睡。保罗 讲了 多时,少年人 睡 熟了,就从 三层楼 上掉 下去;扶起他来, 已经死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, ' 保罗 下去,伏在 他身上, 抱著他,说:「你们 不要发慌, 他 的灵魂 还在 身 上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, ' 保罗又上去, 擘 饼, 吃了, 谈论 许久,直到 天亮,这才 走了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, ' 有人把那童子 活活地 领来, 得的安慰 不 小。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, ' 我们 先上 船,开  往 亚朔去,意思要 在那里 接 保罗;因为 他是 这样 安排的,他自己 打算 要步行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, ' 他既在 亚朔 与我们 相会,我们就接他 上船,来 到 米推利尼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, '从那里 开 船,次 日到 了基阿 的对面;又 次日,在 撒摩 靠岸;又 次日,来 到 米利都。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, '乃因 保罗 早已定意 越过 以弗所,免得 在 亚细亚耽延, 他 急忙前走, 巴不 得 赶 五旬 节 能到 耶路撒冷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, ' 保罗从 米利都 打发 人往 以弗所去,请 教会 的长老来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, ' 他们 来了,保罗就说:「你们 知道,自 从 我 到 亚细亚 的日子 以来,在你们 中间 始终 为 人如何, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, '服事 主, 凡事 谦卑, 眼中流泪,又 因犹太人 的谋害, 经历 试炼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, '你们也知道,凡与你们 有益的,我没有一样 避讳 不 说的,或 在众人面前,或 在各 人家里,我都教导 你们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, '又对 犹太人 和 希腊人 证明 当向 神 悔改, 信 靠 我 主 耶稣基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, ' 现在 我 往 耶路撒冷 去,心甚迫切(原文是心 被捆绑),不 知道 在 那里 要遇见什么事; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, '但 知道 圣 灵 在 各城 里向我 指证,说 有 捆锁 与 患难 等待 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, '我却 不以性命 为念,也不 看 为宝贵,只要 行完 我 的路程, 成就我从 主 耶稣 所 领受 的职事,证明 神 恩惠 的福音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, '「 我素常 在你们 中间 来往,传讲 神国的道;如今我 晓得, 你们 以后都 不得再 见 我 的面了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, '所以 我 今 日 向你们 证明,你们中间无论何人死亡,罪不在我身上(原文是我于  众人 的血 是 洁净的)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, '因为 神 的 旨意,我并没有 一样避讳 不传给 你们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, '圣 灵 立 你们 作全群的监督,你们就当为自己 谨慎,也 为全 群谨慎,牧养 神 的教会,就是 他用 自己 血所买 来的(或译:救赎的)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, '我 知道, 我 去 之后 必有凶暴 的豺狼 进入 你们 中间,不 爱惜 羊群。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, '就是 你们中间,也必有人 起来 说 悖谬的话,要引诱 门徒 跟从 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, '所以 你们应当警醒,记念 我三年 之久昼 夜 不 住地 流泪、劝戒 你们各 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, ' 如今 我把你们 交托 讬 神 和 他 恩惠 的道;这道 能 建立你们, 叫 你们和 一切 成圣 的人同得基业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, '我未曾贪图 一个人 的 金、银、 衣服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, '我这 两只 手 常供给 我 和 同 人 的需用,这是你们自己 知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, '我凡事 给你们 作榜样,叫你们知道应当 这样 劳苦,扶助 软弱的人,又 当记念 主 耶稣 的话, 说:『施 比 受 更 为 有福。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, ' 保罗说 完了这话, 就跪 下 同 众人 祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, ' 众人 痛 哭, 抱著 保罗 的颈项,和他 亲嘴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, '叫 他们最 伤心的,就是他说「以后不能 再 见 我的 面」那 句话,于 是 送 他 上 船去了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, ' 我们 离别 了 众人,就开  船 一直 行 到 哥士。 第二 天到了 罗底,从那里 到 帕大喇, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, ' 遇见 一只船 要往 腓尼基 去,就上船 起行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, ' 望见 塞浦路斯,就 从南边 行 过,往 叙利亚 去,我们就 在 泰尔 上岸,因为 船 要在 那里 卸 货。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, ' 找著了 门徒,就在那里 住了 七 天。他们 被 圣灵感动,对保罗 说:「不 要上 耶路撒冷去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, ' 过了 这几天,我们 就起身 前行。他们众人 同 妻子 儿女,送 我们 到城 外, 我们都 跪 在 岸上 祷告,彼此辞别。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, ' 我们上 了船,他们 就 回 家去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, ' 我们 从 泰尔 行尽 了水路,来 到 多利买 ,就 问那里的弟兄 安,和他们 同 住 了一 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, ' 第二天,我们离开 那里,来 到 凯撒利亚,就 进 了 传福音 的腓利 家里,和他 同 住。他是 那七 个执事里的一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, ' 他 有 四 个女儿,都是处女,是说预言的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, ' 我们在那里多 住了 几天,有一 个先知,名叫 亚迦布,从 犹太 下来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, ' 到了 我们这里,就 拿 保罗 的腰带 捆 上自己 的手 脚,说:「 圣 灵 说:犹太人 在 耶路撒冷,要如此 捆绑 这 腰带 的主 人, 把他交在 外邦人 手里。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, ' 我们 和 那本地 的人 听见 这话,都苦劝 保罗 不要 上 耶路撒冷去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, ' 保罗 说:「你们 为什么 这样痛哭, 使我 心 碎呢?我 为 主 耶稣 的名,不 但 被人捆绑, 就 是 死 在 耶路撒冷 也是愿 意的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, ' 保罗 既不 听劝,我们便住了口,只说:「愿 主 的旨意 成就」,便了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, ' 过了 几 日,我们收拾 行李上 耶路撒冷去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, ' 有 凯撒利亚 的几个门徒 和 我们 同 去,带 我们 到一个久为(久为:或译老)门徒的家里,叫我们与他 同住;他名叫拿孙,是塞浦路斯人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, ' 到了 耶路撒冷,弟兄们 欢欢喜喜地 接待 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, ' 第二天,保罗 同 我们 去 见 雅各; 长老们 也都 在那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, ' 保罗问了他们 安,便将 神 用 他 传教,在外邦人 中间 所行 之事,一一地 述说了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, ' 他们听见,就归荣耀与 神, 对保罗 说:「兄台,你看 犹太人 中 信 主的 有 多少 万,并且 都 为 律法 热心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, ' 他们听 见 人说, 你教训 一切 在 外邦 的犹太人 离弃 摩西,对他们说, 不 要给孩子 行割礼,也不 要遵行 条规。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, '众人必 听见 你来了,这 可怎么 办呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, '你 就 照著 我们的话 行吧!我们 这里有 四个 人,都有 愿  在 身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, '你带 他们去,与他们 一同 行洁净的礼, 替 他们 拿出规费,叫 他们得以剃 头。 这样,众人就可知道,先前所 听见 你 的事 都是 虚的;并可知道,你自己为人, 循规蹈矩,遵行 律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, '至于  信 主的外邦人,我们 已经写信 拟定,叫他们 谨忌那 祭偶像之物,和 血,并 勒死的牲畜,与 奸淫。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, '于 是 保罗 带著 那四个人,第二 天 与 他们 一同行了洁净的礼,进 了 殿,报明 洁净 的日期 满足,只等 祭司为 他们 各 人 献 祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, ' 那七 日 将 完,从 亚细亚 来的犹太人 看见 保罗 在 殿里,就耸动 了众 人, 下 手 拿 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, '喊叫说:「以色列 人 来帮助,这 就是 在各处 教训 众 人 糟践 我们百姓 和 律法,并 这 地方的。 他又 带著 希腊人 进 殿, 污秽了 这 圣 地。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, '(这话是因 他们曾 看见 以弗所人 特罗非摩 同 保罗 在城 里, 以为 保罗 带 他 进了 殿。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, ' 合 城 都震动, 百姓 一齐跑来, 拿住 保罗,拉 他 出 殿, 殿门 立刻 都关了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, ' 他们正 想要杀 他,有人报信 给 营 里的千夫长 说:「耶路撒冷 合 城都乱了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, '千夫长 立时 带著 兵丁 和 几个百夫长,跑下去 到 他们那里。 他们见了 千夫长 和 兵丁,就止住 不打 保罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, '于 是 千夫长 上前 拿住 他, 吩咐 用两 条 铁链捆锁;又 问 他 是什么人, 做 的是 什么事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, ' 众人 有喊叫 这个的,有喊叫那个的;千夫长 因为 这样乱嚷, 得 不 著 实情,就吩咐 人将保罗 带 进 营楼去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, ' 到了 台阶 上,众人 挤得 凶猛,兵丁 只得将 保罗 抬起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, ' 众 人 跟在后面,喊著说:「除掉 他!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, ' 将要 带 他进 营楼,保罗 对千夫长 说:「我 对 你 说 句话可以不可以?」 他 说:「你懂得 希腊话吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, '你 莫非 是 从前 作乱、 带领四千 凶 徒 往 旷野 去 的那埃及人吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, ' 保罗 说:「我 本是 犹太 人,生在基利 家的大数,并 不是无 名 小城 的人。求 你 准 我 对 百姓 说话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, ' 千夫长准了。保罗 就站 在 台阶上,向百姓 摆 手, 他们都 静默 无声,保罗便用 希伯来 话 对他们说:   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, '「诸位 父 兄 请听,我 现在 对 你们 分诉。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, ' 众人 听 他说 的是希伯来 话,就更 加 安静了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, ' 保罗说:「我 原是 犹太 人,生 在 基利 家的大数, 长 在 这 城里,在 迦玛列门 下,按著 我们祖宗 严紧的律法 受教, 热心事奉 神,像 你们 众人 今日 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, '我 也曾逼迫 奉这 道的人,直到 死地,无论 男 女 都锁拿 下 监。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, ' 这是大祭司 和 众 长老 都可以给我 作见证的。我又 领 了 他们 达与 弟兄 的书信, 往 大马士革 去,要把在 那里 奉这道的人锁拿,带 到 耶路撒冷 受刑。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, '「 我 将到 大马士革,正 走的时候,约 在晌午,忽然 从 天 上发大 光,四面照 著 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, '我就 仆倒 在 地, 听见 有声音 对我 说:『扫罗!扫罗!你为什么 逼迫 我?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, ' 我 回答说:『主啊,你是 谁?』 他说:『我 就是 你 所 逼迫 的拿撒勒人 耶稣。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, '与 我 同 行 的人看见了 那 光,却 没 有听明 那位对我 说话 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, ' 我说:『主啊,我当做 什么?』 主 说:『起来,进 大马士革去,在那里,要将 所 派 你 做 的一切事 告诉 你。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, ' 我因 那 光 的荣耀 不 能看见,同行 的人就拉著 我 手 进了 大马士革。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, ' 那里有一个人,名叫亚拿尼亚,按著 律法 是虔诚 人,为一切 住 在那里的犹太人 所 称赞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, '他来 见 我, 站在旁边,对我 说:『兄弟 扫罗,你可以看见。』我 当 时 往 上一看,就看见了他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, '他又 说:『我们 祖宗的 神 拣选了 你,叫你明白 他 的旨意,又 得见 那义者, 听 他 口 中所出 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, '因为 你要将所 看见的, 所听见的,对著 万 人 为他 作 见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, ' 现在 你为什么 耽延呢?起来,求告 他 的名 受洗, 洗去 你 的罪。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, '「 后来,我 回 到 耶路撒冷, 在 殿 里祷告 的时候, 魂游象外, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, ' 看见 主 向我 说:『你赶紧地 离开  耶路撒冷,不可迟延;因 你 为 我 作的见证,这里的人必不 领受。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, '我 就说:『主啊,他们 知道 我 从前把信 你 的人收在监里,又 在各 会堂 里鞭打他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, '并且 你 的见证人 司提反 被害 流血 的时候,我也 站 在 旁边欢喜;又 看守 害死 他 之人的衣裳。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, ' 主向 我 说:『你去吧! 我 要差 你 远远地 往 外邦人那里去。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, ' 众人听 他 说到 这 句话,就 高 声 说:「这样的人,从 世上 除掉他吧! 他 是不 当 活著的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, ' 众人 喧嚷, 摔掉 衣裳, 把尘土 向 空中 扬起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, '千夫长 就吩咐 将保罗 带 进 营楼去,叫 人用鞭子 拷问 他,要 知道 他们向 他 这样喧嚷 是为 什么 缘故。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, ' 刚用皮条 捆上,保罗 对 旁边站著 的百夫长 说:「人 是罗马人,又 没有定罪,你们 就鞭打他,有 这个例吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, ' 百夫长 听见这话,就去 见千夫长,告诉 他说:「 你要 做 什么? 这 人 是 罗马人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, ' 千夫长 就来 问保罗 说:「你告诉 我,你 是 罗马人吗?」 保罗说:「是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, ' 千夫长 说:「我 用许多 银子 才入了 罗马的民籍。」 保罗 说:「 我 生来 就是。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, '于 是 那些 要 拷问 保罗 的人就 离开  他去了。 千夫长 既知道 他是 罗马人,又 因为 捆绑了 他,也 害怕了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, ' 第二天,千夫长为要 知道 犹太人 控告 保罗 的实情,便解开  他, 吩咐 祭司长 和 全 公会 的人都聚集,将 保罗 带下来,叫他 站在他们 面前。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, ' 保罗 定睛看著 公会 的人,说:「弟兄们,我在 神 面前行事为人 都 是凭著良 心,直到 今 日。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, ' 大祭司 亚拿尼亚 就吩咐 旁边站著 的人 打 他 的嘴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, ' 保罗 对 他 说:「你这粉饰 的墙, 神 要 打 你!你 坐 堂为 的是按 律法 审问 我,你竟违背律法, 吩咐 人打 我吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, ' 站在 旁边的人说:「你辱骂 神 的大祭司吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, ' 保罗 说:「弟兄们,我不 晓得 他是 大祭司; 经上记著说:『 不 可毁谤 你 百姓 的官长。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, ' 保罗 看出 大众一 半 是 撒都该人, 一半 是法利赛人,就在 公会 中大声说:「 弟兄们,我 是 法利赛人,也是法利赛人 的子孙。我 现在受审问,是为 盼望 死人 复活。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, ' 说了 这话,法利赛人 和 撒都该人 就争论 起来, 会众 分为两党。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, '因为 撒都该人 说,没 有 复活,也没 有天使 和 鬼魂; 法利赛人 却说,两样都有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, ' 于 是大大地 喧嚷 起来。 有几个 法利赛 党 的文士 站起来 争辩 说:「我们看不 出 这 人 有什么恶处,倘 若 有鬼魂 或 是天使 对他 说过话,怎么样呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, ' 那时大 起 争吵,千夫长 恐 怕 保罗 被 他们 扯碎了,就吩咐 兵丁 下去,把他 从 众人 当中 抢出来, 带 进 营楼去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, ' 当 夜,主 站 在保罗旁边,说:「放心吧! 你怎样 在 耶路撒冷 为 我 作见证, 也 必 怎样 在 罗马 为我作见证。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, ' 到了 天亮,犹太人 同谋 起誓,说:「若不 先杀 保罗 就不 吃 不 喝。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, ' 这样 同心起 誓 的有 四十 多人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, '他们 来 见祭司长 和 长老,说:「我们 已经起了 一个大誓,若不先 杀 保罗 就不吃 什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, '现在 你们 和 公会 要知会 千夫长,叫 他 带下 保罗到 你们这里来,假作 要 详细 察考 他的事; 我们 已经 预备好了,不等他 来到跟前 就杀 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, ' 保罗 的外甥 听见 他们设下埋伏,就来 到 营楼 里告诉 保罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, ' 保罗 请 一个 百夫长来,说:「你领 这 少年人 去 见千夫长, 他有 事 告诉 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, '于 是 把 他 领 去 见千夫长, 说:「被囚 的保罗 请 我到他那里,求 我领 这 少年人 来见 你;他有 事 告诉 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, ' 千夫长 就拉著 他 的手, 走到一旁,私下 问他说:「 你有 什么 事告诉 我呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, ' 他说:「 犹太人 已经约定,要求 你 明天 带下 保罗 到 公会里去,假作 要 详细 查问 他 的 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, ' 你 切不 要随从 他们;因为 他们 有 四十 多 人 埋伏, 已经起誓说:若不 先杀 保罗 就不 吃 不 喝。 现在 预备 好了,只等 你 应允。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, '于 是 千夫长 打发少年人 走,嘱咐他说:「不要告诉 人 你将这事 报 给 我了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, ' 千夫长便叫了 两个 百夫长 来,说:「预备 步兵 二百, 马兵 七十, 长枪手 二百, 今夜 亥初 往 凯撒利亚 去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, '也 要预备 牲口 叫 保罗 骑上,护送 到 巡抚 腓力斯那里去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, '千夫长又 写了 文书, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, '大略说:「克劳第•吕西亚,请巡抚 腓力斯 大人 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, '这 人 被 犹太人 拿住, 将要 杀害,我得知 他是 罗马人,就带 兵丁 下去 救他出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, ' 因要 知道 他们告 他 的 缘故,我就带 他下到 他们 的公会去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, '便查知 他 被告 是因 他们 律法 的辩论,并 没有 什么 该 死 该绑 的罪名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, ' 后来有人把要害他 的计谋 告诉 我,我就立时 解 他到 你那里去,又 吩咐 告他的人 在你 面前 告 他。(有古卷加:愿 你平安!)」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, '于 是,兵丁 照 所吩咐 他们的,将 保罗 夜 里 带 到 安提帕底。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, ' 第二天,让 马兵 护送,他们就回 营楼去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, '马兵 来 到 凯撒利亚, 把文书 呈给 巡抚,便 叫保罗 站在 他面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, ' 巡抚看了文书, 问 保罗是 哪 省的人,既 晓得 他是 基利家人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, '就说:「等 告 你 的人 来到,我要细听 你的事」;便吩咐 人 把他看守 在希律 的衙门 里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, ' 过了 五 天,大祭司 亚拿尼亚 同 几个 长老,和 一个 辩士 帖土罗 下来, 向巡抚 控告 保罗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, ' 保罗 被提了来,帖土罗 就 告 他说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, '「腓力斯 大人,我们因 你 得以大 享 太平,并且 这 一国的弊病,因著 你 的先见 得以 更正了;我们随时 随 地 满心 感谢不尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, ' 惟恐 多说,你 嫌烦絮,只求 你 宽容 听 我们 说几句话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, ' 我们看 这个 人,如同瘟疫一般, 是鼓动 普天下 众 犹太人 生乱的,又 是拿撒勒 教党 里的一个头目, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, '连圣殿 他 也 想要 污秽; 我们把他 捉住了。(有古卷加:要按我们的律法审问, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, '不料 千夫长 吕西亚 前来,甚是 强 横,从我们 手 中把 他夺去,吩咐 告 他 的人到 你 这里来。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, '你自己 究 问 他,就 可以 知道 我们 告 他 的 一切 事了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, ' 众犹太人 也 随著告 他说:「事情 诚然是 这样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, ' 巡抚 点头 叫 保罗 说话。他就说:「我知道 你 在 这 国 里断事 多 年,所以我乐意 为 自己 分诉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, '你 查问就 可以 知道,从 我 上 耶路撒冷 礼拜 到今日不过 有 十二 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, ' 他们并没 有看见 我 在 殿里,或是 在会堂 里,或是 在城 里,和 人 辩论, 耸动 众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, '他们现在 所 告 我 的事 并不 能 对你 证实了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, '但 有一件事,我向你 承认,就是 他们所 称为 异端 的道,我正 按著那道事奉 我祖宗的 神,又信 合乎 律法 的和 先知书 上一切 所 记载的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, '并且靠著 神,盼望死人,无论 善 恶,都要 复活,就是 他们 自己 也 有 这个盼望。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, ' 我因 此 自己 勉励,对 神 对 人,常存 无亏 的良心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, ' 过了 几 年,我带著 赒济 本 国 的捐项和 供献的物 上去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, ' 正 献的时候,他们看见 我 在殿 里 已经洁净了,并没 有 聚众,也没 有 吵嚷,惟有几个 从 亚细亚 来的犹太人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, '他们 若 有 告 我的事,就应当 到 你 面前 来告我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, '即或不然,这些人 若看出 我 站 在公会 前,有 妄为的地方,他们自己 也可以说明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, '纵然有,也不过 一 句话,就是我站在 他们 中间 大声说:『我 今日 在 你们 面前受审,是为 死人 复活的道理。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, ' 腓力斯 本是详细 晓得 这 道,就支吾 他们 说:「且等 千夫长 吕西亚 下来,我要审断 你们 的事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, '于 是吩咐 百夫长 看守 保罗,并且 宽待他,也 不 拦阻 他 的亲友 来供给 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, ' 过了 几 天,腓力斯 和 他 夫人─ 犹太 的女子土西拉─一同来到,就叫了 保罗来, 听 他 讲论 信 基督 耶稣的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, ' 保罗 讲论 公义、节制,和 将来 的审判。腓力斯 甚觉恐惧,说:「你暂且 去吧, 等 我得 便再叫 你来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, '腓力斯又 指望 保罗 送 他 银钱,所以 屡次 叫 他来,和 他 谈论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, ' 过了 两年,波求•非斯都 接了 腓力斯 的任; 腓力斯 要 讨 犹太人 的喜欢,就留 保罗 在监里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, ' 非斯都 到了 任,过了 三 天,就从 凯撒利亚 上 耶路撒冷去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, ' 祭司长 和 犹太人 的首领 向 他 控告 保罗, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, '又 央告 他,求 他的情,将 保罗 提 到 耶路撒冷来,他们要在 路 上埋伏 杀害 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, '非斯都 却 回答说:「保罗 押 在 凯撒利亚, 我自己 快 要 往那里去」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, ' 又说:「你们 中间 有权势 的人与我一同下去, 那人若有什么 不是,就可以告 他。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, ' 非斯都在他们 那里 住了 不过 十 天 八天,就下 凯撒利亚去;第二天 坐 堂,吩咐 将保罗 提上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, ' 保罗 来了,那些从 耶路撒冷 下来 的犹太人 周围站著, 将 许多 重大 的事控告他,都 是不 能 证实的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, '保罗 分诉说:「无论 犹太人 的 律法,或是 圣殿,或是 凯撒,我都 没有干犯。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, '但 非斯都 要 讨 犹太人 的喜欢,就问 保罗 说:「你愿 意 上 耶路撒冷去,在那里 听 我 审断 这 事吗?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, ' 保罗 说:「我站在 凯撒 的堂前,这就是我 应当 受审 的地方。我向犹太人 并没有行过什么不 义的事,这也 是 你 明明 知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, ' 我若 行了不义的事, 犯了 什么该 死 的罪,就是死,我也不 辞。 他们所 告 我 的事 若 都 不实,就没有人 可以 把我 交给 他们。我要上告 于 凯撒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, ' 非斯都 和 议会 商量了,就说:「你既上告 于 凯撒,可以往 凯撒 那里去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, ' 过了 些 日子,亚基帕 王 和 百妮基氏 来 到 凯撒利亚,问 非斯都安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, ' 在 那里 住了 多 日,非斯都 将保罗 的事 告诉 王,说:「这里有 一个 人,是 腓力斯 留在 监里的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, '我 在 耶路撒冷的时候,祭司长 和 犹太 的长老 将他 的事 禀报了我,求 我定 他的罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, '我对 他们 说,无论什么 人,被告 还 没有 和 原告 对质,未 得 机会 分诉 所 告他的事,就先定他的罪, 这不 是 罗马人 的条例。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, ' 及至他们 都来 到这里,我就不 耽延,第二天 便坐 堂,吩咐 把那人 提上来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, '告 他 的人 站著告他;所告的,并没 有 我 所逆料 的那等恶事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, '不过 是有 几样 辩论,为他们 自己 敬鬼神的事,又 为 一个 人名叫耶稣,是已经死了,保罗 却说 他 是活著的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, ' 这些事当 怎样 究问,我 心里作难,所以问他说:『你 愿 意 上 耶路撒冷去,在那里 为 这些事 听审吗?』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, '但 保罗 求 我留下他,要 听 皇上审断,我就吩咐 把他 留下,等 我解 他 到 凯撒那里去。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, ' 亚基帕 对 非斯都说:「我自己 也 愿  听 这人辩论。」非斯都说:「明天 你可以听。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, '第二天, 亚基帕 和 百妮基 大张 威势 而来, 同著 众千夫长 和 城 里的尊贵 人 进 了 公厅。 非斯都 吩咐一声,就有人将保罗 带进来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, ' 非斯都 说:「亚基帕 王 和 在 这里的 诸 位啊,你们看 这人,就是 一切 犹太 人,在 耶路撒冷 和 这里,曾向我恳求、呼叫说:『不 可 容他 再 活著。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, '但 我 查明 他 没有犯 什么 该 死的罪,并且 他自己 上告 于  皇帝,所以我定意 把他解去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, '论到 这人,我没 有 确实的 事 可以奏明 主上。因此,我带 他 到你们 面前,也 特意 带他到你 亚基帕 王 面前,为 要在 查问 之后有 所 陈奏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, '据 我 看来,解送 囚犯, 不 指明 他 的罪案 是不合理的。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, ' 亚基帕 对 保罗 说:「准 你 为 自己 辩明。」于 是 保罗 伸 手 分诉,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, '「亚基帕 王啊,犹太人 所 告 我的一切事,今日 得 在你 面前 分诉,实为 万幸; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, '更可幸的,是 你 熟悉 犹太人 的 规矩 和 他们的 辩论;所以 求 你耐心 听 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, '我 从 起初 在 本 国 的民中,并在 耶路撒冷, 自 幼 为人 如何,犹太人 都 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, '他们若 肯 作见证 就晓得,我 从起初 是 按著 我们 教 中最严紧 的教门 作了 法利赛人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, ' 现在 我站在 这里受审,是 因为 指望 神 向 我们 祖宗 所应许的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, ' 这应许,我们 十二个支派,昼 夜 切切地 事奉 神,都指望 得著。王啊,我被 犹太人 控告,就是因 这 指望。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, ' 神 叫死人 复活, 你们 为什么 看作 不可信的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, '从前 我 自己 以为 应当 多方 攻击 拿撒勒人 耶稣 的名, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, '我在 耶路撒冷 也 曾这样 行了。 既从 祭司长 得了 权柄,我 就把许多 圣徒 囚在 监里。 他们 被杀,我也出 名定案。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, ' 在 各 会堂,我屡次 用刑 强逼 他们 说亵渎的话,又 分外 恼恨 他们,甚至 追逼他们,直到 外邦 的城邑。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, '「那时,我领了 祭司长 的权柄 和 命令,往 大马士革 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, '王啊,我在 路上,晌午的时候,看见 从天 发光,比 日头 还亮,四面照著 我 并 与 我 同行的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, ' 我们 都 仆倒 在 地,我就听见 有声音 用 希伯来 话 向 我说:『扫罗!扫罗!为什么 逼迫 我?你 用脚踢 刺是难的!』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, ' 我 说:『主啊,你是 谁?』 主 说:『我 就是 你 所 逼迫 的耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, ' 你起来 站著, 我 特意 向你 显现,要派 你 作执事, 作见证, 将你所 看见 的事和 我将 要指示你 的事证明出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, '我也要救 你 脱离 百姓 和 外邦人的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, '我 差 你 到 他们那里去,要叫他们 的眼睛 得开 ,从 黑暗 中归 向 光明, 从撒但 权 下归向 神;又因信 我, 得蒙 赦 罪,和 一切成圣 的人同得基业。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, '「亚基帕 王啊,我故此 没 有 违背 那从天上 来的异象; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, ' 先 在 大马士革,后在 耶路撒冷 和 犹太 全 地,以及 外邦,劝勉 他们应当悔改 归 向 神,行 事 与悔改 的心相称。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, '因 此,犹太人 在 殿 里拿住 我,想要 杀我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, '然而 我蒙 神 的帮助,直到 今 日 还站得住, 对著 尊贵、卑贱、老幼 作见证;所讲 的 并 不外乎 众先知 和 摩西 所说 将来必 成 的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, ' 就是基督 必须受害,并且 因从 死 里复活,要 首先 把光明 的道传给 百姓 和 外邦人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, ' 保罗 这样 分诉,非斯都 大 声 说:「保罗,你癫狂了吧。你的学问 太大,反叫 你 癫狂了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, ' 保罗 说:「非斯都 大人,我不 是癫狂,我说 的乃是 真实 明白 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, ' 王 也晓得 这些事,所以 我向 王 放胆 直言, 我深信 这些事 没有 一件向王 隐藏的,因 都不 是 在 背地 里做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, '亚基帕 王啊,你信 先知吗?我知道 你是信的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, ' 亚基帕 对 保罗说:「你想少微 一劝,便叫我 作 基督徒啊(或译:你这样劝我,几乎叫我作基督徒了)!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, ' 保罗说:「无论 是少 劝 是多劝,我向 神 所 求的,不 但 你一个人,就是 今天 一切 听 我的,都 要 像 我 一样,只是 不要像我有这些 锁链。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, '于 是,王 和 巡抚 并 百妮基 与 同坐 的人 都起来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, ' 退到里面,彼此 谈论 说:「 这 人 并没有 犯 什么 该 死 该绑的罪。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, ' 亚基帕 又对非斯都 说:「这 人 若 没 有上告 于 凯撒,就可以 释放了。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, ' 非斯都既然定规了,叫我们 坐船往 意大利 去,便将保罗 和 别 的囚犯 交给 御 营 里的一个百夫长,名叫 犹流。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, ' 有一只亚大米田 的船,要 沿著 亚细亚 一带地方的海边 走,我们就上了那船开 行;有马其顿 的帖撒罗尼迦人 亚里达古 和我们 同 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, ' 第二天,到 了 西顿; 犹流 宽 待 保罗,准 他往 朋友 那里去,受他们的照应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, '从那里 又开 船,因为 风 不顺,就贴著塞浦路斯 背风岸行去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, ' 过 了 基利家、 旁非利亚 前面的海,就到 了 吕家 的每拉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, '在那里,百夫长 遇见 一只亚历山大 的船,要往 意大利 去,便叫我们 上 了那船。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, ' 一连多 日,船行得慢, 仅仅 来到 革尼土 的对面。因为被风 拦阻,就贴著克里特背风岸,从撒摩尼 对面 行过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, ' 我们沿岸行 走,仅仅 来 到 一个 地方,名叫 佳澳;离那里 不远,有 拉西亚 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, ' 走的 日子 多了, 已经 过了 禁食的节期, 行船 又 危险,保罗 就劝 众人 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, '「众位,我看 这次行船,不 但 货物 和 船 要 受 伤损, 大 遭破坏, 连 我们 的性命也难保。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, '但 百夫长 信从 掌船 的和 船主, 不信从 保罗 所说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, '且 因在这海口 过 冬 不便,船上的人就多半 说,不如开 船离开  这地方,或者 能 到 菲尼基 过冬。菲尼基是克里特 的一个海口,一面朝 东北, 一面朝东南。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, '这时,微微起了 南风,他们以为 得 意,就起了锚,贴近 克里特 行去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, ' 不 多 几时,狂 风 从岛上扑下来;那风名叫「友拉革罗」。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, ' 船 被风抓住, 敌 不 住 风,我们就任 风刮去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, ' 贴著一个 小岛 的背风岸奔行,那岛名叫 高大, 在那里仅仅收住了 小船。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, ' 既然把小船拉上来,就用缆索 捆绑 船底,又 恐 怕 在 赛耳底沙滩 上搁了浅,就落下 篷来, 任船飘去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, ' 我们 被风浪 逼得甚急,第二 天众人就把货物抛在海里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, ' 到第三天,他们又亲手 把船 上的器具 抛弃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, ' 太阳 和 星辰 多 日 不显露,又 有狂风大浪 催逼,我们 得救 的指望 就 都 绝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, ' 众人 多日 没有吃什么,保罗 就出来站 在 他们 中间,说:「众位,你们本该 听 我的话,不 离开  克里特, 免得遭 这样 的伤损 破坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, ' 现在 我还劝 你们 放心, 你们 的 性命 一个也不 失丧,惟独 失丧这船。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, '因 我所 属 所 事奉的 神,他的使者 昨 夜 站在 我旁边,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, '『保罗,不要 害怕,你 必定 站在凯撒面前, 并且 与你 同 船的人, 神 都 赐给 你了。』 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, '所以 众位 可以放心, 我信 神 他怎样 对我 说,事情 也要怎样 成就。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, '只是 我们 必 要撞在 一个 岛 上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, ' 到了 第十四 天夜间, 船在 亚得里亚 海飘来飘去。约到 半夜,水手 以为 渐近 旱地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, ' 就探深浅, 探得有十二 丈; 稍 往前行,又 探深浅, 探得 有九 丈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, ' 恐怕 撞在 石头上,就从船尾 抛 下 四个 锚,盼望 天亮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, ' 水手 想要 逃 出 船去, 把小船 放在 海 里,假作 要 从 船头 抛 锚 的样子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, '保罗 对百夫长 和 兵丁 说:「这些 人若 不 等 在 船上,你们 必不能 得救。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, '于 是 兵丁 砍断 小船 的绳子, 由 它 飘去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, ' 天 渐亮 的时候,保罗 劝 众人 都吃 饭,说:「你们悬望 忍 饿 不 吃什么,已经 十四 天了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, '所以 我劝 你们 吃 饭, 这 是 关乎 你们 救命的事;因为 你们 各人 连一根头发 也不至于 损坏。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, ' 保罗说了 这话, 就拿 著饼,在 众人 面前祝谢了 神, 擘开  吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, '于 是 他们 都 放下心,也 就吃 了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, ' 我们在 船 上 的共有 二百 七 十六 个人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, ' 他们吃 饱了,就把船上的麦子 抛在 海 里,为要叫船 轻一点。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, '「 到了 天亮,他们不 认识 那地方,但 见 一个 海湾,有 岸可登,就商议 能 把船 拢 进去不能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, '于 是 砍断 缆索,弃锚 在 海里; 同时也松开  舵 绳, 拉起 头篷,顺著 风 向 岸行去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, '但 遇著 两水 夹流的 地方,就把船 搁了浅; 船头 胶住 不动, 船尾 被 浪 的猛力 冲坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, ' 兵丁 的意思 要 把 囚犯 杀了,恐怕有 洑水 脱逃的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, '但 百夫长 要 救 保罗,不准 他们 任意而行,就 吩咐 会 洑水的,跳下水 去先 上 岸; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, ' 其余 馀的 人 可以用 板子 或 船 上的零碎东西上岸。 这样,众人 都得了救,上了 岸。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, ' 我们既 已得救,才知道 那 岛 名叫 马耳他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, ' 土人 看待 我们,有 非常 的情分;因为 当时下 雨, 天气又冷,就 生 火 接待 我们 众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, '那时,保罗 拾起 一捆 柴, 放在 火 上,有一条毒蛇,因为热了 出来,咬住 他 的手。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, ' 土人 看见 那毒蛇 悬在 他 手 上,就彼此 说:「这 人 必 是 个凶手,虽然从 海 里救上来,天理 还不 容 他 活著。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, ' 保罗竟 把那毒蛇 甩 在 火里,并没 有受伤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, ' 土人想 他 必 要肿起来,或 是忽然 仆倒 死了; 看 了 多时, 见 他无 害, 就转念,说:「他 是个 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, ' 离 那 地方不远,有 田产 是 岛 长 部百流的;他 接纳 我们,尽情 款待 三 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, ' 当时,部百流 的父亲 患 热 病 和 痢疾躺著。 保罗 进去, 为他祷告,按 手 在他身上,治好了 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, '从此, 岛 上 其余 馀的 病人 也 来, 得了医治。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, '他们 又 多 方地 尊敬 我们; 到了开 船的时候,也把我们所需用 的送 到船上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, ' 过了 三 个月,我们上了 亚历山大 的 船往前行;这船以「宙斯双子」 为记,是在 那海岛 过了冬的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, ' 到了 叙拉古,我们停泊 三 日; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, '又从那里 绕行,来 到 利基翁。 过了 一 天,起了 南风,第二天 就来 到 部丢利。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, '在那里 遇见 弟兄们,请 我们与他们 同 住了 七 天。 这样,我们来 到 罗马。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, '那里 的弟兄们 一听 见 我们 的信息就出来,到 亚比乌 市 和 三 馆 地方迎接 我们。 保罗 见了他们,就感谢 神,放心壮 胆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, ' 进了 罗马城,(有古卷加:百夫长把众囚犯交给御营的统领,惟有)保罗 蒙准 和 一个看守 他 的兵 另住在一处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, ' 过了 三 天,保罗 请犹太人 的首领 来。 他们 来了,就对 他们 说:「 弟兄们,我 虽没有做 什么事 干犯 本国的百姓 和 我们祖宗 的规条,却被 锁绑,从 耶路撒冷 解在 罗马人 的手里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, '他们 审问了 我,就愿 意 释放我;因为 在 我身上,并没 有 该死 的罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, '无奈 犹太人 不服,我不得已,只好 上告 于 凯撒,并非 有 什么事要 控告 我 本国的百姓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, '因 此, 我请 你们 来见面 说话, 我原 为 以色列人 所指望的,被这 链子 捆锁。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, ' 他们 说:「我们 并 没有接著 从 犹太 来论 你 的信,也没 有 弟兄 到 这里来报给 我们说 你 有什么 不好处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, '但 我们愿 意 听 你 的意见 如何;因为 这 教门,我们 晓得 是 到处 被毁谤的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, ' 他们和保罗 约定了 日子,就有许多 人到 他 的寓处 来。保罗从 早 到 晚,对他们 讲论这事,证明 神 国的道, 引 摩西 的律法 和 先知的书, 以 耶稣 的事劝勉 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, ' 他所说的话,有信的, 有不信的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, ' 他们彼此 不合,就散了;未散以先,保罗 说了 一 句话,说:「圣 灵 藉 借 先知 以赛亚 向 你们 祖宗 所说 的话是不错的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, '他说:你去 告诉这 百姓 说: 你们听 是要听见,却 不 明白; 看 是要看见,却 不 晓得; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, '因为 这 百姓 油蒙了 心, 耳朵 发 沉, 眼睛 闭著;恐怕 眼睛 看见, 耳朵 听见, 心 里明白, 回转过来, 我就医治 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, '所以 你们 当 知道, 神 这 救恩,如今传给 外邦人,他们也 必听受。」(有古卷加: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, ' 保罗 说了 这话,犹太人 议论纷纷地 就走了。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, ' 保罗在自己 所租的房子 里 住 了足足 两年。 凡 来见 他的人,他全都接待, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, '放 胆 传讲 神 国的道,将 主 耶稣 基督 的 事教导人,并没有人禁止。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, '耶稣 基督的 仆人 保罗,奉召 为使徒,特派传  神的 福音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, '这福音是 神从前藉 借 众先知 在 圣经 上所应许的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, '论到 他 儿子─我主耶稣基督。 按 肉体说,是从大卫 后裔 生的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, '按 圣善的 灵说,因从 死里 复活,以 大能 显明是 神的 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, '我们从 他 受了 恩惠 并 使徒的职分,在万 国 之中 叫人为 他的 名 信 服真道; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, '其中 也 有 你们 这蒙召 属耶稣 基督的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, '我写信给你们 在 罗马、为 神 所爱、奉召 作圣徒的 众人。愿 恩惠、 平安 从 我们的 父 神 并 主 耶稣 基督 归与你们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, ' 第一,我靠著 耶稣 基督,为 你们 众人 感谢 我的 神,因 你们的 信德 传遍了 天下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, ' 我 在 他 儿子 福音上, 用 心灵 所事奉的 神 可以 见证,我怎样不住地 提到 你们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, '在 祷告 之间常常 恳求,或者 照 神的 旨意, 终 能得平坦的道路 往 你们 那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, '因为 我切切地 想见 你们,要 把些 属灵的 恩赐 分给 你们, 使你们 可以坚固; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, ' 这样,我在你们 中间,因 你 与 我 彼此的 信心,就可以同得安慰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, ' 弟兄们,我不 愿 意 你们 不知道, 我屡次 定意 往 你们 那里去, 要在你们 中间 得 些 果子,如同 在其余 馀的 外邦人 中一样;只是 到如今 仍有阻隔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, ' 无论是 希腊人、 化外人、聪明人、 愚拙人,我都 欠他们的债, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, '所以 情愿 尽 我的力量, 将福音也 传 给你们 在 罗马的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, ' 我不 以福音 为耻; 这福音本是 神的 大能, 要救 一切 相信的,先是 犹太人, 后是希腊人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, '因为 神 的义 正在 这 福音上显明出来;这义是本于  信,以至于  信。如 经上所记:「 义人 必因 信 得生。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, '原来, 神的 忿怒 从 天上 显明 在 一切 不虔 不义的 人身上,就是那些 行不义 阻挡 真理的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, ' 神的事情,人所能知道的,原 显明 在人 心里,因为 神 已经给他们 显明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, ' 自从 造 天地以来, 神的 永 能 和 神性 是明明可知的,虽是眼不能见,但藉 借著所造之物 就可以晓得,叫 人 无可推诿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, '因为,他们虽然知道 神,却不 当作 神 荣耀他,也不 感谢他。 他们的 思念 变为虚妄, 无知的 心 就昏暗了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, '自称 为 聪明,反成了愚拙, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, ' 将不能朽坏之 神的 荣耀 变 为 偶像,仿佛必朽坏的 人 和 飞禽、 走兽、 昆虫 的样式。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, '所以, 神 任凭 他们 逞著 心里的 情欲 行污秽的事,以致 彼此 玷辱 自己的 身体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, '他们将 神 的真实 变 为 虚谎, 去敬拜 事奉 受造之物,不 敬奉那造物的主─主 乃是 可称颂的,直到 永远。阿们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, '因 此, 神 任凭 他们 放纵 可羞耻的 情欲。 他们的 女人 把顺性的 用处 变 为 逆 性的用处; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, '男人 也 是 如此,弃了 女人 顺性的 用处, 欲火 攻心,彼此贪恋,男 和 男 行 可羞耻的事,就 在 自己 身上受 这 妄为 当得 的报应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, ' 他们既然 故意不 认识 神, 神 就任凭 他们 存邪僻的 心,行 那些不 合理的事; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, '装满了 各样 不义、邪恶、贪婪、恶毒(或译:阴毒);满 心是嫉妒、凶杀、争竞、诡诈、毒恨; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, '又是谗毁的、背后说人的、怨恨 神的(或译:被 神所憎恶的)、侮慢人的、狂傲的、自夸的、捏造 恶事的、违背 父母的、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, '无知的、背约的、无亲情的、不怜悯人的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, '他们 虽知道 神 判定 行 这样事 的人是 当 死的,然而他们不 但 自己去行,还 喜欢 别人去行。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, ' 你这论断人的,无论你 是谁, 也无可推诿。 你在 什么事 上论断 人,就在什么事上定 自己的罪;因 你这论断人的,自己所行 却和别人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, ' 我们知道 这样行的人, 神 必 照 真理 审判他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, ' 你这 人哪,你论断 行 这样事的人, 自己所行 的却和别人一样, 你 以为能逃脱 神的 审判吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, '还是 你藐视 他 丰富的 恩慈、 宽容、 忍耐,不晓得 他的恩慈 是领 你 悔改呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, '你 竟 任著你刚硬 不悔改的 心,为自己 积蓄 忿怒,以致 神震怒, 显 他公义审判 的日子来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, '他 必照 各人的 行为 报应 各人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, ' 凡恒心 行 善、寻求 荣耀、 尊贵 和 不能朽坏之福的,就以永 生报应他们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, ' 惟有 结党、 不顺从 真理、反 顺从 不义的,就以忿怒、 恼恨报应他们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, '将患难、 困苦 加给一切 作 恶的人,先是 犹太人, 后是希腊人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, '却 将荣耀、尊贵、 平安 加给一切行 善 的人,先是 犹太人, 后是希腊人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, '因为 神 不 偏待 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, ' 凡 没有律法 犯了罪的,也 必不按律法 灭亡; 凡 在律法 以下 犯了罪的,也必按 律法 受审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, '(原来 在 神面前,不是 听 律法的 为义,乃是 行 律法的 称义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, ' 没 有 律法 的外邦人 若顺著本性 行 律法上 的事,他们 虽然没 有 律法,自己就是 自己的 律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, '这是 显出 律法的 功用 刻 在 他们 心里,他们 是非之心 同作见证,并且 他们的思念 互相 较量,或以为是,或以为非。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, '就在 神 藉 借 耶稣 基督 审判 人 隐秘事 的日子,照著 我的 福音所言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, ' 你 称为 犹太人,又 倚靠 律法,且指著 神 夸口; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, '既从 律法 中受了教训,就 晓得 神的旨意,也能分别是非(或译:也喜爱 那美好的事); ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, '又 深信 自己 是 给瞎子 领路的,是黑暗 中 人的光, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, '是蠢笨人 的师傅,是小孩子 的先生,在律法 上 有 知识 和 真理的 模范。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, ' 你既是 教导 别人,还不 教导 自己吗?你讲说 人不可 偷窃,自己还偷窃吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, '你说 人不可 奸淫,自己还奸淫吗?你厌恶 偶像,自己还偷窃庙中之物吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, '你 指著律法 夸口, 自己倒犯 律法、玷辱 神吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, ' 神的 名 在 外邦人中,因 你们 受了亵渎,正如 经上所记的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, ' 你若是 行 律法的,割礼 固然 于 你有益; 若 是 犯 律法的,你的 割礼 就算不得 割礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, '所以 那未受割礼的,若 遵守 律法的 条例,他 虽然未受割礼,岂不 算是 有割礼吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, '而且 那本来 未受割礼的,若能全守 律法,岂不是要审判 你 这有仪文 和 割礼 竟犯 律法的人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, '因为 外面作犹太人的,不 是 真犹太人; 外面 肉身的割礼,也不是 真割礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, '惟有 里面作的,才是真犹太人; 真割礼 也是心里的, 在乎灵,不 在乎仪文。这人 的称赞 不是 从 人来的,乃是 从 神来的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, '这样说来,犹太人 有什么 长处? 割礼 有什么 益处呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, '凡事 大有 好处:第一是 神的 圣言 交托 讬他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, ' 即便有 不信的,这有何妨呢? 难道他们的 不信 就废掉 神的 信吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, '断乎不能!不如说, 神 是 真实的, 人 都是虚谎的。如 经上所记: 你 责备人的时候,显为公义; 被人议论 的时候,可以得胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, '我且照著 人 的常话说, 我们的 不义 若显出 神的 义来,我们可以怎么 说呢? 神 降 怒,是他不义吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, '断乎不是!若是这样, 神 怎 能审判 世界呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, ' 若 神的 真实,因 我的 虚谎 越发 显出 他的 荣耀,为什么 我还 受审判,好像 罪人呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, ' 为什么不 说, 我们可以作 恶 以 成 善呢?这是 毁谤 我们的人 说 我们有这话。这等人 定罪 是 该当的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, ' 这却怎么样呢?我们比他们强吗? 决不是的!因 我们已经证明: 犹太人 和 希腊人 都 在罪恶 之下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, '就如 经上所记: 没 有 义人,连一个 也没有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, '没 有 明白的;没 有 寻求 神的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, '都 是偏离正路,一同 变为无用。没 有 行 善的,连一个 也没 有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, '他们的 喉咙 是敞开 的 坟墓;他们 用舌头 弄诡诈, 嘴唇 里 有虺蛇 的毒气, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, ' 满 口 是咒骂 苦毒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, '杀人流 血,他们的 脚 飞跑, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, ' 所经过的路 便行残害 暴虐的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, ' 平安 的路,他们未 曾知道; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, '他们 眼 中 不 怕 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, ' 我们晓得 律法 上的话 都是对律法 以下 之人说的,好 塞住 各人 的口, 叫普 世的人 都伏在 神 审判之下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, '所以 凡 有血气的,没有 一个因 行 律法能在 神 面前 称义,因为 律法 本是叫人知 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, '但 如今, 神的 义 在律法 以外 已经显明出来, 有律法 和 先知 为证: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, '就是 神的 义,因 信 耶稣 基督 加给 一切 相信的人, 并没有 分别。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, '因为 世人 都犯了罪, 亏缺了 神的 荣耀; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, '如今却蒙 神的 恩典,因 基督 耶稣的 救赎,就白白地 称义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, '神 设立 耶稣 作挽回祭,是凭著 耶稣的 血,藉 借著 人的信,要 显明 神的 义;因为 他用忍耐的心宽容 人先时 所犯的罪, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, ' 好在 今 时 显明 他的 义, 使人知道他自己为 义,也 称信 耶稣 的人为义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, '既是这样,哪里 能夸口呢?没有可夸的了。用 何 法没有的呢?是用立功之法吗?不是, 乃用 信 主之法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, '所以(有古卷:因为)我们看定了:人 称义 是因著信,不在乎 遵行 律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, '难道 神 只 作犹太人的 神吗?不 也是 作外邦人的 神吗?是的,也 作外邦人的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, '神 既是 一位,他 就要因 信 称那受割礼的 为义,也 要因 信 称那未受割礼的为义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, '这样,我们因 信 废了 律法吗?断乎不 是!更是 坚固 律法。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, '如此 说来,我们的 祖宗 亚伯拉罕 凭著 肉体 得了 什么呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, ' 倘若 亚伯拉罕 是因 行为 称义,就有 可夸的;只是在 神 面前 并无可夸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, ' 经 上说 什么呢?说:「亚伯拉罕 信 神, 这就算 为 他的 义。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, ' 做工的 得工价,不 算 恩典,乃 是 该得的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, ' 惟有不 做工的,只 信 称罪人 为义的 神,他的 信 就算 为 义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, '正如 大卫 称 那 在行为 以外蒙 神 算为 义 的人 是有福的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, '他说:得赦免 其 过、 遮盖 其 罪的,这人是有福的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, ' 主 不 算为 有罪的,这人 是有福的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, '如此看来,这 福 是单加给 那受割礼的人吗?不也 是 加给 那未受割礼的人吗?因 我们所说,亚伯拉罕 的信,就算 为 他的义, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, ' 是怎么 算的呢?是 在 他受割礼的时候呢? 是在 他未受割礼的时候呢?不是 在 受割礼的时候,乃是 在 未受割礼的时候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, '并且 他受了 割礼 的记号,作 他 未受割礼 的时候因信 称义 的印证,叫 他 作 一切 未受割礼 而 信 之人的父,使 他们 也 算 为义; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, '又 作受割礼之人 的父,就是那些不 但 受 割礼,并且 按我们的 祖宗 亚伯拉罕 未受割礼 而信 之踪迹 去行的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, '因为 神应许 亚伯拉罕 和 他 后裔,必得 承受 世界,不是 因 律法,乃是 因 信 而得的义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, ' 若是 属乎 律法 的人才得为后嗣,信 就归于 虚空, 应许 也就废弃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, '因为 律法 是惹动 忿怒的(或译:叫人受刑的); 哪里 没 有 律法,那里就没有 过犯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, '所以 人得为后嗣是本乎 信,因此 就属乎 恩,叫应许 定然 归给 一切 后裔;不 但 归给那属乎 律法的,也 归给那效法 亚伯拉罕 之信的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '亚伯拉罕 所信的,是那叫死人 复活、 使 无 变为 有的 神,他 在主面前 作 我们 世人 的父。如 经上所记:「 我已经立 你 作多 国 的父。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, '他 在无 可指望的时候,因 信 仍有指望, 就 得以作 多 国 的父,正如 先前所说:「你的 后裔 将要 如此。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, ' 他 将近 百岁的时候,虽然想到 自己的 身体 如同 已死, 撒拉 的生育 已经断绝,他的信心 还是不 软弱; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, '并且 仰望 神的 应许,总没有 因不信 心里起疑惑,反倒 因信 心里得坚固,将荣耀 归给 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, '且 满心相信 神所应许的 必 能 做成。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, ' 所以,这就算 为 他的 义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, '「 算为 他义」的这句话不是 单 为 他 写的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, '也是 为 我们 将来得 算为 义之人写的,就是我们这信 神使我们的 主 耶稣 从死 里 复活的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, '耶稣 被交给人,是为 我们的 过犯; 复活,是为 叫我们 称义(或译:耶稣是为我们的过犯交付了,是为我们称义复活了)。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, '我们既 因 信 称义,就藉 借著 我们的 主 耶稣 基督 得 与 神 相和。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, '我们又 藉 借著 他,因信 得 进入 现在 所站 的这 恩典 中,并且 欢欢喜喜 盼望 神的 荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, ' 不 但如此,就是 在患难 中 也是 欢欢喜喜的;因为知道 患难 生 忍耐, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, ' 忍耐 生老练, 老练 生盼望; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, ' 盼望 不至于  羞耻,因为 所 赐给 我们 的圣 灵将 神 的爱 浇灌 在 我们 心里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, ' 因 我们 还 软弱的时候,基督 就按所定的 日期 为 罪人 死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, ' 为 义人 死,是少有的; 为 仁人 死, 或者 有敢做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, '惟有 基督 在我们 还 作 罪人 的时候为 我们 死, 神 的 爱 就在此 向 我们 显明了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, '现在 我们既靠著 他的 血 称义,就 更要 藉 借著 他 免去 神的忿怒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, '因为 我们作 仇敌的时候,且 藉 借著 神 儿子 的死,得与 神 和好;既已和好,就更要 因 他的 生 得救了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, ' 不 但如此,我们既 藉 借著 我 主 耶稣 基督 得与 神和好,也 就 藉 借著 他 以 神 为乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, ' 这 就如 罪 是从 一 人 入了 世界,死 又是 从 罪来的;于 是 死 就临 到 众 人,因为 众人 都犯了罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, ' 没有律法 之先,罪 已经 在 世上;但 没 有 律法,罪 也不 算罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, '然而 从 亚当 到 摩西,死 就作了王,连 那些不 与 亚当 犯 一样 罪过的,也在他的权下。亚当 乃是 那以后要来 之人的预像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, '只是 过犯 不 如 恩赐,若 因 一人 的过犯,众人 都死了,何况 神的 恩典,与 那 因 耶稣 基督 一 人 恩典 中的赏赐,岂不更 加倍地 临到 众人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, '因 一人 犯罪就定罪,也 不 如 恩赐,原来 审判 是由 一人 而 定罪,恩赐 乃是 由 许多 过犯 而 称义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, '若 因 一人 的过犯,死 就因 这一人 作了王,何况那些受 洪 恩 又 蒙所赐 之义的,岂不更要 因 耶稣 基督 一人 在生命 中 作王吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, '如此说来, 因 一次的 过犯, 众 人 都被 定罪;照样,因 一次的 义行, 众 人 也就被 称义 得生命了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, ' 因 一 人的 悖逆,众人 成为 罪人;照样,因 一人的 顺从,众人 也成为 义了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, ' 律法 本是外添的,叫 过犯 显多;只是 罪 在哪里 显多,恩典 就更显多了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, ' 就如 罪 作王 叫 人死;照样,恩典 也藉 借著 义 作王,叫 人因 我们的 主 耶稣 基督 得永 生。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, '这样,怎么 说呢?我们可以仍在 罪中、叫 恩典 显多吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, '断乎不可! 我们在罪 上死了 的人岂可 仍 在罪 中 活著呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, ' 岂不知 我们 这受洗 归入 基督 耶稣 的人是受洗 归入 他的 死吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, '所以,我们藉 借著 洗礼 归入 死,和他 一同埋葬,原是叫 我们 一举一动 有 新 生的样式,像 基督 藉 借著 父 的荣耀 从 死里 复活一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, ' 我们若 在 他 死 的形状 上与他联合,也 要 在他复活的形状上与他联合; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, '因为 知道 我们的 旧 人 和他同钉十字架,使 罪 身 灭绝,叫我们 不再 作罪 的奴仆; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, '因为 已死的人 是脱离了 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, ' 我们若是 与 基督 同死,就信 必与他 同活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, '因为知道 基督 既从 死里 复活,就不再 死,死 也不再 作他的 主了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, ' 他 死 是向罪 死了,只有一次; 他活是向 神 活著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, '这样,你们 向罪 也 当 看 自己 是 死的;向 神 在 基督 耶稣里,却 当看自己是活的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, '所以,不要 容罪 在 你们 必死的 身上 作王,使 你们顺从 身子的 私欲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, '也不要 将你们的 肢体 献给 罪 作不义的 器具;倒要 像 从 死里 复活的人,将自己 献给 神,并 将 肢体 作义的 器具献给 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, ' 罪 必不能 作你们的 主;因 你们不 在律法 之下,乃 在恩典 之下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, '这却 怎么样呢? 我们在恩典 之下,不 在律法 之下,就可以犯罪吗?断乎不可! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, '岂不 晓得 你们献上 自己 作奴仆, 顺从 谁,就作 谁的 奴仆吗?或 作罪的奴仆,以至于  死;或 作顺命的奴仆,以致 成义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, ' 感谢 神! 因为你们从前虽然作 罪 的奴仆,现今却 从 心里 顺服了 所 传给 你们道理 的模范。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, '你们既 从 罪 里得了释放,就作了义 的奴仆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, '我因 你们 肉体 的软弱,就照人的常话 对你们说。 你们 从前怎样 将肢体 献给 不洁 不法 作奴仆,以至于  不法;现今 也要照样 将 肢体 献给 义 作奴仆,以至于  成圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, '因为 你们作 罪 之奴仆 的时候,就 不被义 约束了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, ' 你们现今 所看为羞耻 的事,当日 有 什么 果子呢? 那些事 的结局 就是死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, '但 现今,你们既从 罪 里得了释放,作了 神的 奴仆,就有 成 圣 的果子, 那结局 就是永 生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, '因为 罪 的工价 乃是死;惟有 神的 恩赐,在 我们的 主 基督 耶稣里,乃是永 生。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, ' 弟兄们, 我现在对明白 律法 的人说,你们岂不晓得 律法 管 人 是在 活著的 时候吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, '就如 女人 有了丈夫,丈夫 还活著,就被律法 约束; 丈夫 若 死了,就脱离了 丈夫的 律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, '所以 丈夫 活著,她若归于  别人,便叫 淫妇; 丈夫 若 死了,她就 脱离了 丈夫的 律法, 虽然归于  别人,也不 是 淫妇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, '我的 弟兄们,这样说来,你们 藉 借著 基督 的身体,在律法 上也是 死了,叫 你们 归于  别人,就是归于 那从 死里 复活的,叫 我们结果子给 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, '因为 我们 属 肉体 的时候,那 因 律法 而生的恶 欲 就在我们 肢体 中 发动,以致结成 死亡的 果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, '但 我们既然 在 捆 我们的律法上死了,现今就脱离了 律法,叫 我们 服事主,要按著 心灵(心灵:或译圣灵)的新样, 不 按著仪文 的旧样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, '这样,我们可说 什么呢?律法 是罪吗?断乎不是!只是 非 因 律法,我就不 知 何为罪。非 律法 说「不可 起贪心」, 我就不 知 何为贪心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, '然而,罪 趁著 机会,就藉 借著 诫命 叫诸般的 贪心 在我 里头 发动;因为 没有 律法,罪 是死的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, ' 我 以前 没有 律法 是活著的;但是 诫命 来到,罪 又活了,我 就 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, ' 那 本来叫 人活 的诫命,反倒 叫 我 死; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, '因为 罪 趁著 机会,就藉 借著 诫命 引诱 我,并且 杀了我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, '这样看来, 律法 是圣洁的,诫命 也是 圣洁、 公义、 良善的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, '既然如此,那良善的 是叫 我 死吗?断乎不是!叫我死的乃是 罪。但罪藉 借著 那良善的 叫 我 死,就 显出 真是罪,叫 罪 因著 诫命 更显出是 恶 极了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, ' 我们原晓得 律法 是 属乎灵的,但 我 是 属乎肉体的,是已经卖 给 罪了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, '因为 我所做的,我自己不 明白; 我所愿 意 的, 我并不 做; 我所恨恶 的, 我倒去做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, ' 若 我所做的, 是我所不 愿 意的,我就应承 律法 是善的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, ' 既是这样,就不是 我 做 的,乃是 住 在我 里头 的罪做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, ' 我也知道,在我 里头, 就是 我 肉体 之中,没有 良善。因为,立志 为善 由得 我,只是 行出来 由不得我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, '故此,我所愿 意的 善,我反不 做;我所 不 愿 意 的恶, 我倒 去做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, ' 若 我去做 所 不 愿 意做的,就不是 我 做 的,乃是 住 在我 里头 的罪做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, '我 觉得 有个律,就是 我 愿 意 为 善的时候,便有恶 与我 同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, '因为 按著 我里面的意思(原文是人),我是喜欢 神的 律; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, '但 我觉得 肢体 中 另有 个律 和我 心中的 律 交战 , 把我 掳去,叫我附从那 肢体 中 犯罪 的律。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, '我真是 苦啊!谁 能救 我 脱离 这 取死 的身体呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, ' 感谢 神,靠著 我们的 主 耶稣 基督就能脱离了。这样看来,我 以内心 顺服 神的 律,我肉体 却 顺服罪 的律了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, ' 如今,那些在基督 耶稣 里 的就不 定罪了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, '因为 赐生命 圣灵 的律,在基督 耶稣 里 释放了 我,使我脱离 罪 和 死 的律了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, ' 律法 既 因 肉体 软弱,有所不能行的, 神 就差遣 自己的 儿子,成为 罪 身 的形状,作了赎罪祭,在肉体 中 定了 罪案, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, '使 律法的 义 成就 在 我们 这不 随从 肉体、只 随从 圣灵的人身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, '因为,随从 肉体 的人 体贴 肉体 的事; 随从 圣灵 的人体贴圣灵 的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, ' 体贴 肉体的,就是死;体贴 圣灵的,乃是 生命、 平安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, '原来 体贴 肉体的,就是与 神 为仇;因为 不 服 神的 律法,也是 不 能服, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, '而且 属 肉体 的人不 能得 神 的喜欢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, '如果 神的 灵 住 在 你们心里,你们 就 不 属 肉体,乃 属 圣灵了。人 若 没 有 基督 的灵, 就 不 是 属基督的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, '基督 若 在 你们心里,身体 就 因 罪 而死,心灵 却 因 义 而活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, '然而,叫耶稣 从 死里 复活 者的灵 若 住 在 你们心里,那叫基督 耶稣从 死里 复活的,也 必藉 借著 住 在 你们 心里的 圣灵,使你们 必死的 身体 又活过来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, '弟兄们,这样看来,我们并不 是 欠肉体 的债 去顺从 肉体 活著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, ' 你们若 顺从 肉体 活著,必要 死; 若 靠著圣灵 治死 身体的 恶行,必要活著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, '因为 凡被 神 的灵 引导的, 都是 神 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, ' 你们所受的,不是 奴仆 的心,仍旧 害怕;所受的,乃是 儿子 的心,因 此 我们呼叫:「阿爸!父!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, '圣灵 与我们的 心 同证 我们是 神的 儿女; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, ' 既是 儿女,便是 后嗣,就是 神的 后嗣,和 基督 同作后嗣。如果 我们和他一同受苦, 也 必和他一同得荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, ' 我想, 现在 的苦楚 若比起 将来要 显 于  我们 的荣耀 就不 足介意了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, ' 受造之物 切望 等候 神的 众子 显出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, '因为 受造之物 服 在虚空之下,不是 自己愿 意,乃是 因 那叫他如此的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, '但 受造之物 仍然 指望脱离 败坏 的辖制,得享(享:原文是入) 神 儿女 自由 的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, ' 我们知道,一切 受造之物 一同叹息, 劳苦,直到 如今。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, ' 不 但如此,就是 我们 这 有 圣灵 初结果子的,也是 自己 心里 叹息,等候 得著儿子的名分,乃是我们的 身体 得赎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, ' 我们得救 是在乎盼望;只是 所见的 盼望 不 是 盼望, 谁 还盼望 他所见 的呢(有古卷:人所看见的何必再盼望呢)? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, '但 我们若 盼望 那 所不 见的,就必 忍耐 等候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, ' 况且,我们的 软弱 有 圣灵 帮助; 我们本不 晓得 当 怎样 祷告,只是 圣灵 亲自 用说不出来的 叹息 替我们祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, ' 鉴察 人心的,晓得 圣灵 的意思,因为 圣灵照著 神 的旨意替 圣徒 祈求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, ' 我们晓得 万事 都互相效力,叫 爱 神 的人得益处,就是 按 他旨意 被召的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, '因为 他预先所知道的 人,就 预先定下 效法 他 儿子 的模样,使 他儿子 在许多 弟兄 中 作 长子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, ' 预先所定下的 人 又 召 他们来; 所召来的 人 又 称他们 为义; 所称为义的 人 又 叫他们 得荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, '既是这样,还有什么 说 的呢? 神 若 帮助 我们,谁 能敌挡 我们呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, '神 既 不 爱惜 自己的 儿子, 为 我们 众人 舍了,岂 不 也把万物 和 他 一同 白白地赐给 我们吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, '谁 能控告 神 所拣选的人呢?有 神 称他们为义了(或译:是称他们为义的 神吗)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, '谁 能定他们的罪呢?有基督 耶稣已经死了, 而且 从死里复活, 现今 在 神的 右边, 也 替 我们 祈求(有基督....或译:是已经死了,而且从死里复活,现今在 神的右边,也替我们祈求的基督耶稣吗)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, '谁 能使我们 与 基督 的爱 隔绝呢?难道是患难吗?是 困苦吗?是 逼迫吗?是 饥饿吗?是 赤身露体吗?是 危险吗?是 刀剑吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, '如 经上所记: 我们为你 的缘故 终日 被杀;人看 我们如 将宰的 羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, '然而,靠著 爱 我们的主,在 这一切的 事 上已经得胜有余 馀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, '因为 我深信 无论是 死,是 生,是 天使,是 掌权的,是 有能的,是 现在的事,是 将来的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, '是 高处的,是 低处的,是 别的 受造之物,都不能 叫我们 与 神 的爱 隔绝;这爱是在我们的 主 基督 耶稣 里的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, '我在基督 里 说 真话,并不 谎言,有我 良心 被圣 灵 感动,给我 作见证: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, ' 我 是大 有 忧愁, 心里 时常 伤痛; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, '为 我 弟兄,我 骨肉之 亲,就是 自己 被咒诅,与基督 分离,我也愿 意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, '他们 是 以色列人;那儿子的名分、 荣耀、 诸约、 律法、 礼仪、 应许 都是他们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, '列祖 就是他们的祖宗;按 肉体说,基督 也是 从 他们出来的。他是 在万有 之上, 永远 可称颂的 神。阿们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, '这 不是 说 神 的话 落了空。因为 从以色列 生的 不 都是 以色列人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, '也不 因为 是 亚伯拉罕 的后裔 就都 作他的儿女;惟独「从 以撒 生的才要称为 你的 后裔。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, '这 就是说,肉身 所生的儿女 不是 神的 儿女,惟独 那应许的 儿女 才算 是 后裔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, '因为 所应许 的话 是这样说:「到 明年这 时候 我要来, 撒拉 必生 一个儿子。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, ' 不 但如此,还有 利百加,既 从 一个人,就是从我们的 祖宗 以撒 怀了孕, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, '( 双子还没有 生下来, 善 恶 还没有 做出来,只因要 显明 神 拣选 人的旨意,不 在乎 人的行为,乃 在乎 召人的主。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, ' 神就对利百加 说:「将来,大的 要服事 小的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, '正如 经上所记:雅各 是我所爱的; 以扫 是我所恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, '这样,我们可说 什么呢?难道 神 有 什么不公平吗?断乎没有! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, '因 他对摩西 说:我要怜悯 谁 就怜悯 谁, 要恩待 谁 就恩待 谁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, '据此看来,这不在乎 那定意的,也不在乎 那奔跑的,只在乎 发怜悯的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, '因为 经上 有话向法老 说:「我将你 兴起来, 特要在 你 身上彰显 我的 权能,并 要使 我的 名 传 遍 天下。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, '如此看来, 神要 怜悯 谁就怜悯谁, 要 叫谁刚硬 就叫谁刚硬。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, '这样,你必对我 说:「他为什么 还 指责人呢? 有谁 抗拒 他的 旨意呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, ' 你这个人 哪,你 是 谁,竟敢向 神 强嘴呢?受造之物 岂能 对造他的 说:「你为什么 这样 造 我呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, '窑匠 难道 没 有 权柄 从 一团泥 里 拿一块 做 成 贵重的 器皿,又 拿一块 做成 卑贱的器皿吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, ' 倘若 神 要 显明 他的忿怒, 彰显 他的 权能,就 多多 忍耐 宽容 那可怒、预备 遭 毁灭 的器皿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, '又 要 将他 丰盛的 荣耀 彰显 在 那蒙怜悯、早预备 得 荣耀 的器皿上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, '这 器皿就是 我们被 神所召的,不 但是 从犹太人 中, 也是 从外邦人 中。这有什么不可呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, ' 就像 神在 何西阿 书上说:那本来不是 我 子民的,我要称为「我的 子民」; 本来不是 蒙爱的,我要称为「蒙爱的」。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, ' 从前 在 什么地方 对他们 说:你们 不是 我的 子民,将来就在那里 称他们为「永生 神的 儿子」。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, ' 以赛亚 指著 以色列人 喊著说:「以色列 人 虽 多如 海 沙,得救的 不过是剩下的余 馀数; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, '因为 主 要在 世上 施行 他的话,叫他的话都成全,速速地 完结。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, '又 如 以赛亚 先前说过:若 不是 万军之 主 给我们 存留 余 馀种,我们 早已 像 所多玛、 蛾摩拉 的 样子了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, '这样,我们可说 什么呢? 那 本来不 追求 义 的外邦人 反得了 义,就是 因 信 而得的义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, '但 以色列人 追求 律法的 义,反得 不著 律法的义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, '这是什么缘故呢?是因为 他们不 凭著 信心求,只 凭著 行为求;他们正跌 在那绊脚 石上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, '就如 经上所记: 我在 锡安 放 一块绊脚的 石头, 跌人的 磐石; 信 靠 他 的人必不至于  羞愧。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, '弟兄们,我 心里 所愿 的, 向 神 所求的,是要 以色列人 得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, ' 我可以证明,他们向 神 有 热心,但 不是 按著 真知识; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, '因为 不知道 神的 义, 想要 立 自己的 义,就不 服 神的 义了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, ' 律法的 总结 就是基督,使 凡 信 他的都得著义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, ' 摩西 写著说:「 人 若行 那 出于  律法 的义,就必因 此 活著。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, '惟有 出于  信心 的义 如此 说:「你不要 心 里 说:谁 要升 到 天上去呢?( 就是要 领下 基督来;) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, ' 谁 要下 到 阴间去呢?( 就是要 领 基督 从 死里上来。)」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, '他到底 怎么 说呢?他说:这道 离你 不远,正在 你 口里, 在 你 心里─( 就是 我们所传 信 主的道。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, ' 你 若 口里 认 耶稣 为主, 心 里 信 神 叫他 从 死里 复活,就必得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, '因为,人心里 相信 就可以 称义, 口里 承认 就可以 得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, ' 经上 说:「凡 信 他 的人必不至于  羞愧。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, ' 犹太人 和 希腊人 并没 有 分别,因为 众人 同有一位 主;他也厚待 一切 求告 他的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, '因为「凡 求告 主 名 的就必得救」。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, '然而, 人 未曾 信他,怎能 求他呢? 未曾 听见他,怎能 信他呢? 没有 传道的,怎能 听见呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, ' 若 没有 奉差遣,怎能 传道呢?如 经上所记:「报福音、传喜信的人,他们的 脚踪何等 佳美!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, '只是 人没有 都 听从 福音,因为 以赛亚 说:「主啊,我们 所传的 有谁 信呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, '可见,信道 是从 听道来的, 听道 是从 基督 的话来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, '但 我说,人没有 听见吗?诚然听见了。他们的 声音 传遍 天下; 他们的 言语 传到 地 极。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, ' 我再说,以色列人 不 知道吗?先有 摩西 说:我 要用 那不成 子民 的惹动你们的 愤恨;我要用 那无知的 民 触动你们的 怒气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, '又有 以赛亚 放胆 说: 没有 寻找 我的,我叫他们遇见;没有 访问 我的,我向 他们显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, '至于  以色列人,他说:「我 整 天 伸 手 招呼 那悖逆 顶嘴的 百姓。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, '我且 说, 神 弃绝了 他的 百姓吗?断乎没有!因为 我 也 是 以色列人,亚伯拉罕 的 后裔,属便雅悯 支派的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, '神 并没有 弃绝 他 预先所知道的 百姓。 你们岂不 晓得 经上 论 到 以利亚 是怎么说的呢?他在 神 面前怎样 控告 以色列人说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, '「主啊,他们杀了 你的 先知,拆了 你的 祭坛,只剩下 我 一个人;他们还要 寻索 我的 命。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, ' 神的回话 是怎么 说的呢?他说:「我为自己 留下 七千 人, 是未曾 向巴力 屈 膝的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, ' 如今 也是这样,照著 拣选的 恩典,还 有 所留的余 馀数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, ' 既是 出于 恩典,就不 在乎 行为;不然,恩典 就不 是 恩典了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, '这是 怎么样呢?以色列人 所求的,他们没有 得著。惟有 蒙拣选的 人得著了; 其余 馀的 就成了顽梗不化的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, '如 经上所记: 神 给 他们 昏迷的 心,眼睛 不能 看见, 耳朵 不能 听见,直到 今 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, '大卫 也 说:愿 他们的 筵席 变 为 网罗, 变为 机槛, 变为 绊脚石, 作他们的 报应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, '愿 他们的 眼睛 昏蒙,不得 看见; 愿 你时常 弯下 他们的 腰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, '我且 说, 他们失脚 是要 他们跌倒吗?断乎不是!反倒 因他们的 过失,救恩 便临到外邦人,要 激动他们 发愤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, ' 若 他们 的过失 为天下 的富足, 他们的 缺乏 为外邦人的 富足,何况 他们的 丰满呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, ' 我对你们 外邦人 说这话;因 我 是 外邦人的 使徒,所以敬重(原文是荣耀)我的 职分, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, '或者 可以激动我 骨肉之亲 发愤,好 救 他们 一些人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, ' 若 他们 被丢弃,天下就得与 神和好,他们 被收纳,岂不是 死 而 复生吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, ' 所献的新面 麺 若是 圣洁,全团 也就圣洁了; 树根 若是 圣洁,树枝 也就圣洁了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, ' 若 有 几根枝子 被折下来, 你 这 野橄榄 得接 在其 中, 一同得著 橄榄 根 的肥汁, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, '你就不可 向旧枝子 夸口; 若是 夸口,当知道不是 你 托著 根,乃是 根 托著你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, '你若 说,那枝子 被折下来 是特为叫 我 接上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, '不错!他们因为不信,所以被折下来; 你 因为信,所以立得住;你不可 自高,反要 惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, ' 神 既 不 爱惜 原来的 枝子, 也 必不 爱惜 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, '可见, 神的 恩慈 和 严厉 向 那跌倒的 人是严厉的, 向 你 是有恩慈的,只要 你长久 在他的恩慈里;不然,你 也要 被砍下来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, '而且 他们 若 不是 长久 不信,仍要被接上,因为 神 能够 把他们 重新 接上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, ' 你 是从 那 天生的 野橄榄 上砍下来的,尚且 逆著 性 得接 在 好橄榄上,何况 这 本树的枝子,要接 在本 树上呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, '弟兄们, 我不 愿 意 你们 不知道 这 奥秘(恐怕 你们 自 以为 聪明),就是 以色列人 有几分 是 硬心的,等到 外邦人 的数目添 满了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, ' 于 是 以色列 全家 都要得救。如 经上所记:必有一位救主 从 锡安 出来,要消除 雅各 家的一切罪恶; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, '又说:我除去 他们 罪 的时候, 这 就是 我 与他们 所立的约。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, '就著 福音说,他们为你们的 缘故 是仇敌; 就著 拣选说,他们为列祖的 缘故 是蒙爱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, '因为 神的 恩赐 和 选召 是没有后悔的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, ' 你们 从前 不顺服 神, 如今 因 他们的不顺服,你们倒蒙了怜恤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, '这样,他们 也是 不顺服,叫 他们因著施给你们的 怜恤,现在 也就 蒙怜恤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, '因为 神 将众人 都圈 在不顺服 之中,特意要 怜恤 众人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, '深 哉, 神 丰富的 智慧 和 知识!他的 判断 何其 难测! 他的 踪迹 何其难寻! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, ' 谁 知道 主 的心? 谁 作过 他的 谋士呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, ' 谁 是先给了 他,使 他 后来偿还呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, '因为 万有 都是本于  他, 倚靠 他, 归于  他。愿 荣耀 归给他,直到 永远。阿们!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, '所以,弟兄们,我以 神的 慈悲 劝 你们,将 身体 献上,当作活 祭,是圣洁的,是 神 所喜悦的;你们如此事奉 乃是理所当然的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, ' 不要 效法 这个 世界,只要 心意 更新 而变化,叫 你们 察验 何为 神的 善良、 纯全、 可喜悦的 旨意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, ' 我凭著 所赐 我的 恩 对你们 各人 说:不要 看自己过于  所当 看的; 要照著 神 所分给 各人 信心 的大小,看得 合乎 中道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, ' 正如 我们一个 身子 上有 好些 肢体, 肢体 也不 都是 一样的 用处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, ' 我们这许多人,在基督 里 成为 一 身, 互相 联络 作肢体,也是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, ' 按 我们 所得的 恩赐,各有 不同。或 说预言,就当照著 信心 的程度说预言; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, '或 作执事,就当专一 执事;或 作教导的,就当专一 教导; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, '或 作劝化的,就当专一 劝化;施舍的,就当 诚实;治理的,就当 殷勤;怜悯人的,就当 甘心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, '爱 人不可虚假。恶,要厌恶;善,要亲近。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, '爱弟兄,要 彼此 亲热;恭敬人,要彼此 推让。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, '殷勤,不可 懒惰;要心 里火热,常常服事 主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, '在指望 中要喜乐;在患难 中要忍耐;祷告 要恒切。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, '圣徒 缺乏,要帮补;客,要一味地款待。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, '逼迫 你们的,要给他们祝福;只要祝福, 不可 咒诅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, '与 喜乐的人 要同乐;与 哀哭的人 要同哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, '要彼此 同 心;不要 志气 高大,倒要 俯就 卑微的人(人:或译事)。不 要 自 以 为聪明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, '不 要 以恶 报 恶;众 人 以为 美的事 要留心去做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, '若 是能行,总要 尽力与 众 人 和睦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, '亲爱的弟兄,不要 自己 伸冤,宁 可让步,听凭主怒(或译:让人发怒);因为 经上记著:「主 说:『伸冤 在我,我 必报应。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, '所以,「你的 仇敌 若 饿了,就给他 吃,若 渴了,就给他 喝;因为 你这样 行 就是把炭 火 堆在 他的 头上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, '你不可 为 恶 所胜,反要 以 善 胜 恶。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, '在上 有权柄的,人人 当顺服他,因为 没 有 权柄 不是 出于  神的。凡 掌权的 都是 神 所命的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, '所以,抗拒 掌权 的就是抗拒 神的 命; 抗拒的 必自 取 刑罚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, ' 作官 的原不 是 叫行善的 惧怕,乃 是叫作恶的惧怕。 你愿 意 不 惧怕 掌权的吗?你只要行 善, 就可得 他 的 称赞; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, '因为 他是 神的 用人,是与 你 有益的。 你若 作 恶,却当惧怕;因为 他不 是 空空地 佩剑; 他是 神的 用人,是伸冤的,刑罚 那 作 恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, '所以,你们必须 顺服,不 但 是因为 刑罚,也是 因为 良心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, '你们纳 粮,也 为 这个 缘故;因 他们是 神的 差役,常常 特管 这 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, '凡人 所当得的,就给他。当得粮的,给他 纳粮;当得税的,给他 上税;当惧怕的,惧怕 他;当恭敬的,恭敬 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, '凡事 都不可亏欠 人,惟有 彼此 相爱要常以为亏欠,因为 爱 人 的就完全了 律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, ' 像那不可 奸淫,不可 杀人,不可 偷盗,不可 贪婪, 或 有 别的 诫命,都包 在 爱 人 如 己 这 一句话 之内了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, '爱 是不 加 害 与人的,所以 爱 就完全了 律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, '再者,你们 晓得,现今 就是该趁早睡醒 的时候;因为 我们 得救,现今 比 初信 的时候 更近了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, '黑夜 已深, 白昼 将近。我们就当 脱去 暗昧的 行为, 带上 光明的 兵器。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, '行事为人 要端正,好像 行在 白昼。不可 荒宴 醉酒;不可 好色 邪荡;不可 争竞 嫉妒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, '总要 披戴 主 耶稣 基督, 不 要 为 肉体 安排,去放纵私欲。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, '信心 软弱的,你们要接纳,但 不要 辩论 所疑惑的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, ' 有人 信 百物 都可吃;但 那软弱的,只吃 蔬菜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, '吃的人 不可 轻看 不 吃的人; 不 吃的人 不可 论断 吃的人;因为 神 已经收纳 他了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, '你 是 谁,竟论断 别人的 仆人呢?他或站住 或 跌倒,自有他的 主人在;而且 他也必要站住,因为 主 能 使他 站住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, ' 有 人 看 这日 比那日 强; 有人 看 日日都是一样。只是各人 心里 要意见坚定。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, '守 日 的人是为主 守的。 吃的人 是为主 吃的,因 他感谢 神; 不 吃的人 是为主 不 吃的,也 感谢 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, ' 我们 没有一个人 为自己 活,也 没有一个人 为自己 死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, ' 我们若 活著,是为主 而活;若 死了,是为主 而死。所以,我们或 活 或 死 总是 主的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, ' 因 此,基督 死了,又 活了,为要作 死人 并 活人 的主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, ' 你这个人,为什么 论断 弟兄呢?又 为什么 轻看 弟兄呢?因 我们都要站在 神 的台 前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, ' 经上写著:主 说:我 凭著我的永生起誓: 万 膝 必向我 跪拜; 万 口 必向我 承认。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, '这样看来,我们 各人 必要将 自己的事在 神 面前说明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, '所以,我们不可再 彼此 论断,宁可 定意 谁也不给 弟兄 放下 绊脚 跌人之物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, '我凭著 主 耶稣 确知 深信, 凡物本来 没有 不洁净的;惟独 人以为 不洁净的,在他 就不洁净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, ' 你 若 因 食物 叫弟兄 忧愁,就不是 按著 爱人的道理 行。基督 已经替 他 死,你不可 因你的 食物 叫他 败坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, '不可 叫 你的 善 被人毁谤; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, '因为 神 的国 不 在乎 吃 喝,只 在乎公义、 和平,并 圣 灵 中 的喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, ' 在这几样 上 服事 基督的,就为 神 所喜悦,又 为人 所称许。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, '所以,我们务要追求 和睦的事 与 彼此 建立德行的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, '不可 因 食物 毁坏 神的 工程。凡物 固然 洁净,但 有人 因 食物 叫人跌倒,就是他的罪了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, '无论是 吃 肉 是 喝 酒,是什么别的事,叫 弟兄 跌倒,一概不做才好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, ' 你 有 信心,就当在 神 面前 守著。人在 自己以为可行 的事 上能不 自 责,就有福了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, ' 若 有疑心 而吃的,就必有罪,因为 他吃不是 出于  信心。 凡 不 出于  信心 的都是 罪。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, ' 我们 坚固的人 应该 担代 不坚固人 的软弱, 不 求自己的 喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, '我们 各人 务要叫邻舍 喜悦,使 他得益处, 建立德行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, '因为 基督 也 不 求自己 的喜悦, 如 经上所记:「辱骂 你 人的辱骂 都落 在 我身上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, ' 从前所写的 圣经 都是为 教训 我们 写的,叫 我们因 圣经 所生的忍耐 和 安慰 可以得著 盼望。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, ' 但愿 赐忍耐 安慰的 神 叫 你们 彼此 同心,效法 基督 耶稣, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, ' 一心 一 口 荣耀 神─ 我们 主 耶稣 基督 的父! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, '所以,你们要彼此 接纳, 如同基督 接纳 你们 一样,使 荣耀归与 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, ' 我说,基督 是 为 神 真理 作了受割礼人 的执事,要 证实 所应许 列祖的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, '并叫 外邦人 因 他的怜悯 荣耀 神。如 经上所记:因 此,我要在外邦 中 称赞 你, 歌颂 你的 名; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, ' 又 说:你们外邦人 当与主的 百姓 一同 欢乐; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, ' 又说: 外邦啊,你们当赞美 主! 万 民哪,你们都当颂赞 他! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, ' 又有 以赛亚 说:将来有 耶西 的根,就是 那兴起来 要治理 外邦的;外邦人 要仰望 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, '但愿  使人有盼望的 神,因 信 将诸般的 喜乐、 平安 充满 你们的心,使 你们 藉 借著 圣 灵 的能力 大有 盼望! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, ' 弟兄们,我 自己 也 深信 你们 是 满有 良善,充足了 诸般的 知识,也 能 彼此 劝戒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, '但 我稍微放胆 写信给 你们,是要 提醒你们的 记性,特因 神 所 给 我 的恩典, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, '使我 为 外邦人 作 基督 耶稣 的仆役,作 神 福音 的祭司,叫 所献上的 外邦人,因著 圣 灵 成为圣洁,可 蒙悦纳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, '所以论到 神的事,我在 基督 耶稣 里有 可夸的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, ' 除了 基督 藉 借我做的 那些事,我什么都不 敢 提,只提他藉 借 我 言语 作为,用 神迹 奇事 的能力,并 圣灵 的能力,使 外邦人 顺服; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, '甚至 我 从 耶路撒冷, 直转 到 以利哩古,到处传了 基督的 福音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, ' 我立了志向,不 在基督 的名被称过 的地方 传福音,免得 建造 在别人的 根基 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, ' 就如 经上所记: 未曾 闻知 他信息 的,将要看见; 未曾 听过的,将要明白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, ' 我因 多次 被拦阻,总不得到 你们 那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, '但 如今,在 这里 再没 有 可传的地方,而且 这好几 年,我切心想望 到 西班牙去的时候,可以到 你们那里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, '盼望 从你们那里经过, 得见 你们,先 与 你们彼此交往, 心里稍微 满足,然后 蒙 你们 送行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, '但 现在,我往 耶路撒冷 去 供给 圣徒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, '因为 马其顿 和 亚该亚人 乐意 凑出 捐项 给 耶路撒冷 圣徒 中的穷人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, '这固然 是他们乐意的, 其实也算是 所欠的债;因 外邦人 既然 在他们 属灵的 好处上有分,就 当 把 养身之物 供给 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, '等 我办完了 这事, 把这 善果 向他们 交付明白,我就要路过 你们那里,往 西班牙去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, ' 我也晓得,去 的时候必带著 基督 丰盛的 恩典 而去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, ' 弟兄们,我藉 借著 我们主 耶稣 基督,又 藉 借著 圣灵 的爱,劝 你们 与我 一同竭力,为 我 祈求 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, '叫我脱离 在 犹太 不顺从的人,也 叫 我 为 耶路撒冷 所办的捐项 可 蒙圣徒 悦纳, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, '并叫 我顺著 神 的旨意, 欢欢喜喜地 到 你们那里,与你们 同得安息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, '愿  赐平安的 神 常和你们 众人 同在。阿们!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, ' 我对你们 举荐 我们的 姊妹 非比;她是 坚革哩 教会 中的女执事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, '请 你们为 主 接待 她,合乎 圣徒的体统。她在何 事 上 要你们 帮助,你们就 帮助 她;因 她 素来 帮助 许多人, 也 帮助了我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, '问百基拉 和 亚居拉 安。他们在 基督 耶稣 里与我 同工, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, ' 也为 我的 命 将自己的 颈项 置之度外。不 但 我 感谢 他们,就是 外邦的 众 教会 也感谢他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, '又 问在他们 家 中 的教会安。问我 所亲爱的 以拜尼土 安;他 在亚细亚 是 归 基督 初结的果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, '又问马利亚 安;她 为 你们 多受 劳苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, '又问我 亲属 与我 一同 坐监的 安多尼古 和 犹尼亚 安;他们 在使徒 中 是 有名望的, 也 是 比我 先 在基督 里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, '又问我 在主 里面 所亲爱的 暗伯利 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, '又问在基督 里 与我们 同工 的耳巴奴,并 我 所亲爱的 士大古 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, '又问在基督 里 经过试验的 亚比利 安。问亚利多布 家里的 人 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, '又问我 亲属 希罗天 安。问拿其数 家 在主 里 的 人 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, '又问为 主 劳苦 的土非拿氏 和 土富撒氏 安。问可亲爱 为 主 多 受劳苦 的彼息氏 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, '又问在 主 蒙拣选的 鲁孚 和 他 母亲 安;他的母亲就是 我的母亲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, '又问亚逊其土、弗勒干、黑米、八罗巴、黑马,并 与他们 在一处的 弟兄们 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, '又问非罗罗古 和 犹利亚,尼利亚 和 他 姊妹,同 阿林巴 并 与他们 在一处的 众 圣徒 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, '你们 亲嘴 问安,彼此务要圣洁。基督 的众 教会 都问你们 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, ' 弟兄们,那些离间你们、 叫你们跌倒、背乎 所学 之道的人,我劝 你们 要留意 躲避 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, '因为 这样的人 不 服事 我们的 主 基督,只 服事自己的 肚腹, 用 花言 巧语 诱惑 那些老实人 的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, ' 你们的 顺服 已经传 于  众人,所以 我为 你们 欢喜;但 我愿 意 你们 在 善 上 聪明, 在恶 上 愚拙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, ' 赐平安的 神 快要 将撒但 践踏 在你们 脚 下。愿 我 主 耶稣 基督的恩 常和你们 同在! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, '与我 同 工的提摩太,和 我的 亲属 路求、 耶孙、 所西巴德,问你们 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, '我 这代笔写 信 的德提,在主 里面 问你们 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, '那接待 我、也 接待全 教会 的该犹 问你们 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, '城内 管银库的 以拉都 和 兄弟 括土 问你们 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, '惟有 神能 照 我 所传的福音 和 所讲的 耶稣 基督,并照 永 古 隐藏不言 的奥秘,坚固 你们的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, ' 这奥秘如今 显明出来,而且 按著 永生 神 的命,藉 借 众先知 的书 指示 万 国的民,使 他们信服 真道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, ' 愿 荣耀,因 耶稣 基督,归与独一 全智的 神,直到 永远。阿们!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, '奉 神 旨意,蒙召 作耶稣 基督 使徒 的保罗,同 兄弟 所提尼, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, '写信给在哥林多 神 的教会,就 是 在 基督 耶稣 里 成圣、蒙召 作圣徒的,以及 所有 在 各 处 求告 我 主 耶稣 基督 之名的人。基督是他们的主,也 是我们的主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, '愿 恩惠、 平安 从 神 我们的 父 并 主 耶稣 基督 归与你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, '我常 为你们 感谢 我的 神,因 神 在 基督 耶稣 里 所 赐给 你们 的恩惠; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, '又因 你们在 他 里面 凡事 富足, 口才、 知识 都全备, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, '正如 我为基督 作的见证,在 你们 心里得以坚固, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, '以致 你们 在恩赐 上 没有 一样不及人的,等候 我们的 主 耶稣 基督 显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, '他 也 必坚固 你们 到 底,叫你们在 我们 主 耶稣 基督 的日子 无可责备。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, '神 是信实的,你们原是被 他 所召,好与 他 儿子─我们的 主 耶稣 基督 一同得分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, '弟兄们, 我藉 借 我们 主 耶稣 基督 的名 劝 你们 都 说 一样的话。 你们 中间 也 不 可 分党,只 要 一 心 一 意,彼此相合。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, '因为 革来氏 家 里的人曾对我 提 起 弟兄们来,说 你们 中间 有 纷争。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, ' 我的意思 就是 你们 各人 说:「我 是 属保罗的」;「 我 是属亚波罗的」;「 我 是属矶法的」;「 我 是属基督的」。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, '基督 是分开 的吗?保罗 为 你们 钉了十字架 吗? 你们是奉 保罗 的名 受了洗吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, '我感谢 神, 除了 基利司布 并 该犹以外,我没有给你们 一个人 施洗, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, '免得 有人 说,你们是 奉 我的 名 受洗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, ' 我也 给司提法那 家 施过洗,此外给别 人 施洗 没有,我却记 不清。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, ' 基督 差遣 我,原不 是为施洗,乃是 为传福音,并不 用 智慧 的言语,免得 基督 的十字架 落了空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, '因为 十字架 的道理,在那灭亡 的人 为 愚拙;在我们 得救的人,却 为 神 的大能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, '就如 经上所记:我要灭绝 智慧人 的智慧, 废弃 聪明人 的聪明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, '智慧人 在哪里?文士 在哪里?这 世 上的辩士 在哪里? 神 岂不 是叫这世 上的智慧 变成愚拙吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, '世 人凭 自己的智慧,既不 认识 神, 神 就乐意 用 人所当作愚拙 的道理 拯救 那些信的人;这 就 是 神 的智慧了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, ' 犹太人 是要 神迹, 希腊人 是求 智慧, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, '我们 却 是传 钉十字架 的基督,在犹太人 为 绊脚石, 在外邦人 为愚拙; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, '但 在那 蒙召 的, 无论是犹太人、 希腊人,基督总为 神 的能力, 神 的智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, '因 神 的愚拙 总 比人 智慧, 神 的软弱 总比人 强壮。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, '弟兄们哪,可 见 你们 蒙召的, 按著 肉体 有智慧 的不 多,有能力 的不 多,有尊贵 的也不 多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, '神 却 拣选了 世 上愚拙的,叫 有智慧 的羞愧;又 拣选了 世 上软弱的,叫 那强壮 的羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, '神 也 拣选了 世 上卑贱的,被人厌恶的,以及 那 无 有的,为 要废掉 那有的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, '使 一切 有血气的,在 神 面前 一个也不 能自夸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, '但 你们 得在 基督 耶稣 里 是本乎 神, 神 又使 他 成为 我们的 智慧、公义、 圣洁、 救赎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, '如 经上所记:「夸口的,当 指著 主 夸口。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, '弟兄们,从前我 到 你们 那里去, 并没 有用 高 言 大智 对你们 宣传 神 的奥秘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, '因为 我曾定了主意,在你们 中间 不 知道 别的,只 知道耶稣 基督 并 他 钉十字架。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, '我 在 你们那里,又 软弱,又 惧怕 又 甚 战 兢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, ' 我 说的话、 讲的道,不 是用 智慧 委婉 的言语,乃是 用 圣灵 和 大能 的明证, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, '叫 你们的 信 不 在乎 人 的智慧,只 在乎 神 的大能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, '然而,在完全 的人中,我们也讲 智慧。但 不 是这 世 上的智慧,也不是 这 世上有权有位、将要败亡 之人的智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, '我们讲的,乃是 从前所隐藏、 神 奥秘 的智慧,就是 神 在万世 以前 预定 使 我们 得荣耀的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, '这 智慧世 上有权有位的人 没有一个 知道的,他们 若 知道,就不 把荣耀 的主 钉在十字架上了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, ' 如 经上所记: 神 为爱 他 的人所预备 的 是眼睛 未 曾看见, 耳朵 未曾 听见, 人 心 也未曾 想到的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, '只有 神 藉 借著 圣灵 向我们 显明了,因为 圣灵 参透 万事,就是 神 深奥的事也参透了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, '除了 在 人 里头的灵, 谁 知道 人 的事? 像这样,除了 神 的灵,也没有人 知道 神 的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, ' 我们 所领受的,并 不 是世 上的灵,乃是从 神 来的 灵,叫 我们能知道 神 开 恩赐给 我们的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, '并且 我们讲说 这些事,不 是用 人 智慧 所指教 的言语,乃是 用圣灵 所指教的言语,将属灵的话解释 属灵 的事(或译:将属灵的事讲与属灵的人)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, '然而,属血气 的人 不 领会 神 圣灵 的事, 反倒 以为 愚拙,并且 不 能 知道,因为 这些事惟有属灵 的人才能看透。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, ' 属灵 的人能看透 万事,却 没有一人 能看透 了 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, ' 谁 曾知道 主 的心 去 教导 他呢?但 我们 是有 基督 的心了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, '弟兄们,我 从前对 你们说话,不 能 把你们当作 属灵的,只 得把你们当作 属肉体, 在 基督 里为婴孩的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, '我是用奶 喂 𫗭 你们,没有 用饭 喂 𫗭你们。那时你们不 能吃,就是如今 还 是不 能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, ' 你们仍 是 属肉体的,因为 在 你们中间 有 嫉妒、 纷争,这岂不是 属乎 肉体、 照著 世人 的样子行吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, ' 有 说:「我 是 属 保罗的」; 有说:「我 是属亚波罗的。」这岂不 是 你们和世人一样吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, ' 亚波罗 算 什么? 保罗 算 什么?无非是执事, 照 主 所赐给 他们各人的, 引导你们相信。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, '我 栽种了,亚波罗 浇灌了,惟有 神 叫他生长。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, '可见 栽种的,算 不 得什么,浇灌的,也算不得什么;只 在那叫他生长的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, ' 栽种 的和 浇灌的,都是 一样, 但将来各人 要照 自己 的工夫 得 自己 的赏赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, '因为 我们是与 神 同工的;你们是 神 所耕种的田地, 所建造的房屋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, '我照 神 所给 我 的恩, 好像 一个聪明 的工头,立好了 根基, 有别 人在上面建造;只是 各人 要谨慎 怎样 在上面建造。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, '因为 那 已经立 好的根基就是 耶稣 基督,此外 没有人 能 立 别 的根基。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, ' 若 有人 用金、银、宝 石、草 木、禾秸 在这根基 上 建造, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, '各人 的工程 必然 显露,因为 那日子 要将它表明出来, 有 火 发现; 这 火 要试验 各人 的工程 怎样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, ' 人 在那根基上所 建造 的工程 若存得住,他就要得 赏赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, ' 人 的工程 若被烧了,他就要受亏损,自己 却 要得救;虽然得救,乃 像 从 火 里经过的一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, '岂不 知 你们是 神 的殿, 神 的灵 住在 你们 里头吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, '若 有人 毁坏 神 的殿, 神 必要毁坏 那人;因为 神 的殿 是 圣的,这殿 就是 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, '人不 可自 欺。你们 中间 若 有人 在 这 世界 自以为 有 智慧,倒不如变作 愚拙,好 成为 有智慧的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, '因 这 世界 的智慧,在 神 看是 愚拙。如 经上记著说:「主叫 有智慧的,中了 自己的 诡计」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, ' 又说:「主 知道 智慧人 的意念 是 虚妄的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, '所以 无论谁,都不可拿 人 夸口,因为 万有 全是 你们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, '或 保罗,或 亚波罗,或 矶法,或 世界,或 生,或 死,或 现今的事,或 将来的事,全 是你们的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, '并且 你们 是属基督的,基督 又是属 神的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, '人 应当 以 我们 为 基督 的执事,为 神 奥秘事 的管家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, ' 所求 于  管家的,是 要 他 有忠心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, '我被 你们 论断,或 被 别人 论断, 我 都 以为 极小的事;连 我自己 也不 论断自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, ' 我虽不 觉得 自己有错,却 也不 能因此 得以称义;但 判断 我 的乃是 主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, '所以,时候 未到,什么都不要 论断,只等 主 来,他 要照出 暗 中的隐情, 显明 人心 的意念。 那时,各人 要 从 神 那里得著称赞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, ' 弟兄们,我为 你们的缘故,拿这些事 转比 自己 和 亚波罗,叫 你们效法 我们 不 可过于 圣经所 记,免得 你们 自高自大,贵重 这个,轻看 那个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, '使 你 与人不同 的是谁呢? 你有 什么 不 是 领受的呢?若 是领受的,为何 自夸,仿佛 不 是领受的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, ' 你们已经 饱足了!已经 丰富了!不用 我们,自己就作王了! 我愿 意 你们果真 作王,叫 我们 也 得与你们 一同作王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, ' 我想 神 把我们 使徒 明明列在 末后,好像 定死罪的囚犯;因为 我们成了 一台戏,给世 人 和 天使观看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, '我们 为基督 的缘故 算是愚拙的,你们 在 基督 里倒是 聪明的;我们 软弱,你们 倒 强壮;你们 有荣耀,我们 倒 被藐视。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, '直到 如今,我们还是 又饥 又 渴,又 赤身露体,又 挨打,又 没有一定的住处, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, '并且 劳苦,亲 手 做工。被人咒骂,我们就祝福;被人逼迫,我们就忍受; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, '被人毁谤,我们就善劝。直到 如今,人还把我们看 作 世界 上的污秽,万物 中的渣滓。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, '我写 这话,不 是叫你们 羞愧,乃是 警戒你们,好像 我 所亲爱 的儿女一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, ' 你们学 基督的,师傅 虽 有 一万,为父 的却 是不 多,因 我 在基督 耶稣 里 用 福音 生了 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, '所以,我求 你们 效法 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, '因 此 我已打发 提摩太 到你们那里去。他 在 主里面,是 我 所亲爱、 有忠心 的儿子。他 必提醒 你们,记念我 在 基督 里怎样 行事, 在 各处 各 教会 中怎样教导人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, ' 有些 人自高自大,以为 我 不 到 你们 那里去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, '然而,主 若 许我,我必快 到 你们 那里去,并且 我所要知道的,不 是那些自高自大 之人的言语,乃 是他们的权能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, '因为 神 的国 不在乎 言语,乃 在乎 权能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, '你们 愿 意怎么样呢?是愿 意我带著 刑杖 到 你们 那里去呢?还是 要我存 慈爱 温柔 的心呢?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, '风 闻 在你们 中间 有淫乱的事。 这样 的淫乱 连 外邦人 中 也没有,就是 有人 收了 他的继母。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, '你们 还 是 自高自大,并 不 哀痛,把 行 这 事 的人从 你们 中间 赶出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, ' 我 身子 虽不在你们那里,心 却 在你们那里,好像 我亲自与你们同在, 已经 判断了 行 这事的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, '就是你们 聚会的时候, 我的 心也同在。奉 我们 主 耶稣 的名,并用 我们 主 耶稣 的权能, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, '要把这样的人 交给 撒但, 败坏 他的肉体,使 他的灵魂 在 主 耶稣的日子 可以得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, '你们 这自夸 是不 好的。岂不 知 一点 面 麺酵 能使全 团 发起来吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, '你们 既是 无酵的面 麺,应当把旧 酵 除净,好 使你们成为 新 团;因为 我们 逾越节 的羔羊基督 已经 被杀献祭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, '所以,我们守这节 不 可用 旧 酵,也不 可用 恶毒(或译:阴毒)、 邪恶 的酵,只 用 诚实 真正 的无酵饼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, '我先前写 信 给你们说,不 可与淫乱的人 相交。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, ' 此话不 是指这 世 上一概 行淫乱的,或 贪婪的,勒索的,或 拜偶像的;若是这样, 你们除非 离开  世界方可。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, '但 如今 我写 信给你们说,若 有称为 弟兄 是 行淫乱的,或 贪婪的,或 拜偶像的,或 辱骂的,或 醉酒的,或 勒索的,这样的人 不 可与他相交,就是与他 吃饭 都不可。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, '因为 审判 教外 的人与我 何干?教内 的人岂不 是你们 审判的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, '至于  外人有 神 审判他们。你们应当把那 恶人 从 你们 中间赶出去。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, '你们 中间有 彼此 相争的事,怎 敢 在不义的人 面前 求审, 不 在圣徒 面前求审呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, '岂 不 知 圣徒 要审判 世界吗? 若 世界 为 你们 所审,难道你们 不配 审判 这最小的事吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, '岂不 知 我们要审判 天使吗?何况 今生的事呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, '既是 这样,你们若 有 今生 的事当审判,是派 教会 所轻看 的人审判吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, '我说 这话是要 叫你们 羞耻。难道 你们 中间 没 有 一个智慧人 能 审断 弟兄们的事吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, ' 你们竟是弟兄 与 弟兄 告状,而且 告在不信 主的人面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, ' 你们彼 此 告状, 这已经 是 你们 的大 错了。为什么 不 情愿  受欺呢?为什么 不 情愿  吃亏呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, '你们 倒是欺压人、 亏负人, 况且 所欺压所亏负的就是 弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, '你们岂 不 知 不义 的人不 能承受 神 的国吗?不 要自欺!无论 是淫乱的、 拜偶像的、 奸淫的、 作娈童的、 亲男色的、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, ' 偷窃的、 贪婪的、 醉酒的、 辱骂的、 勒索的,都不能承受 神 的国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, '你们 中间也 有人从前是 这样;但 如今你们奉 主 耶稣 基督 的名,并藉 借著 我们 神 的灵,已经洗净, 成圣, 称义了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, '凡事 我 都可行,但 不 都有益处。凡事 我 都可行,但无论哪一件,我 总不 受 它的 辖制。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, '食物 是为肚腹, 肚腹 是为食物;但 神 要叫这两样 都废坏。 身子 不 是为淫乱,乃 是为主; 主 也是为身子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, '并且 神 已经 叫主 复活,也 要用 自己 的能力 叫我们 复活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, '岂不 知 你们 的身子 是 基督 的肢体吗?我可以 将 基督 的肢体 作为 娼妓 的肢体吗?断乎不 可! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, '岂 不 知 与娼妓 联合的,便是 与她成为一 体吗?因为 主说:「二 人要成 为 一 体。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, '但 与主 联合的,便是 与主成为一 灵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, '你们要逃避 淫行。人 所 犯的,无论 什么罪,都在 身子 以外,惟 有行 淫的,是得罪 自己 的身子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, '岂 不 知 你们 的身子 就是 圣灵的殿吗?这 圣 灵 是 从 神而来,住在你们 里头的;并且 你们不 是 自己的人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, '因为 你们是重价 买 来的。所以,要在 你们 的身子 上荣耀 神。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, ' 论到 你们信上所 提的事,我说男 不 近 女 倒好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, '但 要免淫乱的事,男子 当各有 自己 的妻子;女子 也当 各有 自己 的丈夫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, '丈夫 当用合宜之分 待 妻子; 妻子 待丈夫 也 要如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, '妻子 没 有权柄 主张自己 的身子,乃 在丈夫; 丈夫 也 没 有权柄 主张自己 的身子,乃 在妻子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, '夫妻不 可彼此 亏负,除非 两相 情愿 ,暂 时分房,为 要 专心祷告方可; 以后仍 要同 房,免得 撒但 趁著 你们 情不自禁,引诱 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, ' 我说 这话,原是 准你们的,不 是 命你们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, ' 我愿 意 众 人 像 我 一样;只是 各 人 领受 神 的 恩赐,一个是 这样, 一个是那样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, ' 我对著没有嫁娶 的和 寡妇 说,若 他们 常 像 我 就好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, ' 倘若 自己禁止 不住,就可以嫁娶。 与其欲火攻心,倒不如 嫁娶 为 妙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, '至于  那已经嫁娶的,我吩咐他们;其实不 是我吩咐,乃 是主吩咐说:妻子 不 可离开  丈夫, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, ' 若 是离开 了,不可再嫁,或 是仍同丈夫 和好。丈夫 也 不 可离弃 妻子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, ' 我 对其余 馀的人说(不 是主 说):倘若 某 弟兄 有 不信 的妻子,妻子 也 情愿  和 他 同住,他就不 要离弃 妻子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, ' 妻子 有 不信 的丈夫,丈夫 也 情愿  和她 同 住,她就不 要离弃 丈夫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, '因为 不信 的丈夫 就因著 妻子 成了圣洁,并且 不信 的妻子 就因著丈夫(原文是弟兄)成了圣洁。不然,你们 的儿女 就 不洁净,但 如今 他们 是圣洁的了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, ' 倘若 那不信 的人要离去,就由他离去吧!无论是弟兄, 是姊妹,遇著 这样 的事都不 必拘束。 神 召 我们 原是 要 我们和睦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, ' 你这作妻子的,怎么 知道 不能 救 你的丈夫呢? 你这作丈夫的,怎么 知道 不能 救 你的妻子呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, '只要 照 主 所分 给各人的,和 神 所 召 各人 的而行。 我吩咐 各 教会 都是这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, '有人 已受割礼 蒙召呢,就不 要废割礼;有人 未受割礼 蒙召呢,就不 要受割礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, '受割礼 算 不得什么,不受割礼 也 算 不得什么,只 要守 神 的诫命就是了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, '各人 蒙召 的时候 是什么身分,仍要 守住 这 身分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, '你是作奴隶 蒙召的吗? 不 要因此忧虑; 若 能 以 自由,就求 自由更好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, '因为 作奴仆蒙召 于  主 的,就是 主 所释放的人; 作自由之人 蒙召的,就是 基督 的奴仆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, '你们是重价 买 来的,不 要作 人 的奴仆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, '弟兄们,你们各人 蒙召 的时候是什么身分,仍要在 神 面前守住 这身分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, ' 论到 童身的人,我没 有 主 的命令,但 我既蒙 主 怜恤 能作 忠心的人,就 把自己的意见 告诉你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, '因 现今 的艰难, 据我看来, 人 不如 守 素安常才好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, '你有妻子 缠著呢,就不 要求 脱离;你没有妻子 缠著呢,就不 要求 妻子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, ' 你若 娶妻,并不 是犯罪; 处女 若 出嫁,也不 是犯罪。然而 这 等人肉身 必受 苦难, 我 却愿 意你们 免这苦难。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, ' 弟兄们,我对你们说:时候 减少了。从此以后,那 有 妻子的,要 像 没 有妻子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, ' 哀哭的,要像 不 哀哭; 快乐的,要像 不 快乐; 置买 的,要像 无 有所得; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, ' 用 世物的,要像 不 用世物,因为 这 世界 的样子 将要过去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, ' 我愿  你们 无所挂虑。没有娶妻的,是为主 的事 挂虑,想怎样 叫主 喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, ' 娶了妻的,是为 世 上的事挂虑,想怎样 叫妻子 喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, ' 妇人 和 处女 也有 分别。没有出嫁的,是为主 的事 挂虑, 要 身体、 灵魂 都 圣洁; 已经出嫁的,是为世 上的事 挂虑,想怎样 叫丈夫 喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, ' 我说 这 话是为 你们 的 益处,不 是要牢 笼 你们,乃 是要叫你们行合宜 的事, 得以殷勤服事 主,没有分心的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, ' 若 有人 以为 自己待 他 的女儿 不合宜, 女儿也过了 年岁,事 又 当 行,他就可随 意 办理,不 算有罪,叫二人成亲就是了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, '倘若 人 心 里 坚定,没 有 不得已的事,并且 由得 自己 作主, 心 里 又 决定了 留下 女儿不出嫁,如此行 也好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, ' 这样看来,叫 自己的 女儿 出嫁 是好, 不 叫 她出嫁 更是好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, ' 丈夫 活著 的时候,妻子 是被约束的; 丈夫 若 死了,妻子就可以 自由,随意 再嫁,只 是要嫁这在主 里面 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, '然而 按 我 的意见,若 常 守节 更有 福气。 我也 想 自己是被 神 的灵感动了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, ' 论到 祭偶像之物,我们晓得 我们都 有 知识。但知识 是叫人自高自大,惟 有爱心 能造就人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, '若 有人 以为 自己知道 什么,按 他所当 知道的,他仍 是不知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, ' 若 有人 爱 神,这人乃是 神 所 知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, ' 论到 吃祭偶像 之物,我们知道 偶像 在 世 上算不得什么,也知道 神只 有一位,再没有别的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, ' 虽 有 称为 神的,或 在 天,或 在 地,就如 那 许多的 神, 许多 的主; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, '然而 我们 只有一位 神,就是父─万物 都本于  他;我们 也 归于  他─并 有一位 主,就是耶稣 基督─万物 都是藉 借著 他有的;我们 也 是藉 借著 他有的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, '但 人 不 都有这等知识。 有人 到 如今 因拜惯了 偶像,就以为 所吃的 是祭偶像之物。 他们 的良心 既然 软弱,也就污秽了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, ' 其实食物 不 能叫 神 看中我们,因为我们 不 吃 也无 损, 吃 也无 益。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, '只是 你们要谨慎,恐怕 你们 这 自由 竟 成了 那软弱 人的绊脚石。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, ' 若 有人 见 你 这有 知识的,在偶像的庙 里 坐席,这人 的良心 若是 软弱,岂不 放胆 去 吃 那祭偶像之物吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, '因此,基督 为 他 死 的那软弱 弟兄,也就因 你 的知识 沉沦了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, ' 你们这样 得罪 弟兄们, 伤了 他们 软弱 的良心,就是得罪 基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, '所以,食物 若 叫我 弟兄 跌倒,我就永远不 吃 肉,免得 叫我 弟兄 跌倒了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, '我不 是 自由的吗?我不 是 使徒吗?我不 是见过 我们的 主 耶稣吗?你们 不 是 我 在主 里面 所做之工吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, '假若 在 别人,我不 是使徒, 在你们,我总 是使徒,因为 你们 在主 里 正是 我 作使徒 的印证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, '我对那盘问 我 的人就是 这样 分诉: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, '难道我们没 有 权柄 靠福音吃 喝吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, '难道我们没 有 权柄 娶信主的姊妹 为妻,带著一同往来,仿佛 其余 馀 的使徒 和 主 的弟兄 并 矶法一样吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, '独 有我 与 巴拿巴 没 有 权柄 不 做工 吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, '有谁 当兵 自 备粮饷呢?有谁 栽 葡萄园 不 吃 园里的果子呢? 有谁 牧养 牛羊 不 吃 牛羊 的奶呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, '我说 这话,岂是照 人的意见; 律法 不 也 是这样 说吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, '就如 摩西 的律法 记著说:「牛 在场上踹谷的时候,不 可笼住牠的嘴。」难道 神 所挂念 的是牛吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, ' 不全 是为 我们 说的吗?分明 是为 我们 说的。因为 耕种 的当 存著 指望 去耕种; 打场 的也当 存得粮 的指望去打场。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, '我们 若 把属灵的种子 撒 在你们中间,就是 从你们 收割 奉养肉身之物,这还算大事吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, '若 别人 在你们 身上有 这权柄,何况 我们呢?然而,我们没 有用 过这 权柄,倒 凡事 忍受,免 得 基督 的福音 被阻隔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, '你们岂不 知 为圣事 劳碌 的就吃 殿中的物吗?伺候 祭坛 的就分领 坛上的物吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, '主 也 是这样 命定,叫传 福音 的靠著 福音 养生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, '但 这权柄 我 全没 有用过。我写 这话,并 非 要 你们这样 待 我,因为 我 宁可 死 也 不叫人 使我 所夸 的落了空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, ' 我 传福音 原没 有 可夸的,因为 我是不得已的。 若 不 传福音,我 便有 祸了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, ' 我若 甘心 做 这事,就有 赏赐;若 不甘心,责任 却 已经托 讬付我了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, '既是这样,我的 赏赐 是 什么呢?就是 我传 福音 的时候叫 人不花钱得福音, 免得 用尽 我 传福音 的权柄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, '我虽 是 自由的,无人辖管;然而我 甘心作了众人 的仆人,为 要多 得人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, ' 向犹太人,我就作 犹太人,为 要得 犹太人;向律法 以下的人, 我虽不 在 律法 以下,还是作 律法 以下的人,为 要得 律法 以下的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, '向没有律法的人,我就作 没有律法的人,为 要得 没有律法的人;其实我在 神面前,不 是 没有律法;在基督面前,正 在律法之下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, '向软弱的人,我就作 软弱的人,为 要得 软弱的人。向什么样的人,我就作 什么样的人。 无论如何,总要救 些人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, ' 凡我所 行的,都是为福音 的缘故,为 要与人 同 得这福音的好处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, '岂不 知 在 场 上赛跑 的都 跑,但 得 奖赏 的只有一人?你们也当 这样跑,好叫 你们得著奖赏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, ' 凡 较力争胜的,诸事 都有节制,他们 不过 是 要 得 能坏 的冠冕;我们 却 是要得不能坏的冠冕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, '所以, 我 奔跑 不 像 无定向的; 我斗拳 不 像 打 空气的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, ' 我是攻克 己 身, 叫身服我, 恐怕 我传福音 给别人,自己 反被 弃绝了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, ' 弟兄们,我不 愿 意 你们 不晓得, 我们的 祖宗 从前都 在 云 下, 都 从 海 中经过, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, ' 都 在云 里、 海 里 受洗 归了 摩西; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, '并且 都 吃了 一样的 灵 食, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, '也 都 喝了 一样的 灵 水。所 喝 的,是出于 随著 他们的灵 磐石;那 磐石 就是 基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, ' 但他们 中间 多半是 神 不 喜欢的人,所以 在 旷野 倒毙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, ' 这些事 都是 我们的 鉴戒,叫 我们 不 要 贪恋恶 事,像 他们那样 贪恋的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, '也不 要拜 偶像,像 他们 有人拜的。如 经上所记:「百姓 坐下 吃 喝, 起来 玩耍。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, '我们也不 要行奸淫,像 他们 有人 行的, 一 天 就倒毙 了二万三千人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, '也不 要试探主(有古卷:基督),像 他们 有人 试探的, 就被 蛇 所灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, '你们也不 要发怨言,像 他们 有发怨言 的,就 被 灭命的 所灭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, ' 他们 遭遇 这些事 都要作为鉴戒,并且 写在经上,正是 警戒 我们 这末 世 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, '所以,自己以为 站得稳的,须要谨慎,免得 跌倒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, '你们 所 遇见的试探,无非 是人 所能受的。 神 是 信实的, 必不 叫 你们 受试探 过于  所能 受的; 在 受试探的时候,总 要给你们开  一条出路,叫你们能 忍受得住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, ' 我 所亲爱的弟兄啊,你们要逃避 拜偶像的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, '我好像 对明白人 说的,你们 要审察 我的 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, '我们所 祝福 的 杯,岂不 是 同领 基督 的血吗?我们所 擘开  的饼,岂不 是 同领 基督 的身体吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, '我们虽 多,仍是 一 个饼,一 个身体,因为 我们都 是分受 这一 个饼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, '你们看 属 肉体 的以色列人,那吃 祭物 的岂不 是 在祭坛 上有分吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, ' 我是怎么 说呢? 岂是 说祭偶像 之物算得什么呢?或 说 偶像 算 得什么呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, '我乃 是说,外邦人所献的 祭 是祭 鬼, 不是祭 神。 我不 愿 意 你们 与鬼 相交。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, '你们不 能 喝 主 的杯 又 喝鬼 的杯,不 能 吃 主 的筵席 又 吃鬼 的筵席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, ' 我们可惹 主的愤恨吗?我们比 他 还有 能力吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, '凡事 都可行,但 不 都 有益处。凡事 都可行,但 不 都 造就人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, '无论何人,不要求 自己的益处,乃 要求别人的益处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, '凡 市 上 所卖的,你们只管吃,不 要为良心 的缘故 问什么话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, '因为 地 和 其中 所充满 的都属乎主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, '倘 有一个 不 信的人请 你们赴席, 你们若愿 意 去,凡 摆在你们 面前的,只管吃,不 要为良心 的缘故 问什么话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, ' 若 有人 对你们 说:「这 是 献过祭的物」,就 要为那告诉你们的人,并为 良心 的缘故 不 吃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, '我说 的良心 不 是你的, 乃 是他的。 我 这自由 为什么 被 别人 的良心 论断呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, '我 若 谢恩 而吃,为什么 因 我 谢恩 的物 被人毁谤呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, '所以,你们或 吃 或 喝, 无论做 什么,都要 为 荣耀 神 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, '不拘 是犹太人,是 希腊人,是 神 的教会,你们都不要使 他跌倒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, '就好像 我 凡事都叫众 人 喜欢,不 求 自己 的益处,只 求众人 的益处,叫 他们得救。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, '你们该 效法 我,像 我 效法基督一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, ' 我称赞 你们,因 你们凡事 记念 我,又 坚守 我所 传给 你们 的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, ' 我愿 意 你们 知道, 基督 是 各 人 的头; 男人 是女人 的头; 神 是基督 的头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, '凡 男人 祷告 或 是讲道(或译:说预言;下同),若蒙著 头,就羞辱 自己 的头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, ' 凡 女人 祷告 或是 讲道,若不蒙著 头,就羞辱 自己 的头,因为 这 就 如同 剃了 头发一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, ' 女人 若 不 蒙著头,就 该剪了头发; 女人 若 以剪发、 剃发 为羞愧,就该蒙著头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, ' 男人 本 不 该 蒙著 头,因为他是 神 的形像 和 荣耀;但 女人 是 男人 的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, '起初,男人 不 是 由 女人而出,女人 乃 是由 男人而出; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, '并且 男人 不 是为 女人 造的,女人 乃 是为 男人造的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, '因 此,女人 为 天使的缘故,应当 在 头 上有 服权柄的记号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, '然而 照 主的安排,女 也不 是无 男,男 也不 是无 女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, '因为 女人 原 是由 男人而出,男人 也 是 由 女人而出;但 万有 都是出乎 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, '你们 自己 审察,女人 祷告 神,不蒙著 头是 合宜的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, '你们的本 性 不也 指示 你们, 男人 若 有长头发,便是 他 的羞辱吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, '但 女人 有长头发,乃是 她 的荣耀,因为 这头发 是给 她 作 盖头的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, ' 若 有人 想 要 辩驳,我们 却没 有 这样 的规矩, 神 的众教会 也是没有的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, '我现 今 吩咐你们的话,不 是称赞你们;因为 你们聚会 不 是 受益,乃 是 招损。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, '第 一,我听说,你们 聚 会 的时候 彼此 分门别类,我也 稍微地 信 这话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, ' 在你们 中间 不免 有 分门结党的事,好叫 那些有经验 的人显明 出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, '你们 聚会的时候,算 不 得吃 主 的晚餐; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, '因为 吃 的时候,各人 先吃 自己 的饭,甚至 这个 饥饿, 那个 酒醉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, '你们 要吃 喝,难道没 有家 吗?还是 藐视 神 的教会, 叫那没 有 的羞愧呢?我向你们 可怎么 说呢?可因 此 称赞 你们吗?我不 称赞! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, ' 我 当日传给 你们的, 原是 从 主 领受的,就是 主 耶稣 被卖 的那 一夜,拿起 饼来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, ' 祝谢了,就擘开 , 说:「这 是 我 的身体,为你们舍(有古卷:擘开 )的,你们 应当如此 行,为 的是 记念 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, '饭 后,也 照样 拿起杯来,说:「这 杯 是 用 我 的血 所立的新 约,你们每逢 喝的时候,要如此 行,为 的是记念 我。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, ' 你们每逢 吃 这 饼, 喝 这杯,是表明 主的 死,直等到 他 来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, '所以,无论何人,不按理 吃 主的饼, 喝 主 的杯,就是干 犯 主的身、 主 的血了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, ' 人 应当自己 省察, 然后 吃 这饼、 喝 这杯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, '因为 人吃 喝,若不 分辨 是主的身体,就是吃 喝 自己 的罪了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, '因 此,在你们 中间 有好些 软弱 的与 患病的,死(原文是睡)的也不少。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, ' 我们若 是先分辨 自己,就不 至于  受审。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, ' 我们受审的时候,乃是被 主 惩治,免得 我们和 世 人一同定罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, '所以 我 弟兄们,你们聚会 吃的时候,要彼此 等待。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, '若有人 饥饿,可以在家 里 先吃,免得 你们聚会,自己取 罪。 其余 馀的事,我来 的时候 再安排。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, ' 弟兄们,论到 属灵的恩赐,我不 愿 意 你们 不明白。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, ' 你们作 外邦人 的时候,随 事 被牵引,受迷惑,去 服事那哑巴 偶像,这是你们知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, '所以 我告诉你们,被 神 的灵 感动的, 没有 说「耶稣 是可咒诅」的;若 不是 被 圣 灵感动的,也 没有 能 说「耶稣 是主」的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, ' 恩赐 原有 分别,圣灵 却 是一位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, '职事 也 有 分别,主 却 是一位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, '功用 也 有 分别, 神 却 是一位, 在众人 里面 运行 一切的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, ' 圣灵 显 在 各人身上,是叫 人得益处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, ' 这人 蒙 圣灵 赐 他智慧 的言语, 那 人也蒙 这位 圣灵 赐他知识 的言语, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, '又有一人 蒙 这位 圣灵 赐他信心,还 有一人 蒙 这位 圣灵 赐他医病 的恩赐, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, '又 叫一人 能行 异能,又 叫一人 能作先知,又 叫一人 能辨别 诸灵,又叫一人 能说 方言,又 叫一人 能翻 方言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, ' 这 一切 都是这 位 圣灵 所运行、 随 己 意 分给 各人的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, '就 如 身子 是 一个,却 有 许多 肢体;而且 肢体 虽 多,仍是 一个 身子;基督 也 是这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, ' 我们 不拘 是犹太人,是 希腊人,是 为奴的,是 自主的, 都 从 一位 圣灵 受洗, 成了 一个 身体,饮 于 一位 圣灵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, ' 身子 原 不 是 一个 肢体,乃 是许多肢体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, '设若 脚 说:「我不 是 手,所以 不 属 乎 身子,」它不 能因 此 就不 属 乎 身子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, '设若 耳 说:「我不 是 眼,所以 不 属 乎 身子,」它 不 能因 此 就不 属 乎 身子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, '若 全 身 是眼,从哪里 听声呢?若 全 身是耳,从哪里 闻味呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, '但 如今, 神 随 自己的意思 把肢体 俱 各 安排 在身 上了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, ' 若 都 是 一个 肢体,身子 在哪里呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, '但 如今 肢体 是多的,身子 却 是一个。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, ' 眼 不 能 对手 说:「我用不 著 你。」头 也 不 能对脚说:「我用不 著 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, '不但如此,身 上肢体 人以 为 软弱的,更 是 不可少的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, ' 身 上肢体,我们看 为 不体面的,越发 给它 加上 体面; 不俊美的,越发 得著 俊美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, ' 我们 俊美的肢体,自然用不 著装饰;但 神 配搭 这身子,把加倍 的体面 给 那有缺欠的肢体, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, '免 得 身 上 分门别类,总 要肢体 彼 此 相顾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, ' 若 一个 肢体 受苦,所有 的肢体 就一同受苦;若 一个 肢体 得荣耀,所有 的肢体 就一同快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, '你们 就 是 基督 的身子,并且 各自 作肢体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, ' 神 在 教会 所设立的:第一 是使徒,第二 是先知,第三 是教师,其次 是行异能的,再次 是得恩赐 医病的,帮助人的,治理事的,说 方言的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, '岂 都 是使徒吗?岂 都 是先知吗?岂 都 是教师吗?岂 都 是行异能的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, '岂 都 是得 恩赐 医病的吗?岂 都 是说 方言的吗?岂 都 是翻方言的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, '你们要 切切地求 那更大 的恩赐。 我现今把最 妙 的道 指示 你们。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, '我若 能说 万人的 方言,并 天使的话语,却 没 有 爱,我就成了 鸣的 锣, 响的 钹一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, ' 我若 有 先知讲道之能,也 明白 各样 的奥秘, 各样 的知识, 而且 有 全备 的信,叫 我能够移 山,却 没 有 爱,我就算 不得什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, '我若 将所有 的 赒济穷人,又 舍 己 身 叫 人焚烧,却 没 有 爱,仍然与我无 益。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, '爱 是恒久忍耐,又有恩慈;爱 是不 嫉妒;爱 是不 自夸,不 张狂, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, '不 做害羞的事,不 求 自己的益处,不 轻易发怒,不 计算 人的恶, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, '不 喜欢 不义,只 喜欢 真理; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, '凡事 包容,凡事 相信,凡事 盼望,凡事 忍耐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, '爱 是永不 止息。先知 讲道之能终必 归于 无有;说方言 之能终必 停止;知识 也终必 归于 无有。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, '我们现在 所知道 的有限,先知所讲的 也 有限, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, ' 等 那完全的 来到,这有限的必归于  无有了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, '我作 孩子 的时候,话语 像 孩子,心思 像 孩子,意念 像 孩子,既 成了 人,就把孩子的事 丢弃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, ' 我们如今 仿佛对著 镜子 观看,模糊不清(原文是如同猜谜),到那时 就 要面 对 面了。我如今 所知道 的有限,到那时 就 全知道, 如同 主知道我一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, ' 如今 常存 的有信,有望,有爱 这 三样, 其中 最大 的是爱。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, '你们要追求 爱,也 要切慕 属灵的恩赐, 其中更 要羡慕的,是作先知讲道(原文作:是说预言;下同)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, ' 那说 方言的,原不 是对人 说,乃是对 神说,因为 没有人 听出来。然而,他在心灵 里却是讲说 各样的奥秘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, '但 作先知讲道的,是对人 说,要造就、 安慰、 劝勉人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, '说 方言的,是造就 自己; 作先知讲道的,乃是造就 教会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, ' 我愿 意 你们 都 说 方言,更 愿 意 你们作先知讲道;因为 说 方言的,若 不 翻 出来,使 教会 被 造就,那作先知讲道的,就比 他强了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, ' 弟兄们, 我到 你们 那里去,若 只说 方言,不用 启示,或 知识,或 预言,或 教训,给你们 讲解,我与你们 有什么 益处呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, '就是 那有 声 无气的物, 或 箫,或 琴,若 发出来的声音 没有 分别,怎能 知道 所吹 所弹的是什么呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, ' 若 吹 无定 的号 声,谁 能预备 打仗呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, '你们 也 是如此。 舌头 若 不 说 容易明白 的话,怎能 知道 所说的 是什么呢?这就是 向 空 说话了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, ' 世 上 的声音,或者 甚多,却 没有一样 是 无意思的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, ' 我若 不 明白 那声音 的意思,这说话 的人必 以 我 为化外之人,我也 以他 为化外之人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, '你们 也 是如此,既是 切慕 属灵的恩赐,就 当求 多得 造就 教会的恩赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, '所以 那说 方言的,就当求 著 能翻出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, ' 我若 用方言 祷告,是我 的灵 祷告,但 我 的悟性 没有 果效。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, '这却 怎么样呢?我要用灵 祷告, 也 要用悟性 祷告;我要用灵 歌唱, 也 要用悟性 歌唱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, '不然,你用 灵 祝谢,那在座 不通方言的人,既然 不 明白 你 的话,怎能 在 你 感谢 的时候 说「阿们」呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, ' 你 感谢 的固然 是好, 无奈不 能造就 别人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, '我感谢 神,我说 方言 比 你们 众人还多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, '但 在教会 中, 宁可 用 悟性 说 五 句 教导 人的话,强如 说万 句 方言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, '弟兄们,在心志 上不 要作 小孩子。然而,在恶事 上要作婴孩, 在心志 上总要作 大人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, '律法 上 记著:主 说:我要用 外邦人的舌头 和 外邦人 的嘴唇 向这 百姓 说话;虽然 如此,他们还 是不 听从 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, '这样看来,说方言 不 是 为 信 的人作证据,乃 是为不信的人; 作先知讲道 不 是为不信的人作证据,乃 是为信的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, '所以,全 教会 聚 在 一处的时候,若 都 说 方言, 偶然有不通方言的, 或是 不信 的人进来,岂 不 说 你们癫狂了吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, ' 若 都 作先知讲道, 偶然有不信的,或 是不通方言 的人 进来,就被 众 人劝醒,被 众 人审明, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, '他 心 里的隐情 显 露出来, 就 必将脸 伏 地,敬拜 神,说:「 神 真 是 在 你们 中间了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, '弟兄们,这 却怎么样呢?你们聚会的 时候,各人 或有 诗歌,或有 教训,或有 启示,或有 方言,或有 翻出来的话,凡事 都当 造就人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, '若 有 说 方言的,只好 两个人, 至多 三个人,且 要轮 流著说,也 要一 个人翻出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, ' 若 没 有 人翻,就当在会 中 闭口,只 对自己 和 神 说就是了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, ' 至于 作先知 讲道的,只好两 个人或 是三个人, 其余 馀 的就当慎思明辨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, '若 旁边坐著 的得了启示,那先 说话的就当闭口不言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, '因为 你们都 可以 一个一个地 作先知讲道,叫 众 人学道理, 叫众 人得劝勉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, ' 先知的 灵 原是顺服 先知的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, '因为 神 不 是 叫人混乱,乃 是叫人安静。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, '妇女 在会 中 要闭口不言,像 在 圣徒 的众 教会一样,因为 不 准 她们 说话。她们总 要顺服, 正如 律法 所说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, ' 她们若 要 学 什么,可以在家 里 问 自己 的丈夫,因为 妇女 在会 中 说话 原是 可耻的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, '神 的道理 岂是从 你们 出来 吗? 岂是单 临到 你们吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, '若 有人 以为 自己是 先知,或 是属灵的,就该知道,我所 写 给你们 的 是 主 的命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, ' 若 有 不知道的,就由他不知道吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, '所以 我 弟兄们,你们要切慕 作先知讲道,也 不 要禁止 说 方言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, ' 凡事 都要规规矩矩地 按著 次序 行。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, ' 弟兄们,我如今把先前所 传给 你们 的福音 告诉 你们知道;这福音 你们也 领受了,又 靠著 站立得住, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, '并且你们 若 不是 徒然 相信, 能以持守 我所 传给 你们 的,就 必因 这福音 得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, ' 我当日所 领受 又 传给 你们的:第 一,就是 基督 照 圣经所说,为 我们 的罪 死了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, '而且 埋葬了;又 照 圣经所说,第三 天 复活了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, '并且 显给矶法 看,然后 显给十二使徒看; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, '后来 一时 显给五百 多 弟兄 看,其中 一大半 到 如今 还在,却 也有 已经睡了的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, '以后 显给雅各 看,再 显给众 使徒看, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, ' 末了 也 显给我看;我如同 未到产期而生的人一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, ' 我 原是 使徒 中最小的, 不 配 称 为 使徒,因为 我从前逼迫 神 的教会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, '然而,我今日成了 何等人,是蒙 神 的恩 才成的,并且 他 所赐 我 的恩 不 是 徒然的。 我比众 使徒 格外 劳苦; 这原不 是我,乃是 神 的恩 与我 同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, ' 不拘 是我,是 众使徒,我们如此 传,你们也 如此 信了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, ' 既 传 基督 是 从 死 里复活了,怎么 在你们 中间 有人 说 没 有 死人 复活的事呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, ' 若 没 有 死人 复活的事,基督 也就没 有复活了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, ' 若 基督 没 有复活, 我们 所传 的便是枉然, 你们 所信 的也 是枉然; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, ' 并且 明显我们是为 神 妄作见证的,因 我们见证 神 是 叫基督 复活了。若 死人 真 不 复活, 神也就没 有叫基督 复活了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, '因为 死人 若 不 复活,基督 也就没 有复活了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, ' 基督 若 没 有复活,你们 的信 便是徒然,你们 仍 在 罪 里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, ' 就是在基督 里 睡了 的人也 灭亡了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, '我们若 靠 基督 只 在 今 生 有指望,就算 比众 人 更可怜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, '但 基督 已经 从 死 里复活,成为睡了 之人初熟的果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, ' 死 既 是因 一人而来,死人 复活 也 是因 一人而来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, ' 在亚当 里 众 人都死了;照样,在基督 里 众人 也 都要 复活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, '但 各人 是按著 自己 的次序复活:初熟的果子 是基督;以后,在 他 来的时候,是 那些属基督的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, '再后,末期 到了,那时 基督既将一切 执政的、 掌权的、 有能的 都毁灭了,就把国 交与 父 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, '因为 基督 必 要作王,等 神 把一切 仇敌 都放在 他 的脚 下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, '尽 侭末了 所毁灭 的仇敌 就是死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, '因为经上说:「 神叫万物 都服 在他 的脚 下。」 既 说 万物 都服了他,明显 那 叫万物 服 他的,不在其内了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, ' 万物 既服了 他,那时 子 也 要自己 服 那叫万物 服 他的,叫 神 在 万物之上,为 万物之主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, '不然,那些为 死人 受洗的,将来 怎样呢?若 死人 总 不 复活,因何 为 他们 受洗呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, '我们 又 因何 时刻 冒险呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, '弟兄们,我在 我 主 基督 耶稣 里,指著 你们 所夸的口极力地说,我是天天 冒死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, '我若 当日像 寻常人,在 以弗所 同野兽战 斗,那于 我 有什么 益处呢?若 死人 不 复活,我们就吃吃 喝喝吧!因为 明天 要死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, '你们不 要自欺;滥 交 是败坏 善 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, '你们要醒悟 为善, 不 要犯罪,因为 有人 不认识 神。我说 这话是要叫 你们 羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, '或 有人 问:「死人 怎样 复活, 带著什么 身体 来呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, '无知的人哪,你 所种的,若 不 死 就不能 生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, '并且 你所 种 的不 是 那将来的形体,不过 是子 粒,即如 麦子,或 是别 样的谷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, '但 神 随 自己的意思 给 他 一个形体,并 叫各 等子粒 各有自己 的形体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, '凡 肉体 各有不 同: 人 是一样,兽 又 是一样,鸟 又 是一样,鱼 又 是一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, ' 有天 上的形体,也 有地 上的形体;但 天 上形体的荣光 是一样,地 上形体的荣光又 是一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, '日 有日的 荣光, 月 有月的 荣光, 星 有星的 荣光; 这星 和那星 的 荣光 也有分别。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, '死人 复活 也 是这样:所种 的是 必朽坏的,复活 的是 不朽坏的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, '所种 的是 羞辱的,复活 的是 荣耀的;所种 的是 软弱的,复活 的是 强壮的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, '所种 的是血气 的身体,复活 的是灵性 的身体。若 有 血气 的身体,也 必有 灵性的身体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, '经上也 是这样 记著说:「首先 的人 亚当 成了 有灵(灵:或译血气)的活人」;末后 的亚当 成了 叫人活 的灵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, '但 属灵的 不 在先, 属血气的在先,以后 才有属灵的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, '头 一个人 是出于  地,乃属土;第二 个人 是出于  天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, '那 属土的怎样,凡属土 的也 就怎样; 属天的怎样, 凡属天 的也 就怎样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, ' 我们既 有 属土 的形状,将来也 必有 属天 的形状。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, ' 弟兄们,我告诉 你们说, 血 肉 之体不能 承受 神 的国,必朽坏 的不 能承受 不朽坏的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, ' 我如今把一件奥秘的事 告诉 你们:我们不 是都 要睡觉,乃 是都 要改变, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, '就在 一霎时,眨 眼 之间, 号筒 末次吹响的时候。因 号筒要响, 死人 要复活 成为不朽坏的, 我们 也要改变。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, ' 这 必朽坏 的总要变成(变成:原文是穿;下同)不朽坏的, 这 必死 的总要变成 不死的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, ' 这 必朽坏 的既变成 不朽坏的, 这 必死 的既变成 不死的,那时 经上所记「死 被 得胜 吞灭」的话 就应验了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, '死啊!你 得胜 的权势在哪里?死啊!你 的毒钩 在哪里? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, ' 死 的毒钩 就是罪, 罪 的权势 就是律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, ' 感谢 神, 使 我们 藉 借著 我们 的主 耶稣 基督 得胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, '所以,我 亲爱 的弟兄们,你们务要 坚固,不可摇动,常常 竭力 多做主 工;因为知道, 你们 的劳苦 在主 里面 不 是 徒然的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, ' 论到 为 圣徒 捐钱,我从前怎样 吩咐 加拉太 的众教会,你们 也当 怎样 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, '每逢 七日 的第一日,各 人 要 照 自己 的进项 抽出来 留著, 免得 我来 的时候 现凑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, '及 至 我来到了, 你们 写信 举荐 谁,我就打发 他们,把你们的 捐资 送 到 耶路撒冷去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, ' 若 我也 该去,他们可以和我 同 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, '我要从 马其顿 经过;既 经过了,就 要到 你们 那里去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, ' 或者 和你们 同 住几时,或者 也 过冬。无论我 往哪里 去,你们 就 可以给我 送行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, ' 我如今 不 愿 意 路 过 见 你们;主 若 许我, 我就指望 和你们 同 住 几时。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, '但 我要仍旧住 在 以弗所,直等到 五旬节; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, '因为 有宽大 又 有功效 的门 为我 开 了,并且 反对的人 也多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, ' 若是 提摩太 来到,你们要留心,叫 他在 你们 那里无所惧怕;因为 他劳力做 主 的工,像 我一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, '所以,无论 谁 都不可藐视 他,只要 送 他 平安前行,叫 他到 我 这里来,因 我指望 他 和 弟兄们同来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, ' 至于  兄弟 亚波罗,我再三 地劝 他 同 弟兄们 到 你们 那里去;但 这 时他 决 不 愿 意 去, 几时 有了机会 他必去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, '你们务要警醒,在 真道 上站立得稳,要作大丈夫,要刚强。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, '凡你们 所做的 都要凭 爱心 而做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, ' 弟兄们,你们晓得 司提法那 一家, 是 亚该亚 初结的果子,并且 他们 专以 服事 圣徒 为念。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, ' 我劝你们 顺服 这样的人,并 一切 同工 同劳的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, ' 司提法那 和 福徒拿都,并 亚该古 到这里来,我很喜欢;因为 你们 待我有不及之处,他们 补上了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, '他们叫 我 和 你们 心 里都快活。这样的人,你们务要 敬重。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, '亚细亚 的众教会 问你们 安。亚居拉 和 百基拉 并 在 他们 家 里的 教会,因主 多多地 问你们 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, '众 弟兄 都问你们 安。你们要亲嘴 问安,彼此 务要 圣洁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, '我─保罗 亲 笔 问安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, '若 有人 不 爱 主,这人可 诅可咒。主必要来! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, '愿 主 耶稣 基督的恩 常与 你们众人同在! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, '我 在 基督 耶稣 里的爱 与 你们 众人同在。阿们!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, '奉 神 旨意 作基督 耶稣 使徒 的保罗 和 兄弟 提摩太,写信给 在 哥林多 神 的教会,并 亚该亚 遍处 的众 圣徒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, '愿 恩惠、 平安 从 神 我们的 父 和 主 耶稣 基督 归与你们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, '愿 颂赞 归与我们的 主 耶稣 基督 的父 神,就是 发慈悲 的父, 赐各样 安慰的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, '我们 在 一切 患难中,他 就安慰 我们,叫 我们 能 用 神 所赐的 安慰 去安慰 那遭 各样 患难的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, ' 我们 既 多受 基督 的苦楚, 就 靠 基督 多得 安慰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, ' 我们受患难 呢,是为 叫你们 得安慰, 得拯救;我们得安慰 呢,也是为 叫你们 得安慰;这 安慰能叫 你们忍受 我们 所受的 那样 苦楚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, ' 我们 为 你们 所存的盼望 是确定的,因为知道 你们既 是 同 受苦楚,也 必同 得安慰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, ' 弟兄们,我们不 要 你们 不晓得,我们 从前在 亚细亚 遭遇 苦难, 被压 太 重,力 不能胜,甚至 连 活命 的指望都绝了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, ' 自己 心里 也断定 是必死的,叫 我们不 靠 自己,只 靠 叫死人 复活的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, '他 曾救 我们 脱离 那极大的 死亡, 现在仍要救我们,并且我们指望 他 将来还要 救我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, '你们 以祈祷 帮助 我们,好叫 许多人 为 我们 谢恩,就是 为 我们 因 许多 人 所得的恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, ' 我们 所夸的 是 自己的 良心, 见证 我们凭著 神 的圣洁 和 诚实; 在世为人不 靠 人的 聪明,乃 靠 神 的恩惠, 向 你们 更是这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, ' 我们现在写 给你们 的话,并不 外乎 你们所念的、 所认识的,我也 盼望 你们到 底 还是要认识; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, '正如 你们已经有 几分 认识 我们, 以我们 夸口,好像 我们 在 我们主 耶稣 的日子 以你们夸口一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, '我既然 这样 深信,就早 有意 到 你们那里去, 叫你们再得 益处; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, '也 要从 你们 那里经过,往 马其顿去,再 从 马其顿 回到 你们那里, 叫 你们 给我送行 往 犹太去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, ' 我有 此意,岂是 反复不定吗? 我所起的意,岂是从 情欲起的,叫 我 忽是 忽非吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, ' 我指著 信实的 神说,我们 向 你们 所传的道,并没 有 是 而又 非的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, '因为 我 和 西拉 并 提摩太,在你们 中间 所传 神 的儿子 耶稣 基督, 总没 有 是 而又 非的, 在 他 只有 一是。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, ' 神 的应许,不论有多少,在 基督 都是是的。所以 藉 借著 他也都是实在(实在:原文是阿们)的,叫 神 因 我们 得荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, ' 那在 基督 里坚固 我们 和 你们,并且 膏 我们的就是 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, '他 又 用印印了 我们,并 赐 圣灵 在 我们 心里作凭据(原文是质)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, ' 我 呼吁 神 给 我的 心 作见证, 我没有 往 哥林多 去 是为要宽容 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, ' 我们并不是 辖管 你们的 信心,乃 是 帮助 你们的 快乐,因为 你们凭信 才站立得住。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, ' 我自己 定了 主意 再 到 你们那里去,必须大家没有 忧愁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, ' 倘若 我 叫你们 忧愁,除了 我 叫 那忧愁的人以外, 谁 能叫我 快乐呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, ' 我曾把这 事写给你们,恐怕 我到的时候,应该 叫 我 快乐 的那些人,反倒叫我 忧愁。我也深信, 你们 众人 都以我的 快乐 为自己的快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, ' 我先前心里 难过 痛苦, 多多地 流泪,写信 给你们,不是 叫 你们忧愁,乃是 叫 你们知道 我 格外地 疼爱 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, ' 若 有 叫人忧愁的,他不 但叫我 忧愁,也是 叫你们 众人 有 几分忧愁。我说几分,恐怕 说得太重。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, '这样的人 受了 众人 的 责罚 也就够了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, ' 倒不如 赦免他, 安慰他,免得 他 忧愁 太过,甚至 沉沦了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, '所以 我劝 你们,要向 他 显出坚定不移 的爱心来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, '为 此 我先前也 写信给你们,要 试验 你们,看你们 凡事 顺从 不顺从。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, ' 你们赦免 谁,我也赦免谁。 我 若 有所 赦免的, 是在 基督 面前 为你们 赦免的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, '免得 撒但 趁著机会胜过我们,因 我们并非 不晓得 他的 诡计。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, ' 我从前为 基督 的福音 到了 特罗亚, 主 也 给我 开  了门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, '那时,因为 没有 遇见 兄弟 提多,我 心里 不 安,便 辞别 那里的人 往 马其顿去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, ' 感谢 神!常 率领我们 在 基督 里夸胜,并 藉 借著 我们 在 各 处 显扬 那因认识 基督 而有的香气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, '因为 我们在 神面前,无论在 得救 的人身上或 灭亡的人身上,都有基督 馨香之气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, '在 这等人,就作了 死 的香气 叫 他死; 在那等人,就作了 活 的香气 叫 他活。 这事 谁 能当得起呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, ' 我们不 像 那许多人,为利混乱 神 的道;乃是 由于  诚实, 由于  神,在 神 面前 凭著 基督 讲道。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, '我们岂是 又 举荐 自己吗? 岂像 别人 用 人的荐 信 给 你们 或 用 你们的荐信给人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, '你们 就是 我们的 荐信,写 在 我们的 心里,被 众 人 所知道 所念诵的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, '你们明显 是 基督 的信,藉 借著 我们 修成的。不是 用墨 写的,乃是 用永生 神 的灵写的;不是 写在 石 版上,乃是 写在 心 版上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, '我们因 基督,所以在 神 面前 才有 这样的 信心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, '并不 是 我们凭 自己 能承担 什么事; 我们 所能承担的,乃是出于  神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, '他 叫我们 能 承当这新 约 的执事,不是 凭著字句,乃是 凭著精意;因为 那字句 是叫人死,精意(或译:圣灵)是叫人活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, ' 那用 字 刻 在石头 上属死 的职事 尚且有 荣光,甚至 以色列 人 因 摩西 面上 的荣光,不 能 定睛看 他的脸;这 荣光原是渐渐退去的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, '何况 那属灵 的职事 岂不 更 有 荣光吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, ' 若是 定罪 的职事 有荣光,那称义 的职事 荣光 就越发 大了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, ' 那从前有荣光的,因 这 极大的 荣光 就算不得 有荣光了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, ' 若 那废掉的 有荣光,这长存的 就更 有荣光了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, '我们既 有 这样的 盼望,就 大胆 讲说, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, ' 不 像 摩西 将 帕子 蒙在 脸上,叫 以色列 人 不能 定睛看 到 那将废者 的结局。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, '但 他们的 心地 刚硬, 直到 今日 诵读 旧 约的时候, 这 帕子 还没有 揭去。 这帕子在 基督 里已经废去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, '然而 直到 今日, 每逢 诵读 摩西书的时候,帕子 还在 他们 心上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, '但 他们的心几时 归 向 主,帕子 就几时除去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, ' 主 就是 那灵; 主 的灵 在哪里,那里就得以自由。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, '我们 众人 既然 敞著 脸 得以看见主 的荣光,好像从镜子里返照,就变成 主的 形状, 荣 上加 荣,如同 从 主的 灵变成的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, '我们既然 蒙怜悯,受了 这 职分,就不 丧胆, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, '乃 将那些暗昧 可耻 的事弃绝了;不 行 诡诈,不 谬讲 神 的道理,只 将真理 表明出来,好在 神 面前 把自己 荐 与 各 人 的良心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, ' 如果 我们的 福音 蒙蔽,就是 蒙蔽 在 灭亡的人身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, ' 此等不信 之人 被这 世界 的神 弄瞎 了心眼,不叫 基督 荣耀 福音 的光 照 著他们。基督 本是 神 的像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, ' 我们原不是 传 自己,乃是 传基督 耶稣 为主,并且 自己 因 耶稣 作你们的 仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, ' 那 吩咐 光 从 黑暗 里照出来的 神, 已经照 在 我们 心里,叫 我们得知 神 荣耀 的光 显在 耶稣 基督 的面上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, ' 我们有 这 宝贝 放在 瓦 器里,要 显明这莫大的 能力 是出于  神, 不是 出于  我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, '我们 四面 受敌,却 不 被困住;心里作难,却 不 至失望; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, '遭逼迫,却 不 被丢弃;打倒了,却 不 至死亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, '身 上 常 带著 耶稣的 死,使 耶稣的 生 也 显明 在我们 身 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, '因为我们 这 活著 的人是常 为 耶稣 被交 于  死地,使 耶稣 的生 在 我们 这必死的 身上 显明出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, '这样看来,死 是在 我们 身上发动,生 却 在 你们身上发动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, '但 我们既有 信心,正如 经上记著说:「我因信,所以 如此说话。」我们 也 信,所以 也 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, '自己知道 那叫 主 耶稣 复活的,也 必叫我们 与 耶稣 一同复活,并且 叫我们与 你们 一同站在他面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, ' 凡事 都是为 你们,好叫 恩惠 因 人多 越发加增,感谢 格外显多,以致 荣耀归与 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, '所以,我们 不 丧胆。外体 虽然 毁坏, 内心 却 一天 新 似 一天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, ' 我们 这 至暂 至轻 的苦楚,要为我们 成就 极 重 无比、永远的 荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, '原来我们 不是 顾念 所见的,乃是 顾念所不 见的;因为 所见的 是暂时的, 所不 见的 是永远的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, ' 我们原知道, 我们 这地上的 帐棚 若 拆毁了,必得 神所造,不是人手所造,在 天上 永存的 房屋。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, ' 我们 在 这 帐棚里叹息,深想得 那 从 天上 来的房屋,好像穿上衣服; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, '倘若 穿上,被遇见 的时候就不至于  赤身了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, ' 我们在 这帐棚里 叹息 劳苦,并非 愿 意 脱下这个,乃是 愿 意穿上那个,好叫 这必死的 被 生命 吞灭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, ' 为 此,培植 我们的就是 神,他 又赐给 我们 圣灵作凭据(原文是质)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, '所以,我们时常 坦然无惧,并且晓得 我们住 在 身内,便与 主 相离。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, '因 我们行事为人 是凭著 信心,不是 凭著 眼见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, '我们坦然无惧, 是更 愿 意 离开  身体 与 主 同住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, '所以,无论 是住在身内, 离开 身外,我们立了志向,要 得 主 的喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, '因为 我们 众人 必要 在基督 台 前 显露出来,叫 各人 按著 本身 所行的,或 善 或 恶 受报。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, '我们既 知道 主 是可畏的,所以劝 人。但我们在 神 面前是显明的, 盼望 在 你们的 良心里 也 是显明的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, '我们不是 向你们 再 举荐 自己,乃是 叫 你们 因 我们 有可夸 之处,好对 那凭 外貌 不 凭 内心 夸口的人,有 言可答。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, ' 我们若果 颠狂,是为 神;若果 谨守,是为你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, '原来 基督 的爱 激励 我们;因我们 想, 一人 既替 众人 死,众人 就 都死了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, '并且 他替 众人 死,是叫 那些活著的 人不再 为自己 活,乃 为替 他们 死 而 复活的主活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, '所以,我们 从今以后,不 凭著外貌(原文是肉体;本节同)认人了。虽然 凭著 外貌 认过 基督,如今 却 不再 这样认他了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, ' 若 有人 在 基督里,他就是新 造的人,旧事 已过, 都变成 新的了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, ' 一切 都是出于  神;他 藉 借著 基督 使我们 与他 和好,又 将劝人与他和好 的职分 赐给 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, '这 就是 神 在 基督里,叫世人 与自己 和好,不 将他们的过犯 归到 他们 身上,并且 将这和好 的道理 托 讬付 了 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, '所以,我们作基督 的 使者,就好像 神 藉 借 我们 劝你们一般。我们替 基督 求你们与 神 和好。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, '神使 那无罪(无罪:原文是不 知 罪)的,替 我们 成为罪,好叫 我们 在 他 里面成为 神 的义。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, '我们与 神 同工的,也 劝 你们 不可 徒 受 他的恩典。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, '因为 他说:「在悦纳 的时候,我应允 了你; 在 拯救 的日子,我搭救 了你。」看哪,现在 正是悦纳 的时候! 现在 正是拯救 的日子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, '我们 凡事 都不 叫人有 妨碍,免得 这职分 被人毁谤; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, '反倒 在 各样的事 上表明 自己 是 神 的用人,就如在 许多的 忍耐、 患难、 穷乏、 困苦、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, ' 鞭打、 监禁、 扰乱、 勤劳、 警醒、 不食、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, ' 廉洁、 知识、 恒忍、 恩慈、 圣 灵的感化、 无伪的 爱心、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, ' 真实的 道理、 神 的大能; 仁义 的兵器 在左 在右; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, ' 荣耀、 羞辱, 恶名、 美名;似乎是 诱惑人的,却是 诚实的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, '似乎 不为人所知,却是 人所共知的;似乎 要死, 却是 活著的;似乎 受责罚,却是 不至 丧命的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, '似乎 忧愁,却是 常常 快乐的;似乎 贫穷,却是 叫许多人 富足的;似乎 一无 所有,却是 样样 都有的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, '哥林多人哪,我们 向 你们,口 是张开 的, 心 是宽宏的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, '你们狭窄,原不 在乎 我们,是 在乎 自己的 心肠 狭窄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, ' 你们 也要 照样 用宽宏的心 报答我。我这话正像 对自己的孩子 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, '你们和不信的 原不 相配,不要同负一轭。 义 和 不义 有什么 相交呢? 光明 和 黑暗 有什么 相通呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, ' 基督 和 彼列(彼列就是撒但的别名)有什么 相和呢? 信主的 和 不信主的 有什么 相干呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, ' 神 的殿 和 偶像 有什么 相同呢?因为 我们 是 永生 神 的殿,就如 神 曾说: 我要在 他们 中间居住, 在他们中间来往; 我要作 他们的 神; 他们 要作 我的 子民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, ' 又 说:你们务要从 他们 中间 出来, 与他们分别; 不要 沾 不洁净的物,我 就收纳 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, ' 我要作 你们 的父; 你们 要作 我的 儿 女。这是全能的 主 说的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, '亲爱的弟兄啊,我们既 有 这等 应许,就当洁净 自己,除去 身体、 灵魂 一切的 污秽, 敬畏 神,得以成 圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, '你们要心地宽大收纳 我们。我们未曾 亏负谁,未曾 败坏谁,未曾占谁 的便宜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, '我说这话,不是 要定 你们的罪。 我已经说过, 你们常在 我们 心里,情愿 与 你们同生 同死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, '我 大大地 放胆,向 你们说话;我 因 你们 多多 夸口,满得 安慰;我们 在 一切 患难中 分外地 快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, '我们 从前就是 到了 马其顿的时候, 身体 也不 得 安宁, 周围 遭患难,外 有争战 ,内 有惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, '但 那安慰 丧气之人的 神 藉 借著 提多 来 安慰 了我们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, ' 不但 藉 借著 他 来, 也 藉 借著 他从 你们 所得的安慰,安慰了我们;因他把你们的 想念、 哀恸,和 向 我 的热心,都告诉了 我,叫 我 更加 欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, ' 我先前 写信 叫你们 忧愁,我后来虽然 懊悔,如今却不 懊悔;因 我知道,那 信 叫你们 忧愁 不过 是暂时的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, '如今 我欢喜,不是 因 你们忧愁,是 因 你们从忧愁 中生出 懊悔来。 你们依著 神 的意思忧愁, 凡事就不 至于  因 我们 受亏损了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, '因为 依著 神 的意思忧愁,就生出 没有后悔的 懊悔来,以致 得救;但 世俗的 忧愁 是叫 人死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, ' 你看,你们 依著 神 的意思忧愁,从此 就生出 何等的 殷勤、 自诉、 自恨、 恐惧、 想念、 热心、 责罚(或译:自责)。在 这一切事上,你们都表明 自己 是 洁净的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, ' 我虽然 从前写信 给你们,却不是 为 那亏负人的,也不是 为 那受人亏负的,乃 要在 神 面前 把你们 顾念 我们的 热心 表明 出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, '故此,我们得了安慰。并且 在 安慰之中,因 你们 众人 使 提多 心里 畅快 欢喜,我们就更加 欢喜了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, ' 我若对提多 夸奖 了 你们 什么,也觉得没有 惭愧;因 我 对 提多 夸奖 你们的话成了 真的, 正如 我对你们 所说 的话 也都是真的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, '并且 提多想起 你们 众人 的顺服,是怎样 恐惧 战 兢地 接待 他,他 爱 你们 的心肠 就 越发热了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, '我如今欢喜, 能在 凡事 上为 你们 放心。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, ' 弟兄们,我把 神 赐给 马其顿 众教会 的恩 告诉 你们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, '就是 他们 在 患难 中受大 试炼的时候,仍有满足的 快乐, 在极 穷 之间还格外显出 他们 乐捐 的厚恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, '我可以证明, 他们是按著 力量,而且 也过了 力量,自己甘心乐意地捐助, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, '再三地 求 我们, 准他们在这供给 圣徒 的恩情 上有分; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, '并且他们所做的,不但 照 我们所想望的,更 照 神 的旨意 先 把自己 献给 主,又 归附了我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, '因此 我 劝 提多, 既然 在 你们 中间 开 办 这 慈惠的事,就 当 办成了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, '你们既然 在 信心、 口才、 知识、 热心,和 待 我们的 爱心 上,都格外显出满足来,就 当在 这 慈惠的事 上也 格外显出满足来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, '我说这话,不是 吩咐你们,乃是 藉 借著 别人 的热心 试验 你们 爱心 的实在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, ' 你们知道 我们 主 耶稣 基督 的恩典: 他本来 富足,却为 你们 成了贫穷,叫 你们 因他的 贫穷,可以成为富足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, ' 我在 这事 上把 我的意见告诉你们, 是与你们 有益;因为你们 下手 办这事,而且 起此心意,已经 有一年了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, '如今 就当 办成 这事。既有 愿 做 的心,也当 照 你们所有 的去办成。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, '因为 人若有 愿 做的 心,必蒙悦纳,乃是照 他所有的,并不是 照 他所无的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, ' 我原不是 要 别人 轻省,你们 受累, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, '乃 要 均平,就是要你们的 富余 馀,现在 可以补 他们的 不足,使 他们的 富余 馀,将来也 可以 补 你们的 不足,这 就 均平了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, '如 经上所记:多 收 的也没有 余 馀;少 收 的也 没有 缺。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, ' 多谢 神, 感动 提多 的心,叫他待 你们 殷勤,像我一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, ' 他固然 是听了 我的劝,但 自己更是 热心,情愿  往 你们 那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, '我们还 打发 一位兄弟 和 他同去,这人 在 福音 上得了众 教会 的称赞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, ' 不但这样,他也 被 众教会 挑选,和我们 同行,把 所托 讬 与 我们 的这 捐赀 送到了,可以 荣耀 主,又 表明我们 乐意的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, '这 就免得 有人 因 我们 收的 捐银很多,就挑我们 的不是。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, ' 我们留心行 光明的事,不但 在主 面前,就在人 面前 也是这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, '我们 又 打发 一位兄弟 同去;这人 的热心,我们在 许多事 上屡次 试验过。 现在 他因为深 信 你们,就更加 热心了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, '论到 提多,他是我的 同伴, 一同 为 你们劳碌的。论到 那两位 兄弟,他们是众教会 的使者,是基督 的荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, '所以,你们务要在 众教会 面前 显明 你们 爱心 的凭据,并 我 所夸奖 你们的 凭据。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, '论到 供给 圣徒 的事,我 不必 写信 给你们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, '因为 我知道 你们 乐意的心, 常对马其顿人 夸奖 你们,说 亚该亚人 预备好了,已经 有一年了;并且 你们的 热心 激动 了许多人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, '但 我打发 那几位弟兄去,要叫 你们照 我的话 预备妥当,免得 我们 在 这 事 上夸奖 你们 的话落了空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, '万一 有马其顿人 与 我 同去, 见 你们 没有预备,就叫我们 所 确信的,反成了羞愧;你们羞愧,更不用 说了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, '因此,我想 不得不 求 那几位弟兄 先到 你们那里去, 把从前所应许 的捐赀 预备 妥当,就 显出你们 所捐的 是出于  乐意, 不是 出于  勉强。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, '「 少 种的 少 收, 多 种 的 多 收」,这话是真的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, '各人 要随 本心 所酌定的,不要 作难,不要 勉强,因为 捐 得乐意的人是 神 所喜爱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, ' 神 能 将各样的 恩惠 多多地 加给 你们,使 你们 凡事 常常 充足,能多 行 各样 善 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, '如 经上所记:他施舍钱财,赒济 贫穷;他的 仁义 存 到 永远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, ' 那赐 种 给撒种的, 赐粮 给 人吃的,必 多多加 给 你们 种地的种子,又 增添 你们 仁义 的果子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, '叫你们凡事 富足,可以 多多 施舍,就 藉 借著 我们 使感谢 归于  神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, '因为 办这 供给 的事,不但 补 圣徒 的缺乏,而且 叫 许多人 越发 感谢 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, '他们从 这 供给的事 上得了凭据,知道 你们 承认 基督 顺服 他的福音, 多多地 捐钱 给 他们 和 众人,便将荣耀归与 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, '他们 也 因 神 极大的 恩赐 显在 你们心里,就切切地想念 你们,为 你们 祈祷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, '感谢 神,因 他 有说不尽的 恩赐!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, '我-保罗,就是 与 你们 见面 的时候是谦卑的, 不在 你们那里的时候向 你们 是勇敢的,如今 亲自 藉 借著 基督 的温柔、 和平 劝 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, ' 有人 以为 我 是 凭著 血气 行事,我也以为 必须用勇敢 待 这等人;求 你们不要 叫我在 你们那里的时候,有这样的勇敢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, '因为 我们虽然在 血气中 行事,却不 凭著 血气 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, ' 我们 争战 的 兵器 本不是 属血气的,乃是在 神 面前有能力,可以 攻破 坚固的营垒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, '将各样的计谋, 各样 拦阻 人认识 神 的那些自高之事,一概攻破了,又 将人所有的 心意 夺回,使 他都顺服 基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, '并且 我已经 预备好了,等你们 十分 顺服 的时候,要责罚 那一切 不顺服的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, '你们是看 眼前的吗?倘若 有人 自 信 是 属基督的, 他 要再 想想, 他 如何 属基督,我们 也是如何属基督的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, ' 主 赐给 我们权柄,是 要 造就你们,并 不是 要 败坏 你们;我就是 为 这权柄 稍微 夸口,也不 至于 惭愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, '我说这话,免得 你们以为 我 写信 是要威吓 你们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, '因为 有人说:「他的信 又沉重 又 厉害,及至 见面,却是气貌不扬, 言语 粗俗的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, '这等人 当想, 我们不在那里的时候, 信上 的言语 如何,见面的时候,行事也 必 如何。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, '因为 我们不 敢 将自己 和那自 荐 的人 同列 相比。 他们 用 自己 度量 自己, 用自己 比较 自己,乃是不 通达的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, ' 我们 不 愿 意分外 夸口,只要 照 神 所量 给我们 的界限 搆 到 你们那里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, ' 我们并非 过了 自己的界限,好像 搆 不 到 你们那里;因为 我们早到 你们那里, 传了基督 的福音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, '我们不 仗著 别人 所劳碌的,分外 夸口;但 指望 你们 信心 增长的时候, 所量给我们 的界限,就可以因著 你们 更加 开 展, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, '得以将福音传 到 你们 以外的地方;并不是 在 别人 界限之内,藉 借著 他现成的 事夸口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, '但 夸口的,当指著 主 夸口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, '因为 蒙悦纳的,不是 自己 称许的, 乃是 主 所称许的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, '但愿  你们宽容 我 这一点 愚妄, 其实 你们原是宽容 我的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, ' 我为你们 起的愤恨,原是 神 那样的愤恨。因为 我曾把你们 许配 一个 丈夫,要把你们如同贞洁的 童女,献给 基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, ' 我只 怕 你们的 心 或偏于 邪,失去 那向 基督 所存纯一 清洁的心,就像 蛇 用 诡诈 诱惑 了夏娃一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, ' 假如 有人来 另 传 一个耶稣, 不是 我们所传过的;或者 你们另 受 一个灵, 不是 你们所受过的;或者 另 得一个福音, 不是 你们所得过的;你们容让 他也就罢了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, '但 我想,我一点不 在那些最 大的使徒 以下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, '我的言语 虽然 粗俗,我的知识 却 不粗俗。 这是我们在 凡事 上向 你们 众人显明出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, '我因为 白白 传 神 的福音 给你们,就自 居卑微,叫 你们 高升,这算是 我犯 罪吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, '我亏负 了别的 教会,向他们取了 工价 来给 你们 效力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, ' 我在 你们 那里 缺乏的时候, 并没有 累著你们一个人;因 我 所缺乏的,那从 马其顿 来 的弟兄们 都补足了。 我 向来 凡事 谨守,后来也 必谨守,总不至于 累著 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, '既有 基督 的诚实 在 我里面,就 无人 能在 亚该亚 一带地方 阻挡 我 这 自夸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, '为什么呢?是因 我不 爱 你们吗?这有 神 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, ' 我现在所做 的,后来还要 做,为要 断绝 那些寻 机会 人的机会,使 他们在 所夸的 事上 也不过与 我们 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, ' 那等人 是假使徒,行事 诡诈,装作 基督 使徒的模样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, '这也 不 足为怪,因为 连撒但 也装作 光明 的天使。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, '所以 他的 差役,若 装 作 仁义的 差役,也不算 希奇。他们的 结局 必然 照著 他们的 行为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, '我再 说,人 不可 把我 看 作 愚妄的。纵然如此,也要 把我 当作 愚妄人 接纳,叫 我 可以略略 自夸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, '我说 的话 不是 奉 主 命说的,乃是 像 愚妄人 放胆 自夸; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, '既有 好些人 凭著 血气 自夸,我也要 自夸了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, ' 你们既是 精明人,就能甘心 忍耐 愚妄人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, ' 假若有人 强你们 作奴仆,或 侵吞你们,或 掳掠你们,或 侮慢你们,或 打 你们 的脸,你们都能忍耐他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, '我说 这话是 羞辱自己,好像 我们 从前是软弱的。然而,人 在 何事 上勇敢,(我说 句愚妄话,)我也 勇敢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, '他们是 希伯来人吗?我也是。他们是 以色列人吗?我也是。他们是 亚伯拉罕 的后裔吗?我也是。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, '他们是 基督 的仆人吗?(我说 句狂话,)我 更是。我比他们多 受 劳苦,多 下 监牢,受 鞭打 是过重的,冒 死 是屡次有的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, '被 犹太人 鞭打 五次,每次四十 减去 一下; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, '被棍打 了三次;被石头打 了一次;遇著船坏 三次,一昼一夜 在 深海里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, '又屡次 行远路,遭江河 的危险、盗贼 的危险、 同族 的危险、 外邦人 的危险、 城里 的危险、 旷野 的危险、 海中 的危险、 假弟兄 的危险。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, '受劳碌、 受困苦,多次 不得睡, 又饥 又 渴,多次 不得食,受 寒冷, 赤身露体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, '除了 这外面的事,还有为众 教会 挂心 的事, 天天 压在 我身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, '有谁 软弱, 我不 软弱呢?有谁 跌倒, 我 不 焦急呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, '我若 必须 自夸,就夸 那关乎 我 软弱的事便了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, '那 永远 可称颂 之主 耶稣 的父 神 知道 我 不 说谎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, '在 大马士革的 亚哩达 王 手下的提督 把守 大马士革 城,要捉拿 我, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, '我就 从 窗户中,在 筐子里,从 城墙 上被人缒下去, 脱离 了他的 手。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, '我 自夸 固然 无 益,但我是不得已的。如今我要说到 主 的显现 和 启示。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, '我认得 一个在 基督 里的人,他 前 十四 年 被提 到 第三 层天上去;(或 在身 内,我不 知道;或 在身 外,我也不 知道;只有 神 知道。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, ' 我认得 这 人;(或 在身 内,或 在身 外,我都不 知道,只有 神 知道。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, ' 他被提 到 乐园里, 听见 隐秘的 言语, 是人 不 可 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, '为 这人,我要夸口;但 是为 我自己,除了 我的软弱以外,我并不 夸口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, ' 我就是 愿 意 夸口 也不 算 狂,因为 我必说 实话;只是 我禁止不说,恐怕 有人 把 我 看 高了, 过于 他在 我 身上所看见、所听见的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, '又 恐怕 我因所得的启示 甚大,就过于 自高,所以有一根刺 加 在我 肉体上,就是撒但 的差役 要 攻击 我,免得 我过于 自高。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, '为 这事,我三次 求 过主,叫 这刺离开  我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, ' 他对我 说:「我的 恩典 够 你用的,因为 我的能力 是在 人的软弱 上显得完全。」所以,我更 喜欢 夸 自己的 软弱,好叫 基督 的能力 覆 复庇 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, ' 我为基督 的缘故,就以 软弱、 凌辱、 急难、 逼迫、 困苦 为可喜乐的;因 我什么时候 软弱,什么时候 就 刚强了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, '我 成了 愚妄人,是被你们 强逼的。 我 本该 被 你们 称许才是。 我虽 算 不了什么,却 没有一件事 在那些最大的使徒 以下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, '我在 你们中间,用 百般的 忍耐,藉 借著神迹、 奇事、 异能 显出 使徒 的凭据来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, '除了 我 不 累著 你们 这一件事, 你们还有 什么事 不及 别的 教会呢?这不公之处,求你们饶恕 我吧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, '如今,我打算 第三次 到 你们 那里去,也 必不 累著你们;因 我所求 的是 你们,不是 你们的财物。 儿女 不 该 为父母 积财, 父母 该为儿女积财。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, '我 也 甘心乐意 为 你们的 灵魂 费财 费力。难道 我越发 爱 你们,就越发少得 你们的爱吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, ' 罢了,我 自己并没有 累著 你们,你们却有人说,我是 诡诈,用心计 牢笼 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, '我所差 到 你们 那里去的人,我藉 借著 他们 一个人 占过你们 的便宜吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, '我劝了 提多到你们那里去,又 差 那位兄弟与他同去。 提多 占过你们 的便宜吗?我们行事,不 同是一个心灵(或译:圣灵)吗?不 同 是一个脚踪吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, '你们到如今,还 想 我们是向你们 分诉;我们本是在 基督里当 神 面前 说话。 亲爱的弟兄啊,一切的事 都是为 造就 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, ' 我怕 我再来的时候,见 你们 不 合 我所想望的,你们 见 我 也不 合 你们所想望的;又 怕有纷争、嫉妒、恼怒、结党、毁谤、谗言、狂傲、混乱的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, '且 怕我 来的时候,我的 神 叫我 在 你们 面前惭愧,又 因许多人 从前犯罪, 行 污秽、 奸淫、 邪荡的事 不肯 悔改,我就忧愁。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, '这是 我第三 次要到 你们 那里去。「凭 两 三 个人的口 作见证,句句 都要定准。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, '我从前说过, 如今 不在 你们那里又 说,正如 我第二次 见你们的时候所说的一样,就是对那犯了罪 的和 其余 馀的 人说:「我若 再 来,必不 宽容。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, '你们既然 寻求 基督 在我 里面 说话 的凭据,我必不宽容。因为,基督在 你们 身上不 是软弱的, 在你们 里面 是有大能的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, ' 他因 软弱 被钉在十字架上,却 因 神 的大能 仍然活著。 我们 也 是这样同 他 软弱,但 因 神 向 你们 所显的大能,也必与 他 同活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, '你们 总要自己省察 有 信心没有,也要自己 试验。岂 不 知 你们 若 不 是 可弃绝的,就 有耶稣 基督 在你们 心里吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, '我却 盼望 你们晓得, 我们 不 是 可弃绝的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, ' 我们求 神,叫你们 一件恶事 都不 做;这 不是 要显明 我们 是蒙悦纳的, 是要 你们 行事 端正,任凭 人看我们 是 被弃绝的吧! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, ' 我们凡事 不 能 敌挡 真理,只能 扶助 真理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, '即使 我们 软弱, 你们 刚强,我们也欢喜;并且我们所求的,就是 你们 作完全人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, '所以,我不在你们那里的时候,把这话 写给你们,好叫我见你们的时候,不用 照 主 所给 我 的权柄 严厉地 待你们。这权柄原是为 造就人,并 不是 为 败坏人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, '还有末了的话:愿 弟兄们 都喜乐。要作完全人;要受安慰;要同心合意;要彼此和睦。如此,仁爱 和平的 神 必常与 你们 同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, '你们 亲嘴 问安,彼此 务要圣洁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, '众 圣徒 都问 你们安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, '愿 主 耶稣 基督 的恩惠、 神 的慈爱、 圣 灵 的感动 常与你们 众人 同在!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, '作使徒 的保罗(不是 由于  人,也不是 藉 借著 人,乃是 藉 借著 耶稣 基督,与 叫他 从 死里 复活 的父 神) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, '和 一切 与我 同在 的众弟兄,写信给加拉太 的各教会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, '愿 恩惠、 平安 从 父 神 与 我们的 主 耶稣 基督 归与你们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, '基督 照 我们 父 神 的旨意,为 我们的 罪 舍 己,要 救 我们 脱离 这 罪恶的 世代。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, '但愿 荣耀归于  神,直到 永永远远。阿们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, '我希奇 你们这么 快 离开  那 藉 借著 基督 之恩 召 你们的,去从 别的 福音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, '那 并不 是 福音,不过 有些人 搅扰 你们, 要 把基督 的福音 更改了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, '但 无论是 我们,是 天上 来的 使者,若传福音 给你们,与 我们所传给 你们 的不同,他就应当 被咒诅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, '我们 已经说了, 现在 又说,若 有人 传福音 给你们,与你们所 领受的 不同,他就应当 被咒诅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, ' 我现在 是要得人 的心呢?还是要得 神的心呢?我岂是 讨 人 的喜欢吗?若 仍旧 讨人 的喜欢,我就 不 是 基督 的仆人了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, ' 弟兄们,我告诉 你们, 我 素来所 传 的 福音 不 是 出于 人 的意思。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, '因为 我 不是 从 人 领受 的,也不是 人教导我的,乃是 从 耶稣 基督 启示来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, ' 你们听见 我 从前 在犹太教 中 所行的事,怎样 极力 逼迫 残害 神 的教会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, '我又 在犹太教 中,比我本 国 许多 同岁的人 更有 长进, 为我 祖宗 的遗传 更加 热心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, '然而, 那 把我 从 母 腹里 分别出来、又 施恩 召我的 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, '既然乐意 将他 儿子 启示 在我 心里, 叫我把他 传 在外邦人 中,我就 没有 与属血气的人 商量, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, '也没有 上 耶路撒冷 去 见 那些比我 先 作使徒的,惟独 往 阿拉伯 去, 后又回 到 大马士革。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, '过了 三 年,才上 耶路撒冷 去见 矶法, 和他 同 住了 十五 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, '至于  别的 使徒,除了 主 的兄弟 雅各,我都没有 看见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, ' 我写 给你们 的 不是 谎话,这是我在 神 面前说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, '以后 我到了 叙利亚 和 基利家 境 内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, '那时, 犹太 信 基督 的各教会 都 没有见过 我的面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, ' 不过 听说 那 从前 逼迫 我们的,现在 传扬 他原先 所残害的 真道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, ' 他们就为我 的缘故,归荣耀给 神。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, ' 过了 十四 年,我同 巴拿巴 又 上 耶路撒冷 去,并 带著 提多同去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, ' 我是奉 启示 上去的, 把我在外邦人 中 所传的 福音 对弟兄们 陈说;却是 背地里 对那有名望之人说的,惟恐我现在,或是 从前,徒然 奔跑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, '但 与我 同去 的 提多,虽是 希腊人,也没有 勉强 他受割礼; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, ' 因为 有偷著引进来 的假弟兄, 私下 窥探 我们 在基督 耶稣 里 的 自由,要叫 我们 作奴仆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, '我们就是 一刻的工夫 也没有 容让 顺服 他们,为要叫 福音 的真理 仍存在 你们 中间。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, ' 至于  那些有名望的,不论他是 何等人,都与我 无 干。 神 不 以外貌 取人。 那些有名望的,并没有加增 我 什么, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, ' 反倒 看见了 主托 讬 我传福音 给那未受割礼的人,正如 托 讬彼得 传福音给那受割礼的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '( 那感动 彼得、叫 他为受割礼之人 作使徒的,也 感动 我,叫 我为外邦人作使徒;) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, ' 又知道 所赐给 我 的恩典,那 称为 教会柱石 的雅各、 矶法、 约翰,就向 我 和 巴拿巴 用右手 行相交之礼,叫 我们 往外邦人 那里去, 他们 往受割礼的人 那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, '只是 愿 意我们记念 穷人;这 也是 我本来热心 去行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, ' 后来,矶法 到了 安提阿;因 他有 可责之处,我就当面 抵挡 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, ' 从 雅各 那里来 的人 未到以先,他和外邦人 一同 吃饭, 及至 他们来到,他因怕 奉 割礼的人,就退去 与外邦人隔开 了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, ' 其余 馀的 犹太人 也都随著 他 装假,甚至 连巴拿巴 也 随伙 夥 装假。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, '但 我一看见 他们行的不 正,与福音 的真理 不合,就在众人 面前 对矶法 说:「你 既是 犹太人,若 随外邦人 行事, 不 随犹太人行事,怎么 还勉强 外邦人 随犹太人呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, '我们 这生来的 犹太人, 不是 外邦 的 罪人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, '既 知道 人 称义 不是 因 行 律法,乃是 因 信 耶稣 基督,连 我们 也信了 基督 耶稣,使 我们因 信 基督 称义, 不 因 行 律法称义;因为 凡有血气的,没有 一人因 行 律法 称义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, ' 我们若 求 在基督 里 称义, 却仍旧 是 罪人,难道 基督 是叫人犯 罪的吗?断乎不是! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, ' 我素来所拆毁 的,若 重新 建造,这就证明 自己 是犯罪的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, ' 我 因 律法,就向律法 死了,叫我可以向 神 活著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, '我已经与基督 同钉十字架, 现在活著 的不再是 我,乃是 基督 在我 里面 活著;并且 我如今 在 肉身 活著,是因 信 神 的儿子 而活;他 是爱 我, 为 我 舍 己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, '我不 废掉 神 的恩; 义 若是 藉 借著 律法得的, 基督 就是徒然 死了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, ' 无知的 加拉太人哪,耶稣 基督 钉十字架,已经活画 划 在你们 眼 前,谁 又迷惑了 你们呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, '我只要 问 你们 这 一件:你们受了 圣灵,是因 行 律法呢? 是因 听 信福音呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, '你们既靠圣灵 入门,如今 还靠肉身 成全吗?你们是 这样的 无知吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, '你们受苦 如此之多,都是徒然的吗?难道果真 是 徒然的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, '那 赐给 你们 圣灵,又 在你们 中间 行 异能的,是因 你们行 律法呢?是 因 你们听 信福音呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, '正如「亚伯拉罕 信 神, 这就算为 他 的 义」。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, '所以,你们要知道:那 以信 为本的人,就是 亚伯拉罕 的子孙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, '并且 圣经 既然预先看明, 神 要叫外邦人 因 信 称义,就早已传福音 给亚伯拉罕,说:「万国 都必因 你 得福。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, '可见 那以信 为本 的人和有信心的 亚伯拉罕 一同 得福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, ' 凡 以行 律法 为本的,都是 被咒诅的;因为 经上记著:「凡 不 常 照 律法 书 上 所记 一切之事 去行 的,就被咒诅。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, ' 没有一个人 靠著 律法在 神 面前 称义,这是明显的;因为经上说:「义人 必因 信 得生。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, ' 律法 原不 本乎 信,只说:「行 这些事的,就必因 此 活著。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, '基督 既为 我们受(原文是成)了咒诅,就赎出 我们 脱离 律法 的咒诅;因为 经上记著:「凡 挂在 木头 上 都是被咒诅的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, '这 便叫亚伯拉罕 的福,因 基督 耶稣 可以临 到 外邦人,使 我们因 信 得著 所应许的 圣灵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, '弟兄们,我且照著 人 的常话说:虽然 是人 的文约,若已经立定了,就没有能 废弃 或 加增的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, ' 所应许的 原是向亚伯拉罕 和 他 子孙 说的。 神并不是 说「众子孙」,指著 许多人,乃是说「你 那一个子孙」,指著 一个人, 就是 基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, ' 我是这么 说, 神 预先所立的 约,不能 被那 四百 三十 年 以后的 律法 废掉,叫 应许 归于 虚空。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, '因为 承受产业,若 本乎 律法,就不 本乎 应许;但 神 是凭著 应许 把产业赐给 亚伯拉罕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, '这样说来,律法 是为什么有的呢?原是为 过犯 添上的,等候 那 蒙应许的 子孙 来到,并且是藉 借 天使 经 中保 之手 设立的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, '但 中保 本不 是 为一面作的; 神 却是 一位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, '这样,律法是与 神 的应许 反对吗?断乎不是! 若 曾传 一个 能 叫人得生 的律法,义 就 诚然 本乎 律法了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, '但 圣经 把众人 都圈在 罪 里,使 所应许的 福因 信 耶稣 基督,归给 那信的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, '但 这因信 得救的理还未来 以先,我们被看守 在律法 之下,直圈 到 那将来的 真道 显明出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, '这样,律法 是 我们 训蒙的师傅,引我们到 基督那里,使 我们因 信 称义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, '但 这因信 得救的理既然来到,我们从此就 不在 师傅 的手下了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, '所以,你们因 信 基督 耶稣 都 是 神 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, ' 你们受洗 归入 基督 的 都是披戴 基督了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, '并不分 犹太人、 希腊人, 自主的、 为奴的, 或 男 或 女,因为 你们 在基督 耶稣 里 都 成为 一了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, ' 你们 既 属乎基督, 就是 亚伯拉罕 的后裔,是照著 应许 承受产业的了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, ' 我说 那承受产业的,虽然是 全业 的主人,但为 孩童 的时候 却与奴仆 毫无分别, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, '乃 在师傅 和 管家 的手下,直 等他父亲 预定的时候来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, '我们 为 孩童 的时候, 受管于  世俗 小学 之下,也是 如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, ' 及至 时候 满足, 神 就差遣 他 的儿子,为 女子 所生,且 生在律法 以下, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, '要 把律法 以下 的人赎出来,叫 我们得著 儿子的名分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, ' 你们既为 儿子, 神 就差 他 儿子 的灵 进入你们(原文是我们)的心,呼叫:「阿爸!父!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, '可见,从此以后,你不 是 奴仆,乃是 儿子了; 既是 儿子,就 靠著 神 为后嗣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, '但 从前你们不 认识 神 的时候,是给那些本来 不 是 神 的作奴仆; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, '现在 你们既然 认识 神,更 可说是 被 神 所认识的,怎么 还要归回 那懦弱 无用的 小学,情愿  再 给他 作奴仆呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, '你们谨守 日子、 月份、 节期、 年份, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, '我为你们 害怕,惟恐 我在你们 身上 是枉费了 工夫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, '弟兄们,我劝 你们 要 像 我一样,因为 我 也像 你们一样。你们一点没有 亏负 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, ' 你们知道 我头一次 传福音 给你们,是 因为 身体 有疾病。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, ' 你们为 我 身体 的缘故受 试炼,没有 轻看我,也没有 厌弃我,反倒 接待 我,如同 神 的使者,如同 基督 耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, '你们 当日 所夸的福气 在哪里呢?那时你们若 能行,就是把自己的 眼睛 剜出来 给 我,也都情愿 。 这是 我可以给你们 作见证的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, '如今我将真理告诉 你们,就 成了 你们的 仇敌吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, '那些人热心待 你们,却不是 好意, 是要 离间 你们(原文是把你们关在外面),叫 你们热心待 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, ' 在 善事上,常用 热心 待人原是好的, 却 不 单 我 与你们 同 在的时候才这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, '我 小子啊,我为你们 再 受生产之苦,直等到 基督 成形 在你们 心里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, ' 我巴不得 现今 在 你们那里, 改换 口气,因 我为 你们 心里作难。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, '你们这愿 意 在 律法 以下的人,请告诉 我,你们岂没有 听见 律法吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, '因为 律法上记著, 亚伯拉罕 有 两个 儿子,一个 是使女 生的, 一个 是自主之妇人 生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, '然而,那 使女 所生的 是按著 血气 生的; 那自主之妇人 所生的 是凭著 应许生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, '这 都是 比方: 那 两个妇人就是 两 约。一约 是出于  西奈 山,生子 为 奴, 乃是 夏甲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, ' 这夏甲 二字是指著 阿拉伯 的西奈 山,与 现在的 耶路撒冷 同类,因 耶路撒冷和 她 的儿女 都是为奴的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, '但 那在上的 耶路撒冷 是 自主的, 她是 我们 的母。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, '因为 经上记著:不怀孕、不 生养的,你要欢乐;未曾经过 产难的,你要高声欢呼;因为 没有丈夫的,比 有 丈夫 的儿女 更多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, ' 弟兄们,我们 是 凭著应许 作儿女,如同以撒 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, ' 当时,那按著 血气 生的 逼迫了 那按著 圣灵生的,现在 也是 这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, '然而 经上 是怎么 说的呢?是说:「把使女 和 她 儿子 赶出去!因为 使女 的儿子 不可 与自主妇人 的儿子 一同 承受产业。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, '弟兄们,这样看来,我们不 是 使女 的儿女,乃是 自主妇人的儿女了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, '基督 释放了 我们,叫我们得以自由。所以 要站立得稳, 不要 再 被奴仆 的轭 挟制。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, ' 我-保罗 告诉 你们,若 受割礼,基督 就与你们 无 益了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, ' 我再 指著凡 受割礼 的人 确实地说, 他是 欠著行 全 律法 的债。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, '你们 这要靠 律法 称义的,是与 基督 隔绝,从恩典 中坠落了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, ' 我们 靠著圣灵,凭著 信心,等候 所盼望的 义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, '原来 在 基督 耶稣里,受割礼 不受割礼 全无 功效,惟独 使人生发 仁爱 的信心 才有功效。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, '你们向来跑得 好,有谁 拦阻 你们,叫你们不 顺从 真理呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, '这样的劝导 不是 出于  那召 你们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, '一点 面 麺酵 能使全 团 都发起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, '我 在主 里 很信 你们 必不 怀别样的 心;但 搅扰 你们的,无论 是谁,必担当 他的罪名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, ' 弟兄们,我 若 仍旧 传 割礼,为什么 还 受逼迫呢?若是这样,那 十字架 讨厌的地方 就没有了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, '恨不得 那搅乱 你们 的人把自己割绝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, ' 弟兄们,你们 蒙召 是要得 自由,只是 不可 将你们的自由 当作 放纵情欲 的机会,总要 用 爱心 互相 服事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, '因为 全 律法 都包在「爱 人 如 己」这一句 话 之内了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, ' 你们要谨慎,若 相咬 相吞,只怕要 彼此 消灭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, '我说,你们当顺著圣灵 而行,就 不 放纵 肉体 的情欲了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, '因为 情欲 和圣灵 相争, 圣灵 和情欲 相争, 这 两个是彼此 相敌,使 你们不能 做 所 愿 意 做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, '但 你们若 被圣灵 引导,就 不 在律法 以下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, ' 情欲 的事 都是 显而易见的,就 如 奸淫、污秽、邪荡、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, '拜偶像、邪术、仇恨、争竞、忌恨、恼怒、结党、纷争、异端、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, '嫉妒(有古卷加:凶杀二字)、醉酒、荒宴 等类。 我从前 告诉你们, 现在又告诉你们, 行 这样事 的人必不能 承受 神 的国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, ' 圣灵 所结的果子,就是 仁爱、喜乐、和平、忍耐、恩慈、良善、信实、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, '温柔、节制。这样的事 没 有 律法 禁止。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, ' 凡 属基督 耶稣的人,是已经把肉体 连 肉体的邪情 私欲 同钉在十字架上了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, '我们若是 靠圣灵 得生,就当 靠圣灵 行事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, '不 要 贪图虚名,彼此 惹气,互相 嫉妒。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, '弟兄们,若 有人 偶然被 过犯 所胜,你们 属灵的 人就当用 温柔的 心 把他 挽回过来;又当自己 小心,恐怕 也 被引诱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, '你们各人的重担 要互相 担当, 如此,就完全了 基督 的律法。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, ' 人 若 无有,自己 还以为 有,就是自 欺了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, ' 各人 应当察验 自己 的行为;这样,他所 夸 的就专在 自己, 不 在 别人了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, '因为 各人 必担当 自己的 担子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, ' 在道理 上受教的,当把 一切 需用的 供给 施教的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, '不要 自欺, 神 是轻慢 不得的。 人 种 的是什么,收的 也是 什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, ' 顺著 情欲 撒种的,必从 情欲 收 败坏; 顺著 圣灵 撒种的,必从 圣灵 收 永 生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, ' 我们行 善,不可 丧志;若不 灰心, 到了 时候 就要收成。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, '所以, 有了 机会 就当向 众人 行 善,向 信徒 一家的人 更当这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, '请看 我 亲手 写 给你们 的字 是何等的大呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, '凡 希图 外貌 体面 的人 都勉强 你们 受割礼,无非 是怕 自己为基督 的十字架 受逼迫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, ' 他们 那些受割礼的,连自己也不 守 律法; 他们愿 意 你们 受割礼,不过要 藉 借著 你们 的肉体 夸口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, '但 我 断不 以别的夸口,只 夸我们 主 耶稣 基督 的十字架;因 这十字架,就我而论,世界 已经钉在十字架上;就世界而论,我已经钉在十字架上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, ' 受割礼 不受割礼 都无关 紧要, 要紧的就是作新 造的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, ' 凡 照此 理 而行的,愿 平安、 怜悯 加给 他们,和 神 的以色列民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, '从今以后,人 都不要搅扰 我,因为 我 身上 带著 耶稣 的印记。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, '弟兄们,愿 我 主 耶稣 基督 的恩 常在 你们 心里。阿们!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, '奉 神 旨意,作基督 耶稣 使徒 的保罗,写信给在 以弗所 的圣徒, 就是 在 基督 耶稣 里有忠心的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, '愿 恩惠、 平安 从 神 我们的 父 和 主 耶稣 基督 归与你们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, '愿 颂赞 归与我们 主 耶稣 基督 的父 神!他 在 基督 里曾赐 给 我们 天上 各样 属灵的 福气: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, '就如 神从创立 世界 以前,在 基督 里拣选 了我们,使我们 在他 面前 成为 圣洁,无有瑕疵; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, '又因爱我们,就按著 自己的 意旨 所喜悦的,预定 我们 藉 借著 耶稣 基督 得 儿子的名分, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, '使他 荣耀 的恩典 得著 称赞;这恩典是他在 爱子 里所赐给 我们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, ' 我们藉 借 这爱子的 血 得蒙 救赎,过犯 得以赦免,乃是照 他 丰富的 恩典。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, '这恩典是 神用 诸般 智慧 聪明,充充足足 赏给 我们的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, '都是照 他自己 所预定的 美意,叫我们 知道 他 旨意 的奥秘, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, '要照 所安排的,在日期 满足的时候,使 天上、 地上、一切所有的 都在基督 里面 同归于 一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, '我们也 在他 里面得(得:或译成)了基业;这原是那位随 己 意行、做万事的,照著 他旨意 所预定的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, '叫他的 荣耀 从 我们 这首先在基督 里 有盼望的 人可以 得著 称赞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, ' 你们 既听见 真理 的道,就是那叫你们 得救 的福音, 也信了基督,既然信他,就受了所应许 的圣 灵 为印记。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, '这 圣灵是 我们 得基业 的凭据(原文是质),直等到 神之民(民:原文是产业)被赎,使 他的 荣耀 得著称赞。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, '因此,我既 听见 你们 信从 主 耶稣, 亲爱 众 圣徒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, '就为 你们 不 住 地感谢 神。 祷告的时候,常提到你们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, ' 求我们 主 耶稣 基督的 神,荣耀的 父,将那赐人智慧 和 启示 的灵 赏给 你们,使你们真知道 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, '并且照明 你们 心中 的眼睛, 使你们 知道 他的 恩召 有 何等 指望,他 在圣徒 中 得的基业 有何等 丰盛的 荣耀; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, '并 知道他 向 我们 这 信 的人 所显的能力 是何等 浩大, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, ' 就是照他在 基督 身上所运行的大能大力,使他 从 死 里复活, 叫他在 天上 坐 在 自己 的右边, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, '远超过 一切 执政的、 掌权的、 有能的、 主治的,和 一切 有名的;不 但 是 今 世的,连 来世的 也都超过了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, '又 将万有 服在 他的 脚 下, 使 他 为教会 作 万有 之首。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, '教会 是 他的 身体, 是那充满 万有 者所充满的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, ' 你们 死在 过犯 罪恶之中,他叫你们活过来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, '那时,你们在 其中 行事为人,随从 今 世 的风俗,顺服 空中 掌权者 的首领,就是现今 在 悖逆 之子 心中运行 的邪灵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, '我们 从前 也 都 在他们 中间, 放纵 肉体的 私欲,随著 肉体 和 心 中所喜好的去行, 本为 可怒 之子,和 别人 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, '然而, 神 既有 丰富的 怜悯,因 他 爱 我们 的大 爱, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, '当 我们 死 在过犯中的时候,便叫我们与 基督一同活过来。你们得救 是 本乎恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, ' 他又叫我们与 基督 耶稣 一同复活, 一同 坐在 天上, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, ' 要将他 极 丰富的 恩典,就是他在 基督 耶稣 里向 我们 所施的恩慈,显明 给 后来的 世代看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, ' 你们得救 是 本乎恩,也因著 信; 这 并不是 出于  自己,乃是 神 所赐的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, '也不是 出于  行为,免得 有人 自夸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, ' 我们原是 他的 工作,在 基督 耶稣 里造成的,为要 叫我们行善,就是 神 所预备 叫我们行 的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, '所以 你们应当记念: 你们从前 按 肉体 是 外邦人, 是称为 没受割礼的;这名原是 那些 凭人手 在 肉身 上称为 受割礼之人所起的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, ' 那 时,你们 与基督 无关,在以色列 国民 以外, 在所应许的 诸约 上是局外人,并且活在 世上 没 有 指望,没有 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, '你们 从前 远离 神的人,如今 却 在 基督 耶稣里,靠著 他 的血,已经得 亲近了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, '因 他 使 我们 和睦(原文是因他是我们的和睦), 将 两下 合而为一, 拆毁 了中间隔断 的墙; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, '而且以 自己的 身体 废掉 冤仇,就是那记在 律法 上的规条,为要 将两下 藉 借著 自己 造成 一个 新 人,如此便成就 了和睦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, '既在 十字架上灭 了冤仇,便藉 借 这十字架 使两下 归为 一 体,与 神 和好了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, '并且 来 传 和平 的福音给你们 远处的人, 也 给那近处的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, '因为 我们两下 藉 借著 他 被 一个 圣灵 所感,得以 进到 父面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, '这样,你们不再 作外人 和 客旅, 是 与圣徒 同国,是 神 家里的人了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, '并且被建造 在使徒 和 先知 的根基 上,有基督 耶稣 自己 为 房角石, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, '各(或译:全)房 靠 他 联络得合式,渐渐成 为 主 的圣 殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, '你们 也 靠 他 同被建造,成为 神 藉 借著 圣灵 居住的所在。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, '因此,我─保罗 为 你们 外邦人 作了基督 耶稣 被囚的,替你们祈祷(此句是照对十四节所加)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, '谅必 你们曾听见 神 赐恩给我,将 关切你们 的职分 托 讬付 我, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, ' 用 启示 使我 知道 福音的奥秘,正如 我以前 略略写过的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, '你们念了,就 能 晓得 我 深知 基督 的奥秘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, '这奥秘 在以前的 世代 没有 叫人 知道,像 如今 藉 借著 圣灵 启示 他的 圣 使徒 和 先知一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, '这奥秘就是外邦人 在 基督 耶稣里,藉 借著 福音,得以 同为后嗣, 同为一体, 同蒙 应许。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, ' 我作了 这福音的执事,是照 神 的恩赐,这恩赐 是照 他 运行 的大能 赐给 我的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, '我 本来比众 圣徒 中最小的还小,然而他还赐 我这 恩典,叫我把基督 那测不透的 丰富 传给 外邦人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, '又 使众 人都明白,这 历代 以来隐藏 在 创造 万物之 神 里的奥秘 是如何安排的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, ' 为要藉 借著 教会 使 天上 执政的、 掌权的,现在得知 神 百般的 智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, '这是照 神从万世 以前, 在 我们 主 基督 耶稣 里所定的旨意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, '我们因 信 耶稣,就在 他 里面放胆无惧, 笃信不疑地 来到 神面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, '所以,我求 你们不要 因 我 为 你们 所受的患难 丧胆,这 原是 你们的 荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, '因此,我在 父 面前屈 膝, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, '(天上 地上 的各(或译:全)家,都是从 他 得名。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, '求他按著 他 丰盛的 荣耀,藉 借著 他的 灵,叫 你们 心里 的力量 刚强起来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, '使基督 因 你们的信,住 在 你们 心里,叫你们的 爱心 有根 有基, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, ' 能以 和 众 圣徒 一同明白 基督的爱是何等 长 阔 高 深, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, '并 知道 这爱 是过于  人所能测度的,便叫 神 一切 所充满的,充满了你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, ' 神能 照著 运行 在 我们 心里的大力 充充足足地成就 一切, 超过 我们所求 所想的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, '但愿 他 在 教会中,并 在 基督 耶稣里,得著荣耀,直到 世世代代,永永远远。阿们!   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, '我 为 主 被囚的 劝 你们:既然蒙召,行事为人 就当与蒙召 的恩 相称。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, '凡事 谦虚、 温柔、忍耐,用 爱心 互相 宽容, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, '用 和平 彼此联络,竭力 保守 圣灵 所赐合而为一的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, '身体 只有一个, 圣灵 只有一个,正如 你们 蒙召 同有一个 指望。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, '一 主,一 信,一 洗, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, '一 神, 就是众人 的父, 超乎 众人之上, 贯乎 众人之中,也 住在 众人之内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, ' 我们 各人 蒙 恩,都是照 基督 所量给 各人的恩赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, '所以 经上说:他升 上 高天的时候,掳掠 了仇敌,将各样的恩赐 赏给 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, '( 既说升上,岂不 是 先降 在 地 下吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, ' 那降下的,就是 远升 诸 天 之上 要充满 万有的。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, ' 他 所赐的,有 使徒, 有先知, 有传福音的, 有牧师 和 教师, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, '为要 成全 圣徒, 各尽其职, 建立 基督 的身体, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, '直等到 我们众人 在真道 上同归 于  一, 认识 神 的儿子,得以 长大成人, 满有 基督 长成的身量, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, '使 我们不再 作小孩子,中了 人 的诡计 和欺骗的法术, 被 一切 异教 之风摇动,飘来飘去,就 随从 各样的异端; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, '惟 用 爱心 说诚实话,凡事 长进, 连于 元首 基督, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, '全 身 都靠 他 联络 得合式, 百节 各按各职,照著 各 体 的功用 彼此 相助,便叫 身体 渐渐增长, 在 爱 中建立 自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, '所以 我说,且 在 主 里确实地说,你们 行事 不要 再像 外邦人 存 虚妄 的 心 行事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, '他们 心地 昏昧,与 神 所赐的生命 隔绝了,都因 自己 无知, 心里 刚硬; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, ' 良心既然 丧尽,就放纵 私欲,贪 行 种种的 污秽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, '你们 学了 基督,却 不是 这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, '如果 你们听过 他的道, 领了他 的教, 学了他的 真理, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, '就要 脱去 你们 从前 行为 上的旧 人,这 旧人是因 私欲 的迷惑 渐渐变坏的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, '又 要将你们的 心志 改换一新, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, '并且 穿上 新 人;这新人 是照著 神 的形像造的,有 真理 的仁义 和 圣洁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, '所以,你们要弃绝 谎言,各人 与 邻舍 说 实话,因为 我们是 互相 为肢体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, '生气 却 不要 犯罪;不可 含 怒 到日 落, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, '也不可 给魔鬼 留 地步。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, '从前偷窃的,不要再 偷;总要 劳力,亲 手 做 正经事,就可 有余 馀 分给 那缺少的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, '污秽的 言语 一句不可 出 口,只要 随事说 造就 人 的好话,叫 听见的人 得 益处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, ' 不要叫 神 的圣 灵 担忧;你们原是 受了他的印记,等候 得赎 的日子来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, '一切 苦毒、 恼恨、 忿怒、 嚷闹、 毁谤,并 一切 的恶毒(或译:阴毒),都当从 你们 中间除掉; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, '并 要以 恩慈 相待,存怜悯的心,彼此 饶恕,正如 神 在基督里 饶恕了 你们一样。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, '所以,你们该 效法 神,好像 蒙慈爱的 儿女一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, '也 要凭 爱心 行事,正如 基督 爱 我们, 为 我们 舍了 自己,当作 馨香的 供物 和 祭物,献与 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, '至于  淫乱 并 一切 污秽,或 是贪婪,在你们 中间 连提都不可,方合 圣徒 的体统。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, ' 淫词、 妄语,和 戏笑的话 都不 相宜;总要 说感谢的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, '因为 你们确实地知道, 无论 是淫乱的, 是污秽的, 是有贪心的,在 基督 和 神 的国 里都是无分的。有贪心的, 就与拜偶像的一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, '不要被人 虚浮的 话 欺哄; 因 这些事, 神 的忿怒 必临到 那悖逆 之子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, '所以,你们不要 与他们 同伙 夥。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, ' 从前 你们是 暗昧的,但 如今 在 主 里面是光明的,行事为人 就当像 光明 的子女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, ' 光明 所结的果子 就是 一切 良善、 公义、 诚实。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, '总要察验 何 为 主 所喜悦的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, ' 那暗昧 无益的 事,不要 与人同行,倒要 责备行这事的人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, '因为 他们 暗中 所行的,就是 提起来 也是 可耻的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, ' 凡事 受了责备,就被 光 显明出来,因为 一切 能显明 的就是 光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, '所以 主说:你这睡著的 人当醒过来, 从 死 里复活! 基督 就要光照 你了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, ' 你们要谨慎 行事,不要 像 愚昧人,当 像 智慧人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, '要爱惜 光阴,因为 现今的世代 邪恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, ' 不要 作 糊涂人, 要明白 主 的旨意 如何。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, ' 不 要醉 酒, 酒能使人 放荡;乃要 被 圣灵 充满。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, '当用诗章、 颂词、 灵 歌 彼此 对说,口唱 心和 地赞美主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, ' 凡事 要奉 我们 主 耶稣 基督 的名 常常 感谢 父 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, '又当存 敬畏 基督的心,彼此 顺服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, '你们作妻子的,当顺服自己的 丈夫,如同 顺服主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, '因为 丈夫 是 妻子的 头, 如同 基督 是教会的 头;他 又是教会全体的 救主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, ' 教会 怎样 顺服 基督,妻子 也要怎样 凡事 顺服丈夫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, '你们作丈夫的,要爱 你们的妻子,正如 基督 爱 教会, 为 教会 舍己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, ' 要用水 藉 借著 道 把教会 洗净,成为圣洁, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, ' 可以献 给自己,作个荣耀的 教会,毫无 玷污、 皱纹 等类的病,乃 是 圣洁 没有瑕疵的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, '丈夫 也 当 照样 爱 妻子,如同 爱自己的 身子;爱 妻子 便是爱 自己了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, ' 从来 没有人 恨恶 自己的 身子,总是 保养 顾惜,正像 基督 待教会一样, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, '因 我们是 他 身上 的肢体(有古卷加:就是他的骨他的肉)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, '为 这个缘故,人 要离开  父 母, 与 妻子 连合, 二人 成为 一 体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, '这 是 极大的 奥秘,但 我 是指著 基督 和 教会 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, '然而,你们 各人 都当 爱 妻子,如同 爱自己一样。 妻子 也当 敬重 她的丈夫。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, '你们 作儿女的,要在主 里 听从 父母, 这 是 理所当然的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, '「要孝敬 父 母,使 你 得 福, 在 世 长寿。」这 是 第一 条带 应许 的诫命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, ' 你们作父亲的,不要 惹 儿女 的气,只要 照著 主 的教训和警戒 养育 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, '你们作仆人的,要 惧怕 战 兢,用 诚实的 心 听从 你们 肉身的 主人,好像 听从基督一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, '不要 只在 眼前事奉,像是 讨人喜欢的, 要像 基督 的仆人,从 心里 遵行 神 的旨意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, ' 甘心 事奉,好像 服事主, 不像 服事人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, '因为晓得 各人 所行的 善事,不论是 为奴的,是 自主的,都必按所行的 得 主的赏赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, ' 你们作主人的,待 仆人 也是一理,不要 威吓他们。因为知道, 他们和 你们 同有 一位主 在 天上; 他 并 不 偏待人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, '我还有末了的话:你们要靠著 主, 倚赖 他的 大能 大力 作刚强的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, '要穿戴 神 所赐的全副军装, 就 能 抵挡 魔鬼的 诡计。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, '因 我们 并不 是 与属 血气的争战 (原文是摔跤;下同),乃是 与 那些执政的、 掌权的、 管辖 这 幽暗世界的,以及 天空 属灵气的 恶魔争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, '所以,要拿起 神 所赐的全副军装,好 在 磨难的 日子 抵挡仇敌,并且 成就了 一切,还能站立得住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, '所以 要站稳了,用 真理 当作带子束 腰, 用 公义 当作护心镜遮胸, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, '又 用 平安的 福音 当作预备 走路的鞋穿在 脚上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, '此外,又拿著 信德 当作盾牌, 可以 灭尽 那恶者 一切的 火 箭; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, '并 戴上 救恩 的头盔, 拿著圣灵的 宝剑, 就是 神的 道; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, ' 靠著 圣灵,随时 多方 祷告祈求;并要 在 此 警醒 不倦, 为 众 圣徒 祈求, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, '也 为 我祈求,使 我 得著 口才,能以放胆 开  口 讲明 福音的 奥秘, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, '(我为 这福音的奥秘 作了带 锁链 的使者,)并使 我 照著 当 尽的本分放胆讲论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, '今有所亲爱、 忠心 事奉 主 的兄弟 推基古,他要把 我的事情,并我的景况 如何 全 告诉 你们, 叫 你们 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, '我特意 打发 他 到 你们那里去,好叫 你们知道 我们的 光景,又 叫他安慰 你们的 心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, '愿 平安、 仁爱、 信心 从 父 神 和 主 耶稣 基督 归与弟兄们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, '并愿 所有 诚心 爱 我们 主 耶稣 基督 的人都蒙 恩惠!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, '基督 耶稣 的仆人 保罗 和 提摩太 写信给凡 住 腓立比、在基督 耶稣 里 的众圣徒,和 诸位监督, 诸位执事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, '愿 恩惠、 平安 从 神 我们的 父 并 主 耶稣 基督 归与你们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, '我每 逢 想念 你们,就感谢 我的 神; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, '每 逢 为 你们 众人 祈求的时候,常 是 欢欢喜喜地 祈求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, '因为 从 头一 天 直到 如今,你们 是同心合意地 兴旺 福音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, '我深信 那 在你们 心里 动了 善 工的,必成全这工,直到 耶稣 基督 的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, '我 为 你们 众人 有这样 的意念,原 是 应当的;因 你们 常在 我 心 里,无论 我 是在捆锁 之中, 是辩明 证实 福音 的时候,你们 都 与我 一同得 恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, '我体会 基督 耶稣 的心肠,切切地 想念 你们 众人;这是 神 可以给我 作见证的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, ' 我所祷告的,就是 要你们的 爱心 在 知识 和 各样 见识 上多 而 又 多, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, ' 使你们 能分别是非(或译:喜爱那美好的事), 作 诚实 无过的人,直到 基督 的日子; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, '并靠著 耶稣 基督 结满了 仁义的 果子,叫荣耀 称赞 归与 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, ' 弟兄们,我愿 意 你们 知道,我 所 遭遇 的事更是 叫 福音 兴旺, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, '以致 我 受的捆锁 在御营 全 军和 其余 馀的 人中,已经显明 是 为 基督的缘故。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, '并且 那在主 里 的 弟兄 多半因我受的 捆锁 就笃信不疑,越发 放胆 传 神的道,无所惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, '有的 传 基督 是 出于  嫉妒 纷争, 也 有的 是出于  好意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, '这一等 是出于  爱心,知道 我是为 辩明 福音 设立的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, ' 那一等传 基督 是出于  结党,并不 诚实,意思 要加增 我 捆锁的 苦楚。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, '这有 何妨呢?或是 假意,或是 真心,无论 怎样,基督 究竟被传开 了。 为 此,我就欢喜,并且 还要 欢喜; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, '因为 我知道,这事 藉 借著 你们的 祈祷 和 耶稣 基督 之灵 的帮助,终必叫 我 得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, '照著 我 所切慕、 所盼望的, 没有一事 叫我羞愧。只要 凡事 放胆,无论 是生 是 死, 总叫 基督 在 我 身上 照常显大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, '因 我 活著 就是基督, 我死了 就有益处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, '但 我在 肉身 活著,若成就 我工夫 的果子, 我就不 知道 该挑选 什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, ' 我正在 两 难之间,情愿  离世 与 基督 同在,因为 这是好 得无比的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, '然而,我在 肉身活著,为 你们 更是要紧的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, ' 我既然这样 深信,就知道 仍要住在世间,且 与你们 众人 同住,使 你们在所信 的 道上又长进 又 喜乐, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, '叫 你们在 基督 耶稣 里的 欢乐,因 我 再 到 你们那里去,就越发加增。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, '只要 你们行事为人与 基督 的福音 相称,叫 我或 来 见 你们,或 不在你们那里,可以听见 你们的 景况, 知道你们同有 一个 心志,站立得稳,为所信 的福音 齐心努力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, ' 凡事不 怕 敌人 的惊吓,这 是 证明 他们 沉沦, 你们 得救 都是 出于  神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, '因为 你们 蒙恩,不 但 得以信服 基督, 并要 为 他 受苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, ' 你们 的 争战 ,就与你们在 我 身上从前所看见、 现在 所听见的一样。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, '所以,在 基督 里若有什么 劝勉,爱心 有什么 安慰,圣灵 有什么 交通,心中有什么 慈悲 怜悯, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, '你们就要 意念相同,爱心 相同,有一样的 心思,有一样的意念, 使我的 喜乐 可以满足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, ' 凡事不可 结党,不可 贪图虚浮的荣耀;只要 存心谦卑,各人看 别人 比自己 强。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, '各人 不要 单顾 自己的事, 也要 顾别人的 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, ' 你们当以 基督 耶稣 的心为 心: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, '他 本有 神 的形像,不 以自己与 神 同等 为强夺的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, '反倒 虚己,取了 奴仆 的形像,成为 人 的样式; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, '既有 人 的样子,就自己 卑微,存心 顺服,以至 于 死,且 死 在十字架上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, '所以, 神 将他 升为至高,又 赐给 他 那 超乎 万 名 之上的名, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, '叫一切 在天上的、 地上的,和 地底下的,因 耶稣 的名 无不屈 膝, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, ' 无不 口 称「耶稣 基督 为主」,使 荣耀 归与父 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, '这样看来,我 亲爱的弟兄,你们既 是常 顺服的,不 但 我 在你们那里,就是 我如今 不在你们那里,更是顺服的,就当恐惧 战 兢 做成 你们 得救的工夫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, '因为 你们立志行事 都是 神 在 你们 心里运行, 为要 成就 他的 美意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, '凡所行 的,都不要 发怨言, 起争论, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, ' 使 你们无可指摘, 诚实无伪,在这弯曲 悖谬 的世代作 神 无瑕疵 的儿女。你们 显在 这世代 中,好像 明光 照耀, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, '将生命 的道 表明出来,叫 我 在 基督 的日子 好 夸 我没有 空 跑,也没有 徒 劳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, ' 我以你们的 信心 为供献的 祭物,我若 被浇奠 在其上,也是喜乐,并且 与你们 众人 一同喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, ' 你们 也要 照样喜乐,并且 与我 一同喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, ' 我靠 主 耶稣 指望快 打发 提摩太 去见你们,叫 我 知道 你们的 事,心里就得著安慰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, '因为 我没有别人 与我同心, 实在 挂念 你们的 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, ' 别人都 求 自己的事,并不 求 耶稣 基督的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, '但 你们知道 提摩太 的明证; 他兴旺 福音,与 我 同劳,待我像儿子 待父亲 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, ' 所以,我 一看出 我的事要怎样了结,就盼望 立刻 打发 他去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, '但 我靠著 主 自信 我也 必 快 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, '然而,我想 必须 打发 以巴弗提 到 你们那里去。他是我的 兄弟, 与我一同做工, 一同当兵, 是你们 所差遣的,也是 供给 我 需用的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, ' 他 很想念 你们 众人,并且 极其难过,因为 你们听见 他病了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, ' 他实在 是病了,几乎 要死;然而 神 怜恤 他,不 但 怜恤他, 也 怜恤我,免得 我 忧 上加 忧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, '所以 我越发急速 打发 他去,叫 你们再 见 他,就可以喜乐,我 也可以 少些忧愁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, '故此,你们要 在 主 里 欢欢乐乐地 接待 他,而且 要尊重 这样的人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, '因 他为 做 基督的工夫,几乎 至 死,不顾 性命,要 补足 你们 供给 我 的不及之处。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, ' 弟兄们,我还有话说,你们要靠 主 喜乐。我把这话 再写给 你们,于 我 并不 为难, 于 你们 却是妥当。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, '应当防备 犬类,防备 作 恶的,防备 妄自行割的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, '因为 真受割礼的,乃是 我们 这以 神 的灵 敬拜、 在基督 耶稣 里 夸口、 不 靠著 肉体的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, '其实,我 也 可以 靠 肉体;若是 别人 想 他可以靠 肉体,我 更可以靠著了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, '我第八天 受割礼;我是 以色列 族、便雅悯 支派的人,是希伯来人 所生的 希伯来人。就律法 说,我是法利赛人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, '就热心 说,我是逼迫 教会的;就 律法 上 的义 说,我是 无可指摘的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, '只是 我先前以为 与我 有益的, 我现在因 基督 都当作 有损的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, '不但如此,我也 将万事 当作 有损的,因 我以认识 我 主 基督 耶稣 为至宝。我为 他 已经丢弃 万事, 看 作粪土,为要 得著 基督; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, '并且 得以 在他 里面,不是 有 自己 因 律法 而得的义,乃是 有 信 基督的义,就是 因 信 神 而来的 义, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, '使我认识 基督, 晓得他 复活 的大能,并且 晓得和他 一同 受苦,效法 他的 死, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, '或者 我也得以 从 死里 复活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, '这不是 说 我已经 得著了, 已经 完全了;我乃是 竭力追求,或者 可以得著 基督 耶稣 所以 得著我的(所以得著我的:或译所要我得的)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, '弟兄们,我 不是 以为 自己 已经得著了;我只有 一件事,就是忘记 背后, 努力 面前的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, '向著 标竿 直跑,要得 神 在基督 耶稣 里 从上面 召 我来得的奖赏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, '所以我们中间,凡是 完全人 总要存这样的 心; 若在什么事 上存别样的 心, 神 也 必以此 指示 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, '然而,我们到了 什么地步,就当照著什么 地步行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, '弟兄们,你们要 一同效法 我,也 当留意看 那些照 我们 榜样 行的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, '因为 有许多人 行事 是基督 十字架 的仇敌。 我屡次 告诉 你们,现在 又 流泪地 告诉你们: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, '他们的 结局 就是沉沦;他们的 神 就是自己的肚腹。 他们以 自己的 羞辱 为荣耀, 专以地上的事 为念。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, ' 我们 却是 天上 的国民,并且 等候 救主,就是主 耶稣 基督 从天上 降临。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, '他 要按著 那 能 叫万有 归服 自己的大能,将我们 这卑贱的 身体 改变形状, 和他自己 荣耀的 身体 相似。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, ' 我 所亲爱、 所想念的 弟兄们,你们就是我的 喜乐, 我的冠冕。 我亲爱的弟兄,你们应当靠 主 站立得稳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, '我劝 友阿蝶 和 循都基,要在主 里 同 心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, ' 我也 求 你 这真实 同负一轭的,帮助 这两个女人,因为她们 在福音 上 曾与我 一同劳苦; 还有 革利免,并 其余 馀 和我 一同做工的,他们的 名字 都在生命 册 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, '你们要靠 主 常常 喜乐。我再 说,你们要喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, '当叫众 人 知道 你们 谦让的心。主 已经近了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, '应当一无 挂虑,只要 凡事 藉 借著 祷告、 祈求,和 感谢,将你们 所要的 告诉 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, ' 神所赐、 出人意外的 平安 必在基督 耶稣 里 保守 你们的 心怀 意念。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, '弟兄们,我还有未尽的话:凡 是 真实的、 可敬的、 公义的、 清洁的、 可爱的、 有美名的,若有什么 德行, 若有什么 称赞,这些事 你们都要思念。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, ' 你们在 我 身上所学习的, 所领受的, 所听见的, 所看见的,这些事 你们都要去行, 赐平安的 神 就必 与你们 同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, ' 我靠 主 大大地 喜乐,因为 你们思念 我 的心如今 又发生;你们向来 就 思念我,只是 没得机会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, '我并不是 因 缺乏 说这话; 我无论在 什么景况 都 可以 知足,这是我 已经学会了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, ' 我知道 怎样处卑贱,也 知道 怎样处丰富;或 饱足,或 饥饿;或 有余 馀,或 缺乏,随事 随在,我都得了秘诀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, '我靠著 那 加给我 力量的,凡事 都能做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, '然而,你们和我 同 受患难 原是美 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, ' 腓立比人哪,你们 也 知道 我初 传福音 离了 马其顿 的时候, 论到 授 受的事,除了 你们 以外,并没有 别的教会 供给 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, ' 就是 我在 帖撒罗尼迦,你们也 一次 两次地 打发 人供给 我的 需用。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, ' 我并不 求 什么餽送,所求的 就是 你们的果子 渐渐增多,归在 你们的 帐上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, '但 我样样 都有,并且 有余 馀。我已经充足,因我从 以巴弗提 受了 你们的餽送,当作极美的 香气,为 神 所收纳、所喜悦的 祭物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, ' 我的 神 必照 他 荣耀的 丰富,在基督 耶稣 里,使你们 一切 所需用的 都充足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, ' 愿 荣耀 归给我们的 父 神,直到 永永远远。阿们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, '请问在基督 耶稣 里 的各位 圣徒 安。在我 这里的 众弟兄 都问你们 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, '众 圣徒 都问你们 安。 在凯撒 家里 的 人特特地问你们安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, '愿 主 耶稣 基督 的恩 常在 你们 心里!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, '奉 神 旨意,作基督 耶稣 使徒 的保罗 和 兄弟 提摩太 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, '写信给 歌罗西 的圣徒, 在 基督 里有忠心 的弟兄。愿 恩惠、 平安 从 神 我们的 父 归与你们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, '我们感谢 神、我们 主 耶稣 基督 的父,常常 为 你们 祷告; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, '因听见 你们 在 基督 耶稣 里的信心,并 向 众 圣徒 的爱心, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, '是为 那 给你们 存 在 天上 的盼望;这盼望就是 你们从前 在 福音 真理的 道上所听见的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, '这 福音传 到 你们那里,也 传到 普天之下,并且 结果,增长,如同 在你们 中间,自从 你们听见福音, 真 知道 神 恩惠 的 日子一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, '正如 你们从 我们 所亲爱、一同作仆人 的以巴弗 所学的。他 为我们(有古卷:你们)作了 基督 忠心 的执事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, ' 也 把你们 因 圣灵 所存的爱心 告诉了 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, '因此,我们 自从 听见 的 日子,也 就 为 你们 不 住 地祷告祈求, 愿  你们在 一切 属灵 的智慧 悟性上,满心 知道 神的 旨意; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, '好叫你们行事为人 对得起 主, 凡事 蒙他喜悦,在 一切 善 事 上结果子, 渐渐地多 知道 神; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, '照 他 荣耀的 权能,得以在 各样的 力 上加力,好叫 你们凡事 欢欢喜喜地 忍耐 宽容; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, '又感谢 父, 叫我们 能 与众圣徒 在光明 中 同得 基业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, '他 救了 我们 脱离 黑暗 的权势, 把我们迁 到 他 爱 子 的国里; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, '我们在 爱子 里得蒙 救赎,罪过 得以赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, '爱子 是 那不能看见之 神 的像,是首生的,在一切 被造的以先。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, '因为 万有 都是靠 他 造的,无论是天 上的, 地 上的;能看见的, 不能看见的;或是 有位的, 主治的, 执政的, 掌权的;一概 都是藉 借著 他 造的,又是 为 他造的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, ' 他 在 万有 之先;万有 也 靠 他 而立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, '他 也 是 教会 全体 之首。他 是 元始,是从 死里 首先复生的,使 他 可以在 凡事 上居 首位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, '因为 父喜欢 叫一切的 丰盛 在他 里面 居住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, '既然 藉 借著 他 在十字架 上所流的血 成就了和平,便藉 借著 他 叫万有─无论 是地 上的、 天 上的─都与 自己 和好了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, ' 你们 从前 与 神隔绝, 因著 恶 行,心里 与他为敌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, '但 如今 他 藉 借著 基督的肉 身 受 死,叫你们 与自己和好,都成了 圣洁, 没有瑕疵, 无可责备,把你们引到自己 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, '只要 你们在所信的 道上恒心,根基稳固, 坚定不移, 不至被引动失去(原文是离开 )福音 的盼望。这 福音就是你们所听过的, 也是传 与 普天 下万人听的(原文是凡 受造的), 我-保罗 也作了 这福音的执事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, '现在 我 为 你们 受苦,倒觉欢乐;并且 为基督的 身体,就是 为教会,要在 我 肉身上 补满 基督 患难 的缺欠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, ' 我 照 神 为 你们 所赐 我 的 职分 作了 教会的执事,要把 神 的道理 传得全备, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, '这 道理就是 历世 历代 所隐藏的 奥秘;但 如今 向他 的圣徒 显明了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, '神 愿 意 叫他们 知道,这 奥秘 在外邦人 中 有何等 丰盛的 荣耀, 就是 基督 在 你们 心里成了有荣耀的 盼望。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, '我们 传扬 他,是用 诸般的 智慧,劝戒 各 人, 教导 各 人,要把 各 人 在 基督 里完完全全地 引到 神面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, '我也 为此 劳苦,照著 他 在我 里面 运用 的大能 尽心竭力。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, ' 我愿 意 你们 晓得,我为 你们 和 老底嘉人,并 一切 没有 与我 亲自 见 面的人,是 何等地 尽心竭力; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, '要叫 他们的 心 得安慰,因 爱心 互相联络, 以致 丰丰足足 在悟性 中有充足的信心,使 他们真知 神 的奥秘,就是基督; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, '所积蓄的 一切 智慧 知识,都在他 里面 藏著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, '我说 这话,免得 有人 用 花言巧语 迷惑 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, ' 我身子 虽 与你们相离,心 却 与 你们 同在, 见 你们 循规蹈矩, 信 基督 的心也 坚固,我就欢喜了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, ' 你们既然 接受了 主 基督 耶稣,就当遵 他 而行, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, '在他 里面 生根 建造, 信心 坚固,正如 你们所领的教训,感谢 的心 也更增长了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, '你们要谨慎,恐怕 有人 用 他的理学 和 虚空的 妄言, 不 照著 基督,乃照 人间 的遗传 和 世上的 小学 就把你们 掳去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, '因为 神本性 一切的 丰盛 都有形有体地 居住 在基督 里面, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, ' 你们在他 里面 也得了 丰盛。他 是 各样 执政 掌权 者的元首。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, '你们在他 里面 也 受了 不是人手 所行的割礼,乃 是基督 使 你们脱去 肉体 情欲的割礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, '你们既 受洗 与 他 一同埋葬,也 就在此与他一同复活,都因 信 那 叫他 从 死里 复活 神 的功用。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, ' 你们 从前在 过犯 和 未受割礼的 肉体 中 死了, 神赦免了 你们(或译:我们)一切 过犯,便叫你们与 基督 一同活过来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, '又涂抹了 在律例上所写、攻击 我们、 有碍于  我们 的字据, 把它 撤去,钉 在十字架上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, '既将一切执政的、 掌权的 掳来,明显 给众人看,就仗著 十字架 夸胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, '所以,不拘在 饮 食上,或 节期、 月朔、 安息日 都不可 让人 论断 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, '这些 原是 后事 的影儿;那形体 却是 基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, '不可让人 因著 故意 谦虚 和 敬拜 天使,就夺去你们 的奖赏。这等人拘泥在所见过的(有古卷:这等人窥察 所没有见过的),随著 自己的 欲 心,无故地 自高自大, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, ' 不 持定 元首。全 身 既然靠著 他, 筋 节 得以 相助 联络,就因 神 大得长进。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, '你们若是 与 基督 同死,脱离了 世上 的小学,为什么 仍像 在 世俗中 活著、服从那「不可 拿、不可 尝、不可 摸」等类的规条呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'a ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, '这 都 是 照 人 所吩咐、 所教导的。说到这一切,正用 的时候就都 败坏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, '这些 规条使人徒有 智慧 之名,用 私意崇拜, 自表谦卑, 苦待 己身,其实 在 克制 肉体 的情欲上是 毫无 功效。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, '所以,你们若 真与基督 一同复活,就当求 在上面的事;那里 有基督 坐 在 神 的右边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, '你们要思念 上面的事,不要 思念地 上的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, '因为 你们已经死了, 你们 的生命 与 基督 一同藏在 神 里面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, '基督 是我们 的生命, 他显现 的时候,你们 也要 与 他 一同显现 在荣耀 里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, '所以,要治死 你们 在 地上 的肢体,就如淫乱、污秽、邪情、恶 欲,和 贪婪(贪婪 就与拜偶像 一样)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, '因 这些事, 神 的忿怒 必临 到 那悖逆 之子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, '当 你们 在 这些事 中活著 的时候,也 曾 这样 行过。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, '但 现在 你们 要弃绝 这一切的事,以及恼恨、忿怒、恶毒(或译:阴毒)、毁谤,并 口 中 污秽的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, '不要 彼此 说谎;因你们已经脱去 旧 人 和 旧人的 行为, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, ' 穿上了 新人。这新人 在 知识 上渐渐更新,正如 造 他 主的形像。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, '在此 并不 分 希腊人、 犹太人,受割礼的、 未受割礼的,化外人、西古提人,为奴的、自主的,惟有 基督 是包括一切,又 住在 各人之内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, '所以,你们既是 神 的选民,圣洁 蒙爱的人,就要存(原文是穿;下同)怜悯、恩慈、谦虚、温柔、忍耐 的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, '倘若 这人 与 那人 有 嫌隙,总要彼此 包容, 彼此 饶恕;主 怎样 饶恕了 你们,你们 也要 怎样饶恕人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, ' 在这一切 之外,要存著爱心,爱心 就是 联络 全德的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, '又要 叫基督 的平安 在 你们 心里 作主;你们也 为 此 蒙召,归为 一 体;且要 存 感谢的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, '当用 各样的 智慧,把基督 的道理 丰丰富富地 存 在心里(或译:当把基督的道理丰丰富富地存在心里,以各样的智慧),用诗章、颂词、灵 歌,彼此教导, 互相 劝戒, 心 被 恩 感,歌颂 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, '无论 做 什么,或 说话 或 行 事,都要 奉 主 耶稣 的名,藉 借著 他 感谢 父 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, '你们作妻子的,当顺服 自己的丈夫,这 在主 里面 是相宜的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, '你们作丈夫的,要爱 你们的妻子, 不可 苦 待 她们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, '你们作儿女的,要 凡事 听从 父母,因为 这 是 主 所喜悦的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, '你们作父亲的,不要 惹 儿女 的气,恐怕 他们失了志气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, '你们作仆人的,要 凡事 听从 你们 肉身的 主人,不要 只在 眼前事奉,像是 讨人喜欢的,总要 存心 诚实 敬畏 主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, '无论做 什么,都要从心里 做,像是 给主做的, 不是 给人做的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, '因 你们知道 从 主 那里必得著 基业 为赏赐;你们所事奉的 乃是主 基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, ' 那行不义的 必受 不义的报应; 主并 不 偏待人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, '你们作主人的,要公公平平地 待 仆人,因为 知道 你们 也 有 一位主 在 天上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, '你们要恒切 祷告,在 此 警醒 感恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, ' 也要 为 我们 祷告,求 神 给我们 开  传道 的门,能以讲 基督 的奥秘(我为 此 被捆锁), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, '叫 我 按著 所该 说的话 将这 奥秘发明出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, '你们要爱惜 光阴,用 智慧 与 外人交往。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, '你们 的言语 要常常 带著 和气,好像用盐 调和,就可知道 该 怎样 回答 各 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, '有我亲爱的 兄弟 推基古 要将我 一切的 事 都告诉 你们。 他是忠心的 执事,和 我一同 作主 的仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, '我特意 打发 他 到 你们那里去,好叫 你们知道 我们 的光景,又 叫他安慰 你们的 心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, '我又 打发一位亲爱 忠心的 兄弟 阿尼西谋同去;他 也是 你们 那里的人。他们要把这里 一切的事 都告诉 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, '与我 一同坐监的 亚里达古 问你们 安。巴拿巴 的表弟 马可 也问你们安。(说到 这马可,你们已经受了 吩咐;他若 到了 你们 那里,你们就接待 他。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, ' 耶数 又 称为 犹士都,也问你们安。 奉割礼的人中,只有 这 三个人是为 神 的国 与我一同做工的, 也是 叫我 心里得安慰的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, '有你们 那里的人,作基督 耶稣 仆人 的以巴弗 问你们 安。他在 祷告之间,常 为 你们 竭力地祈求, 愿 你们在 神 一切 的旨意上 得以完全,信心充足,能站立 得稳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, ' 他 为 你们 和 老底嘉 并 希拉坡里 的弟兄 多多地 劳苦,这是我可以给他作见证的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, '所亲爱的 医生 路加 和 底马 问你们 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, '请问 老底嘉 的弟兄 和 宁法,并 她 家里的 教会 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, ' 你们 念了 这书信,便交给 老底嘉 的教会,叫 他们也 念; 你们 也要 念 从老底嘉 来的书信。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, ' 要对亚基布 说:「务要谨慎, 尽 你从 主 所受的 职分。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, '我-保罗 亲笔问你们安。你们要记念 我的 捆锁。愿 恩惠 常与 你们同在!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, '保罗、 西拉、 提摩太 写信给 帖撒罗尼迦 在 父 神 和 主 耶稣 基督 里的教会。愿 恩惠、 平安 归与你们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, '我们为 你们 众人 常常 感谢 神,祷告的时候 提到你们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, '在 神─我们的 父 面前,不住地 记念 你们 因信心 所做的工夫,因 爱心 所受的劳苦,因 盼望 我们 主 耶稣 基督 所存的忍耐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, '被 神 所爱的 弟兄啊,我知道 你们 是蒙拣选的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, '因为 我们的 福音 传 到 你们那里,不 独 在乎 言语,也 在乎 权能 和 圣 灵,并 充足的 信心。正如 你们知道,我们 在 你们那里,为 你们 的缘故是怎样为人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, '并且 你们 在 大 难之中,蒙了圣 灵 所赐的 喜乐,领受 真道 就效法 我们,也 效法了主; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, '甚至 你们 作了 马其顿 和 亚该亚 所有 信 主之人的榜样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, '因为 主 的道 从 你们那里 已经传扬出来。你们 向 神 的信心 不但 在 马其顿 和 亚该亚,就是 在 各 处 也都传开 了,所以 不 用 我们 说 什么话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, '因为 他们自己 已经报明 我们 是 怎样 进 到 你们那里, 你们是怎样 离弃 偶像,归 向 神,要服事 那又 真 又活的 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, ' 等候 他 儿子 从 天降临,就是 他从 死 里复活的─那位 救 我们 脱离 将来 忿怒的 耶稣。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, '弟兄们, 你们自己 原晓得 我们 进 到 你们那里 并 不 是 徒然的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, ' 我们从前在 腓立比 被害 受辱,这是 你们知道的;然而还是靠 我们的 神 放开 胆量,在 大 争战 中把 神 的福音 传 给 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, ' 我们的 劝勉 不 是出于  错误,不是 出于  污秽,也不是 用 诡诈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, '但 神 既然 验中了我们,把福音 托 讬付我们,我们就照样讲,不是 要 讨人喜欢,乃是 要讨那察验 我们 心的 神喜欢。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, '因为 我们从来 没有 用过 谄媚 的话,这是 你们知道的;也没有 藏著 贪心,这是 神 可以作见证的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, '我们作 基督的 使徒,虽然可以 叫人尊重,却没有 向 你们 或 向 别人 求 荣耀; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, '只 在 你们 中间 存心温柔,如同 母亲 乳养 自己的 孩子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, '我们既是 这样爱 你们,不 但 愿 意将 神的 福音 给你们,连 自己的 性命 也愿 意给你们,因 你们是 我们 所疼爱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, '弟兄们, 你们记念 我们的 辛苦 劳碌,昼 夜 做工,传 神的 福音 给 你们, 免得 叫你们 一人 受累。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, '我们 向你们 信主的人,是何等 圣洁、 公义、 无可指摘,有你们 作见证,也有 神作见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, ' 你们也晓得,我们怎样 劝勉 你们, 安慰你们,嘱咐 你们 各 人,好像 父亲 待自己的 儿女一样, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, '要 叫 你们 行事 对得起 那召 你们 进 他 国、 得他荣耀的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, ' 为此,我们 也 不住地 感谢 神,因 你们听见 我们所传 神 的道 就领受了;不 以为 是人的 道,乃 以为是 神的 道。这道实在是 神的,并且 运行 在 你们 信主的人心中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, '弟兄们, 你们 曾 效法 犹太 中在 基督 耶稣里 神的 各教会;因为 你们 也 受了 本地人 的苦害, 像 他们 受了犹太人的苦害一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, '这犹太人 杀了 主 耶稣 和 先知,又 把我们赶出去。 他们不得 神的 喜悦,且 与众 人 为敌, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, '不许 我们 传道 给外邦人 使 外邦人得救, 常常 充满 自己的 罪恶。 神的忿怒 临 在 他们身上 已经到了 极处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, ' 弟兄们,我们 暂 时 与 你们 离别,是面目离别,心里 却不离别;我们极力地 想法子,很 愿 意 见 你们的 面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, '所以 我们有意 到 你们那里; 我─保罗 有一 两次要去,只是 撒但 阻挡了 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, '我们的 盼望 和 喜乐,并所夸的 冠冕 是什么呢? 岂不 是 我们 主 耶稣 来的时候、你们 在他面前站立得住吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, '因为 你们 就是 我们的 荣耀, 我们的喜乐。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, '我们既 不能再 忍,就愿 意 独自 等 在 雅典, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, ' 打发 我们的 兄弟 在 基督 福音上作 神执事的(作神执事的:有古卷是与神同工的)提摩太前去, 坚固 你们,并 在 你们 所信 的道上劝慰你们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, ' 免得有人 被 诸般 患难 摇动。因为 你们自己 知道,我们受患难原是 命定的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, ' 我们 在 你们那里的时候,预先告诉 你们, 我们必受 患难,以后 果然 应验了,你们也 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, '为 此,我 既不能再 忍,就打发人去,要 晓得 你们的 信心如何,恐怕 那诱惑人的 到底诱惑了 你们, 叫我们的 劳苦 归 于  徒然。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, '但 提摩太 刚才 从 你们那里 回来, 将你们 信心 和 爱心的 好消息报 给我们,又说 你们常常 记念 我们,切切地 想见 我们, 如同 我们 想见你们一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, '所以,弟兄们,我们 在 一切 困苦 患难之中,因著 你们的 信心 就得了安慰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, '你们 若 靠 主 站立得稳, 我们就活了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, '我们在 神 面前,因著 你们 甚是喜乐;为 这一切 喜乐, 可用何等的 感谢 为 你们 报答 神呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, '我们昼 夜 切切地 祈求,要 见 你们的 面, 补满 你们 信心的 不足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, '愿  神─我们的 父 和 我们的 主 耶稣 一直引领 我们 到 你们那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, ' 又愿 主 叫你们 彼此 相爱的心,并 爱众人 的心都能增长, 充足, 如同 我们 爱 你们一样, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, '好使你们当 我们 主 耶稣 同 他 众 圣徒 来的时候, 在我们 父 神 面前, 心 里坚固,成为 圣洁,无可责备。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, '弟兄们, 我还有话说:我们靠著 主 耶稣 求 你们, 劝你们, 你们 既然 受了 我们的教训,知道该 怎样 行 可以讨 神的喜悦, 就 要照 你们现在所行的 更加勉励。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, ' 你们原晓得,我们凭 主 耶稣 传给 你们 什么 命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, ' 神 的旨意 就是要你们 成为圣洁, 远避 淫行; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, '要你们 各人 晓得 怎样用 圣洁、 尊贵 守著 自己的身体, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, '不 放纵私欲 的邪情, 像 那 不 认识 神 的外邦人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, '不 要一个人在 这事 上越分, 欺负 他的 弟兄;因为 这一类的事,主 必报应,正 如 我预先 对你们说过、又 切切嘱咐你们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, ' 神 召 我们,本不 是要我们沾染 污秽,乃是 要我们成为 圣洁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, '所以,那弃绝的,不 是弃绝 人,乃是 弃绝那赐 圣 灵 给 你们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, ' 论到 弟兄们相爱,不 用 人写信 给你们;因为 你们 自己 蒙了 神的教训,叫 你们彼此 相爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, ' 你们向 马其顿 全 地的众 弟兄 固然 是这样 行,但 我劝 弟兄们 要更加 勉励。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, '又 要立志 作安静人, 办 自己的事, 亲 手 做工,正如 我们从前所吩咐 你们的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, '叫 你们可以向 外人行 事端正,自己也 就没 有 什么 缺乏了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, '论到 睡了的人, 我们不 愿 意 弟兄们 不知道,恐怕 你们 忧伤, 像 那些 没 有 指望 的人一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, ' 我们若 信 耶稣 死 而 复活了,那 已经 在耶稣里睡了的人, 神 也必将他们 与 耶稣 一同 带来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, ' 我们现在照 主 的话 告诉 你们 一件事: 我们 这 活著 还存留 到 主 降临的人,断不能 在那已经睡了 的人 之先。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, '因为 主 必亲自 从 天 降临,有 呼叫 的声音和 天使长 的声音,又 有 神 的号吹响;那 在基督 里 死了 的人必先 复活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, '以后 我们 这 活著 还存留的 人必和 他们 一同 被提到 云 里,在 空中 与 主 相遇。 这样,我们就要和 主 永远 同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, '所以,你们当用 这些 话 彼此 劝慰。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, ' 弟兄们,论到 时候、 日期,不 用 写 信给你们, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, '因为 你们 自己明明 晓得, 主 的日子 来到, 好像 夜间 的 贼一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, '人正说「平安 稳妥」的时候, 灾祸 忽然 临到 他们,如同 产难 临到 怀 胎的妇人一样, 他们绝不 能逃脱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, '弟兄们,你们 却 不 在 黑暗 里,叫 那日子 临到 你们 像 贼一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, ' 你们 都 是 光明 之子, 都是白昼 之子。我们不 是 属黑夜的,也不 是属幽暗的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, '所以,我们不 要睡觉 像 别人一样,总要 警醒 谨守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, '因为 睡了 的人是在夜间 睡, 醉了 的人是在夜间 醉。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, '但我们 既然 属乎 白昼,就应当谨守,把信 和 爱 当作护心镜遮胸, 把得救 的盼望 当作头盔 戴上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, '因为 神 不 是预定 我们 受 刑,乃是 预定 我们藉 借著 我们 主 耶稣 基督 得 救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, '他 替 我们 死,叫 我们无论 醒著, 睡著,都与 他 同 活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, '所以,你们该彼此 劝慰, 互相 建立,正 如 你们素常所行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, ' 弟兄们,我们劝 你们 敬重 那 在你们 中间 劳苦的人,就 是在主 里 面治理 你们、 劝戒 你们的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, '又 因 他们 所做的工,用 爱心 格外 尊重 他们。你们 也要彼此 和睦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, ' 我们又劝 弟兄们,要警戒 不守规矩的人,勉励 灰心的人,扶助 软弱的人,也要向 众人 忍耐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, '你们要谨慎,无论是谁 都不可 以恶 报 恶;或 是 彼此相待,或 是待 众人,常 要 追求 良善。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, '要常常 喜乐, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, '不住地 祷告, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, ' 凡事 谢恩;因为 这是 神 在 基督 耶稣里 向 你们 所定的旨意。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, '不 要消灭 圣灵的感动; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, '不 要藐视 先知的讲论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, '但要 凡事 察验; 善美的 要持守, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, '各样的 恶事 要禁戒不做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, ' 愿 赐平安的 神 亲自 使你们 全然 成圣!又 愿 你们的 灵 与 魂 与 身子 得蒙保守,在 我们 主 耶稣 基督 降临的时候,完全无可指摘! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, '那召 你们 的本是信实的,他 必 成就这事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, '请弟兄们 为 我们 祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, '与众 弟兄 亲嘴 问安, 务要圣洁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, '我指著主 嘱咐 你们,要把这信 念 给众 弟兄听。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, '愿 我 主 耶稣 基督 的恩 常与 你们同在!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, '保罗、 西拉、 提摩太 写信给帖撒罗尼迦、在 神─我们的 父 与 主 耶稣 基督 里的教会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, '愿 恩惠、 平安 从 父 神 和 主 耶稣 基督 归与你们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, '弟兄们,我们该 为 你们 常常 感谢 神,这本 是 合宜的;因 你们的 信心 格外增长,并且 你们 众人 彼 此 相 爱 的心也都充足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, '甚至 我们 在 神的 各教会 里为 你们 夸口,都因 你们 在 所受的 一切 逼迫 患难中,仍旧 存忍耐 和 信心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, '这正是 神 公义 判断 的明证,叫 你们 可算配得 神 的国;你们就是 为 这国 受苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, ' 神 既是 公义的,就必将患难 报应 那加患难 给你们的人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, '也 必使你们 这受患难 的人与我们 同得 平安。那时,主 耶稣 同 他 有能力 的天使 从 天上 在 火 焰 中显现, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, '要报应 那不 认识 神 和 那不 听从 我 主 耶稣 福音的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, '他们 要受刑罚,就是永远 沉沦,离开  主 的面 和 他 权能 的荣光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, '这正是 主降临、要在 他 圣徒 的身上得荣耀、又 在 一切 信 的人身上显为希奇 的 那 日子。 我们 对 你们 作的见证,你们也信了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, '因此,我们 常 为 你们 祷告,愿  我们的 神 看你们 配得 过所蒙的召,又 用 大能 成就 你们一切 所羡慕 的良善 和 一切因信心 所做的工夫, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, '叫 我们 主 耶稣 的名 在 你们 身上得荣耀,你们 也 在 他身上得荣耀,都照著 我们的 神 并 主 耶稣 基督 的恩。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, '弟兄们,论到 我们 主 耶稣 基督 降临 和 我们 到 他 那里聚集, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, ' 我劝 你们:无论 有 灵、 有 言语、 有 冒 我 名的书信, 说 主 的日子现在(现在:或译就)到了,不 要轻易 动 心,也不要 惊慌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, '人 不 拘用 什么 法子,你们 总不要被他诱惑;因为 那日子以前, 必有离道反教的事,并 有那大罪 人,就是沉沦 之子,显露 出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, '他 是抵挡主, 高抬自己,超过 一切 称为 神 的和 一切受人敬拜的,甚至 坐在 神 的殿 里, 自 称 是 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, ' 我还 在 你们那里的时候,曾把这些事 告诉 你们,你们不 记得吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, ' 现在 你们也知道,那拦阻 他的是什么,是叫他 到了 的时候 才可以显露。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, '因为 那不法 的隐意 已经 发动,只是 现在 有一个拦阻的,等到 那拦阻的 被除 去, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, ' 那时 这不法的 人必显露出来。主 耶稣 要用口 中的气 灭绝 他, 用 降临 的荣光 废掉他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, '这不法的人 来,是 照 撒但 的运动,行 各样的 异能、 神迹,和 一切虚假 的奇事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, '并且 在 那沉沦 的人身上行各样 出于 不义 的诡诈;因 他们不 领受 爱 真理的心,使 他们 得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, '故 此, 神 就 给 他们 一个生发 错误的心,叫 他们 信从 虚谎, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, '使 一切 不 信 真理、倒 喜爱 不义 的人 都被定罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, '主 所 爱的 弟兄们哪,我们 本 该 常 为 你们 感谢 神;因为 他 从起初 拣选了 你们,叫你们因 信 真道,又被 圣灵感动,成为圣洁,能以 得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, ' 神藉 借 我们 所 传的福音 召 你们到这地步,好 得著 我们 主 耶稣 基督 的荣光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, '所以,弟兄们,你们要站立得稳,凡所 领受的教训,不拘 是我们 口 传的,是 信上写的,都要 坚守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, '但愿  我们 主 耶稣 基督 和 那 爱 我们、 开  恩 将永远 的安慰 并 美好的 盼望 赐给 我们的 父 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, '安慰 你们的 心,并且 在 一切 善 行 善言 上坚固你们。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, '弟兄们,我还有话说:请你们为 我们 祷告,好叫 主 的道理 快快行开 , 得著荣耀,正 如 在 你们中间一样, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, '也 叫 我们脱离 无理 之恶 人的手;因为 人 不 都是有信心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, '但 主 是 信实的, 要坚固 你们, 保护 你们脱离 那恶者(或译:脱离凶恶)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, ' 我们靠 主 深信, 你们 现在是遵行 我们所 吩咐的,后来 也必 要遵行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, ' 愿 主 引导 你们 的心,叫 你们爱 神,并 学基督 的忍耐! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, ' 弟兄们,我们 奉 主 耶稣 基督 的名 吩咐 你们,凡 有弟兄 不按规矩 而行, 不 遵守 从 我们 所 受的 教训,就当远离他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, '你们自己 原 知道 应当 怎样 效法 我们。因为 我们在你们 中间,未尝不 按规矩而行, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, '也未 尝白 吃 人 的饭,倒是 辛苦 劳碌, 昼 夜 做 工,免 得 叫你们 一人 受累。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, '这并不 是因 我们没 有 权柄,乃是 要 给你们 作 榜样,叫 你们效法 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, ' 我们在 你们 那里的时候,曾 吩咐 你们说, 若 有人 不 肯 做工,就不 可吃饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, '因 我们听说,在你们 中间 有人 不按规矩 而行,什么工 都不做,反倒 专管闲 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, ' 我们靠 主 耶稣 基督 吩咐、 劝戒 这样的人, 要 安静 做工,吃 自己的 饭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, '弟兄们, 你们 行善 不 可丧志。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, ' 若 有人 不 听从 我们 这信 上 的话,要记下 他,不 和他 交往,叫 他自觉羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, '但不 要 以 他为 仇人,要 劝 他如 弟兄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, '愿  赐平安 的主 随 时 随 事 亲自 给 你们 平安!愿 主 常与 你们 众人同在! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, '我─保罗 亲 笔 问你们安。凡 我的信 都以此为 记,我的笔迹 就是这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, '愿 我们 主 耶稣 基督 的恩 常与 你们 众人同在!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, '奉 我们 救主 神 和 我们的 盼望 基督 耶稣 之命,作基督 耶稣 使徒 的保罗, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, '写信给那因 信 主作我真 儿子 的提摩太。愿 恩惠、怜悯、平安 从 父 神 和 我们 主 基督 耶稣归与你! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, '我往 马其顿 去 的时候,曾劝 你 仍住 在 以弗所,好 嘱咐 那几个人 不可 传异教, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, '也不可 听从 荒渺无凭的话语 和 无穷的 家谱;这等事 只生 辩论,并不发明 神 在信 上 所立的章程。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, '但 命令 的总归 就是 爱;这爱是从 清洁的 心 和 无亏的 良心, 无伪的 信心生出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, '有人 偏离 这些,反去 讲虚浮的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, '想要 作 教法师,却不 明白 自己所讲说 的 所论定 的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, ' 我们知道 律法 原是好的,只要 人 用 得 合宜; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, ' 因为 律法 不是 为义人 设立的,乃是 为不法 和 不服的,不虔诚 和 犯罪的,不圣洁 和 恋世俗的,弑父 母 和杀人的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, '行淫 和亲男色的,抢人口 和说谎话的,并 起假誓的,或是 为别样 敌 正 道的事设立的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, '这是照著 可称颂之 神 交托 讬 我 荣耀 福音说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, '我感谢 那给我力量 的我们 主 基督 耶稣,因 他 以 我 有忠心,派 我 服事他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, '我 从前 是亵渎 神的, 逼迫人的, 侮慢人的;然而 我还蒙了怜悯,因 我是 不信 不明白 的时候而做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, '并且 我 主 的恩 是格外丰盛, 使我在基督 耶稣 里 有 信心 和 爱心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, '「基督 耶稣 降 世,为要拯救 罪人。」这话 是可信的, 是 十分 可佩服的。在罪人中 我 是 个罪魁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, '然而,我蒙了怜悯,是因 耶稣 基督 要在 我 这罪魁 身上显明 他一切的 忍耐,给后来 信 他 得 永 生 的人作 榜样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, '但愿  尊贵、 荣耀 归与那不能朽坏、不能看见、永世 的君王、独一的 神,直到 永永远远。阿们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, '我儿 提摩太啊,我照 从前指著 你 的预言,将这 命令 交托 讬 你,叫 你因 此 可以打 那美好的 仗。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, '常存 信心 和 无亏的 良心。 有人 丢弃良心,就在真道 上 如同船破坏了一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, '其中 有 许米乃 和 亚历山大;我已经把他们 交给 撒但,使 他们受责罚 就不再 谤渎了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, '我劝 你,第一 要 为 万 人 恳求、祷告、代求、祝谢; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, '为 君王 和 一切 在位的,也该如此,使 我们可以 敬虔、 端正、平安 无事地 度日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, '这 是好的,在 神 我们 救主 面前 可蒙悦纳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, '他 愿 意 万 人 得救, 明白 真道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, '因为 只有一位 神,在 神 和 人中间,只有一位 中保,乃是降世为人 的基督 耶稣; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, '他 舍 自己 作 万人 的赎价,到了 时候,这事必证明出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, '我 为 此 奉派 作传道的, 作使徒,作外邦人 的师傅,教导他们 相信, 学习真道。我说 的是真话,并不是 谎言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, ' 我愿  男人 无 忿怒,无争论(或译:疑惑),举起 圣洁的 手, 随 处 祷告; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, ' 又 愿 女人 廉耻、 自守,以 正派 衣裳 为妆饰,不 以 编发、 黄金、 珍珠,和 贵价的 衣裳为妆饰, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, '只要 有 善 行,这 才与自称是敬 神的 女人 相宜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, '女人 要 沉静 学道, 一味地 顺服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, ' 我不 许 女人 讲道,也不许 她辖管 男人,只要 沉静。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, '因为 先 造 的是亚当,后 造的是夏娃, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, '且 不是 亚当 被引诱,乃是 女人 被引诱,陷 在罪 里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, '然而,女人若 常存 信心、 爱心,又 圣洁 自守,就必在生产 上 得救。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, '「人 若 想要 得监督的职分,就是羡慕 善 工。」这话 是可信的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, '作监督的, 必须 无可指责,只作一个 妇人 的丈夫,有节制,自守,端正,乐意接待远人,善于 教导; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, '不 因酒滋事,不 打人,只要 温和,不争竞,不贪财; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, '好好 管理 自己的 家,使 儿女 凡事 端庄 顺服(或译:端端庄庄地使儿女顺服)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, ' 人 若 不 知道 管理 自己的 家,焉能 照管 神的 教会呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, '初入教的 不可作监督,恐怕 他自高自大,就落 在魔鬼 所受的刑罚 里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, '监督也 必须 在教外有 好 名声,恐怕 被人毁谤, 落 在魔鬼 的网罗 里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, '作执事的,也是如此:必须端庄,不 一口两舌,不 好 喝酒,不 贪不义之财; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, '要存 清洁的 良心,固守 真道 的奥秘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, '这等人 也要 先 受试验,若 没有可责之处,然后 叫他们作执事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, '女执事(原文是女人)也是如此:必须端庄,不 说谗言,有节制, 凡事 忠心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, '执事 只要作 一个 妇人 的丈夫,好好 管理 儿女 和 自己的 家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, '因为 善 作执事的,自己 就得到 美好的 地步,并且 在 基督 耶稣 里 的真道 上 大 有胆量。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, '我指望 快 到 你 那里去,所以先将这些事 写给 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, '倘 若 我耽延日久, 你也可以知道在 神的 家 中 当 怎样 行。这 家就是 永生 神 的教会,真理 的柱石 和 根基。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, ' 大哉, 敬虔 的奥秘,无人不以为然!就是 神在 肉身 显现,被 圣灵 称义(或译:在灵性称义),被天使 看见,被传 于  外邦,被 世人 信服,被接 在荣耀 里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, ' 圣灵 明 说, 在 后来的 时候,必有人 离弃 真道,听从 那引诱人的 邪灵 和 鬼魔 的道理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, '这是因为 说谎 之人的假冒;这等人 的良心 如同被热铁烙惯了一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, '他们禁止 嫁娶,又禁戒食物(或译:又叫人戒荤),就是 神 所造、叫 那信 而 明白 真道 的人感谢 著 领受的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, ' 凡 神 所造的物 都是好的,若感谢 著 领受,就 没有一样 可弃的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, ' 都因 神的 道 和 人的祈求 成为圣洁了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, '你若将这些事 提醒 弟兄们,便是 基督 耶稣 的好 执事,在真道 的话语 和 你向来所服从 的 善 道 上得了教育。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, '只是 要弃绝 那世俗的 言语和 老妇 荒渺的话, 在敬虔 上 操练 自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, '「操练 身体,益处 还少;惟独 敬虔, 凡事 都有 益处,因有 今 生 和 来生 的应许。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, '这话 是可信的, 是十分 可佩服的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, ' 我们劳苦 努力,正是为 此,因 我们的指望 在乎 永生的 神;他 是 万 人 的救主,更是 信徒的救主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, '这些事,你要吩咐人,也要 教导人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, '不可叫人 小看 你 年轻,总要 在 言语、 行为、 爱心、 信心、 清洁上,都作 信徒 的榜样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, '你要以宣读、劝勉、教导 为念,直等到 我来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, '你 不要 轻忽 所得的 恩赐,就是 从前藉 借著 预言、在众长老 按 手 的时候 赐给 你的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, '这些事 你要殷勤去做,并要在 此 专心,使 众人 看出 你的 长进来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, '你要谨慎 自己 和 自己的教训,要在这些事上 恒心;因为 这样 行,又能 救 自己,又能 救听 你的人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, '不可 严责 老年人,只要 劝 他如同 父亲;劝少年人 如同 弟兄; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, '劝老年妇女 如同 母亲;劝少年妇女 如同 姊妹; 总要 清清洁洁的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, '要尊敬 那真为 寡妇的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, ' 若 寡妇 有 儿女,或有 孙子孙女,便叫他们先 在自己 家中 学著 行孝, 报答 亲恩,因为 这在 神 面前 是 可悦纳的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, ' 那 独居无靠、真为 寡妇的,是仰赖 神, 昼 夜 不住地 祈求 祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, '但 那好宴乐 的寡妇正活著 的时候也是死的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, ' 这些事 你要嘱咐她们,叫 她们 无可指责。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, ' 人 若 不 看顾 亲属,就是背了 真道, 比不信的人 还不好,不看顾自己家里的人, 更是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, ' 寡妇 记在册子上,必须年纪到 六十 岁,从来只作 一个 丈夫 的妻子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, '又有 行 善 的名声,就如 养育儿女, 接待远人, 洗 圣徒的 脚, 救济 遭难的人, 竭力行 各样 善 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, '至于  年轻的 寡妇,就可以辞她;因为 她们的情欲发动,违背基督 的时候 就想要 嫁人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, '她们被 定罪,是因 废弃了 当初 所许的愿 ; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, '并且 她们又习惯 懒惰,挨家 闲 游; 不 但 是懒惰,又 说长道短, 好管闲 事,说 些 不 当说的话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, '所以 我愿 意 年轻的 寡妇嫁人,生养儿女,治理家务,不 给 敌人 辱骂 的把柄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, '因为 已经 有 转去 随从 撒但的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, ' 信主的妇女,若家中有 寡妇,自己就当救济 她们, 不可 累著 教会,好使 教会能救济 那真 无倚靠的寡妇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, '那善于  管理 教会的长老,当以为配受 加倍的 敬奉;那劳苦 传道 教导人的,更当如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, '因为 经上 说:「牛 在场上踹谷的时候,不可 笼住牠的嘴」;又说:「工人 得 工价 是应当的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, '控告 长老 的呈子,非有 两 三 个见证 就不要 收。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, '犯罪的人,当在众人 面前 责备他,叫 其余 馀的 人也 可以 惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, '我在 神 和 基督 耶稣 并 蒙拣选的 天使 面前 嘱咐你: 要遵守 这些话,不可 存成见,行事 也不可 有 偏心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, '给人行按 手的礼,不可 急促;不要 在别人的 罪 上有分,要保守 自己 清洁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, '因 你胃口不清, 屡次 患病,再不要照常 喝水, 可以稍微 用 点酒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, '有些 人 的罪 是 明显的,如同先 到 审判案前; 有些人 的罪是随后跟了去的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, '这样,善 行 也 有明显的, 那 不明显的 也不 能 隐藏。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, '凡 在 轭 下 作仆人的,当以 自己 主人 配受 十分的 恭敬,免得 神 的名 和 道理 被人亵渎。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, ' 仆人有 信道的 主人,不可 因为 与他是 弟兄 就轻看他;更要 加意 服事他;因为 得 服事之益处的,是 信道 蒙爱的。你要以此 教训人, 劝勉人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, '若 有人 传异教, 不 服从 我们 主 耶稣 基督 纯正的 话 与 那合乎 敬虔 的道理, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, '他是自高自大,一无 所知, 专好 问难, 争辩言词,从 此 就生出 嫉妒、纷争、毁谤、妄 疑, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, '并那坏了 心术、 失丧 真理 之人 的争竞。他们以 敬虔 为 得利的门路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, '然而,敬虔 加上 知足的心 便是 大 利了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, '因为 我们没有 带 什么到 世上来, 也不 能 带什么 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, '只要 有 衣 有食,就当 知足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, '但 那些想要 发财的人,就陷 在 迷惑、 落在网罗 和 许多 无知 有害的 私欲里,叫 人 沉 在败坏 和 灭亡 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, ' 贪财 是 万 恶 之根。 有人 贪恋钱财,就被引诱 离了 真道, 用许多 愁苦 把自己 刺透了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, '但 你这属 神 的人 要逃避 这些事, 追求 公义、敬虔、信心、爱心、忍耐、温柔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, '你要为真道 打 那美好的 仗,持定 永 生。你为 此 被召,也 在许多 见证人 面前,已经作了 那美好的 见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, '我在 叫万物 生活的 神 面前,并 在向 本丢•彼拉多 作过 那美好 见证 的 基督 耶稣 面前嘱咐 你: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, ' 要守 这命令,毫不玷污,无可指责,直到 我们的 主 耶稣 基督 显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, ' 到了 日期,那可称颂、 独有 权能的 万王 之王、 万主 之主, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, '就是那 独一 不死、住在 人不 能靠近的 光里, 是人 未曾 看见、也是不能 看见的,要将他显明出来。但愿 尊贵 和 永远的 权能 都归给他。阿们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, '你要嘱咐 那些 今 世 富足的人,不要 自高,也不要 倚靠 无定的 钱财;只要 倚靠 那 厚 赐 百物 给 我们 享受的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, '又要嘱咐他们行善,在好 事 上 富足, 甘心施舍,乐意供给(或译:体贴)人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, '为自己 积成 美好的 根基,预备 将来,叫 他们持定 那真正的 生命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, '提摩太 啊,你要保守 所托 讬付你的,躲避 世俗的 虚谈 和 那敌真道、似是而非 的学问。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, '已经有人 自称 有这学问,就偏离了 真道。愿 恩惠 常与你们 同在!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, '奉 神 旨意,照著 在基督 耶稣 里 生命 的应许,作基督 耶稣 使徒 的保罗 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, '写信给我亲爱的 儿子 提摩太。愿 恩惠、怜悯、平安 从 父 神 和 我们 主 基督 耶稣归与你! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, '我感谢 神,就是 我接续 祖先 用 清洁的 良心 所事奉的 神。 祈祷的时候,不住的 想念 你, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, '记念 你的 眼泪,昼夜切切地想要 见 你,好叫 我满 心快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, '想到 你 心里 无伪 之信,这 信是先 在 你 外祖母 罗以 和 你 母亲 友妮基 心里的, 我深信 也 在你 的心里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, '为 此 我提醒 你,使你将 神 藉 借 我 按 手 所给 你 的恩赐 再如火挑旺起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, '因为 神 赐给 我们,不是 胆怯的 心,乃是 刚强、 仁爱、 谨守的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, ' 你不要 以给我们的 主 作见证 为耻,也不要 以我 这 为主被囚的为耻;总要 按 神 的能力,与我为福音 同受苦难。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, '神 救了 我们, 以圣 召 召我们,不是 按 我们的 行为,乃是 按 他的 旨意 和 恩典;这 恩典是万古 之先,在基督 耶稣 里 赐给 我们的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, '但 如今 藉 借著 我们 救主 基督 耶稣 的显现 才表明出来了。他 已经把死 废去, 藉 借著 福音,将不能坏的 生命 彰显出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, '我 为 这 福音奉派 作传道的, 作使徒, 作师傅。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, '为 这 缘故,我也 受这些 苦难。然而 我不 以为耻;因为 知道 我所信 的是谁,也 深信 他 能 保全 我 所交付他的(或译:他所交托 讬我的),直到 那 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, '你从 我 听 的那 纯正 话语 的规模,要用 在基督 耶稣 里 的 信心 和 爱心,常常守著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, '从前所交托 讬 你的善道,你要靠著 那 住 在我们 里面 的圣 灵 牢牢地守著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, ' 凡 在 亚细亚 的人都离弃 我,这是 你知道的,其中 有 腓吉路 和 黑摩其尼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, '愿 主 怜悯 阿尼色弗 一家的人;因 他屡次 使我 畅快, 不 以我的 锁链 为耻, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, '反倒 在 罗马的时候,殷勤地 找 我,并且 找著了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, '愿 主 使 他 在 那 日 得 主 的 怜悯。 他在 以弗所 怎样多多地 服事我,是你 明明 知道的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, ' 我 儿啊,你 要在 基督 耶稣 的恩典 上 刚强起来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, ' 你在许多 见证人 面前 听见 我 所 教训的, 也要 交托 讬 那忠心 能 教导 别人 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, '你要和我同受苦难,好像 基督 耶稣 的精 兵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, '凡在军中当兵的,不 将世 务 缠身,好叫 那招他当兵的 人喜悦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, ' 人 若 在场上比武,非 按规矩,就不能 得冠冕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, '劳力的 农夫 理当 先 得 粮食。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, '我所说 的话,你要思想,因为 凡事 主 必给 你 聪明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, '你要记念 耶稣 基督 乃是大卫 的 后裔,他从死 里 复活,正合乎 我 所传的福音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, '我为 这 福音受苦难,甚至被 捆绑,像犯人 一样。然而 神 的道 却不被 捆绑。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, '所以,我为 选民 凡事 忍耐,叫 他们 也 可以得著 那 在基督 耶稣 里 的救恩 和 永远的 荣耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, '有可信的 话说: 我们若 与基督同死,也 必与他同活; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, '我们若 能忍耐,也 必和他一同作王。我们若 不认他,他也 必不认 我们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, '我们纵然 失信,他 仍是 可信的,因为 他不 能 背乎 自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, '你要使众人回想 这些事,在主 面前 嘱咐他们:不可 为言语争辩;这是 没有 益处的,只能 败坏 听见的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, '你 当竭力在 神 面前 得蒙喜悦,作无愧的 工人,按著正意分解 真理的 道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, '但 要远避 世俗 的虚谈,因为 这等人必进 到 更 不敬虔的地步。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, ' 他们的 话 如同 毒疮,越烂越大;其中 有 许米乃 和 腓理徒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, '他们 偏离了 真道,说 复活 的事已 过,就 败坏 好些人 的信心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, '然而, 神 坚固的 根基 立住了;上面有 这 印记说:「主 认识 谁是 他的人」;又说:「凡 称呼 主 名 的人总要离开  不义。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, ' 在 大 户人家,不 但 有 金 器 银器,也有 木 器 瓦器; 有 作为 贵重的, 有 作为 卑贱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, '人 若 自 洁,脱离 卑贱的事,就必作 贵重的 器皿,成为圣洁,合乎 主用,预备 行 各样的 善 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, '你 要逃避 少年的 私欲, 同 那 清 心 祷告 主 的人追求 公义、信德、仁爱、和平。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, '惟有 那愚拙 无学问 的辩论,总要弃绝,因为知道 这等事 是起 争竞的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, '然而 主 的仆人 不 可 争竞,只 要 温温和和地 待 众人,善于 教导,存心忍耐, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, '用 温柔 劝戒 那抵挡的人;或者 神 给 他们 悔改的心,可以 明白 真道, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, '叫 他们这已经被 魔鬼 任意 掳去的,可以醒悟,脱离 他的 网罗。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, ' 你该知道, 末 世 必有危险的 日子 来到。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, '因为那时,人 要 专顾自己,贪爱钱财,自夸,狂傲,谤讟,违背 父母,忘恩负义,心不圣洁, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, '无亲情,不解怨,好说谗言,不能自约,性情凶暴,不爱良善, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, '卖主卖友,任意妄为,自高自大,爱宴乐,不爱 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, '有 敬虔 的外貌,却 背了 敬虔的 实意; 这等人 你要躲开 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, '那偷进 人家、 牢笼 无知妇女的, 正 是 这等人。这些妇女担负 罪恶,被各样的 私欲 引诱, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, '常常 学习, 终久不 能 明白 真道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, '从前 雅尼 和 佯庇 怎样 敌挡 摩西,这等人 也 怎样 敌挡 真道。他们的 心地 坏了,在真道 上 是可废弃的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, '然而 他们不能 再 这样敌挡;因为 他们的 愚昧 必 在众人 面前显露出来, 像那二人 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, '但 你 已经服从了 我的 教训、品行、志向、信心、宽容、爱心、忍耐, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, '以及我 在 安提阿、 以哥念、 路司得 所遭遇 的 逼迫、苦难。我所忍受 是何等的 逼迫;但 从 这一切苦难中,主 都把我 救出来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, '不但如此, 凡 立志 在基督 耶稣 里 敬虔 度日 的也都要受逼迫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, '只是 作恶的 和 迷惑人的,必越久越恶,他欺哄人,也 被人欺哄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, '但 你所学习的, 所确信的,要存在心里;因为你知道 是跟 谁 学的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, '并且 知道你是从 小 明白 圣 经,这 圣经能 使你 因 信 基督 耶稣,有 得救 的智慧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, '圣经 都是 神所默示的(或译:凡 神所默示的圣经), 于  教训、 督责、 使人归正、 教导 人 学义 都是有益的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, '叫属 神 的人 得以 完全,预备 行各样的 善 事。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, '我在 神 面前,并 在 将来 审判 活人 死人 的基督 耶稣面前, 凭著他的 显现 和 他的 国度 嘱咐你: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, '务要传 道,无论得时 不得时,总要专心,并用 百般的 忍耐、 各样的教训 责备人,警戒人,劝勉人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, '因为 时候 要到, 人必厌烦 纯正的 道理,耳朵 发痒,就 随从 自己的 情欲 增添 好些师傅, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, '并且 掩 耳 不听 真道, 偏 向 荒渺的言语。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, '你 却要 凡事 谨慎,忍受苦难,做 传道的 工夫,尽 你的 职分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, ' 我 现在 被浇奠, 我 离世 的时候 到了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, '那美好的 仗 我已经打过了,当跑的路 我已经跑尽了,所信 的道我已经守住了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, '从此以后,有公义的 冠冕 为我 存留, 就是按著公义 审判 的主 到了 那 日 要赐给 我的; 不 但 赐给我, 也 赐给凡 爱慕 他 显现的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, '你要赶紧地 到 我这里来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, '因为 底马 贪爱 现今的 世界,就离弃 我 往 帖撒罗尼迦去了;革勒士 往 加拉太去;提多 往 挞马太去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, '独有 路加 在我 这里。 你来的时候,要把 马可 带来,因为 他在传道(或译:服事我)的事上 于 我 有益处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, ' 我已经打发 推基古 往 以弗所去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, '我在 特罗亚 留 于  加布 的那件 外衣,你来 的时候可以带来,那些书 也要带来,更要紧的 是那些皮卷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, '铜匠 亚历山大 多多地 害 我;主 必照 他 所行的 报应 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, '你 也要 防备 他,因为 他极力 敌挡了 我们的 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, ' 我 初次 申诉,没有人 前来帮助,竟 都 离弃 我;但愿 这罪不 归与 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, '惟有 主 站在我 旁边, 加给我 力量,使 福音 被 我 尽都传明,叫 外邦人 都听见;我也 从 狮子 口 里被救出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, '主 必救 我 脱离 诸般的 凶恶,也 必救 我进 他的 天 国。愿 荣耀 归给他,直到 永永远远。阿们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, '问百基拉、 亚居拉,和 阿尼色弗 一家的人 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, '以拉都 在 哥林多 住下了。 特罗非摩 病了,我就留 他在 米利都。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, '你要赶紧 在冬天 以前 到我这里来。有友布罗、 布田、 利奴、 革老底亚,和 众 弟兄 都问你 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, '愿 主 与你的 灵 同在!愿 恩惠 常与你们 同在!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, '神 的仆人,耶稣 基督 的使徒 保罗,凭著 神 选民 的信心 与 敬虔 真理 的知识, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, ' 盼望 那 无谎言的 神 在万古 之先 所应许 的永 生, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, ' 到了 日期,藉 借著 传扬 的工夫把他的 道 显明了;这 传扬的责任是按著 神─我们 救主 的命令 交托 讬 了我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, '现在写信给提多,就是照著 我们共 信 之道作我真 儿子的。愿 恩惠、 平安 从 父 神 和 我们的 救主 基督 耶稣归与你! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, ' 我从前留 你 在 克里特,是要你将那没有办完的事 都办整齐了,又 照 我 所吩咐 你的, 在各 城 设立 长老。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, '若有 无可指责的人,只作一个 妇人 的丈夫, 儿女 也是信主的,没有人 告 他们是放荡 不服约束的,就可以设立。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, ' 监督 既是 神 的管家,必须 无可指责,不 任性,不 暴躁,不 因酒滋事,不 打人,不 贪无义之财; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, ' 乐意接待远人,好善,庄重,公平,圣洁 自持; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, ' 坚守所教 真实的 道理, 就 能 将纯正的 教训 劝化人,又 能把争辩的人 驳倒了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, '因为 有 许多 人不服约束, 说虚空 话欺哄人;那奉割礼 的 更是这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, '这些人 的口总要 堵住。他们因 贪不义 之财, 将不 该 教导的教导人, 败坏 人的全 家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, '有克里特人中 的 一个 本地 先知 说:「克里特人 常 说谎话,乃是恶 兽,又馋 又懒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, '这个 见证 是 真的。所以,你要严严地 责备 他们,使 他们在真道 上 纯全无疵, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, '不 听 犹太人 荒渺的言语 和 离弃 真道 之人 的诫命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, '在洁净的人,凡物 都洁净; 在污秽 不信的人,什么都不 洁净, 连 心地 和 天良 也都污秽了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, '他们说是 认识 神,行事 却 和他相背;本是 可憎恶的, 是悖逆的, 在各样 善 事 上 是可废弃的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, '但 你 所讲的 总要合乎 那纯正的 道理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, '劝老年人 要有 节制、端庄、自守,在信心、爱心、忍耐 上都要纯全无疵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, '又 劝老年妇人, 举止行动 要恭敬,不 说谗言,不 给 酒 作奴仆,用善道教训人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, '好 指教少年妇人,爱丈夫,爱儿女, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, '谨守,贞洁,料理家务,待人有恩,顺服 自己的 丈夫,免得 神 的道理 被毁谤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, '又 劝 少年人 要谨守。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, '你自己 凡事 要显出 善 行 的榜样;在教训 上 要正直、端庄, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, '言语 纯全,无可指责,叫 那反对 的人,既无处 可 说 我们 的不是,便自觉羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, '劝仆人 要顺服 自己的 主人, 凡事 讨 他的喜欢,不可 顶撞他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, '不可 私拿东西,要 显为 忠诚,以致 凡事 尊荣 我们救主─ 神 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, '因为 神 救 众 人 的恩典 已经显明出来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, '教训 我们 除去 不敬虔的心 和 世俗的 情欲,在 今 世 自守、 公义、 敬虔 度日, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, '等候 所盼望的 福,并 等候至大的 神 和 我们(或译: 神─我们)救主 耶稣 基督 的荣耀 显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, '他 为 我们 舍了 自己,要 赎 我们 脱离 一切 罪恶,又 洁净 我们,特作 自己的子民,热心 为善。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, '这些事 你要讲明, 劝戒人, 用 各等 权柄 责备人;不可叫人 轻看 你。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, '你要提醒 众人,叫他们顺服 作官的、掌权的,遵他的命, 预备 行各样的 善 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, '不要 毁谤,不要 争竞,总要和平,向 众 人 大 显 温柔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, ' 我们 从前 也 是 无知、悖逆、受迷惑、服事 各样 私欲,和 宴乐,常存 恶毒(或译:阴毒) 嫉妒的心,是可恨的,又是彼此 相恨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, '但到了 神─我们 救主 的恩慈 和 他向人所施的慈爱 显明 的时候, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, '他便救了 我们;并不是 因 我们 自己所行 的 义,乃是 照 他的 怜悯,藉 借著 重生 的洗 和 圣 灵 的更新。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, '圣灵就是 神藉 借著 耶稣基督─ 我们 救主 厚厚 浇灌 在 我们身上的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, '好叫 我们因他的 恩 得称为义,可以凭著 永 生 的盼望 成为 后嗣(或译:可以凭著盼望承受永生)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, '这话 是可信的。我也 愿  你 把 这些事 切切实实地讲明,使 那些已信 神 的人留心 做 正经 事业(或译:留心行善)。这 都是 美事,并且 与人 有益。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, '要 远避 无知的 辩论 和 家谱的空谈,以及 纷争,并因 律法 而起的争竞,因为 这都是 虚妄 无益的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, '分门结党的 人,警戒 过 一 两次,就要弃绝他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, '因为 知道 这等人 已经背道, 犯了罪,自己明知不是,还是去做。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, '我打发 亚提马 或是 推基古 到 你 那里去的时候,你要赶紧 往 尼哥坡里 去见 我,因为 我已经定意 在那里 过冬。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, '你要赶紧 给律师 西纳 和 亚波罗 送行,叫 他们 没有 缺乏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, ' 并且 我们的人 要学习 正经 事业(或译:要学习行善),预备 所需 用的,免得 不结果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, '同我 在一处的人 都 问你 安。请代问那些因 有信心 爱 我们 的人安。愿 恩惠 常与你们 众人 同在!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, '为基督 耶稣 被囚的 保罗,同 兄弟 提摩太 写信给我们 所亲爱的 同工 腓利门, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, '和 妹子 亚腓亚 并 与我们 同当兵的 亚基布,以及 在 你 家 的教会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, '愿 恩惠、 平安 从 神 我们的 父 和 主 耶稣 基督 归与你们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, '我 祷告 的时候提到 你,常 为你感谢 我的 神; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, '因听说 你的 爱心 并 你向 主 耶稣 和 众 圣徒 的信心(或译:因听说你向主耶稣和众圣徒有爱心有信心)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, ' 愿 你 与人所同有的 信心 显出 功效,使 人知道 你们各样 善事 都是为 基督做的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, ' 兄弟啊,我为 你 的爱心,大 有 快乐, 大得安慰,因 众圣徒 的心 从 你 得了畅快。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, ' 我虽然靠著 基督 能 放胆 吩咐 你 合宜的事, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, '然而像 我这 有年纪的 保罗, 现在 又是 为基督 耶稣 被囚的,宁可 凭著 爱心 求你, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, '就是为 我 在 捆锁 中所 生 的儿子 阿尼西谋(就是有益处的意思)求 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, '他 从前 与你 没有益处,但 如今 与你 我 都有益处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, ' 我现在打发 他 亲自回你那里去;他 是 我 心上的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, '我 本来有意 将他 留下, 在 我为福音 所受的捆锁 中替 你 伺候 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, '但 不知道 你 的意思,我就不 愿 意 这样行,叫 你 的善行 不是 出于  勉强,乃 是 出于  甘心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, ' 他暂时 离开 你,或者 是叫 你永远 得著 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, '不再 是 奴仆,乃是 高过 奴仆,是亲爱的 兄弟。在我 实在是如此,何况 在你呢!这也不拘 是按 肉体说, 是按 主说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, '你若 以 我 为同伴,就收纳 他,如同 收纳我一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, ' 他若 亏负 你,或 欠 你什么, 都归在 我的帐上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, '我 必偿还,这是我─ 保罗 亲笔 写的。我并不用 对你 说, 连 你自己 也是亏欠 于 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, ' 兄弟啊,望你使我 在主 里 因你 得快乐(或译:益处),并望你使我的 心 在基督 里 得畅快。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, '我写信 给你,深信 你 必顺服,知道 你所要 行的 必过于  我所说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, ' 此外 你还要 给我 预备 住处;因为 我盼望 藉 借著 你们的 祷告,必蒙恩 到你们那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, '为 基督 耶稣 与我 同坐监的 以巴弗 问你 安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, '与我 同工的 马可、亚里达古、底马、路加也都问你安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, '愿 我们主 耶稣 基督 的恩 常在 你的 心里。阿们!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, '神 既在古时 藉 借著 众先知 多次 多方 地晓谕 列祖, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, '就在 这 末 世 藉 借著 他儿子 晓谕 我们;又早已立 他 为承受 万有的,也 曾藉 借著 他 创造 诸世界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, '他 是 神荣耀 所发的光辉,是 神 本体 的真像, 常用他 权能 的命令 托住 万有。他洗净了 人的罪,就坐 在 高天 至大者 的右边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, ' 他所承受的 名,既比 天使 的名更 尊贵, 就远超过 天使。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, '所有的天使, 神从来 对 哪一个 说:你 是 我的 儿子,我 今日 生 你?又指著哪一个说:我 要作 他的 父, 他 要作 我的 子? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, '再者, 神使 长子 到 世上 来的时候(或译: 神再使长子到世上来的时候),就说: 神 的使者 都 要拜 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, ' 论到 使者,又说: 神以 风 为 使者, 以火 焰 为 仆役; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, '论到 子 却说: 神啊,你的 宝座 是永永远远的;你的 国 权 是正直的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, '你喜爱 公义, 恨恶 罪恶;所以 神,就是你的 神,用喜乐 油 膏 你,胜过 膏你的 同伴; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, '又说:主啊,你 起初 立了地 的根基; 天 也是 你 手 所造的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, '天地 都要灭没,你 却 要长存。 天地都 要像 衣服 渐渐旧了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, ' 你要将天地 卷起来,像一件外衣, 天地就都改变了。惟有 你 永不改变; 你的 年数 没有 穷尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, ' 所有的天使, 神从来 对 哪一个 说:你坐 在 我的 右边,等 我使 你 仇敌 作你的 脚凳? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, '天使岂不 都 是 服役的 灵、奉差遣 为 那将要 承受 救恩 的人效力吗?   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, '所以,我们 当 越发 郑重 所听见的道理,恐怕 我们随流失去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, '那 藉 借著 天使 所传的 话 既是 确定的; 凡 干犯 悖逆的 都受了 该受的 报应。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, '我们 若忽略 这么大的 救恩,怎能 逃罪呢?这救恩 起 先 是 主 亲自讲的,后来是 听见 的人给 我们 证实了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, '神 又按 自己的 旨意, 用神迹、 奇事 和 百般的 异能,并 圣 灵 的恩赐,同他们作见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, ' 我们所说 将来的 世界, 神原没有 交给天使 管辖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, '但 有人 在经上某处 证明 说:人 算 什么,你竟 顾念 他? 世人算什么,你竟 眷顾 他? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, '你叫他 比 天使 微小 一点(或译:你叫他暂时比天使小),赐他 荣耀 尊贵 为冠冕,并将你手所造的都派他管理, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, '叫万物 都服 在他的 脚 下。 既叫 万物 都服 他,就没有剩下 一样不 服他的。只是 如今 我们还 不见 万物 都服 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, '惟独 见 那 成为比 天使 小 一点 的耶稣(或译:惟独见耶稣暂时比天使小);因为 受死的 苦,就得了尊贵 荣耀 为冠冕,叫他因著 神 的恩,为 人人 尝了 死味。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, '原来 那 为 万物所属、 为 万物所本的,要领 许多的 儿子 进 荣耀里去,使救 他们的 元帅,因受 苦难 得以完全,本是合宜的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, '因 那使人成圣的 和 那些得以成圣的, 都 是出于  一。所以, 他称 他们 为弟兄 也不 以为耻, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, '说:我要将你的 名 传与 我的 弟兄,在 会 中 我要颂扬 你; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, ' 又说:我 要 倚赖 他; 又说:看哪,我 与  神 所给 我 的儿女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, '儿女 既 同有 血 肉之体,他 也 照样 亲自成了 血肉之体,特要 藉 借著 死 败坏 那掌 死 权的,就是 魔鬼, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, '并 要释放 那些 一 生 因 怕 死 而为 奴仆的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, ' 他并 不 救拔 天使,乃是 救拔 亚伯拉罕 的后裔。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, '所以,他 凡事 该 与他的弟兄 相同,为要 在 神 的事上成为 慈悲 忠信的 大祭司,为 百姓 的罪 献上挽回祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, '他自己 既然 被试探 而受苦,就能 搭救 被试探的人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, ' 同蒙 天 召 的圣洁 弟兄啊,你们应当思想 我们 所认为 使者、 为大祭司 的耶稣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, '他为 那设立 他 的尽忠,如 同 摩西 在 神的 全 家尽忠一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, ' 他 比 摩西 算是 更 配多得荣耀,好像 建造 房屋 的比 房屋 更 尊荣; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, '因为 房屋 都必有 人 建造,但 建造 万物的就是 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, ' 摩西 为 仆人,在 神的 全 家 诚然 尽忠,为要 证明 将来必传说的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, '但 基督 为 儿子,治理 神的 家;我们若 将可夸的 盼望 和 胆量 坚持到底, 便是 他的家了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, ' 圣 灵 有 话说:你们今日 若 听 他的 话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, '就不可 硬著 心,像 在 旷野 惹他发怒、 试探 他的 时候一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, '在那里,你们的 祖宗 试 我探我,并且 观看 我的 作为 有四十 年之久。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, '所以,我厌烦 那 世代的人, 说:他们 心里 常常 迷糊,竟 不 晓得 我的 作为! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, '我 就 在怒 中 起誓说:他们断不可 进 入 我的 安息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, '弟兄们,你们要谨慎,免得 你们 中间 或有人 存著 不信的 恶 心,把 永生 神 离弃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, '总要 趁著 还有 今日, 天天 彼此 相劝,免得 你们 中间 有人被罪 迷惑,心里就刚硬了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, '我们若 将起初 确实的 信心 坚持 到 底, 就在基督 里有 分了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, '经上 说:「你们今日 若 听 他的 话,就不 可硬著 心,像 惹他发怒的 日子一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, '那时,听见 他话惹 他发怒的是谁呢?岂 不 是跟著 摩西 从 埃及 出来 的众人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, '神四十 年之久,又 厌烦 谁呢?岂不 是那些犯罪、尸首 倒 在 旷野 的人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, '又 向谁 起誓,不 容他们进 入 他的 安息呢?岂不是 向那些不信从的人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, '这样 看 来,他们不 能 进入 安息是因为 不信的缘故了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, '我们既蒙留下,有进 入 他 安息 的应许,就当 畏惧,免得我们(原文是你们)中间 或有人 似乎 是赶不上了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, '因为 有 福音传给我们,像 传给他们一样;只是 所听见的 道 与他们 无 益,因为他们没 有信心 与所听见的 道调和。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, '但 我们 已经相信 的人得以进 入 那安息,正如 神所说:「我在 怒 中起誓说:『 他们断不可进 入 我的 安息!』」其实 造物之工,从 创 世 以来已经成全了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, ' 论到 第七日,有一处 说:「到 第七日, 神 就歇了 他 一切的 工。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, ' 又 有一处说:「 他们断不可进 入 我的 安息!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, '既 有必 进 安息的人,那 先前 听见福音的,因为 不信从,不得 进去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, '所以 过了 多 年,就在 大卫的书上,又 限定 一日,如 以上所引的说:「你们今日 若 听 他的 话,就不可 硬著 心。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, '若 是 约书亚 已叫他们 享了安息,后来 神 就不 再提 别的 日子了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, '这样看来,必另有一安息日的安息为 神的 子民 存留。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, '因为 那进 入 安息的, 乃是 歇了 自己的 工,正如 神 歇了他的工一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, '所以,我们务必竭力 进 入 那 安息,免得 有人 学 那不信从的 样子 跌倒了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, ' 神 的道 是活泼的, 是有功效的, 比 一切 两刃 的剑 更快,甚至魂 与 灵, 骨节 与 骨髓,都能刺 入、剖开 ,连 心 中的思念 和 主意 都能辨明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, '并且 被造的 没 有 一样在他 面前 不显然的; 原来万物 在那 与 我们有 关系 的主 眼前,都是赤露 敞开 的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, '我们既然 有 一位已经升入 高天 尊荣的大 祭司,就是 神 的儿子 耶稣,便当持定 所承认的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, '因 我们的 大祭司 并非不 能 体恤 我们的 软弱。他也曾凡事 受过 试探,与我们一样,只是 他没有 犯罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, '所以,我们只管坦然无惧地 来到 施恩 的宝座前,为 要得 怜恤, 蒙 恩惠,作 随时的 帮助。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, ' 凡 从人 间 挑选的 大祭司,是奉派 替 人 办理属 神的事,为 要献上 礼物 和 赎罪祭(或译:要为 罪献上礼物和祭物)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, '他能 体谅 那愚蒙的 和 失迷的人,因为 他自己 也 是被软弱 所困。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, ' 故 此,他理当 为 百姓 和 自己 献祭 赎 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, ' 这大祭司的尊荣,没有 人 自 取。惟要蒙 神 所 召,像 亚伦一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, '如此,基督 也 不 是自 取荣耀 作 大祭司,乃 是在乎向 他 说「你 是 我的 儿子,我 今日 生 你」的那一位; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, '就如 经上 又 有 一处说:「你 是照著 麦基洗德 的等次 永远 为祭司。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, '基督 在 肉体 的时候,既 大声 哀哭, 流泪 祷告, 恳求 那 能 救 他 免 死的主,就 因 他的虔诚 蒙了应允。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, '他虽然 为 儿子,还是因 所 受的苦难 学了 顺从。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, '他既 得以完全,就为凡 顺从 他 的人成了 永远 得救 的根源, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, '并蒙 神 照著 麦基洗德 的等次 称 他为大祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, '论到 麦基洗德,我们 有好些 话,并且 难以 解明,因为 你们 听 不进去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, '看你们学习的工夫,本该 作 师傅,谁知还得 有 人将 神 圣言 小学 的开 端 另 教导 你们,并且 成了 那必须 吃 奶、 不能吃 干 粮的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, ' 凡 只能吃 奶 的都不熟练 仁义 的道理,因为 他是 婴孩; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, '惟独 长大成 人 的才能吃干 粮; 他们的心窍 习练 得 通达,就能 分辨 好 歹了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, '所以,我们应当离开  基督 道理 的开 端,竭力进 到 完全的地步,不 必再 立 根基,就如那懊悔 死 行、 信 靠 神、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, '各样洗礼、 按 手之礼、 死人 复活,以及 永远 审判 各等教训。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, '神 若 许我们,我们必 如此 行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, '论到 那些已经 蒙了光照、 尝过 天 恩的滋味、又 于 圣 灵 有 分, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, '并 尝过 神 善 道的滋味、 觉悟来 世 权能的人, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, '若是 离弃道理,就不能 叫他们重新 懊悔了。因为他们把 神 的儿子 重钉十字架, 明明地羞辱他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, '就如 一块田地, 吃过 屡次 下的 雨水, 生长 菜蔬,合乎 耕种的 人用,就从 神 得 福; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, '若 长 荆棘 和 蒺藜,必被废弃, 近于  咒诅,结局 就是 焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, '亲爱的弟兄们,我们虽 是这样 说,却 深信 你们 的行为强过这些,而且 近乎 得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, '因为 神 并非 不公义,竟忘记 你们 所做的工 和 你们为 他 名 所显的 爱心,就是 先前伺候 圣徒,如今还是 伺候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, ' 我们愿  你们 各人 都显出 这样的 殷勤,使 你们有满足的 指望,一直到 底。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, '并且不 懈怠,总要 效法 那些凭 信心 和 忍耐 承受 应许的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, '当初 神 应许 亚伯拉罕的时候,因为 没有 比自己更大 可以 指著 起誓的,就指著 自己 起誓,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, '「论 福,我必 赐大福 给你; 论子孙,我必叫你的 子孙多起来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, '这样,亚伯拉罕既 恒久忍耐,就得了 所应许的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, '人 都 是指著 比自己大 的起誓,并且 以起誓 为 实据,了结 各样 的争论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, '照样, 神 愿 意 为那承受应许 的人 格外 显明 他的 旨意 是不更改的,就起誓 为证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, '藉 借 这 两 件不更改 的事, 神 决不 能说谎, 好叫我们 这逃往避难所、持定 摆在 我们前头指望 的人可以大 得 勉励。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, '我们有 这指望,如同 灵魂 的锚, 又坚固 又 牢靠,且 通 入 幔 内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, ' 作先锋 的耶稣,既照著 麦基洗德 的等次 成了 永远的 大祭司,就为 我们 进入幔内。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, ' 这 麦基洗德 就是撒冷 王,又是至高 神 的祭司,本是长远为祭司的。他当 亚伯拉罕 杀败 诸王 回来的时候,就 迎接他,给他 祝福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, '亚伯拉罕 也 将自己所得来的,取十分之一 给 他。他头一个 名翻出来 就是仁义 王, 他又 名撒冷 王, 就是 平安 王的意思。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, '他无 父,无母,无族谱,无 生 之始,无 命 之终,乃是与 神 的儿子 相似。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, ' 你们想一想, 先祖 亚伯拉罕 将自己所 掳来上等之物 取十分之一 给 他,这人 是何等尊贵呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, ' 那 得 祭司职任 的 利未 子孙,领 命 照 例 向百姓 取十分之一,这百姓是 自己的 弟兄,虽 是从 亚伯拉罕身(原文是腰)中生的,还是照例取十分之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, '独有麦基洗德,不 与 他们 同谱,倒收纳 亚伯拉罕的十分之一,为那 蒙 应许 的亚伯拉罕祝福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, '从来 位分大的 给 位分小的 祝福,这是驳不倒的理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, '在 这里 收 十分之一 的都是必死的 人;但 在那里收十分之一的,有为他作见证 的说,他是活的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, '并且 可说 那 受 十分之一 的利未,也是 藉 借著 亚伯拉罕 纳了十分之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, '因为 麦基洗德 迎接 亚伯拉罕 的时候,利未已经 在 他先祖的身(原文是腰)中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, '从前百姓 在利未人 祭司职任 以下 受律法,倘 若 藉 借 这职任能得 完全,又 何 用 另外 兴起 一位祭司,照 麦基洗德 的等次, 不 照 亚伦 的等次呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, '祭司的职任 既已 更改,律法 也 必须 更 改。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, '因为 这 话 所指的 人 本属 别的 支派,那支派 里 从来没有一人 伺候 祭坛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, ' 我们的 主 分明 是 从 犹大 出来的;但 这 支派,摩西 并没有 提到 祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, '倘若 照 麦基洗德 的样式,另外 兴起 一位祭司来, 我的话更 是 显而 易见的了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, '他 成为祭司,并不 是照 属肉体 的条例,乃是 照无穷(原文是不能毁坏)之生命 的大能。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, '因为 有给他作见证 的说:「你 是照著 麦基洗德 的等次 永远 为祭司。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, '先前的 条例,因 软弱 无益,所以 废掉了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, '(律法 原来 一无 所成)就 引进了 更美的 指望;靠 这指望,我们便可以进到 神面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, '再者,耶稣为祭司,并不是 不 起 誓立的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, '至于  那些祭司,原不 是 起 誓立的,只有 耶稣是起誓立的;因为那立他的 对 他 说:「主 起了誓,决 不 后悔,你 是永远 为祭司。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, ' 既是起誓立的,耶稣 就作了 更美 之约 的中保。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, ' 那些成为 祭司的,数目本来 多,是因为 有死阻隔,不能 长久。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, '这位既是 永远 常存的,他 祭司的职任 就 长久不更换。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, '凡 靠著 他 进到 神面前的人,他都 能 拯救 到 底;因为他是长远 活著, 替 他们 祈求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, '像 这样 圣洁、无邪恶、无玷污、远离 罪人、 高过 诸天 的大祭司,原是 与我们 合宜的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, '他 不 像 那些大祭司,每日 必须 先 为 自己的 罪,后 为百姓的 罪献 祭;因为 他只一次 将自己 献上,就把这事成全了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, '律法 本是 立 软弱 的人 为大祭司;但 在 律法 以后起誓 的话,是立儿子为大祭司,乃是成全 到 永远的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, '我们所 讲 的事,其中第一要紧的,就是我们有 这样的 大祭司, 已经坐 在 天 上 至大者 宝座 的右边, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, '在圣所,就 是真 帐幕里,作执事;这帐幕 是主 所支的,不 是人所支的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, ' 凡 大祭司 都是为 献 礼物 和 祭物 设立的,所以 这位大祭司 也 必须 有 所 献的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, '他若 在 地 上,必不 得 为 祭司,因为已经有 照 律法 献 礼物的祭司。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, '他们 供奉 的事本是天上事 的形状 和 影像,正如 摩西 将要 造 帐幕的时候,蒙 神警戒他,说:「你要 谨慎,作 各样的物件 都要照著 在 山 上指示 你的 样式。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, '如今 耶稣所得的 职任 是更美的,正如 他作 更美 之约 的中保;这约 原是凭 更美 之应许 立的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, ' 那 前 约若 没有 瑕疵,就 无 处 寻求 后约了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, '所以 主指责他的百姓说(或译:所以主 指前约的 缺欠 说): 日子 将到, 我要与 以色列 家 和 犹大 家 另立 新 约, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, '不 像 我 拉著 他们 祖宗 的手,领 他们 出 埃及 的时候,与他们所 立的 约。因为 他们 不 恒心 守 我的 约,我 也不理 他们。这是主 说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, '主 又说: 那些 日子 以后,我与以色列 家 所 立的 约 乃是这样:我要将我的 律法 放 在 他们 里面, 写 在 他们 心上; 我要作 他们的 神; 他们 要作 我的 子民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, ' 他们不用 各人 教导 自己的 乡邻 和 自己的 弟兄,说:你该认识 主;因为 他们 从 最小的 到 至大的,都 必认识 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, ' 我要 宽恕 他们的 不义, 不 再 记念 他们的 罪愆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, '既 说 新约,就 以 前约 为旧了;但 那渐旧渐衰的,就必快 归无有了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, '原 来 前 约 有 礼拜 的条例 和 属世界的 圣幕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, '因为 有预备的 帐幕,头一层 叫作 圣所,里面 有灯台、 桌子,和 陈设 饼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, '第二 幔子 后 又 有一层帐幕, 叫作 至圣所, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, '有 金 香炉(炉:或译坛), 有包 金 的约 柜,柜 里 有 盛吗哪 的金 罐 和 亚伦 发过芽 的杖,并 两块约 版; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, ' 柜 上面 有荣耀 基路伯 的影罩著施恩(施恩:原文是蔽罪)座。这几件 我现在 不 能 一一 细说。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, '这些物件 既 如此 预备齐了,众祭司 就常 进 头一层 帐幕,行拜 神的礼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, '至于  第二层帐幕,惟有大祭司 一年 一次 独自进去,没有 不带著 血 为 自己 和 百姓 的过错 献上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, '圣 灵 用此 指明,头一层 帐幕 仍 存的时候,进入至圣所 的路 还未 显明。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, '那 头一层帐幕作 现今 的一个表 样, 所 献的 礼物 和 祭物,就著 良心说,都不 能 叫礼拜 的人得以完全。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, '这些事,连 那 饮 食 和 诸般 洗濯的规矩,都不过是属肉体的 条例,命定 到 振兴 的时候为止。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, '但 现在基督 已经来到,作了 将来美事 的大祭司,经过 那更大 更全备 的帐幕,不 是人手 所造,也不 是属乎这世界的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, '并且不 用 山羊 和 牛犊 的血,乃 用 自己的 血,只一次 进 入 圣所,成了 永远 赎罪的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, ' 若 山羊 和 公牛 的血,并 母牛犊 的灰,洒在 不洁的人身上,尚且叫人成圣, 身体 洁净, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, '何况基督 藉 借著 永远的 灵,将自己 无瑕无疵 献给 神,他的 血 岂不 更 能洗净 你们的心(原文是良心),除去 你们的死 行,使你们事奉 那永生 神吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, ' 为此, 他作了 新 约 的中保,既然 受 死 赎了 人在 前 约 之时所犯的罪过,便叫 蒙召 之人得著 所应许 永远的 产业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, '凡 有 遗命必须等到 留遗命(遗命:原文与约字同)的人 死了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, '因为 人死 了,遗命 才有效力,若 留遗命的 尚 在,那遗命还有 用处吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, '所以,前 约也不 是不用 血 立的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, '因为 摩西 当日 照著 律法 将各样 诫命 传给 众 百姓,就拿 朱红色 绒 和 牛膝草,把 牛犊 山羊 的血 和 水 洒在 书上,又 洒在众 百姓身上,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, '「这 血 就是 神 与 你们 立 约 的凭据。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, '他又 照样 把血 洒在 帐幕 和 各样 器皿上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, ' 按著 律法,凡物 差不多 都是用 血 洁净的;若不 流血,罪就 不 得 赦免了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, ' 照著 天上 样式 做的物件 必须 用这些 祭物去洁净;但 那天上的本 物 自然当用 更美的 祭物去洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, '因为 基督 并不 是进了 人手 所造的圣所(这不过是真 圣所的影像),乃 是进了 天堂,如今 为 我们 显在 神 面前; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, '也不 是 多次 将自己 献上,像 那大祭司 每 年 带著 牛羊 的血(牛羊的血:原文作不是自己的血)进 入 圣所, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, '如果这样,他 从 创 世以来,就必 多次 受苦了。但 如今 在 这末 世 显现 一次,把 自己 献为祭,好 除掉 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, ' 按著 定命,人人 都有一 死,死后 且 有 审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, '像这样,基督 既然一次 被献, 担当了 多人 的罪,将来要向那等候 他 的人第二次 显现,并与罪 无关,乃是为 拯救他们。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, '律法 既 是 将来 美事 的影儿,不 是本物 的真 像,总不 能 藉 借著每年 常 献 一样的 祭物 叫那近前来的人得以 完全。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, '若不然,献祭 的事 岂不 早已止住了吗?因为 礼拜的人,良心 既被 洁净,就不 再 觉得有 罪了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, '但 这些 祭物是叫 人每 年 想起 罪来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, '因为 公牛 和 山羊 的血,断不能 除 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, '所以 基督到 世上 来的时候,就说: 神啊,祭物 和 礼物 是你不 愿 意的; 你曾给我 预备了 身体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, '燔祭 和 赎罪祭 是你不 喜欢的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, '那时 我说: 神 啊,我来了,为要照你的 旨意 行;我 的事 在经 卷 上 已经记载了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, '以上 说:「 祭物 和 礼物, 燔祭 和 赎罪祭,是你不 愿 意的,也是 你不喜欢的(这 都是按著 律法 献的)」; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, '后 又说:「 我来了 为要照你的 旨意 行」;可见他是除去 在先的,为 要立定 在后的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, '我们凭 这 旨意,靠 耶稣 基督,只一次 献上 他的身体,就得以 成圣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, ' 凡 祭司 天天 站著 事奉 神, 屡次 献上 一样的 祭物,这祭物 永不 能 除 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, '但 基督 献了 一次 永 远 的 赎罪祭,就在 神 的右边 坐下了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, '从此,等候 他 仇敌 成了 他的 脚凳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, '因为 他一次 献祭,便叫那得以成圣 的人永 远 完全。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, '圣 灵 也 对 我们 作见证;因为 他既已 说过: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, '主 说:那些 日子 以后,我与 他们 所 立 的约 乃是这样:我要将我的 律法 写 在 他们 心上,又 要放 在 他们 的 里面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, '以后就说:我不 再 记念 他们的 罪愆 和 他们的 过犯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, '这些罪过 既 已 赦免,就不用再 为 罪 献祭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, '弟兄们,我们既 因 耶稣 的血 得 以坦然 进 入 至圣所, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, '是 藉 借著他给 我们 开 了一条又新 又 活 的路,从 幔子经过,这幔子就是 他的 身体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, '又 有一位大 祭司 治理 神 的家, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, '并 我们心中 天良 的亏欠 已经洒去,身体 用清 水 洗净了,就当存著 诚 心 和 充足的 信心 来到 神面前; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, '也要坚守 我们所承认的 指望,不至摇动,因为 那应许 我们的是信实的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, '又 要彼此 相顾, 激发 爱心, 勉励行 善。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, '你们 不 可停止 聚会,好像 那些 停止惯了的人,倒 要彼此劝勉,既知道(原文是看见)那日子 临近,就 更 当如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, '因为 我们 得 知 真道 以后,若故意 犯罪, 赎罪 的祭 就再 没有了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, '惟 有 战 惧 等候 审判 和 那 烧灭 众敌人 的烈 火。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, '人 干犯 摩西 的律法,凭 两 三 个见证人,尚且不得 怜恤 而死, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, '何况人 践踏 神 的儿子, 将那 使 他成圣 之约 的血 当作 平常,又 亵慢 施恩 的圣灵,你们想,他要受的刑罚 该 怎样 加重呢! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, '因为 我们知道 谁说:「伸冤 在我,我 必报应」; 又说:「主 要审判 他的 百姓。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, '落在 永生 神 的手 里,真是可怕的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, '你们要 追念 往 日, 蒙了光照 以后所忍受 大 争战  的各样苦难: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, '一面 被毁谤, 遭患难,成了 戏景,叫众人观看; 一面 陪伴 那些受这样 苦难的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, '因为 你们体恤了 那些被捆锁的人,并且 你们的 家业 被人抢去,也甘心 忍受,知道 自己 有 更美 长存的 家业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, '所以,你们不 可丢弃 勇敢的心;存这样 的心必得 大 赏赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, ' 你们必 须 忍耐,使 你们行完了 神 的旨意,就可以得著 所应许的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, '因为 还有 一点点 时候,那要来 的就来,并 不 迟延; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, '只是 义人(有古卷:我的义人) 必因 信 得生。他若 退后,我 心里 就不 喜欢 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, '我们 却 不 是 退后 入 沉沦的那等人,乃是 有信心 以致 灵魂 得救的人。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, '信 就 是 所望 之事的实底,是未 见 之事 的确据。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, ' 古人 在 这 信上得了美好的证据。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, '我们因著信,就知道 诸世界是藉 借 神 话 造成的;这样,所 看见的,并不 是从 显然之物 造出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, '亚伯 因著信,献祭与 神,比该隐 所献的 更 美,因 此 便得了称 义 的见证,就是 神 指 他 礼物 作的见证。他虽然死了,却 因 这信,仍旧 说话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, '以诺 因著信,被接去,不 至于 见 死,人也 找 不著他,因为 神 已经把他 接去了;只是 他被接去 以先,已经得了 神 喜悦 他的明证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, ' 人非有 信,就不能得 神的喜悦;因为 到 神 面前来的人必须 信 有 神,且 信他 赏赐 那寻求 他的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, '挪亚 因著信,既蒙 神指示 他未 见 的事,动了敬畏的心,预备了 一只方舟,使 他 全家 得救。 因此就定了 那世代的罪,自己也 承受了 那从 信 而来的义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, '亚伯拉罕 因著信,蒙召 的时候就遵命 出去,往 将来要 得 为 业 的 地方去;出去的时候,还 不 知 往哪里 去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, '他因著信,就在 所应许 之地 作客,好像 在 异地 居住 帐棚,与 那同蒙 一个应许 的以撒、 雅各 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, '因为 他等候 那座 有 根基的城,就是 神 所经营 所 建造的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, '因著信,连 撒拉 自己,虽然 过了 生育 的岁数, 还能怀 孕,因 她以为 那应许 她的是可信的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, '所以 从 一个 仿佛已 死 的人 就生出子孙,如同 天上 的星 那样众多, 海 边 的沙 那样 无数。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, '这些 人 都是存著 信心 死的,并没 有得著 所应许的;却 从远处 望见,且 欢喜迎接,又 承认 自己在 世上 是 客旅,是 寄居的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, ' 说 这样话 的人是表明 自己要找 一个家乡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, ' 他们若 想念 所 离开  的家乡,还有 可以 回去 的机会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, '他们却 羡慕 一个更美的家乡,就是 在天上的。所以 神 被称为 他们的 神,并不 以为耻,因为 他已经给他们 预备了 一座城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, '亚伯拉罕 因著信,被试验的时候,就把以撒 献上;这便是 那欢喜领受 应许的,将自己独生的儿子 献上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, '论到 这儿子,曾有话说:「 从 以撒 生的才要称为 你的 后裔。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, '他以为 神 还 能 叫人从 死 里复活;他也 仿佛 从死中 得回 他的儿子来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, '以撒 因著信,就指著将来 的 事给雅各、 以扫 祝福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, '雅各 因著信,临死的时候,给约瑟 的两个 儿子 各自祝福, 扶著 杖 头 敬拜 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, '约瑟 因著信,临终的时候,提 到 以色列 族 将来要出埃及,并 为 自己的 骸骨 留下遗命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, '摩西 生下来,他的 父母 见 他是个俊美的 孩子,就因著信,把 他藏了 三个月,并 不 怕 王 命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, '摩西 因著信,长大了 就不肯 称为 法老 女儿 之子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, '他宁 可和 神 的百姓 同受苦害,也不愿  暂时 享受 罪 中之乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, '他看为基督 受的凌辱 比 埃及 的财物 更 宝贵,因 他想望 所 要得的赏赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, '他因著信,就离开  埃及,不 怕 王 怒;因为 他恒心忍耐,如同 看见 那不能看见的主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, '他因著信,就守(或译:立)逾越节, 行洒 血的礼,免得 那灭 长子 的临近 以色列人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, '他们因著信,过 红 海 如 行 干地; 埃及人 试著 要过去,就被吞灭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, '以色列人因著信,围绕 耶利哥 城 七 日,城墙就倒塌了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, '妓女 喇合 因著信,曾 和和平平地 接待 探子,就不与那些不 顺从 的人一同灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, '我又 何必 再 说呢? 若要一一细说, 基甸、巴拉、参孙、耶弗他、大卫、 撒母耳,和 众先知的事,时候 就 不够了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, '他们 因著 信,制伏了 敌国,行了 公义,得了 应许,堵了 狮子 的口, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, '灭了 烈火 的猛势,脱了 刀剑 的锋刃; 软弱 变为刚强, 争战  显出 勇敢,打退 外邦的 全军。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, '有妇人 得 自己的 死人 复活。又 有人 忍受严刑,不 肯苟且得 释放(原文是赎),为 要得著 更美的 复活。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, '又 有人 忍受 戏弄、 鞭打、 捆锁、 监禁、各等的磨炼, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, '被石头打死,被锯锯死,受试探,被 刀 杀,披著 绵羊、山羊 的皮 各处奔跑,受穷乏、患难、苦害, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, '在 旷野、 山岭、 山洞、 地 穴,飘流无定,本是 世界 不 配有 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, '这些 人 都是因 信 得了美好的证据,却仍未 得著 所应许 的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, '因为 神 给 我们 预备了 更美的 事,叫 他们若不与 我们同得,就不能 完全。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, '我们既 有 这许多的 见证人,如同云彩 围著 我们,就当放下 各样的 重担,脱去容易缠累 我们的 罪,存 心忍耐,奔 那摆在我们 前头的 路程, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, '仰望 为我们信心 创始 成终 的耶稣(或译:仰望那将真道创始成终的耶稣)。他 因 那摆在 前面的 喜乐,就轻看 羞辱,忍受了 十字架的苦难,便 坐 在 神 宝座 的右边。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, '那 忍受 罪人 这样 顶撞 的,你们 要思想,免得 疲倦 灰 心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, '你们与 罪恶 相争,还没有 抵挡 到 流血的地步。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, '你们又 忘了 那 劝你们 如同 劝儿子 的话,说:我 儿,你 不 可轻看主 的管教,被 他 责备 的时候也不 可灰心; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, '因为 主 所爱 的,他必管教,又 鞭打 凡 所收纳 的儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, '你们所 忍受的,是 神 管教你们,待 你们 如同 待儿子。焉 有 儿子 不 被父亲 管教的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, '管教原是 众子 所共 受的。 你们若 不 受 管教,就 是 私子, 不 是儿子了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, '再者,我们 曾有 生身 的父 管教我们,我们尚且 敬重他,何况万灵 的父,我们岂不 更 当 顺服 他得 生吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, ' 生身的父都 是 暂 随 己 意 管教我们;惟有万灵的父管教我们,是 要 我们得益处,使 我们在他的 圣洁 上有分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, ' 凡 管教的事, 当时 不觉得 快乐,反 觉得愁苦;后来 却 为那经 练过 的人 结出 平安的 果子,就是义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, '所以,你们要把下垂的 手、 发酸的 腿 挺起来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, '也 要为自己的 脚,把道路 修 直了,使 瘸子 不致歪脚(或译:差路),反 得 痊愈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, '你们要追求 与 众人 和睦,并 要追求圣洁;非 圣洁 没有人 能见 主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, '又要谨慎,恐怕 有人 失了 神 的 恩;恐怕 有 毒 根 生出 来 扰乱你们, 因此 叫众人 沾染污秽; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, '恐怕 有 淫乱的,有 贪恋世俗 如 以扫的,他 因 一点 食物 把自己 长子的名分 卖了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, '后来 想要 承受 父所祝的福,竟被弃绝,虽然 号哭 切求,却 得不 著 门路 使他父亲的心意回转。这是 你们知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, '你们原 不 是来到 那能摸的山;此山有 火 焰、 密云、 黑暗、 暴风、 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, ' 角 声 与 说话 的声音。那些听见 这声音的,都求 不要再 向他们 说 话; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, '因为 他们当 不 起所命他们的话,说:「靠近 这山的,即便是 走兽,也要用石头打死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, ' 所见的 极其 可怕,甚至摩西 说:「我甚 是恐惧 战 兢。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, '你们乃是 来到 锡安 山, 永生 神 的城邑,就是天上的 耶路撒冷。那里有 千万的 天使, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, '有 名录 在 天上 诸长子 之会所共聚的总会,有 审判 众人的 神 和 被成全 之义人 的灵魂, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, '并 新 约 的中保 耶稣,以及 所洒的 血;这血所说的 比 亚伯 的血所说的更美。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, '你们总要谨慎,不 可弃绝 那向你们说话的。因为, 那些弃绝 在 地上 警戒 他们 的尚且不 能逃罪,何况 我们 违背 那从 天上警戒我们的呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, '当时 他的 声音 震动了 地,但 如今 他应许 说:「再 一次 我 不 单 要震动 地, 还要 震动天。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, ' 这再 一次的话,是指明 被震动的,就是 受造 之物都要挪去,使 那不 被震动 的常存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, '所以 我们既得了 不能震动 的国,就当 感恩,照 神所喜悦的,用 虔诚、 敬畏 的心事奉 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, '因为 我们的 神 乃是烈 火。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, '你们务要常存 弟兄相爱的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, '不 可忘记 用爱心接待客旅;因为 曾有接待客旅的,不知不觉 就 接待了 天使。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, '你们要记念 被捆绑的人,好像 与他们同受捆绑;也要记念遭苦害的人,想到 自己 也 在 肉身 之内。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, '婚姻,人人 都当 尊重,床 也 不可污秽;因为 苟合 行淫的人, 神 必要审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, '你们存心 不可贪爱钱财,要以自己所有的 为足;因为 主 曾说:「我总不 撇下 你,也 不 丢弃 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, '所以 我们 可以放胆 说:主 是帮助 我的,我必 不 惧怕;人 能把 我 怎么样呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, '从前引导 你们、传 神 之道 给你们 的人,你们要想念他们,效法他们的 信心,留心 看 他们为人 的结局。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, '耶稣 基督 昨日、 今日、一直到 永 远,是一样的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, '你们不 要被那诸般 怪异的 教训 勾引了去;因为 人心 靠恩 得坚固 才是好的,并不 是靠饮食。那 在 饮食上专心的 从来没有 得著益处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, '我们有 一祭坛,上面 的祭物是 那些在帐幕 中供职 的人不 可 同吃的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, '原来 牲畜的 血 被 大祭司 带 入 圣所 作 赎罪祭; 牲畜 的身子 被烧在 营 外。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, '所以,耶稣 要 用 自己的 血 叫百姓 成圣,也 就在城门 外 受苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, '这样,我们也当出到 营 外,就了 他去,忍受 他 所受的凌辱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, ' 我们 在这里 本没有 常存的 城,乃是 寻求 那将来的城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, '我们应当 靠著 耶稣,常常 以颂赞 为祭 献给 神,这就是 那承认 主 名 之人嘴唇 的果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, '只是 不 可忘记 行善 和 捐输的事,因为 这样的 祭是 神 所喜悦的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, '你们要 依从 那些引导 你们的,且要顺服;因 他们 为 你们 的灵魂 时刻警醒,好像 那将来交 帐的人。你们要使 他们交的 时候有 快乐,不 致 忧愁;若 忧愁 就与你们 无益了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, '请你们为 我们 祷告,因 我们自觉 良心无亏,愿 意 凡事 按正道 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, ' 我更 求 你们为我祷告,使 我快些 回到 你们那里去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, '但愿  赐平安的 神,就是那凭 永 约 之血、使群羊 的大 牧人─我 主 耶稣 从 死 里复活的 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, '在 各样 善 事上成全 你们,叫 你们遵行 他的 旨意;又藉 借著 耶稣 基督 在 你们 心里行 他 所喜悦的事。愿 荣耀 归给他,直到永永 远 远。阿们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, ' 弟兄们, 我略略 写信 给你们,望 你们 听 我劝勉的 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, '你们该知道,我们的 兄弟 提摩太 已经释放了;他若 快 来,我必同 他 去见 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, '请你们问 引导 你们 的诸位 和 众 圣徒安。从意大利 来的 人也问 你们安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, '愿 恩惠 常与 你们 众人同在。阿们!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, '作 神 和 主 耶稣 基督 仆人 的雅各 请散住 十二个 支派 之人的安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, '我的 弟兄们, 你们落在 百般 试炼中,都 要以为 大喜乐; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, '因为知道 你们的 信心 经过试验,就生 忍耐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, '但 忍耐 也当 成功,使 你们 成全、 完备, 毫无 缺欠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, ' 你们 中间若 有 缺少 智慧的,应当求 那厚 赐与 众人、也 不 斥责人的 神, 主就必赐给 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, '只要 凭著 信心 求,一点不 疑惑;因为 那疑惑的人,就像 海 中的波浪,被风吹动 翻腾。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, ' 这样的 人 不要 想 从主 那里 得 什么。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, '心怀二意的 人,在他 一切 所行的路 上 都没有定见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, ' 卑微的 弟兄 升高,就该喜乐; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, ' 富足的 降卑,也该如此;因为 他必要过去,如同 草 上的花一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, ' 太阳 出来, 热风刮起, 草 就枯干, 花 也凋谢, 美 容 就消没了;那富足的人,在他 所行的事 上 也要 这样 衰残。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, ' 忍受 试探 的人 是有福的,因为 他经过试验 以后,必得 生命 的冠冕;这 是主应许 给那些爱 他之人的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, '人被试探,不可 说:「 我是被 神 试探」;因为 神 不能被 恶 试探,他 也不 试探 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, '但 各人 被试探,乃是被 自己的 私欲 牵引 诱惑的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, '私欲 既 怀了胎,就生出 罪来;罪 既 长成,就生出 死来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, '我 亲爱的 弟兄们,不要 看错了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, '各样 美善的 恩赐 和 各样 全备的 赏赐 都是 从上头来的,从 众光 之父 那里降下来的;在 他 并没 有 改变,也没有 转动的 影儿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, '他按自己的旨意,用真 道 生了 我们,叫 我们 在他 所造的万物 中好像 初熟的果子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, '我 亲爱的 弟兄们,这是你们所知道的。但 你们各 人 要 快快地 听,慢慢地 说,慢慢地 动怒, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, '因为 人 的怒气 并不 成就 神 的义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, '所以,你们要脱去 一切的 污秽 和 盈余 馀的 邪恶,存 温柔的心 领受 那所栽种的 道,就是 能 救 你们 灵魂的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, '只是 你们要 行 道, 不要 单单 听道,自己欺哄 自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, '因为 听 道 而 不 行道的, 就像 人 对著 镜子 看 自己 本来的 面目, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, ' 看见, 走后, 随即 忘了 他的相貌 如何。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, '惟有 详细察看 那全备、使人自由 之律法的,并且 时常如此,这人既不 是 听了 就忘,乃是 实在行出来, 就在他 所行的事 上 必然得福。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, '若 有人 自以为 虔诚,却不 勒住 他的 舌头,反 欺哄 自己的 心,这人 的虔诚 是虚的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, '在 神 我们的父 面前,那清洁 没有玷污的 虔诚,就是 看顾 在 患难 中 的孤儿 寡妇,并且保守 自己 不沾染 世俗。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, '我的 弟兄们,你们信奉 我们 荣耀的 主 耶稣 基督,便不 可 按著 外貌待人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, ' 若有 一个人 带著金戒指,穿著 华美 衣服,进 你们的 会堂 去;又有 一个穷人 穿著 肮脏 衣服 也 进去; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, ' 你们就重看 那穿 华美 衣服的人, 说:「 请坐 在这 好位上」;又 对那穷人 说:「你 站 在那里」,或「坐 在我 脚凳 下边。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, '这岂不是 你们 偏心待人, 用恶 意 断定人吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, '我 亲爱的 弟兄们,请听, 神 岂不是 拣选了 世上 的贫穷人,叫他们在信 上 富足,并 承受 他所应许 给那些爱 他 之人的国吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, '你们 反倒 羞辱 贫穷人。那富足人 岂不是 欺压 你们、 拉 你们 到公堂 去吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, '他们 不是 亵渎 你们所敬奉(所敬奉:或译被 称)的尊 名吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, '经 上记著说:「要爱 人 如 己。」你们 若 全守 这至尊的 律法 才是 好的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, '但 你们若 按外貌待人,便是犯 罪,被 律法 定 为 犯法的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, '因为 凡 遵守 全 律法的,只 在一条 上 跌倒,他就是 犯了 众条。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, ' 原来那说「不可 奸淫」的,也 说「不可 杀人」; 你就是 不 奸淫,却 杀人,仍是成了 犯 律法的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, '你们既然 要按 使人自由的 律法 受 审判,就该照这律法 说话 行事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, '因为 那 不 怜悯人的,也要受无怜悯 的审判;怜悯 原是向审判 夸胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, '我的 弟兄们,若 有人 说 自己有 信心,却 没 有 行为,有什么 益处呢?这信心 能 救 他吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, '若是 弟兄 或是 姊妹, 赤身露体,又 缺了 日用的 饮食; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, ' 你们 中间 有人 对他们 说:「 平平安安地 去吧!愿 你们穿得暖, 吃得饱」,却 不 给 他们 身体 所需用的,这有什么 益处呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, ' 这样,信心 若 没 有 行为 就是 死的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, ' 必有人 说:「你 有 信心,我 有 行为;你将你 没有 行为 的信心 指给 我看,我 便藉 借著 我的 行为,将我的信心 指给 你看。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, '你 信 神 只有 一位,你信的 不错;鬼魔 也 信,却是 战 惊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, ' 虚浮的 人哪,你愿 意 知道 没有 行为 的信心 是 死的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, '我们的 祖宗 亚伯拉罕 把他 儿子 以撒 献 在坛 上,岂不是 因 行为 称义吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, '可见, 信心 是与他的 行为 并行,而且 信心 因著 行为 才得成全。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, ' 这就应验 经上 所说:「 亚伯拉罕 信 神, 这就算 为 他 的义。」他又 得称为 神 的朋友。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, '这样看来, 人 称义 是因著 行为, 不是 单 因著 信。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, '妓女 喇合 接待 使者,又 放他们从别的 路 上出去, 不 也 是一样 因 行为 称义吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, ' 身体 没有 灵魂 是 死的, 信心 没有 行为 也 是 死的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, '我的 弟兄们,不 要 多人 作师傅,因为晓得 我们要受 更重的 判断。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, '原来 我们在许多事上 都有 过失;若 有人 在话语 上 没有 过失,他就是 完全 人,也 能 勒住 自己的全 身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, ' 我们若把嚼环 放 在马 嘴 里,叫 牠 顺服, 就能调动 牠的 全 身。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, '看哪, 船只 虽然 甚大,又 被 大 风 催逼,只用 小小的 舵,就随著 掌舵的 意思 转动。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, ' 这样,舌头 在百体 里也是 最小的,却 能说大话。看哪,最小的 火 能点著 最大的 树林。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, ' 舌头 就是火,在我们 百体 中,舌头 是 个罪恶 的世界,能污秽 全 身,也能 把生命的 轮子 点起来,并且 是从地狱 里 点著的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, ' 各 类 的走兽、 飞禽、 昆虫、 水族,本来都可以制伏,也 已经被人 制伏了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, '惟独 舌头 没有 人 能 制伏,是不止息的 恶物,满了 害死人 的毒气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, '我们用 舌头 颂赞 那为主、 为父的,又 用 舌头 咒诅 那 照著 神 形像 被造 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, '颂赞 和 咒诅 从 一个 口 里出来!我的 弟兄们,这 是 不 应当的! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, ' 泉源 从 一个 眼 里能发出 甜 苦两样的水吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, '我的 弟兄们, 无花果树 能 生 橄榄吗? 葡萄树 能结无花果吗?咸 水 里也不能 发出 甜水来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, '你们 中间 谁 是有智慧 有见识的呢?他 就当在智慧的 温柔 上 显出 他的善 行来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, ' 你们 心 里 若 怀著 苦毒的 嫉妒 和 纷争,就不可 自夸,也 不可说谎话 抵挡 真道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, '这样的 智慧 不 是 从上头 来的,乃是 属地的,属情欲的,属鬼魔的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, ' 在何处 有嫉妒、 纷争,就在何处 有扰乱 和 各样的 坏 事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, '惟独 从上头来的 智慧,先 是 清洁,后是 和平,温良 柔顺,满有 怜悯,多结善 果,没有偏见, 没有假冒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, '并且 使人 和平的,是用 和平 所栽种 的义 果。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, '你们 中间 的争战  斗殴 是从哪里来的呢?不是 从 你们 百体 中 战 斗 之私欲来的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, '你们贪恋, 还是得不 著;你们杀害 嫉妒,又斗殴 争战 ,也 不 能 得。你们得不 著,是因为 你们 不 求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, '你们求 也 得不 著,是因为 你们妄 求,要 浪费 在你们的 宴乐 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, '你们这些淫乱的人(原文是淫妇)哪,岂不 知 与世俗 为友 就是与 神 为敌吗?所以 凡 想要 与世俗 为友的,就是与 神 为敌了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, ' 你们想 经上 所说 是徒然的吗? 神所赐、住 在我们 里面 的灵,是恋爱 至于  嫉妒吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, '但 他赐 更多的 恩典,所以 经上说: 神 阻挡 骄傲的人, 赐 恩 给谦卑的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, '故此,你们要顺服 神。 务要抵挡 魔鬼, 魔鬼就必离开  你们 逃跑了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, '你们亲近 神, 神就 必亲近 你们。有罪的人哪,要洁净 你们的手! 心怀二意的人哪,要清洁 你们的心! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, '你们要愁苦、 悲哀、 哭泣,将 喜笑 变 作 悲哀, 欢乐 变作 愁闷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, '务要在主 面前 自卑,主就 必叫你们 升高。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, '弟兄们,你们不可 彼此 批评。人若批评 弟兄, 论断 弟兄,就是批评 律法, 论断 律法。 你若 论断 律法,就不 是 遵行 律法,乃是 判断人的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, '设立律法 和 判断人的,只有 一位, 就是那能 救 人也 能灭人的。 你 是 谁,竟敢论断 别人呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, '嗐!你们有话说:「今天 明天 我们要往 某 城 里去, 在那里 住 一年, 做买 卖 得利。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, ' 其实明天 如何,你们还不 知道。你们的 生命 是什么呢?你们原来 是 一片云雾, 出现 少时 就 不见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, ' 你们 只当说:「主 若 愿 意, 我们就可以活著,也 可以做 这事,或 做那事。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, '现今 你们竟 以 张狂 夸口;凡 这样 夸口 都是 恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, ' 人若知道 行 善,却 不去 行,这就是 他 的罪了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, '嗐!你们这些富足人哪,应当哭泣、号咷,因为 将有 苦难 临到你们身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, '你们的 财物 坏了, 衣服 也被 虫子咬了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, '你们的 金 银 都长了锈; 那 锈 要 证明 你们的不是,又要 吃 你们的 肉,如同 火烧。你们在 这末世 只知积攒钱财。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, ' 工人 给你们 收割 庄稼, 你们 亏欠 他们的工钱,这工钱有声音呼叫,并且 那收割 之人的冤声 已经入了 万军 之主 的耳了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, '你们在世 上 享美福, 好宴乐,当 宰杀 的日子 竟娇养 你们的 心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, '你们定了义人 的罪,把他杀害,他也不 抵挡 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, '弟兄们哪, 你们要忍耐,直到 主 来。看哪,农夫 忍耐 等候 地里 宝贵的 出产,直到 得了 秋雨春雨。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, '你们 也当 忍耐,坚固 你们的 心,因为 主 来 的日子近了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, '弟兄们,你们不要 彼此 埋怨,免得 受审判。看哪,审判的主 站 在门 前了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, '弟兄们,你们要把那 先前奉 主 名 说话 的众先知 当作 能受苦 能忍耐 的榜样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, ' 那先前忍耐的人,我们称他们是有福的。你们听见 过约伯 的忍耐,也 知道 主 给他的结局, 明显主 是 满心怜悯, 大有慈悲。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, '我的 弟兄们, 最要紧的 是不可 起誓;不可 指著天起誓,也不可 指著地起誓,无论何 誓 都不可起。 你们说话,是,就 说是; 不是,就说不是,免得 你们落 在审判 之下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, '你们 中间 有 受苦的呢,他就该祷告;有 喜乐的呢,他就该歌颂。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, '你们 中间 有 病了的呢,他就该请 教会 的长老来; 他们可以奉 主 的名 用油 抹 他,为 他 祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, ' 出于 信心 的祈祷 要救 那病人, 主 必叫他 起来;他若 犯了 罪,也必蒙赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, '所以 你们要彼此 认 罪, 互相代求,使 你们可以得医治。义人 祈祷 所发的力量 是大有 功效的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, '以利亚 与我们 是 一样 性情的人, 他恳切 祷告,求不要 下雨,雨 就 三 年 零 六个 月 不 下在地 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, ' 他又 祷告,天 就 降下 雨来,地 也 生出 土产。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, '我的 弟兄们,你们 中间 若 有 失迷 真道的, 有人 使他 回转, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, '这人 该知道: 叫一个罪人 从 迷路 上转回 便是救 一个灵魂 不 死,并且 遮盖 许多的 罪。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, '耶稣 基督 的使徒 彼得 写信给 那分散 在本都、加拉太、加帕多家、亚细亚、 庇推尼 寄居的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, '就是照 父 神 的先见被拣选,藉 借著圣灵 得成 圣洁,以致 顺服 耶稣 基督,又 蒙他血 所洒的人。愿 恩惠、 平安 多多地 加给你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, '愿 颂赞 归与我们 主 耶稣 基督 的 父 神!他 曾照 自己的 大 怜悯,藉 借 耶稣 基督 从 死 里复活,重生了 我们,叫我们有 活泼的 盼望, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, '可以得著 不能朽坏、 不能玷污、 不能衰残、为 你们 存留 在 天 上的基业。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, '你们这 因 信 蒙 神 能力 保守的人,必能得著 所预备、到 末 世 要显现 的救恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, '因 此,你们是大有喜乐;但如今, 在 百般的 试炼 中暂时 忧愁, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, '叫 你们 的 信心 既 被试验,就比那 被 火 试验 仍然 能坏 的金子 更显宝贵,可以在 耶稣 基督 显现 的时候得著 称赞、 荣耀、 尊贵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, '你们虽然没有 见过 他,却是爱他;如今 虽不得 看见,却 因信 他 就有 说不出来、 满有荣光 的大喜乐; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, '并且得著 你们 信心 的 果效,就是灵魂 的救恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, '论到 这 救恩,那 预先说 你们 要得 恩典 的众先知 早已详细地寻求 考察, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, '就是考察 在 他们 心里基督 的灵,预先证明 基督 受苦难, 后来 得荣耀,是指著什么时候,并 怎样的 时候。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, '他们 得了启示,知道他们所传讲(原文是服事)的一切事,不是 为自己,乃是 为你们。 那靠著 从 天 上差来的 圣 灵 传福音 给你们的人,现在 将这些事 报给 你们;天使 也愿 意 详细察看 这些事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, '所以要约束你们的心(原文是束上 你们 心 中的 腰),谨慎自守,专心 盼望 耶稣 基督 显现 的时候所带来 给你们 的 恩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, '你们既作 顺命的 儿女,就不要 效法 从前 蒙昧无知 的时候那放纵 私欲的样子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, ' 那 召 你们 的既是圣洁,你们在 一切 所行的事 上也 要 圣洁。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, '因为 经上记著 说:「你们要 圣洁,因为 我 是 圣洁的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, ' 你们既 称 那 不偏待人、按 各人 行为 审判 人的主为父,就当存 敬畏 的心度 你们 在世寄居 的 日子, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, '知道 你们得赎,脱去 你们 祖宗所传流 虚妄的 行为,不是 凭著能坏的 金 银等物, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, '乃是 凭著基督 的宝 血,如同 无瑕疵、 无玷污 的羔羊之血。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, ' 基督在 创 世以前是预先被 神知道的,却 在 这末 世 才为 你们 显现。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, '你们 也因著 他,信 那 叫 他 从 死里复活、又 给 他 荣耀的 神,叫 你们的 信心 和 盼望 都 在于  神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, '你们既因 顺从 真理,洁净了 自己的 心,以致 爱弟兄 没有虚假,就当从心里(从心里:有古卷是从 清洁的 心)彼此 切实 相爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, '你们蒙了重生,不是 由于  能坏的 种子,乃是 由于 不能坏的种子,是藉 借著 神 活泼 常存 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, '因为 凡 有血气的,尽都如 草; 他 的 美荣 都像 草 上的花。 草 必枯干, 花 必凋谢; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, ' 惟有主 的 道 是永 存的。 所 传 给 你们 的 福音就是 这 道。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, '所以,你们既除去 一切的 恶毒(或译:阴毒)、 诡诈,并 假善、 嫉妒,和 一切 毁谤的话, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, '就要爱慕 那纯净的 灵 奶,像 才生的 婴孩爱慕奶一样,叫 你们因 此 渐长,以致 得救。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, '你们若 尝过 主 恩 的滋味,就必如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, '主 乃 活 石,固然是 被 人 所弃的,却是 被 神 所拣选、所宝贵的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, '你们来到主面前,也 就像 活 石,被建造 成为灵 宫,作 圣洁的 祭司,藉 借著 耶稣 基督 奉献 神 所悦纳的 灵 祭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, '因为 经 上 说:看哪,我把所拣选、所宝贵 的房角石 安放 在 锡安; 信靠 他 的人必不至于  羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, '所以,他在你们 信的人 就为宝贵, 在那不信的人有话说: 匠人 所弃的 石头 已作了 房角 的头块石头。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, '又说:作了绊脚的 石头, 跌人的 磐石。他们既不顺从, 就在道理 上绊跌(或译:他们绊跌都因不顺从道理);他们这样 绊跌也是 预定的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, '惟有 你们 是被拣选的 族类,是有君尊的 祭司,是圣洁的 国度,是属 神 的子民,要叫 你们宣扬 那召 你们 出 黑暗 入 奇妙 光明 者的美德。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, ' 你们 从前 算不得 子民,现在 却作了 神 的子民; 从前未曾 蒙怜恤,现在 却 蒙了怜恤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, '亲爱的弟兄啊,你们是 客旅, 是寄居的。我劝 你们要禁戒 肉体的 私欲;这 私欲是与 灵魂 争战 的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, '你们 在外邦人 中,应当 品行 端正,叫 那些 毁谤 你们 是 作恶的,因 看见 你们的好 行为,便在 鉴察(或译:眷顾)的日子 归荣耀给 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, '你们为 主的缘故,要顺服 人 的一切 制度,或 是 在上的 君王, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, '或 是 君王所派 罚 恶 赏 善 的臣宰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, '因为 神 的旨意 原 是 要你们行善,可以堵住那糊涂 无知 人 的口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, '你们虽是 自由的,却 不可 藉 借著 自由 遮盖 恶毒(或译:阴毒),总要 作 神 的仆人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, '务要尊敬 众人,亲爱 教中的弟兄,敬畏 神,尊敬 君王。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, '你们作仆人的,凡事 要存敬畏 的心 顺服 主人;不 但 顺服那善良 温和的,就是 那乖僻的 也要顺服。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, '倘若 人 为叫 良心对得住 神,就忍受 冤屈 的苦楚, 这是 可喜爱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, '你们若 因 犯罪 受责打,能忍耐,有什么 可夸的呢?但 你们若 因行善 受苦,能忍耐,这在 神 看 是可喜爱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, '你们蒙召 原是为 此;因 基督 也 为 你们 受过苦,给你们 留下 榜样,叫 你们跟随 他的 脚踪行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, '他 并没 有 犯罪, 口 里 也没 有 诡诈。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, '他 被骂 不 还口;受害 不 说威吓的话,只 将自己交托 讬 那按公义 审判人的主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, '他 被挂在木头 上, 亲 身 担当了 我们的 罪,使我们既然 在罪 上死,就得以在义 上活。因 他受的鞭伤,你们便得了医治。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, ' 你们从前好像 迷路的 羊,如今 却 归 到 你们 灵魂 的牧人 监督了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, ' 你们作妻子 的要顺服 自己的 丈夫;这样,若 有 不信从 道理的丈夫,他们虽然不 听道,也 可以因 妻子 的品行 被感化过来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, '这正是因看见 你们 有贞洁的 品行 和 敬畏的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, '你们 不要 以 外面的 辫 头发, 戴 金饰, 穿 美衣 为妆饰, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, '只要 以 里面 存著 长久 温柔、 安静的 心为妆饰;这在 神 面前 是 极宝贵的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, '因为 古时 仰赖 神 的 圣洁 妇人 正是以此 为妆饰,顺服 自己的 丈夫, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, '就如 撒拉 听从 亚伯拉罕,称 他 为主。你们若行善, 不 因 恐吓 而害怕,便是 撒拉的 女儿了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, ' 你们作丈夫 的也要按情理(原文是知识)和妻子 同住;因她比你软弱(比你软弱:原文作是软弱的 器皿), 与你一同 承受生命 之恩的,所以要敬重她。这样,便叫 你们的 祷告 没有 阻碍。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, '总而言之,你们都 要同心,彼此体恤,相爱如弟兄,存慈怜 谦卑的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, '不 以恶 报 恶, 以辱骂 还 辱骂, 倒要 祝福; 因你们是为 此 蒙召,好叫 你们承受 福气。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, '因为经上说:人若 爱 生命, 愿 享 美福,须要禁止 舌头 不出 恶言, 嘴唇 不 说 诡诈的话; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, '也要 离 恶 行 善,寻求 和睦, 一心追赶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, '因为,主 的眼 看顾 义人; 主的 耳 听 他们的 祈祷。惟有 行 恶的人,主 向他们变 脸。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, '你们若 是 热心行善, 有谁 害 你们呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, ' 你们就是 为 义 受苦,也是有福的。 不要 怕 人的 威吓(的威吓:或译所怕的),也不要 惊慌; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, '只要 心 里 尊主 基督 为圣。有人问 你们 心中 盼望 的缘由,就要常 作准备, 以 温柔、 敬畏 的心回答 各人; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, '存著 无亏的 良心,叫 你们在何事 上被毁谤,就在何事上可以叫那诬赖 你们 在基督 里 有好 品行 的人自觉羞愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, ' 神 的旨意 若是 叫 你们因行善 受苦,总强 如 因行恶受苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, '因 基督 也曾 一次 为 罪 受苦(有古卷:受死),就是义的 代替 不义的,为要 引 我们到 神面前。按著肉体说, 他被治死; 按著灵性说,他复活了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, '他藉 借 这灵 曾 去 传道 给那些在监狱 里 的灵听, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, '就是那 从前 在 挪亚 预备 方舟、 神 容忍 等待 的时候,不信从的人。当时进入方舟,藉 借著 水 得救 的不多, 只有 八个 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, '这水 所表明 的洗礼,现在 藉 借著 耶稣 基督 复活 也 拯救 你们;这洗礼本不在乎 除掉 肉体的 污秽,只 求在 神 面前 有无亏的 良心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, '耶稣 已经进 入 天堂, 在 神 的右边;众天使 和 有权柄的,并 有能力的,都服从了 他。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, '基督 既 在肉身 受苦,你们 也当将这样的 心志 作为兵器,因为 在肉身 受过苦的,就已经与罪 断绝了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, '你们存这样的心,从今以后就可以不从 人的 情欲,只从 神 的旨意 在 世 度 余 馀下的 光阴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, '因为 往日 随从 外邦人 的心意 行 邪淫、恶欲、醉酒、荒宴、群饮,并 可恶 拜偶像的事,时候已经够了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, '他们在这些事 上,见你们 不 与他们同 奔 那放荡 无度的路,就以为怪,毁谤你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, '他们 必在那将 要 审判 活人 死人 的主面前交 帐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, ' 为 此,就是死人 也曾有 福音传给他们,要叫 他们的肉体 按著 人 受审判, 他们的灵性 却靠 神 活著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, ' 万物 的结局 近了。所以,你们要谨慎自守, 警醒 祷告。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, '最要紧的 是 彼此 切实 相爱,因为 爱 能遮掩 许多的 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, '你们要互相 款待,不 发怨言。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, '各人 要照 所得的 恩赐 彼此 服事,作 神 百般 恩赐 的好 管家。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, '若 有 讲道的,要按著 神 的圣言讲;若 有 服事人的,要按著 神 所赐 的力量服事,叫 神 在凡事 上 因 耶稣 基督 得荣耀。原来荣耀、 权能 都是 他的,直到 永永远远。阿们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, '亲爱的弟兄啊,有火炼的试验 临到你们,不要 以为奇怪(似乎 是 遭遇 非常的事), ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, '倒要 欢喜;因为 你们是与基督 一同受 苦, 使你们在他 荣耀 显现 的时候,也可以欢喜 快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, '你们若 为 基督 的名 受辱骂,便是有福的;因为 神 荣耀的 灵 常住 在你们 身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, '你们 中间却 不可 有人 因为 杀人、 偷窃、 作恶、 好管闲 事 而受苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, ' 若 为作 基督徒受苦,却不要 羞耻,倒要 因 这 名 归荣耀给 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, '因为 时候到了,审判 要从 神 的家 起首。 若是 先从 我们 起首,那不信从 神 福音 的人将有何等的 结局呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, ' 若是 义人 仅仅 得救,那不虔敬 和 犯罪的人 将有何地 可站呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, '所以,那照 神 旨意 受苦 的人要一心 为善,将自己 灵魂 交与 那信实 的造化之主。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, ' 我这 作长老、 作 基督 受苦 的见证、 同享 后来所要 显现 之 荣耀的,劝 你们 中间 与我同作长老的人: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, '务要牧养 在 你们 中间 神 的 群羊,按著 神 旨意照管他们;不是 出于 勉强,乃是 出于 甘心;也不是 因为贪财,乃是 出于 乐意; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, '也不是 辖制 所托 讬付你们的,乃是 作 群羊 的榜样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, ' 到了 牧长 显现的时候,你们必得 那 永不衰残的 荣耀 冠冕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, '你们年幼的,也要 顺服 年长的。就是 你们众人 也都要以 谦卑 束腰,彼此顺服;因为 神 阻挡 骄傲的人, 赐 恩 给谦卑的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, '所以,你们要自卑,服在 神 大能的 手下, 到了 时候,他必叫 你们升高。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, '你们 要将一切的 忧虑 卸 给 神,因为 他 顾念 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, '务要谨守,警醒。因为你们 的 仇敌 魔鬼,如同 吼叫的 狮子,遍地游行,寻找 可吞吃 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, '你们要用坚固的 信心 抵挡 他,因为知道 你们 在 世上 的 众弟兄 也是经历 这样的 苦难。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, ' 那 赐诸般 恩典的 神 曾在 基督 里召你们,得享 他 永远的 荣耀,等你们暂 受苦难之后,必要亲自 成全 你们,坚固你们,赐力量给你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, '愿  权能 归给他,直到 永永远远。阿们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, '我略略地 写了这信,托 讬 我所看为 忠心的 兄弟 西拉 转交你们,劝勉你们,又 证明 这 恩是 神 的真 恩。你们务要在 这 恩上站立得住。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, '在 巴比伦 与你们 同蒙拣选 的教会问 你们安。 我 儿子 马可也问你们安。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, '你们要用 爱心 彼此 亲嘴 问安。愿 平安 归与你们 凡 在 基督 里的人!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, '作耶稣 基督 仆人 和 使徒 的西门•彼得 写信给那因 我们的 神 和(有古卷没有和字)救主 耶稣 基督 之义、与我们 同得 一样宝贵 信心的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, '愿 恩惠、 平安,因 你们认识 神 和 我们 主 耶稣,多多地 加给你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, ' 神的神 能 已将一切 关乎 生命 和 虔敬 的事赐给 我们,皆因 我们认识 那用 自己荣耀 和 美德 召 我们 的主。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, '因 此,他已将又宝贵 又 极大 的应许 赐给 我们,叫 我们既脱离 世 上 从情欲 来 的败坏,就得与 神的 性情 有分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, ' 正因这缘故,你们 要分外地 殷勤; 有了信心,又要加上 德行; 有了德行,又要加上 知识; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, ' 有了知识,又要加上 节制; 有了节制,又要加上 忍耐; 有了忍耐,又要加上 虔敬; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, ' 有了虔敬,又要加上 爱弟兄的心; 有了爱弟兄的心,又要加上 爱众人的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, '你们 若 充充足足地 有 这几样,就必使 你们在认识 我们的 主 耶稣 基督 上 不至于  闲 懒 不结果子了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, '人 若 没 有 这几样,就是 眼瞎,只看见近处的,忘了 他 旧日的 罪 已经得了 洁净。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, '所以 弟兄们,应当更加 殷勤,使 你们 所蒙的恩召 和 拣选 坚定不移。你们若 行 这几样,就永不 失脚; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, ' 这样,必叫 你们 丰丰富富地 得以进入 我们 主─ 救主 耶稣 基督 永远的 国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, ' 你们虽然 晓得这些事,并且 在你们已有的 真道 上 坚固,我却要 将 这些事 常常 提醒 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, ' 我以为 应当趁 我还在 这 帐棚 的时候 提醒你们,激发 你们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, '因为 知道 我 脱离 这帐棚 的时候 快到了,正 如 我们 主 耶稣 基督 所指示 我的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, '并且,我要尽心竭力,使 你们 在我 去世 以后 时常 记念 这些事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, ' 我们从前将我们 主 耶稣 基督 的大能 和 他降临 的事告诉 你们,并不是 随从 乖巧捏造的 虚言,乃 是 亲眼见过 他的 威荣。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, ' 他从 父 神 得 尊贵 荣耀的时候,从极大 荣光 之中 有 声音 出来,向他说:「这 是 我的 爱 子,我 所喜悦 的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, ' 我们 同 他 在 圣 山的时候,亲自听见 这 声音 从 天上 出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, '我们并 有 先知更确的 预言,如同 灯 照 在 暗 处。你们在这 预言上留意,直等到 天发亮, 晨星 在你们 心 里 出现的时候,才是 好的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, ' 第一要紧的, 该知道 经上 所有的预言 没有 可 随私意 解说的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, '因为 预言 从来 没有 出于  人 意的,乃是 人 被 圣 灵 感动,说出 神的话来。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, ' 从前 在百姓 中 有 假先知起来, 将来在你们 中间 也必有 假师傅, 私自引进 陷害人的 异端, 连买  他们 的主 他们也不承认,自 取 速速地 灭亡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, ' 将有许多人 随从 他们 邪淫的行为,便叫真 道 因他们 的缘故 被毁谤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, ' 他们因有 贪心,要用捏造的 言语 在你们 身上取利。他们的 刑罚,自古以来 并不 迟延; 他们的 灭亡也必速速来到(原文是也不 打盹)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, ' 就是 天使 犯了罪, 神 也没有 宽容, 曾把他们丢在地狱,交 在黑暗 坑中,等候 审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, '神也 没有 宽容 上古的 世代,曾叫洪水 临到 那不敬虔的 世代,却 保护了 传 义 道的挪亚 一家八口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, '又 判定 所多玛、 蛾摩拉,将二城 倾覆 复,焚烧成灰,作为 后世 不敬虔人 的鉴戒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, '只 搭救了 那常为 恶人 淫 行 忧伤 的义人 罗得。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, '(因为 那义人 住 在他们 中间,看见 听见 他们不法 的事,他的义 心 就天天 伤痛。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, '主 知道 搭救 敬虔的人 脱离 试探, 把不义的人 留 在刑罚 之下,等候审判 的日子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, ' 那些 随 肉身、纵 污秽的 情欲、 轻慢 主治之人的,更是如此。他们胆大 任性,毁谤 在尊位的,也不 知惧怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, '就是 天使,虽然 力量 权能 更大,还不 用 毁谤的话 在主 面前 告 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, '但 这些 人好像 没有灵性,生来 就是畜类,以备 捉拿 宰杀的。他们毁谤 所 不晓得的事,正在 败坏人的时候,自己 必遭遇败坏。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, '行的不义,就得了不义的 工价。这些人喜爱 白昼 宴乐,他们已被玷污,又有 瑕疵,正与你们 一同坐席,就以 自己的 诡诈 为快乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, '他们满 眼 是淫色(原文是淫妇), 止不住 犯罪,引诱 那心不坚固的 人,心中 习惯了 贪婪,正是被咒诅的 种类。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, '他们离弃 正 路,就走差了,随从 比珥 之子巴兰 的路。巴兰就是那 贪爱 不义 之工价的先知, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, '他却 为自己的 过犯 受了 责备;那不能说话的 驴 以 人 言 拦阻 先知 的狂妄。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, '这些 人是 无水 的井, 是 狂风 催逼 的雾气,有墨黑的 幽暗 为他们 存留。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, ' 他们说 虚妄 矜夸的大话,用 肉身的 情欲 和邪淫的事 引诱 那些刚才 脱离 妄行的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, '他们应许 人 得以自由,自己 却作 败坏 的奴仆,因为 人 被谁 制伏 就是谁 的奴仆。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, ' 倘若 他们因 认识 主─ 救主 耶稣 基督,得以脱离 世上 的污秽,后来又 在其中 被缠住、 制伏,他们 末后的景况 就比先前 更不好了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, ' 他们 晓得 义 路,竟背弃了 传给 他们 的圣 命, 倒不如 不 晓得 为妙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, ' 俗语 说得真不错:狗 所吐的,牠 转过来 又吃; 猪 洗净了 又回到 泥里 去滚;这话在他们 身上正合式。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, '亲爱的弟兄啊,我现在 写 给你们 的 是第二封 信。 这两封都是 提醒你们,激发 你们 诚实的 心, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, '叫你们记念 圣 先知 预先 所说的话 和 主 救主 的命令,就是使徒 所传给你们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, ' 第一要紧的,该知道 在 末 世 必有 好讥诮的人 随从 自己的 私欲 出来讥诮说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, '「主 要降临 的应许 在哪里呢?因为 从 列祖 睡了以来,万物 与 起初 创造 的时候仍是 一样。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, ' 他们 故意 忘记,从太古,凭 神 的命 有了 天,并 从 水 而出、 藉 借 水 而成的地。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, '故 此,当时的世界 被水 淹没 就消灭了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, '但 现在的 天 地 还是 凭著那 命 存留,直留 到 不敬虔 之人 受审判 遭沉沦 的日子,用火焚烧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, ' 亲爱的弟兄啊,有一件 事 你们 不可 忘记,就是 主 看 一 日 如 千 年, 千 年 如 一 日。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, '主 所应许的尚未成就, 有人 以为 他是耽延,其实不是 耽延,乃是 宽容 你们,不 愿  有一人 沉沦,乃 愿 人人 都 悔改。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, '但 主 的日子 要像 贼 来到一样。那日,天 必大有响声 废去, 有形质的 都要被烈火 销化,地 和 其 上 的物 都要烧尽了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, '这 一切 既然都要如此 销化, 你们 为人 该当 怎样 圣洁, 怎样敬虔, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, '切切 仰望 神 的日子 来到。在 那日,天 被火烧 就销化了, 有形质的 都要被烈火 镕化。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, '但 我们照 他的 应许,盼望 新 天 新 地,有义 居 在其 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, ' 亲爱的弟兄啊,你们既盼望 这些事,就当殷勤,使自己没有玷污, 无可指摘,安然 见 主; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, '并且 要以我 主 长久忍耐 为得救 的因由,就如 我们 所亲爱的 兄弟 保罗, 照著 所赐给 他 的智慧 写了 信给你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, ' 他一切的 信 上 也 都是讲论 这事。信 中 有些 难明白的,那 无学问、 不坚固 的人强解,如 强解别的 经书一样,就 自 取沉沦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, '亲爱的弟兄啊,你们 既然 预先知道这事,就当防备,恐怕 被恶人 的错谬 诱惑,就从自己 坚固的地步 上坠落。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, '你们却要 在我们 主─ 救主 耶稣 基督 的恩典 和 知识 上 有长进。愿 荣耀 归给他,从 今 直到 永远。阿们!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, '论到 从 起初 原有的 生命 之道,就是我们所 听见、所 看见、 亲 眼 看过、 亲 手 摸过的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '(这 生命 已经显现出来,我们也 看见过,现在又 作见证,将 原 与父 同在、且 显现 与我们 那 永远的 生命 传给 你们。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, '我们将所 看见、 所听见的 传 给你们,使 你们 与 我们 相交。 我们 乃是 与 父 并 他 儿子 耶稣 基督 相交的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, ' 我们 将这些话 写给你们,使你们(有古卷:我们)的喜乐 充足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, ' 神 就是 光, 在他 毫 无 黑暗。 这 是 我们从主 所听见、又报 给你们 的信息。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, '我们若 说 是与 神 相交, 却仍在 黑暗里 行,就是说谎话, 不行 真理了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, '我们若 在光明 中 行,如同 神 在 光明 中,就彼此 相交, 他 儿子 耶稣的 血 也洗净 我们 一切的 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, '我们若 说 自己 无 罪,便是自欺, 真理 不在 我们 心里了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, '我们若 认 自己的罪, 神是 信实的, 是公义的,必要赦免 我们的 罪, 洗净 我们 一切的 不义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, '我们若 说 自己没有 犯过罪,便是以 神 为说谎的, 他的 道 也不在 我们 心里了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, '我 小子们哪,我将这些话 写 给你们,是要叫 你们不 犯罪。 若 有人 犯罪,在 父 那里我们有 一位中保,就是那义者 耶稣 基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, ' 他 为 我们的 罪 作了挽回祭, 不 是单 为 我们的罪,也是 为 普 天下人的罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, ' 我们若 遵守 他的 诫命,就晓得 是认识 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, '人若说「我认识 他」, 却不 遵守 他的 诫命,便是 说谎话的, 真理 也不 在 他 心里了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, '凡 遵守 主 道的,爱 神 的心在他 里 面实在 是完全的。从此,我们知道 我们是 在主 里面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, '人若说 他住在 主 里面,就该 自己 照 主 所行 的去行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, '亲爱的弟兄啊,我写 给你们的,不是 一条新 命令,乃是 你们 从 起初 所受的旧 命令;这旧 命令 就是 你们所听见 的道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, '再者,我写 给你们的,是一条新 命令, 在 主 是 真的, 在 你们也是真的;因为 黑暗 渐渐过去, 真 光 已经 照耀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, '人若说 自己在 光明 中,却 恨 他的 弟兄,他到如今 还是在 黑暗 里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, '爱 弟兄的,就是住在 光明 中, 在 他 并没 有 绊跌的缘由。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, '惟独 恨 弟兄的,是 在黑暗 里, 且在黑暗 里 行, 也不 知道 往哪里 去,因为 黑暗 叫他 眼睛 瞎了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, '小子们哪,我写 信给你们,因为 你们 的罪 藉 借著 主名 得了赦免。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, '父老啊,我写 信给你们,因为 你们认识 那从 起初原有的。少年人哪,我写 信给你们,因为 你们胜了 那恶者。小子们哪,我曾写 信给你们,因为 你们认识 父。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, '父老啊,我曾写 信给你们,因为 你们认识 那从 起初原有的。少年人哪,我曾写 信给你们;因为 你们 刚强, 神 的道 常存 在 你们心里; 你们也胜了 那恶者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, '不 要爱 世界 和 世界上 的事。人 若 爱 世界,爱 父 的心就不 在他 里面了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, '因为,凡 世界上的事,就像肉体的 情欲、 眼目的 情欲,并 今生的 骄傲,都不是 从 父来的,乃 是 从 世界来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, ' 这世界 和 其上的 情欲 都要过去,惟 独遵行 神 旨意的,是永远 常存。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, '小子们哪,如今是 末 时了。 你们曾听见说,那敌基督 的要来; 现在 已经有 好些 敌基督的出来了,从此 我们就知道 如今是 末 时了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, '他们从 我们 中间出去,却 不 是 属 我们的; 若 是 属 我们的,就必仍旧 与 我们同在;他们出去, 显明 都 不 是 属我们的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, ' 你们 从 那圣者 受了 恩膏,并且 知道 这一切的事(或译:都有知识)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, '我写 信给你们,不 是因 你们不 知道 真理,正是 因 你们知道,并且 知道没 有虚谎 是 从 真理出来的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, '谁 是 说谎话的呢? 不是 那不认 耶稣 为 基督的吗?不认 父 与 子的,这 就是 敌基督的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, '凡 不认 子的,就没 有 父;认 子的,连父 也 有了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, '论到你们,务要将那 从 起初 所听见的,常存 在心 里。若 将 从 起初 所听见 的存 在心 里,你们 就 必住 在子 里面,也 必住在父 里面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, ' 主 所应许 我们 的 就是 永 生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, '我将这些 话写给 你们,是指著 那引诱 你们的人说的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, ' 你们 从 主 所受 的恩膏 常存 在你们 心里,并 不 用 人 教训 你们, 自有 主的 恩膏 在凡事 上 教训 你们。 这恩膏是 真的, 不 是 假的; 你们 要按 这恩膏的教训 住 在主 里面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, ' 小子们哪,你们要住 在主 里面。这样,他若 显现,我们就可以 坦然无惧; 当 他 来的时候,在他 面前 也不至于  惭愧。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, '你们若 知道 他是 公义的,就知道 凡 行 公义 之人 都是他 所 生的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, '你看 父 赐给 我们 是何等的 慈爱,使 我们得称为 神 的儿女;我们也 真是他的儿女。世人 所以 不 认识 我们,是因 未曾 认识 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, '亲爱的弟兄啊,我们现在 是 神的 儿女, 将来 如何,还未 显明;但我们知道, 主若 显现,我们必要 像 他,因为 必得见 他的 真体。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, ' 凡 向 他 有 这 指望的,就洁净 自己,像 他 洁净一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, '凡 犯 罪的,就是 违背 律法; 违背律法 就是 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, ' 你们知道 主 曾显现,是要 除掉 人的罪, 在 他 并没 有 罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, '凡 住 在他 里面的,就不 犯罪;凡 犯罪的,是未曾 看见 他,也未曾 认识 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, '小子们哪, 不要被人 诱惑。行 义 的才是 义人,正如 主 是 义的一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, '犯 罪 的是 属 魔鬼,因为 魔鬼 从 起初 就犯罪。 神的 儿子 显现出来,为要 除灭 魔鬼 的作为。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, '凡 从 神 生的,就不 犯 罪,因 神的道(原文是种)存 在 他心里;他也 不 能 犯罪,因为 他是由 神 生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, '从 此 就 显出谁是 神的 儿女, 谁是魔鬼 的儿女。凡 不 行 义 的就不 属 神,不 爱 弟兄 的也是如此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, ' 我们应当彼此 相爱。 这 就是 你们从 起初 所听见 的命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, '不可 像 该隐;他是 属 那恶者, 杀了 他的 兄弟。 为 什么 杀了 他呢?因 自己的 行为 是 恶的, 兄弟的 行为是善的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, ' 弟兄们,世人 若 恨 你们,不要 以为希奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, '我们 因为 爱 弟兄,就晓得 是已经 出 死 入 生了。没有 爱心的,仍住 在死 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, '凡 恨 他 弟兄的,就是 杀人的; 你们晓得 凡 杀人的,没 有 永 生 存 在他 里面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, ' 主 为 我们 舍 命,我们从 此 就知道 何为爱;我们 也 当 为 弟兄 舍 命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, ' 凡 有 世上 财物的, 看见 弟兄 穷乏,却 塞住 怜恤的心,爱 神 的心怎能 存 在 他里面呢? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, '小子们哪,我们相爱,不要 只 在言语 和 舌头上,总要 在行为 和 诚实上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, '从 此 就 知道 我们是 属 真理的,并且 我们的 心在 神 面前 可以安稳。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, ' 我们的 心 若 责备我们, 神 比我们的 心 大, 一切事 没有不知道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, '亲爱的弟兄啊,我们的 心 若 不 责备我们,就可以向 神 坦然无惧了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, '并且 我们一切 所求的,就从 他 得著;因为 我们遵守 他的 命令, 行 他 所喜悦的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, ' 神的 命令 就 是 叫 我们信 他 儿子 耶稣 基督 的名,且 照 他所赐给 我们的 命令 彼此 相爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, ' 遵守 神 命令的,就住 在 神里面, 神 也 住在 他里面。 我们所以 知道 神住 在 我们 里面是因 他所 赐给 我们 的圣灵。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, '亲爱的弟兄啊,一切的 灵,你们不可 都信,总要 试验 那些灵 是 出于  神 的不是,因为 世上 有许多 假先知 已经出来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, '凡 灵 认 耶稣 基督 是成了 肉身 来的,就是 出于  神的;从 此 你们可以认出 神的 灵来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, ' 凡 灵 不 认 耶稣,就不 是 出于  神, 这 是 那敌基督者的灵。你们从前听见 他 要来, 现在 已经 在 世上了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, '小子们哪,你们 是 属 神的,并且 胜了 他们;因为 那 在 你们里面的,比 那在 世界 上的更大。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, '他们 是 属 世界的,所以 论 世界 的事, 世人 也听从 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, '我们 是 属 神的,认识 神 的就听从 我们; 不 属 神 的就不 听从 我们。从 此 我们可以认出 真理的 灵 和 谬妄的 灵来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, '亲爱的弟兄啊,我们应当彼此 相爱,因为 爱 是 从 神来的。 凡 有爱心的,都是由 神 而生,并且 认识 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, '没有 爱心的,就不 认识 神,因为 神 就是 爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, ' 神 差 他 独生 子 到 世间来,使 我们藉 借著 他 得生, 神 爱 我们 的心在 此 就显明了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, '不是 我们 爱 神,乃是 神 爱 我们, 差 他的 儿子 为 我们的 罪 作了挽回祭, 这 就是 爱了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, '亲爱的弟兄啊, 神 既是 这样 爱 我们,我们 也 当 彼此 相爱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, '从来没有 人 见过 神,我们若 彼此 相爱, 神 就住 在我们 里面, 爱 他 的心在我们 里面 得以 完全了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, ' 神将他 的 灵 赐给 我们,从 此 就知道 我们是住 在他 里面,他 也 住在我们 里面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, ' 父 差 子 作世人 的救主; 这是我们 所看见 且 作见证的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, ' 凡 认 耶稣 为 神 儿子的, 神 就住 在他 里面,他 也住在 神 里面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, ' 神 爱 我们的心,我们 也 知道 也 信。 神 就是 爱; 住 在爱 里面的,就是住在 神 里面, 神 也 住在 他 里面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, ' 这样,爱 在我们 里面 得以完全, 我们就可以在 审判 的日子 坦然无惧。因为 他 如何,我们 在 这 世上 也 如何。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, '爱 里 没 有 惧怕;爱 既 完全,就把惧怕 除 去。因为 惧怕 里含著 刑罚, 惧怕 的人在爱 里 未得 完全。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, '我们 爱,因为 神 先 爱 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, '人 若 说「我爱 神」,却 恨 他的 弟兄,就是 说谎话的; 不 爱 他 所 看见 的弟兄,就不 能 爱 没有 看见的 神(有古卷:怎能爱没有看见的 神呢)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, ' 爱 神的,也 当爱 弟兄, 这是 我们从 神 所受 的命令。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, '凡 信 耶稣 是 基督的,都是从 神 而生, 凡 爱 生他之 神的,也 必爱 从 神 生的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, ' 我们若爱 神,又 遵守 他的 诫命,从 此 就知道 我们爱 神的 儿女。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, ' 我们遵守 神的 诫命, 这 就是 爱 他了,并且 他的 诫命 不 是 难守的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, '因为 凡 从 神 生的,就胜过 世界; 使我们胜了 世界 的,就 是 我们的 信心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, ' 胜过 世界 的是 谁呢?不是 那信 耶稣 是 神 儿子的吗? ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, '这 藉 借著 水 和 血 而来的,就是 耶稣 基督;不是 单 用 水,乃是 用 水 又 用 血, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, '并且 有 圣灵 作见证,因为 圣灵 就是 真理。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, ' 作见证的 原来有 三:就是圣灵、 水,与 血,这三样 也 都 归于  一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, '我们既 领受 人 的见证, 神 的见证更该领受(该领受:原文是大)了,因 神的 见证 是 为 他 儿子 作的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, '信 神 儿子的,就有 这见证 在 他心里;不 信 神的,就是将 神 当作 说谎的,因 不 信 神 为 他 儿子 作 的见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, ' 这 见证 就是 神 赐给 我们 永 生;这 永生 也 是 在他 儿子 里面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, '人有了 神的儿子 就有 生命,没 有 神的 儿子 就没 有 生命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, '我将这些 话写给 你们 信奉 神 儿子 之名的人,要叫 你们知道 自己有 永 生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, ' 我们若 照 他的 旨意 求 什么,他就听 我们, 这 是 我们向 他 所存 坦然无惧的心。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, ' 既然 知道 他听 我们 一切 所求的,就知道 我们所求 于  他的,无不得著。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, '人 若 看见 弟兄 犯了 不 至于  死 的罪,就当为他祈求, 神必将生命 赐给 他;有 至于  死 的罪,我不 说 当为 这罪 祈求。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, '凡 不义 的事都是 罪,也 有 不 至于  死 的罪。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, '我们知道 凡 从 神 生的,必不 犯罪, 从 神 生的,必保守 自己(有古卷:那从 神生的必保护他),那恶者 也 就无法 害 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, '我们知道, 我们是 属 神的, 全 世界 都卧 在那恶者 手下。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, '我们也 知道, 神的 儿子 已经来到,且 将智慧 赐给 我们,使 我们认识 那位真实的,我们也 在那位真实的 里面,就是在 他 儿子 耶稣 基督里面。这 是 真 神,也是 永 生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, '小子们哪,你们要自 守,远避 偶像!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, '作长老 的写信给蒙拣选的 太太(或译:教会;下同)和 她的 儿女,就是 我 诚心 所爱的; 不但 我爱, 也是 一切 知道 真理之人所爱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, '爱你们是为真理 的缘故,这 真理存在 我们 里面,也 必 永远 与我们 同在。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, '恩惠、怜悯、平安 从 父 神 和 他 儿子 耶稣 基督 在 真理 和 爱心 上必 常与我们 同在! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, ' 我见 你 的儿女,有照 我们从 父 所受 之命令 遵行 真理的,就甚 欢喜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, ' 太太啊,我现在 劝 你, 我们大家要彼此 相爱。这并不是 我写 一条新 命令 给你,乃是 我们从 起初 所受的命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, ' 我们若照 他 的命令 行, 这 就是 爱。 你们从 起初 所 听见 当行的,就是 这 命令。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, '因为 世上 有许多 迷惑人的 出来,他们 不 认 耶稣 基督 是成了 肉身 来的;这 就是 那迷惑人、 敌基督的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, '你们 要小心,不要 失去你们(有古卷:我们)所做的工,乃要 得著 满足的 赏赐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, '凡 越过 基督 的教训 不 常守著的,就没 有 神;常守 这教训的, 就有 父 又有 子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, '若 有人 到 你们那里, 不是 传 这 教训,不要 接 他 到 家里,也不要 问 他 的安; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, '因为 问 他 安的,就在他的 恶 行 上有分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, '我还有 许多事 要写 给你们,却不 愿 意 用 纸 墨写出来,但 盼望 到 你们那里, 与你们当面 谈论,使 你们 的喜乐 满足。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, '你 那蒙拣选之 姊妹 的儿女 都问你 安。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, '作长老的 写信给亲爱的 该犹,就是 我 诚心 所爱的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, '亲爱的兄弟啊,我愿  你 凡事 兴盛, 身体健壮,正如 你 的灵魂 兴盛一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, ' 有弟兄 来 证明 你 心里存的真理,正如 你 按 真理 而行,我就甚 喜乐。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, '我 听见 我 的儿女们 按 真理 而行,我的喜乐 就没 有 比这个大的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, '亲爱的兄弟啊,凡 你向 作客旅 之弟兄 所行 的都是 忠心的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, ' 他们在教会 面前 证明了 你 的爱;你若配得过 神,帮助他们 往前行,这就好了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, '因他们是为主的名(原文是那名) 出外,对于  外邦人 一无 所取。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, '所以 我们 应该 接待 这样的人,叫 我们与他们 一同为真理 做工。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, '我曾略略地写信 给教会,但 那 在教会中 好为首 的丢特腓 不 接待 我们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, '所以 我若 去,必要提说 他 所行 的事,就是他用恶 言 妄论 我们。还 不 以 此 为足,他自己 不 接待 弟兄,有人愿 意接待,他也 禁止,并且 将接待弟兄的人赶 出 教会。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, '亲爱的兄弟啊,不要 效法 恶,只要 效法善。行善的 属乎 神;行恶的 未曾 见过 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, '低米丢行善,有 众人 给他作见证,又有 真理给他作见证,就是 我们 也 给他作见证。你也 知道 我们的 见证 是 真的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, '我原有 许多事 要写 给你,却 不 愿 意 用 笔 墨 写 给你, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, '但 盼望 快快地 见 你, 我们就当面 谈论。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, '愿 你 平安。众位朋友 都问你 安。请你替我按著 姓名 问众位朋友 安。    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, '耶稣 基督的 仆人, 雅各的 弟兄 犹大,写信给那 被召、在父 神 里 蒙爱、 为耶稣 基督 保守的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, '愿 怜恤、 平安、 慈爱 多多地加 给你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, '亲爱的弟兄啊,我想 尽心 写信 给你们,论 我们 同得 救恩的时候,就 不得不 写信 劝 你们,要为 从前一次 交付 圣徒 的真道 竭力地争辩。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, '因为 有些 人 偷著进来,就是 自古 被定 受 刑罚的,是不虔诚的,将 我们 神的 恩 变作 放纵情欲的机会,并且 不认 独一的 主宰─我们(或译:和我们)主 耶稣 基督。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, ' 从前主 救了 他的百姓 出 埃及 地,后来 就把那些 不 信的 灭绝了。这一切的事,你们 虽然都 知道,我却 仍要 提醒 你们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, '又 有 不 守 本位、 离开  自己 住处 的天使,主用锁链 把他们永远 拘留 在黑暗 里,等候 大 日 的审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, '又如 所多玛、 蛾摩拉 和 周围 城邑的人,也照 他们 一味地 行淫, 随 从 逆性的 情欲,就受 永 火的 刑罚,作为 鉴戒。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, ' 这些 做梦的人 也 像 他们 污秽 身体, 轻慢 主治的, 毁谤 在尊位的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, ' 天使长 米迦勒 为 摩西的 尸首 与魔鬼 争 辩 的时候,尚且不 敢 用 毁谤的话 罪责他,只 说:「主 责备 你吧!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, '但 这些人 毁谤 他们所 不 知道 的。 他们本性 所知道 的事 与那没有灵性的 畜类 一样,在这事 上 竟败坏了自己。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, '他们 有祸了!因为 走了 该隐的 道路,又 为利 往巴兰的 错谬里 直奔,并 在可拉的 背叛中 灭亡了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, '这样的人 在你们的 爱席 上 与你们同吃的时候,正是 礁石(或译:玷污)。他们作牧人,只知喂 𫗭养 自己,无所惧怕;是没有雨的 云彩,被 风 飘荡;是秋天 没有果子的 树,死 而又死,连根被拔出来; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, '是海里的 狂 浪,涌出自己 可耻的 沫子来;是流荡的 星,有墨黑的 幽暗 为他们 永远 存留。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, ' 亚当 的七世 孙 以诺,曾预言 这些人 说:「看哪,主 带著 他的 千万 圣者 降临, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, '要在众人 身上 行 审判, 证实 那一切 不敬虔的人 所 妄行 一切 不敬虔 的事,又 证实 不敬虔之 罪人 所 说 顶撞 他的 刚愎话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, '这些人 是 私下议论,常发怨言的,随从 自己的 情欲 而行, 口中 说 夸大的话,为 得便宜 谄媚 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, ' 亲爱的弟兄啊,你们 要记念 我们 主 耶稣 基督之 使徒 从前所 说 的 话。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, ' 他们曾对你们 说过, 末 世 必有 好讥诮的人 随从 自己 不敬虔的 私欲 而行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, '这 就是 那些 引人结党、属乎血气、没 有 圣灵的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, '亲爱的弟兄啊,你们 却 要在 至圣的 真道 上造就 自己,在圣 灵 里 祷告, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, '保守 自己常在 神的 爱 中,仰望 我们 主 耶稣 基督的 怜悯,直到 永 生。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, ' 有些人存疑心,你们 要怜悯 他们; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, ' 有些人你们要从 火 中抢出来,搭救 他们; 有些人你们要存 惧怕 的心怜悯 他们,连 那 被 情欲 沾染 的衣服 也当厌恶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, ' 那 能 保守 你们 不失脚、 叫你们无瑕无疵、 欢欢喜喜 站在 他 荣耀 之前 的我们的 救主─独一的 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, '愿 荣耀、威严、能力、 权柄,因 我们的 主 耶稣 基督归与他, 从 万古以前 并 现今,直到 永永远远。阿们!    ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, '耶稣 基督 的启示,就是 神 赐 给他,叫他将必要 快成 的事 指示 他的 众仆人。 他就差遣 使者 晓谕 他的 仆人 约翰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, '约翰便将 神 的道 和 耶稣 基督 的见证,凡 自己所看见 的都证明出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, '念 这书 上预言 的和 那些听见 又 遵守 其中 所记载的,都是有福的,因为 日期 近了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, '约翰 写信给 亚细亚 的七 个教会。但愿 从 那昔在、 今在、 以后永在的 神,和 他 宝座 前 的七 灵, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, '并 那诚实 作见证的、从死 里 首先复活、 为世上 君王 元首 的耶稣 基督,有恩惠、 平安 归与你们!他爱 我们, 用 自己的 血 使我们 脱离(有古卷:洗去)罪恶, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, '又 使 我们 成为国民, 作他 父 神 的祭司。但愿 荣耀、 权能 归给他,直到 永永远远。阿们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, '看哪,他驾 云 降临! 众 目 要看见 他,连 刺 他 的人也要看见他; 地上的 万 族 都要因 他 哀哭。这话是真实的。阿们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, '主 神 说:「我 是 阿拉法, 我是俄梅戛(阿拉法,俄梅戛:是希腊字母首末二字), 是昔在、今在、 以后永在的 全能者。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, '我─约翰 就是 你们的 弟兄,和 你们在 耶稣 的患难、 国度、 忍耐 里一同有分,为 神 的道,并 为给耶稣 作的见证,曾 在 那名叫 拔摩 的海岛上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, '当 主 日,我被 圣灵 感动, 听见 在我 后面 有大 声音 如 吹号,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, '「你所看见 的 当写 在书 上, 达与 以弗所、 士每拿、 别迦摩、 推雅推喇、 撒狄、 非拉铁非、 老底嘉 那 七个 教会。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, ' 我转过身来,要看 是谁 发声 与 我 说话;既 转过来,就看见 七个 金 灯台。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, ' 灯台 中间 有一位好像 人 子,身穿长衣,直垂到脚, 胸 间 束著 金 带。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, ' 他的 头 与 发 皆白,如 白羊毛, 如 雪; 眼目 如同 火 焰; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, ' 脚 好像 在炉 中 锻炼 链 𫔀 光明的铜; 声音 如同 众 水 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, ' 他 右 手 拿著 七 星, 从 他 口中 出来 一把两刃的 利 剑; 面貌 如同 烈日 放光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, ' 我一看见,就仆倒 在 他 脚前,像死了 一样。 他 用右 手按著 我,说:「不要 惧怕!我 是 首先的, 我是末后的, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, '又 是那存活的; 我曾 死过, 现在又 活了,直活到 永永远远;并且 拿著 死亡 和 阴间 的钥匙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, '所以 你要把所 看见的,和 现在的 事,并 将来 必成的 事,都写出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, '论到你所 看见、在我 右手 中 的七 星 和 七个 金 灯台 的奥秘,那七 星 就是 七个 教会 的使者, 七 灯台 就是 七个 教会。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, '「你要写信 给 以弗所 教会 的使者, 说:『那 右手 拿著 七 星、 在 七个 金 灯台 中间 行走的,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, '我知道 你 的行为、 劳碌、 忍耐,也 知道你不 能 容忍 恶人。你也 曾试验 那自 称 为使徒 却 不 是使徒的, 看出 他们 是假的来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, ' 你也能 忍耐, 曾为 我的 名 劳苦, 并不 乏倦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, '然而 有 一件事我要责备 你,就是 你 把起初的 爱心 离弃了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, '所以,应当回想 你是从哪里 坠落的,并要 悔改, 行 起初 所行的事。 你若 不 悔改,我就临到 你那里, 把你的 灯台 从 原 处 挪去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, '然而 你还有一件 可取的事,就是 你恨恶 尼哥拉一党人 的行为,这 也是我 所恨恶的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, '圣灵 向众教会 所说 的话,凡有 耳的,就应当听! 得胜的,我必将 神 乐园 中生命 树 的果子 赐给 他吃。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, '「 你要写信给 士每拿 教会 的使者, 说:『那首先的、 末后的、 死过 又 活的,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, '我知道 你的 患难, 你的贫穷(你却 是 富足的),也 知道那 自称 是 犹太人 所说的毁谤话,其实 他们不 是犹太人,乃是 撒但 一会的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, ' 你将要 受的苦 你不用 怕。 魔鬼 要把 你们 中间 几个人下在 监 里,叫 你们被试炼, 你们必受 患难 十 日。你务要 至 死 忠心, 我就赐给 你 那生命 的冠冕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, '圣灵 向众教会 所说 的话,凡有 耳的,就应当听!得胜的,必不 受 第二次 死 的害。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, '「 你要写信 给 别迦摩 教会 的使者, 说:『那有 两刃 利 剑的,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, '我知道 你的居所,就是 有撒但 座位之处; 当 我 忠心的 见证人 安提帕 在你们 中间、撒但 所住 的地方 被杀 之时,你还坚守 我的 名, 没有 弃绝 我的 道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, '然而,有 几件事 我要责备 你:因为 在你那里 有 人服从了 巴兰 的教训;这 巴兰曾教导 巴勒 将绊脚石 放在 以色列 人 面前,叫他们吃 祭偶像之物, 行奸淫的事。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, '你 那里也有人 照样 服从了 尼哥拉一党人 的教训。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, '所以,你当悔改;若不悔改,我就快 临到 你那里, 用 我 口中 的剑 攻击 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, '圣灵 向众教会 所说 的话,凡有 耳的,就应当听!得胜的,我必将那隐藏的 吗哪 赐给 他,并 赐 他 一块白 石, 石 上 写著 新 名; 除了 那领受的以外,没有人 能认识。』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, '「 你要写信 给 推雅推喇 教会 的使者, 说:『那 眼目 如 火 焰、 脚 像 光明铜的 神 之子说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, '我知道 你的 行为、 爱心、 信心、 勤劳、 忍耐,又 知道你 末后 所行的善事,比起初 所行的更多。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, '然而,有 一件事我要责备 你,就是 你容让 那 自 称 是先知 的妇人 耶洗别 教导 我的 仆人, 引诱 他们行奸淫, 吃 祭偶像之物。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, ' 我曾给 她 悔改 的机会,她却 不 肯 悔改 她的 淫行。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, '看哪,我要叫 她 病卧在 床。 那些与 她 行淫的人,若不 悔改 所行的,我也要叫他们 同受 大 患难。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, '我又 要杀 死 她的党类(原文是儿女),叫 众 教会 知道, 我 是 那 察看 人肺腑心肠的,并 要照 你们的 行为 报应 你们 各人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, '至于  你们 推雅推喇 其余 馀的人,就是一切 不 从 那 教训、不 晓得 他们素常 所说 撒但 深奥之理的人,我告诉你们,我不 将别的 担子 放在 你们 身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, '但 你们已经有的,总要持守,直等到 我 来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, '那 得胜 又 遵守 我 命令 到 底的,我要赐给 他 权柄 制伏 列国; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, ' 他必用 铁 杖 辖管(辖管:原文是牧)他们,将他们如同 窑户 的瓦器 打得粉碎,像 我 从 我 父 领受的权柄一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, '我又要 把晨 星 赐给 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, '圣灵 向众教会 所说 的话,凡有 耳的,就应当听!』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, '「 你要写信 给 撒狄 教会 的使者, 说:『那有 神 的七 灵 和 七 星的,说:我知道 你的 行为, 按 名 你是活的,其实 是 死的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, '你要 警醒, 坚固 那剩下 将要衰微(原文是死)的;因 我见 你的 行为,在我 神 面前,没有 一样是完全的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, '所以 要回想 你是怎样 领受、 怎样听见的,又要 遵守,并要 悔改。 若 不 警醒,我必临 到你那里,如同 贼一样。 我几 时 临 到,你也决不能 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, '然而 在 撒狄,你还有 几 名 是未曾 污秽 自己 衣服的, 他们要穿 白 衣与我 同 行,因为 他们是 配得过的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, '凡得胜的 必这样穿 白 衣,我也 必不 从 生命 册 上涂抹 他的 名;且 要在我 父 面前,和 我父 众使者 面前,认 他的 名。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, '圣灵 向众教会 所说 的话,凡有 耳的,就应当听!』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, '「 你要写信 给 非拉铁非 教会 的使者, 说:『那圣洁、真实、拿著 大卫 的钥匙、开 了 就 没有人 能关、 关了 就 没有人 能开 的,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, '我知道 你的 行为, 你略有 一点 力量,也 曾遵守 我的 道, 没有 弃绝 我的 名。看哪,我在你 面前 给 你一个敞开 的 门, 是无人 能 关 的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, ' 那 撒但 一会的, 自称 是 犹太人, 其实不 是犹太人,乃是 说谎话的, 我要使 他们 来, 在你 脚 前 下拜,也 使 他们知道 我 是已经爱 你了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, ' 你既遵守 我 忍耐 的道,我 必在 普 天下人 受试炼的时候,保守 你 免去你的试炼。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, ' 我必快 来,你要持守 你所有的, 免得人 夺去 你的 冠冕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, ' 得胜的,我要叫他在我 神 殿 中 作 柱子, 他也必不 再 从那里 出去。我又要 将我 神 的名 和 我 神 城 的名(这 城就是 从 天上、从 我 神 那里降下来 的新 耶路撒冷),并 我的 新 名,都写在 他 上面。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, '圣灵 向众教会 所说 的话,凡有 耳的,就应当听!』」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, '「 你要写信 给 老底嘉 教会 的使者, 说:『那为阿们的,为诚信 真实 见证的,在 神 创造万物 之上为元首的,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, '我知道 你的 行为, 你 也不 冷 也不 热;我巴不得 你 或冷 或 热。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, ' 你既 如温水, 也不 冷 也不 热,所以我必 从 我 口中 把你 吐出去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, ' 你说: 我是 富足, 已经发了财, 一样都不缺;却 不 知道 你 是 那困苦、 可怜、 贫穷、 瞎眼、 赤身的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, '我劝 你 向 我 买  火 炼 的金子,叫 你富足;又 买 白 衣 穿上,叫 你 赤身 的羞耻 不 露出来;又 买 眼药 擦 你的 眼睛,使 你能看见。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, '凡 我所疼爱的,我 就责备 管教他;所以 你要发热心,也要 悔改。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, '看哪,我站 在门 外 叩门,若有 听见 我 声音 就 开  门的, 我要进 到 他那里去, 我与 他,他 与 我 一同坐席。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, ' 得胜的,我要赐 他在我 宝座 上 与我 同 坐,就如 我 得了胜, 在我 父 的 宝座 上 与他同 坐一般。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, '圣灵 向众教会 所说 的话,凡有 耳的,就应当听!』」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, '此 后,我观看, 见 天上 有门 开 了。 我初次 听见 好像 吹号 的声音,对 我 说:「你上到这里 来, 我要将以后 必 成 的事 指示 你。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, '我立刻 被 圣灵 感动, 见有 一个宝座 安置 在 天上,又有 一位坐 在宝座 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, ' 看 那坐著的,好像 碧玉 和 红宝石;又有 虹 围著 宝座, 好像 绿宝石。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, ' 宝座 的周围 又有二十 四 个座位; 其上 坐著 二十 四 位长老,身穿 白 衣, 头 上 戴著金 冠冕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, ' 有闪电、 声音、 雷轰 从 宝座 中发出;又有 七盏 火 灯 在宝座 前 点著;这 七灯就是 神 的七 灵。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, ' 宝座 前 好像 一个玻璃 海,如同 水晶。 宝座 中 和 宝座 周围 有四个 活物,前 后 遍体都满了 眼睛。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, ' 第一个 活物 像 狮子, 第二个 像 牛犊, 第三个 脸面 像 人, 第四个 像 飞 鹰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, ' 四 活物 各 有 六个 翅膀, 遍体内外 都满了 眼睛。 他们昼 夜 不 住地 说:圣哉!圣哉!圣哉!主 神 是昔在、 今在、 以后永在的 全能者。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, ' 每逢 四活物 将荣耀、 尊贵、 感谢 归给 那坐 在宝座 上、 活 到 永永远远者的时候, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, '那二十 四 位长老 就俯伏 在坐 宝座 的面前 敬拜 那活 到 永永远远的,又 把他们的 冠冕 放 在宝座 前,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, '我们的主, 我们的 神,你是 配 得 荣耀、 尊贵、 权柄的;因为 你 创造了 万物,并且 万物是因 你的 旨意 被创造 而 有的。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, ' 我看见 坐 宝座 的右手 中 有书卷,里 外 都写著字,用七 印 封严了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, '我又 看见 一位大力的 天使 大 声 宣传说:「有谁 配 展开  那书卷, 揭开  那 七印呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, ' 在 天上、 地 上、 地 底下,没有 能 展开 、 能观看 那 书卷的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, '因为 没有 配 展开 、 配观看 那 书卷的,我就 大 哭。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, ' 长老 中 有一位 对我 说:「不要 哭!看哪,犹大 支派 中 的狮子,大卫 的根,他已得胜,能以展开  那书卷, 揭开 那 七 印。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, '我又 看见 宝座 与 四 活物,并 长老 之中 有羔羊 站立,像是 被杀过的,有 七 角 七 眼,就 是 神 的七 灵,奉差遣 往 普 天下去的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, ' 这羔羊前来, 从 坐 宝座 的右手 里拿了书卷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, ' 他既 拿了 书卷,四 活物 和 二十 四 位长老 就俯伏 在羔羊 面前,各 拿著 琴 和 盛满了 香 的金 炉;这 香就是 众圣徒 的祈祷。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, ' 他们唱 新 歌,说:你 配 拿 书卷, 配揭开  七印;因为 你曾被杀, 用 自己的 血 从 各 族、 各方、 各民、 各国 中买 了人来,叫他们归于  神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, '又 叫 他们 成为国民, 作祭司 归于  神, 在地 上 执掌王权。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, '我又 看见 且 听见,宝座 与 活物 并 长老 的周围 有许多 天使 的声音; 他们的 数目 有 千千万万, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, '大 声 说:曾被杀的 羔羊 是 配 得 权柄、 丰富、 智慧、 能力、 尊贵、 荣耀、 颂赞的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, '我又 听见 在天 上、 地 上、 地 底下、 沧海 里,和 天地间一切所有 被造之物,都说:但愿 颂赞、 尊贵、 荣耀、 权势 都归给坐 宝座 的和 羔羊,直到 永永远远! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, ' 四 活物 就说:「阿们!」 众长老 也俯伏 敬拜。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, ' 我看见 羔羊 揭开  七 印 中 第一印 的时候,就 听见 四 活物 中 的一个活物,声音 如 雷,说:「你来!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, '我就 观看, 见 有一匹白 马; 骑 在马 上的,拿著 弓,并 有冠冕 赐给 他。 他便出来,胜了 又要 胜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, ' 揭开  第二 印 的时候,我听见 第二个 活物 说:「你来!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, '就 另有 一匹马 出来,是红的, 有权柄给了 那 骑 马的,可以从 地上 夺去 太平, 使 人彼此 相杀;又 有一把大 刀 赐给 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, ' 揭开  第三 印 的时候,我听见 第三个 活物 说:「你来!」我就 观看, 见 有一匹黑 马; 骑 在马 上的, 手 里 拿著 天平。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, ' 我听见 在 四 活物 中 似乎 有声音 说:「一钱银子 买 一升 麦子, 一钱银子 买 三 升 大麦; 油 和 酒 不可 糟蹋。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, ' 揭开  第四 印 的时候,我听见 第四个 活物 说:「你来!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, '我就 观看, 见 有一匹灰色 马; 骑 在马 上的, 名字 叫作死,阴府 也 随著 他; 有权柄 赐给 他们,可以用 刀剑、 饥荒、 瘟疫(或译:死亡)、 野兽,杀害 地上 四分之一的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, ' 揭开  第五 印 的时候,我看见 在祭坛 底下,有为 神 的道、并 为 作见证 被杀 之人的灵魂, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, ' 大 声 喊著 说:「圣洁 真实 的主啊,你不 审判 住 在 地 上的人, 给我们 伸流血 的冤,要等到 几时呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, '于 是 有白 衣 赐给 他们 各人;又有 话对他们 说, 还要 安息 片时,等著 一同作仆人的 和 他们的 弟兄 也像 他们 被 杀,满足了数目。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, ' 揭开  第六 印 的时候,我又 看见 地 大 震动, 日头 变 黑 像 毛 布, 满 月 变 红像 血, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, ' 天上的 星辰 坠落 于  地,如同 无花果树 被 大 风 摇动,落下 未熟的果子一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, ' 天 就挪移,好像 书卷 被卷起来; 山岭 海岛 都被挪移 离开  本位。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, ' 地上 的君王、 臣宰、 将军、 富户、 壮士,和 一切 为奴的、 自主的,都藏 在 山洞 和 岩石 穴里, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, ' 向山 和 岩石 说:「倒 在我们 身上吧! 把我们 藏起来,躲避 坐 宝座 者的面目 和 羔羊 的忿怒; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, '因为 他们 忿怒 的大 日 到了, 谁 能 站得住呢?」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, '此 后,我看见 四位 天使 站 在 地 的四 角,执掌 地上 四方的 风,叫风 不 吹 在地 上、 海 上,和 树 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, '我又 看见 另有 一位天使,从 日出之地 上来,拿著 永生 神 的印。 他就向那 得著权柄 能伤害 地 和 海 的四位 天使 大 声 喊著 说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, '「地 与 海 并 树木,你们不可 伤害,等 我们印了 我们 神 众仆人 的 额。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, ' 我听见 以色列 人 各 支派 中 受印 的数目 有十四万四千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, '犹大 支派 中 受印的 有一万二千;流便 支派 中 有一万二千;迦得 支派 中 有一万二千; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, '亚设 支派 中 有一万二千;拿弗他利 支派 中 有一万二千;玛拿西 支派 中 有一万二千; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, '西缅 支派 中 有一万二千;利未 支派 中 有一万二千;以萨迦 支派 中 有一万二千; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, '西布伦 支派 中 有一万二千;约瑟 支派 中 有一万二千;便雅悯 支派 中 受印的 有一万二千。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, '此 后,我观看, 见 有许多的人, 没有人 能 数过来,是从 各 国、 各族、 各民、 各方来的,站 在宝座 和 羔羊 面前,身穿 白 衣, 手 拿 棕树枝, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, ' 大 声 喊著 说:「愿 救恩 归与 坐 在宝座 上 我们的 神,也 归与羔羊!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, ' 众 天使 都站 在宝座 和 众长老 并 四 活物 的周围, 在宝座 前, 面 伏 于 地, 敬拜 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, '说:阿们!颂赞、 荣耀、 智慧、 感谢、 尊贵、 权柄、 大力 都归与我们的 神,直到 永永远远。阿们! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, ' 长老 中 有一位 问我 说:「这些 穿 白 衣 的是 谁? 是从哪里 来的?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, ' 我对他 说:「我 主,你 知道。」 他向我 说:「这些人 是 从 大 患难 中出来的, 曾用 羔羊 的血 把 衣裳 洗 白净了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, '所以,他们在 神 宝座 前, 昼 夜 在他 殿 中 事奉 他。 坐 宝座 的要用帐幕覆 复庇 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, '他们不 再 饥,不 再 渴;日头 和 炎热 也必不 伤害 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, '因为 宝座 中 的羔羊 必牧养 他们, 领 他们 到 生命 水 的泉源; 神 也必 擦去 他们一切的 眼泪。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, ' 羔羊揭开  第七 印 的时候, 天上 寂静 约有 二刻。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, ' 我看见 那 站在 神 面前 的七位 天使, 有七枝 号 赐给 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, ' 另有一位 天使,拿著 金 香炉 来, 站 在祭坛 旁边。 有许多 香 赐给 他, 要和众 圣徒 的祈祷 一同献 在宝座 前 的金 坛 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, ' 那香 的烟 和众圣徒 的祈祷 从 天使的 手中 一同升到 神 面前。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, ' 天使 拿著 香炉, 盛满了 坛 上的火, 倒 在地 上; 随有 雷轰、大声、 闪电、 地震。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, ' 拿著 七枝 号 的七位 天使 就预备 要 吹。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, ' 第一位 天使吹号,就 有 雹子 与 火 搀著 血 丢 在地 上; 地的 三分之一 和 树 的三分之一 被烧了, 一切的 青 草 也被烧了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, ' 第二位 天使 吹号,就 有仿佛 火 烧著的 大 山 扔 在海 中; 海 的三分之一 变成 血, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, ' 海 中 的活物 死了 三分之一, 船只 也坏了 三分之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, ' 第三位 天使 吹号,就 有烧著的 大 星,好像 火把 从 天上 落下来, 落在 江河 的三分之一 和 众水 的泉源 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, '( 这星 名 叫「茵𫈟」。) 众水 的三分之一 变为 茵𫈟,因 水 变苦, 就 死了 许多 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, ' 第四位 天使 吹号, 日头 的三分之一、 月亮 的三分之一、 星辰 的三分之一 都被击打,以致 日月星的 三分之一 黑暗了, 白昼 的 三分之一 没有 光,黑夜 也是 这样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, '我又 看见 一个 鹰 飞 在空 中,并 听见 牠大 声 说:「 三位 天使 要 吹 那其余 馀的 号。你们住在地 上 的民,祸哉!祸哉!祸哉!」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, ' 第五位 天使 吹号,我就 看见 一个星 从 天 落到 地 上, 有无底 坑 的钥匙 赐给 它。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, ' 它开 了 无底 坑,便有 烟 从 坑里 往上冒,好像 大 火炉 的烟; 日头 和 天空 都因 这烟 昏暗了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, ' 有蝗虫 从 烟 中出来,飞到地 上; 有能力 赐给 牠们,好像 地上 蝎子 的 能力一样, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, '并且 吩咐 牠们说,不可 伤害 地上 的草 和 各样 青物,并 一切 树木,惟独 要伤害 额 上 没 有 神 印记 的人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, '但 不 许 蝗虫 害死 他们,只叫 他们受痛苦 五个 月。 这 痛苦 就像 蝎子 螫 人 的痛苦一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, ' 在 那些 日子,人 要求 死, 决不 得 死; 愿 意 死, 死 却远避 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, ' 蝗虫的 形状,好像 预备 出战 的 马一样, 头 上 戴的好像 金 冠冕, 脸面 好像 男人的 脸面, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, ' 头发 像 女人 的头发, 牙齿 像 狮子的牙齿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, ' 胸前有 甲,好像 铁 甲。 牠们 翅膀 的声音,好像 许多 车 马 奔跑 上 阵 的声音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, ' 有 尾巴 像 蝎子, 尾巴 上 的毒钩 能 伤 人 五个 月。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, '有 无底坑的 使者 作 牠们的 王,按著希伯来话, 名叫 亚巴顿, 希腊话, 名叫 亚玻伦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, '第一样 灾祸 过去了, 还有 两样 灾祸 要来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, ' 第六位 天使 吹号, 我就听见 有 声音 从 神 面前 金 坛 的四 角出来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, '吩咐那吹 号 的第六位 天使,说:「把那 捆绑 在 幼发拉底 大 河 的四个 使者 释放了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, ' 那四个 使者 就被释放;他们 原是预备好了,到 某年 某月 某日 某时,要 杀 人 的三分之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, '马军 有二万万; 他们的 数目 我听见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, ' 我在异象 中 看见 那些马 和 骑 马的,骑马的胸前有 甲 如火,与 紫玛瑙 并 硫磺。 马 的头 好像 狮子 头, 有火、 有烟、 有硫磺 从 马的 口中 出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, ' 口中 所出来 的 火 与 烟 并 硫磺, 这 三样 灾 杀了 人 的三分之一。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, ' 这马 的能力 是 在 口 里 和 尾巴 上;因 这 尾巴 像 蛇,并且有 头 用以 害人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, ' 其余 馀 未曾 被 这些 灾 所杀 的人 仍旧不 悔改 自己 手 所做的,还是 去拜 鬼魔 和 那些 不 能 看、不能 听、不能 走,金、 银、 铜、 木、 石 的偶像, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, '又 不 悔改 他们 那些凶杀、 邪术、 奸淫、 偷窃的事。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, '我又 看见 另有一位 大力的 天使 从 天 降下,披著 云彩, 头 上 有虹, 脸面 像 日头, 两脚 像 火 柱。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, ' 他 手 里 拿著 小书卷,是展开 的。 他 右 脚 踏 海, 左 脚踏地, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, ' 大 声 呼喊,好像 狮子 吼叫。 呼喊 完了,就有七 雷 发 声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, ' 七 雷 发 声之后,我正要 写出来,就 听见 从 天上 有声音 说:「七 雷 所说的,你要封上, 不可 写出来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, ' 我所看见 的那 踏 海 踏 地 的天使 向 天 举起 右 手来, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, ' 指著 那 创造 天 和 天上之物, 地 和 地上之物, 海 和 海中之物,直活 到 永永远远的,起誓说:「 不再 有 时日了(或译:不再耽延了)。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, '但 在 第七位 天使 吹号 发声 的时候, 神 的奥秘 就成全了,正如 神所传给 他 仆人 众先知的佳音。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, ' 我先前从 天上 所听见 的那 声音 又 吩咐 我 说:「你去,把那 踏 海 踏 地 之天使 手 中 展开  的 小书卷 取过来。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, '我就 走 到 天使那里,对他 说:「请你把小书卷 给 我。」 他对我 说:「你拿著 吃 尽了,便 叫你 肚子 发苦,然而 在你 口 中 要 甜 如 蜜。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, ' 我从 天使 手中 把小书卷 接过来, 吃 尽了, 在我 口 中 果然 甜 如 蜜, 吃了 以后, 肚子 觉得发苦了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, '天使(原文是他们)对我 说:「你 必 指著 多 民、 多国、 多方、 多王 再 说预言。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, ' 有一根苇子 赐给 我,当作 量度的杖;且有话说:「起来!将 神 的殿 和 祭坛,并 在殿 中 礼拜 的人都量一量。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, '只是 殿 外 的 院子 要留下 不用 量,因为 这是给了 外邦人的; 他们要践踏 圣 城 四十 二 个月。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, ' 我要使 我 那两个 见证人, 穿著 毛衣,传道 一千 二百 六十 天。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, '他们 就是 那两棵 橄榄树, 两个 灯台,立 在世界 之主 面前的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, ' 若 有人 想要 害 他们,就有火 从 他们 口中 出来, 烧灭 仇敌。 凡 想要 害 他们 的都必 这样 被杀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, '这 二人有 权柄,在 他们 传道 的日子 叫天 闭塞 不 下雨;又 有 权柄 叫 水 变 为 血,并且 能随时 随 意 用各样的 灾殃 攻击 世界。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, ' 他们 作完 见证 的时候,那从 无底坑 里上来 的兽 必与 他们 交 战 ,并且 得胜, 把他们 杀了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, ' 他们的 尸首 就倒在大 城 里的街 上;这 城按著灵意 叫 所多玛,又叫 埃及,就是 他们的 主 钉十字架 之处。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, ' 从 各民、 各族、 各方、 各国中,有人观看 他们的 尸首 三 天 半,又 不 许 把 尸首 放 在坟墓 里。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, ' 住 在地 上 的人就为 他们 欢喜 快乐, 互相 餽送 礼物,因 这 两位 先知 曾叫住 在地 上 的人受痛苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, ' 过了 这三 天 半,有生 气 从 神 那里进入 他们里面, 他们就 站起来; 看见 他们 的人甚是 害怕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, ' 两位先知听见 有大 声音 从 天上来,对他们 说:「上到这里 来。」 他们就驾著 云 上了 天,他们的 仇敌 也 看见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, ' 正在 那 时候,地 大 震动,城 就 倒塌了 十分之一, 因 地震 而死的 有七 千 人; 其余 馀的 都恐惧, 归 荣耀 给天上的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, '第二样 灾祸 过去, 第三样 灾祸 快 到了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, ' 第七位 天使 吹号, 天 上 就有 大 声音 说:世上的 国 成了 我 主 和 主基督的国; 他要作王,直到 永永远远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, '在 神 面前, 坐 在自己 位 上 的二十 四 位长老,就 面 伏 于 地, 敬拜 神, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, '说: 昔在、今在 的主 神─全能者啊,我们感谢 你!因 你 执掌 大 权 作王了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, ' 外邦 发怒,你的 忿怒 也 临到了;审判 死人 的时候 也到了。你的 仆人 众先知 和 众圣徒, 凡敬畏 你 名的人,连大 带小 得 赏赐 的时候也到了。你败坏 那些败坏 世界 之人的时候也就到了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, '当时, 神 天 上 的殿 开 了, 在他 殿 中 现出 他的 约 柜。 随后有 闪电、 声音、 雷轰、 地震、 大 雹。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, ' 天 上 现出 大 异象来:有一个妇人 身披 日头, 脚 踏 月亮, 头 戴 十二 星 的冠冕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, ' 她 怀了孕,在生产 的艰难 中疼痛 呼叫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, ' 天 上 又 现出 异象来: 有一条大 红 龙, 七 头 十 角; 七头 上 戴著七个 冠冕。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, ' 牠的 尾巴 拖拉著 天上 星辰 的三分之一, 摔 在 地上。龙 就 站 在那 将要 生产 的妇人 面前,等她生产 之后,要 吞吃 她的 孩子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, ' 妇人生了 一个男 孩子, 是 将来要用 铁 杖 辖管(辖管:原文是牧)万 国的; 她的 孩子 被提 到 神 宝座那里去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, ' 妇人 就逃 到 旷野,在那里 有 神 给她预备 的地方,使 她 被养活 一千 二百 六十 天。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, ' 在天 上 就有了 争战 。米迦勒 同 他的 使者 与 龙 争战 ,龙 也 同 牠的 使者 去争战 , ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, '并 没有 得胜,天 上 再 没有 牠们的 地方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, ' 大 龙 就是那古 蛇,名叫 魔鬼,又叫 撒但, 是迷惑 普 天下的。牠被摔 在地 上,牠的 使者 也 一同 被摔下去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, ' 我听见 在天 上 有大 声音 说:「我 神 的救恩、 能力、 国度,并 他 基督 的权柄,现在 都来到了!因为 那 在我们 神 面前 昼 夜 控告 我们 弟兄 的,已经被摔下去了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, ' 弟兄 胜过 牠,是因 羔羊 的血 和 自己 所见证 的道。 他们 虽至于  死,也不 爱惜 性命。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, '所以,诸天 和 住 在其 中的,你们都快乐吧!只是地 与 海 有祸了!因为 魔鬼 知道 自己的 时候 不多,就 气忿忿地 下到 你们 那里去了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, ' 龙 见 自己被摔 在地 上,就逼迫 那 生 男 孩子的妇人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, '于 是 有大 鹰 的两个 翅膀 赐给 妇人,叫 她能飞 到 旷野,到 自己的 地方,躲避 那蛇;她在那里 被养活 一载 二载 半 载。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, ' 蛇 就在妇人 身后,从 口中 吐出 水来,像 河一样,要 将 妇人 冲去。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, '地 却 帮助 妇人, 开  口 吞了 从 龙 口 吐出来的水(原文是河)。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, ' 龙 向 妇人 发怒, 去 与 她 其余 馀的 儿女 争战 ,这儿女就是 那守 神 诫命、 为耶稣 作 见证的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 18, ' 那时龙就站 在海 边的沙 上。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, '我又 看见 一个兽 从 海 中上来,有 十 角 七 头, 在 十角 上 戴著十个 冠冕, 七头 上 有亵渎的 名号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, ' 我所 看见 的兽, 形状像 豹, 脚 像 熊的脚, 口 像 狮子 的口。 那龙 将自己的 能力、 座位,和 大 权柄 都给了 牠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, ' 我看见 兽的 七头中,有一个 似乎 受了 死 伤, 那 死 伤 却医好了。 全 地 的人都希奇 跟从 那兽, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, '又 拜 那龙─因为 牠将自己的权柄 给了 兽,也 拜 兽,说:「谁 能比 这兽, 谁 能 与 牠 交战 呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, '又 赐给 牠 说 夸大 亵渎 话的口,又有 权柄 赐给 牠,可以任意而行 四十 二 个月。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, ' 兽就开  口 向 神 说 亵渎的话,亵渎 神 的名 并 他的 帐幕,以及那些住 在天 上的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, '又 任凭 牠 与 圣徒 争战 ,并且 得胜;也把 权柄 赐给 牠,制伏 各 族、 各民、 各方、 各国。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, ' 凡 住 在地 上、 名字 从 创 世 以来没有 记 在被杀之 羔羊 生命 册 上的人,都要拜 牠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, '凡 有 耳的,就应当听! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, ' 掳掠人的,必被 掳掠; 用 刀 杀人的, 必被 刀 杀。圣徒 的忍耐 和 信心 就是 在此。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, '我又 看见 另有一个 兽 从 地 中上来,有 两 角 如同 羊羔, 说话 好像 龙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, ' 牠在头一个兽 面前,施行 头一个 兽 所有的 权柄,并且 叫 地 和 住 在地 上 的人 拜 那 死 伤 医好 的头一个 兽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, '又 行 大 奇事,甚至 在人 面前,叫 火 从 天 降 在地 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, '牠因 赐给牠 权柄 在兽 面前 能行 奇事,就 迷惑 住 在地 上的人,说:「要给那 受 刀 伤 还活著的 兽 作 个像。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, '又有 权柄 赐给牠,叫兽 像 有 生气, 并且 能说话,又 叫 所有 不 拜 兽 像 的人 都被杀害。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, '牠又 叫 众人,无论大 小、 贫 富、 自主的、 为奴的, 都在 右 手 上 或是 在 额 上 受 一个印记。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, ' 除了 那受 印记、 有了兽 名 或 有兽 名 数目的,都不得 做买  卖。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, '在这里 有 智慧:凡有 聪明的,可以算计 兽 的数目;因为 这是 人的 数目, 它的 数目 是六百 六十 六。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, '我又 观看, 见 羔羊 站 在 锡安 山,同 他 又有 十四万四千人,都有 他的 名 和 他 父 的名 写 在 额 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, ' 我听见 从 天上 有声音,像 众 水 的声音 和 大 雷 的声音,并且 我所 听见 的好像 弹琴的 所弹 的 琴 声。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, ' 他们在宝座 前,并 在四 活物 和 众长老 前 唱歌,仿佛是 新 歌; 除了 从 地上 买 来 的那 十四万四千人以外,没有人 能 学 这歌。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, '这些人 未曾 沾染 妇女,他们原 是 童身。羔羊 无论往哪里 去,他们 都跟随他。他们 是从 人间 买 来的,作初熟的果子归与 神 和 羔羊。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, ' 在他们 口 中 察不 出 谎言来;他们是 没有瑕疵的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, '我又 看见 另有一位 天使 飞 在 空中,有 永远的 福音 要传给 住 在 地 上的人, 就是 各 国、 各族、 各方、 各民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, '他 大 声 说:「应当敬畏 神, 将荣耀 归给 他!因 他 施行审判 的时候 已经到了。 应当敬拜 那创造 天 地 海 和 众水 泉源的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, '又 有 第二位 天使 接著 说:「叫万 民 喝 邪淫、大怒 之酒 的巴比伦 大 城倾倒了!倾倒了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, '又有 第三位 天使 接著 他们, 大 声 说:「若 有人 拜 兽 和 兽 像, 在 额 上 或 在 手 上 受了 印记, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, '这人 也 必喝 神 大怒 的酒;此酒 斟在 神 忿怒的 杯 中 纯一不杂。 他要在圣 天使 和 羔羊 面前,在火 与 硫磺 之中 受痛苦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, ' 他 受痛苦 的烟 往上冒,直到 永永远远。 那些 拜 兽 和 兽 像, 受 牠 名 之印记 的,昼 夜 不 得 安宁。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, '圣徒 的忍耐 就在 此;他们是守 神 诫命 和 耶稣 真道的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, ' 我听见 从 天上 有声音 说:「你要写下:从今以后, 在主 里面 而死 的人有福了!」圣灵 说:「是的, 他们息了 自己的 劳苦, 做工的果效 也随著 他们。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, '我又 观看, 见 有一片白 云, 云 上 坐著 一位好像 人 子, 头 上 戴著 金 冠冕, 手 里 拿著快 镰刀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, '又有 一位 天使 从 殿 中出来,向那坐 在云 上 的 大 声 喊著说:「伸出 你的 镰刀 来 收割;因为 收割 的时候 已经到了, 地上 的庄稼 已经熟透了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, ' 那坐 在云 上的,就把 镰刀 扔 在地 上,地 上的庄稼就 被收割了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, '又有 一位 天使 从 天 上 的殿 中出来,他 也 拿著 快 镰刀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, '又有 一位 天使 从 祭坛 中出来,是有 权柄 管 火的, 向拿著 快 镰刀 的大 声 喊著 说:「伸出 快 镰刀来, 收取 地上 葡萄树 的果子,因为 葡萄 熟透了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, '那天使 就 把 镰刀 扔 在地 上, 收取了 地上 的葡萄, 丢在 神 忿怒的 大 酒醡 中。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, ' 那酒醡 踹 在城 外,就 有血 从 酒醡 里流出来,高到 马 的嚼环,远 有六百 里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, '我又 看见 在天 上 有 异象,大 而且 奇,就是七位 天使 掌管 末了的 七 灾,因为 神 的大怒 在这 七灾中 发尽了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, ' 我看见 仿佛有 玻璃 海,其中有火 搀杂。又 看见那些胜了 兽 和 兽的 像 并 牠 名字 数目的人,都站 在玻璃 海 上,拿著 神 的琴, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, ' 唱 神 仆人 摩西 的歌 和 羔羊 的歌,说:主 神─全能者啊,你的 作为 大哉! 奇哉!万世(或译:国)之王啊,你的 道途 义哉! 诚哉! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, '主啊,谁 敢不 敬畏你, 不将荣耀 归与你的 名呢?因为 独有 你是圣的。 万 民 都要来 在你 面前 敬拜,因 你 公义的作为 已经显出来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, ' 此 后,我看见 在天 上 那存法柜 的 殿 开 了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, ' 那掌管 七 灾 的七位 天使 从 殿 中出来,穿著 洁 白 光明的细麻衣(细麻衣:有古卷是宝石), 胸间 束著 金 带。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, ' 四 活物 中 有一个 把盛满了 活 到 永永远远之 神 大怒 的七个 金 碗 给了 那七位 天使。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, ' 因 神 的荣耀 和 能力,殿 中充满了 烟。于 是 没有人 能以 进 殿,直等到 那七位 天使 所降的七 灾 完毕了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, ' 我听见 有大 声音 从 殿中出来,向那七位 天使 说:「你们去,把盛 神 大怒 的七 碗 倒 在地 上。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, '第一位 天使便 去, 把 碗 倒 在地 上,就 有 恶 而且 毒 的疮 生在那些 有 兽 印记、 拜 兽 像 的人 身上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, ' 第二位 天使把 碗 倒 在海 里, 海就变成血,好像 死 人的血, 海 中 的活 物 都 死了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, ' 第三位 天使把 碗 倒 在 江河 与 众水 的泉源里, 水就变成 血了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, ' 我听见 掌管众水 的天使 说: 昔在、 今在 的圣者啊, 你这样 判断 是 公义的; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, ' 他们曾流 圣徒 与 先知 的血, 现在你给 他们 血 喝;这是 他们所该受的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, '我又 听见 祭坛 中有声音说:是的,主 神─全能者啊,你的 判断 义哉! 诚哉! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, ' 第四位 天使把 碗 倒 在日头 上, 叫 日头 能用 火 烤 人。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, ' 人 被大 热 所烤,就 亵渎 那 有 权 掌管 这些 灾的 神 之名,并 不 悔改 将荣耀 归给 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, ' 第五位 天使把 碗 倒 在兽 的座位 上,兽的 国 就 黑暗了。人因 疼痛 就 咬 自己的 舌头; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, '又 因 所受的疼痛,和 生的疮,就亵渎 天上的 神,并 不 悔改 所行的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, ' 第六位 天使把 碗 倒 在幼发拉底 大 河 上, 河水 就干了,要给 那从 日出之地 所来的众王 预备 道路。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, '我又 看见 三个 污秽的 灵,好像 青蛙,从 龙 口、 兽 口 并 假先知 的口中出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, ' 他们本是 鬼魔 的灵,施行 奇事,出去 到 普 天下 众王那里,叫他们在 神 全能者 的大 日 聚集 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, '(看哪,我来 像贼 一样。那警醒、 看守 衣服、免得 赤身 而行、叫 人见 他 羞耻 的有福了!) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, ' 那三个鬼魔便叫众王 聚集 在 一处,希伯来话 叫作 哈米吉多顿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, ' 第七位 天使把 碗 倒 在 空中,就有 大 声音 从 殿 中的宝座 上 出来,说:「成了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, '又 有 闪电、 声音、 雷轰、 大 地震,自从 地 上 有 人以来,没 有 这样 大、这样厉害 的地震。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, ' 那大 城 裂 为 三 段,列国 的城 也 都倒塌了; 神 也 想起 巴比伦 大城来,要把那盛自己 烈怒 的酒 杯 递给 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, ' 各 海岛 都逃避了,众山 也 不 见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, '又有 大 雹子 从 天 落 在人 身上,每一个约 重一他连得(一他连得约有九十斤)。为 这 雹子 的灾 极 大,人 就 亵渎 神。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, ' 拿著 七 碗 的七位 天使 中,有一位 前来 对我 说:「你到这里来,我将坐 在众 水 上 的大 淫妇 所要受的刑罚 指给 你看。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, '地上的 君王 与 她 行淫, 住 在地上 的人喝醉了 她 淫乱 的酒。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, ' 我被 圣灵感动,天使带 我 到旷野 去,我就 看见 一个女人 骑 在朱红色的 兽 上;那兽有 七 头 十 角,遍体有 亵渎 的名号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, ' 那女人 穿著 紫色 和 朱红色的衣服, 用金子、 宝 石、 珍珠 为妆饰; 手 拿 金 杯,杯中 盛满了 可憎之物,就是 她 淫乱的 污秽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, ' 在她 额 上 有名 写著说:「奥秘哉!大 巴比伦,作世上 的淫妇 和 一切可憎之物 的母。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, '我又 看见 那女人 喝醉了 圣徒 的血 和 为耶稣 作见证之人 的血。 我看见 她,就大大地 希奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, ' 天使 对我 说:「你为 什么 希奇呢?我 要将这女人 和 驮著 她 的那 七 头 十 角 兽 的奥秘 告诉 你。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, '你所看见 的 兽,先前有, 如今没 有, 将要 从 无底坑 里上来,又 要归 于  沉沦。 凡住 在地 上、 名字 从 创世 以来没有 记 在生命 册 上的,见 先前有、 如今没 有、 以后再有 的兽,就必希奇。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, ' 智慧 的心 在此可以思想。那七 头 就是 女人 所坐 的 七座 山, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, '又是 七位 王;五位 已经倾倒了, 一位 还在,一位 还没有 来到; 他来 的时候, 必须 暂时 存留。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, ' 那 先前有 如今没 有 的兽, 就是 第八位;他也 和 那七位 同列,并且 归 于  沉沦。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, ' 你所看见 的那 十 角 就是 十 王;他们 还没有 得 国,但 他们一 时 之间要和兽 同 得 权柄,与王 一样。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, '他们 同心合意 将自己的 能力、 权柄 给 那兽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, '他们 与 羔羊 争战 , 羔羊 必胜过 他们,因为 羔羊是 万主 之主、 万王 之王。 同著 羔羊的,就是蒙召、 被选、 有忠心的,也必得胜。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, '天使又 对我 说:「你所 看见 那 淫妇 坐 的众水,就是 多民、 多人、 多国、 多方。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, ' 你所看见 的那 十 角 与 兽 必恨 这淫妇, 使 她 冷落 赤身,又要 吃 她的 肉, 用 火 将她 烧尽。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, '因为 神 使 诸王 同心合意, 遵行 他的 旨意, 把自己的 国 给 那兽,直等到 神 的话 都应验了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, ' 你所看见 的那 女人 就是 管辖 地上 众王 的大 城。」   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, '此 后,我看见 另有一位 有 大 权柄 的天使 从 天 降下, 地 就因 他的 荣耀 发光。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, ' 他 大 声 喊著 说:巴比伦 大 城倾倒了!倾倒了! 成了 鬼魔 的住处 和 各样 污秽 之灵 的巢穴(或译:牢狱;下同),并 各样 污秽 可憎 之雀鸟 的巢穴。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, '因为 列 国 都被 她 邪淫 大怒 的酒 倾倒了。 地上的 君王 与 她 行淫; 地上的 客商 因 她 奢华 太过 就发了财。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, '我又 听见 从 天上 有 声音 说:我的 民哪,你们要从 那城 出来,免得 与她 一同有 罪, 受 她 所受的灾殃; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, '因 她的 罪恶 滔天; 她的 不义, 神 已经想起来了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, ' 她 怎样 待人,也要怎样待 她, 按 她 所行的 加倍地报应她;用 她调酒 的杯 加倍地 调 给她喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, '她怎样 荣耀 自己, 怎样奢华,也当叫 她 照样 痛苦 悲哀,因 她 心 里 说: 我坐了 皇后的位,并 不 是 寡妇, 决不 至于  悲哀。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, '所以 在一 天 之内,她的 灾殃 要一齐来到,就是死亡、 悲哀、 饥荒。她又 要被 火 烧尽了,因为 审判 她 的主 神 大有能力。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, ' 地上 的君王, 素来与 她 行淫、 一同奢华的, 看见 烧 她 的烟,就必为 她 哭泣 哀号。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, '因 怕 她的 痛苦,就 远远地 站著 说:哀哉!哀哉!巴比伦 大 城,坚固的 城啊, 一 时 之间你的 刑罚 就来到了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, ' 地上的 客商 也都为 她 哭泣 悲哀,因为 没有人 再 买  他们的 货物了; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, '这货物 就是金、 银、 宝 石、 珍珠、 细麻布、 紫色料、 绸子、 朱红色料、 各样 香 木、 各样 象牙的 器皿、 各样 极宝贵的 木头,和 铜、 铁、 汉白玉的 器皿, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, '并 肉桂、 荳蔻、 香料、 香膏、 乳香、 酒、 油、 细面 麺、 麦子、 牛、 羊、 车、 马,和 奴仆、 人口。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, '巴比伦哪,你 所贪爱的 果子 离开 了 你; 你一切的 珍馐美味 和 华美的物件 也从 你 中间毁灭, 决不能 再 见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, '贩卖这些 货物、藉 借著 她 发了财的客商,因 怕 她的 痛苦,就 远远地 站著 哭泣 悲哀,说: ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, '哀哉!哀哉!这大 城啊,素常穿著 细麻、 紫色、 朱红色的衣服,又 用 金子、 宝 石,和 珍珠 为妆饰。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, ' 一 时之间,这么大的 富厚 就归于 无有了。 凡 船主 和 坐船往各处去的,并 众水手,连 所有 靠海 为业的,都 远远地 站著, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, '看见 烧 她 的烟,就 喊著 说:「有何 城能比 这大 城呢?」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, '他们 又 把尘土 撒 在头 上,哭泣 悲哀, 喊著 说:哀哉!哀哉!这大 城啊。凡 有 船 在海 中的,都因 她的 珍宝 成了富足! 她在一 时 之间就成了荒场! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, '天哪, 众圣徒、 众使徒、 众先知啊,你们都要因 她 欢喜,因为 神 已经在她 身上 伸了你们的 冤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, ' 有一位 大力的 天使 举起 一块石头,好像 大 磨石, 扔 在海 里,说:巴比伦 大 城 也必这样 猛力地 被扔下去, 决不能 再 见了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, ' 弹琴、 作乐、 吹笛、 吹号 的声音,在你 中间 决不能 再 听见; 各行 手艺人 在你 中间 决不能 再 遇见; 推磨 的声音 在你 中间 决不能 再 听见; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, ' 灯 光 在你 中间 决不能 再 照耀; 新郎 和 新妇 的声音,在你 中间 决不能 再 听见。 你的 客商 原来是 地上 的尊贵人; 万 国 也被 你的 邪术 迷惑了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, '先知 和 圣徒,并 地 上 一切 被杀之人 的血, 都在这城 里 看见了。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, '此 后,我听见 好像 群众 在天 上 大 声 说:哈利路亚(就是要赞美耶和华的意思)!救恩、 荣耀、 权能 都属乎我们的 神! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, ' 他的 判断 是真实 公义的;因 他判断了 那 用 淫行 败坏 世界 的大 淫妇,并且 向 淫妇 讨流 仆人 血的罪,给他们伸冤。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, ' 又 说:哈利路亚! 烧淫妇 的烟 往上冒,直到 永永远远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, ' 那二十 四 位长老 与 四 活物 就俯伏 敬拜 坐 宝座的 神,说:阿们!哈利路亚! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, ' 有声音 从 宝座 出来 说: 神的 众 仆人哪, 凡敬畏 他的,无论大 小,都要赞美 我们的 神! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, ' 我听见 好像 群众 的声音, 众 水 的声音, 大 雷 的声音,说:哈利路亚!因为 主─我们的 神、全能者 作王了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, '我们要欢喜 快乐, 将荣耀 归给 他。因为,羔羊 婚娶 的时候到了; 新妇 也自己 预备好了, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, '就 蒙恩得 穿 光明 洁白 的细麻衣。( 这细麻衣 就是 圣徒 所行的义。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, ' 天使吩咐我 说:「你要写上:凡被请 赴 羔羊 之婚 筵 的有福了!」又 对我 说:「这 是 神 真实的 话。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, ' 我就俯伏 在他 脚 前 要拜 他。 他说:「千万不 可!我和你,并 你 那些为耶稣 作 见证 的弟兄 同是 作仆人的,你要敬拜 神。」因为 预言中 的灵意 乃是 为耶稣 作见证。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, ' 我观看,见 天 开 了。 有一匹白 马, 骑 在马 上 的称为 诚信 真实,他审判, 争战 , 都按著 公义。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, ' 他的 眼睛 如 火 焰, 他 头 上 戴著许多 冠冕;又有 写著的 名字, 除了 他自己 没有人 知道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, ' 他穿著 溅了 血 的衣服; 他的 名 称为 神 之道。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, ' 在 天上 的众军 骑著 白 马,穿著 细麻衣,又白 又洁,跟随 他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, ' 有利 剑 从 他 口中 出来, 可以击杀 列国。 他 必用 铁 杖 辖管(辖管:原文是牧)他们,并 要踹 全能 神 烈怒 的酒醡。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, ' 在他衣服 和 大腿 上 有 名 写著说:「万王 之王, 万主 之主。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, '我又 看见 一位 天使 站 在日头 中, 向 天空 所 飞 的鸟 大 声 喊著 说:「你们聚集 来赴 神 的大 筵席, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, '可以 吃 君王 与 将军 的肉, 壮士 与 马 和 骑 马 者的肉,并 一切 自主的 为奴的,以及 大 小 人民的肉。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, ' 我看见 那兽 和 地上 的君王,并 他们的 众军 都聚集,要与 骑 白马 的并 他的 军兵 争战 。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, ' 那兽 被擒拿; 那在兽 面前 曾行 奇事、 迷惑 受 兽 印记 和 拜 兽 像 之人的假先知,也与 兽同被擒拿。他们两个 就活活地 被扔 在烧著 硫磺 的火 湖 里; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, ' 其余 馀的 被 骑 白马 者 口中 出来 的 剑 杀了; 飞鸟 都 吃饱了 他们的 肉。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, '我又 看见 一位天使 从 天 降下, 手 里 拿著 无底坑 的钥匙 和 一条大 链子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, ' 他捉住 那龙,就是古 蛇, 又叫 魔鬼,也 叫撒但, 把牠 捆绑 一千 年, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, ' 扔 在无底坑 里, 将无底坑关闭, 用印 封上,使牠不得 再 迷惑 列国。等到 那一千 年 完了,以后 必须 暂时 释放 牠。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, '我又 看见 几个宝座,也有 坐 在 上面的,并有 审判 的权柄赐给 他们。我又 看见那些因为 给耶稣 作见证,并 为 神 之道 被斩者 的灵魂,和 那 没有 拜过 兽 与 兽 像,也 没有 在额 上 和 手 上 受过 他印记之人的灵魂, 他们都复活了,与 基督 一同 作王 一千 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, '这是 头一次的 复活。(其余 馀的 死人 还没有 复活,直等 那一千 年 完了。) ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, '在 头一次 复活 有 分 的有福了, 圣洁了!第二次 的死 在他们 身上 没 有 权柄。 他们必作 神 和 基督 的祭司,并要 与基督 一同 作王 一千 年。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, ' 那 一千 年 完了,撒但 必从 监牢 里被释放, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, ' 出来 要迷惑 地上 四方(原文是角)的列国,就是歌革 和 玛各,叫他们 聚集 争战 。 他们的 人数 多如 海 沙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, ' 他们上来 遍满了 全地, 围住 圣徒 的营 与 蒙爱的 城,就 有火 从 天 降下, 烧灭了 他们。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, ' 那迷惑 他们 的魔鬼 被扔 在硫磺 的 火 湖 里, 就是兽 和 假先知 所在的地方。 他们必昼 夜 受痛苦,直到 永永远远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, '我又 看见 一个白色 的大 宝座 与 坐 在 上面的;从 他 面前 天 地 都逃避, 再 无 可见 之处了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, '我又 看见 死了的人,无论大 小,都站 在宝座 前。 案卷 展开 了,并且 另有一 卷 展开 , 就是 生命册。 死了的人 都凭著 这些案卷 所记载的,照 他们 所行的 受审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, '于 是 海 交出 其 中 的死人;死亡 和 阴间 也 交出 其 中 的死人; 他们 都照 各人 所行的 受审判。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, ' 死亡 和 阴间 也被扔 在火 湖 里;这 火 湖 就是 第二次 的死。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, ' 若 有人 名字没 记 在生命 册 上,他就被扔 在火 湖 里。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, '我又 看见 一个新 天 新 地;因为 先前的 天 地 已经过去了,海 也 不 再 有了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, '我又 看见 圣 城 新 耶路撒冷 由 神 那里从 天 而降,预备好了,就如 新妇 妆饰整齐,等候 丈夫。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, ' 我听见 有大 声音 从 宝座 出来说:「看哪, 神 的帐幕 在人 间。 他要与 人 同住, 他们 要作 他的 子民。 神 要 亲自 与他们 同在,作他们的 神。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, ' 神要 擦去 他们一切的 眼泪; 不 再 有 死亡,也不再有 悲哀、 哭号、 疼痛,因为 以前的事 都过去了。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, ' 坐 宝座 的说:「看哪,我将一切 都更 新了!」又 说:「你要写上;因 这些 话 是 可信的, 是真实的。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, '他又 对我 说:「都成了!我 是 阿拉法, 我是俄梅戛;我是初, 我是终。我 要将 生命 泉 的水 白白 赐给 那口渴的人喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, '得胜的,必承受这些 为业: 我要作 他的 神, 他 要作 我的 儿子。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, '惟有 胆怯的、 不信的、 可憎的、 杀人的、 淫乱的、 行邪术的、 拜偶像的,和 一切 说谎话的,他们的 分 就在 烧著 硫磺 的 火 湖 里; 这是 第二次 的死。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, ' 拿著 七个 金碗、盛满 末后 七 灾 的 七位 天使中,有一位 来 对 我 说:「你到这里来,我要将新妇,就是羔羊的 妻,指 给你看。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, ' 我被 圣灵感动,天使就带 我 到 一座高 大的 山, 将那由 神那里、从 天 而降 的圣 城 耶路撒冷 指示 我。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, '城中有 神 的荣耀;城的 光辉 如同 极贵的宝 石,好像 碧玉,明如水晶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, '有 高 大 的墙,有 十二个 门, 门 上 有十二位 天使,门 上又 写著 以色列 十二个 支派 的名字。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, ' 东边 有三 门, 北边 有三 门, 南边 有三 门, 西边 有三 门。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, ' 城 墙 有 十二 根基, 根基 上 有羔羊 十二 使徒 的 名字。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, ' 对 我 说话的,拿著 金 苇子当尺,要 量 那城 和 城 门 城 墙。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, ' 城 是 四方的, 长 宽 一样。 天使用苇子 量 那城,共有四千里, 长、 宽、 高 都是 一样; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, '又 量了 城 墙,按著人 的尺寸, 就是 天使的尺寸,共有一百 四十 四 肘。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, ' 墙 是碧玉 造的; 城 是精 金的,如同 明净的 玻璃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, '城 墙 的根基 是用各样 宝 石 修饰的:第一 根基 是碧玉;第二 是蓝宝石;第三 是绿玛瑙;第四 是绿宝石; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, '第五 是红玛瑙;第六 是红宝石;第七 是黄璧玺;第八 是水苍玉;第九 是红璧玺;第十 是翡翠;第十一 是紫玛瑙;第十二 是紫晶。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, ' 十二个 门 是十二颗 珍珠,每 门 是 一颗 珍珠。 城 内的街道 是精 金,好像 明透的 玻璃。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, ' 我未 见 城 内 有殿,因 主 神─全能者 和 羔羊 为 城 的殿。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, '那城 内又 不 用 日 月 光照;因有 神 的荣耀 光照,又有 羔羊 为城 的灯。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, ' 列国 要在 城 的光 里行走; 地上 的君王 必将自己的 荣耀 归 与 那城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, ' 城 门 白昼 总不 关闭,在那里 原 没 有 黑夜。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, ' 人必将列国 的荣耀、 尊贵 归 与 那城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, ' 凡 不洁净的,并 那行 可憎 与 虚谎之事的,总不得 进 那城;只有 名字写 在羔羊 生命 册 上的才得进去。   ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, '天使又 指示 我 在城内街道当中一道生命 水 的河,明亮 如 水晶,从 神 和 羔羊 的宝座 流出来。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, ' 在河 这边与那边 有生命 树,结 十二样(或译:回)果子,每 月 都结 果子; 树 上的叶子 乃为 医治 万民。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, ' 以后再 没 有 咒诅; 在城 里 有 神 和 羔羊 的宝座; 他的 仆人 都要事奉 他, ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, '也要 见 他的 面。 他的 名字 必写在他们的 额 上。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, ' 不再 有 黑夜;他们也 不 用 灯光、 日 光,因为 主 神 要光照 他们。 他们要作王,直到 永永远远。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, '天使又 对我 说:「这些 话 是真实 可信的。 主 就是众先知 被感之灵的 神,差遣 他的 使者,将那 必要 快 成 的事指示 他 仆人。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, '「看哪,我必快 来!凡遵守 这 书 上预言 的有福了!」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, ' 这些事 是我-约翰 所听见、 所看见的;我既 听见、 看见了,就在 指示 我 的天使 脚 前 俯伏 要拜他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, ' 他对我 说:「千万不可!我与你 和 你的 弟兄 众先知,并 那些守 这 书 上言语的人,同是 作仆人的。你要敬拜 神。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, '他又 对我 说:「不可 封了 这 书 上的预言,因为 日期 近了。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, '不义的,叫他仍旧 不义; 污秽的,叫他仍旧 污秽; 为义的,叫他仍旧 为义; 圣洁的,叫他仍旧 圣洁。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, '「看哪,我必快 来! 赏罚 在 我,要照 各人 所行的 报应他。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, '我 是阿拉法, 我是俄梅戛;我是首先的, 我是末后的;我是初, 我是终。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, '那些洗净 自己 衣服 的有福了! 可得 权柄 能到 生命 树那里,也 能从门 进 城。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, '城外 有那些犬类、 行邪术的、 淫乱的、 杀人的、 拜偶像的,并 一切 喜好说谎言、 编造 虚谎的。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, '「我─耶稣 差遣 我的 使者 为 众教会 将这些事 向你们 证明。我 是 大卫 的根,又是 他的后裔。我是明亮的 晨 星。」 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, ' 圣灵 和 新妇 都说:「来!」听见的人 也 该说:「来!」口渴的人 也 当来;愿 意的,都可以白白 取 生命 的水喝。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, '我 向一切听见 这 书 上预言 的 作见证,若有 人 在这 预言上 加添什么, 神 必将写 在这 书 上 的灾祸 加 在他 身上; ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, ' 这 书 上的预言,若有 人 删去什么, 神 必从 这书 上 所写 的 生命 树 和 圣 城 删去 他的 分。 ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, '证明 这事 的说:「是了,我必快 来!」阿们!主 耶稣啊,我愿 你来! ');
INSERT INTO `ChiUns_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, '愿 主 耶稣 的恩惠 常与众圣徒 同在。阿们!    ');
